From BusyCoq Require Individual62.
From Coq Require Arith Bool Lia List NArith Program.Equality String.
Import Individual62 String Lia NArith Bool Arith Program.Equality List.
Import ListNotations.
Import Individual62.Enumerate.Permute.
Import Individual62.Enumerate.Permute.Flip.
Open Scope string_scope.
Definition tm := Eval compute in
  (TM_from_str "1RB1RF_1RC1RB_1LD0RA_1LA1LE_---0LF_0LC1LF").
Definition smap (q : Q) : Q :=
  match q with B => A | C => B | D => C | A => D | E => E | F => F end.
Definition smap_inv (q : Q) : Q :=
  match q with A => B | B => C | C => D | D => A | E => E | F => F end.
Definition remap_tm (m : TM) : TM :=
  fun qs =>
    match qs with
    | (q, s) =>
        match m (smap q, s) with
        | Some (s', d, q') => Some (s', d, smap_inv q')
        | None => None
        end
    end.
Definition tmB : TM := Eval compute in remap_tm (flip tm).
Open Scope sym.
Open Scope list.
Notation "c --> c'" := (c -[ tmB ]-> c') (at level 40).
Notation "c -->* c'" := (c -[ tmB ]->* c') (at level 40).
Notation "c -->+ c'" := (c -[ tmB ]->+ c') (at level 40).
Notation "c =( n )=> c'" := (c -[ tmB ]->> n / c') (at level 40, n at next level).
Lemma cmul_refl' n (c c' : Q * tape) :
  n = O -> c = c' -> c =( n )=> c'.
Proof. intros -> ->. apply multistep_0. Qed.
Ltac cstep := eapply multistep_S; [prove_step|].
Ltac cfinish := apply cmul_refl'; [reflexivity | simpl_tape; reflexivity].
Ltac cexec := repeat cstep; cfinish.
Lemma cmul_trans_eq {n m : nat} (k : nat) c c' c'' :
  c =( n )=> c' -> c' =( m )=> c'' -> k = (n + m)%nat -> c =( k )=> c''.
Proof. intros H1 H2 ->. eapply multistep_trans; eauto. Qed.
Lemma cscan_C_left n l r :
  l <* [1]^^n <{{C}} r =( n )=> l <{{C}} [1]^^n *> r.
Proof.
  gen l r.
  induction n as [|n IH]; intros l r.
  - cfinish.
  - cbn [lpow]. simpl_tape.
    cstep.
    eapply cmul_trans_eq.
    + apply IH.
    + apply cmul_refl'; [reflexivity|].
      rewrite lpow_shift1. reflexivity.
    + lia.
Qed.
Lemma cscan_F_right n l r :
  l {{F}}> [1]^^n *> r =( n )=> l <* [1]^^n {{F}}> r.
Proof.
  gen l r.
  induction n as [|n IH]; intros l r.
  - cfinish.
  - cbn [lpow]. simpl_tape.
    cstep.
    eapply cmul_trans_eq.
    + apply IH.
    + apply cmul_refl'; [reflexivity|].
      rewrite lpow_shift1. reflexivity.
    + lia.
Qed.
Lemma csection_D0_00 n l r :
  l <* [0] <* [1]^^n <* [0] <{{D}} [0;0] *> r =( n + 6 )=>
  l <{{D}} [1]^^(n+4) *> r.
Proof.
  replace (n + 6)%nat with (S (S (S (S (S (n + 1)))))) by lia.
  do 5 cstep.
  eapply cmul_trans_eq.
  - apply cscan_C_left.
  - cstep.
    apply cmul_refl'; [reflexivity|].
    simpl_tape.
    rewrite <- lpow_shift1.
    replace (n+4) with (S (S (S (S n)))) by lia.
    cbn [lpow]. simpl_tape. reflexivity.
  - lia.
Qed.
Lemma csection_D0_01 n l r :
  l <* [0] <{{D}} [0;1] *> [1]^^n *> [0] *> r =( n + 6 )=>
  l <* [1]^^(n+3) <* [0] {{D}}> r.
Proof.
  replace (n + 6)%nat with (S (S (S (S (S (n + 1)))))) by lia.
  do 5 cstep.
  eapply cmul_trans_eq.
  - apply cscan_F_right.
  - cstep.
    apply cmul_refl'; [reflexivity|].
    simpl_tape.
    replace (n+3) with (S (S (S n))) by lia.
    cbn [lpow]. simpl_tape. reflexivity.
  - lia.
Qed.
Lemma csection_D0_11 n l r :
  l <* [0] <{{D}} [1;1] *> [1]^^n *> [0] *> r =( n + 4 )=>
  l <* [0;1;1] <* [1]^^n <* [0] {{D}}> r.
Proof.
  replace (n + 4)%nat with (S (S (S (n + 1)))) by lia.
  do 3 cstep.
  eapply cmul_trans_eq.
  - apply cscan_F_right.
  - cstep.
    apply cmul_refl'; [reflexivity|].
    simpl_tape. reflexivity.
  - lia.
Qed.
Lemma csection_D1_0 n l r :
  l <* [0] <* [1]^^n <* [1;0] <{{D}} r =( n + 3 )=>
  l <{{D}} [1]^^(n+2) *> [0] *> r.
Proof.
  replace (n + 3)%nat with (S (S (n + 1))) by lia.
  do 2 cstep.
  eapply cmul_trans_eq.
  - apply cscan_C_left.
  - cstep.
    apply cmul_refl'; [reflexivity|].
    simpl_tape.
    rewrite <- lpow_shift1.
    replace (n+2) with (S (S n)) by lia.
    cbn [lpow]. simpl_tape. reflexivity.
  - lia.
Qed.
Lemma csection_D1_1_left l r :
  l <* [1;1;0] <{{D}} r =( 3 )=> l <* [1;0] <{{D}} [0] *> r.
Proof. cexec. Qed.
Lemma csection_D1_1_right l r :
  l <* [1;1;1] <{{D}} r =( 5 )=> l <* [0;1;1] {{D}}> r.
Proof. cexec. Qed.
Definition cB0 : Q * tape := B;; tape0.
Lemma cB_bridge :
  cB0 =( 2 )=> const 0 <{{D}} [1;1] *> const 0.
Proof.
  unfold cB0, tape0.
  do 2 cstep.
  apply cmul_refl'; [reflexivity|].
  simpl_tape. reflexivity.
Qed.
Definition sym_eqb (a b : Sym) : bool :=
  match a, b with
  | S0, S0 | S1, S1 => true
  | _, _ => false
  end.
Lemma sym_eqb_spec a b : sym_eqb a b = true <-> a = b.
Proof. destruct a, b; cbn; intuition congruence. Qed.
Definition run : Type := (Sym * nat)%type.
Definition wside : Type := list run.
Fixpoint wdec (w : wside) : Stream Sym :=
  match w with
  | [] => const 0
  | (b, n) :: t => [b]^^n *> wdec t
  end.
Definition wconf (l : wside) (cur : Sym) (r : wside) : Q * tape :=
  (cur >> wdec l) <{{D}} wdec r.
Fixpoint wpop (w : wside) : Sym * wside :=
  match w with
  | [] => (0, [])
  | (b, n) :: t =>
    match n with
    | O => wpop t
    | S O => (b, t)
    | S n' => (b, (b, n') :: t)
    end
  end.
Fixpoint wpop1s (w : wside) : nat * wside :=
  match w with
  | (b, n) :: t =>
    match b with
    | S1 => let (m, t') := wpop1s t in ((n + m)%nat, t')
    | S0 => match n with O => wpop1s t | _ => (O, w) end
    end
  | [] => (O, [])
  end.
Definition wpush (b : Sym) (n : nat) (w : wside) : wside :=
  match n with
  | O => w
  | _ =>
    match w with
    | (b', n') :: t =>
      if sym_eqb b b' then (b, (n + n')%nat) :: t else (b, n) :: w
    | [] => [(b, n)]
    end
  end.
Definition wsection (l : wside) (cur : Sym) (r : wside)
  : option (wside * Sym * wside * nat) :=
  match cur with
  | S0 =>
    let (b0, r0) := wpop r in
    let (b1, r1) := wpop r0 in
    match b0, b1 with
    | S0, S0 =>
      let (n, la) := wpop1s l in
      let (_, lb) := wpop la in
      let (c2, lc) := wpop lb in
      Some (lc, c2, wpush 1 (n + 4) r1, (n + 6)%nat)
    | S0, S1 =>
      let (m, ra) := wpop1s r1 in
      let (_, rb) := wpop ra in
      let (c2, rc) := wpop rb in
      Some (wpush 0 1 (wpush 1 (m + 3) l), c2, rc, (m + 6)%nat)
    | S1, S0 =>
      None
    | S1, S1 =>
      let (m, ra) := wpop1s r1 in
      let (_, rb) := wpop ra in
      let (c2, rc) := wpop rb in
      Some (wpush 0 1 (wpush 1 m (wpush 0 1 (wpush 1 2 l))), c2, rc,
            (m + 4)%nat)
    end
  | S1 =>
    let (l0, la) := wpop l in
    match l0 with
    | S0 =>
      let (m, lb) := wpop1s la in
      let (_, lc) := wpop lb in
      let (c2, ld) := wpop lc in
      Some (ld, c2, wpush 1 (m + 2) (wpush 0 1 r), (m + 3)%nat)
    | S1 =>
      let (l1, lb) := wpop la in
      match l1 with
      | S0 =>
        Some (wpush 0 1 lb, 1, wpush 0 1 r, 3%nat)
      | S1 =>
        let (c2, rc) := wpop r in
        Some (wpush 0 1 l, c2, rc, 5%nat)
      end
    end
  end.
Lemma wpop_dec (w : wside) :
  wdec w = fst (wpop w) >> wdec (snd (wpop w)).
Proof.
  induction w as [|[b n] t IH].
  - cbn. apply const_unfold.
  - destruct n as [|[|n']].
    + cbn. exact IH.
    + cbn. reflexivity.
    + cbn. reflexivity.
Qed.
Lemma wpush_dec (b : Sym) (n : nat) (w : wside) :
  wdec (wpush b n w) = [b]^^n *> wdec w.
Proof.
  destruct n as [|n]; [reflexivity|].
  destruct w as [|[b' n'] t].
  - reflexivity.
  - cbn [wpush].
    destruct (sym_eqb b b') eqn:Eb.
    + apply sym_eqb_spec in Eb. subst b'.
      cbn [wdec]. rewrite lpow_add, Str_app_assoc. reflexivity.
    + reflexivity.
Qed.
Lemma wpop1s_dec (w : wside) :
  wdec w = [1]^^(fst (wpop1s w)) *> wdec (snd (wpop1s w)).
Proof.
  induction w as [|[b n] t IH].
  - reflexivity.
  - destruct b.
    +
      destruct n as [|n'].
      * cbn [wpop1s]. rewrite <- IH. cbn [wdec lpow]. reflexivity.
      * reflexivity.
    +
      cbn [wpop1s].
      destruct (wpop1s t) as [m t'] eqn:E.
      cbn [fst snd wdec].
      rewrite IH. cbn [fst snd].
      rewrite lpow_add, Str_app_assoc. reflexivity.
Qed.
Lemma wpop1s_stops (w : wside) :
  fst (wpop (snd (wpop1s w))) = 0.
Proof.
  induction w as [|[b n] t IH].
  - reflexivity.
  - destruct b.
    + destruct n as [|n']; [exact IH|].
      cbn [wpop1s snd wpop]. destruct n'; reflexivity.
    + cbn [wpop1s].
      destruct (wpop1s t) as [m t'] eqn:E.
      exact IH.
Qed.
Local Opaque wpush.
Theorem wsection_sound l cur r l' cur' r' n :
  wsection l cur r = Some (l', cur', r', n) ->
  wconf l cur r =( n )=> wconf l' cur' r'.
Proof.
  unfold wsection.
  destruct cur.
  -
    destruct (wpop r) as [b0 r0] eqn:E0.
    destruct (wpop r0) as [b1 r1] eqn:E1.
    pose proof (wpop_dec r) as D0; rewrite E0 in D0; cbn [fst snd] in D0.
    pose proof (wpop_dec r0) as D1; rewrite E1 in D1; cbn [fst snd] in D1.
    destruct b0, b1.
    +
      destruct (wpop1s l) as [m la] eqn:F0.
      destruct (wpop la) as [z lb] eqn:F1.
      destruct (wpop lb) as [c2 lc] eqn:F2.
      intros H; inversion H; subst l' cur' r' n; clear H.
      pose proof (wpop1s_dec l) as G0; rewrite F0 in G0; cbn [fst snd] in G0.
      pose proof (wpop1s_stops l) as GS; rewrite F0 in GS; cbn [snd] in GS;
        rewrite F1 in GS; cbn [fst] in GS; subst z.
      pose proof (wpop_dec la) as G1; rewrite F1 in G1; cbn [fst snd] in G1.
      pose proof (wpop_dec lb) as G2; rewrite F2 in G2; cbn [fst snd] in G2.
      unfold wconf.
      rewrite D0, D1, G0, G1, G2, wpush_dec.
      exact (csection_D0_00 m (c2 >> wdec lc) (wdec r1)).
    +
      destruct (wpop1s r1) as [m ra] eqn:F0.
      destruct (wpop ra) as [z rb] eqn:F1.
      destruct (wpop rb) as [c2 rc] eqn:F2.
      intros H; inversion H; subst l' cur' r' n; clear H.
      pose proof (wpop1s_dec r1) as G0; rewrite F0 in G0; cbn [fst snd] in G0.
      pose proof (wpop1s_stops r1) as GS; rewrite F0 in GS; cbn [snd] in GS;
        rewrite F1 in GS; cbn [fst] in GS; subst z.
      pose proof (wpop_dec ra) as G1; rewrite F1 in G1; cbn [fst snd] in G1.
      pose proof (wpop_dec rb) as G2; rewrite F2 in G2; cbn [fst snd] in G2.
      unfold wconf.
      rewrite D0, D1, G0, G1, G2, !wpush_dec.
      exact (csection_D0_01 m (wdec l) (c2 >> wdec rc)).
    +
      intros H; discriminate H.
    +
      destruct (wpop1s r1) as [m ra] eqn:F0.
      destruct (wpop ra) as [z rb] eqn:F1.
      destruct (wpop rb) as [c2 rc] eqn:F2.
      intros H; inversion H; subst l' cur' r' n; clear H.
      pose proof (wpop1s_dec r1) as G0; rewrite F0 in G0; cbn [fst snd] in G0.
      pose proof (wpop1s_stops r1) as GS; rewrite F0 in GS; cbn [snd] in GS;
        rewrite F1 in GS; cbn [fst] in GS; subst z.
      pose proof (wpop_dec ra) as G1; rewrite F1 in G1; cbn [fst snd] in G1.
      pose proof (wpop_dec rb) as G2; rewrite F2 in G2; cbn [fst snd] in G2.
      unfold wconf.
      rewrite D0, D1, G0, G1, G2, !wpush_dec.
      exact (csection_D0_11 m (wdec l) (c2 >> wdec rc)).
  -
    destruct (wpop l) as [l0 la] eqn:E0.
    pose proof (wpop_dec l) as D0; rewrite E0 in D0; cbn [fst snd] in D0.
    destruct l0.
    +
      destruct (wpop1s la) as [m lb] eqn:F0.
      destruct (wpop lb) as [z lc] eqn:F1.
      destruct (wpop lc) as [c2 ld] eqn:F2.
      intros H; inversion H; subst l' cur' r' n; clear H.
      pose proof (wpop1s_dec la) as G0; rewrite F0 in G0; cbn [fst snd] in G0.
      pose proof (wpop1s_stops la) as GS; rewrite F0 in GS; cbn [snd] in GS;
        rewrite F1 in GS; cbn [fst] in GS; subst z.
      pose proof (wpop_dec lb) as G1; rewrite F1 in G1; cbn [fst snd] in G1.
      pose proof (wpop_dec lc) as G2; rewrite F2 in G2; cbn [fst snd] in G2.
      unfold wconf.
      rewrite D0, G0, G1, G2, !wpush_dec.
      exact (csection_D1_0 m (c2 >> wdec ld) (wdec r)).
    + destruct (wpop la) as [l1 lb] eqn:E1.
      pose proof (wpop_dec la) as D1; rewrite E1 in D1; cbn [fst snd] in D1.
      destruct l1.
      *
        intros H; inversion H; subst l' cur' r' n; clear H.
        unfold wconf.
        rewrite D0, D1, !wpush_dec.
        exact (csection_D1_1_left (wdec lb) (wdec r)).
      *
        destruct (wpop r) as [c2 rc] eqn:F0.
        intros H; inversion H; subst l' cur' r' n; clear H.
        pose proof (wpop_dec r) as G0; rewrite F0 in G0; cbn [fst snd] in G0.
        unfold wconf.
        rewrite !wpush_dec, D0, D1, G0.
        exact (csection_D1_1_right (wdec lb) (c2 >> wdec rc)).
Qed.
Local Transparent wpush.
Local Opaque wpush.
Local Transparent wpush.
Section Closure.
End Closure.
Definition wstate : Type := (wside * Sym * wside)%type.
Definition wconf' (s : wstate) : Q * tape :=
  let '(l, cur, r) := s in wconf l cur r.
Fixpoint wrun (n : nat) (l : wside) (cur : Sym) (r : wside)
  : option wstate :=
  match n with
  | O => Some (l, cur, r)
  | S n' =>
    match wsection l cur r with
    | Some (l', cur', r', _) => wrun n' l' cur' r'
    | None => None
    end
  end.
Definition wrun_state (n : nat) (s : wstate) : option wstate :=
  let '(l, cur, r) := s in wrun n l cur r.
Section RoundClosure.
  Variable Good : wstate -> Prop.
  Hypothesis good_step :
    forall s, Good s ->
    exists n s', wrun_state (S n) s = Some s' /\ Good s'.
  Hypothesis good_init :
    exists fuel s0, wrun fuel [] 0 [(1, 2%nat)] = Some s0 /\ Good s0.
End RoundClosure.
Fixpoint pair_runs (o z c : nat) : wside :=
  match c with
  | O => []
  | S c' => (1, o) :: (0, z) :: pair_runs o z c'
  end.
Fixpoint expand (g : list (nat * nat * nat)) : wside :=
  match g with
  | [] => []
  | (o, z, c) :: t => pair_runs o z c ++ expand t
  end.
Lemma wrun_split (a b : nat) (l : wside) (cur : Sym) (r : wside) l1 c1 r1 :
  wrun a l cur r = Some (l1, c1, r1) ->
  wrun (a + b) l cur r = wrun b l1 c1 r1.
Proof.
  revert l cur r; induction a as [|a IH]; intros l cur r H; cbn in H |- *.
  - now inversion H; subst.
  - destruct (wsection l cur r) as [[[[l' c'] r'] n]|].
    + now apply IH.
    + discriminate.
Qed.
Lemma dborrow_in (x b : nat) (L r : wside) :
  wrun 2 ((0, 1%nat) :: (1, S b) :: L) 0
         ((1, S (S (S x))) :: (0, 3%nat) :: (1, 4%nat) :: (0, 2%nat) :: r)
  = Some ((0, 1%nat) :: (1, 6%nat) :: (0, 1%nat) :: (1, S x) :: (0, 1%nat)
            :: (1, 2%nat) :: (0, 1%nat) :: (1, S b) :: L, 0, r).
Proof. cbn; rewrite ?PeanoNat.Nat.add_0_r; reflexivity. Qed.
Definition vpush (m : nat) (l : wside) : wside :=
  wpush 0 1 (wpush 1 m (wpush 0 1 (wpush 1 2 l))).
Lemma wsection_cross m l r :
  wsection l 0 ((1, (2 + m)%nat) :: (0, 2%nat) :: r)
  = Some (vpush m l, 0, r, (m + 4)%nat).
Proof.
  unfold vpush.
  destruct m as [|m]; cbn; rewrite ?PeanoNat.Nat.add_0_r; reflexivity.
Qed.
Fixpoint pair_runs' (o z c : nat) : wside :=
  match c with
  | O => []
  | S c' => (1, o) :: (0, z) :: pair_runs' o z c'
  end.
Lemma wrun_add a b l cur r :
  wrun (a + b) l cur r
  = match wrun a l cur r with
    | Some (l1, cur1, r1) => wrun b l1 cur1 r1
    | None => None
    end.
Proof.
  gen l cur r. induction a as [|a IH]; intros l cur r; cbn [wrun Nat.add].
  - reflexivity.
  - destruct (wsection l cur r) as [[[[l1 cur1] r1] k]|]; [apply IH | reflexivity].
Qed.
Definition wstep (s s' : wside * Sym * wside) : Prop :=
  exists f, let '(l, cur, r) := s in wrun (S f) l cur r = Some s'.
Lemma wstep_trans s1 s2 s3 : wstep s1 s2 -> wstep s2 s3 -> wstep s1 s3.
Proof.
  destruct s1 as [[l1 c1] r1], s2 as [[l2 c2] r2].
  intros [f1 H1] [f2 H2].
  exists (f1 + S f2)%nat.
  replace (S (f1 + S f2))%nat with (S f1 + S f2)%nat by lia.
  rewrite wrun_add, H1. exact H2.
Qed.
Lemma wstep_of n l cur r s' :
  wrun (S n) l cur r = Some s' -> wstep (l, cur, r) s'.
Proof. intros H. exists n. exact H. Qed.
Fixpoint uword (ms : list nat) (r : wside) : wside :=
  match ms with
  | [] => r
  | m :: t => (1, (2 + m)%nat) :: (0, 2%nat) :: uword t r
  end.
Fixpoint vstack (ms : list nat) (l : wside) : wside :=
  match ms with
  | [] => l
  | m :: t => vstack t (vpush m l)
  end.
Lemma wcross_mixed ms l r :
  wrun (List.length ms) l 0 (uword ms r) = Some (vstack ms l, 0, r).
Proof.
  gen l. induction ms as [|m t IH]; intros l.
  - reflexivity.
  - cbn [uword List.length wrun].
    rewrite wsection_cross. apply IH.
Qed.
Definition vpairC (m : nat) (Z : wside) : wside :=
  match m with
  | O => (0,2%nat) :: (1,2%nat) :: Z
  | S _ => (0,1%nat) :: (1,m) :: (0,1%nat) :: (1,2%nat) :: Z
  end.
Fixpoint vstackC (ms : list nat) (Z : wside) : wside :=
  match ms with
  | [] => Z
  | m :: t => vpairC m (vstackC t Z)
  end.
Definition zheaded (Z : wside) : Prop :=
  match Z with
  | [] => True
  | (b, _) :: _ => b = 0
  end.
Lemma vpairC_vpush m Z : zheaded Z -> vpush m Z = vpairC m Z.
Proof.
  destruct m as [|m]; destruct Z as [|[[|] n] t]; cbn;
    intuition congruence.
Qed.
Lemma vpairC_zheaded m Z : zheaded (vpairC m Z).
Proof. destruct m; cbn; reflexivity. Qed.
Lemma vstackC_zheaded ms Z : zheaded Z -> zheaded (vstackC ms Z).
Proof.
  destruct ms as [|m t]; cbn; [auto | intros _; apply vpairC_zheaded].
Qed.
Lemma vstackC_app a b Z :
  vstackC (a ++ b) Z = vstackC a (vstackC b Z).
Proof.
  induction a as [|m t IH]; cbn; [reflexivity | rewrite IH; reflexivity].
Qed.
Lemma vstack_vstackC ms Z :
  zheaded Z -> vstack ms Z = vstackC (rev ms) Z.
Proof.
  gen Z. induction ms as [|m t IH]; intros Z HZ; cbn [vstack rev].
  - reflexivity.
  - rewrite (IH (vpush m Z)).
    + rewrite vstackC_app. cbn [vstackC].
      rewrite (vpairC_vpush m Z HZ). reflexivity.
    + rewrite (vpairC_vpush m Z HZ). apply vpairC_zheaded.
Qed.
Fixpoint emit (ms : list nat) (r : wside) : wside :=
  match ms with
  | [] => r
  | m :: t => emit t (wpush 1 (m + 2) (wpush 0 1 (wpush 0 1 r)))
  end.
Lemma wstep2 m Z r :
  wsection (vpairC m Z) 1 r
  = Some ((1,1%nat) :: Z, 1, wpush 1 (m + 2) (wpush 0 1 r), (m + 3)%nat).
Proof.
  destruct m as [|m]; cbn; rewrite ?PeanoNat.Nat.add_0_r; reflexivity.
Qed.
Lemma wstep1 m Z r :
  wsection ((1,1%nat) :: vpairC m Z) 1 r
  = Some (vpairC m Z, 1, wpush 0 1 r, 3%nat).
Proof.
  destruct m as [|m]; cbn; reflexivity.
Qed.
Lemma wback_run ms Z r :
  wrun (2 * List.length ms) ((1,1%nat) :: vstackC ms Z) 1 r
  = Some ((1,1%nat) :: Z, 1, emit ms r).
Proof.
  gen r. induction ms as [|m t IH]; intros r.
  - reflexivity.
  - cbn [vstackC List.length].
    replace (2 * S (List.length t))%nat with (S (S (2 * List.length t)))
      by lia.
    cbn [wrun].
    rewrite wstep1, wstep2.
    apply IH.
Qed.
Lemma wfuelcross x y l r :
  wsection l 0 ((1,(2+x)%nat) :: (0,1%nat) :: (1,S (S y)) :: r)
  = Some (vpush x l, 1, (1, S y) :: r, (x + 4)%nat).
Proof.
  destruct x as [|x]; cbn; rewrite ?PeanoNat.Nat.add_0_r; reflexivity.
Qed.
Lemma uword_app a b r : uword (a ++ b) r = uword a (uword b r).
Proof.
  induction a as [|m t IH]; cbn; [reflexivity | rewrite IH; reflexivity].
Qed.
Lemma emit_uword ms n r0 :
  emit ms ((1,S n) :: r0) = uword (rev ms) ((1,S n) :: r0).
Proof.
  gen n r0. induction ms as [|m t IH]; intros n r0; cbn [emit rev].
  - reflexivity.
  - replace ((m + 2)%nat) with (S (m + 1)) by lia.
    cbn.
    rewrite IH.
    rewrite uword_app. cbn [uword].
    replace ((2 + m)%nat) with (S (m + 1)) by lia.
    reflexivity.
Qed.
Lemma wclose1 r :
  wsection [(1,1%nat)] 1 r = Some ([(0,1%nat)], 1, wpush 0 1 r, 3%nat).
Proof. reflexivity. Qed.
Lemma wclose2 r :
  wsection [(0,1%nat)] 1 r
  = Some ([], 0, wpush 1 2 (wpush 0 1 r), 3%nat).
Proof. reflexivity. Qed.
Lemma kernel_return ms x y rest :
  wrun (3 * List.length ms + 4)%nat [] 0
       (uword ms ((1,(2+x)%nat) :: (0,1%nat) :: (1,S (S y)) :: rest))
  = Some ([], 0,
          uword (0%nat :: ms)
                ((1,(2+x)%nat) :: (0,1%nat) :: (1,S y) :: rest)).
Proof.
  replace (3 * List.length ms + 4)%nat
    with (List.length ms + S (2 * List.length ms + 3))%nat by lia.
  rewrite wrun_add, wcross_mixed.
  cbn [wrun].
  rewrite wfuelcross.
  lazy beta iota.
  rewrite (vstack_vstackC ms [] I).
  rewrite (vpairC_vpush x _ (vstackC_zheaded (rev ms) [] I)).
  replace (2 * List.length ms + 3)%nat
    with (S (2 * List.length (rev ms) + 2))%nat
    by (rewrite length_rev; lia).
  cbn [wrun].
  rewrite wstep2.
  lazy beta iota.
  rewrite (wrun_add (2 * List.length (rev ms)) 2).
  rewrite wback_run.
  lazy beta iota.
  replace ((x + 2)%nat) with (S (x + 1)) by lia.
  cbn [wpush sym_eqb].
  rewrite emit_uword, rev_involutive.
  cbn [wrun].
  rewrite wclose1.
  lazy beta iota.
  rewrite wclose2.
  lazy beta iota.
  f_equal. f_equal.
  replace (S (x + 1)) with ((2 + x)%nat) by lia.
  destruct ms as [|m t]; cbn; reflexivity.
Qed.
Lemma pair_runs'_snoc o z c X :
  pair_runs' o z c ++ (1,o)::(0,z)::X = pair_runs' o z (S c) ++ X.
Proof.
  induction c as [|c IH]; cbn.
  - reflexivity.
  - now rewrite IH.
Qed.
Lemma wcross1 m l r :
  wrun 1 l 0 ((1, (2 + m)%nat)::(0,2%nat)::r) = Some (vpush m l, 0, r).
Proof. cbn [wrun]. rewrite wsection_cross. reflexivity. Qed.
Fixpoint zeros (n : nat) : list nat :=
  match n with
  | O => []
  | S n' => 0%nat :: zeros n'
  end.
Lemma zeros_shift n ms : zeros n ++ 0%nat :: ms = zeros (S n) ++ ms.
Proof.
  induction n as [|n IH]; cbn; [reflexivity | rewrite IH; reflexivity].
Qed.
Lemma wmergecross x z l rest :
  wsection l 0 ((1,(2+x)%nat) :: (0,1%nat) :: (1,1%nat) :: (0,S z) :: rest)
  = Some (vpush x l, 1, (0,S z) :: rest, (x + 4)%nat).
Proof.
  destruct x as [|x]; cbn; rewrite ?PeanoNat.Nat.add_0_r; reflexivity.
Qed.
Lemma kernel_merge ms x z rest :
  wrun (3 * List.length ms + 4)%nat [] 0
       (uword ms ((1,(2+x)%nat) :: (0,1%nat) :: (1,1%nat) :: (0,S z) :: rest))
  = Some ([], 0,
          uword (0%nat :: ms) ((1,(2+x)%nat) :: (0,S (S z)) :: rest)).
Proof.
  replace (3 * List.length ms + 4)%nat
    with (List.length ms + S (2 * List.length ms + 3))%nat by lia.
  rewrite wrun_add, wcross_mixed.
  cbn [wrun].
  rewrite wmergecross.
  lazy beta iota.
  rewrite (vstack_vstackC ms [] I).
  rewrite (vpairC_vpush x _ (vstackC_zheaded (rev ms) [] I)).
  replace (2 * List.length ms + 3)%nat
    with (S (2 * List.length (rev ms) + 2))%nat
    by (rewrite length_rev; lia).
  cbn [wrun].
  rewrite wstep2.
  lazy beta iota.
  rewrite (wrun_add (2 * List.length (rev ms)) 2).
  rewrite wback_run.
  lazy beta iota.
  replace ((x + 2)%nat) with (S (x + 1)) by lia.
  cbn [wpush sym_eqb].
  rewrite emit_uword, rev_involutive.
  cbn [wrun].
  rewrite wclose1.
  lazy beta iota.
  rewrite wclose2.
  lazy beta iota.
  f_equal. f_equal.
  replace (S (x + 1)) with ((2 + x)%nat) by lia.
  destruct ms as [|m t]; cbn; reflexivity.
Qed.
Lemma kernel_merge_step ms x z rest :
  wstep ([], 0, uword ms
                  ((1,(2+x)%nat) :: (0,1%nat) :: (1,1%nat) :: (0,S z) :: rest))
        ([], 0, uword (0%nat :: ms) ((1,(2+x)%nat) :: (0,S (S z)) :: rest)).
Proof.
  apply (wstep_of (3 * List.length ms + 3)).
  replace (S (3 * List.length ms + 3))%nat
    with (3 * List.length ms + 4)%nat by lia.
  apply kernel_merge.
Qed.
Lemma wmargincross x l :
  wsection l 0 ((1,(2+x)%nat) :: (0,1%nat) :: (1,1%nat) :: nil)
  = Some (vpush x l, 1, [], (x + 4)%nat).
Proof.
  destruct x as [|x]; cbn; rewrite ?PeanoNat.Nat.add_0_r; reflexivity.
Qed.
Lemma ccyc a b T R :
  wrun 4 ((1,2%nat)::(0,2%nat)::T) 0
       ((1,S (S (S a)))::(0,1%nat)::(1,S (S b))::R)
  = Some (T, 0, (1,5%nat)::(0,1%nat)::(1,(a+2)%nat)::(0,1%nat)::(1,S b)::R).
Proof.
  destruct a as [|a]; cbn; rewrite ?PeanoNat.Nat.add_0_r; reflexivity.
Qed.
Lemma cfin a b R :
  wrun 4 ((1,2%nat)::nil) 0
       ((1,S (S (S a)))::(0,1%nat)::(1,S (S b))::R)
  = Some ([], 0, (1,5%nat)::(0,1%nat)::(1,(a+2)%nat)::(0,1%nat)::(1,S b)::R).
Proof.
  destruct a as [|a]; cbn; rewrite ?PeanoNat.Nat.add_0_r; reflexivity.
Qed.
Fixpoint cdesc (j a b : nat) (R : wside) : wside :=
  match j with
  | O => (1,5%nat)::(0,1%nat)::(1,(a+2)%nat)::(0,1%nat)::(1,S b)::R
  | S j' => cdesc j' 2 a ((0,1%nat)::(1,S b)::R)
  end.
Lemma ccyc_chain j a b R :
  wrun (4 * j + 4) ((1,2%nat)::vstackC (zeros j) []) 0
       ((1,S (S (S a)))::(0,1%nat)::(1,S (S b))::R)
  = Some ([], 0, cdesc j a b R).
Proof.
  gen a b R. induction j as [|j IH]; intros a b R.
  - apply cfin.
  - cbn [zeros vstackC vpairC cdesc].
    replace (4 * S j + 4)%nat with (4 + (4 * j + 4))%nat by lia.
    erewrite wrun_split by apply ccyc.
    replace ((a + 2)%nat) with (S (S a)) by lia.
    apply IH.
Qed.
Lemma length_zeros n : List.length (zeros n) = n.
Proof.
  induction n as [|n IH]; cbn; [reflexivity | rewrite IH; reflexivity].
Qed.
Lemma rev_zeros n : rev (zeros n) = zeros n.
Proof.
  induction n as [|n IH]; cbn.
  - reflexivity.
  - rewrite IH. rewrite (zeros_shift n []). rewrite app_nil_r. reflexivity.
Qed.
Lemma kernel_merge_margin ms x :
  wrun (3 * List.length ms + 4)%nat [] 0
       (uword ms ((1,(2+x)%nat) :: (0,1%nat) :: (1,1%nat) :: nil))
  = Some ([], 0, uword (0%nat :: ms) ((1,(2+x)%nat) :: (0,1%nat) :: nil)).
Proof.
  replace (3 * List.length ms + 4)%nat
    with (List.length ms + S (2 * List.length ms + 3))%nat by lia.
  rewrite wrun_add, wcross_mixed.
  cbn [wrun].
  rewrite wmargincross.
  lazy beta iota.
  rewrite (vstack_vstackC ms [] I).
  rewrite (vpairC_vpush x _ (vstackC_zheaded (rev ms) [] I)).
  replace (2 * List.length ms + 3)%nat
    with (S (2 * List.length (rev ms) + 2))%nat
    by (rewrite length_rev; lia).
  cbn [wrun].
  rewrite wstep2.
  lazy beta iota.
  rewrite (wrun_add (2 * List.length (rev ms)) 2).
  rewrite wback_run.
  lazy beta iota.
  replace ((x + 2)%nat) with (S (x + 1)) by lia.
  cbn [wpush sym_eqb].
  rewrite emit_uword, rev_involutive.
  cbn [wrun].
  rewrite wclose1.
  lazy beta iota.
  rewrite wclose2.
  lazy beta iota.
  f_equal. f_equal.
  replace (S (x + 1)) with ((2 + x)%nat) by lia.
  destruct ms as [|m t]; cbn; reflexivity.
Qed.
Lemma dborrow_in' (x : nat) (l r : wside) :
  zheaded l ->
  wrun 2 l 0 ((1, S (S (S x))) :: (0,3%nat) :: (1,4%nat) :: (0,2%nat) :: r)
  = Some ((0,1%nat) :: (1,6%nat) :: (0,1%nat) :: (1,S x) :: (0,1%nat)
            :: (1,2%nat) :: l, 0, r).
Proof.
  intros H.
  destruct l as [|[b n] t].
  - cbn; rewrite ?PeanoNat.Nat.add_0_r; reflexivity.
  - destruct b; [|discriminate H].
    cbn; rewrite ?PeanoNat.Nat.add_0_r; reflexivity.
Qed.
Lemma kernel_merge_margin_step ms x :
  wstep ([], 0, uword ms ((1,(2+x)%nat) :: (0,1%nat) :: (1,1%nat) :: nil))
        ([], 0, uword (0%nat :: ms) ((1,(2+x)%nat) :: (0,1%nat) :: nil)).
Proof.
  apply (wstep_of (3 * List.length ms + 3)).
  replace (S (3 * List.length ms + 3))%nat
    with (3 * List.length ms + 4)%nat by lia.
  apply kernel_merge_margin.
Qed.
Lemma zheaded0 (n : nat) (w : wside) : zheaded ((0,n) :: w).
Proof. reflexivity. Qed.
Lemma ddeep_in (l r : wside) :
  zheaded l ->
  wrun 2 l 0 ((1,3%nat) :: (0,3%nat) :: (1,4%nat) :: (0,2%nat) :: r)
  = Some ((0,1%nat) :: (1,6%nat) :: (0,1%nat) :: (1,1%nat) :: (0,1%nat)
            :: (1,2%nat) :: l, 0, r).
Proof.
  intros H.
  destruct l as [|[b n] t].
  - cbn; reflexivity.
  - destruct b; [|discriminate H].
    cbn; reflexivity.
Qed.
Lemma ddeep_mint (Z r : wside) (n : nat) :
  wrun 2 ((1,1%nat) :: (0,1%nat) :: (1,6%nat) :: (0,1%nat) :: (1,1%nat)
            :: (0,1%nat) :: (1,2%nat) :: Z) 1 ((1,S n) :: r)
  = Some ((0,1%nat) :: (1,2%nat) :: Z, 1,
          (1,8%nat) :: (0,2%nat) :: (1,S n) :: r).
Proof. reflexivity. Qed.
Lemma uword_one_headed ns n r :
  exists p q, uword ns ((1, S n) :: r) = (1, S p) :: q.
Proof.
  destruct ns as [|m t]; cbn [uword].
  - exists n, r. reflexivity.
  - exists (S m), ((0,2%nat) :: uword t ((1, S n) :: r)). reflexivity.
Qed.
Lemma wpush_1S (x n : nat) (r : wside) :
  wpush 1 (S x) (wpush 0 1 ((1, S n) :: r))
  = (1, S x) :: (0,1%nat) :: (1, S n) :: r.
Proof. reflexivity. Qed.
Lemma ddeep_mint_u (Z : wside) ns (n : nat) (r : wside) :
  wrun 2 ((1,1%nat) :: (0,1%nat) :: (1,6%nat) :: (0,1%nat) :: (1,1%nat)
            :: (0,1%nat) :: (1,2%nat) :: Z) 1 (uword ns ((1, S n) :: r))
  = Some ((0,1%nat) :: (1,2%nat) :: Z, 1,
          (1,8%nat) :: (0,2%nat) :: uword ns ((1, S n) :: r)).
Proof.
  destruct (uword_one_headed ns n r) as (p & q & E).
  rewrite E.
  exact (ddeep_mint Z q p).
Qed.
Lemma ddeep_in4 (l r : wside) :
  zheaded l ->
  wrun 2 l 0 ((1,4%nat) :: (0,3%nat) :: (1,4%nat) :: (0,2%nat) :: r)
  = Some ((0,1%nat) :: (1,6%nat) :: (0,1%nat) :: (1,2%nat) :: (0,1%nat)
            :: (1,2%nat) :: l, 0, r).
Proof.
  intros H.
  destruct l as [|[b n] t].
  - cbn; reflexivity.
  - destruct b; [|discriminate H].
    cbn; reflexivity.
Qed.
Lemma ddeep_mint4 (Z r : wside) (n : nat) :
  wrun 3 ((1,1%nat) :: (0,1%nat) :: (1,6%nat) :: (0,1%nat) :: (1,2%nat)
            :: (0,1%nat) :: (1,2%nat) :: Z) 1 ((1,S n) :: r)
  = Some ((0,1%nat) :: (1,2%nat) :: Z, 1,
          (0,1%nat) :: (1,8%nat) :: (0,2%nat) :: (1,S n) :: r).
Proof. reflexivity. Qed.
Lemma ddeep_mint4_u (Z : wside) ns (n : nat) (r : wside) :
  wrun 3 ((1,1%nat) :: (0,1%nat) :: (1,6%nat) :: (0,1%nat) :: (1,2%nat)
            :: (0,1%nat) :: (1,2%nat) :: Z) 1 (uword ns ((1, S n) :: r))
  = Some ((0,1%nat) :: (1,2%nat) :: Z, 1,
          (0,1%nat) :: (1,8%nat) :: (0,2%nat) :: uword ns ((1, S n) :: r)).
Proof.
  destruct (uword_one_headed ns n r) as (p & q & E).
  rewrite E.
  exact (ddeep_mint4 Z q p).
Qed.
Lemma ddeep_entry4 (T r : wside) (z : nat) :
  wrun 1 ((0,1%nat) :: (1,2%nat) :: (0,2%nat) :: (1,2%nat) :: T) 1
         ((0,S z) :: r)
  = Some ((1,2%nat) :: T, 0, (1,4%nat) :: (0,S (S z)) :: r).
Proof. reflexivity. Qed.
Lemma vpush_merge2 (T : wside) :
  vpush 2 ((1,2%nat) :: T)
  = (0,1%nat) :: (1,2%nat) :: (0,1%nat) :: (1,4%nat) :: T.
Proof. reflexivity. Qed.
Lemma ddeep_redig (Z r : wside) (n : nat) :
  wrun 3 ((1,1%nat) :: (0,1%nat) :: (1,2%nat) :: (0,1%nat) :: (1,4%nat) :: Z)
         1 ((1,S n) :: r)
  = Some ((0,1%nat) :: (1,3%nat) :: Z, 1,
          (1,3%nat) :: (0,2%nat) :: (1,S n) :: r).
Proof. reflexivity. Qed.
Lemma ddeep_fin4 (T r : wside) (n : nat) :
  wrun 1 ((0,1%nat) :: (1,3%nat) :: (0,2%nat) :: (1,2%nat) :: T) 1
         ((1,S n) :: r)
  = Some ((1,2%nat) :: T, 0, (1,5%nat) :: (0,1%nat) :: (1,S n) :: r).
Proof. reflexivity. Qed.
Lemma dm4_half_step (z : nat) (Z : wside) (p : nat) (q : wside) :
  wrun 2 (vpairC 2 ((0,1%nat) :: (1,S z) :: Z)) 1 ((0,1%nat) :: (1,S p) :: q)
  = Some ((0,1%nat) :: (1,S z) :: Z, 1,
          (0,1%nat) :: (1,4%nat) :: (0,2%nat) :: (1,S p) :: q).
Proof. reflexivity. Qed.
Lemma uword_repeat2_shift (j : nat) (X : wside) :
  uword (repeat 2%nat j) ((1,4%nat) :: (0,2%nat) :: X)
  = (1,4%nat) :: (0,2%nat) :: uword (repeat 2%nat j) X.
Proof.
  induction j as [|j IH]; cbn [repeat uword]; [reflexivity | rewrite IH; reflexivity].
Qed.
Lemma dm4_half (j : nat) (z : nat) (Z : wside) (p : nat) (q : wside) :
  wrun (2 * j) (vstackC (repeat 2%nat j) ((0,1%nat) :: (1,S z) :: Z)) 1
       ((0,1%nat) :: (1,S p) :: q)
  = Some ((0,1%nat) :: (1,S z) :: Z, 1,
          (0,1%nat) :: uword (repeat 2%nat j) ((1,S p) :: q)).
Proof.
  gen p q. induction j as [|j IH]; intros p q.
  - reflexivity.
  - replace (2 * S j)%nat with (2 + 2 * j)%nat by lia.
    destruct j as [|j''].
    + erewrite wrun_split by apply (dm4_half_step z Z p q).
      reflexivity.
    + erewrite wrun_split
        by apply (dm4_half_step 1
             ((0,1%nat) :: (1,2%nat)
                :: vstackC (repeat 2%nat j'') ((0,1%nat) :: (1,S z) :: Z))
             p q).
      change ((0, 1%nat) :: (1, S 1) :: (0, 1%nat) :: (1, 2%nat)
                :: vstackC (repeat 2%nat j'') ((0,1%nat) :: (1,S z) :: Z))
        with (vstackC (repeat 2%nat (S j'')) ((0,1%nat) :: (1,S z) :: Z)).
      rewrite (IH 3 ((0,2%nat) :: (1,S p) :: q)).
      cbn [uword repeat].
      rewrite uword_repeat2_shift.
      reflexivity.
Qed.
Lemma rev_repeat (n : nat) : rev (repeat 2%nat n) = repeat 2%nat n.
Proof.
  induction n as [|n IH]; cbn; [reflexivity|].
  rewrite IH.
  clear IH; induction n as [|n IH]; cbn; [reflexivity | rewrite <- IH; reflexivity].
Qed.
Lemma hshift (j : nat) (W : wside) :
  (0,1%nat) :: (1,2%nat) :: vstackC (repeat 2%nat j) W
  = vstackC (repeat 2%nat j) ((0,1%nat) :: (1,2%nat) :: W).
Proof.
  induction j as [|j IH]; cbn [repeat vstackC]; [reflexivity|].
  cbn [vpairC].
  rewrite IH.
  reflexivity.
Qed.
Lemma ddeep_redig_u (Z : wside) (ks : list nat) (n : nat) (r0 : wside) :
  wrun 3 ((1,1%nat) :: (0,1%nat) :: (1,2%nat) :: (0,1%nat) :: (1,4%nat) :: Z)
         1 (uword ks ((1, S n) :: r0))
  = Some ((0,1%nat) :: (1,3%nat) :: Z, 1,
          (1,3%nat) :: (0,2%nat) :: uword ks ((1, S n) :: r0)).
Proof.
  destruct (uword_one_headed ks n r0) as (p & q & E).
  rewrite E.
  apply ddeep_redig.
Qed.
Lemma vpairC_3p (w : nat) (Z : wside) :
  vpairC (3 + w)%nat Z
  = (0,1%nat) :: (1,S (S (S w))) :: (0,1%nat) :: (1,2%nat) :: Z.
Proof. reflexivity. Qed.
Lemma rev_repeat1 (n : nat) : rev (repeat 1%nat n) = repeat 1%nat n.
Proof.
  induction n as [|n IH]; cbn; [reflexivity|].
  rewrite IH.
  clear IH; induction n as [|n IH]; cbn; [reflexivity | rewrite <- IH; reflexivity].
Qed.
Lemma dcp_step (n : nat) (Z r : wside) :
  wsection ((0,1%nat)::(1,2%nat)::(0,1%nat)::(1,1%nat)::(0,1%nat)::(1,2%nat)::Z)
           1 ((1,S n)::r)
  = Some ((0,1%nat)::(1,2%nat)::Z, 1, (1,4%nat)::(0,1%nat)::(1,S n)::r, 5%nat).
Proof. reflexivity. Qed.
Lemma dcp_run (b : nat) (Z : wside) (n : nat) (r : wside) :
  wrun b ((0,1%nat)::(1,2%nat)::vstackC (repeat 1%nat b) Z) 1 ((1,S n)::r)
  = Some ((0,1%nat)::(1,2%nat)::Z, 1, pair_runs' 4%nat 1%nat b ++ (1,S n)::r).
Proof.
  gen n r. induction b as [|b IH]; intros n r.
  - reflexivity.
  - cbn [repeat vstackC vpairC wrun].
    rewrite dcp_step.
    lazy beta iota.
    rewrite (IH 3 ((0,1%nat)::(1,S n)::r)).
    cbn [pair_runs'].
    rewrite pair_runs'_snoc.
    reflexivity.
Qed.
Lemma dcp_disch (w : nat) (Z : wside) (n : nat) (r : wside) :
  wrun 3 ((0,1%nat)::(1,2%nat)::(0,1%nat)::(1,S (S (S w)))
            ::(0,1%nat)::(1,2%nat)::Z) 1 ((1,S n)::r)
  = Some ((1,1%nat)::Z, 1,
          (1,S (S (S (S w))))::(0,1%nat)::(1,3%nat)::(0,1%nat)::(1,S n)::r).
Proof.
  destruct w as [|w]; cbn; rewrite ?PeanoNat.Nat.add_0_r;
    [reflexivity|].
  replace ((w + 2)%nat) with (S (S w)) by lia.
  reflexivity.
Qed.
Lemma pair_runs41_one_headed b n r :
  exists p q, pair_runs' 4%nat 1%nat b ++ (1,S n) :: r = (1,S p) :: q.
Proof.
  destruct b as [|b]; cbn [pair_runs' app].
  - exists n, r. reflexivity.
  - exists 3%nat, ((0,1%nat) :: pair_runs' 4%nat 1%nat b ++ (1,S n) :: r).
    reflexivity.
Qed.
Lemma dcp_disch_u (w : nat) (Z : wside) (b n : nat) (r : wside) :
  wrun 3 ((0,1%nat)::(1,2%nat)::(0,1%nat)::(1,S (S (S w)))
            ::(0,1%nat)::(1,2%nat)::Z) 1
       (pair_runs' 4%nat 1%nat b ++ (1,S n) :: r)
  = Some ((1,1%nat)::Z, 1,
          (1,S (S (S (S w))))::(0,1%nat)::(1,3%nat)::(0,1%nat)
            :: pair_runs' 4%nat 1%nat b ++ (1,S n) :: r).
Proof.
  destruct (pair_runs41_one_headed b n r) as (p & q & E).
  rewrite E.
  apply dcp_disch.
Qed.
Lemma vstackC_repeat1_S (b : nat) (Z : wside) :
  vstackC (repeat 1%nat (S b)) Z
  = (0,1%nat)::(1,1%nat)::(0,1%nat)::(1,2%nat)::vstackC (repeat 1%nat b) Z.
Proof. reflexivity. Qed.
Lemma dcp4_entry (Z : wside) (n : nat) (r : wside) :
  wrun 1 ((0,1%nat)::(1,3%nat)::(0,1%nat)::(1,1%nat)::(0,1%nat)::(1,2%nat)::Z)
       1 ((1,S n)::r)
  = Some ((0,1%nat)::(1,2%nat)::Z, 1, (1,5%nat)::(0,1%nat)::(1,S n)::r).
Proof. reflexivity. Qed.
Lemma dm4_w1 (Z : wside) (p : nat) (q : wside) :
  wrun 3 ((0,1%nat)::(1,2%nat)::vpairC 1 (vpairC 2 Z)) 1
       ((0,1%nat)::(1,S p)::q)
  = Some ((0,1%nat)::(1,2%nat)::Z, 1,
          (0,1%nat)::(1,4%nat)::(0,1%nat)::(1,4%nat)::(0,2%nat)::(1,S p)::q).
Proof. reflexivity. Qed.
Lemma dm4_w1_u (Z : wside) (ks : list nat) (n : nat) (r0 : wside) :
  wrun 3 ((0,1%nat)::(1,2%nat)::vpairC 1 (vpairC 2 Z)) 1
       ((0,1%nat) :: uword ks ((1, S n) :: r0))
  = Some ((0,1%nat)::(1,2%nat)::Z, 1,
          (0,1%nat)::(1,4%nat)::(0,1%nat)::(1,4%nat)::(0,2%nat)
            :: uword ks ((1, S n) :: r0)).
Proof.
  destruct (uword_one_headed ks n r0) as (p & q & E).
  rewrite E.
  apply dm4_w1.
Qed.
Lemma kernel_return_step ms x y rest :
  wstep ([], 0, uword ms ((1,(2+x)%nat)::(0,1%nat)::(1,S (S y))::rest))
        ([], 0, uword (0%nat :: ms) ((1,(2+x)%nat)::(0,1%nat)::(1,S y)::rest)).
Proof.
  apply (wstep_of (3 * List.length ms + 3)).
  replace (S (3 * List.length ms + 3))%nat
    with (3 * List.length ms + 4)%nat by lia.
  apply kernel_return.
Qed.
Definition Sand (c : nat) (W W' : wside) : Prop :=
  forall b0 L0,
    wrun c ((0,1%nat)::(1,S b0)::L0) 0 W
    = Some ((0,1%nat)::(1,S b0)::L0, 1, (0,1%nat) :: W').
Definition wpeq (p q : Sym * nat) : bool :=
  andb (sym_eqb (fst p) (fst q)) (Nat.eqb (snd p) (snd q)).
Fixpoint wseq (l1 l2 : wside) : bool :=
  match l1, l2 with
  | nil, nil => true
  | a :: t1, b :: t2 => andb (wpeq a b) (wseq t1 t2)
  | _, _ => false
  end.
Lemma wseq_refl l : wseq l l = true.
Proof.
  induction l as [|[s n] l IH]; cbn; [reflexivity|].
  unfold wpeq; cbn.
  rewrite IH, PeanoNat.Nat.eqb_refl.
  destruct s; reflexivity.
Qed.
Definition sand_at (c : nat) (l0 W : wside) : bool :=
  match wrun c l0 0 W with
  | Some (l, cur, r) => andb (wseq l l0) (sym_eqb cur 1)
  | None => false
  end.
Fixpoint sand_none (n k : nat) (l0 W : wside) : bool :=
  match n with
  | O => true
  | S n' => andb (negb (sand_at k l0 W)) (sand_none n' (S k) l0 W)
  end.
Lemma sand_none_sound n k l0 W :
  sand_none n k l0 W = true ->
  forall c, k <= c -> c < k + n -> sand_at c l0 W = false.
Proof.
  revert k; induction n as [|n IH]; intros k H c H1 H2; [lia|].
  cbn in H. apply Bool.andb_true_iff in H as [Hk Hrest].
  destruct (PeanoNat.Nat.eq_dec k c) as [->|Hne].
  - now destruct (sand_at c l0 W).
  - apply (IH (S k) Hrest c); lia.
Qed.
Lemma Sand_sand_at c W W' b0 L0 :
  Sand c W W' -> sand_at c ((0,1%nat)::(1,S b0)::L0) W = true.
Proof.
  intros H. unfold sand_at. rewrite (H b0 L0).
  rewrite wseq_refl. reflexivity.
Qed.
Definition SandL0 : wside := (0,1%nat) :: (1,3%nat) :: (1,9%nat) :: nil.
Ltac reject_sand c W :=
  intros Hc HS;
  pose proof (Sand_sand_at c W _ 2%nat ((1,9%nat)::nil) HS) as A;
  assert (B : sand_at c SandL0 W = false)
    by (apply (sand_none_sound 61 0 SandL0 W);
        [ vm_compute; reflexivity | lia | lia ]);
  unfold SandL0 in B; rewrite A in B; discriminate.
Open Scope sym.
Open Scope list.
Lemma halt_at_guard (l r r0 r1 : wside) :
  wpop r = (1, r0) ->
  wpop r0 = (0, r1) ->
  halts tmB (wconf l 0 r).
Proof.
  intros H0 H1.
  eapply halts_multistep with (n := 2%nat).
  2: {
    unfold wconf.
    rewrite (wpop_dec r), H0; cbn [fst snd].
    rewrite (wpop_dec r0), H1; cbn [fst snd].
    do 2 cstep.
    apply cmul_refl'; [reflexivity|].
    simpl_tape. reflexivity.
  }
  apply halted_halts.
  reflexivity.
Qed.
Lemma wsection_none_guard l r :
  wsection l 0 r = None ->
  exists r0 r1, wpop r = (1, r0) /\ wpop r0 = (0, r1).
Proof.
  intros H. unfold wsection in H.
  destruct (wpop r) as [b0 ra] eqn:E0.
  destruct (wpop ra) as [b1 rb] eqn:E1.
  destruct b0, b1.
  - destruct (wpop1s l) as [m la] in H; destruct (wpop la) as [z lb] in H;
      destruct (wpop lb) as [c2 lc] in H; discriminate H.
  - destruct (wpop1s rb) as [m rc] in H; destruct (wpop rc) as [z rd] in H;
      destruct (wpop rd) as [c2 re] in H; discriminate H.
  - eauto.
  - destruct (wpop1s rb) as [m rc] in H; destruct (wpop rc) as [z rd] in H;
      destruct (wpop rd) as [c2 re] in H; discriminate H.
Qed.
Lemma wrun_none_halts n l cur r :
  wrun n l cur r = None ->
  halts tmB (wconf l cur r).
Proof.
  gen l cur r. induction n as [|n IH]; intros l cur r H; cbn in H.
  - discriminate.
  - destruct (wsection l cur r) as [[[[l1 cur1] r1] k]|] eqn:E.
    +
      eapply halts_multistep.
      * eapply IH, H.
      * eapply wsection_sound, E.
    +
      destruct cur.
      * destruct (wsection_none_guard _ _ E) as (r0 & r1 & H0 & H1).
        eapply halt_at_guard; eauto.
      *
        exfalso. unfold wsection in E.
        destruct (wpop l) as [l0 la] in E.
        destruct l0.
        -- destruct (wpop1s la) as [m lb] in E;
             destruct (wpop lb) as [z lc] in E;
             destruct (wpop lc) as [c2 ld] in E; discriminate E.
        -- destruct (wpop la) as [l1 lb] in E.
           destruct l1.
           ++ discriminate E.
           ++ destruct (wpop r) as [c2 rc] in E; discriminate E.
Qed.
Lemma wrun_some_halts n l cur r s' :
  wrun n l cur r = Some s' ->
  halts tmB (wconf' s') ->
  halts tmB (wconf l cur r).
Proof.
  gen l cur r. induction n as [|n IH]; intros l cur r H Hh; cbn in H.
  - inversion H; subst. exact Hh.
  - destruct (wsection l cur r) as [[[[l1 cur1] r1] k]|] eqn:E;
      [|discriminate].
    eapply halts_multistep.
    + eapply IH; eauto.
    + eapply wsection_sound, E.
Qed.
Open Scope sym.
Open Scope list.
Definition cost : Type := (N * N)%type.
Definition clo (c : cost) : N := fst c.
Definition chi (c : cost) : N := snd c.
Definition czero : cost := (0%N, 0%N).
Definition cx (k : N) : cost := (k, k).
Definition cadd (c1 c2 : cost) : cost :=
  ((fst c1 + fst c2)%N, (snd c1 + snd c2)%N).
Definition cscale (t : N) (c : cost) : cost :=
  ((t * fst c)%N, (t * snd c)%N).
Definition cin (k : nat) (c : cost) : Prop :=
  ((fst c <= N.of_nat k)%N /\ (N.of_nat k <= snd c)%N).
Lemma cin_cx (K : N) : cin (N.to_nat K) (cx K).
Proof. unfold cin, cx; cbn [fst snd]; rewrite N2Nat.id; lia. Qed.
Lemma cin_cx_nat (k : nat) : cin k (cx (N.of_nat k)).
Proof. unfold cin, cx; cbn [fst snd]; lia. Qed.
Lemma cin_czero : cin 0 czero.
Proof. unfold cin, czero; cbn [fst snd]; lia. Qed.
Lemma cin_add (k1 k2 : nat) (c1 c2 : cost) :
  cin k1 c1 -> cin k2 c2 -> cin (k1 + k2)%nat (cadd c1 c2).
Proof.
  unfold cin, cadd; cbn [fst snd].
  rewrite Nat2N.inj_add. lia.
Qed.
Lemma cin_widen (k : nat) (lo hi lo' hi' : N) :
  (lo' <= lo)%N -> (hi <= hi')%N -> cin k (lo, hi) -> cin k (lo', hi').
Proof. unfold cin; cbn [fst snd]. lia. Qed.
Lemma cin_widen' (k : nat) (c c' : cost) :
  (fst c' <= fst c)%N -> (snd c <= snd c')%N -> cin k c -> cin k c'.
Proof. unfold cin. lia. Qed.
Lemma cscale_0 (c : cost) : cscale 0%N c = czero.
Proof. unfold cscale, czero; cbn [fst snd]; f_equal; lia. Qed.
Lemma cscale_succ (t : N) (c : cost) :
  cscale (N.succ t) c = cadd c (cscale t c).
Proof.
  unfold cscale, cadd; cbn [fst snd]; f_equal; rewrite N.mul_succ_l; lia.
Qed.
Lemma cin_scale (t k : nat) (c : cost) :
  cin k c -> cin (t * k)%nat (cscale (N.of_nat t) c).
Proof.
  intros Hk. induction t as [|t IH].
  - cbn [Nat.mul]. change (N.of_nat 0) with 0%N.
    rewrite cscale_0. exact cin_czero.
  - rewrite Nat2N.inj_succ, cscale_succ.
    cbn [Nat.mul]. apply cin_add; assumption.
Qed.
Fixpoint nsum (ks : list nat) : nat :=
  match ks with
  | [] => 0%nat
  | k :: t => (k + nsum t)%nat
  end.
Lemma cin_scale_list (ks : list nat) (c : cost) :
  (forall k, In k ks -> cin k c) ->
  cin (nsum ks) (cscale (N.of_nat (List.length ks)) c).
Proof.
  induction ks as [|k ks IH]; intros H.
  - cbn [nsum List.length]. change (N.of_nat 0) with 0%N.
    rewrite cscale_0. exact cin_czero.
  - cbn [nsum List.length].
    rewrite Nat2N.inj_succ, cscale_succ.
    apply cin_add.
    + apply H. now left.
    + apply IH. intros k' Hk'. apply H. now right.
Qed.
Fixpoint tri (t : nat) : N :=
  match t with
  | O => 0%N
  | S t' => (tri t' + N.of_nat t')%N
  end.
Fixpoint sumf (f : nat -> N) (t : nat) : N :=
  match t with
  | O => 0%N
  | S t' => (sumf f t' + f t')%N
  end.
Theorem sum_affine (a b : N) (t : nat) :
  sumf (fun i => (a * N.of_nat i + b)%N) t = (a * tri t + b * N.of_nat t)%N.
Proof.
  induction t as [|t IH].
  - cbn [sumf tri]. change (N.of_nat 0) with 0%N. lia.
  - cbn [sumf tri]. rewrite IH, Nat2N.inj_succ.
    rewrite N.mul_add_distr_l, N.mul_succ_r.
    lia.
Qed.
Lemma tri_double (t : nat) :
  (2 * tri t = N.of_nat t * (N.of_nat t - 1))%N.
Proof.
  induction t as [|t IH].
  - cbn [tri]. change (N.of_nat 0) with 0%N. lia.
  - cbn [tri]. rewrite Nat2N.inj_succ.
    replace (N.succ (N.of_nat t) - 1)%N with (N.of_nat t) by lia.
    nia.
Qed.
Corollary tri_closed (t : nat) :
  tri t = (N.of_nat t * (N.of_nat t - 1) / 2)%N.
Proof.
  rewrite <- tri_double.
  replace (2 * tri t)%N with (tri t * 2)%N by lia.
  rewrite N.div_mul by discriminate.
  reflexivity.
Qed.
Corollary sum_affine_gauss (a b : N) (t : nat) :
  sumf (fun i => (a * N.of_nat i + b)%N) t
  = (a * (N.of_nat t * (N.of_nat t - 1) / 2) + b * N.of_nat t)%N.
Proof. rewrite sum_affine, tri_closed. reflexivity. Qed.
Lemma halts_in_multistep (c c' : Q * tape) (n m : nat) :
  c =( n )=> c' ->
  halts_in tmB c' m ->
  halts_in tmB c (n + m).
Proof.
  intros H1 [ch [H2 H3]].
  exists ch. split; [eapply multistep_trans; eauto | exact H3].
Qed.
Lemma halts_in_unique (n1 n2 : nat) (c : Q * tape) :
  halts_in tmB c n1 -> halts_in tmB c n2 -> n1 = n2.
Proof.
  intros [ch1 [R1 H1]] [ch2 [R2 H2]].
  destruct (PeanoNat.Nat.lt_trichotomy n1 n2) as [Hlt|[Heq|Hgt]];
    [| exact Heq |].
  - exfalso.
    replace n2 with (n1 + (n2 - n1))%nat in R2 by lia.
    destruct (rewind_split _ _ _ _ _ R2) as [cmid [Ra Rb]].
    pose proof (multistep_deterministic _ _ _ _ _ R1 Ra); subst cmid.
    destruct (n2 - n1)%nat as [|k] eqn:Ek; [lia|].
    inverts Rb as Hstep Hrest.
    exact (halted_no_step _ _ _ H1 Hstep).
  - exfalso.
    replace n1 with (n2 + (n1 - n2))%nat in R1 by lia.
    destruct (rewind_split _ _ _ _ _ R1) as [cmid [Ra Rb]].
    pose proof (multistep_deterministic _ _ _ _ _ R2 Ra); subst cmid.
    destruct (n1 - n2)%nat as [|k] eqn:Ek; [lia|].
    inverts Rb as Hstep Hrest.
    exact (halted_no_step _ _ _ H2 Hstep).
Qed.
Fixpoint wrunc_from (n : nat) (l : wside) (cur : Sym) (r : wside) (acc : N)
  : option (wstate * N) :=
  match n with
  | O => Some ((l, cur, r), acc)
  | S n' =>
    match wsection l cur r with
    | Some (l', cur', r', k) => wrunc_from n' l' cur' r' (acc + N.of_nat k)%N
    | None => None
    end
  end.
Definition wrunc (n : nat) (l : wside) (cur : Sym) (r : wside)
  : option (wstate * N) := wrunc_from n l cur r 0%N.
Lemma wrunc_from_shift (n : nat) (l : wside) (cur : Sym) (r : wside) (acc : N) :
  wrunc_from n l cur r acc
  = match wrunc_from n l cur r 0%N with
    | Some (s', K) => Some (s', (acc + K)%N)
    | None => None
    end.
Proof.
  gen l cur r acc.
  induction n as [|n IH]; intros l cur r acc; cbn [wrunc_from].
  - f_equal; f_equal; lia.
  - destruct (wsection l cur r) as [[[[l' c'] r'] k]|]; [|reflexivity].
    rewrite (IH l' c' r' (acc + N.of_nat k)%N),
            (IH l' c' r' (0 + N.of_nat k)%N).
    destruct (wrunc_from n l' c' r' 0%N) as [[s2 K2]|]; [|reflexivity].
    f_equal; f_equal; lia.
Qed.
Lemma wrunc_0 (l : wside) (cur : Sym) (r : wside) :
  wrunc 0 l cur r = Some ((l, cur, r), 0%N).
Proof. reflexivity. Qed.
Lemma wrunc_S (n : nat) (l : wside) (cur : Sym) (r : wside) :
  wrunc (S n) l cur r
  = match wsection l cur r with
    | Some (l', cur', r', k) =>
      match wrunc n l' cur' r' with
      | Some (s', K) => Some (s', (N.of_nat k + K)%N)
      | None => None
      end
    | None => None
    end.
Proof.
  unfold wrunc. cbn [wrunc_from].
  destruct (wsection l cur r) as [[[[l' c'] r'] k]|]; [|reflexivity].
  rewrite (wrunc_from_shift n l' c' r' (0 + N.of_nat k)%N).
  destruct (wrunc_from n l' c' r' 0%N) as [[s2 K2]|]; [|reflexivity].
  f_equal; f_equal; lia.
Qed.
Lemma wrunc_run (n : nat) (l : wside) (cur : Sym) (r : wside) s' K :
  wrunc n l cur r = Some (s', K) -> wrun n l cur r = Some s'.
Proof.
  gen l cur r s' K. induction n as [|n IH]; intros l cur r s' K H.
  - rewrite wrunc_0 in H. injection H as Hs HK. rewrite <- Hs. reflexivity.
  - rewrite wrunc_S in H. cbn [wrun].
    destruct (wsection l cur r) as [[[[l' c'] r'] k]|]; [|discriminate].
    destruct (wrunc n l' c' r') as [[s2 K2]|] eqn:F; [|discriminate].
    injection H as Hs HK. rewrite <- Hs.
    eapply IH, F.
Qed.
Theorem wrunc_sound (n : nat) (l : wside) (cur : Sym) (r : wside) s' K :
  wrunc n l cur r = Some (s', K) ->
  wconf l cur r =( N.to_nat K )=> wconf' s'.
Proof.
  gen l cur r s' K. induction n as [|n IH]; intros l cur r s' K H.
  - rewrite wrunc_0 in H. injection H as Hs HK.
    rewrite <- Hs, <- HK. apply multistep_0.
  - rewrite wrunc_S in H.
    destruct (wsection l cur r) as [[[[l' c'] r'] k]|] eqn:E; [|discriminate].
    destruct (wrunc n l' c' r') as [[s2 K2]|] eqn:F; [|discriminate].
    injection H as Hs HK.
    rewrite <- Hs.
    eapply cmul_trans_eq.
    + eapply wsection_sound, E.
    + eapply IH, F.
    + rewrite <- HK, N2Nat.inj_add, Nat2N.id. reflexivity.
Qed.
Lemma wrunc_add (a b : nat) (l : wside) (cur : Sym) (r : wside) :
  wrunc (a + b) l cur r
  = match wrunc a l cur r with
    | Some ((l1, cur1, r1), K1) =>
      match wrunc b l1 cur1 r1 with
      | Some (s2, K2) => Some (s2, (K1 + K2)%N)
      | None => None
      end
    | None => None
    end.
Proof.
  gen l cur r. induction a as [|a IH]; intros l cur r.
  - cbn [Nat.add]. rewrite wrunc_0.
    destruct (wrunc b l cur r) as [[s2 K2]|]; [|reflexivity].
    f_equal; f_equal; lia.
  - replace (S a + b)%nat with (S (a + b))%nat by lia.
    rewrite !wrunc_S.
    destruct (wsection l cur r) as [[[[l' c'] r'] k]|]; [|reflexivity].
    rewrite IH.
    destruct (wrunc a l' c' r') as [[[[l1 c1] r1] K1]|]; [|reflexivity].
    destruct (wrunc b l1 c1 r1) as [[s2 K2]|]; [|reflexivity].
    f_equal; f_equal; lia.
Qed.
Lemma wrunc_split (a b : nat) (l : wside) (cur : Sym) (r : wside)
      (l1 : wside) (c1 : Sym) (r1 : wside) (K1 : N) :
  wrunc a l cur r = Some ((l1, c1, r1), K1) ->
  wrunc (a + b) l cur r
  = match wrunc b l1 c1 r1 with
    | Some (s2, K2) => Some (s2, (K1 + K2)%N)
    | None => None
    end.
Proof. intros H. rewrite wrunc_add, H. reflexivity. Qed.
Lemma halt_at_guard_in (l r r0 r1 : wside) :
  wpop r = (1, r0) ->
  wpop r0 = (0, r1) ->
  halts_in tmB (wconf l 0 r) 2%nat.
Proof.
  intros H0 H1.
  unfold wconf.
  rewrite (wpop_dec r), H0; cbn [fst snd].
  rewrite (wpop_dec r0), H1; cbn [fst snd].
  eexists. split.
  - do 2 cstep.
    apply cmul_refl'; [reflexivity | simpl_tape; reflexivity].
  - reflexivity.
Qed.
Lemma wsection_none_cur (l : wside) (cur : Sym) (r : wside) :
  wsection l cur r = None -> cur = 0.
Proof.
  destruct cur; intros E; [reflexivity|].
  exfalso. unfold wsection in E.
  destruct (wpop l) as [l0 la] in E.
  destruct l0.
  - destruct (wpop1s la) as [m lb] in E;
      destruct (wpop lb) as [z lc] in E;
      destruct (wpop lc) as [c2 ld] in E; discriminate E.
  - destruct (wpop la) as [l1 lb] in E.
    destruct l1.
    + discriminate E.
    + destruct (wpop r) as [c2 rc] in E; discriminate E.
Qed.
Theorem wrunc_halts_in (n : nat) (l : wside) (cur : Sym) (r : wside)
        (l1 : wside) (c1 : Sym) (r1 : wside) (K : N) :
  wrunc n l cur r = Some ((l1, c1, r1), K) ->
  wsection l1 c1 r1 = None ->
  halts_in tmB (wconf l cur r) (N.to_nat K + 2).
Proof.
  intros HR HN.
  eapply halts_in_multistep.
  - exact (wrunc_sound _ _ _ _ _ _ HR).
  - cbn [wconf'].
    pose proof (wsection_none_cur _ _ _ HN) as Hc. rewrite Hc in HN |- *.
    destruct (wsection_none_guard _ _ HN) as (r2 & r3 & H2 & H3).
    exact (halt_at_guard_in l1 r1 r2 r3 H2 H3).
Qed.
Definition creach (d : cost) (u v : Q * tape) : Prop :=
  exists k, cin k d /\ u =( k )=> v.
Lemma creach_refl (u : Q * tape) : creach czero u u.
Proof. exists 0%nat. split; [exact cin_czero | apply multistep_0]. Qed.
Lemma creach_cx (K : N) (u v : Q * tape) :
  u =( N.to_nat K )=> v -> creach (cx K) u v.
Proof. intros H. exists (N.to_nat K). split; [apply cin_cx | exact H]. Qed.
Lemma creach_trans (d1 d2 : cost) (u v w : Q * tape) :
  creach d1 u v -> creach d2 v w -> creach (cadd d1 d2) u w.
Proof.
  intros [k1 [Hk1 Hs1]] [k2 [Hk2 Hs2]].
  exists (k1 + k2)%nat. split.
  - apply cin_add; assumption.
  - eapply multistep_trans; eauto.
Qed.
Lemma creach_widen (lo hi lo' hi' : N) (u v : Q * tape) :
  (lo' <= lo)%N -> (hi <= hi')%N ->
  creach (lo, hi) u v -> creach (lo', hi') u v.
Proof.
  intros Hl Hh [k [Hk Hs]]. exists k. split; [|exact Hs].
  eapply cin_widen; eassumption.
Qed.
Lemma creach_widen' (d d' : cost) (u v : Q * tape) :
  (fst d' <= fst d)%N -> (snd d <= snd d')%N ->
  creach d u v -> creach d' u v.
Proof.
  intros Hl Hh [k [Hk Hs]]. exists k. split; [|exact Hs].
  eapply cin_widen'; eassumption.
Qed.
Theorem creach_halts_in (d : cost) (u v : Q * tape) (m : nat) :
  creach d u v -> halts_in tmB v m ->
  exists k, cin k d /\ halts_in tmB u (k + m).
Proof.
  intros [k [Hk Hs]] Hh.
  exists k. split; [exact Hk|].
  eapply halts_in_multistep; eassumption.
Qed.
Lemma creach_of_wrunc (n : nat) (l : wside) (cur : Sym) (r : wside) s' K :
  wrunc n l cur r = Some (s', K) ->
  creach (cx K) (wconf l cur r) (wconf' s').
Proof. intros H. apply creach_cx. eapply wrunc_sound, H. Qed.
Open Scope N_scope.
Open Scope bool_scope.
Definition bg : Type := (N * N * N)%type.
Definition word : Type := list bg.
Definition gO (g : bg) : N := let '(o,_,_) := g in o.
Definition gZ (g : bg) : N := let '(_,z,_) := g in z.
Definition gC (g : bg) : N := let '(_,_,c) := g in c.
Definition subst_at (i k : nat) (rep : word) (w : word) : word :=
  firstn i w ++ rep ++ skipn (i + k) w.
Definition wat (w : word) (i : nat) : option bg := nth_error w i.
Definition is_col (g : bg) : bool := (gZ g =? 2) && (2 <=? gO g).
Definition is_cmf (g : bg) : bool :=
  (gZ g =? 2) && (gC g =? 1) && (5 <=? gO g)
  && negb (gO g =? 8) && negb (gO g =? 12).
Definition w42 (g : bg) : bool := (gO g =? 4) && (gZ g =? 2).
Fixpoint normalize (w : word) : word :=
  match w with
  | [] => []
  | g :: t =>
      match normalize t with
      | [] => [g]
      | g2 :: t2 =>
          if (gO g =? gO g2) && (gZ g =? gZ g2)
          then (gO g, gZ g, gC g + gC g2) :: t2
          else g :: g2 :: t2
      end
  end.
Fixpoint find_active_s (w : word) (i : nat) : option nat :=
  match w with
  | [] => None
  | g :: t =>
      if (gZ g =? 1) || (3 <=? gZ g) then Some i
      else find_active_s t (S i)
  end.
Definition find_active (w : word) (start : nat) : option nat :=
  find_active_s (skipn start w) start.
Fixpoint tick_target_s (w : word) (i : nat) : option nat :=
  match w with
  | [] => None
  | g :: t =>
      if (gZ g =? 1) || (3 <=? gZ g) then Some i
      else if is_cmf g then Some i
      else if is_col g then tick_target_s t (S i)
      else None
  end.
Definition tick_target (w : word) (j : nat) : option nat :=
  tick_target_s (skipn j w) j.
Inductive ckind : Type := STD | JMP.
Inductive res : Type :=
  | ROk   (w : word) (f : N)
  | RHalt
  | RBad.
Definition far_end_merge_fire (w : word) (f : N) (i : nat) : res :=
  match wat w i with
  | Some (o, _, _) =>
      if f =? 3 then ROk (subst_at i 1 [(o-1,1,1); (3,1,1)] w) 4
      else if f =? 2 then ROk (subst_at i 1 [(o-1,1,1); (5,2,1)] w) 4
      else if f =? 4 then ROk (subst_at i 1 [(o-1,1,1); (3,2,1)] w) f
      else RBad
  | None => RBad
  end.
Fixpoint dtb_scan (w : word) (s : nat) (best : option nat) : option nat :=
  match w with
  | [] => best
  | g :: t =>
      dtb_scan t (S s)
        (if (gO g =? 8) && (gZ g =? 2) && (gC g =? 1) then Some s else best)
  end.
Definition debris_to_blank (w : word) (f : N) : res :=
  if f =? 4 then
    match dtb_scan w O None with
    | Some s =>
        match wat w (S s), wat w (S (S s)) with
        | Some (o1,z1,c1), Some (o2,z2,c2) =>
            if (o1 =? 4) && (z1 =? 2) && (o2 =? 3) && (z2 =? 2) && (c2 =? 1)
               && (Nat.eqb (length w) (S (S (S s)))
                   || match wat w (S (S (S s))) with
                      | Some (o3,z3,_) =>
                          (o3 =? 4) && (z3 =? 2)
                          && Nat.eqb (length w) (S (S (S (S s))))
                      | None => false
                      end)
            then
              let tail :=
                match wat w (S (S (S s))) with
                | Some (o3,z3,c3) => [(o3, z3, c3 + 1)]
                | None => [(4,2,1)]
                end in
              let mid := if c1 =? 1 then [] else [(o1, z1, c1 - 1)] in
              ROk (subst_at s (length w - s)
                     ([(7,1,1); (3,2,1)] ++ mid ++ [(4,1,1)] ++ tail) w) f
            else if forallb w42 (skipn (S s) w)
                 then ROk (subst_at s 1 [(7,1,1); (3,2,1)] w) f
                 else RBad
        | _, _ =>
            if forallb w42 (skipn (S s) w)
            then ROk (subst_at s 1 [(7,1,1); (3,2,1)] w) f
            else RBad
        end
    | None => RBad
    end
  else if 5 <=? f then
    if forallb (fun g => negb (gO g =? 1)) w
    then ROk (w ++ [(f - 1, 1, 1)]) 3
    else RBad
  else if f =? 3 then
    match dtb_scan w O None with
    | Some s =>
        match wat w (S s) with
        | Some (o1,z1,c1) =>
            if (o1 =? 4) && (z1 =? 2) && (1 <? c1)
               && forallb w42 (skipn (S (S s)) w)
            then ROk (subst_at s 2
                        [(7,1,1); (3,2,1); (o1,z1,c1-1)] w ++ [(4,1,1)]) 4
            else RBad
        | None => RBad
        end
    | None => RBad
    end
  else RBad.
Fixpoint leaf_act (s : word) (f : N) {struct s} : option (word * N) :=
  match s with
  | (X,2,1) :: rest =>
      if (5 <=? X) && negb (X =? 8) && negb (X =? 12) then
        match rest with
        | [] =>
            if f =? 3 then Some ([(X-1,1,1); (3,1,1)], 4)
            else if f =? 2 then Some ([(X-1,1,1); (5,2,1)], 4)
            else if f =? 4 then Some ([(X-1,1,1); (3,2,1)], f)
            else None
        | (on,zn,cn) :: t2 =>
            if on =? 1 then None
            else if (on =? 3) && (zn =? 2) && (cn =? 1) && (f =? 4) then
              (match t2 with
               | [(o2,z2,c2)] =>
                   if (o2 =? 4) && (z2 =? 2)
                   then Some ((X-1,1,1) :: (3,1,1) :: [(4,2,c2+1)], f)
                   else None
               | [] => Some ((X-1,1,1) :: (3,1,1) :: [(4,2,1)], f)
               | _ => None
               end)
            else if (on =? 4) && (zn =? 2) then
              (match t2 with
               | [(o2,z2,c2); (o3,z3,c3)] =>
                   if (1 <=? cn) && (o2 =? 3) && (z2 =? 2) && (c2 =? 1)
                      && (o3 =? 4) && (z3 =? 2) && (f =? 4)
                   then Some ((X-1,1,1) :: (3,2,1)
                              :: (if cn =? 1 then [] else [(on,zn,cn-1)])
                              ++ [(4,1,1); (o3,z3,c3+1)], f)
                   else None
               | [] =>
                   if f =? 4 then Some ((X-1,1,1) :: (3,2,1) :: rest, f)
                   else None
               | _ => None
               end)
            else if (X =? 6) && (on =? 2) && (zn =? 2) && (cn =? 1)
                    && (f =? 4)
                    && match t2 with
                       | [(o2,z2,_)] => (o2 =? 4) && (z2 =? 2)
                       | _ => false
                       end then
              (match t2 with
               | [(o2,z2,c2)] => Some ((5,1,1) :: (5,2,1) :: [(o2,z2,c2+1)], f)
               | _ => None
               end)
            else if (zn =? 1)
                    || ((zn =? 2) && (cn =? 1) && (5 <=? on)
                        && negb (on =? 8) && negb (on =? 12)) then
              (match leaf_act rest f with
               | Some (s', f') => Some ((X,2,1) :: s', f')
               | None => None
               end)
            else None
        end
      else None
  | (oa,1,oc) :: t =>
      if 2 <=? oc then
        if 2 <=? oa
        then Some ((oa,1,1) :: (oa-1,1,1)
                     :: (if 2 <? oc then [(oa,1,oc-2)] else []) ++ t, f)
        else None
      else if negb (oc =? 1) || negb (2 <=? oa) then None
      else
      match t with
      | (ob, zb, cb) :: t2 =>
          if (zb =? 2) && negb (ob =? 8)
             && (negb (ob =? 4)
                 || ((cb =? 1)
                     && match t2 with
                        | (o2,z2,_) :: _ =>
                            negb (((o2 =? 4) || (o2 =? 8)) && (z2 =? 2))
                        | [] => true
                        end))
          then
            if (ob =? 5) && (cb =? 1)
               && match t2 with
                  | (o2,z2,_) :: _ => (o2 =? 4) && (z2 =? 2)
                  | [] => false
                  end
            then match t2 with
                 | (o2,z2,c2) :: t3 => Some ((oa,1,1) :: (o2,z2,c2+1) :: t3, f)
                 | [] => None
                 end
            else if ob =? 1 then
              (if cb =? 1 then Some ((oa,3,1) :: t2, f) else None)
            else
              (if (cb =? 1) && (2 <=? ob)
               then Some ((oa,1,1) :: (ob-1,zb,1) :: t2, f) else None)
          else if (ob =? 8) && (zb =? 2) && (cb =? 1) then
            Some ((oa,1,1) :: (7,2,1) :: t2, f)
          else if (ob =? 4) && (zb =? 2) then
            if cb =? 1
            then Some ((oa,1,1) :: (3,2,1) :: t2, f)
            else (if 2 <=? cb
                  then Some ((oa,1,1) :: (3,2,1) :: (ob,zb,cb-1) :: t2, f)
                  else None)
          else if zb =? 1 then
            if 2 <=? cb then
              (if 2 <=? ob
               then Some ((oa,1,1) :: (ob-1,1,1) :: (ob,1,cb-1) :: t2, f)
               else None)
            else if ob =? 1 then
              (if cb =? 1 then Some ((oa,2,1) :: t2, f) else None)
            else
              (if (cb =? 1) && (2 <=? ob)
               then Some ((oa,1,1) :: (ob-1,zb,cb) :: t2, f)
               else None)
          else if (3 <=? zb) && (cb =? 1) then
            if ob =? 1 then Some ((oa,zb+1,1) :: t2, f)
            else (if 2 <=? ob
                  then Some ((oa,1,1) :: (ob-1,zb,cb) :: t2, f)
                  else None)
          else None
      | [] =>
          if 2 <=? f then Some ([(oa,1,1)], f - 1)
          else if f =? 1 then Some ([], oa)
          else None
      end
  | _ => None
  end.
Fixpoint deliver_tick (fuel : nat) (w : word) (f : N) (i : nat)
                      (via_debris : bool) {struct fuel} : res :=
  match fuel with O => RBad | S fuel =>
  match wat w i with
  | None => RBad
  | Some (o, z, c) =>
    if (z =? 1) && (2 <=? o) then
      match leaf_act (skipn i w) f with
      | Some (s', f') => ROk (firstn i w ++ s') f'
      | None => RBad
      end
    else if 3 <=? z then
      (if c =? 1 then fire fuel w f i via_debris else RBad)
    else if (z =? 2) && (5 <=? o) && negb (o =? 8) && negb (o =? 12) then
      chain_merge_advance fuel w f i
    else RBad
  end
  end
with fire (fuel : nat) (w : word) (f : N) (i : nat)
          (via_debris : bool) {struct fuel} : res :=
  match fuel with O => RBad | S fuel =>
  match wat w i with
  | None => RBad
  | Some (o, z, _) =>
    let nxt := wat w (S i) in
    if 4 <=? z then
      match nxt with
      | Some (on, zn, cn) =>
          if negb (z =? 4) then RBad else
          if (o =? 4) && (on =? 4) && (zn =? 2) && (1 <=? cn)
             && match wat w (Nat.pred i), wat w (Nat.pred (Nat.pred i)) with
                | Some (o1,z1,_), Some (o2,z2,c2) =>
                    Nat.leb 2 i && (o1 =? 4) && (z1 =? 2)
                    && (o2 =? 8) && (z2 =? 2) && (c2 =? 1)
                | _, _ => false
                end
          then match wat w (Nat.pred i) with
               | Some lvlA =>
                   let rep := [(7,1,1); (3,2,1); lvlA; (8,2,1)]
                              ++ (if 1 <? cn then [(4,2,cn-1)] else []) in
                   ROk (subst_at (Nat.pred (Nat.pred i)) 4 rep w) f
               | None => RBad
               end
          else if (4 <? o) && (on =? 4) && (zn =? 2) && (1 <=? cn) then
            let rep := (o-1,1,1) :: (7,2,1)
                       :: (if 1 <? cn then [(4,2,cn-1)] else []) in
            ROk (subst_at i 2 rep w) f
          else RBad
      | None =>
          if o =? 4 then
            let far := if 5 <=? z then [(4,z-4,1)] else [] in
            let f'  := if 5 <=? z then f else f + 4 in
            match wat w (Nat.pred i), wat w (Nat.pred (Nat.pred i)) with
            | Some (o1,z1,c1), Some (o2,z2,c2) =>
                if Nat.leb 2 i && (o1 =? 4) && (z1 =? 2)
                   && (o2 =? 8) && (z2 =? 2) && (1 <=? c2)
                then ROk (subst_at (Nat.pred (Nat.pred i)) 3
                            ((if 1 <? c2 then [(8,2,c2-1)] else [])
                             ++ [(7,1,1); (3,2,1); (o1,z1,c1)] ++ far) w) f'
                else if Nat.leb 1 i && (o1 =? 8) && (z1 =? 2) && (1 <=? c1)
                then ROk (subst_at (Nat.pred i) 2
                            ((if 1 <? c1 then [(8,2,c1-1)] else [])
                             ++ [(7,1,1); (3,2,1)] ++ far) w) f'
                else RBad
            | Some (o1,z1,c1), None =>
                if Nat.leb 1 i && (o1 =? 8) && (z1 =? 2) && (1 <=? c1)
                then ROk (subst_at (Nat.pred i) 2
                            ((if 1 <? c1 then [(8,2,c1-1)] else [])
                             ++ [(7,1,1); (3,2,1)] ++ far) w) f'
                else RBad
            | _, _ => RBad
            end
          else RBad
      end
    else
    if (o =? 3) && match nxt, wat w (Nat.pred i), wat w (Nat.pred (Nat.pred i)) with
                   | Some (on,zn,cn), Some (o1,z1,c1), Some (o2,z2,c2) =>
                       (on =? 4) && (zn =? 2) && Nat.leb 2 i
                       && (o1 =? 4) && (z1 =? 2)
                       && (o2 =? 8) && (z2 =? 2) && (c2 =? 1)
                       && (1 <=? c1) && (1 <=? cn)
                       && Nat.eqb (S (S i)) (length w)
                       && ((f =? 0) || (f =? 4))
                   | _, _, _ => false
                   end
    then
      match wat w (Nat.pred i), nxt with
      | Some (_,_,V), Some (_,_,G) =>
          let rep := [(7,1,1); (3,2,1)]
                     ++ (if 1 <? V then [(4,2,V-1)] else [])
                     ++ [(4,1,1); (7,1,1); (3,2,1)]
                     ++ (if 1 <? G then [(4,2,G-1)] else []) in
          ROk (subst_at (Nat.pred (Nat.pred i)) 4 rep w) f
      | _, _ => RBad
      end
    else if o =? 4 then renewal fuel w f i via_debris
    else if negb (5 <=? o) then RBad
    else
    match nxt with
    | Some (on, zn, cn) =>
        if (on =? 4) && (zn =? 2) && (1 <=? cn)
           && Nat.eqb (S (S i)) (length w) && (f =? 4) then
          let rep := (o-1,1,1) :: (6,1,1) :: (3,2,1)
                     :: (if 1 <? cn then [(4,2,cn-1)] else []) in
          ROk (subst_at i 2 rep w) f
        else if (on =? 4) && (zn =? 2) then
          if negb (1 <=? cn) then RBad else
          let w2 := subst_at i 2
                      ((o-1,1,1) :: (7,2,1)
                       :: (if 1 <? cn then [(4,2,cn-1)] else [])) w in
          let base := if 1 <? cn then S (S (S i)) else S (S i) in
          match tick_target w2 base with
          | Some j =>
              match wat w2 j with
              | Some g2 =>
                  if is_cmf g2
                  then chain_merge_advance fuel w2 f j
                  else match deliver_tick fuel w2 f j true with
                       | RHalt => RBad
                       | r2 => r2
                       end
              | None => RBad
              end
          | None => if forallb is_col (skipn base w2)
                    then debris_to_blank w2 f else RBad
          end
        else if (on =? 8) && (zn =? 2) && (cn =? 1) then
          let w2 := subst_at i 2 [(o-1,1,1); (11,2,1)] w in
          match tick_target w2 (S (S i)) with
          | Some j =>
              match deliver_tick fuel w2 f j true with
              | RHalt => RBad | r2 => r2 end
          | None => if forallb is_col (skipn (S (S i)) w2)
                    then debris_to_blank w2 f else RBad
          end
        else if (zn =? 1) && (cn =? 1) && (1 <=? on)
                && Nat.eqb (S (S i)) (length w) then
          (if 1 <=? f
           then ROk (subst_at i 2 [(o-1,1,1); (on+3,1,1)] w) (f - 1)
           else ROk (subst_at i 2 [(o-1,1,1); (on+2,1,1)] w) 3)
        else if (zn =? 3) && (cn =? 1) && (1 <=? on)
                && Nat.eqb (S (S (S i))) (length w)
                && match wat w (S (S i)) with
                   | Some (o2,z2,c2) => (o2 =? 4) && (z2 =? 2) && (1 <=? c2)
                   | None => false
                   end
        then
          match wat w (S (S i)) with
          | Some (_,_,c2) =>
              let hd := [(o-1,1,1); (on+2,1,1)] in
              let lvl := if 2 <? c2 then [(4,2,c2-2)] else [] in
              if f =? 4 then
                ROk (subst_at i 3 (hd ++ [(6,1,1); (3,2,1)]
                       ++ (if 1 <? c2 then [(4,2,c2-1)] else [])) w) f
              else if 5 <=? f then
                ROk (subst_at i 3 (hd ++ [(7,2,1)]
                       ++ (if 1 <? c2 then [(4,2,c2-1)] else [])
                       ++ [(f-1,1,1)]) w) 3
              else if f =? 3 then
                ROk (subst_at i 3 (hd ++ [(6,1,1)]
                       ++ (if c2 =? 1 then [(3,1,1)]
                           else [(3,2,1)] ++ lvl ++ [(4,1,1)])) w) 4
              else if f =? 2 then
                ROk (subst_at i 3 (hd ++ [(6,1,1)]
                       ++ (if c2 =? 1 then [(5,2,1)]
                           else [(3,2,1)] ++ lvl ++ [(6,2,1)])) w) 4
              else if (f =? 0) && (2 <=? c2) then
                ROk (subst_at i 3 (hd ++ [(6,1,1); (3,2,1)] ++ lvl) w) 4
              else RBad
          | None => RBad
          end
        else if (zn =? 1) && (cn =? 1) && (1 <=? on)
                && match wat w (S (S i)) with
                   | Some (o2,z2,c2) => (o2 =? 4) && (z2 =? 2) && (1 <=? c2)
                   | None => false
                   end
        then
          match wat w (S (S i)) with
          | Some (o2,z2,c2) =>
              let rep := [(o-1,1,1); (on+3,1,1); (3,2,1)]
                         ++ (if 1 <? c2 then [(o2,z2,c2-1)] else []) in
              ROk (subst_at i 3 rep w) f
          | None => RBad
          end
        else if (zn =? 1) && (2 <=? cn) && (1 <=? on) then
          let rep := [(o-1,1,1); (on+3,1,1); (on-1,1,1)]
                     ++ (if 2 <? cn then [(on,1,cn-2)] else []) in
          ROk (subst_at i 2 rep w) f
        else if (zn =? 1) && (cn =? 1) && (1 <=? on)
                && match wat w (S (S i)) with
                   | Some (o2,z2,c2) => (z2 =? 1) && (c2 =? 1) && (1 <=? o2)
                   | None => false
                   end
        then
          match wat w (S (S i)) with
          | Some (k,_,_) =>
              if k =? 1
              then ROk (subst_at i 3 [(o-1,1,1); (on+3,2,1)] w) f
              else ROk (subst_at i 3
                          [(o-1,1,1); (on+3,1,1); (k-1,1,1)] w) f
          | None => RBad
          end
        else if (zn =? 1) && (cn =? 1) && (1 <=? on)
                && match wat w (S (S i)) with
                   | Some (o2,z2,c2) =>
                       (z2 =? 2) && (1 <=? o2) && (o2 <=? 3) && (c2 =? 1)
                   | None => false
                   end
        then
          match wat w (S (S i)) with
          | Some (b,_,_) =>
              if b =? 1
              then ROk (subst_at i 3 [(o-1,1,1); (on+3,3,1)] w) f
              else ROk (subst_at i 3
                          [(o-1,1,1); (on+3,1,1); (b-1,2,1)] w) f
          | None => RBad
          end
        else RBad
    | None =>
        if 2 <=? f
        then ROk (subst_at i 1 [(o-1,1,1); (f+2,1,1)] w) 3
        else RBad
    end
  end
  end
with renewal (fuel : nat) (w : word) (f : N) (i : nat)
             (via_debris : bool) {struct fuel} : res :=
  match fuel with O => RBad | S fuel =>
  let n := length w in
  let nxt := wat w (S i) in
  let ctx1 := wat w (Nat.pred i) in
  let ctx2 := wat w (Nat.pred (Nat.pred i)) in
  let spacer_ok :=
    Nat.leb 2 i
    && match ctx1, ctx2 with
       | Some (o1,z1,_), Some (o2,z2,c2) =>
           (o1 =? 4) && (z1 =? 2) && (z2 =? 2) && (c2 =? 1)
           && ((o2 =? 8) || (o2 =? 12))
       | _, _ => false
       end in
  match nxt with
  | Some (on, zn, cn) =>
      if (zn =? 3) && (cn =? 1) && Nat.eqb (S (S i)) n then
        if negb (1 <=? on) then RBad else
        let far := if 1 <=? f then [(f+2,1,1)] else [] in
        match ctx1, ctx2 with
        | Some (o1,z1,c1), Some (o2,z2,c2) =>
            if Nat.leb 2 i && (o1 =? 4) && (z1 =? 2)
               && (o2 =? 8) && (z2 =? 2) && (1 <=? c2)
            then ROk (subst_at (Nat.pred (Nat.pred i)) 4
                       ((if 1 <? c2 then [(8,2,c2-1)] else [])
                        ++ [(7,1,1); (3,2,1); (o1,z1,c1); (on+3,1,1)]
                        ++ far) w) 3
            else if Nat.leb 1 i && (o1 =? 8) && (z1 =? 2) && (1 <=? c1)
            then ROk (subst_at (Nat.pred i) 3
                       ((if 1 <? c1 then [(8,2,c1-1)] else [])
                        ++ [(7,1,1); (3,2,1); (on+3,1,1)] ++ far) w) 3
            else RBad
        | Some (o1,z1,c1), None =>
            if Nat.leb 1 i && (o1 =? 8) && (z1 =? 2) && (1 <=? c1)
            then ROk (subst_at (Nat.pred i) 3
                       ((if 1 <? c1 then [(8,2,c1-1)] else [])
                        ++ [(7,1,1); (3,2,1); (on+3,1,1)] ++ far) w) 3
            else RBad
        | _, _ => RBad
        end
      else if (zn =? 1) && (cn =? 1) && spacer_ok
              && match wat w (S (S i)) with
                 | Some (o2,z2,c2) =>
                     (z2 =? 2) && (c2 =? 1) && (o2 <=? 3)
                 | None => false
                 end
      then
        match ctx2, ctx1, wat w (S (S i)) with
        | Some (h0,_,_), Some lvlA, Some (b,_,_) =>
            let last :=
              if b =? 1 then [(on+4,3,1)] else [(on+4,1,1); (b-1,2,1)] in
            ROk (subst_at (Nat.pred (Nat.pred i)) 5
                   ([(h0-1,1,1); (3,2,1); lvlA] ++ last) w) f
        | _, _, _ => RBad
        end
      else if (zn =? 1) && (cn =? 1) && spacer_ok
              && match wat w (S (S i)) with
                 | Some (_,z2,c2) => (z2 =? 1) && (c2 =? 1)
                 | None => false
                 end
      then
        match ctx2, ctx1, wat w (S (S i)) with
        | Some (h0,_,_), Some lvlA, Some (k,_,_) =>
            let last :=
              if k =? 1 then [(on+4,2,1)] else [(on+4,1,1); (k-1,1,1)] in
            ROk (subst_at (Nat.pred (Nat.pred i)) 5
                   ([(h0-1,1,1); (3,2,1); lvlA] ++ last) w) f
        | _, _, _ => RBad
        end
      else if (zn =? 3) && (cn =? 1) && (1 <=? on)
              && Nat.ltb (S (S i)) n && spacer_ok
              && Nat.eqb (S (S (S i))) n
              && match wat w (S (S i)) with
                 | Some (o2,z2,c2) => (o2 =? 4) && (z2 =? 2) && (1 <=? c2)
                 | None => false
                 end
      then
        match ctx2, ctx1, wat w (S (S i)) with
        | Some (h0,_,_), Some lvlA, Some (_,_,c2) =>
            let hd  := [(h0-1,1,1); (3,2,1); lvlA; (on+3,1,1)] in
            let one := if 1 <? c2 then [(4,2,c2-1)] else [] in
            let lvl := if 2 <? c2 then [(4,2,c2-2)] else [] in
            let at2 := subst_at (Nat.pred (Nat.pred i)) 5 in
            if (f =? 4) || (f =? 0) then
              ROk (at2 (hd ++ [(6,1,1); (3,2,1)] ++ one) w) f
            else if 5 <=? f then
              ROk (at2 (hd ++ [(7,2,1)] ++ one ++ [(f-1,1,1)]) w) 3
            else if f =? 3 then
              ROk (at2 (hd ++ [(6,1,1)]
                        ++ (if c2 =? 1 then [(3,1,1)]
                            else [(3,2,1)] ++ lvl ++ [(4,1,1)])) w) 4
            else if f =? 2 then
              ROk (at2 (hd ++ [(6,1,1)]
                        ++ (if c2 =? 1 then [(5,2,1)]
                            else [(3,2,1)] ++ lvl ++ [(6,2,1)])) w) 4
            else RBad
        | _, _, _ => RBad
        end
      else if (on =? 8) && (zn =? 2) && (cn =? 1) then
        match ctx1, ctx2 with
        | Some (o1,z1,c1), Some (o2,z2,c2) =>
            if Nat.leb 2 i && (o1 =? 4) && (z1 =? 2)
               && (o2 =? 8) && (z2 =? 2)
            then
              let w2 := subst_at (Nat.pred (Nat.pred i)) 4
                          [(7,1,1); (3,2,1); (o1,z1,c1); (12,2,1)] w in
              match tick_target w2 (S (S i)) with
              | Some j =>
              match deliver_tick fuel w2 f j true with
              | RHalt => RBad | r2 => r2 end
              | None => debris_to_blank w2 f
              end
            else RBad
        | _, _ => RBad
        end
      else if (on =? 4) && (zn =? 2) && (1 <=? cn) then
        if Nat.eqb (S (S i)) n && (f =? 4) && Nat.leb 1 i
           && match ctx1 with
              | Some (o1,z1,c1) => (z1 =? 2) && (c1 =? 1) && (5 <=? o1)
              | None => false
              end
        then
          match ctx1 with
          | Some (h,_,_) =>
              ROk (subst_at (Nat.pred i) 3
                     ([(h-1,1,1); (3,2,1); (7,1,1); (3,2,1)]
                      ++ (if 1 <? cn then [(4,2,cn-1)] else [])) w) f
          | None => RBad
          end
        else if Nat.eqb (S (S i)) n && (f =? 4) then
          if spacer_ok then
            match ctx2, ctx1 with
            | Some (h0,_,_), Some lvlA =>
                ROk (subst_at (Nat.pred (Nat.pred i)) 4
                       ([(h0-1,1,1); (3,2,1); lvlA; (7,1,1); (3,2,1)]
                        ++ (if 1 <? cn then [(4,2,cn-1)] else [])) w) f
            | _, _ => RBad
            end
          else RBad
        else
          if spacer_ok then
            match ctx2, ctx1 with
            | Some (h0,_,_), Some lvlA =>
                let w2 := subst_at (Nat.pred (Nat.pred i)) 4
                            ([(h0-1,1,1); (3,2,1); lvlA; (8,2,1)]
                             ++ (if 1 <? cn then [(4,2,cn-1)] else [])) w in
                let base := if 1 <? cn then S (S (S i)) else S (S i) in
                match tick_target w2 base with
                | Some j =>
                    match deliver_tick fuel w2 f j true with
                    | RHalt => RBad | r2 => r2 end
                | None => debris_to_blank w2 f
                end
            | _, _ => RBad
            end
          else RBad
      else RBad
  | None =>
      let far := if 1 <=? f then [(f+3,1,1)] else [] in
      let f'  := if 1 <=? f then 3 else 4 in
      match ctx1, ctx2 with
      | Some (o1,z1,c1), Some (o2,z2,c2) =>
          if Nat.leb 1 i && (o1 =? 8) && (z1 =? 2) && (1 <=? c1)
          then ROk (subst_at (Nat.pred i) 2
                      ((if 1 <? c1 then [(8,2,c1-1)] else [])
                       ++ [(7,1,1); (3,2,1)] ++ far) w) f'
          else if Nat.leb 2 i && (o1 =? 4) && (z1 =? 2)
                  && (o2 =? 8) && (z2 =? 2) && (1 <=? c2)
          then ROk (subst_at (Nat.pred (Nat.pred i)) 3
                      ((if 1 <? c2 then [(8,2,c2-1)] else [])
                       ++ [(7,1,1); (3,2,1); (o1,z1,c1)] ++ far) w) f'
          else RBad
      | Some (o1,z1,c1), None =>
          if Nat.leb 1 i && (o1 =? 8) && (z1 =? 2) && (1 <=? c1)
          then ROk (subst_at (Nat.pred i) 2
                      ((if 1 <? c1 then [(8,2,c1-1)] else [])
                       ++ [(7,1,1); (3,2,1)] ++ far) w) f'
          else RBad
      | _, _ => RBad
      end
  end
  end
with chain_merge_advance (fuel : nat) (w : word) (f : N) (i : nat)
                         {struct fuel} : res :=
  match fuel with O => RBad | S fuel =>
  match wat w i with
  | None => RBad
  | Some (o, z, c) =>
      if Nat.eqb (S i) (length w) then
        (if c =? 1 then far_end_merge_fire w f i else RBad)
      else
      match wat w (S i) with
      | None => RBad
      | Some (on, zn, cn) =>
          if on =? 1 then
            (if (1 <=? zn) && (1 <=? cn) then RHalt else RBad)
          else if (c =? 1) && (5 <=? o) && (on =? 3) && (zn =? 2) && (cn =? 1)
                  && (f =? 4)
                  && (Nat.eqb (length w) (S (S i))
                      || match wat w (S (S i)) with
                         | Some (o2,z2,_) =>
                             (o2 =? 4) && (z2 =? 2)
                             && Nat.eqb (length w) (S (S (S i)))
                         | None => false
                         end) then
            let tail :=
              match wat w (S (S i)) with
              | Some (o2,z2,c2) =>
                  if (o2 =? 4) && (z2 =? 2) then [(4,2,c2+1)] else []
              | None => []
              end in
            let klen :=
              match wat w (S (S i)) with
              | Some (o2,z2,_) =>
                  if (o2 =? 4) && (z2 =? 2) then 3%nat else 2%nat
              | None => 2%nat
              end in
            let mid :=
              match wat w (S (S i)) with
              | Some (o2,z2,_) =>
                  if (o2 =? 4) && (z2 =? 2) then []
                  else [(4,2,1)]
              | None => [(4,2,1)]
              end in
            ROk (subst_at i klen
                   ([(o-1,1,1); (3,1,1)] ++ mid ++ tail) w) f
          else if (c =? 1) && (5 <=? o) && (on =? 4) && (zn =? 2) && (f =? 4)
          then
            let orphan :=
              match wat w (S (S i)), wat w (S (S (S i))) with
              | Some (o2,z2,c2), Some (o3,z3,_) =>
                  (o2 =? 3) && (z2 =? 2) && (c2 =? 1)
                  && (o3 =? 4) && (z3 =? 2) && (1 <=? cn)
                  && Nat.eqb (length w) (S (S (S (S i))))
              | _, _ => false
              end in
            if orphan then
              match wat w (S (S (S i))) with
              | Some (o3,z3,c3) =>
                  let midlvl := if cn =? 1 then [] else [(on,zn,cn-1)] in
                  ROk (subst_at i 4
                         ([(o-1,1,1); (3,2,1)] ++ midlvl
                          ++ [(4,1,1); (o3,z3,c3+1)]) w) f
              | None => RBad
              end
            else if forallb w42 (skipn (S (S i)) w) then
              ROk (subst_at i 1 [(o-1,1,1); (3,2,1)] w) f
            else RBad
          else if (c =? 1) && (o =? 6) && (on =? 2) && (zn =? 2) && (cn =? 1)
                  && (f =? 4)
                  && match wat w (S (S i)) with
                     | Some (o2,z2,_) =>
                         (o2 =? 4) && (z2 =? 2)
                         && Nat.eqb (length w) (S (S (S i)))
                     | None => false
                     end
          then
            match wat w (S (S i)) with
            | Some (o2,z2,c2) =>
                ROk (subst_at i 3 [(5,1,1); (5,2,1); (o2,z2,c2+1)] w) f
            | None => RBad
            end
          else if zn =? 1 then
            match deliver_tick fuel w f (S i) false with
            | RHalt => RBad | r => r end
          else if (3 <=? zn) && (cn =? 1) then
            match deliver_tick fuel w f (S i) true with
            | RHalt => RBad | r => r end
          else if (zn =? 2) && (cn =? 1) && (5 <=? on)
                  && negb (on =? 8) && negb (on =? 12)
          then
            match chain_merge_advance fuel w f (S i) with
            | RHalt => RBad | r => r end
          else RBad
      end
  end
  end.
Fixpoint seek (s : word) : word * word :=
  match s with
  | g :: t =>
      if is_col g && negb (is_cmf g) && (3 <=? gO g)
      then let '(c, r) := seek t in (g :: c, r)
      else ([], s)
  | [] => ([], [])
  end.
Fixpoint last2 (l : word) : option (word * bg * bg) :=
  match l with
  | [a; b] => Some ([], a, b)
  | g :: t =>
      match last2 t with
      | Some (ini, a, b) => Some (g :: ini, a, b)
      | None => None
      end
  | [] => None
  end.
Definition lawR_seg (cols : word) (B : N) : option word :=
  match last2 cols with
  | Some (ini, (gao,gaz,gac), (gbo,gbz,gbc)) =>
      if (gao =? 8) && (gaz =? 2) && (gac =? 1)
         && (gbo =? 4) && (gbz =? 2) && (1 <=? gbc)
      then Some (ini ++ [(7,1,1); (3,2,1); (4,2,gbc); (7,1,1); (3,2,1)]
                     ++ (if 1 <? B then [(4,2,B-1)] else []))
      else if (gbo =? 8) && (gbz =? 2) && (gbc =? 1)
      then Some (ini ++ [(gao,gaz,gac); (7,1,1); (3,2,1); (7,1,1); (3,2,1)]
                     ++ (if 1 <? B then [(4,2,B-1)] else []))
      else None
  | None => None
  end.
Definition endR_seg (cols : word) (f : N) : option word :=
  match last2 cols with
  | Some (ini, (gao,gaz,gac), (gbo,gbz,gbc)) =>
      if (gao =? 8) && (gaz =? 2) && (gac =? 1)
         && (gbo =? 4) && (gbz =? 2) && (1 <=? gbc) && (2 <=? f)
      then Some (ini ++ [(7,1,1); (3,2,1); (4,2,gbc); (f+3,1,1)])
      else if (gbo =? 8) && (gbz =? 2) && (gbc =? 1) && (2 <=? f)
      then Some (ini ++ [(gao,gaz,gac); (7,1,1); (3,2,1); (f+3,1,1)])
      else None
  | None => None
  end.
Definition endY_seg (cols : word) (y : N) : option word :=
  match last2 cols with
  | Some (ini, (gao,gaz,gac), (gbo,gbz,gbc)) =>
      if (gao =? 8) && (gaz =? 2) && (gac =? 1)
         && (gbo =? 4) && (gbz =? 2) && (1 <=? gbc)
      then Some (ini ++ [(7,1,1); (3,2,1); (4,2,gbc); (y+3,1,1); (6,1,1)])
      else if (gbo =? 8) && (gbz =? 2) && (gbc =? 1)
      then Some (ini ++ [(gao,gaz,gac); (7,1,1); (3,2,1);
                         (y+3,1,1); (6,1,1)])
      else None
  | None => None
  end.
Fixpoint dtb4_conv (body : word) : option word :=
  match body with
  | [] => None
  | g :: t =>
      match dtb4_conv t with
      | Some t' => Some (g :: t')
      | None =>
          if (gO g =? 8) && (gZ g =? 2) && (gC g =? 1)
          then if forallb w42 t
               then Some ((7,1,1) :: (3,2,1) :: t)
               else
                 match t with
                 | (o1,z1,c1) :: (o2,z2,c2) :: t2 =>
                     if (o1 =? 4) && (z1 =? 2) && (1 <=? c1)
                        && (o2 =? 3) && (z2 =? 2) && (c2 =? 1)
                     then
                       match t2 with
                       | [] =>
                           Some ((7,1,1) :: (3,2,1)
                                 :: (if 1 <? c1 then [(4,2,c1-1)] else [])
                                    ++ [(4,1,1); (4,2,1)])
                       | [(o3,z3,c3)] =>
                           if (o3 =? 4) && (z3 =? 2)
                           then Some ((7,1,1) :: (3,2,1)
                                      :: (if 1 <? c1
                                          then [(4,2,c1-1)] else [])
                                         ++ [(4,1,1); (4,2,c3+1)])
                           else None
                       | _ => None
                       end
                     else None
                 | _ => None
                 end
          else None
      end
  end.
Fixpoint dtb3_conv (body : word) : option word :=
  match body with
  | [] => None
  | g :: t =>
      match dtb3_conv t with
      | Some t' => Some (g :: t')
      | None =>
          if (gO g =? 8) && (gZ g =? 2) && (gC g =? 1)
          then match t with
               | (o1,z1,c1) :: t1 =>
                   if (o1 =? 4) && (z1 =? 2) && (1 <? c1)
                      && forallb w42 t1
                   then Some ((7,1,1) :: (3,2,1) :: (o1,z1,c1-1) :: t1)
                   else None
               | [] => None
               end
          else None
      end
  end.
Definition jump_seg (cols : word) (B : N) : option (word) :=
  match last2 cols with
  | Some (ini, (gao,gaz,gac), (gbo,gbz,gbc)) =>
      if (gao =? 8) && (gaz =? 2) && (gac =? 1)
         && (gbo =? 4) && (gbz =? 2) && (1 <=? gbc)
      then Some (ini ++ [(7,1,1); (3,2,1); (4,2,gbc); (8,2,1)]
                     ++ (if 1 <? B then [(4,2,B-1)] else []))
      else if (gbo =? 8) && (gbz =? 2) && (gbc =? 1)
      then Some (ini ++ [(gao,gaz,gac); (7,1,1); (3,2,1); (8,2,1)]
                     ++ (if 1 <? B then [(4,2,B-1)] else []))
      else None
  | None => None
  end.
Definition sand_leaf (s : word) : bool :=
  match s with
  | [(X,2,1)] => (5 <=? X) && negb (X =? 8) && negb (X =? 12)
  | _ => false
  end.
Fixpoint fire_comp (n : nat) (s : word) (f : N) {struct n} : option (word * N) :=
  match n with O => None | S n =>
  match s with
  | (X,3,1) :: rest0 =>
    if negb (5 <=? X) then None else
    match rest0 with
    | [] =>
        if 2 <=? f then Some ([(X-1,1,1); (f+2,1,1)], 3) else None
    | (Y,zY,cY) :: rest =>
      if (Y =? 4) && (zY =? 2) then
      (let NL := cY in
       if negb (1 <=? NL) then None else
        match rest with
        | [] =>
            if f =? 4
            then Some ((X-1,1,1) :: (6,1,1) :: (3,2,1)
                       :: (if 1 <? NL then [(4,2,NL-1)] else []), f)
            else if 5 <=? f
            then Some ((X-1,1,1) :: (7,2,1)
                       :: (if 1 <? NL then [(4,2,NL-1)] else [])
                       ++ [(f-1,1,1)], 3)
            else None
        | _ =>
            let '(cols, s2) := seek rest in
            match s2 with
            | [] =>
                if 5 <=? f
                then Some ((X-1,1,1) :: (7,2,1) :: (4,2,NL-1) :: cols
                           ++ [(f-1,1,1)], 3)
                else if f =? 3 then
                  match dtb3_conv ((4,2,NL-1) :: cols) with
                  | Some body =>
                      Some ((X-1,1,1) :: (7,2,1) :: body ++ [(4,1,1)], 4)
                  | None => None
                  end
                else if f =? 4 then
                  match dtb4_conv ((4,2,NL-1) :: cols) with
                  | Some body => Some ((X-1,1,1) :: (7,2,1) :: body, f)
                  | None => None
                  end
                else None
            | (o4,z4,c4) :: s2t =>
                if (o4 =? 4) && (z4 =? 3) && (c4 =? 1) then
                  match s2t with
                  | [] =>
                      match endR_seg cols f with
                      | Some seg2 =>
                          Some ((X-1,1,1) :: (7,2,1) :: (4,2,NL-1) :: seg2, 3)
                      | None => None
                      end
                  | (o5,z5,ob) :: rest2 =>
                      if (o5 =? 4) && (z5 =? 2) then
                        if 1 <=? ob then
                          match rest2 with
                          | [] =>
                              if f =? 4 then
                                match lawR_seg cols ob with
                                | Some seg2 =>
                                    Some ((X-1,1,1) :: (7,2,1) :: (4,2,NL-1)
                                          :: seg2, f)
                                | None => None
                                end
                              else if 5 <=? f then
                                match jump_seg cols ob with
                                | Some seg2 =>
                                    Some ((X-1,1,1) :: (7,2,1) :: (4,2,NL-1)
                                          :: seg2 ++ [(f-1,1,1)], 3)
                                | None => None
                                end
                              else None
                          | _ =>
                              match jump_seg cols ob with
                              | Some seg =>
                                  let '(cols2, s3) := seek rest2 in
                                  match renew_seg n cols2 s3 f with
                                  | Some (body, f') =>
                                      Some ((X-1,1,1) :: (7,2,1) :: (4,2,NL-1)
                                            :: seg ++ body, f')
                                  | None =>
                                  match fire_comp n s3 f with
                                  | Some (s3', f') =>
                                      Some ((X-1,1,1) :: (7,2,1) :: (4,2,NL-1)
                                            :: seg ++ cols2 ++ s3', f')
                                  | None =>
                                      if sand_leaf s3
                                         && forallb (fun g => (gC g =? 0)%N) cols2
                                      then None else
                                      match leaf_act s3 f with
                                      | Some (s3', f') =>
                                          Some ((X-1,1,1) :: (7,2,1) :: (4,2,NL-1)
                                                :: seg ++ cols2 ++ s3', f')
                                      | None =>
                                          match s3 with
                                          | [] =>
                                              if 5 <=? f
                                              then Some ((X-1,1,1) :: (7,2,1)
                                                         :: (4,2,NL-1)
                                                         :: seg ++ cols2
                                                            ++ [(f-1,1,1)], 3)
                                              else if f =? 4 then
                                                match dtb4_conv cols2 with
                                                | Some cols2' =>
                                                    Some ((X-1,1,1) :: (7,2,1)
                                                          :: (4,2,NL-1)
                                                          :: seg ++ cols2', f)
                                                | None =>
                                                    if forallb w42 cols2
                                                    then match lawR_seg cols ob with
                                                         | Some seg2 =>
                                                             Some ((X-1,1,1)
                                                                   :: (7,2,1)
                                                                   :: (4,2,NL-1)
                                                                   :: seg2
                                                                      ++ cols2, f)
                                                         | None => None
                                                         end
                                                    else None
                                                end
                                              else None
                                          | _ => None
                                          end
                                      end
                                  end
                                  end
                              | None => None
                              end
                          end
                        else None
                      else if (z5 =? 3) && (ob =? 1)
                              && match rest2 with [] => true | _ => false end
                              && (f =? 4) && (1 <=? o5) then
                        (match endY_seg cols o5 with
                         | Some seg2 =>
                             Some ((X-1,1,1) :: (7,2,1) :: (4,2,NL-1)
                                   :: seg2, f - 1)
                         | None => None
                         end)
                      else
                        match leaf_act ((o4,z4,c4) :: s2t) f with
                        | Some (s2', f') =>
                            Some ((X-1,1,1) :: (7,2,1) :: (4,2,NL-1)
                                  :: cols ++ s2', f')
                        | None => None
                        end
                  end
                else if (o4 =? 4) && (z4 =? 4) && (c4 =? 1) then
                  match s2t with
                  | (on,zn,cn) :: t2 =>
                      if (on =? 4) && (zn =? 2) && (1 <=? cn) then
                        match jump_seg cols cn with
                        | Some seg2 =>
                            Some ((X-1,1,1) :: (7,2,1) :: (4,2,NL-1)
                                  :: seg2 ++ t2, f)
                        | None => None
                        end
                      else None
                  | [] => None
                  end
                else
                  match fire_comp n ((o4,z4,c4) :: s2t) f with
                  | Some (s2', f') =>
                      Some ((X-1,1,1) :: (7,2,1) :: (4,2,NL-1) :: cols ++ s2', f')
                  | None =>
                      match leaf_act ((o4,z4,c4) :: s2t) f with
                      | Some (s2', f') =>
                          Some ((X-1,1,1) :: (7,2,1) :: (4,2,NL-1)
                                :: cols ++ s2', f')
                      | None => None
                      end
                  end
            end
        end)
      else if (Y =? 8) && (zY =? 2) && (cY =? 1) then
        (let s2 := (X-1,1,1) :: (11,2,1) :: rest in
         match tick_target s2 2 with
         | Some j =>
             if (match wat s2 j with
                 | Some (_,z,_) => z =? 1
                 | None => false
                 end)
             then match deliver_tick n s2 f j true with
                  | ROk s3 f3 => Some (s3, f3)
                  | _ => None
                  end
             else None
         | None => None
         end)
      else if (zY =? 1) && (cY =? 1) && (1 <=? Y)
              && match rest with [] => true | _ => false end then
        (if 2 <=? f then Some ([(X-1,1,1); (Y+3,1,1)], f - 1) else None)
      else if (zY =? 3) && (cY =? 1) && (1 <=? Y) && (f =? 4) then
        (match rest with
         | [(o2,z2,c2)] =>
             if (o2 =? 4) && (z2 =? 2) && (1 <=? c2)
             then Some ([(X-1,1,1); (Y+2,1,1); (6,1,1); (3,2,1)]
                        ++ (if 1 <? c2 then [(4,2,c2-1)] else []), f)
             else None
         | _ => None
         end)
      else if (zY =? 1) && (cY =? 1) && (1 <=? Y)
              && match rest with
                 | (o2,z2,c2) :: _ => (o2 =? 4) && (z2 =? 2) && (1 <=? c2)
                 | [] => false
                 end then
        (match rest with
         | (o2,z2,c2) :: r2 =>
             Some ((X-1,1,1) :: (Y+3,1,1) :: (3,2,1)
                   :: (if 1 <? c2 then [(o2,z2,c2-1)] else []) ++ r2, f)
         | [] => None
         end)
      else if (zY =? 1) && (2 <=? cY) && (2 <=? Y) then
        Some ((X-1,1,1) :: (Y+3,1,1) :: (Y-1,1,1)
              :: (if 2 <? cY then [(Y,1,cY-2)] else []) ++ rest, f)
      else if (zY =? 1) && (cY =? 1) && (1 <=? Y)
              && match rest with
                 | (o2,z2,c2) :: _ => (z2 =? 1) && (c2 =? 1) && (1 <=? o2)
                 | [] => false
                 end then
        (match rest with
         | (k,_,_) :: r2 =>
             if k =? 1
             then Some ((X-1,1,1) :: (Y+3,2,1) :: r2, f)
             else Some ((X-1,1,1) :: (Y+3,1,1) :: (k-1,1,1) :: r2, f)
         | [] => None
         end)
      else if (zY =? 1) && (cY =? 1) && (1 <=? Y)
              && match rest with
                 | (o2,z2,c2) :: _ =>
                     (z2 =? 2) && (1 <=? o2) && (o2 <=? 3) && (c2 =? 1)
                 | [] => false
                 end then
        (match rest with
         | (b,_,_) :: r2 =>
             if b =? 1
             then Some ((X-1,1,1) :: (Y+3,3,1) :: r2, f)
             else Some ((X-1,1,1) :: (Y+3,1,1) :: (b-1,2,1) :: r2, f)
         | [] => None
         end)
      else None
    end
  | _ => None
  end
  end
with renew_seg (n : nat) (cols : word) (s : word) (f : N) {struct n}
  : option (word * N) :=
  match n with O => None | S n =>
  match s with
  | (4,3,1) :: rest =>
      match rest with
      | [] =>
          match endR_seg cols f with
          | Some body => Some (body, 3)
          | None => None
          end
      | (o5,z5,ob) :: rest2 =>
          if (o5 =? 4) && (z5 =? 2) && (1 <=? ob) then
            match rest2 with
            | [] =>
                if f =? 4 then
                  match lawR_seg cols ob with
                  | Some body => Some (body, f)
                  | None => None
                  end
                else if 5 <=? f then
                  match jump_seg cols ob with
                  | Some seg => Some (seg ++ [(f-1,1,1)], 3)
                  | None => None
                  end
                else None
            | _ =>
                match jump_seg cols ob with
                | Some seg =>
                    let '(cols2, s3) := seek rest2 in
                    match renew_seg n cols2 s3 f with
                    | Some (body, f') => Some (seg ++ body, f')
                    | None =>
                    match (match s3 with
                           | (o7,z7,c7) :: _ =>
                               if (z7 =? 3) && (c7 =? 1)
                               then fire_comp n s3 f
                               else if sand_leaf s3 then None
                               else leaf_act s3 f
                           | [] => leaf_act s3 f
                           end) with
                    | Some (s3', f') => Some (seg ++ cols2 ++ s3', f')
                    | None =>
                        match s3 with
                        | [] =>
                            if 5 <=? f
                            then Some (seg ++ cols2 ++ [(f-1,1,1)], 3)
                            else if f =? 4 then
                              match dtb4_conv cols2 with
                              | Some cols2' => Some (seg ++ cols2', f)
                              | None =>
                                  if forallb w42 cols2
                                  then match lawR_seg cols ob with
                                       | Some seg2 => Some (seg2 ++ cols2, f)
                                       | None => None
                                       end
                                  else None
                              end
                            else None
                        | _ => None
                        end
                    end
                    end
                | None => None
                end
            end
          else if (z5 =? 3) && (ob =? 1)
                  && match rest2 with [] => true | _ => false end
                  && (f =? 4) && (1 <=? o5) then
            match endY_seg cols o5 with
            | Some body => Some (body, f - 1)
            | None => None
            end
          else None
      end
  | _ => None
  end
  end.
Definition FUEL : nat := 60%nat.
Definition round_at (cols s : word) (f : N) : option (word * N) :=
  match s with
  | (_,3,1) :: _ =>
      match renew_seg (length s) cols s f with
      | Some (body, f2) => Some (body, f2)
      | None =>
          match fire_comp (length s) s f with
          | Some (s2, f2) => Some (cols ++ s2, f2)
          | None => None
          end
      end
  | _ =>
      match leaf_act s f with
      | Some (s2, f2) => Some (cols ++ s2, f2)
      | None => None
      end
  end.
Definition round1g (tail : word) (f : N) : option (word * N) :=
  let '(cols, s) := seek tail in round_at cols s f.
Definition round2g (tail : word) (f : N) : option (word * N) :=
  let '(cols, s) := seek tail in
  match round_at cols s f with
  | Some (t2, f2) =>
      let '(cols2, s2) := seek t2 in
      match s2 with
      | [] =>
          if f2 =? 4 then
            match dtb4_conv cols2 with
            | Some cols2' => Some (cols2', f2)
            | None => None
            end
          else if 5 <=? f2 then Some (cols2 ++ [(f2-1,1,1)], 3)
          else None
      | _ => round_at cols2 s2 f2
      end
  | None => None
  end.
Definition round2g_pre8 (tail : word) (f : N) : option word :=
  let '(cols, s) := seek tail in
  match round_at cols s f with
  | Some (t2, f2) =>
      let '(cols2, s2) := seek t2 in
      match s2 with
      | [] =>
          if (f2 =? 4) && forallb w42 cols2 then
            match dtb4_conv cols2 with
            | Some _ => None
            | None => Some cols2
            end
          else None
      | _ => None
      end
  | None => None
  end.
Definition span2_core (a m : N) (rest : word) (f : N) : res :=
  match rest with
  | [(_, _, _)] => RBad
  | (o0, z0, V) :: rest' =>
      if (o0 =? 4) && (z0 =? 2) && (1 <=? V)
      then
        let mid := if 1 <? V then [(4,2,V-1)] else [] in
        let pre := [(2,2,a+1); (4,1,1); (3,1,1); (4,1,m); (8,2,1)] ++ mid in
        let '(cols, s) := seek rest' in
        match s with
        | (oR,1,cR) :: tR =>
            match leaf_act s f with
            | Some (s2, f2) => ROk (pre ++ cols ++ s2) f2
            | None => RBad
            end
        | (oR,3,1) :: tR =>
            match renew_seg (length s) cols s f with
            | Some (body, f2) => ROk (pre ++ body) f2
            | None =>
                match fire_comp (length s) s f with
                | Some (s2, f2) => ROk (pre ++ cols ++ s2) f2
                | None => RBad
                end
            end
        | _ => RBad
        end
      else RBad
  | [] => RBad
  end.
Definition o_ (r : res) : option res := Some r.
Definition fr_primordial (w : word) (f : N) : option res :=
  match w with
  | [(4,1,1)] =>
      if 2 <=? f then o_ (ROk [(2,2,1); (4,1,1)] (f - 1))
      else Some RBad
  | [(2,2,ca); (4,1,1)] =>
      if 2 <=? f then o_ (ROk [(2,2,ca+1); (4,1,1)] (f - 1))
      else if f =? 1 then o_ (ROk [(2,2,ca+1)] 4) else Some RBad
  | _ => None
  end.
Definition fr_prim4 (w : word) (f : N) : option res :=
  match w with
  | [(2,2,cN)] =>
      if (cN =? 4) && (f =? 4)
      then o_ (ROk [(5,1,1); (4,1,1); (3,1,cN-2); (3,2,1); (4,2,1)] f)
      else None
  | _ => None
  end.
Definition fr_clean (w : word) (f : N) : option res :=
  match w with
  | (2,2,4) :: (5,2,1) :: (3,1,K) :: rest =>
      if 2 <=? K then
        let m := N.div2 K in
        o_ (ROk ([(2,2,3*m+4); (5,2,1); (3,2,m)]
                 ++ (if N.odd K then [(3,1,1)] else []) ++ rest) f)
      else None
  | _ => None
  end.
Definition fr_four (w : word) (f : N) : option res :=
  match w with
  | (2,2,cN) :: (4,2,1) :: (4,1,M) :: ((od,zd,_) :: _) as rest =>
      if (2 <=? M) && (((od =? 8) && (zd =? 2)) || ((od =? 5) && (zd =? 1)))
      then
        if N.odd M
        then o_ (ROk ((2,2,cN+2*(M-1)) :: (4,2,N.div2 (M+1))
                      :: (4,1,1) :: rest) f)
        else o_ (ROk ((2,2,cN+2*M) :: (4,2,N.div2 M+1) :: rest) f)
      else None
  | _ => None
  end.
Definition fr_span2A (w : word) (f : N) : option res :=
  match w with
  | (2,2,a) :: (5,2,1) :: (3,2,m) :: (3,3,1) :: ((4,2,_) :: _) as rest =>
      o_ (span2_core a m rest f)
  | _ => None
  end.
Definition fr_span2A' (w : word) (f : N) : option res :=
  match w with
  | [(2,2,a); (5,2,1); (3,2,m); (4,2,V)] =>
      if (1 <=? a) && (1 <=? m) && (1 <=? V) && (f =? 4)
      then o_ (ROk [(2,2,a+1); (4,1,1); (3,1,1); (4,1,m-1); (4,2,V+1)] 4)
      else None
  | _ => None
  end.
Definition fr_span2C' (w : word) (f : N) : option res :=
  match w with
  | [(2,2,a); (5,2,1); (3,2,m); (2,2,1); (4,2,V)] =>
      if (1 <=? a) && (1 <=? m) && (1 <=? V) && (f =? 4)
      then o_ (ROk [(2,2,a+1); (4,1,1); (3,1,1); (4,1,m-1);
                    (6,2,1); (4,2,V+1)] 4)
      else None
  | _ => None
  end.
Definition span8far_out (cN V : N) (rest : word) : word :=
  [(5,1,1); (4,1,1); (3,1,cN-2); (2,2,1)]
  ++ (if 1 <? V then [(4,2,V-1)] else []) ++ [(4,1,1)] ++ rest.
Definition fr_span8far (w : word) (f : N) : option res :=
  match w with
  | [(2,2,cN); (4,2,V)] =>
      if (3 <=? cN) && (1 <=? V) && (f =? 3)
      then o_ (ROk (span8far_out cN V []) f)
      else None
  | [(2,2,cN); (4,2,V); (3,2,1)] =>
      if (3 <=? cN) && (1 <=? V) && (f =? 4)
      then o_ (ROk (span8far_out cN V [(3,2,1)]) f)
      else None
  | [(2,2,cN); (4,2,V); (3,2,1); (4,2,G)] =>
      if (3 <=? cN) && (1 <=? V) && (1 <=? G) && (f =? 4)
      then o_ (ROk (span8far_out cN V [(3,2,1); (4,2,G)]) f)
      else None
  | _ => None
  end.
Definition fr_span2B (w : word) (f : N) : option res :=
  match w with
  | (2,2,a) :: (5,2,1) :: (3,2,m) :: (2,2,1) :: (4,2,V) :: (4,3,1)
      :: (4,2,G) :: restB =>
      if (1 <=? m) && (1 <=? G) then
        match round2g restB f with
        | Some (t3, f3) =>
            o_ (ROk ([(2,2,a+1); (4,1,1); (3,1,1); (4,1,m-1);
                      (5,1,1); (3,2,1); (4,2,V); (8,2,1); (4,2,G-1)]
                     ++ t3) f3)
        | None => None
        end
      else None
  | _ => None
  end.
Definition fr_span8orph (w : word) (f : N) : option res :=
  match w with
  | (2,2,cN) :: (4,2,V) :: (3,2,1) :: (4,2,W) :: (4,3,1)
      :: (4,2,G) :: restB =>
      let pre := [(5,1,1); (4,1,1); (3,1,cN-2); (2,2,1);
                  (4,2,V-1); (4,1,1); (3,2,1); (4,2,W); (8,2,1)] in
      let tail := (if 1 <? G then [(4,2,G-1)] else []) ++ restB in
      match (if (2 <=? cN) && (1 <=? V) && (1 <=? G)
             then round1g tail f else None) with
      | Some (t2, f2) => o_ (ROk (pre ++ t2) f2)
      | None => None
      end
  | _ => None
  end.
Definition fr_span8 (w : word) (f : N) : option res :=
  match w with
  | (2,2,cN) :: (4,2,V) :: (4,3,1) :: (4,2,G) :: rest =>
      let pre := [(5,1,1); (4,1,1); (3,1,cN-2); (2,2,1);
                  (4,2,V); (8,2,1); (4,2,G-1)] in
      match (match rest with
             | [] => None
             | _ => if (2 <=? cN) && (1 <=? G) then round2g rest f else None
             end) with
      | Some (t3, f3) => o_ (ROk (pre ++ t3) f3)
      | None =>
          match rest with
          | [] =>
              let hd := [(5,1,1); (4,1,1); (3,1,cN-2); (2,2,1); (4,2,V)] in
              if (2 <=? cN) && (1 <=? G) && (f =? 4) then
              let neww := hd ++ [(7,1,1); (3,2,1)]
                          ++ (if 1 <? G then [(4,2,G-1)] else []) in
              o_ (match tick_target neww 5 with
                  | Some j =>
                      match deliver_tick FUEL neww f j true with
                      | RHalt => RBad
                      | r2 => r2
                      end
                  | None => ROk neww f
                  end)
              else if (2 <=? cN) && (1 <=? G) && (5 <=? f) then
                o_ (ROk (hd ++ [(8,2,1)]
                         ++ (if 1 <? G then [(4,2,G-1)] else [])
                         ++ [(f-1,1,1)]) 2)
              else None
          | _ =>
              match (if (2 <=? cN) && (1 <=? G)
                     then round2g_pre8 rest f else None) with
              | Some cols2 =>
                  o_ (ROk ([(5,1,1); (4,1,1); (3,1,cN-2); (2,2,1); (4,2,V);
                            (7,1,1); (3,2,1); (4,2,G-1)] ++ cols2) 4)
              | None => None
              end
          end
      end
  | _ => None
  end.
Definition fr_rot (w : word) (f : N) : option res :=
  match w with
  | (5,1,1) :: (4,1,1) :: (3,1,K) :: rest =>
      o_ (ROk ((2,2,1) :: (5,1,1) :: (3,1,K+1) :: rest) f)
  | _ => None
  end.
Definition fr_502 (w : word) (f : N) : option res :=
  match w with
  | (2,2,j) :: (5,1,1) :: (3,1,K) :: rest =>
      if K =? 1
      then o_ (ROk ((2,2,j+1) :: (5,1,1) :: (2,1,1) :: rest) f)
      else if 2 <=? K
      then o_ (ROk ((2,2,j+1) :: (5,1,1) :: (2,1,1) :: (3,1,K-1) :: rest) f)
      else None
  | _ => None
  end.
Definition fr_512 (w : word) (f : N) : option res :=
  match w with
  | (2,2,j) :: (5,1,1) :: (k,1,1) :: rest =>
      if (k <? 3) && (1 <=? k) then
        if k =? 1
        then o_ (ROk ((2,2,j+1) :: (5,2,1) :: rest) f)
        else o_ (ROk ((2,2,j+1) :: (5,1,1) :: (k-1,1,1) :: rest) f)
      else None
  | _ => None
  end.
Definition fr_522 (w : word) (f : N) : option res :=
  match w with
  | (2,2,cN) :: (4,1,1) :: (k,1,1) :: rest =>
      if (k <=? 3) && (1 <=? k) then
        if k =? 1
        then o_ (ROk ((2,2,cN+1) :: (4,2,1) :: rest) f)
        else o_ (ROk ((2,2,cN+1) :: (4,1,1) :: (k-1,1,1) :: rest) f)
      else None
  | _ => None
  end.
Fixpoint first_rule (rules : list (word -> N -> option res))
                    (w : word) (f : N) : option res :=
  match rules with
  | [] => None
  | r :: rules' =>
      match r w f with
      | Some x => Some x
      | None => first_rule rules' w f
      end
  end.
Definition front_rules : list (word -> N -> option res) :=
  [fr_primordial; fr_prim4; fr_clean; fr_four; fr_span2A; fr_span2A';
   fr_span2C'; fr_span8far; fr_span2B; fr_span8orph; fr_span8;
   fr_rot; fr_502; fr_512; fr_522].
Fixpoint cmf_from (w : word) (i : nat) (n : nat) {struct n} : option nat :=
  match n with
  | O => None
  | S n' =>
      match wat w i with
      | None => None
      | Some g => if is_cmf g then Some i else cmf_from w (S i) n'
      end
  end.
Fixpoint last1 (l : word) : option bg :=
  match l with
  | [] => None
  | [g] => Some g
  | _ :: t => last1 t
  end.
Fixpoint csplit (s : word) : word * word :=
  match s with
  | g :: t => if is_col g then let '(c, r) := csplit t in (g :: c, r) else ([], s)
  | [] => ([], [])
  end.
Fixpoint e0_chain (n : nat) (s : word) : bool :=
  match n with
  | O => false
  | S n' =>
      match s with
      | (X,z,c) :: (o2,z2,NL) :: r =>
          (z =? 3) && (c =? 1) && (3 <=? X)
          && (o2 =? 4) && (z2 =? 2) && (1 <=? NL)
          && (let '(_, rest) := csplit r in
              match rest with
              | (o3,zn,cn) :: _ =>
                  if (o3 =? 1) then (1 <=? zn) && (1 <=? cn)
                  else e0_chain n' rest
              | [] => false
              end)
      | _ => false
      end
  end.
Definition jump_comp (pre : word) (B : N) (post : word) (f : N)
  : option (ckind * word * N) :=
  match post with
  | [] =>
      if f =? 4 then
        match lawR_seg pre B with
        | Some body => Some (JMP, body, f)
        | None => None
        end
      else if 5 <=? f then
        match jump_seg pre B with
        | Some segp => Some (JMP, segp ++ [(f-1,1,1)], 3)
        | None => None
        end
      else None
  | _ =>
      match jump_seg pre B with
      | Some segp =>
          let '(cols2, s3) := seek post in
          match renew_seg (length s3) cols2 s3 f with
          | Some (body, f2) => Some (JMP, segp ++ body, f2)
          | None =>
              match (match s3 with
                     | (o7,z7,c7) :: _ =>
                         if (z7 =? 3) && (c7 =? 1)
                         then fire_comp (length s3) s3 f
                         else if sand_leaf s3 then None
                              else leaf_act s3 f
                     | [] => leaf_act s3 f
                     end) with
              | Some (s3', f2) =>
                  Some (JMP, segp ++ cols2 ++ s3', f2)
              | None =>
                  match s3 with
                  | [] =>
                      if 5 <=? f then
                        Some (JMP, segp ++ cols2 ++ [(f-1,1,1)], 3)
                      else if f =? 4 then
                        match dtb4_conv cols2 with
                        | Some cols2' => Some (JMP, segp ++ cols2', f)
                        | None =>
                            if forallb w42 cols2 then
                              match lawR_seg pre B with
                              | Some seg2 => Some (JMP, seg2 ++ cols2, f)
                              | None => None
                              end
                            else None
                        end
                      else None
                  | _ => None
                  end
              end
          end
      | None => None
      end
  end.
Definition step_after_front_with_guard (trusted_prefix : bool)
                            (norm : word -> nat -> word)
                            (splice : word -> word -> nat -> word)
                            (front : option res)
                            (w : word) (f : N) (hint : nat) : res * nat :=
  match front with
  | Some r =>
      (match r with
       | ROk w2 f2 => ROk (norm w2 O) f2
       | RHalt => RBad
       | RBad => RBad
       end, O)
  | None =>
      let start :=
        match w with
        | (2,2,_) :: _ => if Nat.ltb hint 1 then 1%nat else hint
        | _ => hint
        end in
      match find_active w start with
      | Some i =>
          if negb (trusted_prefix || forallb is_col (firstn i w))
          then (RBad, O) else
          if negb (trusted_prefix || match w with
                   | g0 :: _ => (gO g0 =? 2) && (gZ g0 =? 2)
                                && (1 <=? gC g0)
                                && negb (Nat.eqb i 0)
                   | [] => false
                   end) then (RBad, O) else
          if negb (trusted_prefix || match last1 (firstn i w) with
                   | Some g => (3 <=? gO g) && (1 <=? gC g)
                   | None => false
                   end) then (RBad, O) else
          let w1 :=
            match w with
            | g0 :: t => (2, 2, gC g0 + 1) :: t
            | [] => w
            end in
          let sfx := skipn i w1 in
          let comp :=
            match sfx with
            | [] => None
            | (o4,z4,c4) :: s2t =>
                if (o4 =? 4) && (z4 =? 3) && (c4 =? 1)
                   && Nat.leb 3 i then
                  match s2t with
                  | [] =>
                      match endR_seg (firstn i w1) f with
                      | Some body => Some (JMP, body, 3)
                      | None => None
                      end
                  | (o5,z5,ob) :: rest2 =>
                      if (o5 =? 4) && (z5 =? 2) then
                        if 1 <=? ob then
                          jump_comp (firstn i w1) ob rest2 f
                        else None
                      else if (z5 =? 3) && (ob =? 1)
                              && match rest2 with [] => true | _ => false end
                              && (f =? 4) && (1 <=? o5) then
                        (match endY_seg (firstn i w1) o5 with
                         | Some body => Some (JMP, body, f - 1)
                         | None => None
                         end)
                      else
                        match fire_comp (length ((o4,z4,c4) :: s2t))
                                ((o4,z4,c4) :: s2t) f with
                        | Some (s', f2) => Some (STD, s', f2)
                        | None => None
                        end
                  end
                else if (z4 =? 3) && (c4 =? 1) then
                  match fire_comp (length ((o4,z4,c4) :: s2t))
                          ((o4,z4,c4) :: s2t) f with
                  | Some (s', f2) => Some (STD, s', f2)
                  | None => None
                  end
                else if z4 =? 1 then
                  match leaf_act ((o4,z4,c4) :: s2t) f with
                  | Some (s', f2) => Some (STD, s', f2)
                  | None => None
                  end
                else if (z4 =? 4) && (c4 =? 1) then
                  match s2t with
                  | (on,zn,cn) :: t2 =>
                      if (o4 =? 4) && (on =? 4) && (zn =? 2) && (1 <=? cn) then
                        match last2 (firstn i w1) with
                        | Some (ini, (ga,gaz,gac), (gb,gbz,gbc)) =>
                            if (ga =? 8) && (gaz =? 2) && (gac =? 1)
                               && (gb =? 4) && (gbz =? 2) && (1 <=? gbc)
                            then Some (JMP,
                                   ini ++ [(7,1,1); (3,2,1); (gb,gbz,gbc);
                                           (8,2,1)]
                                       ++ (if 1 <? cn then [(4,2,cn-1)]
                                           else [])
                                       ++ t2, f)
                            else None
                        | None => None
                        end
                      else if (4 <? o4) && (on =? 4) && (zn =? 2)
                              && (1 <=? cn) then
                        Some (STD, (o4-1,1,1) :: (7,2,1)
                                   :: (if 1 <? cn then [(4,2,cn-1)] else [])
                                   ++ t2, f)
                      else None
                  | [] =>
                      if (o4 =? 4) && (1 <=? f) then
                        match last2 (firstn i w1) with
                        | Some (ini, (ga,gaz,gac), (gb,gbz,gbc)) =>
                            if (ga =? 8) && (gaz =? 2) && (gac =? 1)
                               && (gb =? 4) && (gbz =? 2) && (1 <=? gbc)
                            then Some (JMP,
                                   ini ++ [(7,1,1); (3,2,1); (gb,gbz,gbc)],
                                   f + 4)
                            else if (gb =? 8) && (gbz =? 2) && (gbc =? 1)
                            then Some (JMP,
                                   ini ++ [(ga,gaz,gac); (7,1,1); (3,2,1)],
                                   f + 4)
                            else None
                        | None => None
                        end
                      else None
                  end
                else None
            end in
          match comp with
          | Some (JMP, body, f2) =>
              (ROk (norm body i) f2, i)
          | Some (STD, sfx', f2) =>
              (ROk (splice (firstn i w1) sfx' i) f2, i)
          | None =>
              match wat w1 i with
              | Some g3 =>
                  if (gZ g3 =? 1)%N then (RBad, O) else
                  if e0_chain (length w1) (skipn i w1) then (RHalt, i) else
                  let r := deliver_tick FUEL w1 f i false in
                  (match r with
                   | RHalt => RHalt
                   | _ => RBad
                   end, i)
              | None => (RBad, O)
              end
          end
      | None =>
          match w with
          | g0i :: t =>
              if negb ((gO g0i =? 2) && (gZ g0i =? 2)
                       && (1 <=? gC g0i)) then (RBad, O) else
              let start2 :=
                match w with
                | (2,2,_) :: (5,2,_) :: (3,2,_) :: (2,2,1) :: _ => 4%nat
                | (2,2,_) :: (5,2,_) :: (3,2,_) :: _ => 3%nat
                | _ => 1%nat
                end in
              match cmf_from w (Nat.max 1 start2) (length w) with
              | Some j =>
                  if negb (forallb is_col (firstn j w)) then (RBad, O) else
                  let w1 := (2, 2, gC g0i + 1) :: t in
                  match leaf_act (skipn j w1) f with
                  | Some (sfx', f2) =>
                      (ROk (splice (firstn j w1) sfx' j) f2, O)
                  | None =>
                      let r := chain_merge_advance FUEL w1 f j in
                      (match r with
                       | RHalt => RHalt
                       | _ => RBad
                       end, O)
                  end
              | None =>
                  if existsb (fun g => (gO g =? 8) && (gZ g =? 2)) t
                  then
                    let w1 := (2, 2, gC g0i + 1) :: t in
                    let r := debris_to_blank w1 f in
                    (match r with
                     | RHalt => RHalt
                     | _ => RBad
                     end, O)
                  else (RBad, O)
              end
          | _ => (RBad, O)
          end
      end
  end.
Definition step_after_front_with (norm : word -> nat -> word)
                            (front : option res)
                            (w : word) (f : N) (hint : nat) : res * nat :=
  step_after_front_with_guard false norm
    (fun pre sfx i => norm (pre ++ sfx) i) front w f hint.
Definition step_after_front_trusted_splice_with
                            (norm : word -> nat -> word)
                            (splice : word -> word -> nat -> word)
                            (front : option res)
                            (w : word) (f : N) (hint : nat) : res * nat :=
  step_after_front_with_guard true norm splice front w f hint.
Definition step_after_front (front : option res)
                            (w : word) (f : N) (hint : nat) : res * nat :=
  step_after_front_with (fun w _ => normalize w) front w f hint.
Definition step (w : word) (f : N) (hint : nat) : res * nat :=
  step_after_front (first_rule front_rules w f) w f hint.
Set Warnings "-require-in-module".
Close Scope N_scope.
Open Scope sym.
Open Scope list.
Definition bgroup : Type := (N * N * N)%type.
Definition bword : Type := (list bgroup * N)%type.
Definition gdecode (g : bgroup) : nat * nat * nat :=
  let '(o, z, c) := g in (N.to_nat o, N.to_nat z, N.to_nat c).
Definition frun (f : N) : wside :=
  match f with
  | N0 => []
  | _ => [(1, N.to_nat f)]
  end.
Lemma frun_pos (f : N) : (1 <= f)%N -> frun f = [(1, N.to_nat f)].
Proof. destruct f; [lia | reflexivity]. Qed.
Definition bdecode (w : bword) : wside :=
  let '(gs, f) := w in
  expand (map gdecode gs) ++ frun f.
Lemma expand_app g1 g2 : expand (g1 ++ g2) = expand g1 ++ expand g2.
Proof.
  induction g1 as [|[[o z] c] t IH]; cbn; [reflexivity|].
  rewrite IH. apply app_assoc.
Qed.
Lemma uword_repeat0_app (j : nat) (r : wside) :
  uword (repeat 0%nat j) r = pair_runs 2 2 j ++ r.
Proof.
  induction j as [|j IH]; cbn; [reflexivity|].
  rewrite IH. reflexivity.
Qed.
Lemma zeros_repeat (n : nat) : zeros n = repeat 0%nat n.
Proof. induction n; cbn; congruence. Qed.
Lemma uword_zeros (j : nat) (r : wside) :
  uword (zeros j) r = pair_runs 2 2 j ++ r.
Proof. rewrite zeros_repeat. apply uword_repeat0_app. Qed.
Lemma to_nat_ge2 (X : N) : (2 <= X)%N ->
  exists x, N.to_nat X = S (S x).
Proof.
  intros H.
  destruct (N.to_nat X) as [|[|x]] eqn:E.
  - exfalso. assert (X = 0%N) by lia. lia.
  - exfalso. assert (X = 1%N) by lia. lia.
  - eauto.
Qed.
Lemma to_nat_ge1 (X : N) : (1 <= X)%N ->
  exists x, N.to_nat X = S x.
Proof.
  intros H.
  destruct (N.to_nat X) as [|x] eqn:E.
  - exfalso. assert (X = 0%N) by lia. lia.
  - eauto.
Qed.
Lemma bridge_merge (J A Z : N) (t : list bgroup) (f : N) :
  (2 <= A)%N -> (1 <= Z)%N ->
  wstep ([], 0, bdecode ((2,2,J)::(A,1,1)::(1,Z,1)::t, f)%N)
        ([], 0, bdecode (((2,2,(J + 1)%N)::(A,(Z + 1)%N,1)::t)%N, f)).
Proof.
  intros HA HZ.
  destruct (to_nat_ge2 A HA) as [x Ex].
  destruct (to_nat_ge1 Z HZ) as [z Ez].
  pose proof (kernel_merge_step (zeros (N.to_nat J)) x z
    (expand (map gdecode t) ++ frun f)) as KM.
  assert (E1 : bdecode ((2,2,J)::(A,1,1)::(1,Z,1)::t, f)%N
             = uword (zeros (N.to_nat J))
                 ((1,(2+x)%nat) :: (0,1%nat) :: (1,1%nat) :: (0, S z)
                    :: expand (map gdecode t) ++ frun f)).
  { unfold bdecode. cbn [map gdecode expand].
    rewrite Ex, Ez.
    change (N.to_nat 2) with 2%nat.
    change (N.to_nat 1) with 1%nat.
    rewrite uword_zeros, <- !app_assoc.
    cbn [pair_runs app]. reflexivity. }
  assert (E2 : bdecode (((2,2,(J + 1)%N)::(A,(Z + 1)%N,1)::t)%N, f)
             = uword (0%nat :: zeros (N.to_nat J))
                 ((1,(2+x)%nat) :: (0, S (S z))
                    :: expand (map gdecode t) ++ frun f)).
  { unfold bdecode. cbn [map gdecode expand].
    rewrite Ex.
    change (N.to_nat 2) with 2%nat.
    change (N.to_nat 1) with 1%nat.
    replace (N.to_nat (Z + 1)) with (S (S z)) by lia.
    replace (N.to_nat (J + 1)) with (S (N.to_nat J)) by lia.
    change (0%nat :: zeros (N.to_nat J)) with (zeros (S (N.to_nat J))).
    rewrite uword_zeros, <- !app_assoc.
    cbn [pair_runs app]. reflexivity. }
  rewrite E1, E2. exact KM.
Qed.
Lemma bridge_tick (J A B Z : N) (t : list bgroup) (f : N) :
  (2 <= A)%N -> (2 <= B)%N -> (1 <= Z)%N ->
  wstep ([], 0, bdecode ((2,2,J)::(A,1,1)::(B,Z,1)::t, f)%N)
        ([], 0, bdecode (((2,2,(J + 1)%N)::(A,1,1)::((B - 1)%N,Z,1)::t)%N, f)).
Proof.
  intros HA HB HZ.
  destruct (to_nat_ge2 A HA) as [x Ex].
  destruct (to_nat_ge2 B HB) as [y Ey].
  destruct (to_nat_ge1 Z HZ) as [z Ez].
  pose proof (kernel_return_step (zeros (N.to_nat J)) x y
    ((0, S z) :: expand (map gdecode t) ++ frun f)) as KR.
  assert (E1 : bdecode ((2,2,J)::(A,1,1)::(B,Z,1)::t, f)%N
             = uword (zeros (N.to_nat J))
                 ((1,(2+x)%nat) :: (0,1%nat) :: (1, S (S y)) :: (0, S z)
                    :: expand (map gdecode t) ++ frun f)).
  { unfold bdecode. cbn [map gdecode expand].
    rewrite Ex, Ey, Ez.
    change (N.to_nat 2) with 2%nat.
    change (N.to_nat 1) with 1%nat.
    rewrite uword_zeros, <- !app_assoc.
    cbn [pair_runs app]. reflexivity. }
  assert (E2 : bdecode (((2,2,(J + 1)%N)::(A,1,1)::((B - 1)%N,Z,1)::t)%N, f)
             = uword (0%nat :: zeros (N.to_nat J))
                 ((1,(2+x)%nat) :: (0,1%nat) :: (1, S y) :: (0, S z)
                    :: expand (map gdecode t) ++ frun f)).
  { unfold bdecode. cbn [map gdecode expand].
    rewrite Ex, Ez.
    change (N.to_nat 2) with 2%nat.
    change (N.to_nat 1) with 1%nat.
    replace (N.to_nat (B - 1)) with (S y) by lia.
    replace (N.to_nat (J + 1)) with (S (N.to_nat J)) by lia.
    change (0%nat :: zeros (N.to_nat J)) with (zeros (S (N.to_nat J))).
    rewrite uword_zeros, <- !app_assoc.
    cbn [pair_runs app]. reflexivity. }
  rewrite E1, E2. exact KR.
Qed.
Fixpoint gms (p : list bgroup) : list nat :=
  match p with
  | [] => []
  | (o, _, c) :: t =>
      repeat (N.to_nat o - 2)%nat (N.to_nat c) ++ gms t
  end.
Definition zpre (p : list bgroup) : Prop :=
  Forall (fun g : bgroup => let '(o, z, c) := g in
    z = 2%N /\ (2 <= o)%N) p.
Lemma uword_repeat_w (w c : nat) (r : wside) :
  uword (repeat w c) r = pair_runs (2 + w) 2 c ++ r.
Proof.
  induction c as [|c IH]; cbn; [reflexivity|].
  rewrite IH. reflexivity.
Qed.
Lemma uword_app_ms (a b : list nat) (r : wside) :
  uword (a ++ b) r = uword a (uword b r).
Proof. induction a as [|m t IH]; cbn; congruence. Qed.
Lemma uword_gms (p : list bgroup) (r : wside) :
  zpre p ->
  uword (gms p) r = expand (map gdecode p) ++ r.
Proof.
  induction p as [|[[o z] c] t IH]; intros HP; cbn.
  - reflexivity.
  - pose proof (Forall_inv HP) as Hg; cbn in Hg; destruct Hg as [Hz Ho].
    pose proof (Forall_inv_tail HP) as HT.
    subst z.
    rewrite uword_app_ms.
    rewrite uword_repeat_w.
    rewrite IH by exact HT.
    cbn [map gdecode expand].
    change (N.to_nat 2) with 2%nat.
    rewrite <- !app_assoc.
    replace (2 + (N.to_nat o - 2))%nat with (N.to_nat o) by lia.
    reflexivity.
Qed.
Lemma bdecode_pre (p X : list bgroup) (f : N) :
  bdecode (p ++ X, f) = expand (map gdecode p) ++ bdecode (X, f).
Proof.
  unfold bdecode. rewrite map_app, expand_app, <- app_assoc. reflexivity.
Qed.
Lemma bridge_tick_p (p : list bgroup) (A B Z : N) t (f : N) :
  zpre p -> (2 <= A)%N -> (2 <= B)%N -> (1 <= Z)%N ->
  wstep ([], 0, bdecode (p ++ (A,1,1)::(B,Z,1)::t, f)%N)
        ([], 0, bdecode ((2,2,1)%N :: p ++ ((A,1,1)::((B - 1)%N,Z,1)::t)%N, f)).
Proof.
  intros HP HA HB HZ.
  destruct (to_nat_ge2 A HA) as [x Ex].
  destruct (to_nat_ge2 B HB) as [y Ey].
  destruct (to_nat_ge1 Z HZ) as [z Ez].
  pose proof (kernel_return_step (gms p) x y
    ((0, S z) :: expand (map gdecode t) ++ frun f)) as KR.
  assert (E1 : bdecode (p ++ (A,1,1)::(B,Z,1)::t, f)%N
             = uword (gms p)
                 ((1,(2+x)%nat) :: (0,1%nat) :: (1, S (S y)) :: (0, S z)
                    :: expand (map gdecode t) ++ frun f)).
  { rewrite bdecode_pre, (uword_gms _ _ HP). f_equal.
    unfold bdecode. cbn [map gdecode expand].
    rewrite Ex, Ey, Ez.
    change (N.to_nat 1) with 1%nat.
    cbn [pair_runs app]. rewrite <- ?app_assoc. reflexivity. }
  assert (E2 : bdecode ((2,2,1)%N :: p ++ ((A,1,1)::((B - 1)%N,Z,1)::t)%N, f)
             = uword (0%nat :: gms p)
                 ((1,(2+x)%nat) :: (0,1%nat) :: (1, S y) :: (0, S z)
                    :: expand (map gdecode t) ++ frun f)).
  { change ((2,2,1)%N :: p ++ ((A,1,1)::((B - 1)%N,Z,1)::t)%N)
      with (((2,2,1)%N :: p) ++ ((A,1,1)::((B - 1)%N,Z,1)::t)%N).
    rewrite bdecode_pre.
    assert (HP' : zpre ((2,2,1)%N :: p)).
    { constructor; [cbn; split; [reflexivity | lia] | exact HP]. }
    rewrite (uword_gms _ _ HP').
    cbn [gms]. change (N.to_nat 2 - 2)%nat with 0%nat.
    change (N.to_nat 1) with 1%nat. cbn [repeat app].
    f_equal.
    unfold bdecode. cbn [map gdecode expand].
    rewrite Ex, Ez.
    replace (N.to_nat (B - 1)) with (S y) by lia.
    change (N.to_nat 1) with 1%nat.
    cbn [pair_runs app]. rewrite <- ?app_assoc. reflexivity. }
  rewrite E1, E2. exact KR.
Qed.
Lemma bridge_merge_p (p : list bgroup) (A Z : N) t (f : N) :
  zpre p -> (2 <= A)%N -> (1 <= Z)%N ->
  wstep ([], 0, bdecode (p ++ (A,1,1)::(1,Z,1)::t, f)%N)
        ([], 0, bdecode ((2,2,1)%N :: p ++ ((A,(Z + 1)%N,1)::t)%N, f)).
Proof.
  intros HP HA HZ.
  destruct (to_nat_ge2 A HA) as [x Ex].
  destruct (to_nat_ge1 Z HZ) as [z Ez].
  pose proof (kernel_merge_step (gms p) x z
    (expand (map gdecode t) ++ frun f)) as KM.
  assert (E1 : bdecode (p ++ (A,1,1)::(1,Z,1)::t, f)%N
             = uword (gms p)
                 ((1,(2+x)%nat) :: (0,1%nat) :: (1,1%nat) :: (0, S z)
                    :: expand (map gdecode t) ++ frun f)).
  { rewrite bdecode_pre, (uword_gms _ _ HP). f_equal.
    unfold bdecode. cbn [map gdecode expand].
    rewrite Ex, Ez.
    change (N.to_nat 1) with 1%nat.
    cbn [pair_runs app]. rewrite <- ?app_assoc. reflexivity. }
  assert (E2 : bdecode ((2,2,1)%N :: p ++ ((A,(Z + 1)%N,1)::t)%N, f)
             = uword (0%nat :: gms p)
                 ((1,(2+x)%nat) :: (0, S (S z))
                    :: expand (map gdecode t) ++ frun f)).
  { change ((2,2,1)%N :: p ++ ((A,(Z + 1)%N,1)::t)%N)
      with (((2,2,1)%N :: p) ++ ((A,(Z + 1)%N,1)::t)%N).
    rewrite bdecode_pre.
    assert (HP' : zpre ((2,2,1)%N :: p)).
    { constructor; [cbn; split; [reflexivity | lia] | exact HP]. }
    rewrite (uword_gms _ _ HP').
    cbn [gms]. change (N.to_nat 2 - 2)%nat with 0%nat.
    change (N.to_nat 1) with 1%nat. cbn [repeat app].
    f_equal.
    unfold bdecode. cbn [map gdecode expand].
    rewrite Ex.
    replace (N.to_nat (Z + 1)) with (S (S z)) by lia.
    cbn [pair_runs app]. rewrite <- ?app_assoc. reflexivity. }
  rewrite E1, E2. exact KM.
Qed.
Lemma bridge_tick_split_p (p : list bgroup) (A B Z C : N) t (f : N) :
  zpre p -> (2 <= A)%N -> (2 <= B)%N -> (1 <= Z)%N -> (2 <= C)%N ->
  wstep ([], 0, bdecode (p ++ (A,1,1)::(B,Z,C)::t, f)%N)
        ([], 0, bdecode ((2,2,1)%N :: p
                 ++ ((A,1,1)::((B - 1)%N,Z,1)::(B,Z,(C - 1)%N)::t)%N, f)).
Proof.
  intros HP HA HB HZ HC.
  destruct (to_nat_ge2 A HA) as [x Ex].
  destruct (to_nat_ge2 B HB) as [y Ey].
  destruct (to_nat_ge1 Z HZ) as [z Ez].
  destruct (to_nat_ge1 C (N.le_trans _ _ _ (N.le_succ_diag_r 1) HC)) as [c Ec].
  pose proof (kernel_return_step (gms p) x y
    ((0, S z) :: pair_runs (S (S y)) (S z) c
       ++ expand (map gdecode t) ++ frun f)) as KR.
  assert (E1 : bdecode (p ++ (A,1,1)::(B,Z,C)::t, f)%N
             = uword (gms p)
                 ((1,(2+x)%nat) :: (0,1%nat) :: (1, S (S y)) :: (0, S z)
                    :: pair_runs (S (S y)) (S z) c
                    ++ expand (map gdecode t) ++ frun f)).
  { rewrite bdecode_pre, (uword_gms _ _ HP). f_equal.
    unfold bdecode. cbn [map gdecode expand].
    rewrite Ex, Ey, Ez, Ec.
    change (N.to_nat 1) with 1%nat.
    cbn [pair_runs app]. rewrite <- ?app_assoc. reflexivity. }
  assert (E2 : bdecode ((2,2,1)%N :: p
                 ++ ((A,1,1)::((B - 1)%N,Z,1)::(B,Z,(C - 1)%N)::t)%N, f)
             = uword (0%nat :: gms p)
                 ((1,(2+x)%nat) :: (0,1%nat) :: (1, S y) :: (0, S z)
                    :: pair_runs (S (S y)) (S z) c
                    ++ expand (map gdecode t) ++ frun f)).
  { change ((2,2,1)%N :: p
       ++ ((A,1,1)::((B - 1)%N,Z,1)::(B,Z,(C - 1)%N)::t)%N)
      with (((2,2,1)%N :: p)
       ++ ((A,1,1)::((B - 1)%N,Z,1)::(B,Z,(C - 1)%N)::t)%N).
    rewrite bdecode_pre.
    assert (HP' : zpre ((2,2,1)%N :: p)).
    { constructor; [cbn; split; [reflexivity | lia] | exact HP]. }
    rewrite (uword_gms _ _ HP').
    cbn [gms]. change (N.to_nat 2 - 2)%nat with 0%nat.
    change (N.to_nat 1) with 1%nat. cbn [repeat app].
    f_equal.
    unfold bdecode. cbn [map gdecode expand].
    rewrite Ex, Ez.
    replace (N.to_nat (B - 1)) with (S y) by lia.
    replace (N.to_nat B) with (S (S y)) by lia.
    replace (N.to_nat (C - 1)) with c by lia.
    replace (N.to_nat Z) with (S z) by lia.
    change (N.to_nat 1) with 1%nat.
    cbn [pair_runs app]. rewrite <- ?app_assoc. reflexivity. }
  rewrite E1, E2. exact KR.
Qed.
Lemma bridge_fartick_p (p : list bgroup) (A f : N) :
  zpre p -> (2 <= A)%N -> (2 <= f)%N ->
  wstep ([], 0, bdecode (p ++ [(A,1,1)%N], f))
        ([], 0, bdecode ((2,2,1)%N :: p ++ [(A,1,1)%N], (f - 1)%N)).
Proof.
  intros HP HA Hf.
  destruct (to_nat_ge2 A HA) as [x Ex].
  destruct (to_nat_ge2 f Hf) as [y Ey].
  pose proof (kernel_return_step (gms p) x y []) as KR.
  assert (E1 : bdecode (p ++ [(A,1,1)%N], f)
             = uword (gms p)
                 ((1,(2+x)%nat) :: (0,1%nat) :: (1, S (S y)) :: [])).
  { rewrite bdecode_pre, (uword_gms _ _ HP). f_equal.
    unfold bdecode. cbn [map gdecode expand].
    rewrite (frun_pos f) by lia.
    rewrite Ex, Ey.
    change (N.to_nat 1) with 1%nat.
    repeat first [rewrite <- app_assoc | progress cbn [app pair_runs]].
    reflexivity. }
  assert (E2 : bdecode ((2,2,1)%N :: p ++ [(A,1,1)%N], (f - 1)%N)
             = uword (0%nat :: gms p)
                 ((1,(2+x)%nat) :: (0,1%nat) :: (1, S y) :: [])).
  { change ((2,2,1)%N :: p ++ [(A,1,1)%N])
      with (((2,2,1)%N :: p) ++ [(A,1,1)%N]).
    rewrite bdecode_pre.
    assert (HP' : zpre ((2,2,1)%N :: p)).
    { constructor; [cbn; split; [reflexivity | lia] | exact HP]. }
    rewrite (uword_gms _ _ HP').
    cbn [gms]. change (N.to_nat 2 - 2)%nat with 0%nat.
    change (N.to_nat 1) with 1%nat. cbn [repeat app].
    f_equal.
    unfold bdecode. cbn [map gdecode expand].
    rewrite (frun_pos (f - 1)) by lia.
    rewrite Ex.
    replace (N.to_nat (f - 1)) with (S y) by lia.
    change (N.to_nat 1) with 1%nat.
    repeat first [rewrite <- app_assoc | progress cbn [app pair_runs]].
    reflexivity. }
  rewrite E1, E2. exact KR.
Qed.
Lemma bridge_harvest_p (p : list bgroup) (A : N) :
  zpre p -> (2 <= A)%N ->
  wstep ([], 0, bdecode (p ++ [(A,1,1)%N], 1%N))
        ([], 0, bdecode ((2,2,1)%N :: p ++ [(A,1,1)%N], 0%N)).
Proof.
  intros HP HA.
  destruct (to_nat_ge2 A HA) as [x Ex].
  pose proof (kernel_merge_margin_step (gms p) x) as KM.
  assert (E1 : bdecode (p ++ [(A,1,1)%N], 1%N)
             = uword (gms p)
                 ((1,(2+x)%nat) :: (0,1%nat) :: (1,1%nat) :: [])).
  { rewrite bdecode_pre, (uword_gms _ _ HP). f_equal.
    unfold bdecode. cbn [map gdecode expand frun].
    rewrite Ex.
    change (N.to_nat 1) with 1%nat.
    repeat first [rewrite <- app_assoc | progress cbn [app pair_runs]].
    reflexivity. }
  assert (E2 : bdecode ((2,2,1)%N :: p ++ [(A,1,1)%N], 0%N)
             = uword (0%nat :: gms p)
                 ((1,(2+x)%nat) :: (0,1%nat) :: [])).
  { change ((2,2,1)%N :: p ++ [(A,1,1)%N])
      with (((2,2,1)%N :: p) ++ [(A,1,1)%N]).
    rewrite bdecode_pre.
    assert (HP' : zpre ((2,2,1)%N :: p)).
    { constructor; [cbn; split; [reflexivity | lia] | exact HP]. }
    rewrite (uword_gms _ _ HP').
    cbn [gms]. change (N.to_nat 2 - 2)%nat with 0%nat.
    change (N.to_nat 1) with 1%nat. cbn [repeat app].
    f_equal.
    unfold bdecode. cbn [map gdecode expand frun].
    rewrite Ex.
    change (N.to_nat 1) with 1%nat.
    repeat first [rewrite <- app_assoc | progress cbn [app pair_runs]].
    reflexivity. }
  rewrite E1, E2. exact KM.
Qed.
Lemma bridge_split_p (p : list bgroup) (A C : N) (t : list bgroup) (f : N) :
  zpre p -> (2 <= A)%N -> (2 <= C)%N ->
  wstep ([], 0, bdecode (p ++ (A,1,C)::t, f)%N)
        ([], 0, bdecode ((2,2,1)%N :: p
                 ++ ((A,1,1)::((A - 1)%N,1,1)::(A,1,(C - 2)%N)::t)%N, f)).
Proof.
  intros HP HA HC.
  destruct (to_nat_ge2 A HA) as [x Ex].
  destruct (to_nat_ge2 C HC) as [c2 Ec].
  pose proof (kernel_return_step (gms p) x x
    ((0, 1%nat) :: pair_runs (S (S x)) 1 c2
       ++ expand (map gdecode t) ++ frun f)) as KR.
  assert (E1 : bdecode (p ++ (A,1,C)::t, f)%N
             = uword (gms p)
                 ((1,(2+x)%nat) :: (0,1%nat) :: (1, S (S x)) :: (0, 1%nat)
                    :: pair_runs (S (S x)) 1 c2
                    ++ expand (map gdecode t) ++ frun f)).
  { rewrite bdecode_pre, (uword_gms _ _ HP). f_equal.
    unfold bdecode. cbn [map gdecode expand].
    rewrite Ex, Ec.
    change (N.to_nat 1) with 1%nat.
    repeat first [rewrite <- app_assoc | progress cbn [app pair_runs]].
    reflexivity. }
  assert (E2 : bdecode ((2,2,1)%N :: p
                 ++ ((A,1,1)::((A - 1)%N,1,1)::(A,1,(C - 2)%N)::t)%N, f)
             = uword (0%nat :: gms p)
                 ((1,(2+x)%nat) :: (0,1%nat) :: (1, S x) :: (0, 1%nat)
                    :: pair_runs (S (S x)) 1 c2
                    ++ expand (map gdecode t) ++ frun f)).
  { change ((2,2,1)%N :: p ++ ?X0) with (((2,2,1)%N :: p) ++ X0).
    rewrite bdecode_pre.
    assert (HP' : zpre ((2,2,1)%N :: p)).
    { constructor; [cbn; split; [reflexivity | lia] | exact HP]. }
    rewrite (uword_gms _ _ HP').
    cbn [gms]. change (N.to_nat 2 - 2)%nat with 0%nat.
    change (N.to_nat 1) with 1%nat. cbn [repeat app].
    f_equal.
    unfold bdecode. cbn [map gdecode expand].
    rewrite Ex.
    replace (N.to_nat (A - 1)) with (S x) by lia.
    replace (N.to_nat (C - 2)) with c2 by lia.
    change (N.to_nat 1) with 1%nat.
    repeat first [rewrite <- app_assoc | progress cbn [app pair_runs]].
    reflexivity. }
  rewrite E1, E2. exact KR.
Qed.
Lemma pair_runs_add (o z c1 c2 : nat) :
  pair_runs o z (c1 + c2) = pair_runs o z c1 ++ pair_runs o z c2.
Proof.
  induction c1 as [|c1 IH]; cbn; [reflexivity | now rewrite IH].
Qed.
Lemma bridge_clean_cycle (a m K : N) (t : list bgroup) (f : N) :
  (2 <= K)%N ->
  wstep ([], 0, bdecode ((2,2,a)::(5,2,1)::(3,2,m)::(3,1,K)::t, f)%N)
        ([], 0, bdecode ((2,2,(a + 3)%N)::(5,2,1)::(3,2,(m + 1)%N)
                          ::(3,1,(K - 2)%N)::t, f)%N).
Proof.
  intros HK.
  assert (EN : bdecode ((2,2,1)::(2,2,1)::(2,2,1)::(2,2,a)::(5,2,1)
                          ::(3,2,m)::(3,2,1)::(3,1,(K - 2)%N)::t, f)%N
             = bdecode ((2,2,(a + 3)%N)::(5,2,1)::(3,2,(m + 1)%N)
                          ::(3,1,(K - 2)%N)::t, f)%N).
  { unfold bdecode. cbn [map gdecode expand].
    replace (N.to_nat (a + 3)) with (1 + (1 + (1 + N.to_nat a)))%nat by lia.
    replace (N.to_nat (m + 1)) with (N.to_nat m + 1)%nat by lia.
    repeat rewrite pair_runs_add.
    change (N.to_nat 1) with 1%nat.
    repeat first [rewrite <- app_assoc | progress cbn [app pair_runs]].
    reflexivity. }
  rewrite <- EN.
  eapply wstep_trans.
  { exact (bridge_split_p [(2,2,a);(5,2,1);(3,2,m)]%N 3 K t f
      ltac:(repeat constructor; cbn; try split; lia)
      ltac:(lia) HK). }
  cbn [app].
  eapply wstep_trans.
  { exact (bridge_tick_p ((2,2,1)::[(2,2,a);(5,2,1);(3,2,m)])%N
      3 2 1 (((3,1,(K - 2))%N)::t) f
      ltac:(repeat constructor; cbn; try split; lia)
      ltac:(lia) ltac:(lia) ltac:(lia)). }
  cbn [app].
  exact (bridge_merge_p ((2,2,1)::(2,2,1)::[(2,2,a);(5,2,1);(3,2,m)])%N
      3 1 (((3,1,(K - 2))%N)::t) f
      ltac:(repeat constructor; cbn; try split; lia)
      ltac:(lia) ltac:(lia)).
Qed.
Lemma bridge_clean_iter (j : nat) :
  forall (a m K : N) (t : list bgroup) (f : N),
  (2 * N.of_nat (S j) <= K)%N ->
  wstep ([], 0, bdecode ((2,2,a)::(5,2,1)::(3,2,m)::(3,1,K)::t, f)%N)
        ([], 0, bdecode ((2,2,(a + 3 * N.of_nat (S j))%N)::(5,2,1)
                          ::(3,2,(m + N.of_nat (S j))%N)
                          ::(3,1,(K - 2 * N.of_nat (S j))%N)::t, f)%N).
Proof.
  induction j as [|j IH]; intros a m K t f HK.
  - replace (3 * N.of_nat 1)%N with 3%N by lia.
    replace (N.of_nat 1) with 1%N by lia.
    replace (2 * N.of_nat 1)%N with 2%N in HK by lia.
    replace (K - 2 * 1)%N with (K - 2)%N by lia.
    replace (m + 1 * 1)%N with (m + 1)%N by lia.
    apply bridge_clean_cycle. lia.
  - eapply wstep_trans.
    + apply bridge_clean_cycle with (a := a) (m := m) (K := K). lia.
    + specialize (IH (a + 3)%N (m + 1)%N (K - 2)%N t f ltac:(lia)).
      replace ((a + 3) + 3 * N.of_nat (S j))%N
        with (a + 3 * N.of_nat (S (S j)))%N in IH by lia.
      replace ((m + 1) + N.of_nat (S j))%N
        with (m + N.of_nat (S (S j)))%N in IH by lia.
      replace ((K - 2) - 2 * N.of_nat (S j))%N
        with (K - 2 * N.of_nat (S (S j)))%N in IH by lia.
      exact IH.
Qed.
Lemma bridge_cleanconv (a m K : N) (t : list bgroup) (f : N) :
  (2 <= K)%N ->
  wstep ([], 0, bdecode ((2,2,a)::(5,2,1)::(3,2,m)::(3,1,K)::t, f)%N)
        ([], 0, bdecode ((2,2,(a + 3 * (K / 2))%N)::(5,2,1)
                          ::(3,2,(m + K / 2)%N)
                          ::(3,1,(K mod 2)%N)::t, f)%N).
Proof.
  intros HK.
  assert (HJ : exists j, N.to_nat (K / 2) = S j).
  { destruct (to_nat_ge1 (K / 2)) as [j Ej].
    - apply N.div_le_lower_bound; lia.
    - eauto. }
  destruct HJ as [j Ej].
  pose proof (bridge_clean_iter j a m K t f) as IT.
  replace (N.of_nat (S j)) with (K / 2)%N in IT
    by (rewrite <- Ej, N2Nat.id; reflexivity).
  replace (K - 2 * (K / 2))%N with (K mod 2)%N in IT
    by (rewrite N.mod_eq; lia).
  apply IT.
  pose proof (N.mul_div_le K 2). lia.
Qed.
Lemma bridge_four_cycle (n v M : N) (t : list bgroup) (f : N) :
  (1 <= v)%N -> (2 <= M)%N ->
  wstep ([], 0, bdecode ((2,2,n)::(4,2,v)::(4,1,M)::t, f)%N)
        ([], 0, bdecode ((2,2,(n + 4)%N)::(4,2,(v + 1)%N)
                          ::(4,1,(M - 2)%N)::t, f)%N).
Proof.
  intros Hv HM.
  assert (EN : bdecode ((2,2,1)::(2,2,1)::(2,2,1)::(2,2,1)::(2,2,n)
                          ::(4,2,v)::(4,2,1)::(4,1,(M - 2)%N)::t, f)%N
             = bdecode ((2,2,(n + 4)%N)::(4,2,(v + 1)%N)
                          ::(4,1,(M - 2)%N)::t, f)%N).
  { unfold bdecode. cbn [map gdecode expand].
    replace (N.to_nat (n + 4))
      with (1 + (1 + (1 + (1 + N.to_nat n))))%nat by lia.
    replace (N.to_nat (v + 1)) with (N.to_nat v + 1)%nat by lia.
    repeat rewrite pair_runs_add.
    change (N.to_nat 1) with 1%nat.
    repeat first [rewrite <- app_assoc | progress cbn [app pair_runs]].
    reflexivity. }
  rewrite <- EN.
  eapply wstep_trans.
  { exact (bridge_split_p [(2,2,n);(4,2,v)]%N 4 M t f
      ltac:(repeat constructor; cbn; try split; lia)
      ltac:(lia) HM). }
  cbn [app].
  eapply wstep_trans.
  { exact (bridge_tick_p ((2,2,1)::[(2,2,n);(4,2,v)])%N
      4 3 1 (((4,1,(M - 2))%N)::t) f
      ltac:(repeat constructor; cbn; try split; lia)
      ltac:(lia) ltac:(lia) ltac:(lia)). }
  cbn [app].
  eapply wstep_trans.
  { exact (bridge_tick_p ((2,2,1)::(2,2,1)::[(2,2,n);(4,2,v)])%N
      4 2 1 (((4,1,(M - 2))%N)::t) f
      ltac:(repeat constructor; cbn; try split; lia)
      ltac:(lia) ltac:(lia) ltac:(lia)). }
  cbn [app].
  exact (bridge_merge_p ((2,2,1)::(2,2,1)::(2,2,1)::[(2,2,n);(4,2,v)])%N
      4 1 (((4,1,(M - 2))%N)::t) f
      ltac:(repeat constructor; cbn; try split; lia)
      ltac:(lia) ltac:(lia)).
Qed.
Lemma bridge_four_iter (j : nat) :
  forall (n v M : N) (t : list bgroup) (f : N),
  (1 <= v)%N -> (2 * N.of_nat (S j) <= M)%N ->
  wstep ([], 0, bdecode ((2,2,n)::(4,2,v)::(4,1,M)::t, f)%N)
        ([], 0, bdecode ((2,2,(n + 4 * N.of_nat (S j))%N)
                          ::(4,2,(v + N.of_nat (S j))%N)
                          ::(4,1,(M - 2 * N.of_nat (S j))%N)::t, f)%N).
Proof.
  induction j as [|j IH]; intros n v M t f Hv HM.
  - replace (4 * N.of_nat 1)%N with 4%N by lia.
    replace (N.of_nat 1) with 1%N by lia.
    replace (M - 2 * 1)%N with (M - 2)%N by lia.
    apply bridge_four_cycle; lia.
  - eapply wstep_trans.
    + apply bridge_four_cycle with (n := n) (v := v) (M := M); lia.
    + specialize (IH (n + 4)%N (v + 1)%N (M - 2)%N t f
        ltac:(lia) ltac:(lia)).
      replace ((n + 4) + 4 * N.of_nat (S j))%N
        with (n + 4 * N.of_nat (S (S j)))%N in IH by lia.
      replace ((v + 1) + N.of_nat (S j))%N
        with (v + N.of_nat (S (S j)))%N in IH by lia.
      replace ((M - 2) - 2 * N.of_nat (S j))%N
        with (M - 2 * N.of_nat (S (S j)))%N in IH by lia.
      exact IH.
Qed.
Lemma bridge_fourconv (n v M : N) (t : list bgroup) (f : N) :
  (1 <= v)%N -> (2 <= M)%N ->
  wstep ([], 0, bdecode ((2,2,n)::(4,2,v)::(4,1,M)::t, f)%N)
        ([], 0, bdecode ((2,2,(n + 4 * (M / 2))%N)
                          ::(4,2,(v + M / 2)%N)
                          ::(4,1,(M mod 2)%N)::t, f)%N).
Proof.
  intros Hv HM.
  assert (HJ : exists j, N.to_nat (M / 2) = S j).
  { destruct (to_nat_ge1 (M / 2)) as [j Ej].
    - apply N.div_le_lower_bound; lia.
    - eauto. }
  destruct HJ as [j Ej].
  pose proof (bridge_four_iter j n v M t f Hv) as IT.
  replace (N.of_nat (S j)) with (M / 2)%N in IT
    by (rewrite <- Ej, N2Nat.id; reflexivity).
  replace (M - 2 * (M / 2))%N with (M mod 2)%N in IT
    by (rewrite N.mod_eq; lia).
  apply IT.
  pose proof (N.mul_div_le M 2). lia.
Qed.
Lemma pair_runs_rot (o z c : nat) (X : wside) :
  pair_runs o z c ++ (1,o) :: (0,z) :: X
  = (1,o) :: (0,z) :: pair_runs o z c ++ X.
Proof.
  change ((1,o) :: (0,z) :: pair_runs o z c ++ X)
    with (pair_runs o z 1 ++ (pair_runs o z c ++ X)).
  rewrite app_assoc, <- pair_runs_add.
  replace (1 + c)%nat with (c + 1)%nat by lia.
  rewrite pair_runs_add.
  cbn [pair_runs app]. rewrite <- app_assoc. reflexivity.
Qed.
Lemma cdesc_group (j b : nat) (R : wside) :
  cdesc j 2 (S b) R
  = (1,5%nat) :: (0,1%nat) :: (1,4%nat) :: (0,1%nat)
      :: pair_runs 3 1 j ++ (1, S (S b)) :: R.
Proof.
  revert b R. induction j as [|j IH]; intros b R.
  - cbn [cdesc pair_runs app]. reflexivity.
  - cbn [cdesc].
    rewrite (IH 1%nat ((0,1%nat) :: (1, S (S b)) :: R)).
    cbn [pair_runs].
    f_equal. f_equal. f_equal. f_equal.
    change ((1, S (S 1)) :: (0,1%nat) :: (1, S (S b)) :: R)
      with ((1,3%nat) :: (0,1%nat) :: ((1, S (S b)) :: R)).
    rewrite (pair_runs_rot 3 1 j ((1, S (S b)) :: R)).
    reflexivity.
Qed.
Open Scope list.
Definition sdecode (w : word) (f : N) : wside :=
  bdecode (w, f).
Definition gdec1 (g : bg) : wside :=
  let '(o,z,c) := g in
  pair_runs (N.to_nat o) (N.to_nat z) (N.to_nat c).
Lemma sdecode_cons g t f :
  sdecode (g :: t) f = gdec1 g ++ sdecode t f.
Proof.
  destruct g as [[o z] c].
  unfold sdecode, bdecode. cbn [map gdecode expand].
  rewrite <- !app_assoc. reflexivity.
Qed.
Lemma gdec1_merge (o z c1 c2 : N) :
  gdec1 (o,z,(c1+c2)%N) = gdec1 (o,z,c1) ++ gdec1 (o,z,c2).
Proof.
  unfold gdec1. rewrite N2Nat.inj_add. apply pair_runs_add.
Qed.
Lemma normalize_sound (w : word) (f : N) :
  sdecode (normalize w) f = sdecode w f.
Proof.
  induction w as [|[[o z] c] t IH]; cbn [normalize].
  - reflexivity.
  - destruct (normalize t) as [|[[o2 z2] c2] t2] eqn:E.
    + rewrite !sdecode_cons. rewrite <- IH. reflexivity.
    + cbn [gO gZ gC].
      destruct (andb (N.eqb o o2) (N.eqb z z2)) eqn:EQ.
      * apply andb_prop in EQ. destruct EQ as [E1 E2].
        apply N.eqb_eq in E1. apply N.eqb_eq in E2. subst o2 z2.
        rewrite sdecode_cons.
        rewrite (sdecode_cons (o,z,c) t).
        rewrite <- IH.
        rewrite sdecode_cons.
        rewrite gdec1_merge, <- app_assoc. reflexivity.
      * rewrite !sdecode_cons. rewrite <- IH.
        rewrite sdecode_cons. reflexivity.
Qed.
Lemma sdecode_app_ctx (q w1 w2 : word) (f : N) :
  sdecode w1 f = sdecode w2 f ->
  sdecode (q ++ w1) f = sdecode (q ++ w2) f.
Proof.
  intros H.
  induction q as [|g q IH]; cbn [app].
  - exact H.
  - rewrite !sdecode_cons, IH. reflexivity.
Qed.
Open Scope sym.
Lemma zero_run_const (z : nat) : [0]^^z *> const 0 = const 0.
Proof.
  apply lpow_all0.
  apply cside_eqb_const0_spec. reflexivity.
Qed.
Lemma wdec_snoc0 (r : wside) (z : nat) :
  wdec (r ++ [(0, z)]) = wdec r.
Proof.
  induction r as [|[b n] t IH]; cbn [wdec app].
  - apply zero_run_const.
  - rewrite IH. reflexivity.
Qed.
Lemma wconf_snoc0 (l : wside) (cur : Sym) (r : wside) (z : nat) :
  wconf l cur (r ++ [(0, z)]) = wconf l cur r.
Proof. unfold wconf. rewrite wdec_snoc0. reflexivity. Qed.
Lemma sdecode_drop0 (o z : N) (t : list bgroup) (f : N) :
  sdecode ((o,z,0%N) :: t) f = sdecode t f.
Proof.
  rewrite sdecode_cons. unfold gdec1. cbn.
  reflexivity.
Qed.
Lemma sdecode_drop0_at (pre : list bgroup) (o z : N)
    (t : list bgroup) (f : N) :
  sdecode (pre ++ (o,z,0%N) :: t) f = sdecode (pre ++ t) f.
Proof.
  induction pre as [|g p IH]; cbn [app].
  - apply sdecode_drop0.
  - rewrite !sdecode_cons. rewrite IH. reflexivity.
Qed.
Lemma seek_split (s : word) :
  forall cols s2, seek s = (cols, s2) ->
  s = cols ++ s2
  /\ forallb (fun g => andb (andb (is_col g) (negb (is_cmf g)))
                       (N.leb 3 (gO g))) cols = true.
Proof.
  induction s as [|g t IH]; intros cols s2 E.
  - cbn in E. inversion E; subst. split; reflexivity.
  - cbn in E.
    destruct (andb (andb (is_col g) (negb (is_cmf g)))
              (N.leb 3 (gO g))) eqn:EG.
    + destruct (seek t) as [c r] eqn:ES.
      inversion E; subst.
      destruct (IH c s2 eq_refl) as (E1 & E2).
      split.
      * cbn. rewrite <- E1. reflexivity.
      * cbn. rewrite EG, E2. reflexivity.
    + inversion E; subst. split; reflexivity.
Qed.
