Definition cundef : cost := (1%N, 0%N).
Lemma cin_cundef (k : nat) : ~ cin k cundef.
Proof. unfold cin, cundef; cbn [fst snd]; lia. Qed.
Definition cproj (x : res * nat * cost) : res * nat :=
  (fst (fst x), snd (fst x)).
Definition decorate (r : word -> N -> option res) (d : word -> N -> cost)
  : word -> N -> option (res * cost) :=
  fun w f => match r w f with
             | Some x => Some (x, d w f)
             | None => None
             end.
Fixpoint zipdec (rs : list (word -> N -> option res))
                (ds : list (word -> N -> cost))
  : list (word -> N -> option (res * cost)) :=
  match rs with
  | [] => []
  | r :: rs' =>
    match ds with
    | [] => decorate r (fun _ _ => cundef) :: zipdec rs' []
    | d :: ds' => decorate r d :: zipdec rs' ds'
    end
  end.
Fixpoint cfirst_rule (rules : list (word -> N -> option (res * cost)))
                     (w : word) (f : N) : option (res * cost) :=
  match rules with
  | [] => None
  | r :: rules' =>
    match r w f with
    | Some x => Some x
    | None => cfirst_rule rules' w f
    end
  end.
Lemma cfirst_rule_proj (rs : list (word -> N -> option res))
      (ds : list (word -> N -> cost)) (w : word) (f : N) :
  option_map fst (cfirst_rule (zipdec rs ds) w f) = first_rule rs w f.
Proof.
  gen ds. induction rs as [|r rs' IH]; intros ds; [reflexivity|].
  destruct ds as [|d ds']; cbn [zipdec cfirst_rule first_rule];
    unfold decorate;
    destruct (r w f) as [x|]; cbn [option_map fst]; auto.
Qed.
