Open Scope N_scope.
Definition gcross (g : bg) : N := let '(o, _, c) := g in c * (o + 2).
Fixpoint wcross (p : word) : N :=
  match p with
  | [] => 0
  | g :: t => gcross g + wcross t
  end.
Definition d_trig (X NL : N) (mid : word) : N :=
  X + 11 + 6 * (NL - 1) + wcross mid.
Fixpoint e0_cost (n : nat) (s : word) : option N :=
  match n with
  | O => None
  | S n' =>
      match s with
      | (X,z,c) :: (o2,z2,NL) :: r =>
          if (z =? 3) && (c =? 1) && (3 <=? X)
             && (o2 =? 4) && (z2 =? 2) && (1 <=? NL)
          then
            let '(cols, rest) := csplit r in
            match rest with
            | (o3,zn,cn) :: _ =>
                if (o3 =? 1)
                then (if (1 <=? zn) && (1 <=? cn)
                      then Some (d_trig X NL cols)
                      else None)
                else match e0_cost n' rest with
                     | Some K => Some (d_trig X NL cols + K)
                     | None => None
                     end
            | [] => None
            end
          else None
      | _ => None
      end
  end.
Definition gstart2 (w : word) : nat :=
  match w with
  | (2,2,_) :: (5,2,_) :: (3,2,_) :: (2,2,1) :: _ => 4%nat
  | (2,2,_) :: (5,2,_) :: (3,2,_) :: _ => 3%nat
  | _ => 1%nat
  end.
Definition d_e0 (w : word) (i : nat) : cost :=
  match e0_cost (List.length w) (skipn i w) with
  | Some K => cx (wcross (firstn i w) + K + 2)
  | None => cundef
  end.
Definition d_inert (w : word) : cost :=
  match cmf_from w (Nat.max 1%nat (gstart2 w)) (List.length w) with
  | Some j => cx (wcross (firstn (S j) w) + 2)
  | None => cundef
  end.
Definition d_guard (w : word) (i : nat) : cost :=
  match i with
  | O => d_inert w
  | S _ => d_e0 w i
  end.
