Open Scope bool_scope.
Definition d_tick (o : N) : cost := cx (2 * o + 9).
Definition d_thru (o : N) : cost := cx (2 * o + 6).
Fixpoint ccolcost (cols : word) : N :=
  match cols with
  | [] => 0
  | g :: t => gC g * (2 * gO g + 6) + ccolcost t
  end.
Fixpoint w42sum (t : word) : N :=
  match t with
  | [] => 0
  | g :: r => gC g + w42sum r
  end.
Definition kdtb_plain  (K : N) : N := 14 * K + 43.
Definition kdtb_orphan (c1 cw : N) : N := 14 * c1 + 14 * cw + 53.
Fixpoint dtb4_convc (body : word) : option (word * N) :=
  match body with
  | [] => None
  | g :: t =>
      match dtb4_convc t with
      | Some (t', k) => Some (g :: t', k + ccolcost [g])
      | None =>
          if (gO g =? 8) && (gZ g =? 2) && (gC g =? 1)
          then if forallb w42 t
               then Some ((7,1,1) :: (3,2,1) :: t, kdtb_plain (w42sum t))
               else
                 match t with
                 | (o1,z1,c1) :: (o2,z2,c2) :: t2 =>
                     if (o1 =? 4) && (z1 =? 2) && (1 <=? c1)
                        && (o2 =? 3) && (z2 =? 2) && (c2 =? 1)
                     then
                       match t2 with
                       | [] =>
                           Some ((7,1,1) :: (3,2,1)
                                 :: (if 1 <? c1 then [(4,2,c1-1)] else [])
                                    ++ [(4,1,1); (4,2,1)],
                                 kdtb_orphan c1 0)
                       | [(o3,z3,c3)] =>
                           if (o3 =? 4) && (z3 =? 2)
                           then Some ((7,1,1) :: (3,2,1)
                                      :: (if 1 <? c1
                                          then [(4,2,c1-1)] else [])
                                         ++ [(4,1,1); (4,2,c3+1)],
                                      kdtb_orphan c1 c3)
                           else None
                       | _ => None
                       end
                     else None
                 | _ => None
                 end
          else None
      end
  end.
Definition kdtb_f3 (c1 K : N) : N := 14 * c1 + 14 * K + 39.
Fixpoint dtb3_convc (body : word) : option (word * N) :=
  match body with
  | [] => None
  | g :: t =>
      match dtb3_convc t with
      | Some (t', k) => Some (g :: t', k + ccolcost [g])
      | None =>
          if (gO g =? 8) && (gZ g =? 2) && (gC g =? 1)
          then match t with
               | (o1,z1,c1) :: t1 =>
                   if (o1 =? 4) && (z1 =? 2) && (1 <? c1)
                      && forallb w42 t1
                   then Some ((7,1,1) :: (3,2,1) :: (o1,z1,c1-1) :: t1,
                              kdtb_f3 c1 (w42sum t1))
                   else None
               | [] => None
               end
          else None
      end
  end.
Lemma dtb3_convc_proj (body : word) :
  option_map fst (dtb3_convc body) = dtb3_conv body.
Proof.
  Transparent dtb3_conv.
  induction body as [|g t IH]; [reflexivity|].
  cbn [dtb3_convc dtb3_conv].
  rewrite <- IH.
  destruct (dtb3_convc t) as [[t' k]|]; cbn [option_map fst]; [reflexivity|].
  destruct g as [[go gz] gc]; cbn [gO gZ gC].
  destruct ((go =? 8) && (gz =? 2) && (gc =? 1)); [|reflexivity].
  destruct t as [|[[o1 z1] c1] t1]; [reflexivity|].
  destruct ((o1 =? 4) && (z1 =? 2) && (1 <? c1) && forallb w42 t1);
    reflexivity.
Qed.
Lemma dtb4_convc_proj (body : word) :
  option_map fst (dtb4_convc body) = dtb4_conv body.
Proof.
  Transparent dtb4_conv.
  induction body as [|g t IH]; [reflexivity|].
  cbn [dtb4_convc dtb4_conv].
  rewrite <- IH.
  destruct (dtb4_convc t) as [[t' k]|]; cbn [option_map fst]; [reflexivity|].
  destruct g as [[go gz] gc]; cbn [gO gZ gC].
  destruct ((go =? 8) && (gz =? 2) && (gc =? 1)); [|reflexivity].
  destruct (forallb w42 t); [reflexivity|].
  destruct t as [|[[o1 z1] c1] t1]; [reflexivity|].
  destruct t1 as [|[[o2 z2] c2] t2]; [reflexivity|].
  destruct ((o1 =? 4) && (z1 =? 2) && (1 <=? c1)
            && (o2 =? 3) && (z2 =? 2) && (c2 =? 1)); [|reflexivity].
  destruct t2 as [|[[o3 z3] c3] t3]; [reflexivity|].
  destruct t3 as [|g4 t4]; [|reflexivity].
  destruct ((o3 =? 4) && (z3 =? 2)); reflexivity.
Qed.
