Definition d_cma_respawn_at (X cn : N) (t2 : word) : cost :=
  match t2 with
  | [] => d_cma_respawn_final X cn
  | [_; g3] => d_cma_respawn_orphan X cn (cw42g g3)
  | _ => cundef
  end.
