Definition cmasterb (w : word) : bool :=
  match w with
  | (o,z,c) :: _ => (o =? 2) && (z =? 2) && (1 <=? c)
  | [] => false
  end.
Definition clift (g : bg) : bool :=
  is_col g && negb (is_cmf g) && (3 <=? gO g).
Definition d_dtb_cross (w : word) (s : nat) : cost :=
  if cmasterb w && forallb is_col (firstn s w)
  then cx (ccolcost (firstn s w))
  else cundef.
Definition d_dtb_plain (f K : N) : cost :=
  if f =? 4 then cx (14 * K + 49) else cundef.
Definition d_dtb_orphan (f c1 cw : N) : cost :=
  if (f =? 4) && (1 <=? c1) then cx (14 * c1 + 14 * cw + 59) else cundef.
Definition d_dtb_far (w : word) (f : N) : cost :=
  if (5 <=? f) && cmasterb w && forallb clift (skipn 1 w)
  then cx (ccolcost w + 2 * f + 19)
  else cundef.
Definition d_dtb_f3 (c1 K : N) : cost :=
  if 1 <? c1 then cx (14 * c1 + 14 * K + 45) else cundef.
Definition d_casc_far (X f : N) : cost :=
  if 2 <=? f then cx (2 * X + 2 * f + 27) else cundef.
Definition d_casc_lvl_end (X cY f : N) : cost :=
  if f =? 4 then cx (2 * X + 14 * cY + 35)
  else if 5 <=? f then cx (2 * X + 14 * cY + 2 * f + 27)
  else cundef.
Definition d_casc_dtb (X cY : N) (cols : word) (f : N) : cost :=
  if 5 <=? f
  then cx (2 * X + 14 * cY + 2 * f + ccolcost cols + 27)
  else if f =? 3
  then match dtb3_convc cols with
       | Some (_, Kd) => cx (Kd + 2 * X + 14 * cY + 14)
       | None => cundef
       end
  else if f =? 4
  then match dtb4_convc cols with
       | Some (_, Kd) => cx (Kd + 2 * X + 14 * cY + 14)
       | None => cundef
       end
  else cundef.
Definition d_casc_tail (X cY : N) (cols : word) (Bq : N) (cols2 : word)
                       (f : N) : cost :=
  if 5 <=? f
  then cx (2 * X + 14 * cY + 14 * Bq + 2 * f
           + ccolcost cols + ccolcost cols2 + 49)
  else if f =? 4
  then match dtb4_convc cols2 with
       | Some (_, Kd) => cx (Kd + 2 * X + 14 * cY + 14 * Bq
                             + ccolcost cols + 36)
       | None =>
           if forallb w42 cols2
           then cx (2 * X + 14 * cY + 14 * Bq
                    + ccolcost cols + ccolcost cols2 + 57)
           else cundef
       end
  else cundef.
