Definition d_casc_leafj (X cY : N) (cols : word) (Bq : N) (cols2 : word)
  : cost :=
  cx (2 * X + 14 * cY + 30 + ccolcost cols + 14 * Bq + ccolcost cols2).
Definition d_casc_z1law (X Y : N) : cost := cx (2 * X + 2 * Y + 17).
Definition d_casc_z1end (X Y f : N) : cost :=
  if 2 <=? f then d_casc_z1law X Y else cundef.
Definition d_casc_z1lvl   (X Y : N) : cost := d_casc_z1law X Y.
Definition d_casc_z1split (X Y : N) : cost := d_casc_z1law X Y.
Definition d_casc_z1z1    (X Y : N) : cost := d_casc_z1law X Y.
Definition d_casc_z1z2    (X Y : N) : cost := d_casc_z1law X Y.
Definition d_casc_z3 (X Y c2 : N) : cost :=
  cx (2 * X + 2 * Y + 14 * c2 + 49).
Definition lvlc (r : word) : N :=
  match r with
  | g :: _ => gC g
  | [] => 0
  end.
Definition cseg (cols : word) : option (N * N) :=
  match last2 cols with
  | Some (ini, (gao,gaz,gac), (gbo,gbz,gbc)) =>
      if (gao =? 8) && (gaz =? 2) && (gac =? 1)
         && (gbo =? 4) && (gbz =? 2) && (1 <=? gbc)
         && forallb is_col ini
      then Some (ccolcost ini, gbc)
      else if (gbo =? 8) && (gbz =? 2) && (gbc =? 1)
              && forallb is_col (ini ++ [(gao,gaz,gac)])
      then Some (ccolcost (ini ++ [(gao,gaz,gac)]), 0)
      else None
  | None => None
  end.
Definition dseg (cols : word) (L : N -> N) : cost :=
  match cseg cols with
  | Some (pc, gbc) => cx (pc + L gbc)
  | None => cundef
  end.
Definition dseg_endR (cols : word) (f : N) : cost :=
  if 2 <=? f then dseg cols (fun gbc => 14 * gbc + 2 * f + 57)
  else cundef.
Definition dseg_lawR (cols : word) (Bq f : N) : cost :=
  if f =? 4 then dseg cols (fun gbc => 14 * gbc + 14 * Bq + 65)
  else if 5 <=? f then dseg cols (fun gbc => 14 * gbc + 14 * Bq + 2 * f + 57)
  else cundef.
Definition dseg_endY (cols : word) (y : N) : cost :=
  dseg cols (fun gbc => 14 * gbc + 2 * y + 79).
Definition d_rseg_endR (cols : word) (f : N)     : cost := dseg_endR cols f.
Definition d_rseg_lawR (cols : word) (Bq f : N)  : cost := dseg_lawR cols Bq f.
Definition d_rseg_endY (cols : word) (y : N)     : cost := dseg_endY cols y.
Definition d_casc_endR (X cY : N) (cols : word) (f : N) : cost :=
  cadd (d_casc_stage X cY) (dseg_endR cols f).
Definition d_casc_lawR (X cY : N) (cols : word) (Bq f : N) : cost :=
  cadd (d_casc_stage X cY) (dseg_lawR cols Bq f).
Definition d_casc_endY (X cY : N) (cols : word) (y : N) : cost :=
  cadd (d_casc_stage X cY) (dseg_endY cols y).
Definition d_casc_z4 (X cY : N) (cols : word) : cost :=
  cadd (d_casc_stage X cY) (dseg cols (fun gbc => 14 * gbc + 43)).
Definition d_rseg_inner (cols : word) (Bq : N) (cols2 : word) : cost :=
  cx (ccolcost cols + 14 * Bq + 16 + ccolcost cols2).
Definition d_rseg_tail (cols : word) (Bq : N) (cols2 : word) (f : N)
  : cost :=
  if 5 <=? f
  then cx (ccolcost cols + 14 * Bq + ccolcost cols2 + 2 * f + 35)
  else if f =? 4
  then match dtb4_convc cols2 with
       | Some (_, Kd) => cx (ccolcost cols + 14 * Bq + 22 + Kd)
       | None =>
           if forallb w42 cols2
           then cx (ccolcost cols + 14 * Bq + ccolcost cols2 + 43)
           else cundef
       end
  else cundef.
Definition cmap {A B : Type} (g : A -> B) (d : cost) (x : (A * cost)%type)
  : (B * cost)%type := (g (fst x), cadd d (snd x)).
Definition cdrop {A B : Type} (g : A -> B) (d : cost) (x : (A * cost)%type)
  : (B * cost)%type := (g (fst x), d).
Lemma cmap_fst {A B : Type} (g : A -> B) (d : cost) (x : (A * cost)%type) :
  fst (cmap g d x) = g (fst x).
Proof. reflexivity. Qed.
Lemma cdrop_fst {A B : Type} (g : A -> B) (d : cost) (x : (A * cost)%type) :
  fst (cdrop g d x) = g (fst x).
Proof. reflexivity. Qed.
Definition cexact_or_empty (c : cost) : Prop :=
  clo c = chi c \/ (chi c < clo c)%N.
Lemma cexact_or_empty_cx (k : N) : cexact_or_empty (cx k).
Proof. left. reflexivity. Qed.
Lemma cexact_or_empty_czero : cexact_or_empty czero.
Proof. left. reflexivity. Qed.
Lemma cexact_or_empty_cundef : cexact_or_empty cundef.
Proof. right. unfold cundef, clo, chi; cbn [fst snd]; lia. Qed.
Lemma cexact_or_empty_cadd (c1 c2 : cost) :
  cexact_or_empty c1 -> cexact_or_empty c2 -> cexact_or_empty (cadd c1 c2).
Proof. unfold cexact_or_empty, cadd, clo, chi; cbn [fst snd]; lia. Qed.
Fixpoint cleaf_act (s : word) (f : N) {struct s}
  : (option (word * N) * cost)%type :=
  match s with
  | (X,2,1) :: rest =>
      if (5 <=? X) && negb (X =? 8) && negb (X =? 12) then
        match rest with
        | [] =>
            ((if f =? 3 then Some ([(X-1,1,1); (3,1,1)], 4)
              else if f =? 2 then Some ([(X-1,1,1); (5,2,1)], 4)
              else if f =? 4 then Some ([(X-1,1,1); (3,2,1)], f)
              else None), d_cma_far X f)
        | (on,zn,cn) :: t2 =>
            if on =? 1 then (None, d_cma_halt)
            else if (on =? 3) && (zn =? 2) && (cn =? 1) && (f =? 4) then
              ((match t2 with
                | [(o2,z2,c2)] =>
                    if (o2 =? 4) && (z2 =? 2)
                    then Some ((X-1,1,1) :: (3,1,1) :: [(4,2,c2+1)], f)
                    else None
                | [] => Some ((X-1,1,1) :: (3,1,1) :: [(4,2,1)], f)
                | _ => None
                end), d_cma_marker X (cw42l t2))
            else if (on =? 4) && (zn =? 2) then
              ((match t2 with
                | [(o2,z2,c2); (o3,z3,c3)] =>
                    if (1 <=? cn) && (o2 =? 3) && (z2 =? 2) && (c2 =? 1)
                       && (o3 =? 4) && (z3 =? 2) && (f =? 4)
                    then Some ((X-1,1,1) :: (3,2,1)
                               :: (if cn =? 1 then [] else [(on,zn,cn-1)])
                               ++ [(4,1,1); (o3,z3,c3+1)], f)
                    else None
                | [] =>
                    if f =? 4 then Some ((X-1,1,1) :: (3,2,1) :: rest, f)
                    else None
                | _ => None
                end), d_cma_respawn_at X cn t2)
            else if (X =? 6) && (on =? 2) && (zn =? 2) && (cn =? 1)
                    && (f =? 4)
                    && match t2 with
                       | [(o2,z2,_)] => (o2 =? 4) && (z2 =? 2)
                       | _ => false
                       end then
              ((match t2 with
                | [(o2,z2,c2)] => Some ((5,1,1) :: (5,2,1) :: [(o2,z2,c2+1)], f)
                | _ => None
                end), d_cma_622 X (cw42l t2))
            else if (zn =? 1)
                    || ((zn =? 2) && (cn =? 1) && (5 <=? on)
                        && negb (on =? 8) && negb (on =? 12)) then
              cmap (fun oa => match oa with
                              | Some (s', f') => Some ((X,2,1) :: s', f')
                              | None => None
                              end)
                   (d_thru X) (cleaf_act rest f)
            else (None, cundef)
        end
      else (None, cundef)
  | (Aa,1,Cc) :: t =>
      ((if 2 <=? Cc then
          if 2 <=? Aa
          then Some ((Aa,1,1) :: (Aa-1,1,1)
                       :: (if 2 <? Cc then [(Aa,1,Cc-2)] else []) ++ t, f)
          else None
        else if negb (Cc =? 1) || negb (2 <=? Aa) then None
        else
        match t with
        | (Bb, zb, cb) :: t2 =>
            if (zb =? 2) && negb (Bb =? 8)
               && (negb (Bb =? 4)
                   || ((cb =? 1)
                       && match t2 with
                          | (o2,z2,_) :: _ =>
                              negb (((o2 =? 4) || (o2 =? 8)) && (z2 =? 2))
                          | [] => true
                          end))
            then
              if (Bb =? 5) && (cb =? 1)
                 && match t2 with
                    | (o2,z2,_) :: _ => (o2 =? 4) && (z2 =? 2)
                    | [] => false
                    end
              then match t2 with
                   | (o2,z2,c2) :: t3 => Some ((Aa,1,1) :: (o2,z2,c2+1) :: t3, f)
                   | [] => None
                   end
              else if Bb =? 1 then
                (if cb =? 1 then Some ((Aa,3,1) :: t2, f) else None)
              else
                (if (cb =? 1) && (2 <=? Bb)
                 then Some ((Aa,1,1) :: (Bb-1,zb,1) :: t2, f) else None)
            else if (Bb =? 8) && (zb =? 2) && (cb =? 1) then
              Some ((Aa,1,1) :: (7,2,1) :: t2, f)
            else if (Bb =? 4) && (zb =? 2) then
              if cb =? 1
              then Some ((Aa,1,1) :: (3,2,1) :: t2, f)
              else (if 2 <=? cb
                    then Some ((Aa,1,1) :: (3,2,1) :: (Bb,zb,cb-1) :: t2, f)
                    else None)
            else if zb =? 1 then
              if 2 <=? cb then
                (if 2 <=? Bb
                 then Some ((Aa,1,1) :: (Bb-1,1,1) :: (Bb,1,cb-1) :: t2, f)
                 else None)
              else if Bb =? 1 then
                (if cb =? 1 then Some ((Aa,2,1) :: t2, f) else None)
              else
                (if (cb =? 1) && (2 <=? Bb)
                 then Some ((Aa,1,1) :: (Bb-1,zb,cb) :: t2, f)
                 else None)
            else if (3 <=? zb) && (cb =? 1) then
              if Bb =? 1 then Some ((Aa,zb+1,1) :: t2, f)
              else (if 2 <=? Bb
                    then Some ((Aa,1,1) :: (Bb-1,zb,cb) :: t2, f)
                    else None)
            else None
        | [] =>
            if 2 <=? f then Some ([(Aa,1,1)], f - 1)
            else if f =? 1 then Some ([], Aa)
            else None
        end), d_tick Aa)
  | _ => (None, cundef)
  end.
Lemma cleaf_act_proj (s : word) (f : N) :
  fst (cleaf_act s f) = leaf_act s f.
Proof.
  revert f. induction s as [|g s IH]; intros f; [reflexivity|].
  destruct g as [[X z] c].
  destruct z as [|zp]; [cbn [cleaf_act leaf_act fst]; reflexivity|].
  destruct zp as [zp'|zp'|];
    try (cbn [cleaf_act leaf_act fst]; reflexivity).
  destruct zp' as [q|q|];
    try (cbn [cleaf_act leaf_act fst]; reflexivity).
  destruct c as [|cp]; [cbn [cleaf_act leaf_act fst]; reflexivity|].
  destruct cp as [cp'|cp'|];
    try (cbn [cleaf_act leaf_act fst]; reflexivity).
  cbn [cleaf_act leaf_act].
  destruct ((5 <=? X) && negb (X =? 8) && negb (X =? 12));
    [|reflexivity].
  destruct s as [|[[on zn] cn] t2]; [reflexivity|].
  destruct (on =? 1); [reflexivity|].
  destruct ((on =? 3) && (zn =? 2) && (cn =? 1) && (f =? 4)); [reflexivity|].
  destruct ((on =? 4) && (zn =? 2)); [reflexivity|].
  destruct ((X =? 6) && (on =? 2) && (zn =? 2) && (cn =? 1) && (f =? 4)
            && match t2 with
               | [(o2,z2,_)] => (o2 =? 4) && (z2 =? 2)
               | _ => false
               end); [reflexivity|].
  destruct ((zn =? 1)
            || ((zn =? 2) && (cn =? 1) && (5 <=? on)
                && negb (on =? 8) && negb (on =? 12))); [|reflexivity].
  rewrite cmap_fst, IH. reflexivity.
Qed.
Definition cdebris_to_blank (w : word) (f : N) : (res * cost)%type :=
  if f =? 4 then
    match dtb_scan w O None with
    | Some s =>
        match wat w (S s), wat w (S (S s)) with
        | Some (o1,z1,c1), Some (o2,z2,c2) =>
            if (o1 =? 4) && (z1 =? 2) && (o2 =? 3) && (z2 =? 2) && (c2 =? 1)
               && (Nat.eqb (length w) (S (S (S s)))
                   || match wat w (S (S (S s))) with
                      | Some (o3,z3,_) =>
                          (o3 =? 4) && (z3 =? 2)
                          && Nat.eqb (length w) (S (S (S (S s))))
                      | None => false
                      end)
            then
              (let tail :=
                 match wat w (S (S (S s))) with
                 | Some (o3,z3,c3) => [(o3, z3, c3 + 1)]
                 | None => [(4,2,1)]
                 end in
               let mid := if c1 =? 1 then [] else [(o1, z1, c1 - 1)] in
               ROk (subst_at s (length w - s)
                      ([(7,1,1); (3,2,1)] ++ mid ++ [(4,1,1)] ++ tail) w) f,
               cadd (d_dtb_cross w s)
                 (d_dtb_orphan f c1 (cw42at w (S (S (S s))))))
            else if forallb w42 (skipn (S s) w)
                 then (ROk (subst_at s 1 [(7,1,1); (3,2,1)] w) f,
                       cadd (d_dtb_cross w s)
                         (d_dtb_plain f (ccnt (skipn (S s) w))))
                 else (RBad, cundef)
        | _, _ =>
            if forallb w42 (skipn (S s) w)
            then (ROk (subst_at s 1 [(7,1,1); (3,2,1)] w) f,
                  cadd (d_dtb_cross w s)
                    (d_dtb_plain f (ccnt (skipn (S s) w))))
            else (RBad, cundef)
        end
    | None => (RBad, cundef)
    end
  else if 5 <=? f then
    (if forallb (fun g => negb (gO g =? 1)) w
     then (ROk (w ++ [(f - 1, 1, 1)]) 3, d_dtb_far w f)
     else (RBad, cundef))
  else if f =? 3 then
    match dtb_scan w O None with
    | Some s =>
        match wat w (S s) with
        | Some (o1,z1,c1) =>
            if (o1 =? 4) && (z1 =? 2) && (1 <? c1)
               && forallb w42 (skipn (S (S s)) w)
            then (ROk (subst_at s 2
                         [(7,1,1); (3,2,1); (o1,z1,c1-1)] w ++ [(4,1,1)]) 4,
                  cadd (d_dtb_cross w s)
                    (d_dtb_f3 c1 (ccnt (skipn (S (S s)) w))))
            else (RBad, cundef)
        | None => (RBad, cundef)
        end
    | None => (RBad, cundef)
    end
  else (RBad, cundef).
Lemma cdebris_to_blank_proj (w : word) (f : N) :
  fst (cdebris_to_blank w f) = debris_to_blank w f.
Proof.
  unfold cdebris_to_blank, debris_to_blank.
  destruct (f =? 4).
  { destruct (dtb_scan w O None) as [s|]; [|reflexivity].
    destruct (wat w (S s)) as [[[o1 z1] c1]|];
      destruct (wat w (S (S s))) as [[[o2 z2] c2]|];
      try (destruct (forallb w42 (skipn (S s) w)); reflexivity).
    destruct ((o1 =? 4) && (z1 =? 2) && (o2 =? 3) && (z2 =? 2) && (c2 =? 1)
              && (Nat.eqb (length w) (S (S (S s)))
                  || match wat w (S (S (S s))) with
                     | Some (o3,z3,_) =>
                         (o3 =? 4) && (z3 =? 2)
                         && Nat.eqb (length w) (S (S (S (S s))))
                     | None => false
                     end)); [reflexivity|].
    destruct (forallb w42 (skipn (S s) w)); reflexivity. }
  destruct (5 <=? f).
  { destruct (forallb (fun g => negb (gO g =? 1)) w); reflexivity. }
  destruct (f =? 3); [|reflexivity].
  destruct (dtb_scan w O None) as [s|]; [|reflexivity].
  destruct (wat w (S s)) as [[[o1 z1] c1]|]; [|reflexivity].
  destruct ((o1 =? 4) && (z1 =? 2) && (1 <? c1)
            && forallb w42 (skipn (S (S s)) w)); reflexivity.
Qed.
Definition cpair_cost (o z : N) : N := 2 * (o + z) + 2.
Definition cpart (g : bg) (t : N) : N :=
  t * cpair_cost (gO g) (gZ g).
Fixpoint ccross_pairs_from (w : word) (b : nat) : N :=
  match b, w with
  | O, _ => 0
  | S _, [] => 0
  | S b', g :: t => cpart g (gC g) + ccross_pairs_from t b'
  end.
Definition ccross_pairs (w : word) (a b : nat) : N :=
  ccross_pairs_from (skipn a w) (b - a).
Lemma cpair_cost_z2 (o : N) : cpair_cost o 2 = 2 * o + 6.
Proof. unfold cpair_cost. lia. Qed.
Lemma d_thru_is_pair_cost (o : N) : d_thru o = cx (cpair_cost o 2).
Proof. unfold d_thru. rewrite cpair_cost_z2. reflexivity. Qed.
Definition cub_word (w : word) (f : N) : N :=
  ccross_pairs w O (length w) + 2 * f.
Definition cub_return (before after : N) : N := 4 * (before + after) + 64.
Definition cub_step (w : word) (f : N) (r : res) : cost :=
  match r with
  | ROk w' f' => (0, cub_return (cub_word w f) (cub_word w' f'))
  | _ => cundef
  end.
Fixpoint cdeliver_tick (fuel : nat) (w : word) (f : N) (i : nat)
                       (via_debris : bool) {struct fuel} : (res * cost)%type :=
  match fuel with O => (RBad, cundef) | S fuel =>
  match wat w i with
  | None => (RBad, cundef)
  | Some (o, z, c) =>
    if (z =? 1) && (2 <=? o) then
      cmap (fun oa => match oa with
                      | Some (s', f') => ROk (firstn i w ++ s') f'
                      | None => RBad
                      end)
           czero (cleaf_act (skipn i w) f)
    else if 3 <=? z then
      (if c =? 1 then cfire fuel w f i via_debris else (RBad, cundef))
    else if (z =? 2) && (5 <=? o) && negb (o =? 8) && negb (o =? 12) then
      cchain_merge_advance fuel w f i
    else (RBad, cundef)
  end
  end
with cfire (fuel : nat) (w : word) (f : N) (i : nat)
           (via_debris : bool) {struct fuel} : (res * cost)%type :=
  match fuel with O => (RBad, cundef) | S fuel =>
  match wat w i with
  | None => (RBad, cundef)
  | Some (o, z, _) =>
    let nxt := wat w (S i) in
    if 4 <=? z then
      match nxt with
      | Some (on, zn, cn) =>
          ((if negb (z =? 4) then RBad else
            if (o =? 4) && (on =? 4) && (zn =? 2) && (1 <=? cn)
               && match wat w (Nat.pred i),
                        wat w (Nat.pred (Nat.pred i)) with
                  | Some (o1,z1,_), Some (o2,z2,c2) =>
                      Nat.leb 2 i && (o1 =? 4) && (z1 =? 2)
                      && (o2 =? 8) && (z2 =? 2) && (c2 =? 1)
                  | _, _ => false
                  end
            then match wat w (Nat.pred i) with
                 | Some lvlA =>
                     let rep := [(7,1,1); (3,2,1); lvlA; (8,2,1)]
                                ++ (if 1 <? cn then [(4,2,cn-1)] else []) in
                     ROk (subst_at (Nat.pred (Nat.pred i)) 4 rep w) f
                 | None => RBad
                 end
            else if (4 <? o) && (on =? 4) && (zn =? 2) && (1 <=? cn) then
              let rep := (o-1,1,1) :: (7,2,1)
                         :: (if 1 <? cn then [(4,2,cn-1)] else []) in
              ROk (subst_at i 2 rep w) f
            else RBad), d_fire_lvl_nxt o z)
      | None =>
          ((if o =? 4 then
              let far := if 5 <=? z then [(4,z-4,1)] else [] in
              let f'  := if 5 <=? z then f else f + 4 in
              match wat w (Nat.pred i),
                    wat w (Nat.pred (Nat.pred i)) with
              | Some (o1,z1,c1), Some (o2,z2,c2) =>
                  if Nat.leb 2 i && (o1 =? 4) && (z1 =? 2)
                     && (o2 =? 8) && (z2 =? 2) && (1 <=? c2)
                  then ROk (subst_at (Nat.pred (Nat.pred i)) 3
                              ((if 1 <? c2 then [(8,2,c2-1)] else [])
                               ++ [(7,1,1); (3,2,1); (o1,z1,c1)] ++ far) w) f'
                  else if Nat.leb 1 i && (o1 =? 8) && (z1 =? 2) && (1 <=? c1)
                  then ROk (subst_at (Nat.pred i) 2
                              ((if 1 <? c1 then [(8,2,c1-1)] else [])
                               ++ [(7,1,1); (3,2,1)] ++ far) w) f'
                  else RBad
              | Some (o1,z1,c1), None =>
                  if Nat.leb 1 i && (o1 =? 8) && (z1 =? 2) && (1 <=? c1)
                  then ROk (subst_at (Nat.pred i) 2
                              ((if 1 <? c1 then [(8,2,c1-1)] else [])
                               ++ [(7,1,1); (3,2,1)] ++ far) w) f'
                  else RBad
              | _, _ => RBad
              end
            else RBad), d_fire_lvl_end o z f)
      end
    else
    if (o =? 3) && match nxt, wat w (Nat.pred i),
                         wat w (Nat.pred (Nat.pred i)) with
                   | Some (on,zn,cn), Some (o1,z1,c1), Some (o2,z2,c2) =>
                       (on =? 4) && (zn =? 2) && Nat.leb 2 i
                       && (o1 =? 4) && (z1 =? 2)
                       && (o2 =? 8) && (z2 =? 2) && (c2 =? 1)
                       && (1 <=? c1) && (1 <=? cn)
                       && Nat.eqb (S (S i)) (length w)
                       && ((f =? 0) || (f =? 4))
                   | _, _, _ => false
                   end
    then
      ((match wat w (Nat.pred i), nxt with
        | Some (_,_,V), Some (_,_,G) =>
            let rep := [(7,1,1); (3,2,1)]
                       ++ (if 1 <? V then [(4,2,V-1)] else [])
                       ++ [(4,1,1); (7,1,1); (3,2,1)]
                       ++ (if 1 <? G then [(4,2,G-1)] else []) in
            ROk (subst_at (Nat.pred (Nat.pred i)) 4 rep w) f
        | _, _ => RBad
        end), d_fire_dcp3 o)
    else if o =? 4 then crenewal fuel w f i via_debris
    else if negb (5 <=? o) then (RBad, cundef)
    else
    match nxt with
    | Some (on, zn, cn) =>
        if (on =? 4) && (zn =? 2) && (1 <=? cn)
           && Nat.eqb (S (S i)) (length w) && (f =? 4) then
          (let rep := (o-1,1,1) :: (6,1,1) :: (3,2,1)
                      :: (if 1 <? cn then [(4,2,cn-1)] else []) in
           ROk (subst_at i 2 rep w) f, d_fire_c6 o)
        else if (on =? 4) && (zn =? 2) then
          (if negb (1 <=? cn) then (RBad, cundef) else
           let w2 := subst_at i 2
                       ((o-1,1,1) :: (7,2,1)
                        :: (if 1 <? cn then [(4,2,cn-1)] else [])) w in
           let base := if 1 <? cn then S (S (S i)) else S (S i) in
           match tick_target w2 base with
           | Some j =>
               match wat w2 j with
               | Some g2 =>
                   if is_cmf g2
                   then cdrop (fun r => r) (d_fire_casc4 o)
                              (cchain_merge_advance fuel w2 f j)
                   else cdrop (fun r2 => match r2 with
                                         | RHalt => RBad
                                         | _ => r2
                                         end)
                              (d_fire_casc4 o)
                              (cdeliver_tick fuel w2 f j true)
               | None => (RBad, cundef)
               end
           | None => if forallb is_col (skipn base w2)
                     then cdrop (fun r => r) (d_fire_casc4 o)
                                (cdebris_to_blank w2 f)
                     else (RBad, cundef)
           end)
        else if (on =? 8) && (zn =? 2) && (cn =? 1) then
          (let w2 := subst_at i 2 [(o-1,1,1); (11,2,1)] w in
           match tick_target w2 (S (S i)) with
           | Some j =>
               cdrop (fun r2 => match r2 with RHalt => RBad | _ => r2 end)
                     (d_fire_casc8 o) (cdeliver_tick fuel w2 f j true)
           | None => if forallb is_col (skipn (S (S i)) w2)
                     then cdrop (fun r => r) (d_fire_casc8 o)
                                (cdebris_to_blank w2 f)
                     else (RBad, cundef)
           end)
        else if (zn =? 1) && (cn =? 1) && (1 <=? on)
                && Nat.eqb (S (S i)) (length w) then
          ((if 1 <=? f
            then ROk (subst_at i 2 [(o-1,1,1); (on+3,1,1)] w) (f - 1)
            else ROk (subst_at i 2 [(o-1,1,1); (on+2,1,1)] w) 3),
           d_fire_z1end o on f)
        else if (zn =? 3) && (cn =? 1) && (1 <=? on)
                && Nat.eqb (S (S (S i))) (length w)
                && match wat w (S (S i)) with
                   | Some (o2,z2,c2) => (o2 =? 4) && (z2 =? 2) && (1 <=? c2)
                   | None => false
                   end
        then
          ((match wat w (S (S i)) with
            | Some (_,_,c2) =>
                let hd := [(o-1,1,1); (on+2,1,1)] in
                let lvl := if 2 <? c2 then [(4,2,c2-2)] else [] in
                if f =? 4 then
                  ROk (subst_at i 3 (hd ++ [(6,1,1); (3,2,1)]
                         ++ (if 1 <? c2 then [(4,2,c2-1)] else [])) w) f
                else if 5 <=? f then
                  ROk (subst_at i 3 (hd ++ [(7,2,1)]
                         ++ (if 1 <? c2 then [(4,2,c2-1)] else [])
                         ++ [(f-1,1,1)]) w) 3
                else if f =? 3 then
                  ROk (subst_at i 3 (hd ++ [(6,1,1)]
                         ++ (if c2 =? 1 then [(3,1,1)]
                             else [(3,2,1)] ++ lvl ++ [(4,1,1)])) w) 4
                else if f =? 2 then
                  ROk (subst_at i 3 (hd ++ [(6,1,1)]
                         ++ (if c2 =? 1 then [(5,2,1)]
                             else [(3,2,1)] ++ lvl ++ [(6,2,1)])) w) 4
                else if (f =? 0) && (2 <=? c2) then
                  ROk (subst_at i 3 (hd ++ [(6,1,1); (3,2,1)] ++ lvl) w) 4
                else RBad
            | None => RBad
            end), d_fire_z3 o on f)
        else if (zn =? 1) && (cn =? 1) && (1 <=? on)
                && match wat w (S (S i)) with
                   | Some (o2,z2,c2) => (o2 =? 4) && (z2 =? 2) && (1 <=? c2)
                   | None => false
                   end
        then
          ((match wat w (S (S i)) with
            | Some (o2,z2,c2) =>
                let rep := [(o-1,1,1); (on+3,1,1); (3,2,1)]
                           ++ (if 1 <? c2 then [(o2,z2,c2-1)] else []) in
                ROk (subst_at i 3 rep w) f
            | None => RBad
            end), d_fire_z1lvl o on)
        else if (zn =? 1) && (2 <=? cn) && (1 <=? on) then
          (let rep := [(o-1,1,1); (on+3,1,1); (on-1,1,1)]
                      ++ (if 2 <? cn then [(on,1,cn-2)] else []) in
           ROk (subst_at i 2 rep w) f, d_fire_z1split o on)
        else if (zn =? 1) && (cn =? 1) && (1 <=? on)
                && match wat w (S (S i)) with
                   | Some (o2,z2,c2) => (z2 =? 1) && (c2 =? 1) && (1 <=? o2)
                   | None => false
                   end
        then
          ((match wat w (S (S i)) with
            | Some (k,_,_) =>
                if k =? 1
                then ROk (subst_at i 3 [(o-1,1,1); (on+3,2,1)] w) f
                else ROk (subst_at i 3
                            [(o-1,1,1); (on+3,1,1); (k-1,1,1)] w) f
            | None => RBad
            end), d_fire_z1z1 o on)
        else if (zn =? 1) && (cn =? 1) && (1 <=? on)
                && match wat w (S (S i)) with
                   | Some (o2,z2,c2) =>
                       (z2 =? 2) && (1 <=? o2) && (o2 <=? 3) && (c2 =? 1)
                   | None => false
                   end
        then
          ((match wat w (S (S i)) with
            | Some (b,_,_) =>
                if b =? 1
                then ROk (subst_at i 3 [(o-1,1,1); (on+3,3,1)] w) f
                else ROk (subst_at i 3
                            [(o-1,1,1); (on+3,1,1); (b-1,2,1)] w) f
            | None => RBad
            end), d_fire_z1z2 o on)
        else (RBad, cundef)
    | None =>
        ((if 2 <=? f
          then ROk (subst_at i 1 [(o-1,1,1); (f+2,1,1)] w) 3
          else RBad), d_fire_far o f)
    end
  end
  end
with crenewal (fuel : nat) (w : word) (f : N) (i : nat)
              (via_debris : bool) {struct fuel} : (res * cost)%type :=
  match fuel with O => (RBad, cundef) | S fuel =>
  let n := length w in
  let nxt := wat w (S i) in
  let ctx1 := wat w (Nat.pred i) in
  let ctx2 := wat w (Nat.pred (Nat.pred i)) in
  let spacer_ok :=
    Nat.leb 2 i
    && match ctx1, ctx2 with
       | Some (o1,z1,_), Some (o2,z2,c2) =>
           (o1 =? 4) && (z1 =? 2) && (z2 =? 2) && (c2 =? 1)
           && ((o2 =? 8) || (o2 =? 12))
       | _, _ => false
       end in
  match nxt with
  | Some (on, zn, cn) =>
      if (zn =? 3) && (cn =? 1) && Nat.eqb (S (S i)) n then
        ((if negb (1 <=? on) then RBad else
          let far := if 1 <=? f then [(f+2,1,1)] else [] in
          match ctx1, ctx2 with
          | Some (o1,z1,c1), Some (o2,z2,c2) =>
              if Nat.leb 2 i && (o1 =? 4) && (z1 =? 2)
                 && (o2 =? 8) && (z2 =? 2) && (1 <=? c2)
              then ROk (subst_at (Nat.pred (Nat.pred i)) 4
                         ((if 1 <? c2 then [(8,2,c2-1)] else [])
                          ++ [(7,1,1); (3,2,1); (o1,z1,c1); (on+3,1,1)]
                          ++ far) w) 3
              else if Nat.leb 1 i && (o1 =? 8) && (z1 =? 2) && (1 <=? c1)
              then ROk (subst_at (Nat.pred i) 3
                         ((if 1 <? c1 then [(8,2,c1-1)] else [])
                          ++ [(7,1,1); (3,2,1); (on+3,1,1)] ++ far) w) 3
              else RBad
          | Some (o1,z1,c1), None =>
              if Nat.leb 1 i && (o1 =? 8) && (z1 =? 2) && (1 <=? c1)
              then ROk (subst_at (Nat.pred i) 3
                         ((if 1 <? c1 then [(8,2,c1-1)] else [])
                          ++ [(7,1,1); (3,2,1); (on+3,1,1)] ++ far) w) 3
              else RBad
          | _, _ => RBad
          end), d_ren_z3end on f)
      else if (zn =? 1) && (cn =? 1) && spacer_ok
              && match wat w (S (S i)) with
                 | Some (o2,z2,c2) =>
                     (z2 =? 2) && (c2 =? 1) && (o2 <=? 3)
                 | None => false
                 end
      then
        ((match ctx2, ctx1, wat w (S (S i)) with
          | Some (h0,_,_), Some lvlA, Some (b,_,_) =>
              let last :=
                if b =? 1 then [(on+4,3,1)] else [(on+4,1,1); (b-1,2,1)] in
              ROk (subst_at (Nat.pred (Nat.pred i)) 5
                     ([(h0-1,1,1); (3,2,1); lvlA] ++ last) w) f
          | _, _, _ => RBad
          end), d_ren_z1b on)
      else if (zn =? 1) && (cn =? 1) && spacer_ok
              && match wat w (S (S i)) with
                 | Some (_,z2,c2) => (z2 =? 1) && (c2 =? 1)
                 | None => false
                 end
      then
        ((match ctx2, ctx1, wat w (S (S i)) with
          | Some (h0,_,_), Some lvlA, Some (k,_,_) =>
              let last :=
                if k =? 1 then [(on+4,2,1)] else [(on+4,1,1); (k-1,1,1)] in
              ROk (subst_at (Nat.pred (Nat.pred i)) 5
                     ([(h0-1,1,1); (3,2,1); lvlA] ++ last) w) f
          | _, _, _ => RBad
          end), d_ren_z1k on)
      else if (zn =? 3) && (cn =? 1) && (1 <=? on)
              && Nat.ltb (S (S i)) n && spacer_ok
              && Nat.eqb (S (S (S i))) n
              && match wat w (S (S i)) with
                 | Some (o2,z2,c2) => (o2 =? 4) && (z2 =? 2) && (1 <=? c2)
                 | None => false
                 end
      then
        ((match ctx2, ctx1, wat w (S (S i)) with
          | Some (h0,_,_), Some lvlA, Some (_,_,c2) =>
              let hd  := [(h0-1,1,1); (3,2,1); lvlA; (on+3,1,1)] in
              let one := if 1 <? c2 then [(4,2,c2-1)] else [] in
              let lvl := if 2 <? c2 then [(4,2,c2-2)] else [] in
              let at2 := subst_at (Nat.pred (Nat.pred i)) 5 in
              if (f =? 4) || (f =? 0) then
                ROk (at2 (hd ++ [(6,1,1); (3,2,1)] ++ one) w) f
              else if 5 <=? f then
                ROk (at2 (hd ++ [(7,2,1)] ++ one ++ [(f-1,1,1)]) w) 3
              else if f =? 3 then
                ROk (at2 (hd ++ [(6,1,1)]
                          ++ (if c2 =? 1 then [(3,1,1)]
                              else [(3,2,1)] ++ lvl ++ [(4,1,1)])) w) 4
              else if f =? 2 then
                ROk (at2 (hd ++ [(6,1,1)]
                          ++ (if c2 =? 1 then [(5,2,1)]
                              else [(3,2,1)] ++ lvl ++ [(6,2,1)])) w) 4
              else RBad
          | _, _, _ => RBad
          end), d_ren_z3lvl on f)
      else if (on =? 8) && (zn =? 2) && (cn =? 1) then
        match ctx1, ctx2 with
        | Some (o1,z1,c1), Some (o2,z2,c2) =>
            if Nat.leb 2 i && (o1 =? 4) && (z1 =? 2)
               && (o2 =? 8) && (z2 =? 2)
            then
              (let w2 := subst_at (Nat.pred (Nat.pred i)) 4
                           [(7,1,1); (3,2,1); (o1,z1,c1); (12,2,1)] w in
               match tick_target w2 (S (S i)) with
               | Some j =>
                   cdrop (fun r2 => match r2 with RHalt => RBad | _ => r2 end)
                         d_ren_casc8 (cdeliver_tick fuel w2 f j true)
               | None => cdrop (fun r => r) d_ren_casc8
                               (cdebris_to_blank w2 f)
               end)
            else (RBad, cundef)
        | _, _ => (RBad, cundef)
        end
      else if (on =? 4) && (zn =? 2) && (1 <=? cn) then
        (if Nat.eqb (S (S i)) n && (f =? 4) && Nat.leb 1 i
            && match ctx1 with
               | Some (o1,z1,c1) => (z1 =? 2) && (c1 =? 1) && (5 <=? o1)
               | None => false
               end
         then
           ((match ctx1 with
             | Some (h,_,_) =>
                 ROk (subst_at (Nat.pred i) 3
                        ([(h-1,1,1); (3,2,1); (7,1,1); (3,2,1)]
                         ++ (if 1 <? cn then [(4,2,cn-1)] else [])) w) f
             | None => RBad
             end), d_ren_lvl_h cn f)
         else if Nat.eqb (S (S i)) n && (f =? 4) then
           (if spacer_ok then
              ((match ctx2, ctx1 with
                | Some (h0,_,_), Some lvlA =>
                    ROk (subst_at (Nat.pred (Nat.pred i)) 4
                           ([(h0-1,1,1); (3,2,1); lvlA; (7,1,1); (3,2,1)]
                            ++ (if 1 <? cn then [(4,2,cn-1)] else [])) w) f
                | _, _ => RBad
                end), d_ren_lvl_sp cn f)
            else (RBad, cundef))
         else
           (if spacer_ok then
              match ctx2, ctx1 with
              | Some (h0,_,_), Some lvlA =>
                  (let w2 := subst_at (Nat.pred (Nat.pred i)) 4
                               ([(h0-1,1,1); (3,2,1); lvlA; (8,2,1)]
                                ++ (if 1 <? cn then [(4,2,cn-1)] else [])) w in
                   let base := if 1 <? cn then S (S (S i)) else S (S i) in
                   match tick_target w2 base with
                   | Some j =>
                       cdrop (fun r2 => match r2 with
                                        | RHalt => RBad
                                        | _ => r2
                                        end)
                             (d_ren_casc4 cn) (cdeliver_tick fuel w2 f j true)
                   | None => cdrop (fun r => r) (d_ren_casc4 cn)
                                   (cdebris_to_blank w2 f)
                   end)
              | _, _ => (RBad, cundef)
              end
            else (RBad, cundef)))
      else (RBad, cundef)
  | None =>
      ((let far := if 1 <=? f then [(f+3,1,1)] else [] in
        let f'  := if 1 <=? f then 3 else 4 in
        match ctx1, ctx2 with
        | Some (o1,z1,c1), Some (o2,z2,c2) =>
            if Nat.leb 1 i && (o1 =? 8) && (z1 =? 2) && (1 <=? c1)
            then ROk (subst_at (Nat.pred i) 2
                        ((if 1 <? c1 then [(8,2,c1-1)] else [])
                         ++ [(7,1,1); (3,2,1)] ++ far) w) f'
            else if Nat.leb 2 i && (o1 =? 4) && (z1 =? 2)
                    && (o2 =? 8) && (z2 =? 2) && (1 <=? c2)
            then ROk (subst_at (Nat.pred (Nat.pred i)) 3
                        ((if 1 <? c2 then [(8,2,c2-1)] else [])
                         ++ [(7,1,1); (3,2,1); (o1,z1,c1)] ++ far) w) f'
            else RBad
        | Some (o1,z1,c1), None =>
            if Nat.leb 1 i && (o1 =? 8) && (z1 =? 2) && (1 <=? c1)
            then ROk (subst_at (Nat.pred i) 2
                        ((if 1 <? c1 then [(8,2,c1-1)] else [])
                         ++ [(7,1,1); (3,2,1)] ++ far) w) f'
            else RBad
        | _, _ => RBad
        end), d_ren_end f)
  end
  end
with cchain_merge_advance (fuel : nat) (w : word) (f : N) (i : nat)
                          {struct fuel} : (res * cost)%type :=
  match fuel with O => (RBad, cundef) | S fuel =>
  match wat w i with
  | None => (RBad, cundef)
  | Some (o, z, c) =>
      if Nat.eqb (S i) (length w) then
        ((if c =? 1 then far_end_merge_fire w f i else RBad),
         cma_at o z c (d_cma_far o f))
      else
      match wat w (S i) with
      | None => (RBad, cundef)
      | Some (on, zn, cn) =>
          if on =? 1 then
            ((if (1 <=? zn) && (1 <=? cn) then RHalt else RBad), d_cma_halt)
          else if (c =? 1) && (5 <=? o) && (on =? 3) && (zn =? 2) && (cn =? 1)
                  && (f =? 4)
                  && (Nat.eqb (length w) (S (S i))
                      || match wat w (S (S i)) with
                         | Some (o2,z2,_) =>
                             (o2 =? 4) && (z2 =? 2)
                             && Nat.eqb (length w) (S (S (S i)))
                         | None => false
                         end) then
            (let tail :=
               match wat w (S (S i)) with
               | Some (o2,z2,c2) =>
                   if (o2 =? 4) && (z2 =? 2) then [(4,2,c2+1)] else []
               | None => []
               end in
             let klen :=
               match wat w (S (S i)) with
               | Some (o2,z2,_) =>
                   if (o2 =? 4) && (z2 =? 2) then 3%nat else 2%nat
               | None => 2%nat
               end in
             let mid :=
               match wat w (S (S i)) with
               | Some (o2,z2,_) =>
                   if (o2 =? 4) && (z2 =? 2) then []
                   else [(4,2,1)]
               | None => [(4,2,1)]
               end in
             ROk (subst_at i klen
                    ([(o-1,1,1); (3,1,1)] ++ mid ++ tail) w) f,
             cma_at o z c (d_cma_marker o (cw42at w (S (S i)))))
          else if (c =? 1) && (5 <=? o) && (on =? 4) && (zn =? 2) && (f =? 4)
          then
            (let orphan :=
               match wat w (S (S i)), wat w (S (S (S i))) with
               | Some (o2,z2,c2), Some (o3,z3,_) =>
                   (o2 =? 3) && (z2 =? 2) && (c2 =? 1)
                   && (o3 =? 4) && (z3 =? 2) && (1 <=? cn)
                   && Nat.eqb (length w) (S (S (S (S i))))
               | _, _ => false
               end in
             ((if orphan then
                 match wat w (S (S (S i))) with
                 | Some (o3,z3,c3) =>
                     let midlvl := if cn =? 1 then [] else [(on,zn,cn-1)] in
                     ROk (subst_at i 4
                            ([(o-1,1,1); (3,2,1)] ++ midlvl
                             ++ [(4,1,1); (o3,z3,c3+1)]) w) f
                 | None => RBad
                 end
               else if forallb w42 (skipn (S (S i)) w) then
                 ROk (subst_at i 1 [(o-1,1,1); (3,2,1)] w) f
               else RBad),
              cma_at o z c
                (if orphan
                 then d_cma_respawn_orphan o cn (cw42at w (S (S (S i))))
                 else d_cma_respawn_final o
                        (cn + ccnt (skipn (S (S i)) w)))))
          else if (c =? 1) && (o =? 6) && (on =? 2) && (zn =? 2) && (cn =? 1)
                  && (f =? 4)
                  && match wat w (S (S i)) with
                     | Some (o2,z2,_) =>
                         (o2 =? 4) && (z2 =? 2)
                         && Nat.eqb (length w) (S (S (S i)))
                     | None => false
                     end
          then
            ((match wat w (S (S i)) with
              | Some (o2,z2,c2) =>
                  ROk (subst_at i 3 [(5,1,1); (5,2,1); (o2,z2,c2+1)] w) f
              | None => RBad
              end), cma_at o z c (d_cma_622 o (cw42at w (S (S i)))))
          else if zn =? 1 then
            cmap (fun r => match r with RHalt => RBad | _ => r end)
                 (d_thru o) (cdeliver_tick fuel w f (S i) false)
          else if (3 <=? zn) && (cn =? 1) then
            cmap (fun r => match r with RHalt => RBad | _ => r end)
                 (d_thru o) (cdeliver_tick fuel w f (S i) true)
          else if (zn =? 2) && (cn =? 1) && (5 <=? on)
                  && negb (on =? 8) && negb (on =? 12)
          then
            cmap (fun r => match r with RHalt => RBad | _ => r end)
                 (d_thru o) (cchain_merge_advance fuel w f (S i))
          else (RBad, cundef)
      end
  end
  end.
Ltac unhalt_close :=
  first
    [ reflexivity
    | match goal with
      | |- context [ deliver_tick ?a ?b ?c ?d ?e ] =>
          destruct (deliver_tick a b c d e); reflexivity
      | |- context [ chain_merge_advance ?a ?b ?c ?d ] =>
          destruct (chain_merge_advance a b c d); reflexivity
      end ].
Lemma ctick_block_proj (fuel : nat) :
  (forall w f i vd, fst (cdeliver_tick fuel w f i vd)
                    = deliver_tick fuel w f i vd)
  /\ (forall w f i vd, fst (cfire fuel w f i vd) = fire fuel w f i vd)
  /\ (forall w f i vd, fst (crenewal fuel w f i vd)
                       = renewal fuel w f i vd)
  /\ (forall w f i, fst (cchain_merge_advance fuel w f i)
                    = chain_merge_advance fuel w f i).
Proof.
  induction fuel as [|fuel IH].
  { repeat split; reflexivity. }
  destruct IH as [IHdt [IHfi [IHrn IHcm]]].
  repeat split.
  -
    intros w f i vd.
    cbn [cdeliver_tick deliver_tick].
    destruct (wat w i) as [[[o z] c]|]; [|reflexivity].
    destruct ((z =? 1) && (2 <=? o)).
    { rewrite cmap_fst, cleaf_act_proj. reflexivity. }
    destruct (3 <=? z).
    { destruct (c =? 1); [apply IHfi|reflexivity]. }
    destruct ((z =? 2) && (5 <=? o) && negb (o =? 8) && negb (o =? 12));
      [apply IHcm|reflexivity].
  -
    intros w f i vd.
    cbn [cfire fire].
    destruct (wat w i) as [[[o z] c]|]; [|reflexivity].
    destruct (4 <=? z).
    { destruct (wat w (S i)) as [[[on zn] cn]|]; reflexivity. }
    destruct ((o =? 3)
              && match wat w (S i), wat w (Nat.pred i),
                       wat w (Nat.pred (Nat.pred i)) with
                 | Some (on,zn,cn), Some (o1,z1,c1), Some (o2,z2,c2) =>
                     (on =? 4) && (zn =? 2) && Nat.leb 2 i
                     && (o1 =? 4) && (z1 =? 2)
                     && (o2 =? 8) && (z2 =? 2) && (c2 =? 1)
                     && (1 <=? c1) && (1 <=? cn)
                     && Nat.eqb (S (S i)) (length w)
                     && ((f =? 0) || (f =? 4))
                 | _, _, _ => false
                 end); [reflexivity|].
    destruct (o =? 4); [apply IHrn|].
    destruct (negb (5 <=? o)); [reflexivity|].
    destruct (wat w (S i)) as [[[on zn] cn]|]; [|reflexivity].
    destruct ((on =? 4) && (zn =? 2) && (1 <=? cn)
              && Nat.eqb (S (S i)) (length w) && (f =? 4)); [reflexivity|].
    destruct ((on =? 4) && (zn =? 2)).
    { destruct (negb (1 <=? cn)); [reflexivity|].
      match goal with
      | |- context [ tick_target ?a ?b ] =>
          destruct (tick_target a b) as [j|] eqn:Etgt
      end.
      - match goal with
        | |- context [ wat ?a j ] => destruct (wat a j) as [g2|]
        end; [|reflexivity].
        destruct (is_cmf g2).
        + rewrite cdrop_fst, IHcm. reflexivity.
        + rewrite cdrop_fst, IHdt. unhalt_close.
      - match goal with
        | |- context [ forallb is_col ?l ] =>
            destruct (forallb is_col l)
        end; [|reflexivity].
        rewrite cdrop_fst, cdebris_to_blank_proj. reflexivity. }
    destruct ((on =? 8) && (zn =? 2) && (cn =? 1)).
    { match goal with
      | |- context [ tick_target ?a ?b ] =>
          destruct (tick_target a b) as [j|] eqn:Etgt8
      end.
      - rewrite cdrop_fst, IHdt. unhalt_close.
      - match goal with
        | |- context [ forallb is_col ?l ] =>
            destruct (forallb is_col l)
        end; [|reflexivity].
        rewrite cdrop_fst, cdebris_to_blank_proj. reflexivity. }
    destruct ((zn =? 1) && (cn =? 1) && (1 <=? on)
              && Nat.eqb (S (S i)) (length w)); [reflexivity|].
    destruct ((zn =? 3) && (cn =? 1) && (1 <=? on)
              && Nat.eqb (S (S (S i))) (length w)
              && match wat w (S (S i)) with
                 | Some (o2,z2,c2) => (o2 =? 4) && (z2 =? 2) && (1 <=? c2)
                 | None => false
                 end); [reflexivity|].
    destruct ((zn =? 1) && (cn =? 1) && (1 <=? on)
              && match wat w (S (S i)) with
                 | Some (o2,z2,c2) => (o2 =? 4) && (z2 =? 2) && (1 <=? c2)
                 | None => false
                 end); [reflexivity|].
    destruct ((zn =? 1) && (2 <=? cn) && (1 <=? on)); [reflexivity|].
    destruct ((zn =? 1) && (cn =? 1) && (1 <=? on)
              && match wat w (S (S i)) with
                 | Some (o2,z2,c2) => (z2 =? 1) && (c2 =? 1) && (1 <=? o2)
                 | None => false
                 end); [reflexivity|].
    destruct ((zn =? 1) && (cn =? 1) && (1 <=? on)
              && match wat w (S (S i)) with
                 | Some (o2,z2,c2) =>
                     (z2 =? 2) && (1 <=? o2) && (o2 <=? 3) && (c2 =? 1)
                 | None => false
                 end); reflexivity.
  -
    intros w f i vd.
    cbn [crenewal renewal].
    destruct (wat w (S i)) as [[[on zn] cn]|]; [|reflexivity].
    destruct ((zn =? 3) && (cn =? 1) && Nat.eqb (S (S i)) (length w));
      [reflexivity|].
    destruct ((zn =? 1) && (cn =? 1)
              && (Nat.leb 2 i
                  && match wat w (Nat.pred i),
                           wat w (Nat.pred (Nat.pred i)) with
                     | Some (o1,z1,_), Some (o2,z2,c2) =>
                         (o1 =? 4) && (z1 =? 2) && (z2 =? 2) && (c2 =? 1)
                         && ((o2 =? 8) || (o2 =? 12))
                     | _, _ => false
                     end)
              && match wat w (S (S i)) with
                 | Some (o2,z2,c2) => (z2 =? 2) && (c2 =? 1) && (o2 <=? 3)
                 | None => false
                 end); [reflexivity|].
    destruct ((zn =? 1) && (cn =? 1)
              && (Nat.leb 2 i
                  && match wat w (Nat.pred i),
                           wat w (Nat.pred (Nat.pred i)) with
                     | Some (o1,z1,_), Some (o2,z2,c2) =>
                         (o1 =? 4) && (z1 =? 2) && (z2 =? 2) && (c2 =? 1)
                         && ((o2 =? 8) || (o2 =? 12))
                     | _, _ => false
                     end)
              && match wat w (S (S i)) with
                 | Some (_,z2,c2) => (z2 =? 1) && (c2 =? 1)
                 | None => false
                 end); [reflexivity|].
    destruct ((zn =? 3) && (cn =? 1) && (1 <=? on)
              && Nat.ltb (S (S i)) (length w)
              && (Nat.leb 2 i
                  && match wat w (Nat.pred i),
                           wat w (Nat.pred (Nat.pred i)) with
                     | Some (o1,z1,_), Some (o2,z2,c2) =>
                         (o1 =? 4) && (z1 =? 2) && (z2 =? 2) && (c2 =? 1)
                         && ((o2 =? 8) || (o2 =? 12))
                     | _, _ => false
                     end)
              && Nat.eqb (S (S (S i))) (length w)
              && match wat w (S (S i)) with
                 | Some (o2,z2,c2) => (o2 =? 4) && (z2 =? 2) && (1 <=? c2)
                 | None => false
                 end); [reflexivity|].
    destruct ((on =? 8) && (zn =? 2) && (cn =? 1)).
    { destruct (wat w (Nat.pred i)) as [[[o1 z1] c1]|];
        destruct (wat w (Nat.pred (Nat.pred i))) as [[[o2 z2] c2]|];
        try reflexivity.
      destruct (Nat.leb 2 i && (o1 =? 4) && (z1 =? 2)
                && (o2 =? 8) && (z2 =? 2)); [|reflexivity].
      match goal with
      | |- context [ tick_target ?a ?b ] =>
          destruct (tick_target a b) as [j|] eqn:Ert8
      end.
      - rewrite cdrop_fst, IHdt. unhalt_close.
      - rewrite cdrop_fst, cdebris_to_blank_proj. reflexivity. }
    destruct ((on =? 4) && (zn =? 2) && (1 <=? cn)); [|reflexivity].
    destruct (Nat.eqb (S (S i)) (length w) && (f =? 4) && Nat.leb 1 i
              && match wat w (Nat.pred i) with
                 | Some (o1,z1,c1) => (z1 =? 2) && (c1 =? 1) && (5 <=? o1)
                 | None => false
                 end); [reflexivity|].
    destruct (Nat.eqb (S (S i)) (length w) && (f =? 4)).
    { destruct (Nat.leb 2 i
                && match wat w (Nat.pred i),
                         wat w (Nat.pred (Nat.pred i)) with
                   | Some (o1,z1,_), Some (o2,z2,c2) =>
                       (o1 =? 4) && (z1 =? 2) && (z2 =? 2) && (c2 =? 1)
                       && ((o2 =? 8) || (o2 =? 12))
                   | _, _ => false
                   end); reflexivity. }
    destruct (Nat.leb 2 i
              && match wat w (Nat.pred i),
                       wat w (Nat.pred (Nat.pred i)) with
                 | Some (o1,z1,_), Some (o2,z2,c2) =>
                     (o1 =? 4) && (z1 =? 2) && (z2 =? 2) && (c2 =? 1)
                     && ((o2 =? 8) || (o2 =? 12))
                 | _, _ => false
                 end); [|reflexivity].
    destruct (wat w (Nat.pred (Nat.pred i))) as [[[h0 hz] hc]|];
      [|reflexivity].
    destruct (wat w (Nat.pred i)) as [lvlA|]; [|reflexivity].
    match goal with
    | |- context [ tick_target ?a ?b ] =>
        destruct (tick_target a b) as [j|] eqn:Ert4
    end.
    + rewrite cdrop_fst, IHdt. unhalt_close.
    + rewrite cdrop_fst, cdebris_to_blank_proj. reflexivity.
  -
    intros w f i.
    cbn [cchain_merge_advance chain_merge_advance].
    destruct (wat w i) as [[[o z] c]|]; [|reflexivity].
    destruct (Nat.eqb (S i) (length w)); [reflexivity|].
    destruct (wat w (S i)) as [[[on zn] cn]|]; [|reflexivity].
    destruct (on =? 1); [reflexivity|].
    destruct ((c =? 1) && (5 <=? o) && (on =? 3) && (zn =? 2) && (cn =? 1)
              && (f =? 4)
              && (Nat.eqb (length w) (S (S i))
                  || match wat w (S (S i)) with
                     | Some (o2,z2,_) =>
                         (o2 =? 4) && (z2 =? 2)
                         && Nat.eqb (length w) (S (S (S i)))
                     | None => false
                     end)); [reflexivity|].
    destruct ((c =? 1) && (5 <=? o) && (on =? 4) && (zn =? 2) && (f =? 4));
      [reflexivity|].
    destruct ((c =? 1) && (o =? 6) && (on =? 2) && (zn =? 2) && (cn =? 1)
              && (f =? 4)
              && match wat w (S (S i)) with
                 | Some (o2,z2,_) =>
                     (o2 =? 4) && (z2 =? 2)
                     && Nat.eqb (length w) (S (S (S i)))
                 | None => false
                 end); [reflexivity|].
    destruct (zn =? 1).
    { rewrite cmap_fst, IHdt. unhalt_close. }
    destruct ((3 <=? zn) && (cn =? 1)).
    { rewrite cmap_fst, IHdt. unhalt_close. }
    destruct ((zn =? 2) && (cn =? 1) && (5 <=? on)
              && negb (on =? 8) && negb (on =? 12)); [|reflexivity].
    rewrite cmap_fst, IHcm. unhalt_close.
Qed.
Corollary cdeliver_tick_proj (fuel : nat) (w : word) (f : N) (i : nat)
          (vd : bool) :
  fst (cdeliver_tick fuel w f i vd) = deliver_tick fuel w f i vd.
Proof. apply (proj1 (ctick_block_proj fuel)). Qed.
Corollary cfire_proj (fuel : nat) (w : word) (f : N) (i : nat) (vd : bool) :
  fst (cfire fuel w f i vd) = fire fuel w f i vd.
Proof. apply (proj1 (proj2 (ctick_block_proj fuel))). Qed.
Corollary crenewal_proj (fuel : nat) (w : word) (f : N) (i : nat) (vd : bool) :
  fst (crenewal fuel w f i vd) = renewal fuel w f i vd.
Proof. apply (proj1 (proj2 (proj2 (ctick_block_proj fuel)))). Qed.
Corollary cchain_merge_advance_proj (fuel : nat) (w : word) (f : N) (i : nat) :
  fst (cchain_merge_advance fuel w f i) = chain_merge_advance fuel w f i.
Proof. apply (proj2 (proj2 (proj2 (ctick_block_proj fuel)))). Qed.
Fixpoint cfire_comp (n : nat) (s : word) (f : N) {struct n}
  : (option (word * N) * cost)%type :=
  match n with O => (None, cundef) | S n =>
  match s with
  | (X,3,1) :: rest0 =>
    if negb (5 <=? X) then (None, cundef) else
    match rest0 with
    | [] =>
        ((if 2 <=? f then Some ([(X-1,1,1); (f+2,1,1)], 3) else None),
         d_casc_far X f)
    | (Y,zY,cY) :: rest =>
      if (Y =? 4) && (zY =? 2) then
      (let NL := cY in
       if negb (1 <=? NL) then (None, cundef) else
        match rest with
        | [] =>
            ((if f =? 4
              then Some ((X-1,1,1) :: (6,1,1) :: (3,2,1)
                         :: (if 1 <? NL then [(4,2,NL-1)] else []), f)
              else if 5 <=? f
              then Some ((X-1,1,1) :: (7,2,1)
                         :: (if 1 <? NL then [(4,2,NL-1)] else [])
                         ++ [(f-1,1,1)], 3)
              else None), d_casc_lvl_end X NL f)
        | _ =>
            let '(cols, s2) := seek rest in
            match s2 with
            | [] =>
                ((if 5 <=? f
                  then Some ((X-1,1,1) :: (7,2,1) :: (4,2,NL-1) :: cols
                             ++ [(f-1,1,1)], 3)
                  else if f =? 3 then
                    match dtb3_conv ((4,2,NL-1) :: cols) with
                    | Some body =>
                        Some ((X-1,1,1) :: (7,2,1) :: body ++ [(4,1,1)], 4)
                    | None => None
                    end
                  else if f =? 4 then
                    match dtb4_conv ((4,2,NL-1) :: cols) with
                    | Some body => Some ((X-1,1,1) :: (7,2,1) :: body, f)
                    | None => None
                    end
                  else None), d_casc_dtb X NL cols f)
            | (o4,z4,c4) :: s2t =>
                if (o4 =? 4) && (z4 =? 3) && (c4 =? 1) then
                  match s2t with
                  | [] =>
                      ((match endR_seg cols f with
                        | Some seg2 =>
                            Some ((X-1,1,1) :: (7,2,1) :: (4,2,NL-1) :: seg2, 3)
                        | None => None
                        end), d_casc_endR X NL cols f)
                  | (o5,z5,Bq) :: rest2 =>
                      if (o5 =? 4) && (z5 =? 2) then
                        if 1 <=? Bq then
                          match rest2 with
                          | [] =>
                              ((if f =? 4 then
                                  match lawR_seg cols Bq with
                                  | Some seg2 =>
                                      Some ((X-1,1,1) :: (7,2,1) :: (4,2,NL-1)
                                            :: seg2, f)
                                  | None => None
                                  end
                                else if 5 <=? f then
                                  match jump_seg cols Bq with
                                  | Some seg2 =>
                                      Some ((X-1,1,1) :: (7,2,1) :: (4,2,NL-1)
                                            :: seg2 ++ [(f-1,1,1)], 3)
                                  | None => None
                                  end
                                else None), d_casc_lawR X NL cols Bq f)
                          | _ =>
                              match jump_seg cols Bq with
                              | Some seg =>
                                  let '(cols2, s3) := seek rest2 in
                                  let rs := crenew_seg n cols2 s3 f in
                                  match fst rs with
                                  | Some (body, f') =>
                                      (Some ((X-1,1,1) :: (7,2,1)
                                             :: (4,2,NL-1) :: seg ++ body, f'),
                                       cadd (d_casc_stage X NL)
                                         (cadd (d_jsplice cols Bq) (snd rs)))
                                  | None =>
                                  let fc := cfire_comp n s3 f in
                                  match fst fc with
                                  | Some (s3', f') =>
                                      (Some ((X-1,1,1) :: (7,2,1)
                                             :: (4,2,NL-1)
                                             :: seg ++ cols2 ++ s3', f'),
                                       cadd (d_casc_stage X NL)
                                         (cadd (d_jsplice cols Bq)
                                            (cadd (d_cols cols2) (snd fc))))
                                  | None =>
                                      if sand_leaf s3
                                         && forallb (fun g => (gC g =? 0)%N)
                                                    cols2
                                      then (None, cundef) else
                                      let la := cleaf_act s3 f in
                                      match fst la with
                                      | Some (s3', f') =>
                                          (Some ((X-1,1,1) :: (7,2,1)
                                                 :: (4,2,NL-1)
                                                 :: seg ++ cols2 ++ s3', f'),
                                           cadd (d_casc_leafj X NL cols Bq cols2)
                                                (snd la))
                                      | None =>
                                          ((match s3 with
                                            | [] =>
                                                if 5 <=? f
                                                then Some ((X-1,1,1) :: (7,2,1)
                                                           :: (4,2,NL-1)
                                                           :: seg ++ cols2
                                                              ++ [(f-1,1,1)], 3)
                                                else if f =? 4 then
                                                  match dtb4_conv cols2 with
                                                  | Some cols2' =>
                                                      Some ((X-1,1,1)
                                                            :: (7,2,1)
                                                            :: (4,2,NL-1)
                                                            :: seg ++ cols2', f)
                                                  | None =>
                                                      if forallb w42 cols2
                                                      then match lawR_seg cols Bq with
                                                           | Some seg2 =>
                                                               Some ((X-1,1,1)
                                                                     :: (7,2,1)
                                                                     :: (4,2,NL-1)
                                                                     :: seg2
                                                                        ++ cols2, f)
                                                           | None => None
                                                           end
                                                      else None
                                                  end
                                                else None
                                            | _ => None
                                            end),
                                           d_casc_tail X NL cols Bq cols2 f)
                                      end
                                  end
                                  end
                              | None => (None, cundef)
                              end
                          end
                        else (None, cundef)
                      else if (z5 =? 3) && (Bq =? 1)
                              && match rest2 with [] => true | _ => false end
                              && (f =? 4) && (1 <=? o5) then
                        ((match endY_seg cols o5 with
                          | Some seg2 =>
                              Some ((X-1,1,1) :: (7,2,1) :: (4,2,NL-1)
                                    :: seg2, f - 1)
                          | None => None
                          end), d_casc_endY X NL cols o5)
                      else
                        cmap (fun oa =>
                                 match oa with
                                 | Some (s2', f') =>
                                     Some ((X-1,1,1) :: (7,2,1) :: (4,2,NL-1)
                                           :: cols ++ s2', f')
                                 | None => None
                                 end)
                              (d_casc_leaf X NL cols)
                              (cleaf_act ((o4,z4,c4) :: s2t) f)
                  end
                else if (o4 =? 4) && (z4 =? 4) && (c4 =? 1) then
                  ((match s2t with
                    | (on,zn,cn) :: t2 =>
                        if (on =? 4) && (zn =? 2) && (1 <=? cn) then
                          match jump_seg cols cn with
                          | Some seg2 =>
                              Some ((X-1,1,1) :: (7,2,1) :: (4,2,NL-1)
                                    :: seg2 ++ t2, f)
                          | None => None
                          end
                        else None
                    | [] => None
                    end), d_casc_z4 X NL cols)
                else
                  let fc := cfire_comp n ((o4,z4,c4) :: s2t) f in
                  match fst fc with
                  | Some (s2', f') =>
                      (Some ((X-1,1,1) :: (7,2,1) :: (4,2,NL-1)
                             :: cols ++ s2', f'),
                       cadd (d_casc_stage X NL)
                         (cadd (d_cols cols) (snd fc)))
                  | None =>
                      cmap (fun oa =>
                               match oa with
                               | Some (s2', f') =>
                                   Some ((X-1,1,1) :: (7,2,1) :: (4,2,NL-1)
                                         :: cols ++ s2', f')
                               | None => None
                               end)
                            (d_casc_leaf X NL cols)
                            (cleaf_act ((o4,z4,c4) :: s2t) f)
                  end
            end
        end)
      else if (Y =? 8) && (zY =? 2) && (cY =? 1) then
        (let s2 := (X-1,1,1) :: (11,2,1) :: rest in
         match tick_target s2 2 with
         | Some j =>
             if (match wat s2 j with
                 | Some (_,z,_) => z =? 1
                 | None => false
                 end)
             then cmap (fun r => match r with
                                  | ROk s3 f3 => Some (s3, f3)
                                  | _ => None
                                  end)
                        (d_casc_tick8 X (tickcols s2 j))
                        (cdeliver_tick n s2 f j true)
             else (None, cundef)
         | None => (None, cundef)
         end)
      else if (zY =? 1) && (cY =? 1) && (1 <=? Y)
              && match rest with [] => true | _ => false end then
        ((if 2 <=? f then Some ([(X-1,1,1); (Y+3,1,1)], f - 1) else None),
         d_casc_z1end X Y f)
      else if (zY =? 3) && (cY =? 1) && (1 <=? Y) && (f =? 4) then
        ((match rest with
          | [(o2,z2,c2)] =>
              if (o2 =? 4) && (z2 =? 2) && (1 <=? c2)
              then Some ([(X-1,1,1); (Y+2,1,1); (6,1,1); (3,2,1)]
                         ++ (if 1 <? c2 then [(4,2,c2-1)] else []), f)
              else None
          | _ => None
          end), d_casc_z3 X Y (lvlc rest))
      else if (zY =? 1) && (cY =? 1) && (1 <=? Y)
              && match rest with
                 | (o2,z2,c2) :: _ => (o2 =? 4) && (z2 =? 2) && (1 <=? c2)
                 | [] => false
                 end then
        ((match rest with
          | (o2,z2,c2) :: r2 =>
              Some ((X-1,1,1) :: (Y+3,1,1) :: (3,2,1)
                    :: (if 1 <? c2 then [(o2,z2,c2-1)] else []) ++ r2, f)
          | [] => None
          end), d_casc_z1lvl X Y)
      else if (zY =? 1) && (2 <=? cY) && (2 <=? Y) then
        (Some ((X-1,1,1) :: (Y+3,1,1) :: (Y-1,1,1)
               :: (if 2 <? cY then [(Y,1,cY-2)] else []) ++ rest, f),
         d_casc_z1split X Y)
      else if (zY =? 1) && (cY =? 1) && (1 <=? Y)
              && match rest with
                 | (o2,z2,c2) :: _ => (z2 =? 1) && (c2 =? 1) && (1 <=? o2)
                 | [] => false
                 end then
        ((match rest with
          | (k,_,_) :: r2 =>
              if k =? 1
              then Some ((X-1,1,1) :: (Y+3,2,1) :: r2, f)
              else Some ((X-1,1,1) :: (Y+3,1,1) :: (k-1,1,1) :: r2, f)
          | [] => None
          end), d_casc_z1z1 X Y)
      else if (zY =? 1) && (cY =? 1) && (1 <=? Y)
              && match rest with
                 | (o2,z2,c2) :: _ =>
                     (z2 =? 2) && (1 <=? o2) && (o2 <=? 3) && (c2 =? 1)
                 | [] => false
                 end then
        ((match rest with
          | (b,_,_) :: r2 =>
              if b =? 1
              then Some ((X-1,1,1) :: (Y+3,3,1) :: r2, f)
              else Some ((X-1,1,1) :: (Y+3,1,1) :: (b-1,2,1) :: r2, f)
          | [] => None
          end), d_casc_z1z2 X Y)
      else (None, cundef)
    end
  | _ => (None, cundef)
  end
  end
with crenew_seg (n : nat) (cols : word) (s : word) (f : N) {struct n}
  : (option (word * N) * cost)%type :=
  match n with O => (None, cundef) | S n =>
  match s with
  | (4,3,1) :: rest =>
      match rest with
      | [] =>
          ((match endR_seg cols f with
            | Some body => Some (body, 3)
            | None => None
            end), d_rseg_endR cols f)
      | (o5,z5,Bq) :: rest2 =>
          if (o5 =? 4) && (z5 =? 2) && (1 <=? Bq) then
            match rest2 with
            | [] =>
                ((if f =? 4 then
                    match lawR_seg cols Bq with
                    | Some body => Some (body, f)
                    | None => None
                    end
                  else if 5 <=? f then
                    match jump_seg cols Bq with
                    | Some seg => Some (seg ++ [(f-1,1,1)], 3)
                    | None => None
                    end
                  else None), d_rseg_lawR cols Bq f)
            | _ =>
                match jump_seg cols Bq with
                | Some seg =>
                    let '(cols2, s3) := seek rest2 in
                    let rs := crenew_seg n cols2 s3 f in
                    match fst rs with
                    | Some (body, f') =>
                        (Some (seg ++ body, f'),
                         cadd (d_jsplice cols Bq) (snd rs))
                    | None =>
                    let inner :=
                      (match s3 with
                       | (o7,z7,c7) :: _ =>
                           if (z7 =? 3) && (c7 =? 1)
                           then cmap (fun x => x)
                                  (cadd (d_jsplice cols Bq) (d_cols cols2))
                                  (cfire_comp n s3 f)
                           else if sand_leaf s3 then (None, cundef)
                           else cmap (fun x => x)
                                     (d_rseg_inner cols Bq cols2)
                                     (cleaf_act s3 f)
                       | [] => cdrop (fun x => x) cundef (cleaf_act s3 f)
                       end) in
                    match fst inner with
                    | Some (s3', f') =>
                        (Some (seg ++ cols2 ++ s3', f'), snd inner)
                    | None =>
                        ((match s3 with
                          | [] =>
                              if 5 <=? f
                              then Some (seg ++ cols2 ++ [(f-1,1,1)], 3)
                              else if f =? 4 then
                                match dtb4_conv cols2 with
                                | Some cols2' => Some (seg ++ cols2', f)
                                | None =>
                                    if forallb w42 cols2
                                    then match lawR_seg cols Bq with
                                         | Some seg2 => Some (seg2 ++ cols2, f)
                                         | None => None
                                         end
                                    else None
                                end
                              else None
                          | _ => None
                          end), d_rseg_tail cols Bq cols2 f)
                    end
                    end
                | None => (None, cundef)
                end
            end
          else if (z5 =? 3) && (Bq =? 1)
                  && match rest2 with [] => true | _ => false end
                  && (f =? 4) && (1 <=? o5) then
            ((match endY_seg cols o5 with
              | Some body => Some (body, f - 1)
              | None => None
              end), d_rseg_endY cols o5)
          else (None, cundef)
      end
  | _ => (None, cundef)
  end
  end.
Ltac dfc :=
  match goal with
  | |- context [ fst (cfire_comp ?a ?b ?c) ] =>
      destruct (fst (cfire_comp a b c)) as [[? ?]|]
  end.
Ltac drs :=
  match goal with
  | |- context [ fst (crenew_seg ?a ?b ?c ?d) ] =>
      destruct (fst (crenew_seg a b c d)) as [[? ?]|]
  end.
Ltac dla :=
  match goal with
  | |- context [ fst (cleaf_act ?a ?b) ] =>
      destruct (fst (cleaf_act a b)) as [[? ?]|]
  end.
Lemma ccascade_proj (n : nat) :
  (forall s f, fst (cfire_comp n s f) = fire_comp n s f)
  /\ (forall cols s f, fst (crenew_seg n cols s f) = renew_seg n cols s f).
Proof.
  induction n as [|n IH].
  { split; reflexivity. }
  destruct IH as [IHfc IHrs].
  split.
  -
    intros s f.
    destruct s as [|[[X z] c] rest0];
      [cbn [cfire_comp fire_comp fst]; reflexivity|].
    destruct z as [|zp]; [cbn [cfire_comp fire_comp fst]; reflexivity|].
    destruct zp as [zp'|zp'|];
      try (cbn [cfire_comp fire_comp fst]; reflexivity).
    destruct zp' as [q|q|];
      try (cbn [cfire_comp fire_comp fst]; reflexivity).
    destruct c as [|cp]; [cbn [cfire_comp fire_comp fst]; reflexivity|].
    destruct cp as [cp'|cp'|];
      try (cbn [cfire_comp fire_comp fst]; reflexivity).
    cbn [cfire_comp fire_comp].
    destruct (negb (5 <=? X)); [reflexivity|].
    destruct rest0 as [|[[Y zY] cY] rest]; [reflexivity|].
    destruct ((Y =? 4) && (zY =? 2)).
    { destruct (negb (1 <=? cY)); [reflexivity|].
      destruct rest as [|gr rest']; [reflexivity|].
      destruct (seek (gr :: rest')) as [cols s2] eqn:Eseek.
      destruct s2 as [|[[o4 z4] c4] s2t]; [reflexivity|].
      destruct ((o4 =? 4) && (z4 =? 3) && (c4 =? 1)).
      { destruct s2t as [|[[o5 z5] Bq] rest2]; [reflexivity|].
        destruct ((o5 =? 4) && (z5 =? 2)).
        { destruct (1 <=? Bq); [|reflexivity].
          destruct rest2 as [|gr2 rest2']; [reflexivity|].
          destruct (jump_seg cols Bq) as [seg|]; [|reflexivity].
          destruct (seek (gr2 :: rest2')) as [cols2 s3] eqn:Eseek2.
          rewrite <- IHrs. drs; [reflexivity|].
          rewrite <- IHfc. dfc; [reflexivity|].
          destruct (sand_leaf s3
                    && forallb (fun g => (gC g =? 0)%N) cols2);
            [reflexivity|].
          rewrite <- cleaf_act_proj. dla; reflexivity. }
        destruct ((z5 =? 3) && (Bq =? 1)
                  && match rest2 with [] => true | _ => false end
                  && (f =? 4) && (1 <=? o5)); [reflexivity|].
        rewrite cmap_fst, cleaf_act_proj. reflexivity. }
      destruct ((o4 =? 4) && (z4 =? 4) && (c4 =? 1)); [reflexivity|].
      rewrite <- IHfc. dfc; [reflexivity|].
      rewrite cmap_fst, cleaf_act_proj. reflexivity. }
    destruct ((Y =? 8) && (zY =? 2) && (cY =? 1)).
    { match goal with
      | |- context [ tick_target ?a ?b ] =>
          destruct (tick_target a b) as [j|] eqn:Etg
      end; [|reflexivity].
      match goal with
      | |- context [ match wat ?a j with _ => _ end ] =>
          destruct (wat a j) as [[[oq zq] cq]|]
      end.
      - destruct (zq =? 1); [|reflexivity].
        rewrite cmap_fst, cdeliver_tick_proj. reflexivity.
      - reflexivity. }
    destruct ((zY =? 1) && (cY =? 1) && (1 <=? Y)
              && match rest with [] => true | _ => false end); [reflexivity|].
    destruct ((zY =? 3) && (cY =? 1) && (1 <=? Y) && (f =? 4)); [reflexivity|].
    destruct ((zY =? 1) && (cY =? 1) && (1 <=? Y)
              && match rest with
                 | (o2,z2,c2) :: _ => (o2 =? 4) && (z2 =? 2) && (1 <=? c2)
                 | [] => false
                 end); [reflexivity|].
    destruct ((zY =? 1) && (2 <=? cY) && (2 <=? Y)); [reflexivity|].
    destruct ((zY =? 1) && (cY =? 1) && (1 <=? Y)
              && match rest with
                 | (o2,z2,c2) :: _ => (z2 =? 1) && (c2 =? 1) && (1 <=? o2)
                 | [] => false
                 end); [reflexivity|].
    destruct ((zY =? 1) && (cY =? 1) && (1 <=? Y)
              && match rest with
                 | (o2,z2,c2) :: _ =>
                     (z2 =? 2) && (1 <=? o2) && (o2 <=? 3) && (c2 =? 1)
                 | [] => false
                 end); reflexivity.
  -
    intros cols s f.
    destruct s as [|[[o z] c] rest];
      [cbn [crenew_seg renew_seg fst]; reflexivity|].
    destruct o as [|op]; [cbn [crenew_seg renew_seg fst]; reflexivity|].
    destruct op as [op'|op'|];
      try (cbn [crenew_seg renew_seg fst]; reflexivity).
    destruct op' as [q|q|];
      try (cbn [crenew_seg renew_seg fst]; reflexivity).
    destruct q as [r|r|];
      try (cbn [crenew_seg renew_seg fst]; reflexivity).
    destruct z as [|zp]; [cbn [crenew_seg renew_seg fst]; reflexivity|].
    destruct zp as [zp'|zp'|];
      try (cbn [crenew_seg renew_seg fst]; reflexivity).
    destruct zp' as [q|q|];
      try (cbn [crenew_seg renew_seg fst]; reflexivity).
    destruct c as [|cp]; [cbn [crenew_seg renew_seg fst]; reflexivity|].
    destruct cp as [cp'|cp'|];
      try (cbn [crenew_seg renew_seg fst]; reflexivity).
    cbn [crenew_seg renew_seg].
    destruct rest as [|[[o5 z5] Bq] rest2]; [reflexivity|].
    destruct ((o5 =? 4) && (z5 =? 2) && (1 <=? Bq)).
    { destruct rest2 as [|gr2 rest2']; [reflexivity|].
      destruct (jump_seg cols Bq) as [seg|]; [|reflexivity].
      destruct (seek (gr2 :: rest2')) as [cols2 s3] eqn:Eseek2.
      rewrite <- IHrs. drs; [reflexivity|].
      destruct s3 as [|[[o7 z7] c7] s3t]; cbv beta iota.
      - rewrite cdrop_fst; cbv beta.
        rewrite <- cleaf_act_proj. dla; reflexivity.
      - destruct ((z7 =? 3) && (c7 =? 1)).
        + rewrite cmap_fst; cbv beta.
          rewrite <- IHfc. dfc; reflexivity.
        + match goal with
          | |- context [ sand_leaf ?x ] => destruct (sand_leaf x)
          end; [reflexivity|].
          rewrite cmap_fst; cbv beta.
          rewrite <- cleaf_act_proj. dla; reflexivity. }
    destruct ((z5 =? 3) && (Bq =? 1)
              && match rest2 with [] => true | _ => false end
              && (f =? 4) && (1 <=? o5)); reflexivity.
Qed.
Corollary cfire_comp_proj (n : nat) (s : word) (f : N) :
  fst (cfire_comp n s f) = fire_comp n s f.
Proof. apply (proj1 (ccascade_proj n)). Qed.
Corollary crenew_seg_proj (n : nat) (cols s : word) (f : N) :
  fst (crenew_seg n cols s f) = renew_seg n cols s f.
Proof. apply (proj2 (ccascade_proj n)). Qed.
