Inductive ctier : Set := Tloc | Tftrip | Tsand | Tret.
Definition ctier_close (t : ctier) : cost :=
  match t with
  | Tloc   => czero
  | Tftrip => cx 6
  | Tsand  => cx 3
  | Tret   => czero
  end.
Definition cprefix (w : word) (site : nat) : cost :=
  cx (ccolcost (firstn site w)).
Definition cdispatch (t : ctier) (w : word) (site : nat) (d : cost) : cost :=
  match t with
  | Tret => d
  | _    => cadd (cprefix w site) (cadd d (ctier_close t))
  end.
Lemma cdispatch_ret (w : word) (i : nat) (d : cost) :
  cdispatch Tret w i d = d.
Proof. reflexivity. Qed.
Lemma cdispatch_loc (w : word) (i : nat) (K : N) :
  cdispatch Tloc w i (cx K) = cx (ccolcost (firstn i w) + K).
Proof.
  unfold cdispatch, cprefix, ctier_close, cadd, cx, czero; cbn [fst snd].
  f_equal; lia.
Qed.
Lemma cdispatch_ftrip (w : word) (i : nat) (K : N) :
  cdispatch Tftrip w i (cx K) = cx (ccolcost (firstn i w) + (K + 6)).
Proof.
  unfold cdispatch, cprefix, ctier_close, cadd, cx; cbn [fst snd].
  f_equal; lia.
Qed.
Lemma cdispatch_sand (w : word) (i : nat) (K : N) :
  cdispatch Tsand w i (cx K) = cx (ccolcost (firstn i w) + (K + 3)).
Proof.
  unfold cdispatch, cprefix, ctier_close, cadd, cx; cbn [fst snd].
  f_equal; lia.
Qed.
Lemma cexact_or_empty_ctier_close (t : ctier) :
  cexact_or_empty (ctier_close t).
Proof.
  destruct t; cbn [ctier_close];
    [apply cexact_or_empty_czero | apply cexact_or_empty_cx
    |apply cexact_or_empty_cx | apply cexact_or_empty_czero].
Qed.
Lemma cexact_or_empty_cdispatch (t : ctier) (w : word) (i : nat) (d : cost) :
  cexact_or_empty d -> cexact_or_empty (cdispatch t w i d).
Proof.
  intros H. destruct t; cbn [cdispatch]; try exact H;
    (apply cexact_or_empty_cadd;
       [ apply cexact_or_empty_cx
       | apply cexact_or_empty_cadd;
           [exact H | apply cexact_or_empty_ctier_close] ]).
Qed.
Lemma cdispatch_cundef_absurd (t : ctier) (w : word) (i : nat)
      (k : nat) (P : Prop) :
  cin k (cdispatch t w i cundef) -> P.
Proof.
  intros H. exfalso.
  destruct t;
    cbv [cdispatch cprefix ctier_close cin cadd cx czero cundef fst snd] in H;
    lia.
Qed.
Example cdispatch_is_additive (w : word) (i : nat) (K1 K2 : N) :
  cdispatch Tloc w i (cx (K1 + K2))
  = cadd (cdispatch Tloc w i (cx K1)) (cx K2).
Proof.
  rewrite !cdispatch_loc.
  unfold cadd, cx; cbn [fst snd]. f_equal; lia.
Qed.
Lemma cexact_or_empty_dseg (cols : word) (L : N -> N) :
  cexact_or_empty (dseg cols L).
Proof.
  unfold dseg. destruct (cseg cols) as [[pc gbc]|];
    [apply cexact_or_empty_cx | apply cexact_or_empty_cundef].
Qed.
Example dseg_slots_exact_or_empty (cols : word) (Bq f y : N) :
  cexact_or_empty (dseg_endR cols f)
  /\ cexact_or_empty (dseg_lawR cols Bq f)
  /\ cexact_or_empty (dseg_endY cols y).
Proof.
  repeat split;
    unfold dseg_endR, dseg_lawR, dseg_endY;
    repeat (match goal with
            | |- context [ if ?b then _ else _ ] => destruct b
            end);
    try apply cexact_or_empty_dseg; apply cexact_or_empty_cundef.
Qed.
Definition d_jcomp (pre : word) (B : N) (post : word) (f : N) : cost :=
  if negb (forallb is_col pre) then cundef else
  match post with
  | [] => dseg_lawR pre B f
  | _ =>
    match jump_seg pre B with
    | None => cundef
    | Some _ =>
      let '(cols2, s3) := seek post in
      let rs := crenew_seg (List.length s3) cols2 s3 f in
      match fst rs with
      | Some _ => cadd (d_jsplice pre B) (snd rs)
      | None =>
          match s3 with
          | (o7,z7,c7) :: _ =>
              if (z7 =? 3) && (c7 =? 1) then
                let fc := cfire_comp (List.length s3) s3 f in
                match fst fc with
                | Some _ =>
                    cadd (d_jsplice pre B) (cadd (d_cols cols2) (snd fc))
                | None => cundef
                end
              else if sand_leaf s3 then cundef
              else
                let la := cleaf_act s3 f in
                match fst la with
                | Some _ =>
                    cadd (cx (ccolcost pre + 14 * B + 16 + ccolcost cols2))
                         (snd la)
                | None => cundef
                end
          | [] =>
              if 5 <=? f
              then cx (ccolcost pre + 14 * B + 22
                       + (2 * f + 13 + ccolcost cols2))
              else if f =? 4 then
                match dtb4_convc cols2 with
                | Some (_, Kd) => cx (ccolcost pre + 14 * B + 22 + Kd)
                | None =>
                    if forallb w42 cols2 then
                      match lawR_seg pre B with
                      | Some _ =>
                          cx (ccolcost pre + 14 * B + ccolcost cols2 + 43)
                      | None => cundef
                      end
                    else cundef
                end
              else cundef
          end
      end
    end
  end.
Definition d_span2A (w : word) (f : N) : cost :=
  match w with
  | (2,2,a) :: (5,2,1) :: (3,2,m) :: (3,3,1) :: (o0,z0,V) :: rest' =>
      if (o0 =? 4) && (z0 =? 2) && (1 <=? V) then
        let '(cols, s) := seek rest' in
        match s with
        | (_,1,_) :: _ =>
            let la := cleaf_act s f in
            match fst la with
            | Some _ =>
                cadd (cx (10 * a + 10 * m + 14 * V + 34 + ccolcost cols))
                     (snd la)
            | None => cundef
            end
        | (_,3,1) :: _ =>
            let rs := crenew_seg (List.length s) cols s f in
            match fst rs with
            | Some _ => cadd (cx (10 * a + 10 * m + 14 * V + 40)) (snd rs)
            | None =>
                let fc := cfire_comp (List.length s) s f in
                match fst fc with
                | Some _ =>
                    cadd (cx (10 * a + 10 * m + 14 * V + 40 + ccolcost cols))
                         (snd fc)
                | None => cundef
                end
            end
        | _ => cundef
        end
      else cundef
  | _ => cundef
  end.
Definition cadds (a b : cost) : cost :=
  if orb (N.ltb (chi a) (clo a)) (N.ltb (chi b) (clo b))
  then cundef else cadd a b.
Lemma cadds_exact (a b : cost) :
  (clo a <= chi a)%N -> (clo b <= chi b)%N -> cadds a b = cadd a b.
Proof.
  intros Ha Hb. unfold cadds.
  destruct (N.ltb (chi a) (clo a)) eqn:E1; [apply N.ltb_lt in E1; lia|].
  destruct (N.ltb (chi b) (clo b)) eqn:E2; [apply N.ltb_lt in E2; lia|].
  reflexivity.
Qed.
Definition cround_at (cols s : word) (f : N)
  : (option (word * N) * cost)%type :=
  match s with
  | (_,3,1) :: _ =>
      let n := List.length s in
      let rs := crenew_seg n cols s f in
      match fst rs with
      | Some (body, f2) =>
          (Some (body, f2), cadd (cx 6) (snd rs))
      | None =>
          let fc := cfire_comp n s f in
          match fst fc with
          | Some (s2, f2) =>
              (Some (cols ++ s2, f2),
               cadd (cx (ccolcost cols + 6)) (snd fc))
          | None => (None, cundef)
          end
      end
  | _ =>
      let la := cleaf_act s f in
      match fst la with
      | Some (s2, f2) =>
          (Some (cols ++ s2, f2),
           cadd (cx (ccolcost cols)) (snd la))
      | None => (None, cundef)
      end
  end.
Lemma cround_at_proj (cols s : word) (f : N) :
  fst (cround_at cols s f) = round_at cols s f.
Proof.
  unfold cround_at, round_at. cbv zeta.
  assert (LEAF : forall s0 : word,
             fst (match fst (cleaf_act s0 f) with
                  | Some (s2, f2) =>
                      (Some (cols ++ s2, f2),
                       cadd (cx (ccolcost cols)) (snd (cleaf_act s0 f)))
                  | None => (None, cundef)
                  end : (option (word * N) * cost)%type)
             = match leaf_act s0 f with
               | Some (s2, f2) => Some (cols ++ s2, f2)
               | None => None
               end).
  { intros s0. rewrite <- (cleaf_act_proj s0 f).
    destruct (fst (cleaf_act s0 f)) as [[s2 f2]|]; reflexivity. }
  destruct s as [|[[oR zR] cR] tR]; cbv beta iota; [apply LEAF|].
  destruct zR as [|pz]; cbv beta iota; [apply LEAF|].
  destruct pz as [q1|q1|]; cbv beta iota; [|apply LEAF|apply LEAF].
  destruct q1 as [r1|r1|]; cbv beta iota; [apply LEAF|apply LEAF|].
  destruct cR as [|pc]; cbv beta iota; [apply LEAF|].
  destruct pc as [pc'|pc'|]; cbv beta iota; [apply LEAF|apply LEAF|].
  match goal with
  | |- context [ renew_seg ?a ?b ?c ?d ] =>
      rewrite <- (crenew_seg_proj a b c d)
  end.
  match goal with
  | |- context [ fire_comp ?a ?b ?c ] =>
      rewrite <- (cfire_comp_proj a b c)
  end.
  match goal with
  | |- context [ fst (crenew_seg ?a ?b ?c ?d) ] =>
      destruct (fst (crenew_seg a b c d)) as [[body fb]|]
  end; [reflexivity|].
  cbn [fst].
  match goal with
  | |- context [ fst (cfire_comp ?a ?b ?c) ] =>
      destruct (fst (cfire_comp a b c)) as [[s2 g2]|]
  end; reflexivity.
Qed.
Definition cround1g (tail : word) (f : N)
  : (option (word * N) * cost)%type :=
  let '(cols, s) := seek tail in cround_at cols s f.
Lemma cround1g_proj (tail : word) (f : N) :
  fst (cround1g tail f) = round1g tail f.
Proof.
  unfold cround1g, round1g.
  destruct (seek tail) as [cols s]. apply cround_at_proj.
Qed.
Definition cround2g (tail : word) (f : N)
  : (option (word * N) * cost)%type :=
  let '(cols, s) := seek tail in
  let r1 := cround_at cols s f in
  match fst r1 with
  | Some (t2, f2) =>
      let '(cols2, s2) := seek t2 in
      match s2 with
      | [] =>
          ((if f2 =? 4 then
              match dtb4_conv cols2 with
              | Some cols2' => Some (cols2', f2)
              | None => None
              end
            else if 5 <=? f2 then Some (cols2 ++ [(f2-1,1,1)], 3)
            else None),
           cadds (snd r1)
             (if f2 =? 4 then
                match dtb4_convc cols2 with
                | Some (_, Kd) => cx (Kd + 6)
                | None => cundef
                end
              else if 5 <=? f2
              then cx (2 * f2 + 13 + ccolcost cols2 + 6)
              else cundef))
      | _ :: _ =>
          let r2 := cround_at cols2 s2 f2 in
          (fst r2, cadds (snd r1) (snd r2))
      end
  | None => (None, cundef)
  end.
Lemma cround2g_proj (tail : word) (f : N) :
  fst (cround2g tail f) = round2g tail f.
Proof.
  unfold cround2g, round2g. cbv zeta.
  destruct (seek tail) as [cols s].
  rewrite <- (cround_at_proj cols s f).
  destruct (fst (cround_at cols s f)) as [[t2 f2]|]; [|reflexivity].
  destruct (seek t2) as [cols2 s2].
  destruct s2 as [|g2 s2'].
  - cbn [fst].
    destruct (f2 =? 4); [|destruct (5 <=? f2); reflexivity].
    destruct (dtb4_conv cols2); reflexivity.
  - cbn [fst]. apply cround_at_proj.
Qed.
Definition cround2g_pre8 (tail : word) (f g : N)
  : (option word * cost)%type :=
  let '(cols, s) := seek tail in
  let r1 := cround_at cols s f in
  match fst r1 with
  | Some (t2, f2) =>
      let '(cols2, s2) := seek t2 in
      match s2 with
      | [] =>
          if (f2 =? 4) && forallb w42 cols2 then
            match dtb4_conv cols2 with
            | Some _ => (None, cundef)
            | None =>
                (Some cols2,
                 cadds (snd r1)
                   (cx (kdtb_plain (g + w42sum cols2) + 6)))
            end
          else (None, cundef)
      | _ :: _ => (None, cundef)
      end
  | None => (None, cundef)
  end.
Lemma cround2g_pre8_proj (tail : word) (f g : N) :
  fst (cround2g_pre8 tail f g) = round2g_pre8 tail f.
Proof.
  unfold cround2g_pre8, round2g_pre8. cbv zeta.
  destruct (seek tail) as [cols s].
  rewrite <- (cround_at_proj cols s f).
  destruct (fst (cround_at cols s f)) as [[t2 f2]|]; [|reflexivity].
  destruct (seek t2) as [cols2 s2].
  destruct s2 as [|g2 s2']; [|reflexivity].
  cbn [fst].
  destruct ((f2 =? 4) && forallb w42 cols2);
    [|reflexivity].
  destruct (dtb4_conv cols2); reflexivity.
Qed.
Definition d_span8 (w : word) (f : N) : cost :=
  match w with
  | (2,2,cN) :: (4,2,V) :: (4,3,1) :: (4,2,G) :: rest =>
      match rest with
      | [] =>
          if (2 <=? cN) && (1 <=? G) && (f =? 4)
          then cx (28 * cN + 28 * V + 14 * G + 60)
          else if (2 <=? cN) && (1 <=? G) && (5 <=? f)
               then cx (28 * cN + 28 * V + 28 * (G - 1) + 4 * f + 72)
               else cundef
      | _ :: _ =>
          if (2 <=? cN) && (1 <=? G)
          then let r := cround2g rest f in
               match fst r with
               | Some _ =>
                   cadd (cx (28 * cN + 28 * V + 28 * (G - 1) + 46))
                        (snd r)
               | None =>
                   let rp := cround2g_pre8 rest f (G - 1) in
                   match fst rp with
                   | Some _ =>
                       cadd (cx (28 * cN + 28 * V + 14 * (G - 1) + 24))
                            (snd rp)
                   | None => cundef
                   end
               end
          else cundef
      end
  | _ => cundef
  end.
Definition d_span2B (w : word) (f : N) : cost :=
  match w with
  | (2,2,a) :: (5,2,1) :: (3,2,m) :: (2,2,1) :: (4,2,V) :: (4,3,1)
      :: (4,2,G) :: restB =>
      if (1 <=? m) && (1 <=? G)
      then let r := cround2g restB f in
           match fst r with
           | Some _ =>
               cadd (cx (10 * a + 10 * m + 28 * V + 28 * (G - 1) + 97))
                    (snd r)
           | None => cundef
           end
      else cundef
  | _ => cundef
  end.
Definition d_span8orph (w : word) (f : N) : cost :=
  match w with
  | (2,2,cN) :: (4,2,V) :: (3,2,1) :: (4,2,W) :: (4,3,1)
      :: (4,2,G) :: restB =>
      if (2 <=? cN) && (1 <=? V) && (1 <=? G)
      then let r := cround1g ((if 1 <? G then [(4,2,G-1)] else [])
                              ++ restB) f in
           match fst r with
           | Some _ => cadd (cx (28 * cN + 28 * V + 14 * W + 37)) (snd r)
           | None => cundef
           end
      else cundef
  | _ => cundef
  end.
Definition d_lcol (gbc : N) : N := 14 * gbc + 43.
Definition d_lcstd (X : N) : N := 2 * X + 13.
Definition d_comp (w : word) (f : N) (hint : nat) : cost :=
  let start :=
    match w with
    | (2,2,_) :: _ => if Nat.ltb hint 1 then 1%nat else hint
    | _ => hint
    end in
  match find_active w start with
  | Some i =>
      let w1 :=
        match w with
        | g0 :: t => (2, 2, gC g0 + 1) :: t
        | [] => w
        end in
      let sfx := skipn i w1 in
      match sfx with
      | [] => cundef
      | (o4,z4,c4) :: s2t =>
          if (o4 =? 4) && (z4 =? 3) && (c4 =? 1) && Nat.leb 3 i then
            match s2t with
            | [] =>
                cdispatch Tftrip w 1%nat
                  (dseg_endR (skipn 1 (firstn i w1)) f)
            | (o5,z5,Bq) :: rest2 =>
                if (o5 =? 4) && (z5 =? 2) then
                  (if 1 <=? Bq
                   then cdispatch Tftrip w 1%nat
                          (d_jcomp (skipn 1 (firstn i w1)) Bq rest2 f)
                   else cundef)
                else if (z5 =? 3) && (Bq =? 1)
                        && (match rest2 with [] => true | _ => false end)
                        && (f =? 4) && (1 <=? o5)
                     then cdispatch Tftrip w 1%nat
                            (dseg_endY (skipn 1 (firstn i w1)) o5)
                else
                  cdispatch Tftrip w i
                    (snd (cfire_comp (List.length sfx) sfx f))
            end
          else if (z4 =? 3) && (c4 =? 1) then
            cdispatch Tftrip w i (snd (cfire_comp (List.length sfx) sfx f))
          else if z4 =? 1 then
            cdispatch Tloc w i (snd (cleaf_act sfx f))
          else if (z4 =? 4) && (c4 =? 1) then
            match s2t with
            | (on,zn,cn) :: _ =>
                if (o4 =? 4) && (on =? 4) && (zn =? 2) && (1 <=? cn) then
                  match last2 (firstn i w1) with
                  | Some (ini, (ga,gaz,gac), (gb,gbz,gbc)) =>
                      if (ga =? 8) && (gaz =? 2) && (gac =? 1)
                         && (gb =? 4) && (gbz =? 2) && (1 <=? gbc)
                      then cdispatch Tftrip w (List.length ini)
                             (cx (d_lcol gbc))
                      else cundef
                  | None => cundef
                  end
                else if (4 <? o4) && (on =? 4) && (zn =? 2)
                        && (1 <=? cn) then
                  cdispatch Tftrip w i (cx (d_lcstd o4))
                else cundef
            | [] =>
                if (o4 =? 4) && (1 <=? f) then
                  match last2 (firstn i w1) with
                  | Some (ini, (ga,gaz,gac), (gb,gbz,gbc)) =>
                      if (ga =? 8) && (gaz =? 2) && (gac =? 1)
                         && (gb =? 4) && (gbz =? 2) && (1 <=? gbc)
                      then cdispatch Tftrip w (List.length ini)
                             (cx (d_lcol gbc))
                      else if (gb =? 8) && (gbz =? 2) && (gbc =? 1)
                      then cdispatch Tftrip w (S (List.length ini))
                             (cx (d_lcol 0))
                      else cundef
                  | None => cundef
                  end
                else cundef
            end
          else cundef
      end
  | None =>
      match w with
      | g0i :: t =>
          let start2 :=
            match w with
            | (2,2,_) :: (5,2,_) :: (3,2,_) :: (2,2,1) :: _ => 4%nat
            | (2,2,_) :: (5,2,_) :: (3,2,_) :: _ => 3%nat
            | _ => 1%nat
            end in
          match cmf_from w (Nat.max 1 start2) (List.length w) with
          | Some j =>
              let w1 := (2, 2, gC g0i + 1) :: t in
              cdispatch Tloc w j (snd (cleaf_act (skipn j w1) f))
          | None => cundef
          end
      | [] => cundef
      end
  end.
Definition ccbase (w : word) : nat -> N :=
  fun site => ccolcost (firstn site w).
Definition cdispatch_from (base : nat -> N) (t : ctier) (site : nat)
                          (d : cost) : cost :=
  match t with
  | Tret => d
  | _    => cadd (cx (base site)) (cadd d (ctier_close t))
  end.
Lemma cdispatch_from_ccbase (t : ctier) (w : word) (site : nat) (d : cost) :
  cdispatch_from (ccbase w) t site d = cdispatch t w site d.
Proof. destruct t; reflexivity. Qed.
Definition d_comp_from (base : nat -> N) (w : word) (f : N) (hint : nat)
  : cost :=
  let start :=
    match w with
    | (2,2,_) :: _ => if Nat.ltb hint 1 then 1%nat else hint
    | _ => hint
    end in
  match find_active w start with
  | Some i =>
      let w1 :=
        match w with
        | g0 :: t => (2, 2, gC g0 + 1) :: t
        | [] => w
        end in
      let sfx := skipn i w1 in
      match sfx with
      | [] => cundef
      | (o4,z4,c4) :: s2t =>
          if (o4 =? 4) && (z4 =? 3) && (c4 =? 1) && Nat.leb 3 i then
            match s2t with
            | [] =>
                cdispatch_from base Tftrip 1%nat
                  (dseg_endR (skipn 1 (firstn i w1)) f)
            | (o5,z5,Bq) :: rest2 =>
                if (o5 =? 4) && (z5 =? 2) then
                  (if 1 <=? Bq
                   then cdispatch_from base Tftrip 1%nat
                          (d_jcomp (skipn 1 (firstn i w1)) Bq rest2 f)
                   else cundef)
                else if (z5 =? 3) && (Bq =? 1)
                        && (match rest2 with [] => true | _ => false end)
                        && (f =? 4) && (1 <=? o5)
                     then cdispatch_from base Tftrip 1%nat
                            (dseg_endY (skipn 1 (firstn i w1)) o5)
                else
                  cdispatch_from base Tftrip i
                    (snd (cfire_comp (List.length sfx) sfx f))
            end
          else if (z4 =? 3) && (c4 =? 1) then
            cdispatch_from base Tftrip i
              (snd (cfire_comp (List.length sfx) sfx f))
          else if z4 =? 1 then
            cdispatch_from base Tloc i (snd (cleaf_act sfx f))
          else if (z4 =? 4) && (c4 =? 1) then
            match s2t with
            | (on,zn,cn) :: _ =>
                if (o4 =? 4) && (on =? 4) && (zn =? 2) && (1 <=? cn) then
                  match last2 (firstn i w1) with
                  | Some (ini, (ga,gaz,gac), (gb,gbz,gbc)) =>
                      if (ga =? 8) && (gaz =? 2) && (gac =? 1)
                         && (gb =? 4) && (gbz =? 2) && (1 <=? gbc)
                      then cdispatch_from base Tftrip (List.length ini)
                             (cx (d_lcol gbc))
                      else cundef
                  | None => cundef
                  end
                else if (4 <? o4) && (on =? 4) && (zn =? 2)
                        && (1 <=? cn) then
                  cdispatch_from base Tftrip i (cx (d_lcstd o4))
                else cundef
            | [] =>
                if (o4 =? 4) && (1 <=? f) then
                  match last2 (firstn i w1) with
                  | Some (ini, (ga,gaz,gac), (gb,gbz,gbc)) =>
                      if (ga =? 8) && (gaz =? 2) && (gac =? 1)
                         && (gb =? 4) && (gbz =? 2) && (1 <=? gbc)
                      then cdispatch_from base Tftrip (List.length ini)
                             (cx (d_lcol gbc))
                      else if (gb =? 8) && (gbz =? 2) && (gbc =? 1)
                      then cdispatch_from base Tftrip (S (List.length ini))
                             (cx (d_lcol 0))
                      else cundef
                  | None => cundef
                  end
                else cundef
            end
          else cundef
      end
  | None =>
      match w with
      | g0i :: t =>
          let start2 :=
            match w with
            | (2,2,_) :: (5,2,_) :: (3,2,_) :: (2,2,1) :: _ => 4%nat
            | (2,2,_) :: (5,2,_) :: (3,2,_) :: _ => 3%nat
            | _ => 1%nat
            end in
          match cmf_from w (Nat.max 1 start2) (List.length w) with
          | Some j =>
              let w1 := (2, 2, gC g0i + 1) :: t in
              cdispatch_from base Tloc j (snd (cleaf_act (skipn j w1) f))
          | None => cundef
          end
      | [] => cundef
      end
  end.
Lemma d_comp_from_base (w : word) (f : N) (hint : nat) :
  d_comp_from (ccbase w) w f hint = d_comp w f hint.
Proof. reflexivity. Qed.
Lemma d_comp_from_cong (b1 b2 : nat -> N) (w : word) (f : N) (hint : nat) :
  (forall s : nat, b1 s = b2 s) ->
  d_comp_from b1 w f hint = d_comp_from b2 w f hint.
Proof.
  intros HB. unfold d_comp_from, cdispatch_from.
  destruct (find_active w _) as [i|].
  - destruct (skipn i _) as [|[[o4 z4] c4] s2t]; [reflexivity|].
    destruct ((o4 =? 4) && (z4 =? 3) && (c4 =? 1) && Nat.leb 3 i).
    + destruct s2t as [|[[o5 z5] Bq] rest2]; [rewrite HB; reflexivity|].
      destruct ((o5 =? 4) && (z5 =? 2)).
      * destruct (1 <=? Bq); [rewrite HB|]; reflexivity.
      * destruct ((z5 =? 3) && (Bq =? 1)
                  && (match rest2 with [] => true | _ => false end)
                  && (f =? 4) && (1 <=? o5));
          [rewrite HB; reflexivity|].
        rewrite HB; reflexivity.
    + destruct ((z4 =? 3) && (c4 =? 1)); [rewrite HB; reflexivity|].
      destruct (z4 =? 1); [rewrite HB; reflexivity|].
      destruct ((z4 =? 4) && (c4 =? 1)); [|reflexivity].
      destruct s2t as [|[[on zn] cn] t2].
      * destruct ((o4 =? 4) && (1 <=? f)); [|reflexivity].
        match goal with |- context [last2 ?a] =>
          destruct (last2 a)
            as [[[ini [[ga gaz] gac]] [[gb gbz] gbc]]|] end;
          [|reflexivity].
        destruct ((ga =? 8) && (gaz =? 2) && (gac =? 1)
                  && (gb =? 4) && (gbz =? 2) && (1 <=? gbc));
          [rewrite HB; reflexivity|].
        destruct ((gb =? 8) && (gbz =? 2) && (gbc =? 1));
          [rewrite HB|]; reflexivity.
      * destruct ((o4 =? 4) && (on =? 4) && (zn =? 2) && (1 <=? cn)).
        -- match goal with |- context [last2 ?a] =>
             destruct (last2 a)
               as [[[ini [[ga gaz] gac]] [[gb gbz] gbc]]|] end;
             [|reflexivity].
           destruct ((ga =? 8) && (gaz =? 2) && (gac =? 1)
                     && (gb =? 4) && (gbz =? 2) && (1 <=? gbc));
             [rewrite HB|]; reflexivity.
        -- destruct ((4 <? o4) && (on =? 4) && (zn =? 2) && (1 <=? cn));
             [rewrite HB|]; reflexivity.
  - destruct w as [|g0i t]; [reflexivity|].
    destruct (cmf_from _ _ _) as [j|]; [rewrite HB|]; reflexivity.
Qed.
Lemma ccolcost_app (a b : word) :
  ccolcost (a ++ b) = ccolcost a + ccolcost b.
Proof.
  induction a as [|g t IH]; cbn [ccolcost app].
  - reflexivity.
  - rewrite IH, N.add_assoc. reflexivity.
Qed.
Lemma ccolcost_split (w : word) (s : nat) :
  ccolcost w = ccolcost (firstn s w) + ccolcost (skipn s w).
Proof.
  transitivity (ccolcost (firstn s w ++ skipn s w)).
  - rewrite firstn_skipn. reflexivity.
  - apply ccolcost_app.
Qed.
Definition ccbase_suf (S : N) (w : word) : nat -> N :=
  fun s => S - ccolcost (skipn s w).
Lemma ccbase_suf_ok (w : word) (s : nat) :
  ccbase_suf (ccolcost w) w s = ccbase w s.
Proof.
  unfold ccbase_suf, ccbase.
  pose proof (ccolcost_split w s) as H. lia.
Qed.
Lemma nleb_le : forall a s : nat, Nat.leb a s = true -> (a <= s)%nat.
Proof.
  induction a as [|a IH]; intros [|s] E; cbn in E;
    try discriminate; try lia.
  apply IH in E. lia.
Qed.
Lemma nleb_gt : forall a s : nat, Nat.leb a s = false -> (s < a)%nat.
Proof.
  induction a as [|a IH]; intros [|s] E; cbn in E;
    try discriminate; try lia.
  apply IH in E. lia.
Qed.
Definition ccg (g : bg) : N := gC g * (2 * gO g + 6).
Lemma ccolcost_cons (g : bg) (t : word) :
  ccolcost (g :: t) = ccg g + ccolcost t.
Proof. reflexivity. Qed.
Definition ccolrange (w : word) (a s : nat) : N :=
  if Nat.leb s a then 0 else ccolcost (firstn (s - a)%nat (skipn a w)).
Lemma ccolcost_firstn_add (w : word) (a k : nat) :
  ccolcost (firstn (a + k)%nat w)
  = ccolcost (firstn a w) + ccolcost (firstn k (skipn a w)).
Proof.
  rewrite <- ccolcost_app. f_equal.
  rewrite <- (firstn_skipn a (firstn (a + k)%nat w)) at 1.
  rewrite List.firstn_firstn.
  replace (Nat.min a (a + k)) with a by lia.
  rewrite <- (List.firstn_skipn_comm k a w). reflexivity.
Qed.
Lemma ccolrange_ok (w : word) (a s : nat) :
  (a <= s)%nat ->
  ccolcost (firstn s w) = ccolcost (firstn a w) + ccolrange w a s.
Proof.
  intros H. unfold ccolrange.
  destruct (Nat.leb s a) eqn:E.
  - apply nleb_le in E.
    replace s with a by lia. lia.
  - apply nleb_gt in E.
    replace s with (a + (s - a))%nat at 1 by lia.
    apply ccolcost_firstn_add.
Qed.
Definition cadjust (A : N) (a : nat) (w : word) (s : nat) : N :=
  if Nat.leb a s then A + ccolrange w a s
  else if Nat.leb (a - s)%nat s then A - ccolrange w s a
  else ccolcost (firstn s w).
Lemma cadjust_ok (A : N) (a : nat) (w : word) (s : nat) :
  A = ccolcost (firstn a w) -> cadjust A a w s = ccbase w s.
Proof.
  intros HA. unfold cadjust, ccbase.
  destruct (Nat.leb a s) eqn:E1.
  - apply nleb_le in E1.
    rewrite HA. symmetry. now apply ccolrange_ok.
  - apply nleb_gt in E1.
    destruct (Nat.leb (a - s)%nat s) eqn:E2.
    + assert (Hs : (s <= a)%nat) by lia.
      pose proof (ccolrange_ok w s a Hs) as H.
      rewrite HA, H. lia.
    + reflexivity.
Qed.
Definition chd (w : word) : N :=
  match w with [] => 0 | g :: _ => ccg g end.
Definition cpre_shift (w w' : word) (n : nat) : Prop :=
  ccolcost (firstn n w') = ccolcost (firstn n w) - chd w + chd w'.
Lemma cpre_shift_head (g g' : bg) (t t' : word) (n : nat) :
  firstn n t = firstn n t' ->
  cpre_shift (g :: t) (g' :: t') (S n).
Proof.
  intros Ht. unfold cpre_shift, chd.
  cbn [firstn]. rewrite !ccolcost_cons, Ht. lia.
Qed.
Definition goz_eqb (g1 g2 : bg) : bool :=
  andb (gO g1 =? gO g2) (gZ g1 =? gZ g2).
Definition cnext (A : N) (a : nat) (w : word) (i : nat) (w' : word)
  : nat * N :=
  match i with
  | S (S (S _)) =>
      match skipn (i - 3)%nat w with
      | g1 :: g2 :: g3 :: _ =>
          if andb (negb (goz_eqb g1 g2)) (negb (goz_eqb g2 g3))
          then ((i - 2)%nat,
                cadjust A a w (i - 2)%nat - chd w + chd w')
          else (O, 0)
      | _ => (O, 0)
      end
  | _ => (O, 0)
  end.
Lemma cnext_reset (w w' : word) (n : nat) :
  ccolcost (firstn O w') = 0.
Proof. reflexivity. Qed.
Theorem cnext_ok (A : N) (a : nat) (w : word) (i : nat) (w' : word) :
  A = ccolcost (firstn a w) ->
  cpre_shift w w' (i - 2)%nat ->
  snd (cnext A a w i w') = ccolcost (firstn (fst (cnext A a w i w')) w').
Proof.
  intros HA HS. unfold cnext.
  destruct i as [|i1]; [reflexivity|].
  destruct i1 as [|i2]; [reflexivity|].
  destruct i2 as [|i3]; [reflexivity|].
  destruct (skipn (S (S (S i3)) - 3)%nat w) as [|g1 [|g2 [|g3 tl]]];
    try reflexivity.
  destruct (andb (negb (goz_eqb g1 g2)) (negb (goz_eqb g2 g3)));
    [|reflexivity].
  cbn [fst snd].
  unfold cpre_shift in HS.
  rewrite (cadjust_ok A a w _ HA). unfold ccbase. lia.
Qed.
Close Scope N_scope.
Definition front_costs : list (word -> N -> cost) :=
  [d_primordial; d_prim4; d_clean; d_four; d_span2A; d_span2A';
   d_span2C'; d_span8far; d_span2B; d_span8orph; d_span8;
   d_rot; d_502; d_512; d_522].
Definition cfront_rules : list (word -> N -> option (res * cost)) :=
  zipdec front_rules front_costs.
Definition cstep_front (w : word) (f : N) : option (res * cost) :=
  cfirst_rule cfront_rules w f.
Lemma cstep_front_proj (w : word) (f : N) :
  option_map fst (cstep_front w f) = first_rule front_rules w f.
Proof. apply cfirst_rule_proj. Qed.
Definition cstep (w : word) (f : N) (h : nat) : res * nat * cost :=
  match cstep_front w f with
  | Some (r, d) =>
      ((match r with
        | ROk w2 f2 => ROk (normalize w2) f2
        | RHalt => RBad
        | RBad => RBad
        end), O, d)
  | None =>
      let '(r, i) := step_after_front None w f h in
      (r, i, match r with
             | RHalt => d_guard w i
             | ROk _ _ => d_comp w f h
             | RBad => cundef
             end)
  end.
Theorem cstep_proj (w : word) (f : N) (h : nat) :
  cproj (cstep w f h) = step w f h.
Proof.
  unfold cstep, cproj, step.
  pose proof (cstep_front_proj w f) as HP.
  destruct (cstep_front w f) as [[r d]|] eqn:E.
  - cbn [option_map fst] in HP. rewrite <- HP.
    unfold step_after_front, step_after_front_with,
           step_after_front_with_guard.
    destruct r; reflexivity.
  - cbn [option_map] in HP. rewrite <- HP.
    destruct (step_after_front None w f h) as [r i] eqn:E2.
    reflexivity.
Qed.
Corollary cstep_res (w : word) (f : N) (h : nat) (r : res) (i : nat)
          (d : cost) :
  cstep w f h = (r, i, d) -> step w f h = (r, i).
Proof.
  intros E. rewrite <- cstep_proj. unfold cproj. rewrite E. reflexivity.
Qed.
Corollary cstep_of_step (w : word) (f : N) (h : nat) (r : res) (i : nat) :
  step w f h = (r, i) ->
  exists d, cstep w f h = (r, i, d).
Proof.
  intros E. exists (snd (cstep w f h)).
  pose proof (cstep_proj w f h) as HP. rewrite E in HP.
  unfold cproj in HP.
  destruct (cstep w f h) as [[r' i'] d']; cbn [fst snd] in HP |- *.
  injection HP as <- <-. reflexivity.
Qed.
Definition cstep_from (base : nat -> N) (w : word) (f : N) (h : nat)
  : res * nat * cost :=
  match cstep_front w f with
  | Some (r, d) =>
      ((match r with
        | ROk w2 f2 => ROk (normalize w2) f2
        | RHalt => RBad
        | RBad => RBad
        end), O, d)
  | None =>
      let '(r, i) := step_after_front None w f h in
      (r, i, match r with
             | RHalt => d_guard w i
             | ROk _ _ => d_comp_from base w f h
             | RBad => cundef
             end)
  end.
Lemma cstep_from_base (w : word) (f : N) (h : nat) :
  cstep_from (ccbase w) w f h = cstep w f h.
Proof. reflexivity. Qed.
Lemma cstep_from_cong (b1 b2 : nat -> N) (w : word) (f : N) (h : nat) :
  (forall s : nat, b1 s = b2 s) ->
  cstep_from b1 w f h = cstep_from b2 w f h.
Proof.
  intros HB. unfold cstep_from.
  destruct (cstep_front w f) as [[r d]|]; [reflexivity|].
  destruct (step_after_front None w f h) as [r i].
  rewrite (d_comp_from_cong b1 b2 w f h HB). reflexivity.
Qed.
Corollary cstep_from_ccbase (base : nat -> N) (w : word) (f : N) (h : nat) :
  (forall s : nat, base s = ccbase w s) ->
  cstep_from base w f h = cstep w f h.
Proof.
  intros HB. rewrite (cstep_from_cong base (ccbase w) w f h HB).
  apply cstep_from_base.
Qed.
Corollary cstep_from_cadjust (A : N) (a : nat) (w : word) (f : N) (h : nat) :
  A = ccolcost (firstn a w) ->
  cstep_from (cadjust A a w) w f h = cstep w f h.
Proof.
  intros HA. apply cstep_from_ccbase. intros s. now apply cadjust_ok.
Qed.
Corollary cstep_from_reset (w : word) (f : N) (h : nat) :
  cstep_from (cadjust 0%N O w) w f h = cstep w f h.
Proof. apply cstep_from_cadjust. reflexivity. Qed.
Theorem cstep_from_proj (base : nat -> N) (w : word) (f : N) (h : nat) :
  cproj (cstep_from base w f h) = step w f h.
Proof.
  unfold cstep_from, cproj, step.
  pose proof (cstep_front_proj w f) as HP.
  destruct (cstep_front w f) as [[r d]|] eqn:E.
  - cbn [option_map fst] in HP. rewrite <- HP.
    unfold step_after_front, step_after_front_with,
           step_after_front_with_guard.
    destruct r; reflexivity.
  - cbn [option_map] in HP. rewrite <- HP.
    destruct (step_after_front None w f h) as [r i] eqn:E2.
    reflexivity.
Qed.
Corollary cstep_from_res (base : nat -> N) (w : word) (f : N) (h : nat)
          (r : res) (i : nat) (d : cost) :
  cstep_from base w f h = (r, i, d) -> step w f h = (r, i).
Proof.
  intros E. rewrite <- (cstep_from_proj base). unfold cproj.
  rewrite E. reflexivity.
Qed.
Lemma cstep_deliver (w : word) (f : N) (h : nat) (w2 : word) (f2 : N)
      (d : cost) :
  cstep_front w f = Some (ROk w2 f2, d) ->
  cstep w f h = (ROk (normalize w2) f2, O, d).
Proof. intros E. unfold cstep. rewrite E. reflexivity. Qed.
