Lemma cfront_rules_unfold :
  cfront_rules
  = [cfr_primordial; cfr_prim4; cfr_clean; cfr_four;
     cfr_span2A; cfr_span2A';
     cfr_span2C'; cfr_span8far;
     cfr_span2B; cfr_span8orph;
     cfr_span8; cfr_rot; cfr_502;
     cfr_512; cfr_522].
Proof. reflexivity. Qed.
Open Scope N_scope.
Lemma seek_app (l : word) :
  fst (seek l) ++ snd (seek l) = l.
Proof.
  induction l as [|g t IH]; [reflexivity|].
  cbn [seek].
  destruct (is_col g && negb (is_cmf g) && (3 <=? gO g))%bool;
    [|reflexivity].
  destruct (seek t) as [c r] eqn:E.
  cbn [fst snd app] in *. rewrite IH. reflexivity.
Qed.
Lemma ccolcost_seek (l : word) :
  ccolcost l = ccolcost (fst (seek l)) + ccolcost (snd (seek l)).
Proof. rewrite <- ccolcost_app, seek_app. reflexivity. Qed.
Lemma last2_app (l ini : word) (a b : bg) :
  last2 l = Some (ini, a, b) -> l = ini ++ [a; b].
Proof.
  revert ini a b.
  induction l as [|g t IH]; intros ini a b E; [discriminate E|].
  destruct t as [|g2 t2]; [discriminate E|].
  destruct t2 as [|g3 t3].
  - cbn in E. injection E as <- <- <-. reflexivity.
  - change (last2 (g :: g2 :: g3 :: t3))
      with (match last2 (g2 :: g3 :: t3) with
            | Some (ini0, a0, b0) => Some (g :: ini0, a0, b0)
            | None => None
            end) in E.
    destruct (last2 (g2 :: g3 :: t3)) as [[[ini0 a0] b0]|] eqn:E2;
      [|discriminate E].
    pose proof (IH ini0 a0 b0 eq_refl) as HI2.
    injection E as <- <- <-.
    cbn [app]. rewrite HI2. reflexivity.
Qed.
Lemma cadd_czero_l (d : cost) : cadd czero d = d.
Proof. destruct d as [lo hi]. reflexivity. Qed.
Lemma ccolcost_seek_eq (l cols r : word) :
  seek l = (cols, r) -> ccolcost l = ccolcost cols + ccolcost r.
Proof.
  intros E. pose proof (ccolcost_seek l) as H. rewrite E in H. exact H.
Qed.
Lemma ccolcost_nil : ccolcost [] = 0.
Proof. reflexivity. Qed.
Definition cbump (w : word) : word :=
  match w with
  | g0 :: t => (2, 2, gC g0 + 1) :: t
  | [] => w
  end.
Lemma ccg_unfold (o z c : N) : ccg (o,z,c) = c * (2 * o + 6).
Proof. reflexivity. Qed.
Lemma ccolcost_1 (g : bg) : ccolcost [g] = ccg g.
Proof. rewrite ccolcost_cons. cbn [ccolcost]. lia. Qed.
Lemma ccolcost_opt42 (B : N) :
  ccolcost (if 1 <? B then [(4,2,B-1)] else []) = 14 * (B - 1).
Proof.
  destruct (1 <? B) eqn:E.
  - rewrite ccolcost_1. rewrite ccg_unfold. lia.
  - cbn [ccolcost]. apply N.ltb_ge in E. lia.
Qed.
Lemma jump_seg_ccolcost (cols seg : word) (B : N) :
  jump_seg cols B = Some seg ->
  ccolcost seg = ccolcost cols + 32 + 14 * (B - 1).
Proof.
  unfold jump_seg.
  destruct (last2 cols) as [[[ini [[gao gaz] gac]] [[gbo gbz] gbc]]|]
    eqn:EL; [|discriminate].
  apply last2_app in EL.
  destruct ((gao =? 8) && (gaz =? 2) && (gac =? 1)
            && (gbo =? 4) && (gbz =? 2) && (1 <=? gbc)) eqn:E1.
  - intros H. injection H as <-.
    rewrite EL, !ccolcost_app, !ccolcost_cons, ccolcost_opt42.
    cbn [ccolcost].
    repeat match goal with
    | H : (?a && ?b)%bool = true |- _ => apply andb_prop in H; destruct H
    end.
    repeat match goal with
    | H : (_ =? _) = true |- _ => apply N.eqb_eq in H; subst
    end.
    unfold ccg; cbn [gC gO]. lia.
  - destruct ((gbo =? 8) && (gbz =? 2) && (gbc =? 1)) eqn:E2; [|discriminate].
    intros H. injection H as <-.
    rewrite EL, !ccolcost_app, !ccolcost_cons, ccolcost_opt42.
    cbn [ccolcost].
    repeat match goal with
    | H : (?a && ?b)%bool = true |- _ => apply andb_prop in H; destruct H
    end.
    repeat match goal with
    | H : (_ =? _) = true |- _ => apply N.eqb_eq in H; subst
    end.
    unfold ccg; cbn [gC gO]. lia.
Qed.
