Fixpoint dtb4d (body : word) : option N :=
  match body with
  | [] => None
  | g :: t =>
      match dtb4d t with
      | Some d => Some d
      | None =>
          if (gO g =? 8) && (gZ g =? 2) && (gC g =? 1)
          then if forallb w42 t
               then Some 10
               else
                 match t with
                 | (o1,z1,c1) :: (o2,z2,c2) :: t2 =>
                     if (o1 =? 4) && (z1 =? 2) && (1 <=? c1)
                        && (o2 =? 3) && (z2 =? 2) && (c2 =? 1)
                     then
                       match t2 with
                       | [] => Some 12
                       | [(o3,z3,c3)] =>
                           if (o3 =? 4) && (z3 =? 2) then Some 12 else None
                       | _ => None
                       end
                     else None
                 | _ => None
                 end
          else None
      end
  end.
Lemma dtb4d_none (t : word) : dtb4_conv t = None -> dtb4d t = None.
Proof.
  induction t as [|g t IH]; intros HN; [reflexivity|].
  cbn [dtb4_conv] in HN. cbn [dtb4d].
  destruct (dtb4_conv t) as [t'|] eqn:ET; [discriminate HN|].
  rewrite (IH eq_refl).
  destruct ((gO g =? 8) && (gZ g =? 2) && (gC g =? 1));
    [|reflexivity].
  destruct (forallb w42 t); [discriminate HN|].
  destruct t as [|[[o1 z1] c1] t1]; [reflexivity|].
  destruct t1 as [|[[o2 z2] c2] t2]; [reflexivity|].
  destruct ((o1 =? 4) && (z1 =? 2) && (1 <=? c1)
            && (o2 =? 3) && (z2 =? 2) && (c2 =? 1)); [|reflexivity].
  destruct t2 as [|[[o3 z3] c3] t3]; [discriminate HN|].
  destruct t3 as [|? ?]; [|reflexivity].
  destruct ((o3 =? 4) && (z3 =? 2)); [discriminate HN|reflexivity].
Qed.
Lemma dtb4d_some (t t' : word) :
  dtb4_conv t = Some t' -> exists d, dtb4d t = Some d.
Proof.
  revert t'. induction t as [|g t IH]; intros t' HS; [discriminate|].
  cbn [dtb4_conv] in HS. cbn [dtb4d].
  destruct (dtb4_conv t) as [t2|] eqn:ET.
  - destruct (IH t2 eq_refl) as [dd Hd]. rewrite Hd. exists dd. reflexivity.
  - rewrite (dtb4d_none t ET).
    destruct ((gO g =? 8) && (gZ g =? 2) && (gC g =? 1));
      [|discriminate].
    destruct (forallb w42 t); [exists 10; reflexivity|].
    destruct t as [|[[o1 z1] c1] t1]; [discriminate|].
    destruct t1 as [|[[o2 z2] c2] t2]; [discriminate|].
    destruct ((o1 =? 4) && (z1 =? 2) && (1 <=? c1)
              && (o2 =? 3) && (z2 =? 2) && (c2 =? 1)); [|discriminate].
    destruct t2 as [|[[o3 z3] c3] t3]; [exists 12; reflexivity|].
    destruct t3 as [|? ?]; [|discriminate].
    destruct ((o3 =? 4) && (z3 =? 2)); [exists 12; reflexivity|discriminate].
Qed.
Lemma dtb4_conv_ccolcost (cols body : word) (d : N) :
  dtb4_conv cols = Some body ->
  dtb4d cols = Some d ->
  ccolcost body = ccolcost cols + d.
Proof.
  revert body d. induction cols as [|g t IH]; intros body d; [discriminate|].
  cbn [dtb4_conv dtb4d].
  destruct (dtb4_conv t) as [t'|] eqn:ET.
  - destruct (dtb4d t) as [d'|] eqn:ED.
    + intros HH HD. injection HH as HH. injection HD as HD. subst body d.
      rewrite ?ccolcost_cons, (IH t' d' eq_refl eq_refl). lia.
    + exfalso. destruct (dtb4d_some t t' ET) as [dd Hdd].
      rewrite Hdd in ED. discriminate.
  - rewrite (dtb4d_none t ET).
    destruct ((gO g =? 8) && (gZ g =? 2) && (gC g =? 1)) eqn:EG;
      [|discriminate].
    repeat match goal with
    | Hb : (?a && ?b)%bool = true |- _ => apply andb_prop in Hb; destruct Hb
    end.
    repeat match goal with
    | He : (_ =? _) = true |- _ => apply N.eqb_eq in He
    end.
    destruct (forallb w42 t) eqn:EW.
    + intros HH HD. injection HH as HH. injection HD as HD. subst body d.
      rewrite ?ccolcost_cons. cbn [ccolcost]. destruct g as [[go gz] gc].
      cbn [gO gZ gC] in *. subst.
      unfold ccg; cbn [gO gC]. lia.
    + destruct t as [|[[o1 z1] c1] t1]; [discriminate|].
      destruct t1 as [|[[o2 z2] c2] t2]; [discriminate|].
      destruct ((o1 =? 4) && (z1 =? 2) && (1 <=? c1)
                && (o2 =? 3) && (z2 =? 2) && (c2 =? 1)) eqn:EO; [|discriminate].
      repeat match goal with
      | Hb : (?a && ?b)%bool = true |- _ => apply andb_prop in Hb; destruct Hb
      end.
      destruct t2 as [|[[o3 z3] c3] t3].
      * intros HH HD. injection HH as HH. injection HD as HD. subst body d.
        rewrite ?ccolcost_cons, ?ccolcost_app, ?ccolcost_cons, ?ccolcost_opt42.
        cbn [ccolcost]. destruct g as [[go gz] gc].
        cbn [gO gZ gC] in *.
        repeat match goal with
        | He : (_ =? _) = true |- _ => apply N.eqb_eq in He; subst
        end.
        assert (Hc1 : 1 <= c1) by (apply N.leb_le; assumption).
        unfold ccg; cbn [gO gC].
        destruct (1 <? c1) eqn:EL1; cbn [ccolcost];
          [ apply N.ltb_lt in EL1 | apply N.ltb_ge in EL1 ];
          unfold ccg; cbn [gO gC]; lia.
      * destruct t3 as [|? ?]; [|discriminate].
        destruct ((o3 =? 4) && (z3 =? 2)) eqn:E3; [|discriminate].
        intros HH HD. injection HH as HH. injection HD as HD. subst body d.
        rewrite ?ccolcost_cons, ?ccolcost_app, ?ccolcost_cons.
        cbn [ccolcost]. destruct g as [[go gz] gc].
        cbn [gO gZ gC] in *.
        repeat match goal with
        | Hb : (?a && ?b)%bool = true |- _ => apply andb_prop in Hb; destruct Hb
        end.
        repeat match goal with
        | He : (_ =? _) = true |- _ => apply N.eqb_eq in He; subst
        end.
        assert (Hc1 : 1 <= c1) by (apply N.leb_le; assumption).
        unfold ccg; cbn [gO gC].
        destruct (1 <? c1) eqn:EL1; cbn [ccolcost];
          [ apply N.ltb_lt in EL1 | apply N.ltb_ge in EL1 ];
          unfold ccg; cbn [gO gC]; lia.
Qed.
Lemma dtb3_conv_ccolcost (cols body : word) :
  dtb3_conv cols = Some body ->
  ccolcost body + 4 = ccolcost cols.
Proof.
  revert body. induction cols as [|g t IH]; intros body; [discriminate|].
  cbn [dtb3_conv].
  destruct (dtb3_conv t) as [t'|] eqn:ET.
  - intros HH. injection HH as <-. rewrite ?ccolcost_cons, <- (IH t' eq_refl). lia.
  - destruct ((gO g =? 8) && (gZ g =? 2) && (gC g =? 1)) eqn:EG;
      [|discriminate].
    destruct t as [|[[o1 z1] c1] t1]; [discriminate|].
    destruct ((o1 =? 4) && (z1 =? 2) && (1 <? c1) && forallb w42 t1) eqn:EO;
      [|discriminate].
    intros HH. injection HH as <-.
    rewrite ?ccolcost_cons, ?ccolcost_app, ?ccolcost_cons.
    cbn [ccolcost]. destruct g as [[go gz] gc].
    cbn [gO gZ gC] in *.
    repeat match goal with
    | Hb : (?a && ?b)%bool = true |- _ => apply andb_prop in Hb; destruct Hb
    end.
    repeat match goal with
    | He : (_ =? _) = true |- _ => apply N.eqb_eq in He; subst
    end.
    assert (1 < c1) by (apply N.ltb_lt; assumption).
    unfold ccg; cbn [gO gC]. lia.
Qed.
Ltac nlbools :=
  repeat match goal with
  | Hb : (?a && ?b)%bool = true |- _ => apply andb_prop in Hb; destruct Hb
  | H : negb _ = true |- _ => apply negb_true_iff in H
  end;
  repeat match goal with
  | H : (?a =? ?b) = true |- _ => apply N.eqb_eq in H
  | H : (?a <=? ?b) = true |- _ => apply N.leb_le in H
  | H : (?a <? ?b) = true |- _ => apply N.ltb_lt in H
  end.
Lemma ccolcost_niln : ccolcost (@nil (N * N * N)) = 0.
Proof. reflexivity. Qed.
Lemma ccolcost_consn (g : N * N * N) (t : list (N * N * N)) :
  ccolcost (g :: t) = ccg g + ccolcost t.
Proof. exact (ccolcost_cons g t). Qed.
Lemma ccolcost_appn (a b : list (N * N * N)) :
  ccolcost (a ++ b) = ccolcost a + ccolcost b.
Proof. exact (ccolcost_app a b). Qed.
Local Opaque ccolcost.
Lemma ccolcost_normalize (u : word) :
  ccolcost (normalize u) = ccolcost u.
Proof.
  induction u as [|g t IH]; [reflexivity|].
  cbn [normalize].
  destruct (normalize t) as [|g2 t2] eqn:EN.
  - cbn [ccolcost] in IH.
    rewrite !ccolcost_cons. cbn [ccolcost]. lia.
  - rewrite ccolcost_cons in IH.
    destruct g as [[o z] c]; destruct g2 as [[o2 z2] c2].
    cbn [gO gZ gC].
    destruct ((o =? o2) && (z =? z2))%bool eqn:EQ.
    + apply andb_prop in EQ. destruct EQ as [E1 _].
      apply N.eqb_eq in E1. subst o2.
      rewrite !ccolcost_cons. unfold ccg in *.
      cbn [gO gZ gC] in *. nia.
    + rewrite !ccolcost_cons. unfold ccg in *.
      cbn [gO gZ gC] in *. lia.
Qed.
Definition ctot : Type := option N.
Definition ctot_ok (T : ctot) (w : word) : Prop :=
  match T with None => True | Some t => t = ccolcost w end.
Definition chd22 (w : word) : bool :=
  match w with (o,z,_) :: _ => (o =? 2) && (z =? 2) | [] => false end.
Lemma ccolcost_bump10 (w : word) :
  chd22 w = true -> ccolcost (cbump w) = ccolcost w + 10.
Proof.
  destruct w as [|[[o z] c] t]; [discriminate|].
  cbn [chd22]. intros H. apply andb_prop in H. destruct H as [H1 H2].
  apply N.eqb_eq in H1. apply N.eqb_eq in H2. subst.
  unfold cbump. rewrite !ccolcost_cons. unfold ccg.
  cbn [gO gZ gC]. lia.
Qed.
Lemma ccl_split (w : word) (i : nat) :
  chd22 w = true ->
  ccolcost (firstn i (cbump w)) + ccolcost (skipn i (cbump w))
  = ccolcost w + 10.
Proof.
  intros HC. rewrite <- (ccolcost_split (cbump w) i).
  apply ccolcost_bump10. exact HC.
Qed.
Lemma jump_comp_jmp (cols : word) (B : N) (post : word) (f : N)
      (k : ckind) (body : word) (f2 : N) :
  jump_comp cols B post f = Some (k, body, f2) -> k = JMP.
Proof.
  unfold jump_comp. intros H.
  repeat (match type of H with
          | (if ?b then _ else _) = _ => destruct b; try discriminate H
          | (match ?x with _ => _ end) = _ => destruct x; try discriminate H
          end).
  all: injection H as HH; subst; reflexivity.
Qed.
