Lemma djump_mint8 (Z : wside) (p : nat) (q : wside) :
  wrun 2 ((1,1%nat)::(0,1%nat)::(1,6%nat)::(0,1%nat)::(1,2%nat)::(0,1%nat)::Z)
       1 ((1,S p)::q)
  = Some ((1,1%nat)::(0,1%nat)::Z, 1, (1,8%nat)::(0,2%nat)::(1,S p)::q).
Proof. reflexivity. Qed.
Lemma djump_mint7 (Z : wside) (p : nat) (q : wside) :
  wrun 4 ((1,1%nat)::(0,1%nat)::(1,2%nat)::(0,1%nat)::(1,6%nat)::(0,1%nat)
            ::(1,2%nat)::Z)
       1 ((1,S p)::q)
  = Some ((1,1%nat)::Z, 1,
          (1,7%nat)::(0,1%nat)::(1,3%nat)::(0,2%nat)::(1,S p)::q).
Proof. reflexivity. Qed.
Lemma djump_hop (Z : wside) (p : nat) (q : wside) :
  wrun 2 ((1,1%nat)::(0,1%nat)::(1,2%nat)::(0,1%nat)::(1,2%nat)::Z)
       1 ((1,S p)::q)
  = Some ((1,1%nat)::Z, 1, (1,4%nat)::(0,2%nat)::(1,S p)::q).
Proof. reflexivity. Qed.
Fixpoint fourk (k : nat) (r : wside) : wside :=
  match k with
  | O => r
  | S k' => fourk k' ((1,4%nat)::(0,2%nat)::r)
  end.
Lemma fourk_shift (k : nat) (r : wside) :
  fourk k ((1,4%nat)::(0,2%nat)::r) = (1,4%nat)::(0,2%nat):: fourk k r.
Proof.
  revert r. induction k as [|k IH]; intros r.
  - reflexivity.
  - cbn [fourk]. rewrite IH. reflexivity.
Qed.
Lemma fourk_uword (k : nat) (r : wside) :
  fourk k r = uword (repeat 2%nat k) r.
Proof.
  revert r. induction k as [|k IH]; intros r.
  - reflexivity.
  - cbn [fourk repeat uword]. rewrite fourk_shift, IH. reflexivity.
Qed.
Lemma djump_hops2 (k : nat) (Z : wside) (p : nat) (q : wside) :
  wrun (2 * k)
       ((1,1%nat):: vstackC (repeat 2%nat k) Z)
       1 ((1,S p)::q)
  = Some ((1,1%nat)::Z, 1, fourk k ((1,S p)::q)).
Proof.
  revert Z p q. induction k as [|k IH]; intros Z p q.
  - reflexivity.
  - cbn [repeat vstackC vpairC fourk].
    replace (2 * S k)%nat with (2 + 2 * k)%nat by lia.
    erewrite wrun_split by apply djump_hop.
    apply IH.
Qed.
Lemma djump_hops (k : nat) (Z : wside) (p : nat) (q : wside) :
  wrun (2 * k)
       ((1,1%nat)::(0,1%nat)::(1,2%nat):: vstackC (repeat 2%nat k) Z)
       1 ((1,S p)::q)
  = Some ((1,1%nat)::(0,1%nat)::(1,2%nat)::Z, 1, fourk k ((1,S p)::q)).
Proof.
  revert Z p q. induction k as [|k IH]; intros Z p q.
  - reflexivity.
  - cbn [repeat vstackC vpairC fourk].
    replace (2 * S k)%nat with (2 + 2 * k)%nat by lia.
    erewrite wrun_split by apply djump_hop.
    apply IH.
Qed.
Lemma repeat2_S_last (k : nat) :
  repeat 2%nat (S k) = repeat 2%nat k ++ [2%nat].
Proof.
  induction k as [|k IH]; [reflexivity|].
  change (repeat 2%nat (S (S k))) with (2%nat :: repeat 2%nat (S k)).
  rewrite IH at 1.
  change (repeat 2%nat (S k)) with (2%nat :: repeat 2%nat k).
  cbn [app]. reflexivity.
Qed.
Lemma djump_hop0 (Z : wside) (p : nat) (q : wside) :
  wrun 2 ((0,1%nat)::(1,2%nat)::(0,1%nat)::(1,2%nat)
            ::(0,1%nat)::(1,2%nat)::Z) 1
       ((0,1%nat)::(1,S p)::q)
  = Some ((0,1%nat)::(1,2%nat)::Z, 1,
          (0,1%nat)::(1,4%nat)::(0,2%nat)::(1,S p)::q).
Proof. reflexivity. Qed.
Lemma djump_hops0 (k : nat) (Z : wside) (p : nat) (q : wside) :
  wrun (2 * k)
       ((0,1%nat)::(1,2%nat):: vstackC (repeat 2%nat k) Z)
       1 ((0,1%nat)::(1,S p)::q)
  = Some ((0,1%nat)::(1,2%nat)::Z, 1,
          (0,1%nat):: fourk k ((1,S p)::q)).
Proof.
  revert Z p q. induction k as [|k IH]; intros Z p q.
  - reflexivity.
  - cbn [repeat vstackC vpairC fourk].
    replace (2 * S k)%nat with (2 + 2 * k)%nat by lia.
    erewrite wrun_split by apply djump_hop0.
    rewrite IH.
    rewrite fourk_shift. reflexivity.
Qed.
Lemma wb0_zero (n w : nat) (t : wside) (p : nat) (q : wside) :
  wrun 2 ((0,2%nat)::(1,2%nat)::(0,S n)::(1,S w)::t) 1
       ((0,1%nat)::(1,S p)::q)
  = Some ((0,S n)::(1,S w)::t, 1,
          (0,1%nat)::(1,2%nat)::(0,2%nat)::(1,S p)::q).
Proof.
  destruct n as [|n]; destruct w as [|w]; cbn; reflexivity.
Qed.
Lemma wb0_S (m n w : nat) (t : wside) (p : nat) (q : wside) :
  wrun 2 ((0,1%nat)::(1,S m)::(0,1%nat)::(1,2%nat)::(0,S n)::(1,S w)::t) 1
       ((0,1%nat)::(1,S p)::q)
  = Some ((0,S n)::(1,S w)::t, 1,
          (0,1%nat)::(1,(S m + 2)%nat)::(0,2%nat)::(1,S p)::q).
Proof.
  destruct n as [|n]; destruct w as [|w]; cbn;
    rewrite ?PeanoNat.Nat.add_0_r; repeat f_equal; lia.
Qed.
Lemma wb0_zero_last (p : nat) (q : wside) :
  wrun 2 ((0,2%nat)::(1,2%nat)::[]) 1 ((0,1%nat)::(1,S p)::q)
  = Some ([(0,1%nat)], 1, (0,1%nat)::(1,2%nat)::(0,2%nat)::(1,S p)::q).
Proof. reflexivity. Qed.
Lemma wb0_S_last (m : nat) (p : nat) (q : wside) :
  wrun 2 ((0,1%nat)::(1,S m)::(0,1%nat)::(1,2%nat)::[]) 1
       ((0,1%nat)::(1,S p)::q)
  = Some ([(0,1%nat)], 1,
          (0,1%nat)::(1,(S m + 2)%nat)::(0,2%nat)::(1,S p)::q).
Proof.
  cbn; rewrite ?PeanoNat.Nat.add_0_r; repeat f_equal; lia.
Qed.
Fixpoint emitI (ks : list nat) (r : wside) : wside :=
  match ks with
  | [] => r
  | k :: t => emitI t ((1,(2+k)%nat)::(0,2%nat)::r)
  end.
Lemma emitI_uword (ks : list nat) (r : wside) :
  emitI ks r = uword (rev ks) r.
Proof.
  revert r. induction ks as [|k t IH]; intros r.
  - reflexivity.
  - cbn [emitI rev].
    rewrite IH, uword_app. cbn [uword]. reflexivity.
Qed.
Lemma wback0_run (ks : list nat) (p : nat) (q : wside) :
  wrun (2 * List.length ks + 1) (vstackC ks []) 1
       ((0,1%nat)::(1,S p)::q)
  = Some ([], 0, (1,2%nat)::(0,2%nat):: emitI ks ((1,S p)::q)).
Proof.
  revert p q. induction ks as [|k t IH]; intros p q.
  - cbn. reflexivity.
  - cbn [List.length].
    replace (2 * S (List.length t) + 1)%nat
      with (2 + (2 * List.length t + 1))%nat by lia.
    cbn [vstackC emitI].
    destruct t as [|k2 t2].
    + destruct k as [|m].
      * cbn [vpairC vstackC].
        erewrite wrun_split by apply wb0_zero_last.
        cbn. reflexivity.
      * cbn [vpairC vstackC].
        erewrite wrun_split by apply wb0_S_last.
        cbn.
        repeat f_equal; lia.
    + destruct k as [|m].
      * cbn [vpairC vstackC].
        destruct k2 as [|m2]; cbn [vpairC].
        -- erewrite wrun_split by apply wb0_zero. apply IH.
        -- erewrite wrun_split by apply wb0_zero. apply IH.
      * cbn [vpairC vstackC].
        destruct k2 as [|m2]; cbn [vpairC].
        -- erewrite wrun_split by apply wb0_S.
           replace ((S m + 2)%nat) with (S (S (S m))) by lia.
           apply (IH (S (S m))).
        -- erewrite wrun_split by apply wb0_S.
           replace ((S m + 2)%nat) with (S (S (S m))) by lia.
           apply (IH (S (S m))).
Qed.
Lemma vstack1_shift (K : nat) (W : wside) :
  vstackC (repeat 2%nat K) ((0,1%nat)::(1,2%nat)::W)
  = (0,1%nat)::(1,2%nat)::vstackC (repeat 2%nat K) W.
Proof.
  induction K as [|k IH]; cbn [repeat vstackC vpairC].
  - reflexivity.
  - rewrite IH. reflexivity.
Qed.
Lemma d203_x4 (L : wside) (r : wside) :
  wrun 1 ((0,1%nat)::L) 0 ((1,4%nat)::(0,2%nat)::r)
  = Some ((0,1%nat)::(1,2%nat)::(0,1%nat)::(1,2%nat)::(0,1%nat)::L, 0, r).
Proof. reflexivity. Qed.
Lemma d203_cross (k : nat) (L : wside) (r : wside) :
  wrun k ((0,1%nat)::L) 0 (uword (repeat 2%nat k) ((1,4%nat)::r))
  = Some (vstackC (repeat 2%nat k) ((0,1%nat)::L), 0, (1,4%nat)::r).
Proof.
  revert L. induction k as [|k IH]; intros L.
  - reflexivity.
  - cbn [repeat uword].
    replace (S k) with (1 + k)%nat by lia.
    erewrite wrun_split by apply d203_x4.
    rewrite IH.
    cbn [vstackC vpairC].
    rewrite 2!vstack1_shift.
    reflexivity.
Qed.
Lemma d203_end (L : wside) :
  wrun 1 ((0,1%nat)::L) 0 [(1,4%nat)]
  = Some ((0,1%nat)::(1,2%nat)::(0,1%nat)::(1,2%nat)::(0,1%nat)::L, 0, []).
Proof. reflexivity. Qed.
Lemma d203_turn (L : wside) :
  wrun 2 ((0,1%nat)::(1,2%nat)::(0,1%nat)::(1,2%nat)::L) 0 []
  = Some ((0,1%nat)::(1,2%nat)::L, 1, [(0,1%nat);(1,4%nat)]).
Proof. reflexivity. Qed.
Lemma d203_hop2 (zb y : nat) (Z : wside) (p : nat) (q : wside) :
  wrun 2 ((0,1%nat)::(1,2%nat)::(0,1%nat)::(1,2%nat)
            ::(0,S zb)::(1,S y)::Z) 1
    ((0,1%nat)::(1,S p)::q)
  = Some ((0,S zb)::(1,S y)::Z, 1,
          (0,1%nat)::(1,4%nat)::(0,2%nat)::(1,S p)::q).
Proof. destruct zb; reflexivity. Qed.
Lemma d203_hops (zb k y : nat) (Z : wside) (p : nat) (q : wside) :
  wrun (2 * k) (vstackC (repeat 2%nat k) ((0,S zb)::(1,S y)::Z)) 1
    ((0,1%nat)::(1,S p)::q)
  = Some ((0,S zb)::(1,S y)::Z, 1, (0,1%nat)::fourk k ((1,S p)::q)).
Proof.
  revert p q. induction k as [|k IH]; intros p q.
  - reflexivity.
  - cbn [repeat vstackC vpairC].
    replace (2 * S k)%nat with (2 + 2 * k)%nat by lia.
    destruct k as [|k'].
    { cbn [vstackC].
      erewrite wrun_split by apply (d203_hop2 _ y).
      cbn [fourk]. reflexivity. }
    cbn [repeat vstackC vpairC].
    erewrite wrun_split by apply (d203_hop2 _ 1).
    change ((0,1%nat)::(1,2%nat)::(0,1%nat)::(1,2%nat)
              :: vstackC (repeat 2%nat k') ((0,S zb)::(1,S y)::Z))
      with (vstackC (repeat 2%nat (S k')) ((0,S zb)::(1,S y)::Z)).
    rewrite IH. cbn [fourk]. reflexivity.
Qed.
Lemma Kernels_vstackC_app (a b : list nat) (Z : wside) :
  vstackC (a ++ b) Z = vstackC a (vstackC b Z).
Proof.
  induction a as [|m t IH]; cbn [app vstackC]; [reflexivity | rewrite IH; reflexivity].
Qed.
Lemma d203_crossg (k : nat) (L : wside) (r : wside) :
  wrun k ((0,1%nat)::L) 0 (uword (repeat 2%nat k) r)
  = Some (vstackC (repeat 2%nat k) ((0,1%nat)::L), 0, r).
Proof.
  revert L. induction k as [|k IH]; intros L.
  - reflexivity.
  - cbn [repeat uword].
    replace (S k) with (1 + k)%nat by lia.
    erewrite wrun_split by apply d203_x4.
    rewrite IH.
    cbn [vstackC vpairC].
    rewrite 2!vstack1_shift.
    reflexivity.
Qed.
Definition FTrip (c : nat) (Win : wside) (p : nat) (q : wside) : Prop :=
  forall (zb y : nat) (Z : wside),
    wrun c ((0,S zb)::(1,S y)::Z) 0 Win
    = Some ((1,1%nat)::(0,S zb)::(1,S y)::Z, 1, (1,S p)::q).
Lemma d_col_ret (zb w' y : nat) (Z : wside) (p : nat) (q : wside) :
  wrun 2 ((1,1%nat)::(0,1%nat)::(1,S w')::(0,1%nat)::(1,2%nat)
            ::(0,S zb)::(1,S y)::Z) 1
    ((1,S p)::q)
  = Some ((1,1%nat)::(0,S zb)::(1,S y)::Z, 1,
          (1,(3 + w')%nat)::(0,2%nat)::(1,S p)::q).
Proof.
  cbn.
  do 4 f_equal.
  lia.
Qed.
Lemma FTrip_col (c : nat) (Win : wside) (p : nat) (q : wside) (w' : nat) :
  FTrip c Win p q ->
  FTrip (c + 3)
    ((1,(3 + w')%nat)::(0,2%nat)::Win)
    ((2 + w')%nat) ((0,2%nat)::(1,S p)::q).
Proof.
  intros HT zb y Z.
  replace (c + 3)%nat with (1 + (c + 2))%nat by lia.
  change ((1,(3 + w')%nat)::(0,2%nat)::Win)
    with ((1,(2 + S w')%nat)::(0,2%nat)::Win).
  rewrite wrun_add.
  cbn [wrun].
  rewrite wsection_cross.
  lazy beta iota.
  unfold vpush.
  cbn [wpush sym_eqb].
  rewrite wrun_add.
  rewrite (HT _ w').
  lazy beta iota.
  rewrite d_col_ret.
  reflexivity.
Qed.
Lemma FTrip_kernel (c : nat) (Win : wside) (p : nat) (q : wside)
    (ms : list nat) (w' : nat) :
  FTrip c Win p q ->
  wrun (3 * List.length ms + c + 8)%nat [] 0
    (uword ((0%nat :: ms) ++ [S w']) Win)
  = Some ([], 0,
      uword (0%nat :: (0%nat :: ms) ++ [S w']) ((1,S p)::q)).
Proof.
  intros HT.
  replace (3 * List.length ms + c + 8)%nat
    with (List.length ((0%nat :: ms) ++ [S w'])
          + (c + (2 * List.length (rev ((0%nat :: ms) ++ [S w'])) + 2)))%nat
    by (rewrite length_rev, !length_app; cbn [List.length]; lia).
  rewrite wrun_add, wcross_mixed.
  lazy beta iota.
  rewrite (vstack_vstackC _ [] I).
  rewrite rev_app_distr.
  cbn [rev app vstackC vpairC].
  rewrite wrun_add.
  rewrite (HT _ w').
  lazy beta iota.
  change ((1,1%nat)::(0,1%nat)::(1,S w')::(0,1%nat)::(1,2%nat)
            :: vstackC (rev ms ++ [0%nat]) [])
    with ((1,1%nat):: vstackC (S w' :: rev ms ++ [0%nat]) []).
  rewrite (wrun_add (2 * List.length (S w' :: rev ms ++ [0%nat]))), wback_run.
  lazy beta iota.
  rewrite emit_uword.
  cbn [rev].
  rewrite rev_app_distr, rev_involutive.
  cbn [rev app wrun].
  rewrite wclose1.
  lazy beta iota.
  rewrite wclose2.
  lazy beta iota.
  cbn; reflexivity.
Qed.
Lemma d_tick_v (zb y s t : nat) (Z : wside) (r : wside) :
  wrun 2 ((0,S zb)::(1,S y)::Z) 0
    ((1,(2+s)%nat)::(0,1%nat)::(1,S (S t))::r)
  = Some ((1,1%nat)::(0,S zb)::(1,S y)::Z, 1,
          (1,(2+s)%nat)::(0,1%nat)::(1,S t)::r).
Proof.
  destruct s as [|s']; destruct t as [|t']; cbn;
    rewrite ?PeanoNat.Nat.add_0_r; try reflexivity;
    do 4 f_equal; lia.
Qed.
Lemma FTrip_tick (s t : nat) (r : wside) :
  FTrip 2 ((1,(2+s)%nat)::(0,1%nat)::(1,S (S t))::r)
          (1+s) ((0,1%nat)::(1,S t)::r).
Proof.
  intros zb y Z.
  change (S (1+s)) with ((2+s)%nat).
  apply d_tick_v.
Qed.
Lemma d_merge_v (zb y s z : nat) (Z : wside) (r : wside) :
