Lemma d_split_v (zb a y : nat) (Z : wside) (r : wside) :
  wrun 2 ((0,S zb)::(1,S y)::Z) 0
    ((1,S (S a))::(0,1%nat)::(1,S (S a))::(0,1%nat)::r)
  = Some ((1,1%nat)::(0,S zb)::(1,S y)::Z, 1,
          (1,S (S a))::(0,1%nat)::(1,S a)::(0,1%nat)::r).
Proof.
  destruct a as [|a']; cbn; try reflexivity.
  replace (S (a' + 0 + 0 + 2)) with (S (S (S a'))) by lia.
  reflexivity.
Qed.
Lemma FTrip_split (a : nat) (r : wside) :
  FTrip 2 ((1,S (S a))::(0,1%nat)::(1,S (S a))::(0,1%nat)::r)
