       ::(1,S (S b))::(0,1%nat)::r)
  = Some ((1,1%nat)::(0,S zb)::(1,S y)::Z, 1,
          (1,(2+s)%nat)::(0,1%nat)::(1,S b)::(0,1%nat)
            ::(1,S (S b))::(0,1%nat)::r).
Proof.
  destruct s as [|s']; destruct b as [|b']; cbn;
    rewrite ?PeanoNat.Nat.add_0_r; try reflexivity;
    try (do 4 f_equal; lia);
    try (replace (S (b' + 0 + 1)) with (S (S b')) by lia; reflexivity).
Qed.
