Lemma FTrip_jump (c : nat) (Win : wside) (p : nat) (q : wside)
    (h' nb : nat) :
  FTrip c Win p q ->
  FTrip (c + 3 * h' + 3 * nb + 12)
    (uword ((6%nat :: repeat 2%nat h') ++ [2%nat])
       ((1,4%nat)::(0,3%nat)::(1,4%nat)::(0,2%nat)
          :: uword (repeat 2%nat nb) Win))
    6
    ((0,1%nat)::(1,3%nat)::(0,2%nat)
       :: uword (repeat 2%nat h' ++ [2%nat])
            ((1,8%nat)::(0,2%nat)
               :: uword (repeat 2%nat nb) ((1,S p)::q))).
Proof.
  intros HT zb y Z.
  replace (c + 3 * h' + 3 * nb + 12)%nat
    with (List.length ((6%nat :: repeat 2%nat h') ++ [2%nat])
          + (2 + (nb + (c + (2 * nb + (2
             + ((2 * h' + 2) + 4)))))))%nat
    by (rewrite !length_app; cbn [List.length];
        rewrite !repeat_length; lia).
  rewrite wrun_add, wcross_mixed.
  lazy beta iota.
  rewrite (vstack_vstackC _ _ (zheaded0 _ _)).
  rewrite rev_app_distr.
  cbn [rev app vstackC vpairC].
  rewrite rev_repeat.
  erewrite wrun_split by apply (dborrow_in 1 1).
  erewrite wrun_split by apply d203_crossg.
  destruct nb as [|nb'].
  { cbn [repeat vstackC].
    rewrite wrun_add.
    rewrite (HT _ 5%nat).
    lazy beta iota.
    erewrite wrun_split by apply (djump_hops2 0).
    cbn [fourk].
    erewrite wrun_split by apply djump_mint8.
    replace (2 * h' + 2)%nat with (2 * S h')%nat by lia.
    rewrite Kernels_vstackC_app.
    change ((0,1%nat)::(1,2%nat)::(0,1%nat)::(1,2%nat)
              :: vstackC (repeat 2%nat h')
                   (vstackC [6%nat] ((0,S zb)::(1,S y)::Z)))
      with (vstackC (repeat 2%nat (S h'))
              (vstackC [6%nat] ((0,S zb)::(1,S y)::Z))).
    erewrite wrun_split by apply djump_hops.
    cbn [vstackC vpairC fourk].
    rewrite fourk_shift.
    rewrite djump_mint7.
    rewrite fourk_uword.
    rewrite <- repeat2_S_last.
    reflexivity. }
  cbn [repeat vstackC vpairC].
  rewrite wrun_add.
  rewrite (HT _ 1%nat).
  lazy beta iota.
  erewrite wrun_split by apply (djump_hops2 (S nb')).
  rewrite fourk_uword.
  cbn [repeat uword].
  change ((2 + 2)%nat) with 4%nat.
  erewrite wrun_split by apply djump_mint8.
  replace (2 * h' + 2)%nat with (2 * S h')%nat by lia.
  rewrite Kernels_vstackC_app.
  change ((0,1%nat)::(1,2%nat)::(0,1%nat)::(1,2%nat)
            :: vstackC (repeat 2%nat h')
                 (vstackC [6%nat] ((0,S zb)::(1,S y)::Z)))
    with (vstackC (repeat 2%nat (S h'))
            (vstackC [6%nat] ((0,S zb)::(1,S y)::Z))).
  erewrite wrun_split by apply djump_hops.
  cbn [vstackC vpairC fourk].
  rewrite fourk_shift.
  rewrite djump_mint7.
  rewrite fourk_uword.
  rewrite <- repeat2_S_last.
  reflexivity.
Qed.
Lemma FTrip_jump0 (c : nat) (Win : wside) (p : nat) (q : wside) (nb : nat) :
  FTrip c Win p q ->
  FTrip (c + 3 * nb + 9)
    ((1,8%nat)::(0,2%nat)
       ::(1,4%nat)::(0,3%nat)::(1,4%nat)::(0,2%nat)
       :: uword (repeat 2%nat nb) Win)
    6
    ((0,1%nat)::(1,3%nat)::(0,2%nat)
       ::(1,8%nat)::(0,2%nat)
       :: uword (repeat 2%nat nb) ((1,S p)::q)).
Proof.
  intros HT zb y Z.
  change ((1,8%nat)::(0,2%nat)
            ::(1,4%nat)::(0,3%nat)::(1,4%nat)::(0,2%nat)
            :: uword (repeat 2%nat nb) Win)
    with (uword [6%nat]
            ((1,4%nat)::(0,3%nat)::(1,4%nat)::(0,2%nat)
               :: uword (repeat 2%nat nb) Win)).
  replace (c + 3 * nb + 9)%nat
    with (List.length [6%nat]
          + (2 + (nb + (c + (2 * nb + (2 + 4))))))%nat
    by (cbn [List.length]; lia).
  rewrite wrun_add, wcross_mixed.
  lazy beta iota.
  rewrite (vstack_vstackC _ _ (zheaded0 _ _)).
  cbn [rev app vstackC vpairC].
  erewrite wrun_split by apply (dborrow_in 1 5).
  erewrite wrun_split by apply d203_crossg.
  destruct nb as [|nb'].
  { cbn [repeat vstackC].
    rewrite wrun_add.
    rewrite (HT _ 5%nat).
    lazy beta iota.
    erewrite wrun_split by apply (djump_hops2 0).
    cbn [fourk].
    erewrite wrun_split by apply djump_mint8.
    rewrite djump_mint7.
    cbn [uword].
    reflexivity. }
  cbn [repeat vstackC vpairC].
  rewrite wrun_add.
  rewrite (HT _ 1%nat).
  lazy beta iota.
  erewrite wrun_split by apply (djump_hops2 (S nb')).
  rewrite fourk_uword.
  cbn [repeat uword].
  change ((2 + 2)%nat) with 4%nat.
  erewrite wrun_split by apply djump_mint8.
  rewrite djump_mint7.
  reflexivity.
Qed.
Lemma d_endR_inv (zb y fp' : nat) (Z : wside) :
  wrun 2 ((0,S zb)::(1,S y)::Z) 0
    ((1,4%nat)::(0,3%nat)::[(1,S (S fp'))])
  = Some ((0,1%nat)::(1,(4 + fp')%nat)::(0,1%nat)::(1,2%nat)
            ::(0,1%nat)::(1,2%nat)::(0,S zb)::(1,S y)::Z, 0, []).
Proof.
  cbn.
  replace (S (fp' + 0 + 3)) with ((4 + fp')%nat) by lia.
  reflexivity.
Qed.
Lemma d_endR_mintv (fp' : nat) (Z : wside) :
