            ::(0,1%nat)::(1,2%nat)::Z) 0 []
  = Some ((0,1%nat)::(1,2%nat)::Z, 1,
          (0,1%nat)::(1,(5 + fp')%nat)::(0,1%nat)::[(1,3%nat)]).
