Qed.
Lemma d_endR_stopv (zb y : nat) (Z : wside) (p : nat) (q : wside) :
  wrun 3 ((0,1%nat)::(1,2%nat)::(0,1%nat)::(1,6%nat)::(0,1%nat)::(1,2%nat)
            ::(0,S zb)::(1,S y)::Z) 1
    ((0,1%nat)::(1,S p)::q)
  = Some ((1,1%nat)::(0,S zb)::(1,S y)::Z, 1,
          (1,7%nat)::(0,1%nat)::(1,3%nat)::(0,2%nat)::(1,S p)::q).
