Lemma FTrip_endR (h' fp' : nat) :
  FTrip (3 * h' + 13)
    (uword ((6%nat :: repeat 2%nat h') ++ [2%nat])
       ((1,4%nat)::(0,3%nat)::[(1,S (S fp'))]))
    6
    ((0,1%nat)::(1,3%nat)::(0,2%nat)
       :: uword (repeat 2%nat h' ++ [2%nat])
            ((1,(5 + fp')%nat)::(0,1%nat)::[(1,3%nat)])).
Proof.
  intros zb y Z.
  replace (3 * h' + 13)%nat
    with (List.length ((6%nat :: repeat 2%nat h') ++ [2%nat])
          + (2 + (4 + (2 * S h' + 3))))%nat
    by (rewrite !length_app; cbn [List.length];
        rewrite !repeat_length; lia).
  rewrite wrun_add, wcross_mixed.
  lazy beta iota.
  rewrite (vstack_vstackC _ _ (zheaded0 _ _)).
  rewrite rev_app_distr.
  cbn [rev app vstackC vpairC].
  rewrite rev_repeat.
  erewrite wrun_split by apply (d_endR_inv _ 1).
  erewrite wrun_split by apply d_endR_mintv.
  rewrite Kernels_vstackC_app.
  change ((0,1%nat)::(1,2%nat)::(0,1%nat)::(1,2%nat)
            :: vstackC (repeat 2%nat h')
                 (vstackC [6%nat] ((0,S zb)::(1,S y)::Z)))
    with (vstackC (repeat 2%nat (S h'))
            (vstackC [6%nat] ((0,S zb)::(1,S y)::Z))).
  erewrite wrun_split by apply djump_hops0.
  cbn [vstackC vpairC fourk].
  rewrite fourk_shift.
  rewrite d_endR_stopv.
  rewrite fourk_uword.
  rewrite <- repeat2_S_last.
  reflexivity.
Qed.
