    by (cbn [List.length]; lia).
  rewrite wrun_add, wcross_mixed.
  lazy beta iota.
  rewrite (vstack_vstackC _ _ (zheaded0 _ _)).
  cbn [rev app vstackC vpairC].
  erewrite wrun_split by apply (dborrow_in 1 5).
  erewrite wrun_split by apply d203_crossg.
  destruct nb as [|nb'].
  { cbn [repeat vstackC].
    erewrite wrun_split by apply d_far_eatv.
    erewrite wrun_split by apply d_jb_turn.
    erewrite wrun_split by apply d_jb_mint.
    erewrite wrun_split by apply (djump_hops2 0).
    cbn [fourk].
    erewrite wrun_split by apply djump_mint8.
    rewrite djump_mint7.
    cbn [uword].
    reflexivity. }
  cbn [repeat vstackC vpairC].
  erewrite wrun_split by apply d_far_eatv.
  erewrite wrun_split by apply d_jb_turn.
  erewrite wrun_split by apply d_jb_mint.
  erewrite wrun_split by apply (djump_hops2 (S nb')).
  rewrite fourk_uword.
  cbn [repeat uword].
  change ((2 + 2)%nat) with 4%nat.
  erewrite wrun_split by apply djump_mint8.
  rewrite djump_mint7.
  reflexivity.
Qed.
Lemma d_lr_m1 (Z : wside) (p : nat) (q : wside) :
  wrun 2 ((0,1%nat)::(1,2%nat)::(0,1%nat)::(1,6%nat)::Z) 1
    ((0,1%nat)::(1,S p)::q)
  = Some ((0,1%nat)::(1,5%nat)::Z, 1,
          (1,3%nat)::(0,2%nat)::(1,S p)::q).
Proof. reflexivity. Qed.
Lemma d_lr_m2 (u : nat) (Z : wside) (p : nat) (q : wside) :
  wrun 2 ((0,1%nat)::(1,5%nat)::(0,1%nat)::(1,2%nat)
            ::(0,1%nat)::(1,S u)::Z) 1 ((1,S p)::q)
  = Some ((0,1%nat)::(1,S u)::Z, 1,
          (0,1%nat)::(1,7%nat)::(0,1%nat)::(1,S p)::q).
Proof. reflexivity. Qed.
Lemma FTrip_lawR (h' nb : nat) :
  FTrip (3 * h' + 3 * nb + 16)
    (uword ((6%nat :: repeat 2%nat h') ++ [2%nat])
       ((1,4%nat)::(0,3%nat)::(1,4%nat)::(0,2%nat)
          :: uword (repeat 2%nat nb) [(1,4%nat)]))
    6
    ((0,1%nat)::(1,3%nat)::(0,2%nat)
       :: uword (repeat 2%nat h' ++ [2%nat])
            ((1,7%nat)::(0,1%nat)::(1,3%nat)::(0,2%nat)
               :: uword (repeat 2%nat nb) [(1,4%nat)])).
Proof.
  intros zb y Z.
  replace (3 * h' + 3 * nb + 16)%nat
    with (List.length ((6%nat :: repeat 2%nat h') ++ [2%nat])
          + (2 + (nb + (1 + (2 + (2 * nb + (2 + (2
             + ((2 * h' + 2) + 3)))))))))%nat
    by (rewrite !length_app; cbn [List.length];
        rewrite !repeat_length; lia).
  rewrite wrun_add, wcross_mixed.
  lazy beta iota.
  rewrite (vstack_vstackC _ _ (zheaded0 _ _)).
  rewrite rev_app_distr.
  cbn [rev app vstackC vpairC].
  rewrite rev_repeat.
  erewrite wrun_split by apply (dborrow_in 1 1).
  erewrite wrun_split by apply d203_crossg.
  destruct nb as [|nb'].
  { erewrite wrun_split by apply (d_far_eatv 1).
    erewrite wrun_split by apply d203_turn.
    erewrite wrun_split by apply (d203_hops _ 0 1).
    cbn [fourk].
    erewrite wrun_split by apply d_lr_m1.
    erewrite wrun_split by apply (d_lr_m2 1).
    rewrite Kernels_vstackC_app.
    change ((0,1%nat)::(1,2%nat)::(0,1%nat)::(1,2%nat)
              :: vstackC (repeat 2%nat h')
                   (vstackC [6%nat] ((0,S zb)::(1,S y)::Z)))
      with (vstackC (repeat 2%nat (S h'))
              (vstackC [6%nat] ((0,S zb)::(1,S y)::Z))).
    replace (2 * h' + 2)%nat with (2 * S h')%nat by lia.
    erewrite wrun_split by apply (djump_hops0 (S h')).
    cbn [vstackC vpairC].
    rewrite fourk_uword.
    cbn [repeat uword].
    change ((2 + 2)%nat) with 4%nat.
    rewrite d_endR_stopv.
    rewrite <- repeat2_S_last.
    reflexivity. }
  cbn [repeat vstackC vpairC].
  erewrite wrun_split by apply (d_far_eatv 1).
  erewrite wrun_split by apply d203_turn.
  rewrite <- (vstack1_shift nb').
  change ((0,1%nat)::(1,2%nat)::(0,1%nat)::(1,2%nat)
            :: vstackC (repeat 2%nat nb')
                 ((0,1%nat)::(1,2%nat)::(0,1%nat)::(1,6%nat)
                    ::(0,1%nat)::(1,2%nat)::(0,1%nat)::(1,2%nat)
                    :: vstackC (repeat 2%nat h' ++ [6%nat])
                         ((0,S zb)::(1,S y)::Z)))
    with (vstackC (repeat 2%nat (S nb'))
            ((0,1%nat)::(1,2%nat)::(0,1%nat)::(1,6%nat)
               ::(0,1%nat)::(1,2%nat)::(0,1%nat)::(1,2%nat)
               :: vstackC (repeat 2%nat h' ++ [6%nat])
                    ((0,S zb)::(1,S y)::Z))).
  erewrite wrun_split by apply (d203_hops _ (S nb') 1).
  rewrite fourk_uword.
  cbn [repeat uword].
  change ((2 + 2)%nat) with 4%nat.
  erewrite wrun_split by apply d_lr_m1.
  erewrite wrun_split by apply (d_lr_m2 1).
  rewrite Kernels_vstackC_app.
  change ((0,1%nat)::(1,2%nat)::(0,1%nat)::(1,2%nat)
            :: vstackC (repeat 2%nat h')
                 (vstackC [6%nat] ((0,S zb)::(1,S y)::Z)))
    with (vstackC (repeat 2%nat (S h'))
            (vstackC [6%nat] ((0,S zb)::(1,S y)::Z))).
  replace (2 * h' + 2)%nat with (2 * S h')%nat by lia.
  erewrite wrun_split by apply (djump_hops0 (S h')).
  cbn [vstackC vpairC].
  rewrite fourk_uword.
  cbn [repeat uword].
  change ((2 + 2)%nat) with 4%nat.
  rewrite d_endR_stopv.
  rewrite <- repeat2_S_last.
  reflexivity.
Qed.
Lemma FTrip_lawR0 (nb : nat) :
  FTrip (3 * nb + 13)
    ((1,8%nat)::(0,2%nat)::(1,4%nat)::(0,3%nat)::(1,4%nat)::(0,2%nat)
       :: uword (repeat 2%nat nb) [(1,4%nat)])
    6
    ((0,1%nat)::(1,3%nat)::(0,2%nat)
       ::(1,7%nat)::(0,1%nat)::(1,3%nat)::(0,2%nat)
       :: uword (repeat 2%nat nb) [(1,4%nat)]).
Proof.
  intros zb y Z.
  change ((1,8%nat)::(0,2%nat)::(1,4%nat)::(0,3%nat)::(1,4%nat)::(0,2%nat)
            :: uword (repeat 2%nat nb) [(1,4%nat)])
    with (uword [6%nat]
            ((1,4%nat)::(0,3%nat)::(1,4%nat)::(0,2%nat)
               :: uword (repeat 2%nat nb) [(1,4%nat)])).
  replace (3 * nb + 13)%nat
    with (List.length [6%nat]
          + (2 + (nb + (1 + (2 + (2 * nb + (2 + (2 + 3))))))))%nat
    by (cbn [List.length]; lia).
  rewrite wrun_add, wcross_mixed.
  lazy beta iota.
  rewrite (vstack_vstackC _ _ (zheaded0 _ _)).
  cbn [rev app vstackC vpairC].
  erewrite wrun_split by apply (dborrow_in 1 5).
  erewrite wrun_split by apply d203_crossg.
  destruct nb as [|nb'].
  { cbn [repeat vstackC].
    erewrite wrun_split by apply (d_far_eatv 1).
    erewrite wrun_split by apply d203_turn.
    change (2 * 0 + (2 + (2 + 3)))%nat with (2 + (2 + 3))%nat.
    erewrite wrun_split by apply d_lr_m1.
    erewrite wrun_split by apply (d_lr_m2 1).
    rewrite d_endR_stopv.
    cbn [repeat uword].
    reflexivity. }
  cbn [repeat vstackC vpairC].
  erewrite wrun_split by apply (d_far_eatv 1).
  erewrite wrun_split by apply d203_turn.
  rewrite <- (vstack1_shift nb').
  match goal with
  | |- context [ (0,1%nat)::(1,2%nat)::(0,1%nat)::(1,2%nat)
                   :: vstackC (repeat 2%nat nb') ?W ] =>
      change ((0,1%nat)::(1,2%nat)::(0,1%nat)::(1,2%nat)
                :: vstackC (repeat 2%nat nb') W)
        with (vstackC (repeat 2%nat (S nb')) W)
  end.
  erewrite wrun_split by apply (d203_hops _ (S nb') 1).
  cbn [fourk].
  rewrite fourk_shift.
  erewrite wrun_split by apply d_lr_m1.
  erewrite wrun_split by apply (d_lr_m2 1).
  rewrite d_endR_stopv.
  rewrite fourk_uword.
  cbn [repeat uword].
  reflexivity.
Qed.
Lemma d_col_sret (zb w' y : nat) (Z : wside) (W' : wside) :
  wrun 1 ((0,1%nat)::(1,S w')::(0,1%nat)::(1,2%nat)
            ::(0,S zb)::(1,S y)::Z) 1
    ((0,1%nat)::W')
  = Some ((1,1%nat)::(0,S zb)::(1,S y)::Z, 1,
          (1,(3 + w')%nat)::(0,2%nat)::W').
Proof.
  cbn.
  do 4 f_equal.
  lia.
Qed.
Lemma Sand_col (c : nat) (Win : wside) (W' : wside) (w' : nat) :
  Sand c Win W' ->
  FTrip (c + 2)
    ((1,(3 + w')%nat)::(0,2%nat)::Win)
    ((2 + w')%nat) ((0,2%nat)::W').
Proof.
  intros HS zb y Z.
  replace (c + 2)%nat with (1 + (c + 1))%nat by lia.
  change ((1,(3 + w')%nat)::(0,2%nat)::Win)
    with ((1,(2 + S w')%nat)::(0,2%nat)::Win).
  rewrite wrun_add.
  cbn [wrun].
  rewrite wsection_cross.
  lazy beta iota.
  unfold vpush.
  cbn [wpush sym_eqb].
  rewrite wrun_add.
  rewrite (HS w').
  lazy beta iota.
  rewrite d_col_sret.
  reflexivity.
Qed.
Lemma FTrip_endR0 (fp' : nat) :
  FTrip 10
    ((1,8%nat)::(0,2%nat)::(1,4%nat)::(0,3%nat)::[(1,S (S fp'))])
    6
    ((0,1%nat)::(1,3%nat)::(0,2%nat)
       ::(1,(5 + fp')%nat)::(0,1%nat)::[(1,3%nat)]).
Proof.
  intros zb y Z.
  destruct fp' as [|w'].
  - cbn. reflexivity.
  - cbn.
    replace (w' + 0 + 3)%nat with (S (S (S w'))) by lia.
    cbn.
    replace (w' + 0 + 2)%nat with (S (S w')) by lia.
    reflexivity.
Qed.
Lemma FTrip_marker (c : nat) (Win : wside) (p : nat) (q : wside) :
  FTrip c Win p q ->
  FTrip (c + 3) ((1,2%nat)::(0,2%nat)::Win) 1 ((0,2%nat)::(1,S p)::q).
Proof.
  intros HT zb y Z.
  replace (c + 3)%nat with (1 + (c + 2))%nat by lia.
  rewrite wrun_add.
  cbn [wrun].
  change ((1,2%nat)::(0,2%nat)::Win)
    with ((1,(2 + 0)%nat)::(0,2%nat)::Win).
  rewrite wsection_cross.
  lazy beta iota.
  unfold vpush.
  cbn [wpush sym_eqb].
  rewrite wrun_add.
  change ((0,(1 + 1)%nat)::(1,2%nat)::(0,S zb)::(1,S y)::Z)
    with ((0,S 1%nat)::(1,S 1%nat)::(0,S zb)::(1,S y)::Z).
  rewrite (HT 1%nat 1%nat ((0,S zb)::(1,S y)::Z)).
  lazy beta iota.
  cbn.
  reflexivity.
Qed.
Lemma FTrip_kernel1 (c : nat) (W : wside) (p : nat) (q : wside) :
  FTrip c W p q ->
  wrun (c + 5)%nat [] 0 (uword [0%nat] W)
  = Some ([], 0, uword [0%nat;0%nat] ((1,S p)::q)).
Proof.
  intros HT.
  cbn [uword].
  replace (c + 5)%nat with (1 + (c + 4))%nat by lia.
  rewrite wrun_add.
  cbn [wrun].
  change ((1,2%nat)::(0,2%nat)::W) with ((1,(2 + 0)%nat)::(0,2%nat)::W).
  rewrite wsection_cross.
  lazy beta iota.
  unfold vpush.
  cbn [wpush sym_eqb].
  change ((0,(1 + 1)%nat)::(1,2%nat)::nil)
    with ((0,S 1%nat)::(1,S 1%nat)::(@nil run)).
  rewrite wrun_add.
  rewrite (HT 1%nat 1%nat []).
  lazy beta iota.
  reflexivity.
Qed.
Lemma FTrip_kernel_all (ms : list nat) :
  forall (c : nat) (Win : wside) (p : nat) (q : wside),
  FTrip c Win p q ->
  wrun (3 * List.length ms + c + 5)%nat [] 0 (uword (0%nat :: ms) Win)
  = Some ([], 0, uword (0%nat :: 0%nat :: ms) ((1,S p)::q)).
Proof.
  induction ms as [|m ms' IH] using rev_ind; intros c Win p q HT.
  - cbn [List.length].
    replace (3 * 0 + c + 5)%nat with (c + 5)%nat by lia.
    exact (FTrip_kernel1 c Win p q HT).
  - destruct m as [|m'].
    +
      change (0%nat :: ms' ++ [0%nat]) with ((0%nat :: ms') ++ [0%nat]).
      rewrite uword_app.
      cbn [uword].
      specialize (IH (c + 3)%nat ((1,2%nat)::(0,2%nat)::Win) 1%nat
                     ((0,2%nat)::(1,S p)::q)
                     (FTrip_marker c Win p q HT)).
      rewrite length_app.
      cbn [List.length].
      replace (3 * (List.length ms' + 1) + c + 5)%nat
        with (3 * List.length ms' + (c + 3) + 5)%nat by lia.
      change ((1,(2 + 0)%nat)::(0,2%nat)
                :: uword ms' ((1,(2 + 0)%nat)::(0,2%nat)::Win))
        with (uword (0%nat :: ms') ((1,2%nat)::(0,2%nat)::Win)).
      rewrite IH.
      change (0%nat :: 0%nat :: ms' ++ [0%nat])
        with ((0%nat :: 0%nat :: ms') ++ [0%nat]).
      rewrite uword_app.
      cbn [uword].
      reflexivity.
    +
      replace (3 * List.length (ms' ++ [S m']) + c + 5)%nat
        with (3 * List.length ms' + c + 8)%nat
        by (rewrite length_app; cbn [List.length]; lia).
      exact (FTrip_kernel c Win p q ms' m' HT).
Qed.
Lemma FTrip_chainphase (c : nat) (Win : wside) (p : nat) (q : wside)
    (ms : list nat) (w b : nat) (ns : list nat) :
  FTrip c Win p q ->
  wrun (3 * List.length ms + 2 * b + 3 * List.length ns + c + 10)%nat [] 0
       (uword (ms ++ (3 + w)%nat :: repeat 1%nat b)
          ((1,3%nat)::(0,3%nat)::(1,4%nat)::(0,2%nat)
             :: uword ns Win))
  = Some ([], 0,
          uword (0%nat :: ms)
                ((1,(4+w)%nat)::(0,1%nat)::(1,3%nat)::(0,1%nat)
                   :: pair_runs' 4%nat 1%nat b
                   ++ (1,8%nat)::(0,2%nat)
                   :: uword ns ((1,S p)::q))).
Proof.
  intros HT.
  replace (3 * List.length ms + 2 * b + 3 * List.length ns + c + 10)%nat
    with (List.length (ms ++ (3 + w)%nat :: repeat 1%nat b)
          + (2 + (List.length ns
             + (c + (2 * List.length (rev ns)
                + (2 + (b + (3 + (2 * List.length (rev ms) + 2)))))))))%nat
    by (rewrite !length_app, !length_rev;
        cbn [List.length]; rewrite !repeat_length; lia).
  rewrite wrun_add, wcross_mixed.
  lazy beta iota.
  rewrite (vstack_vstackC _ [] I).
  rewrite rev_app_distr.
  cbn [rev].
  rewrite rev_repeat1.
  rewrite <- app_assoc.
  rewrite Kernels_vstackC_app.
  cbn [app vstackC].
  erewrite wrun_split
    by (apply ddeep_in; apply vstackC_zheaded; apply vpairC_zheaded).
  rewrite wrun_add, wcross_mixed.
  lazy beta iota.
  rewrite (vstack_vstackC ns _ (zheaded0 _ _)).
  rewrite wrun_add.
  destruct (rev ns) as [|n0 nr] eqn:ERN;
    [|destruct n0 as [|n0']]; cbn [vstackC vpairC].
  1: rewrite (HT 0%nat 5%nat
               ((0,1%nat)::(1,1%nat)::(0,1%nat)::(1,2%nat)
                  :: vstackC (repeat 1%nat b)
                       (vpairC (3 + w)%nat (vstackC (rev ms) [])))).
  2: rewrite (HT 1%nat 1%nat
               (vstackC nr
                  ((0,1%nat)::(1,6%nat)::(0,1%nat)::(1,1%nat)
                     ::(0,1%nat)::(1,2%nat)
                  :: vstackC (repeat 1%nat b)
                       (vpairC (3 + w)%nat (vstackC (rev ms) []))))).
  3: rewrite (HT 0%nat n0'
               ((0,1%nat)::(1,2%nat)
                  :: vstackC nr
                       ((0,1%nat)::(1,6%nat)::(0,1%nat)::(1,1%nat)
                          ::(0,1%nat)::(1,2%nat)
                  :: vstackC (repeat 1%nat b)
                       (vpairC (3 + w)%nat (vstackC (rev ms) []))))).
  all: lazy beta iota.
  1: change ((0,1%nat)::(1,6%nat)::(0,1%nat)::(1,1%nat)
               ::(0,1%nat)::(1,2%nat)
                  :: vstackC (repeat 1%nat b)
                       (vpairC (3 + w)%nat (vstackC (rev ms) [])))
       with (vstackC (@nil nat)
               ((0,1%nat)::(1,6%nat)::(0,1%nat)::(1,1%nat)
                  ::(0,1%nat)::(1,2%nat)
                  :: vstackC (repeat 1%nat b)
                       (vpairC (3 + w)%nat (vstackC (rev ms) [])))).
  2: change ((0,2%nat)::(1,2%nat)
               :: vstackC nr
                    ((0,1%nat)::(1,6%nat)::(0,1%nat)::(1,1%nat)
                       ::(0,1%nat)::(1,2%nat)
                  :: vstackC (repeat 1%nat b)
                       (vpairC (3 + w)%nat (vstackC (rev ms) []))))
       with (vstackC (0%nat :: nr)
               ((0,1%nat)::(1,6%nat)::(0,1%nat)::(1,1%nat)
                  ::(0,1%nat)::(1,2%nat)
                  :: vstackC (repeat 1%nat b)
                       (vpairC (3 + w)%nat (vstackC (rev ms) [])))).
  3: change ((0,1%nat)::(1,S n0')::(0,1%nat)::(1,2%nat)
               :: vstackC nr
                    ((0,1%nat)::(1,6%nat)::(0,1%nat)::(1,1%nat)
                       ::(0,1%nat)::(1,2%nat)
                  :: vstackC (repeat 1%nat b)
                       (vpairC (3 + w)%nat (vstackC (rev ms) []))))
       with (vstackC (S n0' :: nr)
               ((0,1%nat)::(1,6%nat)::(0,1%nat)::(1,1%nat)
                  ::(0,1%nat)::(1,2%nat)
                  :: vstackC (repeat 1%nat b)
                       (vpairC (3 + w)%nat (vstackC (rev ms) [])))).
  all: rewrite wrun_add, wback_run.
  all: lazy beta iota.
  all: rewrite <- ERN.
  all: rewrite emit_uword, rev_involutive.
  all: erewrite wrun_split by apply ddeep_mint_u.
  all: rewrite (wrun_add b).
  all: rewrite (dcp_run b).
  all: lazy beta iota.
  all: rewrite vpairC_3p.
  all: erewrite wrun_split by apply (dcp_disch_u w _ b).
  all: rewrite (wrun_add (2 * List.length (rev ms))), wback_run.
  all: lazy beta iota.
  all: rewrite emit_uword, rev_involutive.
  all: cbn [wrun].
  all: rewrite wclose1.
  all: lazy beta iota.
  all: rewrite wclose2.
  all: lazy beta iota.
  all: f_equal. f_equal.
  all: replace (S (S (S (S w)))) with ((4 + w)%nat) by lia.
  all: destruct ms as [|m t']; cbn; reflexivity.
Qed.
