Lemma eat0_step (L R : wside) :
  wrun 4 ((1,2%nat)::(0,2%nat)::L) S0
       ((1,5%nat)::(0,1%nat)::(1,4%nat)::(0,1%nat)::R)
  = Some (L, S0,
          (1,5%nat)::(0,1%nat)::(1,4%nat)::(0,1%nat)
            ::(1,3%nat)::(0,1%nat)::R).
Proof. vm_compute. reflexivity. Qed.
Lemma eat0_last (R : wside) :
  wrun 4 [(1,2%nat)] S0
       ((1,5%nat)::(0,1%nat)::(1,4%nat)::(0,1%nat)::R)
  = Some ([], S0,
          (1,5%nat)::(0,1%nat)::(1,4%nat)::(0,1%nat)
            ::(1,3%nat)::(0,1%nat)::R).
Proof. vm_compute. reflexivity. Qed.
Lemma pair_runs22_app (k : nat) (L : wside) :
  pair_runs 2%nat 2%nat (S k) ++ L
  = (1,2%nat)::(0,2%nat):: (pair_runs 2%nat 2%nat k ++ L).
Proof. reflexivity. Qed.
Lemma pair_runs_snoc_cons (o z k : nat) (R : wside) :
  pair_runs o z k ++ (1,o)::(0,z)::R
  = (1,o)::(0,z):: pair_runs o z k ++ R.
Proof.
  revert R. induction k as [|k IH]; intros R; [reflexivity|].
  cbn [pair_runs app].
  rewrite IH.
  reflexivity.
Qed.
Lemma eat0_run (k : nat) (L R : wside) :
  wrun (4 * k) (pair_runs 2%nat 2%nat k ++ L) S0
       ((1,5%nat)::(0,1%nat)::(1,4%nat)::(0,1%nat)::R)
  = Some (L, S0,
          (1,5%nat)::(0,1%nat)::(1,4%nat)::(0,1%nat)
            :: pair_runs 3%nat 1%nat k ++ R).
