  - reflexivity.
  - replace (4 * S k)%nat with (4 + 4 * k)%nat by lia.
    rewrite pair_runs22_app.
    rewrite wrun_add.
    rewrite eat0_step.
    lazy beta iota.
    rewrite (IH L ((1,3%nat)::(0,1%nat)::R)).
    rewrite pair_runs_snoc_cons.
