  rewrite (vstackC2_cons V' Zin).
  erewrite wrun_split by apply dfarA4.
  rewrite <- (vstackC2_cons V' Zin).
  rewrite (vstackC2_shift (S V') Zin).
  rewrite wrun_add, wback_run.
  lazy beta iota.
  rewrite emit_uword, rev_repeat.
  unfold Zin.
  cbn [repeat vstackC vpairC].
  rewrite (uword_fours_app (S V')).
  cbn [pair_runs app].
  rewrite wrun_add, dmintA.
  lazy beta iota.
  rewrite wrun_add, dcp_run.
  lazy beta iota.
  rewrite (dcp_disch_u 0%nat).
