Ltac unblock :=
  repeat match goal with
  | |- context [(?a + 0)%nat] => replace (a + 0)%nat with a by lia
  end;
  repeat match goal with
  | |- context [(?a + 3)%nat] => replace (a + 3)%nat with (S (S (S a))) by lia
  | |- context [(?a + 2)%nat] => replace (a + 2)%nat with (S (S a)) by lia
  | |- context [(?a + 1)%nat] => replace (a + 1)%nat with (S a) by lia
  end.
Ltac gker := cbn; try reflexivity; repeat f_equal; lia.
Ltac gker2 :=
  cbn; unblock; cbn; unblock; cbn;
  try reflexivity; repeat f_equal; lia.
