Lemma FTrip_x203g (X' c : nat) :
  FTrip (3 * c + 9)
    ((1,(5 + X')%nat)::(0,2%nat)::(1,3%nat)::(0,2%nat)
       :: uword (repeat 2%nat c) [(1,4%nat)])
    (3 + X')%nat
    ((0,1%nat)::(1,3%nat)::(0,1%nat)
       :: uword (repeat 2%nat (S c)) [(1,4%nat)]).
Proof.
  intros zb y Z.
  replace (3 * c + 9)%nat
    with (1 + (1 + (c + (1 + (2 + (2 * c + 4))))))%nat by lia.
  erewrite wrun_split by apply (g203_in X' zb y Z).
  erewrite wrun_split by apply (g203_m3 (2 + X')%nat).
  erewrite wrun_split by apply (d203_cross c).
  erewrite wrun_split by apply (d203_end_v c).
  erewrite wrun_split by apply d203_turn.
  rewrite <- (vstack1_shift c).
  erewrite wrun_split by apply (d203_hops 0 c 1).
  rewrite fourk_split.
  rewrite (g203_mint X').
  rewrite <- fourk_split, fourk_uword.
  cbn [repeat uword].
  reflexivity.
