Lemma d203_crossg_g (k : nat) (L r : wside) :
  wrun k ((0,1%nat)::L) 0 (uword (repeat 2%nat k) r)
  = Some (vstackC (repeat 2%nat k) ((0,1%nat)::L), 0, r).
