Lemma FTrip_x218og (X' cn' d : nat) :
  FTrip (3 * cn' + 3 * d + 12)
    ((1,(5 + X')%nat)::(0,2%nat)
       :: uword (repeat 2%nat (S cn'))
            ((1,3%nat)::(0,2%nat):: uword (repeat 2%nat d) [(1,4%nat)]))
    (3 + X')%nat
    ((0,1%nat)::(1,3%nat)::(0,2%nat)
       :: uword (repeat 2%nat cn')
            ((1,4%nat)::(0,1%nat)
               :: uword (repeat 2%nat (S d)) [(1,4%nat)])).
Proof.
  intros zb y Z.
  replace (3 * cn' + 3 * d + 12)%nat
    with (1 + (S cn' + (1 + (d + (1 + (2 + (2 * d
           + (1 + (2 + (2 * cn' + 3)))))))))) %nat by lia.
  erewrite wrun_split by apply (g203_in X' zb y Z).
