  erewrite wrun_split by apply (d203_cross d).
  erewrite wrun_split by apply (d203_end_v d).
  erewrite wrun_split by apply d203_turn.
  rewrite <- (vstack1_shift d).
  erewrite wrun_split by apply (d203_hops 0 d 1).
  rewrite fourk_split.
  erewrite wrun_split by apply g218o_dig.
  rewrite <- fourk_split.
  erewrite wrun_split by apply (g218o_hopB 0 1).
  rewrite <- (vstack1_shift cn').
  erewrite wrun_split by apply (d203_hops 0 cn' 1).
  rewrite fourk_split4.
  rewrite (g218_mint X').
  rewrite <- fourk_split4.
  rewrite <- (fourk_shift d [(1,4%nat)]).
  change (fourk d ((1,4%nat)::(0,2%nat)::[(1,4%nat)]))
    with (fourk (S d) [(1,4%nat)]).
  rewrite !fourk_uword.
  reflexivity.
Qed.
