Lemma gC_mint (X' Y' : nat) (Z R : wside) :
  wrun 5 ((0,1%nat)::(1,5%nat)::(0,1%nat)::(1,(3 + Y')%nat)
            ::(0,1%nat)::(1,(3 + X')%nat)::(0,1%nat)::(1,2%nat)::Z) 1
    ((1,3%nat)::(0,2%nat)::R)
  = Some ((1,1%nat)::Z, 1,
          (1,(4 + X')%nat)::(0,1%nat)::(1,(3 + Y')%nat)::(0,1%nat)
            ::(1,6%nat)::(0,1%nat)::(1,3%nat)::(0,2%nat)::R).
Proof. destruct X' as [|[|[|d]]]; destruct Y' as [|[|[|e]]]; gker2. Qed.
Lemma FTrip_armC (X' Y' c' : nat) :
  FTrip (3 * c' + 13)
    ((1,(5 + X')%nat)::(0,3%nat)::(1,(1 + Y')%nat)::(0,3%nat)
       :: uword (repeat 2%nat (S c')) [(1,4%nat)])
    (3 + X')%nat
    ((0,1%nat)::(1,(3 + Y')%nat)::(0,1%nat)::(1,6%nat)::(0,1%nat)
       ::(1,3%nat)::(0,2%nat):: uword (repeat 2%nat c') [(1,4%nat)]).
Proof.
  intros zb y Z.
  replace (3 * c' + 13)%nat
    with (1 + (1 + (1 + (c' + (1 + (2 + (2 * c' + (2 + 5))))))))%nat by lia.
  erewrite wrun_split by apply (gC_in X' zb y Z).
  cbn [repeat uword].
  erewrite wrun_split by apply (gC_y3 Y').
  erewrite wrun_split by apply gC_first.
  erewrite wrun_split by apply (d203_cross c').
  erewrite wrun_split by apply (d203_end_v c').
  erewrite wrun_split by apply d203_turn.
  rewrite <- (vstack1_shift c').
  erewrite wrun_split by apply (d203_hops 0 c' 1).
  rewrite fourk_split.
  erewrite wrun_split by apply gC_hop6.
  rewrite (gC_mint X' Y').
  rewrite <- fourk_split, fourk_uword.
  reflexivity.
Qed.
Lemma d227_m2 (L r : wside) :
  wrun 1 ((0,1%nat)::L) 0 ((1,2%nat)::(0,2%nat)::r)
  = Some ((0,2%nat)::(1,2%nat)::(0,1%nat)::L, 0, r).
Proof. reflexivity. Qed.
Lemma d227_x4 (zb : nat) (L r : wside) :
  wrun 1 ((0,S zb)::L) 0 ((1,4%nat)::(0,2%nat)::r)
  = Some ((0,1%nat)::(1,2%nat)::(0,1%nat)::(1,2%nat)::(0,S zb)::L, 0, r).
Proof. destruct zb; reflexivity. Qed.
Lemma d227_cross (k zb : nat) (L r : wside) :
  wrun k ((0,S zb)::L) 0 (uword (repeat 2%nat k) r)
  = Some (vstackC (repeat 2%nat k) ((0,S zb)::L), 0, r).
Proof.
  revert zb L. induction k as [|k IH]; intros zb L.
  - reflexivity.
  - cbn [repeat uword].
    replace (S k) with (1 + k)%nat by lia.
    erewrite wrun_split by apply (d227_x4 zb).
    rewrite (IH 0%nat).
    cbn [vstackC vpairC].
    rewrite 2!vstack1_shift.
    reflexivity.
Qed.
Lemma d227_end (zb : nat) (L : wside) :
