Lemma FTrip_x227g (X' c : nat) :
  FTrip (6 * c + 15)
    ((1,(5 + X')%nat)::(0,2%nat)::(1,2%nat)::(0,2%nat)
       :: uword (repeat 2%nat c) [(1,4%nat)])
    (3 + X')%nat
    ((0,1%nat)::(1,5%nat)::(0,2%nat)
       :: uword (repeat 2%nat (S c)) [(1,4%nat)]).
Proof.
  intros zb y Z.
  replace (6 * c + 15)%nat
    with (1 + (1 + (c + (1 + (2 + (2 * c + (1 + (1 + (c
           + (1 + (2 + (2 * (S c) + 3))))))))))))%nat by lia.
  erewrite wrun_split by apply (g203_in X' zb y Z).
  erewrite wrun_split by apply d227_m2.
  erewrite wrun_split by apply (d227_cross c 1).
  erewrite wrun_split by apply (d227_end_v c 1).
  erewrite wrun_split by apply d203_turn.
  rewrite <- (vstack1_shift c).
  erewrite wrun_split by apply (d203_hops 0 c 1).
  rewrite fourk_split.
  erewrite wrun_split by apply (d227_turn2 1).
  rewrite <- fourk_split, fourk_uword.
  erewrite wrun_split by apply d227_x4b.
  erewrite wrun_split by apply (d203_crossg_g c).
  erewrite wrun_split by apply (d203_end_v c).
  erewrite wrun_split by apply d203_turn.
  rewrite (vstack1_shift c), vstack_succ.
  erewrite wrun_split by apply (d203_hops 0 (S c) 3).
  change (fourk (S c) [(1,4%nat)])
    with (fourk c ((1,4%nat)::(0,2%nat)::[(1,4%nat)])).
  rewrite fourk_shift.
  rewrite (d227_mint X').
  rewrite <- fourk_uword.
  change (fourk (S c) [(1,4%nat)])
    with (fourk c ((1,4%nat)::(0,2%nat)::[(1,4%nat)])).
  rewrite fourk_shift.
  reflexivity.
Qed.
