Lemma FTrip_stageXg (X' : nat) (c : nat) (Win : wside) (p : nat) (q : wside)
    (NLr : nat) :
  FTrip c Win p q ->
  FTrip (c + 3 * NLr + 6)
    ((1,(5+X')%nat)::(0,3%nat)::(1,4%nat)::(0,2%nat)
       :: uword (repeat 2%nat NLr) Win)
    ((3+X')%nat)
    ((0,1%nat)::(1,7%nat)::(0,2%nat)
       :: uword (repeat 2%nat NLr) ((1,S p)::q)).
Proof.
  intros HT zb y Z.
  replace (c + 3 * NLr + 6)%nat
    with (2 + (NLr + (c + (2 * NLr + 4))))%nat by lia.
  erewrite wrun_split by apply (d357_inXv X' _ y).
  erewrite wrun_split by apply d203_crossg_g.
  destruct NLr as [|NLr'].
  { cbn [repeat vstackC].
    rewrite wrun_add.
    rewrite (HT _ 5%nat).
    lazy beta iota.
    erewrite wrun_split by apply (djump_hops2 0).
    cbn [fourk].
    rewrite d_casc_retX.
    reflexivity. }
  cbn [repeat vstackC vpairC].
  rewrite wrun_add.
  rewrite (HT _ 1%nat).
  lazy beta iota.
  erewrite wrun_split by apply (djump_hops2 (S NLr')).
  rewrite fourk_uword.
  cbn [repeat uword].
  change ((2 + 2)%nat) with 4%nat.
  rewrite d_casc_retX.
  cbn [repeat uword].
  reflexivity.
Qed.
Lemma FTrip_stageXg_sand (X' : nat) (c : nat) (Win : wside) (p : nat)
    (q : wside) (NLr : nat) :
  Sand c Win ((1,S p)::q) ->
  FTrip (c + 3 * NLr + 5)
    ((1,(5+X')%nat)::(0,3%nat)::(1,4%nat)::(0,2%nat)
       :: uword (repeat 2%nat NLr) Win)
    ((3+X')%nat)
    ((0,1%nat)::(1,7%nat)::(0,2%nat)
       :: uword (repeat 2%nat NLr) ((1,S p)::q)).
Proof.
  intros HS zb y Z.
  replace (c + 3 * NLr + 5)%nat
    with (2 + (NLr + (c + (2 * NLr + 3))))%nat by lia.
  erewrite wrun_split by apply (d357_inXv X' _ y).
  erewrite wrun_split by apply d203_crossg_g.
  destruct NLr as [|NLr'].
  { cbn [repeat vstackC].
    rewrite wrun_add.
    rewrite (HS 5%nat).
    lazy beta iota.
    rewrite d_casc_sretX.
    reflexivity. }
  cbn [repeat vstackC vpairC].
  rewrite wrun_add.
  rewrite (HS 1%nat).
  lazy beta iota.
  change ((0,1%nat)::(1,2%nat)::(0,1%nat)::(1,2%nat)
            :: vstackC (repeat 2%nat NLr')
                 ((0,1%nat)::(1,6%nat)::(0,1%nat)::(1,(3+X')%nat)
                    ::(0,1%nat)::(1,2%nat)::(0,S zb)::(1,S y)::Z))
    with (vstackC (repeat 2%nat (S NLr'))
            ((0,1%nat)::(1,6%nat)::(0,1%nat)::(1,(3+X')%nat)
               ::(0,1%nat)::(1,2%nat)::(0,S zb)::(1,S y)::Z)).
  erewrite wrun_split by apply (d203_hops _ (S NLr') 5).
  rewrite fourk_uword.
  cbn [repeat uword].
  change ((2 + 2)%nat) with 4%nat.
  rewrite d_casc_sretX.
  cbn [repeat uword].
  reflexivity.
Qed.
Lemma FTrip_birthXg (X' dI : nat) :
  FTrip (3 * dI + 10)
    ((1,(5+X')%nat)::(0,3%nat):: uword (repeat 2%nat (S dI)) [(1,4%nat)])
    ((3+X')%nat)
    ((0,1%nat)::(1,6%nat)::(0,1%nat)::(1,3%nat)::(0,2%nat)
       :: uword (repeat 2%nat dI) [(1,4%nat)]).
Proof.
  intros zb y Z.
  replace (3 * dI + 10)%nat
    with (2 + (dI + (1 + (2 + (2 * dI + 5)))))%nat by lia.
  cbn [repeat uword].
  erewrite wrun_split by apply (d357_inXv X' _ y).
  erewrite wrun_split by apply d203_crossg_g.
  destruct dI as [|dI'].
  { erewrite wrun_split by apply d203_end.
    erewrite wrun_split by apply d203_turn.
    erewrite wrun_split by apply (d203_hops _ 0 1).
    cbn [fourk].
    erewrite d357_mintX.
    reflexivity. }
  cbn [repeat vstackC vpairC].
  erewrite wrun_split by apply d203_end.
  erewrite wrun_split by apply d203_turn.
  rewrite <- (vstack1_shift dI').
  change ((0,1%nat)::(1,2%nat)::(0,1%nat)::(1,2%nat)
            :: vstackC (repeat 2%nat dI')
                 ((0,1%nat)::(1,2%nat)::(0,1%nat)::(1,6%nat)
                    ::(0,1%nat)::(1,(3+X')%nat)::(0,1%nat)::(1,2%nat)
                    ::(0,S zb)::(1,S y)::Z))
    with (vstackC (repeat 2%nat (S dI'))
            ((0,1%nat)::(1,2%nat)::(0,1%nat)::(1,6%nat)
               ::(0,1%nat)::(1,(3+X')%nat)::(0,1%nat)::(1,2%nat)
               ::(0,S zb)::(1,S y)::Z)).
  erewrite wrun_split by apply (d203_hops _ (S dI') 1).
  rewrite fourk_uword.
  cbn [repeat uword].
  change ((2 + 2)%nat) with 4%nat.
  erewrite d357_mintX.
  cbn [repeat uword].
  reflexivity.
Qed.
Lemma d3_far_turn (L : wside) :
  wrun 1 ((0,1%nat)::(1,1%nat)::L) 0 [] = Some (L, 1, [(1,4%nat)]).
Proof. reflexivity. Qed.
Lemma d3_first (W : wside) (p : nat) (q : wside) :
  wrun 1 ((0,1%nat)::(1,2%nat)::(0,1%nat)::(1,2%nat)::W) 1 ((1,S p)::q)
  = Some ((1,1%nat)::W, 1, (1,4%nat)::(0,1%nat)::(1,S p)::q).
Proof. reflexivity. Qed.
Lemma d3_drop (W : wside) (p : nat) (q : wside) :
  wrun 1 ((1,1%nat)::(0,1%nat)::(1,2%nat)::W) 1 ((1,S p)::q)
  = Some ((0,1%nat)::(1,2%nat)::W, 1, (0,1%nat)::(1,S p)::q).
Proof. reflexivity. Qed.
Lemma FTrip_dtb3S (m : nat) :
  FTrip (3 * m + 9)
    (uword ((6%nat :: repeat 2%nat m) ++ [2%nat]) [(1,3%nat)])
    6
    ((0,1%nat)::(1,3%nat)::(0,2%nat)
       :: uword (repeat 2%nat m) ((1,4%nat)::(0,1%nat)::[(1,4%nat)])).
Proof.
  intros zb y Z.
  replace (3 * m + 9)%nat
    with (List.length ((6%nat :: repeat 2%nat m) ++ [2%nat])
          + (1 + (1 + (1 + (2 * m + (1 + 3))))))%nat
    by (rewrite !length_app; cbn [List.length];
        rewrite !repeat_length; lia).
  rewrite wrun_add, wcross_mixed.
  lazy beta iota.
  rewrite (vstack_vstackC _ _ (zheaded0 _ _)).
  rewrite rev_app_distr.
  cbn [rev app vstackC vpairC].
  rewrite rev_repeat.
  erewrite wrun_split by apply (d_far_eatv 0).
  erewrite wrun_split by apply d3_far_turn.
  rewrite vstackC_app.
  cbn [vstackC vpairC].
  erewrite wrun_split by apply d3_first.
  rewrite <- (vstack1_shift m).
  erewrite wrun_split by apply (djump_hops2 m).
  rewrite fourk_uword.
  destruct (uword_one_headed (repeat 2%nat m) 3 ((0,1%nat)::[(1,4%nat)]))
    as (p0 & q0 & EU).
  rewrite EU.
  erewrite wrun_split by apply d3_drop.
  rewrite d_endR_stopv.
  reflexivity.
Qed.
Lemma d8_inv (X' zb y : nat) (Z : wside) (r : wside) :
  wrun 2 ((0,S zb)::(1,S y)::Z) 0
    ((1,(5+X')%nat)::(0,3%nat)::(1,8%nat)::(0,2%nat)::r)
  = Some ((0,1%nat)::(1,10%nat)::(0,1%nat)::(1,(3+X')%nat)::(0,1%nat)
            ::(1,2%nat)::(0,S zb)::(1,S y)::Z, 0, r).
Proof. destruct zb; cbn; rewrite PeanoNat.Nat.add_0_r; reflexivity. Qed.
Lemma d8_ret (X' : nat) (Z : wside) (p : nat) (q : wside) :
  wrun 4 ((1,1%nat)::(0,1%nat)::(1,10%nat)::(0,1%nat)::(1,(3+X')%nat)
            ::(0,1%nat)::(1,2%nat)::Z) 1 ((1,S p)::q)
  = Some ((1,1%nat)::Z, 1,
          (1,(4+X')%nat)::(0,1%nat)::(1,11%nat)::(0,2%nat)::(1,S p)::q).
Proof.
  destruct X' as [|[|d]]; cbn; try reflexivity;
  replace (d + 0 + 2)%nat with (S (S d)) by lia; reflexivity.
Qed.
Lemma FTrip_retag8 (X' c : nat) (Win : wside) (p : nat) (q : wside) :
  FTrip c Win p q ->
  FTrip (c + 6)
    ((1,(5+X')%nat)::(0,3%nat)::(1,8%nat)::(0,2%nat):: Win)
    ((3+X')%nat)
    ((0,1%nat)::(1,11%nat)::(0,2%nat)::(1,S p)::q).
Proof.
  intros HT zb y Z.
  replace (c + 6)%nat with (2 + (c + 4))%nat by lia.
  erewrite wrun_split by apply (d8_inv X' _ y).
  rewrite wrun_add.
  rewrite (HT 0%nat 9%nat _).
  lazy beta iota.
  rewrite d8_ret.
  reflexivity.
Qed.
