Lemma zpre_cons_col (c_0 : N) (p' : list bgroup) :
  zpre p' -> zpre ((2,2,c_0)%N :: p').
Proof. intros HP. constructor; [split; [reflexivity | lia] | exact HP]. Qed.
Lemma gms_col_head (c_0 : N) (p' : list bgroup) (c0' : nat) :
  N.to_nat c_0 = S c0' ->
  gms ((2,2,c_0)%N :: p') = 0%nat :: repeat 0%nat c0' ++ gms p'.
Proof.
  intros E0. cbn [gms].
  change ((N.to_nat 2 - 2))%nat with 0%nat.
  rewrite E0. reflexivity.
Qed.
