Lemma zpre_of_forallb (p : word) :
  forallb is_col p = true -> zpre p.
Proof.
  induction p as [|[[o z] c] t IH]; intros H.
  - constructor.
  - cbn in H. apply andb_prop in H. destruct H as [H1 H2].
    unfold is_col in H1. cbn [gZ gO] in H1.
    apply andb_prop in H1. destruct H1 as [HZ HO].
    apply N.eqb_eq in HZ. apply N.leb_le in HO.
    constructor.
    + split; assumption.
    + apply IH, H2.
Qed.
Lemma skipn_wat (w : word) (i : nat) (g : bg) :
  wat w i = Some g -> skipn i w = g :: skipn (S i) w.
Proof.
  revert w. induction i as [|i IH]; intros w H.
  - destruct w; cbn in *; [discriminate|]. now inversion H.
  - destruct w; cbn in *; [discriminate|]. now apply IH.
Qed.
Lemma word_split (w : word) (i : nat) (g : bg) :
  wat w i = Some g ->
  w = firstn i w ++ g :: skipn (S i) w.
Proof.
  intros H.
  rewrite <- (firstn_skipn i w) at 1.
  f_equal. now apply skipn_wat.
Qed.
Lemma wstep_halts_pull (s s' : wstate) :
  wstep s s' ->
  halts tmB (wconf' s') ->
  halts tmB (wconf' s).
Proof.
  intros [fw HW] Hh.
  destruct s as [[l cur] r].
  eapply wrun_some_halts; eauto.
Qed.
Lemma absorb_branch_sound (p : word) (A NL : N) (t : word) (f : N) :
  forallb is_col p = true ->
  (2 <= A)%N ->
  wstep ([], 0, sdecode ((p ++ (A,1,1) :: (5,2,1) :: (4,2,NL) :: t)%N) f)
        ([], 0, sdecode (((2,2,1) :: p ++ (A,1,1) :: (4,2,(NL+1)) :: t)%N) f).
Proof.
  intros HP HA.
  pose proof (bridge_tick_p p A 5 2 ((4,2,NL)%N :: t) f
                (zpre_of_forallb p HP) HA ltac:(lia) ltac:(lia)) as BT.
  replace ((5 - 1)%N) with 4%N in BT by lia.
  match type of BT with
  | wstep _ ([], 0, bdecode (?W, _)) =>
      replace (bdecode (W, f))
        with (sdecode (((2,2,1) :: p ++ (A,1,1) :: (4,2,(NL+1)) :: t)%N) f)
        in BT
  end.
  { exact BT. }
  change (bdecode (?W, f)) with (sdecode W f).
  symmetry.
  rewrite !sdecode_cons.
  f_equal.
  apply sdecode_app_ctx.
  rewrite !sdecode_cons.
  f_equal.
  rewrite app_assoc, <- gdec1_merge.
  replace ((1 + NL)%N) with ((NL + 1)%N) by lia.
  reflexivity.
Qed.
Lemma sdecode_harvest0 (q : word) (A : N) :
  (1 <= A)%N ->
  sdecode ((q ++ [(A,1,1)])%N) 0 = sdecode q A ++ [(0,1%nat)].
Proof.
  intros HA.
  induction q as [|g q IH].
  - cbn [app]. unfold sdecode, bdecode.
    cbn [map gdecode expand].
    rewrite (frun_pos A) by lia.
    change (N.to_nat 1) with 1%nat.
    repeat first [rewrite <- app_assoc
                 | progress cbn [app pair_runs frun]].
    reflexivity.
  - cbn [app]. rewrite !sdecode_cons, IH, app_assoc. reflexivity.
Qed.
Lemma harvest_branch_sound (p : word) (A : N) :
  forallb is_col p = true -> (2 <= A)%N ->
  halts tmB (wconf [] 0 (sdecode ((2,2,1)%N :: p) A)) ->
  halts tmB (wconf [] 0 (sdecode ((p ++ [(A,1,1)])%N) 1)).
Proof.
  intros HP HA Hh.
  assert (E : bdecode (((2,2,1)%N :: p ++ [(A,1,1)%N]), 0%N)
            = sdecode ((2,2,1)%N :: p) A ++ [(0,1%nat)]).
  { exact (sdecode_harvest0 ((2,2,1)%N :: p) A
             (N.le_trans _ _ _ (N.le_succ_diag_r 1) HA)). }
  assert (Hmid : halts tmB
    (wconf' ([], 0, bdecode (((2,2,1)%N :: p ++ [(A,1,1)%N]), 0%N)))).
  { cbn [wconf'].
    rewrite E, wconf_snoc0.
    exact Hh. }
  exact (wstep_halts_pull _ _
           (bridge_harvest_p p A (zpre_of_forallb p HP) HA) Hmid).
Qed.
