Definition sound_impl (w : word) (f : N) (w' : word) (f' : N) : Prop :=
  halts tmB (wconf [] 0 (sdecode w' f')) ->
  halts tmB (wconf [] 0 (sdecode w f)).
Lemma wstep_sound_impl w f w' f' :
  wstep ([], 0, sdecode w f) ([], 0, sdecode w' f') ->
  sound_impl w f w' f'.
Proof.
  intros HW Hh.
  exact (wstep_halts_pull ([],0,sdecode w f) ([],0,sdecode w' f') HW Hh).
Qed.
Definition StepSound : Prop :=
  forall w f h w' f' i,
    step w f h = (ROk w' f', i) ->
    sound_impl w f w' f'.
Definition StepGuard : Prop :=
  forall w f h i,
    step w f h = (RHalt, i) ->
    halts tmB (wconf [] 0 (sdecode w f)).
