Lemma guard_halts (p : word) (zn cn : N) (t : word) (f : N) :
  forallb is_col p = true ->
  (1 <= zn)%N -> (1 <= cn)%N ->
  halts tmB (wconf [] 0 (sdecode ((p ++ (1,zn,cn) :: t)%N) f)).
Proof.
  intros HP Hz Hc.
  destruct (to_nat_ge1 zn Hz) as [z Ez].
  destruct (to_nat_ge1 cn Hc) as [c Ec].
  pose proof (zpre_of_forallb p HP) as HZP.
  assert (E1 : sdecode ((p ++ (1,zn,cn) :: t)%N) f
             = uword (gms p)
                 ((1,1%nat) :: (0,S z)
                    :: pair_runs 1%nat (S z) c
                    ++ expand (map gdecode t) ++ frun f)).
  { unfold sdecode.
    rewrite bdecode_pre, (uword_gms _ _ HZP).
    f_equal.
    unfold bdecode. cbn [map gdecode expand].
    rewrite Ez, Ec.
    change (N.to_nat 1) with 1%nat.
    repeat first [rewrite <- app_assoc | progress cbn [app pair_runs]].
    reflexivity. }
  rewrite E1.
  eapply wrun_some_halts.
  { apply wcross_mixed. }
  cbn [wconf'].
  apply (wrun_none_halts 1%nat).
  cbn [wrun].
  destruct z as [|z']; unfold wsection; cbn [wpop]; reflexivity.
Qed.
Lemma guard_deep_halts (p : word) (X NL : N) (mid : word)
      (zn cn : N) (t : word) (f : N) :
  forallb is_col p = true ->
  (3 <= X)%N -> (1 <= NL)%N ->
  forallb is_col mid = true ->
  (1 <= zn)%N -> (1 <= cn)%N ->
  halts tmB (wconf [] 0
    (sdecode ((p ++ (X,3,1) :: (4,2,NL) :: mid ++ (1,zn,cn) :: t)%N) f)).
Proof.
  intros HP HX HN HM Hz Hc.
  assert (EX : exists x, N.to_nat X = S (S (S x))).
  { destruct (N.to_nat X) as [|[|[|x]]] eqn:E; try (exfalso; lia). eauto. }
  destruct EX as [x EXx].
  destruct (to_nat_ge1 NL HN) as [n1 EN].
  destruct (to_nat_ge1 zn Hz) as [z Ez].
  destruct (to_nat_ge1 cn Hc) as [c Ec].
  pose proof (zpre_of_forallb p HP) as HZP.
  pose proof (zpre_of_forallb mid HM) as HZM.
  set (REST := pair_runs 1%nat (S z) c
               ++ expand (map gdecode t) ++ frun f).
  assert (E1 : sdecode ((p ++ (X,3,1) :: (4,2,NL) :: mid ++ (1,zn,cn) :: t)%N) f
             = uword (gms p)
                 ((1, S (S (S x))) :: (0,3%nat) :: (1,4%nat) :: (0,2%nat)
                    :: uword (repeat 2%nat n1 ++ gms mid)
                         ((1,1%nat) :: (0,S z) :: REST))).
  { unfold sdecode.
    rewrite bdecode_pre, (uword_gms _ _ HZP).
    f_equal.
    rewrite (uword_app_ms (repeat 2%nat n1)), uword_repeat_w,
            (uword_gms _ _ HZM).
    unfold bdecode. cbn [map gdecode expand].
    rewrite map_app, expand_app. cbn [map gdecode expand].
    rewrite EXx, EN, Ez, Ec.
    change (N.to_nat 3) with 3%nat.
    change (N.to_nat 4) with 4%nat.
    change (N.to_nat 2) with 2%nat.
    change (N.to_nat 1) with 1%nat.
    unfold REST.
    repeat first [rewrite <- app_assoc | progress cbn [app pair_runs]].
    reflexivity. }
  rewrite E1.
  eapply wrun_some_halts. { apply wcross_mixed. }
  cbn [wconf'].
  eapply wrun_some_halts.
  { apply dborrow_in'.
    rewrite (vstack_vstackC _ [] I).
    apply vstackC_zheaded. exact I. }
  cbn [wconf'].
  eapply wrun_some_halts. { apply wcross_mixed. }
  cbn [wconf'].
  apply (wrun_none_halts 1%nat).
  cbn [wrun].
  destruct z as [|z']; unfold wsection; cbn [wpop]; reflexivity.
Qed.
Lemma zheaded_vstack (ms : list nat) (Z : wside) :
  zheaded Z -> zheaded (vstack ms Z).
Proof.
  intros H. rewrite (vstack_vstackC _ _ H). apply vstackC_zheaded. exact H.
Qed.
Lemma dying_ms (L : wside) (ms : list nat) (z : nat) (R : wside) :
  halts tmB (wconf L 0 (uword ms ((1,1%nat) :: (0,S z) :: R))).
Proof.
  eapply wrun_some_halts. { apply wcross_mixed. }
  cbn [wconf'].
  apply (wrun_none_halts 1%nat).
  cbn [wrun].
  destruct z as [|z']; unfold wsection; cbn [wpop]; reflexivity.
Qed.
Lemma trig_ms (L : wside) (ms : list nat) (x : nat) (R : wside) :
  zheaded L ->
  halts tmB (wconf ((0,1%nat) :: (1,6%nat) :: (0,1%nat) :: (1,S x)
                     :: (0,1%nat) :: (1,2%nat) :: vstack ms L) 0 R) ->
  halts tmB (wconf L 0
     (uword ms ((1, S (S (S x))) :: (0,3%nat) :: (1,4%nat) :: (0,2%nat) :: R))).
Proof.
  intros HZ Hh.
  eapply wrun_some_halts. { apply wcross_mixed. }
  cbn [wconf'].
  eapply wrun_some_halts.
  { apply dborrow_in'. apply zheaded_vstack. exact HZ. }
  cbn [wconf'].
  exact Hh.
Qed.
Definition trg : Type := (N * N * word)%type.
Fixpoint dchain (ch : list trg) (tl : word) : word :=
  match ch with
  | [] => tl
  | (X, NL, mid) :: r => (X,3,1)%N :: (4,2,NL)%N :: mid ++ dchain r tl
  end.
Definition trgok (e : trg) : bool :=
  let '(X, NL, mid) := e in
  (3 <=? X)%N && (1 <=? NL)%N && forallb is_col mid.
Lemma guard_chain_gen (L : wside) (p : word) (ch : list trg)
      (zn cn : N) (t : word) (f : N) :
  zheaded L ->
  forallb is_col p = true ->
  forallb trgok ch = true ->
  (1 <= zn)%N -> (1 <= cn)%N ->
  halts tmB (wconf L 0
    (bdecode ((p ++ dchain ch ((1,zn,cn)%N :: t))%N, f))).
Proof.
  intros HZ0 HP0 HC0 Hz Hc. revert L p HZ0 HP0 HC0.
  induction ch as [|[[X NL] mid] ch IH]; intros L p HZ HP HC.
  -
    destruct (to_nat_ge1 zn Hz) as [z Ez].
    destruct (to_nat_ge1 cn Hc) as [c Ec].
    assert (E1 : bdecode ((p ++ ((1,zn,cn)%N :: t))%N, f)
               = uword (gms p)
                   ((1,1%nat) :: (0,S z)
                      :: pair_runs 1%nat (S z) c
                         ++ expand (map gdecode t) ++ frun f)).
    { rewrite bdecode_pre, (uword_gms _ _ (zpre_of_forallb p HP)).
      f_equal.
      unfold bdecode. cbn [map gdecode expand].
      rewrite Ez, Ec.
      change (N.to_nat 1) with 1%nat.
      cbn [pair_runs app].
      rewrite <- ?app_assoc. reflexivity. }
    cbn [dchain]. rewrite E1. apply dying_ms.
  -
    cbn [forallb] in HC. apply andb_prop in HC. destruct HC as (HE & HC').
    unfold trgok in HE.
    apply andb_prop in HE. destruct HE as (HE1 & HM).
    apply andb_prop in HE1. destruct HE1 as (HX & HN).
    apply N.leb_le in HX. apply N.leb_le in HN.
    assert (EX : exists x, N.to_nat X = S (S (S x))).
    { destruct (N.to_nat X) as [|[|[|x]]] eqn:E; try (exfalso; lia). eauto. }
    destruct EX as [x EXx].
    destruct (to_nat_ge1 NL HN) as [n1 EN].
    assert (HPQ : forallb is_col ((4,2,N.of_nat n1)%N :: mid) = true).
    { cbn [forallb]. rewrite HM. reflexivity. }
    assert (E1 : bdecode
                   ((p ++ (X,3,1)%N :: (4,2,NL)%N
                        :: mid ++ dchain ch ((1,zn,cn)%N :: t))%N, f)
               = uword (gms p)
                   ((1, S (S (S x))) :: (0,3%nat) :: (1,4%nat) :: (0,2%nat)
                      :: uword (repeat 2%nat n1 ++ gms mid)
                           (bdecode
                              ((dchain ch ((1,zn,cn)%N :: t))%N, f)))).
    { rewrite bdecode_pre, (uword_gms _ _ (zpre_of_forallb p HP)).
      f_equal.
      rewrite (uword_app_ms (repeat 2%nat n1)), uword_repeat_w,
              (uword_gms _ _ (zpre_of_forallb mid HM)).
      unfold bdecode. cbn [map gdecode expand].
      rewrite map_app, expand_app. cbn [map gdecode expand].
      rewrite EXx, EN.
      change (N.to_nat 3) with 3%nat.
      change (N.to_nat 4) with 4%nat.
      change (N.to_nat 2) with 2%nat.
      change (N.to_nat 1) with 1%nat.
      change (2 + 2)%nat with 4%nat.
      cbn [pair_runs app].
      rewrite <- ?app_assoc. reflexivity. }
    cbn [dchain]. rewrite E1.
    apply trig_ms; [exact HZ|].
    specialize (IH ((0,1%nat) :: (1,6%nat) :: (0,1%nat) :: (1,S x)
                      :: (0,1%nat) :: (1,2%nat)
                      :: vstack (gms p) L)
                   ((4,2,N.of_nat n1)%N :: mid)).
    rewrite bdecode_pre in IH.
    rewrite <- (uword_gms _ _ (zpre_of_forallb _ HPQ)) in IH.
    cbn [gms] in IH.
    rewrite Nat2N.id in IH.
    change (N.to_nat 4 - 2)%nat with 2%nat in IH.
    apply IH; try assumption.
    cbn. reflexivity.
Qed.
Lemma csplit_cols (s c r : word) :
  csplit s = (c, r) -> forallb is_col c = true /\ s = c ++ r.
Proof.
  revert c r. induction s as [|g t IH]; intros c r H.
  - cbn in H. injection H as <- <-. split; reflexivity.
  - cbn in H. destruct (is_col g) eqn:EG.
    + destruct (csplit t) as [c' r'] eqn:ET.
      injection H as <- <-.
      destruct (IH c' r' eq_refl) as (HC & HE).
      split; [cbn; rewrite EG, HC; reflexivity | cbn; rewrite <- HE; reflexivity].
    + injection H as <- <-. split; reflexivity.
Qed.
Lemma e0_chain_decomp (n : nat) (s : word) :
  e0_chain n s = true ->
  exists ch zn cn t,
    s = dchain ch ((1,zn,cn)%N :: t)
    /\ forallb trgok ch = true /\ (1 <= zn)%N /\ (1 <= cn)%N.
Proof.
  revert s. induction n as [|n IH]; intros s H; [discriminate|].
  cbn [e0_chain] in H.
  destruct s as [|[[X z] c] s1]; [discriminate|].
  destruct s1 as [|[[o2 z2] NL] r]; [discriminate|].
  destruct (csplit r) as [cols rest] eqn:ECS.
  destruct (csplit_cols _ _ _ ECS) as (HCOL & HRE).
  apply andb_prop in H; destruct H as (HG & HTAIL).
  apply andb_prop in HG; destruct HG as (HG & HNL).
  apply andb_prop in HG; destruct HG as (HG & HZ2).
  apply andb_prop in HG; destruct HG as (HG & HO2).
  apply andb_prop in HG; destruct HG as (HG & HX).
  apply andb_prop in HG; destruct HG as (HZ3 & HC1).
  apply N.eqb_eq in HZ3. apply N.eqb_eq in HC1.
  apply N.eqb_eq in HO2. apply N.eqb_eq in HZ2.
  subst z c o2 z2.
  apply N.leb_le in HX. apply N.leb_le in HNL.
  assert (HTRG : trgok (X, NL, cols) = true).
  { unfold trgok. apply andb_true_intro. split.
    - apply andb_true_intro. split.
      + apply N.leb_le. exact HX.
      + apply N.leb_le. exact HNL.
    - exact HCOL. }
  destruct rest as [|[[o3 zn] cn] rest1]; [discriminate|].
  destruct ((o3 =? 1)%N) eqn:EO3.
  - apply N.eqb_eq in EO3. subst o3.
    apply andb_prop in HTAIL. destruct HTAIL as (HZN & HCN).
    apply N.leb_le in HZN. apply N.leb_le in HCN.
    exists [(X, NL, cols)], zn, cn, rest1.
    split; [|split; [|split]]; try assumption.
    + cbn [dchain]. rewrite HRE. reflexivity.
    + cbn [forallb]. rewrite HTRG. reflexivity.
  - destruct (IH _ HTAIL) as (ch & zn' & cn' & t & HEQ & HCH & HZ & HC).
    exists ((X, NL, cols) :: ch), zn', cn', t.
    split; [|split; [|split]]; try assumption.
    + cbn [dchain]. rewrite HRE, HEQ. reflexivity.
    + cbn [forallb]. rewrite HTRG, HCH. reflexivity.
Qed.
Lemma guard_chain_halts (p : word) (ch : list trg)
      (zn cn : N) (t : word) (f : N) :
  forallb is_col p = true ->
  forallb trgok ch = true ->
  (1 <= zn)%N -> (1 <= cn)%N ->
  halts tmB (wconf [] 0 (sdecode ((p ++ dchain ch ((1,zn,cn)%N :: t))%N) f)).
Proof.
  intros HP HC Hz Hc.
  unfold sdecode.
  exact (guard_chain_gen [] p ch zn cn t f I HP HC Hz Hc).
Qed.
Local Open Scope N_scope.
Local Open Scope bool_scope.
Local Open Scope sym.
Local Open Scope N_scope.
Local Open Scope bool_scope.
Local Open Scope sym.
Local Open Scope list.
Local Open Scope bool_scope.
Lemma cma_rhalt_inv (fuel : nat) (w : word) (f : N) (i : nat) :
  chain_merge_advance fuel w f i = RHalt ->
  exists zn cn,
    wat w (S i) = Some (1%N, zn, cn) /\ (1 <= zn)%N /\ (1 <= cn)%N.
Proof.
  revert w f i.
  induction fuel as [|fuel IH]; intros w f i H; cbn [chain_merge_advance] in H.
  - discriminate.
  - destruct (wat w i) as [[[o z] c]|] eqn:E0; [|discriminate].
    destruct (Nat.eqb (S i) (length w)) eqn:EL.
    +
      destruct ((c =? 1)%N); [|discriminate].
      unfold far_end_merge_fire in H.
      destruct (wat w i) as [[[o' z'] c']|]; [|discriminate].
      destruct (f =? 3)%N; [discriminate|].
      destruct (f =? 2)%N; [discriminate|].
      destruct (f =? 4)%N; discriminate.
    + destruct (wat w (S i)) as [[[on zn] cn]|] eqn:E1; [|discriminate].
      destruct (on =? 1)%N eqn:EON.
      * destruct ((1 <=? zn)%N && (1 <=? cn)%N) eqn:EZC; [|discriminate].
        apply andb_prop in EZC. destruct EZC as [EZ EC].
        apply N.leb_le in EZ. apply N.leb_le in EC.
        apply N.eqb_eq in EON. subst on.
        eauto.
      *
        repeat first
          [ discriminate
          | match type of H with
            | context [if ?b then _ else _] => destruct b eqn:?
            | context [match ?x with _ => _ end] => destruct x eqn:?
            end ].
Qed.
Lemma dtb_no_rhalt (w : word) (f : N) :
  debris_to_blank w f <> RHalt.
Proof.
  unfold debris_to_blank.
  repeat first
    [ discriminate
    | match goal with
      | |- (if ?b then _ else _) <> _ => destruct b eqn:?
      | |- (match ?x with _ => _ end) <> _ => destruct x eqn:?
      end ].
Qed.
Lemma renewal_no_rhalt (fuel : nat) (w : word) (f : N) (i : nat) (vd : bool) :
  renewal fuel w f i vd <> RHalt.
Proof.
  revert w f i vd.
  induction fuel as [|fuel IH]; intros w f i vd; cbn [renewal].
  - discriminate.
  - repeat first
      [ discriminate
      | apply dtb_no_rhalt
      | match goal with
        | |- (if ?b then _ else _) <> _ => destruct b eqn:?
        | |- (match ?x with _ => _ end) <> _ => destruct x eqn:?
        end ].
Qed.
Lemma fire_rhalt_inv (fuel : nat) (w : word) (f : N) (i : nat) (vd : bool)
      (o z c : N) :
  wat w i = Some (o, z, c) ->
  (3 <= z)%N -> (z < 4)%N -> c = 1%N ->
  fire fuel w f i vd = RHalt ->
  exists NL w2 base j zn cn,
    z = 3%N /\ (5 <= o)%N /\
    wat w (S i) = Some (4%N, 2%N, NL) /\ (1 <= NL)%N /\
    w2 = subst_at i 2
           ((o-1,1,1)%N :: (7,2,1)%N
            :: (if (1 <? NL)%N then [(4,2,NL-1)%N] else [])) w /\
    base = (if (1 <? NL)%N then S (S (S i)) else S (S i)) /\
    tick_target w2 base = Some j /\
    (exists g2, wat w2 j = Some g2 /\ is_cmf g2 = true) /\
    wat w2 (S j) = Some (1%N, zn, cn) /\ (1 <= zn)%N /\ (1 <= cn)%N.
Proof.
  intros E0 HZ3 HZ4 -> H.
  assert (EZ : z = 3%N) by lia. subst z.
  destruct fuel as [|fuel]; cbn [fire] in H; [discriminate|].
  rewrite E0 in H.
  destruct ((4 <=? 3)%N) eqn:EZ4; [discriminate EZ4|].
  cbn in EZ4. clear EZ4.
  destruct ((o =? 3)%N && _) eqn:E33 in H.
  { repeat first
      [ discriminate
      | match type of H with
        | context [if ?b then _ else _] => destruct b eqn:?
        | context [match ?x with _ => _ end] => destruct x eqn:?
        end ]. }
  destruct ((o =? 4)%N) eqn:EO4.
  { exfalso. exact (renewal_no_rhalt _ _ _ _ _ H). }
  destruct (negb (5 <=? o)%N) eqn:EO5; [discriminate|].
  apply negb_false_iff in EO5. apply N.leb_le in EO5.
  destruct (wat w (S i)) as [[[on zn] cn]|] eqn:E1;
    [|destruct ((2 <=? f)%N); discriminate].
  destruct ((on =? 4)%N && (zn =? 2)%N && (1 <=? cn)%N
            && Nat.eqb (S (S i)) (length w)
            && (f =? 4)%N) eqn:EBIRTH; [discriminate|].
  destruct ((on =? 4)%N && (zn =? 2)%N) eqn:E42.
  - apply andb_prop in E42. destruct E42 as [EON EZN].
    apply N.eqb_eq in EON. apply N.eqb_eq in EZN. subst on zn.
    destruct (negb (1 <=? cn)%N) eqn:ENL; [discriminate|].
    apply negb_false_iff in ENL. apply N.leb_le in ENL.
    destruct (tick_target _ _) eqn:ETT in H.
    + destruct (wat _ n) as [g2|] eqn:EG2 in H; [|discriminate].
      destruct (is_cmf g2) eqn:ECMF in H.
      * apply cma_rhalt_inv in H.
        destruct H as (zn' & cn' & HW & HZ & HC).
        eexists cn, _, _, n, zn', cn'.
        repeat split; try assumption; try reflexivity.
        eauto.
      * destruct (deliver_tick _ _ _ _ _) in H; discriminate.
    + destruct (forallb is_col _) in H; [|discriminate].
      exfalso. eapply dtb_no_rhalt. exact H.
  - repeat first
      [ discriminate
      | exfalso; eapply dtb_no_rhalt; exact H
      | match type of H with
        | context [if ?b then _ else _] => destruct b eqn:?
        | context [match ?x with _ => _ end] => destruct x eqn:?
        end ].
Qed.
Lemma fire_z4_no_rhalt (fuel : nat) (w : word) (f : N) (i : nat)
      (vd : bool) (o z c : N) :
  wat w i = Some (o, z, c) ->
  (4 <= z)%N ->
  fire fuel w f i vd <> RHalt.
Proof.
  intros E0 HZ H.
  destruct fuel as [|fuel]; cbn [fire] in H; [discriminate|].
  rewrite E0 in H.
  apply N.leb_le in HZ. rewrite HZ in H.
  repeat first
    [ discriminate
    | exact (renewal_no_rhalt _ _ _ _ _ H)
    | exfalso; eapply dtb_no_rhalt; exact H
    | match type of H with
      | context [if ?b then _ else _] => destruct b eqn:?
      | context [match ?x with _ => _ end] => destruct x eqn:?
      end ].
Qed.
Lemma dt_rhalt_inv (fuel : nat) (w : word) (f : N) (i : nat) (vd : bool)
      (o z c : N) :
  wat w i = Some (o, z, c) ->
  (3 <= z)%N ->
  deliver_tick fuel w f i vd = RHalt ->
  exists NL w2 base j zn cn,
    z = 3%N /\ c = 1%N /\ (5 <= o)%N /\
    wat w (S i) = Some (4%N, 2%N, NL) /\ (1 <= NL)%N /\
    w2 = subst_at i 2
           ((o-1,1,1)%N :: (7,2,1)%N
            :: (if (1 <? NL)%N then [(4,2,NL-1)%N] else [])) w /\
    base = (if (1 <? NL)%N then S (S (S i)) else S (S i)) /\
    tick_target w2 base = Some j /\
    (exists g2, wat w2 j = Some g2 /\ is_cmf g2 = true) /\
    wat w2 (S j) = Some (1%N, zn, cn) /\ (1 <= zn)%N /\ (1 <= cn)%N.
Proof.
  intros E0 HZ3 H.
  destruct fuel as [|fuel]; cbn [deliver_tick] in H; [discriminate|].
  rewrite E0 in H.
  destruct ((z =? 1)%N) eqn:EZ1.
  { apply N.eqb_eq in EZ1. lia. }
  apply N.leb_le in HZ3. rewrite HZ3 in H.
  apply N.leb_le in HZ3.
  destruct ((c =? 1)%N) eqn:EC; [|discriminate].
  apply N.eqb_eq in EC. subst c.
  destruct ((4 <=? z)%N) eqn:EZ4.
  + exfalso.
    eapply fire_z4_no_rhalt; [exact E0| |exact H].
    apply N.leb_le. exact EZ4.
  + assert (HZ4 : (z < 4)%N).
    { apply N.leb_gt in EZ4. exact EZ4. }
    destruct (fire_rhalt_inv _ _ _ _ _ _ _ _ E0 HZ3 HZ4 eq_refl H)
      as (NL & w2 & base & j & zn & cn & EZq & HO & E1 & HNL & EW2 & EB & ETT & HCMF & EG & HZ & HC).
    eexists NL, w2, base, j, zn, cn.
    repeat split; assumption.
Qed.
Lemma find_active_s_inv (w : word) (s i : nat) :
  find_active_s w s = Some i ->
  (s <= i)%nat /\
  exists o z c,
    nth_error w (i - s) = Some (o, z, c) /\
    ((z = 1%N) \/ (3 <= z)%N).
Proof.
  revert s. induction w as [|[[o z] c] t IH]; intros s H; cbn in H.
  - discriminate.
  - destruct ((z =? 1)%N || (3 <=? z)%N) eqn:EA.
    + inversion H; subst i.
      split; [lia|].
      rewrite PeanoNat.Nat.sub_diag. cbn.
      exists o, z, c. split; [reflexivity|].
      apply orb_prop in EA.
      destruct EA as [E|E]; [left; apply N.eqb_eq, E | right; apply N.leb_le, E].
    + apply IH in H.
      destruct H as (HLE & o' & z' & c' & HN & HZ).
      split; [lia|].
      exists o', z', c'.
      split; [|assumption].
      replace (i - s)%nat with (S (i - S s))%nat by lia.
      cbn. exact HN.
Qed.
Lemma find_active_inv (w : word) (start i : nat) :
  find_active w start = Some i ->
  (start <= i)%nat /\
  exists o z c,
    wat w i = Some (o, z, c) /\
    ((z = 1%N) \/ (3 <= z)%N).
Proof.
  unfold find_active, wat.
  intros H.
  apply find_active_s_inv in H.
  destruct H as (HLE & o & z & c & HN & HZ).
  split; [assumption|].
  exists o, z, c. split; [|assumption].
  rewrite <- HN.
  rewrite nth_error_skipn.
  f_equal. lia.
Qed.
Lemma cmf_from_inv (w : word) (i n j : nat) :
  cmf_from w i n = Some j ->
  (i <= j)%nat /\
  exists g, wat w j = Some g /\ is_cmf g = true.
Proof.
  revert i. induction n as [|n IH]; intros i H; cbn in H.
  - discriminate.
  - destruct (wat w i) as [g|] eqn:E0; [|discriminate].
    destruct (is_cmf g) eqn:EC.
    + inversion H; subst j. split; [lia|]. eauto.
    + apply IH in H. destruct H as (HLE & HG).
      split; [lia | exact HG].
Qed.
Lemma tick_target_s_inv (w : word) (s k : nat) :
  tick_target_s w s = Some k ->
  (s <= k)%nat /\
  (exists g, nth_error w (k - s) = Some g /\
     ((gZ g = 1%N) \/ (3 <= gZ g)%N \/ is_cmf g = true)) /\
  (forall m, (s <= m < k)%nat ->
     exists g, nth_error w (m - s) = Some g /\ is_col g = true).
Proof.
  revert s. induction w as [|g t IH]; intros s H; cbn in H.
  - discriminate.
  - destruct ((gZ g =? 1)%N || (3 <=? gZ g)%N) eqn:EA.
    + inversion H; subst k.
      split; [lia|]. split.
      * rewrite PeanoNat.Nat.sub_diag. cbn.
        exists g. split; [reflexivity|].
        apply orb_prop in EA.
        destruct EA as [E|E];
          [left; apply N.eqb_eq, E | right; left; apply N.leb_le, E].
      * intros m Hm. lia.
    + destruct (is_cmf g) eqn:ECMF.
      * inversion H; subst k.
        split; [lia|]. split.
        -- rewrite PeanoNat.Nat.sub_diag. cbn.
           exists g. split; [reflexivity | right; right; exact ECMF].
        -- intros m Hm. lia.
      * destruct (is_col g) eqn:ECOL; [|discriminate].
        apply IH in H.
        destruct H as (HLE & (g' & HN & HS) & HALL).
        split; [lia|]. split.
        -- exists g'. split; [|assumption].
           replace (k - s)%nat with (S (k - S s))%nat by lia.
           cbn. exact HN.
        -- intros m Hm.
           destruct (PeanoNat.Nat.eq_dec m s) as [->|NE].
           ++ exists g. rewrite PeanoNat.Nat.sub_diag. cbn.
              split; [reflexivity | exact ECOL].
           ++ destruct (HALL m ltac:(lia)) as (g2 & HN2 & HC2).
              exists g2. split; [|assumption].
              replace (m - s)%nat with (S (m - S s))%nat by lia.
              cbn. exact HN2.
Qed.
Lemma tick_target_inv (w : word) (j k : nat) :
  tick_target w j = Some k ->
  (j <= k)%nat /\
  (exists g, wat w k = Some g /\
     ((gZ g = 1%N) \/ (3 <= gZ g)%N \/ is_cmf g = true)) /\
  (forall m, (j <= m < k)%nat ->
     exists g, wat w m = Some g /\ is_col g = true).
Proof.
  unfold tick_target, wat.
  intros H.
  apply tick_target_s_inv in H.
  destruct H as (HLE & (g & HN & HS) & HALL).
  split; [assumption|]. split.
  - exists g. split; [|assumption].
    rewrite <- HN, nth_error_skipn. f_equal. lia.
  - intros m Hm.
    destruct (HALL m Hm) as (g2 & HN2 & HC2).
    exists g2. split; [|assumption].
    rewrite <- HN2, nth_error_skipn. f_equal. lia.
Qed.
Lemma pointwise_slice_col (w : word) (a n : nat) :
  (forall m, (a <= m < a + n)%nat ->
     exists g, wat w m = Some g /\ is_col g = true) ->
  forallb is_col (firstn n (skipn a w)) = true.
Proof.
  revert a. induction n as [|n IH]; intros a HP.
  - reflexivity.
  - destruct (HP a ltac:(lia)) as (g & HW & HC).
    rewrite (skipn_wat w a g HW).
    cbn [firstn forallb].
    rewrite HC. cbn [andb].
    apply IH.
    intros m Hm. apply HP. lia.
Qed.
Lemma wat_subst_high (i k : nat) (rep : word) (w : word) (n : nat) :
  (i <= length w)%nat ->
  (i + length rep <= n)%nat ->
  wat (subst_at i k rep w) n
  = wat w (n + k - length rep).
Proof.
  intros HI HN.
  unfold subst_at, wat.
  rewrite nth_error_app2
    by (rewrite firstn_length_le by exact HI; lia).
  rewrite firstn_length_le by exact HI.
  rewrite nth_error_app2 by lia.
  rewrite nth_error_skipn.
  f_equal. lia.
Qed.
Lemma skipn_skipn (A : Type) (a b : nat) (l : list A) :
  skipn a (skipn b l) = skipn (b + a) l.
Proof.
  revert l. induction b as [|b IH]; intros l; cbn.
  - reflexivity.
  - destruct l; cbn.
    + rewrite skipn_nil. reflexivity.
    + apply IH.
Qed.
Lemma generic_rhalt_halts (w : word) (f : N) (i : nat)
      (o NL zn cn : N) (jw : nat) :
  forallb is_col (firstn i w) = true ->
  wat w i = Some (o, 3%N, 1%N) ->
  (5 <= o)%N ->
  wat w (S i) = Some (4%N, 2%N, NL) ->
  (1 <= NL)%N ->
  (S (S i) <= jw)%nat ->
  (forall m, (S (S i) <= m < jw)%nat ->
     exists g, wat w m = Some g /\ is_col g = true) ->
  wat w jw = Some (1%N, zn, cn) ->
  (1 <= zn)%N -> (1 <= cn)%N ->
  halts tmB (wconf [] 0 (sdecode w f)).
Proof.
  intros HP E0 HO E1 HNL HLE HMID EG HZ HC.
  set (mid := firstn (jw - S (S i)) (skipn (S (S i)) w)).
  assert (EW : w = firstn i w
                 ++ (o,3%N,1%N) :: (4%N,2%N,NL) :: mid
                 ++ (1%N,zn,cn) :: skipn (S jw) w).
  { rewrite (word_split w i _ E0) at 1.
    f_equal. f_equal.
    rewrite (skipn_wat w (S i) _ E1).
    f_equal.
    unfold mid.
    rewrite <- (firstn_skipn (jw - S (S i)) (skipn (S (S i)) w)) at 1.
    f_equal.
    rewrite skipn_skipn.
    replace (S (S i) + (jw - S (S i)))%nat with jw by lia.
    apply (skipn_wat w jw _ EG). }
  rewrite EW.
  apply guard_deep_halts; try assumption.
  all: first
    [ lia
    | unfold mid; apply pointwise_slice_col;
      intros m Hm; apply HMID; lia ].
Qed.
Lemma inert_rhalt_halts (w : word) (f : N) (j : nat) (g : bg)
      (zn cn : N) :
  forallb is_col (firstn j w) = true ->
  wat w j = Some g ->
  is_col g = true ->
  wat w (S j) = Some (1%N, zn, cn) ->
  (1 <= zn)%N -> (1 <= cn)%N ->
  halts tmB (wconf [] 0 (sdecode w f)).
Proof.
  intros HP EJ HCJ EG HZ HC.
  assert (EW : w = (firstn j w ++ [g]) ++ (1%N,zn,cn) :: skipn (S (S j)) w).
  { rewrite <- app_assoc. cbn [app].
    rewrite (word_split w j _ EJ) at 1.
    f_equal. f_equal.
    apply (skipn_wat w (S j) _ EG). }
  rewrite EW.
  apply guard_halts; try assumption.
  rewrite forallb_app. rewrite HP. cbn.
  rewrite HCJ. reflexivity.
Qed.
Opaque FUEL.
Opaque deliver_tick fire renewal chain_merge_advance.
Opaque fire_comp leaf_act debris_to_blank.
Lemma wat_len (w : word) (n : nat) (g : bg) :
  wat w n = Some g -> (n < length w)%nat.
Proof.
  intros H. apply nth_error_Some. unfold wat in H. congruence.
Qed.
Lemma cmf_is_col (g : bg) :
  is_cmf g = true -> is_col g = true.
Proof.
  unfold is_cmf, is_col.
  intros H.
  apply andb_prop in H. destruct H as (H & _).
  apply andb_prop in H. destruct H as (H & _).
  apply andb_prop in H. destruct H as (H & H5).
  apply andb_prop in H. destruct H as (HZ & _).
  rewrite HZ. cbn.
  apply N.leb_le in H5. apply N.leb_le. lia.
Qed.
Lemma payload_to_halts (w0 w1c : word) (f : N) (i0 : nat)
      (o NL : N) (w2 : word) (base j : nat) (zn cn : N) :
  (forall n, (1 <= n)%nat -> wat w1c n = wat w0 n) ->
  forallb is_col (firstn i0 w0) = true ->
  wat w0 i0 = Some (o, 3%N, 1%N) ->
  (5 <= o)%N ->
  wat w1c (S i0) = Some (4%N, 2%N, NL) ->
  (1 <= NL)%N ->
  w2 = subst_at i0 2
         ((o-1,1,1)%N :: (7,2,1)%N
          :: (if (1 <? NL)%N then [(4,2,NL-1)%N] else [])) w1c ->
  base = (if (1 <? NL)%N then S (S (S i0)) else S (S i0)) ->
  tick_target w2 base = Some j ->
  (exists g2, wat w2 j = Some g2 /\ is_cmf g2 = true) ->
  wat w2 (S j) = Some (1%N, zn, cn) ->
  (1 <= zn)%N -> (1 <= cn)%N ->
  (i0 <= length w1c)%nat ->
  halts tmB (wconf [] 0 (sdecode w0 f)).
Proof.
  intros TRW HP E0 HO E1 HNL EW2 EB ETT (g2 & EG2 & ECMF) EG HZ HC HLEN.
  pose proof (tick_target_inv _ _ _ ETT) as (HBJ & _ & HMID).
  destruct ((1 <? NL)%N) eqn:ENL.
  -
    subst base.
    try rewrite ENL in EW2.
    cbn beta iota in EW2.
    assert (SH : forall n, (S (S (S i0)) <= n)%nat ->
              wat w2 n = wat w0 (n - 1)).
    { intros n HN.
      rewrite EW2.
      rewrite (wat_subst_high i0 2
                 ((o-1,1,1)%N :: (7,2,1)%N :: [(4,2,(NL-1))%N]) w1c n
                 HLEN ltac:(cbn [length]; lia)).
      cbn [length].
      rewrite TRW by lia.
      f_equal. lia. }
    apply (generic_rhalt_halts w0 f i0 o NL zn cn j); try assumption.
    + rewrite <- TRW by lia. exact E1.
    + lia.
    + intros m Hm.
      destruct (PeanoNat.Nat.eq_dec m (j - 1)) as [->|NE].
      * exists g2. split; [|apply cmf_is_col; exact ECMF].
        rewrite <- (SH j) by lia. exact EG2.
      * destruct (HMID (m + 1)%nat ltac:(lia)) as (gm & HGm & HCm).
        exists gm. split; [|exact HCm].
        replace m with ((m + 1) - 1)%nat by lia.
        rewrite <- (SH (m + 1)%nat) by lia.
        exact HGm.
    + replace j with (S j - 1)%nat by lia.
      rewrite <- (SH (S j)) by lia.
      exact EG.
  -
    subst base.
    try rewrite ENL in EW2.
    cbn beta iota in EW2.
    assert (SH : forall n, (S (S i0) <= n)%nat ->
              wat w2 n = wat w0 n).
    { intros n HN.
      rewrite EW2.
      rewrite (wat_subst_high i0 2
                 ((o-1,1,1)%N :: (7,2,1)%N :: []) w1c n
                 HLEN ltac:(cbn [length]; lia)).
      cbn [length].
      rewrite TRW by lia.
      f_equal. lia. }
    apply (generic_rhalt_halts w0 f i0 o NL zn cn (S j)); try assumption.
    + rewrite <- TRW by lia. exact E1.
    + lia.
    + intros m Hm.
      destruct (PeanoNat.Nat.eq_dec m j) as [->|NE].
      * exists g2. split; [|apply cmf_is_col; exact ECMF].
        rewrite <- (SH j) by lia. exact EG2.
      * destruct (HMID m ltac:(lia)) as (gm & HGm & HCm).
        exists gm. split; [|exact HCm].
        rewrite <- (SH m) by lia. exact HGm.
    + rewrite <- (SH (S j)) by lia. exact EG.
Qed.
Theorem StepGuard_holds :
  forall w f h i,
    step w f h = (RHalt, i) ->
    halts tmB (wconf [] 0 (sdecode w f)).
Proof.
  intros w f h i H.
  unfold step in H.
  destruct (first_rule _ w f) as [r|] eqn:EFR.
  { destruct r; inversion H. }
  destruct w as [|g0 t0].
  { cbn [step_after_front step_after_front_with
         step_after_front_with_guard find_active
         find_active_s] in H.
    unfold find_active in H.
    rewrite skipn_nil in H.
    cbn [find_active_s] in H.
    discriminate. }
  cbn [step_after_front step_after_front_with
       step_after_front_with_guard] in H.
  destruct (find_active (g0 :: t0)
              (match g0 with
               | (2,2,_) => if Nat.ltb h 1 then 1%nat else h
               | _ => h
               end)) as [i0|] eqn:EFA.
  -
    pose proof (find_active_inv _ _ _ EFA) as (HST & o & z & c & EW & HZD).
    destruct (negb (forallb is_col (firstn i0 (g0 :: t0)))) eqn:EFB;
      cbn [orb negb] in H; try rewrite EFB in H; try discriminate H.
    apply negb_false_iff in EFB.
    destruct ((gO g0 =? 2)%N && (gZ g0 =? 2)%N
              && (1 <=? gC g0)%N
              && negb (Nat.eqb i0 0)) eqn:EB;
      cbn [orb negb] in H; try rewrite EB in H; try discriminate H.
    destruct (match last1 (firstn i0 (g0 :: t0)) with
              | Some g => ((3 <=? gO g)%N && (1 <=? gC g)%N)%bool
              | None => false
              end) eqn:EBL;
      cbn [orb negb] in H; try rewrite EBL in H; try discriminate H.
    {
      match type of H with
      | context [match ?C with
                 | Some _ => _
                 | None => _
                 end] =>
          remember C as comp0 eqn:ECdef
      end.
      destruct comp0 as [[[k b2] f2]|].
      { destruct k; discriminate H. }
      clear ECdef.
      destruct (wat ((2,2,gC g0+1)%N :: t0) i0) as [g3|] eqn:EW3;
        [|inversion H].
      destruct ((gZ g3 =? 1)%N) eqn:EZ1; [inversion H|].
      match type of H with
      | context [e0_chain ?A ?B] => destruct (e0_chain A B) eqn:EE0
      end.
      { apply andb_prop in EB. destruct EB as (_ & EBI).
        apply negb_true_iff in EBI.
        apply PeanoNat.Nat.eqb_neq in EBI.
        destruct i0 as [|i0']; [congruence|].
        destruct (e0_chain_decomp _ _ EE0)
          as (ch & zn & cn & tl & HEQ & HCH & HZn & HCn).
        rewrite <- (firstn_skipn (S i0') (g0 :: t0)).
        replace (skipn (S i0') (g0 :: t0))
          with (dchain ch ((1,zn,cn)%N :: tl))
          by (rewrite <- HEQ; cbn [skipn]; reflexivity).
        apply guard_chain_halts; assumption. }
      remember (deliver_tick FUEL ((2,2,gC g0+1)%N :: t0)
                  f i0 false) as dtr eqn:EDTdef.
      destruct dtr; try (inversion H; fail).
      symmetry in EDTdef. rename EDTdef into EDT.
      apply andb_prop in EB. destruct EB as (_ & EBI).
      apply negb_true_iff in EBI.
      apply PeanoNat.Nat.eqb_neq in EBI.
      destruct i0 as [|i0']; [congruence|].
      assert (EWX : wat ((2,2,gC g0+1)%N :: t0) (S i0')
                    = Some (o, z, c)) by exact EW.
      assert (EQ3 : g3 = (o, z, c)) by congruence.
      subst g3.
      cbn [gZ] in EZ1.
      assert (HZ3 : (3 <= z)%N).
      { destruct HZD as [-> | HZ3]; [|exact HZ3].
        rewrite N.eqb_refl in EZ1. discriminate. }
      destruct (dt_rhalt_inv _ _ _ _ _ _ _ _ EWX HZ3 EDT)
        as (NL & w2 & base & j & zn & cn & EZq & ECq & HO & E1 & HNL
            & EW2 & EB2 & ETT & HG2 & EG & HZg & HCg).
      subst z c.
      apply (payload_to_halts (g0 :: t0) ((2,2,gC g0+1)%N :: t0)
               f (S i0') o NL w2 base j zn cn); try assumption.
      { intros n HN. destruct n as [|n]; [lia|reflexivity]. }
      eapply PeanoNat.Nat.lt_le_incl, wat_len. exact EWX. }
  -
    destruct (negb ((gO g0 =? 2)%N && (gZ g0 =? 2)%N
                    && (1 <=? gC g0)%N)) eqn:EI22;
      [inversion H|].
    match type of H with
    | context [cmf_from ?W ?S2 ?L] =>
        destruct (cmf_from W S2 L) as [j|] eqn:ECF
    end.
    +
      apply cmf_from_inv in ECF.
      destruct ECF as (HJ1 & gc & EGC & ECMFc).
      destruct (negb (forallb is_col (firstn j (g0 :: t0)))) eqn:EFB2;
        [inversion H|].
      apply negb_false_iff in EFB2.
      destruct (leaf_act _ _) as [[sfx2 f2]|] eqn:ELA; [inversion H|].
      remember (chain_merge_advance FUEL
                  ((2,2,gC g0+1)%N :: t0) f j) as cmr eqn:ECMdef.
      destruct cmr; try (inversion H; fail).
      symmetry in ECMdef.
      apply cma_rhalt_inv in ECMdef.
      destruct ECMdef as (zn & cn & EGn & HZn & HCn).
      assert (HJ : (1 <= j)%nat) by lia.
      apply (inert_rhalt_halts (g0 :: t0) f j gc zn cn); try assumption.
      all: try (apply cmf_is_col; exact ECMFc).
    +
      destruct (existsb _ t0) eqn:EEX; [|inversion H].
      remember (debris_to_blank ((2,2,gC g0+1)%N :: t0) f)
        as dbr eqn:EDBdef.
      destruct dbr; try (inversion H; fail).
      symmetry in EDBdef.
      exfalso. eapply dtb_no_rhalt. exact EDBdef.
Qed.
Local Open Scope N_scope.
Local Open Scope N_scope.
Local Open Scope bool_scope.
Local Open Scope sym.
Local Open Scope N_scope.
Local Open Scope bool_scope.
Local Open Scope sym.
Local Open Scope sym.
Local Open Scope list.
Local Open Scope bool_scope.
Opaque FUEL.
Opaque deliver_tick fire renewal chain_merge_advance.
Opaque fire_comp leaf_act debris_to_blank.
Opaque renew_seg.
Transparent leaf_act.
Lemma leaf_act_nil (f : N) : leaf_act [] f = None.
Proof. reflexivity. Qed.
Opaque leaf_act.
Definition cmf_prefix_ok (p s : word) : Prop :=
  match s with
  | ((X,z,c) :: _)%N =>
      (5 <= X)%N -> z = 2%N ->
      match p with
      | ((o0,z0,c_0) :: _)%N => o0 = 2%N /\ z0 = 2%N /\ (1 <= c_0)%N
      | [] => False
      end
  | [] => True
  end.
Definition sdec (s : word) (f : N) : wside :=
  expand (map gdecode s) ++ frun f.
Lemma sdec_cons (o z c : N) (t : word) (f : N) :
  sdec ((o,z,c) :: t) f
  = pair_runs (N.to_nat o) (N.to_nat z) (N.to_nat c) ++ sdec t f.
Proof.
  unfold sdec. cbn [map gdecode expand].
  rewrite <- app_assoc. reflexivity.
Qed.
Lemma sdec_app (s1 s2 : word) (f : N) :
  sdec (s1 ++ s2) f = expand (map gdecode s1) ++ sdec s2 f.
Proof.
  unfold sdec. rewrite map_app, expand_app, <- app_assoc. reflexivity.
Qed.
Lemma sdec_incr (J : N) (r : word) (f : N) :
  sdec ((2,2,(J+1))%N :: r) f = sdec ((2,2,1)%N :: (2,2,J)%N :: r) f.
Proof.
  rewrite !sdec_cons.
  change (N.to_nat 2) with 2%nat.
  change (N.to_nat 1) with 1%nat.
  rewrite N2Nat.inj_add.
  change (N.to_nat 1) with 1%nat.
  rewrite PeanoNat.Nat.add_comm.
  rewrite pair_runs_add.
  rewrite <- !app_assoc.
  reflexivity.
Qed.
Lemma Trip_uword_app (ms1 ms2 : list nat) (r : wside) :
  uword (ms1 ++ ms2) r = uword ms1 (uword ms2 r).
Proof.
  induction ms1 as [|m t IH]; cbn [app uword]; [reflexivity|].
  rewrite IH. reflexivity.
Qed.
Fixpoint walls_of (p : word) : list nat :=
  match p with
  | [] => []
  | ((o,z,c) :: t)%N =>
      repeat (N.to_nat o - 2)%nat (N.to_nat c) ++ walls_of t
  end.
Lemma uword_walls (p : word) (R : wside) :
  forallb is_col p = true ->
  expand (map gdecode p) ++ R = uword (walls_of p) R.
Proof.
  induction p as [|[[o z] c] t IH]; intros HC.
  - reflexivity.
  - cbn [forallb] in HC. apply andb_prop in HC. destruct HC as (HG & HC).
    unfold is_col in HG. cbn [gZ gO] in HG.
    apply andb_prop in HG. destruct HG as (HZ & HO).
    apply N.eqb_eq in HZ. apply N.leb_le in HO. subst z.
    cbn [map gdecode expand walls_of].
    rewrite <- app_assoc.
    rewrite (IH HC).
    rewrite Trip_uword_app.
    rewrite uword_repeat_w.
    change (N.to_nat 2) with 2%nat.
    replace (2 + (N.to_nat o - 2))%nat with (N.to_nat o) by lia.
    reflexivity.
Qed.
Lemma walls_of_cons (o z c : N) (t : word) :
  walls_of ((o,z,c)%N :: t)
  = repeat (N.to_nat o - 2)%nat (N.to_nat c) ++ walls_of t.
Proof. reflexivity. Qed.
Lemma sdec_nil (f : N) : sdec [] f = frun f.
Proof. reflexivity. Qed.
Lemma last2_split (l ini : word) (a b : bg) :
  last2 l = Some (ini, a, b) -> l = ini ++ [a; b].
Proof.
  revert ini.
  induction l as [|g t IH]; intros ini H; cbn [last2] in H.
  - discriminate.
  - destruct t as [|g2 t2].
    { discriminate. }
    destruct t2 as [|g3 t3].
    { inversion H; subst. reflexivity. }
    destruct (last2 (g2 :: g3 :: t3)) as [[[ini' a'] b']|] eqn:E2;
      [|discriminate].
    inversion H; subst.
    cbn [app]. rewrite <- (IH ini' eq_refl). reflexivity.
Qed.
Lemma uword_rep2_snoc (k : nat) (r : wside) :
  uword (repeat 2%nat k ++ [2%nat]) r = pair_runs 4 2 (S k) ++ r.
Proof.
  induction k as [|k IHk]; cbn [repeat app uword pair_runs]; [reflexivity|].
  rewrite IHk. reflexivity.
Qed.
Lemma expand_nil_gc0 (l : word) :
  expand (map gdecode l) = [] ->
  forallb (fun g => (gC g =? 0)%N) l = true.
Proof.
  induction l as [|[[o z] c] t IH]; intros H; cbn [forallb]; [reflexivity|].
  cbn [map gdecode expand] in H.
  destruct (N.to_nat c) as [|k] eqn:EC.
  - cbn [pair_runs app] in H.
    rewrite IH by exact H.
    cbn [gC].
    assert (c = 0%N) by lia.
    subst c. reflexivity.
  - cbn [pair_runs app] in H. discriminate.
Qed.
Ltac killmN H :=
  repeat (match type of H with
          | (match ?x with _ => _ end) = _ =>
              match type of x with
              | N => destruct x
              | positive => destruct x
              end
          end; try discriminate);
  try discriminate.
Ltac killm H :=
  repeat (match type of H with
          | (match ?x with _ => _ end) = _ => destruct x
          end; try discriminate);
  try discriminate.
Ltac okeq H ww' ff' :=
  match type of H with
  | (ROk ?ww ?ff, _) = _ =>
      let EW := fresh "EW" in
      let EF := fresh "EFq" in
      assert (EW : ww = ww') by
        (exact (f_equal (fun p => match fst p with
                                  | ROk x _ => x | _ => ww' end) H));
      assert (EF : ff = ff') by
        (exact (f_equal (fun p => match fst p with
                                  | ROk _ x => x | _ => ff end) H))
  end.
Ltac dtkill H :=
  killm H;
  match type of H with
  | context [deliver_tick ?a ?b ?c ?d ?e] =>
      destruct (deliver_tick a b c d e); discriminate H
  end.
Lemma wdec_app_cong (pre u v : wside) :
  wdec u = wdec v -> wdec (pre ++ u) = wdec (pre ++ v).
Proof.
  intros E. induction pre as [|[b n] t IH]; cbn [wdec app].
  - exact E.
  - rewrite IH. reflexivity.
Qed.
Lemma wconf_app_cong (pre u v : wside) :
  wconf [] 0 u = wconf [] 0 v ->
  wconf [] 0 (pre ++ u) = wconf [] 0 (pre ++ v).
Proof.
  unfold wconf. intros E.
  injection E as E1.
  rewrite (wdec_app_cong pre u v E1).
  reflexivity.
Qed.
Lemma wconf_cons_cong (a : run) (u v : wside) :
  wconf [] 0 u = wconf [] 0 v ->
  wconf [] 0 (a :: u) = wconf [] 0 (a :: v).
Proof. exact (wconf_app_cong (a :: nil) u v). Qed.
Lemma wconf_uword_cong (ms : list nat) (u v : wside) :
  wconf [] 0 u = wconf [] 0 v ->
  wconf [] 0 (uword ms u) = wconf [] 0 (uword ms v).
Proof.
  intros E.
  induction ms as [|m t IH]; cbn [uword]; [exact E|].
  apply wconf_cons_cong, wconf_cons_cong, IH.
Qed.
Lemma uword2_pair (c : nat) (r : wside) :
  uword (repeat 2%nat c) r = pair_runs 4%nat 2%nat c ++ r.
Proof. rewrite uword_repeat_w. reflexivity. Qed.
Lemma w42_expand (t : word) :
  forallb w42 t = true ->
  exists K, expand (map gdecode t) = pair_runs 4 2 K.
Proof.
  induction t as [|[[o z] c] t IH]; intros HB.
  - exists 0%nat. reflexivity.
  - cbn [forallb] in HB. apply andb_prop in HB. destruct HB as (HG & HB').
    unfold w42 in HG. cbn [gO gZ] in HG.
    apply andb_prop in HG. destruct HG as (HO & HZ).
    apply N.eqb_eq in HO, HZ. subst o z.
    destruct (IH HB') as [K EK].
    exists (N.to_nat c + K)%nat.
    cbn [map gdecode expand].
    rewrite EK.
    change (N.to_nat 4) with 4%nat. change (N.to_nat 2) with 2%nat.
    rewrite pair_runs_add. reflexivity.
Qed.
Lemma leaf_ftrip (s : word) (f : N) (s' : word) (f2 : N) :
  leaf_act s f = Some (s', f2) ->
  (exists c p q,
      FTrip c (sdec s f) p q
      /\ wconf [] 0 ((1,S p)::q) = wconf [] 0 (sdec s' f2))
  \/ (exists c p q,
      Sand c (sdec s f) ((1,S p)::q)
      /\ (1,S p)::q = sdec s' f2
      /\ sand_leaf s = true
      /\ f = 4%N).
Proof.
  revert s' f2.
  induction s as [|[[X zX] cX] rest IH]; intros s' f2 HLA.
  { Transparent leaf_act. cbn in HLA. discriminate. }
  Transparent leaf_act.
  cbn [leaf_act] in HLA.
  Opaque leaf_act.
  destruct zX as [|pz]; [destruct cX; discriminate|].
  destruct pz as [zq|zq|].
  {   destruct cX; discriminate. }
  {
    destruct zq as [q'|q'|].
    { destruct cX; discriminate. }
    { destruct cX; discriminate. }
    destruct cX as [|pc]; [discriminate|].
    destruct pc as [pc'|pc'|]; [discriminate|discriminate|].
    destruct ((5 <=? X)%N && negb (X =? 8)%N && negb (X =? 12)%N) eqn:EG;
      [|discriminate].
    destruct rest as [|[[o2 z2] c2] rest1].
    {
      apply andb_prop in EG. destruct EG as (EG5 & E12).
      apply andb_prop in EG5. destruct EG5 as (E5b & E8).
      assert (E5 : (5 <= X)%N) by (apply N.leb_le; exact E5b).
      destruct (f =? 3)%N eqn:EF3.
      { apply N.eqb_eq in EF3. subst f.
        injection HLA as <- <-.
        left.
        exists 6%nat, (3 + N.to_nat (X - 5)%N)%nat,
          ((0,1%nat)::(1,3%nat)::(0,1%nat)::[(1,4%nat)]).
        split.
        - unfold sdec.
          cbn [map gdecode expand app frun].
          change (N.to_nat 3) with 3%nat.
          change (N.to_nat 2) with 2%nat.
          change (N.to_nat 1) with 1%nat.
          rewrite (NtoS5 X E5).
          cbn [pair_runs app].
          rewrite ?app_nil_r.
          exact (FTrip_far162 (N.to_nat (X - 5)%N)).
        - unfold sdec.
          cbn [map gdecode expand app frun].
          change (N.to_nat 4) with 4%nat.
          change (N.to_nat 3) with 3%nat.
          change (N.to_nat 1) with 1%nat.
          rewrite (NtoS4 X E5).
          cbn [pair_runs app].
          rewrite ?app_nil_r.
          reflexivity. }
      destruct (f =? 2)%N eqn:EF2.
      { apply N.eqb_eq in EF2. subst f.
        injection HLA as <- <-.
        left.
        exists 9%nat, (3 + N.to_nat (X - 5)%N)%nat,
          ((0,1%nat)::(1,5%nat)::(0,2%nat)::[(1,4%nat)]).
        split.
        - unfold sdec.
          cbn [map gdecode expand app frun].
          change (N.to_nat 2) with 2%nat.
          change (N.to_nat 1) with 1%nat.
          rewrite (NtoS5 X E5).
          cbn [pair_runs app].
          rewrite ?app_nil_r.
          exact (FTrip_far165 (N.to_nat (X - 5)%N)).
        - unfold sdec.
          cbn [map gdecode expand app frun].
          change (N.to_nat 5) with 5%nat.
          change (N.to_nat 4) with 4%nat.
          change (N.to_nat 2) with 2%nat.
          change (N.to_nat 1) with 1%nat.
          rewrite (NtoS4 X E5).
          cbn [pair_runs app].
          rewrite ?app_nil_r.
          reflexivity. }
      destruct (f =? 4)%N eqn:EF4; [|discriminate].
      apply N.eqb_eq in EF4. subst f.
      injection HLA as <- <-.
      right.
      exists 8%nat, (3 + N.to_nat (X - 5)%N)%nat,
        ((0,1%nat)::(1,3%nat)::(0,2%nat)::[(1,4%nat)]).
      split; [|split; [|split]].
      - unfold sdec.
        cbn [map gdecode expand app frun].
        change (N.to_nat 4) with 4%nat.
        change (N.to_nat 2) with 2%nat.
        change (N.to_nat 1) with 1%nat.
        rewrite (NtoS5 X E5).
        cbn [pair_runs app].
        rewrite ?app_nil_r.
