  destruct ((3 <=? zb)%N && (cb =? 1)%N) eqn:EZ3F; [|discriminate].
  apply andb_prop in EZ3F. destruct EZ3F as (EZB3 & EC1b).
  apply N.leb_le in EZB3. apply N.eqb_eq in EC1b. subst cb.
  left.
  destruct (to_nat_ge2 X EA1) as [a EA].
  assert (EZB2 : (2 <= zb)%N) by lia.
  destruct (to_nat_ge2 zb EZB2) as [m EZ].
  destruct ((B =? 1)%N) eqn:EB1.
  {
