    cbn [app].
    reflexivity.
Qed.
Lemma FTrip_walls (k w' : nat) (c : nat) (Win : wside) (p : nat) (q : wside) :
  FTrip c Win p q ->
  exists c2 p2 q2,
    FTrip c2 (pair_runs (3+w')%nat 2 k ++ Win) p2 q2
    /\ (1,S p2)::q2 = pair_runs (3+w')%nat 2 k ++ (1,S p)::q.
Proof.
  revert c Win p q.
  induction k as [|k IHk]; intros c Win p q HF.
  - exists c, p, q. split; [exact HF|reflexivity].
  - destruct (IHk c Win p q HF) as (c2 & p2 & q2 & HF2 & EQ2).
    exists (c2 + 3)%nat, (2+w')%nat, ((0,2%nat)::(1,S p2)::q2).
    split.
    + cbn [pair_runs app].
      exact (FTrip_col c2 _ p2 q2 w' HF2).
    + cbn [pair_runs app].
      rewrite EQ2. reflexivity.
Qed.
Lemma FTrip_cols (cols : word) (c : nat) (Win : wside)
    (p : nat) (q : wside) :
  forallb (fun g => is_col g && negb (is_cmf g)
                    && (3 <=? gO g)%N) cols = true ->
  FTrip c Win p q ->
  exists c2 p2 q2,
    FTrip c2 (expand (map gdecode cols) ++ Win) p2 q2
    /\ (1,S p2)::q2 = expand (map gdecode cols) ++ (1,S p)::q.
Proof.
  revert c Win p q.
  induction cols as [|g cols' IH]; intros c Win p q HB HF.
  - cbn [map expand app]. exists c, p, q. split; [exact HF|reflexivity].
  - cbn [forallb] in HB. apply andb_prop in HB. destruct HB as (HG & HB').
    apply andb_prop in HG. destruct HG as (HG1 & HG3).
    apply andb_prop in HG1. destruct HG1 as (HCOL & _).
    destruct g as [[o z] cg].
    unfold is_col in HCOL. cbn [gZ gO] in *.
    apply andb_prop in HCOL. destruct HCOL as (HZ & _).
    apply N.eqb_eq in HZ. subst z.
    apply N.leb_le in HG3.
    assert (EW : exists w', N.to_nat o = (3 + w')%nat).
    { exists (N.to_nat o - 3)%nat. lia. }
    destruct EW as [w' EW].
    destruct (IH c Win p q HB' HF) as (c2 & p2 & q2 & HF2 & EQ2).
    destruct (FTrip_walls (N.to_nat cg) w' c2 _ p2 q2 HF2)
      as (c3 & p3 & q3 & HF3 & EQ3).
    exists c3, p3, q3.
    cbn [map gdecode expand].
    change (N.to_nat 2) with 2%nat.
    rewrite EW.
    rewrite <- app_assoc.
    split; [exact HF3|].
    rewrite EQ3, EQ2, <- app_assoc. reflexivity.
Qed.
Lemma d_col_ret0 (zb y : nat) (Z : wside) (p : nat) (q : wside) :
  wrun 2 ((1,1%nat)::(0,2%nat)::(1,2%nat)::(0,S zb)::(1,S y)::Z) 1
    ((1,S p)::q)
  = Some ((1,1%nat)::(0,S zb)::(1,S y)::Z, 1,
          (1,2%nat)::(0,2%nat)::(1,S p)::q).
Proof. reflexivity. Qed.
Lemma FTrip_col2 (c : nat) (Win : wside) (p : nat) (q : wside) :
  FTrip c Win p q ->
  FTrip (c + 3) ((1,2%nat)::(0,2%nat)::Win) 1 ((0,2%nat)::(1,S p)::q).
Proof.
  intros HT zb y Z.
  replace (c + 3)%nat with (1 + (c + 2))%nat by lia.
  change ((1,2%nat)::(0,2%nat)::Win)
    with ((1,(2 + 0)%nat)::(0,2%nat)::Win).
  rewrite wrun_add.
  cbn [wrun].
  rewrite wsection_cross.
  lazy beta iota.
  unfold vpush.
  cbn [wpush sym_eqb].
  rewrite wrun_add.
  rewrite (HT 1%nat 1%nat).
  lazy beta iota.
  rewrite d_col_ret0.
  reflexivity.
Qed.
Lemma FTrip_colg (c : nat) (Win : wside) (p : nat) (q : wside) (m : nat) :
  FTrip c Win p q ->
  FTrip (c + 3)
    ((1,(2 + m)%nat)::(0,2%nat)::Win)
    (S m) ((0,2%nat)::(1,S p)::q).
Proof.
  destruct m as [|m'].
  - exact (FTrip_col2 c Win p q).
  - exact (FTrip_col c Win p q m').
Qed.
Lemma FTrip_walls2 (k m : nat) (c : nat) (Win : wside) (p : nat) (q : wside) :
  FTrip c Win p q ->
  exists c2 p2 q2,
    FTrip c2 (pair_runs (2+m)%nat 2 k ++ Win) p2 q2
    /\ (1,S p2)::q2 = pair_runs (2+m)%nat 2 k ++ (1,S p)::q.
Proof.
  revert c Win p q.
  induction k as [|k IHk]; intros c Win p q HF.
  - exists c, p, q. split; [exact HF|reflexivity].
  - destruct (IHk c Win p q HF) as (c2 & p2 & q2 & HF2 & EQ2).
    exists (c2 + 3)%nat, (S m), ((0,2%nat)::(1,S p2)::q2).
    split.
    + cbn [pair_runs app].
      exact (FTrip_colg c2 _ p2 q2 m HF2).
    + cbn [pair_runs app].
      rewrite EQ2. reflexivity.
Qed.
Lemma FTrip_cols2 (cols : word) (c : nat) (Win : wside)
    (p : nat) (q : wside) :
  forallb is_col cols = true ->
  FTrip c Win p q ->
  exists c2 p2 q2,
    FTrip c2 (expand (map gdecode cols) ++ Win) p2 q2
    /\ (1,S p2)::q2 = expand (map gdecode cols) ++ (1,S p)::q.
Proof.
  revert c Win p q.
  induction cols as [|g cols' IH]; intros c Win p q HB HF.
  - cbn [map expand app]. exists c, p, q. split; [exact HF|reflexivity].
  - cbn [forallb] in HB. apply andb_prop in HB. destruct HB as (HCOL & HB').
    destruct g as [[o z] cg].
    unfold is_col in HCOL. cbn [gZ gO] in *.
    apply andb_prop in HCOL. destruct HCOL as (HZ & HO).
    apply N.eqb_eq in HZ. subst z.
    apply N.leb_le in HO.
    assert (EW : exists m, N.to_nat o = (2 + m)%nat).
    { exists (N.to_nat o - 2)%nat. lia. }
    destruct EW as [m EW].
    destruct (IH c Win p q HB' HF) as (c2 & p2 & q2 & HF2 & EQ2).
    destruct (FTrip_walls2 (N.to_nat cg) m c2 _ p2 q2 HF2)
      as (c3 & p3 & q3 & HF3 & EQ3).
    exists c3, p3, q3.
    cbn [map gdecode expand].
    change (N.to_nat 2) with 2%nat.
    rewrite EW.
    rewrite <- app_assoc.
    split; [exact HF3|].
    rewrite EQ3, EQ2, <- app_assoc. reflexivity.
Qed.
Lemma Sand_walls (k w' : nat) (c : nat) (Win : wside) (W' : wside) :
  Sand c Win W' ->
  exists c2 p2 q2,
    FTrip c2 (pair_runs (3+w')%nat 2 (S k) ++ Win) p2 q2
    /\ (1,S p2)::q2 = pair_runs (3+w')%nat 2 (S k) ++ W'.
Proof.
  intros HS.
  induction k as [|k IHk].
  - exists (c + 2)%nat, (2+w')%nat, ((0,2%nat)::W').
    split.
    + cbn [pair_runs app].
      exact (Sand_col c _ W' w' HS).
    + cbn [pair_runs app]. reflexivity.
  - destruct IHk as (c2 & p2 & q2 & HF2 & EQ2).
    exists (c2 + 3)%nat, (2+w')%nat, ((0,2%nat)::(1,S p2)::q2).
    split.
    + change (pair_runs (3+w')%nat 2 (S (S k)) ++ Win)
        with ((1,(3+w')%nat)::(0,2%nat)::(pair_runs (3+w')%nat 2 (S k) ++ Win)).
      exact (FTrip_col c2 _ p2 q2 w' HF2).
    + change (pair_runs (3+w')%nat 2 (S (S k)) ++ W')
        with ((1,(3+w')%nat)::(0,2%nat)::(pair_runs (3+w')%nat 2 (S k) ++ W')).
      rewrite EQ2. reflexivity.
Qed.
Lemma Sand_cols (cols : word) (c : nat) (Win : wside) (W' : wside) :
  forallb (fun g => is_col g && negb (is_cmf g)
                    && (3 <=? gO g)%N) cols = true ->
  Sand c Win W' ->
  (exists c2 p2 q2,
      FTrip c2 (expand (map gdecode cols) ++ Win) p2 q2
      /\ (1,S p2)::q2 = expand (map gdecode cols) ++ W')
  \/ expand (map gdecode cols) = [].
Proof.
  induction cols as [|g cols' IH]; intros HB HS.
  - right. reflexivity.
  - cbn [forallb] in HB. apply andb_prop in HB. destruct HB as (HG & HB').
    apply andb_prop in HG. destruct HG as (HG1 & HG3).
    apply andb_prop in HG1. destruct HG1 as (HCOL & _).
    destruct g as [[o z] cg].
    unfold is_col in HCOL. cbn [gZ gO] in *.
    apply andb_prop in HCOL. destruct HCOL as (HZ & _).
    apply N.eqb_eq in HZ. subst z.
    apply N.leb_le in HG3.
    assert (EW : exists w', N.to_nat o = (3 + w')%nat).
    { exists (N.to_nat o - 3)%nat. lia. }
    destruct EW as [w' EW].
    destruct (IH HB' HS) as [(c2 & p2 & q2 & HF2 & EQ2)|ENIL].
    +
      destruct (FTrip_walls (N.to_nat cg) w' c2 _ p2 q2 HF2)
        as (c3 & p3 & q3 & HF3 & EQ3).
      left. exists c3, p3, q3.
      cbn [map gdecode expand].
      change (N.to_nat 2) with 2%nat.
      rewrite EW.
      rewrite <- app_assoc.
      split; [exact HF3|].
      rewrite EQ3, EQ2, <- app_assoc. reflexivity.
    +
      cbn [map gdecode expand].
      change (N.to_nat 2) with 2%nat.
      rewrite EW, ENIL.
      rewrite app_nil_r.
      destruct (N.to_nat cg) as [|k] eqn:ECG.
      * right. reflexivity.
      * left.
        destruct (Sand_walls k w' c Win W' HS)
          as (c3 & p3 & q3 & HF3 & EQ3).
        exists c3, p3, q3.
        split; [exact HF3|exact EQ3].
Qed.
Definition Sand0 (c : nat) (W W' : wside) : Prop :=
  forall n b0 L0,
    wrun c ((0,S n)::(1,S b0)::L0) 0 W
    = Some ((0,S n)::(1,S b0)::L0, 1, (0,1%nat) :: W').
Lemma Sand0_Sand (c : nat) (W W' : wside) : Sand0 c W W' -> Sand c W W'.
Proof. intros H b0 L0. exact (H 0%nat b0 L0). Qed.
Lemma Sand0_far169 (X' : nat) :
  Sand0 8 ((1,(5 + X')%nat)::(0,2%nat)::[(1,4%nat)])
          ((1,(4 + X')%nat)::(0,1%nat)::(1,3%nat)::(0,2%nat)::[(1,4%nat)]).
Proof. intros n b0 L0. destruct n; destruct X' as [|d]; gker. Qed.
Lemma Sand0_col2 (c : nat) (Win : wside) (W' : wside) :
  Sand0 c Win W' ->
  FTrip (c + 2) ((1,2%nat)::(0,2%nat)::Win) 1 ((0,2%nat)::W').
Proof.
  intros HS zb y Z.
  replace (c + 2)%nat with (1 + (c + 1))%nat by lia.
  change ((1,2%nat)::(0,2%nat)::Win)
    with ((1,(2 + 0)%nat)::(0,2%nat)::Win).
  rewrite wrun_add.
  cbn [wrun].
  rewrite wsection_cross.
  lazy beta iota.
  unfold vpush.
  cbn [wpush sym_eqb].
  change ((1 + 1)%nat) with (S 1).
  rewrite wrun_add.
  unfold Sand0 in HS.
  rewrite HS.
  lazy beta iota.
  reflexivity.
Qed.
Lemma Sand0_colg (c : nat) (Win : wside) (W' : wside) (m : nat) :
  Sand0 c Win W' ->
  FTrip (c + 2) ((1,(2 + m)%nat)::(0,2%nat)::Win) (S m) ((0,2%nat)::W').
Proof.
  intros HS. destruct m as [|m'].
  - exact (Sand0_col2 c Win W' HS).
  - exact (Sand_col c Win W' m' (Sand0_Sand c Win W' HS)).
Qed.
Lemma Sand0_walls2 (k m : nat) (c : nat) (Win : wside) (W' : wside) :
  Sand0 c Win W' ->
  exists c2 p2 q2,
    FTrip c2 (pair_runs (2+m)%nat 2 (S k) ++ Win) p2 q2
    /\ (1,S p2)::q2 = pair_runs (2+m)%nat 2 (S k) ++ W'.
Proof.
  intros HS.
  induction k as [|k IHk].
  - exists (c + 2)%nat, (S m), ((0,2%nat)::W').
    split.
    + cbn [pair_runs app].
      exact (Sand0_colg c Win W' m HS).
    + cbn [pair_runs app]. reflexivity.
  - destruct IHk as (c2 & p2 & q2 & HF2 & EQ2).
    exists (c2 + 3)%nat, (S m), ((0,2%nat)::(1,S p2)::q2).
    split.
    + change (pair_runs (2+m)%nat 2 (S (S k)) ++ Win)
        with ((1,(2+m)%nat)::(0,2%nat)
                ::(pair_runs (2+m)%nat 2 (S k) ++ Win)).
      exact (FTrip_colg c2 _ p2 q2 m HF2).
    + change (pair_runs (2+m)%nat 2 (S (S k)) ++ W')
        with ((1,(2+m)%nat)::(0,2%nat)::(pair_runs (2+m)%nat 2 (S k) ++ W')).
      rewrite EQ2. reflexivity.
Qed.
Lemma Sand0_cols2 (cols : word) (c : nat) (Win : wside) (W' : wside) :
  forallb is_col cols = true ->
  Sand0 c Win W' ->
  (exists c2 p2 q2,
      FTrip c2 (expand (map gdecode cols) ++ Win) p2 q2
      /\ (1,S p2)::q2 = expand (map gdecode cols) ++ W')
  \/ expand (map gdecode cols) = [].
Proof.
  induction cols as [|g cols' IH]; intros HB HS.
  - right. reflexivity.
  - cbn [forallb] in HB. apply andb_prop in HB. destruct HB as (HCOL & HB').
    destruct g as [[o z] cg].
    unfold is_col in HCOL. cbn [gZ gO] in *.
    apply andb_prop in HCOL. destruct HCOL as (HZ & HO).
    apply N.eqb_eq in HZ. subst z.
    apply N.leb_le in HO.
    assert (EW : exists m, N.to_nat o = (2 + m)%nat).
    { exists (N.to_nat o - 2)%nat. lia. }
    destruct EW as [m EW].
    destruct (IH HB' HS) as [(c2 & p2 & q2 & HF2 & EQ2)|ENIL].
    + destruct (FTrip_walls2 (N.to_nat cg) m c2 _ p2 q2 HF2)
        as (c3 & p3 & q3 & HF3 & EQ3).
      left. exists c3, p3, q3.
      cbn [map gdecode expand].
      change (N.to_nat 2) with 2%nat.
      rewrite EW.
      rewrite <- app_assoc.
      split; [exact HF3|].
      rewrite EQ3, EQ2, <- app_assoc. reflexivity.
    + cbn [map gdecode expand].
      change (N.to_nat 2) with 2%nat.
      rewrite EW, ENIL.
      rewrite app_nil_r.
      destruct (N.to_nat cg) as [|k] eqn:ECG.
      * right. reflexivity.
      * left.
        destruct (Sand0_walls2 k m c Win W' HS)
          as (c3 & p3 & q3 & HF3 & EQ3).
        exists c3, p3, q3.
        split; [exact HF3|exact EQ3].
Qed.
Lemma sand_leaf_shape (s : word) :
  sand_leaf s = true ->
  exists X, s = [(X,2,1)%N] /\ (5 <= X)%N.
Proof.
  intros ESL.
  destruct s as [|[[X z] c_0] t].
  { cbv [sand_leaf] in ESL. discriminate. }
  cbv [sand_leaf] in ESL.
  destruct t as [|g t'].
  2:{ killmN ESL. }
  killmN ESL.
  exists X. split; [reflexivity|].
  apply andb_prop in ESL. destruct ESL as (ESL & _).
  apply andb_prop in ESL. destruct ESL as (ESL & _).
  apply N.leb_le. exact ESL.
Qed.
Lemma leaf_ftrip0 (s : word) (f : N) (s' : word) (f2 : N) :
  leaf_act s f = Some (s', f2) ->
  (exists c p q, FTrip c (sdec s f) p q
                 /\ wconf [] 0 ((1,S p)::q) = wconf [] 0 (sdec s' f2))
  \/ (exists c p q, Sand0 c (sdec s f) ((1,S p)::q)
                    /\ (1,S p)::q = sdec s' f2).
Proof.
  intros HLA.
  destruct (leaf_ftrip s f s' f2 HLA)
    as [(c & p & q & HF & EQ)|(c & p & q & _ & _ & ESL & EF4)].
  { left. exists c, p, q. split; assumption. }
  subst f.
  destruct (sand_leaf_shape s ESL) as (X & ES & E5).
  subst s.
  assert (EG : ((5 <=? X)%N && negb (X =? 8)%N && negb (X =? 12)%N) = true)
    by (cbv [sand_leaf] in ESL; exact ESL).
  Transparent leaf_act. cbn [leaf_act] in HLA.
  Opaque leaf_act.
  rewrite EG in HLA.
  change ((4 =? 3)%N) with false in HLA.
  change ((4 =? 2)%N) with false in HLA.
  change ((4 =? 4)%N) with true in HLA.
  cbv beta iota in HLA.
  injection HLA as <- <-.
  right.
  exists 8%nat, (3 + N.to_nat (X - 5)%N)%nat,
    ((0,1%nat)::(1,3%nat)::(0,2%nat)::[(1,4%nat)]).
  split.
  - unfold sdec.
    cbn [map gdecode expand app frun].
    change (N.to_nat 4) with 4%nat.
    change (N.to_nat 2) with 2%nat.
    change (N.to_nat 1) with 1%nat.
    rewrite (NtoS5 X E5).
    cbn [pair_runs app].
    rewrite ?app_nil_r.
    exact (Sand0_far169 (N.to_nat (X - 5)%N)).
  - unfold sdec.
    cbn [map gdecode expand app frun].
    change (N.to_nat 4) with 4%nat.
    change (N.to_nat 3) with 3%nat.
    change (N.to_nat 2) with 2%nat.
    change (N.to_nat 1) with 1%nat.
    rewrite (NtoS4 X E5).
    cbn [pair_runs app].
    rewrite ?app_nil_r.
    reflexivity.
Qed.
Lemma pair_runs_2 (o z c : nat) :
  pair_runs o z (2 + c) = (1,o)::(0,z)::(1,o)::(0,z)::pair_runs o z c.
Proof. reflexivity. Qed.
Lemma sdec_optk (o z c k : N) (r : word) (f : N) :
  sdec ((if (k <? c)%N then [(o,z,c-k)%N] else []) ++ r) f
  = pair_runs (N.to_nat o) (N.to_nat z) (N.to_nat (c - k)%N) ++ sdec r f.
Proof.
  destruct (k <? c)%N eqn:E.
  - cbn [app]. rewrite sdec_cons. reflexivity.
  - apply N.ltb_ge in E.
    replace (c - k)%N with 0%N by lia.
    cbn [app N.to_nat pair_runs]. reflexivity.
Qed.
Ltac flatapp :=
  repeat (progress (cbn [app]; rewrite <- app_assoc)); cbn [app].
Ltac flatappH H :=
  repeat (progress (cbn [app] in H; rewrite <- app_assoc in H));
  cbn [app] in H.
Lemma app_cons_snoc (l : word) (a : bg) (r : word) :
  l ++ a :: r = (l ++ [a]) ++ r.
Proof. rewrite <- app_assoc. reflexivity. Qed.
Lemma ren_lift (ini sfx tail : word) (f f2 : N)
    (c p : nat) (q : wside) :
  forallb (fun g => is_col g && negb (is_cmf g)
                    && (3 <=? gO g)%N) ini = true ->
  FTrip c (sdec sfx f) p q ->
  wconf [] 0 ((1,S p)::q) = wconf [] 0 (sdec tail f2) ->
  exists c2 p2 q2,
    FTrip c2 (sdec (ini ++ sfx) f) p2 q2
    /\ wconf [] 0 ((1,S p2)::q2) = wconf [] 0 (sdec (ini ++ tail) f2).
Proof.
  intros HB HF EQ.
  destruct (FTrip_cols ini c (sdec sfx f) p q HB HF)
    as (c2 & p2 & q2 & HF2 & EQ2).
  exists c2, p2, q2. split; [rewrite sdec_app; exact HF2|].
  rewrite EQ2, sdec_app.
  apply wconf_app_cong. exact EQ.
Qed.
Lemma ren_lift2 (ini sfx tail : word) (f f2 : N)
    (c p : nat) (q : wside) :
  forallb is_col ini = true ->
  FTrip c (sdec sfx f) p q ->
  wconf [] 0 ((1,S p)::q) = wconf [] 0 (sdec tail f2) ->
  exists c2 p2 q2,
    FTrip c2 (sdec (ini ++ sfx) f) p2 q2
    /\ wconf [] 0 ((1,S p2)::q2) = wconf [] 0 (sdec (ini ++ tail) f2).
Proof.
  intros HB HF EQ.
  destruct (FTrip_cols2 ini c (sdec sfx f) p q HB HF)
    as (c2 & p2 & q2 & HF2 & EQ2).
  exists c2, p2, q2. split; [rewrite sdec_app; exact HF2|].
  rewrite EQ2, sdec_app.
  apply wconf_app_cong. exact EQ.
Qed.
Lemma ren_lift1 (ini : word) (a : bg) (sfx tail : word)
    (f f2 : N) (c p : nat) (q : wside) :
  forallb (fun g => is_col g && negb (is_cmf g)
                    && (3 <=? gO g)%N) (ini ++ [a]) = true ->
  FTrip c (sdec sfx f) p q ->
  wconf [] 0 ((1,S p)::q) = wconf [] 0 (sdec tail f2) ->
  exists c2 p2 q2,
    FTrip c2 (sdec (ini ++ a :: sfx) f) p2 q2
    /\ wconf [] 0 ((1,S p2)::q2) = wconf [] 0 (sdec (ini ++ a :: tail) f2).
Proof.
  intros HB HF EQ.
  rewrite (app_cons_snoc ini a sfx), (app_cons_snoc ini a tail).
  exact (ren_lift (ini ++ [a]) sfx tail f f2 c p q HB HF EQ).
Qed.
Lemma ren_jump (ini : word) (gbc B : N) (h1 nb : nat)
    (sfx tail : word) (f f2 : N) (c p : nat) (q : wside) :
  forallb (fun g => is_col g && negb (is_cmf g)
                    && (3 <=? gO g)%N) ini = true ->
  N.to_nat gbc = S h1 -> N.to_nat B = S nb ->
  FTrip c (sdec sfx f) p q ->
  wconf [] 0 ((1,S p)::q) = wconf [] 0 (sdec tail f2) ->
  exists c2 p2 q2,
    FTrip c2
      (sdec ((ini ++ [(8,2,1)%N; (4,2,gbc)%N])
               ++ (4,3,1)%N :: (4,2,B)%N :: sfx) f) p2 q2
    /\ wconf [] 0 ((1,S p2)::q2)
       = wconf [] 0
           (sdec ((ini ++ [(7,1,1)%N; (3,2,1)%N; (4,2,gbc)%N; (8,2,1)%N]
                     ++ (if (1 <? B)%N then [(4,2,(B-1))%N] else []))
                    ++ tail) f2).
Proof.
  intros HPI EH EB HF EQ.
  pose proof (FTrip_jump c (sdec sfx f) p q h1 nb HF) as HT.
  cbn [uword app] in HT.
  rewrite !uword_rep2_snoc, !uword_repeat_w in HT.
  flatapp.
  refine (ren_lift ini _ _ _ _ _ _ _ HPI _ _).
  - rewrite !sdec_cons.
    rewrite EH, EB.
    change (N.to_nat 8) with 8%nat.
    change (N.to_nat 4) with 4%nat.
    change (N.to_nat 3) with 3%nat.
    change (N.to_nat 2) with 2%nat.
    change (N.to_nat 1) with 1%nat.
    cbn [pair_runs app].
    flatapp.
    exact HT.
  - rewrite !sdec_cons, sdec_app.
    rewrite EH.
    change (N.to_nat 8) with 8%nat.
    change (N.to_nat 7) with 7%nat.
    change (N.to_nat 4) with 4%nat.
    change (N.to_nat 3) with 3%nat.
    change (N.to_nat 2) with 2%nat.
    change (N.to_nat 1) with 1%nat.
    destruct ((1 <? B)%N) eqn:ELT.
    { apply N.ltb_lt in ELT.
      assert (EBm : N.to_nat (B - 1)%N = nb)
        by (rewrite N2Nat.inj_sub, EB;
            change (N.to_nat 1) with 1%nat; lia).
      cbn [map gdecode expand].
      rewrite EBm.
      cbn [pair_runs app].
      flatapp.
      rewrite ?app_nil_r.
      repeat (first [exact EQ | apply wconf_app_cong
                    | apply wconf_cons_cong]). }
    apply N.ltb_ge in ELT.
    assert (EB1x : B = 1%N) by lia. subst B.
    assert (ENB0 : nb = 0%nat) by (cbn in EB; lia). subst nb.
    cbn [map gdecode expand].
    cbn [pair_runs app].
    flatapp.
    rewrite ?app_nil_r.
    repeat (first [exact EQ | apply wconf_app_cong
                  | apply wconf_cons_cong]).
Qed.
Lemma ren_jump0 (ini : word) (B : N) (nb : nat)
    (sfx tail : word) (f f2 : N) (c p : nat) (q : wside) :
