            change (N.to_nat 1) with 1%nat; lia).
      cbn [map gdecode expand].
      rewrite EBm.
      cbn [pair_runs app].
      flatapp.
      rewrite ?app_nil_r.
      repeat (first [exact EQ | apply wconf_app_cong
                    | apply wconf_cons_cong]). }
    apply N.ltb_ge in ELT.
    assert (EB1x : B = 1%N) by lia. subst B.
    assert (ENB0 : nb = 0%nat) by (cbn in EB; lia). subst nb.
    cbn [map gdecode expand].
    cbn [pair_runs app].
    flatapp.
    rewrite ?app_nil_r.
    repeat (first [exact EQ | apply wconf_app_cong
                  | apply wconf_cons_cong]).
Qed.
Lemma ren_lcjmp (ini : word) (gbc cn : N) (h1 nb : nat)
    (tail : word) (f : N) :
  forallb (fun g => is_col g && negb (is_cmf g)
                    && (3 <=? gO g)%N) ini = true ->
  N.to_nat gbc = S h1 -> N.to_nat cn = S nb ->
  exists c2 p2 q2,
    FTrip c2
      (sdec ((ini ++ [(8,2,1)%N; (4,2,gbc)%N])
               ++ (4,4,1)%N :: (4,2,cn)%N :: tail) f) p2 q2
    /\ wconf [] 0 ((1,S p2)::q2)
       = wconf [] 0
           (sdec ((ini ++ [(7,1,1)%N; (3,2,1)%N; (4,2,gbc)%N; (8,2,1)%N]
                     ++ (if (1 <? cn)%N then [(4,2,(cn-1))%N] else []))
                    ++ tail) f).
Proof.
  intros HPI EH EB.
  pose proof (FTrip_lcJMP h1 nb (sdec tail f)) as HT.
  cbn [uword app] in HT.
  rewrite !uword_rep2_snoc in HT.
  flatapp.
  refine (ren_lift ini _ _ _ _ _ _ _ HPI _ _).
  - rewrite !sdec_cons.
    rewrite EH, EB.
    change (N.to_nat 8) with 8%nat.
    change (N.to_nat 4) with 4%nat.
    change (N.to_nat 2) with 2%nat.
    change (N.to_nat 1) with 1%nat.
    cbn [pair_runs app].
    flatapp. flatappH HT.
    exact HT.
  - rewrite !sdec_cons, sdec_app.
    rewrite EH.
    change (N.to_nat 8) with 8%nat.
    change (N.to_nat 7) with 7%nat.
    change (N.to_nat 4) with 4%nat.
    change (N.to_nat 3) with 3%nat.
    change (N.to_nat 2) with 2%nat.
    change (N.to_nat 1) with 1%nat.
    destruct ((1 <? cn)%N) eqn:ELT.
    { apply N.ltb_lt in ELT.
      assert (EBm : N.to_nat (cn - 1)%N = nb)
        by (rewrite N2Nat.inj_sub, EB;
            change (N.to_nat 1) with 1%nat; lia).
      cbn [map gdecode expand].
      rewrite EBm.
      cbn [pair_runs app].
      flatapp.
      rewrite ?app_nil_r.
      reflexivity. }
    apply N.ltb_ge in ELT.
    assert (EB1x : cn = 1%N) by lia. subst cn.
    assert (ENB0 : nb = 0%nat) by (cbn in EB; lia). subst nb.
    cbn [map gdecode expand].
    cbn [pair_runs app].
    flatapp.
    rewrite ?app_nil_r.
    reflexivity.
Qed.
Lemma ren_lcjmp0 (ini : word) (cn : N) (nb : nat)
    (tail : word) (f : N) :
  forallb (fun g => is_col g && negb (is_cmf g)
                    && (3 <=? gO g)%N) ini = true ->
  N.to_nat cn = S nb ->
  exists c2 p2 q2,
    FTrip c2
      (sdec ((ini ++ [(8,2,1)%N])
               ++ (4,4,1)%N :: (4,2,cn)%N :: tail) f) p2 q2
    /\ wconf [] 0 ((1,S p2)::q2)
       = wconf [] 0
           (sdec ((ini ++ [(7,1,1)%N; (3,2,1)%N; (8,2,1)%N]
                     ++ (if (1 <? cn)%N then [(4,2,(cn-1))%N] else []))
                    ++ tail) f).
Proof.
  intros HPI EB.
  pose proof (FTrip_lcJMP0 nb (sdec tail f)) as HT.
  flatapp.
  refine (ren_lift ini _ _ _ _ _ _ _ HPI _ _).
  - rewrite !sdec_cons.
    rewrite EB.
    change (N.to_nat 8) with 8%nat.
    change (N.to_nat 4) with 4%nat.
    change (N.to_nat 2) with 2%nat.
    change (N.to_nat 1) with 1%nat.
    cbn [pair_runs app].
    flatapp. flatappH HT.
    exact HT.
  - rewrite !sdec_cons, sdec_app.
    change (N.to_nat 8) with 8%nat.
    change (N.to_nat 7) with 7%nat.
    change (N.to_nat 4) with 4%nat.
    change (N.to_nat 3) with 3%nat.
    change (N.to_nat 2) with 2%nat.
    change (N.to_nat 1) with 1%nat.
    destruct ((1 <? cn)%N) eqn:ELT.
    { apply N.ltb_lt in ELT.
      assert (EBm : N.to_nat (cn - 1)%N = nb)
        by (rewrite N2Nat.inj_sub, EB;
            change (N.to_nat 1) with 1%nat; lia).
      cbn [map gdecode expand].
      rewrite EBm.
      cbn [pair_runs app].
      flatapp.
      rewrite ?app_nil_r.
      reflexivity. }
    apply N.ltb_ge in ELT.
    assert (EB1x : cn = 1%N) by lia. subst cn.
    assert (ENB0 : nb = 0%nat) by (cbn in EB; lia). subst nb.
    cbn [map gdecode expand].
    cbn [pair_runs app].
    flatapp.
    rewrite ?app_nil_r.
    reflexivity.
Qed.
Definition jblk (blk : word) : Prop :=
  blk = [] \/ exists gbc, blk = [(4,2,gbc)%N] /\ (1 <= gbc)%N.
Lemma jump_seg_split (cols seg : word) (B : N) :
  jump_seg cols B = Some seg ->
  exists P blk,
       cols = P ++ (8,2,1)%N :: blk
    /\ seg = P ++ (7,1,1)%N :: (3,2,1)%N :: blk ++ (8,2,1)%N
               :: (if (1 <? B)%N then [(4,2,(B-1))%N] else [])
    /\ jblk blk
    /\ lawR_seg cols B
       = Some (P ++ (7,1,1)%N :: (3,2,1)%N :: blk ++ (7,1,1)%N :: (3,2,1)%N
                 :: (if (1 <? B)%N then [(4,2,(B-1))%N] else [])).
Proof.
  intros EJS.
  unfold jump_seg in EJS.
  destruct (last2 cols)
    as [[[ini [[gao gaz] gac]] [[gbo gbz] gbc]]|] eqn:EL2; [|discriminate].
  pose proof (last2_split _ _ _ _ EL2) as ECOLS.
  destruct ((gao =? 8)%N && (gaz =? 2)%N && (gac =? 1)%N
            && (gbo =? 4)%N && (gbz =? 2)%N && (1 <=? gbc)%N) eqn:EG1.
  { injection EJS as <-.
    apply andb_prop in EG1. destruct EG1 as (EG1 & EGB1).
    apply andb_prop in EG1. destruct EG1 as (EG1 & EBZ).
    apply andb_prop in EG1. destruct EG1 as (EG1 & EBO).
    apply andb_prop in EG1. destruct EG1 as (EAOZ & EAC).
    apply andb_prop in EAOZ. destruct EAOZ as (EAO & EAZ).
    apply N.eqb_eq in EAO, EAZ, EAC, EBO, EBZ.
    apply N.leb_le in EGB1.
    subst gao gaz gac gbo gbz.
    exists ini, [(4,2,gbc)%N].
    split; [rewrite ECOLS; reflexivity|].
    split; [cbn [app]; reflexivity|].
    split; [right; exists gbc; split; [reflexivity|exact EGB1]|].
    unfold lawR_seg. rewrite EL2.
    assert (EGBb : (1 <=? gbc)%N = true) by (apply N.leb_le; exact EGB1).
    rewrite EGBb. cbn [N.eqb Pos.eqb andb app]. reflexivity. }
  destruct ((gbo =? 8)%N && (gbz =? 2)%N && (gbc =? 1)%N) eqn:EG2;
    [|discriminate EJS].
  injection EJS as <-.
  apply andb_prop in EG2. destruct EG2 as (EG2 & EBC).
  apply andb_prop in EG2. destruct EG2 as (EBO & EBZ).
  apply N.eqb_eq in EBO, EBZ, EBC. subst gbo gbz gbc.
  exists (ini ++ [(gao,gaz,gac)%N]), (nil : word).
  split; [rewrite ECOLS, <- app_assoc; reflexivity|].
  split; [rewrite <- app_assoc; cbn [app]; reflexivity|].
  split; [left; reflexivity|].
  unfold lawR_seg. rewrite EL2.
  cbn [N.eqb Pos.eqb andb] in EG1 |- *.
  rewrite EG1.
  rewrite <- app_assoc. cbn [app]. reflexivity.
Qed.
Lemma jsplit_cols (P blk : word) :
  forallb (fun g => is_col g && negb (is_cmf g)
                    && (3 <=? gO g)%N) (P ++ (8,2,1)%N :: blk) = true ->
  forallb (fun g => is_col g && negb (is_cmf g)
                    && (3 <=? gO g)%N) P = true.
Proof.
  intros H. rewrite forallb_app in H.
