Lemma ren_jumpU (P blk sfx tail : word) (B f f2 : N)
    (c p : nat) (q : wside) :
  forallb (fun g => is_col g && negb (is_cmf g)
                    && (3 <=? gO g)%N) P = true ->
  jblk blk ->
  (1 <= B)%N ->
  FTrip c (sdec sfx f) p q ->
  wconf [] 0 ((1,S p)::q) = wconf [] 0 (sdec tail f2) ->
  exists c2 p2 q2,
    FTrip c2 (sdec ((P ++ (8,2,1)%N :: blk)
                      ++ (4,3,1)%N :: (4,2,B)%N :: sfx) f) p2 q2
    /\ wconf [] 0 ((1,S p2)::q2)
       = wconf [] 0
           (sdec ((P ++ (7,1,1)%N :: (3,2,1)%N :: blk ++ (8,2,1)%N
                     :: (if (1 <? B)%N then [(4,2,(B-1))%N] else []))
                    ++ tail) f2).
Proof.
  intros HP HBLK EB1 HF EQ.
  destruct (to_nat_ge1 B EB1) as [nb EB].
  destruct HBLK as [-> | (gbc & -> & EGB1)].
  - cbn [app].
    exact (ren_jump0 P B nb sfx tail f f2 c p q HP EB HF EQ).
  - destruct (to_nat_ge1 gbc EGB1) as [h1 EH].
    cbn [app].
    exact (ren_jump P gbc B h1 nb sfx tail f f2 c p q HP EH EB HF EQ).
Qed.
Lemma ren_lcjmpU (P blk tail : word) (cn f : N) :
