Lemma ren_jumpbare (ini : word) (gbc B : N) (h1 nb : nat) (f : N) :
  forallb (fun g => is_col g && negb (is_cmf g)
                    && (3 <=? gO g)%N) ini = true ->
  N.to_nat gbc = S h1 -> N.to_nat B = S nb -> (5 <= f)%N ->
  exists c2 p2 q2,
    FTrip c2 (sdec ((ini ++ [(8,2,1)%N; (4,2,gbc)%N])
                      ++ (4,3,1)%N :: (4,2,B)%N :: []) f) p2 q2
    /\ wconf [] 0 ((1,S p2)::q2)
       = wconf [] 0
           (sdec ((ini ++ [(7,1,1)%N; (3,2,1)%N; (4,2,gbc)%N; (8,2,1)%N]
                     ++ (if (1 <? B)%N then [(4,2,(B-1))%N] else []))
                    ++ [((f-1)%N,1,1)%N]) 3).
Proof.
  intros HPI EH EB EF5g.
  pose (wj := N.to_nat (f - 5)%N).
  assert (EF5 : N.to_nat f = (5 + wj)%nat)
    by (unfold wj; rewrite N2Nat.inj_sub;
        change (N.to_nat 5) with 5%nat; lia).
  assert (EFm : N.to_nat (f - 1)%N = (4 + wj)%nat)
    by (unfold wj; rewrite !N2Nat.inj_sub;
        change (N.to_nat 5) with 5%nat;
        change (N.to_nat 1) with 1%nat; lia).
  pose proof (FTrip_jumpbare h1 nb wj) as HT.
  cbn [uword app] in HT.
  rewrite !uword_rep2_snoc, !uword_repeat_w in HT.
  flatapp.
  refine (ren_lift ini _ _ _ _ _ _ _ HPI _ _).
  - unfold sdec.
    rewrite (frun_pos f) by lia.
    cbn [map gdecode expand app].
    rewrite EH, EB, EF5.
    change (N.to_nat 8) with 8%nat.
    change (N.to_nat 4) with 4%nat.
    change (N.to_nat 3) with 3%nat.
    change (N.to_nat 2) with 2%nat.
    change (N.to_nat 1) with 1%nat.
    cbn [pair_runs app].
    flatapp.
    rewrite ?app_nil_r.
    exact HT.
  - unfold sdec.
    destruct ((1 <? B)%N) eqn:ELT.
    { apply N.ltb_lt in ELT.
      assert (EBm : N.to_nat (B - 1)%N = nb)
        by (rewrite N2Nat.inj_sub, EB;
            change (N.to_nat 1) with 1%nat; lia).
      cbn [map gdecode expand app frun].
      rewrite EH, EBm, EFm.
      change (N.to_nat 8) with 8%nat.
      change (N.to_nat 7) with 7%nat.
      change (N.to_nat 4) with 4%nat.
      change (N.to_nat 3) with 3%nat.
      change (N.to_nat 2) with 2%nat.
      change (N.to_nat 1) with 1%nat.
      cbn [pair_runs app].
      flatapp.
      rewrite ?app_nil_r.
      reflexivity. }
    apply N.ltb_ge in ELT.
    assert (EB1x : B = 1%N) by lia. subst B.
    assert (ENB0 : nb = 0%nat) by (cbn in EB; lia). subst nb.
    cbn [map gdecode expand app frun].
    rewrite EH, EFm.
    change (N.to_nat 8) with 8%nat.
    change (N.to_nat 7) with 7%nat.
    change (N.to_nat 4) with 4%nat.
    change (N.to_nat 3) with 3%nat.
    change (N.to_nat 2) with 2%nat.
    change (N.to_nat 1) with 1%nat.
    cbn [pair_runs app].
    flatapp.
    rewrite ?app_nil_r.
    reflexivity.
Qed.
