Lemma dtb4o_core (c1 e : N) (cn' d : nat) (tl : word) :
  N.to_nat c1 = S cn' ->
  expand (map gdecode tl) = pair_runs 4 2 d ->
  N.to_nat e = S d ->
  exists c p q,
    FTrip c (sdec ((8,2,1)%N :: (4,2,c1)%N :: (3,2,1)%N :: tl) 4) p q
    /\ wconf [] 0 ((1,S p)::q)
       = wconf [] 0
           (sdec ((7,1,1)%N :: (3,2,1)%N
                  :: (if (1 <? c1)%N then [(4,2,(c1-1))%N] else [])
                     ++ [(4,1,1)%N; (4,2,e)%N]) 4).
Proof.
  intros EC ETL EE.
  pose proof (FTrip_x218og 3 cn' d) as HT.
  rewrite !uword_repeat_w in HT.
  change ((2 + 2)%nat) with 4%nat in HT.
  change ((5 + 3)%nat) with 8%nat in HT.
  change ((3 + 3)%nat) with 6%nat in HT.
  eexists. eexists. eexists. split.
  - unfold sdec.
    cbn [map gdecode expand app frun].
    rewrite ETL, EC.
    change (N.to_nat 8) with 8%nat.
    change (N.to_nat 4) with 4%nat.
    change (N.to_nat 3) with 3%nat.
    change (N.to_nat 2) with 2%nat.
    change (N.to_nat 1) with 1%nat.
    cbn [pair_runs app].
    flatapp. flatappH HT.
    exact HT.
  - assert (ECm : N.to_nat (c1 - 1)%N = cn')
      by (rewrite N2Nat.inj_sub, EC;
          change (N.to_nat 1) with 1%nat; lia).
    rewrite !sdec_cons.
    rewrite (sdec_optk 4 2 c1 1 [(4,1,1)%N; (4,2,e)%N] 4).
    rewrite !sdec_cons, sdec_nil.
    rewrite ECm, EE.
    change (N.to_nat 7) with 7%nat.
    change (N.to_nat 4) with 4%nat.
    change (N.to_nat 3) with 3%nat.
    change (N.to_nat 2) with 2%nat.
    change (N.to_nat 1) with 1%nat.
    cbn [frun pair_runs app].
    flatapp.
    reflexivity.
Qed.
Lemma dtb4_ftrip (cols : word) :
  forall cols',
  forallb (fun g => is_col g && negb (is_cmf g)
                    && (3 <=? gO g)%N) cols = true ->
  dtb4_conv cols = Some cols' ->
  exists c p q,
    FTrip c (sdec cols 4) p q
    /\ wconf [] 0 ((1,S p)::q) = wconf [] 0 (sdec cols' 4).
Proof.
  Transparent dtb4_conv.
  induction cols as [|[[go gz] gc] t IH]; intros cols' HB HD.
  { cbn in HD. discriminate. }
  cbn [forallb] in HB. apply andb_prop in HB. destruct HB as (HG & HB').
  cbn [dtb4_conv gO gZ gC] in HD.
  destruct (dtb4_conv t) as [t'|] eqn:ED.
  { injection HD as <-.
    destruct (IH t' HB' eq_refl) as (ci & pi & qi & HFi & EQi).
    assert (HG1 : forallb (fun g => is_col g && negb (is_cmf g)
                                    && (3 <=? gO g)%N)
                    [(go,gz,gc)%N] = true)
      by (cbn [forallb]; rewrite HG; reflexivity).
    exact (ren_lift [(go,gz,gc)%N] t t' 4 4 ci pi qi HG1 HFi EQi). }
  destruct ((go =? 8)%N && (gz =? 2)%N && (gc =? 1)%N) eqn:EGU;
    [|discriminate].
  apply andb_prop in EGU. destruct EGU as (EGU & EGC).
  apply andb_prop in EGU. destruct EGU as (EGO & EGZ).
  apply N.eqb_eq in EGO, EGZ, EGC. subst go gz gc.
  destruct (forallb w42 t) eqn:EW42.
  2:{
      destruct t as [|[[o1 z1] c1] t1]; [discriminate|].
      destruct t1 as [|[[o2 z2] c2] t2]; [discriminate|].
      cbn [w42 gO gZ forallb] in EW42.
      destruct ((o1 =? 4)%N && (z1 =? 2)%N && (1 <=? c1)%N
                && (o2 =? 3)%N && (z2 =? 2)%N && (c2 =? 1)%N) eqn:EGO2;
        [|discriminate].
      apply andb_prop in EGO2. destruct EGO2 as (EGO2 & EC2).
      apply andb_prop in EGO2. destruct EGO2 as (EGO2 & EZ2).
      apply andb_prop in EGO2. destruct EGO2 as (EGO2 & EO2).
      apply andb_prop in EGO2. destruct EGO2 as (EGO2 & EC1).
      apply andb_prop in EGO2. destruct EGO2 as (EO1 & EZ1).
      apply N.eqb_eq in EO1, EZ1, EO2, EZ2, EC2.
      apply N.leb_le in EC1.
      subst o1 z1 o2 z2 c2.
      destruct (to_nat_ge1 c1 EC1) as [cn' EC].
      destruct t2 as [|[[o3 z3] c3] t3].
      { injection HD as <-.
        exact (dtb4o_core c1 1 cn' 0 [] EC eq_refl eq_refl). }
      destruct t3 as [|g4 t4]; [|discriminate].
      destruct ((o3 =? 4)%N && (z3 =? 2)%N) eqn:EG3; [|discriminate].
      injection HD as <-.
      apply andb_prop in EG3. destruct EG3 as (EO3 & EZ3).
      apply N.eqb_eq in EO3, EZ3. subst o3 z3.
      refine (dtb4o_core c1 (c3+1)%N cn' (N.to_nat c3) [(4,2,c3)%N]
                EC _ _).
      - cbn [map gdecode expand app].
        change (N.to_nat 4) with 4%nat. change (N.to_nat 2) with 2%nat.
        rewrite app_nil_r. reflexivity.
      - rewrite N2Nat.inj_add.
        change (N.to_nat 1) with 1%nat. lia. }
  injection HD as <-.
  destruct (w42_expand t EW42) as [K EK].
  unfold sdec.
  cbn [map gdecode expand app frun].
  rewrite !EK.
  change (N.to_nat 8) with 8%nat. change (N.to_nat 7) with 7%nat.
  change (N.to_nat 3) with 3%nat. change (N.to_nat 2) with 2%nat.
  change (N.to_nat 1) with 1%nat. change (N.to_nat 4) with 4%nat.
  cbn [pair_runs app].
  flatapp.
  destruct K as [|k'].
  - exists 7%nat, 6%nat, ((0,1%nat)::(1,3%nat)::(0,2%nat)::[(1,4%nat)]).
    cbn [pair_runs app].
    split; [exact FTrip_dtb4_0 | reflexivity].
  - pose proof (FTrip_dtb4S k') as HT.
    cbn [uword app] in HT.
    rewrite !uword_rep2_snoc in HT.
    exists (3 * k' + 10)%nat, 6%nat,
      ((0,1%nat)::(1,3%nat)::(0,2%nat)
         :: pair_runs 4 2 (S k') ++ [(1,4%nat)]).
    split; [exact HT | reflexivity].
Qed.
Lemma ren_far_tail (cols2 : word) (f : N) :
  forallb (fun g => is_col g && negb (is_cmf g)
                    && (3 <=? gO g)%N) cols2 = true ->
  (5 <= f)%N ->
  exists c p q,
    FTrip c (sdec cols2 f) p q
    /\ wconf [] 0 ((1,S p)::q)
       = wconf [] 0 (sdec (cols2 ++ [((f-1)%N,1,1)%N]) 3).
Proof.
  intros HCOLS2 EF5g.
  pose (wj := N.to_nat (f - 5)%N).
  assert (EF5 : N.to_nat f = (5 + wj)%nat)
    by (unfold wj; rewrite N2Nat.inj_sub;
        change (N.to_nat 5) with 5%nat; lia).
  assert (EFm : N.to_nat (f - 1)%N = (4 + wj)%nat)
    by (unfold wj; rewrite !N2Nat.inj_sub;
        change (N.to_nat 5) with 5%nat;
        change (N.to_nat 1) with 1%nat; lia).
  assert (HF0 : FTrip 4 (sdec [] f) (3 + wj)%nat
                  ((0,1%nat)::[(1,3%nat)])).
  { unfold sdec. cbn [map expand app].
    rewrite (frun_pos f) by lia.
    rewrite EF5. exact (FTrip_farbare wj). }
  assert (EQ0 : wconf [] 0 ((1,(4 + wj)%nat)::(0,1%nat)::[(1,3%nat)])
                = wconf [] 0 (sdec [((f-1)%N,1,1)%N] 3)).
  { unfold sdec.
    cbn [map gdecode expand app frun].
    rewrite EFm.
    change (N.to_nat 1) with 1%nat.
    cbn [pair_runs app].
    reflexivity. }
  destruct (ren_lift cols2 [] [((f-1)%N,1,1)%N] f 3 _ _ _
              HCOLS2 HF0 EQ0)
    as (c2 & p2 & q2 & HF2 & EQ2).
  rewrite app_nil_r in HF2.
  exists c2, p2, q2. split; [exact HF2 | exact EQ2].
Qed.
Lemma ren_lawR_tail (ini : word) (gbc B : N) (h1 nb : nat)
    (cols2 : word) :
  forallb (fun g => is_col g && negb (is_cmf g)
                    && (3 <=? gO g)%N) ini = true ->
  N.to_nat gbc = S h1 -> N.to_nat B = S nb ->
  forallb w42 cols2 = true ->
  exists c2 p2 q2,
    FTrip c2 (sdec ((ini ++ [(8,2,1)%N; (4,2,gbc)%N])
                    ++ (4,3,1)%N :: (4,2,B)%N :: cols2) 4) p2 q2
    /\ wconf [] 0 ((1,S p2)::q2)
       = wconf [] 0
           (sdec ((ini ++ [(7,1,1)%N; (3,2,1)%N; (4,2,gbc)%N;
                           (7,1,1)%N; (3,2,1)%N]
                   ++ (if (1 <? B)%N then [(4,2,(B-1))%N] else []))
                  ++ cols2) 4).
Proof.
  intros HPI EH EB EW42.
    destruct (w42_expand cols2 EW42) as [K EK2].
    pose proof (FTrip_lawR h1 (nb + K)) as HT.
    cbn [uword app] in HT.
    rewrite !uword_rep2_snoc, !uword_repeat_w in HT.
    flatapp.
    refine (ren_lift ini _ _ _ _ _ _ _ HPI _ _).
    - rewrite !sdec_cons.
      rewrite EH, EB.
      change (N.to_nat 8) with 8%nat.
      change (N.to_nat 4) with 4%nat.
      change (N.to_nat 3) with 3%nat.
      change (N.to_nat 2) with 2%nat.
      change (N.to_nat 1) with 1%nat.
      unfold sdec at 1. rewrite EK2.
      cbn [frun].
      change (N.to_nat 4) with 4%nat.
      cbn [pair_runs app].
      flatapp.
      rewrite pair_runs_add in HT.
      rewrite <- app_assoc in HT.
      exact HT.
    - rewrite !sdec_cons, sdec_app.
      rewrite EH.
      change (N.to_nat 7) with 7%nat.
      change (N.to_nat 4) with 4%nat.
      change (N.to_nat 3) with 3%nat.
      change (N.to_nat 2) with 2%nat.
      change (N.to_nat 1) with 1%nat.
      unfold sdec at 1. rewrite EK2.
      cbn [frun].
      change (N.to_nat 4) with 4%nat.
      destruct ((1 <? B)%N) eqn:ELT.
      { apply N.ltb_lt in ELT.
        assert (EBm : N.to_nat (B - 1)%N = nb)
          by (rewrite N2Nat.inj_sub, EB;
              change (N.to_nat 1) with 1%nat; lia).
        cbn [map gdecode expand].
        rewrite EBm.
        change (N.to_nat 4) with 4%nat. change (N.to_nat 2) with 2%nat.
        cbn [pair_runs app].
        flatapp.
        rewrite ?app_nil_r.
        reflexivity. }
      apply N.ltb_ge in ELT.
      assert (EB1x : B = 1%N) by lia. subst B.
      assert (ENB0 : nb = 0%nat) by (cbn in EB; lia). subst nb.
      cbn [map gdecode expand].
      cbn [pair_runs app].
      flatapp.
      rewrite ?app_nil_r.
      reflexivity.
Qed.
Lemma lawR0_core (B : N) (nb : nat) (cols2 : word) :
  N.to_nat B = S nb ->
  forallb w42 cols2 = true ->
  exists c p q,
    FTrip c (sdec ((8,2,1)%N :: (4,3,1)%N :: (4,2,B)%N :: cols2) 4) p q
    /\ wconf [] 0 ((1,S p)::q)
       = wconf [] 0
           (sdec (((7,1,1)%N :: (3,2,1)%N :: (7,1,1)%N :: (3,2,1)%N
                    :: (if (1 <? B)%N then [(4,2,(B-1))%N] else []))
                  ++ cols2) 4).
Proof.
  intros EB EW42.
  destruct (w42_expand cols2 EW42) as [K EK2].
  pose proof (FTrip_lawR0 (nb + K)) as HT.
  rewrite !uword_repeat_w in HT.
  change ((2 + 2)%nat) with 4%nat in HT.
  eexists. eexists. eexists. split.
  - rewrite !sdec_cons.
    rewrite EB.
    change (N.to_nat 8) with 8%nat.
    change (N.to_nat 4) with 4%nat.
    change (N.to_nat 3) with 3%nat.
    change (N.to_nat 2) with 2%nat.
    change (N.to_nat 1) with 1%nat.
    unfold sdec at 1. rewrite EK2.
    cbn [frun].
    change (N.to_nat 4) with 4%nat.
    cbn [pair_runs app].
    flatapp.
    rewrite pair_runs_add in HT.
    rewrite <- app_assoc in HT.
    exact HT.
  - flatapp.
    rewrite !sdec_cons, sdec_app.
    change (N.to_nat 7) with 7%nat.
    change (N.to_nat 4) with 4%nat.
    change (N.to_nat 3) with 3%nat.
    change (N.to_nat 2) with 2%nat.
    change (N.to_nat 1) with 1%nat.
    unfold sdec at 1. rewrite EK2.
    cbn [frun].
    change (N.to_nat 4) with 4%nat.
    destruct ((1 <? B)%N) eqn:ELT.
    { apply N.ltb_lt in ELT.
      assert (EBm : N.to_nat (B - 1)%N = nb)
        by (rewrite N2Nat.inj_sub, EB;
            change (N.to_nat 1) with 1%nat; lia).
      cbn [map gdecode expand].
      rewrite EBm.
      change (N.to_nat 4) with 4%nat. change (N.to_nat 2) with 2%nat.
      cbn [pair_runs app].
      flatapp.
      rewrite ?app_nil_r.
      reflexivity. }
    apply N.ltb_ge in ELT.
    assert (EB1x : B = 1%N) by lia. subst B.
    assert (ENB0 : nb = 0%nat) by (cbn in EB; lia). subst nb.
    cbn [map gdecode expand].
    cbn [pair_runs app].
    flatapp.
    rewrite ?app_nil_r.
    reflexivity.
Qed.
Lemma ren_lawR0_tail (ini : word) (ga : bg) (B : N) (nb : nat)
    (cols2 : word) :
  forallb (fun g => is_col g && negb (is_cmf g)
                    && (3 <=? gO g)%N) (ini ++ [ga]) = true ->
  N.to_nat B = S nb ->
  forallb w42 cols2 = true ->
  exists c2 p2 q2,
    FTrip c2 (sdec ((ini ++ [ga; (8,2,1)%N])
                    ++ (4,3,1)%N :: (4,2,B)%N :: cols2) 4) p2 q2
    /\ wconf [] 0 ((1,S p2)::q2)
       = wconf [] 0
           (sdec ((ini ++ [ga; (7,1,1)%N; (3,2,1)%N; (7,1,1)%N; (3,2,1)%N]
                   ++ (if (1 <? B)%N then [(4,2,(B-1))%N] else []))
                  ++ cols2) 4).
Proof.
  intros HPI EB EW42.
  destruct (lawR0_core B nb cols2 EB EW42) as (c & p & q & HF & EQ).
  flatapp. flatappH EQ.
  exact (ren_lift1 ini ga _ _ 4%N 4%N c p q HPI HF EQ).
Qed.
Lemma sdec_lvl_app (c : N) (r : word) (f : N) :
  sdec ((if (1 <? c)%N then [(4,2,c-1)%N] else []) ++ r) f
  = sdec ((4,2,(c-1))%N :: r) f.
Proof. rewrite (sdec_optk 4 2 c 1 r f), sdec_cons. reflexivity. Qed.
Lemma sdec_lvl (c : N) (f : N) :
  sdec (if (1 <? c)%N then [(4,2,c-1)%N] else []) f
  = sdec [(4,2,(c-1))%N] f.
Proof.
  destruct (1 <? c)%N eqn:E; [reflexivity|].
  apply N.ltb_ge in E.
  replace (c - 1)%N with 0%N by lia.
  rewrite sdec_cons. change (N.to_nat 0) with 0%nat.
  cbn [pair_runs app]. reflexivity.
Qed.
Lemma leaf_act_z3 (o c : N) (t : word) (f : N) :
  leaf_act ((o,3,c)%N :: t) f = None.
Proof.
  Transparent leaf_act. cbn [leaf_act]. reflexivity.
Qed.
Lemma casc_stage (X cY : N) (rest TAIL : word) (f f2 : N)
    (c p : nat) (q : wside) :
  (5 <= X)%N -> (1 <= cY)%N ->
  FTrip c (sdec rest f) p q ->
  wconf [] 0 ((1,S p)::q) = wconf [] 0 (sdec TAIL f2) ->
  exists c2 p2 q2,
    FTrip c2 (sdec ((X,3,1)%N :: (4,2,cY)%N :: rest) f) p2 q2
    /\ wconf [] 0 ((1,S p2)::q2)
       = wconf [] 0
           (sdec ((X-1,1,1)%N :: (7,2,1)%N :: (4,2,(cY-1))%N :: TAIL) f2).
Proof.
  intros E5 EC1 HF EQ.
  exists (c + 3 * N.to_nat (cY-1)%N + 6)%nat, (3 + N.to_nat (X-5)%N)%nat,
    ((0,1%nat)::(1,7%nat)::(0,2%nat)
       :: uword (repeat 2%nat (N.to_nat (cY-1)%N)) ((1,S p)::q)).
  split.
  - rewrite !sdec_cons.
    change (N.to_nat 3) with 3%nat. change (N.to_nat 4) with 4%nat.
    change (N.to_nat 2) with 2%nat. change (N.to_nat 1) with 1%nat.
    rewrite (NtoS5 X E5), (NtoSc cY EC1).
    cbn [pair_runs app].
    rewrite <- uword2_pair.
    exact (FTrip_stageXg (N.to_nat (X-5)%N) c (sdec rest f) p q
             (N.to_nat (cY-1)%N) HF).
  - rewrite !sdec_cons.
    change (N.to_nat 7) with 7%nat.
    change (N.to_nat 2) with 2%nat. change (N.to_nat 1) with 1%nat.
    rewrite (NtoS4 X E5), uword2_pair.
    cbn [pair_runs app].
    change (N.to_nat 4) with 4%nat.
    repeat apply wconf_cons_cong.
    apply wconf_app_cong. exact EQ.
Qed.
Lemma casc_stage_sand (X cY : N) (rest TAIL : word) (f f2 : N)
    (c p : nat) (q : wside) :
  (5 <= X)%N -> (1 <= cY)%N ->
  Sand c (sdec rest f) ((1,S p)::q) ->
  (1,S p)::q = sdec TAIL f2 ->
  exists c2 p2 q2,
    FTrip c2 (sdec ((X,3,1)%N :: (4,2,cY)%N :: rest) f) p2 q2
    /\ wconf [] 0 ((1,S p2)::q2)
       = wconf [] 0
           (sdec ((X-1,1,1)%N :: (7,2,1)%N :: (4,2,(cY-1))%N :: TAIL) f2).
Proof.
  intros E5 EC1 HS EQ.
  exists (c + 3 * N.to_nat (cY-1)%N + 5)%nat, (3 + N.to_nat (X-5)%N)%nat,
    ((0,1%nat)::(1,7%nat)::(0,2%nat)
       :: uword (repeat 2%nat (N.to_nat (cY-1)%N)) ((1,S p)::q)).
  split.
  - rewrite !sdec_cons.
    change (N.to_nat 3) with 3%nat. change (N.to_nat 4) with 4%nat.
    change (N.to_nat 2) with 2%nat. change (N.to_nat 1) with 1%nat.
    rewrite (NtoS5 X E5), (NtoSc cY EC1).
    cbn [pair_runs app].
    rewrite <- uword2_pair.
    exact (FTrip_stageXg_sand (N.to_nat (X-5)%N) c (sdec rest f) p q
             (N.to_nat (cY-1)%N) HS).
  - rewrite !sdec_cons.
    change (N.to_nat 7) with 7%nat.
    change (N.to_nat 2) with 2%nat. change (N.to_nat 1) with 1%nat.
    rewrite (NtoS4 X E5), uword2_pair.
    cbn [pair_runs app].
    change (N.to_nat 4) with 4%nat.
    rewrite EQ. reflexivity.
Qed.
Lemma retag8_stage (X : N) (rest TAIL : word) (f f2 : N)
    (c p : nat) (q : wside) :
  (5 <= X)%N ->
  FTrip c (sdec rest f) p q ->
  wconf [] 0 ((1,S p)::q) = wconf [] 0 (sdec TAIL f2) ->
  exists c2 p2 q2,
    FTrip c2 (sdec ((X,3,1)%N :: (8,2,1)%N :: rest) f) p2 q2
    /\ wconf [] 0 ((1,S p2)::q2)
       = wconf [] 0 (sdec ((X-1,1,1)%N :: (11,2,1)%N :: TAIL) f2).
Proof.
  intros E5 HF EQ.
  exists (c + 6)%nat, (3 + N.to_nat (X-5)%N)%nat,
    ((0,1%nat)::(1,11%nat)::(0,2%nat)::(1,S p)::q).
  split.
  - rewrite !sdec_cons.
    change (N.to_nat 3) with 3%nat. change (N.to_nat 8) with 8%nat.
    change (N.to_nat 2) with 2%nat. change (N.to_nat 1) with 1%nat.
    rewrite (NtoS5 X E5).
    cbn [pair_runs app].
    exact (FTrip_retag8 (N.to_nat (X-5)%N) c (sdec rest f) p q HF).
  - rewrite !sdec_cons.
    change (N.to_nat 11) with 11%nat.
    change (N.to_nat 2) with 2%nat. change (N.to_nat 1) with 1%nat.
    rewrite (NtoS4 X E5).
    cbn [pair_runs app].
    repeat apply wconf_cons_cong.
    exact EQ.
Qed.
Lemma sand_leaf_z1 (A C : N) (t : word) :
  sand_leaf ((A,1,C)%N :: t) = false.
Proof. destruct t; reflexivity. Qed.
Lemma retag8_leaf1 (X : N) (cols s2' t : word) (f f2 A C : N) :
  (5 <= X)%N ->
  forallb is_col cols = true ->
  leaf_act ((A,1,C)%N :: t) f = Some (s2', f2) ->
  exists c p q,
    FTrip c (sdec ((X,3,1)%N :: (8,2,1)%N :: cols ++ (A,1,C)%N :: t) f) p q
    /\ wconf [] 0 ((1,S p)::q)
       = wconf [] 0 (sdec ((X-1,1,1)%N :: (11,2,1)%N :: cols ++ s2') f2).
Proof.
  intros E5 HC HLA.
  destruct (leaf_ftrip _ _ _ _ HLA)
    as [(ci & pi & qi & HFi & EQi)|(ci & pi & qi & _ & _ & ESL & _)].
  - destruct (ren_lift2 cols ((A,1,C)%N :: t) s2' f f2 ci pi qi HC HFi EQi)
      as (c2 & p2 & q2 & HF2 & EQ2).
    exact (retag8_stage X (cols ++ (A,1,C)%N :: t) (cols ++ s2') f f2
             c2 p2 q2 E5 HF2 EQ2).
  - rewrite sand_leaf_z1 in ESL. discriminate.
Qed.
Lemma casc_leaf (X cY : N) (cols s2 s2' : word) (f f2 : N) :
  (5 <= X)%N -> (1 <= cY)%N ->
  forallb (fun g => is_col g && negb (is_cmf g)
                    && (3 <=? gO g)%N) cols = true ->
  leaf_act s2 f = Some (s2', f2) ->
  exists c p q,
    FTrip c (sdec ((X,3,1)%N :: (4,2,cY)%N :: cols ++ s2) f) p q
    /\ wconf [] 0 ((1,S p)::q)
       = wconf [] 0
           (sdec ((X-1,1,1)%N :: (7,2,1)%N :: (4,2,(cY-1))%N
                  :: cols ++ s2') f2).
Proof.
  intros E5 EC1 HC HLA.
  destruct (leaf_ftrip _ _ _ _ HLA)
    as [(ci & pi & qi & HFi & EQi)|(ci & pi & qi & HSi & EQi & _ & _)].
  - destruct (ren_lift cols s2 s2' f f2 ci pi qi HC HFi EQi)
      as (c2 & p2 & q2 & HF2 & EQ2).
    exact (casc_stage X cY (cols ++ s2) (cols ++ s2') f f2 c2 p2 q2
             E5 EC1 HF2 EQ2).
  - destruct (Sand_cols cols ci (sdec s2 f) ((1,S pi)::qi) HC HSi)
      as [(c2 & p2 & q2 & HF2 & EQ2)|ENIL].
    + refine (casc_stage X cY (cols ++ s2) (cols ++ s2') f f2 c2 p2 q2
                E5 EC1 _ _).
      * rewrite sdec_app. exact HF2.
      * rewrite EQ2, EQi, sdec_app. reflexivity.
    + refine (casc_stage_sand X cY (cols ++ s2) (cols ++ s2') f f2 ci pi qi
                E5 EC1 _ _).
      * rewrite sdec_app, ENIL. cbn [app]. exact HSi.
      * rewrite sdec_app, ENIL. cbn [app]. exact EQi.
Qed.
Lemma dtb3_ftrip (cols : word) :
  forall cols',
  forallb (fun g => is_col g && negb (is_cmf g)
                    && (3 <=? gO g)%N) cols = true ->
  dtb3_conv cols = Some cols' ->
  exists c p q,
    FTrip c (sdec cols 3) p q
    /\ wconf [] 0 ((1,S p)::q) = wconf [] 0 (sdec (cols' ++ [(4,1,1)%N]) 4).
Proof.
  Transparent dtb3_conv.
  induction cols as [|[[go gz] gc] t IH]; intros cols' HB HD.
  { cbn in HD. discriminate. }
  cbn [forallb] in HB. apply andb_prop in HB. destruct HB as (HG & HB').
  cbn [dtb3_conv gO gZ gC] in HD.
  destruct (dtb3_conv t) as [t'|] eqn:ED.
  { injection HD as <-.
    destruct (IH t' HB' eq_refl) as (ci & pi & qi & HFi & EQi).
    assert (HG1 : forallb (fun g => is_col g && negb (is_cmf g)
                                    && (3 <=? gO g)%N)
                    [(go,gz,gc)%N] = true)
      by (cbn [forallb]; rewrite HG; reflexivity).
    exact (ren_lift [(go,gz,gc)%N] t (t' ++ [(4,1,1)%N]) 3 4 ci pi qi
             HG1 HFi EQi). }
  destruct ((go =? 8)%N && (gz =? 2)%N && (gc =? 1)%N) eqn:EGU;
    [|discriminate].
  destruct t as [|[[o1 z1] c1] t1]; [discriminate|].
  destruct ((o1 =? 4)%N && (z1 =? 2)%N && (1 <? c1)%N
            && forallb w42 t1) eqn:EG2; [|discriminate].
  injection HD as <-.
  apply andb_prop in EGU. destruct EGU as (EGU & EGC).
  apply andb_prop in EGU. destruct EGU as (EGO & EGZ).
  apply N.eqb_eq in EGO, EGZ, EGC. subst go gz gc.
  apply andb_prop in EG2. destruct EG2 as (EG2 & EW42).
  apply andb_prop in EG2. destruct EG2 as (EG2 & EC12).
  apply andb_prop in EG2. destruct EG2 as (EO1 & EZ1).
  apply N.eqb_eq in EO1, EZ1. apply N.ltb_lt in EC12.
  subst o1 z1.
  destruct (w42_expand t1 EW42) as [K EK].
  assert (EMM : (N.to_nat c1 + K)%nat = S (N.to_nat (c1-1)%N + K)%nat)
    by (rewrite N2Nat.inj_sub;
        change (N.to_nat 1) with 1%nat; lia).
  exists (3 * (N.to_nat (c1-1)%N + K) + 9)%nat, 6%nat,
    ((0,1%nat)::(1,3%nat)::(0,2%nat)
       :: uword (repeat 2%nat (N.to_nat (c1-1)%N + K))
            ((1,4%nat)::(0,1%nat)::[(1,4%nat)])).
  split.
  - rewrite !sdec_cons.
    unfold sdec at 1. rewrite EK.
    cbn [frun].
    change (N.to_nat 8) with 8%nat. change (N.to_nat 4) with 4%nat.
    change (N.to_nat 3) with 3%nat. change (N.to_nat 2) with 2%nat.
    change (N.to_nat 1) with 1%nat.
    cbn [pair_runs app].
    rewrite app_assoc, <- pair_runs_add, EMM.
    rewrite <- uword_rep2_snoc.
    change ((1,8%nat)::(0,2%nat)
              :: uword (repeat 2%nat (N.to_nat (c1-1)%N + K) ++ [2%nat])
                   [(1,3%nat)])
      with (uword ((6%nat :: repeat 2%nat (N.to_nat (c1-1)%N + K))
                   ++ [2%nat]) [(1,3%nat)]).
    exact (FTrip_dtb3S (N.to_nat (c1-1)%N + K)%nat).
  - cbn [app].
    rewrite !sdec_cons, sdec_app, !sdec_cons, sdec_nil, EK.
    rewrite (frun_pos 4 ltac:(lia)).
    change (N.to_nat 7) with 7%nat. change (N.to_nat 4) with 4%nat.
    change (N.to_nat 3) with 3%nat. change (N.to_nat 2) with 2%nat.
    change (N.to_nat 1) with 1%nat.
    cbn [pair_runs app].
    rewrite uword2_pair, pair_runs_add, <- app_assoc.
    reflexivity.
Qed.
Lemma casc_jump_inner (cols sfx tail seg : word) (B f f2 : N)
    (ci pi : nat) (qi : wside) :
  forallb (fun g => is_col g && negb (is_cmf g)
                    && (3 <=? gO g)%N) cols = true ->
  jump_seg cols B = Some seg ->
  (1 <= B)%N ->
  FTrip ci (sdec sfx f) pi qi ->
  wconf [] 0 ((1,S pi)::qi) = wconf [] 0 (sdec tail f2) ->
  exists c p q,
    FTrip c (sdec (cols ++ (4,3,1)%N :: (4,2,B)%N :: sfx) f) p q
    /\ wconf [] 0 ((1,S p)::q) = wconf [] 0 (sdec (seg ++ tail) f2).
Proof.
  intros HPC EJS EB1 HFi EQi.
  destruct (jump_seg_split cols seg B EJS)
    as (P & blk & ECOLS & ESEG & HBLK & _).
  subst cols seg.
  exact (ren_jumpU P blk sfx tail B f f2 ci pi qi
           (jsplit_cols P blk HPC) HBLK EB1 HFi EQi).
Qed.
Lemma casc_jumpbare_inner (cols seg : word) (B f : N) :
  forallb (fun g => is_col g && negb (is_cmf g)
                    && (3 <=? gO g)%N) cols = true ->
  jump_seg cols B = Some seg ->
  (1 <= B)%N -> (5 <= f)%N ->
  exists c p q,
    FTrip c (sdec (cols ++ (4,3,1)%N :: (4,2,B)%N :: []) f) p q
    /\ wconf [] 0 ((1,S p)::q)
       = wconf [] 0 (sdec (seg ++ [((f-1)%N,1,1)%N]) 3).
Proof.
  intros HPC EJS EB1 EF5.
  destruct (jump_seg_split cols seg B EJS)
    as (P & blk & ECOLS & ESEG & HBLK & _).
  subst cols seg.
  exact (ren_jumpbareU P blk B f (jsplit_cols P blk HPC) HBLK EB1 EF5).
Qed.
Lemma casc_lcjmp_inner (cols tail seg : word) (cn f : N) :
  forallb (fun g => is_col g && negb (is_cmf g)
                    && (3 <=? gO g)%N) cols = true ->
  jump_seg cols cn = Some seg ->
  (1 <= cn)%N ->
  exists c p q,
    FTrip c (sdec (cols ++ (4,4,1)%N :: (4,2,cn)%N :: tail) f) p q
    /\ wconf [] 0 ((1,S p)::q) = wconf [] 0 (sdec (seg ++ tail) f).
Proof.
  intros HPC EJS EC1.
  destruct (jump_seg_split cols seg cn EJS)
    as (P & blk & ECOLS & ESEG & HBLK & _).
  subst cols seg.
  exact (ren_lcjmpU P blk tail cn f (jsplit_cols P blk HPC) HBLK EC1).
Qed.
Lemma casc_lawR_inner (cols cols2 seg2 : word) (B : N) :
  forallb (fun g => is_col g && negb (is_cmf g)
                    && (3 <=? gO g)%N) cols = true ->
  lawR_seg cols B = Some seg2 ->
  (1 <= B)%N ->
  forallb w42 cols2 = true ->
  exists c p q,
    FTrip c (sdec (cols ++ (4,3,1)%N :: (4,2,B)%N :: cols2) 4) p q
    /\ wconf [] 0 ((1,S p)::q) = wconf [] 0 (sdec (seg2 ++ cols2) 4).
Proof.
  intros HPC ELS EB1 EW42.
  unfold lawR_seg in ELS.
  destruct (last2 cols)
    as [[[ini [[gao gaz] gac]] [[gbo gbz] gbc]]|] eqn:EL2; [|discriminate].
  pose proof (last2_split _ _ _ _ EL2) as ECOLS.
  rewrite ECOLS in HPC. rewrite forallb_app in HPC.
  apply andb_prop in HPC. destruct HPC as (HPI & HPG).
  destruct ((gao =? 8)%N && (gaz =? 2)%N && (gac =? 1)%N
            && (gbo =? 4)%N && (gbz =? 2)%N && (1 <=? gbc)%N) eqn:EG1.
  { injection ELS as <-.
  apply andb_prop in EG1. destruct EG1 as (EG1 & EGB1).
  apply andb_prop in EG1. destruct EG1 as (EG1 & EBZ).
  apply andb_prop in EG1. destruct EG1 as (EG1 & EBO).
  apply andb_prop in EG1. destruct EG1 as (EAOZ & EAC).
  apply andb_prop in EAOZ. destruct EAOZ as (EAO & EAZ).
  apply N.eqb_eq in EAO, EAZ, EAC, EBO, EBZ.
  apply N.leb_le in EGB1.
  subst gao gaz gac gbo gbz.
  destruct (to_nat_ge1 gbc EGB1) as [h1 EH].
  destruct (to_nat_ge1 B EB1) as [nb EB].
  rewrite ECOLS.
  exact (ren_lawR_tail ini gbc B h1 nb cols2 HPI EH EB EW42). }
  destruct ((gbo =? 8)%N && (gbz =? 2)%N && (gbc =? 1)%N) eqn:EG2;
    [|discriminate].
  injection ELS as <-.
  apply andb_prop in EG2. destruct EG2 as (EG2 & EBC).
  apply andb_prop in EG2. destruct EG2 as (EBO & EBZ).
  apply N.eqb_eq in EBO, EBZ, EBC.
  subst gbo gbz gbc.
  destruct (to_nat_ge1 B EB1) as [nb EB].
  assert (HPI2 : forallb (fun g => is_col g && negb (is_cmf g)
                                   && (3 <=? gO g)%N)
                   (ini ++ [(gao,gaz,gac)%N]) = true).
  { rewrite forallb_app, HPI.
    cbn [forallb] in HPG |- *.
    apply andb_prop in HPG. destruct HPG as (HGA & _).
    rewrite HGA. reflexivity. }
  rewrite ECOLS.
  exact (ren_lawR0_tail ini (gao,gaz,gac)%N B nb cols2 HPI2 EB EW42).
Qed.
