Opaque leaf_act.
Lemma tt_split (s : word) (i j : nat) :
  tick_target_s s i = Some j ->
  exists mid g t,
    s = mid ++ g :: t
    /\ List.length mid = (j - i)%nat
    /\ (i <= j)%nat
    /\ forallb (fun x => is_col x && negb (is_cmf x)) mid = true
    /\ ((gZ g =? 1)%N || (3 <=? gZ g)%N || is_cmf g) = true.
Proof.
  revert i j. induction s as [|g0 s' IH]; intros i j H.
  - cbn in H. discriminate.
  - cbn [tick_target_s] in H.
    destruct ((gZ g0 =? 1)%N || (3 <=? gZ g0)%N) eqn:E1.
    { injection H as EJ. subst j.
      exists (@nil bg), g0, s'. cbn [app forallb List.length].
      rewrite E1. cbn [orb].
      repeat split; try lia; reflexivity. }
    destruct (is_cmf g0) eqn:E2.
    { injection H as EJ. subst j.
      exists (@nil bg), g0, s'. cbn [app forallb List.length].
      rewrite E1, E2. cbn [orb].
      repeat split; try lia; reflexivity. }
    destruct (is_col g0) eqn:E3; [|discriminate].
    destruct (IH (S i) j H) as (mid & g & t & ES & EL & EI & EC & EG).
    exists (g0 :: mid), g, t.
    cbn [app forallb List.length].
    repeat split.
    + rewrite <- ES. reflexivity.
    + lia.
    + lia.
    + rewrite E3, E2. cbn [andb negb]. exact EC.
    + exact EG.
Qed.
Lemma wat_skipn (w : word) (j : nat) :
  wat w j = hd_error (skipn j w).
Proof.
  revert j. induction w as [|g t IH]; intros j.
  - destruct j; reflexivity.
  - destruct j as [|j']; [reflexivity|].
    cbn [skipn]. unfold wat in *. cbn [nth_error].
    apply IH.
Qed.
Lemma dt_leaf (fuel : nat) (w : word) (f : N) (j : nat)
    (vd : bool) (s' : word) (f' : N) :
  leaf_act (skipn j w) f = Some (s', f') ->
  (match wat w j with
   | Some (_,z,_) => (z =? 1)%N
   | None => false
   end) = true ->
  deliver_tick (S fuel) w f j vd = ROk (firstn j w ++ s') f'.
Proof.
  intros HLA HZ1.
  Transparent leaf_act deliver_tick.
  rewrite wat_skipn in HZ1.
  destruct (skipn j w) as [|[[o z] c] t] eqn:ESK.
  { cbn in HLA. discriminate. }
  cbn [hd_error] in HZ1.
  apply N.eqb_eq in HZ1. subst z.
  assert (EOG2 : (2 <=? o)%N = true).
  { revert HLA. cbn [leaf_act].
    destruct ((2 <=? o)%N) eqn:EOx; [intros; reflexivity|].
    destruct ((2 <=? c)%N), ((c =? 1)%N);
      intros H; cbn [andb orb negb] in H; discriminate H. }
  cbn [deliver_tick].
  rewrite wat_skipn, ESK.
  cbn [hd_error].
  change ((1 =? 1)%N) with true.
  rewrite EOG2. cbn [andb].
  rewrite HLA. reflexivity.
Qed.
Lemma dt_leaf_agree (fuel : nat) (w : word) (f : N) (j : nat)
    (vd : bool) (w' : word) (f' : N) :
  (match wat w j with
   | Some (_,z,_) => (z =? 1)%N
   | None => false
   end) = true ->
  deliver_tick (S fuel) w f j vd = ROk w' f' ->
  leaf_act (skipn j w) f <> None.
Proof.
  intros HZ HDT ELA.
  Transparent deliver_tick.
  cbn [deliver_tick] in HDT.
  Opaque deliver_tick.
  destruct (wat w j) as [[[o z] c]|] eqn:EWJ; [|discriminate].
  cbn beta iota in HZ. apply N.eqb_eq in HZ. subst z.
  change ((1 =? 1)%N) with true in HDT.
  destruct ((2 <=? o)%N) eqn:EO2; cbn [andb] in HDT.
  - rewrite ELA in HDT. discriminate.
  - change ((3 <=? 1)%N) with false in HDT.
    change ((1 =? 2)%N) with false in HDT.
    cbn [andb] in HDT. discriminate.
Qed.
Lemma dt_leaf_conv (fuel : nat) (w : word) (f : N) (j : nat)
    (vd : bool) (w' : word) (f' : N) :
  (match wat w j with
   | Some (_,z,_) => (z =? 1)%N
   | None => false
   end) = true ->
  deliver_tick (S fuel) w f j vd = ROk w' f' ->
  exists s', leaf_act (skipn j w) f = Some (s', f')
             /\ w' = firstn j w ++ s'.
Proof.
  intros HZ HDT.
  destruct (leaf_act (skipn j w) f) as [[s2 f2]|] eqn:ELA.
  2:{ exfalso. exact (dt_leaf_agree fuel w f j vd w' f' HZ HDT ELA). }
  rewrite (dt_leaf fuel w f j vd s2 f2 ELA HZ) in HDT.
  injection HDT as <- <-.
  exists s2. split; reflexivity.
Qed.
Lemma retag8_route1 (X : N) (rest : word) (f : N) (fuel j : nat)
    (s3 : word) (f3 : N) :
  (5 <= X)%N ->
  tick_target ((X-1,1,1)%N :: (11,2,1)%N :: rest) 2 = Some j ->
  (match wat ((X-1,1,1)%N :: (11,2,1)%N :: rest) j with
   | Some (_,z,_) => (z =? 1)%N | None => false end) = true ->
  deliver_tick (S fuel) ((X-1,1,1)%N :: (11,2,1)%N :: rest) f j true
    = ROk s3 f3 ->
  exists c p q,
    FTrip c (sdec ((X,3,1)%N :: (8,2,1)%N :: rest) f) p q
    /\ wconf [] 0 ((1,S p)::q) = wconf [] 0 (sdec s3 f3).
Proof.
  intros E5 HTT HZ HDT.
  set (s2 := (((X-1,1,1)%N :: (11,2,1)%N :: rest) : word)) in *.
  assert (HTS : tick_target_s rest 2 = Some j).
  { unfold tick_target in HTT. exact HTT. }
  destruct (tt_split rest 2 j HTS)
    as (mid & g & t & EREST & ELEN & EIJ & HCOLS & _).
  destruct j as [|[|k]]; [lia|lia|].
  replace (S (S k) - 2)%nat with k in * by lia.
  assert (ESK : skipn k rest = g :: t).
  { rewrite EREST, <- ELEN, skipn_app, skipn_all2 by lia.
    rewrite PeanoNat.Nat.sub_diag. reflexivity. }
  assert (EFN : firstn k rest = mid).
  { rewrite EREST, <- ELEN, firstn_app, firstn_all2 by lia.
    rewrite PeanoNat.Nat.sub_diag. cbn [firstn]. rewrite app_nil_r.
    reflexivity. }
  assert (HSK2 : skipn (S (S k)) s2 = g :: t)
    by (unfold s2; cbn [skipn]; exact ESK).
  assert (EWAT : wat s2 (S (S k)) = Some g)
    by (rewrite wat_skipn, HSK2; reflexivity).
  rewrite EWAT in HZ.
  destruct g as [[A z] C]. cbn in HZ. apply N.eqb_eq in HZ. subst z.
  assert (HZ2 : (match wat s2 (S (S k)) with
                 | Some (_,z,_) => (z =? 1)%N | None => false end) = true)
    by (rewrite EWAT; reflexivity).
  destruct (dt_leaf_conv fuel s2 f (S (S k)) true s3 f3 HZ2 HDT)
    as (s' & ELA & ES3).
  rewrite HSK2 in ELA.
  assert (HFN2 : firstn (S (S k)) s2 = (X-1,1,1)%N :: (11,2,1)%N :: mid)
    by (unfold s2; cbn [firstn]; rewrite EFN; reflexivity).
  rewrite HFN2 in ES3.
  assert (HC2 : forallb is_col mid = true).
  { revert HCOLS. clear. induction mid as [|g mid' IH]; [reflexivity|].
    cbn [forallb]. intros HH. apply andb_prop in HH. destruct HH as (HG & HT).
    apply andb_prop in HG. destruct HG as (HG & _).
    rewrite HG. cbn [andb]. exact (IH HT). }
  destruct (retag8_leaf1 X mid s' t f f3 A C E5 HC2 ELA)
    as (c & p & q & HF & EQ).
  exists c, p, q. split.
  - rewrite EREST. exact HF.
  - rewrite ES3. cbn [app]. exact EQ.
Qed.
Ltac rn_nrm := change (N.to_nat 8) with 8%nat;
            change (N.to_nat 7) with 7%nat;
            change (N.to_nat 6) with 6%nat;
            change (N.to_nat 4) with 4%nat;
            change (N.to_nat 3) with 3%nat;
            change (N.to_nat 2) with 2%nat;
            change (N.to_nat 1) with 1%nat.
Ltac rn3_nrm := change (N.to_nat 8) with 8%nat;
            change (N.to_nat 7) with 7%nat;
            change (N.to_nat 6) with 6%nat;
            change (N.to_nat 4) with 4%nat;
            change (N.to_nat 3) with 3%nat;
            change (N.to_nat 2) with 2%nat;
            change (N.to_nat 1) with 1%nat.
Definition FCProp (n : nat) : Prop :=
  forall (s : word) (f : N) (s' : word) (f2 : N),
  fire_comp n s f = Some (s', f2) ->
  exists c p q,
    FTrip c (sdec s f) p q
    /\ wconf [] 0 ((1,S p)::q) = wconf [] 0 (sdec s' f2).
Definition RNProp (n : nat) : Prop :=
  forall (cols s : word) (f : N) (body : word) (f2 : N),
  forallb (fun g => is_col g && negb (is_cmf g)
                    && (3 <=? gO g)%N) cols = true ->
  renew_seg n cols s f = Some (body, f2) ->
  exists c p q,
    FTrip c (sdec (cols ++ s) f) p q
    /\ wconf [] 0 ((1,S p)::q) = wconf [] 0 (sdec body f2).
Lemma renew_ftrip_step (n : nat) : FCProp n -> RNProp n -> RNProp (S n).
Proof.
  intros IHF IHR cols s f body f2 HPC HR.
    Transparent renew_seg. cbn [renew_seg] in HR.
    Opaque renew_seg.
    destruct s as [|[[o1 z1] c1] rest]; [discriminate|].
    killmN HR.
    destruct rest as [|[[o5 z5] B] rest2].
    {
      match type of HR with
      | context [match endR_seg ?a ?b with _ => _ end] =>
          destruct (endR_seg a b) as [bd|] eqn:EES
      end; [|discriminate].
      injection HR as <- <-.
      unfold endR_seg in EES.
      match type of EES with
      | context [match last2 ?a with _ => _ end] =>
          destruct (last2 a) as [[[ini [[gao gaz] gac]] [[gbo gbz] gbc]]|]
            eqn:EL2
      end; [|discriminate].
      pose proof (last2_split _ _ _ _ EL2) as ECOLS.
      rewrite ECOLS in HPC.
      rewrite forallb_app in HPC.
      apply andb_prop in HPC. destruct HPC as (HPI & HPG).
      rewrite ECOLS.
      rewrite <- app_assoc. cbn [app].
      destruct ((gao =? 8)%N && (gaz =? 2)%N && (gac =? 1)%N
                && (gbo =? 4)%N && (gbz =? 2)%N && (1 <=? gbc)%N
                && (2 <=? f)%N) eqn:EG1.
      {
        injection EES as <-.
        apply andb_prop in EG1. destruct EG1 as (EG1 & EF2g).
        apply andb_prop in EG1. destruct EG1 as (EG1 & EGB1).
        apply andb_prop in EG1. destruct EG1 as (EG1 & EBZ).
        apply andb_prop in EG1. destruct EG1 as (EG1 & EBO).
        apply andb_prop in EG1. destruct EG1 as (EAOZ & EAC).
        apply andb_prop in EAOZ. destruct EAOZ as (EAO & EAZ).
        apply N.eqb_eq in EAO, EAZ, EAC, EBO, EBZ.
        apply N.leb_le in EGB1, EF2g.
        subst gao gaz gac gbo gbz.
        destruct (to_nat_ge1 gbc EGB1) as [h1 EH].
        pose (fp := N.to_nat (f - 2)%N).
        assert (EF2 : N.to_nat f = (2 + fp)%nat)
          by (unfold fp; rewrite N2Nat.inj_sub;
              change (N.to_nat 2) with 2%nat; lia).
        assert (EF3 : N.to_nat (f + 3)%N = (5 + fp)%nat)
          by (unfold fp; rewrite N2Nat.inj_add, N2Nat.inj_sub;
              change (N.to_nat 2) with 2%nat;
              change (N.to_nat 3) with 3%nat; lia).
        pose proof (FTrip_endR h1 fp) as HT.
        cbn [uword app] in HT.
        rewrite !uword_rep2_snoc in HT.
        refine (ren_lift ini _ _ _ _ _ _ _ HPI _ _).
        - unfold sdec.
          rewrite (frun_pos f) by lia.
          cbn [map gdecode expand app].
          rewrite EH, EF2.
          change (N.to_nat 8) with 8%nat.
          change (N.to_nat 4) with 4%nat.
          change (N.to_nat 3) with 3%nat.
          change (N.to_nat 2) with 2%nat.
          change (N.to_nat 1) with 1%nat.
          cbn [pair_runs app].
          flatapp.
          rewrite ?app_nil_r.
          change (pair_runs 4 2 (S h1))
            with ((1,4%nat)::(0,2%nat)::pair_runs 4 2 h1) in HT.
          cbn [app] in HT.
          exact HT.
        - unfold sdec.
          cbn [map gdecode expand app frun].
          rewrite EH, EF3.
          change (N.to_nat 7) with 7%nat.
          change (N.to_nat 4) with 4%nat.
          change (N.to_nat 3) with 3%nat.
          change (N.to_nat 2) with 2%nat.
          change (N.to_nat 1) with 1%nat.
          cbn [pair_runs app].
          flatapp.
          rewrite ?app_nil_r.
          reflexivity. }
      destruct ((gbo =? 8)%N && (gbz =? 2)%N && (gbc =? 1)%N
                && (2 <=? f)%N) eqn:EG2; [|discriminate].
      injection EES as <-.
      apply andb_prop in EG2. destruct EG2 as (EG2 & EF2g).
      apply andb_prop in EG2. destruct EG2 as (EG2 & EBC).
      apply andb_prop in EG2. destruct EG2 as (EBO & EBZ).
      apply N.eqb_eq in EBO, EBZ, EBC.
      apply N.leb_le in EF2g.
      subst gbo gbz gbc.
      pose (fp := N.to_nat (f - 2)%N).
      assert (EF2 : N.to_nat f = (2 + fp)%nat)
        by (unfold fp; rewrite N2Nat.inj_sub;
            change (N.to_nat 2) with 2%nat; lia).
      assert (EF3 : N.to_nat (f + 3)%N = (5 + fp)%nat)
        by (unfold fp; rewrite N2Nat.inj_add, N2Nat.inj_sub;
            change (N.to_nat 2) with 2%nat;
            change (N.to_nat 3) with 3%nat; lia).
      assert (HPI2 : forallb (fun g => is_col g && negb (is_cmf g)
                                       && (3 <=? gO g)%N)
                       (ini ++ [(gao,gaz,gac)%N]) = true).
      { rewrite forallb_app, HPI.
        cbn [forallb] in HPG |- *.
        apply andb_prop in HPG. destruct HPG as (HGA & _).
        rewrite HGA. reflexivity. }
      refine (ren_lift1 ini (gao,gaz,gac)%N _ _ _ _ _ _ _ HPI2 _ _).
      - unfold sdec.
        rewrite (frun_pos f) by lia.
        cbn [map gdecode expand app].
        rewrite EF2.
        change (N.to_nat 8) with 8%nat.
        change (N.to_nat 4) with 4%nat.
        change (N.to_nat 3) with 3%nat.
        change (N.to_nat 2) with 2%nat.
        change (N.to_nat 1) with 1%nat.
        cbn [pair_runs app].
        rewrite ?app_nil_r.
        exact (FTrip_endR0 fp).
      - unfold sdec.
        cbn [map gdecode expand app frun].
        rewrite EF3.
        change (N.to_nat 7) with 7%nat.
        change (N.to_nat 3) with 3%nat.
        change (N.to_nat 2) with 2%nat.
        change (N.to_nat 1) with 1%nat.
        cbn [pair_runs app].
        rewrite ?app_nil_r.
        reflexivity. }
    destruct ((o5 =? 4)%N && (z5 =? 2)%N && (1 <=? B)%N) eqn:E42.
    2:{
        destruct ((z5 =? 3)%N && (B =? 1)%N
                  && match rest2 with [] => true | _ => false end
