          as (ci & pi & qi & HFi & EQi).
        rewrite (app_nil_r cols2).
        exact (casc_jump_inner cols cols2 cols2' seg B 4 4 ci pi qi
                 HPC EES EB1g HFi EQi). }
      destruct (forallb w42 cols2) eqn:EW42; [|discriminate].
      match type of HR with
      | context [match lawR_seg ?a ?b with _ => _ end] =>
          destruct (lawR_seg a b) as [seg2|] eqn:ELS
      end; [|discriminate].
      injection HR as <- <-.
      rewrite (app_nil_r cols2).
      exact (casc_lawR_inner cols cols2 seg2 B HPC ELS EB1g EW42). }
    destruct ((z7 =? 3)%N && (c7 =? 1)%N) eqn:E731.
    {
      match type of HR with
      | context [match fire_comp ?a ?b ?c with _ => _ end] =>
          destruct (fire_comp a b c) as [[s3' fi]|] eqn:EINN
      end; [|discriminate].
      injection HR as <- <-.
      destruct (IHF _ _ _ _ EINN) as (ci & pi & qi & HFi & EQi).
      destruct (ren_lift cols2 _ _ f fi ci pi qi HCOLS2 HFi EQi)
        as (c2 & p2 & q2 & HF2 & EQ2).
      exact (casc_jump_inner cols _ _ seg B f fi c2 p2 q2
               HPC EES EB1g HF2 EQ2). }
    match type of HR with
    | context [if sand_leaf ?ss then _ else _] =>
        revert HR; destruct (sand_leaf ss) eqn:ESAND; intros HR
    end.
    { cbv beta iota in HR. discriminate HR. }
    match type of HR with
    | context [match leaf_act ?a ?b with _ => _ end] =>
        destruct (leaf_act a b) as [[s3' fi]|] eqn:EINN
