    injection HR as <- <-.
    destruct (leaf_ftrip _ _ _ _ EINN)
      as [(ci & pi & qi & HFi & EQi)
         |(ci & pi & qi & HSi & EQi & ES5 & EF4)].
    2:{ rewrite ES5 in ESAND. discriminate ESAND. }
    destruct (ren_lift cols2 _ _ f fi ci pi qi HCOLS2 HFi EQi)
      as (c2 & p2 & q2 & HF2 & EQ2).
    exact (casc_jump_inner cols _ _ seg B f fi c2 p2 q2
             HPC EES EB1g HF2 EQ2).
Qed.
