Local Open Scope N_scope.
Lemma fc_zY1 (n : nat) (X Y cY : N) (rest : word) (f : N) :
  fire_comp (S n) ((X,3,1) :: (Y,1,cY) :: rest) f
  = if negb (5 <=? X) then None else
    if (cY =? 1) && (1 <=? Y)
       && match rest with [] => true | _ => false end
    then (if 2 <=? f then Some ([(X-1,1,1); (Y+3,1,1)], f - 1) else None)
    else if (cY =? 1) && (1 <=? Y)
            && match rest with
               | (o2,z2,c2) :: _ => (o2 =? 4) && (z2 =? 2) && (1 <=? c2)
               | [] => false
               end
    then (match rest with
          | (o2,z2,c2) :: r2 =>
              Some ((X-1,1,1) :: (Y+3,1,1) :: (3,2,1)
                    :: (if 1 <? c2 then [(o2,z2,c2-1)] else []) ++ r2, f)
          | [] => None
          end)
    else if (2 <=? cY) && (2 <=? Y)
    then Some ((X-1,1,1) :: (Y+3,1,1) :: (Y-1,1,1)
               :: (if 2 <? cY then [(Y,1,cY-2)] else []) ++ rest, f)
    else if (cY =? 1) && (1 <=? Y)
            && match rest with
               | (o2,z2,c2) :: _ => (z2 =? 1) && (c2 =? 1) && (1 <=? o2)
               | [] => false
               end
    then (match rest with
          | (k,_,_) :: r2 =>
              if k =? 1 then Some ((X-1,1,1) :: (Y+3,2,1) :: r2, f)
              else Some ((X-1,1,1) :: (Y+3,1,1) :: (k-1,1,1) :: r2, f)
          | [] => None
          end)
    else if (cY =? 1) && (1 <=? Y)
            && match rest with
               | (o2,z2,c2) :: _ =>
                   (z2 =? 2) && (1 <=? o2) && (o2 <=? 3) && (c2 =? 1)
               | [] => false
               end
    then (match rest with
          | (b,_,_) :: r2 =>
              if b =? 1 then Some ((X-1,1,1) :: (Y+3,3,1) :: r2, f)
              else Some ((X-1,1,1) :: (Y+3,1,1) :: (b-1,2,1) :: r2, f)
          | [] => None
          end)
    else None.
Proof.
  Transparent fire_comp. cbn [fire_comp]. Opaque fire_comp.
  destruct (Y =? 4), (Y =? 8); reflexivity.
Qed.
Lemma fc_zY2 (n : nat) (X Y cY : N) (rest : word) (f : N) :
  (Y =? 4) = false ->
  fire_comp (S n) ((X,3,1) :: (Y,2,cY) :: rest) f
  = if negb (5 <=? X) then None else
    if (Y =? 8) && (cY =? 1)
    then (match tick_target ((X-1,1,1) :: (11,2,1) :: rest) 2%nat with
          | Some j =>
              if (match wat ((X-1,1,1) :: (11,2,1) :: rest) j with
                  | Some (_,z,_) => (z =? 1)%N
                  | None => false
                  end)
              then match deliver_tick n ((X-1,1,1) :: (11,2,1) :: rest)
                                           f j true with
                   | ROk s3 f3 => Some (s3, f3)
                   | _ => None
                   end
              else None
          | None => None
          end)
    else None.
Proof.
  intros HY4.
  Transparent fire_comp. cbn [fire_comp]. Opaque fire_comp.
  rewrite HY4. destruct (Y =? 8); reflexivity.
Qed.
Lemma fc_zY3 (n : nat) (X Y cY : N) (rest : word) (f : N) :
  fire_comp (S n) ((X,3,1) :: (Y,3,cY) :: rest) f
  = if negb (5 <=? X) then None else
    if (cY =? 1) && (1 <=? Y) && (f =? 4)
    then (match rest with
          | [(o2,z2,c2)] =>
              if (o2 =? 4) && (z2 =? 2) && (1 <=? c2)
              then Some ([(X-1,1,1); (Y+2,1,1); (6,1,1); (3,2,1)]
                         ++ (if 1 <? c2 then [(4,2,c2-1)] else []), f)
              else None
          | _ => None
          end)
    else None.
Proof.
  Transparent fire_comp. cbn [fire_comp]. Opaque fire_comp.
  destruct (Y =? 4), (Y =? 8); reflexivity.
Qed.
Lemma fc_zY_dead (n : nat) (X Y zY cY : N) (rest : word) (f : N) :
  (zY =? 1) = false -> (zY =? 2) = false -> (zY =? 3) = false ->
  fire_comp (S n) ((X,3,1) :: (Y,zY,cY) :: rest) f = None.
Proof.
  intros H1 H2 H3.
  Transparent fire_comp. cbn [fire_comp]. Opaque fire_comp.
  rewrite H1, H2, H3.
  destruct (Y =? 4), (Y =? 8), (negb (5 <=? X)); reflexivity.
Qed.
End FCChain.
