Lemma retag8_route1_any (X : N) (rest : word) (f : N) (fuel j : nat)
    (s3 : word) (f3 : N) :
  (5 <= X)%N ->
  tick_target ((X-1,1,1)%N :: (11,2,1)%N :: rest) 2 = Some j ->
  (match wat ((X-1,1,1)%N :: (11,2,1)%N :: rest) j with
   | Some (_,z,_) => (z =? 1)%N
   | None => false
   end) = true ->
  deliver_tick fuel ((X-1,1,1)%N :: (11,2,1)%N :: rest) f j true
    = ROk s3 f3 ->
  exists c p q,
    FTrip c (sdec ((X,3,1)%N :: (8,2,1)%N :: rest) f) p q
    /\ wconf [] 0 ((1,S p)::q) = wconf [] 0 (sdec s3 f3).
Proof.
  intros E5 HTT HZ HDT.
  destruct fuel as [|fuel0].
  { Transparent deliver_tick.
    cbn [deliver_tick] in HDT.
    Opaque deliver_tick.
    discriminate. }
  exact (retag8_route1 X rest f fuel0 j s3 f3 E5 HTT HZ HDT).
Qed.
