Lemma fire_renew_ftrip (n : nat) : FCProp n /\ RNProp n.
Proof.
  induction n as [|n IH].
  { split.
    - intros s f s' f2 HFC.
      Transparent fire_comp. cbn in HFC. discriminate.
    - intros cols s f body f2 HPC HR.
      Transparent renew_seg. cbn in HR. discriminate. }
  destruct IH as (IHF & IHR).
  pose proof (renew_ftrip_step n IHF IHR) as RN1.
  split; [|exact RN1].
  intros s f s' f2 HFC.
    Transparent fire_comp.
    cbn [fire_comp] in HFC.
    Opaque fire_comp.
    destruct s as [|[[X zX] cX] rest]; [discriminate|].
    destruct zX as [|pz]; [destruct cX; discriminate|].
    destruct pz as [a1|a1|].
    {
      destruct a1 as [a2|a2|]; [destruct cX; discriminate|destruct cX; discriminate|].
      destruct cX as [|pc]; [discriminate|].
      destruct pc as [a3|a3|]; [discriminate|discriminate|].
      destruct rest as [|[[Y zY] cY] rest1].
      {
        destruct (negb (5 <=? X)%N) eqn:EX5; [discriminate|].
        apply negb_false_iff in EX5.
        assert (E5 : (5 <= X)%N) by (apply N.leb_le; exact EX5).
        destruct (2 <=? f)%N eqn:EF2; [|discriminate].
        assert (F2 : (2 <= f)%N) by (apply N.leb_le; exact EF2).
        injection HFC as <- <-.
