              | context [if sand_leaf ?ss && ?cc then _ else _] =>
                  revert HFC;
                  destruct (sand_leaf ss && cc) eqn:ESAND;
                  intros HFC
              end.
              { cbv beta iota in HFC. discriminate HFC. }
              match type of HFC with
              | context [match leaf_act ?a ?b with _ => _ end] =>
                  destruct (leaf_act a b) as [[s3' fi]|] eqn:ELA
              end.
              2:{
                  destruct s3 as [|g7 s3t]; [|discriminate HFC].
                  rewrite app_nil_r in EREST2 |- *.
                  destruct (5 <=? f)%N eqn:EF5.
                  { apply N.leb_le in EF5.
                    injection HFC as <- <-.
                    destruct (ren_far_tail cols2 f HCOLS2 EF5)
                      as (ci & pi & qi & HFi & EQi).
                    destruct (casc_jump_inner cols cols2
                                (cols2 ++ [((f-1)%N,1,1)%N]) seg B f 3
                                ci pi qi HCOLS EJS EB1 HFi EQi)
                      as (c3 & p3 & q3 & HF3 & EQ3).
                    exact (casc_stage _ _ _ _ _ _ _ _ _ E5 EC1 HF3 EQ3). }
                  destruct (f =? 4)%N eqn:EF4; [|discriminate HFC].
                  apply N.eqb_eq in EF4. subst f.
                  destruct (dtb4_conv cols2) as [cols2'|] eqn:EDT4.
                  { injection HFC as <- <-.
                    destruct (dtb4_ftrip cols2 cols2' HCOLS2 EDT4)
                      as (ci & pi & qi & HFi & EQi).
                    destruct (casc_jump_inner cols cols2 cols2' seg B 4 4
                                ci pi qi HCOLS EJS EB1 HFi EQi)
                      as (c3 & p3 & q3 & HF3 & EQ3).
                    exact (casc_stage _ _ _ _ _ _ _ _ _ E5 EC1 HF3 EQ3). }
                  destruct (forallb w42 cols2) eqn:EW42;
                    [|discriminate HFC].
                  destruct (lawR_seg cols B) as [seg2|] eqn:ELS;
                    [|discriminate HFC].
                  injection HFC as <- <-.
                  destruct (casc_lawR_inner cols cols2 seg2 B
                              HCOLS ELS EB1 EW42)
                    as (c3 & p3 & q3 & HF3 & EQ3).
                  exact (casc_stage _ _ _ _ _ _ _ _ _ E5 EC1 HF3 EQ3). }
              injection HFC as <- <-.
              destruct (leaf_ftrip _ _ _ _ ELA)
                as [(ci & pi & qi & HFi & EQi)
                   |(ci & pi & qi & HSi & EQi & ES5 & _)].
              { destruct (ren_lift cols2 _ _ f fi ci pi qi HCOLS2 HFi EQi)
                  as (c2 & p2 & q2 & HF2 & EQ2).
                destruct (casc_jump_inner cols _ _ _ B f fi c2 p2 q2
                            HCOLS EJS EB1 HF2 EQ2)
                  as (c3 & p3 & q3 & HF3 & EQ3).
                exact (casc_stage _ _ _ _ _ _ _ _ _ E5 EC1 HF3 EQ3). }
              rewrite ES5 in ESAND. cbn [andb] in ESAND.
              destruct (Sand_cols cols2 ci (sdec s3 f) ((1,S pi)::qi)
                          HCOLS2 HSi)
                as [(c2 & p2 & q2 & HF2 & EQ2)|ENIL].
              2:{ rewrite (expand_nil_gc0 cols2 ENIL) in ESAND.
                  discriminate. }
              assert (HF2' : FTrip c2 (sdec (cols2 ++ s3) f) p2 q2)
