              destruct (casc_jump_inner cols _ _ _ B f fi c2 p2 q2
                          HCOLS EJS EB1 HF2' EQ2')
                as (c3 & p3 & q3 & HF3 & EQ3).
              exact (casc_stage _ _ _ _ _ _ _ _ _ E5 EC1 HF3 EQ3). }
            destruct ((z5 =? 3)%N && (B =? 1)%N
                      && match rest2 with [] => true | _ => false end
                      && (f =? 4)%N && (1 <=? o5)%N) eqn:EY.
            {
              match type of HFC with
              | context [match endY_seg ?a ?b with _ => _ end] =>
                  destruct (endY_seg a b) as [seg2|] eqn:EYS
              end; [|discriminate].
              injection HFC as <- <-.
              assert (HRN : renew_seg (S n) cols
                              ((4,3,1)%N :: (o5,z5,B) :: rest2) f
                            = Some (seg2, (f-1)%N)).
              { Transparent renew_seg. cbn [renew_seg].
                Opaque renew_seg.
                rewrite E42. cbn [andb]. rewrite EY, EYS. reflexivity. }
              destruct (RN1 _ _ _ _ _ HCOLS HRN)
                as (ci & pi & qi & HFi & EQi).
              exact (casc_stage _ _ _ _ _ _ _ _ _ E5 EC1 HFi EQi). }
            rewrite leaf_act_z3 in HFC. discriminate. }
          destruct ((o4 =? 4)%N && (z4 =? 4)%N && (c4 =? 1)%N) eqn:E441.
          { apply andb_prop in E441. destruct E441 as (E441a & EC4).
            apply andb_prop in E441a. destruct E441a as (EO4 & EZ4).
            apply N.eqb_eq in EO4, EZ4, EC4. subst o4 z4 c4.
            destruct s2t as [|[[on zn] cn] t2]; [discriminate|].
            destruct ((on =? 4)%N && (zn =? 2)%N && (1 <=? cn)%N) eqn:EFOL;
