            apply andb_prop in EFOL. destruct EFOL as (EFOLa & ECN).
            apply andb_prop in EFOLa. destruct EFOLa as (EON & EZN).
            apply N.eqb_eq in EON, EZN. apply N.leb_le in ECN. subst on zn.
            match type of HFC with
            | context [match jump_seg ?a ?b with _ => _ end] =>
                destruct (jump_seg a b) as [seg2|] eqn:EJS
            end; [|discriminate].
            injection HFC as <- <-.
            destruct (casc_lcjmp_inner cols t2 seg2 cn f HCOLS EJS ECN)
              as (c3 & p3 & q3 & HF3 & EQ3).
            exact (casc_stage _ _ _ _ _ _ _ _ _ E5 EC1 HF3 EQ3). }
          match type of HFC with
          | context [match fire_comp ?a ?b ?c with _ => _ end] =>
              destruct (fire_comp a b c) as [[s2' fi]|] eqn:EFC2
          end.
          { injection HFC as <- <-.
            destruct (IHF _ _ _ _ EFC2) as (ci & pi & qi & HFi & EQi).
            destruct (ren_lift cols _ _ f fi ci pi qi HCOLS HFi EQi)
              as (c2 & p2 & q2 & HF2 & EQ2).
            exact (casc_stage _ _ _ _ _ _ _ _ _ E5 EC1 HF2 EQ2). }
          match type of HFC with
          | context [match leaf_act ?a ?b with _ => _ end] =>
              destruct (leaf_act a b) as [[s2' fi]|] eqn:ELA
          end; [|discriminate].
          injection HFC as <- <-.
          exact (casc_leaf X cY cols _ s2' f fi E5 EC1 HCOLS ELA). }
        rewrite (fc_zY2 n X Y cY rest1 f EY4) in HFC.
        destruct (negb (5 <=? X)%N) eqn:EX5c; [discriminate|].
        destruct ((Y =? 8)%N && (cY =? 1)%N) eqn:G8; [|discriminate].
        apply negb_false_iff in EX5c.
        assert (E5 : (5 <= X)%N) by (apply N.leb_le; exact EX5c).
        apply andb_prop in G8. destruct G8 as (GY8 & GCY1).
        apply N.eqb_eq in GY8. apply N.eqb_eq in GCY1. subst Y cY.
        destruct (tick_target ((X-1,1,1)%N :: (11,2,1)%N :: rest1) 2%nat)
          as [j|] eqn:HTT; [|discriminate].
        destruct (match wat ((X-1,1,1)%N :: (11,2,1)%N :: rest1) j with
                  | Some (_,z,_) => (z =? 1)%N
                  | None => false
                  end) eqn:HZ; [|discriminate].
        destruct (deliver_tick n ((X-1,1,1)%N :: (11,2,1)%N :: rest1)
                                    f j true)
          as [s3 f3| |] eqn:HDT; [|discriminate|discriminate].
        injection HFC as <- <-.
        exact (retag8_route1_any X rest1 f n j _ _ E5 HTT HZ HDT). }
      destruct (zY =? 3)%N eqn:EZ3.
      {
        apply N.eqb_eq in EZ3. subst zY.
        rewrite fc_zY3 in HFC.
        destruct (negb (5 <=? X)%N) eqn:EX5d; [discriminate|].
        destruct ((cY =? 1)%N && (1 <=? Y)%N && (f =? 4)%N) eqn:GC4;
          [|discriminate].
        apply andb_prop in GC4. destruct GC4 as (GC4a & GF4).
        apply andb_prop in GC4a. destruct GC4a as (GCY & GY1).
        apply N.eqb_eq in GCY. apply N.leb_le in GY1. apply N.eqb_eq in GF4.
        subst cY f.
        apply negb_false_iff in EX5d.
        assert (E5 : (5 <= X)%N) by (apply N.leb_le; exact EX5d).
        destruct rest1 as [|[[o2 z2] c2] r2]; [discriminate|].
        destruct r2 as [|g3 r3]; [|discriminate].
        destruct ((o2 =? 4)%N && (z2 =? 2)%N && (1 <=? c2)%N) eqn:GL;
          [|discriminate].
        apply andb_prop in GL. destruct GL as (GLa & GC2).
        apply andb_prop in GLa. destruct GLa as (GO2 & GZ2).
        apply N.eqb_eq in GO2. apply N.eqb_eq in GZ2. subst o2 z2.
        apply N.leb_le in GC2.
        injection HFC as <- <-.
        assert (HK : exists cc p q,
                   FTrip cc (sdec ((X,3,1)%N :: (Y,3,1)%N :: [(4,2,c2)%N]) 4)
                         p q
                   /\ wconf [] 0 ((1,S p)::q)
                      = wconf [] 0
                          (sdec ([(X-1,1,1)%N; (Y+2,1,1)%N; (6,1,1)%N;
                                  (3,2,1)%N]
                                 ++ (if (1 <? c2)%N then [(4,2,c2-1)%N]
                                     else [])) 4)).
        { assert (HL : sdec ((X,3,1)%N :: (Y,3,1)%N :: [(4,2,c2)%N]) 4
                     = (1,N.to_nat X)::(0,3%nat)::(1,N.to_nat Y)::(0,3%nat)
                         :: uword (repeat 2%nat (N.to_nat c2)) [(1,4%nat)]).
          { rewrite uword2_pair.
            unfold sdec. cbn [map gdecode expand app frun].
            change (N.to_nat 3) with 3%nat. change (N.to_nat 1) with 1%nat.
            change (N.to_nat 4) with 4%nat. change (N.to_nat 2) with 2%nat.
            cbn [pair_runs app]. rewrite ?app_nil_r. reflexivity. }
          assert (HR : sdec ([(X-1,1,1)%N; (Y+2,1,1)%N; (6,1,1)%N; (3,2,1)%N]
                             ++ (if (1 <? c2)%N then [(4,2,c2-1)%N] else [])) 4
                     = (1,N.to_nat (X-1)%N)::(0,1%nat)::(1,N.to_nat (Y+2)%N)
                         ::(0,1%nat)::(1,6%nat)::(0,1%nat)::(1,3%nat)::(0,2%nat)
                         :: uword (repeat 2%nat (N.to_nat (c2-1)%N))
                              [(1,4%nat)]).
          { rewrite uword2_pair.
            rewrite sdec_app.
            cbn [map gdecode expand app].
            change (N.to_nat 1) with 1%nat. change (N.to_nat 6) with 6%nat.
            change (N.to_nat 3) with 3%nat. change (N.to_nat 2) with 2%nat.
            cbn [pair_runs app].
            destruct (1 <? c2)%N eqn:EP.
            - unfold sdec. cbn [map gdecode expand app frun].
              change (N.to_nat 4) with 4%nat. change (N.to_nat 2) with 2%nat.
              rewrite ?app_nil_r. reflexivity.
            - apply N.ltb_ge in EP.
              replace (c2 - 1)%N with 0%N by lia.
