              cbn [pair_runs app]. reflexivity. }
          exists (3 * N.to_nat (c2 - 1)%N + 13)%nat,
                 (3 + N.to_nat (X - 5)%N)%nat,
            ((0,1%nat)::(1,(3 + N.to_nat (Y - 1)%N)%nat)::(0,1%nat)::(1,6%nat)
               ::(0,1%nat)::(1,3%nat)::(0,2%nat)
               :: uword (repeat 2%nat (N.to_nat (c2-1)%N)) [(1,4%nat)]).
          rewrite HL, HR.
          rewrite (NtoS5 X E5), (NtoS1y Y GY1), (NtoSc c2 GC2).
          rewrite (NtoS4 X E5), (NtoS3y Y GY1).
          split; [exact (FTrip_armC (N.to_nat (X - 5)%N) (N.to_nat (Y - 1)%N)
                           (N.to_nat (c2 - 1)%N))
                 |reflexivity]. }
        exact HK. }
      rewrite (fc_zY_dead n X Y zY cY rest1 f EZ1 EZ2 EZ3) in HFC.
      discriminate. }
    {
      killm HFC. }
    killm HFC.
Qed.
