Lemma halts_cong (u v : wside) :
  wconf [] 0 u = wconf [] 0 v ->
  halts tmB (wconf [] 0 v) -> halts tmB (wconf [] 0 u).
Proof. intros E H. rewrite E. exact H. Qed.
Lemma kernel_out (J : N) (pr : word) (X : wside) :
  forallb is_col pr = true ->
  uword (0%nat :: walls_of ((2,2,J)%N :: pr)) X
  = expand (map gdecode ((2,2,(J+1))%N :: pr)) ++ X.
Proof.
  intros HPC.
  assert (HPC1 : forallb is_col ((2,2,J)%N :: pr) = true).
  { cbn [forallb]. rewrite HPC.
    unfold is_col. cbn [gZ gO]. reflexivity. }
  cbn [uword].
  rewrite <- (uword_walls _ X HPC1).
  cbn [map gdecode expand].
  assert (EJ1 : N.to_nat (J + 1)%N = S (N.to_nat J))
    by (rewrite N2Nat.inj_add; change (N.to_nat 1) with 1%nat; lia).
  rewrite EJ1.
  change (N.to_nat 2) with 2%nat.
  cbn [pair_runs].
  rewrite <- !app_assoc.
  reflexivity.
Qed.
Lemma kernel_transfer (J : N) (pr : word) (Win : wside)
    (c p : nat) (q : wside) :
  forallb is_col pr = true ->
  (1 <= J)%N ->
  FTrip c Win p q ->
  halts tmB (wconf [] 0
    (uword (0%nat :: walls_of ((2,2,J)%N :: pr)) ((1,S p)::q))) ->
  halts tmB (wconf [] 0
    (expand (map gdecode ((2,2,J)%N :: pr)) ++ Win)).
Proof.
  intros HPC HJ HFT Hh.
  destruct (to_nat_ge1 J HJ) as [j0 EJ].
  assert (HPC1 : forallb is_col ((2,2,J)%N :: pr) = true).
  { cbn [forallb]. rewrite HPC.
    unfold is_col. cbn [gZ gO]. reflexivity. }
  assert (EWIN : walls_of ((2,2,J)%N :: pr)
                 = 0%nat :: (repeat 0%nat j0 ++ walls_of pr)).
  { rewrite walls_of_cons.
    rewrite EJ.
    change (N.to_nat 2 - 2)%nat with 0%nat.
    cbn [repeat app].
    reflexivity. }
  pose proof (FTrip_kernel_all (repeat 0%nat j0 ++ walls_of pr)
                c _ p q HFT) as HK.
  set (FUELK := (3 * List.length (repeat 0%nat j0 ++ walls_of pr)
                 + c + 5)%nat) in HK.
  assert (ES : FUELK = S (Nat.pred FUELK)) by (unfold FUELK; lia).
  rewrite ES in HK.
  apply wstep_of in HK.
  rewrite (uword_walls _ _ HPC1).
  rewrite EWIN.
  assert (Hmid : halts tmB (wconf' ([], 0,
    uword (0%nat :: 0%nat :: (repeat 0%nat j0 ++ walls_of pr))
      ((1,S p)::q)))).
  { cbn [wconf'].
    rewrite EWIN in Hh.
    exact Hh. }
  exact (wstep_halts_pull _ _ HK Hmid).
Qed.
Lemma fire_comp_sound (n : nat) (J : N) (pr sfx sfx' : word)
    (f f2 : N) :
  fire_comp n sfx f = Some (sfx', f2) ->
  forallb is_col pr = true ->
  (1 <= J)%N ->
  (match last1 pr with
   | Some g => ((3 <=? gO g)%N && (1 <=? gC g)%N)%bool
   | None => false
   end) = true ->
  halts tmB (wconf [] 0 (sdec (((2,2,(J+1))%N :: pr) ++ sfx') f2)) ->
  halts tmB (wconf [] 0 (sdec (((2,2,J)%N :: pr) ++ sfx) f)).
Proof.
  intros HFC HPC HJ HL Hh.
  destruct (fire_comp_ftrip n sfx f sfx' f2 HFC) as (c & p & q & HFT & EQo).
  rewrite sdec_app.
  apply (kernel_transfer J pr _ c p q HPC HJ HFT).
  assert (HPC2 : forallb is_col ((2,2,(J+1))%N :: pr) = true).
  { cbn [forallb]. rewrite HPC.
    unfold is_col. cbn [gZ gO]. reflexivity. }
  assert (EWJ : walls_of ((2,2,(J+1))%N :: pr)
                = 0%nat :: walls_of ((2,2,J)%N :: pr)).
  { rewrite !walls_of_cons.
    assert (EJ1 : N.to_nat (J + 1)%N = S (N.to_nat J))
      by (rewrite N2Nat.inj_add;
          change (N.to_nat 1) with 1%nat; lia).
    rewrite EJ1.
    change (N.to_nat 2 - 2)%nat with 0%nat.
    cbn [repeat app].
    reflexivity. }
  rewrite sdec_app in Hh.
  rewrite (uword_walls _ _ HPC2) in Hh.
  rewrite EWJ in Hh.
  rewrite (wconf_uword_cong _ _ _ EQo).
  exact Hh.
Qed.
Lemma std_transfer (J : N) (pr sfx sfx' : word) (f f2 : N)
    (c p : nat) (q : wside) :
  FTrip c (sdec sfx f) p q ->
  wconf [] 0 ((1, S p) :: q) = wconf [] 0 (sdec sfx' f2) ->
  forallb is_col pr = true ->
  (1 <= J)%N ->
  halts tmB (wconf [] 0 (sdec (((2,2,(J+1))%N :: pr) ++ sfx') f2)) ->
  halts tmB (wconf [] 0 (sdec (((2,2,J)%N :: pr) ++ sfx) f)).
Proof.
  intros HFT EQo HPC HJ Hh.
  rewrite sdec_app.
  apply (kernel_transfer J pr _ c p q HPC HJ HFT).
  assert (HPC2 : forallb is_col ((2,2,(J+1))%N :: pr) = true).
  { cbn [forallb]. rewrite HPC.
    unfold is_col. cbn [gZ gO]. reflexivity. }
  assert (EWJ : walls_of ((2,2,(J+1))%N :: pr)
                = 0%nat :: walls_of ((2,2,J)%N :: pr)).
  { rewrite !walls_of_cons.
    assert (EJ1 : N.to_nat (J + 1)%N = S (N.to_nat J))
      by (rewrite N2Nat.inj_add; change (N.to_nat 1) with 1%nat; lia).
    rewrite EJ1.
    change (N.to_nat 2 - 2)%nat with 0%nat.
    cbn [repeat app]. reflexivity. }
  rewrite sdec_app in Hh.
  rewrite (uword_walls _ _ HPC2) in Hh.
  rewrite EWJ in Hh.
  rewrite (wconf_uword_cong _ _ _ EQo).
  exact Hh.
Qed.
