Lemma dxfar_invX (X' : nat) (ms : list nat) :
  wrun 2 (vstackC ms []) 0 [(1,(5 + X')%nat);(0,2%nat);(1,4%nat)]
  = Some ((0,1%nat)::(1,2%nat)::(0,1%nat)::(1,2%nat)
            ::(0,1%nat)::(1,(3 + X')%nat)::(0,1%nat)::(1,2%nat)
            :: vstackC ms [], 0, []).
Proof.
  destruct ms as [|[|m'] t]; destruct X' as [|d]; gker2.
Qed.
Lemma dxfar_mintvX (X' : nat) (ms : list nat) :
  wrun 6 ((0,1%nat)::(1,2%nat)::(0,1%nat)::(1,2%nat)
            ::(0,1%nat)::(1,(3 + X')%nat)::(0,1%nat)::(1,2%nat)
            :: vstackC ms [(0,2%nat);(1,2%nat)]) 0 []
  = Some (vstackC ms [(0,2%nat);(1,2%nat)], 1,
          (0,1%nat)::(1,(4 + X')%nat)::(0,1%nat)::(1,3%nat)
            ::(0,2%nat)::[(1,4%nat)]).
Proof.
  destruct ms as [|[|m'] t]; destruct X' as [|d]; gker2.
Qed.
Lemma kernel_x169gX (X' : nat) (ms : list nat) :
  wrun (3 * S (List.length ms) + 9)%nat [] 0
    (uword (0%nat :: ms) ((1,(5 + X')%nat)::(0,2%nat)::[(1,4%nat)]))
  = Some ([], 0,
      uword (0%nat :: 0%nat :: ms)
            ((1,(4 + X')%nat)::(0,1%nat)::(1,3%nat)::(0,2%nat)::[(1,4%nat)])).
Proof.
  replace (3 * S (List.length ms) + 9)%nat
    with (List.length (0%nat :: ms)
          + (2 + (6 + (2 * List.length (rev (0%nat :: ms)) + 1))))%nat
    by (rewrite length_rev; cbn [List.length]; lia).
  rewrite wrun_add, wcross_mixed.
  lazy beta iota.
  rewrite (vstack_vstackC _ [] I).
  erewrite wrun_split by apply (dxfar_invX X').
  cbn [rev].
  rewrite vstackC_app.
  cbn [vstackC vpairC].
  erewrite wrun_split by apply (dxfar_mintvX X').
  change ([(0,2%nat);(1,2%nat)]) with (vstackC [0%nat] ([] : wside)).
  rewrite <- vstackC_app.
  change (4 + X')%nat with (S (3 + X')%nat).
  replace (2 * List.length (rev (0%nat :: ms)) + 1)%nat
    with (2 * List.length (rev ms ++ [0%nat]) + 1)%nat
    by (cbn [rev]; reflexivity).
  erewrite wback0_run.
  f_equal. f_equal.
  rewrite emitI_uword.
  rewrite rev_app_distr, rev_involutive.
  cbn [app uword].
  reflexivity.
Qed.
Lemma kernel_x169gX_step (X' : nat) (ms : list nat) :
  wstep ([], 0, uword (0%nat :: ms)
                  ((1,(5 + X')%nat)::(0,2%nat)::[(1,4%nat)]))
        ([], 0, uword (0%nat :: 0%nat :: ms)
                  ((1,(4 + X')%nat)::(0,1%nat)::(1,3%nat)
                     ::(0,2%nat)::[(1,4%nat)])).
Proof.
  apply (wstep_of (3 * S (List.length ms) + 8)%nat).
  replace (S (3 * S (List.length ms) + 8))%nat
    with (3 * S (List.length ms) + 9)%nat by lia.
  apply kernel_x169gX.
Qed.
Lemma bridge_far169_pg (X c_0 : N) (p' : list bgroup) :
  (5 <= X)%N -> zpre p' -> (1 <= c_0)%N ->
  wstep ([], 0, bdecode (((2,2,c_0)%N :: p') ++ [(X,2,1)]%N, 4%N))
        ([], 0, bdecode ((2,2,1)%N :: ((2,2,c_0)%N :: p')
                           ++ [((X-1)%N,1,1); (3,2,1)]%N, 4%N)).
Proof.
  intros E5 HP HC0.
  destruct (to_nat_ge1 c_0 HC0) as [c0' E0].
  pose proof (kernel_x169gX_step (N.to_nat (X - 5)%N)
                (repeat 0%nat c0' ++ gms p')) as KE.
  assert (E1 : bdecode (((2,2,c_0)%N :: p') ++ [(X,2,1)]%N, 4%N)
             = uword (0%nat :: repeat 0%nat c0' ++ gms p')
                 ((1,(5 + N.to_nat (X - 5)%N)%nat)::(0,2%nat)::[(1,4%nat)])).
  { rewrite bdecode_pre;
      rewrite <- (gms_col_head _ _ _ E0);
      rewrite (uword_gms _ _ (zpre_cons_col _ _ HP));
      f_equal;
      unfold bdecode;
      cbn [map gdecode expand];
      rewrite ?uword_repeat_w;
      rewrite <- (NtoS5 X E5);
      cbn [frun];
      repeat (change (N.to_nat 4) with 4%nat
           || change (N.to_nat 3) with 3%nat
           || change (N.to_nat 2) with 2%nat
           || change (N.to_nat 1) with 1%nat);
      cbn [pair_runs];
      rewrite <- ?app_assoc, ?app_nil_r;
      cbn [app];
      reflexivity. }
  assert (E2 : bdecode ((2,2,1)%N :: ((2,2,c_0)%N :: p')
                          ++ [((X-1)%N,1,1); (3,2,1)]%N, 4%N)
             = uword (0%nat :: 0%nat :: repeat 0%nat c0' ++ gms p')
                 ((1,(4 + N.to_nat (X - 5)%N)%nat)::(0,1%nat)::(1,3%nat)
                    ::(0,2%nat)::[(1,4%nat)])).
  { assert (EG : gms ((2,2,1)%N :: (2,2,c_0)%N :: p')
               = 0%nat :: 0%nat :: repeat 0%nat c0' ++ gms p').
    { cbn [gms];
        change ((N.to_nat 2 - 2))%nat with 0%nat;
        change (N.to_nat 1) with 1%nat;
        rewrite E0; reflexivity. }
    change ((2,2,1)%N :: ((2,2,c_0)%N :: p')
              ++ [((X-1)%N,1,1); (3,2,1)]%N)
      with (((2,2,1)%N :: (2,2,c_0)%N :: p')
              ++ [((X-1)%N,1,1); (3,2,1)]%N);
      rewrite bdecode_pre;
      rewrite <- EG;
      rewrite (uword_gms _ _ (zpre_cons_col _ _ (zpre_cons_col _ _ HP)));
      f_equal;
      unfold bdecode;
      cbn [map gdecode expand];
      rewrite ?uword_repeat_w;
      rewrite <- (NtoS4 X E5);
      cbn [frun];
      repeat (change (N.to_nat 4) with 4%nat
           || change (N.to_nat 3) with 3%nat
           || change (N.to_nat 2) with 2%nat
           || change (N.to_nat 1) with 1%nat);
      cbn [pair_runs];
      rewrite <- ?app_assoc, ?app_nil_r;
      cbn [app];
      reflexivity. }
  rewrite E1, E2. exact KE.
Qed.
Lemma leaf_act_sound (p s : word) (f : N) (s' : word) (f2 : N) :
  forallb is_col p = true ->
  cmf_prefix_ok p s ->
  leaf_act s f = Some (s', f2) ->
  halts tmB (wconf [] 0 (sdecode ((2,2,1)%N :: p ++ s') f2)) ->
  halts tmB (wconf [] 0 (sdecode (p ++ s) f)).
Proof.
  intros HP HPS HLA Hh.
  destruct s as [|[[X zX] cX] rest].
  { Transparent leaf_act. cbn in HLA. discriminate. }
  destruct ((5 <=? X)%N && (zX =? 2)%N) eqn:ECMF.
  {
    change (sdecode ((2,2,1)%N :: p ++ s') f2)
      with (sdec ((2,2,1)%N :: p ++ s') f2) in Hh.
    change (sdecode (p ++ ((X,zX,cX)%N :: rest)) f)
      with (sdec (p ++ ((X,zX,cX)%N :: rest)) f).
    apply andb_prop in ECMF. destruct ECMF as (E5b & EZ2b).
    apply N.leb_le in E5b. apply N.eqb_eq in EZ2b. subst zX.
    cbn in HPS. specialize (HPS E5b eq_refl).
    destruct p as [|[[o0 z0] c_0] p']; [contradiction|].
    destruct HPS as (Eo0 & Ez0 & HC0). subst o0 z0.
    assert (HP' : forallb is_col p' = true).
    { cbn [forallb] in HP. apply andb_prop in HP. exact (proj2 HP). }
    destruct (leaf_ftrip _ f s' f2 HLA)
      as [(c & pp & q & HFT & EQo) | (c & pp & q & HS & EQo & HSL & HF4)].
    - rewrite sdec_app.
      apply (kernel_transfer c_0 p' _ c pp q HP' HC0 HFT).
      assert (HPC2 : forallb is_col ((2,2,1)%N :: (2,2,c_0)%N :: p')
                     = true).
      { cbn [forallb]. rewrite HP'.
        unfold is_col. cbn [gZ gO]. reflexivity. }
      assert (EW1 : walls_of ((2,2,1)%N :: (2,2,c_0)%N :: p')
                    = 0%nat :: walls_of ((2,2,c_0)%N :: p')).
      { rewrite (walls_of_cons 2 2 1). change (N.to_nat 2 - 2)%nat with 0%nat.
        change (N.to_nat 1) with 1%nat. cbn [repeat app]. reflexivity. }
      change ((2,2,1)%N :: ((2,2,c_0)%N :: p') ++ s')
        with (((2,2,1)%N :: (2,2,c_0)%N :: p') ++ s') in Hh.
      rewrite sdec_app in Hh.
      rewrite (uword_walls _ _ HPC2) in Hh.
      rewrite EW1 in Hh.
      rewrite (wconf_uword_cong _ _ _ EQo).
      exact Hh.
    -
      subst f.
      unfold sand_leaf in HSL.
      destruct cX as [|pcx]; [cbn in HSL; discriminate HSL|].
      destruct pcx as [pcx'|pcx'|];
        [cbn in HSL; discriminate HSL|cbn in HSL; discriminate HSL|].
      destruct rest as [|g rest']; [|cbn in HSL; discriminate HSL].
      cbn in HSL.
      Transparent leaf_act. cbn [leaf_act] in HLA.
      Opaque leaf_act.
      apply andb_prop in HSL. destruct HSL as (HSLa & H12).
      apply andb_prop in HSLa. destruct HSLa as (_ & H8).
      assert (E5t : (5 <=? X)%N = true) by (apply N.leb_le; exact E5b).
      rewrite E5t, H8, H12 in HLA. cbn in HLA.
      injection HLA as <- <-.
      assert (Hmid : halts tmB (wconf' ([], 0,
        bdecode ((2,2,1)%N :: ((2,2,c_0)%N :: p')
                   ++ [((X-1)%N,1,1); (3,2,1)]%N, 4%N)))).
      { cbn [wconf']. exact Hh. }
      exact (wstep_halts_pull _ _
               (bridge_far169_pg X c_0 p' E5b (zpre_of_forallb p' HP') HC0)
               Hmid). }
  Transparent leaf_act.
  cbn [leaf_act] in HLA.
  Opaque leaf_act.
  destruct zX as [|pz]; [destruct cX; discriminate|].
  destruct pz as [pz1|pz1|].
  {   destruct cX; discriminate. }
  {
    destruct pz1 as [q'|q'|];
      [destruct cX; discriminate|destruct cX; discriminate|].
    destruct cX as [|pc]; [discriminate|].
    destruct pc as [pc'|pc'|]; [discriminate|discriminate|].
    assert (E5f : (5 <=? X)%N = false).
    { destruct (5 <=? X)%N; [cbn in ECMF; discriminate|reflexivity]. }
    rewrite E5f in HLA. cbn in HLA. discriminate. }
  destruct ((2 <=? cX)%N) eqn:EC2.
  {
    destruct ((2 <=? X)%N) eqn:EA2; [|discriminate].
    apply N.leb_le in EC2. apply N.leb_le in EA2.
    injection HLA as <- <-.
    assert (Hmid : halts tmB (wconf' ([], 0,
      bdecode ((2,2,1)%N :: p
        ++ ((X,1,1) :: ((X-1),1,1) :: (X,1,(cX-2)) :: rest)%N, f)))).
    { cbn [wconf'].
      destruct ((2 <? cX)%N) eqn:EC3.
      - exact Hh.
      - apply N.ltb_ge in EC3.
        assert (EQZ : sdecode ((2,2,1)%N :: p
                        ++ ((X,1,1) :: ((X-1),1,1) :: (X,1,(cX-2)) :: rest)%N) f
                    = sdecode ((2,2,1)%N :: p
                        ++ ((X,1,1) :: ((X-1),1,1) :: rest)%N) f).
        { change ((2,2,1)%N :: p ++ ?R) with (((2,2,1)%N :: p) ++ R).
          apply sdecode_app_ctx.
          change (((X,1,1) :: ((X-1),1,1) :: ?R)%N)
            with ([(X,1,1); ((X-1),1,1)]%N ++ R).
          apply sdecode_app_ctx.
          replace ((cX - 2)%N) with 0%N by lia.
          apply sdecode_drop0. }
        cbn [app] in Hh.
        rewrite <- EQZ in Hh.
        exact Hh. }
    exact (wstep_halts_pull _ _
             (bridge_split_p p X cX rest f
                (zpre_of_forallb p HP) EA2 EC2) Hmid). }
  destruct (negb (cX =? 1)%N || negb (2 <=? X)%N) eqn:ENG; [discriminate|].
  apply orb_false_iff in ENG. destruct ENG as (EC1 & EA1).
  apply negb_false_iff in EC1. apply negb_false_iff in EA1.
  apply N.eqb_eq in EC1. apply N.leb_le in EA1. subst cX.
  destruct rest as [|[[B zb] cb] t2].
  {
    destruct ((2 <=? f)%N) eqn:EF2.
    { apply N.leb_le in EF2.
      injection HLA as <- <-.
      assert (Hmid : halts tmB (wconf' ([], 0,
        bdecode ((2,2,1)%N :: p ++ [(X,1,1)%N], (f - 1)%N)))).
      { cbn [wconf']. exact Hh. }
      exact (wstep_halts_pull _ _
               (bridge_fartick_p p X f
                  (zpre_of_forallb p HP) EA1 EF2) Hmid). }
    destruct ((f =? 1)%N) eqn:EF1; [|discriminate].
    apply N.eqb_eq in EF1. subst f.
    injection HLA as <- <-.
    rewrite app_nil_r in Hh.
    apply (harvest_branch_sound p X HP EA1).
    exact Hh. }
  destruct ((zb =? 2)%N && negb (B =? 8)%N
            && (negb (B =? 4)%N
                || ((cb =? 1)%N
                    && match t2 with
                       | (o2,z2,_) :: _ =>
                           negb (((o2 =? 4)%N || (o2 =? 8)%N) && (z2 =? 2)%N)
                       | [] => true
                       end))) eqn:EOB.
  {
    apply andb_prop in EOB. destruct EOB as (EOB & _).
    apply andb_prop in EOB. destruct EOB as (EZB & _).
    apply N.eqb_eq in EZB. subst zb.
    destruct ((B =? 5)%N && (cb =? 1)%N
              && match t2 with
                 | (o2,z2,_) :: _ => (o2 =? 4)%N && (z2 =? 2)%N
                 | [] => false
                 end) eqn:EAB.
    {
      apply andb_prop in EAB. destruct EAB as (EAB & ET2).
      apply andb_prop in EAB. destruct EAB as (EB5 & EC1b).
      apply N.eqb_eq in EB5. apply N.eqb_eq in EC1b. subst B cb.
      destruct t2 as [|[[o2 z2] c2] t3]; [discriminate|].
      apply andb_prop in ET2. destruct ET2 as (EO2 & EZ2).
      apply N.eqb_eq in EO2. apply N.eqb_eq in EZ2. subst o2 z2.
      injection HLA as <- <-.
      assert (Hmid : halts tmB (wconf' ([], 0,
        bdecode ((2,2,1)%N :: p ++ ((X,1,1) :: (4,2,(c2+1)%N) :: t3)%N, f)))).
      { cbn [wconf']. exact Hh. }
      exact (wstep_halts_pull _ _
               (absorb_branch_sound p X c2 t3 f HP EA1) Hmid). }
    destruct ((B =? 1)%N) eqn:EB1.
    {
      apply N.eqb_eq in EB1. subst B.
      destruct ((cb =? 1)%N) eqn:EC1b; [|discriminate].
      apply N.eqb_eq in EC1b. subst cb.
      injection HLA as <- <-.
      assert (Hmid : halts tmB (wconf' ([], 0,
        bdecode ((2,2,1)%N :: p ++ ((X,(2+1)%N,1) :: t2)%N, f)))).
      { cbn [wconf'].
        replace ((2+1)%N) with 3%N by lia.
        exact Hh. }
      exact (wstep_halts_pull _ _
               (bridge_merge_p p X 2 t2 f
                  (zpre_of_forallb p HP) EA1 ltac:(lia)) Hmid). }
    destruct ((cb =? 1)%N && (2 <=? B)%N) eqn:ETK; [|discriminate].
    apply andb_prop in ETK. destruct ETK as (EC1b & EB2b).
    apply N.eqb_eq in EC1b. apply N.leb_le in EB2b. subst cb.
    injection HLA as <- <-.
    assert (Hmid : halts tmB (wconf' ([], 0,
      bdecode ((2,2,1)%N :: p ++ ((X,1,1) :: ((B-1)%N,2,1) :: t2)%N, f)))).
    { cbn [wconf']. exact Hh. }
    exact (wstep_halts_pull _ _
             (bridge_tick_p p X B 2 t2 f
                (zpre_of_forallb p HP) EA1 EB2b ltac:(lia)) Hmid). }
  destruct ((B =? 8)%N && (zb =? 2)%N && (cb =? 1)%N) eqn:ECAP.
  {
    apply andb_prop in ECAP. destruct ECAP as (ECAP & EC1b).
    apply andb_prop in ECAP. destruct ECAP as (EB8 & EZB).
    apply N.eqb_eq in EB8. apply N.eqb_eq in EZB.
    apply N.eqb_eq in EC1b. subst B zb cb.
    injection HLA as <- <-.
    assert (Hmid : halts tmB (wconf' ([], 0,
      bdecode ((2,2,1)%N :: p ++ ((X,1,1) :: ((8-1)%N,2,1) :: t2)%N, f)))).
    { cbn [wconf']. exact Hh. }
    exact (wstep_halts_pull _ _
             (bridge_tick_p p X 8 2 t2 f
                (zpre_of_forallb p HP) EA1 ltac:(lia) ltac:(lia)) Hmid). }
  destruct ((B =? 4)%N && (zb =? 2)%N) eqn:ERSP.
  {
    apply andb_prop in ERSP. destruct ERSP as (EB4 & EZB).
    apply N.eqb_eq in EB4. apply N.eqb_eq in EZB. subst B zb.
    destruct ((cb =? 1)%N) eqn:EC1b.
    { apply N.eqb_eq in EC1b. subst cb.
      injection HLA as <- <-.
      assert (Hmid : halts tmB (wconf' ([], 0,
        bdecode ((2,2,1)%N :: p ++ ((X,1,1) :: ((4-1)%N,2,1) :: t2)%N, f)))).
      { cbn [wconf']. exact Hh. }
      exact (wstep_halts_pull _ _
               (bridge_tick_p p X 4 2 t2 f
                  (zpre_of_forallb p HP) EA1 ltac:(lia) ltac:(lia)) Hmid). }
    destruct ((2 <=? cb)%N) eqn:EC2b; [|discriminate].
    apply N.leb_le in EC2b.
    injection HLA as <- <-.
    assert (HC2 : (2 <= cb)%N) by exact EC2b.
    assert (Hmid : halts tmB (wconf' ([], 0,
      bdecode ((2,2,1)%N :: p
        ++ ((X,1,1) :: ((4-1)%N,2,1) :: (4,2,(cb-1)%N) :: t2)%N, f)))).
    { cbn [wconf']. exact Hh. }
    exact (wstep_halts_pull _ _
             (bridge_tick_split_p p X 4 2 cb t2 f
                (zpre_of_forallb p HP) EA1 ltac:(lia) ltac:(lia) HC2) Hmid). }
  destruct ((zb =? 1)%N) eqn:EZB1.
  { apply N.eqb_eq in EZB1. subst zb.
    destruct ((2 <=? cb)%N) eqn:ECB2.
    {
      apply N.leb_le in ECB2.
      destruct ((2 <=? B)%N) eqn:EB2b; [|discriminate].
      apply N.leb_le in EB2b.
      injection HLA as <- <-.
      assert (Hmid : halts tmB (wconf' ([], 0,
        bdecode ((2,2,1)%N :: p
          ++ ((X,1,1) :: ((B-1)%N,1,1) :: (B,1,(cb-1)%N) :: t2)%N, f)))).
      { cbn [wconf']. exact Hh. }
      exact (wstep_halts_pull _ _
               (bridge_tick_split_p p X B 1 cb t2 f
                  (zpre_of_forallb p HP) EA1 EB2b ltac:(lia) ECB2) Hmid). }
    destruct ((B =? 1)%N) eqn:EB1.
    {
      apply N.eqb_eq in EB1. subst B.
      destruct ((cb =? 1)%N) eqn:EC1c; [|discriminate].
      apply N.eqb_eq in EC1c. subst cb.
      injection HLA as <- <-.
      assert (Hmid : halts tmB (wconf' ([], 0,
        bdecode ((2,2,1)%N :: p ++ ((X,(1+1)%N,1) :: t2)%N, f)))).
      { cbn [wconf'].
        replace ((1+1)%N) with 2%N by lia.
        exact Hh. }
      exact (wstep_halts_pull _ _
               (bridge_merge_p p X 1 t2 f
                  (zpre_of_forallb p HP) EA1 ltac:(lia)) Hmid). }
    destruct ((cb =? 1)%N && (2 <=? B)%N) eqn:EG132; [|discriminate].
    apply andb_prop in EG132. destruct EG132 as (EC1b & EB2b).
    apply N.eqb_eq in EC1b. apply N.leb_le in EB2b. subst cb.
    injection HLA as <- <-.
    assert (Hmid : halts tmB (wconf' ([], 0,
      bdecode ((2,2,1)%N :: p ++ ((X,1,1) :: ((B-1)%N,1,1) :: t2)%N, f)))).
    { cbn [wconf']. exact Hh. }
    exact (wstep_halts_pull _ _
             (bridge_tick_p p X B 1 t2 f
                (zpre_of_forallb p HP) EA1 EB2b ltac:(lia)) Hmid). }
  destruct ((3 <=? zb)%N && (cb =? 1)%N) eqn:EZ3F; [|discriminate].
  apply andb_prop in EZ3F. destruct EZ3F as (EZB3 & EC1b).
  apply N.leb_le in EZB3. apply N.eqb_eq in EC1b. subst cb.
  destruct ((B =? 1)%N) eqn:EB1.
  {
    apply N.eqb_eq in EB1. subst B.
    injection HLA as <- <-.
    assert (Hmid : halts tmB (wconf' ([], 0,
      bdecode ((2,2,1)%N :: p ++ ((X,(zb+1)%N,1) :: t2)%N, f)))).
    { cbn [wconf']. exact Hh. }
    exact (wstep_halts_pull _ _
             (bridge_merge_p p X zb t2 f
                (zpre_of_forallb p HP) EA1 ltac:(lia)) Hmid). }
  destruct ((2 <=? B)%N) eqn:EB2b; [|discriminate].
  apply N.leb_le in EB2b.
  injection HLA as <- <-.
  assert (Hmid : halts tmB (wconf' ([], 0,
    bdecode ((2,2,1)%N :: p ++ ((X,1,1) :: ((B-1)%N,zb,1) :: t2)%N, f)))).
  { cbn [wconf']. exact Hh. }
  exact (wstep_halts_pull _ _
           (bridge_tick_p p X B zb t2 f
              (zpre_of_forallb p HP) EA1 EB2b ltac:(lia)) Hmid).
Qed.
