Lemma NtoS (x : N) : (1 <= x)%N -> N.to_nat x = S (N.to_nat (x - 1)%N).
Proof. intros H. rewrite N2Nat.inj_sub. change (N.to_nat 1) with 1%nat. lia. Qed.
Lemma NtoSS (x : N) : (1 <= x)%N -> N.to_nat (x + 1)%N = S (S (N.to_nat (x - 1)%N)).
Proof.
  intros H. rewrite N2Nat.inj_add, N2Nat.inj_sub.
  change (N.to_nat 1) with 1%nat. lia.
Qed.
Lemma NtoS3 (x : N) : (3 <= x)%N -> N.to_nat x = (N.to_nat (x-3)%N + 3)%nat.
Proof.
  intros H. rewrite N2Nat.inj_sub. change (N.to_nat 3) with 3%nat. lia.
Qed.
Lemma NtoS2 (x : N) :
  (3 <= x)%N -> N.to_nat (x-2)%N = S (N.to_nat (x-3)%N).
Proof.
  intros H. rewrite !N2Nat.inj_sub.
  change (N.to_nat 2) with 2%nat. change (N.to_nat 3) with 3%nat. lia.
Qed.
