Lemma pair_runs'_eq (o z c : nat) : pair_runs' o z c = pair_runs o z c.
Proof. induction c as [|c IH]; cbn; [reflexivity|rewrite IH; reflexivity]. Qed.
Lemma Front_uword_zeros (k : nat) (r : wside) :
  uword (repeat 0%nat k) r = pair_runs 2 2 k ++ r.
Proof.
  induction k as [|k IH]; cbn [repeat uword pair_runs app]; [reflexivity|].
  rewrite IH. reflexivity.
Qed.
Lemma rot_run (R : wside) :
  wrun 4 [] 0 ((1,5%nat)::(0,1%nat)::(1,4%nat)::(0,1%nat)::R)
  = Some ([], 0, (1,2%nat)::(0,2%nat)::(1,5%nat)::(0,1%nat)
                   ::(1,3%nat)::(0,1%nat)::R).
Proof. vm_compute. reflexivity. Qed.
Lemma rot_sound (K : N) (rest : word) (f : N) :
  sound_impl ((5,1,1)%N :: (4,1,1)%N :: (3,1,K)%N :: rest) f
             ((2,2,1)%N :: (5,1,1)%N :: (3,1,(K+1))%N :: rest) f.
Proof.
  unfold sound_impl. intros Hh.
  change (sdecode ?x ?y) with (sdec x y) in Hh |- *.
  rewrite !sdec_cons in Hh |- *.
  change (N.to_nat 5) with 5%nat in Hh |- *.
  change (N.to_nat 4) with 4%nat in Hh |- *.
  change (N.to_nat 3) with 3%nat in Hh |- *.
  change (N.to_nat 2) with 2%nat in Hh |- *.
  change (N.to_nat 1) with 1%nat in Hh |- *.
  assert (EK : N.to_nat (K+1)%N = S (N.to_nat K))
    by (rewrite N2Nat.inj_add; change (N.to_nat 1) with 1%nat; lia).
  rewrite EK in Hh.
  cbn [pair_runs app] in Hh |- *.
  apply (wstep_halts_pull _ _
           (wstep_of 3 _ _ _ _
              (rot_run (pair_runs 3 1 (N.to_nat K) ++ sdec rest f)))).
  cbn [wconf'].
  exact Hh.
Qed.
Ltac tickend :=
  rewrite ?sdec_cons;
  change (N.to_nat 1) with 1%nat;
  change (N.to_nat 2) with 2%nat;
  change (N.to_nat 3) with 3%nat;
  change (N.to_nat 4) with 4%nat;
  change (N.to_nat 7) with 7%nat;
  change (N.to_nat 8) with 8%nat;
  cbn [pair_runs app];
  rewrite <- ?app_assoc;
  match goal with
  | H : N.to_nat ?X = S ?x |- context [ N.to_nat ?X ] => rewrite H
  | _ => idtac
  end;
  reflexivity.
Lemma kernel_deep4_chain1_gen (cT : nat) (Win : wside) (pT : nat) (qT : wside)
      (k a' kk : nat) (ns : list nat) :
  FTrip cT Win pT qT ->
  wrun (5 * k + 6 * a' + 3 * kk + 3 * List.length ns + cT + 24)%nat [] 0
       (uword (zeros (S (S k)) ++ repeat 2%nat (S a') ++ 1%nat :: repeat 2%nat kk)
          ((1,4%nat) :: (0,3%nat) :: (1,4%nat) :: (0,2%nat)
             :: uword ns Win))
  = Some ([], 0,
          cdesc k 2 1
            ((0,2%nat) :: uword (repeat 2%nat a')
               ((1,4%nat) :: (0,1%nat) :: (1,3%nat) :: (0,2%nat)
                  :: uword (repeat 2%nat kk ++ 6%nat :: ns)
                       ((1,S pT) :: qT)))).
Proof.
  intros HT.
  replace (5 * k + 6 * a' + 3 * kk + 3 * List.length ns + cT + 24)%nat
    with (List.length (zeros (S (S k)) ++ repeat 2%nat (S a')
                         ++ 1%nat :: repeat 2%nat kk)
          + (2 + (List.length ns
             + (cT + (2 * List.length (rev ns)
                + (3 + (2 * kk + (3 + (2 * a' + (1 + (1 + (a'
                   + S (S (2 * List.length (rev (repeat 2%nat a'))
                      + (3 + (1 + (4 * k + 4)))))))))))))))))%nat
    by (rewrite ?length_app, ?length_zeros; cbn [List.length];
        rewrite ?length_rev, ?repeat_length; lia).
  rewrite wrun_add, wcross_mixed.
  lazy beta iota.
  rewrite (vstack_vstackC _ [] I).
  rewrite rev_app_distr.
  cbn [rev].
  rewrite rev_app_distr.
  cbn [rev].
  rewrite rev_zeros, !rev_repeat.
  rewrite <- !app_assoc.
  cbn [app].
  rewrite vstackC_app.
  cbn [vstackC].
  rewrite vstackC_app.
  erewrite wrun_split
    by (apply ddeep_in4; apply vstackC_zheaded; apply zheaded0).
  rewrite wrun_add, wcross_mixed.
  lazy beta iota.
  rewrite (vstack_vstackC ns _ (zheaded0 _ _)).
  rewrite wrun_add.
  remember ((0,1%nat)::(1,2%nat)::(0,1%nat)::(1,2%nat)
              :: vstackC (repeat 2%nat kk)
                   (vpairC 1 (vstackC (repeat 2%nat (S a'))
                                (vstackC (zeros (S (S k))) [])))) as ZB
    eqn:EZB.
  destruct (rev ns) as [|n0 nr] eqn:ERN;
    [|destruct n0 as [|n0']]; cbn [vstackC vpairC].
  1: rewrite (HT 0%nat 5%nat ZB).
  2: rewrite (HT 1%nat 1%nat (vstackC nr ((0,1%nat)::(1,6%nat)::ZB))).
  3: rewrite (HT 0%nat n0'
                ((0,1%nat)::(1,2%nat) :: vstackC nr ((0,1%nat)::(1,6%nat)::ZB))).
  all: lazy beta iota.
  1: change ((0,1%nat)::(1,6%nat)::ZB) with (vstackC (@nil nat) ((0,1%nat)::(1,6%nat)::ZB)).
  2: change ((0,2%nat)::(1,2%nat) :: vstackC nr ((0,1%nat)::(1,6%nat)::ZB))
       with (vstackC (0%nat :: nr) ((0,1%nat)::(1,6%nat)::ZB)).
  3: change ((0,1%nat)::(1,S n0')::(0,1%nat)::(1,2%nat)
               :: vstackC nr ((0,1%nat)::(1,6%nat)::ZB))
       with (vstackC (S n0' :: nr) ((0,1%nat)::(1,6%nat)::ZB)).
  all: rewrite wrun_add, wback_run.
  all: lazy beta iota.
  all: rewrite <- ERN.
  all: rewrite emit_uword, rev_involutive.
  all: rewrite EZB.
  all: erewrite wrun_split by apply ddeep_mint4_u.
  all: rewrite (wrun_add (2 * kk)).
  all: rewrite hshift.
  all: rewrite (dm4_half kk 1).
  all: lazy beta iota.
  all: cbn [repeat vstackC].
  all: erewrite wrun_split by apply dm4_w1_u.
  all: rewrite (wrun_add (2 * a')).
  all: rewrite hshift.
  all: rewrite (dm4_half a' 1).
  all: lazy beta iota.
  all: erewrite wrun_split by apply ddeep_entry4.
  all: erewrite wrun_split by apply (wcross1 2).
  all: rewrite vpush_merge2.
  all: rewrite wrun_add.
  all: replace a' with (List.length (repeat 2%nat a')) at 1 by apply repeat_length.
  all: rewrite wcross_mixed.
  all: lazy beta iota.
  all: rewrite (vstack_vstackC _ _ (zheaded0 _ _)).
  all: rewrite rev_repeat.
  all: cbn [wrun].
  all: rewrite (wfuelcross 2 2).
  all: lazy beta iota.
  all: rewrite (vpairC_vpush 2 _ (vstackC_zheaded _ _ (zheaded0 _ _))).
  all: rewrite wstep2.
  all: lazy beta iota.
  all: change ((2 + 2)%nat) with 4%nat.
  all: cbn [wpush sym_eqb].
  all: rewrite (wrun_add (2 * List.length (repeat 2%nat a'))).
  all: rewrite wback_run.
  all: lazy beta iota.
  all: rewrite emit_uword, rev_repeat.
  all: erewrite wrun_split by apply (ddeep_redig_u _ (repeat 2%nat a')).
  all: erewrite wrun_split by apply ddeep_fin4.
  all: rewrite (ccyc_chain k 2 1).
  all: f_equal. f_equal.
  all: rewrite uword_app.
  all: reflexivity.
Qed.
Lemma ddeep_mint4_sand (Z r : wside) (n : nat) :
