Definition dgmid (L : list nat) : wside :=
  (0,1%nat)::(1,2%nat)::(0,1%nat)::(1,4%nat) :: vstackC L [].
Lemma dg_half1 (L : list nat) (c : nat)
      (c1 : nat) (Win : wside) (p1 : nat) (q1 : wside) :
  FTrip c1 Win p1 q1 ->
  wrun (List.length L + 3 * c + c1 + 8)%nat [] 0
       (uword (L ++ 0%nat :: repeat 2%nat c)
          ((1,4%nat)::(0,3%nat)::(1,4%nat)::(0,2%nat) :: Win))
  = Some (dgmid (rev L), 0, uword (repeat 2%nat c ++ [6%nat]) ((1,S p1)::q1)).
Proof.
  intros HT.
  replace (List.length L + 3 * c + c1 + 8)%nat
    with (List.length (L ++ 0%nat :: repeat 2%nat c)
          + (2 + (c1 + (3 + (2 * c + (1 + (1 + 0)))))))%nat
    by (rewrite length_app; cbn [List.length];
        rewrite repeat_length; lia).
  rewrite wrun_add, wcross_mixed.
  lazy beta iota.
  rewrite (vstack_vstackC _ [] I).
  rewrite rev_app_distr.
  cbn [rev].
  rewrite rev_repeat, <- app_assoc.
  cbn [app].
  rewrite vstackC_app.
  erewrite wrun_split
    by (apply ddeep_in4; apply vstackC_zheaded; apply vstackC_zheaded;
        exact I).
  rewrite wrun_add.
  rewrite (HT 0%nat 5%nat ((0,1%nat)::(1,2%nat)::(0,1%nat)::(1,2%nat)
                             :: vstackC (repeat 2%nat c)
                                  (vstackC (0%nat :: rev L) []))).
  lazy beta iota.
  erewrite wrun_split by apply (ddeep_mint4_u _ []).
  rewrite (wrun_add (2 * c)).
  rewrite hshift.
  cbn [vstackC vpairC].
  rewrite (dm4_half c 1).
  lazy beta iota.
  erewrite wrun_split by apply ddeep_entry4.
  erewrite wrun_split by apply (wcross1 2).
  rewrite vpush_merge2.
  cbn [wrun].
  unfold dgmid.
  rewrite uword_app_ms.
  cbn [uword].
  reflexivity.
Qed.
