Definition d4mid (k : nat) : wside :=
  (0,1%nat)::(1,2%nat)::(0,1%nat)::(1,4%nat)::(0,2%nat)::(1,2%nat)
    :: vstackC (zeros k) [].
Lemma dgmid_zeros (k : nat) : dgmid (zeros (S k)) = d4mid k.
Proof. reflexivity. Qed.
Lemma zeros_front (k c : nat) :
  zeros (S k) ++ 0%nat :: repeat 2%nat c = zeros (S (S k)) ++ repeat 2%nat c.
Proof. apply zeros_shift. Qed.
Lemma cp_half2 (ms : list nat) (w b' : nat)
      (c2 : nat) (W : wside) (p2 : nat) (q2 : wside) :
  FTrip c2 W p2 q2 ->
  wrun (2 * List.length ms + b' + c2 + 9)%nat
       (dgmid (repeat 1%nat (S b') ++ (3 + w)%nat :: rev ms)) 0 W
  = Some ([], 0,
          uword (0%nat :: ms)
            ((1,(4+w)%nat)::(0,1%nat)::(1,3%nat)::(0,1%nat)
               :: pair_runs' 4%nat 1%nat b'
               ++ (1,5%nat)::(0,1%nat)::(1,3%nat)::(0,2%nat)
               :: (1,S p2)::q2)).
Proof.
  intros HT.
  replace (2 * List.length ms + b' + c2 + 9)%nat
    with (c2 + (3 + (1 + (b' + (3 + (2 * List.length (rev ms) + 2))))))%nat
    by (rewrite length_rev; lia).
  unfold dgmid.
  rewrite wrun_add.
  rewrite (HT 0%nat 1%nat ((0,1%nat)::(1,4%nat)
                             :: vstackC (repeat 1%nat (S b')
                                  ++ (3 + w)%nat :: rev ms) [])).
  lazy beta iota.
  erewrite wrun_split by apply (ddeep_redig_u _ []).
  rewrite vstackC_app, vstackC_repeat1_S.
  erewrite wrun_split by apply dcp4_entry.
  rewrite (wrun_add b').
  rewrite (dcp_run b').
  lazy beta iota.
  cbn [vstackC].
  rewrite vpairC_3p.
  erewrite wrun_split by apply (dcp_disch_u w _ b').
  rewrite (wrun_add (2 * List.length (rev ms))), wback_run.
  lazy beta iota.
  rewrite emit_uword, rev_involutive.
  cbn [wrun].
  rewrite wclose1.
  lazy beta iota.
  rewrite wclose2.
  lazy beta iota.
  f_equal. f_equal.
  replace (S (S (S (S w)))) with ((4 + w)%nat) by lia.
  destruct ms as [|m t']; cbn; reflexivity.
Qed.
Lemma wconf_gen_cong (l : wside) (cur : Sym) (u v : wside) :
  wconf [] 0 u = wconf [] 0 v -> wconf l cur u = wconf l cur v.
Proof. unfold wconf. intros E. injection E as E1. rewrite E1. reflexivity. Qed.
Lemma wconf_cdesc_cong (j a b : nat) (u v : wside) :
  wconf [] 0 u = wconf [] 0 v ->
  wconf [] 0 (cdesc j a b u) = wconf [] 0 (cdesc j a b v).
Proof.
  revert a b u v. induction j as [|j IH]; intros a b u v E; cbn [cdesc].
  - repeat apply wconf_cons_cong. exact E.
  - apply IH. repeat apply wconf_cons_cong. exact E.
Qed.
Lemma m4_bare (y : nat) (Z : wside) :
  wrun 4 ((0,1%nat)::(1,S (S y))::Z) 0 [(1,4%nat)]
  = Some ((1,S y)::Z, 1, [(1,4%nat); (0,2%nat); (1,4%nat)]).
Proof. reflexivity. Qed.
Lemma m4_cross (y : nat) (Z R : wside) :
  wrun 1 ((0,1%nat)::(1,S (S y))::Z) 0 ((1,4%nat)::(0,2%nat)::R)
  = Some ((0,1%nat)::(1,2%nat)::(0,1%nat)::(1,2%nat)
            ::(0,1%nat)::(1,S (S y))::Z, 0, R).
Proof. reflexivity. Qed.
Lemma m4_ret (y n : nat) (Z R : wside) :
  wrun 2 ((1,1%nat)::(0,1%nat)::(1,2%nat)::(0,1%nat)::(1,S (S y))::Z) 1
         ((1,S n)::R)
  = Some ((1,S y)::Z, 1, (1,4%nat)::(0,2%nat)::(1,S n)::R).
Proof. reflexivity. Qed.
Lemma m4_mint (L Y : wside) :
  wrun 3 ((1,5%nat)::(0,1%nat)::(1,2%nat)::(0,1%nat)::(1,2%nat)::L) 1
         ((1,4%nat)::(0,2%nat)::Y)
  = Some ((0,1%nat)::(1,2%nat)::L, 1,
          (0,1%nat)::(1,7%nat)::(0,1%nat)::(1,3%nat)::(0,2%nat)::Y).
Proof. reflexivity. Qed.
Lemma m4_walls (g : nat) (y : nat) (Z : wside) :
  wrun (4 + 3 * g)%nat ((0,1%nat)::(1,S (S y))::Z) 0
       (uword (repeat 2%nat g) [(1,4%nat)])
  = Some ((1,S y)::Z, 1,
          uword (repeat 2%nat g) [(1,4%nat); (0,2%nat); (1,4%nat)]).
Proof.
  revert y Z. induction g as [|g IH]; intros y Z.
  - cbn [repeat uword]. exact (m4_bare y Z).
  - cbn [repeat uword].
    replace (4 + 3 * S g)%nat with (1 + ((4 + 3 * g) + 2))%nat by lia.
    erewrite wrun_split
      by exact (m4_cross y Z (uword (repeat 2%nat g) [(1,4%nat)])).
    erewrite wrun_split
      by exact (IH 0%nat ((0,1%nat)::(1,2%nat)::(0,1%nat)::(1,S (S y))::Z)).
    destruct (uword_one_headed (repeat 2%nat g) 3%nat
                [(0,2%nat); (1,4%nat)]) as (p & q & E).
    change (uword (repeat 2%nat g) [(1,4%nat); (0,2%nat); (1,4%nat)])
      with (uword (repeat 2%nat g) ((1,S 3%nat) :: [(0,2%nat); (1,4%nat)])).
    rewrite E.
    exact (m4_ret y p Z q).
Qed.
Lemma d4_margin4 (g : nat) (L : wside) :
  wrun (7 + 3 * g)%nat
       ((0,1%nat)::(1,6%nat)::(0,1%nat)::(1,2%nat)::(0,1%nat)::(1,2%nat)::L)
       0 (uword (repeat 2%nat g) [(1,4%nat)])
  = Some ((0,1%nat)::(1,2%nat)::L, 1,
          (0,1%nat)::(1,7%nat)::(0,1%nat)::(1,3%nat)::(0,2%nat)
            :: uword (repeat 2%nat g) [(1,4%nat)]).
Proof.
  replace (7 + 3 * g)%nat with ((4 + 3 * g) + 3)%nat by lia.
  change (1,6%nat) with (1, S (S 4%nat)).
  erewrite wrun_split
    by exact (m4_walls g 4%nat
                ((0,1%nat)::(1,2%nat)::(0,1%nat)::(1,2%nat)::L)).
  change [(1,4%nat); (0,2%nat); (1,4%nat)]
    with ((1,4%nat) :: (0,2%nat) :: [(1,4%nat)]).
  rewrite uword_repeat2_shift.
  exact (m4_mint L (uword (repeat 2%nat g) [(1,4%nat)])).
Qed.
Lemma d4_half2_gen (c2 : nat) (U : wside) (p2 : nat) (q2 : wside) (k : nat) :
  FTrip c2 U p2 q2 ->
  wrun (4 * k + c2 + 8)%nat (d4mid k) 0 U
