  replace (4 * k + c2 + 8)%nat with (c2 + (3 + (1 + (4 * k + 4))))%nat by lia.
  unfold d4mid.
  rewrite wrun_add.
  rewrite (HT 0%nat 1%nat ((0,1%nat)::(1,4%nat)::(0,2%nat)::(1,2%nat)
                             :: vstackC (zeros k) [])).
  lazy beta iota.
  erewrite wrun_split by apply (ddeep_redig_u _ []).
  erewrite wrun_split by apply ddeep_fin4.
  apply (ccyc_chain k 2 1).
Qed.
Lemma d4_half1_m4 (k c g : nat) :
  wrun (k + 3 * c + 3 * g + 13)%nat [] 0
       (uword (zeros (S (S k)) ++ repeat 2%nat c)
          ((1,4%nat)::(0,3%nat)::(1,4%nat)::(0,2%nat)
             :: uword (repeat 2%nat g) [(1,4%nat)]))
  = Some (d4mid k, 0,
          uword (repeat 2%nat c)
            ((1,7%nat)::(0,1%nat)::(1,3%nat)::(0,2%nat)
               :: uword (repeat 2%nat g) [(1,4%nat)])).
Proof.
  replace (k + 3 * c + 3 * g + 13)%nat
    with (List.length (zeros (S (S k)) ++ repeat 2%nat c)
          + (2 + ((7 + 3 * g) + (2 * c + (1 + (1 + 0))))))%nat
    by (rewrite length_app, length_zeros, repeat_length; lia).
  rewrite wrun_add, wcross_mixed.
  lazy beta iota.
  rewrite (vstack_vstackC _ [] I).
  rewrite rev_app_distr, rev_zeros, rev_repeat.
  rewrite vstackC_app.
  erewrite wrun_split
    by (apply ddeep_in4; apply vstackC_zheaded; apply vstackC_zheaded;
        exact I).
  rewrite wrun_add.
  rewrite (d4_margin4 g (vstackC (repeat 2%nat c)
                           (vstackC (zeros (S (S k))) []))).
  lazy beta iota.
  rewrite (wrun_add (2 * c)).
  rewrite hshift.
  cbn [zeros vstackC vpairC].
  rewrite (dm4_half c 1).
  lazy beta iota.
  erewrite wrun_split by apply ddeep_entry4.
  erewrite wrun_split by apply (wcross1 2).
  rewrite vpush_merge2.
  cbn [wrun].
  unfold d4mid.
  reflexivity.
Qed.
Lemma m4_tick_target (a v : N) (tl : word) :
  tick_target ([(5,1,1); (4,1,1); (3,1,a); (2,2,1); (4,2,v)]%N
                    ++ [(7,1,1); (3,2,1)]%N ++ tl) 5 = Some 5%nat.
Proof. reflexivity. Qed.
Lemma m4_deliver (a v : N) (tl : word) :
  deliver_tick FUEL
    ([(5,1,1); (4,1,1); (3,1,a); (2,2,1); (4,2,v)]%N
     ++ [(7,1,1); (3,2,1)]%N ++ tl) 4 5 true
  = ROk ([(5,1,1); (4,1,1); (3,1,a); (2,2,1); (4,2,v); (7,1,1);
               (2,2,1)]%N ++ tl) 4%N.
Proof. reflexivity. Qed.
