Ltac wcbn :=
  cbn [wrunc wrunc_from wsection wpop wpop1s wpush vpush vpairC vstackC
       uword emit pair_runs pair_runs' repeat rev app List.length
       Nat.add Nat.mul sym_eqb fst snd].
Ltac ccost_close :=
  f_equal; f_equal; try reflexivity;
  rewrite ?Nat2N.inj_succ, ?Nat2N.inj_add; lia.
Lemma wrunc_1 (l : wside) (cur : Sym) (r : wside) :
  wrunc 1 l cur r
  = match wsection l cur r with
    | Some (l', cur', r', k) => Some ((l', cur', r'), N.of_nat k)
    | None => None
    end.
Proof.
  rewrite wrunc_S.
  destruct (wsection l cur r) as [[[[l' c'] r'] k]|]; [|reflexivity].
  rewrite wrunc_0. ccost_close.
Qed.
Definition ccost (n : nat) (l : wside) (cur : Sym) (r : wside) (K : N)
  : Prop := exists s, wrunc n l cur r = Some (s, K).
Lemma ccost_pin (n : nat) (l : wside) (cur : Sym) (r : wside)
      (s' : wstate) (K : N) :
  wrun n l cur r = Some s' ->
  ccost n l cur r K ->
  wrunc n l cur r = Some (s', K).
Proof.
  intros HR [s HC].
  pose proof (wrunc_run _ _ _ _ _ _ HC) as HW.
  rewrite HR in HW. injection HW as <-. exact HC.
Qed.
Fixpoint csuml (f : nat -> N) (ms : list nat) : N :=
  match ms with
  | [] => 0%N
  | m :: t => (f m + csuml f t)%N
  end.
Lemma csuml_app (f : nat -> N) (a b : list nat) :
  csuml f (a ++ b) = (csuml f a + csuml f b)%N.
Proof.
  induction a as [|m t IH]; cbn [csuml app]; [lia | rewrite IH; lia].
Qed.
Lemma csuml_repeat (f : nat -> N) (m k : nat) :
  csuml f (repeat m k) = (N.of_nat k * f m)%N.
Proof.
  induction k as [|k IH]; cbn [csuml repeat].
  - change (N.of_nat 0) with 0%N. lia.
  - rewrite IH, Nat2N.inj_succ. lia.
Qed.
Lemma csuml_rev (f : nat -> N) (ms : list nat) :
  csuml f (rev ms) = csuml f ms.
Proof.
  induction ms as [|m t IH]; cbn [rev csuml]; [reflexivity|].
  rewrite csuml_app, IH. cbn [csuml]. lia.
Qed.
Lemma csuml_zeros (f : nat -> N) (n : nat) :
  csuml f (zeros n) = (N.of_nat n * f 0%nat)%N.
Proof.
  induction n as [|n IH]; cbn [csuml zeros].
  - change (N.of_nat 0) with 0%N. lia.
  - rewrite IH, Nat2N.inj_succ. lia.
Qed.
Definition ccross (m : nat) : N := (N.of_nat m + 4)%N.
Definition cback  (m : nat) : N := (N.of_nat m + 6)%N.
Lemma wcross_mixedc (ms : list nat) (l r : wside) :
  wrunc (List.length ms) l 0 (uword ms r)
  = Some ((vstack ms l, 0, r), csuml ccross ms).
Proof.
  gen l. induction ms as [|m t IH]; intros l.
  - cbn [List.length uword csuml]. rewrite wrunc_0. reflexivity.
  - cbn [uword List.length csuml vstack].
    rewrite wrunc_S, wsection_cross.
    lazy beta iota.
    rewrite IH.
    unfold ccross.
    ccost_close.
Qed.
Lemma wback_runc (ms : list nat) (Z r : wside) :
  wrunc (2 * List.length ms) ((1,1%nat) :: vstackC ms Z) 1 r
  = Some (((1,1%nat) :: Z, 1, emit ms r), csuml cback ms).
Proof.
  gen r. induction ms as [|m t IH]; intros r.
  - cbn [List.length vstackC emit csuml].
    change (2 * 0)%nat with 0%nat. rewrite wrunc_0. reflexivity.
  - cbn [vstackC List.length csuml emit].
    replace (2 * S (List.length t)) with (S (S (2 * List.length t))) by lia.
    rewrite wrunc_S, wstep1. lazy beta iota.
    rewrite wrunc_S, wstep2. lazy beta iota.
    rewrite IH.
    unfold cback.
    ccost_close.
Qed.
Lemma dcp_runc (b : nat) (Z : wside) (n : nat) (r : wside) :
  wrunc b ((0,1%nat)::(1,2%nat)::vstackC (repeat 1%nat b) Z) 1 ((1,S n)::r)
  = Some ((((0,1%nat)::(1,2%nat)::Z), 1,
           pair_runs' 4%nat 1%nat b ++ (1,S n)::r), (5 * N.of_nat b)%N).
Proof.
  gen n r. induction b as [|b IH]; intros n r.
  - cbn [repeat vstackC pair_runs' app]. rewrite wrunc_0.
    change (N.of_nat 0) with 0%N. ccost_close.
  - cbn [repeat vstackC vpairC].
    rewrite wrunc_S, dcp_step. lazy beta iota.
    rewrite (IH 3%nat ((0,1%nat)::(1,S n)::r)).
    cbn [pair_runs'].
    rewrite pair_runs'_snoc.
    ccost_close.
Qed.
Lemma dfarA4c (T : wside) :
  wrunc 2 ((0,1%nat)::(1,2%nat)::(0,1%nat)::(1,2%nat)::T) 0 [(1,4%nat)]
  = Some ((((1,1%nat)::(0,1%nat)::(1,2%nat)
             ::(0,1%nat)::(1,2%nat)::(0,1%nat)::(1,2%nat)::T), 1,
           [(1,4%nat)]), 12%N).
Proof. reflexivity. Qed.
Lemma dmintAc (Z : wside) (n : nat) (r : wside) :
  wrunc 2 ((1,1%nat)::(0,1%nat)::(1,2%nat)::(0,1%nat)::(1,1%nat)
             ::(0,1%nat)::(1,2%nat)::Z) 1 ((1,S n)::r)
  = Some ((((0,1%nat)::(1,2%nat)::Z), 1,
           (1,4%nat)::(0,2%nat)::(1,S n)::r), 8%N).
Proof. reflexivity. Qed.
Lemma dcp_dischc (w : nat) (Z : wside) (n : nat) (r : wside) :
  wrunc 3 ((0,1%nat)::(1,2%nat)::(0,1%nat)::(1,S (S (S w)))
             ::(0,1%nat)::(1,2%nat)::Z) 1 ((1,S n)::r)
  = Some ((((1,1%nat)::Z), 1,
           (1,S (S (S (S w))))::(0,1%nat)::(1,3%nat)::(0,1%nat)::(1,S n)::r),
          (N.of_nat w + 15)%N).
Proof.
  destruct w as [|w]; wcbn; rewrite ?PeanoNat.Nat.add_0_r.
  - reflexivity.
  - replace ((w + 2)%nat) with (S (S w)) by lia.
    ccost_close.
Qed.
Lemma dcp_dischc_u (w : nat) (Z : wside) (b n : nat) (r : wside) :
  wrunc 3 ((0,1%nat)::(1,2%nat)::(0,1%nat)::(1,S (S (S w)))
             ::(0,1%nat)::(1,2%nat)::Z) 1
       (pair_runs' 4%nat 1%nat b ++ (1,S n) :: r)
  = Some ((((1,1%nat)::Z), 1,
           (1,S (S (S (S w))))::(0,1%nat)::(1,3%nat)::(0,1%nat)
             :: pair_runs' 4%nat 1%nat b ++ (1,S n) :: r),
          (N.of_nat w + 15)%N).
Proof.
  destruct (pair_runs41_one_headed b n r) as (p & q & E).
  rewrite E. apply dcp_dischc.
Qed.
Definition FTripC (c : nat) (K : N) (Win : wside) (p : nat) (q : wside)
  : Prop :=
  forall (zb y : nat) (Z : wside),
    wrunc c ((0,S zb)::(1,S y)::Z) 0 Win
    = Some ((((1,1%nat)::(0,S zb)::(1,S y)::Z), 1, (1,S p)::q), K).
Lemma FTripC_FTrip (c : nat) (K : N) (Win : wside) (p : nat) (q : wside) :
  FTripC c K Win p q -> FTrip c Win p q.
Proof.
  intros H zb y Z. exact (wrunc_run _ _ _ _ _ _ (H zb y Z)).
Qed.
Lemma FTripC_of (c : nat) (K : N) (Win : wside) (p : nat) (q : wside) :
  FTrip c Win p q ->
  (forall zb y Z, ccost c ((0,S zb)::(1,S y)::Z) 0 Win K) ->
  FTripC c K Win p q.
Proof.
  intros HF HC zb y Z. exact (ccost_pin _ _ _ _ _ _ (HF zb y Z) (HC zb y Z)).
Qed.
Lemma FTripC_marker (c : nat) (K : N) (Win : wside) (p : nat) (q : wside) :
  FTripC c K Win p q ->
  FTripC (c + 3) (K + 10)%N ((1,2%nat)::(0,2%nat)::Win) 1
         ((0,2%nat)::(1,S p)::q).
Proof.
  intros HT zb y Z.
  replace (c + 3) with (S (c + 2)) by lia.
  rewrite wrunc_S.
  change ((1,2%nat)::(0,2%nat)::Win)
    with ((1,(2 + 0)%nat)::(0,2%nat)::Win).
  rewrite wsection_cross.
  lazy beta iota.
  unfold vpush.
  cbn [wpush sym_eqb].
  rewrite wrunc_add.
  change ((0,(1 + 1)%nat)::(1,2%nat)::(0,S zb)::(1,S y)::Z)
    with ((0,S 1%nat)::(1,S 1%nat)::(0,S zb)::(1,S y)::Z).
  rewrite (HT 1%nat 1%nat ((0,S zb)::(1,S y)::Z)).
  lazy beta iota.
  wcbn.
  ccost_close.
Qed.
Lemma FTripC_kernel1 (c : nat) (K : N) (W : wside) (p : nat) (q : wside) :
  FTripC c K W p q ->
  wrunc (c + 5) [] 0 (uword [0%nat] W)
  = Some (([], 0, uword [0%nat;0%nat] ((1,S p)::q)), (K + 16)%N).
Proof.
  intros HT.
  cbn [uword].
  replace (c + 5) with (S (c + 4)) by lia.
  rewrite wrunc_S.
  change ((1,2%nat)::(0,2%nat)::W) with ((1,(2 + 0)%nat)::(0,2%nat)::W).
  rewrite wsection_cross.
  lazy beta iota.
  unfold vpush.
  cbn [wpush sym_eqb].
  change ((0,(1 + 1)%nat)::(1,2%nat)::nil)
    with ((0,S 1%nat)::(1,S 1%nat)::(@nil run)).
  rewrite wrunc_add.
  rewrite (HT 1%nat 1%nat []).
  lazy beta iota.
  wcbn.
  ccost_close.
Qed.
Definition umark (a : nat) (p : nat) (q : wside) : nat * wside :=
  match a with
  | O => (p, q)
  | S a' => (1%nat, (0,2%nat) :: uword (repeat 0%nat a') ((1,S p)::q))
  end.
Lemma umark_out (a : nat) (p : nat) (q : wside) :
  (1,S (fst (umark a p q))) :: snd (umark a p q)
  = uword (repeat 0%nat a) ((1,S p)::q).
Proof. destruct a; reflexivity. Qed.
Lemma FTripC_markers (a : nat) :
  forall (c : nat) (K : N) (Win : wside) (p : nat) (q : wside),
  FTripC c K Win p q ->
  FTripC (c + 3 * a) (K + 10 * N.of_nat a)%N
         (uword (repeat 0%nat a) Win)
         (fst (umark a p q)) (snd (umark a p q)).
Proof.
  induction a as [|a IH]; intros c K Win p q HT.
  - cbn [repeat uword umark fst snd].
    replace (c + 3 * 0) with c by lia.
    replace (K + 10 * N.of_nat 0)%N with K by (cbn; lia).
    exact HT.
  - specialize (IH c K Win p q HT).
    pose proof (FTripC_marker _ _ _ _ _ IH) as HM.
    rewrite umark_out in HM.
    cbn [repeat uword umark fst snd].
    replace (c + 3 * S a) with (c + 3 * a + 3) by lia.
    replace (K + 10 * N.of_nat (S a))%N with (K + 10 * N.of_nat a + 10)%N
      by (rewrite Nat2N.inj_succ; lia).
    exact HM.
Qed.
Lemma FTripC_kernel_markers (a c : nat) (K : N) (Win : wside)
      (p : nat) (q : wside) :
  FTripC c K Win p q ->
  wrunc (3 * a + c + 5) [] 0 (uword (0%nat :: repeat 0%nat a) Win)
  = Some (([], 0, uword (0%nat :: 0%nat :: repeat 0%nat a) ((1,S p)::q)),
          (K + 10 * N.of_nat a + 16)%N).
Proof.
  intros HT.
  pose proof (FTripC_kernel1 _ _ _ _ _ (FTripC_markers a c K Win p q HT))
    as HK.
  rewrite umark_out in HK.
  change (0%nat :: repeat 0%nat a) with ([0%nat] ++ repeat 0%nat a).
  change (0%nat :: 0%nat :: repeat 0%nat a)
    with ([0%nat;0%nat] ++ repeat 0%nat a).
  rewrite !uword_app.
  replace (3 * a + c + 5) with (c + 3 * a + 5) by lia.
  exact HK.
Qed.
Lemma FTripC_farA (m' V' : nat) :
  FTripC (2 * m' + 3 * V' + 12)
    (10 * N.of_nat m' + 14 * N.of_nat V' + 61)%N
    (uword (3%nat :: repeat 1%nat (S m') ++ repeat 2%nat (S V')) [(1,4%nat)])
    3
    ((0,1%nat)::(1,3%nat)::(0,1%nat)
       :: pair_runs' 4%nat 1%nat m'
       ++ pair_runs 4 2 (S (S V')) ++ [(1,4%nat)]).
Proof.
  apply FTripC_of; [apply FTrip_farA|].
  intros zb y Z. eexists.
  replace (2 * m' + 3 * V' + 12)%nat
    with (List.length (3%nat :: repeat 1%nat (S m') ++ repeat 2%nat (S V'))
          + (2 + (2 * List.length (repeat 2%nat (S V'))
             + (2 + (m' + 3)))))%nat
    by (cbn [List.length]; rewrite length_app, !repeat_length; lia).
  rewrite wrunc_add, wcross_mixedc.
  lazy beta iota.
  rewrite (vstack_vstackC _ _ (zheaded0 _ _)).
  cbn [rev].
  rewrite rev_app_distr, rev_repeat, rev_repeat1.
  rewrite <- app_assoc.
  rewrite !vstackC_app.
  cbn [vstackC].
  set (Zin := vstackC (repeat 1%nat (S m'))
                (vpairC 3%nat ((0,S zb)::(1,S y)::Z))).
  rewrite (vstackC2_cons V' Zin).
  erewrite wrunc_split by apply dfarA4c.
  rewrite <- (vstackC2_cons V' Zin).
  rewrite (vstackC2_shift (S V') Zin).
  rewrite wrunc_add, wback_runc.
  lazy beta iota.
  rewrite emit_uword, rev_repeat.
  unfold Zin.
  cbn [repeat vstackC vpairC].
  rewrite (uword_fours_app (S V')).
  cbn [pair_runs app].
  rewrite wrunc_add, dmintAc.
  lazy beta iota.
  rewrite wrunc_add, dcp_runc.
  lazy beta iota.
  rewrite (dcp_dischc_u 0%nat).
  f_equal. f_equal.
  cbn [csuml].
  rewrite !csuml_app.
  cbn [csuml].
  rewrite !csuml_repeat.
  unfold ccross, cback.
  change (N.of_nat 1) with 1%N. change (N.of_nat 2) with 2%N.
  change (N.of_nat 3) with 3%N. change (N.of_nat 0) with 0%N.
  lia.
Qed.
Lemma spanA'_tripc (a' m' V' : nat) :
  wrunc (3 * a' + 2 * m' + 3 * V' + 17) [] 0
       (pair_runs 2 2 (S a') ++ pair_runs 5 2 1 ++ pair_runs 3 2 (S m')
        ++ pair_runs 4 2 (S V') ++ [(1,4%nat)])
  = Some (([], 0,
           pair_runs 2 2 (S (S a'))
             ++ (1,4%nat)::(0,1%nat)::(1,3%nat)::(0,1%nat)
             :: pair_runs 4 1 m' ++ pair_runs 4 2 (S (S V')) ++ [(1,4%nat)]),
          (10 * N.of_nat a' + 10 * N.of_nat m' + 14 * N.of_nat V' + 77)%N).
Proof.
  pose proof (FTripC_kernel_markers a' _ _ _ _ _ (FTripC_farA m' V')) as HK.
  replace (3 * a' + (2 * m' + 3 * V' + 12) + 5)%nat
    with (3 * a' + 2 * m' + 3 * V' + 17)%nat in HK by lia.
  cbn [uword] in HK.
  rewrite !uword_zeros_app in HK.
  rewrite uword_app in HK.
  cbn [uword] in HK.
  rewrite uword_threes_app, uword_fours_app in HK.
  rewrite (pair_runsE 4%nat 1%nat m') in HK.
  cbn [pair_runs app] in HK |- *.
  rewrite <- ?app_assoc in HK.
  rewrite <- ?app_assoc.
  replace (10 * N.of_nat a' + 10 * N.of_nat m' + 14 * N.of_nat V' + 77)%N
    with (10 * N.of_nat m' + 14 * N.of_nat V' + 61
          + 10 * N.of_nat a' + 16)%N by lia.
  exact HK.
Qed.
Lemma kernel_returnc (ms : list nat) (x y : nat) (rest : wside) :
  wrunc (3 * List.length ms + 4)%nat [] 0
       (uword ms ((1,(2+x)%nat) :: (0,1%nat) :: (1,S (S y)) :: rest))
  = Some (([], 0,
           uword (0%nat :: ms)
                 ((1,(2+x)%nat) :: (0,1%nat) :: (1,S y) :: rest)),
          (csuml ccross ms + csuml cback ms + 2 * N.of_nat x + 13)%N).
Proof.
  apply (ccost_pin _ _ _ _ _ _ (kernel_return ms x y rest)).
  eexists.
  replace (3 * List.length ms + 4)%nat
    with (List.length ms + S (2 * List.length ms + 3))%nat by lia.
  rewrite wrunc_add, wcross_mixedc.
  lazy beta iota.
  rewrite wrunc_S, wfuelcross.
  lazy beta iota.
  rewrite (vstack_vstackC ms [] I).
  rewrite (vpairC_vpush x _ (vstackC_zheaded (rev ms) [] I)).
  replace (2 * List.length ms + 3)%nat
    with (S (2 * List.length (rev ms) + 2))%nat
    by (rewrite length_rev; lia).
  rewrite wrunc_S, wstep2.
  lazy beta iota.
  rewrite (wrunc_add (2 * List.length (rev ms)) 2).
  rewrite wback_runc.
  lazy beta iota.
  replace ((x + 2)%nat) with (S (x + 1)) by lia.
  cbn [wpush sym_eqb].
  rewrite emit_uword, rev_involutive.
  rewrite wrunc_S, wclose1. lazy beta iota.
  rewrite wrunc_S, wclose2. lazy beta iota.
  rewrite wrunc_0.
  f_equal. f_equal.
  rewrite csuml_rev. lia.
Qed.
Corollary kernel_returnc_zeros (j x y : nat) (rest : wside) :
  wrunc (3 * j + 4)%nat [] 0
       (uword (zeros j) ((1,(2+x)%nat) :: (0,1%nat) :: (1,S (S y)) :: rest))
  = Some (([], 0,
           uword (0%nat :: zeros j)
                 ((1,(2+x)%nat) :: (0,1%nat) :: (1,S y) :: rest)),
          (10 * N.of_nat j + 2 * N.of_nat x + 13)%N).
Proof.
  replace (3 * j + 4)%nat with (3 * List.length (zeros j) + 4)%nat
    by (rewrite length_zeros; lia).
  rewrite kernel_returnc, !csuml_zeros.
  unfold ccross, cback.
  change (N.of_nat 0) with 0%N.
  f_equal. f_equal. lia.
Qed.
Lemma rot_runc (R : wside) :
  wrunc 4 [] 0 ((1,5%nat)::(0,1%nat)::(1,4%nat)::(0,1%nat)::R)
  = Some (([], 0, (1,2%nat)::(0,2%nat)::(1,5%nat)::(0,1%nat)
                    ::(1,3%nat)::(0,1%nat)::R), 19%N).
Proof. reflexivity. Qed.
