Opaque renew_seg.
Lemma creach_cx_trans (k1 k2 : N) (u v w : Q * tape) :
  creach (cx k1) u v -> creach (cx k2) v w -> creach (cx (k1 + k2)%N) u w.
Proof. intros H1 H2. exact (creach_trans _ _ _ _ _ H1 H2). Qed.
Lemma kernel_mergec (ms : list nat) (x z : nat) (rest : wside) :
  wrunc (3 * List.length ms + 4)%nat [] 0
       (uword ms ((1,(2+x)%nat) :: (0,1%nat) :: (1,1%nat) :: (0,S z) :: rest))
  = Some (([], 0,
           uword (0%nat :: ms) ((1,(2+x)%nat) :: (0,S (S z)) :: rest)),
          (csuml ccross ms + csuml cback ms + 2 * N.of_nat x + 13)%N).
Proof.
  apply (ccost_pin _ _ _ _ _ _ (kernel_merge ms x z rest)).
  eexists.
  replace (3 * List.length ms + 4)%nat
    with (List.length ms + S (2 * List.length ms + 3))%nat by lia.
  rewrite wrunc_add, wcross_mixedc.
  lazy beta iota.
  rewrite wrunc_S, wmergecross.
  lazy beta iota.
  rewrite (vstack_vstackC ms [] I).
  rewrite (vpairC_vpush x _ (vstackC_zheaded (rev ms) [] I)).
  replace (2 * List.length ms + 3)%nat
    with (S (2 * List.length (rev ms) + 2))%nat
    by (rewrite length_rev; lia).
  rewrite wrunc_S, wstep2.
  lazy beta iota.
  rewrite (wrunc_add (2 * List.length (rev ms)) 2).
  rewrite wback_runc.
  lazy beta iota.
  rewrite wrunc_S, wclose1. lazy beta iota.
  rewrite wrunc_S, wclose2. lazy beta iota.
  rewrite wrunc_0.
  f_equal. f_equal.
  rewrite csuml_rev. lia.
Qed.
Lemma kernel_merge_marginc (ms : list nat) (x : nat) :
  wrunc (3 * List.length ms + 4)%nat [] 0
       (uword ms ((1,(2+x)%nat) :: (0,1%nat) :: (1,1%nat) :: nil))
  = Some (([], 0,
           uword (0%nat :: ms) ((1,(2+x)%nat) :: (0,1%nat) :: nil)),
          (csuml ccross ms + csuml cback ms + 2 * N.of_nat x + 13)%N).
Proof.
  apply (ccost_pin _ _ _ _ _ _ (kernel_merge_margin ms x)).
  eexists.
  replace (3 * List.length ms + 4)%nat
    with (List.length ms + S (2 * List.length ms + 3))%nat by lia.
  rewrite wrunc_add, wcross_mixedc.
  lazy beta iota.
  rewrite wrunc_S, wmargincross.
  lazy beta iota.
  rewrite (vstack_vstackC ms [] I).
  rewrite (vpairC_vpush x _ (vstackC_zheaded (rev ms) [] I)).
  replace (2 * List.length ms + 3)%nat
    with (S (2 * List.length (rev ms) + 2))%nat
    by (rewrite length_rev; lia).
  rewrite wrunc_S, wstep2.
  lazy beta iota.
  rewrite (wrunc_add (2 * List.length (rev ms)) 2).
  rewrite wback_runc.
  lazy beta iota.
  rewrite wrunc_S, wclose1. lazy beta iota.
  rewrite wrunc_S, wclose2. lazy beta iota.
  rewrite wrunc_0.
  f_equal. f_equal.
  rewrite csuml_rev. lia.
Qed.
Corollary kernel_mergec_zeros (j x z : nat) (rest : wside) :
  wrunc (3 * j + 4)%nat [] 0
       (uword (zeros j) ((1,(2+x)%nat) :: (0,1%nat) :: (1,1%nat)
                           :: (0,S z) :: rest))
  = Some (([], 0,
           uword (0%nat :: zeros j) ((1,(2+x)%nat) :: (0,S (S z)) :: rest)),
          (10 * N.of_nat j + 2 * N.of_nat x + 13)%N).
Proof.
  replace (3 * j + 4)%nat with (3 * List.length (zeros j) + 4)%nat
    by (rewrite length_zeros; lia).
  rewrite kernel_mergec, !csuml_zeros.
  unfold ccross, cback.
  change (N.of_nat 0) with 0%N.
  f_equal. f_equal. lia.
Qed.
Definition bpc (g : bgroup) : N :=
  let '(o,z,c) := g in (c * (2 * (o + z) + 2))%N.
Fixpoint bsum (w : list bgroup) : N :=
  match w with
  | [] => 0%N
  | g :: t => (bpc g + bsum t)%N
  end.
Lemma bsum_app (a b : list bgroup) : bsum (a ++ b) = (bsum a + bsum b)%N.
Proof. induction a as [|g t IH]; cbn [bsum app]; lia. Qed.
Lemma bsum_gms (p : list bgroup) :
  zpre p ->
  bsum p = (csuml ccross (gms p) + csuml cback (gms p))%N.
Proof.
  induction p as [|[[o z] c] t IH]; intros HP; cbn [bsum gms]; [reflexivity|].
  pose proof (Forall_inv HP) as Hg; cbn in Hg; destruct Hg as [Hz Ho].
  pose proof (Forall_inv_tail HP) as HT.
  subst z.
  rewrite !csuml_app, !csuml_repeat, (IH HT).
  unfold ccross, cback. cbn [bpc].
  rewrite !N2Nat.id.
  replace (N.of_nat (N.to_nat o - 2)) with (o - 2)%N
    by (rewrite Nat2N.inj_sub, N2Nat.id; reflexivity).
  replace (o - 2 + 4)%N with (o + 2)%N by lia.
  replace (o - 2 + 6)%N with (o + 4)%N by lia.
  nia.
Qed.
Definition dtick_z1 (A : N) : N := (2 * A + 9)%N.
Lemma bdec_pre_uword (p : list bgroup) (X : list bgroup) (f : N) :
  zpre p -> bdecode (p ++ X, f) = uword (gms p) (bdecode (X, f)).
Proof.
  intros HP. rewrite bdecode_pre.
  symmetry. apply uword_gms. exact HP.
Qed.
Lemma bdec_col1_uword (p : list bgroup) (X : list bgroup) (f : N) :
  zpre p ->
  bdecode ((2,2,1)%N :: p ++ X, f) = uword (0%nat :: gms p) (bdecode (X, f)).
Proof.
  intros HP.
  pose proof (zpre_cons_col 1%N p HP) as HP'.
  change ((2,2,1)%N :: p ++ X) with (((2,2,1)%N :: p) ++ X).
  rewrite bdecode_pre.
  symmetry.
  exact (uword_gms ((2,2,1)%N :: p) (bdecode (X, f)) HP').
Qed.
Lemma ofnat_ge2 (A : N) (x : nat) :
  (2 <= A)%N -> N.to_nat A = S (S x) -> N.of_nat x = (A - 2)%N.
Proof.
  intros HA E. apply (f_equal N.of_nat) in E. rewrite N2Nat.id in E. lia.
Qed.
Lemma bridge_mergec (J A Z : N) (t : list bgroup) (f : N) :
  (2 <= A)%N -> (1 <= Z)%N ->
  creach (cx (10 * J + dtick_z1 A)%N)
    (wconf [] 0 (bdecode ((2,2,J)::(A,1,1)::(1,Z,1)::t, f)%N))
    (wconf [] 0 (bdecode (((2,2,(J + 1)%N)::(A,(Z + 1)%N,1)::t)%N, f))).
Proof.
  intros HA HZ.
  destruct (to_nat_ge2 A HA) as [x Ex].
  destruct (to_nat_ge1 Z HZ) as [z Ez].
  pose proof (ofnat_ge2 A x HA Ex) as Exn.
  pose proof (kernel_mergec_zeros (N.to_nat J) x z
    (expand (map gdecode t) ++ frun f)) as KM.
  assert (E1 : bdecode ((2,2,J)::(A,1,1)::(1,Z,1)::t, f)%N
             = uword (zeros (N.to_nat J))
                 ((1,(2+x)%nat) :: (0,1%nat) :: (1,1%nat) :: (0, S z)
                    :: expand (map gdecode t) ++ frun f)).
  { unfold bdecode. cbn [map gdecode expand].
    rewrite Ex, Ez.
    change (N.to_nat 2) with 2%nat.
    change (N.to_nat 1) with 1%nat.
    rewrite uword_zeros, <- !app_assoc.
    cbn [pair_runs app]. reflexivity. }
  assert (E2 : bdecode (((2,2,(J + 1)%N)::(A,(Z + 1)%N,1)::t)%N, f)
             = uword (0%nat :: zeros (N.to_nat J))
                 ((1,(2+x)%nat) :: (0, S (S z))
                    :: expand (map gdecode t) ++ frun f)).
  { unfold bdecode. cbn [map gdecode expand].
    rewrite Ex.
    change (N.to_nat 2) with 2%nat.
    change (N.to_nat 1) with 1%nat.
    replace (N.to_nat (Z + 1)) with (S (S z)) by lia.
    replace (N.to_nat (J + 1)) with (S (N.to_nat J)) by lia.
    change (0%nat :: zeros (N.to_nat J)) with (zeros (S (N.to_nat J))).
    rewrite uword_zeros, <- !app_assoc.
    cbn [pair_runs app]. reflexivity. }
  rewrite E1, E2.
  replace (10 * J + dtick_z1 A)%N
    with (10 * N.of_nat (N.to_nat J) + 2 * N.of_nat x + 13)%N
    by (unfold dtick_z1; rewrite N2Nat.id, Exn; lia).
  exact (creach_of_wrunc _ _ _ _ _ _ KM).
Qed.
Lemma bridge_tickc (J A B Z : N) (t : list bgroup) (f : N) :
  (2 <= A)%N -> (2 <= B)%N -> (1 <= Z)%N ->
  creach (cx (10 * J + dtick_z1 A)%N)
    (wconf [] 0 (bdecode ((2,2,J)::(A,1,1)::(B,Z,1)::t, f)%N))
    (wconf [] 0 (bdecode (((2,2,(J + 1)%N)::(A,1,1)::((B - 1)%N,Z,1)::t)%N, f))).
Proof.
  intros HA HB HZ.
  destruct (to_nat_ge2 A HA) as [x Ex].
  destruct (to_nat_ge2 B HB) as [y Ey].
  destruct (to_nat_ge1 Z HZ) as [z Ez].
  pose proof (ofnat_ge2 A x HA Ex) as Exn.
  pose proof (kernel_returnc_zeros (N.to_nat J) x y
    ((0, S z) :: expand (map gdecode t) ++ frun f)) as KR.
  assert (E1 : bdecode ((2,2,J)::(A,1,1)::(B,Z,1)::t, f)%N
             = uword (zeros (N.to_nat J))
                 ((1,(2+x)%nat) :: (0,1%nat) :: (1, S (S y)) :: (0, S z)
                    :: expand (map gdecode t) ++ frun f)).
  { unfold bdecode. cbn [map gdecode expand].
    rewrite Ex, Ey, Ez.
    change (N.to_nat 2) with 2%nat.
    change (N.to_nat 1) with 1%nat.
    rewrite uword_zeros, <- !app_assoc.
    cbn [pair_runs app]. reflexivity. }
  assert (E2 : bdecode (((2,2,(J + 1)%N)::(A,1,1)::((B - 1)%N,Z,1)::t)%N, f)
             = uword (0%nat :: zeros (N.to_nat J))
                 ((1,(2+x)%nat) :: (0,1%nat) :: (1, S y) :: (0, S z)
                    :: expand (map gdecode t) ++ frun f)).
  { unfold bdecode. cbn [map gdecode expand].
    rewrite Ex, Ez.
    change (N.to_nat 2) with 2%nat.
    change (N.to_nat 1) with 1%nat.
    replace (N.to_nat (B - 1)) with (S y) by lia.
    replace (N.to_nat (J + 1)) with (S (N.to_nat J)) by lia.
    change (0%nat :: zeros (N.to_nat J)) with (zeros (S (N.to_nat J))).
    rewrite uword_zeros, <- !app_assoc.
    cbn [pair_runs app]. reflexivity. }
  rewrite E1, E2.
  replace (10 * J + dtick_z1 A)%N
    with (10 * N.of_nat (N.to_nat J) + 2 * N.of_nat x + 13)%N
    by (unfold dtick_z1; rewrite N2Nat.id, Exn; lia).
  exact (creach_of_wrunc _ _ _ _ _ _ KR).
Qed.
Lemma bridge_tick_pc' (p : list bgroup) (A B Z : N) (t : list bgroup) (f : N) :
  zpre p -> (2 <= A)%N -> (2 <= B)%N -> (1 <= Z)%N ->
  creach (cx (bsum p + dtick_z1 A)%N)
    (wconf [] 0 (bdecode (p ++ (A,1,1)::(B,Z,1)::t, f)%N))
    (wconf [] 0 (bdecode ((2,2,1)%N :: p ++ ((A,1,1)::((B - 1)%N,Z,1)::t)%N, f))).
Proof.
  intros HP HA HB HZ.
  destruct (to_nat_ge2 A HA) as [x Ex].
  destruct (to_nat_ge2 B HB) as [y Ey].
  destruct (to_nat_ge1 Z HZ) as [z Ez].
  pose proof (ofnat_ge2 A x HA Ex) as Exn.
  pose proof (kernel_returnc (gms p) x y
    ((0, S z) :: expand (map gdecode t) ++ frun f)) as KR.
  assert (E1 : bdecode (p ++ (A,1,1)::(B,Z,1)::t, f)%N
             = uword (gms p)
                 ((1,(2+x)%nat) :: (0,1%nat) :: (1, S (S y)) :: (0, S z)
                    :: expand (map gdecode t) ++ frun f)).
  { rewrite (bdec_pre_uword _ _ f HP). f_equal.
    unfold bdecode. cbn [map gdecode expand].
    rewrite Ex, Ey, Ez.
    change (N.to_nat 1) with 1%nat.
    cbn [pair_runs app]. rewrite <- ?app_assoc. reflexivity. }
  assert (E2 : bdecode ((2,2,1)%N :: p ++ ((A,1,1)::((B - 1)%N,Z,1)::t)%N, f)
             = uword (0%nat :: gms p)
                 ((1,(2+x)%nat) :: (0,1%nat) :: (1, S y) :: (0, S z)
                    :: expand (map gdecode t) ++ frun f)).
  { rewrite (bdec_col1_uword _ _ f HP). f_equal.
    unfold bdecode. cbn [map gdecode expand].
    rewrite Ex, Ez.
    replace (N.to_nat (B - 1)) with (S y) by lia.
    change (N.to_nat 1) with 1%nat.
    cbn [pair_runs app]. rewrite <- ?app_assoc. reflexivity. }
  rewrite E1, E2.
  replace (bsum p + dtick_z1 A)%N
    with (csuml ccross (gms p) + csuml cback (gms p) + 2 * N.of_nat x + 13)%N
    by (rewrite (bsum_gms p HP); unfold dtick_z1; rewrite Exn; lia).
  exact (creach_of_wrunc _ _ _ _ _ _ KR).
Qed.
Lemma bridge_merge_pc (p : list bgroup) (A Z : N) (t : list bgroup) (f : N) :
  zpre p -> (2 <= A)%N -> (1 <= Z)%N ->
  creach (cx (bsum p + dtick_z1 A)%N)
    (wconf [] 0 (bdecode (p ++ (A,1,1)::(1,Z,1)::t, f)%N))
    (wconf [] 0 (bdecode ((2,2,1)%N :: p ++ ((A,(Z + 1)%N,1)::t)%N, f))).
Proof.
  intros HP HA HZ.
  destruct (to_nat_ge2 A HA) as [x Ex].
  destruct (to_nat_ge1 Z HZ) as [z Ez].
  pose proof (ofnat_ge2 A x HA Ex) as Exn.
  pose proof (kernel_mergec (gms p) x z
    (expand (map gdecode t) ++ frun f)) as KM.
  assert (E1 : bdecode (p ++ (A,1,1)::(1,Z,1)::t, f)%N
             = uword (gms p)
                 ((1,(2+x)%nat) :: (0,1%nat) :: (1,1%nat) :: (0, S z)
                    :: expand (map gdecode t) ++ frun f)).
  { rewrite (bdec_pre_uword _ _ f HP). f_equal.
    unfold bdecode. cbn [map gdecode expand].
    rewrite Ex, Ez.
    change (N.to_nat 1) with 1%nat.
    cbn [pair_runs app]. rewrite <- ?app_assoc. reflexivity. }
  assert (E2 : bdecode ((2,2,1)%N :: p ++ ((A,(Z + 1)%N,1)::t)%N, f)
             = uword (0%nat :: gms p)
                 ((1,(2+x)%nat) :: (0, S (S z))
                    :: expand (map gdecode t) ++ frun f)).
  { rewrite (bdec_col1_uword _ _ f HP). f_equal.
    unfold bdecode. cbn [map gdecode expand].
    rewrite Ex.
    replace (N.to_nat (Z + 1)) with (S (S z)) by lia.
    change (N.to_nat 1) with 1%nat.
    cbn [pair_runs app]. rewrite <- ?app_assoc. reflexivity. }
  rewrite E1, E2.
  replace (bsum p + dtick_z1 A)%N
    with (csuml ccross (gms p) + csuml cback (gms p) + 2 * N.of_nat x + 13)%N
    by (rewrite (bsum_gms p HP); unfold dtick_z1; rewrite Exn; lia).
  exact (creach_of_wrunc _ _ _ _ _ _ KM).
Qed.
Lemma bridge_fartick_pc (p : list bgroup) (A f : N) :
  zpre p -> (2 <= A)%N -> (2 <= f)%N ->
  creach (cx (bsum p + dtick_z1 A)%N)
    (wconf [] 0 (bdecode (p ++ [(A,1,1)%N], f)))
    (wconf [] 0 (bdecode ((2,2,1)%N :: p ++ [(A,1,1)%N], (f - 1)%N))).
Proof.
  intros HP HA Hf.
  destruct (to_nat_ge2 A HA) as [x Ex].
  destruct (to_nat_ge2 f Hf) as [y Ey].
  pose proof (ofnat_ge2 A x HA Ex) as Exn.
  pose proof (kernel_returnc (gms p) x y []) as KR.
  assert (E1 : bdecode (p ++ [(A,1,1)%N], f)
             = uword (gms p)
                 ((1,(2+x)%nat) :: (0,1%nat) :: (1, S (S y)) :: [])).
  { rewrite (bdec_pre_uword _ _ f HP). f_equal.
    unfold bdecode. cbn [map gdecode expand].
    rewrite (frun_pos f) by lia.
    rewrite Ex, Ey.
    change (N.to_nat 1) with 1%nat.
    repeat first [rewrite <- app_assoc | progress cbn [app pair_runs]].
    reflexivity. }
  assert (E2 : bdecode ((2,2,1)%N :: p ++ [(A,1,1)%N], (f - 1)%N)
             = uword (0%nat :: gms p)
                 ((1,(2+x)%nat) :: (0,1%nat) :: (1, S y) :: [])).
  { rewrite (bdec_col1_uword _ _ (f - 1)%N HP). f_equal.
    unfold bdecode. cbn [map gdecode expand].
    rewrite (frun_pos (f - 1)) by lia.
    rewrite Ex.
    replace (N.to_nat (f - 1)) with (S y) by lia.
    change (N.to_nat 1) with 1%nat.
    repeat first [rewrite <- app_assoc | progress cbn [app pair_runs]].
    reflexivity. }
  rewrite E1, E2.
  replace (bsum p + dtick_z1 A)%N
    with (csuml ccross (gms p) + csuml cback (gms p) + 2 * N.of_nat x + 13)%N
    by (rewrite (bsum_gms p HP); unfold dtick_z1; rewrite Exn; lia).
  exact (creach_of_wrunc _ _ _ _ _ _ KR).
Qed.
Lemma bridge_harvest_pc (p : list bgroup) (A : N) :
  zpre p -> (2 <= A)%N ->
  creach (cx (bsum p + dtick_z1 A)%N)
    (wconf [] 0 (bdecode (p ++ [(A,1,1)%N], 1%N)))
    (wconf [] 0 (bdecode ((2,2,1)%N :: p ++ [(A,1,1)%N], 0%N))).
Proof.
  intros HP HA.
  destruct (to_nat_ge2 A HA) as [x Ex].
  pose proof (ofnat_ge2 A x HA Ex) as Exn.
  pose proof (kernel_merge_marginc (gms p) x) as KM.
  assert (E1 : bdecode (p ++ [(A,1,1)%N], 1%N)
             = uword (gms p)
                 ((1,(2+x)%nat) :: (0,1%nat) :: (1,1%nat) :: [])).
  { rewrite (bdec_pre_uword _ _ 1%N HP). f_equal.
    unfold bdecode. cbn [map gdecode expand frun].
    rewrite Ex.
    change (N.to_nat 1) with 1%nat.
    repeat first [rewrite <- app_assoc | progress cbn [app pair_runs]].
    reflexivity. }
  assert (E2 : bdecode ((2,2,1)%N :: p ++ [(A,1,1)%N], 0%N)
             = uword (0%nat :: gms p)
                 ((1,(2+x)%nat) :: (0,1%nat) :: [])).
  { rewrite (bdec_col1_uword _ _ 0%N HP). f_equal.
    unfold bdecode. cbn [map gdecode expand frun].
    rewrite Ex.
    change (N.to_nat 1) with 1%nat.
    repeat first [rewrite <- app_assoc | progress cbn [app pair_runs]].
    reflexivity. }
  rewrite E1, E2.
  replace (bsum p + dtick_z1 A)%N
    with (csuml ccross (gms p) + csuml cback (gms p) + 2 * N.of_nat x + 13)%N
    by (rewrite (bsum_gms p HP); unfold dtick_z1; rewrite Exn; lia).
  exact (creach_of_wrunc _ _ _ _ _ _ KM).
Qed.
Lemma bridge_split_pc (p : list bgroup) (A C : N) (t : list bgroup) (f : N) :
  zpre p -> (2 <= A)%N -> (2 <= C)%N ->
  creach (cx (bsum p + dtick_z1 A)%N)
    (wconf [] 0 (bdecode (p ++ (A,1,C)::t, f)%N))
    (wconf [] 0 (bdecode ((2,2,1)%N :: p
                 ++ ((A,1,1)::((A - 1)%N,1,1)::(A,1,(C - 2)%N)::t)%N, f))).
Proof.
  intros HP HA HC.
  destruct (to_nat_ge2 A HA) as [x Ex].
  destruct (to_nat_ge2 C HC) as [c2 Ec].
  pose proof (ofnat_ge2 A x HA Ex) as Exn.
  pose proof (kernel_returnc (gms p) x x
    ((0, 1%nat) :: pair_runs (S (S x)) 1 c2
       ++ expand (map gdecode t) ++ frun f)) as KR.
  assert (E1 : bdecode (p ++ (A,1,C)::t, f)%N
             = uword (gms p)
                 ((1,(2+x)%nat) :: (0,1%nat) :: (1, S (S x)) :: (0, 1%nat)
                    :: pair_runs (S (S x)) 1 c2
                    ++ expand (map gdecode t) ++ frun f)).
  { rewrite (bdec_pre_uword _ _ f HP). f_equal.
    unfold bdecode. cbn [map gdecode expand].
    rewrite Ex, Ec.
    change (N.to_nat 1) with 1%nat.
    repeat first [rewrite <- app_assoc | progress cbn [app pair_runs]].
    reflexivity. }
  assert (E2 : bdecode ((2,2,1)%N :: p
                 ++ ((A,1,1)::((A - 1)%N,1,1)::(A,1,(C - 2)%N)::t)%N, f)
             = uword (0%nat :: gms p)
                 ((1,(2+x)%nat) :: (0,1%nat) :: (1, S x) :: (0, 1%nat)
                    :: pair_runs (S (S x)) 1 c2
                    ++ expand (map gdecode t) ++ frun f)).
  { rewrite (bdec_col1_uword _ _ f HP). f_equal.
    unfold bdecode. cbn [map gdecode expand].
    rewrite Ex.
    replace (N.to_nat (A - 1)) with (S x) by lia.
    replace (N.to_nat (C - 2)) with c2 by lia.
    change (N.to_nat 1) with 1%nat.
    repeat first [rewrite <- app_assoc | progress cbn [app pair_runs]].
    reflexivity. }
  rewrite E1, E2.
  replace (bsum p + dtick_z1 A)%N
    with (csuml ccross (gms p) + csuml cback (gms p) + 2 * N.of_nat x + 13)%N
    by (rewrite (bsum_gms p HP); unfold dtick_z1; rewrite Exn; lia).
  exact (creach_of_wrunc _ _ _ _ _ _ KR).
Qed.
Definition dclean (a m : N) : N := (30 * a + 36 * m + 123)%N.
Definition dfour (n v : N) : N := (40 * n + 56 * v + 128)%N.
Lemma bridge_clean_cyclec (a m K : N) (t : list bgroup) (f : N) :
  (2 <= K)%N ->
  creach (cx (dclean a m))
    (wconf [] 0 (bdecode ((2,2,a)::(5,2,1)::(3,2,m)::(3,1,K)::t, f)%N))
    (wconf [] 0 (bdecode ((2,2,(a + 3)%N)::(5,2,1)::(3,2,(m + 1)%N)
                          ::(3,1,(K - 2)%N)::t, f)%N)).
Proof.
  intros HK.
  assert (EN : bdecode ((2,2,1)::(2,2,1)::(2,2,1)::(2,2,a)::(5,2,1)
                          ::(3,2,m)::(3,2,1)::(3,1,(K - 2)%N)::t, f)%N
             = bdecode ((2,2,(a + 3)%N)::(5,2,1)::(3,2,(m + 1)%N)
                          ::(3,1,(K - 2)%N)::t, f)%N).
  { unfold bdecode. cbn [map gdecode expand].
    replace (N.to_nat (a + 3)) with (1 + (1 + (1 + N.to_nat a)))%nat by lia.
    replace (N.to_nat (m + 1)) with (N.to_nat m + 1)%nat by lia.
    repeat rewrite pair_runs_add.
    change (N.to_nat 1) with 1%nat.
    repeat first [rewrite <- app_assoc | progress cbn [app pair_runs]].
    reflexivity. }
  rewrite <- EN.
  replace (dclean a m)
    with ((bsum [(2,2,a);(5,2,1);(3,2,m)]%N + dtick_z1 3)
          + ((bsum ((2,2,1)::[(2,2,a);(5,2,1);(3,2,m)])%N + dtick_z1 3)
             + (bsum ((2,2,1)::(2,2,1)::[(2,2,a);(5,2,1);(3,2,m)])%N
                + dtick_z1 3)))%N
    by (unfold dclean, dtick_z1; cbn [bsum bpc]; lia).
  eapply creach_cx_trans.
  { exact (bridge_split_pc [(2,2,a);(5,2,1);(3,2,m)]%N 3 K t f
      ltac:(repeat constructor; cbn; try split; lia)
      ltac:(lia) HK). }
  cbn [app].
  eapply creach_cx_trans.
  { exact (bridge_tick_pc' ((2,2,1)::[(2,2,a);(5,2,1);(3,2,m)])%N
      3 2 1 (((3,1,(K - 2))%N)::t) f
      ltac:(repeat constructor; cbn; try split; lia)
      ltac:(lia) ltac:(lia) ltac:(lia)). }
  cbn [app].
  exact (bridge_merge_pc ((2,2,1)::(2,2,1)::[(2,2,a);(5,2,1);(3,2,m)])%N
      3 1 (((3,1,(K - 2))%N)::t) f
      ltac:(repeat constructor; cbn; try split; lia)
      ltac:(lia) ltac:(lia)).
Qed.
Lemma bridge_four_cyclec (n v M : N) (t : list bgroup) (f : N) :
  (1 <= v)%N -> (2 <= M)%N ->
  creach (cx (dfour n v))
    (wconf [] 0 (bdecode ((2,2,n)::(4,2,v)::(4,1,M)::t, f)%N))
    (wconf [] 0 (bdecode ((2,2,(n + 4)%N)::(4,2,(v + 1)%N)
                          ::(4,1,(M - 2)%N)::t, f)%N)).
Proof.
  intros Hv HM.
  assert (EN : bdecode ((2,2,1)::(2,2,1)::(2,2,1)::(2,2,1)::(2,2,n)
                          ::(4,2,v)::(4,2,1)::(4,1,(M - 2)%N)::t, f)%N
             = bdecode ((2,2,(n + 4)%N)::(4,2,(v + 1)%N)
                          ::(4,1,(M - 2)%N)::t, f)%N).
  { unfold bdecode. cbn [map gdecode expand].
    replace (N.to_nat (n + 4))
      with (1 + (1 + (1 + (1 + N.to_nat n))))%nat by lia.
    replace (N.to_nat (v + 1)) with (N.to_nat v + 1)%nat by lia.
    repeat rewrite pair_runs_add.
    change (N.to_nat 1) with 1%nat.
    repeat first [rewrite <- app_assoc | progress cbn [app pair_runs]].
    reflexivity. }
  rewrite <- EN.
  replace (dfour n v)
    with ((bsum [(2,2,n);(4,2,v)]%N + dtick_z1 4)
          + ((bsum ((2,2,1)::[(2,2,n);(4,2,v)])%N + dtick_z1 4)
             + ((bsum ((2,2,1)::(2,2,1)::[(2,2,n);(4,2,v)])%N + dtick_z1 4)
                + (bsum ((2,2,1)::(2,2,1)::(2,2,1)::[(2,2,n);(4,2,v)])%N
                   + dtick_z1 4))))%N
    by (unfold dfour, dtick_z1; cbn [bsum bpc]; lia).
  eapply creach_cx_trans.
  { exact (bridge_split_pc [(2,2,n);(4,2,v)]%N 4 M t f
      ltac:(repeat constructor; cbn; try split; lia)
      ltac:(lia) HM). }
  cbn [app].
  eapply creach_cx_trans.
  { exact (bridge_tick_pc' ((2,2,1)::[(2,2,n);(4,2,v)])%N
      4 3 1 (((4,1,(M - 2))%N)::t) f
      ltac:(repeat constructor; cbn; try split; lia)
      ltac:(lia) ltac:(lia) ltac:(lia)). }
  cbn [app].
  eapply creach_cx_trans.
  { exact (bridge_tick_pc' ((2,2,1)::(2,2,1)::[(2,2,n);(4,2,v)])%N
      4 2 1 (((4,1,(M - 2))%N)::t) f
      ltac:(repeat constructor; cbn; try split; lia)
      ltac:(lia) ltac:(lia) ltac:(lia)). }
  cbn [app].
  exact (bridge_merge_pc ((2,2,1)::(2,2,1)::(2,2,1)::[(2,2,n);(4,2,v)])%N
      4 1 (((4,1,(M - 2))%N)::t) f
      ltac:(repeat constructor; cbn; try split; lia)
      ltac:(lia) ltac:(lia)).
Qed.
Lemma dclean_step (a m : N) : dclean (a + 3)%N (m + 1)%N = (dclean a m + 126)%N.
Proof. unfold dclean. lia. Qed.
Lemma dfour_step (n v : N) : dfour (n + 4)%N (v + 1)%N = (dfour n v + 216)%N.
Proof. unfold dfour. lia. Qed.
Lemma bridge_clean_iterc (j : nat) :
  forall (a m K : N) (t : list bgroup) (f : N),
  (2 * N.of_nat (S j) <= K)%N ->
  creach (cx (126 * tri (S j) + dclean a m * N.of_nat (S j))%N)
    (wconf [] 0 (bdecode ((2,2,a)::(5,2,1)::(3,2,m)::(3,1,K)::t, f)%N))
    (wconf [] 0 (bdecode ((2,2,(a + 3 * N.of_nat (S j))%N)::(5,2,1)
                          ::(3,2,(m + N.of_nat (S j))%N)
                          ::(3,1,(K - 2 * N.of_nat (S j))%N)::t, f)%N)).
Proof.
  induction j as [|j IH]; intros a m K t f HK.
  - replace (3 * N.of_nat 1)%N with 3%N by lia.
    replace (N.of_nat 1) with 1%N by lia.
    replace (2 * N.of_nat 1)%N with 2%N in HK by lia.
    replace (K - 2 * 1)%N with (K - 2)%N by lia.
    replace (m + 1 * 1)%N with (m + 1)%N by lia.
    replace (126 * tri 1 + dclean a m * 1)%N with (dclean a m)
      by (cbn [tri]; lia).
    apply bridge_clean_cyclec. lia.
  - specialize (IH (a + 3)%N (m + 1)%N (K - 2)%N t f ltac:(lia)).
    rewrite dclean_step in IH.
    replace ((a + 3) + 3 * N.of_nat (S j))%N
      with (a + 3 * N.of_nat (S (S j)))%N in IH by lia.
    replace ((m + 1) + N.of_nat (S j))%N
      with (m + N.of_nat (S (S j)))%N in IH by lia.
    replace ((K - 2) - 2 * N.of_nat (S j))%N
      with (K - 2 * N.of_nat (S (S j)))%N in IH by lia.
    replace (126 * tri (S (S j)) + dclean a m * N.of_nat (S (S j)))%N
      with (dclean a m
            + (126 * tri (S j) + (dclean a m + 126) * N.of_nat (S j)))%N.
    2:{ cbn [tri]. rewrite (Nat2N.inj_succ (S j)). nia. }
    exact (creach_cx_trans _ _ _ _ _
             (bridge_clean_cyclec a m K t f ltac:(lia)) IH).
Qed.
Lemma bridge_four_iterc (j : nat) :
  forall (n v M : N) (t : list bgroup) (f : N),
  (1 <= v)%N -> (2 * N.of_nat (S j) <= M)%N ->
  creach (cx (216 * tri (S j) + dfour n v * N.of_nat (S j))%N)
    (wconf [] 0 (bdecode ((2,2,n)::(4,2,v)::(4,1,M)::t, f)%N))
    (wconf [] 0 (bdecode ((2,2,(n + 4 * N.of_nat (S j))%N)
                          ::(4,2,(v + N.of_nat (S j))%N)
                          ::(4,1,(M - 2 * N.of_nat (S j))%N)::t, f)%N)).
Proof.
  induction j as [|j IH]; intros n v M t f Hv HM.
  - replace (4 * N.of_nat 1)%N with 4%N by lia.
    replace (N.of_nat 1) with 1%N by lia.
    replace (2 * N.of_nat 1)%N with 2%N in HM by lia.
    replace (M - 2 * 1)%N with (M - 2)%N by lia.
    replace (v + 1 * 1)%N with (v + 1)%N by lia.
    replace (216 * tri 1 + dfour n v * 1)%N with (dfour n v)
      by (cbn [tri]; lia).
    apply bridge_four_cyclec; lia.
  - specialize (IH (n + 4)%N (v + 1)%N (M - 2)%N t f ltac:(lia) ltac:(lia)).
    rewrite dfour_step in IH.
    replace ((n + 4) + 4 * N.of_nat (S j))%N
      with (n + 4 * N.of_nat (S (S j)))%N in IH by lia.
    replace ((v + 1) + N.of_nat (S j))%N
      with (v + N.of_nat (S (S j)))%N in IH by lia.
    replace ((M - 2) - 2 * N.of_nat (S j))%N
      with (M - 2 * N.of_nat (S (S j)))%N in IH by lia.
    replace (216 * tri (S (S j)) + dfour n v * N.of_nat (S (S j)))%N
      with (dfour n v
            + (216 * tri (S j) + (dfour n v + 216) * N.of_nat (S j)))%N.
    2:{ cbn [tri]. rewrite (Nat2N.inj_succ (S j)). nia. }
    exact (creach_cx_trans _ _ _ _ _
             (bridge_four_cyclec n v M t f Hv ltac:(lia)) IH).
Qed.
Lemma bridge_cleanconvc (a m K : N) (t : list bgroup) (f : N) :
  (2 <= K)%N ->
  creach (cx (63 * ((K / 2) * (K / 2 - 1)) + dclean a m * (K / 2))%N)
    (wconf [] 0 (bdecode ((2,2,a)::(5,2,1)::(3,2,m)::(3,1,K)::t, f)%N))
    (wconf [] 0 (bdecode ((2,2,(a + 3 * (K / 2))%N)::(5,2,1)
                          ::(3,2,(m + K / 2)%N)
                          ::(3,1,(K mod 2)%N)::t, f)%N)).
Proof.
  intros HK.
  assert (HJ : exists j, N.to_nat (K / 2) = S j).
  { destruct (to_nat_ge1 (K / 2)) as [j Ej].
    - apply N.div_le_lower_bound; lia.
    - eauto. }
  destruct HJ as [j Ej].
  pose proof (bridge_clean_iterc j a m K t f) as IT.
  replace (126 * tri (S j))%N
    with (63 * (N.of_nat (S j) * (N.of_nat (S j) - 1)))%N in IT
    by (rewrite <- tri_double; lia).
  replace (N.of_nat (S j)) with (K / 2)%N in IT
    by (rewrite <- Ej, N2Nat.id; reflexivity).
  replace (K - 2 * (K / 2))%N with (K mod 2)%N in IT
    by (rewrite N.mod_eq; lia).
  apply IT.
  pose proof (N.mul_div_le K 2). lia.
Qed.
Lemma bridge_fourconvc (n v M : N) (t : list bgroup) (f : N) :
  (1 <= v)%N -> (2 <= M)%N ->
  creach (cx (108 * ((M / 2) * (M / 2 - 1)) + dfour n v * (M / 2))%N)
    (wconf [] 0 (bdecode ((2,2,n)::(4,2,v)::(4,1,M)::t, f)%N))
    (wconf [] 0 (bdecode ((2,2,(n + 4 * (M / 2))%N)
                          ::(4,2,(v + M / 2)%N)
                          ::(4,1,(M mod 2)%N)::t, f)%N)).
Proof.
  intros Hv HM.
  assert (HJ : exists j, N.to_nat (M / 2) = S j).
  { destruct (to_nat_ge1 (M / 2)) as [j Ej].
    - apply N.div_le_lower_bound; lia.
    - eauto. }
  destruct HJ as [j Ej].
  pose proof (bridge_four_iterc j n v M t f Hv) as IT.
  replace (216 * tri (S j))%N
    with (108 * (N.of_nat (S j) * (N.of_nat (S j) - 1)))%N in IT
    by (rewrite <- tri_double; lia).
  replace (N.of_nat (S j)) with (M / 2)%N in IT
    by (rewrite <- Ej, N2Nat.id; reflexivity).
  replace (M - 2 * (M / 2))%N with (M mod 2)%N in IT
    by (rewrite N.mod_eq; lia).
  apply IT.
  pose proof (N.mul_div_le M 2). lia.
Qed.
Lemma harvest_branch_soundc (p : word) (A : N) :
  forallb is_col p = true -> (2 <= A)%N ->
  creach (cx (bsum p + dtick_z1 A)%N)
    (wconf [] 0 (sdecode ((p ++ [(A,1,1)])%N) 1))
    (wconf [] 0 (sdecode ((2,2,1)%N :: p) A)).
Proof.
  intros HP HA.
  pose proof (bridge_harvest_pc p A (zpre_of_forallb p HP) HA) as BH.
  assert (E : bdecode ((2,2,1)%N :: p ++ [(A,1,1)%N], 0%N)
            = sdecode ((2,2,1)%N :: p) A ++ [(0,1%nat)]).
  { exact (sdecode_harvest0 ((2,2,1)%N :: p) A
             (N.le_trans _ _ _ (N.le_succ_diag_r 1) HA)). }
  assert (Econf : wconf [] 0 (bdecode ((2,2,1)%N :: p ++ [(A,1,1)%N], 0%N))
                = wconf [] 0 (sdecode ((2,2,1)%N :: p) A))
    by (rewrite E; apply wconf_snoc0).
  rewrite <- Econf.
  exact BH.
Qed.
Lemma dxfar_invXc (X' : nat) (ms : list nat) :
  wrunc 2 (vstackC ms []) 0 [(1,(5 + X')%nat);(0,2%nat);(1,4%nat)]
  = Some (((0,1%nat)::(1,2%nat)::(0,1%nat)::(1,2%nat)
            ::(0,1%nat)::(1,(3 + X')%nat)::(0,1%nat)::(1,2%nat)
            :: vstackC ms [], 0, []),
          (N.of_nat X' + 13)%N).
Proof.
  apply (ccost_pin _ _ _ _ _ _ (dxfar_invX X' ms)).
  destruct ms as [|[|m'] t]; destruct X' as [|d];
    eexists; wcbn; ccost_close.
Qed.
Lemma dxfar_mintvXc (X' : nat) (ms : list nat) :
  wrunc 6 ((0,1%nat)::(1,2%nat)::(0,1%nat)::(1,2%nat)
            ::(0,1%nat)::(1,(3 + X')%nat)::(0,1%nat)::(1,2%nat)
            :: vstackC ms [(0,2%nat);(1,2%nat)]) 0 []
  = Some ((vstackC ms [(0,2%nat);(1,2%nat)], 1,
           (0,1%nat)::(1,(4 + X')%nat)::(0,1%nat)::(1,3%nat)
             ::(0,2%nat)::[(1,4%nat)]),
          (N.of_nat X' + 27)%N).
Proof.
  apply (ccost_pin _ _ _ _ _ _ (dxfar_mintvX X' ms)).
  destruct ms as [|[|m'] t]; destruct X' as [|d];
    eexists; wcbn; ccost_close.
Qed.
Lemma wb0_zeroc (n w : nat) (t : wside) (p : nat) (q : wside) :
  wrunc 2 ((0,2%nat)::(1,2%nat)::(0,S n)::(1,S w)::t) 1
       ((0,1%nat)::(1,S p)::q)
  = Some (((0,S n)::(1,S w)::t, 1,
           (0,1%nat)::(1,2%nat)::(0,2%nat)::(1,S p)::q), 6%N).
Proof. destruct n as [|n]; destruct w as [|w]; reflexivity. Qed.
Lemma wb0_Sc (m n w : nat) (t : wside) (p : nat) (q : wside) :
  wrunc 2 ((0,1%nat)::(1,S m)::(0,1%nat)::(1,2%nat)::(0,S n)::(1,S w)::t) 1
       ((0,1%nat)::(1,S p)::q)
  = Some (((0,S n)::(1,S w)::t, 1,
           (0,1%nat)::(1,(S m + 2)%nat)::(0,2%nat)::(1,S p)::q),
          (N.of_nat m + 7)%N).
Proof.
  apply (ccost_pin _ _ _ _ _ _ (wb0_S m n w t p q)).
  destruct n as [|n]; destruct w as [|w]; eexists; wcbn; ccost_close.
Qed.
Lemma wb0_zero_lastc (p : nat) (q : wside) :
  wrunc 2 ((0,2%nat)::(1,2%nat)::[]) 1 ((0,1%nat)::(1,S p)::q)
  = Some (([(0,1%nat)], 1,
           (0,1%nat)::(1,2%nat)::(0,2%nat)::(1,S p)::q), 6%N).
Proof. reflexivity. Qed.
Lemma wb0_S_lastc (m : nat) (p : nat) (q : wside) :
  wrunc 2 ((0,1%nat)::(1,S m)::(0,1%nat)::(1,2%nat)::[]) 1
       ((0,1%nat)::(1,S p)::q)
  = Some (([(0,1%nat)], 1,
           (0,1%nat)::(1,(S m + 2)%nat)::(0,2%nat)::(1,S p)::q),
          (N.of_nat m + 7)%N).
Proof.
  apply (ccost_pin _ _ _ _ _ _ (wb0_S_last m p q)).
  eexists; wcbn; ccost_close.
Qed.
Lemma vpairC_shape (k : nat) (Z : wside) :
  exists n w t', vpairC k Z = (0,S n)::(1,S w)::t'.
Proof. destruct k as [|m]; cbn [vpairC]; eauto. Qed.
Lemma wback0_ccost (ks : list nat) :
  forall (p : nat) (q : wside),
  ccost (2 * List.length ks + 1) (vstackC ks []) 1 ((0,1%nat)::(1,S p)::q)
        (csuml cback ks + 3)%N.
Proof.
  induction ks as [|k t IH]; intros p q.
  - eexists. cbn [List.length vstackC csuml].
    change (2 * 0 + 1)%nat with 1%nat.
    rewrite wrunc_1. wcbn. ccost_close.
  - cbn [List.length csuml vstackC].
    replace (2 * S (List.length t) + 1)%nat
      with (2 + (2 * List.length t + 1))%nat by lia.
    destruct t as [|k2 t2].
    + cbn [List.length vstackC csuml].
      change (2 * 0 + 1)%nat with 1%nat.
      destruct k as [|m]; cbn [vpairC].
      * eexists.
        erewrite wrunc_split by apply wb0_zero_lastc.
        rewrite wrunc_1. wcbn. unfold cback. ccost_close.
      * eexists.
        erewrite wrunc_split by apply wb0_S_lastc.
        rewrite wrunc_1. wcbn. unfold cback. ccost_close.
    + cbn [vstackC].
      destruct (vpairC_shape k2 (vstackC t2 [])) as (n & w & t' & Ek2).
      rewrite Ek2.
      destruct k as [|m]; cbn [vpairC].
      * destruct (IH 1%nat ((0,2%nat)::(1,S p)::q)) as [s Hs].
        cbn [vstackC] in Hs. rewrite Ek2 in Hs.
        eexists.
        erewrite wrunc_split by apply wb0_zeroc.
        rewrite Hs. unfold cback. ccost_close.
      * destruct (IH (S (S m)) ((0,2%nat)::(1,S p)::q)) as [s2 Hs2].
        cbn [vstackC] in Hs2. rewrite Ek2 in Hs2.
        eexists.
        erewrite wrunc_split by apply wb0_Sc.
        replace ((S m + 2)%nat) with (S (S (S m))) by lia.
        rewrite Hs2. unfold cback. ccost_close.
Qed.
Lemma wback0_runc (ks : list nat) (p : nat) (q : wside) :
  wrunc (2 * List.length ks + 1) (vstackC ks []) 1 ((0,1%nat)::(1,S p)::q)
  = Some (([], 0, (1,2%nat)::(0,2%nat):: emitI ks ((1,S p)::q)),
          (csuml cback ks + 3)%N).
Proof.
  exact (ccost_pin _ _ _ _ _ _ (wback0_run ks p q) (wback0_ccost ks p q)).
Qed.
Lemma kernel_x169gXc (X' : nat) (ms : list nat) :
  wrunc (3 * S (List.length ms) + 9)%nat [] 0
    (uword (0%nat :: ms) ((1,(5 + X')%nat)::(0,2%nat)::[(1,4%nat)]))
  = Some (([], 0,
      uword (0%nat :: 0%nat :: ms)
            ((1,(4 + X')%nat)::(0,1%nat)::(1,3%nat)::(0,2%nat)::[(1,4%nat)])),
      (csuml ccross ms + csuml cback ms + 2 * N.of_nat X' + 53)%N).
Proof.
  apply (ccost_pin _ _ _ _ _ _ (kernel_x169gX X' ms)).
  eexists.
  replace (3 * S (List.length ms) + 9)%nat
    with (List.length (0%nat :: ms)
          + (2 + (6 + (2 * List.length (rev (0%nat :: ms)) + 1))))%nat
    by (rewrite length_rev; cbn [List.length]; lia).
  rewrite wrunc_add, wcross_mixedc.
  lazy beta iota.
  rewrite (vstack_vstackC _ [] I).
  erewrite wrunc_split by apply (dxfar_invXc X').
  cbn [rev].
  rewrite vstackC_app.
  cbn [vstackC vpairC].
  erewrite wrunc_split by apply (dxfar_mintvXc X').
  change ([(0,2%nat);(1,2%nat)]) with (vstackC [0%nat] ([] : wside)).
  rewrite <- vstackC_app.
  change (4 + X')%nat with (S (3 + X')%nat).
  replace (2 * List.length (rev (0%nat :: ms)) + 1)%nat
    with (2 * List.length (rev ms ++ [0%nat]) + 1)%nat
    by (cbn [rev]; reflexivity).
  rewrite wback0_runc.
  f_equal. f_equal.
  rewrite csuml_app, csuml_rev.
  cbn [csuml].
  unfold ccross, cback.
  change (N.of_nat 0) with 0%N.
  lia.
Qed.
Definition dfar169 (X : N) : N := (2 * X + 33)%N.
Lemma bridge_far169_pgc (X c_0 : N) (p' : list bgroup) :
  (5 <= X)%N -> zpre p' -> (1 <= c_0)%N ->
  creach (cx (bsum ((2,2,c_0)%N :: p') + dfar169 X)%N)
    (wconf [] 0 (bdecode (((2,2,c_0)%N :: p') ++ [(X,2,1)]%N, 4%N)))
    (wconf [] 0 (bdecode ((2,2,1)%N :: ((2,2,c_0)%N :: p')
                           ++ [((X-1)%N,1,1); (3,2,1)]%N, 4%N))).
Proof.
  intros E5 HP HC0.
  destruct (to_nat_ge1 c_0 HC0) as [c0' E0].
  pose proof (kernel_x169gXc (N.to_nat (X - 5)%N)
                (repeat 0%nat c0' ++ gms p')) as KE.
  assert (E1 : bdecode (((2,2,c_0)%N :: p') ++ [(X,2,1)]%N, 4%N)
             = uword (0%nat :: repeat 0%nat c0' ++ gms p')
                 ((1,(5 + N.to_nat (X - 5)%N)%nat)::(0,2%nat)::[(1,4%nat)])).
  { rewrite bdecode_pre;
      rewrite <- (gms_col_head _ _ _ E0);
      rewrite (uword_gms _ _ (zpre_cons_col _ _ HP));
      f_equal;
      unfold bdecode;
      cbn [map gdecode expand];
      rewrite ?uword_repeat_w;
      rewrite <- (NtoS5 X E5);
      cbn [frun];
      repeat (change (N.to_nat 4) with 4%nat
           || change (N.to_nat 3) with 3%nat
           || change (N.to_nat 2) with 2%nat
           || change (N.to_nat 1) with 1%nat);
      cbn [pair_runs];
      rewrite <- ?app_assoc, ?app_nil_r;
      cbn [app];
      reflexivity. }
  assert (E2 : bdecode ((2,2,1)%N :: ((2,2,c_0)%N :: p')
                          ++ [((X-1)%N,1,1); (3,2,1)]%N, 4%N)
             = uword (0%nat :: 0%nat :: repeat 0%nat c0' ++ gms p')
                 ((1,(4 + N.to_nat (X - 5)%N)%nat)::(0,1%nat)::(1,3%nat)
                    ::(0,2%nat)::[(1,4%nat)])).
  { assert (EG : gms ((2,2,1)%N :: (2,2,c_0)%N :: p')
               = 0%nat :: 0%nat :: repeat 0%nat c0' ++ gms p').
    { cbn [gms];
        change ((N.to_nat 2 - 2))%nat with 0%nat;
        change (N.to_nat 1) with 1%nat;
        rewrite E0; reflexivity. }
    change ((2,2,1)%N :: ((2,2,c_0)%N :: p')
              ++ [((X-1)%N,1,1); (3,2,1)]%N)
      with (((2,2,1)%N :: (2,2,c_0)%N :: p')
              ++ [((X-1)%N,1,1); (3,2,1)]%N);
      rewrite bdecode_pre;
      rewrite <- EG;
      rewrite (uword_gms _ _ (zpre_cons_col _ _ (zpre_cons_col _ _ HP)));
      f_equal;
      unfold bdecode;
      cbn [map gdecode expand];
      rewrite ?uword_repeat_w;
      rewrite <- (NtoS4 X E5);
      cbn [frun];
      repeat (change (N.to_nat 4) with 4%nat
           || change (N.to_nat 3) with 3%nat
           || change (N.to_nat 2) with 2%nat
           || change (N.to_nat 1) with 1%nat);
      cbn [pair_runs];
      rewrite <- ?app_assoc, ?app_nil_r;
      cbn [app];
      reflexivity. }
  rewrite E1, E2.
  replace (bsum ((2,2,c_0)%N :: p') + dfar169 X)%N
    with (csuml ccross (repeat 0%nat c0' ++ gms p')
          + csuml cback (repeat 0%nat c0' ++ gms p')
          + 2 * N.of_nat (N.to_nat (X - 5)%N) + 53)%N.
  2:{ rewrite (bsum_gms _ (zpre_cons_col c_0 p' HP)).
      rewrite (gms_col_head _ _ _ E0).
      cbn [csuml].
      unfold ccross, cback, dfar169.
      rewrite N2Nat.id.
      change (N.of_nat 0) with 0%N.
      lia. }
  exact (creach_of_wrunc _ _ _ _ _ _ KE).
Qed.
