Definition sound_impl_c (d : cost) (w : word) (f : N)
                        (w' : word) (f' : N) : Prop :=
  creach d (wconf [] 0 (sdecode w f)) (wconf [] 0 (sdecode w' f')).
Lemma sound_impl_c_transfer (d : cost) (w : word) (f : N)
      (w' : word) (f' : N) :
  sound_impl_c d w f w' f' -> sound_impl w f w' f'.
Proof.
  intros [k [_ Hs]] Hh.
  exact (halts_multistep tmB _ _ _ Hh Hs).
Qed.
Lemma sound_impl_c_trans (d1 d2 : cost) (w1 : word) (f1 : N)
      (w2 : word) (f2 : N) (w3 : word) (f3 : N) :
  sound_impl_c d1 w1 f1 w2 f2 ->
  sound_impl_c d2 w2 f2 w3 f3 ->
  sound_impl_c (cadd d1 d2) w1 f1 w3 f3.
Proof. apply creach_trans. Qed.
Lemma sound_impl_c_normalize (d : cost) (w : word) (f : N)
      (w2 : word) (f2 : N) :
  sound_impl_c d w f w2 f2 ->
  sound_impl_c d w f (normalize w2) f2.
Proof. unfold sound_impl_c. rewrite normalize_sound. exact (fun H => H). Qed.
Lemma creach_cx_inv (K : N) (u v : Q * tape) :
  creach (cx K) u v -> u =( N.to_nat K )=> v.
Proof.
  intros [k [Hk Hs]].
  unfold cin, cx in Hk; cbn [fst snd] in Hk.
  replace (N.to_nat K) with k by lia. exact Hs.
Qed.
Lemma cadd_cx (a b : N) : cadd (cx a) (cx b) = cx (a + b)%N.
Proof. reflexivity. Qed.
Lemma rot_sound_c (K : N) (rest : word) (f : N) :
  sound_impl_c (cx 19%N)
    ((5,1,1)%N :: (4,1,1)%N :: (3,1,K)%N :: rest) f
    ((2,2,1)%N :: (5,1,1)%N :: (3,1,(K+1))%N :: rest) f.
Proof.
  unfold sound_impl_c.
  change (sdecode ?x ?y) with (sdec x y).
  rewrite !sdec_cons.
  change (N.to_nat 5) with 5%nat.
  change (N.to_nat 4) with 4%nat.
  change (N.to_nat 3) with 3%nat.
  change (N.to_nat 2) with 2%nat.
  change (N.to_nat 1) with 1%nat.
  assert (EK : N.to_nat (K+1)%N = S (N.to_nat K))
    by (rewrite N2Nat.inj_add; change (N.to_nat 1) with 1%nat; lia).
  rewrite EK.
  cbn [pair_runs app].
  exact (creach_of_wrunc 4 [] 0 _ _ _
           (rot_runc (pair_runs 3 1 (N.to_nat K) ++ sdec rest f))).
Qed.
Lemma spanA'_sound_c (a m V : N) :
  (1 <= a)%N -> (1 <= m)%N -> (1 <= V)%N ->
  sound_impl_c (cx (10 * a + 10 * m + 14 * V + 43)%N)
    [(2,2,a); (5,2,1); (3,2,m); (4,2,V)]%N 4
    [(2,2,a+1); (4,1,1); (3,1,1); (4,1,m-1); (4,2,V+1)]%N 4.
Proof.
  intros Ha Hm HV.
  unfold sound_impl_c.
  replace (10 * a + 10 * m + 14 * V + 43)%N
    with (10 * N.of_nat (N.to_nat (a-1)%N)
          + 10 * N.of_nat (N.to_nat (m-1)%N)
          + 14 * N.of_nat (N.to_nat (V-1)%N) + 77)%N
    by (rewrite !N2Nat.id; lia).
  change (sdecode ?x ?y) with (sdec x y).
  rewrite !sdec_cons, sdec_nil.
  cbn [frun].
  change (N.to_nat 2) with 2%nat.
  change (N.to_nat 5) with 5%nat.
  change (N.to_nat 3) with 3%nat.
  change (N.to_nat 4) with 4%nat.
  change (N.to_nat 1) with 1%nat.
  rewrite (NtoS a Ha), (NtoS m Hm), (NtoS V HV),
          (NtoSS a Ha), (NtoSS V HV).
  cbn [pair_runs app].
  repeat rewrite <- app_assoc.
  pose proof (spanA'_tripc (N.to_nat (a-1)%N) (N.to_nat (m-1)%N)
                (N.to_nat (V-1)%N)) as HT.
  cbn [pair_runs app] in HT.
  repeat rewrite <- app_assoc in HT.
  exact (creach_of_wrunc _ _ _ _ _ _ HT).
Qed.
Lemma FrontC_bridge_tickc (J A B Z : N) (t : list bgroup) (f : N) :
  (2 <= A)%N -> (2 <= B)%N -> (1 <= Z)%N ->
  creach (cx (10 * J + 2 * A + 9)%N)
    (wconf [] 0 (bdecode ((2,2,J)::(A,1,1)::(B,Z,1)::t, f)%N))
    (wconf [] 0 (bdecode
                   (((2,2,(J + 1)%N)::(A,1,1)::((B - 1)%N,Z,1)::t)%N, f))).
Proof.
  intros HA HB HZ.
  destruct (to_nat_ge2 A HA) as [x Ex].
  destruct (to_nat_ge2 B HB) as [y Ey].
  destruct (to_nat_ge1 Z HZ) as [z Ez].
  assert (Exn : N.of_nat x = (A - 2)%N).
  { apply (f_equal N.of_nat) in Ex. rewrite N2Nat.id in Ex. lia. }
  pose proof (kernel_returnc_zeros (N.to_nat J) x y
    ((0, S z) :: expand (map gdecode t) ++ frun f)) as KR.
  assert (E1 : bdecode ((2,2,J)::(A,1,1)::(B,Z,1)::t, f)%N
             = uword (zeros (N.to_nat J))
                 ((1,(2+x)%nat) :: (0,1%nat) :: (1, S (S y)) :: (0, S z)
                    :: expand (map gdecode t) ++ frun f)).
  { unfold bdecode. cbn [map gdecode expand].
    rewrite Ex, Ey, Ez.
    change (N.to_nat 2) with 2%nat.
    change (N.to_nat 1) with 1%nat.
    rewrite uword_zeros, <- !app_assoc.
    cbn [pair_runs app]. reflexivity. }
  assert (E2 : bdecode
                 (((2,2,(J + 1)%N)::(A,1,1)::((B - 1)%N,Z,1)::t)%N, f)
             = uword (0%nat :: zeros (N.to_nat J))
                 ((1,(2+x)%nat) :: (0,1%nat) :: (1, S y) :: (0, S z)
                    :: expand (map gdecode t) ++ frun f)).
  { unfold bdecode. cbn [map gdecode expand].
    rewrite Ex, Ez.
    change (N.to_nat 2) with 2%nat.
    change (N.to_nat 1) with 1%nat.
    replace (N.to_nat (B - 1)%N) with (S y) by lia.
    replace (N.to_nat (J + 1)%N) with (S (N.to_nat J)) by lia.
    change (0%nat :: zeros (N.to_nat J)) with (zeros (S (N.to_nat J))).
    rewrite uword_zeros, <- !app_assoc.
    cbn [pair_runs app]. reflexivity. }
  rewrite E1, E2.
  replace (10 * J + 2 * A + 9)%N
    with (10 * N.of_nat (N.to_nat J) + 2 * N.of_nat x + 13)%N
    by (rewrite N2Nat.id, Exn; lia).
  exact (creach_of_wrunc _ _ _ _ _ _ KR).
Qed.
Lemma d502_sound_c1 (j : N) (rest : word) (f : N) :
  sound_impl_c (cx (10 * j + 19)%N)
    ((2,2,j)%N :: (5,1,1)%N :: (3,1,1)%N :: rest) f
    ((2,2,(j+1))%N :: (5,1,1)%N :: (2,1,1)%N :: rest) f.
Proof.
  unfold sound_impl_c, sdecode.
  replace (10 * j + 19)%N with (10 * j + 2 * 5 + 9)%N by lia.
  exact (FrontC_bridge_tickc j 5 3 1 rest f ltac:(lia) ltac:(lia) ltac:(lia)).
Qed.
Lemma d502_sound_c2 (j K : N) (rest : word) (f : N) :
  (2 <= K)%N ->
  sound_impl_c (cx (10 * j + 19)%N)
    ((2,2,j)%N :: (5,1,1)%N :: (3,1,K)%N :: rest) f
    ((2,2,(j+1))%N :: (5,1,1)%N :: (2,1,1)%N :: (3,1,(K-1))%N :: rest) f.
Proof.
  intros HK.
  unfold sound_impl_c.
  assert (ESPL : sdecode ((2,2,j)%N :: (5,1,1)%N :: (3,1,K)%N :: rest) f
               = sdecode ((2,2,j)%N :: (5,1,1)%N :: (3,1,1)%N
                            :: (3,1,(K-1))%N :: rest) f).
  { rewrite !sdecode_cons.
    replace ((3,1,K)%N) with ((3,1,(1 + (K-1))%N)%N)
      by (f_equal; f_equal; lia).
    rewrite gdec1_merge.
    rewrite <- !app_assoc. reflexivity. }
  rewrite ESPL.
  exact (d502_sound_c1 j ((3,1,(K-1))%N :: rest) f).
Qed.
Lemma decorate_sound (r : word -> N -> option res)
      (dd : word -> N -> cost) :
  (forall w f w2 f2, r w f = Some (ROk w2 f2) ->
                     sound_impl_c (dd w f) w f w2 f2) ->
  forall w f w2 f2 d,
    decorate r dd w f = Some (ROk w2 f2, d) ->
    sound_impl_c d w f w2 f2.
Proof.
  intros H w f w2 f2 d E.
  unfold decorate in E.
  destruct (r w f) as [x|] eqn:EF; [|discriminate E].
  injection E as E1 E2. subst.
  apply H. exact EF.
Qed.
Lemma fr_rot_sound_c (w : word) (f : N) (w2 : word) (f2 : N) :
  fr_rot w f = Some (ROk w2 f2) ->
  sound_impl_c (d_rot w f) w f w2 f2.
Proof.
  intros E. unfold fr_rot in E.
  destruct w as [|[[o1 z1] c1] w1]; [discriminate E|].
  destruct w1 as [|[[o2 z2] c2] w1']; [killmN E|].
  destruct w1' as [|[[o3 z3] K] rest]; [killmN E|].
  killmN E.
  unfold o_ in E. injection E as E1 E2. subst.
  unfold d_rot. apply rot_sound_c.
Qed.
Lemma fr_502_sound_c (w : word) (f : N) (w2 : word) (f2 : N) :
  fr_502 w f = Some (ROk w2 f2) ->
  sound_impl_c (d_502 w f) w f w2 f2.
Proof.
  intros E. unfold fr_502 in E.
  destruct w as [|[[o1 z1] j] w1]; [discriminate E|].
  destruct w1 as [|[[o2 z2] c2] w1']; [killmN E|].
  destruct w1' as [|[[o3 z3] KK] rest]; [killmN E|].
  killmN E.
  destruct (KK =? 1)%N eqn:EK1.
  { apply N.eqb_eq in EK1. subst KK.
    unfold o_ in E. injection E as E1 E2. subst.
    unfold d_502. apply d502_sound_c1. }
  destruct (2 <=? KK)%N eqn:EK2; [|discriminate E].
  apply N.leb_le in EK2.
  unfold o_ in E. injection E as E1 E2. subst.
  unfold d_502. apply d502_sound_c2. exact EK2.
Qed.
Lemma fr_span2A'_sound_c (w : word) (f : N) (w2 : word) (f2 : N) :
  fr_span2A' w f = Some (ROk w2 f2) ->
  sound_impl_c (d_span2A' w f) w f w2 f2.
Proof.
  intros E. unfold fr_span2A' in E.
  destruct w as [|[[o1 z1] c1] w1]; [discriminate E|].
  destruct w1 as [|[[o2 z2] c2] w1']; [killmN E|].
  destruct w1' as [|[[o3 z3] c3] w3]; [killmN E|].
  destruct w3 as [|[[o4 z4] c4] w4]; [killmN E|].
  destruct w4 as [|g5 w5]; [|killmN E].
  killmN E.
  destruct ((1 <=? c1)%N && (1 <=? c3)%N && (1 <=? c4)%N && ((f =? 4)%N))
    eqn:EG; [|discriminate E].
  apply andb_prop in EG as [EG EF4].
  apply andb_prop in EG as [EG EV1].
  apply andb_prop in EG as [EA1 EM1].
  apply N.leb_le in EA1, EM1, EV1. apply N.eqb_eq in EF4. subst f.
  unfold o_ in E. injection E as E1 E2. subst.
  unfold d_span2A'.
  apply spanA'_sound_c; assumption.
Qed.
Corollary cfr_rot_sound (w : word) (f : N) (w2 : word) (f2 : N)
          (d : cost) :
  cfr_rot w f = Some (ROk w2 f2, d) -> sound_impl_c d w f w2 f2.
Proof. apply (decorate_sound _ _ fr_rot_sound_c). Qed.
Corollary cfr_502_sound (w : word) (f : N) (w2 : word) (f2 : N)
          (d : cost) :
  cfr_502 w f = Some (ROk w2 f2, d) -> sound_impl_c d w f w2 f2.
Proof. apply (decorate_sound _ _ fr_502_sound_c). Qed.
Corollary cfr_span2A'_sound (w : word) (f : N) (w2 : word)
          (f2 : N) (d : cost) :
  cfr_span2A' w f = Some (ROk w2 f2, d) ->
  sound_impl_c d w f w2 f2.
Proof. apply (decorate_sound _ _ fr_span2A'_sound_c). Qed.
Definition slice_wins (w : word) (f : N) : Prop :=
  (cstep_front w f = cfr_rot w f
   \/ cstep_front w f = cfr_502 w f
   \/ cstep_front w f = cfr_span2A' w f)
  /\ cstep_front w f <> None.
Theorem cstep_sound_slice (w : word) (f : N) (h : nat)
        (w' : word) (f' : N) (i : nat) (d : cost) :
  cstep w f h = (ROk w' f', i, d) ->
  slice_wins w f ->
  sound_impl_c d w f w' f'.
Proof.
  intros HS [HW HN].
  unfold cstep in HS.
  destruct (cstep_front w f) as [[r dd]|] eqn:EF;
    [|exact (match HN eq_refl with end)].
  destruct r as [w2 f2| |]; try discriminate HS.
  injection HS as HS1 HS2 HS3. subst.
  apply sound_impl_c_normalize.
  destruct HW as [H|[H|H]].
  - exact (cfr_rot_sound _ _ _ _ _ (eq_sym H)).
  - exact (cfr_502_sound _ _ _ _ _ (eq_sym H)).
  - exact (cfr_span2A'_sound _ _ _ _ _ (eq_sym H)).
Qed.
Definition wc0 : word := [(5,1,1); (4,1,1); (3,1,2); (4,2,3)]%N.
Definition wc1 : word := [(2,2,1); (5,1,1); (3,1,3); (4,2,3)]%N.
Definition wc2 : word :=
  [(2,2,2); (5,1,1); (2,1,1); (3,1,2); (4,2,3)]%N.
Example emit0 : cstep wc0 4%N 0%nat = (ROk wc1 4%N, 0%nat, cx 19%N).
Proof. vm_compute. reflexivity. Qed.
Example emit1 : cstep wc1 4%N 0%nat = (ROk wc2 4%N, 0%nat, cx 29%N).
Proof. vm_compute. reflexivity. Qed.
Example proj0 : step wc0 4%N 0%nat = (ROk wc1 4%N, 0%nat).
Proof. vm_compute. reflexivity. Qed.
Example FrontC_proj1 : step wc1 4%N 0%nat = (ROk wc2 4%N, 0%nat).
Proof. vm_compute. reflexivity. Qed.
Example slice_covers_rot : slice_wins wc0 4%N.
Proof.
  split; [left; vm_compute; reflexivity | vm_compute; discriminate].
Qed.
Example slice_covers_502 : slice_wins wc1 4%N.
Proof.
  split; [right; left; vm_compute; reflexivity
         | vm_compute; discriminate].
Qed.
Lemma step0_c : sound_impl_c (cx 19%N) wc0 4%N wc1 4%N.
Proof. exact (cstep_sound_slice _ _ _ _ _ _ _ emit0 slice_covers_rot). Qed.
Lemma step1_c : sound_impl_c (cx 29%N) wc1 4%N wc2 4%N.
Proof. exact (cstep_sound_slice _ _ _ _ _ _ _ emit1 slice_covers_502). Qed.
Theorem chain_c : sound_impl_c (cx 48%N) wc0 4%N wc2 4%N.
Proof.
  pose proof (sound_impl_c_trans _ _ _ _ _ _ _ _ step0_c step1_c) as H.
  rewrite cadd_cx in H. exact H.
Qed.
Theorem chain_steps :
  wconf [] 0 (sdecode wc0 4%N) =( 48 )=> wconf [] 0 (sdecode wc2 4%N).
Proof.
  exact (creach_cx_inv 48%N _ _ chain_c).
Qed.
Corollary chain_transfer : sound_impl wc0 4%N wc2 4%N.
Proof. exact (sound_impl_c_transfer _ _ _ _ _ chain_c). Qed.
