Definition cpair (m : nat) : N := (2 * N.of_nat m + 10)%N.
Lemma cpair_cross (m : nat) : cpair m = (ccross m + cback m)%N.
Proof. unfold cpair, ccross, cback. lia. Qed.
Lemma csuml_cpair_app (a b : list nat) :
  csuml cpair (a ++ b) = (csuml cpair a + csuml cpair b)%N.
Proof. apply csuml_app. Qed.
Lemma csuml_cpair_split (ms : list nat) :
  csuml cpair ms = (csuml ccross ms + csuml cback ms)%N.
Proof.
  induction ms as [|m t IH]; cbn [csuml]; [lia|].
  rewrite IH, cpair_cross. lia.
Qed.
Ltac wcbnu := wcbn; unblock; wcbn; unblock; wcbn.
Ltac ckerc := wcbnu; ccost_close.
Lemma FTripC_tick (s t : nat) (r : wside) :
  FTripC 2 (2 * N.of_nat s + 7)%N
    ((1,(2+s)%nat)::(0,1%nat)::(1,S (S t))::r)
    (1+s) ((0,1%nat)::(1,S t)::r).
Proof.
  apply FTripC_of; [apply FTrip_tick|].
  intros zb y Z. eexists. destruct s as [|s']; ckerc.
Qed.
Lemma FTripC_merge (s z : nat) (r : wside) :
  FTripC 2 (2 * N.of_nat s + 7)%N
    ((1,(2+s)%nat)::(0,1%nat)::(1,1%nat)::(0,S z)::r)
    (1+s) ((0,S (S z))::r).
Proof.
  apply FTripC_of; [apply FTrip_merge|].
  intros zb y Z. eexists. destruct s as [|s']; ckerc.
Qed.
Lemma FTripC_split (a : nat) (r : wside) :
  FTripC 2 (2 * N.of_nat a + 7)%N
    ((1,S (S a))::(0,1%nat)::(1,S (S a))::(0,1%nat)::r)
    (S a) ((0,1%nat)::(1,S a)::(0,1%nat)::r).
Proof.
  apply FTripC_of; [apply FTrip_split|].
  intros zb y Z. eexists. destruct a as [|a']; ckerc.
Qed.
Lemma FTripC_chainsplit (s b : nat) (r : wside) :
  FTripC 2 (2 * N.of_nat s + 7)%N
    ((1,(2+s)%nat)::(0,1%nat)::(1,S (S b))::(0,1%nat)
       ::(1,S (S b))::(0,1%nat)::r)
    (1+s)
    ((0,1%nat)::(1,S b)::(0,1%nat)::(1,S (S b))::(0,1%nat)::r).
Proof.
  apply FTripC_of; [apply FTrip_chainsplit|].
  intros zb y Z. eexists. destruct s as [|s']; ckerc.
Qed.
Lemma FTripC_fartick (s fp : nat) :
  FTripC 2 (2 * N.of_nat s + 7)%N
    ((1,(2+s)%nat)::(0,1%nat)::[(1,S (S fp))])
    (1+s) ((0,1%nat)::[(1,S fp)]).
Proof.
  apply FTripC_of; [apply FTrip_fartick|].
  intros zb y Z. eexists. destruct s as [|s']; ckerc.
Qed.
Lemma FTripC_far1 (s : nat) :
  FTripC 2 (2 * N.of_nat s + 7)%N
    ((1,(2+s)%nat)::(0,1%nat)::[(1,1%nat)])
    (1+s) [(0,1%nat)].
Proof.
  apply FTripC_of; [apply FTrip_far1|].
  intros zb y Z. eexists. destruct s as [|s']; ckerc.
Qed.
Lemma d_col_retc (zb w' y : nat) (Z : wside) (p : nat) (q : wside) :
  wrunc 2 ((1,1%nat)::(0,1%nat)::(1,S w')::(0,1%nat)::(1,2%nat)
            ::(0,S zb)::(1,S y)::Z) 1 ((1,S p)::q)
  = Some ((((1,1%nat)::(0,S zb)::(1,S y)::Z), 1,
           (1,(3 + w')%nat)::(0,2%nat)::(1,S p)::q), (N.of_nat w' + 7)%N).
Proof.
  apply (ccost_pin _ _ _ _ _ _ (d_col_ret zb w' y Z p q)).
  eexists. ckerc.
Qed.
Lemma FTripC_col (c : nat) (K : N) (Win : wside) (p : nat) (q : wside)
      (w' : nat) :
  FTripC c K Win p q ->
  FTripC (c + 3) (K + cpair (S w'))%N
    ((1,(3 + w')%nat)::(0,2%nat)::Win)
    ((2 + w')%nat) ((0,2%nat)::(1,S p)::q).
Proof.
  intros HT zb y Z.
  replace (c + 3) with (S (c + 2)) by lia.
  rewrite wrunc_S.
  change ((1,(3 + w')%nat)::(0,2%nat)::Win)
    with ((1,(2 + S w')%nat)::(0,2%nat)::Win).
  rewrite wsection_cross.
  lazy beta iota.
  unfold vpush.
  cbn [wpush sym_eqb].
  rewrite wrunc_add.
  rewrite (HT _ w').
  lazy beta iota.
  rewrite d_col_retc.
  unfold cpair.
  ccost_close.
Qed.
Corollary FTripC_col2 (c : nat) (K : N) (Win : wside) (p : nat) (q : wside) :
  FTripC c K Win p q ->
  FTripC (c + 3) (K + cpair 0)%N ((1,2%nat)::(0,2%nat)::Win) 1
         ((0,2%nat)::(1,S p)::q).
Proof.
  intros HT.
  replace (K + cpair 0)%N with (K + 10)%N
    by (unfold cpair; change (N.of_nat 0) with 0%N; lia).
  exact (FTripC_marker c K Win p q HT).
Qed.
Lemma FTripC_colg (c : nat) (K : N) (Win : wside) (p : nat) (q : wside)
      (m : nat) :
  FTripC c K Win p q ->
  FTripC (c + 3) (K + cpair m)%N
    ((1,(2 + m)%nat)::(0,2%nat)::Win)
    (S m) ((0,2%nat)::(1,S p)::q).
Proof.
  destruct m as [|m'].
  - exact (FTripC_col2 c K Win p q).
  - exact (FTripC_col c K Win p q m').
Qed.
Fixpoint ucol (ms : list nat) (p : nat) (q : wside) : nat * wside :=
  match ms with
  | [] => (p, q)
  | m :: t =>
    (S m, (0,2%nat) :: (1, S (fst (ucol t p q))) :: snd (ucol t p q))
  end.
Lemma ucol_out (ms : list nat) (p : nat) (q : wside) :
  (1, S (fst (ucol ms p q))) :: snd (ucol ms p q)
  = uword ms ((1,S p)::q).
Proof.
  induction ms as [|m t IH]; cbn [ucol uword fst snd]; [reflexivity|].
  rewrite IH. reflexivity.
Qed.
Lemma FTripC_cols_gen (ms : list nat) :
  forall (c : nat) (K : N) (Win : wside) (p : nat) (q : wside),
  FTripC c K Win p q ->
  FTripC (c + 3 * List.length ms) (K + csuml cpair ms)%N
         (uword ms Win) (fst (ucol ms p q)) (snd (ucol ms p q)).
Proof.
  induction ms as [|m t IH]; intros c K Win p q HT.
  - cbn [List.length uword csuml ucol fst snd].
    replace (c + 3 * 0) with c by lia.
    replace (K + 0)%N with K by lia.
    exact HT.
  - specialize (IH c K Win p q HT).
    pose proof (FTripC_colg _ _ _ _ _ m IH) as HM.
    cbn [uword List.length csuml ucol fst snd].
    replace (c + 3 * S (List.length t))
      with (c + 3 * List.length t + 3) by lia.
    replace (K + (cpair m + csuml cpair t))%N
      with (K + csuml cpair t + cpair m)%N by lia.
    exact HM.
Qed.
Lemma FTripC_kernel_all (ms : list nat) (c : nat) (K : N) (Win : wside)
      (p : nat) (q : wside) :
  FTripC c K Win p q ->
  wrunc (3 * List.length ms + c + 5)%nat [] 0 (uword (0%nat :: ms) Win)
  = Some (([], 0, uword (0%nat :: 0%nat :: ms) ((1,S p)::q)),
          (K + csuml cpair ms + 16)%N).
Proof.
  intros HT.
  pose proof (FTripC_kernel1 _ _ _ _ _ (FTripC_cols_gen ms c K Win p q HT))
    as HK.
  rewrite ucol_out in HK.
  change (0%nat :: ms) with ([0%nat] ++ ms).
  change (0%nat :: 0%nat :: ms) with ([0%nat;0%nat] ++ ms).
  rewrite !uword_app.
  replace (3 * List.length ms + c + 5)
    with (c + 3 * List.length ms + 5) by lia.
  exact HK.
Qed.
Definition SandC (c : nat) (K : N) (W W' : wside) : Prop :=
  forall (b0 : nat) (L0 : wside),
    wrunc c ((0,1%nat)::(1,S b0)::L0) 0 W
    = Some ((((0,1%nat)::(1,S b0)::L0), 1, (0,1%nat) :: W'), K).
Definition Sand0C (c : nat) (K : N) (W W' : wside) : Prop :=
  forall (n b0 : nat) (L0 : wside),
    wrunc c ((0,S n)::(1,S b0)::L0) 0 W
    = Some ((((0,S n)::(1,S b0)::L0), 1, (0,1%nat) :: W'), K).
Lemma SandC_Sand (c : nat) (K : N) (W W' : wside) :
  SandC c K W W' -> Sand c W W'.
Proof. intros H b0 L0. exact (wrunc_run _ _ _ _ _ _ (H b0 L0)). Qed.
Lemma Sand0C_Sand0 (c : nat) (K : N) (W W' : wside) :
  Sand0C c K W W' -> Sand0 c W W'.
Proof. intros H n b0 L0. exact (wrunc_run _ _ _ _ _ _ (H n b0 L0)). Qed.
Lemma Sand0C_SandC (c : nat) (K : N) (W W' : wside) :
  Sand0C c K W W' -> SandC c K W W'.
Proof. intros H b0 L0. exact (H 0%nat b0 L0). Qed.
Lemma SandC_of (c : nat) (K : N) (W W' : wside) :
  Sand c W W' ->
  (forall b0 L0, ccost c ((0,1%nat)::(1,S b0)::L0) 0 W K) ->
  SandC c K W W'.
Proof.
  intros HS HC b0 L0. exact (ccost_pin _ _ _ _ _ _ (HS b0 L0) (HC b0 L0)).
Qed.
Lemma Sand0C_of (c : nat) (K : N) (W W' : wside) :
  Sand0 c W W' ->
  (forall n b0 L0, ccost c ((0,S n)::(1,S b0)::L0) 0 W K) ->
  Sand0C c K W W'.
Proof.
  intros HS HC n b0 L0.
  exact (ccost_pin _ _ _ _ _ _ (HS n b0 L0) (HC n b0 L0)).
Qed.
Lemma Sand0C_far169 (X' : nat) :
  Sand0C 8 (2 * N.of_nat X' + 40)%N
    ((1,(5 + X')%nat)::(0,2%nat)::[(1,4%nat)])
    ((1,(4 + X')%nat)::(0,1%nat)::(1,3%nat)::(0,2%nat)::[(1,4%nat)]).
Proof.
  apply Sand0C_of; [apply Sand0_far169|].
  intros n b0 L0. eexists. destruct n; destruct X' as [|d]; ckerc.
Qed.
Corollary SandC_far169 (X' : nat) :
  SandC 8 (2 * N.of_nat X' + 40)%N
    ((1,(5 + X')%nat)::(0,2%nat)::[(1,4%nat)])
    ((1,(4 + X')%nat)::(0,1%nat)::(1,3%nat)::(0,2%nat)::[(1,4%nat)]).
Proof. apply Sand0C_SandC, Sand0C_far169. Qed.
Lemma SandC_col (c : nat) (K : N) (Win : wside) (W' : wside) (w' : nat) :
  SandC c K Win W' ->
  FTripC (c + 2) (K + 2 * N.of_nat w' + 9)%N
    ((1,(3 + w')%nat)::(0,2%nat)::Win)
    ((2 + w')%nat) ((0,2%nat)::W').
Proof.
  intros HS.
  apply FTripC_of; [apply (Sand_col c Win W' w' (SandC_Sand _ _ _ _ HS))|].
  intros zb y Z. eexists.
  replace (c + 2) with (S (c + 1)) by lia.
  rewrite wrunc_S.
  change ((1,(3 + w')%nat)::(0,2%nat)::Win)
    with ((1,(2 + S w')%nat)::(0,2%nat)::Win).
  rewrite wsection_cross.
  lazy beta iota.
  unfold vpush.
  cbn [wpush sym_eqb].
  rewrite wrunc_add, (HS w').
  lazy beta iota.
  ckerc.
Qed.
Lemma Sand0C_col2 (c : nat) (K : N) (Win : wside) (W' : wside) :
  Sand0C c K Win W' ->
  FTripC (c + 2) (K + 7)%N ((1,2%nat)::(0,2%nat)::Win) 1 ((0,2%nat)::W').
Proof.
  intros HS.
  apply FTripC_of;
    [apply (Sand0_col2 c Win W' (Sand0C_Sand0 _ _ _ _ HS))|].
  intros zb y Z. eexists.
  replace (c + 2) with (S (c + 1)) by lia.
  rewrite wrunc_S.
  change ((1,2%nat)::(0,2%nat)::Win)
    with ((1,(2 + 0)%nat)::(0,2%nat)::Win).
  rewrite wsection_cross.
  lazy beta iota.
  unfold vpush.
  cbn [wpush sym_eqb].
  change ((1 + 1)%nat) with (S 1).
  rewrite wrunc_add, HS.
  lazy beta iota.
  ckerc.
Qed.
Lemma Sand0C_colg (c : nat) (K : N) (Win : wside) (W' : wside) (m : nat) :
  Sand0C c K Win W' ->
  FTripC (c + 2) (K + 2 * N.of_nat m + 7)%N
    ((1,(2 + m)%nat)::(0,2%nat)::Win) (S m) ((0,2%nat)::W').
Proof.
  intros HS. destruct m as [|m'].
  - replace (K + 2 * N.of_nat 0 + 7)%N with (K + 7)%N
      by (change (N.of_nat 0) with 0%N; lia).
    exact (Sand0C_col2 c K Win W' HS).
  - replace (K + 2 * N.of_nat (S m') + 7)%N with (K + 2 * N.of_nat m' + 9)%N
      by (rewrite Nat2N.inj_succ; lia).
    exact (SandC_col c K Win W' m' (Sand0C_SandC _ _ _ _ HS)).
Qed.
Lemma uword_repeat_app (m k : nat) (r : wside) :
  uword (repeat m k) r = pair_runs (2+m)%nat 2 k ++ r.
Proof.
  induction k as [|k IH]; cbn [repeat uword pair_runs app]; [reflexivity|].
  rewrite IH. reflexivity.
Qed.
Lemma FTripC_walls2 (k m : nat) (c : nat) (K : N) (Win : wside)
      (p : nat) (q : wside) :
  FTripC c K Win p q ->
  exists c2 p2 q2,
    FTripC c2 (K + N.of_nat k * cpair m)%N
           (pair_runs (2+m)%nat 2 k ++ Win) p2 q2
    /\ (1,S p2)::q2 = pair_runs (2+m)%nat 2 k ++ (1,S p)::q.
Proof.
  intros HT.
  pose proof (FTripC_cols_gen (repeat m k) c K Win p q HT) as H.
  rewrite csuml_repeat, uword_repeat_app in H.
  exists (c + 3 * List.length (repeat m k)),
         (fst (ucol (repeat m k) p q)), (snd (ucol (repeat m k) p q)).
  split; [exact H|].
  rewrite ucol_out, uword_repeat_app. reflexivity.
Qed.
Corollary FTripC_walls (k w' : nat) (c : nat) (K : N) (Win : wside)
      (p : nat) (q : wside) :
  FTripC c K Win p q ->
  exists c2 p2 q2,
    FTripC c2 (K + N.of_nat k * cpair (S w'))%N
           (pair_runs (3+w')%nat 2 k ++ Win) p2 q2
    /\ (1,S p2)::q2 = pair_runs (3+w')%nat 2 k ++ (1,S p)::q.
Proof. exact (FTripC_walls2 k (S w') c K Win p q). Qed.
Lemma Sand0C_walls2 (k m : nat) (c : nat) (K : N) (Win W' : wside) :
  Sand0C c K Win W' ->
  exists c2 p2 q2,
    FTripC c2 (K + 2 * N.of_nat m + 7 + N.of_nat k * cpair m)%N
           (pair_runs (2+m)%nat 2 (S k) ++ Win) p2 q2
    /\ (1,S p2)::q2 = pair_runs (2+m)%nat 2 (S k) ++ W'.
Proof.
  intros HS.
  destruct (FTripC_walls2 k m (c + 2) (K + 2 * N.of_nat m + 7)%N
              ((1,(2+m)%nat)::(0,2%nat)::Win) (S m) ((0,2%nat)::W')
              (Sand0C_colg c K Win W' m HS)) as (c2 & p2 & q2 & HF & EQ).
  exists c2, p2, q2.
  rewrite (pair_runs_snoc_cons (2+m)%nat 2 k Win) in HF.
  split; [cbn [pair_runs app]; exact HF|].
  rewrite EQ.
  change (S (S m)) with ((2+m)%nat).
  rewrite (pair_runs_snoc_cons (2+m)%nat 2 k W').
  cbn [pair_runs app]. reflexivity.
Qed.
Lemma SandC_walls (k w' : nat) (c : nat) (K : N) (Win W' : wside) :
  SandC c K Win W' ->
  exists c2 p2 q2,
    FTripC c2 (K + 2 * N.of_nat w' + 9 + N.of_nat k * cpair (S w'))%N
           (pair_runs (3+w')%nat 2 (S k) ++ Win) p2 q2
    /\ (1,S p2)::q2 = pair_runs (3+w')%nat 2 (S k) ++ W'.
Proof.
  intros HS.
  destruct (FTripC_walls k w' (c + 2) (K + 2 * N.of_nat w' + 9)%N
              ((1,(3+w')%nat)::(0,2%nat)::Win) ((2+w')%nat) ((0,2%nat)::W')
              (SandC_col c K Win W' w' HS)) as (c2 & p2 & q2 & HF & EQ).
  exists c2, p2, q2.
  rewrite (pair_runs_snoc_cons (3+w')%nat 2 k Win) in HF.
  split; [cbn [pair_runs app]; exact HF|].
  rewrite EQ.
  change (S (2+w')%nat) with ((3+w')%nat).
  rewrite (pair_runs_snoc_cons (3+w')%nat 2 k W').
  cbn [pair_runs app]. reflexivity.
Qed.
Fixpoint wcolcost (cols : word) : N :=
  match cols with
  | [] => 0%N
  | g :: t => (gC g * (2 * gO g + 6) + wcolcost t)%N
  end.
Lemma wcolcost_col (o cg : N) (m : nat) :
  N.to_nat o = (2 + m)%nat ->
  (N.of_nat (N.to_nat cg) * cpair m)%N = (cg * (2 * o + 6))%N.
Proof.
  intros EW.
  assert (EO : o = (2 + N.of_nat m)%N).
  { rewrite <- (N2Nat.id o), EW, Nat2N.inj_add.
    change (N.of_nat 2) with 2%N. reflexivity. }
  rewrite N2Nat.id, EO. unfold cpair. lia.
Qed.
Lemma FTripC_cols2 (cols : word) (c : nat) (K : N) (Win : wside)
      (p : nat) (q : wside) :
  forallb is_col cols = true ->
  FTripC c K Win p q ->
  exists c2 p2 q2,
    FTripC c2 (K + wcolcost cols)%N
           (expand (map gdecode cols) ++ Win) p2 q2
    /\ (1,S p2)::q2 = expand (map gdecode cols) ++ (1,S p)::q.
Proof.
  induction cols as [|g cols' IH]; intros HB HF.
  - cbn [map expand app wcolcost]. exists c, p, q.
    replace (K + 0)%N with K by lia.
    split; [exact HF|reflexivity].
  - cbn [forallb] in HB. apply andb_prop in HB. destruct HB as (HCOL & HB').
    destruct g as [[o z] cg].
    unfold is_col in HCOL. cbn [gZ gO] in *.
    apply andb_prop in HCOL. destruct HCOL as (HZ & HO).
    apply N.eqb_eq in HZ. subst z.
    apply N.leb_le in HO.
    assert (EW : exists m, N.to_nat o = (2 + m)%nat).
    { exists (N.to_nat o - 2)%nat. lia. }
    destruct EW as [m EW].
    destruct (IH HB' HF) as (c2 & p2 & q2 & HF2 & EQ2).
    destruct (FTripC_walls2 (N.to_nat cg) m c2 _ _ p2 q2 HF2)
      as (c3 & p3 & q3 & HF3 & EQ3).
    exists c3, p3, q3.
    cbn [map gdecode expand wcolcost gC gO].
    change (N.to_nat 2) with 2%nat.
    rewrite EW.
    rewrite <- app_assoc.
    replace (K + (cg * (2 * o + 6) + wcolcost cols'))%N
      with (K + wcolcost cols' + N.of_nat (N.to_nat cg) * cpair m)%N
      by (rewrite (wcolcost_col o cg m EW); lia).
    split; [exact HF3|].
    rewrite EQ3, EQ2, <- app_assoc. reflexivity.
Qed.
Lemma forallb_seek_is_col (cols : word) :
  forallb (fun g => is_col g && negb (is_cmf g)
                    && (3 <=? gO g)%N) cols = true ->
  forallb is_col cols = true.
Proof.
  induction cols as [|g t IH]; [reflexivity|].
  cbn [forallb]. intros HB.
  apply andb_prop in HB. destruct HB as (HG & HB').
  apply andb_prop in HG. destruct HG as (HG1 & _).
  apply andb_prop in HG1. destruct HG1 as (HCOL & _).
  rewrite HCOL. cbn [andb]. exact (IH HB').
Qed.
Corollary FTripC_cols (cols : word) (c : nat) (K : N) (Win : wside)
      (p : nat) (q : wside) :
  forallb (fun g => is_col g && negb (is_cmf g)
                    && (3 <=? gO g)%N) cols = true ->
  FTripC c K Win p q ->
  exists c2 p2 q2,
    FTripC c2 (K + wcolcost cols)%N
           (expand (map gdecode cols) ++ Win) p2 q2
    /\ (1,S p2)::q2 = expand (map gdecode cols) ++ (1,S p)::q.
Proof.
  intros HB. apply FTripC_cols2, forallb_seek_is_col, HB.
Qed.
Lemma djump_hopc (Z : wside) (p : nat) (q : wside) :
  wrunc 2 ((1,1%nat)::(0,1%nat)::(1,2%nat)::(0,1%nat)::(1,2%nat)::Z)
       1 ((1,S p)::q)
  = Some ((((1,1%nat)::Z), 1, (1,4%nat)::(0,2%nat)::(1,S p)::q), 8%N).
Proof. reflexivity. Qed.
Lemma djump_hops2c (k : nat) (Z : wside) (p : nat) (q : wside) :
  wrunc (2 * k) ((1,1%nat):: vstackC (repeat 2%nat k) Z) 1 ((1,S p)::q)
  = Some ((((1,1%nat)::Z), 1, fourk k ((1,S p)::q)), (8 * N.of_nat k)%N).
Proof.
  revert Z p q. induction k as [|k IH]; intros Z p q.
  - cbn [repeat vstackC fourk]. change (2 * 0)%nat with 0%nat.
    rewrite wrunc_0. change (N.of_nat 0) with 0%N. ccost_close.
  - cbn [repeat vstackC vpairC fourk].
    replace (2 * S k)%nat with (2 + 2 * k)%nat by lia.
    erewrite wrunc_split by apply djump_hopc.
    rewrite IH. ccost_close.
Qed.
Lemma djump_hop0c (Z : wside) (p : nat) (q : wside) :
  wrunc 2 ((0,1%nat)::(1,2%nat)::(0,1%nat)::(1,2%nat)
            ::(0,1%nat)::(1,2%nat)::Z) 1 ((0,1%nat)::(1,S p)::q)
  = Some ((((0,1%nat)::(1,2%nat)::Z), 1,
           (0,1%nat)::(1,4%nat)::(0,2%nat)::(1,S p)::q), 8%N).
Proof. reflexivity. Qed.
Lemma djump_hops0c (k : nat) (Z : wside) (p : nat) (q : wside) :
  wrunc (2 * k) ((0,1%nat)::(1,2%nat):: vstackC (repeat 2%nat k) Z) 1
       ((0,1%nat)::(1,S p)::q)
  = Some ((((0,1%nat)::(1,2%nat)::Z), 1, (0,1%nat):: fourk k ((1,S p)::q)),
          (8 * N.of_nat k)%N).
Proof.
  revert Z p q. induction k as [|k IH]; intros Z p q.
  - cbn [repeat vstackC fourk]. change (2 * 0)%nat with 0%nat.
    rewrite wrunc_0. change (N.of_nat 0) with 0%N. ccost_close.
  - cbn [repeat vstackC vpairC fourk].
    replace (2 * S k)%nat with (2 + 2 * k)%nat by lia.
    erewrite wrunc_split by apply djump_hop0c.
    rewrite IH, fourk_shift. ccost_close.
Qed.
Lemma d203_hop2c (zb y : nat) (Z : wside) (p : nat) (q : wside) :
  wrunc 2 ((0,1%nat)::(1,2%nat)::(0,1%nat)::(1,2%nat)
            ::(0,S zb)::(1,S y)::Z) 1 ((0,1%nat)::(1,S p)::q)
  = Some ((((0,S zb)::(1,S y)::Z), 1,
           (0,1%nat)::(1,4%nat)::(0,2%nat)::(1,S p)::q), 8%N).
Proof.
  apply (ccost_pin _ _ _ _ _ _ (d203_hop2 zb y Z p q)).
  eexists. destruct zb; ckerc.
Qed.
Lemma d203_hopsc (zb k y : nat) (Z : wside) (p : nat) (q : wside) :
  wrunc (2 * k) (vstackC (repeat 2%nat k) ((0,S zb)::(1,S y)::Z)) 1
    ((0,1%nat)::(1,S p)::q)
  = Some ((((0,S zb)::(1,S y)::Z), 1, (0,1%nat)::fourk k ((1,S p)::q)),
          (8 * N.of_nat k)%N).
Proof.
  revert p q. induction k as [|k IH]; intros p q.
  - cbn [repeat vstackC fourk]. change (2 * 0)%nat with 0%nat.
    rewrite wrunc_0. change (N.of_nat 0) with 0%N. ccost_close.
  - cbn [repeat vstackC vpairC].
    replace (2 * S k)%nat with (2 + 2 * k)%nat by lia.
    destruct k as [|k'].
    { cbn [vstackC].
      erewrite wrunc_split by apply (d203_hop2c _ y).
      cbn [fourk]. rewrite wrunc_0. ccost_close. }
    cbn [repeat vstackC vpairC].
    erewrite wrunc_split by apply (d203_hop2c _ 1).
    change ((0,1%nat)::(1,2%nat)::(0,1%nat)::(1,2%nat)
              :: vstackC (repeat 2%nat k') ((0,S zb)::(1,S y)::Z))
      with (vstackC (repeat 2%nat (S k')) ((0,S zb)::(1,S y)::Z)).
    rewrite IH. cbn [fourk]. ccost_close.
Qed.
Lemma d203_crossg_gc (k : nat) (L r : wside) :
  wrunc k ((0,1%nat)::L) 0 (uword (repeat 2%nat k) r)
  = Some ((vstackC (repeat 2%nat k) ((0,1%nat)::L), 0, r),
          (6 * N.of_nat k)%N).
Proof.
  replace k with (List.length (repeat 2%nat k)) at 1 by apply repeat_length.
  rewrite wcross_mixedc, (vstack_vstackC _ _ (zheaded0 _ _)), rev_repeat,
          csuml_repeat.
  unfold ccross. change (N.of_nat 2) with 2%N.
  f_equal. f_equal. lia.
Qed.
