Lemma FTripC_stageXg (X' : nat) (c : nat) (K : N) (Win : wside) (p : nat)
      (q : wside) (NLr : nat) :
  FTripC c K Win p q ->
  FTripC (c + 3 * NLr + 6)
    (K + 2 * N.of_nat X' + 14 * N.of_nat NLr + 38)%N
    ((1,(5+X')%nat)::(0,3%nat)::(1,4%nat)::(0,2%nat)
       :: uword (repeat 2%nat NLr) Win)
    ((3+X')%nat)
    ((0,1%nat)::(1,7%nat)::(0,2%nat)
       :: uword (repeat 2%nat NLr) ((1,S p)::q)).
Proof.
  intros HT zb y Z.
  replace (c + 3 * NLr + 6)%nat
    with (2 + (NLr + (c + (2 * NLr + 4))))%nat by lia.
  erewrite wrunc_split by apply (d357_inXvc X' _ y).
  erewrite wrunc_split by apply d203_crossg_gc.
  destruct NLr as [|NLr'].
  { cbn [repeat vstackC].
    rewrite wrunc_add.
    rewrite (HT _ 5%nat).
    lazy beta iota.
    erewrite wrunc_split by apply (djump_hops2c 0).
    cbn [fourk].
    rewrite d_casc_retXc.
    lazy beta iota.
    change (N.of_nat 0) with 0%N.
    ccost_close. }
  cbn [repeat vstackC vpairC].
  rewrite wrunc_add.
  rewrite (HT _ 1%nat).
  lazy beta iota.
  erewrite wrunc_split by apply (djump_hops2c (S NLr')).
  rewrite fourk_uword.
  cbn [repeat uword].
  change ((2 + 2)%nat) with 4%nat.
  rewrite d_casc_retXc.
  lazy beta iota.
  cbn [repeat uword].
  ccost_close.
Qed.
Lemma FTripC_stageXg_sand (X' : nat) (c : nat) (K : N) (Win : wside)
      (p : nat) (q : wside) (NLr : nat) :
  SandC c K Win ((1,S p)::q) ->
  FTripC (c + 3 * NLr + 5)
    (K + 2 * N.of_nat X' + 14 * N.of_nat NLr + 35)%N
    ((1,(5+X')%nat)::(0,3%nat)::(1,4%nat)::(0,2%nat)
       :: uword (repeat 2%nat NLr) Win)
    ((3+X')%nat)
    ((0,1%nat)::(1,7%nat)::(0,2%nat)
       :: uword (repeat 2%nat NLr) ((1,S p)::q)).
Proof.
  intros HS zb y Z.
  replace (c + 3 * NLr + 5)%nat
    with (2 + (NLr + (c + (2 * NLr + 3))))%nat by lia.
  erewrite wrunc_split by apply (d357_inXvc X' _ y).
  erewrite wrunc_split by apply d203_crossg_gc.
  destruct NLr as [|NLr'].
  { cbn [repeat vstackC].
    rewrite wrunc_add.
    rewrite (HS 5%nat).
    lazy beta iota.
    rewrite d_casc_sretXc.
    lazy beta iota.
    change (N.of_nat 0) with 0%N.
    ccost_close. }
  cbn [repeat vstackC vpairC].
  rewrite wrunc_add.
  rewrite (HS 1%nat).
  lazy beta iota.
  change ((0,1%nat)::(1,2%nat)::(0,1%nat)::(1,2%nat)
            :: vstackC (repeat 2%nat NLr')
                 ((0,1%nat)::(1,6%nat)::(0,1%nat)::(1,(3+X')%nat)
                    ::(0,1%nat)::(1,2%nat)::(0,S zb)::(1,S y)::Z))
    with (vstackC (repeat 2%nat (S NLr'))
            ((0,1%nat)::(1,6%nat)::(0,1%nat)::(1,(3+X')%nat)
               ::(0,1%nat)::(1,2%nat)::(0,S zb)::(1,S y)::Z)).
  erewrite wrunc_split by apply (d203_hopsc _ (S NLr') 5).
  rewrite fourk_uword.
  cbn [repeat uword].
  change ((2 + 2)%nat) with 4%nat.
  rewrite d_casc_sretXc.
  lazy beta iota.
  cbn [repeat uword].
  ccost_close.
Qed.
