Lemma FTripC_endR (h' fp' : nat) :
  FTripC (3 * h' + 13)
    (14 * N.of_nat h' + 2 * N.of_nat fp' + 75)%N
    (uword ((6%nat :: repeat 2%nat h') ++ [2%nat])
       ((1,4%nat)::(0,3%nat)::[(1,S (S fp'))]))
    6
    ((0,1%nat)::(1,3%nat)::(0,2%nat)
       :: uword (repeat 2%nat h' ++ [2%nat])
            ((1,(5 + fp')%nat)::(0,1%nat)::[(1,3%nat)])).
Proof.
  apply FTripC_of; [apply FTrip_endR|].
  intros zb y Z. eexists.
  replace (3 * h' + 13)%nat
    with (List.length ((6%nat :: repeat 2%nat h') ++ [2%nat])
          + (2 + (4 + (2 * S h' + 3))))%nat
    by (rewrite !length_app; cbn [List.length];
        rewrite !repeat_length; lia).
  rewrite wrunc_add, wcross_mixedc.
  lazy beta iota.
  rewrite (vstack_vstackC _ _ (zheaded0 _ _)).
  rewrite rev_app_distr.
  cbn [rev app vstackC vpairC].
  rewrite rev_repeat.
  erewrite wrunc_split by apply (d_endR_invc _ 1).
  erewrite wrunc_split by apply d_endR_mintvc.
  rewrite vstackC_app.
  change ((0,1%nat)::(1,2%nat)::(0,1%nat)::(1,2%nat)
            :: vstackC (repeat 2%nat h')
                 (vstackC [6%nat] ((0,S zb)::(1,S y)::Z)))
    with (vstackC (repeat 2%nat (S h'))
            (vstackC [6%nat] ((0,S zb)::(1,S y)::Z))).
  erewrite wrunc_split by apply djump_hops0c.
  cbn [vstackC vpairC fourk].
  rewrite fourk_shift.
  rewrite d_endR_stopvc.
  lazy beta iota.
  f_equal. f_equal.
  cbn [csuml app repeat].
  rewrite csuml_app, csuml_repeat.
  cbn [csuml].
  unfold ccross.
  change (N.of_nat 6) with 6%N. change (N.of_nat 2) with 2%N.
  rewrite Nat2N.inj_succ.
  lia.
Qed.
