Lemma ddeep_inc (l r : wside) :
  zheaded l ->
  wrunc 2 l 0 ((1,3%nat) :: (0,3%nat) :: (1,4%nat) :: (0,2%nat) :: r)
  = Some ((((0,1%nat) :: (1,6%nat) :: (0,1%nat) :: (1,1%nat) :: (0,1%nat)
             :: (1,2%nat) :: l), 0, r), 14%N).
Proof.
  intros H.
  apply (ccost_pin _ _ _ _ _ _ (ddeep_in l r H)).
  destruct l as [|[b n] t].
  - eexists. ckerc.
  - destruct b; [|discriminate H].
    destruct n as [|n']; eexists; ckerc.
Qed.
Lemma ddeep_mintc (Z r : wside) (n : nat) :
