Lemma FTripC_chainphase (c : nat) (K : N) (Win : wside) (p : nat) (q : wside)
    (ms : list nat) (w b : nat) (ns : list nat) :
  FTripC c K Win p q ->
  wrunc (3 * List.length ms + 2 * b + 3 * List.length ns + c + 10)%nat [] 0
       (uword (ms ++ (3 + w)%nat :: repeat 1%nat b)
          ((1,3%nat)::(0,3%nat)::(1,4%nat)::(0,2%nat)
             :: uword ns Win))
  = Some (([], 0,
           uword (0%nat :: ms)
                 ((1,(4+w)%nat)::(0,1%nat)::(1,3%nat)::(0,1%nat)
                    :: pair_runs' 4%nat 1%nat b
                    ++ (1,8%nat)::(0,2%nat)
                    :: uword ns ((1,S p)::q))),
          (K + csuml cpair ms + csuml cpair ns
           + 2 * N.of_nat w + 10 * N.of_nat b + 54)%N).
Proof.
  intros HT.
  apply (ccost_pin _ _ _ _ _ _
           (FTrip_chainphase c Win p q ms w b ns (FTripC_FTrip _ _ _ _ _ HT))).
  eexists.
  replace (3 * List.length ms + 2 * b + 3 * List.length ns + c + 10)%nat
    with (List.length (ms ++ (3 + w)%nat :: repeat 1%nat b)
          + (2 + (List.length ns
             + (c + (2 * List.length (rev ns)
                + (2 + (b + (3 + (2 * List.length (rev ms) + 2)))))))))%nat
    by (rewrite !length_app, !length_rev;
        cbn [List.length]; rewrite !repeat_length; lia).
  rewrite wrunc_add, wcross_mixedc.
  lazy beta iota.
  rewrite (vstack_vstackC _ [] I).
  rewrite rev_app_distr.
  cbn [rev].
  rewrite rev_repeat1.
  rewrite <- app_assoc.
  rewrite vstackC_app.
  cbn [app vstackC].
  erewrite wrunc_split
    by (apply ddeep_inc; apply vstackC_zheaded; apply vpairC_zheaded).
  rewrite wrunc_add, wcross_mixedc.
  lazy beta iota.
  rewrite (vstack_vstackC ns _ (zheaded0 _ _)).
  rewrite wrunc_add.
  destruct (rev ns) as [|n0 nr] eqn:ERN;
    [|destruct n0 as [|n0']]; cbn [vstackC vpairC].
  1: rewrite (HT 0%nat 5%nat
               ((0,1%nat)::(1,1%nat)::(0,1%nat)::(1,2%nat)
                  :: vstackC (repeat 1%nat b)
                       (vpairC (3 + w)%nat (vstackC (rev ms) [])))).
  2: rewrite (HT 1%nat 1%nat
               (vstackC nr
                  ((0,1%nat)::(1,6%nat)::(0,1%nat)::(1,1%nat)
                     ::(0,1%nat)::(1,2%nat)
                  :: vstackC (repeat 1%nat b)
                       (vpairC (3 + w)%nat (vstackC (rev ms) []))))).
  3: rewrite (HT 0%nat n0'
               ((0,1%nat)::(1,2%nat)
                  :: vstackC nr
                       ((0,1%nat)::(1,6%nat)::(0,1%nat)::(1,1%nat)
                          ::(0,1%nat)::(1,2%nat)
                  :: vstackC (repeat 1%nat b)
                       (vpairC (3 + w)%nat (vstackC (rev ms) []))))).
  all: lazy beta iota.
  1: change ((0,1%nat)::(1,6%nat)::(0,1%nat)::(1,1%nat)
               ::(0,1%nat)::(1,2%nat)
                  :: vstackC (repeat 1%nat b)
                       (vpairC (3 + w)%nat (vstackC (rev ms) [])))
       with (vstackC (@nil nat)
               ((0,1%nat)::(1,6%nat)::(0,1%nat)::(1,1%nat)
                  ::(0,1%nat)::(1,2%nat)
                  :: vstackC (repeat 1%nat b)
                       (vpairC (3 + w)%nat (vstackC (rev ms) [])))).
  2: change ((0,2%nat)::(1,2%nat)
               :: vstackC nr
                    ((0,1%nat)::(1,6%nat)::(0,1%nat)::(1,1%nat)
                       ::(0,1%nat)::(1,2%nat)
                  :: vstackC (repeat 1%nat b)
                       (vpairC (3 + w)%nat (vstackC (rev ms) []))))
       with (vstackC (0%nat :: nr)
               ((0,1%nat)::(1,6%nat)::(0,1%nat)::(1,1%nat)
                  ::(0,1%nat)::(1,2%nat)
                  :: vstackC (repeat 1%nat b)
                       (vpairC (3 + w)%nat (vstackC (rev ms) [])))).
  3: change ((0,1%nat)::(1,S n0')::(0,1%nat)::(1,2%nat)
               :: vstackC nr
                    ((0,1%nat)::(1,6%nat)::(0,1%nat)::(1,1%nat)
                       ::(0,1%nat)::(1,2%nat)
                  :: vstackC (repeat 1%nat b)
                       (vpairC (3 + w)%nat (vstackC (rev ms) []))))
       with (vstackC (S n0' :: nr)
               ((0,1%nat)::(1,6%nat)::(0,1%nat)::(1,1%nat)
                  ::(0,1%nat)::(1,2%nat)
                  :: vstackC (repeat 1%nat b)
                       (vpairC (3 + w)%nat (vstackC (rev ms) [])))).
  all: rewrite wrunc_add, wback_runc.
  all: lazy beta iota.
  all: rewrite <- ERN.
  all: rewrite emit_uword, rev_involutive.
  all: erewrite wrunc_split by apply ddeep_mint_uc.
  all: rewrite (wrunc_add b).
  all: rewrite (dcp_runc b).
  all: lazy beta iota.
  all: rewrite vpairC_3p.
  all: erewrite wrunc_split by apply (dcp_dischc_u w _ b).
  all: rewrite (wrunc_add (2 * List.length (rev ms))), wback_runc.
  all: lazy beta iota.
  all: rewrite emit_uword, rev_involutive.
  all: rewrite wrunc_S, wclose1.
  all: lazy beta iota.
  all: rewrite wrunc_S, wclose2.
  all: lazy beta iota.
  all: rewrite wrunc_0.
  all: f_equal; f_equal.
  all: rewrite !csuml_cpair_split.
  all: rewrite csuml_app; cbn [csuml].
  all: rewrite csuml_repeat, !csuml_rev.
  all: unfold ccross, cback.
  all: change (N.of_nat 1) with 1%N.
  all: rewrite Nat2N.inj_add.
  all: change (N.of_nat 3) with 3%N.
  all: lia.
Qed.
