Lemma FTripC_farC (m' V' : nat) :
  FTripC (2 * m' + 6 * V' + 23)
    (10 * N.of_nat m' + 28 * N.of_nat V' + 115)%N
    (uword (3%nat :: repeat 1%nat (S m') ++ 0%nat :: repeat 2%nat (S V'))
       [(1,4%nat)])
    3
    ((0,1%nat)::(1,3%nat)::(0,1%nat)
       :: pair_runs' 4%nat 1%nat m'
       ++ (1,6%nat)::(0,2%nat)
       :: pair_runs 4 2 (S (S V')) ++ [(1,4%nat)]).
Proof.
  apply FTripC_of; [apply FTrip_farC|].
  intros zb y Z. eexists.
  replace (2 * m' + 6 * V' + 23)%nat
    with (List.length
            (3%nat :: repeat 1%nat (S m') ++ 0%nat :: repeat 2%nat (S V'))
          + (2 + (2 * List.length (repeat 2%nat (S V'))
             + (2 + (1 + (List.length (repeat 2%nat (S V'))
                + (2 + (2 * List.length (repeat 2%nat (S (S V')))
                   + (2 + (m' + 3)))))))))) %nat
    by (cbn [List.length]; rewrite length_app; cbn [List.length];
        rewrite !repeat_length; lia).
  rewrite wrunc_add, wcross_mixedc.
  lazy beta iota.
  rewrite (vstack_vstackC _ _ (zheaded0 _ _)).
  cbn [rev].
  rewrite rev_app_distr.
  cbn [rev app].
  rewrite rev_repeat, rev_repeat1.
  rewrite !vstackC_app.
  cbn [vstackC].
  set (X := vstackC (repeat 1%nat (S m'))
              (vpairC 3%nat ((0,S zb)::(1,S y)::Z))).
  set (Zc := vpairC 0%nat X).
  rewrite (vstackC2_cons V' Zc).
  erewrite wrunc_split by apply dfarA4c.
  rewrite <- (vstackC2_cons V' Zc).
  rewrite (vstackC2_shift (S V') Zc).
  rewrite wrunc_add, wback_runc.
  lazy beta iota.
  rewrite emit_uword, rev_repeat.
  unfold Zc.
  cbn [vpairC].
  rewrite wrunc_add, dentryC_uc.
  lazy beta iota.
  change ((1,4%nat)::(0,2%nat):: uword (repeat 2%nat (S V')) [(1,4%nat)])
    with (uword (repeat 2%nat (S (S V'))) [(1,4%nat)]).
  cbn [repeat uword].
  rewrite wrunc_add, dcrossCc.
  lazy beta iota.
  change ((1,(2 + 2)%nat)::(0,2%nat):: uword (repeat 2%nat V') [(1,4%nat)])
    with (uword (repeat 2%nat (S V')) [(1,4%nat)]).
  rewrite wrunc_add, wcross_mixedc.
  lazy beta iota.
  rewrite (vstack_vstackC _ _ (zheaded0 _ _)), rev_repeat.
  set (W0 := (0,1%nat)::(1,2%nat)::(0,1%nat)::(1,4%nat)::X).
  rewrite (vstackC2_cons V' W0).
  erewrite wrunc_split by apply dfarA4c.
  rewrite <- (vstackC2_cons V' W0).
  rewrite (vstackC2_shift (S V') W0).
  unfold W0.
  change ((0,1%nat)::(1,2%nat)::(0,1%nat)::(1,2%nat)::(0,1%nat)::(1,4%nat)::X)
    with (vstackC (repeat 2%nat 1) ((0,1%nat)::(1,4%nat)::X)).
  rewrite <- vstackC_app.
  rewrite <- repeat_app.
  rewrite wrunc_add.
  replace (S V' + 1)%nat with (S (S V')) by lia.
  rewrite wback_runc.
  lazy beta iota.
  rewrite emit_uword, rev_repeat.
  unfold X.
  cbn [repeat vstackC vpairC].
  rewrite wrunc_add, dmintC_uc.
  lazy beta iota.
  rewrite wrunc_add, dcp_runc.
  lazy beta iota.
  rewrite (dcp_dischc_u 0%nat).
  f_equal. f_equal.
  cbn [csuml].
  rewrite csuml_app.
  cbn [csuml].
  rewrite !csuml_repeat.
  unfold ccross, cback.
  change (N.of_nat 1) with 1%N. change (N.of_nat 2) with 2%N.
  change (N.of_nat 3) with 3%N. change (N.of_nat 0) with 0%N.
  rewrite ?Nat2N.inj_succ.
  lia.
Qed.
Lemma spanC'_tripc (a' m' V' : nat) :
  wrunc (3 * a' + 2 * m' + 6 * V' + 28) [] 0
       (pair_runs 2 2 (S a') ++ pair_runs 5 2 1 ++ pair_runs 3 2 (S m')
        ++ pair_runs 2 2 1 ++ pair_runs 4 2 (S V') ++ [(1,4%nat)])
  = Some (([], 0,
           pair_runs 2 2 (S (S a'))
             ++ (1,4%nat)::(0,1%nat)::(1,3%nat)::(0,1%nat)
             :: pair_runs 4 1 m' ++ pair_runs 6 2 1
             ++ pair_runs 4 2 (S (S V')) ++ [(1,4%nat)]),
          (10 * N.of_nat a' + 10 * N.of_nat m' + 28 * N.of_nat V' + 131)%N).
Proof.
  pose proof (FTripC_kernel_all (repeat 0%nat a') _ _ _ _ _
                (FTripC_farC m' V')) as HK.
  rewrite repeat_length, csuml_repeat in HK.
  replace (3 * a' + (2 * m' + 6 * V' + 23) + 5)%nat
    with (3 * a' + 2 * m' + 6 * V' + 28)%nat in HK by lia.
  cbn [uword] in HK.
  rewrite !uword_zeros_app in HK.
  rewrite uword_app in HK.
  cbn [uword] in HK.
  rewrite uword_threes_app in HK.
  rewrite uword_fours_app in HK.
  rewrite (pair_runsE 4%nat 1%nat m') in HK.
  cbn [pair_runs app] in HK |- *.
  rewrite <- ?app_assoc in HK.
  rewrite <- ?app_assoc.
  replace (10 * N.of_nat a' + 10 * N.of_nat m' + 28 * N.of_nat V' + 131)%N
    with (10 * N.of_nat m' + 28 * N.of_nat V' + 115
          + N.of_nat a' * cpair 0%nat + 16)%N
    by (unfold cpair; change (N.of_nat 0) with 0%N; lia).
  exact HK.
Qed.
