Lemma eat0_runc (k : nat) (L R : wside) :
  wrunc (4 * k) (pair_runs 2%nat 2%nat k ++ L) S0
       ((1,5%nat)::(0,1%nat)::(1,4%nat)::(0,1%nat)::R)
  = Some ((L, S0,
           (1,5%nat)::(0,1%nat)::(1,4%nat)::(0,1%nat)
             :: pair_runs 3%nat 1%nat k ++ R), (24 * N.of_nat k)%N).
