Lemma dmarkF_uc (T : wside) (ks : list nat) (n : nat) (r0 : wside) :
  wrunc 3 ((0,1%nat)::(1,2%nat)::(0,1%nat)::(1,4%nat)
            ::(0,2%nat)::(1,2%nat)::T) 1 (wpush 0 1 (uword ks ((1,S n)::r0)))
  = Some ((((1,2%nat)::T), 0,
           (1,5%nat)::(0,1%nat)::(1,3%nat)::(0,2%nat)
             :: uword ks ((1,S n)::r0)), 16%N).
Proof.
  destruct (uword_one_headed ks n r0) as (p & q & E).
  rewrite E. apply dmarkFc.
Qed.
Lemma dtickFc (l : wside) :
  wrunc 1 l 0 ((1,4%nat)::(0,1%nat)::(1,4%nat)::(@nil run))
  = Some ((vpush 2%nat l, 1, [(1,3%nat)]), 6%N).
Proof.
  change ((1,4%nat)::(0,1%nat)::(1,4%nat)::(@nil run))
    with ((1,(2+2)%nat)::(0,1%nat)::(1,S (S 2))::(@nil run)).
  rewrite wrunc_1, wfuelcross. ccost_close.
Qed.
Lemma dtickF4c (l r : wside) :
  wrunc 1 l 0 ((1,4%nat)::(0,1%nat)::(1,4%nat)::r)
  = Some ((vpush 2%nat l, 1, (1,3%nat)::r), 6%N).
Proof.
  change ((1,4%nat)::(0,1%nat)::(1,4%nat)::r)
    with ((1,(2+2)%nat)::(0,1%nat)::(1,S (S 2))::r).
  rewrite wrunc_1, wfuelcross. ccost_close.
Qed.
Lemma dfar1c (T : wside) :
  wrunc 2 ((0,1%nat)::(1,1%nat)::(0,1%nat)::(1,2%nat)::T) 0 [(1,4%nat)]
  = Some ((((1,1%nat)::(0,1%nat)::(1,2%nat)
             ::(0,1%nat)::(1,1%nat)::(0,1%nat)::(1,2%nat)::T), 1,
           [(1,4%nat)]), 12%N).
Proof. reflexivity. Qed.
Lemma dfarGc (G : nat) (Z : wside) :
  wrunc (2 * G + 2)
       (vstackC (repeat 2%nat G) ((0,1%nat)::(1,1%nat)::(0,1%nat)
                                    ::(1,2%nat)::Z)) 0 [(1,4%nat)]
  = Some ((((1,1%nat)::(0,1%nat)::(1,2%nat)
             ::(0,1%nat)::(1,1%nat)::(0,1%nat)::(1,2%nat)::Z), 1,
           uword (repeat 2%nat G) [(1,4%nat)]),
          (8 * N.of_nat G + 12)%N).
Proof.
  destruct G as [|G].
  - cbn [repeat vstackC uword Nat.mul Nat.add].
    change (N.of_nat 0) with 0%N.
    rewrite dfar1c. ccost_close.
  - set (Z1 := (0,1%nat)::(1,1%nat)::(0,1%nat)::(1,2%nat)::Z).
    replace (2 * S G + 2)%nat
      with (2 + 2 * List.length (repeat 2%nat (S G)))%nat
      by (rewrite repeat_length; lia).
    rewrite (vstackC2_cons G Z1).
    rewrite wrunc_add, dfarA4c.
    lazy beta iota.
    rewrite <- (vstackC2_cons G Z1).
    rewrite (vstackC2_shift (S G) Z1).
    rewrite wback_runc.
    lazy beta iota.
    rewrite emit_uword, rev_repeat.
    rewrite csuml_repeat. unfold cback.
    change (N.of_nat 2) with 2%N.
    unfold Z1.
    ccost_close.
Qed.
Lemma dmintA_uc (Z : wside) (ks : list nat) (n : nat) (r0 : wside) :
  wrunc 2 ((1,1%nat)::(0,1%nat)::(1,2%nat)::(0,1%nat)::(1,1%nat)
            ::(0,1%nat)::(1,2%nat)::Z) 1 (uword ks ((1,S n)::r0))
  = Some ((((0,1%nat)::(1,2%nat)::Z), 1,
           (1,4%nat)::(0,2%nat):: uword ks ((1,S n)::r0)), 8%N).
Proof.
  destruct (uword_one_headed ks n r0) as (p & q & E).
  rewrite E. apply dmintAc.
Qed.
Lemma spanfar3_tripc (k V' : nat) :
  wrunc (5 * k + 6 * V' + 24) [] 0
       (pair_runs 2 2 (k+3) ++ pair_runs 4 2 (S V') ++ [(1,3%nat)])
  = Some (([], 0,
           (1,5%nat)::(0,1%nat)::(1,4%nat)::(0,1%nat)
             :: pair_runs 3 1 (S k) ++ (1,2%nat)::(0,2%nat)
             :: pair_runs 4 2 V' ++ (1,4%nat)::(0,1%nat)::[(1,3%nat)]),
          (28 * N.of_nat k + 28 * N.of_nat V' + 126)%N).
Proof.
  apply (ccost_pin _ _ _ _ _ _ (spanfar3_trip k V')).
  eexists.
  replace (5 * k + 6 * V' + 24)%nat
    with (List.length (repeat 0%nat (k+3) ++ repeat 2%nat (S V'))
          + (2 + (2 * S V' + (1 + (1 + (List.length (repeat 2%nat V')
             + (1 + (2 * S V' + (3 + (4 + 4 * S k))))))))))%nat
    by (rewrite length_app, !repeat_length; lia).
  rewrite <- uword_fours_app, <- uword_zeros_app, <- uword_app.
  rewrite wrunc_add, wcross_mixedc.
  lazy beta iota.
  rewrite (vstack_vstackC _ [] I).
  rewrite rev_app_distr, rev_repeat, rev_repeat0.
  rewrite vstackC_app.
  set (Zn := vstackC (repeat 0%nat (k+3)) []).
  rewrite (vstackC2_cons V' Zn).
  erewrite wrunc_split by apply dfar3c.
  rewrite <- (vstackC2_cons V' Zn).
  rewrite (vstackC2_shift (S V') Zn).
  rewrite wrunc_add.
  rewrite wbackFc.
  lazy beta iota.
  unfold Zn.
  replace (k+3)%nat with (S (k+2)) by lia.
  rewrite vstack0_cons.
  rewrite wrunc_add, dentryF_uc.
  lazy beta iota.
  rewrite wrunc_add, dcrossCc.
  lazy beta iota.
  rewrite wrunc_add, wcross_mixedc.
  lazy beta iota.
  rewrite (vstack_vstackC _ _ (zheaded0 _ _)), rev_repeat.
  set (W0 := (0,1%nat)::(1,2%nat)::(0,1%nat)::(1,4%nat)
               :: vstackC (repeat 0%nat (k+2)) []).
  erewrite wrunc_split by apply dtickFc.
  assert (HZ : zheaded (vstackC (repeat 2%nat V') W0))
    by (apply vstackC_zheaded; unfold W0; reflexivity).
  rewrite (vpairC_vpush 2%nat _ HZ).
  change (vpairC 2%nat (vstackC (repeat 2%nat V') W0))
    with (vstackC (repeat 2%nat (S V')) W0).
  unfold W0.
  erewrite wrunc_split
    by apply (wbackFc V' ((0,1%nat)::(1,4%nat)
                           :: vstackC (repeat 0%nat (k+2)) []) 2%nat
                (@nil run)).
  lazy beta iota.
  unfold W0.
  replace (k+2)%nat with (S (k+1)) by lia.
  rewrite vstack0_cons.
  rewrite wrunc_add, dmarkF_uc.
  lazy beta iota.
  rewrite cons12_vstack0.
  replace (k+1)%nat with (S k) by lia.
  cbn [pair_runs app].
  rewrite wrunc_add, eat0_firstc.
  lazy beta iota.
  rewrite eat0_run_closec.
  f_equal. f_equal.
  rewrite csuml_app, !csuml_repeat.
  unfold ccross.
  change (N.of_nat 0) with 0%N. change (N.of_nat 2) with 2%N.
  rewrite ?Nat2N.inj_add, ?Nat2N.inj_succ.
  change (N.of_nat 3) with 3%N.
  lia.
Qed.
Lemma spanfar4_tripc (k V' G : nat) :
  wrunc (5 * k + 6 * V' + 3 * G + 27) [] 0
       (pair_runs 2 2 (k+3) ++ pair_runs 4 2 (S V')
          ++ (1,3%nat)::(0,2%nat):: pair_runs 4 2 G ++ [(1,4%nat)])
  = Some (([], 0,
           (1,5%nat)::(0,1%nat)::(1,4%nat)::(0,1%nat)
             :: pair_runs 3 1 (S k) ++ (1,2%nat)::(0,2%nat)
             :: pair_runs 4 2 V' ++ (1,4%nat)::(0,1%nat)
             :: (1,3%nat)::(0,2%nat):: pair_runs 4 2 G ++ [(1,4%nat)]),
          (28 * N.of_nat k + 28 * N.of_nat V' + 14 * N.of_nat G + 140)%N).
Proof.
  apply (ccost_pin _ _ _ _ _ _ (spanfar4_trip k V' G)).
  eexists.
  rewrite <- uword_span4_in.
  replace (5 * k + 6 * V' + 3 * G + 27)%nat
    with (List.length (repeat 0%nat (k+3) ++ repeat 2%nat (S V')
                         ++ 1%nat :: repeat 2%nat G)
          + ((2 * G + 2)
             + (2 + (2 * S V' + (1 + (1 + (List.length (repeat 2%nat V')
                + (1 + (2 * S V' + (3 + (4 + 4 * S k))))))))))) %nat
    by (rewrite !length_app; cbn [List.length];
        rewrite !repeat_length; lia).
  rewrite wrunc_add, wcross_mixedc.
  lazy beta iota.
  rewrite (vstack_vstackC _ [] I).
  rewrite !rev_app_distr.
  cbn [rev].
  rewrite !rev_repeat, rev_repeat0.
  rewrite !vstackC_app.
  set (Zk := vstackC (repeat 0%nat (k+3)) []).
  set (ZV := vstackC (repeat 2%nat (S V')) Zk).
  change (vstackC [1%nat] ZV)
    with ((0,1%nat)::(1,1%nat)::(0,1%nat)::(1,2%nat)::ZV).
  rewrite wrunc_add, dfarGc.
  lazy beta iota.
  rewrite wrunc_add, dmintA_uc.
  lazy beta iota.
  unfold ZV.
  rewrite (vstackC2_shift (S V') Zk).
  rewrite wrunc_add, wbackFc.
  lazy beta iota.
  unfold Zk.
  replace (k+3)%nat with (S (k+2)) by lia.
  rewrite vstack0_cons.
  rewrite wrunc_add, dentryF_uc.
  lazy beta iota.
  rewrite wrunc_add, dcrossCc.
  lazy beta iota.
  rewrite wrunc_add, wcross_mixedc.
  lazy beta iota.
  rewrite (vstack_vstackC _ _ (zheaded0 _ _)), rev_repeat.
  set (W0 := (0,1%nat)::(1,2%nat)::(0,1%nat)::(1,4%nat)
               :: vstackC (repeat 0%nat (k+2)) []).
  rewrite wrunc_add, dtickF4c.
  lazy beta iota.
  assert (HZ : zheaded (vstackC (repeat 2%nat V') W0))
    by (apply vstackC_zheaded; unfold W0; reflexivity).
  rewrite (vpairC_vpush 2%nat _ HZ).
  change (vpairC 2%nat (vstackC (repeat 2%nat V') W0))
    with (vstackC (repeat 2%nat (S V')) W0).
  unfold W0.
  rewrite wrunc_add, wbackFc.
  lazy beta iota.
  replace (k+2)%nat with (S (k+1)) by lia.
  rewrite vstack0_cons.
  rewrite wrunc_add, dmarkF_uc.
  lazy beta iota.
  rewrite cons12_vstack0.
  replace (k+1)%nat with (S k) by lia.
  cbn [pair_runs app].
  rewrite wrunc_add, eat0_firstc.
  lazy beta iota.
  rewrite eat0_run_closec.
  f_equal. f_equal.
  rewrite !csuml_app.
  cbn [csuml].
  rewrite !csuml_repeat.
  unfold ccross.
  change (N.of_nat 0) with 0%N. change (N.of_nat 1) with 1%N.
  change (N.of_nat 2) with 2%N.
  rewrite ?Nat2N.inj_add, ?Nat2N.inj_succ.
  change (N.of_nat 3) with 3%N.
  lia.
Qed.
