Lemma djump_hopsc (k : nat) (Z : wside) (p : nat) (q : wside) :
  wrunc (2 * k) ((1,1%nat)::(0,1%nat)::(1,2%nat)
                   :: vstackC (repeat 2%nat k) Z)
       1 ((1,S p)::q)
  = Some ((((1,1%nat)::(0,1%nat)::(1,2%nat)::Z), 1, fourk k ((1,S p)::q)),
          (8 * N.of_nat k)%N).
Proof.
  rewrite <- (vstack1_shift k Z).
  exact (djump_hops2c k ((0,1%nat)::(1,2%nat)::Z) p q).
Qed.
Lemma d203_endc (L : wside) :
  wrunc 1 ((0,1%nat)::L) 0 [(1,4%nat)]
  = Some ((((0,1%nat)::(1,2%nat)::(0,1%nat)::(1,2%nat)::(0,1%nat)::L),
           0, []), 6%N).
Proof. reflexivity. Qed.
Lemma d203_turnc (L : wside) :
  wrunc 2 ((0,1%nat)::(1,2%nat)::(0,1%nat)::(1,2%nat)::L) 0 []
  = Some ((((0,1%nat)::(1,2%nat)::L), 1, [(0,1%nat);(1,4%nat)]), 9%N).
Proof. reflexivity. Qed.
Lemma d357_mintXc (X' : nat) (Z : wside) (p : nat) (q : wside) :
  wrunc 5 ((0,1%nat)::(1,2%nat)::(0,1%nat)::(1,6%nat)
            ::(0,1%nat)::(1,(3+X')%nat)::(0,1%nat)::(1,2%nat)::Z) 1
    ((0,1%nat)::(1,S p)::q)
  = Some ((((1,1%nat)::Z), 1,
           (1,(4+X')%nat)::(0,1%nat)::(1,6%nat)::(0,1%nat)
             ::(1,3%nat)::(0,2%nat)::(1,S p)::q),
          (N.of_nat X' + 28)%N).
Proof.
  apply (ccost_pin _ _ _ _ _ _ (d357_mintX X' Z p q)).
  eexists. destruct X' as [|[|d]]; ckerc.
Qed.
Lemma FTripC_jump (c : nat) (K : N) (Win : wside) (p : nat) (q : wside)
      (h' nb : nat) :
  FTripC c K Win p q ->
  FTripC (c + 3 * h' + 3 * nb + 12)
    (K + 14 * N.of_nat h' + 14 * N.of_nat nb + 72)%N
    (uword ((6%nat :: repeat 2%nat h') ++ [2%nat])
       ((1,4%nat)::(0,3%nat)::(1,4%nat)::(0,2%nat)
          :: uword (repeat 2%nat nb) Win))
    6
    ((0,1%nat)::(1,3%nat)::(0,2%nat)
       :: uword (repeat 2%nat h' ++ [2%nat])
            ((1,8%nat)::(0,2%nat)
               :: uword (repeat 2%nat nb) ((1,S p)::q))).
Proof.
  intros HT zb y Z.
  replace (c + 3 * h' + 3 * nb + 12)%nat
    with (List.length ((6%nat :: repeat 2%nat h') ++ [2%nat])
          + (2 + (nb + (c + (2 * nb + (2
             + ((2 * h' + 2) + 4)))))))%nat
    by (rewrite !length_app; cbn [List.length];
        rewrite !repeat_length; lia).
  rewrite wrunc_add, wcross_mixedc.
  lazy beta iota.
  rewrite (vstack_vstackC _ _ (zheaded0 _ _)).
  rewrite rev_app_distr.
  cbn [rev app vstackC vpairC].
  rewrite rev_repeat.
  erewrite wrunc_split by apply (dborrow_inc 1 1).
  erewrite wrunc_split by apply d203_crossg_gc.
  destruct nb as [|nb'].
  { cbn [repeat vstackC].
    rewrite wrunc_add.
    rewrite (HT _ 5%nat).
    lazy beta iota.
    erewrite wrunc_split by apply (djump_hops2c 0).
    cbn [fourk].
    erewrite wrunc_split by apply djump_mint8c.
    replace (2 * h' + 2)%nat with (2 * S h')%nat by lia.
    rewrite vstackC_app.
    change ((0,1%nat)::(1,2%nat)::(0,1%nat)::(1,2%nat)
              :: vstackC (repeat 2%nat h')
                   (vstackC [6%nat] ((0,S zb)::(1,S y)::Z)))
      with (vstackC (repeat 2%nat (S h'))
              (vstackC [6%nat] ((0,S zb)::(1,S y)::Z))).
    erewrite wrunc_split by apply djump_hopsc.
    cbn [vstackC vpairC fourk].
    rewrite fourk_shift.
    rewrite djump_mint7c.
    rewrite fourk_uword.
    rewrite <- repeat2_S_last.
    lazy beta iota.
    f_equal. f_equal.
    cbn [csuml].
    rewrite csuml_repeat.
    unfold ccross.
    change (N.of_nat 6) with 6%N. change (N.of_nat 2) with 2%N.
    change (N.of_nat 0) with 0%N.
    rewrite !Nat2N.inj_succ.
    lia. }
  cbn [repeat vstackC vpairC].
  rewrite wrunc_add.
  rewrite (HT _ 1%nat).
  lazy beta iota.
  erewrite wrunc_split by apply (djump_hops2c (S nb')).
  rewrite fourk_uword.
  cbn [repeat uword].
  change ((2 + 2)%nat) with 4%nat.
  erewrite wrunc_split by apply djump_mint8c.
  replace (2 * h' + 2)%nat with (2 * S h')%nat by lia.
  rewrite vstackC_app.
  change ((0,1%nat)::(1,2%nat)::(0,1%nat)::(1,2%nat)
            :: vstackC (repeat 2%nat h')
                 (vstackC [6%nat] ((0,S zb)::(1,S y)::Z)))
    with (vstackC (repeat 2%nat (S h'))
            (vstackC [6%nat] ((0,S zb)::(1,S y)::Z))).
  erewrite wrunc_split by apply djump_hopsc.
  cbn [vstackC vpairC fourk].
  rewrite fourk_shift.
  rewrite djump_mint7c.
  rewrite fourk_uword.
  rewrite <- repeat2_S_last.
  lazy beta iota.
  f_equal. f_equal.
  cbn [csuml].
  rewrite csuml_repeat.
  unfold ccross.
  change (N.of_nat 6) with 6%N. change (N.of_nat 2) with 2%N.
  rewrite !Nat2N.inj_succ.
  lia.
Qed.
Lemma FTripC_jump0 (c : nat) (K : N) (Win : wside) (p : nat) (q : wside)
      (nb : nat) :
  FTripC c K Win p q ->
  FTripC (c + 3 * nb + 9) (K + 14 * N.of_nat nb + 58)%N
    ((1,8%nat)::(0,2%nat)
       ::(1,4%nat)::(0,3%nat)::(1,4%nat)::(0,2%nat)
       :: uword (repeat 2%nat nb) Win)
    6
    ((0,1%nat)::(1,3%nat)::(0,2%nat)
       ::(1,8%nat)::(0,2%nat)
       :: uword (repeat 2%nat nb) ((1,S p)::q)).
Proof.
  intros HT zb y Z.
  change ((1,8%nat)::(0,2%nat)
            ::(1,4%nat)::(0,3%nat)::(1,4%nat)::(0,2%nat)
            :: uword (repeat 2%nat nb) Win)
    with (uword [6%nat]
            ((1,4%nat)::(0,3%nat)::(1,4%nat)::(0,2%nat)
               :: uword (repeat 2%nat nb) Win)).
  replace (c + 3 * nb + 9)%nat
    with (List.length [6%nat]
          + (2 + (nb + (c + (2 * nb + (2 + 4))))))%nat
    by (cbn [List.length]; lia).
  rewrite wrunc_add, wcross_mixedc.
  lazy beta iota.
  rewrite (vstack_vstackC _ _ (zheaded0 _ _)).
  cbn [rev app vstackC vpairC].
  erewrite wrunc_split by apply (dborrow_inc 1 5).
  erewrite wrunc_split by apply d203_crossg_gc.
  destruct nb as [|nb'].
  { cbn [repeat vstackC].
    rewrite wrunc_add.
    rewrite (HT _ 5%nat).
    lazy beta iota.
    erewrite wrunc_split by apply (djump_hops2c 0).
    cbn [fourk].
    erewrite wrunc_split by apply djump_mint8c.
    rewrite djump_mint7c.
    cbn [uword].
    lazy beta iota.
    f_equal. f_equal.
    cbn [csuml]. unfold ccross.
    change (N.of_nat 6) with 6%N. change (N.of_nat 0) with 0%N.
    lia. }
  cbn [repeat vstackC vpairC].
  rewrite wrunc_add.
  rewrite (HT _ 1%nat).
  lazy beta iota.
  erewrite wrunc_split by apply (djump_hops2c (S nb')).
  rewrite fourk_uword.
  cbn [repeat uword].
  change ((2 + 2)%nat) with 4%nat.
  erewrite wrunc_split by apply djump_mint8c.
  rewrite djump_mint7c.
  lazy beta iota.
  f_equal. f_equal.
  cbn [csuml]. unfold ccross.
  change (N.of_nat 6) with 6%N.
  rewrite !Nat2N.inj_succ.
  lia.
Qed.
Lemma FTripC_birthXg (X' dI : nat) :
  FTripC (3 * dI + 10) (2 * N.of_nat X' + 14 * N.of_nat dI + 59)%N
    ((1,(5+X')%nat)::(0,3%nat):: uword (repeat 2%nat (S dI)) [(1,4%nat)])
    ((3+X')%nat)
    ((0,1%nat)::(1,6%nat)::(0,1%nat)::(1,3%nat)::(0,2%nat)
       :: uword (repeat 2%nat dI) [(1,4%nat)]).
Proof.
  intros zb y Z.
  replace (3 * dI + 10)%nat
    with (2 + (dI + (1 + (2 + (2 * dI + 5)))))%nat by lia.
  cbn [repeat uword].
  erewrite wrunc_split by apply (d357_inXvc X' _ y).
  erewrite wrunc_split by apply d203_crossg_gc.
  destruct dI as [|dI'].
  { erewrite wrunc_split by apply d203_endc.
    erewrite wrunc_split by apply d203_turnc.
    erewrite wrunc_split by apply (d203_hopsc _ 0 1).
    cbn [fourk].
    rewrite d357_mintXc.
    lazy beta iota.
    change (N.of_nat 0) with 0%N.
    ccost_close. }
  cbn [repeat vstackC vpairC].
  erewrite wrunc_split by apply d203_endc.
  erewrite wrunc_split by apply d203_turnc.
  rewrite <- (vstack1_shift dI').
  change ((0,1%nat)::(1,2%nat)::(0,1%nat)::(1,2%nat)
            :: vstackC (repeat 2%nat dI')
                 ((0,1%nat)::(1,2%nat)::(0,1%nat)::(1,6%nat)
                    ::(0,1%nat)::(1,(3+X')%nat)::(0,1%nat)::(1,2%nat)
                    ::(0,S zb)::(1,S y)::Z))
    with (vstackC (repeat 2%nat (S dI'))
            ((0,1%nat)::(1,2%nat)::(0,1%nat)::(1,6%nat)
               ::(0,1%nat)::(1,(3+X')%nat)::(0,1%nat)::(1,2%nat)
               ::(0,S zb)::(1,S y)::Z)).
  erewrite wrunc_split by apply (d203_hopsc _ (S dI') 1).
  rewrite fourk_uword.
  cbn [repeat uword].
  change ((2 + 2)%nat) with 4%nat.
  rewrite d357_mintXc.
  lazy beta iota.
  cbn [repeat uword].
  rewrite !Nat2N.inj_succ.
  ccost_close.
Qed.
Lemma wcolcost_app (a b : word) :
  wcolcost (a ++ b) = (wcolcost a + wcolcost b)%N.
Proof. induction a as [|g t IH]; cbn [wcolcost app]; lia. Qed.
Lemma FTripC_cost_eq (c : nat) (K K' : N) (W : wside) (p : nat) (q : wside) :
  K = K' -> FTripC c K W p q -> FTripC c K' W p q.
Proof. intros <- H. exact H. Qed.
Lemma clift_is_col (g : bg) : clift g = true -> is_col g = true.
Proof.
  unfold clift. intros H.
  apply andb_prop in H. destruct H as (H & _).
  apply andb_prop in H. exact (proj1 H).
Qed.
Lemma forallb_clift_is_col (l : word) :
  forallb clift l = true -> forallb is_col l = true.
Proof.
  induction l as [|g t IH]; cbn [forallb]; [reflexivity|].
  intros H. apply andb_prop in H. destruct H as (Hg & Ht).
  rewrite (clift_is_col g Hg), (IH Ht). reflexivity.
Qed.
Lemma ren_liftc_col (ini sfx tail : word) (f f2 : N)
    (c p : nat) (K : N) (q : wside) :
  forallb is_col ini = true ->
  FTripC c K (sdec sfx f) p q ->
  wconf [] 0 ((1,S p)::q) = wconf [] 0 (sdec tail f2) ->
  exists c2 p2 q2,
    FTripC c2 (K + wcolcost ini)%N (sdec (ini ++ sfx) f) p2 q2
    /\ wconf [] 0 ((1,S p2)::q2) = wconf [] 0 (sdec (ini ++ tail) f2).
Proof.
  intros HB HF EQ.
  destruct (FTripC_cols2 ini c K (sdec sfx f) p q HB HF)
    as (c2 & p2 & q2 & HF2 & EQ2).
  exists c2, p2, q2. split; [rewrite sdec_app; exact HF2|].
  rewrite EQ2, sdec_app.
  apply wconf_app_cong. exact EQ.
Qed.
Lemma ren_liftc (ini sfx tail : word) (f f2 : N)
    (c p : nat) (K : N) (q : wside) :
  forallb (fun g => is_col g && negb (is_cmf g)
                    && (3 <=? gO g)%N) ini = true ->
  FTripC c K (sdec sfx f) p q ->
  wconf [] 0 ((1,S p)::q) = wconf [] 0 (sdec tail f2) ->
  exists c2 p2 q2,
    FTripC c2 (K + wcolcost ini)%N (sdec (ini ++ sfx) f) p2 q2
    /\ wconf [] 0 ((1,S p2)::q2) = wconf [] 0 (sdec (ini ++ tail) f2).
Proof.
  intros HB HF EQ.
  exact (ren_liftc_col ini sfx tail f f2 c p K q
           (forallb_clift_is_col ini HB) HF EQ).
Qed.
Lemma ren_jumpc_col (ini : word) (gbc B : N) (h1 nb : nat)
    (sfx tail : word) (f f2 : N) (c p : nat) (K : N) (q : wside) :
  forallb is_col ini = true ->
  N.to_nat gbc = S h1 -> N.to_nat B = S nb ->
  FTripC c K (sdec sfx f) p q ->
  wconf [] 0 ((1,S p)::q) = wconf [] 0 (sdec tail f2) ->
  exists c2 p2 q2,
    FTripC c2
      (K + 14 * N.of_nat h1 + 14 * N.of_nat nb + 72 + wcolcost ini)%N
      (sdec ((ini ++ [(8,2,1)%N; (4,2,gbc)%N])
               ++ (4,3,1)%N :: (4,2,B)%N :: sfx) f) p2 q2
    /\ wconf [] 0 ((1,S p2)::q2)
       = wconf [] 0
           (sdec ((ini ++ [(7,1,1)%N; (3,2,1)%N; (4,2,gbc)%N; (8,2,1)%N]
                     ++ (if (1 <? B)%N then [(4,2,(B-1))%N] else []))
                    ++ tail) f2).
Proof.
  intros HPI EH EB HF EQ.
  pose proof (FTripC_jump c K (sdec sfx f) p q h1 nb HF) as HT.
  cbn [uword app] in HT.
  rewrite !uword_rep2_snoc, !uword_repeat_w in HT.
  flatapp.
  refine (ren_liftc_col ini _ _ _ _ _ _ _ _ HPI _ _).
  - rewrite !sdec_cons.
    rewrite EH, EB.
    change (N.to_nat 8) with 8%nat.
    change (N.to_nat 4) with 4%nat.
    change (N.to_nat 3) with 3%nat.
    change (N.to_nat 2) with 2%nat.
    change (N.to_nat 1) with 1%nat.
    cbn [pair_runs app].
    flatapp.
    exact HT.
  - rewrite !sdec_cons, sdec_app.
    rewrite EH.
    change (N.to_nat 8) with 8%nat.
    change (N.to_nat 7) with 7%nat.
    change (N.to_nat 4) with 4%nat.
    change (N.to_nat 3) with 3%nat.
    change (N.to_nat 2) with 2%nat.
    change (N.to_nat 1) with 1%nat.
    destruct ((1 <? B)%N) eqn:ELT.
    { apply N.ltb_lt in ELT.
      assert (EBm : N.to_nat (B - 1)%N = nb)
        by (rewrite N2Nat.inj_sub, EB;
            change (N.to_nat 1) with 1%nat; lia).
      cbn [map gdecode expand].
      rewrite EBm.
      cbn [pair_runs app].
      flatapp.
      rewrite ?app_nil_r.
      repeat (first [exact EQ | apply wconf_app_cong
                    | apply wconf_cons_cong]). }
    apply N.ltb_ge in ELT.
    assert (EB1x : B = 1%N) by lia. subst B.
    assert (ENB0 : nb = 0%nat) by (cbn in EB; lia). subst nb.
    cbn [map gdecode expand].
    cbn [pair_runs app].
    flatapp.
    rewrite ?app_nil_r.
    repeat (first [exact EQ | apply wconf_app_cong
                  | apply wconf_cons_cong]).
Qed.
Lemma ren_jumpc (ini : word) (gbc B : N) (h1 nb : nat)
    (sfx tail : word) (f f2 : N) (c p : nat) (K : N) (q : wside) :
  forallb (fun g => is_col g && negb (is_cmf g)
                    && (3 <=? gO g)%N) ini = true ->
  N.to_nat gbc = S h1 -> N.to_nat B = S nb ->
