      (K + 14 * N.of_nat h1 + 14 * N.of_nat nb + 72 + wcolcost ini)%N
      (sdec ((ini ++ [(8,2,1)%N; (4,2,gbc)%N])
               ++ (4,3,1)%N :: (4,2,B)%N :: sfx) f) p2 q2
    /\ wconf [] 0 ((1,S p2)::q2)
       = wconf [] 0
           (sdec ((ini ++ [(7,1,1)%N; (3,2,1)%N; (4,2,gbc)%N; (8,2,1)%N]
                     ++ (if (1 <? B)%N then [(4,2,(B-1))%N] else []))
