Lemma ren_jumpUc_col (P blk sfx tail : word) (B f f2 : N)
    (c p : nat) (K : N) (q : wside) :
  forallb is_col P = true ->
  jblk blk ->
  (1 <= B)%N ->
  FTripC c K (sdec sfx f) p q ->
  wconf [] 0 ((1,S p)::q) = wconf [] 0 (sdec tail f2) ->
  exists c2 p2 q2,
    FTripC c2 (K + wcolcost (P ++ (8,2,1)%N :: blk) + 14 * B + 22)%N
      (sdec ((P ++ (8,2,1)%N :: blk)
               ++ (4,3,1)%N :: (4,2,B)%N :: sfx) f) p2 q2
    /\ wconf [] 0 ((1,S p2)::q2)
       = wconf [] 0
           (sdec ((P ++ (7,1,1)%N :: (3,2,1)%N :: blk ++ (8,2,1)%N
                     :: (if (1 <? B)%N then [(4,2,(B-1))%N] else []))
                    ++ tail) f2).
Proof.
  intros HP HBLK EB1 HF EQ.
  destruct (to_nat_ge1 B EB1) as [nb EB].
  destruct HBLK as [-> | (gbc & -> & EGB1)].
  - cbn [app].
    destruct (ren_jump0c_col P B nb sfx tail f f2 c p K q HP EB HF EQ)
      as (c2 & p2 & q2 & HF2 & EQ2).
    exists c2, p2, q2. split; [|exact EQ2].
    refine (FTripC_cost_eq _ _ _ _ _ _ _ HF2).
    rewrite wcolcost_app. cbn [wcolcost gC gO].
    rewrite <- (N2Nat.id B), EB, Nat2N.inj_succ. lia.
  - destruct (to_nat_ge1 gbc EGB1) as [h1 EH].
    cbn [app].
    destruct (ren_jumpc_col P gbc B h1 nb sfx tail f f2 c p K q
                HP EH EB HF EQ)
      as (c2 & p2 & q2 & HF2 & EQ2).
    exists c2, p2, q2. split; [|exact EQ2].
    refine (FTripC_cost_eq _ _ _ _ _ _ _ HF2).
    rewrite wcolcost_app. cbn [wcolcost gC gO].
    rewrite <- (N2Nat.id B), EB, <- (N2Nat.id gbc), EH,
            !Nat2N.inj_succ. lia.
Qed.
Lemma ren_jumpUc (P blk sfx tail : word) (B f f2 : N)
    (c p : nat) (K : N) (q : wside) :
  forallb (fun g => is_col g && negb (is_cmf g)
                    && (3 <=? gO g)%N) P = true ->
  jblk blk ->
  (1 <= B)%N ->
  FTripC c K (sdec sfx f) p q ->
  wconf [] 0 ((1,S p)::q) = wconf [] 0 (sdec tail f2) ->
  exists c2 p2 q2,
    FTripC c2 (K + wcolcost (P ++ (8,2,1)%N :: blk) + 14 * B + 22)%N
      (sdec ((P ++ (8,2,1)%N :: blk)
               ++ (4,3,1)%N :: (4,2,B)%N :: sfx) f) p2 q2
    /\ wconf [] 0 ((1,S p2)::q2)
       = wconf [] 0
           (sdec ((P ++ (7,1,1)%N :: (3,2,1)%N :: blk ++ (8,2,1)%N
                     :: (if (1 <? B)%N then [(4,2,(B-1))%N] else []))
                    ++ tail) f2).
Proof.
  intros HP HBLK EB1 HF EQ.
  exact (ren_jumpUc_col P blk sfx tail B f f2 c p K q
           (forallb_clift_is_col P HP) HBLK EB1 HF EQ).
Qed.
Lemma casc_jump_innerc_col (cols sfx tail seg : word) (B f f2 : N)
    (ci pi : nat) (K : N) (qi : wside) :
  forallb is_col cols = true ->
  jump_seg cols B = Some seg ->
  (1 <= B)%N ->
  FTripC ci K (sdec sfx f) pi qi ->
  wconf [] 0 ((1,S pi)::qi) = wconf [] 0 (sdec tail f2) ->
  exists c p q,
    FTripC c (K + wcolcost cols + 14 * B + 22)%N
      (sdec (cols ++ (4,3,1)%N :: (4,2,B)%N :: sfx) f) p q
    /\ wconf [] 0 ((1,S p)::q) = wconf [] 0 (sdec (seg ++ tail) f2).
Proof.
  intros HPC EJS EB1 HFi EQi.
  destruct (jump_seg_split cols seg B EJS)
    as (P & blk & ECOLS & ESEG & HBLK & _).
  subst cols seg.
  exact (ren_jumpUc_col P blk sfx tail B f f2 ci pi K qi
           (jsplit_iscol P blk HPC) HBLK EB1 HFi EQi).
Qed.
Lemma casc_jump_innerc (cols sfx tail seg : word) (B f f2 : N)
