Lemma casc_stagec (X cY : N) (rest TAIL : word) (f f2 : N)
    (c p : nat) (K : N) (q : wside) :
  (5 <= X)%N -> (1 <= cY)%N ->
  FTripC c K (sdec rest f) p q ->
  wconf [] 0 ((1,S p)::q) = wconf [] 0 (sdec TAIL f2) ->
  exists c2 p2 q2,
    FTripC c2 (K + 2 * X + 14 * cY + 14)%N
      (sdec ((X,3,1)%N :: (4,2,cY)%N :: rest) f) p2 q2
    /\ wconf [] 0 ((1,S p2)::q2)
       = wconf [] 0
           (sdec ((X-1,1,1)%N :: (7,2,1)%N :: (4,2,(cY-1))%N :: TAIL) f2).
Proof.
  intros E5 EC1 HF EQ.
  exists (c + 3 * N.to_nat (cY-1)%N + 6)%nat, (3 + N.to_nat (X-5)%N)%nat,
    ((0,1%nat)::(1,7%nat)::(0,2%nat)
       :: uword (repeat 2%nat (N.to_nat (cY-1)%N)) ((1,S p)::q)).
  split.
  - rewrite !sdec_cons.
    change (N.to_nat 3) with 3%nat. change (N.to_nat 4) with 4%nat.
    change (N.to_nat 2) with 2%nat. change (N.to_nat 1) with 1%nat.
    rewrite (NtoS5 X E5), (NtoSc cY EC1).
    cbn [pair_runs app].
    rewrite <- uword2_pair.
    replace (K + 2 * X + 14 * cY + 14)%N
      with (K + 2 * N.of_nat (N.to_nat (X-5)%N)
            + 14 * N.of_nat (N.to_nat (cY-1)%N) + 38)%N
      by (rewrite !N2Nat.id; lia).
    exact (FTripC_stageXg (N.to_nat (X-5)%N) c K (sdec rest f) p q
             (N.to_nat (cY-1)%N) HF).
  - rewrite !sdec_cons.
    change (N.to_nat 7) with 7%nat.
    change (N.to_nat 2) with 2%nat. change (N.to_nat 1) with 1%nat.
    rewrite (NtoS4 X E5), uword2_pair.
    cbn [pair_runs app].
    change (N.to_nat 4) with 4%nat.
    repeat apply wconf_cons_cong.
    apply wconf_app_cong. exact EQ.
Qed.
Lemma casc_stage_sandc (X cY : N) (rest TAIL : word) (f f2 : N)
