Lemma retag8_stagec (X : N) (rest TAIL : word) (f f2 : N)
    (c p : nat) (K : N) (q : wside) :
  (5 <= X)%N ->
  FTripC c K (sdec rest f) p q ->
  wconf [] 0 ((1,S p)::q) = wconf [] 0 (sdec TAIL f2) ->
  exists c2 p2 q2,
    FTripC c2 (K + 2 * X + 36)%N
      (sdec ((X,3,1)%N :: (8,2,1)%N :: rest) f) p2 q2
    /\ wconf [] 0 ((1,S p2)::q2)
       = wconf [] 0 (sdec ((X-1,1,1)%N :: (11,2,1)%N :: TAIL) f2).
Proof.
  intros E5 HF EQ.
  exists (c + 6)%nat, (3 + N.to_nat (X-5)%N)%nat,
    ((0,1%nat)::(1,11%nat)::(0,2%nat)::(1,S p)::q).
  split.
  - rewrite !sdec_cons.
    change (N.to_nat 3) with 3%nat. change (N.to_nat 8) with 8%nat.
    change (N.to_nat 2) with 2%nat. change (N.to_nat 1) with 1%nat.
    rewrite (NtoS5 X E5).
    cbn [pair_runs app].
    replace (K + 2 * X + 36)%N
      with (K + 2 * N.of_nat (N.to_nat (X-5)%N) + 46)%N
      by (rewrite !N2Nat.id; lia).
    exact (FTripC_retag8 (N.to_nat (X-5)%N) c K (sdec rest f) p q HF).
  - rewrite !sdec_cons.
    change (N.to_nat 11) with 11%nat.
    change (N.to_nat 2) with 2%nat. change (N.to_nat 1) with 1%nat.
    rewrite (NtoS4 X E5).
    cbn [pair_runs app].
    repeat apply wconf_cons_cong.
    exact EQ.
Qed.
Definition FCPropC (n : nat) : Prop :=
  forall (s : word) (f : N) (s' : word) (f2 : N)
         (d : cost) (k : nat),
  cfire_comp n s f = (Some (s', f2), d) ->
  cin k d ->
  exists c p q,
    FTripC c (N.of_nat k) (sdec s f) p q
    /\ wconf [] 0 ((1,S p)::q) = wconf [] 0 (sdec s' f2).
Definition RNPropC (n : nat) : Prop :=
  forall (cols s : word) (f : N) (body : word) (f2 : N)
         (d : cost) (k : nat),
  forallb (fun g => is_col g && negb (is_cmf g)
                    && (3 <=? gO g)%N) cols = true ->
  crenew_seg n cols s f = (Some (body, f2), d) ->
  cin k d ->
  exists c p q,
    FTripC c (N.of_nat k) (sdec (cols ++ s) f) p q
    /\ wconf [] 0 ((1,S p)::q) = wconf [] 0 (sdec body f2).
Lemma FCPropC_0 : FCPropC 0.
Proof. intros s f s' f2 d k H. cbn in H. discriminate. Qed.
Lemma RNPropC_0 : RNPropC 0.
Proof. intros cols s f body f2 d k _ H. cbn in H. discriminate. Qed.
Lemma cundef_absurd (k : nat) (P : Prop) : cin k cundef -> P.
Proof. intros H. destruct (cin_cundef k H). Qed.
Lemma cadd_cundef_absurd (k : nat) (d : cost) (P : Prop) :
  cexact_or_empty d -> cin k (cadd cundef d) -> P.
Proof.
  intros HE H. exfalso.
  unfold cexact_or_empty, cin, cadd, cundef, clo, chi in *;
    cbn [fst snd] in *. lia.
Qed.
Lemma cin_cx_eq (k : nat) (K : N) : cin k (cx K) -> N.of_nat k = K.
Proof. unfold cin, cx; cbn [fst snd]. lia. Qed.
Lemma casc_farc (X f : N) :
  (5 <= X)%N -> (2 <= f)%N ->
  exists c p q,
    FTripC c (2 * X + 2 * f + 27)%N (sdec [(X,3,1)%N] f) p q
    /\ wconf [] 0 ((1,S p)::q)
       = wconf [] 0 (sdec [((X-1)%N,1,1)%N; ((f+2)%N,1,1)%N] 3).
Proof.
  intros E5 F2.
  exists 7%nat, (3 + N.to_nat (X - 5)%N)%nat,
    ((0,1%nat)::(1,(4 + N.to_nat (f - 2)%N)%nat)::(0,1%nat)::[(1,3%nat)]).
  split.
  - unfold sdec.
    cbn [map gdecode expand app frun pair_runs].
    change (N.to_nat 3) with 3%nat.
    change (N.to_nat 1) with 1%nat.
    rewrite (NtoS5 X E5), (frun_pos f ltac:(lia)).
    rewrite (NtoS2f f F2).
    cbn [pair_runs app].
    refine (FTripC_cost_eq _ _ _ _ _ _ _
              (FTripC_403 (N.to_nat (X - 5)%N) (N.to_nat (f - 2)%N))).
    rewrite !N2Nat.id. lia.
  - unfold sdec.
    cbn [map gdecode expand app frun pair_runs].
    change (N.to_nat 3) with 3%nat.
    change (N.to_nat 1) with 1%nat.
    rewrite (NtoS4 X E5).
    rewrite (NtoS4f f F2).
    cbn [pair_runs app].
    reflexivity.
Qed.
Lemma casc_z1endc (X Y f : N) :
  (5 <= X)%N -> (1 <= Y)%N -> (2 <= f)%N ->
  exists c p q,
    FTripC c (2 * X + 2 * Y + 17)%N (sdec [(X,3,1)%N; (Y,1,1)%N] f) p q
    /\ wconf [] 0 ((1,S p)::q)
       = wconf [] 0 (sdec [((X-1)%N,1,1)%N; ((Y+3)%N,1,1)%N] (f-1)%N).
Proof.
  intros E5 GY F2.
  exists 5%nat, (3 + N.to_nat (X - 5)%N)%nat,
    ((0,1%nat)::(1,(4 + N.to_nat (Y - 1)%N)%nat)::(0,1%nat)
       ::[(1,(1 + N.to_nat (f - 2)%N)%nat)]).
  split.
  - unfold sdec.
    cbn [map gdecode expand app].
    rewrite (frun_pos f ltac:(lia)).
    change (N.to_nat 3) with 3%nat. change (N.to_nat 1) with 1%nat.
    rewrite (NtoS5 X E5), (NtoS1y Y GY), (NtoS2f f F2).
    cbn [pair_runs app].
    refine (FTripC_cost_eq _ _ _ _ _ _ _
              (FTripC_408g (N.to_nat (X - 5)%N) (N.to_nat (Y - 1)%N)
                           (N.to_nat (f - 2)%N))).
    rewrite !N2Nat.id. lia.
  - unfold sdec.
    cbn [map gdecode expand app].
    rewrite (frun_pos (f - 1)%N ltac:(lia)).
    change (N.to_nat 1) with 1%nat.
    rewrite (NtoS4 X E5), (NtoS4y Y GY), (NtoS1m f F2).
    cbn [pair_runs app].
    reflexivity.
Qed.
Lemma casc_z1lvlc (X Y c2 : N) (r2 : word) (f : N) :
  (5 <= X)%N -> (1 <= Y)%N -> (1 <= c2)%N ->
  exists c p q,
    FTripC c (2 * X + 2 * Y + 17)%N
      (sdec ((X,3,1)%N :: (Y,1,1)%N :: (4,2,c2)%N :: r2) f) p q
    /\ wconf [] 0 ((1,S p)::q)
       = wconf [] 0
           (sdec ((X-1,1,1)%N :: ((Y+3)%N,1,1)%N :: (3,2,1)%N
                  :: (if (1 <? c2)%N then [(4,2,(c2-1))%N] else []) ++ r2) f).
Proof.
  intros E5 GY GC2.
  exists 5%nat, (3 + N.to_nat (X - 5)%N)%nat,
    ((0,1%nat)::(1,(4 + N.to_nat (Y - 1)%N)%nat)::(0,1%nat)
       ::(1,3%nat)::(0,2%nat)
       :: (pair_runs 4%nat 2%nat (N.to_nat (c2 - 1)%N) ++ sdec r2 f)).
  split.
  - rewrite !sdec_cons.
    change (N.to_nat 3) with 3%nat. change (N.to_nat 1) with 1%nat.
