Lemma casc_z1splitc (X Y cY : N) (rest1 : word) (f : N) :
  (5 <= X)%N -> (2 <= Y)%N -> (2 <= cY)%N ->
  exists c p q,
    FTripC c (2 * X + 2 * Y + 17)%N
      (sdec ((X,3,1)%N :: (Y,1,cY)%N :: rest1) f) p q
    /\ wconf [] 0 ((1,S p)::q)
       = wconf [] 0
           (sdec ((X-1,1,1)%N :: ((Y+3)%N,1,1)%N :: ((Y-1)%N,1,1)%N
                  :: (if (2 <? cY)%N then [(Y,1,(cY-2))%N] else [])
                     ++ rest1) f).
Proof.
  intros E5 GY2 GCY.
  exists 5%nat, (3 + N.to_nat (X - 5)%N)%nat,
    ((0,1%nat)::(1,(5 + N.to_nat (Y - 2)%N)%nat)::(0,1%nat)
       ::(1,(1 + N.to_nat (Y - 2)%N)%nat)::(0,1%nat)
       :: (pair_runs (2 + N.to_nat (Y - 2)%N)%nat 1%nat
             (N.to_nat (cY - 2)%N) ++ sdec rest1 f)).
  split.
  - rewrite !sdec_cons.
    change (N.to_nat 3) with 3%nat. change (N.to_nat 1) with 1%nat.
    rewrite (NtoS2f cY GCY), pair_runs_2.
    rewrite (NtoS5 X E5), (NtoS2f Y GY2).
    cbn [pair_runs app].
    refine (FTripC_cost_eq _ _ _ _ _ _ _
              (FTripC_Esplit (N.to_nat (X - 5)%N) (N.to_nat (Y - 2)%N)
                 (pair_runs (2 + N.to_nat (Y - 2)%N)%nat 1%nat
                    (N.to_nat (cY - 2)%N) ++ sdec rest1 f))).
    rewrite !N2Nat.id. lia.
  - rewrite !sdec_cons, sdec_optk.
    change (N.to_nat 1) with 1%nat.
    rewrite (NtoS4 X E5), (NtoS5y Y GY2), (NtoS1m Y GY2), (NtoS2f Y GY2).
    cbn [pair_runs app].
    reflexivity.
Qed.
Lemma casc_z1z1c (X Y k0 : N) (r2 : word) (f : N) :
  (5 <= X)%N -> (1 <= Y)%N -> (1 <= k0)%N ->
  exists c p q,
    FTripC c (2 * X + 2 * Y + 17)%N
      (sdec ((X,3,1)%N :: (Y,1,1)%N :: (k0,1,1)%N :: r2) f) p q
    /\ wconf [] 0 ((1,S p)::q)
       = wconf [] 0
           (sdec (if (k0 =? 1)%N
                  then (X-1,1,1)%N :: ((Y+3)%N,2,1)%N :: r2
                  else (X-1,1,1)%N :: ((Y+3)%N,1,1)%N
                       :: ((k0-1)%N,1,1)%N :: r2) f).
Proof.
  intros E5 GY GK.
  destruct (k0 =? 1)%N eqn:EK1.
  { apply N.eqb_eq in EK1. subst k0.
    exists 5%nat, (3 + N.to_nat (X - 5)%N)%nat,
      ((0,1%nat)::(1,(4 + N.to_nat (Y - 1)%N)%nat)::(0,2%nat) :: sdec r2 f).
    split.
    - rewrite !sdec_cons.
      change (N.to_nat 3) with 3%nat. change (N.to_nat 1) with 1%nat.
      rewrite (NtoS5 X E5), (NtoS1y Y GY).
      cbn [pair_runs app].
      refine (FTripC_cost_eq _ _ _ _ _ _ _
                (FTripC_F1 (N.to_nat (X - 5)%N) (N.to_nat (Y - 1)%N)
                   (sdec r2 f))).
      rewrite !N2Nat.id. lia.
    - rewrite !sdec_cons.
      change (N.to_nat 1) with 1%nat. change (N.to_nat 2) with 2%nat.
      rewrite (NtoS4 X E5), (NtoS4y Y GY).
      cbn [pair_runs app].
      reflexivity. }
  assert (K2 : (2 <= k0)%N) by (apply N.eqb_neq in EK1; lia).
  exists 5%nat, (3 + N.to_nat (X - 5)%N)%nat,
    ((0,1%nat)::(1,(4 + N.to_nat (Y - 1)%N)%nat)::(0,1%nat)
       ::(1,(1 + N.to_nat (k0 - 2)%N)%nat)::(0,1%nat) :: sdec r2 f).
  split.
  - rewrite !sdec_cons.
    change (N.to_nat 3) with 3%nat. change (N.to_nat 1) with 1%nat.
    rewrite (NtoS5 X E5), (NtoS1y Y GY), (NtoS2f k0 K2).
    cbn [pair_runs app].
    refine (FTripC_cost_eq _ _ _ _ _ _ _
              (FTripC_Fk (N.to_nat (X - 5)%N) (N.to_nat (Y - 1)%N)
                 (N.to_nat (k0 - 2)%N) (sdec r2 f))).
    rewrite !N2Nat.id. lia.
  - rewrite !sdec_cons.
    change (N.to_nat 1) with 1%nat.
    rewrite (NtoS4 X E5), (NtoS4y Y GY), (NtoS1m k0 K2).
    cbn [pair_runs app].
    reflexivity.
Qed.
Lemma casc_z1z2c (X Y b0 : N) (r2 : word) (f : N) :
  (5 <= X)%N -> (1 <= Y)%N -> (1 <= b0)%N ->
  exists c p q,
    FTripC c (2 * X + 2 * Y + 17)%N
      (sdec ((X,3,1)%N :: (Y,1,1)%N :: (b0,2,1)%N :: r2) f) p q
    /\ wconf [] 0 ((1,S p)::q)
       = wconf [] 0
           (sdec (if (b0 =? 1)%N
                  then (X-1,1,1)%N :: ((Y+3)%N,3,1)%N :: r2
                  else (X-1,1,1)%N :: ((Y+3)%N,1,1)%N
                       :: ((b0-1)%N,2,1)%N :: r2) f).
Proof.
  intros E5 GY GB.
  destruct (b0 =? 1)%N eqn:EB1.
  { apply N.eqb_eq in EB1. subst b0.
    exists 5%nat, (3 + N.to_nat (X - 5)%N)%nat,
      ((0,1%nat)::(1,(4 + N.to_nat (Y - 1)%N)%nat)::(0,3%nat) :: sdec r2 f).
    split.
    - rewrite !sdec_cons.
      change (N.to_nat 3) with 3%nat. change (N.to_nat 1) with 1%nat.
      change (N.to_nat 2) with 2%nat.
      rewrite (NtoS5 X E5), (NtoS1y Y GY).
      cbn [pair_runs app].
      refine (FTripC_cost_eq _ _ _ _ _ _ _
                (FTripC_G1 (N.to_nat (X - 5)%N) (N.to_nat (Y - 1)%N)
                   (sdec r2 f))).
      rewrite !N2Nat.id. lia.
    - rewrite !sdec_cons.
      change (N.to_nat 1) with 1%nat. change (N.to_nat 3) with 3%nat.
      rewrite (NtoS4 X E5), (NtoS4y Y GY).
      cbn [pair_runs app].
      reflexivity. }
  assert (B2 : (2 <= b0)%N) by (apply N.eqb_neq in EB1; lia).
  exists 5%nat, (3 + N.to_nat (X - 5)%N)%nat,
    ((0,1%nat)::(1,(4 + N.to_nat (Y - 1)%N)%nat)::(0,1%nat)
       ::(1,(1 + N.to_nat (b0 - 2)%N)%nat)::(0,2%nat) :: sdec r2 f).
  split.
  - rewrite !sdec_cons.
    change (N.to_nat 3) with 3%nat. change (N.to_nat 1) with 1%nat.
    change (N.to_nat 2) with 2%nat.
    rewrite (NtoS5 X E5), (NtoS1y Y GY), (NtoS2f b0 B2).
    cbn [pair_runs app].
    refine (FTripC_cost_eq _ _ _ _ _ _ _
              (FTripC_Gb (N.to_nat (X - 5)%N) (N.to_nat (Y - 1)%N)
                 (N.to_nat (b0 - 2)%N) (sdec r2 f))).
    rewrite !N2Nat.id. lia.
  - rewrite !sdec_cons.
    change (N.to_nat 1) with 1%nat. change (N.to_nat 2) with 2%nat.
    rewrite (NtoS4 X E5), (NtoS4y Y GY), (NtoS1m b0 B2).
    cbn [pair_runs app].
    reflexivity.
Qed.
Lemma casc_lvl_end4c (X cY : N) :
  (5 <= X)%N -> (1 <= cY)%N ->
  exists c p q,
    FTripC c (2 * X + 14 * cY + 35)%N
      (sdec ((X,3,1)%N :: (4,2,cY)%N :: []) 4) p q
    /\ wconf [] 0 ((1,S p)::q)
       = wconf [] 0
           (sdec ((X-1,1,1)%N :: (6,1,1)%N :: (3,2,1)%N
                  :: (if (1 <? cY)%N then [(4,2,(cY-1))%N] else [])) 4).
Proof.
  intros E5 EC1.
  exists (3 * N.to_nat (cY-1)%N + 10)%nat, (3 + N.to_nat (X-5)%N)%nat,
    ((0,1%nat)::(1,6%nat)::(0,1%nat)::(1,3%nat)::(0,2%nat)
       :: uword (repeat 2%nat (N.to_nat (cY-1)%N)) [(1,4%nat)]).
  split.
  - rewrite !sdec_cons, sdec_nil, (frun_pos 4 ltac:(lia)).
    change (N.to_nat 3) with 3%nat.
    change (N.to_nat 4) with 4%nat.
    change (N.to_nat 2) with 2%nat.
    change (N.to_nat 1) with 1%nat.
    rewrite (NtoS5 X E5), (NtoSc cY EC1).
    rewrite <- (uword2_pair (S (N.to_nat (cY-1)%N)) [(1,4%nat)]).
    cbn [pair_runs app].
    refine (FTripC_cost_eq _ _ _ _ _ _ _
              (FTripC_birthXg (N.to_nat (X-5)%N) (N.to_nat (cY-1)%N))).
    rewrite !N2Nat.id. lia.
  - rewrite !sdec_cons, sdec_lvl, sdec_cons, sdec_nil,
            (frun_pos 4 ltac:(lia)).
    change (N.to_nat 6) with 6%nat.
    change (N.to_nat 3) with 3%nat.
    change (N.to_nat 4) with 4%nat.
    change (N.to_nat 2) with 2%nat.
    change (N.to_nat 1) with 1%nat.
    rewrite (NtoS4 X E5), uword2_pair.
    cbn [pair_runs app].
    reflexivity.
Qed.
Lemma ren_far_tailc (cols2 : word) (f : N) :
  forallb (fun g => is_col g && negb (is_cmf g)
                    && (3 <=? gO g)%N) cols2 = true ->
  (5 <= f)%N ->
  exists c p q,
    FTripC c (2 * f + 13 + wcolcost cols2)%N (sdec cols2 f) p q
    /\ wconf [] 0 ((1,S p)::q)
       = wconf [] 0 (sdec (cols2 ++ [((f-1)%N,1,1)%N]) 3).
Proof.
  intros HCOLS2 EF5g.
  pose (wj := N.to_nat (f - 5)%N).
  assert (EF5 : N.to_nat f = (5 + wj)%nat)
    by (unfold wj; rewrite N2Nat.inj_sub;
        change (N.to_nat 5) with 5%nat; lia).
  assert (EFm : N.to_nat (f - 1)%N = (4 + wj)%nat)
    by (unfold wj; rewrite !N2Nat.inj_sub;
        change (N.to_nat 5) with 5%nat;
        change (N.to_nat 1) with 1%nat; lia).
  assert (HF0 : FTripC 4 (2 * f + 13)%N (sdec [] f) (3 + wj)%nat
                  ((0,1%nat)::[(1,3%nat)])).
  { unfold sdec. cbn [map expand app].
    rewrite (frun_pos f) by lia.
    rewrite EF5.
    refine (FTripC_cost_eq _ _ _ _ _ _ _ (FTripC_farbare wj)).
    unfold wj. rewrite N2Nat.inj_sub.
    change (N.to_nat 5) with 5%nat.
    rewrite Nat2N.inj_sub, N2Nat.id.
    change (N.of_nat 5) with 5%N. lia. }
  assert (EQ0 : wconf [] 0 ((1,(4 + wj)%nat)::(0,1%nat)::[(1,3%nat)])
                = wconf [] 0 (sdec [((f-1)%N,1,1)%N] 3)).
  { unfold sdec.
    cbn [map gdecode expand app frun].
    rewrite EFm.
    change (N.to_nat 1) with 1%nat.
    cbn [pair_runs app].
    reflexivity. }
  destruct (ren_liftc cols2 [] [((f-1)%N,1,1)%N] f 3 _ _ _ _
              HCOLS2 HF0 EQ0)
    as (c2 & p2 & q2 & HF2 & EQ2).
  rewrite (app_nil_r cols2) in HF2.
  exists c2, p2, q2. split; [exact HF2 | exact EQ2].
Qed.
Lemma casc_lvl_end5c (X cY f : N) :
  (5 <= X)%N -> (1 <= cY)%N -> (5 <= f)%N ->
  exists c p q,
    FTripC c (2 * X + 14 * cY + 2 * f + 27)%N
      (sdec ((X,3,1)%N :: (4,2,cY)%N :: []) f) p q
    /\ wconf [] 0 ((1,S p)::q)
       = wconf [] 0
           (sdec ((X-1,1,1)%N :: (7,2,1)%N :: (4,2,(cY-1))%N
                  :: [((f-1)%N,1,1)%N]) 3).
Proof.
  intros E5 EC1 EF5.
  destruct (ren_far_tailc [] f eq_refl EF5) as (ci & pi & qi & HFi & EQi).
  cbn [wcolcost] in HFi.
  destruct (casc_stagec X cY [] [((f-1)%N,1,1)%N] f 3 ci pi
              (2 * f + 13 + 0)%N qi E5 EC1 HFi EQi)
    as (c2 & p2 & q2 & HF2 & EQ2).
  exists c2, p2, q2. split; [|exact EQ2].
  refine (FTripC_cost_eq _ _ _ _ _ _ _ HF2). lia.
Qed.
Local Open Scope N_scope.
Local Open Scope N_scope.
