Lemma SandC_cols_exact (cols : word) (c : nat) (K : N)
      (Win W' : wside) :
  forallb (fun g => is_col g && negb (is_cmf g)
                    && (3 <=? gO g)%N) cols = true ->
  SandC c K Win W' ->
  (exists c2 p2 q2 (D : N),
      (D + 3 = wcolcost cols)%N
      /\ FTripC c2 (K + D)%N (expand (map gdecode cols) ++ Win) p2 q2
      /\ (1,S p2)::q2 = expand (map gdecode cols) ++ W')
  \/ (wcolcost cols = 0%N /\ expand (map gdecode cols) = []).
Proof.
  induction cols as [|g cols' IH]; intros HB HS.
  - right. split; reflexivity.
  - cbn [forallb] in HB. apply andb_prop in HB. destruct HB as (HG & HB').
    apply andb_prop in HG. destruct HG as (HG1 & HG3).
    apply andb_prop in HG1. destruct HG1 as (HCOL & _).
    destruct g as [[o z] cg].
    unfold is_col in HCOL. cbn [gZ gO] in *.
    apply andb_prop in HCOL. destruct HCOL as (HZ & _).
    apply N.eqb_eq in HZ. subst z.
    apply N.leb_le in HG3.
    assert (EW : exists w', N.to_nat o = (3 + w')%nat).
    { exists (N.to_nat o - 3)%nat. lia. }
    destruct EW as [w' EW].
    assert (EW2 : N.to_nat o = (2 + S w')%nat) by lia.
    destruct (IH HB' HS) as [(c2 & p2 & q2 & D & HD & HF2 & EQ2)|(HZC & ENIL)].
    +
      destruct (FTripC_walls (N.to_nat cg) w' c2 _ _ p2 q2 HF2)
        as (c3 & p3 & q3 & HF3 & EQ3).
      left. exists c3, p3, q3, (D + N.of_nat (N.to_nat cg) * cpair (S w'))%N.
      cbn [map gdecode expand wcolcost gC gO].
      change (N.to_nat 2) with 2%nat.
      rewrite EW.
      rewrite <- app_assoc.
      split.
      { rewrite (wcolcost_col o cg (S w') EW2). lia. }
      split.
      { refine (FTripC_cost_eq _ _ _ _ _ _ _ HF3). lia. }
      rewrite EQ3, EQ2, <- app_assoc. reflexivity.
    +
      cbn [map gdecode expand wcolcost gC gO].
      change (N.to_nat 2) with 2%nat.
      rewrite EW, ENIL, app_nil_r.
      destruct (N.to_nat cg) as [|k] eqn:ECG.
      * right.
        assert (ECg : cg = 0%N) by lia.
        rewrite ECg. split; [lia|].
        cbn [pair_runs app]. reflexivity.
      * left.
        destruct (SandC_walls k w' c K Win W' HS)
          as (c3 & p3 & q3 & HF3 & EQ3).
        exists c3, p3, q3,
          (2 * N.of_nat w' + 9 + N.of_nat k * cpair (S w'))%N.
        assert (ECg : cg = N.of_nat (S k))
          by (rewrite <- (N2Nat.id cg), ECG; reflexivity).
        assert (EO : o = (3 + N.of_nat w')%N).
        { rewrite <- (N2Nat.id o), EW, Nat2N.inj_add.
          change (N.of_nat 3) with 3%N. reflexivity. }
        split.
        { rewrite HZC, ECg, EO, Nat2N.inj_succ. unfold cpair.
          rewrite Nat2N.inj_succ. lia. }
        split.
        { refine (FTripC_cost_eq _ _ _ _ _ _ _ HF3). lia. }
        exact EQ3.
Qed.
Lemma ren_lift_sandc (ini sfx tail : word) (f f2 : N)
    (c p : nat) (K : N) (q : wside) :
  forallb (fun g => is_col g && negb (is_cmf g)
                    && (3 <=? gO g)%N) ini = true ->
  SandC c K (sdec sfx f) ((1,S p)::q) ->
  (1,S p)::q = sdec tail f2 ->
  (exists c2 p2 q2 (D : N),
      (D + 3 = wcolcost ini)%N
      /\ FTripC c2 (K + D)%N (sdec (ini ++ sfx) f) p2 q2
      /\ wconf [] 0 ((1,S p2)::q2) = wconf [] 0 (sdec (ini ++ tail) f2))
  \/ (wcolcost ini = 0%N
      /\ SandC c K (sdec (ini ++ sfx) f) ((1,S p)::q)
      /\ (1,S p)::q = sdec (ini ++ tail) f2).
Proof.
  intros HB HS EQ.
  destruct (SandC_cols_exact ini c K (sdec sfx f) ((1,S p)::q) HB HS)
    as [(c2 & p2 & q2 & D & HD & HF2 & EQ2)|(HZC & ENIL)].
  - left. exists c2, p2, q2, D.
    split; [exact HD|].
    split; [rewrite sdec_app; exact HF2|].
    rewrite EQ2, sdec_app, EQ. reflexivity.
  - right. split; [exact HZC|].
    rewrite !sdec_app, ENIL. cbn [app].
    split; [exact HS|exact EQ].
Qed.
Lemma casc_leaf_ftripc (X cY : N) (ini sfx tail : word) (f f2 : N)
    (c p : nat) (K : N) (q : wside) :
  (5 <= X)%N -> (1 <= cY)%N ->
  forallb (fun g => is_col g && negb (is_cmf g)
                    && (3 <=? gO g)%N) ini = true ->
  FTripC c K (sdec sfx f) p q ->
  wconf [] 0 ((1,S p)::q) = wconf [] 0 (sdec tail f2) ->
  exists c2 p2 q2,
    FTripC c2 (K + wcolcost ini + 2 * X + 14 * cY + 14)%N
      (sdec ((X,3,1)%N :: (4,2,cY)%N :: (ini ++ sfx)) f) p2 q2
    /\ wconf [] 0 ((1,S p2)::q2)
       = wconf [] 0
           (sdec ((X-1,1,1)%N :: (7,2,1)%N :: (4,2,(cY-1))%N
                  :: (ini ++ tail)) f2).
Proof.
  intros E5 EC1 HB HF EQ.
  destruct (ren_liftc ini sfx tail f f2 c p K q HB HF EQ)
    as (cL & pL & qL & HFL & EQL).
  destruct (casc_stagec X cY (ini ++ sfx) (ini ++ tail) f f2 cL pL
              (K + wcolcost ini)%N qL E5 EC1 HFL EQL)
    as (c2 & p2 & q2 & HF2 & EQ2).
  exists c2, p2, q2. split; [|exact EQ2].
  refine (FTripC_cost_eq _ _ _ _ _ _ _ HF2). lia.
Qed.
Lemma casc_leaf_sandc (X cY : N) (ini sfx tail : word) (f f2 : N)
    (c p : nat) (K : N) (q : wside) :
  (5 <= X)%N -> (1 <= cY)%N ->
  forallb (fun g => is_col g && negb (is_cmf g)
                    && (3 <=? gO g)%N) ini = true ->
  SandC c K (sdec sfx f) ((1,S p)::q) ->
  (1,S p)::q = sdec tail f2 ->
  exists c2 p2 q2,
    FTripC c2 (K + wcolcost ini + 2 * X + 14 * cY + 11)%N
      (sdec ((X,3,1)%N :: (4,2,cY)%N :: (ini ++ sfx)) f) p2 q2
    /\ wconf [] 0 ((1,S p2)::q2)
       = wconf [] 0
           (sdec ((X-1,1,1)%N :: (7,2,1)%N :: (4,2,(cY-1))%N
                  :: (ini ++ tail)) f2).
Proof.
  intros E5 EC1 HB HS EQ.
  destruct (ren_lift_sandc ini sfx tail f f2 c p K q HB HS EQ)
    as [(cL & pL & qL & D & HD & HFL & EQL)|(HZC & HSL & EQL)].
  - destruct (casc_stagec X cY (ini ++ sfx) (ini ++ tail) f f2 cL pL
                (K + D)%N qL E5 EC1 HFL EQL)
      as (c2 & p2 & q2 & HF2 & EQ2).
    exists c2, p2, q2. split; [|exact EQ2].
    refine (FTripC_cost_eq _ _ _ _ _ _ _ HF2). lia.
  - destruct (casc_stage_sandc X cY (ini ++ sfx) (ini ++ tail) f f2 c p
                K q E5 EC1 HSL EQL)
      as (c2 & p2 & q2 & HF2 & EQ2).
    exists c2, p2, q2. split; [|exact EQ2].
    refine (FTripC_cost_eq _ _ _ _ _ _ _ HF2). lia.
Qed.
Definition LeafFTripC (s : word) : Prop :=
  forall (f : N) (s' : word) (f2 : N) (d : cost) (k : nat),
    cleaf_act s f = (Some (s', f2), d) ->
    cin k d ->
    (exists (c p : nat) (q : wside) (K : N),
        N.of_nat k = (K + 6)%N
        /\ FTripC c K (sdec s f) p q
        /\ wconf [] 0 ((1,S p)::q) = wconf [] 0 (sdec s' f2))
    \/ (exists (c p : nat) (q : wside) (K : N),
        N.of_nat k = (K + 3)%N
        /\ SandC c K (sdec s f) ((1,S p)::q)
        /\ (1,S p)::q = sdec s' f2
        /\ sand_leaf s = true
        /\ f = 4%N).
Lemma cin_split_cx (k : nat) (K1 : N) (d2 : cost) :
  cin k (cadd (cx K1) d2) ->
  exists k2, N.of_nat k = (K1 + N.of_nat k2)%N /\ cin k2 d2.
Proof.
  unfold cin, cadd, cx; cbn [fst snd]. intros H.
  exists (k - N.to_nat K1)%nat. lia.
Qed.
Lemma casc_leaf_armc (X cY : N) (cols site s' : word) (f f2 : N)
      (dl : cost) (k : nat) :
  LeafFTripC site ->
  (5 <= X)%N -> (1 <= cY)%N ->
  forallb (fun g => is_col g && negb (is_cmf g)
                    && (3 <=? gO g)%N) cols = true ->
  cleaf_act site f = (Some (s', f2), dl) ->
  cin k (cadd (d_casc_leaf X cY cols) dl) ->
  exists c2 p2 q2,
    FTripC c2 (N.of_nat k)
      (sdec ((X,3,1)%N :: (4,2,cY)%N :: (cols ++ site)) f) p2 q2
    /\ wconf [] 0 ((1,S p2)::q2)
       = wconf [] 0
           (sdec ((X-1,1,1)%N :: (7,2,1)%N :: (4,2,(cY-1))%N
                  :: (cols ++ s')) f2).
Proof.
  intros HL E5 EC1 HB HLA Hk.
  unfold d_casc_leaf in Hk.
  destruct (cin_split_cx _ _ _ Hk) as (k2 & EK & Hk2).
  pose proof (ccolcost_wcolcost cols) as EWC.
  destruct (HL f s' f2 dl k2 HLA Hk2)
    as [(c & p & q & K & EKK & HT & EQ)
       |(c & p & q & K & EKK & HS & EQq & _ & _)].
  - destruct (casc_leaf_ftripc X cY cols site s' f f2 c p K q
                E5 EC1 HB HT EQ) as (c2 & p2 & q2 & HF2 & EQ2).
    exists c2, p2, q2. split; [|exact EQ2].
    refine (FTripC_cost_eq _ _ _ _ _ _ _ HF2). lia.
  - destruct (casc_leaf_sandc X cY cols site s' f f2 c p K q
                E5 EC1 HB HS EQq) as (c2 & p2 & q2 & HF2 & EQ2).
    exists c2, p2, q2. split; [|exact EQ2].
    refine (FTripC_cost_eq _ _ _ _ _ _ _ HF2). lia.
Qed.
Lemma casc_leaf_closec (X cY : N) (cols site : word) (f : N)
      (R : option (word * N)) (dl : cost)
      (s' : word) (f2 : N) (d : cost) (k : nat) :
  LeafFTripC site ->
  (5 <= X)%N -> (1 <= cY)%N ->
  forallb (fun g => is_col g && negb (is_cmf g)
                    && (3 <=? gO g)%N) cols = true ->
  cleaf_act site f = (R, dl) ->
  (match R with
   | Some (s2', f') =>
       Some ((X-1,1,1)%N :: (7,2,1)%N :: (4,2,(cY-1))%N :: cols ++ s2', f')
   | None => None
   end, cadd (d_casc_leaf X cY cols) dl) = (Some (s', f2), d) ->
  cin k d ->
  exists c2 p2 q2,
    FTripC c2 (N.of_nat k)
      (sdec ((X,3,1)%N :: (4,2,cY)%N :: (cols ++ site)) f) p2 q2
    /\ wconf [] 0 ((1,S p2)::q2) = wconf [] 0 (sdec s' f2).
Proof.
  intros HL E5 EC1 HB HR HFC Hk.
  destruct R as [[sa fa]|]; [|discriminate HFC].
  pose proof (f_equal fst HFC) as HW. cbn [fst] in HW.
  pose proof (f_equal snd HFC) as HD. cbn [snd] in HD.
  injection HW as HW1 HW2. subst s' f2.
  rewrite <- HD in Hk.
  exact (casc_leaf_armc X cY cols site sa f fa dl k HL E5 EC1 HB HR Hk).
Qed.
Lemma wcolcost_zero_counts (cols : word) :
  wcolcost cols = 0%N ->
  forallb (fun g => (gC g =? 0)%N) cols = true.
Proof.
  induction cols as [|g t IH]; cbn [wcolcost forallb]; [reflexivity|].
  intros H.
  assert (HP : (gC g * (2 * gO g + 6) = 0)%N) by lia.
  assert (HT : wcolcost t = 0%N) by lia.
  apply N.eq_mul_0 in HP.
  assert (HG : gC g = 0%N) by (destruct HP as [HP|HP]; lia).
  rewrite HG, N.eqb_refl, (IH HT). reflexivity.
Qed.
Lemma casc_leafj_armc (X cY Bq : N) (cols cols2 site s' seg : word)
      (f f2 : N) (dl : cost) (k : nat) :
  LeafFTripC site ->
  (5 <= X)%N -> (1 <= cY)%N -> (1 <= Bq)%N ->
  forallb is_col cols = true ->
  forallb (fun g => is_col g && negb (is_cmf g)
                    && (3 <=? gO g)%N) cols2 = true ->
  jump_seg cols Bq = Some seg ->
  sand_leaf site && forallb (fun g => (gC g =? 0)%N) cols2 = false ->
  cleaf_act site f = (Some (s', f2), dl) ->
  cin k (cadd (d_casc_leafj X cY cols Bq cols2) dl) ->
  exists c2 p2 q2,
    FTripC c2 (N.of_nat k)
      (sdec ((X,3,1)%N :: (4,2,cY)%N
             :: (cols ++ (4,3,1)%N :: (4,2,Bq)%N :: cols2 ++ site)) f) p2 q2
    /\ wconf [] 0 ((1,S p2)::q2)
       = wconf [] 0
           (sdec ((X-1,1,1)%N :: (7,2,1)%N :: (4,2,(cY-1))%N
                  :: (seg ++ cols2 ++ s')) f2).
Proof.
  intros HL E5 EC1 EB1 HBC HC2 EJS ESL HLA Hk.
  unfold d_casc_leafj in Hk.
  destruct (cin_split_cx _ _ _ Hk) as (k2 & EK & Hk2).
  pose proof (ccolcost_wcolcost cols) as EW1.
  pose proof (ccolcost_wcolcost cols2) as EW2.
  destruct (HL f s' f2 dl k2 HLA Hk2)
    as [(c & p & q & K & EKK & HT & EQ)
       |(c & p & q & K & EKK & HS & EQq & HSL & _)].
  - destruct (ren_liftc cols2 site s' f f2 c p K q HC2 HT EQ)
      as (cL & pL & qL & HFL & EQL).
    destruct (casc_jump_innerc_col cols (cols2 ++ site) (cols2 ++ s') seg
                Bq f f2 cL pL (K + wcolcost cols2)%N qL HBC EJS EB1 HFL EQL)
      as (cJ & pJ & qJ & HFJ & EQJ).
    destruct (casc_stagec X cY
                (cols ++ (4,3,1)%N :: (4,2,Bq)%N :: cols2 ++ site)
                (seg ++ cols2 ++ s') f f2 cJ pJ _ qJ E5 EC1 HFJ EQJ)
      as (c2 & p2 & q2 & HF2 & EQ2).
    exists c2, p2, q2. split; [|exact EQ2].
    refine (FTripC_cost_eq _ _ _ _ _ _ _ HF2). lia.
  - destruct (ren_lift_sandc cols2 site s' f f2 c p K q HC2 HS EQq)
      as [(cL & pL & qL & D & HD & HFL & EQL)|(HZC & _ & _)].
    + destruct (casc_jump_innerc_col cols (cols2 ++ site) (cols2 ++ s') seg
                  Bq f f2 cL pL (K + D)%N qL HBC EJS EB1 HFL EQL)
        as (cJ & pJ & qJ & HFJ & EQJ).
      destruct (casc_stagec X cY
                  (cols ++ (4,3,1)%N :: (4,2,Bq)%N :: cols2 ++ site)
                  (seg ++ cols2 ++ s') f f2 cJ pJ _ qJ E5 EC1 HFJ EQJ)
        as (c2 & p2 & q2 & HF2 & EQ2).
      exists c2, p2, q2. split; [|exact EQ2].
      refine (FTripC_cost_eq _ _ _ _ _ _ _ HF2). lia.
    + rewrite HSL, (wcolcost_zero_counts cols2 HZC) in ESL.
      discriminate ESL.
Qed.
Lemma casc_leafj_closec (X cY Bq : N) (cols cols2 site seg : word)
      (f : N) (R : option (word * N)) (dl : cost)
      (alt : option (word * N))
      (s' : word) (f2 : N) (d : cost) (k : nat) :
  LeafFTripC site ->
  (5 <= X)%N -> (1 <= cY)%N -> (1 <= Bq)%N ->
  forallb is_col cols = true ->
  forallb (fun g => is_col g && negb (is_cmf g)
                    && (3 <=? gO g)%N) cols2 = true ->
  jump_seg cols Bq = Some seg ->
  sand_leaf site && forallb (fun g => (gC g =? 0)%N) cols2 = false ->
  cleaf_act site f = (R, dl) ->
  (R = None ->
   (alt, d_casc_tail X cY cols Bq cols2 f) = (Some (s', f2), d) ->
   exists c2 p2 q2,
     FTripC c2 (N.of_nat k)
       (sdec ((X,3,1)%N :: (4,2,cY)%N
              :: (cols ++ (4,3,1)%N :: (4,2,Bq)%N :: cols2 ++ site)) f)
       p2 q2
     /\ wconf [] 0 ((1,S p2)::q2) = wconf [] 0 (sdec s' f2)) ->
  (match R with
   | Some (s2', f') =>
       (Some ((X-1,1,1)%N :: (7,2,1)%N :: (4,2,(cY-1))%N
              :: seg ++ cols2 ++ s2', f'),
        cadd (d_casc_leafj X cY cols Bq cols2) dl)
   | None => (alt, d_casc_tail X cY cols Bq cols2 f)
   end) = (Some (s', f2), d) ->
  cin k d ->
  exists c2 p2 q2,
    FTripC c2 (N.of_nat k)
      (sdec ((X,3,1)%N :: (4,2,cY)%N
             :: (cols ++ (4,3,1)%N :: (4,2,Bq)%N :: cols2 ++ site)) f) p2 q2
    /\ wconf [] 0 ((1,S p2)::q2) = wconf [] 0 (sdec s' f2).
Proof.
  intros HL E5 EC1 EB1 HBC HC2 EJS ESL HR Htail HFC Hk.
  destruct R as [[sa fa]|].
  2:{ exact (Htail eq_refl HFC). }
  pose proof (f_equal fst HFC) as HW. cbn [fst] in HW.
  pose proof (f_equal snd HFC) as HD. cbn [snd] in HD.
  injection HW as HW1 HW2. subst s' f2.
  rewrite <- HD in Hk.
  exact (casc_leafj_armc X cY Bq cols cols2 site sa seg f fa dl k
           HL E5 EC1 EB1 HBC HC2 EJS ESL HR Hk).
Qed.
Lemma cseg_split (cols : word) (pc gbc : N) :
  cseg cols = Some (pc, gbc) ->
  exists ini ga gb,
    last2 cols = Some (ini, ga, gb)
    /\ (( ga = (8,2,1)%N /\ gb = (4,2,gbc)%N /\ (1 <= gbc)%N
          /\ pc = ccolcost ini /\ forallb is_col ini = true )
        \/ ( gb = (8,2,1)%N /\ gbc = 0%N
             /\ pc = ccolcost (ini ++ [ga])
             /\ forallb is_col (ini ++ [ga]) = true )).
Proof.
  unfold cseg. intros HC.
  destruct (last2 cols)
    as [[[ini [[gao gaz] gac]] [[gbo gbz] gbc']]|] eqn:EL2; [|discriminate HC].
  destruct ((gao =? 8)%N && (gaz =? 2)%N && (gac =? 1)%N
            && (gbo =? 4)%N && (gbz =? 2)%N && (1 <=? gbc')%N
            && forallb is_col ini) eqn:EG1.
  { injection HC as <- <-.
    apply andb_prop in EG1. destruct EG1 as (EG1 & HBI).
    apply andb_prop in EG1. destruct EG1 as (EG1 & EGB1).
    apply andb_prop in EG1. destruct EG1 as (EG1 & EBZ).
    apply andb_prop in EG1. destruct EG1 as (EG1 & EBO).
    apply andb_prop in EG1. destruct EG1 as (EAOZ & EAC).
    apply andb_prop in EAOZ. destruct EAOZ as (EAO & EAZ).
    apply N.eqb_eq in EAO, EAZ, EAC, EBO, EBZ.
    apply N.leb_le in EGB1. subst gao gaz gac gbo gbz.
    exists ini, (8,2,1)%N, (4,2,gbc')%N.
    split; [reflexivity|].
    left. repeat split; assumption. }
  destruct ((gbo =? 8)%N && (gbz =? 2)%N && (gbc' =? 1)%N
            && forallb is_col (ini ++ [(gao,gaz,gac)%N])) eqn:EG2;
    [|discriminate HC].
  injection HC as <- <-.
  apply andb_prop in EG2. destruct EG2 as (EG2 & HBI).
  apply andb_prop in EG2. destruct EG2 as (EG2 & EBC).
  apply andb_prop in EG2. destruct EG2 as (EBO & EBZ).
  apply N.eqb_eq in EBO, EBZ, EBC. subst gbo gbz gbc'.
  exists ini, (gao,gaz,gac)%N, (8,2,1)%N.
  split; [reflexivity|].
  right. repeat split; assumption.
Qed.
Lemma ren_lift1c (ini : word) (a : bg) (sfx tail : word)
    (f f2 : N) (c p : nat) (K : N) (q : wside) :
  forallb is_col (ini ++ [a]) = true ->
  FTripC c K (sdec sfx f) p q ->
  wconf [] 0 ((1,S p)::q) = wconf [] 0 (sdec tail f2) ->
  exists c2 p2 q2,
    FTripC c2 (K + wcolcost (ini ++ [a]))%N (sdec (ini ++ a :: sfx) f) p2 q2
    /\ wconf [] 0 ((1,S p2)::q2)
       = wconf [] 0 (sdec (ini ++ a :: tail) f2).
Proof.
  intros HB HF EQ.
  rewrite (app_cons_snoc ini a sfx), (app_cons_snoc ini a tail).
  exact (ren_liftc_col (ini ++ [a]) sfx tail f f2 c p K q HB HF EQ).
Qed.
Lemma ren_lift1cc (ini : word) (a : bg) (sfx tail : word)
    (f f2 : N) (c p : nat) (K : N) (q : wside) :
  forallb is_col (ini ++ [a]) = true ->
  FTripC c K (sdec sfx f) p q ->
  wconf [] 0 ((1,S p)::q) = wconf [] 0 (sdec tail f2) ->
  exists c2 p2 q2,
    FTripC c2 (ccolcost (ini ++ [a]) + K)%N (sdec (ini ++ a :: sfx) f) p2 q2
    /\ wconf [] 0 ((1,S p2)::q2)
       = wconf [] 0 (sdec (ini ++ a :: tail) f2).
Proof.
  intros HB HF EQ.
  destruct (ren_lift1c ini a sfx tail f f2 c p K q HB HF EQ)
    as (c2 & p2 & q2 & HF2 & EQ2).
  exists c2, p2, q2. split; [|exact EQ2].
  refine (FTripC_cost_eq _ _ _ _ _ _ _ HF2).
  rewrite (ccolcost_wcolcost (ini ++ [a])). lia.
Qed.
Lemma FTripC_ex_cost_eq (K K' : N) (W T : wside) :
  K = K' ->
  (exists c p q, FTripC c K W p q
                 /\ wconf [] 0 ((1,S p)::q) = wconf [] 0 T) ->
  (exists c p q, FTripC c K' W p q
                 /\ wconf [] 0 ((1,S p)::q) = wconf [] 0 T).
Proof. intros <- H. exact H. Qed.
Lemma dseg_endR_tripc (cols body : word) (f : N) (k : nat) :
  endR_seg cols f = Some body ->
  cin k (dseg_endR cols f) ->
  exists c p q,
    FTripC c (N.of_nat k) (sdec (cols ++ [(4,3,1)%N]) f) p q
    /\ wconf [] 0 ((1,S p)::q) = wconf [] 0 (sdec body 3%N).
Proof.
  intros EES Hk.
  unfold dseg_endR in Hk.
  destruct (2 <=? f)%N eqn:EFb; [|exact (cundef_absurd _ _ Hk)].
  pose proof EFb as EF2b. apply N.leb_le in EF2b.
  unfold dseg in Hk.
  destruct (cseg cols) as [[pc gbc]|] eqn:ECS;
    [|exact (cundef_absurd _ _ Hk)].
  apply cin_cx_eq in Hk.
  unfold endR_seg in EES.
  destruct (cseg_split cols pc gbc ECS)
    as (ini & ga & gb & EL2 &
        [(EGA & EGB & EGB1 & EPC & HBI)|(EGB & EGB0 & EPC & HBI)]).
  -
    subst pc ga gb.
    pose proof (last2_split _ _ _ _ EL2) as ECOLS.
    rewrite EL2 in EES.
    assert (EGBb : (1 <=? gbc)%N = true) by (apply N.leb_le; exact EGB1).
    rewrite EGBb, EFb in EES.
    cbn [N.eqb Pos.eqb andb] in EES.
    injection EES as <-.
    destruct (to_nat_ge1 gbc EGB1) as [h1 EH].
    pose (fp := N.to_nat (f - 2)%N).
    assert (EF2 : N.to_nat f = (2 + fp)%nat)
      by (unfold fp; rewrite N2Nat.inj_sub;
          change (N.to_nat 2) with 2%nat; lia).
    assert (EF3 : N.to_nat (f + 3)%N = (5 + fp)%nat)
      by (unfold fp; rewrite N2Nat.inj_add, N2Nat.inj_sub;
          change (N.to_nat 2) with 2%nat;
          change (N.to_nat 3) with 3%nat; lia).
    clearbody fp.
    pose proof (FTripC_endR h1 fp) as HT.
    cbn [uword app] in HT.
    rewrite !uword_rep2_snoc in HT.
    change (pair_runs 4 2 (S h1))
      with ((1,4%nat)::(0,2%nat)::pair_runs 4 2 h1) in HT.
    cbn [app] in HT.
    rewrite ECOLS, <- app_assoc. cbn [app].
    refine (FTripC_ex_cost_eq
              ((14 * N.of_nat h1 + 2 * N.of_nat fp + 75)%N + wcolcost ini)%N
              _ _ _ _ _).
    { pose proof (ccolcost_wcolcost ini) as EW.
      rewrite Hk.
      assert (EGN : gbc = N.of_nat (S h1))
        by (rewrite <- (N2Nat.id gbc), EH; reflexivity).
      assert (EFN : f = N.of_nat (2 + fp))
        by (rewrite <- (N2Nat.id f), EF2; reflexivity).
      rewrite EGN, EFN, !Nat2N.inj_add, Nat2N.inj_succ.
      change (N.of_nat 2) with 2%N. change (N.of_nat 1) with 1%N.
      lia. }
    refine (ren_liftc_col ini
                [(8,2,1)%N; (4,2,gbc)%N; (4,3,1)%N]
                [(7,1,1)%N; (3,2,1)%N; (4,2,gbc)%N; ((f+3)%N,1,1)%N]
                f 3%N _ _ _ _ HBI _ _).
    { unfold sdec.
      rewrite (frun_pos f) by lia.
      cbn [map gdecode expand app].
      rewrite EH, EF2.
      change (N.to_nat 8) with 8%nat.
      change (N.to_nat 4) with 4%nat.
      change (N.to_nat 3) with 3%nat.
      change (N.to_nat 2) with 2%nat.
      change (N.to_nat 1) with 1%nat.
      cbn [pair_runs app].
      flatapp.
      rewrite ?app_nil_r.
      exact HT. }
    { unfold sdec.
      cbn [map gdecode expand app frun].
      rewrite EH, EF3.
      change (N.to_nat 7) with 7%nat.
      change (N.to_nat 4) with 4%nat.
      change (N.to_nat 3) with 3%nat.
      change (N.to_nat 2) with 2%nat.
      change (N.to_nat 1) with 1%nat.
      cbn [pair_runs app].
      flatapp.
      rewrite ?app_nil_r.
      reflexivity. }
  -
    subst pc gb gbc.
    destruct ga as [[gao gaz] gac].
    pose proof (last2_split _ _ _ _ EL2) as ECOLS.
    assert (EESb : body = ini ++ [(gao,gaz,gac)%N; (7,1,1)%N; (3,2,1)%N;
                                  ((f+3)%N,1,1)%N]).
    { rewrite EL2 in EES.
      destruct ((gao =? 8)%N && (gaz =? 2)%N && (gac =? 1)%N) eqn:EA3;
        try rewrite EA3 in EES; rewrite EFb in EES;
        cbn [N.eqb Pos.eqb andb] in EES;
        injection EES as <-; reflexivity. }
    subst body.
    pose (fp := N.to_nat (f - 2)%N).
    assert (EF2 : N.to_nat f = (2 + fp)%nat)
      by (unfold fp; rewrite N2Nat.inj_sub;
          change (N.to_nat 2) with 2%nat; lia).
    assert (EF3 : N.to_nat (f + 3)%N = (5 + fp)%nat)
      by (unfold fp; rewrite N2Nat.inj_add, N2Nat.inj_sub;
          change (N.to_nat 2) with 2%nat;
          change (N.to_nat 3) with 3%nat; lia).
    clearbody fp.
    pose proof (FTripC_endR0 fp) as HT.
    rewrite ECOLS, <- app_assoc. cbn [app].
    refine (FTripC_ex_cost_eq _ _ _ _ _ _).
    2:{ refine (ren_lift1cc ini _ _ _ f 3%N _ _
                  (2 * N.of_nat fp + 61)%N _ HBI _ _).
        { unfold sdec.
          rewrite (frun_pos f) by lia.
          cbn [map gdecode expand app].
          rewrite EF2.
          change (N.to_nat 8) with 8%nat.
          change (N.to_nat 4) with 4%nat.
          change (N.to_nat 3) with 3%nat.
          change (N.to_nat 2) with 2%nat.
          change (N.to_nat 1) with 1%nat.
          cbn [pair_runs app].
          rewrite ?app_nil_r.
          exact HT. }
        { unfold sdec.
          cbn [map gdecode expand app frun].
          rewrite EF3.
          change (N.to_nat 7) with 7%nat.
          change (N.to_nat 3) with 3%nat.
          change (N.to_nat 2) with 2%nat.
          change (N.to_nat 1) with 1%nat.
          cbn [pair_runs app].
          rewrite ?app_nil_r.
          reflexivity. } }
    rewrite Hk.
    assert (EFN : f = N.of_nat (2 + fp))
      by (rewrite <- (N2Nat.id f), EF2; reflexivity).
    rewrite EFN, !Nat2N.inj_add.
    change (N.of_nat 2) with 2%N.
    lia.
Qed.
Lemma last2_app2 (ini : word) (a b : bg) :
  last2 (ini ++ [a; b]) = Some (ini, a, b).
Proof.
  induction ini as [|g t IH]; [reflexivity|].
  cbn [app last2].
  destruct t as [|g2 t2]; [reflexivity|].
  cbn [app] in IH |- *. rewrite IH.
  destruct (t2 ++ [a; b]) eqn:E;
    [destruct t2; discriminate E|reflexivity].
Qed.
Lemma endR_seg_cons (g : bg) (cols body : word) (f : N) :
  endR_seg cols f = Some body ->
  endR_seg (g :: cols) f = Some (g :: body).
Proof.
  unfold endR_seg.
  destruct (last2 cols) as [[[ini a] b]|] eqn:EL2; [|discriminate].
  pose proof (last2_split _ _ _ _ EL2) as EC.
  assert (E2 : last2 (g :: cols) = Some (g :: ini, a, b))
    by (rewrite EC; apply (last2_app2 (g :: ini) a b)).
  rewrite E2.
  destruct a as [[gao gaz] gac], b as [[gbo gbz] gbc].
  destruct ((gao =? 8)%N && (gaz =? 2)%N && (gac =? 1)%N
            && (gbo =? 4)%N && (gbz =? 2)%N && (1 <=? gbc)%N && (2 <=? f)%N).
  { intros H. injection H as <-. cbn [app]. reflexivity. }
  destruct ((gbo =? 8)%N && (gbz =? 2)%N && (gbc =? 1)%N && (2 <=? f)%N);
    [|discriminate].
  intros H. injection H as <-. cbn [app]. reflexivity.
Qed.
Lemma cseg_endR_some (cols : word) (f : N) (k : nat) :
  cin k (dseg_endR cols f) -> exists body, endR_seg cols f = Some body.
Proof.
  unfold dseg_endR.
  destruct (2 <=? f)%N eqn:EFb;
    [|intros H; exact (cundef_absurd _ _ H)].
  unfold dseg.
  destruct (cseg cols) as [[pc gbc]|] eqn:ECS;
    [|intros H; exact (cundef_absurd _ _ H)].
  intros _.
  destruct (cseg_split cols pc gbc ECS)
    as (ini & ga & gb & EL2 &
        [(EGA & EGB & EGB1 & _ & _)|(EGB & _ & _ & _)]).
  - subst ga gb. unfold endR_seg. rewrite EL2.
    assert (EGBb : (1 <=? gbc)%N = true) by (apply N.leb_le; exact EGB1).
    rewrite EGBb, EFb. cbn [N.eqb Pos.eqb andb].
    eexists. reflexivity.
  - subst gb. destruct ga as [[gao gaz] gac].
    unfold endR_seg. rewrite EL2.
    destruct ((gao =? 8)%N && (gaz =? 2)%N && (gac =? 1)%N) eqn:EA3;
      try rewrite EA3; rewrite EFb; cbn [N.eqb Pos.eqb andb];
      eexists; reflexivity.
Qed.
Lemma jump_seg_cons (g : bg) (cols seg : word) (B : N) :
  jump_seg cols B = Some seg ->
  jump_seg (g :: cols) B = Some (g :: seg).
Proof.
  unfold jump_seg.
  destruct (last2 cols) as [[[ini a] b]|] eqn:EL2; [|discriminate].
  pose proof (last2_split _ _ _ _ EL2) as EC.
  assert (E2 : last2 (g :: cols) = Some (g :: ini, a, b))
    by (rewrite EC; apply (last2_app2 (g :: ini) a b)).
  rewrite E2.
  destruct a as [[gao gaz] gac], b as [[gbo gbz] gbc].
  destruct ((gao =? 8)%N && (gaz =? 2)%N && (gac =? 1)%N
            && (gbo =? 4)%N && (gbz =? 2)%N && (1 <=? gbc)%N).
  { intros H. injection H as <-. cbn [app]. reflexivity. }
  destruct ((gbo =? 8)%N && (gbz =? 2)%N && (gbc =? 1)%N); [|discriminate].
  intros H. injection H as <-. cbn [app]. reflexivity.
Qed.
Lemma lawR_seg_cons (g : bg) (cols seg : word) (B : N) :
  lawR_seg cols B = Some seg ->
  lawR_seg (g :: cols) B = Some (g :: seg).
Proof.
  unfold lawR_seg.
  destruct (last2 cols) as [[[ini a] b]|] eqn:EL2; [|discriminate].
  pose proof (last2_split _ _ _ _ EL2) as EC.
  assert (E2 : last2 (g :: cols) = Some (g :: ini, a, b))
    by (rewrite EC; apply (last2_app2 (g :: ini) a b)).
  rewrite E2.
  destruct a as [[gao gaz] gac], b as [[gbo gbz] gbc].
  destruct ((gao =? 8)%N && (gaz =? 2)%N && (gac =? 1)%N
            && (gbo =? 4)%N && (gbz =? 2)%N && (1 <=? gbc)%N).
  { intros H. injection H as <-. cbn [app]. reflexivity. }
  destruct ((gbo =? 8)%N && (gbz =? 2)%N && (gbc =? 1)%N); [|discriminate].
  intros H. injection H as <-. cbn [app]. reflexivity.
Qed.
Lemma jump_comp_JMP (pre post body : word) (B f f2 : N)
      (kd : ckind) :
  jump_comp pre B post f = Some (kd, body, f2) -> kd = JMP.
Proof.
  unfold jump_comp.
  repeat (match goal with
          | |- context [ match ?x with _ => _ end ] => destruct x
          | |- context [ if ?b then _ else _ ] => destruct b
          end);
    intros H; try discriminate H;
    (pose proof (f_equal (fun o : option (ckind * word * N) =>
                            match o with
                            | Some (kk, _, _) => kk
                            | None => JMP
                            end) H) as EK;
     cbn in EK; exact (eq_sym EK)).
Qed.
Lemma jump_lawR_seg_both (cols seg : word) (B : N) :
  jump_seg cols B = Some seg ->
  exists b, lawR_seg cols B = Some b.
Proof.
  unfold jump_seg, lawR_seg.
  destruct (last2 cols) as [[[ini a] b]|]; [|discriminate].
  destruct a as [[gao gaz] gac], b as [[gbo gbz] gbc].
  destruct ((gao =? 8)%N && (gaz =? 2)%N && (gac =? 1)%N
            && (gbo =? 4)%N && (gbz =? 2)%N && (1 <=? gbc)%N);
    [intros _; eexists; reflexivity|].
  destruct ((gbo =? 8)%N && (gbz =? 2)%N && (gbc =? 1)%N);
    [intros _; eexists; reflexivity|discriminate].
Qed.
Lemma cseg_seg_some (cols : word) (pc gbc B : N) :
  cseg cols = Some (pc, gbc) ->
  exists s, jump_seg cols B = Some s.
Proof.
  intros HC.
  destruct (cseg_split cols pc gbc HC)
    as (ini & ga & gb & EL2 &
        [(EGA & EGB & EGB1 & _ & _)|(EGB & _ & _ & _)]).
  - subst ga gb. unfold jump_seg. rewrite EL2.
    assert (EGBb : (1 <=? gbc)%N = true) by (apply N.leb_le; exact EGB1).
    rewrite EGBb. cbn [N.eqb Pos.eqb andb]. eexists. reflexivity.
  - subst gb. destruct ga as [[gao gaz] gac].
    unfold jump_seg. rewrite EL2.
    destruct ((gao =? 8)%N && (gaz =? 2)%N && (gac =? 1)%N) eqn:EA3;
      try rewrite EA3; cbn [N.eqb Pos.eqb andb]; eexists; reflexivity.
Qed.
Lemma jump_comp_uncons (g : bg) (pre post body seg lb : word)
      (B f f2 : N) :
  jump_seg pre B = Some seg ->
  lawR_seg pre B = Some lb ->
  jump_comp (g :: pre) B post f = Some (JMP, body, f2) ->
  exists body', jump_comp pre B post f = Some (JMP, body', f2)
                /\ body = g :: body'.
Proof.
  intros EJ EL H.
  unfold jump_comp in H |- *.
  rewrite (jump_seg_cons g pre seg B EJ) in H.
  rewrite (lawR_seg_cons g pre lb B EL) in H.
  rewrite EJ, EL.
  repeat (match goal with
          | HH : context [ match ?x with _ => _ end ] |- _ =>
              lazymatch x with
              | Some _ => fail
              | _ => destruct x
              end
          | HH : context [ if ?b then _ else _ ] |- _ => destruct b
          end);
    try discriminate H;
    (pose proof (f_equal (fun o : option (ckind * word * N) =>
                            match o with
                            | Some (_, w, _) => w
                            | None => ([] : word)
                            end) H) as EW;
     pose proof (f_equal (fun o : option (ckind * word * N) =>
                            match o with
                            | Some (_, _, x) => x
                            | None => 0%N
                            end) H) as EF;
     cbn in EW, EF; rewrite <- EW, <- EF;
     eexists; split; reflexivity).
Qed.
