Lemma d227_crossc (k zb : nat) (L r : wside) :
  wrunc k ((0,S zb)::L) 0 (uword (repeat 2%nat k) r)
  = Some ((vstackC (repeat 2%nat k) ((0,S zb)::L), 0, r),
          (6 * N.of_nat k)%N).
Proof.
  revert zb L. induction k as [|k IH]; intros zb L.
  - rewrite wrunc_0. change (N.of_nat 0) with 0%N. ccost_close.
  - cbn [repeat uword].
    replace (S k) with (1 + k)%nat by lia.
    erewrite wrunc_split by apply (d227_x4c zb).
    rewrite (IH 0%nat).
    cbn [vstackC vpairC].
    rewrite 2!vstack1_shift.
    rewrite Nat2N.inj_succ. ccost_close.
Qed.
