Lemma FTripC_x203g (X' c : nat) :
  FTripC (3 * c + 9) (2 * N.of_nat X' + 14 * N.of_nat c + 47)%N
    ((1,(5 + X')%nat)::(0,2%nat)::(1,3%nat)::(0,2%nat)
       :: uword (repeat 2%nat c) [(1,4%nat)])
    (3 + X')%nat
    ((0,1%nat)::(1,3%nat)::(0,1%nat)
       :: uword (repeat 2%nat (S c)) [(1,4%nat)]).
Proof.
  apply FTripC_of; [apply FTrip_x203g|].
  intros zb y Z. eexists.
  replace (3 * c + 9)%nat
    with (1 + (1 + (c + (1 + (2 + (2 * c + 4))))))%nat by lia.
  erewrite wrunc_split by apply (g203_inc X' zb y Z).
  erewrite wrunc_split by apply (g203_m3c (2 + X')%nat).
  erewrite wrunc_split by apply (d203_crossg_gc c).
  erewrite wrunc_split by apply (d203_end_vc c).
  erewrite wrunc_split by apply DebrisLeafC_d203_turnc.
  rewrite <- (vstack1_shift c).
  erewrite wrunc_split by apply (d203_hopsc 0 c 1).
  rewrite fourk_split.
  rewrite (g203_mintc X').
  lazy beta iota.
  ccost_close.
Qed.
