Lemma FTripC_dtb4S (k' : nat) :
  FTripC (3 * k' + 10) (14 * N.of_nat k' + 57)%N
    (uword ((6%nat :: repeat 2%nat k') ++ [2%nat]) [(1,4%nat)])
    6
    ((0,1%nat)::(1,3%nat)::(0,2%nat)
