  lazy beta iota.
  rewrite (vstack_vstackC _ _ (zheaded0 _ _)).
  rewrite rev_app_distr.
  cbn [rev app vstackC vpairC].
  rewrite rev_repeat.
  erewrite wrunc_split by apply (d_far_eatvc 1).
  erewrite wrunc_split by apply DebrisLeafC_d203_turnc.
  rewrite vstackC_app.
  change ((0,1%nat)::(1,2%nat)::(0,1%nat)::(1,2%nat)
            :: vstackC (repeat 2%nat k')
                 (vstackC [6%nat] ((0,S zb)::(1,S y)::Z)))
    with (vstackC (repeat 2%nat (S k'))
            (vstackC [6%nat] ((0,S zb)::(1,S y)::Z))).
