      (sdec ((X,2,1)%N :: (4,2,cn)%N :: (3,2,1)%N :: [(4,2,cw)%N]) 4) p q
    /\ wconf [] 0 ((1,S p)::q)
       = wconf [] 0
           (sdec ((X-1,1,1)%N :: (3,2,1)%N
                  :: (if (cn =? 1)%N then [] else [(4,2,(cn-1))%N])
                     ++ [(4,1,1)%N; (4,2,(cw+1))%N]) 4).
Proof.
  intros E5 E1.
  assert (HL : sdec ((X,2,1)%N :: (4,2,cn)%N :: (3,2,1)%N :: [(4,2,cw)%N]) 4
             = (1,N.to_nat X)::(0,2%nat)
                 :: uword (repeat 2%nat (N.to_nat cn))
                      ((1,3%nat)::(0,2%nat)
                         :: uword (repeat 2%nat (N.to_nat cw))
                              [(1,4%nat)])).
  { rewrite !uword2_pair.
    unfold sdec. cbn [map gdecode expand app frun].
    change (N.to_nat 2) with 2%nat. change (N.to_nat 1) with 1%nat.
    change (N.to_nat 3) with 3%nat. change (N.to_nat 4) with 4%nat.
    cbn [pair_runs app]. rewrite ?app_nil_r, <- ?app_assoc.
    reflexivity. }
  assert (HR0 : sdec ((X-1,1,1)%N :: (3,2,1)%N
                       :: [(4,1,1)%N; (4,2,(cw+1))%N]) 4
              = (1,N.to_nat (X-1)%N)::(0,1%nat)::(1,3%nat)::(0,2%nat)
                  ::(1,4%nat)::(0,1%nat)
                  :: uword (repeat 2%nat (S (N.to_nat cw))) [(1,4%nat)]).
