    replace (N.to_nat cw + 1)%nat with (S (N.to_nat cw)) by lia.
    cbn [pair_runs app]. rewrite ?app_nil_r, <- ?app_assoc.
    reflexivity. }
  assert (HR1 : forall (m : N),
              sdec ((X-1,1,1)%N :: (3,2,1)%N :: (4,2,m)%N
                     :: [(4,1,1)%N; (4,2,(cw+1))%N]) 4
              = (1,N.to_nat (X-1)%N)::(0,1%nat)::(1,3%nat)::(0,2%nat)
                  :: uword (repeat 2%nat (N.to_nat m))
                       ((1,4%nat)::(0,1%nat)
                          :: uword (repeat 2%nat (S (N.to_nat cw)))
                               [(1,4%nat)])).
  { intros m. rewrite !uword2_pair.
    unfold sdec. cbn [map gdecode expand app frun].
    change (N.to_nat 2) with 2%nat. change (N.to_nat 1) with 1%nat.
    change (N.to_nat 3) with 3%nat. change (N.to_nat 4) with 4%nat.
    rewrite N2Nat.inj_add. change (N.to_nat 1) with 1%nat.
    replace (N.to_nat cw + 1)%nat with (S (N.to_nat cw)) by lia.
    cbn [pair_runs app]. rewrite ?app_nil_r, <- ?app_assoc.
    reflexivity. }
  destruct (cn =? 1)%N eqn:EQ1.
  { apply N.eqb_eq in EQ1. subst cn.
    exists (3 * 0 + 3 * N.to_nat cw + 12)%nat, (3 + N.to_nat (X - 5)%N)%nat,
           ((0,1%nat)::(1,3%nat)::(0,2%nat)::(1,4%nat)::(0,1%nat)
              :: uword (repeat 2%nat (S (N.to_nat cw))) [(1,4%nat)]).
    cbn [app].
    rewrite HL, HR0, (NtoS5 X E5), (NtoS4 X E5).
    unfold kl_leaf_respawn_orphan.
    replace (2 * X + 14 * 1 + 14 * cw + 37)%N
      with (2 * N.of_nat (N.to_nat (X - 5)%N) + 14 * N.of_nat 0%nat
            + 14 * N.of_nat (N.to_nat cw) + 61)%N
      by (rewrite !N2Nat.id; lia).
    split; [exact (FTripC_x218og (N.to_nat (X - 5)%N) 0%nat (N.to_nat cw))
           |reflexivity]. }
  assert (Hm : N.to_nat cn = S (N.to_nat (cn - 1)%N)) by (apply NtoSc; exact E1).
  exists (3 * N.to_nat (cn-1)%N + 3 * N.to_nat cw + 12)%nat,
         (3 + N.to_nat (X - 5)%N)%nat,
         ((0,1%nat)::(1,3%nat)::(0,2%nat)
            :: uword (repeat 2%nat (N.to_nat (cn-1)%N))
                 ((1,4%nat)::(0,1%nat)
                    :: uword (repeat 2%nat (S (N.to_nat cw))) [(1,4%nat)])).
  cbn [app].
  rewrite HL, (HR1 (cn-1)%N), Hm, (NtoS5 X E5), (NtoS4 X E5).
  unfold kl_leaf_respawn_orphan.
  replace (2 * X + 14 * cn + 14 * cw + 37)%N
    with (2 * N.of_nat (N.to_nat (X - 5)%N)
          + 14 * N.of_nat (N.to_nat (cn - 1)%N)
          + 14 * N.of_nat (N.to_nat cw) + 61)%N
    by (rewrite !N2Nat.id; lia).
  split; [exact (FTripC_x218og (N.to_nat (X - 5)%N) (N.to_nat (cn-1)%N)
                   (N.to_nat cw))
         |reflexivity].
Qed.
Lemma leaf_622_tripc (cw : N) :
  exists c p q,
    FTripC c (kl_leaf_622 6 cw)
      (sdec ((6,2,1)%N :: (2,2,1)%N :: [(4,2,cw)%N]) 4) p q
