             = (1,6%nat)::(0,2%nat)::(1,2%nat)::(0,2%nat)
                 :: uword (repeat 2%nat (N.to_nat cw)) [(1,4%nat)]).
  { rewrite uword2_pair.
    unfold sdec. cbn [map gdecode expand app frun].
    change (N.to_nat 2) with 2%nat. change (N.to_nat 1) with 1%nat.
    change (N.to_nat 6) with 6%nat. change (N.to_nat 4) with 4%nat.
    cbn [pair_runs app]. rewrite ?app_nil_r, <- ?app_assoc.
    reflexivity. }
  assert (HR : sdec ((5,1,1)%N :: (5,2,1)%N :: [(4,2,(cw+1))%N]) 4
             = (1,5%nat)::(0,1%nat)::(1,5%nat)::(0,2%nat)
                 :: uword (repeat 2%nat (S (N.to_nat cw))) [(1,4%nat)]).
  { rewrite uword2_pair.
    unfold sdec. cbn [map gdecode expand app frun].
    change (N.to_nat 2) with 2%nat. change (N.to_nat 1) with 1%nat.
    change (N.to_nat 5) with 5%nat. change (N.to_nat 4) with 4%nat.
    rewrite N2Nat.inj_add. change (N.to_nat 1) with 1%nat.
