            :: uword (repeat 2%nat (S (N.to_nat cw))) [(1,4%nat)]).
  rewrite HL, HR.
  unfold kl_leaf_622.
  replace (2 * 6 + 28 * cw + 67)%N
    with (2 * N.of_nat 1%nat + 28 * N.of_nat (N.to_nat cw) + 77)%N
