Lemma DebrisLeafC_ren_liftc (ini sfx tail : word) (f f2 : N)
    (c p : nat) (K : N) (q : wside) :
  forallb (fun g => is_col g && negb (is_cmf g)
                    && (3 <=? gO g)%N) ini = true ->
  FTripC c K (sdec sfx f) p q ->
  wconf [] 0 ((1,S p)::q) = wconf [] 0 (sdec tail f2) ->
  exists c2 p2 q2,
    FTripC c2 (K + wcolcost ini)%N (sdec (ini ++ sfx) f) p2 q2
    /\ wconf [] 0 ((1,S p2)::q2) = wconf [] 0 (sdec (ini ++ tail) f2).
Proof.
  intros HB HF EQ.
  destruct (FTripC_cols ini c K (sdec sfx f) p q HB HF)
    as (c2 & p2 & q2 & HF2 & EQ2).
  exists c2, p2, q2. split; [rewrite sdec_app; exact HF2|].
  rewrite EQ2, sdec_app.
  apply wconf_app_cong. exact EQ.
Qed.
Lemma dtb4_pre8_tripc (mid : word) :
  forallb w42 mid = true ->
  exists (K : nat),
    expand (map gdecode mid) = pair_runs 4%nat 2%nat K
    /\ exists c p q,
         FTripC c (kl_dtb_plain (N.of_nat K))
           (sdec ((8,2,1)%N :: mid) 4) p q
         /\ (1,S p)::q = sdec ((7,1,1)%N :: (3,2,1)%N :: mid) 4.
Proof.
  intros HW.
  destruct (w42_expand mid HW) as [K EK].
  exists K. split; [exact EK|].
  unfold sdec.
  cbn [map gdecode expand app frun].
  rewrite !EK.
  change (N.to_nat 8) with 8%nat. change (N.to_nat 7) with 7%nat.
  change (N.to_nat 3) with 3%nat. change (N.to_nat 2) with 2%nat.
  change (N.to_nat 1) with 1%nat. change (N.to_nat 4) with 4%nat.
  cbn [pair_runs app].
  flatapp.
  destruct K as [|k'].
  - exists 7%nat, 6%nat, ((0,1%nat)::(1,3%nat)::(0,2%nat)::[(1,4%nat)]).
    cbn [pair_runs app].
    unfold kl_dtb_plain.
    replace (14 * N.of_nat 0%nat + 43)%N with 43%N
      by (change (N.of_nat 0%nat) with 0%N; lia).
    split; [exact FTripC_dtb4_0 | reflexivity].
  - pose proof (FTripC_dtb4S k') as HT.
    cbn [uword app] in HT.
    rewrite !uword_rep2_snoc in HT.
    exists (3 * k' + 10)%nat, 6%nat,
      ((0,1%nat)::(1,3%nat)::(0,2%nat)
         :: pair_runs 4 2 (S k') ++ [(1,4%nat)]).
    unfold kl_dtb_plain.
    replace (14 * N.of_nat (S k') + 43)%N with (14 * N.of_nat k' + 57)%N
      by (rewrite Nat2N.inj_succ; lia).
    split; [exact HT | reflexivity].
Qed.
Lemma DebrisLeafC_ren_far_tailc (cols2 : word) (f : N) :
  forallb (fun g => is_col g && negb (is_cmf g)
                    && (3 <=? gO g)%N) cols2 = true ->
  (5 <= f)%N ->
  exists c p q,
    FTripC c (kl_dtb_far f + wcolcost cols2)%N (sdec cols2 f) p q
    /\ wconf [] 0 ((1,S p)::q)
       = wconf [] 0 (sdec (cols2 ++ [((f-1)%N,1,1)%N]) 3).
Proof.
  intros HCOLS2 EF5g.
  pose (wj := N.to_nat (f - 5)%N).
  assert (EF5 : N.to_nat f = (5 + wj)%nat)
    by (unfold wj; rewrite N2Nat.inj_sub;
        change (N.to_nat 5) with 5%nat; lia).
  assert (EFm : N.to_nat (f - 1)%N = (4 + wj)%nat)
    by (unfold wj; rewrite !N2Nat.inj_sub;
        change (N.to_nat 5) with 5%nat;
        change (N.to_nat 1) with 1%nat; lia).
  assert (HF0 : FTripC 4 (kl_dtb_far f) (sdec [] f) (3 + wj)%nat
                  ((0,1%nat)::[(1,3%nat)])).
  { unfold sdec. cbn [map expand app].
    rewrite (frun_pos f) by lia.
    rewrite EF5.
    unfold kl_dtb_far.
    replace (2 * f + 13)%N with (2 * N.of_nat wj + 23)%N
      by (unfold wj; rewrite N2Nat.id; lia).
    exact (DebrisLeafC_FTripC_farbare wj). }
  assert (EQ0 : wconf [] 0 ((1,(4 + wj)%nat)::(0,1%nat)::[(1,3%nat)])
                = wconf [] 0 (sdec [((f-1)%N,1,1)%N] 3)).
  { unfold sdec.
    cbn [map gdecode expand app frun].
    rewrite EFm.
    change (N.to_nat 1) with 1%nat.
    cbn [pair_runs app].
    reflexivity. }
  destruct (DebrisLeafC_ren_liftc cols2 [] [((f-1)%N,1,1)%N] f 3 _ _ _ _
              HCOLS2 HF0 EQ0)
    as (c2 & p2 & q2 & HF2 & EQ2).
  rewrite app_nil_r in HF2.
  exists c2, p2, q2. split; [exact HF2 | exact EQ2].
Qed.
Lemma dtb4o_corec (c1 e : N) (cn' d : nat) (tl : word) :
  N.to_nat c1 = S cn' ->
  expand (map gdecode tl) = pair_runs 4%nat 2%nat d ->
  N.to_nat e = S d ->
  exists c p q,
    FTripC c (kl_dtb_orphan c1 (N.of_nat d))
      (sdec ((8,2,1)%N :: (4,2,c1)%N :: (3,2,1)%N :: tl) 4) p q
    /\ wconf [] 0 ((1,S p)::q)
       = wconf [] 0
           (sdec ((7,1,1)%N :: (3,2,1)%N
                  :: (if (1 <? c1)%N then [(4,2,(c1-1))%N] else [])
                     ++ [(4,1,1)%N; (4,2,e)%N]) 4).
Proof.
  intros EC ETL EE.
  assert (EC1 : c1 = N.of_nat (S cn'))
    by (rewrite <- EC, N2Nat.id; reflexivity).
  pose proof (FTripC_x218og 3 cn' d) as HT.
  rewrite !uword_repeat_w in HT.
  change ((2 + 2)%nat) with 4%nat in HT.
  change ((5 + 3)%nat) with 8%nat in HT.
  change ((3 + 3)%nat) with 6%nat in HT.
  replace (kl_dtb_orphan c1 (N.of_nat d))
    with (2 * N.of_nat 3%nat + 14 * N.of_nat cn' + 14 * N.of_nat d + 61)%N
    by (unfold kl_dtb_orphan; rewrite EC1, Nat2N.inj_succ; lia).
  eexists. eexists. eexists. split.
  - unfold sdec.
    cbn [map gdecode expand app frun].
    rewrite ETL, EC.
    change (N.to_nat 8) with 8%nat.
    change (N.to_nat 4) with 4%nat.
    change (N.to_nat 3) with 3%nat.
    change (N.to_nat 2) with 2%nat.
    change (N.to_nat 1) with 1%nat.
    cbn [pair_runs app].
    flatapp. flatappH HT.
    exact HT.
  - assert (ECm : N.to_nat (c1 - 1)%N = cn')
      by (rewrite N2Nat.inj_sub, EC;
          change (N.to_nat 1) with 1%nat; lia).
    rewrite !sdec_cons.
    rewrite (sdec_optk 4 2 c1 1 [(4,1,1)%N; (4,2,e)%N] 4).
    rewrite !sdec_cons, sdec_nil.
    rewrite ECm, EE.
    change (N.to_nat 7) with 7%nat.
    change (N.to_nat 4) with 4%nat.
    change (N.to_nat 3) with 3%nat.
    change (N.to_nat 2) with 2%nat.
    change (N.to_nat 1) with 1%nat.
    cbn [frun pair_runs app].
    flatapp.
    reflexivity.
Qed.
Lemma dtb3_core_tripc (c1 : N) (t1 : word) :
  (1 < c1)%N ->
  forallb w42 t1 = true ->
  exists (K : nat),
    expand (map gdecode t1) = pair_runs 4%nat 2%nat K
    /\ exists c p q,
         FTripC c (kl_dtb_f3 c1 (N.of_nat K))
           (sdec ((8,2,1)%N :: (4,2,c1)%N :: t1) 3) p q
         /\ wconf [] 0 ((1,S p)::q)
            = wconf [] 0
                (sdec (((7,1,1)%N :: (3,2,1)%N :: (4,2,(c1-1))%N :: t1)
                       ++ [(4,1,1)%N]) 4).
Proof.
  intros EC12 EW42.
