    rewrite app_assoc, <- pair_runs_add, EMM.
    rewrite <- uword_rep2_snoc.
    change ((1,8%nat)::(0,2%nat)
              :: uword (repeat 2%nat (N.to_nat (c1-1)%N + K) ++ [2%nat])
                   [(1,3%nat)])
      with (uword ((6%nat :: repeat 2%nat (N.to_nat (c1-1)%N + K))
                   ++ [2%nat]) [(1,3%nat)]).
    exact (FTripC_dtb3S (N.to_nat (c1-1)%N + K)%nat).
