Lemma DebrisLeafC_FTripC_cost_eq (c : nat) (K K' : N) (W : wside) (p : nat) (q : wside) :
  K = K' -> FTripC c K W p q -> FTripC c K' W p q.
Proof. intros <- H. exact H. Qed.
Lemma ccolcost_wcolcost1 (g : bg) :
  ccolcost [g] = wcolcost [g].
Proof. destruct g as [[o z] c]. reflexivity. Qed.
Lemma pair_runs_len (o z c : nat) :
  List.length (pair_runs o z c) = (2 * c)%nat.
Proof. induction c as [|c IH]; cbn [pair_runs List.length]; lia. Qed.
Lemma w42sum_expand (t : word) :
  forallb w42 t = true ->
  expand (map gdecode t) = pair_runs 4%nat 2%nat (N.to_nat (w42sum t)).
Proof.
  induction t as [|[[o z] c] r IH];
    cbn [forallb map gdecode expand w42sum]; [reflexivity|].
  intros H. apply andb_prop in H. destruct H as (Hg & Hr).
  unfold w42 in Hg. cbn [gO gZ] in Hg.
  apply andb_prop in Hg. destruct Hg as (Ho & Hz).
  apply N.eqb_eq in Ho, Hz. subst o z.
  rewrite (IH Hr).
  change (N.to_nat 4) with 4%nat. change (N.to_nat 2) with 2%nat.
  rewrite N2Nat.inj_add, pair_runs_add. reflexivity.
Qed.
Lemma dtb4_pre8_tripc_sum (mid : word) :
  forallb w42 mid = true ->
  exists c p q,
    FTripC c (kl_dtb_plain (w42sum mid))
      (sdec ((8,2,1)%N :: mid) 4) p q
    /\ (1,S p)::q = sdec ((7,1,1)%N :: (3,2,1)%N :: mid) 4.
Proof.
  intros HW.
  destruct (dtb4_pre8_tripc mid HW) as (K & EK & c & p & q & HF & EQ).
  rewrite (w42sum_expand mid HW) in EK.
  assert (EKn : K = N.to_nat (w42sum mid)).
  { pose proof (f_equal (@List.length _) EK) as EL.
    rewrite !pair_runs_len in EL. lia. }
  exists c, p, q. split; [|exact EQ].
  refine (DebrisLeafC_FTripC_cost_eq _ _ _ _ _ _ _ HF).
  unfold kl_dtb_plain. rewrite EKn, N2Nat.id. reflexivity.
Qed.
Lemma dtb4_convc_tripc (cols : word) :
  forall cols' Kd,
  forallb (fun g => is_col g && negb (is_cmf g)
                    && (3 <=? gO g)%N) cols = true ->
  dtb4_convc cols = Some (cols', Kd) ->
  exists c p q,
    FTripC c Kd (sdec cols 4) p q
    /\ wconf [] 0 ((1,S p)::q) = wconf [] 0 (sdec cols' 4).
Proof.
  induction cols as [|[[go gz] gc] t IH]; intros cols' Kd HB HD.
  { cbn in HD. discriminate. }
  cbn [forallb] in HB. apply andb_prop in HB. destruct HB as (HG & HB').
  cbn [dtb4_convc gO gZ gC] in HD.
  destruct (dtb4_convc t) as [[t' k]|] eqn:ED.
  { injection HD as <- <-.
    destruct (IH t' k HB' eq_refl) as (ci & pi & qi & HFi & EQi).
    assert (HG1 : forallb (fun g => is_col g && negb (is_cmf g)
                                    && (3 <=? gO g)%N)
                    [(go,gz,gc)%N] = true)
      by (cbn [forallb]; rewrite HG; reflexivity).
    destruct (DebrisLeafC_ren_liftc [(go,gz,gc)%N] t t' 4 4 ci pi k qi HG1 HFi EQi)
      as (c2 & p2 & q2 & HF2 & EQ2).
    cbn [app] in HF2, EQ2.
    exists c2, p2, q2. split; [|exact EQ2].
    refine (DebrisLeafC_FTripC_cost_eq _ _ _ _ _ _ _ HF2).
    f_equal; try (symmetry; apply ccolcost_wcolcost1). }
  destruct ((go =? 8)%N && (gz =? 2)%N && (gc =? 1)%N) eqn:EGU;
    [|discriminate].
  apply andb_prop in EGU. destruct EGU as (EGU & EGC).
  apply andb_prop in EGU. destruct EGU as (EGO & EGZ).
  apply N.eqb_eq in EGO, EGZ, EGC. subst go gz gc.
  destruct (forallb w42 t) eqn:EW42.
  2:{
      destruct t as [|[[o1 z1] c1] t1]; [discriminate|].
      destruct t1 as [|[[o2 z2] c2] t2]; [discriminate|].
      cbn [w42 gO gZ forallb] in EW42.
      destruct ((o1 =? 4)%N && (z1 =? 2)%N && (1 <=? c1)%N
                && (o2 =? 3)%N && (z2 =? 2)%N && (c2 =? 1)%N) eqn:EGO2;
        [|discriminate].
      apply andb_prop in EGO2. destruct EGO2 as (EGO2 & EC2).
      apply andb_prop in EGO2. destruct EGO2 as (EGO2 & EZ2).
      apply andb_prop in EGO2. destruct EGO2 as (EGO2 & EO2).
      apply andb_prop in EGO2. destruct EGO2 as (EGO2 & EC1).
      apply andb_prop in EGO2. destruct EGO2 as (EO1 & EZ1).
      apply N.eqb_eq in EO1, EZ1, EO2, EZ2, EC2.
      apply N.leb_le in EC1.
      subst o1 z1 o2 z2 c2.
      destruct (to_nat_ge1 c1 EC1) as [cn' EC].
      destruct t2 as [|[[o3 z3] c3] t3].
      { injection HD as <- <-.
        destruct (dtb4o_corec c1 1 cn' 0 [] EC eq_refl eq_refl)
          as (c & p & q & HF & EQ).
        exists c, p, q. split; [|exact EQ].
        refine (DebrisLeafC_FTripC_cost_eq _ _ _ _ _ _ _ HF).
        unfold kl_dtb_orphan, kdtb_orphan.
        change (N.of_nat 0) with 0%N. lia. }
      destruct t3 as [|g4 t4]; [|discriminate].
      destruct ((o3 =? 4)%N && (z3 =? 2)%N) eqn:EG3; [|discriminate].
      injection HD as <- <-.
      apply andb_prop in EG3. destruct EG3 as (EO3 & EZ3).
      apply N.eqb_eq in EO3, EZ3. subst o3 z3.
      assert (ETL : expand (map gdecode [(4,2,c3)%N])
                  = pair_runs 4%nat 2%nat (N.to_nat c3)).
      { cbn [map gdecode expand app].
        change (N.to_nat 4) with 4%nat. change (N.to_nat 2) with 2%nat.
        rewrite app_nil_r. reflexivity. }
      assert (EE : N.to_nat (c3 + 1)%N = S (N.to_nat c3))
        by (rewrite N2Nat.inj_add;
            change (N.to_nat 1) with 1%nat; lia).
      destruct (dtb4o_corec c1 (c3+1)%N cn' (N.to_nat c3) [(4,2,c3)%N]
                  EC ETL EE)
        as (c & p & q & HF & EQ).
      exists c, p, q. split; [|exact EQ].
      refine (DebrisLeafC_FTripC_cost_eq _ _ _ _ _ _ _ HF).
      unfold kl_dtb_orphan, kdtb_orphan. rewrite N2Nat.id. lia. }
  injection HD as <- <-.
  destruct (dtb4_pre8_tripc_sum t EW42) as (c & p & q & HF & EQ).
  exists c, p, q. split.
