Lemma leaf_trip_returnc (c_0 : N) (p' site site' : word) (f f2 : N)
      (c pp : nat) (K : N) (q : wside) :
  zpre p' -> (1 <= c_0)%N ->
  FTripC c K (sdec site f) pp q ->
  wconf [] 0 ((1, S pp) :: q) = wconf [] 0 (sdec site' f2) ->
  creach (cx (bsum ((2,2,c_0)%N :: p') + (K + 6))%N)
    (wconf [] 0 (sdecode (((2,2,c_0)%N :: p') ++ site) f))
    (wconf [] 0 (sdecode ((2,2,1)%N :: ((2,2,c_0)%N :: p') ++ site') f2)).
Proof.
  intros HP HC0 HT EQ.
  destruct (to_nat_ge1 c_0 HC0) as [c0' E0].
  assert (EG : gms ((2,2,c_0)%N :: p')
             = 0%nat :: (repeat 0%nat c0' ++ gms p'))
    by exact (gms_col_head c_0 p' c0' E0).
  assert (E1 : sdecode (((2,2,c_0)%N :: p') ++ site) f
             = uword (0%nat :: (repeat 0%nat c0' ++ gms p')) (sdec site f)).
  { unfold sdecode.
    rewrite (bdec_pre_uword _ _ f (zpre_cons_col c_0 p' HP)).
    rewrite EG. reflexivity. }
  assert (E2 : sdecode ((2,2,1)%N :: ((2,2,c_0)%N :: p') ++ site') f2
             = uword (0%nat :: 0%nat :: (repeat 0%nat c0' ++ gms p'))
                 (sdec site' f2)).
  { unfold sdecode.
    rewrite (bdec_col1_uword _ _ f2 (zpre_cons_col c_0 p' HP)).
    rewrite EG. reflexivity. }
  rewrite E1, E2.
  rewrite <- (wconf_uword_cong
                (0%nat :: 0%nat :: (repeat 0%nat c0' ++ gms p')) _ _ EQ).
  replace (bsum ((2,2,c_0)%N :: p') + (K + 6))%N
    with (csuml cpair (0%nat :: (repeat 0%nat c0' ++ gms p')) + (K + 6))%N.
  2:{ rewrite (bsum_gms _ (zpre_cons_col c_0 p' HP)), EG,
              csuml_cpair_split.
      lia. }
  exact (ftripc_creach (repeat 0%nat c0' ++ gms p') c K (sdec site f)
           pp q HT).
Qed.
