Lemma casc_z3c (X Y c2 : N) :
  (5 <= X)%N -> (1 <= Y)%N -> (1 <= c2)%N ->
  exists c p q,
    FTripC c (2 * X + 2 * Y + 14 * c2 + 49)%N
      (sdec ((X,3,1)%N :: (Y,3,1)%N :: [(4,2,c2)%N]) 4) p q
    /\ wconf [] 0 ((1,S p)::q)
       = wconf [] 0
           (sdec ([(X-1,1,1)%N; ((Y+2)%N,1,1)%N; (6,1,1)%N; (3,2,1)%N]
                  ++ (if (1 <? c2)%N then [(4,2,(c2-1))%N] else [])) 4).
Proof.
  intros E5 GY1 GC2.
  assert (HL : sdec ((X,3,1)%N :: (Y,3,1)%N :: [(4,2,c2)%N]) 4
             = (1,N.to_nat X)::(0,3%nat)::(1,N.to_nat Y)::(0,3%nat)
                 :: uword (repeat 2%nat (N.to_nat c2)) [(1,4%nat)]).
  { rewrite uword2_pair.
    unfold sdec. cbn [map gdecode expand app frun].
    change (N.to_nat 3) with 3%nat. change (N.to_nat 1) with 1%nat.
    change (N.to_nat 4) with 4%nat. change (N.to_nat 2) with 2%nat.
    cbn [pair_runs app]. rewrite ?app_nil_r. reflexivity. }
  assert (HR : sdec ([(X-1,1,1)%N; ((Y+2)%N,1,1)%N; (6,1,1)%N; (3,2,1)%N]
                     ++ (if (1 <? c2)%N then [(4,2,(c2-1))%N] else [])) 4
             = (1,N.to_nat (X-1)%N)::(0,1%nat)::(1,N.to_nat (Y+2)%N)
                 ::(0,1%nat)::(1,6%nat)::(0,1%nat)::(1,3%nat)::(0,2%nat)
                 :: uword (repeat 2%nat (N.to_nat (c2-1)%N)) [(1,4%nat)]).
  { rewrite uword2_pair.
    rewrite sdec_app.
    cbn [map gdecode expand app].
    change (N.to_nat 1) with 1%nat. change (N.to_nat 6) with 6%nat.
    change (N.to_nat 3) with 3%nat. change (N.to_nat 2) with 2%nat.
    cbn [pair_runs app].
    destruct (1 <? c2)%N eqn:EP.
    - unfold sdec. cbn [map gdecode expand app frun].
      change (N.to_nat 4) with 4%nat. change (N.to_nat 2) with 2%nat.
      rewrite ?app_nil_r. reflexivity.
    - apply N.ltb_ge in EP.
      replace (c2 - 1)%N with 0%N by lia.
      unfold sdec. cbn [map gdecode expand app frun N.to_nat].
      cbn [pair_runs app]. reflexivity. }
  exists (3 * N.to_nat (c2 - 1)%N + 13)%nat,
         (3 + N.to_nat (X - 5)%N)%nat,
    ((0,1%nat)::(1,(3 + N.to_nat (Y - 1)%N)%nat)::(0,1%nat)::(1,6%nat)
       ::(0,1%nat)::(1,3%nat)::(0,2%nat)
       :: uword (repeat 2%nat (N.to_nat (c2-1)%N)) [(1,4%nat)]).
  rewrite HL, HR.
  rewrite (NtoS5 X E5), (NtoS1y Y GY1), (NtoSc c2 GC2).
  rewrite (NtoS4 X E5), (NtoS3y Y GY1).
  split; [|reflexivity].
  refine (DebrisLeafC_FTripC_cost_eq _ _ _ _ _ _ _
            (FTripC_armC (N.to_nat (X - 5)%N) (N.to_nat (Y - 1)%N)
                         (N.to_nat (c2 - 1)%N))).
  rewrite !N2Nat.id. lia.
Qed.
Lemma ren_lawRc (ini : word) (gbc B : N) (h1 nb : nat) :
  forallb is_col ini = true ->
  N.to_nat gbc = S h1 -> N.to_nat B = S nb ->
  exists c2 p2 q2,
    FTripC c2 (14 * N.of_nat h1 + 14 * N.of_nat nb + 93 + wcolcost ini)%N
      (sdec ((ini ++ [(8,2,1)%N; (4,2,gbc)%N])
               ++ [(4,3,1)%N; (4,2,B)%N]) 4%N) p2 q2
    /\ wconf [] 0 ((1,S p2)::q2)
       = wconf [] 0
           (sdec (ini ++ [(7,1,1)%N; (3,2,1)%N; (4,2,gbc)%N;
                          (7,1,1)%N; (3,2,1)%N]
                    ++ (if (1 <? B)%N then [(4,2,(B-1))%N] else [])) 4%N).
Proof.
  intros HPI EH EB.
  pose proof (FTripC_lawR h1 nb) as HT.
  cbn [uword app] in HT.
  rewrite !uword_rep2_snoc, !uword_repeat_w in HT.
  flatapp.
  refine (ren_liftc_col ini _ _ _ _ _ _ _ _ HPI _ _).
  - rewrite !sdec_cons.
    rewrite EH, EB.
    change (N.to_nat 8) with 8%nat.
    change (N.to_nat 4) with 4%nat.
    change (N.to_nat 3) with 3%nat.
    change (N.to_nat 2) with 2%nat.
    change (N.to_nat 1) with 1%nat.
    unfold sdec. cbn [map gdecode expand app frun].
    change (N.to_nat 4) with 4%nat.
    cbn [pair_runs app].
    flatapp.
    rewrite ?app_nil_r.
    exact HT.
  - rewrite !sdec_cons.
    rewrite EH.
    change (N.to_nat 7) with 7%nat.
    change (N.to_nat 4) with 4%nat.
    change (N.to_nat 3) with 3%nat.
    change (N.to_nat 2) with 2%nat.
    change (N.to_nat 1) with 1%nat.
    destruct ((1 <? B)%N) eqn:ELT.
    { apply N.ltb_lt in ELT.
      assert (EBm : N.to_nat (B - 1)%N = nb)
        by (rewrite N2Nat.inj_sub, EB;
            change (N.to_nat 1) with 1%nat; lia).
      unfold sdec. cbn [map gdecode expand app frun].
      rewrite EBm.
      change (N.to_nat 4) with 4%nat.
      change (N.to_nat 2) with 2%nat.
      cbn [pair_runs app].
      flatapp.
      rewrite ?app_nil_r.
      reflexivity. }
    apply N.ltb_ge in ELT.
    assert (EB1x : B = 1%N) by lia. subst B.
    assert (ENB0 : nb = 0%nat) by (cbn in EB; lia). subst nb.
    unfold sdec. cbn [map gdecode expand app frun].
    change (N.to_nat 4) with 4%nat.
    cbn [pair_runs app].
    flatapp.
    rewrite ?app_nil_r.
    reflexivity.
Qed.
