Lemma w42sum_ccolcostC (t : word) :
  forallb w42 t = true ->
  (14 * w42sum t = ccolcost t)%N.
Proof.
  induction t as [|[[o z] c] r IH]; [reflexivity|].
  cbn [forallb]. intros H. apply andb_prop in H. destruct H as (Hg & Hr).
  unfold w42 in Hg. cbn [gO gZ] in Hg.
  apply andb_prop in Hg. destruct Hg as (Ho & _).
  apply N.eqb_eq in Ho. subst o.
  cbn [w42sum gC].
  rewrite ccolcost_cons, ccg_unfold.
  rewrite <- (IH Hr). lia.
Qed.
Lemma ren_lawR_tailc (ini : word) (gbc B : N) (h1 nb : nat)
    (cols2 : word) :
  forallb is_col ini = true ->
  N.to_nat gbc = S h1 -> N.to_nat B = S nb ->
  forallb w42 cols2 = true ->
  exists c2 p2 q2,
    FTripC c2
      (14 * N.of_nat h1 + 14 * N.of_nat nb + 93
       + ccolcost cols2 + wcolcost ini)%N
      (sdec ((ini ++ [(8,2,1)%N; (4,2,gbc)%N])
              ++ (4,3,1)%N :: (4,2,B)%N :: cols2) 4) p2 q2
    /\ wconf [] 0 ((1,S p2)::q2)
       = wconf [] 0
           (sdec ((ini ++ [(7,1,1)%N; (3,2,1)%N; (4,2,gbc)%N;
                           (7,1,1)%N; (3,2,1)%N]
                   ++ (if (1 <? B)%N then [(4,2,(B-1))%N] else []))
                  ++ cols2) 4).
Proof.
  intros HPI EH EB EW42.
  pose proof (w42sum_expand cols2 EW42) as EK2.
  pose proof (FTripC_lawR h1
                (nb + N.to_nat (w42sum cols2))) as HT.
  cbn [uword app] in HT.
  rewrite !uword_rep2_snoc, !uword_repeat_w in HT.
  flatapp.
  refine (ren_liftc_col ini _ _ 4%N 4%N _ _
            (14 * N.of_nat h1 + 14 * N.of_nat nb + 93
             + ccolcost cols2)%N _ HPI _ _).
  - rewrite !sdec_cons.
    rewrite EH, EB.
    change (N.to_nat 8) with 8%nat.
    change (N.to_nat 4) with 4%nat.
    change (N.to_nat 3) with 3%nat.
    change (N.to_nat 2) with 2%nat.
    change (N.to_nat 1) with 1%nat.
    unfold sdec at 1. rewrite EK2.
    cbn [frun].
    change (N.to_nat 4) with 4%nat.
    cbn [pair_runs app].
    flatapp.
    rewrite pair_runs_add in HT.
    rewrite <- app_assoc in HT.
    refine (DebrisLeafC_FTripC_cost_eq _ _ _ _ _ _ _ HT).
    rewrite Nat2N.inj_add, N2Nat.id, <- (w42sum_ccolcostC cols2 EW42).
    lia.
  - rewrite !sdec_cons, sdec_app.
    rewrite EH.
    change (N.to_nat 7) with 7%nat.
    change (N.to_nat 4) with 4%nat.
    change (N.to_nat 3) with 3%nat.
    change (N.to_nat 2) with 2%nat.
    change (N.to_nat 1) with 1%nat.
    unfold sdec at 1. rewrite EK2.
    cbn [frun].
    change (N.to_nat 4) with 4%nat.
    destruct ((1 <? B)%N) eqn:ELT.
    { apply N.ltb_lt in ELT.
      assert (EBm : N.to_nat (B - 1)%N = nb)
        by (rewrite N2Nat.inj_sub, EB;
            change (N.to_nat 1) with 1%nat; lia).
      cbn [map gdecode expand]. rewrite EBm.
      change (N.to_nat 4) with 4%nat. change (N.to_nat 2) with 2%nat.
      cbn [pair_runs app]. flatapp. rewrite ?app_nil_r. reflexivity. }
    apply N.ltb_ge in ELT.
    assert (EB1x : B = 1%N) by lia. subst B.
    assert (ENB0 : nb = 0%nat) by (cbn in EB; lia). subst nb.
    cbn [map gdecode expand]. cbn [pair_runs app].
    flatapp. rewrite ?app_nil_r. reflexivity.
Qed.
Lemma lawR0_corec (B : N) (nb : nat) (cols2 : word) :
  N.to_nat B = S nb ->
  forallb w42 cols2 = true ->
  exists c p q,
    FTripC c (14 * N.of_nat nb + 79 + ccolcost cols2)%N
      (sdec ((8,2,1)%N :: (4,3,1)%N :: (4,2,B)%N :: cols2) 4) p q
    /\ wconf [] 0 ((1,S p)::q)
       = wconf [] 0
           (sdec (((7,1,1)%N :: (3,2,1)%N :: (7,1,1)%N :: (3,2,1)%N
                    :: (if (1 <? B)%N then [(4,2,(B-1))%N] else []))
                  ++ cols2) 4).
Proof.
  intros EB EW42.
  pose proof (w42sum_expand cols2 EW42) as EK2.
  pose proof (FTripC_lawR0
                (nb + N.to_nat (w42sum cols2))) as HT.
  rewrite !uword_repeat_w in HT.
  change ((2 + 2)%nat) with 4%nat in HT.
  eexists. eexists. eexists. split.
  - rewrite !sdec_cons. rewrite EB.
    change (N.to_nat 8) with 8%nat.
    change (N.to_nat 4) with 4%nat.
    change (N.to_nat 3) with 3%nat.
    change (N.to_nat 2) with 2%nat.
    change (N.to_nat 1) with 1%nat.
    unfold sdec at 1. rewrite EK2.
    cbn [frun]. change (N.to_nat 4) with 4%nat.
    cbn [pair_runs app]. flatapp.
    rewrite pair_runs_add in HT.
    rewrite <- app_assoc in HT.
    refine (DebrisLeafC_FTripC_cost_eq _ _ _ _ _ _ _ HT).
    rewrite Nat2N.inj_add, N2Nat.id, <- (w42sum_ccolcostC cols2 EW42).
    lia.
  - flatapp.
    rewrite !sdec_cons, sdec_app.
    change (N.to_nat 7) with 7%nat.
    change (N.to_nat 4) with 4%nat.
    change (N.to_nat 3) with 3%nat.
    change (N.to_nat 2) with 2%nat.
    change (N.to_nat 1) with 1%nat.
    unfold sdec at 1. rewrite EK2.
    cbn [frun]. change (N.to_nat 4) with 4%nat.
    destruct ((1 <? B)%N) eqn:ELT.
    { apply N.ltb_lt in ELT.
      assert (EBm : N.to_nat (B - 1)%N = nb)
        by (rewrite N2Nat.inj_sub, EB;
            change (N.to_nat 1) with 1%nat; lia).
      cbn [map gdecode expand]. rewrite EBm.
      change (N.to_nat 4) with 4%nat. change (N.to_nat 2) with 2%nat.
      cbn [pair_runs app]. flatapp. rewrite ?app_nil_r. reflexivity. }
    apply N.ltb_ge in ELT.
    assert (EB1x : B = 1%N) by lia. subst B.
    assert (ENB0 : nb = 0%nat) by (cbn in EB; lia). subst nb.
    cbn [map gdecode expand]. cbn [pair_runs app].
    flatapp. rewrite ?app_nil_r. reflexivity.
Qed.
Lemma ren_lawR0_tailc (ini : word) (ga : bg) (B : N)
    (nb : nat) (cols2 : word) :
  forallb is_col (ini ++ [ga]) = true ->
  N.to_nat B = S nb ->
  forallb w42 cols2 = true ->
  exists c2 p2 q2,
    FTripC c2
      (ccolcost (ini ++ [ga])
       + 14 * N.of_nat nb + 79 + ccolcost cols2)%N
      (sdec ((ini ++ [ga; (8,2,1)%N])
              ++ (4,3,1)%N :: (4,2,B)%N :: cols2) 4) p2 q2
    /\ wconf [] 0 ((1,S p2)::q2)
       = wconf [] 0
           (sdec ((ini ++ [ga; (7,1,1)%N; (3,2,1)%N;
                              (7,1,1)%N; (3,2,1)%N]
                   ++ (if (1 <? B)%N then [(4,2,(B-1))%N] else []))
                  ++ cols2) 4).
Proof.
  intros HPI EB EW42.
  destruct (lawR0_corec B nb cols2 EB EW42)
    as (c & p & q & HF & EQ).
  flatapp. flatappH EQ.
  destruct (ren_lift1cc ini ga _ _ 4%N 4%N c p
              (14 * N.of_nat nb + 79 + ccolcost cols2)%N q
              HPI HF EQ) as (c2 & p2 & q2 & HF2 & EQ2).
  exists c2, p2, q2. split; [|exact EQ2].
  refine (DebrisLeafC_FTripC_cost_eq _ _ _ _ _ _ _ HF2). lia.
Qed.
Lemma casc_lawR_innerc_col (cols cols2 seg2 : word) (B : N) :
  forallb is_col cols = true ->
  lawR_seg cols B = Some seg2 ->
  (1 <= B)%N ->
  forallb w42 cols2 = true ->
  exists c p q,
    FTripC c
      (ccolcost cols + 14 * B + ccolcost cols2 + 43)%N
      (sdec (cols ++ (4,3,1)%N :: (4,2,B)%N :: cols2) 4) p q
    /\ wconf [] 0 ((1,S p)::q) = wconf [] 0 (sdec (seg2 ++ cols2) 4).
Proof.
  intros HPC ELS EB1 EW42.
  unfold lawR_seg in ELS.
  destruct (last2 cols)
    as [[[ini [[gao gaz] gac]] [[gbo gbz] gbc]]|] eqn:EL2;
    [|discriminate].
  pose proof (last2_split _ _ _ _ EL2) as ECOLS.
  rewrite ECOLS in HPC. rewrite forallb_app in HPC.
  apply andb_prop in HPC. destruct HPC as (HPI & HPG).
  destruct ((gao =? 8)%N && (gaz =? 2)%N && (gac =? 1)%N
            && (gbo =? 4)%N && (gbz =? 2)%N && (1 <=? gbc)%N) eqn:EG1.
  { injection ELS as <-.
    apply andb_prop in EG1. destruct EG1 as (EG1 & EGB1).
    apply andb_prop in EG1. destruct EG1 as (EG1 & EBZ).
    apply andb_prop in EG1. destruct EG1 as (EG1 & EBO).
    apply andb_prop in EG1. destruct EG1 as (EAOZ & EAC).
    apply andb_prop in EAOZ. destruct EAOZ as (EAO & EAZ).
    apply N.eqb_eq in EAO, EAZ, EAC, EBO, EBZ.
    apply N.leb_le in EGB1.
    subst gao gaz gac gbo gbz.
    destruct (to_nat_ge1 gbc EGB1) as [h1 EH].
    destruct (to_nat_ge1 B EB1) as [nb EB].
    destruct (ren_lawR_tailc ini gbc B h1 nb cols2 HPI EH EB EW42)
      as (c & p & q & HF & EQ).
    rewrite ECOLS.
    exists c, p, q. split; [|exact EQ].
    refine (DebrisLeafC_FTripC_cost_eq _ _ _ _ _ _ _ HF).
    rewrite ccolcost_app, !ccolcost_cons,
            ccolcost_nil, !ccg_unfold.
    pose proof (ccolcost_wcolcost ini) as EW.
    assert (EGN : gbc = N.of_nat (S h1))
      by (rewrite <- (N2Nat.id gbc), EH; reflexivity).
    assert (EBN : B = N.of_nat (S nb))
      by (rewrite <- (N2Nat.id B), EB; reflexivity).
    rewrite EGN, EBN, !Nat2N.inj_succ. lia. }
  destruct ((gbo =? 8)%N && (gbz =? 2)%N && (gbc =? 1)%N) eqn:EG2;
    [|discriminate].
  injection ELS as <-.
  apply andb_prop in EG2. destruct EG2 as (EG2 & EBC).
  apply andb_prop in EG2. destruct EG2 as (EBO & EBZ).
  apply N.eqb_eq in EBO, EBZ, EBC. subst gbo gbz gbc.
  destruct (to_nat_ge1 B EB1) as [nb EB].
  assert (HPI2 :
    forallb is_col (ini ++ [(gao,gaz,gac)%N]) = true).
  { rewrite forallb_app, HPI.
    cbn [forallb] in HPG |- *.
    apply andb_prop in HPG. destruct HPG as (HGA & _).
    rewrite HGA. reflexivity. }
  destruct (ren_lawR0_tailc ini (gao,gaz,gac)%N B nb cols2 HPI2 EB EW42)
    as (c & p & q & HF & EQ).
  rewrite ECOLS.
  exists c, p, q. split; [|exact EQ].
  refine (DebrisLeafC_FTripC_cost_eq _ _ _ _ _ _ _ HF).
  assert (ECC :
    ccolcost (ini ++ [(gao,gaz,gac)%N; (8,2,1)%N])
    = (ccolcost (ini ++ [(gao,gaz,gac)%N]) + 22)%N).
  { replace (ini ++ [(gao,gaz,gac)%N; (8,2,1)%N])
      with ((ini ++ [(gao,gaz,gac)%N]) ++ [(8,2,1)%N])
      by exact (eq_sym (app_assoc ini [(gao,gaz,gac)%N] [(8,2,1)%N])).
    rewrite ccolcost_app, ccolcost_1, ccg_unfold. lia. }
  assert (EBN : B = N.of_nat (S nb))
    by (rewrite <- (N2Nat.id B), EB; reflexivity).
  rewrite EBN, Nat2N.inj_succ.
  assert (EALG : forall A D C n : N,
    D = (A + 22)%N ->
    (A + 14 * n + 79 + C)%N
    = (D + 14 * N.succ n + C + 43)%N).
  { intros A D C n ED. subst D. nia. }
  exact (EALG _ _ _ _ ECC).
Qed.
Lemma casc_lawR_innerc (cols cols2 seg2 : word) (B : N) :
  forallb (fun g => is_col g && negb (is_cmf g)
                    && (3 <=? gO g)%N) cols = true ->
  lawR_seg cols B = Some seg2 ->
  (1 <= B)%N ->
  forallb w42 cols2 = true ->
  exists c p q,
    FTripC c
      (ccolcost cols + 14 * B + ccolcost cols2 + 43)%N
      (sdec (cols ++ (4,3,1)%N :: (4,2,B)%N :: cols2) 4) p q
    /\ wconf [] 0 ((1,S p)::q) = wconf [] 0 (sdec (seg2 ++ cols2) 4).
Proof.
  intros HPC ELS EB1 EW42.
  exact (casc_lawR_innerc_col cols cols2 seg2 B
           (forallb_clift_is_col cols HPC) ELS EB1 EW42).
Qed.
Lemma is_col_82 : is_col (8,2,1)%N = true.
Proof. reflexivity. Qed.
Lemma is_col_42 (c : N) : is_col (4,2,c)%N = true.
Proof. reflexivity. Qed.
Lemma dseg_lawR_tripc (cols body : word) (Bq f f2 : N) (k : nat) :
  (1 <= Bq)%N ->
  (if (f =? 4)%N then
     match lawR_seg cols Bq with
     | Some b => Some (b, f)
     | None => None
     end
   else if (5 <=? f)%N then
     match jump_seg cols Bq with
     | Some seg => Some (seg ++ [((f-1)%N,1,1)%N], 3%N)
     | None => None
     end
   else None) = Some (body, f2) ->
  cin k (dseg_lawR cols Bq f) ->
  exists c p q,
    FTripC c (N.of_nat k) (sdec (cols ++ [(4,3,1)%N; (4,2,Bq)%N]) f) p q
    /\ wconf [] 0 ((1,S p)::q) = wconf [] 0 (sdec body f2).
Proof.
  intros EB1 Hres Hk.
  destruct (to_nat_ge1 Bq EB1) as [nb EB].
  unfold dseg_lawR in Hk.
  destruct (f =? 4)%N eqn:EF4.
  {
    apply N.eqb_eq in EF4. subst f.
    destruct (lawR_seg cols Bq) as [b|] eqn:ELR; [|discriminate Hres].
    injection Hres as <- <-.
    unfold dseg in Hk.
    destruct (cseg cols) as [[pc gbc]|] eqn:ECS;
      [|exact (cundef_absurd _ _ Hk)].
    apply cin_cx_eq in Hk.
    unfold lawR_seg in ELR.
    destruct (cseg_split cols pc gbc ECS)
      as (ini & ga & gb & EL2 &
          [(EGA & EGB & EGB1 & EPC & HBI)|(EGB & EGB0 & EPC & HBI)]).
    -
      subst pc ga gb.
      pose proof (last2_split _ _ _ _ EL2) as ECOLS.
      rewrite EL2 in ELR.
      assert (EGBb : (1 <=? gbc)%N = true) by (apply N.leb_le; exact EGB1).
      rewrite EGBb in ELR. cbn [N.eqb Pos.eqb andb] in ELR.
      injection ELR as <-.
      destruct (to_nat_ge1 gbc EGB1) as [h1 EH].
      rewrite ECOLS.
      refine (FTripC_ex_cost_eq _ _ _ _ _ _).
      2: exact (ren_lawRc ini gbc Bq h1 nb HBI EH EB).
      rewrite Hk.
      pose proof (ccolcost_wcolcost ini) as EW.
      assert (EGN : gbc = N.of_nat (S h1))
        by (rewrite <- (N2Nat.id gbc), EH; reflexivity).
      assert (EBN : Bq = N.of_nat (S nb))
        by (rewrite <- (N2Nat.id Bq), EB; reflexivity).
      rewrite EGN, EBN, !Nat2N.inj_succ. lia.
    -
      subst gb gbc.
      destruct ga as [[gao gaz] gac].
      pose proof (last2_split _ _ _ _ EL2) as ECOLS.
      assert (EPCW : pc = wcolcost (ini ++ [(gao,gaz,gac)%N]))
        by (rewrite EPC; apply ccolcost_wcolcost).
      assert (ELRb : b = ini ++ [(gao,gaz,gac)%N; (7,1,1)%N; (3,2,1)%N;
                                 (7,1,1)%N; (3,2,1)%N]
                           ++ (if (1 <? Bq)%N then [(4,2,(Bq-1))%N] else [])).
      { rewrite EL2 in ELR.
        destruct ((gao =? 8)%N && (gaz =? 2)%N && (gac =? 1)%N) eqn:EA3;
          try rewrite EA3 in ELR; cbn [N.eqb Pos.eqb andb] in ELR;
          injection ELR as <-; try rewrite <- app_assoc; reflexivity. }
      subst b.
      rewrite ECOLS, <- app_assoc. cbn [app].
      refine (FTripC_ex_cost_eq _ _ _ _ _ _).
      2:{ pose proof (ren_lawR0c (ini ++ [(gao,gaz,gac)%N]) Bq nb HBI EB)
            as HL0.
          rewrite <- ?app_assoc in HL0. cbn [app] in HL0.
          exact HL0. }
      rewrite Hk, EPCW.
      assert (EBN : Bq = N.of_nat (S nb))
        by (rewrite <- (N2Nat.id Bq), EB; reflexivity).
      rewrite EBN, !Nat2N.inj_succ. lia. }
  destruct (5 <=? f)%N eqn:EF5b; [|exact (cundef_absurd _ _ Hk)].
  pose proof EF5b as EF5. apply N.leb_le in EF5.
  destruct (jump_seg cols Bq) as [seg|] eqn:EJS; [|discriminate Hres].
  injection Hres as <- <-.
  unfold dseg in Hk.
  destruct (cseg cols) as [[pc gbc]|] eqn:ECS;
    [|exact (cundef_absurd _ _ Hk)].
  apply cin_cx_eq in Hk.
  destruct (DebrisLeafC_ren_far_tailc [] f eq_refl EF5) as (ci & pi & qi & HFi & EQi).
  cbn [app] in EQi.
  assert (HCC : forallb is_col cols = true
                /\ (wcolcost cols = pc + 14 * gbc + 22)%N).
  { destruct (cseg_split cols pc gbc ECS)
      as (ini & ga & gb & EL2 &
          [(EGA & EGB & EGB1 & EPC & HBI)|(EGB & EGB0 & EPC & HBI)]).
    - subst ga gb.
      assert (EPCW : pc = wcolcost ini)
        by (rewrite EPC; apply ccolcost_wcolcost).
      pose proof (last2_split _ _ _ _ EL2) as ECOLS.
      rewrite ECOLS. split.
      + rewrite forallb_app, HBI. cbn [forallb].
        rewrite is_col_82, is_col_42. reflexivity.
      + rewrite EPCW, wcolcost_app. cbn [wcolcost gC gO]. lia.
    - subst gb gbc.
      assert (EPCW : pc = wcolcost (ini ++ [ga]))
        by (rewrite EPC; apply ccolcost_wcolcost).
      pose proof (last2_split _ _ _ _ EL2) as ECOLS.
      rewrite forallb_app in HBI.
      apply andb_prop in HBI. destruct HBI as (HB1 & HB2).
      cbn [forallb] in HB2. rewrite andb_true_r in HB2.
      rewrite ECOLS. split.
      + rewrite forallb_app, HB1. cbn [forallb].
        rewrite HB2, is_col_82. reflexivity.
      + rewrite EPCW, !wcolcost_app. cbn [wcolcost gC gO]. lia. }
  destruct HCC as (HCC & HWC).
  destruct (casc_jump_innerc_col cols [] [((f-1)%N,1,1)%N] seg Bq f 3%N
              ci pi _ qi HCC EJS EB1 HFi EQi)
    as (c2 & p2 & q2 & HF2 & EQ2).
  exists c2, p2, q2. split; [|exact EQ2].
  refine (DebrisLeafC_FTripC_cost_eq _ _ _ _ _ _ _ HF2).
  rewrite Hk, HWC. cbn [wcolcost]. unfold kl_dtb_far. lia.
Qed.
Lemma dseg_endY_tripc (cols body : word) (y : N) (k : nat) :
  (1 <= y)%N ->
  endY_seg cols y = Some body ->
  cin k (dseg_endY cols y) ->
  exists c p q,
    FTripC c (N.of_nat k) (sdec (cols ++ [(4,3,1)%N; (y,3,1)%N]) 4%N) p q
    /\ wconf [] 0 ((1,S p)::q) = wconf [] 0 (sdec body 3%N).
Proof.
  intros EY1 EYS Hk.
  destruct (to_nat_ge1 y EY1) as [y1 EYY].
  assert (EY3 : N.to_nat (y + 3)%N = (4 + y1)%nat)
    by (rewrite N2Nat.inj_add, EYY; change (N.to_nat 3) with 3%nat; lia).
  unfold dseg_endY, dseg in Hk.
  destruct (cseg cols) as [[pc gbc]|] eqn:ECS;
    [|exact (cundef_absurd _ _ Hk)].
  apply cin_cx_eq in Hk.
  unfold endY_seg in EYS.
  destruct (cseg_split cols pc gbc ECS)
    as (ini & ga & gb & EL2 &
        [(EGA & EGB & EGB1 & EPC & HBI)|(EGB & EGB0 & EPC & HBI)]).
  -
    subst ga gb.
    assert (EPCW : pc = wcolcost ini)
      by (rewrite EPC; apply ccolcost_wcolcost).
    pose proof (last2_split _ _ _ _ EL2) as ECOLS.
    rewrite EL2 in EYS.
    assert (EGBb : (1 <=? gbc)%N = true) by (apply N.leb_le; exact EGB1).
    rewrite EGBb in EYS. cbn [N.eqb Pos.eqb andb] in EYS.
    injection EYS as <-.
    destruct (to_nat_ge1 gbc EGB1) as [h1 EH].
    pose proof (FTripC_endY h1 y1) as HT.
    cbn [uword app] in HT.
    rewrite !uword_rep2_snoc in HT.
    change (pair_runs 4 2 (S h1))
      with ((1,4%nat)::(0,2%nat)::pair_runs 4 2 h1) in HT.
    cbn [app] in HT.
    rewrite ECOLS, <- app_assoc. cbn [app].
    refine (FTripC_ex_cost_eq
              ((14 * N.of_nat h1 + 2 * N.of_nat y1 + 95)%N + wcolcost ini)%N
              _ _ _ _ _).
    { rewrite Hk, EPCW.
      assert (EGN : gbc = N.of_nat (S h1))
        by (rewrite <- (N2Nat.id gbc), EH; reflexivity).
      assert (EYN : y = N.of_nat (S y1))
        by (rewrite <- (N2Nat.id y), EYY; reflexivity).
      rewrite EGN, EYN, !Nat2N.inj_succ. lia. }
    refine (ren_liftc_col ini
                [(8,2,1)%N; (4,2,gbc)%N; (4,3,1)%N; (y,3,1)%N]
                [(7,1,1)%N; (3,2,1)%N; (4,2,gbc)%N; ((y+3)%N,1,1)%N;
                 (6,1,1)%N]
                4%N 3%N _ _ _ _ HBI _ _).
    { unfold sdec.
      cbn [map gdecode expand app frun].
      rewrite EH, EYY.
      change (N.to_nat 8) with 8%nat.
      change (N.to_nat 4) with 4%nat.
      change (N.to_nat 3) with 3%nat.
      change (N.to_nat 2) with 2%nat.
      change (N.to_nat 1) with 1%nat.
      cbn [pair_runs app].
      flatapp.
      rewrite ?app_nil_r.
      exact HT. }
    { unfold sdec.
      cbn [map gdecode expand app frun].
      rewrite EH, EY3.
      change (N.to_nat 7) with 7%nat.
      change (N.to_nat 6) with 6%nat.
      change (N.to_nat 4) with 4%nat.
      change (N.to_nat 3) with 3%nat.
      change (N.to_nat 2) with 2%nat.
      change (N.to_nat 1) with 1%nat.
      cbn [pair_runs app].
      flatapp.
      rewrite ?app_nil_r.
      reflexivity. }
  -
    subst gb gbc.
    destruct ga as [[gao gaz] gac].
    assert (EPCW : pc = wcolcost (ini ++ [(gao,gaz,gac)%N]))
      by (rewrite EPC; apply ccolcost_wcolcost).
    pose proof (last2_split _ _ _ _ EL2) as ECOLS.
    assert (EYSb : body = ini ++ [(gao,gaz,gac)%N; (7,1,1)%N; (3,2,1)%N;
                                  ((y+3)%N,1,1)%N; (6,1,1)%N]).
    { rewrite EL2 in EYS.
      destruct ((gao =? 8)%N && (gaz =? 2)%N && (gac =? 1)%N) eqn:EA3;
        try rewrite EA3 in EYS; cbn [N.eqb Pos.eqb andb] in EYS;
        injection EYS as <-; reflexivity. }
    subst body.
    pose proof (FTripC_endY0 y1) as HT.
    rewrite ECOLS, <- app_assoc. cbn [app].
    refine (FTripC_ex_cost_eq _ _ _ _ _ _).
    2:{ refine (ren_lift1cc ini _ _ _ 4%N 3%N _ _
                  (2 * N.of_nat y1 + 81)%N _ HBI _ _).
        { unfold sdec.
          cbn [map gdecode expand app frun].
          rewrite EYY.
          change (N.to_nat 8) with 8%nat.
          change (N.to_nat 4) with 4%nat.
          change (N.to_nat 3) with 3%nat.
          change (N.to_nat 2) with 2%nat.
          change (N.to_nat 1) with 1%nat.
          cbn [pair_runs app].
          rewrite ?app_nil_r.
          exact HT. }
        { unfold sdec.
          cbn [map gdecode expand app frun].
          rewrite EY3.
          change (N.to_nat 7) with 7%nat.
          change (N.to_nat 6) with 6%nat.
          change (N.to_nat 3) with 3%nat.
          change (N.to_nat 2) with 2%nat.
          change (N.to_nat 1) with 1%nat.
          cbn [pair_runs app].
          rewrite ?app_nil_r.
          reflexivity. } }
    rewrite Hk, EPCW.
    assert (EYN : y = N.of_nat (S y1))
      by (rewrite <- (N2Nat.id y), EYY; reflexivity).
    rewrite EYN, !Nat2N.inj_succ. lia.
Qed.
Lemma casc_dtb5c (X cY f : N) (cols : word) :
  forallb (fun g => is_col g && negb (is_cmf g)
                    && (3 <=? gO g)%N) cols = true ->
  (5 <= X)%N -> (1 <= cY)%N -> (5 <= f)%N ->
  exists c p q,
    FTripC c (2 * X + 14 * cY + 2 * f + wcolcost cols + 27)%N
      (sdec ((X,3,1)%N :: (4,2,cY)%N :: cols) f) p q
    /\ wconf [] 0 ((1,S p)::q)
       = wconf [] 0
           (sdec ((X-1,1,1)%N :: (7,2,1)%N :: (4,2,(cY-1))%N
                  :: cols ++ [((f-1)%N,1,1)%N]) 3).
Proof.
  intros HC E5 EC1 EF5.
  destruct (ren_far_tailc cols f HC EF5)
    as (ci & pi & qi & HFi & EQi).
  destruct (casc_stagec X cY cols (cols ++ [((f-1)%N,1,1)%N]) f 3
              ci pi (2 * f + 13 + wcolcost cols)%N qi E5 EC1 HFi EQi)
    as (c2 & p2 & q2 & HF2 & EQ2).
  exists c2, p2, q2. split; [|exact EQ2].
  refine (DebrisLeafC_FTripC_cost_eq _ _ _ _ _ _ _ HF2). lia.
Qed.
Lemma dtb3_convc_tripc (cols : word) :
  forall cols' Kd,
  forallb (fun g => is_col g && negb (is_cmf g)
                    && (3 <=? gO g)%N) cols = true ->
  dtb3_convc cols = Some (cols', Kd) ->
  exists c p q,
    FTripC c Kd (sdec cols 3) p q
    /\ wconf [] 0 ((1,S p)::q) = wconf [] 0 (sdec (cols' ++ [(4,1,1)%N]) 4).
Proof.
  induction cols as [|[[go gz] gc] t IH]; intros cols' Kd HB HD.
  { cbn in HD. discriminate. }
  cbn [forallb] in HB. apply andb_prop in HB. destruct HB as (HG & HB').
  cbn [dtb3_convc gO gZ gC] in HD.
  destruct (dtb3_convc t) as [[t' k]|] eqn:ED.
  { injection HD as <- <-.
    destruct (IH t' k HB' eq_refl) as (ci & pi & qi & HFi & EQi).
    assert (HG1 : forallb (fun g => is_col g && negb (is_cmf g)
                                    && (3 <=? gO g)%N)
                    [(go,gz,gc)%N] = true)
      by (cbn [forallb]; rewrite HG; reflexivity).
    destruct (DebrisLeafC_ren_liftc [(go,gz,gc)%N] t (t' ++ [(4,1,1)%N]) 3 4
                ci pi k qi HG1 HFi EQi)
      as (c2 & p2 & q2 & HF2 & EQ2).
    cbn [app] in HF2, EQ2.
    exists c2, p2, q2. split; [|exact EQ2].
    refine (DebrisLeafC_FTripC_cost_eq _ _ _ _ _ _ _ HF2).
    f_equal; try (symmetry; apply ccolcost_wcolcost1). }
  destruct ((go =? 8)%N && (gz =? 2)%N && (gc =? 1)%N) eqn:EGU;
    [|discriminate].
  apply andb_prop in EGU. destruct EGU as (EGU & EGC).
  apply andb_prop in EGU. destruct EGU as (EGO & EGZ).
  apply N.eqb_eq in EGO, EGZ, EGC. subst go gz gc.
  destruct t as [|[[o1 z1] c1] t1]; [discriminate|].
  destruct (((o1 =? 4) && (z1 =? 2) && (1 <? c1)
             && forallb w42 t1)%N) eqn:EG1; [|discriminate].
  apply andb_prop in EG1. destruct EG1 as (EG1 & EW42).
  apply andb_prop in EG1. destruct EG1 as (EG1 & EC1).
  apply andb_prop in EG1. destruct EG1 as (EO1 & EZ1).
  apply N.eqb_eq in EO1, EZ1. apply N.ltb_lt in EC1. subst o1 z1.
  injection HD as <- <-.
  destruct (dtb3_core_tripc c1 t1 EC1 EW42)
    as (K & EK & c & p & q & HF & EQ).
  exists c, p, q. split; [|exact EQ].
  refine (DebrisLeafC_FTripC_cost_eq _ _ _ _ _ _ _ HF).
  assert (EKn : K = N.to_nat (w42sum t1)).
  { pose proof (w42sum_expand t1 EW42) as EW.
    rewrite EW in EK.
    pose proof (f_equal (@List.length _) EK) as EL.
    rewrite !pair_runs_len in EL. lia. }
  unfold kl_dtb_f3, kdtb_f3. rewrite EKn, N2Nat.id. reflexivity.
Qed.
Lemma lcjmpW_tripc (gbc cn : N) (t2 : word) (f : N) :
  (1 <= gbc)%N -> (1 <= cn)%N ->
  exists c p q,
    FTripC c (14 * gbc + 43)%N
      (sdec ((8,2,1)%N :: (4,2,gbc)%N :: (4,4,1)%N :: (4,2,cn)%N :: t2) f)
      p q
    /\ wconf [] 0 ((1,S p)::q)
       = wconf [] 0
           (sdec ([(7,1,1); (3,2,1); (4,2,gbc); (8,2,1)]%N
                  ++ (if (1 <? cn)%N then [(4,2,(cn-1))%N] else [])
                  ++ t2) f).
Proof.
  intros H1 H2.
  destruct (to_nat_ge1 gbc H1) as [h1 EH].
  destruct (to_nat_ge1 cn H2) as [cn1 ECN].
  pose proof (FTripC_lcJMP h1 cn1 (sdec t2 f)) as HJ.
  cbn [uword app] in HJ. rewrite !uword_rep2_snoc in HJ.
  assert (EK : (14 * gbc + 43)%N = (14 * N.of_nat h1 + 57)%N).
  { replace gbc with (N.of_nat (S h1))
      by (rewrite <- EH, N2Nat.id; reflexivity).
    rewrite Nat2N.inj_succ. lia. }
  assert (EIN : sdec ((8,2,1)%N :: (4,2,gbc)%N :: (4,4,1)%N
                        :: (4,2,cn)%N :: t2) f
              = (1,8%nat) :: (0,2%nat)
                :: pair_runs 4 2 (S h1)
                   ++ (1,4%nat) :: (0,4%nat) :: (1,4%nat) :: (0,2%nat)
                      :: pair_runs 4 2 cn1 ++ sdec t2 f).
  { rewrite !sdec_cons. rewrite EH, ECN.
    change (N.to_nat 8) with 8%nat. change (N.to_nat 4) with 4%nat.
    change (N.to_nat 2) with 2%nat. change (N.to_nat 1) with 1%nat.
    cbn [pair_runs app]. rewrite <- ?app_assoc. reflexivity. }
  assert (EOUT : sdec ([(7,1,1); (3,2,1); (4,2,gbc); (8,2,1)]%N
                       ++ (if (1 <? cn)%N then [(4,2,(cn-1))%N] else [])
                       ++ t2) f
               = (1,7%nat) :: (0,1%nat) :: (1,3%nat) :: (0,2%nat)
                 :: pair_runs 4 2 (S h1)
                    ++ (1,8%nat) :: (0,2%nat)
                       :: pair_runs 4 2 cn1 ++ sdec t2 f).
  { destruct ((1 <? cn)%N) eqn:ELT.
    - apply N.ltb_lt in ELT.
      assert (ECM : N.to_nat (cn - 1)%N = cn1)
        by (rewrite N2Nat.inj_sub, ECN;
            change (N.to_nat 1) with 1%nat; lia).
      cbn [app]. rewrite !sdec_cons. rewrite EH, ECM.
      change (N.to_nat 8) with 8%nat. change (N.to_nat 7) with 7%nat.
      change (N.to_nat 4) with 4%nat. change (N.to_nat 3) with 3%nat.
      change (N.to_nat 2) with 2%nat. change (N.to_nat 1) with 1%nat.
      cbn [pair_runs app]. rewrite <- ?app_assoc. reflexivity.
    - apply N.ltb_ge in ELT.
      assert (ECZ : cn1 = O) by lia.
      subst cn1. cbn [app]. rewrite !sdec_cons. rewrite EH.
      change (N.to_nat 8) with 8%nat. change (N.to_nat 7) with 7%nat.
      change (N.to_nat 4) with 4%nat. change (N.to_nat 3) with 3%nat.
      change (N.to_nat 2) with 2%nat. change (N.to_nat 1) with 1%nat.
      cbn [pair_runs app]. rewrite <- ?app_assoc. reflexivity. }
  rewrite EK, EIN, EOUT.
  exists (3 * h1 + 10)%nat, 6%nat,
    ((0,1%nat) :: (1,3%nat) :: (0,2%nat)
     :: pair_runs 4 2 (S h1)
        ++ (1,8%nat) :: (0,2%nat) :: pair_runs 4 2 cn1 ++ sdec t2 f).
  split; [exact HJ|reflexivity].
Qed.
