Lemma dseg_z4_tripc (cols t2 : word) (cn f : N) (body : word)
      (k : nat) :
  (1 <= cn)%N ->
  jump_seg cols cn = Some body ->
  cin k (dseg cols (fun gbc => (14 * gbc + 43)%N)) ->
  exists c p q,
    FTripC c (N.of_nat k)
      (sdec (cols ++ (4,4,1)%N :: (4,2,cn)%N :: t2) f) p q
    /\ wconf [] 0 ((1,S p)::q) = wconf [] 0 (sdec (body ++ t2) f).
Proof.
  intros ECN1 EJS Hk.
  unfold dseg in Hk.
  destruct (cseg cols) as [[pc gbc]|] eqn:ECS;
    [|exact (cundef_absurd _ _ Hk)].
  apply cin_cx_eq in Hk.
  unfold jump_seg in EJS.
  destruct (cseg_split cols pc gbc ECS)
    as (ini & ga & gb & EL2 &
        [(EGA & EGB & EGB1 & EPC & HBI)|(EGB & EGB0 & EPC & HBI)]).
  -
    subst ga gb.
    assert (EPCW : pc = wcolcost ini)
      by (rewrite EPC; apply ccolcost_wcolcost).
    pose proof (last2_split _ _ _ _ EL2) as ECOLS.
    rewrite EL2 in EJS.
    assert (EGBb : (1 <=? gbc)%N = true) by (apply N.leb_le; exact EGB1).
    rewrite EGBb in EJS. cbn [N.eqb Pos.eqb andb] in EJS.
    injection EJS as <-.
    rewrite ECOLS, <- ?app_assoc. cbn [app].
    refine (FTripC_ex_cost_eq _ _ _ _ _ _).
    2:{ destruct (lcjmpW_tripc gbc cn t2 f EGB1 ECN1)
          as (ci & pi & qi & HFi & EQi).
        exact (ren_liftc_col ini _ _ f f ci pi (14 * gbc + 43)%N qi
                 HBI HFi EQi). }
    rewrite Hk, EPCW. lia.
  -
    subst gb gbc.
    destruct ga as [[gao gaz] gac].
    pose proof (last2_split _ _ _ _ EL2) as ECOLS.
    assert (EJSb : body = ini ++ [(gao,gaz,gac)%N; (7,1,1)%N; (3,2,1)%N;
                                  (8,2,1)%N]
                          ++ (if (1 <? cn)%N then [(4,2,(cn-1))%N] else [])).
    { rewrite EL2 in EJS.
      destruct ((gao =? 8)%N && (gaz =? 2)%N && (gac =? 1)%N) eqn:EA3;
        try rewrite EA3 in EJS; cbn [N.eqb Pos.eqb andb] in EJS;
        injection EJS as <-; reflexivity. }
    subst body.
    rewrite ECOLS, <- ?app_assoc. cbn [app].
    refine (FTripC_ex_cost_eq _ _ _ _ _ _).
    2:{ destruct (lcjmp0_tripc cn t2 f ECN1) as (ci & pi & qi & HFi & EQi).
        refine (ren_lift1cc ini _ _ _ f f ci pi 43%N qi HBI HFi _).
        rewrite EQi. reflexivity. }
    rewrite Hk, EPC. lia.
Qed.
Lemma cin_cadd_cx_split (k : nat) (K1 : N) (d2 : cost) :
  cin k (cadd (cx K1) d2) ->
  exists k2, N.of_nat k = (K1 + N.of_nat k2)%N /\ cin k2 d2.
Proof.
  unfold cin, cadd, cx, clo, chi; cbn [fst snd]. intros H.
  exists (k - N.to_nat K1)%nat. lia.
Qed.
Lemma cadd_cx_cx (A B : N) : cadd (cx A) (cx B) = cx (A + B)%N.
Proof. reflexivity. Qed.
Lemma rok_of_match (o : option (word * N))
    (pre r : word) (fr : N) :
  match o with
  | Some (s', f') => ROk (pre ++ s') f'
  | None => RBad
  end = ROk r fr ->
  exists s', o = Some (s', fr) /\ r = pre ++ s'.
Proof.
  destruct o as [[s' f']|]; intros H; [|discriminate].
  injection H as <- <-. exists s'. split; reflexivity.
Qed.
Lemma cdt_leaf_convc (fuel : nat) (w : word) (f : N) (j : nat)
    (vd : bool) (w' : word) (f' : N) (d : cost) :
  (match wat w j with
   | Some (_,z,_) => (z =? 1)%N
   | None => false
   end) = true ->
  cdeliver_tick (S fuel) w f j vd = (ROk w' f', d) ->
  exists s',
    cleaf_act (skipn j w) f = (Some (s', f'), d)
    /\ w' = firstn j w ++ s'.
Proof.
  intros HZ HDT.
  cbn [cdeliver_tick] in HDT.
  destruct (wat w j) as [[[o z] c]|] eqn:EWJ; [|discriminate].
  cbn beta iota in HZ. apply N.eqb_eq in HZ. subst z.
  change ((1 =? 1)%N) with true in HDT.
  destruct ((2 <=? o)%N) eqn:EO2; cbn [andb] in HDT.
  2:{ change ((3 <=? 1)%N) with false in HDT.
      change ((1 =? 2)%N) with false in HDT.
      cbn [andb] in HDT. discriminate. }
  unfold cmap in HDT.
  pose proof (f_equal fst HDT) as HW. cbn [fst] in HW.
  pose proof (f_equal snd HDT) as HD. cbn [snd] in HD.
  apply rok_of_match in HW. destruct HW as (s' & EO & ER).
  exists s'. split; [|exact ER].
  apply injective_projections; cbn [fst snd].
  - exact EO.
  - rewrite <- HD. symmetry. apply cadd_czero_l.
Qed.
Section Retag8ForInduction.
Variable HL8 : forall st : word, LeafFTripC st.
Lemma retag8_leaf1c (X : N) (cols s2' t : word) (f f2 A C : N)
      (dl : cost) (kl : nat) :
  (5 <= X)%N ->
  forallb is_col cols = true ->
  cleaf_act ((A,1,C)%N :: t) f = (Some (s2', f2), dl) ->
  cin kl dl ->
  exists c p q,
    FTripC c (N.of_nat kl + wcolcost cols + 2 * X + 30)%N
      (sdec ((X,3,1)%N :: (8,2,1)%N :: (cols ++ (A,1,C)%N :: t)) f) p q
    /\ wconf [] 0 ((1,S p)::q)
       = wconf [] 0 (sdec ((X-1,1,1)%N :: (11,2,1)%N :: (cols ++ s2')) f2).
Proof.
  intros E5 HC HLA Hk.
  destruct (HL8 ((A,1,C)%N :: t) f s2' f2 dl kl HLA Hk)
    as [(c & p & q & K & EK & HT & EQ)
       |(c & p & q & K & EK & HS & EQq & ESL & _)].
  2:{ rewrite (sand_leaf_z1 A C t) in ESL. discriminate. }
  destruct (ren_liftc_col cols ((A,1,C)%N :: t) s2' f f2 c p K q HC HT EQ)
    as (c2 & p2 & q2 & HF2 & EQ2).
  destruct (retag8_stagec X (cols ++ (A,1,C)%N :: t) (cols ++ s2') f f2
              c2 p2 (K + wcolcost cols)%N q2 E5 HF2 EQ2)
    as (c3 & p3 & q3 & HF3 & EQ3).
  exists c3, p3, q3. split; [|exact EQ3].
  refine (DebrisLeafC_FTripC_cost_eq _ _ _ _ _ _ _ HF3). lia.
Qed.
Lemma retag8_route1c (X : N) (rest : word) (f : N) (fuel j : nat)
    (s3 : word) (f3 : N) (d : cost) (k : nat) :
  (5 <= X)%N ->
  tick_target ((X-1,1,1)%N :: (11,2,1)%N :: rest) 2 = Some j ->
  (match wat ((X-1,1,1)%N :: (11,2,1)%N :: rest) j with
   | Some (_,z,_) => (z =? 1)%N | None => false end) = true ->
  cdeliver_tick (S fuel)
    ((X-1,1,1)%N :: (11,2,1)%N :: rest) f j true
    = (ROk s3 f3, d) ->
  cin k
    (cadd
       (d_casc_tick8 X
          (tickcols
             ((X-1,1,1)%N :: (11,2,1)%N :: rest) j)) d) ->
  exists c p q,
    FTripC c (N.of_nat k) (sdec ((X,3,1)%N :: (8,2,1)%N :: rest) f) p q
    /\ wconf [] 0 ((1,S p)::q) = wconf [] 0 (sdec s3 f3).
Proof.
  intros E5 HTT HZ HDT Hk.
  set (s2 := (((X-1,1,1)%N :: (11,2,1)%N :: rest) : word)) in *.
  assert (HTS : tick_target_s rest 2 = Some j).
  { unfold tick_target in HTT. exact HTT. }
  destruct (tt_split rest 2 j HTS)
    as (mid & g & t & EREST & ELEN & EIJ & HCOLS & _).
  destruct j as [|[|kk]]; [lia|lia|].
  replace (S (S kk) - 2)%nat with kk in * by lia.
  assert (ESK : skipn kk rest = g :: t).
  { rewrite EREST, <- ELEN, skipn_app, skipn_all2 by lia.
    rewrite PeanoNat.Nat.sub_diag. reflexivity. }
  assert (EFN : firstn kk rest = mid).
  { rewrite EREST, <- ELEN, firstn_app, firstn_all2 by lia.
    rewrite PeanoNat.Nat.sub_diag. cbn [firstn]. rewrite app_nil_r.
    reflexivity. }
  assert (HSK2 : skipn (S (S kk)) s2 = g :: t)
    by (unfold s2; cbn [skipn]; exact ESK).
  assert (EWAT : wat s2 (S (S kk)) = Some g)
    by (rewrite wat_skipn, HSK2; reflexivity).
  assert (ECOLS : tickcols s2 (S (S kk)) = mid).
  { unfold tickcols, s2. cbn [firstn skipn]. exact EFN. }
  rewrite ECOLS in Hk.
  rewrite EWAT in HZ.
  destruct g as [[A z] Cc]. cbn in HZ. apply N.eqb_eq in HZ. subst z.
  assert (HZ2 : (match wat s2 (S (S kk)) with
                 | Some (_,z,_) => (z =? 1)%N | None => false end) = true)
    by (rewrite EWAT; reflexivity).
  destruct (cdt_leaf_convc fuel s2 f (S (S kk)) true s3 f3 d HZ2 HDT)
    as (s' & ELA & ES3).
  rewrite HSK2 in ELA.
  assert (HFN2 : firstn (S (S kk)) s2
                  = (X-1,1,1)%N :: (11,2,1)%N :: mid)
    by (unfold s2; cbn [firstn]; rewrite EFN; reflexivity).
  rewrite HFN2 in ES3.
  assert (HC2 : forallb is_col mid = true).
  { revert HCOLS. clear. induction mid as [|gg mid' IH]; [reflexivity|].
    cbn [forallb]. intros HH. apply andb_prop in HH. destruct HH as (HG & HT).
    apply andb_prop in HG. destruct HG as (HG & _).
    rewrite HG. cbn [andb]. exact (IH HT). }
  unfold d_casc_tick8 in Hk.
  destruct (cin_cadd_cx_split _ _ _ Hk) as (kl & EK & Hkl).
  destruct (retag8_leaf1c X mid s' t f f3 A Cc d kl E5 HC2 ELA Hkl)
    as (c & p & q & HF & EQ).
  exists c, p, q. split.
  - rewrite EREST.
    refine (DebrisLeafC_FTripC_cost_eq _ _ _ _ _ _ _ HF).
    pose proof (ccolcost_wcolcost mid) as EW. lia.
  - rewrite ES3. cbn [app]. exact EQ.
Qed.
Lemma retag8_route1c_any (X : N) (rest : word) (f : N)
    (fuel j : nat) (s3 : word) (f3 : N) (d : cost) (k : nat) :
  (5 <= X)%N ->
  tick_target ((X-1,1,1)%N :: (11,2,1)%N :: rest) 2 = Some j ->
  (match wat ((X-1,1,1)%N :: (11,2,1)%N :: rest) j with
   | Some (_,z,_) => (z =? 1)%N | None => false end) = true ->
  cdeliver_tick fuel
    ((X-1,1,1)%N :: (11,2,1)%N :: rest) f j true
    = (ROk s3 f3, d) ->
  cin k
    (cadd
       (d_casc_tick8 X
          (tickcols
             ((X-1,1,1)%N :: (11,2,1)%N :: rest) j)) d) ->
  exists c p q,
    FTripC c (N.of_nat k) (sdec ((X,3,1)%N :: (8,2,1)%N :: rest) f) p q
    /\ wconf [] 0 ((1,S p)::q) = wconf [] 0 (sdec s3 f3).
Proof.
  intros E5 HTT HZ HDT Hk.
  destruct fuel as [|fuel0].
  { cbn [cdeliver_tick] in HDT. discriminate. }
  exact (retag8_route1c X rest f fuel0 j s3 f3 d k
           E5 HTT HZ HDT Hk).
Qed.
End Retag8ForInduction.
Ltac slot_dead :=
  first
    [ match goal with HR : _ = (Some _, _) |- _ => discriminate HR end
    | match goal with
      | HR : _ = (Some _, ?d), Hk : cin _ ?d |- _ =>
          inversion HR; subst;
          cbv [d_rseg_endR d_rseg_lawR d_rseg_inner d_rseg_endY d_rseg_tail
               d_casc_dtb d_casc_leaf
               d_casc_tick8 cundef] in Hk;
          exact (cundef_absurd _ _ Hk)
      end ].
Lemma renew_ftripc_step (n : nat) :
  (forall st, LeafFTripC st) -> FCPropC n -> RNPropC n -> RNPropC (S n).
Proof.
  intros HL IHF IHR cols s f body f2 d k HPC HR Hk.
  cbn [crenew_seg] in HR.
  destruct s as [|[[o1 z1] c1] rest]; [discriminate HR|].
  killmN HR.
  destruct rest as [|[[o5 z5] Bq] rest2].
  {
    destruct (endR_seg cols f) as [bd|] eqn:EES; [|discriminate HR].
    unfold d_rseg_endR in HR.
    pose proof (f_equal fst HR) as HW. cbn [fst] in HW.
    pose proof (f_equal snd HR) as HD. cbn [snd] in HD.
    injection HW as <- <-.
    rewrite <- HD in Hk.
    exact (dseg_endR_tripc cols bd f k EES Hk). }
  destruct (((o5 =? 4) && (z5 =? 2) && (1 <=? Bq))%N) eqn:EG5.
  2:{ destruct (((z5 =? 3) && (Bq =? 1)
                && match rest2 with [] => true | _ => false end
                && (f =? 4) && (1 <=? o5))%N) eqn:EGY.
      -
        apply andb_prop in EGY. destruct EGY as (EGY & EO51).
        apply andb_prop in EGY. destruct EGY as (EGY & EF4).
        apply andb_prop in EGY. destruct EGY as (EGY & ENIL).
        apply andb_prop in EGY. destruct EGY as (EZ53 & EB1).
        apply N.eqb_eq in EZ53, EB1, EF4. apply N.leb_le in EO51.
        subst z5 Bq f.
        destruct rest2 as [|g6 rest3]; [|discriminate ENIL].
        destruct (endY_seg cols o5) as [bd|] eqn:EYS;
          [|discriminate HR].
        unfold d_rseg_endY in HR.
        pose proof (f_equal fst HR) as HW. cbn [fst] in HW.
        pose proof (f_equal snd HR) as HD. cbn [snd] in HD.
        injection HW as <- <-.
        rewrite <- HD in Hk.
        exact (dseg_endY_tripc cols bd o5 k EO51 EYS Hk).
      - discriminate HR. }
  apply andb_prop in EG5. destruct EG5 as (EG5a & EGB).
  apply andb_prop in EG5a. destruct EG5a as (EO5 & EZ5).
  apply N.eqb_eq in EO5, EZ5. apply N.leb_le in EGB. subst o5 z5.
  destruct rest2 as [|g2 rest2t].
  {
    unfold d_rseg_lawR in HR.
    pose proof (f_equal fst HR) as HW. cbn [fst] in HW.
    pose proof (f_equal snd HR) as HD. cbn [snd] in HD.
    rewrite <- HD in Hk.
    exact (dseg_lawR_tripc cols body Bq f f2 k EGB HW Hk). }
  destruct (jump_seg cols Bq) as [seg|] eqn:EJS; [|discriminate HR].
  destruct (seek (g2 :: rest2t)) as [cols2 s3] eqn:ESK.
  destruct (seek_split (g2 :: rest2t) cols2 s3 ESK) as (EREST2 & HC2).
  destruct (fst (crenew_seg n cols2 s3 f)) as [[bd f']|] eqn:ERS.
  {
    inversion HR; subst.
    pose proof (surjective_pairing (crenew_seg n cols2 s3 f)) as ESP.
    rewrite ERS in ESP.
    unfold d_jsplice in Hk.
    destruct (cin_cadd_cx_split _ _ _ Hk) as (k2 & EK & Hk2).
    destruct (IHR cols2 s3 f bd f2 _ k2 HC2 ESP Hk2)
      as (ci & pi & qi & HFi & EQi).
    destruct (casc_jump_innerc cols (cols2 ++ s3) bd seg Bq f f2
                ci pi (N.of_nat k2) qi HPC EJS EGB HFi EQi)
      as (c2 & p2 & q2 & HF2 & EQ2).
    exists c2, p2, q2. split; [|exact EQ2].
    rewrite EREST2.
    refine (DebrisLeafC_FTripC_cost_eq _ _ _ _ _ _ _ HF2).
    pose proof (ccolcost_wcolcost cols) as EW1. lia. }
  destruct s3 as [|[[o7 z7] c7] s3t].
  { unfold cdrop in HR; cbn [fst snd] in HR.
    destruct (fst (cleaf_act ([] : word) f)) as [[s3' f']|] eqn:ELA;
      cbn [fst snd] in HR.
    { slot_dead. }
    pose proof (f_equal fst HR) as HW. cbn [fst] in HW.
    pose proof (f_equal snd HR) as HD. cbn [snd] in HD.
    rewrite <- HD in Hk.
    unfold d_rseg_tail in Hk.
    destruct (5 <=? f)%N eqn:EF5.
    { apply N.leb_le in EF5.
      injection HW as <- <-.
      apply cin_cx_eq in Hk.
      destruct (ren_far_tailc cols2 f HC2 EF5)
        as (ci & pi & qi & HFi & EQi).
      destruct (casc_jump_innerc cols cols2
                  (cols2 ++ [((f-1)%N,1,1)%N]) seg Bq f 3%N
                  ci pi _ qi HPC EJS EGB HFi EQi)
        as (c2 & p2 & q2 & HF2 & EQ2).
      exists c2, p2, q2. split; [|exact EQ2].
      rewrite EREST2, app_nil_r.
      refine (DebrisLeafC_FTripC_cost_eq _ _ _ _ _ _ _ HF2).
      pose proof (ccolcost_wcolcost cols) as EW1.
      pose proof (ccolcost_wcolcost cols2) as EW2. lia. }
    destruct (f =? 4)%N eqn:EF4; [|discriminate HW].
    apply N.eqb_eq in EF4. subst f.
    destruct (dtb4_convc cols2) as [[cols2' Kd]|] eqn:EDC4.
    { assert (EDT4 : dtb4_conv cols2 = Some cols2').
      { pose proof (dtb4_convc_proj cols2) as EP.
        rewrite EDC4 in EP. cbn [option_map fst] in EP.
        symmetry. exact EP. }
      rewrite EDT4 in HW. injection HW as <- <-.
      apply cin_cx_eq in Hk.
      destruct (dtb4_convc_tripc cols2 cols2' Kd HC2 EDC4)
        as (ci & pi & qi & HFi & EQi).
      destruct (casc_jump_innerc cols cols2 cols2' seg Bq 4%N 4%N
                  ci pi _ qi HPC EJS EGB HFi EQi)
        as (c2 & p2 & q2 & HF2 & EQ2).
      exists c2, p2, q2. split; [|exact EQ2].
      rewrite EREST2, app_nil_r.
      refine (DebrisLeafC_FTripC_cost_eq _ _ _ _ _ _ _ HF2).
      pose proof (ccolcost_wcolcost cols) as EW1. lia. }
    pose proof (dtb4_convc_proj cols2) as EP.
    rewrite EDC4 in EP. cbn [option_map fst] in EP.
    rewrite <- EP in HW.
    destruct (forallb w42 cols2) eqn:EW42;
      [|exact (cundef_absurd _ _ Hk)].
    destruct (lawR_seg cols Bq) as [seg2|] eqn:ELS;
      [|discriminate HW].
    injection HW as <- <-.
    apply cin_cx_eq in Hk.
    destruct (casc_lawR_innerc cols cols2 seg2 Bq HPC ELS EGB EW42)
      as (c2 & p2 & q2 & HF2 & EQ2).
    exists c2, p2, q2. split; [|exact EQ2].
    rewrite EREST2, app_nil_r.
    refine (DebrisLeafC_FTripC_cost_eq _ _ _ _ _ _ _ HF2).
    symmetry. exact Hk. }
  destruct (((z7 =? 3) && (c7 =? 1))%N) eqn:EZ7.
  {
    unfold cmap in HR; cbn [fst snd] in HR.
    match type of HR with
    | context [ fst (cfire_comp ?a ?b ?c) ] =>
        destruct (fst (cfire_comp a b c)) as [[s3' f']|] eqn:EFC
    end;
      cbn [fst snd] in HR.
    2:{ slot_dead. }
    inversion HR; subst.
    match type of EFC with
    | fst ?X = _ => pose proof (surjective_pairing X) as ESP
    end.
    rewrite EFC in ESP.
    unfold d_jsplice, d_cols in Hk. rewrite cadd_cx_cx in Hk.
    destruct (cin_cadd_cx_split _ _ _ Hk) as (k3 & EK & Hk3).
    destruct (IHF _ f s3' f2 _ k3 ESP Hk3) as (ci & pi & qi & HFi & EQi).
    destruct (DebrisLeafC_ren_liftc cols2 _ s3' f f2 ci pi (N.of_nat k3) qi HC2 HFi EQi)
      as (cL & pL & qL & HFL & EQL).
    destruct (casc_jump_innerc cols _ (cols2 ++ s3') seg Bq f f2
                cL pL (N.of_nat k3 + wcolcost cols2)%N qL HPC EJS EGB HFL EQL)
      as (c2 & p2 & q2 & HF2 & EQ2).
    exists c2, p2, q2. split; [|exact EQ2].
    rewrite EREST2.
    refine (DebrisLeafC_FTripC_cost_eq _ _ _ _ _ _ _ HF2).
    pose proof (ccolcost_wcolcost cols) as EW1.
    pose proof (ccolcost_wcolcost cols2) as EW2. lia. }
  match type of HR with
  | context [ sand_leaf ?a ] => destruct (sand_leaf a) eqn:ESL
  end.
  { cbn [fst snd] in HR; slot_dead. }
  unfold cmap in HR; cbn [fst snd] in HR.
  match type of HR with
  | context [ fst (cleaf_act ?a ?b) ] =>
      destruct (fst (cleaf_act a b)) as [[s3' f']|] eqn:ELA
  end;
    cbn [fst snd] in HR.
  2:{ slot_dead. }
  inversion HR; subst.
  match type of ELA with
  | fst ?X = _ => pose proof (surjective_pairing X) as ESP
  end.
  rewrite ELA in ESP.
  unfold d_rseg_inner in Hk.
  destruct (cin_cadd_cx_split _ _ _ Hk) as (kl & EK & Hkl).
  destruct (HL _ f s3' f2 _ kl ESP Hkl)
    as [(ci & pi & qi & K & EKK & HFi & EQi)
       |(ci & pi & qi & K & EKK & HSi & EQq & HSL & _)].
  2:{ rewrite HSL in ESL. discriminate ESL. }
  destruct (DebrisLeafC_ren_liftc cols2 _ s3' f f2 ci pi K qi HC2 HFi EQi)
    as (cL & pL & qL & HFL & EQL).
  destruct (casc_jump_innerc cols _ (cols2 ++ s3') seg Bq f f2
              cL pL (K + wcolcost cols2)%N qL HPC EJS EGB HFL EQL)
    as (c2 & p2 & q2 & HF2 & EQ2).
  exists c2, p2, q2. split; [|exact EQ2].
  rewrite EREST2.
  refine (DebrisLeafC_FTripC_cost_eq _ _ _ _ _ _ _ HF2).
  pose proof (ccolcost_wcolcost cols) as EW1.
  pose proof (ccolcost_wcolcost cols2) as EW2. lia.
Qed.
Lemma fire_comp_ftripc_step (n : nat) :
  (forall st, LeafFTripC st) -> FCPropC n -> RNPropC n -> FCPropC (S n).
Proof.
  intros HL IHF IHR s f s' f2 d k HFC Hk.
  cbn [cfire_comp] in HFC.
  destruct s as [|[[X zX] cX] rest0]; [discriminate HFC|].
  killmN HFC.
  destruct (negb (5 <=? X)%N) eqn:EX5; [discriminate HFC|].
  apply negb_false_iff, N.leb_le in EX5.
  destruct rest0 as [|[[Y zY] cY] rest].
  {
    unfold d_casc_far in HFC, Hk.
    destruct (2 <=? f)%N eqn:EF2; [|discriminate HFC].
    apply N.leb_le in EF2.
    inversion HFC; subst.
    apply cin_cx_eq in Hk. rewrite Hk.
    exact (casc_farc X f EX5 EF2). }
  destruct (((Y =? 4) && (zY =? 2))%N) eqn:EY4.
  { apply andb_prop in EY4. destruct EY4 as (EY & EZY).
    apply N.eqb_eq in EY, EZY. subst Y zY.
    destruct (negb (1 <=? cY)%N) eqn:ENL; [discriminate HFC|].
    apply negb_false_iff, N.leb_le in ENL.
    destruct rest as [|g1 rest1].
    {
      unfold d_casc_lvl_end in HFC, Hk.
      destruct (f =? 4)%N eqn:EF4.
      { apply N.eqb_eq in EF4. subst f.
        inversion HFC; subst.
        apply cin_cx_eq in Hk. rewrite Hk.
        exact (casc_lvl_end4c X cY EX5 ENL). }
      destruct (5 <=? f)%N eqn:EF5; [|discriminate HFC].
      apply N.leb_le in EF5.
      inversion HFC; subst.
      apply cin_cx_eq in Hk. rewrite Hk.
      destruct (casc_lvl_end5c X cY f EX5 ENL EF5) as (c & p & q & HF & EQ).
      exists c, p, q. split; [exact HF|].
