    apply cin_cx_eq in Hk. rewrite Hk.
    exact (casc_z1endc X Y f EX5 GY EF2). }
  destruct (((zY =? 3) && (cY =? 1) && (1 <=? Y) && (f =? 4))%N) eqn:GZ3.
  {
    apply andb_prop in GZ3. destruct GZ3 as (GZ3a & GF4).
    apply andb_prop in GZ3a. destruct GZ3a as (GZ3b & GY).
    apply andb_prop in GZ3b. destruct GZ3b as (GZ & GC).
    apply N.eqb_eq in GZ, GC, GF4. apply N.leb_le in GY. subst zY cY f.
    destruct rest as [|[[o2 z2] c2] r2]; [discriminate HFC|].
    destruct r2 as [|g3 r3]; [|discriminate HFC].
    destruct (((o2 =? 4) && (z2 =? 2) && (1 <=? c2))%N) eqn:GL;
      [|discriminate HFC].
    apply andb_prop in GL. destruct GL as (GLa & GC2).
    apply andb_prop in GLa. destruct GLa as (GO2 & GZ2).
    apply N.eqb_eq in GO2, GZ2. apply N.leb_le in GC2. subst o2 z2.
    inversion HFC; subst.
    unfold d_casc_z3, lvlc in Hk. cbn [gC] in Hk.
    apply cin_cx_eq in Hk. rewrite Hk.
    exact (casc_z3c X Y c2 EX5 GY GC2). }
  destruct (((zY =? 1) && (cY =? 1) && (1 <=? Y)
             && match rest with
                | (o2,z2,c2) :: _ => (o2 =? 4) && (z2 =? 2) && (1 <=? c2)
                | [] => false
                end)%N) eqn:GZL.
  {
    apply andb_prop in GZL. destruct GZL as (GZLa & GZLb).
    apply andb_prop in GZLa. destruct GZLa as (GZLc & GY).
    apply andb_prop in GZLc. destruct GZLc as (GZ & GC).
    apply N.eqb_eq in GZ, GC. apply N.leb_le in GY. subst zY cY.
    destruct rest as [|[[o2 z2] c2] r2]; [discriminate GZLb|].
    apply andb_prop in GZLb. destruct GZLb as (GLa & GC2).
    apply andb_prop in GLa. destruct GLa as (GO2 & GZ2).
    apply N.eqb_eq in GO2, GZ2. apply N.leb_le in GC2. subst o2 z2.
    inversion HFC; subst.
    unfold d_casc_z1lvl, d_casc_z1law in Hk.
    apply cin_cx_eq in Hk. rewrite Hk.
    exact (casc_z1lvlc X Y c2 r2 f2 EX5 GY GC2). }
  destruct (((zY =? 1) && (2 <=? cY) && (2 <=? Y))%N) eqn:GSP.
  {
    apply andb_prop in GSP. destruct GSP as (GSPa & GY2).
    apply andb_prop in GSPa. destruct GSPa as (GZ & GCY).
    apply N.eqb_eq in GZ. apply N.leb_le in GCY, GY2. subst zY.
    inversion HFC; subst.
    unfold d_casc_z1split, d_casc_z1law in Hk.
    apply cin_cx_eq in Hk. rewrite Hk.
    exact (casc_z1splitc X Y cY rest f2 EX5 GY2 GCY). }
  destruct (((zY =? 1) && (cY =? 1) && (1 <=? Y)
             && match rest with
                | (o2,z2,c2) :: _ => (z2 =? 1) && (c2 =? 1) && (1 <=? o2)
                | [] => false
                end)%N) eqn:GZ11.
  {
    apply andb_prop in GZ11. destruct GZ11 as (GZ11a & GZ11b).
    apply andb_prop in GZ11a. destruct GZ11a as (GZ11c & GY).
    apply andb_prop in GZ11c. destruct GZ11c as (GZ & GC).
    apply N.eqb_eq in GZ, GC. apply N.leb_le in GY. subst zY cY.
    destruct rest as [|[[o2 z2] c2] r2]; [discriminate GZ11b|].
    apply andb_prop in GZ11b. destruct GZ11b as (GLa & GO2).
    apply andb_prop in GLa. destruct GLa as (GZ2 & GC2).
    apply N.eqb_eq in GZ2, GC2. apply N.leb_le in GO2. subst z2 c2.
    destruct (o2 =? 1)%N eqn:EO1;
      (inversion HFC; subst;
       unfold d_casc_z1z1, d_casc_z1law in Hk;
       apply cin_cx_eq in Hk; rewrite Hk;
       destruct (casc_z1z1c X Y o2 r2 f2 EX5 GY GO2)
         as (c & p & q & HF & EQ);
       exists c, p, q;
       split; [exact HF | rewrite EQ, EO1; reflexivity]). }
  destruct (((zY =? 1) && (cY =? 1) && (1 <=? Y)
             && match rest with
                | (o2,z2,c2) :: _ =>
                    (z2 =? 2) && (1 <=? o2) && (o2 <=? 3) && (c2 =? 1)
                | [] => false
                end)%N) eqn:GZ12.
  {
    apply andb_prop in GZ12. destruct GZ12 as (GZ12a & GZ12b).
    apply andb_prop in GZ12a. destruct GZ12a as (GZ12c & GY).
    apply andb_prop in GZ12c. destruct GZ12c as (GZ & GC).
    apply N.eqb_eq in GZ, GC. apply N.leb_le in GY. subst zY cY.
    destruct rest as [|[[o2 z2] c2] r2]; [discriminate GZ12b|].
    apply andb_prop in GZ12b. destruct GZ12b as (GLa & GC2).
    apply andb_prop in GLa. destruct GLa as (GLb & GO3).
    apply andb_prop in GLb. destruct GLb as (GZ2 & GO2).
    apply N.eqb_eq in GZ2, GC2. apply N.leb_le in GO2, GO3. subst z2 c2.
    destruct (o2 =? 1)%N eqn:EO1;
      (inversion HFC; subst;
       unfold d_casc_z1z2, d_casc_z1law in Hk;
       apply cin_cx_eq in Hk; rewrite Hk;
       destruct (casc_z1z2c X Y o2 r2 f2 EX5 GY GO2)
         as (c & p & q & HF & EQ);
       exists c, p, q;
       split; [exact HF | rewrite EQ, EO1; reflexivity]). }
  discriminate HFC.
Qed.
Theorem fire_renew_ftripc (HL : forall st, LeafFTripC st) (n : nat) :
  FCPropC n /\ RNPropC n.
Proof.
  induction n as [|n IH].
  { split; [exact FCPropC_0 | exact RNPropC_0]. }
  destruct IH as (IHF & IHR).
  split; [exact (fire_comp_ftripc_step n HL IHF IHR)
        | exact (renew_ftripc_step n HL IHF IHR)].
Qed.
Corollary fire_comp_ftripc (HL : forall st, LeafFTripC st) (n : nat) :
  FCPropC n.
Proof. apply (fire_renew_ftripc HL). Qed.
Corollary renew_ftripc (HL : forall st, LeafFTripC st) (n : nat) :
  RNPropC n.
Proof. apply (fire_renew_ftripc HL). Qed.
Corollary fire_comp_returnc (HL : forall st, LeafFTripC st)
      (n : nat) (c_0 : N) (p' : word)
      (s s' : word) (f f2 : N) (d : cost) (k : nat) :
  zpre p' -> (1 <= c_0)%N ->
  cfire_comp n s f = (Some (s', f2), d) ->
  cin k d ->
  creach (cx (bsum ((2,2,c_0)%N :: p') + (N.of_nat k + 6))%N)
    (wconf [] 0 (sdecode (((2,2,c_0)%N :: p') ++ s) f))
    (wconf [] 0 (sdecode ((2,2,1)%N :: ((2,2,c_0)%N :: p') ++ s') f2)).
Proof.
  intros HP HC0 HFC Hk.
  destruct (fire_comp_ftripc HL n s f s' f2 d k HFC Hk)
    as (c & pp & q & HT & EQ).
  exact (leaf_trip_returnc c_0 p' s s' f f2 c pp (N.of_nat k) q HP HC0 HT EQ).
Qed.
