Opaque FUEL.
Opaque deliver_tick fire renewal chain_merge_advance.
Opaque fire_comp leaf_act debris_to_blank.
Opaque renew_seg.
Lemma ftz1 (A : N) (a : nat) :
  N.to_nat A = S (S a) -> (2 * A + 3)%N = (2 * N.of_nat a + 7)%N.
Proof.
  intros E.
  rewrite <- (N2Nat.id A), E, !Nat2N.inj_succ. lia.
Qed.
Lemma leaf_z1_ftripC (A C : N) (rest s' : word) (f f2 : N) :
  leaf_act ((A,1,C)%N :: rest) f = Some (s', f2) ->
  exists p q,
    FTripC 2 (2 * A + 3)%N (sdec ((A,1,C)%N :: rest) f) p q
    /\ wconf [] 0 ((1,S p)::q) = wconf [] 0 (sdec s' f2).
Proof.
  intros HLA.
  Transparent leaf_act.
  cbn [leaf_act] in HLA.
  Opaque leaf_act.
  destruct ((2 <=? C)%N) eqn:EC2.
  {
    destruct ((2 <=? A)%N) eqn:EA2; [|discriminate].
    apply N.leb_le in EC2. apply N.leb_le in EA2.
    injection HLA as <- <-.
    destruct (to_nat_ge2 A EA2) as [a EA].
    destruct (to_nat_ge2 C EC2) as [cc EC].
    assert (EC1 : N.to_nat (C - 2)%N = cc)
      by (rewrite N2Nat.inj_sub; rewrite EC;
          change (N.to_nat 2%N) with 2%nat; lia).
    assert (EA1 : N.to_nat (A - 1)%N = S a)
      by (rewrite N2Nat.inj_sub; rewrite EA;
          change (N.to_nat 1%N) with 1%nat; lia).
    exists (S a),
      ((0,1%nat)::(1,S a)::(0,1%nat)
         :: pair_runs (S (S a)) 1 cc
         ++ expand (map gdecode rest) ++ frun f).
    rewrite (ftz1 A a EA).
    split.
    - unfold sdec.
      cbn [map gdecode expand].
      rewrite EA, EC.
      cbn [pair_runs].
      rewrite <- !app_assoc.
      exact (FTripC_split a _).
    - unfold sdec.
      destruct ((2 <? C)%N) eqn:ELT.
      + cbn [map gdecode expand].
        rewrite map_app, expand_app.
        cbn [map gdecode expand].
        rewrite EA, EA1, EC1.
        change (N.to_nat 1%N) with 1%nat.
        cbn [pair_runs].
        rewrite <- !app_assoc.
        cbn [app].
        reflexivity.
      + apply N.ltb_ge in ELT.
        assert (E2 : C = 2%N) by lia.
        subst C.
        change (N.to_nat 2%N) with 2%nat in EC.
        assert (cc = 0%nat) by lia. subst cc.
        change (N.to_nat (2 - 2)%N) with 0%nat.
        cbn [pair_runs app map gdecode expand].
        rewrite EA, EA1.
        change (N.to_nat 1%N) with 1%nat.
        cbn [pair_runs].
        rewrite <- !app_assoc.
        cbn [app].
        reflexivity. }
  destruct (negb (C =? 1)%N || negb (2 <=? A)%N) eqn:ENG; [discriminate|].
  apply orb_false_iff in ENG. destruct ENG as (EC1 & EA1).
  apply negb_false_iff in EC1. apply negb_false_iff in EA1.
  apply N.eqb_eq in EC1. apply N.leb_le in EA1. subst C.
  destruct rest as [|[[B zb] cb] t2].
  {
    destruct ((2 <=? f)%N) eqn:EF2.
    {
      apply N.leb_le in EF2.
      injection HLA as <- <-.
      destruct (to_nat_ge2 A EA1) as [a EA].
      destruct (to_nat_ge2 f EF2) as [fp EF].
      assert (EF1 : N.to_nat (f - 1)%N = S fp)
        by (rewrite N2Nat.inj_sub; rewrite EF;
            change (N.to_nat 1%N) with 1%nat; lia).
      exists (1 + a), ((0,1%nat)::[(1,S fp)]).
      rewrite (ftz1 A a EA).
      split.
      - unfold sdec.
        cbn [map gdecode expand app].
        rewrite EA.
        change (N.to_nat 1%N) with 1%nat.
        destruct f as [|pf]; [exfalso; lia|].
        cbn [frun].
        rewrite EF.
        cbn [pair_runs app].
        exact (FTripC_fartick a fp).
      - unfold sdec.
        cbn [map gdecode expand app].
        rewrite EA.
        change (N.to_nat 1%N) with 1%nat.
        destruct ((f - 1)%N) as [|pf1] eqn:EFM; [exfalso; lia|].
        replace (frun (N.pos pf1)) with ([(1, S fp)] : wside).
        2: { simpl. simpl in EF1. rewrite EF1. reflexivity. }
        cbn [pair_runs app].
        reflexivity. }
    destruct ((f =? 1)%N) eqn:EF1e.
    {
      apply N.eqb_eq in EF1e. subst f.
      injection HLA as <- <-.
      destruct (to_nat_ge2 A EA1) as [a EA].
      exists (1 + a), [(0,1%nat)].
      rewrite (ftz1 A a EA).
      split.
      - unfold sdec.
        cbn [map gdecode expand app frun].
        rewrite EA.
        change (N.to_nat 1%N) with 1%nat.
        cbn [pair_runs app].
        exact (FTripC_far1 a).
      - unfold sdec.
        cbn [map gdecode expand app].
        destruct A as [|pX]; [discriminate|].
        cbn [frun].
        change ((1,S (1 + a))::[(0,1%nat)])
          with ([(1,(2 + a)%nat)] ++ [(0,1%nat)]).
        rewrite wconf_snoc0.
        rewrite EA.
        change ((2 + a)%nat) with (S (S a)).
        reflexivity. }
    discriminate. }
  destruct ((zb =? 2)%N && negb (B =? 8)%N
            && (negb (B =? 4)%N
                || ((cb =? 1)%N
                    && match t2 with
                       | (o2,z2,_) :: _ =>
                           negb (((o2 =? 4)%N || (o2 =? 8)%N) && (z2 =? 2)%N)
                       | [] => true
                       end))) eqn:EOB.
  {
    apply andb_prop in EOB. destruct EOB as (EOB & _).
    apply andb_prop in EOB. destruct EOB as (EZB & _).
    apply N.eqb_eq in EZB. subst zb.
    destruct ((B =? 5)%N && (cb =? 1)%N
              && match t2 with
                 | (o2,z2,_) :: _ => (o2 =? 4)%N && (z2 =? 2)%N
                 | [] => false
                 end) eqn:EAB.
    {
      apply andb_prop in EAB. destruct EAB as (EAB & ET2).
      apply andb_prop in EAB. destruct EAB as (EB5 & EC1b).
      apply N.eqb_eq in EB5. apply N.eqb_eq in EC1b. subst B cb.
      destruct t2 as [|[[o2 z2] c2] t3]; [discriminate|].
      apply andb_prop in ET2. destruct ET2 as (EO2 & EZ2).
      apply N.eqb_eq in EO2. apply N.eqb_eq in EZ2. subst o2 z2.
      injection HLA as <- <-.
      destruct (to_nat_ge2 A EA1) as [a EA].
      assert (EC2p : N.to_nat (c2 + 1)%N = S (N.to_nat c2))
        by (rewrite N2Nat.inj_add;
            change (N.to_nat 1%N) with 1%nat; lia).
      exists (1 + a),
        ((0,1%nat)::(1,4%nat)::(0,2%nat)
           :: pair_runs 4 2 (N.to_nat c2)
              ++ expand (map gdecode t3) ++ frun f).
      rewrite (ftz1 A a EA).
      split.
      - unfold sdec.
        cbn [map gdecode expand].
        rewrite EA.
        change (N.to_nat 1%N) with 1%nat.
        change (N.to_nat 2%N) with 2%nat.
        change (N.to_nat 5%N) with 5%nat.
        change (N.to_nat 4%N) with 4%nat.
        cbn [pair_runs].
        rewrite <- !app_assoc.
        cbn [app].
        exact (FTripC_tick a 3 _).
      - unfold sdec.
        cbn [map gdecode expand].
        rewrite EA, EC2p.
        change (N.to_nat 1%N) with 1%nat.
        change (N.to_nat 2%N) with 2%nat.
        change (N.to_nat 4%N) with 4%nat.
        cbn [pair_runs].
        rewrite <- !app_assoc.
        cbn [app].
        reflexivity. }
    destruct ((B =? 1)%N) eqn:EB1.
    {
      apply N.eqb_eq in EB1. subst B.
      destruct ((cb =? 1)%N) eqn:EC1b; [|discriminate].
      apply N.eqb_eq in EC1b. subst cb.
      injection HLA as <- <-.
      destruct (to_nat_ge2 A EA1) as [a EA].
      exists (1 + a),
        ((0,3%nat) :: expand (map gdecode t2) ++ frun f).
      rewrite (ftz1 A a EA).
      split.
      - unfold sdec.
        cbn [map gdecode expand].
        rewrite EA.
        change (N.to_nat 1%N) with 1%nat.
        change (N.to_nat 2%N) with 2%nat.
        cbn [pair_runs].
        rewrite <- !app_assoc.
        cbn [app].
        exact (FTripC_merge a 1 _).
      - unfold sdec.
        cbn [map gdecode expand].
        rewrite EA.
        change (N.to_nat 1%N) with 1%nat.
        change (N.to_nat 3%N) with 3%nat.
        cbn [pair_runs].
        rewrite <- !app_assoc.
        cbn [app].
        reflexivity. }
    destruct ((cb =? 1)%N && (2 <=? B)%N) eqn:ETK; [|discriminate].
    apply andb_prop in ETK. destruct ETK as (EC1b & EB2b).
    apply N.eqb_eq in EC1b. apply N.leb_le in EB2b. subst cb.
    injection HLA as <- <-.
    destruct (to_nat_ge2 A EA1) as [a EA].
    destruct (to_nat_ge2 B EB2b) as [b EB].
    assert (EBm : N.to_nat (B - 1)%N = S b)
      by (rewrite N2Nat.inj_sub; rewrite EB;
          change (N.to_nat 1%N) with 1%nat; lia).
    exists (1 + a),
      ((0,1%nat)::(1,S b)::(0,2%nat)
         :: expand (map gdecode t2) ++ frun f).
    rewrite (ftz1 A a EA).
    split.
    - unfold sdec.
      cbn [map gdecode expand].
      rewrite EA, EB.
      change (N.to_nat 1%N) with 1%nat.
      change (N.to_nat 2%N) with 2%nat.
      cbn [pair_runs].
      rewrite <- !app_assoc.
      cbn [app].
      exact (FTripC_tick a b _).
    - unfold sdec.
      cbn [map gdecode expand].
      rewrite EA, EBm.
      change (N.to_nat 1%N) with 1%nat.
      change (N.to_nat 2%N) with 2%nat.
      cbn [pair_runs].
      rewrite <- !app_assoc.
      cbn [app].
      reflexivity. }
  destruct ((B =? 8)%N && (zb =? 2)%N && (cb =? 1)%N) eqn:ECAP.
  {
    apply andb_prop in ECAP. destruct ECAP as (ECAP & EC1b).
    apply andb_prop in ECAP. destruct ECAP as (EB8 & EZB).
    apply N.eqb_eq in EB8. apply N.eqb_eq in EZB.
    apply N.eqb_eq in EC1b. subst B zb cb.
    injection HLA as <- <-.
    destruct (to_nat_ge2 A EA1) as [a EA].
    exists (1 + a),
      ((0,1%nat)::(1,7%nat)::(0,2%nat)
         :: expand (map gdecode t2) ++ frun f).
    rewrite (ftz1 A a EA).
    split.
    - unfold sdec.
      cbn [map gdecode expand].
      rewrite EA.
      change (N.to_nat 1%N) with 1%nat.
      change (N.to_nat 2%N) with 2%nat.
      change (N.to_nat 8%N) with 8%nat.
      cbn [pair_runs].
      rewrite <- !app_assoc.
      cbn [app].
      exact (FTripC_tick a 6 _).
    - unfold sdec.
      cbn [map gdecode expand].
      rewrite EA.
      change (N.to_nat 1%N) with 1%nat.
      change (N.to_nat 2%N) with 2%nat.
      change (N.to_nat 7%N) with 7%nat.
      cbn [pair_runs].
      rewrite <- !app_assoc.
      cbn [app].
      reflexivity. }
  destruct ((B =? 4)%N && (zb =? 2)%N) eqn:ERSP.
  {
    apply andb_prop in ERSP. destruct ERSP as (EB4 & EZB).
    apply N.eqb_eq in EB4. apply N.eqb_eq in EZB. subst B zb.
    destruct (to_nat_ge2 A EA1) as [a EA].
    destruct ((cb =? 1)%N) eqn:EC1b.
    { apply N.eqb_eq in EC1b. subst cb.
      injection HLA as <- <-.
      exists (1 + a),
        ((0,1%nat)::(1,3%nat)::(0,2%nat)
           :: expand (map gdecode t2) ++ frun f).
      rewrite (ftz1 A a EA).
      split.
      - unfold sdec.
        cbn [map gdecode expand].
        rewrite EA.
        change (N.to_nat 1%N) with 1%nat.
        change (N.to_nat 2%N) with 2%nat.
        change (N.to_nat 4%N) with 4%nat.
        cbn [pair_runs].
        rewrite <- !app_assoc.
        cbn [app].
        exact (FTripC_tick a 2 _).
      - unfold sdec.
        cbn [map gdecode expand].
        rewrite EA.
        change (N.to_nat 1%N) with 1%nat.
        change (N.to_nat 2%N) with 2%nat.
        change (N.to_nat 3%N) with 3%nat.
        cbn [pair_runs].
        rewrite <- !app_assoc.
        cbn [app].
        reflexivity. }
    destruct ((2 <=? cb)%N) eqn:EC2b; [|discriminate].
    apply N.leb_le in EC2b.
    injection HLA as <- <-.
    destruct (to_nat_ge2 cb EC2b) as [k EKB].
    assert (EKm : N.to_nat (cb - 1)%N = S k)
      by (rewrite N2Nat.inj_sub; rewrite EKB;
          change (N.to_nat 1%N) with 1%nat; lia).
    exists (1 + a),
      ((0,1%nat)::(1,3%nat)::(0,2%nat)::(1,4%nat)::(0,2%nat)
         :: pair_runs 4 2 k
            ++ expand (map gdecode t2) ++ frun f).
    rewrite (ftz1 A a EA).
    split.
    - unfold sdec.
      cbn [map gdecode expand].
      rewrite EA, EKB.
      change (N.to_nat 1%N) with 1%nat.
      change (N.to_nat 2%N) with 2%nat.
      change (N.to_nat 4%N) with 4%nat.
      cbn [pair_runs].
      rewrite <- !app_assoc.
      cbn [app].
      exact (FTripC_tick a 2 _).
    - unfold sdec.
      cbn [map gdecode expand].
      rewrite EA, EKm.
      change (N.to_nat 1%N) with 1%nat.
      change (N.to_nat 2%N) with 2%nat.
      change (N.to_nat 3%N) with 3%nat.
      change (N.to_nat 4%N) with 4%nat.
      cbn [pair_runs].
      rewrite <- !app_assoc.
      cbn [app].
      reflexivity. }
  destruct ((zb =? 1)%N) eqn:EZB1.
  { apply N.eqb_eq in EZB1. subst zb.
    destruct (to_nat_ge2 A EA1) as [a EA].
    destruct ((2 <=? cb)%N) eqn:ECB2.
    {
      apply N.leb_le in ECB2.
      destruct ((2 <=? B)%N) eqn:EB2b; [|discriminate].
      apply N.leb_le in EB2b.
      injection HLA as <- <-.
      destruct (to_nat_ge2 B EB2b) as [b EB].
      assert (EBm : N.to_nat (B - 1)%N = S b)
        by (rewrite N2Nat.inj_sub; rewrite EB;
            change (N.to_nat 1%N) with 1%nat; lia).
      destruct (to_nat_ge2 cb ECB2) as [k EKB].
      assert (EKm : N.to_nat (cb - 1)%N = S k)
        by (rewrite N2Nat.inj_sub; rewrite EKB;
            change (N.to_nat 1%N) with 1%nat; lia).
      exists (1 + a),
        ((0,1%nat)::(1,S b)::(0,1%nat)::(1,S (S b))::(0,1%nat)
           :: pair_runs (S (S b)) 1 k
              ++ expand (map gdecode t2) ++ frun f).
      rewrite (ftz1 A a EA).
      split.
      - unfold sdec.
        cbn [map gdecode expand].
        rewrite EA, EB, EKB.
        change (N.to_nat 1%N) with 1%nat.
        cbn [pair_runs].
        rewrite <- !app_assoc.
        cbn [app].
        exact (FTripC_chainsplit a b _).
      - unfold sdec.
        cbn [map gdecode expand].
        rewrite EA, EB, EBm, EKm.
        change (N.to_nat 1%N) with 1%nat.
        cbn [pair_runs].
        rewrite <- !app_assoc.
        cbn [app].
        reflexivity. }
    destruct ((B =? 1)%N) eqn:EB1.
    {
      apply N.eqb_eq in EB1. subst B.
      destruct ((cb =? 1)%N) eqn:EC1c; [|discriminate].
      apply N.eqb_eq in EC1c. subst cb.
      injection HLA as <- <-.
      exists (1 + a),
        ((0,2%nat) :: expand (map gdecode t2) ++ frun f).
      rewrite (ftz1 A a EA).
      split.
      - unfold sdec.
        cbn [map gdecode expand].
        rewrite EA.
        change (N.to_nat 1%N) with 1%nat.
        cbn [pair_runs].
        rewrite <- !app_assoc.
        cbn [app].
        exact (FTripC_merge a 0 _).
      - unfold sdec.
        cbn [map gdecode expand].
        rewrite EA.
        change (N.to_nat 1%N) with 1%nat.
        change (N.to_nat 2%N) with 2%nat.
        cbn [pair_runs].
        rewrite <- !app_assoc.
        cbn [app].
        reflexivity. }
    destruct ((cb =? 1)%N && (2 <=? B)%N) eqn:EG132; [|discriminate].
    apply andb_prop in EG132. destruct EG132 as (EC1b & EB2b).
    apply N.eqb_eq in EC1b. apply N.leb_le in EB2b. subst cb.
    injection HLA as <- <-.
    destruct (to_nat_ge2 B EB2b) as [b EB].
    assert (EBm : N.to_nat (B - 1)%N = S b)
      by (rewrite N2Nat.inj_sub; rewrite EB;
          change (N.to_nat 1%N) with 1%nat; lia).
    exists (1 + a),
      ((0,1%nat)::(1,S b)::(0,1%nat)
         :: expand (map gdecode t2) ++ frun f).
    rewrite (ftz1 A a EA).
    split.
    - unfold sdec.
      cbn [map gdecode expand].
      rewrite EA, EB.
      change (N.to_nat 1%N) with 1%nat.
      cbn [pair_runs].
      rewrite <- !app_assoc.
      cbn [app].
      exact (FTripC_tick a b _).
    - unfold sdec.
      cbn [map gdecode expand].
      rewrite EA, EBm.
      change (N.to_nat 1%N) with 1%nat.
      cbn [pair_runs].
      rewrite <- !app_assoc.
      cbn [app].
      reflexivity. }
  destruct ((3 <=? zb)%N && (cb =? 1)%N) eqn:EZ3F; [|discriminate].
  apply andb_prop in EZ3F. destruct EZ3F as (EZB3 & EC1b).
  apply N.leb_le in EZB3. apply N.eqb_eq in EC1b. subst cb.
  destruct (to_nat_ge2 A EA1) as [a EA].
  assert (EZB2 : (2 <= zb)%N) by lia.
  destruct (to_nat_ge2 zb EZB2) as [m EZ].
  destruct ((B =? 1)%N) eqn:EB1.
  {
    apply N.eqb_eq in EB1. subst B.
    injection HLA as <- <-.
    assert (EZp : N.to_nat (zb + 1)%N = S (S (S m)))
      by (rewrite N2Nat.inj_add; rewrite EZ;
          change (N.to_nat 1%N) with 1%nat; lia).
    exists (1 + a),
      ((0,S (S (S m))) :: expand (map gdecode t2) ++ frun f).
    rewrite (ftz1 A a EA).
    split.
    - unfold sdec.
      cbn [map gdecode expand].
      rewrite EA, EZ.
      change (N.to_nat 1%N) with 1%nat.
      cbn [pair_runs].
      rewrite <- !app_assoc.
      cbn [app].
      exact (FTripC_merge a (S m) _).
    - unfold sdec.
      cbn [map gdecode expand].
      rewrite EA, EZp.
      change (N.to_nat 1%N) with 1%nat.
      cbn [pair_runs].
      rewrite <- !app_assoc.
      cbn [app].
      reflexivity. }
  destruct ((2 <=? B)%N) eqn:EB2b; [|discriminate].
  apply N.leb_le in EB2b.
  injection HLA as <- <-.
  destruct (to_nat_ge2 B EB2b) as [b EB].
  assert (EBm : N.to_nat (B - 1)%N = S b)
    by (rewrite N2Nat.inj_sub; rewrite EB;
        change (N.to_nat 1%N) with 1%nat; lia).
  exists (1 + a),
    ((0,1%nat)::(1,S b)::(0,S (S m))
       :: expand (map gdecode t2) ++ frun f).
  rewrite (ftz1 A a EA).
  split.
  - unfold sdec.
    cbn [map gdecode expand].
    rewrite EA, EB, EZ.
    change (N.to_nat 1%N) with 1%nat.
    cbn [pair_runs].
    rewrite <- !app_assoc.
    cbn [app].
    exact (FTripC_tick a b _).
  - unfold sdec.
    cbn [map gdecode expand].
    rewrite EA, EBm, EZ.
    change (N.to_nat 1%N) with 1%nat.
    cbn [pair_runs].
    rewrite <- !app_assoc.
    cbn [app].
    reflexivity.
Qed.
Definition LeafPropC (s : word) : Prop :=
  forall (f : N) (s' : word) (f2 : N) (d : cost) (k : nat),
    cleaf_act s f = (Some (s', f2), d) ->
    cin k d ->
    (exists (c p : nat) (q : wside) (K : N),
        N.of_nat k = (K + 6)%N
        /\ FTripC c K (sdec s f) p q
        /\ wconf [] 0 ((1,S p)::q) = wconf [] 0 (sdec s' f2))
    \/ (exists (c p : nat) (q : wside) (K : N),
        N.of_nat k = (K + 3)%N
        /\ SandC c K (sdec s f) ((1,S p)::q)
        /\ (1,S p)::q = sdec s' f2
        /\ sand_leaf s = true
        /\ f = 4%N).
Lemma sdec_opt42_marker (X cw f : N) :
  sdec ((X,2,1)%N :: (3,2,1)%N
        :: (if (0 <? cw)%N then [(4,2,cw)%N] else [])) f
  = sdec ((X,2,1)%N :: (3,2,1)%N :: [(4,2,cw)%N]) f.
Proof.
  destruct (0 <? cw)%N eqn:E; [reflexivity|].
  apply N.ltb_ge in E. replace cw with 0%N by lia. reflexivity.
Qed.
Lemma cmap_inv {A B : Type} (g : A -> B) (dd : cost)
      (x : (A * cost)%type) (y : B) (d : cost) :
  cmap g dd x = (y, d) -> g (fst x) = y /\ d = cadd dd (snd x).
Proof.
  unfold cmap. intros H.
  split; [exact (f_equal fst H) | symmetry; exact (f_equal snd H)].
Qed.
Lemma cpair_of_fst {A B : Type} (x : (A * B)%type) (a : A) :
  fst x = a -> x = (a, snd x).
Proof. intros <-. apply surjective_pairing. Qed.
Lemma leaf_pass_inv (X : N) (R : option (word * N))
      (s' : word) (f2 : N) :
  match R with
  | Some (s2, f') => Some ((X,2,1)%N :: s2, f')
  | None => None
  end = Some (s', f2) ->
  exists s2 f3, R = Some (s2, f3) /\ s' = (X,2,1)%N :: s2 /\ f2 = f3.
Proof.
  destruct R as [[s2 f3]|]; intros H; [|discriminate].
  injection H as <- <-. exists s2, f3. repeat split.
Qed.
Ltac cres HR :=
  let Hw := fresh "Hw" in
  pose proof (f_equal fst HR) as Hw; cbn [fst] in Hw;
  injection Hw as <- <-.
Lemma leaf_thru_ftripc (X : N) (rest s2 : word) (f f3 : N)
      (c pp : nat) (K : N) (q : wside) :
  (3 <= X)%N ->
  FTripC c K (sdec rest f) pp q ->
  wconf [] 0 ((1,S pp)::q) = wconf [] 0 (sdec s2 f3) ->
  exists c2 p2 q2,
    FTripC c2 (K + (2 * X + 6))%N (sdec ((X,2,1)%N :: rest) f) p2 q2
    /\ wconf [] 0 ((1,S p2)::q2)
       = wconf [] 0 (sdec ((X,2,1)%N :: s2) f3).
Proof.
  intros E3 HFT EQ.
  pose (w' := N.to_nat (X - 3)%N).
  assert (EW : N.to_nat X = (3 + w')%nat) by exact (NtoS3g X E3).
  assert (EW2 : N.of_nat w' = (X - 3)%N)
    by (unfold w'; rewrite N2Nat.id; reflexivity).
  assert (EC : (K + (2 * X + 6))%N = (K + cpair (S w'))%N)
    by (unfold cpair; rewrite Nat2N.inj_succ, EW2; lia).
  exists (c + 3)%nat, (2 + w')%nat, ((0,2%nat)::(1,S pp)::q).
  rewrite (sdec_cons X 2 1 rest f), (sdec_cons X 2 1 s2 f3).
  change (N.to_nat 2%N) with 2%nat. change (N.to_nat 1%N) with 1%nat.
  cbn [pair_runs app].
  rewrite EW, EC.
  split.
  - exact (FTripC_col c K (sdec rest f) pp q w' HFT).
  - apply wconf_cons_cong, wconf_cons_cong. exact EQ.
Qed.
Lemma leaf_thru_sandc (X : N) (rest s2 : word) (f f3 : N)
      (c pp : nat) (K : N) (q : wside) :
  (3 <= X)%N ->
  SandC c K (sdec rest f) ((1,S pp)::q) ->
  (1,S pp)::q = sdec s2 f3 ->
  exists c2 p2 q2,
    FTripC c2 (K + (2 * X + 3))%N (sdec ((X,2,1)%N :: rest) f) p2 q2
    /\ wconf [] 0 ((1,S p2)::q2)
       = wconf [] 0 (sdec ((X,2,1)%N :: s2) f3).
Proof.
  intros E3 HS EQ.
  pose (w' := N.to_nat (X - 3)%N).
  assert (EW : N.to_nat X = (3 + w')%nat) by exact (NtoS3g X E3).
  assert (EW2 : N.of_nat w' = (X - 3)%N)
    by (unfold w'; rewrite N2Nat.id; reflexivity).
  assert (EC : (K + (2 * X + 3))%N = (K + 2 * N.of_nat w' + 9)%N)
    by (rewrite EW2; lia).
  exists (c + 2)%nat, (2 + w')%nat, ((0,2%nat)::(1,S pp)::q).
  rewrite (sdec_cons X 2 1 rest f), (sdec_cons X 2 1 s2 f3).
  change (N.to_nat 2%N) with 2%nat. change (N.to_nat 1%N) with 1%nat.
  cbn [pair_runs app].
  rewrite EW, EC.
  split.
  - exact (SandC_col c K (sdec rest f) ((1,S pp)::q) w' HS).
  - rewrite <- EQ. reflexivity.
Qed.
Theorem leaf_ftripC (s : word) : LeafPropC s.
Proof.
  unfold LeafPropC.
  induction s as [|[[X zX] cX] rest IH]; intros f s' f2 d k HR Hk;
    [cbn [cleaf_act] in HR; discriminate|].
  destruct zX as [|pz]; [cbn [cleaf_act] in HR; destruct cX; discriminate|].
  destruct pz as [zq|zq|].
  { cbn [cleaf_act] in HR; destruct cX; discriminate. }
  2:{
      match type of HR with
      | cleaf_act ?a ?b = _ => pose proof (cleaf_act_proj a b) as HP
      end.
      rewrite HR in HP. cbn [fst] in HP. symmetry in HP.
      cbn [cleaf_act] in HR.
      assert (Hd : d = d_tick X) by (inversion HR; reflexivity).
      rewrite Hd in Hk. unfold d_tick in Hk.
      apply cin_cx_eq in Hk.
      destruct (leaf_z1_ftripC X cX rest s' f f2 HP) as (p & q & HT & EQ).
      left. exists 2, p, q, (2 * X + 3)%N.
      split; [rewrite Hk; lia|].
      split; [exact HT|exact EQ]. }
  destruct zq as [q'|q'|];
    try (cbn [cleaf_act] in HR; destruct cX; discriminate).
  destruct cX as [|pc]; [cbn [cleaf_act] in HR; discriminate|].
  destruct pc as [pc'|pc'|];
    [cbn [cleaf_act] in HR; discriminate
    |cbn [cleaf_act] in HR; discriminate|].
  cbn [cleaf_act] in HR.
  destruct ((5 <=? X)%N && negb (X =? 8)%N && negb (X =? 12)%N) eqn:EG;
    [|discriminate].
  assert (E5 : (5 <= X)%N).
  { apply andb_prop in EG. destruct EG as (EG5 & _).
    apply andb_prop in EG5. destruct EG5 as (E5b & _).
    apply N.leb_le; exact E5b. }
  destruct rest as [|[[on zn] cn] t2].
  {
    unfold d_cma_far in HR.
    destruct ((f =? 3)%N) eqn:EF3.
    { apply N.eqb_eq in EF3. subst f.
      assert (Hd : d = cx (2 * X + 29)%N) by (inversion HR; reflexivity).
      rewrite Hd in Hk. apply cin_cx_eq in Hk. cres HR.
      destruct (leaf_far3_tripc X E5) as (c & p & q & HT & EQ).
      left. exists c, p, q, (kl_leaf_far3 X).
      split; [rewrite Hk; unfold kl_leaf_far3; lia|].
      split; [exact HT|exact EQ]. }
    destruct ((f =? 2)%N) eqn:EF2.
    { apply N.eqb_eq in EF2. subst f.
      assert (Hd : d = cx (2 * X + 45)%N) by (inversion HR; reflexivity).
      rewrite Hd in Hk. apply cin_cx_eq in Hk. cres HR.
      destruct (leaf_far2_tripc X E5) as (c & p & q & HT & EQ).
      left. exists c, p, q, (kl_leaf_far2 X).
      split; [rewrite Hk; unfold kl_leaf_far2; lia|].
      split; [exact HT|exact EQ]. }
    destruct ((f =? 4)%N) eqn:EF4; [|discriminate].
    apply N.eqb_eq in EF4. subst f.
    assert (Hd : d = cx (2 * X + 33)%N) by (inversion HR; reflexivity).
    rewrite Hd in Hk. apply cin_cx_eq in Hk. cres HR.
    destruct (leaf_far4_sandc X E5) as (c & p & q & HS & EQ).
    right. exists c, p, q, (kl_leaf_far4 X).
    split; [rewrite Hk; unfold kl_leaf_far4; lia|].
    split; [exact HS|]. split; [exact EQ|].
    split; [cbn [sand_leaf]; exact EG|reflexivity]. }
  destruct ((on =? 1)%N) eqn:EO1; [discriminate|].
  destruct ((on =? 3)%N && (zn =? 2)%N && (cn =? 1)%N && (f =? 4)%N)
    eqn:E203.
  {
    apply andb_prop in E203. destruct E203 as (E203a & EF4).
    apply andb_prop in E203a. destruct E203a as (E203b & EC1).
    apply andb_prop in E203b. destruct E203b as (EO3 & EZ2).
    apply N.eqb_eq in EO3, EZ2, EC1, EF4. subst on zn cn f.
    destruct t2 as [|[[o2 z2] c2] t3].
    { assert (Hd : d = cx (2 * X + 14 * 0 + 43)%N)
        by (inversion HR; reflexivity).
      rewrite Hd in Hk. apply cin_cx_eq in Hk. cres HR.
      destruct (leaf_marker_tripc X 0%N E5) as (c & p & q & HT & EQ).
      change (0 <? 0)%N with false in HT.
      left. exists c, p, q, (kl_leaf_marker X 0).
      split; [rewrite Hk; unfold kl_leaf_marker; lia|].
      split; [exact HT|].
      rewrite EQ. replace (0 + 1)%N with 1%N by lia. reflexivity. }
    destruct t3 as [|g4 t4]; [|discriminate].
    destruct ((o2 =? 4)%N && (z2 =? 2)%N) eqn:EG2; [|discriminate].
    apply andb_prop in EG2. destruct EG2 as (EO2 & EZ2b).
    apply N.eqb_eq in EO2, EZ2b. subst o2 z2.
    assert (Hd : d = cx (2 * X + 14 * c2 + 43)%N)
      by (inversion HR; reflexivity).
    rewrite Hd in Hk. apply cin_cx_eq in Hk. cres HR.
    destruct (leaf_marker_tripc X c2 E5) as (c & p & q & HT & EQ).
    left. exists c, p, q, (kl_leaf_marker X c2).
    split; [rewrite Hk; unfold kl_leaf_marker; lia|].
    split; [|exact EQ].
    rewrite (sdec_opt42_marker X c2 4) in HT. exact HT. }
  destruct ((on =? 4)%N && (zn =? 2)%N) eqn:E218.
  {
    apply andb_prop in E218. destruct E218 as (EO4 & EZ2).
    apply N.eqb_eq in EO4, EZ2. subst on zn.
    destruct t2 as [|[[o2 z2] c2] t3].
    {
      destruct ((f =? 4)%N) eqn:EF4; [|discriminate].
      apply N.eqb_eq in EF4. subst f.
      assert (Hd : d = cx (2 * X + 14 * cn + 33)%N)
        by (inversion HR; reflexivity).
      rewrite Hd in Hk. apply cin_cx_eq in Hk. cres HR.
      destruct (leaf_respawn_final_tripc X cn E5) as (c & p & q & HT & EQ).
      left. exists c, p, q, (kl_leaf_respawn_final X cn).
      split; [rewrite Hk; unfold kl_leaf_respawn_final; lia|].
      split; [exact HT|exact EQ]. }
    destruct t3 as [|[[o3 z3] c3] t4]; [discriminate|].
    destruct t4 as [|g5 t5]; [|discriminate].
    destruct ((1 <=? cn)%N && (o2 =? 3)%N && (z2 =? 2)%N && (c2 =? 1)%N
              && (o3 =? 4)%N && (z3 =? 2)%N && (f =? 4)%N) eqn:EORP;
      [|discriminate].
    apply andb_prop in EORP. destruct EORP as (EORP & EF4).
    apply andb_prop in EORP. destruct EORP as (EORP & EZ3).
    apply andb_prop in EORP. destruct EORP as (EORP & EO3).
    apply andb_prop in EORP. destruct EORP as (EORP & EC2).
    apply andb_prop in EORP. destruct EORP as (EORP & EZ2).
    apply andb_prop in EORP. destruct EORP as (ECN & EO2).
    apply N.leb_le in ECN.
    apply N.eqb_eq in EO2, EZ2, EC2, EO3, EZ3, EF4.
    subst o2 z2 c2 o3 z3 f.
    assert (Hd : d = cx (2 * X + 14 * cn + 14 * c3 + 43)%N)
      by (inversion HR; reflexivity).
    rewrite Hd in Hk. apply cin_cx_eq in Hk. cres HR.
    destruct (leaf_respawn_orphan_tripc X cn c3 E5 ECN)
      as (c & p & q & HT & EQ).
    left. exists c, p, q, (kl_leaf_respawn_orphan X cn c3).
    split; [rewrite Hk; unfold kl_leaf_respawn_orphan; lia|].
    split; [exact HT|exact EQ]. }
  destruct ((X =? 6)%N && (on =? 2)%N && (zn =? 2)%N && (cn =? 1)%N
            && (f =? 4)%N
            && match t2 with
               | [(o2,z2,_)] => ((o2 =? 4) && (z2 =? 2))%N
               | _ => false
               end) eqn:E227.
  {
    apply andb_prop in E227. destruct E227 as (E227a & ET2).
    apply andb_prop in E227a. destruct E227a as (E227b & EF4).
    apply andb_prop in E227b. destruct E227b as (E227c & EC1).
    apply andb_prop in E227c. destruct E227c as (E227d & EZ2).
    apply andb_prop in E227d. destruct E227d as (EX6 & EO2).
    apply N.eqb_eq in EX6, EO2, EZ2, EC1, EF4. subst X on zn cn f.
    destruct t2 as [|[[o2 z2] c2] t3]; [discriminate|].
    destruct t3 as [|g4 t4]; [|discriminate].
    apply andb_prop in ET2. destruct ET2 as (EO2b & EZ2b).
    apply N.eqb_eq in EO2b, EZ2b. subst o2 z2.
    assert (Hd : d = cx (2 * 6 + 28 * c2 + 73)%N)
      by (inversion HR; reflexivity).
    rewrite Hd in Hk. apply cin_cx_eq in Hk. cres HR.
    destruct (leaf_622_tripc c2) as (c & p & q & HT & EQ).
    left. exists c, p, q, (kl_leaf_622 6 c2).
    split; [rewrite Hk; unfold kl_leaf_622; lia|].
    split; [exact HT|exact EQ]. }
  destruct ((zn =? 1)%N
            || ((zn =? 2)%N && (cn =? 1)%N && (5 <=? on)%N
                && negb (on =? 8)%N && negb (on =? 12)%N)) eqn:EPASS;
    [|discriminate].
  destruct (cmap_inv _ _ _ _ _ HR) as (HW & Hd).
  destruct (leaf_pass_inv X _ _ _ HW) as (s2 & f3 & HFR & -> & ->).
  pose proof (cpair_of_fst _ _ HFR) as ESP.
  rewrite Hd in Hk. unfold d_thru in Hk.
  destruct (cin_cadd_cx_split _ _ _ Hk) as (k2 & EK & Hk2).
  assert (E3 : (3 <= X)%N) by lia.
  destruct (IH f s2 f3 _ k2 ESP Hk2)
    as [(c & pp & q & K & EKa & HFT & EQo)
       |(c & pp & q & K & EKa & HS & EQq & _ & _)].
  - destruct (leaf_thru_ftripc X _ _ f f3 c pp K q E3 HFT EQo)
      as (c2 & p2 & q2 & HF2 & EQ2).
    left. exists c2, p2, q2, (K + (2 * X + 6))%N.
    split; [rewrite EK, EKa; lia|].
    split; [exact HF2|exact EQ2].
  - destruct (leaf_thru_sandc X _ _ f f3 c pp K q E3 HS EQq)
      as (c2 & p2 & q2 & HF2 & EQ2).
    left. exists c2, p2, q2, (K + (2 * X + 3))%N.
    split; [rewrite EK, EKa; lia|].
    split; [exact HF2|exact EQ2].
Qed.
Lemma ccolcost_bsum (p : word) : zpre p -> ccolcost p = bsum p.
Proof.
  induction p as [|[[o z] c] t IH]; intros HP; [reflexivity|].
  pose proof (Forall_inv HP) as Hg. cbn in Hg. destruct Hg as [Hz Ho].
  subst z.
  pose proof (Forall_inv_tail HP) as HT.
  cbn [ccolcost bsum bpc gC gO]. rewrite (IH HT).
  replace (2 * (o + 2) + 2)%N with (2 * o + 6)%N by lia. reflexivity.
Qed.
Lemma firstn_length_app (l1 l2 : word) :
  firstn (List.length l1) (l1 ++ l2) = l1.
Proof.
  induction l1 as [|g t IH]; cbn [List.length firstn app]; [reflexivity|].
  rewrite IH. reflexivity.
Qed.
Lemma cdispatch_ftrip_sound (n : nat) (c_0 : N) (p' s s' : word)
      (f f2 : N) (d : cost) (k : nat) :
  zpre p' -> (1 <= c_0)%N ->
  cfire_comp n s f = (Some (s', f2), d) -> cin k d ->
  creach (cx (clo (cdispatch Tftrip (((2,2,c_0)%N :: p') ++ s)
                     (List.length ((2,2,c_0)%N :: p')) (cx (N.of_nat k)))))
    (wconf [] 0 (sdecode (((2,2,c_0)%N :: p') ++ s) f))
    (wconf [] 0 (sdecode ((2,2,1)%N :: ((2,2,c_0)%N :: p') ++ s') f2)).
Proof.
  intros HP HC0 HFC Hk.
  pose proof (fire_comp_returnc leaf_ftripC n c_0 p' s s' f f2 d k
                HP HC0 HFC Hk) as HR.
  rewrite cdispatch_ftrip. cbn [clo cx fst].
  rewrite firstn_length_app.
  refine (creach_widen' _ _ _ _ _ _ HR); unfold cx; cbn [fst snd];
    pose proof (ccolcost_bsum ((2,2,c_0)%N :: p')
                  (zpre_cons_col c_0 p' HP)) as EB; lia.
Qed.
Local Open Scope N_scope.
Local Open Scope N_scope.
Local Open Scope bool_scope.
