Definition cempty (d : cost) : Prop := (chi d < clo d)%N.
Lemma cempty_cundef : cempty cundef.
Proof. unfold cempty, cundef, clo, chi; cbn [fst snd]. lia. Qed.
Lemma cempty_dec (d : cost) : cempty d \/ ~ cempty d.
Proof. unfold cempty. lia. Qed.
Lemma cin_of_not_cempty (d : cost) : ~ cempty d -> cin (N.to_nat (clo d)) d.
Proof. unfold cempty, cin, clo, chi. lia. Qed.
Lemma cx_not_cempty (K : N) : ~ cempty (cx K).
Proof. unfold cempty, cx, clo, chi; cbn [fst snd]. lia. Qed.
Lemma cempty_cadd_cx_l (K : N) (d : cost) : cempty d -> cempty (cadd (cx K) d).
Proof. unfold cempty, cadd, cx, clo, chi; cbn [fst snd]. lia. Qed.
Lemma cempty_cdispatch (t : ctier) (w : word) (i : nat) (d : cost) :
  cempty d -> cempty (cdispatch t w i d).
Proof.
  intros H. destruct t;
    unfold cempty, cdispatch, cprefix, ctier_close, cadd, cx, czero,
           clo, chi in H |- *;
    cbn [fst snd] in H |- *; lia.
Qed.
Lemma not_cempty_cdispatch (t : ctier) (w : word) (i : nat) (d : cost) :
  ~ cempty d -> ~ cempty (cdispatch t w i d).
Proof.
  intros H. destruct t;
    unfold cempty, cdispatch, cprefix, ctier_close, cadd, cx, czero,
           clo, chi in H |- *;
    cbn [fst snd] in H |- *; lia.
Qed.
Lemma clo_cx (K : N) : clo (cx K) = K.
Proof. reflexivity. Qed.
Lemma clo_cdispatch_loc (w : word) (i : nat) (d : cost) :
  (clo (cdispatch Tloc w i d) = ccolcost (firstn i w) + clo d)%N.
Proof.
  unfold cdispatch, cprefix, ctier_close, cadd, cx, czero, clo, chi;
    cbn [fst snd]. lia.
Qed.
Lemma clo_cdispatch_ftrip (w : word) (i : nat) (d : cost) :
  (clo (cdispatch Tftrip w i d) = ccolcost (firstn i w) + (clo d + 6))%N.
Proof.
  unfold cdispatch, cprefix, ctier_close, cadd, cx, clo, chi;
    cbn [fst snd]. lia.
Qed.
Lemma creach_of_clo (d : cost) (u v : Q * tape) :
  ~ cempty d -> creach (cx (clo d)) u v -> creach d u v.
Proof.
  intros HE H. refine (creach_widen' _ _ _ _ _ _ H);
    unfold cempty, cx, clo, chi in *; cbn [fst snd]; lia.
Qed.
Lemma sdecode_master_grow (c_0 : N) (t : word) (f : N) :
  sdecode ((2,2,(c_0+1))%N :: t) f = sdecode ((2,2,1)%N :: (2,2,c_0)%N :: t) f.
Proof.
  rewrite !sdecode_cons.
  replace (c_0+1)%N with (1+c_0)%N by lia.
  rewrite gdec1_merge, <- app_assoc. reflexivity.
Qed.
Lemma DispatchC_sand_leaf_shape (s : word) :
  sand_leaf s = true ->
  exists X, s = [(X,2,1)%N]
            /\ (5 <= X)%N /\ X <> 8%N /\ X <> 12%N.
Proof.
  intros H. unfold sand_leaf in H.
  destruct s as [|[[X z] c] tl]; [discriminate H|].
  destruct tl as [|g tl']; killmN H.
  apply andb_prop in H. destruct H as (H1 & H12).
  apply andb_prop in H1. destruct H1 as (H5 & H8).
  exists X. split; [reflexivity|].
  split; [apply N.leb_le; exact H5|].
  split; apply N.eqb_neq; apply negb_true_iff; assumption.
Qed.
Lemma route_leaf (c_0 : N) (p' site s' : word) (f f2 : N) (d : cost) :
  (1 <= c_0)%N -> forallb is_col p' = true ->
  cleaf_act site f = (Some (s', f2), d) -> ~ cempty d ->
  creach (cx (ccolcost ((2,2,c_0)%N :: p') + clo d)%N)
    (wconf [] 0 (sdecode (((2,2,c_0)%N :: p') ++ site) f))
    (wconf [] 0 (sdecode ((2,2,1)%N :: ((2,2,c_0)%N :: p') ++ s') f2)).
Proof.
  intros HC0 HP HLA HE.
  pose proof (cin_of_not_cempty d HE) as Hk.
  assert (EB : (ccolcost ((2,2,c_0)%N :: p') = bsum ((2,2,c_0)%N :: p'))%N)
    by (apply ccolcost_bsum, zpre_cons_col, zpre_of_forallb, HP).
  assert (EK : (clo d = N.of_nat (N.to_nat (clo d)))%N)
    by (rewrite N2Nat.id; reflexivity).
  rewrite EB, EK.
  destruct (leaf_ftripC site f s' f2 d _ HLA Hk)
    as [(c & pp & q & K & EKK & HT & EQ)
       |(c & pp & q & K & EKK & HS & EQq & HSL & HF4)].
  { rewrite EKK.
    exact (leaf_trip_returnc c_0 p' site s' f f2 c pp K q
             (zpre_of_forallb _ HP) HC0 HT EQ). }
  clear EKK HS EQq K c pp q.
  destruct (DispatchC_sand_leaf_shape site HSL) as (X & ESITE & EX5 & E8 & E12).
  subst site f.
  assert (EG : ((5 <=? X) && negb (X =? 8) && negb (X =? 12))%N = true).
  { apply andb_true_intro; split;
      [apply andb_true_intro; split;
        [apply N.leb_le; exact EX5
        |apply negb_true_iff, N.eqb_neq; exact E8]
      |apply negb_true_iff, N.eqb_neq; exact E12]. }
  cbn [cleaf_act] in HLA. rewrite EG in HLA.
  cbn [andb N.eqb Pos.eqb] in HLA.
  unfold d_cma_far in HLA. cbn [N.eqb Pos.eqb] in HLA.
  pose proof (f_equal snd HLA) as ED. cbn [snd] in ED.
  pose proof (f_equal fst HLA) as EW. cbn [fst] in EW.
  injection EW as <- <-.
  rewrite <- ED. unfold cx, clo; cbn [fst].
  replace (2 * X + 33)%N with (dfar169 X) by (unfold dfar169; lia).
  rewrite N2Nat.id.
  exact (bridge_far169_pgc X c_0 p' EX5 (zpre_of_forallb _ HP) HC0).
Qed.
Lemma route_fire (n : nat) (c_0 : N) (p' s s' : word) (f f2 : N)
      (d : cost) :
  (1 <= c_0)%N -> forallb is_col p' = true ->
  cfire_comp n s f = (Some (s', f2), d) -> ~ cempty d ->
  creach (cx (ccolcost ((2,2,c_0)%N :: p') + (clo d + 6))%N)
    (wconf [] 0 (sdecode (((2,2,c_0)%N :: p') ++ s) f))
    (wconf [] 0 (sdecode ((2,2,1)%N :: ((2,2,c_0)%N :: p') ++ s') f2)).
Proof.
  intros HC0 HP HFC HE.
  pose proof (cin_of_not_cempty d HE) as Hk.
  pose proof (cdispatch_ftrip_sound n c_0 p' s s' f f2 d _
                (zpre_of_forallb _ HP) HC0 HFC Hk) as HR.
  rewrite clo_cdispatch_ftrip, firstn_length_app, clo_cx, N2Nat.id in HR.
  exact HR.
Qed.
Lemma close_leaf (c_0 : N) (t : word) (i1 : nat)
      (site sfx' : word) (f f2 : N) :
  (1 <= c_0)%N ->
  forallb is_col (firstn i1 t) = true ->
  skipn i1 t = site ->
  leaf_act site f = Some (sfx', f2) ->
  cempty (cdispatch Tloc ((2,2,c_0)%N :: t) (S i1) (snd (cleaf_act site f)))
  \/ sound_impl_c (cdispatch Tloc ((2,2,c_0)%N :: t) (S i1)
                     (snd (cleaf_act site f)))
       ((2,2,c_0)%N :: t) f
       (normalize (((2,2,(c_0+1))%N :: firstn i1 t) ++ sfx')) f2.
Proof.
  intros HC0 HP ESFX ELA.
  set (dl := snd (cleaf_act site f)) in *.
  destruct (cempty_dec dl) as [HE|HE];
    [left; apply cempty_cdispatch; exact HE|]. right.
  assert (EAPP : ((2,2,c_0)%N :: firstn i1 t) ++ site = (2,2,c_0)%N :: t)
    by (cbn [app]; f_equal; rewrite <- ESFX; apply firstn_skipn).
  assert (ESP : cleaf_act site f = (Some (sfx', f2), dl)).
  { unfold dl. rewrite (surjective_pairing (cleaf_act _ _)) at 1.
    rewrite cleaf_act_proj, ELA. reflexivity. }
  pose proof (route_leaf c_0 (firstn i1 t) site sfx' f f2 dl
                HC0 HP ESP HE) as HR.
  rewrite EAPP in HR.
  apply sound_impl_c_normalize. unfold sound_impl_c.
  apply (creach_of_clo _ _ _ (not_cempty_cdispatch _ _ _ _ HE)).
  rewrite clo_cdispatch_loc. cbn [firstn].
  change ((((2,2,(c_0+1))%N :: firstn i1 t) ++ sfx'))
    with ((2,2,(c_0+1))%N :: (firstn i1 t ++ sfx')).
  rewrite sdecode_master_grow.
  change ((2,2,1)%N :: (2,2,c_0)%N :: (firstn i1 t ++ sfx'))
    with ((2,2,1)%N :: ((2,2,c_0)%N :: firstn i1 t) ++ sfx').
  exact HR.
Qed.
Lemma close_fire (n : nat) (c_0 : N) (t : word) (i1 : nat)
      (site sfx' : word) (f f2 : N) :
  (1 <= c_0)%N ->
  forallb is_col (firstn i1 t) = true ->
  skipn i1 t = site ->
  fire_comp n site f = Some (sfx', f2) ->
  cempty (cdispatch Tftrip ((2,2,c_0)%N :: t) (S i1)
            (snd (cfire_comp n site f)))
  \/ sound_impl_c (cdispatch Tftrip ((2,2,c_0)%N :: t) (S i1)
                     (snd (cfire_comp n site f)))
       ((2,2,c_0)%N :: t) f
       (normalize (((2,2,(c_0+1))%N :: firstn i1 t) ++ sfx')) f2.
Proof.
  intros HC0 HP ESFX EFC.
  set (dl := snd (cfire_comp n site f)) in *.
  destruct (cempty_dec dl) as [HE|HE];
    [left; apply cempty_cdispatch; exact HE|]. right.
  assert (EAPP : ((2,2,c_0)%N :: firstn i1 t) ++ site = (2,2,c_0)%N :: t)
    by (cbn [app]; f_equal; rewrite <- ESFX; apply firstn_skipn).
  assert (ESP : cfire_comp n site f = (Some (sfx', f2), dl)).
  { unfold dl. rewrite (surjective_pairing (cfire_comp _ _ _)) at 1.
    rewrite cfire_comp_proj, EFC. reflexivity. }
  pose proof (route_fire n c_0 (firstn i1 t) site sfx' f f2 dl
                HC0 HP ESP HE) as HR.
  rewrite EAPP in HR.
  apply sound_impl_c_normalize. unfold sound_impl_c.
  apply (creach_of_clo _ _ _ (not_cempty_cdispatch _ _ _ _ HE)).
  rewrite clo_cdispatch_ftrip. cbn [firstn].
  change ((((2,2,(c_0+1))%N :: firstn i1 t) ++ sfx'))
    with ((2,2,(c_0+1))%N :: (firstn i1 t ++ sfx')).
  rewrite sdecode_master_grow.
  change ((2,2,1)%N :: (2,2,c_0)%N :: (firstn i1 t ++ sfx'))
    with ((2,2,1)%N :: ((2,2,c_0)%N :: firstn i1 t) ++ sfx').
  exact HR.
Qed.
Lemma creach_cx_eq (a b : N) (u v : Q * tape) :
  a = b -> creach (cx a) u v -> creach (cx b) u v.
Proof. intros <- H. exact H. Qed.
Lemma close_endR (c_0 : N) (t : word) (i1 : nat)
      (body : word) (f : N) :
  (1 <= c_0)%N ->
  skipn i1 t = [(4,3,1)%N] ->
  endR_seg ((2,2,(c_0+1))%N :: firstn i1 t) f = Some body ->
  cempty (cdispatch Tftrip ((2,2,c_0)%N :: t) 1%nat
            (dseg_endR (firstn i1 t) f))
  \/ sound_impl_c (cdispatch Tftrip ((2,2,c_0)%N :: t) 1%nat
                     (dseg_endR (firstn i1 t) f))
       ((2,2,c_0)%N :: t) f (normalize body) 3%N.
Proof.
  intros HC0 ESFX EES.
  set (dl := dseg_endR (firstn i1 t) f) in *.
  destruct (cempty_dec dl) as [HE|HE];
    [left; apply cempty_cdispatch; exact HE|]. right.
  pose proof (cin_of_not_cempty dl HE) as Hk.
  destruct (cseg_endR_some (firstn i1 t) f _ Hk) as (body' & EE').
  pose proof (endR_seg_cons (2,2,(c_0+1))%N (firstn i1 t) body' f EE') as EC.
  pose proof (eq_trans (eq_sym EC) EES) as EQB. injection EQB as <-.
  destruct (dseg_endR_tripc (firstn i1 t) body' f _ EE' Hk)
    as (c & pp & q & HT0 & EQ).
  assert (HT : FTripC c (clo dl)
                 (sdec (firstn i1 t ++ [(4,3,1)%N]) f) pp q)
    by (refine (DebrisLeafC_FTripC_cost_eq _ _ _ _ _ _ _ HT0); apply N2Nat.id).
  assert (ET : t = firstn i1 t ++ [(4,3,1)%N]).
  { pose proof (firstn_skipn i1 t) as HFS. rewrite ESFX in HFS.
    symmetry. exact HFS. }
  apply sound_impl_c_normalize. unfold sound_impl_c.
  apply (creach_of_clo _ _ _ (not_cempty_cdispatch _ _ _ _ HE)).
  rewrite clo_cdispatch_ftrip. cbn [firstn].
  change ((2,2,(c_0+1))%N :: body')
    with ((2,2,(c_0+1))%N :: ([] ++ body')).
  rewrite sdecode_master_grow.
  rewrite ET.
  change ((2,2,c_0)%N :: (firstn i1 t ++ [(4,3,1)%N]))
    with (((2,2,c_0)%N :: []) ++ (firstn i1 t ++ [(4,3,1)%N])).
  change ((2,2,1)%N :: (2,2,c_0)%N :: ([] ++ body'))
    with ((2,2,1)%N :: ((2,2,c_0)%N :: []) ++ body').
  refine (creach_cx_eq _ _ _ _ _
            (leaf_trip_returnc c_0 [] (firstn i1 t ++ [(4,3,1)%N]) body'
               f 3%N c pp (clo dl) q (Forall_nil _) HC0 HT EQ)).
  f_equal; reflexivity.
Qed.
Lemma endY_seg_cons (g : bg) (cols body : word) (y : N) :
  endY_seg cols y = Some body ->
  endY_seg (g :: cols) y = Some (g :: body).
Proof.
  unfold endY_seg.
  destruct (last2 cols) as [[[ini a] b]|] eqn:EL2; [|discriminate].
  pose proof (last2_split _ _ _ _ EL2) as EC.
  assert (E2 : last2 (g :: cols) = Some (g :: ini, a, b))
    by (rewrite EC; apply (last2_app2 (g :: ini) a b)).
  rewrite E2.
  destruct a as [[gao gaz] gac], b as [[gbo gbz] gbc].
  destruct ((gao =? 8)%N && (gaz =? 2)%N && (gac =? 1)%N
            && (gbo =? 4)%N && (gbz =? 2)%N && (1 <=? gbc)%N).
  { intros H. injection H as <-. cbn [app]. reflexivity. }
  destruct ((gbo =? 8)%N && (gbz =? 2)%N && (gbc =? 1)%N);
    [|discriminate].
  intros H. injection H as <-. cbn [app]. reflexivity.
Qed.
Lemma cseg_endY_some (cols : word) (y : N) (k : nat) :
  cin k (dseg_endY cols y) -> exists body, endY_seg cols y = Some body.
Proof.
  unfold dseg_endY, dseg.
  destruct (cseg cols) as [[pc gbc]|] eqn:ECS;
    [|intros H; exact (cundef_absurd _ _ H)].
  intros _.
  destruct (cseg_split cols pc gbc ECS)
    as (ini & ga & gb & EL2 &
        [(EGA & EGB & EGB1 & _ & _)|(EGB & _ & _ & _)]).
  - subst ga gb. unfold endY_seg. rewrite EL2.
    assert (EGBb : (1 <=? gbc)%N = true) by (apply N.leb_le; exact EGB1).
    rewrite EGBb. cbn [N.eqb Pos.eqb andb]. eexists. reflexivity.
  - subst gb. destruct ga as [[gao gaz] gac].
    unfold endY_seg. rewrite EL2.
    destruct ((gao =? 8)%N && (gaz =? 2)%N && (gac =? 1)%N) eqn:EA3;
      try rewrite EA3; cbn [N.eqb Pos.eqb andb]; eexists; reflexivity.
Qed.
Lemma close_endY (c_0 : N) (t : word) (i1 : nat)
      (body : word) (y : N) :
  (1 <= c_0)%N ->
  skipn i1 t = [(4,3,1)%N; (y,3,1)%N] ->
  (1 <= y)%N ->
  endY_seg ((2,2,(c_0+1))%N :: firstn i1 t) y = Some body ->
  cempty (cdispatch Tftrip ((2,2,c_0)%N :: t) 1%nat
            (dseg_endY (firstn i1 t) y))
  \/ sound_impl_c (cdispatch Tftrip ((2,2,c_0)%N :: t) 1%nat
                     (dseg_endY (firstn i1 t) y))
       ((2,2,c_0)%N :: t) 4%N (normalize body) 3%N.
Proof.
  intros HC0 ESFX EY1 EES.
  set (dl := dseg_endY (firstn i1 t) y) in *.
  destruct (cempty_dec dl) as [HE|HE];
    [left; apply cempty_cdispatch; exact HE|]. right.
  pose proof (cin_of_not_cempty dl HE) as Hk.
  destruct (cseg_endY_some (firstn i1 t) y _ Hk) as (body' & EE').
  pose proof (endY_seg_cons (2,2,(c_0+1))%N
                (firstn i1 t) body' y EE') as EC.
  pose proof (eq_trans (eq_sym EC) EES) as EQB. injection EQB as <-.
  destruct (dseg_endY_tripc (firstn i1 t) body' y _ EY1 EE' Hk)
    as (c & pp & q & HT0 & EQ).
  assert (HT : FTripC c (clo dl)
                 (sdec (firstn i1 t ++ [(4,3,1)%N; (y,3,1)%N]) 4) pp q)
    by (refine (DebrisLeafC_FTripC_cost_eq _ _ _ _ _ _ _ HT0); apply N2Nat.id).
  assert (ET : t = firstn i1 t ++ [(4,3,1)%N; (y,3,1)%N]).
  { pose proof (firstn_skipn i1 t) as HFS. rewrite ESFX in HFS.
    symmetry. exact HFS. }
  apply sound_impl_c_normalize. unfold sound_impl_c.
  apply (creach_of_clo _ _ _ (not_cempty_cdispatch _ _ _ _ HE)).
  rewrite clo_cdispatch_ftrip. cbn [firstn].
  change ((2,2,(c_0+1))%N :: body')
    with ((2,2,(c_0+1))%N :: ([] ++ body')).
  rewrite sdecode_master_grow.
  rewrite ET.
  change ((2,2,c_0)%N :: (firstn i1 t ++ [(4,3,1)%N; (y,3,1)%N]))
    with (((2,2,c_0)%N :: [])
          ++ (firstn i1 t ++ [(4,3,1)%N; (y,3,1)%N])).
  change ((2,2,1)%N :: (2,2,c_0)%N :: ([] ++ body'))
    with ((2,2,1)%N :: ((2,2,c_0)%N :: []) ++ body').
  refine (creach_cx_eq _ _ _ _ _
            (leaf_trip_returnc c_0 []
               (firstn i1 t ++ [(4,3,1)%N; (y,3,1)%N]) body'
               4%N 3%N c pp (clo dl) q (Forall_nil _) HC0 HT EQ)).
  f_equal; reflexivity.
Qed.
Lemma d_jcomp_tripc (pre post body : word) (B f f2 : N) (k : nat) :
  (1 <= B)%N ->
  jump_comp pre B post f = Some (JMP, body, f2) ->
  cin k (d_jcomp pre B post f) ->
  exists c p q,
    FTripC c (N.of_nat k)
      (sdec (pre ++ (4,3,1)%N :: (4,2,B)%N :: post) f) p q
    /\ wconf [] 0 ((1,S p)::q) = wconf [] 0 (sdec body f2).
Proof.
  intros EB1 EJC Hk.
  unfold d_jcomp in Hk.
  destruct (forallb is_col pre) eqn:HCP; cbn [negb] in Hk;
    [|exact (cundef_absurd _ _ Hk)].
  unfold jump_comp in EJC.
  destruct post as [|g0 post'].
  {
    assert (HR : (if (f =? 4)%N then
                    match lawR_seg pre B with
                    | Some b => Some (b, f)
                    | None => None
                    end
                  else if (5 <=? f)%N then
                    match jump_seg pre B with
                    | Some seg => Some (seg ++ [((f-1)%N,1,1)%N], 3%N)
                    | None => None
                    end
                  else None) = Some (body, f2)).
    { destruct (f =? 4)%N.
      - destruct (lawR_seg pre B) as [b|]; [|discriminate EJC].
        pose proof (f_equal (fun o => match o with
                                      | Some (_, w, _) => w
                                      | None => body end) EJC) as EW.
        pose proof (f_equal (fun o => match o with
                                      | Some (_, _, x) => x
                                      | None => f2 end) EJC) as EF.
        cbn in EW, EF. rewrite EW, EF. reflexivity.
      - destruct (5 <=? f)%N; [|discriminate EJC].
        destruct (jump_seg pre B) as [sg|]; [|discriminate EJC].
        pose proof (f_equal (fun o => match o with
                                      | Some (_, w, _) => w
                                      | None => body end) EJC) as EW.
        pose proof (f_equal (fun o => match o with
                                      | Some (_, _, x) => x
                                      | None => f2 end) EJC) as EF.
        cbn in EW, EF. rewrite EW, EF. reflexivity. }
    cbn [app].
    exact (dseg_lawR_tripc pre body B f f2 k EB1 HR Hk). }
  destruct (jump_seg pre B) as [segp|] eqn:EJS;
    [|exact (cundef_absurd _ _ Hk)].
  destruct (seek (g0 :: post')) as [cols2 s3] eqn:ESK.
  destruct (seek_split (g0 :: post') cols2 s3 ESK) as (EREST & HC2).
  rewrite EREST.
  destruct (fst (crenew_seg (List.length s3) cols2 s3 f))
    as [[bd f3]|] eqn:ERS.
  {
    pose proof (surjective_pairing (crenew_seg (List.length s3) cols2 s3 f))
      as ESP. rewrite ERS in ESP.
    assert (EW : body = segp ++ bd /\ f2 = f3).
    { rewrite <- crenew_seg_proj, ERS in EJC.
      pose proof (f_equal (fun o => match o with
                                    | Some (_, w, _) => w
                                    | None => body end) EJC) as EW1.
      pose proof (f_equal (fun o => match o with
                                    | Some (_, _, x) => x
                                    | None => f2 end) EJC) as EF1.
      cbn in EW1, EF1. split; [symmetry; exact EW1|symmetry; exact EF1]. }
    destruct EW as (-> & ->).
    unfold d_jsplice in Hk.
    destruct (cin_cadd_cx_split _ _ _ Hk) as (k2 & EK & Hk2).
    destruct (renew_ftripc leaf_ftripC (List.length s3) cols2 s3 f bd f3
                _ k2 HC2 ESP Hk2) as (ci & pi & qi & HFi & EQi).
    destruct (casc_jump_innerc_col pre (cols2 ++ s3) bd segp B f f3
                ci pi (N.of_nat k2) qi HCP EJS EB1 HFi EQi)
      as (c2 & p2 & q2 & HF2 & EQ2).
    exists c2, p2, q2. split; [|exact EQ2].
    refine (DebrisLeafC_FTripC_cost_eq _ _ _ _ _ _ _ HF2).
    pose proof (ccolcost_wcolcost pre) as EW1. lia. }
  rewrite <- crenew_seg_proj, ERS in EJC.
  destruct s3 as [|[[o7 z7] c7] s3t].
  {
    assert (ELN : leaf_act ([] : word) f = None) by reflexivity.
    rewrite ELN in EJC.
    destruct (5 <=? f)%N eqn:EF5b.
    2:{
        destruct (f =? 4)%N eqn:EF4b; [|exact (cundef_absurd _ _ Hk)].
        pose proof EF4b as EF4. apply N.eqb_eq in EF4. subst f.
        destruct (dtb4_convc cols2) as [[cols2' Kd]|] eqn:EDC.
        { assert (EDV : dtb4_conv cols2 = Some cols2')
            by (rewrite <- dtb4_convc_proj, EDC; reflexivity).
          rewrite EDV in EJC.
          apply cin_cx_eq in Hk.
          assert (EW : body = segp ++ cols2' /\ f2 = 4%N).
          { pose proof (f_equal (fun o => match o with
                                          | Some (_, w, _) => w
                                          | None => body end) EJC) as EW1.
            pose proof (f_equal (fun o => match o with
                                          | Some (_, _, x) => x
                                          | None => f2 end) EJC) as EF1.
            cbn in EW1, EF1.
            split; [symmetry; exact EW1|symmetry; exact EF1]. }
          destruct EW as (-> & ->).
          rewrite app_nil_r.
          destruct (dtb4_convc_tripc cols2 cols2' Kd HC2 EDC)
            as (ci & pi & qi & HFi & EQi).
          destruct (casc_jump_innerc_col pre cols2 cols2' segp B 4%N 4%N
                      ci pi Kd qi HCP EJS EB1 HFi EQi)
            as (c2 & p2 & q2 & HF2 & EQ2).
          exists c2, p2, q2. split; [|exact EQ2].
          refine (DebrisLeafC_FTripC_cost_eq _ _ _ _ _ _ _ HF2).
          rewrite Hk.
          pose proof (ccolcost_wcolcost pre) as EW1. lia. }
        pose proof (dtb4_convc_proj cols2) as EDP.
        rewrite EDC in EDP. cbn [option_map fst] in EDP.
        rewrite <- EDP in EJC.
        destruct (forallb w42 cols2) eqn:EW42;
          [|exact (cundef_absurd _ _ Hk)].
        destruct (lawR_seg pre B) as [seg2|] eqn:ELS;
          [|discriminate EJC].
        apply cin_cx_eq in Hk.
        assert (EW : body = seg2 ++ cols2 /\ f2 = 4%N).
        { pose proof (f_equal (fun o => match o with
                                        | Some (_, w, _) => w
                                        | None => body end) EJC) as EW1.
          pose proof (f_equal (fun o => match o with
                                        | Some (_, _, x) => x
                                        | None => f2 end) EJC) as EF1.
          cbn in EW1, EF1.
          split; [symmetry; exact EW1|symmetry; exact EF1]. }
        destruct EW as (-> & ->).
        rewrite app_nil_r.
        destruct (casc_lawR_innerc_col pre cols2 seg2 B HCP ELS EB1 EW42)
          as (c2 & p2 & q2 & HF2 & EQ2).
        exists c2, p2, q2. split; [|exact EQ2].
        refine (DebrisLeafC_FTripC_cost_eq _ _ _ _ _ _ _ HF2).
        symmetry. exact Hk. }
    pose proof EF5b as EF5. apply N.leb_le in EF5.
    apply cin_cx_eq in Hk.
    assert (EW : body = segp ++ cols2 ++ [((f-1)%N,1,1)%N] /\ f2 = 3%N).
    { pose proof (f_equal (fun o => match o with
                                    | Some (_, w, _) => w
                                    | None => body end) EJC) as EW1.
      pose proof (f_equal (fun o => match o with
                                    | Some (_, _, x) => x
                                    | None => f2 end) EJC) as EF1.
      cbn in EW1, EF1. split; [symmetry; exact EW1|symmetry; exact EF1]. }
    destruct EW as (-> & ->).
    rewrite app_nil_r.
    destruct (DebrisLeafC_ren_far_tailc cols2 f HC2 EF5) as (ci & pi & qi & HFi & EQi).
    destruct (casc_jump_innerc_col pre cols2 (cols2 ++ [((f-1)%N,1,1)%N]) segp
                B f 3%N ci pi _ qi HCP EJS EB1 HFi EQi)
      as (c2 & p2 & q2 & HF2 & EQ2).
    exists c2, p2, q2. split; [|exact EQ2].
    refine (DebrisLeafC_FTripC_cost_eq _ _ _ _ _ _ _ HF2).
    rewrite Hk. unfold kl_dtb_far.
    pose proof (ccolcost_wcolcost pre) as EW1.
    pose proof (ccolcost_wcolcost cols2) as EW2. lia. }
  destruct ((z7 =? 3)%N && (c7 =? 1)%N) eqn:EZ7.
  {
    match type of Hk with
    | context [ fst (cfire_comp ?a ?b ?c) ] =>
        destruct (fst (cfire_comp a b c)) as [[s3' f3]|] eqn:EFC
    end;
      try rewrite EFC in Hk; cbv beta iota in Hk;
      [|exact (cundef_absurd _ _ Hk)].
    match type of EFC with
    | fst ?X = _ => pose proof (surjective_pairing X) as ESP
    end.
    rewrite EFC in ESP.
    assert (EW : body = segp ++ cols2 ++ s3' /\ f2 = f3).
    { rewrite <- cfire_comp_proj, EFC in EJC.
      pose proof (f_equal (fun o => match o with
                                    | Some (_, w, _) => w
                                    | None => body end) EJC) as EW1.
      pose proof (f_equal (fun o => match o with
                                    | Some (_, _, x) => x
                                    | None => f2 end) EJC) as EF1.
      cbn in EW1, EF1. split; [symmetry; exact EW1|symmetry; exact EF1]. }
    destruct EW as (-> & ->).
    unfold d_jsplice, d_cols in Hk.
    destruct (cin_cadd_cx_split _ _ _ Hk) as (k2 & EK2 & Hk2).
    destruct (cin_cadd_cx_split _ _ _ Hk2) as (k3 & EK & Hk3).
    destruct (fire_comp_ftripc leaf_ftripC _ _ f s3' f3 _ k3 ESP Hk3)
      as (ci & pi & qi & HFi & EQi).
    destruct (DebrisLeafC_ren_liftc cols2 _ s3' f f3 ci pi (N.of_nat k3) qi
                HC2 HFi EQi) as (cL & pL & qL & HFL & EQL).
    destruct (casc_jump_innerc_col pre _ (cols2 ++ s3') segp B f f3
                cL pL _ qL HCP EJS EB1 HFL EQL)
      as (c2 & p2 & q2 & HF2 & EQ2).
    exists c2, p2, q2. split; [|exact EQ2].
    refine (DebrisLeafC_FTripC_cost_eq _ _ _ _ _ _ _ HF2).
    pose proof (ccolcost_wcolcost pre) as EW1.
    pose proof (ccolcost_wcolcost cols2) as EW2. lia. }
  match type of Hk with
  | context [ sand_leaf ?a ] => destruct (sand_leaf a) eqn:ESL
  end; cbv beta iota in Hk; [exact (cundef_absurd _ _ Hk)|].
  match type of Hk with
  | context [ fst (cleaf_act ?a ?b) ] =>
      destruct (fst (cleaf_act a b)) as [[s3' f3]|] eqn:ELA
  end;
    try rewrite ELA in Hk; cbv beta iota in Hk;
    [|exact (cundef_absurd _ _ Hk)].
  match type of ELA with
  | fst ?X = _ => pose proof (surjective_pairing X) as ESP
  end.
  rewrite ELA in ESP.
  assert (EW : body = segp ++ cols2 ++ s3' /\ f2 = f3).
  { rewrite <- cleaf_act_proj, ELA in EJC.
    pose proof (f_equal (fun o => match o with
                                  | Some (_, w, _) => w
                                  | None => body end) EJC) as EW1.
    pose proof (f_equal (fun o => match o with
                                  | Some (_, _, x) => x
                                  | None => f2 end) EJC) as EF1.
    cbn in EW1, EF1. split; [symmetry; exact EW1|symmetry; exact EF1]. }
  destruct EW as (-> & ->).
  destruct (cin_cadd_cx_split _ _ _ Hk) as (k3 & EK & Hk3).
  destruct (leaf_ftripC _ f s3' f3 _ k3 ESP Hk3)
    as [(ci & pi & qi & Ki & EKi & HFi & EQi)
       |(ci & pi & qi & Ki & EKi & HSi & EQq & HSL & _)];
    [|rewrite HSL in ESL; discriminate ESL].
  destruct (DebrisLeafC_ren_liftc cols2 _ s3' f f3 ci pi Ki qi HC2 HFi EQi)
    as (cL & pL & qL & HFL & EQL).
  destruct (casc_jump_innerc_col pre _ (cols2 ++ s3') segp B f f3
              cL pL _ qL HCP EJS EB1 HFL EQL)
    as (c2 & p2 & q2 & HF2 & EQ2).
  exists c2, p2, q2. split; [|exact EQ2].
  refine (DebrisLeafC_FTripC_cost_eq _ _ _ _ _ _ _ HF2).
  pose proof (ccolcost_wcolcost pre) as EW1.
  pose proof (ccolcost_wcolcost cols2) as EW2. lia.
Qed.
Lemma close_jcomp (c_0 : N) (t : word) (i1 : nat)
      (B f f2 : N) (rest2 body : word) :
  (1 <= c_0)%N -> (1 <= B)%N ->
  skipn i1 t = (4,3,1)%N :: (4,2,B)%N :: rest2 ->
  jump_comp ((2,2,(c_0+1))%N :: firstn i1 t) B rest2 f
    = Some (JMP, body, f2) ->
  cempty (cdispatch Tftrip ((2,2,c_0)%N :: t) 1%nat
            (d_jcomp (firstn i1 t) B rest2 f))
  \/ sound_impl_c (cdispatch Tftrip ((2,2,c_0)%N :: t) 1%nat
                     (d_jcomp (firstn i1 t) B rest2 f))
       ((2,2,c_0)%N :: t) f (normalize body) f2.
Proof.
  intros HC0 HB1 ESFX EJC.
  set (dl := d_jcomp (firstn i1 t) B rest2 f) in *.
  destruct (cempty_dec dl) as [HE|HE];
    [left; apply cempty_cdispatch; exact HE|]. right.
  pose proof (cin_of_not_cempty dl HE) as Hk.
  unfold dl in Hk.
  assert (HJS : exists sg, jump_seg (firstn i1 t) B = Some sg).
  { unfold d_jcomp in Hk.
    destruct (forallb is_col (firstn i1 t)); cbn [negb] in Hk;
      [|exact (cundef_absurd _ _ Hk)].
    destruct rest2 as [|g0 r0].
    - unfold dseg_lawR, dseg in Hk.
      destruct (f =? 4)%N;
        [|destruct (5 <=? f)%N; [|exact (cundef_absurd _ _ Hk)]];
        (destruct (cseg (firstn i1 t)) as [[pc gbc]|] eqn:ECS;
         [exact (cseg_seg_some _ pc gbc B ECS)
         |exact (cundef_absurd _ _ Hk)]).
    - destruct (jump_seg (firstn i1 t) B) as [sg|] eqn:EJS;
        [exists sg; reflexivity | exact (cundef_absurd _ _ Hk)]. }
  destruct HJS as (sg & EJS).
  destruct (jump_lawR_seg_both _ _ B EJS) as (lb & ELS).
  destruct (jump_comp_uncons (2,2,(c_0+1))%N (firstn i1 t) rest2 body sg lb
              B f f2 EJS ELS EJC) as (body' & EJC' & ->).
  destruct (d_jcomp_tripc (firstn i1 t) rest2 body' B f f2 _ HB1 EJC' Hk)
    as (c & pp & q & HT0 & EQ).
  assert (HT : FTripC c (clo dl)
                 (sdec (firstn i1 t ++ (4,3,1)%N :: (4,2,B)%N :: rest2) f)
                 pp q)
    by (refine (DebrisLeafC_FTripC_cost_eq _ _ _ _ _ _ _ HT0); apply N2Nat.id).
  assert (ET : t = firstn i1 t ++ (4,3,1)%N :: (4,2,B)%N :: rest2).
  { pose proof (firstn_skipn i1 t) as HFS. rewrite ESFX in HFS.
    symmetry. exact HFS. }
  apply sound_impl_c_normalize. unfold sound_impl_c.
  apply (creach_of_clo _ _ _ (not_cempty_cdispatch _ _ _ _ HE)).
  rewrite clo_cdispatch_ftrip. cbn [firstn].
  change ((2,2,(c_0+1))%N :: body')
    with ((2,2,(c_0+1))%N :: ([] ++ body')).
  rewrite sdecode_master_grow.
  rewrite ET.
  change ((2,2,c_0)%N
          :: (firstn i1 t ++ (4,3,1)%N :: (4,2,B)%N :: rest2))
    with (((2,2,c_0)%N :: [])
          ++ (firstn i1 t ++ (4,3,1)%N :: (4,2,B)%N :: rest2)).
  change ((2,2,1)%N :: (2,2,c_0)%N :: ([] ++ body'))
    with ((2,2,1)%N :: ((2,2,c_0)%N :: []) ++ body').
  refine (creach_cx_eq _ _ _ _ _
            (leaf_trip_returnc c_0 []
               (firstn i1 t ++ (4,3,1)%N :: (4,2,B)%N :: rest2) body'
               f f2 c pp (clo dl) q (Forall_nil _) HC0 HT EQ)).
  f_equal; reflexivity.
Qed.
Lemma firstn_pre {A : Type} (l1 l2 : list A) :
  firstn (List.length l1) (l1 ++ l2) = l1.
Proof.
  induction l1 as [|x t IH]; cbn [List.length firstn app];
    [reflexivity|f_equal; exact IH].
Qed.
Lemma close_lcol (c_0 : N) (t : word) (site : nat)
      (pre site0 body : word) (f f2 K : N) :
  (1 <= c_0)%N ->
  forallb is_col pre = true ->
  t = pre ++ site0 ->
  firstn site ((2,2,c_0)%N :: t) = (2,2,c_0)%N :: pre ->
  (exists c pp q, FTripC c K (sdec site0 f) pp q
                  /\ wconf [] 0 ((1,S pp)::q) = wconf [] 0 (sdec body f2)) ->
  sound_impl_c (cdispatch Tftrip ((2,2,c_0)%N :: t) site (cx K))
    ((2,2,c_0)%N :: t) f
    (normalize ((2,2,(c_0+1))%N :: pre ++ body)) f2.
Proof.
  intros HC0 HP ET HF (c & pp & q & HT & EQ). subst t.
  apply sound_impl_c_normalize. unfold sound_impl_c.
  assert (EQC : (bsum ((2,2,c_0)%N :: pre) + (K + 6))%N
              = (ccolcost (firstn site ((2,2,c_0)%N :: pre ++ site0))
                 + (K + 6))%N).
  { rewrite HF. f_equal; symmetry;
      exact (ccolcost_bsum _ (zpre_cons_col c_0 pre (zpre_of_forallb _ HP))). }
  rewrite cdispatch_ftrip.
  rewrite sdecode_master_grow.
  refine (creach_cx_eq _ _ _ _ EQC _).
  change ((2,2,1)%N :: (2,2,c_0)%N :: (pre ++ body))
    with ((2,2,1)%N :: ((2,2,c_0)%N :: pre) ++ body).
  change ((2,2,c_0)%N :: (pre ++ site0))
    with (((2,2,c_0)%N :: pre) ++ site0).
  exact (leaf_trip_returnc c_0 pre site0 body f f2 c pp K q
           (zpre_of_forallb _ HP) HC0 HT EQ).
Qed.
Lemma lcolJ_tripc (gbc cn : N) (t2 : word) (f : N) :
  (1 <= gbc)%N -> (1 <= cn)%N ->
  exists c pp q,
    FTripC c (d_lcol gbc)
      (sdec ((8,2,1)%N :: (4,2,gbc)%N :: (4,4,1)%N :: (4,2,cn)%N :: t2) f)
      pp q
    /\ wconf [] 0 ((1,S pp)::q)
       = wconf [] 0
           (sdec ([(7,1,1); (3,2,1); (4,2,gbc); (8,2,1)]%N
                  ++ (if (1 <? cn)%N then [(4,2,(cn-1))%N] else [])
                  ++ t2) f).
Proof.
  intros H1 H2.
  destruct (to_nat_ge1 gbc H1) as [h1 EH].
  destruct (to_nat_ge1 cn H2) as [cn1 ECN].
  pose proof (FTripC_lcJMP h1 cn1 (sdec t2 f)) as HJ.
  cbn [uword app] in HJ. rewrite !uword_rep2_snoc in HJ.
  assert (EK : d_lcol gbc = (14 * N.of_nat h1 + 57)%N).
  { unfold d_lcol.
    replace gbc with (N.of_nat (S h1))
      by (rewrite <- EH, N2Nat.id; reflexivity).
    rewrite Nat2N.inj_succ. lia. }
  assert (EIN : sdec ((8,2,1)%N :: (4,2,gbc)%N :: (4,4,1)%N
                        :: (4,2,cn)%N :: t2) f
              = (1,8%nat) :: (0,2%nat)
                :: pair_runs 4 2 (S h1)
                   ++ (1,4%nat) :: (0,4%nat) :: (1,4%nat) :: (0,2%nat)
                      :: pair_runs 4 2 cn1 ++ sdec t2 f).
  { rewrite !sdec_cons. rewrite EH, ECN.
    change (N.to_nat 8) with 8%nat. change (N.to_nat 4) with 4%nat.
    change (N.to_nat 2) with 2%nat. change (N.to_nat 1) with 1%nat.
    cbn [pair_runs app]. rewrite <- ?app_assoc. reflexivity. }
  assert (EOUT : sdec ([(7,1,1); (3,2,1); (4,2,gbc); (8,2,1)]%N
                       ++ (if (1 <? cn)%N then [(4,2,(cn-1))%N] else [])
                       ++ t2) f
               = (1,7%nat) :: (0,1%nat) :: (1,3%nat) :: (0,2%nat)
                 :: pair_runs 4 2 (S h1)
                    ++ (1,8%nat) :: (0,2%nat)
                       :: pair_runs 4 2 cn1 ++ sdec t2 f).
  { destruct ((1 <? cn)%N) eqn:ELT.
    - apply N.ltb_lt in ELT.
      assert (ECM : N.to_nat (cn - 1)%N = cn1)
        by (rewrite N2Nat.inj_sub, ECN;
            change (N.to_nat 1) with 1%nat; lia).
      cbn [app]. rewrite !sdec_cons. rewrite EH, ECM.
      change (N.to_nat 8) with 8%nat. change (N.to_nat 7) with 7%nat.
      change (N.to_nat 4) with 4%nat. change (N.to_nat 3) with 3%nat.
      change (N.to_nat 2) with 2%nat. change (N.to_nat 1) with 1%nat.
      cbn [pair_runs app]. rewrite <- ?app_assoc. reflexivity.
    - apply N.ltb_ge in ELT.
      assert (ECZ : cn1 = O) by lia.
      subst cn1. cbn [app]. rewrite !sdec_cons. rewrite EH.
      change (N.to_nat 8) with 8%nat. change (N.to_nat 7) with 7%nat.
      change (N.to_nat 4) with 4%nat. change (N.to_nat 3) with 3%nat.
      change (N.to_nat 2) with 2%nat. change (N.to_nat 1) with 1%nat.
      cbn [pair_runs app]. rewrite <- ?app_assoc. reflexivity. }
  rewrite EK, EIN, EOUT.
  exists (3 * h1 + 10)%nat, 6%nat,
    ((0,1%nat) :: (1,3%nat) :: (0,2%nat)
     :: pair_runs 4 2 (S h1)
        ++ (1,8%nat) :: (0,2%nat) :: pair_runs 4 2 cn1 ++ sdec t2 f).
  split; [exact HJ|reflexivity].
Qed.
Lemma lcolE_tripc (gbc f : N) :
  (1 <= gbc)%N -> (1 <= f)%N ->
  exists c pp q,
    FTripC c (d_lcol gbc)
      (sdec ((8,2,1)%N :: (4,2,gbc)%N :: [(4,4,1)%N]) f) pp q
    /\ wconf [] 0 ((1,S pp)::q)
       = wconf [] 0 (sdec [(7,1,1); (3,2,1); (4,2,gbc)]%N (f+4)%N).
Proof.
  intros H1 HF1.
  destruct (to_nat_ge1 gbc H1) as [h1 EH].
  destruct (to_nat_ge1 f HF1) as [fq EFQ].
  pose proof (FTripC_lcEND h1 fq) as HE.
  cbn [uword app] in HE. rewrite !uword_rep2_snoc in HE.
  assert (EK : d_lcol gbc = (14 * N.of_nat h1 + 57)%N).
  { unfold d_lcol.
    replace gbc with (N.of_nat (S h1))
      by (rewrite <- EH, N2Nat.id; reflexivity).
    rewrite Nat2N.inj_succ. lia. }
  assert (EFP : frun f = [(1,S fq)])
    by (rewrite (frun_pos f HF1); rewrite EFQ; reflexivity).
  assert (EFA4 : N.to_nat (f + 4)%N = (5 + fq)%nat)
    by (rewrite N2Nat.inj_add, EFQ;
        change (N.to_nat 4) with 4%nat; lia).
  assert (EFP4 : frun (f + 4)%N = [(1,(5 + fq)%nat)])
    by (rewrite (frun_pos (f+4)%N ltac:(lia)); rewrite EFA4; reflexivity).
  assert (EIN : sdec ((8,2,1)%N :: (4,2,gbc)%N :: [(4,4,1)%N]) f
              = (1,8%nat) :: (0,2%nat)
                :: pair_runs 4 2 (S h1)
                   ++ (1,4%nat) :: (0,4%nat) :: [(1,S fq)]).
  { rewrite !sdec_cons, sdec_nil, EFP, EH.
    change (N.to_nat 8) with 8%nat. change (N.to_nat 4) with 4%nat.
    change (N.to_nat 2) with 2%nat. change (N.to_nat 1) with 1%nat.
    cbn [pair_runs app]. rewrite <- ?app_assoc. reflexivity. }
  assert (EOUT : sdec [(7,1,1); (3,2,1); (4,2,gbc)]%N (f+4)%N
               = (1,7%nat) :: (0,1%nat) :: (1,3%nat) :: (0,2%nat)
                 :: pair_runs 4 2 (S h1) ++ [(1,(5 + fq)%nat)]).
  { rewrite !sdec_cons, sdec_nil, EFP4, EH.
    change (N.to_nat 7) with 7%nat. change (N.to_nat 4) with 4%nat.
    change (N.to_nat 3) with 3%nat. change (N.to_nat 2) with 2%nat.
    change (N.to_nat 1) with 1%nat.
    cbn [pair_runs app]. rewrite <- ?app_assoc. reflexivity. }
  rewrite EK, EIN, EOUT.
  exists (3 * h1 + 10)%nat, 6%nat,
    ((0,1%nat) :: (1,3%nat) :: (0,2%nat)
     :: pair_runs 4 2 (S h1) ++ [(1,(5 + fq)%nat)]).
  split; [exact HE|reflexivity].
Qed.
Lemma lcolE0_tripc (f : N) :
  (1 <= f)%N ->
  exists c pp q,
    FTripC c (d_lcol 0)
      (sdec ((8,2,1)%N :: [(4,4,1)%N]) f) pp q
    /\ wconf [] 0 ((1,S pp)::q)
       = wconf [] 0 (sdec [(7,1,1); (3,2,1)]%N (f+4)%N).
Proof.
  intros HF1.
  destruct (to_nat_ge1 f HF1) as [fq EFQ].
  pose proof (FTripC_lcEND0 fq) as HE.
  assert (EK : d_lcol 0 = 43%N) by reflexivity.
  assert (EFP : frun f = [(1,S fq)])
    by (rewrite (frun_pos f HF1); rewrite EFQ; reflexivity).
  assert (EFA4 : N.to_nat (f + 4)%N = (5 + fq)%nat)
    by (rewrite N2Nat.inj_add, EFQ;
        change (N.to_nat 4) with 4%nat; lia).
  assert (EFP4 : frun (f + 4)%N = [(1,(5 + fq)%nat)])
    by (rewrite (frun_pos (f+4)%N ltac:(lia)); rewrite EFA4; reflexivity).
  assert (EIN : sdec ((8,2,1)%N :: [(4,4,1)%N]) f
              = (1,8%nat) :: (0,2%nat) :: (1,4%nat) :: (0,4%nat)
                :: [(1,S fq)]).
  { rewrite !sdec_cons, sdec_nil, EFP.
    change (N.to_nat 8) with 8%nat. change (N.to_nat 4) with 4%nat.
    change (N.to_nat 2) with 2%nat. change (N.to_nat 1) with 1%nat.
    cbn [pair_runs app]. reflexivity. }
  assert (EOUT : sdec [(7,1,1); (3,2,1)]%N (f+4)%N
               = (1,7%nat) :: (0,1%nat) :: (1,3%nat) :: (0,2%nat)
                 :: [(1,(5 + fq)%nat)]).
  { rewrite !sdec_cons, sdec_nil, EFP4.
    change (N.to_nat 7) with 7%nat. change (N.to_nat 3) with 3%nat.
    change (N.to_nat 2) with 2%nat. change (N.to_nat 1) with 1%nat.
    cbn [pair_runs app]. reflexivity. }
  rewrite EK, EIN, EOUT.
  exists 7%nat, 6%nat,
    ((0,1%nat) :: (1,3%nat) :: (0,2%nat) :: [(1,(5 + fq)%nat)]).
  split; [exact HE|reflexivity].
Qed.
Lemma lcolS_tripc (X cn : N) (t2 : word) (f : N) :
  (5 <= X)%N -> (1 <= cn)%N ->
  exists c pp q,
    FTripC c (d_lcstd X)
      (sdec ((X,4,1)%N :: (4,2,cn)%N :: t2) f) pp q
    /\ wconf [] 0 ((1,S pp)::q)
       = wconf [] 0
           (sdec (((X-1)%N,1,1)%N :: (7,2,1)%N
                  :: (if (1 <? cn)%N then [(4,2,(cn-1))%N] else []) ++ t2) f).
Proof.
  intros HX H2.
  destruct (to_nat_ge1 cn H2) as [cn1 ECN].
  set (x1 := (N.to_nat X - 5)%nat).
  assert (EX : N.to_nat X = (5 + x1)%nat) by (unfold x1; lia).
  assert (EXM : N.to_nat (X - 1)%N = (4 + x1)%nat)
    by (rewrite N2Nat.inj_sub, EX; change (N.to_nat 1) with 1%nat; lia).
  pose proof (FTripC_lcSTD x1 cn1 (sdec t2 f)) as HS.
  assert (EK : d_lcstd X = (2 * N.of_nat x1 + 23)%N).
  { unfold d_lcstd.
    replace X with (N.of_nat (5 + x1)%nat)
      by (rewrite <- EX, N2Nat.id; reflexivity).
    rewrite Nat2N.inj_add. change (N.of_nat 5) with 5%N. lia. }
  assert (EIN : sdec ((X,4,1)%N :: (4,2,cn)%N :: t2) f
              = (1,(5 + x1)%nat) :: (0,4%nat) :: (1,4%nat) :: (0,2%nat)
                :: pair_runs 4 2 cn1 ++ sdec t2 f).
  { rewrite !sdec_cons, EX, ECN.
    change (N.to_nat 4) with 4%nat. change (N.to_nat 2) with 2%nat.
    change (N.to_nat 1) with 1%nat.
    cbn [pair_runs app]. rewrite <- ?app_assoc. reflexivity. }
  assert (EOUT : sdec (((X-1)%N,1,1)%N :: (7,2,1)%N
                       :: (if (1 <? cn)%N then [(4,2,(cn-1))%N] else [])
                          ++ t2) f
               = (1,(4 + x1)%nat) :: (0,1%nat) :: (1,7%nat) :: (0,2%nat)
                 :: pair_runs 4 2 cn1 ++ sdec t2 f).
  { destruct ((1 <? cn)%N) eqn:ELT.
    - apply N.ltb_lt in ELT.
      assert (ECM : N.to_nat (cn - 1)%N = cn1)
        by (rewrite N2Nat.inj_sub, ECN;
            change (N.to_nat 1) with 1%nat; lia).
      cbn [app]. rewrite !sdec_cons, EXM, ECM.
      change (N.to_nat 7) with 7%nat. change (N.to_nat 4) with 4%nat.
      change (N.to_nat 2) with 2%nat. change (N.to_nat 1) with 1%nat.
      cbn [pair_runs app]. rewrite <- ?app_assoc. reflexivity.
    - apply N.ltb_ge in ELT.
      assert (ECZ : cn1 = O) by lia.
      subst cn1. cbn [app]. rewrite !sdec_cons, EXM.
      change (N.to_nat 7) with 7%nat. change (N.to_nat 2) with 2%nat.
      change (N.to_nat 1) with 1%nat.
      cbn [pair_runs app]. rewrite <- ?app_assoc. reflexivity. }
  rewrite EK, EIN, EOUT.
  exists 4%nat, (3 + x1)%nat,
    ((0,1%nat) :: (1,7%nat) :: (0,2%nat) :: pair_runs 4 2 cn1 ++ sdec t2 f).
  split; [exact HS|reflexivity].
Qed.
Ltac no_law := intros _; left; exact cempty_cundef.
Ltac not_rok := intros HH; discriminate HH.
Ltac comp_none_tail :=
  match goal with |- context [wat ?a ?b] =>
    destruct (wat a b) end; [|not_rok];
  match goal with |- context [ (gZ ?g =? 1)%N ] =>
    destruct ((gZ g =? 1)%N) end; [not_rok|];
  match goal with |- context [e0_chain ?a ?b] =>
    destruct (e0_chain a b) end; [not_rok|];
  match goal with |- context [deliver_tick ?a ?b ?c ?d ?e] =>
    destruct (deliver_tick a b c d e) end; not_rok.
Ltac take_jmp bd ff :=
  intros HH;
  match goal with
  | |- _ \/ sound_impl_c _ _ _ ?ww ?f2 =>
      assert (EWq : normalize bd = ww)
        by (exact (f_equal (fun p => match fst p with
                                     | ROk y _ => y | _ => ww end) HH));
      assert (EFq : ff = f2)
        by (exact (f_equal (fun p => match fst p with
                                     | ROk _ y => y | _ => ff end) HH));
      subst ww; subst f2
  end.
Ltac take_rok c_0 t i1 sfx' f2 ww ff :=
  intros HH;
  assert (EWq : normalize (((2,2,(c_0+1))%N :: firstn i1 t) ++ sfx') = ww)
    by (exact (f_equal (fun p => match fst p with
                                 | ROk y _ => y | _ => ww end) HH));
  assert (EFq : f2 = ff)
    by (exact (f_equal (fun p => match fst p with
                                 | ROk _ y => y | _ => ff end) HH));
  subst ww; subst ff.
Theorem d_comp_sound (w : word) (f : N) (h : nat)
        (w' : word) (f' : N) (i : nat) :
  step_after_front None w f h = (ROk w' f', i) ->
  cempty (d_comp w f h) \/ sound_impl_c (d_comp w f h) w f w' f'.
Proof.
  unfold step_after_front, step_after_front_with,
         step_after_front_with_guard, d_comp.
  cbn [orb negb].
  match goal with
  | |- context [find_active w ?st] =>
      destruct (find_active w st) as [i0|] eqn:EFA
  end.
  -
    match goal with |- context [ if negb ?b then _ else _ ] =>
      destruct b eqn:EP end; cbn [negb]; [|not_rok].
    match goal with |- context [ if negb ?b then _ else _ ] =>
      destruct b eqn:EG0 end; cbn [negb]; [|not_rok].
    match goal with |- context [ if negb ?b then _ else _ ] =>
      destruct b eqn:EL1 end; cbn [negb]; [|not_rok].
    destruct w as [|[[o0 z0] c_0] t]; [discriminate EG0|].
    cbn [gO gZ gC] in EG0.
    apply andb_prop in EG0; destruct EG0 as (EG0 & EI0).
    apply andb_prop in EG0; destruct EG0 as (EG0 & EC0).
    apply andb_prop in EG0; destruct EG0 as (EO0 & EZ0).
    apply N.eqb_eq in EO0. apply N.eqb_eq in EZ0. apply N.leb_le in EC0.
    apply negb_true_iff in EI0.
    subst o0 z0.
    destruct i0 as [|i1]; [cbn [Nat.eqb] in EI0; discriminate EI0|].
    cbn [firstn skipn] in EP |- *.
    apply andb_prop in EP. destruct EP as (_ & EP).
    destruct (skipn i1 t) as [|[[o4 z4] c4] s2t] eqn:ESFX; [no_law|].
    destruct ((o4 =? 4)%N && (z4 =? 3)%N && (c4 =? 1)%N
              && Nat.leb 3 (S i1)) eqn:EA.
    {
      apply andb_prop in EA. destruct EA as (EA & _).
      apply andb_prop in EA. destruct EA as (EA & EAC).
      apply andb_prop in EA. destruct EA as (EAO & EAZ).
      apply N.eqb_eq in EAO, EAZ, EAC. subst o4 z4 c4.
      destruct s2t as [|[[o5 z5] Bq] rest2].
      {
        match goal with |- context [endR_seg ?a ?b] =>
          destruct (endR_seg a b) as [body|] eqn:EES end.
        2:{ comp_none_tail. }
        intros HH.
        assert (EWq : normalize body = w')
          by (exact (f_equal (fun p => match fst p with
                                       | ROk y _ => y | _ => w' end) HH)).
        assert (EFq : 3%N = f')
          by (exact (f_equal (fun p => match fst p with
                                       | ROk _ y => y | _ => 3%N end) HH)).
        subst w'; subst f'.
        exact (close_endR c_0 t i1 body f EC0 ESFX EES). }
      destruct ((o5 =? 4)%N && (z5 =? 2)%N) eqn:E52.
      {
        destruct (1 <=? Bq)%N eqn:EBb.
        2:{ comp_none_tail. }
        apply N.leb_le in EBb.
        apply andb_prop in E52. destruct E52 as (EO5 & EZ5).
        apply N.eqb_eq in EO5, EZ5. subst o5 z5.
        match goal with |- context [jump_comp ?a ?b ?c ?d] =>
          destruct (jump_comp a b c d) as [[[kd bd] fd]|] eqn:EJC end.
        2:{ comp_none_tail. }
        rewrite (jump_comp_JMP _ _ _ _ _ _ _ EJC) in EJC |- *.
        intros HH.
        assert (EWq : normalize bd = w')
          by (exact (f_equal (fun p => match fst p with
                                       | ROk y _ => y | _ => w' end) HH)).
        assert (EFq : fd = f')
          by (exact (f_equal (fun p => match fst p with
                                       | ROk _ y => y | _ => f' end) HH)).
        subst w'; subst f'.
        exact (close_jcomp c_0 t i1 Bq f fd rest2 bd EC0 EBb ESFX EJC). }
      destruct (((z5 =? 3)%N && (Bq =? 1)%N
                 && match rest2 with [] => true | _ => false end
                 && (f =? 4)%N && (1 <=? o5)%N)) eqn:EY.
      {
        apply andb_prop in EY. destruct EY as (EY & EO51).
        apply andb_prop in EY. destruct EY as (EY & EF4).
        apply andb_prop in EY. destruct EY as (EY & ENIL).
        apply andb_prop in EY. destruct EY as (EZ53 & EB1).
        apply N.eqb_eq in EZ53, EB1, EF4. apply N.leb_le in EO51.
        subst z5 Bq f.
        destruct rest2 as [|g2 rest2t]; [|discriminate ENIL].
        match goal with |- context [endY_seg ?a ?b] =>
          destruct (endY_seg a b) as [body|] eqn:EES end.
        2:{ comp_none_tail. }
        intros HH.
        assert (EWq : normalize body = w')
          by (exact (f_equal (fun p => match fst p with
                                       | ROk y _ => y | _ => w' end) HH)).
        assert (EFq : 3%N = f')
          by (exact (f_equal (fun p => match fst p with
                                       | ROk _ y => y | _ => 3%N end) HH)).
        subst w'; subst f'.
        exact (close_endY c_0 t i1 body o5 EC0 ESFX EO51 EES). }
      match goal with |- context [fire_comp ?n ?st ?ff] =>
        destruct (fire_comp n st ff) as [[sfx' f2]|] eqn:EFCq end.
      2:{ comp_none_tail. }
      take_rok c_0 t i1 sfx' f2 w' f'.
      exact (close_fire _ c_0 t i1 ((4,3,1)%N :: (o5,z5,Bq)%N :: rest2)
               sfx' f f2 EC0 EP ESFX EFCq). }
    destruct ((z4 =? 3)%N && (c4 =? 1)%N) eqn:EB.
    {
      match goal with |- context [fire_comp ?n ?st ?ff] =>
        destruct (fire_comp n st ff) as [[sfx' f2]|] eqn:EFCq end.
      2:{ comp_none_tail. }
      take_rok c_0 t i1 sfx' f2 w' f'.
      exact (close_fire _ c_0 t i1 ((o4,z4,c4)%N :: s2t)
               sfx' f f2 EC0 EP ESFX EFCq). }
    destruct ((z4 =? 1)%N) eqn:EC.
    {
      match goal with |- context [leaf_act ?st ?ff] =>
        destruct (leaf_act st ff) as [[sfx' f2]|] eqn:ELA end.
      2:{ comp_none_tail. }
      take_rok c_0 t i1 sfx' f2 w' f'.
      exact (close_leaf c_0 t i1 ((o4,z4,c4)%N :: s2t)
               sfx' f f2 EC0 EP ESFX ELA). }
    destruct ((z4 =? 4)%N && (c4 =? 1)%N) eqn:EZ4; [|no_law].
    apply andb_prop in EZ4. destruct EZ4 as (EZ44 & EC41).
    apply N.eqb_eq in EZ44. apply N.eqb_eq in EC41. subst z4 c4.
    assert (ET : t = firstn i1 t ++ skipn i1 t)
      by (symmetry; apply firstn_skipn).
    destruct s2t as [|[[on zn] cn] t2].
    {
      destruct ((o4 =? 4)%N && (1 <=? f)%N) eqn:EO4F; [|comp_none_tail].
      apply andb_prop in EO4F. destruct EO4F as (EO44 & EF1).
      apply N.eqb_eq in EO44. apply N.leb_le in EF1. subst o4.
      match goal with |- context [last2 ?a] =>
        destruct (last2 a)
          as [[[ini [[gao gaz] gac]] [[gbo gbz] gbc]]|] eqn:EL2 end;
        [|comp_none_tail].
      pose proof (last2_split _ _ _ _ EL2) as ECOLS.
      destruct ((gao =? 8)%N && (gaz =? 2)%N && (gac =? 1)%N
                && (gbo =? 4)%N && (gbz =? 2)%N && (1 <=? gbc)%N) eqn:EG1.
      {
        apply andb_prop in EG1. destruct EG1 as (EG1 & EGB1).
        apply andb_prop in EG1. destruct EG1 as (EG1 & EBZ).
        apply andb_prop in EG1. destruct EG1 as (EG1 & EBO).
        apply andb_prop in EG1. destruct EG1 as (EAOZ & EAC).
        apply andb_prop in EAOZ. destruct EAOZ as (EAO & EAZ).
        apply N.eqb_eq in EAO, EAZ, EAC, EBO, EBZ.
        apply N.leb_le in EGB1. subst gao gaz gac gbo gbz.
        destruct ini as [|ihd ini'];
          [exfalso; cbn [app] in ECOLS; congruence|].
        injection ECOLS as EIHD ECOLS'. subst ihd.
        assert (HPC' : forallb is_col ini' = true).
        { assert (EPP : forallb is_col
                          (ini' ++ [(8,2,1)%N; (4,2,gbc)%N]) = true)
            by (rewrite ECOLS' in EP; exact EP).
          rewrite forallb_app in EPP. apply andb_prop in EPP.
          destruct EPP as (EPP1 & _). exact EPP1. }
        assert (ETT : t = ini' ++ ((8,2,1)%N :: (4,2,gbc)%N
                                     :: [(4,4,1)%N])).
        { rewrite ET at 1. rewrite ECOLS', ESFX.
          rewrite <- app_assoc. reflexivity. }
        take_jmp (((2,2,(c_0+1))%N :: ini')
                  ++ [(7,1,1); (3,2,1); (4,2,gbc)]%N) (f+4)%N.
        right.
        refine (close_lcol c_0 t (S (List.length ini')) ini'
                  ((8,2,1)%N :: (4,2,gbc)%N :: [(4,4,1)%N])
                  [(7,1,1); (3,2,1); (4,2,gbc)]%N f (f+4)%N _
                  EC0 HPC' ETT _ (lcolE_tripc gbc f EGB1 EF1)).
        cbn [firstn]. f_equal. rewrite ETT. apply firstn_pre. }
      destruct ((gbo =? 8)%N && (gbz =? 2)%N && (gbc =? 1)%N) eqn:EG2;
        [|comp_none_tail].
      apply andb_prop in EG2. destruct EG2 as (EG2 & EBC1x).
      apply andb_prop in EG2. destruct EG2 as (EBO8 & EBZ2).
      apply N.eqb_eq in EBO8, EBZ2, EBC1x. subst gbo gbz gbc.
      assert (HSP : exists pr,
                 ini ++ [(gao,gaz,gac)%N] = (2,2,(c_0+1))%N :: pr
                 /\ firstn i1 t = pr ++ [(8,2,1)%N]
                 /\ List.length ini = List.length pr).
      { destruct ini as [|ihd ini'].
        - cbn [app] in ECOLS.
          injection ECOLS as EA1 EA2 EA3 ECOLS'. subst gao gaz gac.
          exists (@nil bg). cbn [app List.length].
          split; [reflexivity|split; [exact ECOLS'|reflexivity]].
        - injection ECOLS as EIHD ECOLS'. subst ihd.
          exists (ini' ++ [(gao,gaz,gac)%N]).
          cbn [app]. split; [reflexivity|].
          rewrite ECOLS', <- app_assoc. cbn [app].
          split; [reflexivity|].
          rewrite length_app. cbn [List.length]. lia. }
      destruct HSP as (pr & HSP1 & HSP2 & HSPL).
      assert (HPC' : forallb is_col pr = true).
      { assert (EPP : forallb is_col (pr ++ [(8,2,1)%N]) = true)
          by (rewrite HSP2 in EP; exact EP).
        rewrite forallb_app in EPP. apply andb_prop in EPP.
        destruct EPP as (EPP1 & _). exact EPP1. }
      assert (ETT : t = pr ++ ((8,2,1)%N :: [(4,4,1)%N])).
      { rewrite ET at 1. rewrite HSP2, ESFX.
        rewrite <- app_assoc. reflexivity. }
      take_jmp (ini ++ [(gao,gaz,gac); (7,1,1); (3,2,1)]%N) (f+4)%N.
      right.
      assert (EBODY : ini ++ [(gao,gaz,gac); (7,1,1); (3,2,1)]%N
                    = ((2,2,(c_0+1))%N :: pr) ++ [(7,1,1); (3,2,1)]%N).
      { rewrite <- HSP1, <- app_assoc. reflexivity. }
      rewrite EBODY.
      refine (close_lcol c_0 t (S (List.length ini)) pr
                ((8,2,1)%N :: [(4,4,1)%N]) [(7,1,1); (3,2,1)]%N
                f (f+4)%N _ EC0 HPC' ETT _ (lcolE0_tripc f EF1)).
      rewrite HSPL. cbn [firstn]. f_equal. rewrite ETT. apply firstn_pre. }
    destruct ((o4 =? 4)%N && (on =? 4)%N && (zn =? 2)%N
              && (1 <=? cn)%N) eqn:EC4.
    {
      apply andb_prop in EC4. destruct EC4 as (EC4 & ECN1).
      apply andb_prop in EC4. destruct EC4 as (EC4 & EZN2).
      apply andb_prop in EC4. destruct EC4 as (EO44 & EON4).
      apply N.eqb_eq in EO44, EON4, EZN2. apply N.leb_le in ECN1.
      subst o4 on zn.
      match goal with |- context [last2 ?a] =>
        destruct (last2 a)
          as [[[ini [[gao gaz] gac]] [[gbo gbz] gbc]]|] eqn:EL2 end;
        [|comp_none_tail].
      pose proof (last2_split _ _ _ _ EL2) as ECOLS.
      destruct ((gao =? 8)%N && (gaz =? 2)%N && (gac =? 1)%N
                && (gbo =? 4)%N && (gbz =? 2)%N && (1 <=? gbc)%N) eqn:EG1;
        [|comp_none_tail].
      apply andb_prop in EG1. destruct EG1 as (EG1 & EGB1).
      apply andb_prop in EG1. destruct EG1 as (EG1 & EBZ).
      apply andb_prop in EG1. destruct EG1 as (EG1 & EBO).
      apply andb_prop in EG1. destruct EG1 as (EAOZ & EAC).
      apply andb_prop in EAOZ. destruct EAOZ as (EAO & EAZ).
      apply N.eqb_eq in EAO, EAZ, EAC, EBO, EBZ.
      apply N.leb_le in EGB1. subst gao gaz gac gbo gbz.
      destruct ini as [|ihd ini'];
        [exfalso; cbn [app] in ECOLS; congruence|].
      injection ECOLS as EIHD ECOLS'. subst ihd.
      assert (HPC' : forallb is_col ini' = true).
      { assert (EPP : forallb is_col
                        (ini' ++ [(8,2,1)%N; (4,2,gbc)%N]) = true)
          by (rewrite ECOLS' in EP; exact EP).
        rewrite forallb_app in EPP. apply andb_prop in EPP.
        destruct EPP as (EPP1 & _). exact EPP1. }
      assert (ETT : t = ini' ++ ((8,2,1)%N :: (4,2,gbc)%N
                                   :: (4,4,1)%N :: (4,2,cn)%N :: t2)).
      { rewrite ET at 1. rewrite ECOLS', ESFX.
        rewrite <- app_assoc. reflexivity. }
      take_jmp (((2,2,(c_0+1))%N :: ini')
                ++ [(7,1,1); (3,2,1); (4,2,gbc); (8,2,1)]%N
                ++ (if (1 <? cn)%N then [(4,2,(cn-1))%N] else []) ++ t2) f.
      right.
      refine (close_lcol c_0 t (S (List.length ini')) ini'
                ((8,2,1)%N :: (4,2,gbc)%N :: (4,4,1)%N :: (4,2,cn)%N :: t2)
                ([(7,1,1); (3,2,1); (4,2,gbc); (8,2,1)]%N
                 ++ (if (1 <? cn)%N then [(4,2,(cn-1))%N] else []) ++ t2)
                f f _ EC0 HPC' ETT _ (lcolJ_tripc gbc cn t2 f EGB1 ECN1)).
      cbn [firstn]. f_equal. rewrite ETT. apply firstn_pre. }
    destruct ((4 <? o4)%N && (on =? 4)%N && (zn =? 2)%N
              && (1 <=? cn)%N) eqn:EC5; [|comp_none_tail].
    apply andb_prop in EC5. destruct EC5 as (EC5 & ECN1).
    apply andb_prop in EC5. destruct EC5 as (EC5 & EZN2).
    apply andb_prop in EC5. destruct EC5 as (EO4G & EON4).
    apply N.eqb_eq in EON4, EZN2. apply N.ltb_lt in EO4G.
    apply N.leb_le in ECN1. subst on zn.
    take_rok c_0 t i1
      ((o4-1,1,1)%N :: (7,2,1)%N
       :: (if (1 <? cn)%N then [(4,2,(cn-1))%N] else []) ++ t2) f w' f'.
    right.
    refine (close_lcol c_0 t (S i1) (firstn i1 t) ((o4,4,1)%N :: (4,2,cn)%N :: t2)
              ((o4-1,1,1)%N :: (7,2,1)%N
               :: (if (1 <? cn)%N then [(4,2,(cn-1))%N] else []) ++ t2)
              f f _ EC0 EP _ _ (lcolS_tripc o4 cn t2 f ltac:(lia) ECN1)).
    { rewrite ET at 1. rewrite ESFX. reflexivity. }
    { cbn [firstn]. reflexivity. }
  -
    destruct w as [|[[o0 z0] c_0] t]; [not_rok|].
    match goal with |- context [ if negb ?b then _ else _ ] =>
      destruct b eqn:EG0 end; cbn [negb]; [|not_rok].
    cbn [gO gZ gC] in EG0.
    apply andb_prop in EG0; destruct EG0 as (EG0 & EC0).
    apply andb_prop in EG0; destruct EG0 as (EO0 & EZ0).
    apply N.eqb_eq in EO0. apply N.eqb_eq in EZ0. apply N.leb_le in EC0.
    subst o0 z0.
    match goal with
    | |- context [cmf_from ?a ?b ?c] =>
        destruct (cmf_from a b c) as [j|] eqn:ECF
    end.
    2:{ match goal with |- context [existsb ?p ?l] =>
          destruct (existsb p l) end; [|no_law].
        match goal with |- context [debris_to_blank ?a ?b] =>
          destruct (debris_to_blank a b) end; no_law. }
    pose proof (cmf_from_inv _ _ _ _ ECF) as HJ.
    destruct HJ as (HJ1 & _).
    match goal with |- context [ if negb ?b then _ else _ ] =>
      destruct b eqn:EFB end; cbn [negb]; [|not_rok].
    destruct j as [|j1].
    { exfalso.
      match type of HJ1 with
      | (Nat.max 1 ?x <= 0)%nat =>
          assert (HM : (1 <= Nat.max 1 x)%nat)
            by (destruct x; cbn [Nat.max]; lia)
      end. lia. }
    cbn [firstn skipn] in EFB |- *.
    apply andb_prop in EFB. destruct EFB as (_ & EFB).
    match goal with |- context [leaf_act ?st ?ff] =>
      destruct (leaf_act st ff) as [[sfx' f2]|] eqn:ELA end.
    2:{ match goal with |- context [chain_merge_advance ?a ?b ?c ?d] =>
          destruct (chain_merge_advance a b c d) end; not_rok. }
    take_rok c_0 t j1 sfx' f2 w' f'.
    exact (close_leaf c_0 t j1 (skipn j1 t) sfx' f f2 EC0 EFB eq_refl ELA).
Qed.
