Lemma primordial_sound_c0 (f : N) :
  (2 <= f)%N ->
  sound_impl_c (cx 17%N) [(4,1,1)]%N f [(2,2,1); (4,1,1)]%N (f-1)%N.
Proof.
  intros Hf.
  unfold sound_impl_c, sdecode.
  pose proof (bridge_fartick_pc [] 4 f
                (Forall_nil _) ltac:(lia) Hf) as BF.
  replace (bsum [] + dtick_z1 4)%N with 17%N in BF
    by (unfold dtick_z1; cbn [bsum]; lia).
  exact BF.
Qed.
Lemma primordial_sound_c1 (ca f : N) :
  (2 <= f)%N ->
  sound_impl_c (cx (10 * ca + 17)%N)
    [(2,2,ca); (4,1,1)]%N f [(2,2,(ca+1)); (4,1,1)]%N (f-1)%N.
Proof.
  intros Hf.
  unfold sound_impl_c.
  assert (EM : sdecode ((2,2,1)%N :: [(2,2,ca)%N] ++ [(4,1,1)%N]) (f-1)%N
             = sdecode [(2,2,(ca+1))%N; (4,1,1)%N] (f-1)%N).
  { cbn [app]. rewrite !sdecode_cons.
    replace ((ca+1)%N) with ((1+ca)%N) by lia.
    rewrite gdec1_merge. rewrite <- !app_assoc. reflexivity. }
  rewrite <- EM.
  pose proof (bridge_fartick_pc [(2,2,ca)%N] 4 f
                ltac:(repeat constructor; cbn; try split; lia)
                ltac:(lia) Hf) as BF.
  replace (bsum [(2,2,ca)%N] + dtick_z1 4)%N
    with (10 * ca + 17)%N in BF
    by (unfold dtick_z1; cbn [bsum bpc]; lia).
  exact BF.
Qed.
Lemma primordial_sound_c2 (ca : N) :
