  unfold sound_impl_c.
  assert (EM : sdecode ((2,2,1)%N :: [(2,2,ca)%N]) 4%N
             = sdecode [(2,2,(ca+1))%N] 4%N).
  { rewrite !sdecode_cons.
    replace ((ca+1)%N) with ((1+ca)%N) by lia.
    rewrite gdec1_merge. rewrite <- !app_assoc. reflexivity. }
  rewrite <- EM.
  pose proof (harvest_branch_soundc [(2,2,ca)%N] 4
                eq_refl ltac:(lia)) as BH.
  replace (bsum [(2,2,ca)%N] + dtick_z1 4)%N
    with (10 * ca + 17)%N in BH
    by (unfold dtick_z1; cbn [bsum bpc]; lia).
  exact BH.
Qed.
Lemma spanC'_sound_c (a m V : N) :
  (1 <= a)%N -> (1 <= m)%N -> (1 <= V)%N ->
  sound_impl_c (cx (10 * a + 10 * m + 28 * V + 83)%N)
    [(2,2,a); (5,2,1); (3,2,m); (2,2,1); (4,2,V)]%N 4
    [(2,2,a+1); (4,1,1); (3,1,1); (4,1,m-1);
     (6,2,1); (4,2,V+1)]%N 4.
Proof.
  intros Ha Hm HV.
  unfold sound_impl_c.
  replace (10 * a + 10 * m + 28 * V + 83)%N
    with (10 * N.of_nat (N.to_nat (a-1)%N)
          + 10 * N.of_nat (N.to_nat (m-1)%N)
          + 28 * N.of_nat (N.to_nat (V-1)%N) + 131)%N
    by (rewrite !N2Nat.id; lia).
  change (sdecode ?x ?y) with (sdec x y).
  rewrite !sdec_cons, sdec_nil.
  cbn [frun].
  change (N.to_nat 2) with 2%nat.
  change (N.to_nat 5) with 5%nat.
  change (N.to_nat 6) with 6%nat.
  change (N.to_nat 3) with 3%nat.
  change (N.to_nat 4) with 4%nat.
  change (N.to_nat 1) with 1%nat.
  rewrite (NtoS a Ha), (NtoS m Hm), (NtoS V HV),
          (NtoSS a Ha), (NtoSS V HV).
  cbn [pair_runs app].
  repeat rewrite <- app_assoc.
  pose proof (spanC'_tripc (N.to_nat (a-1)%N) (N.to_nat (m-1)%N)
                (N.to_nat (V-1)%N)) as HT.
  cbn [pair_runs app] in HT.
  repeat rewrite <- app_assoc in HT.
  exact (creach_of_wrunc _ _ _ _ _ _ HT).
Qed.
