Lemma clean_sound_c (K : N) (rest : word) (f : N) :
  (2 <= K)%N ->
  sound_impl_c (cx (63 * ((K / 2) * (K / 2 - 1)) + 243 * (K / 2))%N)
    ((2,2,4)%N :: (5,2,1)%N :: (3,1,K)%N :: rest) f
    ([(2,2,(3 * (K / 2) + 4)); (5,2,1); (3,2,(K / 2))]%N
       ++ (if ((K mod 2) =? 1)%N then [(3,1,1)%N] else []) ++ rest) f.
Proof.
  intros HK.
  unfold sound_impl_c.
  replace (sdecode ((2,2,4)%N :: (5,2,1)%N :: (3,1,K)%N :: rest) f)
    with (sdecode ((2,2,4)%N :: (5,2,1)%N :: (3,2,0)%N :: (3,1,K)%N
                     :: rest) f)
    by (exact (sdecode_drop0_at [(2,2,4)%N; (5,2,1)%N] 3 2
                 ((3,1,K)%N :: rest) f)).
  pose proof (bridge_cleanconvc 4 0 K rest f HK) as BC.
  replace (dclean 4 0) with 243%N in BC
    by (unfold dclean; lia).
  replace ((4 + 3 * (K / 2))%N) with ((3 * (K / 2) + 4)%N) in BC by lia.
  replace ((0 + K / 2)%N) with ((K / 2)%N) in BC by lia.
  destruct ((K mod 2 =? 1)%N) eqn:EKM.
  - apply N.eqb_eq in EKM. rewrite EKM in BC. cbn [app]. exact BC.
  - assert (EK0 : (K mod 2 = 0)%N).
    { apply N.eqb_neq in EKM.
      pose proof (N.mod_lt K 2 ltac:(lia)). lia. }
    rewrite EK0 in BC. cbn [app].
    replace (sdecode ((2,2,(3 * (K / 2) + 4))%N :: (5,2,1)%N
                        :: (3,2,(K / 2))%N :: rest) f)
      with (sdecode ((2,2,(3 * (K / 2) + 4))%N :: (5,2,1)%N
                       :: (3,2,(K / 2))%N :: (3,1,0)%N :: rest) f)
      by (exact (sdecode_drop0_at
                   [(2,2,(3 * (K / 2) + 4))%N; (5,2,1)%N;
                    (3,2,(K / 2))%N] 3 1 rest f)).
    exact BC.
Qed.
Lemma four_sound_c (cN M : N) (rest : word) (f : N) :
  (2 <= M)%N ->
  sound_impl_c
    (cx (108 * ((M / 2) * (M / 2 - 1)) + (40 * cN + 184) * (M / 2))%N)
    ((2,2,cN)%N :: (4,2,1)%N :: (4,1,M)%N :: rest) f
    ((2,2,(cN + 4 * (M / 2)))%N :: (4,2,(1 + M / 2))%N
       :: (4,1,(M mod 2))%N :: rest) f.
Proof.
  intros HM.
  unfold sound_impl_c.
  pose proof (bridge_fourconvc cN 1 M rest f ltac:(lia) HM) as BF.
  replace (dfour cN 1) with (40 * cN + 184)%N in BF
    by (unfold dfour; lia).
  exact BF.
Qed.
Lemma four_sound_c_odd (cN M : N) (rest : word) (f : N) :
  (2 <= M)%N -> (M mod 2 = 1)%N ->
  sound_impl_c
    (cx (108 * ((M / 2) * (M / 2 - 1)) + (40 * cN + 184) * (M / 2))%N)
    ((2,2,cN)%N :: (4,2,1)%N :: (4,1,M)%N :: rest) f
    ((2,2,(cN + 2 * (M - 1)))%N :: (4,2,((M + 1) / 2))%N
       :: (4,1,1)%N :: rest) f.
Proof.
  intros HM HO.
  assert (HQ : M = (2 * (M / 2) + 1)%N)
    by (pose proof (N.div_mod M 2 ltac:(lia)) as HD; rewrite HO in HD; lia).
  pose proof (four_sound_c cN M rest f HM) as H.
  rewrite HO in H.
  replace ((cN + 4 * (M / 2))%N) with ((cN + 2 * (M - 1))%N) in H by lia.
  replace ((1 + M / 2)%N) with (((M + 1) / 2)%N) in H.
  2:{ replace ((M + 1)%N) with ((2 * (M / 2 + 1))%N) by lia.
      rewrite N.mul_comm, N.div_mul by lia. lia. }
  exact H.
Qed.
Lemma four_sound_c_even (cN M : N) (rest : word) (f : N) :
  (2 <= M)%N -> (M mod 2 = 0)%N ->
  sound_impl_c
    (cx (108 * ((M / 2) * (M / 2 - 1)) + (40 * cN + 184) * (M / 2))%N)
    ((2,2,cN)%N :: (4,2,1)%N :: (4,1,M)%N :: rest) f
    ((2,2,(cN + 2 * M))%N :: (4,2,(M / 2 + 1))%N :: rest) f.
Proof.
  intros HM HO.
  assert (HQ : M = (2 * (M / 2))%N)
    by (pose proof (N.div_mod M 2 ltac:(lia)) as HD; rewrite HO in HD; lia).
  pose proof (four_sound_c cN M rest f HM) as H.
  rewrite HO in H.
  replace ((cN + 4 * (M / 2))%N) with ((cN + 2 * M)%N) in H by lia.
  replace ((1 + M / 2)%N) with ((M / 2 + 1)%N) in H by lia.
  unfold sound_impl_c in H |- *.
  replace (sdecode ((2,2,(cN + 2 * M))%N :: (4,2,(M / 2 + 1))%N :: rest) f)
    with (sdecode ((2,2,(cN + 2 * M))%N :: (4,2,(M / 2 + 1))%N
                     :: (4,1,0)%N :: rest) f)
    by (exact (sdecode_drop0_at
                 [(2,2,(cN + 2 * M))%N; (4,2,(M / 2 + 1))%N] 4 1 rest f)).
  exact H.
Qed.
Lemma fr_512_sound_c (w : word) (f : N) (w2 : word) (f2 : N) :
  fr_512 w f = Some (ROk w2 f2) ->
  sound_impl_c (d_512 w f) w f w2 f2.
Proof.
  intros E. unfold fr_512 in E.
  destruct w as [|[[o1 z1] j] w1]; [discriminate E|].
  destruct w1 as [|[[o2 z2] c2] w1']; [killmN E|].
  destruct w1' as [|[[kk z3] c3] rest]; [killmN E|].
  killmN E.
  destruct ((kk <? 3)%N && (1 <=? kk)%N) eqn:EGK; [|discriminate E].
  apply andb_true_iff in EGK as [EK3 EK1].
  apply N.ltb_lt in EK3. apply N.leb_le in EK1.
  destruct ((kk =? 1)%N) eqn:EKQ.
  { apply N.eqb_eq in EKQ. subst kk.
    unfold o_ in E. injection E as E1 E2. subst.
    unfold d_512. apply d512_sound_c1. }
  apply N.eqb_neq in EKQ.
  assert (EK2 : kk = 2%N) by lia. subst kk.
  unfold o_ in E. injection E as E1 E2. subst.
  change ((2 - 1)%N) with 1%N.
  unfold d_512. apply d512_sound_c2.
Qed.
Lemma fr_522_sound_c (w : word) (f : N) (w2 : word) (f2 : N) :
  fr_522 w f = Some (ROk w2 f2) ->
  sound_impl_c (d_522 w f) w f w2 f2.
Proof.
  intros E. unfold fr_522 in E.
  destruct w as [|[[o1 z1] cN] w1]; [discriminate E|].
  destruct w1 as [|[[o2 z2] c2] w1']; [killmN E|].
  destruct w1' as [|[[kk z3] c3] rest]; [killmN E|].
  killmN E.
  destruct ((kk <=? 3)%N && (1 <=? kk)%N) eqn:EGK; [|discriminate E].
  apply andb_true_iff in EGK as [EK3 EK1].
  apply N.leb_le in EK3. apply N.leb_le in EK1.
  destruct ((kk =? 1)%N) eqn:EKQ.
  { apply N.eqb_eq in EKQ. subst kk.
    unfold o_ in E. injection E as E1 E2. subst.
    unfold d_522. apply d522_sound_c1. }
  apply N.eqb_neq in EKQ.
  unfold o_ in E. injection E as E1 E2. subst.
  unfold d_522. apply d522_sound_c2. lia.
Qed.
Lemma fr_prim4_sound_c (w : word) (f : N) (w2 : word) (f2 : N) :
  fr_prim4 w f = Some (ROk w2 f2) ->
  sound_impl_c (d_prim4 w f) w f w2 f2.
Proof.
  intros E. unfold fr_prim4 in E.
  destruct w as [|[[o1 z1] cN] w1]; [discriminate E|].
  destruct w1 as [|g2 w1']; [|killmN E].
  killmN E.
  destruct ((cN =? 4)%N && (f =? 4)%N) eqn:EG; [|discriminate E].
  apply andb_true_iff in EG as [ECN EFF].
  apply N.eqb_eq in ECN. apply N.eqb_eq in EFF. subst cN f.
  unfold o_ in E. injection E as E1 E2. subst.
  change ((4 - 2)%N) with 2%N.
  unfold d_prim4. apply prim4_sound_c.
Qed.
Lemma fr_primordial_sound_c (w : word) (f : N) (w2 : word)
      (f2 : N) :
  fr_primordial w f = Some (ROk w2 f2) ->
  sound_impl_c (d_primordial w f) w f w2 f2.
Proof.
  intros E. unfold fr_primordial in E.
  destruct w as [|[[o1 z1] c1] w1]; [discriminate E|].
  destruct w1 as [|[[o2 z2] c2] w1'].
  {
    killmN E.
    destruct ((2 <=? f)%N) eqn:EF; [|discriminate E].
    apply N.leb_le in EF.
    unfold o_ in E. injection E as E1 E2. subst.
    unfold d_primordial. apply primordial_sound_c0. exact EF. }
  destruct w1' as [|g3 w3]; [|killmN E].
  killmN E.
  destruct ((2 <=? f)%N) eqn:EF.
  { apply N.leb_le in EF.
    unfold o_ in E. injection E as E1 E2. subst.
    unfold d_primordial. apply primordial_sound_c1. exact EF. }
  destruct ((f =? 1)%N) eqn:EF1; [|discriminate E].
  apply N.eqb_eq in EF1. subst f.
  unfold o_ in E. injection E as E1 E2. subst.
  unfold d_primordial. apply primordial_sound_c2.
Qed.
Lemma fr_span2C'_sound_c (w : word) (f : N) (w2 : word)
      (f2 : N) :
  fr_span2C' w f = Some (ROk w2 f2) ->
  sound_impl_c (d_span2C' w f) w f w2 f2.
Proof.
  intros E. unfold fr_span2C' in E.
  destruct w as [|[[o1 z1] c1] w1]; [discriminate E|].
  destruct w1 as [|[[o2 z2] c2] w2']; [killmN E|].
  destruct w2' as [|[[o3 z3] c3] w3]; [killmN E|].
  destruct w3 as [|[[o4 z4] c4] w4]; [killmN E|].
  destruct w4 as [|[[o5 z5] c5] w5]; [killmN E|].
  destruct w5 as [|g6 w6]; [|killmN E].
  killmN E.
  destruct ((1 <=? c1)%N && (1 <=? c3)%N && (1 <=? c5)%N
            && ((f =? 4)%N)) eqn:EG; [|discriminate E].
  apply andb_prop in EG as [EG EF4].
  apply andb_prop in EG as [EG EV1].
  apply andb_prop in EG as [EA1 EM1].
  apply N.leb_le in EA1, EM1, EV1. apply N.eqb_eq in EF4. subst f.
  unfold o_ in E. injection E as E1 E2. subst.
  unfold d_span2C'.
  apply spanC'_sound_c; assumption.
Qed.
Lemma fr_span8far_sound_c (w : word) (f : N) (w2 : word)
      (f2 : N) :
  fr_span8far w f = Some (ROk w2 f2) ->
  sound_impl_c (d_span8far w f) w f w2 f2.
Proof.
  intros E. unfold fr_span8far in E.
  destruct w as [|[[o1 z1] c1] w1]; [discriminate E|].
  destruct w1 as [|[[o2 z2] c2] w2']; [killmN E|].
  destruct w2' as [|[[o3 z3] c3] w3].
  {
    killmN E.
    destruct ((3 <=? c1)%N && (1 <=? c2)%N && ((f =? 3)%N)) eqn:EG;
      [|discriminate E].
    apply andb_prop in EG as [EG EF3].
    apply andb_prop in EG as [EN3 EV1].
    apply N.leb_le in EN3, EV1. apply N.eqb_eq in EF3. subst f.
    unfold o_, span8far_out in E.
    destruct ((1 <? c2)%N) eqn:EVb.
    { cbn [app] in E. injection E as E1 E2. subst.
      unfold d_span8far. apply spanfar3_sound_cV; assumption. }
    cbn [app] in E. injection E as E1 E2. subst.
    unfold d_span8far. apply spanfar3_sound_c1;
      [exact EN3 | apply N.ltb_ge in EVb; lia]. }
  destruct w3 as [|[[o4 z4] c4] w4].
  {
    killmN E.
    destruct ((3 <=? c1)%N && (1 <=? c2)%N && ((f =? 4)%N)) eqn:EG;
      [|discriminate E].
    apply andb_prop in EG as [EG EF4].
    apply andb_prop in EG as [EN3 EV1].
    apply N.leb_le in EN3, EV1. apply N.eqb_eq in EF4. subst f.
    unfold o_, span8far_out in E.
    destruct ((1 <? c2)%N) eqn:EVb.
    { cbn [app] in E. injection E as E1 E2. subst.
      unfold d_span8far. apply spanfar4_sound_cV; assumption. }
    cbn [app] in E. injection E as E1 E2. subst.
    unfold d_span8far. apply spanfar4_sound_c1;
      [exact EN3 | apply N.ltb_ge in EVb; lia]. }
  destruct w4 as [|g5 w5]; [|killmN E].
  killmN E.
  destruct ((3 <=? c1)%N && (1 <=? c2)%N && (1 <=? c4)%N
            && ((f =? 4)%N)) eqn:EG; [|discriminate E].
  apply andb_prop in EG as [EG EF4].
  apply andb_prop in EG as [EG EG1].
  apply andb_prop in EG as [EN3 EV1].
  apply N.leb_le in EN3, EV1. apply N.eqb_eq in EF4. subst f.
  unfold o_, span8far_out in E.
  destruct ((1 <? c2)%N) eqn:EVb.
  { cbn [app] in E. injection E as E1 E2. subst.
    unfold d_span8far. apply spanfar4G_sound_cV; assumption. }
  cbn [app] in E. injection E as E1 E2. subst.
  unfold d_span8far. apply spanfar4G_sound_c1;
    [exact EN3 | apply N.ltb_ge in EVb; lia].
Qed.
Lemma fr_clean_sound_c (w : word) (f : N) (w2 : word) (f2 : N) :
  fr_clean w f = Some (ROk w2 f2) ->
  sound_impl_c (d_clean w f) w f w2 f2.
Proof.
  intros E. unfold fr_clean in E.
  destruct w as [|[[o1 z1] c1] w1]; [discriminate E|].
  destruct w1 as [|[[o2 z2] c2] w1']; [killmN E|].
  destruct w1' as [|[[o3 z3] K] rest]; [killmN E|].
  killmN E.
  destruct ((2 <=? K)%N) eqn:EK2; [|discriminate E].
  cbv zeta in E.
  rewrite !N.div2_div in E.
  rewrite <- N.bit0_odd in E. rewrite N.bit0_eqb in E.
  unfold o_ in E. injection E as E1 E2. subst.
  unfold d_clean. cbv beta iota zeta. rewrite EK2.
  apply clean_sound_c. apply N.leb_le. exact EK2.
Qed.
Lemma fr_four_sound_c (w : word) (f : N) (w2 : word) (f2 : N) :
  fr_four w f = Some (ROk w2 f2) ->
  sound_impl_c (d_four w f) w f w2 f2.
Proof.
  intros E. unfold fr_four in E.
  destruct w as [|[[o1 z1] cN] w1]; [discriminate E|].
  destruct w1 as [|[[o2 z2] c2] w1']; [killmN E|].
  destruct w1' as [|[[o3 z3] M] w3]; [killmN E|].
  destruct w3 as [|[[od zd] cd] w4]; [killmN E|].
  killmN E.
  destruct ((2 <=? M)%N && (((od =? 8)%N && (zd =? 2)%N)
                            || ((od =? 5)%N && (zd =? 1)%N))) eqn:EGF;
    [|discriminate E].
  apply andb_true_iff in EGF as [EM2b _].
  assert (EM2 : (2 <= M)%N) by (apply N.leb_le; exact EM2b).
  rewrite <- N.bit0_odd in E. rewrite N.bit0_eqb in E.
  destruct ((M mod 2 =? 1)%N) eqn:EMOD.
  { apply N.eqb_eq in EMOD.
    unfold o_ in E. injection E as E1 E2. subst.
    rewrite !N.div2_div.
    unfold d_four. cbv beta iota zeta. rewrite EM2b.
    apply four_sound_c_odd; assumption. }
  assert (EM0 : (M mod 2 = 0)%N).
  { apply N.eqb_neq in EMOD.
    assert ((M mod 2 < 2)%N) by (apply N.mod_lt; lia). lia. }
  unfold o_ in E. injection E as E1 E2. subst.
  rewrite !N.div2_div.
  unfold d_four. cbv beta iota zeta. rewrite EM2b.
  apply four_sound_c_even; assumption.
Qed.
