Lemma decorate_sound_disj (r : word -> N -> option res)
      (dd : word -> N -> cost) :
  (forall w f w2 f2, r w f = Some (ROk w2 f2) ->
                     cempty (dd w f) \/ sound_impl_c (dd w f) w f w2 f2) ->
  forall w f w2 f2 d,
    decorate r dd w f = Some (ROk w2 f2, d) ->
    cempty d \/ sound_impl_c d w f w2 f2.
Proof.
  intros H w f w2 f2 d E.
  unfold decorate in E.
  destruct (r w f) as [x|] eqn:EF; [|discriminate E].
  injection E as E1 E2. subst.
  apply H. exact EF.
Qed.
Lemma creach_tgt_eq (d : cost) (u v v' : Q * tape) :
  v = v' -> creach d u v -> creach d u v'.
Proof. intros <- H. exact H. Qed.
Lemma span2A_ftrip_soundc (a m V : N) (rest' cols s sfx mid : word)
      (f f2 : N) (c p : nat) (K : N) (q : wside) :
  rest' = cols ++ s ->
  FTripC c K (expand (map gdecode cols) ++ sdec s f) p q ->
  wconf [] 0 ((1,S p)::q) = wconf [] 0 (sdec sfx f2) ->
  (1 <= V)%N ->
  expand (map gdecode mid) = pair_runs 4 2 (N.to_nat V - 1)%nat ->
  sound_impl_c (cx (K + 10 * a + 10 * m + 14 * V + 40)%N)
    ((2,2,a)%N :: (5,2,1)%N :: (3,2,m)%N :: (3,3,1)%N
       :: (4,2,V)%N :: rest') f
    ([(2,2,(a+1))%N; (4,1,1)%N; (3,1,1)%N; (4,1,m)%N; (8,2,1)%N]
       ++ mid ++ sfx) f2.
Proof.
  intros EREST HF2 EQi HV Emid.
  unfold sound_impl_c.
  change (sdecode ?x ?y) with (sdec x y).
  assert (HVn : N.to_nat V = S (N.to_nat V - 1)%nat).
  { assert (HP : (1 <= N.to_nat V)%nat) by lia. lia. }
  assert (EIN : sdec ((2,2,a)%N :: (5,2,1)%N :: (3,2,m)%N :: (3,3,1)%N
                        :: (4,2,V)%N :: rest') f
                = uword (repeat 0%nat (N.to_nat a)
                           ++ (3 + 0)%nat :: repeat 1%nat (N.to_nat m))
                    ((1,3%nat)::(0,3%nat)::(1,4%nat)::(0,2%nat)
                       :: uword (repeat 2%nat (N.to_nat V - 1))
                            (expand (map gdecode cols)
                               ++ sdec s f))).
  { rewrite uword_app, Front_uword_zeros.
    cbn [uword repeat app].
    rewrite uword_repeat_w.
    rewrite uword_repeat_w.
    rewrite sdec_cons, sdec_cons, sdec_cons, sdec_cons, sdec_cons.
    rewrite EREST.
    rewrite sdec_app.
    change (N.to_nat 2) with 2%nat.
    change (N.to_nat 5) with 5%nat.
    change (N.to_nat 3) with 3%nat.
    change (N.to_nat 4) with 4%nat.
    change (N.to_nat 1) with 1%nat.
    cbn [pair_runs app].
    change ((2 + (3 + 0))%nat) with 5%nat.
    change ((2 + 1)%nat) with 3%nat.
    change ((2 + 2)%nat) with 4%nat.
    rewrite HVn at 1.
    cbn [pair_runs app].
    rewrite <- ?app_assoc.
    reflexivity. }
  rewrite EIN.
  pose proof (FTripC_chainphase c K _ p q
                (repeat 0%nat (N.to_nat a)) 0%nat (N.to_nat m)
                (repeat 2%nat (N.to_nat V - 1)) HF2) as HS2.
  replace (K + 10 * a + 10 * m + 14 * V + 40)%N
    with (K + csuml cpair (repeat 0%nat (N.to_nat a))
          + csuml cpair (repeat 2%nat (N.to_nat V - 1))
          + 2 * N.of_nat 0 + 10 * N.of_nat (N.to_nat m) + 54)%N.
  2:{ rewrite !csuml_repeat. unfold cpair.
      change (N.of_nat 0) with 0%N.
      rewrite !N2Nat.id.
      rewrite Nat2N.inj_sub, N2Nat.id.
      change (N.of_nat 1) with 1%N.
      change (N.of_nat 2) with 2%N.
      lia. }
  refine (creach_tgt_eq _ _ _ _ _ (creach_of_wrunc _ _ _ _ _ _ HS2)).
  assert (EA1 : N.to_nat (a + 1)%N = S (N.to_nat a))
    by (rewrite N2Nat.inj_add; change (N.to_nat 1) with 1%nat; lia).
  assert (EOUTW :
    sdec ([(2,2,(a+1))%N; (4,1,1)%N; (3,1,1)%N; (4,1,m)%N; (8,2,1)%N]
            ++ mid ++ sfx) f2
    = (1,2%nat)::(0,2%nat) :: pair_runs 2 2 (N.to_nat a)
      ++ (1,4%nat)::(0,1%nat)::(1,3%nat)::(0,1%nat)
      :: pair_runs 4 1 (N.to_nat m)
      ++ (1,8%nat)::(0,2%nat)
      :: pair_runs 4 2 (N.to_nat V - 1)%nat ++ sdec sfx f2).
  { rewrite !sdec_app, Emid.
    cbn [map gdecode expand].
    rewrite EA1.
    change (N.to_nat 2) with 2%nat. change (N.to_nat 4) with 4%nat.
    change (N.to_nat 3) with 3%nat. change (N.to_nat 1) with 1%nat.
    change (N.to_nat 8) with 8%nat.
    cbn [pair_runs].
    rewrite ?app_nil_r, <- ?app_assoc.
    reflexivity. }
  rewrite EOUTW.
  cbn [wconf'].
  rewrite pair_runs'_eq.
  cbn [uword].
  rewrite Front_uword_zeros, uword_repeat_w.
  change ((4 + 0)%nat) with 4%nat.
  change ((2 + 2)%nat) with 4%nat.
  rewrite <- ?app_assoc.
  repeat (first [exact EQi
                | apply wconf_app_cong
                | apply wconf_cons_cong]).
Qed.
Lemma pair_of_fst_snd {A B : Type} (x : (A * B)%type) (u : A) (v : B) :
  fst x = u -> snd x = v -> x = (u, v).
Proof. intros <- <-. apply surjective_pairing. Qed.
Lemma not_cempty_cadd_cx_l (K : N) (d : cost) :
  ~ cempty d -> ~ cempty (cadd (cx K) d).
Proof. unfold cempty, cadd, cx, clo, chi; cbn [fst snd]. lia. Qed.
Lemma clo_cadd_cx_l (K : N) (d : cost) :
  (clo (cadd (cx K) d) = K + clo d)%N.
Proof. unfold cadd, cx, clo; cbn [fst snd]. lia. Qed.
Lemma fr_span2A_sound_c (w : word) (f : N) (w2 : word) (f2 : N) :
  fr_span2A w f = Some (ROk w2 f2) ->
  cempty (d_span2A w f)
  \/ sound_impl_c (d_span2A w f) w f w2 f2.
Proof.
  intros E. unfold fr_span2A in E.
  destruct w as [|[[o1 z1] c1] w1]; [discriminate E|].
  destruct w1 as [|[[o2 z2] c2] wb]; [killmN E|].
  destruct wb as [|[[o3 z3] c3] wc]; [killmN E|].
  destruct wc as [|[[o4 z4] c4] wd]; [killmN E|].
  destruct wd as [|[[o5 z5] c5] we]; [killmN E|].
  killmN E.
  unfold o_ in E. injection E as E'.
  unfold span2_core in E'.
  destruct we as [|g6 wf]; [discriminate E'|].
  cbn [d_span2A].
  cbn [N.eqb Pos.eqb andb] in E' |- *.
  destruct (1 <=? c5)%N eqn:EVb; [|discriminate E'].
  pose proof EVb as EV. apply N.leb_le in EV.
  destruct (seek (g6 :: wf)) as [cols s] eqn:ESK.
  destruct (seek_split (g6 :: wf) cols s ESK) as (EREST & HCOLS).
  assert (Emid : expand (map gdecode
                   (if (1 <? c5)%N then [(4,2,(c5-1))%N] else []))
                 = pair_runs 4 2 (N.to_nat c5 - 1)%nat).
  { destruct (1 <? c5)%N eqn:EL.
    - apply N.ltb_lt in EL.
      assert (EM : N.to_nat (c5-1)%N = (N.to_nat c5 - 1)%nat)
        by (rewrite N2Nat.inj_sub; change (N.to_nat 1) with 1%nat; lia).
      cbn [map gdecode expand].
      rewrite EM.
      change (N.to_nat 4) with 4%nat. change (N.to_nat 2) with 2%nat.
      rewrite app_nil_r. reflexivity.
    - apply N.ltb_ge in EL.
      assert (EC : c5 = 1%N) by lia. subst c5.
      cbn [map expand]. cbn [pair_runs]. reflexivity. }
  pose proof (ccolcost_wcolcost cols) as EWC.
  destruct s as [|[[oR zR] cR] tR]; [discriminate E'|].
  destruct zR as [|zp]; [discriminate E'|].
  destruct zp as [zp'|zp'|].
  -
    destruct zp' as [q|q|]; try discriminate E'.
    destruct cR as [|cp]; [discriminate E'|].
    destruct cp as [cp'|cp'|]; try discriminate E'.
    assert (E2 : (match renew_seg (List.length ((oR,3,1)%N :: tR)) cols
                          ((oR,3,1)%N :: tR) f with
                  | Some (bd, gg) => ROk (([(2,2,(c1+1))%N; (4,1,1)%N; (3,1,1)%N; (4,1,c3)%N; (8,2,1)%N]
                    ++ (if (1 <? c5)%N then [(4,2,(c5-1))%N] else [])) ++ bd) gg
                  | None =>
                      match fire_comp (List.length ((oR,3,1)%N :: tR))
                              ((oR,3,1)%N :: tR) f with
                      | Some (s2, gg) => ROk (([(2,2,(c1+1))%N; (4,1,1)%N; (3,1,1)%N; (4,1,c3)%N; (8,2,1)%N]
                    ++ (if (1 <? c5)%N then [(4,2,(c5-1))%N] else [])) ++ cols ++ s2) gg
                      | None => RBad
                      end
                  end) = ROk w2 f2) by exact E'.
    clear E'.
    match goal with
    | |- context [ fst (crenew_seg ?a ?b ?c ?d) ] =>
        destruct (fst (crenew_seg a b c d)) as [[bb gg]|] eqn:ERSC
    end.
    {
      assert (ERS : renew_seg (List.length ((oR,3,1)%N :: tR)) cols
                      ((oR,3,1)%N :: tR) f = Some (bb, gg))
        by (rewrite <- ERSC; symmetry; apply crenew_seg_proj).
      rewrite ERS in E2. injection E2 as <- <-.
      match goal with
      | |- context [ snd (crenew_seg ?a ?b ?c ?d) ] =>
          set (dl := snd (crenew_seg a b c d))
      end.
      destruct (cempty_dec dl) as [HE|HE];
        [left; apply cempty_cadd_cx_l; exact HE|]. right.
      pose proof (cin_of_not_cempty dl HE) as Hk.
      assert (ESP : crenew_seg (List.length ((oR,3,1)%N :: tR)) cols
                      ((oR,3,1)%N :: tR) f = (Some (bb, gg), dl))
        by (apply pair_of_fst_snd; [exact ERSC | unfold dl; reflexivity]).
      destruct (renew_ftripc leaf_ftripC _ cols _ f bb gg dl _ HCOLS ESP Hk)
        as (ci & pi & qi & HFi & EQi).
      apply (creach_of_clo _ _ _ (not_cempty_cadd_cx_l _ _ HE)).
      rewrite clo_cadd_cx_l.
      refine (creach_cx_eq _ _ _ _ _
                (span2A_ftrip_soundc c1 c3 c5 (g6 :: wf) cols
                   ((oR,3,1)%N :: tR) bb _ f gg ci pi
                   (N.of_nat (N.to_nat (clo dl))) qi
                   EREST _ EQi EV Emid)).
      2:{ rewrite <- sdec_app. exact HFi. }
      rewrite N2Nat.id. lia. }
    assert (ERS : renew_seg (List.length ((oR,3,1)%N :: tR)) cols
                    ((oR,3,1)%N :: tR) f = None)
      by (rewrite <- ERSC; symmetry; apply crenew_seg_proj).
    rewrite ERS in E2.
    match goal with
    | |- context [ fst (cfire_comp ?a ?b ?c) ] =>
        destruct (fst (cfire_comp a b c)) as [[s2 gg]|] eqn:EFCC
    end; [|discriminate E2 ||
           (assert (EFC : fire_comp (List.length ((oR,3,1)%N :: tR))
                            ((oR,3,1)%N :: tR) f = None)
              by (rewrite <- cfire_comp_proj; exact EFCC);
            rewrite EFC in E2; discriminate E2)].
    assert (EFC : fire_comp (List.length ((oR,3,1)%N :: tR))
                    ((oR,3,1)%N :: tR) f = Some (s2, gg))
      by (rewrite <- EFCC; symmetry; apply cfire_comp_proj).
    rewrite EFC in E2. injection E2 as <- <-.
    match goal with
    | |- context [ snd (cfire_comp ?a ?b ?c) ] =>
        set (dl := snd (cfire_comp a b c))
    end.
    destruct (cempty_dec dl) as [HE|HE];
      [left; apply cempty_cadd_cx_l; exact HE|]. right.
    pose proof (cin_of_not_cempty dl HE) as Hk.
    assert (ESP : cfire_comp (List.length ((oR,3,1)%N :: tR))
                    ((oR,3,1)%N :: tR) f = (Some (s2, gg), dl))
      by (apply pair_of_fst_snd; [exact EFCC | unfold dl; reflexivity]).
    destruct (fire_comp_ftripc leaf_ftripC _ _ f s2 gg dl _ ESP Hk)
      as (ci & pi & qi & HFi & EQi).
    destruct (FTripC_cols cols ci _ _ pi qi HCOLS HFi)
      as (cL & pL & qL & HFL & EQL).
    apply (creach_of_clo _ _ _ (not_cempty_cadd_cx_l _ _ HE)).
    rewrite clo_cadd_cx_l.
    refine (creach_cx_eq _ _ _ _ _
              (span2A_ftrip_soundc c1 c3 c5 (g6 :: wf) cols
                 ((oR,3,1)%N :: tR) (cols ++ s2) _ f gg cL pL
                 (N.of_nat (N.to_nat (clo dl)) + wcolcost cols)%N qL
                 EREST HFL _ EV Emid)).
    2:{ rewrite EQL, sdec_app. apply wconf_app_cong. exact EQi. }
    rewrite N2Nat.id. lia.
  -
    discriminate E'.
  -
    assert (E2 : (match leaf_act ((oR,1,cR)%N :: tR) f with
                  | Some (s2, gg) => ROk (([(2,2,(c1+1))%N; (4,1,1)%N; (3,1,1)%N; (4,1,c3)%N; (8,2,1)%N]
                    ++ (if (1 <? c5)%N then [(4,2,(c5-1))%N] else [])) ++ cols ++ s2) gg
                  | None => RBad
                  end) = ROk w2 f2) by exact E'.
    clear E'.
    match goal with
    | |- context [ fst (cleaf_act ?a ?b) ] =>
        destruct (fst (cleaf_act a b)) as [[s2 gg]|] eqn:ELAC
    end;
      [ assert (ELA : leaf_act ((oR,1,cR)%N :: tR) f = Some (s2, gg))
          by (rewrite <- ELAC; symmetry; apply cleaf_act_proj)
      | assert (ELA : leaf_act ((oR,1,cR)%N :: tR) f = None)
          by (rewrite <- ELAC; symmetry; apply cleaf_act_proj) ];
      rewrite ELA in E2; [|discriminate E2].
    injection E2 as <- <-.
    match goal with
    | |- context [ snd (cleaf_act ?a ?b) ] => set (dl := snd (cleaf_act a b))
    end.
    destruct (cempty_dec dl) as [HE|HE];
      [left; apply cempty_cadd_cx_l; exact HE|]. right.
    pose proof (cin_of_not_cempty dl HE) as Hk.
    assert (ESP : cleaf_act ((oR,1,cR)%N :: tR) f = (Some (s2, gg), dl))
      by (apply pair_of_fst_snd; [exact ELAC | unfold dl; reflexivity]).
    destruct (leaf_ftripC _ f s2 gg dl _ ESP Hk)
      as [(ci & pi & qi & Ki & EKi & HFi & EQi)
         |(ci & pi & qi & Ki & EKi & HSi & EQq & HSL & _)];
      [|cbn in HSL; discriminate HSL].
    destruct (FTripC_cols cols ci Ki _ pi qi HCOLS HFi)
      as (cL & pL & qL & HFL & EQL).
    apply (creach_of_clo _ _ _ (not_cempty_cadd_cx_l _ _ HE)).
    rewrite clo_cadd_cx_l.
    refine (creach_cx_eq _ _ _ _ _
              (span2A_ftrip_soundc c1 c3 c5 (g6 :: wf) cols
                 ((oR,1,cR)%N :: tR) (cols ++ s2) _ f gg cL pL
                 (Ki + wcolcost cols)%N qL
                 EREST HFL _ EV Emid)).
    2:{ rewrite EQL, sdec_app. apply wconf_app_cong. exact EQi. }
    rewrite N2Nat.id in EKi. rewrite EKi. lia.
Qed.
Corollary cfr_span2A_sound (w : word) (f : N) (w2 : word)
          (f2 : N) (d : cost) :
  cfr_span2A w f = Some (ROk w2 f2, d) ->
  cempty d \/ sound_impl_c d w f w2 f2.
Proof. apply (decorate_sound_disj _ _ fr_span2A_sound_c). Qed.
Lemma ddeep_in4c (l r : wside) :
  zheaded l ->
  wrunc 2 l 0 ((1,4%nat) :: (0,3%nat) :: (1,4%nat) :: (0,2%nat) :: r)
  = Some (((0,1%nat) :: (1,6%nat) :: (0,1%nat) :: (1,2%nat) :: (0,1%nat)
             :: (1,2%nat) :: l, 0, r), 15%N).
Proof.
  intros H.
  apply (ccost_pin _ _ _ _ _ _ (ddeep_in4 l r H)).
  destruct l as [|[b n] t].
  - eexists. ckerc.
  - destruct b; [|discriminate H]. eexists. ckerc.
Qed.
Lemma ddeep_mint4c (Z r : wside) (n : nat) :
  wrunc 3 ((1,1%nat) :: (0,1%nat) :: (1,6%nat) :: (0,1%nat) :: (1,2%nat)
             :: (0,1%nat) :: (1,2%nat) :: Z) 1 ((1,S n) :: r)
  = Some (((0,1%nat) :: (1,2%nat) :: Z, 1,
           (0,1%nat) :: (1,8%nat) :: (0,2%nat) :: (1,S n) :: r), 15%N).
Proof.
  apply (ccost_pin _ _ _ _ _ _ (ddeep_mint4 Z r n)).
  eexists. ckerc.
Qed.
Lemma ddeep_mint4_uc (Z : wside) (ns : list nat) (n : nat) (r : wside) :
  wrunc 3 ((1,1%nat) :: (0,1%nat) :: (1,6%nat) :: (0,1%nat) :: (1,2%nat)
             :: (0,1%nat) :: (1,2%nat) :: Z) 1 (uword ns ((1, S n) :: r))
  = Some (((0,1%nat) :: (1,2%nat) :: Z, 1,
           (0,1%nat) :: (1,8%nat) :: (0,2%nat) :: uword ns ((1, S n) :: r)),
          15%N).
Proof.
  destruct (uword_one_headed ns n r) as (p & q & E).
  rewrite E. exact (ddeep_mint4c Z q p).
Qed.
Lemma ddeep_mint4_sandc (Z r : wside) (n : nat) :
  wrunc 2 ((0,1%nat) :: (1,6%nat) :: (0,1%nat) :: (1,2%nat)
             :: (0,1%nat) :: (1,2%nat) :: Z) 1 ((0,1%nat) :: (1,S n) :: r)
  = Some (((0,1%nat) :: (1,2%nat) :: Z, 1,
           (0,1%nat) :: (1,8%nat) :: (0,2%nat) :: (1,S n) :: r), 12%N).
Proof.
  apply (ccost_pin _ _ _ _ _ _ (ddeep_mint4_sand Z r n)).
  eexists. ckerc.
Qed.
Lemma ddeep_entry4c (T r : wside) (z : nat) :
  wrunc 1 ((0,1%nat) :: (1,2%nat) :: (0,2%nat) :: (1,2%nat) :: T) 1
         ((0,S z) :: r)
  = Some (((1,2%nat) :: T, 0, (1,4%nat) :: (0,S (S z)) :: r), 5%N).
Proof.
  apply (ccost_pin _ _ _ _ _ _ (ddeep_entry4 T r z)).
  eexists. ckerc.
Qed.
Lemma wcross1c (m : nat) (l r : wside) :
  wrunc 1 l 0 ((1, (2 + m)%nat)::(0,2%nat)::r)
  = Some ((vpush m l, 0, r), (N.of_nat m + 4)%N).
Proof.
  apply (ccost_pin _ _ _ _ _ _ (wcross1 m l r)).
  destruct m as [|m']; eexists; ckerc.
Qed.
Lemma ddeep_redigc (Z r : wside) (n : nat) :
