Lemma ddeep_redig_uc (Z : wside) (ks : list nat) (n : nat) (r0 : wside) :
  wrunc 3 ((1,1%nat) :: (0,1%nat) :: (1,2%nat) :: (0,1%nat) :: (1,4%nat) :: Z)
         1 (uword ks ((1, S n) :: r0))
  = Some (((0,1%nat) :: (1,3%nat) :: Z, 1,
