Lemma ddeep_fin4c (T r : wside) (n : nat) :
  wrunc 1 ((0,1%nat) :: (1,3%nat) :: (0,2%nat) :: (1,2%nat) :: T) 1
         ((1,S n) :: r)
  = Some (((1,2%nat) :: T, 0, (1,5%nat) :: (0,1%nat) :: (1,S n) :: r), 6%N).
