Lemma dm4_half_stepc (z : nat) (Z : wside) (p : nat) (q : wside) :
  wrunc 2 (vpairC 2 ((0,1%nat) :: (1,S z) :: Z)) 1 ((0,1%nat) :: (1,S p) :: q)
  = Some (((0,1%nat) :: (1,S z) :: Z, 1,
           (0,1%nat) :: (1,4%nat) :: (0,2%nat) :: (1,S p) :: q), 8%N).
Proof.
  apply (ccost_pin _ _ _ _ _ _ (dm4_half_step z Z p q)).
  eexists. ckerc.
Qed.
Lemma dm4_halfc (j : nat) (z : nat) (Z : wside) (p : nat) (q : wside) :
  wrunc (2 * j) (vstackC (repeat 2%nat j) ((0,1%nat) :: (1,S z) :: Z)) 1
        ((0,1%nat) :: (1,S p) :: q)
  = Some (((0,1%nat) :: (1,S z) :: Z, 1,
           (0,1%nat) :: uword (repeat 2%nat j) ((1,S p) :: q)),
          (8 * N.of_nat j)%N).
Proof.
  gen p q. induction j as [|j IH]; intros p q.
  - cbn [repeat vstackC uword]. change (2 * 0)%nat with 0%nat.
    rewrite wrunc_0. change (N.of_nat 0) with 0%N. ccost_close.
  - replace (2 * S j)%nat with (2 + 2 * j)%nat by lia.
    destruct j as [|j''].
    + erewrite wrunc_split by apply (dm4_half_stepc z Z p q).
      change (2 * 0)%nat with 0%nat. rewrite wrunc_0.
      reflexivity.
    + erewrite wrunc_split
        by apply (dm4_half_stepc 1
             ((0,1%nat) :: (1,2%nat)
                :: vstackC (repeat 2%nat j'') ((0,1%nat) :: (1,S z) :: Z))
             p q).
      change ((0, 1%nat) :: (1, S 1) :: (0, 1%nat) :: (1, 2%nat)
                :: vstackC (repeat 2%nat j'') ((0,1%nat) :: (1,S z) :: Z))
        with (vstackC (repeat 2%nat (S j'')) ((0,1%nat) :: (1,S z) :: Z)).
      rewrite (IH 3 ((0,2%nat) :: (1,S p) :: q)).
      cbn [uword repeat].
      rewrite uword_repeat2_shift.
      rewrite Nat2N.inj_succ. ccost_close.
Qed.
Lemma ccycc (a b : nat) (T R : wside) :
  wrunc 4 ((1,2%nat)::(0,2%nat)::T) 0
        ((1,S (S (S a)))::(0,1%nat)::(1,S (S b))::R)
  = Some ((T, 0,
           (1,5%nat)::(0,1%nat)::(1,(a+2)%nat)::(0,1%nat)::(1,S b)::R),
          (2 * N.of_nat a + 20)%N).
Proof.
  apply (ccost_pin _ _ _ _ _ _ (ccyc a b T R)).
  destruct a as [|a']; eexists; ckerc.
Qed.
Lemma cfinc (a b : nat) (R : wside) :
  wrunc 4 ((1,2%nat)::nil) 0
        ((1,S (S (S a)))::(0,1%nat)::(1,S (S b))::R)
  = Some (([], 0,
           (1,5%nat)::(0,1%nat)::(1,(a+2)%nat)::(0,1%nat)::(1,S b)::R),
          (2 * N.of_nat a + 20)%N).
Proof.
  apply (ccost_pin _ _ _ _ _ _ (cfin a b R)).
  destruct a as [|a']; eexists; ckerc.
Qed.
Lemma ccyc_chainc (j a b : nat) (R : wside) :
  wrunc (4 * j + 4) ((1,2%nat)::vstackC (zeros j) []) 0
        ((1,S (S (S a)))::(0,1%nat)::(1,S (S b))::R)
  = Some (([], 0, cdesc j a b R),
          (2 * N.of_nat a + 24 * N.of_nat j + 20)%N).
Proof.
  gen a b R. induction j as [|j IH]; intros a b R.
  - cbn [zeros vstackC cdesc]. rewrite cfinc.
    change (N.of_nat 0) with 0%N. ccost_close.
  - cbn [zeros vstackC vpairC cdesc].
    replace (4 * S j + 4)%nat with (4 + (4 * j + 4))%nat by lia.
    rewrite wrunc_add, ccycc.
    lazy beta iota.
    replace ((a + 2)%nat) with (S (S a)) by lia.
    rewrite IH.
    change (N.of_nat 2) with 2%N.
    rewrite Nat2N.inj_succ. ccost_close.
Qed.
Lemma dg_half1c (L : list nat) (c : nat)
      (c1 : nat) (K1 : N) (Win : wside) (p1 : nat) (q1 : wside) :
  FTripC c1 K1 Win p1 q1 ->
  wrunc (List.length L + 3 * c + c1 + 8)%nat [] 0
       (uword (L ++ 0%nat :: repeat 2%nat c)
          ((1,4%nat)::(0,3%nat)::(1,4%nat)::(0,2%nat) :: Win))
  = Some ((dgmid (rev L), 0,
           uword (repeat 2%nat c ++ [6%nat]) ((1,S p1)::q1)),
          (csuml ccross L + 14 * N.of_nat c + 45 + K1)%N).
Proof.
  intros HT.
  apply (ccost_pin _ _ _ _ _ _
           (dg_half1 L c c1 Win p1 q1 (FTripC_FTrip _ _ _ _ _ HT))).
  eexists.
  replace (List.length L + 3 * c + c1 + 8)%nat
    with (List.length (L ++ 0%nat :: repeat 2%nat c)
          + (2 + (c1 + (3 + (2 * c + (1 + (1 + 0)))))))%nat
    by (rewrite length_app; cbn [List.length];
        rewrite repeat_length; lia).
  rewrite wrunc_add, wcross_mixedc.
  lazy beta iota.
  rewrite (vstack_vstackC _ [] I).
  rewrite rev_app_distr.
  cbn [rev].
  rewrite rev_repeat, <- app_assoc.
  cbn [app].
  rewrite vstackC_app.
  erewrite wrunc_split
    by (apply ddeep_in4c; apply vstackC_zheaded; apply vstackC_zheaded;
        exact I).
  rewrite wrunc_add.
  rewrite (HT 0%nat 5%nat ((0,1%nat)::(1,2%nat)::(0,1%nat)::(1,2%nat)
                             :: vstackC (repeat 2%nat c)
                                  (vstackC (0%nat :: rev L) []))).
  lazy beta iota.
  erewrite wrunc_split by apply (ddeep_mint4_uc _ []).
  rewrite (wrunc_add (2 * c)).
  rewrite hshift.
  cbn [vstackC vpairC].
  rewrite (dm4_halfc c 1).
  lazy beta iota.
  erewrite wrunc_split by apply ddeep_entry4c.
  erewrite wrunc_split by apply (wcross1c 2).
  rewrite wrunc_0.
  lazy beta iota.
  rewrite (csuml_app ccross L (0%nat :: repeat 2%nat c)).
  cbn [csuml].
  rewrite (csuml_repeat ccross 2%nat c).
  change (ccross 0%nat) with 4%N.
  change (ccross 2%nat) with 6%N.
  ccost_close.
Qed.
Lemma dg_half1_sandc (L : list nat) (c : nat)
      (cS : nat) (KS : N) (Win : wside) (pS : nat) (qS : wside) :
  SandC cS KS Win ((1,S pS)::qS) ->
  wrunc (List.length L + 3 * c + cS + 7)%nat [] 0
       (uword (L ++ 0%nat :: repeat 2%nat c)
          ((1,4%nat)::(0,3%nat)::(1,4%nat)::(0,2%nat) :: Win))
  = Some ((dgmid (rev L), 0,
           uword (repeat 2%nat c ++ [6%nat]) ((1,S pS)::qS)),
          (csuml ccross L + 14 * N.of_nat c + 42 + KS)%N).
Proof.
  intros HS.
  apply (ccost_pin _ _ _ _ _ _
           (dg_half1_sand L c cS Win pS qS (SandC_Sand _ _ _ _ HS))).
  eexists.
  replace (List.length L + 3 * c + cS + 7)%nat
    with (List.length (L ++ 0%nat :: repeat 2%nat c)
          + (2 + (cS + (2 + (2 * c + (1 + (1 + 0)))))))%nat
    by (rewrite length_app; cbn [List.length];
        rewrite repeat_length; lia).
  rewrite wrunc_add, wcross_mixedc.
  lazy beta iota.
  rewrite (vstack_vstackC _ [] I).
  rewrite rev_app_distr.
  cbn [rev].
  rewrite rev_repeat, <- app_assoc.
  cbn [app].
  rewrite vstackC_app.
  erewrite wrunc_split
    by (apply ddeep_in4c; apply vstackC_zheaded; apply vstackC_zheaded;
        exact I).
  rewrite wrunc_add.
  rewrite (HS 5%nat ((0,1%nat)::(1,2%nat)::(0,1%nat)::(1,2%nat)
                       :: vstackC (repeat 2%nat c)
                            (vstackC (0%nat :: rev L) []))).
  lazy beta iota.
  erewrite wrunc_split by apply ddeep_mint4_sandc.
  rewrite (wrunc_add (2 * c)).
  rewrite hshift.
  cbn [vstackC vpairC].
  rewrite (dm4_halfc c 1).
  lazy beta iota.
  erewrite wrunc_split by apply ddeep_entry4c.
  erewrite wrunc_split by apply (wcross1c 2).
  rewrite wrunc_0.
  lazy beta iota.
  rewrite (csuml_app ccross L (0%nat :: repeat 2%nat c)).
  cbn [csuml].
  rewrite (csuml_repeat ccross 2%nat c).
  change (ccross 0%nat) with 4%N.
  change (ccross 2%nat) with 6%N.
  ccost_close.
Qed.
Lemma d4_half1c (c1 : nat) (K1 : N) (Win : wside) (p1 : nat) (q1 : wside)
      (k c : nat) :
  FTripC c1 K1 Win p1 q1 ->
  wrunc (k + 3 * c + c1 + 9)%nat [] 0
       (uword (zeros (S (S k)) ++ repeat 2%nat c)
          ((1,4%nat)::(0,3%nat)::(1,4%nat)::(0,2%nat) :: Win))
  = Some ((d4mid k, 0, uword (repeat 2%nat c ++ [6%nat]) ((1,S p1)::q1)),
          (4 * N.of_nat k + 14 * N.of_nat c + 49 + K1)%N).
Proof.
  intros HT.
  rewrite <- (zeros_front k c).
  replace (k + 3 * c + c1 + 9)%nat
    with (List.length (zeros (S k)) + 3 * c + c1 + 8)%nat
    by (rewrite length_zeros; lia).
  rewrite (dg_half1c (zeros (S k)) c c1 K1 Win p1 q1 HT).
  rewrite rev_zeros, dgmid_zeros.
  rewrite (csuml_zeros ccross (S k)).
  change (ccross 0%nat) with 4%N.
  rewrite Nat2N.inj_succ.
  ccost_close.
Qed.
