Lemma d4_half2_genc (c2 : nat) (K2 : N) (U : wside) (p2 : nat) (q2 : wside)
      (k : nat) :
  FTripC c2 K2 U p2 q2 ->
  wrunc (4 * k + c2 + 8)%nat (d4mid k) 0 U
  = Some (([], 0, cdesc k 2 1 ((0,2%nat) :: (1,S p2)::q2)),
          (K2 + 24 * N.of_nat k + 43)%N).
Proof.
  intros HT.
  apply (ccost_pin _ _ _ _ _ _
           (d4_half2_gen c2 U p2 q2 k (FTripC_FTrip _ _ _ _ _ HT))).
  eexists.
  replace (4 * k + c2 + 8)%nat with (c2 + (3 + (1 + (4 * k + 4))))%nat by lia.
  unfold d4mid.
  rewrite wrunc_add.
  rewrite (HT 0%nat 1%nat ((0,1%nat)::(1,4%nat)::(0,2%nat)::(1,2%nat)
                             :: vstackC (zeros k) [])).
  lazy beta iota.
  erewrite wrunc_split by apply (ddeep_redig_uc _ []).
  erewrite wrunc_split by apply ddeep_fin4c.
  rewrite (ccyc_chainc k 2 1).
  change (N.of_nat 2) with 2%N.
  ccost_close.
Qed.
