Lemma m4_wallsc (g : nat) (y : nat) (Z : wside) :
  wrunc (4 + 3 * g)%nat ((0,1%nat)::(1,S (S y))::Z) 0
       (uword (repeat 2%nat g) [(1,4%nat)])
  = Some ((((1,S y)::Z, 1,
            uword (repeat 2%nat g) [(1,4%nat); (0,2%nat); (1,4%nat)])),
          (14 * N.of_nat g + 20)%N).
Proof.
  revert y Z. induction g as [|g IH]; intros y Z.
  - cbn [repeat uword]. change (4 + 3 * 0)%nat with 4%nat.
    rewrite (m4_barec y Z).
    change (N.of_nat 0) with 0%N. ccost_close.
  - cbn [repeat uword].
    replace (4 + 3 * S g)%nat with (1 + ((4 + 3 * g) + 2))%nat by lia.
    erewrite wrunc_split
      by exact (m4_crossc y Z (uword (repeat 2%nat g) [(1,4%nat)])).
    erewrite wrunc_split
      by exact (IH 0%nat ((0,1%nat)::(1,2%nat)::(0,1%nat)::(1,S (S y))::Z)).
    destruct (uword_one_headed (repeat 2%nat g) 3%nat
                [(0,2%nat); (1,4%nat)]) as (p & q & E).
    change (uword (repeat 2%nat g) [(1,4%nat); (0,2%nat); (1,4%nat)])
      with (uword (repeat 2%nat g) ((1,S 3%nat) :: [(0,2%nat); (1,4%nat)])).
    rewrite E.
    rewrite (m4_retc y p Z q).
    rewrite Nat2N.inj_succ. ccost_close.
Qed.
Lemma d4_margin4c (g : nat) (L : wside) :
  wrunc (7 + 3 * g)%nat
       ((0,1%nat)::(1,6%nat)::(0,1%nat)::(1,2%nat)::(0,1%nat)::(1,2%nat)::L)
       0 (uword (repeat 2%nat g) [(1,4%nat)])
  = Some ((((0,1%nat)::(1,2%nat)::L, 1,
            (0,1%nat)::(1,7%nat)::(0,1%nat)::(1,3%nat)::(0,2%nat)
              :: uword (repeat 2%nat g) [(1,4%nat)])),
          (14 * N.of_nat g + 36)%N).
Proof.
  replace (7 + 3 * g)%nat with ((4 + 3 * g) + 3)%nat by lia.
  change (1,6%nat) with (1, S (S 4%nat)).
  erewrite wrunc_split
    by exact (m4_wallsc g 4%nat
                ((0,1%nat)::(1,2%nat)::(0,1%nat)::(1,2%nat)::L)).
  change [(1,4%nat); (0,2%nat); (1,4%nat)]
    with ((1,4%nat) :: (0,2%nat) :: [(1,4%nat)]).
  rewrite uword_repeat2_shift.
  rewrite (m4_mintc L (uword (repeat 2%nat g) [(1,4%nat)])).
  ccost_close.
Qed.
Lemma d4_half1_m4c (k c g : nat) :
  wrunc (k + 3 * c + 3 * g + 13)%nat [] 0
       (uword (zeros (S (S k)) ++ repeat 2%nat c)
          ((1,4%nat)::(0,3%nat)::(1,4%nat)::(0,2%nat)
             :: uword (repeat 2%nat g) [(1,4%nat)]))
  = Some ((d4mid k, 0,
           uword (repeat 2%nat c)
             ((1,7%nat)::(0,1%nat)::(1,3%nat)::(0,2%nat)
                :: uword (repeat 2%nat g) [(1,4%nat)])),
          (4 * N.of_nat k + 14 * N.of_nat c + 14 * N.of_nat g + 70)%N).
Proof.
  apply (ccost_pin _ _ _ _ _ _ (d4_half1_m4 k c g)).
  eexists.
  replace (k + 3 * c + 3 * g + 13)%nat
    with (List.length (zeros (S (S k)) ++ repeat 2%nat c)
          + (2 + ((7 + 3 * g) + (2 * c + (1 + (1 + 0))))))%nat
    by (rewrite length_app, length_zeros, repeat_length; lia).
  rewrite wrunc_add, wcross_mixedc.
  lazy beta iota.
  rewrite (csuml_app ccross (zeros (S (S k))) (repeat 2%nat c)).
  rewrite (csuml_zeros ccross (S (S k))).
  rewrite (csuml_repeat ccross 2%nat c).
  change (ccross 0%nat) with 4%N.
  change (ccross 2%nat) with 6%N.
  rewrite (vstack_vstackC _ [] I).
  rewrite rev_app_distr, rev_zeros, rev_repeat.
  rewrite vstackC_app.
  erewrite wrunc_split
    by (apply ddeep_in4c; apply vstackC_zheaded; apply vstackC_zheaded;
        exact I).
  rewrite wrunc_add.
  rewrite (d4_margin4c g (vstackC (repeat 2%nat c)
                           (vstackC (zeros (S (S k))) []))).
  lazy beta iota.
  rewrite (wrunc_add (2 * c)).
  rewrite hshift.
  cbn [zeros vstackC vpairC].
  rewrite (dm4_halfc c 1).
  lazy beta iota.
  erewrite wrunc_split by apply ddeep_entry4c.
  erewrite wrunc_split by apply (wcross1c 2).
  rewrite wrunc_0.
  lazy beta iota.
  rewrite !Nat2N.inj_succ.
  ccost_close.
Qed.
Lemma span8_sound_genOc (cN V G : N) (rest t2 out : word) (f f2 f3 : N)
      (c1 p1 : nat) (q1 : wside) (c2 p2 : nat) (q2 : wside)
      (Ke K2 : N) (Y : wside) :
  (2 <= cN)%N -> (1 <= G)%N ->
  ((exists K1 : N, Ke = (K1 + 6)%N
        /\ FTripC c1 K1 (sdec ((4,2,(G-1))%N :: rest) f) p1 q1)
   \/ (exists KS : N, Ke = (KS + 3)%N
        /\ SandC c1 KS (sdec ((4,2,(G-1))%N :: rest) f) ((1,S p1)::q1))) ->
  wconf [] 0 ((1,S p1)::q1) = wconf [] 0 (sdec ((4,2,(G-1))%N :: t2) f2) ->
  FTripC c2 K2 (sdec ((4,2,V)%N :: (8,2,1)%N :: (4,2,(G-1))%N :: t2) f2) p2 q2 ->
  wconf [] 0 ((1,S p2)::q2) = wconf [] 0 Y ->
  sdec out f3 = cdesc (N.to_nat cN - 2)%nat 2 1 ((0,2%nat) :: Y) ->
  sound_impl_c (cx (28 * cN + 14 * V + 30 + Ke + K2)%N)
    ((2,2,cN) :: (4,2,V) :: (4,3,1) :: (4,2,G) :: rest)%N f
    out f3.
Proof.
  intros HN2 HG HF1 EQ1 HF2 EQ2 HOUT.
  set (k := (N.to_nat cN - 2)%nat).
  set (c := N.to_nat V).
  set (g := (N.to_nat G - 1)%nat).
  assert (EcV : N.to_nat V = c) by reflexivity.
  assert (EcN : N.to_nat cN = S (S k)) by (subst k; lia).
  assert (EcN2 : N.to_nat (cN - 2)%N = k) by (subst k; lia).
  assert (EG : N.to_nat G = S g) by (subst g; lia).
  assert (EG1 : N.to_nat (G - 1)%N = g) by (subst g; lia).
  assert (EIN : sdec ((2,2,cN) :: (4,2,V) :: (4,3,1) :: (4,2,G) :: rest)%N f
                = uword (zeros (S (S k)) ++ repeat 2%nat c)
                    ((1,4%nat)::(0,3%nat)::(1,4%nat)::(0,2%nat)
                       :: sdec ((4,2,(G-1))%N :: rest) f)).
  { rewrite uword_app_ms, uword_zeros, uword_repeat_w.
    rewrite !sdec_cons.
    rewrite EcN, EG, EG1.
    change (N.to_nat 2) with 2%nat.
    change (N.to_nat 3) with 3%nat.
    change (N.to_nat 4) with 4%nat.
    change (N.to_nat 1) with 1%nat.
    change (2 + 2)%nat with 4%nat.
    rewrite <- EcV.
    cbn [pair_runs app].
    flatapp. reflexivity. }
  assert (EMID : forall (t : word) (ff : N),
             uword (repeat 2%nat c ++ [6%nat]) (sdec ((4,2,(G-1))%N :: t) ff)
             = sdec ((4,2,V)%N :: (8,2,1)%N :: (4,2,(G-1))%N :: t) ff).
  { intros t ff.
    rewrite uword_app_ms, uword_repeat_w.
    cbn [uword].
    rewrite !sdec_cons.
    change (N.to_nat 2) with 2%nat.
    change (N.to_nat 4) with 4%nat.
    change (N.to_nat 8) with 8%nat.
    change (N.to_nat 1) with 1%nat.
    change (2 + 2)%nat with 4%nat.
    rewrite <- EcV.
    cbn [pair_runs app].
    flatapp. reflexivity. }
  unfold sound_impl_c.
  change (sdecode ?x ?y) with (sdec x y).
  rewrite EIN.
  assert (HL1 : creach (cx (4 * N.of_nat k + 14 * N.of_nat c + 43 + Ke)%N)
                  (wconf [] 0
                     (uword (zeros (S (S k)) ++ repeat 2%nat c)
                        ((1,4%nat)::(0,3%nat)::(1,4%nat)::(0,2%nat)
                           :: sdec ((4,2,(G-1))%N :: rest) f)))
                  (wconf (d4mid k) 0
                     (uword (repeat 2%nat c ++ [6%nat]) ((1,S p1)::q1)))).
  { destruct HF1 as [(K1 & EK & HF)|(KS & EK & HS)].
    - pose proof (creach_of_wrunc _ _ _ _ _ _
                    (d4_half1c c1 K1 _ p1 q1 k c HF)) as CC.
      cbn [wconf'] in CC.
      refine (creach_cx_eq _ _ _ _ _ CC). lia.
    - pose proof (creach_of_wrunc _ _ _ _ _ _
                    (d4_half1_sandc c1 KS _ p1 q1 k c HS)) as CC.
      cbn [wconf'] in CC.
      refine (creach_cx_eq _ _ _ _ _ CC). lia. }
  rewrite (wconf_gen_cong (d4mid k) 0 _ _
             (wconf_uword_cong (repeat 2%nat c ++ [6%nat]) _ _ EQ1)) in HL1.
  rewrite (EMID t2 f2) in HL1.
  pose proof (creach_of_wrunc _ _ _ _ _ _
                (d4_half2_genc c2 K2 _ p2 q2 k HF2)) as HL2.
  cbn [wconf'] in HL2.
  rewrite HOUT.
  refine (creach_tgt_eq _ _ _ _
            (wconf_cdesc_cong k 2 1 _ _
               (wconf_cons_cong (0,2%nat) _ _ EQ2)) _).
  refine (creach_cx_eq _ _ _ _ _ (creach_cx_trans _ _ _ _ _ HL1 HL2)).
  assert (EK : N.of_nat k = (cN - 2)%N)
    by (rewrite <- EcN2, N2Nat.id; reflexivity).
  assert (EC : N.of_nat c = V)
    by (rewrite <- EcV, N2Nat.id; reflexivity).
  rewrite EK, EC. lia.
Qed.
Lemma span8_sound_genc (cN V G : N) (rest t2 t3 : word) (f f2 f3 : N)
      (c1 p1 : nat) (q1 : wside) (c2 p2 : nat) (q2 : wside) (Ke K2 : N) :
  (2 <= cN)%N -> (1 <= G)%N ->
  ((exists K1 : N, Ke = (K1 + 6)%N
        /\ FTripC c1 K1 (sdec ((4,2,(G-1))%N :: rest) f) p1 q1)
   \/ (exists KS : N, Ke = (KS + 3)%N
        /\ SandC c1 KS (sdec ((4,2,(G-1))%N :: rest) f) ((1,S p1)::q1))) ->
  wconf [] 0 ((1,S p1)::q1) = wconf [] 0 (sdec ((4,2,(G-1))%N :: t2) f2) ->
  FTripC c2 K2 (sdec ((4,2,V)%N :: (8,2,1)%N :: (4,2,(G-1))%N :: t2) f2) p2 q2 ->
  wconf [] 0 ((1,S p2)::q2)
    = wconf [] 0 (sdec ((4,2,V)%N :: (8,2,1)%N :: (4,2,(G-1))%N :: t3) f3) ->
  sound_impl_c (cx (28 * cN + 14 * V + 30 + Ke + K2)%N)
    ((2,2,cN) :: (4,2,V) :: (4,3,1) :: (4,2,G) :: rest)%N f
    ([(5,1,1); (4,1,1); (3,1,(cN-2)); (2,2,1); (4,2,V); (8,2,1);
      (4,2,(G-1))]%N ++ t3) f3.
Proof.
  intros HN2 HG HF1 EQ1 HF2 EQ2.
  set (k := (N.to_nat cN - 2)%nat).
  set (g := (N.to_nat G - 1)%nat).
  assert (EcN2 : N.to_nat (cN - 2)%N = k) by (subst k; lia).
  assert (EG1 : N.to_nat (G - 1)%N = g) by (subst g; lia).
  refine (span8_sound_genOc cN V G rest t2 _ f f2 f3 c1 p1 q1 c2 p2 q2
            Ke K2 _ HN2 HG HF1 EQ1 HF2 EQ2 _).
  assert (EOUT : sdec ([(5,1,1); (4,1,1); (3,1,(cN-2)); (2,2,1); (4,2,V);
                        (8,2,1); (4,2,(G-1))]%N ++ t3) f3
                 = cdesc k 2 1
                     ((0,2%nat) :: sdec ((4,2,V)%N :: (8,2,1)%N
                                           :: (4,2,(G-1))%N :: t3) f3)).
  { rewrite (cdesc_group k 0).
    rewrite ?sdec_app, ?sdec_cons.
    cbn [map gdecode expand].
    rewrite EcN2, EG1.
    change (N.to_nat 5) with 5%nat.
    change (N.to_nat 4) with 4%nat.
    change (N.to_nat 3) with 3%nat.
    change (N.to_nat 2) with 2%nat.
    change (N.to_nat 1) with 1%nat.
    change (N.to_nat 8) with 8%nat.
    cbn [pair_runs app].
    flatapp. reflexivity. }
  exact EOUT.
Qed.
Lemma sp1_exc2c (V g y : N) :
  (2 <= y)%N ->
  exists c p q,
    FTripC c (14 * V + 14 * g + 2 * y + 25)%N
      (sdec ((4,2,V) :: (8,2,1) :: (4,2,g) :: [(y,1,1)])%N 3) p q
    /\ (1,S p)::q =
       sdec ((4,2,V) :: (8,2,1) :: (4,2,g) :: [(y,1,1)])%N 2.
Proof.
  intros Hy.
  set (s := (N.to_nat y - 2)%nat).
  assert (Ey : N.to_nat y = (2 + s)%nat) by (unfold s; lia).
  assert (ES : forall ff : N, (1 <= ff)%N ->
            sdec ((4,2,V) :: (8,2,1) :: (4,2,g) :: [(y,1,1)])%N ff
            = pair_runs 4 2 (N.to_nat V)
              ++ pair_runs 8 2 1
              ++ pair_runs 4 2 (N.to_nat g)
              ++ (1,(2+s)%nat)::(0,1%nat)::[(1,N.to_nat ff)]).
  { intros ff Hff. unfold sdec.
    cbn [map gdecode expand].
    rewrite frun_pos by exact Hff.
    rewrite Ey.
    change (N.to_nat 4) with 4%nat.
    change (N.to_nat 8) with 8%nat.
    change (N.to_nat 2) with 2%nat.
    change (N.to_nat 1) with 1%nat.
    cbn [pair_runs]. flatapp. reflexivity. }
  pose proof (FTripC_tick s 1%nat []) as HT.
  cbn [Nat.add] in HT.
  destruct (FTripC_walls2 (N.to_nat g) 2 _ _ _ _ _ HT)
    as (ca & pa & qa & HFa & EQa).
  destruct (FTripC_walls2 1%nat 6 _ _ _ _ _ HFa)
    as (cb & pb & qb & HFb & EQb).
  destruct (FTripC_walls2 (N.to_nat V) 2 _ _ _ _ _ HFb)
    as (cc & pc & qc & HFc & EQc).
  exists cc, pc, qc. split.
  - rewrite (ES 3%N ltac:(lia)).
    change (pair_runs 8 2 1) with (pair_runs (2+6)%nat 2 1).
    change (pair_runs 4 2 (N.to_nat V)) with
      (pair_runs (2+2)%nat 2 (N.to_nat V)).
    change (pair_runs 4 2 (N.to_nat g)) with
      (pair_runs (2+2)%nat 2 (N.to_nat g)).
    change (N.to_nat 3) with 3%nat.
    refine (DebrisLeafC_FTripC_cost_eq _ _ _ _ _ _ _ HFc).
    unfold cpair, s.
    rewrite !N2Nat.id, Nat2N.inj_sub, N2Nat.id.
    change (N.of_nat 2) with 2%N. lia.
  - rewrite EQc, EQb, EQa.
    rewrite (ES 2%N ltac:(lia)).
    change (N.to_nat 2) with 2%nat. reflexivity.
Qed.
Lemma span8g_rest0_farc (cN V G f : N) :
  (2 <= cN)%N -> (1 <= G)%N -> (5 <= f)%N ->
  sound_impl_c
    (cx (28 * cN + 28 * V + 28 * (G-1) + 4 * f + 72)%N)
    ((2,2,cN) :: (4,2,V) :: (4,3,1) :: [(4,2,G)])%N f
    ([(5,1,1); (4,1,1); (3,1,cN-2); (2,2,1); (4,2,V); (8,2,1)]%N
       ++ (if (1 <? G)%N then [(4,2,G-1)]%N else [])
       ++ [(f-1,1,1)]%N) 2%N.
Proof.
  intros HN HG HF.
  assert (HC : forallb (fun g => is_col g && negb (is_cmf g)
                                  && (3 <=? gO g)%N)
                [(4,2,(G-1))%N] = true).
  { cbn [forallb].
    unfold is_col, is_cmf, gO, gZ, gC.
    destruct (((G-1) =? 1)%N); reflexivity. }
  destruct (ren_far_tailc [(4,2,(G-1))%N] f HC HF)
    as (c1 & p1 & q1 & HF1 & EQ1).
  destruct (sp1_exc2c V (G-1)%N (f-1)%N ltac:(lia))
    as (c2 & p2 & q2 & HF2 & EQ2).
  assert (MAIN : sound_impl_c
      (cx (28 * cN + 28 * V + 28 * (G-1) + 4 * f + 72)%N)
      ((2,2,cN) :: (4,2,V) :: (4,3,1) :: [(4,2,G)])%N f
      ([(5,1,1); (4,1,1); (3,1,(cN-2)); (2,2,1); (4,2,V);
         (8,2,1); (4,2,(G-1)); (f-1,1,1)]%N) 2%N).
  { pose proof (span8_sound_genc cN V G [] [(f-1,1,1)]%N
        [(f-1,1,1)]%N f 3 2 c1 p1 q1 c2 p2 q2
        (2*f + 13 + wcolcost [(4,2,(G-1))%N] + 6)%N
        (14*V + 14*(G-1) + 2*(f-1) + 25)%N
        HN HG (or_introl (ex_intro _
          (2*f + 13 + wcolcost [(4,2,(G-1))%N])%N
          (conj eq_refl HF1))) EQ1 HF2) as HS.
    assert (EQ2' : wconf [] 0 ((1,S p2)::q2) =
        wconf [] 0
          (sdec ((4,2,V)%N :: (8,2,1)%N :: (4,2,(G-1))%N
                   :: [(f-1,1,1)%N]) 2)).
    { rewrite EQ2. reflexivity. }
    specialize (HS EQ2').
    unfold sound_impl_c in HS |- *.
    refine (creach_cx_eq _ _ _ _ _ HS).
    cbn [wcolcost gC gO]. lia. }
  destruct ((1 <? G)%N) eqn:EGT.
  - revert MAIN. cbn [app]. exact (fun x => x).
  - assert (EG0 : (G - 1)%N = 0%N).
    { apply N.ltb_ge in EGT. lia. }
    revert MAIN. unfold sound_impl_c.
    rewrite EG0. cbn [app].
    assert (ESD : forall (ff : N),
              sdecode [(5,1,1); (4,1,1); (3,1,(cN-2)); (2,2,1); (4,2,V);
                       (8,2,1); (4,2,0); (f-1,1,1)]%N ff
              = sdecode [(5,1,1); (4,1,1); (3,1,(cN-2)); (2,2,1); (4,2,V);
                         (8,2,1); (f-1,1,1)]%N ff).
    { intros ff. unfold sdecode.
      cbn [map gdecode expand app].
      change (N.to_nat 0) with 0%nat.
      cbn [pair_runs app]. reflexivity. }
    rewrite ESD. exact (fun x => x).
Qed.
Lemma m4_exc2c (V g : N) :
  exists c p q,
    FTripC c (14 * V + 17)%N
      (sdec ((4,2,V) :: (7,1,1) :: (3,2,1) :: [(4,2,g)])%N 4) p q
    /\ (1,S p)::q = sdec ((4,2,V) :: (7,1,1) :: (2,2,1) :: [(4,2,g)])%N 4.
Proof.
  assert (ES : forall o : N, (2 <= o)%N ->
            sdec ((4,2,V) :: (7,1,1) :: (o,2,1) :: [(4,2,g)])%N 4
            = pair_runs 4 2 (N.to_nat V)
              ++ (1,7%nat)::(0,1%nat)::(1,N.to_nat o)::(0,2%nat)
                 :: (pair_runs 4 2 (N.to_nat g) ++ [(1,4%nat)])).
  { intros o Ho. unfold sdec.
    cbn [map gdecode expand].
    rewrite frun_pos by lia.
    change (N.to_nat 4) with 4%nat.
    change (N.to_nat 2) with 2%nat.
    change (N.to_nat 7) with 7%nat.
    change (N.to_nat 1) with 1%nat.
    cbn [pair_runs].
    flatapp. reflexivity. }
  pose proof (FTripC_tick 5%nat 1%nat
                ((0,2%nat) :: (pair_runs 4 2 (N.to_nat g) ++ [(1,4%nat)])))
    as HT.
  cbn [Nat.add] in HT.
  destruct (FTripC_walls2 (N.to_nat V) 2 _ _ _ _ _ HT)
    as (cc & pc & qc & HFc & EQc).
  exists cc, pc, qc.
  split.
  - rewrite (ES 3%N ltac:(lia)).
    change (pair_runs 4 2 (N.to_nat V)) with
      (pair_runs (2+2)%nat 2 (N.to_nat V)).
    change (N.to_nat 3) with 3%nat.
    refine (DebrisLeafC_FTripC_cost_eq _ _ _ _ _ _ _ HFc).
    unfold cpair. rewrite N2Nat.id.
    change (N.of_nat 5) with 5%N. change (N.of_nat 2) with 2%N. lia.
  - rewrite EQc.
    rewrite (ES 2%N ltac:(lia)).
    change (N.to_nat 2) with 2%nat.
    reflexivity.
Qed.
Lemma span8_sound_m4c (cN V G : N) (out : word) (f3 : N)
      (c2 p2 : nat) (K2 : N) (q2 : wside) (Y : wside) :
  (2 <= cN)%N -> (1 <= G)%N ->
  FTripC c2 K2
    (sdec ((4,2,V) :: (7,1,1) :: (3,2,1) :: [(4,2,(G-1))])%N 4) p2 q2 ->
  wconf [] 0 ((1,S p2)::q2) = wconf [] 0 Y ->
  sdec out f3 = cdesc (N.to_nat cN - 2)%nat 2 1 ((0,2%nat) :: Y) ->
  sound_impl_c (cx (28 * cN + 14 * V + 14 * G + 43 + K2)%N)
    ((2,2,cN) :: (4,2,V) :: (4,3,1) :: [(4,2,G)])%N 4 out f3.
Proof.
  intros HN2 HG HF2 EQ2 HOUT.
  set (k := (N.to_nat cN - 2)%nat).
  set (c := N.to_nat V).
  set (g := (N.to_nat G - 1)%nat).
  assert (EcV : N.to_nat V = c) by reflexivity.
  assert (EcN : N.to_nat cN = S (S k)) by (subst k; lia).
  assert (EG : N.to_nat G = S g) by (subst g; lia).
  assert (EG1 : N.to_nat (G - 1)%N = g) by (subst g; lia).
  assert (EIN : sdec ((2,2,cN) :: (4,2,V) :: (4,3,1) :: [(4,2,G)])%N 4
                = uword (zeros (S (S k)) ++ repeat 2%nat c)
                    ((1,4%nat)::(0,3%nat)::(1,4%nat)::(0,2%nat)
                       :: uword (repeat 2%nat g) [(1,4%nat)])).
  { rewrite uword_app_ms, uword_zeros, uword_repeat_w.
    rewrite uword_repeat_w.
    rewrite !sdec_cons.
    unfold sdec. cbn [map gdecode expand app].
    rewrite frun_pos by lia.
    rewrite EcN, EG.
    change (N.to_nat 2) with 2%nat.
    change (N.to_nat 3) with 3%nat.
    change (N.to_nat 4) with 4%nat.
    change (N.to_nat 1) with 1%nat.
    change (2 + 2)%nat with 4%nat.
    rewrite <- EcV.
    cbn [pair_runs app].
    flatapp. reflexivity. }
  assert (EMID : uword (repeat 2%nat c)
                   ((1,7%nat)::(0,1%nat)::(1,3%nat)::(0,2%nat)
                      :: uword (repeat 2%nat g) [(1,4%nat)])
                 = sdec ((4,2,V) :: (7,1,1) :: (3,2,1)
                           :: [(4,2,(G-1))])%N 4).
  { rewrite uword_repeat_w, uword_repeat_w.
    unfold sdec. cbn [map gdecode expand app].
    rewrite frun_pos by lia.
    rewrite EG1.
    change (N.to_nat 2) with 2%nat.
    change (N.to_nat 3) with 3%nat.
    change (N.to_nat 4) with 4%nat.
    change (N.to_nat 7) with 7%nat.
    change (N.to_nat 1) with 1%nat.
    change (2 + 2)%nat with 4%nat.
    rewrite <- EcV.
    cbn [pair_runs app].
    flatapp. reflexivity. }
  unfold sound_impl_c.
  change (sdecode ?x ?y) with (sdec x y).
  rewrite EIN.
  pose proof (creach_of_wrunc _ _ _ _ _ _ (d4_half1_m4c k c g)) as HL1.
  cbn [wconf'] in HL1.
  rewrite EMID in HL1.
  pose proof (creach_of_wrunc _ _ _ _ _ _
                (d4_half2_genc c2 K2 _ p2 q2 k HF2)) as HL2.
  cbn [wconf'] in HL2.
  rewrite HOUT.
  refine (creach_tgt_eq _ _ _ _
            (wconf_cdesc_cong k 2 1 _ _
               (wconf_cons_cong (0,2%nat) _ _ EQ2)) _).
  refine (creach_cx_eq _ _ _ _ _ (creach_cx_trans _ _ _ _ _ HL1 HL2)).
  assert (EcN2 : N.to_nat (cN - 2)%N = k) by (subst k; lia).
  assert (EK : N.of_nat k = (cN - 2)%N)
    by (rewrite <- EcN2, N2Nat.id; reflexivity).
  assert (EC : N.of_nat c = V)
    by (rewrite <- EcV, N2Nat.id; reflexivity).
  assert (EGg : N.of_nat g = (G - 1)%N)
    by (rewrite <- EG1, N2Nat.id; reflexivity).
  rewrite EK, EC, EGg. lia.
Qed.
Definition seekb (w : word) : bool :=
  forallb (fun g => is_col g && negb (is_cmf g)
                    && (3 <=? gO g)%N) w.
Lemma round_at_excc (pre cols s : word) (f : N) (t2 : word) (f2 : N)
      (k : nat) :
  seekb pre = true -> seekb cols = true ->
  fst (cround_at cols s f) = Some (t2, f2) ->
  cin k (cadd (cx (ccolcost pre)) (snd (cround_at cols s f))) ->
  (exists (c p : nat) (q : wside) (K : N),
      N.of_nat k = (K + 6)%N
      /\ FTripC c K (sdec (pre ++ cols ++ s) f) p q
      /\ wconf [] 0 ((1,S p)::q) = wconf [] 0 (sdec (pre ++ t2) f2))
  \/ (expand (map gdecode (pre ++ cols)) = []
      /\ exists (c p : nat) (q : wside) (K : N),
        N.of_nat k = (K + 3)%N
        /\ SandC c K (sdec (pre ++ cols ++ s) f) ((1,S p)::q)
        /\ wconf [] 0 ((1,S p)::q) = wconf [] 0 (sdec (pre ++ t2) f2)).
Proof.
  intros HP HC HR Hk.
  assert (HPC : seekb (pre ++ cols) = true).
  { unfold seekb in *. rewrite forallb_app, HP, HC. reflexivity. }
  assert (HPCcol : forallb is_col (pre ++ cols) = true)
    by (apply forallb_seek_is_col; exact HPC).
  assert (ESP : forall (u : word) (g : N),
             sdec (pre ++ cols ++ u) g
             = expand (map gdecode (pre ++ cols)) ++ sdec u g).
  { intros u g. rewrite app_assoc, sdec_app. reflexivity. }
  pose proof (ccolcost_wcolcost pre) as EWP.
  pose proof (ccolcost_wcolcost cols) as EWC.
  pose proof (wcolcost_app pre cols) as EWA.
  assert (LEAF : forall s0 : word,
             s = s0 ->
             fst (match fst (cleaf_act s0 f) with
                  | Some (s2, g2) =>
                      (Some (cols ++ s2, g2),
                       cadd (cx (ccolcost cols)) (snd (cleaf_act s0 f)))
                  | None => (None, cundef)
                  end : (option (word * N) * cost)%type) = Some (t2, f2) ->
             cin k (cadd (cx (ccolcost pre))
                     (snd (match fst (cleaf_act s0 f) with
                           | Some (s2, g2) =>
                               (Some (cols ++ s2, g2),
                                cadd (cx (ccolcost cols)) (snd (cleaf_act s0 f)))
                           | None => (None, cundef)
                           end : (option (word * N) * cost)%type))) ->
             (exists (c p : nat) (q : wside) (K : N),
                 N.of_nat k = (K + 6)%N
                 /\ FTripC c K (sdec (pre ++ cols ++ s) f) p q
                 /\ wconf [] 0 ((1,S p)::q) = wconf [] 0 (sdec (pre ++ t2) f2))
             \/ (expand (map gdecode (pre ++ cols)) = []
                 /\ exists (c p : nat) (q : wside) (K : N),
                   N.of_nat k = (K + 3)%N
                   /\ SandC c K (sdec (pre ++ cols ++ s) f) ((1,S p)::q)
                   /\ wconf [] 0 ((1,S p)::q)
                      = wconf [] 0 (sdec (pre ++ t2) f2))).
  { intros s0 <- HR0 Hk0.
    destruct (fst (cleaf_act s f)) as [[s2 g2]|] eqn:ELA;
      [|cbn [fst] in HR0; discriminate HR0].
    cbn [fst] in HR0. injection HR0 as <- <-.
    cbn [snd] in Hk0.
    destruct (cin_split_cx _ _ _ Hk0) as (ka & EKA & Hka).
    destruct (cin_split_cx _ _ _ Hka) as (kl & EKL & Hkl).
    assert (ESL : cleaf_act s f = (Some (s2, g2), snd (cleaf_act s f)))
      by (rewrite <- ELA; apply surjective_pairing).
    destruct (leaf_ftripC s f s2 g2 _ kl ESL Hkl)
      as [(ci & pi & qi & K & EKK & HFi & EQi)
         |(ci & pi & qi & K & EKK & HSi & EQq & _ & _)].
    - destruct (FTripC_cols2 (pre ++ cols) ci K _ pi qi HPCcol HFi)
        as (c2 & p2 & q2 & HF2 & EQ2).
      left. exists c2, p2, q2, (K + wcolcost (pre ++ cols))%N.
      split; [lia|].
      split; [rewrite ESP; exact HF2|].
      rewrite EQ2, (ESP s2 g2). apply wconf_app_cong. exact EQi.
    - destruct (SandC_cols_exact (pre ++ cols) ci K _ _ HPC HSi)
        as [(c2 & p2 & q2 & D & HD & HF2 & EQ2)|(HZC & ENIL)].
      + left. exists c2, p2, q2, (K + D)%N.
        split; [lia|].
        split; [rewrite ESP; exact HF2|].
        rewrite EQ2, (ESP s2 g2), EQq. reflexivity.
      + right. split; [exact ENIL|].
        exists ci, pi, qi, K.
        split; [lia|].
        split; [rewrite ESP, ENIL; cbn [app]; exact HSi|].
        rewrite (ESP s2 g2), ENIL. cbn [app]. rewrite EQq. reflexivity. }
  unfold cround_at in HR, Hk.
  destruct s as [|[[oR zR] cR] tR]; cbv beta iota in HR, Hk;
    [exact (LEAF _ eq_refl HR Hk)|].
  destruct zR as [|pz]; cbv beta iota in HR, Hk;
    [exact (LEAF _ eq_refl HR Hk)|].
  destruct pz as [q1|q1|]; cbv beta iota in HR, Hk;
    [|exact (LEAF _ eq_refl HR Hk)|exact (LEAF _ eq_refl HR Hk)].
  destruct q1 as [r1|r1|]; cbv beta iota in HR, Hk;
    [exact (LEAF _ eq_refl HR Hk)|exact (LEAF _ eq_refl HR Hk)|].
  destruct cR as [|pc]; cbv beta iota in HR, Hk;
    [exact (LEAF _ eq_refl HR Hk)|].
  destruct pc as [pc'|pc'|]; cbv beta iota in HR, Hk;
    [exact (LEAF _ eq_refl HR Hk)|exact (LEAF _ eq_refl HR Hk)|].
  clear LEAF.
  match type of HR with
  | context [ fst (crenew_seg ?a ?b ?c ?d) ] =>
      destruct (fst (crenew_seg a b c d)) as [[body fb]|] eqn:ERS
  end.
  { cbn [fst snd] in HR, Hk. injection HR as <- <-.
    destruct (cin_split_cx _ _ _ Hk) as (ka & EKA & Hka).
    destruct (cin_split_cx _ _ _ Hka) as (kr & EKR & Hkr).
    assert (ESR : crenew_seg (List.length ((oR,3,1)%N :: tR)) cols
                    ((oR,3,1)%N :: tR) f
                  = (Some (body, fb),
                     snd (crenew_seg (List.length ((oR,3,1)%N :: tR)) cols
                            ((oR,3,1)%N :: tR) f)))
      by (rewrite <- ERS; apply surjective_pairing).
    destruct (renew_ftripc leaf_ftripC _ cols _ f body fb _ kr HC ESR Hkr)
      as (ci & pi & qi & HFi & EQi).
    destruct (FTripC_cols2 pre ci (N.of_nat kr) _ pi qi
                (forallb_seek_is_col _ HP) HFi)
      as (c2 & p2 & q2 & HF2 & EQ2).
    left. exists c2, p2, q2, (N.of_nat kr + wcolcost pre)%N.
    split; [lia|].
    split; [rewrite sdec_app; exact HF2|].
    rewrite EQ2, sdec_app. apply wconf_app_cong. exact EQi. }
  match type of HR with
  | context [ fst (cfire_comp ?a ?b ?c) ] =>
      destruct (fst (cfire_comp a b c)) as [[s2 g2]|] eqn:EFC
  end; cbn [fst snd] in HR, Hk; [|discriminate HR].
  injection HR as <- <-.
  destruct (cin_split_cx _ _ _ Hk) as (ka & EKA & Hka).
  destruct (cin_split_cx _ _ _ Hka) as (kf & EKF & Hkf).
  assert (ESF : cfire_comp (List.length ((oR,3,1)%N :: tR))
                  ((oR,3,1)%N :: tR) f
                = (Some (s2, g2),
                   snd (cfire_comp (List.length ((oR,3,1)%N :: tR))
                          ((oR,3,1)%N :: tR) f)))
    by (rewrite <- EFC; apply surjective_pairing).
  destruct (fire_comp_ftripc leaf_ftripC _ _ f s2 g2 _ kf ESF Hkf)
    as (ci & pi & qi & HFi & EQi).
  destruct (FTripC_cols2 (pre ++ cols) ci (N.of_nat kf) _ pi qi HPCcol HFi)
    as (c2 & p2 & q2 & HF2 & EQ2).
  left. exists c2, p2, q2, (N.of_nat kf + wcolcost (pre ++ cols))%N.
  split; [lia|].
  split; [rewrite ESP; exact HF2|].
  rewrite EQ2, (ESP s2 g2). apply wconf_app_cong. exact EQi.
Qed.
Lemma cadds_cempty_l (a b : cost) : cempty a -> cempty (cadds a b).
Proof.
  unfold cempty, cadds. intros H.
  destruct (N.ltb (chi a) (clo a)) eqn:E; cbn [orb].
  - apply cempty_cundef.
  - apply N.ltb_ge in E. lia.
Qed.
Lemma cadds_cempty_r (a b : cost) : cempty b -> cempty (cadds a b).
Proof.
  unfold cempty, cadds. intros H.
  destruct (N.ltb (chi b) (clo b)) eqn:E; rewrite ?orb_true_r.
  - apply cempty_cundef.
  - apply N.ltb_ge in E. lia.
Qed.
Lemma cadds_live (a b : cost) :
  ~ cempty a -> ~ cempty b -> cadds a b = cadd a b.
Proof.
  unfold cempty, cadds. intros Ha Hb.
  destruct (N.ltb (chi a) (clo a)) eqn:E1; [apply N.ltb_lt in E1; lia|].
  destruct (N.ltb (chi b) (clo b)) eqn:E2; [apply N.ltb_lt in E2; lia|].
  reflexivity.
Qed.
Lemma cadds_not_cempty_l (a b : cost) : ~ cempty (cadds a b) -> ~ cempty a.
Proof. intros H Ha. apply H, cadds_cempty_l, Ha. Qed.
Lemma cadds_not_cempty_r (a b : cost) : ~ cempty (cadds a b) -> ~ cempty b.
Proof. intros H Hb. apply H, cadds_cempty_r, Hb. Qed.
Lemma seekb_42 (c : N) : seekb [(4,2,c)%N] = true.
Proof.
  unfold seekb, is_col, is_cmf.
  cbn [forallb gO gZ gC].
  destruct ((c =? 1)%N); reflexivity.
Qed.
Lemma seekb_pre2 (V G : N) : seekb [(4,2,V); (8,2,1); (4,2,G)]%N = true.
Proof.
  unfold seekb, is_col, is_cmf.
  cbn [forallb gO gZ gC].
  destruct ((V =? 1)%N), ((G =? 1)%N); reflexivity.
Qed.
Lemma clo_cadd (a b : cost) : (clo (cadd a b) = clo a + clo b)%N.
Proof. reflexivity. Qed.
Lemma round2g_nil_exc2c (V G : N) (cols2 t3 : word) (f2 f3 : N) :
  forallb (fun g => is_col g && negb (is_cmf g)
                    && (3 <=? gO g)%N) cols2 = true ->
  (if (f2 =? 4)%N
   then match dtb4_conv cols2 with
        | Some cols2' => Some (cols2', f2)
        | None => None
        end
   else if (5 <=? f2)%N then Some (cols2 ++ [((f2-1)%N,1,1)%N], 3%N)
   else None) = Some (t3, f3) ->
  ~ cempty (if (f2 =? 4)%N
            then match dtb4_convc cols2 with
                 | Some (_, Kd) => cx (Kd + 6)%N
                 | None => cundef
                 end
            else if (5 <=? f2)%N
            then cx (2 * f2 + 13 + ccolcost cols2 + 6)%N
            else cundef) ->
  exists (c2 p2 : nat) (q2 : wside) (K2 : N),
    (clo (if (f2 =? 4)%N
          then match dtb4_convc cols2 with
               | Some (_, Kd) => cx (Kd + 6)%N
               | None => cundef
               end
          else if (5 <=? f2)%N
          then cx (2 * f2 + 13 + ccolcost cols2 + 6)%N
          else cundef)
     + ccolcost [(4,2,V); (8,2,1); (4,2,(G-1))]%N
     = K2 + 6)%N
    /\ FTripC c2 K2
         (sdec ((4,2,V)%N :: (8,2,1)%N :: (4,2,(G-1))%N :: cols2) f2) p2 q2
    /\ wconf [] 0 ((1,S p2)::q2)
       = wconf [] 0 (sdec ((4,2,V)%N :: (8,2,1)%N :: (4,2,(G-1))%N :: t3) f3).
Proof.
  intros HC HR HNE.
  assert (HP2 : forallb is_col
                  [(4,2,V); (8,2,1); (4,2,(G-1))]%N = true) by reflexivity.
  destruct ((f2 =? 4)%N) eqn:EF4.
  -
    apply N.eqb_eq in EF4. subst f2.
    destruct (dtb4_convc cols2) as [[cols2c Kd]|] eqn:EDTC.
    2:{ exfalso. apply HNE. apply cempty_cundef. }
    assert (EDT : dtb4_conv cols2 = Some cols2c).
    { pose proof (dtb4_convc_proj cols2) as EP.
      rewrite EDTC in EP. cbn [option_map fst] in EP. symmetry. exact EP. }
    rewrite EDT in HR. injection HR as <- <-.
    destruct (dtb4_convc_tripc cols2 cols2c Kd HC EDTC)
      as (ci & pi & qi & HFi & EQi).
    destruct (ren_liftc_col [(4,2,V); (8,2,1); (4,2,(G-1))]%N
                cols2 cols2c 4 4 ci pi Kd qi HP2 HFi EQi)
      as (c2 & p2 & q2 & HF2 & EQ2).
    cbn [app] in HF2, EQ2.
    exists c2, p2, q2,
      (Kd + wcolcost [(4,2,V); (8,2,1); (4,2,(G-1))]%N)%N.
    split; [|split; [exact HF2|exact EQ2]].
    unfold clo, cx;
      cbn [fst snd ccolcost wcolcost gC gO]. lia.
  -
    destruct ((5 <=? f2)%N) eqn:EF5.
    2:{ exfalso. apply HNE. apply cempty_cundef. }
    apply N.leb_le in EF5.
    injection HR as <- <-.
    destruct (ren_far_tailc cols2 f2 HC EF5)
      as (ci & pi & qi & HFi & EQi).
    destruct (ren_liftc_col [(4,2,V); (8,2,1); (4,2,(G-1))]%N
                cols2 (cols2 ++ [((f2-1)%N,1,1)%N]) f2 3 ci pi
                (2 * f2 + 13 + wcolcost cols2)%N qi HP2 HFi EQi)
      as (c2 & p2 & q2 & HF2 & EQ2).
    cbn [app] in HF2, EQ2.
    exists c2, p2, q2,
      (2 * f2 + 13 + wcolcost cols2
       + wcolcost [(4,2,V); (8,2,1); (4,2,(G-1))]%N)%N.
    split; [|split; [exact HF2|exact EQ2]].
    pose proof (ccolcost_wcolcost cols2) as EW.
    unfold clo, cx;
      cbn [fst snd ccolcost wcolcost gC gO]. lia.
Qed.
Lemma span8g_pre8_closec (cN V G : N) (rest cols2 : word) (f : N) :
  (2 <= cN)%N -> (1 <= G)%N ->
  fst (cround2g_pre8 rest f (G-1)) = Some cols2 ->
  ~ cempty (snd (cround2g_pre8 rest f (G-1))) ->
  sound_impl_c
    (cx (28 * cN + 28 * V + 14 * (G-1) + 24
           + clo (snd (cround2g_pre8 rest f (G-1))) )%N)
    ((2,2,cN) :: (4,2,V) :: (4,3,1) :: (4,2,G) :: rest)%N f
    ([(5,1,1); (4,1,1); (3,1,(cN-2)); (2,2,1); (4,2,V);
       (7,1,1); (3,2,1); (4,2,(G-1))]%N ++ cols2) 4.
Proof.
  intros HN2 HG HR HNE.
  unfold cround2g_pre8 in HR, HNE |- *.
  destruct (seek rest) as [cols s] eqn:ESK.
  destruct (seek_split rest cols s ESK) as (EREST & HCOLS).
  destruct (fst (cround_at cols s f)) as [[t2 f2]|] eqn:ERA;
    [|cbn [fst] in HR; discriminate HR].
  destruct (seek t2) as [cols2' s2] eqn:ESK2.
  destruct (seek_split t2 cols2' s2 ESK2) as (ET2 & HCOLS2).
  destruct s2 as [|g2 s2']; [|cbn [fst] in HR; discriminate HR].
  rewrite app_nil_r in ET2. subst t2.
  destruct (((f2 =? 4) && forallb w42 cols2')%N) eqn:EGD;
    [|cbn [fst] in HR; discriminate HR].
  apply andb_prop in EGD as [EF4 EW42].
  apply N.eqb_eq in EF4. subst f2.
  destruct (dtb4_conv cols2') as [served|] eqn:EDT;
    [cbn [fst] in HR; discriminate HR|].
  cbn [fst snd] in HR, HNE |- *.
  injection HR as <-.
  assert (HE1 : ~ cempty (snd (cround_at cols s f)))
    by (apply (cadds_not_cempty_l _ _ HNE)).
  assert (HEK :
      ~ cempty
          (cx (kdtb_plain ((G-1) + w42sum cols2') + 6)))
    by apply cx_not_cempty.
  rewrite (cadds_live _ _ HE1 HEK), clo_cadd.
  set (d1 := cadd (cx (ccolcost [(4,2,(G-1))%N]))
                  (snd (cround_at cols s f))).
  assert (HD1 : ~ cempty d1) by (apply not_cempty_cadd_cx_l; exact HE1).
  pose proof (cin_of_not_cempty d1 HD1) as Hk1.
  assert (ECLO1 :
      (N.of_nat (N.to_nat (clo d1))
       = ccolcost [(4,2,(G-1))%N]
           + clo (snd (cround_at cols s f)))%N)
    by (rewrite N2Nat.id; reflexivity).
  assert (HEX1 : exists (c1 p1 : nat) (q1 : wside),
      ((exists K1 : N, N.of_nat (N.to_nat (clo d1)) = (K1 + 6)%N
          /\ FTripC c1 K1
               (sdec ((4,2,(G-1))%N :: rest) f) p1 q1)
       \/ (exists KS : N, N.of_nat (N.to_nat (clo d1)) = (KS + 3)%N
          /\ SandC c1 KS (sdec ((4,2,(G-1))%N :: rest) f)
               ((1,S p1)::q1)))
      /\ wconf [] 0 ((1,S p1)::q1)
           = wconf [] 0 (sdec ((4,2,(G-1))%N :: cols2') 4)).
  { destruct (round_at_excc [(4,2,(G-1))%N] cols s f cols2' 4
                (N.to_nat (clo d1)) (seekb_42 _) HCOLS ERA Hk1)
      as [(c1 & p1 & q1 & K1 & EK1 & HF1 & EQ1)
         |(_ & c1 & p1 & q1 & K1 & EK1 & HS1 & EQ1)].
    - exists c1, p1, q1. cbn [app] in HF1, EQ1.
      rewrite <- EREST in HF1.
      split; [left; exists K1; split; [exact EK1|exact HF1]|exact EQ1].
    - exists c1, p1, q1. cbn [app] in HS1, EQ1.
      rewrite <- EREST in HS1.
      split; [right; exists K1; split; [exact EK1|exact HS1]|exact EQ1]. }
  destruct HEX1 as (c1 & p1 & q1 & HF1 & EQ1).
  assert (HW :
      forallb w42 ((4,2,(G-1))%N :: cols2') = true).
  { cbn [forallb]. rewrite EW42.
    unfold w42. cbn [gO gZ]. reflexivity. }
  destruct (dtb4_pre8_tripc_sum
              ((4,2,(G-1))%N :: cols2') HW)
    as (ci & pi & qi & HFi & EQi).
  destruct (ren_liftc_col [(4,2,V)%N]
              ((8,2,1)%N :: (4,2,(G-1))%N :: cols2')
              ((7,1,1)%N :: (3,2,1)%N :: (4,2,(G-1))%N :: cols2')
              4 4 ci pi
              (kl_dtb_plain
                 (w42sum ((4,2,(G-1))%N :: cols2')))
              qi eq_refl HFi ltac:(rewrite EQi; reflexivity))
    as (c2 & p2 & q2 & HF2 & EQ2).
  cbn [app] in HF2, EQ2.
  assert (EOUT :
      sdec ([(5,1,1); (4,1,1); (3,1,(cN-2)); (2,2,1); (4,2,V);
              (7,1,1); (3,2,1); (4,2,(G-1))]%N ++ cols2') 4
      = cdesc (N.to_nat cN - 2)%nat 2 1
          ((0,2%nat) ::
             sdec ((4,2,V)%N :: (7,1,1)%N :: (3,2,1)%N
                     :: (4,2,(G-1))%N :: cols2') 4)).
  { set (k := (N.to_nat cN - 2)%nat).
    assert (EcN2 : N.to_nat (cN - 2)%N = k) by (subst k; lia).
    rewrite (cdesc_group k 0).
    rewrite ?sdec_app, ?sdec_cons.
    cbn [map gdecode expand].
    rewrite EcN2.
    change (N.to_nat 5) with 5%nat.
    change (N.to_nat 4) with 4%nat.
    change (N.to_nat 3) with 3%nat.
    change (N.to_nat 2) with 2%nat.
    change (N.to_nat 1) with 1%nat.
    change (N.to_nat 7) with 7%nat.
    cbn [pair_runs app].
    flatapp. reflexivity. }
  refine (creach_cx_eq _ _ _ _ _
            (span8_sound_genOc cN V G rest cols2'
              ([(5,1,1); (4,1,1); (3,1,(cN-2)); (2,2,1); (4,2,V);
                 (7,1,1); (3,2,1); (4,2,(G-1))]%N ++ cols2')
              f 4 4 c1 p1 q1 c2 p2 q2
              (N.of_nat (N.to_nat (clo d1)))
              (kl_dtb_plain
                   (w42sum ((4,2,(G-1))%N :: cols2'))
                 + wcolcost [(4,2,V)%N])%N
              (sdec ((4,2,V)%N :: (7,1,1)%N :: (3,2,1)%N
                       :: (4,2,(G-1))%N :: cols2') 4)
              HN2 HG HF1 EQ1 HF2 EQ2 EOUT)).
  cbn [w42sum ccolcost wcolcost gC gO] in ECLO1 |- *.
  unfold kdtb_plain, kl_dtb_plain.
  rewrite ECLO1. unfold clo, cx. cbn [fst]. lia.
Qed.
Lemma span8g_closec (cN V G : N) (rest t3 : word) (f f3 : N) :
  (2 <= cN)%N -> (1 <= G)%N ->
  fst (cround2g rest f) = Some (t3, f3) ->
  ~ cempty (snd (cround2g rest f)) ->
  sound_impl_c (cx (28 * cN + 28 * V + 28 * (G-1) + 46
                    + clo (snd (cround2g rest f)))%N)
    ((2,2,cN) :: (4,2,V) :: (4,3,1) :: (4,2,G) :: rest)%N f
    ([(5,1,1); (4,1,1); (3,1,(cN-2)); (2,2,1); (4,2,V); (8,2,1);
      (4,2,(G-1))]%N ++ t3) f3.
Proof.
  intros HN2 HG HR HNE.
  unfold cround2g in HR, HNE |- *.
  destruct (seek rest) as [cols s] eqn:ESK.
  destruct (seek_split rest cols s ESK) as (EREST & HCOLS).
  destruct (fst (cround_at cols s f)) as [[t2 f2]|] eqn:ERA;
    [|cbn [snd] in HNE; exfalso; apply HNE; apply cempty_cundef].
  destruct (seek t2) as [cols2 s2] eqn:ESK2.
  destruct (seek_split t2 cols2 s2 ESK2) as (ET2 & HCOLS2).
  destruct s2 as [|g2 s2'].
  {
    rewrite app_nil_r in ET2. subst t2.
    cbn [fst snd] in HR, HNE |- *.
    assert (HE1 : ~ cempty (snd (cround_at cols s f)))
      by (apply (cadds_not_cempty_l _ _ HNE)).
    assert (HE2 := cadds_not_cempty_r _ _ HNE).
    rewrite (cadds_live _ _ HE1 HE2), clo_cadd.
    set (d1 := cadd (cx (ccolcost [(4,2,(G-1))%N]))
                    (snd (cround_at cols s f))).
    assert (HD1 : ~ cempty d1) by (apply not_cempty_cadd_cx_l; exact HE1).
    pose proof (cin_of_not_cempty d1 HD1) as Hk1.
    assert (ECLO1 : (N.of_nat (N.to_nat (clo d1))
                     = ccolcost [(4,2,(G-1))%N]
                       + clo (snd (cround_at cols s f)))%N)
      by (rewrite N2Nat.id; reflexivity).
    assert (HEX1 : exists (c1 p1 : nat) (q1 : wside),
               ((exists K1 : N, N.of_nat (N.to_nat (clo d1)) = (K1 + 6)%N
                     /\ FTripC c1 K1 (sdec ((4,2,(G-1))%N :: rest) f) p1 q1)
                \/ (exists KS : N, N.of_nat (N.to_nat (clo d1)) = (KS + 3)%N
                     /\ SandC c1 KS (sdec ((4,2,(G-1))%N :: rest) f)
                          ((1,S p1)::q1)))
               /\ wconf [] 0 ((1,S p1)::q1)
                  = wconf [] 0 (sdec ((4,2,(G-1))%N :: cols2) f2)).
    { destruct (round_at_excc [(4,2,(G-1))%N] cols s f cols2 f2
                  (N.to_nat (clo d1)) (seekb_42 _) HCOLS ERA Hk1)
        as [(c1 & p1 & q1 & K1 & EK1 & HF1 & EQ1)
           |(_ & c1 & p1 & q1 & K1 & EK1 & HS1 & EQ1)].
      - exists c1, p1, q1. cbn [app] in HF1, EQ1.
        rewrite <- EREST in HF1.
        split; [left; exists K1; split; [exact EK1|exact HF1]|exact EQ1].
      - exists c1, p1, q1. cbn [app] in HS1, EQ1.
        rewrite <- EREST in HS1.
        split; [right; exists K1; split; [exact EK1|exact HS1]|exact EQ1]. }
    destruct HEX1 as (c1 & p1 & q1 & HF1 & EQ1).
    destruct (round2g_nil_exc2c V G cols2 t3 f2 f3 HCOLS2 HR HE2)
      as (c2 & p2 & q2 & K2 & EK2 & HF2 & EQ2).
    refine (creach_cx_eq _ _ _ _ _
              (span8_sound_genc cN V G rest cols2 t3 f f2 f3
                 c1 p1 q1 c2 p2 q2 _ K2 HN2 HG HF1 EQ1 HF2 EQ2)).
    cbn [ccolcost gC gO] in ECLO1, EK2.
    rewrite ECLO1 in *. lia. }
  cbn [fst snd] in HR, HNE |- *.
  assert (HE1 : ~ cempty (snd (cround_at cols s f)))
    by (apply (cadds_not_cempty_l _ _ HNE)).
  assert (HE2 : ~ cempty (snd (cround_at cols2 (g2 :: s2') f2)))
    by (apply (cadds_not_cempty_r _ _ HNE)).
  rewrite (cadds_live _ _ HE1 HE2), clo_cadd.
  set (d1 := cadd (cx (ccolcost [(4,2,(G-1))%N]))
                  (snd (cround_at cols s f))).
  assert (HD1 : ~ cempty d1) by (apply not_cempty_cadd_cx_l; exact HE1).
  pose proof (cin_of_not_cempty d1 HD1) as Hk1.
  assert (ECLO1 : (N.of_nat (N.to_nat (clo d1))
                   = ccolcost [(4,2,(G-1))%N] + clo (snd (cround_at cols s f)))%N)
    by (rewrite N2Nat.id; reflexivity).
  assert (HEX1 : exists (c1 p1 : nat) (q1 : wside),
             ((exists K1 : N, N.of_nat (N.to_nat (clo d1)) = (K1 + 6)%N
                   /\ FTripC c1 K1 (sdec ((4,2,(G-1))%N :: rest) f) p1 q1)
              \/ (exists KS : N, N.of_nat (N.to_nat (clo d1)) = (KS + 3)%N
                   /\ SandC c1 KS (sdec ((4,2,(G-1))%N :: rest) f)
                        ((1,S p1)::q1)))
             /\ wconf [] 0 ((1,S p1)::q1)
                = wconf [] 0 (sdec ((4,2,(G-1))%N :: t2) f2)).
  { destruct (round_at_excc [(4,2,(G-1))%N] cols s f t2 f2
                (N.to_nat (clo d1)) (seekb_42 _) HCOLS ERA Hk1)
      as [(c1 & p1 & q1 & K1 & EK1 & HF1 & EQ1)
         |(_ & c1 & p1 & q1 & K1 & EK1 & HS1 & EQ1)].
    - exists c1, p1, q1. cbn [app] in HF1, EQ1.
      rewrite <- EREST in HF1.
      split; [left; exists K1; split; [exact EK1|exact HF1]|exact EQ1].
    - exists c1, p1, q1. cbn [app] in HS1, EQ1.
      rewrite <- EREST in HS1.
      split; [right; exists K1; split; [exact EK1|exact HS1]|exact EQ1]. }
  destruct HEX1 as (c1 & p1 & q1 & HF1 & EQ1).
  set (d2 := cadd (cx (ccolcost [(4,2,V); (8,2,1); (4,2,(G-1))]%N))
                  (snd (cround_at cols2 (g2 :: s2') f2))).
  assert (HD2 : ~ cempty d2) by (apply not_cempty_cadd_cx_l; exact HE2).
  pose proof (cin_of_not_cempty d2 HD2) as Hk2.
  assert (ECLO2 : (N.of_nat (N.to_nat (clo d2))
                   = ccolcost [(4,2,V); (8,2,1); (4,2,(G-1))]%N
                     + clo (snd (cround_at cols2 (g2 :: s2') f2)))%N)
    by (rewrite N2Nat.id; reflexivity).
  destruct (round_at_excc [(4,2,V); (8,2,1); (4,2,(G-1))]%N cols2
              (g2 :: s2') f2 t3 f3 (N.to_nat (clo d2))
              (seekb_pre2 _ _) HCOLS2 HR Hk2)
    as [(c2 & p2 & q2 & K2 & EK2 & HF2 & EQ2)
       |(ENIL & _)].
  2:{ exfalso. revert ENIL.
      cbn [map gdecode expand app].
      change (N.to_nat 8) with 8%nat.
      change (N.to_nat 2) with 2%nat.
      destruct (N.to_nat V); cbn [pair_runs app]; discriminate. }
  cbn [app] in HF2, EQ2.
  rewrite <- ET2 in HF2.
  refine (creach_cx_eq _ _ _ _ _
            (span8_sound_genc cN V G rest t2 t3 f f2 f3 c1 p1 q1 c2 p2 q2
               _ K2 HN2 HG HF1 EQ1 HF2 EQ2)).
  cbn [ccolcost gC gO] in ECLO1, ECLO2.
  rewrite ECLO1 in *.
  lia.
Qed.
Lemma span8g_rest0_m4c (cN V G : N) :
  (2 <= cN)%N -> (1 <= G)%N ->
  sound_impl_c (cx (28 * cN + 28 * V + 14 * G + 60)%N)
    ((2,2,cN) :: (4,2,V) :: (4,3,1) :: [(4,2,G)])%N 4
    ([(5,1,1); (4,1,1); (3,1,cN-2); (2,2,1); (4,2,V); (7,1,1); (2,2,1)]%N
     ++ (if (1 <? G)%N then [(4,2,G-1)]%N else [])) 4%N.
Proof.
  intros HN HG.
  destruct (m4_exc2c V (G-1)%N) as (c2 & p2 & q2 & HF2 & EQ2).
  set (k := (N.to_nat cN - 2)%nat).
  assert (EcN2 : N.to_nat (cN - 2)%N = k) by (subst k; lia).
  assert (MAIN : sound_impl_c (cx (28 * cN + 28 * V + 14 * G + 60)%N)
                   ((2,2,cN) :: (4,2,V) :: (4,3,1) :: [(4,2,G)])%N 4
                   ([(5,1,1); (4,1,1); (3,1,(cN-2)); (2,2,1); (4,2,V);
                     (7,1,1); (2,2,1); (4,2,(G-1))]%N) 4%N).
  { refine (creach_cx_eq _ _ _ _ _
              (span8_sound_m4c cN V G _ 4%N c2 p2 (14 * V + 17)%N q2 _
                 HN HG HF2 _ _)).
    - lia.
    - rewrite EQ2. reflexivity.
    - rewrite (cdesc_group k 0).
      rewrite ?sdec_cons.
      unfold sdec. cbn [map gdecode expand app].
      rewrite frun_pos by lia.
      rewrite EcN2.
      change (N.to_nat 5) with 5%nat.
      change (N.to_nat 4) with 4%nat.
      change (N.to_nat 3) with 3%nat.
      change (N.to_nat 2) with 2%nat.
      change (N.to_nat 1) with 1%nat.
      change (N.to_nat 7) with 7%nat.
      cbn [pair_runs app].
      flatapp. reflexivity. }
  destruct ((1 <? G)%N) eqn:EGT.
  - revert MAIN. cbn [app]. exact (fun x => x).
  - assert (EG0 : (G - 1)%N = 0%N).
    { apply N.ltb_ge in EGT. lia. }
    revert MAIN. unfold sound_impl_c.
    rewrite EG0. cbn [app].
    assert (ESD : forall (ff : N),
              sdecode [(5,1,1); (4,1,1); (3,1,(cN-2)); (2,2,1); (4,2,V);
                       (7,1,1); (2,2,1); (4,2,0)]%N ff
              = sdecode [(5,1,1); (4,1,1); (3,1,(cN-2)); (2,2,1); (4,2,V);
                         (7,1,1); (2,2,1)]%N ff).
    { intros ff. unfold sdecode.
      cbn [map gdecode expand app].
      change (N.to_nat 0) with 0%nat.
      cbn [pair_runs app]. reflexivity. }
    rewrite ESD. exact (fun x => x).
Qed.
Lemma fr_span8_sound_c (w : word) (f : N) (w2 : word) (f2 : N) :
  fr_span8 w f = Some (ROk w2 f2) ->
  cempty (d_span8 w f) \/ sound_impl_c (d_span8 w f) w f w2 f2.
Proof.
  intros E. unfold fr_span8 in E.
  destruct w as [|[[o1 z1] c1] w1]; [discriminate E|].
  destruct w1 as [|[[o2 z2] c2] wb]; [killmN E|].
  destruct wb as [|[[o3 z3] c3] wc]; [killmN E|].
  destruct wc as [|[[o4 z4] c4] rest]; [killmN E|].
  killmN E.
  destruct rest as [|g5 rest'].
  -
    cbv beta iota zeta in E.
    cbn [d_span8].
    destruct (((2 <=? c1) && (1 <=? c4) && (f =? 4))%N) eqn:EG4.
    + cbv beta iota zeta in E.
      apply andb_prop in EG4. destruct EG4 as (EG4a & EF4).
      apply andb_prop in EG4a. destruct EG4a as (EN2 & EG1).
      apply N.leb_le in EN2. apply N.leb_le in EG1.
      apply N.eqb_eq in EF4. subst f.
      match type of E with
      | context [ tick_target ?a ?j ] =>
          replace (tick_target a j) with (Some 5%nat) in E
            by (symmetry; apply m4_tick_target)
      end.
      cbv beta iota in E.
      match type of E with
      | context [ deliver_tick ?fu ?a ?ff ?j ?vd ] =>
          replace (deliver_tick fu a ff j vd)
            with (ROk ([(5,1,1); (4,1,1); (3,1,(c1-2)); (2,2,1); (4,2,c2);
                             (7,1,1); (2,2,1)]%N
                            ++ (if (1 <? c4)%N then [(4,2,(c4-1))%N] else []))
                   4%N) in E
            by (symmetry; apply m4_deliver)
      end.
      cbv beta iota in E.
      unfold o_ in E. injection E as <- <-.
      right. exact (span8g_rest0_m4c c1 c2 c4 EN2 EG1).
    + cbv beta iota zeta in E.
      destruct (((2 <=? c1) && (1 <=? c4) && (5 <=? f))%N) eqn:EG5;
        [|discriminate E].
      apply andb_prop in EG5. destruct EG5 as (EG5a & EF5).
      apply andb_prop in EG5a. destruct EG5a as (EN2 & EG1).
      apply N.leb_le in EN2. apply N.leb_le in EG1.
      apply N.leb_le in EF5.
      unfold o_ in E. injection E as <- <-.
      right. exact (span8g_rest0_farc c1 c2 c4 f EN2 EG1 EF5).
  -
    cbn [d_span8].
    destruct (((2 <=? c1) && (1 <=? c4))%N) eqn:EG2;
      [|left; apply cempty_cundef].
    cbv beta iota zeta in E. try rewrite EG2 in E. cbv beta iota zeta in E.
    apply andb_prop in EG2. destruct EG2 as (EN2 & EG1).
    apply N.leb_le in EN2. apply N.leb_le in EG1.
    rewrite <- (cround2g_proj (g5 :: rest') f) in E.
    destruct (fst (cround2g (g5 :: rest') f)) as [[t3 f3]|] eqn:ER2.
    + cbv beta iota in E.
      unfold o_ in E. injection E as <- <-.
      destruct (cempty_dec (snd (cround2g (g5 :: rest') f))) as [HE|HE];
        [left; apply cempty_cadd_cx_l; exact HE|].
      right.
      apply (creach_of_clo _ _ _ (not_cempty_cadd_cx_l _ _ HE)).
      rewrite clo_cadd_cx_l.
      exact (span8g_closec c1 c2 c4 (g5 :: rest') t3 f f3 EN2 EG1 ER2 HE).
    + rewrite <- (cround2g_pre8_proj
                    (g5 :: rest') f (c4-1)) in E.
      destruct (fst (cround2g_pre8
                       (g5 :: rest') f (c4-1))) as [cols2|] eqn:ERP.
      2:{ cbn in E. discriminate E. }
      cbv beta iota in E.
      unfold o_ in E. injection E as <- <-.
      destruct (cempty_dec
                  (snd (cround2g_pre8
                          (g5 :: rest') f (c4-1)))) as [HE|HE].
      { left. apply cempty_cadd_cx_l. exact HE. }
      right.
      apply (creach_of_clo _ _ _ (not_cempty_cadd_cx_l _ _ HE)).
      rewrite clo_cadd_cx_l.
      exact (span8g_pre8_closec c1 c2 c4 (g5 :: rest') cols2 f
               EN2 EG1 ERP HE).
Qed.
Corollary cfr_span8_sound (w : word) (f : N) (w2 : word)
          (f2 : N) (d : cost) :
  cfr_span8 w f = Some (ROk w2 f2, d) ->
  cempty d \/ sound_impl_c d w f w2 f2.
Proof. apply (decorate_sound_disj _ _ fr_span8_sound_c). Qed.
Lemma dm4_w1c (Z : wside) (p : nat) (q : wside) :
  wrunc 3 ((0,1%nat)::(1,2%nat)::vpairC 1 (vpairC 2 Z)) 1
       ((0,1%nat)::(1,S p)::q)
  = Some ((((0,1%nat)::(1,2%nat)::Z), 1,
           (0,1%nat)::(1,4%nat)::(0,1%nat)::(1,4%nat)::(0,2%nat)::(1,S p)::q),
          13%N).
Proof.
  apply (ccost_pin _ _ _ _ _ _ (dm4_w1 Z p q)).
  eexists. ckerc.
Qed.
Lemma dm4_w1_uc (Z : wside) (ks : list nat) (n : nat) (r0 : wside) :
  wrunc 3 ((0,1%nat)::(1,2%nat)::vpairC 1 (vpairC 2 Z)) 1
       ((0,1%nat) :: uword ks ((1, S n) :: r0))
  = Some ((((0,1%nat)::(1,2%nat)::Z), 1,
           (0,1%nat)::(1,4%nat)::(0,1%nat)::(1,4%nat)::(0,2%nat)
             :: uword ks ((1, S n) :: r0)),
          13%N).
Proof.
  destruct (uword_one_headed ks n r0) as (p & q & E).
  rewrite E. apply dm4_w1c.
Qed.
Lemma kernel_deep4_chain1_sandc (cS : nat) (KS : N) (Win : wside)
      (pS : nat) (qS : wside) (k a' kk : nat) :
  SandC cS KS Win ((1,S pS)::qS) ->
  wrunc (5 * k + 6 * a' + 3 * kk + cS + 23)%nat [] 0
       (uword (zeros (S (S k)) ++ repeat 2%nat (S a')
                 ++ 1%nat :: repeat 2%nat kk)
          ((1,4%nat) :: (0,3%nat) :: (1,4%nat) :: (0,2%nat) :: Win))
  = Some (([], 0,
           cdesc k 2 1
             ((0,2%nat) :: uword (repeat 2%nat a')
                ((1,4%nat) :: (0,1%nat) :: (1,3%nat) :: (0,2%nat)
                   :: uword (repeat 2%nat kk ++ [6%nat]) ((1,S pS) :: qS)))),
          (KS + 28 * N.of_nat k + 28 * N.of_nat a'
              + 14 * N.of_nat kk + 124)%N).
Proof.
  intros HS.
  apply (ccost_pin _ _ _ _ _ _
           (kernel_deep4_chain1_sand cS Win pS qS k a' kk
              (SandC_Sand _ _ _ _ HS))).
  eexists.
  replace (5 * k + 6 * a' + 3 * kk + cS + 23)%nat
    with (List.length (zeros (S (S k)) ++ repeat 2%nat (S a')
                         ++ 1%nat :: repeat 2%nat kk)
          + (2 + (cS
             + (2
                + (2 * kk + (3 + (2 * a' + (1 + (1 + (a'
                   + S (S (2 * List.length (rev (repeat 2%nat a'))
                      + (3 + (1 + (4 * k + 4)))))))))))))))%nat
    by (rewrite ?length_app, ?length_zeros; cbn [List.length];
        rewrite ?length_rev, ?repeat_length; lia).
  rewrite wrunc_add, wcross_mixedc.
  lazy beta iota.
  rewrite (vstack_vstackC _ [] I).
  rewrite rev_app_distr.
  cbn [rev].
  rewrite rev_app_distr.
  cbn [rev].
  rewrite rev_zeros, !rev_repeat.
  rewrite <- !app_assoc.
  cbn [app].
  rewrite vstackC_app.
  cbn [vstackC].
  rewrite vstackC_app.
  erewrite wrunc_split
    by (apply ddeep_in4c; apply vstackC_zheaded; apply zheaded0).
  rewrite wrunc_add.
  rewrite (HS 5%nat ((0,1%nat)::(1,2%nat)::(0,1%nat)::(1,2%nat)
                       :: vstackC (repeat 2%nat kk)
                            (vpairC 1 (vstackC (repeat 2%nat (S a'))
                                         (vstackC (zeros (S (S k))) []))))).
  lazy beta iota.
  erewrite wrunc_split by apply ddeep_mint4_sandc.
  rewrite (wrunc_add (2 * kk)).
  rewrite hshift.
  rewrite (dm4_halfc kk 1).
  lazy beta iota.
  cbn [repeat vstackC].
  erewrite wrunc_split by apply dm4_w1_uc.
  rewrite (wrunc_add (2 * a')).
  rewrite hshift.
  rewrite (dm4_halfc a' 1).
  lazy beta iota.
  erewrite wrunc_split by apply ddeep_entry4c.
  erewrite wrunc_split by apply (wcross1c 2).
  rewrite vpush_merge2.
  rewrite wrunc_add.
  replace a' with (List.length (repeat 2%nat a')) at 1 by apply repeat_length.
  rewrite wcross_mixedc.
  lazy beta iota.
  rewrite (vstack_vstackC _ _ (zheaded0 _ _)).
  rewrite rev_repeat.
  rewrite wrunc_S.
  rewrite (wfuelcross 2 2).
  lazy beta iota.
  rewrite (vpairC_vpush 2 _ (vstackC_zheaded _ _ (zheaded0 _ _))).
  rewrite wrunc_S, wstep2.
  lazy beta iota.
  change ((2 + 2)%nat) with 4%nat.
  cbn [wpush sym_eqb].
  rewrite (wrunc_add (2 * List.length (repeat 2%nat a'))).
  rewrite wback_runc.
  lazy beta iota.
  rewrite emit_uword, rev_repeat.
  erewrite wrunc_split by apply (ddeep_redig_uc _ (repeat 2%nat a')).
  erewrite wrunc_split by apply ddeep_fin4c.
  rewrite (ccyc_chainc k 2 1).
  f_equal. f_equal.
  rewrite !csuml_app. cbn [csuml].
  rewrite ?csuml_repeat, ?csuml_zeros.
  cbn [csuml].
  rewrite ?csuml_repeat, ?csuml_zeros.
  unfold ccross, cback.
  rewrite ?Nat2N.inj_succ.
  lia.
Qed.
