  rewrite wrunc_add.
  rewrite (HT 0%nat 5%nat ((0,1%nat)::(1,2%nat)::(0,1%nat)::(1,2%nat)
                       :: vstackC (repeat 2%nat kk)
                            (vpairC 1 (vstackC (repeat 2%nat (S a'))
