Lemma span8orph_soundc (cN V W G : N) (restB cols s sfx : word)
      (f f2 : N) (c1 p1 : nat) (q1 : wside) (Ke : N) :
  (2 <= cN)%N -> (1 <= V)%N -> (1 <= G)%N ->
  (if (1 <? G)%N then [(4,2,(G-1))%N] else []) ++ restB = cols ++ s ->
  ((exists K1 : N, Ke = (K1 + 6)%N
        /\ FTripC c1 K1 (sdec (cols ++ s) f) p1 q1)
   \/ (exists KS : N, Ke = (KS + 3)%N
        /\ SandC c1 KS (sdec (cols ++ s) f) ((1,S p1)::q1))) ->
  wconf [] 0 ((1,S p1)::q1) = wconf [] 0 (sdec sfx f2) ->
  sound_impl_c (cx (28 * cN + 28 * V + 14 * W + 37 + Ke)%N)
    ((2,2,cN)%N :: (4,2,V)%N :: (3,2,1)%N :: (4,2,W)%N
       :: (4,3,1)%N :: (4,2,G)%N :: restB) f
    ([(5,1,1); (4,1,1); (3,1,(cN-2)); (2,2,1); (4,2,(V-1));
      (4,1,1); (3,2,1); (4,2,W); (8,2,1)]%N ++ sfx) f2.
Proof.
  intros HN2 HV1 HG1 HSK HF1 EQ.
  set (k := (N.to_nat cN - 2)%nat).
  set (a' := (N.to_nat V - 1)%nat).
  set (kk := N.to_nat W).
  set (g := (N.to_nat G - 1)%nat).
  assert (EcN : N.to_nat cN = S (S k)) by (unfold k; lia).
  assert (EV : N.to_nat V = S a') by (unfold a'; lia).
  assert (EcN2 : N.to_nat (cN - 2)%N = k) by (unfold k; lia).
  assert (EV2 : N.to_nat (V - 1)%N = a') by (unfold a'; lia).
  assert (EG : N.to_nat G = S g) by (unfold g; lia).
  assert (EG1 : N.to_nat (G - 1)%N = g) by (unfold g; lia).
  assert (ETAIL : pair_runs 4 2 g ++ sdec restB f = sdec (cols ++ s) f).
  { rewrite <- HSK.
    destruct ((1 <? G)%N) eqn:EGb.
    - cbn [app]. rewrite sdec_cons.
      change (N.to_nat 4) with 4%nat.
      change (N.to_nat 2) with 2%nat.
      rewrite EG1. reflexivity.
    - apply N.ltb_ge in EGb.
      assert (EG0 : g = 0%nat) by (unfold g; lia).
      rewrite EG0. cbn [app pair_runs]. reflexivity. }
  assert (EIN : sdec ((2,2,cN)%N :: (4,2,V)%N :: (3,2,1)%N :: (4,2,W)%N
                        :: (4,3,1)%N :: (4,2,G)%N :: restB) f
                = uword (zeros (S (S k)) ++ repeat 2%nat (S a')
                           ++ 1%nat :: repeat 2%nat kk)
                    ((1,4%nat)::(0,3%nat)::(1,4%nat)::(0,2%nat)
                       :: sdec (cols ++ s) f)).
  { rewrite <- ETAIL.
    rewrite uword_app_ms, uword_zeros.
    cbn [uword].
    rewrite uword_app_ms, uword_repeat_w.
    cbn [uword].
    rewrite uword_repeat_w.
    rewrite !sdec_cons.
    rewrite EcN, EV, EG.
    change (N.to_nat 2) with 2%nat.
    change (N.to_nat 3) with 3%nat.
    change (N.to_nat 4) with 4%nat.
    change (N.to_nat 1) with 1%nat.
    change (2 + 1)%nat with 3%nat.
    change (2 + 2)%nat with 4%nat.
    unfold kk.
    cbn [pair_runs app].
    flatapp. reflexivity. }
  assert (EOUT : sdec ([(5,1,1); (4,1,1); (3,1,(cN-2)); (2,2,1); (4,2,(V-1));
                        (4,1,1); (3,2,1); (4,2,W); (8,2,1)]%N ++ sfx) f2
             = cdesc k 2 1
               ((0,2%nat) :: uword (repeat 2%nat a')
                  ((1,4%nat)::(0,1%nat)::(1,3%nat)::(0,2%nat)
                     :: uword (repeat 2%nat kk ++ [6%nat]) (sdec sfx f2)))).
  { rewrite sdec_app.
    rewrite (cdesc_group k 0).
    rewrite uword_repeat_w.
    rewrite uword_app_ms, uword_repeat_w.
    cbn [uword].
    cbn [map gdecode expand].
    rewrite EcN2, EV2.
    change (N.to_nat 5) with 5%nat.
    change (N.to_nat 4) with 4%nat.
    change (N.to_nat 3) with 3%nat.
    change (N.to_nat 2) with 2%nat.
    change (N.to_nat 1) with 1%nat.
    change (N.to_nat 8) with 8%nat.
    change (2 + 2)%nat with 4%nat.
    change (2 + 6)%nat with 8%nat.
    unfold kk.
    cbn [pair_runs app].
    flatapp. reflexivity. }
  unfold sound_impl_c.
  change (sdecode ?x ?y) with (sdec x y).
  rewrite EIN.
  assert (HL : creach (cx (28 * N.of_nat k + 28 * N.of_nat a'
                           + 14 * N.of_nat kk + 121 + Ke)%N)
                 (wconf [] 0
                    (uword (zeros (S (S k)) ++ repeat 2%nat (S a')
                              ++ 1%nat :: repeat 2%nat kk)
                       ((1,4%nat)::(0,3%nat)::(1,4%nat)::(0,2%nat)
                          :: sdec (cols ++ s) f)))
                 (wconf [] 0
                    (cdesc k 2 1
                       ((0,2%nat) :: uword (repeat 2%nat a')
                          ((1,4%nat)::(0,1%nat)::(1,3%nat)::(0,2%nat)
                             :: uword (repeat 2%nat kk ++ [6%nat])
                                  ((1,S p1)::q1)))))).
  { destruct HF1 as [(K1 & EK & HF)|(KS & EK & HS)].
    - pose proof (creach_of_wrunc _ _ _ _ _ _
                    (kernel_deep4_chain1_genc c1 K1 _ p1 q1 k a' kk HF)) as CC.
      cbn [wconf'] in CC.
      refine (creach_cx_eq _ _ _ _ _ CC). lia.
    - pose proof (creach_of_wrunc _ _ _ _ _ _
                    (kernel_deep4_chain1_sandc c1 KS _ p1 q1 k a' kk HS)) as CC.
      cbn [wconf'] in CC.
      refine (creach_cx_eq _ _ _ _ _ CC). lia. }
  rewrite EOUT.
  refine (creach_tgt_eq _ _ _ _
            (wconf_cdesc_cong k 2 1 _ _
               (wconf_cons_cong (0,2%nat) _ _
                  (wconf_uword_cong (repeat 2%nat a') _ _
                     (wconf_cons_cong (1,4%nat) _ _
                        (wconf_cons_cong (0,1%nat) _ _
                           (wconf_cons_cong (1,3%nat) _ _
                              (wconf_cons_cong (0,2%nat) _ _
                                 (wconf_uword_cong
                                    (repeat 2%nat kk ++ [6%nat]) _ _
                                    EQ)))))))) _).
  refine (creach_cx_eq _ _ _ _ _ HL).
  assert (EK : N.of_nat k = (cN - 2)%N)
    by (rewrite <- EcN2, N2Nat.id; reflexivity).
  assert (EA : N.of_nat a' = (V - 1)%N)
    by (rewrite <- EV2, N2Nat.id; reflexivity).
  assert (EW : N.of_nat kk = W) by (unfold kk; rewrite N2Nat.id; reflexivity).
  rewrite EK, EA, EW. lia.
Qed.
Lemma span8orph_closec (cN V W G : N) (restB cols s t2 : word) (f f2 : N) :
  (2 <= cN)%N -> (1 <= V)%N -> (1 <= G)%N ->
  (if (1 <? G)%N then [(4,2,(G-1))%N] else []) ++ restB = cols ++ s ->
  seekb cols = true ->
  fst (cround_at cols s f) = Some (t2, f2) ->
  ~ cempty (snd (cround_at cols s f)) ->
  sound_impl_c (cx (28 * cN + 28 * V + 14 * W + 37
                    + clo (snd (cround_at cols s f)))%N)
    ((2,2,cN)%N :: (4,2,V)%N :: (3,2,1)%N :: (4,2,W)%N
       :: (4,3,1)%N :: (4,2,G)%N :: restB) f
    ([(5,1,1); (4,1,1); (3,1,(cN-2)); (2,2,1); (4,2,(V-1));
      (4,1,1); (3,2,1); (4,2,W); (8,2,1)]%N ++ t2) f2.
Proof.
  intros HN2 HV1 HG1 HSK HC HR HNE.
  set (d1 := cadd (cx (ccolcost ([] : word)))
                  (snd (cround_at cols s f))).
  assert (HD1 : ~ cempty d1) by (apply not_cempty_cadd_cx_l; exact HNE).
  pose proof (cin_of_not_cempty d1 HD1) as Hk1.
  assert (ECLO1 : N.of_nat (N.to_nat (clo d1))
                  = clo (snd (cround_at cols s f)))
    by (rewrite N2Nat.id; unfold d1; reflexivity).
  assert (HSB : seekb ([] : word) = true) by reflexivity.
  destruct (round_at_excc [] cols s f t2 f2 (N.to_nat (clo d1)) HSB HC HR Hk1)
    as [(c1 & p1 & q1 & K1 & EK1 & HF1 & EQ1)
       |(_ & c1 & p1 & q1 & KS & EK1 & HS1 & EQ1)].
  - refine (creach_cx_eq _ _ _ _ _
              (span8orph_soundc cN V W G restB cols s t2 f f2 c1 p1 q1
                 (N.of_nat (N.to_nat (clo d1)))
                 HN2 HV1 HG1 HSK
                 (or_introl (ex_intro _ K1 (conj EK1 HF1))) EQ1)).
    rewrite ECLO1. lia.
  - refine (creach_cx_eq _ _ _ _ _
              (span8orph_soundc cN V W G restB cols s t2 f f2 c1 p1 q1
                 (N.of_nat (N.to_nat (clo d1)))
                 HN2 HV1 HG1 HSK
                 (or_intror (ex_intro _ KS (conj EK1 HS1))) EQ1)).
    rewrite ECLO1. lia.
Qed.
Lemma fr_span8orph_sound_c (w : word) (f : N) (w2 : word) (f2 : N) :
  fr_span8orph w f = Some (ROk w2 f2) ->
  cempty (d_span8orph w f) \/ sound_impl_c (d_span8orph w f) w f w2 f2.
Proof.
  intros E. unfold fr_span8orph in E.
  destruct w as [|[[o1 z1] c1] w1]; [discriminate E|].
  destruct w1 as [|[[o2 z2] c2] wb]; [killmN E|].
  destruct wb as [|[[o3 z3] c3] wc]; [killmN E|].
  destruct wc as [|[[o4 z4] c4] wd]; [killmN E|].
  destruct wd as [|[[o5 z5] c5] we]; [killmN E|].
  destruct we as [|[[o6 z6] c6] restB]; [killmN E|].
  killmN E.
  cbn [d_span8orph].
  destruct (((2 <=? c1) && (1 <=? c2) && (1 <=? c6))%N) eqn:EG3;
    [|left; apply cempty_cundef].
  cbv beta iota zeta in E. try rewrite EG3 in E. cbv beta iota zeta in E.
  apply andb_prop in EG3. destruct EG3 as (EG3a & EG1).
  apply andb_prop in EG3a. destruct EG3a as (EN2 & EV1).
  apply N.leb_le in EN2. apply N.leb_le in EV1. apply N.leb_le in EG1.
  rewrite <- (cround1g_proj ((if (1 <? c6)%N then [(4,2,c6-1)]%N else [])
                            ++ restB) f) in E.
  unfold cround1g in E |- *.
  destruct (seek ((if (1 <? c6)%N then [(4,2,c6-1)]%N else []) ++ restB))
    as [cols s] eqn:ESK.
  destruct (seek_split _ cols s ESK) as (EREST & HCOLS).
  destruct (fst (cround_at cols s f)) as [[t2 g2]|] eqn:ERA;
    [|left; apply cempty_cundef].
  cbv beta iota in E.
  unfold o_ in E. injection E as <- <-.
  destruct (cempty_dec (snd (cround_at cols s f))) as [HE|HE];
    [left; apply cempty_cadd_cx_l; exact HE|].
  right.
  apply (creach_of_clo _ _ _ (not_cempty_cadd_cx_l _ _ HE)).
  rewrite clo_cadd_cx_l.
  exact (span8orph_closec c1 c2 c4 c6 restB cols s t2 f g2
           EN2 EV1 EG1 EREST HCOLS ERA HE).
Qed.
Corollary cfr_span8orph_sound (w : word) (f : N) (w2 : word)
          (f2 : N) (d : cost) :
  cfr_span8orph w f = Some (ROk w2 f2, d) ->
  cempty d \/ sound_impl_c d w f w2 f2.
Proof. apply (decorate_sound_disj _ _ fr_span8orph_sound_c). Qed.
Lemma dcp4_entryc (Z : wside) (n : nat) (r : wside) :
  wrunc 1 ((0,1%nat)::(1,3%nat)::(0,1%nat)::(1,1%nat)::(0,1%nat)::(1,2%nat)::Z)
       1 ((1,S n)::r)
  = Some ((((0,1%nat)::(1,2%nat)::Z), 1,
           (1,5%nat)::(0,1%nat)::(1,S n)::r), 6%N).
Proof.
  apply (ccost_pin _ _ _ _ _ _ (dcp4_entry Z n r)).
  eexists. ckerc.
Qed.
Lemma cp_half2c (ms : list nat) (w b' : nat)
      (c2 : nat) (K2 : N) (Wi : wside) (p2 : nat) (q2 : wside) :
  FTripC c2 K2 Wi p2 q2 ->
  wrunc (2 * List.length ms + b' + c2 + 9)%nat
       (dgmid (repeat 1%nat (S b') ++ (3 + w)%nat :: rev ms)) 0 Wi
  = Some (([], 0,
           uword (0%nat :: ms)
             ((1,(4+w)%nat)::(0,1%nat)::(1,3%nat)::(0,1%nat)
                :: pair_runs' 4%nat 1%nat b'
                ++ (1,5%nat)::(0,1%nat)::(1,3%nat)::(0,2%nat)
                :: (1,S p2)::q2)),
          (K2 + 5 * N.of_nat b' + csuml cback ms + N.of_nat w + 40)%N).
Proof.
  intros HT.
  apply (ccost_pin _ _ _ _ _ _
           (cp_half2 ms w b' c2 Wi p2 q2 (FTripC_FTrip _ _ _ _ _ HT))).
  eexists.
  replace (2 * List.length ms + b' + c2 + 9)%nat
    with (c2 + (3 + (1 + (b' + (3 + (2 * List.length (rev ms) + 2))))))%nat
    by (rewrite length_rev; lia).
  unfold dgmid.
  rewrite wrunc_add.
  rewrite (HT 0%nat 1%nat ((0,1%nat)::(1,4%nat)
                             :: vstackC (repeat 1%nat (S b')
                                  ++ (3 + w)%nat :: rev ms) [])).
  lazy beta iota.
  erewrite wrunc_split by apply (ddeep_redig_uc _ []).
  rewrite vstackC_app, vstackC_repeat1_S.
  erewrite wrunc_split by apply dcp4_entryc.
  rewrite (wrunc_add b').
  rewrite (dcp_runc b').
  lazy beta iota.
  cbn [vstackC].
  rewrite vpairC_3p.
  erewrite wrunc_split by apply (dcp_dischc_u w _ b').
  rewrite (wrunc_add (2 * List.length (rev ms))), wback_runc.
  lazy beta iota.
  rewrite emit_uword, rev_involutive.
  rewrite wrunc_S, wclose1.
  lazy beta iota.
  rewrite wrunc_S, wclose2.
  lazy beta iota.
  rewrite wrunc_0.
  f_equal. f_equal.
  rewrite csuml_rev.
  rewrite ?Nat2N.inj_add.
  lia.
Qed.
Lemma span2B_sound_genOc (a m V G : N) (rest t2 out : word) (f f2 f3 : N)
      (c1 p1 : nat) (q1 : wside) (c2 p2 : nat) (q2 : wside)
      (Ke K2 : N) (Y : wside) :
  (1 <= m)%N -> (1 <= G)%N ->
  ((exists K1 : N, Ke = (K1 + 6)%N
        /\ FTripC c1 K1 (sdec ((4,2,(G-1))%N :: rest) f) p1 q1)
   \/ (exists KS : N, Ke = (KS + 3)%N
        /\ SandC c1 KS (sdec ((4,2,(G-1))%N :: rest) f) ((1,S p1)::q1))) ->
  wconf [] 0 ((1,S p1)::q1) = wconf [] 0 (sdec ((4,2,(G-1))%N :: t2) f2) ->
  FTripC c2 K2 (sdec ((4,2,V)%N :: (8,2,1)%N :: (4,2,(G-1))%N :: t2) f2) p2 q2 ->
  wconf [] 0 ((1,S p2)::q2) = wconf [] 0 Y ->
  sdec out f3
    = uword (0%nat :: zeros (N.to_nat a))
        ((1,4%nat)::(0,1%nat)::(1,3%nat)::(0,1%nat)
           :: pair_runs' 4%nat 1%nat (N.to_nat (m-1)%N)
           ++ (1,5%nat)::(0,1%nat)::(1,3%nat)::(0,2%nat) :: Y) ->
  sound_impl_c (cx (10 * a + 10 * m + 14 * V + 81 + Ke + K2)%N)
    ((2,2,a) :: (5,2,1) :: (3,2,m) :: (2,2,1) :: (4,2,V) :: (4,3,1)
       :: (4,2,G) :: rest)%N f  out f3.
Proof.
  intros Hm HG HF1 EQ1 HF2 EQ2 HOUT.
  set (ms := zeros (N.to_nat a)).
  set (b' := N.to_nat (m-1)%N).
  set (c := N.to_nat V).
  set (g := (N.to_nat G - 1)%nat).
  set (L := (ms ++ 3%nat :: repeat 1%nat (N.to_nat m))).
  assert (Em : N.to_nat m = S b') by (unfold b'; lia).
  assert (EG : N.to_nat G = S g) by (unfold g; lia).
  assert (EG1 : N.to_nat (G - 1)%N = g) by (unfold g; lia).
  assert (ERL : rev L = repeat 1%nat (S b') ++ (3 + 0)%nat :: rev ms).
  { unfold L. rewrite rev_app_distr. cbn [rev].
    rewrite rev_repeat1, <- app_assoc, Em. reflexivity. }
  assert (EIN : sdec ((2,2,a) :: (5,2,1) :: (3,2,m) :: (2,2,1) :: (4,2,V)
                        :: (4,3,1) :: (4,2,G) :: rest)%N f
                = uword (L ++ 0%nat :: repeat 2%nat c)
                    ((1,4%nat)::(0,3%nat)::(1,4%nat)::(0,2%nat)
                       :: sdec ((4,2,(G-1))%N :: rest) f)).
  { unfold L, ms, c.
    rewrite <- app_assoc.
    rewrite uword_app_ms, uword_zeros.
    cbn [app uword].
    rewrite uword_app_ms, uword_repeat_w.
    cbn [app uword].
    rewrite uword_repeat_w.
    rewrite !sdec_cons.
    rewrite EG, EG1.
    change (N.to_nat 2) with 2%nat.
    change (N.to_nat 3) with 3%nat.
    change (N.to_nat 4) with 4%nat.
    change (N.to_nat 5) with 5%nat.
    change (N.to_nat 1) with 1%nat.
    change (2 + 1)%nat with 3%nat.
    change (2 + 2)%nat with 4%nat.
    change (2 + 3)%nat with 5%nat.
    change (2 + 0)%nat with 2%nat.
    cbn [pair_runs app].
    flatapp. reflexivity. }
  assert (EMID : forall (t : word) (ff : N),
             uword (repeat 2%nat c ++ [6%nat]) (sdec ((4,2,(G-1))%N :: t) ff)
             = sdec ((4,2,V)%N :: (8,2,1)%N :: (4,2,(G-1))%N :: t) ff).
  { intros t ff.
    rewrite uword_app_ms, uword_repeat_w.
    cbn [uword].
    rewrite !sdec_cons.
    change (N.to_nat 2) with 2%nat.
    change (N.to_nat 4) with 4%nat.
    change (N.to_nat 8) with 8%nat.
    change (N.to_nat 1) with 1%nat.
    change (2 + 2)%nat with 4%nat.
    unfold c.
    cbn [pair_runs app].
    flatapp. reflexivity. }
  unfold sound_impl_c.
  change (sdecode ?x ?y) with (sdec x y).
  rewrite EIN.
  assert (HL1 : creach (cx (csuml ccross L + 14 * N.of_nat c + 39 + Ke)%N)
                  (wconf [] 0
                     (uword (L ++ 0%nat :: repeat 2%nat c)
                        ((1,4%nat)::(0,3%nat)::(1,4%nat)::(0,2%nat)
                           :: sdec ((4,2,(G-1))%N :: rest) f)))
                  (wconf (dgmid (rev L)) 0
                     (uword (repeat 2%nat c ++ [6%nat]) ((1,S p1)::q1)))).
  { destruct HF1 as [(K1 & EK & HF)|(KS & EK & HS)].
    - pose proof (creach_of_wrunc _ _ _ _ _ _
                    (dg_half1c L c c1 K1 _ p1 q1 HF)) as CC.
      cbn [wconf'] in CC.
      refine (creach_cx_eq _ _ _ _ _ CC). lia.
    - pose proof (creach_of_wrunc _ _ _ _ _ _
                    (dg_half1_sandc L c c1 KS _ p1 q1 HS)) as CC.
      cbn [wconf'] in CC.
      refine (creach_cx_eq _ _ _ _ _ CC). lia. }
  rewrite (wconf_gen_cong (dgmid (rev L)) 0 _ _
             (wconf_uword_cong (repeat 2%nat c ++ [6%nat]) _ _ EQ1)) in HL1.
  rewrite (EMID t2 f2) in HL1.
  rewrite ERL in HL1.
  pose proof (creach_of_wrunc _ _ _ _ _ _
                (cp_half2c ms 0 b' c2 K2
                   (sdec ((4,2,V)%N :: (8,2,1)%N :: (4,2,(G-1))%N :: t2) f2)
                   p2 q2 HF2)) as HL2.
  cbn [wconf'] in HL2.
  rewrite HOUT.
  change (4 + 0)%nat with 4%nat in HL2.
  refine (creach_tgt_eq _ _ _ _
            (wconf_uword_cong (0%nat :: ms) _ _
               (wconf_cons_cong (1,4%nat) _ _
                  (wconf_cons_cong (0,1%nat) _ _
                     (wconf_cons_cong (1,3%nat) _ _
                        (wconf_cons_cong (0,1%nat) _ _
                           (wconf_app_cong (pair_runs' 4%nat 1%nat b') _ _
                              (wconf_cons_cong (1,5%nat) _ _
                                 (wconf_cons_cong (0,1%nat) _ _
                                    (wconf_cons_cong (1,3%nat) _ _
                                       (wconf_cons_cong (0,2%nat) _ _
                                          EQ2)))))))))) _).
  refine (creach_cx_eq _ _ _ _ _ (creach_cx_trans _ _ _ _ _ HL1 HL2)).
  assert (ECL : csuml ccross L = (4 * a + 5 * m + 7)%N).
  { unfold L, ms. rewrite csuml_app. cbn [csuml].
    rewrite csuml_zeros, csuml_repeat. unfold ccross.
    change (N.of_nat 0) with 0%N.
    change (N.of_nat 1) with 1%N.
    change (N.of_nat 3) with 3%N.
    rewrite !N2Nat.id. lia. }
  assert (ECB : csuml cback ms = (6 * a)%N).
  { unfold ms. rewrite csuml_zeros. unfold cback.
    change (N.of_nat 0) with 0%N. rewrite N2Nat.id. lia. }
  assert (EB : N.of_nat b' = (m - 1)%N)
    by (unfold b'; rewrite N2Nat.id; reflexivity).
  assert (EC : N.of_nat c = V) by (unfold c; rewrite N2Nat.id; reflexivity).
  rewrite ECL, ECB, EB, EC.
  change (N.of_nat 0) with 0%N.
  lia.
Qed.
Lemma span2B_sound_genc (a m V G : N) (rest t2 t3 : word) (f f2 f3 : N)
      (c1 p1 : nat) (q1 : wside) (c2 p2 : nat) (q2 : wside) (Ke K2 : N) :
  (1 <= m)%N -> (1 <= G)%N ->
  ((exists K1 : N, Ke = (K1 + 6)%N
        /\ FTripC c1 K1 (sdec ((4,2,(G-1))%N :: rest) f) p1 q1)
   \/ (exists KS : N, Ke = (KS + 3)%N
        /\ SandC c1 KS (sdec ((4,2,(G-1))%N :: rest) f) ((1,S p1)::q1))) ->
  wconf [] 0 ((1,S p1)::q1) = wconf [] 0 (sdec ((4,2,(G-1))%N :: t2) f2) ->
  FTripC c2 K2 (sdec ((4,2,V)%N :: (8,2,1)%N :: (4,2,(G-1))%N :: t2) f2) p2 q2 ->
  wconf [] 0 ((1,S p2)::q2)
    = wconf [] 0 (sdec ((4,2,V)%N :: (8,2,1)%N :: (4,2,(G-1))%N :: t3) f3) ->
  sound_impl_c (cx (10 * a + 10 * m + 14 * V + 81 + Ke + K2)%N)
    ((2,2,a) :: (5,2,1) :: (3,2,m) :: (2,2,1) :: (4,2,V) :: (4,3,1)
       :: (4,2,G) :: rest)%N f
    ([(2,2,a+1); (4,1,1); (3,1,1); (4,1,m-1);
      (5,1,1); (3,2,1); (4,2,V); (8,2,1); (4,2,G-1)]%N ++ t3) f3.
Proof.
  intros Hm HG HF1 EQ1 HF2 EQ2.
  refine (span2B_sound_genOc a m V G rest t2 _ f f2 f3 c1 p1 q1 c2 p2 q2
            Ke K2 _ Hm HG HF1 EQ1 HF2 EQ2 _).
  assert (EOUT : sdec ([(2,2,a+1); (4,1,1); (3,1,1); (4,1,m-1);
                        (5,1,1); (3,2,1); (4,2,V); (8,2,1); (4,2,G-1)]%N
                       ++ t3) f3
                 = uword (0%nat :: zeros (N.to_nat a))
                     ((1,4%nat)::(0,1%nat)::(1,3%nat)::(0,1%nat)
                        :: pair_runs' 4%nat 1%nat (N.to_nat (m-1)%N)
                        ++ (1,5%nat)::(0,1%nat)::(1,3%nat)::(0,2%nat)
                        :: sdec ((4,2,V)%N :: (8,2,1)%N :: (4,2,(G-1))%N
                                   :: t3) f3)).
  { rewrite pair_runs'_eq.
    cbn [uword].
    rewrite uword_zeros.
    rewrite ?sdec_app, ?sdec_cons.
    cbn [map gdecode expand].
    assert (Ea : N.to_nat (a+1)%N = S (N.to_nat a)) by lia.
    rewrite Ea.
    change (N.to_nat 2) with 2%nat.
    change (N.to_nat 3) with 3%nat.
    change (N.to_nat 4) with 4%nat.
    change (N.to_nat 5) with 5%nat.
    change (N.to_nat 8) with 8%nat.
    change (N.to_nat 1) with 1%nat.
    change (2 + 2)%nat with 4%nat.
    cbn [pair_runs app].
    flatapp. reflexivity. }
  exact EOUT.
Qed.
Lemma span2Bg_closec (a m V G : N) (rest t3 : word) (f f3 : N) :
  (1 <= m)%N -> (1 <= G)%N ->
  fst (cround2g rest f) = Some (t3, f3) ->
  ~ cempty (snd (cround2g rest f)) ->
  sound_impl_c (cx (10 * a + 10 * m + 28 * V + 28 * (G-1) + 97
                    + clo (snd (cround2g rest f)))%N)
    ((2,2,a) :: (5,2,1) :: (3,2,m) :: (2,2,1) :: (4,2,V) :: (4,3,1)
       :: (4,2,G) :: rest)%N f
    ([(2,2,a+1); (4,1,1); (3,1,1); (4,1,m-1);
      (5,1,1); (3,2,1); (4,2,V); (8,2,1); (4,2,G-1)]%N ++ t3) f3.
Proof.
  intros Hm HG HR HNE.
  unfold cround2g in HR, HNE |- *.
  destruct (seek rest) as [cols s] eqn:ESK.
  destruct (seek_split rest cols s ESK) as (EREST & HCOLS).
  destruct (fst (cround_at cols s f)) as [[t2 f2]|] eqn:ERA;
    [|cbn [snd] in HNE; exfalso; apply HNE; apply cempty_cundef].
  destruct (seek t2) as [cols2 s2] eqn:ESK2.
  destruct (seek_split t2 cols2 s2 ESK2) as (ET2 & HCOLS2).
  destruct s2 as [|g2 s2'].
  {
    rewrite app_nil_r in ET2. subst t2.
    cbn [fst snd] in HR, HNE |- *.
    assert (HE1 : ~ cempty (snd (cround_at cols s f)))
      by (apply (cadds_not_cempty_l _ _ HNE)).
    assert (HE2 := cadds_not_cempty_r _ _ HNE).
    rewrite (cadds_live _ _ HE1 HE2), clo_cadd.
    set (d1 := cadd (cx (ccolcost [(4,2,(G-1))%N]))
                    (snd (cround_at cols s f))).
    assert (HD1 : ~ cempty d1) by (apply not_cempty_cadd_cx_l; exact HE1).
    pose proof (cin_of_not_cempty d1 HD1) as Hk1.
    assert (ECLO1 : (N.of_nat (N.to_nat (clo d1))
                     = ccolcost [(4,2,(G-1))%N]
                       + clo (snd (cround_at cols s f)))%N)
      by (rewrite N2Nat.id; reflexivity).
    assert (HEX1 : exists (c1 p1 : nat) (q1 : wside),
               ((exists K1 : N, N.of_nat (N.to_nat (clo d1)) = (K1 + 6)%N
                     /\ FTripC c1 K1 (sdec ((4,2,(G-1))%N :: rest) f) p1 q1)
                \/ (exists KS : N, N.of_nat (N.to_nat (clo d1)) = (KS + 3)%N
                     /\ SandC c1 KS (sdec ((4,2,(G-1))%N :: rest) f)
                          ((1,S p1)::q1)))
               /\ wconf [] 0 ((1,S p1)::q1)
                  = wconf [] 0 (sdec ((4,2,(G-1))%N :: cols2) f2)).
    { destruct (round_at_excc [(4,2,(G-1))%N] cols s f cols2 f2
                  (N.to_nat (clo d1)) (seekb_42 _) HCOLS ERA Hk1)
        as [(c1 & p1 & q1 & K1 & EK1 & HF1 & EQ1)
           |(_ & c1 & p1 & q1 & K1 & EK1 & HS1 & EQ1)].
      - exists c1, p1, q1. cbn [app] in HF1, EQ1.
        rewrite <- EREST in HF1.
        split; [left; exists K1; split; [exact EK1|exact HF1]|exact EQ1].
      - exists c1, p1, q1. cbn [app] in HS1, EQ1.
        rewrite <- EREST in HS1.
        split; [right; exists K1; split; [exact EK1|exact HS1]|exact EQ1]. }
    destruct HEX1 as (c1 & p1 & q1 & HF1 & EQ1).
    destruct (round2g_nil_exc2c V G cols2 t3 f2 f3 HCOLS2 HR HE2)
      as (c2 & p2 & q2 & K2 & EK2 & HF2 & EQ2).
    refine (creach_cx_eq _ _ _ _ _
              (span2B_sound_genc a m V G rest cols2 t3 f f2 f3
                 c1 p1 q1 c2 p2 q2 _ K2 Hm HG HF1 EQ1 HF2 EQ2)).
    cbn [ccolcost gC gO] in ECLO1, EK2.
    rewrite ECLO1 in *. lia. }
  cbn [fst snd] in HR, HNE |- *.
  assert (HE1 : ~ cempty (snd (cround_at cols s f)))
    by (apply (cadds_not_cempty_l _ _ HNE)).
  assert (HE2 : ~ cempty (snd (cround_at cols2 (g2 :: s2') f2)))
    by (apply (cadds_not_cempty_r _ _ HNE)).
  rewrite (cadds_live _ _ HE1 HE2), clo_cadd.
  set (d1 := cadd (cx (ccolcost [(4,2,(G-1))%N]))
                  (snd (cround_at cols s f))).
  assert (HD1 : ~ cempty d1) by (apply not_cempty_cadd_cx_l; exact HE1).
  pose proof (cin_of_not_cempty d1 HD1) as Hk1.
  assert (ECLO1 : (N.of_nat (N.to_nat (clo d1))
                   = ccolcost [(4,2,(G-1))%N]
                     + clo (snd (cround_at cols s f)))%N)
    by (rewrite N2Nat.id; reflexivity).
  assert (HEX1 : exists (c1 p1 : nat) (q1 : wside),
             ((exists K1 : N, N.of_nat (N.to_nat (clo d1)) = (K1 + 6)%N
                   /\ FTripC c1 K1 (sdec ((4,2,(G-1))%N :: rest) f) p1 q1)
              \/ (exists KS : N, N.of_nat (N.to_nat (clo d1)) = (KS + 3)%N
                   /\ SandC c1 KS (sdec ((4,2,(G-1))%N :: rest) f)
                        ((1,S p1)::q1)))
             /\ wconf [] 0 ((1,S p1)::q1)
                = wconf [] 0 (sdec ((4,2,(G-1))%N :: t2) f2)).
  { destruct (round_at_excc [(4,2,(G-1))%N] cols s f t2 f2
                (N.to_nat (clo d1)) (seekb_42 _) HCOLS ERA Hk1)
      as [(c1 & p1 & q1 & K1 & EK1 & HF1 & EQ1)
         |(_ & c1 & p1 & q1 & K1 & EK1 & HS1 & EQ1)].
    - exists c1, p1, q1. cbn [app] in HF1, EQ1.
      rewrite <- EREST in HF1.
      split; [left; exists K1; split; [exact EK1|exact HF1]|exact EQ1].
    - exists c1, p1, q1. cbn [app] in HS1, EQ1.
      rewrite <- EREST in HS1.
      split; [right; exists K1; split; [exact EK1|exact HS1]|exact EQ1]. }
  destruct HEX1 as (c1 & p1 & q1 & HF1 & EQ1).
  set (d2 := cadd (cx (ccolcost [(4,2,V); (8,2,1); (4,2,(G-1))]%N))
                  (snd (cround_at cols2 (g2 :: s2') f2))).
  assert (HD2 : ~ cempty d2) by (apply not_cempty_cadd_cx_l; exact HE2).
  pose proof (cin_of_not_cempty d2 HD2) as Hk2.
  assert (ECLO2 : (N.of_nat (N.to_nat (clo d2))
                   = ccolcost [(4,2,V); (8,2,1); (4,2,(G-1))]%N
                     + clo (snd (cround_at cols2 (g2 :: s2') f2)))%N)
    by (rewrite N2Nat.id; reflexivity).
  destruct (round_at_excc [(4,2,V); (8,2,1); (4,2,(G-1))]%N cols2
              (g2 :: s2') f2 t3 f3 (N.to_nat (clo d2))
              (seekb_pre2 _ _) HCOLS2 HR Hk2)
    as [(c2 & p2 & q2 & K2 & EK2 & HF2 & EQ2)
       |(ENIL & _)].
  2:{ exfalso. revert ENIL.
      cbn [map gdecode expand app].
      change (N.to_nat 8) with 8%nat.
      change (N.to_nat 2) with 2%nat.
      destruct (N.to_nat V); cbn [pair_runs app]; discriminate. }
  cbn [app] in HF2, EQ2.
  rewrite <- ET2 in HF2.
  refine (creach_cx_eq _ _ _ _ _
            (span2B_sound_genc a m V G rest t2 t3 f f2 f3 c1 p1 q1 c2 p2 q2
               _ K2 Hm HG HF1 EQ1 HF2 EQ2)).
  cbn [ccolcost gC gO] in ECLO1, ECLO2.
  rewrite ECLO1 in *.
  lia.
Qed.
Lemma fr_span2B_sound_c (w : word) (f : N) (w2 : word) (f2 : N) :
  fr_span2B w f = Some (ROk w2 f2) ->
  cempty (d_span2B w f) \/ sound_impl_c (d_span2B w f) w f w2 f2.
Proof.
  intros E. unfold fr_span2B in E.
  destruct w as [|[[o1 z1] c1] w1]; [discriminate E|].
  destruct w1 as [|[[o2 z2] c2] wb]; [killmN E|].
  destruct wb as [|[[o3 z3] c3] wc]; [killmN E|].
  destruct wc as [|[[o4 z4] c4] wd]; [killmN E|].
  destruct wd as [|[[o5 z5] c5] we]; [killmN E|].
  destruct we as [|[[o6 z6] c6] wf]; [killmN E|].
  destruct wf as [|[[o7 z7] c7] restB]; [killmN E|].
  killmN E.
  cbn [d_span2B].
  destruct (((1 <=? c3) && (1 <=? c7))%N) eqn:EG2;
    [|left; apply cempty_cundef].
  cbv beta iota zeta in E. try rewrite EG2 in E. cbv beta iota zeta in E.
  apply andb_prop in EG2. destruct EG2 as (EM1 & EG1).
  apply N.leb_le in EM1. apply N.leb_le in EG1.
  rewrite <- (cround2g_proj restB f) in E.
  destruct (fst (cround2g restB f)) as [[t3 f3]|] eqn:ER2;
    [|left; apply cempty_cundef].
  cbv beta iota in E.
  unfold o_ in E. injection E as <- <-.
  destruct (cempty_dec (snd (cround2g restB f))) as [HE|HE];
    [left; apply cempty_cadd_cx_l; exact HE|].
  right.
  apply (creach_of_clo _ _ _ (not_cempty_cadd_cx_l _ _ HE)).
  rewrite clo_cadd_cx_l.
  exact (span2Bg_closec c1 c3 c5 c7 restB t3 f f3 EM1 EG1 ER2 HE).
Qed.
Corollary cfr_span2B_sound (w : word) (f : N) (w2 : word)
          (f2 : N) (d : cost) :
  cfr_span2B w f = Some (ROk w2 f2, d) ->
  cempty d \/ sound_impl_c d w f w2 f2.
Proof. apply (decorate_sound_disj _ _ fr_span2B_sound_c). Qed.
Theorem cstep_front_sound (w : word) (f : N) (w2 : word)
        (f2 : N) (d : cost) :
  cstep_front w f = Some (ROk w2 f2, d) ->
  cempty d \/ sound_impl_c d w f w2 f2.
Proof.
  intros E.
  unfold cstep_front in E.
  rewrite cfront_rules_unfold in E.
  cbn [cfirst_rule] in E.
  destruct (cfr_primordial w f) as [x|] eqn:E1.
  { injection E as E'; subst x; right.
    exact (cfr_primordial_sound _ _ _ _ _ E1). }
  destruct (cfr_prim4 w f) as [x|] eqn:E2.
  { injection E as E'; subst x; right.
    exact (cfr_prim4_sound _ _ _ _ _ E2). }
  destruct (cfr_clean w f) as [x|] eqn:E3.
  { injection E as E'; subst x; right.
    exact (cfr_clean_sound _ _ _ _ _ E3). }
  destruct (cfr_four w f) as [x|] eqn:E4.
  { injection E as E'; subst x; right.
    exact (cfr_four_sound _ _ _ _ _ E4). }
  destruct (cfr_span2A w f) as [x|] eqn:E5.
  { injection E as E'; subst x.
    exact (cfr_span2A_sound _ _ _ _ _ E5). }
  destruct (cfr_span2A' w f) as [x|] eqn:E6.
  { injection E as E'; subst x; right.
    exact (cfr_span2A'_sound _ _ _ _ _ E6). }
  destruct (cfr_span2C' w f) as [x|] eqn:E7.
  { injection E as E'; subst x; right.
    exact (cfr_span2C'_sound _ _ _ _ _ E7). }
  destruct (cfr_span8far w f) as [x|] eqn:E8.
  { injection E as E'; subst x; right.
    exact (cfr_span8far_sound _ _ _ _ _ E8). }
  destruct (cfr_span2B w f) as [x|] eqn:E9.
  { injection E as E'; subst x.
    exact (cfr_span2B_sound _ _ _ _ _ E9). }
  destruct (cfr_span8orph w f) as [x|] eqn:E10.
  { injection E as E'; subst x.
    exact (cfr_span8orph_sound _ _ _ _ _ E10). }
  destruct (cfr_span8 w f) as [x|] eqn:E11.
  { injection E as E'; subst x.
    exact (cfr_span8_sound _ _ _ _ _ E11). }
  destruct (cfr_rot w f) as [x|] eqn:E12.
  { injection E as E'; subst x; right.
    exact (cfr_rot_sound _ _ _ _ _ E12). }
  destruct (cfr_502 w f) as [x|] eqn:E13.
  { injection E as E'; subst x; right.
    exact (cfr_502_sound _ _ _ _ _ E13). }
  destruct (cfr_512 w f) as [x|] eqn:E14.
  { injection E as E'; subst x; right.
    exact (cfr_512_sound _ _ _ _ _ E14). }
  destruct (cfr_522 w f) as [x|] eqn:E15.
  { injection E as E'; subst x; right.
    exact (cfr_522_sound _ _ _ _ _ E15). }
  discriminate E.
Qed.
Theorem cstep_sound_bank (w : word) (f : N) (h : nat)
        (w' : word) (f' : N) (i : nat) (d : cost) :
  cstep w f h = (ROk w' f', i, d) ->
  cempty d \/ sound_impl_c d w f w' f'.
Proof.
  intros HS. unfold cstep in HS.
  destruct (cstep_front w f) as [[r dd]|] eqn:EF.
  - destruct r as [wq fq| |]; try discriminate HS.
    assert (Ed : dd = d) by (exact (f_equal snd HS)).
    destruct (cstep_front_sound w f wq fq dd EF) as [Hc|Hs].
    + left. rewrite <- Ed. exact Hc.
    + right.
      assert (Ew : normalize wq = w')
        by (exact (f_equal (fun x => match fst (fst x) with
                                     | ROk y _ => y
                                     | _ => w' end) HS)).
      assert (Ef : fq = f')
        by (exact (f_equal (fun x => match fst (fst x) with
                                     | ROk _ y => y
                                     | _ => f' end) HS)).
      rewrite <- Ed, <- Ew, <- Ef.
      apply sound_impl_c_normalize. exact Hs.
  -
    destruct (step_after_front None w f h) as [r i2] eqn:E2.
    destruct r as [wq fq| |]; [|discriminate HS|discriminate HS].
    assert (Ed : d_comp w f h = d) by (exact (f_equal snd HS)).
    assert (Ew : wq = w')
      by (exact (f_equal (fun x => match fst (fst x) with
                                   | ROk y _ => y
                                   | _ => w' end) HS)).
    assert (Ef : fq = f')
      by (exact (f_equal (fun x => match fst (fst x) with
                                   | ROk _ y => y
                                   | _ => f' end) HS)).
    rewrite <- Ed. subst wq fq.
    exact (d_comp_sound w f h w' f' i2 E2).
Qed.
