Local Open Scope N_scope.
Definition cyc_clean (K : N) : N :=
  63 * ((K / 2) * (K / 2 - 1)) + 243 * (K / 2).
Definition cyc_four (c M : N) : N :=
  108 * ((M / 2) * (M / 2 - 1)) + (40 * c + 184) * (M / 2).
Inductive fcarm : Type :=
  | FCnone
  | FCclean (ac K : N)
  | FCfour  (ac c M : N).
Definition fcsplit (w : word) : fcarm :=
  match w with
  | (2,2,cN) :: (4,1,1) :: (k,1,1) :: (4,1,M) :: _ =>
      if 2 <=? M then
        (if k =? 1 then FCfour (10 * cN + 17) (cN + 1) M
         else if k =? 2 then FCfour (20 * cN + 44) (cN + 2) M
         else if k =? 3 then FCfour (30 * cN + 81) (cN + 3) M
         else FCnone)
      else FCnone
  | (2,2,cN) :: (5,1,1) :: (k,1,1) :: (3,1,K) :: _ =>
      if (cN + k =? 4) && (2 <=? K) then
        (if k =? 1 then FCclean 49 K
         else if k =? 2 then FCclean 88 K
         else FCnone)
      else FCnone
  | (2,2,cN) :: (5,1,1) :: (3,1,K) :: _ =>
      if (cN =? 1) && (3 <=? K) then FCclean 117 (K - 1) else FCnone
  | (5,1,1) :: (4,1,1) :: (3,1,K) :: _ =>
      if 2 <=? K then FCclean 136 K else FCnone
  | _ => FCnone
  end.
Definition dfc (w : word) (_ : N) : cost :=
  match fcsplit w with
  | FCnone => cundef
  | FCclean ac K => cx (ac + cyc_clean K)
  | FCfour ac c M => cx (ac + cyc_four c M)
  end.
Close Scope N_scope.
Local Open Scope N_scope.
Lemma odd_mod2 (K : N) : N.odd K = (K mod 2 =? 1).
Proof. rewrite <- N.bit0_odd. apply N.bit0_eqb. Qed.
Close Scope N_scope.
Definition Qclean (K : N) : word :=
  [(2,2,3 * N.div2 K + 4); (5,2,1); (3,2,N.div2 K)]%N
  ++ (if N.odd K then [(3,1,1)%N] else []).
Definition Qfour (n M : N) : word :=
  if N.odd M
  then [(2,2,n+2*(M-1)); (4,2,N.div2 (M+1)); (4,1,1)]%N
  else [(2,2,n+2*M); (4,2,N.div2 M+1)]%N.
Lemma clean_cyc_c (K : N) (t : word) (f : N) :
  (2 <= K)%N ->
  sound_impl_c (cx (cyc_clean K))
    ((2,2,4)%N :: (5,2,1)%N :: (3,1,K)%N :: t) f (Qclean K ++ t) f.
Proof.
  intros HK. unfold cyc_clean, Qclean.
  rewrite !N.div2_div, odd_mod2, <- app_assoc.
  exact (clean_sound_c K t f HK).
Qed.
Lemma four_cyc_c (n M : N) (t : word) (f : N) :
  (2 <= M)%N ->
  sound_impl_c (cx (cyc_four n M))
    ((2,2,n)%N :: (4,2,1)%N :: (4,1,M)%N :: t) f (Qfour n M ++ t) f.
Proof.
  intros HM. unfold cyc_four, Qfour.
  rewrite odd_mod2.
  destruct ((M mod 2 =? 1)%N) eqn:EM.
  - cbn [app].
    replace (N.div2 (M+1))%N with ((M+1)/2)%N
      by (symmetry; apply N.div2_div).
    assert (EM1 : (M mod 2 = 1)%N) by (apply N.eqb_eq; exact EM).
    exact (four_sound_c_odd n M t f HM EM1).
  - cbn [app].
    assert (EM0 : (M mod 2 = 0)%N).
    { apply N.eqb_neq in EM. pose proof (N.mod_lt M 2 ltac:(lia)). lia. }
    replace (N.div2 M)%N with (M/2)%N by (symmetry; apply N.div2_div).
    exact (four_sound_c_even n M t f HM EM0).
Qed.
Lemma fcc_522_1 (c M : N) (t : word) (f : N) :
  (2 <= M)%N ->
  sound_impl_c (cx (10 * c + 17 + cyc_four (c + 1) M)%N)
    ((2,2,c)%N :: (4,1,1)%N :: (1,1,1)%N :: (4,1,M)%N :: t) f
    (Qfour (c+1)%N M ++ t) f.
Proof.
  intros HM.
  assert (H1 : fr_522 ((2,2,c)%N :: (4,1,1)%N :: (1,1,1)%N
                            :: (4,1,M)%N :: t) f
             = Some (ROk ((2,2,c+1)%N :: (4,2,1)%N
                               :: (4,1,M)%N :: t) f)) by reflexivity.
  pose proof (fr_522_sound_c _ _ _ _ H1) as S1.
  change (d_522 ((2,2,c)%N :: (4,1,1)%N :: (1,1,1)%N
                       :: (4,1,M)%N :: t) f)
    with (cx (10 * c + 17)%N) in S1.
  pose proof (four_cyc_c (c+1)%N M t f HM) as S2.
  exact (sound_impl_c_trans _ _ _ _ _ _ _ _ S1 S2).
Qed.
Lemma fcc_522_2 (c M : N) (t : word) (f : N) :
  (2 <= M)%N ->
  sound_impl_c (cx (20 * c + 44 + cyc_four (c + 2) M)%N)
    ((2,2,c)%N :: (4,1,1)%N :: (2,1,1)%N :: (4,1,M)%N :: t) f
    (Qfour (c+2)%N M ++ t) f.
Proof.
  intros HM.
  assert (H1 : fr_522 ((2,2,c)%N :: (4,1,1)%N :: (2,1,1)%N
                            :: (4,1,M)%N :: t) f
             = Some (ROk ((2,2,c+1)%N :: (4,1,1)%N :: (1,1,1)%N
                               :: (4,1,M)%N :: t) f)) by reflexivity.
  pose proof (fr_522_sound_c _ _ _ _ H1) as S1.
  change (d_522 ((2,2,c)%N :: (4,1,1)%N :: (2,1,1)%N
                       :: (4,1,M)%N :: t) f)
    with (cx (10 * c + 17)%N) in S1.
  pose proof (fcc_522_1 (c+1)%N M t f HM) as S2.
  replace ((c+1)+1)%N with (c+2)%N in S2 by lia.
  pose proof (sound_impl_c_trans _ _ _ _ _ _ _ _ S1 S2) as S3.
  rewrite cadd_cx in S3.
  assert (EA : forall X : N, (10 * c + 17 + (10 * (c+1) + 17 + X)
                              = 20 * c + 44 + X)%N) by (intros; lia).
  rewrite (EA (cyc_four (c+2)%N M)) in S3.
  exact S3.
Qed.
Lemma fcc_522_3 (c M : N) (t : word) (f : N) :
  (2 <= M)%N ->
  sound_impl_c (cx (30 * c + 81 + cyc_four (c + 3) M)%N)
    ((2,2,c)%N :: (4,1,1)%N :: (3,1,1)%N :: (4,1,M)%N :: t) f
    (Qfour (c+3)%N M ++ t) f.
Proof.
  intros HM.
  assert (H1 : fr_522 ((2,2,c)%N :: (4,1,1)%N :: (3,1,1)%N
                            :: (4,1,M)%N :: t) f
             = Some (ROk ((2,2,c+1)%N :: (4,1,1)%N :: (2,1,1)%N
                               :: (4,1,M)%N :: t) f)) by reflexivity.
  pose proof (fr_522_sound_c _ _ _ _ H1) as S1.
  change (d_522 ((2,2,c)%N :: (4,1,1)%N :: (3,1,1)%N
                       :: (4,1,M)%N :: t) f)
    with (cx (10 * c + 17)%N) in S1.
  pose proof (fcc_522_2 (c+1)%N M t f HM) as S2.
  replace ((c+1)+2)%N with (c+3)%N in S2 by lia.
  pose proof (sound_impl_c_trans _ _ _ _ _ _ _ _ S1 S2) as S3.
  rewrite cadd_cx in S3.
  assert (EA : forall X : N, (10 * c + 17 + (20 * (c+1) + 44 + X)
                              = 30 * c + 81 + X)%N) by (intros; lia).
  rewrite (EA (cyc_four (c+3)%N M)) in S3.
  exact S3.
Qed.
Lemma fcc_512_1 (K : N) (t : word) (f : N) :
  (2 <= K)%N ->
  sound_impl_c (cx (49 + cyc_clean K)%N)
    ((2,2,3)%N :: (5,1,1)%N :: (1,1,1)%N :: (3,1,K)%N :: t) f
    (Qclean K ++ t) f.
Proof.
  intros HK.
  assert (H1 : fr_512 ((2,2,3)%N :: (5,1,1)%N :: (1,1,1)%N
                            :: (3,1,K)%N :: t) f
             = Some (ROk ((2,2,4)%N :: (5,2,1)%N
                               :: (3,1,K)%N :: t) f)) by reflexivity.
  pose proof (fr_512_sound_c _ _ _ _ H1) as S1.
  change (d_512 ((2,2,3)%N :: (5,1,1)%N :: (1,1,1)%N
                       :: (3,1,K)%N :: t) f) with (cx 49%N) in S1.
  pose proof (clean_cyc_c K t f HK) as S2.
  exact (sound_impl_c_trans _ _ _ _ _ _ _ _ S1 S2).
Qed.
Lemma fcc_512_2 (K : N) (t : word) (f : N) :
  (2 <= K)%N ->
  sound_impl_c (cx (88 + cyc_clean K)%N)
    ((2,2,2)%N :: (5,1,1)%N :: (2,1,1)%N :: (3,1,K)%N :: t) f
    (Qclean K ++ t) f.
Proof.
  intros HK.
  assert (H1 : fr_512 ((2,2,2)%N :: (5,1,1)%N :: (2,1,1)%N
                            :: (3,1,K)%N :: t) f
             = Some (ROk ((2,2,3)%N :: (5,1,1)%N :: (1,1,1)%N
                               :: (3,1,K)%N :: t) f)) by reflexivity.
  pose proof (fr_512_sound_c _ _ _ _ H1) as S1.
  change (d_512 ((2,2,2)%N :: (5,1,1)%N :: (2,1,1)%N
                       :: (3,1,K)%N :: t) f) with (cx 39%N) in S1.
  pose proof (fcc_512_1 K t f HK) as S2.
  pose proof (sound_impl_c_trans _ _ _ _ _ _ _ _ S1 S2) as S3.
  rewrite cadd_cx in S3.
  assert (EA : forall X : N, (39 + (49 + X) = 88 + X)%N) by (intros; lia).
  rewrite (EA (cyc_clean K)) in S3. exact S3.
Qed.
Lemma fcc_502 (K : N) (t : word) (f : N) :
  (3 <= K)%N ->
  sound_impl_c (cx (117 + cyc_clean (K - 1))%N)
    ((2,2,1)%N :: (5,1,1)%N :: (3,1,K)%N :: t) f
    (Qclean (K-1)%N ++ t) f.
Proof.
  intros HK.
  assert (E1 : (K =? 1)%N = false) by (apply N.eqb_neq; lia).
  assert (E2 : (2 <=? K)%N = true) by (apply N.leb_le; lia).
  assert (H1 : fr_502 ((2,2,1)%N :: (5,1,1)%N :: (3,1,K)%N :: t) f
             = Some (ROk ((2,2,2)%N :: (5,1,1)%N :: (2,1,1)%N
                               :: (3,1,K-1)%N :: t) f)).
  { unfold fr_502. cbv beta iota zeta. rewrite E1, E2.
    unfold o_. reflexivity. }
  pose proof (fr_502_sound_c _ _ _ _ H1) as S1.
  change (d_502 ((2,2,1)%N :: (5,1,1)%N :: (3,1,K)%N :: t) f)
    with (cx 29%N) in S1.
  pose proof (fcc_512_2 (K-1)%N t f ltac:(lia)) as S2.
  pose proof (sound_impl_c_trans _ _ _ _ _ _ _ _ S1 S2) as S3.
  rewrite cadd_cx in S3.
  assert (EA : forall X : N, (29 + (88 + X) = 117 + X)%N) by (intros; lia).
  rewrite (EA (cyc_clean (K-1)%N)) in S3. exact S3.
Qed.
Lemma fcc_rot (K : N) (t : word) (f : N) :
  (2 <= K)%N ->
  sound_impl_c (cx (136 + cyc_clean K)%N)
    ((5,1,1)%N :: (4,1,1)%N :: (3,1,K)%N :: t) f
    (Qclean K ++ t) f.
Proof.
  intros HK.
  assert (H1 : fr_rot ((5,1,1)%N :: (4,1,1)%N :: (3,1,K)%N :: t) f
             = Some (ROk ((2,2,1)%N :: (5,1,1)%N
                               :: (3,1,K+1)%N :: t) f)) by reflexivity.
  pose proof (fr_rot_sound_c _ _ _ _ H1) as S1.
  change (d_rot ((5,1,1)%N :: (4,1,1)%N :: (3,1,K)%N :: t) f)
    with (cx 19%N) in S1.
  pose proof (fcc_502 (K+1)%N t f ltac:(lia)) as S2.
  replace ((K+1)-1)%N with K in S2 by lia.
  pose proof (sound_impl_c_trans _ _ _ _ _ _ _ _ S1 S2) as S3.
  rewrite cadd_cx in S3.
  assert (EA : forall X : N, (19 + (117 + X) = 136 + X)%N) by (intros; lia).
  rewrite (EA (cyc_clean K)) in S3. exact S3.
Qed.
Local Open Scope N_scope.
Lemma shiftr_shiftl_le (x e : N) : N.shiftl (N.shiftr x e) e <= x.
Proof.
  rewrite N.shiftr_div_pow2, N.shiftl_mul_pow2, N.mul_comm.
  apply N.mul_div_le. apply N.pow_nonzero. discriminate.
Qed.
Lemma shiftr_shiftl_lt (x e : N) : x < N.shiftl (N.shiftr x e + 1) e.
Proof.
  rewrite N.shiftr_div_pow2, N.shiftl_mul_pow2.
  assert (HP : 2 ^ e <> 0) by (apply N.pow_nonzero; discriminate).
  pose proof (N.div_mod x (2 ^ e) HP) as HD.
  pose proof (N.mod_lt x (2 ^ e) HP) as HM.
  nia.
Qed.
Lemma shiftl_mul_split3 (a b c e g : N) :
  N.shiftl (a * b * c) (e + g) = a * N.shiftl b e * N.shiftl c g.
Proof. rewrite !N.shiftl_mul_pow2, N.pow_add_r. ring. Qed.
Definition TSP_BITS : N := 512.
Definition tsp (x : N) : N * N * N :=
  let s := N.size x in
  if s <=? TSP_BITS then (x, x, 0)
  else let e := s - TSP_BITS in let q := N.shiftr x e in (q, q + 1, e).
Definition tlo (t : N * N * N) : N := fst (fst t).
Definition thi (t : N * N * N) : N := snd (fst t).
Definition tex (t : N * N * N) : N := snd t.
Lemma tsp_le (x : N) : N.shiftl (tlo (tsp x)) (tex (tsp x)) <= x.
Proof.
  unfold tsp, tlo, tex. destruct (N.size x <=? TSP_BITS); cbn [fst snd].
  - rewrite N.shiftl_0_r. reflexivity.
  - apply shiftr_shiftl_le.
Qed.
Lemma tsp_ge (x : N) : x <= N.shiftl (thi (tsp x)) (tex (tsp x)).
Proof.
  unfold tsp, thi, tex. destruct (N.size x <=? TSP_BITS); cbn [fst snd].
  - rewrite N.shiftl_0_r. reflexivity.
  - pose proof (shiftr_shiftl_lt x (N.size x - TSP_BITS)). lia.
Qed.
Definition smulbt (a : N) (tx ty : N * N * N) : cost :=
  let e := (tex tx + tex ty)%N in
  (N.shiftl (a * tlo tx * tlo ty) e,
   N.shiftl (a * thi tx * thi ty) e).
Definition smulb (a x y : N) : cost :=
  smulbt a (tsp x) (tsp y).
Lemma smulb_lo (a x y : N) : fst (smulb a x y) <= a * x * y.
Proof.
  unfold smulb, smulbt. cbn [fst].
  rewrite shiftl_mul_split3.
  pose proof (tsp_le x) as HX. pose proof (tsp_le y) as HY.
  apply N.mul_le_mono; [apply N.mul_le_mono; [reflexivity|exact HX]|exact HY].
Qed.
Lemma smulb_hi (a x y : N) : a * x * y <= snd (smulb a x y).
Proof.
  unfold smulb, smulbt. cbn [snd].
  rewrite shiftl_mul_split3.
  pose proof (tsp_ge x) as HX. pose proof (tsp_ge y) as HY.
  apply N.mul_le_mono; [apply N.mul_le_mono; [reflexivity|exact HX]|exact HY].
Qed.
Definition spredb (a : N) (tx : N * N * N) : cost :=
  let e := tex tx in
  (N.shiftl (a * tlo tx * (tlo tx - 1)) (e + e),
   N.shiftl (a * thi tx * thi tx) (e + e)).
Lemma shiftl_pred_le (q e x : N) :
  N.shiftl q e <= x -> N.shiftl (q - 1) e <= x - 1.
Proof.
  rewrite !N.shiftl_mul_pow2.
  pose proof (N.pow_nonzero 2 e ltac:(discriminate)) as HP.
  intros H.
  destruct q as [|p]; [cbn; lia|].
  rewrite !N.sub_1_r.
  apply N.lt_le_pred.
  eapply N.lt_le_trans; [|exact H].
  apply (N.mul_lt_mono_pos_r (2 ^ e)); lia.
Qed.
Lemma spredb_lo (a x : N) :
  fst (spredb a (tsp x)) <= a * x * (x - 1).
Proof.
  unfold spredb. cbn [fst].
  rewrite shiftl_mul_split3.
  pose proof (tsp_le x) as HX.
  pose proof (shiftl_pred_le (tlo (tsp x)) (tex (tsp x)) x HX) as HP.
  apply N.mul_le_mono; [apply N.mul_le_mono; [reflexivity|exact HX]|exact HP].
Qed.
Lemma spredb_hi (a x : N) :
  a * x * (x - 1) <= snd (spredb a (tsp x)).
Proof.
  unfold spredb. cbn [snd].
  rewrite shiftl_mul_split3.
  pose proof (tsp_ge x) as HX.
  apply N.mul_le_mono; [apply N.mul_le_mono; [reflexivity|exact HX]|].
  eapply N.le_trans; [apply N.le_sub_l|exact HX].
Qed.
Definition cyc_clean_i (K : N) : cost :=
  let r := K / 2 in
  let tr := tsp r in
  cadd (spredb 63 tr) (cx (243 * r)).
Definition cyc_four_i (c M : N) : cost :=
  let r := M / 2 in
  let tr := tsp r in
  let tc := tsp (40 * c + 184) in
  cadd (spredb 108 tr) (smulbt 1 tc tr).
Lemma cyc_clean_i_lo (K : N) : fst (cyc_clean_i K) <= cyc_clean K.
Proof.
  unfold cyc_clean_i, cyc_clean, cadd, cx. cbn [fst].
  pose proof (spredb_lo 63 (K/2)). lia.
Qed.
Lemma cyc_clean_i_hi (K : N) : cyc_clean K <= snd (cyc_clean_i K).
Proof.
  unfold cyc_clean_i, cyc_clean, cadd, cx. cbn [snd].
  pose proof (spredb_hi 63 (K/2)). lia.
Qed.
Lemma cyc_four_i_lo (c M : N) : fst (cyc_four_i c M) <= cyc_four c M.
Proof.
  unfold cyc_four_i, cyc_four, cadd. cbn [fst].
  pose proof (spredb_lo 108 (M/2)) as HS.
  pose proof (smulb_lo 1 (40 * c + 184) (M/2)) as HM.
  change (fst (smulbt 1 (tsp (40 * c + 184)) (tsp (M/2)))
          <= 1 * (40 * c + 184) * (M/2)) in HM.
  lia.
Qed.
Lemma cyc_four_i_hi (c M : N) : cyc_four c M <= snd (cyc_four_i c M).
Proof.
  unfold cyc_four_i, cyc_four, cadd. cbn [snd].
  pose proof (spredb_hi 108 (M/2)) as HS.
  pose proof (smulb_hi 1 (40 * c + 184) (M/2)) as HM.
  change (1 * (40 * c + 184) * (M/2)
          <= snd (smulbt 1 (tsp (40 * c + 184)) (tsp (M/2)))) in HM.
  lia.
Qed.
Close Scope N_scope.
Definition dfci (w : word) (_ : N) : cost :=
  match fcsplit w with
  | FCnone => cundef
  | FCclean ac K => cadd (cx ac) (cyc_clean_i K)
  | FCfour ac c M => cadd (cx ac) (cyc_four_i c M)
  end.
Lemma dfc_dfci (w : word) (f : N) :
  (fst (dfci w f) <= fst (dfc w f))%N /\ (snd (dfc w f) <= snd (dfci w f))%N.
Proof.
  unfold dfc, dfci.
  destruct (fcsplit w) as [|ac K|ac c M]; cbn [fst snd cadd cx cundef].
  - lia.
  - pose proof (cyc_clean_i_lo K); pose proof (cyc_clean_i_hi K). lia.
  - pose proof (cyc_four_i_lo c M); pose proof (cyc_four_i_hi c M). lia.
Qed.
Definition LATE_BITS : N := 10632.
Definition front_late (w : word) : bool :=
  match fcsplit w with
  | FCnone => false
  | FCclean _ K => (LATE_BITS <=? N.size K)%N
  | FCfour _ c M => (LATE_BITS <=? N.max (N.size c) (N.size M))%N
  end.
