Lemma cseg_ccolcost (cols : word) (pc gbc : N) :
  cseg cols = Some (pc, gbc) ->
  ccolcost cols = (pc + 14 * gbc + 22)%N.
Proof.
  unfold cseg.
  destruct (last2 cols) as [[[ini [[gao gaz] gac]] [[gbo gbz] gbc']]|]
    eqn:EL; [|discriminate].
  assert (Ecols := last2_split cols ini _ _ EL).
  destruct ((gao =? 8) && (gaz =? 2) && (gac =? 1)
            && (gbo =? 4) && (gbz =? 2) && (1 <=? gbc')
            && forallb is_col ini)%N eqn:EA.
  - intros H. injection H as <- <-.
    repeat (apply andb_prop in EA; destruct EA as [EA ?]).
    apply N.eqb_eq in EA.
    match goal with H : (gac =? 1)%N = true |- _ => apply N.eqb_eq in H end.
    match goal with H : (gbo =? 4)%N = true |- _ => apply N.eqb_eq in H end.
    subst gao gac gbo.
    rewrite Ecols, ccolcost_app.
    cbn [ccolcost gC gO]. lia.
  - destruct ((gbo =? 8) && (gbz =? 2) && (gbc' =? 1)
              && forallb is_col (ini ++ [(gao,gaz,gac)%N]))%N eqn:EB;
      [|discriminate].
    intros H. injection H as <- <-.
    repeat (apply andb_prop in EB; destruct EB as [EB ?]).
    apply N.eqb_eq in EB.
    match goal with H : (gbc' =? 1)%N = true |- _ => apply N.eqb_eq in H end.
    subst gbo gbc'.
    rewrite Ecols, !ccolcost_app.
    cbn [ccolcost gC gO]. lia.
Qed.
Lemma ccg_col_bpc (g : bg) : is_col g = true -> ccg g = bpc g.
Proof.
  destruct g as [[o z] c]. unfold is_col, ccg, bpc.
  cbn [gO gZ gC]. intros H.
  apply andb_prop in H. destruct H as [H _].
  apply N.eqb_eq in H. subst z. lia.
Qed.
Lemma ccolcost_col_bsum (w : word) :
  forallb is_col w = true -> ccolcost w = bsum w.
Proof.
  induction w as [|g t IH]; [reflexivity|].
  cbn [forallb]. intros H. apply andb_prop in H. destruct H as [H1 H2].
  rewrite ccolcost_cons. cbn [bsum].
  rewrite (ccg_col_bpc g H1), (IH H2). reflexivity.
Qed.
Lemma cw42g_le (g : bg) : 14 * cw42g g <= ccg g.
Proof.
  destruct g as [[o z] c]. unfold cw42g, w42, ccg.
  cbn [gO gZ gC].
  destruct ((o =? 4) && (z =? 2))%bool eqn:E.
  - apply andb_prop in E. destruct E as [E _]. apply N.eqb_eq in E. subst o.
    lia.
  - lia.
Qed.
Lemma cw42l_le (t : word) : 14 * cw42l t <= ccolcost t.
Proof.
  destruct t as [|g [|g2 t2]]; cbn [cw42l];
    [cbn; lia | rewrite ccolcost_cons; pose proof (cw42g_le g); lia
     | cbn; lia].
Qed.
Definition ubc (C f : N) : N := 2 * C + 2 * f + 64.
Lemma le_add_bound (a A B R : N) : A <= B -> a + B <= R -> a + A <= R.
Proof. lia. Qed.
Lemma optmap_pair_some {A B C : Type} (F : A -> B -> C)
      (o : option (A * B)) (r : C) :
  match o with Some (a, b) => Some (F a b) | None => None end = Some r ->
  exists a b, o = Some (a, b).
Proof. destruct o as [[a b]|]; [exists a, b; reflexivity|discriminate]. Qed.
Theorem cleaf_act_ub (s : word) (f : N) (s' : word) (f' : N) :
  fst (cleaf_act s f) = Some (s', f') ->
  chi (snd (cleaf_act s f)) <= ubc (ccolcost s) f.
Proof.
  unfold ubc. revert f s' f'.
  induction s as [|g s IH]; intros f s' f' HS; [cbn in HS; discriminate|].
  destruct g as [[X z] c].
  destruct z as [|zp].
  {   cbn in HS; discriminate. }
  destruct zp as [zp'|zp'|].
  -   cbn in HS; discriminate.
  - destruct zp' as [q|q|]; try (cbn in HS; discriminate).
    destruct c as [|cp]; [cbn in HS; discriminate|].
    destruct cp as [cp'|cp'|]; try (cbn in HS; discriminate).
    cbn [cleaf_act] in HS |- *.
    rewrite ccolcost_cons. rewrite ccg_unfold.
    destruct ((5 <=? X) && negb (X =? 8) && negb (X =? 12))%bool eqn:EG;
      [|cbn in HS; discriminate].
    destruct s as [|[[on zn] cn] t2].
    {
      cbn [snd]. unfold d_cma_far.
      destruct (f =? 3); [cbn [chi cx snd]; cbn [ccolcost]; lia|].
      destruct (f =? 2); [cbn [chi cx snd]; cbn [ccolcost]; lia|].
      destruct (f =? 4); [cbn [chi cx snd]; cbn [ccolcost]; lia|].
      cbn [chi cundef snd]; lia. }
    rewrite ccolcost_cons, ccg_unfold.
    destruct (on =? 1);
      [cbn [snd]; unfold d_cma_halt, cundef; cbn [chi snd]; lia|].
    destruct ((on =? 3) && (zn =? 2) && (cn =? 1) && (f =? 4))%bool eqn:EM.
    {
      apply andb_prop in EM; destruct EM as [EM Ef4].
      apply andb_prop in EM; destruct EM as [EM Ecn].
      apply andb_prop in EM; destruct EM as [Eon Ezn].
      apply N.eqb_eq in Eon. apply N.eqb_eq in Ezn. apply N.eqb_eq in Ecn.
      subst on zn cn.
      pose proof (cw42l_le t2).
      cbn [snd]. unfold d_cma_marker. cbn [chi cx snd]. lia. }
    destruct ((on =? 4) && (zn =? 2))%bool eqn:ER.
    {
      apply andb_prop in ER. destruct ER as [ER1 ER2].
      apply N.eqb_eq in ER1. apply N.eqb_eq in ER2. subst on zn.
      cbn [snd]. unfold d_cma_respawn_at.
      destruct t2 as [|g2 [|g3 [|g4 t4]]].
      - unfold d_cma_respawn_final. cbn [chi cx snd].
        cbn [ccolcost]. lia.
      - cbn [chi cundef snd]. lia.
      - unfold d_cma_respawn_orphan. cbn [chi cx snd].
        pose proof (cw42g_le g3).
        rewrite ccolcost_cons, ccolcost_cons. cbn [ccolcost].
        lia.
      - cbn [chi cundef snd]. lia. }
    destruct ((X =? 6) && (on =? 2) && (zn =? 2) && (cn =? 1) && (f =? 4)
              && match t2 with
                 | [(o2,z2,_)] => (o2 =? 4) && (z2 =? 2)
                 | _ => false
                 end)%bool eqn:E6.
    {
      apply andb_prop in E6; destruct E6 as [E6 Et2].
      apply andb_prop in E6; destruct E6 as [E6 Ef4].
      apply andb_prop in E6; destruct E6 as [E6 Ecn].
      apply andb_prop in E6; destruct E6 as [E6 Ezn].
      apply andb_prop in E6; destruct E6 as [EX Eon].
      apply N.eqb_eq in EX. apply N.eqb_eq in Eon.
      apply N.eqb_eq in Ezn. apply N.eqb_eq in Ecn.
      subst X on zn cn.
      pose proof (cw42l_le t2).
      cbn [snd]. unfold d_cma_622. cbn [chi cx snd]. lia. }
    destruct ((zn =? 1)
              || ((zn =? 2) && (cn =? 1) && (5 <=? on)
                  && negb (on =? 8) && negb (on =? 12)))%bool eqn:EP.
    {
      rewrite cmap_fst in HS. cbv beta in HS.
      apply optmap_pair_some in HS. destruct HS as (s2 & f2 & EI).
      specialize (IH f s2 f2 EI).
      rewrite ccolcost_cons, ccg_unfold in IH.
      unfold cmap. cbn [snd].
      unfold d_thru, cadd, chi, cx. cbn [fst snd].
      unfold chi in IH. apply (le_add_bound _ _ _ _ IH). lia. }
    cbn [snd]. unfold cundef; cbn [chi snd]. lia.
  -
    cbn [cleaf_act] in HS |- *.
    rewrite ccolcost_cons, ccg_unfold.
    cbn [snd]. unfold d_tick. cbn [chi cx snd].
    assert (Hc : 1 <= c).
    { destruct (2 <=? c) eqn:E2; [apply N.leb_le in E2; lia|].
      cbn [fst] in HS.
      destruct (negb (c =? 1) || negb (2 <=? X))%bool eqn:E1;
        [cbn in HS; discriminate|].
      apply orb_false_iff in E1. destruct E1 as [E1 _].
      apply negb_false_iff, N.eqb_eq in E1. lia. }
    nia.
Qed.
Lemma chi_cx (k : N) : chi (cx k) = k.
Proof. reflexivity. Qed.
Lemma chi_cundef : chi cundef = 0.
Proof. reflexivity. Qed.
Lemma chi_czero : chi czero = 0.
Proof. reflexivity. Qed.
Lemma chi_cadd (a b : cost) : chi (cadd a b) = chi a + chi b.
Proof. reflexivity. Qed.
Lemma tick8_ub_arith (X P S f : N) :
  2 * X + P + 30 + (2 * S + 2 * f + 64) <=
  2 * ((2 * X + 6) + (22 + (P + S))) + 2 * f + 64.
Proof. nia. Qed.
Lemma dseg_ub (cols : word) (L : N -> N) (K : N) :
  (forall gbc, L gbc <= 14 * gbc + K) ->
  chi (dseg cols L) <= ccolcost cols + K.
Proof.
  intros HL. unfold dseg.
  destruct (cseg cols) as [[pc gbc]|] eqn:EC; [|cbn; lia].
  rewrite (cseg_ccolcost cols pc gbc EC).
  rewrite chi_cx. specialize (HL gbc). lia.
Qed.
Lemma w42sum_ccolcost (t : word) :
  forallb w42 t = true -> 14 * w42sum t = ccolcost t.
Proof.
  induction t as [|[[o z] c] r IH]; [reflexivity|].
  cbn [forallb]. intros H. apply andb_prop in H. destruct H as [H1 H2].
  unfold w42 in H1. cbn [gO gZ] in H1.
  apply andb_prop in H1. destruct H1 as [H1 _]. apply N.eqb_eq in H1. subst o.
  cbn [w42sum gC].
  rewrite ccolcost_cons, ccg_unfold.
  rewrite <- (IH H2). lia.
Qed.
Local Opaque ccolcost.
Lemma dtb4_convc_ub (body : word) (b : word) (k : N) :
  dtb4_convc body = Some (b, k) -> k <= ccolcost body + 21.
Proof.
  revert b k. induction body as [|g t IH]; intros b k; [discriminate|].
  cbn [dtb4_convc].
  destruct (dtb4_convc t) as [[t' k']|] eqn:ET.
  { intros HH. injection HH as <- <-.
    specialize (IH t' k' eq_refl).
    rewrite (ccolcost_cons g t), ccolcost_1. lia. }
  destruct ((gO g =? 8) && (gZ g =? 2) && (gC g =? 1))%bool
    eqn:EG; [|discriminate].
  repeat (apply andb_prop in EG; destruct EG as [EG ?]).
  apply N.eqb_eq in EG.
  destruct g as [[go gz] gc]. cbn [gO gZ gC] in *. subst go.
  match goal with H : (gz =? 2) = true |- _ => apply N.eqb_eq in H; subst gz end.
  match goal with H : (gc =? 1) = true |- _ => apply N.eqb_eq in H; subst gc end.
  rewrite ccolcost_cons, ccg_unfold.
  destruct (forallb w42 t) eqn:EW.
  { intros HH. injection HH as <- <-.
    unfold kdtb_plain. rewrite <- (w42sum_ccolcost t EW). lia. }
  destruct t as [|[[o1 z1] c1] [|[[o2 z2] c2] t2]]; try discriminate.
  destruct ((o1 =? 4) && (z1 =? 2) && (1 <=? c1)
            && (o2 =? 3) && (z2 =? 2) && (c2 =? 1))%bool eqn:EA;
    [|discriminate].
  apply andb_prop in EA; destruct EA as [EA Ec2].
  apply andb_prop in EA; destruct EA as [EA Ez2].
  apply andb_prop in EA; destruct EA as [EA Eo2].
  apply andb_prop in EA; destruct EA as [EA Ec1].
  apply andb_prop in EA; destruct EA as [Eo1 Ez1].
  apply N.eqb_eq in Eo1. apply N.eqb_eq in Eo2. apply N.eqb_eq in Ec2.
  subst o1 o2 c2.
  destruct t2 as [|[[o3 z3] c3] [|g4 t4]].
  - intros HH. injection HH as <- <-. unfold kdtb_orphan.
    rewrite !ccolcost_cons, !ccg_unfold, ccolcost_nil.
    lia.
  - destruct ((o3 =? 4) && (z3 =? 2))%bool eqn:E3; [|discriminate].
    apply andb_prop in E3. destruct E3 as [E3 _]. apply N.eqb_eq in E3. subst o3.
    intros HH. injection HH as <- <-. unfold kdtb_orphan.
    rewrite !ccolcost_cons, !ccg_unfold, ccolcost_nil.
    lia.
  - discriminate.
Qed.
Lemma dtb3_convc_ub (body : word) (b : word) (k : N) :
  dtb3_convc body = Some (b, k) -> k <= ccolcost body + 21.
Proof.
  revert b k. induction body as [|g t IH]; intros b k; [discriminate|].
  cbn [dtb3_convc].
  destruct (dtb3_convc t) as [[t' k']|] eqn:ET.
  { intros HH. injection HH as <- <-.
    specialize (IH t' k' eq_refl).
    rewrite (ccolcost_cons g t), ccolcost_1. lia. }
  destruct ((gO g =? 8) && (gZ g =? 2) && (gC g =? 1))%bool
    eqn:EG; [|discriminate].
  apply andb_prop in EG; destruct EG as [EG Egc].
  apply andb_prop in EG; destruct EG as [Ego Egz].
  destruct g as [[go gz] gc]. cbn [gO gZ gC] in *.
  apply N.eqb_eq in Ego. apply N.eqb_eq in Egz. apply N.eqb_eq in Egc.
  subst go gz gc.
  rewrite ccolcost_cons, ccg_unfold.
  destruct t as [|[[o1 z1] c1] t1]; [discriminate|].
  destruct ((o1 =? 4) && (z1 =? 2) && (1 <? c1) && forallb w42 t1)%bool
    eqn:EA; [|discriminate].
  apply andb_prop in EA; destruct EA as [EA EW1].
  apply andb_prop in EA; destruct EA as [EA Ec1].
  apply andb_prop in EA; destruct EA as [Eo1 Ez1].
  apply N.eqb_eq in Eo1. subst o1.
  pose proof (w42sum_ccolcost t1 EW1) as HW.
  intros HH. injection HH as <- <-. unfold kdtb_f3.
  rewrite ccolcost_cons, ccg_unfold. lia.
Qed.
Lemma d_rseg_tail_ub (cols : word) (Bq : N)
      (cols2 : word) (f : N) :
  chi (d_rseg_tail cols Bq cols2 f) <=
  ccolcost cols + 14 * Bq + ccolcost cols2 + 2 * f + 43.
Proof.
  unfold d_rseg_tail.
  destruct (5 <=? f)%N eqn:EF5; [rewrite chi_cx; lia|].
  destruct (f =? 4)%N eqn:EF4; [|rewrite chi_cundef; lia].
  destruct (dtb4_convc cols2) as [[cols2' Kd]|] eqn:ED4.
  { rewrite chi_cx.
    pose proof (dtb4_convc_ub cols2 cols2' Kd ED4). lia. }
  destruct (forallb w42 cols2); [rewrite chi_cx|rewrite chi_cundef]; lia.
Qed.
Ltac ubfin :=
  cbn [fst snd];
  try (unfold word in *);
  rewrite ?chi_cadd, ?chi_cx, ?chi_cundef, ?chi_czero;
  rewrite ?ccolcost_cons, ?ccolcost_consn,
          ?ccolcost_nil, ?ccolcost_niln,
          ?ccg_unfold in *;
  (lia || nia).
Ltac ubun := intros ? ? _; ubfin.
Theorem cascade_ub (n : nat) :
  (forall s f s2 f2, fst (cfire_comp n s f) = Some (s2, f2) ->
     chi (snd (cfire_comp n s f)) <= ubc (ccolcost s) f)
  /\ (forall cols s f body f2,
        fst (crenew_seg n cols s f) = Some (body, f2) ->
        chi (snd (crenew_seg n cols s f))
          <= ubc (ccolcost cols + ccolcost s) f).
Proof.
  unfold ubc.
  induction n as [|n IH]; [split; intros; discriminate|].
  destruct IH as [IHfc IHrs].
  split.
  -
    intros s f.
    destruct s as [|[[X z] c] rest0]; [discriminate|].
    destruct z as [|zp]; [discriminate|].
    destruct zp as [zp'|zp'|]; try discriminate.
    destruct zp' as [q|q|]; try discriminate.
    destruct c as [|cp]; [discriminate|].
    destruct cp as [cp'|cp'|]; try discriminate.
    cbn [cfire_comp].
    destruct (negb (5 <=? X)) eqn:EX; [discriminate|].
    apply negb_false_iff, N.leb_le in EX.
    destruct rest0 as [|[[Y zY] cY] rest].
    {   unfold d_casc_far.
      destruct (2 <=? f) eqn:E2; [|ubun].
      apply N.leb_le in E2. intros ? ? _. ubfin. }
    destruct ((Y =? 4) && (zY =? 2))%bool eqn:EY4.
    { apply andb_prop in EY4. destruct EY4 as [EY4 EZ4].
      apply N.eqb_eq in EY4. apply N.eqb_eq in EZ4. subst Y zY.
      destruct (negb (1 <=? cY)) eqn:ENL; [discriminate|].
      apply negb_false_iff, N.leb_le in ENL.
      destruct rest as [|gr rest'].
      {   unfold d_casc_lvl_end.
        destruct (f =? 4) eqn:EF4; [intros ? ? _; ubfin|].
        destruct (5 <=? f) eqn:EF5; [|ubun].
        apply N.leb_le in EF5. intros ? ? _. ubfin. }
      destruct (seek (gr :: rest')) as [cols s2] eqn:Eseek.
      pose proof (ccolcost_seek_eq _ _ _ Eseek) as HSK.
      destruct s2 as [|[[o4 z4] c4] s2t].
      {   unfold d_casc_dtb.
        destruct (5 <=? f) eqn:EF5.
        { apply N.leb_le in EF5. intros ? ? _. ubfin. }
        destruct (f =? 3) eqn:EF3.
        { match goal with
          | |- context [ dtb3_convc ?a ] =>
              destruct (dtb3_convc a) as [[bd Kd]|] eqn:ED
          end; [|ubun].
          pose proof (dtb3_convc_ub _ _ _ ED) as HD.
          apply N.eqb_eq in EF3. intros ? ? _. ubfin. }
        destruct (f =? 4) eqn:EF4; [|ubun].
        match goal with
        | |- context [ dtb4_convc ?a ] =>
            destruct (dtb4_convc a) as [[bd Kd]|] eqn:ED
        end; [|ubun].
        pose proof (dtb4_convc_ub _ _ _ ED) as HD.
        apply N.eqb_eq in EF4. intros ? ? _. ubfin. }
      destruct ((o4 =? 4) && (z4 =? 3) && (c4 =? 1))%bool eqn:E43.
      { apply andb_prop in E43; destruct E43 as [E43 Ec4].
        apply andb_prop in E43; destruct E43 as [Eo4 Ez4].
        apply N.eqb_eq in Eo4. apply N.eqb_eq in Ez4. apply N.eqb_eq in Ec4.
        subst o4 z4 c4.
        destruct s2t as [|[[o5 z5] Bq] rest2].
        {
          unfold d_casc_endR, d_casc_stage.
          pose proof (dseg_ub cols (fun gbc => 14 * gbc + 2 * f + 57)
                        (2 * f + 57) ltac:(intros; lia)) as HR.
          unfold dseg_endR.
          destruct (2 <=? f) eqn:E2; [|ubun].
          intros ? ? _. ubfin. }
        destruct ((o5 =? 4) && (z5 =? 2))%bool eqn:E52.
        { apply andb_prop in E52. destruct E52 as [Eo5 Ez5].
          apply N.eqb_eq in Eo5. apply N.eqb_eq in Ez5. subst o5 z5.
          destruct (1 <=? Bq) eqn:EB; [|discriminate].
          apply N.leb_le in EB.
          destruct rest2 as [|gr2 rest2'].
          {
            unfold d_casc_lawR, d_casc_stage, dseg_lawR.
            destruct (f =? 4) eqn:EF4.
            { pose proof (dseg_ub cols (fun gbc => 14 * gbc + 14 * Bq + 65)
                            (14 * Bq + 65) ltac:(intros; lia)) as HR.
              intros ? ? _. ubfin. }
            destruct (5 <=? f) eqn:EF5; [|ubun].
            apply N.leb_le in EF5.
            pose proof (dseg_ub cols
                          (fun gbc => 14 * gbc + 14 * Bq + 2 * f + 57)
                          (14 * Bq + 2 * f + 57) ltac:(intros; lia)) as HR.
            intros ? ? _. ubfin. }
          destruct (jump_seg cols Bq) as [seg|] eqn:EJ; [|discriminate].
          destruct (seek (gr2 :: rest2')) as [cols2 s3] eqn:Eseek2.
          pose proof (ccolcost_seek_eq _ _ _ Eseek2) as HSK2.
          match goal with
          | |- context [ crenew_seg ?a ?b ?cc ?d ] =>
              destruct (fst (crenew_seg a b cc d)) as [[bd fd]|] eqn:ER
          end.
          { pose proof (IHrs cols2 s3 f bd fd ER) as IHq.
            unfold d_casc_stage, d_jsplice.
            intros ? ? _. ubfin. }
          match goal with
          | |- context [ cfire_comp ?a ?b ?cc ] =>
              destruct (fst (cfire_comp a b cc)) as [[sd fd]|] eqn:EFq
          end.
          { pose proof (IHfc s3 f sd fd EFq) as IHq.
            unfold d_casc_stage, d_jsplice, d_cols.
            intros ? ? _. ubfin. }
          destruct (sand_leaf s3
                    && forallb (fun g => (gC g =? 0)%N) cols2)%bool;
            [discriminate|].
          match goal with
          | |- context [ cleaf_act ?b ?cc ] =>
              destruct (fst (cleaf_act b cc)) as [[sd fd]|] eqn:EL
          end.
          { pose proof (cleaf_act_ub s3 f sd fd EL) as IHq. unfold ubc in IHq.
            unfold d_casc_leafj. intros ? ? _. ubfin. }
          unfold d_casc_tail.
          destruct (5 <=? f) eqn:EF5.
          { apply N.leb_le in EF5. intros ? ? _. ubfin. }
          destruct (f =? 4) eqn:EF4; [|ubun].
          match goal with
          | |- context [ dtb4_convc ?a ] =>
              destruct (dtb4_convc a) as [[bd2 Kd]|] eqn:ED
          end.
          { pose proof (dtb4_convc_ub _ _ _ ED) as HD.
            apply N.eqb_eq in EF4. intros ? ? _. ubfin. }
          destruct (forallb w42 cols2) eqn:EW42; [|ubun].
          destruct (lawR_seg cols Bq) as [seg2|] eqn:ELR; [|ubun].
          apply N.eqb_eq in EF4. intros ? ? _. ubfin. }
        destruct ((z5 =? 3) && (Bq =? 1)
                  && match rest2 with [] => true | _ => false end
                  && (f =? 4) && (1 <=? o5))%bool eqn:EYY.
        {
          destruct rest2 as [|? ?];
            [|repeat rewrite ?Bool.andb_false_r, ?Bool.andb_false_l in EYY;
              discriminate].
          apply andb_prop in EYY; destruct EYY as [EYY Eo5].
          apply andb_prop in EYY; destruct EYY as [EYY Ef4].
          apply andb_prop in EYY; destruct EYY as [EYY _].
          apply andb_prop in EYY; destruct EYY as [Ez5 EBq].
          apply N.eqb_eq in Ez5. apply N.eqb_eq in EBq. subst z5 Bq.
          unfold d_casc_endY, d_casc_stage, dseg_endY.
          pose proof (dseg_ub cols (fun gbc => 14 * gbc + 2 * o5 + 79)
                        (2 * o5 + 79) ltac:(intros; lia)) as HR.
          intros ? ? _. ubfin. }
        rewrite cmap_fst. cbv beta.
        intros s2' f2' HS. apply optmap_pair_some in HS.
        destruct HS as (sd & fd & EL).
        pose proof (cleaf_act_ub _ f sd fd EL) as IHq. unfold ubc in IHq.
        unfold cmap, d_casc_leaf. cbn [snd]. ubfin. }
      destruct ((o4 =? 4) && (z4 =? 4) && (c4 =? 1))%bool eqn:E44.
      {
        apply andb_prop in E44; destruct E44 as [E44 Ec4].
        apply andb_prop in E44; destruct E44 as [Eo4 Ez4].
        apply N.eqb_eq in Eo4. apply N.eqb_eq in Ez4. apply N.eqb_eq in Ec4.
        subst o4 z4 c4.
        unfold d_casc_z4, d_casc_stage.
        pose proof (dseg_ub cols (fun gbc => 14 * gbc + 43) 43
                      ltac:(intros; lia)) as HR.
        intros ? ? _. ubfin. }
      match goal with
      | |- context [ cfire_comp ?a ?b ?cc ] =>
          destruct (fst (cfire_comp a b cc)) as [[sd fd]|] eqn:EFq
      end.
      { match goal with
        | EFq : fst (cfire_comp ?a ?b ?cc) = _ |- _ =>
            pose proof (IHfc b cc sd fd EFq) as IHq
        end.
        unfold d_casc_stage, d_cols. intros ? ? _. ubfin. }
      rewrite cmap_fst. cbv beta.
      intros s2' f2' HS. apply optmap_pair_some in HS.
      destruct HS as (sd2 & fd2 & EL).
      pose proof (cleaf_act_ub _ f sd2 fd2 EL) as IHq. unfold ubc in IHq.
      unfold cmap, d_casc_leaf. cbn [snd]. ubfin. }
    destruct ((Y =? 8) && (zY =? 2) && (cY =? 1))%bool eqn:EY8.
    {
      apply andb_prop in EY8; destruct EY8 as [EY8 EcY].
      apply andb_prop in EY8; destruct EY8 as [EY EzY].
      apply N.eqb_eq in EY. apply N.eqb_eq in EzY. apply N.eqb_eq in EcY.
      subst Y zY cY.
      match goal with
      | |- context [ tick_target ?a ?b ] =>
          destruct (tick_target a b) as [j|] eqn:Etg
      end; [|discriminate].
      pose proof (proj1 (tick_target_inv
                           ((X-1,1,1) :: (11,2,1) :: rest) 2 j Etg)) as HJ.
      destruct j as [|[|jj]]; [lia|lia|].
      match goal with
      | |- context [ match wat ?a (S (S jj)) with _ => _ end ] =>
          destruct (wat a (S (S jj))) as [[[oq zq] cq]|] eqn:Ewat
      end; [|discriminate].
      destruct (zq =? 1) eqn:EZQ; [|discriminate].
      match goal with
      | |- context [tickcols ?ss ?site] =>
          pose proof (ccolcost_split ss site) as HT1;
          pose proof (ccolcost_split (firstn site ss) 2) as HT2
      end.
      destruct n as [|fuel]; [cbn [cdeliver_tick cmap]; discriminate|].
      intros s3 f3 Hout.
      destruct (cdeliver_tick (S fuel)
                  ((X-1,1,1) :: (11,2,1) :: rest) f (S (S jj)) true)
        as [[w3 f3'| |] d] eqn:EDT;
        cbn [cmap] in Hout |- *; try discriminate Hout.
      injection Hout as <- <-.
      assert (HZ :
        (match wat ((X-1,1,1) :: (11,2,1) :: rest) (S (S jj)) with
         | Some (_,z,_) => (z =? 1)%N | None => false end) = true)
        by (rewrite Ewat; exact EZQ).
      destruct (cdt_leaf_convc fuel
                  ((X-1,1,1) :: (11,2,1) :: rest) f (S (S jj)) true
                  w3 f3' d HZ EDT) as (s' & ELeaf & _).
      pose proof (f_equal fst ELeaf) as ELeafF; cbn [fst] in ELeafF.
      pose proof (f_equal snd ELeaf) as ELeafD; cbn [snd] in ELeafD.
      pose proof (cleaf_act_ub
                    (skipn (S (S jj))
                       ((X-1,1,1) :: (11,2,1) :: rest))
                    f s' f3' ELeafF) as HD.
      unfold ubc in HD.
      cbn [firstn] in HT2.
      unfold d_casc_tick8, tickcols.
      cbn [cmap]. rewrite <- ELeafD.
      unfold cmap.
      cbn [fst snd firstn skipn] in HT1, HT2, HD |- *.
      pose proof (ccolcost_split rest jj) as HRest.
      rewrite chi_cadd, chi_cx.
      eapply N.le_trans.
      { apply N.add_le_mono_l. exact HD. }
      rewrite !ccolcost_cons, ?ccolcost_nil,
              !ccg_unfold, HRest.
      rewrite !N.mul_1_l.
      change (2 * X + ccolcost (firstn jj rest) + 30 +
                (2 * ccolcost (skipn jj rest) + 2 * f + 64) <=
              2 * ((2 * X + 6) +
                     (22 + (ccolcost (firstn jj rest) +
                              ccolcost (skipn jj rest)))) +
                2 * f + 64).
      apply tick8_ub_arith. }
    destruct ((zY =? 1) && (cY =? 1) && (1 <=? Y)
              && match rest with [] => true | _ => false end)%bool eqn:EZ1.
    { destruct rest as [|? ?];
        [|repeat rewrite ?Bool.andb_false_r, ?Bool.andb_false_l in EZ1;
          discriminate].
      apply andb_prop in EZ1; destruct EZ1 as [EZ1 _].
      apply andb_prop in EZ1; destruct EZ1 as [EZ1 EY1].
      apply andb_prop in EZ1; destruct EZ1 as [Ez1 Ec1].
      apply N.eqb_eq in Ez1. apply N.eqb_eq in Ec1. subst zY cY.
      unfold d_casc_z1end, d_casc_z1law.
      destruct (2 <=? f) eqn:E2; [|ubun].
      intros ? ? _. ubfin. }
    destruct ((zY =? 3) && (cY =? 1) && (1 <=? Y) && (f =? 4))%bool eqn:EZ3.
    { apply andb_prop in EZ3; destruct EZ3 as [EZ3 _].
      apply andb_prop in EZ3; destruct EZ3 as [EZ3 _].
      apply andb_prop in EZ3; destruct EZ3 as [Ez3 Ec1].
      apply N.eqb_eq in Ez3. apply N.eqb_eq in Ec1. subst zY cY.
      destruct rest as [|[[o2 z2] c2] r2]; [discriminate|].
      destruct r2 as [|? ?]; [|discriminate].
      destruct ((o2 =? 4) && (z2 =? 2) && (1 <=? c2))%bool eqn:E42;
        [|discriminate].
      apply andb_prop in E42; destruct E42 as [E42 Ecc2].
      apply andb_prop in E42; destruct E42 as [Eo2 Ez2].
      apply N.eqb_eq in Eo2. apply N.eqb_eq in Ez2. subst o2 z2.
      unfold d_casc_z3, lvlc.
      cbn [gC]. intros ? ? _. ubfin. }
    destruct ((zY =? 1) && (cY =? 1) && (1 <=? Y)
              && match rest with
                 | (o2,z2,c2) :: _ => (o2 =? 4) && (z2 =? 2) && (1 <=? c2)
                 | [] => false
                 end)%bool eqn:EZL.
    { destruct rest as [|[[o2 z2] c2] r2]; [discriminate|].
      apply andb_prop in EZL; destruct EZL as [EZL _].
      apply andb_prop in EZL; destruct EZL as [EZL EY1].
      apply andb_prop in EZL; destruct EZL as [Ez1 Ec1].
      apply N.eqb_eq in Ez1. apply N.eqb_eq in Ec1. subst zY cY.
      apply N.leb_le in EY1.
      unfold d_casc_z1lvl, d_casc_z1law. intros ? ? _. ubfin. }
    destruct ((zY =? 1) && (2 <=? cY) && (2 <=? Y))%bool eqn:EZS.
    { apply andb_prop in EZS; destruct EZS as [EZS EY2].
      apply andb_prop in EZS; destruct EZS as [Ez1 Ec2].
      apply N.eqb_eq in Ez1. subst zY.
      apply N.leb_le in Ec2. apply N.leb_le in EY2.
      unfold d_casc_z1split, d_casc_z1law. intros ? ? _. ubfin. }
    destruct ((zY =? 1) && (cY =? 1) && (1 <=? Y)
              && match rest with
                 | (o2,z2,c2) :: _ => (z2 =? 1) && (c2 =? 1) && (1 <=? o2)
                 | [] => false
                 end)%bool eqn:EZZ.
    { destruct rest as [|[[k kz] kc] r2]; [discriminate|].
      apply andb_prop in EZZ; destruct EZZ as [EZZ _].
      apply andb_prop in EZZ; destruct EZZ as [EZZ EY1].
      apply andb_prop in EZZ; destruct EZZ as [Ez1 Ec1].
      apply N.eqb_eq in Ez1. apply N.eqb_eq in Ec1. subst zY cY.
      apply N.leb_le in EY1.
      unfold d_casc_z1z1, d_casc_z1law.
      destruct (k =? 1); intros ? ? _; ubfin. }
    destruct ((zY =? 1) && (cY =? 1) && (1 <=? Y)
              && match rest with
                 | (o2,z2,c2) :: _ =>
                     (z2 =? 2) && (1 <=? o2) && (o2 <=? 3) && (c2 =? 1)
                 | [] => false
                 end)%bool eqn:EZ2; [|discriminate].
    destruct rest as [|[[b bz] bc] r2]; [discriminate|].
    apply andb_prop in EZ2; destruct EZ2 as [EZ2 _].
    apply andb_prop in EZ2; destruct EZ2 as [EZ2 EY1].
    apply andb_prop in EZ2; destruct EZ2 as [Ez1 Ec1].
    apply N.eqb_eq in Ez1. apply N.eqb_eq in Ec1. subst zY cY.
    apply N.leb_le in EY1.
    unfold d_casc_z1z2, d_casc_z1law.
    destruct (b =? 1); intros ? ? _; ubfin.
  -
    intros cols s f.
    destruct s as [|[[o z] c] rest]; [discriminate|].
    destruct o as [|op]; [discriminate|].
    destruct op as [op'|op'|]; try discriminate.
    destruct op' as [q|q|]; try discriminate.
    destruct q as [r|r|]; try discriminate.
    destruct z as [|zp]; [discriminate|].
    destruct zp as [zp'|zp'|]; try discriminate.
    destruct zp' as [q|q|]; try discriminate.
    destruct c as [|cp]; [discriminate|].
    destruct cp as [cp'|cp'|]; try discriminate.
    cbn [crenew_seg].
    destruct rest as [|[[o5 z5] Bq] rest2].
    { unfold d_rseg_endR, dseg_endR.
      destruct (2 <=? f) eqn:E2; [|ubun].
      pose proof (dseg_ub cols (fun gbc => 14 * gbc + 2 * f + 57)
                    (2 * f + 57) ltac:(intros; lia)) as HR.
      intros ? ? _. ubfin. }
    destruct ((o5 =? 4) && (z5 =? 2) && (1 <=? Bq))%bool eqn:E52.
    { apply andb_prop in E52; destruct E52 as [E52 EB].
      apply andb_prop in E52; destruct E52 as [Eo5 Ez5].
      apply N.eqb_eq in Eo5. apply N.eqb_eq in Ez5. subst o5 z5.
      apply N.leb_le in EB.
      destruct rest2 as [|gr2 rest2'].
      { unfold d_rseg_lawR, dseg_lawR.
        destruct (f =? 4) eqn:EF4.
        { pose proof (dseg_ub cols (fun gbc => 14 * gbc + 14 * Bq + 65)
                        (14 * Bq + 65) ltac:(intros; lia)) as HR.
          intros ? ? _. ubfin. }
        destruct (5 <=? f) eqn:EF5; [|ubun].
        apply N.leb_le in EF5.
        pose proof (dseg_ub cols (fun gbc => 14 * gbc + 14 * Bq + 2 * f + 57)
                      (14 * Bq + 2 * f + 57) ltac:(intros; lia)) as HR.
        intros ? ? _. ubfin. }
      destruct (jump_seg cols Bq) as [seg|] eqn:EJ; [|discriminate].
      destruct (seek (gr2 :: rest2')) as [cols2 s3] eqn:Eseek2.
      pose proof (ccolcost_seek_eq _ _ _ Eseek2) as HSK2.
      match goal with
      | |- context [ crenew_seg ?a ?b ?cc ?d ] =>
          destruct (fst (crenew_seg a b cc d)) as [[bd fd]|] eqn:ER
      end.
      { pose proof (IHrs cols2 s3 f bd fd ER) as IHq.
        unfold d_jsplice. intros ? ? _. ubfin. }
      destruct s3 as [|[[o7 z7] c7] s3t].
      {
        unfold cdrop. cbn [fst].
        match goal with
        | |- context [ cleaf_act ?b ?cc ] =>
            destruct (fst (cleaf_act b cc)) as [[sd fd]|] eqn:EL0
        end.
        { cbn [cleaf_act] in EL0. discriminate. }
        intros ? ? _.
        eapply N.le_trans; [apply d_rseg_tail_ub|].
        ubfin. }
      destruct ((z7 =? 3) && (c7 =? 1))%bool eqn:E73.
      { rewrite cmap_fst. cbv beta.
        match goal with
        | |- context [ cfire_comp ?a ?b ?cc ] =>
            destruct (fst (cfire_comp a b cc)) as [[sd fd]|] eqn:EFq
        end.
        { match goal with
          | EFq : fst (cfire_comp ?a ?b ?cc) = _ |- _ =>
              pose proof (IHfc b cc sd fd EFq) as IHq
          end.
          unfold cmap, d_jsplice, d_cols. cbn [snd].
          intros ? ? _. ubfin. }
        intros ? ? HSome. discriminate HSome. }
      match goal with
      | |- context [ sand_leaf ?a ] => destruct (sand_leaf a) eqn:ESL
      end.
      { cbn [fst]. intros ? ? HSome. discriminate HSome. }
      rewrite cmap_fst. cbv beta.
      match goal with
      | |- context [ cleaf_act ?b ?cc ] =>
          destruct (fst (cleaf_act b cc)) as [[sd fd]|] eqn:EL
      end.
      { match goal with
        | EL : fst (cleaf_act ?b ?cc) = _ |- _ =>
            pose proof (cleaf_act_ub b cc sd fd EL) as IHq
        end.
        unfold ubc in IHq.
        unfold cmap, d_rseg_inner. cbn [snd]. intros ? ? _. ubfin. }
      intros ? ? HSome. discriminate HSome. }
    destruct ((z5 =? 3) && (Bq =? 1)
              && match rest2 with [] => true | _ => false end
              && (f =? 4) && (1 <=? o5))%bool eqn:EYY; [|discriminate].
    destruct rest2 as [|? ?];
      [|repeat rewrite ?Bool.andb_false_r, ?Bool.andb_false_l in EYY;
        discriminate].
    apply andb_prop in EYY; destruct EYY as [EYY Eo5].
    apply andb_prop in EYY; destruct EYY as [EYY Ef4].
    apply andb_prop in EYY; destruct EYY as [EYY _].
    apply andb_prop in EYY; destruct EYY as [Ez5 EBq].
    apply N.eqb_eq in Ez5. apply N.eqb_eq in EBq. subst z5 Bq.
    unfold d_rseg_endY, dseg_endY.
    pose proof (dseg_ub cols (fun gbc => 14 * gbc + 2 * o5 + 79)
                  (2 * o5 + 79) ltac:(intros; lia)) as HR.
    intros ? ? _. ubfin.
Qed.
Lemma mul_sub1 (c A : N) : 1 <= c -> c * A = A + (c - 1) * A.
Proof.
  intros H. replace c with (1 + (c - 1)) at 1 by lia.
  rewrite N.mul_add_distr_r. lia.
Qed.
Lemma mul_sub2 (c A : N) : 2 <= c -> c * A = 2 * A + (c - 2) * A.
Proof.
  intros H. replace c with (2 + (c - 2)) at 1 by lia.
  rewrite N.mul_add_distr_r. lia.
Qed.
Ltac gbools :=
  repeat match goal with
  | H : (?a <? ?b)%N = false |- _ => apply N.ltb_ge in H
  | H : (?a <=? ?b)%N = false |- _ => apply N.leb_gt in H
  | H : (?a =? ?b)%N = false |- _ => apply N.eqb_neq in H
  end.
Ltac gcc :=
  repeat first
    [ rewrite ccolcost_app in *
    | rewrite ccolcost_appn in *
    | rewrite ccolcost_cons in *
    | rewrite ccolcost_consn in *
    | rewrite ccolcost_nil in *
    | rewrite ccolcost_niln in * ];
  rewrite ?ccg_unfold in *.
Ltac gfin := nlbools; gbools; subst; gcc.
Ltac garm_one := intros HH; injection HH; intros; subst; gfin; (lia || nia).
Ltac garm :=
  intros HH; injection HH; intros; subst; gfin;
  repeat match goal with H : _ /\ _ |- _ => destruct H end;
  split; (lia || nia).
Theorem leaf_grow_bounds (s : word) (f : N)
    (s' : word) (f' : N) :
  leaf_act s f = Some (s', f') ->
  (ccolcost s + 2 * f <= ccolcost s' + 2 * f' + 8) /\
  (ccolcost s' + 2 * f' <= ccolcost s + 2 * f + 64).
Proof.
  revert f s' f'. induction s as [|[[X z] c] rest0 IH]; intros f s' f';
    [discriminate|].
  destruct z as [|zp].
  { cbn [leaf_act]. discriminate. }
  destruct zp as [zp'|zp'|].
  -   cbn [leaf_act]. discriminate.
  - destruct zp' as [q|q|]; try (cbn [leaf_act]; discriminate).
    destruct c as [|cp]; [cbn [leaf_act]; discriminate|].
    destruct cp as [cp'|cp'|]; try (cbn [leaf_act]; discriminate).
    cbn [leaf_act].
    destruct ((5 <=? X) && negb (X =? 8) && negb (X =? 12))%bool eqn:EG;
      [|discriminate].
    destruct rest0 as [|[[on zn] cn] t2].
    { destruct (f =? 3) eqn:E3; [garm|].
      destruct (f =? 2) eqn:E2; [garm|].
      destruct (f =? 4) eqn:E4; [garm|discriminate]. }
    destruct (on =? 1) eqn:E1; [discriminate|].
    destruct ((on =? 3) && (zn =? 2) && (cn =? 1) && (f =? 4))%bool eqn:EM.
    { destruct t2 as [|[[o2 z2] c2] [|? ?]].
      - garm.
      - destruct ((o2 =? 4) && (z2 =? 2))%bool eqn:E42; [garm|discriminate].
      - discriminate. }
    destruct ((on =? 4) && (zn =? 2))%bool eqn:ER.
    { destruct t2 as [|[[o2 z2] c2] [|[[o3 z3] c3] [|? ?]]].
      - destruct (f =? 4) eqn:E4; [garm|discriminate].
      - discriminate.
      - destruct ((1 <=? cn) && (o2 =? 3) && (z2 =? 2) && (c2 =? 1)
                  && (o3 =? 4) && (z3 =? 2) && (f =? 4))%bool eqn:EO;
          [|discriminate].
        destruct (cn =? 1) eqn:ECN; garm.
      - discriminate. }
    destruct ((X =? 6) && (on =? 2) && (zn =? 2) && (cn =? 1) && (f =? 4)
              && match t2 with
                 | [(o2,z2,_)] => (o2 =? 4) && (z2 =? 2)
                 | _ => false
                 end)%bool eqn:E6.
    { destruct t2 as [|[[o2 z2] c2] [|? ?]];
        [ repeat rewrite ?Bool.andb_false_r in E6; discriminate
        | | repeat rewrite ?Bool.andb_false_r in E6; discriminate ].
      garm. }
    destruct ((zn =? 1)
              || ((zn =? 2) && (cn =? 1) && (5 <=? on)
                  && negb (on =? 8) && negb (on =? 12)))%bool eqn:EP;
      [|discriminate].
    match goal with
    | |- context [ leaf_act ?a ?b ] =>
        destruct (leaf_act a b) as [[s2 f2]|] eqn:EI
    end; [|discriminate].
    specialize (IH f s2 f2 EI).
    garm.
  -
    cbn [leaf_act].
    destruct (2 <=? c) eqn:EC2.
    { destruct (2 <=? X) eqn:EX2; [|discriminate].
      destruct (2 <? c) eqn:EC3.
      { intros HH; injection HH; intros; subst; gfin.
        rewrite (mul_sub2 c (2 * X + 6) ltac:(lia)). split; lia. }
      apply N.ltb_ge in EC3. apply N.leb_le in EC2.
      assert (Hc2 : c = 2) by lia. subst c. garm. }
    destruct (negb (c =? 1) || negb (2 <=? X))%bool eqn:EC1; [discriminate|].
    apply orb_false_iff in EC1. destruct EC1 as [EC1a EC1b].
    apply negb_false_iff in EC1a. apply negb_false_iff in EC1b.
    destruct rest0 as [|[[B zb] cb] t2].
    { destruct (2 <=? f) eqn:EF2; [garm|].
      destruct (f =? 1) eqn:EF1; [garm|discriminate]. }
    destruct ((zb =? 2) && negb (B =? 8)
              && (negb (B =? 4)
                  || ((cb =? 1)
                      && match t2 with
                         | (o2,z2,_) :: _ =>
                             negb (((o2 =? 4) || (o2 =? 8)) && (z2 =? 2))
                         | [] => true
                         end)))%bool eqn:EB1.
    { destruct ((B =? 5) && (cb =? 1)
                && match t2 with
                   | (o2,z2,_) :: _ => (o2 =? 4) && (z2 =? 2)
                   | [] => false
                   end)%bool eqn:EB5.
      { destruct t2 as [|[[o2 z2] c2] t3];
          [repeat rewrite ?Bool.andb_false_r in EB5; discriminate|].
        apply andb_prop in EB5; destruct EB5 as [EB5 EB5b].
        apply andb_prop in EB5b; destruct EB5b as [EB5b _].
        apply N.eqb_eq in EB5b. subst o2.
        apply andb_prop in EB5; destruct EB5 as [EB5c EB5d].
        apply N.eqb_eq in EB5c. apply N.eqb_eq in EB5d. subst B cb.
        garm. }
      destruct (B =? 1) eqn:EBB.
      { destruct (cb =? 1) eqn:ECB; [garm|discriminate]. }
      destruct ((cb =? 1) && (2 <=? B))%bool eqn:ECB2; [garm|discriminate]. }
    destruct ((B =? 8) && (zb =? 2) && (cb =? 1))%bool eqn:EB8; [garm|].
    destruct ((B =? 4) && (zb =? 2))%bool eqn:EB4.
    { destruct (cb =? 1) eqn:ECB; [garm|].
      destruct (2 <=? cb) eqn:ECB2; [garm|discriminate]. }
    destruct (zb =? 1) eqn:EZ1.
      { destruct (2 <=? cb) eqn:ECB2.
      { destruct (2 <=? B) eqn:EBB2; [|discriminate].
        intros HH; injection HH; intros; subst; gfin.
        rewrite (mul_sub1 cb (2 * B + 6) ltac:(lia)). split; lia. }
      destruct (B =? 1) eqn:EBB.
      { destruct (cb =? 1) eqn:ECB; [garm|discriminate]. }
      destruct ((cb =? 1) && (2 <=? B))%bool eqn:ECB3; [garm|discriminate]. }
    destruct ((3 <=? zb) && (cb =? 1))%bool eqn:EZ3; [|discriminate].
    destruct (B =? 1) eqn:EBB; [garm|].
    destruct (2 <=? B) eqn:EBB2; [garm|discriminate].
Qed.
Theorem leaf_grow (s : word) (f : N) (s' : word) (f' : N) :
  leaf_act s f = Some (s', f') ->
  ccolcost s + 2 * f <= ccolcost s' + 2 * f' + 8.
Proof. intros H; exact (proj1 (leaf_grow_bounds s f s' f' H)). Qed.
Theorem leaf_growU (s : word) (f : N) (s' : word) (f' : N) :
  leaf_act s f = Some (s', f') ->
  ccolcost s' + 2 * f' <= ccolcost s + 2 * f + 64.
Proof. intros H; exact (proj2 (leaf_grow_bounds s f s' f' H)). Qed.
Lemma deliver_tick_z1_grow_bounds
      (fuel : nat) (w : word) (f : N) (i : nat)
      (vd : bool) (o c : N) (w' : word) (f' : N) :
  wat w i = Some (o, 1%N, c) ->
  deliver_tick fuel w f i vd = ROk w' f' ->
  (ccolcost w + 2 * f <= ccolcost w' + 2 * f' + 8) /\
  (ccolcost w' + 2 * f' <= ccolcost w + 2 * f + 64).
Proof.
  destruct fuel as [|fuel]; [discriminate|].
  intros HW. cbn [deliver_tick]. rewrite HW.
  cbn [gZ gO].
  destruct (2 <=? o)%N eqn:EO; [|cbn; discriminate].
  cbn [andb].
  match goal with
  | |- context [ leaf_act ?a ?b ] =>
      destruct (leaf_act a b) as [[s2 f2]|] eqn:EL
  end; [|discriminate].
  intros HH; injection HH; intros; subst.
  pose proof (leaf_grow_bounds _ _ _ _ EL) as HG.
  rewrite ccolcost_app.
  rewrite (ccolcost_split w i). destruct HG. split; lia.
Qed.
Lemma deliver_tick_z1_grow (fuel : nat) (w : word) (f : N) (i : nat)
      (vd : bool) (o c : N) (w' : word) (f' : N) :
  wat w i = Some (o, 1%N, c) ->
  deliver_tick fuel w f i vd = ROk w' f' ->
  ccolcost w + 2 * f <= ccolcost w' + 2 * f' + 8.
Proof.
  intros HW HR. exact (proj1
    (deliver_tick_z1_grow_bounds fuel w f i vd o c w' f' HW HR)).
Qed.
Lemma deliver_tick_z1_growU (fuel : nat) (w : word) (f : N) (i : nat)
      (vd : bool) (o c : N) (w' : word) (f' : N) :
  wat w i = Some (o, 1%N, c) ->
  deliver_tick fuel w f i vd = ROk w' f' ->
  ccolcost w' + 2 * f' <= ccolcost w + 2 * f + 64.
Proof.
  intros HW HR. exact (proj2
    (deliver_tick_z1_grow_bounds fuel w f i vd o c w' f' HW HR)).
Qed.
Lemma dtb4d_le (t : word) (d : N) : dtb4d t = Some d -> d <= 12.
Proof.
  revert d. induction t as [|g t IH]; intros d; [discriminate|].
  cbn [dtb4d].
  destruct (dtb4d t) as [d0|] eqn:E0.
  - pose proof (IH d0 eq_refl) as HI. intros HH; injection HH; intros; subst; lia.
  - destruct ((gO g =? 8) && (gZ g =? 2) && (gC g =? 1))%bool;
      [|discriminate].
    destruct (forallb w42 t); [intros HH; injection HH; lia|].
    destruct t as [|[[o1 z1] c1] [|[[o2 z2] c2] t2]]; try discriminate.
    destruct ((o1 =? 4) && (z1 =? 2) && (1 <=? c1)
              && (o2 =? 3) && (z2 =? 2) && (c2 =? 1))%bool; [|discriminate].
    destruct t2 as [|[[o3 z3] c3] [|? ?]]; try discriminate.
    + intros HH; injection HH; lia.
    + destruct ((o3 =? 4) && (z3 =? 2))%bool;
        [intros HH; injection HH; lia|discriminate].
Qed.
Theorem casc_grow_bounds (n : nat) :
  (forall s f s' f', fire_comp n s f = Some (s', f') ->
     (ccolcost s + 2 * f <= ccolcost s' + 2 * f' + 4) /\
     (ccolcost s' + 2 * f'
       <= 2 * (ccolcost s + 2 * f) + 64))
  /\ (forall cols s f body f', renew_seg n cols s f = Some (body, f') ->
     (ccolcost cols + ccolcost s + 2 * f
       <= ccolcost body + 2 * f' + 4) /\
     (ccolcost body + 2 * f'
       <= 2 * (ccolcost cols + ccolcost s + 2 * f) + 64)).
Proof.
  induction n as [|n IH]; [split; intros; discriminate|].
  destruct IH as [IHfc IHrs].
  split.
  - intros s f s' f'.
    destruct s as [|[[X z] c] rest0]; [discriminate|].
    destruct z as [|zp]; [discriminate|].
    destruct zp as [zp'|zp'|]; try discriminate.
    destruct zp' as [q|q|]; try discriminate.
    destruct c as [|cp]; [discriminate|].
    destruct cp as [cp'|cp'|]; try discriminate.
    cbn [fire_comp].
    destruct (negb (5 <=? X)) eqn:EX; [discriminate|].
    apply negb_false_iff in EX.
    destruct rest0 as [|[[Y zY] cY] rest].
    { destruct (2 <=? f) eqn:E2; [garm|discriminate]. }
    destruct ((Y =? 4) && (zY =? 2))%bool eqn:EY4.
    { destruct (negb (1 <=? cY)) eqn:ENL; [discriminate|].
      apply negb_false_iff in ENL.
      destruct rest as [|gr rest'].
      { destruct (f =? 4) eqn:EF4.
        { destruct (1 <? cY) eqn:ENL2; garm. }
        destruct (5 <=? f) eqn:EF5; [|discriminate].
        destruct (1 <? cY) eqn:ENL2; garm. }
      destruct (seek (gr :: rest')) as [cols s2] eqn:Eseek.
      pose proof (ccolcost_seek_eq _ _ _ Eseek) as HSK.
      destruct s2 as [|[[o4 z4] c4] s2t].
      { destruct (5 <=? f) eqn:EF5; [garm|].
        destruct (f =? 3) eqn:EF3.
        { match goal with
          | |- context [ dtb3_conv ?a ] =>
              destruct (dtb3_conv a) as [bd|] eqn:ED
          end; [|discriminate].
          pose proof (dtb3_conv_ccolcost _ _ ED) as HD.
          garm. }
        destruct (f =? 4) eqn:EF4; [|discriminate].
        match goal with
        | |- context [ dtb4_conv ?a ] =>
            destruct (dtb4_conv a) as [bd|] eqn:ED
        end; [|discriminate].
        destruct (dtb4d_some _ _ ED) as [dd EDD].
        pose proof (dtb4_conv_ccolcost _ _ _ ED EDD) as HD.
        pose proof (dtb4d_le _ _ EDD) as HDL. garm. }
      destruct ((o4 =? 4) && (z4 =? 3) && (c4 =? 1))%bool eqn:E43.
      { destruct s2t as [|[[o5 z5] Bq] rest2].
        { destruct (endR_seg cols f) as [seg2|] eqn:EE; [|discriminate].
          pose proof (endR_seg_ccolcost _ _ _ EE) as HE. garm. }
        destruct ((o5 =? 4) && (z5 =? 2))%bool eqn:E52.
        { destruct (1 <=? Bq) eqn:EB; [|discriminate].
          destruct rest2 as [|gr2 rest2'].
          { destruct (f =? 4) eqn:EF4.
            { destruct (lawR_seg cols Bq) as [seg2|] eqn:EE;
                [|discriminate].
              pose proof (lawR_seg_ccolcost _ _ _ EE) as HE. garm. }
            destruct (5 <=? f) eqn:EF5; [|discriminate].
            destruct (jump_seg cols Bq) as [seg2|] eqn:EE; [|discriminate].
            pose proof (jump_seg_ccolcost _ _ _ EE) as HE. garm. }
          destruct (jump_seg cols Bq) as [seg|] eqn:EJ; [|discriminate].
          pose proof (jump_seg_ccolcost _ _ _ EJ) as HJ.
          destruct (seek (gr2 :: rest2')) as [cols2 s3] eqn:Eseek2.
          pose proof (ccolcost_seek_eq _ _ _ Eseek2) as HSK2.
          match goal with
          | |- context [ renew_seg ?a ?b ?cc ?d ] =>
              destruct (renew_seg a b cc d) as [[bd fd]|] eqn:ER
          end.
          { pose proof (IHrs cols2 s3 f bd fd ER) as IHq. garm. }
          match goal with
          | |- context [ fire_comp ?a ?b ?cc ] =>
              destruct (fire_comp a b cc) as [[sd fd]|] eqn:EFq
          end.
          { pose proof (IHfc s3 f sd fd EFq) as IHq. garm. }
          match goal with
          | |- context [ sand_leaf ?a && ?b ] =>
              destruct (sand_leaf a && b)%bool
          end; [discriminate|].
          match goal with
          | |- context [ leaf_act ?b ?cc ] =>
              destruct (leaf_act b cc) as [[sd fd]|] eqn:EL
          end.
          { pose proof (leaf_grow_bounds _ _ _ _ EL) as IHq. garm. }
          destruct s3 as [|? ?]; [|discriminate].
          destruct (5 <=? f) eqn:EF5; [garm|].
          destruct (f =? 4) eqn:EF4; [|discriminate].
          destruct (dtb4_conv cols2) as [cols2'|] eqn:ED.
          { destruct (dtb4d_some _ _ ED) as [dd EDD].
            pose proof (dtb4_conv_ccolcost _ _ _ ED EDD) as HD.
            pose proof (dtb4d_le _ _ EDD) as HDL. garm. }
          destruct (forallb w42 cols2); [|discriminate].
          destruct (lawR_seg cols Bq) as [seg2|] eqn:EE; [|discriminate].
          pose proof (lawR_seg_ccolcost _ _ _ EE) as HE. garm. }
        destruct ((z5 =? 3) && (Bq =? 1)
                  && match rest2 with [] => true | _ => false end
                  && (f =? 4) && (1 <=? o5))%bool eqn:EYY.
        { destruct rest2 as [|? ?];
            [|repeat rewrite ?Bool.andb_false_r, ?Bool.andb_false_l in EYY;
              discriminate].
          destruct (endY_seg cols o5) as [seg2|] eqn:EE; [|discriminate].
          pose proof (endY_seg_ccolcost _ _ _ EE) as HE. garm. }
        match goal with
        | |- context [ leaf_act ?b ?cc ] =>
            destruct (leaf_act b cc) as [[sd fd]|] eqn:EL
        end; [|discriminate].
        pose proof (leaf_grow_bounds _ _ _ _ EL) as IHq. garm. }
      destruct ((o4 =? 4) && (z4 =? 4) && (c4 =? 1))%bool eqn:E44.
      { destruct s2t as [|[[on zn] cn] t2]; [discriminate|].
        destruct ((on =? 4) && (zn =? 2) && (1 <=? cn))%bool eqn:E42;
          [|discriminate].
        destruct (jump_seg cols cn) as [seg2|] eqn:EE; [|discriminate].
        pose proof (jump_seg_ccolcost _ _ _ EE) as HE. garm. }
      match goal with
      | |- context [ fire_comp ?a ?b ?cc ] =>
          destruct (fire_comp a b cc) as [[sd fd]|] eqn:EFq
      end.
      { match goal with
        | EFq : fire_comp ?a ?b ?cc = _ |- _ =>
            pose proof (IHfc b cc sd fd EFq) as IHq
        end. garm. }
      match goal with
      | |- context [ leaf_act ?b ?cc ] =>
          destruct (leaf_act b cc) as [[sd fd]|] eqn:EL
      end; [|discriminate].
      pose proof (leaf_grow_bounds _ _ _ _ EL) as IHq. garm. }
    destruct ((Y =? 8) && (zY =? 2) && (cY =? 1))%bool eqn:EY8.
    { match goal with
      | |- context [ tick_target ?a ?b ] =>
          destruct (tick_target a b) as [jt|] eqn:Etg
      end; [|discriminate].
      match goal with
      | |- context [ match wat ?a jt with _ => _ end ] =>
          destruct (wat a jt) as [[[oq zq] cq]|] eqn:Ewat
      end; [|discriminate].
      destruct (zq =? 1) eqn:EZQ; [|discriminate].
      apply N.eqb_eq in EZQ. subst zq.
      match goal with
      | |- context [ deliver_tick ?fu ?a ?b ?jj ?vd ] =>
          destruct (deliver_tick fu a b jj vd) as [s3 f3| |] eqn:EDT
      end; [|discriminate|discriminate].
      pose proof (deliver_tick_z1_grow_bounds
        _ _ _ _ _ _ _ _ _ Ewat EDT) as HG.
      garm. }
    destruct ((zY =? 1) && (cY =? 1) && (1 <=? Y)
              && match rest with [] => true | _ => false end)%bool eqn:EZ1.
    { destruct rest as [|? ?];
        [|repeat rewrite ?Bool.andb_false_r, ?Bool.andb_false_l in EZ1;
          discriminate].
      destruct (2 <=? f) eqn:E2; [garm|discriminate]. }
    destruct ((zY =? 3) && (cY =? 1) && (1 <=? Y) && (f =? 4))%bool eqn:EZ3.
    { destruct rest as [|[[o2 z2] c2] r2]; [discriminate|].
      destruct r2 as [|? ?]; [|discriminate].
      destruct ((o2 =? 4) && (z2 =? 2) && (1 <=? c2))%bool eqn:E42;
        [|discriminate].
      destruct (1 <? c2) eqn:EC2; garm. }
    destruct ((zY =? 1) && (cY =? 1) && (1 <=? Y)
              && match rest with
                 | (o2,z2,c2) :: _ => (o2 =? 4) && (z2 =? 2) && (1 <=? c2)
                 | [] => false
                 end)%bool eqn:EZL.
    { destruct rest as [|[[o2 z2] c2] r2]; [discriminate|].
      destruct (1 <? c2) eqn:EC2; garm. }
    destruct ((zY =? 1) && (2 <=? cY) && (2 <=? Y))%bool eqn:EZS.
    { destruct (2 <? cY) eqn:ECY.
      { intros HH; injection HH; intros; subst; gfin.
        rewrite (mul_sub2 cY (2 * Y + 6) ltac:(lia)). split; lia. }
      apply N.ltb_ge in ECY.
      nlbools. assert (HcY : cY = 2) by lia. subst cY. garm. }
    destruct ((zY =? 1) && (cY =? 1) && (1 <=? Y)
              && match rest with
                 | (o2,z2,c2) :: _ => (z2 =? 1) && (c2 =? 1) && (1 <=? o2)
                 | [] => false
                 end)%bool eqn:EZZ.
    { destruct rest as [|[[k kz] kc] r2]; [discriminate|].
      destruct (k =? 1) eqn:EK; garm. }
    destruct ((zY =? 1) && (cY =? 1) && (1 <=? Y)
              && match rest with
                 | (o2,z2,c2) :: _ =>
                     (z2 =? 2) && (1 <=? o2) && (o2 <=? 3) && (c2 =? 1)
                 | [] => false
                 end)%bool eqn:EZ2; [|discriminate].
    destruct rest as [|[[b bz] bc] r2]; [discriminate|].
    destruct (b =? 1) eqn:EBB; garm.
  - intros cols s f body f'.
    destruct s as [|[[o z] c] rest]; [discriminate|].
    destruct o as [|op]; [discriminate|].
    destruct op as [op'|op'|]; try discriminate.
    destruct op' as [q|q|]; try discriminate.
    destruct q as [r|r|]; try discriminate.
    destruct z as [|zp]; [discriminate|].
    destruct zp as [zp'|zp'|]; try discriminate.
    destruct zp' as [q|q|]; try discriminate.
    destruct c as [|cp]; [discriminate|].
    destruct cp as [cp'|cp'|]; try discriminate.
    cbn [renew_seg].
    destruct rest as [|[[o5 z5] Bq] rest2].
    { destruct (endR_seg cols f) as [bd|] eqn:EE; [|discriminate].
      pose proof (endR_seg_ccolcost _ _ _ EE) as HE. garm. }
    destruct ((o5 =? 4) && (z5 =? 2) && (1 <=? Bq))%bool eqn:E52.
    { destruct rest2 as [|gr2 rest2'].
      { destruct (f =? 4) eqn:EF4.
        { destruct (lawR_seg cols Bq) as [bd|] eqn:EE; [|discriminate].
          pose proof (lawR_seg_ccolcost _ _ _ EE) as HE. garm. }
        destruct (5 <=? f) eqn:EF5; [|discriminate].
        destruct (jump_seg cols Bq) as [seg|] eqn:EE; [|discriminate].
        pose proof (jump_seg_ccolcost _ _ _ EE) as HE. garm. }
      destruct (jump_seg cols Bq) as [seg|] eqn:EJ; [|discriminate].
      pose proof (jump_seg_ccolcost _ _ _ EJ) as HJ.
      destruct (seek (gr2 :: rest2')) as [cols2 s3] eqn:Eseek2.
      pose proof (ccolcost_seek_eq _ _ _ Eseek2) as HSK2.
      match goal with
      | |- context [ renew_seg ?a ?b ?cc ?d ] =>
          destruct (renew_seg a b cc d) as [[bd fd]|] eqn:ER
      end.
      { pose proof (IHrs cols2 s3 f bd fd ER) as IHq. garm. }
      destruct s3 as [|[[o7 z7] c7] s3t].
      { match goal with
        | |- context [ leaf_act ?b ?cc ] =>
            destruct (leaf_act b cc) as [[sd fd]|] eqn:EL
        end.
        { pose proof (leaf_grow_bounds _ _ _ _ EL) as IHq. garm. }
        destruct (5 <=? f) eqn:EF5; [garm|].
        destruct (f =? 4) eqn:EF4; [|discriminate].
        destruct (dtb4_conv cols2) as [cols2'|] eqn:ED.
        { destruct (dtb4d_some _ _ ED) as [dd EDD].
          pose proof (dtb4_conv_ccolcost _ _ _ ED EDD) as HD.
          pose proof (dtb4d_le _ _ EDD) as HDL. garm. }
        destruct (forallb w42 cols2); [|discriminate].
        destruct (lawR_seg cols Bq) as [seg2|] eqn:EE; [|discriminate].
        pose proof (lawR_seg_ccolcost _ _ _ EE) as HE. garm. }
      destruct ((z7 =? 3) && (c7 =? 1))%bool eqn:E73.
      { match goal with
        | |- context [ fire_comp ?a ?b ?cc ] =>
            destruct (fire_comp a b cc) as [[sd fd]|] eqn:EFq
        end.
        { match goal with
          | EFq : fire_comp ?a ?b ?cc = _ |- _ =>
              pose proof (IHfc b cc sd fd EFq) as IHq
          end. garm. }
        discriminate. }
      match goal with
      | |- context [ sand_leaf ?a ] => destruct (sand_leaf a)
      end; [discriminate|].
      match goal with
      | |- context [ leaf_act ?b ?cc ] =>
          destruct (leaf_act b cc) as [[sd fd]|] eqn:EL
      end; [|discriminate].
      pose proof (leaf_grow_bounds _ _ _ _ EL) as IHq. garm. }
    destruct ((z5 =? 3) && (Bq =? 1)
              && match rest2 with [] => true | _ => false end
              && (f =? 4) && (1 <=? o5))%bool eqn:EYY; [|discriminate].
    destruct rest2 as [|? ?];
      [|repeat rewrite ?Bool.andb_false_r, ?Bool.andb_false_l in EYY;
        discriminate].
    destruct (endY_seg cols o5) as [bd|] eqn:EE; [|discriminate].
    pose proof (endY_seg_ccolcost _ _ _ EE) as HE. garm.
Qed.
Theorem casc_grow (n : nat) :
  (forall s f s' f', fire_comp n s f = Some (s', f') ->
     ccolcost s + 2 * f <= ccolcost s' + 2 * f' + 4)
  /\ (forall cols s f body f', renew_seg n cols s f = Some (body, f') ->
     ccolcost cols + ccolcost s + 2 * f
       <= ccolcost body + 2 * f' + 4).
Proof.
  destruct (casc_grow_bounds n) as [HF HR]. split.
  - intros s f s' f' H. exact (proj1 (HF s f s' f' H)).
  - intros cols s f body f' H. exact (proj1 (HR cols s f body f' H)).
Qed.
Theorem casc_growU (n : nat) :
  (forall s f s' f', fire_comp n s f = Some (s', f') ->
     ccolcost s' + 2 * f'
       <= 2 * (ccolcost s + 2 * f) + 64)
  /\ (forall cols s f body f', renew_seg n cols s f = Some (body, f') ->
     ccolcost body + 2 * f'
       <= 2 * (ccolcost cols + ccolcost s + 2 * f) + 64).
Proof.
  destruct (casc_grow_bounds n) as [HF HR]. split.
  - intros s f s' f' H. exact (proj2 (HF s f s' f' H)).
  - intros cols s f body f' H. exact (proj2 (HR cols s f body f' H)).
Qed.
Ltac garm ::= garm_one.
Theorem jump_comp_grow (pre : word) (B : N) (post : word) (f : N)
        (body : word) (f' : N) :
  1 <= B ->
  jump_comp pre B post f = Some (JMP, body, f') ->
  ccolcost pre + 14 * B + ccolcost post + 2 * f + 4
    <= ccolcost body + 2 * f'.
Proof.
  intros HB. unfold jump_comp.
  destruct post as [|g0 postT].
  { destruct (f =? 4) eqn:EF4.
    { destruct (lawR_seg pre B) as [bd|] eqn:EE; [|discriminate].
      pose proof (lawR_seg_ccolcost _ _ _ EE) as HE. garm. }
    destruct (5 <=? f) eqn:EF5; [|discriminate].
    destruct (jump_seg pre B) as [segp|] eqn:EE; [|discriminate].
    pose proof (jump_seg_ccolcost _ _ _ EE) as HE. garm. }
  destruct (jump_seg pre B) as [segp|] eqn:EJ; [|discriminate].
  pose proof (jump_seg_ccolcost _ _ _ EJ) as HJ.
  destruct (seek (g0 :: postT)) as [cols2 s3] eqn:Esk.
  pose proof (ccolcost_seek_eq _ _ _ Esk) as HSK.
  match goal with
  | |- context [ renew_seg ?a ?b ?cc ?d ] =>
      destruct (renew_seg a b cc d) as [[bd fd]|] eqn:ER
  end.
  { pose proof (proj2 (casc_grow (List.length s3)) cols2 s3 f bd fd ER) as IHq.
    garm. }
  destruct s3 as [|[[o7 z7] c7] s3t].
  { cbn [leaf_act].
    destruct (5 <=? f) eqn:EF5; [garm|].
    destruct (f =? 4) eqn:EF4; [|discriminate].
    destruct (dtb4_conv cols2) as [cols2'|] eqn:ED.
    { destruct (dtb4d_some _ _ ED) as [dd EDD].
      pose proof (dtb4_conv_ccolcost _ _ _ ED EDD) as HD. garm. }
    destruct (forallb w42 cols2); [|discriminate].
    destruct (lawR_seg pre B) as [seg2|] eqn:EE; [|discriminate].
    pose proof (lawR_seg_ccolcost _ _ _ EE) as HE. garm. }
  destruct ((z7 =? 3) && (c7 =? 1))%bool eqn:E73.
  { match goal with
    | |- context [ fire_comp ?a ?b ?cc ] =>
        destruct (fire_comp a b cc) as [[sd fd]|] eqn:EFq
    end; [|discriminate].
    match goal with
    | EFq : fire_comp ?a ?b ?cc = _ |- _ =>
        pose proof (proj1 (casc_grow a) b cc sd fd EFq) as IHq
    end. garm. }
  match goal with
  | |- context [ sand_leaf ?a ] => destruct (sand_leaf a)
  end; [discriminate|].
  match goal with
  | |- context [ leaf_act ?b ?cc ] =>
      destruct (leaf_act b cc) as [[sd fd]|] eqn:EL
  end; [|discriminate].
  pose proof (leaf_grow _ _ _ _ EL) as IHq. garm.
Qed.
