Definition sstate : Type := (word * N * nat)%type.
Definition step1 (s : sstate) : option sstate :=
  let '(w, f, h) := s in
  match step w f h with
  | (ROk w2 f2, i) => Some (w2, f2, if Nat.ltb i 5 then O else (i - 4)%nat)
  | _ => None
  end.
Fixpoint stepk (k : nat) (s : sstate) : option sstate :=
  match k with
  | O => Some s
  | S k' => match step1 s with Some s' => stepk k' s' | None => None end
  end.
Definition stepN (n : N) (s : sstate) : option sstate := stepk (N.to_nat n) s.
Definition bg_eqb (a b : bg) : bool :=
  (gO a =? gO b) && (gZ a =? gZ b) && (gC a =? gC b).
Fixpoint word_eqb (a b : word) : bool :=
  match a, b with
  | [], [] => true
  | x :: a', y :: b' => bg_eqb x y && word_eqb a' b'
  | _, _ => false
  end.
Definition DBu_tbl : list N :=
  [3;3;3;3; 2;2;2;3; 2;2;2;2; 1;1;1;2; 1;1;1;1; 0;0;0;1; 0;0;0;0].
Definition DBu (p : N) : N := nth (N.to_nat p) DBu_tbl 3.
Definition EMt (p : N) : N := if p <? 4 then 0 else (p - 4) / 8 + 1.
Definition marks (t : N) : N := 4 * (t / 28) + EMt (t mod 28).
Definition phase_form (p : N) : word :=
  if p <? 4 then
    (if p =? 3 then [(7,3,1)] else [(7,1,1); (3 - p, 2, 1)])
  else
    let x := 6 - (p - 4) / 8 in
    let q := (p - 4) mod 8 in
    if q =? 3 then [(x,1,1)]
    else if q =? 7 then [(x,3,1)]
    else [(x,1,1); (7 - q, 2, 1)].
Definition phase_len (p : N) : nat := if (p mod 4) =? 3 then 1%nat else 2%nat.
Definition detect_phase (w : word) (j : nat) : option N :=
  match wat w j with
  | None => None
  | Some (o,z,c) =>
      if negb (c =? 1) then None
      else if z =? 3 then
        (if o =? 7 then Some 3
         else if o =? 6 then Some 11
         else if o =? 5 then Some 19
         else if o =? 4 then Some 27
         else None)
      else if negb ((z =? 1) && (4 <=? o) && (o <=? 7)) then None
      else
        let bare :=
          match wat w (S j) with
          | Some (o2,z2,_) =>
              if (o2 =? 4) && (z2 =? 2) then Some (4 + (6 - o) * 8 + 3) else None
          | None => None
          end in
        let fol :=
          match wat w (S j) with
          | Some (o2,z2,c2) => if (z2 =? 2) && (c2 =? 1) then Some o2 else None
          | None => None
          end in
        if o =? 7 then
          match fol with
          | Some b =>
              if b =? 3 then Some 0
              else if b =? 2 then Some 1
              else if b =? 1 then Some 2
              else None
          | None => None
          end
        else
          let base := 4 + (6 - o) * 8 in
          match fol with
          | Some b =>
              if (5 <=? b) && (b <=? 7) then Some (base + (7 - b))
              else if (1 <=? b) && (b <=? 3) then Some (base + 4 + (3 - b))
              else bare
          | None => bare
          end
  end.
Definition FLOOR : N := 40.
Definition THRESH : N := 2.
Definition lvl_big (g : bg) : bool :=
  (gO g =? 4) && (gZ g =? 2) && (FLOOR <=? gC g).
Definition spacer (g : bg) : bool :=
  (gO g =? 8) && (gZ g =? 2) && (gC g =? 1).
Fixpoint clean_above (w : word) (k : nat) (m : nat) : bool :=
  match m with
  | O => true
  | S m' =>
      if Nat.ltb k 1 then false
      else match wat w k, wat w (k - 1) with
           | Some l, Some s =>
               lvl_big l && spacer s && clean_above w (k - 2) m'
           | _, _ => false
           end
  end.
Fixpoint count_clean (w : word) (k : nat) (mmax : nat) : nat :=
  match mmax with
  | O => O
  | S m' =>
      if Nat.ltb k 1 then O
      else match wat w k, wat w (k - 1) with
           | Some l, Some s =>
               if lvl_big l && spacer s
               then S (count_clean w (k - 2) m')
               else O
           | _, _ => O
           end
  end.
Definition adj4 (g : bg) : bg :=
  let '(o,z,c) := g in if (o =? 4) && (z =? 2) then (o, z, c - 4) else g.
Definition bulk_stage (w : word) (j : nat) (p : N) (t : N)
  : option (word * nat * N * N) :=
  let total := p + t in
  let full := N.to_nat (total / 28) in
  let rem := total mod 28 in
  let emit := marks total - marks p in
  let npair := phase_len p in
  let blw := (j + npair)%nat in
  match wat w blw with
  | None => None
  | Some gb =>
      if negb (lvl_big gb) then None
      else if Nat.eqb (S blw) (length w) then None
      else if Nat.eqb full 0 then
        Some (subst_at j npair (phase_form rem)
                (subst_at blw 1 [(4, 2, (gC gb + DBu rem) - DBu p)] w),
              j, rem, emit)
      else if Nat.ltb j (2 * full) then None
      else if negb (clean_above w (j - 1) full) then None
      else
        let nh := (j - 2 * full)%nat in
        match firstn (2 * full - 1) (skipn (S nh) w) with
        | (o0,z0,c_0) :: rest0 =>
            let strip := phase_form rem
                         ++ [(o0, z0, (c_0 + DBu rem) - 3)]
                         ++ map adj4 rest0 ++ [(8,2,1)] in
            Some (firstn nh w ++ strip
                    ++ ((4, 2, (gC gb - 1) - DBu p) :: skipn (S blw) w),
                  nh, rem, emit)
        | [] => None
        end
  end.
Definition dtick_after_seek (cols2 s3 : word) (f : N)
  : option (word * N) :=
  match renew_seg (length s3) cols2 s3 f with
  | Some (body, f2) => Some (body, f2)
  | None =>
      match (match s3 with
             | (o7,z7,c7) :: _ =>
                 if (z7 =? 3) && (c7 =? 1) then fire_comp (length s3) s3 f
                 else if sand_leaf s3 then None
                 else leaf_act s3 f
             | [] => leaf_act s3 f
             end) with
      | Some (s3', f2) => Some (cols2 ++ s3', f2)
      | None => None
      end
  end.
Definition dtick (rest : word) (f : N) : option (word * N) :=
  let '(cols2, s3) := seek rest in
  dtick_after_seek cols2 s3 f.
Definition CFUEL : nat := 67.
Fixpoint setsfx (n : nat) (w : word) (s : word) : word :=
  match n, w with
  | O, _ => s
  | S n', g :: t => g :: setsfx n' t s
  | S _, [] => s
  end.
Definition bulk_take (w : word) (cur tg : nat) (pk tk : N) : N :=
  let mgeom := Nat.div2 (tg - cur - 2) in
  let mneed := N.to_nat ((pk + tk) / 28) in
  let m := Nat.min mneed (count_clean w (tg - 1) (Nat.min mgeom mneed)) in
  if Nat.eqb m O then N.min tk (27 - pk)
  else N.min tk (28 * N.of_nat m - pk).
Fixpoint cascade (fu : nat) (w : word) (f : N) (st : list (nat * N))
  : option (word * N) :=
  match fu with
  | O => None
  | S fu' =>
      match st with
      | [] => Some (w, f)
      | (cur, tk) :: rest =>
        if tk =? 0 then cascade fu' w f rest
        else
          let sf := skipn cur w in
          let '(cols2, s3) := seek sf in
          match s3 with
          | [] => None
          | _ :: _ =>
            let tg := (cur + length cols2)%nat in
            match (if Nat.ltb (cur + 2) tg then
                     match detect_phase w tg with
                     | Some pk =>
                         let take := bulk_take w cur tg pk tk in
                         if THRESH <=? take
                         then match bulk_stage w tg pk take with
                              | Some (w2, t2, p2k, ek) =>
                                  Some (w2, t2, p2k, ek, take)
                              | None => None
                              end
                         else None
                     | None => None
                     end
                   else None) with
            | Some (w2, t2, p2k, ek, take) =>
                cascade fu' (normalize w2) f
                  ((t2 + phase_len p2k, ek)%nat :: (cur, tk - take) :: rest)
            | None =>
                match dtick sf f with
                | Some (sfx, f2) =>
                    cascade fu' (normalize (setsfx cur w sfx)) f2
                            ((cur, tk - 1) :: rest)
                | None => None
                end
            end
          end
      end
  end.
Inductive gres : Type :=
  | GOk (n : N) (w : word) (f : N) (h : nat)
  | GNo.
Definition MARGIN : nat := 6.
Definition front_blind (w : word) : bool :=
  Nat.leb MARGIN (length w) && forallb is_col (firstn MARGIN w).
Fixpoint gen_try (k : nat) (w : word) (f : N) (cN : N)
                 (i : nat) (p : N) (m : nat) : gres :=
  match k with
  | O => GNo
  | S k' =>
      if Nat.eqb m O then GNo else
      let t := 28 * N.of_nat m - p in
      match bulk_stage w i p t with
      | None => GNo
      | Some (w1, j2, rem, emit) =>
          let w2 := subst_at O 1 [(2,2,cN + t)] w1 in
          match cascade CFUEL (normalize w2) f
                        [((j2 + phase_len rem)%nat, emit)] with
          | Some (w3, f3) =>
              GOk t w3 f3
                  (if Nat.ltb (j2 + 2) 5 then O else (j2 + 2 - 4)%nat)
          | None => gen_try k' w f cN i p (Nat.div2 m)
          end
      end
  end.
Definition TRIES : nat := 20.
Definition genstep (w : word) (f : N) (hint : nat) : gres :=
  if negb (front_blind w) then GNo
  else match first_rule front_rules w f with
  | Some _ => GNo
  | None =>
    if negb (f =? 4) then GNo else
    match w with
    | (2,2,cN) :: _ =>
      let start := if Nat.ltb hint 1 then 1%nat else hint in
      match find_active w start with
      | None => GNo
      | Some i =>
        if negb (Nat.ltb (S MARGIN) i) then GNo else
        if negb (forallb is_col (firstn i w)) then GNo else
        match detect_phase w i with
        | None => GNo
        | Some p =>
          let mmax := Nat.div2 (i - MARGIN) in
          gen_try TRIES w f cN i p (count_clean w (i - 1) mmax)
        end
      end
    | _ => GNo
    end
  end.
Inductive gorun : Type :=
  | GGuard (w : word) (f : N) (n : N)
  | GOut   (w : word) (f : N) (n : N)
  | GBad   (w : word) (f : N) (n : N).
Fixpoint gen_brun (fuel : nat) (w : word) (f : N) (h : nat) (n : N) : gorun :=
  match fuel with
  | O => GOut w f n
  | S fu =>
      match genstep w f h with
      | GOk k w2 f2 h2 => gen_brun fu w2 f2 h2 (n + k)
      | GNo =>
          match step w f h with
          | (ROk w2 f2, i) =>
              gen_brun fu w2 f2 (if Nat.ltb i 5 then O else (i - 4)%nat) (n + 1)
          | (RHalt, _) => GGuard w f n
          | (RBad, _)  => GBad w f n
          end
      end
  end.
