Lemma cadd_0_l (c : cost) : cadd czero c = c.
Proof. destruct c as [a b]; unfold cadd, czero; cbn [fst snd]; f_equal; lia. Qed.
Lemma cadd_0_r (c : cost) : cadd c czero = c.
Proof. destruct c as [a b]; unfold cadd, czero; cbn [fst snd]; f_equal; lia. Qed.
Lemma cadd_assoc (c1 c2 c3 : cost) :
  cadd (cadd c1 c2) c3 = cadd c1 (cadd c2 c3).
Proof.
  destruct c1 as [a1 b1], c2 as [a2 b2], c3 as [a3 b3].
  unfold cadd; cbn [fst snd]; f_equal; lia.
Qed.
Lemma Count_cadd_cx (a b : N) : cadd (cx a) (cx b) = cx (a + b)%N.
Proof. reflexivity. Qed.
Lemma cx_0 : cx 0%N = czero.
Proof. reflexivity. Qed.
Definition cstep1 (s : sstate)
  : option (sstate * cost) :=
  let '(w, f, h) := s in
  match cstep w f h with
  | (ROk w2 f2, i, d) =>
      Some ((w2, f2, if Nat.ltb i 5 then O else (i - 4)%nat), d)
  | _ => None
  end.
Lemma cstep1_proj (s : sstate) :
  option_map fst (cstep1 s) = step1 s.
Proof.
  destruct s as [[w f] h].
  unfold cstep1, step1.
  pose proof (cstep_proj w f h) as HP. unfold cproj in HP.
  destruct (cstep w f h) as [[r i] d] eqn:E.
  cbn [fst snd] in HP. rewrite <- HP.
  destruct r; reflexivity.
Qed.
Corollary cstep1_state (s s2 : sstate) (d : cost) :
  cstep1 s = Some (s2, d) -> step1 s = Some s2.
Proof.
  intros E. rewrite <- cstep1_proj, E. reflexivity.
Qed.
Corollary cstep1_of_step1 (s s2 : sstate) :
  step1 s = Some s2 -> exists d, cstep1 s = Some (s2, d).
Proof.
  intros E. pose proof (cstep1_proj s) as HP. rewrite E in HP.
  destruct (cstep1 s) as [[s' d]|]; cbn [option_map fst] in HP;
    [|discriminate].
  injection HP as <-. now exists d.
Qed.
Fixpoint cbrun_from (k : nat) (s : sstate) (acc : cost)
  : option (sstate * cost) :=
  match k with
  | O => Some (s, acc)
  | S k' =>
      match cstep1 s with
      | Some (s', d) => cbrun_from k' s' (cadd acc d)
      | None => None
      end
  end.
Definition cbrun (k : nat) (s : sstate)
  : option (sstate * cost) := cbrun_from k s czero.
Lemma cbrun_from_shift (k : nat) (s : sstate) (acc : cost) :
  cbrun_from k s acc
  = match cbrun k s with
    | Some (s', Dc) => Some (s', cadd acc Dc)
    | None => None
    end.
Proof.
  revert s acc. induction k as [|k IH]; intros s acc; cbn [cbrun_from].
  - unfold cbrun. cbn [cbrun_from]. now rewrite cadd_0_r.
  - unfold cbrun. cbn [cbrun_from].
    destruct (cstep1 s) as [[s' d]|]; [|reflexivity].
    rewrite (IH s' (cadd acc d)), (IH s' (cadd czero d)).
    unfold cbrun.
    destruct (cbrun_from k s' czero) as [[s2 Dc]|]; [|reflexivity].
    now rewrite cadd_0_l, cadd_assoc.
Qed.
Lemma cbrun_0 (s : sstate) : cbrun 0 s = Some (s, czero).
Proof. reflexivity. Qed.
Lemma cbrun_S (k : nat) (s : sstate) :
  cbrun (S k) s
  = match cstep1 s with
    | Some (s', d) =>
        match cbrun k s' with
        | Some (s2, Dc) => Some (s2, cadd d Dc)
        | None => None
        end
    | None => None
    end.
Proof.
  unfold cbrun at 1. cbn [cbrun_from].
  destruct (cstep1 s) as [[s' d]|]; [|reflexivity].
  rewrite (cbrun_from_shift k s' (cadd czero d)).
  destruct (cbrun k s') as [[s2 Dc]|]; [|reflexivity].
  now rewrite cadd_0_l.
Qed.
Theorem cbrun_proj (k : nat) (s : sstate) :
  option_map fst (cbrun k s) = stepk k s.
Proof.
  revert s. induction k as [|k IH]; intros s.
  - reflexivity.
  - rewrite cbrun_S. cbn [stepk].
    pose proof (cstep1_proj s) as HP.
    destruct (cstep1 s) as [[s' d]|] eqn:E;
      cbn [option_map fst] in HP; rewrite <- HP; [|reflexivity].
    rewrite <- (IH s').
    destruct (cbrun k s') as [[s2 Dc]|]; reflexivity.
Qed.
Corollary cbrun_state (k : nat) (s s' : sstate) (Dc : cost) :
  cbrun k s = Some (s', Dc) -> stepk k s = Some s'.
Proof. intros E. rewrite <- cbrun_proj, E. reflexivity. Qed.
Corollary cbrun_of_stepk (k : nat) (s s' : sstate) :
  stepk k s = Some s' -> exists Dc, cbrun k s = Some (s', Dc).
Proof.
  intros E. pose proof (cbrun_proj k s) as HP. rewrite E in HP.
  destruct (cbrun k s) as [[s2 Dc]|]; cbn [option_map fst] in HP;
    [|discriminate].
  injection HP as <-. now exists Dc.
Qed.
Lemma cbrun_add (a b : nat) (s : sstate) :
  cbrun (a + b) s
  = match cbrun a s with
    | Some (s1, D1) =>
        match cbrun b s1 with
        | Some (s2, D2) => Some (s2, cadd D1 D2)
        | None => None
        end
    | None => None
    end.
Proof.
  revert s. induction a as [|a IH]; intros s.
  - cbn [Nat.add]. rewrite cbrun_0.
    destruct (cbrun b s) as [[s2 D2]|]; [|reflexivity].
    now rewrite cadd_0_l.
  - replace (S a + b)%nat with (S (a + b))%nat by lia.
    rewrite !cbrun_S.
    destruct (cstep1 s) as [[s' d]|]; [|reflexivity].
    rewrite IH.
    destruct (cbrun a s') as [[s1 D1]|]; [|reflexivity].
    destruct (cbrun b s1) as [[s2 D2]|]; [|reflexivity].
    now rewrite cadd_assoc.
Qed.
Lemma cbrun_split (a b : nat) (s s1 : sstate) (D1 : cost) :
  cbrun a s = Some (s1, D1) ->
  cbrun (a + b) s
  = match cbrun b s1 with
    | Some (s2, D2) => Some (s2, cadd D1 D2)
    | None => None
    end.
Proof. intros H. now rewrite cbrun_add, H. Qed.
Lemma cbrun_exact_cons (d : cost) (a b : N) :
  d = cx a -> cadd d (cx b) = cx (a + b)%N.
Proof. intros ->. apply Count_cadd_cx. Qed.
Lemma cadds_emp_l (a b : cost) :
  (chi a < clo a)%N -> cadds a b = cundef.
Proof.
  intros H. unfold cadds.
  replace (N.ltb (chi a) (clo a)) with true
    by (symmetry; apply N.ltb_lt; exact H).
  reflexivity.
Qed.
Lemma cadds_emp_r (a b : cost) :
  (chi b < clo b)%N -> cadds a b = cundef.
Proof.
  intros H. unfold cadds.
  replace (N.ltb (chi b) (clo b)) with true
    by (symmetry; apply N.ltb_lt; exact H).
  now rewrite orb_true_r.
Qed.
Lemma cadd_ne (a b : cost) :
  (clo a <= chi a)%N -> (clo b <= chi b)%N ->
  (clo (cadd a b) <= chi (cadd a b))%N.
Proof.
  destruct a as [a1 a2], b as [b1 b2]; unfold cadd, clo, chi; cbn [fst snd].
  lia.
Qed.
Lemma cundef_emp : (chi cundef < clo cundef)%N.
Proof. unfold cundef, clo, chi; cbn [fst snd]; lia. Qed.
Lemma cadds_assoc (a b c : cost) :
  cadds (cadds a b) c = cadds a (cadds b c).
Proof.
  destruct (N.le_gt_cases (clo a) (chi a)) as [Ha|Ha];
    [|rewrite (cadds_emp_l a b Ha), (cadds_emp_l _ c cundef_emp),
             (cadds_emp_l a _ Ha); reflexivity].
  destruct (N.le_gt_cases (clo b) (chi b)) as [Hb|Hb];
    [|rewrite (cadds_emp_r a b Hb), (cadds_emp_l _ c cundef_emp),
             (cadds_emp_l b c Hb), (cadds_emp_r a _ cundef_emp);
      reflexivity].
  destruct (N.le_gt_cases (clo c) (chi c)) as [Hc|Hc];
    [|rewrite (cadds_emp_r _ c Hc), (cadds_emp_r b c Hc),
             (cadds_emp_r a _ cundef_emp); reflexivity].
  rewrite (cadds_exact a b Ha Hb), (cadds_exact b c Hb Hc).
  rewrite (cadds_exact _ c (cadd_ne a b Ha Hb) Hc),
          (cadds_exact a _ Ha (cadd_ne b c Hb Hc)).
  apply cadd_assoc.
Qed.
Lemma cadds_czero_czero : cadds czero czero = czero.
Proof. reflexivity. Qed.
Lemma cadds_czero_l (d D : cost) :
  cadds (cadds czero d) D = cadds d D.
Proof.
  destruct (N.le_gt_cases (clo d) (chi d)) as [Hd|Hd].
  - rewrite (cadds_exact czero d (N.le_refl _) Hd), cadd_0_l.
    reflexivity.
  - rewrite (cadds_emp_r czero d Hd), (cadds_emp_l _ D cundef_emp),
            (cadds_emp_l d D Hd). reflexivity.
Qed.
Fixpoint cbruns_from (k : nat) (s : sstate) (acc : cost)
  : option (sstate * cost) :=
  match k with
  | O => Some (s, cadds acc czero)
  | S k' =>
      match cstep1 s with
      | Some (s', d) => cbruns_from k' s' (cadds acc d)
      | None => None
      end
  end.
Definition cbruns (k : nat) (s : sstate)
  : option (sstate * cost) := cbruns_from k s czero.
Lemma cbruns_from_shift (k : nat) (s : sstate) (acc : cost) :
  cbruns_from k s acc
  = match cbruns k s with
    | Some (s', Dc) => Some (s', cadds acc Dc)
    | None => None
    end.
Proof.
  revert s acc. induction k as [|k IH]; intros s acc.
  - unfold cbruns; cbn [cbruns_from]. now rewrite cadds_czero_czero.
  - cbn [cbruns_from]. unfold cbruns; cbn [cbruns_from].
    destruct (cstep1 s) as [[s' d]|]; [|reflexivity].
    rewrite (IH s' (cadds acc d)), (IH s' (cadds czero d)).
    unfold cbruns.
    destruct (cbruns_from k s' czero) as [[s2 Dc]|]; [|reflexivity].
    now rewrite cadds_czero_l, cadds_assoc.
Qed.
Lemma cbruns_zero (s : sstate) : cbruns 0 s = Some (s, czero).
Proof. unfold cbruns; cbn [cbruns_from]. now rewrite cadds_czero_czero. Qed.
Lemma cbruns_S (k : nat) (s : sstate) :
  cbruns (S k) s
  = match cstep1 s with
    | Some (s', d) =>
        match cbruns k s' with
        | Some (s2, Dc) => Some (s2, cadds d Dc)
        | None => None
        end
    | None => None
    end.
Proof.
  unfold cbruns at 1. cbn [cbruns_from].
  destruct (cstep1 s) as [[s' d]|]; [|reflexivity].
  rewrite (cbruns_from_shift k s' (cadds czero d)).
  destruct (cbruns k s') as [[s2 Dc]|]; [|reflexivity].
  now rewrite cadds_czero_l.
Qed.
Theorem cbruns_proj (k : nat) (s : sstate) :
  option_map fst (cbruns k s) = stepk k s.
Proof.
  revert s. induction k as [|k IH]; intros s.
  - rewrite cbruns_zero. reflexivity.
  - rewrite cbruns_S. cbn [stepk].
    pose proof (cstep1_proj s) as HP.
    destruct (cstep1 s) as [[s' d]|] eqn:E;
      cbn [option_map fst] in HP; rewrite <- HP; [|reflexivity].
    rewrite <- (IH s').
    destruct (cbruns k s') as [[s2 Dc]|]; reflexivity.
Qed.
Corollary cbruns_state (k : nat) (s s' : sstate) (Dc : cost) :
  cbruns k s = Some (s', Dc) -> stepk k s = Some s'.
Proof. intros E. rewrite <- cbruns_proj, E. reflexivity. Qed.
Corollary cbruns_cbrun_state (k : nat) (s s' : sstate)
          (Dc : cost) :
  cbruns k s = Some (s', Dc) -> exists Dp, cbrun k s = Some (s', Dp).
Proof. intros E. exact (cbrun_of_stepk k s s' (cbruns_state k s s' Dc E)). Qed.
Lemma cbruns_canon (k : nat) (s s' : sstate) (D : cost) :
  cbruns k s = Some (s', D) -> cadds czero D = D.
Proof.
  destruct k as [|k].
  - rewrite cbruns_zero. intros HB. injection HB as _ <-.
    exact cadds_czero_czero.
  - rewrite cbruns_S.
    destruct (cstep1 s) as [[s1 d]|]; [|discriminate].
    destruct (cbruns k s1) as [[s2 Dc]|]; [|discriminate].
    intros HB. injection HB as _ <-.
    now rewrite <- cadds_assoc, cadds_czero_l.
Qed.
Lemma cadds_ne_inv (a b : cost) :
  ~ (chi (cadds a b) < clo (cadds a b))%N ->
  (clo a <= chi a)%N /\ (clo b <= chi b)%N /\ cadds a b = cadd a b.
Proof.
  intros H.
  destruct (N.le_gt_cases (clo a) (chi a)) as [Ha|Ha];
    [|exfalso; apply H; rewrite (cadds_emp_l a b Ha); exact cundef_emp].
  destruct (N.le_gt_cases (clo b) (chi b)) as [Hb|Hb];
    [|exfalso; apply H; rewrite (cadds_emp_r a b Hb); exact cundef_emp].
  split; [exact Ha|]. split; [exact Hb|]. exact (cadds_exact a b Ha Hb).
Qed.
Lemma cstep1_inv (w : word) (f : N) (h : nat)
      (s2 : sstate) (d : cost) :
  cstep1 (w, f, h) = Some (s2, d) ->
  exists i, cstep w f h
            = (ROk (fst (fst s2)) (snd (fst s2)), i, d).
Proof.
  unfold cstep1.
  destruct (cstep w f h) as [[r i] dd].
  destruct r as [w2 f2| |]; try discriminate.
  intros HS. injection HS as E1 E2. subst s2 d.
  exists i. cbn [fst snd]. reflexivity.
Qed.
