Definition GenerationGuard : Prop :=
  forall (w : word) (f : N),
    front_blind w = true ->
    first_rule front_rules w f = None.
Ltac kill_front :=
  repeat (cbn;
          match goal with
          | [ |- context [ match ?x with _ => _ end ] ] =>
              is_var x;
              let T := type of x in
              first [ unify T N | unify T positive ];
              destruct x
          end);
  cbn; reflexivity.
Lemma fr_rot_blind (o c : N) (w' : word) (f : N) :
  fr_rot ((o, 2, c) :: w') f = None.
Proof. kill_front. Qed.
