Lemma front_blind_shape (w : word) :
  front_blind w = true ->
  exists o0 c_0 o1 c1 o2 c2 o3 c3 o4 c4 o5 c5 rest,
    w = (o0,2,c_0) :: (o1,2,c1) :: (o2,2,c2)
          :: (o3,2,c3) :: (o4,2,c4) :: (o5,2,c5) :: rest.
Proof.
  unfold front_blind. intros H.
  apply andb_prop in H. destruct H as [Hlen Hcol].
  destruct w as [|[[o0 z0] c_0] [|[[o1 z1] c1] [|[[o2 z2] c2]
                [|[[o3 z3] c3] [|[[o4 z4] c4] [|[[o5 z5] c5] rest]]]]]];
    try discriminate Hlen.
  cbn [firstn forallb MARGIN] in Hcol.
  unfold is_col, gZ, gO in Hcol. cbn in Hcol.
  repeat (apply andb_prop in Hcol; destruct Hcol as [? Hcol]).
  repeat match goal with
         | [ H : (?z =? 2) && _ = true |- _ ] =>
             apply andb_prop in H; destruct H as [H ?];
             apply N.eqb_eq in H; subst z
         end.
  exists o0. exists c_0. exists o1. exists c1. exists o2. exists c2.
  exists o3. exists c3. exists o4. exists c4. exists o5. exists c5.
  exists rest. reflexivity.
Qed.
Theorem GenerationGuard_holds : GenerationGuard.
Proof.
  intros w f Hb.
  apply front_blind_shape in Hb.
  destruct Hb as (o0 & c_0 & o1 & c1 & o2 & c2 & o3 & c3 & o4 & c4
                  & o5 & c5 & rest & Hw).
  subst w.
  unfold first_rule, front_rules. cbn [fold_right].
  rewrite fr_primordial_blind, fr_prim4_blind, fr_clean_blind, fr_four_blind,
          fr_span2A_blind, fr_span2A'_blind, fr_span2C'_blind,
          fr_span8far_blind, fr_span2B_blind, fr_span8orph_blind,
          fr_span8_blind, fr_rot_blind, fr_502_blind, fr_512_blind,
          fr_522_blind.
  reflexivity.
Qed.
Open Scope list.
Lemma step1_sound_impl (SS : StepSound) :
  forall w f h w' f' h',
    step1 (w, f, h) = Some (w', f', h') ->
    sound_impl w f w' f'.
Proof.
  intros w f h w' f' h' H.
  unfold step1 in H.
  destruct (step w f h) as [r i] eqn:ES.
  destruct r as [w2 f2| |]; try discriminate.
  inversion H; subst.
  exact (SS _ _ _ _ _ _ ES).
Qed.
Lemma stepk_sound_impl (SS : StepSound) :
  forall k w f h w' f' h',
    stepk k (w, f, h) = Some (w', f', h') ->
    sound_impl w f w' f'.
Proof.
  induction k as [|k IH]; intros w f h w' f' h' H;
    cbn [stepk] in H.
  - inversion H; subst. unfold sound_impl. exact (fun x => x).
  - destruct (step1 (w, f, h)) as [[[w2 f2] h2]|] eqn:E1;
      [|discriminate].
    unfold sound_impl. intros Hh.
    exact (step1_sound_impl SS _ _ _ _ _ _ E1 (IH _ _ _ _ _ _ H Hh)).
Qed.
Lemma stepN_sound_impl (SS : StepSound) :
  forall n w f h w' f' h',
    stepN n (w, f, h) = Some (w', f', h') ->
    sound_impl w f w' f'.
Proof.
  intros n w f h w' f' h' H.
  unfold stepN in H.
  exact (stepk_sound_impl SS _ _ _ _ _ _ _ H).
Qed.
