Open Scope bool_scope.
Lemma GenerationSound_firstn_pre (pre l : word) : firstn (length pre) (pre ++ l) = pre.
Proof. induction pre as [|a p IH]; simpl; [reflexivity | now rewrite IH]. Qed.
Lemma skipn_pre (pre l : word) : skipn (length pre) (pre ++ l) = l.
Proof. induction pre as [|a p IH]; simpl; [reflexivity | exact IH]. Qed.
Lemma nth_pre (pre : word) (x : bg) (l : word) :
  nth_error (pre ++ x :: l) (length pre) = Some x.
Proof. induction pre as [|a p IH]; simpl; [reflexivity | exact IH]. Qed.
Lemma len_app3 (a b : word) (x : bg) (c : word) :
  length (a ++ b ++ x :: c) = (length a + length b + 1 + length c)%nat.
Proof. repeat rewrite app_length. simpl. lia. Qed.
Definition P28 : list N := map N.of_nat (seq 0 28).
Lemma below28_In (p : N) : p < 28 -> In p P28.
Proof.
  intros H. unfold P28. apply in_map_iff. exists (N.to_nat p). split.
  - apply N2Nat.id.
  - apply in_seq. simpl. lia.
Qed.
Ltac by28 :=
  match goal with
  | [ H : ?p < 28 |- _ ] =>
      apply below28_In in H; unfold P28 in H; simpl in H;
      repeat (destruct H as [H|H];
              [subst p; vm_compute; first [reflexivity | lia | discriminate]|]);
      destruct H
  end.
Lemma phase_form_len (p : N) : p < 28 -> length (phase_form p) = phase_len p.
Proof. intros H. by28. Qed.
Lemma DBu_le3 (p : N) : p < 28 -> DBu p <= 3.
Proof. intros H. by28. Qed.
Lemma marks_is_EMt (q : N) : q < 28 -> marks q = EMt q.
Proof.
  intros H. unfold marks.
  rewrite (N.div_small q 28) by lia. rewrite (N.mod_small q 28) by lia.
  reflexivity.
Qed.
Lemma EMt_mono (a b : N) : a <= b -> EMt a <= EMt b.
Proof.
  intros H. unfold EMt.
  destruct (a <? 4) eqn:Ea; [lia|].
  apply N.ltb_ge in Ea.
  destruct (b <? 4) eqn:Eb; [apply N.ltb_lt in Eb; lia|].
  apply N.add_le_mono_r. apply N.div_le_mono; [lia | lia].
Qed.
Lemma marks_mono (a b : N) : a <= b -> b < 28 -> marks a <= marks b.
Proof.
  intros H1 H2. rewrite marks_is_EMt by lia. rewrite marks_is_EMt by lia.
  now apply EMt_mono.
Qed.
Definition site (pre : word) (p c : N) (post : word) : word :=
  pre ++ phase_form p ++ (4, 2, c) :: post.
Lemma lvl_big_intro (c : N) : FLOOR <= c -> lvl_big (4,2,c) = true.
Proof.
  intros H. unfold lvl_big, gO, gZ, gC.
  apply andb_true_intro; split; [reflexivity | now apply N.leb_le].
Qed.
Lemma skipn_pre2 (a b r : word) :
  skipn (length a + length b) (a ++ b ++ r) = r.
Proof.
  induction a as [|x a IH]; cbn [length app skipn Nat.add];
    [apply skipn_pre | exact IH].
Qed.
Lemma subst2 (a b r rep : word) :
  subst_at (length a) (length b) rep (a ++ b ++ r) = a ++ rep ++ r.
Proof.
  unfold subst_at. rewrite GenerationSound_firstn_pre. f_equal. f_equal. apply skipn_pre2.
Qed.
Lemma subst1 (a r rep : word) (x : bg) :
  subst_at (length a) 1 rep (a ++ x :: r) = a ++ rep ++ r.
Proof. exact (subst2 a [x] r rep). Qed.
Lemma subst_site (pre pair post rep : word) (c c' : N) :
  subst_at (length pre) (length pair) rep
    (subst_at (length pre + length pair) 1 [(4,2,c')]
              (pre ++ pair ++ (4,2,c) :: post))
  = pre ++ rep ++ (4,2,c') :: post.
Proof.
  assert (HL : (length pre + length pair)%nat = length (pre ++ pair))
    by (rewrite app_length; reflexivity).
  rewrite HL, (app_assoc pre pair ((4,2,c) :: post)), subst1, <- app_assoc.
  apply subst2.
Qed.
Ltac lenlia := try unfold bg in *; try unfold word in *; lia.
Lemma forallb_skipn (P : bg -> bool) (l : word) (k : nat) :
  forallb P l = true -> forallb P (skipn k l) = true.
Proof.
  revert k. induction l as [|a t IH]; intros k H.
  - now rewrite skipn_nil.
  - destruct k as [|k']; [exact H|].
    cbn [skipn]. cbn [forallb] in H. apply andb_prop in H. now apply IH.
Qed.
Lemma forallb_firstn (P : bg -> bool) (l : word) (k : nat) :
  forallb P l = true -> forallb P (firstn k l) = true.
Proof.
  revert k. induction l as [|a t IH]; intros k H.
  - now rewrite firstn_nil.
  - destruct k as [|k']; [reflexivity|].
    cbn [firstn forallb] in *. apply andb_prop in H. destruct H as [H1 H2].
    rewrite H1. now apply IH.
Qed.
Lemma firstn_app_le (k : nat) (a b : word) :
  (k <= length a)%nat -> firstn k (a ++ b) = firstn k a.
Proof.
  revert k. induction a as [|g a IH]; intros k Hk.
  - cbn [length] in Hk. replace k with 0%nat by lia. reflexivity.
  - destruct k as [|k']; [reflexivity|].
    cbn [app firstn length] in *. f_equal. apply IH. lia.
Qed.
Lemma find_active_s_shift (l : word) (a i : nat) :
  find_active_s l (a + i) = option_map (Nat.add a) (find_active_s l i).
Proof.
  revert i. induction l as [|g t IH]; intros i; cbn [find_active_s].
  - reflexivity.
  - destruct ((gZ g =? 1) || (3 <=? gZ g)); [reflexivity|].
    replace (S (a + i))%nat with (a + S i)%nat by lia. apply IH.
Qed.
Lemma find_active_s_col_pre (pre l : word) (i : nat) :
  forallb is_col pre = true ->
  find_active_s (pre ++ l) i
  = option_map (Nat.add (length pre)) (find_active_s l i).
Proof.
  revert i. induction pre as [|g p IH]; intros i H.
  - cbn [length app]. destruct (find_active_s l i); reflexivity.
  - cbn [forallb] in H. apply andb_prop in H. destruct H as [Hg Hp].
    unfold is_col in Hg. apply andb_prop in Hg. destruct Hg as [Hz _].
    apply N.eqb_eq in Hz.
    cbn [app length find_active_s]. rewrite Hz. cbn.
    rewrite (IH (S i) Hp).
    replace (S i) with (1 + i)%nat by lia.
    rewrite (find_active_s_shift l 1 i).
    destruct (find_active_s l i); cbn [option_map];
      [f_equal; lia | reflexivity].
Qed.
Theorem find_active_app_col (pre rest : word) (k : nat) :
  forallb is_col pre = true ->
  find_active (pre ++ rest) k
  = option_map (Nat.add (length pre)) (find_active rest (k - length pre)).
Proof.
  intros Hc. unfold find_active.
  assert (HD : (k <= length pre)%nat \/ (length pre < k)%nat) by lia.
  destruct HD as [Hle|Hgt].
  - rewrite skipn_app.
    replace (k - length pre)%nat with 0%nat by lia.
    cbn [skipn].
    rewrite (find_active_s_col_pre (skipn k pre) rest k (forallb_skipn _ _ _ Hc)).
    rewrite skipn_length.
    assert (Hk0 : find_active_s rest k
                  = option_map (Nat.add k) (find_active_s rest 0)).
    { rewrite <- (find_active_s_shift rest k 0). f_equal. lia. }
    rewrite Hk0.
    destruct (find_active_s rest 0); cbn [option_map];
      [f_equal; lia | reflexivity].
  - rewrite skipn_app.
    replace (skipn k pre) with (@nil bg)
      by (symmetry; apply skipn_all2; lia).
    cbn [app].
    rewrite <- (find_active_s_shift (skipn (k - length pre) rest) (length pre)
                                    (k - length pre)).
    f_equal. lia.
Qed.
Corollary find_active_at_site (pre rest : word) (g : bg) (k : nat) :
  forallb is_col pre = true ->
  (k <= length pre)%nat ->
  ((gZ g =? 1) || (3 <=? gZ g)) = true ->
  find_active (pre ++ g :: rest) k = Some (length pre).
Proof.
  intros Hc Hk Hg.
  rewrite (find_active_app_col pre (g :: rest) k Hc).
  replace (k - length pre)%nat with 0%nat by lia.
  unfold find_active. cbn [skipn find_active_s].
  rewrite Hg. cbn [option_map]. f_equal. lia.
Qed.
Corollary find_active_at_site_c (g0 g : bg) (pre' rest : word)
                                (k : nat) :
  forallb is_col (g0 :: pre') = true ->
  (k <= S (length pre'))%nat ->
  ((gZ g =? 1) || (3 <=? gZ g)) = true ->
  find_active (g0 :: (pre' ++ g :: rest)) k = Some (S (length pre')).
Proof.
  intros H1 H2 H3. exact (find_active_at_site (g0::pre') rest g k H1 H2 H3).
Qed.
Definition last_ok (pre : word) : bool :=
  match last1 pre with
  | Some g => (3 <=? gO g) && (1 <=? gC g)
  | None => false
  end.
Lemma step_site_z1 (pre pre' tl : word) (g : bg)
                   (c_0 f : N) (h : nat) :
  pre = (2,2,c_0) :: pre' ->
  1 <= c_0 ->
  (6 <= length pre)%nat ->
  (h <= length pre)%nat ->
  forallb is_col pre = true ->
  last_ok pre = true ->
  gZ g = 1 ->
  step (pre ++ g :: tl) f h
  = match leaf_act (g :: tl) f with
    | Some (s', f2) =>
        (ROk (normalize (((2,2,c_0+1) :: pre') ++ s')) f2, length pre)
    | None => (RBad, O)
    end.
Proof.
  intros Hpre Hc0 Hlen Hh Hcol Hlast Hz.
  assert (Hfb : front_blind (pre ++ g :: tl) = true).
  { unfold front_blind, MARGIN.
    apply andb_true_intro. split.
    - apply PeanoNat.Nat.leb_le. rewrite app_length. lenlia.
    - rewrite (firstn_app_le 6 pre (g :: tl)) by lia.
      exact (forallb_firstn _ _ 6 Hcol). }
  subst pre.
  cbn [length] in Hlen, Hh |- *.
  assert (Hi : ((if Nat.ltb h 1 then 1%nat else h) <= S (length pre'))%nat)
    by (destruct (Nat.ltb h 1); lia).
  assert (Hc1 : (1 <=? c_0) = true) by (apply N.leb_le; lia).
  unfold step.
  unfold step_after_front, step_after_front_with,
         step_after_front_with_guard.
  rewrite (GenerationGuard_holds _ f Hfb).
  cbn [app].
  try unfold word in *. try unfold bg in *.
  destruct g as [[o z] c1]. cbn [gZ] in Hz. subst z.
  assert (HFA : find_active ((2,2,c_0) :: pre' ++ (o,1,c1) :: tl)
                  (if Nat.ltb h 1 then 1%nat else h) = Some (S (length pre'))).
  { apply (find_active_at_site_c (2,2,c_0) (o,1,c1) pre' tl _);
      [exact Hcol | exact Hi | reflexivity]. }
  rewrite HFA. cbv beta iota.
  cbn [gO gZ gC].
  assert (HF : forall d : N,
            firstn (S (length pre')) ((2,2,d) :: pre' ++ (o,1,c1) :: tl)
            = (2,2,d) :: pre').
  { intros d. cbn [firstn]. f_equal. apply GenerationSound_firstn_pre. }
  assert (HS : forall d : N,
            skipn (S (length pre')) ((2,2,d) :: pre' ++ (o,1,c1) :: tl)
            = (o,1,c1) :: tl).
  { intros d. cbn [skipn]. apply skipn_pre. }
  assert (HW : wat ((2,2,c_0+1) :: pre' ++ (o,1,c1) :: tl)
                 (S (length pre')) = Some (o,1,c1)).
  { unfold wat. cbn [nth_error]. apply nth_pre. }
  rewrite !HF, !HS, Hc1, Hcol.
  unfold last_ok in Hlast. revert Hlast.
  destruct (last1 ((2,2,c_0) :: pre')) as [g1|] eqn:EL;
    cbv beta iota; intros Hlast; [|discriminate Hlast].
  rewrite Hlast.
  assert (Hx : ((o =? 4) && (1 =? 3) && (c1 =? 1)
                && Nat.leb 3 (S (length pre'))) = false)
    by (destruct (o =? 4); reflexivity).
  rewrite Hx. cbv beta iota.
  assert (Hy : ((1 =? 3) && (c1 =? 1)) = false) by reflexivity.
  rewrite Hy. cbv beta iota.
  assert (Hz1 : (1 =? 1) = true) by reflexivity.
  rewrite Hz1. cbv beta iota.
  destruct (leaf_act ((o,1,c1) :: tl) f) as [[s2 f2]|] eqn:ELA;
    cbv beta iota.
  - reflexivity.
  - rewrite HW. cbv beta iota. reflexivity.
Qed.
Lemma step_site_z3 (pre pre' tl s' : word) (g : bg)
                   (c_0 f f2 : N) (h : nat) :
  pre = (2,2,c_0) :: pre' ->
  1 <= c_0 ->
  (6 <= length pre)%nat ->
  (h <= length pre)%nat ->
  forallb is_col pre = true ->
  last_ok pre = true ->
  gZ g = 3 -> gC g = 1 -> (gO g =? 4) = false ->
  fire_comp (length (g :: tl)) (g :: tl) f = Some (s', f2) ->
  step (pre ++ g :: tl) f h
  = (ROk (normalize (((2,2,c_0+1) :: pre') ++ s')) f2, length pre).
Proof.
  intros Hpre Hc0 Hlen Hh Hcol Hlast Hz Hc Ho HFC.
  assert (Hfb : front_blind (pre ++ g :: tl) = true).
  { unfold front_blind, MARGIN.
    apply andb_true_intro. split.
    - apply PeanoNat.Nat.leb_le. rewrite app_length. lenlia.
    - rewrite (firstn_app_le 6 pre (g :: tl)) by lia.
      exact (forallb_firstn _ _ 6 Hcol). }
  subst pre.
  cbn [length] in Hlen, Hh |- *.
  assert (Hi : ((if Nat.ltb h 1 then 1%nat else h) <= S (length pre'))%nat)
    by (destruct (Nat.ltb h 1); lia).
  assert (Hc1 : (1 <=? c_0) = true) by (apply N.leb_le; lia).
  unfold step.
  unfold step_after_front, step_after_front_with,
         step_after_front_with_guard.
  rewrite (GenerationGuard_holds _ f Hfb).
  cbn [app].
  try unfold word in *. try unfold bg in *.
  destruct g as [[o z] c1].
  cbn [gZ gC gO] in Hz, Hc, Ho. subst z. subst c1.
  assert (HFA : find_active ((2,2,c_0) :: pre' ++ (o,3,1) :: tl)
                  (if Nat.ltb h 1 then 1%nat else h) = Some (S (length pre'))).
  { apply (find_active_at_site_c (2,2,c_0) (o,3,1) pre' tl _);
      [exact Hcol | exact Hi | reflexivity]. }
  rewrite HFA. cbv beta iota.
  cbn [gO gZ gC].
  assert (HF : forall d : N,
            firstn (S (length pre')) ((2,2,d) :: pre' ++ (o,3,1) :: tl)
            = (2,2,d) :: pre').
  { intros d. cbn [firstn]. f_equal. apply GenerationSound_firstn_pre. }
  assert (HS : forall d : N,
            skipn (S (length pre')) ((2,2,d) :: pre' ++ (o,3,1) :: tl)
            = (o,3,1) :: tl).
  { intros d. cbn [skipn]. apply skipn_pre. }
  rewrite !HF, !HS, Hc1, Hcol.
  unfold last_ok in Hlast. revert Hlast.
  destruct (last1 ((2,2,c_0) :: pre')) as [g1|] eqn:EL;
    cbv beta iota; intros Hlast; [|discriminate Hlast].
  rewrite Hlast.
  assert (Hx : ((o =? 4) && (3 =? 3) && (1 =? 1)
                && Nat.leb 3 (S (length pre'))) = false)
    by (rewrite Ho; reflexivity).
  rewrite Hx. cbv beta iota.
  assert (Hy : ((3 =? 3) && (1 =? 1)) = true) by reflexivity.
  rewrite Hy. cbv beta iota.
  rewrite HFC. cbv beta iota. reflexivity.
Qed.
Definition emits (p : N) : bool :=
  (p =? 3) || (p =? 11) || (p =? 19) || (p =? 27).
Example emits_is_the_marks_jump (p : N) :
  p < 28 -> emits p = negb (marks (p+1) =? marks p).
Proof. intros H. by28. Qed.
Lemma leaf_phase_head (p : N) :
  p < 28 -> emits p = false ->
  exists (x : N) (tl0 : word), phase_form p = (x,1,1) :: tl0.
Proof.
  intros Hp Hem.
  apply below28_In in Hp; unfold P28 in Hp; simpl in Hp.
  repeat (destruct Hp as [Hp|Hp];
          [subst p;
           first [ discriminate Hem
                 | vm_compute (phase_form _);
                   eexists; eexists; reflexivity ]|]).
  destruct Hp.
Qed.
Transparent leaf_act.
Ltac normgen :=
  repeat (match goal with
          | |- context [phase_form ?k] =>
              let v := eval vm_compute in (phase_form k) in
              change (phase_form k) with v
          | |- context [DBu ?k] =>
              let v := eval vm_compute in (DBu k) in
              change (DBu k) with v
          end).
Theorem leaf_tick (p c : N) (post : word) (f : N) :
  p < 28 -> emits p = false -> 2 <= c ->
  leaf_act (phase_form p ++ (4,2,c) :: post) f
  = Some (phase_form (p+1)
            ++ (4,2, (c + DBu (p+1)) - DBu p) :: post, f).
Proof.
  intros Hp Hem Hc.
  assert (Hc1 : (c =? 1) = false) by (apply N.eqb_neq; lia).
  assert (Hc2 : (2 <=? c) = true) by (apply N.leb_le; lia).
  assert (E0 : c + 3 - 3 = c) by lia.
  assert (E1 : c + 2 - 2 = c) by lia.
  assert (E2 : c + 1 - 1 = c) by lia.
  assert (E3 : c + 0 - 0 = c) by lia.
  assert (E4 : c + 3 - 2 = c + 1) by lia.
  assert (E5 : c + 2 - 1 = c + 1) by lia.
  assert (E6 : c + 1 - 0 = c + 1) by lia.
  assert (E7 : c + 2 - 3 = c - 1) by lia.
  assert (E8 : c + 1 - 2 = c - 1) by lia.
  assert (E9 : c + 0 - 1 = c - 1) by lia.
  apply below28_In in Hp; unfold P28 in Hp; simpl in Hp.
  repeat (destruct Hp as [Hp|Hp]; [subst p|]).
  all: try (exfalso; exact Hp).
  all: try discriminate Hem.
  all: normgen; cbn [app leaf_act]; rewrite ?Hc1, ?Hc2; cbn.
  all: rewrite ?E0, ?E1, ?E2, ?E3, ?E4, ?E5, ?E6, ?E7, ?E8, ?E9.
  all: reflexivity.
Qed.
Opaque leaf_act.
Definition bump (pre : word) : word :=
  match pre with (o,z,c) :: t => (2,2,c+1) :: t | [] => [] end.
Opaque jump_comp.
Lemma step_site_jump_closed
      (pre pre' post body : word) (c_0 B f f' : N) (h : nat) :
  pre = (2,2,c_0) :: pre' ->
  1 <= c_0 ->
  (6 <= length pre)%nat ->
  (h <= length pre)%nat ->
  forallb is_col pre = true ->
  last_ok pre = true ->
  1 <= B ->
  jump_comp (bump pre) B post f
    = Some (JMP, body, f') ->
  step (pre ++ phase_form 27 ++ (4,2,B) :: post) f h
    = (ROk (normalize body) f', length pre).
Proof.
  intros Hpre Hc0 Hlen Hh Hcol Hlast HB HJC.
  assert (Hfb : front_blind
      (pre ++ phase_form 27 ++ (4,2,B) :: post) = true).
  { unfold front_blind, MARGIN.
    apply andb_true_intro. split.
    - apply PeanoNat.Nat.leb_le. repeat rewrite length_app. cbn. lia.
    - rewrite (firstn_app_le 6 pre
                 (phase_form 27 ++ (4,2,B) :: post)) by lia.
      exact (forallb_firstn _ _ 6 Hcol). }
  subst pre.
  cbn [length] in Hlen, Hh |- *.
  cbn [bump] in HJC.
  assert (Hi : ((if Nat.ltb h 1 then 1%nat else h) <= S (length pre'))%nat)
    by (destruct (Nat.ltb h 1); lia).
  assert (Hc1 : (1 <=? c_0) = true) by (apply N.leb_le; lia).
  change (phase_form 27) with [(4,3,1)].
  change (phase_form 27) with [(4,3,1)] in Hfb.
  unfold step.
  unfold step_after_front, step_after_front_with,
         step_after_front_with_guard.
  rewrite (GenerationGuard_holds _ f Hfb).
  cbn [app].
  try unfold word in *. try unfold bg in *.
  assert (HFA : find_active
      ((2,2,c_0) :: pre' ++ (4,3,1) :: (4,2,B) :: post)
      (if Nat.ltb h 1 then 1%nat else h) = Some (S (length pre'))).
  { apply (find_active_at_site_c
             (2,2,c_0) (4,3,1) pre' ((4,2,B)::post) _);
      [exact Hcol | exact Hi | reflexivity]. }
  rewrite HFA. cbv beta iota.
  cbn [gO gZ gC].
  assert (HF : forall d : N,
      firstn (S (length pre'))
        ((2,2,d) :: pre' ++ (4,3,1) :: (4,2,B) :: post)
      = (2,2,d) :: pre').
  { intros d. cbn [firstn]. f_equal. apply GenerationSound_firstn_pre. }
  assert (HS : forall d : N,
      skipn (S (length pre'))
        ((2,2,d) :: pre' ++ (4,3,1) :: (4,2,B) :: post)
      = (4,3,1) :: (4,2,B) :: post).
  { intros d. cbn [skipn]. apply skipn_pre. }
  rewrite !HF, !HS, Hc1, Hcol.
  unfold last_ok in Hlast. revert Hlast.
  destruct (last1 ((2,2,c_0) :: pre')) as [g1|] eqn:EL;
    cbv beta iota; intros Hlast; [|discriminate Hlast].
  rewrite Hlast.
  assert (Hjump :
      ((4 =? 4) && (3 =? 3) && (1 =? 1)
        && Nat.leb 3 (S (length pre'))) = true).
  { apply andb_true_intro. split; [reflexivity|].
    apply PeanoNat.Nat.leb_le. lia. }
  rewrite Hjump. cbv beta iota.
  assert (H42 : ((4 =? 4) && (2 =? 2)) = true) by reflexivity.
  rewrite H42. cbv beta iota.
  assert (HBb : (1 <=? B) = true) by (apply N.leb_le; lia).
  rewrite HBb. cbv beta iota.
  cbn [negb andb Nat.eqb N.eqb].
  repeat rewrite Pos.eqb_refl.
  cbn [negb andb].
  rewrite HJC. cbv beta iota. reflexivity.
Qed.
Transparent jump_comp.
Theorem tick_law_leaf_raw
      (pre pre' post : word) (c_0 p c f : N) (h : nat) :
  pre = (2,2,c_0) :: pre' ->
  1 <= c_0 ->
  (6 <= length pre)%nat ->
  (h <= length pre)%nat ->
  forallb is_col pre = true ->
  last_ok pre = true ->
  p < 28 -> emits p = false -> 2 <= c ->
  step (pre ++ phase_form p ++ (4,2,c) :: post) f h
  = (ROk (normalize
       (bump pre ++ phase_form (p+1)
          ++ (4,2,(c + DBu (p+1)) - DBu p) :: post)) f,
     length pre).
Proof.
  intros Hpre Hc0 Hlen Hh Hcol Hlast Hp Hem Hc.
  destruct (leaf_phase_head p Hp Hem) as (x & tl0 & Hph).
  pose proof (leaf_tick p c post f Hp Hem Hc) as HLA.
  rewrite Hph in HLA. cbn [app] in HLA.
  rewrite Hph. cbn [app].
  rewrite (step_site_z1 pre pre'
             (tl0 ++ (4,2,c) :: post) (x,1,1) c_0 f h
             Hpre Hc0 Hlen Hh Hcol Hlast ltac:(reflexivity)).
  rewrite HLA.
  subst pre. reflexivity.
Qed.
Lemma emits_nonjump (p : N) :
  p < 28 -> emits p = true -> p <> 27 ->
  p = 3 \/ p = 11 \/ p = 19.
Proof. intros Hp Hem H27. by28. Qed.
Theorem tick_law_fire_raw
      (pre pre' post out : word) (c_0 p c f f' : N) (h : nat) :
  pre = (2,2,c_0) :: pre' ->
  1 <= c_0 ->
  (6 <= length pre)%nat ->
  (h <= length pre)%nat ->
  forallb is_col pre = true ->
  last_ok pre = true ->
  p < 28 -> emits p = true -> p <> 27 ->
  fire_comp
    (length (phase_form p ++ (4,2,c) :: post))
    (phase_form p ++ (4,2,c) :: post) f = Some (out, f') ->
  step (pre ++ phase_form p ++ (4,2,c) :: post) f h
  = (ROk (normalize (bump pre ++ out)) f',
     length pre).
Proof.
  intros Hpre Hc0 Hlen Hh Hcol Hlast Hp Hem H27 HFC.
  destruct (emits_nonjump p Hp Hem H27) as [E|[E|E]]; subst p.
  - change (phase_form 3) with [(7,3,1)] in HFC |- *.
    subst pre.
    exact (step_site_z3 ((2,2,c_0)::pre') pre'
             ((4,2,c)::post) out (7,3,1) c_0 f f' h
             ltac:(reflexivity) Hc0 Hlen Hh Hcol Hlast
             ltac:(reflexivity) ltac:(reflexivity) ltac:(reflexivity) HFC).
  - change (phase_form 11) with [(6,3,1)] in HFC |- *.
    subst pre.
    exact (step_site_z3 ((2,2,c_0)::pre') pre'
             ((4,2,c)::post) out (6,3,1) c_0 f f' h
             ltac:(reflexivity) Hc0 Hlen Hh Hcol Hlast
             ltac:(reflexivity) ltac:(reflexivity) ltac:(reflexivity) HFC).
  - change (phase_form 19) with [(5,3,1)] in HFC |- *.
    subst pre.
    exact (step_site_z3 ((2,2,c_0)::pre') pre'
             ((4,2,c)::post) out (5,3,1) c_0 f f' h
             ltac:(reflexivity) Hc0 Hlen Hh Hcol Hlast
             ltac:(reflexivity) ltac:(reflexivity) ltac:(reflexivity) HFC).
Qed.
Lemma bg_eqb_true (a b : bg) :
  bg_eqb a b = true -> a = b.
Proof.
  destruct a as [[ao az] ac], b as [[bo bz] bc].
  unfold bg_eqb, gO, gZ, gC.
  cbn. intros H.
  repeat (apply andb_prop in H; destruct H as [H ?]).
  apply N.eqb_eq in H. subst bo.
  match goal with H : (az =? bz) = true |- _ =>
    apply N.eqb_eq in H; subst bz
  end.
  match goal with H : (ac =? bc) = true |- _ =>
    apply N.eqb_eq in H; subst bc
  end.
  reflexivity.
Qed.
Lemma word_eqb_true (a b : word) :
  word_eqb a b = true -> a = b.
Proof.
  revert b. induction a as [|x a IH]; intros [|y b] H; try discriminate.
  - reflexivity.
  - cbn [word_eqb] in H.
    apply andb_prop in H. destruct H as [Hxy Hab].
    apply bg_eqb_true in Hxy. apply IH in Hab. subst. reflexivity.
Qed.
Definition next_hint (j : nat) : nat :=
  if Nat.ltb j 5 then O else (j - 4)%nat.
Definition closed_tick (st : sstate) : option sstate :=
  let '(w, f, h) := st in
  let start := if Nat.ltb h 1 then 1%nat else h in
  match find_active w start with
  | None => None
  | Some j =>
      let pre := firstn j w in
      let suf := skipn j w in
      match pre with
      | (o0,z0,c_0) :: pre' =>
          if (o0 =? 2) && (z0 =? 2) && (1 <=? c_0) then
          if Nat.leb 6 (length pre) then
          if Nat.leb h (length pre) then
          if forallb is_col pre then
          if last_ok pre then
          match detect_phase w j with
          | None => None
          | Some p =>
              if p <? 28 then
              let ph := phase_form p in
              let k := length ph in
              if word_eqb (firstn k suf) ph then
              match skipn k suf with
              | (o,z,c) :: post =>
                  if (o =? 4) && (z =? 2) then
                  if emits p then
                    if p =? 27 then
                      if 1 <=? c then
                        match jump_comp (bump pre) c post f with
                        | Some (JMP, body, f') =>
                            Some (normalize body, f', next_hint (length pre))
                        | _ => None
                        end
                      else None
                    else
                      match fire_comp (length suf) suf f with
                      | Some (body, f') =>
                          Some (normalize (bump pre ++ body),
                                f', next_hint (length pre))
                      | None => None
                      end
                  else if 2 <=? c then
                    Some
                      (normalize
                         (bump pre
                          ++ phase_form (p+1)
                          ++ (4,2,(c + DBu (p+1))
                                     - DBu p) :: post),
                       f, next_hint (length pre))
                  else None
                  else None
              | [] => None
              end
              else None
              else None
          end
          else None
          else None
          else None
          else None
          else None
      | _ => None
      end
  end.
Lemma if_some_inv {A : Type} (b : bool) (x : option A) (y : A) :
  (if b then x else None) = Some y -> b = true /\ x = Some y.
Proof. destruct b; cbn; intros H; [split; [reflexivity|exact H]|discriminate]. Qed.
Lemma if_result_inv {A : Type} (b : bool) (x y z : A) :
  (if b then x else y) = z ->
  (b = true /\ x = z) \/ (b = false /\ y = z).
Proof.
  destruct b; cbn; intros H.
  - left. split; [reflexivity|exact H].
  - right. split; [reflexivity|exact H].
Qed.
Lemma option_some_inv {A B : Type}
      (o : option A) (k : A -> option B) (y : B) :
  (match o with Some x => k x | None => None end) = Some y ->
  exists x, o = Some x /\ k x = Some y.
Proof.
  destruct o as [x|]; cbn; intros H; [exists x; auto|discriminate].
Qed.
Lemma list_some_inv {A B : Type}
      (l : list A) (k : A -> list A -> option B) (y : B) :
  (match l with [] => None | x :: xs => k x xs end) = Some y ->
  exists x xs, l = x :: xs /\ k x xs = Some y.
Proof.
  destruct l as [|x xs]; cbn; intros H; [discriminate|].
  exists x, xs. auto.
Qed.
Lemma jump_some_inv {A : Type}
      (o : option (ckind * word * N))
      (k : word -> N -> option A) (y : A) :
  (match o with
   | Some (JMP, body, f') => k body f'
   | _ => None
   end) = Some y ->
  exists body f', o = Some (JMP, body, f') /\ k body f' = Some y.
Proof.
  destruct o as [[[kind body] f']|]; cbn; [destruct kind|];
    intros H; try discriminate.
  exists body, f'. auto.
Qed.
Lemma closed_tick_front_blind
      (w w' : word) (f f' : N) (h h' : nat) :
  closed_tick (w, f, h) = Some (w', f', h') ->
  front_blind w = true.
Proof.
  intros H. cbn [closed_tick] in H.
  destruct (find_active w (if Nat.ltb h 1 then 1%nat else h))
    as [j|] eqn:EFA; [|discriminate].
  cbv beta zeta iota in H.
  apply list_some_inv in H. destruct H as (g0 & pre' & Epre & H).
  destruct g0 as [[o0 z0] c_0]. cbv beta zeta iota in H.
  apply if_some_inv in H. destruct H as [Ehead H].
  apply if_some_inv in H. destruct H as [Elen H].
  apply if_some_inv in H. destruct H as [Eh H].
  apply if_some_inv in H. destruct H as [Ecol H].
  rewrite Epre in Elen, Ecol.
  unfold front_blind.
  apply andb_true_intro. split.
  - apply PeanoNat.Nat.leb_le. unfold MARGIN.
    apply PeanoNat.Nat.leb_le in Elen.
    rewrite <- (firstn_skipn j w), Epre, app_length. cbn [length].
    eapply PeanoNat.Nat.le_trans; [exact Elen|].
    apply PeanoNat.Nat.le_add_r.
  - rewrite <- (firstn_skipn j w), Epre.
    rewrite firstn_app_le.
    + exact (forallb_firstn _ _ MARGIN Ecol).
    + apply PeanoNat.Nat.leb_le in Elen.
      unfold MARGIN in *. cbn [length] in *. exact Elen.
Qed.
Lemma closed_tick_front_none
      (w w' : word) (f f' : N) (h h' : nat) :
  closed_tick (w, f, h) = Some (w', f', h') ->
  fr_clean w f = None /\ fr_four w f = None.
Proof.
  intros H. pose proof (closed_tick_front_blind _ _ _ _ _ _ H) as HB.
  apply front_blind_shape in HB.
  destruct HB as (o0 & c_0 & o1 & c1 & o2 & c2 & o3 & c3 & o4 & c4
                  & o5 & c5 & rest & ->).
  split; [apply fr_clean_blind|apply fr_four_blind].
Qed.
Opaque step.
Lemma step1_of_step
      (w w2 : word) (f f2 : N) (h i : nat) :
  step w f h = (ROk w2 f2, i) ->
  step1 (w, f, h) = Some (w2, f2, next_hint i).
Proof.
  intros E. unfold step1, next_hint. rewrite E. reflexivity.
Qed.
Theorem closed_tick_sound :
  forall w f h w' f' h',
    closed_tick (w, f, h) = Some (w', f', h') ->
    step1 (w, f, h) = Some (w', f', h').
Proof.
  intros w f h w' f' h' H.
  cbn [closed_tick] in H.
  destruct (find_active w (if Nat.ltb h 1 then 1%nat else h))
    as [j|] eqn:EFA; [|discriminate].
  cbv beta zeta iota in H.
  apply list_some_inv in H. destruct H as (g0 & pre' & Epre & H).
  destruct g0 as [[o0 z0] c_0]. cbv beta iota in H.
  apply if_some_inv in H. destruct H as [Ehead H].
  apply andb_prop in Ehead. destruct Ehead as [Ehead Ec0].
  apply andb_prop in Ehead. destruct Ehead as [Eo0 Ez0].
  apply N.eqb_eq in Eo0. apply N.eqb_eq in Ez0.
  apply N.leb_le in Ec0. subst o0 z0.
  apply if_some_inv in H. destruct H as [Elen H].
  apply PeanoNat.Nat.leb_le in Elen.
  apply if_some_inv in H. destruct H as [Eh H].
  apply PeanoNat.Nat.leb_le in Eh.
  apply if_some_inv in H. destruct H as [Ecol H].
  apply if_some_inv in H. destruct H as [Elast H].
  apply option_some_inv in H. destruct H as (p & Ephase & H).
  apply if_some_inv in H. destruct H as [Ep H].
  apply N.ltb_lt in Ep.
  apply if_some_inv in H. destruct H as [Eprefix H].
  apply word_eqb_true in Eprefix.
  apply list_some_inv in H. destruct H as (g & post & Erest & H).
  destruct g as [[o z] c]. cbv beta iota in H.
  apply if_some_inv in H. destruct H as [Elevel H].
  apply andb_prop in Elevel. destruct Elevel as [Eo Ez].
  apply N.eqb_eq in Eo. apply N.eqb_eq in Ez. subst o z.
  rewrite Epre in Elen, Eh, Ecol, Elast, H.
  assert (Hsuf :
      skipn j w = phase_form p ++ (4,2,c) :: post).
  { symmetry.
    rewrite <- (firstn_skipn (length (phase_form p)) (skipn j w)).
    rewrite Eprefix, Erest. reflexivity. }
  assert (Hw :
      w = ((2,2,c_0)::pre') ++ phase_form p ++ (4,2,c) :: post).
  { rewrite <- (firstn_skipn j w).
    rewrite Epre.
    rewrite Hsuf. reflexivity. }
  apply if_result_inv in H. destruct H as [[Eemit H]|[Eemit H]].
  - apply if_result_inv in H. destruct H as [[Ep27 H]|[Ep27 H]].
    + apply N.eqb_eq in Ep27. subst p.
      apply if_some_inv in H. destruct H as [Ec H].
      apply N.leb_le in Ec.
      apply jump_some_inv in H. destruct H as (body & ff & EJC & H).
      inversion H; subst w' f' h'.
      rewrite Hw. apply step1_of_step.
      exact (step_site_jump_closed ((2,2,c_0)::pre') pre' post body
               c_0 c f ff h ltac:(reflexivity) Ec0 Elen Eh Ecol Elast Ec EJC).
    + apply N.eqb_neq in Ep27.
      apply option_some_inv in H. destruct H as (bf & EFC & H).
      destruct bf as [body ff]. cbv beta iota in H.
      inversion H; subst w' f' h'.
      rewrite Hsuf in EFC.
      rewrite Hw. apply step1_of_step.
      exact (tick_law_fire_raw ((2,2,c_0)::pre') pre' post body
               c_0 p c f ff h ltac:(reflexivity) Ec0 Elen Eh Ecol Elast
               Ep Eemit Ep27 EFC).
  - apply if_some_inv in H. destruct H as [Ec H].
    apply N.leb_le in Ec.
    inversion H; subst w' f' h'.
    rewrite Hw. apply step1_of_step.
    exact (tick_law_leaf_raw ((2,2,c_0)::pre') pre' post
             c_0 p c f h ltac:(reflexivity) Ec0 Elen Eh Ecol Elast
             Ep Eemit Ec).
Qed.
Transparent step.
Fixpoint closed_tickk (k : nat) (st : sstate)
  : option sstate :=
  match k with
  | O => Some st
  | S k' =>
      match closed_tick st with
      | Some st' => closed_tickk k' st'
      | None => None
      end
  end.
Theorem closed_tickk_sound :
  forall k st st',
    closed_tickk k st = Some st' ->
    stepk k st = Some st'.
Proof.
  induction k as [|k IH]; intros st st' H;
    cbn [closed_tickk stepk] in *.
  - exact H.
  - destruct (closed_tick st) as [st1|] eqn:EC; [|discriminate].
    destruct st as [[w f] h], st1 as [[w1 f1] h1].
    pose proof (closed_tick_sound _ _ _ _ _ _ EC) as ES.
    cbn in ES |- *. rewrite ES. exact (IH _ _ H).
Qed.
Definition state_eqb (a b : sstate) : bool :=
  let '(wa, fa, ha) := a in
  let '(wb, fb, hb) := b in
  word_eqb wa wb && (fa =? fb) && Nat.eqb ha hb.
Lemma state_eqb_true (a b : sstate) :
  state_eqb a b = true -> a = b.
Proof.
  destruct a as [[wa fa] ha], b as [[wb fb] hb].
  cbn [state_eqb]. intros H.
  apply andb_prop in H. destruct H as [Hwf Hh].
  apply andb_prop in Hwf. destruct Hwf as [Hw Hf].
  apply word_eqb_true in Hw. apply N.eqb_eq in Hf.
  apply PeanoNat.Nat.eqb_eq in Hh. subst. reflexivity.
Qed.
Definition span_certificate
      (n : N) (st target : sstate) : bool :=
  match closed_tickk (N.to_nat n) st with
  | Some actual => state_eqb actual target
  | None => false
  end.
Theorem span_certificate_sound :
  forall n st target,
    span_certificate n st target = true ->
    stepN n st = Some target.
Proof.
  intros n st target H. unfold span_certificate in H.
  destruct (closed_tickk (N.to_nat n) st) as [actual|] eqn:EC;
    [|discriminate].
  apply state_eqb_true in H. subst actual.
  unfold stepN. exact (closed_tickk_sound _ _ _ EC).
Qed.
Fixpoint generation_audit
    (fuel : nat) (w : word) (f : N) (h : nat) : bool :=
  match fuel with
  | O => true
  | S fu =>
      match genstep w f h with
      | GOk k w2 f2 h2 =>
          span_certificate k (w, f, h) (w2, f2, h2)
          && generation_audit fu w2 f2 h2
      | GNo =>
          match step w f h with
          | (ROk w2 f2, i) =>
              generation_audit fu w2 f2 (next_hint i)
          | _ => true
          end
      end
  end.
Theorem gen_brun_halts_audited
        (SS : StepSound)
        (SG : StepGuard) :
  forall fuel w f h n w' f' n',
    generation_audit fuel w f h = true ->
    gen_brun fuel w f h n = GGuard w' f' n' ->
    halts tmB (wconf [] 0 (sdecode w f)).
Proof.
  induction fuel as [|fu IH]; intros w f h n w' f' n' HA HG;
    cbn [generation_audit gen_brun] in *.
  - discriminate.
  - destruct (genstep w f h) as [k w2 f2 h2|] eqn:EG.
    + apply andb_prop in HA. destruct HA as [HC HA].
      exact (stepN_sound_impl SS _ _ _ _ _ _ _
               (span_certificate_sound _ _ _ HC)
               (IH _ _ _ _ _ _ _ HA HG)).
    + destruct (step w f h) as [r i] eqn:ES.
      destruct r as [w2 f2| |].
      * exact (SS _ _ _ _ _ _ ES (IH _ _ _ _ _ _ _ HA HG)).
      * inversion HG; subst. exact (SG _ _ _ _ ES).
      * discriminate.
Qed.
Local Open Scope N_scope.
Local Open Scope N_scope.
Local Open Scope bool_scope.
Local Open Scope sym.
Local Open Scope N_scope.
Local Open Scope bool_scope.
Local Open Scope sym.
Local Open Scope nat_scope.
Local Open Scope sym.
Local Open Scope list.
Lemma wcross_gms (p : word) :
  forallb is_col p = true ->
  wcross p = csuml ccross (gms p).
Proof.
  induction p as [|[[o z] c] t IH]; intros HP; [reflexivity|].
  cbn [forallb] in HP. apply andb_prop in HP. destruct HP as (HG & HT).
  unfold is_col in HG. cbn [gZ gO] in HG.
  apply andb_prop in HG. destruct HG as (HZ & HO).
  apply N.eqb_eq in HZ. apply N.leb_le in HO.
  specialize (IH HT).
  cbn [gms wcross gcross].
  rewrite (csuml_app ccross (repeat (N.to_nat o - 2)%nat (N.to_nat c))
             (gms t)).
  rewrite (csuml_repeat ccross (N.to_nat o - 2)%nat (N.to_nat c)).
  rewrite <- IH.
  unfold ccross.
  assert (Eo : N.of_nat (N.to_nat o - 2)%nat = (o - 2)%N)
    by (rewrite Nat2N.inj_sub, N2Nat.id; reflexivity).
  assert (Ec : N.of_nat (N.to_nat c) = c) by apply N2Nat.id.
  rewrite Eo, Ec.
  replace (o - 2 + 4)%N with (o + 2)%N by lia.
  reflexivity.
Qed.
Definition trgcost (e : trg) : N :=
  let '(X, NL, mid) := e in d_trig X NL mid.
Fixpoint chcost (ch : list trg) : N :=
  match ch with
  | [] => 0%N
  | e :: r => (trgcost e + chcost r)%N
  end.
Definition gchcost (p : word) (ch : list trg) : N :=
  (wcross p + chcost ch + 2)%N.
Lemma halts_in_pre (n : nat) (l : wside) (cur : Sym) (r : wside)
      (l1 : wside) (c1 : Sym) (r1 : wside) (K M : N) :
  wrunc n l cur r = Some ((l1, c1, r1), K) ->
  halts_in tmB (wconf l1 c1 r1) (N.to_nat M) ->
  halts_in tmB (wconf l cur r) (N.to_nat (K + M)%N).
Proof.
  intros HR HH.
  rewrite N2Nat.inj_add.
  eapply halts_in_multistep; [exact (wrunc_sound _ _ _ _ _ _ HR)|].
  cbn [wconf']. exact HH.
Qed.
Lemma StepGuardC_dborrow_inc (x : nat) (l r : wside) :
  zheaded l ->
  wrunc 2 l 0 ((1, S (S (S x))) :: (0,3%nat) :: (1,4%nat) :: (0,2%nat) :: r)
  = Some ((((0,1%nat) :: (1,6%nat) :: (0,1%nat) :: (1,S x) :: (0,1%nat)
             :: (1,2%nat) :: l), 0, r), (N.of_nat x + 14)%N).
Proof.
  intros H.
  apply (ccost_pin _ _ _ _ _ _ (dborrow_in' x l r H)).
  eexists. wcbn. ccost_close.
Qed.
Lemma dying_msc (L : wside) (ms : list nat) (z : nat) (R : wside) (T : N) :
  T = (csuml ccross ms + 2)%N ->
  halts_in tmB (wconf L 0 (uword ms ((1,1%nat) :: (0,S z) :: R)))
           (N.to_nat T).
Proof.
  intros ->.
  rewrite N2Nat.inj_add. change (N.to_nat 2%N) with 2%nat.
  eapply wrunc_halts_in.
  - apply wcross_mixedc.
  - destruct z as [|z']; unfold wsection; cbn [wpop]; reflexivity.
Qed.
Lemma trig_msc (L : wside) (ms : list nat) (x : nat) (R : wside) (M T : N) :
  zheaded L ->
  T = (csuml ccross ms + (N.of_nat x + 14) + M)%N ->
  halts_in tmB (wconf ((0,1%nat) :: (1,6%nat) :: (0,1%nat) :: (1,S x)
                        :: (0,1%nat) :: (1,2%nat) :: vstack ms L) 0 R)
           (N.to_nat M) ->
  halts_in tmB (wconf L 0
     (uword ms ((1, S (S (S x))) :: (0,3%nat) :: (1,4%nat) :: (0,2%nat)
                  :: R)))
     (N.to_nat T).
Proof.
  intros HZ -> Hh.
  replace (csuml ccross ms + (N.of_nat x + 14) + M)%N
    with (csuml ccross ms + ((N.of_nat x + 14) + M))%N by lia.
  apply (halts_in_pre _ _ _ _ _ _ _ _ _ (wcross_mixedc ms L _)).
  apply (halts_in_pre _ _ _ _ _ _ _ _ _
           (StepGuardC_dborrow_inc x _ R (zheaded_vstack ms L HZ))).
  exact Hh.
Qed.
Lemma guard_chain_gen_in (L : wside) (p : word) (ch : list trg)
      (zn cn : N) (t : word) (f : N) :
  zheaded L ->
  forallb is_col p = true ->
  forallb trgok ch = true ->
  (1 <= zn)%N -> (1 <= cn)%N ->
  halts_in tmB (wconf L 0
    (bdecode ((p ++ dchain ch ((1,zn,cn)%N :: t))%N, f)))
    (N.to_nat (gchcost p ch)).
Proof.
  intros HZ0 HP0 HC0 Hz Hc. revert L p HZ0 HP0 HC0.
  induction ch as [|[[X NL] mid] ch IH]; intros L p HZ HP HC.
  -
    destruct (to_nat_ge1 zn Hz) as [z Ez].
    destruct (to_nat_ge1 cn Hc) as [c Ec].
    assert (E1 : bdecode ((p ++ ((1,zn,cn)%N :: t))%N, f)
               = uword (gms p)
                   ((1,1%nat) :: (0,S z)
                      :: pair_runs 1%nat (S z) c
                         ++ expand (map gdecode t) ++ frun f)).
    { rewrite bdecode_pre, (uword_gms _ _ (zpre_of_forallb p HP)).
      f_equal.
      unfold bdecode. cbn [map gdecode expand].
      rewrite Ez, Ec.
      change (N.to_nat 1) with 1%nat.
      cbn [pair_runs app].
      rewrite <- ?app_assoc. reflexivity. }
    cbn [dchain]. rewrite E1.
    unfold gchcost. cbn [chcost].
    rewrite (wcross_gms p HP).
    apply dying_msc. lia.
  -
    cbn [forallb] in HC. apply andb_prop in HC. destruct HC as (HE & HC').
    unfold trgok in HE.
    apply andb_prop in HE. destruct HE as (HE1 & HM).
    apply andb_prop in HE1. destruct HE1 as (HX & HN).
    apply N.leb_le in HX. apply N.leb_le in HN.
    assert (EX : exists x, N.to_nat X = S (S (S x))).
    { destruct (N.to_nat X) as [|[|[|x]]] eqn:E; try (exfalso; lia). eauto. }
    destruct EX as [x EXx].
    destruct (to_nat_ge1 NL HN) as [n1 EN].
    assert (HPQ : forallb is_col ((4,2,N.of_nat n1)%N :: mid) = true).
    { cbn [forallb]. rewrite HM. reflexivity. }
    assert (E1 : bdecode
                   ((p ++ (X,3,1)%N :: (4,2,NL)%N
                        :: mid ++ dchain ch ((1,zn,cn)%N :: t))%N, f)
               = uword (gms p)
                   ((1, S (S (S x))) :: (0,3%nat) :: (1,4%nat) :: (0,2%nat)
                      :: uword (repeat 2%nat n1 ++ gms mid)
                           (bdecode
                              ((dchain ch ((1,zn,cn)%N :: t))%N, f)))).
    { rewrite bdecode_pre, (uword_gms _ _ (zpre_of_forallb p HP)).
      f_equal.
      rewrite (uword_app_ms (repeat 2%nat n1)), uword_repeat_w,
              (uword_gms _ _ (zpre_of_forallb mid HM)).
      unfold bdecode. cbn [map gdecode expand].
      rewrite map_app, expand_app. cbn [map gdecode expand].
      rewrite EXx, EN.
      change (N.to_nat 3) with 3%nat.
      change (N.to_nat 4) with 4%nat.
      change (N.to_nat 2) with 2%nat.
      change (N.to_nat 1) with 1%nat.
      change (2 + 2)%nat with 4%nat.
      cbn [pair_runs app].
      rewrite <- ?app_assoc. reflexivity. }
    cbn [dchain]. rewrite E1.
    assert (EXn : X = (N.of_nat x + 3)%N) by lia.
    assert (ENn : NL = (N.of_nat n1 + 1)%N) by lia.
    apply (trig_msc L (gms p) x _
             (gchcost ((4,2,N.of_nat n1)%N :: mid) ch) _ HZ).
    {
      unfold gchcost.
      cbn [chcost trgcost wcross gcross].
      unfold d_trig.
      rewrite (wcross_gms p HP).
      lia. }
    specialize (IH ((0,1%nat) :: (1,6%nat) :: (0,1%nat) :: (1,S x)
                      :: (0,1%nat) :: (1,2%nat)
                      :: vstack (gms p) L)
                   ((4,2,N.of_nat n1)%N :: mid)).
    rewrite bdecode_pre in IH.
    rewrite <- (uword_gms _ _ (zpre_of_forallb _ HPQ)) in IH.
    cbn [gms] in IH.
    rewrite Nat2N.id in IH.
    change (N.to_nat 4 - 2)%nat with 2%nat in IH.
    apply IH; try assumption.
    cbn. reflexivity.
Qed.
Lemma guard_chain_halts_in (p : word) (ch : list trg)
      (zn cn : N) (t : word) (f : N) (T : N) :
  forallb is_col p = true ->
  forallb trgok ch = true ->
  (1 <= zn)%N -> (1 <= cn)%N ->
  T = gchcost p ch ->
  halts_in tmB
    (wconf [] 0 (sdecode ((p ++ dchain ch ((1,zn,cn)%N :: t))%N) f))
    (N.to_nat T).
Proof.
  intros HP HC Hz Hc ->.
  unfold sdecode.
  exact (guard_chain_gen_in [] p ch zn cn t f I HP HC Hz Hc).
Qed.
Corollary guard_halts_in (p : word) (zn cn : N) (t : word) (f : N)
      (T : N) :
  forallb is_col p = true ->
  (1 <= zn)%N -> (1 <= cn)%N ->
  T = (wcross p + 2)%N ->
  halts_in tmB (wconf [] 0 (sdecode ((p ++ (1,zn,cn)%N :: t)%N) f))
           (N.to_nat T).
Proof.
  intros HP Hz Hc HT.
  apply (guard_chain_halts_in p [] zn cn t f T HP eq_refl Hz Hc).
  rewrite HT. unfold gchcost. cbn [chcost]. lia.
Qed.
Lemma e0_chain_cost (n : nat) (s : word) :
  e0_chain n s = true -> exists K, e0_cost n s = Some K.
Proof.
  revert s. induction n as [|n IH]; intros s H; [discriminate|].
  cbn [e0_chain] in H. cbn [e0_cost].
  destruct s as [|[[X z] c] s1]; [discriminate|].
  destruct s1 as [|[[o2 z2] NL] r]; [discriminate|].
  destruct (csplit r) as [cols rest] eqn:ECS.
  apply andb_prop in H. destruct H as (HG & HR).
  rewrite HG.
  destruct rest as [|[[o3 zn] cn] rest1]; [discriminate HR|].
  destruct ((o3 =? 1)%N) eqn:EO3.
  - rewrite HR. eauto.
  - destruct (IH _ HR) as [K EK]. rewrite EK. eauto.
Qed.
Lemma e0_cost_chain (n : nat) (s : word) (K : N) :
  e0_cost n s = Some K -> e0_chain n s = true.
Proof.
  revert s K. induction n as [|n IH]; intros s K H; [discriminate|].
  cbn [e0_cost] in H. cbn [e0_chain].
  destruct s as [|[[X z] c] s1]; [discriminate|].
  destruct s1 as [|[[o2 z2] NL] r]; [discriminate|].
  destruct (csplit r) as [cols rest] eqn:ECS.
  destruct ((z =? 3) && (c =? 1) && (3 <=? X)
            && (o2 =? 4) && (z2 =? 2) && (1 <=? NL))%N eqn:HG; [|discriminate].
  destruct rest as [|[[o3 zn] cn] rest1]; [discriminate|].
  destruct ((o3 =? 1)%N) eqn:EO3.
  -
    destruct ((1 <=? zn) && (1 <=? cn))%N eqn:HZC; [|discriminate].
    reflexivity.
  -
    match type of H with
    | context [e0_cost ?A ?B] =>
        destruct (e0_cost A B) as [K1|] eqn:EK1
    end; [|discriminate].
    rewrite (IH _ _ EK1). reflexivity.
Qed.
Lemma e0_cost_decomp (n : nat) (s : word) (K : N) :
  e0_cost n s = Some K ->
  exists ch zn cn t,
    s = dchain ch ((1,zn,cn)%N :: t)
    /\ forallb trgok ch = true /\ (1 <= zn)%N /\ (1 <= cn)%N
    /\ K = chcost ch.
Proof.
  revert s K. induction n as [|n IH]; intros s K H; [discriminate|].
  cbn [e0_cost] in H.
  destruct s as [|[[X z] c] s1]; [discriminate|].
  destruct s1 as [|[[o2 z2] NL] r]; [discriminate|].
  destruct (csplit r) as [cols rest] eqn:ECS.
  destruct (csplit_cols _ _ _ ECS) as (HCOL & HRE).
  destruct ((z =? 3) && (c =? 1) && (3 <=? X)
            && (o2 =? 4) && (z2 =? 2) && (1 <=? NL))%N eqn:HG; [|discriminate].
  apply andb_prop in HG; destruct HG as (HG & HNL).
  apply andb_prop in HG; destruct HG as (HG & HZ2).
  apply andb_prop in HG; destruct HG as (HG & HO2).
  apply andb_prop in HG; destruct HG as (HG & HX).
  apply andb_prop in HG; destruct HG as (HZ3 & HC1).
  apply N.eqb_eq in HZ3. apply N.eqb_eq in HC1.
  apply N.eqb_eq in HO2. apply N.eqb_eq in HZ2.
  subst z c o2 z2.
  apply N.leb_le in HX. apply N.leb_le in HNL.
  assert (HTRG : trgok (X, NL, cols) = true).
  { unfold trgok. apply andb_true_intro. split.
    - apply andb_true_intro. split.
      + apply N.leb_le. exact HX.
      + apply N.leb_le. exact HNL.
    - exact HCOL. }
  destruct rest as [|[[o3 zn] cn] rest1]; [discriminate|].
  destruct ((o3 =? 1)%N) eqn:EO3.
  - apply N.eqb_eq in EO3. subst o3.
    destruct ((1 <=? zn) && (1 <=? cn))%N eqn:HZC; [|discriminate].
    apply andb_prop in HZC. destruct HZC as (HZN & HCN).
    apply N.leb_le in HZN. apply N.leb_le in HCN.
    injection H as HK.
    exists [(X, NL, cols)], zn, cn, rest1.
    split; [|split; [|split; [|split]]]; try assumption.
    + cbn [dchain]. rewrite HRE. reflexivity.
    + cbn [forallb]. rewrite HTRG. reflexivity.
    + cbn [chcost trgcost]. lia.
  - match type of H with
    | context [e0_cost ?A ?B] =>
        destruct (e0_cost A B) as [K1|] eqn:EK1
    end; [|discriminate].
    injection H as HK.
    destruct (IH _ _ EK1) as (ch & zn' & cn' & tl & HEQ & HCH & HZ & HC & HKC).
    exists ((X, NL, cols) :: ch), zn', cn', tl.
    split; [|split; [|split; [|split]]]; try assumption.
    + cbn [dchain]. rewrite HRE, HEQ. reflexivity.
    + cbn [forallb]. rewrite HTRG, HCH. reflexivity.
    + cbn [chcost trgcost]. lia.
Qed.
Lemma e0_rhalt_halts_in (w : word) (f : N) (i : nat) (K : N) :
  forallb is_col (firstn i w) = true ->
  e0_cost (List.length w) (skipn i w) = Some K ->
  halts_in tmB (wconf [] 0 (sdecode w f))
           (N.to_nat (wcross (firstn i w) + K + 2)%N).
Proof.
  intros HP EC.
  destruct (e0_cost_decomp _ _ _ EC)
    as (ch & zn & cn & tl & HEQ & HCH & HZn & HCn & HKC).
  rewrite <- (firstn_skipn i w) at 1.
  rewrite HEQ.
  apply (guard_chain_halts_in (firstn i w) ch zn cn tl f _ HP HCH HZn HCn).
  unfold gchcost. lia.
Qed.
Lemma firstn_S_wat (w : word) (j : nat) (g : bg) :
  wat w j = Some g -> firstn (S j) w = firstn j w ++ [g].
Proof.
  revert j. induction w as [|a t IH]; intros j H.
  - unfold wat in H. destruct j; discriminate.
  - destruct j as [|j].
    + unfold wat in H. cbn [nth_error] in H. injection H as <-.
      reflexivity.
    + cbn [firstn app]. f_equal. apply IH. exact H.
Qed.
Lemma inert_rhalt_halts_in (w : word) (f : N) (j : nat) (g : bg)
      (zn cn : N) (T : N) :
  forallb is_col (firstn j w) = true ->
  wat w j = Some g ->
  is_col g = true ->
  wat w (S j) = Some (1%N, zn, cn) ->
  (1 <= zn)%N -> (1 <= cn)%N ->
  T = (wcross (firstn (S j) w) + 2)%N ->
  halts_in tmB (wconf [] 0 (sdecode w f)) (N.to_nat T).
Proof.
  intros HP EJ HCJ EG HZ HC HT.
  assert (EF : firstn (S j) w = firstn j w ++ [g])
    by (apply firstn_S_wat; exact EJ).
  assert (EW : w = (firstn j w ++ [g]) ++ (1%N,zn,cn) :: skipn (S (S j)) w).
  { rewrite <- app_assoc. cbn [app].
    rewrite (word_split w j _ EJ) at 1.
    f_equal. f_equal.
    apply (skipn_wat w (S j) _ EG). }
  rewrite EW at 1.
  apply (guard_halts_in (firstn j w ++ [g]) zn cn (skipn (S (S j)) w) f T).
  - rewrite forallb_app, HP. cbn [forallb andb].
    rewrite HCJ. reflexivity.
  - exact HZ.
  - exact HC.
  - rewrite HT, EF. reflexivity.
Qed.
Lemma e0_arm_halts_in (w : word) (f : N) (i : nat) :
  forallb is_col (firstn i w) = true ->
  e0_chain (List.length w) (skipn i w) = true ->
  exists k, cin k (d_e0 w i)
            /\ halts_in tmB (wconf [] 0 (sdecode w f)) k.
Proof.
  intros HP HE.
  destruct (e0_chain_cost _ _ HE) as [K EK].
  unfold d_e0. rewrite EK.
  exists (N.to_nat (wcross (firstn i w) + K + 2)%N).
  split; [apply cin_cx|].
  exact (e0_rhalt_halts_in w f i K HP EK).
Qed.
Lemma inert_arm_halts_in (w : word) (f : N) (j : nat) (g : bg)
      (zn cn : N) :
  cmf_from w (Nat.max 1%nat (gstart2 w)) (List.length w) = Some j ->
  forallb is_col (firstn j w) = true ->
  wat w j = Some g -> is_col g = true ->
  wat w (S j) = Some (1%N, zn, cn) ->
  (1 <= zn)%N -> (1 <= cn)%N ->
  exists k, cin k (d_inert w)
            /\ halts_in tmB (wconf [] 0 (sdecode w f)) k.
Proof.
  intros ECF HP EJ HCJ EG HZ HC.
  unfold d_inert. rewrite ECF.
  exists (N.to_nat (wcross (firstn (S j) w) + 2)%N).
  split; [apply cin_cx|].
  exact (inert_rhalt_halts_in w f j g zn cn _ HP EJ HCJ EG HZ HC eq_refl).
Qed.
Opaque FUEL.
Opaque deliver_tick fire renewal chain_merge_advance.
