Lemma csplit_range (s : word) (k : nat) (g : bg) :
  forallb is_col (firstn k s) = true ->
  wat s k = Some g -> is_col g = false ->
  csplit s = (firstn k s, skipn k s).
Proof.
  revert s. induction k as [|k IH]; intros s HP EJ HC.
  - destruct s as [|a t]; [unfold wat in EJ; discriminate|].
    unfold wat in EJ. cbn [nth_error] in EJ.
    injection EJ as EJ. subst a.
    cbn [csplit firstn skipn]. rewrite HC. reflexivity.
  - destruct s as [|a t].
    + unfold wat in EJ. destruct k; discriminate.
    + cbn [firstn forallb] in HP. apply andb_prop in HP.
      destruct HP as (HA & HT).
      cbn [csplit]. rewrite HA.
      rewrite (IH t HT EJ HC).
      cbn [firstn skipn]. reflexivity.
Qed.
Lemma e0_cost_of_shape (w : word) (i jw : nat) (o NL zn cn : N)
      (n : nat) :
  wat w i = Some (o, 3%N, 1%N) ->
  (3 <= o)%N ->
  wat w (S i) = Some (4%N, 2%N, NL) ->
  (1 <= NL)%N ->
  (S (S i) <= jw)%nat ->
  (forall m, (S (S i) <= m < jw)%nat ->
     exists g, wat w m = Some g /\ is_col g = true) ->
  wat w jw = Some (1%N, zn, cn) ->
  (1 <= zn)%N -> (1 <= cn)%N ->
  e0_cost (S n) (skipn i w)
  = Some (d_trig o NL (firstn (jw - S (S i)) (skipn (S (S i)) w))).
Proof.
  intros E0 HO E1 HNL HLE HMID EG HZ HC.
  assert (ES : skipn i w
             = (o,3%N,1%N) :: (4%N,2%N,NL) :: skipn (S (S i)) w).
  { rewrite (skipn_wat w i _ E0). f_equal.
    exact (skipn_wat w (S i) _ E1). }
  assert (EGJ : wat (skipn (S (S i)) w) (jw - S (S i))
              = Some (1%N, zn, cn)).
  { unfold wat. rewrite nth_error_skipn.
    replace (S (S i) + (jw - S (S i)))%nat with jw by lia.
    exact EG. }
  assert (HNC : is_col (1%N, zn, cn) = false).
  { unfold is_col. cbn [gZ gO].
    destruct ((zn =? 2)%N); reflexivity. }
  assert (HCOL : forallb is_col
                   (firstn (jw - S (S i)) (skipn (S (S i)) w)) = true).
  { apply pointwise_slice_col. intros m Hm. apply HMID. lia. }
  assert (ERE : skipn (jw - S (S i)) (skipn (S (S i)) w)
              = (1%N,zn,cn) :: skipn (S jw) w).
  { rewrite skipn_skipn.
    replace (S (S i) + (jw - S (S i)))%nat with jw by lia.
    exact (skipn_wat w jw _ EG). }
  assert (HG : ((3 =? 3) && (1 =? 1) && (3 <=? o)
                && (4 =? 4) && (2 =? 2) && (1 <=? NL))%N = true).
  { rewrite (proj2 (N.leb_le 3 o) HO), (proj2 (N.leb_le 1 NL) HNL).
    reflexivity. }
  rewrite ES. cbn [e0_cost].
  rewrite HG, (csplit_range _ _ _ HCOL EGJ HNC), ERE.
  lazy beta iota.
  rewrite (proj2 (N.leb_le 1 zn) HZ), (proj2 (N.leb_le 1 cn) HC).
  reflexivity.
Qed.
Lemma payload_e0_chain (w0 w1c : word) (i0 : nat)
      (o NL : N) (w2 : word) (base j : nat) (zn cn : N) (n : nat) :
  (forall m, (1 <= m)%nat -> wat w1c m = wat w0 m) ->
  wat w0 i0 = Some (o, 3%N, 1%N) ->
  (5 <= o)%N ->
  wat w1c (S i0) = Some (4%N, 2%N, NL) ->
  (1 <= NL)%N ->
  w2 = subst_at i0 2
         ((o-1,1,1)%N :: (7,2,1)%N
          :: (if (1 <? NL)%N then [(4,2,NL-1)%N] else [])) w1c ->
  base = (if (1 <? NL)%N then S (S (S i0)) else S (S i0)) ->
  tick_target w2 base = Some j ->
  (exists g2, wat w2 j = Some g2 /\ is_cmf g2 = true) ->
  wat w2 (S j) = Some (1%N, zn, cn) ->
  (1 <= zn)%N -> (1 <= cn)%N ->
  (i0 <= length w1c)%nat ->
  e0_chain (S n) (skipn i0 w0) = true.
Proof.
  intros TRW E0 HO E1 HNL EW2 EB ETT (g2 & EG2 & ECMF) EG HZ HC HLEN.
  pose proof (tick_target_inv _ _ _ ETT) as (HBJ & _ & HMID).
  destruct ((1 <? NL)%N) eqn:ENL.
  -
    subst base.
    try rewrite ENL in EW2.
    cbn beta iota in EW2.
    assert (SH : forall m, (S (S (S i0)) <= m)%nat ->
              wat w2 m = wat w0 (m - 1)).
    { intros m HN.
      rewrite EW2.
      rewrite (wat_subst_high i0 2
                 ((o-1,1,1)%N :: (7,2,1)%N :: [(4,2,(NL-1))%N]) w1c m
                 HLEN ltac:(cbn [length]; lia)).
      cbn [length].
      rewrite TRW by lia.
      f_equal. lia. }
    refine (e0_cost_chain (S n) (skipn i0 w0)
              (d_trig o NL
                 (firstn (j - S (S i0)) (skipn (S (S i0)) w0))) _).
    apply (e0_cost_of_shape w0 i0 j o NL zn cn n).
    + exact E0.
    + lia.
    + rewrite <- TRW by lia. exact E1.
    + exact HNL.
    + lia.
    + intros m Hm.
      destruct (PeanoNat.Nat.eq_dec m (j - 1)) as [->|NE].
      * exists g2. split; [|apply cmf_is_col; exact ECMF].
        rewrite <- (SH j) by lia. exact EG2.
      * destruct (HMID (m + 1)%nat ltac:(lia)) as (gm & HGm & HCm).
        exists gm. split; [|exact HCm].
        replace m with ((m + 1) - 1)%nat by lia.
        rewrite <- (SH (m + 1)%nat) by lia.
        exact HGm.
    + replace j with (S j - 1)%nat by lia.
      rewrite <- (SH (S j)) by lia.
      exact EG.
    + exact HZ.
    + exact HC.
  -
    subst base.
    try rewrite ENL in EW2.
    cbn beta iota in EW2.
    assert (SH : forall m, (S (S i0) <= m)%nat ->
              wat w2 m = wat w0 m).
    { intros m HN.
      rewrite EW2.
      rewrite (wat_subst_high i0 2
                 ((o-1,1,1)%N :: (7,2,1)%N :: []) w1c m
                 HLEN ltac:(cbn [length]; lia)).
      cbn [length].
      rewrite TRW by lia.
      f_equal. lia. }
    refine (e0_cost_chain (S n) (skipn i0 w0)
              (d_trig o NL
                 (firstn (S j - S (S i0)) (skipn (S (S i0)) w0))) _).
    apply (e0_cost_of_shape w0 i0 (S j) o NL zn cn n).
    + exact E0.
    + lia.
    + rewrite <- TRW by lia. exact E1.
    + exact HNL.
    + lia.
    + intros m Hm.
      destruct (PeanoNat.Nat.eq_dec m j) as [->|NE].
      * exists g2. split; [|apply cmf_is_col; exact ECMF].
        rewrite <- (SH j) by lia. exact EG2.
      * destruct (HMID m ltac:(lia)) as (gm & HGm & HCm).
        exists gm. split; [|exact HCm].
        rewrite <- (SH m) by lia. exact HGm.
    + rewrite <- (SH (S j)) by lia. exact EG.
    + exact HZ.
    + exact HC.
Qed.
Lemma guard_arm_halts_in (w : word) (f : N) (h : nat) (i : nat) :
  step_after_front None w f h = (RHalt, i) ->
  exists k, cin k (d_guard w i)
            /\ halts_in tmB (wconf [] 0 (sdecode w f)) k.
Proof.
  intros H.
  destruct w as [|g0 t0].
  { cbn [step_after_front step_after_front_with
         step_after_front_with_guard find_active
         find_active_s] in H.
    unfold find_active in H.
    rewrite skipn_nil in H.
    cbn [find_active_s] in H.
    discriminate. }
  cbn [step_after_front step_after_front_with
       step_after_front_with_guard] in H.
  match type of H with
  | context [find_active ?W ?S] =>
      destruct (find_active W S) as [i0|] eqn:EFA
  end.
  -
    pose proof (find_active_inv _ _ _ EFA) as (HST & o & z & c & EW & HZD).
    destruct (negb (forallb is_col (firstn i0 (g0 :: t0)))) eqn:EFB;
      cbn [orb negb] in H; try rewrite EFB in H; try discriminate H.
    apply negb_false_iff in EFB.
    destruct ((gO g0 =? 2)%N && (gZ g0 =? 2)%N
              && (1 <=? gC g0)%N
              && negb (Nat.eqb i0 0)) eqn:EB;
      cbn [orb negb] in H; try rewrite EB in H; try discriminate H.
    destruct (match last1 (firstn i0 (g0 :: t0)) with
              | Some g => ((3 <=? gO g)%N && (1 <=? gC g)%N)%bool
              | None => false
              end) eqn:EBL;
      cbn [orb negb] in H; try rewrite EBL in H; try discriminate H.
    { match type of H with
      | context [match ?C with
                 | Some _ => _
                 | None => _
                 end] =>
          remember C as comp0 eqn:ECdef
      end.
      destruct comp0 as [[[k b2] f2]|].
      { destruct k; discriminate H. }
      clear ECdef.
      destruct (wat ((2,2,gC g0+1)%N :: t0) i0) as [g3|] eqn:EW3;
        [|inversion H].
      destruct ((gZ g3 =? 1)%N) eqn:EZ1; [inversion H|].
      apply andb_prop in EB. destruct EB as (_ & EBI).
      apply negb_true_iff in EBI.
      apply PeanoNat.Nat.eqb_neq in EBI.
      destruct i0 as [|i0']; [congruence|].
      match type of H with
      | context [e0_chain ?A ?B] => destruct (e0_chain A B) eqn:EE0
      end.
      {
        assert (Ei : S i0' = i) by (exact (f_equal snd H)).
        rewrite <- Ei.
        apply (e0_arm_halts_in (g0 :: t0) f (S i0')).
        - exact EFB.
        - exact EE0. }
      exfalso.
      match type of H with
      | context [deliver_tick ?A ?B ?C ?D ?E] =>
          remember (deliver_tick A B C D E) as dtr eqn:EDTdef
      end.
      destruct dtr; try (inversion H; fail).
      symmetry in EDTdef.
      assert (EWX : wat ((2,2,gC g0+1)%N :: t0) (S i0')
                    = Some (o, z, c)) by exact EW.
      assert (EQ3 : g3 = (o, z, c)) by congruence.
      subst g3.
      cbn [gZ] in EZ1.
      assert (HZ3 : (3 <= z)%N).
      { destruct HZD as [-> | HZ3]; [|exact HZ3].
        rewrite N.eqb_refl in EZ1. discriminate. }
      destruct (dt_rhalt_inv _ _ _ _ _ _ _ _ EWX HZ3 EDTdef)
        as (NL & w2 & base & j & zn & cn & EZq & ECq & HO & E1 & HNL
            & EW2 & EB2 & ETT & HG2 & EG & HZg & HCg).
      subst z c.
      assert (EE0' : e0_chain (S (List.length t0))
                       (skipn (S i0') (g0 :: t0)) = false) by exact EE0.
      assert (ECH : e0_chain (S (List.length t0))
                      (skipn (S i0') (g0 :: t0)) = true).
      { apply (payload_e0_chain (g0 :: t0) ((2,2,gC g0+1)%N :: t0)
                 (S i0') o NL w2 base j zn cn (List.length t0));
          try assumption.
        - intros m HM. destruct m as [|m]; [lia|reflexivity].
        - eapply PeanoNat.Nat.lt_le_incl, wat_len. exact EWX. }
      rewrite ECH in EE0'. discriminate. }
  -
    destruct (negb ((gO g0 =? 2)%N && (gZ g0 =? 2)%N
                    && (1 <=? gC g0)%N)) eqn:EI22;
      [inversion H|].
    match type of H with
    | context [cmf_from ?W ?S2 ?L] =>
        destruct (cmf_from W S2 L) as [j|] eqn:ECF
    end.
    +
      pose proof (cmf_from_inv _ _ _ _ ECF) as (HJ1 & gc & EGC & ECMFc).
      destruct (negb (forallb is_col (firstn j (g0 :: t0)))) eqn:EFB2;
        [inversion H|].
      apply negb_false_iff in EFB2.
      destruct (leaf_act _ _) as [[sfx2 f2]|] eqn:ELA; [inversion H|].
      remember (chain_merge_advance FUEL
                  ((2,2,gC g0+1)%N :: t0) f j) as cmr eqn:ECMdef.
      destruct cmr; try (inversion H; fail).
      symmetry in ECMdef.
      apply cma_rhalt_inv in ECMdef.
      destruct ECMdef as (zn & cn & EGn & HZn & HCn).
      assert (Ei : O = i) by (exact (f_equal snd H)).
      rewrite <- Ei.
      apply (inert_arm_halts_in (g0 :: t0) f j gc zn cn).
      * exact ECF.
      * exact EFB2.
      * exact EGC.
      * apply cmf_is_col. exact ECMFc.
      * exact EGn.
      * exact HZn.
      * exact HCn.
    +
      destruct (existsb _ t0) eqn:EEX; [|inversion H].
      remember (debris_to_blank ((2,2,gC g0+1)%N :: t0) f)
        as dbr eqn:EDBdef.
      destruct dbr; try (inversion H; fail).
      symmetry in EDBdef.
      exfalso. eapply dtb_no_rhalt. exact EDBdef.
Qed.
Theorem StepGuardC_holds (w : word) (f : N) (h : nat) (i : nat)
        (d : cost) :
  cstep w f h = (RHalt, i, d) ->
  exists k, cin k d /\ halts_in tmB (wconf [] 0 (sdecode w f)) k.
Proof.
  intros HS. unfold cstep in HS.
  destruct (cstep_front w f) as [[r dd]|] eqn:EF.
  - destruct r as [wq fq| |]; discriminate HS.
  - destruct (step_after_front None w f h) as [r i2] eqn:E2.
    destruct r as [wq fq| |]; try discriminate HS.
    assert (Ei : i2 = i) by (exact (f_equal (fun x => snd (fst x)) HS)).
    assert (Ed : d_guard w i2 = d) by (exact (f_equal snd HS)).
    subst i2.
    rewrite <- Ed.
    exact (guard_arm_halts_in w f h i E2).
Qed.
