Theorem StepSoundC_holds (w : word) (f : N) (h : nat)
        (w' : word) (f' : N) (i : nat) (d : cost) :
  cstep w f h = (ROk w' f', i, d) ->
  cempty d \/ sound_impl_c d w f w' f'.
Proof. exact (cstep_sound_bank w f h w' f' i d). Qed.
Definition sconfc (s : sstate) : Q * tape :=
  wconf [] 0 (sdecode (fst (fst s)) (snd (fst s))).
Theorem cbruns_sound (k : nat) (s s' : sstate) (D : cost) :
  cbruns k s = Some (s', D) -> ~ cempty D ->
  creach D (sconfc s) (sconfc s').
Proof.
  revert s D. induction k as [|k IH]; intros s D HB HE.
  - rewrite cbruns_zero in HB. injection HB as E1 E2.
    subst s' D. exact (creach_refl _).
  - rewrite cbruns_S in HB.
    destruct (cstep1 s) as [[s2 d]|] eqn:E1; [|discriminate HB].
    destruct (cbruns k s2) as [[s3 D2]|] eqn:E2; [|discriminate HB].
    injection HB as E3 E4. subst s3 D.
    destruct (cadds_ne_inv d D2 HE) as (Hd & HD2 & Heq).
    rewrite Heq.
    destruct s as [[w f] h].
    destruct (cstep1_inv w f h s2 d E1) as [i Hi].
    assert (Hne : ~ cempty d) by (unfold cempty; lia).
    assert (Hstep : creach d (sconfc (w, f, h)) (sconfc s2)).
    { destruct (StepSoundC_holds w f h (fst (fst s2)) (snd (fst s2)) i d Hi)
        as [Hc|Hs]; [exact (match Hne Hc with end)|exact Hs]. }
    assert (Hrest : creach D2 (sconfc s2) (sconfc s')).
    { apply (IH s2 D2 E2). unfold cempty; lia. }
    exact (creach_trans d D2 _ _ _ Hstep Hrest).
Qed.
Corollary cbruns_sound_cx (k : nat) (s s' : sstate) (K : N) :
  cbruns k s = Some (s', cx K) ->
  sconfc s =( N.to_nat K )=> sconfc s'.
Proof.
  intros HB.
  exact (creach_cx_inv K _ _
           (cbruns_sound k s s' (cx K) HB (cx_not_cempty K))).
Qed.
Theorem cbruns_halts_in (k : nat) (s s' : sstate) (K : N)
        (i : nat) (dg : cost) :
  cbruns k s = Some (s', cx K) ->
  cstep (fst (fst s')) (snd (fst s')) (snd s') = (RHalt, i, dg) ->
  exists kg, cin kg dg /\ halts_in tmB (sconfc s) (N.to_nat K + kg).
Proof.
  intros HB HG.
  destruct (StepGuardC_holds (fst (fst s')) (snd (fst s')) (snd s') i dg HG)
    as (kg & Hin & Hh).
  exists kg. split; [exact Hin|].
  eapply halts_in_multistep;
    [exact (cbruns_sound_cx k s s' K HB) | exact Hh].
Qed.
Corollary cbruns_halts_in_exact (k : nat) (s s' : sstate)
          (K Kg : N) (i : nat) :
  cbruns k s = Some (s', cx K) ->
  cstep (fst (fst s')) (snd (fst s')) (snd s')
    = (RHalt, i, cx Kg) ->
  halts_in tmB (sconfc s) (N.to_nat K + N.to_nat Kg).
Proof.
  intros HB HG.
  destruct (cbruns_halts_in k s s' K i (cx Kg) HB HG) as (kg & Hin & Hh).
  rewrite (StepGuardC_cin_cx_eq kg Kg Hin) in Hh. exact Hh.
Qed.
