Definition samez (a b : bg) : bool :=
  (gO a =? gO b) && (gZ a =? gZ b).
Fixpoint nmerge (a b : word) : word :=
  match a with
  | [] => b
  | g :: t =>
      match nmerge t b with
      | [] => [g]
      | g2 :: t2 =>
          if (gO g =? gO g2) && (gZ g =? gZ g2)
          then (gO g, gZ g, gC g + gC g2) :: t2
          else g :: g2 :: t2
      end
  end.
Lemma normalize_nmerge : forall w, normalize w = nmerge w [].
Proof.
  induction w as [|g t IH]; cbn [normalize nmerge]; [reflexivity|].
  rewrite IH. reflexivity.
Qed.
Lemma nmerge_app : forall a b c, nmerge (a ++ b) c = nmerge a (nmerge b c).
Proof.
  induction a as [|g t IH]; intros b c; cbn [app nmerge]; [reflexivity|].
  rewrite IH. reflexivity.
Qed.
Lemma normalize_app : forall a b,
  normalize (a ++ b) = nmerge a (normalize b).
Proof. intros a b. rewrite !normalize_nmerge, nmerge_app. reflexivity. Qed.
Fixpoint nml (w : word) : bool :=
  match w with
  | [] => true
  | g :: t =>
      match t with
      | [] => true
      | g2 :: _ => negb (samez g g2) && nml t
      end
  end.
Definition nojunc (a b : word) : bool :=
  match last1 a, b with
  | Some g, g2 :: _ => negb (samez g g2)
  | _, _ => true
  end.
Lemma nml_cons_inv : forall g t, nml (g :: t) = true -> nml t = true.
Proof.
  intros g [|g2 t] H; cbn in H |- *; [reflexivity|].
  apply andb_prop in H. destruct H as [_ H]. exact H.
Qed.
Lemma last1_cons2 : forall g g2 t, last1 (g :: g2 :: t) = last1 (g2 :: t).
Proof. intros. reflexivity. Qed.
Lemma nmerge_no_merge : forall a b,
  nml a = true -> nojunc a b = true -> nmerge a b = a ++ b.
Proof.
  induction a as [|g t IH]; intros b Hn Hj; cbn [nmerge app]; [reflexivity|].
  destruct t as [|g1 t'].
  - cbn [nmerge]. destruct b as [|g2 b']; [reflexivity|].
    unfold nojunc in Hj. cbn [last1] in Hj.
    unfold samez in Hj. apply negb_true_iff in Hj. rewrite Hj. reflexivity.
  - rewrite IH.
    + cbn [app]. cbn [nml] in Hn. apply andb_prop in Hn. destruct Hn as [Hn _].
      unfold samez in Hn. apply negb_true_iff in Hn. rewrite Hn. reflexivity.
    + exact (nml_cons_inv _ _ Hn).
    + unfold nojunc in Hj |- *. rewrite last1_cons2 in Hj. exact Hj.
Qed.
Lemma nml_normalize_id : forall w, nml w = true -> normalize w = w.
Proof.
  intros w H. rewrite normalize_nmerge, nmerge_no_merge; auto.
  - apply app_nil_r.
  - unfold nojunc. destruct (last1 w); reflexivity.
Qed.
Lemma nml_cons_merged : forall g g2 t2,
  (gO g =? gO g2) && (gZ g =? gZ g2) = true ->
  nml (g2 :: t2) = true ->
  nml ((gO g, gZ g, gC g + gC g2) :: t2) = true.
Proof.
  intros [[a b] c] [[a2 b2] c2] t2 Hs Hn.
  cbn [gO gZ gC] in *.
  apply andb_prop in Hs. destruct Hs as [H1 H2].
  apply N.eqb_eq in H1. apply N.eqb_eq in H2. subst a2 b2.
  destruct t2 as [|g3 t2']; [reflexivity|].
  cbn [nml] in Hn |- *. exact Hn.
Qed.
Lemma nml_normalize : forall w, nml (normalize w) = true.
Proof.
  induction w as [|g t IH]; cbn [normalize]; [reflexivity|].
  destruct (normalize t) as [|g2 t2] eqn:E; [reflexivity|].
  try rewrite E in IH.
  destruct ((gO g =? gO g2) && (gZ g =? gZ g2)) eqn:Es.
  - exact (nml_cons_merged g g2 t2 Es IH).
  - cbn [nml]. unfold samez. rewrite Es. cbn [negb andb]. exact IH.
Qed.
Lemma nml_nmerge : forall a b,
  nml a = true -> nml b = true -> nml (nmerge a b) = true.
Proof.
  induction a as [|g t IH]; intros b Ha Hb; cbn [nmerge]; [exact Hb|].
  assert (Ht : nml (nmerge t b) = true)
    by (apply IH; [exact (nml_cons_inv _ _ Ha)|exact Hb]).
  destruct (nmerge t b) as [|g2 t2] eqn:E; [reflexivity|].
  try rewrite E in Ht.
  destruct ((gO g =? gO g2) && (gZ g =? gZ g2)) eqn:Es.
  - exact (nml_cons_merged g g2 t2 Es Ht).
  - cbn [nml]. unfold samez. rewrite Es. cbn [negb andb]. exact Ht.
Qed.
Lemma nml_app : forall a b,
  nml a = true -> nml b = true -> nojunc a b = true -> nml (a ++ b) = true.
Proof.
  intros a b Ha Hb Hj.
  rewrite <- (nmerge_no_merge a b Ha Hj). exact (nml_nmerge a b Ha Hb).
Qed.
Lemma nml_cons2 : forall g g2 t,
  nml (g :: g2 :: t) = negb (samez g g2) && nml (g2 :: t).
Proof. reflexivity. Qed.
Lemma nml_app_inv : forall a b, nml (a ++ b) = true -> nml a = true /\ nml b = true.
Proof.
  induction a as [|g t IH]; intros b H; cbn [app] in H.
  - split; [reflexivity|exact H].
  - destruct t as [|g1 t'].
    + cbn [app] in H. split; [reflexivity|].
      destruct b as [|g2 b']; [reflexivity|].
      rewrite nml_cons2 in H.
      apply andb_prop in H. destruct H as [_ H]. exact H.
    + cbn [app] in H.
      rewrite nml_cons2 in H.
      apply andb_prop in H. destruct H as [H1 H2].
      change (g1 :: (t' ++ b)) with ((g1 :: t') ++ b) in H2.
      specialize (IH b H2). destruct IH as [I1 I2].
      split; [| exact I2].
      rewrite nml_cons2, H1, I1. reflexivity.
Qed.
Lemma nml_head_count : forall o z c c' t,
  nml ((o,z,c) :: t) = nml ((o,z,c') :: t).
Proof. intros o z c c' [|g t]; reflexivity. Qed.
Definition isact (g : bg) : bool := (gZ g =? 1) || (3 <=? gZ g).
Lemma is_col_not_act : forall g, is_col g = true -> isact g = false.
Proof.
  intros [[o z] c] H. unfold is_col, isact, gZ, gO in *.
  cbn in *. apply andb_prop in H. destruct H as [H _].
  apply N.eqb_eq in H. subst z. reflexivity.
Qed.
Lemma GenerationFast_forallb_skipn : forall (p : bg -> bool) n l,
  forallb p l = true -> forallb p (skipn n l) = true.
Proof.
  intros p n l H. rewrite <- (firstn_skipn n l) in H.
  rewrite forallb_app in H. apply andb_prop in H. destruct H as [_ H]. exact H.
Qed.
Lemma find_active_s_app : forall l g t i,
  forallb is_col l = true -> isact g = true ->
  find_active_s (l ++ g :: t) i = Some (i + length l)%nat.
Proof.
  induction l as [|c l' IH]; intros g t i Hc Ha; cbn [app length].
  - cbn [find_active_s]. unfold isact in Ha. rewrite Ha.
    f_equal. lia.
  - cbn [forallb] in Hc. apply andb_prop in Hc. destruct Hc as [Hc1 Hc2].
    pose proof (is_col_not_act c Hc1) as E. unfold isact in E.
    cbn [find_active_s]. rewrite E.
    rewrite (IH g t (S i) Hc2 Ha). f_equal. cbn [length]. lia.
Qed.
Lemma find_active_split : forall pre g t i,
  forallb is_col pre = true -> isact g = true -> (i <= length pre)%nat ->
  find_active (pre ++ g :: t) i = Some (length pre).
Proof.
  intros pre g t i Hc Ha Hi. unfold find_active.
  rewrite skipn_app.
  replace (i - length pre)%nat with O by lia. cbn [skipn].
  rewrite (find_active_s_app (skipn i pre) g t i (GenerationFast_forallb_skipn _ i _ Hc) Ha).
  rewrite skipn_length. f_equal. lia.
Qed.
Lemma nth_error_skipn' : forall n (l : word) i,
  nth_error (skipn n l) i = nth_error l (n + i).
Proof.
  induction n as [|n IH]; intros l i; [reflexivity|].
  destruct l as [|g l']; cbn [skipn].
  - destruct i; reflexivity.
  - cbn [Nat.add nth_error]. apply IH.
Qed.
Lemma detect_phase_skipn : forall w j,
  detect_phase w j = detect_phase (skipn j w) 0.
Proof.
  intros w j. unfold detect_phase, wat.
  rewrite !nth_error_skipn'.
  rewrite Nat.add_0_r, Nat.add_1_r. reflexivity.
Qed.
Lemma last1_cons_nonnil : forall x y u, last1 (x :: y :: u) = last1 (y :: u).
Proof. reflexivity. Qed.
Lemma last1_app_cons : forall l g t, last1 (l ++ g :: t) = last1 (g :: t).
Proof.
  induction l as [|x l IH]; intros g t; cbn [app]; [reflexivity|].
  destruct (l ++ g :: t) as [|y u] eqn:E.
  - exfalso. destruct l; cbn in E; discriminate.
  - rewrite last1_cons_nonnil, <- E. apply IH.
Qed.
Lemma last2_cons3 : forall g x y r,
  last2 (g :: x :: y :: r) =
    match last2 (x :: y :: r) with
    | Some (ini,a,b) => Some (g :: ini, a, b)
    | None => None
    end.
Proof. intros. reflexivity. Qed.
Lemma GenerationFast_last2_app : forall P Q ini a b,
  last2 Q = Some (ini,a,b) -> last2 (P ++ Q) = Some (P ++ ini, a, b).
Proof.
  induction P as [|g P' IH]; intros Q ini a b HQ; cbn [app]; [exact HQ|].
  specialize (IH Q ini a b HQ).
  destruct (P' ++ Q) as [|x [|y r]] eqn:Hr.
  - cbn in IH. discriminate.
  - cbn in IH. discriminate.
  - rewrite last2_cons3, IH. cbn [app]. reflexivity.
Qed.
Ltac ez := cbv beta iota; rewrite <- ?app_assoc; reflexivity.
Lemma jump_seg_app : forall P Q B ini a b,
  last2 Q = Some (ini,a,b) ->
  jump_seg (P ++ Q) B =
    match jump_seg Q B with Some r => Some (P ++ r) | None => None end.
Proof.
  intros P Q B ini a b HQ.
  destruct a as [[gao gaz] gac]. destruct b as [[gbo gbz] gbc].
  unfold jump_seg. rewrite HQ, (GenerationFast_last2_app P Q _ _ _ HQ).
  cbv beta iota.
  destruct ((gao =? 8) && (gaz =? 2) && (gac =? 1) && (gbo =? 4) && (gbz =? 2)
            && (1 <=? gbc)); [ez|].
  destruct ((gbo =? 8) && (gbz =? 2) && (gbc =? 1)); ez.
Qed.
Lemma lawR_seg_app : forall P Q B ini a b,
  last2 Q = Some (ini,a,b) ->
  lawR_seg (P ++ Q) B =
    match lawR_seg Q B with Some r => Some (P ++ r) | None => None end.
Proof.
  intros P Q B ini a b HQ.
  destruct a as [[gao gaz] gac]. destruct b as [[gbo gbz] gbc].
  unfold lawR_seg. rewrite HQ, (GenerationFast_last2_app P Q _ _ _ HQ).
  cbv beta iota.
  destruct ((gao =? 8) && (gaz =? 2) && (gac =? 1) && (gbo =? 4) && (gbz =? 2)
            && (1 <=? gbc)); [ez|].
  destruct ((gbo =? 8) && (gbz =? 2) && (gbc =? 1)); ez.
Qed.
Ltac dfire := match goal with
  | |- context [fire_comp ?n ?s ?ff] =>
      destruct (fire_comp n s ff) as [[s3' f2]|] end.
Ltac dleaf := match goal with
  | |- context [leaf_act ?s ?ff] =>
      destruct (leaf_act s ff) as [[s3' f2]|] end.
Ltac dsand := match goal with
  | |- context [sand_leaf ?s] => destruct (sand_leaf s) end.
Ltac ddtb := match goal with
  | |- context [dtb4_conv ?s] => destruct (dtb4_conv s) as [cols2'|] end.
Ltac dw42 := match goal with
  | |- context [forallb w42 ?s] => destruct (forallb w42 s) end.
Ltac dren := match goal with
  | |- context [renew_seg ?n ?c ?s ?ff] =>
      destruct (renew_seg n c s ff) as [[body f2]|] end.
Lemma jump_comp_app : forall P Q B post f ini a b,
  last2 Q = Some (ini,a,b) ->
  jump_comp (P ++ Q) B post f =
    match jump_comp Q B post f with
    | Some (kd, body, f') => Some (kd, P ++ body, f')
    | None => None
    end.
Proof.
  intros P Q B post f ini a b HQ.
  unfold jump_comp.
  destruct post as [|pg pt].
  - destruct (f =? 4).
    + rewrite (lawR_seg_app P Q B ini a b HQ).
      destruct (lawR_seg Q B) as [body|]; ez.
    + destruct (5 <=? f); [|ez].
      rewrite (jump_seg_app P Q B ini a b HQ).
      destruct (jump_seg Q B) as [segp0|]; ez.
  - rewrite (jump_seg_app P Q B ini a b HQ).
    destruct (jump_seg Q B) as [segp0|]; [|ez].
    cbv beta iota.
    destruct (seek (pg :: pt)) as [cols2 s3].
    cbv beta iota.
    dren; [ez|].
    cbv beta iota.
    destruct s3 as [|[[o7 z7] c7] s3t]; cbv beta iota.
    + dleaf; [ez|].
      cbv beta iota.
      destruct (5 <=? f); [ez|].
      destruct (f =? 4); [|ez].
      cbv beta iota.
      ddtb; [ez|].
      cbv beta iota.
      dw42; [|ez].
      cbv beta iota.
      rewrite (lawR_seg_app P Q B ini a b HQ).
      destruct (lawR_seg Q B) as [seg2|]; ez.
    + destruct ((z7 =? 3) && (c7 =? 1)); cbv beta iota.
      * dfire; ez.
      * dsand; cbv beta iota; [ez|].
        dleaf; ez.
Qed.
Lemma firstn_app_len : forall (l1 l2 : word), firstn (length l1) (l1 ++ l2) = l1.
Proof.
  intros. rewrite firstn_app, firstn_all, Nat.sub_diag. cbn [firstn].
  apply app_nil_r.
Qed.
Lemma skipn_app_len : forall (l1 l2 : word), skipn (length l1) (l1 ++ l2) = l2.
Proof. intros. rewrite skipn_app, skipn_all, Nat.sub_diag. reflexivity. Qed.
Definition zst : Type := (N * word * nat * word * N * nat)%type.
Definition GenerationFast_zpre (c_0 : N) (rmid : word) : word := (2,2,c_0) :: rev rmid.
Definition zstate (Z : zst) : sstate :=
  let '(c_0, rmid, _, suf, f, h) := Z in ((2,2,c_0) :: rev_append rmid suf, f, h).
Lemma zstate_eq : forall c_0 rmid j suf f h,
  zstate (c_0, rmid, j, suf, f, h) = (GenerationFast_zpre c_0 rmid ++ suf, f, h).
Proof.
  intros. cbn [zstate]. unfold GenerationFast_zpre. rewrite rev_append_rev. reflexivity.
Qed.
Definition ZInv (Z : zst) : Prop :=
  let '(c_0, rmid, j, suf, f, h) := Z in
  j = S (length rmid) /\
  (6 <= j)%nat /\ (h <= j)%nat /\
  1 <= c_0 /\
  forallb is_col (GenerationFast_zpre c_0 rmid) = true /\
  nml (GenerationFast_zpre c_0 rmid ++ suf) = true /\
  (match suf with g :: _ => isact g = true | [] => False end).
Lemma zpre_len : forall c_0 rmid, length (GenerationFast_zpre c_0 rmid) = S (length rmid).
Proof. intros. unfold GenerationFast_zpre. cbn [length]. rewrite rev_length. reflexivity. Qed.
Lemma zlast1 : forall c_0 rmid,
  last1 (GenerationFast_zpre c_0 rmid) =
  Some (match rmid with [] => (2,2,c_0) | r :: _ => r end).
Proof.
  intros c_0 [|r rm]; unfold GenerationFast_zpre; cbn [rev].
  - reflexivity.
  - replace ((2,2,c_0) :: (rev rm ++ [r])) with (((2,2,c_0) :: rev rm) ++ r :: nil)
      by (cbn [app]; reflexivity).
    rewrite last1_app_cons. reflexivity.
Qed.
Lemma closed_tick_split : forall c_0 rmid j suf f h,
  j = S (length rmid) -> (6 <= j)%nat -> (h <= j)%nat -> 1 <= c_0 ->
  forallb is_col (GenerationFast_zpre c_0 rmid) = true ->
  (match suf with g :: _ => isact g = true | [] => False end) ->
  closed_tick (GenerationFast_zpre c_0 rmid ++ suf, f, h) =
  (if last_ok (GenerationFast_zpre c_0 rmid) then
   match detect_phase suf 0 with
   | None => None
   | Some p =>
     if p <? 28 then
     if word_eqb (firstn (length (phase_form p)) suf)
                            (phase_form p) then
     match skipn (length (phase_form p)) suf with
     | (o,z,c) :: post =>
         if (o =? 4) && (z =? 2) then
         if emits p then
           if p =? 27 then
             if 1 <=? c then
               match jump_comp (bump (GenerationFast_zpre c_0 rmid)) c post f with
               | Some (JMP, body, f') =>
                   Some (normalize body, f', next_hint j)
               | _ => None
               end
             else None
           else
             match fire_comp (length suf) suf f with
             | Some (body, f') =>
                 Some (normalize (bump (GenerationFast_zpre c_0 rmid) ++ body),
                       f', next_hint j)
             | None => None
             end
         else if 2 <=? c then
           Some (normalize (bump (GenerationFast_zpre c_0 rmid)
                  ++ phase_form (p+1)
                  ++ (4,2,(c + DBu (p+1)) - DBu p) :: post),
                 f, next_hint j)
         else None
         else None
     | [] => None
     end
     else None
     else None
   end
   else None).
Proof.
  intros c_0 rmid j suf f h Hj H6 Hhj Hc0 Hcol Hact.
  destruct suf as [|g0 sufT]; [contradiction|].
  assert (Hlen : length (GenerationFast_zpre c_0 rmid) = j) by (rewrite zpre_len; lia).
  assert (Hfa : find_active (GenerationFast_zpre c_0 rmid ++ g0 :: sufT)
                  (if Nat.ltb h 1 then 1%nat else h) = Some j).
  { rewrite <- Hlen. apply find_active_split; [exact Hcol|exact Hact|].
    rewrite Hlen. destruct (Nat.ltb h 1); lia. }
  assert (Hf : firstn j (GenerationFast_zpre c_0 rmid ++ g0 :: sufT) = GenerationFast_zpre c_0 rmid).
  { rewrite <- Hlen. apply firstn_app_len. }
  assert (Hs : skipn j (GenerationFast_zpre c_0 rmid ++ g0 :: sufT) = g0 :: sufT).
  { rewrite <- Hlen. apply skipn_app_len. }
  unfold closed_tick.
  cbv beta iota zeta.
  rewrite Hfa. cbv beta iota zeta.
  rewrite Hf, Hs.
  unfold GenerationFast_zpre at 1. cbv beta iota zeta.
  rewrite N.eqb_refl. cbn [andb].
  replace (1 <=? c_0) with true by (symmetry; apply N.leb_le; exact Hc0).
  cbn [andb].
  rewrite Hlen.
  replace (Nat.leb 6 j) with true by (symmetry; apply Nat.leb_le; exact H6).
  replace (Nat.leb h j) with true by (symmetry; apply Nat.leb_le; exact Hhj).
  fold (GenerationFast_zpre c_0 rmid). rewrite Hcol.
  rewrite (detect_phase_skipn (GenerationFast_zpre c_0 rmid ++ g0 :: sufT) j), Hs.
  reflexivity.
Qed.
Definition zlast (c_0 : N) (rmid : word) : bg :=
  match rmid with [] => (2,2,c_0) | r :: _ => r end.
Definition zlast_ok (c_0 : N) (rmid : word) : bool :=
  let g := zlast c_0 rmid in (3 <=? gO g) && (1 <=? gC g).
Lemma zlast_ok_eq : forall c_0 rmid,
  last_ok (GenerationFast_zpre c_0 rmid) = zlast_ok c_0 rmid.
Proof.
  intros. unfold last_ok, zlast_ok, zlast. rewrite zlast1.
  reflexivity.
Qed.
Definition nojunc1 (g : bg) (s : word) : bool :=
  match s with g2 :: _ => negb (samez g g2) | [] => true end.
Lemma nojunc_zpre : forall c_0 rm s, nojunc (GenerationFast_zpre c_0 rm) s = nojunc1 (zlast c_0 rm) s.
Proof.
  intros. unfold nojunc, nojunc1. rewrite zlast1. destruct s; reflexivity.
Qed.
Lemma bump_zpre : forall c_0 rmid,
  bump (GenerationFast_zpre c_0 rmid) = GenerationFast_zpre (c_0+1) rmid.
Proof. intros. reflexivity. Qed.
Lemma zpre_split2 : forall c_0 ga gb rest,
  GenerationFast_zpre c_0 (ga :: gb :: rest) = GenerationFast_zpre c_0 rest ++ [gb; ga].
Proof.
  intros. unfold GenerationFast_zpre. cbn [rev app]. rewrite <- app_assoc. reflexivity.
Qed.
Fixpoint zseat_s (rm : word) (j : nat) (s : word)
  : option (word * nat * word) :=
  match s with
  | [] => None
  | g :: t =>
      if isact g then Some (rm, j, s)
      else if is_col g then zseat_s (g :: rm) (S j) t
      else None
  end.
Definition zseat (c_0 : N) (rm : word) (j : nat) (s : word)
                 (f : N) (h : nat) : option zst :=
  if nojunc1 (zlast c_0 rm) s then
    match zseat_s rm j s with
    | Some (rm2, j2, s2) =>
        if Nat.leb 6 j2 then Some (c_0, rm2, j2, s2, f, h) else None
    | None => None
    end
  else None.
Lemma zpre_col_cons : forall c_0 g rm,
  forallb is_col (GenerationFast_zpre c_0 (g :: rm)) =
  (forallb is_col (GenerationFast_zpre c_0 rm) && is_col g)%bool.
Proof.
  intros. unfold GenerationFast_zpre. cbn [rev forallb].
  rewrite forallb_app. cbn [forallb].
  destruct (is_col (2,2,c_0)), (forallb is_col (rev rm)),
           (is_col g); reflexivity.
Qed.
Lemma zseat_s_ok : forall s c_0 rm j rm2 j2 s2,
  zseat_s rm j s = Some (rm2, j2, s2) ->
  j = S (length rm) ->
  forallb is_col (GenerationFast_zpre c_0 rm) = true ->
  rev rm ++ s = rev rm2 ++ s2 /\
  j2 = S (length rm2) /\
  (j <= j2)%nat /\
  forallb is_col (GenerationFast_zpre c_0 rm2) = true /\
  (match s2 with g :: _ => isact g = true | [] => False end).
Proof.
  induction s as [|g t IH]; intros c_0 rm j rm2 j2 s2 H Hj Hcol;
    cbn [zseat_s] in H; [discriminate|].
  destruct (isact g) eqn:Ea.
  - inversion H; subst rm2 j2 s2.
    repeat split; try reflexivity; try lia; assumption.
  - destruct (is_col g) eqn:Ec; [|discriminate].
    assert (Hj2 : S j = S (length (g :: rm))) by (cbn [length]; lia).
    assert (Hc2 : forallb is_col (GenerationFast_zpre c_0 (g :: rm)) = true)
      by (rewrite zpre_col_cons, Hcol, Ec; reflexivity).
    specialize (IH c_0 (g :: rm) (S j) rm2 j2 s2 H Hj2 Hc2).
    destruct IH as (E1 & E2 & E3 & E4 & E5).
    repeat split; try assumption; try lia.
    cbn [rev] in E1. rewrite <- app_assoc in E1. cbn [app] in E1. exact E1.
Qed.
Lemma zseat_junc : forall c_0 rm j s f h Z',
  zseat c_0 rm j s f h = Some Z' -> nojunc1 (zlast c_0 rm) s = true.
Proof.
  intros c_0 rm j s f h Z' H. unfold zseat in H.
  destruct (nojunc1 (zlast c_0 rm) s); [reflexivity|discriminate].
Qed.
Lemma zseat_ok : forall c_0 rm j s f h Z',
  zseat c_0 rm j s f h = Some Z' ->
  j = S (length rm) -> 1 <= c_0 ->
  forallb is_col (GenerationFast_zpre c_0 rm) = true ->
  nml (GenerationFast_zpre c_0 rm) = true -> nml s = true -> (h <= j)%nat ->
  zstate Z' = (GenerationFast_zpre c_0 rm ++ s, f, h) /\ ZInv Z'.
Proof.
  intros c_0 rm j s f h Z' H Hj Hc0 Hcol Hnp Hns Hhj.
  unfold zseat in H.
  destruct (nojunc1 (zlast c_0 rm) s) eqn:EJ; [|discriminate].
  destruct (zseat_s rm j s) as [[[rm2 j2] s2]|] eqn:ES; [|discriminate].
  destruct (Nat.leb 6 j2) eqn:E6; [|discriminate].
  inversion H; subst Z'.
  destruct (zseat_s_ok s c_0 rm j rm2 j2 s2 ES Hj Hcol)
    as (E1 & E2 & E3 & E4 & E5).
  assert (Hw : GenerationFast_zpre c_0 rm2 ++ s2 = GenerationFast_zpre c_0 rm ++ s).
  { unfold GenerationFast_zpre. cbn [app]. rewrite <- E1. reflexivity. }
  assert (Hn : nml (GenerationFast_zpre c_0 rm ++ s) = true).
  { apply nml_app; [exact Hnp|exact Hns|rewrite nojunc_zpre; exact EJ]. }
  split.
  - rewrite zstate_eq, Hw. reflexivity.
  - cbn [ZInv]. repeat split; try assumption.
    + apply Nat.leb_le. exact E6.
    + lia.
    + rewrite Hw. exact Hn.
Qed.
Lemma normalize_prefix : forall P body,
  nml P = true -> nojunc P (normalize body) = true ->
  normalize (P ++ body) = P ++ normalize body.
Proof. intros. rewrite normalize_app. apply nmerge_no_merge; assumption. Qed.
Lemma normalize_prefix_local : forall P X post,
  nml P = true -> nml post = true -> nojunc P (nmerge X post) = true ->
  normalize (P ++ X ++ post) = P ++ nmerge X post.
Proof.
  intros P X post HP Hpost Hj.
  rewrite normalize_app, normalize_app, (nml_normalize_id post Hpost).
  apply nmerge_no_merge; assumption.
Qed.
Lemma app_cons_split : forall (A B : word) g, (A ++ [g]) ++ B = A ++ g :: B.
Proof. intros. rewrite <- app_assoc. reflexivity. Qed.
Lemma normalize_prefix_local' : forall P A g post,
  nml P = true -> nml post = true ->
  nojunc P (nmerge (A ++ [g]) post) = true ->
  normalize (P ++ A ++ g :: post) = P ++ nmerge (A ++ [g]) post.
Proof.
  intros P A g post HP Hpost Hj.
  rewrite <- (app_cons_split A post g).
  apply normalize_prefix_local; assumption.
Qed.
Lemma zpre_col_c : forall c c' rm,
  forallb is_col (GenerationFast_zpre c rm) = forallb is_col (GenerationFast_zpre c' rm).
Proof. intros. unfold GenerationFast_zpre, is_col, gZ, gO. cbn. reflexivity. Qed.
Lemma zpre_nml_c : forall c c' rm, nml (GenerationFast_zpre c rm) = nml (GenerationFast_zpre c' rm).
Proof. intros. unfold GenerationFast_zpre. apply nml_head_count. Qed.
Lemma nml_skipn : forall k w, nml w = true -> nml (skipn k w) = true.
Proof.
  intros k w H. rewrite <- (firstn_skipn k w) in H.
  destruct (nml_app_inv _ _ H) as [_ A]. exact A.
Qed.
Definition ztick (Z : zst) : option zst :=
  let '(c_0, rmid, j, suf, f, h) := Z in
  if zlast_ok c_0 rmid then
  match detect_phase suf 0 with
  | None => None
  | Some p =>
    if p <? 28 then
    if word_eqb (firstn (length (phase_form p)) suf)
                           (phase_form p) then
    match skipn (length (phase_form p)) suf with
    | (o,z,c) :: post =>
        if (o =? 4) && (z =? 2) then
        if emits p then
          if p =? 27 then
            if 1 <=? c then
              match rmid with
              | ga :: gb :: rest =>
                  match jump_comp [gb; ga] c post f with
                  | Some (JMP, body, f') =>
                      zseat (c_0+1) rest (j-2)%nat (normalize body) f'
                            (next_hint j)
                  | _ => None
                  end
              | _ => None
              end
            else None
          else
            match fire_comp (length suf) suf f with
            | Some (body, f') =>
                zseat (c_0+1) rmid j (normalize body) f'
                      (next_hint j)
            | None => None
            end
        else if 2 <=? c then
          (if nml (phase_form (p+1)
                   ++ [(4,2,(c + DBu (p+1)) - DBu p)])
           then zseat (c_0+1) rmid j
                  (nmerge (phase_form (p+1)
                           ++ [(4,2,(c + DBu (p+1))
                                      - DBu p)]) post)
                  f (next_hint j)
           else None)
        else None
        else None
    | [] => None
    end
    else None
    else None
  end
  else None.
Lemma ztick_ok : forall Z Z',
  ZInv Z -> ztick Z = Some Z' ->
  closed_tick (zstate Z) = Some (zstate Z') /\ ZInv Z'.
Proof.
  intros [[[[[c_0 rmid] j] suf] f] h] Z' HI HT.
  cbn [ZInv] in HI.
  destruct HI as (Hj & H6 & Hhj & Hc0 & Hcol & Hnml & Hact).
  assert (Hnp : nml (GenerationFast_zpre c_0 rmid) = true)
    by (destruct (nml_app_inv _ _ Hnml) as [A _]; exact A).
  assert (Hns : nml suf = true)
    by (destruct (nml_app_inv _ _ Hnml) as [_ A]; exact A).
  assert (Hh1 : (1 <= c_0 + 1)) by lia.
  rewrite zstate_eq.
  rewrite (closed_tick_split c_0 rmid j suf f h Hj H6 Hhj Hc0 Hcol Hact).
  rewrite zlast_ok_eq.
  unfold ztick in HT. cbv beta iota zeta in HT.
  destruct (zlast_ok c_0 rmid); [|discriminate].
  destruct (detect_phase suf 0) as [p|]; [|discriminate].
  destruct (p <? 28); [|discriminate].
  destruct (word_eqb (firstn (length (phase_form p)) suf)
                                (phase_form p)); [|discriminate].
  destruct (skipn (length (phase_form p)) suf)
    as [|[[o z] c] post] eqn:Esk; [discriminate|].
  assert (Hpost : nml post = true).
  { pose proof (nml_skipn (length (phase_form p)) suf Hns) as A.
    rewrite Esk in A. exact (nml_cons_inv _ _ A). }
  destruct ((o =? 4) && (z =? 2)); [|discriminate].
  destruct (emits p).
  - destruct (p =? 27).
    + destruct (1 <=? c); [|discriminate].
      destruct rmid as [|ga [|gb rest]]; try discriminate.
      rewrite bump_zpre, zpre_split2.
      rewrite (jump_comp_app (GenerationFast_zpre (c_0+1) rest) [gb;ga] c post f [] gb ga eq_refl).
      destruct (jump_comp [gb;ga] c post f) as [[[kd body] f']|];
        [|discriminate].
      destruct kd; try discriminate.
      cbv beta iota in *.
      assert (Hj2 : (j - 2)%nat = S (length rest)) by (cbn [length] in Hj; lia).
      assert (Hc2 : forallb is_col (GenerationFast_zpre (c_0+1) rest) = true).
      { rewrite (zpre_col_c (c_0+1) c_0 rest).
        rewrite zpre_split2, forallb_app in Hcol.
        apply andb_prop in Hcol. destruct Hcol as [A _]. exact A. }
      assert (Hn2 : nml (GenerationFast_zpre (c_0+1) rest) = true).
      { rewrite (zpre_nml_c (c_0+1) c_0 rest).
        rewrite zpre_split2 in Hnp.
        destruct (nml_app_inv _ _ Hnp) as [A _]. exact A. }
      assert (Hhn : (next_hint j <= j - 2)%nat).
      { unfold next_hint. destruct (Nat.ltb j 5); lia. }
      destruct (zseat_ok (c_0+1) rest (j-2)%nat (normalize body) f'
                  (next_hint j) Z' HT Hj2 Hh1 Hc2 Hn2
                  (nml_normalize body) Hhn) as [Hz Hi].
      split; [|exact Hi].
      rewrite Hz. repeat f_equal.
      apply normalize_prefix; [exact Hn2|].
      rewrite nojunc_zpre. exact (zseat_junc _ _ _ _ _ _ _ HT).
    + destruct (fire_comp (length suf) suf f) as [[body f']|];
        [|discriminate].
      rewrite bump_zpre.
      assert (Hc2 : forallb is_col (GenerationFast_zpre (c_0+1) rmid) = true)
        by (rewrite (zpre_col_c (c_0+1) c_0 rmid); exact Hcol).
      assert (Hn2 : nml (GenerationFast_zpre (c_0+1) rmid) = true)
        by (rewrite (zpre_nml_c (c_0+1) c_0 rmid); exact Hnp).
      assert (Hhn : (next_hint j <= j)%nat).
      { unfold next_hint. destruct (Nat.ltb j 5); lia. }
      destruct (zseat_ok (c_0+1) rmid j (normalize body) f'
                  (next_hint j) Z' HT Hj Hh1 Hc2 Hn2
                  (nml_normalize body) Hhn) as [Hz Hi].
      split; [|exact Hi].
      rewrite Hz. repeat f_equal.
      apply normalize_prefix; [exact Hn2|].
      rewrite nojunc_zpre. exact (zseat_junc _ _ _ _ _ _ _ HT).
  - destruct (2 <=? c); [|discriminate].
    destruct (nml (phase_form (p+1)
                   ++ [(4,2,(c + DBu (p+1)) - DBu p)]))
      eqn:EX; [|discriminate].
    rewrite bump_zpre.
    assert (Hc2 : forallb is_col (GenerationFast_zpre (c_0+1) rmid) = true)
      by (rewrite (zpre_col_c (c_0+1) c_0 rmid); exact Hcol).
    assert (Hn2 : nml (GenerationFast_zpre (c_0+1) rmid) = true)
      by (rewrite (zpre_nml_c (c_0+1) c_0 rmid); exact Hnp).
    assert (Hhn : (next_hint j <= j)%nat).
    { unfold next_hint. destruct (Nat.ltb j 5); lia. }
    destruct (zseat_ok (c_0+1) rmid j
                (nmerge (phase_form (p+1)
                         ++ [(4,2,(c + DBu (p+1))
                                    - DBu p)]) post)
                f (next_hint j) Z' HT Hj Hh1 Hc2 Hn2
                (nml_nmerge _ _ EX Hpost) Hhn) as [Hz Hi].
    split; [|exact Hi].
    rewrite Hz. repeat f_equal.
    apply normalize_prefix_local'; [exact Hn2|exact Hpost|].
    rewrite nojunc_zpre. exact (zseat_junc _ _ _ _ _ _ _ HT).
Qed.
Fixpoint ztickk (k : nat) (Z : zst) : option zst :=
  match k with
  | O => Some Z
  | S k' => match ztick Z with Some Z' => ztickk k' Z' | None => None end
  end.
Lemma ztickk_ok : forall k Z Z',
  ZInv Z -> ztickk k Z = Some Z' ->
  closed_tickk k (zstate Z) = Some (zstate Z') /\ ZInv Z'.
Proof.
  induction k as [|k IH]; intros Z Z' HI HT;
    cbn [ztickk closed_tickk] in *.
  - inversion HT; subst Z'. split; [reflexivity|exact HI].
  - destruct (ztick Z) as [Z1|] eqn:E; [|discriminate].
    destruct (ztick_ok Z Z1 HI E) as [Hc Hi].
    rewrite Hc. exact (IH Z1 Z' Hi HT).
Qed.
Definition zsplit (st : sstate) : option zst :=
  let '(w, f, h) := st in
  let start := if Nat.ltb h 1 then 1%nat else h in
  match find_active w start with
  | None => None
  | Some j =>
      match firstn j w, skipn j w with
      | (o0,z0,c_0) :: mid, g :: t =>
          if (o0 =? 2) && (z0 =? 2) && (1 <=? c_0) && isact g
             && Nat.eqb (S (length mid)) j && Nat.leb 6 j && Nat.leb h j
             && forallb is_col ((o0,z0,c_0) :: mid) && nml w
          then Some (c_0, rev mid, j, g :: t, f, h)
          else None
      | _, _ => None
      end
  end.
Lemma zsplit_ok : forall st Z, zsplit st = Some Z -> zstate Z = st /\ ZInv Z.
Proof.
  intros [[w f] h] Z H. unfold zsplit in H. cbv beta iota zeta in H.
  destruct (find_active w (if Nat.ltb h 1 then 1%nat else h)) as [j|];
    [|discriminate].
  destruct (firstn j w) as [|[[o0 z0] c_0] mid] eqn:EF; [discriminate|].
  destruct (skipn j w) as [|g t] eqn:ES; [discriminate|].
  destruct ((o0 =? 2) && (z0 =? 2) && (1 <=? c_0) && isact g
            && Nat.eqb (S (length mid)) j && Nat.leb 6 j && Nat.leb h j
            && forallb is_col ((o0,z0,c_0) :: mid) && nml w) eqn:EA;
    [|discriminate].
  inversion H; subst Z. clear H.
  repeat (apply andb_prop in EA; destruct EA as [EA ?]).
  match goal with H : (o0 =? 2) = true |- _ => apply N.eqb_eq in H; subst o0 end.
  match goal with H : (z0 =? 2) = true |- _ => apply N.eqb_eq in H; subst z0 end.
  assert (Hzp : GenerationFast_zpre c_0 (rev mid) = firstn j w).
  { unfold GenerationFast_zpre. rewrite rev_involutive, EF. reflexivity. }
  assert (Hw : GenerationFast_zpre c_0 (rev mid) ++ (g :: t) = w).
  { rewrite Hzp, <- ES. apply firstn_skipn. }
  split.
  - rewrite zstate_eq, Hw. reflexivity.
  - cbn [ZInv]. rewrite Hw, Hzp. repeat split.
    + rewrite rev_length.
      match goal with H : Nat.eqb (S (length mid)) j = true |- _ =>
        symmetry; apply PeanoNat.Nat.eqb_eq; exact H end.
    + match goal with H : Nat.leb 6 j = true |- _ =>
        apply Nat.leb_le; exact H end.
    + match goal with H : Nat.leb h j = true |- _ =>
        apply Nat.leb_le; exact H end.
    + match goal with H : (1 <=? c_0) = true |- _ => apply N.leb_le; exact H end.
    + rewrite EF. assumption.
    + assumption.
    + assumption.
Qed.
Definition fast_span_certificate (n : N) (st target : sstate) : bool :=
  match zsplit st with
  | Some Z =>
      match ztickk (N.to_nat n) Z with
      | Some Z' => state_eqb (zstate Z') target
      | None => false
      end
  | None => false
  end.
Theorem fast_span_certificate_sound : forall n st target,
  fast_span_certificate n st target = true ->
  stepN n st = Some target.
Proof.
  intros n st target H. unfold fast_span_certificate in H.
  destruct (zsplit st) as [Z|] eqn:EZ; [|discriminate].
  destruct (ztickk (N.to_nat n) Z) as [Z'|] eqn:ET; [|discriminate].
  apply state_eqb_true in H.
  destruct (zsplit_ok st Z EZ) as [Hst Hi].
  destruct (ztickk_ok _ _ _ Hi ET) as [Hc _].
  rewrite Hst, H in Hc.
  unfold stepN. exact (closed_tickk_sound _ _ _ Hc).
Qed.
Set Warnings "require-in-module".
Open Scope N_scope.
Open Scope bool_scope.
Open Scope list.
Definition skb2 (g : bg) : bool :=
  let '(o,z,c) := g in
  if z =? 2 then
    (if 3 <=? o then
       (if c =? 1
        then (if 5 <=? o then ((o =? 8) || (o =? 12)) else true)
        else true)
     else false)
  else false.
Lemma skb2_ok : forall g,
  skb2 g = (is_col g && negb (is_cmf g) && (3 <=? gO g))%bool.
Proof.
  intros [[o z] c].
  unfold skb2, is_col, is_cmf, gO, gZ, gC.
  destruct (N.eqb_spec z 2); [|cbn; reflexivity].
  destruct (N.leb_spec0 2 o), (N.leb_spec0 3 o), (N.leb_spec0 5 o),
           (N.eqb_spec c 1), (N.eqb_spec o 8), (N.eqb_spec o 12);
    cbn; try reflexivity; try lia.
Qed.
Fixpoint seek2 (s : word) : word * word :=
  match s with
  | g :: t => if skb2 g then let '(c, r) := seek2 t in (g :: c, r) else ([], s)
  | [] => ([], [])
  end.
Lemma seek2_ok : forall s, seek2 s = seek s.
Proof.
  induction s as [|g t IH]; [reflexivity|].
  cbn [seek2 seek]. rewrite skb2_ok.
  destruct (is_col g && negb (is_cmf g) && (3 <=? gO g));
    [rewrite IH; reflexivity | reflexivity].
Qed.
Fixpoint ff2 (n : nat) (s : word) (f : N) : option (word * N) :=
  match n with
  | O => None
  | S n' =>
    match s with
    | (X,zX,cX) :: rest0 =>
        if negb ((zX =? 3) && (cX =? 1) && (5 <=? X)) then fire_comp n s f
        else match rest0 with
             | [] => fire_comp n s f
             | (Y,zY,cY) :: rest =>
                 if negb ((Y =? 4) && (zY =? 2) && (1 <=? cY))
                 then fire_comp n s f
                 else match rest with
                      | [] => fire_comp n s f
                      | _ :: _ =>
                          let '(cols, s2) := seek2 rest in
                          match s2 with
                          | [] => fire_comp n s f
                          | (o4,z4,c4) :: _ =>
                              if (o4 =? 4) && (c4 =? 1) && ((z4 =? 3) || (z4 =? 4))
                              then fire_comp n s f
                              else
                                match ff2 n' s2 f with
                                | Some (s2', f') =>
                                    Some ((X-1,1,1) :: (7,2,1) :: (4,2,cY-1)
                                          :: cols ++ s2', f')
                                | None =>
                                    match leaf_act s2 f with
                                    | Some (s2', f') =>
                                        Some ((X-1,1,1) :: (7,2,1) :: (4,2,cY-1)
                                              :: cols ++ s2', f')
                                    | None => None
                                    end
                                end
                          end
                      end
             end
    | [] => None
    end
  end.
Theorem ff2_ok : forall n s f, ff2 n s f = fire_comp n s f.
Proof.
  induction n as [|n IH]; intros s f; [reflexivity|].
  destruct s as [|[[X zX] cX] rest0]; [reflexivity|].
  cbn [ff2].
  destruct (negb ((zX =? 3) && (cX =? 1) && (5 <=? X))) eqn:E1; [reflexivity|].
  apply negb_false_iff in E1.
  apply andb_true_iff in E1 as [E1a EX].
  apply andb_true_iff in E1a as [Ez Ec].
  apply N.eqb_eq in Ez. apply N.eqb_eq in Ec. subst zX cX.
  destruct rest0 as [|[[Y zY] cY] rest]; [reflexivity|].
  destruct (negb ((Y =? 4) && (zY =? 2) && (1 <=? cY))) eqn:E2; [reflexivity|].
  apply negb_false_iff in E2.
  apply andb_true_iff in E2 as [E2a ENL].
  apply andb_true_iff in E2a as [EY EzY].
  apply N.eqb_eq in EY. apply N.eqb_eq in EzY. subst Y zY.
  destruct rest as [|g rest]; [reflexivity|].
  rewrite seek2_ok.
  destruct (seek (g :: rest)) as [cols s2] eqn:ESK.
  destruct s2 as [|[[o4 z4] c4] s2t]; [reflexivity|].
  destruct ((o4 =? 4) && (c4 =? 1) && ((z4 =? 3) || (z4 =? 4))) eqn:E3;
    [reflexivity|].
  cbn [fire_comp].
  rewrite EX. cbn [negb].
  cbn [N.eqb Pos.eqb andb].
  rewrite ENL. cbn [negb].
  rewrite ESK.
  assert (H43 : (o4 =? 4) && (z4 =? 3) && (c4 =? 1) = false).
  { destruct (o4 =? 4), (z4 =? 3), (z4 =? 4), (c4 =? 1); cbn in E3 |- *;
      try reflexivity; discriminate. }
  assert (H44 : (o4 =? 4) && (z4 =? 4) && (c4 =? 1) = false).
  { destruct (o4 =? 4), (z4 =? 3), (z4 =? 4), (c4 =? 1); cbn in E3 |- *;
      try reflexivity; discriminate. }
  rewrite H43, H44.
  rewrite IH. reflexivity.
Qed.
Definition jump_comp2 (pre : word) (B : N) (post : word) (f : N)
  : option (ckind * word * N) :=
  match post with
  | [] => jump_comp pre B post f
  | _ :: _ =>
      match jump_seg pre B with
      | Some segp =>
          let '(cols2, s3) := seek2 post in
          match renew_seg (length s3) cols2 s3 f with
          | Some (body, f2) => Some (JMP, segp ++ body, f2)
          | None =>
              match (match s3 with
                     | (o7,z7,c7) :: _ =>
                         if (z7 =? 3) && (c7 =? 1)
                         then ff2 (length s3) s3 f
                         else if sand_leaf s3 then None
                              else leaf_act s3 f
                     | [] => leaf_act s3 f
                     end) with
              | Some (s3', f2) => Some (JMP, segp ++ cols2 ++ s3', f2)
              | None =>
                  match s3 with
                  | [] =>
                      if 5 <=? f then
                        Some (JMP, segp ++ cols2 ++ [(f-1,1,1)], 3)
                      else if f =? 4 then
                        match dtb4_conv cols2 with
                        | Some cols2' => Some (JMP, segp ++ cols2', f)
                        | None =>
                            if forallb w42 cols2 then
                              match lawR_seg pre B with
                              | Some seg2 => Some (JMP, seg2 ++ cols2, f)
                              | None => None
                              end
                            else None
                        end
                      else None
                  | _ :: _ => None
                  end
              end
          end
      | None => None
      end
  end.
Lemma jump_comp2_eq : forall pre B post f,
  jump_comp2 pre B post f = jump_comp pre B post f.
Proof.
  intros pre B post f. destruct post as [|pg pt]; [reflexivity|].
  unfold jump_comp2, jump_comp.
  destruct (jump_seg pre B) as [segp|]; [|reflexivity].
  rewrite seek2_ok.
  destruct (seek (pg :: pt)) as [cols2 s3].
  destruct s3 as [|[[o7 z7] c7] s3t]; [reflexivity|].
  rewrite ff2_ok. reflexivity.
Qed.
Definition ztick2 (Z : zst) : option zst :=
  let '(c_0, rmid, j, suf, f, h) := Z in
  if zlast_ok c_0 rmid then
  match detect_phase suf 0 with
  | None => None
  | Some p =>
    if p <? 28 then
    if word_eqb (firstn (length (phase_form p)) suf)
                           (phase_form p) then
    match skipn (length (phase_form p)) suf with
    | (o,z,c) :: post =>
        if (o =? 4) && (z =? 2) then
        if emits p then
          if p =? 27 then
            if 1 <=? c then
              match rmid with
              | ga :: gb :: rest =>
                  match jump_comp2 [gb; ga] c post f with
                  | Some (JMP, body, f') =>
                      zseat (c_0+1) rest (j-2)%nat (normalize body) f'
                            (next_hint j)
                  | _ => None
                  end
              | _ => None
              end
            else None
          else
            match ff2 (length suf) suf f with
            | Some (body, f') =>
                zseat (c_0+1) rmid j (normalize body) f'
                      (next_hint j)
            | None => None
            end
        else if 2 <=? c then
          (if nml (phase_form (p+1)
                   ++ [(4,2,(c + DBu (p+1)) - DBu p)])
           then zseat (c_0+1) rmid j
                  (nmerge (phase_form (p+1)
                           ++ [(4,2,(c + DBu (p+1))
                                      - DBu p)]) post)
                  f (next_hint j)
           else None)
        else None
        else None
    | [] => None
    end
    else None
    else None
  end
  else None.
Lemma ztick2_eq : forall Z, ztick2 Z = ztick Z.
Proof.
  intros [[[[[c_0 rmid] j] suf] f] h].
  unfold ztick2, ztick.
  destruct (zlast_ok c_0 rmid); [|reflexivity].
  destruct (detect_phase suf 0) as [p|]; [|reflexivity].
  destruct (p <? 28); [|reflexivity].
  destruct (word_eqb (firstn (length (phase_form p)) suf)
                                (phase_form p)); [|reflexivity].
  destruct (skipn (length (phase_form p)) suf) as [|[[o z] c] post];
    [reflexivity|].
  destruct ((o =? 4) && (z =? 2)); [|reflexivity].
  destruct (emits p); [|reflexivity].
  destruct (p =? 27).
  - destruct (1 <=? c); [|reflexivity].
    destruct rmid as [|ga [|gb rest]]; try reflexivity.
    rewrite jump_comp2_eq. reflexivity.
  - rewrite ff2_ok. reflexivity.
Qed.
Fixpoint ztickk2 (k : nat) (Z : zst)
  : option zst :=
  match k with
  | O => Some Z
  | S k' => match ztick2 Z with Some Z' => ztickk2 k' Z' | None => None end
  end.
Lemma ztickk2_eq : forall k Z, ztickk2 k Z = ztickk k Z.
Proof.
  induction k as [|k IH]; intros Z; [reflexivity|].
  cbn [ztickk2 ztickk].
  rewrite ztick2_eq.
  destruct (ztick Z) as [Z'|]; [apply IH|reflexivity].
Qed.
Lemma ztickk2_snoc : forall n Z Z' Z'',
  ztickk2 n Z = Some Z' -> ztick2 Z' = Some Z'' ->
  ztickk2 (S n) Z = Some Z''.
Proof.
  induction n as [|n IH]; intros Z Z' Z'' H1 H2; cbn [ztickk2] in *.
  - inversion H1; subst. rewrite H2. reflexivity.
  - destruct (ztick2 Z) as [Z1|]; [|discriminate].
    exact (IH _ _ _ H1 H2).
Qed.
Open Scope N_scope.
Open Scope bool_scope.
Definition zst3 : Type :=
  (N * word * nat * word * word * nat * word
   * N * nat)%type.
Definition to2 (Z : zst3) : zst :=
  let '(c_0, rmid, j, pear, colsB, nc, bot, f, h) := Z in
  (c_0, rmid, j, pear ++ colsB ++ bot, f, h).
Definition botfree (bot : word) : bool :=
  match bot with
  | [] => true
  | g :: _ => negb (skb2 g)
  end.
Definition Z3Inv (Z : zst3) : Prop :=
  let '(c_0, rmid, j, pear, colsB, nc, bot, f, h) := Z in
  (2 <= length pear)%nat /\
  forallb skb2 colsB = true /\
  botfree bot = true /\
  nc = length colsB /\
  nml (pear ++ colsB ++ bot) = true.
Definition split3 (Z : zst) : option zst3 :=
  let '(c_0, rmid, j, suf, f, h) := Z in
  match detect_phase suf 0 with
  | None => None
  | Some p =>
      let n := length (phase_form p) in
      match firstn n suf, skipn n suf with
      | pf, g :: rest =>
          let '(cols, bt) := seek2 rest in
          Some (c_0, rmid, j, pf ++ [g], cols, length cols, bt, f, h)
      | _, [] => None
      end
  end.
Lemma skb2_z2 : forall g, skb2 g = true -> gZ g = 2.
Proof.
  intros [[o z] c] H. unfold skb2 in H. cbn [gZ].
  destruct (N.eqb_spec z 2); [exact e|discriminate].
Qed.
Lemma seek2_split : forall rest cols bt,
  seek2 rest = (cols, bt) ->
  rest = cols ++ bt /\
  forallb skb2 cols = true /\
  botfree bt = true.
Proof.
  induction rest as [|g t IH]; intros cols bt Hs;
    cbn [seek2] in Hs.
  - inversion Hs; subst. cbn. auto.
  - destruct (skb2 g) eqn:Eg.
    + destruct (seek2 t) as [c r] eqn:Es.
      inversion Hs; subst cols bt.
      destruct (IH c r eq_refl) as (H1 & H2 & H3).
      cbn [app forallb]. rewrite Eg, H2. rewrite H1 at 1. auto.
    + inversion Hs; subst cols bt.
      cbn [forallb]. unfold botfree. rewrite Eg. cbn. auto.
Qed.
Lemma seek2_app : forall a b,
  forallb skb2 a = true ->
  botfree b = true ->
  seek2 (a ++ b) = (a, b).
Proof.
  induction a as [|g t IH]; intros b Ha Hb; cbn [app].
  - destruct b as [|gb bt]; [reflexivity|].
    unfold botfree in Hb. apply negb_true_iff in Hb.
    cbn [seek2]. rewrite Hb. reflexivity.
  - cbn [forallb] in Ha. apply andb_prop in Ha. destruct Ha as [Hg Ht].
    cbn [seek2]. rewrite Hg, (IH b Ht Hb). reflexivity.
Qed.
Lemma GenerationJump_nml_skipn : forall n w,
  nml w = true -> nml (skipn n w) = true.
Proof.
  induction n as [|n IH]; intros w H; [exact H|].
  destruct w as [|g t]; [reflexivity|].
  cbn [skipn]. apply IH.
  exact (nml_cons_inv _ _ H).
Qed.
Lemma normalize_head_oz : forall g t,
  exists c' t', normalize (g :: t) = (gO g, gZ g, c') :: t'.
Proof.
  intros [[o z] c] t. rewrite normalize_nmerge.
  cbn [nmerge].
  destruct (nmerge t []) as [|[[o2 z2] c2] t2].
  - do 2 eexists. cbn [gO gZ]. reflexivity.
  - cbn [gO gZ].
    destruct ((o =? o2) && (z =? z2)); do 2 eexists; reflexivity.
Qed.
Lemma wat_app_lt : forall w x k,
  (k < length w)%nat -> wat (w ++ x) k = wat w k.
Proof.
  induction w as [|g t IH]; intros x k Hk; cbn [app].
  - cbn in Hk. lia.
  - destruct k as [|k]; [reflexivity|].
    unfold wat in *. cbn [nth_error]. cbn in Hk. apply IH. lia.
Qed.
Lemma detect_phase_app : forall w x,
  (2 <= length w)%nat ->
  detect_phase (w ++ x) 0 = detect_phase w 0.
Proof.
  intros w x Hw. unfold detect_phase.
  rewrite (wat_app_lt w x 0) by lia.
  rewrite (wat_app_lt w x 1) by lia.
  reflexivity.
Qed.
Lemma GenerationJump_firstn_app_le : forall n (w x : word),
  (n <= length w)%nat -> firstn n (w ++ x) = firstn n w.
Proof.
  intros. rewrite firstn_app.
  replace (n - length w)%nat with O by lia.
  cbn [firstn]. apply app_nil_r.
Qed.
Lemma skipn_app_le : forall n (w x : word),
  (n <= length w)%nat -> skipn n (w ++ x) = skipn n w ++ x.
Proof.
  intros. rewrite skipn_app.
  replace (n - length w)%nat with O by lia.
  reflexivity.
Qed.
Definition headz_not2 (w : word) : bool :=
  match w with
  | (_, z, _) :: _ => negb (z =? 2)
  | [] => true
  end.
Definition head_no_merge (g : bg) (w : word) : bool :=
  match w with
  | (o2, z2, _) :: _ =>
      negb ((gO g =? o2) && (gZ g =? z2))
  | [] => true
  end.
Definition zsuf (Z : zst) : word :=
  let '(_, _, _, suf, _, _) := Z in suf.
Definition tick3_slow (Z : zst3) : option zst3 :=
  match ztick2 (to2 Z) with
  | Some Z2 => split3 Z2
  | None => None
  end.
Definition tick3 (Z : zst3) : option zst3 :=
  let '(c_0, rmid, j, pear, colsB, nc, bot, f, h) := Z in
  if negb (zlast_ok c_0 rmid) then None else
  match detect_phase pear 0 with
  | None => None
  | Some p =>
    if negb (p <? 28) then None else
    let pf := phase_form p in
    if negb (word_eqb (firstn (length pf) pear) pf) then None
    else
    match skipn (length pf) pear with
    | (o,z,c) :: pear_rest =>
        if negb ((o =? 4) && (z =? 2)) then None else
        match pear_rest with
        | _ :: _ => tick3_slow (c_0, rmid, j, pear, colsB, nc, bot, f, h)
        | [] =>
        if emits p then
          if p =? 27 then
            tick3_slow (c_0, rmid, j, pear, colsB, nc, bot, f, h)
          else
            match pear with
            | (X,_,_) :: _ =>
                if negb (Nat.eqb (length pear) 2) then
                  tick3_slow (c_0, rmid, j, pear, colsB, nc, bot, f, h)
                else if negb (5 <=? X) then
                  tick3_slow (c_0, rmid, j, pear, colsB, nc, bot, f, h)
                else if negb (1 <=? c) then
                  tick3_slow (c_0, rmid, j, pear, colsB, nc, bot, f, h)
                else
                match colsB with
                | [] => tick3_slow (c_0, rmid, j, pear, colsB, nc, bot, f, h)
                | gc :: _ =>
                match bot with
                | (o4,z4,c4) :: _ =>
                    if (o4 =? 4) && (c4 =? 1) && ((z4 =? 3) || (z4 =? 4))
                    then tick3_slow (c_0, rmid, j, pear, colsB, nc, bot, f, h)
                    else
                      match (match ff2
                                     (S (length bot + nc)) bot f with
                             | Some r => Some r
                             | None => leaf_act bot f
                             end) with
                      | Some (s2', f2) =>
                          if headz_not2 s2'
                             && head_no_merge (4,2,c-1) colsB
                             && nojunc1
                                  (zlast (c_0+1) rmid)
                                  [(X-1,1,1)]
                             && Nat.leb 6 j
                          then Some (c_0+1, rmid, j,
                                     [(X-1,1,1); (7,2,1); (4,2,c-1)],
                                     colsB, nc, normalize s2', f2,
                                     next_hint j)
                          else tick3_slow
                                 (c_0, rmid, j, pear, colsB, nc, bot, f, h)
                      | None =>
                          tick3_slow (c_0, rmid, j, pear, colsB, nc, bot, f, h)
                      end
                | [] => tick3_slow (c_0, rmid, j, pear, colsB, nc, bot, f, h)
                end
                end
            | [] => None
            end
        else if 2 <=? c then
          let pf1 := phase_form (p+1) in
          let c' := (c + DBu (p+1)) - DBu p in
          if nml (pf1 ++ [(4,2,c')]) then
            if (match colsB with
                | _ :: _ => head_no_merge (4,2,c') colsB
                | [] => head_no_merge (4,2,c') bot
                end)
               && nojunc1
                    (zlast (c_0+1) rmid)
                    (pf1 ++ [(4,2,c')])
               && Nat.leb 6 j
            then Some (c_0+1, rmid, j, pf1 ++ [(4,2,c')], colsB, nc, bot, f,
                       next_hint j)
            else tick3_slow (c_0, rmid, j, pear, colsB, nc, bot, f, h)
          else None
        else None
        end
    | [] => None
    end
  end.
Lemma zseat_s_suffix : forall s rm j rm2 j2 s2,
  zseat_s rm j s = Some (rm2, j2, s2) ->
  exists k, s2 = skipn k s.
Proof.
  induction s as [|g t IH]; intros rm j rm2 j2 s2 H;
    cbn [zseat_s] in H.
  - discriminate.
  - destruct (isact g).
    + inversion H; subst. exists O. reflexivity.
    + destruct (is_col g); [|discriminate].
      destruct (IH _ _ _ _ _ H) as [k ->]. exists (S k). reflexivity.
Qed.
Lemma zseat_suffix : forall c_0 rm j s f h Z',
  zseat c_0 rm j s f h = Some Z' ->
  exists k, zsuf Z' = skipn k s.
Proof.
  intros c_0 rm j s f h Z' H. unfold zseat in H.
  destruct (nojunc1 _ _); [|discriminate].
  destruct (zseat_s rm j s) as [[[rm2 j2] s2]|] eqn:Es;
    [|discriminate].
  destruct (Nat.leb 6 j2); [|discriminate].
  inversion H; subst. cbn [zsuf].
  exact (zseat_s_suffix _ _ _ _ _ _ Es).
Qed.
Lemma ztick2_nml : forall Z Z',
  nml (zsuf Z) = true ->
  ztick2 Z = Some Z' ->
  nml (zsuf Z') = true.
Proof.
  intros [[[[[c_0 rmid] j] suf] f] h] Z' Hn HT.
  cbn [zsuf] in Hn.
  unfold ztick2 in HT.
  repeat
    match type of HT with
    | (if ?b then _ else _) = _ => destruct b eqn:?; try discriminate
    | match ?x with _ => _ end = _ => destruct x eqn:?; try discriminate
    end.
  all: match goal with
  | HZ : zseat _ _ _ ?S _ _ = Some _ |- _ =>
      destruct (zseat_suffix _ _ _ _ _ _ _ HZ) as [k Hk];
      rewrite Hk; apply GenerationJump_nml_skipn
  end.
  all: first
    [ apply nml_normalize
    | apply nml_nmerge;
      [ assumption
      | match goal with
        | HS : skipn ?n ?SUF = ?G :: ?POST |- _ =>
            apply (nml_cons_inv G POST);
            rewrite <- HS; apply GenerationJump_nml_skipn; exact Hn
        end ] ].
Qed.
Lemma phase_form_nonnil : forall p,
  (1 <= length (phase_form p))%nat.
Proof.
  intros p. unfold phase_form.
  repeat match goal with
         | |- context [if ?b then _ else _] => destruct b
         end; cbn; lia.
Qed.
Lemma split3_ok : forall Z Z3,
  split3 Z = Some Z3 ->
  to2 Z3 = Z /\
  (nml (zsuf Z) = true -> Z3Inv Z3).
Proof.
  intros [[[[[c_0 rmid] j] suf] f] h] Z3 H. unfold split3 in H.
  destruct (detect_phase suf 0) as [p|]; [|discriminate].
  destruct (skipn (length (phase_form p)) suf) as [|g rest]
    eqn:Esk; [discriminate|].
  destruct (seek2 rest) as [cols bt] eqn:Ese.
  inversion H; subst Z3. clear H.
  destruct (seek2_split _ _ _ Ese) as (Hr & Hc & Hb).
  assert (Hre : (firstn (length (phase_form p)) suf ++ [g])
                  ++ cols ++ bt = suf).
  { rewrite <- app_assoc. cbn [app]. rewrite <- Hr, <- Esk.
    apply firstn_skipn. }
  split.
  - cbn [to2]. rewrite Hre. reflexivity.
  - intros Hn. cbn [Z3Inv].
    assert (Hlt : (length (phase_form p) < length suf)%nat).
    { pose proof (f_equal (@length _) Esk) as HL.
      rewrite skipn_length in HL. cbn [length] in HL. lia. }
    assert (Hlen : (1 <= length (firstn
              (length (phase_form p)) suf))%nat).
    { rewrite firstn_length. pose proof (phase_form_nonnil p). lia. }
    repeat split.
    + rewrite app_length. cbn [length]. lia.
    + exact Hc.
    + exact Hb.
    + rewrite Hre. exact Hn.
Qed.
Lemma tick3_slow_sim : forall Z3 Z3',
  Z3Inv Z3 ->
  tick3_slow Z3 = Some Z3' ->
  ztick2 (to2 Z3) = Some (to2 Z3') /\ Z3Inv Z3'.
Proof.
  intros Z3 Z3' HI H. unfold tick3_slow in H.
  destruct (ztick2 (to2 Z3)) as [Z2|] eqn:ET;
    [|discriminate].
  destruct (split3_ok _ _ H) as [Hto HInv].
  split; [rewrite Hto; reflexivity|].
  apply HInv.
  apply (ztick2_nml (to2 Z3) Z2); [|exact ET].
  destruct Z3 as [[[[[[[[c_0 rmid] j] pear] colsB] nc] bot] f] h].
  cbn [to2 zsuf]. destruct HI as (_ & _ & _ & _ & Hn). exact Hn.
Qed.
Lemma phase_form_emit_shape : forall p,
  emits p = true -> (p =? 27) = false ->
  exists X, phase_form p = [(X,3,1)] /\ (5 <=? X) = true.
Proof.
  intros p HE H27. unfold emits in HE.
  rewrite H27, orb_false_r in HE.
  apply orb_prop in HE. destruct HE as [HE|E19].
  - apply orb_prop in HE. destruct HE as [E3|E11].
    + apply N.eqb_eq in E3; subst p. exists 7. split; reflexivity.
    + apply N.eqb_eq in E11; subst p. exists 6. split; reflexivity.
  - apply N.eqb_eq in E19; subst p. exists 5. split; reflexivity.
Qed.
Lemma last1_snoc : forall (l : word) g,
  last1 (l ++ [g]) = Some g.
Proof. intros. rewrite last1_app_cons. reflexivity. Qed.
Lemma forallb_last1_skb2 : forall w g,
  forallb skb2 w = true ->
  last1 w = Some g -> skb2 g = true.
Proof.
  induction w as [|a t IH]; intros g Hf Hl; [discriminate|].
  cbn [forallb] in Hf. apply andb_prop in Hf. destruct Hf as [Ha Ht].
  destruct t as [|b t'].
  - cbn in Hl. inversion Hl; subst. exact Ha.
  - rewrite last1_cons2 in Hl. exact (IH _ Ht Hl).
Qed.
Lemma last1_all_skb2_z2 : forall w g,
  forallb skb2 w = true ->
  last1 w = Some g -> gZ g = 2.
Proof.
  intros w g Hf Hl. exact (skb2_z2 _ (forallb_last1_skb2 _ _ Hf Hl)).
Qed.
Lemma pear_decompose : forall pear pf c,
  word_eqb (firstn (length pf) pear) pf = true ->
  skipn (length pf) pear = [(4,2,c)] ->
  pear = pf ++ [(4,2,c)].
Proof.
  intros pear pf c He Hs.
  apply word_eqb_true in He.
  rewrite <- (firstn_skipn (length pf) pear), He, Hs. reflexivity.
Qed.
Lemma advance_sim : forall c_0 rmid j pear colsB bot f h p c,
  zlast_ok c_0 rmid = true ->
  detect_phase pear 0 = Some p ->
  (p <? 28) = true ->
  word_eqb
    (firstn (length (phase_form p)) pear)
    (phase_form p) = true ->
  skipn (length (phase_form p)) pear = [(4,2,c)] ->
  emits p = false ->
  (2 <=? c) = true ->
  nml (phase_form (p+1)
    ++ [(4,2,(c + DBu (p+1)) - DBu p)]) = true ->
  nojunc
    (phase_form (p+1)
      ++ [(4,2,(c + DBu (p+1)) - DBu p)])
    (colsB ++ bot) = true ->
  nojunc1 (zlast (c_0+1) rmid)
    (phase_form (p+1)
      ++ [(4,2,(c + DBu (p+1)) - DBu p)]) = true ->
  Nat.leb 6 j = true ->
  (2 <= length pear)%nat ->
  ztick2 (c_0, rmid, j, pear ++ colsB ++ bot, f, h)
    = Some (c_0+1, rmid, j,
        (phase_form (p+1)
          ++ [(4,2,(c + DBu (p+1)) - DBu p)])
          ++ colsB ++ bot,
        f, next_hint j).
Proof.
  intros c_0 rmid j pear colsB bot f h p c
    HZL Hdp Hp28 Heqb Hsk Hem Hc2 Hnml Hnj Hnj1 Hj6 Hp2.
  assert (Hplen : (length (phase_form p) <= length pear)%nat).
  { pose proof (f_equal (@length _) Hsk) as HL.
    rewrite skipn_length in HL. cbn [length] in HL. lia. }
  unfold ztick2.
  rewrite HZL.
  rewrite (detect_phase_app pear (colsB ++ bot) Hp2), Hdp, Hp28.
  rewrite (GenerationJump_firstn_app_le _ pear (colsB ++ bot) Hplen), Heqb.
  rewrite (skipn_app_le _ pear (colsB ++ bot) Hplen), Hsk.
  cbn [app].
  rewrite N.eqb_refl. cbn [andb].
  rewrite Hem.
  rewrite Hc2.
  rewrite Hnml.
  rewrite (nmerge_no_merge _ _ Hnml Hnj).
  unfold zseat.
  set (S3 := (phase_form (p+1)
      ++ [(4,2,(c + DBu (p+1)) - DBu p)])
      ++ colsB ++ bot).
  assert (Hhd : exists o z cg t,
      phase_form (p+1) = (o,z,cg) :: t /\
      isact (o,z,cg) = true).
  { pose proof (phase_form_nonnil (p+1)) as HN.
    destruct (phase_form (p+1)) as [|[[o z] cg] t] eqn:EF;
      [cbn in HN; lia|].
    exists o, z, cg, t. split; [reflexivity|].
    revert EF. unfold phase_form.
    repeat match goal with
           | |- context [if ?b then _ else _] => destruct b
           end; intros EF; inversion EF; subst; reflexivity.
  }
  destruct Hhd as (o & z & cg & t & Hpf & Hact).
  assert (Hnj1' : nojunc1
      (zlast (c_0+1) rmid) S3 = true).
  { unfold S3. rewrite Hpf. cbn [app].
    unfold nojunc1 in Hnj1 |- *.
    rewrite Hpf in Hnj1. cbn [app] in Hnj1. exact Hnj1. }
  rewrite Hnj1'.
  assert (Hseat : zseat_s rmid j S3 = Some (rmid, j, S3)).
  { unfold S3. rewrite Hpf. cbn [app zseat_s].
    rewrite Hact. reflexivity. }
  rewrite Hseat, Hj6.
  reflexivity.
Qed.
Lemma last1_nonnil : forall (w : word),
  w <> [] -> exists g, last1 w = Some g.
Proof.
  induction w as [|a t IH]; intros Hne; [congruence|].
  destruct t as [|b t'].
  - exists a. reflexivity.
  - destruct (IH ltac:(congruence)) as [g Hg].
    exists g. rewrite last1_cons2. exact Hg.
Qed.
Lemma nml_wrapA : forall X c,
  nml [(X-1,1,1); (7,2,1); (4,2,c-1)] = true.
Proof.
  intros X c. cbn [nml]. unfold samez.
  cbn [gO gZ].
  rewrite (proj2 (N.eqb_neq 1 2)) by discriminate.
  rewrite (proj2 (N.eqb_neq 7 4)) by discriminate.
  rewrite !andb_false_r. reflexivity.
Qed.
Lemma nojunc_colsB_norm : forall colsB s2',
  forallb skb2 colsB = true ->
  colsB <> [] ->
  headz_not2 s2' = true ->
  nojunc colsB (normalize s2') = true.
Proof.
  intros colsB s2' Hf Hne Hz.
  unfold nojunc.
  destruct (last1_nonnil colsB Hne) as [gL HgL]. rewrite HgL.
  destruct s2' as [|gh t].
  - cbn [normalize]. reflexivity.
  - destruct (normalize_head_oz gh t) as (c' & t' & ->).
    destruct gh as [[oh zh] ch].
    unfold headz_not2 in Hz. apply negb_true_iff in Hz.
    cbn [gZ] in Hz.
    pose proof (last1_all_skb2_z2 _ _ Hf HgL) as HZ2.
    destruct gL as [[oL zL] cL]. cbn [gZ] in HZ2. subst zL.
    unfold samez. cbn [gO gZ].
    rewrite (N.eqb_sym 2 zh), Hz.
    rewrite andb_false_r. reflexivity.
Qed.
Lemma normalize_wrapper : forall X c colsB s2',
  forallb skb2 colsB = true ->
  colsB <> [] ->
  head_no_merge (4,2,c-1) colsB = true ->
  headz_not2 s2' = true ->
  nml colsB = true ->
  normalize ((X-1,1,1) :: (7,2,1) :: (4,2,c-1) :: colsB ++ s2')
    = (X-1,1,1) :: (7,2,1) :: (4,2,c-1) :: (colsB ++ normalize s2').
Proof.
  intros X c colsB s2' Hf Hne Hhm Hz Hnml.
  change ((X-1,1,1) :: (7,2,1) :: (4,2,c-1) :: colsB ++ s2')
    with ([(X-1,1,1); (7,2,1); (4,2,c-1)] ++ (colsB ++ s2')).
  rewrite normalize_app.
  rewrite normalize_app.
  rewrite (nmerge_no_merge colsB _ Hnml
             (nojunc_colsB_norm _ _ Hf Hne Hz)).
  rewrite (nmerge_no_merge _ _ (nml_wrapA X c)).
  - reflexivity.
  - unfold nojunc.
    change (last1 [(X-1,1,1); (7,2,1); (4,2,c-1)])
      with (Some (4,2,c-1)).
    destruct colsB as [|gc ct]; [congruence|].
    cbn [app]. unfold head_no_merge in Hhm.
    destruct gc as [[oc zc] cc].
    unfold samez. cbn [gO gZ] in Hhm |- *.
    exact Hhm.
Qed.
Lemma ff2_step_emit : forall n X zX cX Y zY cY rest f,
  ff2 (S n) ((X,zX,cX) :: (Y,zY,cY) :: rest) f =
  if negb ((zX =? 3) && (cX =? 1) && (5 <=? X))
  then fire_comp (S n) ((X,zX,cX) :: (Y,zY,cY) :: rest) f
  else if negb ((Y =? 4) && (zY =? 2) && (1 <=? cY))
  then fire_comp (S n) ((X,zX,cX) :: (Y,zY,cY) :: rest) f
  else match rest with
       | [] => fire_comp (S n) ((X,zX,cX) :: (Y,zY,cY) :: rest) f
       | _ :: _ =>
         let '(cols, s2) := seek2 rest in
         match s2 with
         | [] => fire_comp (S n) ((X,zX,cX) :: (Y,zY,cY) :: rest) f
         | (o4,z4,c4) :: _ =>
             if (o4 =? 4) && (c4 =? 1) && ((z4 =? 3) || (z4 =? 4))
             then fire_comp (S n) ((X,zX,cX) :: (Y,zY,cY) :: rest) f
             else
               match ff2 n s2 f with
               | Some (s2', f') =>
                   Some ((X-1,1,1)::(7,2,1)::(4,2,cY-1) :: cols ++ s2', f')
               | None =>
                   match leaf_act s2 f with
                   | Some (s2', f') =>
                       Some ((X-1,1,1)::(7,2,1)::(4,2,cY-1) :: cols ++ s2',
                             f')
                   | None => None
                   end
               end
         end
       end.
Proof. reflexivity. Qed.
Lemma emit_sim : forall c_0 rmid j colsB bot f h p c X s2' f2,
  zlast_ok c_0 rmid = true ->
  detect_phase [(X,3,1); (4,2,c)] 0 = Some p ->
  (p <? 28) = true ->
  emits p = true ->
  (p =? 27) = false ->
  phase_form p = [(X,3,1)] ->
  (5 <=? X) = true ->
  (1 <=? c) = true ->
  colsB <> [] ->
  forallb skb2 colsB = true ->
  nml colsB = true ->
  botfree bot = true ->
  (match bot with
   | (o4,z4,c4) :: _ =>
       ((o4 =? 4) && (c4 =? 1) && ((z4 =? 3) || (z4 =? 4))) = false
   | [] => False
   end) ->
  (match ff2 (S (length bot + length colsB)) bot f with
   | Some r => Some r
   | None => leaf_act bot f
   end) = Some (s2', f2) ->
  headz_not2 s2' = true ->
  head_no_merge (4,2,c-1) colsB = true ->
  nojunc1 (zlast (c_0+1) rmid)
    [(X-1,1,1)] = true ->
  Nat.leb 6 j = true ->
  ztick2
    (c_0, rmid, j, [(X,3,1); (4,2,c)] ++ colsB ++ bot, f, h)
    = Some (c_0+1, rmid, j,
        (X-1,1,1) :: (7,2,1) :: (4,2,c-1) :: (colsB ++ normalize s2'),
        f2, next_hint j).
Proof.
  intros c_0 rmid j colsB bot f h p c X s2' f2
    HZL Hdp Hp28 Hem H27 Hpf HX Hc1 Hne Hskb Hnml Hbf Hbt Hff Hz2 Hhm Hnj1
    Hj6.
  unfold ztick2.
  rewrite HZL.
  cbv beta iota zeta.
  rewrite detect_phase_app by (cbn [length]; lia).
  rewrite Hdp, Hp28, Hpf.
  cbn [length firstn app].
  unfold word_eqb, bg_eqb.
  rewrite !N.eqb_refl. cbn [andb].
  cbn [skipn].
  rewrite N.eqb_refl. cbn [andb].
  rewrite Hem, H27.
  destruct colsB as [|gc cs]; [congruence|].
  destruct bot as [|[[o4 z4] c4] bt']; [contradiction|].
  cbn [length].
  rewrite ff2_step_emit.
  replace ((3 =? 3) && (1 =? 1) && (5 <=? X)) with true
    by (rewrite HX; reflexivity).
  replace ((4 =? 4) && (2 =? 2) && (1 <=? c)) with true
    by (rewrite Hc1; reflexivity).
  cbn [negb].
  cbn [app].
  change (gc :: cs ++ (o4,z4,c4) :: bt')
    with ((gc :: cs) ++ (o4,z4,c4) :: bt').
  rewrite (seek2_app (gc :: cs) ((o4,z4,c4) :: bt') Hskb Hbf).
  cbv beta iota.
  rewrite Hbt. cbv beta iota.
  match goal with
  | |- context [ff2 ?n ((o4,z4,c4) :: bt') f] =>
      replace n with
        (S (length ((o4,z4,c4) :: bt') + length (gc :: cs)))
        by (repeat rewrite app_length; cbn [length];
            apply f_equal; apply Nat.add_comm)
  end.
  change (prod (prod N N) N) with bg.
  match type of Hff with
  | match ?FFT with _ => _ end = _ =>
      revert Hff; destruct FFT as [[s2'' f'']|] eqn:EFF; intros Hff;
      cbv iota in Hff
  end.
  - injection Hff as Hs Hf; subst. cbv beta iota.
    rewrite (normalize_wrapper _ _ _ _ Hskb Hne Hhm Hz2 Hnml).
    unfold zseat.
    unfold nojunc1 in Hnj1 |- *.
    rewrite Hnj1.
    cbn [zseat_s].
    unfold isact. cbn [gZ].
    cbn [N.eqb Pos.eqb N.leb N.compare Pos.compare Pos.compare_cont orb].
    rewrite Hj6.
    reflexivity.
  - rewrite Hff. cbv beta iota.
    rewrite (normalize_wrapper _ _ _ _ Hskb Hne Hhm Hz2 Hnml).
    unfold zseat.
    unfold nojunc1 in Hnj1 |- *.
    rewrite Hnj1.
    cbn [zseat_s].
    unfold isact. cbn [gZ].
    cbn [N.eqb Pos.eqb N.leb N.compare Pos.compare Pos.compare_cont orb].
    rewrite Hj6.
    reflexivity.
Qed.
Lemma skb2_z_not2 : forall o z c,
  (z =? 2) = false -> skb2 (o,z,c) = false.
Proof.
  intros o z c Hz. unfold skb2. rewrite Hz. reflexivity.
Qed.
Lemma botfree_normalize : forall s2',
  headz_not2 s2' = true -> botfree (normalize s2') = true.
Proof.
  intros s2' Hz. destruct s2' as [|[[o z] c] t]; [reflexivity|].
  destruct (normalize_head_oz (o,z,c) t) as (c' & t' & ->).
  unfold botfree. cbn [gO gZ].
  unfold headz_not2 in Hz. apply negb_true_iff in Hz.
  cbn [gZ] in Hz.
  rewrite (skb2_z_not2 o z c' Hz). reflexivity.
Qed.
Lemma nojunc_snoc : forall (a : word) g w,
  head_no_merge g w = true ->
  nojunc (a ++ [g]) w = true.
Proof.
  intros a g w H. unfold nojunc. rewrite last1_snoc.
  destruct w as [|[[ow zw] cw] t]; [reflexivity|].
  unfold head_no_merge in H. unfold samez.
  destruct g as [[og zg] cg]. cbn [gO gZ] in H |- *. exact H.
Qed.
Lemma hnm_app : forall g (a b : word),
  a <> [] -> head_no_merge g a = true -> head_no_merge g (a ++ b) = true.
Proof.
  intros g a b Hne H. destruct a as [|ga t]; [congruence|].
  cbn [app]. exact H.
Qed.
Lemma tick3_sim : forall Z3 Z3',
  Z3Inv Z3 ->
  tick3 Z3 = Some Z3' ->
  ztick2 (to2 Z3) = Some (to2 Z3') /\ Z3Inv Z3'.
Proof.
  intros [[[[[[[[c_0 rmid] j] pear] colsB] nc] bot] f] h] Z3' HI Hrun.
  unfold tick3 in Hrun.
  destruct (negb (zlast_ok c_0 rmid)) eqn:EZL;
    [discriminate|].
  apply negb_false_iff in EZL.
  destruct (detect_phase pear 0) as [p|] eqn:EDP;
    [|discriminate].
  destruct (negb (p <? 28)) eqn:EP28; [discriminate|].
  apply negb_false_iff in EP28.
  destruct (negb (word_eqb
      (firstn (length (phase_form p)) pear)
      (phase_form p))) eqn:EWE; [discriminate|].
  apply negb_false_iff in EWE.
  destruct (skipn (length (phase_form p)) pear)
    as [|[[o z] c] pear_rest] eqn:ESK; [discriminate|].
  destruct (negb ((o =? 4) && (z =? 2))) eqn:EOZ; [discriminate|].
  apply negb_false_iff in EOZ.
  apply andb_prop in EOZ. destruct EOZ as [EO EZ].
  apply N.eqb_eq in EO. apply N.eqb_eq in EZ. subst o z.
  destruct pear_rest as [|pg pear_rest'].
  2: { exact (tick3_slow_sim _ _ HI Hrun). }
  assert (Hpear : pear = phase_form p ++ [(4,2,c)])
    by (exact (pear_decompose _ _ _ EWE ESK)).
  destruct (emits p) eqn:EEM.
  -
    destruct (p =? 27) eqn:E27.
    { exact (tick3_slow_sim _ _ HI Hrun). }
    destruct pear as [|[[X zX] cX] pear1] eqn:EPR; [discriminate|].
    match type of Hrun with (if negb ?B then _ else _) = _ =>
      destruct B eqn:EL2 end;
      cbn [negb] in Hrun.
    2: { exact (tick3_slow_sim _ _ HI Hrun). }
    apply Nat.eqb_eq in EL2.
    match type of Hrun with (if negb ?B then _ else _) = _ =>
      destruct B eqn:EX5 end;
      cbn [negb] in Hrun.
    2: { exact (tick3_slow_sim _ _ HI Hrun). }
    match type of Hrun with (if negb ?B then _ else _) = _ =>
      destruct B eqn:EC1 end;
      cbn [negb] in Hrun.
    2: { exact (tick3_slow_sim _ _ HI Hrun). }
    destruct colsB as [|gc cs] eqn:ECB.
    { exact (tick3_slow_sim _ _ HI Hrun). }
    destruct bot as [|[[o4 z4] c4] bt'] eqn:EBT.
    { exact (tick3_slow_sim _ _ HI Hrun). }
    match type of Hrun with (if ?B then _ else _) = _ =>
      destruct B eqn:EB4 end.
    { exact (tick3_slow_sim _ _ HI Hrun). }
    match type of Hrun with
    | (match ?S with Some _ => _ | None => _ end) = _ =>
        destruct S as [[s2' f2]|] eqn:EFF2
    end.
    2: { exact (tick3_slow_sim _ _ HI Hrun). }
    match type of Hrun with (if ?B then _ else _) = _ =>
      destruct B eqn:ECHK end.
    2: { exact (tick3_slow_sim _ _ HI Hrun). }
    apply andb_prop in ECHK. destruct ECHK as [ECHK EJ6].
    apply andb_prop in ECHK. destruct ECHK as [ECHK ENJ].
    apply andb_prop in ECHK. destruct ECHK as [EHZ EHM].
    inversion Hrun; subst Z3'. clear Hrun.
    destruct HI as (HIp & HIc & HIb & HInc & HInml).
    destruct (phase_form_emit_shape p EEM E27) as (X' & HPF & HX5').
    assert (HXX : (X,zX,cX) = (X',3,1) /\ pear1 = [(4,2,c)]).
    { rewrite HPF in Hpear. cbn [app] in Hpear.
      inversion Hpear; subst. auto. }
    destruct HXX as [HXeq Hp1]. inversion HXeq; subst X' zX cX.
    subst pear1.
    subst nc.
    destruct (nml_app_inv _ _ HInml) as [_ HnmlT].
    destruct (nml_app_inv _ _ HnmlT) as [HnmlCB _].
    split.
    + exact (emit_sim c_0 rmid j (gc :: cs) ((o4,z4,c4) :: bt') f h p c X
               s2' f2 EZL EDP EP28 EEM E27 HPF EX5 EC1
               ltac:(congruence) HIc HnmlCB
               HIb EB4 EFF2 EHZ EHM ENJ EJ6).
    + cbn [Z3Inv].
      repeat split.
      * cbn [length]. lia.
      * exact HIc.
      * exact (botfree_normalize _ EHZ).
      * match goal with
        | |- nml ?W = true =>
            replace W with (normalize ((X-1,1,1) :: (7,2,1)
              :: (4,2,c-1) :: (gc :: cs) ++ s2'))
        end.
        { apply nml_normalize. }
        exact (normalize_wrapper X c (gc :: cs) s2' HIc
                 ltac:(congruence) EHM EHZ HnmlCB).
  -
    match type of Hrun with (if ?B then _ else _) = _ =>
      destruct B eqn:EC2 end; [|discriminate].
    match type of Hrun with (if ?B then _ else _) = _ =>
      destruct B eqn:ENML end; [|discriminate].
    match type of Hrun with (if ?B then _ else _) = _ =>
      destruct B eqn:ECHK end.
    2: { exact (tick3_slow_sim _ _ HI Hrun). }
    apply andb_prop in ECHK. destruct ECHK as [ECHK EJ6].
    apply andb_prop in ECHK. destruct ECHK as [EHM ENJ].
    inversion Hrun; subst Z3'. clear Hrun.
    destruct HI as (HIp & HIc & HIb & HInc & HInml).
    assert (HNJ : nojunc
        (phase_form (p+1)
          ++ [(4,2,(c + DBu (p+1)) - DBu p)])
        (colsB ++ bot) = true).
    { apply nojunc_snoc.
      destruct colsB as [|gc cs].
      - cbn [app]. exact EHM.
      - apply hnm_app; [congruence|exact EHM]. }
    split.
    + rewrite Hpear in EDP, EWE, ESK, HIp.
      pose proof (advance_sim c_0 rmid j
                    (phase_form p ++ [(4,2,c)])
                    colsB bot f h p c EZL EDP EP28 EWE ESK EEM EC2 ENML
                    HNJ ENJ EJ6 HIp) as HAS.
      rewrite Hpear. exact HAS.
    + cbn [Z3Inv].
      repeat split.
      * rewrite app_length. cbn [length].
        pose proof (phase_form_nonnil (p+1)). lia.
      * exact HIc.
      * exact HIb.
      * exact HInc.
      * apply nml_app; [exact ENML| |exact HNJ].
        rewrite Hpear in HInml.
        exact (proj2 (nml_app_inv _ _ HInml)).
Qed.
Fixpoint zrun3 (k : nat) (Z : zst3) (cd : nat) (t bt : N)
               (bz : option zst3) : N * option zst3 :=
  match k with
  | O => (bt, bz)
  | S k' =>
      match tick3 Z with
      | None => (bt, bz)
      | Some Z' =>
          match cd with
          | O => (bt, bz)
          | S O => zrun3 k' Z' 28 (t + 1) (t + 1) (Some Z')
          | S cd' => zrun3 k' Z' cd' (t + 1) bt bz
          end
      end
  end.
Definition zstate3 (Z : zst3) : sstate :=
  zstate (to2 Z).
Definition zjump3 (w : word) (f : N) (h : nat)
  : option (N * sstate) :=
  if negb (front_blind w) then None
  else match first_rule front_rules w f with
  | Some _ => None
  | None =>
    if negb (f =? 4) then None else
    match w with
    | (2,2,cN) :: _ =>
      let start := if Nat.ltb h 1 then 1%nat else h in
      match find_active w start with
      | None => None
      | Some i =>
        if negb (Nat.ltb (S MARGIN) i) then None else
        if negb (forallb is_col (firstn i w)) then None else
        match detect_phase w i with
        | None => None
        | Some p =>
            match zsplit (w, f, h) with
            | Some Z =>
                if negb (nml (zsuf Z)) then None else
                match split3 Z with
                | Some Z3 =>
                    let mmax := Nat.div2 (i - MARGIN) in
                    let m0 := count_clean w (i - 1) mmax in
                    if Nat.eqb m0 O then None else
                    let tmax := 28 * N.of_nat m0 - p in
                    match zrun3 (N.to_nat tmax) Z3 (N.to_nat (28 - p))
                            0 0 None with
                    | (bt, Some Zb) =>
                        if 1 <=? bt then Some (bt, zstate3 Zb)
                        else None
                    | (_, None) => None
                    end
                | None => None
                end
            | None => None
            end
        end
      end
    | _ => None
    end
  end.
Definition ckpt3_ok (Z0 : zst) (bt : N)
           (bz : option zst3) : Prop :=
  match bz with
  | None => True
  | Some zb => ztickk2 (N.to_nat bt) Z0 = Some (to2 zb)
  end.
Lemma zrun3_sound : forall k Z0 Z3 cd t bt bz bt' zb',
  Z3Inv Z3 ->
  ztickk2 (N.to_nat t) Z0 = Some (to2 Z3) ->
  ckpt3_ok Z0 bt bz ->
  zrun3 k Z3 cd t bt bz = (bt', Some zb') ->
  ztickk2 (N.to_nat bt') Z0 = Some (to2 zb').
Proof.
  induction k as [|k IH]; intros Z0 Z3 cd t bt bz bt' zb' HI HZ Hck Hrun;
    cbn [zrun3] in Hrun.
  - inversion Hrun; subst. exact Hck.
  - destruct (tick3 Z3) as [Z1|] eqn:E1.
    + destruct (tick3_sim _ _ HI E1) as [ET HI1].
      assert (HZ1 : ztickk2 (N.to_nat (t + 1)) Z0
                      = Some (to2 Z1)).
      { replace (N.to_nat (t + 1)) with (S (N.to_nat t))
          by (rewrite N2Nat.inj_add; cbn; lia).
        exact (ztickk2_snoc _ _ _ _ HZ ET). }
      destruct cd as [|[|cd']].
      * inversion Hrun; subst. exact Hck.
      * refine (IH _ _ _ _ _ _ _ _ HI1 HZ1 _ Hrun). exact HZ1.
      * exact (IH _ _ _ _ _ _ _ _ HI1 HZ1 Hck Hrun).
    + inversion Hrun; subst. exact Hck.
Qed.
Theorem zjump3_closed : forall w f h t st',
  zjump3 w f h = Some (t, st') ->
  closed_tickk (N.to_nat t) (w, f, h) = Some st'.
Proof.
  intros w f h t st' H. unfold zjump3 in H.
  repeat
    match type of H with
    | (if ?b then _ else _) = _ => destruct b eqn:?; try discriminate
    | match ?x with _ => _ end = _ =>
        destruct x eqn:?; try discriminate
    | (let '(_, _) := ?x in _) = _ => destruct x eqn:?
    end;
  inversion H; subst t st'.
  match goal with
  | ENL : negb (nml (zsuf ?Z)) = false,
    EZ : zsplit _ = Some ?Z,
    ES : split3 ?Z = Some ?Z3,
    ER : zrun3 _ ?Z3 _ _ _ _ = (_, Some ?Zb) |- _ =>
      apply negb_false_iff in ENL;
      destruct (zsplit_ok _ _ EZ) as [Hst HInv];
      destruct (split3_ok _ _ ES) as [Hto HI3];
      pose proof (zrun3_sound _ Z Z3 _ 0 0 None _ _
                    (HI3 ENL)
                    ltac:(cbn [ztickk2 N.to_nat];
                          rewrite Hto; reflexivity)
                    I ER) as HK
  end.
  rewrite ztickk2_eq in HK.
  destruct (ztickk_ok _ _ _ HInv HK) as [Hc _].
  rewrite Hst in Hc.
  exact Hc.
Qed.
Theorem zjump3_sound : forall w f h t st',
  zjump3 w f h = Some (t, st') ->
  stepN t (w, f, h) = Some st'.
Proof.
  intros w f h t st' H.
  unfold stepN.
  exact (closed_tickk_sound _ _ _
           (zjump3_closed _ _ _ _ _ H)).
Qed.
Set Warnings "require-in-module".
Transparent leaf_act.
Transparent jump_comp.
Open Scope N_scope.
Open Scope bool_scope.
Definition ACT_UB : N := N.shiftl 1 13100.
Definition EARLY_UNITS : N :=
  N.shiftl 47 (2 * LATE_BITS - 13100).
Definition EARLY_UB : N := EARLY_UNITS * ACT_UB.
Definition BOUND_TERM : N := .
Definition BOUND_MAX : N := BOUND_TERM + 7 + 2 * 520224631.
Definition CLOSE_UB : N :=
  (BOUND_MAX + 21) * (BOUND_MAX + 21).
Definition closeq (M : N) : N := (M + 21) * (M + 21).
Definition spanq (q M : N) : N := q * closeq (M + 2 * q).
Definition FLIGHT_QMAX : N := 520224631.
Definition FLIGHT_UB : N :=
  (17 * BOUND_MAX * FLIGHT_QMAX + 5 * FLIGHT_QMAX * FLIGHT_QMAX
     + 880 * BOUND_MAX + 214 * FLIGHT_QMAX + 11440)
  + 67 *
      (3 * (BOUND_MAX + 8 * FLIGHT_QMAX) * FLIGHT_QMAX
         + 6 * FLIGHT_QMAX * FLIGHT_QMAX
         + 547 * (BOUND_MAX + 8 * FLIGHT_QMAX)
         + 54 * FLIGHT_QMAX + 8000).
Definition FLIGHT_UB_WIDE : N :=
  (17 * BOUND_MAX * (3 * BOUND_MAX)
     + 5 * (3 * BOUND_MAX) * (3 * BOUND_MAX)
     + 880 * BOUND_MAX + 214 * (3 * BOUND_MAX) + 11440)
  + 67 *
      (3 * (BOUND_MAX + 8 * (3 * BOUND_MAX)) * (3 * BOUND_MAX)
         + 6 * (3 * BOUND_MAX) * (3 * BOUND_MAX)
         + 547 * (BOUND_MAX + 8 * (3 * BOUND_MAX))
         + 54 * (3 * BOUND_MAX) + 8000).
Definition flight_ub (q : N) : N :=
  if (q <=? FLIGHT_QMAX)%N then FLIGHT_UB else FLIGHT_UB_WIDE.
Definition ncost : Type := (N * ((cost * cost) * N))%type.
Definition nc0 : ncost := (0, ((czero, czero), 0)).
Definition ncs (a : ncost) : cost := fst (fst (snd a)).
Definition ncq (a : ncost) : N := snd (snd a).
Definition ncf (a : ncost) : N := fst (snd (fst (snd a))).
Definition ncfw (a : ncost) : N := snd (snd (fst (snd a))).
Definition ncl (a : ncost) : cost :=
  cadds (ncs a)
    (0, ncq a * ACT_UB + ncf a * FLIGHT_UB
        + ncfw a * FLIGHT_UB_WIDE).
Definition nce (a : ncost) : cost := snd (fst (snd a)).
Definition nc_bump (a : ncost) (q : N) (dc _de : cost) : ncost :=
  (fst a + q,
   ((cadds (ncs a) dc, nce a), ncq a)).
Definition nc_qbump (a : ncost) (q : N) (_de : cost) : ncost :=
  (fst a + q,
   ((ncs a, nce a), ncq a + 1)).
Definition nc_ebump (a : ncost) (q : N) : ncost :=
  (fst a + q,
   ((ncs a, nce a), ncq a + EARLY_UNITS)).
Definition nc_fbump (a : ncost) (q : N) : ncost :=
  (fst a + q,
   ((ncs a,
     if (q <=? FLIGHT_QMAX)%N
     then (ncf a + 1, ncfw a)
     else (ncf a, ncfw a + 1)),
    ncq a)).
Definition nc_rbump (a : ncost) (q : N) : ncost :=
  (fst a + q, ((ncs a, nce a), ncq a + q)).
Definition nc_sbump (a : ncost) (q M : N) : ncost :=
  nc_bump a q (0, spanq q M) czero.
Definition nc_add (a b : ncost) : ncost :=
  (fst a + fst b,
   ((cadds (ncs a) (ncs b), cadd (nce a) (nce b)),
    ncq a + ncq b)).
Definition MARG : nat := 10.
Definition GUARD : nat := 3.
Definition SEGMIN : nat := 20.
Definition SEGMIN_GROUPS : nat := 2 * SEGMIN - 1.
Definition d0 : bg := (0,0,0).
Definition is_lvl (g : bg) : bool := (gO g =? 4) && (gZ g =? 2).
Definition is_spc (g : bg) : bool :=
  (gO g =? 8) && (gZ g =? 2) && (gC g =? 1).
Definition casc (g : bg) : bool := is_lvl g || is_spc g.
Definition PHO : N := 9.
Definition phg (k : N) : bg := (PHO, 2, k).
Definition tagbase (g : bg) : bool :=
  (gO g =? PHO) && (gZ g =? 2).
Definition phshape (g : bg) : bool :=
  tagbase g && (2 <=? gC g).
Definition seg : Type := (N * N * N * nat * word * word * N)%type.
Definition sKey (s : seg) : N := let '(k,_,_,_,_,_,_) := s in k.
Definition sPend (s : seg) : N := let '(_,p,_,_,_,_,_) := s in p.
Definition sMin (s : seg) : N := let '(_,_,m,_,_,_,_) := s in m.
Definition sLen (s : seg) : nat := let '(_,_,_,l,_,_,_) := s in l.
Definition sFront (s : seg) : word := let '(_,_,_,_,b,_,_) := s in b.
Definition sBack (s : seg) : word := let '(_,_,_,_,_,b,_) := s in b.
Definition sCsum (s : seg) : N := let '(_,_,_,_,_,_,c) := s in c.
Definition sBody (s : seg) : word := sFront s ++ rev (sBack s).
Definition adjk (p : N) (g : bg) : bg :=
  let '(o,z,c) := g in if (o =? 4) && (z =? 2) then (o, z, c - 4 * p) else g.
Definition matb (p : N) (b : word) : word := map (adjk p) b.
Definition sFlat (s : seg) : word := matb (sPend s) (sBody s).
Fixpoint minlvl (b : word) : N :=
  match b with
  | [] => 0
  | g :: t => if is_lvl g
              then (match t with [] => gC g | _ => N.min (gC g) (minlvl t) end)
              else minlvl t
  end.
Fixpoint segalt (b : word) : bool :=
  match b with
  | [l] => is_lvl l
  | l :: s :: b' => is_lvl l && is_spc s && segalt b'
  | _ => false
  end.
Definition segshape (s : seg) : bool :=
  Nat.leb 2 (sLen s) && segalt (sBody s).
Definition segok (s : seg) : bool :=
  let b := sBody s in
  let m := sMin s in
  let l := sLen s in
  match b with
  | [] => false
  | g0 :: _ =>
      is_lvl g0
      && is_lvl (nth (l - 1) b d0)
      && Nat.odd l
      && forallb casc b
      && forallb (fun g => negb (is_lvl g) || (m <=? gC g)) b
  end.
Definition segcache (s : seg) : bool :=
  Nat.eqb (sLen s) (length (sFront s) + length (sBack s)).
Definition can_cross (s : seg) : bool :=
  FLOOR + 3 + 4 * sPend s <=? sMin s.
Definition lit_crossable (g : bg) : bool :=
  lvl_big g && (FLOOR + 3 <=? gC g).
Definition erode_safe (p : N) (g : bg) : bool :=
  (FLOOR + DBu p <=? gC g)%N.
Definition segpos (s : seg) : bool :=
  (1 + 4 * sPend s <=? sMin s)%N.
Definition bump_pend (s : seg) : seg :=
  let '(k,p,m,l,bf,bb,cs) := s in
  (k, p + 1, m, l, bf, bb, cs - 56 * N.of_nat (S (Nat.div2 l))).
Definition segl (s : seg) : nat := S (Nat.div2 (sLen s)).
Fixpoint takerun (w : word) : word * word :=
  match w with
  | g :: t => if casc g
              then let '(a, b) := takerun t in (g :: a, b)
              else ([], w)
  | [] => ([], [])
  end.
Fixpoint lplan (fu : nat) (w : word) (i : nat) : list (nat * nat) :=
  match fu with
  | O => []
  | S fu' =>
      match w with
      | [] => []
      | g :: t =>
          if casc g then
            let '(r, rest) := takerun w in
            let n := length r in
            if Nat.leb (2 * MARG + SEGMIN_GROUPS) n then
              let a := if is_lvl (nth MARG r d0) then MARG else S MARG in
              let b0 := (n - MARG)%nat in
              let b := if is_lvl (nth (b0 - 1) r d0) then b0 else (b0 - 1)%nat in
              if is_spc (nth (a - 1) r d0) && is_spc (nth b r d0)
                 && Nat.ltb a b
              then ((i + a)%nat, (b - a)%nat) :: lplan fu' rest (i + n)
              else lplan fu' rest (i + n)
            else lplan fu' rest (i + n)
          else lplan fu' t (S i)
      end
  end.
Definition split_body (b : word) : word * word :=
  let n := Nat.div2 (length b) in
  (firstn n b, rev (skipn n b)).
Fixpoint lapply (pl : list (nat * nat)) (w : word) (off : nat) (kx : N)
  : word * list seg :=
  match pl with
  | [] => (w, [])
  | (s, l) :: pl' =>
      let s' := (s - off)%nat in
      let body := firstn l (skipn s' w) in
      let '(bf, bb) := split_body body in
      let '(cw2, sg2) := lapply pl' (skipn (s' + l) w) (s + l)%nat (kx + 1) in
      (firstn s' w ++ phg kx :: cw2,
       (kx, 0, minlvl body, length body, bf, bb, bsum body)
         :: sg2)
  end.
Definition keyi (sg : list seg) (g : bg) : option seg :=
  if phshape g then
    (fix go (l : list seg) : option seg :=
       match l with
       | [] => None
       | s :: t => if gC g =? sKey s then Some s else go t
       end) sg
  else None.
Definition keyl (sg : list seg) (g : bg) : option nat :=
  match keyi sg g with Some s => Some (sLen s) | None => None end.
Definition keyb (sg : list seg) (g : bg) : option word :=
  match keyi sg g with Some s => Some (sFlat s) | None => None end.
Definition lin_gcross (sg : list seg) (g : bg) : N :=
  match keyi sg g with
  | Some s => sCsum s
  | None => bpc g
  end.
Fixpoint lin_bsum (sg : list seg) (w : word) : N :=
  match w with
  | [] => 0
  | g :: t => lin_gcross sg g + lin_bsum sg t
  end.
Definition lin_ubw (sg : list seg) (w : word) (f : N) : N :=
  lin_bsum sg w + 2 * f.
Definition lin_ubret (a b : N) : N := 4 * (a + b) + 64.
Definition lin_ubstage (a b : N) : N := 8 * (a + b) + 64.
Definition lin_dmicro (sg : list seg) (w : word) (f : N)
                      (sg' : list seg) (w' : word) (f' : N) : cost :=
  (0, lin_ubret (lin_ubw sg w f) (lin_ubw sg' w' f')).
Definition lin_dflight (sg' : list seg) (w' : word) (f' : N)
                       (t : N) : cost :=
  let b := lin_ubw sg' w' f' in
  cscale t (1, lin_ubstage b b).
Fixpoint fmapw (sg : list seg) (w : word) (j acc h : nat) : nat :=
  match w with
  | [] => (h + acc)%nat
  | g :: t =>
      if Nat.leb h j then (h + acc)%nat
      else match keyl sg g with
           | Some l => fmapw sg t (S j) (acc + l - 1)%nat h
           | None => fmapw sg t (S j) acc h
           end
  end.
Fixpoint hmapw (sg : list seg) (w : word) (j fl h : nat) : nat :=
  match w with
  | [] => (j + (h - fl))%nat
  | g :: t =>
      match keyl sg g with
      | Some l =>
          if Nat.ltb h (fl + l)%nat then j
          else hmapw sg t (S j) (fl + l)%nat h
      | None => if Nat.leb h fl then j else hmapw sg t (S j) (S fl) h
      end
  end.
Definition hint_of (j : nat) : nat := if Nat.ltb j 5 then O else (j - 4)%nat.
Fixpoint countkey (k : N) (w : word) : nat :=
  match w with
  | [] => O
  | g :: t => (if phshape g && (N.eqb (gC g) k) then 1 else 0) + countkey k t
  end%nat.
Definition lin_ok (sg : list seg) (w : word) : bool :=
  forallb (fun s => Nat.eqb (countkey (sKey s) w) 1) sg.
Definition ph (sg : list seg) (g : bg) : bool :=
  match keyi sg g with Some _ => true | None => false end.
Fixpoint lin_tags (sg : list seg) (w : word) : bool :=
  match w with
  | [] => true
  | g :: t => (negb (tagbase g) || ph sg g) && lin_tags sg t
  end.
Fixpoint lguard (sg : list seg) (w : word) (before need : nat) : bool :=
  match w with
  | [] => Nat.eqb need O
  | g :: t =>
      let isph := ph sg g in
      if Nat.ltb O need then
        if isph || negb (casc g) then false
        else lguard sg t (S before) (need - 1)
      else if isph then
        if Nat.ltb before GUARD then false else lguard sg t O GUARD
      else if casc g then lguard sg t (S before) O
      else lguard sg t O O
  end.
Definition lin_guard (sg : list seg) (w : word) : bool := lguard sg w O O.
Fixpoint lshape_guard (w : word) (before need : nat) : bool :=
  match w with
  | [] => Nat.eqb need O
  | g :: t =>
      let isph := phshape g in
      if Nat.ltb O need then
        if isph || negb (casc g) then false
        else lshape_guard t (S before) (need - 1)
      else if isph then
        if Nat.ltb before GUARD then false
        else lshape_guard t O GUARD
      else if casc g then lshape_guard t (S before) O
      else lshape_guard t O O
  end.
Definition lin_shape_guard (w : word) : bool :=
  lshape_guard w O O.
Fixpoint lin_flen (sg : list seg) (w : word) : nat :=
  match w with
  | [] => O
  | g :: t => (match keyl sg g with Some l => l | None => 1%nat end
               + lin_flen sg t)%nat
  end.
Fixpoint lin_flat (sg : list seg) (w : word) : word :=
  match w with
  | [] => []
  | g :: t =>
      match keyb sg g with
      | Some body => body ++ lin_flat sg t
      | None => g :: lin_flat sg t
      end
  end.
Definition lin_post (sg : list seg) (w : word) : bool :=
  forallb segok sg && lin_ok sg w.
Definition lin_post_full (sg : list seg) (w : word) : bool :=
  forallb segcache sg && lin_post sg w.
Definition lin_condk (kx : N) (w : word) (h : nat)
  : option (word * list seg * nat) :=
  match lplan (length w) w O with
  | [] => None
  | pl =>
      let '(cw, sg) := lapply pl w O kx in
      if forallb (fun s => segcache s && segok s) sg then
        if forallb segshape sg
        then if forallb segpos sg
             then Some (cw, sg, hmapw sg cw O O h)
             else None
        else None
      else None
  end.
Definition KMAGIC : N := 18446744073709551616 + 4276996862.
Definition lin_cond (w : word) (h : nat) : option (word * list seg * nat) :=
  match lplan (length w) w O with
  | [] => None
  | _ :: _ =>
      match lin_condk KMAGIC w h with
      | Some (cw, sg, h0) =>
          if lin_ok sg cw then
            if lin_tags sg cw then Some (cw, sg, h0) else None
          else None
      | None => None
      end
  end.
Fixpoint sgset (sg : list seg) (k : N) (s : seg) : list seg :=
  match sg with
  | [] => []
  | x :: t => if sKey x =? k then s :: t else x :: sgset t k s
  end.
Fixpoint lin_hasn {A : Type} (n : nat) (xs : list A) : bool :=
  match n, xs with
  | O, _ => true
  | S n', _ :: xs' => lin_hasn n' xs'
  | S _, [] => false
  end.
Definition spill_front (s : seg) (k : nat) : word * seg :=
  let '(key,p,m,l,bf,bb,cs) := s in
  let n := (2*k)%nat in
  if lin_hasn n bf then
    let out := matb p (firstn n bf) in
    (out,
     (key, p, m, (l - n)%nat, skipn n bf, bb, cs - bsum out))
  else
    let b := bf ++ rev bb in
    let rest := skipn n b in
    let '(rf, rb) := split_body rest in
    let out := matb p (firstn n b) in
    (out, (key, p, m, (l - n)%nat, rf, rb, cs - bsum out)).
Definition spill_back (s : seg) (k : nat) : seg * word :=
  let '(key,p,m,l,bf,bb,cs) := s in
  let n := (2*k)%nat in
  if lin_hasn n bb then
    let out := matb p (rev (firstn n bb)) in
    ((key, p, m, (l - n)%nat, bf, skipn n bb, cs - bsum out),
     out)
  else
    let b := bf ++ rev bb in
    let cut := (l - n)%nat in
    let rest := firstn cut b in
    let '(rf, rb) := split_body rest in
    let out := matb p (skipn cut b) in
    ((key, p, m, cut, rf, rb, cs - bsum out), out).
Fixpoint cleanrun (sg : list seg) (w : word) (k : nat) : nat :=
  match k, w with
  | O, _ => O
  | _, [] => O
  | S k', g :: t =>
      if ph sg g || negb (casc g) then O else S (cleanrun sg t k')
  end.
Definition SLACK : nat := 4.
Fixpoint relax (fu : nat) (sg : list seg) (w : word) (before : nat)
  : word * list seg :=
  match fu, w with
  | O, _ => (w, sg)
  | _, [] => ([], sg)
  | S fu', g :: t =>
      match keyi sg g with
      | Some s =>
          let aft := cleanrun sg t (GUARD + SLACK) in
          let kf := Nat.div2 (S (GUARD + SLACK - before)) in
          let kb := Nat.div2 (S (GUARD + SLACK - aft)) in
          let nl := segl s in
          if Nat.leb nl (kf + kb + SEGMIN) then
            let sg' := filter (fun x => negb (sKey x =? sKey s)) sg in
            let '(t', sg'') := relax fu' sg' t (GUARD + SLACK) in
            (sFlat s ++ t', sg'')
          else
            let '(fr, s1) := spill_front s kf in
            let '(s2, bk) := spill_back s1 kb in
            let sg' := sgset sg (sKey s) s2 in
            let '(t', sg'') := relax fu' sg' (bk ++ t) (GUARD + SLACK) in
            (fr ++ phg (sKey s) :: t', sg'')
      | None =>
          let '(t', sg') := relax fu' sg t (if casc g then S before else O) in
          (g :: t', sg')
      end
  end.
Definition lin_relax (sg : list seg) (w : word) : word * list seg :=
  relax (length w) sg w (GUARD + SLACK).
Definition remap (sg : list seg) (w : word) (sg' : list seg) (w' : word)
                 (q : nat) : nat :=
  hmapw sg' w' O O (fmapw sg w O O q).
Definition remapst (sg : list seg) (w : word) (sg' : list seg) (w' : word)
                   (st : list (nat * N)) : list (nat * N) :=
  map (fun fr => (remap sg w sg' w' (fst fr), snd fr)) st.
Definition fixup (sg : list seg) (w : word) (st : list (nat * N))
  : option (list seg * word * list (nat * N)) :=
  if negb (lin_ok sg w) then None
  else if lin_guard sg w then Some (sg, w, st)
  else let '(w4, sg4) := lin_relax sg w in
       if lin_guard sg4 w4 then
         if lin_ok sg4 w4 then
           Some (sg4, w4, remapst sg w sg4 w4 st)
         else None
       else None.
Fixpoint lin_split_at (n : nat) (w : word) : word * word :=
  match n, w with
  | O, _ => ([], w)
  | S n', [] => ([], [])
  | S n', g :: w' =>
      let '(a, b) := lin_split_at n' w' in (g :: a, b)
  end.
Fixpoint lin_normalize_full (w : word) : word :=
  match w with
  | [] => []
  | (o,z,c) as g :: w' =>
      match lin_normalize_full w' with
      | ((o2,z2,c2) as g2) :: t =>
          if tagbase g || tagbase g2 then g :: g2 :: t
          else if (o =? o2) && (z =? z2)
               then (o,z,c+c2) :: t
               else g :: g2 :: t
      | [] => [g]
      end
  end.
Definition lin_normalize_slice (_sg : list seg) (w : word) : word :=
  lin_normalize_full w.
Fixpoint lin_nadj_span (fu : nat) (sg : list seg) (w : word) : bool :=
  match fu, w with
  | O, _ | _, [] | _, [_] => true
  | S fu', g1 :: ((g2 :: _) as w') =>
      negb ((gO g1 =? gO g2) && (gZ g1 =? gZ g2))
      && lin_nadj_span fu' sg w'
  end.
Definition lin_normalize_at (sg : list seg) (w : word) (center : nat) : word :=
  if Nat.eqb center O then w else
  let lo := (center - 2)%nat in
  if lin_nadj_span 6 sg (skipn lo w) then w else
    let '(pre, rest) := lin_split_at lo w in
    let '(mid, post) := lin_split_at 6 rest in
    pre ++ lin_normalize_slice sg mid ++ post.
Definition lin_at_safe (sg : list seg) (w : word) (center : nat)
  : option word :=
  if Nat.eqb center O then Some w else
  if lin_nadj_span 6 sg (skipn (center - 2)%nat w)
  then Some w
  else None.
Fixpoint lin_normalize_join (sg : list seg) (pre sfx : word) : word :=
  match pre with
  | g :: ((g1 :: g2 :: t) as pre') =>
      g :: lin_normalize_join sg pre' sfx
  | _ =>
      let '(mid, post) := lin_split_at (6 - length pre)%nat sfx in
      lin_normalize_slice sg (pre ++ mid) ++ post
  end.
Fixpoint lin_join_safe (sg : list seg) (pre sfx : word) : option word :=
  match pre with
  | g :: ((g1 :: g2 :: t) as pre') =>
      match lin_join_safe sg pre' sfx with
      | Some out => Some (g :: out)
      | None => None
      end
  | _ =>
      let '(mid, _) := lin_split_at (6 - length pre)%nat sfx in
      if lin_nadj_span 6 sg (pre ++ mid)
      then Some (pre ++ sfx)
      else None
  end.
Definition lin_literal_word (w : word) : bool :=
  forallb (fun g => negb (phshape g)) w.
Definition adj4p (sg : list seg) (g : bg) : bg :=
  if ph sg g then g else adj4 g.
Fixpoint climb (fu : nat) (sg : list seg) (w : word) (k need : nat)
                (top : bool) : option (nat * list seg) :=
  match fu with
  | O => None
  | S fu' =>
      if Nat.eqb need O then Some (S k, sg) else
      if Nat.ltb k 1 then None else
      match wat w k, wat w (k - 1) with
      | Some l, Some s =>
          if negb (is_spc s) then None else
          match keyi sg l with
          | Some sg1 =>
              if top then None else
              let nl := segl sg1 in
              if negb (can_cross sg1) then None else
              if Nat.ltb need nl then None else
              climb fu' (sgset sg (sKey sg1) (bump_pend sg1)) w
                    (k - 2) (need - nl) false
          | None =>
              if negb (lit_crossable l) then None else
              climb fu' sg w (k - 2) (need - 1) false
          end
      | _, _ => None
      end
  end.
Definition lin_bulk (sg : list seg) (w : word) (j : nat) (p : N) (t : N)
  : option (word * list seg * nat * N * N) :=
  let total := p + t in
  let full := N.to_nat (total / 28) in
  let rem := total mod 28 in
  let emit := marks total - marks p in
  let npair := phase_len p in
  let blw := (j + npair)%nat in
  match wat w blw with
  | None => None
  | Some gb =>
      if ph sg gb then None else
      if negb (lvl_big gb) then None
      else if negb (erode_safe p gb) then None
      else if Nat.eqb (S blw) (length w) then None
      else if Nat.eqb full 0 then
        Some (subst_at j npair (phase_form rem)
                (subst_at blw 1 [(4, 2, (gC gb + DBu rem) - DBu p)] w),
              sg, j, rem, emit)
      else if Nat.ltb j 1 then None
      else match climb (S full) sg w (j - 1) full true with
      | None => None
      | Some (nh, sg') =>
        match firstn (j - S nh) (skipn (S nh) w) with
        | (o0,z0,c_0) :: rest0 =>
            if ph sg' (o0,z0,c_0) then None else
            let strip := phase_form rem
                         ++ [(o0, z0, (c_0 + DBu rem) - 3)]
                         ++ map (adj4p sg') rest0 ++ [(8,2,1)] in
            let w' := firstn nh w ++ strip
                        ++ ((4, 2, (gC gb - 1) - DBu p) :: skipn (S blw) w) in
            Some (w', sg', nh, rem, emit)
        | [] => None
        end
      end
  end.
Fixpoint lcc (fu : nat) (sg : list seg) (w : word) (k : nat) (mmax : nat)
  : nat :=
  match fu with
  | O => O
  | S fu' =>
      if Nat.eqb mmax O then O
      else if Nat.ltb k 1 then O
      else match wat w k, wat w (k - 1) with
           | Some l, Some s =>
               if negb (is_spc s) then O else
               match keyi sg l with
               | Some sg1 =>
                   let nl := segl sg1 in
                   if can_cross sg1 && Nat.leb nl mmax
                   then (nl + lcc fu' sg w (k - 2) (mmax - nl))%nat
                   else O
               | None =>
                   if lit_crossable l
                   then S (lcc fu' sg w (k - 2) (mmax - 1))
                   else O
               end
           | _, _ => O
           end
  end.
Definition lin_count_clean (sg : list seg) (w : word) (k : nat) (mmax : nat)
  : nat := lcc (S k) sg w k mmax.
Definition lin_bulk_take (sg : list seg) (w : word) (cur tg : nat)
                         (pk tk : N) : N :=
  let mgeom := Nat.div2 (fmapw sg w O O tg - fmapw sg w O O cur - 2) in
  let mneed := N.to_nat ((pk + tk) / 28) in
  let m := Nat.min mneed (lin_count_clean sg w (tg - 1) (Nat.min mgeom mneed)) in
  if Nat.eqb m O then N.min tk (27 - pk)
  else N.min tk (28 * N.of_nat m - pk).
Definition lin_transfer_prefix (w : word) (i : nat) : bool :=
  match w with
  | [] => false
  | _ :: tail =>
      forallb (fun g => is_col g && negb (is_cmf g) && (3 <=? gO g)%N)
        (firstn (i - 1)%nat tail)
  end.
Definition atab : Type := list nat.
Definition RELOC : nat := 16.
Definition is_key (k : N) (g : bg) : bool :=
  phshape g && (N.eqb (gC g) k).
Fixpoint find_key_scan (fu : nat) (w : word) (i : nat) (k : N)
  : option nat :=
  match fu, w with
  | O, _ | _, [] => None
  | S fu', g :: w' =>
      if is_key k g then Some i else find_key_scan fu' w' (S i) k
  end.
Definition find_key_from (fu : nat) (w : word) (i : nat) (k : N)
  : option nat :=
  find_key_scan fu (skipn i w) i k.
Definition locate_key (w : word) (k : N) : option nat :=
  find_key_from (length w) w O k.
Fixpoint locate_all_slow (sg : list seg) (w : word) : option atab :=
  match sg with
  | [] => Some []
  | s :: sg' =>
      match locate_key w (sKey s), locate_all_slow sg' w with
      | Some i, Some ps => Some (i :: ps)
      | _, _ => None
      end
  end.
Fixpoint find_key_rest_all (w : word) (i : nat) (k : N)
  : option (nat * word) :=
  match w with
  | [] => None
  | g :: w' =>
      if is_key k g then Some (i, w')
      else find_key_rest_all w' (S i) k
  end.
Fixpoint locate_all_ordered (sg : list seg) (w : word) (i : nat)
  : option atab :=
  match sg with
  | [] => Some []
  | s :: sg' =>
      match find_key_rest_all w i (sKey s) with
      | None => None
      | Some (j, w') =>
          match locate_all_ordered sg' w' (S j) with
          | Some ps => Some (j :: ps)
          | None => None
          end
      end
  end.
Definition locate_all (sg : list seg) (w : word) : option atab :=
  match locate_all_ordered sg w O with
  | Some ps => Some ps
  | None => locate_all_slow sg w
  end.
Definition relocate_key (w : word) (old : nat) (k : N) : option nat :=
  let lo := (old - RELOC)%nat in
  find_key_from (S (2 * RELOC)) w lo k.
Fixpoint relocate_all_slow (sg : list seg) (ps : atab) (w : word)
  : option atab :=
  match sg, ps with
  | [], [] => Some []
  | s :: sg', i :: ps' =>
      match relocate_key w i (sKey s), relocate_all_slow sg' ps' w with
      | Some j, Some ps2 => Some (j :: ps2)
      | _, _ => None
      end
  | _, _ => None
  end.
Definition relocate_all (sg : list seg) (ps : atab) (w : word)
  : option atab :=
  relocate_all_slow sg ps w.
Fixpoint lin_same_length (a b : word) : bool :=
  match a, b with
  | [], [] => true
  | _ :: a', _ :: b' => lin_same_length a' b'
  | _, _ => false
  end.
Fixpoint clean_window_scan (fu : nat) (sg : list seg) (w : word)
                           (i ph_i : nat) : bool :=
  match fu, w with
  | O, _ => true
  | _, [] => false
  | S fu', g :: w' =>
      (if Nat.eqb i ph_i
       then true
       else casc g && negb (ph sg g))
      && clean_window_scan fu' sg w' (S i) ph_i
  end.
Definition clean_window (fu : nat) (sg : list seg) (w : word)
                        (i ph_i : nat) : bool :=
  clean_window_scan fu sg (skipn i w) i ph_i.
Fixpoint guard_at_slow (all : list seg) (sg : list seg) (ps : atab)
                   (w : word) : bool :=
  match sg, ps with
  | [], [] => true
  | s :: sg', i :: ps' =>
      match wat w i with
      | Some g =>
          Nat.leb GUARD i
          && is_key (sKey s) g
          && clean_window (S (2 * GUARD)) all w (i - GUARD)%nat i
          && guard_at_slow all sg' ps' w
      | None => false
      end
  | _, _ => false
  end.
Fixpoint guard_at_ordered (all : list seg) (sg : list seg) (ps : atab)
                          (w : word) (base : nat) : bool :=
  match sg, ps with
  | [], [] => true
  | s :: sg', p :: ps' =>
      let lo := (p - GUARD)%nat in
      if Nat.leb base lo then
        let w0 := skipn (lo - base) w in
        match nth_error w0 (p - lo) with
        | Some g =>
            Nat.leb GUARD p
            && is_key (sKey s) g
            && clean_window_scan (S (2 * GUARD)) all w0 lo p
            && guard_at_ordered all sg' ps' w0 lo
        | None => false
        end
      else false
  | _, _ => false
  end.
Definition lin_guard_at (sg : list seg) (ps : atab) (w : word) : bool :=
  if guard_at_ordered sg sg ps w O then true
  else guard_at_slow sg sg ps w.
Definition lin_fixup_at (sg : list seg) (ps : atab) (w : word)
                        (st : list (nat * N))
  : option (list seg * atab * word * list (nat * N)) :=
  if lin_guard_at sg ps w then Some (sg, ps, w, st)
  else
    match fixup sg w st with
    | Some (sg2, w2, st2) =>
        match locate_all sg2 w2 with
        | Some ps2 =>
            if lin_guard_at sg2 ps2 w2
            then Some (sg2, ps2, w2, st2)
            else None
        | None => None
        end
    | None => None
    end.
Definition lin_keep_at (sg : list seg) (ps : atab) (w : word)
                       (st : list (nat * N))
  : option (list seg * atab * word * list (nat * N)) :=
  if lin_guard_at sg ps w then Some (sg, ps, w, st) else None.
Fixpoint lin_near_at (ps : atab) (i r : nat) : bool :=
  match ps with
  | [] => false
  | p :: ps' =>
      (Nat.leb (i - r)%nat p && Nat.leb p (i + r)%nat)
      || lin_near_at ps' i r
  end.
Definition lin_bottom_form (s3 : word) : option (nat * N) :=
  match s3 with
    | [(7,1,1); (3,2,1); (4,2,fuel)] => Some (0%nat, fuel)
    | [(7,1,1); (2,2,1); (4,2,fuel)] => Some (1%nat, fuel)
    | [(7,1,1); (1,2,1); (4,2,fuel)] => Some (2%nat, fuel)
    | [(7,3,1); (4,2,fuel)] => Some (3%nat, fuel)
    | [(6,1,2); (3,2,1); (4,2,fuel)] => Some (4%nat, fuel+1)
    | [(6,1,1); (5,1,1); (3,2,1); (4,2,fuel)] => Some (5%nat, fuel+1)
    | [(6,1,1); (4,1,1); (3,2,1); (4,2,fuel)] => Some (6%nat, fuel+1)
    | [(6,1,1); (3,1,1); (3,2,1); (4,2,fuel)] => Some (7%nat, fuel+1)
    | [(6,1,1); (2,1,1); (3,2,1); (4,2,fuel)] => Some (8%nat, fuel+1)
    | [(6,1,1); (1,1,1); (3,2,1); (4,2,fuel)] => Some (9%nat, fuel+1)
    | [(6,2,1); (3,2,1); (4,2,fuel)] => Some (10%nat, fuel+1)
    | [(5,1,1); (3,1,1); (4,2,fuel)] => Some (11%nat, fuel)
    | [(5,1,1); (2,1,1); (4,2,fuel)] => Some (12%nat, fuel)
    | [(5,1,1); (1,1,1); (4,2,fuel)] => Some (13%nat, fuel)
    | [(5,2,1); (4,2,fuel)] => Some (14%nat, fuel)
    | [(4,1,1); (3,2,1); (4,2,fuel)] => Some (15%nat, fuel)
    | [(4,1,1); (2,2,1); (4,2,fuel)] => Some (16%nat, fuel)
    | [(4,1,1); (1,2,1); (4,2,fuel)] => Some (17%nat, fuel)
    | [(4,3,1); (4,2,fuel)] => Some (18%nat, fuel)
    | _ => None
  end.
Definition lin_bottom_level (cols : word) : option N :=
  match last2 cols with
  | Some (_, (8,2,1), (4,2,H)) => Some H
  | _ => None
  end.
Definition lin_bottom_take (cols s3 : word) (f tk : N) : option N :=
  match lin_bottom_form s3 with
  | None => None
  | Some (p, fuel) =>
      match lin_bottom_level cols with
      | Some H =>
          if (f =? 4) && (1 <=? tk) && (FLOOR <=? H) && (2 <=? fuel)
          then Some (N.of_nat (Nat.min (N.to_nat tk) (19 - p)%nat))
          else None
      | None => None
      end
  end.
Fixpoint lin_bottom_zrun (fu lc : nat) (sg : list seg)
                         (lw : word) (f : N) : option (word * N) :=
  if lin_literal_word lw then
  match fu with
  | O => Some (lw, f)
  | S fu' =>
      let sf := skipn lc lw in
      let '(cols, s3) := seek sf in
      match s3 with
      | [] => None
      | _ :: _ =>
          match dtick_after_seek cols s3 f with
          | Some (sfx, f2) =>
              match (if Nat.eqb lc O then Some sfx
                     else lin_join_safe sg (firstn lc lw) sfx) with
              | Some lw2 => lin_bottom_zrun fu' lc sg lw2 f2
              | None => None
              end
          | None => None
          end
      end
  end
  else None.
Record lsc_frame : Type := {
  lsCur : nat;
  lsTicks : N;
  lsSlot : N;
  lsGap : nat
}.
Definition lin_sched_slot (p : N) : N :=
  3 - (marks p mod 4).
Definition lin_sched_grants (slot take : N) : N :=
  (take + (3-slot)) / 4.
Definition lin_sched_slot_advance (slot take : N) : N :=
  3 - ((3-slot+take) mod 4).
Definition lin_sched_advance (fr : lsc_frame) (take : N) : lsc_frame :=
  {| lsCur := lsCur fr;
     lsTicks := lsTicks fr - take;
     lsSlot := lin_sched_slot_advance (lsSlot fr) take;
     lsGap := (lsGap fr -
       2 * N.to_nat (lin_sched_grants (lsSlot fr) take))%nat |}.
Definition lin_sched_grant_one (slot : N) : N :=
  if slot =? 0 then 1 else 0.
Definition lin_sched_slot_advance_one (slot : N) : N :=
  if slot =? 0 then 3
  else if slot =? 1 then 0
       else if slot =? 2 then 1 else 2.
Definition lin_sched_advance_one (fr : lsc_frame) : lsc_frame :=
  {| lsCur := lsCur fr;
     lsTicks := lsTicks fr - 1;
     lsSlot := lin_sched_slot_advance_one (lsSlot fr);
     lsGap := (lsGap fr -
       2 * N.to_nat (lin_sched_grant_one (lsSlot fr)))%nat |}.
Definition lin_sched_child
    (j : nat) (rem emit p take : N) : lsc_frame :=
  let full := N.to_nat ((p+take)/28) in
  {| lsCur := (j + phase_len rem)%nat;
     lsTicks := emit;
     lsSlot := lin_sched_slot p;
     lsGap := (2*full + 1)%nat |}.
Definition lin_sched_bulk_safe (fr : lsc_frame)
    (colflat : nat) (pk take : N) : bool :=
  let full := (pk+take)/28 in
  if full =? 0 then true
  else
    Nat.leb (lsGap fr) colflat &&
    Nat.leb (lsGap fr + 2)
      (colflat + 2 * N.to_nat (lin_sched_grants (lsSlot fr) (27-pk))).
Definition lin_dtick_after_seek (cols2 s3 : word) (f : N)
  : option (bool * word * N) :=
  match renew_seg (length s3) cols2 s3 f with
  | Some (body, f2) => Some (true, body, f2)
  | None =>
      match (match s3 with
             | (o7,z7,c7) :: _ =>
                 if (z7 =? 3) && (c7 =? 1)
                 then fire_comp (length s3) s3 f
                 else if sand_leaf s3 then None
                 else leaf_act s3 f
             | [] => leaf_act s3 f
             end) with
      | Some (s3', f2) => Some (false, cols2 ++ s3', f2)
      | None => None
      end
  end.
Fixpoint lin_bottom_sched_zrun (q lc : nat) (sg : list seg)
          (lw : word) (f : N) (gap : nat) (slot : N)
  : option (word * N) :=
  if lin_literal_word lw then
  match q with
  | O => Some (lw, f)
  | S q' =>
      let sf := skipn lc lw in
      let '(cols, s3) := seek sf in
      match s3 with
      | [] => None
      | _ :: _ =>
          match lin_dtick_after_seek cols s3 f with
          | Some (renewed, sfx, f2) =>
              if renewed then
                if negb (Nat.leb (gap + 2) (lin_flen sg cols))
                then None else
                match (if Nat.eqb lc O then Some sfx
                       else lin_join_safe sg (firstn lc lw) sfx) with
                | Some lw2 =>
                    lin_bottom_sched_zrun q' lc sg lw2 f2
                      (gap - 2 * N.to_nat (lin_sched_grant_one slot))%nat
                      (lin_sched_slot_advance_one slot)
                | None => None
                end
              else
                match (if Nat.eqb lc O then Some sfx
                       else lin_join_safe sg (firstn lc lw) sfx) with
                | Some lw2 =>
                    lin_bottom_sched_zrun q' lc sg lw2 f2
                      (gap - 2 * N.to_nat (lin_sched_grant_one slot))%nat
                      (lin_sched_slot_advance_one slot)
                | None => None
                end
          | None => None
          end
      end
  end
  else None.
Fixpoint lin_casc_safe_at (fu : nat) (sg : list seg) (ps : atab)
                  (w : word) (f : N) (st : list lsc_frame)
  : option (word * list seg * atab * N) :=
  match fu with
  | O => None
  | S fu' =>
      match st with
      | [] => Some (w, sg, ps, f)
      | fr :: rest =>
          let cur := lsCur fr in
          let tk := lsTicks fr in
          if tk =? 0 then lin_casc_safe_at fu' sg ps w f rest
          else
          let sf := skipn cur w in
          let '(cols2, s3) := seek sf in
          match s3 with
          | [] => None
          | _ :: _ =>
            let tg := (cur + length cols2)%nat in
            match lin_bottom_take cols2 s3 f tk with
            | Some take =>
                let basec := (cur - 2)%nat in
                let lc := (cur - basec)%nat in
                match lin_bottom_sched_zrun (N.to_nat take) lc sg
                        (skipn basec w) f (lsGap fr) (lsSlot fr) with
                | Some (lw2, f2) =>
                    let w2 := setsfx basec w lw2 in
                    match relocate_all sg ps w2 with
                    | Some ps2 =>
                        let st2 := lin_sched_advance fr take :: rest in
                        if lin_guard_at sg ps2 w2 then
                          lin_casc_safe_at fu' sg ps2 w2 f2 st2
                        else None
                    | None => None
                    end
                | None => None
                end
            | None =>
            match (if Nat.ltb (cur + 2) tg then
                     match detect_phase s3 O with
                     | Some pk =>
                         let take := lin_bulk_take sg w cur tg pk tk in
                         if THRESH <=? take
                         then match lin_bulk sg w tg pk take with
                              | Some (w2, sg2, t2, p2k, ek) =>
                                  Some (w2, sg2, t2, p2k, ek, take, pk)
                              | None => None
                              end
                         else None
                     | None => None
                     end
                   else None) with
            | Some (w2, sg2, t2, p2k, ek, take, pk) =>
                let colflat := lin_flen sg cols2 in
                if negb (lin_sched_bulk_safe fr colflat pk take)
                then None else
                match lin_at_safe sg2 w2 t2 with
                | Some w3 =>
                match locate_all sg2 w3 with
                | Some ps2 =>
                    if lin_guard_at sg2 ps2 w3 then
                      lin_casc_safe_at fu' sg2 ps2 w3 f
                        (lin_sched_child t2 p2k ek pk take ::
                         lin_sched_advance fr take :: rest)
                    else None
                | None => None
                end
                | None => None
                end
            | None =>
                match lin_dtick_after_seek cols2 s3 f with
                | Some (renewed, sfx, f2) =>
                    if renewed then
                      if negb (Nat.leb (lsGap fr + 2) (lin_flen sg cols2))
                      then None else
                      match (if Nat.eqb cur O then Some sfx
                             else lin_join_safe sg (firstn cur w) sfx) with
                      | Some w2 =>
                      match (if lin_same_length w w2
                             then Some ps else relocate_all sg ps w2) with
                      | Some ps2 =>
                          if lin_guard_at sg ps2 w2 then
                            lin_casc_safe_at fu' sg ps2 w2 f2
                              (lin_sched_advance_one fr :: rest)
                          else None
                      | None => None
                      end
                      | None => None
                      end
                    else
                      match (if Nat.eqb cur O then Some sfx
                             else lin_join_safe sg (firstn cur w) sfx) with
                      | Some w2 =>
                      match (if lin_same_length w w2
                             then Some ps else relocate_all sg ps w2) with
                      | Some ps2 =>
                          if lin_guard_at sg ps2 w2 then
                            lin_casc_safe_at fu' sg ps2 w2 f2
                              (lin_sched_advance_one fr :: rest)
                          else None
                      | None => None
                      end
                      | None => None
                      end
                | None => None
                end
            end
            end
          end
      end
  end.
Fixpoint lin_try_at (k : nat) (sg : list seg) (ps : atab)
                 (w : word) (f cN : N) (i : nat) (p : N) (m : nat)
  : option (N * word * list seg * atab * N * nat) :=
  match k with
  | O => None
  | S k' =>
      if Nat.eqb m O then None else
      let t := 28 * N.of_nat m - p in
      match lin_bulk sg w i p t with
      | None => None
      | Some (w1, sg1, j2, rem, emit) =>
          match lin_at_safe sg1
                  (subst_at O 1 [(2,2,cN + t)] w1) j2 with
          | Some w2 =>
          let fsite := fmapw sg1 w1 O O (j2 + 2)%nat in
          match locate_all sg1 w2 with
          | Some ps1 =>
              match lin_keep_at sg1 ps1 w2
                      [((j2 + phase_len rem)%nat, emit)] with
              | Some (sgA, psA, wA, stA) =>
                  match lin_casc_safe_at CFUEL sgA psA wA f
                          [lin_sched_child j2 rem emit p t] with
                  | Some (w3, sg3, ps3, f3) =>
                      Some (t, w3, sg3, ps3, f3, fsite)
                  | None => lin_try_at k' sg ps w f cN i p (Nat.div2 m)
                  end
              | None => lin_try_at k' sg ps w f cN i p (Nat.div2 m)
              end
          | None => lin_try_at k' sg ps w f cN i p (Nat.div2 m)
          end
          | None => lin_try_at k' sg ps w f cN i p (Nat.div2 m)
          end
      end
  end.
Definition lin_gen_action_at (front : option res)
                  (sg : list seg) (ps : atab)
                  (w : word) (f : N) (hint : nat)
  : option (option (N * word * list seg * atab * N * nat)) :=
  if negb (front_blind w) then None
  else match front with
  | Some _ => None
  | None =>
    if negb (f =? 4) then None else
    match w with
    | (2,2,cN) :: _ =>
      let start := if Nat.ltb hint 1 then 1%nat else hint in
      match find_active w start with
      | None => None
      | Some i =>
        if negb (Nat.ltb (S MARGIN) i) then None else
        if negb (forallb is_col (firstn i w)) then None else
        match detect_phase w i with
        | None => None
        | Some p =>
          let k := (i - 1)%nat in
          let clean1 :=
            if Nat.ltb k 1 then false
            else match wat w k, wat w (k - 1) with
                 | Some l, Some s => lvl_big l && spacer s
                 | _, _ => false
                 end in
          if negb clean1 then None
          else if negb (1 <=? cN)%N then Some None
          else
            let mmax := Nat.div2 (fmapw sg w O O i - MARGIN) in
            Some (lin_try_at TRIES sg ps w f cN i p
                    (lin_count_clean sg w k mmax))
        end
      end
    | _ => None
    end
  end.
Definition lin_tick_front_stage (w : word) (i : nat)
  : option (N * word * nat * N * N) :=
  if Nat.eqb i 7 then
    match w with
    | a0 :: a1 :: a2 :: a3 :: a4 :: sp :: lv
         :: (7,1,1) :: (3,2,1) :: (4,2,cg) :: ((_ :: _) as rest) =>
        if spacer sp && lvl_big lv && erode_safe 0 (4,2,cg)
        then Some (28,
               [a0;a1;a2;a3;a4; (7,1,1); (3,2,1); lv;
                (8,2,1); (4,2,cg-4)] ++ rest,
               5%nat, 0, 4)
        else None
    | _ => None
    end
  else if Nat.eqb i 6 then
    match wat w (i + phase_len 0)%nat with
    | Some gb =>
      if erode_safe 0 gb then
        match bulk_stage w i 0 28 with
        | Some (w1, j2, rem, emit) => Some (28, w1, j2, rem, emit)
        | None => None
        end
      else None
    | None => None
    end
  else if Nat.eqb i 5 then
    match w with
    | a0 :: a1 :: a2 :: a3 :: a4
         :: (7,1,1) :: (3,2,1) :: (4,2,cg) :: ((_ :: _) as rest) =>
        if erode_safe 0 (4,2,cg)
        then Some (27,
               [a0;a1;a2;a3;a4; (4,3,1); (4,2,cg-3)] ++ rest,
               5%nat, 27, 3)
        else None
    | _ => None
    end
  else None.
Definition lin_tick_front_at (front : option res)
                  (sg : list seg) (ps : atab)
                  (w : word) (f : N) (hint : nat)
  : option (N * word * list seg * atab * N * nat) :=
  match front with
  | Some _ => None
  | None =>
    if Nat.ltb (length sg) 2
       || negb (forallb (fun s => Nat.leb SEGMIN (segl s)) sg)
    then None else
    if negb (f =? 4) then None else
    match w with
    | (2,2,cN) :: _ =>
      if negb (1 <=? cN)%N then None else
      let start := if Nat.ltb hint 1 then 1%nat else hint in
      match find_active w start with
      | Some i =>
        if negb (lin_transfer_prefix w i) then None else
        match detect_phase w i with
        | Some p =>
          let q := if (Nat.eqb i 7 || Nat.eqb i 6) && (p =? 0) then 28
                   else if Nat.eqb i 5 && (p =? 0) then 27
                   else 0 in
          if q =? 0 then None else
          match lin_tick_front_stage w i with
          | Some (q, w1, j2, rem, emit) =>
              match (if Nat.eqb i 6
                     then lin_at_safe sg w1 j2 else Some w1) with
              | Some w1' =>
              let w2 := subst_at O 1 [(2,2,cN+q)] w1' in
              match relocate_all sg ps w2 with
              | Some ps1 =>
                  if lin_guard_at sg ps1 w2 then
                    match lin_casc_safe_at CFUEL sg ps1 w2 f
                            [lin_sched_child j2 rem emit p q] with
                    | Some (w3, sg3, ps3, f3) =>
                        Some (q, w3, sg3, ps3, f3, i)
                    | None => None
                    end
                  else None
              | None => None
              end
              | None => None
              end
          | None => None
          end
        | None => None
        end
      | None => None
      end
    | _ => None
    end
  end.
Definition lin_phase0_at (w : word) (i : nat) : bool :=
  match wat w i, wat w (S i) with
  | Some (7,1,1), Some (3,2,1) => true
  | _, _ => false
  end.
Definition lin_tick_front_due (w : word) : bool :=
  lin_phase0_at w 5 || lin_phase0_at w 6 || lin_phase0_at w 7.
Inductive lpstate : Type :=
  | LPFlat (w : word) (f : N) (h : nat)
  | LPCond (sg : list seg) (ps : atab) (cw : word)
           (f : N) (h j : nat).
Definition lp_sem (s : lpstate) : sstate :=
  match s with
  | LPFlat w f h => (w, f, h)
  | LPCond sg _ cw f _ j => (lin_flat sg cw, f, hint_of j)
  end.
Inductive lpnext : Type :=
  | LPNext (k : ncost) (m : nat) (s : lpstate)
  | LPGuard (k : ncost) (m : nat) (w : word) (f : N)
  | LPBad (k : ncost) (m : nat) (w : word) (f : N).
Definition repack_store (p : N) (g : bg) : bg :=
  let '(o, z, c) := g in
  if is_lvl g then (o, z, c + 4 * p) else g.
Fixpoint minlvl_from (b : word) (m : N) : N :=
  match b with
  | [] => m
  | g :: t => minlvl_from t (if is_lvl g then N.min m (gC g) else m)
  end.
Fixpoint repack_front_ok (b : word) : bool :=
  match b with
  | [] => true
  | l :: s :: t => lvl_big l && is_spc s && repack_front_ok t
  | _ => false
  end.
Fixpoint repack_back_ok (b : word) : bool :=
  match b with
  | [] => true
  | s :: l :: t => is_spc s && lvl_big l && repack_back_ok t
  | _ => false
  end.
Definition repack_edges_ok (rpre post : word) (lb la : nat) : bool :=
  is_spc (nth lb rpre d0) && is_spc (nth la post d0).
Definition repack_one (sg : list seg) (w : word) (key : N)
  : option (list seg * word) :=
  match locate_key w key with
  | None => None
  | Some i =>
      let '(pre, here) := lin_split_at i w in
      match here with
      | [] => None
      | g :: post =>
          match keyi sg g with
          | None => None
          | Some s =>
              let rpre := rev pre in
              let nb := cleanrun sg rpre i in
              let na := cleanrun sg post (length post) in
              let kb := Nat.div2 (nb - MARG) in
              let ka := Nat.div2 (na - MARG) in
              let lb := (2 * kb)%nat in
              let la := (2 * ka)%nat in
              let cut := (i - lb)%nat in
              let fr := rev (firstn lb rpre) in
              let bk := firstn la post in
              if repack_front_ok fr && repack_back_ok bk then
              if repack_edges_ok rpre post lb la then
                let frs := map (repack_store (sPend s)) fr in
                let bks := map (repack_store (sPend s)) bk in
                let mn := minlvl_from bks (minlvl_from frs (sMin s)) in
                let s2 := (sKey s, sPend s, mn,
                           (sLen s + lb + la)%nat,
                           frs ++ sFront s, rev bks ++ sBack s,
                           sCsum s + bsum fr + bsum bk) in
                Some (sgset sg key s2,
                      firstn cut pre ++ [g] ++ skipn la post)
              else None
              else None
          end
      end
  end.
Fixpoint repack_keys (keys : list N) (sg : list seg) (w : word)
  : option (list seg * word) :=
  match keys with
  | [] => Some (sg, w)
  | k :: ks =>
      match repack_one sg w k with
      | Some (sg2, w2) => repack_keys ks sg2 w2
      | None => None
      end
  end.
Definition casc_real (sg : list seg) (g : bg) : bool :=
  casc g && negb (ph sg g).
Fixpoint takerun_real (sg : list seg) (w : word) : word * word :=
  match w with
  | g :: t =>
      if casc_real sg g
      then let '(a, b) := takerun_real sg t in (g :: a, b)
      else ([], w)
  | [] => ([], [])
  end.
Fixpoint lplan_real (fu : nat) (sg : list seg) (w : word) (i : nat)
  : list (nat * nat) :=
  match fu with
  | O => []
  | S fu' =>
      match w with
      | [] => []
      | g :: t =>
          if casc_real sg g then
            let '(r, rest) := takerun_real sg w in
            let n := length r in
            if Nat.leb (2 * MARG + SEGMIN_GROUPS) n then
              let a := if is_lvl (nth MARG r d0) then MARG else S MARG in
              let b0 := (n - MARG)%nat in
              let b := if is_lvl (nth (b0 - 1) r d0) then b0 else (b0 - 1)%nat in
              if is_spc (nth (a - 1) r d0) && is_spc (nth b r d0)
                 && Nat.ltb a b
              then ((i + a)%nat, (b - a)%nat)
                     :: lplan_real fu' sg rest (i + n)
              else lplan_real fu' sg rest (i + n)
            else lplan_real fu' sg rest (i + n)
          else lplan_real fu' sg t (S i)
      end
  end.
Fixpoint fresh_key (sg : list seg) (k : N) : N :=
  match sg with
  | [] => k
  | s :: sg' => fresh_key sg' (N.max k (sKey s + 1))
  end.
Definition lin_extend (sg : list seg) (w : word)
  : option (list seg * word) :=
  match lplan_real (length w) sg w O with
  | [] => Some (sg, w)
  | pl =>
      let '(w2, added) := lapply pl w O (fresh_key sg KMAGIC) in
      let sg2 := sg ++ added in
      if forallb (fun s => segcache s && segok s) added && lin_ok sg2 w2
      then if forallb segshape added
           then if forallb segpos added then Some (sg2, w2) else None
           else None
      else None
  end.
Definition LZONE_MAX : nat := 150.
Definition lin_repack (sg : list seg) (w : word)
  : option (list seg * atab * word) :=
  match repack_keys (map sKey sg) sg w with
  | None => None
  | Some (sg2, w2) =>
      match (if Nat.leb (length w2) LZONE_MAX
             then Some (sg2, w2) else lin_extend sg2 w2) with
      | None => None
      | Some (sg3, w3) =>
      match locate_all sg3 w3 with
      | Some ps2 =>
          if lin_guard_at sg3 ps2 w3 then
            if lin_tags sg3 w3 then Some (sg3, ps2, w3) else None
          else None
      | None => None
      end
      end
  end.
Definition lin_round_closing (w : word) (f : N) : bool :=
  match fr_clean w f with
  | Some _ => true
  | None => match fr_four w f with Some _ => true | None => false end
  end.
Definition lin_front_done (q : nat) (r : option res)
  : option (nat * word * N) :=
  match r with
  | Some (ROk w f) => Some (q, lin_normalize_full w, f)
  | _ => None
  end.
Inductive lin_front_shape : word -> Type :=
  | LFS522 (c k M : N) (rest : word) :
      lin_front_shape
        ((2,2,c) :: (4,1,1) :: (k,1,1) :: (4,1,M) :: rest)
  | LFS512 (c k K : N) (rest : word) :
      lin_front_shape
        ((2,2,c) :: (5,1,1) :: (k,1,1) :: (3,1,K) :: rest)
  | LFS502 (c K : N) (rest : word) :
      lin_front_shape ((2,2,c) :: (5,1,1) :: (3,1,K) :: rest)
  | LFSrot (K : N) (rest : word) :
      lin_front_shape ((5,1,1) :: (4,1,1) :: (3,1,K) :: rest).
Definition lin_front_shape_of (w : word) : option (lin_front_shape w) :=
  match w as w0 return option (lin_front_shape w0) with
  | (2,2,c) :: (4,1,1) :: (k,1,1) :: (4,1,M) :: rest =>
      Some (LFS522 c k M rest)
  | (2,2,c) :: (5,1,1) :: (k,1,1) :: (3,1,K) :: rest =>
      Some (LFS512 c k K rest)
  | (2,2,c) :: (5,1,1) :: (3,1,K) :: rest =>
      Some (LFS502 c K rest)
  | (5,1,1) :: (4,1,1) :: (3,1,K) :: rest =>
      Some (LFSrot K rest)
  | _ => None
  end.
Definition lin_front_shape_run {w : word} (s : lin_front_shape w) (f : N)
  : option (nat * word * N) :=
  match s with
  | LFS522 c k M rest =>
      if k =? 1 then
        lin_front_done 2
          (fr_four ((2,2,c+1) :: (4,2,1) :: (4,1,M) :: rest) f)
      else if k =? 2 then
        lin_front_done 3
          (fr_four ((2,2,c+2) :: (4,2,1) :: (4,1,M) :: rest) f)
      else if k =? 3 then
        lin_front_done 4
          (fr_four ((2,2,c+3) :: (4,2,1) :: (4,1,M) :: rest) f)
      else None
  | LFS512 c k K rest =>
      if (c + k =? 4) && (2 <=? K) then
        if k =? 1 then
          lin_front_done 2
            (fr_clean ((2,2,4) :: (5,2,1) :: (3,1,K) :: rest) f)
        else if k =? 2 then
          lin_front_done 3
            (fr_clean ((2,2,4) :: (5,2,1) :: (3,1,K) :: rest) f)
        else None
      else None
  | LFS502 c K rest =>
      if (c =? 1) && (3 <=? K) then
        lin_front_done 4
          (fr_clean ((2,2,4) :: (5,2,1) :: (3,1,K-1) :: rest) f)
      else None
  | LFSrot K rest =>
      if 2 <=? K then
        lin_front_done 5
          (fr_clean ((2,2,4) :: (5,2,1) :: (3,1,K) :: rest) f)
      else None
  end.
Definition lin_front_close (w : word) (f : N)
  : option (nat * word * N) :=
  match lin_front_shape_of w with
  | Some s => lin_front_shape_run s f
  | None => None
  end.
Definition lin_zsp (w : word) (f : N) (h : nat)
  : option (N * sstate * cost) :=
  match zjump3 w f h with
  | Some (t, st) => Some (t, st, czero)
  | None => None
  end.
Lemma lin_zsp_proj (w : word) (f : N) (h : nat)
      (t : N) (st : sstate) (d : cost) :
  lin_zsp w f h = Some (t, st, d) ->
  zjump3 w f h = Some (t, st).
Proof.
  unfold lin_zsp. destruct (zjump3 w f h)
    as [[t' st']|] eqn:E; [|discriminate].
  intros H. injection H as <- <- <-. reflexivity.
Qed.
Definition FLAT_ROUND_FUEL : nat := 500.
Fixpoint lp_fallback_round_run
         (fu : nat) (T : ctot) (w : word) (f : N) (h : nat)
         (k : ncost) (m : nat)
  : lpnext :=
  match fu with
  | O => LPNext k m (LPFlat w f h)
  | S fu' =>
      match lin_zsp w f h with
      | Some (k2, (w2, f2, h2), dz) =>
          lp_fallback_round_run fu' None w2 f2 h2
            (nc_rbump k k2) (S m)
      | None =>
          match step w f h with
          | (ROk w2 f2, i) =>
              let h2 := if Nat.ltb i 5 then O else (i - 4)%nat in
              if lin_round_closing w f
              then let dcl := snd (cstep w f h) in
                   LPNext (nc_bump k 1 dcl dcl) (S m)
                     (LPFlat w2 f2 h2)
              else lp_fallback_round_run fu' None w2 f2 h2
                     (nc_qbump k 1 czero) (S m)
          | (RHalt, _) =>
              let dg := snd (cstep w f h) in
              LPGuard (nc_bump k 0 dg dg) m w f
          | (RBad, _) => LPBad k m w f
          end
      end
  end.
Definition lp_fallback_round (w : word) (f : N) (h : nat) : lpnext :=
  lp_fallback_round_run FLAT_ROUND_FUEL None w f h nc0 O.
Definition lin_front_possible (w : word) : bool :=
  match w with
  | (o0,z0,_) :: (o1,z1,_) :: (o2,z2,_) :: (o3,z3,_) :: _ :: _ :: _ =>
      if negb ((o0 =? 2) && (z0 =? 2)) then true else
      if ((o1 =? 5) && (z1 =? 1)) || ((o1 =? 4) && (z1 =? 1))
      then true
      else if (o1 =? 5) && (z1 =? 2) then
        if (o2 =? 3) && (z2 =? 1) then true
        else if (o2 =? 3) && (z2 =? 2) then
          ((o3 =? 3) && (z3 =? 3))
          || ((o3 =? 2) && (z3 =? 2))
          || match find_active w 3 with None => true | Some _ => false end
        else false
      else if (o1 =? 4) && (z1 =? 2) then
        ((o2 =? 4) && ((z2 =? 1) || (z2 =? 3)))
        || ((o2 =? 3) && (z2 =? 2))
      else false
  | _ => true
  end.
Definition lin_splice_guard (w : word) (i : nat) : bool :=
  if lin_front_possible w then lin_shape_guard w
  else if lin_literal_word (firstn 7 w)
       then lin_literal_word (skipn (i - 3) w)
       else false.
Definition lin_splice_guard_complete (w : word) (i : nat) : bool :=
  if lin_splice_guard w i then true else lin_shape_guard w.
Definition lin_leaf_site (w : word) (i : nat) : bool :=
  match skipn i w with
  | (_, z, _) :: _ => (z =? 1)%N
  | [] => false
  end.
Definition lin_splice_arm_guard (front : option res) (w : word)
    (i : nat) : bool :=
  match front with
  | Some _ => lin_shape_guard w
  | None =>
      if lin_leaf_site w i then true else lin_splice_guard_complete w i
  end.
Definition lin_micro_action_guard (front : option res) (w : word)
    (h : nat) : bool :=
  match front with
  | Some _ => true
  | None =>
      match find_active w (if Nat.ltb h 1 then 1%nat else h) with
      | Some _ => true
      | None => false
      end
  end.
Lemma lin_micro_action_guard_sound (front : option res) (w : word)
      (h : nat) :
  lin_micro_action_guard front w h = true ->
  ~ (front = None /\
     find_active w (if Nat.ltb h 1 then 1%nat else h) = None).
Proof.
  unfold lin_micro_action_guard.
  destruct front as [r|]; [intros _ [H _]; discriminate H|].
  destruct (find_active w (if Nat.ltb h 1 then 1%nat else h));
    intros H [_ HF]; try discriminate; congruence.
Qed.
Definition lin_micro_post (sg : list seg) (ps : atab) (w : word) (i : nat)
  : option (list seg * atab * word * nat) :=
  if lin_near_at ps i GUARD then
    let fi := fmapw sg w O O i in
    match lin_fixup_at sg ps w [] with
    | Some (sg2, ps2, w2, _) =>
        Some (sg2, ps2, w2, hmapw sg2 w2 O O fi)
    | None => None
    end
  else if lin_guard_at sg ps w
       then Some (sg, ps, w, i)
       else
         let fi := fmapw sg w O O i in
         match lin_fixup_at sg ps w [] with
         | Some (sg2, ps2, w2, _) =>
             Some (sg2, ps2, w2, hmapw sg2 w2 O O fi)
         | None => None
         end.
Definition lin_step_post (front : option res)
                  (sg : list seg) (ps : atab) (w : word) (i : nat)
  : option (list seg * atab * word * nat) :=
  match front with
  | None => lin_micro_post sg ps w i
  | Some _ =>
      let fi := fmapw sg w O O i in
      match lin_fixup_at sg ps w [] with
      | Some (sg2, ps2, w2, _) =>
          Some (sg2, ps2, w2, hmapw sg2 w2 O O fi)
      | None => None
      end
  end.
Definition lin_halt_probe (front : option res) (sg : list seg)
                          (w : word) (f : N) (h : nat) : bool :=
  match step_after_front_trusted_splice_with
          (lin_normalize_at sg)
          (fun pre sfx _ => lin_normalize_join sg pre sfx)
          front w f h with
  | (RHalt, _) => true
  | _ => false
  end.
Definition lin_halt_confirm (sg : list seg) (cw : word) (f : N)
  : bool * cost :=
  match cstep (lin_flat sg cw) f O with
  | (RHalt, _, d) => (true, d)
  | (_, _, _) => (false, cundef)
  end.
Inductive lrstop : Type := LRFuel | LRMore | LRClosed | LRHalt.
Definition lround_result : Type :=
  (list seg * atab * word * N * nat * nat * ncost * nat * lrstop)%type.
Fixpoint lin_run_round (fu : nat) (sg : list seg) (ps : atab)
                 (cw : word) (f : N) (h : nat) (jc : nat) (n : ncost)
                 (m : nat)
  : lround_result :=
  match fu with
  | O => (sg, ps, cw, f, h, jc, n, m, LRFuel)
  | S fu' =>
      let '(sg0, ps0, cw0) := (sg, ps, cw) in
        match lin_front_close cw0 f with
        | Some (q, cw2, f2) =>
            match relocate_all sg0 ps0 cw2 with
            | Some ps2 =>
                if front_late cw0 then
                  let dc := dfci cw0 f in
                  (sg0, ps2, cw2, f2, O, O,
                   nc_bump n (N.of_nat q) dc dc,
                   (m + q)%nat, LRClosed)
                else
                  (sg0, ps2, cw2, f2, O, O,
                   nc_ebump n (N.of_nat q),
                   (m + q)%nat, LRClosed)
            | None => (sg0, ps0, cw0, f, h, jc, n, m, LRMore)
            end
        | None =>
        let front := if lin_front_possible cw0
                     then first_rule front_rules cw0 f else None in
        match lin_gen_action_at front sg0 ps0 cw0 f h with
        | Some (Some (t, cw2, sg2, ps2, f2, fs)) =>
            let jc2 := hmapw sg2 cw2 O O fs in
            lin_run_round fu' sg2 ps2 cw2 f2
              (hmapw sg2 cw2 O O (hint_of fs)) jc2
              (nc_fbump n t) (S m)
        | Some None =>
            if lin_halt_probe front sg0 cw0 f h
            then (let hc := lin_halt_confirm sg0 cw0 f in
                  if fst hc
                  then (sg0, ps0, cw0, f, h, jc,
                        nc_bump n 0 (snd hc) (snd hc), m, LRHalt)
                  else (sg0, ps0, cw0, f, h, jc, n, m, LRMore))
            else (sg0, ps0, cw0, f, h, jc, n, m, LRMore)
        | None =>
          match (if lin_tick_front_due cw0
                 then lin_tick_front_at front sg0 ps0 cw0 f h
                 else None) with
          | Some (q, cw2, sg2, ps2, f2, fs) =>
              let jc2 := hmapw sg2 cw2 O O fs in
              lin_run_round fu' sg2 ps2 cw2 f2
                (hmapw sg2 cw2 O O (hint_of fs)) jc2
                (nc_fbump n q)
                (m + N.to_nat q)%nat
          | None =>
          let closing := lin_round_closing cw0 f in
          if lin_micro_action_guard front cw0 h then
          match step_after_front_with_guard false
                  (lin_normalize_at sg0)
                  (fun pre sfx _ => lin_normalize_join sg0 pre sfx)
                  front cw0 f h with
          | (ROk cw2 f2, i) =>
              if lin_splice_arm_guard front cw0 i then
                match relocate_all sg0 ps0 cw2 with
                | Some ps2 =>
                    if closing then
                      (sg0, ps2, cw2, f2, hint_of i, i,
                       nc_bump n 1 (0, CLOSE_UB) czero,
                       S m, LRClosed)
                    else
                      match lin_step_post front sg0 ps2 cw2 i with
                      | Some (sg3, ps3, cw3, i3) =>
                          lin_run_round fu' sg3 ps3 cw3 f2
                            (hint_of i3) i3
                            (nc_qbump n 1 czero) (S m)
                      | None => (sg0, ps0, cw0, f, h, jc, n, m, LRMore)
                      end
                | None =>
                    (sg0, ps0, cw0, f, h, jc, n, m, LRMore)
                end
              else (sg0, ps0, cw0, f, h, jc, n, m, LRMore)
          | (RHalt, _) =>
              let hc := lin_halt_confirm sg0 cw0 f in
              if fst hc
              then (sg0, ps0, cw0, f, h, jc,
                    nc_bump n 0 (snd hc) (snd hc), m, LRHalt)
              else (sg0, ps0, cw0, f, h, jc, n, m, LRMore)
          | _ => (sg0, ps0, cw0, f, h, jc, n, m, LRMore)
          end
          else (sg0, ps0, cw0, f, h, jc, n, m, LRMore)
          end
        end
        end
  end.
Definition LROUND_FUEL : nat := 1000.
Definition LROUND_CHUNKS : nat := 8.
Fixpoint lin_run_round_chunked (chunks : nat)
                 (sg : list seg) (ps : atab)
                 (cw : word) (f : N) (h : nat) (jc : nat)
                 (n : ncost) (m : nat)
  : list seg * atab * word * N * nat * ncost * nat * lrstop :=
  match chunks with
  | O => (sg, ps, cw, f, jc, n, m, LRMore)
  | S chunks' =>
      let '(sg2, ps2, cw2, f2, h2, j2, n2, m2, stop) :=
        lin_run_round LROUND_FUEL sg ps cw f h jc n m in
      match stop with
      | LRFuel =>
          lin_run_round_chunked chunks' sg2 ps2 cw2 f2
            h2 j2 n2 m2
      | _ => (sg2, ps2, cw2, f2, j2, n2, m2, stop)
      end
  end.
Definition lin_repack_needed_one (sg : list seg) (w : word) (p : nat)
  : bool :=
  let cap := (MARG + 2)%nat in
  let lo := (p - cap)%nat in
  let before := firstn (p - lo) (skipn lo w) in
  let nb := cleanrun sg (rev before) cap in
  let na := cleanrun sg (skipn (S p) w) cap in
  Nat.leb cap nb || Nat.leb cap na.
Fixpoint lin_repack_needed (sg : list seg) (ps : atab) (w : word) : bool :=
  match ps with
  | [] => false
  | p :: ps' => lin_repack_needed_one sg w p || lin_repack_needed sg ps' w
  end.
Definition lin_repack_when_needed (sg : list seg) (ps : atab) (cw : word)
  : option (list seg * atab * word) :=
  if Nat.ltb LZONE_MAX (length cw) || lin_repack_needed sg ps cw
  then lin_repack sg cw
  else if lin_guard_at sg ps cw then Some (sg, ps, cw)
       else lin_repack sg cw.
Definition lr_accept (closed : bool) (sg : list seg) (ps : atab) (cw : word)
                     (f : N) (jc : nat) (k : ncost) (m : nat)
  : option lpnext :=
  if Nat.eqb m O then None
  else
    let jflat := fmapw sg cw O O jc in
    let hflat := hint_of jflat in
    if closed || Nat.eqb m LROUND_FUEL
    then
      match lin_repack_when_needed sg ps cw with
      | Some (sg2, ps2, cw2) =>
          if negb (lin_ok sg2 cw2) then None
          else match sg2 with
               | [] => Some (LPNext k m (LPFlat cw2 f hflat))
               | _ :: _ => Some (LPNext k m
                            (LPCond sg2 ps2 cw2 f
                              (hmapw sg2 cw2 O O hflat) jflat))
               end
      | None => None
      end
    else if negb (lin_post_full sg cw) then None
         else Some (LPNext k m (LPFlat (lin_flat sg cw) f hflat)).
Definition lr_continue_flat (sg : list seg) (cw : word) (f : N)
                            (jc : nat) (k : ncost) (m : nat)
  : option lpnext :=
  if Nat.eqb m O then None
  else if negb (lin_post_full sg cw) then None
  else
    let jflat := fmapw sg cw O O jc in
    Some (lp_fallback_round_run FLAT_ROUND_FUEL None
            (lin_flat sg cw) f (hint_of jflat) k m).
Definition lmeas (w : word) (f : N) : N := ccolcost w + 2 * f.
Inductive lpsnext : Type :=
  | LPSNext (k : ncost) (m : nat) (s : lpstate)
  | LPSGuard (k : ncost) (m : nat) (flat_len : nat) (f : N) (lm : N)
  | LPSBad (k : ncost) (m : nat) (flat_len : nat) (f : N) (lm : N).
Definition lps_of_lpnext (r : lpnext) : lpsnext :=
  match r with
  | LPNext k m s => LPSNext k m s
  | LPGuard k m w f => LPSGuard k m (length w) f (lmeas w f)
  | LPBad k m w f => LPSBad k m (length w) f (lmeas w f)
  end.
Definition linstep (s : lpstate) : lpsnext :=
  match s with
  | LPFlat w f h =>
      match lin_cond w h with
      | None => lps_of_lpnext (lp_fallback_round w f h)
      | Some (cw, sg, h0) =>
          match locate_all sg cw with
          | None => lps_of_lpnext (lp_fallback_round w f h)
          | Some ps =>
              let '(sg2, ps2, cw2, f2, j2, k, m, stop) :=
                lin_run_round_chunked LROUND_CHUNKS
                  sg ps cw f h0 O nc0 O in
              match stop with
              | LRHalt => LPSGuard k m (lin_flen sg2 cw2) f2
                            (lmeas (lin_flat sg2 cw2) f2)
              | LRFuel =>
                  match lr_continue_flat sg2 cw2 f2 j2 k m with
                  | Some r => lps_of_lpnext r
                  | None => lps_of_lpnext (lp_fallback_round w f h)
                  end
              | LRClosed =>
                  match lr_accept true sg2 ps2 cw2 f2 j2 k m with
                  | Some r => lps_of_lpnext r
                  | None => lps_of_lpnext (lp_fallback_round w f h)
                  end
              | LRMore =>
                  match lr_continue_flat sg2 cw2 f2 j2 k m with
                  | Some r => lps_of_lpnext r
                  | None => lps_of_lpnext (lp_fallback_round w f h)
                  end
              end
          end
      end
  | LPCond sg ps cw f h j =>
      let '(sg2, ps2, cw2, f2, j2, k, m, stop) :=
        lin_run_round_chunked LROUND_CHUNKS sg ps cw f h
          (hmapw sg cw O O j) nc0 O in
      match stop with
      | LRHalt => LPSGuard k m (lin_flen sg2 cw2) f2
                    (lmeas (lin_flat sg2 cw2) f2)
      | LRFuel =>
          match lr_continue_flat sg2 cw2 f2 j2 k m with
          | Some r => lps_of_lpnext r
          | None => lps_of_lpnext
                      (lp_fallback_round (lin_flat sg cw) f (hint_of j))
          end
      | LRClosed =>
          match lr_accept true sg2 ps2 cw2 f2 j2 k m with
          | Some r => lps_of_lpnext r
          | None => lps_of_lpnext
                      (lp_fallback_round (lin_flat sg cw) f (hint_of j))
          end
      | LRMore =>
          match lr_continue_flat sg2 cw2 f2 j2 k m with
          | Some r => lps_of_lpnext r
          | None => lps_of_lpnext
                      (lp_fallback_round (lin_flat sg cw) f (hint_of j))
          end
      end
  end.
Inductive lsummary : Type :=
  | LSGuard (flat_len : nat) (f : N) (n : ncost) (lm : N)
  | LSOut (flat_len : nat) (f : N) (n : ncost) (lm : N)
  | LSBad (flat_len : nat) (f : N) (n : ncost) (lm : N).
Definition lsm (r : lsummary) : N :=
  match r with
  | LSGuard _ _ _ lm => lm
  | LSOut _ _ _ lm => lm
  | LSBad _ _ _ lm => lm
  end.
Definition lsn (r : lsummary) : ncost :=
  match r with
  | LSGuard _ _ n _ => n
  | LSOut _ _ n _ => n
  | LSBad _ _ n _ => n
  end.
Inductive lpsacc : Type :=
  | LPSRunning (s : lpstate) (n : ncost)
  | LPSFinished (r : lsummary).
Definition lps_once (a : lpsacc) : lpsacc :=
  match a with
  | LPSFinished r => LPSFinished r
  | LPSRunning s n =>
      match linstep s with
      | LPSNext k _ s2 => LPSRunning s2 (nc_add n k)
      | LPSGuard k _ len f lm => LPSFinished (LSGuard len f (nc_add n k) lm)
      | LPSBad k _ len f lm => LPSFinished (LSBad len f (nc_add n k) lm)
      end
  end.
Fixpoint lps_run_pos (p : positive) (a : lpsacc) : lpsacc :=
  match p with
  | xH => lps_once a
  | xO q => lps_run_pos q (lps_run_pos q a)
  | xI q => lps_once (lps_run_pos q (lps_run_pos q a))
  end.
Definition lps_finish (a : lpsacc) : lsummary :=
  match a with
  | LPSFinished r => r
  | LPSRunning (LPFlat w f _) n => LSOut (length w) f n (lmeas w f)
  | LPSRunning (LPCond sg _ cw f _ _) n =>
      LSOut (lin_flen sg cw) f n (lmeas (lin_flat sg cw) f)
  end.
Definition lin_brunN (fuel : N) (w : word) (f : N)
                     (h : nat) (n : ncost) : lsummary :=
  match fuel with
  | N0 => LSOut (length w) f n (lmeas w f)
  | Npos p =>
      lps_finish (lps_run_pos p (LPSRunning (LPFlat w f h) n))
  end.
Definition lin_brun (fuel : nat) (w : word) (f : N)
                    (h : nat) (n : ncost) : lsummary :=
  lin_brunN (N.of_nat fuel) w f h n.
Set Warnings "-require-in-module".
