Local Open Scope N_scope.
Definition CL (d : cost) : Prop := (1 <= clo d)%N /\ clo d = chi d.
Lemma CL_cx (k : N) : (1 <= k)%N -> CL (cx k).
Proof. intros H. split; [exact H|reflexivity]. Qed.
Lemma CL_cadd_ex (a b : cost) :
  clo a = chi a -> CL b -> CL (cadd a b).
Proof. unfold CL, cadd, clo, chi; cbn [fst snd]; lia. Qed.
Lemma CL_cadd_cx (k : N) (b : cost) : CL b -> CL (cadd (cx k) b).
Proof. intros H. apply CL_cadd_ex; [reflexivity|exact H]. Qed.
Theorem cleaf_act_live (s : word) (f : N) (s' : word) (f' : N) :
  fst (cleaf_act s f) = Some (s', f') ->
  CL (snd (cleaf_act s f)).
Proof.
  revert f s' f'.
  induction s as [|g s IH]; intros f s' f' HS; [cbn in HS; discriminate|].
  destruct g as [[X z] c].
  destruct z as [|zp].
  { cbn in HS; discriminate. }
  destruct zp as [zp'|zp'|].
  -   cbn in HS; discriminate.
  - destruct zp' as [q|q|]; try (cbn in HS; discriminate).
    destruct c as [|cp]; [cbn in HS; discriminate|].
    destruct cp as [cp'|cp'|]; try (cbn in HS; discriminate).
    cbn [cleaf_act] in HS |- *.
    destruct ((5 <=? X) && negb (X =? 8) && negb (X =? 12))%bool eqn:EG;
      [|cbn in HS; discriminate].
    destruct s as [|[[on zn] cn] t2].
    {
      cbn [fst snd] in HS |- *. unfold d_cma_far in *.
      destruct (f =? 3); [apply CL_cx; lia|].
      destruct (f =? 2); [apply CL_cx; lia|].
      destruct (f =? 4); [apply CL_cx; lia|].
      discriminate HS. }
    destruct (on =? 1); [cbn [fst] in HS; discriminate|].
    destruct ((on =? 3) && (zn =? 2) && (cn =? 1) && (f =? 4))%bool eqn:EM.
    { cbn [snd]. unfold d_cma_marker. apply CL_cx; lia. }
    destruct ((on =? 4) && (zn =? 2))%bool eqn:ER.
    { cbn [snd]. unfold d_cma_respawn_at.
      destruct t2 as [|[[o2 z2] c2] [|[[o3 z3] c3] [|g4 t4]]].
      - unfold d_cma_respawn_final. apply CL_cx; lia.
      - cbn [fst] in HS; discriminate.
      - unfold d_cma_respawn_orphan. apply CL_cx; lia.
      - cbn [fst] in HS; discriminate. }
    destruct ((X =? 6) && (on =? 2) && (zn =? 2) && (cn =? 1) && (f =? 4)
              && match t2 with
                 | [(o2,z2,_)] => (o2 =? 4) && (z2 =? 2)
                 | _ => false
                 end)%bool eqn:E6.
    { cbn [snd]. unfold d_cma_622. apply CL_cx; lia. }
    destruct ((zn =? 1)
              || ((zn =? 2) && (cn =? 1) && (5 <=? on)
                  && negb (on =? 8) && negb (on =? 12)))%bool eqn:EP.
    {
      rewrite cmap_fst in HS. cbv beta in HS.
      apply optmap_pair_some in HS. destruct HS as (s2 & f2 & EI).
      specialize (IH f s2 f2 EI).
      unfold cmap. cbn [snd]. unfold d_thru.
      apply CL_cadd_cx. exact IH. }
    cbn [fst] in HS; discriminate.
  -
    cbn [cleaf_act] in HS |- *.
    cbn [snd]. unfold d_tick. apply CL_cx; lia.
Qed.
Definition CE (d : cost) : Prop := clo d = chi d.
Lemma CE_of_CL (d : cost) : CL d -> CE d.
Proof. intros (_ & H). exact H. Qed.
Lemma CE_cx (k : N) : CE (cx k).
Proof. reflexivity. Qed.
Lemma CE_czero : CE czero.
Proof. reflexivity. Qed.
Lemma CE_cadd (a b : cost) : CE a -> CE b -> CE (cadd a b).
Proof. unfold CE, cadd, clo, chi; cbn [fst snd]; lia. Qed.
Lemma seek_cols (w cols s : word) :
  seek w = (cols, s) -> forallb is_col cols = true.
Proof.
  revert cols s. induction w as [|g t IH]; intros cols s E.
  - injection E as <- <-. reflexivity.
  - cbn [seek] in E.
    destruct (is_col g && negb (is_cmf g)
              && (3 <=? gO g))%bool eqn:EG.
    + destruct (seek t) as [ct st] eqn:ET.
      injection E as <- <-. cbn [forallb].
      apply andb_prop in EG as [EG _].
      apply andb_prop in EG as [Hcol _].
      rewrite Hcol. exact (IH ct st eq_refl).
    + injection E as <- <-. reflexivity.
Qed.
Definition seg_shape (gao gaz gac gbo gbz gbc : N) : bool :=
  ((gao =? 8) && (gaz =? 2) && (gac =? 1)
   && (gbo =? 4) && (gbz =? 2) && (1 <=? gbc))
  || ((gbo =? 8) && (gbz =? 2) && (gbc =? 1)).
Lemma cseg_some_of_shape (cols : word) :
  forallb is_col cols = true ->
  (match last2 cols with
   | Some (_, (gao,gaz,gac), (gbo,gbz,gbc)) =>
       seg_shape gao gaz gac gbo gbz gbc
   | None => false
   end) = true ->
  exists pc gbc, cseg cols = Some (pc, gbc).
Proof.
  intros HC HS.
  destruct (last2 cols)
    as [[[ini [[gao gaz] gac]] [[gbo gbz] gbc]]|] eqn:EL;
    [|discriminate].
  pose proof (last2_app cols ini (gao,gaz,gac) (gbo,gbz,gbc) EL)
    as EC. subst cols.
  rewrite !forallb_app in HC. cbn [forallb] in HC.
  apply andb_prop in HC as [Hini Htail].
  apply andb_prop in Htail as [Hga Htail].
  apply andb_prop in Htail as [Hgb _].
  unfold seg_shape in HS.
  set (A := ((gao =? 8) && (gaz =? 2) && (gac =? 1)
             && (gbo =? 4) && (gbz =? 2) && (1 <=? gbc))%bool) in *.
  set (B := ((gbo =? 8) && (gbz =? 2) && (gbc =? 1))%bool) in *.
  unfold cseg. rewrite EL.
  destruct A eqn:EA.
  - fold A. rewrite EA, Hini.
    exists (ccolcost ini), gbc. reflexivity.
  - cbn [orb] in HS.
    assert (HP : forallb is_col (ini ++ [(gao,gaz,gac)]) = true).
    { rewrite forallb_app, Hini. cbn [forallb]. rewrite Hga. reflexivity. }
    fold A B. rewrite EA, HS, HP.
    exists (ccolcost (ini ++ [(gao,gaz,gac)])), 0%N.
    reflexivity.
Qed.
Lemma endR_seg_shape (cols body : word) (f : N) :
  endR_seg cols f = Some body ->
  (match last2 cols with
   | Some (_, (gao,gaz,gac), (gbo,gbz,gbc)) =>
       seg_shape gao gaz gac gbo gbz gbc
   | None => false
   end) = true.
Proof.
  unfold endR_seg.
  destruct (last2 cols)
    as [[[ini [[gao gaz] gac]] [[gbo gbz] gbc]]|]; [|discriminate].
  cbv beta iota.
  set (A := ((gao =? 8) && (gaz =? 2) && (gac =? 1)
             && (gbo =? 4) && (gbz =? 2) && (1 <=? gbc))%bool).
  set (B := ((gbo =? 8) && (gbz =? 2) && (gbc =? 1))%bool).
  destruct (A && (2 <=? f))%bool eqn:EA.
  - intros _. apply andb_prop in EA as [EA _].
    unfold seg_shape. fold A B. rewrite EA. reflexivity.
  - destruct (B && (2 <=? f))%bool eqn:EB; [|discriminate].
    intros _. apply andb_prop in EB as [EB _].
    unfold seg_shape. fold A B. rewrite EB, Bool.orb_true_r. reflexivity.
Qed.
Lemma endR_seg_f_live (cols body : word) (f : N) :
  endR_seg cols f = Some body -> (2 <=? f)%N = true.
Proof.
  unfold endR_seg.
  destruct (last2 cols)
    as [[[ini [[gao gaz] gac]] [[gbo gbz] gbc]]|]; [|discriminate].
  cbv beta iota.
  set (A := ((gao =? 8) && (gaz =? 2) && (gac =? 1)
             && (gbo =? 4) && (gbz =? 2) && (1 <=? gbc))%bool).
  set (B := ((gbo =? 8) && (gbz =? 2) && (gbc =? 1))%bool).
  destruct (A && (2 <=? f))%bool eqn:EA.
  - intros _. apply andb_prop in EA as [_ EF]. exact EF.
  - destruct (B && (2 <=? f))%bool eqn:EB; [|discriminate].
    intros _. apply andb_prop in EB as [_ EF]. exact EF.
Qed.
