             && (gbo =? 4) && (gbz =? 2) && (1 <=? gbc))%bool).
  set (B := ((gbo =? 8) && (gbz =? 2) && (gbc =? 1))%bool).
  destruct A eqn:EA;
    [intros _; unfold seg_shape; fold A B; rewrite EA; reflexivity|].
  destruct B eqn:EB; [|discriminate].
