Lemma dseg_CE_of_some (cols : word) (L : N -> N) :
  (exists pc gbc, cseg cols = Some (pc, gbc)) ->
  CE (dseg cols L).
Proof.
  intros (pc & gbc & EC). unfold dseg. rewrite EC. apply CE_cx.
Qed.
Ltac cefin :=
  unfold CE, clo, chi, cadd, cx, czero in *;
  cbn [fst snd] in *; lia.
Theorem cascade_live (n : nat) :
  (forall s f s2 f2,
     fst (cfire_comp n s f) = Some (s2, f2) ->
     CE (snd (cfire_comp n s f)))
  /\ (forall cols s f body f2,
        forallb is_col cols = true ->
        fst (crenew_seg n cols s f) = Some (body, f2) ->
        CE (snd (crenew_seg n cols s f))).
Proof.
  induction n as [|n IH]; [split; intros; discriminate|].
  destruct IH as [IHfc IHrs].
  split.
  -
    intros s f.
    destruct s as [|[[X z] c] rest0]; [discriminate|].
    destruct z as [|zp]; [discriminate|].
    destruct zp as [zp'|zp'|]; try discriminate.
    destruct zp' as [q|q|]; try discriminate.
    destruct c as [|cp]; [discriminate|].
    destruct cp as [cp'|cp'|]; try discriminate.
    cbn [cfire_comp].
    destruct (negb (5 <=? X)) eqn:EX; [discriminate|].
    destruct rest0 as [|[[Y zY] cY] rest].
    { unfold d_casc_far.
      destruct (2 <=? f); [intros; apply CE_cx|intros; discriminate]. }
    destruct ((Y =? 4) && (zY =? 2))%bool eqn:EY4.
    { destruct (negb (1 <=? cY)); [discriminate|].
      destruct rest as [|gr rest'].
      { unfold d_casc_lvl_end.
        destruct (f =? 4); [intros; apply CE_cx|].
        destruct (5 <=? f); [intros; apply CE_cx|intros; discriminate]. }
      destruct (seek (gr :: rest')) as [cols s2] eqn:Eseek.
      assert (HCOLS : forallb is_col cols = true)
        by (exact (seek_cols _ _ _ Eseek)).
      destruct s2 as [|[[o4 z4] c4] s2t].
      { unfold d_casc_dtb.
        destruct (5 <=? f) eqn:EF5; [intros; apply CE_cx|].
        destruct (f =? 3) eqn:EF3.
        { destruct (dtb3_convc cols) as [[bd Kd]|] eqn:ED.
          - intros; apply CE_cx.
          - assert (EDT : dtb3_conv cols = None).
            { pose proof (dtb3_convc_proj cols) as EP.
              rewrite ED in EP. cbn [option_map fst] in EP.
              symmetry. exact EP. }
            intros ? ? HS.
            Transparent dtb3_conv.
            cbn [dtb3_conv gO gZ gC] in HS.
            Opaque dtb3_conv.
            rewrite EDT in HS. discriminate HS. }
        destruct (f =? 4) eqn:EF4; [|intros; discriminate].
        destruct (dtb4_convc cols) as [[bd Kd]|] eqn:ED.
        - intros; apply CE_cx.
        - assert (EDT : dtb4_conv cols = None).
          { pose proof (dtb4_convc_proj cols) as EP.
            rewrite ED in EP. cbn [option_map fst] in EP.
            symmetry. exact EP. }
          intros ? ? HS.
          Transparent dtb4_conv.
          cbn [dtb4_conv gO gZ gC] in HS.
          Opaque dtb4_conv.
          rewrite EDT in HS. discriminate HS. }
      destruct ((o4 =? 4) && (z4 =? 3) && (c4 =? 1))%bool eqn:E43.
      { apply andb_prop in E43 as [E43 Ec4].
        apply andb_prop in E43 as [Eo4 Ez4].
        apply N.eqb_eq in Eo4, Ez4, Ec4. subst o4 z4 c4.
        destruct s2t as [|[[o5 z5] Bq] rest2].
        { destruct (2 <=? f) eqn:E2.
          destruct (endR_seg cols f) as [seg2|] eqn:ES;
            [|intros; discriminate].
          intros ? ? _.
          pose proof (cseg_some_of_shape cols HCOLS
            (endR_seg_shape cols seg2 f ES)) as HC.
          unfold d_casc_endR, dseg_endR. rewrite E2.
          apply CE_cadd; [apply CE_cx|exact (dseg_CE_of_some _ _ HC)].
          destruct (endR_seg cols f) as [seg2|] eqn:ES;
            [|intros; discriminate].
          pose proof (endR_seg_f_live cols seg2 f ES) as EF.
          rewrite E2 in EF. discriminate EF. }
        destruct ((o5 =? 4) && (z5 =? 2))%bool eqn:E52.
        { apply andb_prop in E52 as [Eo5 Ez5].
          apply N.eqb_eq in Eo5, Ez5. subst o5 z5.
          destruct (1 <=? Bq); [|discriminate].
          destruct rest2 as [|gr2 rest2'].
          { destruct (f =? 4) eqn:EF4.
            - destruct (lawR_seg cols Bq) as [seg2|] eqn:ES;
                [|intros; discriminate].
              intros ? ? _.
              pose proof (cseg_some_of_shape cols HCOLS
                (lawR_seg_shape cols seg2 Bq ES)) as HC.
              unfold d_casc_lawR, dseg_lawR. rewrite EF4.
              apply CE_cadd; [apply CE_cx|exact (dseg_CE_of_some _ _ HC)].
            - destruct (5 <=? f) eqn:EF5; [|intros; discriminate].
              destruct (jump_seg cols Bq) as [seg2|] eqn:ES;
                [|intros; discriminate].
              intros ? ? _.
              pose proof (cseg_some_of_shape cols HCOLS
                (jump_seg_shape cols seg2 Bq ES)) as HC.
              unfold d_casc_lawR, dseg_lawR.
              rewrite EF4, EF5.
              apply CE_cadd; [apply CE_cx|exact (dseg_CE_of_some _ _ HC)]. }
          destruct (jump_seg cols Bq) as [seg|] eqn:EJ;
            [|discriminate].
          destruct (seek (gr2 :: rest2')) as [cols2 s3] eqn:Eseek2.
          assert (HCOLS2 : forallb is_col cols2 = true)
            by (exact (seek_cols _ _ _ Eseek2)).
          match goal with
          | |- context [ crenew_seg ?a ?b ?cc ?d ] =>
              destruct (fst (crenew_seg a b cc d))
                as [[bd fd]|] eqn:ER
          end.
          { pose proof (IHrs cols2 s3 f bd fd HCOLS2 ER) as IHq.
            unfold d_casc_stage, d_jsplice.
            intros ? ? _. cefin. }
          match goal with
          | |- context [ cfire_comp ?a ?b ?cc ] =>
              destruct (fst (cfire_comp a b cc))
                as [[sd fd]|] eqn:EFq
          end.
          { pose proof (IHfc s3 f sd fd EFq) as IHq.
            unfold d_casc_stage, d_jsplice, d_cols.
            intros ? ? _. cefin. }
          destruct (sand_leaf s3
                    && forallb (fun g => (gC g =? 0)%N) cols2)%bool;
            [discriminate|].
          match goal with
          | |- context [ cleaf_act ?b ?cc ] =>
              destruct (fst (cleaf_act b cc))
                as [[sd fd]|] eqn:EL
          end.
          { pose proof (CE_of_CL _ (cleaf_act_live s3 f sd fd EL)) as IHq.
            unfold d_casc_leafj. intros ? ? _. cefin. }
          destruct s3 as [|g3 t3]; [|intros; discriminate].
          unfold d_casc_tail.
          destruct (5 <=? f) eqn:EF5; [intros; apply CE_cx|].
          destruct (f =? 4) eqn:EF4; [|intros; discriminate].
          destruct (dtb4_convc cols2) as [[bd2 Kd]|] eqn:ED.
          { intros; apply CE_cx. }
          pose proof (dtb4_convc_proj cols2) as EP.
          rewrite ED in EP. cbn [option_map] in EP.
          rewrite <- EP.
          destruct (forallb w42 cols2) eqn:EW42;
            [|intros; discriminate].
          destruct (lawR_seg cols Bq) as [seg2|] eqn:ELR;
            [intros; apply CE_cx|intros; discriminate]. }
        destruct ((z5 =? 3) && (Bq =? 1)
                  && match rest2 with [] => true | _ => false end
                  && (f =? 4) && (1 <=? o5))%bool eqn:EYY.
        { destruct rest2 as [|? ?].
          2:{ apply andb_prop in EYY as [EYY _].
              apply andb_prop in EYY as [EYY _].
              apply andb_prop in EYY as [_ Hnil]. discriminate Hnil. }
          destruct (endY_seg cols o5) as [seg2|] eqn:ES;
            [|intros; discriminate].
          intros ? ? _.
          pose proof (cseg_some_of_shape cols HCOLS
            (endY_seg_shape cols seg2 o5 ES)) as HC.
          unfold d_casc_endY, dseg_endY.
          apply CE_cadd; [apply CE_cx|exact (dseg_CE_of_some _ _ HC)]. }
        rewrite cmap_fst. cbv beta.
        intros s2' f2' HS. apply optmap_pair_some in HS.
        destruct HS as (sd & fd & EL).
        pose proof (CE_of_CL _ (cleaf_act_live _ f sd fd EL)) as IHq.
        unfold cmap, d_casc_leaf. cbn [snd].
        apply CE_cadd; [apply CE_cx|exact IHq]. }
      destruct ((o4 =? 4) && (z4 =? 4) && (c4 =? 1))%bool eqn:E44.
      { destruct s2t as [|[[on zn] cn] t2]; [intros; discriminate|].
        destruct ((on =? 4) && (zn =? 2) && (1 <=? cn))%bool;
          [|intros; discriminate].
        destruct (jump_seg cols cn) as [seg2|] eqn:EJ;
          [|intros; discriminate].
        intros ? ? _.
        pose proof (cseg_some_of_shape cols HCOLS
          (jump_seg_shape cols seg2 cn EJ)) as HC.
        unfold d_casc_z4, d_casc_stage.
        apply CE_cadd; [apply CE_cx|exact (dseg_CE_of_some _ _ HC)]. }
      match goal with
      | |- context [ cfire_comp ?a ?b ?cc ] =>
          destruct (fst (cfire_comp a b cc))
            as [[sd fd]|] eqn:EFq
      end.
      { pose proof (IHfc ((o4,z4,c4) :: s2t) f sd fd EFq) as IHq.
        unfold d_casc_stage, d_cols. intros ? ? _. cefin. }
      rewrite cmap_fst. cbv beta.
      intros s2' f2' HS. apply optmap_pair_some in HS.
      destruct HS as (sd2 & fd2 & EL).
      pose proof (CE_of_CL _ (cleaf_act_live _ f sd2 fd2 EL)) as IHq.
      unfold cmap, d_casc_leaf. cbn [snd].
      apply CE_cadd; [apply CE_cx|exact IHq]. }
    destruct ((Y =? 8) && (zY =? 2) && (cY =? 1))%bool eqn:EY8.
    { apply andb_prop in EY8 as [EY8 EcY].
      apply andb_prop in EY8 as [EY EzY].
      apply N.eqb_eq in EY, EzY, EcY. subst Y zY cY.
      match goal with
      | |- context [ tick_target ?a ?b ] =>
          destruct (tick_target a b) as [j|] eqn:Etg
      end; [|discriminate].
      match goal with
      | |- context [match wat ?a j with _ => _ end] =>
          destruct (wat a j) as [[[oq zq] cq]|] eqn:Ewat
      end; [|discriminate].
      destruct (zq =? 1) eqn:EZQ; [|discriminate].
      destruct n as [|fuel];
        [cbn [cdeliver_tick cmap]; intros; discriminate|].
      intros s3 f3 Hout.
      destruct (cdeliver_tick (S fuel)
                  ((X-1,1,1) :: (11,2,1) :: rest) f j true)
        as [[w3 f3'| |] d] eqn:EDT;
        cbn [cmap] in Hout |- *; try discriminate Hout.
      injection Hout as <- <-.
      assert (HZ :
        (match wat ((X-1,1,1) :: (11,2,1) :: rest) j with
         | Some (_,z,_) => (z =? 1)%N | None => false end) = true)
        by (rewrite Ewat; exact EZQ).
      destruct (cdt_leaf_convc fuel
                  ((X-1,1,1) :: (11,2,1) :: rest) f j true
                  w3 f3' d HZ EDT) as (s' & ELeaf & _).
      pose proof (f_equal fst ELeaf) as ELeafF; cbn [fst] in ELeafF.
      pose proof (f_equal snd ELeaf) as ELeafD; cbn [snd] in ELeafD.
      pose proof (CE_of_CL _ (cleaf_act_live _ f s' f3' ELeafF)) as IHq.
      unfold d_casc_tick8, cmap. rewrite <- ELeafD. cefin. }
    destruct ((zY =? 1) && (cY =? 1) && (1 <=? Y)
              && match rest with [] => true | _ => false end)%bool eqn:EZ1.
    { destruct rest as [|? ?].
      2:{ apply andb_prop in EZ1 as [_ Hnil]. discriminate Hnil. }
      unfold d_casc_z1end, d_casc_z1law.
      destruct (2 <=? f); [intros; apply CE_cx|intros; discriminate]. }
    destruct ((zY =? 3) && (cY =? 1) && (1 <=? Y) && (f =? 4))%bool
      eqn:EZ3.
    { destruct rest as [|[[o2 z2] c2] r2]; [intros; discriminate|].
      destruct r2 as [|? ?]; [|intros; discriminate].
      destruct ((o2 =? 4) && (z2 =? 2) && (1 <=? c2))%bool;
        [|intros; discriminate].
      unfold d_casc_z3. intros; apply CE_cx. }
    destruct ((zY =? 1) && (cY =? 1) && (1 <=? Y)
              && match rest with
                 | (o2,z2,c2) :: _ => (o2 =? 4) && (z2 =? 2) && (1 <=? c2)
                 | [] => false
                 end)%bool eqn:EZL.
    { destruct rest as [|[[o2 z2] c2] r2]; [intros; discriminate|].
      unfold d_casc_z1lvl, d_casc_z1law.
      intros; apply CE_cx. }
    destruct ((zY =? 1) && (2 <=? cY) && (2 <=? Y))%bool eqn:EZS.
    { unfold d_casc_z1split, d_casc_z1law.
      intros; apply CE_cx. }
    destruct ((zY =? 1) && (cY =? 1) && (1 <=? Y)
              && match rest with
                 | (o2,z2,c2) :: _ => (z2 =? 1) && (c2 =? 1) && (1 <=? o2)
                 | [] => false
                 end)%bool eqn:EZZ.
    { destruct rest as [|[[k kz] kc] r2]; [intros; discriminate|].
      unfold d_casc_z1z1, d_casc_z1law.
      destruct (k =? 1); intros; apply CE_cx. }
    destruct ((zY =? 1) && (cY =? 1) && (1 <=? Y)
              && match rest with
                 | (o2,z2,c2) :: _ =>
                     (z2 =? 2) && (1 <=? o2) && (o2 <=? 3) && (c2 =? 1)
                 | [] => false
                 end)%bool eqn:EZ2; [|intros; discriminate].
    destruct rest as [|[[b bz] bc] r2]; [intros; discriminate|].
    unfold d_casc_z1z2, d_casc_z1law.
    destruct (b =? 1); intros; apply CE_cx.
  -
    intros cols s f out fout HCOLS HS.
    destruct s as [|[[o z] c] rest]; [discriminate HS|].
    destruct o as [|op]; [discriminate HS|].
    destruct op as [op'|op'|]; try (discriminate HS).
    destruct op' as [q|q|]; try (discriminate HS).
    destruct q as [r|r|]; try (discriminate HS).
    destruct z as [|zp]; [discriminate HS|].
    destruct zp as [zp'|zp'|]; try (discriminate HS).
    destruct zp' as [q|q|]; try (discriminate HS).
    destruct c as [|cp]; [discriminate HS|].
    destruct cp as [cp'|cp'|]; try (discriminate HS).
    cbn [crenew_seg] in HS |- *.
    destruct rest as [|[[o5 z5] Bq] rest2].
    { destruct (2 <=? f) eqn:E2.
      destruct (endR_seg cols f) as [body|] eqn:ES;
        [|discriminate HS].
      pose proof (cseg_some_of_shape cols HCOLS
        (endR_seg_shape cols body f ES)) as HC.
      unfold d_rseg_endR, dseg_endR. rewrite E2.
      exact (dseg_CE_of_some _ _ HC).
      destruct (endR_seg cols f) as [body|] eqn:ES;
        [|intros; discriminate].
      pose proof (endR_seg_f_live cols body f ES) as EF.
      rewrite E2 in EF. discriminate EF. }
    destruct ((o5 =? 4) && (z5 =? 2) && (1 <=? Bq))%bool eqn:E52.
    { destruct rest2 as [|gr2 rest2'].
      { destruct (f =? 4) eqn:EF4.
        - destruct (lawR_seg cols Bq) as [body|] eqn:ES;
            [|discriminate HS].
          pose proof (cseg_some_of_shape cols HCOLS
            (lawR_seg_shape cols body Bq ES)) as HC.
          unfold d_rseg_lawR, dseg_lawR. rewrite EF4.
          exact (dseg_CE_of_some _ _ HC).
        - destruct (5 <=? f) eqn:EF5; [|discriminate HS].
          destruct (jump_seg cols Bq) as [seg|] eqn:ES;
            [|discriminate HS].
          pose proof (cseg_some_of_shape cols HCOLS
            (jump_seg_shape cols seg Bq ES)) as HC.
          unfold d_rseg_lawR, dseg_lawR. rewrite EF4, EF5.
          exact (dseg_CE_of_some _ _ HC). }
      destruct (jump_seg cols Bq) as [seg|] eqn:EJ;
        [|discriminate HS].
      destruct (seek (gr2 :: rest2')) as [cols2 s3] eqn:Eseek2.
      assert (HCOLS2 : forallb is_col cols2 = true)
        by (exact (seek_cols _ _ _ Eseek2)).
      match goal with
      | |- context [ crenew_seg ?a ?b ?cc ?d ] =>
          destruct (fst (crenew_seg a b cc d))
            as [[bd fd]|] eqn:ER
      end.
      { pose proof (IHrs cols2 s3 f bd fd HCOLS2 ER) as IHq.
        unfold d_jsplice.
        apply CE_cadd; [apply CE_cx|exact IHq]. }
      destruct s3 as [|[[o7 z7] c7] s3t].
      { unfold cdrop. cbn [fst].
        match goal with
        | |- context [ cleaf_act ?b ?cc ] =>
            destruct (fst (cleaf_act b cc)) as [[sd fd]|] eqn:EL0
        end.
        { cbn [cleaf_act] in EL0. discriminate. }
        unfold d_rseg_tail.
        destruct (5 <=? f) eqn:EF5; [apply CE_cx|].
        destruct (f =? 4) eqn:EF4; [|discriminate HS].
        destruct (dtb4_convc cols2) as [[bd2 Kd]|] eqn:ED.
        { apply CE_cx. }
        pose proof (dtb4_convc_proj cols2) as EP.
        rewrite ED in EP. cbn [option_map] in EP. rewrite <- EP.
        destruct (forallb w42 cols2).
        2:{ match goal with H : fst _ = Some _ |- _ =>
              unfold cdrop in H; cbn [fst] in H;
              rewrite EL0 in H; cbn in H; rewrite <- EP in H;
              discriminate H
            end. }
        destruct (lawR_seg cols Bq) eqn:ELR; [apply CE_cx|].
        unfold cdrop in HS. cbn [fst] in HS. rewrite EL0 in HS.
        cbn in HS. rewrite <- EP in HS. discriminate HS. }
      destruct ((z7 =? 3) && (c7 =? 1))%bool eqn:E73.
      { rewrite cmap_fst. cbv beta.
        match goal with
        | |- context [ cfire_comp ?a ?b ?cc ] =>
            destruct (fst (cfire_comp a b cc))
              as [[sd fd]|] eqn:EFq
        end.
        { pose proof (IHfc ((o7,z7,c7) :: s3t) f sd fd EFq) as IHq.
          unfold cmap, d_jsplice, d_cols.
          cbn [snd].
          apply CE_cadd; [apply CE_cx|exact IHq]. }
        unfold cmap in HS. cbn [fst snd] in HS.
        rewrite EFq in HS. cbn in HS. discriminate HS. }
      revert HS.
      match goal with
      | |- context [ sand_leaf ?a ] =>
          destruct (sand_leaf a) eqn:ESand
      end.
      { cbn [fst]. intros HSome. discriminate HSome. }
      rewrite cmap_fst. cbv beta.
      match goal with
      | |- context [ cleaf_act ?b ?cc ] =>
          destruct (fst (cleaf_act b cc))
            as [[sd fd]|] eqn:EL
      end.
      { pose proof (CE_of_CL _
          (cleaf_act_live ((o7,z7,c7) :: s3t) f sd fd EL)) as IHq.
        unfold cmap, d_rseg_inner. cbn [snd].
        intros _. apply CE_cadd; [apply CE_cx|exact IHq]. }
      intros HSome. discriminate HSome. }
    destruct ((z5 =? 3) && (Bq =? 1)
              && match rest2 with [] => true | _ => false end
              && (f =? 4) && (1 <=? o5))%bool eqn:EYY;
      [|discriminate HS].
    destruct rest2 as [|? ?].
    2:{ apply andb_prop in EYY as [EYY _].
        apply andb_prop in EYY as [EYY _].
        apply andb_prop in EYY as [_ Hnil]. discriminate Hnil. }
    destruct (endY_seg cols o5) as [body|] eqn:ES;
      [|discriminate HS].
    pose proof (cseg_some_of_shape cols HCOLS
      (endY_seg_shape cols body o5 ES)) as HC.
    unfold d_rseg_endY, dseg_endY.
    exact (dseg_CE_of_some _ _ HC).
Qed.
Theorem d_jcomp_live (pre post body : word) (B f f2 : N)
    (kd : ckind) :
  forallb is_col pre = true ->
  jump_comp pre B post f = Some (kd, body, f2) ->
  CE (d_jcomp pre B post f).
Proof.
  intros HCP HJC.
  unfold d_jcomp. rewrite HCP. cbn [negb].
  unfold jump_comp in HJC.
  destruct post as [|g0 postT].
  - destruct (f =? 4)%N eqn:EF4.
    + destruct (lawR_seg pre B) as [seg2|] eqn:ELS;
        [|discriminate HJC].
      pose proof (cseg_some_of_shape pre HCP
        (lawR_seg_shape pre seg2 B ELS)) as HC.
      unfold dseg_lawR. rewrite EF4.
      exact (dseg_CE_of_some _ _ HC).
    + destruct (5 <=? f)%N eqn:EF5; [|discriminate HJC].
      destruct (jump_seg pre B) as [seg2|] eqn:EJS;
        [|discriminate HJC].
      pose proof (cseg_some_of_shape pre HCP
        (jump_seg_shape pre seg2 B EJS)) as HC.
      unfold dseg_lawR. rewrite EF4, EF5.
      exact (dseg_CE_of_some _ _ HC).
  - destruct (jump_seg pre B) as [segp|] eqn:EJS;
      [|discriminate HJC].
    destruct (seek (g0 :: postT)) as [cols2 s3] eqn:ESK.
    assert (HC2 : forallb is_col cols2 = true)
      by exact (seek_cols _ _ _ ESK).
    rewrite <- crenew_seg_proj in HJC.
    destruct (fst (crenew_seg (List.length s3) cols2 s3 f))
      as [[bd fd]|] eqn:ERS.
    + pose proof (proj2 (cascade_live (List.length s3))
        cols2 s3 f bd fd HC2 ERS) as HR.
      unfold d_jsplice. apply CE_cadd; [apply CE_cx|exact HR].
    + destruct s3 as [|[[o7 z7] c7] s3t].
      * cbn [leaf_act] in HJC.
        destruct (5 <=? f)%N eqn:EF5; [apply CE_cx|].
        destruct (f =? 4)%N eqn:EF4; [|discriminate HJC].
        destruct (dtb4_convc cols2) as [[cols2' Kd]|] eqn:EDC.
        { apply CE_cx. }
        pose proof (dtb4_convc_proj cols2) as EDP.
        rewrite EDC in EDP. cbn [option_map fst] in EDP.
        rewrite <- EDP in HJC.
        destruct (forallb w42 cols2) eqn:EW42;
          [|discriminate HJC].
        destruct (lawR_seg pre B) as [seg2|] eqn:ELS;
          [apply CE_cx|discriminate HJC].
      * destruct ((z7 =? 3) && (c7 =? 1))%bool eqn:E73.
        { rewrite <- cfire_comp_proj in HJC.
          match type of HJC with
          | context [fst (cfire_comp ?n ?ss ?ff)] =>
              destruct (fst (cfire_comp n ss ff))
                as [[sd fd]|] eqn:EFC
          end.
          2:{ cbn [fst] in HJC. discriminate HJC. }
          pose proof (proj1 (cascade_live _)
            ((o7,z7,c7) :: s3t) f sd fd EFC) as HF.
          unfold d_jsplice, d_cols.
          apply CE_cadd; [apply CE_cx|].
          apply CE_cadd; [apply CE_cx|exact HF]. }
        match type of HJC with
        | context [sand_leaf ?ss] =>
            destruct (sand_leaf ss) eqn:ESand
        end; [cbn in HJC; discriminate HJC|].
        rewrite <- cleaf_act_proj in HJC.
        match type of HJC with
        | context [fst (cleaf_act ?ss ?ff)] =>
            destruct (fst (cleaf_act ss ff))
              as [[sd fd]|] eqn:ELA
        end.
        2:{ cbn [fst] in HJC. discriminate HJC. }
        pose proof (CE_of_CL _
          (cleaf_act_live ((o7,z7,c7) :: s3t) f sd fd ELA)) as HL.
        apply CE_cadd; [apply CE_cx|exact HL].
Qed.
Lemma CE_cadds (a b : cost) : CE a -> CE b -> CE (cadds a b).
Proof.
  intros HA HB. unfold cadds.
  destruct (N.ltb (chi a) (clo a)) eqn:EA.
  { apply N.ltb_lt in EA. unfold CE in HA. lia. }
  destruct (N.ltb (chi b) (clo b)) eqn:EB.
  { apply N.ltb_lt in EB. unfold CE in HB. lia. }
  exact (CE_cadd _ _ HA HB).
Qed.
Lemma cleaf_act_CE (s : word) (f : N) (s2 : word) (f2 : N) :
  fst (cleaf_act s f) = Some (s2, f2) ->
  CE (snd (cleaf_act s f)).
Proof.
  intros H. exact (CE_of_CL _ (cleaf_act_live s f s2 f2 H)).
Qed.
Theorem cround_at_live (cols s : word) (f : N)
    (body : word) (f2 : N) :
  forallb is_col cols = true ->
  fst (cround_at cols s f) = Some (body, f2) ->
  CE (snd (cround_at cols s f)).
Proof.
  intros HCOLS. revert body f2.
  unfold cround_at.
  destruct s as [|[[o z] c] t].
  { intros body f2 HS.
    match goal with
    | |- context [fst (cleaf_act ?ss ?ff)] =>
        destruct (fst (cleaf_act ss ff)) as [[sd fd]|] eqn:EL
    end; [|cbn [fst] in HS; discriminate HS].
    pose proof (cleaf_act_CE [] f sd fd EL) as HL.
    apply CE_cadd; [apply CE_cx|exact HL]. }
  destruct z as [|pz].
  { intros body f2 HS.
    match goal with
    | |- context [fst (cleaf_act ?ss ?ff)] =>
        destruct (fst (cleaf_act ss ff)) as [[sd fd]|] eqn:EL
    end; [|cbn [fst] in HS; discriminate HS].
    pose proof (cleaf_act_CE _ f sd fd EL) as HL.
    apply CE_cadd; [apply CE_cx|exact HL]. }
  destruct pz as [q1|q1|].
  2,3: intros body f2 HS;
       match goal with
       | |- context [fst (cleaf_act ?ss ?ff)] =>
           destruct (fst (cleaf_act ss ff))
             as [[sd fd]|] eqn:EL
       end;
       [ pose proof (cleaf_act_CE _ _ _ _ EL) as HL;
         apply CE_cadd; [apply CE_cx|exact HL]
       | discriminate HS ].
  destruct q1 as [r1|r1|].
  1,2: intros body f2 HS;
       match goal with
       | |- context [fst (cleaf_act ?ss ?ff)] =>
           destruct (fst (cleaf_act ss ff))
             as [[sd fd]|] eqn:EL
       end;
       [ pose proof (cleaf_act_CE _ _ _ _ EL) as HL;
         apply CE_cadd; [apply CE_cx|exact HL]
       | discriminate HS ].
  destruct c as [|pc].
  { intros body f2 HS.
    match goal with
    | |- context [fst (cleaf_act ?ss ?ff)] =>
        destruct (fst (cleaf_act ss ff))
          as [[sd fd]|] eqn:EL
    end;
    [ pose proof (cleaf_act_CE _ _ _ _ EL) as HL;
      apply CE_cadd; [apply CE_cx|exact HL]
    | discriminate HS ]. }
  destruct pc as [pc'|pc'|].
  1,2: intros body f2 HS;
       match goal with
       | |- context [fst (cleaf_act ?ss ?ff)] =>
           destruct (fst (cleaf_act ss ff))
             as [[sd fd]|] eqn:EL
       end;
       [ pose proof (cleaf_act_CE _ _ _ _ EL) as HL;
         apply CE_cadd; [apply CE_cx|exact HL]
       | discriminate HS ].
  cbv beta iota zeta.
  match goal with
  | |- context [fst (crenew_seg ?n ?cs ?ss ?ff)] =>
      destruct (fst (crenew_seg n cs ss ff))
        as [[bd fd]|] eqn:ER
  end.
  { intros body f2 HS. injection HS as <- <-.
    pose proof (proj2 (cascade_live _) cols _ f bd fd HCOLS ER) as HR.
    apply CE_cadd; [apply CE_cx|exact HR]. }
  match goal with
  | |- context [fst (cfire_comp ?n ?ss ?ff)] =>
      destruct (fst (cfire_comp n ss ff))
        as [[sd fd]|] eqn:EF
  end.
  { intros body f2 HS. injection HS as <- <-.
    pose proof (proj1 (cascade_live _) _ f sd fd EF) as HF.
    apply CE_cadd; [apply CE_cx|exact HF]. }
  intros ? ? HS. discriminate HS.
Qed.
Theorem cround1g_live (tail body : word) (f f2 : N) :
  fst (cround1g tail f) = Some (body, f2) ->
  CE (snd (cround1g tail f)).
Proof.
  unfold cround1g.
  destruct (seek tail) as [cols s] eqn:ES.
  exact (cround_at_live cols s f body f2 (seek_cols _ _ _ ES)).
Qed.
Theorem cround2g_live (tail body : word) (f f2 : N) :
  fst (cround2g tail f) = Some (body, f2) ->
  CE (snd (cround2g tail f)).
Proof.
  unfold cround2g. cbv zeta.
  destruct (seek tail) as [cols s] eqn:ES.
  assert (HC : forallb is_col cols = true)
    by exact (seek_cols _ _ _ ES).
  destruct (fst (cround_at cols s f)) as [[t2 ft]|] eqn:ER1;
    [|intros HS; discriminate HS].
  pose proof (cround_at_live cols s f t2 ft HC ER1) as H1.
  destruct (seek t2) as [cols2 s2] eqn:ES2.
  assert (HC2 : forallb is_col cols2 = true)
    by exact (seek_cols _ _ _ ES2).
  destruct s2 as [|g2 s2t].
  - destruct (ft =? 4)%N eqn:EF4.
    + destruct (dtb4_conv cols2) as [cols2'|] eqn:ED;
        [|intros HS; discriminate HS].
      intros _.
      assert (EDC : exists Kd, dtb4_convc cols2 = Some (cols2', Kd)).
      { pose proof (dtb4_convc_proj cols2) as EP.
        rewrite ED in EP.
        destruct (dtb4_convc cols2) as [[w K]|] eqn:EC;
          cbn [option_map fst] in EP; [injection EP as <-|discriminate EP].
        exists K. reflexivity. }
      destruct EDC as (Kd & EDC). rewrite EDC.
      apply CE_cadds; [exact H1|apply CE_cx].
    + destruct (5 <=? ft)%N eqn:EF5;
        [intros _; apply CE_cadds; [exact H1|apply CE_cx]
        |intros HS; discriminate HS].
  - match goal with
    | |- context [fst (cround_at ?cs ?ss ?ff)] =>
        destruct (fst (cround_at cs ss ff))
          as [[t3 f3]|] eqn:ER2
    end; [|intros HS; discriminate HS].
    intros _.
    pose proof (cround_at_live cols2 (g2 :: s2t) ft t3 f3 HC2 ER2) as H2.
    exact (CE_cadds _ _ H1 H2).
Qed.
Open Scope N_scope.
Definition seekt (g : bg) : bool :=
  ((is_col g && negb (is_cmf g)) && (3 <=? gO g))%bool.
Lemma seek_cons (g : bg) (t : word) :
  seek (g :: t)
  = if seekt g
    then (g :: fst (seek t), snd (seek t))
    else ([], g :: t).
Proof.
  cbn [seek]. unfold seekt.
  destruct ((is_col g && negb (is_cmf g)) && (3 <=? gO g))%bool;
    [|reflexivity].
  destruct (seek t) as [c r]. reflexivity.
Qed.
Section Expand.
Variable exp : bg -> word.
End Expand.
Close Scope N_scope.
Local Open Scope N_scope.
Lemma cempty_CE_absurd (d : cost) : cempty d -> CE d -> False.
Proof. unfold cempty, CE, clo, chi. lia. Qed.
Lemma cround2g_pre8_live (tail body : word) (f g : N) :
  fst (cround2g_pre8 tail f g) = Some body ->
  CE (snd (cround2g_pre8 tail f g)).
Proof.
  unfold cround2g_pre8. cbv zeta.
  destruct (seek tail) as [cols s] eqn:ES.
  assert (HC : forallb is_col cols = true)
    by exact (seek_cols _ _ _ ES).
  destruct (fst (cround_at cols s f)) as [[t2 f2]|] eqn:ER1;
    [|intros HS; discriminate HS].
  pose proof (cround_at_live cols s f t2 f2 HC ER1) as H1.
  destruct (seek t2) as [cols2 s2].
  destruct s2 as [|g2 s2t]; [|intros HS; discriminate HS].
  destruct (((f2 =? 4) && forallb w42 cols2)%N);
    [|intros HS; discriminate HS].
  destruct (dtb4_conv cols2); [intros HS; discriminate HS|].
  intros _. apply CE_cadds; [exact H1|apply CE_cx].
Qed.
Theorem d_span2A_live (w : word) (f : N)
    (w2 : word) (f2 : N) :
  fr_span2A w f = Some (ROk w2 f2) ->
  CE (d_span2A w f).
Proof.
  intros E. unfold fr_span2A in E.
  destruct w as [|[[o1 z1] c1] w1]; [discriminate E|].
  destruct w1 as [|[[o2 z2] c2] wb]; [killmN E|].
  destruct wb as [|[[o3 z3] c3] wc]; [killmN E|].
  destruct wc as [|[[o4 z4] c4] wd]; [killmN E|].
  destruct wd as [|[[o5 z5] c5] we]; [killmN E|].
  killmN E.
  unfold o_ in E. injection E as E'.
  unfold span2_core in E'.
  destruct we as [|g6 wf]; [discriminate E'|].
  cbn [d_span2A].
  cbn [N.eqb Pos.eqb andb] in E' |- *.
  destruct (1 <=? c5)%N eqn:EV; [|discriminate E'].
  destruct (seek (g6 :: wf)) as [cols s] eqn:ES.
  assert (HC : forallb is_col cols = true)
    by exact (seek_cols _ _ _ ES).
  destruct s as [|[[oR zR] cR] tR]; [discriminate E'|].
  destruct zR as [|zp]; [discriminate E'|].
  destruct zp as [zp'|zp'|].
  - destruct zp' as [q|q|]; try discriminate E'.
    destruct cR as [|cp]; [discriminate E'|].
    destruct cp as [cp'|cp'|]; try discriminate E'.
    assert (E2 :
      (match renew_seg (List.length ((oR,3,1)%N :: tR)) cols
               ((oR,3,1)%N :: tR) f with
       | Some (bd, gg) =>
           ROk
             (([(2,2,(c1+1)); (4,1,1); (3,1,1); (4,1,c3); (8,2,1)]%N
                ++ (if (1 <? c5)%N then [(4,2,(c5-1))%N] else [])) ++ bd) gg
       | None =>
           match fire_comp (List.length ((oR,3,1)%N :: tR))
                   ((oR,3,1)%N :: tR) f with
           | Some (s2, gg) =>
               ROk
                 (([(2,2,(c1+1)); (4,1,1); (3,1,1); (4,1,c3); (8,2,1)]%N
                    ++ (if (1 <? c5)%N then [(4,2,(c5-1))%N] else []))
                    ++ cols ++ s2) gg
           | None => RBad
           end
       end) = ROk w2 f2) by exact E'.
    clear E'.
    rewrite <- (crenew_seg_proj
      (List.length ((oR,3,1)%N :: tR)) cols ((oR,3,1)%N :: tR) f) in E2.
    set (rs := crenew_seg
      (List.length ((oR,3,1)%N :: tR)) cols ((oR,3,1)%N :: tR) f)
      in E2 |- *.
    change (CE
      (match fst rs with
       | Some _ => cadd (cx (10*c1 + 10*c3 + 14*c5 + 40)) (snd rs)
       | None =>
           match fst (cfire_comp
             (List.length ((oR,3,1)%N :: tR)) ((oR,3,1)%N :: tR) f) with
           | Some _ => cadd
               (cx (10*c1 + 10*c3 + 14*c5 + 40 + ccolcost cols))
               (snd (cfire_comp
                 (List.length ((oR,3,1)%N :: tR)) ((oR,3,1)%N :: tR) f))
           | None => cundef
           end
       end)).
    destruct (fst rs) as [[body fb]|] eqn:ERP.
    + cbn [fst] in E2. injection E2 as <- <-.
      apply CE_cadd; [apply CE_cx|].
      destruct (cascade_live
        (List.length ((oR,3,1)%N :: tR))) as [_ Hrenew].
      apply (Hrenew cols ((oR,3,1)%N :: tR) f body fb HC).
      unfold rs in ERP. exact ERP.
    + rewrite <- (cfire_comp_proj
        (List.length ((oR,3,1)%N :: tR)) ((oR,3,1)%N :: tR) f) in E2.
      set (fc := cfire_comp
        (List.length ((oR,3,1)%N :: tR)) ((oR,3,1)%N :: tR) f)
        in E2 |- *.
      change (CE
        (match fst fc with
         | Some _ => cadd
             (cx (10*c1 + 10*c3 + 14*c5 + 40 + ccolcost cols))
             (snd fc)
         | None => cundef
         end)).
      destruct (fst fc) as [[s2 fb]|] eqn:EFP; [|discriminate E2].
      cbn [fst] in E2. injection E2 as <- <-.
      apply CE_cadd; [apply CE_cx|].
      destruct (cascade_live
        (List.length ((oR,3,1)%N :: tR))) as [Hfire _].
      apply (Hfire ((oR,3,1)%N :: tR) f s2 fb).
      unfold fc in EFP. exact EFP.
  - discriminate E'.
  - assert (E2 :
      (match leaf_act ((oR,1,cR)%N :: tR) f with
       | Some (s2, gg) =>
           ROk
             (([(2,2,(c1+1)); (4,1,1); (3,1,1); (4,1,c3); (8,2,1)]%N
                ++ (if (1 <? c5)%N then [(4,2,(c5-1))%N] else []))
                ++ cols ++ s2) gg
       | None => RBad
       end) = ROk w2 f2) by exact E'.
    clear E'.
    rewrite <- (cleaf_act_proj ((oR,1,cR)%N :: tR) f) in E2.
    set (la := cleaf_act ((oR,1,cR)%N :: tR) f) in E2 |- *.
    change (CE
      (match fst la with
       | Some _ => cadd
           (cx (10*c1 + 10*c3 + 14*c5 + 34 + ccolcost cols))
           (snd la)
       | None => cundef
       end)).
    destruct (fst la) as [[s2 fb]|] eqn:ELP; [|discriminate E2].
    cbn [fst] in E2. injection E2 as <- <-.
    apply CE_cadd; [apply CE_cx|].
    apply (cleaf_act_CE ((oR,1,cR)%N :: tR) f s2 fb).
    unfold la in ELP. exact ELP.
Qed.
Theorem d_span2B_live (w : word) (f : N)
    (w2 : word) (f2 : N) :
  fr_span2B w f = Some (ROk w2 f2) ->
  CE (d_span2B w f).
Proof.
  intros E. unfold fr_span2B in E.
  destruct w as [|[[o1 z1] c1] w1]; [discriminate E|].
  destruct w1 as [|[[o2 z2] c2] wb]; [killmN E|].
  destruct wb as [|[[o3 z3] c3] wc]; [killmN E|].
  destruct wc as [|[[o4 z4] c4] wd]; [killmN E|].
  destruct wd as [|[[o5 z5] c5] we]; [killmN E|].
  destruct we as [|[[o6 z6] c6] wf]; [killmN E|].
  destruct wf as [|[[o7 z7] c7] restB]; [killmN E|].
  killmN E. cbn [d_span2B].
  destruct (((1 <=? c3) && (1 <=? c7))%N) eqn:EG; [|discriminate E].
  cbv beta iota zeta in E.
  rewrite <- (cround2g_proj restB f) in E.
  destruct (fst (cround2g restB f)) as [[t3 f3]|] eqn:ER;
    [|discriminate E].
  cbv beta iota in E. injection E as <- <-.
  apply CE_cadd; [apply CE_cx|].
  exact (cround2g_live restB t3 f f3 ER).
Qed.
Theorem d_span8orph_live (w : word) (f : N)
    (w2 : word) (f2 : N) :
  fr_span8orph w f = Some (ROk w2 f2) ->
  CE (d_span8orph w f).
Proof.
  intros E. unfold fr_span8orph in E.
  destruct w as [|[[o1 z1] c1] w1]; [discriminate E|].
  destruct w1 as [|[[o2 z2] c2] wb]; [killmN E|].
  destruct wb as [|[[o3 z3] c3] wc]; [killmN E|].
  destruct wc as [|[[o4 z4] c4] wd]; [killmN E|].
  destruct wd as [|[[o5 z5] c5] we]; [killmN E|].
  destruct we as [|[[o6 z6] c6] restB]; [killmN E|].
  killmN E. cbn [d_span8orph].
  destruct (((2 <=? c1) && (1 <=? c2) && (1 <=? c6))%N) eqn:EG;
    [|discriminate E].
  cbv beta iota zeta in E.
  rewrite <- (cround1g_proj
    ((if (1 <? c6)%N then [(4,2,c6-1)%N] else []) ++ restB) f) in E.
  destruct (fst (cround1g
    ((if (1 <? c6)%N then [(4,2,c6-1)%N] else []) ++ restB) f))
    as [[t2 g2]|] eqn:ER;
    [|discriminate E].
  cbv beta iota in E. injection E as <- <-.
  apply CE_cadd; [apply CE_cx|].
  exact (cround1g_live
    ((if (1 <? c6)%N then [(4,2,c6-1)%N] else []) ++ restB)
    t2 f g2 ER).
Qed.
Theorem d_span8_live (w : word) (f : N)
    (w2 : word) (f2 : N) :
  fr_span8 w f = Some (ROk w2 f2) ->
  CE (d_span8 w f).
Proof.
  intros E. unfold fr_span8 in E.
  destruct w as [|[[o1 z1] c1] w1]; [discriminate E|].
  destruct w1 as [|[[o2 z2] c2] wb]; [killmN E|].
  destruct wb as [|[[o3 z3] c3] wc]; [killmN E|].
  destruct wc as [|[[o4 z4] c4] rest]; [killmN E|].
  killmN E. destruct rest as [|g5 rest'].
  - cbv beta iota zeta in E. cbn [d_span8].
    destruct (((2 <=? c1) && (1 <=? c4) && (f =? 4))%N).
    + apply CE_cx.
    + destruct (((2 <=? c1) && (1 <=? c4) && (5 <=? f))%N);
        [apply CE_cx|discriminate E].
  - cbn [d_span8].
    destruct (((2 <=? c1) && (1 <=? c4))%N) eqn:EG;
      [|cbv beta iota zeta in E; discriminate E].
    cbv beta iota zeta in E.
    rewrite <- (cround2g_proj (g5 :: rest') f) in E.
    destruct (fst (cround2g (g5 :: rest') f))
      as [[t3 f3]|] eqn:ER.
    + cbv beta iota in E. injection E as <- <-.
      apply CE_cadd; [apply CE_cx|].
      exact (cround2g_live (g5 :: rest') t3 f f3 ER).
    + rewrite <- (cround2g_pre8_proj
                    (g5 :: rest') f (c4-1)) in E.
      destruct (fst (cround2g_pre8
                       (g5 :: rest') f (c4-1))) as [cols2|] eqn:ERP;
        [|cbn in E; discriminate E].
      cbv beta iota in E. injection E as <- <-.
      apply CE_cadd; [apply CE_cx|].
      exact (cround2g_pre8_live (g5 :: rest') cols2 f (c4-1) ERP).
Qed.
Lemma decorate_live
    (r : word -> N -> option res)
    (dd : word -> N -> cost) :
  (forall w f w2 f2,
      r w f = Some (ROk w2 f2) -> CE (dd w f)) ->
  forall w f w2 f2 d,
    decorate r dd w f = Some (ROk w2 f2, d) ->
    CE d.
Proof.
  intros HL w f w2 f2 d E. unfold decorate in E.
  destruct (r w f) as [rr|] eqn:ER; [|discriminate E].
  injection E as E1 E2. subst rr d. exact (HL _ _ _ _ ER).
Qed.
Lemma live_sound (d : cost) (P : Prop) :
  CE d -> (cempty d \/ P) -> P.
Proof.
  intros HE [HC|HP]; [exact (False_ind _ (cempty_CE_absurd d HC HE))|exact HP].
Qed.
Lemma CE_cdispatch (t : ctier) (w : word) (i : nat) (d : cost) :
  CE d -> CE (cdispatch t w i d).
Proof.
  intros HD. destruct t; cbn [cdispatch].
  all: try exact HD.
  all: apply CE_cadd; [apply CE_cx|].
  all: apply CE_cadd; [exact HD|apply CE_cx].
Qed.
Lemma seg_shape_cons_tail (g : bg) (cols : word) :
  (2 <= List.length cols)%nat ->
  (match last2 (g :: cols) with
   | Some (_, (gao,gaz,gac), (gbo,gbz,gbc)) =>
       seg_shape gao gaz gac gbo gbz gbc
   | None => false
   end) = true ->
  (match last2 cols with
   | Some (_, (gao,gaz,gac), (gbo,gbz,gbc)) =>
       seg_shape gao gaz gac gbo gbz gbc
   | None => false
   end) = true.
Proof.
  intros HL HS.
  destruct cols as [|a cols]; [cbn in HL; lia|].
  destruct cols as [|b rest]; [cbn in HL; lia|].
  change (last2 (g :: a :: b :: rest)) with
    (match last2 (a :: b :: rest) with
     | Some (ini, x, y) => Some (g :: ini, x, y)
     | None => None
     end) in HS.
  destruct (last2 (a :: b :: rest))
    as [[[ini [[gao gaz] gac]] [[gbo gbz] gbc]]|] eqn:EL;
    [exact HS|discriminate HS].
Qed.
Lemma dseg_endR_tail_live (g : bg) (cols body : word) (f : N) :
  (2 <= List.length cols)%nat ->
  forallb is_col cols = true ->
  endR_seg (g :: cols) f = Some body ->
  CE (dseg_endR cols f).
Proof.
  intros HL HC HE.
  pose proof (endR_seg_f_live (g :: cols) body f HE) as EF.
  pose proof (endR_seg_shape (g :: cols) body f HE) as HS.
  pose proof (seg_shape_cons_tail g cols HL HS) as HST.
  pose proof (cseg_some_of_shape cols HC HST) as HCS.
  unfold dseg_endR. rewrite EF.
  exact (dseg_CE_of_some cols _ HCS).
Qed.
Lemma dseg_endY_tail_live (g : bg) (cols body : word) (y : N) :
  (2 <= List.length cols)%nat ->
  forallb is_col cols = true ->
  endY_seg (g :: cols) y = Some body ->
  CE (dseg_endY cols y).
Proof.
  intros HL HC HE.
  pose proof (endY_seg_shape (g :: cols) body y HE) as HS.
  pose proof (seg_shape_cons_tail g cols HL HS) as HST.
  pose proof (cseg_some_of_shape cols HC HST) as HCS.
  unfold dseg_endY.
  exact (dseg_CE_of_some cols _ HCS).
Qed.
Lemma jump_comp_seg_shape (cols post body : word) (B f f2 : N)
    (kd : ckind) :
  jump_comp cols B post f = Some (kd, body, f2) ->
  (match last2 cols with
   | Some (_, (gao,gaz,gac), (gbo,gbz,gbc)) =>
       seg_shape gao gaz gac gbo gbz gbc
   | None => false
   end) = true.
Proof.
  intros H. unfold jump_comp in H.
  destruct post as [|g0 post'].
  - destruct (f =? 4)%N.
    + destruct (lawR_seg cols B) as [b|] eqn:ES;
        [exact (lawR_seg_shape cols b B ES)|discriminate H].
    + destruct (5 <=? f)%N; [|discriminate H].
      destruct (jump_seg cols B) as [b|] eqn:ES;
        [exact (jump_seg_shape cols b B ES)|discriminate H].
  - destruct (jump_seg cols B) as [b|] eqn:ES;
      [exact (jump_seg_shape cols b B ES)|discriminate H].
Qed.
Lemma d_jcomp_tail_live (g : bg) (pre post body : word)
    (B f f2 : N) (kd : ckind) :
  (2 <= List.length pre)%nat ->
  forallb is_col pre = true ->
  jump_comp (g :: pre) B post f = Some (kd, body, f2) ->
  CE (d_jcomp pre B post f).
Proof.
  intros HL HC HJC.
  pose proof (jump_comp_seg_shape (g :: pre) post body B f f2 kd HJC) as HS.
  pose proof (seg_shape_cons_tail g pre HL HS) as HST.
  destruct (cseg_some_of_shape pre HC HST) as (pc & gbc & ECS).
  destruct (cseg_seg_some pre pc gbc B ECS) as (seg & EJS).
  destruct (jump_lawR_seg_both pre seg B EJS) as (lb & ELS).
  pose proof (jump_comp_JMP (g :: pre) post body B f f2 kd HJC) as EK.
  subst kd.
  destruct (jump_comp_uncons g pre post body seg lb B f f2
              EJS ELS HJC) as (body' & HJC' & _).
  exact (d_jcomp_live pre post body' B f f2 JMP HC HJC').
Qed.
Ltac kill_comp_rok H :=
  match type of H with
  | context [wat ?a ?b] =>
      destruct (wat a b) as [g|] eqn:?EWAT; [|discriminate H]
  end;
  match type of H with
  | context [(gZ ?g =? 1)%N] =>
      destruct ((gZ g =? 1)%N); [discriminate H|]
  end;
  match type of H with
  | context [e0_chain ?a ?b] =>
      destruct (e0_chain a b); [discriminate H|]
  end;
  match type of H with
  | context [deliver_tick ?a ?b ?c ?d ?e] =>
      destruct (deliver_tick a b c d e); discriminate H
  end.
Theorem d_comp_live (w : word) (f : N) (h : nat)
    (w' : word) (f' : N) (i : nat) :
  step_after_front None w f h = (ROk w' f', i) ->
  CE (d_comp w f h).
Proof.
  intros H.
  unfold step_after_front, step_after_front_with,
         step_after_front_with_guard in H.
  cbn [orb negb] in H.
  unfold d_comp.
  match type of H with
  | context [find_active w ?st] =>
      destruct (find_active w st) as [i0|] eqn:EFA
  end.
  -
    match type of H with context [if negb ?b then _ else _] =>
      destruct b eqn:EP end; cbn [negb] in H; [|discriminate H].
    match type of H with context [if negb ?b then _ else _] =>
      destruct b eqn:EG0 end; cbn [negb] in H; [|discriminate H].
    match type of H with context [if negb ?b then _ else _] =>
      destruct b eqn:EL1 end; cbn [negb] in H; [|discriminate H].
    destruct w as [|[[o0 z0] c_0] t]; [discriminate EG0|].
    cbn [gO gZ gC] in EG0.
    apply andb_prop in EG0 as [EG0 EI0].
    apply andb_prop in EG0 as [EG0 EC0].
    apply andb_prop in EG0 as [EO0 EZ0].
    apply N.eqb_eq in EO0, EZ0. apply N.leb_le in EC0.
    apply negb_true_iff in EI0. subst o0 z0.
    destruct i0 as [|i1]; [cbn [Nat.eqb] in EI0; discriminate EI0|].
    cbn [gC firstn skipn] in H |- *.
    cbn [firstn skipn] in EP.
    apply andb_prop in EP as [_ EP].
    destruct (skipn i1 t) as [|[[o4 z4] c4] s2t] eqn:ESFX.
    { kill_comp_rok H. }
    destruct ((o4 =? 4)%N && (z4 =? 3)%N && (c4 =? 1)%N
              && Nat.leb 3 (S i1)) eqn:EA.
    + pose proof EA as EAI. apply andb_prop in EAI as [_ EAI].
      apply PeanoNat.Nat.leb_le in EAI.
      assert (HIT : (i1 <= List.length t)%nat).
      { pose proof (f_equal (@List.length bg) ESFX) as HH.
        rewrite skipn_length in HH. cbn [List.length] in HH. lia. }
      assert (HLEN : (2 <= List.length (firstn i1 t))%nat).
      { rewrite firstn_length, PeanoNat.Nat.min_l by exact HIT. lia. }
      destruct s2t as [|[[o5 z5] Bq] rest2].
      * match type of H with
        | context [endR_seg ?a ?b] =>
            destruct (endR_seg a b) as [body|] eqn:EES
        end; [|kill_comp_rok H].
        apply CE_cdispatch.
        exact (dseg_endR_tail_live (2,2,(c_0+1))%N
                 (firstn i1 t) body f HLEN EP EES).
      * destruct ((o5 =? 4)%N && (z5 =? 2)%N) eqn:E52.
        { destruct (1 <=? Bq)%N eqn:EBQ; [|kill_comp_rok H].
          match type of H with
          | context [jump_comp ?a ?b ?c ?d] =>
              destruct (jump_comp a b c d)
                as [[[kd body] fd]|] eqn:EJC
          end; [|kill_comp_rok H].
          apply CE_cdispatch.
          exact (d_jcomp_tail_live (2,2,(c_0+1))%N (firstn i1 t)
                   rest2 body Bq f fd kd HLEN EP EJC). }
        destruct (((z5 =? 3)%N && (Bq =? 1)%N
                   && match rest2 with [] => true | _ => false end
                   && (f =? 4)%N && (1 <=? o5)%N)) eqn:EY.
        { destruct rest2 as [|g2 rest2t].
          2:{ apply andb_prop in EY as [EY _].
              apply andb_prop in EY as [EY _].
              apply andb_prop in EY as [_ ENIL]. discriminate ENIL. }
          match type of H with
          | context [endY_seg ?a ?b] =>
              destruct (endY_seg a b) as [body|] eqn:EES
          end; [|kill_comp_rok H].
          apply CE_cdispatch.
          exact (dseg_endY_tail_live (2,2,(c_0+1))%N
                   (firstn i1 t) body o5 HLEN EP EES). }
        match type of H with
        | context [fire_comp ?n ?s ?ff] =>
            destruct (fire_comp n s ff) as [[sfx' fd]|] eqn:EFC
        end; [|kill_comp_rok H].
        apply CE_cdispatch.
        assert (ECF : fst (cfire_comp
            (List.length ((o4,z4,c4)%N :: (o5,z5,Bq)%N :: rest2))
            ((o4,z4,c4)%N :: (o5,z5,Bq)%N :: rest2) f)
            = Some (sfx', fd)).
        { rewrite cfire_comp_proj. exact EFC. }
        destruct (cascade_live
          (List.length ((o4,z4,c4)%N :: (o5,z5,Bq)%N :: rest2)))
          as [HFIRE _].
        exact (HFIRE _ _ _ _ ECF).
    + destruct ((z4 =? 3)%N && (c4 =? 1)%N) eqn:EB.
      { match type of H with
        | context [fire_comp ?n ?s ?ff] =>
            destruct (fire_comp n s ff) as [[sfx' fd]|] eqn:EFC
        end; [|kill_comp_rok H].
        apply CE_cdispatch.
        assert (ECF : fst (cfire_comp
            (List.length ((o4,z4,c4)%N :: s2t))
            ((o4,z4,c4)%N :: s2t) f) = Some (sfx', fd)).
        { rewrite cfire_comp_proj. exact EFC. }
        destruct (cascade_live
          (List.length ((o4,z4,c4)%N :: s2t))) as [HFIRE _].
        exact (HFIRE _ _ _ _ ECF). }
      destruct (z4 =? 1)%N eqn:EC.
      { match type of H with
        | context [leaf_act ?s ?ff] =>
            destruct (leaf_act s ff) as [[sfx' fd]|] eqn:ELA
        end; [|kill_comp_rok H].
        apply CE_cdispatch.
        apply (cleaf_act_CE ((o4,z4,c4)%N :: s2t) f sfx' fd).
        rewrite cleaf_act_proj. exact ELA. }
      destruct ((z4 =? 4)%N && (c4 =? 1)%N) eqn:EZ4;
        [|kill_comp_rok H].
      destruct s2t as [|[[on zn] cn] t2].
      * destruct ((o4 =? 4)%N && (1 <=? f)%N) eqn:EO4F;
          [|kill_comp_rok H].
        match type of H with
        | context [last2 ?a] =>
            destruct (last2 a)
              as [[[ini [[gao gaz] gac]] [[gbo gbz] gbc]]|] eqn:EL2
        end; [|kill_comp_rok H].
        destruct ((gao =? 8)%N && (gaz =? 2)%N && (gac =? 1)%N
                  && (gbo =? 4)%N && (gbz =? 2)%N && (1 <=? gbc)%N)
          eqn:EG1.
        { apply CE_cdispatch. apply CE_cx. }
        destruct ((gbo =? 8)%N && (gbz =? 2)%N && (gbc =? 1)%N)
          eqn:EG2; [apply CE_cdispatch; apply CE_cx|kill_comp_rok H].
      * destruct ((o4 =? 4)%N && (on =? 4)%N && (zn =? 2)%N
                  && (1 <=? cn)%N) eqn:EC4.
        { match type of H with
          | context [last2 ?a] =>
              destruct (last2 a)
                as [[[ini [[gao gaz] gac]] [[gbo gbz] gbc]]|] eqn:EL2
          end; [|kill_comp_rok H].
          destruct ((gao =? 8)%N && (gaz =? 2)%N && (gac =? 1)%N
                    && (gbo =? 4)%N && (gbz =? 2)%N && (1 <=? gbc)%N)
            eqn:EG1; [apply CE_cdispatch; apply CE_cx|kill_comp_rok H]. }
        destruct ((4 <? o4)%N && (on =? 4)%N && (zn =? 2)%N
                  && (1 <=? cn)%N) eqn:EC5;
          [apply CE_cdispatch; apply CE_cx|kill_comp_rok H].
  -
    destruct w as [|[[o0 z0] c_0] t]; [discriminate H|].
    match type of H with context [if negb ?b then _ else _] =>
      destruct b eqn:EG0 end; cbn [negb] in H; [|discriminate H].
    match type of H with
    | context [cmf_from ?a ?b ?c] =>
        destruct (cmf_from a b c) as [j|] eqn:ECF
    end.
    + match type of H with context [if negb ?b then _ else _] =>
        destruct b eqn:EFB end; cbn [negb] in H; [|discriminate H].
      match type of H with
      | context [leaf_act ?s ?ff] =>
          destruct (leaf_act s ff) as [[sfx' fd]|] eqn:ELA
      end.
      * apply CE_cdispatch.
        apply (cleaf_act_CE
          (skipn j ((2,2,(c_0+1))%N :: t)) f sfx' fd).
        rewrite cleaf_act_proj. exact ELA.
      * match type of H with
        | context [chain_merge_advance ?a ?b ?c ?d] =>
            destruct (chain_merge_advance a b c d)
        end; discriminate H.
    + match type of H with context [existsb ?p ?l] =>
        destruct (existsb p l) end.
      * match type of H with
        | context [debris_to_blank ?a ?b] =>
            destruct (debris_to_blank a b)
        end; discriminate H.
      * discriminate H.
Qed.
Corollary cfr_span2A_sound_live (w : word) (f : N)
    (w2 : word) (f2 : N) (d : cost) :
  cfr_span2A w f = Some (ROk w2 f2, d) ->
  sound_impl_c d w f w2 f2.
Proof.
  intros E. apply (live_sound d).
  - exact (decorate_live fr_span2A d_span2A d_span2A_live
             w f w2 f2 d E).
  - exact (cfr_span2A_sound w f w2 f2 d E).
Qed.
