Theorem cstep_front_sound_live (w : word) (f : N)
    (w2 : word) (f2 : N) (d : cost) :
  cstep_front w f = Some (ROk w2 f2, d) ->
  sound_impl_c d w f w2 f2.
Proof.
  intros E. unfold cstep_front in E.
  rewrite cfront_rules_unfold in E.
  cbn [cfirst_rule] in E.
  destruct (cfr_primordial w f) as [x|] eqn:E1.
  { injection E as E'; subst x. exact (cfr_primordial_sound _ _ _ _ _ E1). }
  destruct (cfr_prim4 w f) as [x|] eqn:E2.
  { injection E as E'; subst x. exact (cfr_prim4_sound _ _ _ _ _ E2). }
  destruct (cfr_clean w f) as [x|] eqn:E3.
  { injection E as E'; subst x. exact (cfr_clean_sound _ _ _ _ _ E3). }
  destruct (cfr_four w f) as [x|] eqn:E4.
  { injection E as E'; subst x. exact (cfr_four_sound _ _ _ _ _ E4). }
  destruct (cfr_span2A w f) as [x|] eqn:E5.
  { injection E as E'; subst x. exact (cfr_span2A_sound_live _ _ _ _ _ E5). }
  destruct (cfr_span2A' w f) as [x|] eqn:E6.
  { injection E as E'; subst x. exact (cfr_span2A'_sound _ _ _ _ _ E6). }
  destruct (cfr_span2C' w f) as [x|] eqn:E7.
  { injection E as E'; subst x. exact (cfr_span2C'_sound _ _ _ _ _ E7). }
  destruct (cfr_span8far w f) as [x|] eqn:E8.
  { injection E as E'; subst x. exact (cfr_span8far_sound _ _ _ _ _ E8). }
  destruct (cfr_span2B w f) as [x|] eqn:E9.
  { injection E as E'; subst x. exact (cfr_span2B_sound_live _ _ _ _ _ E9). }
  destruct (cfr_span8orph w f) as [x|] eqn:E10.
  { injection E as E'; subst x. exact (cfr_span8orph_sound_live _ _ _ _ _ E10). }
  destruct (cfr_span8 w f) as [x|] eqn:E11.
  { injection E as E'; subst x. exact (cfr_span8_sound_live _ _ _ _ _ E11). }
  destruct (cfr_rot w f) as [x|] eqn:E12.
  { injection E as E'; subst x. exact (cfr_rot_sound _ _ _ _ _ E12). }
  destruct (cfr_502 w f) as [x|] eqn:E13.
  { injection E as E'; subst x. exact (cfr_502_sound _ _ _ _ _ E13). }
  destruct (cfr_512 w f) as [x|] eqn:E14.
  { injection E as E'; subst x. exact (cfr_512_sound _ _ _ _ _ E14). }
  destruct (cfr_522 w f) as [x|] eqn:E15.
  { injection E as E'; subst x. exact (cfr_522_sound _ _ _ _ _ E15). }
  discriminate E.
Qed.
Theorem cstep_sound_live (w : word) (f : N) (h : nat)
    (w' : word) (f' : N) (i : nat) (d : cost) :
  cstep w f h = (ROk w' f', i, d) ->
  sound_impl_c d w f w' f'.
Proof.
  intros HS. unfold cstep in HS.
  destruct (cstep_front w f) as [[r dd]|] eqn:EF.
  - destruct r as [wq fq| |]; try discriminate HS.
    assert (Ed : dd = d) by exact (f_equal snd HS).
    assert (Ew : normalize wq = w')
      by exact (f_equal (fun x => match fst (fst x) with
                         | ROk y _ => y | _ => w' end) HS).
    assert (Ef : fq = f')
      by exact (f_equal (fun x => match fst (fst x) with
                         | ROk _ y => y | _ => f' end) HS).
    rewrite <- Ed, <- Ew, <- Ef.
    apply sound_impl_c_normalize.
    exact (cstep_front_sound_live w f wq fq dd EF).
  - destruct (step_after_front None w f h) as [r i2] eqn:E2.
    destruct r as [wq fq| |]; [|discriminate HS|discriminate HS].
    assert (Ed : d_comp w f h = d) by exact (f_equal snd HS).
    assert (Ew : wq = w')
      by exact (f_equal (fun x => match fst (fst x) with
                         | ROk y _ => y | _ => w' end) HS).
    assert (Ef : fq = f')
      by exact (f_equal (fun x => match fst (fst x) with
                         | ROk _ y => y | _ => f' end) HS).
    rewrite <- Ed. subst wq fq.
    apply (live_sound (d_comp w f h)).
    + exact (d_comp_live w f h w' f' i2 E2).
    + exact (d_comp_sound w f h w' f' i2 E2).
Qed.
