Lemma step_sound_live : forall w f h w' f' i,
  step w f h = (ROk w' f', i) ->
  sound_impl w f w' f'.
Proof.
  intros w f h w' f' i HS.
  destruct (cstep_of_step w f h (ROk w' f') i HS) as [d HC].
  exact (sound_impl_c_transfer d w f w' f'
           (cstep_sound_live w f h w' f' i d HC)).
Qed.
