Lemma adj4_adjk (p : N) (g : bg) :
  adj4 (adjk p g) = adjk (p + 1) g.
Proof.
  destruct g as [[o z] c]. unfold adjk, adj4.
  destruct ((o =? 4) && (z =? 2)) eqn:E; cbn [gO gZ gC].
  - rewrite E. f_equal. rewrite N.mul_add_distr_l, N.mul_1_r.
    symmetry. apply N.sub_add_distr.
  - rewrite E. reflexivity.
Qed.
Lemma lin_pend_step (p : N) (b : word) :
  map adj4 (matb p b) = matb (p + 1) b.
Proof.
  unfold matb. rewrite map_map.
  apply map_ext. intros g. apply adj4_adjk.
Qed.
Lemma sFlat_bump (s : seg) :
  sFlat (bump_pend s) = map adj4 (sFlat s).
Proof.
  destruct s as [[[[[[k p] m] l] bf] bb] cs].
  unfold sFlat, bump_pend, sPend, sBody,
    sFront, sBack.
  symmetry. apply lin_pend_step.
Qed.
Definition notag (g : bg) : bool := negb (phshape g).
Lemma phshape_is_col g : phshape g = true -> is_col g = true.
Proof.
  destruct g as [[o z] c]. unfold phshape, tagbase,
    PHO, is_col.
  cbn [gO gZ gC]. intros H.
  apply andb_prop in H as [H _]. apply andb_prop in H as [Ho Hz].
  apply N.eqb_eq in Ho. apply N.eqb_eq in Hz. subst.
  cbn. reflexivity.
Qed.
Lemma phshape_seek_col g :
  phshape g = true ->
  (is_col g && negb (is_cmf g) && (3 <=? gO g)) = true.
Proof.
  destruct g as [[o z] c]. unfold phshape, tagbase, PHO,
    is_col, is_cmf. cbn [gO gZ gC]. intros H.
  apply andb_prop in H as [H Hc]. apply andb_prop in H as [Ho Hz].
  apply N.eqb_eq in Ho. apply N.eqb_eq in Hz. subst.
  apply N.leb_le in Hc.
  assert (Hc1 : (c =? 1) = false) by (apply N.eqb_neq; lia).
  rewrite Hc1. cbn. reflexivity.
Qed.
Lemma phshape_not_cmf g : phshape g = true -> is_cmf g = false.
Proof.
  destruct g as [[o z] c]. unfold phshape, tagbase,
    PHO, is_cmf.
  cbn [gO gZ gC]. intros H.
  apply andb_prop in H as [_ Hc]. apply N.leb_le in Hc.
  assert (Hc1 : (c =? 1) = false) by (apply N.eqb_neq; lia).
  rewrite Hc1. rewrite andb_false_r, andb_false_l. reflexivity.
Qed.
Lemma phshape_o (g : bg) :
  phshape g = true -> gO g = 9%N /\ gZ g = 2%N.
