Proof. unfold keyb. rewrite keyi_nil. reflexivity. Qed.
Lemma lin_flat_nil (w : word) : lin_flat [] w = w.
Proof.
  induction w as [|g t IH]; [reflexivity|].
  cbn [lin_flat]. rewrite keyb_nil, IH. reflexivity.
Qed.
Definition front_gate (cw : word) (f : N) : option res :=
  if lin_front_possible cw
  then first_rule front_rules cw f else None.
Definition splice_call (sg : list seg) (front : option res)
    (cw : word) (f : N) (h : nat) : res * nat :=
  step_after_front_with_guard false
    (lin_normalize_at sg)
    (fun pre sfx _ => lin_normalize_join sg pre sfx)
    front cw f h.
Definition keys_big (sg : list seg) : Prop :=
  forall s, In s sg -> (KMAGIC <= sKey s)%N.
Definition sg_shape (sg : list seg) : Prop :=
  forallb segshape sg = true.
Definition ok_guard (sg : list seg) (cw : word) : Prop :=
  lin_ok sg cw = true /\ lin_guard sg cw = true /\
  keys_big sg /\ lin_tags sg cw = true.
Theorem zjump_sound_impl :
  forall w f h t w' f' h',
    zjump3 w f h = Some (t, (w', f', h')) ->
    sound_impl w f w' f'.
Proof.
  intros w f h t w' f' h' HZ.
  exact (stepN_sound_impl step_sound_live
           t w f h w' f' h'
           (zjump3_sound _ _ _ _ _ HZ)).
Qed.
Theorem splice_halt_confirmed :
  forall sg cw f,
    fst (lin_halt_confirm sg cw f) = true ->
    halts tmB (wconf [] 0 (sdecode (lin_flat sg cw) f)).
Proof.
  intros sg cw f HC. unfold lin_halt_confirm in HC.
  destruct (cstep (lin_flat sg cw) f O)
    as [[[w2 f2| |] j] d] eqn:ES; cbn [fst] in HC; try discriminate.
  exact (StepGuard_holds _ _ _ _ (cstep_res _ _ _ _ _ _ ES)).
Qed.
Definition T_cond : Prop :=
  forall w h cw sg h0,
    lin_cond w h = Some (cw, sg, h0) ->
    lin_flat sg cw = w /\ ok_guard sg cw.
