Lemma sound_refl w f : sound_impl w f w f.
Proof. exact (fun H => H). Qed.
Lemma sound_trans a fa b fb c fc :
  sound_impl a fa b fb ->
  sound_impl b fb c fc ->
  sound_impl a fa c fc.
Proof. intros H1 H2 H. exact (H1 (H2 H)). Qed.
Lemma fallback_run_next :
  forall fu T w f h k m k' m' s',
    lp_fallback_round_run fu T w f h k m = LPNext k' m' s' ->
    exists w' f' h', s' = LPFlat w' f' h' /\
      sound_impl w f w' f'.
Proof.
  induction fu as [|fu IH]; intros T w f h k m k' m' s' Hrun;
    cbn [lp_fallback_round_run] in Hrun; cbv zeta in Hrun.
  - inversion Hrun; subst. do 3 eexists.
    split; [reflexivity|]. exact (sound_refl _ _).
  -
    destruct (lin_zsp w f h)
      as [[[t2 [[w2 f2] h2]] dz]|] eqn:EZ.
    + destruct (IH _ _ _ _ _ _ _ _ _ Hrun) as (w' & f' & h' & -> & HS).
      do 3 eexists. split; [reflexivity|].
      exact (sound_trans _ _ _ _ _ _
               (zjump_sound_impl _ _ _ _ _ _ _
                  (lin_zsp_proj _ _ _ _ _ _ EZ)) HS).
    + destruct (step w f h) as [[w2 f2| |] i] eqn:ES.
      *
        destruct (lin_round_closing w f).
        -- inversion Hrun; subst. do 3 eexists. split; [reflexivity|].
           exact (step_sound_live _ _ _ _ _ _ ES).
        -- destruct (IH _ _ _ _ _ _ _ _ _ Hrun)
             as (w' & f' & h' & -> & HS).
           do 3 eexists. split; [reflexivity|].
           exact (sound_trans _ _ _ _ _ _
               (step_sound_live _ _ _ _ _ _ ES) HS).
      * discriminate.
      * discriminate.
Qed.
Lemma fallback_run_guard :
  forall fu T w f h k m k' m' wg fg,
    lp_fallback_round_run fu T w f h k m
      = LPGuard k' m' wg fg ->
    halts tmB (wconf [] 0 (sdecode w f)).
Proof.
  induction fu as [|fu IH]; intros T w f h k m k' m' wg fg Hrun;
    cbn [lp_fallback_round_run] in Hrun; cbv zeta in Hrun.
  - discriminate.
  - destruct (lin_zsp w f h)
      as [[[t2 [[w2 f2] h2]] dz]|] eqn:EZ.
    + exact (zjump_sound_impl _ _ _ _ _ _ _
               (lin_zsp_proj _ _ _ _ _ _ EZ)
               (IH _ _ _ _ _ _ _ _ _ _ Hrun)).
    + destruct (step w f h) as [[w2 f2| |] i] eqn:ES.
      *
        destruct (lin_round_closing w f); [discriminate|].
        exact (step_sound_live _ _ _ _ _ _ ES
                 (IH _ _ _ _ _ _ _ _ _ _ Hrun)).
      * inversion Hrun; subst.
        exact (StepGuard_holds _ _ _ _ ES).
      * discriminate.
Qed.
Lemma fallback_lps_guard w f h k m len fg lm :
  lps_of_lpnext (lp_fallback_round w f h)
    = LPSGuard k m len fg lm ->
  halts tmB (wconf [] 0 (sdecode w f)).
Proof.
  unfold lp_fallback_round. intros H.
  destruct (lp_fallback_round_run FLAT_ROUND_FUEL
      None w f h nc0 O) as [k1 m1 s1|k1 m1 w1 f1|k1 m1 w1 f1] eqn:EF;
    cbn [lps_of_lpnext] in H; try discriminate.
  exact (fallback_run_guard _ _ _ _ _ _ _ _ _ _ _ EF).
Qed.
Lemma adjk_0 (g : bg) : adjk 0 g = g.
Proof.
  destruct g as [[o z] c]. unfold adjk.
  destruct ((o =? 4) && (z =? 2)); [|reflexivity].
  f_equal. lia.
Qed.
Lemma matb_0 (b : word) : matb 0 b = b.
Proof.
  unfold matb.
  transitivity (List.map (fun x => x) b).
  - apply List.map_ext. exact adjk_0.
  - apply List.map_id.
Qed.
Lemma split_body_id (b : word) :
  fst (split_body b) ++ rev (snd (split_body b)) = b.
Proof.
  unfold split_body. cbn [fst snd].
  rewrite rev_involutive. apply firstn_skipn.
Qed.
Lemma countkey_app (k : N) (a b : word) :
  countkey k (a ++ b)
    = (countkey k a + countkey k b)%nat.
Proof.
  induction a as [|g a IH]; [reflexivity|].
  cbn [app countkey]. rewrite IH. lia.
Qed.
Lemma countkey_in (g : bg) (a : word) :
  In g a -> phshape g = true ->
  countkey (gC g) a <> O.
Proof.
  induction a as [|g0 a IH]; intros Hin El; [contradiction|].
  cbn [countkey].
  destruct Hin as [<-|Hin].
  - rewrite El, N.eqb_refl. cbn. lia.
  - specialize (IH Hin El). lia.
Qed.
Lemma lin_flat_cons sg g w :
  lin_flat sg (g :: w)
  = match keyb sg g with
    | Some b => b ++ lin_flat sg w
    | None => g :: lin_flat sg w
    end.
Proof. reflexivity. Qed.
Lemma keyi_none_of_counts sg (g : bg) (a : word) :
  In g a ->
  (forall s, In s sg -> countkey (sKey s) a = O) ->
  keyi sg g = None.
Proof.
  intros Hin Hz. unfold keyi.
  destruct (phshape g) eqn:El; [|reflexivity].
  induction sg as [|s sg IH]; [reflexivity|].
  cbn.
  destruct (gC g =? sKey s) eqn:Ek.
  - exfalso. apply N.eqb_eq in Ek.
    apply (countkey_in g a Hin El).
    rewrite Ek. exact (Hz s (or_introl eq_refl)).
  - apply IH. intros s' Hs'. exact (Hz s' (or_intror Hs')).
Qed.
Lemma lin_flat_nomatch sg (a : word) :
  (forall s, In s sg -> countkey (sKey s) a = O) ->
  lin_flat sg a = a.
Proof.
  induction a as [|g a IH]; intros Hz; [reflexivity|].
  cbn [lin_flat].
  assert (Ek : keyb sg g = None).
  { unfold keyb.
    rewrite (keyi_none_of_counts sg g (g::a) (or_introl eq_refl) Hz).
    reflexivity. }
  rewrite Ek. f_equal. apply IH.
  intros s Hs. specialize (Hz s Hs).
  cbn [countkey] in Hz. lia.
Qed.
Lemma lin_flat_app_c sg (a b : word) :
  lin_flat sg (a ++ b)
    = lin_flat sg a ++ lin_flat sg b.
Proof.
  induction a as [|g a IH]; [reflexivity|].
  cbn [app lin_flat].
  destruct (keyb sg g).
  - rewrite IH. apply app_assoc.
  - rewrite IH. reflexivity.
Qed.
Lemma lin_flat_skip_seg s0 sg (a : word) :
  countkey (sKey s0) a = O ->
  lin_flat (s0 :: sg) a = lin_flat sg a.
Proof.
  induction a as [|g a IH]; intros Hz; [reflexivity|].
  cbn [lin_flat].
  assert (Ek : keyb (s0::sg) g = keyb sg g).
  { unfold keyb, keyi.
    destruct (phshape g) eqn:El; [|reflexivity].
    destruct (gC g =? sKey s0) eqn:E0.
    - exfalso. apply N.eqb_eq in E0.
      apply (countkey_in g (g::a) (or_introl eq_refl) El).
      rewrite E0. exact Hz.
    - reflexivity. }
  rewrite Ek.
  cbn [countkey] in Hz.
  destruct (keyb sg g); f_equal; apply IH; lia.
Qed.
Lemma lapply_keys_present :
  forall pl w off kx cw sg,
    (2 <= kx)%N ->
    lapply pl w off kx = (cw, sg) ->
    forall s, In s sg -> (1 <= countkey (sKey s) cw)%nat.
Proof.
  induction pl as [|[st l] pl IH]; intros w off kx cw sg Hkx H s Hin.
  - cbn in H. inversion H; subst cw sg. contradiction.
  - assert (Hkx1 : (2 <= kx + 1)%N) by lia.
    cbn [lapply] in H.
    destruct (split_body (firstn l (skipn (st - off) w)))
      as [bf bb] eqn:ESB.
    cbv beta iota zeta in H.
    destruct (lapply pl (skipn ((st - off) + l) w)
                (st + l) (kx + 1))
      as [cw2 sg2] eqn:EL.
    cbv beta iota zeta in H.
    inversion H; subst cw sg. clear H.
    destruct Hin as [<-|Hin].
    + cbn [sKey]. rewrite countkey_app.
      cbn [countkey].
      rewrite (phshape_phg kx Hkx), gC_phg, N.eqb_refl. cbn [andb]. lia.
    + rewrite countkey_app. cbn [countkey].
      pose proof (IH _ _ _ _ _ Hkx1 EL s Hin). lia.
Qed.
Lemma lapply_flat :
  forall pl w off kx cw sg,
    (2 <= kx)%N ->
    lapply pl w off kx = (cw, sg) ->
    lin_ok sg cw = true ->
    lin_flat sg cw = w.
Proof.
  induction pl as [|[st l] pl IH]; intros w off kx cw sg Hkx H HOk.
  - cbn in H. inversion H; subst cw sg. apply lin_flat_nil.
  - assert (Hkx1 : (2 <= kx + 1)%N) by lia.
    cbn [lapply] in H.
    destruct (split_body (firstn l (skipn (st - off) w)))
      as [bf bb] eqn:ESB.
    cbv beta iota zeta in H.
    destruct (lapply pl (skipn ((st - off) + l) w)
                (st + l) (kx + 1))
      as [cw2 sg2] eqn:EL.
    cbv beta iota zeta in H.
    inversion H; subst cw sg. clear H.
    unfold lin_ok in HOk. cbn [forallb] in HOk.
    apply andb_prop in HOk. destruct HOk as [Hk1 Hrest].
    apply PeanoNat.Nat.eqb_eq in Hk1.
    rewrite countkey_app in Hk1.
    cbn [countkey sKey] in Hk1.
    rewrite (phshape_phg kx Hkx), gC_phg, N.eqb_refl in Hk1.
    cbn [andb] in Hk1.
    assert (Hpre0 : countkey kx (firstn (st - off) w) = O)
      by lia.
    assert (Hcw20 : countkey kx cw2 = O) by lia.
    assert (Htail : forall s, In s sg2 ->
        countkey (sKey s) (firstn (st - off) w) = O
        /\ countkey (sKey s) cw2 = 1%nat).
    { intros s Hin.
      pose proof (proj1 (List.forallb_forall _ _) Hrest s Hin) as Hs.
      apply PeanoNat.Nat.eqb_eq in Hs.
      rewrite countkey_app in Hs.
      cbn [countkey] in Hs.
      pose proof (lapply_keys_present _ _ _ _ _ _ Hkx1 EL s Hin) as Hge.
      lia. }
    rewrite lin_flat_app_c.
    rewrite lin_flat_nomatch.
    2: { intros s Hin. destruct Hin as [<-|Hin].
         - exact Hpre0.
         - exact (proj1 (Htail s Hin)). }
    rewrite lin_flat_cons.
    assert (EK : keyb
        ((kx, 0%N, minlvl (firstn l (skipn (st - off) w)),
          length (firstn l (skipn (st - off) w)), bf, bb,
          bsum (firstn l (skipn (st - off) w))) :: sg2)
        (phg kx)
      = Some (sFlat
          (kx, 0%N, minlvl (firstn l (skipn (st - off) w)),
           length (firstn l (skipn (st - off) w)), bf, bb,
           bsum (firstn l (skipn (st - off) w))))).
    { unfold keyb, keyi.
      rewrite (phshape_phg kx Hkx), gC_phg.
      cbn [sKey]. rewrite N.eqb_refl. reflexivity. }
    rewrite EK. cbv beta iota.
    assert (EB : sFlat
        (kx, 0%N, minlvl (firstn l (skipn (st - off) w)),
         length (firstn l (skipn (st - off) w)), bf, bb,
         bsum (firstn l (skipn (st - off) w)))
      = firstn l (skipn (st - off) w)).
    { unfold sFlat.
      cbn [sPend sBody sFront sBack].
      rewrite matb_0.
      pose proof (split_body_id (firstn l (skipn (st - off) w))) as E.
      rewrite ESB in E. cbn [fst snd] in E. exact E. }
    rewrite EB.
    rewrite lin_flat_skip_seg
      by (cbn [sKey]; exact Hcw20).
    assert (HOk2 : lin_ok sg2 cw2 = true).
    { unfold lin_ok. apply List.forallb_forall.
      intros s Hin. apply PeanoNat.Nat.eqb_eq.
      exact (proj2 (Htail s Hin)). }
    rewrite (IH _ _ _ _ _ Hkx1 EL HOk2).
    transitivity
      (firstn (st - off) w ++ skipn (st - off) w);
      [|apply firstn_skipn].
    f_equal.
    rewrite <- (firstn_skipn l (skipn (st - off) w)) at 2.
    f_equal.
    rewrite List.skipn_skipn.
    f_equal. lia.
Qed.
Theorem T_cond_flat_ok :
  forall w h cw sg h0,
    lin_cond w h = Some (cw, sg, h0) ->
    lin_flat sg cw = w /\ lin_ok sg cw = true.
Proof.
  intros w h cw sg h0 H.
  unfold lin_cond in H.
  destruct (lplan (length w) w O) as [|p pl0] eqn:EP;
    [discriminate|].
  destruct (lin_condk KMAGIC w h)
    as [[[cw1 sg1] h1]|] eqn:EC; [|discriminate].
  destruct (lin_ok sg1 cw1) eqn:EOk; [|discriminate].
  destruct (lin_tags sg1 cw1) eqn:ETags; [|discriminate].
  inversion H; subst cw1 sg1 h1.
  split; [|exact EOk].
  unfold lin_condk in EC.
  rewrite EP in EC.
  destruct (lapply (p :: pl0) w O KMAGIC)
    as [cw' sg'] eqn:ELap.
  cbv beta iota zeta in EC.
  destruct (forallb (fun s => segcache s && segok s) sg');
    [|discriminate].
  destruct (forallb segshape sg'); [|discriminate].
  destruct (forallb segpos sg'); [|discriminate].
  inversion EC; subst cw' sg'.
  exact (lapply_flat _ _ _ _ _ _ KMAGIC_2 ELap EOk).
Qed.
Lemma takerun_split :
  forall w, fst (takerun w) ++ snd (takerun w) = w.
Proof.
  induction w as [|g w IH]; [reflexivity|].
  cbn [takerun].
  destruct (casc g); [|reflexivity].
  destruct (takerun w) as [a b]. cbn [fst snd] in *.
  cbn [app]. now rewrite IH.
Qed.
Lemma takerun_casc :
  forall w, forallb casc (fst (takerun w)) = true.
Proof.
  induction w as [|g w IH]; [reflexivity|].
  cbn [takerun].
  destruct (casc g) eqn:Ec; [|reflexivity].
  destruct (takerun w) as [a b]. cbn [fst snd] in *.
  cbn [forallb]. now rewrite Ec, IH.
Qed.
Fixpoint lgw (sg : list seg) (w : word)
    (before need : nat) : option (nat * nat) :=
  match w with
  | [] => Some (before, need)
  | g :: t =>
      let isph := ph sg g in
      if Nat.ltb O need then
        if isph || negb (casc g) then None
        else lgw sg t (S before) (need - 1)
      else if isph then
        if Nat.ltb before GUARD then None else lgw sg t O GUARD
      else if casc g then lgw sg t (S before) O
      else lgw sg t O O
  end.
Lemma lguard_lgw :
  forall sg w before need,
    lguard sg w before need
    = match lgw sg w before need with
      | Some (_, n') => Nat.eqb n' O
      | None => false
      end.
Proof.
  intros sg w. induction w as [|g w IH]; intros before need.
  - reflexivity.
  - cbn [lguard lgw].
    destruct (Nat.ltb O need).
    + destruct (ph sg g || negb (casc g)); [reflexivity|].
      apply IH.
    + destruct (ph sg g).
      * destruct (Nat.ltb before GUARD); [reflexivity|]. apply IH.
      * destruct (casc g); apply IH.
Qed.
Lemma lgw_app :
  forall sg a b before need,
    lgw sg (a ++ b) before need
    = match lgw sg a before need with
      | Some (b', n') => lgw sg b b' n'
      | None => None
      end.
Proof.
  intros sg a. induction a as [|g a IH]; intros b before need.
  - reflexivity.
  - cbn [app lgw].
    destruct (Nat.ltb O need).
    + destruct (ph sg g || negb (casc g)); [reflexivity|].
      apply IH.
    + destruct (ph sg g).
      * destruct (Nat.ltb before GUARD); [reflexivity|]. apply IH.
      * destruct (casc g); apply IH.
Qed.
Lemma lgw_clean_block :
  forall sg a before need,
    forallb casc a = true ->
    (forall g, In g a -> ph sg g = false) ->
    lgw sg a before need
    = Some ((before + length a)%nat, (need - length a)%nat).
Proof.
  intros sg a. induction a as [|g a IH]; intros before need Hc Hp.
  - cbn. f_equal. f_equal; lia.
  - cbn [forallb] in Hc. apply andb_prop in Hc as [Hcg Hc].
    cbn [lgw].
    rewrite (Hp g (or_introl eq_refl)).
    destruct (Nat.ltb O need) eqn:En.
    + apply PeanoNat.Nat.ltb_lt in En.
      cbn [orb]. rewrite Hcg. cbn [negb].
      rewrite IH; [|exact Hc|intros g' H'; exact (Hp g' (or_intror H'))].
      cbn [length]. f_equal. f_equal; lia.
    + apply PeanoNat.Nat.ltb_ge in En.
      rewrite Hcg.
      rewrite IH; [|exact Hc|intros g' H'; exact (Hp g' (or_intror H'))].
      cbn [length]. f_equal. f_equal; lia.
Qed.
Lemma In_firstn : forall (g : bg) n l, In g (firstn n l) -> In g l.
Proof.
  intros g n l H. rewrite <- (firstn_skipn n l).
  apply in_or_app. left. exact H.
Qed.
Lemma In_skipn : forall (g : bg) n l, In g (skipn n l) -> In g l.
Proof.
  intros g n l H. rewrite <- (firstn_skipn n l).
  apply in_or_app. right. exact H.
Qed.
Lemma forallb_sub : forall (p : bg -> bool) a b,
  (forall g, In g a -> In g b) ->
  forallb p b = true -> forallb p a = true.
Proof.
  intros p a b Hincl Hb. apply forallb_forall.
  intros g Hg. eapply forallb_forall in Hb; [exact Hb|].
  exact (Hincl g Hg).
Qed.
Lemma lgw_nonph_runs : forall sg a x,
  (forall g, In g a -> ph sg g = false) ->
  exists y, lgw sg a x O = Some (y, O).
Proof.
  intros sg a. induction a as [|g t IH]; intros x Hp.
  - exists x. reflexivity.
  - assert (Hp' : forall g', In g' t -> ph sg g' = false)
      by (intros g' H'; exact (Hp g' (or_intror H'))).
    destruct (casc g) eqn:Ec.
    + cbn [lgw]. rewrite (Hp g (or_introl eq_refl)), Ec.
      cbn [Nat.ltb Nat.leb]. exact (IH (S x) Hp').
    + cbn [lgw]. rewrite (Hp g (or_introl eq_refl)), Ec.
      cbn [Nat.ltb Nat.leb]. exact (IH O Hp').
Qed.
Lemma lgw_need_head : forall sg a x need,
  (forall g, In g a -> ph sg g = false) ->
  (need <= GUARD)%nat ->
  (GUARD <= length a)%nat ->
  forallb casc (firstn GUARD a) = true ->
  exists y, lgw sg a x need = Some (y, O).
Proof.
  intros sg a x need Hp Hn Hl Hc.
  rewrite <- (firstn_skipn GUARD a).
  rewrite lgw_app.
  rewrite (lgw_clean_block sg _ x need Hc).
  2:{ intros g Hg. exact (Hp g (In_firstn _ _ _ Hg)). }
  rewrite length_firstn.
  replace (Init.Nat.min GUARD (length a)) with GUARD by lia.
  replace (need - GUARD)%nat with O by (unfold GUARD in *; lia).
  apply lgw_nonph_runs.
  intros g Hg. exact (Hp g (In_skipn _ _ _ Hg)).
Qed.
Lemma lgw_end_before : forall sg a x need y n',
  (forall g, In g a -> ph sg g = false) ->
  forallb casc (skipn (length a - GUARD) a) = true ->
  (GUARD <= length a)%nat ->
  lgw sg a x need = Some (y, n') ->
  (GUARD <= y)%nat.
Proof.
  intros sg a. induction a as [|g t IH]; intros x need y n' Hp Hw Hl Hrun.
  - cbn [length] in Hl. unfold GUARD in Hl. lia.
  - assert (Hp' : forall g', In g' t -> ph sg g' = false)
      by (intros g' H'; exact (Hp g' (or_intror H'))).
    destruct (PeanoNat.Nat.le_gt_cases GUARD (length t)) as [Hge|Hlt].
    + cbn [length] in Hw.
      replace (S (length t) - GUARD)%nat
        with (S (length t - GUARD))%nat in Hw
        by (unfold GUARD in *; lia).
      cbn [skipn] in Hw.
      cbn [lgw] in Hrun.
      rewrite (Hp g (or_introl eq_refl)) in Hrun.
      destruct (Nat.ltb O need) eqn:En; rewrite ?En in Hrun.
      * destruct (casc g) eqn:Ec; cbn in Hrun.
        -- exact (IH _ _ _ _ Hp' Hw Hge Hrun).
        -- discriminate.
      * destruct (casc g) eqn:Ec; cbn in Hrun.
        -- exact (IH _ _ _ _ Hp' Hw Hge Hrun).
        -- exact (IH _ _ _ _ Hp' Hw Hge Hrun).
    + assert (Ha : length (g :: t) = GUARD).
      { cbn [length]. cbn [length] in Hl. unfold GUARD in *. lia. }
      rewrite Ha, PeanoNat.Nat.sub_diag in Hw. cbn [skipn] in Hw.
      rewrite (lgw_clean_block sg (g :: t) x need Hw Hp) in Hrun.
      injection Hrun as Hy Hn.
      cbn [length] in Ha, Hy. unfold GUARD in *. lia.
Qed.
Fixpoint lkept (pl : list (nat * nat)) (w : word) (off : nat)
  : word :=
  match pl with
  | [] => w
  | (s, l) :: pl' =>
      firstn (s - off) w ++ lkept pl' (skipn ((s - off) + l) w) (s + l)%nat
  end.
Lemma lapply_kept_lower :
  forall pl w off kx k,
    (countkey k (lkept pl w off)
     <= countkey k (fst (lapply pl w off kx)))%nat.
Proof.
  induction pl as [|[st l] pl IH]; intros w off kx k.
  - cbn. lia.
  - cbn [lapply lkept].
    destruct (split_body (firstn l (skipn (st - off) w)))
      as [bf bb] eqn:ESB.
    cbv beta iota zeta.
    destruct (lapply pl (skipn ((st - off) + l) w)
                (st + l) (kx + 1))
      as [cw2 sg2] eqn:EL.
    cbv beta iota zeta. cbn [fst].
    rewrite !countkey_app. cbn [countkey].
    pose proof (IH (skipn ((st - off) + l) w) (st + l)%nat ((kx+1)%N) k) as H.
    rewrite EL in H. cbn [fst] in H. lia.
Qed.
Lemma lapply_seg_count :
  forall pl w off kx cw sg s,
    (2 <= kx)%N ->
    lapply pl w off kx = (cw, sg) ->
    In s sg ->
    (1 + countkey (sKey s) (lkept pl w off)
     <= countkey (sKey s) cw)%nat.
Proof.
  induction pl as [|[st l] pl IH]; intros w off kx cw sg s Hkx H Hin.
  - cbn in H. inversion H; subst cw sg. contradiction.
  - assert (Hkx1 : (2 <= kx + 1)%N) by lia.
    cbn [lapply] in H.
    destruct (split_body (firstn l (skipn (st - off) w)))
      as [bf bb] eqn:ESB.
    cbv beta iota zeta in H.
    destruct (lapply pl (skipn ((st - off) + l) w)
                (st + l) (kx + 1))
      as [cw2 sg2] eqn:EL.
    cbv beta iota zeta in H.
    inversion H; subst cw sg. clear H.
    cbn [lkept]. rewrite !countkey_app. cbn [countkey].
    destruct Hin as [<-|Hin].
    + cbn [sKey].
      rewrite (phshape_phg kx Hkx), gC_phg, N.eqb_refl. cbn [andb].
      pose proof (lapply_kept_lower pl (skipn ((st - off) + l) w)
                    (st + l)%nat ((kx+1)%N) kx) as H.
      rewrite EL in H. cbn [fst] in H. lia.
    + pose proof (IH _ _ _ _ _ _ Hkx1 EL Hin) as H. lia.
Qed.
Lemma lin_ok_kept_nonph :
  forall pl w off kx cw sg,
    (2 <= kx)%N ->
    lapply pl w off kx = (cw, sg) ->
    lin_ok sg cw = true ->
    forall g, In g (lkept pl w off) -> ph sg g = false.
Proof.
  intros pl w off kx cw sg Hkx HL HOk g Hg.
  unfold ph.
  rewrite (keyi_none_of_counts sg g (lkept pl w off) Hg); [reflexivity|].
  intros s Hs.
  pose proof (lapply_seg_count pl w off kx cw sg s Hkx HL Hs) as Hc.
  unfold lin_ok in HOk.
  eapply forallb_forall in HOk; [|exact Hs].
  apply PeanoNat.Nat.eqb_eq in HOk. lia.
Qed.
Fixpoint plan_okP (pl : list (nat * nat)) (w : word) (i : nat)
  : Prop :=
  match pl with
  | [] => True
  | (s, l) :: pl' =>
      (i <= s)%nat /\
      (GUARD <= s - i)%nat /\
      forallb casc
        (skipn (s - i - GUARD) (firstn (s - i) w)) = true /\
      forallb casc
        (firstn GUARD (skipn ((s - i) + l) w)) = true /\
      (GUARD <= length (skipn ((s - i) + l) w))%nat /\
      plan_okP pl' (skipn ((s - i) + l) w) (s + l)%nat
  end.
Lemma lplan_lb :
  forall fu w i s l,
    In (s, l) (lplan fu w i) -> (i + GUARD <= s)%nat.
Proof.
  induction fu as [|fu IH]; intros w i s l Hin.
  - cbn in Hin. contradiction.
  - destruct w as [|g t]; [cbn in Hin; contradiction|].
    cbn [lplan] in Hin.
    destruct (casc g) eqn:Ec.
    2:{ cbv beta iota in Hin. apply IH in Hin. lia. }
    destruct (takerun (g :: t)) as [r rest] eqn:ET.
    cbv beta iota zeta in Hin.
    destruct (Nat.leb (2 * MARG + SEGMIN_GROUPS) (length r))
      eqn:E1.
    2:{ cbv beta iota in Hin. apply IH in Hin. lia. }
    cbv beta iota in Hin.
    match type of Hin with
    | In _ (if ?gate then _ else _) => destruct gate eqn:EG
    end.
    2:{ cbv beta iota in Hin. apply IH in Hin. lia. }
    cbv beta iota in Hin.
    destruct Hin as [Hhd|Hin].
    2:{ apply IH in Hin. lia. }
    injection Hhd as Hs Hl.
    subst s.
    match goal with
    | |- (i + GUARD <= i + ?a)%nat =>
        assert (HA : (MARG <= a)%nat)
          by (destruct (is_lvl (nth MARG r d0));
              cbv beta iota; lia)
    end.
    unfold GUARD, MARG in *. lia.
Qed.
Lemma plan_okP_shift_pre :
  forall pl pre t i,
    plan_okP pl t (i + length pre)%nat ->
    (forall s l, In (s, l) pl -> (i + length pre + GUARD <= s)%nat) ->
    plan_okP pl (pre ++ t) i.
Proof.
  intros pl pre t i HP HB.
  destruct pl as [|[s l] pl']; [exact I|].
  cbn [plan_okP] in HP |- *.
  destruct HP as (H1 & H2 & H3 & H4 & H5 & H6).
  pose proof (HB s l (or_introl eq_refl)) as Hs.
  assert (HS : skipn ((s - i) + l)%nat (pre ++ t)
               = skipn ((s - (i + length pre)) + l)%nat t).
  { rewrite skipn_app.
    assert (HK : skipn ((s - i) + l)%nat pre = [])
      by (apply skipn_all2; lia).
    rewrite HK. cbn [app]. f_equal. lia. }
  repeat split.
  - lia.
  - lia.
  - rewrite firstn_app.
    assert (HF : firstn (s - i)%nat pre = pre) by (apply firstn_all2; lia).
    rewrite HF.
    rewrite skipn_app.
    assert (HK : skipn ((s - i) - GUARD)%nat pre = [])
      by (apply skipn_all2; lia).
    rewrite HK. cbn [app].
    replace ((s - i) - GUARD - length pre)%nat
      with ((s - (i + length pre)) - GUARD)%nat by lia.
    replace ((s - i) - length pre)%nat
      with (s - (i + length pre))%nat by lia.
    exact H3.
  - rewrite HS. exact H4.
  - rewrite HS. exact H5.
  - rewrite HS. exact H6.
Qed.
Lemma lplan_run_shift :
  forall fu' w r rest i,
    (forall w' i', plan_okP (lplan fu' w' i') w' i') ->
    takerun w = (r, rest) ->
    plan_okP (lplan fu' rest (i + length r)%nat) w i.
Proof.
  intros fu' w r rest i IH ET.
  pose proof (takerun_split w) as HW. rewrite ET in HW. cbn [fst snd] in HW.
  rewrite <- HW.
  apply plan_okP_shift_pre.
  - apply IH.
  - intros s l Hin.
    pose proof (lplan_lb fu' rest (i + length r)%nat s l Hin). lia.
Qed.
Lemma lplan_entry_ok :
  forall fu' w r rest i a b,
    (forall w' i', plan_okP (lplan fu' w' i') w' i') ->
    takerun w = (r, rest) ->
    (2 * MARG + SEGMIN_GROUPS <= length r)%nat ->
    (MARG <= a)%nat ->
    (a <= S MARG)%nat ->
    (b <= length r - MARG)%nat ->
    (a < b)%nat ->
    plan_okP (((i + a)%nat, (b - a)%nat)
                :: lplan fu' rest (i + length r)%nat) w i.
Proof.
  intros fu' w r rest i a b IH ET Hn Ha1 Ha2 Hb1 Hab.
  pose proof (takerun_split w) as HW. rewrite ET in HW. cbn [fst snd] in HW.
  pose proof (takerun_casc w) as HC. rewrite ET in HC. cbn [fst] in HC.
  subst w.
  unfold MARG, SEGMIN_GROUPS, SEGMIN in Hn, Ha1, Ha2, Hb1.
  cbn [plan_okP].
  replace ((i + a) - i)%nat with a by lia.
  replace (a + (b - a))%nat with b by lia.
  replace ((i + a) + (b - a))%nat with (i + b)%nat by lia.
  repeat split.
  - lia.
  - unfold GUARD. lia.
  - rewrite firstn_app.
    replace (a - length r)%nat with O by lia.
    rewrite firstn_O, app_nil_r.
    eapply forallb_sub; [|exact HC].
    intros g' Hg'. eapply In_firstn. eapply In_skipn. exact Hg'.
  - rewrite skipn_app.
    replace (b - length r)%nat with O by lia.
    cbn [skipn].
    rewrite firstn_app.
    replace (GUARD - length (skipn b r))%nat with O
      by (rewrite length_skipn; unfold GUARD; lia).
    rewrite firstn_O, app_nil_r.
    eapply forallb_sub; [|exact HC].
    intros g' Hg'. eapply In_skipn. eapply In_firstn. exact Hg'.
  - rewrite length_skipn, length_app.
    unfold GUARD. lia.
  - rewrite skipn_app.
    replace (b - length r)%nat with O by lia.
    cbn [skipn].
    apply plan_okP_shift_pre.
    + rewrite length_skipn.
      replace ((i + b) + (length r - b))%nat with (i + length r)%nat by lia.
      apply IH.
    + intros s' l' Hin'.
      pose proof (lplan_lb fu' rest (i + length r)%nat s' l' Hin') as HB.
      rewrite length_skipn. lia.
Qed.
Lemma lplan_plan_okP :
  forall fu w i, plan_okP (lplan fu w i) w i.
Proof.
  induction fu as [|fu IH]; intros w i.
  - exact I.
  - destruct w as [|g t].
    + exact I.
    + cbn [lplan].
      destruct (casc g) eqn:Ec.
      2:{ cbv beta iota.
          change (g :: t) with ([g] ++ t).
          apply plan_okP_shift_pre.
          - cbn [length].
            replace (i + 1)%nat with (S i) by lia.
            apply IH.
          - cbn [length]. intros s l Hin.
            pose proof (lplan_lb fu t (S i) s l Hin). lia. }
      destruct (takerun (g :: t)) as [r rest] eqn:ET.
      cbv beta iota zeta.
      destruct (Nat.leb (2 * MARG + SEGMIN_GROUPS) (length r))
        eqn:E1.
      2:{ cbv beta iota. eapply lplan_run_shift; [exact IH|exact ET]. }
      apply PeanoNat.Nat.leb_le in E1.
      cbv beta iota.
      match goal with
      | |- plan_okP (if ?gate then _ else _) _ _ => destruct gate eqn:EG
      end.
      2:{ eapply lplan_run_shift; [exact IH|exact ET]. }
      apply andb_prop in EG. destruct EG as [EG1 EL2].
      apply PeanoNat.Nat.ltb_lt in EL2.
      apply lplan_entry_ok.
      * exact IH.
      * exact ET.
      * exact E1.
      * destruct (is_lvl (nth MARG r d0));
          cbv beta iota; unfold MARG; lia.
      * destruct (is_lvl (nth MARG r d0));
          cbv beta iota; lia.
      * destruct (is_lvl
                    (nth (length r - MARG - 1) r d0));
          cbv beta iota; lia.
      * exact EL2.
Qed.
Lemma lapply_lgw :
  forall pl sg w i kx x need,
    plan_okP pl w i ->
    (forall g, In g (lkept pl w i) -> ph sg g = false) ->
    (need = O \/
     ((need <= GUARD)%nat /\
      forallb casc (firstn GUARD w) = true /\
      (GUARD <= length w)%nat)) ->
    exists y, lgw sg (fst (lapply pl w i kx)) x need = Some (y, O).
Proof.
  induction pl as [|[s l] pl' IH]; intros sg w i kx x need HP Hnp Hneed.
  - cbn [lapply fst].
    destruct Hneed as [->|(Hn1 & Hn2 & Hn3)].
    + apply lgw_nonph_runs. exact Hnp.
    + apply lgw_need_head; [exact Hnp|exact Hn1|exact Hn3|exact Hn2].
  - cbn [plan_okP] in HP.
    destruct HP as (H1 & H2 & H3 & H4 & H5 & H6).
    cbn [lapply].
    destruct (split_body (firstn l (skipn (s - i) w)))
      as [bf bb] eqn:ESB.
    cbv beta iota zeta.
    destruct (lapply pl' (skipn ((s - i) + l) w) (s + l) (kx + 1))
      as [cw2 sg2] eqn:EL.
    cbv beta iota zeta. cbn [fst].
    cbn [lkept] in Hnp.
    assert (HnpPre : forall g, In g (firstn (s - i) w) ->
                      ph sg g = false)
      by (intros g Hg; apply Hnp, in_or_app; left; exact Hg).
    assert (HnpTail : forall g,
               In g (lkept pl' (skipn ((s - i) + l) w) (s + l)%nat) ->
               ph sg g = false)
      by (intros g Hg; apply Hnp, in_or_app; right; exact Hg).
    assert (Hsw : ((s - i) + l + GUARD <= length w)%nat)
      by (rewrite length_skipn in H5; unfold GUARD in *; lia).
    assert (Hlen : length (firstn (s - i) w) = (s - i)%nat)
      by (rewrite length_firstn; lia).
    rewrite lgw_app.
    assert (Hpre : exists y0,
               lgw sg (firstn (s - i) w) x need = Some (y0, O)).
    { destruct Hneed as [->|(Hn1 & Hn2 & Hn3)].
      - apply lgw_nonph_runs. exact HnpPre.
      - apply lgw_need_head.
        + exact HnpPre.
        + exact Hn1.
        + rewrite Hlen. exact H2.
        + rewrite firstn_firstn.
          replace (Init.Nat.min GUARD (s - i))
            with GUARD by lia.
          exact Hn2. }
    destruct Hpre as (y0 & Hy0).
    assert (Hy0G : (GUARD <= y0)%nat).
    { eapply lgw_end_before with (a := firstn (s - i) w).
      - exact HnpPre.
      - rewrite Hlen. exact H3.
      - rewrite Hlen. exact H2.
      - exact Hy0. }
    rewrite Hy0. cbv beta iota.
    cbn [lgw].
    destruct (ph sg (phg kx)) eqn:EPH.
    + change (Nat.ltb O O) with false.
      replace (Nat.ltb y0 GUARD) with false
        by (symmetry; apply PeanoNat.Nat.ltb_ge; exact Hy0G).
      cbv beta iota.
      pose proof (IH sg (skipn ((s - i) + l) w) (s + l)%nat (kx+1)%N O
                     GUARD H6 HnpTail
                     (or_intror (conj (le_n GUARD) (conj H4 H5))))
        as HI.
      rewrite EL in HI. cbn [fst] in HI. exact HI.
    + change (Nat.ltb O O) with false.
      rewrite casc_phg.
      cbv beta iota.
      pose proof (IH sg (skipn ((s - i) + l) w) (s + l)%nat (kx+1)%N
                     O O H6 HnpTail (or_introl eq_refl)) as HI.
      rewrite EL in HI. cbn [fst] in HI. exact HI.
Qed.
Theorem T_cond_guard :
  forall w h cw sg h0,
    lin_cond w h = Some (cw, sg, h0) ->
    lin_guard sg cw = true.
Proof.
  intros w h cw sg h0 H.
  unfold lin_cond in H.
  destruct (lplan (length w) w O) as [|p pl0] eqn:EP;
    [discriminate|].
  destruct (lin_condk KMAGIC w h)
    as [[[cw1 sg1] h1]|] eqn:EC; [|discriminate].
  destruct (lin_ok sg1 cw1) eqn:EOk; [|discriminate].
  destruct (lin_tags sg1 cw1) eqn:ETags; [|discriminate].
  inversion H; subst cw1 sg1 h1.
  unfold lin_condk in EC.
  rewrite EP in EC.
  destruct (lapply (p :: pl0) w O KMAGIC)
    as [cw' sg'] eqn:ELap.
  cbv beta iota zeta in EC.
  destruct (forallb (fun s => segcache s && segok s) sg');
    [|discriminate].
  destruct (forallb segshape sg'); [|discriminate].
  destruct (forallb segpos sg'); [|discriminate].
  inversion EC; subst cw' sg'.
  pose proof (lplan_plan_okP (length w) w O) as HP.
  rewrite EP in HP.
  pose proof (lin_ok_kept_nonph (p :: pl0) w O KMAGIC cw sg
                KMAGIC_2 ELap EOk) as Hnp.
  destruct (lapply_lgw (p :: pl0) sg w O KMAGIC O O HP Hnp
              (or_introl eq_refl)) as (y & Hy).
  rewrite ELap in Hy. cbn [fst] in Hy.
  unfold lin_guard.
  rewrite lguard_lgw, Hy.
  reflexivity.
Qed.
Lemma nth_skipn : forall (n m : nat) (l : word),
  nth_error (skipn n l) m = nth_error l (n + m).
Proof.
  induction n as [|n IH]; intros m l; [reflexivity|].
  destruct l as [|g l].
  - cbn [skipn]. destruct m; reflexivity.
  - cbn [skipn].
    replace (S n + m)%nat with (S (n + m)) by lia.
    cbn [nth_error]. apply IH.
Qed.
Lemma keyi_in : forall sg g s,
  keyi sg g = Some s ->
  In s sg /\ phshape g = true /\ gC g = sKey s.
Proof.
  intros sg g s. unfold keyi.
  destruct (phshape g) eqn:El; [|discriminate].
  induction sg as [|s0 sg IH]; intros H.
  - discriminate.
  - cbn in H.
    destruct (gC g =? sKey s0) eqn:Ek.
    + injection H as ->.
      split; [left; reflexivity|].
      split; [reflexivity|].
      apply N.eqb_eq. exact Ek.
    + destruct (IH H) as (Hin & _ & Hk).
      split; [right; exact Hin|].
      split; [reflexivity|exact Hk].
Qed.
Lemma countkey_pos_le : forall k w i j gi gj,
  nth_error w i = Some gi -> phshape gi = true -> gC gi = k ->
  nth_error w j = Some gj -> phshape gj = true -> gC gj = k ->
  i <> j ->
  (2 <= countkey k w)%nat.
Proof.
  intros k w. induction w as [|g t IH]; intros i j gi gj Hi Hli Hki Hj Hlj Hkj Hne.
  - destruct i; discriminate.
  - destruct i as [|i']; destruct j as [|j'].
    + congruence.
    + cbn [nth_error] in Hi. injection Hi as <-.
      cbn [countkey].
      rewrite Hli, Hki, N.eqb_refl. cbn [andb].
      cbn [nth_error] in Hj.
      assert (Hin : (countkey k t <> O)%nat).
      { rewrite <- Hkj. apply (countkey_in gj); [|exact Hlj].
        eapply nth_error_In. exact Hj. }
      lia.
    + cbn [nth_error] in Hj. injection Hj as <-.
      cbn [countkey].
      rewrite Hlj, Hkj, N.eqb_refl. cbn [andb].
      cbn [nth_error] in Hi.
      assert (Hin : (countkey k t <> O)%nat).
      { rewrite <- Hki. apply (countkey_in gi); [|exact Hli].
        eapply nth_error_In. exact Hi. }
      lia.
    + cbn [nth_error] in Hi, Hj.
      cbn [countkey].
      assert (H2 : (2 <= countkey k t)%nat)
        by (eapply IH;
            [exact Hi|exact Hli|exact Hki|exact Hj|exact Hlj|exact Hkj|lia]).
      lia.
Qed.
Lemma countkey_unique_pos : forall k w i j gi gj,
  countkey k w = 1%nat ->
  nth_error w i = Some gi -> phshape gi = true -> gC gi = k ->
  nth_error w j = Some gj -> phshape gj = true -> gC gj = k ->
  i = j.
Proof.
  intros k w i j gi gj H1 Hi Hli Hki Hj Hlj Hkj.
  destruct (PeanoNat.Nat.eq_dec i j) as [E|NE]; [exact E|].
  pose proof (countkey_pos_le k w i j gi gj Hi Hli Hki Hj Hlj Hkj NE).
  lia.
Qed.
Definition ph_margins (sg : list seg) (w : word) : Prop :=
  forall j g,
    nth_error w j = Some g -> ph sg g = true ->
    (GUARD <= j)%nat /\
    (j + GUARD < length w)%nat /\
    (forall j', (j - GUARD <= j')%nat ->
                (j' <= j + GUARD)%nat -> j' <> j ->
     exists g', nth_error w j' = Some g' /\
                casc g' = true /\ ph sg g' = false).
Lemma clean_window_scan_spec : forall fu all w' i ph_i,
  clean_window_scan fu all w' i ph_i = true ->
  forall off, (off < fu)%nat -> (i + off)%nat <> ph_i ->
    exists g', nth_error w' off = Some g' /\
               casc g' = true /\ ph all g' = false.
Proof.
  induction fu as [|fu IH]; intros all w' i ph_i H off Hoff Hne; [lia|].
  destruct w' as [|g t]; [discriminate|].
  cbn [clean_window_scan] in H.
  apply andb_prop in H. destruct H as [Hh Ht].
  destruct off as [|off'].
  - rewrite PeanoNat.Nat.add_0_r in Hne.
    destruct (Nat.eqb i ph_i) eqn:Ei.
    + apply PeanoNat.Nat.eqb_eq in Ei. congruence.
    + apply andb_prop in Hh. destruct Hh as [Hc Hp].
      exists g. split; [reflexivity|]. split; [exact Hc|].
      destruct (ph all g); [discriminate|reflexivity].
  - cbn [nth_error].
    eapply IH; [exact Ht|lia|].
    replace (S i + off')%nat with (i + S off')%nat by lia.
    exact Hne.
Qed.
Lemma clean_window_spec : forall fu all w i0 ph_i,
  clean_window fu all w i0 ph_i = true ->
  forall off, (off < fu)%nat -> (i0 + off)%nat <> ph_i ->
    exists g', nth_error w (i0 + off)%nat = Some g' /\
               casc g' = true /\ ph all g' = false.
Proof.
  intros fu all w i0 ph_i H off Hoff Hne.
  unfold clean_window in H.
  destruct (clean_window_scan_spec fu all (skipn i0 w) i0 ph_i H off
              Hoff Hne) as (g' & Hg & Hc & Hp).
  exists g'. split; [|split; assumption].
  rewrite <- (nth_skipn i0 off w). exact Hg.
Qed.
Definition at_entry (all : list seg) (w : word)
                    (s : seg) : Prop :=
  exists i g,
    nth_error w i = Some g /\
    is_key (sKey s) g = true /\
    (GUARD <= i)%nat /\
    (forall off, (off < S (2 * GUARD))%nat ->
       ((i - GUARD) + off)%nat <> i ->
       exists g', nth_error w ((i - GUARD) + off)%nat = Some g' /\
                  casc g' = true /\ ph all g' = false).
Lemma guard_at_slow_spec : forall all sg ps w,
  guard_at_slow all sg ps w = true ->
  forall s, In s sg -> at_entry all w s.
Proof.
  intros all sg. induction sg as [|s0 sg IH]; intros ps w H s Hin;
    [contradiction|].
  destruct ps as [|i ps']; [discriminate|].
  cbn [guard_at_slow] in H.
  destruct (wat w i) as [g|] eqn:EW; [|discriminate].
  apply andb_prop in H. destruct H as [H H4].
  apply andb_prop in H. destruct H as [H H3].
  apply andb_prop in H. destruct H as [H1 H2].
  destruct Hin as [<-|Hin].
  - exists i, g.
    split; [exact EW|].
    split; [exact H2|].
    split; [apply PeanoNat.Nat.leb_le; exact H1|].
    intros off Hoff Hne.
    exact (clean_window_spec _ all w (i - GUARD) i H3 off Hoff Hne).
  - exact (IH ps' w H4 s Hin).
Qed.
Lemma guard_at_ordered_spec : forall all sg ps base w,
  guard_at_ordered all sg ps (skipn base w) base = true ->
  forall s, In s sg -> at_entry all w s.
Proof.
  intros all sg. induction sg as [|s0 sg IH]; intros ps base w H s Hin;
    [contradiction|].
  destruct ps as [|p ps']; [discriminate|].
  cbn [guard_at_ordered] in H.
  cbv zeta in H.
  destruct (Nat.leb base (p - GUARD)) eqn:EB; [|discriminate].
  apply PeanoNat.Nat.leb_le in EB.
  rewrite skipn_skipn in H.
  replace (base + (p - GUARD - base))%nat
    with (p - GUARD)%nat in H by lia.
  destruct (nth_error (skipn (p - GUARD) w)
              (p - (p - GUARD))) as [g|] eqn:EN; [|discriminate].
  apply andb_prop in H. destruct H as [H H4].
  apply andb_prop in H. destruct H as [H H3].
  apply andb_prop in H. destruct H as [H1 H2].
  apply PeanoNat.Nat.leb_le in H1.
  destruct Hin as [<-|Hin].
  - exists p, g.
    rewrite nth_skipn in EN.
    replace ((p - GUARD) + (p - (p - GUARD)))%nat
      with p in EN by lia.
    split; [exact EN|].
    split; [exact H2|].
    split; [exact H1|].
    intros off Hoff Hne.
    destruct (clean_window_scan_spec _ all _ (p - GUARD) p H3 off
                Hoff Hne) as (g' & Hg' & Hc & Hp).
    rewrite nth_skipn in Hg'.
    exists g'. auto.
  - exact (IH ps' (p - GUARD)%nat w H4 s Hin).
Qed.
Lemma at_entries_margins : forall sg w,
  lin_ok sg w = true ->
  (forall s, In s sg -> at_entry sg w s) ->
  ph_margins sg w.
Proof.
  intros sg w HOk HA j g Hj Hph.
  unfold ph in Hph.
  destruct (keyi sg g) as [s|] eqn:EK; [|discriminate].
  destruct (keyi_in sg g s EK) as (Hin & Hlv & Hkey).
  destruct (HA s Hin) as (i & gi & Hi & Hik & HiG & Hwin).
  unfold is_key in Hik. apply andb_prop in Hik.
  destruct Hik as [Hilv Hieq]. apply N.eqb_eq in Hieq.
  assert (H1 : countkey (sKey s) w = 1%nat).
  { unfold lin_ok in HOk.
    eapply forallb_forall in HOk; [|exact Hin].
    apply PeanoNat.Nat.eqb_eq in HOk. exact HOk. }
  assert (Ej : j = i)
    by (exact (countkey_unique_pos (sKey s) w j i g gi H1
                 Hj Hlv Hkey Hi Hilv Hieq)).
  subst j.
  split; [exact HiG|].
  split.
  - destruct (Hwin (2 * GUARD)%nat) as (g' & Hg' & _ & _);
      [lia|unfold GUARD in *; lia|].
    replace ((i - GUARD) + 2 * GUARD)%nat
      with (i + GUARD)%nat in Hg' by lia.
    apply nth_error_Some. rewrite Hg'. discriminate.
  - intros j' Hj1 Hj2 Hne.
    destruct (Hwin (j' - (i - GUARD))%nat) as (g' & Hg' & Hc & Hp);
      [lia|lia|].
    replace ((i - GUARD) + (j' - (i - GUARD)))%nat
      with j' in Hg' by lia.
    exists g'. auto.
Qed.
Lemma lin_guard_at_margins : forall sg ps w,
  lin_ok sg w = true ->
  lin_guard_at sg ps w = true ->
  ph_margins sg w.
Proof.
  intros sg ps w HOk H.
  unfold lin_guard_at in H.
  destruct (guard_at_ordered sg sg ps w O) eqn:EO.
  - eapply at_entries_margins; [exact HOk|].
    intros s Hin.
    eapply guard_at_ordered_spec with (base := O) (ps := ps); [|exact Hin].
    cbn [skipn]. exact EO.
  - eapply at_entries_margins; [exact HOk|].
    intros s Hin.
    eapply guard_at_slow_spec; [exact H|exact Hin].
Qed.
Lemma lgw_of_margins : forall sg w rest j before need,
  ph_margins sg w ->
  rest = skipn j w ->
  (need <= GUARD)%nat ->
  ((0 < need)%nat ->
     exists p gp, nth_error w p = Some gp /\ ph sg gp = true /\
       (p < j)%nat /\ (j + need)%nat = (p + GUARD + 1)%nat) ->
  (forall q gq, nth_error w q = Some gq -> ph sg gq = true ->
     (j <= q)%nat -> (GUARD <= before + (q - j))%nat) ->
  exists y, lgw sg rest before need = Some (y, O).
Proof.
  intros sg w rest. revert w.
  induction rest as [|g t IH]; intros w j before need HM Hrest Hn HA HB.
  - destruct need as [|n'].
    + exists before. reflexivity.
    + exfalso.
      destruct (HA (PeanoNat.Nat.lt_0_succ n'))
        as (p & gp & Hp & Hphp & Hpj & Heq).
      destruct (HM p gp Hp Hphp) as (_ & Hbound & _).
      assert (Hlw : (length w <= j)%nat).
      { pose proof (length_skipn j w) as L.
        rewrite <- Hrest in L. cbn [length] in L. lia. }
      lia.
  - assert (Hg : nth_error w j = Some g).
    { pose proof (nth_skipn j O w) as L.
      rewrite <- Hrest in L. cbn [nth_error] in L.
      rewrite PeanoNat.Nat.add_0_r in L. exact (eq_sym L). }
    assert (Ht : t = skipn (S j) w).
    { rewrite <- PeanoNat.Nat.add_1_r, <- skipn_skipn, <- Hrest.
      reflexivity. }
    cbn [lgw].
    destruct (ph sg g) eqn:EP.
    + destruct (HM j g Hg EP) as (HjG & HjB & Hwin).
      destruct need as [|n'].
      * change (Nat.ltb O O) with false.
        replace (Nat.ltb before GUARD) with false
          by (symmetry; apply PeanoNat.Nat.ltb_ge;
              pose proof (HB j g Hg EP (le_n j)) as HBj; lia).
        cbv beta iota.
        eapply IH with (j := S j).
        -- exact HM.
        -- exact Ht.
        -- lia.
        -- intros _. exists j, g.
           split; [exact Hg|]. split; [exact EP|].
           split; [lia|]. lia.
        -- intros q gq Hq Hphq Hle.
           destruct (PeanoNat.Nat.le_gt_cases q (j + GUARD))
             as [Hqle|Hqgt].
           ++ exfalso.
              destruct (Hwin q) as (g' & Hg' & _ & Hp'); [lia|lia|lia|].
              rewrite Hq in Hg'. injection Hg' as <-. congruence.
           ++ lia.
      * exfalso.
        destruct (HA (PeanoNat.Nat.lt_0_succ n'))
          as (p & gp & Hp & Hphp & Hpj & Heq).
        destruct (HM p gp Hp Hphp) as (_ & _ & Hwinp).
        destruct (Hwinp j) as (g' & Hg' & _ & Hp'); [lia|lia|lia|].
        rewrite Hg in Hg'. injection Hg' as <-. congruence.
    + destruct need as [|n'].
      * change (Nat.ltb O O) with false.
        cbv beta iota.
        destruct (casc g) eqn:EC; cbv beta iota.
        -- eapply IH with (j := S j).
           ++ exact HM.
           ++ exact Ht.
           ++ lia.
           ++ intros F. exfalso. lia.
           ++ intros q gq Hq Hphq Hle.
              assert (Hjq : (j <= q)%nat) by lia.
              pose proof (HB q gq Hq Hphq Hjq). lia.
        -- eapply IH with (j := S j).
           ++ exact HM.
           ++ exact Ht.
           ++ lia.
           ++ intros F. exfalso. lia.
           ++ intros q gq Hq Hphq Hle.
              destruct (HM q gq Hq Hphq) as (HqG & HqB & Hwinq).
              destruct (PeanoNat.Nat.le_gt_cases q (j + GUARD))
                as [Hqle|Hqgt].
              ** exfalso.
                 destruct (Hwinq j) as (g' & Hg' & Hc' & _); [lia|lia|lia|].
                 rewrite Hg in Hg'. injection Hg' as <-. congruence.
              ** lia.
      * destruct (HA (PeanoNat.Nat.lt_0_succ n'))
          as (p & gp & Hp & Hphp & Hpj & Heq).
        destruct (HM p gp Hp Hphp) as (_ & _ & Hwinp).
        destruct (Hwinp j) as (g' & Hg' & Hc' & _); [lia|lia|lia|].
        rewrite Hg in Hg'. injection Hg' as <-.
        change (Nat.ltb O (S n')) with true.
        cbv beta iota.
        rewrite Hc'. cbn [orb negb].
        eapply IH with (j := S j).
        -- exact HM.
        -- exact Ht.
        -- lia.
        -- intros Hpos. exists p, gp.
           split; [exact Hp|]. split; [exact Hphp|].
           split; [lia|]. lia.
        -- intros q gq Hq Hphq Hle.
           assert (Hjq : (j <= q)%nat) by lia.
           pose proof (HB q gq Hq Hphq Hjq). lia.
Qed.
Lemma lguard_of_margins : forall sg w,
  ph_margins sg w -> lin_guard sg w = true.
Proof.
  intros sg w HM.
  unfold lin_guard.
  rewrite lguard_lgw.
  assert (HW : exists y, lgw sg w O O = Some (y, O)).
  { apply (lgw_of_margins sg w w O O O HM).
    - reflexivity.
    - lia.
    - intros F. exfalso. lia.
    - intros q gq Hq Hphq _.
      destruct (HM q gq Hq Hphq) as (HqG & _ & _). lia. }
  destruct HW as (y & Hy).
  rewrite Hy. reflexivity.
Qed.
Theorem lin_guard_at_sound : forall sg ps w,
  lin_ok sg w = true ->
  lin_guard_at sg ps w = true ->
  lin_guard sg w = true.
Proof.
  intros sg ps w HOk H.
  apply lguard_of_margins.
  exact (lin_guard_at_margins sg ps w HOk H).
Qed.
Lemma lin_split_at_spec : forall n (w : word),
  lin_split_at n w = (firstn n w, skipn n w).
Proof.
  induction n as [|n IH]; intros w.
  - reflexivity.
  - destruct w as [|g w']; [reflexivity|].
    cbn [lin_split_at firstn skipn].
    rewrite IH. reflexivity.
Qed.
Lemma find_key_scan_spec : forall fu w' i k j,
  find_key_scan fu w' i k = Some j ->
  (i <= j)%nat /\
  exists g, nth_error w' (j - i)%nat = Some g /\ is_key k g = true.
Proof.
  induction fu as [|fu IH]; intros w' i k j H; [discriminate|].
  destruct w' as [|g t]; [discriminate|].
  cbn [find_key_scan] in H.
  destruct (is_key k g) eqn:EK.
  - injection H as <-. split; [lia|].
    exists g. rewrite PeanoNat.Nat.sub_diag. cbn [nth_error]. auto.
  - destruct (IH t (S i) k j H) as (Hle & g' & Hg' & Hk').
    split; [lia|].
    exists g'. split; [|exact Hk'].
    replace (j - i)%nat with (S (j - S i))%nat by lia.
    cbn [nth_error]. exact Hg'.
Qed.
Lemma locate_key_spec : forall w k i,
  locate_key w k = Some i ->
  exists g, nth_error w i = Some g /\ is_key k g = true.
Proof.
  intros w k i H.
  unfold locate_key, find_key_from in H.
  destruct (find_key_scan_spec _ _ _ _ _ H) as (Hle & g & Hg & Hk).
  cbn [skipn] in Hg. rewrite PeanoNat.Nat.sub_0_r in Hg.
  eauto.
Qed.
Lemma cleanrun_spec : forall k sg w' m,
  (m < cleanrun sg w' k)%nat ->
  exists g, nth_error w' m = Some g /\
            casc g = true /\ ph sg g = false.
Proof.
  induction k as [|k IH]; intros sg w' m H;
    [destruct w'; cbn in H; lia|].
  destruct w' as [|g t]; [cbn in H; lia|].
  cbn [cleanrun] in H.
  destruct (ph sg g || negb (casc g)) eqn:EC; cbn in H;
    [lia|].
  apply orb_false_elim in EC. destruct EC as [EP EN].
  destruct m as [|m'].
  - exists g. cbn [nth_error]. split; [reflexivity|].
    split; [|exact EP].
    destruct (casc g); [reflexivity|discriminate EN].
  - cbn [nth_error]. apply IH. lia.
Qed.
Lemma lin_flat_nonph : forall sg a,
  (forall g, In g a -> ph sg g = false) ->
  lin_flat sg a = a.
Proof.
  intros sg a. induction a as [|g t IH]; intros Hnp; [reflexivity|].
  rewrite lin_flat_cons.
  assert (EK : keyb sg g = None).
  { unfold keyb.
    pose proof (Hnp g (or_introl eq_refl)) as HP.
    unfold ph in HP.
    destruct (keyi sg g); [discriminate|reflexivity]. }
  rewrite EK.
  f_equal. apply IH. intros g' H'. exact (Hnp g' (or_intror H')).
Qed.
Lemma keyi_cons : forall x t g,
  keyi (x :: t) g
  = if phshape g
    then (if gC g =? sKey x
          then Some x else keyi t g)
    else None.
Proof.
  intros x t g. unfold keyi.
  destruct (phshape g); reflexivity.
Qed.
Lemma sgset_keyi : forall sg k s2 g,
  sKey s2 = k ->
  keyi (sgset sg k s2) g
  = match keyi sg g with
    | Some s => if sKey s =? k then Some s2 else Some s
    | None => None
    end.
Proof.
  intros sg k s2 g Hk.
  induction sg as [|x t IH].
  - unfold keyi. cbn [sgset].
    destruct (phshape g); reflexivity.
  - cbn [sgset].
    destruct (sKey x =? k) eqn:Ex.
    + rewrite !keyi_cons.
      destruct (phshape g) eqn:El; [|reflexivity].
      assert (ExE : sKey x = k) by (apply N.eqb_eq; exact Ex).
      rewrite Hk, <- ExE.
      destruct (gC g =? sKey x) eqn:Eg.
      * cbv beta iota. rewrite N.eqb_refl. reflexivity.
      * destruct (keyi t g) as [s|] eqn:Et; [|reflexivity].
        cbv beta iota.
        destruct (keyi_in t g s Et) as (_ & _ & Hgc).
        replace (sKey s =? sKey x) with false;
          [reflexivity|].
        symmetry. apply N.eqb_neq.
        rewrite <- Hgc.
        apply N.eqb_neq. exact Eg.
    + rewrite !keyi_cons.
      rewrite IH.
      destruct (phshape g) eqn:El; [|reflexivity].
      destruct (gC g =? sKey x) eqn:Eg; [|reflexivity].
      cbv beta iota. rewrite Ex. reflexivity.
Qed.
Lemma sgset_keys : forall sg k s2,
  sKey s2 = k ->
  List.map sKey (sgset sg k s2) = List.map sKey sg.
Proof.
  intros sg k s2 Hk. induction sg as [|x t IH]; [reflexivity|].
  cbn [sgset].
  destruct (sKey x =? k) eqn:Ex.
  - apply N.eqb_eq in Ex. cbn [List.map]. rewrite Hk, Ex. reflexivity.
  - cbn [List.map]. rewrite IH. reflexivity.
Qed.
Lemma lin_ok_of_keys : forall sg1 sg2 w,
  List.map sKey sg1 = List.map sKey sg2 ->
  lin_ok sg1 w = lin_ok sg2 w.
Proof.
  intros sg1. induction sg1 as [|x t IH]; intros sg2 w H.
  - destruct sg2; [reflexivity|discriminate].
  - destruct sg2 as [|y t2]; [discriminate|].
    cbn [List.map] in H. injection H as Hxy Ht.
    unfold lin_ok. cbn [forallb].
    rewrite Hxy.
    f_equal.
    exact (IH t2 w Ht).
Qed.
Lemma keyi_some_of_in : forall sg s g,
  In s sg -> phshape g = true -> gC g = sKey s ->
  ph sg g = true.
Proof.
  intros sg s g Hin Hlv Hgc.
  unfold ph.
  destruct (keyi sg g) eqn:EK; [reflexivity|].
  exfalso.
  revert Hin EK.
  induction sg as [|x t IH]; intros Hin EK; [contradiction|].
  rewrite keyi_cons, Hlv in EK.
  destruct (gC g =? sKey x) eqn:Ex; [discriminate|].
  destruct Hin as [<-|Hin].
  - apply N.eqb_neq in Ex. congruence.
  - exact (IH Hin EK).
Qed.
Lemma countkey_nonph_zero : forall sg a s,
  (forall g, In g a -> ph sg g = false) ->
  In s sg ->
  countkey (sKey s) a = O.
Proof.
  intros sg a s Hnp Hin.
  induction a as [|g t IH].
  - reflexivity.
  - cbn [countkey].
    destruct (phshape g) eqn:El.
    + destruct (gC g =? sKey s) eqn:Eg.
      * exfalso.
        apply N.eqb_eq in Eg.
        pose proof (keyi_some_of_in sg s g Hin El Eg) as HP.
        rewrite (Hnp g (or_introl eq_refl)) in HP. discriminate.
      * cbn [andb]. apply IH.
        intros g' H'. exact (Hnp g' (or_intror H')).
    + cbn [andb]. apply IH.
      intros g' H'. exact (Hnp g' (or_intror H')).
Qed.
Lemma adjk_repack_store : forall p g,
  adjk p (repack_store p g) = g.
Proof.
  intros p g. destruct g as [[o z] c].
  cbn [repack_store].
  destruct (is_lvl (o, z, c)) eqn:El;
    unfold is_lvl in El; cbn [gO gZ] in El;
    cbn [adjk]; rewrite El.
  - rewrite N.add_sub. reflexivity.
  - reflexivity.
Qed.
Lemma nth_firstn : forall n m (l : word),
  (m < n)%nat -> nth_error (firstn n l) m = nth_error l m.
Proof.
  induction n as [|n IH]; intros m l H; [lia|].
  destruct l as [|g t]; [destruct m; reflexivity|].
  destruct m as [|m']; [reflexivity|].
  cbn [firstn nth_error]. apply IH. lia.
Qed.
Lemma cleanrun_prefix_clean : forall sg u cap n g',
  (n <= cleanrun sg u cap)%nat ->
  In g' (firstn n u) ->
  casc g' = true /\ ph sg g' = false.
Proof.
  intros sg u cap n g' Hn Hin.
  destruct (In_nth_error _ _ Hin) as (m & Hm).
  assert (Hmn : (m < n)%nat).
  { assert (HmL : (m < length (firstn n u))%nat).
    { apply nth_error_Some. rewrite Hm. discriminate. }
    rewrite length_firstn in HmL. lia. }
  rewrite nth_firstn in Hm by exact Hmn.
  destruct (cleanrun_spec cap sg u m) as (g'' & Hg'' & Hc & Hp); [lia|].
  rewrite Hm in Hg''. injection Hg'' as <-.
  auto.
Qed.
Lemma lin_flat_sgset : forall sg k s2 a,
  sKey s2 = k ->
  countkey k a = O ->
  lin_flat (sgset sg k s2) a = lin_flat sg a.
Proof.
  intros sg k s2 a Hk. induction a as [|g t IH]; intros Hc; [reflexivity|].
  cbn [countkey] in Hc.
  rewrite !lin_flat_cons.
  assert (EKB : keyb (sgset sg k s2) g = keyb sg g).
  { unfold keyb.
    rewrite (sgset_keyi sg k s2 g Hk).
    destruct (keyi sg g) as [s|] eqn:EKI; [|reflexivity].
    destruct (keyi_in sg g s EKI) as (_ & Hlv & Hgc).
    destruct (sKey s =? k) eqn:Es; [|reflexivity].
    exfalso.
    apply N.eqb_eq in Es.
    rewrite Hlv, Hgc, Es, N.eqb_refl in Hc.
    cbn [andb] in Hc. lia. }
  rewrite EKB.
  destruct (keyb sg g) as [b|].
  - f_equal. apply IH.
    destruct (phshape g && (gC g =? k)); lia.
  - f_equal. apply IH.
    destruct (phshape g && (gC g =? k)); lia.
Qed.
Lemma lin_ok_ext : forall sg w1 w2,
  (forall s, In s sg ->
     countkey (sKey s) w1
     = countkey (sKey s) w2) ->
  lin_ok sg w1 = lin_ok sg w2.
Proof.
  intros sg w1 w2 H. unfold lin_ok.
  induction sg as [|x t IH]; [reflexivity|].
  cbn [forallb].
  rewrite (H x (or_introl eq_refl)).
  f_equal. apply IH. intros s Hs. exact (H s (or_intror Hs)).
Qed.
Lemma keys_big_map_eq : forall sg1 sg2,
  List.map sKey sg1 = List.map sKey sg2 ->
  keys_big sg2 -> keys_big sg1.
Proof.
  intros sg1 sg2 HM HK s Hs.
  assert (Hin : In (sKey s) (List.map sKey sg1))
    by (apply in_map; exact Hs).
  rewrite HM in Hin.
  apply in_map_iff in Hin. destruct Hin as (s' & Heq & Hin').
  rewrite <- Heq. exact (HK s' Hin').
Qed.
Lemma map_adjk_repack : forall p l,
  List.map (adjk p) (List.map (repack_store p) l) = l.
Proof.
  intros p l. rewrite List.map_map.
  erewrite List.map_ext; [apply List.map_id|].
  intros g. apply adjk_repack_store.
Qed.
Lemma repack_one_ok : forall sg w key sg' w',
  lin_ok sg w = true ->
  keys_big sg ->
  repack_one sg w key = Some (sg', w') ->
  lin_flat sg' w' = lin_flat sg w /\
  lin_ok sg' w' = true /\ keys_big sg'.
Proof.
  intros sg w key sg' w' HOk HKb H.
  unfold repack_one in H.
  destruct (locate_key w key) as [i|] eqn:EL; [|discriminate].
  destruct (locate_key_spec w key i EL) as (gi & Hgi & Hik).
  rewrite lin_split_at_spec in H.
  cbv beta iota in H.
  destruct (skipn i w) as [|g post] eqn:ES; [discriminate|].
  destruct (keyi sg g) as [s|] eqn:EKI; [|discriminate].
  cbv zeta in H.
  match type of H with
  | (if ?gate then _ else _) = _ => destruct gate eqn:EG
  end; [|discriminate].
  apply andb_prop in EG. destruct EG as [EGf EGb].
  match type of H with
  | (if ?gate then _ else _) = _ => destruct gate eqn:EGE
  end; [|discriminate].
  injection H as Hsg Hw.
  set (pre := firstn i w) in *.
  set (nb := cleanrun sg (rev pre) i) in *.
  set (na := cleanrun sg post (length post)) in *.
  set (lb := (2 * Nat.div2 (nb - MARG))%nat) in *.
  set (la := (2 * Nat.div2 (na - MARG))%nat) in *.
  set (fr := rev (firstn lb (rev pre))) in *.
  set (bk := firstn la post) in *.
  set (frs := List.map (repack_store (sPend s)) fr) in *.
  set (bks := List.map (repack_store (sPend s)) bk) in *.
  subst sg' w'.
  replace (Nat.div2 (nb - MARG)
           + (Nat.div2 (nb - MARG) + 0))%nat
    with lb in * by (unfold lb; lia).
  replace (Nat.div2 (na - MARG)
           + (Nat.div2 (na - MARG) + 0))%nat
    with la in * by (unfold la; lia).
  match goal with
  | |- context [sgset sg key ?t] => set (s2 := t) in *
  end.
  assert (Hgw : nth_error w i = Some g).
  { rewrite <- (PeanoNat.Nat.add_0_r i), <- nth_skipn, ES. reflexivity. }
  assert (Egi : gi = g) by congruence.
  subst gi.
  unfold is_key in Hik. apply andb_prop in Hik.
  destruct Hik as [Hglv Hgck]. apply N.eqb_eq in Hgck.
  destruct (keyi_in sg g s EKI) as (Hins & _ & Hgcs).
  assert (Hks : sKey s = key) by congruence.
  assert (Hk2 : sKey s2 = key)
    by (unfold s2; cbn [sKey]; exact Hks).
  assert (Hiw : (i < length w)%nat).
  { apply nth_error_Some. rewrite Hgw. discriminate. }
  assert (HW : w = pre ++ g :: post).
  { unfold pre. rewrite <- ES. symmetry. apply firstn_skipn. }
  assert (Hpre : length pre = i).
  { unfold pre. rewrite length_firstn. lia. }
  assert (HC1 : countkey key w = 1%nat).
  { unfold lin_ok in HOk.
    pose proof HOk as HOk'.
    eapply forallb_forall in HOk'; [|exact Hins].
    apply PeanoNat.Nat.eqb_eq in HOk'. rewrite Hks in HOk'. exact HOk'. }
  assert (Hlbnb : (lb <= nb)%nat).
  { unfold lb. pose proof (PeanoNat.Nat.div2_odd (nb - MARG)). lia. }
  assert (Hlana : (la <= na)%nat).
  { unfold la. pose proof (PeanoNat.Nat.div2_odd (na - MARG)). lia. }
  assert (Hfr : forall g0, In g0 fr ->
            casc g0 = true /\ ph sg g0 = false).
  { intros g0 Hg0. unfold fr in Hg0.
    rewrite <- in_rev in Hg0.
    exact (cleanrun_prefix_clean sg (rev pre) i lb g0 Hlbnb Hg0). }
  assert (Hbk : forall g0, In g0 bk ->
            casc g0 = true /\ ph sg g0 = false).
  { intros g0 Hg0. unfold bk in Hg0.
    exact (cleanrun_prefix_clean sg post (length post) la g0 Hlana Hg0). }
  set (pc := firstn (i - lb)%nat pre) in *.
  set (pt := skipn la post) in *.
  assert (Hpref : pre = pc ++ fr).
  { unfold pc, fr.
    rewrite firstn_rev, rev_involutive, Hpre.
    symmetry. apply firstn_skipn. }
  assert (Hpost : post = bk ++ pt).
  { unfold bk, pt. symmetry. apply firstn_skipn. }
  assert (HCsplit : countkey key pre = O /\
                    countkey key post = O).
  { pose proof HC1 as HC1'.
    rewrite HW, countkey_app in HC1'. cbn [countkey] in HC1'.
    rewrite Hglv, Hgck, N.eqb_refl in HC1'. cbn [andb] in HC1'.
    split; lia. }
  destruct HCsplit as [HCpre HCpost].
  assert (HCpc : countkey key pc = O).
  { pose proof HCpre as X. rewrite Hpref, countkey_app in X. lia. }
  assert (HCpt : countkey key pt = O).
  { pose proof HCpost as X. rewrite Hpost, countkey_app in X. lia. }
  assert (EKB2 : keyb (sgset sg key s2) g
                 = Some (sFlat s2)).
  { unfold keyb.
    rewrite (sgset_keyi sg key s2 g Hk2), EKI, Hks, N.eqb_refl.
    reflexivity. }
  assert (EKB : keyb sg g = Some (sFlat s))
    by (unfold keyb; rewrite EKI; reflexivity).
  assert (HsF : sFlat s2 = fr ++ sFlat s ++ bk).
  { unfold s2. unfold sFlat, sBody.
    cbn [sPend sFront sBack].
    rewrite rev_app_distr, rev_involutive.
    unfold matb. rewrite !map_app.
    unfold frs, bks.
    rewrite !map_adjk_repack.
    rewrite <- !app_assoc. reflexivity. }
  split.
  -
    assert (RHSeq : lin_flat sg w
      = lin_flat sg pc ++ fr ++ sFlat s ++ bk
        ++ lin_flat sg pt).
    { rewrite HW, Hpref, Hpost.
      rewrite !lin_flat_app_c, lin_flat_cons, EKB.
      rewrite !lin_flat_app_c.
      rewrite (lin_flat_nonph sg fr)
        by (intros g0 Hg0; exact (proj2 (Hfr g0 Hg0))).
      rewrite (lin_flat_nonph sg bk)
        by (intros g0 Hg0; exact (proj2 (Hbk g0 Hg0))).
      rewrite <- !app_assoc. reflexivity. }
    rewrite RHSeq.
    rewrite !lin_flat_app_c, lin_flat_cons, EKB2.
    rewrite (lin_flat_sgset sg key s2 pc Hk2 HCpc).
    rewrite (lin_flat_sgset sg key s2 pt Hk2 HCpt).
    rewrite HsF.
    cbn [lin_flat].
    rewrite <- !app_assoc. reflexivity.
  - split.
    2:{ apply (keys_big_map_eq _ sg);
        [apply sgset_keys; exact Hk2|exact HKb]. }
    rewrite (lin_ok_of_keys (sgset sg key s2) sg)
      by (apply sgset_keys; exact Hk2).
    rewrite (lin_ok_ext sg (pc ++ g :: pt) w); [exact HOk|].
    intros s0 Hs0.
    rewrite HW, Hpref, Hpost.
    rewrite !countkey_app. cbn [countkey].
    rewrite !countkey_app.
    rewrite (countkey_nonph_zero sg fr s0)
      by (assumption || (intros g0 Hg0; exact (proj2 (Hfr g0 Hg0)))).
    rewrite (countkey_nonph_zero sg bk s0)
      by (assumption || (intros g0 Hg0; exact (proj2 (Hbk g0 Hg0)))).
    lia.
Qed.
Lemma repack_keys_ok : forall keys sg w sg' w',
  lin_ok sg w = true ->
  keys_big sg ->
  repack_keys keys sg w = Some (sg', w') ->
  lin_flat sg' w' = lin_flat sg w /\
  lin_ok sg' w' = true /\ keys_big sg'.
Proof.
  induction keys as [|k ks IH]; intros sg w sg' w' HOk HKb H.
  - cbn in H. injection H as <- <-.
    split; [reflexivity|split; [exact HOk|exact HKb]].
  - cbn [repack_keys] in H.
    destruct (repack_one sg w k) as [[sg2 w2]|] eqn:E1;
      [|discriminate].
    destruct (repack_one_ok sg w k sg2 w2 HOk HKb E1)
      as [HF1 [HO1 HK1]].
    destruct (IH sg2 w2 sg' w' HO1 HK1 H) as [HF2 [HO2 HK2]].
    split; [|split; [exact HO2|exact HK2]].
    rewrite HF2, HF1. reflexivity.
Qed.
Lemma keyi_app : forall sg1 sg2 g,
  keyi (sg1 ++ sg2) g
  = match keyi sg1 g with
    | Some s => Some s
    | None => keyi sg2 g
    end.
Proof.
  induction sg1 as [|x t IH]; intros sg2 g.
  - cbn [app].
    replace (keyi [] g) with (None : option seg);
      [reflexivity|].
    unfold keyi. destruct (phshape g); reflexivity.
  - cbn [app]. rewrite !keyi_cons.
    destruct (phshape g) eqn:El.
    2:{ unfold keyi. rewrite El. reflexivity. }
    destruct (gC g =? sKey x); [reflexivity|].
    apply IH.
Qed.
Lemma ph_sgset_preserve : forall sg k s2 g,
  sKey s2 = k ->
  ph sg g = true ->
  ph (sgset sg k s2) g = true.
Proof.
  intros sg k s2 g Hk H.
  unfold ph in H |- *.
  rewrite (sgset_keyi sg k s2 g Hk).
  destruct (keyi sg g) as [s|]; [|discriminate].
  destruct (sKey s =? k); reflexivity.
Qed.
Lemma keyi_none_of_keys : forall sg g,
  (forall s, In s sg -> sKey s <> gC g) ->
  keyi sg g = None.
Proof.
  induction sg as [|x t IH]; intros g H.
  - unfold keyi. destruct (phshape g); reflexivity.
  - rewrite keyi_cons.
    destruct (phshape g); [|reflexivity].
    destruct (gC g =? sKey x) eqn:Ex.
    + exfalso. apply N.eqb_eq in Ex.
      exact (H x (or_introl eq_refl) (eq_sym Ex)).
    + apply IH. intros s Hs. exact (H s (or_intror Hs)).
Qed.
Lemma lin_flat_ext : forall sg0 added a,
  (forall s, In s added -> countkey (sKey s) a = O) ->
  lin_flat (sg0 ++ added) a = lin_flat sg0 a.
Proof.
  intros sg0 added a. induction a as [|g t IH]; intros Hz; [reflexivity|].
  rewrite !lin_flat_cons.
  assert (EKB : keyb (sg0 ++ added) g = keyb sg0 g).
  { unfold keyb. rewrite keyi_app.
    destruct (keyi sg0 g) eqn:E0; [reflexivity|].
    rewrite (keyi_none_of_counts added g (g :: t) (or_introl eq_refl));
      [reflexivity|].
    intros s Hs. exact (Hz s Hs). }
  rewrite EKB.
  destruct (keyb sg0 g).
  - f_equal. apply IH. intros s Hs.
    pose proof (Hz s Hs) as Z. cbn [countkey] in Z.
    destruct (phshape g && (gC g =? sKey s)); lia.
  - f_equal. apply IH. intros s Hs.
    pose proof (Hz s Hs) as Z. cbn [countkey] in Z.
    destruct (phshape g && (gC g =? sKey s)); lia.
Qed.
Lemma lin_flat_skip_mid : forall sg0 hs added2 a,
  countkey (sKey hs) a = O ->
  lin_flat (sg0 ++ hs :: added2) a
  = lin_flat (sg0 ++ added2) a.
Proof.
  intros sg0 hs added2 a. induction a as [|g t IH]; intros Hz;
    [reflexivity|].
  cbn [countkey] in Hz.
  rewrite !lin_flat_cons.
  assert (EKB : keyb (sg0 ++ hs :: added2) g
                = keyb (sg0 ++ added2) g).
  { unfold keyb. rewrite !keyi_app.
    destruct (keyi sg0 g) eqn:E0; [reflexivity|].
    rewrite keyi_cons.
    destruct (phshape g) eqn:El.
    + destruct (gC g =? sKey hs) eqn:Eh.
      * exfalso. cbn [andb] in Hz. lia.
      * reflexivity.
    + unfold keyi. rewrite El. reflexivity. }
  rewrite EKB.
  destruct (keyb (sg0 ++ added2) g).
  - f_equal. apply IH.
    destruct (phshape g && (gC g =? sKey hs)); lia.
  - f_equal. apply IH.
    destruct (phshape g && (gC g =? sKey hs)); lia.
Qed.
Lemma fresh_key_spec : forall sg k,
  (k <= fresh_key sg k)%N /\
  (forall s, In s sg -> (sKey s < fresh_key sg k)%N).
Proof.
  induction sg as [|x t IH]; intros k.
  - split; [apply N.le_refl|contradiction].
  - cbn [fresh_key].
    destruct (IH (N.max k (sKey x + 1))) as [H1 H2].
    split.
    + eapply N.le_trans; [|exact H1]. apply N.le_max_l.
    + intros s Hs. destruct Hs as [<-|Hs].
      * eapply N.lt_le_trans; [|exact H1].
        eapply N.lt_le_trans; [|apply N.le_max_r]. lia.
      * exact (H2 s Hs).
Qed.
Lemma lapply_keys_lb : forall pl w off kx cw added,
  lapply pl w off kx = (cw, added) ->
  forall s, In s added -> (kx <= sKey s)%N.
Proof.
  induction pl as [|[st l] pl IH]; intros w off kx cw added H s Hin.
  - cbn in H. inversion H; subst cw added. contradiction.
  - cbn [lapply] in H.
    destruct (split_body (firstn l (skipn (st - off) w)))
      as [bf bb] eqn:ESB.
    cbv beta iota zeta in H.
    destruct (lapply pl (skipn ((st - off) + l) w)
                (st + l) (kx + 1))
      as [cw2 sg2] eqn:EL.
    cbv beta iota zeta in H.
    inversion H; subst cw added. clear H.
    destruct Hin as [<-|Hin].
    + cbn [sKey]. apply N.le_refl.
    + pose proof (IH _ _ _ _ _ EL s Hin). lia.
Qed.
Lemma takerun_real_split :
  forall sg w,
    fst (takerun_real sg w) ++ snd (takerun_real sg w) = w.
Proof.
  intros sg w. induction w as [|g w IH]; [reflexivity|].
  cbn [takerun_real].
  destruct (casc_real sg g); [|reflexivity].
  destruct (takerun_real sg w) as [a b]. cbn [fst snd] in *.
  cbn [app]. now rewrite IH.
Qed.
Lemma takerun_real_casc :
  forall sg w,
    forallb (casc_real sg)
      (fst (takerun_real sg w)) = true.
Proof.
  intros sg w. induction w as [|g w IH]; [reflexivity|].
  cbn [takerun_real].
  destruct (casc_real sg g) eqn:Ec; [|reflexivity].
  destruct (takerun_real sg w) as [a b]. cbn [fst snd] in *.
  cbn [forallb]. now rewrite Ec, IH.
Qed.
Fixpoint plan_realP (sg0 : list seg) (pl : list (nat * nat))
    (w : word) (i : nat) : Prop :=
  match pl with
  | [] => True
  | (s, l) :: pl' =>
      (i <= s)%nat /\
      (forall g, In g (firstn l (skipn (s - i) w)) ->
         casc g = true /\ ph sg0 g = false) /\
      plan_realP sg0 pl' (skipn ((s - i) + l) w) (s + l)%nat
  end.
Lemma lplan_real_lb :
  forall fu sg0 w i s l,
    In (s, l) (lplan_real fu sg0 w i) -> (i <= s)%nat.
Proof.
  induction fu as [|fu IH]; intros sg0 w i s l Hin.
  - cbn in Hin. contradiction.
  - destruct w as [|g t]; [cbn in Hin; contradiction|].
    cbn [lplan_real] in Hin.
    destruct (casc_real sg0 g) eqn:Ec.
    2:{ cbv beta iota in Hin. apply IH in Hin. lia. }
    destruct (takerun_real sg0 (g :: t)) as [r rest] eqn:ET.
    cbv beta iota zeta in Hin.
    destruct (Nat.leb (2 * MARG + SEGMIN_GROUPS) (length r))
      eqn:E1.
    2:{ cbv beta iota in Hin. apply IH in Hin. lia. }
    cbv beta iota in Hin.
    match type of Hin with
    | In _ (if ?gate then _ else _) => destruct gate eqn:EG
    end.
    2:{ cbv beta iota in Hin. apply IH in Hin. lia. }
    cbv beta iota in Hin.
    destruct Hin as [Hhd|Hin].
    2:{ apply IH in Hin. lia. }
    injection Hhd as Hs Hl.
    subst s. lia.
Qed.
Lemma plan_realP_shift_pre :
  forall sg0 pl pre t i,
    plan_realP sg0 pl t (i + length pre)%nat ->
    (forall s l, In (s, l) pl -> (i + length pre <= s)%nat) ->
    plan_realP sg0 pl (pre ++ t) i.
Proof.
  intros sg0 pl pre t i HP HB.
  destruct pl as [|[s l] pl']; [exact I|].
  cbn [plan_realP] in HP |- *.
  destruct HP as (H1 & H2 & H3).
  pose proof (HB s l (or_introl eq_refl)) as Hs.
  assert (HS : skipn (s - i)%nat (pre ++ t)
               = skipn (s - (i + length pre))%nat t).
  { rewrite skipn_app.
    assert (HK : skipn (s - i)%nat pre = []) by (apply skipn_all2; lia).
    rewrite HK. cbn [app]. f_equal. lia. }
  assert (HS2 : skipn ((s - i) + l)%nat (pre ++ t)
                = skipn ((s - (i + length pre)) + l)%nat t).
  { rewrite skipn_app.
    assert (HK : skipn ((s - i) + l)%nat pre = [])
      by (apply skipn_all2; lia).
    rewrite HK. cbn [app]. f_equal. lia. }
  split; [lia|].
  split.
  - rewrite HS. exact H2.
  - rewrite HS2. exact H3.
Qed.
Lemma lplan_real_run_shift :
  forall fu' sg0 w r rest i,
    (forall w' i',
       plan_realP sg0 (lplan_real fu' sg0 w' i') w' i') ->
    takerun_real sg0 w = (r, rest) ->
    plan_realP sg0
      (lplan_real fu' sg0 rest (i + length r)%nat) w i.
Proof.
  intros fu' sg0 w r rest i IH ET.
  pose proof (takerun_real_split sg0 w) as HW. rewrite ET in HW.
  cbn [fst snd] in HW.
  rewrite <- HW.
  apply plan_realP_shift_pre.
  - apply IH.
  - intros s l Hin.
    pose proof (lplan_real_lb fu' sg0 rest (i + length r)%nat s l Hin). lia.
Qed.
Lemma lplan_real_entry :
  forall fu' sg0 w r rest i a b,
    (forall w' i',
       plan_realP sg0 (lplan_real fu' sg0 w' i') w' i') ->
    takerun_real sg0 w = (r, rest) ->
    (a <= b)%nat -> (b <= length r)%nat ->
    plan_realP sg0
      (((i + a)%nat, (b - a)%nat)
         :: lplan_real fu' sg0 rest (i + length r)%nat) w i.
Proof.
  intros fu' sg0 w r rest i a b IH ET Hab Hbr.
  pose proof (takerun_real_split sg0 w) as HW. rewrite ET in HW.
  cbn [fst snd] in HW.
  pose proof (takerun_real_casc sg0 w) as HC. rewrite ET in HC.
  cbn [fst] in HC.
  subst w.
  cbn [plan_realP].
  replace ((i + a) - i)%nat with a by lia.
  replace (a + (b - a))%nat with b by lia.
  replace ((i + a) + (b - a))%nat with (i + b)%nat by lia.
  split; [lia|].
  split.
  - intros g Hg.
    rewrite skipn_app in Hg.
    replace (a - length r)%nat with O in Hg by lia.
    cbn [skipn] in Hg.
    rewrite firstn_app in Hg.
    replace ((b - a) - length (skipn a r))%nat with O in Hg
      by (rewrite length_skipn; lia).
    rewrite firstn_O, app_nil_r in Hg.
    assert (Hin : In g r)
      by (exact (In_skipn g a r (In_firstn g (b - a)%nat (skipn a r) Hg))).
    eapply forallb_forall in HC; [|exact Hin].
    unfold casc_real in HC. apply andb_prop in HC.
    destruct HC as [Hc Hp].
    split; [exact Hc|].
    destruct (ph sg0 g); [discriminate|reflexivity].
  - rewrite skipn_app.
    replace (b - length r)%nat with O by lia.
    cbn [skipn].
    apply plan_realP_shift_pre.
    + rewrite length_skipn.
      replace ((i + b) + (length r - b))%nat with (i + length r)%nat by lia.
      apply IH.
    + intros s' l' Hin'.
      pose proof (lplan_real_lb fu' sg0 rest (i + length r)%nat s' l' Hin')
        as HB.
      rewrite length_skipn. lia.
Qed.
Lemma lplan_real_spec :
  forall fu sg0 w i,
    plan_realP sg0 (lplan_real fu sg0 w i) w i.
Proof.
  induction fu as [|fu IH]; intros sg0 w i.
  - exact I.
  - destruct w as [|g t].
    + exact I.
    + cbn [lplan_real].
      destruct (casc_real sg0 g) eqn:Ec.
      2:{ cbv beta iota.
          change (g :: t) with ([g] ++ t).
          apply plan_realP_shift_pre.
          - cbn [length].
            replace (i + 1)%nat with (S i) by lia.
            apply IH.
          - cbn [length]. intros s l Hin.
            pose proof (lplan_real_lb fu sg0 t (S i) s l Hin). lia. }
      destruct (takerun_real sg0 (g :: t)) as [r rest] eqn:ET.
      cbv beta iota zeta.
      destruct (Nat.leb (2 * MARG + SEGMIN_GROUPS)
                  (length r)) eqn:E1.
      2:{ cbv beta iota.
          eapply lplan_real_run_shift; [exact (IH sg0)|exact ET]. }
      apply PeanoNat.Nat.leb_le in E1.
      cbv beta iota.
      match goal with
      | |- plan_realP _ (if ?gate then _ else _) _ _ =>
          destruct gate eqn:EG
      end.
      2:{ eapply lplan_real_run_shift; [exact (IH sg0)|exact ET]. }
      apply andb_prop in EG. destruct EG as [EG1 EL2].
      apply PeanoNat.Nat.ltb_lt in EL2.
      apply lplan_real_entry.
      * exact (IH sg0).
      * exact ET.
      * lia.
      * destruct (is_lvl
                    (nth (length r - MARG - 1) r d0));
          cbv beta iota;
          unfold MARG, SEGMIN_GROUPS, SEGMIN in *;
          lia.
Qed.
Lemma lapply_flat_amb : forall pl sg0 w off kx cw added,
  (2 <= kx)%N ->
  lapply pl w off kx = (cw, added) ->
  plan_realP sg0 pl w off ->
  (forall s0, In s0 sg0 -> (sKey s0 < kx)%N) ->
  (forall s, In s added ->
     countkey (sKey s) cw = 1%nat) ->
  lin_flat (sg0 ++ added) cw = lin_flat sg0 w.
Proof.
  induction pl as [|[st l] pl IH];
    intros sg0 w off kx cw added Hkx H HP Hfr Hcnt.
  - cbn in H. inversion H; subst cw added.
    rewrite app_nil_r. reflexivity.
  - assert (Hkx1 : (2 <= kx + 1)%N) by lia.
    cbn [plan_realP] in HP. destruct HP as (HP1 & HPreg & HPrec).
    cbn [lapply] in H.
    destruct (split_body (firstn l (skipn (st - off) w)))
      as [bf bb] eqn:ESB.
    cbv beta iota zeta in H.
    destruct (lapply pl (skipn ((st - off) + l) w)
                (st + l) (kx + 1))
      as [cw2 sg2] eqn:EL.
    cbv beta iota zeta in H.
    inversion H; subst cw added. clear H.
    pose proof (Hcnt _ (or_introl eq_refl)) as Hk1.
    cbn [sKey] in Hk1.
    rewrite countkey_app in Hk1. cbn [countkey] in Hk1.
    rewrite (phshape_phg kx Hkx), gC_phg, N.eqb_refl in Hk1.
    cbn [andb] in Hk1.
    assert (Hpre0 : countkey kx (firstn (st - off) w) = O) by lia.
    assert (Hcw20 : countkey kx cw2 = O) by lia.
    assert (Htail : forall s, In s sg2 ->
        countkey (sKey s) (firstn (st - off) w) = O
        /\ countkey (sKey s) cw2 = 1%nat).
    { intros s Hin.
      pose proof (Hcnt s (or_intror Hin)) as Hs.
      rewrite countkey_app in Hs.
      cbn [countkey] in Hs.
      pose proof (lapply_keys_present _ _ _ _ _ _ Hkx1 EL s Hin) as Hge.
      lia. }
    set (KP := firstn (st - off) w) in *.
    set (RG := firstn l (skipn (st - off) w)) in *.
    set (TL := skipn ((st - off) + l) w) in *.
    assert (HWdec : w = KP ++ RG ++ TL).
    { unfold KP, RG, TL.
      transitivity (firstn (st - off) w ++ skipn (st - off) w);
        [symmetry; apply firstn_skipn|].
      f_equal.
      rewrite <- (firstn_skipn l (skipn (st - off) w)) at 1.
      f_equal.
      rewrite List.skipn_skipn.
      f_equal. lia. }
    rewrite HWdec.
    rewrite !lin_flat_app_c.
    rewrite (lin_flat_nonph sg0 RG)
      by (intros g0 Hg0; exact (proj2 (HPreg g0 Hg0))).
    rewrite (lin_flat_ext sg0).
    2:{ intros s Hin. destruct Hin as [<-|Hin].
        - cbn [sKey]. exact Hpre0.
        - exact (proj1 (Htail s Hin)). }
    rewrite lin_flat_cons.
    assert (EK : keyb
        (sg0 ++ (kx, 0%N, minlvl RG, length RG, bf, bb,
                 bsum RG) :: sg2)
        (phg kx)
      = Some (sFlat
               (kx, 0%N, minlvl RG, length RG, bf, bb,
                bsum RG))).
    { unfold keyb. rewrite keyi_app.
      rewrite (keyi_none_of_keys sg0).
      2:{ intros s0 Hs0.
          pose proof (Hfr s0 Hs0). rewrite gC_phg. lia. }
      rewrite keyi_cons.
      rewrite (phshape_phg kx Hkx), gC_phg.
      cbn [sKey]. rewrite N.eqb_refl. reflexivity. }
    rewrite EK. cbv beta iota.
    assert (EB : sFlat
        (kx, 0%N, minlvl RG, length RG, bf, bb,
         bsum RG) = RG).
    { unfold sFlat.
      cbn [sPend sBody sFront sBack].
      rewrite matb_0.
      pose proof (split_body_id RG) as E.
      rewrite ESB in E. cbn [fst snd] in E. exact E. }
    rewrite EB.
    rewrite lin_flat_skip_mid by (cbn [sKey]; exact Hcw20).
    assert (Hfr1 : forall s0, In s0 sg0 -> (sKey s0 < kx + 1)%N)
      by (intros s0 Hs0; pose proof (Hfr s0 Hs0); lia).
    rewrite (IH sg0 _ _ _ _ _ Hkx1 EL HPrec Hfr1
               (fun s Hin => proj2 (Htail s Hin))).
    reflexivity.
Qed.
Lemma lin_extend_ok : forall sg w sg2 w2,
  lin_ok sg w = true ->
  keys_big sg ->
  lin_extend sg w = Some (sg2, w2) ->
  lin_flat sg2 w2 = lin_flat sg w /\
  lin_ok sg2 w2 = true /\ keys_big sg2.
Proof.
  intros sg w sg2 w2 HOk HKb H.
  unfold lin_extend in H.
  destruct (lplan_real (length w) sg w O) as [|p pl0] eqn:EP.
  - injection H as <- <-.
    split; [reflexivity|split; [exact HOk|exact HKb]].
  - cbv beta iota in H.
    destruct (lapply (p :: pl0) w O
                (fresh_key sg KMAGIC))
      as [w2' added] eqn:ELap.
    cbv beta iota zeta in H.
    destruct (forallb (fun s => segcache s && segok s) added
              && lin_ok (sg ++ added) w2') eqn:EGate;
      [|discriminate].
    destruct (forallb segshape added); [|discriminate].
    destruct (forallb segpos added); [|discriminate].
    injection H as <- <-.
    apply andb_prop in EGate. destruct EGate as [_ HOk2].
    split.
    2:{ split; [exact HOk2|].
        intros s Hs. apply in_app_or in Hs. destruct Hs as [Hs|Hs].
        - exact (HKb s Hs).
        - eapply N.le_trans;
            [exact (proj1 (fresh_key_spec sg KMAGIC))|].
      exact (lapply_keys_lb _ _ _ _ _ _ ELap s Hs). }
    apply (lapply_flat_amb (p :: pl0) sg w O
             (fresh_key sg KMAGIC) w2' added
             ltac:(pose proof (proj1 (fresh_key_spec sg KMAGIC));
                   pose proof KMAGIC_2; lia)
             ELap).
    + pose proof (lplan_real_spec (length w) sg w O) as HP.
      rewrite EP in HP. exact HP.
    + intros s0 Hs0.
      exact (proj2 (fresh_key_spec sg KMAGIC) s0 Hs0).
    + intros s Hin.
      unfold lin_ok in HOk2.
      eapply forallb_forall in HOk2;
        [|apply in_or_app; right; exact Hin].
      apply PeanoNat.Nat.eqb_eq in HOk2. exact HOk2.
Qed.
Lemma lin_repack_ok : forall sg cw sg3 ps2 cw3,
  lin_ok sg cw = true ->
  keys_big sg ->
  lin_repack sg cw = Some (sg3, ps2, cw3) ->
  lin_flat sg3 cw3 = lin_flat sg cw /\
  lin_ok sg3 cw3 = true /\
  lin_guard sg3 cw3 = true /\ keys_big sg3.
Proof.
  intros sg cw sg3 ps2 cw3 HOk HKb H.
  unfold lin_repack in H.
  destruct (repack_keys (List.map sKey sg) sg cw)
    as [[sgA wA]|] eqn:ER; [|discriminate].
  cbv beta iota in H.
  destruct (repack_keys_ok _ _ _ _ _ HOk HKb ER) as [HFA [HOA HKA]].
  destruct (if Nat.leb (length wA) LZONE_MAX
            then Some (sgA, wA) else lin_extend sgA wA)
    as [[sgB wB]|] eqn:EE; [|discriminate].
  cbv beta iota in H.
  assert (HB : lin_flat sgB wB = lin_flat sg cw /\
               (lin_ok sgB wB = true /\ keys_big sgB)).
  { destruct (Nat.leb (length wA) LZONE_MAX).
    - injection EE as <- <-.
      split; [exact HFA|split; [exact HOA|exact HKA]].
    - destruct (lin_extend_ok sgA wA sgB wB HOA HKA EE)
        as [HFB [HOB HKB]].
      split; [rewrite HFB; exact HFA|split; [exact HOB|exact HKB]]. }
  destruct HB as [HFB [HOB HKB]].
  destruct (locate_all sgB wB) as [psB|] eqn:ELA; [|discriminate].
  destruct (lin_guard_at sgB psB wB) eqn:EGA; [|discriminate].
  destruct (lin_tags sgB wB); [|discriminate].
  injection H as <- <- <-.
  split; [exact HFB|].
  split; [exact HOB|].
  split; [exact (lin_guard_at_sound sgB psB wB HOB EGA)|exact HKB].
Qed.
Theorem T_cond_keys :
  forall w h cw sg h0,
    lin_cond w h = Some (cw, sg, h0) -> keys_big sg.
Proof.
  intros w h cw sg h0 H.
  unfold lin_cond in H.
  destruct (lplan (length w) w O) as [|p pl0] eqn:EP;
    [discriminate|].
  destruct (lin_condk KMAGIC w h)
    as [[[cw1 sg1] h1]|] eqn:EC; [|discriminate].
  destruct (lin_ok sg1 cw1) eqn:EOk; [|discriminate].
  destruct (lin_tags sg1 cw1) eqn:ETags; [|discriminate].
  inversion H; subst cw1 sg1 h1.
  unfold lin_condk in EC.
  rewrite EP in EC.
  destruct (lapply (p :: pl0) w O KMAGIC)
    as [cw' sg'] eqn:ELap.
  cbv beta iota zeta in EC.
  destruct (forallb (fun s => segcache s && segok s) sg');
    [|discriminate].
  destruct (forallb segshape sg'); [|discriminate].
  destruct (forallb segpos sg'); [|discriminate].
  inversion EC; subst cw' sg'.
  intros s Hs. exact (lapply_keys_lb _ _ _ _ _ _ ELap s Hs).
Qed.
Theorem T_cond_tags :
  forall w h cw sg h0,
    lin_cond w h = Some (cw, sg, h0) ->
    lin_tags sg cw = true.
Proof.
  intros w h cw sg h0 H.
  unfold lin_cond in H.
  destruct (lplan (length w) w O) as [|p pl0] eqn:EP;
    [discriminate|].
  destruct (lin_condk KMAGIC w h)
    as [[[cw1 sg1] h1]|] eqn:EC; [|discriminate].
  destruct (lin_ok sg1 cw1) eqn:EOk; [|discriminate].
  destruct (lin_tags sg1 cw1) eqn:ETags; [|discriminate].
  inversion H; subst cw1 sg1 h1. exact ETags.
Qed.
Theorem T_cond_shape :
  forall w h cw sg h0,
    lin_cond w h = Some (cw, sg, h0) -> sg_shape sg.
Proof.
  intros w h cw sg h0 H.
  unfold lin_cond in H.
  destruct (lplan (length w) w O) as [|p pl0] eqn:EP;
    [discriminate|].
  destruct (lin_condk KMAGIC w h)
    as [[[cw1 sg1] h1]|] eqn:EC; [|discriminate].
  destruct (lin_ok sg1 cw1); [|discriminate].
  destruct (lin_tags sg1 cw1); [|discriminate].
  inversion H; subst cw1 sg1 h1.
  unfold lin_condk in EC. rewrite EP in EC.
  destruct (lapply (p :: pl0) w O KMAGIC)
    as [cw' sg'] eqn:ELap.
  cbv beta iota zeta in EC.
  destruct (forallb (fun s => segcache s && segok s) sg');
    [|discriminate].
  destruct (forallb segshape sg') eqn:ES; [|discriminate].
  destruct (forallb segpos sg'); [|discriminate].
  inversion EC; subst cw' sg'. exact ES.
Qed.
Theorem T_cond_holds : T_cond.
Proof.
  intros w h cw sg h0 H.
  destruct (T_cond_flat_ok w h cw sg h0 H) as [Hflat HOk].
  split; [exact Hflat|].
  split; [exact HOk|].
  split; [exact (T_cond_guard w h cw sg h0 H)|].
  split.
  - exact (T_cond_keys w h cw sg h0 H).
  - exact (T_cond_tags w h cw sg h0 H).
Qed.
Definition sg_cached (sg : list seg) : Prop :=
  forallb segcache sg = true.
Lemma sflat_len : forall s,
  segcache s = true ->
  length (sFlat s) = sLen s.
Proof.
  intros s HC.
  unfold segcache in HC.
  apply PeanoNat.Nat.eqb_eq in HC.
  unfold sFlat, matb.
  rewrite length_map.
  unfold sBody.
  rewrite length_app, length_rev. lia.
Qed.
Lemma flen_flat : forall sg w,
  sg_cached sg ->
  lin_flen sg w = length (lin_flat sg w).
Proof.
  intros sg w HC. induction w as [|g t IH]; [reflexivity|].
  cbn [lin_flen].
  rewrite lin_flat_cons.
  unfold keyl, keyb.
  destruct (keyi sg g) as [s|] eqn:EK.
  - destruct (keyi_in sg g s EK) as (Hin & _ & _).
    rewrite length_app.
    rewrite sflat_len.
    + rewrite IH. reflexivity.
    + eapply forallb_forall in HC; [exact HC|exact Hin].
  - cbn [length]. rewrite IH. reflexivity.
Qed.
Definition sg_wf (sg : list seg) : Prop :=
  forallb (fun s => segcache s && segok s) sg = true.
Lemma segok_len1 : forall s,
  segok s = true -> (1 <= sLen s)%nat.
Proof.
  intros s H. unfold segok in H. cbv zeta in H.
  destruct (sBody s) as [|g0 b'] eqn:EB; [discriminate|].
  cbv beta iota in H.
  apply andb_prop in H. destruct H as [H _].
  apply andb_prop in H. destruct H as [H _].
  apply andb_prop in H. destruct H as [_ HOdd].
  destruct (sLen s) as [|n]; [cbn in HOdd; discriminate|lia].
Qed.
Lemma sg_wf_seg : forall sg s,
  sg_wf sg -> In s sg ->
  segcache s = true /\ segok s = true.
Proof.
  intros sg s HW Hin.
  unfold sg_wf in HW. eapply forallb_forall in HW; [|exact Hin].
  apply andb_prop in HW. exact HW.
Qed.
Lemma fmapw_gen : forall sg w j acc h,
  sg_wf sg ->
  (j <= h)%nat -> (h - j <= length w)%nat ->
  fmapw sg w j acc h
  = (acc + j + length (lin_flat sg (firstn (h - j)%nat w)))%nat.
Proof.
  intros sg w. induction w as [|g t IH]; intros j acc h HW Hjh Hlen.
  - cbn [length] in Hlen.
    assert (h = j) by lia. subst h.
    cbn [fmapw].
    rewrite PeanoNat.Nat.sub_diag. cbn [firstn lin_flat length].
    lia.
  - cbn [fmapw].
    destruct (Nat.leb h j) eqn:Ehj.
    + apply PeanoNat.Nat.leb_le in Ehj.
      assert (h = j) by lia. subst h.
      rewrite PeanoNat.Nat.sub_diag. cbn [firstn lin_flat length].
      lia.
    + apply PeanoNat.Nat.leb_gt in Ehj.
      unfold keyl.
      destruct (keyi sg g) as [s|] eqn:EK.
      * destruct (keyi_in sg g s EK) as (Hin & _ & _).
        destruct (sg_wf_seg sg s HW Hin) as [HC HOk].
        pose proof (segok_len1 s HOk) as HL1.
        rewrite IH; [|exact HW|lia|cbn [length] in Hlen; lia].
        replace (h - j)%nat with (S (h - S j))%nat by lia.
        cbn [firstn]. rewrite lin_flat_cons.
        unfold keyb. rewrite EK.
        rewrite length_app, (sflat_len s HC). lia.
      * rewrite IH; [|exact HW|lia|cbn [length] in Hlen; lia].
        replace (h - j)%nat with (S (h - S j))%nat by lia.
        cbn [firstn]. rewrite lin_flat_cons.
        unfold keyb. rewrite EK.
        cbn [length]. lia.
Qed.
Lemma casc_z2 : forall g, casc g = true -> gZ g = 2%N.
Proof.
  intros g H. unfold casc, is_lvl, is_spc in H.
  apply orb_prop in H.
  destruct g as [[o z] c].
  cbn [gO gZ gC] in *.
  destruct H as [H|H]; apply andb_prop in H.
  - destruct H as [_ H]. apply N.eqb_eq in H. exact H.
  - destruct H as [H _]. apply andb_prop in H. destruct H as [_ H].
    apply N.eqb_eq in H. exact H.
Qed.
Lemma sflat_z2 : forall s g,
  segok s = true -> In g (sFlat s) -> gZ g = 2%N.
Proof.
  intros s g HOk Hin.
  unfold sFlat, matb in Hin.
  apply in_map_iff in Hin. destruct Hin as (g0 & <- & Hin0).
  unfold segok in HOk. cbv zeta in HOk.
  destruct (sBody s) as [|gh b'] eqn:EB; [discriminate|].
  cbv beta iota in HOk.
  apply andb_prop in HOk. destruct HOk as [HOk _].
  apply andb_prop in HOk. destruct HOk as [_ HC].
  assert (Hcg : casc g0 = true)
    by (eapply forallb_forall in HC; [exact HC|exact Hin0]).
  destruct g0 as [[o z] c].
  pose proof (casc_z2 _ Hcg) as HZ. cbn [gZ] in HZ. subst z.
  unfold adjk.
  destruct ((o =? 4) && (2 =? 2))%N; cbn [gZ]; reflexivity.
Qed.
Lemma find_active_s_lb : forall w j i,
  find_active_s w j = Some i -> (j <= i)%nat.
Proof.
  induction w as [|g t IH]; intros j i H; [discriminate|].
  cbn [find_active_s] in H.
  destruct ((gZ g =? 1) || (3 <=? gZ g))%N.
  - injection H as <-. lia.
  - pose proof (IH (S j) i H). lia.
Qed.
Lemma find_active_s_app_z2 : forall a w j,
  (forall g, In g a -> gZ g = 2%N) ->
  find_active_s (a ++ w) j
  = find_active_s w (j + length a)%nat.
Proof.
  induction a as [|g a IH]; intros w j HZ.
  - cbn [app]. rewrite PeanoNat.Nat.add_0_r. reflexivity.
  - cbn [app find_active_s].
    rewrite (HZ g (or_introl eq_refl)).
    change (((2 =? 1) || (3 <=? 2))%N) with false.
    cbv beta iota.
    rewrite IH; [|intros g' H'; exact (HZ g' (or_intror H'))].
    f_equal. cbn [length]. lia.
Qed.
Lemma find_active_s_flat_gen : forall sg w j jf,
  sg_wf sg ->
  find_active_s (lin_flat sg w) jf
  = match find_active_s w j with
    | Some i =>
        Some (jf + length (lin_flat sg (firstn (i - j)%nat w)))%nat
    | None => None
    end.
Proof.
  intros sg w. induction w as [|g t IH]; intros j jf HW; [reflexivity|].
  rewrite lin_flat_cons.
  unfold keyb.
  destruct (keyi sg g) as [s|] eqn:EK.
  - destruct (keyi_in sg g s EK) as (Hin & Hlv & _).
    destruct (sg_wf_seg sg s HW Hin) as [HC HOk].
    cbn [find_active_s].
    assert (HZg : gZ g = 2%N) by exact (proj2 (phshape_o g Hlv)).
    rewrite HZg.
    change (((2 =? 1) || (3 <=? 2))%N) with false.
    cbv beta iota.
    rewrite (find_active_s_app_z2 (sFlat s) _ jf)
      by (intros g' H'; exact (sflat_z2 s g' HOk H')).
    rewrite (IH (S j) (jf + length (sFlat s))%nat HW).
    destruct (find_active_s t (S j)) as [i|] eqn:EF; [|reflexivity].
    f_equal.
    pose proof (find_active_s_lb t (S j) i EF) as Hlb.
    replace (i - j)%nat with (S (i - S j))%nat by lia.
    cbn [firstn]. rewrite lin_flat_cons.
    unfold keyb. rewrite EK. rewrite length_app. lia.
  - cbn [find_active_s].
    destruct ((gZ g =? 1) || (3 <=? gZ g))%N eqn:EA;
      cbv beta iota.
    + rewrite PeanoNat.Nat.sub_diag. cbn [firstn lin_flat length].
      f_equal. lia.
    + rewrite (IH (S j) (S jf) HW).
      destruct (find_active_s t (S j)) as [i|] eqn:EF; [|reflexivity].
      f_equal.
      pose proof (find_active_s_lb t (S j) i EF) as Hlb.
      replace (i - j)%nat with (S (i - S j))%nat by lia.
      cbn [firstn]. rewrite lin_flat_cons.
      unfold keyb. rewrite EK. cbn [length]. lia.
Qed.
Definition flat_res (sg : list seg)
    (r : option (word * N)) : option (word * N) :=
  match r with
  | Some (s', f') => Some (lin_flat sg s', f')
  | None => None
  end.
Definition kdist (a b : N) : N := if (a <? b)%N then (b - a)%N else (a - b)%N.
Definition gapn (n : N) (sg : list seg) (g : bg) : Prop :=
  forall s0, In s0 sg -> (n < kdist (gC g) (sKey s0))%N.
Lemma gap_nonph_any : forall sg g, gapn 0 sg g -> ph sg g = false.
Proof.
  intros sg g HG. unfold ph, keyi.
  destruct (phshape g); [|reflexivity].
  induction sg as [|s0 t IH]; [reflexivity|].
  destruct (gC g =? sKey s0)%N eqn:E.
  - exfalso. apply N.eqb_eq in E.
    pose proof (HG s0 (or_introl eq_refl)) as H.
    unfold kdist in H. rewrite E in H.
    rewrite N.ltb_irrefl in H. lia.
  - apply IH. intros s1 Hs1. exact (HG s1 (or_intror Hs1)).
Qed.
Lemma gap_nonph : forall sg g,
  is_lvl g = true -> gapn 0 sg g -> ph sg g = false.
Proof.
  intros sg g Hlvl _. unfold ph, keyi.
  rewrite (is_lvl_not_phshape g Hlvl). reflexivity.
Qed.
Lemma lvl_nonph : forall sg g,
  is_lvl g = true -> ph sg g = false.
Proof.
  intros sg g Hlvl. unfold ph, keyi.
  rewrite (is_lvl_not_phshape g Hlvl). reflexivity.
Qed.
Definition small4 (sg : list seg) (s : word) : Prop :=
  forall g, In g s -> is_lvl g = true ->
    ph sg g = true \/ gapn 32 sg g.
Definition small5 (sg : list seg) (s : word) : Prop :=
  forall g, In g s -> is_lvl g = true ->
    ph sg g = true \/ gapn 64 sg g.
Lemma keyi_nonlvl : forall sg g,
  phshape g = false -> keyi sg g = None.
Proof.
  intros sg g H. unfold keyi. rewrite H. reflexivity.
Qed.
Lemma flat_cons_nonlvl : forall sg g t,
  phshape g = false ->
  lin_flat sg (g :: t) = g :: lin_flat sg t.
Proof.
  intros sg g t H. rewrite lin_flat_cons.
  unfold keyb. rewrite (keyi_nonlvl sg g H). reflexivity.
Qed.
Lemma flat_cons_level : forall sg (c : N) t,
  lin_flat sg ((4%N, 2%N, c) :: t)
  = (4%N, 2%N, c) :: lin_flat sg t.
Proof.
  intros sg c t. apply flat_cons_nonlvl. reflexivity.
Qed.
Lemma keyi_small_none : forall sg (c : N),
  keys_big sg -> (c < KMAGIC)%N ->
  keyi sg (4%N, 2%N, c) = None.
Proof.
  intros sg c HK Hc.
  apply keyi_none_of_keys.
  intros s Hs. pose proof (HK s Hs). cbn [gC]. lia.
Qed.
Lemma flat_cons_small : forall sg (c : N) t,
  keys_big sg -> (c < KMAGIC)%N ->
  lin_flat sg ((4%N, 2%N, c) :: t)
  = (4%N, 2%N, c) :: lin_flat sg t.
Proof.
  intros sg c t HK Hc. rewrite lin_flat_cons.
  unfold keyb. rewrite (keyi_small_none sg c HK Hc). reflexivity.
Qed.
Lemma flat_cons_nonph : forall sg g t,
  ph sg g = false ->
  lin_flat sg (g :: t) = g :: lin_flat sg t.
Proof.
  intros sg g t H. rewrite lin_flat_cons.
  unfold keyb. unfold ph in H.
  destruct (keyi sg g); [discriminate|reflexivity].
Qed.
Lemma is_lvl_znot2 : forall (o z c : N),
  (z =? 2)%N = false -> is_lvl (o, z, c) = false.
Proof.
  intros o z c H. unfold is_lvl. cbn [gO gZ].
  rewrite H. apply andb_false_r.
Qed.
Lemma casc_cmf_false : forall (o : N) (c : N),
  ((5 <=? o) && negb (o =? 8) && negb (o =? 12))%N = true ->
  casc (o, 2%N, c) = false.
Proof.
  intros o c H.
  apply andb_prop in H. destruct H as [H _].
  apply andb_prop in H. destruct H as [H5 H8].
  apply N.leb_le in H5.
  unfold casc, is_lvl, is_spc.
  cbn [gO gZ gC].
  replace (o =? 4)%N with false
    by (symmetry; apply N.eqb_neq; lia).
  destruct (o =? 8)%N; [discriminate|].
  reflexivity.
Qed.
Ltac xrewrite H :=
  match type of H with
  | ?L = ?R =>
      match goal with
      | |- context [?T] =>
          unify T L;
          let E := fresh "EX" in
          assert (E : T = R) by (exact H);
          rewrite E; clear E
      end
  end.
Lemma flat_wnil : forall sg, lin_flat sg [] = [].
Proof. reflexivity. Qed.
Ltac xrewrite_in H E :=
  match type of E with
  | ?L = ?R =>
      match type of H with
      | context [?T] =>
          unify T L;
          let X := fresh "EX" in
          assert (X : T = R) by (exact E);
          rewrite X in H; clear X
      end
  end.
Ltac flatnil :=
  match goal with
  | |- context [lin_flat ?SG ?W] =>
      unify W (@nil bg);
      let E := fresh "EN" in
      assert (E : lin_flat SG W = []) by (apply flat_wnil);
      rewrite E; clear E
  end.
Ltac flatnil_in H :=
  match type of H with
  | context [lin_flat ?SG ?W] =>
      unify W (@nil bg);
      let E := fresh "EN" in
      assert (E : lin_flat SG W = []) by (apply flat_wnil);
      rewrite E in H; clear E
  end.
Lemma flat_cons_nonlvl' : forall sg g t,
  is_lvl g = false ->
  phshape g = false ->
  lin_flat sg (g :: t) = g :: lin_flat sg t.
Proof. intros sg g t _ H. exact (flat_cons_nonlvl sg g t H). Qed.
Ltac flatlit :=
  repeat first
    [ rewrite flat_cons_nonlvl'
        by (first [reflexivity
                  |apply is_lvl_znot2; reflexivity
                  |apply phshape_znot2; reflexivity
                  |apply phshape_onot9; reflexivity])
    | flatnil ].
Lemma gap_push : forall (n : N) sg (c2 c : N) t,
  (forall s0, In s0 sg -> (n < kdist c2 (sKey s0))%N) ->
  (kdist c c2 <= n)%N ->
  lin_flat sg ((4%N,2%N,c) :: t)
  = (4%N,2%N,c) :: lin_flat sg t.
Proof.
  intros n sg c2 c t HG Hd.
  apply flat_cons_nonph. apply gap_nonph; [reflexivity|].
  intros s0 Hs0. pose proof (HG s0 Hs0) as H0.
  cbn [gC]. unfold kdist in *.
  destruct (c2 <? sKey s0)%N eqn:E1;
    [apply N.ltb_lt in E1|apply N.ltb_ge in E1];
  (destruct (c <? c2)%N eqn:E2;
    [apply N.ltb_lt in E2|apply N.ltb_ge in E2]);
  (destruct (c <? sKey s0)%N eqn:E3;
    [apply N.ltb_lt in E3|apply N.ltb_ge in E3]); lia.
Qed.
Ltac flatsmall HK :=
  match goal with
  | |- context [lin_flat ?sg ((4%N, 2%N, ?c) :: ?t)] =>
      let E := fresh "EFS" in
      assert (E : lin_flat sg ((4%N, 2%N, c) :: t)
                  = (4%N, 2%N, c) :: lin_flat sg t)
        by (first
            [ apply flat_cons_level
            | apply flat_cons_small;
              [exact HK|apply N.ltb_lt; reflexivity]
            | match goal with
              | HG : forall s1, In s1 sg ->
                       (?n < kdist ?c2 (sKey s1))%N |- _ =>
                  apply (gap_push n sg c2 c t HG);
                  unfold kdist;
                  match goal with
                  | |- context [(?a <? ?b)%N] =>
                      destruct (a <? b)%N eqn:EDX;
                      [apply N.ltb_lt in EDX|apply N.ltb_ge in EDX]
                  end; lia
              end ]);
      rewrite E; clear E
  end.
Ltac flatchain HK :=
  repeat first [progress flatlit | flatsmall HK];
  try reflexivity.
Lemma flat_cons_ne : forall sg g u,
  sg_wf sg ->
  lin_flat sg (g :: u) <> [].
Proof.
  intros sg g u HW.
  rewrite lin_flat_cons.
  unfold keyb.
  destruct (keyi sg g) as [s|] eqn:EK.
  - destruct (keyi_in sg g s EK) as (Hin & _ & _).
    destruct (sg_wf_seg sg s HW Hin) as [HC HOk].
    pose proof (segok_len1 s HOk) as HL.
    pose proof (sflat_len s HC) as HF.
    destruct (sFlat s) as [|b0 bs].
    + cbn [length] in HF. lia.
    + cbn [app]. discriminate.
  - discriminate.
Qed.
Lemma flat_cons_smallc : forall sg (o z c : N) t,
  keys_big sg -> (c < KMAGIC)%N ->
  lin_flat sg ((o,z,c) :: t) = (o,z,c) :: lin_flat sg t.
Proof.
  intros sg o z c t HK Hc.
  rewrite lin_flat_cons.
  unfold keyb.
  rewrite keyi_none_of_keys; [reflexivity|].
  intros s Hs. pose proof (HK s Hs). cbn [gC]. lia.
Qed.
Lemma gap_push_any : forall (n : N) sg (o z c2 c : N) t,
  (forall s0, In s0 sg -> (n < kdist c2 (sKey s0))%N) ->
  (kdist c c2 <= n)%N ->
  lin_flat sg ((o,z,c) :: t)
  = (o,z,c) :: lin_flat sg t.
Proof.
  intros n sg o z c2 c t HG Hd.
  apply flat_cons_nonph. apply gap_nonph_any.
  intros s0 Hs0. pose proof (HG s0 Hs0) as H0.
  cbn [gC]. unfold kdist in *.
  destruct (c2 <? sKey s0)%N eqn:E1;
    [apply N.ltb_lt in E1|apply N.ltb_ge in E1];
  (destruct (c <? c2)%N eqn:E2;
    [apply N.ltb_lt in E2|apply N.ltb_ge in E2]);
  (destruct (c <? sKey s0)%N eqn:E3;
    [apply N.ltb_lt in E3|apply N.ltb_ge in E3]); lia.
Qed.
Ltac flatc HK :=
  match goal with
  | |- context [lin_flat ?SG ((?o, ?z, ?c) :: ?t)] =>
      let E := fresh "EFC" in
      assert (E : lin_flat SG ((o,z,c) :: t)
                  = (o,z,c) :: lin_flat SG t)
        by (first
            [ apply flat_cons_nonlvl; reflexivity
            | apply flat_cons_smallc;
              [exact HK|apply N.ltb_lt; reflexivity]
            | match goal with
              | HG : forall s1, In s1 SG ->
                       (?n < kdist ?c2 (sKey s1))%N |- _ =>
                  apply (gap_push_any n SG o z c2 c t HG);
                  unfold kdist;
                  match goal with
                  | |- context [(?a <? ?b)%N] =>
                      destruct (a <? b)%N eqn:EDX;
                      [apply N.ltb_lt in EDX|apply N.ltb_ge in EDX]
                  end; lia
              end ]);
      rewrite E; clear E
  end.
Ltac flatgo HK :=
  repeat first [progress flatlit | flatc HK];
  try reflexivity.
Ltac flatgo2 HK EF :=
  repeat first [progress flatlit | flatc HK | xrewrite EF];
  try reflexivity.
Lemma casc_z1_false : forall (A C : N), casc (A, 1%N, C) = false.
Proof.
  intros A C.
  unfold casc, is_lvl, is_spc.
  cbn [gO gZ gC].
  change ((1 =? 2)%N) with false.
  rewrite !andb_false_r.
  reflexivity.
Qed.
Lemma last2_cons_ge2 : forall (g : bg) t,
  (2 <= length t)%nat ->
  last2 (g :: t)
  = match last2 t with
    | Some (ini, a, b) => Some (g :: ini, a, b)
    | None => None
    end.
Proof.
  intros g t H.
  destruct t as [|x [|y t2]]; cbn [length] in H; try lia.
  reflexivity.
Qed.
Lemma LineageGuard_last2_app : forall (ini : word) (a b : bg),
  last2 (ini ++ [a; b]) = Some (ini, a, b).
Proof.
  induction ini as [|g ini IH]; intros a b.
  - reflexivity.
  - cbn [app].
    rewrite last2_cons_ge2.
    + rewrite IH. reflexivity.
    + rewrite length_app. cbn [length]. lia.
Qed.
Lemma LineageGuard_last2_split : forall cols ini (a b : bg),
  last2 cols = Some (ini, a, b) -> cols = ini ++ [a; b].
Proof.
  induction cols as [|g t IH]; intros ini a b H; [discriminate|].
  destruct t as [|x [|y t2]].
  - discriminate.
  - cbn in H. injection H as <- <- <-. reflexivity.
  - rewrite last2_cons_ge2 in H by (cbn [length]; lia).
    destruct (last2 (x :: y :: t2)) as [[[ini' a'] b']|] eqn:E;
      [|discriminate].
    injection H as <- <- <-.
    cbn [app]. f_equal.
    exact (IH _ _ _ eq_refl).
Qed.
Ltac flatph H :=
  match goal with
  | |- context [lin_flat ?SG (?g :: ?t)] =>
      let E := fresh "EFP" in
      assert (E : lin_flat SG (g :: t)
                  = g :: lin_flat SG t)
        by (apply flat_cons_nonph; exact H);
      rewrite E; clear E
  end.
Ltac flatall HK Hpa Hpb :=
  repeat first
    [ progress flatlit
    | flatc HK
    | flatph Hpa
    | flatph Hpb ];
  try reflexivity.
Lemma lawR_seg_flat : forall sg ini (a b : bg) (B : N),
  keys_big sg ->
  ph sg a = false -> ph sg b = false ->
  lawR_seg (lin_flat sg (ini ++ [a; b])) B
  = match lawR_seg (ini ++ [a; b]) B with
    | Some seg2 => Some (lin_flat sg seg2)
    | None => None
    end.
Proof.
  intros sg ini a b B HK Hpa Hpb.
  assert (EFI : lin_flat sg (ini ++ [a; b])
                = lin_flat sg ini ++ [a; b]).
  { rewrite lin_flat_app_c. f_equal.
    flatph Hpa. flatph Hpb. rewrite flat_wnil.
    reflexivity. }
  xrewrite EFI.
  destruct a as [[gao gaz] gac]. destruct b as [[gbo gbz] gbc].
  unfold lawR_seg.
  rewrite !LineageGuard_last2_app.
  destruct ((gao =? 8) && (gaz =? 2) && (gac =? 1)
            && (gbo =? 4) && (gbz =? 2) && (1 <=? gbc))%N eqn:E1.
  { apply andb_prop in E1. destruct E1 as [E1 Egbc].
    apply andb_prop in E1. destruct E1 as [E1 Egbz].
    apply andb_prop in E1. destruct E1 as [E1 Egbo].
    apply N.eqb_eq in Egbo, Egbz. subst gbo gbz.
    f_equal.
    rewrite !lin_flat_app_c. f_equal.
    destruct (1 <? B)%N; flatall HK Hpa Hpb. }
  destruct ((gbo =? 8) && (gbz =? 2) && (gbc =? 1))%N eqn:E2;
    [|reflexivity].
  f_equal.
  rewrite !lin_flat_app_c. f_equal.
  destruct (1 <? B)%N; flatall HK Hpa Hpb.
Qed.
Lemma endR_seg_flat : forall sg ini (a b : bg) (f : N),
