Definition seektest (g : bg) : bool :=
  is_col g && negb (is_cmf g) && (3 <=? gO g)%N.
Lemma phshape_seektest : forall g,
  phshape g = true -> seektest g = true.
Proof. intros g H. unfold seektest. exact (phshape_seek_col g H). Qed.
Lemma seek_cons_eq : forall g t,
  seek (g :: t)
  = if seektest g
    then (g :: fst (seek t), snd (seek t))
    else ([], g :: t).
Proof.
  intros g t. cbn [seek].
  unfold seektest.
  destruct (is_col g && negb (is_cmf g) && (3 <=? gO g))%N.
  - destruct (seek t) as [c r]. reflexivity.
  - reflexivity.
Qed.
Lemma casc_seekable : forall g,
  casc g = true -> seektest g = true.
Proof.
  intros g H.
  unfold casc, is_lvl, is_spc in H.
  destruct g as [[o z] c].
  cbn [gO gZ gC] in H.
  apply orb_prop in H.
  unfold seektest, is_col, is_cmf.
  cbn [gO gZ gC].
  destruct H as [H|H].
  - apply andb_prop in H. destruct H as [Ho Hz].
    apply N.eqb_eq in Ho, Hz. subst o z.
    cbn. rewrite ?andb_false_r. reflexivity.
  - apply andb_prop in H. destruct H as [H Hc].
    apply andb_prop in H. destruct H as [Ho Hz].
    apply N.eqb_eq in Ho, Hz, Hc. subst o z c.
    cbn. rewrite ?andb_false_r. reflexivity.
Qed.
Lemma sflat_seekable : forall s g,
  segok s = true -> In g (sFlat s) ->
  seektest g = true.
Proof.
  intros s g HOk Hin.
  apply casc_seekable.
  unfold sFlat, matb in Hin.
  apply in_map_iff in Hin. destruct Hin as (g0 & <- & Hin0).
  unfold segok in HOk. cbv zeta in HOk.
  destruct (sBody s) as [|gh b'] eqn:EB; [discriminate|].
  cbv beta iota in HOk.
  apply andb_prop in HOk. destruct HOk as [HOk _].
  apply andb_prop in HOk. destruct HOk as [_ HC].
  assert (Hcg : casc g0 = true)
    by (eapply forallb_forall in HC; [exact HC|exact Hin0]).
  destruct g0 as [[o z] c].
  unfold casc, is_lvl, is_spc in Hcg |- *.
  cbn [gO gZ gC] in Hcg.
  unfold adjk.
  apply orb_prop in Hcg.
  destruct Hcg as [H|H].
  - apply andb_prop in H. destruct H as [Ho Hz].
    apply N.eqb_eq in Ho, Hz. subst o z.
    cbn. rewrite ?andb_false_r. reflexivity.
  - apply andb_prop in H. destruct H as [H Hc].
    apply andb_prop in H. destruct H as [Ho Hz].
    apply N.eqb_eq in Ho, Hz, Hc. subst o z c.
    cbn. rewrite ?andb_false_r. reflexivity.
Qed.
Lemma seek_app_col : forall a w,
  (forall g, In g a -> seektest g = true) ->
  seek (a ++ w)
  = (a ++ fst (seek w), snd (seek w)).
Proof.
  induction a as [|g a IH]; intros w H.
  - cbn [app]. destruct (seek w). reflexivity.
  - cbn [app]. rewrite seek_cons_eq.
    rewrite (H g (or_introl eq_refl)).
    rewrite IH by (intros g' H'; exact (H g' (or_intror H'))).
    reflexivity.
Qed.
Lemma seek_flat : forall sg r,
  sg_wf sg ->
  seek (lin_flat sg r)
  = (lin_flat sg (fst (seek r)),
     lin_flat sg (snd (seek r))).
Proof.
  intros sg r HW. induction r as [|g t IH].
  - reflexivity.
  - rewrite lin_flat_cons.
    unfold keyb.
    destruct (keyi sg g) as [s|] eqn:EK.
    + destruct (keyi_in sg g s EK) as (Hin & Hlv & _).
      destruct (sg_wf_seg sg s HW Hin) as [HC HOk].
      rewrite seek_app_col
        by (intros g' H'; exact (sflat_seekable s g' HOk H')).
      rewrite IH.
      rewrite seek_cons_eq.
      rewrite phshape_seektest by exact Hlv.
      cbn [fst snd].
      rewrite lin_flat_cons.
      unfold keyb. rewrite EK. reflexivity.
    + assert (Hphg : ph sg g = false)
        by (unfold ph; rewrite EK; reflexivity).
      rewrite !seek_cons_eq.
      destruct (seektest g) eqn:ET; cbv beta iota.
      * rewrite IH. cbn [fst snd].
        f_equal. flatph Hphg. reflexivity.
      * cbn [fst snd]. flatnil. flatph Hphg. reflexivity.
Qed.
Lemma ph_seektest : forall sg g,
  ph sg g = true -> seektest g = true.
Proof. intros sg g H. exact (phshape_seektest g (ph_shape sg g H)). Qed.
Lemma seektest_notag : forall g, seektest g = false -> notag g = true.
Proof.
  intros g H. unfold notag.
  destruct (phshape g) eqn:E; [|reflexivity].
  rewrite (phshape_seektest g E) in H. discriminate.
Qed.
Lemma ph_not_cmf : forall sg g,
  ph sg g = true -> is_cmf g = false.
Proof. intros sg g H. exact (phshape_not_cmf g (ph_shape sg g H)). Qed.
Lemma LineageGuard_seek_split : forall r,
  r = fst (seek r) ++ snd (seek r).
Proof.
  induction r as [|g t IH]; [reflexivity|].
  rewrite seek_cons_eq.
  destruct (seektest g); cbn [fst snd app].
  - f_equal. exact IH.
  - reflexivity.
Qed.
Lemma seek_fst_col : forall r g,
  In g (fst (seek r)) -> seektest g = true.
Proof.
  induction r as [|g0 t IH]; intros g Hin; [contradiction|].
  rewrite seek_cons_eq in Hin.
  destruct (seektest g0) eqn:E0; cbn [fst] in Hin.
  - destruct Hin as [<-|Hin]; [exact E0|exact (IH g Hin)].
  - contradiction.
Qed.
Lemma seek_snd_head : forall r g b,
  snd (seek r) = g :: b -> seektest g = false.
Proof.
  induction r as [|g0 t IH]; intros g b H; [discriminate|].
  rewrite seek_cons_eq in H.
  destruct (seektest g0) eqn:E0; cbn [snd] in H.
  - exact (IH g b H).
  - injection H as <- _. exact E0.
Qed.
Lemma seektest_noncasc : forall g,
  seektest g = false -> casc g = false.
Proof.
  intros g H.
  destruct (casc g) eqn:E; [|reflexivity].
  rewrite (casc_seekable g E) in H. discriminate.
Qed.
Lemma is_cmf_o4 : forall (z c : N), is_cmf (4%N, z, c) = false.
Proof.
  intros z c. unfold is_cmf. cbn [gO gZ gC].
  change ((5 <=? 4)%N) with false.
  rewrite !andb_false_r. rewrite ?andb_false_l. reflexivity.
Qed.
Lemma is_cmf_o8 : forall (z c : N), is_cmf (8%N, z, c) = false.
Proof.
  intros z c. unfold is_cmf. cbn [gO gZ gC].
  change (negb (8 =? 8)%N) with false.
  rewrite !andb_false_r. reflexivity.
Qed.
Lemma casc_not_cmf : forall g,
  casc g = true -> is_cmf g = false.
Proof.
  intros g H.
  unfold casc, is_lvl, is_spc in H.
  destruct g as [[o z] c].
  cbn [gO gZ gC] in H.
  apply orb_prop in H.
  destruct H as [H|H].
  - apply andb_prop in H. destruct H as [Ho _].
    apply N.eqb_eq in Ho. subst o. apply is_cmf_o4.
  - apply andb_prop in H. destruct H as [H _].
    apply andb_prop in H. destruct H as [Ho _].
    apply N.eqb_eq in Ho. subst o. apply is_cmf_o8.
Qed.
Lemma sflat_not_cmf : forall s g,
  segok s = true -> In g (sFlat s) ->
  is_cmf g = false.
Proof.
  intros s g HOk Hin.
  unfold sFlat, matb in Hin.
  apply in_map_iff in Hin. destruct Hin as (g0 & <- & Hin0).
  unfold segok in HOk. cbv zeta in HOk.
  destruct (sBody s) as [|gh b'] eqn:EB; [discriminate|].
  cbv beta iota in HOk.
  apply andb_prop in HOk. destruct HOk as [HOk _].
  apply andb_prop in HOk. destruct HOk as [_ HC].
  assert (Hcg : casc g0 = true)
    by (eapply forallb_forall in HC; [exact HC|exact Hin0]).
  destruct g0 as [[o z] c].
  pose proof (casc_not_cmf _ Hcg) as HNC.
  unfold casc, is_lvl, is_spc in Hcg.
  cbn [gO gZ gC] in Hcg.
  apply orb_prop in Hcg.
  unfold adjk.
  destruct Hcg as [H|H].
  - apply andb_prop in H. destruct H as [Ho _].
    apply N.eqb_eq in Ho. subst o.
    destruct ((4 =? 4) && (z =? 2))%N; apply is_cmf_o4.
  - apply andb_prop in H. destruct H as [H _].
    apply andb_prop in H. destruct H as [Ho _].
    apply N.eqb_eq in Ho. subst o.
    destruct ((8 =? 4) && (z =? 2))%N; apply is_cmf_o8.
Qed.
Lemma sflat_is_col : forall s g,
  segok s = true -> In g (sFlat s) ->
  is_col g = true.
Proof.
  intros s g HOk Hin.
  unfold sFlat, matb in Hin.
  apply in_map_iff in Hin. destruct Hin as (g0 & <- & Hin0).
  unfold segok in HOk. cbv zeta in HOk.
  destruct (sBody s) as [|gh b'] eqn:EB; [discriminate|].
  cbv beta iota in HOk.
  apply andb_prop in HOk. destruct HOk as [HOk _].
  apply andb_prop in HOk. destruct HOk as [_ HC].
  assert (Hcg : casc g0 = true)
    by (eapply forallb_forall in HC; [exact HC|exact Hin0]).
  destruct g0 as [[o z] c].
  pose proof (casc_z2 _ Hcg) as HZ. cbn [gZ] in HZ. subst z.
  unfold casc, is_lvl, is_spc in Hcg.
  cbn [gO gZ gC] in Hcg.
  unfold adjk.
  unfold is_col.
  apply orb_prop in Hcg.
  destruct Hcg as [H|H].
  - apply andb_prop in H. destruct H as [Ho _].
    apply N.eqb_eq in Ho. subst o.
    destruct ((4 =? 4) && (2 =? 2))%N; cbn [gO gZ]; reflexivity.
  - apply andb_prop in H. destruct H as [H _].
    apply andb_prop in H. destruct H as [Ho _].
    apply N.eqb_eq in Ho. subst o.
    destruct ((8 =? 4) && (2 =? 2))%N; cbn [gO gZ]; reflexivity.
Qed.
Definition ph_flanked (sg : list seg) (w : word) : Prop :=
  forall p g, nth_error w p = Some g -> ph sg g = true ->
    (1 <= p)%nat /\
    (exists gl, nth_error w (p - 1) = Some gl /\
                is_spc gl = true) /\
    (exists gr, nth_error w (p + 1) = Some gr /\
                is_spc gr = true).
Fixpoint plan_flankP (pl : list (nat * nat)) (w : word) (i : nat)
  : Prop :=
  match pl with
  | [] => True
  | (s, l) :: pl' =>
      (1 <= s - i)%nat /\
      (exists gl, nth_error w (s - i - 1) = Some gl /\
                  is_spc gl = true) /\
      (exists gr, nth_error w ((s - i) + l) = Some gr /\
                  is_spc gr = true) /\
      plan_flankP pl' (skipn ((s - i) + l) w) (s + l)%nat
  end.
Lemma plan_flankP_shift_pre : forall pl pre t i,
  plan_flankP pl t (i + length pre)%nat ->
  (forall s l, In (s, l) pl ->
     (i + length pre + GUARD <= s)%nat) ->
  plan_flankP pl (pre ++ t) i.
Proof.
  intros pl pre t i HP HB.
  destruct pl as [|[s l] pl']; [exact I|].
  cbn [plan_flankP] in HP |- *.
  destruct HP as (H1 & (gl & Hgl & Hsl) & (gr & Hgr & Hsr) & H4).
  pose proof (HB s l (or_introl eq_refl)) as Hs.
  assert (HS2 : skipn ((s - i) + l)%nat (pre ++ t)
                = skipn ((s - (i + length pre)) + l)%nat t).
  { rewrite skipn_app.
    assert (HK : skipn ((s - i) + l)%nat pre = [])
      by (apply skipn_all2; unfold GUARD in Hs; lia).
    rewrite HK. cbn [app]. f_equal. lia. }
  split; [unfold GUARD in Hs; lia|].
  split.
  { exists gl. split; [|exact Hsl].
    rewrite nth_error_app2 by (unfold GUARD in Hs; lia).
    replace (s - i - 1 - length pre)%nat
      with (s - (i + length pre) - 1)%nat
      by (unfold GUARD in Hs; lia).
    exact Hgl. }
  split.
  { exists gr. split; [|exact Hsr].
    rewrite nth_error_app2 by (unfold GUARD in Hs; lia).
    replace ((s - i) + l - length pre)%nat
      with ((s - (i + length pre)) + l)%nat
      by (unfold GUARD in Hs; lia).
    exact Hgr. }
  rewrite HS2. exact H4.
Qed.
Lemma lplan_flank_run_shift : forall fu' w r rest i,
  (forall w' i', plan_flankP (lplan fu' w' i') w' i') ->
  takerun w = (r, rest) ->
  plan_flankP (lplan fu' rest (i + length r)%nat) w i.
Proof.
  intros fu' w r rest i IH ET.
  pose proof (takerun_split w) as HW. rewrite ET in HW.
  cbn [fst snd] in HW.
  rewrite <- HW.
  apply plan_flankP_shift_pre.
  - apply IH.
  - intros s l Hin.
    pose proof (lplan_lb fu' rest (i + length r)%nat s l Hin).
    lia.
Qed.
Lemma lplan_flank_entry : forall fu' w r rest i a b,
  (forall w' i', plan_flankP (lplan fu' w' i') w' i') ->
  takerun w = (r, rest) ->
  (2 * MARG + SEGMIN_GROUPS <= length r)%nat ->
  (MARG <= a)%nat -> (a <= S MARG)%nat ->
  (b <= length r - MARG)%nat -> (a < b)%nat ->
  is_spc (nth (a - 1) r d0) = true ->
  is_spc (nth b r d0) = true ->
  plan_flankP (((i + a)%nat, (b - a)%nat)
                 :: lplan fu' rest (i + length r)%nat) w i.
Proof.
  intros fu' w r rest i a b IH ET Hn Ha1 Ha2 Hb1 Hab HS1 HS2.
  pose proof (takerun_split w) as HW. rewrite ET in HW.
  cbn [fst snd] in HW.
  subst w.
  unfold MARG, SEGMIN_GROUPS, SEGMIN
    in Hn, Ha1, Ha2, Hb1.
  cbn [plan_flankP].
  replace ((i + a) - i)%nat with a by lia.
  replace (a + (b - a))%nat with b by lia.
  replace ((i + a) + (b - a))%nat with (i + b)%nat by lia.
  split; [lia|].
  split.
  { exists (nth (a - 1)%nat r d0).
    split; [|exact HS1].
    rewrite nth_error_app1 by lia.
    apply nth_error_nth'. lia. }
  split.
  { exists (nth b r d0).
    split; [|exact HS2].
    rewrite nth_error_app1 by lia.
    apply nth_error_nth'. lia. }
  rewrite skipn_app.
  replace (b - length r)%nat with O by lia.
  cbn [skipn].
  apply plan_flankP_shift_pre.
  - rewrite length_skipn.
    replace ((i + b) + (length r - b))%nat with (i + length r)%nat by lia.
    apply IH.
  - intros s' l' Hin'.
    pose proof (lplan_lb fu' rest (i + length r)%nat s' l'
                  Hin') as HB.
    rewrite length_skipn. lia.
Qed.
Lemma lplan_plan_flankP :
  forall fu w i, plan_flankP (lplan fu w i) w i.
Proof.
  induction fu as [|fu IH]; intros w i.
  - exact I.
  - destruct w as [|g t].
    + exact I.
    + cbn [lplan].
      destruct (casc g) eqn:Ec.
      2:{ cbv beta iota.
          change (g :: t) with ([g] ++ t).
          apply plan_flankP_shift_pre.
          - cbn [length].
            replace (i + 1)%nat with (S i) by lia.
            apply IH.
          - cbn [length]. intros s l Hin.
            pose proof (lplan_lb fu t (S i) s l Hin). lia. }
      destruct (takerun (g :: t)) as [r rest] eqn:ET.
      cbv beta iota zeta.
      destruct (Nat.leb (2 * MARG + SEGMIN_GROUPS)
                  (length r)) eqn:E1.
      2:{ cbv beta iota.
          eapply lplan_flank_run_shift; [exact IH|exact ET]. }
      apply PeanoNat.Nat.leb_le in E1.
      cbv beta iota.
      match goal with
      | |- plan_flankP (if ?gate then _ else _) _ _ =>
          destruct gate eqn:EG
      end.
      2:{ eapply lplan_flank_run_shift; [exact IH|exact ET]. }
      apply andb_prop in EG. destruct EG as [EG1 EL2].
      apply andb_prop in EG1. destruct EG1 as [ES1 ES2].
      apply PeanoNat.Nat.ltb_lt in EL2.
      apply lplan_flank_entry.
      * exact IH.
      * exact ET.
      * exact E1.
      * destruct (is_lvl (nth MARG r d0));
          cbv beta iota; unfold MARG; lia.
      * destruct (is_lvl (nth MARG r d0));
          cbv beta iota; lia.
      * destruct (is_lvl
                    (nth (length r - MARG - 1) r d0));
          cbv beta iota; lia.
      * exact EL2.
      * exact ES1.
      * exact ES2.
Qed.
Lemma lapply_flanked : forall pl sg w i kx,
  plan_flankP pl w i ->
  plan_okP pl w i ->
  (forall g, In g (lkept pl w i) ->
     ph sg g = false) ->
  ph_flanked sg (fst (lapply pl w i kx)).
Proof.
  induction pl as [|[s l] pl' IH]; intros sg w i kx HF HO Hnp.
  - cbn [lapply fst].
    intros p gp Hp Hph.
    exfalso.
    rewrite (Hnp gp (nth_error_In _ _ Hp)) in Hph. discriminate.
  - cbn [plan_flankP] in HF.
    destruct HF as (HF1 & (gl & Hgl & Hsl) & (gr & Hgr & Hsr) & HFrec).
    cbn [plan_okP] in HO.
    destruct HO as (HO1 & HO2 & HO3 & HO4 & HO5 & HO6).
    cbn [lapply].
    destruct (split_body (firstn l (skipn (s - i) w)))
      as [bf bb] eqn:ESB.
    cbv beta iota zeta.
    destruct (lapply pl' (skipn ((s - i) + l) w) (s + l) (kx + 1))
      as [cw2 sg2] eqn:EL.
    cbv beta iota zeta. cbn [fst].
    cbn [lkept] in Hnp.
    assert (Hsw : ((s - i) + l + GUARD <= length w)%nat)
      by (rewrite length_skipn in HO5; unfold GUARD in *; lia).
    assert (Hklen : length (firstn (s - i) w) = (s - i)%nat)
      by (rewrite length_firstn; lia).
    assert (Hc2head : nth_error cw2 O
                      = nth_error (skipn ((s - i) + l) w) O).
    { destruct pl' as [|[s2 l2] pl''].
      - cbn in EL. injection EL as <- <-. reflexivity.
      - cbn [lapply] in EL.
        destruct (split_body
                    (firstn l2 (skipn (s2 - (s + l))
                       (skipn ((s - i) + l) w))))
          as [bf2 bb2] eqn:ESB2.
        cbv beta iota zeta in EL.
        destruct (lapply pl''
                    (skipn ((s2 - (s + l)) + l2)
                       (skipn ((s - i) + l) w))
                    (s2 + l2) (kx + 1 + 1))
          as [cw3 sg3] eqn:EL2.
        cbv beta iota zeta in EL.
        injection EL as <- <-.
        cbn [plan_flankP] in HFrec.
        destruct HFrec as (HF21 & _).
        destruct (skipn ((s - i) + l) w) as [|u0 ut] eqn:EU.
        + exfalso.
          assert (HL0 : length (skipn ((s - i) + l) w) = O)
            by (rewrite EU; reflexivity).
          rewrite length_skipn in HL0.
          unfold GUARD in Hsw. lia.
        + destruct (s2 - (s + l))%nat as [|k2] eqn:EK2; [lia|].
          cbn [firstn app nth_error]. reflexivity. }
    intros p gp Hp Hph.
    destruct (PeanoNat.Nat.lt_trichotomy p (s - i)) as [Hlt|[Heq|Hgt]].
    + exfalso.
      rewrite nth_error_app1 in Hp by (rewrite Hklen; lia).
      apply nth_error_In in Hp.
      rewrite (Hnp gp (in_or_app _ _ _ (or_introl Hp))) in Hph.
      discriminate.
    + subst p.
      split; [lia|].
      split.
      { exists gl. split; [|exact Hsl].
        rewrite nth_error_app1 by (rewrite Hklen; lia).
        rewrite nth_firstn by lia.
        exact Hgl. }
      { exists gr. split; [|exact Hsr].
        rewrite nth_error_app2 by (rewrite Hklen; lia).
        rewrite Hklen.
        replace ((s - i) + 1 - (s - i))%nat with 1%nat by lia.
        cbn [nth_error].
        xrewrite Hc2head.
        rewrite nth_skipn.
        rewrite PeanoNat.Nat.add_0_r.
        exact Hgr. }
    + assert (Hq : nth_error cw2 (p - (s - i) - 1)%nat = Some gp).
      { rewrite nth_error_app2 in Hp by (rewrite Hklen; lia).
        rewrite Hklen in Hp.
        destruct (p - (s - i))%nat as [|q] eqn:EQ; [lia|].
        cbn [nth_error] in Hp.
        replace (S q - 1)%nat with q by lia.
        exact Hp. }
      pose proof (IH sg (skipn ((s - i) + l) w) (s + l)%nat (kx+1)%N
                     HFrec HO6
                     (fun g Hg => Hnp g (in_or_app _ _ _ (or_intror Hg))))
        as HIH.
      rewrite EL in HIH. cbn [fst] in HIH.
      destruct (HIH (p - (s - i) - 1)%nat gp Hq Hph)
        as (Hq1 & (gl2 & Hgl2 & Hsl2) & (gr2 & Hgr2 & Hsr2)).
      split; [lia|].
      split.
      { exists gl2. split; [|exact Hsl2].
        rewrite nth_error_app2 by (rewrite Hklen; lia).
        rewrite Hklen.
        destruct (p - 1 - (s - i))%nat as [|q1] eqn:EQ1; [lia|].
        cbn [nth_error].
        replace q1 with (p - (s - i) - 1 - 1)%nat by lia.
        exact Hgl2. }
      { exists gr2. split; [|exact Hsr2].
        rewrite nth_error_app2 by (rewrite Hklen; lia).
        rewrite Hklen.
        destruct (p + 1 - (s - i))%nat as [|q2] eqn:EQ2; [lia|].
        cbn [nth_error].
        replace q2 with (p - (s - i) - 1 + 1)%nat by lia.
        exact Hgr2. }
Qed.
Theorem T_cond_flanked : forall w h cw sg h0,
  lin_cond w h = Some (cw, sg, h0) -> ph_flanked sg cw.
Proof.
  intros w h cw sg h0 H.
  unfold lin_cond in H.
  destruct (lplan (length w) w O) as [|p pl0] eqn:EP;
    [discriminate|].
  destruct (lin_condk KMAGIC w h)
    as [[[cw1 sg1] h1]|] eqn:EC; [|discriminate].
  destruct (lin_ok sg1 cw1) eqn:EOk; [|discriminate].
  destruct (lin_tags sg1 cw1) eqn:ETags; [|discriminate].
  inversion H; subst cw1 sg1 h1.
  unfold lin_condk in EC.
  rewrite EP in EC.
  destruct (lapply (p :: pl0) w O KMAGIC)
    as [cw' sg'] eqn:ELap.
  cbv beta iota zeta in EC.
  destruct (forallb (fun s => segcache s && segok s) sg');
    [|discriminate].
  destruct (forallb segshape sg'); [|discriminate].
  destruct (forallb segpos sg'); [|discriminate].
  inversion EC; subst cw' sg'.
  pose proof (lplan_plan_flankP (length w) w O) as HF.
  rewrite EP in HF.
  pose proof (lplan_plan_okP (length w) w O) as HO.
  rewrite EP in HO.
  pose proof (lin_ok_kept_nonph (p :: pl0) w O
                KMAGIC cw sg KMAGIC_2 ELap EOk) as Hnp.
  pose proof (lapply_flanked (p :: pl0) sg w O KMAGIC
                HF HO Hnp) as HFl.
  rewrite ELap in HFl. cbn [fst] in HFl.
  exact HFl.
Qed.
Ltac insolver :=
  cbn [In];
  first [ left; reflexivity
        | right; left; reflexivity
        | right; right; left; reflexivity
        | right; right; right; left; reflexivity
        | right; right; right; right; left; reflexivity
        | right; right; right; right; right; left; reflexivity ].
Ltac kdside :=
  unfold kdist;
  match goal with
  | |- context [(?a <? ?b)%N] =>
      destruct (a <? b)%N eqn:EDX;
      [apply N.ltb_lt in EDX|apply N.ltb_ge in EDX]
  end; lia.
Ltac gappush SG cc tt HK :=
  first
    [ apply flat_cons_level
    | apply flat_cons_small;
      [exact HK|apply N.ltb_lt; reflexivity]
    | match goal with
      | HG : forall s1, In s1 SG ->
               (?n < kdist ?c2 (sKey s1))%N |- _ =>
          apply (gap_push n SG c2 cc tt HG); kdside
      end
    | match goal with
      | HS4 : small4 SG ?ww,
        HPH : ph SG (4%N,2%N,?c2) = false |- _ =>
          apply (gap_push 4 SG c2 cc tt);
          [ intros s1 Hs1;
            destruct (HS4 (4%N,2%N,c2) ltac:(insolver) eq_refl) as [HX|HX];
            [congruence | exact (HX s1 Hs1)]
          | kdside ]
      end
    | match goal with
      | HS5 : small5 SG ?ww,
        HPH : ph SG (4%N,2%N,?c2) = false |- _ =>
          apply (gap_push 5 SG c2 cc tt);
          [ intros s1 Hs1;
            destruct (HS5 (4%N,2%N,c2) ltac:(insolver) eq_refl) as [HX|HX];
            [congruence | exact (HX s1 Hs1)]
          | kdside ]
      end ].
Ltac fsmall HK :=
  match goal with
  | |- context [lin_flat ?SG ((4%N,2%N,?cc) :: ?tt)] =>
      let E := fresh "EFS" in
      assert (E : lin_flat SG ((4%N,2%N,cc) :: tt)
                  = (4%N,2%N,cc) :: lin_flat SG tt)
        by (gappush SG cc tt HK);
      rewrite E; clear E
  end.
Ltac plit := progress flatlit.
Definition ph_nbrs (sg : list seg) (w : word) : Prop :=
  forall p g, nth_error w p = Some g -> ph sg g = true ->
    (exists gr, nth_error w (p + 1) = Some gr /\
                is_spc gr = true) /\
    (forall gl, (1 <= p)%nat -> nth_error w (p - 1) = Some gl ->
                is_spc gl = true).
Lemma ph_flanked_nbrs : forall sg w,
  ph_flanked sg w -> ph_nbrs sg w.
Proof.
  intros sg w H p g Hp Hph.
  destruct (H p g Hp Hph) as (H1 & (gl & Hgl & Hsl) & HR).
  split; [exact HR|].
  intros gl' Hp1 Hgl'.
  rewrite Hgl' in Hgl. injection Hgl as <-. exact Hsl.
Qed.
Lemma ph_nbrs_tail : forall sg g t,
  ph_nbrs sg (g :: t) -> ph_nbrs sg t.
Proof.
  intros sg g t H p gp Hp Hph.
  destruct (H (S p) gp Hp Hph) as (HR & HL).
  split.
  - exact HR.
  - intros gl Hp1 Hgl.
    apply (HL gl); [lia|].
    replace (S p - 1)%nat with (S (p - 1)) by lia.
    cbn [nth_error]. exact Hgl.
Qed.
Lemma spc_nonph : forall sg g,
  is_spc g = true -> ph sg g = false.
Proof. intros sg g H. exact (notag_ph sg g (spc_notag g H)). Qed.
Lemma casc_o48 : forall g,
  casc g = true -> gO g = 4%N \/ gO g = 8%N.
Proof.
  intros g H.
  unfold casc, is_lvl, is_spc in H.
  destruct g as [[o z] c]. cbn [gO gZ gC] in *.
  apply orb_prop in H.
  destruct H as [H|H].
  - apply andb_prop in H. destruct H as [Ho _].
    apply N.eqb_eq in Ho. auto.
  - apply andb_prop in H. destruct H as [H _].
    apply andb_prop in H. destruct H as [Ho _].
    apply N.eqb_eq in Ho. auto.
Qed.
Lemma In_flat_nonph : forall sg t g,
  In g t -> ph sg g = false ->
  In g (lin_flat sg t).
Proof.
  intros sg t. induction t as [|g0 t IH]; intros g Hin Hph;
    [contradiction|].
  rewrite lin_flat_cons.
  destruct Hin as [->|Hin].
  - unfold keyb. unfold ph in Hph.
    destruct (keyi sg g); [discriminate|].
    left. reflexivity.
  - unfold keyb.
    destruct (keyi sg g0) as [s|].
    + apply in_or_app. right. exact (IH g Hin Hph).
    + right. exact (IH g Hin Hph).
Qed.
Lemma spc_not_w42 : forall g,
  is_spc g = true -> w42 g = false.
Proof.
  intros g H.
  unfold is_spc in H. unfold w42.
  destruct g as [[o z] c]. cbn [gO gZ gC] in *.
  apply andb_prop in H. destruct H as [H _].
  apply andb_prop in H. destruct H as [Ho _].
  apply N.eqb_eq in Ho. subst o.
  reflexivity.
Qed.
Lemma forallb_w42_spc_false : forall a gx X',
  is_spc gx = true ->
  forallb w42 (a ++ gx :: X') = false.
Proof.
  intros a gx X' H.
  destruct (forallb w42 (a ++ gx :: X')) eqn:E; [|reflexivity].
  exfalso.
  eapply forallb_forall in E;
    [|apply in_or_app; right; left; reflexivity].
  rewrite (spc_not_w42 gx H) in E. discriminate.
Qed.
Lemma dtb4_app_skip : forall a gx X',
  (forall g, In g a -> casc g = true) ->
  is_spc gx = true ->
  dtb4_conv (a ++ gx :: X')
  = match dtb4_conv (gx :: X') with
    | Some Y => Some (a ++ Y)
    | None => None
    end.
Proof.
  induction a as [|g a IH]; intros gx X' HC HS.
  - cbn [app]. destruct (dtb4_conv (gx :: X')); reflexivity.
  - cbn [app].
    remember (dtb4_conv (gx :: X')) as R eqn:ER.
    cbn [dtb4_conv].
    rewrite (IH gx X')
      by first [exact HS | intros g' H'; exact (HC g' (or_intror H'))].
    rewrite <- ER.
    destruct R as [Y|].
    { reflexivity. }
    pose proof (HC g (or_introl eq_refl)) as Hcg.
    destruct g as [[o z] c].
    cbn [gO gZ gC].
    destruct ((o =? 8) && (z =? 2) && (c =? 1))%N eqn:E8; [|reflexivity].
    rewrite forallb_w42_spc_false by exact HS.
    destruct a as [|[[o1 z1] c1] a'].
    +
      cbn [app].
      destruct gx as [[ox zx] cx].
      assert (Hox : ox = 8%N).
      { unfold is_spc in HS.
        cbn [gO gZ gC] in HS.
        apply andb_prop in HS. destruct HS as [HS' _].
        apply andb_prop in HS'. destruct HS' as [Ho _].
        apply N.eqb_eq in Ho. exact Ho. }
      subst ox.
      destruct X' as [|g2 X''].
      * reflexivity.
      * destruct g2 as [[o2 z2] c2].
        change ((8 =? 4)%N) with false.
        cbn [andb]. reflexivity.
    +
      cbn [app].
      pose proof (HC (o1,z1,c1) (or_intror (or_introl eq_refl))) as Hc1.
      destruct (casc_o48 _ Hc1) as [Ho1|Ho1];
        cbn [gO] in Ho1; subst o1.
      *
        destruct a' as [|[[o2 z2] c2] a''].
        --
           cbn [app].
           destruct gx as [[ox zx] cx].
           assert (Hox : ox = 8%N).
           { unfold is_spc in HS.
             cbn [gO gZ gC] in HS.
             apply andb_prop in HS. destruct HS as [HS' _].
             apply andb_prop in HS'. destruct HS' as [Ho _].
             apply N.eqb_eq in Ho. exact Ho. }
           subst ox.
           change ((8 =? 3)%N) with false.
           destruct (z1 =? 2)%N, (1 <=? c1)%N, (zx =? 2)%N, (cx =? 1)%N;
             reflexivity.
        --
           pose proof (HC (o2,z2,c2)
                         (or_intror (or_intror (or_introl eq_refl))))
             as Hc2.
           destruct (casc_o48 _ Hc2) as [Ho2|Ho2];
             cbn [gO] in Ho2; subst o2.
           ++ change ((4 =? 3)%N) with false.
              destruct (z1 =? 2)%N, (1 <=? c1)%N, (z2 =? 2)%N,
                (c2 =? 1)%N; reflexivity.
           ++ change ((8 =? 3)%N) with false.
              destruct (z1 =? 2)%N, (1 <=? c1)%N, (z2 =? 2)%N,
                (c2 =? 1)%N; reflexivity.
      *
        change ((8 =? 4)%N) with false.
        cbn [andb].
        destruct gx as [[ox zx] cx].
        destruct a' as [|[[oq zq] cq] a2]; cbn [app].
        { destruct X' as [|[[o3 z3] c3] X2]; reflexivity. }
        { destruct a2 as [|[[o3 z3] c3] a3]; cbn [app]; reflexivity. }
Qed.
Lemma forallb_false_ex : forall (p : bg -> bool) l,
  forallb p l = false -> exists x, In x l /\ p x = false.
Proof.
  induction l as [|g t IH]; intros H; [discriminate|].
  cbn [forallb] in H.
  destruct (p g) eqn:E.
  - cbn [andb] in H.
    destruct (IH H) as (x & Hin & Hx).
    exists x. split; [right; exact Hin|exact Hx].
  - exists g. split; [left; reflexivity|exact E].
Qed.
Lemma w42_forallb_flat : forall sg t,
  sg_wf sg -> ph_nbrs sg t ->
  (forall p g, nth_error t p = Some g -> ph sg g = true ->
     exists gr, nth_error t (p + 1) = Some gr /\ is_spc gr = true) ->
  forallb w42 (lin_flat sg t) = forallb w42 t.
Proof.
  intros sg t HW HN HR.
  destruct (forallb w42 t) eqn:ET.
  - assert (Hnp : forall g, In g t -> ph sg g = false).
    { intros g Hin.
      destruct (ph sg g) eqn:EP; [|reflexivity].
      exfalso.
      destruct (In_nth_error _ _ Hin) as (q & Hq).
      destruct (HR q g Hq EP) as (gr & Hgr & Hsr).
      eapply forallb_forall in ET; [|exact (nth_error_In _ _ Hgr)].
      rewrite (spc_not_w42 gr Hsr) in ET. discriminate. }
    rewrite (lin_flat_nonph sg t Hnp).
    exact ET.
  - destruct (forallb_false_ex _ _ ET) as (x & Hin & Hx).
    destruct (forallb w42 (lin_flat sg t)) eqn:EF;
      [|reflexivity].
    exfalso.
    assert (Hy : exists y, In y t /\ w42 y = false /\
                           ph sg y = false).
    { destruct (ph sg x) eqn:EPx.
      - destruct (In_nth_error _ _ Hin) as (q & Hq).
        destruct (HR q x Hq EPx) as (gr & Hgr & Hsr).
        exists gr. split; [exact (nth_error_In _ _ Hgr)|].
        split; [exact (spc_not_w42 gr Hsr)|exact (spc_nonph sg gr Hsr)].
      - exists x. split; [exact Hin|split; [exact Hx|exact EPx]]. }
    destruct Hy as (y & Hiny & Hwy & Hpy).
    eapply forallb_forall in EF;
      [|exact (In_flat_nonph sg t y Hiny Hpy)].
    rewrite Hwy in EF. discriminate.
Qed.
Lemma ph_shape42 : forall sg g,
  ph sg g = true ->
  exists K, g = (9%N, 2%N, K).
Proof.
  intros sg g H.
  pose proof (ph_shape sg g H) as Hs.
  destruct (phshape_o g Hs) as [Ho Hz].
  destruct g as [[o z] c]. cbn [gO gZ] in Ho, Hz.
  subst o z. exists c. reflexivity.
Qed.
Lemma flat_ph_head : forall sg g t s,
  keyi sg g = Some s ->
  sg_wf sg ->
  exists cb bt,
    lin_flat sg (g :: t)
    = (4%N, 2%N, cb) :: bt ++ lin_flat sg t /\
    (forall g', In g' ((4%N,2%N,cb) :: bt) -> casc g' = true).
Proof.
  intros sg g t s EK HW.
  destruct (keyi_in sg g s EK) as (Hin & _ & _).
  destruct (sg_wf_seg sg s HW Hin) as (HC & HOk).
  rewrite lin_flat_cons.
  unfold keyb. rewrite EK.
  assert (HCB : forall g', In g' (sFlat s) ->
            casc g' = true).
  { intros g' Hg'.
    unfold sFlat, matb in Hg'.
    apply in_map_iff in Hg'. destruct Hg' as (g0 & <- & Hin0).
    unfold segok in HOk. cbv zeta in HOk.
    destruct (sBody s) as [|gh b'] eqn:EB; [discriminate|].
    cbv beta iota in HOk.
    apply andb_prop in HOk. destruct HOk as [HOk' _].
    apply andb_prop in HOk'. destruct HOk' as [_ HCc].
    assert (Hcg : casc g0 = true)
      by (eapply forallb_forall in HCc; [exact HCc|exact Hin0]).
    destruct g0 as [[o0 z0] c_0].
    pose proof (casc_z2 _ Hcg) as HZ.
    cbn [gZ] in HZ. subst z0.
    unfold casc, is_lvl, is_spc in Hcg |- *.
    cbn [gO gZ gC] in Hcg.
    unfold adjk.
    apply orb_prop in Hcg.
    destruct Hcg as [H0|H0].
    - apply andb_prop in H0. destruct H0 as [Ho _].
      apply N.eqb_eq in Ho. subst o0.
      change ((4 =? 4) && (2 =? 2))%N with true.
      cbv beta iota. reflexivity.
    - apply andb_prop in H0. destruct H0 as [H0 Hc].
      apply andb_prop in H0. destruct H0 as [Ho _].
      apply N.eqb_eq in Ho, Hc. subst o0 c_0.
      change ((8 =? 4) && (2 =? 2))%N with false.
      cbv beta iota. reflexivity. }
  unfold segok in HOk. cbv zeta in HOk.
  destruct (sBody s) as [|[[oh zh] ch] b'] eqn:EB;
    [discriminate|].
  cbv beta iota in HOk.
  apply andb_prop in HOk. destruct HOk as [HOk' _].
  apply andb_prop in HOk'. destruct HOk' as [HOk' _].
  apply andb_prop in HOk'. destruct HOk' as [HOk' _].
  apply andb_prop in HOk'. destruct HOk' as [Hh _].
  unfold is_lvl in Hh. cbn [gO gZ] in Hh.
  apply andb_prop in Hh. destruct Hh as [Ho4 Hz2].
  apply N.eqb_eq in Ho4, Hz2. subst oh zh.
  unfold sFlat. rewrite EB.
  unfold matb. cbn [map].
  unfold adjk at 1.
  change ((4 =? 4) && (2 =? 2))%N with true.
  cbv beta iota.
  do 2 eexists.
  split.
  - cbn [app]. reflexivity.
  - intros g' Hg'.
    apply HCB.
    unfold sFlat. rewrite EB.
    unfold matb. cbn [map].
    unfold adjk at 1.
    change ((4 =? 4) && (2 =? 2))%N with true.
    cbv beta iota.
    exact Hg'.
Qed.
Lemma dtb4_cons : forall (g : bg) t,
  dtb4_conv (g :: t)
  = match dtb4_conv t with
    | Some t' => Some (g :: t')
    | None =>
        if ((gO g =? 8) && (gZ g =? 2) && (gC g =? 1))%N
        then if forallb w42 t
             then Some ((7,1,1)%N :: (3,2,1)%N :: t)
             else
               match t with
               | (o1,z1,c1) :: (o2,z2,c2) :: t2 =>
                   if ((o1 =? 4) && (z1 =? 2) && (1 <=? c1)
                      && (o2 =? 3) && (z2 =? 2) && (c2 =? 1))%N
                   then match t2 with
                        | [] => Some ((7,1,1)%N :: (3,2,1)%N
                                :: (if (1 <? c1)%N then [(4,2,c1-1)%N]
                                    else []) ++ [(4,1,1)%N; (4,2,1)%N])
                        | [(o3,z3,c3)] =>
                            if ((o3 =? 4) && (z3 =? 2))%N
                            then Some ((7,1,1)%N :: (3,2,1)%N
                                 :: (if (1 <? c1)%N then [(4,2,c1-1)%N]
                                     else []) ++ [(4,1,1)%N; (4,2,c3+1)%N])
                            else None
                        | _ :: _ :: _ => None
                        end
                   else None
               | _ => None
               end
        else None
    end.
Proof.
  intros g t. destruct g as [[o z] c]. reflexivity.
Qed.
Lemma dtb4_conv_flat : forall sg cols,
  sg_wf sg -> keys_big sg ->
  ph_nbrs sg cols ->
  dtb4_conv (lin_flat sg cols)
  = match dtb4_conv cols with
    | Some Y => Some (lin_flat sg Y)
    | None => None
    end.
Proof.
  intros sg cols. induction cols as [|g t IH]; intros HW HK HN.
  - reflexivity.
  - pose proof (ph_nbrs_tail sg g t HN) as HNt.
    destruct (keyi sg g) as [s|] eqn:EK.
    +
      assert (Hph : ph sg g = true)
        by (unfold ph; rewrite EK; reflexivity).
      destruct (HN O g eq_refl Hph) as ((gr & Hgr & Hsr) & _).
      cbn [nth_error] in Hgr.
      destruct t as [|g1 t1]; [discriminate|].
      cbn [nth_error] in Hgr. injection Hgr as ->.
      destruct (flat_ph_head sg g (gr :: t1) s EK HW)
        as (cb & bt & EFH & HCB).
      xrewrite EFH.
      assert (EF1 : lin_flat sg (gr :: t1)
                    = gr :: lin_flat sg t1)
        by (apply flat_cons_nonph;
            exact (spc_nonph sg gr Hsr)).
      xrewrite EF1.
      match goal with
      | |- context [dtb4_conv ?T] =>
          unify T (((4%N,2%N,cb) :: bt) ++ gr :: lin_flat sg t1);
          let E := fresh "ESK" in
          assert (E : dtb4_conv T
                      = match dtb4_conv
                              (gr :: lin_flat sg t1) with
                        | Some Y => Some (((4%N,2%N,cb) :: bt) ++ Y)
                        | None => None
                        end)
            by (exact (dtb4_app_skip ((4%N,2%N,cb) :: bt) gr
                         (lin_flat sg t1) HCB Hsr));
          rewrite E; clear E
      end.
      pose proof (IH HW HK HNt) as IHt.
      rewrite EF1 in IHt.
      xrewrite IHt.
      destruct (ph_shape42 sg g Hph) as (K & Hg42). subst g.
      assert (EFlatY : forall Y,
          lin_flat sg ((9%N,2%N,K) :: Y)
          = sFlat s ++ lin_flat sg Y)
        by (intros Y; rewrite lin_flat_cons;
            unfold keyb; rewrite EK; reflexivity).
      assert (EBody : sFlat s = (4%N,2%N,cb) :: bt).
      { apply (app_inv_tail (lin_flat sg (gr :: t1))).
        rewrite <- EFlatY.
        exact EFH. }
      assert (ECOND : dtb4_conv ((9%N,2%N,K) :: gr :: t1)
                      = match dtb4_conv (gr :: t1) with
                        | Some t' => Some ((9%N,2%N,K) :: t')
                        | None => None
                        end) by reflexivity.
      xrewrite ECOND.
      destruct (dtb4_conv (gr :: t1)) as [Y|] eqn:EY.
      * cbv beta iota.
        xrewrite (EFlatY Y). rewrite EBody. reflexivity.
      * cbv beta iota. reflexivity.
    +
      assert (Hphg : ph sg g = false)
        by (unfold ph; rewrite EK; reflexivity).
      assert (EFg : lin_flat sg (g :: t)
                    = g :: lin_flat sg t)
        by (apply flat_cons_nonph; exact Hphg).
      xrewrite EFg.
      xrewrite (dtb4_cons g (lin_flat sg t)).
      xrewrite (dtb4_cons g t).
      pose proof (IH HW HK HNt) as IHt.
      xrewrite IHt.
      destruct (dtb4_conv t) as [Y|] eqn:EY; cbv beta iota.
      { assert (EFY : lin_flat sg (g :: Y)
                      = g :: lin_flat sg Y)
          by (apply flat_cons_nonph; exact Hphg).
        xrewrite EFY. reflexivity. }
      destruct g as [[o z] c].
      cbn [gO gZ gC].
      destruct ((o =? 8) && (z =? 2) && (c =? 1))%N eqn:E8;
        cbv beta iota; [|reflexivity].
      rewrite (w42_forallb_flat sg t HW HNt
                 (fun p g' Hp Hph' => proj1 (HNt p g' Hp Hph'))).
      destruct (forallb w42 t) eqn:EW; cbv beta iota.
      {
        assert (Hnp : forall g', In g' t -> ph sg g' = false).
        { intros g' Hin.
          destruct (ph sg g') eqn:EP; [|reflexivity].
          exfalso.
          destruct (In_nth_error _ _ Hin) as (q & Hq).
          destruct (proj1 (HNt q g' Hq EP)) as (grr & Hgrr & Hsrr).
          eapply forallb_forall in EW;
            [|exact (nth_error_In _ _ Hgrr)].
          rewrite (spc_not_w42 grr Hsrr) in EW. discriminate. }
        rewrite (lin_flat_nonph sg t Hnp).
        rewrite !flat_cons_nonlvl by reflexivity.
        rewrite (lin_flat_nonph sg t Hnp).
        reflexivity. }
      destruct t as [|g1 t1].
      { reflexivity. }
      destruct (keyi sg g1) as [s1|] eqn:EK1.
      {
        assert (Hph1 : ph sg g1 = true)
          by (unfold ph; rewrite EK1; reflexivity).
        destruct (HNt O g1 eq_refl Hph1) as ((gr2 & Hgr2 & Hsr2) & _).
        cbn [nth_error] in Hgr2.
        destruct t1 as [|g2 t2]; [discriminate|].
        cbn [nth_error] in Hgr2. injection Hgr2 as ->.
        destruct (ph_shape42 sg g1 Hph1) as (K1 & Hg1e). subst g1.
        destruct gr2 as [[or2 zr2] cr2].
        assert (Hor2 : or2 = 8%N).
        { unfold is_spc in Hsr2.
          cbn [gO gZ gC] in Hsr2.
          apply andb_prop in Hsr2. destruct Hsr2 as [Hsr2' _].
          apply andb_prop in Hsr2'. destruct Hsr2' as [Ho _].
          apply N.eqb_eq in Ho. exact Ho. }
        subst or2.
        change ((8 =? 3)%N) with false.
        destruct (flat_ph_head sg (9%N,2%N,K1) ((8%N,zr2,cr2) :: t2)
                    s1 EK1 HW)
          as (cb1 & bt1 & EFH1 & HCB1).
        xrewrite EFH1.
        destruct bt1 as [|gb bt1'].
        {
          cbn [app].
          assert (EF2 : lin_flat sg ((8%N,zr2,cr2) :: t2)
                        = (8%N,zr2,cr2) :: lin_flat sg t2).
          { apply flat_cons_nonph.
            apply spc_nonph.
            unfold is_spc.
            cbn [gO gZ gC].
            unfold is_spc in Hsr2.
            cbn [gO gZ gC] in Hsr2.
            exact Hsr2. }
          xrewrite EF2.
          destruct (1 <=? K1)%N, (1 <=? cb1)%N, (zr2 =? 2)%N,
            (cr2 =? 1)%N; cbn [andb]; reflexivity. }
        {
          pose proof (HCB1 gb (or_intror (or_introl eq_refl))) as Hcgb.
          destruct gb as [[ob zb] cbb].
          destruct (casc_o48 _ Hcgb) as [Hob|Hob];
            cbn [gO] in Hob; subst ob.
          - change ((4 =? 3)%N) with false.
            destruct (1 <=? K1)%N, (1 <=? cb1)%N, (zb =? 2)%N,
              (cbb =? 1)%N; cbn [andb]; reflexivity.
          - change ((8 =? 3)%N) with false.
            destruct (1 <=? K1)%N, (1 <=? cb1)%N, (zb =? 2)%N,
              (cbb =? 1)%N; cbn [andb]; reflexivity. } }
      {
        assert (Hphg1 : ph sg g1 = false)
          by (unfold ph; rewrite EK1; reflexivity).
        assert (EFg1 : lin_flat sg (g1 :: t1)
                       = g1 :: lin_flat sg t1)
          by (apply flat_cons_nonph; exact Hphg1).
        xrewrite EFg1.
        destruct t1 as [|g2 t2].
        { flatnil. destruct g1 as [[oo zz] cc].
          reflexivity. }
        destruct (keyi sg g2) as [s2|] eqn:EK2.
        {
          assert (Hph2 : ph sg g2 = true)
            by (unfold ph; rewrite EK2; reflexivity).
          destruct (ph_shape42 sg g2 Hph2) as (K2 & Hg2e). subst g2.
          destruct (flat_ph_head sg (9%N,2%N,K2) t2 s2 EK2 HW)
            as (cb2 & bt2 & EFH2 & HCB2).
          xrewrite EFH2.
          destruct g1 as [[o1 z1] c1].
          change ((4 =? 3)%N) with false.
          destruct (o1 =? 4)%N, (z1 =? 2)%N, (1 <=? c1)%N,
            (2 =? 2)%N, (1 <=? cb2)%N, (1 <=? K2)%N;
            cbn [andb]; reflexivity. }
        assert (Hphg2 : ph sg g2 = false)
          by (unfold ph; rewrite EK2; reflexivity).
        assert (EFg2 : lin_flat sg (g2 :: t2)
                       = g2 :: lin_flat sg t2)
          by (apply flat_cons_nonph; exact Hphg2).
        xrewrite EFg2.
        destruct g1 as [[o1 z1] c1]. destruct g2 as [[o2 z2] c2].
        destruct ((o1 =? 4) && (z1 =? 2) && (1 <=? c1)
                  && (o2 =? 3) && (z2 =? 2) && (c2 =? 1))%N eqn:EC;
          [|reflexivity].
        assert (Ho2 : o2 = 3%N /\ z2 = 2%N /\ c2 = 1%N).
        { pose proof EC as EC2.
          apply andb_prop in EC2. destruct EC2 as [EC2 Ec2].
          apply andb_prop in EC2. destruct EC2 as [EC2 Ez2].
          apply andb_prop in EC2. destruct EC2 as [_ Eo2].
          apply N.eqb_eq in Eo2, Ez2, Ec2. auto. }
        destruct Ho2 as (-> & -> & ->).
        destruct t2 as [|g3 t3].
        {
          flatnil.
          f_equal.
          destruct (1 <? c1)%N; cbn [app];
            repeat first [fsmall HK|plit]; reflexivity. }
        assert (Hphg3 : ph sg g3 = false).
        { destruct (ph sg g3) eqn:EP3; [|reflexivity].
          exfalso.
          destruct (HNt 2%nat g3 eq_refl EP3) as (_ & HL3).
          pose proof (HL3 (3%N,2%N,1%N) ltac:(lia) eq_refl) as HSL.
          unfold is_spc in HSL.
          cbn [gO gZ gC] in HSL.
          discriminate. }
        assert (EFg3 : lin_flat sg (g3 :: t3)
                       = g3 :: lin_flat sg t3)
          by (apply flat_cons_nonph; exact Hphg3).
        xrewrite EFg3.
        destruct g3 as [[o3 z3] c3].
        destruct t3 as [|g4 t4].
        {
          flatnil.
          destruct ((o3 =? 4) && (z3 =? 2))%N eqn:E34; [|reflexivity].
          apply andb_prop in E34. destruct E34 as [Eo3 Ez3].
          apply N.eqb_eq in Eo3, Ez3. subst o3 z3.
          f_equal.
          destruct (1 <? c1)%N; cbn [app];
            repeat first [fsmall HK|plit]; reflexivity. }
        destruct (lin_flat sg (g4 :: t4)) as [|g4' r4] eqn:EF4.
        { exfalso.
          exact (flat_cons_ne sg g4 t4 HW EF4). }
        reflexivity. }
Qed.
Lemma dtb3_cons : forall (g : bg) t,
  dtb3_conv (g :: t)
  = match dtb3_conv t with
    | Some t' => Some (g :: t')
    | None =>
        if ((gO g =? 8) && (gZ g =? 2) && (gC g =? 1))%N
        then match t with
             | (o1,z1,c1) :: t1 =>
                 if ((o1 =? 4) && (z1 =? 2) && (1 <? c1))%N
                    && forallb w42 t1
                 then Some ((7,1,1)%N :: (3,2,1)%N :: (o1,z1,c1-1)%N :: t1)
                 else None
             | [] => None
             end
        else None
    end.
Proof.
  intros g t. destruct g as [[o z] c]. reflexivity.
Qed.
Lemma dtb3_app_skip : forall a gx X',
  (forall g, In g a -> casc g = true) ->
  is_spc gx = true ->
  dtb3_conv (a ++ gx :: X')
  = match dtb3_conv (gx :: X') with
    | Some Y => Some (a ++ Y)
    | None => None
    end.
Proof.
  induction a as [|g a IH]; intros gx X' HC HS.
  - cbn [app]. destruct (dtb3_conv (gx :: X')); reflexivity.
  - cbn [app].
    rewrite (dtb3_cons g (a ++ gx :: X')).
    rewrite (IH gx X')
      by first [exact HS | intros g' H'; exact (HC g' (or_intror H'))].
    destruct (dtb3_conv (gx :: X')) as [Y|].
    { reflexivity. }
    pose proof (HC g (or_introl eq_refl)) as Hcg.
    destruct g as [[o z] c].
    cbn [gO gZ gC].
    destruct ((o =? 8) && (z =? 2) && (c =? 1))%N eqn:E8; [|reflexivity].
    destruct a as [|[[o1 z1] c1] a2].
    + cbn [app].
      destruct gx as [[ox zx] cx].
      assert (Hox : ox = 8%N).
      { unfold is_spc in HS.
        cbn [gO gZ gC] in HS.
        apply andb_prop in HS. destruct HS as [HS' _].
        apply andb_prop in HS'. destruct HS' as [Ho _].
        apply N.eqb_eq in Ho. exact Ho. }
      subst ox.
      change ((8 =? 4)%N) with false.
      cbn [andb]. reflexivity.
    + cbn [app].
      pose proof (HC (o1,z1,c1) (or_intror (or_introl eq_refl))) as Hc1.
      destruct (casc_o48 _ Hc1) as [Ho1|Ho1];
        cbn [gO] in Ho1; subst o1.
      * rewrite (forallb_w42_spc_false a2 gx X' HS).
        rewrite !andb_false_r. reflexivity.
      * change ((8 =? 4)%N) with false.
        cbn [andb]. reflexivity.
Qed.
Lemma dtb3_conv_flat : forall sg cols,
  sg_wf sg -> keys_big sg ->
  ph_nbrs sg cols ->
  dtb3_conv (lin_flat sg cols)
  = match dtb3_conv cols with
    | Some Y => Some (lin_flat sg Y)
    | None => None
    end.
Proof.
  intros sg cols. induction cols as [|g t IH]; intros HW HK HN.
  - reflexivity.
  - pose proof (ph_nbrs_tail sg g t HN) as HNt.
    destruct (keyi sg g) as [s|] eqn:EK.
    +
      assert (Hph : ph sg g = true)
        by (unfold ph; rewrite EK; reflexivity).
      destruct (HN O g eq_refl Hph) as ((gr & Hgr & Hsr) & _).
      cbn [nth_error] in Hgr.
      destruct t as [|g1 t1]; [discriminate|].
      cbn [nth_error] in Hgr. injection Hgr as ->.
      destruct (flat_ph_head sg g (gr :: t1) s EK HW)
        as (cb & bt & EFH & HCB).
      xrewrite EFH.
      assert (EF1 : lin_flat sg (gr :: t1)
                    = gr :: lin_flat sg t1)
        by (apply flat_cons_nonph;
            exact (spc_nonph sg gr Hsr)).
      xrewrite EF1.
      match goal with
      | |- context [dtb3_conv ?T] =>
          unify T (((4%N,2%N,cb) :: bt) ++ gr :: lin_flat sg t1);
          let E := fresh "ESK" in
          assert (E : dtb3_conv T
                      = match dtb3_conv
                              (gr :: lin_flat sg t1) with
                        | Some Y => Some (((4%N,2%N,cb) :: bt) ++ Y)
                        | None => None
                        end)
            by (exact (dtb3_app_skip ((4%N,2%N,cb) :: bt) gr
                         (lin_flat sg t1) HCB Hsr));
          rewrite E; clear E
      end.
      pose proof (IH HW HK HNt) as IHt.
      rewrite EF1 in IHt.
      xrewrite IHt.
      destruct (ph_shape42 sg g Hph) as (K & Hg42). subst g.
      assert (EFlatY : forall Y,
          lin_flat sg ((9%N,2%N,K) :: Y)
          = sFlat s ++ lin_flat sg Y)
        by (intros Y; rewrite lin_flat_cons;
            unfold keyb; rewrite EK; reflexivity).
      assert (EBody : sFlat s = (4%N,2%N,cb) :: bt).
      { apply (app_inv_tail (lin_flat sg (gr :: t1))).
        rewrite <- EFlatY.
        exact EFH. }
      assert (ECOND : dtb3_conv ((9%N,2%N,K) :: gr :: t1)
                      = match dtb3_conv (gr :: t1) with
                        | Some t' => Some ((9%N,2%N,K) :: t')
                        | None => None
                        end) by reflexivity.
      xrewrite ECOND.
      destruct (dtb3_conv (gr :: t1)) as [Y|] eqn:EY.
      * cbv beta iota.
        xrewrite (EFlatY Y). rewrite EBody. reflexivity.
      * cbv beta iota. reflexivity.
    +
      assert (Hphg : ph sg g = false)
        by (unfold ph; rewrite EK; reflexivity).
      assert (EFg : lin_flat sg (g :: t)
                    = g :: lin_flat sg t)
        by (apply flat_cons_nonph; exact Hphg).
      xrewrite EFg.
      xrewrite (dtb3_cons g (lin_flat sg t)).
      xrewrite (dtb3_cons g t).
      pose proof (IH HW HK HNt) as IHt.
      xrewrite IHt.
      destruct (dtb3_conv t) as [Y|] eqn:EY; cbv beta iota.
      { assert (EFY : lin_flat sg (g :: Y)
                      = g :: lin_flat sg Y)
          by (apply flat_cons_nonph; exact Hphg).
        xrewrite EFY. reflexivity. }
      destruct g as [[o z] c].
      cbn [gO gZ gC].
      destruct ((o =? 8) && (z =? 2) && (c =? 1))%N eqn:E8;
        cbv beta iota; [|reflexivity].
      destruct t as [|g1 t1].
      { reflexivity. }
      destruct (keyi sg g1) as [s1|] eqn:EK1.
      {
        assert (Hph1 : ph sg g1 = true)
          by (unfold ph; rewrite EK1; reflexivity).
        destruct (HNt O g1 eq_refl Hph1) as ((gr2 & Hgr2 & Hsr2) & _).
        cbn [nth_error] in Hgr2.
        destruct t1 as [|g2 t2]; [discriminate|].
        cbn [nth_error] in Hgr2. injection Hgr2 as ->.
        destruct (ph_shape42 sg g1 Hph1) as (K1 & Hg1e). subst g1.
        destruct (flat_ph_head sg (9%N,2%N,K1) (gr2 :: t2) s1 EK1 HW)
          as (cb1 & bt1 & EFH1 & HCB1).
        xrewrite EFH1.
        assert (EF2 : lin_flat sg (gr2 :: t2)
                      = gr2 :: lin_flat sg t2)
          by (apply flat_cons_nonph;
              exact (spc_nonph sg gr2 Hsr2)).
        xrewrite EF2.
        rewrite (forallb_w42_spc_false bt1 gr2
                   (lin_flat sg t2) Hsr2).
        assert (ECW : forallb w42 (gr2 :: t2) = false).
        { cbn [forallb]. rewrite (spc_not_w42 gr2 Hsr2). reflexivity. }
        rewrite ECW.
        rewrite !andb_false_r. reflexivity. }
      {
        assert (Hphg1 : ph sg g1 = false)
          by (unfold ph; rewrite EK1; reflexivity).
        assert (EFg1 : lin_flat sg (g1 :: t1)
                       = g1 :: lin_flat sg t1)
          by (apply flat_cons_nonph; exact Hphg1).
        xrewrite EFg1.
        destruct g1 as [[o1 z1] c1].
        rewrite (w42_forallb_flat sg t1 HW (ph_nbrs_tail _ _ _ HNt)
                   (fun p g' Hp Hph' =>
                      proj1 (ph_nbrs_tail _ _ _ HNt p g' Hp Hph'))).
        destruct (((o1 =? 4) && (z1 =? 2) && (1 <? c1))%N
                  && forallb w42 t1) eqn:EC; [|reflexivity].
        apply andb_prop in EC. destruct EC as [EC1 EW].
        assert (Hnp : forall g', In g' t1 -> ph sg g' = false).
        { intros g' Hin.
          destruct (ph sg g') eqn:EP; [|reflexivity].
          exfalso.
          destruct (In_nth_error _ _ Hin) as (q & Hq).
          destruct (proj1 (ph_nbrs_tail _ _ _ HNt q g' Hq EP))
            as (grr & Hgrr & Hsrr).
          eapply forallb_forall in EW;
            [|exact (nth_error_In _ _ Hgrr)].
          rewrite (spc_not_w42 grr Hsrr) in EW. discriminate. }
        apply andb_prop in EC1. destruct EC1 as [EC1' Ec1big].
        apply andb_prop in EC1'. destruct EC1' as [Eo1 Ez1].
        apply N.eqb_eq in Eo1, Ez1. subst o1 z1.
        cbv beta iota.
        rewrite (lin_flat_nonph sg t1 Hnp).
        f_equal.
        flatlit.
        fsmall HK.
        rewrite (lin_flat_nonph sg t1 Hnp).
        reflexivity. }
Qed.
Lemma ph_nbrs_app_r : forall sg a b,
  ph_nbrs sg (a ++ b) -> ph_nbrs sg b.
Proof.
  intros sg a b H p g Hp Hph.
  assert (Hp' : nth_error (a ++ b) (length a + p) = Some g)
    by (rewrite nth_error_app2 by lia;
        replace (length a + p - length a)%nat with p by lia; exact Hp).
  destruct (H (length a + p)%nat g Hp' Hph) as ((gr & Hgr & Hsr) & HL).
  split.
  - exists gr. split; [|exact Hsr].
    rewrite nth_error_app2 in Hgr by lia.
    replace (length a + p + 1 - length a)%nat with (p + 1)%nat in Hgr
      by lia.
    exact Hgr.
  - intros gl Hp1 Hgl.
    apply (HL gl); [lia|].
    rewrite nth_error_app2 by lia.
    replace (length a + p - 1 - length a)%nat with (p - 1)%nat by lia.
    exact Hgl.
Qed.
Lemma ph_nbrs_seek_fst : forall sg r,
  ph_nbrs sg r ->
  ph_nbrs sg (fst (seek r)).
Proof.
  intros sg r H p g Hp Hph.
  pose proof (LineageGuard_seek_split r) as HSp.
  assert (Hp' : nth_error r p = Some g).
  { rewrite HSp. rewrite nth_error_app1; [exact Hp|].
    apply nth_error_Some. rewrite Hp. discriminate. }
  destruct (H p g Hp' Hph) as ((gr & Hgr & Hsr) & HL).
  assert (Hplen : (p < length (fst (seek r)))%nat)
    by (apply nth_error_Some; rewrite Hp; discriminate).
  assert (Hlast : (p + 1 < length (fst (seek r)))%nat \/
                  (p + 1 = length (fst (seek r)))%nat) by lia.
  destruct Hlast as [Hlt|Heq].
  - split.
    + exists gr. split; [|exact Hsr].
      rewrite HSp in Hgr.
      rewrite nth_error_app1 in Hgr by lia.
      exact Hgr.
    + intros gl Hp1 Hgl.
      apply (HL gl); [exact Hp1|].
      rewrite HSp.
      rewrite nth_error_app1 by lia.
      exact Hgl.
  -
    exfalso.
    rewrite HSp in Hgr.
    rewrite nth_error_app2 in Hgr by lia.
    rewrite Heq, PeanoNat.Nat.sub_diag in Hgr.
    destruct (snd (seek r)) as [|gs b] eqn:ES; [discriminate|].
    cbn [nth_error] in Hgr. injection Hgr as E. subst gs.
    pose proof (seek_snd_head r gr b ES) as HT.
    pose proof (casc_seekable gr) as HCS.
    assert (Hcgr : casc gr = true).
    { unfold casc. rewrite Hsr. apply orb_true_r. }
    rewrite (HCS Hcgr) in HT. discriminate.
Qed.
Lemma lgw_step_need : forall sg (g : bg) t before need y,
  lgw sg (g :: t) before (S need) = Some (y, O) ->
  casc g = true /\ ph sg g = false /\
  lgw sg t (S before) need = Some (y, O).
Proof.
  intros sg g t before need y H.
  cbn [lgw] in H.
  destruct (ph sg g) eqn:EP.
  { cbn [orb] in H. discriminate. }
  destruct (casc g) eqn:EC.
  { cbn [orb negb] in H.
    replace (S need - 1)%nat with need in H by lia.
    auto. }
  { cbn [orb negb] in H. discriminate. }
Qed.
Lemma lgw_step_ph : forall sg (g : bg) t before y,
  lgw sg (g :: t) before O = Some (y, O) ->
  ph sg g = true ->
  (GUARD <= before)%nat /\
  lgw sg t O GUARD = Some (y, O).
Proof.
  intros sg g t before y H HP.
  cbn [lgw] in H. rewrite HP in H.
  destruct (Nat.ltb before GUARD) eqn:EB.
  { discriminate. }
  apply PeanoNat.Nat.ltb_ge in EB.
  auto.
Qed.
Lemma lgw_step_casc : forall sg (g : bg) t before y,
  lgw sg (g :: t) before O = Some (y, O) ->
  ph sg g = false ->
  casc g = true ->
  lgw sg t (S before) O = Some (y, O).
Proof.
  intros sg g t before y H HP HC.
  cbn [lgw] in H. rewrite HP, HC in H. exact H.
Qed.
Lemma lgw_step_junk : forall sg (g : bg) t before y,
  lgw sg (g :: t) before O = Some (y, O) ->
  ph sg g = false ->
  casc g = false ->
  lgw sg t O O = Some (y, O).
Proof.
  intros sg g t before y H HP HC.
  cbn [lgw] in H. rewrite HP, HC in H. exact H.
Qed.
Lemma lgw_margins_gen : forall sg w rest j before need y,
  rest = skipn j w ->
  lgw sg rest before need = Some (y, O) ->
  (forall k, (k < before)%nat -> (k < GUARD)%nat ->
     (1 + k <= j)%nat /\
     exists g, nth_error w (j - 1 - k) = Some g /\
               casc g = true /\ ph sg g = false) ->
  forall p gp, nth_error w p = Some gp -> ph sg gp = true ->
    (j <= p)%nat ->
    (GUARD <= p)%nat /\
    (p + GUARD < length w)%nat /\
    (forall r, (p - GUARD <= r)%nat ->
       (r <= p + GUARD)%nat -> r <> p ->
       exists gr, nth_error w r = Some gr /\
                  casc gr = true /\ ph sg gr = false).
Proof.
  intros sg w rest. revert w.
  induction rest as [|g t IH]; intros w j before need y Hrest Hrun HB
    p gp Hp Hph Hjp.
  - exfalso.
    assert (Hlw : (length w <= j)%nat).
    { pose proof (length_skipn j w) as L.
      rewrite <- Hrest in L. cbn [length] in L. lia. }
    assert (Hpl : (p < length w)%nat)
      by (apply nth_error_Some; rewrite Hp; discriminate).
    lia.
  - assert (Hg : nth_error w j = Some g).
    { pose proof (nth_skipn j O w) as L.
      rewrite <- Hrest in L. cbn [nth_error] in L.
      rewrite PeanoNat.Nat.add_0_r in L. exact (eq_sym L). }
    assert (Ht : t = skipn (S j) w).
    { rewrite <- PeanoNat.Nat.add_1_r, <- skipn_skipn, <- Hrest.
      reflexivity. }
    destruct need as [|need'].
    + destruct (ph sg g) eqn:EP.
      * destruct (lgw_step_ph sg g t before y Hrun EP) as (HBge & HW3).
        change GUARD with 3%nat in HW3.
        destruct t as [|c1 t1]; [cbn [lgw] in HW3; congruence|].
        destruct (lgw_step_need sg c1 t1 O 2 y HW3)
          as (Hc1 & Hpc1 & HW2).
        assert (Ht1 : t1 = skipn (S (S j)) w).
        { pose proof (f_equal (skipn 1) Ht) as E2.
          rewrite skipn_skipn in E2.
          replace (S j + 1)%nat with (S (S j)) in E2 by lia.
          cbn [skipn] in E2. exact E2. }
        destruct t1 as [|c2 t2]; [cbn [lgw] in HW2; congruence|].
        destruct (lgw_step_need sg c2 t2 1 1 y HW2)
          as (Hc2 & Hpc2 & HW1).
        assert (Ht2 : t2 = skipn (S (S (S j))) w).
        { pose proof (f_equal (skipn 1) Ht1) as E2.
          rewrite skipn_skipn in E2.
          replace (S (S j) + 1)%nat with (S (S (S j))) in E2 by lia.
          cbn [skipn] in E2. exact E2. }
        destruct t2 as [|c3 t3]; [cbn [lgw] in HW1; congruence|].
        destruct (lgw_step_need sg c3 t3 2 O y HW1)
          as (Hc3 & Hpc3 & HW0).
        assert (Hn1 : nth_error w (S j) = Some c1).
        { pose proof (nth_skipn (S j) O w) as L.
          rewrite <- Ht in L. cbn [nth_error] in L.
          rewrite PeanoNat.Nat.add_0_r in L. exact (eq_sym L). }
        assert (Hn2 : nth_error w (S (S j)) = Some c2).
        { pose proof (nth_skipn (S (S j)) O w) as L.
          rewrite <- Ht1 in L. cbn [nth_error] in L.
          rewrite PeanoNat.Nat.add_0_r in L. exact (eq_sym L). }
        assert (Hn3 : nth_error w (S (S (S j))) = Some c3).
        { pose proof (nth_skipn (S (S (S j))) O w) as L.
          rewrite <- Ht2 in L. cbn [nth_error] in L.
          rewrite PeanoNat.Nat.add_0_r in L. exact (eq_sym L). }
        destruct (PeanoNat.Nat.eq_dec p j) as [->|Hne].
        { assert (H3j : (3 <= j)%nat).
          { destruct (HB 2%nat) as (Hj2 & _);
              [unfold GUARD in HBge; lia
              |unfold GUARD; lia|lia]. }
          split; [unfold GUARD; lia|].
          split.
          { assert (Hb3 : (S (S (S j)) < length w)%nat)
              by (apply nth_error_Some; rewrite Hn3; discriminate).
            unfold GUARD. lia. }
          intros r Hr1 Hr2 Hrne.
          destruct (PeanoNat.Nat.lt_ge_cases r j) as [Hrlt|Hrge].
          { destruct (HB (j - 1 - r)%nat) as (_ & gk & Hgk & Hck & Hpk);
              [unfold GUARD in *; lia
              |unfold GUARD in *; lia|].
            replace (j - 1 - (j - 1 - r))%nat with r in Hgk
              by (unfold GUARD in *; lia).
            eauto. }
          { assert (HR : r = S j \/ r = S (S j) \/ r = S (S (S j)))
              by (unfold GUARD in *; lia).
            destruct HR as [HR|[HR|HR]]; subst r; eauto. } }
        { assert (HB0 : forall k, (k < O)%nat ->
                    (k < GUARD)%nat ->
                    (1 + k <= S j)%nat /\
                    exists g0, nth_error w (S j - 1 - k) = Some g0 /\
                      casc g0 = true /\
                      ph sg g0 = false)
            by (intros k Hk _; lia).
          assert (Hjp' : (S j <= p)%nat) by lia.
          exact (IH w (S j) O 3%nat y Ht HW3 HB0 p gp Hp Hph Hjp'). }
      *
        assert (Hpj : p <> j).
        { intro E. subst p. rewrite Hp in Hg.
          injection Hg as E. subst gp. congruence. }
        assert (Hjp' : (S j <= p)%nat) by lia.
        destruct (casc g) eqn:EC.
        { pose proof (lgw_step_casc sg g t before y Hrun EP EC) as HWt.
          assert (HB' : forall k, (k < S before)%nat ->
                     (k < GUARD)%nat ->
                     (1 + k <= S j)%nat /\
                     exists g0, nth_error w (S j - 1 - k) = Some g0 /\
                       casc g0 = true /\
                       ph sg g0 = false).
          { intros k Hk1 Hk2.
            destruct k as [|k'].
            - split; [lia|].
              exists g.
              replace (S j - 1 - 0)%nat with j by lia.
              auto.
            - destruct (HB k') as (Hk3 & g0 & Hg0 & Hc0 & Hp0);
                [lia|unfold GUARD in *; lia|].
              split; [lia|].
              exists g0.
              replace (S j - 1 - S k')%nat with (j - 1 - k')%nat by lia.
              auto. }
          exact (IH w (S j) (S before) O y Ht HWt HB' p gp Hp Hph
                   Hjp'). }
        { pose proof (lgw_step_junk sg g t before y Hrun EP EC) as HWt.
          assert (HB0 : forall k, (k < O)%nat ->
                     (k < GUARD)%nat ->
                     (1 + k <= S j)%nat /\
                     exists g0, nth_error w (S j - 1 - k) = Some g0 /\
                       casc g0 = true /\
                       ph sg g0 = false)
            by (intros k Hk _; lia).
          exact (IH w (S j) O O y Ht HWt HB0 p gp Hp Hph Hjp'). }
    +
      destruct (lgw_step_need sg g t before need' y Hrun)
        as (HCg & HPg & HWt).
      assert (Hpj : p <> j).
      { intro E. subst p. rewrite Hp in Hg.
        injection Hg as E. subst gp. congruence. }
      assert (Hjp' : (S j <= p)%nat) by lia.
      assert (HB' : forall k, (k < S before)%nat ->
                 (k < GUARD)%nat ->
                 (1 + k <= S j)%nat /\
                 exists g0, nth_error w (S j - 1 - k) = Some g0 /\
                   casc g0 = true /\
                   ph sg g0 = false).
      { intros k Hk1 Hk2.
        destruct k as [|k'].
        - split; [lia|].
          exists g.
          replace (S j - 1 - 0)%nat with j by lia.
          auto.
        - destruct (HB k') as (Hk3 & g0 & Hg0 & Hc0 & Hp0);
            [lia|unfold GUARD in *; lia|].
          split; [lia|].
          exists g0.
          replace (S j - 1 - S k')%nat with (j - 1 - k')%nat by lia.
          auto. }
      exact (IH w (S j) (S before) need' y Ht HWt HB' p gp Hp Hph
               Hjp').
Qed.
Theorem lguard_margins : forall sg w,
  lin_guard sg w = true -> ph_margins sg w.
Proof.
  intros sg w HG.
  unfold lin_guard in HG.
  rewrite lguard_lgw in HG.
  destruct (lgw sg w O O) as [[y n']|] eqn:EW; [|discriminate].
  apply PeanoNat.Nat.eqb_eq in HG. subst n'.
  intros p gp Hp Hph.
  exact (lgw_margins_gen sg w w O O O y eq_refl EW
           (fun k Hk _ => ltac:(lia)) p gp Hp Hph ltac:(lia)).
Qed.
Lemma flat_firstn_skipn : forall sg u j,
  lin_flat sg u
  = lin_flat sg (firstn j u) ++ lin_flat sg (skipn j u).
Proof.
  intros sg u j.
  rewrite <- lin_flat_app_c.
  rewrite firstn_skipn. reflexivity.
Qed.
Lemma flat_skipn : forall sg u j,
  lin_flat sg (skipn j u)
  = skipn (length (lin_flat sg (firstn j u)))
      (lin_flat sg u).
Proof.
  intros sg u j.
  rewrite (flat_firstn_skipn sg u j).
  rewrite skipn_app.
  rewrite PeanoNat.Nat.sub_diag.
  assert (E1 : skipn (length (lin_flat sg (firstn j u)))
                 (lin_flat sg (firstn j u)) = [])
    by (apply skipn_all2; lia).
  rewrite E1.
  cbn [app skipn]. reflexivity.
Qed.
Lemma flat_firstn : forall sg u j,
  lin_flat sg (firstn j u)
  = firstn (length (lin_flat sg (firstn j u)))
      (lin_flat sg u).
Proof.
  intros sg u j.
  rewrite (flat_firstn_skipn sg u j).
  rewrite firstn_app.
  rewrite PeanoNat.Nat.sub_diag.
  assert (E1 : firstn (length (lin_flat sg (firstn j u)))
                 (lin_flat sg (firstn j u))
               = lin_flat sg (firstn j u))
    by (apply firstn_all2; lia).
  rewrite E1.
  cbn [firstn]. rewrite app_nil_r. reflexivity.
Qed.
Lemma tick_target_s_flat : forall sg w j jf,
  sg_wf sg ->
  tick_target_s (lin_flat sg w) jf
  = match tick_target_s w j with
    | Some i =>
        Some (jf + length (lin_flat sg (firstn (i - j)%nat w)))%nat
    | None => None
    end.
Proof.
  intros sg w. induction w as [|g t IH]; intros j jf HW; [reflexivity|].
  rewrite lin_flat_cons.
  unfold keyb.
  destruct (keyi sg g) as [s|] eqn:EK.
  - destruct (keyi_in sg g s EK) as (Hin & Hlv & _).
    destruct (sg_wf_seg sg s HW Hin) as [HC HOk].
    cbn [tick_target_s].
    assert (HZg : gZ g = 2%N) by exact (proj2 (phshape_o g Hlv)).
    rewrite HZg.
    change (((2 =? 1) || (3 <=? 2))%N) with false.
    cbv beta iota.
    assert (HNC : is_cmf g = false) by exact (phshape_not_cmf g Hlv).
    rewrite HNC.
    assert (HIC : is_col g = true) by exact (phshape_is_col g Hlv).
    rewrite HIC.
    assert (HA : forall a w0 j0,
       (forall g0, In g0 a -> gZ g0 = 2%N /\
          is_cmf g0 = false /\ is_col g0 = true) ->
       tick_target_s (a ++ w0) j0
       = tick_target_s w0 (j0 + length a)%nat).
    { induction a as [|g0 a IHa]; intros w0 j0 HZ.
      - cbn [app]. rewrite PeanoNat.Nat.add_0_r. reflexivity.
      - cbn [app tick_target_s].
        destruct (HZ g0 (or_introl eq_refl)) as (HZ0 & HC0 & HL0).
        rewrite HZ0.
        change (((2 =? 1) || (3 <=? 2))%N) with false.
        cbv beta iota.
        rewrite HC0, HL0.
        rewrite IHa by (intros g' H'; exact (HZ g' (or_intror H'))).
        cbn [length].
        replace (j0 + S (length a))%nat with (S j0 + length a)%nat
          by lia.
        reflexivity. }
    rewrite (HA (sFlat s) _ jf)
      by (intros g' H';
          exact (conj (sflat_z2 s g' HOk H')
                   (conj (sflat_not_cmf s g' HOk H')
                      (sflat_is_col s g' HOk H')))).
    rewrite (IH (S j) (jf + length (sFlat s))%nat HW).
    destruct (tick_target_s t (S j)) as [i|] eqn:EF; [|reflexivity].
    f_equal.
    assert (Hlb : (S j <= i)%nat).
    { clear - EF. revert j i EF.
      induction t as [|g0 t IHt]; intros j i H; [discriminate|].
      cbn [tick_target_s] in H.
      destruct ((gZ g0 =? 1) || (3 <=? gZ g0))%N.
      - injection H as <-. lia.
      - destruct (is_cmf g0).
        + injection H as <-. lia.
        + destruct (is_col g0); [|discriminate].
          pose proof (IHt (S j) i H). lia. }
    replace (i - j)%nat with (S (i - S j))%nat by lia.
    cbn [firstn]. rewrite lin_flat_cons.
    unfold keyb. rewrite EK. rewrite length_app. lia.
  - cbn [tick_target_s].
    destruct ((gZ g =? 1) || (3 <=? gZ g))%N eqn:EA;
      cbv beta iota.
    + rewrite PeanoNat.Nat.sub_diag.
      cbn [firstn lin_flat length].
      f_equal. lia.
    + destruct (is_cmf g) eqn:EC.
      { rewrite PeanoNat.Nat.sub_diag.
        cbn [firstn lin_flat length].
        f_equal. lia. }
      destruct (is_col g) eqn:EL; [|reflexivity].
      rewrite (IH (S j) (S jf) HW).
      destruct (tick_target_s t (S j)) as [i|] eqn:EF;
        [|reflexivity].
      f_equal.
      assert (Hlb : (S j <= i)%nat).
      { clear - EF. revert j i EF.
        induction t as [|g0 t IHt]; intros j i H; [discriminate|].
        cbn [tick_target_s] in H.
        destruct ((gZ g0 =? 1) || (3 <=? gZ g0))%N.
        - injection H as <-. lia.
        - destruct (is_cmf g0).
          + injection H as <-. lia.
          + destruct (is_col g0); [|discriminate].
            pose proof (IHt (S j) i H). lia. }
      replace (i - j)%nat with (S (i - S j))%nat by lia.
      cbn [firstn]. rewrite lin_flat_cons.
      unfold keyb. rewrite EK. cbn [length]. lia.
Qed.
Lemma z31_noncasc : forall (X : N), casc (X, 3%N, 1%N) = false.
Proof.
  intros X.
  unfold casc, is_lvl, is_spc.
  cbn [gO gZ gC].
  change ((3 =? 2)%N) with false.
  rewrite !andb_false_r. reflexivity.
Qed.
Lemma ph_nbrs_cons : forall sg (h : bg) cols,
  ph sg h = false ->
  (forall g, cols = g :: (List.tl cols) -> ph sg g = false) ->
  ph_nbrs sg cols ->
  ph_nbrs sg (h :: cols).
Proof.
  intros sg h cols Hh Hc0 HN p g Hp Hph.
  destruct p as [|p'].
  { cbn [nth_error] in Hp. injection Hp as E. subst g. congruence. }
  cbn [nth_error] in Hp.
  destruct (HN p' g Hp Hph) as ((gr & Hgr & Hsr) & HL).
  split.
  { exists gr. split; [|exact Hsr].
    replace (S p' + 1)%nat with (S (p' + 1)) by lia.
    cbn [nth_error]. exact Hgr. }
  intros gl Hp1 Hgl.
  destruct p' as [|p''].
  {
    exfalso.
    destruct cols as [|c_0 ct]; [discriminate|].
    cbn [nth_error] in Hp. injection Hp as E. subst g.
    rewrite (Hc0 c_0 eq_refl) in Hph. discriminate. }
  apply (HL gl); [lia|].
  replace (S (S p'') - 1)%nat with (S (S p'' - 1)) in Hgl by lia.
  cbn [nth_error] in Hgl.
  exact Hgl.
Qed.
Lemma spc_casc : forall g,
  is_spc g = true -> casc g = true.
Proof.
  intros g H. unfold casc. rewrite H. apply orb_true_r.
Qed.
Definition ph_notlast (sg : list seg) (cols : word) : Prop :=
  forall p g, nth_error cols p = Some g -> ph sg g = true ->
    (p + 1 < length cols)%nat.
Definition sg_live (sg : list seg) : Prop :=
  forall s, In s sg ->
    existsb (fun g => negb (gC g =? 0)%N) (sFlat s) = true.
Lemma existsb_neg_forallb : forall (p : bg -> bool) l,
  existsb (fun g => negb (p g)) l = true -> forallb p l = false.
Proof.
  induction l as [|g t IH]; intros H; [discriminate|].
  cbn in H |- *.
  apply orb_prop in H. destruct H as [H|H].
  - destruct (p g); [discriminate|reflexivity].
  - rewrite (IH H). apply andb_false_r.
Qed.
Lemma gc0_forallb_flat : forall sg w,
  keys_big sg -> sg_live sg ->
  forallb (fun g => (gC g =? 0)%N) (lin_flat sg w)
  = forallb (fun g => (gC g =? 0)%N) w.
Proof.
  intros sg w HK HL. induction w as [|g t IH]; [reflexivity|].
  rewrite lin_flat_cons.
  unfold keyb.
  destruct (keyi sg g) as [s|] eqn:EK.
  - destruct (keyi_in sg g s EK) as (Hin & Hlv & Hc).
    rewrite forallb_app.
    rewrite (existsb_neg_forallb _ _ (HL s Hin)).
    cbn [forallb].
    assert (Hgc : (gC g =? 0)%N = false).
    { apply N.eqb_neq. rewrite Hc.
      pose proof (HK s Hin) as HB.
      unfold KMAGIC in HB. lia. }
    rewrite Hgc. reflexivity.
  - cbn [forallb]. rewrite IH. reflexivity.
Qed.
Lemma flat_cons_ex : forall sg g t,
  sg_wf sg ->
  exists h u, lin_flat sg (g :: t) = h :: u.
Proof.
  intros sg g t HW.
  rewrite lin_flat_cons.
  unfold keyb.
  destruct (keyi sg g) as [s|] eqn:EK.
  - destruct (keyi_in sg g s EK) as (Hin & _ & _).
    destruct (sg_wf_seg sg s HW Hin) as [HC HOk].
    unfold segok in HOk. cbv zeta in HOk.
    destruct (sBody s) as [|g0 b] eqn:EB; [discriminate|].
    unfold sFlat, matb. rewrite EB.
    cbn [map app].
    do 2 eexists. reflexivity.
  - do 2 eexists. reflexivity.
Qed.
Lemma sand_leaf_flat : forall sg s,
  sg_wf sg ->
  (forall g t, s = g :: t -> ph sg g = false) ->
  sand_leaf (lin_flat sg s) = sand_leaf s.
Proof.
  intros sg s HW Hh.
  destruct s as [|g t]; [reflexivity|].
  assert (EF : lin_flat sg (g :: t) = g :: lin_flat sg t)
    by (apply flat_cons_nonph; exact (Hh g t eq_refl)).
  rewrite EF.
  destruct t as [|h u]; [reflexivity|].
  destruct (flat_cons_ex sg h u HW) as (h' & u' & EF2).
  rewrite EF2.
  destruct g as [[go gz] gc].
  reflexivity.
Qed.
Lemma nth_last : forall (l : word) d,
  l <> [] -> nth (length l - 1) l d = last l d.
Proof.
  induction l as [|a l IH]; intros d Hne; [congruence|].
  destruct l as [|b l2]; [reflexivity|].
  cbn [length].
  replace (S (S (length l2)) - 1)%nat with (S (S (length l2) - 1))
    by lia.
  cbn [nth last].
  exact (IH d ltac:(discriminate)).
Qed.
Lemma sflat_last_lvl : forall s,
  segcache s = true -> segok s = true ->
  exists ini2 a2, sFlat s = ini2 ++ [a2] /\
    is_lvl a2 = true.
Proof.
  intros s HC HOk.
  unfold segok in HOk. cbv zeta in HOk.
  destruct (sBody s) as [|g0 b] eqn:EB; [discriminate|].
  apply andb_prop in HOk; destruct HOk as [HOk H5].
  apply andb_prop in HOk; destruct HOk as [HOk H4].
  apply andb_prop in HOk; destruct HOk as [HOk H3].
  apply andb_prop in HOk; destruct HOk as [H1 H2].
  unfold segcache in HC. apply PeanoNat.Nat.eqb_eq in HC.
  assert (HLb : length (sBody s) = sLen s).
  { unfold sBody. rewrite length_app, length_rev. lia. }
  rewrite EB in HLb.
  assert (H2' : is_lvl (last (g0 :: b) d0) = true).
  { rewrite <- (nth_last (g0 :: b) d0 ltac:(discriminate)).
    rewrite <- HLb in H2. exact H2. }
  pose proof (app_removelast_last d0
                (l := g0 :: b) ltac:(discriminate)) as ERL.
  exists (List.map (adjk (sPend s)) (removelast (g0 :: b))),
         (adjk (sPend s) (last (g0 :: b) d0)).
  split.
  { unfold sFlat, matb. rewrite EB.
    transitivity (List.map (adjk (sPend s))
                    (removelast (g0 :: b) ++ [last (g0 :: b) d0])).
    { f_equal. exact ERL. }
    rewrite map_app. cbn [map]. reflexivity. }
  destruct (last (g0 :: b) d0) as [[xo xz] xc].
  unfold is_lvl in H2'. cbn [gO gZ] in H2'.
  apply andb_prop in H2'. destruct H2' as [Ho Hz].
  apply N.eqb_eq in Ho, Hz. subst xo xz.
  unfold adjk.
  cbn [gO gZ].
  change (((4 =? 4) && (2 =? 2))%N) with true.
  cbv beta iota.
  unfold is_lvl. cbn [gO gZ]. reflexivity.
Qed.
Lemma ph_notlast_seek : forall sg r,
  ph_nbrs sg r ->
  ph_notlast sg (fst (seek r)).
Proof.
  intros sg r HN p g Hp Hph.
  pose proof (LineageGuard_seek_split r) as HSp.
  assert (Hplen : (p < length (fst (seek r)))%nat)
    by (apply nth_error_Some; rewrite Hp; discriminate).
  destruct (PeanoNat.Nat.lt_ge_cases (p + 1)
              (length (fst (seek r)))) as [Hlt|Hge];
    [exact Hlt|exfalso].
  assert (Hpe : (p + 1 = length (fst (seek r)))%nat) by lia.
  assert (Hp' : nth_error r p = Some g)
    by (rewrite HSp; rewrite nth_error_app1 by lia; exact Hp).
  destruct (HN p g Hp' Hph) as ((gr & Hgr & Hsr) & _).
  rewrite HSp in Hgr.
  rewrite nth_error_app2 in Hgr by lia.
  rewrite Hpe, PeanoNat.Nat.sub_diag in Hgr.
  destruct (snd (seek r)) as [|gs b] eqn:ESnd.
  - cbn [nth_error] in Hgr. discriminate.
  - cbn [nth_error] in Hgr. injection Hgr as <-.
    pose proof (seek_snd_head r gs b ESnd) as Hst.
    rewrite (casc_seekable gs (spc_casc gs Hsr)) in Hst.
    discriminate.
Qed.
Lemma flat_nilb : forall sg w,
  sg_wf sg ->
  (match lin_flat sg w with [] => true | _ :: _ => false end)
  = (match w with [] => true | _ :: _ => false end).
Proof.
  intros sg w HW.
  destruct w as [|g t]; [reflexivity|].
  destruct (flat_cons_ex sg g t HW) as (h & u & E).
  rewrite E. reflexivity.
Qed.
Lemma list_split_last2 : forall (t : word) (g1 g2 : bg),
  exists ini a b, g1 :: g2 :: t = ini ++ [a; b].
Proof.
  induction t as [|g3 t IH]; intros g1 g2.
  - exists ([] : word), g1, g2. reflexivity.
  - destruct (IH g2 g3) as (ini & a & b & E).
    exists (g1 :: ini), a, b. cbn [app]. f_equal. exact E.
Qed.
Lemma flat_cons_key : forall sg g sa t,
  keyi sg g = Some sa ->
  lin_flat sg (g :: t) = sFlat sa ++ lin_flat sg t.
Proof.
  intros sg g sa t EK.
  rewrite lin_flat_cons.
  unfold keyb. rewrite EK. reflexivity.
Qed.
Lemma lawR_wrap : forall sg cols B,
  sg_wf sg -> keys_big sg ->
  ph_notlast sg cols ->
  lawR_seg (lin_flat sg cols) B
  = match lawR_seg cols B with
    | Some seg2 => Some (lin_flat sg seg2)
    | None => None
    end.
Proof.
  intros sg cols B HW HK HP.
  destruct cols as [|g1 [|g2 t]].
  { reflexivity. }
  { assert (Hg : ph sg g1 = false).
    { destruct (ph sg g1) eqn:E; [|reflexivity].
      pose proof (HP O g1 eq_refl E) as HL. cbn [length] in HL. lia. }
    rewrite (flat_cons_nonph sg g1 [] Hg).
    reflexivity. }
  destruct (list_split_last2 t g1 g2) as (ini & a & b & ECols).
  rewrite ECols in HP |- *.
  assert (Hb : ph sg b = false).
  { destruct (ph sg b) eqn:E; [|reflexivity].
    exfalso.
    assert (Hnb : nth_error (ini ++ [a; b]) (length ini + 1)%nat = Some b)
      by (rewrite nth_error_app2 by lia;
          replace (length ini + 1 - length ini)%nat with 1%nat by lia;
          reflexivity).
    pose proof (HP _ _ Hnb E) as HL.
    rewrite length_app in HL. cbn [length] in HL. lia. }
  destruct (ph sg a) eqn:EPa.
  2:{ exact (lawR_seg_flat sg ini a b B HK EPa Hb). }
  unfold ph in EPa.
  destruct (keyi sg a) as [sa|] eqn:EKa; [|discriminate].
  destruct (keyi_in sg a sa EKa) as (Hin & Hlv & Hkey).
  destruct (sg_wf_seg sg sa HW Hin) as [HCa HOka].
  destruct (sflat_last_lvl sa HCa HOka) as (ini2 & a2 & ESF & Hlvl2).
  destruct a as [[ao az] ac].
  destruct (phshape_o _ Hlv) as [Hao Haz].
  cbn [gO gZ] in Hao, Haz. subst ao az.
  destruct a2 as [[o2 z2] c2].
  unfold is_lvl in Hlvl2. cbn [gO gZ] in Hlvl2.
  apply andb_prop in Hlvl2. destruct Hlvl2 as [Ho2 Hz2].
  apply N.eqb_eq in Ho2, Hz2. subst o2 z2.
  destruct b as [[bo bz] bc].
  assert (EFLAT : lin_flat sg (ini ++ [(9%N,2%N,ac); (bo,bz,bc)])
                  = (lin_flat sg ini ++ ini2)
                    ++ [(4%N,2%N,c2); (bo,bz,bc)]).
  { rewrite lin_flat_app_c.
    rewrite (flat_cons_key sg _ sa _ EKa).
    assert (EFB : lin_flat sg ((bo,bz,bc) :: @nil bg)
                  = (bo,bz,bc) :: @nil bg)
      by (exact (flat_cons_nonph sg (bo,bz,bc)
                   (@nil bg) Hb)).
    xrewrite EFB.
    rewrite ESF.
    rewrite <- !app_assoc. cbn [app]. reflexivity. }
  xrewrite EFLAT.
  unfold lawR_seg.
  rewrite !LineageGuard_last2_app.
  cbv beta iota.
  change ((9 =? 8)%N) with false.
  cbn [andb].
  destruct ((bo =? 8) && (bz =? 2) && (bc =? 1))%N eqn:EB2;
    [|reflexivity].
  f_equal.
  destruct (1 <? B)%N eqn:E1B.
  - rewrite !lin_flat_app_c.
    rewrite (flat_cons_key sg _ sa _ EKa).
    repeat first [fsmall HK|plit].
    rewrite ESF.
    rewrite <- !app_assoc. cbn [app]. reflexivity.
  - rewrite !lin_flat_app_c.
    rewrite (flat_cons_key sg _ sa _ EKa).
    repeat first [fsmall HK|plit].
    rewrite ESF.
    rewrite <- !app_assoc. cbn [app]. reflexivity.
Qed.
