  cbv beta iota.
  change ((9 =? 8)%N) with false.
  cbn [andb].
  destruct ((bo =? 8) && (bz =? 2) && (bc =? 1) && (2 <=? f))%N eqn:EB2;
    [|reflexivity].
  f_equal.
  rewrite !lin_flat_app_c.
  rewrite (flat_cons_key sg _ sa _ EKa).
  repeat first [fsmall HK|plit].
  rewrite ESF.
  rewrite <- !app_assoc. cbn [app]. reflexivity.
Qed.
