Lemma nth_skipn_cons : forall (w : word) p g,
  nth_error w p = Some g -> skipn p w = g :: skipn (S p) w.
Proof.
  induction w as [|a w IH]; intros p g H.
  - destruct p; discriminate.
  - destruct p as [|p'].
    + cbn in H |- *. injection H as <-. reflexivity.
    + cbn in H |- *. exact (IH p' g H).
Qed.
Lemma tts_spec : forall (w : word) j i,
  tick_target_s w j = Some i ->
  (j <= i)%nat /\
  exists gt, nth_error w (i - j) = Some gt /\
             casc gt = false /\ notag gt = true.
Proof.
  induction w as [|g t IH]; intros j i H; [discriminate|].
  cbn in H.
  destruct ((gZ g =? 1) || (3 <=? gZ g))%N eqn:EZ.
  { injection H as <-. split; [lia|].
    exists g. rewrite PeanoNat.Nat.sub_diag. cbn.
    split; [reflexivity|].
    assert (Hz : (gZ g =? 2)%N = false).
    { apply N.eqb_neq. apply orb_prop in EZ.
      destruct EZ as [E|E]; [apply N.eqb_eq in E|apply N.leb_le in E];
        lia. }
    destruct g as [[og zg] cg]. cbn [gZ] in Hz.
    split.
    - unfold casc, is_lvl, is_spc.
      cbn [gO gZ gC].
      rewrite Hz. rewrite !andb_false_r. cbn [andb orb]. reflexivity.
    - unfold notag. rewrite (phshape_znot2 og zg cg Hz). reflexivity. }
  destruct (is_cmf g) eqn:EC.
  { injection H as <-. split; [lia|].
    exists g. rewrite PeanoNat.Nat.sub_diag. cbn.
    split; [reflexivity|].
    split.
    - destruct (casc g) eqn:ECs; [|reflexivity].
      rewrite (casc_not_cmf g ECs) in EC. discriminate.
    - exact (cmf_notag g EC). }
  destruct (is_col g) eqn:ECl; [|discriminate].
  destruct (IH (S j) i H) as (Hge & gt & Hnth & Hcs & Hnt).
  split; [lia|].
  exists gt. split; [|exact (conj Hcs Hnt)].
  replace (i - j)%nat with (S (i - S j)) by lia.
  cbn. exact Hnth.
Qed.
Ltac pfxpush HK :=
  cbn [flat_res]; f_equal; f_equal;
  repeat first [fsmall HK|flatc HK|plit];
  rewrite ?lin_flat_app_c;
  rewrite <- ?app_assoc; cbn [app];
  repeat first [fsmall HK|flatc HK|plit];
  try reflexivity.
Lemma flat_len_ge : forall sg w,
  sg_wf sg ->
  (length w <= length (lin_flat sg w))%nat.
Proof.
  intros sg w HW. induction w as [|g t IH]; [cbn; lia|].
  rewrite lin_flat_cons.
  unfold keyb.
  destruct (keyi sg g) as [s|] eqn:EK.
  - destruct (keyi_in sg g s EK) as (Hin & _ & _).
    destruct (sg_wf_seg sg s HW Hin) as [HC HOk].
    unfold segok in HOk. cbv zeta in HOk.
    destruct (sBody s) as [|g0 b] eqn:EB; [discriminate|].
    rewrite length_app.
    unfold sFlat, matb. rewrite EB.
    cbn [List.map length]. cbn [length]. lia.
  - cbn [length]. lia.
Qed.
Lemma seek_snd_len : forall r,
  (length (snd (seek r)) <= length r)%nat.
Proof.
  intros r.
  pose proof (LineageGuard_seek_split r) as HS.
  rewrite HS at 2.
  rewrite length_app. lia.
Qed.
Lemma deliver_z1_sat : forall n m w f j (o c : N),
  (1 <= n)%nat -> (1 <= m)%nat ->
  wat w j = Some (o, 1%N, c) ->
  deliver_tick n w f j true = deliver_tick m w f j true.
Proof.
  intros n m w f j o c Hn Hm HW.
  destruct n as [|n]; [lia|].
  destruct m as [|m]; [lia|].
  cbn [deliver_tick].
  rewrite HW.
  reflexivity.
Qed.
Lemma fire_renew_sat : forall k,
  (forall s f n m, (length s <= k)%nat ->
     (length s <= n)%nat -> (length s <= m)%nat ->
     fire_comp n s f = fire_comp m s f)
  /\ (forall cols s f n m, (length s <= k)%nat ->
     (length s <= n)%nat -> (length s <= m)%nat ->
     renew_seg n cols s f = renew_seg m cols s f).
Proof.
  induction k as [|k IH].
  { split.
    - intros s f n m Hk Hn Hm.
      destruct s; [|cbn in Hk; lia].
      destruct n, m; reflexivity.
    - intros cols s f n m Hk Hn Hm.
      destruct s; [|cbn in Hk; lia].
      destruct n, m; reflexivity. }
  destruct IH as [IHf IHr].
  split.
  - intros s f n m Hk Hn Hm.
    destruct s as [|[[X z] c] rest0].
    { destruct n, m; reflexivity. }
    cbn [length] in Hk, Hn, Hm.
    destruct n as [|n]; [lia|]. destruct m as [|m]; [lia|].
    cbn [fire_comp].
    destruct z as [|[zp|zp|]]; try reflexivity.
    destruct zp as [zp'|zp'|]; try reflexivity.
    destruct c as [|[cp|cp|]]; try reflexivity.
    destruct (negb (5 <=? X))%N; [reflexivity|].
    cbv beta iota.
    destruct rest0 as [|[[Y zY] cY] rest]; [reflexivity|].
    cbn [length] in Hk, Hn, Hm.
    destruct ((Y =? 4) && (zY =? 2))%N eqn:EY4.
    2:{ cbv beta iota.
        destruct ((Y =? 8) && (zY =? 2) && (cY =? 1))%N eqn:EY8.
        {
          cbv beta iota zeta.
          destruct (tick_target
                      ((X-1,1,1) :: (11,2,1) :: rest)%N 2%nat)
            as [j|]; [|reflexivity].
          cbv beta iota.
          destruct (wat ((X-1,1,1) :: (11,2,1) :: rest)%N j)
            as [[[ow zw] cw]|] eqn:EWs; [|reflexivity].
          cbv beta iota.
          destruct (zw =? 1)%N eqn:EZ1; [|reflexivity].
          cbv beta iota.
          apply N.eqb_eq in EZ1. subst zw.
          rewrite (deliver_z1_sat n m _ f j ow cw
                     ltac:(lia) ltac:(lia) EWs).
          reflexivity. }
        reflexivity. }
    cbv beta iota.
    destruct (negb (1 <=? cY))%N; [reflexivity|].
    cbv beta iota.
    destruct rest as [|gr1 rest']; [reflexivity|].
    cbn [length] in Hk, Hn, Hm.
    destruct (seek (gr1 :: rest')) as [cols s2] eqn:ESK.
    cbv beta iota.
    assert (HL2 : (length s2 <= S (length rest'))%nat).
    { pose proof (seek_snd_len (gr1 :: rest')) as H0.
      rewrite ESK in H0. cbn [snd length] in H0. exact H0. }
    destruct s2 as [|[[o4 z4] c4] s2t]; [reflexivity|].
    cbn [length] in HL2.
    destruct ((o4 =? 4) && (z4 =? 3) && (c4 =? 1))%N eqn:E43.
    { cbv beta iota.
      destruct s2t as [|[[o5 z5] B] rest2]; [reflexivity|].
      cbn [length] in HL2.
      destruct ((o5 =? 4) && (z5 =? 2))%N; [|reflexivity].
      cbv beta iota.
      destruct (1 <=? B)%N; [|reflexivity].
      cbv beta iota.
      destruct rest2 as [|gr2 rest2t]; [reflexivity|].
      cbn [length] in HL2.
      destruct (jump_seg cols B); [|reflexivity].
      cbv beta iota.
      destruct (seek (gr2 :: rest2t)) as [cols2 s3] eqn:ESK2.
      assert (HL3 : (length s3 <= S (length rest2t))%nat).
      { pose proof (seek_snd_len (gr2 :: rest2t)) as H0.
        rewrite ESK2 in H0. cbn [snd length] in H0. exact H0. }
      rewrite (IHr cols2 s3 f n m ltac:(lia) ltac:(lia) ltac:(lia)).
      destruct (renew_seg m cols2 s3 f) as [[body f']|];
        [reflexivity|].
      rewrite (IHf s3 f n m ltac:(lia) ltac:(lia) ltac:(lia)).
      reflexivity. }
    destruct ((o4 =? 4) && (z4 =? 4) && (c4 =? 1))%N; [reflexivity|].
    cbv beta iota.
    rewrite (IHf ((o4,z4,c4) :: s2t) f n m
               ltac:(cbn [length]; lia) ltac:(cbn [length]; lia)
               ltac:(cbn [length]; lia)).
    reflexivity.
  - intros cols s f n m Hk Hn Hm.
    destruct s as [|[[o0 z0] c_0] rest].
    { destruct n, m; reflexivity. }
    cbn [length] in Hk, Hn, Hm.
    destruct n as [|n]; [lia|]. destruct m as [|m]; [lia|].
    cbn [renew_seg].
    destruct o0 as [|o1]; try reflexivity.
    destruct o1 as [o1|o1|]; try reflexivity.
    destruct o1 as [o1|o1|]; try reflexivity.
    destruct o1 as [o1|o1|]; try reflexivity.
    destruct z0 as [|z1]; try reflexivity.
    destruct z1 as [z1|z1|]; try reflexivity.
    destruct z1 as [z1|z1|]; try reflexivity.
    destruct c_0 as [|c1]; try reflexivity.
    destruct c1 as [c1|c1|]; try reflexivity.
    destruct rest as [|[[o5 z5] B] rest2]; [reflexivity|].
    cbn [length] in Hk, Hn, Hm.
    destruct ((o5 =? 4) && (z5 =? 2) && (1 <=? B))%N; [|reflexivity].
    cbv beta iota.
    destruct rest2 as [|gr2 rest2t]; [reflexivity|].
    cbn [length] in Hk, Hn, Hm.
    destruct (jump_seg cols B); [|reflexivity].
    cbv beta iota.
    destruct (seek (gr2 :: rest2t)) as [cols2 s3] eqn:ESK2.
    assert (HL3 : (length s3 <= S (length rest2t))%nat).
    { pose proof (seek_snd_len (gr2 :: rest2t)) as H0.
      rewrite ESK2 in H0. cbn [snd length] in H0. exact H0. }
    rewrite (IHr cols2 s3 f n m ltac:(lia) ltac:(lia) ltac:(lia)).
    destruct (renew_seg m cols2 s3 f) as [[body f']|];
      [reflexivity|].
    destruct s3 as [|[[o7 z7] c7] s3t]; [reflexivity|].
    cbn [length] in HL3.
    destruct ((z7 =? 3) && (c7 =? 1))%N.
    { assert (EIH := IHf ((o7,z7,c7) :: s3t) f n m
                 ltac:(cbn [length]; lia) ltac:(cbn [length]; lia)
                 ltac:(cbn [length]; lia)).
      xrewrite EIH. reflexivity. }
    reflexivity.
Qed.
Lemma fire_comp_sat : forall s f n,
  (length s <= n)%nat ->
  fire_comp n s f = fire_comp (length s) s f.
Proof.
  intros s f n Hn.
  exact (proj1 (fire_renew_sat (length s)) s f n (length s)
           ltac:(lia) Hn ltac:(lia)).
Qed.
Lemma renew_seg_sat : forall cols s f n,
  (length s <= n)%nat ->
  renew_seg n cols s f = renew_seg (length s) cols s f.
Proof.
  intros cols s f n Hn.
  exact (proj2 (fire_renew_sat (length s)) cols s f n (length s)
           ltac:(lia) Hn ltac:(lia)).
Qed.
Definition fres (sg : list seg) (r : res) : res :=
  match r with
  | ROk w f => ROk (lin_flat sg w) f
  | x => x
  end.
Lemma margins_cut : forall sg a g b,
  ph_margins sg (a ++ g :: b) ->
  casc g = false ->
  notag g = true ->
  ph_margins sg (g :: b).
Proof.
  intros sg a g b HM Hg HNT p gp Hp Hph.
  assert (Hp' : nth_error (a ++ g :: b) (length a + p) = Some gp)
    by (rewrite nth_error_app2 by lia;
        replace (length a + p - length a)%nat with p by lia;
        exact Hp).
  destruct (HM (length a + p)%nat gp Hp' Hph) as (H3 & HE & HW).
  assert (Hp3 : (3 <= p)%nat).
  { destruct p as [|p'].
    { exfalso. cbn [nth_error] in Hp. injection Hp as E. subst gp.
      rewrite (notag_ph sg g HNT) in Hph. discriminate. }
    destruct (PeanoNat.Nat.le_gt_cases 3 (S p')) as [|Hlt];
      [assumption|].
    exfalso.
    destruct (HW (length a)%nat
                ltac:(unfold GUARD in *; lia)
                ltac:(unfold GUARD in *; lia)
                ltac:(unfold GUARD in *; lia))
      as (g' & Hg' & Hc' & _).
    rewrite nth_error_app2 in Hg' by lia.
    rewrite PeanoNat.Nat.sub_diag in Hg'.
    cbn [nth_error] in Hg'. injection Hg' as E. subst g'.
    congruence. }
  split; [exact Hp3|].
  split.
  { rewrite length_app in HE. cbn [length] in HE |- *. lia. }
  intros q Hq1 Hq2 Hq3.
  destruct (HW (length a + q)%nat
              ltac:(unfold GUARD in *; lia)
              ltac:(unfold GUARD in *; lia)
              ltac:(unfold GUARD in *; lia))
    as (g' & Hg' & Hc' & Hph').
  rewrite nth_error_app2 in Hg' by lia.
  replace (length a + q - length a)%nat with q in Hg' by lia.
  exists g'. auto.
Qed.
Lemma nbrs_excl : forall sg (w : word) p g gl,
  ph_nbrs sg w ->
  nth_error w (S p) = Some g ->
  nth_error w p = Some gl ->
  is_spc gl = false ->
  ph sg g = false.
Proof.
  intros sg w p g gl HN Hg Hgl Hsp.
  destruct (ph sg g) eqn:E; [|reflexivity].
  destruct (HN (S p) g Hg E) as (_ & HL).
  rewrite (HL gl ltac:(lia)
             ltac:(replace (S p - 1)%nat with p by lia; exact Hgl))
    in Hsp.
  discriminate.
Qed.
Lemma flat_head_oz : forall sg (o z c : N) (t : word),
  sg_wf sg ->
  exists (o' c' : N) rest',
    lin_flat sg ((o,z,c) :: t) = (o',z,c') :: rest' /\
    (ph sg (o,z,c) = false -> o' = o /\ c' = c /\
       rest' = lin_flat sg t) /\
    (t <> [] -> exists h u, rest' = h :: u).
Proof.
  intros sg o z c t HW.
  rewrite lin_flat_cons.
  unfold keyb.
  destruct (keyi sg (o,z,c)) as [s|] eqn:EK.
  - destruct (keyi_in sg _ s EK) as (Hin & Hlv & _).
    destruct (sg_wf_seg sg s HW Hin) as [HC HOk].
    destruct (phshape_o _ Hlv) as [Ho Hz].
    cbn [gO gZ] in Ho, Hz. subst o z.
    unfold segok in HOk. cbv zeta in HOk.
    destruct (sBody s) as [|g0 b] eqn:EB; [discriminate|].
    apply andb_prop in HOk. destruct HOk as [HOk _].
    apply andb_prop in HOk. destruct HOk as [HOk _].
    apply andb_prop in HOk. destruct HOk as [HOk _].
    apply andb_prop in HOk. destruct HOk as [Hg0 _].
    destruct g0 as [[o0 z0] c_0].
    unfold is_lvl in Hg0. cbn [gO gZ] in Hg0.
    apply andb_prop in Hg0. destruct Hg0 as [Ho0 Hz0].
    apply N.eqb_eq in Ho0, Hz0. subst o0 z0.
    unfold sFlat, matb. rewrite EB.
    cbn [List.map].
    unfold adjk. cbn [gO gZ].
    change (((4 =? 4) && (2 =? 2))%N) with true.
    cbv beta iota.
    do 3 eexists.
    split; [cbn [app]; reflexivity|].
    split.
    { intros Hph.
      exfalso.
      unfold ph in Hph. rewrite EK in Hph. discriminate. }
    intros Hne.
    destruct b as [|gb bb].
    { cbn [List.map app].
      destruct t as [|gt tt]; [congruence|].
      destruct (flat_cons_ex sg gt tt HW) as (h & u & E).
      exists h, u. exact E. }
    cbn [List.map app].
    do 2 eexists. reflexivity.
  - exists o, c, (lin_flat sg t).
    split; [reflexivity|].
    split; [intros _; split; [reflexivity|split; reflexivity]|].
    intros Hne.
    destruct t as [|gt tt]; [congruence|].
    exact (flat_cons_ex sg gt tt HW).
Qed.
Lemma ph_nbrs_at_eq : forall sg w u,
  ph_nbrs sg w -> w = u -> ph_nbrs sg u.
Proof. intros sg w u H ->. exact H. Qed.
Lemma noncasc_nonspc : forall g,
  casc g = false -> is_spc g = false.
Proof.
  intros g H.
  destruct (is_spc g) eqn:E; [|reflexivity].
  rewrite (spc_casc g E) in H. discriminate.
Qed.
Lemma ph_nbrs_app_join : forall sg X Y,
  ph_nbrs sg X -> ph_nbrs sg Y ->
  (forall g, nth_error X (length X - 1) = Some g ->
     ph sg g = false) ->
  (forall g, nth_error Y O = Some g -> ph sg g = true ->
     (1 <= length X)%nat /\
     exists gl, nth_error X (length X - 1) = Some gl /\
                is_spc gl = true) ->
  ph_nbrs sg (X ++ Y).
Proof.
  intros sg X Y HX HY HXl HYh p g Hp Hph.
  destruct (PeanoNat.Nat.lt_ge_cases p (length X)) as [HpX|HpY].
  - rewrite nth_error_app1 in Hp by lia.
    destruct (HX p g Hp Hph) as ((gr & Hgr & Hsr) & HL).
    assert (HgrX : (p + 1 < length X)%nat)
      by (apply nth_error_Some; rewrite Hgr; discriminate).
    split.
    { exists gr. split; [|exact Hsr].
      rewrite nth_error_app1 by lia. exact Hgr. }
    intros gl Hp1 Hgl.
    rewrite nth_error_app1 in Hgl by lia.
    exact (HL gl Hp1 Hgl).
  - rewrite nth_error_app2 in Hp by lia.
    destruct (HY _ _ Hp Hph) as ((gr & Hgr & Hsr) & HL).
    split.
    { exists gr. split; [|exact Hsr].
      rewrite nth_error_app2 by lia.
      replace (p + 1 - length X)%nat with (p - length X + 1)%nat
        by lia.
      exact Hgr. }
    intros gl Hp1 Hgl.
    destruct (PeanoNat.Nat.eq_dec p (length X)) as [Hpe|Hpne].
    + subst p.
      rewrite PeanoNat.Nat.sub_diag in Hp.
      destruct (HYh g Hp Hph) as (HX1 & gl' & Hgl' & Hsl').
      rewrite nth_error_app1 in Hgl by lia.
      rewrite Hgl' in Hgl.
      injection Hgl as <-.
      exact Hsl'.
    + apply (HL gl); [lia|].
      rewrite nth_error_app2 in Hgl by lia.
      replace (p - length X - 1)%nat with (p - 1 - length X)%nat in Hgl
        by lia.
      replace (p - length X - 1)%nat with (p - 1 - length X)%nat
        by lia.
      exact Hgl.
Qed.
Lemma ph_nbrs_phfree : forall sg A,
  (forall g, In g A -> ph sg g = false) ->
  ph_nbrs sg A.
Proof.
  intros sg A HF p g Hp Hph.
  exfalso.
  rewrite (HF g (nth_error_In A p Hp)) in Hph. discriminate.
Qed.
Lemma ph_nbrs_cons_join : forall sg (h : bg) Y,
  ph sg h = false ->
  ph_nbrs sg Y ->
  (forall g, nth_error Y O = Some g -> ph sg g = true ->
     is_spc h = true) ->
  ph_nbrs sg (h :: Y).
Proof.
  intros sg h Y Hh HY HYh p g Hp Hph.
  destruct p as [|p'].
  { cbn [nth_error] in Hp. injection Hp as <-. congruence. }
  cbn [nth_error] in Hp.
  destruct (HY p' g Hp Hph) as ((gr & Hgr & Hsr) & HL).
  split.
  { exists gr. split; [|exact Hsr].
    replace (S p' + 1)%nat with (S (p' + 1)) by lia.
    cbn [nth_error]. exact Hgr. }
  intros gl Hp1 Hgl.
  destruct p' as [|p''].
  { cbn [nth_error] in Hgl. injection Hgl as <-.
    exact (HYh g Hp Hph). }
  replace (S (S p'') - 1)%nat with (S (S p'' - 1)) in Hgl by lia.
  cbn [nth_error] in Hgl.
  apply (HL gl); [lia|].
  exact Hgl.
Qed.
Lemma margins_win_excl : forall sg w p q g gq,
  ph_margins sg w ->
  nth_error w p = Some g ->
  nth_error w q = Some gq -> casc gq = false ->
  (q < p)%nat -> (p <= q + 3)%nat ->
  ph sg g = false.
Proof.
  intros sg w p q g gq HM Hp Hq Hc Hlt Hle.
  destruct (ph sg g) eqn:E; [|reflexivity].
  destruct (HM p g Hp E) as (_ & _ & HWn).
  destruct (HWn q ltac:(unfold GUARD; lia)
              ltac:(unfold GUARD; lia) ltac:(lia))
    as (g' & Hg' & Hc' & _).
  rewrite Hq in Hg'. injection Hg' as <-.
  congruence.
Qed.
Lemma margins_tail : forall sg g t,
  ph_margins sg (g :: t) -> casc g = false ->
  ph_margins sg t.
Proof.
  intros sg g t HM Hc p gp Hp Hph.
  destruct (HM (S p) gp Hp Hph) as (H3 & HE & HWn).
  assert (Hp3 : (3 <= p)%nat).
  { destruct (PeanoNat.Nat.le_gt_cases 3 p) as [|Hlt]; [assumption|].
    exfalso.
    destruct (HWn O ltac:(unfold GUARD; lia)
                ltac:(unfold GUARD; lia) ltac:(lia))
      as (g' & Hg' & Hc' & _).
    cbn [nth_error] in Hg'. injection Hg' as <-.
    congruence. }
  split; [exact Hp3|].
  split; [cbn [length] in HE; unfold GUARD in *; lia|].
  intros q Hq1 Hq2 Hq3.
  destruct (HWn (S q) ltac:(unfold GUARD in *; lia)
              ltac:(unfold GUARD in *; lia) ltac:(lia))
    as (g' & Hg' & Hc' & Hph').
  cbn [nth_error] in Hg'.
  exists g'. auto.
Qed.
Ltac litnp HK :=
  first
    [ reflexivity
    | (unfold ph;
       rewrite keyi_nonlvl;
       [ reflexivity
       | apply phshape_znot2; reflexivity ])
    | (unfold ph;
       rewrite keyi_nonlvl;
       [ reflexivity
       | apply phshape_znot2; apply N.eqb_neq; lia ])
    | (unfold ph;
       rewrite keyi_nonlvl;
       [ reflexivity
       | apply phshape_onot9; reflexivity ])
    | (unfold ph;
       rewrite keyi_nonlvl;
       [ reflexivity
       | apply phshape_onot9; apply N.eqb_neq; lia ])
    | (unfold ph;
       rewrite keyi_nonlvl;
       [ reflexivity
       | apply phshape_csmall; reflexivity ])
    | (unfold ph;
       rewrite keyi_none_of_keys;
       [ reflexivity
       | let s := fresh "s" in let Hs := fresh "Hs" in
         intros s Hs;
         first
         [ let H := fresh "HKs" in
           pose proof (HK s Hs) as H;
           cbn [gC]; unfold KMAGIC in *; lia
         | match goal with
           | HG : forall s1, In s1 ?SG ->
                    (?n < kdist ?cst (sKey s1))%N |- _ =>
               let H := fresh "HGs" in
               pose proof (HG s Hs) as H;
               cbn [gC]; unfold kdist in H;
               let E := fresh "EDL" in
               match type of H with
               | context [(?a <? ?b)%N] =>
                   destruct (a <? b)%N eqn:E;
                   [apply N.ltb_lt in E|apply N.ltb_ge in E]
               end; lia
           end ] ]) ].
Ltac lit_out HK :=
  split;
  [ apply ph_nbrs_phfree;
    let g := fresh "g" in let Hin := fresh "Hin" in
    intros g Hin;
    repeat (destruct Hin as [<-|Hin]); try (destruct Hin);
    litnp HK
  | split;
    [ let g := fresh "g" in let Hin := fresh "Hin" in
      let Hlv := fresh "Hlv" in
      intros g Hin Hlv;
      repeat (destruct Hin as [<-|Hin]); try (destruct Hin);
      first [ discriminate Hlv
            | right; unfold KMAGIC in *; cbn [gC]; lia ]
    | let g := fresh "g" in let t := fresh "t" in
      let E := fresh "E" in
      intros g t E; injection E as <- _; litnp HK ] ].
Lemma ph_nbrs_nil : forall sg, ph_nbrs sg [].
Proof. intros sg p g Hp. destruct p; discriminate. Qed.
Ltac litsm Hlv :=
  first
    [ discriminate Hlv
    | (rewrite is_lvl_znot2 in Hlv by reflexivity;
       discriminate Hlv)
    | (rewrite is_lvl_znot2 in Hlv
         by (apply N.eqb_neq; lia);
       discriminate Hlv)
    | (try right;
       let s0 := fresh "s0" in let Hs0 := fresh "Hs0" in
       intros s0 Hs0;
       first
       [ let H := fresh "HKs" in
         match goal with
         | HKb : keys_big ?SG |- _ => pose proof (HKb s0 Hs0) as H
         end;
         cbn [gC]; unfold kdist;
         let E := fresh "EDX" in
         match goal with
         | |- context [(?a <? ?b)%N] =>
             destruct (a <? b)%N eqn:E;
             [apply N.ltb_lt in E|apply N.ltb_ge in E]
         end; unfold KMAGIC in *; lia
       | match goal with
         | HG : forall s1, In s1 ?SG ->
                  (?n < kdist ?cst (sKey s1))%N |- _ =>
             let H := fresh "HGs" in
             pose proof (HG s0 Hs0) as H;
             cbn [gC]; unfold kdist in *;
             repeat match goal with
             | |- context [(?a <? ?b)%N] =>
                 let E := fresh "EDX" in
                 destruct (a <? b)%N eqn:E;
                 [apply N.ltb_lt in E|apply N.ltb_ge in E]
             end;
             repeat match type of H with
             | context [(?a <? ?b)%N] =>
                 let E := fresh "EDH" in
                 destruct (a <? b)%N eqn:E;
                 [apply N.ltb_lt in E|apply N.ltb_ge in E]
             end; lia
         end ]) ].
Ltac lin_facts HK :=
  split;
  [ let g := fresh "g" in let Hin := fresh "Hin" in
    intros g Hin;
    repeat (destruct Hin as [<-|Hin]); try (destruct Hin);
    litnp HK
  | let g := fresh "g" in let Hin := fresh "Hin" in
    let Hlv := fresh "Hlv" in
    intros g Hin Hlv;
    repeat (destruct Hin as [<-|Hin]); try (destruct Hin);
    first [ discriminate Hlv
          | cbn [gC]; unfold KMAGIC in *; lia ] ].
Definition nbrs1z (sg : list seg) (w : word) : Prop :=
  forall p g, nth_error w p = Some g -> ph sg g = true ->
    (exists gr, nth_error w (p + 1) = Some gr /\
                (is_spc gr = true \/ gZ gr = 1%N)) /\
    (forall gl, (1 <= p)%nat -> nth_error w (p - 1) = Some gl ->
                is_spc gl = true).
Lemma nbrs_nbrs1z : forall sg w,
  ph_nbrs sg w -> nbrs1z sg w.
Proof.
  intros sg w H p g Hp Hph.
  destruct (H p g Hp Hph) as ((gr & Hgr & Hsr) & HL).
  split; [|exact HL].
  exists gr. split; [exact Hgr|left; exact Hsr].
Qed.
Lemma nbrs1z_nil : forall sg, nbrs1z sg [].
Proof. intros sg p g Hp. destruct p; discriminate. Qed.
Lemma nbrs1z_app_join : forall sg X Y,
  nbrs1z sg X -> nbrs1z sg Y ->
  (forall g, nth_error X (length X - 1) = Some g ->
     ph sg g = true ->
     exists gy, nth_error Y O = Some gy /\
                (is_spc gy = true \/ gZ gy = 1%N)) ->
  (forall g, nth_error Y O = Some g -> ph sg g = true ->
     (1 <= length X)%nat /\
     exists gl, nth_error X (length X - 1) = Some gl /\
                is_spc gl = true) ->
  nbrs1z sg (X ++ Y).
Proof.
  intros sg X Y HX HY HXl HYh p g Hp Hph.
  destruct (PeanoNat.Nat.lt_ge_cases p (length X)) as [HpX|HpY].
  - rewrite nth_error_app1 in Hp by lia.
    destruct (HX p g Hp Hph) as ((gr & Hgr & Hsr) & HL).
    destruct (PeanoNat.Nat.lt_ge_cases (p + 1) (length X)) as [Hin|Hbd].
    + split.
      { exists gr. split; [|exact Hsr].
        rewrite nth_error_app1 by lia. exact Hgr. }
      intros gl Hp1 Hgl.
      rewrite nth_error_app1 in Hgl by lia.
      exact (HL gl Hp1 Hgl).
    +
      assert (Hpe : p = (length X - 1)%nat)
        by lia.
      subst p.
      destruct (HXl g Hp Hph) as (gy & Hgy & Hsy).
      split.
      { exists gy. split; [|exact Hsy].
        rewrite nth_error_app2 by lia.
        replace (length X - 1 + 1 - length X)%nat with O by lia.
        exact Hgy. }
      intros gl Hp1 Hgl.
      rewrite nth_error_app1 in Hgl by lia.
      exact (HL gl Hp1 Hgl).
  - rewrite nth_error_app2 in Hp by lia.
    destruct (HY _ _ Hp Hph) as ((gr & Hgr & Hsr) & HL).
    split.
    { exists gr. split; [|exact Hsr].
      rewrite nth_error_app2 by lia.
      replace (p + 1 - length X)%nat with (p - length X + 1)%nat by lia.
      exact Hgr. }
    intros gl Hp1 Hgl.
    destruct (PeanoNat.Nat.eq_dec p (length X)) as [Hpe|Hpne].
    + subst p.
      rewrite PeanoNat.Nat.sub_diag in Hp.
      destruct (HYh g Hp Hph) as (HX1 & gl' & Hgl' & Hsl').
      rewrite nth_error_app1 in Hgl by lia.
      rewrite Hgl' in Hgl.
      injection Hgl as <-.
      exact Hsl'.
    + apply (HL gl); [lia|].
      rewrite nth_error_app2 in Hgl by lia.
      replace (p - length X - 1)%nat with (p - 1 - length X)%nat
        by lia.
      exact Hgl.
Qed.
Lemma w42_tail_phfree : forall sg pre t,
  ph_nbrs sg (pre ++ t) ->
  forallb w42 t = true ->
  forall g, In g t -> ph sg g = false.
Proof.
  intros sg pre t HN HW g Hin.
  destruct (ph sg g) eqn:E; [|reflexivity].
  exfalso.
  apply In_nth_error in Hin. destruct Hin as (q & Hq).
  assert (HqL : (q < length t)%nat)
    by (apply nth_error_Some; rewrite Hq; discriminate).
  assert (Hq' : nth_error (pre ++ t) (length pre + q) = Some g)
    by (rewrite nth_error_app2 by lia;
        replace (length pre + q - length pre)%nat with q by lia;
        exact Hq).
  destruct (HN _ _ Hq' E) as ((gr & Hgr & Hsr) & _).
  assert (HgrL : (length pre + q + 1 < length (pre ++ t))%nat)
    by (apply nth_error_Some; rewrite Hgr; discriminate).
  rewrite length_app in HgrL.
  rewrite nth_error_app2 in Hgr by lia.
  replace (length pre + q + 1 - length pre)%nat with (q + 1)%nat in Hgr
    by lia.
  assert (HinR : In gr t) by (exact (nth_error_In t _ Hgr)).
  rewrite forallb_forall in HW.
  pose proof (HW gr HinR) as Hw42.
  unfold w42 in Hw42.
  unfold is_spc in Hsr.
  destruct gr as [[go gz] gc].
  cbn [gO gZ gC] in Hw42, Hsr.
  apply andb_prop in Hw42. destruct Hw42 as [Hgo _].
  apply N.eqb_eq in Hgo. subst go.
  cbn [andb] in Hsr.
  discriminate Hsr.
Qed.
Lemma dtb4_ne : forall b b', dtb4_conv b = Some b' -> b' <> [].
Proof.
  intros b b' H E. subst b'.
  destruct b as [|g t]; [discriminate|].
  cbn [dtb4_conv] in H.
  destruct (dtb4_conv t) as [t'|];
    [injection H as H; discriminate H|].
  match type of H with (if ?X then _ else _) = _ => destruct X end;
    [|discriminate H].
  match type of H with (if ?X then _ else _) = _ => destruct X end;
    [injection H as H; discriminate H|].
  destruct t as [|[[o1 z1] c1] [|[[o2 z2] c2] t2]]; try discriminate H.
  match type of H with (if ?X then _ else _) = _ => destruct X end;
    [|discriminate H].
  destruct t2 as [|[[o3 z3] c3] [|g4 t4]]; try discriminate H.
  match type of H with (if ?X then _ else _) = _ => destruct X end;
    [discriminate H|discriminate H].
Qed.
Lemma dtb3_ne : forall b b', dtb3_conv b = Some b' -> b' <> [].
Proof.
  intros b b' H E. subst b'.
  destruct b as [|g t]; [discriminate|].
  cbn [dtb3_conv] in H.
  destruct (dtb3_conv t) as [t'|];
    [injection H as H; discriminate H|].
  match type of H with (if ?X then _ else _) = _ => destruct X end;
    [|discriminate H].
  destruct t as [|[[o1 z1] c1] t1]; [discriminate H|].
  match type of H with (if ?X then _ else _) = _ => destruct X end;
    [discriminate H|discriminate H].
Qed.
Lemma nbrs1z_app_lit_l : forall sg A Y,
  (forall g, In g A -> ph sg g = false) ->
  nbrs1z sg Y ->
  (forall g u, Y = g :: u -> ph sg g = false) ->
  nbrs1z sg (A ++ Y).
Proof.
  intros sg A Y HA HY HYh.
  apply nbrs1z_app_join;
    [apply nbrs_nbrs1z; apply ph_nbrs_phfree; exact HA
    |exact HY| |].
  - intros g Hg Hph.
    exfalso.
    rewrite (HA g (nth_error_In A _ Hg)) in Hph. discriminate.
  - intros g Hg Hph.
    exfalso.
    destruct Y as [|g0 u]; [discriminate|].
    cbn [nth_error] in Hg. injection Hg as <-.
    rewrite (HYh g0 u eq_refl) in Hph. discriminate.
Qed.
Definition mend (sg : list seg) (X : word) : Prop :=
  forall p g, nth_error X p = Some g -> ph sg g = true ->
    (p + 3 < length X)%nat.
Lemma mend_last2_nonph : forall sg ini (a b : bg),
  mend sg (ini ++ [a; b]) ->
  ph sg a = false /\ ph sg b = false.
Proof.
  intros sg ini a b HM.
  split.
  - destruct (ph sg a) eqn:E; [|reflexivity].
    exfalso.
    assert (Hp : nth_error (ini ++ [a; b]) (length ini) = Some a)
      by (rewrite nth_error_app2 by lia;
          rewrite PeanoNat.Nat.sub_diag; reflexivity).
    pose proof (HM _ _ Hp E) as HE.
    rewrite length_app in HE. cbn [length] in HE. lia.
  - destruct (ph sg b) eqn:E; [|reflexivity].
    exfalso.
    assert (Hp : nth_error (ini ++ [a; b]) (length ini + 1) = Some b)
      by (rewrite nth_error_app2 by lia;
          replace (length ini + 1 - length ini)%nat with 1%nat by lia;
          reflexivity).
    pose proof (HM _ _ Hp E) as HE.
    rewrite length_app in HE. cbn [length] in HE. lia.
Qed.
Lemma nbrs_prefix2_mend : forall sg X (a b : bg),
  mend sg (X ++ [a; b]) ->
  ph_nbrs sg (X ++ [a; b]) ->
  ph_nbrs sg X.
Proof.
  intros sg X a b HM HN p g Hp Hph.
  assert (HpX : (p < length X)%nat)
    by (apply nth_error_Some; rewrite Hp; discriminate).
  assert (Hp' : nth_error (X ++ [a; b]) p = Some g)
    by (rewrite nth_error_app1 by lia; exact Hp).
  pose proof (HM _ _ Hp' Hph) as HE.
  rewrite length_app in HE. cbn [length] in HE.
  destruct (HN _ _ Hp' Hph) as ((gr & Hgr & Hsr) & HL).
  split.
  { exists gr. split; [|exact Hsr].
    rewrite nth_error_app1 in Hgr by lia. exact Hgr. }
  intros gl Hp1 Hgl.
  apply (HL gl); [exact Hp1|].
  rewrite nth_error_app1 by lia. exact Hgl.
Qed.
Lemma mend_seek : forall sg pfx r,
  ph_margins sg (pfx ++ r) ->
  mend sg (fst (seek r)).
Proof.
  intros sg pfx r HM p g Hp Hph.
  pose proof (LineageGuard_seek_split r) as HSp.
  assert (HpL : (p < length (fst (seek r)))%nat)
    by (apply nth_error_Some; rewrite Hp; discriminate).
  assert (Hp' : nth_error (pfx ++ r) (length pfx + p) = Some g).
  { rewrite nth_error_app2 by lia.
    replace (length pfx + p - length pfx)%nat with p by lia.
    rewrite HSp.
    rewrite nth_error_app1 by lia.
    exact Hp. }
  destruct (HM _ _ Hp' Hph) as (_ & HE & HWn).
  destruct (PeanoNat.Nat.lt_ge_cases (p + 3)
              (length (fst (seek r)))) as [|Hge]; [assumption|].
  exfalso.
  destruct (snd (seek r)) as [|gs bs] eqn:ESnd.
  { pose proof (f_equal (@length bg) HSp) as HLen.
    rewrite length_app in HLen.
    cbn [length] in HLen.
    rewrite length_app in HE.
    unfold GUARD in HE. lia. }
  set (qs := (length pfx + length (fst (seek r)))%nat).
  destruct (HWn qs
              ltac:(unfold qs, GUARD in *; lia)
              ltac:(unfold qs, GUARD in *; lia)
              ltac:(unfold qs, GUARD in *; lia))
    as (g' & Hg' & Hc' & _).
  unfold qs in Hg'.
  rewrite nth_error_app2 in Hg' by lia.
  replace (length pfx + length (fst (seek r)) - length pfx)%nat
    with (length (fst (seek r))) in Hg' by lia.
  set (LF := length (fst (seek r))) in Hg'.
  rewrite HSp in Hg'.
  rewrite nth_error_app2 in Hg' by (unfold LF; lia).
  replace (LF - length (fst (seek r)))%nat with O in Hg'
    by (unfold LF; lia).
  cbn [nth_error] in Hg'. injection Hg' as <-.
  pose proof (seek_snd_head r gs bs ESnd) as Hst.
  rewrite (casc_seekable gs Hc') in Hst.
  discriminate.
Qed.
Lemma mend_tail_word : forall sg pfx X,
  ph_margins sg (pfx ++ X) ->
  mend sg X.
Proof.
  intros sg pfx X HM p g Hp Hph.
  assert (Hp' : nth_error (pfx ++ X) (length pfx + p) = Some g)
    by (rewrite nth_error_app2 by lia;
        replace (length pfx + p - length pfx)%nat with p by lia;
        exact Hp).
  destruct (HM _ _ Hp' Hph) as (_ & HE & _).
  rewrite length_app in HE.
  unfold GUARD in HE. lia.
Qed.
Lemma margins_cut_at : forall sg w a g b,
  ph_margins sg w -> w = a ++ g :: b ->
  casc g = false ->
  notag g = true ->
  ph_margins sg (g :: b).
Proof.
  intros sg w a g b HM -> HC HNT.
  exact (margins_cut sg a g b HM HC HNT).
Qed.
Lemma nbrs1z_seek_all : forall sg t2,
  nbrs1z sg t2 ->
  snd (seek t2) = [] ->
  ph_nbrs sg (fst (seek t2)).
Proof.
  intros sg t2 H1 ESnd p g Hp Hph.
  pose proof (LineageGuard_seek_split t2) as HSp.
  pose proof (f_equal (@length bg) HSp) as HLen.
  rewrite length_app in HLen.
  assert (E0 : length (snd (seek t2)) = O)
    by (rewrite ESnd; reflexivity).
  assert (HpL : (p < length (fst (seek t2)))%nat)
    by (apply nth_error_Some; rewrite Hp; discriminate).
  assert (Hp' : nth_error t2 p = Some g)
    by (rewrite HSp; rewrite nth_error_app1 by lia; exact Hp).
  destruct (H1 p g Hp' Hph) as ((gr & Hgr & Hsr) & HL).
  assert (HgrL : (p + 1 < length t2)%nat)
    by (apply nth_error_Some; rewrite Hgr; discriminate).
  assert (HgrF : nth_error (fst (seek t2)) (p + 1) = Some gr).
  { rewrite HSp in Hgr.
    rewrite nth_error_app1 in Hgr by lia.
    exact Hgr. }
  split.
  { exists gr. split; [exact HgrF|].
    destruct Hsr as [Hs|Hz1]; [exact Hs|].
    exfalso.
    pose proof (seek_fst_col t2 gr
                  (nth_error_In _ _ HgrF)) as Hcol.
    unfold seektest in Hcol.
    apply andb_prop in Hcol. destruct Hcol as [Hcol _].
    apply andb_prop in Hcol. destruct Hcol as [Hcol _].
    unfold is_col in Hcol.
    apply andb_prop in Hcol. destruct Hcol as [Hz2 _].
    apply N.eqb_eq in Hz2. lia. }
  intros gl Hp1 Hgl.
  apply (HL gl); [exact Hp1|].
  rewrite HSp.
  rewrite nth_error_app1 by lia.
  exact Hgl.
Qed.
Lemma nbrs_excl1z : forall sg (w : word) p g gl,
  nbrs1z sg w ->
  nth_error w (S p) = Some g ->
  nth_error w p = Some gl ->
  is_spc gl = false ->
  ph sg g = false.
Proof.
  intros sg w p g gl HN Hg Hgl Hsp.
  destruct (ph sg g) eqn:E; [|reflexivity].
  destruct (HN (S p) g Hg E) as (_ & HL).
  rewrite (HL gl ltac:(lia)
             ltac:(replace (S p - 1)%nat with p by lia; exact Hgl))
    in Hsp.
  discriminate.
Qed.
Lemma nbrs1z_tail : forall sg g t,
  nbrs1z sg (g :: t) -> nbrs1z sg t.
Proof.
  intros sg g t H p gp Hp Hph.
  destruct (H (S p) gp Hp Hph) as ((gr & Hgr & Hsr) & HL).
  split.
  { exists gr. split; [|exact Hsr].
    replace (S p + 1)%nat with (S (p + 1)) in Hgr by lia.
    cbn [nth_error] in Hgr. exact Hgr. }
  intros gl Hp1 Hgl.
  apply (HL gl); [lia|].
  replace (S p - 1)%nat with (S (p - 1)) by lia.
  cbn [nth_error]. exact Hgl.
Qed.
Lemma nbrs1z_app_r : forall sg a b,
  nbrs1z sg (a ++ b) -> nbrs1z sg b.
Proof.
  intros sg a b H.
  induction a as [|g a IH]; [exact H|].
  apply IH.
  exact (nbrs1z_tail sg g (a ++ b) H).
Qed.
Lemma nbrs1z_at_eq : forall sg w u,
  nbrs1z sg w -> w = u -> nbrs1z sg u.
Proof. intros sg w u H ->. exact H. Qed.
Lemma nbrs1z_seek_notlast : forall sg r gs bs,
  nbrs1z sg r ->
  snd (seek r) = gs :: bs ->
  is_spc gs = false -> gZ gs <> 1%N ->
  ph_notlast sg (fst (seek r)).
Proof.
  intros sg r gs bs HN ESnd Hsp Hz1 p g Hp Hph.
  pose proof (LineageGuard_seek_split r) as HSp.
  assert (HpL : (p < length (fst (seek r)))%nat)
    by (apply nth_error_Some; rewrite Hp; discriminate).
  destruct (PeanoNat.Nat.lt_ge_cases (p + 1)
              (length (fst (seek r)))) as [|Hge];
    [assumption|exfalso].
  assert (Hpe : (p + 1 = length (fst (seek r)))%nat) by lia.
  assert (Hp' : nth_error r p = Some g)
    by (rewrite HSp; rewrite nth_error_app1 by lia; exact Hp).
  destruct (HN p g Hp' Hph) as ((gr & Hgr & Hsr) & _).
  rewrite HSp in Hgr.
  rewrite nth_error_app2 in Hgr by lia.
  rewrite Hpe, PeanoNat.Nat.sub_diag in Hgr.
  rewrite ESnd in Hgr.
  cbn [nth_error] in Hgr. injection Hgr as <-.
  destruct Hsr as [Hs|Hz]; [congruence|].
  exact (Hz1 Hz).
Qed.
Lemma nbrs1z_seek_snd_head : forall sg r gs bs,
  nbrs1z sg r ->
  snd (seek r) = gs :: bs ->
  ph sg gs = false.
Proof.
  intros sg r gs bs HN ESnd.
  pose proof (seek_snd_head r gs bs ESnd) as Hst.
  pose proof (seektest_noncasc _ Hst) as Hnc.
  destruct (ph sg gs) eqn:E; [|reflexivity].
  rewrite (ph_seektest sg _ E) in Hst. discriminate.
Qed.
Lemma leaf_act_flat_z1_z : forall sg (A C : N) t f,
  sg_wf sg -> keys_big sg ->
  nbrs1z sg ((A, 1%N, C) :: t) ->
  leaf_act ((A, 1%N, C) :: lin_flat sg t) f
  = flat_res sg (leaf_act ((A, 1%N, C) :: t) f).
Proof.
  intros sg A C t f HW HK HN.
  assert (Hsp0 : is_spc (A,1%N,C) = false).
  { unfold is_spc. cbn [gO gZ gC].
    change ((1 =? 2)%N) with false.
    rewrite andb_false_r. cbn [andb]. reflexivity. }
  cbn [leaf_act].
  destruct (2 <=? C)%N.
  { destruct (2 <=? A)%N; [|reflexivity].
    cbn [flat_res].
    destruct (2 <? C)%N; cbn [app]; flatgo HK. }
  destruct (negb (C =? 1) || negb (2 <=? A))%N; [reflexivity|].
  destruct t as [|[[B zb] cb] t2].
  { flatnil.
    destruct (2 <=? f)%N;
      [cbn [flat_res]; flatgo HK|].
    destruct (f =? 1)%N;
      [cbn [flat_res]; flatgo HK|].
    reflexivity. }
  assert (Hnp0 : ph sg (B,zb,cb) = false)
    by (exact (nbrs_excl1z sg _ O _ _ HN eq_refl eq_refl Hsp0)).
  assert (EF : lin_flat sg ((B,zb,cb) :: t2)
               = (B,zb,cb) :: lin_flat sg t2)
    by (apply flat_cons_nonph; exact Hnp0).
  xrewrite EF. cbv beta iota.
  destruct t2 as [|[[o2 z2] c2] t3].
  -
    flatnil.
    match goal with
    | |- (if ?X then _ else _) = _ => destruct X eqn:EG
    end.
    + match goal with
      | |- (if ?X then _ else _) = _ => destruct X
      end; [reflexivity|].
      destruct (B =? 1)%N.
      { destruct (cb =? 1)%N; [|reflexivity].
        cbn [flat_res]. flatgo HK. }
      destruct ((cb =? 1) && (2 <=? B))%N eqn:EB2; [|reflexivity].
      apply andb_prop in EB2. destruct EB2 as [Ecb _].
      apply N.eqb_eq in Ecb. subst cb.
      apply andb_prop in EG. destruct EG as [EG _].
      apply andb_prop in EG. destruct EG as [Ezb _].
      apply N.eqb_eq in Ezb. subst zb.
      cbn [flat_res]. flatgo HK.
    + destruct ((B =? 8) && (zb =? 2) && (cb =? 1))%N.
      { cbn [flat_res]. flatgo HK. }
      destruct ((B =? 4) && (zb =? 2))%N eqn:E4.
      { apply andb_prop in E4. destruct E4 as [EB4 Ezb].
        apply N.eqb_eq in EB4, Ezb. subst B zb.
        destruct (cb =? 1)%N eqn:Ecb1.
        { cbn [flat_res]. flatgo HK. }
        destruct (2 <=? cb)%N eqn:Ecb2; [|reflexivity].
        cbn [flat_res]. flatgo HK. }
      destruct (zb =? 1)%N eqn:Ezb1.
      { apply N.eqb_eq in Ezb1. subst zb.
        destruct (2 <=? cb)%N.
        { destruct (2 <=? B)%N; [|reflexivity].
          cbn [flat_res]. flatgo HK. }
        destruct (B =? 1)%N.
        { destruct (cb =? 1)%N; [|reflexivity].
          cbn [flat_res]. flatgo HK. }
        destruct ((cb =? 1) && (2 <=? B))%N; [|reflexivity].
        cbn [flat_res]. flatgo HK. }
      destruct ((3 <=? zb) && (cb =? 1))%N eqn:E3z; [|reflexivity].
      apply andb_prop in E3z. destruct E3z as [E3z _].
      apply N.leb_le in E3z.
      destruct (B =? 1)%N.
      { cbn [flat_res]. flatc HK. reflexivity. }
      destruct (2 <=? B)%N; [|reflexivity].
      cbn [flat_res]. flatlit.
      rewrite flat_cons_nonlvl
        by (apply phshape_znot2; apply N.eqb_neq; lia).
      reflexivity.
  -
    destruct (flat_head_oz sg o2 z2 c2 t3 HW)
      as (o2' & c2' & rest2' & EOZ & HOZ & HNE).
    xrewrite EOZ.
    match goal with
    | |- (if ?X then _ else _) = _ => destruct X eqn:EG
    end.
    + pose proof EG as EGparts.
      apply andb_prop in EGparts. destruct EGparts as [EGhead _].
      apply andb_prop in EGhead. destruct EGhead as [Ezb EB8].
      apply N.eqb_eq in Ezb. subst zb.
      apply negb_true_iff in EB8.
      assert (Hsp1 : is_spc (B,2%N,cb) = false).
      { unfold is_spc. cbn [gO gZ gC].
        rewrite EB8. reflexivity. }
      assert (Hnp1 : ph sg (o2,z2,c2) = false)
        by (exact (nbrs_excl1z sg _ 1%nat _ _ HN eq_refl eq_refl Hsp1)).
      destruct (HOZ Hnp1) as (-> & -> & ->).
      rewrite EG.
      match goal with
      | |- (if ?X then _ else _) = _ => destruct X eqn:E5
      end.
      {
        apply andb_prop in E5. destruct E5 as [E5a E5b].
        apply andb_prop in E5a. destruct E5a as [EB5 Ecb1].
        apply N.eqb_eq in EB5, Ecb1. subst B cb.
        apply andb_prop in E5b. destruct E5b as [Eo2 Ez2].
        apply N.eqb_eq in Eo2, Ez2. subst o2 z2.
        cbn [flat_res]. flatgo HK. }
      destruct (B =? 1)%N.
      { destruct (cb =? 1)%N; [|reflexivity].
        cbn [flat_res]. flatgo2 HK EOZ. }
      destruct ((cb =? 1) && (2 <=? B))%N eqn:EB2; [|reflexivity].
      cbn [flat_res]. flatgo2 HK EOZ.
    + destruct ((B =? 8) && (zb =? 2) && (cb =? 1))%N eqn:Espc.
      { apply andb_prop in Espc. destruct Espc as [E82 Ecb].
        apply andb_prop in E82. destruct E82 as [EB8 Ezb].
        apply N.eqb_eq in EB8, Ezb, Ecb. subst B zb cb.
        cbn [flat_res N.eqb Pos.eqb andb orb negb]. flatgo2 HK EOZ. }
      assert (Hsp1 : is_spc (B,zb,cb) = false).
      { unfold is_spc. cbn [gO gZ gC]. exact Espc. }
      assert (Hnp1 : ph sg (o2,z2,c2) = false)
        by (exact (nbrs_excl1z sg _ 1%nat _ _ HN eq_refl eq_refl Hsp1)).
      destruct (HOZ Hnp1) as (-> & -> & ->).
      rewrite EG.
      destruct ((B =? 4) && (zb =? 2))%N eqn:E4.
      { apply andb_prop in E4. destruct E4 as [EB4 Ezb].
        apply N.eqb_eq in EB4, Ezb. subst B zb.
        destruct (cb =? 1)%N eqn:Ecb1.
        { cbn [flat_res]. flatgo2 HK EOZ. }
        destruct (2 <=? cb)%N eqn:Ecb2; [|reflexivity].
        cbn [flat_res]. flatgo2 HK EOZ. }
      destruct (zb =? 1)%N eqn:Ezb1.
      { apply N.eqb_eq in Ezb1. subst zb.
        destruct (2 <=? cb)%N.
        { destruct (2 <=? B)%N; [|reflexivity].
          cbn [flat_res]. flatgo2 HK EOZ. }
        destruct (B =? 1)%N.
        { destruct (cb =? 1)%N; [|reflexivity].
          cbn [flat_res]. flatgo2 HK EOZ. }
        destruct ((cb =? 1) && (2 <=? B))%N; [|reflexivity].
        cbn [flat_res]. flatgo2 HK EOZ. }
      destruct ((3 <=? zb) && (cb =? 1))%N eqn:E3z; [|reflexivity].
      apply andb_prop in E3z. destruct E3z as [E3z _].
      apply N.leb_le in E3z.
      destruct (B =? 1)%N.
      { cbn [flat_res]. flatc HK. flatgo2 HK EOZ. }
      destruct (2 <=? B)%N; [|reflexivity].
      cbn [flat_res]. flatlit.
      rewrite flat_cons_nonlvl
        by (apply phshape_znot2; apply N.eqb_neq; lia).
      flatgo2 HK EOZ.
Qed.
Lemma leaf_act_flat_z2_z : forall sg (o : N) t f,
  sg_wf sg -> keys_big sg ->
  nbrs1z sg ((o, 2%N, 1%N) :: t) ->
  ((5 <=? o) && negb (o =? 8) && negb (o =? 12))%N = true ->
  (forall f', leaf_act (lin_flat sg t) f'
              = flat_res sg (leaf_act t f')) ->
  leaf_act ((o, 2%N, 1%N) :: lin_flat sg t) f
  = flat_res sg (leaf_act ((o, 2%N, 1%N) :: t) f).
Proof.
  intros sg o t f HW HK HN EO IH.
  pose proof (casc_cmf_false o 1%N EO) as Hcasc.
  pose proof (phshape_c1 o 2%N) as Hlvo.
  assert (Hsp0 : is_spc (o,2%N,1%N) = false).
  { pose proof EO as EO2.
    apply andb_prop in EO2. destruct EO2 as [EO2 _].
    apply andb_prop in EO2. destruct EO2 as [_ Ho8].
    unfold is_spc. cbn [gO gZ gC].
    destruct (o =? 8)%N; [discriminate|].
    cbn [andb]. reflexivity. }
  cbn [leaf_act].
  rewrite EO. cbv beta iota.
  destruct t as [|[[on zn] cn] t1].
  - flatnil.
    destruct (f =? 3)%N;
      [cbn [flat_res]; flatchain HK|].
    destruct (f =? 2)%N;
      [cbn [flat_res]; flatchain HK|].
    destruct (f =? 4)%N;
      [cbn [flat_res]; flatchain HK|].
    reflexivity.
  - assert (Hnp0 : ph sg (on,zn,cn) = false)
      by (exact (nbrs_excl1z sg _ O _ _ HN eq_refl eq_refl Hsp0)).
    assert (EF : lin_flat sg ((on,zn,cn) :: t1)
                 = (on,zn,cn) :: lin_flat sg t1)
      by (apply flat_cons_nonph; exact Hnp0).
    xrewrite EF. cbv beta iota.
    pose proof (IH f) as IHf.
    xrewrite_in IHf EF.
    destruct (on =? 1)%N; [reflexivity|].
    destruct t1 as [|[[o2 z2] c2] t2].
    +
      flatnil_in IHf. flatnil.
      destruct ((on =? 3) && (zn =? 2) && (cn =? 1) && (f =? 4))%N.
      { cbn [flat_res]. flatchain HK. }
      destruct ((on =? 4) && (zn =? 2))%N.
      { destruct (f =? 4)%N; [|reflexivity].
        cbn [flat_res]. flatlit.
        rewrite flat_cons_nonph by exact Hnp0.
        rewrite flat_wnil. reflexivity. }
      match goal with
      | |- (if ?X then _ else _) = _ => destruct X
      end; [reflexivity|].
      match goal with
      | |- (if ?X then _ else _) = _ => destruct X
      end; [|reflexivity].
      match goal with
      | |- _ = flat_res _ (match ?T with _ => _ end) =>
          destruct T as [[sC fC]|] eqn:ERC
      end.
      * xrewrite ERC. xrewrite_in IHf ERC.
        cbn [flat_res] in IHf.
        injection IHf as IHs.
        cbv beta iota. cbn [flat_res].
        rewrite flat_cons_nonlvl by exact Hlvo.
        rewrite <- IHs. reflexivity.
      * xrewrite ERC. reflexivity.
    +
      destruct (flat_head_oz sg o2 z2 c2 t2 HW)
        as (o2' & c2' & r1' & EOZ1 & HOZ1 & HNE1).
      xrewrite EOZ1.
      xrewrite_in IHf EOZ1.
      destruct t2 as [|[[o3 z3] c3] t3].
      *
        destruct ((on =? 3) && (zn =? 2) && (cn =? 1) && (f =? 4))%N
          eqn:E3.
        { apply andb_prop in E3. destruct E3 as [E3 Ef4].
          apply andb_prop in E3. destruct E3 as [E3 Ecn1].
          apply andb_prop in E3. destruct E3 as [Eon Ezn].
          apply N.eqb_eq in Eon, Ezn, Ecn1. subst on zn cn.
          assert (Hsp1 : is_spc (3%N,2%N,1%N) = false)
            by reflexivity.
          assert (Hnp1 : ph sg (o2,z2,c2) = false)
            by (exact (nbrs_excl1z sg _ 1%nat _ _ HN eq_refl eq_refl
                         Hsp1)).
          destruct (HOZ1 Hnp1) as (-> & -> & ->).
          flatnil.
          destruct ((o2 =? 4) && (z2 =? 2))%N eqn:E42; [|reflexivity].
          apply andb_prop in E42. destruct E42 as [Eo2 Ez2].
          apply N.eqb_eq in Eo2, Ez2. subst o2 z2.
          cbn [flat_res]. flatchain HK. }
        destruct ((on =? 4) && (zn =? 2))%N eqn:E4.
        { apply andb_prop in E4. destruct E4 as [Eon Ezn].
          apply N.eqb_eq in Eon, Ezn. subst on zn.
          assert (Hsp1 : is_spc (4%N,2%N,cn) = false)
            by reflexivity.
          assert (Hnp1 : ph sg (o2,z2,c2) = false)
            by (exact (nbrs_excl1z sg _ 1%nat _ _ HN eq_refl eq_refl
                         Hsp1)).
          destruct (HOZ1 Hnp1) as (-> & -> & ->).
          flatnil.
          reflexivity. }
        match goal with
        | |- (if ?P && ?Q then _ else _) = _ => destruct P eqn:EX6
        end.
        2:{ cbn [andb]. cbv beta iota.
            match goal with
            | |- (if ?X then _ else _) = _ => destruct X eqn:ER
            end.
            2:{ reflexivity. }
            assert (Hsp1 : is_spc (on,zn,cn) = false).
            { apply orb_prop in ER.
              unfold is_spc. cbn [gO gZ gC].
              destruct ER as [Ez1|ER].
              - apply N.eqb_eq in Ez1. subst zn.
                change ((1 =? 2)%N) with false.
                rewrite andb_false_r. cbn [andb]. reflexivity.
              - apply andb_prop in ER. destruct ER as [ER _].
                apply andb_prop in ER. destruct ER as [ER Hn8].
                destruct (on =? 8)%N; [discriminate|].
                cbn [andb]. reflexivity. }
            assert (Hnp1 : ph sg (o2,z2,c2) = false)
              by (exact (nbrs_excl1z sg _ 1%nat _ _ HN eq_refl eq_refl
                           Hsp1)).
            destruct (HOZ1 Hnp1) as (-> & -> & ->).
            match goal with
            | |- _ = flat_res _ (match ?T with _ => _ end) =>
                destruct T as [[sC fC]|] eqn:ERC
            end.
            { xrewrite ERC.
              xrewrite_in IHf ERC.
              cbn [flat_res] in IHf.
              injection IHf as IHs.
              cbv beta iota. cbn [flat_res].
              rewrite flat_cons_nonlvl by exact Hlvo.
              rewrite <- IHs. reflexivity. }
            { xrewrite ERC. reflexivity. } }
        apply andb_prop in EX6. destruct EX6 as [EX6 Ef4].
        apply andb_prop in EX6. destruct EX6 as [EX6 Ecn1].
        apply andb_prop in EX6. destruct EX6 as [EX6 Ezn2].
        apply andb_prop in EX6. destruct EX6 as [EoX6 Eon2].
        apply N.eqb_eq in Eon2, Ezn2, Ecn1. subst on zn cn.
        assert (Hsp1 : is_spc (2%N,2%N,1%N) = false)
          by reflexivity.
        assert (Hnp1 : ph sg (o2,z2,c2) = false)
          by (exact (nbrs_excl1z sg _ 1%nat _ _ HN eq_refl eq_refl
                       Hsp1)).
        destruct (HOZ1 Hnp1) as (-> & -> & ->).
        flatnil.
        cbn [andb].
        destruct ((o2 =? 4) && (z2 =? 2))%N eqn:E42.
        { cbv beta iota.
          apply andb_prop in E42. destruct E42 as [Eo2 Ez2].
          apply N.eqb_eq in Eo2, Ez2. subst o2 z2.
          cbn [flat_res]. flatchain HK. }
        cbv beta iota.
        match goal with
        | |- (if ?X then _ else _) = _ => destruct X eqn:ER
        end; [discriminate ER|reflexivity].
      *
        destruct (HNE1 ltac:(discriminate)) as (h1 & u1 & Er1).
        subst r1'.
        destruct ((on =? 3) && (zn =? 2) && (cn =? 1) && (f =? 4))%N.
        { reflexivity. }
        destruct ((on =? 4) && (zn =? 2))%N eqn:E4.
        { apply andb_prop in E4. destruct E4 as [Eon Ezn].
          apply N.eqb_eq in Eon, Ezn. subst on zn.
          assert (Hsp1 : is_spc (4%N,2%N,cn) = false)
            by reflexivity.
          assert (Hnp1 : ph sg (o2,z2,c2) = false)
            by (exact (nbrs_excl1z sg _ 1%nat _ _ HN eq_refl eq_refl
                         Hsp1)).
          destruct (HOZ1 Hnp1) as (-> & -> & Er1').
          destruct (flat_head_oz sg o3 z3 c3 t3 HW)
            as (o3' & c3' & r2' & EOZ2 & HOZ2 & HNE2).
          rewrite EOZ2 in Er1'.
          injection Er1' as Eh1 Eu1.
          subst h1 u1.
          destruct t3 as [|g4 t4].
          -
            assert (Hnp2 : ph sg (o3,z3,c3) = false).
            { destruct (ph sg (o3,z3,c3)) eqn:EP3;
                [|reflexivity].
              exfalso.
              destruct (HN 3%nat (o3,z3,c3) eq_refl EP3)
                as ((gr & Hgr & _) & _).
              cbn [nth_error] in Hgr. discriminate. }
            destruct (HOZ2 Hnp2) as (-> & -> & Er2n).
            rewrite flat_wnil in Er2n. subst r2'.
            match goal with
            | |- (if ?X then _ else _) = _ => destruct X eqn:EOr
            end; [|reflexivity].
            apply andb_prop in EOr. destruct EOr as [EOr _].
            apply andb_prop in EOr. destruct EOr as [EOr Ez3].
            apply andb_prop in EOr. destruct EOr as [EOr Eo3].
            apply andb_prop in EOr. destruct EOr as [EOr Ec21].
            apply andb_prop in EOr. destruct EOr as [EOr Ez2].
            apply andb_prop in EOr. destruct EOr as [E1cn Eo2].
            apply N.eqb_eq in Eo2, Ez2, Ec21, Eo3, Ez3.
            subst o2 z2 c2 o3 z3.
            cbn [flat_res].
            destruct (cn =? 1)%N; cbn [app]; flatchain HK.
          -
            destruct (HNE2 ltac:(discriminate)) as (h2 & u2 & Er2).
            subst r2'.
            reflexivity. }
        cbv beta iota.
        rewrite !andb_false_r.
        cbv beta iota.
        match goal with
        | |- (if ?X then _ else _) = _ => destruct X eqn:ER
        end; [|reflexivity].
        assert (Hsp1 : is_spc (on,zn,cn) = false).
        { apply orb_prop in ER.
          unfold is_spc. cbn [gO gZ gC].
          destruct ER as [Ez1|ER'].
          - apply N.eqb_eq in Ez1. subst zn.
            change ((1 =? 2)%N) with false.
            rewrite andb_false_r. cbn [andb]. reflexivity.
          - apply andb_prop in ER'. destruct ER' as [ER' _].
            apply andb_prop in ER'. destruct ER' as [ER' Hn8].
            destruct (on =? 8)%N; [discriminate|].
            cbn [andb]. reflexivity. }
        assert (Hnp1 : ph sg (o2,z2,c2) = false)
          by (exact (nbrs_excl1z sg _ 1%nat _ _ HN eq_refl eq_refl
                       Hsp1)).
        destruct (HOZ1 Hnp1) as (Eo2' & Ec2' & Er1').
        subst c2'.
        destruct (leaf_act
                    ((on,zn,cn) :: (o2,z2,c2) :: (o3,z3,c3) :: t3) f)
          as [[sC fC]|] eqn:ERC.
        { cbn [flat_res] in IHf.
          xrewrite IHf.
          cbv beta iota. cbn [flat_res].
          rewrite flat_cons_nonlvl by exact Hlvo.
          reflexivity. }
        { cbn [flat_res] in IHf.
          xrewrite IHf.
          cbv beta iota. reflexivity. }
Qed.
Lemma leaf_act_flat_z : forall sg s f,
  sg_wf sg -> keys_big sg ->
  nbrs1z sg s ->
  (forall g t, s = g :: t -> ph sg g = false) ->
  leaf_act (lin_flat sg s) f
  = flat_res sg (leaf_act s f).
Proof.
  induction s as [|g t IH]; intros f HW HK HN Hh.
  - flatnil. reflexivity.
  - assert (Hph := Hh g t eq_refl).
    assert (EF : lin_flat sg (g :: t)
                 = g :: lin_flat sg t)
      by (apply flat_cons_nonph; exact Hph).
    xrewrite EF.
    destruct g as [[o z] c].
    destruct z as [|[zp|zp|]].
    + cbn [leaf_act]. reflexivity.
    + cbn [leaf_act]. reflexivity.
    + destruct zp as [zq|zq|].
      * cbn [leaf_act]. reflexivity.
      * cbn [leaf_act]. reflexivity.
      * destruct c as [|[cp|cp|]].
        -- cbn [leaf_act]. reflexivity.
        -- cbn [leaf_act]. reflexivity.
        -- cbn [leaf_act]. reflexivity.
        -- destruct ((5 <=? o) && negb (o =? 8) && negb (o =? 12))%N
             eqn:EO.
           ++ assert (Hsp0 : is_spc (o,2%N,1%N) = false).
              { pose proof EO as EO2.
                apply andb_prop in EO2. destruct EO2 as [EO2 _].
                apply andb_prop in EO2. destruct EO2 as [_ Ho8].
                unfold is_spc.
                cbn [gO gZ gC].
                destruct (o =? 8)%N; [discriminate|].
                cbn [andb]. reflexivity. }
              apply leaf_act_flat_z2_z; try assumption.
              intros f'.
              apply IH; try assumption.
              ** exact (nbrs1z_tail _ _ _ HN).
              ** intros g' t' Et. subst t.
                 exact (nbrs_excl1z sg _ O _ _ HN eq_refl eq_refl Hsp0).
           ++ cbn [leaf_act]. rewrite EO. cbv beta iota.
              reflexivity.
    + apply leaf_act_flat_z1_z; assumption.
Qed.
Lemma fire_renew_flat_z : forall n sg,
  sg_wf sg -> keys_big sg ->
  sg_live sg ->
  (forall s f,
     nbrs1z sg s ->
     (forall g t, s = g :: t -> ph sg g = false) ->
     fire_comp n (lin_flat sg s) f
     = flat_res sg (fire_comp n s f))
  /\ (forall cols s f,
     (forall t', s = (4%N,3%N,1%N) :: t' ->
        ph_notlast sg cols) ->
     nbrs1z sg s ->
     (forall g t, s = g :: t -> ph sg g = false) ->
     renew_seg n (lin_flat sg cols)
       (lin_flat sg s) f
     = flat_res sg (renew_seg n cols s f)).
Proof.
  induction n as [|n IH]; intros sg HW HK HL.
  { split; intros; reflexivity. }
  pose proof (IH sg HW HK HL) as IHp.
  destruct IHp as [IHf IHr].
  split.
  - intros s f HN Hh.
    destruct s as [|[[X z] c] rest0]; [reflexivity|].
    assert (Hph0 : ph sg (X,z,c) = false)
      by (exact (Hh _ _ eq_refl)).
    assert (EF0 : lin_flat sg ((X,z,c) :: rest0)
                  = (X,z,c) :: lin_flat sg rest0)
      by (apply flat_cons_nonph; exact Hph0).
    xrewrite EF0.
    destruct z as [|[zp|zp|]]; try reflexivity.
    destruct zp as [zp'|zp'|]; try reflexivity.
    destruct c as [|[cp|cp|]]; try reflexivity.
    cbn [fire_comp].
    destruct (negb (5 <=? X))%N eqn:E5; [reflexivity|].
    cbv beta iota.
    destruct rest0 as [|[[Y zY] cY] rest].
    {
      flatnil.
      destruct (2 <=? f)%N; [|reflexivity].
      cbn [flat_res]. f_equal. f_equal.
      flatlit. reflexivity. }
    assert (Hcasc0 : casc (X, 3%N, 1%N) = false)
      by (exact (z31_noncasc X)).
    assert (Hsph : is_spc (X,3%N,1%N) = false).
    { unfold is_spc. cbn [gO gZ gC].
      change ((3 =? 2)%N) with false.
      rewrite andb_false_r. cbn [andb]. reflexivity. }
    assert (Hph1 : ph sg (Y,zY,cY) = false)
      by (exact (nbrs_excl1z sg _ O _ _ HN eq_refl eq_refl Hsph)).
    assert (EF1 : lin_flat sg ((Y,zY,cY) :: rest)
                  = (Y,zY,cY) :: lin_flat sg rest)
      by (apply flat_cons_nonph; exact Hph1).
    xrewrite EF1.
    destruct ((Y =? 4) && (zY =? 2))%N eqn:EY4.
    2:{ cbv beta iota.
        destruct ((Y =? 8) && (zY =? 2) && (cY =? 1))%N eqn:EY8.
        {
          cbv beta iota zeta.
          apply andb_prop in EY8. destruct EY8 as [EY8 EcY1].
          apply andb_prop in EY8. destruct EY8 as [EYo8 EYz2].
          apply N.eqb_eq in EYo8, EYz2, EcY1. subst Y zY cY.
          unfold tick_target.
          cbn [skipn].
          assert (ETTF := tick_target_s_flat sg rest
                            2%nat 2%nat HW).
          xrewrite ETTF.
          destruct (tick_target_s rest 2%nat) as [i|] eqn:ETT;
            repeat (xrewrite ETT).
          2:{ cbv beta iota. reflexivity. }
          cbv beta iota.
          destruct (tts_spec rest 2%nat i ETT)
            as (Hi2 & gt & Hgt & Hcgt & Hntgt).
          assert (Hphgt : ph sg gt = false).
          { exact (notag_ph sg gt Hntgt). }
          assert (EWC : wat (((X-1)%N,1%N,1%N) :: (11%N,2%N,1%N)
                                    :: rest) i
                        = Some gt).
          { unfold wat.
            replace i with (2 + (i - 2))%nat by lia.
            cbn [Nat.add nth_error]. exact Hgt. }
          assert (EWF : wat (((X-1)%N,1%N,1%N) :: (11%N,2%N,1%N)
                                    :: lin_flat sg rest)
                          (2 + length (lin_flat sg
                                         (firstn (i - 2)%nat rest)))%nat
                        = Some gt).
          { unfold wat.
            cbn [Nat.add nth_error].
            rewrite (flat_firstn_skipn sg rest (i - 2)%nat).
            rewrite nth_error_app2 by lia.
            rewrite PeanoNat.Nat.sub_diag.
            rewrite (nth_skipn_cons rest (i - 2)%nat gt Hgt).
            rewrite (flat_cons_nonph sg gt _ Hphgt).
            cbn [nth_error]. reflexivity. }
          xrewrite EWF.
          xrewrite EWC.
          cbv beta iota.
          destruct gt as [[og zg] cg].
          cbn [gZ] in *.
          destruct (zg =? 1)%N eqn:EZ1.
          2:{ cbv beta iota. reflexivity. }
          cbv beta iota.
          apply N.eqb_eq in EZ1. subst zg.
          destruct n as [|n'].
          { cbn [deliver_tick]. cbv beta iota. reflexivity. }
          cbn [deliver_tick].
          xrewrite EWF.
          xrewrite EWC.
          cbv beta iota.
          change ((1 =? 1)%N) with true.
          cbn [andb].
          destruct (2 <=? og)%N eqn:EO2.
          2:{ cbv beta iota. reflexivity. }
          cbv beta iota.
          assert (ESC : skipn i (((X-1)%N,1%N,1%N) :: (11%N,2%N,1%N)
                                   :: rest)
                        = skipn (i - 2)%nat rest).
          { set (m := (i - 2)%nat).
            replace i with (2 + m)%nat by (unfold m; lia).
            cbn [Nat.add skipn]. reflexivity. }
          xrewrite ESC.
          assert (ESF : skipn (2 + length (lin_flat sg
                                  (firstn (i - 2)%nat rest)))%nat
                          (((X-1)%N,1%N,1%N) :: (11%N,2%N,1%N)
                             :: lin_flat sg rest)
                        = lin_flat sg (skipn (i - 2)%nat rest)).
          { cbn [Nat.add skipn].
            rewrite (flat_skipn sg rest (i - 2)%nat).
            reflexivity. }
          xrewrite ESF.
          assert (HEq3 : (X,3%N,1%N) :: (8%N,2%N,1%N) :: rest
                         = ((X,3%N,1%N) :: (8%N,2%N,1%N)
                            :: firstn (i - 2)%nat rest)
                           ++ (og,1%N,cg) :: skipn (S (i - 2))%nat rest).
          { cbn [app]. f_equal. f_equal.
            transitivity (firstn (i - 2)%nat rest
                          ++ skipn (i - 2)%nat rest).
            { symmetry. apply firstn_skipn. }
            f_equal.
            exact (nth_skipn_cons rest (i - 2)%nat (og,1%N,cg) Hgt). }
          assert (HNk : nbrs1z sg
                          (skipn (i - 2)%nat rest)).
          { rewrite (nth_skipn_cons rest (i - 2)%nat (og,1%N,cg) Hgt).
            exact (nbrs1z_app_r sg _ _
                    (nbrs1z_at_eq sg _ _ HN HEq3)). }
          assert (Hhk : forall g t,
                    skipn (i - 2)%nat rest = g :: t ->
                    ph sg g = false).
          { intros g t E.
            rewrite (nth_skipn_cons rest (i - 2)%nat (og,1%N,cg) Hgt)
              in E.
            injection E as E1 E2. subst g. exact Hphgt. }
          assert (ELFT : leaf_act
