          try (xrewrite EDC). cbv beta iota.
          assert (EW42 : forallb w42 (lin_flat sg cols2)
                         = forallb w42 cols2).
          { apply (w42_forallb_flat sg cols2 HW HNc2).
            intros p g Hp Hph.
            exact (proj1 (HNc2 p g Hp Hph)). }
          xrewrite EW42.
          destruct (forallb w42 cols2) eqn:EW;
            repeat (xrewrite EW).
          2:{ cbv beta iota. reflexivity. }
          cbv beta iota.
          rewrite (lawR_wrap sg cols B HW HK HPnl).
          destruct (lawR_seg cols B) as [seg2|] eqn:ELR2.
          { try (xrewrite ELR2). cbv beta iota. pfxpush HK. }
          try (xrewrite ELR2). cbv beta iota. reflexivity. }
      cbv beta iota.
      rewrite (flat_nilb sg rest2 HW).
      destruct ((z5 =? 3) && (B =? 1)
                && match rest2 with [] => true | _ :: _ => false end
                && (f =? 4) && (1 <=? o5))%N eqn:EREN.
      { cbv beta iota.
        rewrite (endY_wrap sg cols o5 HW HK HPnl).
        destruct (endY_seg cols o5) as [seg2|] eqn:EEY.
        2:{ try (xrewrite EEY). reflexivity. }
        try (xrewrite EEY).
        cbv beta iota. pfxpush HK. }
      cbv beta iota.
      assert (ELF : leaf_act
                      (lin_flat sg
                         ((o4,z4,c4) :: (o5,z5,B) :: rest2)) f
                    = flat_res sg
                        (leaf_act ((o4,z4,c4) :: (o5,z5,B) :: rest2) f))
        by (apply leaf_act_flat_z;
            [exact HW|exact HK|exact HN2
            |ltac:(intros g' t' E'; injection E' as E1 E2; subst; exact Hph4)]).
      rewrite (flat_cons_nonph sg (o4,z4,c4) _ Hph4) in ELF.
      rewrite (flat_cons_nonph sg (o5,z5,B) _ Hph5) in ELF.
      xrewrite ELF.
      destruct (leaf_act ((o4,z4,c4) :: (o5,z5,B) :: rest2) f)
        as [[s2' f']|] eqn:ELA.
      2:{ try (xrewrite ELA). reflexivity. }
      try (xrewrite ELA).
      cbv beta iota. pfxpush HK. }
    destruct ((o4 =? 4) && (z4 =? 4) && (c4 =? 1))%N eqn:E44.
    {
      cbv beta iota.
      assert (HPnl : ph_notlast sg cols).
      { apply andb_prop in E44. destruct E44 as [E44' Ec41].
        apply andb_prop in E44'. destruct E44' as [Eo44 Ez44].
        apply N.eqb_eq in Eo44, Ez44, Ec41.
        pose proof (nbrs1z_seek_notlast sg (gr1 :: rest') (o4,z4,c4)
                      s2t HNr ltac:(rewrite ESK; reflexivity)
                      ltac:(subst o4 z4 c4; reflexivity)
                      ltac:(subst z4; cbn [gZ]; lia)) as H0.
        rewrite ESK in H0. cbn [fst] in H0. exact H0. }
      destruct s2t as [|[[on zn] cn] t2]; [reflexivity|].
      assert (Hphn : ph sg (on,zn,cn) = false)
        by (exact (nbrs_excl1z sg _ O _ _ HN2 eq_refl eq_refl
                     (noncasc_nonspc _ Hnc4))).
      assert (EFSN : lin_flat sg ((on,zn,cn) :: t2)
                     = (on,zn,cn) :: lin_flat sg t2)
        by (apply flat_cons_nonph; exact Hphn).
      xrewrite EFSN. cbv beta iota.
      destruct ((on =? 4) && (zn =? 2) && (1 <=? cn))%N eqn:ECN;
        [|reflexivity].
      cbv beta iota.
      apply andb_prop in ECN. destruct ECN as [ECN E1cn].
      apply andb_prop in ECN. destruct ECN as [ENo ENz].
      apply N.eqb_eq in ENo, ENz. subst on zn.
      rewrite (jump_wrap sg cols cn HW HK HPnl).
      destruct (jump_seg cols cn) as [seg2|] eqn:EJP.
      2:{ try (xrewrite EJP). reflexivity. }
      try (xrewrite EJP).
      cbv beta iota. pfxpush HK. }
    cbv beta iota.
    assert (EFRC : fire_comp n
                     (lin_flat sg ((o4,z4,c4) :: s2t)) f
                   = flat_res sg
                       (fire_comp n ((o4,z4,c4) :: s2t) f))
      by (exact (IHf ((o4,z4,c4) :: s2t) f HN2
                   ltac:(intros g' t' E'; injection E' as E1 E2; subst; exact Hph4))).
    rewrite (flat_cons_nonph sg (o4,z4,c4) _ Hph4) in EFRC.
    xrewrite EFRC.
    destruct (fire_comp n ((o4,z4,c4) :: s2t) f)
      as [[s2' f']|] eqn:EFC2.
    { try (xrewrite EFC2). cbv beta iota. pfxpush HK. }
    try (xrewrite EFC2).
    cbn [flat_res]. cbv beta iota.
    assert (ELF2 : leaf_act
                     (lin_flat sg ((o4,z4,c4) :: s2t)) f
                   = flat_res sg
                       (leaf_act ((o4,z4,c4) :: s2t) f))
      by (apply leaf_act_flat_z;
          [exact HW|exact HK|exact HN2
          |ltac:(intros g' t' E'; injection E' as E1 E2; subst; exact Hph4)]).
    rewrite (flat_cons_nonph sg (o4,z4,c4) _ Hph4) in ELF2.
    xrewrite ELF2.
    destruct (leaf_act ((o4,z4,c4) :: s2t) f)
      as [[s2' f']|] eqn:ELA.
    2:{ try (xrewrite ELA). reflexivity. }
    try (xrewrite ELA).
    cbv beta iota. pfxpush HK.
  - intros cols s f HPnlC KN Hh.
    destruct s as [|[[o0 z0] c_0] rest]; [reflexivity|].
    assert (Hph0' : ph sg (o0,z0,c_0) = false)
      by (exact (Hh _ _ eq_refl)).
    assert (EF0' : lin_flat sg ((o0,z0,c_0) :: rest)
                  = (o0,z0,c_0) :: lin_flat sg rest)
      by (apply flat_cons_nonph; exact Hph0').
    xrewrite EF0'.
    destruct o0 as [|o1]; try reflexivity.
    destruct o1 as [o1|o1|]; try reflexivity.
    destruct o1 as [o1|o1|]; try reflexivity.
    destruct o1 as [o1|o1|]; try reflexivity.
    destruct z0 as [|z1]; try reflexivity.
    destruct z1 as [z1|z1|]; try reflexivity.
    destruct z1 as [z1|z1|]; try reflexivity.
    destruct c_0 as [|c1]; try reflexivity.
    destruct c1 as [c1|c1|]; try reflexivity.
    assert (HPnl : ph_notlast sg cols)
      by (exact (HPnlC _ eq_refl)).
    cbn [renew_seg].
    assert (Hnc43 : casc (4%N, 3%N, 1%N) = false)
      by (exact (z31_noncasc 4%N)).
    destruct rest as [|[[o5 z5] B] rest2].
    {
      flatnil.
      rewrite (endR_wrap sg cols f HW HK HPnl).
      destruct (endR_seg cols f) as [body|] eqn:EER.
      2:{ try (xrewrite EER). reflexivity. }
      try (xrewrite EER).
      cbv beta iota. cbn [flat_res]. reflexivity. }
    assert (Hsph : is_spc (4%N,3%N,1%N) = false)
      by reflexivity.
    assert (Hph5 : ph sg (o5,z5,B) = false)
      by (exact (nbrs_excl1z sg _ O _ _ KN eq_refl eq_refl Hsph)).
    assert (EFS5 : lin_flat sg ((o5,z5,B) :: rest2)
                   = (o5,z5,B) :: lin_flat sg rest2)
      by (apply flat_cons_nonph; exact Hph5).
    xrewrite EFS5. cbv beta iota.
    destruct ((o5 =? 4) && (z5 =? 2) && (1 <=? B))%N eqn:E52.
    { cbv beta iota.
      apply andb_prop in E52. destruct E52 as [E52 E1B].
      apply andb_prop in E52. destruct E52 as [E5o E5z].
      apply N.eqb_eq in E5o, E5z. subst o5 z5.
      destruct rest2 as [|gr2 rest2t].
      {
        flatnil.
        destruct (f =? 4)%N.
        { rewrite (lawR_wrap sg cols B HW HK HPnl).
          destruct (lawR_seg cols B) as [body|] eqn:ELR.
          2:{ try (xrewrite ELR). reflexivity. }
          try (xrewrite ELR).
          cbv beta iota. cbn [flat_res]. reflexivity. }
        destruct (5 <=? f)%N; [|reflexivity].
        rewrite (jump_wrap sg cols B HW HK HPnl).
        destruct (jump_seg cols B) as [seg|] eqn:EJP.
        2:{ try (xrewrite EJP). reflexivity. }
        try (xrewrite EJP).
        cbv beta iota. cbn [flat_res]. f_equal. f_equal.
        rewrite ?lin_flat_app_c.
        f_equal.
        repeat first [fsmall HK|flatc HK|plit]; try reflexivity. }
      assert (Hphg2 : ph sg gr2 = false)
        by (exact (nbrs_excl1z sg _ 1%nat _ _ KN eq_refl eq_refl
                     eq_refl)).
      assert (EFG2 : lin_flat sg (gr2 :: rest2t)
                     = gr2 :: lin_flat sg rest2t)
        by (apply flat_cons_nonph; exact Hphg2).
      xrewrite EFG2. cbv beta iota.
      rewrite (jump_wrap sg cols B HW HK HPnl).
      destruct (jump_seg cols B) as [seg|] eqn:EJS.
      2:{ try (xrewrite EJS). reflexivity. }
      try (xrewrite EJS).
      cbv beta iota.
      destruct (seek (gr2 :: rest2t)) as [cols2 s3] eqn:ESK2.
      assert (ESKF2 : seek (gr2 :: lin_flat sg rest2t)
                      = (lin_flat sg cols2,
                         lin_flat sg s3)).
      { rewrite <- EFG2.
        rewrite (seek_flat sg (gr2 :: rest2t) HW).
        rewrite ESK2. reflexivity. }
      xrewrite ESKF2. cbv beta iota.
      pose proof (LineageGuard_seek_split (gr2 :: rest2t)) as HSPL2.
      rewrite ESK2 in HSPL2. cbn [fst snd] in HSPL2.
      assert (HNr2 : nbrs1z sg (gr2 :: rest2t))
        by (exact (nbrs1z_tail sg _ _
                    (nbrs1z_tail sg _ _ KN))).
      assert (HEq2 : gr2 :: rest2t = cols2 ++ s3)
        by (exact HSPL2).
      assert (HN3 : nbrs1z sg s3)
        by (exact (nbrs1z_app_r sg cols2 s3
                    (nbrs1z_at_eq sg _ _ HNr2 HEq2))).
      assert (Hh3 : forall g t, s3 = g :: t ->
                      ph sg g = false).
      { intros g7 s3t E7.
        assert (Hst7 : seektest g7 = false)
          by (apply (seek_snd_head (gr2 :: rest2t)
                       g7 s3t);
              rewrite ESK2; cbn [snd]; rewrite E7; reflexivity).
        pose proof (seektest_noncasc _ Hst7) as Hnc7.
        destruct (ph sg g7) eqn:EP; [|reflexivity].
        rewrite (ph_seektest sg _ EP) in Hst7.
        discriminate. }
      assert (HPnlC2 : forall t', s3 = (4%N,3%N,1%N) :: t' ->
                ph_notlast sg cols2).
      { intros t' E3.
        pose proof (nbrs1z_seek_notlast sg (gr2 :: rest2t)
                      (4%N,3%N,1%N) t' HNr2
                      ltac:(rewrite ESK2; cbn [snd]; rewrite E3;
                            reflexivity)
                      ltac:(reflexivity)
                      ltac:(cbn [gZ]; lia)) as H0.
        rewrite ESK2 in H0. cbn [fst] in H0. exact H0. }
      assert (ERN := IHr cols2 s3 f HPnlC2 HN3 Hh3).
      xrewrite ERN.
      destruct (renew_seg n cols2 s3 f) as [[body f']|] eqn:ERN2.
      { try (xrewrite ERN2). cbv beta iota.
        cbn [flat_res]. f_equal. f_equal.
        rewrite ?lin_flat_app_c.
        rewrite <- ?app_assoc.
        repeat first [fsmall HK|flatc HK|plit]; try reflexivity. }
      try (xrewrite ERN2). cbv beta iota.
      destruct s3 as [|[[o7 z7] c7] s3t].
      {
        assert (HNc2 : ph_nbrs sg cols2).
        { pose proof (nbrs1z_seek_all sg (gr2 :: rest2t) HNr2
                        ltac:(rewrite ESK2; reflexivity)) as H0.
          rewrite ESK2 in H0. cbn [fst] in H0. exact H0. }
        flatnil. cbv beta iota.
        cbn [leaf_act]. cbv beta iota.
        destruct (5 <=? f)%N.
        { cbv beta iota. cbn [flat_res]. f_equal. f_equal.
          rewrite ?lin_flat_app_c.
          rewrite <- ?app_assoc.
          repeat first [fsmall HK|flatc HK|plit]; try reflexivity. }
        destruct (f =? 4)%N; [|cbv beta iota; reflexivity].
        cbv beta iota.
        pose proof ((dtb4_conv_flat sg cols2 HW HK HNc2))
          as ED4.
        xrewrite ED4.
        destruct (dtb4_conv cols2) as [cols2'|] eqn:EDC.
        { try (xrewrite EDC). cbv beta iota.
          cbn [flat_res]. f_equal. f_equal.
          rewrite ?lin_flat_app_c.
          rewrite <- ?app_assoc.
          repeat first [fsmall HK|flatc HK|plit]; try reflexivity. }
        try (xrewrite EDC). cbv beta iota.
        assert (EW42 : forallb w42 (lin_flat sg cols2)
                       = forallb w42 cols2).
        { apply (w42_forallb_flat sg cols2 HW HNc2).
          intros p g Hp Hph.
          exact (proj1 (HNc2 p g Hp Hph)). }
        xrewrite EW42.
        destruct (forallb w42 cols2) eqn:EW;
          repeat (xrewrite EW).
        2:{ cbv beta iota. reflexivity. }
        cbv beta iota.
        rewrite (lawR_wrap sg cols B HW HK HPnl).
        destruct (lawR_seg cols B) as [seg2|] eqn:ELR2.
        { try (xrewrite ELR2). cbv beta iota.
          cbn [flat_res]. f_equal. f_equal.
          rewrite ?lin_flat_app_c.
          rewrite <- ?app_assoc.
          repeat first [fsmall HK|flatc HK|plit]; try reflexivity. }
        try (xrewrite ELR2). cbv beta iota. reflexivity. }
      assert (Hst7 : seektest (o7,z7,c7) = false)
        by (apply (seek_snd_head (gr2 :: rest2t)
                     (o7,z7,c7) s3t);
            rewrite ESK2; reflexivity).
      assert (Hnc7 : casc (o7,z7,c7) = false)
        by (exact (seektest_noncasc _ Hst7)).
      assert (Hph7 : ph sg (o7,z7,c7) = false).
      { destruct (ph sg (o7,z7,c7)) eqn:E; [|reflexivity].
        rewrite (ph_seektest sg _ E) in Hst7. discriminate. }
      assert (EFS7 : lin_flat sg ((o7,z7,c7) :: s3t)
                     = (o7,z7,c7) :: lin_flat sg s3t)
        by (apply flat_cons_nonph; exact Hph7).
      xrewrite EFS7. cbv beta iota.
      destruct ((z7 =? 3) && (c7 =? 1))%N eqn:E73.
      {
        cbv beta iota.
        assert (EFI : fire_comp n
                        (lin_flat sg ((o7,z7,c7) :: s3t)) f
                      = flat_res sg
                          (fire_comp n ((o7,z7,c7) :: s3t) f))
          by (exact (IHf ((o7,z7,c7) :: s3t) f HN3 Hh3)).
        rewrite (flat_cons_nonph sg (o7,z7,c7) _ Hph7)
          in EFI.
        xrewrite EFI.
        destruct (fire_comp n ((o7,z7,c7) :: s3t) f)
          as [[s3' f3']|] eqn:EFC3.
        { try (xrewrite EFC3). cbv beta iota.
          cbn [flat_res]. f_equal. f_equal.
          rewrite ?lin_flat_app_c.
          rewrite <- ?app_assoc.
          repeat first [fsmall HK|flatc HK|plit]; try reflexivity. }
        try (xrewrite EFC3). cbv beta iota. reflexivity. }
      cbv beta iota.
      assert (ESL : sand_leaf
                      ((o7,z7,c7) :: lin_flat sg s3t)
                    = sand_leaf ((o7,z7,c7) :: s3t)).
      { rewrite <- EFS7.
        apply sand_leaf_flat; [exact HW|].
        intros g t E. injection E as <- E2. exact Hph7. }
      xrewrite ESL.
      destruct (sand_leaf ((o7,z7,c7) :: s3t)) eqn:ES1;
        repeat (xrewrite ES1).
      { cbv beta iota. reflexivity. }
      cbv beta iota.
      assert (ELF3 : leaf_act
                       ((o7,z7,c7) :: lin_flat sg s3t) f
                     = flat_res sg
                         (leaf_act ((o7,z7,c7) :: s3t) f)).
      { rewrite <- EFS7.
        apply leaf_act_flat_z;
          [exact HW|exact HK|exact HN3|exact Hh3]. }
      xrewrite ELF3.
      destruct (leaf_act ((o7,z7,c7) :: s3t) f)
        as [[s3' f3']|] eqn:ELA3.
      { try (xrewrite ELA3). cbv beta iota.
        cbn [flat_res]. f_equal. f_equal.
        rewrite ?lin_flat_app_c.
        rewrite <- ?app_assoc.
        repeat first [fsmall HK|flatc HK|plit]; try reflexivity. }
      try (xrewrite ELA3). cbv beta iota. reflexivity. }
    cbv beta iota.
    rewrite (flat_nilb sg rest2 HW).
    match goal with
    | |- (if ?X then _ else _) = _ => destruct X eqn:EREN
    end.
    { cbv beta iota.
      rewrite (endY_wrap sg cols o5 HW HK HPnl).
      destruct (endY_seg cols o5) as [body|] eqn:EEY.
      2:{ try (xrewrite EEY). reflexivity. }
      try (xrewrite EEY).
      cbv beta iota. cbn [flat_res]. reflexivity. }
    cbv beta iota. reflexivity.
Qed.
Lemma round_leaf_flat_z : forall sg cols s f,
  sg_wf sg -> keys_big sg ->
  nbrs1z sg s ->
  (forall g t, s = g :: t -> ph sg g = false) ->
  (match leaf_act (lin_flat sg s) f with
   | Some (s2, f2) => Some (lin_flat sg cols ++ s2, f2)
   | None => None
   end)
  = flat_res sg
      (match leaf_act s f with
       | Some (s2, f2) => Some (cols ++ s2, f2)
       | None => None
       end).
Proof.
  intros sg cols s f HW HK HN Hh.
  rewrite (leaf_act_flat_z sg s f HW HK HN Hh).
  destruct (leaf_act s f) as [[s2 f2]|]; [|reflexivity].
  cbn [flat_res].
  f_equal. f_equal.
  rewrite lin_flat_app_c. reflexivity.
Qed.
Lemma round_at_flat_z : forall sg cols s f,
  sg_wf sg -> keys_big sg ->
  sg_live sg ->
  (forall t', s = (4%N,3%N,1%N) :: t' ->
     ph_notlast sg cols) ->
  nbrs1z sg s ->
  (forall g t, s = g :: t -> ph sg g = false) ->
  round_at (lin_flat sg cols) (lin_flat sg s) f
  = flat_res sg (round_at cols s f).
Proof.
  intros sg cols s f HW HK HL HPnC HN Hh.
  destruct s as [|[[og zg] cg] t]; [reflexivity|].
  assert (Hph : ph sg (og,zg,cg) = false)
    by (exact (Hh _ _ eq_refl)).
  assert (EF : lin_flat sg ((og,zg,cg) :: t)
               = (og,zg,cg) :: lin_flat sg t)
    by (apply flat_cons_nonph; exact Hph).
  unfold round_at.
  xrewrite EF.
  assert (LEAF : forall (zc : N) (cc : N),
      zg = zc -> cg = cc ->
      (match leaf_act ((og,zg,cg) :: lin_flat sg t) f with
       | Some (s2, f2) => Some (lin_flat sg cols ++ s2, f2)
       | None => None
       end)
      = flat_res sg
          (match leaf_act ((og,zg,cg) :: t) f with
           | Some (s2, f2) => Some (cols ++ s2, f2)
           | None => None
           end)).
  { intros zc cc _ _.
    pose proof (round_leaf_flat_z sg cols ((og,zg,cg) :: t) f
                  HW HK HN Hh) as ELFI.
    xrewrite_in ELFI
      (flat_cons_nonph sg (og,zg,cg) t Hph).
    exact ELFI. }
  destruct zg as [|z1]; [exact (LEAF 0%N cg eq_refl eq_refl)|].
  destruct z1 as [z1|z1|];
    [|exact (LEAF _ cg eq_refl eq_refl)
     |exact (LEAF _ cg eq_refl eq_refl)].
  destruct z1 as [z1|z1|];
    [exact (LEAF _ cg eq_refl eq_refl)
    |exact (LEAF _ cg eq_refl eq_refl)|].
  destruct cg as [|c1]; [exact (LEAF _ _ eq_refl eq_refl)|].
  destruct c1 as [c1|c1|];
    [exact (LEAF _ _ eq_refl eq_refl)
    |exact (LEAF _ _ eq_refl eq_refl)|].
  clear LEAF.
  cbv beta iota.
  assert (EREN : renew_seg
                   (length ((og,3%N,1%N) :: lin_flat sg t))
                   (lin_flat sg cols)
                   ((og,3%N,1%N) :: lin_flat sg t) f
                 = flat_res sg
                     (renew_seg (length ((og,3%N,1%N) :: t))
                        cols ((og,3%N,1%N) :: t) f)).
  { pose proof (proj2 (fire_renew_flat_z
                         (length ((og,3%N,1%N) :: lin_flat sg t))
                         sg HW HK HL)
                  cols ((og,3%N,1%N) :: t) f
                    ltac:(intros t' E; exact (HPnC t' E)) HN Hh)
        as E0.
    xrewrite_in E0
      (flat_cons_nonph sg (og,3%N,1%N) t Hph).
    xrewrite E0.
    f_equal.
    apply renew_seg_sat.
    cbn [length].
    apply le_n_S. exact (flat_len_ge sg t HW). }
  xrewrite EREN.
  destruct (renew_seg (length ((og,3%N,1%N) :: t)) cols
              ((og,3%N,1%N) :: t) f) as [[body f2]|] eqn:ER;
    repeat (xrewrite ER).
  { cbn [flat_res]. reflexivity. }
  cbn [flat_res]. cbv beta iota.
  assert (EFIR : fire_comp
                   (length ((og,3%N,1%N) :: lin_flat sg t))
                   ((og,3%N,1%N) :: lin_flat sg t) f
                 = flat_res sg
                     (fire_comp (length ((og,3%N,1%N) :: t))
                        ((og,3%N,1%N) :: t) f)).
  { pose proof (proj1 (fire_renew_flat_z
                         (length ((og,3%N,1%N) :: lin_flat sg t))
                         sg HW HK HL)
                  ((og,3%N,1%N) :: t) f HN Hh) as E0.
    xrewrite_in E0
      (flat_cons_nonph sg (og,3%N,1%N) t Hph).
    xrewrite E0.
    f_equal.
    apply fire_comp_sat.
    cbn [length].
    apply le_n_S. exact (flat_len_ge sg t HW). }
  xrewrite EFIR.
  destruct (fire_comp (length ((og,3%N,1%N) :: t))
              ((og,3%N,1%N) :: t) f) as [[s2 f2]|] eqn:EFC;
    repeat (xrewrite EFC).
  2:{ cbn [flat_res]. reflexivity. }
  cbn [flat_res]. cbv beta iota.
  f_equal. f_equal.
  rewrite lin_flat_app_c. reflexivity.
Qed.
Open Scope N_scope.
Open Scope bool_scope.
Opaque LROUND_FUEL LROUND_CHUNKS
       FLAT_ROUND_FUEL CFUEL TRIES.
Lemma tagbase_c : forall o z c c',
  tagbase (o,z,c) = tagbase (o,z,c').
Proof. reflexivity. Qed.
Lemma flat_cons_ctx : forall sg g w1 w2 f,
  sdecode (lin_flat sg w1) f
  = sdecode (lin_flat sg w2) f ->
  sdecode (lin_flat sg (g :: w1)) f
  = sdecode (lin_flat sg (g :: w2)) f.
Proof.
  intros sg g w1 w2 f H. cbn [lin_flat].
  destruct (keyb sg g) as [body|].
  - exact (sdecode_app_ctx body _ _ f H).
  - exact (sdecode_app_ctx [g] _ _ f H).
Qed.
Lemma flat_head_notagbase : forall sg o z c w f,
  tagbase (o,z,c) = false ->
  sdecode (lin_flat sg ((o,z,c) :: w)) f
  = gdec1 (o,z,c) ++ sdecode (lin_flat sg w) f.
Proof.
  intros sg o z c w f HB.
  rewrite flat_cons_nonlvl.
  - apply sdecode_cons.
  - unfold phshape, tagbase in *.
    cbn [gO gZ gC] in *. rewrite HB. reflexivity.
Qed.
Lemma lin_normalize_full_hd : forall g t,
  exists c r, lin_normalize_full (g :: t) =
    (gO g, gZ g, c) :: r.
Proof.
  intros [[o z] c] t. cbn [lin_normalize_full].
  destruct (lin_normalize_full t) as [|[[o2 z2] c2] r].
  - exists c, ([] : word). reflexivity.
  - destruct (tagbase (o,z,c) ||
              tagbase (o2,z2,c2));
      [exists c, ((o2,z2,c2) :: r); reflexivity|].
    destruct ((o =? o2) && (z =? z2))%N;
      [exists (c+c2), r|exists c, ((o2,z2,c2) :: r)]; reflexivity.
Qed.
Lemma phshape_false_of_tagbase_false : forall g,
  tagbase g = false -> phshape g = false.
Proof.
  intros [[o z] c] H. unfold phshape, tagbase in *.
  cbn [gO gZ gC] in *.
  rewrite H. reflexivity.
Qed.
Lemma countkey_lin_normalize_full : forall k w,
  countkey k (lin_normalize_full w) =
  countkey k w.
Proof.
  intros k w. induction w as [|[[o1 z1] c1] t IH]; [reflexivity|].
  cbn [lin_normalize_full].
  destruct (lin_normalize_full t) as [|[[o2 z2] c2] r] eqn:E.
  - cbn [countkey] in IH |- *. lia.
  - destruct (tagbase (o1,z1,c1) ||
              tagbase (o2,z2,c2)) eqn:ET.
    + cbn [countkey] in IH |- *. lia.
    + apply orb_false_iff in ET as [ET1 ET2].
      pose proof (phshape_false_of_tagbase_false _ ET1) as EP1.
      pose proof (phshape_false_of_tagbase_false _ ET2) as EP2.
      destruct ((o1 =? o2) && (z1 =? z2))%N eqn:EOZ.
      * apply andb_prop in EOZ as [EO EZ].
        apply N.eqb_eq in EO, EZ. subst o2 z2.
        assert (EPM : phshape (o1,z1,c1+c2) = false).
        { apply phshape_false_of_tagbase_false.
          rewrite (tagbase_c o1 z1 (c1+c2) c1). exact ET1. }
        cbn [countkey] in IH |- *.
        rewrite EP2 in IH. cbn [andb] in IH.
        rewrite EP1, EPM. cbn [andb]. exact IH.
      * cbn [countkey] in IH |- *. lia.
Qed.
Lemma lin_ok_lin_normalize_full : forall sg w,
  lin_ok sg (lin_normalize_full w) =
  lin_ok sg w.
Proof.
  intros sg w. unfold lin_ok.
  induction sg as [|s sg IH]; [reflexivity|].
  cbn [forallb]. rewrite IH, countkey_lin_normalize_full. reflexivity.
Qed.
Lemma flat_lin_normalize_full_sd : forall sg w f,
  sdecode (lin_flat sg (lin_normalize_full w)) f =
  sdecode (lin_flat sg w) f.
Proof.
  intros sg w. induction w as [|[[o1 z1] c1] t IH]; intros f;
    [reflexivity|].
  cbn [lin_normalize_full].
  destruct (lin_normalize_full t) as [|[[o2 z2] c2] r] eqn:E.
  - exact (flat_cons_ctx sg (o1,z1,c1) _ _ f (IH f)).
  - destruct (tagbase (o1,z1,c1) ||
              tagbase (o2,z2,c2)) eqn:ET.
    + exact (flat_cons_ctx sg (o1,z1,c1) _ _ f (IH f)).
    + apply orb_false_iff in ET as [ET1 ET2].
      destruct ((o1 =? o2) && (z1 =? z2))%N eqn:EOZ.
      * apply andb_prop in EOZ as [EO EZ].
        apply N.eqb_eq in EO, EZ. subst o2 z2.
        assert (HB : forall c, tagbase (o1,z1,c) = false).
        { intros c. rewrite (tagbase_c o1 z1 c c1). exact ET1. }
        etransitivity.
        { apply (flat_head_notagbase sg o1 z1 (c1+c2) r f (HB _)). }
        symmetry.
        etransitivity.
        { apply (flat_head_notagbase sg o1 z1 c1
                   t f (HB _)). }
        etransitivity.
        { apply (f_equal (fun u => gdec1 (o1,z1,c1) ++ u)
                   (eq_sym (IH f))). }
        etransitivity.
        { apply (f_equal (fun u => gdec1 (o1,z1,c1) ++ u)
                   (flat_head_notagbase sg o1 z1 c2 r f (HB _))). }
        etransitivity; [apply app_assoc|].
        apply (f_equal
          (fun u => u ++ sdecode (lin_flat sg r) f)).
        symmetry. apply gdec1_merge.
      * exact (flat_cons_ctx sg (o1,z1,c1) _ _ f (IH f)).
Qed.
Lemma lin_normalize_full_sound : forall sg w f,
  sound_impl (lin_flat sg w) f
    (lin_flat sg (lin_normalize_full w)) f.
Proof.
  intros sg w f H. unfold sound_impl in *.
  rewrite flat_lin_normalize_full_sd in H. exact H.
Qed.
Fixpoint lin_ptags (sg : list seg) (w : word) : bool :=
  match w with
  | [] => true
  | g :: t => (negb (phshape g) || ph sg g)
              && lin_ptags sg t
  end.
Lemma phshape_tagbase : forall g,
  phshape g = true -> tagbase g = true.
Proof.
  intros [[o z] c] H. unfold phshape, tagbase in *.
  cbn [gO gZ gC] in *.
  apply andb_prop in H as [H _]. exact H.
Qed.
Lemma lin_tags_ptags : forall sg w,
  lin_tags sg w = true -> lin_ptags sg w = true.
Proof.
  intros sg w. induction w as [|g w IH]; intros HT; [reflexivity|].
  cbn [lin_tags] in HT. apply andb_prop in HT as [Hg HT].
  cbn [lin_ptags]. apply andb_true_intro. split; [|exact (IH HT)].
  destruct (phshape g) eqn:EP; [|reflexivity].
  pose proof (phshape_tagbase g EP) as EB. rewrite EB in Hg.
  cbn [negb orb] in Hg |- *. exact Hg.
Qed.
Lemma lin_ptags_app_true : forall sg a b,
  lin_ptags sg a = true -> lin_ptags sg b = true ->
  lin_ptags sg (a ++ b) = true.
Proof.
  intros sg a. induction a as [|g a IH]; intros b HA HB; [exact HB|].
  cbn [lin_ptags] in HA |- *. apply andb_prop in HA as [Hg HA].
  apply andb_true_intro. split; [exact Hg|exact (IH b HA HB)].
Qed.
Lemma lin_ptags_skipn : forall sg n w,
  lin_ptags sg w = true -> lin_ptags sg (skipn n w) = true.
Proof.
  intros sg n. induction n as [|n IH]; intros [|g w] H; try exact H;
    try reflexivity.
  cbn [lin_ptags] in H. exact (IH w (proj2 (andb_prop _ _ H))).
Qed.
Lemma lin_ptags_mono : forall sg1 sg2 w,
  (forall g, ph sg1 g = true -> ph sg2 g = true) ->
  lin_ptags sg1 w = true -> lin_ptags sg2 w = true.
Proof.
  intros sg1 sg2 w HM. induction w as [|g w IH]; intros H;
    [reflexivity|].
  cbn [lin_ptags] in H |- *. apply andb_prop in H as [Hg Hw].
  apply andb_true_intro. split; [|exact (IH Hw)].
  destruct (phshape g) eqn:EP; [|reflexivity].
  cbn [negb orb] in Hg |- *. exact (HM g Hg).
Qed.
Lemma lin_ptags_lin_normalize_full : forall sg w,
  lin_ptags sg w = true ->
  lin_ptags sg (lin_normalize_full w) = true.
Proof.
  intros sg w. induction w as [|[[o1 z1] c1] t IH]; intros HT;
    [reflexivity|].
  cbn [lin_ptags] in HT. apply andb_prop in HT as [HT1 HT].
  specialize (IH HT).
  cbn [lin_normalize_full].
  destruct (lin_normalize_full t) as [|[[o2 z2] c2] r] eqn:E.
  - cbn [lin_ptags] in IH |- *. rewrite andb_true_r. exact HT1.
  - cbn [lin_ptags] in IH. apply andb_prop in IH as [IH2 IHr].
    destruct (tagbase (o1,z1,c1) ||
              tagbase (o2,z2,c2)) eqn:ET.
    + cbn [lin_ptags]. apply andb_true_intro. split; [exact HT1|].
      cbn [lin_ptags]. apply andb_true_intro. split; assumption.
    + apply orb_false_iff in ET as [ET1 ET2].
      destruct ((o1 =? o2) && (z1 =? z2))%N eqn:EOZ.
      * apply andb_prop in EOZ as [EO EZ].
        apply N.eqb_eq in EO, EZ. subst o2 z2.
        assert (EPM : phshape (o1,z1,c1+c2) = false).
        { apply phshape_false_of_tagbase_false.
          rewrite (tagbase_c o1 z1 (c1+c2) c1). exact ET1. }
        cbn [lin_ptags]. rewrite EPM. cbn [negb orb andb]. exact IHr.
      * cbn [lin_ptags]. apply andb_true_intro. split; [exact HT1|].
        cbn [lin_ptags]. apply andb_true_intro. split; assumption.
Qed.
Open Scope N_scope.
Open Scope bool_scope.
Opaque LROUND_FUEL LROUND_CHUNKS
       FLAT_ROUND_FUEL CFUEL TRIES.
Lemma segalt_head : forall g t,
  segalt (g :: t) = true -> is_lvl g = true.
Proof.
  intros g [|s t] H; cbn [segalt] in H; [exact H|].
  repeat rewrite Bool.andb_true_iff in H. exact (proj1 (proj1 H)).
Qed.
Lemma odd_SS : forall n, Nat.odd (S (S n)) = Nat.odd n.
Proof. intros n. unfold Nat.odd. cbn [Nat.even]. reflexivity. Qed.
Lemma segalt_odd : forall b,
  segalt b = true -> Nat.odd (length b) = true.
Proof.
  fix IH 1. intros b H. destruct b as [|l [|s b']].
  - discriminate.
  - reflexivity.
  - cbn [segalt] in H. repeat rewrite Bool.andb_true_iff in H.
    cbn [length]. rewrite odd_SS. exact (IH b' (proj2 H)).
Qed.
Lemma segalt_casc : forall b,
  segalt b = true -> forallb casc b = true.
Proof.
  fix IH 1. intros b H. destruct b as [|l [|s b']].
  - discriminate.
  - cbn [segalt] in H. cbn [forallb].
    replace (casc l) with true
      by (unfold casc; rewrite H; reflexivity).
    reflexivity.
  - cbn [segalt] in H. repeat rewrite Bool.andb_true_iff in H.
    destruct H as [[Hl Hs] HA]. cbn [forallb]. rewrite (IH b' HA).
    replace (casc l) with true
      by (unfold casc; rewrite Hl; reflexivity).
    replace (casc s) with true
      by (unfold casc; rewrite Hs; symmetry; apply Bool.orb_true_r).
    reflexivity.
Qed.
Lemma segalt_last : forall b,
  segalt b = true ->
  is_lvl (nth (length b - 1) b d0) = true.
Proof.
  fix IH 1. intros b H. destruct b as [|l [|s b']].
  - discriminate.
  - cbn [segalt] in H. cbn [length nth]. exact H.
  - cbn [segalt] in H. repeat rewrite Bool.andb_true_iff in H.
    destruct H as [_ HA].
    assert (HL : (1 <= length b')%nat).
    { destruct b' as [|x b'']; [discriminate HA|cbn [length]; lia]. }
    cbn [length].
    replace (S (S (length b')) - 1)%nat
      with (S (S (length b' - 1)))%nat by lia.
    cbn [nth]. exact (IH b' HA).
Qed.
Lemma segalt_skipn2 : forall a b,
  segalt b = true -> (2 * a < length b)%nat ->
  segalt (skipn (2 * a) b) = true.
Proof.
  induction a as [|a IH]; intros b H HL.
  - replace (2 * 0)%nat with O by lia. exact H.
  - destruct b as [|l [|s b']].
    + cbn [length] in HL. lia.
    + cbn [length] in HL. lia.
    + cbn [segalt] in H. repeat rewrite Bool.andb_true_iff in H.
      replace (2 * S a)%nat with (S (S (2 * a)))%nat by lia.
      cbn [skipn]. apply IH; [exact (proj2 H)|].
      cbn [length] in HL. lia.
Qed.
Lemma segalt_firstn_odd : forall b m,
  segalt b = true -> Nat.odd m = true ->
  (m <= length b)%nat -> segalt (firstn m b) = true.
Proof.
  fix IH 1. intros b m HA HO HL. destruct b as [|l [|s b']].
  - discriminate.
  - cbn [length] in HL. destruct m as [|[|m']];
      [discriminate HO| |lia].
    cbn [firstn]. exact HA.
  - destruct m as [|[|m']].
    + discriminate HO.
    + cbn [firstn]. cbn [segalt] in *.
      repeat rewrite Bool.andb_true_iff in HA. exact (proj1 (proj1 HA)).
    + cbn [segalt] in HA. repeat rewrite Bool.andb_true_iff in HA.
      destruct HA as [[Hl Hs] HA'].
      cbn [firstn segalt]. rewrite Hl, Hs. cbn [andb].
      apply IH; [exact HA'| |cbn [length] in HL; lia].
      rewrite odd_SS in HO. exact HO.
Qed.
Lemma segalt_sub : forall b a m,
  segalt b = true -> Nat.odd m = true -> (1 <= m)%nat ->
  (2 * a + m <= length b)%nat ->
  segalt (firstn m (skipn (2 * a) b)) = true.
Proof.
  intros b a m HA HO H1 HB. apply segalt_firstn_odd.
  - apply segalt_skipn2; [exact HA|lia].
  - exact HO.
  - rewrite length_skipn. lia.
Qed.
Definition mbnd (m : N) (b : word) : bool :=
  forallb (fun g => negb (is_lvl g) || (m <=? gC g)%N) b.
Lemma segok_mbnd : forall s,
  segok s = true -> mbnd (sMin s) (sBody s) = true.
Proof.
  intros s H. unfold segok in H. cbv zeta in H.
  destruct (sBody s) as [|g0 b'] eqn:EB; [discriminate|].
  cbv beta iota in H. apply andb_prop in H as [_ H].
  unfold mbnd. exact H.
Qed.
Theorem segok_of_segalt : forall s,
  segcache s = true -> segalt (sBody s) = true ->
  mbnd (sMin s) (sBody s) = true ->
  segok s = true.
Proof.
  intros s HC HA HM. unfold mbnd in HM.
  assert (HL : length (sBody s) = sLen s).
  { unfold segcache in HC. apply PeanoNat.Nat.eqb_eq in HC.
    unfold sBody. rewrite length_app, length_rev. lia. }
  unfold segok. cbv zeta.
  destruct (sBody s) as [|g0 b'] eqn:EB.
  - cbn [segalt] in HA. discriminate HA.
  - rewrite <- HL. apply andb_true_intro. split; [|exact HM].
    apply andb_true_intro. split; [|exact (segalt_casc _ HA)].
    apply andb_true_intro. split.
    + apply andb_true_intro. split.
      * exact (segalt_head g0 b' HA).
      * exact (segalt_last _ HA).
    + exact (segalt_odd _ HA).
Qed.
Lemma lin_hasn_le : forall (A : Type) (n : nat) (xs : list A),
  lin_hasn n xs = true -> (n <= length xs)%nat.
Proof.
  induction n as [|n IH]; intros [|x xs] H.
  - cbn [length]. lia.
  - cbn [length]. lia.
  - cbn [lin_hasn] in H. discriminate.
  - cbn [lin_hasn] in H. cbn [length].
    pose proof (IH xs H). lia.
Qed.
Lemma div2_le : forall n, (Nat.div2 n <= n)%nat.
Proof.
  fix IH 1. intros [|[|n]]; cbn [Nat.div2];
    try (pose proof (IH n)); lia.
Qed.
Lemma div2_odd : forall j, Nat.div2 (2 * j + 1)%nat = j.
Proof.
  induction j as [|j IH]; [reflexivity|].
  replace (2 * S j + 1)%nat with (S (S (2 * j + 1)))%nat by lia.
  cbn [Nat.div2]. rewrite IH. reflexivity.
Qed.
Lemma odd_ex : forall l,
  Nat.odd l = true -> exists j, l = (2 * j + 1)%nat.
Proof.
  intros l H. apply PeanoNat.Nat.odd_spec in H. destruct H as (m & Hm).
  exists m. lia.
Qed.
Lemma odd_of : forall j, Nat.odd (2 * j + 1)%nat = true.
Proof. intros j. apply PeanoNat.Nat.odd_spec. exists j. lia. Qed.
Lemma split_body_join : forall b,
  fst (split_body b) ++ rev (snd (split_body b)) = b.
Proof.
  intros b. unfold split_body. cbn [fst snd].
  rewrite rev_involutive. apply firstn_skipn.
Qed.
Lemma split_body_len : forall b,
  (length (fst (split_body b)) +
   length (snd (split_body b)))%nat = length b.
Proof.
  intros b. unfold split_body. cbn [fst snd].
  rewrite length_rev, length_firstn, length_skipn.
  pose proof (div2_le (length b)). lia.
Qed.
Ltac segfields :=
  cbn [fst snd];
  unfold segcache, sBody, sFront, sBack,
         sLen, sMin, sKey, sPend;
  cbv beta iota zeta.
Lemma spill_front_body : forall s k,
  segcache s = true ->
  sBody (snd (spill_front s k)) =
    skipn (2 * k) (sBody s) /\
  sLen (snd (spill_front s k)) =
    (sLen s - 2 * k)%nat /\
  segcache (snd (spill_front s k)) = true /\
  sMin (snd (spill_front s k)) = sMin s.
Proof.
  intros [[[[[[key p] m] l] bf] bb] cs] k HC.
  unfold segcache, sLen, sFront, sBack in HC.
  cbv beta iota zeta in HC. apply PeanoNat.Nat.eqb_eq in HC.
  unfold spill_front. cbv beta zeta iota.
  destruct (lin_hasn (2 * k)%nat bf) eqn:EH.
  - pose proof (lin_hasn_le _ (2 * k)%nat bf EH) as HLE.
    segfields. split.
    { rewrite List.skipn_app.
      replace (2 * k - length bf)%nat with O by lia.
      cbn [skipn]. reflexivity. }
    split; [reflexivity|]. split; [|reflexivity].
    apply PeanoNat.Nat.eqb_eq. rewrite length_skipn. lia.
  - pose proof (split_body_join (skipn (2 * k)%nat (bf ++ rev bb))) as HJ.
    pose proof (split_body_len (skipn (2 * k)%nat (bf ++ rev bb))) as HN.
    destruct (split_body (skipn (2 * k)%nat (bf ++ rev bb)))
      as [rf rb] eqn:ES. cbn [fst snd] in HJ, HN.
    segfields. split; [exact HJ|]. split; [reflexivity|].
    split; [|reflexivity]. apply PeanoNat.Nat.eqb_eq.
    rewrite HN, length_skipn, length_app, length_rev. lia.
Qed.
Lemma spill_back_body : forall s k,
  segcache s = true ->
  sBody (fst (spill_back s k)) =
    firstn (sLen s - 2 * k) (sBody s) /\
  sLen (fst (spill_back s k)) =
    (sLen s - 2 * k)%nat /\
  segcache (fst (spill_back s k)) = true /\
  sMin (fst (spill_back s k)) = sMin s.
Proof.
  intros [[[[[[key p] m] l] bf] bb] cs] k HC.
  unfold segcache, sLen, sFront, sBack in HC.
  cbv beta iota zeta in HC. apply PeanoNat.Nat.eqb_eq in HC.
  unfold spill_back. cbv beta zeta iota.
  destruct (lin_hasn (2 * k)%nat bb) eqn:EH.
  - pose proof (lin_hasn_le _ (2 * k)%nat bb EH) as HLE.
    segfields.
    assert (HR : rev bb = rev (skipn (2 * k)%nat bb)
                           ++ rev (firstn (2 * k)%nat bb)).
    { rewrite <- rev_app_distr. rewrite firstn_skipn. reflexivity. }
    assert (HA : length (bf ++ rev (skipn (2 * k)%nat bb)) =
                 (l - 2 * k)%nat).
    { rewrite length_app, length_rev, length_skipn. lia. }
    split.
    { rewrite HR, app_assoc, List.firstn_app, HA.
      replace (l - 2 * k - (l - 2 * k))%nat with O by lia.
      cbn [firstn]. rewrite app_nil_r.
      rewrite <- HA at 1. rewrite List.firstn_all. reflexivity. }
    split; [reflexivity|]. split; [|reflexivity].
    apply PeanoNat.Nat.eqb_eq. rewrite length_skipn. lia.
  - pose proof (split_body_join (firstn (l - 2 * k)%nat (bf ++ rev bb)))
      as HJ.
    pose proof (split_body_len (firstn (l - 2 * k)%nat (bf ++ rev bb)))
      as HN.
    destruct (split_body (firstn (l - 2 * k)%nat (bf ++ rev bb)))
      as [rf rb] eqn:ES. cbn [fst snd] in HJ, HN.
    segfields. split; [exact HJ|]. split; [reflexivity|].
    split; [|reflexivity]. apply PeanoNat.Nat.eqb_eq.
    rewrite HN, length_firstn, length_app, length_rev. lia.
Qed.
Lemma segcache_len : forall s,
  segcache s = true -> length (sBody s) = sLen s.
Proof.
  intros s HC. unfold segcache in HC.
  apply PeanoNat.Nat.eqb_eq in HC. unfold sBody.
  rewrite length_app, length_rev. lia.
Qed.
Lemma segok_odd : forall s,
  segok s = true -> Nat.odd (sLen s) = true.
Proof.
  intros s H. unfold segok in H. cbv zeta in H.
  destruct (sBody s) as [|g0 b']; [discriminate|].
  cbv beta iota in H. apply andb_prop in H as [H _].
  apply andb_prop in H as [H _]. apply andb_prop in H as [_ H]. exact H.
Qed.
Lemma in_sub : forall (x : bg) n a (b : word),
  In x (firstn n (skipn a b)) -> In x b.
Proof.
  intros x n a b H.
  assert (Hs : In x (skipn a b)).
  { rewrite <- (firstn_skipn n (skipn a b)). apply in_or_app. left. exact H. }
  rewrite <- (firstn_skipn a b). apply in_or_app. right. exact Hs.
Qed.
Lemma mbnd_sub : forall m b a n,
  mbnd m b = true -> mbnd m (firstn n (skipn a b)) = true.
Proof.
  intros m b a n H. unfold mbnd in *.
  apply forallb_forall. intros x Hx.
  eapply forallb_forall in H; [exact H|exact (in_sub x n a b Hx)].
Qed.
Theorem relax_step_shape : forall s kf kb fr s1 s2 bk,
  segcache s = true -> segok s = true ->
  segshape s = true ->
  Nat.leb (segl s) (kf + kb + SEGMIN) = false ->
  spill_front s kf = (fr, s1) ->
  spill_back s1 kb = (s2, bk) ->
  segcache s2 = true /\ segok s2 = true /\
  segshape s2 = true.
Proof.
  intros s kf kb fr s1 s2 bk HC HO HS HSM ESF ESB.
  unfold segshape in HS. apply andb_prop in HS as [_ HA].
  pose proof (segok_odd s HO) as HOD.
  destruct (odd_ex _ HOD) as (j & HJ).
  apply PeanoNat.Nat.leb_gt in HSM.
  unfold segl, SEGMIN in HSM. rewrite HJ, div2_odd in HSM.
  destruct (spill_front_body s kf HC) as (HB1 & HL1 & HC1 & HM1).
  rewrite ESF in HB1, HL1, HC1, HM1. cbn [snd] in HB1, HL1, HC1, HM1.
  destruct (spill_back_body s1 kb HC1) as (HB2 & HL2 & HC2 & HM2).
  rewrite ESB in HB2, HL2, HC2, HM2. cbn [fst] in HB2, HL2, HC2, HM2.
  rewrite HB1, HL1 in HB2. rewrite HL1 in HL2. rewrite HM1 in HM2.
  set (L2 := (sLen s - 2 * kf - 2 * kb)%nat) in *.
  assert (HL2v : L2 = (2 * (j - kf - kb) + 1)%nat)
    by (unfold L2; lia).
  assert (HBODY : sBody s2 =
                  firstn L2 (skipn (2 * kf) (sBody s))).
  { rewrite HB2. unfold L2. f_equal; lia. }
  assert (HALT : segalt (sBody s2) = true).
  { rewrite HBODY. apply segalt_sub; [exact HA| | |].
    - rewrite HL2v. apply odd_of.
    - lia.
    - rewrite (segcache_len s HC). unfold L2. lia. }
  assert (HSOK : segok s2 = true).
  { apply segok_of_segalt; [exact HC2|exact HALT|].
    rewrite HM2, HBODY. apply mbnd_sub. exact (segok_mbnd s HO). }
  split; [exact HC2|]. split; [exact HSOK|].
  unfold segshape. apply andb_true_intro. split.
  - apply PeanoNat.Nat.leb_le. rewrite HL2, HL2v. lia.
  - exact HALT.
Qed.
Definition SGS (sg : list seg) : Prop :=
  forallb (fun s => (segcache s && segok s)
                     && segshape s) sg = true.
Lemma SGS_in : forall sg s,
  SGS sg -> In s sg ->
  segcache s = true /\ segok s = true /\
  segshape s = true.
Proof.
  intros sg s H Hin. unfold SGS in H.
  eapply forallb_forall in H; [|exact Hin].
  apply andb_prop in H as [H12 H3].
  apply andb_prop in H12 as [H1 H2].
  split; [exact H1|]. split; assumption.
Qed.
Lemma SGS_filter : forall p sg, SGS sg -> SGS (filter p sg).
Proof.
  intros p sg H. unfold SGS in *. apply forallb_forall. intros x Hx.
  apply filter_In in Hx.
  eapply forallb_forall in H; [exact H|exact (proj1 Hx)].
Qed.
Lemma SGS_sgset : forall sg k s,
  SGS sg -> segcache s = true -> segok s = true ->
  segshape s = true -> SGS (sgset sg k s).
Proof.
  intros sg k s H HC HO HS. unfold SGS in *.
  induction sg as [|x sg IH]; [reflexivity|].
  cbn [forallb] in H. apply andb_prop in H as [Hx Hsg].
  cbn [sgset]. destruct (sKey x =? k)%N.
  - cbn [forallb]. rewrite HC, HO, HS. cbn [andb]. exact Hsg.
  - cbn [forallb]. rewrite Hx. cbn [andb]. exact (IH Hsg).
Qed.
Lemma SGS_of : forall sg,
  sg_wf sg -> sg_shape sg -> SGS sg.
Proof.
  intros sg HW HS. unfold SGS. apply forallb_forall. intros s Hin.
  destruct (sg_wf_seg sg s HW Hin) as [HC HO].
  unfold sg_shape in HS.
  eapply forallb_forall in HS; [|exact Hin].
  rewrite HC, HO, HS. reflexivity.
Qed.
Lemma SGS_wf : forall sg, SGS sg -> sg_wf sg.
Proof.
  intros sg H. unfold sg_wf. apply forallb_forall.
  intros s Hin. destruct (SGS_in sg s H Hin) as (HC & HO & _).
  rewrite HC, HO. reflexivity.
Qed.
Lemma SGS_shape : forall sg, SGS sg -> sg_shape sg.
Proof.
  intros sg H. unfold sg_shape. apply forallb_forall.
  intros s Hin. exact (proj2 (proj2 (SGS_in sg s H Hin))).
Qed.
Theorem relax_SGS : forall fu sg w before,
  SGS sg -> SGS (snd (relax fu sg w before)).
Proof.
  intros fu. induction fu as [|fu IH]; intros sg w before H.
  - cbn [relax snd]. exact H.
  - destruct w as [|g t]; [cbn [relax snd]; exact H|].
    cbn [relax]. cbv beta zeta iota.
    destruct (keyi sg g) as [s|] eqn:EK.
    + destruct (keyi_in sg g s EK) as (Hin & _ & _).
      destruct (SGS_in sg s H Hin) as (HC & HO & HS).
      match goal with
      | |- context [Nat.leb ?a ?b] => destruct (Nat.leb a b) eqn:ESM
      end.
      * match goal with
        | |- context [relax fu ?a ?b ?c] =>
            specialize (IH a b c);
            destruct (relax fu a b c) as [t' sg''] eqn:ER
        end.
        cbn [snd] in IH |- *. apply IH. apply SGS_filter. exact H.
      * match goal with
        | |- context [spill_front ?a ?b] =>
            destruct (spill_front a b) as [fr s1] eqn:ESF
        end.
        match goal with
        | |- context [spill_back ?a ?b] =>
            destruct (spill_back a b) as [s2 bk] eqn:ESB
        end.
        destruct (relax_step_shape s _ _ fr s1 s2 bk
                    HC HO HS ESM ESF ESB) as (HC2 & HO2 & HS2).
        match goal with
        | |- context [relax fu ?a ?b ?c] =>
            specialize (IH a b c);
            destruct (relax fu a b c) as [t' sg''] eqn:ER
        end.
        cbn [snd] in IH |- *. apply IH.
        apply SGS_sgset; [exact H|exact HC2|exact HO2|exact HS2].
    + match goal with
      | |- context [relax fu ?a ?b ?c] =>
          specialize (IH a b c);
          destruct (relax fu a b c) as [t' sg'] eqn:ER
      end.
      cbn [snd] in IH |- *. exact (IH H).
Qed.
Theorem lin_relax_table : forall sg w w2 sg2,
  sg_wf sg -> sg_shape sg ->
  lin_relax sg w = (w2, sg2) ->
  sg_wf sg2 /\ sg_shape sg2.
Proof.
  intros sg w w2 sg2 HW HS HR.
  pose proof (relax_SGS (length w) sg w
                (GUARD + SLACK)%nat (SGS_of sg HW HS)) as H.
  unfold lin_relax in HR. rewrite HR in H. cbn [snd] in H.
  split; [exact (SGS_wf sg2 H)|exact (SGS_shape sg2 H)].
Qed.
Definition SGP (sg : list seg) : Prop :=
  forallb segpos sg = true.
Lemma SGP_in : forall sg s,
  SGP sg -> In s sg -> segpos s = true.
Proof.
  intros sg s H Hin. unfold SGP in H.
  eapply forallb_forall in H; [exact H|exact Hin].
Qed.
Lemma SGP_filter : forall p sg, SGP sg -> SGP (filter p sg).
Proof.
  intros p sg H. unfold SGP in *. apply forallb_forall.
  intros s Hin. apply filter_In in Hin.
  eapply forallb_forall in H; [exact H|exact (proj1 Hin)].
Qed.
Lemma SGP_sgset : forall sg k s,
  SGP sg -> segpos s = true -> SGP (sgset sg k s).
Proof.
  intros sg k s H HP. unfold SGP in *.
  induction sg as [|x sg IH]; [reflexivity|].
  cbn [forallb] in H. apply andb_prop in H as [Hx Hsg].
  cbn [sgset]. destruct (sKey x =? k)%N.
  - cbn [forallb]. rewrite HP. exact Hsg.
  - cbn [forallb]. rewrite Hx. cbn [andb]. exact (IH Hsg).
Qed.
Lemma spill_front_pos : forall s k,
  segpos s = true ->
  segpos (snd (spill_front s k)) = true.
Proof.
  intros [[[[[[key p] m] l] bf] bb] cs] k HP.
  unfold segpos in HP |- *.
  unfold spill_front. cbv beta zeta iota.
  destruct (lin_hasn (2 * k)%nat bf); [exact HP|].
  destruct (split_body (skipn (2 * k)%nat (bf ++ rev bb)));
    exact HP.
Qed.
Lemma spill_back_pos : forall s k,
  segpos s = true ->
  segpos (fst (spill_back s k)) = true.
Proof.
  intros [[[[[[key p] m] l] bf] bb] cs] k HP.
  unfold segpos in HP |- *.
  unfold spill_back. cbv beta zeta iota.
  destruct (lin_hasn (2 * k)%nat bb); [exact HP|].
  destruct (split_body
    (firstn (l - 2 * k)%nat (bf ++ rev bb))); exact HP.
Qed.
Theorem relax_SGP : forall fu sg w before,
  SGP sg -> SGP (snd (relax fu sg w before)).
Proof.
  intros fu. induction fu as [|fu IH]; intros sg w before HP.
  - cbn [relax snd]. exact HP.
  - destruct w as [|g t]; [cbn [relax snd]; exact HP|].
    cbn [relax]. cbv beta zeta iota.
    destruct (keyi sg g) as [s|] eqn:EK.
    + destruct (keyi_in sg g s EK) as [Hin _].
      pose proof (SGP_in sg s HP Hin) as Hs.
      match goal with
      | |- context [Nat.leb ?a ?b] => destruct (Nat.leb a b)
      end.
      * match goal with
        | |- context [relax fu ?a ?b ?c] =>
            specialize (IH a b c);
            destruct (relax fu a b c) as [t' sg'] eqn:ER
        end.
        cbn [snd] in IH |- *. apply IH. apply SGP_filter. exact HP.
      * match goal with
        | |- context [spill_front ?a ?b] =>
            pose proof (spill_front_pos a b Hs) as HP1;
            destruct (spill_front a b) as [fr s1] eqn:ESF
        end.
        cbn [snd] in HP1.
        match goal with
        | |- context [spill_back ?a ?b] =>
            pose proof (spill_back_pos a b HP1) as HP2;
            destruct (spill_back a b) as [s2 bk] eqn:ESB
        end.
        cbn [fst] in HP2.
        match goal with
        | |- context [relax fu ?a ?b ?c] =>
            specialize (IH a b c);
            destruct (relax fu a b c) as [t' sg'] eqn:ER
        end.
        cbn [snd] in IH |- *. apply IH.
        apply SGP_sgset; [exact HP|exact HP2].
    + match goal with
      | |- context [relax fu ?a ?b ?c] =>
          specialize (IH a b c);
          destruct (relax fu a b c) as [t' sg'] eqn:ER
      end.
      cbn [snd] in IH |- *. exact (IH HP).
Qed.
Theorem lin_relax_pos : forall sg w w2 sg2,
  SGP sg -> lin_relax sg w = (w2, sg2) -> SGP sg2.
Proof.
  intros sg w w2 sg2 HP HR.
  pose proof (relax_SGP (length w) sg w
    (GUARD + SLACK)%nat HP) as H.
  unfold lin_relax in HR. rewrite HR in H. exact H.
Qed.
Lemma incl_keys_filter : forall (p : seg -> bool) sg,
  incl (map sKey (filter p sg)) (map sKey sg).
Proof.
  intros p sg k Hk. apply in_map_iff in Hk.
  destruct Hk as (s & <- & Hin). apply filter_In in Hin.
  apply in_map. exact (proj1 Hin).
Qed.
Lemma spill_front_key : forall s k,
  sKey (snd (spill_front s k)) = sKey s.
Proof.
  intros [[[[[[key p] m] l] bf] bb] cs] k.
  unfold spill_front. cbv beta zeta iota.
  destruct (lin_hasn (2 * k)%nat bf); [reflexivity|].
  destruct (split_body (skipn (2 * k)%nat (bf ++ rev bb)))
    as [rf rb]. reflexivity.
Qed.
Lemma spill_back_key : forall s k,
  sKey (fst (spill_back s k)) = sKey s.
Proof.
  intros [[[[[[key p] m] l] bf] bb] cs] k.
  unfold spill_back. cbv beta zeta iota.
  destruct (lin_hasn (2 * k)%nat bb); [reflexivity|].
  destruct (split_body (firstn (l - 2 * k)%nat (bf ++ rev bb)))
    as [rf rb]. reflexivity.
Qed.
Lemma relax_keys : forall fu sg w before,
  incl (map sKey (snd (relax fu sg w before)))
       (map sKey sg).
Proof.
  induction fu as [|fu IH]; intros sg w before.
  - cbn [relax snd]. apply incl_refl.
  - destruct w as [|g t]; [cbn [relax snd]; apply incl_refl|].
    cbn [relax]. cbv beta zeta iota.
    destruct (keyi sg g) as [s|] eqn:EK.
    + match goal with
      | |- context [Nat.leb ?a ?b] => destruct (Nat.leb a b) eqn:ESM
      end.
      * match goal with
        | |- context [relax fu ?a ?b ?c] =>
            specialize (IH a b c);
            destruct (relax fu a b c) as [t' sg''] eqn:ER
        end.
        cbn [snd] in IH. eapply incl_tran; [exact IH|apply incl_keys_filter].
      * match goal with
        | |- context [spill_front ?a ?b] =>
            pose proof (spill_front_key a b) as HKF;
            destruct (spill_front a b) as [fr s1] eqn:ESF
        end.
        cbn [snd] in HKF.
        match goal with
        | |- context [spill_back ?a ?b] =>
            pose proof (spill_back_key a b) as HKB;
            destruct (spill_back a b) as [s2 bk] eqn:ESB
        end.
        cbn [fst] in HKB.
        match goal with
        | |- context [relax fu ?a ?b ?c] =>
            specialize (IH a b c);
            destruct (relax fu a b c) as [t' sg''] eqn:ER
        end.
        cbn [snd] in IH. eapply incl_tran; [exact IH|].
        rewrite (sgset_keys sg (sKey s) s2)
          by (rewrite HKB, HKF; reflexivity).
        apply incl_refl.
    + match goal with
      | |- context [relax fu ?a ?b ?c] =>
          specialize (IH a b c);
          destruct (relax fu a b c) as [t' sg'] eqn:ER
      end.
      cbn [snd] in IH. exact IH.
Qed.
Theorem lin_relax_keys_big : forall sg w w2 sg2,
  keys_big sg -> lin_relax sg w = (w2, sg2) ->
  keys_big sg2.
Proof.
  intros sg w w2 sg2 HK HR s Hin.
  pose proof (relax_keys (length w) sg w
                (GUARD + SLACK)%nat) as HI.
  unfold lin_relax in HR. rewrite HR in HI. cbn [snd] in HI.
  assert (Hk : In (sKey s) (map sKey sg)).
  { apply HI. apply in_map. exact Hin. }
  apply in_map_iff in Hk. destruct Hk as (s0 & Hs0 & Hin0).
  rewrite <- Hs0. exact (HK s0 Hin0).
Qed.
Lemma repack_store_oz : forall p g,
  gO (repack_store p g) = gO g /\
  gZ (repack_store p g) = gZ g.
Proof.
  intros p [[o z] c]. unfold repack_store.
  cbn [gO gZ gC].
  destruct (is_lvl (o, z, c)); auto.
Qed.
Lemma repack_store_is_lvl : forall p g,
  is_lvl (repack_store p g) = is_lvl g.
Proof.
  intros p g. unfold is_lvl.
  destruct (repack_store_oz p g) as [HO HZ]. now rewrite HO, HZ.
Qed.
Lemma repack_store_is_spc : forall p g,
  is_spc (repack_store p g) = is_spc g.
Proof.
  intros p [[o z] c]. unfold repack_store.
  cbn [gO gZ gC].
  destruct (is_lvl (o, z, c)) eqn:EL; [|reflexivity].
  unfold is_lvl in EL. cbn [gO gZ] in EL.
  apply andb_prop in EL as [HO _]. apply N.eqb_eq in HO. subst o.
  reflexivity.
Qed.
Lemma lvl_big_is_lvl : forall g,
  lvl_big g = true -> is_lvl g = true.
Proof.
  intros [[o z] c] H. unfold lvl_big, is_lvl in *.
  cbn [gO gZ gC] in H |- *.
  exact (proj1 (andb_prop _ _ H)).
Qed.
Lemma segalt_front : forall p fr b,
  repack_front_ok fr = true -> segalt b = true ->
  segalt (map (repack_store p) fr ++ b) = true.
Proof.
  intros p. fix IH 1. intros fr b HF HB.
  destruct fr as [|l [|s t]].
  - exact HB.
  - discriminate HF.
  - cbn [repack_front_ok] in HF.
    repeat rewrite Bool.andb_true_iff in HF.
    destruct HF as [[HL HS] HT].
    cbn [map app segalt].
    rewrite repack_store_is_lvl, repack_store_is_spc,
            (lvl_big_is_lvl l HL), HS.
    cbn [andb]. exact (IH t b HT HB).
Qed.
Lemma segalt_single_back : forall p l bk,
  is_lvl l = true -> repack_back_ok bk = true ->
  segalt (l :: map (repack_store p) bk) = true.
Proof.
  intros p. fix IH 2. intros l bk HL HK.
  destruct bk as [|sp [|lv bk']].
  - cbn [map segalt]. exact HL.
  - discriminate HK.
  - cbn [repack_back_ok] in HK.
    repeat rewrite Bool.andb_true_iff in HK.
    destruct HK as [[HSP HLV] HKT].
    cbn [map segalt]. apply andb_true_intro. split.
    + apply andb_true_intro. split; [exact HL|].
      rewrite repack_store_is_spc. exact HSP.
    + apply (IH (repack_store p lv) bk');
        [rewrite repack_store_is_lvl; exact (lvl_big_is_lvl lv HLV)|].
      exact HKT.
Qed.
Lemma segalt_back : forall p b bk,
  segalt b = true -> repack_back_ok bk = true ->
  segalt (b ++ map (repack_store p) bk) = true.
Proof.
  intros p. fix IH 1. intros b bk HB HK.
  destruct b as [|l [|s t]].
  - discriminate HB.
  - cbn [segalt] in HB.
    cbn [app]. exact (segalt_single_back p l bk HB HK).
  - cbn [segalt] in HB.
    repeat rewrite Bool.andb_true_iff in HB.
    destruct HB as [[HL HS] HT].
    cbn [app segalt]. rewrite HL, HS. cbn [andb].
    exact (IH t bk HT HK).
Qed.
Definition extend_seg (s : seg) (fr bk : word) : seg :=
  let p := sPend s in
  let frs := map (repack_store p) fr in
  let bks := map (repack_store p) bk in
  let mn := minlvl_from bks
      (minlvl_from frs (sMin s)) in
  (sKey s, p, mn,
   (sLen s + length fr + length bk)%nat,
   frs ++ sFront s, rev bks ++ sBack s,
   sCsum s + bsum fr + bsum bk).
Lemma extend_seg_body : forall s fr bk,
  sBody (extend_seg s fr bk) =
  map (repack_store (sPend s)) fr ++
  sBody s ++
  map (repack_store (sPend s)) bk.
Proof.
  intros s fr bk. unfold extend_seg, sBody.
  cbn [sFront sBack].
  rewrite rev_app_distr, rev_involutive. now rewrite !app_assoc.
Qed.
Lemma extend_seg_cache : forall s fr bk,
  segcache s = true ->
  segcache (extend_seg s fr bk) = true.
Proof.
  intros [[[[[[k p] m] l] sf] sb] cs] fr bk H.
  unfold segcache in H |- *.
  cbn [sLen sFront sBack] in H |- *.
  apply PeanoNat.Nat.eqb_eq in H. apply PeanoNat.Nat.eqb_eq.
  unfold extend_seg. cbn [sLen sFront sBack].
  rewrite !length_app, !length_map, length_rev.
  rewrite length_map. lia.
Qed.
Lemma minlvl_from_le : forall b m, (minlvl_from b m <= m)%N.
Proof.
  induction b as [|g b IH]; intros m; cbn [minlvl_from].
  - apply N.le_refl.
  -
  destruct (is_lvl g); [etransitivity; [apply IH|apply N.le_min_l]|apply IH].
Qed.
Lemma minlvl_from_bound : forall b m,
  mbnd (minlvl_from b m) b = true.
Proof.
  intros b. induction b as [|g b IH]; intros m; [reflexivity|].
  cbn [minlvl_from]. destruct (is_lvl g) eqn:EL.
  - unfold mbnd. cbn [forallb]. rewrite EL. cbn [negb orb].
    apply andb_true_intro. split.
    + apply N.leb_le. etransitivity; [apply minlvl_from_le|apply N.le_min_r].
    + exact (IH (N.min m (gC g))).
  - unfold mbnd. cbn [forallb]. rewrite EL. cbn [negb orb]. exact (IH m).
Qed.
Lemma mbnd_weaken : forall b lo hi,
  (lo <= hi)%N -> mbnd hi b = true -> mbnd lo b = true.
Proof.
  intros b lo hi Hle H. unfold mbnd in *. apply forallb_forall.
  intros g Hin. eapply forallb_forall in H; [|exact Hin].
  destruct (is_lvl g); cbn [negb orb] in H |- *; [|reflexivity].
  apply N.leb_le in H. apply N.leb_le. lia.
Qed.
Lemma extend_seg_mbnd : forall s fr bk,
  mbnd (sMin s) (sBody s) = true ->
  mbnd (sMin (extend_seg s fr bk))
       (sBody (extend_seg s fr bk)) = true.
Proof.
  intros s fr bk H. rewrite extend_seg_body.
  unfold extend_seg. cbn [sMin sPend].
  set (frs := map (repack_store (sPend s)) fr).
  set (bks := map (repack_store (sPend s)) bk).
  set (m1 := minlvl_from frs (sMin s)).
  set (mn := minlvl_from bks m1).
  unfold mbnd. rewrite forallb_app. apply andb_true_intro. split.
  - fold (mbnd mn frs). apply mbnd_weaken with (hi := m1).
    + subst mn. apply minlvl_from_le.
    + subst m1. apply minlvl_from_bound.
  - rewrite forallb_app. apply andb_true_intro. split.
    + fold (mbnd mn (sBody s)).
      apply mbnd_weaken with (hi := sMin s); [|exact H].
      subst mn m1. etransitivity; apply minlvl_from_le.
    + fold (mbnd mn bks). subst mn. apply minlvl_from_bound.
Qed.
Lemma extend_seg_shape : forall s fr bk,
  segcache s = true -> segok s = true ->
  segshape s = true ->
  repack_front_ok fr = true ->
  repack_back_ok bk = true ->
  segcache (extend_seg s fr bk) = true /\
  segok (extend_seg s fr bk) = true /\
  segshape (extend_seg s fr bk) = true.
Proof.
  intros s fr bk HC HO HS HF HB.
  unfold segshape in HS. apply andb_prop in HS as [HL HA].
  assert (HC2 := extend_seg_cache s fr bk HC).
  assert (HA2 : segalt (sBody (extend_seg s fr bk)) = true).
  { rewrite extend_seg_body, app_assoc.
    apply segalt_back; [apply segalt_front|]; assumption. }
  assert (HM2 : mbnd (sMin (extend_seg s fr bk))
                     (sBody (extend_seg s fr bk)) = true)
    by (apply extend_seg_mbnd; exact (segok_mbnd s HO)).
  assert (HO2 := segok_of_segalt (extend_seg s fr bk) HC2 HA2 HM2).
  split; [exact HC2|]. split; [exact HO2|].
  unfold segshape. apply andb_true_intro. split; [|exact HA2].
  apply PeanoNat.Nat.leb_le. apply PeanoNat.Nat.leb_le in HL.
  unfold extend_seg. cbn [sLen]. lia.
Qed.
Lemma repack_store_big : forall p g,
  lvl_big g = true ->
  is_lvl (repack_store p g) = true /\
  (1 + 4 * p <= gC (repack_store p g))%N.
Proof.
  intros p [[o z] c] H.
  unfold lvl_big in H.
  cbn [gO gZ gC] in H.
  repeat rewrite Bool.andb_true_iff in H.
  destruct H as [[Ho Hz] Hc].
  apply N.eqb_eq in Ho, Hz. apply N.leb_le in Hc. subst o z.
  unfold repack_store, is_lvl.
  cbn [gO gZ gC]. split; [reflexivity|].
  apply N.add_le_mono_r. unfold FLOOR in Hc. lia.
Qed.
Lemma repack_store_spc : forall p g,
  is_spc g = true ->
  is_lvl (repack_store p g) = false.
Proof.
  intros p [[o z] c] H.
  unfold is_spc in H.
  cbn [gO gZ gC] in H.
  repeat rewrite Bool.andb_true_iff in H.
  destruct H as [[Ho Hz] Hc].
  apply N.eqb_eq in Ho, Hz, Hc. subst o z c.
  unfold repack_store, is_lvl.
  cbn [gO gZ gC]. reflexivity.
Qed.
Lemma repack_front_mbnd : forall p b,
  repack_front_ok b = true ->
  mbnd (1 + 4 * p)%N (map (repack_store p) b) = true.
Proof.
  fix IH 2. intros p b H. destruct b as [|l [|s t]];
    try reflexivity; try discriminate.
  cbn [repack_front_ok] in H.
  repeat rewrite Bool.andb_true_iff in H.
  destruct H as [[Hl Hs] Ht].
  cbn [map]. unfold mbnd. cbn [forallb].
  destruct (repack_store_big p l Hl) as [HLB HCB].
  assert (HCB' : (1 + 4 * p <=?
    gC (repack_store p l))%N = true)
    by (apply N.leb_le; exact HCB).
  rewrite HLB, HCB'. cbn [negb orb].
  rewrite (repack_store_spc p s Hs). cbn [negb orb andb].
  exact (IH p t Ht).
Qed.
Lemma repack_back_mbnd : forall p b,
  repack_back_ok b = true ->
  mbnd (1 + 4 * p)%N (map (repack_store p) b) = true.
Proof.
  fix IH 2. intros p b H. destruct b as [|s [|l t]];
    try reflexivity; try discriminate.
  cbn [repack_back_ok] in H.
  repeat rewrite Bool.andb_true_iff in H.
  destruct H as [[Hs Hl] Ht].
  cbn [map]. unfold mbnd. cbn [forallb].
  rewrite (repack_store_spc p s Hs). cbn [negb orb andb].
  destruct (repack_store_big p l Hl) as [HLB HCB].
  assert (HCB' : (1 + 4 * p <=?
    gC (repack_store p l))%N = true)
    by (apply N.leb_le; exact HCB).
  rewrite HLB, HCB'. cbn [negb orb].
  exact (IH p t Ht).
Qed.
Lemma minlvl_from_lower : forall b m lo,
  (lo <= m)%N -> mbnd lo b = true ->
  (lo <= minlvl_from b m)%N.
Proof.
  induction b as [|g b IH]; intros m lo Hm HB; [exact Hm|].
  cbn [minlvl_from]. unfold mbnd in HB.
  cbn [forallb] in HB. apply andb_prop in HB as [Hg Hb].
  destruct (is_lvl g) eqn:EL.
  - cbn [negb orb] in Hg. apply N.leb_le in Hg.
    apply IH; [apply N.min_glb; assumption|exact Hb].
  - apply IH; [exact Hm|exact Hb].
Qed.
Lemma extend_seg_pos : forall s fr bk,
  segpos s = true ->
  repack_front_ok fr = true ->
  repack_back_ok bk = true ->
  segpos (extend_seg s fr bk) = true.
Proof.
  intros s fr bk HP HF HB.
  unfold segpos in HP |- *. apply N.leb_le in HP.
  unfold extend_seg. cbn [sPend sMin].
  apply N.leb_le.
  apply minlvl_from_lower.
  - apply minlvl_from_lower.
    + exact HP.
    + apply repack_front_mbnd. exact HF.
  - apply repack_back_mbnd. exact HB.
Qed.
Lemma cleanrun_le_length : forall sg w cap,
  (cleanrun sg w cap <= length w)%nat.
Proof.
  intros sg w cap. revert w. induction cap as [|cap IH]; intros [|g w].
  - cbn [cleanrun length]. lia.
  - cbn [cleanrun length]. lia.
  - reflexivity.
  - cbn [cleanrun length].
    destruct (ph sg g || negb (casc g)); cbn; [lia|].
    specialize (IH w). lia.
Qed.
Lemma twice_div2_le : forall n, (2 * Nat.div2 n <= n)%nat.
Proof.
  intros n. pose proof (PeanoNat.Nat.div2_odd n) as H.
  destruct (Nat.odd n); cbn in H; lia.
Qed.
Lemma SGS_app : forall a b, SGS a -> SGS b -> SGS (a ++ b).
Proof.
  intros a b HA HB. unfold SGS in *. rewrite forallb_app, HA, HB.
  reflexivity.
Qed.
Lemma SGS_parts : forall sg,
  forallb (fun s => segcache s && segok s) sg = true ->
  forallb segshape sg = true -> SGS sg.
Proof.
  intros sg HW HS. unfold SGS. apply forallb_forall. intros s Hin.
  eapply forallb_forall in HW; [|exact Hin].
  eapply forallb_forall in HS; [|exact Hin].
  rewrite HW, HS. reflexivity.
Qed.
Lemma repack_one_SGS : forall sg w key sg2 w2,
  SGS sg ->
  repack_one sg w key = Some (sg2, w2) -> SGS sg2.
Proof.
  intros sg w key sg2 w2 Hall Hr. unfold repack_one in Hr.
  destruct (locate_key w key) as [i|] eqn:ELoc; [|discriminate].
  destruct (lin_split_at i w) as [pre here] eqn:ESplit.
  destruct here as [|g post]; [discriminate|].
  destruct (keyi sg g) as [sold|] eqn:EKey; [|discriminate].
  cbv beta zeta iota in Hr.
  destruct (repack_front_ok
      (rev
         (firstn
            (2 * Nat.div2
               (cleanrun sg (rev pre) i - MARG))
            (rev pre))) &&
    repack_back_ok
      (firstn
         (2 * Nat.div2
            (cleanrun sg post (length post) - MARG))
         post)) eqn:EOk; [|discriminate].
  match type of Hr with
  | (if ?gate then _ else _) = _ => destruct gate eqn:EEdge
  end; [|discriminate].
  inversion Hr; subst sg2 w2. clear Hr.
  set (nb := cleanrun sg (rev pre) i) in *.
  set (na := cleanrun sg post (length post)) in *.
  set (lb := (2 * Nat.div2 (nb - MARG))%nat) in *.
  set (la := (2 * Nat.div2 (na - MARG))%nat) in *.
  set (fr := rev (firstn lb (rev pre))) in *.
  set (bk := firstn la post) in *.
  set (frs := map (repack_store (sPend sold)) fr) in *.
  set (bks := map (repack_store (sPend sold)) bk) in *.
  set (mn := minlvl_from bks
      (minlvl_from frs (sMin sold))) in *.
  set (snew :=
      ((sKey sold, sPend sold, mn,
        (sLen sold + lb + la)%nat,
        frs ++ sFront sold,
        rev bks ++ sBack sold,
        sCsum sold + bsum fr + bsum bk)
       : seg)) in *.
  change (SGS (sgset sg key snew)).
  apply andb_prop in EOk as [Hfr Hbk].
  assert (Hlb : (lb <= length (rev pre))%nat).
  { unfold lb, nb. etransitivity.
    - apply twice_div2_le.
    - etransitivity; [apply PeanoNat.Nat.le_sub_l|apply cleanrun_le_length]. }
  assert (Hla : (la <= length post)%nat).
  { unfold la, na. etransitivity.
    - apply twice_div2_le.
    - etransitivity; [apply PeanoNat.Nat.le_sub_l|apply cleanrun_le_length]. }
  assert (Hfrlen : length fr = lb).
  { unfold fr. rewrite length_rev. now apply firstn_length_le. }
  assert (Hbklen : length bk = la).
  { unfold bk. now apply firstn_length_le. }
  assert (Hsnew : snew = extend_seg sold fr bk).
  { unfold snew, extend_seg, frs, bks, mn.
    rewrite Hfrlen, Hbklen. reflexivity. }
  destruct (keyi_in sg g sold EKey) as [Hin _].
  destruct (SGS_in sg sold Hall Hin) as (HC & HO & HS).
  destruct (extend_seg_shape sold fr bk HC HO HS Hfr Hbk)
    as (HC2 & HO2 & HS2).
  rewrite Hsnew. apply SGS_sgset; assumption.
Qed.
Lemma repack_keys_SGS : forall keys sg w sg2 w2,
  SGS sg ->
  repack_keys keys sg w = Some (sg2, w2) -> SGS sg2.
Proof.
  induction keys as [|key keys IH]; intros sg w sg2 w2 Hall Hr.
  - cbn [repack_keys] in Hr. injection Hr as <- <-. exact Hall.
  - cbn [repack_keys] in Hr.
    destruct (repack_one sg w key) as [[sg1 w1]|] eqn:EOne;
      [|discriminate].
    eapply IH; [eapply repack_one_SGS; eassumption|exact Hr].
Qed.
Lemma lin_extend_SGS : forall sg w sg2 w2,
  SGS sg -> lin_extend sg w = Some (sg2, w2) -> SGS sg2.
Proof.
  intros sg w sg2 w2 Hall H.
  unfold lin_extend in H.
  destruct (lplan_real (length w) sg w O) as [|p pl] eqn:EP.
  - injection H as <- <-. exact Hall.
  - cbv beta iota in H.
    destruct (lapply (p :: pl) w O
                (fresh_key sg KMAGIC))
      as [w' added] eqn:ELA.
    cbv beta iota zeta in H.
    destruct (forallb (fun s => segcache s && segok s) added
              && lin_ok (sg ++ added) w') eqn:EGate;
      [|discriminate].
    destruct (forallb segshape added) eqn:EShape; [|discriminate].
    destruct (forallb segpos added); [|discriminate].
    injection H as <- <-. apply SGS_app; [exact Hall|].
    apply andb_prop in EGate as [HAdded _].
    exact (SGS_parts added HAdded EShape).
Qed.
Theorem lin_repack_table : forall sg w sg2 ps2 w2,
  sg_wf sg -> sg_shape sg ->
  lin_repack sg w = Some (sg2, ps2, w2) ->
  sg_wf sg2 /\ sg_shape sg2.
Proof.
  intros sg w sg2 ps2 w2 HW HS H.
  unfold lin_repack in H.
  destruct (repack_keys (map sKey sg) sg w)
    as [[sgA wA]|] eqn:ER; [|discriminate].
  pose proof (repack_keys_SGS _ _ _ _ _ (SGS_of sg HW HS) ER) as HA.
  cbv beta iota in H.
  destruct (if Nat.leb (length wA) LZONE_MAX
            then Some (sgA, wA) else lin_extend sgA wA)
    as [[sgB wB]|] eqn:EE; [|discriminate].
  assert (HB : SGS sgB).
  { destruct (Nat.leb (length wA) LZONE_MAX).
    - injection EE as <- <-. exact HA.
    - exact (lin_extend_SGS sgA wA sgB wB HA EE). }
  cbv beta iota in H.
  destruct (locate_all sgB wB) as [psB|] eqn:EL; [|discriminate].
  destruct (lin_guard_at sgB psB wB); [|discriminate].
  destruct (lin_tags sgB wB); [|discriminate].
  injection H as <- <- <-.
  split; [exact (SGS_wf sgB HB)|exact (SGS_shape sgB HB)].
Qed.
Lemma SGP_app : forall a b, SGP a -> SGP b -> SGP (a ++ b).
Proof.
  intros a b HA HB. unfold SGP in *. rewrite forallb_app, HA, HB.
  reflexivity.
Qed.
Lemma repack_one_SGP : forall sg w key sg2 w2,
  SGP sg ->
  repack_one sg w key = Some (sg2, w2) -> SGP sg2.
Proof.
  intros sg w key sg2 w2 Hall Hr. unfold repack_one in Hr.
  destruct (locate_key w key) as [i|] eqn:ELoc; [|discriminate].
  destruct (lin_split_at i w) as [pre here] eqn:ESplit.
  destruct here as [|g post]; [discriminate|].
  destruct (keyi sg g) as [sold|] eqn:EKey; [|discriminate].
  cbv beta zeta iota in Hr.
  destruct (repack_front_ok
      (rev
         (firstn
            (2 * Nat.div2
               (cleanrun sg (rev pre) i - MARG))
            (rev pre))) &&
    repack_back_ok
      (firstn
         (2 * Nat.div2
            (cleanrun sg post (length post) - MARG))
         post)) eqn:EOk; [|discriminate].
  match type of Hr with
  | (if ?gate then _ else _) = _ => destruct gate eqn:EEdge
  end; [|discriminate].
  inversion Hr; subst sg2 w2. clear Hr.
  set (nb := cleanrun sg (rev pre) i) in *.
  set (na := cleanrun sg post (length post)) in *.
  set (lb := (2 * Nat.div2 (nb - MARG))%nat) in *.
  set (la := (2 * Nat.div2 (na - MARG))%nat) in *.
  set (fr := rev (firstn lb (rev pre))) in *.
  set (bk := firstn la post) in *.
  set (frs := map (repack_store (sPend sold)) fr) in *.
  set (bks := map (repack_store (sPend sold)) bk) in *.
  set (mn := minlvl_from bks
      (minlvl_from frs (sMin sold))) in *.
  set (snew :=
      ((sKey sold, sPend sold, mn,
        (sLen sold + lb + la)%nat,
        frs ++ sFront sold,
        rev bks ++ sBack sold,
        sCsum sold + bsum fr + bsum bk)
       : seg)) in *.
  change (SGP (sgset sg key snew)).
  apply andb_prop in EOk as [Hfr Hbk].
  assert (Hlb : (lb <= length (rev pre))%nat).
  { unfold lb, nb. etransitivity.
    - apply twice_div2_le.
    - etransitivity; [apply PeanoNat.Nat.le_sub_l|apply cleanrun_le_length]. }
  assert (Hla : (la <= length post)%nat).
  { unfold la, na. etransitivity.
    - apply twice_div2_le.
    - etransitivity; [apply PeanoNat.Nat.le_sub_l|apply cleanrun_le_length]. }
  assert (Hfrlen : length fr = lb).
  { unfold fr. rewrite length_rev. now apply firstn_length_le. }
  assert (Hbklen : length bk = la).
  { unfold bk. now apply firstn_length_le. }
  assert (Hsnew : snew = extend_seg sold fr bk).
  { unfold snew, extend_seg, frs, bks, mn.
    rewrite Hfrlen, Hbklen. reflexivity. }
  destruct (keyi_in sg g sold EKey) as [Hin _].
  pose proof (SGP_in sg sold Hall Hin) as HP.
  pose proof (extend_seg_pos sold fr bk HP Hfr Hbk) as HP2.
  rewrite Hsnew. exact (SGP_sgset sg key (extend_seg sold fr bk) Hall HP2).
Qed.
Lemma repack_keys_SGP : forall keys sg w sg2 w2,
  SGP sg ->
  repack_keys keys sg w = Some (sg2, w2) -> SGP sg2.
Proof.
  induction keys as [|key keys IH]; intros sg w sg2 w2 Hall Hr.
  - cbn [repack_keys] in Hr. injection Hr as <- <-. exact Hall.
  - cbn [repack_keys] in Hr.
    destruct (repack_one sg w key) as [[sg1 w1]|] eqn:EOne;
      [|discriminate].
    eapply IH; [eapply repack_one_SGP; eassumption|exact Hr].
Qed.
Lemma lin_extend_SGP : forall sg w sg2 w2,
  SGP sg -> lin_extend sg w = Some (sg2, w2) -> SGP sg2.
Proof.
  intros sg w sg2 w2 Hall H.
  unfold lin_extend in H.
  destruct (lplan_real (length w) sg w O) as [|p pl] eqn:EP.
  - injection H as <- <-. exact Hall.
  - cbv beta iota in H.
    destruct (lapply (p :: pl) w O
                (fresh_key sg KMAGIC))
      as [w' added] eqn:ELA.
    cbv beta iota zeta in H.
    destruct (forallb (fun s => segcache s && segok s) added
              && lin_ok (sg ++ added) w'); [|discriminate].
    destruct (forallb segshape added); [|discriminate].
    destruct (forallb segpos added) eqn:EPos; [|discriminate].
    injection H as <- <-. apply SGP_app; [exact Hall|exact EPos].
Qed.
Theorem lin_repack_pos : forall sg w sg2 ps2 w2,
  SGP sg ->
  lin_repack sg w = Some (sg2, ps2, w2) -> SGP sg2.
Proof.
  intros sg w sg2 ps2 w2 HP H.
  unfold lin_repack in H.
  destruct (repack_keys (map sKey sg) sg w)
    as [[sgA wA]|] eqn:ER; [|discriminate].
  pose proof (repack_keys_SGP _ _ _ _ _ HP ER) as HA.
  cbv beta iota in H.
  destruct (if Nat.leb (length wA) LZONE_MAX
            then Some (sgA, wA) else lin_extend sgA wA)
    as [[sgB wB]|] eqn:EE; [|discriminate].
  assert (HB : SGP sgB).
  { destruct (Nat.leb (length wA) LZONE_MAX).
    - injection EE as <- <-. exact HA.
    - exact (lin_extend_SGP sgA wA sgB wB HA EE). }
  cbv beta iota in H.
  destruct (locate_all sgB wB) as [psB|] eqn:EL; [|discriminate].
  destruct (lin_guard_at sgB psB wB); [|discriminate].
  destruct (lin_tags sgB wB); [|discriminate].
  injection H as <- <- <-. exact HB.
Qed.
Definition tagfree (w : word) : bool :=
  forallb (fun g => negb (tagbase g)) w.
Lemma tagbase_of_lvl : forall g,
  is_lvl g = true -> tagbase g = false.
Proof.
  intros [[o z] c] H. unfold is_lvl, tagbase in *.
  cbn [gO gZ gC] in *.
  apply andb_prop in H as [HO _]. apply N.eqb_eq in HO. subst o.
  reflexivity.
Qed.
Lemma tagbase_of_spc : forall g,
  is_spc g = true -> tagbase g = false.
Proof.
  intros [[o z] c] H. unfold is_spc, tagbase in *.
  cbn [gO gZ gC] in *.
  repeat rewrite Bool.andb_true_iff in H.
  destruct H as [[HO _] _]. apply N.eqb_eq in HO. subst o.
  reflexivity.
Qed.
Lemma segalt_tagfree : forall b,
  segalt b = true -> tagfree b = true.
Proof.
  fix IH 1. intros b H. destruct b as [|l [|s b']].
  - discriminate H.
  - cbn [segalt] in H. cbn [tagfree forallb].
    rewrite (tagbase_of_lvl l H). reflexivity.
  - cbn [segalt] in H. repeat rewrite Bool.andb_true_iff in H.
    destruct H as [[HL HS] HB]. cbn [tagfree forallb].
    rewrite (tagbase_of_lvl l HL), (tagbase_of_spc s HS).
    cbn [negb andb]. exact (IH b' HB).
Qed.
Lemma tagbase_adjk : forall p g,
  tagbase (adjk p g) = tagbase g.
Proof.
  intros p [[o z] c]. unfold adjk, tagbase.
  cbn [gO gZ gC].
  destruct ((o =? 4)%N && (z =? 2)%N); reflexivity.
Qed.
Lemma tagfree_matb : forall p b,
  tagfree (matb p b) = tagfree b.
Proof.
  intros p b. unfold tagfree, matb. induction b as [|g b IH].
  - reflexivity.
  - cbn [map forallb]. rewrite tagbase_adjk, IH. reflexivity.
Qed.
Lemma tagfree_sFlat : forall s,
  segalt (sBody s) = true ->
  tagfree (sFlat s) = true.
Proof.
  intros s H. unfold sFlat. rewrite tagfree_matb.
  exact (segalt_tagfree _ H).
Qed.
Lemma tagfree_app_parts : forall a b,
  tagfree (a ++ b) = true -> tagfree a = true /\ tagfree b = true.
Proof.
  intros a b H. unfold tagfree in *. rewrite forallb_app in H.
  exact (andb_prop _ _ H).
Qed.
Lemma countkey_tagfree : forall k w,
  tagfree w = true -> countkey k w = O.
Proof.
  intros k w. induction w as [|g w IH]; intros H; [reflexivity|].
  unfold tagfree in H. cbn [forallb] in H.
  apply andb_prop in H as [HG HW].
  cbn [countkey].
  assert (HP : phshape g = false).
  { unfold phshape, tagbase in *.
    destruct g as [[o z] c]. cbn [gO gZ gC] in *.
    destruct ((o =? PHO)%N && (z =? 2)%N) eqn:E;
      cbn [negb] in HG |- *; [discriminate|reflexivity]. }
  rewrite HP, (IH HW). reflexivity.
Qed.
Lemma flat_tagfree : forall sg w,
  tagfree w = true -> lin_flat sg w = w.
Proof.
  intros sg w. induction w as [|g w IH]; intros H; [reflexivity|].
  unfold tagfree in H. cbn [forallb] in H.
  apply andb_prop in H as [HG HW].
  rewrite flat_cons_nonlvl.
  - f_equal. exact (IH HW).
  - unfold phshape, tagbase in *.
    destruct g as [[o z] c]. cbn [gO gZ gC] in *.
    destruct ((o =? PHO)%N && (z =? 2)%N) eqn:E;
      cbn [negb] in HG |- *; [discriminate|reflexivity].
Qed.
Lemma spill_front_flat : forall s k,
  let '(fr, s') := spill_front s k in
  fr ++ sFlat s' = sFlat s.
Proof.
  intros [[[[[[key p] m] l] bf] bb] cs] k.
  unfold spill_front.
  destruct (lin_hasn (2 * k)%nat bf) eqn:EH.
  - unfold sFlat, sPend, sBody,
      sFront, sBack. cbn.
    unfold matb. rewrite <- !map_app. f_equal.
    replace (k + (k + 0))%nat with (2 * k)%nat by lia.
    rewrite (app_assoc (firstn (2 * k) bf)
                       (skipn (2 * k) bf) (rev bb)).
    rewrite firstn_skipn. reflexivity.
  - remember (bf ++ rev bb) as b eqn:EB.
    remember (skipn (2 * k) b) as rest eqn:ER.
    destruct (split_body rest) as [rf rb] eqn:ES.
    unfold sFlat, sPend, sBody,
      sFront, sBack. cbn.
    unfold matb. rewrite <- !map_app.
    assert (Ejoin : rf ++ rev rb = rest).
    { pose proof (split_body_join rest) as H.
      rewrite ES in H. cbn [fst snd] in H. exact H. }
    rewrite Ejoin.
    replace (k + (k + 0))%nat with (2 * k)%nat by lia.
    rewrite ER, <- EB. f_equal. apply firstn_skipn.
Qed.
Lemma spill_back_flat : forall s k,
  let '(s', bk) := spill_back s k in
  sFlat s' ++ bk = sFlat s.
Proof.
  intros [[[[[[key p] m] l] bf] bb] cs] k.
  unfold spill_back.
  destruct (lin_hasn (2 * k)%nat bb) eqn:EH.
  - unfold sFlat, sPend, sBody,
      sFront, sBack. cbn.
    unfold matb.
    replace (k + (k + 0))%nat with (2 * k)%nat by lia.
    rewrite !map_app, !map_rev.
    rewrite <- app_assoc. f_equal.
    rewrite <- rev_app_distr.
    rewrite <- map_app, firstn_skipn. reflexivity.
  - remember (bf ++ rev bb) as b eqn:EB.
    remember (firstn (l - 2 * k)%nat b) as rest eqn:ER.
    destruct (split_body rest) as [rf rb] eqn:ES.
    unfold sFlat, sPend, sBody,
      sFront, sBack. cbn.
    unfold matb.
    assert (Ejoin : rf ++ rev rb = rest).
    { pose proof (split_body_join rest) as H.
      rewrite ES in H. cbn [fst snd] in H. exact H. }
    rewrite Ejoin.
    replace (k + (k + 0))%nat with (2 * k)%nat by lia.
    rewrite ER, <- EB, <- map_app.
    f_equal. apply firstn_skipn.
Qed.
Lemma spill_tagfree : forall s kf kb fr s1 s2 bk,
  segalt (sBody s) = true ->
  spill_front s kf = (fr, s1) ->
  spill_back s1 kb = (s2, bk) ->
  tagfree fr = true /\ tagfree (sFlat s1) = true /\
  tagfree bk = true.
Proof.
  intros s kf kb fr s1 s2 bk HA EF EB.
  pose proof (spill_front_flat s kf) as HF. rewrite EF in HF.
  cbn [fst snd] in HF.
  pose proof (tagfree_sFlat s HA) as HT.
  rewrite <- HF in HT.
  destruct (tagfree_app_parts fr (sFlat s1) HT) as [Hfr Hs1].
  pose proof Hs1 as Hs1orig.
  pose proof (spill_back_flat s1 kb) as HB. rewrite EB in HB.
  cbn [fst snd] in HB. rewrite <- HB in Hs1.
  destruct (tagfree_app_parts (sFlat s2) bk Hs1) as [_ Hbk].
  split; [exact Hfr|]. split; [exact Hs1orig|exact Hbk].
Qed.
Definition lin_atmost (sg : list seg) (w : word) : Prop :=
  forall s, In s sg ->
    (countkey (sKey s) w <= 1)%nat.
Lemma lin_ok_atmost : forall sg w,
  lin_ok sg w = true -> lin_atmost sg w.
Proof.
  intros sg w H s Hin. unfold lin_ok in H.
  eapply forallb_forall in H; [|exact Hin].
  apply PeanoNat.Nat.eqb_eq in H. lia.
Qed.
Lemma atmost_tail : forall sg g t,
  lin_atmost sg (g :: t) -> lin_atmost sg t.
Proof.
  intros sg g t H s Hin. specialize (H s Hin).
  cbn [countkey] in H.
  destruct (phshape g &&
            (gC g =? sKey s)%N); lia.
Qed.
Lemma atmost_filter_tail : forall p sg g t,
  lin_atmost sg (g :: t) -> lin_atmost (filter p sg) t.
Proof.
  intros p sg g t H s Hin. apply filter_In in Hin.
  exact (atmost_tail sg g t H s (proj1 Hin)).
Qed.
Lemma atmost_sgset_tagfree : forall sg k s2 g t bk,
  sKey s2 = k -> tagfree bk = true ->
  lin_atmost sg (g :: t) ->
  lin_atmost (sgset sg k s2) (bk ++ t).
Proof.
  intros sg k s2 g t bk HK HT HA sout Hout.
  assert (Hkey : In (sKey sout)
                    (map sKey (sgset sg k s2))).
  { apply in_map. exact Hout. }
  rewrite (sgset_keys sg k s2 HK) in Hkey.
  apply in_map_iff in Hkey. destruct Hkey as (sin & HE & Hin).
  specialize (HA sin Hin). rewrite countkey_app.
  rewrite (countkey_tagfree (sKey sout) bk HT).
  cbn [countkey] in HA. rewrite <- HE. lia.
Qed.
Lemma keyi_filter_other : forall sg g s k,
  keyi sg g = Some s -> sKey s <> k ->
  keyi (filter (fun x => negb (sKey x =? k)%N) sg) g
  = Some s.
Proof.
  induction sg as [|x sg IH]; intros g s k H Hneq.
  - unfold keyi in H. destruct (phshape g); discriminate H.
  - rewrite keyi_cons in H.
    destruct (phshape g) eqn:HP; [|discriminate H].
    destruct (gC g =? sKey x)%N eqn:EX.
    + injection H as <-. cbn [filter].
      destruct (sKey x =? k)%N eqn:EK.
      * apply N.eqb_eq in EK. contradiction.
      * cbn [negb]. rewrite keyi_cons, HP, EX. reflexivity.
    + cbn [filter]. destruct (sKey x =? k)%N eqn:EK.
      * cbn [negb]. exact (IH g s k H Hneq).
      * cbn [negb]. rewrite keyi_cons, HP, EX.
        exact (IH g s k H Hneq).
Qed.
Lemma keyi_sgset_other : forall sg k s2 g s,
  sKey s2 = k -> keyi sg g = Some s ->
  sKey s <> k ->
  keyi (sgset sg k s2) g = Some s.
Proof.
  intros sg k s2 g s HK HE Hneq.
  rewrite (sgset_keyi sg k s2 g HK), HE.
  destruct (sKey s =? k)%N eqn:E; [|reflexivity].
  apply N.eqb_eq in E. contradiction.
Qed.
Lemma keyi_head_key_neq : forall sg g t cur k,
  keyi sg g = Some cur ->
  countkey k (g :: t) = O ->
  sKey cur <> k.
Proof.
  intros sg g t cur k HE HC Eq. subst k.
  destruct (keyi_in sg g cur HE) as (_ & HP & HG).
  cbn [countkey] in HC. rewrite HP, HG, N.eqb_refl in HC.
  cbn [andb] in HC. lia.
Qed.
Lemma countkey_tail_zero : forall k g t,
  countkey k (g :: t) = O -> countkey k t = O.
Proof.
  intros k g t H. cbn [countkey] in H.
  destruct (phshape g && (gC g =? k)%N); lia.
Qed.
Lemma countkey_tagfree_app_zero : forall k a b,
  tagfree a = true -> countkey k b = O ->
  countkey k (a ++ b) = O.
Proof.
  intros k a b HA HB. rewrite countkey_app.
  rewrite (countkey_tagfree k a HA), HB. lia.
Qed.
Theorem relax_preserve_absent_key : forall fu sg w before k keep,
  SGS sg ->
  keyi sg (phg k) = Some keep ->
  countkey k w = O ->
  keyi (snd (relax fu sg w before)) (phg k)
  = Some keep.
Proof.
  intros fu. induction fu as [|fu IH]; intros sg w before k keep HSG HKeep HC.
  - cbn [relax snd]. exact HKeep.
  - destruct w as [|g t]; [cbn [relax snd]; exact HKeep|].
    assert (HKeepKey : sKey keep = k).
    { destruct (keyi_in sg (phg k) keep HKeep)
        as (_ & _ & HK). cbn [phg gC] in HK. symmetry. exact HK. }
    pose proof (countkey_tail_zero k g t HC) as HCT.
    cbn [relax]. cbv beta zeta iota.
    destruct (keyi sg g) as [s|] eqn:EK.
    + destruct (keyi_in sg g s EK) as (Hin & _ & _).
      destruct (SGS_in sg s HSG Hin) as (HCache & HOk & HShape).
      assert (HOther : sKey keep <> sKey s).
      { rewrite HKeepKey. intro E. symmetry in E.
        exact (keyi_head_key_neq sg g t s k EK HC E). }
      match goal with
      | |- context [Nat.leb ?a ?b] => destruct (Nat.leb a b) eqn:ESM
      end.
      * match goal with
        | |- context [relax fu ?a ?b ?c] =>
            assert (HSG' : SGS a) by (apply SGS_filter; exact HSG);
            assert (HK' : keyi a (phg k) = Some keep)
              by (apply keyi_filter_other; assumption);
            specialize (IH a b c k keep HSG' HK' HCT);
            destruct (relax fu a b c) as [t' sg''] eqn:ER
        end.
        cbn [snd] in IH |- *. exact IH.
      * match goal with
        | |- context [spill_front ?a ?b] =>
            pose proof (spill_front_key a b) as HKF;
            destruct (spill_front a b) as [fr s1] eqn:ESF
        end.
        cbn [snd] in HKF.
        match goal with
        | |- context [spill_back ?a ?b] =>
            pose proof (spill_back_key a b) as HKB;
            destruct (spill_back a b) as [s2 bk] eqn:ESB
        end.
        cbn [fst] in HKB.
        destruct (relax_step_shape s _ _ fr s1 s2 bk
                    HCache HOk HShape ESM ESF ESB)
          as (HC2 & HO2 & HS2).
        assert (HK2 : sKey s2 = sKey s)
          by (rewrite HKB, HKF; reflexivity).
        assert (HAlt : segalt (sBody s) = true).
        { unfold segshape in HShape.
          exact (proj2 (andb_prop _ _ HShape)). }
        destruct (spill_tagfree s _ _ fr s1 s2 bk HAlt ESF ESB)
          as (_ & _ & HBK).
        match goal with
        | |- context [relax fu ?a ?b ?c] =>
            assert (HSG' : SGS a)
              by (apply SGS_sgset; [exact HSG|exact HC2|exact HO2|exact HS2]);
            assert (HK' : keyi a (phg k) = Some keep)
              by (apply keyi_sgset_other; [exact HK2|exact HKeep|exact HOther]);
            assert (HC' : countkey k b = O)
              by (apply countkey_tagfree_app_zero; [exact HBK|exact HCT]);
            specialize (IH a b c k keep HSG' HK' HC');
            destruct (relax fu a b c) as [t' sg''] eqn:ER
        end.
        cbn [snd] in IH |- *. exact IH.
    + match goal with
      | |- context [relax fu ?a ?b ?c] =>
          specialize (IH a b c k keep HSG HKeep HCT);
          destruct (relax fu a b c) as [t' sg'] eqn:ER
      end.
      cbn [snd] in IH |- *. exact IH.
Qed.
Lemma keyi_filter_none : forall p sg g,
  keyi sg g = None ->
  keyi (filter p sg) g = None.
Proof.
  intros p sg. induction sg as [|x sg IH]; intros g H.
  - unfold keyi. destruct (phshape g); reflexivity.
  - rewrite keyi_cons in H.
    destruct (phshape g) eqn:HP.
    + destruct (gC g =? sKey x)%N eqn:EX;
        [discriminate H|].
      cbn [filter]. destruct (p x) eqn:EP.
      * rewrite keyi_cons, HP, EX. exact (IH g H).
      * exact (IH g H).
    + cbn [filter]. destruct (p x).
      * rewrite keyi_cons, HP. reflexivity.
      * apply IH. unfold keyi. rewrite HP. reflexivity.
Qed.
Lemma keyi_none_keys_incl : forall sg1 sg2 g,
  incl (map sKey sg1) (map sKey sg2) ->
  keyi sg2 g = None -> keyi sg1 g = None.
Proof.
  intros sg1 sg2 g HI HN.
  destruct (keyi sg1 g) as [s|] eqn:HE; [|reflexivity].
  destruct (keyi_in sg1 g s HE) as (Hin & HP & HG).
  assert (Hkey : In (sKey s) (map sKey sg1))
    by (apply in_map; exact Hin).
  specialize (HI _ Hkey). apply in_map_iff in HI.
  destruct HI as (s0 & HK & Hin0).
  pose proof (keyi_some_of_in sg2 s0 g Hin0 HP) as Hph.
  assert (HGC : gC g = sKey s0) by (rewrite HK; exact HG).
  specialize (Hph HGC). unfold ph in Hph. rewrite HN in Hph.
  discriminate.
Qed.
Lemma lin_flat_filter_absent : forall sg k w,
  countkey k w = O ->
  lin_flat (filter (fun x => negb (sKey x =? k)%N) sg) w
  = lin_flat sg w.
Proof.
  intros sg k w. induction w as [|g t IH]; intros HC; [reflexivity|].
  pose proof (countkey_tail_zero k g t HC) as HCT.
  cbn [lin_flat]. unfold keyb.
  destruct (keyi sg g) as [s|] eqn:HE.
  - assert (Hneq : sKey s <> k)
      by (eapply keyi_head_key_neq; eassumption).
    rewrite (keyi_filter_other sg g s k HE Hneq).
    f_equal. exact (IH HCT).
  - rewrite (keyi_filter_none (fun x => negb (sKey x =? k)%N)
               sg g HE).
    f_equal. exact (IH HCT).
Qed.
Lemma keyi_atmost_tail_zero : forall sg g t s,
  lin_atmost sg (g :: t) -> keyi sg g = Some s ->
  countkey (sKey s) t = O.
Proof.
  intros sg g t s HA HE.
  destruct (keyi_in sg g s HE) as (Hin & HP & HG).
  specialize (HA s Hin). cbn [countkey] in HA.
  rewrite HP, HG, N.eqb_refl in HA. cbn [andb] in HA. lia.
Qed.
Lemma keyi_phg_self : forall sg g s,
  keyi sg g = Some s ->
  keyi sg (phg (sKey s)) = Some s.
Proof.
  intros sg g s HE.
  destruct (keyi_in sg g s HE) as (_ & HP & HG).
  unfold phshape, tagbase in HP.
  destruct g as [[o z] c]. cbn [gO gZ gC] in HP, HG.
  repeat rewrite Bool.andb_true_iff in HP.
  destruct HP as [[HO HZ] HC].
  apply N.eqb_eq in HO. apply N.eqb_eq in HZ. subst o z.
  apply N.leb_le in HC.
  unfold phg.
  rewrite <- HG. exact HE.
Qed.
Theorem relax_flat : forall fu sg w before,
  SGS sg -> lin_atmost sg w ->
  lin_flat (snd (relax fu sg w before))
                   (fst (relax fu sg w before))
  = lin_flat sg w.
Proof.
  intros fu. induction fu as [|fu IH]; intros sg w before HSG HA.
  - cbn [relax fst snd]. reflexivity.
  - destruct w as [|g t]; [cbn [relax fst snd]; reflexivity|].
    cbn [relax]. cbv beta zeta iota.
    destruct (keyi sg g) as [s|] eqn:EK.
    + destruct (keyi_in sg g s EK) as (Hin & _ & _).
      destruct (SGS_in sg s HSG Hin) as (HCache & HOk & HShape).
      assert (HAlt : segalt (sBody s) = true).
      { unfold segshape in HShape.
        exact (proj2 (andb_prop _ _ HShape)). }
      assert (HCT : countkey (sKey s) t = O)
        by (eapply keyi_atmost_tail_zero; eassumption).
      match goal with
      | |- context [Nat.leb ?a ?b] => destruct (Nat.leb a b) eqn:ESM
      end.
      * match goal with
        | |- context [relax fu ?a ?b ?c] =>
            assert (HSG' : SGS a) by (apply SGS_filter; exact HSG);
            assert (HA' : lin_atmost a b)
              by (apply atmost_filter_tail with (g := g); exact HA);
            specialize (IH a b c HSG' HA');
            destruct (relax fu a b c) as [t' sg''] eqn:ER
        end.
        cbn [fst snd] in IH |- *.
        rewrite lin_flat_app_c.
        rewrite (flat_tagfree sg'' (sFlat s)
                   (tagfree_sFlat s HAlt)).
        rewrite IH.
        rewrite (lin_flat_filter_absent sg (sKey s) t HCT).
        rewrite lin_flat_cons. unfold keyb. rewrite EK.
        reflexivity.
      * match goal with
        | |- context [spill_front ?a ?b] =>
            pose proof (spill_front_key a b) as HKF;
            pose proof (spill_front_flat a b) as HFF;
            destruct (spill_front a b) as [fr s1] eqn:ESF
        end.
        cbn [snd] in HKF. cbn [fst snd] in HFF.
        match goal with
        | |- context [spill_back ?a ?b] =>
            pose proof (spill_back_key a b) as HKB;
            pose proof (spill_back_flat a b) as HBF;
            destruct (spill_back a b) as [s2 bk] eqn:ESB
        end.
        cbn [fst] in HKB. cbn [fst snd] in HBF.
        destruct (relax_step_shape s _ _ fr s1 s2 bk
                    HCache HOk HShape ESM ESF ESB)
          as (HC2 & HO2 & HS2).
        assert (HK2 : sKey s2 = sKey s)
          by (rewrite HKB, HKF; reflexivity).
        destruct (spill_tagfree s _ _ fr s1 s2 bk HAlt ESF ESB)
          as (HFR & _ & HBK).
        assert (HSG2 : SGS (sgset sg (sKey s) s2))
          by (apply SGS_sgset; [exact HSG|exact HC2|exact HO2|exact HS2]).
        assert (HA2 : lin_atmost (sgset sg (sKey s) s2)
                                  (bk ++ t))
          by (apply atmost_sgset_tagfree with (g := g);
              [exact HK2|exact HBK|exact HA]).
        assert (HCK : countkey (sKey s) (bk ++ t) = O)
          by (apply countkey_tagfree_app_zero; [exact HBK|exact HCT]).
        assert (HSelf : keyi sg (phg (sKey s))
                        = Some s) by (exact (keyi_phg_self sg g s EK)).
        assert (HSelf2 :
          keyi (sgset sg (sKey s) s2)
                       (phg (sKey s)) = Some s2).
        { rewrite (sgset_keyi sg (sKey s) s2
                    (phg (sKey s)) HK2), HSelf.
          rewrite N.eqb_refl. reflexivity. }
        match goal with
        | |- context [relax fu ?a ?b ?c] =>
            specialize (IH a b c HSG2 HA2);
            pose proof (relax_preserve_absent_key fu a b c
                          (sKey s) s2 HSG2 HSelf2 HCK) as HOutKey;
            destruct (relax fu a b c) as [t' sg''] eqn:ER
        end.
        cbn [fst snd] in IH, HOutKey |- *.
        rewrite lin_flat_app_c.
        rewrite (flat_tagfree sg'' fr HFR).
        rewrite lin_flat_cons. unfold keyb.
        rewrite HOutKey. rewrite IH.
        rewrite lin_flat_app_c.
        rewrite (flat_tagfree (sgset sg (sKey s) s2) bk HBK).
        rewrite (lin_flat_sgset sg (sKey s) s2 t
                   HK2 HCT).
        rewrite lin_flat_cons. unfold keyb. rewrite EK.
        cbn [fst snd] in HFF, HBF.
        assert (HSpill : fr ++ sFlat s2 ++ bk = sFlat s).
        { rewrite HBF. exact HFF. }
        rewrite (app_assoc (sFlat s2) bk (lin_flat sg t)).
        rewrite (app_assoc fr (sFlat s2 ++ bk)
                   (lin_flat sg t)).
        rewrite HSpill. reflexivity.
    + match goal with
      | |- context [relax fu ?a ?b ?c] =>
          specialize (IH a b c HSG (atmost_tail sg g t HA));
          pose proof (relax_keys fu a b c) as HKeys;
          destruct (relax fu a b c) as [t' sg'] eqn:ER
      end.
      cbn [fst snd] in IH, HKeys |- *.
      assert (ENone : keyi sg' g = None)
        by (apply keyi_none_keys_incl with (sg2 := sg); assumption).
      rewrite !lin_flat_cons. unfold keyb.
      rewrite ENone, EK. f_equal. exact IH.
Qed.
Theorem lin_relax_flat : forall sg w w2 sg2,
  sg_wf sg -> sg_shape sg ->
  lin_ok sg w = true ->
  lin_relax sg w = (w2, sg2) ->
  lin_flat sg2 w2 = lin_flat sg w.
Proof.
  intros sg w w2 sg2 HW HS HOk HR.
  pose proof (relax_flat (length w) sg w
    (GUARD + SLACK)%nat (SGS_of sg HW HS)
    (lin_ok_atmost sg w HOk)) as H.
  unfold lin_relax in HR. rewrite HR in H. exact H.
Qed.
Lemma lin_ptags_tagfree : forall sg w,
  tagfree w = true -> lin_ptags sg w = true.
Proof.
  intros sg w. induction w as [|g w IH]; intros H; [reflexivity|].
  unfold tagfree in H. cbn [forallb] in H.
  apply andb_prop in H as [HG HW].
  cbn [lin_ptags]. apply andb_true_intro. split.
  - apply negb_true_iff in HG.
    rewrite (phshape_false_of_tagbase_false g HG).
    reflexivity.
  - exact (IH HW).
Qed.
Lemma lin_ptags_tail : forall sg g t,
  lin_ptags sg (g :: t) = true ->
  lin_ptags sg t = true.
Proof.
  intros sg g t H. cbn [lin_ptags] in H.
  exact (proj2 (andb_prop _ _ H)).
Qed.
Lemma lin_ptags_filter_absent : forall sg k w,
  countkey k w = O -> lin_ptags sg w = true ->
  lin_ptags
    (filter (fun x => negb (sKey x =? k)%N) sg) w = true.
Proof.
  intros sg k w. induction w as [|g t IH]; intros HC HT; [reflexivity|].
  pose proof (countkey_tail_zero k g t HC) as HCT.
  cbn [lin_ptags] in HT |- *.
  apply andb_prop in HT as [HG HT]. apply andb_true_intro. split.
  - destruct (phshape g) eqn:EP;
      cbn [negb orb] in HG |- *; [|reflexivity].
    unfold ph in HG |- *.
    destruct (keyi sg g) as [s|] eqn:EK; [|discriminate HG].
    assert (Hneq : sKey s <> k)
      by (eapply keyi_head_key_neq; eassumption).
    rewrite (keyi_filter_other sg g s k EK Hneq). reflexivity.
  - exact (IH HCT HT).
Qed.
Theorem relax_ptags : forall fu sg w before,
  SGS sg -> lin_atmost sg w -> lin_ptags sg w = true ->
  lin_ptags (snd (relax fu sg w before))
                        (fst (relax fu sg w before)) = true.
Proof.
  intros fu. induction fu as [|fu IH]; intros sg w before HSG HA HT.
  - cbn [relax fst snd]. exact HT.
  - destruct w as [|g t]; [reflexivity|].
    pose proof (lin_ptags_tail sg g t HT) as HTT.
    assert (HTH : negb (phshape g) || ph sg g = true).
    { cbn [lin_ptags] in HT.
      exact (proj1 (andb_prop _ _ HT)). }
    cbn [relax]. cbv beta zeta iota.
    destruct (keyi sg g) as [s|] eqn:EK.
    + destruct (keyi_in sg g s EK) as (Hin & _ & _).
      destruct (SGS_in sg s HSG Hin) as (HCache & HOk & HShape).
      assert (HAlt : segalt (sBody s) = true).
      { unfold segshape in HShape.
        exact (proj2 (andb_prop _ _ HShape)). }
      assert (HCT : countkey (sKey s) t = O)
        by (eapply keyi_atmost_tail_zero; eassumption).
      match goal with
      | |- context [Nat.leb ?a ?b] => destruct (Nat.leb a b) eqn:ESM
      end.
      * match goal with
        | |- context [relax fu ?a ?b ?c] =>
            assert (HSG' : SGS a) by (apply SGS_filter; exact HSG);
            assert (HA' : lin_atmost a b)
              by (apply atmost_filter_tail with (g := g); exact HA);
            assert (HT' : lin_ptags a b = true)
              by (apply lin_ptags_filter_absent; [exact HCT|exact HTT]);
            specialize (IH a b c HSG' HA' HT');
            destruct (relax fu a b c) as [t' sg''] eqn:ER
        end.
        cbn [fst snd] in IH |- *.
        apply lin_ptags_app_true.
        -- apply lin_ptags_tagfree. exact (tagfree_sFlat s HAlt).
        -- exact IH.
      * match goal with
        | |- context [spill_front ?a ?b] =>
            pose proof (spill_front_key a b) as HKF;
            destruct (spill_front a b) as [fr s1] eqn:ESF
        end.
        cbn [snd] in HKF.
        match goal with
        | |- context [spill_back ?a ?b] =>
            pose proof (spill_back_key a b) as HKB;
            destruct (spill_back a b) as [s2 bk] eqn:ESB
        end.
        cbn [fst] in HKB.
        destruct (relax_step_shape s _ _ fr s1 s2 bk
                    HCache HOk HShape ESM ESF ESB)
          as (HC2 & HO2 & HS2).
        assert (HK2 : sKey s2 = sKey s)
          by (rewrite HKB, HKF; reflexivity).
        destruct (spill_tagfree s _ _ fr s1 s2 bk HAlt ESF ESB)
          as (HFR & _ & HBK).
        assert (HSG2 : SGS (sgset sg (sKey s) s2))
          by (apply SGS_sgset; [exact HSG|exact HC2|exact HO2|exact HS2]).
        assert (HA2 : lin_atmost (sgset sg (sKey s) s2)
                                  (bk ++ t))
          by (apply atmost_sgset_tagfree with (g := g);
              [exact HK2|exact HBK|exact HA]).
        assert (HCK : countkey (sKey s) (bk ++ t) = O)
          by (apply countkey_tagfree_app_zero; [exact HBK|exact HCT]).
        assert (HSelf : keyi sg (phg (sKey s))
                        = Some s) by (exact (keyi_phg_self sg g s EK)).
        assert (HSelf2 :
          keyi (sgset sg (sKey s) s2)
                       (phg (sKey s)) = Some s2).
        { rewrite (sgset_keyi sg (sKey s) s2
                    (phg (sKey s)) HK2), HSelf.
          rewrite N.eqb_refl. reflexivity. }
        assert (HT2 : lin_ptags
          (sgset sg (sKey s) s2) (bk ++ t) = true).
        { apply lin_ptags_app_true.
          - apply lin_ptags_tagfree. exact HBK.
          - eapply lin_ptags_mono; [|exact HTT].
            intros x HX. eapply ph_sgset_preserve;
              [exact HK2|exact HX]. }
        match goal with
        | |- context [relax fu ?a ?b ?c] =>
            specialize (IH a b c HSG2 HA2 HT2);
            pose proof (relax_preserve_absent_key fu a b c
                          (sKey s) s2 HSG2 HSelf2 HCK) as HOutKey;
            destruct (relax fu a b c) as [t' sg''] eqn:ER
        end.
        cbn [fst snd] in IH, HOutKey |- *.
        apply lin_ptags_app_true.
        -- apply lin_ptags_tagfree. exact HFR.
        -- cbn [lin_ptags]. apply andb_true_intro. split.
           ++ unfold ph. rewrite HOutKey, orb_true_r. reflexivity.
           ++ exact IH.
    + match goal with
      | |- context [relax fu ?a ?b ?c] =>
          specialize (IH a b c HSG (atmost_tail sg g t HA) HTT);
          destruct (relax fu a b c) as [t' sg'] eqn:ER
      end.
      cbn [fst snd] in IH |- *.
      cbn [lin_ptags]. apply andb_true_intro. split.
      * destruct (phshape g) eqn:EP;
          cbn [negb orb] in *; [|reflexivity].
        unfold ph in HTH. rewrite EK in HTH. discriminate.
      * exact IH.
Qed.
Theorem lin_relax_ptags : forall sg w w2 sg2,
  sg_wf sg -> sg_shape sg ->
  lin_ok sg w = true -> lin_ptags sg w = true ->
  lin_relax sg w = (w2, sg2) ->
  lin_ptags sg2 w2 = true.
Proof.
  intros sg w w2 sg2 HW HS HOk HT HR.
  pose proof (relax_ptags (length w) sg w
    (GUARD + SLACK)%nat (SGS_of sg HW HS)
    (lin_ok_atmost sg w HOk) HT) as H.
  unfold lin_relax in HR. rewrite HR in H. exact H.
Qed.
Open Scope N_scope.
Open Scope bool_scope.
Opaque LROUND_FUEL LROUND_CHUNKS
       FLAT_ROUND_FUEL CFUEL TRIES.
Definition seg_pos (s : seg) : bool :=
  segpos s.
Definition sg_pos (sg : list seg) : Prop :=
  forallb seg_pos sg = true.
Lemma sg_pos_seg : forall sg s,
  sg_pos sg -> In s sg -> seg_pos s = true.
Proof.
  intros sg s HP Hin. unfold sg_pos in HP.
  eapply forallb_forall in HP; [exact HP|exact Hin].
Qed.
Lemma segok_level_bound : forall s g,
  segok s = true -> In g (sBody s) ->
  is_lvl g = true -> (sMin s <= gC g)%N.
Proof.
  intros s g HOk Hin Hlvl.
  unfold segok in HOk. cbv zeta in HOk.
  destruct (sBody s) as [|g0 b] eqn:EB; [discriminate|].
  cbv beta iota in HOk.
  repeat rewrite Bool.andb_true_iff in HOk.
  destruct HOk as [[[[H0 Hlast] Hodd] Hcasc] Hbound].
  eapply forallb_forall in Hbound; [|exact Hin].
  rewrite Hlvl in Hbound. cbn [negb orb] in Hbound.
  apply N.leb_le. exact Hbound.
Qed.
Lemma adjk_level_count : forall p g,
  is_lvl g = true ->
  gC (adjk p g) = (gC g - 4 * p)%N.
Proof.
  intros p [[o z] c] Hlvl.
  unfold is_lvl in Hlvl.
  cbn [gO gZ gC] in Hlvl |- *.
  apply andb_prop in Hlvl as [Ho Hz].
  apply N.eqb_eq in Ho, Hz. subst o z.
  reflexivity.
Qed.
Lemma sflat_level_pos : forall s g,
  segok s = true -> seg_pos s = true ->
  In g (sFlat s) -> is_lvl g = true ->
  (1 <= gC g)%N.
Proof.
  intros s g HOk HP Hin Hlvl.
  unfold sFlat, matb in Hin.
  apply in_map_iff in Hin. destruct Hin as (g0 & Eg & Hin0).
  subst g.
  assert (Hlvl0 : is_lvl g0 = true).
  { destruct g0 as [[o z] c].
    unfold adjk in Hlvl.
    destruct ((o =? 4) && (z =? 2))%N eqn:E.
    - apply andb_prop in E as [Ho Hz].
      apply N.eqb_eq in Ho, Hz. subst o z. reflexivity.
    - exact Hlvl. }
  pose proof (segok_level_bound s g0 HOk Hin0 Hlvl0) as Hmin.
  unfold seg_pos in HP. apply N.leb_le in HP.
  rewrite (adjk_level_count _ _ Hlvl0).
  lia.
Qed.
Lemma sflat_last_guard : forall s,
  segcache s = true -> segok s = true ->
  seg_pos s = true ->
  exists ini g, sFlat s = ini ++ [g] /\
    ((3 <=? gO g) && (1 <=? gC g))%N = true.
Proof.
  intros s HC HOk HP.
  destruct (sflat_last_lvl s HC HOk)
    as (ini & g & E & Hlvl).
  exists ini, g. split; [exact E|].
  apply andb_true_intro. split.
  - unfold is_lvl in Hlvl.
    apply andb_prop in Hlvl as [Ho _].
    apply N.eqb_eq in Ho. rewrite Ho. reflexivity.
  - apply N.leb_le.
    apply (sflat_level_pos s g HOk HP).
    + rewrite E. apply in_or_app. right. cbn [In]. auto.
    + exact Hlvl.
Qed.
Lemma last1_app_single : forall (u : word) g,
  last1 (u ++ [g]) = Some g.
Proof.
  induction u as [|a [|b u] IH]; intros g;
    cbn [app last1]; try reflexivity.
  exact (IH g).
Qed.
Lemma last1_decomp : forall (u : word) g,
  last1 u = Some g -> exists u', u = u' ++ [g].
Proof.
  induction u as [|a [|b u] IH]; intros g H;
    cbn [last1] in H.
  - discriminate.
  - injection H as <-. exists (@nil bg). reflexivity.
  - destruct (IH g H) as (u' & E). exists (a :: u').
    cbn [app]. f_equal. exact E.
Qed.
Lemma flat_last_guard : forall sg u,
  sg_wf sg -> sg_pos sg ->
  (match last1 u with
   | Some g => ((3 <=? gO g) && (1 <=? gC g))%N
   | None => false
   end) = true ->
  (match last1 (lin_flat sg u) with
   | Some g => ((3 <=? gO g) && (1 <=? gC g))%N
   | None => false
   end) = true.
Proof.
  intros sg u HW HP Hlast.
  destruct (last1 u) as [g|] eqn:EL; [|discriminate].
  destruct (last1_decomp u g EL) as (pre & ->).
  rewrite lin_flat_app_c.
  rewrite lin_flat_cons.
  unfold keyb.
  destruct (keyi sg g) as [s|] eqn:EK.
  - destruct (keyi_in sg g s EK) as (Hin & _ & _).
    destruct (sg_wf_seg sg s HW Hin) as (HC & HOk).
    pose proof (sg_pos_seg sg s HP Hin) as HPos.
    destruct (sflat_last_guard s HC HOk HPos)
      as (ini & gl & ES & HG).
    cbn [lin_flat app]. rewrite !app_nil_r, ES, app_assoc.
    rewrite last1_app_single. exact HG.
  - cbn [lin_flat app]. rewrite last1_app_single.
    exact Hlast.
Qed.
Lemma flat_forallb_is_col : forall sg u,
  sg_wf sg ->
  forallb (fun g => ph sg g || is_col g) u = true ->
  forallb is_col (lin_flat sg u) = true.
Proof.
  intros sg u HW. induction u as [|a u IH]; intros H; [reflexivity|].
  cbn [forallb] in H. apply andb_prop in H as [Hg Hu].
  rewrite lin_flat_cons. unfold keyb.
  destruct (keyi sg a) as [s|] eqn:EK.
  - rewrite forallb_app. apply andb_true_intro. split.
    + apply forallb_forall. intros g Hin.
      destruct (keyi_in sg a s EK) as (Hs & _ & _).
      destruct (sg_wf_seg sg s HW Hs) as (_ & HOk).
      exact (sflat_is_col s g HOk Hin).
    + apply IH. exact Hu.
  - cbn [forallb]. rewrite (IH Hu), andb_true_r.
    unfold ph in Hg. rewrite EK in Hg.
    cbn [orb] in Hg. exact Hg.
Qed.
Lemma find_active_lb : forall w s i,
  find_active w s = Some i -> (s <= i)%nat.
Proof.
  intros w s i H. unfold find_active in H.
  revert H. generalize (skipn s w) as u. intros u.
  revert s i. induction u as [|g u IH]; intros s i H; [discriminate|].
  cbn [find_active_s] in H.
  destruct ((gZ g =? 1) || (3 <=? gZ g))%N.
  - injection H as <-. lia.
  - pose proof (IH (S s) i H). lia.
Qed.
Lemma firstn_add_skip : forall (A : Type) s d (w : list A),
  firstn (s + d) w = firstn s w ++ firstn d (skipn s w).
Proof.
  induction s as [|s IH]; intros d w; [reflexivity|].
  destruct w as [|x w]; [cbn; rewrite firstn_nil; reflexivity|].
  cbn [Nat.add firstn skipn app]. f_equal. apply IH.
Qed.
Lemma firstn_skipn_split : forall (A : Type) (w : list A) s i,
  (s <= i)%nat ->
  firstn i w = firstn s w ++ firstn (i - s) (skipn s w).
Proof.
  intros A w s i Hle.
  replace i with (s + (i - s))%nat at 1 by lia.
  apply firstn_add_skip.
Qed.
Lemma skipn_len_app : forall (A : Type) (a b : list A),
  skipn (length a) (a ++ b) = b.
Proof. induction a; intros b; [reflexivity|cbn; apply IHa]. Qed.
Lemma find_active_flat : forall sg w s i,
  sg_wf sg ->
  find_active w s = Some i ->
  find_active (lin_flat sg w)
    (length (lin_flat sg (firstn s w)))
  = Some (length (lin_flat sg (firstn i w))).
Proof.
  intros sg w s i HW HFA.
  pose proof (find_active_lb _ _ _ HFA) as Hlb.
  unfold find_active in *.
  assert (ESK : skipn (length (lin_flat sg (firstn s w)))
                  (lin_flat sg w)
                = lin_flat sg (skipn s w)).
  { rewrite (flat_firstn_skipn sg w s).
    apply skipn_len_app. }
  rewrite ESK.
  rewrite (find_active_s_flat_gen sg (skipn s w) s _ HW).
  rewrite HFA. f_equal.
  rewrite (firstn_skipn_split _ w s i Hlb).
  rewrite lin_flat_app_c, length_app. reflexivity.
Qed.
Lemma flat_cons_notagbase : forall sg g t,
  tagbase g = false ->
  lin_flat sg (g :: t) = g :: lin_flat sg t.
Proof.
  intros sg [[o z] c] t HB.
  apply flat_cons_nonlvl.
  unfold phshape, tagbase in *.
  cbn [gO gZ gC] in *.
  rewrite HB. reflexivity.
Qed.
Lemma flat_notagbase_single : forall sg g,
  tagbase g = false -> lin_flat sg [g] = [g].
Proof.
  intros sg g H. rewrite flat_cons_notagbase by exact H. reflexivity.
Qed.
Definition flat_comp (sg : list seg)
    (r : option (ckind * word * N))
  : option (ckind * word * N) :=
  match r with
  | Some (k, w, f) => Some (k, lin_flat sg w, f)
  | None => None
  end.
Definition site_comp (w1 : word) (i : nat) (f : N)
  : option (ckind * word * N) :=
  let sfx := skipn i w1 in
  match sfx with
  | [] => None
  | (o4,z4,c4) :: s2t =>
      if (o4 =? 4) && (z4 =? 3) && (c4 =? 1)
         && Nat.leb 3 i then
        match s2t with
        | [] =>
            match endR_seg (firstn i w1) f with
            | Some body => Some (JMP, body, 3)
            | None => None
            end
        | (o5,z5,b5) :: rest2 =>
            if (o5 =? 4) && (z5 =? 2) then
              if 1 <=? b5 then
                jump_comp (firstn i w1) b5 rest2 f
              else None
            else if (z5 =? 3) && (b5 =? 1)
                    && match rest2 with [] => true | _ => false end
                    && (f =? 4) && (1 <=? o5) then
              match endY_seg (firstn i w1) o5 with
              | Some body => Some (JMP, body, f - 1)
              | None => None
              end
            else
              match fire_comp (length ((o4,z4,c4) :: s2t))
                      ((o4,z4,c4) :: s2t) f with
              | Some (s', f2) => Some (STD, s', f2)
              | None => None
              end
        end
      else if (z4 =? 3) && (c4 =? 1) then
        match fire_comp (length ((o4,z4,c4) :: s2t))
                ((o4,z4,c4) :: s2t) f with
        | Some (s', f2) => Some (STD, s', f2)
        | None => None
        end
      else if z4 =? 1 then
        match leaf_act ((o4,z4,c4) :: s2t) f with
        | Some (s', f2) => Some (STD, s', f2)
        | None => None
        end
      else if (z4 =? 4) && (c4 =? 1) then
        match s2t with
        | (on,zn,cn) :: t2 =>
            if (o4 =? 4) && (on =? 4) && (zn =? 2) && (1 <=? cn) then
              match last2 (firstn i w1) with
              | Some (ini, (ga,gaz,gac), (gb,gbz,gbc)) =>
                  if (ga =? 8) && (gaz =? 2) && (gac =? 1)
                     && (gb =? 4) && (gbz =? 2) && (1 <=? gbc)
                  then Some (JMP,
                         ini ++ [(7,1,1); (3,2,1); (gb,gbz,gbc);
                                 (8,2,1)]
                             ++ (if 1 <? cn then [(4,2,cn-1)] else [])
                             ++ t2, f)
                  else None
              | None => None
              end
            else if (4 <? o4) && (on =? 4) && (zn =? 2)
                    && (1 <=? cn) then
              Some (STD, (o4-1,1,1) :: (7,2,1)
                         :: (if 1 <? cn then [(4,2,cn-1)] else [])
                         ++ t2, f)
            else None
        | [] =>
            if (o4 =? 4) && (1 <=? f) then
              match last2 (firstn i w1) with
              | Some (ini, (ga,gaz,gac), (gb,gbz,gbc)) =>
                  if (ga =? 8) && (gaz =? 2) && (gac =? 1)
                     && (gb =? 4) && (gbz =? 2) && (1 <=? gbc)
                  then Some (JMP,
                         ini ++ [(7,1,1); (3,2,1); (gb,gbz,gbc)], f + 4)
                  else if (gb =? 8) && (gbz =? 2) && (gbc =? 1)
                  then Some (JMP,
                         ini ++ [(ga,gaz,gac); (7,1,1); (3,2,1)], f + 4)
                  else None
              | None => None
              end
            else None
        end
      else None
  end.
Lemma jump_comp_flat_z : forall sg pre B post f,
  sg_wf sg -> keys_big sg ->
  sg_live sg ->
  ph_notlast sg pre ->
  nbrs1z sg post ->
  jump_comp (lin_flat sg pre) B
    (lin_flat sg post) f
  = flat_comp sg (jump_comp pre B post f).
Proof.
  intros sg pre B post f HW HK HL HP HN.
  destruct post as [|g rest].
  - cbn [lin_flat jump_comp flat_comp].
    destruct (f =? 4)%N eqn:Ef4.
    + rewrite (lawR_wrap sg pre B HW HK HP).
      destruct (lawR_seg pre B) as [body|]; reflexivity.
    + destruct (5 <=? f)%N eqn:Ef5; [|reflexivity].
      rewrite (jump_wrap sg pre B HW HK HP).
      destruct (jump_seg pre B) as [segp|]; [|reflexivity].
      cbn [flat_comp]. f_equal. f_equal.
      rewrite lin_flat_app_c.
      f_equal.
      f_equal. symmetry. apply flat_notagbase_single.
      unfold tagbase. cbn [gO gZ].
      rewrite andb_false_r. reflexivity.
  - destruct (flat_cons_ex sg g rest HW)
      as (gf & rf & EPost).
    unfold jump_comp at 1 2.
    rewrite EPost.
    rewrite (jump_wrap sg pre B HW HK HP).
    destruct (jump_seg pre B) as [segp|] eqn:EJump;
      [|reflexivity].
    cbv beta iota zeta.
    pose proof (seek_flat sg (g :: rest) HW) as ESeek.
    destruct (seek (g :: rest)) as [cols s3] eqn:ES.
    cbn [fst snd] in ESeek. rewrite EPost in ESeek.
    rewrite ESeek. cbv beta iota zeta.
    pose proof (LineageGuard_seek_split (g :: rest)) as HSplit.
    rewrite ES in HSplit. cbn [fst snd] in HSplit.
    assert (HN3 : nbrs1z sg s3).
    { apply (nbrs1z_app_r sg cols s3).
      rewrite <- HSplit. exact HN. }
    assert (Hhead : forall gh t, s3 = gh :: t ->
                    ph sg gh = false).
    { intros gh t Egh.
      exact (nbrs1z_seek_snd_head sg (g :: rest) gh t HN
               ltac:(rewrite ES; exact Egh)). }
    assert (HPcols : forall t,
      s3 = (4%N,3%N,1%N) :: t -> ph_notlast sg cols).
    { intros t Et.
      pose proof (nbrs1z_seek_notlast sg (g :: rest)
                    (4%N,3%N,1%N) t HN
                    ltac:(rewrite ES; exact Et)
                    ltac:(reflexivity) ltac:(cbn [gZ]; lia)) as H0.
      rewrite ES in H0. cbn [fst]. exact H0. }
    assert (ERen :
      renew_seg (length (lin_flat sg s3))
        (lin_flat sg cols) (lin_flat sg s3) f
      = flat_res sg
          (renew_seg (length s3) cols s3 f)).
    { pose proof (proj2 (fire_renew_flat_z
                           (length (lin_flat sg s3)) sg HW HK HL)
                    cols s3 f HPcols HN3 Hhead) as H0.
      rewrite (renew_seg_sat cols s3 f
                 (length (lin_flat sg s3))) in H0.
      - exact H0.
      - exact (flat_len_ge sg s3 HW). }
    rewrite ERen.
    destruct (renew_seg (length s3) cols s3 f)
      as [[body f2]|] eqn:ER; cbn [flat_res flat_comp].
    + f_equal. f_equal.
      rewrite !lin_flat_app_c. reflexivity.
    + destruct s3 as [|[[o7 z7] c7] t7].
      * cbn [lin_flat leaf_act].
        destruct (5 <=? f)%N eqn:Ef5.
        -- cbn [flat_comp]. f_equal. f_equal.
           rewrite !lin_flat_app_c. f_equal. f_equal. f_equal.
           symmetry. apply flat_notagbase_single.
           unfold tagbase. cbn [gO gZ].
           rewrite andb_false_r. reflexivity.
        -- destruct (f =? 4)%N eqn:Ef4; [|reflexivity].
           assert (HNcols : ph_nbrs sg cols).
           { pose proof (nbrs1z_seek_all sg (g :: rest) HN
                           ltac:(rewrite ES; reflexivity)) as H0.
             rewrite ES in H0. cbn [fst]. exact H0. }
           pose proof (dtb4_conv_flat sg cols HW HK HNcols)
             as ED4.
           rewrite ED4.
           destruct (dtb4_conv cols) as [cols'|] eqn:ED;
             cbn [flat_comp].
           ++ f_equal. f_equal.
              rewrite !lin_flat_app_c. reflexivity.
           ++ assert (EW : forallb w42 (lin_flat sg cols)
                            = forallb w42 cols).
              { apply (w42_forallb_flat sg cols HW HNcols).
                intros p gp Hp0 Hph.
                exact (proj1 (HNcols p gp Hp0 Hph)). }
              rewrite EW.
              destruct (forallb w42 cols) eqn:E42; [|reflexivity].
              rewrite (lawR_wrap sg pre B HW HK HP).
              destruct (lawR_seg pre B) as [seg2|] eqn:EL;
                cbn [flat_comp]; [|reflexivity].
              f_equal. f_equal.
              rewrite !lin_flat_app_c. reflexivity.
      * assert (Hph7 : ph sg (o7,z7,c7) = false)
          by (exact (Hhead _ _ eq_refl)).
        assert (EF7 : lin_flat sg ((o7,z7,c7) :: t7)
                      = (o7,z7,c7) :: lin_flat sg t7)
          by (apply flat_cons_nonph; exact Hph7).
        xrewrite EF7. cbv beta iota.
        destruct ((z7 =? 3) && (c7 =? 1))%N eqn:E73.
        -- assert (EFire :
             fire_comp (length (lin_flat sg ((o7,z7,c7)::t7)))
               (lin_flat sg ((o7,z7,c7)::t7)) f
             = flat_res sg
                 (fire_comp (length ((o7,z7,c7)::t7))
                    ((o7,z7,c7)::t7) f)).
           { pose proof (proj1 (fire_renew_flat_z
                                  (length (lin_flat sg
                                             ((o7,z7,c7)::t7)))
                                  sg HW HK HL)
                           ((o7,z7,c7)::t7) f HN3
                           ltac:(intros gh tt E; injection E as <- _;
                                 exact Hph7)) as H0.
             rewrite (fire_comp_sat ((o7,z7,c7)::t7) f
                        (length (lin_flat sg ((o7,z7,c7)::t7))))
               in H0.
             - exact H0.
             - exact (flat_len_ge sg ((o7,z7,c7)::t7) HW). }
           rewrite EF7 in EFire. rewrite EFire.
           destruct (fire_comp (length ((o7,z7,c7)::t7))
                       ((o7,z7,c7)::t7) f) as [[s' f']|] eqn:EF.
           ++ xrewrite EF.
              cbn [flat_res flat_comp].
              f_equal. f_equal.
              rewrite !lin_flat_app_c. reflexivity.
           ++ xrewrite EF.
              cbn [flat_res flat_comp]. reflexivity.
        -- assert (ESand : sand_leaf (lin_flat sg
                              ((o7,z7,c7)::t7))
                            = sand_leaf ((o7,z7,c7)::t7)).
           { apply sand_leaf_flat; [exact HW|].
             intros gh tt E. injection E as <- _. exact Hph7. }
           rewrite EF7 in ESand. rewrite ESand.
           destruct (sand_leaf ((o7,z7,c7)::t7)) eqn:ES0.
           ++ xrewrite ES0. cbn [flat_comp]. reflexivity.
           ++ xrewrite ES0. cbv beta iota.
           pose proof (leaf_act_flat_z sg
                         ((o7,z7,c7)::t7) f HW HK HN3
                         ltac:(intros gh tt E; injection E as <- _;
                               exact Hph7)) as ELeaf.
           rewrite EF7 in ELeaf. rewrite ELeaf.
           destruct (leaf_act ((o7,z7,c7)::t7) f)
             as [[s' f']|] eqn:EL.
           +++ xrewrite EL.
               cbn [flat_res flat_comp].
               f_equal. f_equal.
               rewrite !lin_flat_app_c. reflexivity.
           +++ xrewrite EL.
               cbn [flat_res flat_comp]. reflexivity.
Qed.
Lemma LineageSplice_lin_split_at_spec : forall n (w : word),
  lin_split_at n w = (firstn n w, skipn n w).
Proof.
  induction n as [|n IH]; intros [|g w];
    cbn [lin_split_at firstn skipn]; try reflexivity.
  rewrite IH. reflexivity.
Qed.
Lemma flat_normalize_slice_expand : forall sg w,
  expand (map gdecode
    (lin_flat sg (lin_normalize_slice sg w)))
  = expand (map gdecode (lin_flat sg w)).
Proof.
  intros sg w. unfold lin_normalize_slice.
  pose proof (flat_lin_normalize_full_sd sg w 0) as H.
  unfold sdecode, bdecode, frun in H.
  cbn [app] in H. rewrite !app_nil_r in H. exact H.
Qed.
Lemma flat_replace_mid_sdecode : forall sg pre a b post f,
  expand (map gdecode (lin_flat sg a))
  = expand (map gdecode (lin_flat sg b)) ->
  sdecode (lin_flat sg (pre ++ a ++ post)) f
  = sdecode (lin_flat sg (pre ++ b ++ post)) f.
Proof.
  intros sg pre a b post f E.
  rewrite !lin_flat_app_c.
  change (sdec
    (lin_flat sg pre ++ lin_flat sg a
       ++ lin_flat sg post) f
    = sdec
    (lin_flat sg pre ++ lin_flat sg b
       ++ lin_flat sg post) f).
  rewrite !sdec_app. rewrite E. reflexivity.
Qed.
Lemma lin_normalize_at_flat_sdecode : forall sg w center f,
  sdecode (lin_flat sg
    (lin_normalize_at sg w center)) f
  = sdecode (lin_flat sg w) f.
Proof.
  intros sg w center f.
  unfold lin_normalize_at. cbv beta zeta.
  destruct (Nat.eqb center O); [reflexivity|].
  destruct (lin_nadj_span 6 sg (skipn (center - 2) w));
    [reflexivity|].
  rewrite !LineageSplice_lin_split_at_spec. cbn [fst snd].
  assert (EW : w = firstn (center - 2) w
                    ++ firstn 6 (skipn (center - 2) w)
                    ++ skipn 6 (skipn (center - 2) w)).
  { rewrite firstn_skipn, firstn_skipn. reflexivity. }
  transitivity (sdecode (lin_flat sg
    (firstn (center - 2) w
      ++ firstn 6 (skipn (center - 2) w)
      ++ skipn 6 (skipn (center - 2) w))) f).
  - apply flat_replace_mid_sdecode.
    apply flat_normalize_slice_expand.
  - rewrite <- EW. reflexivity.
Qed.
Lemma lin_normalize_join_flat_sdecode : forall sg pre sfx f,
  sdecode (lin_flat sg
    (lin_normalize_join sg pre sfx)) f
  = sdecode (lin_flat sg (pre ++ sfx)) f.
Proof.
  intros sg pre. induction pre as [|g pre IH]; intros sfx f.
  - cbn [lin_normalize_join app].
    rewrite LineageSplice_lin_split_at_spec. cbn [fst snd].
    transitivity (sdecode (lin_flat sg
      (firstn 6 sfx ++ skipn 6 sfx)) f).
    + apply (flat_replace_mid_sdecode sg []
      (lin_normalize_slice sg (firstn 6 sfx))
      (firstn 6 sfx) (skipn 6 sfx) f).
      apply flat_normalize_slice_expand.
    + rewrite firstn_skipn. reflexivity.
  - destruct pre as [|g1 pre1].
    + cbn [lin_normalize_join app].
      rewrite LineageSplice_lin_split_at_spec. cbn [fst snd].
      transitivity (sdecode (lin_flat sg
        ((g :: firstn 5 sfx) ++ skipn 5 sfx)) f).
      * apply (flat_replace_mid_sdecode sg []
          (lin_normalize_slice sg (g :: firstn 5 sfx))
          (g :: firstn 5 sfx) (skipn 5 sfx) f).
        apply flat_normalize_slice_expand.
      * cbn [app]. rewrite firstn_skipn. reflexivity.
    + destruct pre1 as [|g2 tail].
      * cbn [lin_normalize_join app].
        rewrite LineageSplice_lin_split_at_spec. cbn [fst snd].
        transitivity (sdecode (lin_flat sg
          ((g :: g1 :: firstn 4 sfx) ++ skipn 4 sfx)) f).
        -- apply (flat_replace_mid_sdecode sg []
             (lin_normalize_slice sg
               (g :: g1 :: firstn 4 sfx))
             (g :: g1 :: firstn 4 sfx) (skipn 4 sfx) f).
           apply flat_normalize_slice_expand.
        -- cbn [app]. rewrite firstn_skipn. reflexivity.
      * cbn [lin_normalize_join app] in *.
        apply flat_cons_ctx.
        apply IH.
Qed.
Lemma forallb_is_col_phcol : forall sg w,
  forallb is_col w = true ->
  forallb (fun g => ph sg g || is_col g) w = true.
Proof.
  intros sg w. induction w as [|g w IH]; intros H; [reflexivity|].
  cbn [forallb] in H |- *. apply andb_prop in H as [Hg Hw].
  rewrite Hg, Bool.orb_true_r. cbn [andb]. exact (IH Hw).
Qed.
Lemma flat_checked_prefix_cols : forall sg w,
  sg_wf sg ->
  forallb is_col w = true ->
  forallb is_col (lin_flat sg w) = true.
Proof.
  intros sg w HW HC. apply flat_forallb_is_col; [exact HW|].
  exact (forallb_is_col_phcol sg w HC).
Qed.
Lemma fire_flat_len : forall sg s f,
  sg_wf sg -> keys_big sg ->
  sg_live sg ->
  nbrs1z sg s ->
  (forall g t, s = g :: t -> ph sg g = false) ->
  fire_comp (length (lin_flat sg s))
    (lin_flat sg s) f =
  flat_res sg (fire_comp (length s) s f).
Proof.
  intros sg s f HW HK HL HN HH.
  pose proof (proj1 (fire_renew_flat_z
    (length (lin_flat sg s)) sg HW HK HL) s f HN HH) as H.
  rewrite (fire_comp_sat s f
    (length (lin_flat sg s))
    (flat_len_ge sg s HW)) in H.
  exact H.
Qed.
Definition z4_mid (cols : word) (B : N) (tail : word)
  : option word :=
  match last2 cols with
  | Some (ini, (ga,gaz,gac), (gb,gbz,gbc)) =>
      if (ga =? 8) && (gaz =? 2) && (gac =? 1)
         && (gb =? 4) && (gbz =? 2) && (1 <=? gbc)
      then Some (ini ++ [(7,1,1); (3,2,1); (gb,gbz,gbc); (8,2,1)]
                    ++ (if 1 <? B then [(4,2,B-1)] else []) ++ tail)
      else None
  | None => None
  end.
Definition z4_end (cols : word) : option word :=
  match last2 cols with
  | Some (ini, (ga,gaz,gac), (gb,gbz,gbc)) =>
      if (ga =? 8) && (gaz =? 2) && (gac =? 1)
         && (gb =? 4) && (gbz =? 2) && (1 <=? gbc)
      then Some (ini ++ [(7,1,1); (3,2,1); (gb,gbz,gbc)])
      else if (gb =? 8) && (gbz =? 2) && (gbc =? 1)
      then Some (ini ++ [(ga,gaz,gac); (7,1,1); (3,2,1)])
      else None
  | None => None
  end.
Lemma z4_mid_wrap : forall sg cols B tail,
  sg_wf sg -> keys_big sg ->
  ph_notlast sg cols ->
  z4_mid (lin_flat sg cols) B
    (lin_flat sg tail) =
  match z4_mid cols B tail with
  | Some body => Some (lin_flat sg body)
  | None => None
  end.
Proof.
  intros sg cols B tail HW HK HP.
  destruct cols as [|g1 [|g2 t]].
  { reflexivity. }
  { assert (Hg : ph sg g1 = false).
    { destruct (ph sg g1) eqn:E; [|reflexivity].
      pose proof (HP O g1 eq_refl E) as HL. cbn [length] in HL. lia. }
    rewrite (flat_cons_nonph sg g1 [] Hg).
    reflexivity. }
  destruct (list_split_last2 t g1 g2)
    as (ini & a & b & ECols).
  rewrite ECols in HP |- *.
  assert (Hb : ph sg b = false).
  { destruct (ph sg b) eqn:E; [|reflexivity].
    exfalso.
    assert (Hnb : nth_error (ini ++ [a; b]) (length ini + 1)%nat = Some b)
      by (rewrite nth_error_app2 by lia;
          replace (length ini + 1 - length ini)%nat with 1%nat by lia;
          reflexivity).
    pose proof (HP _ _ Hnb E) as HL.
    rewrite length_app in HL. cbn [length] in HL. lia. }
  destruct (ph sg a) eqn:EPa.
  2:{ assert (EFI : lin_flat sg (ini ++ [a; b])
                    = lin_flat sg ini ++ [a; b]).
      { rewrite lin_flat_app_c. f_equal.
        rewrite (flat_cons_nonph sg a _ EPa).
        rewrite (flat_cons_nonph sg b _ Hb).
        reflexivity. }
      rewrite EFI. unfold z4_mid. rewrite !LineageGuard_last2_app.
      destruct a as [[ga gaz] gac]. destruct b as [[gb gbz] gbc].
      destruct ((ga =? 8) && (gaz =? 2) && (gac =? 1)
        && (gb =? 4) && (gbz =? 2) && (1 <=? gbc))%N eqn:EC;
        [|reflexivity].
      apply andb_prop in EC as [EC _].
      apply andb_prop in EC as [EC Egbz].
      apply andb_prop in EC as [EC Egb].
      apply N.eqb_eq in Egb, Egbz. subst gb gbz.
      f_equal. rewrite !lin_flat_app_c.
      assert (EL : lin_flat sg
        [(7,1,1); (3,2,1); (4,2,gbc); (8,2,1)] =
        [(7,1,1); (3,2,1); (4,2,gbc); (8,2,1)]).
      { repeat rewrite flat_cons_notagbase by reflexivity.
        reflexivity. }
      rewrite EL. destruct (1 <? B)%N;
        [rewrite flat_cons_level|]; reflexivity. }
  unfold ph in EPa.
  destruct (keyi sg a) as [sa|] eqn:EKa; [|discriminate].
  destruct (keyi_in sg a sa EKa) as (Hin & Hlv & Hkey).
  destruct (sg_wf_seg sg sa HW Hin) as [HCa HOka].
  destruct (sflat_last_lvl sa HCa HOka)
    as (ini2 & a2 & ESF & Hlvl2).
  destruct a as [[ao az] ac].
  destruct (phshape_o _ Hlv) as [Hao Haz].
  cbn [gO gZ] in Hao, Haz. subst ao az.
  destruct a2 as [[o2 z2] c2].
  unfold is_lvl in Hlvl2. cbn [gO gZ] in Hlvl2.
  apply andb_prop in Hlvl2 as [Ho2 Hz2].
  apply N.eqb_eq in Ho2, Hz2. subst o2 z2.
  destruct b as [[bo bz] bc].
  assert (EFLAT :
    lin_flat sg (ini ++ [(9%N,2%N,ac); (bo,bz,bc)])
    = (lin_flat sg ini ++ ini2)
        ++ [(4%N,2%N,c2); (bo,bz,bc)]).
  { rewrite lin_flat_app_c.
    rewrite (flat_cons_key sg _ sa _ EKa).
    rewrite (flat_cons_nonph sg (bo,bz,bc) _ Hb).
    rewrite ESF. rewrite <- !app_assoc. reflexivity. }
  xrewrite EFLAT.
  unfold z4_mid. rewrite !LineageGuard_last2_app.
  cbv beta iota. reflexivity.
Qed.
Lemma z4_end_wrap : forall sg cols,
  sg_wf sg -> keys_big sg ->
  ph_notlast sg cols ->
  z4_end (lin_flat sg cols) =
  match z4_end cols with
  | Some body => Some (lin_flat sg body)
  | None => None
  end.
Proof.
  intros sg cols HW HK HP.
  destruct cols as [|g1 [|g2 t]].
  { reflexivity. }
  { assert (Hg : ph sg g1 = false).
    { destruct (ph sg g1) eqn:E; [|reflexivity].
      pose proof (HP O g1 eq_refl E) as HL. cbn [length] in HL. lia. }
    rewrite (flat_cons_nonph sg g1 [] Hg).
    reflexivity. }
  destruct (list_split_last2 t g1 g2)
    as (ini & a & b & ECols).
  rewrite ECols in HP |- *.
  assert (Hb : ph sg b = false).
  { destruct (ph sg b) eqn:E; [|reflexivity].
    exfalso.
    assert (Hnb : nth_error (ini ++ [a; b]) (length ini + 1)%nat = Some b)
      by (rewrite nth_error_app2 by lia;
          replace (length ini + 1 - length ini)%nat with 1%nat by lia;
          reflexivity).
    pose proof (HP _ _ Hnb E) as HL.
    rewrite length_app in HL. cbn [length] in HL. lia. }
  destruct (ph sg a) eqn:EPa.
  2:{ assert (EFI : lin_flat sg (ini ++ [a; b])
                    = lin_flat sg ini ++ [a; b]).
      { rewrite lin_flat_app_c. f_equal.
        rewrite (flat_cons_nonph sg a _ EPa).
        rewrite (flat_cons_nonph sg b _ Hb).
        reflexivity. }
      rewrite EFI. unfold z4_end. rewrite !LineageGuard_last2_app.
      destruct a as [[ga gaz] gac]. destruct b as [[gb gbz] gbc].
      destruct ((ga =? 8) && (gaz =? 2) && (gac =? 1)
        && (gb =? 4) && (gbz =? 2) && (1 <=? gbc))%N eqn:EC.
      - apply andb_prop in EC as [EC _].
        apply andb_prop in EC as [EC Egbz].
        apply andb_prop in EC as [EC Egb].
        apply N.eqb_eq in Egb, Egbz. subst gb gbz.
        f_equal. rewrite lin_flat_app_c. f_equal.
      - destruct ((gb =? 8) && (gbz =? 2) && (gbc =? 1))%N
          eqn:EB; [|reflexivity].
        f_equal. rewrite lin_flat_app_c. f_equal.
        rewrite (flat_cons_nonph sg (ga,gaz,gac) _ EPa).
        repeat rewrite flat_cons_notagbase by reflexivity.
        reflexivity. }
  unfold ph in EPa.
  destruct (keyi sg a) as [sa|] eqn:EKa; [|discriminate].
  destruct (keyi_in sg a sa EKa) as (Hin & Hlv & Hkey).
  destruct (sg_wf_seg sg sa HW Hin) as [HCa HOka].
  destruct (sflat_last_lvl sa HCa HOka)
    as (ini2 & a2 & ESF & Hlvl2).
  destruct a as [[ao az] ac].
  destruct (phshape_o _ Hlv) as [Hao Haz].
  cbn [gO gZ] in Hao, Haz. subst ao az.
  destruct a2 as [[o2 z2] c2].
  unfold is_lvl in Hlvl2. cbn [gO gZ] in Hlvl2.
  apply andb_prop in Hlvl2 as [Ho2 Hz2].
  apply N.eqb_eq in Ho2, Hz2. subst o2 z2.
  destruct b as [[bo bz] bc].
  assert (EFLAT :
    lin_flat sg (ini ++ [(9%N,2%N,ac); (bo,bz,bc)])
    = (lin_flat sg ini ++ ini2)
        ++ [(4%N,2%N,c2); (bo,bz,bc)]).
  { rewrite lin_flat_app_c.
    rewrite (flat_cons_key sg _ sa _ EKa).
    rewrite (flat_cons_nonph sg (bo,bz,bc) _ Hb).
    rewrite ESF. rewrite <- !app_assoc. reflexivity. }
  xrewrite EFLAT.
  unfold z4_end. rewrite !LineageGuard_last2_app.
  cbv beta iota. change ((9 =? 8)%N) with false. cbn [andb].
  destruct ((bo =? 8) && (bz =? 2) && (bc =? 1))%N eqn:EB;
    [|reflexivity].
  f_equal. rewrite !lin_flat_app_c.
  rewrite (flat_cons_key sg _ sa _ EKa).
  rewrite ESF.
  repeat rewrite flat_cons_notagbase by reflexivity.
  rewrite <- !app_assoc. reflexivity.
Qed.
Definition lift (k : ckind) (f : N) (r : option word)
  : option (ckind * word * N) :=
  match r with Some body => Some (k,body,f) | None => None end.
Lemma z4_end_comp : forall sg cols f,
  sg_wf sg -> keys_big sg ->
  ph_notlast sg cols ->
  lift JMP (f+4) (z4_end (lin_flat sg cols)) =
  flat_comp sg
    (lift JMP (f+4) (z4_end cols)).
Proof.
  intros sg cols f HW HK HP.
  rewrite (z4_end_wrap sg cols HW HK HP).
  destruct (z4_end cols); reflexivity.
Qed.
Lemma z4_mid_comp : forall sg cols B tail f,
  sg_wf sg -> keys_big sg ->
  ph_notlast sg cols ->
  lift JMP f
    (z4_mid (lin_flat sg cols) B
      (lin_flat sg tail)) =
  flat_comp sg
    (lift JMP f (z4_mid cols B tail)).
Proof.
  intros sg cols B tail f HW HK HP.
  rewrite (z4_mid_wrap sg cols B tail HW HK HP).
  destruct (z4_mid cols B tail); reflexivity.
Qed.
Definition z4_end_direct (cols : word) (f : N)
  : option (ckind * word * N) :=
  match last2 cols with
  | Some (ini, (ga,gaz,gac), (gb,gbz,gbc)) =>
      if (ga =? 8) && (gaz =? 2) && (gac =? 1)
         && (gb =? 4) && (gbz =? 2) && (1 <=? gbc)
      then Some (JMP,
        ini ++ [(7,1,1); (3,2,1); (gb,gbz,gbc)], f+4)
      else if (gb =? 8) && (gbz =? 2) && (gbc =? 1)
      then Some (JMP,
        ini ++ [(ga,gaz,gac); (7,1,1); (3,2,1)], f+4)
      else None
  | None => None
  end.
Definition z4_mid_direct (cols : word) (B : N)
    (tail : word) (f : N)
  : option (ckind * word * N) :=
  match last2 cols with
  | Some (ini, (ga,gaz,gac), (gb,gbz,gbc)) =>
      if (ga =? 8) && (gaz =? 2) && (gac =? 1)
         && (gb =? 4) && (gbz =? 2) && (1 <=? gbc)
      then Some (JMP,
        ini ++ [(7,1,1); (3,2,1); (gb,gbz,gbc); (8,2,1)]
          ++ (if 1 <? B then [(4,2,B-1)] else []) ++ tail, f)
      else None
  | None => None
  end.
Lemma z4_end_direct_lift : forall cols f,
  z4_end_direct cols f =
  lift JMP (f+4) (z4_end cols).
Proof.
  intros cols f. unfold z4_end_direct, lift, z4_end.
  destruct (last2 cols) as [[[ini a] b]|]; [|reflexivity].
  destruct a as [[ga gaz] gac]. destruct b as [[gb gbz] gbc].
  destruct ((ga =? 8) && (gaz =? 2) && (gac =? 1)
    && (gb =? 4) && (gbz =? 2) && (1 <=? gbc))%N;
    [reflexivity|].
  destruct ((gb =? 8) && (gbz =? 2) && (gbc =? 1))%N;
    reflexivity.
Qed.
Lemma z4_mid_direct_lift : forall cols B tail f,
  z4_mid_direct cols B tail f =
  lift JMP f (z4_mid cols B tail).
Proof.
  intros cols B tail f.
  unfold z4_mid_direct, lift, z4_mid.
  destruct (last2 cols) as [[[ini a] b]|]; [|reflexivity].
  destruct a as [[ga gaz] gac]. destruct b as [[gb gbz] gbc].
  destruct ((ga =? 8) && (gaz =? 2) && (gac =? 1)
    && (gb =? 4) && (gbz =? 2) && (1 <=? gbc))%N;
    reflexivity.
Qed.
Lemma z4_end_direct_comp : forall sg cols f,
  sg_wf sg -> keys_big sg ->
  ph_notlast sg cols ->
  z4_end_direct (lin_flat sg cols) f =
  flat_comp sg (z4_end_direct cols f).
Proof.
  intros sg cols f HW HK HP.
  rewrite !z4_end_direct_lift.
  apply z4_end_comp; assumption.
Qed.
Lemma z4_mid_direct_comp : forall sg cols B tail f,
  sg_wf sg -> keys_big sg ->
  ph_notlast sg cols ->
  z4_mid_direct (lin_flat sg cols) B
    (lin_flat sg tail) f =
  flat_comp sg (z4_mid_direct cols B tail f).
Proof.
  intros sg cols B tail f HW HK HP.
  rewrite !z4_mid_direct_lift.
  apply z4_mid_comp; assumption.
Qed.
Lemma z4_std_flat : forall sg o B tail,
  lin_flat sg
    ((o-1,1,1) :: (7,2,1)
       :: (if 1 <? B then [(4,2,B-1)] else []) ++ tail) =
  (o-1,1,1) :: (7,2,1)
       :: (if 1 <? B then [(4,2,B-1)] else [])
       ++ lin_flat sg tail.
Proof.
  intros sg o B tail.
  rewrite flat_cons_notagbase.
  2:{ unfold tagbase. cbn [gO gZ].
      rewrite andb_false_r. reflexivity. }
  rewrite flat_cons_notagbase by reflexivity.
  destruct (1 <? B)%N; reflexivity.
Qed.
Lemma second_nonph : forall sg g h t,
  nbrs1z sg (g :: h :: t) ->
  is_spc g = false -> ph sg h = false.
Proof.
  intros sg g h t HN Hsp.
  exact (nbrs_excl1z sg (g :: h :: t) O h g
    HN eq_refl eq_refl Hsp).
Qed.
Lemma std_flat_res : forall sg r,
  (match flat_res sg r with
   | Some (body,f2) => Some (STD,body,f2)
   | None => None
   end) =
  flat_comp sg
    (match r with
     | Some (body,f2) => Some (STD,body,f2)
     | None => None
     end).
Proof. intros sg [[body f2]|]; reflexivity. Qed.
Lemma site_comp_flat_dispatch : forall sg w i f,
  sg_wf sg -> keys_big sg ->
  sg_live sg ->
  Nat.leb 3 i =
    Nat.leb 3 (length (lin_flat sg (firstn i w))) ->
  ph_notlast sg (firstn i w) ->
  nbrs1z sg (skipn i w) ->
  (forall g t, skipn i w = g :: t -> ph sg g = false) ->
  site_comp (lin_flat sg w)
    (length (lin_flat sg (firstn i w))) f =
  flat_comp sg (site_comp w i f).
Proof.
  intros sg w i f HW HK HL HD HP HN HH.
  unfold site_comp.
  rewrite <- (flat_skipn sg w i).
  rewrite <- (flat_firstn sg w i).
  remember (firstn i w) as p eqn:EP in HD, HP |- *.
  remember (skipn i w) as s eqn:ES in HN, HH |- *.
  destruct s as [|[[o z] c] t].
  { reflexivity. }
  assert (Hiw : (i < length w)%nat).
  { apply PeanoNat.Nat.lt_nge. intros Hle.
    assert (Hnil : skipn i w = []) by (apply skipn_all2; lia).
    rewrite Hnil in ES. discriminate. }
  assert (Hplen : length p = i).
  { rewrite EP. apply firstn_length_le. lia. }
  rewrite <- HD.
  assert (Hph : ph sg (o,z,c) = false).
  { apply (HH (o,z,c) t). reflexivity. }
  assert (EF0 : lin_flat sg ((o,z,c) :: t)
                = (o,z,c) :: lin_flat sg t)
    by (apply flat_cons_nonph; exact Hph).
  xrewrite EF0.
  destruct (Nat.leb 3 i) eqn:EI.
  { cbn [andb].
    destruct ((o =? 4) && (z =? 3) && (c =? 1))%N eqn:E43;
      cbn [andb].
  - apply andb_prop in E43 as [E43 Ec].
    apply andb_prop in E43 as [Eo Ez].
    apply N.eqb_eq in Eo, Ez, Ec. subst o z c.
    destruct t as [|[[o5 z5] b5] rest2].
    + rewrite (endR_wrap sg p f HW HK HP).
      destruct (endR_seg p f); reflexivity.
    + assert (Hph5 : ph sg (o5,z5,b5) = false).
      { apply (second_nonph sg (4,3,1) (o5,z5,b5) rest2 HN).
        reflexivity. }
      assert (EF5 : lin_flat sg ((o5,z5,b5) :: rest2)
                    = (o5,z5,b5) :: lin_flat sg rest2)
        by (apply flat_cons_nonph; exact Hph5).
      xrewrite EF5.
      pose proof (nbrs1z_tail sg (4,3,1)
        ((o5,z5,b5)::rest2) HN) as HN5.
      pose proof (nbrs1z_tail sg (o5,z5,b5)
        rest2 HN5) as HNr.
      rewrite (flat_nilb sg rest2 HW).
      destruct ((o5 =? 4) && (z5 =? 2))%N eqn:E52.
      * destruct (1 <=? b5)%N eqn:EB; [|reflexivity].
        rewrite (jump_comp_flat_z
          sg p b5 rest2 f HW HK HL HP HNr).
        destruct (jump_comp p b5 rest2 f); reflexivity.
      * destruct ((z5 =? 3) && (b5 =? 1)
          && match rest2 with [] => true | _ => false end
          && (f =? 4) && (1 <=? o5))%N eqn:EY.
        -- rewrite (endY_wrap sg p o5 HW HK HP).
           destruct (endY_seg p o5); reflexivity.
        -- pose proof (fire_flat_len sg
             ((4,3,1)::(o5,z5,b5)::rest2) f HW HK HL HN
             ltac:(intros g0 t0 E; injection E as <- <-; exact Hph)) as EF.
           xrewrite_in EF EF0.
           xrewrite_in EF EF5.
           xrewrite EF.
           apply std_flat_res.
  - destruct ((z =? 3) && (c =? 1))%N eqn:E3.
    + pose proof (fire_flat_len sg ((o,z,c)::t) f
        HW HK HL HN
        ltac:(intros g0 t0 E; injection E as <- <-; exact Hph)) as EF.
      xrewrite_in EF EF0. xrewrite EF.
      apply std_flat_res.
    + destruct (z =? 1)%N eqn:E1.
      * pose proof (leaf_act_flat_z sg ((o,z,c)::t) f
          HW HK HN
          ltac:(intros g0 t0 E; injection E as <- <-; exact Hph)) as ELF.
        xrewrite_in ELF EF0. xrewrite ELF.
        apply std_flat_res.
      * destruct ((z =? 4) && (c =? 1))%N eqn:E4; [|reflexivity].
        apply andb_prop in E4 as [Ez Ec].
        apply N.eqb_eq in Ez, Ec. subst z c.
        destruct t as [|[[on zn] cn] t2].
        -- destruct ((o =? 4) && (1 <=? f))%N eqn:EOF; [|reflexivity].
           rewrite flat_wnil.
           change (z4_end_direct (lin_flat sg p) f =
             flat_comp sg (z4_end_direct p f)).
           apply z4_end_direct_comp; assumption.
        -- assert (Hphn : ph sg (on,zn,cn) = false).
           { apply (second_nonph sg (o,4,1) (on,zn,cn) t2 HN).
             unfold is_spc. cbn [gO gZ gC].
             rewrite andb_false_r. reflexivity. }
           assert (EFn : lin_flat sg ((on,zn,cn) :: t2)
                         = (on,zn,cn) :: lin_flat sg t2)
             by (apply flat_cons_nonph; exact Hphn).
           xrewrite EFn.
           destruct ((o =? 4) && (on =? 4) && (zn =? 2)
             && (1 <=? cn))%N eqn:EA.
           ++ change (z4_mid_direct (lin_flat sg p) cn
                (lin_flat sg t2) f =
                flat_comp sg
                  (z4_mid_direct p cn t2 f)).
              apply z4_mid_direct_comp; assumption.
           ++ destruct ((4 <? o) && (on =? 4) && (zn =? 2)
                && (1 <=? cn))%N eqn:ESD; [|reflexivity].
              unfold flat_comp.
              rewrite z4_std_flat. reflexivity. }
  cbn [andb]. repeat rewrite andb_false_r.
  destruct ((z =? 3) && (c =? 1))%N eqn:E3.
  - pose proof (fire_flat_len sg ((o,z,c)::t) f
      HW HK HL HN
      ltac:(intros g0 t0 E; injection E as <- <-; exact Hph)) as EF.
    xrewrite_in EF EF0. xrewrite EF.
    apply std_flat_res.
  - destruct (z =? 1)%N eqn:E1.
    + pose proof (leaf_act_flat_z sg ((o,z,c)::t) f
        HW HK HN
        ltac:(intros g0 t0 E; injection E as <- <-; exact Hph)) as ELF.
      xrewrite_in ELF EF0. xrewrite ELF.
      apply std_flat_res.
    + destruct ((z =? 4) && (c =? 1))%N eqn:E4; [|reflexivity].
      apply andb_prop in E4 as [Ez Ec].
      apply N.eqb_eq in Ez, Ec. subst z c.
      destruct t as [|[[on zn] cn] t2].
      * destruct ((o =? 4) && (1 <=? f))%N eqn:EOF; [|reflexivity].
        rewrite flat_wnil.
        change (z4_end_direct (lin_flat sg p) f =
          flat_comp sg (z4_end_direct p f)).
        apply z4_end_direct_comp; assumption.
      * assert (Hphn : ph sg (on,zn,cn) = false).
        { apply (second_nonph sg (o,4,1) (on,zn,cn) t2 HN).
          unfold is_spc. cbn [gO gZ gC].
          rewrite andb_false_r. reflexivity. }
        assert (EFn : lin_flat sg ((on,zn,cn) :: t2)
                      = (on,zn,cn) :: lin_flat sg t2)
          by (apply flat_cons_nonph; exact Hphn).
        xrewrite EFn.
        destruct ((o =? 4) && (on =? 4) && (zn =? 2)
          && (1 <=? cn))%N eqn:EA.
        -- change (z4_mid_direct (lin_flat sg p) cn
             (lin_flat sg t2) f =
             flat_comp sg (z4_mid_direct p cn t2 f)).
           apply z4_mid_direct_comp; assumption.
        -- destruct ((4 <? o) && (on =? 4) && (zn =? 2)
             && (1 <=? cn))%N eqn:ESD; [|reflexivity].
           unfold flat_comp.
           rewrite z4_std_flat. reflexivity.
Qed.
Lemma site_comp_some_lt : forall w i f k body f2,
  site_comp w i f = Some (k,body,f2) ->
  (i < length w)%nat.
Proof.
  intros w i f k body f2 H.
  unfold site_comp in H.
  destruct (skipn i w) as [|g t] eqn:ES; [discriminate|].
  apply PeanoNat.Nat.lt_nge. intros Hle.
  assert (skipn i w = []) by (apply skipn_all2; lia).
  rewrite H0 in ES. discriminate.
Qed.
Lemma flat_master : forall sg J t,
  lin_flat sg ((2,2,J) :: t) =
  (2,2,J) :: lin_flat sg t.
Proof.
  intros. apply flat_cons_notagbase. reflexivity.
Qed.
Lemma flat_firstn_master_len : forall sg J K t n,
  (1 <= n)%nat ->
  length (lin_flat sg (firstn n ((2,2,J) :: t))) =
  length (lin_flat sg (firstn n ((2,2,K) :: t))).
Proof.
  intros sg J K t [|n] HN; [lia|].
  cbn [firstn]. rewrite !flat_master. reflexivity.
Qed.
Lemma sound_impl_sdecode : forall a fa b fb a' fa' b' fb',
  sdecode a fa = sdecode a' fa' ->
  sdecode b fb = sdecode b' fb' ->
  sound_impl a fa b fb ->
  sound_impl a' fa' b' fb'.
Proof.
  intros a fa b fb a' fa' b' fb' EA EB HS Hh.
  unfold sound_impl in HS |- *.
  rewrite <- EA. apply HS. rewrite EB. exact Hh.
Qed.
Lemma site_comp_head : forall sg w i f k body f2,
  site_comp w i f = Some (k,body,f2) ->
  exists g u, skipn i w = g :: u /\
    ph sg g = false /\ casc g = false /\
    notag g = true.
Proof.
  intros sg w i f k body f2 H.
  unfold site_comp in H.
  destruct (skipn i w) as [|[[o z] c] u] eqn:ES; [discriminate|].
  destruct ((o =? 4) && (z =? 3) && (c =? 1) && Nat.leb 3 i)%N
    eqn:E43.
  - apply andb_prop in E43 as [E43 _].
    apply andb_prop in E43 as [E43 Ec].
    apply andb_prop in E43 as [_ Ez].
    apply N.eqb_eq in Ez, Ec. subst z c.
    exists (o,3,1), u. split; [reflexivity|]. split; [|split].
    + unfold ph, keyi.
      rewrite (phshape_znot2 o 3 1 ltac:(reflexivity)).
      reflexivity.
    + apply z31_noncasc.
    + apply notag_lit.
      change ((o =? 9) && false && false = false)%bool.
      rewrite !andb_false_r. reflexivity.
  - destruct ((z =? 3) && (c =? 1))%N eqn:E3.
    + apply andb_prop in E3 as [Ez Ec].
      apply N.eqb_eq in Ez, Ec. subst z c.
      exists (o,3,1), u. split; [reflexivity|]. split; [|split].
      * unfold ph, keyi.
        rewrite (phshape_znot2 o 3 1 ltac:(reflexivity)).
        reflexivity.
      * apply z31_noncasc.
      * apply notag_lit.
        change ((o =? 9) && false && false = false)%bool.
        rewrite !andb_false_r. reflexivity.
    + destruct (z =? 1)%N eqn:E1.
      * apply N.eqb_eq in E1. subst z.
        exists (o,1,c), u. split; [reflexivity|]. split; [|split].
        -- unfold ph, keyi.
           rewrite (phshape_znot2 o 1 c ltac:(reflexivity)).
           reflexivity.
        -- unfold casc, is_lvl, is_spc.
           cbn [gO gZ gC].
           change ((1 =? 2)%N) with false.
           rewrite !andb_false_r. reflexivity.
        -- apply notag_lit.
           cbn [gO gZ gC].
           change ((1 =? 2)%N) with false.
           rewrite !andb_false_r. reflexivity.
      * destruct ((z =? 4) && (c =? 1))%N eqn:E4.
        -- apply andb_prop in E4 as [Ez Ec].
           apply N.eqb_eq in Ez, Ec. subst z c.
           exists (o,4,1), u. split; [reflexivity|]. split; [|split].
           ++ unfold ph, keyi.
              rewrite (phshape_znot2 o 4 1 ltac:(reflexivity)).
              reflexivity.
           ++ unfold casc, is_lvl, is_spc.
              cbn [gO gZ gC].
              change ((4 =? 2)%N) with false.
              rewrite !andb_false_r. reflexivity.
           ++ apply notag_lit.
              cbn [gO gZ gC].
              change ((4 =? 2)%N) with false.
              rewrite !andb_false_r. reflexivity.
        -- discriminate.
Qed.
Lemma margins_ph_notlast : forall sg w i g u,
  ph_margins sg w ->
  skipn i w = g :: u -> casc g = false ->
  ph_notlast sg (firstn i w).
Proof.
  intros sg w i g u HM ES HC p gp Hp Hph.
  assert (Hiw : (i < length w)%nat).
  { apply PeanoNat.Nat.lt_nge. intros Hle.
    assert (skipn i w = []) by (apply skipn_all2; lia).
    rewrite H in ES. discriminate. }
  assert (Hlen : length (firstn i w) = i).
  { apply firstn_length_le. lia. }
  assert (HpLen : (p < length (firstn i w))%nat).
  { apply (proj1 (nth_error_Some (firstn i w) p)).
    rewrite Hp. discriminate. }
  assert (HpL : (p < i)%nat) by lia.
  destruct (PeanoNat.Nat.lt_ge_cases (p + 1) i) as [Hlt|Hge].
  - rewrite Hlen. exact Hlt.
  - assert (Hpi : (p + 1 = i)%nat) by lia.
    assert (Hpw : nth_error w p = Some gp).
    { rewrite <- (firstn_skipn i w).
      rewrite nth_error_app1; [exact Hp|]. rewrite Hlen. lia. }
    destruct (HM p gp Hpw Hph) as (_ & _ & HW).
    destruct (HW i ltac:(unfold GUARD; lia)
              ltac:(unfold GUARD; lia) ltac:(lia))
      as (gi & Hgi & Hci & _).
    assert (Hsite : nth_error w i = Some g).
    { replace i with (i + O)%nat by lia.
      rewrite <- (nth_skipn i O w), ES. reflexivity. }
    rewrite Hsite in Hgi. injection Hgi as <-. congruence.
Qed.
Lemma margins_firstn_phfree : forall sg w n,
  ph_margins sg w ->
  (n <= GUARD)%nat ->
  forall g, In g (firstn n w) -> ph sg g = false.
Proof.
  intros sg w n HM Hn g Hin.
  apply In_nth_error in Hin. destruct Hin as (p & Hp).
  assert (HpLen : (p < length (firstn n w))%nat).
  { apply (proj1 (nth_error_Some (firstn n w) p)).
    rewrite Hp. discriminate. }
  assert (Hpn : (p < n)%nat).
  { pose proof (firstn_le_length n w). lia. }
  assert (Hpw : nth_error w p = Some g).
  { rewrite <- (nth_firstn n p w Hpn). exact Hp. }
  destruct (ph sg g) eqn:Hph; [|reflexivity].
  destruct (HM p g Hpw Hph) as (Hguard & _).
  lia.
Qed.
Lemma splice_none_direct_inv : forall sg J t f h s i cw2 f2 ir,
  s = (if Nat.ltb h 1 then 1%nat else h) ->
  find_active ((2,2,J) :: t) s = Some i ->
  splice_call sg None ((2,2,J) :: t) f h
    = (ROk cw2 f2, ir) ->
  exists k body,
    (1 <= J)%N /\ (1 <= s)%nat /\
    forallb is_col (firstn i ((2,2,J) :: t)) = true /\
    (match last1 (firstn i ((2,2,J) :: t)) with
     | Some g => ((3 <=? gO g) && (1 <=? gC g))%N
     | None => false
     end) = true /\
    site_comp ((2,2,J+1) :: t) i f = Some (k,body,f2) /\
    ir = i /\
    cw2 = match k with
          | JMP => lin_normalize_at sg body i
          | STD => lin_normalize_join sg
                          (firstn i ((2,2,J+1) :: t)) body
          end.
Proof.
  intros sg J t f h s i cw2 f2 ir ES HFA H.
  subst s.
  unfold splice_call, step_after_front_with_guard in H.
  cbv beta zeta iota in H.
  rewrite HFA in H.
  cbv beta zeta iota in H.
  cbn [gO gZ gC] in H.
  lazymatch type of H with
  | (if ?b then _ else _) = _ =>
      destruct b eqn:HBadCols in H
  end; [discriminate|].
  apply Bool.negb_false_iff in HBadCols.
  cbn [orb] in HBadCols.
  rename HBadCols into HCols.
  lazymatch type of H with
  | (if ?b then _ else _) = _ =>
      destruct b eqn:HBadMaster in H
  end; [discriminate|].
  apply Bool.negb_false_iff in HBadMaster.
  cbn [orb] in HBadMaster.
  lazymatch type of H with
  | (if ?b then _ else _) = _ =>
      destruct b eqn:HBadLast in H
  end; [discriminate|].
  apply Bool.negb_false_iff in HBadLast.
  cbn [orb] in HBadLast.
  rename HBadLast into HLast.
  fold (site_comp ((2,2,J+1) :: t) i f) in H.
  destruct (site_comp ((2,2,J+1) :: t) i f)
    as [[[k body] f2']|] eqn:HComp in H.
  2:{ lazymatch type of H with
      | (match ?x with Some _ => _ | None => _ end) = _ =>
          destruct x as [g3|] eqn:EW in H
      end; [|discriminate].
      lazymatch type of H with
      | (if ?b then _ else _) = _ => destruct b eqn:EZ in H
      end; [discriminate|].
      lazymatch type of H with
      | (if ?b then _ else _) = _ => destruct b eqn:EE in H
      end; [discriminate|].
      lazymatch type of H with
      | context [match ?r with
                 | ROk _ _ => _ | RHalt => _ | RBad => _
                 end] => destruct r eqn:ED in H
      end; discriminate. }
  destruct k.
  all: cbv beta zeta iota in H; try discriminate.
  all: inversion H; subst cw2 f2 ir.
  all: cbn [N.eqb andb] in HBadMaster;
       apply andb_prop in HBadMaster as [HJ _]; apply N.leb_le in HJ.
  all: assert (HS : (1 <= if Nat.ltb h 1 then 1 else h)%nat)
         by (destruct (Nat.ltb h 1) eqn:E; [lia|];
             apply PeanoNat.Nat.ltb_ge in E; lia).
  all: assert (HC : forallb is_col
         (firstn i ((2,2,J) :: t)) = true) by exact HCols.
  all: assert (HL :
         (match last1 (firstn i ((2,2,J) :: t)) with
          | Some g => ((3 <=? gO g) && (1 <=? gC g))%N
          | None => false
          end) = true) by exact HLast.
  - exists STD, body. repeat split; try assumption.
  - exists JMP, body. repeat split; try assumption.
Qed.
Open Scope N_scope.
Open Scope bool_scope.
Opaque LROUND_FUEL LROUND_CHUNKS
       FLAT_ROUND_FUEL CFUEL TRIES.
Definition side8 (g : bg) : Prop :=
  gO g = 8%N /\ gZ g = 2%N.
Definition right_edge (g : bg) : Prop :=
  side8 g \/ gZ g = 1%N.
Definition edge_pair (a b : bg) : Prop :=
  (phshape a = true -> right_edge b) /\
  (phshape b = true -> side8 a).
Fixpoint tag_edges (w : word) : Prop :=
  match w with
  | a :: ((b :: _) as t) => edge_pair a b /\ tag_edges t
  | _ => True
  end.
Lemma spc_side8 : forall g,
  is_spc g = true -> side8 g.
Proof.
  intros [[o z] c] H. unfold is_spc in H. unfold side8.
  cbn [gO gZ gC] in *.
  apply andb_prop in H as [H _]. apply andb_prop in H as [Ho Hz].
  apply N.eqb_eq in Ho, Hz. auto.
Qed.
Lemma casc_side8_spc : forall g,
  casc g = true -> side8 g -> is_spc g = true.
Proof.
  intros [[o z] c] HC [Ho Hz]. cbn [gO gZ] in Ho, Hz.
  subst o z. unfold casc in HC. apply orb_prop in HC as [HL|HS].
  - unfold is_lvl in HL. cbn [gO gZ] in HL.
    discriminate.
  - exact HS.
Qed.
Lemma lin_ptags_head_ph : forall sg g t,
  lin_ptags sg (g :: t) = true ->
  phshape g = true -> ph sg g = true.
Proof.
  intros sg g t H HP. cbn [lin_ptags] in H.
  apply andb_prop in H as [Hg _]. rewrite HP in Hg.
  cbn [negb orb] in Hg. exact Hg.
Qed.
Lemma tag_edges_tail : forall g t,
  tag_edges (g :: t) -> tag_edges t.
Proof.
  intros g [|a t] H; [exact I|exact (proj2 H)].
Qed.
Lemma tag_edges_of_nbrs1z : forall sg w,
  nbrs1z sg w ->
  lin_ptags sg w = true -> tag_edges w.
Proof.
  intros sg w. induction w as [|g1 [|g2 t] IH]; intros HN HPT;
    try exact I.
  cbn [tag_edges]. split.
  - split.
    + intros HP1.
      assert (Hph1 : ph sg g1 = true)
        by (exact (lin_ptags_head_ph sg g1 (g2::t) HPT HP1)).
      destruct (HN O g1 eq_refl Hph1) as ((gr & Hgr & Hright) & _).
      cbn [nth_error Nat.add] in Hgr.
      assert (gr = g2) by congruence. subst gr.
      destruct Hright as [Hsp|Hz].
      * left. exact (spc_side8 g2 Hsp).
      * right. exact Hz.
    + intros HP2.
      assert (HPTt : lin_ptags sg (g2::t) = true).
      { cbn [lin_ptags] in HPT.
        exact (proj2 (andb_prop _ _ HPT)). }
      assert (Hph2 : ph sg g2 = true)
        by (exact (lin_ptags_head_ph sg g2 t HPTt HP2)).
      destruct (HN 1%nat g2 eq_refl Hph2) as (_ & HL).
      exact (spc_side8 g1 (HL g1 ltac:(lia) eq_refl)).
  - apply IH.
    + exact (nbrs1z_tail sg g1 (g2::t) HN).
    + cbn [lin_ptags] in HPT.
      exact (proj2 (andb_prop _ _ HPT)).
Qed.
Lemma tag_edges_right : forall w p g,
  tag_edges w -> nth_error w p = Some g ->
  (p + 1 < length w)%nat -> phshape g = true ->
  exists gr, nth_error w (p + 1) = Some gr /\ right_edge gr.
Proof.
  induction w as [|a t IH]; intros p g HE Hp Hlen HP.
  - cbn [length] in Hlen. lia.
  - destruct p as [|p].
  + cbn [nth_error] in Hp. injection Hp as <-.
    destruct t as [|b t]; [cbn [length] in Hlen; lia|].
    exists b. split; [reflexivity|]. exact (proj1 (proj1 HE) HP).
  + cbn [nth_error] in Hp. destruct t as [|b t];
      [destruct p; discriminate|].
    cbn [length] in Hlen.
    assert (Hlen' : (p + 1 < length (b::t))%nat)
      by (cbn [length]; lia).
    destruct (IH p g (proj2 HE) Hp Hlen' HP) as (gr & Hgr & HR).
    exists gr. split; [exact Hgr|exact HR].
Qed.
Lemma tag_edges_left : forall w p g gl,
  tag_edges w -> nth_error w p = Some g -> (1 <= p)%nat ->
  nth_error w (p - 1) = Some gl -> phshape g = true ->
  side8 gl.
Proof.
  induction w as [|a t IH]; intros p g gl HE Hp Hp1 Hgl HP.
  - destruct p; discriminate.
  - destruct p as [|p]; [lia|]. destruct t as [|b t];
      [destruct p; discriminate|].
    destruct p as [|p].
  + cbn [nth_error] in Hp, Hgl. injection Hp as <-. injection Hgl as <-.
    exact (proj2 (proj1 HE) HP).
  + cbn [nth_error] in Hp.
    replace (S (S p) - 1)%nat with (S p) in Hgl by lia.
    cbn [nth_error] in Hgl.
    assert (Hgl' : nth_error (b::t) (S p - 1) = Some gl).
    { replace (S p - 1)%nat with p by lia. exact Hgl. }
    exact (IH (S p) g gl (proj2 HE) Hp ltac:(lia) Hgl' HP).
Qed.
Lemma margins_edges_nbrs : forall sg w,
  ph_margins sg w -> tag_edges w ->
  ph_nbrs sg w.
Proof.
  intros sg w HM HE p g Hp Hph.
  pose proof (ph_shape sg g Hph) as HP.
  destruct (HM p g Hp Hph) as (Hlo & Hhi & Hwin).
  destruct (tag_edges_right w p g HE Hp ltac:(unfold GUARD in Hhi; lia)
              HP) as (gr & Hgr & HR).
  split.
  - exists gr. split; [exact Hgr|].
    destruct (Hwin (p+1)%nat ltac:(unfold GUARD; lia)
      ltac:(unfold GUARD; lia) ltac:(lia))
      as (gr' & Hgr' & HC & _).
    rewrite Hgr in Hgr'. injection Hgr' as <-.
    destruct HR as [HS|Hz].
    + exact (casc_side8_spc gr HC HS).
    + destruct gr as [[o z] c]. cbn [gZ] in Hz. subst z.
      rewrite casc_z1_false in HC. discriminate.
  - intros gl Hp1 Hgl.
    pose proof (tag_edges_left w p g gl HE Hp Hp1 Hgl HP) as HS.
    assert (HL : (p - GUARD <= p - 1)%nat).
    { unfold GUARD in Hlo |- *. lia. }
    assert (HU : (p - 1 <= p + GUARD)%nat)
      by (unfold GUARD; lia).
    assert (Hne : (p - 1)%nat <> p) by lia.
    destruct (Hwin (p-1)%nat HL HU Hne)
      as (gl' & Hgl' & HC & _).
    rewrite Hgl in Hgl'. injection Hgl' as <-.
    exact (casc_side8_spc gl HC HS).
Qed.
Lemma tag_edges_merge_ctx : forall pre o z c1 c2 post,
  tagbase (o,z,c1) = false ->
  tagbase (o,z,c2) = false ->
  tag_edges (pre ++ (o,z,c1) :: (o,z,c2) :: post) ->
  tag_edges (pre ++ (o,z,c1+c2) :: post).
Proof.
  induction pre as [|a pre IH]; intros o z c1 c2 post HB1 HB2 HE.
  - cbn [app] in HE |- *.
    assert (HBm : tagbase (o,z,c1+c2) = false).
    { rewrite (tagbase_c o z (c1+c2) c1). exact HB1. }
    assert (HPm : phshape (o,z,c1+c2) = false)
      by (exact (phshape_false_of_tagbase_false _ HBm)).
    destruct post as [|b post]; [exact I|].
    destruct HE as (_ & HE2). destruct HE2 as (H2b & Htail).
    split; [|exact Htail]. split.
    + intros H. rewrite HPm in H. discriminate.
    + intros HPb.
      unfold side8 in *. cbn [gO gZ] in *. exact (proj2 H2b HPb).
  - destruct pre as [|b pre].
    + cbn [app] in HE |- *.
      destruct HE as (Ha1 & Hrest).
      split.
      * split.
        -- intros HPa. destruct (proj1 Ha1 HPa) as [HS|Hz].
           ++ left. unfold side8 in *. cbn [gO gZ] in *. exact HS.
           ++ right. cbn [gZ] in *. exact Hz.
        -- intros HPm.
           assert (HBm : tagbase (o,z,c1+c2) = false)
             by (rewrite (tagbase_c o z (c1+c2) c1); exact HB1).
           rewrite (phshape_false_of_tagbase_false _ HBm) in HPm.
           discriminate.
      * exact (IH o z c1 c2 post HB1 HB2 Hrest).
    + cbn [app] in HE |- *.
      split; [exact (proj1 HE)|].
      exact (IH o z c1 c2 post HB1 HB2 (proj2 HE)).
Qed.
Lemma tag_edges_normalize_ctx : forall pre w post,
  tag_edges (pre ++ w ++ post) ->
  tag_edges (pre ++ lin_normalize_full w ++ post).
Proof.
  intros pre w. revert pre.
  induction w as [|[[o z] c] t IH]; intros pre post HE.
  - exact HE.
  - assert (HE1 : tag_edges ((pre ++ [(o,z,c)]) ++ t ++ post)).
    { rewrite <- !app_assoc. exact HE. }
    pose proof (IH (pre ++ [(o,z,c)]) post HE1) as HN.
    cbn [lin_normalize_full].
    destruct (lin_normalize_full t) as [|[[o2 z2] c2] r] eqn:EN.
    + rewrite <- app_assoc in HN. cbn [app] in HN |- *. exact HN.
    + rewrite <- app_assoc in HN. cbn [app] in HN |- *.
      destruct (tagbase (o,z,c) ||
                tagbase (o2,z2,c2)) eqn:ET; [exact HN|].
      apply orb_false_iff in ET as [HB1 HB2].
      destruct ((o =? o2) && (z =? z2))%N eqn:EOZ; [|exact HN].
      apply andb_prop in EOZ as [EO EZ].
      apply N.eqb_eq in EO, EZ. subst o2 z2.
      exact (tag_edges_merge_ctx pre o z c c2 (r ++ post)
               HB1 HB2 HN).
Qed.
Corollary tag_edges_normalize_full : forall w,
  tag_edges w -> tag_edges (lin_normalize_full w).
Proof.
  intros w H.
  assert (Hin : tag_edges ([] ++ w ++ []))
    by (cbn [app]; rewrite app_nil_r; exact H).
  pose proof (tag_edges_normalize_ctx [] w [] Hin) as H0.
  cbn [app] in H0. rewrite app_nil_r in H0. exact H0.
Qed.
Lemma tag_edges_normalize_at : forall sg w center,
  tag_edges w -> tag_edges (lin_normalize_at sg w center).
Proof.
  intros sg w center HE. unfold lin_normalize_at.
  destruct (Nat.eqb center O); [exact HE|].
  cbv beta zeta.
  destruct (lin_nadj_span 6 sg (skipn (center-2) w)); [exact HE|].
  rewrite !LineageSplice_lin_split_at_spec. cbn [fst snd].
  assert (EW : w = firstn (center-2) w
      ++ firstn 6 (skipn (center-2) w)
      ++ skipn 6 (skipn (center-2) w)).
  { rewrite firstn_skipn, firstn_skipn. reflexivity. }
  apply tag_edges_normalize_ctx. rewrite <- EW. exact HE.
Qed.
Definition head_equiv (a b : bg) : Prop :=
  gO a = gO b /\ gZ a = gZ b /\
  phshape a = phshape b.
Lemma normalize_full_head_equiv : forall g t h r,
  lin_normalize_full (g::t) = h::r -> head_equiv g h.
Proof.
  intros [[o z] c] t [[oh zh] ch] r H.
  cbn [lin_normalize_full] in H.
  destruct (lin_normalize_full t) as [|[[o2 z2] c2] r2] eqn:E.
  - injection H as <- <- <- <-. repeat split; reflexivity.
  - destruct (tagbase (o,z,c) ||
              tagbase (o2,z2,c2)) eqn:ET.
    + injection H as <- <- <- <-. repeat split; reflexivity.
    + apply orb_false_iff in ET as [HB1 HB2].
      destruct ((o =? o2) && (z =? z2))%N eqn:EOZ.
      * apply andb_prop in EOZ as [EO EZ].
        apply N.eqb_eq in EO, EZ. subst o2 z2.
        injection H as <- <- <- <-. split; [reflexivity|]. split;
          [reflexivity|].
        rewrite (phshape_false_of_tagbase_false _ HB1).
        symmetry. apply phshape_false_of_tagbase_false.
        rewrite (tagbase_c o z (c+c2) c). exact HB1.
      * injection H as <- <- <- <-. repeat split; reflexivity.
Qed.
Lemma normalize_join_head : forall sg g pre sfx,
  exists h r, lin_normalize_join sg (g::pre) sfx = h::r /\
              head_equiv g h.
Proof.
  intros sg g pre sfx. destruct pre as [|g1 [|g2 tail]].
  - cbn [lin_normalize_join app].
    rewrite LineageSplice_lin_split_at_spec. cbn [fst snd].
    destruct (lin_normalize_slice sg (g::firstn 5 sfx))
      as [|h r] eqn:E.
    + unfold lin_normalize_slice in E.
      destruct (lin_normalize_full_hd g (firstn 5 sfx))
        as (c & r & EH). rewrite EH in E. discriminate.
    + exists h, (r ++ skipn 5 sfx). split.
      * change (lin_normalize_slice sg (g::firstn 5 sfx)
                  ++ skipn 5 sfx = h :: (r ++ skipn 5 sfx)).
        rewrite E. reflexivity.
      * apply (normalize_full_head_equiv g (firstn 5 sfx) h r).
        exact E.
  - cbn [lin_normalize_join app].
    rewrite LineageSplice_lin_split_at_spec. cbn [fst snd].
    destruct (lin_normalize_slice sg (g::g1::firstn 4 sfx))
      as [|h r] eqn:E.
    + unfold lin_normalize_slice in E.
      destruct (lin_normalize_full_hd g
        (g1::firstn 4 sfx)) as (c & r & EH).
      rewrite EH in E. discriminate.
    + exists h, (r ++ skipn 4 sfx). split.
      * change (lin_normalize_slice sg
                  (g::g1::firstn 4 sfx) ++ skipn 4 sfx
                = h :: (r ++ skipn 4 sfx)).
        rewrite E. reflexivity.
      * apply (normalize_full_head_equiv g (g1::firstn 4 sfx) h r).
        exact E.
  - cbn [lin_normalize_join app].
    exists g, (lin_normalize_join sg (g1::g2::tail) sfx).
    split; [reflexivity|]. unfold head_equiv. repeat split; reflexivity.
Qed.
Lemma edge_pair_head_equiv : forall a b b',
  edge_pair a b -> head_equiv b b' -> edge_pair a b'.
Proof.
  intros a b b' [HR HL] [HO [HZ HP]]. split.
  - intros HPa. destruct (HR HPa) as [[H8 H2]|H1].
    + left. unfold side8 in *. rewrite <- HO, <- HZ. auto.
    + right. rewrite <- HZ. exact H1.
  - intros HP'. apply HL. rewrite HP. exact HP'.
Qed.
Lemma tag_edges_normalize_join : forall sg pre sfx,
  tag_edges (pre ++ sfx) ->
  tag_edges (lin_normalize_join sg pre sfx).
Proof.
  intros sg pre. induction pre as [|g pre IH]; intros sfx HE.
  - cbn [lin_normalize_join app].
    rewrite LineageSplice_lin_split_at_spec. cbn [fst snd].
    unfold lin_normalize_slice.
    apply (tag_edges_normalize_ctx [] (firstn 6 sfx) (skipn 6 sfx)).
    cbn [app]. rewrite firstn_skipn. exact HE.
  - destruct pre as [|g1 pre1].
    + cbn [lin_normalize_join app].
      rewrite LineageSplice_lin_split_at_spec. cbn [fst snd].
      unfold lin_normalize_slice.
      apply (tag_edges_normalize_ctx []
        ([g] ++ firstn 5 sfx) (skipn 5 sfx)).
      cbn [app] in HE |- *. rewrite firstn_skipn. exact HE.
    + destruct pre1 as [|g2 tail].
      * cbn [lin_normalize_join app].
        rewrite LineageSplice_lin_split_at_spec. cbn [fst snd].
        unfold lin_normalize_slice.
        apply (tag_edges_normalize_ctx []
          ([g;g1] ++ firstn 4 sfx) (skipn 4 sfx)).
        cbn [app] in HE |- *. rewrite firstn_skipn. exact HE.
      * change (tag_edges
          (g :: lin_normalize_join sg (g1 :: g2 :: tail) sfx)).
        cbn [app] in HE.
        pose proof (IH sfx (proj2 HE)) as Htail.
        destruct (normalize_join_head sg g1 (g2::tail) sfx)
          as (h & r & E & HH).
        rewrite E in Htail. rewrite E. split.
        -- exact (edge_pair_head_equiv g g1 h (proj1 HE) HH).
        -- exact Htail.
Qed.
Open Scope N_scope.
Open Scope bool_scope.
Opaque LROUND_FUEL LROUND_CHUNKS
       FLAT_ROUND_FUEL CFUEL TRIES.
Definition phfreeP (w : word) : Prop :=
  forall g, In g w -> phshape g = false.
Lemma tagfree_phfreeP : forall w,
  tagfree w = true -> phfreeP w.
Proof.
  intros w H g Hin. unfold tagfree in H.
  apply forallb_forall with (x := g) in H; [|exact Hin].
  apply negb_true_iff in H.
  exact (phshape_false_of_tagbase_false g H).
Qed.
Lemma phfreeP_tail : forall g t,
  phfreeP (g :: t) -> phfreeP t.
Proof. intros g t H x Hx. apply H. right. exact Hx. Qed.
Lemma phfreeP_head : forall g t,
  phfreeP (g :: t) -> phshape g = false.
Proof. intros g t H. apply H. left. reflexivity. Qed.
Lemma side8_noph : forall g,
  side8 g -> phshape g = false.
Proof.
  intros [[o z] c] [Ho Hz]. unfold side8 in *.
  cbn [gO gZ] in Ho, Hz. subst o z. reflexivity.
Qed.
Lemma right_edge_noph : forall g,
  right_edge g -> phshape g = false.
Proof.
  intros [[o z] c] [HS|Hz].
  - exact (side8_noph (o,z,c) HS).
  - cbn [gZ] in Hz. subst z.
    unfold phshape, tagbase.
    cbn [gO gZ gC].
    destruct (o =? PHO)%N; reflexivity.
Qed.
Lemma edge_pair_noph : forall a b,
  phshape a = false -> phshape b = false ->
  edge_pair a b.
Proof.
  intros a b HA HB. split; intros H; congruence.
Qed.
Lemma edge_pair_head_l : forall a a' b,
  head_equiv a a' ->
  edge_pair a b -> edge_pair a' b.
Proof.
  intros a a' b [HO [HZ HP]] [HR HL]. split.
  - intros H. apply HR. rewrite HP. exact H.
  - intros H. specialize (HL H). unfold side8 in *.
    rewrite <- HO, <- HZ. exact HL.
Qed.
Lemma edge_pair_head_r : forall a b b',
  head_equiv b b' ->
  edge_pair a b -> edge_pair a b'.
Proof.
  intros a b b' [HO [HZ HP]] [HR HL]. split.
  - intros H. specialize (HR H). unfold right_edge,
      side8 in *.
    destruct HR as [[H8 H2]|H1].
    + left. rewrite <- HO, <- HZ. auto.
    + right. rewrite <- HZ. exact H1.
  - intros H. apply HL. rewrite HP. exact H.
Qed.
Lemma tag_edges_phfreeP : forall w,
  phfreeP w -> tag_edges w.
Proof.
  induction w as [|a [|b t] IH]; intros H; try exact I.
  cbn [tag_edges]. split.
  - apply edge_pair_noph; [apply (H a); left; reflexivity|].
    apply (H b). right. left. reflexivity.
  - apply IH. intros x Hx. apply H. right. exact Hx.
Qed.
Lemma tag_edges_replace_head : forall pre a b post,
  head_equiv a b ->
  tag_edges (pre ++ a :: post) ->
  tag_edges (pre ++ b :: post).
Proof.
  induction pre as [|x pre IH]; intros a b post E HE.
  - cbn [app] in HE |- *. destruct post as [|y post]; [exact I|].
    split.
    + exact (edge_pair_head_l a b y E (proj1 HE)).
    + exact (proj2 HE).
  - destruct pre as [|y pre].
    + cbn [app] in HE |- *. split.
      * exact (edge_pair_head_r x a b E (proj1 HE)).
      * exact (IH a b post E (proj2 HE)).
    + cbn [app] in HE |- *. split; [exact (proj1 HE)|].
      exact (IH a b post E (proj2 HE)).
Qed.
Lemma tag_edges_phfree_before_ph : forall fr g post,
  phfreeP fr ->
  (fr = [] \/ side8 (last fr d0)) ->
  phshape g = true ->
  tag_edges (g :: post) ->
  tag_edges (fr ++ g :: post).
Proof.
  induction fr as [|a fr IH]; intros g post HF Hend HP HE.
  - exact HE.
  - destruct fr as [|b fr].
    + cbn [app last tag_edges]. split.
      * split.
        -- intros H. rewrite (phfreeP_head a [] HF) in H. discriminate.
        -- intros _. destruct Hend as [E|HS]; [discriminate E|exact HS].
      * exact HE.
    + cbn [app tag_edges]. split.
      * apply edge_pair_noph.
        -- exact (phfreeP_head a (b::fr) HF).
        -- exact (phfreeP_head b fr (phfreeP_tail a (b::fr) HF)).
      * apply IH.
        -- exact (phfreeP_tail a (b::fr) HF).
        -- destruct Hend as [E|HS]; [discriminate E|].
           right. cbn [last] in HS |- *. exact HS.
        -- exact HP.
        -- exact HE.
Qed.
Lemma tag_edges_insert_before_ph : forall pre fr g post,
  phfreeP fr ->
  (fr = [] \/ side8 (last fr d0)) ->
  phshape g = true ->
  tag_edges (pre ++ g :: post) ->
  tag_edges (pre ++ fr ++ g :: post).
Proof.
  induction pre as [|a pre IH]; intros fr g post HF Hend HP HE.
  - cbn [app] in HE |- *.
    exact (tag_edges_phfree_before_ph fr g post HF Hend HP HE).
  - destruct pre as [|b pre].
    + cbn [app] in HE |- *. destruct fr as [|x fr].
      * exact HE.
      * change (edge_pair a x /\
                  tag_edges ((x :: fr) ++ g :: post)).
        split.
        -- apply edge_pair_noph.
           ++ exact (side8_noph a (proj2 (proj1 HE) HP)).
           ++ exact (phfreeP_head x fr HF).
        -- apply tag_edges_phfree_before_ph.
           ++ exact HF.
           ++ destruct Hend as [E|HS]; [discriminate E|]. right. exact HS.
           ++ exact HP.
           ++ exact (proj2 HE).
    + cbn [app] in HE |- *. split; [exact (proj1 HE)|].
      exact (IH fr g post HF Hend HP (proj2 HE)).
Qed.
Lemma tag_edges_phfree_replace_ph : forall mid g post,
  mid <> [] -> phfreeP mid -> phshape g = true ->
  tag_edges (g :: post) ->
  tag_edges (mid ++ post).
Proof.
  induction mid as [|a mid IH]; intros g post Hne HF HP HE;
    [contradiction|].
  destruct mid as [|b mid].
  - cbn [app]. destruct post as [|x post]; [exact I|].
    cbn [tag_edges] in HE |- *. split.
    + apply edge_pair_noph.
      * exact (phfreeP_head a [] HF).
      * exact (right_edge_noph x (proj1 (proj1 HE) HP)).
    + exact (proj2 HE).
  - change (edge_pair a b /\
              tag_edges ((b :: mid) ++ post)).
    split.
    + apply edge_pair_noph.
      * exact (phfreeP_head a (b::mid) HF).
      * exact (phfreeP_head b mid (phfreeP_tail a (b::mid) HF)).
    + apply IH with (g := g).
      * discriminate.
      * exact (phfreeP_tail a (b::mid) HF).
      * exact HP.
      * exact HE.
Qed.
Lemma tag_edges_replace_phfree : forall pre mid g post,
  mid <> [] -> phfreeP mid -> phshape g = true ->
  tag_edges (pre ++ g :: post) ->
  tag_edges (pre ++ mid ++ post).
Proof.
  induction pre as [|a pre IH]; intros mid g post Hne HF HP HE.
  - cbn [app] in HE |- *.
    exact (tag_edges_phfree_replace_ph mid g post Hne HF HP HE).
  - destruct pre as [|b pre].
    + cbn [app] in HE |- *. destruct mid as [|x mid]; [contradiction|].
      change (edge_pair a x /\
                tag_edges ((x :: mid) ++ post)).
      split.
      * apply edge_pair_noph.
        -- exact (side8_noph a (proj2 (proj1 HE) HP)).
        -- exact (phfreeP_head x mid HF).
      * exact (tag_edges_phfree_replace_ph (x::mid) g post
                 ltac:(discriminate) HF HP (proj2 HE)).
    + cbn [app] in HE |- *. split; [exact (proj1 HE)|].
      exact (IH mid g post Hne HF HP (proj2 HE)).
Qed.
Lemma tag_edges_phfree_after_ph : forall g bk post,
  phfreeP bk ->
  (bk = [] \/ right_edge (hd d0 bk)) ->
  phshape g = true ->
  tag_edges (g :: post) ->
  tag_edges (g :: bk ++ post).
Proof.
  intros g bk post HF Hhead HP HE.
  destruct bk as [|a bk].
  - exact HE.
  - change (edge_pair g a /\
              tag_edges ((a :: bk) ++ post)).
    split.
    + split.
      * intros _. destruct Hhead as [E|HR]; [discriminate E|exact HR].
      * intros H. rewrite (phfreeP_head a bk HF) in H. discriminate.
    + exact (tag_edges_phfree_replace_ph (a::bk) g post
               ltac:(discriminate) HF HP HE).
Qed.
Lemma tag_edges_insert_after_ph : forall pre g bk post,
  phfreeP bk ->
  (bk = [] \/ right_edge (hd d0 bk)) ->
  phshape g = true ->
  tag_edges (pre ++ g :: post) ->
  tag_edges (pre ++ g :: bk ++ post).
Proof.
  induction pre as [|a pre IH]; intros g bk post HF Hhead HP HE.
  - cbn [app] in HE |- *.
    exact (tag_edges_phfree_after_ph g bk post HF Hhead HP HE).
  - destruct pre as [|b pre].
    + cbn [app] in HE |- *. split; [exact (proj1 HE)|].
      exact (tag_edges_phfree_after_ph g bk post HF Hhead HP (proj2 HE)).
    + cbn [app] in HE |- *. split; [exact (proj1 HE)|].
      exact (IH g bk post HF Hhead HP (proj2 HE)).
Qed.
Lemma is_lvl_adjk : forall p g,
  is_lvl (adjk p g) = is_lvl g.
Proof.
  intros p [[o z] c]. unfold adjk, is_lvl.
  cbn [gO gZ gC].
  destruct ((o =? 4)%N && (z =? 2)%N) eqn:E;
    cbn [gO gZ gC]; rewrite E; reflexivity.
Qed.
Lemma is_spc_adjk : forall p g,
  is_spc (adjk p g) = is_spc g.
Proof.
  intros p [[o z] c]. unfold adjk.
  destruct ((o =? 4)%N && (z =? 2)%N) eqn:E; [|reflexivity].
  apply andb_prop in E as [HO HZ].
  apply N.eqb_eq in HO, HZ. subst o z. reflexivity.
Qed.
Lemma segalt_matb : forall p b,
  segalt (matb p b) = segalt b.
Proof.
  fix IH 2. intros p b. destruct b as [|l [|s b]].
  - reflexivity.
  - change (is_lvl (adjk p l) = is_lvl l).
    apply is_lvl_adjk.
  - change ((is_lvl (adjk p l) &&
              is_spc (adjk p s) &&
              segalt (matb p b)) =
            (is_lvl l && is_spc s && segalt b)).
    rewrite is_lvl_adjk, is_spc_adjk, (IH p b). reflexivity.
Qed.
Lemma sFlat_segalt : forall s,
  segalt (sBody s) = true ->
  segalt (sFlat s) = true.
Proof.
  intros s H. unfold sFlat. rewrite segalt_matb. exact H.
Qed.
Lemma segalt_nonempty : forall b,
  segalt b = true -> b <> [].
Proof. intros [|g b] H; [discriminate|discriminate]. Qed.
Lemma lvl_nspc : forall g,
  is_lvl g = true -> is_spc g = false.
Proof.
  intros [[o z] c] H. unfold is_lvl in H.
  cbn [gO gZ] in H. apply andb_prop in H as [HO HZ].
  apply N.eqb_eq in HO, HZ. subst o z. reflexivity.
Qed.
Lemma segalt_cut_left_last_spc : forall a b,
  segalt (a ++ b) = true -> segalt b = true ->
  a <> [] -> is_spc (last a d0) = true.
Proof.
  fix IH 1. intros a b HW HB Hne.
  destruct a as [|x [|y a]].
  - contradiction.
  - destruct b as [|l [|s b]].
    + discriminate HB.
    + cbn [app segalt] in HW, HB.
      repeat rewrite Bool.andb_true_iff in HW.
      discriminate (proj2 HW).
    + cbn [app segalt] in HW, HB.
      repeat rewrite Bool.andb_true_iff in HW, HB.
      pose proof (proj2 (proj1 HW)) as Hsp.
      rewrite (lvl_nspc l (proj1 (proj1 HB))) in Hsp. discriminate.
  - cbn [app segalt] in HW.
    repeat rewrite Bool.andb_true_iff in HW.
    destruct HW as [[_ HY] HW].
    assert (HR : a <> [] -> is_spc (last a d0) = true).
    { intro Hna. exact (IH a b HW HB Hna). }
    destruct a as [|z a].
    + cbn [last]. exact HY.
    + cbn [last]. apply HR. discriminate.
Qed.
Lemma segalt_cut_right_head_spc : forall a b,
  segalt a = true -> segalt (a ++ b) = true ->
  b <> [] -> is_spc (hd d0 b) = true.
Proof.
  fix IH 1. intros a b HA HW Hne.
  destruct a as [|l [|s a]].
  - discriminate HA.
  - destruct b as [|x b]; [contradiction|].
    cbn [app segalt] in HW.
    repeat rewrite Bool.andb_true_iff in HW.
    exact (proj2 (proj1 HW)).
  - cbn [segalt] in HA.
    cbn [app segalt] in HW.
    repeat rewrite Bool.andb_true_iff in HA, HW.
    exact (IH a b (proj2 HA) (proj2 HW) Hne).
Qed.
Lemma spill_front_segalt : forall s kf kb fr s1,
  segcache s = true ->
  segalt (sBody s) = true ->
  Nat.leb (segl s) (kf + kb + SEGMIN) = false ->
  spill_front s kf = (fr, s1) ->
  segalt (sBody s1) = true.
Proof.
  intros s kf kb fr s1 HC HA HSM EF.
  pose proof (segcache_len s HC) as HL.
  pose proof (segalt_odd _ HA) as HO.
  destruct (odd_ex _ HO) as (j & HJ).
  apply PeanoNat.Nat.leb_gt in HSM.
  unfold segl in HSM. rewrite <- HL, HJ,
    div2_odd in HSM.
  destruct (spill_front_body s kf HC)
    as (HB & _ & _ & _). rewrite EF in HB. cbn [snd] in HB.
  rewrite HB. apply segalt_skipn2; [exact HA|].
  rewrite HJ. lia.
Qed.
Lemma spill_front_edge_end : forall s kf kb fr s1,
  segcache s = true ->
  segalt (sBody s) = true ->
  Nat.leb (segl s) (kf + kb + SEGMIN) = false ->
  spill_front s kf = (fr, s1) ->
  fr = [] \/ side8 (last fr d0).
Proof.
  intros s kf kb fr s1 HC HA HSM EF.
  destruct fr as [|x fr]; [left; reflexivity|]. right.
  apply spc_side8.
  pose proof (spill_front_flat s kf) as HF.
  rewrite EF in HF. cbn [fst snd] in HF.
  apply (segalt_cut_left_last_spc (x::fr) (sFlat s1)).
  - rewrite HF. exact (sFlat_segalt s HA).
  - apply sFlat_segalt. exact (spill_front_segalt s kf kb (x::fr) s1
      HC HA HSM EF).
  - discriminate.
Qed.
Lemma spill_back_edge_head : forall s1 kb s2 bk,
  segalt (sBody s1) = true ->
  segalt (sBody s2) = true ->
  spill_back s1 kb = (s2, bk) ->
  bk = [] \/ right_edge (hd d0 bk).
Proof.
  intros s1 kb s2 bk HA1 HA2 EB.
  destruct bk as [|x bk]; [left; reflexivity|].
  right. left. apply spc_side8.
  pose proof (spill_back_flat s1 kb) as HF.
  rewrite EB in HF. cbn [fst snd] in HF.
  apply (segalt_cut_right_head_spc (sFlat s2) (x::bk)).
  - exact (sFlat_segalt s2 HA2).
  - rewrite HF. exact (sFlat_segalt s1 HA1).
  - discriminate.
Qed.
Lemma keyi_phg_head_equiv : forall sg g s,
  keyi sg g = Some s ->
  head_equiv g (phg (sKey s)).
Proof.
  intros sg [[o z] c] s H.
  destruct (keyi_in sg (o,z,c) s H)
    as (_ & HP & HC).
  unfold phshape, tagbase in HP.
  cbn [gO gZ gC] in HP, HC.
  repeat rewrite Bool.andb_true_iff in HP.
  destruct HP as [[HO HZ] H2].
  apply N.eqb_eq in HO, HZ. subst o z.
  unfold head_equiv, phg.
  cbn [gO gZ gC]. repeat split; try reflexivity.
  rewrite <- HC. reflexivity.
Qed.
Theorem relax_edges_ctx : forall fu sg w before,
  SGS sg -> lin_atmost sg w ->
  lin_ptags sg w = true ->
  forall pre,
  tag_edges (pre ++ w) ->
  tag_edges
    (pre ++ fst (relax fu sg w before)).
Proof.
  intros fu. induction fu as [|fu IH]; intros sg w before HSG HA HT pre HE.
  - cbn [relax fst]. exact HE.
  - destruct w as [|g t].
    + cbn [relax fst app] in HE |- *. exact HE.
    + pose proof (lin_ptags_tail sg g t HT) as HTT.
      cbn [relax]. cbv beta zeta iota.
      destruct (keyi sg g) as [s|] eqn:EK.
      * destruct (keyi_in sg g s EK) as (Hin & HP & HC).
        destruct (SGS_in sg s HSG Hin)
          as (HCache & HOk & HShape).
        assert (HAlt : segalt (sBody s) = true).
        { unfold segshape in HShape.
          exact (proj2 (andb_prop _ _ HShape)). }
        assert (HCT : countkey (sKey s) t = O)
          by (eapply keyi_atmost_tail_zero; eassumption).
        match goal with
        | |- context [Nat.leb ?a ?b] => destruct (Nat.leb a b) eqn:ESM
        end.
        -- match goal with
           | |- context [relax fu ?a ?b ?c] =>
               assert (HSG' : SGS a)
                 by (apply SGS_filter; exact HSG);
               assert (HA' : lin_atmost a b)
                 by (apply atmost_filter_tail with (g := g);
                     exact HA);
               assert (HT' : lin_ptags a b = true)
                 by (apply lin_ptags_filter_absent;
                     [exact HCT|exact HTT]);
               assert (HNE : sFlat s <> [])
                 by (apply segalt_nonempty; apply sFlat_segalt; exact HAlt);
               assert (HFree : phfreeP (sFlat s))
                 by (apply tagfree_phfreeP;
                     apply tagfree_sFlat; exact HAlt);
               assert (HEin : tag_edges
                   ((pre ++ sFlat s) ++ b));
               [ rewrite <- app_assoc;
                 exact (tag_edges_replace_phfree pre (sFlat s)
                          g b HNE HFree HP HE)
               | specialize (IH a b c HSG' HA' HT' (pre ++ sFlat s)
                               HEin);
                 destruct (relax fu a b c) as [t' sg''] eqn:ER ]
           end.
           cbn [fst] in IH |- *. rewrite <- app_assoc in IH. exact IH.
        -- match goal with
           | |- context [spill_front ?a ?b] =>
               pose proof (spill_front_key a b) as HKF;
               destruct (spill_front a b) as [fr s1] eqn:ESF
           end.
           cbn [snd] in HKF.
           match goal with
           | |- context [spill_back ?a ?b] =>
               pose proof (spill_back_key a b) as HKB;
               destruct (spill_back a b) as [s2 bk] eqn:ESB
           end.
           cbn [fst] in HKB.
           destruct (relax_step_shape s _ _ fr s1 s2 bk
                       HCache HOk HShape ESM ESF ESB)
             as (HC2 & HO2 & HS2).
           assert (HK2 : sKey s2 = sKey s)
             by (rewrite HKB, HKF; reflexivity).
           destruct (spill_tagfree s _ _ fr s1 s2 bk
                       HAlt ESF ESB) as (HFR & _ & HBK).
           assert (HSG2 : SGS
             (sgset sg (sKey s) s2))
             by (apply SGS_sgset;
                 [exact HSG|exact HC2|exact HO2|exact HS2]).
           assert (HA2 : lin_atmost
             (sgset sg (sKey s) s2) (bk ++ t))
             by (apply atmost_sgset_tagfree with (g := g);
                 [exact HK2|exact HBK|exact HA]).
           assert (HT2 : lin_ptags
             (sgset sg (sKey s) s2) (bk ++ t) = true).
           { apply lin_ptags_app_true.
             - apply lin_ptags_tagfree. exact HBK.
             - eapply lin_ptags_mono; [|exact HTT].
               intros x HX. eapply ph_sgset_preserve;
                 [exact HK2|exact HX]. }
           assert (HFRP : phfreeP fr)
             by (apply tagfree_phfreeP; exact HFR).
           assert (HBKP : phfreeP bk)
             by (apply tagfree_phfreeP; exact HBK).
           assert (Hend : fr = [] \/
             side8 (last fr d0))
             by (exact (spill_front_edge_end s _ _ fr s1 HCache HAlt ESM ESF)).
           assert (HA1 : segalt (sBody s1) = true)
             by (exact (spill_front_segalt s _ _ fr s1
                          HCache HAlt ESM ESF)).
           assert (HA2s : segalt (sBody s2) = true).
           { unfold segshape in HS2.
             exact (proj2 (andb_prop _ _ HS2)). }
           assert (Hhead : bk = [] \/
             right_edge (hd d0 bk))
             by (exact (spill_back_edge_head s1 _ s2 bk HA1 HA2s ESB)).
           pose proof (tag_edges_insert_before_ph pre fr g t
             HFRP Hend HP HE) as HE1.
           assert (HE1' : tag_edges
             ((pre ++ fr) ++ g :: t)).
           { rewrite <- app_assoc. exact HE1. }
           pose proof (tag_edges_replace_head (pre ++ fr) g
             (phg (sKey s)) t
             (keyi_phg_head_equiv sg g s EK) HE1') as HE2.
           pose proof (tag_edges_insert_after_ph (pre ++ fr)
             (phg (sKey s)) bk t HBKP Hhead
             (proj1 (proj2 (keyi_in sg
                       (phg (sKey s)) s
                       (keyi_phg_self sg g s EK)))) HE2) as HE3.
           assert (HEin : tag_edges
             (((pre ++ fr) ++ [phg (sKey s)]) ++ (bk ++ t))).
           { rewrite <- app_assoc. cbn [app]. exact HE3. }
           match goal with
           | |- context [relax fu ?a ?b ?c] =>
               specialize (IH a b c HSG2 HA2 HT2
                 ((pre ++ fr) ++ [phg (sKey s)]) HEin);
               destruct (relax fu a b c) as [t' sg''] eqn:ER
           end.
           cbn [fst] in IH |- *.
           repeat rewrite <- app_assoc in IH. cbn [app] in IH. exact IH.
      * match goal with
        | |- context [relax fu ?a ?b ?c] =>
            assert (HEin : tag_edges ((pre ++ [g]) ++ b));
            [ rewrite <- app_assoc; cbn [app]; exact HE
            | specialize (IH a b c HSG
                (atmost_tail sg g t HA) HTT
                (pre ++ [g]) HEin);
              destruct (relax fu a b c) as [t' sg'] eqn:ER ]
        end.
        cbn [fst] in IH |- *. rewrite <- app_assoc in IH.
        cbn [app] in IH. exact IH.
Qed.
Theorem lin_relax_edges : forall sg w w2 sg2,
  sg_wf sg -> sg_shape sg ->
  lin_ok sg w = true -> lin_ptags sg w = true ->
  tag_edges w ->
  lin_relax sg w = (w2, sg2) ->
  tag_edges w2.
Proof.
  intros sg w w2 sg2 HW HS HOk HT HE HR.
  pose proof (relax_edges_ctx (length w) sg w
    (GUARD + SLACK)%nat
    (SGS_of sg HW HS)
    (lin_ok_atmost sg w HOk) HT [] HE) as H.
  unfold lin_relax in HR. rewrite HR in H.
  cbn [fst app] in H. exact H.
Qed.
Lemma tag_edges_suffix : forall p t,
  tag_edges (p ++ t) -> tag_edges t.
Proof.
  induction p as [|g p IH]; intros t H; [exact H|].
  apply IH. exact (tag_edges_tail g (p ++ t) H).
Qed.
Lemma tag_edges_ph_right : forall g t,
  phshape g = true ->
  (t = [] \/ right_edge (hd d0 t)) ->
  tag_edges t -> tag_edges (g :: t).
Proof.
  intros g [|x t] HP HR HE; [exact I|].
  cbn [tag_edges]. split; [|exact HE]. split.
  - intros _. destruct HR as [E|H]; [discriminate E|exact H].
  - intros Hx. destruct HR as [E|H]; [discriminate E|].
    rewrite (right_edge_noph x H) in Hx. discriminate.
Qed.
Lemma tag_edges_delete_around : forall pc fr g bk pt,
  phshape g = true ->
  (pc = [] \/ side8 (last pc d0)) ->
  (pt = [] \/ right_edge (hd d0 pt)) ->
  tag_edges ((pc ++ fr) ++ g :: (bk ++ pt)) ->
  tag_edges (pc ++ g :: pt).
Proof.
  induction pc as [|a pc IH]; intros fr g bk pt HP HL HR HE.
  - cbn [app] in HE |- *.
    apply tag_edges_ph_right; [exact HP|exact HR|].
    apply (tag_edges_suffix bk pt).
    apply tag_edges_tail with (g := g).
    exact (tag_edges_suffix fr (g :: bk ++ pt) HE).
  - destruct pc as [|b pc].
    + change (edge_pair a g /\
                tag_edges (g :: pt)). split.
      * split.
        -- intros HPa. destruct HL as [E|HS]; [discriminate E|].
           rewrite (side8_noph a HS) in HPa.
           discriminate.
        -- intros _. destruct HL as [E|HS]; [discriminate E|exact HS].
      * apply (IH fr g bk pt HP (or_introl eq_refl) HR).
        cbn [app] in HE.
        exact (tag_edges_tail a (fr ++ g :: bk ++ pt) HE).
    + cbn [app] in HE |- *. split; [exact (proj1 HE)|].
      apply (IH fr g bk pt HP).
      * destruct HL as [E|HS]; [discriminate E|].
        right. cbn [last] in HS |- *. exact HS.
      * exact HR.
      * exact (proj2 HE).
Qed.
Lemma hd_rev_last : forall (A : Type) (d : A) (l : list A),
  hd d (rev l) = last l d.
Proof.
  intros A d l. induction l using rev_ind.
  - reflexivity.
  - rewrite rev_app_distr. cbn [rev hd]. rewrite last_last. reflexivity.
Qed.
Lemma hd_skipn_nth : forall (A : Type) (d : A) n (l : list A),
  hd d (skipn n l) = nth n l d.
Proof.
  intros A d n. induction n as [|n IH]; intros [|x l];
    cbn [skipn hd nth]; try reflexivity. apply IH.
Qed.
Lemma last_firstn_rev_nth : forall (A : Type) (d : A) pre lb,
  (lb < length pre)%nat ->
  last (firstn (length pre - lb) pre) d = nth lb (rev pre) d.
Proof.
  intros A d pre lb Hlt.
  rewrite <- hd_rev_last, firstn_skipn_rev, rev_involutive,
    hd_skipn_nth.
  replace (length pre - (length pre - lb))%nat with lb by lia.
  reflexivity.
Qed.
Lemma spc_nth_lt : forall n w,
  is_spc (nth n w d0) = true -> (n < length w)%nat.
Proof.
  induction n as [|n IH]; intros [|g w] H;
    cbn [nth length] in H |- *; try discriminate; try lia.
  specialize (IH w H). lia.
Qed.
Lemma repack_one_edges : forall sg w key sg2 w2,
  tag_edges w ->
  repack_one sg w key = Some (sg2, w2) ->
  tag_edges w2.
Proof.
  intros sg w key sg2 w2 HE H.
  unfold repack_one in H.
  destruct (locate_key w key) as [i|] eqn:EL; [|discriminate].
  destruct (locate_key_spec w key i EL)
    as (gi & Hgi & Hik).
  rewrite LineageSplice_lin_split_at_spec in H.
  cbv beta iota in H.
  destruct (skipn i w) as [|g post] eqn:ES; [discriminate|].
  destruct (keyi sg g) as [s|] eqn:EKI; [|discriminate].
  cbv zeta in H.
  match type of H with
  | (if ?gate then _ else _) = _ => destruct gate eqn:EG
  end; [|discriminate].
  match type of H with
  | (if ?gate then _ else _) = _ => destruct gate eqn:EGE
  end; [|discriminate].
  injection H as Hsg Hw. subst sg2 w2.
  set (pre := firstn i w) in *.
  set (nb := cleanrun sg (rev pre) i) in *.
  set (na := cleanrun sg post (length post)) in *.
  set (lb := (2 * Nat.div2 (nb - MARG))%nat) in *.
  set (la := (2 * Nat.div2 (na - MARG))%nat) in *.
  set (fr := rev (firstn lb (rev pre))) in *.
  set (bk := firstn la post) in *.
  set (pc := firstn (i - lb)%nat pre) in *.
  set (pt := skipn la post) in *.
  assert (Hgw : nth_error w i = Some g).
  { rewrite <- (PeanoNat.Nat.add_0_r i), <- nth_skipn, ES.
    reflexivity. }
  assert (Egi : gi = g) by congruence. subst gi.
  unfold is_key in Hik. apply andb_prop in Hik as [HP _].
  assert (Hiw : (i < length w)%nat).
  { apply nth_error_Some. rewrite Hgw. discriminate. }
  assert (HW : w = pre ++ g :: post).
  { unfold pre. rewrite <- ES. symmetry. apply firstn_skipn. }
  assert (Hpre : length pre = i).
  { unfold pre. rewrite length_firstn. lia. }
  unfold repack_edges_ok in EGE.
  apply andb_prop in EGE as [HLE HRE].
  assert (Hlblen : (lb < length pre)%nat).
  { rewrite <- length_rev. exact (spc_nth_lt lb (rev pre) HLE). }
  assert (Hpref : pre = pc ++ fr).
  { unfold pc, fr. rewrite firstn_rev, rev_involutive, Hpre.
    symmetry. apply firstn_skipn. }
  assert (Hpost : post = bk ++ pt).
  { unfold bk, pt. symmetry. apply firstn_skipn. }
  assert (HL : pc = [] \/ side8 (last pc d0)).
  { right. apply spc_side8. unfold pc.
    rewrite <- Hpre.
    rewrite (last_firstn_rev_nth bg d0 pre lb Hlblen).
    exact HLE. }
  assert (HR : pt = [] \/ right_edge (hd d0 pt)).
  { right. left. apply spc_side8. unfold pt.
    rewrite hd_skipn_nth. exact HRE. }
  apply (tag_edges_delete_around pc fr g bk pt HP HL HR).
  rewrite <- Hpref, <- Hpost, <- HW. exact HE.
Qed.
Lemma repack_keys_edges : forall keys sg w sg2 w2,
  tag_edges w ->
  repack_keys keys sg w = Some (sg2, w2) ->
  tag_edges w2.
Proof.
  induction keys as [|k keys IH]; intros sg w sg2 w2 HE H.
  - cbn [repack_keys] in H. injection H as <- <-. exact HE.
  - cbn [repack_keys] in H.
    destruct (repack_one sg w k) as [[sg1 w1]|] eqn:ER;
      [|discriminate].
    exact (IH sg1 w1 sg2 w2 (repack_one_edges sg w k sg1 w1 HE ER) H).
Qed.
Lemma tag_edges_firstn : forall n w,
  tag_edges w -> tag_edges (firstn n w).
Proof.
  induction n as [|n IH]; intros w HE.
  - exact I.
  - destruct w as [|a t]; [exact I|].
    destruct n as [|n]; [exact I|].
    destruct t as [|b t]; [exact I|].
    change (edge_pair a b /\
              tag_edges (firstn (S n) (b::t))).
    split; [exact (proj1 HE)|exact (IH (b::t) (proj2 HE))].
Qed.
Lemma tag_edges_skipn : forall n w,
  tag_edges w -> tag_edges (skipn n w).
Proof.
  induction n as [|n IH]; intros [|g w] HE; try exact HE; try exact I.
  cbn [skipn]. apply IH. exact (tag_edges_tail g w HE).
Qed.
Lemma tag_edges_prepend_ph : forall pre g out,
  tag_edges pre ->
  (pre = [] \/ side8 (last pre d0)) ->
  phshape g = true ->
  tag_edges out ->
  (out = [] \/ right_edge (hd d0 out)) ->
  tag_edges (pre ++ g :: out).
Proof.
  induction pre as [|a pre IH]; intros g out HPre HL HP HOut HR.
  - cbn [app]. exact (tag_edges_ph_right g out HP HR HOut).
  - destruct pre as [|b pre].
    + change (edge_pair a g /\
                tag_edges (g :: out)). split.
      * split.
        -- intros HPa. destruct HL as [E|HS]; [discriminate E|].
           rewrite (side8_noph a HS) in HPa.
           discriminate.
        -- intros _. destruct HL as [E|HS]; [discriminate E|exact HS].
      * exact (tag_edges_ph_right g out HP HR HOut).
    + cbn [app tag_edges]. split; [exact (proj1 HPre)|].
      apply IH; [exact (proj2 HPre)| |exact HP|exact HOut|exact HR].
      destruct HL as [E|HS]; [discriminate E|].
      right. cbn [last] in HS |- *. exact HS.
Qed.
Lemma last_firstn_nth_error : forall (A : Type) (d : A) w n g,
  nth_error w n = Some g -> last (firstn (S n) w) d = g.
Proof.
  intros A d w. induction w as [|x w IH]; intros n g H;
    [destruct n; discriminate|].
  destruct n as [|n].
  - cbn [nth_error firstn last] in H |- *. injection H as <-. reflexivity.
  - cbn [nth_error] in H.
    change (last (x :: firstn (S n) w) d = g).
    assert (HLEN : length (firstn (S n) w) = S n).
    { assert (Hlt : (n < length w)%nat).
      { apply nth_error_Some. rewrite H. discriminate. }
      rewrite length_firstn. apply PeanoNat.Nat.min_l. lia. }
    destruct (firstn (S n) w) as [|y ys] eqn:EF.
    + cbn [length] in HLEN. lia.
    + cbn [last].
      pose proof (IH n g H) as HI. rewrite EF in HI. exact HI.
Qed.
Lemma lapply_head : forall pl w i kx,
  plan_flankP pl w i ->
  nth_error (fst (lapply pl w i kx)) O = nth_error w O.
Proof.
  intros [|[s l] pl] w i kx HF; [reflexivity|].
  cbn [plan_flankP] in HF.
  destruct HF as (Hs & (gl & Hgl & Hsl) & _ & _).
  cbn [lapply].
  destruct (split_body (firstn l (skipn (s-i) w)))
    as [bf bb] eqn:EB.
  cbv beta iota zeta.
  destruct (lapply pl (skipn ((s-i)+l) w) (s+l) (kx+1))
    as [cw added] eqn:ER. cbn [fst].
  destruct w as [|g w].
  - destruct (s-i-1)%nat; discriminate Hgl.
  - destruct (s-i)%nat as [|d] eqn:Ed; [lia|]. reflexivity.
Qed.
Lemma plan_flankP_shift_pre1 : forall pl pre t i,
  plan_flankP pl t (i + length pre)%nat ->
  (forall s l, In (s, l) pl -> (i + length pre < s)%nat) ->
  plan_flankP pl (pre ++ t) i.
Proof.
  intros pl pre t i HP HB. destruct pl as [|[s l] pl']; [exact I|].
  cbn [plan_flankP] in HP |- *.
  destruct HP as (H1 & (gl & Hgl & Hsl) & (gr & Hgr & Hsr) & H4).
  pose proof (HB s l (or_introl eq_refl)) as Hs.
  assert (HS2 : skipn ((s-i)+l) (pre++t) =
      skipn ((s-(i+length pre))+l) t).
  { rewrite skipn_app.
    assert (HK : skipn ((s-i)+l) pre = []) by (apply skipn_all2; lia).
    rewrite HK. cbn [app]. f_equal. lia. }
  split; [lia|]. split.
  - exists gl. split; [|exact Hsl]. rewrite nth_error_app2 by lia.
    replace (s-i-1-length pre)%nat with (s-(i+length pre)-1)%nat by lia.
    exact Hgl.
  - split.
    + exists gr. split; [|exact Hsr]. rewrite nth_error_app2 by lia.
      replace ((s-i)+l-length pre)%nat
        with ((s-(i+length pre))+l)%nat by lia. exact Hgr.
    + rewrite HS2. exact H4.
Qed.
Lemma takerun_real_nonempty : forall sg0 g t r rest,
  casc_real sg0 g = true ->
  takerun_real sg0 (g::t) = (r,rest) -> r <> [].
Proof.
  intros sg0 g t r rest HC H. cbn [takerun_real] in H.
  rewrite HC in H. destruct (takerun_real sg0 t) as [a b].
  injection H as <- <-. discriminate.
Qed.
Lemma lplan_real_lb1 : forall fu sg0 w i s l,
  In (s,l) (lplan_real fu sg0 w i) -> (i < s)%nat.
Proof.
  induction fu as [|fu IH]; intros sg0 w i s l Hin.
  - contradiction.
  - destruct w as [|g t]; [contradiction|].
    cbn [lplan_real] in Hin.
    destruct (casc_real sg0 g) eqn:Ec.
    2:{ cbv beta iota in Hin. specialize (IH sg0 t (S i) s l Hin). lia. }
    destruct (takerun_real sg0 (g::t)) as [r rest] eqn:ET.
    cbv beta iota zeta in Hin.
    destruct (Nat.leb (2*MARG+SEGMIN_GROUPS) (length r));
      cbv beta iota in Hin.
    2:{ specialize (IH sg0 rest (i+length r)%nat s l Hin).
        pose proof (takerun_real_nonempty sg0 g t r rest Ec ET) as Hrn.
        destruct r; cbn [length] in *; [contradiction|lia]. }
    match type of Hin with
    | In _ (if ?gate then _ else _) => destruct gate eqn:EG
    end; cbv beta iota in Hin.
    2:{ specialize (IH sg0 rest (i+length r)%nat s l Hin).
        pose proof (takerun_real_nonempty sg0 g t r rest Ec ET) as Hrn.
        destruct r; cbn [length] in *; [contradiction|lia]. }
    destruct Hin as [Hhd|Hin].
    + injection Hhd as Hs Hl. subst s l.
      destruct (is_lvl (nth MARG r d0));
        cbv beta; unfold MARG; lia.
    + specialize (IH sg0 rest (i+length r)%nat s l Hin).
      pose proof (takerun_real_nonempty sg0 g t r rest Ec ET) as Hrn.
      destruct r; cbn [length] in *; [contradiction|lia].
Qed.
Lemma lplan_real_flank_run_shift : forall fu sg0 w r rest i,
  (forall w' i', plan_flankP
      (lplan_real fu sg0 w' i') w' i') ->
  takerun_real sg0 w = (r,rest) ->
  plan_flankP
    (lplan_real fu sg0 rest (i+length r)%nat) w i.
Proof.
  intros fu sg0 w r rest i IH ET.
  pose proof (takerun_real_split sg0 w) as HW.
  rewrite ET in HW. cbn [fst snd] in HW. rewrite <- HW.
  apply plan_flankP_shift_pre1.
  - apply IH.
  - intros s l Hin.
    exact (lplan_real_lb1 fu sg0 rest (i+length r)%nat s l Hin).
Qed.
Lemma lplan_real_flank_entry : forall fu sg0 w r rest i a b,
  (forall w' i', plan_flankP
      (lplan_real fu sg0 w' i') w' i') ->
  takerun_real sg0 w = (r,rest) ->
  (1 <= a)%nat -> (a < b)%nat -> (b < length r)%nat ->
  is_spc (nth (a-1) r d0) = true ->
  is_spc (nth b r d0) = true ->
  plan_flankP
    (((i+a)%nat,(b-a)%nat) ::
      lplan_real fu sg0 rest (i+length r)%nat) w i.
Proof.
  intros fu sg0 w r rest i a b IH ET Ha Hab Hbr HS1 HS2.
  pose proof (takerun_real_split sg0 w) as HW.
  rewrite ET in HW. cbn [fst snd] in HW. subst w.
  cbn [plan_flankP].
  replace (i+a-i)%nat with a by lia.
  replace (a+(b-a))%nat with b by lia.
  replace (i+a+(b-a))%nat with (i+b)%nat by lia.
  split; [exact Ha|]. split.
  - exists (nth (a-1) r d0). split; [|exact HS1].
    rewrite nth_error_app1 by lia. apply nth_error_nth'. lia.
  - split.
    + exists (nth b r d0). split; [|exact HS2].
      rewrite nth_error_app1 by lia. apply nth_error_nth'. lia.
    + rewrite skipn_app. replace (b-length r)%nat with O by lia.
      cbn [skipn]. apply plan_flankP_shift_pre1.
      * rewrite length_skipn.
        replace (i+b+(length r-b))%nat with (i+length r)%nat by lia.
        apply IH.
      * intros s l Hin. rewrite length_skipn.
        pose proof (lplan_real_lb1 fu sg0 rest (i+length r)%nat s l Hin).
        lia.
Qed.
Lemma lplan_real_flankP : forall fu sg0 w i,
  plan_flankP (lplan_real fu sg0 w i) w i.
Proof.
  induction fu as [|fu IH]; intros sg0 w i; [exact I|].
  destruct w as [|g t]; [exact I|].
  cbn [lplan_real].
  destruct (casc_real sg0 g) eqn:Ec.
  2:{ cbv beta iota. change (g::t) with ([g]++t).
      apply plan_flankP_shift_pre1.
      - cbn [length]. replace (i+1)%nat with (S i) by lia. apply IH.
      - cbn [length]. intros s l Hin.
        pose proof (lplan_real_lb1 fu sg0 t (S i) s l Hin). lia. }
  destruct (takerun_real sg0 (g::t)) as [r rest] eqn:ET.
  cbv beta iota zeta.
  destruct (Nat.leb (2*MARG+SEGMIN_GROUPS) (length r))
    eqn:E1.
  2:{ eapply lplan_real_flank_run_shift; [exact (IH sg0)|exact ET]. }
  apply PeanoNat.Nat.leb_le in E1. cbv beta iota.
  match goal with
  | |- plan_flankP (if ?gate then _ else _) _ _ =>
      destruct gate eqn:EG
  end.
  2:{ eapply lplan_real_flank_run_shift; [exact (IH sg0)|exact ET]. }
  apply andb_prop in EG as [EG1 EL2].
  apply andb_prop in EG1 as [ES1 ES2].
  apply PeanoNat.Nat.ltb_lt in EL2.
  apply lplan_real_flank_entry.
  - exact (IH sg0).
  - exact ET.
  - destruct (is_lvl (nth MARG r d0));
      cbv beta; unfold MARG; lia.
  - exact EL2.
  - destruct (is_lvl
      (nth (length r-MARG-1) r d0)); cbv beta;
      unfold MARG, SEGMIN_GROUPS, SEGMIN in *; lia.
  - exact ES1.
  - exact ES2.
Qed.
Lemma phg_shape : forall k,
  (2 <= k)%N -> phshape (phg k) = true.
Proof.
  intros k H. unfold phshape, phg.
  cbn [gO gZ gC]. apply N.leb_le. exact H.
Qed.
Lemma lapply_edges : forall pl w i kx,
  plan_flankP pl w i ->
  tag_edges w -> (2 <= kx)%N ->
  tag_edges (fst (lapply pl w i kx)).
Proof.
  induction pl as [|[s l] pl IH]; intros w i kx HF HE HK.
  - cbn [lapply fst]. exact HE.
  - cbn [plan_flankP] in HF.
    destruct HF as (Hs & (gl & Hgl & Hsl) &
      (gr & Hgr & Hsr) & HFrec).
    assert (HErest : tag_edges (skipn ((s-i)+l) w))
      by (apply tag_edges_skipn; exact HE).
    pose proof (IH (skipn ((s-i)+l) w) (s+l)%nat (kx+1)%N
      HFrec HErest ltac:(lia)) as HRec.
    pose proof (lapply_head pl (skipn ((s-i)+l) w)
      (s+l)%nat (kx+1)%N HFrec) as HHead.
    cbn [lapply].
    destruct (split_body (firstn l (skipn (s-i) w)))
      as [bf bb] eqn:EB.
    cbv beta iota zeta.
    destruct (lapply pl (skipn ((s-i)+l) w)
      (s+l)%nat (kx+1)%N) as [cw added] eqn:ER.
    cbn [fst] in HRec, HHead |- *.
    assert (HPre : tag_edges (firstn (s-i) w))
      by (apply tag_edges_firstn; exact HE).
    assert (HL : firstn (s-i) w = [] \/
      side8 (last (firstn (s-i) w) d0)).
    { right. apply spc_side8.
      replace (s-i)%nat with (S (s-i-1)) by lia.
      rewrite (last_firstn_nth_error bg d0 w (s-i-1)%nat
                 gl Hgl). exact Hsl. }
    assert (Hcw0 : nth_error cw O = Some gr).
    { rewrite HHead, nth_skipn.
      replace ((s-i)+l+0)%nat with ((s-i)+l)%nat by lia. exact Hgr. }
    assert (HR : cw = [] \/ right_edge (hd d0 cw)).
    { destruct cw as [|x cw]; [discriminate Hcw0|]. right. left.
      apply spc_side8. cbn [nth_error] in Hcw0.
      injection Hcw0 as <-. exact Hsr. }
    exact (tag_edges_prepend_ph (firstn (s-i) w) (phg kx) cw
      HPre HL (phg_shape kx HK) HRec HR).
Qed.
Lemma lin_extend_edges : forall sg w sg2 w2,
  tag_edges w ->
  lin_extend sg w = Some (sg2,w2) ->
  tag_edges w2.
Proof.
  intros sg w sg2 w2 HE H. unfold lin_extend in H.
  destruct (lplan_real (length w) sg w O) as [|p pl] eqn:EP.
  - injection H as <- <-. exact HE.
  - destruct (lapply (p::pl) w O
      (fresh_key sg KMAGIC)) as [wA added] eqn:EL.
    cbv beta iota zeta in H.
    repeat match type of H with
    | (if ?gate then _ else _) = _ => destruct gate eqn:?E
    end; try discriminate.
    injection H as <- <-.
    pose proof (lplan_real_flankP (length w) sg w O) as HF.
    rewrite EP in HF.
    assert (HK : (2 <= fresh_key sg KMAGIC)%N).
    { pose proof (proj1 (fresh_key_spec sg KMAGIC)).
      unfold KMAGIC in *. lia. }
    pose proof (lapply_edges (p::pl) w O
      (fresh_key sg KMAGIC) HF HE HK) as HX.
    rewrite EL in HX. cbn [fst] in HX. exact HX.
Qed.
Lemma lin_repack_edges : forall sg w sg2 ps2 w2,
  tag_edges w ->
  lin_repack sg w = Some (sg2,ps2,w2) ->
  tag_edges w2.
Proof.
  intros sg w sg2 ps2 w2 HE H. unfold lin_repack in H.
  destruct (repack_keys (map sKey sg) sg w)
    as [[sgA wA]|] eqn:ER; [|discriminate].
  pose proof (repack_keys_edges (map sKey sg) sg w sgA wA HE ER)
    as HEA.
  cbv beta iota in H.
  destruct (Nat.leb (length wA) LZONE_MAX) eqn:EZ.
  - cbv beta iota in H.
    destruct (locate_all sgA wA) as [psA|] eqn:EL;
      [|discriminate].
    destruct (lin_guard_at sgA psA wA); [|discriminate].
    destruct (lin_tags sgA wA); [|discriminate].
    injection H as <- <- <-. exact HEA.
  - cbv beta iota in H.
    destruct (lin_extend sgA wA) as [[sgB wB]|] eqn:EE;
      [|discriminate].
    pose proof (lin_extend_edges sgA wA sgB wB HEA EE) as HEB.
    cbv beta iota in H.
    destruct (locate_all sgB wB) as [psB|] eqn:EL;
      [|discriminate].
    destruct (lin_guard_at sgB psB wB); [|discriminate].
    destruct (lin_tags sgB wB); [|discriminate].
    injection H as <- <- <-. exact HEB.
Qed.
Open Scope N_scope.
Open Scope bool_scope.
Opaque LROUND_FUEL LROUND_CHUNKS
       FLAT_ROUND_FUEL CFUEL TRIES.
Fixpoint phseq (w : word) : word :=
  match w with
  | [] => []
  | g :: t => if phshape g then g :: phseq t else phseq t
  end.
Lemma phseq_app : forall a b,
  phseq (a ++ b) = phseq a ++ phseq b.
Proof.
  induction a as [|g a IH]; intros b; [reflexivity|].
  cbn [app phseq]. destruct (phshape g); rewrite IH; reflexivity.
Qed.
Ltac phfalse :=
  first
    [ apply phshape_c1
    | apply phshape_c0
    | apply phshape_znot2; reflexivity
    | apply phshape_onot9; reflexivity
    | reflexivity ].
Ltac phseq_lits :=
  cbn [phseq app];
  repeat first
    [ rewrite phshape_c1
    | rewrite phshape_c0
    | rewrite phshape_znot2 by reflexivity
    | rewrite phshape_onot9 by reflexivity ];
  reflexivity.
Lemma leaf_act_phseq : forall s f s2 f2,
  leaf_act s f = Some (s2, f2) -> phseq s2 = phseq s.
Proof.
  induction s as [|[[o z] c] t IH]; intros f s2 f2 H;
    [discriminate|].
  destruct z as [|[zp|zp|]].
  { cbn [leaf_act] in H. discriminate. }
  { cbn [leaf_act] in H. discriminate. }
  2:{ cbn [leaf_act] in H.
      destruct (2 <=? c)%N eqn:EC2.
      - destruct (2 <=? o)%N; [|discriminate].
        destruct (2 <? c)%N;
          injection H as <- <-; cbn [phseq];
          repeat rewrite phshape_znot2 by reflexivity;
          reflexivity.
      - destruct (negb (c =? 1) || negb (2 <=? o))%N; [discriminate|].
        destruct t as [|[[B zb] cb] t2].
        + destruct (2 <=? f)%N.
          * injection H as <- <-. cbn [phseq].
            repeat rewrite phshape_znot2 by reflexivity.
            reflexivity.
          * destruct (f =? 1)%N; [|discriminate].
            injection H as <- <-. cbn [phseq].
            repeat rewrite phshape_znot2 by reflexivity.
            reflexivity.
        + match type of H with
          | (if ?X then _ else _) = _ => destruct X eqn:EG
          end.
          * match type of H with
            | (if ?X then _ else _) = _ => destruct X eqn:E5
            end.
            -- destruct t2 as [|[[o2 z2] c2] t3]; [discriminate|].
               injection H as <- <-.
               apply andb_prop in E5 as [E5a E5b].
               apply andb_prop in E5a as [EB5 Ecb1].
               apply N.eqb_eq in EB5, Ecb1. subst B cb.
               apply andb_prop in E5b as [Eo2 Ez2].
               apply N.eqb_eq in Eo2, Ez2. subst o2 z2.
               phseq_lits.
            -- destruct (B =? 1)%N eqn:EB1.
               ++ apply N.eqb_eq in EB1. subst B.
                  destruct (cb =? 1)%N eqn:Ecb; [|discriminate].
                  apply N.eqb_eq in Ecb. subst cb.
                  injection H as <- <-. phseq_lits.
               ++ destruct ((cb =? 1) && (2 <=? B))%N eqn:EB2;
                    [|discriminate].
                  apply andb_prop in EB2 as [Ecb _].
                  apply N.eqb_eq in Ecb. subst cb.
                  injection H as <- <-. phseq_lits.
          * destruct ((B =? 8) && (zb =? 2) && (cb =? 1))%N eqn:E8.
            -- apply andb_prop in E8 as [E8 Ecb].
               apply andb_prop in E8 as [EB Ez].
               apply N.eqb_eq in EB, Ez, Ecb. subst B zb cb.
               injection H as <- <-. phseq_lits.
            -- destruct ((B =? 4) && (zb =? 2))%N eqn:E4.
               ++ apply andb_prop in E4 as [EB Ez].
                  apply N.eqb_eq in EB, Ez. subst B zb.
                  destruct (cb =? 1)%N eqn:Ecb.
                  ** apply N.eqb_eq in Ecb. subst cb.
                     injection H as <- <-. phseq_lits.
                  ** destruct (2 <=? cb)%N; [|discriminate].
                     injection H as <- <-. phseq_lits.
               ++ destruct (zb =? 1)%N eqn:Ezb.
                  ** apply N.eqb_eq in Ezb. subst zb.
                     destruct (2 <=? cb)%N.
                     --- destruct (2 <=? B)%N; [|discriminate].
                         injection H as <- <-. phseq_lits.
                     --- destruct (B =? 1)%N eqn:EB.
                         +++ apply N.eqb_eq in EB. subst B.
                             destruct (cb =? 1)%N eqn:Ecb;
                               [|discriminate].
                             apply N.eqb_eq in Ecb. subst cb.
                             injection H as <- <-. phseq_lits.
                         +++ destruct ((cb =? 1) && (2 <=? B))%N
                               eqn:EB2; [|discriminate].
                             apply andb_prop in EB2 as [Ecb _].
                             apply N.eqb_eq in Ecb. subst cb.
                             injection H as <- <-. phseq_lits.
                  ** destruct ((3 <=? zb) && (cb =? 1))%N eqn:E3z;
                       [|discriminate].
                     apply andb_prop in E3z as [_ Ecb].
                     apply N.eqb_eq in Ecb. subst cb.
                     destruct (B =? 1)%N eqn:EB.
                     --- apply N.eqb_eq in EB. subst B.
                         injection H as <- <-. phseq_lits.
                     --- destruct (2 <=? B)%N; [|discriminate].
                         injection H as <- <-. phseq_lits. }
  - destruct zp as [zp'|zp'|]; cbn [leaf_act] in H; try discriminate.
    destruct c as [|[cp|cp|]]; cbn [leaf_act] in H; try discriminate.
    destruct ((5 <=? o) && negb (o =? 8) && negb (o =? 12))%N;
      [|discriminate].
    destruct t as [|[[on zn] cn] t2].
    + destruct (f =? 3)%N; cbv beta iota in H.
      * injection H as <- <-. cbn [phseq].
        repeat rewrite phshape_c1. reflexivity.
      * destruct (f =? 2)%N; cbv beta iota in H.
        -- injection H as <- <-. cbn [phseq].
           repeat rewrite phshape_c1. reflexivity.
        -- destruct (f =? 4)%N; cbv beta iota in H;
             [injection H as <- <-|discriminate].
           cbn [phseq]. repeat rewrite phshape_c1.
           reflexivity.
    + destruct (on =? 1)%N; [discriminate|].
      destruct ((on =? 3) && (zn =? 2) && (cn =? 1) && (f =? 4))%N
        eqn:E3.
      * apply andb_prop in E3 as [E3 _].
        apply andb_prop in E3 as [E3 Ecn].
        apply andb_prop in E3 as [Eon Ezn].
        apply N.eqb_eq in Eon, Ezn, Ecn. subst on zn cn.
        destruct t2 as [|[[o2 z2] c2] t3].
        -- injection H as <- <-. phseq_lits.
        -- destruct t3 as [|g3 t4]; [|discriminate].
           destruct ((o2 =? 4) && (z2 =? 2))%N eqn:E42;
             [|discriminate].
           apply andb_prop in E42 as [Eo Ez].
           apply N.eqb_eq in Eo, Ez. subst o2 z2.
           injection H as <- <-. phseq_lits.
      * destruct ((on =? 4) && (zn =? 2))%N eqn:E4.
        -- apply andb_prop in E4 as [Eon Ezn].
           apply N.eqb_eq in Eon, Ezn. subst on zn.
           destruct t2 as [|[[o2 z2] c2] t3].
           ++ destruct (f =? 4)%N; [|discriminate].
              injection H as <- <-. phseq_lits.
           ++ destruct t3 as [|[[o3 z3] c3] t4]; [discriminate|].
              destruct t4 as [|g4 t5]; [|discriminate].
              lazymatch type of H with
              | (if ?b then _ else _) = _ => destruct b eqn:EOr in H
              end; [|discriminate].
              apply andb_prop in EOr as [EOr _].
              apply andb_prop in EOr as [EOr Ez3].
              apply andb_prop in EOr as [EOr Eo3].
              apply andb_prop in EOr as [EOr Ec2].
              apply andb_prop in EOr as [EOr Ez2].
              apply andb_prop in EOr as [_ Eo2].
              apply N.eqb_eq in Eo2, Ez2, Ec2, Eo3, Ez3.
              subst o2 z2 c2 o3 z3.
              injection H as <- <-.
              destruct (cn =? 1)%N; phseq_lits.
        -- lazymatch type of H with
           | (if ?b then _ else _) = _ => destruct b eqn:EX6 in H
           end.
           ++ destruct t2 as [|[[o2 z2] c2] t3]; [discriminate|].
              destruct t3 as [|g3 t4]; [|discriminate].
              apply andb_prop in EX6 as [EX6 EM].
              apply andb_prop in EX6 as [EX6 _].
              apply andb_prop in EX6 as [EX6 Ecn].
              apply andb_prop in EX6 as [EX6 Ezn].
              apply andb_prop in EX6 as [Eo6 Eon].
              apply N.eqb_eq in Eon, Ezn, Ecn. subst on zn cn.
              apply andb_prop in EM as [Eo Ez].
              apply N.eqb_eq in Eo, Ez. subst o2 z2.
              injection H as <- <-. phseq_lits.
           ++ lazymatch type of H with
              | (if ?b then _ else _) = _ => destruct b eqn:ER in H
              end; [|discriminate].
              lazymatch type of H with
              | context [leaf_act ?w ?ff] =>
                  destruct (leaf_act w ff) as [[s' f']|] eqn:ERC in H
              end; [|discriminate].
              cbv beta iota in H. injection H as <- <-.
              cbn [phseq]. rewrite phshape_c1.
              exact (IH f s' f' ERC).
Qed.
Ltac split_last2 H cols :=
  lazymatch type of H with
  | context [last2 cols] =>
      destruct (last2 cols) as [[[ini [[ga gaz] gac]] [[gb gbz] gbc]]|]
        eqn:EL in H; [|discriminate];
      pose proof (LineageGuard_last2_split cols ini
        (ga,gaz,gac) (gb,gbz,gbc) EL) as EC;
      subst cols
  end.
Ltac split6 E :=
  repeat match type of E with
  | (_ && _)%bool = true =>
      apply andb_prop in E; destruct E as [E ?E]
  end.
Lemma lawR_seg_phseq : forall cols B body,
  lawR_seg cols B = Some body -> phseq body = phseq cols.
Proof.
  intros cols B body H. unfold lawR_seg in H.
  split_last2 H cols.
  destruct ((ga =? 8) && (gaz =? 2) && (gac =? 1)
    && (gb =? 4) && (gbz =? 2) && (1 <=? gbc))%N eqn:E1.
  - injection H as <-. split6 E1.
    repeat match goal with
    | E : (_ =? _)%N = true |- _ => apply N.eqb_eq in E
    end. subst ga gaz gac gb gbz.
    rewrite !phseq_app. destruct (1 <? B)%N; phseq_lits.
  - destruct ((gb =? 8) && (gbz =? 2) && (gbc =? 1))%N eqn:E2;
      [|discriminate].
    injection H as <-. split6 E2.
    repeat match goal with
    | E : (_ =? _)%N = true |- _ => apply N.eqb_eq in E
    end. subst gb gbz gbc.
    rewrite !phseq_app. destruct (1 <? B)%N; phseq_lits.
Qed.
Lemma endR_seg_phseq : forall cols f body,
  endR_seg cols f = Some body -> phseq body = phseq cols.
Proof.
  intros cols f body H. unfold endR_seg in H.
  split_last2 H cols.
  destruct ((ga =? 8) && (gaz =? 2) && (gac =? 1)
    && (gb =? 4) && (gbz =? 2) && (1 <=? gbc) && (2 <=? f))%N eqn:E1.
  - injection H as <-. split6 E1.
    repeat match goal with
    | E : (_ =? _)%N = true |- _ => apply N.eqb_eq in E
    end. subst ga gaz gac gb gbz.
    rewrite !phseq_app. phseq_lits.
  - destruct ((gb =? 8) && (gbz =? 2) && (gbc =? 1)
              && (2 <=? f))%N eqn:E2; [|discriminate].
    injection H as <-. split6 E2.
    repeat match goal with
    | E : (_ =? _)%N = true |- _ => apply N.eqb_eq in E
    end. subst gb gbz gbc.
    rewrite !phseq_app. phseq_lits.
Qed.
Lemma endY_seg_phseq : forall cols y body,
  endY_seg cols y = Some body -> phseq body = phseq cols.
Proof.
  intros cols y body H. unfold endY_seg in H.
  split_last2 H cols.
  destruct ((ga =? 8) && (gaz =? 2) && (gac =? 1)
    && (gb =? 4) && (gbz =? 2) && (1 <=? gbc))%N eqn:E1.
  - injection H as <-. split6 E1.
    repeat match goal with
    | E : (_ =? _)%N = true |- _ => apply N.eqb_eq in E
    end. subst ga gaz gac gb gbz.
    rewrite !phseq_app. phseq_lits.
  - destruct ((gb =? 8) && (gbz =? 2) && (gbc =? 1))%N eqn:E2;
      [|discriminate].
    injection H as <-. split6 E2.
    repeat match goal with
    | E : (_ =? _)%N = true |- _ => apply N.eqb_eq in E
    end. subst gb gbz gbc.
    rewrite !phseq_app. phseq_lits.
Qed.
Lemma jump_seg_phseq : forall cols B body,
  jump_seg cols B = Some body -> phseq body = phseq cols.
Proof.
  intros cols B body H. unfold jump_seg in H.
  split_last2 H cols.
  destruct ((ga =? 8) && (gaz =? 2) && (gac =? 1)
    && (gb =? 4) && (gbz =? 2) && (1 <=? gbc))%N eqn:E1.
  - injection H as <-. split6 E1.
    repeat match goal with
    | E : (_ =? _)%N = true |- _ => apply N.eqb_eq in E
    end. subst ga gaz gac gb gbz.
    rewrite !phseq_app. destruct (1 <? B)%N; phseq_lits.
  - destruct ((gb =? 8) && (gbz =? 2) && (gbc =? 1))%N eqn:E2;
      [|discriminate].
    injection H as <-. split6 E2.
    repeat match goal with
    | E : (_ =? _)%N = true |- _ => apply N.eqb_eq in E
    end. subst gb gbz gbc.
    rewrite !phseq_app. destruct (1 <? B)%N; phseq_lits.
Qed.
Lemma dtb4_conv_phseq : forall body body',
  dtb4_conv body = Some body' -> phseq body' = phseq body.
Proof.
  intros body. induction body as [|[[o z] c] t IH];
    intros body' H; [discriminate|].
  cbn [dtb4_conv] in H.
  destruct (dtb4_conv t) as [t'|] eqn:ED.
  { injection H as <-. cbn [phseq]. rewrite (IH t' eq_refl). reflexivity. }
  lazymatch type of H with
  | (if ?b then _ else _) = _ => destruct b eqn:E8 in H
  end; [|discriminate].
  cbn [gO gZ gC] in E8.
  apply andb_prop in E8 as [E8 Ec].
  apply andb_prop in E8 as [Eo Ez].
  apply N.eqb_eq in Eo, Ez, Ec. subst o z c.
  lazymatch type of H with
  | (if ?b then _ else _) = _ => destruct b eqn:EW in H
  end.
  { injection H as <-. cbn [phseq].
    repeat rewrite phshape_c1. reflexivity. }
  destruct t as [|[[o1 z1] c1] [|[[o2 z2] c2] t2]];
    try discriminate.
  lazymatch type of H with
  | (if ?b then _ else _) = _ => destruct b eqn:EOr in H
  end; [|discriminate].
  apply andb_prop in EOr as [EOr Ec2].
  apply andb_prop in EOr as [EOr Ez2].
  apply andb_prop in EOr as [EOr Eo2].
  apply andb_prop in EOr as [EOr _].
  apply andb_prop in EOr as [Eo1 Ez1].
  apply N.eqb_eq in Eo1, Ez1, Eo2, Ez2, Ec2.
  rewrite Eo1, Ez1, Eo2, Ez2, Ec2 in *.
  destruct t2 as [|[[o3 z3] c3] [|g4 t4]]; try discriminate.
  - injection H as <-. destruct (1 <? c1)%N; phseq_lits.
  - lazymatch type of H with
    | (if ?b then _ else _) = _ => destruct b eqn:E3 in H
    end; [|discriminate].
    apply andb_prop in E3 as [Eo3 Ez3].
    apply N.eqb_eq in Eo3, Ez3. rewrite Eo3, Ez3 in *.
    injection H as <-. destruct (1 <? c1)%N; phseq_lits.
Qed.
Lemma dtb3_conv_phseq : forall body body',
  dtb3_conv body = Some body' -> phseq body' = phseq body.
Proof.
  intros body. induction body as [|[[o z] c] t IH];
    intros body' H; [discriminate|].
  cbn [dtb3_conv] in H.
  destruct (dtb3_conv t) as [t'|] eqn:ED.
  { injection H as <-. cbn [phseq]. rewrite (IH t' eq_refl). reflexivity. }
  lazymatch type of H with
  | (if ?b then _ else _) = _ => destruct b eqn:E8 in H
  end; [|discriminate].
  cbn [gO gZ gC] in E8.
  apply andb_prop in E8 as [E8 Ec].
  apply andb_prop in E8 as [Eo Ez].
  apply N.eqb_eq in Eo, Ez, Ec. subst o z c.
  destruct t as [|[[o1 z1] c1] t1]; [discriminate|].
  lazymatch type of H with
  | (if ?b then _ else _) = _ => destruct b eqn:EOr in H
  end; [|discriminate].
  apply andb_prop in EOr as [EOr _].
  apply andb_prop in EOr as [EOr _].
  apply andb_prop in EOr as [Eo1 Ez1].
  apply N.eqb_eq in Eo1, Ez1. rewrite Eo1, Ez1 in *.
  injection H as <-. phseq_lits.
Qed.
Lemma seek_phseq : forall w cols s,
  seek w = (cols, s) -> phseq w = phseq cols ++ phseq s.
Proof.
  intros w cols s E.
  pose proof (LineageGuard_seek_split w) as H.
  rewrite E in H. cbn [fst snd] in H. subst w. apply phseq_app.
Qed.
Lemma deliver_tick_z1_phseq : forall n w f i o c w' f',
  wat w i = Some (o, 1, c) ->
  deliver_tick (S n) w f i true = ROk w' f' ->
  phseq w' = phseq w.
Proof.
  intros n w f i o c w' f' EW H.
  unfold deliver_tick in H. rewrite EW in H. cbv beta iota in H.
  destruct (2 <=? o)%N; [|discriminate].
  destruct (leaf_act (skipn i w) f) as [[s' f2]|] eqn:EL;
    [|discriminate].
  injection H as <- <-. rewrite phseq_app, (leaf_act_phseq _ _ _ _ EL).
  rewrite <- phseq_app, firstn_skipn. reflexivity.
Qed.
Definition fire_ledger (n : nat) : Prop :=
  forall s f w2 f2,
    fire_comp n s f = Some (w2, f2) -> phseq w2 = phseq s.
Definition renew_ledger (n : nat) : Prop :=
  forall cols s f body f2,
    renew_seg n cols s f = Some (body, f2) ->
    phseq body = phseq cols ++ phseq s.
Ltac collect_ledgers IHf IHr :=
  repeat match goal with
  | E : leaf_act ?s ?f = Some (?s2, ?f2) |- _ =>
      let P := fresh "Pleaf" in
      pose proof (leaf_act_phseq s f s2 f2 E) as P; clear E
  | E : lawR_seg ?cols ?B = Some ?body |- _ =>
      let P := fresh "PlawR" in
      pose proof (lawR_seg_phseq cols B body E) as P; clear E
  | E : endR_seg ?cols ?f = Some ?body |- _ =>
      let P := fresh "PendR" in
      pose proof (endR_seg_phseq cols f body E) as P; clear E
  | E : endY_seg ?cols ?y = Some ?body |- _ =>
      let P := fresh "PendY" in
      pose proof (endY_seg_phseq cols y body E) as P; clear E
  | E : jump_seg ?cols ?B = Some ?body |- _ =>
      let P := fresh "Pjump" in
      pose proof (jump_seg_phseq cols B body E) as P; clear E
  | E : dtb4_conv ?body = Some ?body' |- _ =>
      let P := fresh "Pdtb4" in
      pose proof (dtb4_conv_phseq body body' E) as P; clear E
  | E : dtb3_conv ?body = Some ?body' |- _ =>
      let P := fresh "Pdtb3" in
      pose proof (dtb3_conv_phseq body body' E) as P; clear E
  | E : seek ?w = (?cols, ?s) |- _ =>
      let P := fresh "Pseek" in
      pose proof (seek_phseq w cols s E) as P; clear E
  | E : fire_comp ?n ?s ?f = Some (?s2, ?f2) |- _ =>
      let P := fresh "Pfire" in
      first [ pose proof (IHf s f s2 f2 E) as P
            | pose proof (IHf n s f s2 f2 E) as P ]; clear E
  | E : renew_seg ?n ?cols ?s ?f = Some (?body, ?f2) |- _ =>
      let P := fresh "Prenew" in
      first [ pose proof (IHr cols s f body f2 E) as P
            | pose proof (IHr n cols s f body f2 E) as P ]; clear E
  end.
Ltac split_all_ands :=
  repeat match goal with
  | E : (_ && _)%bool = true |- _ =>
      apply andb_prop in E; destruct E
  end.
Ltac phseq_cleanup :=
  repeat rewrite phseq_app in *;
  cbn [phseq app] in *;
  repeat first
    [ progress rewrite phshape_c1 in *
    | progress rewrite phshape_c0 in *
    | progress rewrite phshape_znot2 in * by reflexivity
    | progress rewrite phshape_onot9 in * by reflexivity ];
  repeat match goal with
  | |- context [phshape (?o, 1, ?c)] =>
      rewrite (phshape_znot2 o 1 c ltac:(reflexivity))
  | H : context [phshape (?o, 1, ?c)] |- _ =>
      rewrite (phshape_znot2 o 1 c ltac:(reflexivity)) in H
  | |- context [phshape (?o, 3, ?c)] =>
      rewrite (phshape_znot2 o 3 c ltac:(reflexivity))
  | H : context [phshape (?o, 3, ?c)] |- _ =>
      rewrite (phshape_znot2 o 3 c ltac:(reflexivity)) in H
  | |- context [phshape (?o, 4, ?c)] =>
      rewrite (phshape_znot2 o 4 c ltac:(reflexivity))
  | H : context [phshape (?o, 4, ?c)] |- _ =>
      rewrite (phshape_znot2 o 4 c ltac:(reflexivity)) in H
  | |- context [phshape (4, ?z, ?c)] =>
      rewrite (phshape_onot9 4 z c ltac:(reflexivity))
  | H : context [phshape (4, ?z, ?c)] |- _ =>
      rewrite (phshape_onot9 4 z c ltac:(reflexivity)) in H
  end;
  repeat rewrite phseq_app in *;
  cbn [phseq app] in *;
  repeat rewrite phshape_c1 in *;
  repeat rewrite phshape_c0 in *;
  cbn [phseq app] in *;
  cbn [app] in *;
  repeat rewrite app_nil_r in *;
  try congruence; try reflexivity.
Ltac close_ledger IHf IHr := collect_ledgers IHf IHr; phseq_cleanup.
Lemma renew_ledger_step : forall n,
  fire_ledger n -> renew_ledger n -> renew_ledger (S n).
Proof.
  intros n IHf IHr. unfold fire_ledger in IHf. unfold renew_ledger in IHr |- *.
  intros cols s f body f2 HRun.
  cbn [renew_seg] in HRun.
  destruct s as [|[[o0 z0] c_0] rest]; [discriminate|].
  destruct o0 as [|o1]; try discriminate.
  destruct o1 as [o1|o1|]; try discriminate.
  destruct o1 as [o1|o1|]; try discriminate.
  destruct o1 as [o1|o1|]; try discriminate.
  destruct z0 as [|z1]; try discriminate.
  destruct z1 as [z1|z1|]; try discriminate.
  destruct z1 as [z1|z1|]; try discriminate.
  destruct c_0 as [|c1]; try discriminate.
  destruct c1 as [c1|c1|]; try discriminate.
  destruct rest as [|[[o5 z5] B] rest2].
  { destruct (endR_seg cols f) as [body0|] eqn:EER;
      [|discriminate].
    injection HRun as <- <-. close_ledger IHf IHr. }
  destruct ((o5 =? 4) && (z5 =? 2) && (1 <=? B))%N eqn:E52.
  2:{ destruct ((z5 =? 3) && (B =? 1)
                && match rest2 with [] => true | _ :: _ => false end
                && (f =? 4) && (1 <=? o5))%N eqn:EREN;
        [|discriminate].
      split6 EREN.
      destruct rest2 as [|g2 r2]; try discriminate.
      cbv beta iota in HRun.
      destruct (endY_seg cols o5) as [body0|] eqn:EEY;
        [|discriminate].
      injection HRun as <- <-.
      repeat match goal with
      | E : (_ =? _)%N = true |- _ => apply N.eqb_eq in E
      end.
      subst z5 B. close_ledger IHf IHr. }
  cbv beta iota in HRun.
  apply andb_prop in E52 as [E52 _].
  apply andb_prop in E52 as [Eo5 Ez5].
  apply N.eqb_eq in Eo5, Ez5. subst o5 z5.
  destruct rest2 as [|gr2 rest2t].
  { destruct (f =? 4)%N.
    - destruct (lawR_seg cols B) as [body0|] eqn:ELR;
        [|discriminate].
      injection HRun as <- <-. close_ledger IHf IHr.
    - destruct (5 <=? f)%N; [|discriminate].
      destruct (jump_seg cols B) as [seg|] eqn:EJP;
        [|discriminate].
      injection HRun as <- <-. close_ledger IHf IHr. }
  destruct (jump_seg cols B) as [seg|] eqn:EJS;
    [|discriminate].
  cbv beta iota in HRun.
  destruct (seek (gr2 :: rest2t)) as [cols2 s3] eqn:ESK2.
  match type of HRun with
  | context [renew_seg ?nn ?cc ?ss ?ff] =>
      destruct (renew_seg nn cc ss ff) as [[body0 f0]|] eqn:ERN2
  end.
  { cbv beta iota in HRun. injection HRun as <- <-.
    close_ledger IHf IHr. }
  cbv beta iota in HRun.
  destruct s3 as [|[[o7 z7] c7] s3t].
  { cbn [leaf_act] in HRun. cbv beta iota in HRun.
    destruct (5 <=? f)%N.
    - injection HRun as <- <-. close_ledger IHf IHr.
    - destruct (f =? 4)%N; [|discriminate].
      match type of HRun with
      | context [dtb4_conv ?w] =>
          destruct (dtb4_conv w) as [cols2'|] eqn:EDC
      end.
      + cbv beta iota in HRun. injection HRun as <- <-.
        close_ledger IHf IHr.
      + cbv beta iota in HRun.
        destruct (forallb w42 cols2); [|discriminate].
        destruct (lawR_seg cols B) as [seg2|] eqn:ELR2;
          [|discriminate].
        injection HRun as <- <-. close_ledger IHf IHr. }
  destruct ((z7 =? 3) && (c7 =? 1))%N eqn:E73.
  { cbv beta iota in HRun.
    match type of HRun with
    | context [fire_comp ?nn ?w ?ff] =>
        destruct (fire_comp nn w ff) as [[s3' f3']|] eqn:EFC3
    end; [|discriminate].
    cbv beta iota in HRun. injection HRun as <- <-.
    close_ledger IHf IHr. }
  cbv beta iota in HRun.
  match type of HRun with
  | context [sand_leaf ?w] => destruct (sand_leaf w)
  end; [cbv beta iota in HRun; discriminate|].
  cbv beta iota in HRun.
  match type of HRun with
  | context [leaf_act ?w ?ff] =>
      destruct (leaf_act w ff) as [[s3' f3']|] eqn:ELA3
  end; [|discriminate].
  cbv beta iota in HRun. injection HRun as <- <-.
  close_ledger IHf IHr.
Qed.
Lemma fire_ledger_step : forall n,
  fire_ledger n -> renew_ledger n -> fire_ledger (S n).
Proof.
  intros n IHf IHr. unfold fire_ledger in IHf |- *. unfold renew_ledger in IHr.
  intros s f w2 f2 HRun.
  cbn [fire_comp] in HRun.
  destruct s as [|[[X z] c] rest0]; [discriminate|].
  destruct z as [|[zp|zp|]]; try discriminate.
  destruct zp as [zp'|zp'|]; try discriminate.
  destruct c as [|[cp|cp|]]; try discriminate.
  destruct (negb (5 <=? X))%N; [discriminate|].
  cbv beta iota in HRun.
  destruct rest0 as [|[[Y zY] cY] rest].
  { destruct (2 <=? f)%N; [|discriminate].
    injection HRun as <- <-. close_ledger IHf IHr. }
  destruct ((Y =? 4) && (zY =? 2))%N eqn:EY4.
  2:{ cbv beta iota in HRun.
      destruct ((Y =? 8) && (zY =? 2) && (cY =? 1))%N eqn:EY8.
      { cbv beta iota zeta in HRun.
        apply andb_prop in EY8 as [EY8 EcY].
        apply andb_prop in EY8 as [EYo EYz].
        apply N.eqb_eq in EYo, EYz, EcY. subst Y zY cY.
        unfold tick_target in HRun. cbn [skipn] in HRun.
        destruct (tick_target_s rest 2%nat) as [i|] eqn:ETT;
          [|discriminate].
        cbv beta iota in HRun.
        match type of HRun with
        | context [wat ?ww ?ii] =>
            destruct (wat ww ii) as [[[og zg] cg]|] eqn:EWC in HRun
        end; [|discriminate].
        cbv beta iota in HRun.
        destruct (zg =? 1)%N eqn:EZ1; [|discriminate].
        apply N.eqb_eq in EZ1. subst zg.
        destruct n as [|n']; [discriminate|].
        match type of HRun with
        | context [deliver_tick ?nn ?ww ?ff ?ii ?vd] =>
            destruct (deliver_tick nn ww ff ii vd)
              as [s3 f3| |] eqn:EDT in HRun
        end; [|discriminate|discriminate].
        cbv beta iota in HRun. injection HRun as <- <-.
        pose proof (deliver_tick_z1_phseq n'
          (((X-1),1,1) :: (11,2,1) :: rest) f i og cg s3 f3
          EWC EDT) as PDT.
        phseq_cleanup. }
      cbv beta iota in HRun.
      destruct rest as [|[[o2 z2] c2] r2].
      { destruct ((zY =? 1) && (cY =? 1) && (1 <=? Y) && true)%N
          eqn:EA1.
        { cbv beta iota in HRun. destruct (2 <=? f)%N; [|discriminate].
          injection HRun as <- <-. split6 EA1.
          repeat match goal with
          | E : (_ =? _)%N = true |- _ => apply N.eqb_eq in E
          end. subst zY cY. close_ledger IHf IHr. }
        cbv beta iota in HRun.
        destruct ((zY =? 3) && (cY =? 1) && (1 <=? Y) && (f =? 4))%N;
          [cbv beta iota in HRun; discriminate|].
        cbv beta iota in HRun.
        destruct ((zY =? 1) && (cY =? 1) && (1 <=? Y) && false)%N
          eqn:EA4; [rewrite andb_false_r in EA4; discriminate|].
        cbv beta iota in HRun.
        destruct ((zY =? 1) && (2 <=? cY) && (2 <=? Y))%N
          eqn:EA5; [|cbv beta iota in HRun; discriminate].
        cbv beta iota in HRun. injection HRun as <- <-.
        split6 EA5.
        repeat match goal with
        | E : (_ =? _)%N = true |- _ => apply N.eqb_eq in E
        end. subst zY. destruct (2 <? cY)%N.
        - close_ledger IHf IHr.
        - close_ledger IHf IHr. }
      destruct ((zY =? 1) && (cY =? 1) && (1 <=? Y) && false)%N
        eqn:EA2; [rewrite andb_false_r in EA2; discriminate|].
      cbv beta iota in HRun.
      destruct ((zY =? 3) && (cY =? 1) && (1 <=? Y) && (f =? 4))%N
        eqn:EA3.
      { cbv beta iota in HRun. destruct r2 as [|g8 r8]; [|discriminate].
        destruct ((o2 =? 4) && (z2 =? 2) && (1 <=? c2))%N
          eqn:E42; [|discriminate].
        injection HRun as <- <-. split6 EA3. split6 E42.
        repeat match goal with
        | E : (_ =? _)%N = true |- _ => apply N.eqb_eq in E
        end. subst zY cY o2 z2.
        destruct (1 <? c2)%N; close_ledger IHf IHr. }
      cbv beta iota in HRun.
      destruct ((zY =? 1) && (cY =? 1) && (1 <=? Y)
                && ((o2 =? 4) && (z2 =? 2) && (1 <=? c2)))%N
        eqn:EA4.
      { cbv beta iota in HRun. injection HRun as <- <-.
        split_all_ands.
        repeat match goal with
        | E : (_ =? _)%N = true |- _ => apply N.eqb_eq in E
        end. subst zY cY o2 z2.
        destruct (1 <? c2)%N; close_ledger IHf IHr. }
      cbv beta iota in HRun.
      destruct ((zY =? 1) && (2 <=? cY) && (2 <=? Y))%N eqn:EA5.
      { cbv beta iota in HRun. injection HRun as <- <-.
        split6 EA5.
        repeat match goal with
        | E : (_ =? _)%N = true |- _ => apply N.eqb_eq in E
        end. subst zY. destruct (2 <? cY)%N.
        - close_ledger IHf IHr.
        - close_ledger IHf IHr. }
      cbv beta iota in HRun.
      destruct ((zY =? 1) && (cY =? 1) && (1 <=? Y)
                && ((z2 =? 1) && (c2 =? 1) && (1 <=? o2)))%N
        eqn:EA6.
      { cbv beta iota in HRun. split_all_ands.
        repeat match goal with
        | E : (_ =? _)%N = true |- _ => apply N.eqb_eq in E
        end. subst zY cY z2 c2.
        destruct (o2 =? 1)%N; injection HRun as <- <-;
          close_ledger IHf IHr. }
      cbv beta iota in HRun.
      destruct ((zY =? 1) && (cY =? 1) && (1 <=? Y)
                && ((z2 =? 2) && (1 <=? o2) && (o2 <=? 3)
                    && (c2 =? 1)))%N eqn:EA7; [|discriminate].
      cbv beta iota in HRun. split_all_ands.
      repeat match goal with
      | E : (_ =? _)%N = true |- _ => apply N.eqb_eq in E
      end. subst zY cY z2 c2.
      destruct (o2 =? 1)%N; injection HRun as <- <-;
        close_ledger IHf IHr. }
  cbv beta iota in HRun.
  destruct (negb (1 <=? cY))%N; [discriminate|].
  cbv beta iota in HRun.
  apply andb_prop in EY4 as [EYo EYz].
  apply N.eqb_eq in EYo, EYz. subst Y zY.
  destruct rest as [|gr1 rest'].
  { destruct (f =? 4)%N.
    - injection HRun as <- <-. destruct (1 <? cY)%N; close_ledger IHf IHr.
    - destruct (5 <=? f)%N; [|discriminate].
      injection HRun as <- <-. destruct (1 <? cY)%N; close_ledger IHf IHr. }
  destruct (seek (gr1 :: rest')) as [cols s2] eqn:ESK.
  cbv beta iota in HRun.
  destruct s2 as [|[[o4 z4] c4] s2t].
  { destruct (5 <=? f)%N.
    - injection HRun as <- <-. close_ledger IHf IHr.
    - destruct (f =? 3)%N.
      + destruct (dtb3_conv ((4,2,cY-1) :: cols))
          as [body0|] eqn:ED3; [|discriminate].
        injection HRun as <- <-. close_ledger IHf IHr.
      + destruct (f =? 4)%N; [|discriminate].
        destruct (dtb4_conv ((4,2,cY-1) :: cols))
          as [body0|] eqn:ED4; [|discriminate].
        injection HRun as <- <-. close_ledger IHf IHr. }
  destruct ((o4 =? 4) && (z4 =? 3) && (c4 =? 1))%N eqn:E43.
  { cbv beta iota in HRun. split6 E43.
    repeat match goal with
    | E : (_ =? _)%N = true |- _ => apply N.eqb_eq in E
    end. subst o4 z4 c4.
    destruct s2t as [|[[o5 z5] B] rest2].
    { destruct (endR_seg cols f) as [seg2|] eqn:EER;
        [|discriminate].
      injection HRun as <- <-. close_ledger IHf IHr. }
    destruct ((o5 =? 4) && (z5 =? 2))%N eqn:E52.
    { cbv beta iota in HRun. destruct (1 <=? B)%N; [|discriminate].
      cbv beta iota in HRun.
      apply andb_prop in E52 as [Eo5 Ez5].
      apply N.eqb_eq in Eo5, Ez5. subst o5 z5.
      destruct rest2 as [|gr2 rest2t].
      { destruct (f =? 4)%N.
        - destruct (lawR_seg cols B) as [seg2|] eqn:ELR;
            [|discriminate].
          injection HRun as <- <-. close_ledger IHf IHr.
        - destruct (5 <=? f)%N; [|discriminate].
          destruct (jump_seg cols B) as [seg2|] eqn:EJP;
            [|discriminate].
          injection HRun as <- <-. close_ledger IHf IHr. }
      destruct (jump_seg cols B) as [seg|] eqn:EJS;
        [|discriminate].
      cbv beta iota in HRun.
      destruct (seek (gr2 :: rest2t)) as [cols2 s3] eqn:ESK2.
      match type of HRun with
      | context [renew_seg ?nn ?cc ?ss ?ff] =>
          destruct (renew_seg nn cc ss ff) as [[body0 f0]|] eqn:ERN2
      end.
      { cbv beta iota in HRun. injection HRun as <- <-.
        close_ledger IHf IHr. }
      cbv beta iota in HRun.
      match type of HRun with
      | context [fire_comp ?nn ?ss ?ff] =>
          destruct (fire_comp nn ss ff) as [[s3' f3']|] eqn:EFC3
      end.
      { cbv beta iota in HRun. injection HRun as <- <-.
        close_ledger IHf IHr. }
      cbv beta iota in HRun.
      destruct (sand_leaf s3
                && forallb (fun g => (gC g =? 0)%N) cols2);
        [discriminate|].
      match type of HRun with
      | context [leaf_act ?ss ?ff] =>
          destruct (leaf_act ss ff) as [[s3' f3']|] eqn:ELA3
      end.
      { cbv beta iota in HRun. injection HRun as <- <-.
        close_ledger IHf IHr. }
      cbv beta iota in HRun.
      destruct s3 as [|g7 s3t]; [|discriminate].
      destruct (5 <=? f)%N.
      { injection HRun as <- <-. close_ledger IHf IHr. }
      destruct (f =? 4)%N; [|discriminate].
      destruct (dtb4_conv cols2) as [cols2'|] eqn:EDC.
      { injection HRun as <- <-. close_ledger IHf IHr. }
      destruct (forallb w42 cols2); [|discriminate].
      destruct (lawR_seg cols B) as [seg2|] eqn:ELR2;
        [|discriminate].
      injection HRun as <- <-. close_ledger IHf IHr. }
    cbv beta iota in HRun.
    destruct ((z5 =? 3) && (B =? 1)
              && match rest2 with [] => true | _ :: _ => false end
              && (f =? 4) && (1 <=? o5))%N eqn:EREN.
    { split6 EREN. destruct rest2 as [|g2 r2]; try discriminate.
      cbv beta iota in HRun.
      destruct (endY_seg cols o5) as [seg2|] eqn:EEY;
        [|discriminate].
      injection HRun as <- <-.
      repeat match goal with
      | E : (_ =? _)%N = true |- _ => apply N.eqb_eq in E
      end. subst z5 B. close_ledger IHf IHr. }
    cbv beta iota in HRun.
    match type of HRun with
    | context [leaf_act ?ss ?ff] =>
        destruct (leaf_act ss ff) as [[s2' f']|] eqn:ELA
    end; [|discriminate].
    cbv beta iota in HRun. injection HRun as <- <-.
    close_ledger IHf IHr. }
  destruct ((o4 =? 4) && (z4 =? 4) && (c4 =? 1))%N eqn:E44.
  { cbv beta iota in HRun. split6 E44.
    repeat match goal with
    | E : (_ =? _)%N = true |- _ => apply N.eqb_eq in E
    end. subst o4 z4 c4.
    destruct s2t as [|[[on zn] cn] t2]; [discriminate|].
    destruct ((on =? 4) && (zn =? 2) && (1 <=? cn))%N
      eqn:ECN; [|discriminate].
    cbv beta iota in HRun. split6 ECN.
    repeat match goal with
    | E : (_ =? _)%N = true |- _ => apply N.eqb_eq in E
    end. subst on zn.
    destruct (jump_seg cols cn) as [seg2|] eqn:EJP;
      [|discriminate].
    injection HRun as <- <-. close_ledger IHf IHr. }
  cbv beta iota in HRun.
  match type of HRun with
  | context [fire_comp ?nn ?ss ?ff] =>
      destruct (fire_comp nn ss ff) as [[s2' f']|] eqn:EFC2
  end.
  { cbv beta iota in HRun. injection HRun as <- <-.
    close_ledger IHf IHr. }
  cbv beta iota in HRun.
  match type of HRun with
  | context [leaf_act ?ss ?ff] =>
      destruct (leaf_act ss ff) as [[s2' f']|] eqn:ELA2
  end; [|discriminate].
  cbv beta iota in HRun. injection HRun as <- <-.
  close_ledger IHf IHr.
Qed.
Lemma fire_renew_phseq : forall n, fire_ledger n /\ renew_ledger n.
Proof.
  induction n as [|n [IHf IHr]].
  - split; unfold fire_ledger, renew_ledger; intros; discriminate.
  - split.
    + exact (fire_ledger_step n IHf IHr).
    + exact (renew_ledger_step n IHf IHr).
Qed.
Corollary fire_comp_phseq : forall n s f w2 f2,
  fire_comp n s f = Some (w2, f2) -> phseq w2 = phseq s.
Proof. intros n. exact (proj1 (fire_renew_phseq n)). Qed.
Corollary renew_seg_phseq : forall n cols s f body f2,
  renew_seg n cols s f = Some (body, f2) ->
  phseq body = phseq cols ++ phseq s.
Proof. intros n. exact (proj2 (fire_renew_phseq n)). Qed.
Lemma jump_comp_phseq : forall pre B post f k body f2,
  jump_comp pre B post f = Some (k, body, f2) ->
  phseq body = phseq pre ++ phseq post.
Proof.
  intros pre B post f k body f2 HRun.
  unfold jump_comp in HRun.
  destruct post as [|g rest].
  { destruct (f =? 4)%N.
    - destruct (lawR_seg pre B) as [body0|] eqn:ELR;
        [|discriminate].
      injection HRun as <- <- <-. close_ledger fire_comp_phseq renew_seg_phseq.
    - destruct (5 <=? f)%N; [|discriminate].
      destruct (jump_seg pre B) as [segp|] eqn:EJS;
        [|discriminate].
      injection HRun as <- <- <-. close_ledger fire_comp_phseq renew_seg_phseq. }
  destruct (jump_seg pre B) as [segp|] eqn:EJS;
    [|discriminate].
  cbv beta iota in HRun.
  destruct (seek (g :: rest)) as [cols2 s3] eqn:ESK.
  destruct (renew_seg (length s3) cols2 s3 f)
    as [[body0 f0]|] eqn:ERN.
  { injection HRun as <- <- <-. close_ledger fire_comp_phseq renew_seg_phseq. }
  destruct s3 as [|[[o7 z7] c7] s3t].
  { cbn [leaf_act] in HRun. cbv beta iota in HRun.
    destruct (5 <=? f)%N.
    - injection HRun as <- <- <-. close_ledger fire_comp_phseq renew_seg_phseq.
    - destruct (f =? 4)%N; [|discriminate].
      destruct (dtb4_conv cols2) as [cols2'|] eqn:EDC.
      + injection HRun as <- <- <-. close_ledger fire_comp_phseq renew_seg_phseq.
      + destruct (forallb w42 cols2); [|discriminate].
        destruct (lawR_seg pre B) as [seg2|] eqn:ELR2;
          [|discriminate].
        injection HRun as <- <- <-. close_ledger fire_comp_phseq renew_seg_phseq. }
  destruct ((z7 =? 3) && (c7 =? 1))%N.
  { match type of HRun with
    | context [fire_comp ?nn ?ss ?ff] =>
        destruct (fire_comp nn ss ff) as [[s3' f3']|] eqn:EFC in HRun
    end.
    - cbv beta iota in HRun.
      injection HRun as <- <- <-.
      close_ledger fire_comp_phseq renew_seg_phseq.
    - cbv beta iota in HRun. discriminate. }
  match type of HRun with
  | context [sand_leaf ?ss] =>
      destruct (sand_leaf ss) eqn:ESand in HRun
  end; [cbv beta iota in HRun; discriminate|].
  cbv beta iota in HRun.
  match type of HRun with
  | context [leaf_act ?ss ?ff] =>
      destruct (leaf_act ss ff) as [[s3' f3']|] eqn:ELA in HRun
  end.
  - cbv beta iota in HRun. injection HRun as <- <- <-.
    close_ledger fire_comp_phseq renew_seg_phseq.
  - cbv beta iota in HRun. discriminate.
Qed.
Lemma jump_comp_kind : forall pre B post f k body f2,
  jump_comp pre B post f = Some (k, body, f2) -> k = JMP.
Proof.
  intros pre B post f k body f2 HRun.
  unfold jump_comp in HRun.
  destruct post as [|g rest].
  - destruct (f =? 4)%N.
    + destruct (lawR_seg pre B);
        [injection HRun as <- <- <-; reflexivity|discriminate].
    + destruct (5 <=? f)%N; [|discriminate].
      destruct (jump_seg pre B);
        [injection HRun as <- <- <-; reflexivity|discriminate].
  - destruct (jump_seg pre B); [|discriminate].
    cbv beta iota in HRun.
    destruct (seek (g :: rest)) as [cols2 s3].
    destruct (renew_seg (length s3) cols2 s3 f) as [[body0 f0]|].
    + injection HRun as <- <- <-; reflexivity.
    + cbv beta iota in HRun.
      lazymatch type of HRun with
      | context [match ?r with Some _ => _ | None => _ end] =>
          destruct r as [[s3' f3']|] eqn:ER in HRun
      end.
      * cbv beta iota in HRun. injection HRun as <- <- <-; reflexivity.
      * cbv beta iota in HRun. destruct s3 as [|g3 t3]; [|discriminate].
        destruct (5 <=? f)%N.
        -- injection HRun as <- <- <-; reflexivity.
        -- destruct (f =? 4)%N; [|discriminate].
           destruct (dtb4_conv cols2).
           ++ injection HRun as <- <- <-; reflexivity.
           ++ destruct (forallb w42 cols2); [|discriminate].
              destruct (lawR_seg pre B);
                [injection HRun as <- <- <-; reflexivity|discriminate].
Qed.
Lemma cut_phseq : forall i w,
  phseq w = phseq (firstn i w) ++ phseq (skipn i w).
Proof.
  intros i w. rewrite <- phseq_app, firstn_skipn. reflexivity.
Qed.
Lemma site_comp_phseq : forall w i f k body f2,
  site_comp w i f = Some (k, body, f2) ->
  phseq body =
    match k with
    | JMP => phseq (firstn i w) ++ phseq (skipn i w)
    | STD => phseq (skipn i w)
    end.
Proof.
  intros w i f k body f2 HRun.
  unfold site_comp in HRun.
  destruct (skipn i w) as [|[[o4 z4] c4] s2t] eqn:ES;
    [discriminate|].
  destruct ((o4 =? 4) && (z4 =? 3) && (c4 =? 1)
            && Nat.leb 3 i)%N eqn:E43.
  { cbv beta iota in HRun. split_all_ands.
    repeat match goal with
    | E : (_ =? _)%N = true |- _ => apply N.eqb_eq in E
    end. subst o4 z4 c4.
    destruct s2t as [|[[o5 z5] b5] rest2].
    - destruct (endR_seg (firstn i w) f) as [body0|] eqn:EER;
        [|discriminate].
      injection HRun as <- <- <-.
      close_ledger fire_comp_phseq renew_seg_phseq.
    - destruct ((o5 =? 4) && (z5 =? 2))%N eqn:E52.
      + cbv beta iota in HRun. destruct (1 <=? b5)%N; [|discriminate].
        apply andb_prop in E52 as [Eo5 Ez5].
        apply N.eqb_eq in Eo5, Ez5. subst o5 z5.
        pose proof (jump_comp_kind (firstn i w) b5 rest2 f
          k body f2 HRun) as HK. subst k.
        pose proof (jump_comp_phseq (firstn i w) b5 rest2 f
          JMP body f2 HRun) as HJ.
        phseq_cleanup.
      + cbv beta iota in HRun.
        destruct ((z5 =? 3) && (b5 =? 1)
                  && match rest2 with [] => true | _ :: _ => false end
                  && (f =? 4) && (1 <=? o5))%N eqn:EREN.
        * split_all_ands. destruct rest2 as [|g2 r2]; try discriminate.
          destruct (endY_seg (firstn i w) o5) as [body0|] eqn:EEY;
            [|discriminate].
          injection HRun as <- <- <-.
          repeat match goal with
          | E : (_ =? _)%N = true |- _ => apply N.eqb_eq in E
          end. subst z5 b5.
          close_ledger fire_comp_phseq renew_seg_phseq.
        * match type of HRun with
          | context [fire_comp ?nn ?ss ?ff] =>
              destruct (fire_comp nn ss ff)
                as [[s' f']|] eqn:EFC in HRun
          end; [|discriminate].
          cbv beta iota in HRun. injection HRun as <- <- <-.
          close_ledger fire_comp_phseq renew_seg_phseq. }
  cbv beta iota in HRun.
  destruct ((z4 =? 3) && (c4 =? 1))%N eqn:E3.
  { match type of HRun with
    | context [fire_comp ?nn ?ss ?ff] =>
        destruct (fire_comp nn ss ff) as [[s' f']|] eqn:EFC in HRun
    end; [|discriminate].
    cbv beta iota in HRun. injection HRun as <- <- <-.
    close_ledger fire_comp_phseq renew_seg_phseq. }
  cbv beta iota in HRun.
  destruct (z4 =? 1)%N eqn:E1.
  { match type of HRun with
    | context [leaf_act ?ss ?ff] =>
        destruct (leaf_act ss ff) as [[s' f']|] eqn:ELA in HRun
    end; [|discriminate].
    cbv beta iota in HRun. injection HRun as <- <- <-.
    close_ledger fire_comp_phseq renew_seg_phseq. }
  cbv beta iota in HRun.
  destruct ((z4 =? 4) && (c4 =? 1))%N eqn:E4; [|discriminate].
  apply andb_prop in E4 as [Ez4 Ec4].
  apply N.eqb_eq in Ez4, Ec4. subst z4 c4.
  destruct s2t as [|[[on zn] cn] t2].
  2:{ destruct ((o4 =? 4) && (on =? 4) && (zn =? 2)
                 && (1 <=? cn))%N eqn:EA.
      - cbv beta iota in HRun. split_all_ands.
        repeat match goal with
        | E : (_ =? _)%N = true |- _ => apply N.eqb_eq in E
        end. subst o4 on zn.
        destruct (last2 (firstn i w))
          as [[[ini [[ga gaz] gac]] [[gb gbz] gbc]]|] eqn:EL;
          [|discriminate].
        pose proof (LineageGuard_last2_split (firstn i w) ini
          (ga,gaz,gac) (gb,gbz,gbc) EL) as EP.
        lazymatch type of HRun with
        | (if ?b then _ else _) = _ => destruct b eqn:EG in HRun
        end; [|discriminate].
        split_all_ands.
        repeat match goal with
        | E : (_ =? _)%N = true |- _ => apply N.eqb_eq in E
        end. subst ga gaz gac gb gbz.
        injection HRun as <- <- <-. rewrite EP.
        destruct (1 <? cn)%N; phseq_cleanup.
      - cbv beta iota in HRun.
        destruct ((4 <? o4) && (on =? 4) && (zn =? 2)
                  && (1 <=? cn))%N eqn:EB; [|discriminate].
        split_all_ands.
        repeat match goal with
        | E : (_ =? _)%N = true |- _ => apply N.eqb_eq in E
        end. subst on zn.
        injection HRun as <- <- <-.
        destruct (1 <? cn)%N; phseq_cleanup. }
  destruct ((o4 =? 4) && (1 <=? f))%N eqn:EO; [|discriminate].
  cbv beta iota in HRun. split_all_ands.
  repeat match goal with
  | E : (_ =? _)%N = true |- _ => apply N.eqb_eq in E
  end. subst o4.
  destruct (last2 (firstn i w))
    as [[[ini [[ga gaz] gac]] [[gb gbz] gbc]]|] eqn:EL;
    [|discriminate].
  pose proof (LineageGuard_last2_split (firstn i w) ini
    (ga,gaz,gac) (gb,gbz,gbc) EL) as EP.
  lazymatch type of HRun with
  | (if ?b then _ else _) = _ => destruct b eqn:EG1 in HRun
  end.
  { split_all_ands.
    repeat match goal with
    | E : (_ =? _)%N = true |- _ => apply N.eqb_eq in E
    end. subst ga gaz gac gb gbz.
    injection HRun as <- <- <-. rewrite EP. phseq_cleanup. }
  lazymatch type of HRun with
  | (if ?b then _ else _) = _ => destruct b eqn:EG2 in HRun
  end; [|discriminate].
  split_all_ands.
  repeat match goal with
  | E : (_ =? _)%N = true |- _ => apply N.eqb_eq in E
  end. subst gb gbz gbc.
  injection HRun as <- <- <-. rewrite EP. phseq_cleanup.
Qed.
Corollary site_comp_jmp_phseq : forall w i f body f2,
  site_comp w i f = Some (JMP, body, f2) ->
  phseq body = phseq w.
Proof.
  intros w i f body f2 H.
  rewrite (site_comp_phseq w i f JMP body f2 H).
  symmetry. apply cut_phseq.
Qed.
Corollary site_comp_std_phseq : forall w i f body f2,
  site_comp w i f = Some (STD, body, f2) ->
  phseq body = phseq (skipn i w).
Proof. intros. exact (site_comp_phseq _ _ _ _ _ _ H). Qed.
Lemma countkey_phseq : forall key w,
  countkey key (phseq w) = countkey key w.
Proof.
  intros key w. induction w as [|g w IH]; [reflexivity|].
  cbn [phseq]. destruct (phshape g) eqn:EP.
  - cbn [countkey]. rewrite EP. cbn [andb]. rewrite IH. reflexivity.
  - cbn [countkey]. rewrite EP. cbn [andb Nat.add]. exact IH.
Qed.
Lemma countkey_phseq_eq : forall key a b,
  phseq a = phseq b ->
  countkey key a = countkey key b.
Proof.
  intros key a b E.
  rewrite <- (countkey_phseq key a), <- (countkey_phseq key b), E.
  reflexivity.
Qed.
Lemma lin_ok_phseq_eq : forall sg a b,
  phseq a = phseq b ->
  lin_ok sg a = lin_ok sg b.
Proof.
  intros sg a b E. unfold lin_ok.
  induction sg as [|s sg IH]; [reflexivity|].
  cbn [forallb]. rewrite IH.
  rewrite (countkey_phseq_eq (sKey s) a b E). reflexivity.
Qed.
Lemma lin_ptags_phseq : forall sg w,
  lin_ptags sg (phseq w) = lin_ptags sg w.
Proof.
  intros sg w. induction w as [|g w IH]; [reflexivity|].
  cbn [phseq]. destruct (phshape g) eqn:EP.
  - cbn [lin_ptags]. rewrite EP. cbn [negb orb]. rewrite IH.
    reflexivity.
  - cbn [lin_ptags]. rewrite EP. cbn [negb orb andb]. exact IH.
Qed.
Lemma lin_ptags_phseq_eq : forall sg a b,
  phseq a = phseq b ->
  lin_ptags sg a = lin_ptags sg b.
Proof.
  intros sg a b E.
  rewrite <- (lin_ptags_phseq sg a), <- (lin_ptags_phseq sg b), E.
  reflexivity.
Qed.
Lemma lin_ok_of_phseq_eq : forall sg src out,
  phseq out = phseq src ->
  lin_ok sg src = true -> lin_ok sg out = true.
Proof.
  intros sg src out E H.
  rewrite (lin_ok_phseq_eq sg out src E). exact H.
Qed.
Lemma lin_ptags_of_phseq_eq : forall sg src out,
  phseq out = phseq src ->
  lin_ptags sg src = true ->
  lin_ptags sg out = true.
Proof.
  intros sg src out E H.
  rewrite (lin_ptags_phseq_eq sg out src E). exact H.
Qed.
Lemma phseq_lin_normalize_full : forall w,
  phseq (lin_normalize_full w) = phseq w.
Proof.
  intros w. induction w as [|[[o1 z1] c1] t IH]; [reflexivity|].
  cbn [lin_normalize_full].
  destruct (lin_normalize_full t) as [|[[o2 z2] c2] r] eqn:E.
  - cbn [phseq] in IH |- *.
    destruct (phshape (o1,z1,c1)); cbn; congruence.
  - cbn [phseq] in IH.
    destruct (tagbase (o1,z1,c1) ||
              tagbase (o2,z2,c2)) eqn:ET.
    + cbn [phseq].
      destruct (phshape (o1,z1,c1)); cbn; congruence.
    + apply orb_false_iff in ET as [ET1 ET2].
      pose proof (phshape_false_of_tagbase_false _ ET1) as EP1.
      pose proof (phshape_false_of_tagbase_false _ ET2) as EP2.
      destruct ((o1 =? o2) && (z1 =? z2))%N eqn:EOZ.
      * apply andb_prop in EOZ as [EO EZ].
        apply N.eqb_eq in EO, EZ. subst o2 z2.
        assert (EPM : phshape (o1,z1,c1+c2) = false).
        { apply phshape_false_of_tagbase_false.
          rewrite (tagbase_c o1 z1 (c1+c2) c1). exact ET1. }
        cbn [phseq]. rewrite EP1, EP2, EPM in *.
        cbn in *. exact IH.
      * cbn [phseq]. rewrite EP1, EP2 in *.
        cbn in *. exact IH.
Qed.
Lemma phseq_lin_normalize_at : forall sg w center,
  phseq (lin_normalize_at sg w center) = phseq w.
Proof.
  intros sg w center. unfold lin_normalize_at.
  destruct (Nat.eqb center O); [reflexivity|].
  cbv beta zeta.
  destruct (lin_nadj_span 6 sg (skipn (center-2) w));
    [reflexivity|].
  rewrite !LineageSplice_lin_split_at_spec. cbn [fst snd].
  rewrite !phseq_app, phseq_lin_normalize_full.
  rewrite <- phseq_app, firstn_skipn.
  rewrite <- phseq_app, firstn_skipn.
  reflexivity.
Qed.
Lemma phseq_lin_normalize_join : forall sg pre sfx,
  phseq (lin_normalize_join sg pre sfx) = phseq (pre ++ sfx).
Proof.
  intros sg pre. induction pre as [|g pre IH]; intros sfx.
  - cbn [lin_normalize_join app].
    rewrite LineageSplice_lin_split_at_spec. cbn [fst snd].
    rewrite !phseq_app, phseq_lin_normalize_full.
    rewrite <- phseq_app, firstn_skipn. reflexivity.
  - destruct pre as [|g1 pre1].
    + cbn [lin_normalize_join app].
      rewrite LineageSplice_lin_split_at_spec. cbn [fst snd].
      rewrite phseq_app, phseq_lin_normalize_full.
      rewrite <- phseq_app. f_equal.
      cbn [app]. rewrite firstn_skipn. reflexivity.
    + destruct pre1 as [|g2 tail].
      * cbn [lin_normalize_join app].
        rewrite LineageSplice_lin_split_at_spec. cbn [fst snd].
        rewrite phseq_app, phseq_lin_normalize_full.
        rewrite <- phseq_app. f_equal.
        cbn [app]. rewrite firstn_skipn. reflexivity.
      * change
          ((if phshape g
            then g :: phseq
                        (lin_normalize_join sg (g1::g2::tail) sfx)
            else phseq
                        (lin_normalize_join sg (g1::g2::tail) sfx)) =
           (if phshape g
            then g :: phseq ((g1::g2::tail) ++ sfx)
            else phseq ((g1::g2::tail) ++ sfx))).
        rewrite IH. reflexivity.
Qed.
Open Scope N_scope.
Open Scope bool_scope.
Opaque LROUND_FUEL LROUND_CHUNKS
       FLAT_ROUND_FUEL CFUEL TRIES.
Definition npack (sg : list seg) (w : word) : Prop :=
  ph_nbrs sg w /\
  (forall g t, w = g :: t -> ph sg g = false).
Lemma npack_lits_tail : forall sg (L t : word),
  (forall g, In g L -> ph sg g = false) ->
  ph_nbrs sg t ->
  (forall g u, t = g :: u -> ph sg g = false) ->
  npack sg (L ++ t).
Proof.
  intros sg L t HL HN Hh. split.
  - apply ph_nbrs_app_join.
    + apply ph_nbrs_phfree. exact HL.
    + exact HN.
    + intros g Hg. exact (HL g (nth_error_In _ _ Hg)).
    + intros g Hg Hph. destruct t as [|g0 u]; [discriminate|].
      cbn [nth_error] in Hg. injection Hg as <-.
      rewrite (Hh g0 u eq_refl) in Hph. discriminate.
  - intros g u E. destruct L as [|g0 L].
    + cbn [app] in E. exact (Hh g u E).
    + cbn [app] in E. injection E as <- _. apply HL. left. reflexivity.
Qed.
Ltac lits_nonph HK :=
  let g := fresh "g" in let Hin := fresh "Hin" in
  intros g Hin;
  repeat (destruct Hin as [<-|Hin]); try (destruct Hin);
  litnp HK.
Lemma leaf_npack_out_tag : forall sg s f s2 f2,
  sg_wf sg -> keys_big sg ->
  ph_margins sg s -> ph_nbrs sg s ->
  leaf_act s f = Some (s2, f2) -> npack sg s2.
Proof.
  intros sg s.
  induction s as [|[[o z] c] t IH]; intros f s2 f2 HW HK HM HN HRun;
    [discriminate|].
  destruct z as [|[zp|zp|]].
  { cbn [leaf_act] in HRun. discriminate. }
  { cbn [leaf_act] in HRun. discriminate. }
  2:{
      cbn [leaf_act] in HRun.
      assert (Hc1 : casc (o,1%N,c) = false)
        by (exact (casc_z1_false o c)).
      assert (Hsp0 : is_spc (o,1%N,c) = false)
        by (exact (noncasc_nonspc _ Hc1)).
      assert (HNt : ph_nbrs sg t)
        by (exact (ph_nbrs_tail _ _ _ HN)).
      assert (Hext : forall g u, t = g :: u -> ph sg g = false)
        by (intros g u ->;
            exact (nbrs_excl sg _ O _ _ HN eq_refl eq_refl
                     Hsp0)).
      destruct (2 <=? c)%N.
      { destruct (2 <=? o)%N; [|discriminate].
        injection HRun as <- <-.
        destruct (2 <? c)%N.
        - apply (npack_lits_tail sg
            [(o,1%N,1%N); ((o-1)%N,1%N,1%N); (o,1%N,(c-2)%N)] t);
            try assumption.
          lits_nonph HK.
        - apply (npack_lits_tail sg
            [(o,1%N,1%N); ((o-1)%N,1%N,1%N)] t);
            try assumption.
          lits_nonph HK. }
      destruct (negb (c =? 1) || negb (2 <=? o))%N; [discriminate|].
      destruct t as [|[[B zb] cb] t2].
      { destruct (2 <=? f)%N.
        { injection HRun as <- <-.
          apply (npack_lits_tail sg [(o,1%N,1%N)] []);
            try apply ph_nbrs_nil;
            try (intros g u E; discriminate E).
          lits_nonph HK. }
        destruct (f =? 1)%N; [|discriminate].
        injection HRun as <- <-. split.
        - apply ph_nbrs_nil.
        - intros g u E. discriminate E. }
      assert (Hnp1 : ph sg (B,zb,cb) = false)
        by (exact (Hext _ _ eq_refl)).
      assert (HNt2 : ph_nbrs sg t2)
        by (exact (ph_nbrs_tail _ _ _ HNt)).
      match type of HRun with
      | (if ?X then _ else _) = _ => destruct X eqn:EG
      end.
      { match type of HRun with
        | (if ?X then _ else _) = _ => destruct X eqn:E5
        end.
        { destruct t2 as [|[[o2 z2] c2] t3]; [discriminate|].
          injection HRun as <- <-.
          apply andb_prop in E5. destruct E5 as [E5a E5b].
          apply andb_prop in E5a. destruct E5a as [EB5 Ecb1].
          apply N.eqb_eq in EB5, Ecb1. subst B cb.
          apply andb_prop in E5b. destruct E5b as [Eo2 Ez2].
          apply N.eqb_eq in Eo2, Ez2. subst o2 z2.
          assert (Hnp2 : ph sg (4%N,2%N,c2) = false)
            by (exact (nbrs_excl sg _ 1%nat _ _ HN
                         eq_refl eq_refl eq_refl)).
          assert (HNt3 : ph_nbrs sg t3)
            by (exact (ph_nbrs_tail _ _ _ HNt2)).
          assert (Hext3 : forall g u, t3 = g :: u ->
                            ph sg g = false)
            by (intros g u ->;
                exact (nbrs_excl sg _ 2%nat _ _ HN
                         eq_refl eq_refl eq_refl)).
          apply (npack_lits_tail sg
            [(o,1%N,1%N); (4%N,2%N,(c2+1)%N)] t3);
            try assumption.
          lits_nonph HK. }
        assert (Hex2 : forall g u, t2 = g :: u ->
                         ph sg g = false).
        { intros g u ->.
          apply andb_prop in EG. destruct EG as [EG _].
          apply andb_prop in EG. destruct EG as [Ezb EB8].
          apply N.eqb_eq in Ezb. subst zb.
          refine (nbrs_excl sg _ 1%nat _ _ HN
                    eq_refl eq_refl _).
          unfold is_spc. cbn [gO gZ gC].
          destruct (B =? 8)%N; [discriminate|]. reflexivity. }
        destruct (B =? 1)%N.
        { destruct (cb =? 1)%N; [|discriminate].
          injection HRun as <- <-.
          apply (npack_lits_tail sg [(o,3%N,1%N)] t2);
            try assumption.
          lits_nonph HK. }
        destruct ((cb =? 1) && (2 <=? B))%N; [|discriminate].
        injection HRun as <- <-.
        apply (npack_lits_tail sg
          [(o,1%N,1%N); ((B-1)%N,zb,1%N)] t2);
          try assumption.
        lits_nonph HK. }
      destruct ((B =? 8) && (zb =? 2) && (cb =? 1))%N eqn:E8.
      { injection HRun as <- <-.
        assert (Hex2 : forall g u, t2 = g :: u ->
                         ph sg g = false)
          by (intros g u ->;
              exact (margins_win_excl sg _ 2%nat O _ _ HM
