Definition zpack (sg : list seg) (w : word) : Prop :=
  nbrs1z sg w /\
  (forall g t, w = g :: t -> ph sg g = false).
Definition zspack (sg : list seg) (w : word) : Prop :=
  mend sg w /\ ph_nbrs sg w /\
  (forall g t, w = g :: t -> ph sg g = false).
Lemma zpack_nil : forall sg, zpack sg [].
Proof.
  intros sg. split.
  - apply nbrs1z_nil.
  - intros g t E. discriminate E.
Qed.
Lemma zpack_lits_app : forall sg A Y,
  (forall g, In g A -> ph sg g = false) ->
  zpack sg Y -> zpack sg (A ++ Y).
Proof.
  intros sg A Y HA (HY & HH). split.
  - exact (nbrs1z_app_lit_l sg A Y HA HY HH).
  - intros g t E. destruct A as [|ga At].
    + cbn [app] in E. exact (HH g t E).
    + cbn [app] in E. injection E as <- _.
      exact (HA ga (or_introl eq_refl)).
Qed.
Lemma zpack_lits : forall sg A,
  (forall g, In g A -> ph sg g = false) -> zpack sg A.
Proof.
  intros sg A HA. rewrite <- (app_nil_r A).
  exact (zpack_lits_app sg A [] HA (zpack_nil sg)).
Qed.
Lemma zpack_app : forall sg X Y,
  zpack sg X -> zpack sg Y -> zpack sg (X ++ Y).
Proof.
  intros sg X Y (HX & HHX) (HY & HHY). split.
  - apply nbrs1z_app_join; [exact HX|exact HY| |].
    + intros g Hg Hph. exfalso.
      destruct (HX _ _ Hg Hph) as ((gr & Hgr & _) & _).
      assert (H1 : (length X - 1 + 1 < length X)%nat)
        by (apply nth_error_Some; rewrite Hgr; discriminate).
      assert (H2 : (length X - 1 < length X)%nat)
        by (apply nth_error_Some; rewrite Hg; discriminate).
      lia.
    + intros g Hg Hph. exfalso.
      destruct Y as [|g0 t]; [discriminate|].
      cbn [nth_error] in Hg. injection Hg as <-.
      rewrite (HHY g0 t eq_refl) in Hph. discriminate.
  - intros g t E. destruct X as [|gx Xt].
    + cbn [app] in E. exact (HHY g t E).
    + cbn [app] in E. injection E as <- _.
      exact (HHX gx Xt eq_refl).
Qed.
Lemma zpack_zspack_app : forall sg X Y,
  zspack sg X -> zpack sg Y -> zpack sg (X ++ Y).
Proof.
  intros sg X Y (HM & HN & HH) (HY & HHY). split.
  - apply nbrs1z_app_join;
      [apply nbrs_nbrs1z; exact HN|exact HY| |].
    + intros g Hg Hph. exfalso.
      assert (HL : (length X - 1 < length X)%nat)
        by (apply nth_error_Some; rewrite Hg; discriminate).
      pose proof (HM _ _ Hg Hph) as HE. lia.
    + intros g Hg Hph. exfalso.
      destruct Y as [|g0 t]; [discriminate|].
      cbn [nth_error] in Hg. injection Hg as <-.
      rewrite (HHY g0 t eq_refl) in Hph. discriminate.
  - intros g t E. destruct X as [|gx Xt].
    + cbn [app] in E. exact (HHY g t E).
    + cbn [app] in E. injection E as <- _.
      exact (HH gx Xt eq_refl).
Qed.
Lemma zpack_zspack : forall sg X, zspack sg X -> zpack sg X.
Proof.
  intros sg X HP. rewrite <- (app_nil_r X).
  exact (zpack_zspack_app sg X [] HP (zpack_nil sg)).
Qed.
Lemma zpack_ini_lits : forall sg ini (a b : bg) L,
  mend sg (ini ++ [a; b]) ->
  ph_nbrs sg (ini ++ [a; b]) ->
  (forall g t, ini ++ [a; b] = g :: t -> ph sg g = false) ->
  (forall g, In g L -> ph sg g = false) ->
  zpack sg (ini ++ L).
Proof.
  intros sg ini a b L HM HN HHd HL.
  assert (HNi : ph_nbrs sg ini)
    by (exact (nbrs_prefix2_mend sg ini a b HM HN)).
  assert (Hil : forall g,
      nth_error ini (length ini - 1) = Some g -> ph sg g = false).
  { intros g Hg. destruct (ph sg g) eqn:E; [|reflexivity].
    exfalso.
    assert (HgL : (length ini - 1 < length ini)%nat)
      by (apply nth_error_Some; rewrite Hg; discriminate).
    assert (Hg' : nth_error (ini ++ [a; b]) (length ini - 1) = Some g)
      by (rewrite nth_error_app1 by lia; exact Hg).
    pose proof (HM _ _ Hg' E) as HE.
    rewrite length_app in HE. cbn [length] in HE. lia. }
  assert (Hih : forall g t, ini = g :: t -> ph sg g = false).
  { intros g t Ei. apply (HHd g (t ++ [a; b])).
    rewrite Ei. cbn [app]. reflexivity. }
  split.
  - apply nbrs1z_app_join.
    + apply nbrs_nbrs1z. exact HNi.
    + apply nbrs_nbrs1z.
      apply ph_nbrs_phfree. exact HL.
    + intros g Hg Hph. rewrite (Hil g Hg) in Hph. discriminate.
    + intros g Hg Hph. exfalso.
      destruct L as [|g0 t]; [discriminate|].
      cbn [nth_error] in Hg. injection Hg as <-.
      rewrite (HL g0 (or_introl eq_refl)) in Hph. discriminate.
  - intros g t E. destruct ini as [|gi it].
    + cbn [app] in E. destruct L as [|g0 t0]; [discriminate|].
      injection E as <- _. exact (HL g0 (or_introl eq_refl)).
    + cbn [app] in E. injection E as <- _.
      exact (Hih gi it eq_refl).
Qed.
Lemma lawR_out_tag : forall sg cols B body,
  keys_big sg -> zspack sg cols ->
  lawR_seg cols B = Some body -> zpack sg body.
Proof.
  intros sg cols B body HK (HM & HN & HHd) HRun.
  unfold lawR_seg in HRun.
  destruct (last2 cols) as [[[ini aa] bb]|] eqn:EL2;
    [|discriminate].
  pose proof (LineageGuard_last2_split cols ini aa bb EL2) as EC.
  subst cols.
  destruct (mend_last2_nonph sg ini aa bb HM) as [Hpa Hpb].
  destruct aa as [[ao az] ac], bb as [[bo bz] bc].
  destruct ((ao =? 8) && (az =? 2) && (ac =? 1)
            && (bo =? 4) && (bz =? 2) && (1 <=? bc))%N eqn:E1.
  { injection HRun as <-.
    destruct (1 <? B)%N.
    - refine (zpack_ini_lits sg ini _ _
        ([(7,1,1); (3,2,1); (4,2,bc); (7,1,1); (3,2,1)]
          ++ [(4,2,B-1)]) HM HN HHd _).
      intros g Hin. cbn [app In] in Hin.
      repeat (destruct Hin as [<-|Hin]); try (destruct Hin);
        litnp HK.
    - refine (zpack_ini_lits sg ini _ _
        ([(7,1,1); (3,2,1); (4,2,bc); (7,1,1); (3,2,1)] ++ [])
        HM HN HHd _).
      intros g Hin. cbn [app In] in Hin.
      repeat (destruct Hin as [<-|Hin]); try (destruct Hin);
        litnp HK. }
  destruct ((bo =? 8) && (bz =? 2) && (bc =? 1))%N;
    [|discriminate].
  injection HRun as <-.
  destruct (1 <? B)%N.
  - refine (zpack_ini_lits sg ini _ _
      ([(ao,az,ac); (7,1,1); (3,2,1); (7,1,1); (3,2,1)]
        ++ [(4,2,B-1)]) HM HN HHd _).
    intros g Hin. cbn [app In] in Hin.
    repeat (destruct Hin as [<-|Hin]); try (destruct Hin);
      first [exact Hpa | litnp HK].
  - refine (zpack_ini_lits sg ini _ _
      ([(ao,az,ac); (7,1,1); (3,2,1); (7,1,1); (3,2,1)] ++ [])
      HM HN HHd _).
    intros g Hin. cbn [app In] in Hin.
    repeat (destruct Hin as [<-|Hin]); try (destruct Hin);
      first [exact Hpa | litnp HK].
Qed.
Lemma endR_out_tag : forall sg cols f body,
  keys_big sg -> zspack sg cols ->
  endR_seg cols f = Some body -> zpack sg body.
Proof.
  intros sg cols f body HK (HM & HN & HHd) HRun.
  unfold endR_seg in HRun.
