Lemma endY_out_tag : forall sg cols y body,
  keys_big sg -> zspack sg cols ->
  endY_seg cols y = Some body -> zpack sg body.
Proof.
  intros sg cols y body HK (HM & HN & HHd) HRun.
  unfold endY_seg in HRun.
  destruct (last2 cols) as [[[ini aa] bb]|] eqn:EL2;
    [|discriminate].
