  subst cols.
  destruct (mend_last2_nonph sg ini aa bb HM) as [Hpa Hpb].
  destruct aa as [[ao az] ac], bb as [[bo bz] bc].
  destruct ((ao =? 8) && (az =? 2) && (ac =? 1)
            && (bo =? 4) && (bz =? 2) && (1 <=? bc))%N.
  { injection HRun as <-.
    refine (zpack_ini_lits sg ini _ _
      [(7,1,1); (3,2,1); (4,2,bc); (y+3,1,1); (6,1,1)]
      HM HN HHd _).
    intros g Hin. repeat (destruct Hin as [<-|Hin]); try (destruct Hin);
      litnp HK. }
  destruct ((bo =? 8) && (bz =? 2) && (bc =? 1))%N;
    [|discriminate].
  injection HRun as <-.
  refine (zpack_ini_lits sg ini _ _
    [(ao,az,ac); (7,1,1); (3,2,1); (y+3,1,1); (6,1,1)]
    HM HN HHd _).
  intros g Hin. repeat (destruct Hin as [<-|Hin]); try (destruct Hin);
    first [exact Hpa | litnp HK].
Qed.
Lemma jump_out_tag : forall sg cols B body,
  keys_big sg -> zspack sg cols ->
  jump_seg cols B = Some body -> zpack sg body.
Proof.
  intros sg cols B body HK (HM & HN & HHd) HRun.
  unfold jump_seg in HRun.
  destruct (last2 cols) as [[[ini aa] bb]|] eqn:EL2;
    [|discriminate].
  pose proof (LineageGuard_last2_split cols ini aa bb EL2) as EC.
  subst cols.
  destruct (mend_last2_nonph sg ini aa bb HM) as [Hpa Hpb].
  destruct aa as [[ao az] ac], bb as [[bo bz] bc].
  destruct ((ao =? 8) && (az =? 2) && (ac =? 1)
            && (bo =? 4) && (bz =? 2) && (1 <=? bc))%N.
  { injection HRun as <-.
    destruct (1 <? B)%N.
    - refine (zpack_ini_lits sg ini _ _
        ([(7,1,1); (3,2,1); (4,2,bc); (8,2,1)] ++ [(4,2,B-1)])
        HM HN HHd _).
      intros g Hin. cbn [app In] in Hin.
      repeat (destruct Hin as [<-|Hin]); try (destruct Hin);
        litnp HK.
    - refine (zpack_ini_lits sg ini _ _
        ([(7,1,1); (3,2,1); (4,2,bc); (8,2,1)] ++ [])
        HM HN HHd _).
      intros g Hin. cbn [app In] in Hin.
      repeat (destruct Hin as [<-|Hin]); try (destruct Hin);
        litnp HK. }
  destruct ((bo =? 8) && (bz =? 2) && (bc =? 1))%N;
    [|discriminate].
  injection HRun as <-.
  destruct (1 <? B)%N.
  - refine (zpack_ini_lits sg ini _ _
      ([(ao,az,ac); (7,1,1); (3,2,1); (8,2,1)] ++ [(4,2,B-1)])
      HM HN HHd _).
    intros g Hin. cbn [app In] in Hin.
    repeat (destruct Hin as [<-|Hin]); try (destruct Hin);
      first [exact Hpa | litnp HK].
  - refine (zpack_ini_lits sg ini _ _
      ([(ao,az,ac); (7,1,1); (3,2,1); (8,2,1)] ++ [])
      HM HN HHd _).
    intros g Hin. cbn [app In] in Hin.
    repeat (destruct Hin as [<-|Hin]); try (destruct Hin);
      first [exact Hpa | litnp HK].
Qed.
Lemma dtb4_out_tag : forall sg body body',
  keys_big sg -> ph_nbrs sg body ->
  dtb4_conv body = Some body' ->
  nbrs1z sg body' /\
  (forall g u, body' = g :: u ->
     (exists t, body = g :: t) \/ g = (7%N,1%N,1%N)).
Proof.
  intros sg body. induction body as [|g t IH];
    intros body' HK HN HRun; [discriminate|].
  cbn [dtb4_conv] in HRun.
  destruct (dtb4_conv t) as [t'|] eqn:ED.
  { injection HRun as <-.
    destruct (IH t' HK (ph_nbrs_tail _ _ _ HN) eq_refl)
      as (HN' & HH'). split.
    - intros p gp Hp Hph. destruct p as [|p'].
      + cbn [nth_error] in Hp. injection Hp as <-.
        destruct (HN O g eq_refl Hph) as ((gr & Hgr & Hsr) & _).
        cbn [nth_error] in Hgr.
        destruct t as [|gt tt]; [discriminate ED|].
        injection Hgr as <-.
        split; [|intros gl Hp1 Hgl; lia].
        destruct t' as [|g0' u'];
          [exfalso; exact (dtb4_ne _ _ ED eq_refl)|].
        destruct (HH' g0' u' eq_refl) as [(tb & Etb)|E7].
        * injection Etb as <- _. exists gt. split; [reflexivity|left; exact Hsr].
        * subst g0'. exists (7,1,1). split; [reflexivity|right; reflexivity].
      + cbn [nth_error] in Hp.
        destruct (HN' p' gp Hp Hph) as ((gr & Hgr & Hsr) & HL).
        split.
        * exists gr. split; [|exact Hsr].
          replace (S p' + 1)%nat with (S (p' + 1)) by lia.
          cbn [nth_error]. exact Hgr.
        * intros gl Hp1 Hgl. destruct p' as [|p''].
          -- cbn [nth_error] in Hgl. injection Hgl as <-.
             destruct t' as [|g0' u'];
               [exfalso; exact (dtb4_ne _ _ ED eq_refl)|].
             cbn [nth_error] in Hp. injection Hp as <-.
             destruct (HH' g0' u' eq_refl) as [(tb & Etb)|E7].
             ++ destruct t as [|gt tt]; [discriminate ED|].
                injection Etb as <- _. destruct (HN 1%nat gt eq_refl Hph)
                  as (_ & HL2). exact (HL2 g ltac:(lia) eq_refl).
             ++ exfalso. subst g0'. unfold ph in Hph.
                rewrite keyi_nonlvl in Hph;
                  [discriminate|reflexivity].
          -- replace (S (S p'') - 1)%nat with (S (S p'' - 1)) in Hgl by lia.
             cbn [nth_error] in Hgl. apply (HL gl); [lia|exact Hgl].
    - intros gg u E. injection E as <- _. left. eexists. reflexivity. }
  match type of HRun with
  | (if ?X then _ else _) = _ => destruct X eqn:E8
  end; [|discriminate HRun].
  assert (Hg8 : ph sg g = false).
  { destruct g as [[go gz] gc].
    cbn [gO gZ gC] in E8.
    apply andb_prop in E8 as [E8 _]. apply andb_prop in E8 as [Ego _].
    apply N.eqb_eq in Ego. subst go. litnp HK. }
  match type of HRun with
  | (if ?X then _ else _) = _ => destruct X eqn:EW
  end.
  { injection HRun as <-.
    assert (Hphf : forall gg, In gg t -> ph sg gg = false)
      by (exact (w42_tail_phfree sg [g] t HN EW)).
    split.
    - intros p gp Hp Hph. exfalso. destruct p as [|[|p'']].
      + cbn [nth_error] in Hp. injection Hp as <-.
        assert (E : ph sg (7,1,1) = false)
          by (litnp HK).
        rewrite E in Hph. discriminate.
      + cbn [nth_error] in Hp. injection Hp as <-.
        assert (E : ph sg (3,2,1) = false)
          by (litnp HK).
        rewrite E in Hph. discriminate.
      + cbn [nth_error] in Hp.
        rewrite (Hphf gp (nth_error_In t _ Hp)) in Hph. discriminate.
    - intros gg u E. injection E as <- _. right. reflexivity. }
  destruct t as [|[[o1 z1] c1] [|[[o2 z2] c2] t2]];
    try discriminate HRun.
  match type of HRun with
  | (if ?X then _ else _) = _ => destruct X eqn:EOr
  end; [|discriminate HRun].
  apply andb_prop in EOr as [EOr Ec21].
  apply andb_prop in EOr as [EOr Ez23].
  apply andb_prop in EOr as [EOr Eo23].
  apply andb_prop in EOr as [EOr E1c1].
  apply andb_prop in EOr as [Eo14 Ez12].
  apply N.eqb_eq in Eo14, Ez12, Eo23, Ez23, Ec21.
  subst o1 z1 o2 z2 c2.
  destruct t2 as [|[[o3 z3] c3] [|g4 t4]]; try discriminate HRun.
  { injection HRun as <-. split.
    - apply nbrs_nbrs1z.
      apply ph_nbrs_phfree. intros gg Hin.
      destruct (1 <? c1)%N; cbn [app In] in Hin;
        repeat (destruct Hin as [<-|Hin]); try (destruct Hin);
        litnp HK.
    - intros gg u E. injection E as <- _. right. reflexivity. }
  match type of HRun with
  | (if ?X then _ else _) = _ => destruct X eqn:E43
  end; [|discriminate HRun].
  injection HRun as <-.
  split.
  - apply nbrs_nbrs1z.
    apply ph_nbrs_phfree. intros gg Hin.
    destruct (1 <? c1)%N; cbn [app In] in Hin;
      repeat (destruct Hin as [<-|Hin]); try (destruct Hin);
      litnp HK.
  - intros gg u E. injection E as <- _. right. reflexivity.
Qed.
Lemma dtb3_out_tag : forall sg body body',
  keys_big sg -> ph_nbrs sg body ->
  dtb3_conv body = Some body' ->
  nbrs1z sg body' /\
  (forall g u, body' = g :: u ->
     (exists t, body = g :: t) \/ g = (7%N,1%N,1%N)).
Proof.
  intros sg body. induction body as [|g t IH];
    intros body' HK HN HRun; [discriminate|].
  cbn [dtb3_conv] in HRun.
  destruct (dtb3_conv t) as [t'|] eqn:ED.
  { injection HRun as <-.
    destruct (IH t' HK (ph_nbrs_tail _ _ _ HN) eq_refl)
      as (HN' & HH'). split.
    - intros p gp Hp Hph. destruct p as [|p'].
      + cbn [nth_error] in Hp. injection Hp as <-.
        destruct (HN O g eq_refl Hph) as ((gr & Hgr & Hsr) & _).
        cbn [nth_error] in Hgr.
        destruct t as [|gt tt]; [discriminate ED|].
        injection Hgr as <-.
        split; [|intros gl Hp1 Hgl; lia].
        destruct t' as [|g0' u'];
          [exfalso; exact (dtb3_ne _ _ ED eq_refl)|].
        destruct (HH' g0' u' eq_refl) as [(tb & Etb)|E7].
        * injection Etb as <- _. exists gt. split; [reflexivity|left; exact Hsr].
        * subst g0'. exists (7,1,1). split; [reflexivity|right; reflexivity].
      + cbn [nth_error] in Hp.
        destruct (HN' p' gp Hp Hph) as ((gr & Hgr & Hsr) & HL).
        split.
        * exists gr. split; [|exact Hsr].
          replace (S p' + 1)%nat with (S (p' + 1)) by lia.
          cbn [nth_error]. exact Hgr.
        * intros gl Hp1 Hgl. destruct p' as [|p''].
          -- cbn [nth_error] in Hgl. injection Hgl as <-.
             destruct t' as [|g0' u'];
               [exfalso; exact (dtb3_ne _ _ ED eq_refl)|].
             cbn [nth_error] in Hp. injection Hp as <-.
             destruct (HH' g0' u' eq_refl) as [(tb & Etb)|E7].
             ++ destruct t as [|gt tt]; [discriminate ED|].
                injection Etb as <- _. destruct (HN 1%nat gt eq_refl Hph)
                  as (_ & HL2). exact (HL2 g ltac:(lia) eq_refl).
             ++ exfalso. subst g0'. unfold ph in Hph.
                rewrite keyi_nonlvl in Hph;
                  [discriminate|reflexivity].
          -- replace (S (S p'') - 1)%nat with (S (S p'' - 1)) in Hgl by lia.
             cbn [nth_error] in Hgl. apply (HL gl); [lia|exact Hgl].
    - intros gg u E. injection E as <- _. left. eexists. reflexivity. }
  match type of HRun with
  | (if ?X then _ else _) = _ => destruct X eqn:E8
  end; [|discriminate HRun].
  destruct t as [|[[o1 z1] c1] t1]; [discriminate HRun|].
  match type of HRun with
  | (if ?X then _ else _) = _ => destruct X eqn:EOr
  end; [|discriminate HRun].
  injection HRun as <-.
  apply andb_prop in EOr as [EOr EW].
  apply andb_prop in EOr as [EOr E1c1].
  apply andb_prop in EOr as [Eo14 Ez12].
  apply N.eqb_eq in Eo14, Ez12. subst o1 z1.
  assert (Hphf : forall gg, In gg t1 -> ph sg gg = false)
    by (exact (w42_tail_phfree sg [g; (4,2,c1)] t1 HN EW)).
  split.
  - apply nbrs_nbrs1z.
    apply ph_nbrs_phfree. intros gg Hin.
    destruct Hin as [<-|Hin]; [litnp HK|].
    destruct Hin as [<-|Hin]; [litnp HK|].
    destruct Hin as [<-|Hin]; [litnp HK|].
    exact (Hphf gg Hin).
  - intros gg u E. injection E as <- _. right. reflexivity.
Qed.
Lemma zpack_of_npack : forall sg w,
  npack sg w -> zpack sg w.
Proof.
  intros sg w (HN & HH). split;
    [exact (nbrs_nbrs1z sg w HN)|exact HH].
Qed.
Lemma zpack_of_head_origin : forall sg src out,
  keys_big sg ->
  (forall g t, src = g :: t -> ph sg g = false) ->
  nbrs1z sg out ->
  (forall g u, out = g :: u ->
     (exists t, src = g :: t) \/ g = (7%N,1%N,1%N)) ->
  zpack sg out.
Proof.
  intros sg src out HK HS HN HH. split; [exact HN|].
  intros g u E. destruct (HH g u E) as [(t & ES)|E7].
  - exact (HS g t ES).
  - subst g. litnp HK.
Qed.
Lemma z1_nonspc : forall o c, is_spc (o,1%N,c) = false.
Proof.
  intros o c. unfold is_spc. cbn [gO gZ gC].
  change ((1 =? 2)%N) with false. rewrite andb_false_r. reflexivity.
Qed.
Lemma fire_renew_out_tag : forall n sg,
  sg_wf sg -> keys_big sg ->
  (forall s f w2 f2,
     ph_margins sg s -> ph_nbrs sg s ->
     fire_comp n s f = Some (w2, f2) -> zpack sg w2)
  /\ (forall cols s f b2 f2,
     zspack sg cols ->
     ph_margins sg s -> ph_nbrs sg s ->
     renew_seg n cols s f = Some (b2, f2) -> zpack sg b2).
Proof.
  induction n as [|n IH]; intros sg HW HK.
  { split; intros; discriminate. }
  pose proof (IH sg HW HK) as (IHf & IHr). split.
  - intros s f w2 f2 HM HN HRun.
    cbn [fire_comp] in HRun.
    destruct s as [|[[X z] c] rest0]; [discriminate|].
    destruct z as [|[zp|zp|]]; try discriminate.
    destruct zp as [zp'|zp'|]; try discriminate.
    destruct c as [|[cp|cp|]]; try discriminate.
    destruct (negb (5 <=? X))%N; [discriminate|].
    cbv beta iota in HRun.
    assert (Hsph : is_spc (X,3,1) = false).
    { unfold is_spc. cbn [gO gZ gC].
      change ((3 =? 2)%N) with false. rewrite andb_false_r.
      reflexivity. }
    assert (Hnch : casc (X,3,1) = false)
      by (exact (z31_noncasc X)).
    destruct rest0 as [|[[Y zY] cY] rest].
    { destruct (2 <=? f)%N; [|discriminate].
      injection HRun as <- <-. apply zpack_lits. lits_nonph HK. }
    assert (Hph1 : ph sg (Y,zY,cY) = false)
      by (exact (nbrs_excl sg _ O _ _ HN eq_refl eq_refl
                   Hsph)).
    destruct ((Y =? 4) && (zY =? 2))%N eqn:EY4.
    2:{ cbv beta iota in HRun.
        destruct ((Y =? 8) && (zY =? 2) && (cY =? 1))%N eqn:EY8.
        { cbv beta iota zeta in HRun.
          apply andb_prop in EY8 as [EY8 EcY1].
          apply andb_prop in EY8 as [EYo8 EYz2].
          apply N.eqb_eq in EYo8, EYz2, EcY1. subst Y zY cY.
          unfold tick_target in HRun. cbn [skipn] in HRun.
          destruct (tick_target_s rest 2%nat) as [i|] eqn:ETT;
            [|discriminate].
          cbv beta iota in HRun.
          destruct (tts_spec rest 2%nat i ETT)
            as (Hi2 & gt & Hgt & Hcgt & Hntgt).
          assert (Hphgt : ph sg gt = false)
            by (exact (notag_ph sg gt Hntgt)).
          assert (EWC : wat
              (((X-1),1,1) :: (11,2,1) :: rest) i = Some gt).
          { unfold wat. replace i with (2 + (i-2))%nat by lia.
            cbn [Nat.add nth_error]. exact Hgt. }
          xrewrite_in HRun EWC. cbv beta iota in HRun.
          destruct gt as [[og zg] cg]. cbn [gZ] in HRun.
          destruct (zg =? 1)%N eqn:EZ1; [|discriminate].
          cbv beta iota in HRun. apply N.eqb_eq in EZ1. subst zg.
          destruct n as [|n']; [discriminate|].
          cbn [deliver_tick] in HRun.
          xrewrite_in HRun EWC. cbv beta iota in HRun.
          change ((1 =? 1)%N) with true in HRun. cbn [andb] in HRun.
          destruct (2 <=? og)%N eqn:EO2.
          2:{ cbv beta iota in HRun.
              change ((3 <=? 1)%N) with false in HRun.
              change ((1 =? 2)%N) with false in HRun.
              cbn [andb orb] in HRun. cbv beta iota in HRun.
              discriminate. }
          cbv beta iota in HRun.
          assert (ESC : skipn i (((X-1),1,1) :: (11,2,1) :: rest)
                        = skipn (i-2)%nat rest).
          { set (m := (i-2)%nat). replace i with (2+m)%nat by lia.
            cbn [Nat.add skipn]. reflexivity. }
          xrewrite_in HRun ESC.
          assert (HMk : ph_margins sg (skipn (i-2) rest)).
          { rewrite (nth_skipn_cons rest (i-2)%nat
                       (og,1,cg) Hgt).
            assert (HEq3 : (X,3,1) :: (8,2,1) :: rest
                = ((X,3,1) :: (8,2,1) :: firstn (i-2) rest)
                    ++ (og,1,cg) :: skipn (S (i-2)) rest).
            { cbn [app]. f_equal. f_equal.
              transitivity (firstn (i-2) rest ++ skipn (i-2) rest).
              { symmetry. apply firstn_skipn. }
              f_equal. exact (nth_skipn_cons rest (i-2)%nat
                                (og,1,cg) Hgt). }
            exact (margins_cut_at sg _ _ _ _ HM HEq3
                     Hcgt Hntgt). }
          assert (HNk : ph_nbrs sg (skipn (i-2) rest)).
          { rewrite (nth_skipn_cons rest (i-2)%nat
                       (og,1,cg) Hgt).
            assert (HEq3 : (X,3,1) :: (8,2,1) :: rest
                = ((X,3,1) :: (8,2,1) :: firstn (i-2) rest)
                    ++ (og,1,cg) :: skipn (S (i-2)) rest).
            { cbn [app]. f_equal. f_equal.
              transitivity (firstn (i-2) rest ++ skipn (i-2) rest).
              { symmetry. apply firstn_skipn. }
              f_equal. exact (nth_skipn_cons rest (i-2)%nat
                                (og,1,cg) Hgt). }
            exact (ph_nbrs_app_r sg _ _
                    (ph_nbrs_at_eq sg _ _ HN HEq3)). }
          match type of HRun with
          | context [leaf_act ?w ?ff] =>
              destruct (leaf_act w ff) as [[s' f']|] eqn:ELA4
          end.
          2:{ cbv beta iota in HRun. discriminate. }
          cbv beta iota in HRun. injection HRun as <- <-.
          assert (ESF : forall (A B : bg),
              firstn i (A :: B :: rest) = A :: B :: firstn (i-2) rest).
          { intros A B. set (m := (i-2)%nat).
            replace i with (2+m)%nat by lia. cbn [Nat.add firstn].
            reflexivity. }
          rewrite ESF.
          apply (zpack_lits_app sg [((X-1),1,1); (11,2,1)]).
          { lits_nonph HK. }
          apply zpack_app.
          { apply zpack_zspack. split; [|split].
            - intros p g Hp Hph.
              assert (HpL : (p < length (firstn (i-2) rest))%nat)
                by (apply nth_error_Some; rewrite Hp; discriminate).
              rewrite length_firstn in HpL.
              assert (HtL : (i-2 < length rest)%nat)
                by (apply nth_error_Some; rewrite Hgt; discriminate).
              rewrite length_firstn.
              destruct (PeanoNat.Nat.lt_ge_cases (p+3) (i-2))
                as [Hlt|Hge]; [lia|]. exfalso.
              assert (Hp' : nth_error rest p = Some g).
              { rewrite <- (firstn_skipn (i-2) rest).
                rewrite nth_error_app1 by (rewrite length_firstn; lia).
                exact Hp. }
              assert (Hps : nth_error ((X,3,1)::(8,2,1)::rest)
                                      (S (S p)) = Some g)
                by (cbn [nth_error]; exact Hp').
              destruct (HM _ _ Hps Hph) as (_ & _ & HWn).
              destruct (HWn (S (S (i-2)))
                          ltac:(unfold GUARD; lia)
                          ltac:(unfold GUARD; lia) ltac:(lia))
                as (g' & Hg' & Hc' & _).
              cbn [nth_error] in Hg'. rewrite Hgt in Hg'.
              injection Hg' as <-. congruence.
            - intros p g Hp Hph.
              assert (HpL : (p < length (firstn (i-2) rest))%nat)
                by (apply nth_error_Some; rewrite Hp; discriminate).
              rewrite length_firstn in HpL.
              assert (HtL : (i-2 < length rest)%nat)
                by (apply nth_error_Some; rewrite Hgt; discriminate).
              assert (Hp' : nth_error rest p = Some g).
              { rewrite <- (firstn_skipn (i-2) rest).
                rewrite nth_error_app1 by (rewrite length_firstn; lia).
                exact Hp. }
              assert (HNrest : ph_nbrs sg rest)
                by (exact (ph_nbrs_tail sg _ _
                            (ph_nbrs_tail sg _ _ HN))).
              destruct (HNrest p g Hp' Hph) as ((gr & Hgr & Hsr) & HL).
              assert (HpNL : (p+1 < i-2)%nat).
              { destruct (PeanoNat.Nat.lt_ge_cases (p+1) (i-2));
                  [assumption|]. exfalso.
                assert (Hpe : (p + 1 = i - 2)%nat) by lia.
                rewrite Hpe, Hgt in Hgr. injection Hgr as <-.
                unfold is_spc in Hsr.
                cbn [gO gZ gC] in Hsr.
                change ((1 =? 2)%N) with false in Hsr.
                rewrite andb_false_r in Hsr. cbn [andb] in Hsr.
                discriminate Hsr. }
              split.
              + exists gr. split; [|exact Hsr].
                rewrite <- (firstn_skipn (i-2) rest) in Hgr.
                rewrite nth_error_app1 in Hgr
                  by (rewrite length_firstn; lia). exact Hgr.
              + intros gl Hp1 Hgl. apply (HL gl); [exact Hp1|].
                rewrite <- (firstn_skipn (i-2) rest).
                rewrite nth_error_app1 by (rewrite length_firstn; lia).
                exact Hgl.
            - intros g u E.
              destruct (ph sg g) eqn:EP; [|reflexivity].
              exfalso.
              assert (Hg0 : nth_error rest O = Some g).
              { rewrite <- (firstn_skipn (i-2) rest).
                destruct (firstn (i-2) rest) as [|f0 ft];
                  [discriminate E|]. injection E as <- _. reflexivity. }
              assert (Hg0s : nth_error ((X,3,1)::(8,2,1)::rest) 2
                              = Some g) by (cbn [nth_error]; exact Hg0).
              destruct (HM _ _ Hg0s EP) as (H3 & _ & _).
              unfold GUARD in H3. lia. }
          exact (zpack_of_npack sg s'
            (leaf_npack_out_tag sg _ f s' f' HW HK HMk HNk ELA4)). }
        cbv beta iota in HRun.
        assert (Hsph1 : is_spc (Y,zY,cY) = false ->
            forall g u, rest = g :: u -> ph sg g = false).
        { intros Hsp g u ->.
          exact (nbrs_excl sg _ 1%nat _ _ HN eq_refl
                   eq_refl Hsp). }
        assert (HTrest : zpack sg rest).
        { apply zpack_zspack. split; [|split].
          - exact (mend_tail_word sg
                     ((X,3,1)::(Y,zY,cY)::[]) rest HM).
          - exact (ph_nbrs_tail sg _ _
                    (ph_nbrs_tail sg _ _ HN)).
          - intros g u E. destruct (ph sg g) eqn:EP;
              [|reflexivity]. exfalso.
            assert (Hg0 : nth_error ((X,3,1)::(Y,zY,cY)::rest) 2
                          = Some g) by (rewrite E; reflexivity).
            destruct (HM _ _ Hg0 EP) as (H3 & _ & _).
            unfold GUARD in H3. lia. }
        destruct rest as [|[[o2 z2] c2] r2].
        { destruct ((zY =? 1) && (cY =? 1) && (1 <=? Y) && true)%N.
          { cbv beta iota in HRun. destruct (2 <=? f)%N; [|discriminate].
