      - intros g u E. subst t2.
        exact (nbrs_excl sg _ 1%nat _ _ HN2 eq_refl
                 eq_refl eq_refl). }
    cbv beta iota in HRun.
    match type of HRun with
    | context [fire_comp ?nn ?w ?ff] =>
        destruct (fire_comp nn w ff) as [[s2' f']|] eqn:EFC2
    end.
    { cbv beta iota in HRun. injection HRun as <- <-.
      apply (zpack_lits_app sg [((X-1),1,1);(7,2,1);(4,2,cY-1)]);
        [lits_nonph HK|].
      apply (zpack_zspack_app sg cols s2' HPc).
      exact (IHf _ f s2' f' HM2 HN2 EFC2). }
    cbv beta iota in HRun.
    match type of HRun with
    | context [leaf_act ?w ?ff] =>
        destruct (leaf_act w ff) as [[s2' f']|] eqn:ELA2
    end.
    2:{ cbv beta iota in HRun. discriminate. }
    cbv beta iota in HRun. injection HRun as <- <-.
    apply (zpack_lits_app sg [((X-1),1,1);(7,2,1);(4,2,cY-1)]);
      [lits_nonph HK|].
    apply (zpack_zspack_app sg cols s2' HPc).
    exact (zpack_of_npack sg s2'
      (leaf_npack_out_tag sg _ f s2' f' HW HK HM2 HN2 ELA2)).
  - intros cols s f b2 f2 HPc HM HN HRun.
    cbn [renew_seg] in HRun.
    destruct s as [|[[o0 z0] c_0] rest]; [discriminate|].
    destruct o0 as [|o1]; try discriminate.
    destruct o1 as [o1|o1|]; try discriminate.
    destruct o1 as [o1|o1|]; try discriminate.
    destruct o1 as [o1|o1|]; try discriminate.
    destruct z0 as [|z1]; try discriminate.
    destruct z1 as [z1|z1|]; try discriminate.
    destruct z1 as [z1|z1|]; try discriminate.
    destruct c_0 as [|c1]; try discriminate.
    destruct c1 as [c1|c1|]; try discriminate.
    assert (Hsph : is_spc (4,3,1) = false) by reflexivity.
    destruct rest as [|[[o5 z5] B] rest2].
    { destruct (endR_seg cols f) as [body|] eqn:EER;
        [|discriminate]. injection HRun as <- <-.
      exact (endR_out_tag sg cols f body HK HPc EER). }
    assert (Hph5 : ph sg (o5,z5,B) = false)
      by (exact (nbrs_excl sg _ O _ _ HN eq_refl
                   eq_refl Hsph)).
    destruct ((o5 =? 4) && (z5 =? 2) && (1 <=? B))%N eqn:E52;
      [|destruct ((z5 =? 3) && (B =? 1)
                  && match rest2 with [] => true | _::_ => false end
                  && (f =? 4) && (1 <=? o5))%N eqn:EREN;
        [|discriminate]].
    2:{ cbv beta iota in HRun.
        destruct (endY_seg cols o5) as [body|] eqn:EEY;
          [|discriminate]. injection HRun as <- <-.
        exact (endY_out_tag sg cols o5 body HK HPc EEY). }
    cbv beta iota in HRun.
    apply andb_prop in E52 as [E52 E1B].
    apply andb_prop in E52 as [E5o E5z].
    apply N.eqb_eq in E5o, E5z. subst o5 z5.
    destruct rest2 as [|gr2 rest2t].
    { destruct (f =? 4)%N.
      { destruct (lawR_seg cols B) as [body|] eqn:ELR;
          [|discriminate]. injection HRun as <- <-.
        exact (lawR_out_tag sg cols B body HK HPc ELR). }
      destruct (5 <=? f)%N; [|discriminate].
      destruct (jump_seg cols B) as [seg|] eqn:EJP;
        [|discriminate]. injection HRun as <- <-.
      apply zpack_app; [exact (jump_out_tag sg cols B seg HK HPc EJP)|].
      apply zpack_lits. lits_nonph HK. }
    destruct (jump_seg cols B) as [seg|] eqn:EJS;
      [|discriminate]. cbv beta iota in HRun.
    destruct (seek (gr2::rest2t)) as [cols2 s3] eqn:ESK2.
    pose proof (LineageGuard_seek_split (gr2::rest2t)) as HSPL2.
    rewrite ESK2 in HSPL2. cbn [fst snd] in HSPL2.
    assert (HNr2 : ph_nbrs sg (gr2::rest2t))
      by (exact (ph_nbrs_tail sg _ _
                  (ph_nbrs_tail sg _ _ HN))).
    assert (HMEc2 : mend sg cols2).
    { pose proof (mend_seek sg
                    ((4,3,1)::(4,2,B)::[]) (gr2::rest2t) HM) as H0.
      rewrite ESK2 in H0. exact H0. }
    assert (HNc2 : ph_nbrs sg cols2).
    { pose proof (ph_nbrs_seek_fst sg (gr2::rest2t) HNr2)
        as H0. rewrite ESK2 in H0. exact H0. }
    assert (HHc2 : forall g u, cols2=g::u -> ph sg g=false).
    { intros g u E. assert (Hg2 : gr2 = g).
      { rewrite E in HSPL2. cbn [app] in HSPL2.
        injection HSPL2 as <- _. reflexivity. }
      subst gr2. exact (nbrs_excl sg _ 1%nat _ _ HN
                         eq_refl eq_refl eq_refl). }
    assert (HPc2 : zspack sg cols2)
      by (exact (conj HMEc2 (conj HNc2 HHc2))).
    assert (HM3 : ph_margins sg s3).
    { destruct s3 as [|g7 s3t].
      { intros p g Hp Hph. destruct p; discriminate. }
      assert (Hst7 : seektest g7 = false)
        by (apply (seek_snd_head (gr2::rest2t) g7 s3t);
            rewrite ESK2; reflexivity).
      assert (Hnc7 : casc g7 = false)
        by (exact (seektest_noncasc _ Hst7)).
      assert (HEq3 : (4,3,1)::(4,2,B)::gr2::rest2t
          = ((4,3,1)::(4,2,B)::cols2) ++ g7::s3t)
        by (cbn [app]; f_equal; f_equal; exact HSPL2).
      exact (margins_cut_at sg _ _ _ _ HM HEq3 Hnc7
               (seektest_notag _ Hst7)). }
    assert (HN3 : ph_nbrs sg s3)
      by (exact (ph_nbrs_app_r sg cols2 s3
                  (ph_nbrs_at_eq sg _ _ HNr2 HSPL2))).
    assert (HJ : zpack sg seg)
      by (exact (jump_out_tag sg cols B seg HK HPc EJS)).
    match type of HRun with
    | context [renew_seg ?nn ?cc ?ss ?ff] =>
        destruct (renew_seg nn cc ss ff) as [[body f']|] eqn:ERN2
    end.
    { cbv beta iota in HRun. injection HRun as <- <-.
      apply zpack_app; [exact HJ|exact (IHr cols2 s3 f body f' HPc2 HM3 HN3 ERN2)]. }
    cbv beta iota in HRun.
    destruct s3 as [|[[o7 z7] c7] s3t].
    { cbn [leaf_act] in HRun. cbv beta iota in HRun.
      destruct (5 <=? f)%N.
      { injection HRun as <- <-. apply zpack_app; [exact HJ|].
        apply (zpack_zspack_app sg cols2 [(f-1,1,1)] HPc2).
        apply zpack_lits. lits_nonph HK. }
      destruct (f =? 4)%N; [|discriminate].
      match type of HRun with
      | context [dtb4_conv ?w] =>
          destruct (dtb4_conv w) as [cols2'|] eqn:EDC
      end.
      2:{ cbv beta iota in HRun. destruct (forallb w42 cols2);
            [|discriminate].
          destruct (lawR_seg cols B) as [seg2|] eqn:ELR2;
            [|discriminate]. injection HRun as <- <-.
          apply zpack_app.
          - exact (lawR_out_tag sg cols B seg2 HK HPc ELR2).
          - exact (zpack_zspack sg cols2 HPc2). }
      cbv beta iota in HRun. injection HRun as <- <-.
      destruct (dtb4_out_tag sg cols2 cols2' HK HNc2 EDC)
        as (HD1 & HD3).
      apply zpack_app; [exact HJ|].
      exact (zpack_of_head_origin sg cols2 cols2' HK HHc2 HD1 HD3). }
    destruct ((z7 =? 3) && (c7 =? 1))%N eqn:E73.
    { cbv beta iota in HRun.
      match type of HRun with
      | context [fire_comp ?nn ?w ?ff] =>
          destruct (fire_comp nn w ff) as [[s3' f3']|] eqn:EFC3
      end.
      { cbv beta iota in HRun. injection HRun as <- <-.
        apply zpack_app; [exact HJ|].
        apply (zpack_zspack_app sg cols2 s3' HPc2).
        exact (IHf _ f s3' f3' HM3 HN3 EFC3). }
      cbv beta iota in HRun. discriminate. }
    cbv beta iota in HRun.
    match type of HRun with
    | context [sand_leaf ?w] => destruct (sand_leaf w)
    end; [cbv beta iota in HRun; discriminate|].
    cbv beta iota in HRun.
    match type of HRun with
    | context [leaf_act ?w ?ff] =>
        destruct (leaf_act w ff) as [[s3' f3']|] eqn:ELA3
    end.
    2:{ cbv beta iota in HRun. discriminate. }
    cbv beta iota in HRun. injection HRun as <- <-.
    apply zpack_app; [exact HJ|].
    apply (zpack_zspack_app sg cols2 s3' HPc2).
    exact (zpack_of_npack sg s3'
      (leaf_npack_out_tag sg _ f s3' f3' HW HK HM3 HN3 ELA3)).
Qed.
Lemma round_at_out_tag : forall sg cols s f t2 f2,
  sg_wf sg -> keys_big sg ->
  zspack sg cols ->
  ph_margins sg s -> ph_nbrs sg s ->
  round_at cols s f = Some (t2, f2) -> zpack sg t2.
Proof.
  intros sg cols s f t2 f2 HW HK HPc HM HN HRun.
  unfold round_at in HRun.
  destruct s as [|[[og zg] cg] t].
  { cbn [leaf_act] in HRun. discriminate. }
  destruct zg as [|[z1|z1|]].
  { match type of HRun with
    | context [leaf_act ?w ?ff] =>
        destruct (leaf_act w ff) as [[s2 g2]|] eqn:ELA
    end;
    [ cbv beta iota in HRun; injection HRun as <- <-;
      apply (zpack_zspack_app sg cols s2 HPc);
      exact (zpack_of_npack sg s2
        (leaf_npack_out_tag sg _ f s2 g2 HW HK HM HN ELA))
    | cbv beta iota in HRun; discriminate ]. }
  2:{ match type of HRun with
    | context [leaf_act ?w ?ff] =>
        destruct (leaf_act w ff) as [[s2 g2]|] eqn:ELA
    end;
    [ cbv beta iota in HRun; injection HRun as <- <-;
      apply (zpack_zspack_app sg cols s2 HPc);
      exact (zpack_of_npack sg s2
        (leaf_npack_out_tag sg _ f s2 g2 HW HK HM HN ELA))
    | cbv beta iota in HRun; discriminate ]. }
  2:{ match type of HRun with
    | context [leaf_act ?w ?ff] =>
        destruct (leaf_act w ff) as [[s2 g2]|] eqn:ELA
    end;
    [ cbv beta iota in HRun; injection HRun as <- <-;
      apply (zpack_zspack_app sg cols s2 HPc);
      exact (zpack_of_npack sg s2
        (leaf_npack_out_tag sg _ f s2 g2 HW HK HM HN ELA))
    | cbv beta iota in HRun; discriminate ]. }
  destruct z1 as [z1|z1|].
  1,2: match type of HRun with
    | context [leaf_act ?w ?ff] =>
        destruct (leaf_act w ff) as [[s2 g2]|] eqn:ELA
    end;
    [ cbv beta iota in HRun; injection HRun as <- <-;
      apply (zpack_zspack_app sg cols s2 HPc);
      exact (zpack_of_npack sg s2
        (leaf_npack_out_tag sg _ f s2 g2 HW HK HM HN ELA))
    | cbv beta iota in HRun; discriminate ].
  destruct cg as [|[c1|c1|]].
  1,2,3: match type of HRun with
    | context [leaf_act ?w ?ff] =>
        destruct (leaf_act w ff) as [[s2 g2]|] eqn:ELA
    end;
    [ cbv beta iota in HRun; injection HRun as <- <-;
      apply (zpack_zspack_app sg cols s2 HPc);
      exact (zpack_of_npack sg s2
        (leaf_npack_out_tag sg _ f s2 g2 HW HK HM HN ELA))
    | cbv beta iota in HRun; discriminate ].
  match type of HRun with
  | context [renew_seg ?nn ?cc ?ss ?ff] =>
      destruct (renew_seg nn cc ss ff) as [[body g2]|] eqn:ERN
  end.
  { cbv beta iota in HRun. injection HRun as <- <-.
    exact (proj2 (fire_renew_out_tag _ sg HW HK)
             cols _ f body g2 HPc HM HN ERN). }
  cbv beta iota in HRun.
  match type of HRun with
  | context [fire_comp ?nn ?w ?ff] =>
      destruct (fire_comp nn w ff) as [[s2 g2]|] eqn:EFC
  end.
  2:{ cbv beta iota in HRun. discriminate. }
  cbv beta iota in HRun. injection HRun as <- <-.
  apply (zpack_zspack_app sg cols s2 HPc).
  exact (proj1 (fire_renew_out_tag _ sg HW HK)
           _ f s2 g2 HM HN EFC).
Qed.
Lemma round2g_flat_at_tag : forall sg pfx tail f,
  sg_wf sg -> keys_big sg ->
  sg_live sg ->
  ph_margins sg (pfx ++ tail) ->
  ph_nbrs sg (pfx ++ tail) ->
  (forall g, nth_error tail O = Some g -> ph sg g = false) ->
  round2g (lin_flat sg tail) f
  = flat_res sg (round2g tail f).
Proof.
  intros sg pfx tail f HW HK HL HMo HNo Hhd.
  assert (HN : ph_nbrs sg tail)
    by (exact (ph_nbrs_app_r sg pfx tail HNo)).
  unfold round2g.
  rewrite (seek_flat sg tail HW).
  destruct (seek tail) as [cols s] eqn:ESK.
  cbn [fst snd].
  pose proof (LineageGuard_seek_split tail) as HSP.
  rewrite ESK in HSP. cbn [fst snd] in HSP.
  assert (HPn : ph_notlast sg cols).
  { pose proof (ph_notlast_seek sg tail HN) as H0.
    rewrite ESK in H0. cbn [fst] in H0. exact H0. }
  assert (HMs : ph_margins sg s).
  { destruct s as [|g7 s3t].
    { intros p g Hp Hph. destruct p; discriminate. }
    assert (Hst7 : seektest g7 = false)
      by (apply (seek_snd_head tail g7 s3t);
          rewrite ESK; reflexivity).
    assert (HEq : pfx ++ tail = (pfx ++ cols) ++ g7 :: s3t)
      by (rewrite <- app_assoc; f_equal; exact HSP).
    exact (margins_cut_at sg _ _ _ _ HMo HEq
             (seektest_noncasc _ Hst7)
             (seektest_notag _ Hst7)). }
  assert (HNs : ph_nbrs sg s)
    by (exact (ph_nbrs_app_r sg cols s
                (ph_nbrs_at_eq sg _ _ HN HSP))).
  assert (HHs : forall g u, s = g :: u -> ph sg g = false).
  { intros g u E. subst s.
    assert (Hst : seektest g = false)
      by (apply (seek_snd_head tail g u);
          rewrite ESK; reflexivity).
    destruct (ph sg g) eqn:Hph; [|reflexivity].
    rewrite (ph_seektest sg g Hph) in Hst.
    discriminate. }
  rewrite (round_at_flat_z sg cols s f HW HK HL
             (fun t' _ => HPn) (nbrs_nbrs1z _ _ HNs) HHs).
  destruct (round_at cols s f) as [[t2 f2]|] eqn:ERA;
    [|reflexivity].
  cbn [flat_res]. cbv beta iota.
  assert (HPcols : zspack sg cols).
  { split; [|split].
    - pose proof (mend_seek sg pfx tail HMo) as H0.
      rewrite ESK in H0. cbn [fst] in H0. exact H0.
    - pose proof (ph_nbrs_seek_fst sg tail HN) as H0.
      rewrite ESK in H0. cbn [fst] in H0. exact H0.
    - intros g u E. apply Hhd.
      rewrite HSP, E. reflexivity. }
  destruct (round_at_out_tag sg cols s f t2 f2 HW HK HPcols HMs HNs ERA)
    as (HT1z & HTh).
  rewrite (seek_flat sg t2 HW).
  destruct (seek t2) as [cols2 s2] eqn:ESK2.
  cbn [fst snd].
  pose proof (LineageGuard_seek_split t2) as HSP2.
  rewrite ESK2 in HSP2. cbn [fst snd] in HSP2.
  destruct s2 as [|[[o7 z7] c7] s2t].
  { flatnil.
    assert (HNc2 : ph_nbrs sg cols2).
    { pose proof (nbrs1z_seek_all sg t2 HT1z
                    ltac:(rewrite ESK2; reflexivity)) as H0.
      rewrite ESK2 in H0. cbn [fst] in H0. exact H0. }
    destruct (f2 =? 4)%N.
    { pose proof (dtb4_conv_flat sg cols2 HW HK HNc2) as ED.
      xrewrite ED.
      destruct (dtb4_conv cols2) as [cols2'|] eqn:EDC;
        repeat (xrewrite EDC);
        cbn [flat_res]; reflexivity. }
    destruct (5 <=? f2)%N; [|reflexivity].
    cbn [flat_res]. f_equal. f_equal.
    rewrite lin_flat_app_c. f_equal.
    flatlit. reflexivity. }
  assert (HN2z : nbrs1z sg ((o7,z7,c7) :: s2t))
    by (exact (nbrs1z_app_r sg cols2 _
                (nbrs1z_at_eq sg _ _ HT1z HSP2))).
  assert (Hh2 : forall g u, (o7,z7,c7) :: s2t = g :: u ->
                  ph sg g = false).
  { intros g u E. injection E as E1 E2. subst g.
    exact (nbrs1z_seek_snd_head sg t2 _ _ HT1z
             ltac:(rewrite ESK2; reflexivity)). }
  assert (HPnC2 : forall t',
      (o7,z7,c7) :: s2t = (4%N,3%N,1%N) :: t' ->
      ph_notlast sg cols2).
  { intros t' E.
    pose proof (nbrs1z_seek_notlast sg t2
                  (4%N,3%N,1%N) t' HT1z
                  ltac:(rewrite ESK2; cbn [snd]; exact E)
                  ltac:(reflexivity)
                  ltac:(cbn [gZ]; lia)) as H0.
    rewrite ESK2 in H0. cbn [fst] in H0. exact H0. }
  assert (Hph7 : ph sg (o7,z7,c7) = false)
    by (exact (Hh2 _ _ eq_refl)).
  assert (EF7 : lin_flat sg ((o7,z7,c7) :: s2t)
                = (o7,z7,c7) :: lin_flat sg s2t)
    by (apply flat_cons_nonph; exact Hph7).
  xrewrite EF7. cbv beta iota.
  pose proof (round_at_flat_z sg cols2
                ((o7,z7,c7) :: s2t) f2 HW HK HL HPnC2 HN2z Hh2) as HRZ.
  xrewrite_in HRZ EF7. exact HRZ.
Qed.
Lemma round1g_flat_at_tag : forall sg pfx tail f,
  sg_wf sg -> keys_big sg ->
  sg_live sg ->
  ph_nbrs sg (pfx ++ tail) ->
  round1g (lin_flat sg tail) f
  = flat_res sg (round1g tail f).
Proof.
  intros sg pfx tail f HW HK HL HNo.
  assert (HN : ph_nbrs sg tail)
    by (exact (ph_nbrs_app_r sg pfx tail HNo)).
  unfold round1g.
  rewrite (seek_flat sg tail HW).
  destruct (seek tail) as [cols s] eqn:ESK.
  cbn [fst snd].
  pose proof (LineageGuard_seek_split tail) as HSP.
  rewrite ESK in HSP. cbn [fst snd] in HSP.
  assert (HPn : ph_notlast sg cols).
  { pose proof (ph_notlast_seek sg tail HN) as H0.
    rewrite ESK in H0. cbn [fst] in H0. exact H0. }
  assert (HNs : ph_nbrs sg s)
    by (exact (ph_nbrs_app_r sg cols s
                (ph_nbrs_at_eq sg _ _ HN HSP))).
  assert (HHs : forall g u, s = g :: u -> ph sg g = false).
  { intros g u E. subst s.
    assert (Hst : seektest g = false)
      by (apply (seek_snd_head tail g u);
          rewrite ESK; reflexivity).
    destruct (ph sg g) eqn:Hph; [|reflexivity].
    rewrite (ph_seektest sg g Hph) in Hst.
    discriminate. }
  exact (round_at_flat_z sg cols s f HW HK HL
           (fun t' _ => HPn) (nbrs_nbrs1z _ _ HNs) HHs).
Qed.
Lemma round2g_pre8_flat_at_tag : forall sg pfx tail f,
  sg_wf sg -> keys_big sg ->
  sg_live sg ->
  ph_margins sg (pfx ++ tail) ->
  ph_nbrs sg (pfx ++ tail) ->
  (forall g, nth_error tail O = Some g -> ph sg g = false) ->
  round2g_pre8 (lin_flat sg tail) f
  = match round2g_pre8 tail f with
    | Some w => Some (lin_flat sg w)
    | None => None
    end.
Proof.
  intros sg pfx tail f HW HK HL HMo HNo Hhd.
  assert (HN : ph_nbrs sg tail)
    by (exact (ph_nbrs_app_r sg pfx tail HNo)).
  unfold round2g_pre8.
  rewrite (seek_flat sg tail HW).
  destruct (seek tail) as [cols s] eqn:ESK.
  cbn [fst snd].
  pose proof (LineageGuard_seek_split tail) as HSP.
  rewrite ESK in HSP. cbn [fst snd] in HSP.
  assert (HPn : ph_notlast sg cols).
  { pose proof (ph_notlast_seek sg tail HN) as H0.
    rewrite ESK in H0. cbn [fst] in H0. exact H0. }
  assert (HMs : ph_margins sg s).
  { destruct s as [|g7 s3t].
    { intros p g Hp Hph. destruct p; discriminate. }
    assert (Hst7 : seektest g7 = false)
      by (apply (seek_snd_head tail g7 s3t);
          rewrite ESK; reflexivity).
    assert (HEq : pfx ++ tail = (pfx ++ cols) ++ g7 :: s3t)
      by (rewrite <- app_assoc; f_equal; exact HSP).
    exact (margins_cut_at sg _ _ _ _ HMo HEq
             (seektest_noncasc _ Hst7)
             (seektest_notag _ Hst7)). }
  assert (HNs : ph_nbrs sg s)
    by (exact (ph_nbrs_app_r sg cols s
                (ph_nbrs_at_eq sg _ _ HN HSP))).
  assert (HHs : forall g u, s = g :: u -> ph sg g = false).
  { intros g u E. subst s.
    assert (Hst : seektest g = false)
      by (apply (seek_snd_head tail g u);
          rewrite ESK; reflexivity).
    destruct (ph sg g) eqn:Hph; [|reflexivity].
    rewrite (ph_seektest sg g Hph) in Hst.
    discriminate. }
  rewrite (round_at_flat_z sg cols s f HW HK HL
             (fun t' _ => HPn) (nbrs_nbrs1z _ _ HNs) HHs).
  destruct (round_at cols s f) as [[t2 f2]|] eqn:ERA;
    [|reflexivity].
  cbn [flat_res]. cbv beta iota.
  assert (HPcols : zspack sg cols).
  { split; [|split].
    - pose proof (mend_seek sg pfx tail HMo) as H0.
      rewrite ESK in H0. cbn [fst] in H0. exact H0.
    - pose proof (ph_nbrs_seek_fst sg tail HN) as H0.
      rewrite ESK in H0. cbn [fst] in H0. exact H0.
    - intros g u E. apply Hhd. rewrite HSP, E. reflexivity. }
  destruct (round_at_out_tag sg cols s f t2 f2 HW HK HPcols HMs HNs ERA)
    as (HT1z & HTh).
  rewrite (seek_flat sg t2 HW).
  destruct (seek t2) as [cols2 s2] eqn:ESK2.
  cbn [fst snd].
  destruct s2 as [|g7 s2t].
  2:{ destruct (flat_cons_ex sg g7 s2t HW)
        as (h7 & u7 & E7).
      xrewrite E7. cbv beta iota. reflexivity. }
  flatnil.
  assert (HNc2 : ph_nbrs sg cols2).
  { pose proof (nbrs1z_seek_all sg t2 HT1z
                  ltac:(rewrite ESK2; reflexivity)) as H0.
    rewrite ESK2 in H0. cbn [fst] in H0. exact H0. }
  assert (EW42 : forallb w42 (lin_flat sg cols2)
                 = forallb w42 cols2).
  { apply (w42_forallb_flat sg cols2 HW HNc2).
    intros p g Hp Hph. exact (proj1 (HNc2 p g Hp Hph)). }
  xrewrite EW42.
  destruct ((f2 =? 4) && forallb w42 cols2)%N eqn:EWT;
    repeat (xrewrite EWT).
  2:{ reflexivity. }
  pose proof (dtb4_conv_flat sg cols2 HW HK HNc2) as ED.
  xrewrite ED.
  destruct (dtb4_conv cols2) as [cols2'|] eqn:EDC;
    repeat (xrewrite EDC); reflexivity.
Qed.
Lemma margins_nonph_lt3_tag : forall sg w j g,
  ph_margins sg w -> nth_error w j = Some g ->
  (j < 3)%nat -> ph sg g = false.
Proof.
  intros sg w j g HM Hj Hlt.
  destruct (ph sg g) eqn:E; [|reflexivity].
  destruct (HM j g Hj E) as (HG & _).
  unfold GUARD in HG. lia.
Qed.
Lemma span2_core_flat_tag_heads : forall sg (a m : N) rest f,
  sg_wf sg -> keys_big sg ->
  sg_live sg ->
  ph_nbrs sg rest ->
  (forall g, nth_error rest O = Some g -> ph sg g = false) ->
  (forall g, nth_error rest 1%nat = Some g -> ph sg g = false) ->
  span2_core a m (lin_flat sg rest) f
  = fres sg (span2_core a m rest f).
Proof.
  intros sg a m rest f HW HK HL HN HH0 HH1.
  destruct rest as [|[[o0 z0] V] rest']; [reflexivity|].
  assert (Hph0 : ph sg (o0,z0,V) = false)
    by (exact (HH0 _ eq_refl)).
  assert (EF0 : lin_flat sg ((o0,z0,V) :: rest')
                = (o0,z0,V) :: lin_flat sg rest')
    by (apply flat_cons_nonph; exact Hph0).
  unfold span2_core. xrewrite EF0.
  destruct rest' as [|g2 r2].
  { flatnil. reflexivity. }
  assert (Hph2 : ph sg g2 = false)
    by (exact (HH1 _ eq_refl)).
  assert (EF2 : lin_flat sg (g2 :: r2)
                = g2 :: lin_flat sg r2)
    by (apply flat_cons_nonph; exact Hph2).
  xrewrite EF2. cbv beta iota.
  destruct ((o0 =? 4) && (z0 =? 2) && (1 <=? V))%N eqn:E42V;
    [|reflexivity].
  cbv beta iota zeta.
  destruct (seek (g2 :: r2)) as [cols s] eqn:ESK.
  assert (ESKF : seek (g2 :: lin_flat sg r2)
                 = (lin_flat sg cols, lin_flat sg s)).
  { rewrite <- EF2, (seek_flat sg (g2 :: r2) HW), ESK.
    reflexivity. }
  xrewrite ESKF. cbv beta iota.
  pose proof (LineageGuard_seek_split (g2 :: r2)) as HSP.
  rewrite ESK in HSP. cbn [fst snd] in HSP.
  assert (HNr : ph_nbrs sg (g2 :: r2))
    by (exact (ph_nbrs_tail sg _ _ HN)).
  assert (HPn : ph_notlast sg cols).
  { pose proof (ph_notlast_seek sg (g2 :: r2) HNr) as H0.
    rewrite ESK in H0. cbn [fst] in H0. exact H0. }
  assert (HNs : ph_nbrs sg s)
    by (exact (ph_nbrs_app_r sg cols s
                (ph_nbrs_at_eq sg _ _ HNr HSP))).
  assert (HHs : forall g u, s = g :: u -> ph sg g = false).
  { intros g u E. subst s.
    assert (Hst : seektest g = false)
      by (apply (seek_snd_head (g2 :: r2) g u);
          rewrite ESK; reflexivity).
    destruct (ph sg g) eqn:Hph; [|reflexivity].
    rewrite (ph_seektest sg g Hph) in Hst.
    discriminate. }
  destruct s as [|[[oR zR] cR] tR].
  { flatnil. reflexivity. }
  assert (HphR : ph sg (oR,zR,cR) = false)
    by (exact (HHs _ _ eq_refl)).
  assert (EFR : lin_flat sg ((oR,zR,cR) :: tR)
                = (oR,zR,cR) :: lin_flat sg tR)
    by (apply flat_cons_nonph; exact HphR).
  xrewrite EFR.
  assert (EPRE : lin_flat sg
      ([(2%N,2%N,(a+1)%N); (4%N,1%N,1%N); (3%N,1%N,1%N);
        (4%N,1%N,m); (8%N,2%N,1%N)] ++
       (if (1 <? V)%N then [(4%N,2%N,(V-1)%N)] else []))
      = ([(2%N,2%N,(a+1)%N); (4%N,1%N,1%N); (3%N,1%N,1%N);
          (4%N,1%N,m); (8%N,2%N,1%N)] ++
         (if (1 <? V)%N then [(4%N,2%N,(V-1)%N)] else []))).
  { apply lin_flat_nonph.
    destruct (1 <? V)%N; cbn [app]; lits_nonph HK. }
  destruct zR as [|z1]; [reflexivity|].
  destruct z1 as [z1|z1|]; [|reflexivity|].
  2:{ cbv beta iota.
      pose proof (leaf_act_flat_z sg
        ((oR,1%N,cR) :: tR) f HW HK
        (nbrs_nbrs1z _ _ HNs) HHs) as EL.
      xrewrite_in EL EFR. xrewrite EL.
      destruct (leaf_act ((oR,1%N,cR) :: tR) f)
        as [[s2 f2]|] eqn:EA; repeat (xrewrite EA).
      2:{ reflexivity. }
      cbn [flat_res fres]. f_equal.
      rewrite !lin_flat_app_c.
      destruct (1 <? V)%N;
        repeat rewrite flat_cons_nonlvl by reflexivity;
        cbn [lin_flat app]; reflexivity. }
  destruct z1 as [z1|z1|]; [reflexivity|reflexivity|].
  destruct cR as [|c1]; [reflexivity|].
  destruct c1 as [c1|c1|]; [reflexivity|reflexivity|].
  cbv beta iota.
  assert (EREN : renew_seg
      (length ((oR,3%N,1%N) :: lin_flat sg tR))
      (lin_flat sg cols)
      ((oR,3%N,1%N) :: lin_flat sg tR) f
    = flat_res sg
      (renew_seg (length ((oR,3%N,1%N) :: tR))
         cols ((oR,3%N,1%N) :: tR) f)).
  { pose proof (proj2 (fire_renew_flat_z
                         (length ((oR,3%N,1%N) ::
                           lin_flat sg tR)) sg HW HK HL)
                  cols ((oR,3%N,1%N) :: tR) f
                  (fun t' _ => HPn)
                  (nbrs_nbrs1z _ _ HNs) HHs) as E0.
    xrewrite_in E0 EFR. xrewrite E0.
    f_equal. apply renew_seg_sat.
    cbn [length]. apply le_n_S. exact (flat_len_ge sg tR HW). }
  xrewrite EREN.
  destruct (renew_seg (length ((oR,3%N,1%N) :: tR)) cols
              ((oR,3%N,1%N) :: tR) f) as [[body f2]|] eqn:ER;
    repeat (xrewrite ER).
  { cbn [flat_res fres]. f_equal.
    rewrite !lin_flat_app_c.
    destruct (1 <? V)%N;
      repeat rewrite flat_cons_nonlvl by reflexivity;
      cbn [lin_flat app]; reflexivity. }
  cbn [flat_res]. cbv beta iota.
  assert (EFIR : fire_comp
      (length ((oR,3%N,1%N) :: lin_flat sg tR))
      ((oR,3%N,1%N) :: lin_flat sg tR) f
    = flat_res sg
      (fire_comp (length ((oR,3%N,1%N) :: tR))
         ((oR,3%N,1%N) :: tR) f)).
  { pose proof (proj1 (fire_renew_flat_z
                         (length ((oR,3%N,1%N) ::
                           lin_flat sg tR)) sg HW HK HL)
                  ((oR,3%N,1%N) :: tR) f
                  (nbrs_nbrs1z _ _ HNs) HHs) as E0.
    xrewrite_in E0 EFR. xrewrite E0.
    f_equal. apply fire_comp_sat.
    cbn [length]. apply le_n_S. exact (flat_len_ge sg tR HW). }
  xrewrite EFIR.
  destruct (fire_comp (length ((oR,3%N,1%N) :: tR))
              ((oR,3%N,1%N) :: tR) f) as [[s2 f2]|] eqn:EFC;
    repeat (xrewrite EFC).
  2:{ cbn [flat_res]. reflexivity. }
  cbn [flat_res fres]. f_equal.
  rewrite !lin_flat_app_c.
  destruct (1 <? V)%N;
    repeat rewrite flat_cons_nonlvl by reflexivity;
    cbn [lin_flat app]; reflexivity.
Qed.
Ltac digs_tag :=
  repeat match goal with
  | |- context [match ?x with N0 => _ | N.pos _ => _ end] =>
      is_var x; destruct x
  | |- context [match ?x with xI _ => _ | xO _ => _ | xH => _ end] =>
      is_var x; destruct x
  end.
Lemma fr_rot_flat_tag : forall sg cw f,
  sg_wf sg -> ph_margins sg cw ->
  fr_rot (lin_flat sg cw) f
  = option_map (fres sg) (fr_rot cw f).
Proof.
  intros sg cw f HW HM.
  destruct cw as [|g0 t0]; [reflexivity|].
  rewrite (flat_cons_nonph sg g0 t0
             (margins_nonph_lt3_tag sg _ O g0 HM eq_refl ltac:(lia))).
  destruct t0 as [|g1 t1].
  { destruct g0 as [[o0 z0] c_0]. cbn [fr_rot]. digs_tag; reflexivity. }
  rewrite (flat_cons_nonph sg g1 t1
             (margins_nonph_lt3_tag sg _ 1%nat g1 HM eq_refl ltac:(lia))).
  destruct t1 as [|g2 t2].
  { destruct g0 as [[o0 z0] c_0]; destruct g1 as [[o1 z1] c1].
    cbn [fr_rot]. digs_tag; reflexivity. }
  rewrite (flat_cons_nonph sg g2 t2
             (margins_nonph_lt3_tag sg _ 2%nat g2 HM eq_refl ltac:(lia))).
  destruct g0 as [[o0 z0] c_0]; destruct g1 as [[o1 z1] c1];
    destruct g2 as [[o2 z2] c2].
  cbn [fr_rot]. digs_tag; reflexivity.
Qed.
Lemma fr_502_flat_tag : forall sg cw f,
