Lemma fr_primordial_flat_tag : forall sg cw f,
  sg_wf sg -> ph_margins sg cw ->
  fr_primordial (lin_flat sg cw) f
  = option_map (fres sg) (fr_primordial cw f).
Proof.
  intros sg cw f HW HM.
  destruct cw as [|g0 t0]; [reflexivity|].
  rewrite (flat_cons_nonph sg g0 t0
             (margins_nonph_lt3_tag sg _ O g0 HM eq_refl ltac:(lia))).
  destruct t0 as [|g1 t1].
  { destruct g0 as [[o0 z0] c_0]. cbn [fr_primordial].
    digs_tag; try reflexivity.
    all: first
      [ destruct (2 <=? f)%N;
        cbv beta iota delta [option_map fres o_];
        repeat rewrite flat_cons_nonlvl
          by first [reflexivity
                   |apply phshape_znot2; reflexivity];
        reflexivity
      | idtac ].
    all: reflexivity. }
  rewrite (flat_cons_nonph sg g1 t1
             (margins_nonph_lt3_tag sg _ 1%nat g1 HM eq_refl ltac:(lia))).
  destruct t1 as [|g2 t2].
  { destruct g0 as [[o0 z0] c_0]; destruct g1 as [[o1 z1] c1].
    cbn [fr_primordial]. digs_tag; try reflexivity.
    all: first
      [ destruct (2 <=? f)%N; [|destruct (f =? 1)%N];
        cbv beta iota delta [option_map fres o_];
        repeat rewrite flat_cons_nonlvl
          by first [reflexivity
                   |apply phshape_znot2; reflexivity];
        reflexivity
      | idtac ]. }
  destruct g0 as [[o0 z0] c_0]; destruct g1 as [[o1 z1] c1].
  destruct (flat_cons_ex sg g2 t2 HW) as (h2 & u2 & E2).
  rewrite E2. cbn [fr_primordial]. digs_tag; reflexivity.
Qed.
Lemma fr_prim4_flat_tag : forall sg cw f,
  sg_wf sg -> ph_margins sg cw ->
  fr_prim4 (lin_flat sg cw) f
  = option_map (fres sg) (fr_prim4 cw f).
Proof.
  intros sg cw f HW HM.
  destruct cw as [|g0 t0]; [reflexivity|].
  rewrite (flat_cons_nonph sg g0 t0
             (margins_nonph_lt3_tag sg _ O g0 HM eq_refl ltac:(lia))).
  destruct t0 as [|g1 t1].
  { rewrite flat_wnil.
    destruct g0 as [[o0 z0] c_0]. cbn [fr_prim4].
    digs_tag; try reflexivity.
    all: destruct (((c_0 =? 4) && (f =? 4))%N) eqn:Ecf;
         cbv beta iota in *;
         cbv beta iota delta [option_map fres o_];
         repeat rewrite flat_cons_nonlvl
           by first [reflexivity
                    |apply phshape_znot2; reflexivity];
         rewrite ?flat_wnil; reflexivity. }
  destruct g0 as [[o0 z0] c_0].
  destruct (flat_cons_ex sg g1 t1 HW) as (h1 & u1 & E1).
  rewrite E1. cbn [fr_prim4]. digs_tag; reflexivity.
Qed.
Lemma fr_clean_flat_tag : forall sg cw f,
  sg_wf sg -> ph_margins sg cw ->
  fr_clean (lin_flat sg cw) f
  = option_map (fres sg) (fr_clean cw f).
Proof.
  intros sg cw f HW HM.
  destruct cw as [|g0 t0]; [reflexivity|].
  rewrite (flat_cons_nonph sg g0 t0
             (margins_nonph_lt3_tag sg _ O g0 HM eq_refl ltac:(lia))).
  destruct t0 as [|g1 t1].
  { destruct g0 as [[o0 z0] c_0]. cbn [fr_clean]. digs_tag; reflexivity. }
  rewrite (flat_cons_nonph sg g1 t1
             (margins_nonph_lt3_tag sg _ 1%nat g1 HM eq_refl ltac:(lia))).
  destruct t1 as [|g2 t2].
  { destruct g0 as [[o0 z0] c_0]; destruct g1 as [[o1 z1] c1].
    cbn [fr_clean]. digs_tag; reflexivity. }
  rewrite (flat_cons_nonph sg g2 t2
             (margins_nonph_lt3_tag sg _ 2%nat g2 HM eq_refl ltac:(lia))).
  destruct g0 as [[o0 z0] c_0]; destruct g1 as [[o1 z1] c1];
    destruct g2 as [[o2 z2] c2].
  cbn [fr_clean]. digs_tag; try reflexivity.
  all: first
    [ destruct (2 <=? c2)%N eqn:EG; [|reflexivity];
      cbv zeta;
      cbv beta iota delta [option_map fres o_];
      rewrite !lin_flat_app_c;
      repeat rewrite flat_cons_nonlvl
        by first [reflexivity
                 |apply phshape_znot2; reflexivity];
      destruct (N.odd c2);
      repeat rewrite flat_cons_nonlvl
        by first [reflexivity
                 |apply phshape_znot2; reflexivity];
      cbn [lin_flat]; reflexivity
    | idtac ].
Qed.
Lemma fr_span2A'_flat_tag : forall sg cw f,
  sg_wf sg -> ph_margins sg cw ->
  fr_span2A' (lin_flat sg cw) f
  = option_map (fres sg) (fr_span2A' cw f).
Proof.
  intros sg cw f HW HM.
  destruct cw as [|g0 t0]; [reflexivity|].
  rewrite (flat_cons_nonph sg g0 t0
             (margins_nonph_lt3_tag sg _ O g0 HM eq_refl ltac:(lia))).
  destruct t0 as [|g1 t1].
  { destruct g0 as [[o0 z0] c_0]. cbn [fr_span2A']. digs_tag; reflexivity. }
  rewrite (flat_cons_nonph sg g1 t1
             (margins_nonph_lt3_tag sg _ 1%nat g1 HM eq_refl ltac:(lia))).
  destruct t1 as [|g2 t2].
  { destruct g0 as [[o0 z0] c_0]; destruct g1 as [[o1 z1] c1].
    cbn [fr_span2A']. digs_tag; reflexivity. }
  rewrite (flat_cons_nonph sg g2 t2
             (margins_nonph_lt3_tag sg _ 2%nat g2 HM eq_refl ltac:(lia))).
  destruct g0 as [[o0 z0] c_0]; destruct g1 as [[o1 z1] c1];
    destruct g2 as [[o2 z2] c2].
  destruct t2 as [|g3 t3].
  { cbn [fr_span2A']. digs_tag; reflexivity. }
  cbn [fr_span2A']. digs_tag; try reflexivity.
  all: first
    [ assert (H3 : ph sg g3 = false)
        by (apply (margins_win_excl sg _ 3%nat 1%nat g3 _
                     HM eq_refl eq_refl eq_refl); lia);
      rewrite (flat_cons_nonph sg g3 t3 H3);
      destruct g3 as [[o3 z3] c3];
      destruct t3 as [|g4 t4];
      [ cbn [lin_flat]; digs_tag; try reflexivity;
        first
        [ destruct ((1 <=? c_0) && (1 <=? c2) && (1 <=? c3)
                    && (f =? 4))%N eqn:EG; [|reflexivity];
          cbv beta iota delta [option_map fres o_];
          repeat rewrite flat_cons_nonlvl
            by first [reflexivity
                     |apply phshape_znot2; reflexivity];
          reflexivity
        | idtac ]
      | destruct (flat_cons_ex sg g4 t4 HW)
          as (h4 & u4 & E4); rewrite E4; digs_tag; reflexivity ]
    | idtac ].
Qed.
