Lemma fr_four_flat_tag : forall sg cw f,
  sg_wf sg -> ph_margins sg cw ->
  fr_four (lin_flat sg cw) f
  = option_map (fres sg) (fr_four cw f).
Proof.
  intros sg cw f HW HM.
  destruct cw as [|g0 t0]; [reflexivity|].
  rewrite (flat_cons_nonph sg g0 t0
             (margins_nonph_lt3_tag sg _ O g0 HM eq_refl ltac:(lia))).
  destruct t0 as [|g1 t1].
  { destruct g0 as [[o0 z0] c_0]. cbn [fr_four]. digs_tag; reflexivity. }
  rewrite (flat_cons_nonph sg g1 t1
             (margins_nonph_lt3_tag sg _ 1%nat g1 HM eq_refl ltac:(lia))).
  destruct t1 as [|g2 t2].
  { destruct g0 as [[o0 z0] c_0]; destruct g1 as [[o1 z1] c1].
    cbn [fr_four]. digs_tag; reflexivity. }
  rewrite (flat_cons_nonph sg g2 t2
             (margins_nonph_lt3_tag sg _ 2%nat g2 HM eq_refl ltac:(lia))).
  destruct g0 as [[o0 z0] c_0]; destruct g1 as [[o1 z1] c1];
    destruct g2 as [[o2 z2] c2].
  destruct t2 as [|g3 t3].
  { cbn [fr_four]. digs_tag; reflexivity. }
  cbn [fr_four]. digs_tag; try reflexivity.
  assert (H3 : ph sg g3 = false)
    by (apply (margins_win_excl sg _ 3%nat 2%nat g3 _
                 HM eq_refl eq_refl eq_refl); lia).
  rewrite (flat_cons_nonph sg g3 t3 H3).
  destruct g3 as [[od zd] cd]. cbv beta iota.
  match goal with
  | |- (if ?X then _ else _) = _ => destruct X eqn:EG
  end; [|reflexivity].
  destruct (N.odd c2);
    cbv beta iota delta [option_map fres o_];
    repeat f_equal;
    repeat rewrite flat_cons_nonlvl
      by first [reflexivity
               |apply phshape_znot2; reflexivity];
    try rewrite (flat_cons_nonph sg (od,zd,cd) t3 H3);
    reflexivity.
Qed.
Lemma fr_span2A_flat_tag : forall sg cw f,
  sg_wf sg -> keys_big sg ->
  sg_live sg ->
  ph_margins sg cw -> ph_nbrs sg cw ->
  fr_span2A (lin_flat sg cw) f
  = option_map (fres sg) (fr_span2A cw f).
Proof.
  intros sg cw f HW HK HL HM HN.
  destruct cw as [|g0 t0]; [reflexivity|].
  rewrite (flat_cons_nonph sg g0 t0
             (margins_nonph_lt3_tag sg _ O g0 HM eq_refl ltac:(lia))).
  destruct t0 as [|g1 t1].
  { destruct g0 as [[o0 z0] c_0]. cbn [fr_span2A]. digs_tag; reflexivity. }
  rewrite (flat_cons_nonph sg g1 t1
             (margins_nonph_lt3_tag sg _ 1%nat g1 HM eq_refl ltac:(lia))).
  destruct t1 as [|g2 t2].
  { destruct g0 as [[o0 z0] c_0]; destruct g1 as [[o1 z1] c1].
    cbn [fr_span2A]. digs_tag; reflexivity. }
  rewrite (flat_cons_nonph sg g2 t2
             (margins_nonph_lt3_tag sg _ 2%nat g2 HM eq_refl ltac:(lia))).
  destruct g0 as [[o0 z0] c_0]; destruct g1 as [[o1 z1] c1];
    destruct g2 as [[o2 z2] c2].
  destruct t2 as [|g3 t3].
  { cbn [fr_span2A]. digs_tag; reflexivity. }
  destruct g3 as [[o3 z3] c3].
  cbn [fr_span2A]. digs_tag;
    try (rewrite ?(flat_cons_nonlvl sg (_,_,_))
           by first [reflexivity
                    |apply phshape_znot2; reflexivity];
         digs_tag; reflexivity);
    try (match goal with
         | |- context [lin_flat ?SG (?g :: ?t)] =>
             let Hx := fresh "H3x" in
             assert (Hx : ph SG g = false)
               by (apply (margins_win_excl SG _ 3%nat O g _
                            HM eq_refl eq_refl eq_refl); lia);
             rewrite (flat_cons_nonph SG g t Hx)
         end;
         digs_tag; reflexivity);
    try reflexivity.
  all: first
    [ rewrite (flat_cons_nonlvl sg (3%N,3%N,1%N) t3)
        by (apply phshape_znot2; reflexivity);
      destruct t3 as [|g4 t4];
      [ cbn [lin_flat]; reflexivity | ];
      assert (H4 : ph sg g4 = false)
        by (apply (margins_win_excl sg _ 4%nat 3%nat g4 _
                     HM eq_refl eq_refl eq_refl); lia);
      rewrite (flat_cons_nonph sg g4 t4 H4);
      destruct g4 as [[o4 z4] c4];
      digs_tag; try reflexivity;
      first
      [ cbv beta iota delta [option_map fres o_];
        f_equal;
        rewrite <- (flat_cons_nonph sg (4%N,2%N,c4) t4 H4);
        apply (span2_core_flat_tag_heads sg c_0 c2
                 ((4%N,2%N,c4) :: t4) f HW HK HL);
        [ exact (ph_nbrs_app_r sg
            [(2%N,2%N,c_0); (5%N,2%N,1%N); (3%N,2%N,c2);
             (3%N,3%N,1%N)] _ HN)
        | intros g Hg; cbn [nth_error] in Hg; injection Hg as <-; exact H4
        | intros g Hg;
          apply (margins_win_excl sg _ 5%nat 3%nat g
                   (3%N,3%N,1%N) HM);
          [cbn [nth_error] in Hg; exact Hg|reflexivity|reflexivity|lia|lia] ]
      | match goal with |- ?G => fail 100 "span2A-tag" G end ]
    | match goal with |- ?G => fail 100 "span2A-shape" G end ].
Qed.
Lemma fr_span2B_flat_tag : forall sg cw f,
  sg_wf sg -> keys_big sg ->
  sg_live sg ->
  ph_margins sg cw -> ph_nbrs sg cw ->
  fr_span2B (lin_flat sg cw) f
  = option_map (fres sg) (fr_span2B cw f).
Proof.
  intros sg cw f HW HK HL HM HN.
  destruct cw as [|g0 t0]; [reflexivity|].
  rewrite (flat_cons_nonph sg g0 t0
             (margins_nonph_lt3_tag sg _ O g0 HM eq_refl ltac:(lia))).
  destruct t0 as [|g1 t1].
  { destruct g0 as [[o0 z0] c_0]. cbn [fr_span2B]. digs_tag; reflexivity. }
  rewrite (flat_cons_nonph sg g1 t1
             (margins_nonph_lt3_tag sg _ 1%nat g1 HM eq_refl ltac:(lia))).
  destruct t1 as [|g2 t2].
  { destruct g0 as [[o0 z0] c_0]; destruct g1 as [[o1 z1] c1].
    cbn [fr_span2B]. digs_tag; reflexivity. }
  rewrite (flat_cons_nonph sg g2 t2
             (margins_nonph_lt3_tag sg _ 2%nat g2 HM eq_refl ltac:(lia))).
  destruct g0 as [[o0 z0] c_0]; destruct g1 as [[o1 z1] c1];
    destruct g2 as [[o2 z2] c2].
  destruct t2 as [|g3 t3].
  { cbn [fr_span2B]. digs_tag; reflexivity. }
  cbn [fr_span2B]. digs_tag; try reflexivity.
  assert (H3 : ph sg g3 = false)
    by (apply (margins_win_excl sg _ 3%nat O g3 _
                 HM eq_refl eq_refl eq_refl); lia).
  rewrite (flat_cons_nonph sg g3 t3 H3).
  destruct g3 as [[o3 z3] c3]. digs_tag; try reflexivity.
  destruct t3 as [|g4 t4].
  { cbn [lin_flat]. reflexivity. }
  assert (H4 : ph sg g4 = false)
    by (apply (margins_win_excl sg _ 4%nat 1%nat g4 _
                 HM eq_refl eq_refl eq_refl); lia).
  rewrite (flat_cons_nonph sg g4 t4 H4).
  destruct g4 as [[o4 z4] c4]. digs_tag; try reflexivity.
  destruct t4 as [|g5 t5].
  { cbn [lin_flat]. reflexivity. }
  assert (H5 : ph sg g5 = false)
    by (apply (margins_win_excl sg _ 5%nat 2%nat g5 _
                 HM eq_refl eq_refl eq_refl); lia).
  rewrite (flat_cons_nonph sg g5 t5 H5).
  destruct g5 as [[o5 z5] c5]. digs_tag; try reflexivity.
  destruct t5 as [|g6 t6].
  { cbn [lin_flat]. reflexivity. }
  assert (H6 : ph sg g6 = false)
    by (apply (margins_win_excl sg _ 6%nat 3%nat g6 _
                 HM eq_refl eq_refl eq_refl); lia).
  rewrite (flat_cons_nonph sg g6 t6 H6).
  destruct g6 as [[o6 z6] c6]. digs_tag; try reflexivity.
  destruct ((1 <=? c2) && (1 <=? c6))%N eqn:EG; [|reflexivity].
  rewrite (round2g_flat_at_tag sg
             [(2%N,2%N,c_0); (5%N,2%N,1%N); (3%N,2%N,c2);
              (2%N,2%N,1%N); (4%N,2%N,c4); (4%N,3%N,1%N);
              (4%N,2%N,c6)]
             t6 f HW HK HL
             ltac:(cbn [app]; exact HM)
             ltac:(cbn [app]; exact HN)
             ltac:(intros g Hg;
                   apply (margins_win_excl sg _ 7%nat 5%nat
                            g (4%N,3%N,1%N) HM Hg eq_refl eq_refl);
                   lia)).
  destruct (round2g t6 f) as [[t3' f3]|] eqn:ER;
    cbn [flat_res]; [|reflexivity].
  cbv beta iota delta [option_map fres o_].
  rewrite !lin_flat_app_c.
  repeat rewrite flat_cons_nonlvl
    by first [reflexivity
             |apply phshape_znot2; reflexivity].
  reflexivity.
Qed.
Lemma fr_span8orph_flat_tag : forall sg cw f,
  sg_wf sg -> keys_big sg ->
  sg_live sg ->
  ph_margins sg cw -> ph_nbrs sg cw ->
  fr_span8orph (lin_flat sg cw) f
  = option_map (fres sg) (fr_span8orph cw f).
Proof.
  intros sg cw f HW HK HL HM HN.
  destruct cw as [|g0 t0]; [reflexivity|].
  rewrite (flat_cons_nonph sg g0 t0
             (margins_nonph_lt3_tag sg _ O g0 HM eq_refl ltac:(lia))).
  destruct t0 as [|g1 t1].
  { destruct g0 as [[o0 z0] c_0]. cbn [fr_span8orph].
    digs_tag; reflexivity. }
  rewrite (flat_cons_nonph sg g1 t1
             (margins_nonph_lt3_tag sg _ 1%nat g1 HM eq_refl ltac:(lia))).
  destruct t1 as [|g2 t2].
  { destruct g0 as [[o0 z0] c_0]; destruct g1 as [[o1 z1] c1].
    cbn [fr_span8orph]. digs_tag; reflexivity. }
  rewrite (flat_cons_nonph sg g2 t2
             (margins_nonph_lt3_tag sg _ 2%nat g2 HM eq_refl ltac:(lia))).
  destruct g0 as [[o0 z0] c_0]; destruct g1 as [[o1 z1] c1];
    destruct g2 as [[o2 z2] c2].
  destruct t2 as [|g3 t3].
  { cbn [fr_span8orph]. digs_tag; reflexivity. }
  cbn [fr_span8orph]. digs_tag; try reflexivity.
  assert (H3 : ph sg g3 = false)
    by (apply (margins_win_excl sg _ 3%nat O g3 _
                 HM eq_refl eq_refl eq_refl); lia).
  rewrite (flat_cons_nonph sg g3 t3 H3).
  destruct g3 as [[o3 z3] c3]. digs_tag; try reflexivity.
  destruct t3 as [|g4 t4].
  { cbv beta iota. cbn [lin_flat]. reflexivity. }
  assert (H4 : ph sg g4 = false)
    by (apply (margins_win_excl sg _ 4%nat 2%nat g4 _
                 HM eq_refl eq_refl eq_refl); lia).
  rewrite (flat_cons_nonph sg g4 t4 H4).
  destruct g4 as [[o4 z4] c4]. digs_tag; try reflexivity.
  destruct t4 as [|g5 t5].
  { cbv beta iota. cbn [lin_flat]. reflexivity. }
  assert (H5 : ph sg g5 = false)
    by (apply (margins_win_excl sg _ 5%nat 2%nat g5 _
                 HM eq_refl eq_refl eq_refl); lia).
  rewrite (flat_cons_nonph sg g5 t5 H5).
  destruct g5 as [[o5 z5] c5]. digs_tag; try reflexivity.
  cbv zeta.
  destruct ((2 <=? c_0) && (1 <=? c1) && (1 <=? c5))%N eqn:EG.
  2:{ cbv beta iota. reflexivity. }
  cbv beta iota.
  destruct (1 <? c5)%N eqn:EGG.
  - cbn [app].
    assert (HG1 : ph sg (4%N,2%N,(c5-1)%N) = false)
      by (litnp HK).
    assert (HNt5 : ph_nbrs sg t5).
    { exact (ph_nbrs_app_r sg
        [(2%N,2%N,c_0); (4%N,2%N,c1); (3%N,2%N,1%N);
         (4%N,2%N,c3); (4%N,3%N,1%N); (4%N,2%N,c5)] t5 HN). }
    assert (HHt5 : forall g u, t5 = g :: u -> ph sg g = false).
    { intros g u Et.
      apply (margins_win_excl sg _ 6%nat 4%nat g
               (4%N,3%N,1%N) HM);
        [cbn [nth_error]; rewrite Et; reflexivity
        |reflexivity|reflexivity|lia|lia]. }
    assert (HNtail : ph_nbrs sg
                       ((4%N,2%N,(c5-1)%N) :: t5)).
    { apply ph_nbrs_cons; [exact HG1| |exact HNt5].
      intros g Et. exact (HHt5 g (tl t5) Et). }
    assert (EFold : (4%N,2%N,(c5-1)%N) :: lin_flat sg t5
                    = lin_flat sg
                        ((4%N,2%N,(c5-1)%N) :: t5))
      by (symmetry; apply flat_cons_nonph; exact HG1).
    xrewrite EFold.
    rewrite (round1g_flat_at_tag sg []
               ((4%N,2%N,(c5-1)%N) :: t5) f HW HK HL HNtail).
    destruct (round1g ((4%N,2%N,(c5-1)%N) :: t5) f)
      as [[t2' f2]|] eqn:ER;
      cbn [flat_res]; [|reflexivity].
    cbv beta iota delta [option_map fres o_].
    repeat rewrite flat_cons_nonlvl
      by first [reflexivity
               |apply phshape_znot2; reflexivity].
    reflexivity.
  - cbn [app].
    rewrite (round1g_flat_at_tag sg
               [(2%N,2%N,c_0); (4%N,2%N,c1); (3%N,2%N,1%N);
                (4%N,2%N,c3); (4%N,3%N,1%N); (4%N,2%N,c5)]
               t5 f HW HK HL ltac:(cbn [app]; exact HN)).
    destruct (round1g t5 f) as [[t2' f2]|] eqn:ER;
      cbn [flat_res]; [|reflexivity].
    cbv beta iota delta [option_map fres o_].
    repeat rewrite flat_cons_nonlvl
      by first [reflexivity
               |apply phshape_znot2; reflexivity].
    reflexivity.
Qed.
Lemma fr_span8_flat_tag : forall sg cw f,
  sg_wf sg -> keys_big sg ->
  sg_live sg ->
  ph_margins sg cw -> ph_nbrs sg cw ->
  fr_span8 (lin_flat sg cw) f
  = option_map (fres sg) (fr_span8 cw f).
Proof.
  intros sg cw f HW HK HL HM HN.
  destruct cw as [|g0 t0]; [reflexivity|].
  rewrite (flat_cons_nonph sg g0 t0
             (margins_nonph_lt3_tag sg _ O g0 HM eq_refl ltac:(lia))).
  destruct t0 as [|g1 t1].
  { destruct g0 as [[o0 z0] c_0]. cbn [fr_span8]. digs_tag; reflexivity. }
  rewrite (flat_cons_nonph sg g1 t1
             (margins_nonph_lt3_tag sg _ 1%nat g1 HM eq_refl ltac:(lia))).
  destruct t1 as [|g2 t2].
  { destruct g0 as [[o0 z0] c_0]; destruct g1 as [[o1 z1] c1].
    cbn [fr_span8]. digs_tag; reflexivity. }
  rewrite (flat_cons_nonph sg g2 t2
             (margins_nonph_lt3_tag sg _ 2%nat g2 HM eq_refl ltac:(lia))).
  destruct g0 as [[o0 z0] c_0]; destruct g1 as [[o1 z1] c1];
    destruct g2 as [[o2 z2] c2].
  destruct t2 as [|g3 t3].
  { cbn [fr_span8]. digs_tag; reflexivity. }
  cbn [fr_span8]. digs_tag; try reflexivity.
  assert (H3 : ph sg g3 = false)
    by (apply (margins_win_excl sg _ 3%nat O g3 _
                 HM eq_refl eq_refl eq_refl); lia).
  rewrite (flat_cons_nonph sg g3 t3 H3).
  destruct g3 as [[o3 z3] c3]. digs_tag; try reflexivity.
  assert (HG1 : ph sg (4%N,2%N,(c3-1)%N) = false)
    by (litnp HK).
  destruct t3 as [|g4 t4].
  { cbn [lin_flat].
    destruct ((2 <=? c_0) && (1 <=? c3) && (f =? 4))%N eqn:EG4.
    - apply andb_prop in EG4. destruct EG4 as [EG4a Ef4].
      apply N.eqb_eq in Ef4. subst f.
      cbv zeta.
      cbv beta iota delta [option_map fres o_].
      f_equal.
      destruct (1 <? c3)%N eqn:EGG.
      + replace (tick_target
                   ([(5%N,1%N,1%N); (4%N,1%N,1%N); (3%N,1%N,(c_0-2)%N);
                     (2%N,2%N,1%N); (4%N,2%N,c1)]
                    ++ [(7%N,1%N,1%N); (3%N,2%N,1%N)]
                    ++ [(4%N,2%N,(c3-1)%N)]) 5%nat)
          with (Some 5%nat) by reflexivity.
        set (u := [(7%N,1%N,1%N); (3%N,2%N,1%N);
                   (4%N,2%N,(c3-1)%N)]).
        assert (ZU : zpack sg u).
        { apply zpack_lits. unfold u. lits_nonph HK. }
        destruct ZU as (HNu & HHu).
        assert (EFU : lin_flat sg u = u).
        { apply lin_flat_nonph.
          unfold u. lits_nonph HK. }
        pose proof (leaf_act_flat_z sg u 4 HW HK HNu HHu)
          as EFL.
        rewrite EFU in EFL.
        change (deliver_tick FUEL ?w 4 5 true)
          with (match leaf_act (skipn 5 w) 4 with
                | Some (s', f') => ROk (firstn 5 w ++ s') f'
                | None => RBad
                end).
        cbn [skipn firstn app]. fold u.
        destruct (leaf_act u 4) as [[s' f']|] eqn:EL;
          try rewrite EL in EFL; cbn [flat_res] in EFL.
        * injection EFL as EFI. cbn [fres].
          repeat rewrite flat_cons_nonlvl
            by first [reflexivity
                     |apply phshape_znot2; reflexivity].
          rewrite <- EFI. reflexivity.
        * reflexivity.
      + replace (tick_target
                   ([(5%N,1%N,1%N); (4%N,1%N,1%N); (3%N,1%N,(c_0-2)%N);
                     (2%N,2%N,1%N); (4%N,2%N,c1)]
                    ++ [(7%N,1%N,1%N); (3%N,2%N,1%N)] ++ []) 5%nat)
          with (Some 5%nat) by reflexivity.
        set (u2 := [(7%N,1%N,1%N); (3%N,2%N,1%N)]).
        assert (ZU2 : zpack sg u2).
        { apply zpack_lits. unfold u2. lits_nonph HK. }
        destruct ZU2 as (HNu2 & HHu2).
        assert (EFU2 : lin_flat sg u2 = u2).
        { apply lin_flat_nonph.
          unfold u2. lits_nonph HK. }
        pose proof (leaf_act_flat_z sg u2 4 HW HK HNu2 HHu2)
          as EFL2.
        rewrite EFU2 in EFL2.
        change (deliver_tick FUEL ?w 4 5 true)
          with (match leaf_act (skipn 5 w) 4 with
                | Some (s', f') => ROk (firstn 5 w ++ s') f'
                | None => RBad
                end).
        cbn [skipn firstn app]. fold u2. rewrite ?(app_nil_r u2).
        destruct (leaf_act u2 4) as [[s' f']|] eqn:EL2;
          try rewrite EL2 in EFL2;
          cbn [flat_res] in EFL2.
        * injection EFL2 as EFI2. cbn [fres].
          repeat rewrite flat_cons_nonlvl
            by first [reflexivity
                     |apply phshape_znot2; reflexivity].
          rewrite <- EFI2. reflexivity.
        * reflexivity.
    - destruct ((2 <=? c_0) && (1 <=? c3) && (5 <=? f))%N eqn:EG5;
        [|reflexivity].
      cbv beta iota delta [option_map fres o_].
      destruct (1 <? c3)%N.
      all: match goal with
      | |- context [lin_flat ?SG ?L] =>
          let E := fresh "EFLits" in
          assert (E : lin_flat SG L = L)
            by (apply lin_flat_nonph; lits_nonph HK);
          rewrite E; reflexivity
      end. }
  assert (Hhd : forall g, nth_error (g4 :: t4) O = Some g ->
                ph sg g = false).
  { intros g Hg. cbn in Hg. injection Hg as <-.
    apply (margins_win_excl sg _ 4%nat 2%nat g4 _
             HM eq_refl eq_refl eq_refl); lia. }
  assert (H4 : ph sg g4 = false) by (apply Hhd; reflexivity).
  rewrite (flat_cons_nonph sg g4 t4 H4).
  destruct ((2 <=? c_0) && (1 <=? c3))%N eqn:EG2.
  - rewrite <- (flat_cons_nonph sg g4 t4 H4).
    rewrite (round2g_flat_at_tag sg
               [(2%N,2%N,c_0); (4%N,2%N,c1); (4%N,3%N,1%N);
                (4%N,2%N,c3)]
               (g4 :: t4) f HW HK HL
               ltac:(cbn [app]; exact HM)
               ltac:(cbn [app]; exact HN) Hhd).
    destruct (round2g (g4 :: t4) f) as [[t3' f3]|] eqn:ER;
      cbn [flat_res].
    + cbv beta iota delta [option_map fres o_].
      repeat f_equal.
    + rewrite (round2g_pre8_flat_at_tag sg
                 [(2%N,2%N,c_0); (4%N,2%N,c1); (4%N,3%N,1%N);
                  (4%N,2%N,c3)]
                 (g4 :: t4) f HW HK HL
                 ltac:(cbn [app]; exact HM)
                 ltac:(cbn [app]; exact HN) Hhd).
      destruct (round2g_pre8 (g4 :: t4) f) as [cols2|] eqn:EP;
        [|reflexivity].
      cbv beta iota delta [option_map fres o_].
      repeat f_equal.
  - reflexivity.
Qed.
Lemma first_rule_flat_tag : forall sg cw f,
  sg_wf sg -> keys_big sg ->
  sg_live sg ->
  ph_margins sg cw -> ph_nbrs sg cw ->
  first_rule front_rules (lin_flat sg cw) f
  = option_map (fres sg)
      (first_rule front_rules cw f).
Proof.
  intros sg cw f HW HK HL HM HN.
  cbn [front_rules first_rule].
  rewrite (fr_primordial_flat_tag sg cw f HW HM).
  destruct (fr_primordial cw f); [reflexivity|]. cbn [option_map].
  rewrite (fr_prim4_flat_tag sg cw f HW HM).
  destruct (fr_prim4 cw f); [reflexivity|]. cbn [option_map].
  rewrite (fr_clean_flat_tag sg cw f HW HM).
  destruct (fr_clean cw f); [reflexivity|]. cbn [option_map].
  rewrite (fr_four_flat_tag sg cw f HW HM).
  destruct (fr_four cw f); [reflexivity|]. cbn [option_map].
  rewrite (fr_span2A_flat_tag sg cw f HW HK HL HM HN).
  destruct (fr_span2A cw f); [reflexivity|]. cbn [option_map].
  rewrite (fr_span2A'_flat_tag sg cw f HW HM).
  destruct (fr_span2A' cw f); [reflexivity|]. cbn [option_map].
  rewrite (fr_span2C'_flat_tag sg cw f HW HM).
  destruct (fr_span2C' cw f); [reflexivity|]. cbn [option_map].
  rewrite (fr_span8far_flat_tag sg cw f HW HM).
  destruct (fr_span8far cw f); [reflexivity|]. cbn [option_map].
  rewrite (fr_span2B_flat_tag sg cw f HW HK HL HM HN).
  destruct (fr_span2B cw f); [reflexivity|]. cbn [option_map].
  rewrite (fr_span8orph_flat_tag sg cw f HW HK HL HM HN).
  destruct (fr_span8orph cw f); [reflexivity|]. cbn [option_map].
  rewrite (fr_span8_flat_tag sg cw f HW HK HL HM HN).
  destruct (fr_span8 cw f); [reflexivity|]. cbn [option_map].
  rewrite (fr_rot_flat_tag sg cw f HW HM).
  destruct (fr_rot cw f); [reflexivity|]. cbn [option_map].
  rewrite (fr_502_flat_tag sg cw f HW HM).
  destruct (fr_502 cw f); [reflexivity|]. cbn [option_map].
  rewrite (fr_512_flat_tag sg cw f HW HM).
  destruct (fr_512 cw f); [reflexivity|]. cbn [option_map].
  rewrite (fr_522_flat_tag sg cw f HW HM).
  destruct (fr_522 cw f); reflexivity.
Qed.
Lemma splice_front_sound_tag : forall sg cw f w2 f2,
  sg_wf sg -> keys_big sg ->
  sg_live sg ->
  ph_margins sg cw -> ph_nbrs sg cw ->
  front_gate cw f = Some (ROk w2 f2) ->
  sound_impl (lin_flat sg cw) f
    (lin_flat sg w2) f2.
Proof.
  intros sg cw f w2 f2 HW HK HL HM HN HFG.
  unfold front_gate in HFG.
  destruct (lin_front_possible cw); [|discriminate].
  assert (EFR : first_rule front_rules (lin_flat sg cw) f
                = Some (ROk (lin_flat sg w2) f2)).
  { rewrite (first_rule_flat_tag sg cw f HW HK HL HM HN), HFG.
    reflexivity. }
  assert (ES : step (lin_flat sg cw) f O
               = (ROk (normalize (lin_flat sg w2)) f2,
                  O)).
  { unfold step. rewrite EFR. reflexivity. }
  pose proof (step_sound_live _ _ _ _ _ _ ES) as HSound.
  unfold sound_impl in *.
  rewrite normalize_sound in HSound. exact HSound.
Qed.
Ltac hit_digs H :=
  repeat match type of H with
  | context [match ?x with N0 => _ | N.pos _ => _ end] =>
      is_var x; destruct x
  | context [match ?x with xI _ => _ | xO _ => _ | xH => _ end] =>
      is_var x; destruct x
  end.
Ltac hit_bools H :=
  repeat match type of H with
  | context [if ?b then _ else _] => destruct b eqn:?; try discriminate
  end.
Inductive fr_span2A_hit : word -> N -> res -> Prop :=
  | FSpan2AHit (a m V : N) (rest : word) (f : N)
      (r : res) :
      span2_core a m ((4,2,V)%N :: rest) f = r ->
      fr_span2A_hit
        ([(2,2,a); (5,2,1); (3,2,m); (3,3,1); (4,2,V)]%N ++ rest)
        f r.
Theorem fr_span2A_hit_of : forall w f r,
  fr_span2A w f = Some r -> fr_span2A_hit w f r.
Proof.
  intros w f r H.
  destruct w as [|[[o0 z0] c_0] [|[[o1 z1] c1]
    [|[[o2 z2] c2] [|[[o3 z3] c3] [|[[o4 z4] c4] rest]]]]];
    try discriminate.
  all: cbn [fr_span2A] in H; hit_digs H; try discriminate.
  all: injection H as <-; apply FSpan2AHit; reflexivity.
Qed.
Inductive fr_span2A'_hit : word -> N -> res -> Prop :=
  | FSpan2APrimeHit (a m V f : N) :
      fr_span2A'_hit [(2,2,a); (5,2,1); (3,2,m); (4,2,V)]%N f
        (ROk
          [(2,2,a+1); (4,1,1); (3,1,1); (4,1,m-1); (4,2,V+1)]%N
          4%N).
Theorem fr_span2A'_hit_of : forall w f r,
  fr_span2A' w f = Some r -> fr_span2A'_hit w f r.
Proof.
  intros w f r H.
  destruct w as [|[[o0 z0] c_0] [|[[o1 z1] c1]
    [|[[o2 z2] c2] [|[[o3 z3] c3] [|g4 rest]]]]];
    try discriminate.
  all: cbn [fr_span2A'] in H; hit_digs H; try discriminate;
    hit_bools H.
  all: injection H as <-; constructor.
Qed.
Inductive fr_span2C'_hit : word -> N -> res -> Prop :=
  | FSpan2CPrimeHit (a m V f : N) :
      fr_span2C'_hit
        [(2,2,a); (5,2,1); (3,2,m); (2,2,1); (4,2,V)]%N f
        (ROk
          [(2,2,a+1); (4,1,1); (3,1,1); (4,1,m-1);
           (6,2,1); (4,2,V+1)]%N 4%N).
