Qed.
Inductive fr_span8far_hit : word -> N -> res -> Prop :=
  | FSpan8Far2Hit (cN V f : N) :
      fr_span8far_hit [(2,2,cN); (4,2,V)]%N f
        (ROk (span8far_out cN V []) f)
  | FSpan8Far3Hit (cN V f : N) :
      fr_span8far_hit [(2,2,cN); (4,2,V); (3,2,1)]%N f
        (ROk (span8far_out cN V [(3,2,1)]%N) f)
  | FSpan8Far4Hit (cN V G f : N) :
      fr_span8far_hit
        [(2,2,cN); (4,2,V); (3,2,1); (4,2,G)]%N f
        (ROk
          (span8far_out cN V [(3,2,1); (4,2,G)]%N) f).
Theorem fr_span8far_hit_of : forall w f r,
  fr_span8far w f = Some r -> fr_span8far_hit w f r.
Proof.
  intros w f r H.
  destruct w as [|[[o0 z0] c_0] [|[[o1 z1] c1]
    [|[[o2 z2] c2] [|[[o3 z3] c3] [|g4 rest]]]]];
    try discriminate.
  all: cbn [fr_span8far] in H; hit_digs H; try discriminate;
    hit_bools H.
  all: injection H as <-;
    first [apply FSpan8Far2Hit | apply FSpan8Far3Hit | apply FSpan8Far4Hit].
Qed.
