Inductive fr_span2B_hit : word -> N -> res -> Prop :=
  | FSpan2BHit (a m V G : N) (rest : word) (f : N)
      (t3 : word) (f3 : N) :
      round2g rest f = Some (t3, f3) ->
      fr_span2B_hit
        ([(2,2,a); (5,2,1); (3,2,m); (2,2,1); (4,2,V);
          (4,3,1); (4,2,G)]%N ++ rest) f
        (ROk
          ([(2,2,a+1); (4,1,1); (3,1,1); (4,1,m-1);
            (5,1,1); (3,2,1); (4,2,V); (8,2,1); (4,2,G-1)]%N ++ t3)
          f3).
Theorem fr_span2B_hit_of : forall w f r,
  fr_span2B w f = Some r -> fr_span2B_hit w f r.
Proof.
  intros w f r H.
  destruct w as [|[[o0 z0] c_0] [|[[o1 z1] c1]
    [|[[o2 z2] c2] [|[[o3 z3] c3] [|[[o4 z4] c4]
    [|[[o5 z5] c5] [|[[o6 z6] c6] rest]]]]]]]; try discriminate.
  all: cbn [fr_span2B] in H; hit_digs H; try discriminate;
    hit_bools H.
  all: match type of H with
  | context [round2g ?tail ?ff] =>
      destruct (round2g tail ff) as [[t3 f3]|] eqn:ER
  end; try discriminate.
  all: injection H as <-; apply FSpan2BHit; exact ER.
Qed.
Inductive fr_span8orph_hit : word -> N -> res -> Prop :=
  | FSpan8OrphMoreHit (cN V W G : N) (rest : word) (f : N)
      (t2 : word) (f2 : N) :
      (1 <? G)%N = true ->
      round1g ((4,2,G-1)%N :: rest) f = Some (t2, f2) ->
      fr_span8orph_hit
        ([(2,2,cN); (4,2,V); (3,2,1); (4,2,W); (4,3,1);
          (4,2,G)]%N ++ rest) f
        (ROk
          ([(5,1,1); (4,1,1); (3,1,cN-2); (2,2,1);
            (4,2,V-1); (4,1,1); (3,2,1); (4,2,W); (8,2,1)]%N ++ t2)
          f2)
  | FSpan8OrphOneHit (cN V W G : N) (rest : word) (f : N)
      (t2 : word) (f2 : N) :
      (1 <? G)%N = false ->
      round1g rest f = Some (t2, f2) ->
      fr_span8orph_hit
        ([(2,2,cN); (4,2,V); (3,2,1); (4,2,W); (4,3,1);
          (4,2,G)]%N ++ rest) f
        (ROk
          ([(5,1,1); (4,1,1); (3,1,cN-2); (2,2,1);
            (4,2,V-1); (4,1,1); (3,2,1); (4,2,W); (8,2,1)]%N ++ t2)
          f2).
Theorem fr_span8orph_hit_of : forall w f r,
  fr_span8orph w f = Some r -> fr_span8orph_hit w f r.
Proof.
  intros w f r H.
  destruct w as [|[[o0 z0] c_0] [|[[o1 z1] c1]
    [|[[o2 z2] c2] [|[[o3 z3] c3] [|[[o4 z4] c4]
    [|[[o5 z5] c5] rest]]]]]]; try discriminate.
  all: cbn [fr_span8orph] in H; hit_digs H; try discriminate.
  all: destruct (1 <? c5)%N eqn:EGG; cbn [app] in H.
  all: hit_bools H.
  all: match type of H with
  | context [round1g ?tail ?ff] =>
      destruct (round1g tail ff) as [[t2 f2]|] eqn:ER
  end; try discriminate.
  all: injection H as <-.
  - eapply FSpan8OrphMoreHit; eassumption.
  - eapply FSpan8OrphOneHit; eassumption.
Qed.
Ltac digsH_tag H :=
  repeat match type of H with
  | context [match ?x with N0 => _ | N.pos _ => _ end] =>
      is_var x; destruct x
  | context [match ?x with xI _ => _ | xO _ => _ | xH => _ end] =>
      is_var x; destruct x
  end.
Ltac poss_head_tag :=
  intros cw f r H;
  destruct cw as [|[[o0 z0] c_0] [|[[o1 z1] c1] [|[[o2 z2] c2]
    [|[[o3 z3] c3] [|[[o4 z4] c4] [|[[o5 z5] c5] t5]]]]]].
Ltac poss_tail_tag H :=
  try discriminate;
  digsH_tag H; try discriminate;
  cbn [lin_front_possible]; try reflexivity.
Ltac finish_possible_hit :=
  repeat match goal with
  | g : bg |- _ => destruct g as [[?o ?z] ?c]
  end;
  cbn [app lin_front_possible]; reflexivity.
Lemma fr_primordial_possible_tag : forall cw f r,
  fr_primordial cw f = Some r ->
  lin_front_possible cw = true.
Proof.
  intros cw f r H. destruct (fr_primordial_hit_of cw f r H);
    finish_possible_hit.
Qed.
