  finish_possible_hit.
Qed.
Lemma fr_clean_possible_tag : forall cw f r,
  fr_clean cw f = Some r ->
  lin_front_possible cw = true.
Proof.
  intros cw f r H. destruct (fr_clean_hit_of cw f r H).
  destruct rest as [|a [|b [|c [|d rest]]]];
    finish_possible_hit.
Qed.
