Lemma fr_span2C'_possible_tag : forall cw f r,
  fr_span2C' cw f = Some r ->
  lin_front_possible cw = true.
Proof.
  intros cw f r H. destruct (fr_span2C'_hit_of cw f r H).
  finish_possible_hit.
Qed.
