Lemma first_rule_possible_tag : forall cw f r,
  first_rule front_rules cw f = Some r ->
  lin_front_possible cw = true.
Proof.
  intros cw f r H.
  cbn [front_rules first_rule] in H.
  destruct (fr_primordial cw f) eqn:E1;
    [injection H as <-; exact (fr_primordial_possible_tag _ _ _ E1)|].
  destruct (fr_prim4 cw f) eqn:E2;
    [injection H as <-; exact (fr_prim4_possible_tag _ _ _ E2)|].
  destruct (fr_clean cw f) eqn:E3;
    [injection H as <-; exact (fr_clean_possible_tag _ _ _ E3)|].
  destruct (fr_four cw f) eqn:E4;
    [injection H as <-; exact (fr_four_possible_tag _ _ _ E4)|].
  destruct (fr_span2A cw f) eqn:E5;
    [injection H as <-; exact (fr_span2A_possible_tag _ _ _ E5)|].
  destruct (fr_span2A' cw f) eqn:E6;
    [injection H as <-; exact (fr_span2A'_possible_tag _ _ _ E6)|].
  destruct (fr_span2C' cw f) eqn:E7;
    [injection H as <-; exact (fr_span2C'_possible_tag _ _ _ E7)|].
  destruct (fr_span8far cw f) eqn:E8;
    [injection H as <-; exact (fr_span8far_possible_tag _ _ _ E8)|].
  destruct (fr_span2B cw f) eqn:E9;
    [injection H as <-; exact (fr_span2B_possible_tag _ _ _ E9)|].
  destruct (fr_span8orph cw f) eqn:E10;
    [injection H as <-; exact (fr_span8orph_possible_tag _ _ _ E10)|].
  destruct (fr_span8 cw f) eqn:E11;
    [injection H as <-; exact (fr_span8_possible_tag _ _ _ E11)|].
  destruct (fr_rot cw f) eqn:E12;
    [injection H as <-; exact (fr_rot_possible_tag _ _ _ E12)|].
  destruct (fr_502 cw f) eqn:E13;
    [injection H as <-; exact (fr_502_possible_tag _ _ _ E13)|].
  destruct (fr_512 cw f) eqn:E14;
    [injection H as <-; exact (fr_512_possible_tag _ _ _ E14)|].
  destruct (fr_522 cw f) eqn:E15;
    [injection H as <-; exact (fr_522_possible_tag _ _ _ E15)|].
  discriminate.
Qed.
Lemma front_gate_None_flat_tag : forall sg cw f,
  sg_wf sg -> keys_big sg ->
  sg_live sg ->
  ph_margins sg cw -> ph_nbrs sg cw ->
  front_gate cw f = None ->
  first_rule front_rules (lin_flat sg cw) f = None.
Proof.
  intros sg cw f HW HK HL HM HN HFG.
  rewrite (first_rule_flat_tag sg cw f HW HK HL HM HN).
  destruct (first_rule front_rules cw f) eqn:EFR;
    [|reflexivity].
  exfalso.
  unfold front_gate in HFG.
  rewrite (first_rule_possible_tag _ _ _ EFR) in HFG.
  rewrite EFR in HFG. discriminate.
Qed.
Open Scope N_scope.
Open Scope bool_scope.
Opaque LROUND_FUEL LROUND_CHUNKS
       FLAT_ROUND_FUEL CFUEL TRIES.
Lemma round_at_phseq_probe : forall cols s f t2 f2,
  round_at cols s f = Some (t2, f2) ->
  phseq t2 = phseq (cols ++ s).
Proof.
  intros cols s f t2 f2 HRun.
  unfold round_at in HRun.
  destruct s as [|[[og zg] cg] t].
  { cbn [leaf_act] in HRun. discriminate. }
  destruct zg as [|[z1|z1|]].
  { match type of HRun with
    | context [leaf_act ?w ?ff] =>
        destruct (leaf_act w ff) as [[s2 g2]|] eqn:ELA
    end;
    [ cbv beta iota in HRun; injection HRun as <- <-;
      rewrite !phseq_app,
        (leaf_act_phseq _ _ _ _ ELA); reflexivity
    | cbv beta iota in HRun; discriminate ]. }
  2:{ match type of HRun with
    | context [leaf_act ?w ?ff] =>
        destruct (leaf_act w ff) as [[s2 g2]|] eqn:ELA
    end;
    [ cbv beta iota in HRun; injection HRun as <- <-;
      rewrite !phseq_app,
        (leaf_act_phseq _ _ _ _ ELA); reflexivity
    | cbv beta iota in HRun; discriminate ]. }
  2:{ match type of HRun with
    | context [leaf_act ?w ?ff] =>
        destruct (leaf_act w ff) as [[s2 g2]|] eqn:ELA
    end;
    [ cbv beta iota in HRun; injection HRun as <- <-;
      rewrite !phseq_app,
        (leaf_act_phseq _ _ _ _ ELA); reflexivity
    | cbv beta iota in HRun; discriminate ]. }
  destruct z1 as [z1|z1|].
  1,2: match type of HRun with
    | context [leaf_act ?w ?ff] =>
        destruct (leaf_act w ff) as [[s2 g2]|] eqn:ELA
    end;
    [ cbv beta iota in HRun; injection HRun as <- <-;
      rewrite !phseq_app,
        (leaf_act_phseq _ _ _ _ ELA); reflexivity
    | cbv beta iota in HRun; discriminate ].
  destruct cg as [|[c1|c1|]].
  1,2,3: match type of HRun with
    | context [leaf_act ?w ?ff] =>
        destruct (leaf_act w ff) as [[s2 g2]|] eqn:ELA
    end;
    [ cbv beta iota in HRun; injection HRun as <- <-;
      rewrite !phseq_app,
        (leaf_act_phseq _ _ _ _ ELA); reflexivity
    | cbv beta iota in HRun; discriminate ].
  match type of HRun with
  | context [renew_seg ?nn ?cc ?ss ?ff] =>
      destruct (renew_seg nn cc ss ff) as [[body g2]|] eqn:ERN
  end.
  { cbv beta iota in HRun. injection HRun as <- <-.
    rewrite phseq_app.
    exact (renew_seg_phseq _ _ _ _ _ _ ERN). }
  cbv beta iota in HRun.
  match type of HRun with
  | context [fire_comp ?nn ?w ?ff] =>
      destruct (fire_comp nn w ff) as [[s2 g2]|] eqn:EFC
  end.
  2:{ cbv beta iota in HRun. discriminate. }
  cbv beta iota in HRun. injection HRun as <- <-.
  rewrite !phseq_app,
    (fire_comp_phseq _ _ _ _ _ EFC). reflexivity.
Qed.
Lemma round1g_phseq_probe : forall tail f t2 f2,
  round1g tail f = Some (t2, f2) ->
  phseq t2 = phseq tail.
Proof.
  intros tail f t2 f2 H.
  unfold round1g in H.
  destruct (seek tail) as [cols s] eqn:ES.
  transitivity (phseq (cols ++ s)).
  - exact (round_at_phseq_probe cols s f t2 f2 H).
  - rewrite phseq_app.
    symmetry. exact (seek_phseq tail cols s ES).
Qed.
Lemma round2g_phseq_probe : forall tail f t3 f3,
  round2g tail f = Some (t3, f3) ->
  phseq t3 = phseq tail.
Proof.
  intros tail f t3 f3 H.
  unfold round2g in H.
  destruct (seek tail) as [cols s] eqn:ES1.
  destruct (round_at cols s f) as [[t2 f2]|] eqn:ER1;
    [|discriminate].
  assert (HR1 : phseq t2 = phseq tail).
  { transitivity (phseq (cols ++ s)).
    - exact (round_at_phseq_probe cols s f t2 f2 ER1).
    - rewrite phseq_app. symmetry.
      exact (seek_phseq tail cols s ES1). }
  destruct (seek t2) as [cols2 s2] eqn:ES2.
  destruct s2 as [|g2 s2t].
  - destruct (f2 =? 4)%N eqn:EF4.
    + destruct (dtb4_conv cols2) as [cols2'|] eqn:ED;
        [|discriminate].
      cbv beta iota in H. injection H as <- <-.
      rewrite (dtb4_conv_phseq cols2 cols2' ED).
      rewrite <- HR1. rewrite (seek_phseq t2 cols2 [] ES2).
      cbn [app phseq]. rewrite app_nil_r. reflexivity.
    + destruct (5 <=? f2)%N eqn:EF5; [|discriminate].
      cbv beta iota in H. injection H as <- <-.
      rewrite phseq_app.
      cbn [phseq].
      rewrite phshape_znot2 by reflexivity. cbn [app].
      rewrite <- HR1. rewrite (seek_phseq t2 cols2 [] ES2).
      cbn [phseq app]. rewrite app_nil_r. reflexivity.
  - assert (ER2 : round_at cols2 (g2::s2t) f2 = Some (t3, f3))
      by exact H.
    transitivity (phseq (cols2 ++ g2 :: s2t)).
    + exact (round_at_phseq_probe cols2 (g2::s2t) f2 t3 f3 ER2).
    + rewrite phseq_app.
      rewrite <- (seek_phseq t2 cols2 (g2::s2t) ES2).
      exact HR1.
Qed.
Lemma round2g_pre8_phseq_probe : forall tail f cols2,
  round2g_pre8 tail f = Some cols2 ->
  phseq cols2 = phseq tail.
Proof.
  intros tail f cols2 H.
  unfold round2g_pre8 in H.
  destruct (seek tail) as [cols s] eqn:ES1.
  destruct (round_at cols s f) as [[t2 f2]|] eqn:ER1;
    [|discriminate].
  assert (HR1 : phseq t2 = phseq tail).
  { transitivity (phseq (cols ++ s)).
    - exact (round_at_phseq_probe cols s f t2 f2 ER1).
    - rewrite phseq_app. symmetry.
      exact (seek_phseq tail cols s ES1). }
  destruct (seek t2) as [cols0 s2] eqn:ES2.
  destruct s2 as [|g2 s2t]; [|discriminate].
  destruct ((f2 =? 4) && forallb w42 cols0)%N; [|discriminate].
  destruct (dtb4_conv cols0); [discriminate|].
  injection H as <-.
  rewrite <- HR1. rewrite (seek_phseq t2 cols0 [] ES2).
  cbn [phseq app]. rewrite app_nil_r. reflexivity.
Qed.
Ltac phseq_lits_probe :=
  cbn [phseq app];
  repeat first
    [ rewrite phshape_c1
    | rewrite phshape_c0
    | rewrite phshape_znot2 by reflexivity
    | rewrite phshape_onot9 by reflexivity ];
  try reflexivity.
Lemma span2_core_phseq_probe : forall a m rest f w2 f2,
  span2_core a m rest f = ROk w2 f2 ->
  phseq w2 = phseq rest.
Proof.
  intros a m rest f w2 f2 H.
  unfold span2_core in H.
  destruct rest as [|[[o0 z0] V] rest']; [discriminate|].
  destruct rest' as [|g1 rest'']; [discriminate|].
  destruct ((o0 =? 4) && (z0 =? 2) && (1 <=? V))%N eqn:EG;
    [|discriminate].
  apply andb_prop in EG as [EG _]. apply andb_prop in EG as [EO EZ].
  apply N.eqb_eq in EO, EZ. subst o0 z0.
  cbv beta zeta iota in H.
  destruct (seek (g1::rest'')) as [cols s] eqn:ES.
  destruct s as [|[[oR zR] cR] tR]; [discriminate|].
  destruct zR as [|[zr|zr|]]; try discriminate.
  - destruct zr as [zr|zr|]; try discriminate.
    destruct cR as [|[cr|cr|]]; try discriminate.
    match type of H with
    | context [renew_seg ?nn ?cc ?ss ?ff] =>
        destruct (renew_seg nn cc ss ff) as [[body g2]|] eqn:ERN
    end.
    + injection H as <- <-.
      destruct (1 <? V)%N; phseq_lits_probe;
        rewrite (renew_seg_phseq _ _ _ _ _ _ ERN);
        symmetry; exact (seek_phseq (g1::rest'') cols
          ((oR,3,1)::tR) ES).
    + match type of H with
      | context [fire_comp ?nn ?ss ?ff] =>
          destruct (fire_comp nn ss ff) as [[s2 g2]|] eqn:EFC
      end; [|discriminate].
      injection H as <- <-.
      destruct (1 <? V)%N; phseq_lits_probe;
        rewrite phseq_app,
          (fire_comp_phseq _ _ _ _ _ EFC);
        symmetry; exact (seek_phseq (g1::rest'') cols
          ((oR,3,1)::tR) ES).
  - match type of H with
    | context [leaf_act ?ss ?ff] =>
        destruct (leaf_act ss ff) as [[s2 g2]|] eqn:ELA
    end; [|discriminate].
    injection H as <- <-.
    destruct (1 <? V)%N; phseq_lits_probe;
      rewrite phseq_app,
        (leaf_act_phseq _ _ _ _ ELA);
      symmetry; exact (seek_phseq (g1::rest'') cols
        ((oR,1,cR)::tR) ES).
Qed.
Ltac digs_probe H :=
  repeat match type of H with
  | context [match ?x with N0 => _ | N.pos _ => _ end] =>
      is_var x; destruct x
  | context [match ?x with xI _ => _ | xO _ => _ | xH => _ end] =>
      is_var x; destruct x
  end.
Ltac bools_probe H :=
  repeat match type of H with
  | context [if ?b then _ else _] => destruct b eqn:?; try discriminate
  end.
Lemma fr_clean_phseq_probe : forall w f w2 f2,
  fr_clean w f = Some (ROk w2 f2) ->
  phseq w2 = phseq w.
Proof.
  intros w f w2 f2 H.
  pose proof (fr_clean_hit_of
    w f (ROk w2 f2) H) as HH.
  inversion HH; subst; clear HH.
  cbn [fr_clean app] in H; bools_probe H.
  all: try (injection H as <- <-); phseq_lits_probe.
Qed.
