Inductive fr_span2A_view : word -> N -> word -> N -> Prop :=
  | FSpan2A (a m V : N) (rest : word) (f : N)
      (w2 : word) (f2 : N) :
      span2_core a m ((4,2,V)%N :: rest) f = ROk w2 f2 ->
      fr_span2A_view
        ([(2,2,a); (5,2,1); (3,2,m); (3,3,1); (4,2,V)]%N ++ rest)
        f w2 f2.
Theorem fr_span2A_view_of : forall w f w2 f2,
  fr_span2A w f = Some (ROk w2 f2) ->
  fr_span2A_view w f w2 f2.
Proof.
  intros w f w2 f2 H.
  pose proof (fr_span2A_hit_of
    w f (ROk w2 f2) H) as HH.
  inversion HH; subst. apply FSpan2A. assumption.
Qed.
Lemma fr_span2A_phseq_probe : forall w f w2 f2,
  fr_span2A w f = Some (ROk w2 f2) ->
  phseq w2 = phseq w.
Proof.
  intros w f w2 f2 H.
  destruct (fr_span2A_view_of w f w2 f2 H)
    as [a m V rest ff out f2' HC].
  pose proof (span2_core_phseq_probe a m ((4,2,V)::rest)
    ff out f2' HC) as HP.
  phseq_lits_probe. exact HP.
Qed.
Inductive fr_span2B_view : word -> N -> word -> N -> Prop :=
  | FSpan2B (a m V G : N) (rest : word) (f : N)
      (t3 : word) (f3 : N) :
      round2g rest f = Some (t3, f3) ->
      fr_span2B_view
        ([(2,2,a); (5,2,1); (3,2,m); (2,2,1); (4,2,V);
          (4,3,1); (4,2,G)]%N ++ rest) f
        ([(2,2,a+1); (4,1,1); (3,1,1); (4,1,m-1);
          (5,1,1); (3,2,1); (4,2,V); (8,2,1); (4,2,G-1)]%N ++ t3) f3.
Theorem fr_span2B_view_of : forall w f w2 f2,
  fr_span2B w f = Some (ROk w2 f2) ->
  fr_span2B_view w f w2 f2.
Proof.
  intros w f w2 f2 H.
  pose proof (fr_span2B_hit_of
    w f (ROk w2 f2) H) as HH.
  inversion HH; subst. apply FSpan2B. assumption.
Qed.
Lemma fr_span2B_phseq_probe : forall w f w2 f2,
  fr_span2B w f = Some (ROk w2 f2) ->
  phseq w2 = phseq w.
Proof.
  intros w f w2 f2 H.
  destruct (fr_span2B_view_of w f w2 f2 H).
  pose proof (round2g_phseq_probe rest f t3 f3 H0) as HP.
  phseq_lits_probe. exact HP.
Qed.
Inductive fr_span8orph_view : word -> N -> word -> N -> Prop :=
  | FSpan8OrphMore (cN V W G : N) (rest : word) (f : N)
      (t2 : word) (f2 : N) :
      (1 <? G)%N = true ->
      round1g ((4,2,G-1)%N :: rest) f = Some (t2, f2) ->
      fr_span8orph_view
        ([(2,2,cN); (4,2,V); (3,2,1); (4,2,W); (4,3,1);
          (4,2,G)]%N ++ rest) f
        ([(5,1,1); (4,1,1); (3,1,cN-2); (2,2,1);
          (4,2,V-1); (4,1,1); (3,2,1); (4,2,W); (8,2,1)]%N ++ t2) f2
  | FSpan8OrphOne (cN V W G : N) (rest : word) (f : N)
      (t2 : word) (f2 : N) :
      (1 <? G)%N = false ->
      round1g rest f = Some (t2, f2) ->
      fr_span8orph_view
        ([(2,2,cN); (4,2,V); (3,2,1); (4,2,W); (4,3,1);
          (4,2,G)]%N ++ rest) f
        ([(5,1,1); (4,1,1); (3,1,cN-2); (2,2,1);
          (4,2,V-1); (4,1,1); (3,2,1); (4,2,W); (8,2,1)]%N ++ t2) f2.
Theorem fr_span8orph_view_of : forall w f w2 f2,
  fr_span8orph w f = Some (ROk w2 f2) ->
  fr_span8orph_view w f w2 f2.
Proof.
  intros w f w2 f2 H.
  pose proof (fr_span8orph_hit_of
    w f (ROk w2 f2) H) as HH.
  inversion HH; subst.
  - eapply FSpan8OrphMore; eassumption.
  - eapply FSpan8OrphOne; eassumption.
Qed.
Lemma fr_span8orph_phseq_probe : forall w f w2 f2,
  fr_span8orph w f = Some (ROk w2 f2) ->
  phseq w2 = phseq w.
Proof.
  intros w f w2 f2 H.
  destruct (fr_span8orph_view_of w f w2 f2 H);
    pose proof (round1g_phseq_probe _ f t2 f2 H1) as HP;
    phseq_lits_probe; exact HP.
Qed.
Inductive fr_span8_nonempty_view (cN V G : N) (g : bg)
    (rest : word) (f : N) : word -> N -> Prop :=
  | FSpan8Round (t3 : word) (f3 : N) :
      round2g (g :: rest) f = Some (t3, f3) ->
      fr_span8_nonempty_view cN V G g rest f
        ([(5,1,1); (4,1,1); (3,1,cN-2); (2,2,1); (4,2,V);
          (8,2,1); (4,2,G-1)]%N ++ t3) f3
  | FSpan8Pre (cols2 : word) :
      round2g (g :: rest) f = None ->
      round2g_pre8 (g :: rest) f = Some cols2 ->
      fr_span8_nonempty_view cN V G g rest f
        ([(5,1,1); (4,1,1); (3,1,cN-2); (2,2,1); (4,2,V);
          (7,1,1); (3,2,1); (4,2,G-1)]%N ++ cols2) 4%N.
Theorem fr_span8_nonempty_view_of : forall cN V G g rest f w2 f2,
  fr_span8
    ([(2,2,cN); (4,2,V); (4,3,1); (4,2,G)]%N ++ g :: rest) f =
    Some (ROk w2 f2) ->
  fr_span8_nonempty_view cN V G g rest f w2 f2.
Proof.
  intros cN V G g rest f w2 f2 H.
  cbn [app fr_span8] in H; digs_probe H; try discriminate.
  cbv beta zeta iota in H.
  destruct ((2 <=? cN) && (1 <=? G))%N eqn:EG.
  all: cbv beta zeta iota in H.
  - destruct (round2g (g::rest) f) as [[t3 f3]|] eqn:ER.
    + injection H as <- <-. apply FSpan8Round. exact ER.
    + cbv beta zeta iota in H.
      destruct (round2g_pre8 (g::rest) f) as [cols2|] eqn:EP;
        [|discriminate].
      injection H as <- <-. apply FSpan8Pre; assumption.
  - cbv beta zeta iota in H. discriminate.
Qed.
Lemma fr_span8_phseq_probe : forall w f w2 f2,
  fr_span8 w f = Some (ROk w2 f2) ->
  phseq w2 = phseq w.
Proof.
  intros w f w2 f2 H.
  destruct w as [|[[o0 z0] c_0] [|[[o1 z1] c1]
    [|[[o2 z2] c2] [|[[o3 z3] c3] rest]]]]; try discriminate.
  all: cbn [fr_span8] in H; digs_probe H; try discriminate.
  all: destruct rest as [|g rest].
  - cbv beta zeta iota in H.
    bools_probe H.
    all: try solve [injection H as <- <-; phseq_lits_probe].
    all: match type of H with
    | context [deliver_tick ?fu ?ww ?ff ?i ?vb] =>
        destruct (deliver_tick fu ww ff i vb) eqn:ED
    end; try discriminate.
    all: injection H as <- <-.
    all: eapply deliver_tick_z1_phseq in ED.
    all: rewrite ED; phseq_lits_probe.
  - destruct (fr_span8_nonempty_view_of c_0 c1 c3 g rest f w2 f2 H)
      as [t3 f3 ER|cols2 ER EP].
    + pose proof (round2g_phseq_probe (g::rest) f t3 f3 ER) as HP.
      phseq_lits_probe. exact HP.
    + pose proof (round2g_pre8_phseq_probe (g::rest) f cols2 EP) as HP.
      phseq_lits_probe. exact HP.
Qed.
Lemma first_rule_front_phseq_probe : forall w f w2 f2,
  first_rule front_rules w f = Some (ROk w2 f2) ->
  phseq w2 = phseq w.
Proof.
  intros w f w2 f2 H.
  cbn [front_rules first_rule] in H.
  destruct (fr_primordial w f) as [r|] eqn:E1.
  { injection H as ->. exact (fr_primordial_phseq_probe _ _ _ _ E1). }
  destruct (fr_prim4 w f) as [r|] eqn:E2.
  { injection H as ->. exact (fr_prim4_phseq_probe _ _ _ _ E2). }
  destruct (fr_clean w f) as [r|] eqn:E3.
  { injection H as ->. exact (fr_clean_phseq_probe _ _ _ _ E3). }
  destruct (fr_four w f) as [r|] eqn:E4.
  { injection H as ->. exact (fr_four_phseq_probe _ _ _ _ E4). }
  destruct (fr_span2A w f) as [r|] eqn:E5.
  { injection H as ->. exact (fr_span2A_phseq_probe _ _ _ _ E5). }
  destruct (fr_span2A' w f) as [r|] eqn:E6.
  { injection H as ->. exact (fr_span2A'_phseq_probe _ _ _ _ E6). }
  destruct (fr_span2C' w f) as [r|] eqn:E7.
  { injection H as ->. exact (fr_span2C'_phseq_probe _ _ _ _ E7). }
  destruct (fr_span8far w f) as [r|] eqn:E8.
  { injection H as ->. exact (fr_span8far_phseq_probe _ _ _ _ E8). }
  destruct (fr_span2B w f) as [r|] eqn:E9.
  { injection H as ->. exact (fr_span2B_phseq_probe _ _ _ _ E9). }
  destruct (fr_span8orph w f) as [r|] eqn:E10.
  { injection H as ->. exact (fr_span8orph_phseq_probe _ _ _ _ E10). }
  destruct (fr_span8 w f) as [r|] eqn:E11.
  { injection H as ->. exact (fr_span8_phseq_probe _ _ _ _ E11). }
  destruct (fr_rot w f) as [r|] eqn:E12.
  { injection H as ->. exact (fr_rot_phseq_probe _ _ _ _ E12). }
  destruct (fr_502 w f) as [r|] eqn:E13.
  { injection H as ->. exact (fr_502_phseq_probe _ _ _ _ E13). }
  destruct (fr_512 w f) as [r|] eqn:E14.
  { injection H as ->. exact (fr_512_phseq_probe _ _ _ _ E14). }
  destruct (fr_522 w f) as [r|] eqn:E15.
  { injection H as ->. exact (fr_522_phseq_probe _ _ _ _ E15). }
  discriminate.
Qed.
Lemma front_gate_phseq_probe : forall cw f w2 f2,
  front_gate cw f = Some (ROk w2 f2) ->
  phseq w2 = phseq cw.
Proof.
  intros cw f w2 f2 H. unfold front_gate in H.
  destruct (lin_front_possible cw); [|discriminate].
  exact (first_rule_front_phseq_probe cw f w2 f2 H).
Qed.
Open Scope N_scope.
Open Scope bool_scope.
Opaque LROUND_FUEL LROUND_CHUNKS
       FLAT_ROUND_FUEL CFUEL TRIES.
Definition shape_free (w : word) : Prop :=
  forall g, In g w -> phshape g = false.
Definition shape_head_free (w : word) : Prop :=
  forall g t, w = g :: t -> phshape g = false.
Lemma tag_edges_app_r_probe : forall p t,
  tag_edges (p ++ t) -> tag_edges t.
Proof.
  intros p. induction p as [|g p IH]; intros t H; [exact H|].
  apply IH. exact (tag_edges_tail g (p++t) H).
Qed.
Lemma tag_edges_shape_free_probe : forall w,
  shape_free w -> tag_edges w.
Proof.
  intros w. induction w as [|a [|b t] IH]; intros HF; try exact I.
  cbn [tag_edges]. split.
  - split; intros Hph.
    + rewrite (HF a ltac:(left; reflexivity)) in Hph. discriminate.
    + rewrite (HF b ltac:(right; left; reflexivity)) in Hph. discriminate.
  - apply IH. intros g Hg. apply HF. right. exact Hg.
Qed.
Lemma tag_edges_shape_free_app_probe : forall p t,
  shape_free p -> shape_head_free t -> tag_edges t ->
  tag_edges (p ++ t).
Proof.
  intros p. induction p as [|a p IH]; intros t HP HH HT; [exact HT|].
  destruct p as [|b p].
  - destruct t as [|g u]; [exact I|].
    cbn [app tag_edges]. split; [|exact HT]. split; intros Hph.
    + rewrite (HP a ltac:(left; reflexivity)) in Hph. discriminate.
    + rewrite (HH g u eq_refl) in Hph. discriminate.
  - cbn [app tag_edges]. split.
    + split; intros Hph.
      * rewrite (HP a ltac:(left; reflexivity)) in Hph. discriminate.
      * rewrite (HP b ltac:(right; left; reflexivity)) in Hph. discriminate.
    + apply IH; [|exact HH|exact HT].
      intros g Hg. apply HP. right. exact Hg.
Qed.
Lemma head_free_after_nonside_probe : forall p l t,
  tag_edges (p ++ l :: t) ->
  ~ side8 l -> shape_head_free t.
Proof.
  intros p l [|g u] HE HNS; intros x v E; [discriminate|].
  injection E as <- <-.
  pose proof (tag_edges_app_r_probe p (l::g::u) HE) as H.
  cbn [tag_edges] in H. destruct H as ([HR HL] & _).
  destruct (phshape g) eqn:EP; [|reflexivity].
  exfalso. exact (HNS (HL eq_refl)).
Qed.
Lemma tag_edges_replace_prefix_probe : forall pin l pout t,
  tag_edges (pin ++ l :: t) ->
  ~ side8 l -> shape_free pout ->
  tag_edges (pout ++ t).
Proof.
  intros pin l pout t HE HNS HF.
  apply tag_edges_shape_free_app_probe; [exact HF| |].
  - exact (head_free_after_nonside_probe pin l t HE HNS).
  - exact (tag_edges_app_r_probe (pin ++ [l]) t
      ltac:(rewrite <- app_assoc; cbn [app]; exact HE)).
Qed.
Ltac shape_lits_probe :=
  intros g Hin;
  repeat (destruct Hin as [<-|Hin]); try (destruct Hin);
  first
    [ apply phshape_c1
    | apply phshape_c0
    | apply phshape_znot2; reflexivity
    | apply phshape_onot9; reflexivity
    | reflexivity ].
Lemma fr_clean_edges_probe : forall w f w2 f2,
  fr_clean w f = Some (ROk w2 f2) ->
  tag_edges w -> tag_edges w2.
Proof.
  intros w f w2 f2 H HE.
  pose proof (fr_clean_hit_of
    w f (ROk w2 f2) H) as HH.
  inversion HH; subst; clear HH.
  cbn [fr_clean app] in H; bools_probe H.
  all: try (injection H as <- <-).
  all: cbn [app] in HE.
  all: lazymatch type of HE with
  | tag_edges (_ :: _ :: _ :: ?rt) =>
      lazymatch goal with
      | |- tag_edges (?a :: ?b :: ?c :: ?d :: ?rt2) =>
          unify rt2 rt;
          eapply tag_edges_replace_prefix_probe with
            (pin := [(2,2,4); (5,2,1)]) (l := (3,1,K)) (t := rt)
            (pout := [a;b;c;d])
      | |- tag_edges (?a :: ?b :: ?c :: ?rt2) =>
          unify rt2 rt;
          eapply tag_edges_replace_prefix_probe with
            (pin := [(2,2,4); (5,2,1)]) (l := (3,1,K)) (t := rt)
            (pout := [a;b;c])
      end
  end.
  all: try exact HE.
  all: try (unfold side8; cbn [gO gZ];
            intros [_ E]; discriminate E).
  all: unfold shape_free; shape_lits_probe.
Qed.
