Lemma round1g_zpack_at_probe : forall sg pfx tail f t2 f2,
  sg_wf sg -> keys_big sg ->
  ph_margins sg (pfx ++ tail) ->
  ph_nbrs sg (pfx ++ tail) ->
  (forall g, nth_error tail O = Some g -> ph sg g = false) ->
  round1g tail f = Some (t2, f2) ->
  zpack sg t2.
Proof.
  intros sg pfx tail f t2 f2 HW HK HM HN0 Hhd HR.
  assert (HN : ph_nbrs sg tail)
    by (exact (ph_nbrs_app_r sg pfx tail HN0)).
  unfold round1g in HR.
  destruct (seek tail) as [cols s] eqn:ESK.
  pose proof (LineageGuard_seek_split tail) as HSP.
  rewrite ESK in HSP. cbn [fst snd] in HSP.
  assert (HMs : ph_margins sg s).
  { destruct s as [|g u].
    - intros p x Hp Hph. destruct p; discriminate.
    - assert (Hst : seektest g = false)
        by (apply (seek_snd_head tail g u);
            rewrite ESK; reflexivity).
      assert (HEq : pfx ++ tail = (pfx ++ cols) ++ g :: u)
        by (rewrite <- app_assoc; f_equal; exact HSP).
      exact (margins_cut_at sg _ _ _ _ HM HEq
               (seektest_noncasc _ Hst)
               (seektest_notag _ Hst)). }
  assert (HNs : ph_nbrs sg s)
    by (exact (ph_nbrs_app_r sg cols s
                (ph_nbrs_at_eq sg _ _ HN HSP))).
  assert (HPcols : zspack sg cols).
  { split; [|split].
    - pose proof (mend_seek sg pfx tail HM) as H0.
      rewrite ESK in H0. cbn [fst] in H0. exact H0.
    - pose proof (ph_nbrs_seek_fst sg tail HN) as H0.
      rewrite ESK in H0. cbn [fst] in H0. exact H0.
    - intros g u E. apply Hhd. rewrite HSP, E. reflexivity. }
  exact (round_at_out_tag sg cols s f t2 f2
           HW HK HPcols HMs HNs HR).
Qed.
Lemma zpack_ptags_edges_probe : forall sg src out,
  zpack sg out ->
  phseq out = phseq src ->
  lin_ptags sg src = true ->
  tag_edges out.
Proof.
  intros sg src out [HN _] HP HT.
  apply (tag_edges_of_nbrs1z sg out HN).
  exact (lin_ptags_of_phseq_eq sg src out HP HT).
Qed.
Lemma span2_core_zpack_at_probe : forall sg pfx a m rest f w2 f2,
  sg_wf sg -> keys_big sg ->
  ph_margins sg (pfx ++ rest) ->
  ph_nbrs sg (pfx ++ rest) ->
  (forall g, nth_error rest 1%nat = Some g -> ph sg g = false) ->
  span2_core a m rest f = ROk w2 f2 ->
  zpack sg w2.
Proof.
  intros sg pfx a m rest f w2 f2 HW HK HM HN HH H.
  unfold span2_core in H.
  destruct rest as [|[[o0 z0] V] rest']; [discriminate|].
  destruct rest' as [|g1 rest'']; [discriminate|].
  destruct ((o0 =? 4) && (z0 =? 2) && (1 <=? V))%N eqn:EG;
    [|discriminate].
  apply andb_prop in EG as [EG _]. apply andb_prop in EG as [EO EZ].
  apply N.eqb_eq in EO, EZ. subst o0 z0.
  cbv beta zeta iota in H.
  destruct (seek (g1::rest'')) as [cols s] eqn:ES.
  assert (HM' : ph_margins sg
      ((pfx ++ [(4,2,V)]) ++ g1 :: rest'')).
  { rewrite <- app_assoc. cbn [app]. exact HM. }
  assert (HN' : ph_nbrs sg
      ((pfx ++ [(4,2,V)]) ++ g1 :: rest'')).
  { rewrite <- app_assoc. cbn [app]. exact HN. }
  assert (HH' : forall g, nth_error (g1::rest'') O = Some g ->
                  ph sg g = false).
  { intros g Hg. apply HH. cbn [nth_error]. exact Hg. }
  destruct s as [|[[oR zR] cR] tR]; [discriminate|].
  destruct zR as [|[zr|zr|]]; try discriminate.
  - destruct zr as [zr|zr|]; try discriminate.
    destruct cR as [|[cr|cr|]]; try discriminate.
    match type of H with
    | context [renew_seg ?nn ?cc ?ss ?ff] =>
        destruct (renew_seg nn cc ss ff) as [[body g2]|] eqn:ERN
    end.
    + injection H as <- <-.
      assert (ER : round1g (g1::rest'') f = Some (body, g2)).
      { unfold round1g. rewrite ES. unfold round_at.
        rewrite ERN. reflexivity. }
      pose proof (round1g_zpack_at_probe sg (pfx ++ [(4,2,V)])
        (g1::rest'') f body g2 HW HK HM' HN' HH' ER) as HP.
      eapply zpack_lits_app with
        (A := [(2,2,a+1); (4,1,1); (3,1,1); (4,1,m); (8,2,1)] ++
              (if 1 <? V then [(4,2,V-1)] else [])) (Y := body);
        [|exact HP].
      destruct (1 <? V)%N; cbn [app]; lits_nonph HK.
    + match type of H with
      | context [fire_comp ?nn ?ss ?ff] =>
          destruct (fire_comp nn ss ff) as [[s2 g2]|] eqn:EFC
      end; [|discriminate].
      injection H as <- <-.
      assert (ER : round1g (g1::rest'') f = Some (cols ++ s2, g2)).
      { unfold round1g. rewrite ES. unfold round_at.
        rewrite ERN, EFC. reflexivity. }
      pose proof (round1g_zpack_at_probe sg (pfx ++ [(4,2,V)])
        (g1::rest'') f (cols++s2) g2 HW HK HM' HN' HH' ER) as HP.
      eapply zpack_lits_app with
        (A := [(2,2,a+1); (4,1,1); (3,1,1); (4,1,m); (8,2,1)] ++
              (if 1 <? V then [(4,2,V-1)] else [])) (Y := cols++s2);
        [|exact HP].
      destruct (1 <? V)%N; cbn [app]; lits_nonph HK.
  - match type of H with
    | context [leaf_act ?ss ?ff] =>
        destruct (leaf_act ss ff) as [[s2 g2]|] eqn:ELA
    end; [|discriminate].
    injection H as <- <-.
    assert (ER : round1g (g1::rest'') f = Some (cols ++ s2, g2)).
    { unfold round1g. rewrite ES. unfold round_at.
      rewrite ELA. reflexivity. }
    pose proof (round1g_zpack_at_probe sg (pfx ++ [(4,2,V)])
      (g1::rest'') f (cols++s2) g2 HW HK HM' HN' HH' ER) as HP.
    eapply zpack_lits_app with
      (A := [(2,2,a+1); (4,1,1); (3,1,1); (4,1,m); (8,2,1)] ++
            (if 1 <? V then [(4,2,V-1)] else [])) (Y := cols++s2);
      [|exact HP].
    destruct (1 <? V)%N; cbn [app]; lits_nonph HK.
Qed.
Lemma fr_span2A_edges_probe : forall sg w f w2 f2,
  sg_wf sg -> keys_big sg ->
  ph_margins sg w -> ph_nbrs sg w ->
  lin_ptags sg w = true ->
  fr_span2A w f = Some (ROk w2 f2) ->
  tag_edges w2.
Proof.
  intros sg w f w2 f2 HW HK HM HN HT H.
  destruct (fr_span2A_view_of w f w2 f2 H)
    as [a m V rest ff out f2' HC].
  pose proof (span2_core_phseq_probe a m ((4,2,V)::rest)
    ff out f2' HC) as HCore.
  assert (HPS : phseq out = phseq
      ([(2,2,a); (5,2,1); (3,2,m); (3,3,1); (4,2,V)] ++ rest)).
  { phseq_lits_probe. exact HCore. }
  assert (HH : forall g,
      nth_error ((4,2,V)::rest) 1%nat = Some g ->
      ph sg g = false).
  { intros g Hg;
    apply (margins_win_excl sg _ 5%nat 3%nat g
             (3,3,1) HM);
    [cbn [nth_error] in Hg; exact Hg|reflexivity|reflexivity|lia|lia]. }
  pose proof (span2_core_zpack_at_probe sg
    [(2,2,a); (5,2,1); (3,2,m); (3,3,1)] a m
    ((4,2,V)::rest) ff out f2' HW HK HM HN HH HC) as HP.
  exact (zpack_ptags_edges_probe sg
    ((2,2,a)::(5,2,1)::(3,2,m)::(3,3,1)::(4,2,V)::rest)
    out HP HPS HT).
Qed.
Definition guard_group_eq_probe (sg : list seg)
    (a b : bg) : Prop :=
  ph sg a = ph sg b /\
  casc a = casc b /\
  is_spc a = is_spc b /\
  gZ a = gZ b.
Definition guard_word_eq_probe (sg : list seg)
    (a b : word) : Prop := Forall2 (guard_group_eq_probe sg) a b.
Lemma guard_group_eq_refl_probe : forall sg g,
  guard_group_eq_probe sg g g.
Proof. intros; repeat split; reflexivity. Qed.
Lemma guard_word_eq_refl_probe : forall sg w,
  guard_word_eq_probe sg w w.
Proof.
  intros sg w. induction w as [|g t IH]; constructor; auto.
  apply guard_group_eq_refl_probe.
Qed.
Lemma guard_word_eq_nth_l_probe : forall sg a b,
  guard_word_eq_probe sg a b -> forall i ga,
  nth_error a i = Some ga ->
  exists gb, nth_error b i = Some gb /\ guard_group_eq_probe sg ga gb.
Proof.
  intros sg a b HR. induction HR as [|x y xs ys Hxy HR IH];
    intros i ga Hg; [destruct i; discriminate|].
  destruct i as [|i].
  - cbn [nth_error] in Hg. injection Hg as <-.
    exists y. split; [reflexivity|exact Hxy].
  - cbn [nth_error] in Hg |- *. exact (IH i ga Hg).
Qed.
Lemma guard_word_eq_nth_r_probe : forall sg a b,
  guard_word_eq_probe sg a b -> forall i gb,
  nth_error b i = Some gb ->
  exists ga, nth_error a i = Some ga /\ guard_group_eq_probe sg ga gb.
Proof.
  intros sg a b HR. induction HR as [|x y xs ys Hxy HR IH];
    intros i gb Hg; [destruct i; discriminate|].
  destruct i as [|i].
  - cbn [nth_error] in Hg. injection Hg as <-.
    exists x. split; [reflexivity|exact Hxy].
  - cbn [nth_error] in Hg |- *. exact (IH i gb Hg).
Qed.
Lemma guard_word_eq_length_probe : forall sg a b,
  guard_word_eq_probe sg a b -> length a = length b.
Proof. intros sg a b H. induction H; cbn [length]; congruence. Qed.
Lemma ph_margins_guard_word_eq_probe : forall sg src out,
  guard_word_eq_probe sg src out ->
  ph_margins sg src -> ph_margins sg out.
Proof.
  intros sg src out HR HM j g Hg Hph.
  destruct (guard_word_eq_nth_r_probe sg src out HR j g Hg)
    as (gs & Hgs & HRel).
  destruct HRel as (HP & HC & _ & _).
  assert (Hphs : ph sg gs = true) by (rewrite HP; exact Hph).
  destruct (HM j gs Hgs Hphs) as (Hlo & Hhi & Hwin).
  split; [exact Hlo|]. split.
  - rewrite <- (guard_word_eq_length_probe sg src out HR). exact Hhi.
  - intros j' Hj1 Hj2 Hne.
    destruct (Hwin j' Hj1 Hj2 Hne) as (g' & Hg' & Hc' & Hp').
    destruct (guard_word_eq_nth_l_probe sg src out HR j' g' Hg')
      as (go & Hgo & HRel').
    destruct HRel' as (HP' & HC' & _ & _).
    exists go. split; [exact Hgo|]. split.
    + rewrite <- HC'. exact Hc'.
    + rewrite <- HP'. exact Hp'.
Qed.
Lemma ph_nbrs_guard_word_eq_probe : forall sg src out,
  guard_word_eq_probe sg src out ->
  ph_nbrs sg src -> ph_nbrs sg out.
Proof.
  intros sg src out HR HN p g Hg Hph.
  destruct (guard_word_eq_nth_r_probe sg src out HR p g Hg)
    as (gs & Hgs & HRel).
  destruct HRel as (HP & _ & _ & _).
  assert (Hphs : ph sg gs = true) by (rewrite HP; exact Hph).
  destruct (HN p gs Hgs Hphs) as ((gr & Hgr & Hright) & Hleft).
  destruct (guard_word_eq_nth_l_probe sg src out HR (p+1)%nat gr Hgr)
    as (gro & Hgro & HRgr).
  destruct HRgr as (_ & _ & Hspgr & Hzgr).
  split.
  - exists gro. split; [exact Hgro|].
    rewrite <- Hspgr. exact Hright.
  - intros gl Hp1 Hgl.
    destruct (guard_word_eq_nth_r_probe sg src out HR (p-1)%nat gl Hgl)
      as (gls & Hgls & HRgl).
    destruct HRgl as (_ & _ & Hspgl & _).
    rewrite <- Hspgl. exact (Hleft gls Hp1 Hgls).
Qed.
Lemma guard_group_eq_42_probe : forall sg a b,
  guard_group_eq_probe sg (4,2,a) (4,2,b).
Proof.
  intros sg a b. unfold guard_group_eq_probe.
  repeat split; try reflexivity.
Qed.
Lemma guard_word_eq_42_ctx_probe : forall sg p a b t,
  guard_word_eq_probe sg (p ++ (4,2,a) :: t) (p ++ (4,2,b) :: t).
Proof.
  intros sg p. induction p as [|g p IH]; intros a b t; cbn [app].
  - constructor; [apply guard_group_eq_42_probe|].
    apply guard_word_eq_refl_probe.
  - constructor; [apply guard_group_eq_refl_probe|apply IH].
Qed.
Lemma span8orph_finish_edges_probe : forall sg cN V W G rest t2,
  keys_big sg ->
  zpack sg t2 ->
  phseq
    ([(5,1,1); (4,1,1); (3,1,cN-2); (2,2,1);
      (4,2,V-1); (4,1,1); (3,2,1); (4,2,W); (8,2,1)] ++ t2) =
  phseq
    ([(2,2,cN); (4,2,V); (3,2,1); (4,2,W); (4,3,1);
      (4,2,G)] ++ rest) ->
  lin_ptags sg
    ([(2,2,cN); (4,2,V); (3,2,1); (4,2,W); (4,3,1);
      (4,2,G)] ++ rest) = true ->
  tag_edges
    ([(5,1,1); (4,1,1); (3,1,cN-2); (2,2,1);
      (4,2,V-1); (4,1,1); (3,2,1); (4,2,W); (8,2,1)] ++ t2).
Proof.
  intros sg cN V W G rest t2 HK HP HPS HT.
  assert (HOut : zpack sg
    ([(5,1,1); (4,1,1); (3,1,cN-2); (2,2,1);
      (4,2,V-1); (4,1,1); (3,2,1); (4,2,W); (8,2,1)] ++ t2))
    by (apply zpack_lits_app;
        [lits_nonph HK|exact HP]).
  exact (zpack_ptags_edges_probe sg
    ([(2,2,cN); (4,2,V); (3,2,1); (4,2,W); (4,3,1);
      (4,2,G)] ++ rest)
    ([(5,1,1); (4,1,1); (3,1,cN-2); (2,2,1);
      (4,2,V-1); (4,1,1); (3,2,1); (4,2,W); (8,2,1)] ++ t2)
    HOut HPS HT).
Qed.
Lemma fr_span8orph_edges_probe : forall sg w f w2 f2,
  sg_wf sg -> keys_big sg ->
  ph_margins sg w -> ph_nbrs sg w ->
  lin_ptags sg w = true ->
  fr_span8orph w f = Some (ROk w2 f2) ->
  tag_edges w2.
Proof.
  intros sg w f w2 f2 HW HK HM HN HT H.
  pose proof (fr_span8orph_view_of w f w2 f2 H) as HV.
  pose proof (fr_span8orph_phseq_probe w f w2 f2 H) as HPS.
  destruct HV as [cN V W G rest ff t2 f2' EGG ER
                 |cN V W G rest ff t2 f2' EGG ER].
  - let src := constr:([(2,2,cN); (4,2,V); (3,2,1);
                        (4,2,W); (4,3,1)] ++ (4,2,G)::rest) in
    let dst := constr:([(2,2,cN); (4,2,V); (3,2,1);
                        (4,2,W); (4,3,1)] ++ (4,2,G-1)::rest) in
    assert (HRg : guard_word_eq_probe sg src dst)
      by (apply guard_word_eq_42_ctx_probe);
    assert (HMg : ph_margins sg dst)
      by (apply (ph_margins_guard_word_eq_probe sg src dst HRg); exact HM);
    assert (HNg : ph_nbrs sg dst)
      by (apply (ph_nbrs_guard_word_eq_probe sg src dst HRg); exact HN);
    assert (HP : zpack sg t2).
    { apply (round1g_zpack_at_probe sg
        [(2,2,cN); (4,2,V); (3,2,1); (4,2,W); (4,3,1)]
        ((4,2,G-1)::rest) ff t2 f2' HW HK HMg HNg).
      - intros g Hg. cbn [nth_error] in Hg. injection Hg as <-.
        litnp HK.
      - exact ER. }
    exact (span8orph_finish_edges_probe sg cN V W G rest t2
      HK HP HPS HT).
  - assert (HP : zpack sg t2).
    { apply (round1g_zpack_at_probe sg
        [(2,2,cN); (4,2,V); (3,2,1); (4,2,W); (4,3,1); (4,2,G)]
        rest ff t2 f2' HW HK HM HN).
      - intros g Hg.
        apply (margins_win_excl sg _ 6%nat 4%nat g
                 (4,3,1) HM).
        + cbn [nth_error]. exact Hg.
        + reflexivity.
        + reflexivity.
        + lia.
        + lia.
      - exact ER. }
    exact (span8orph_finish_edges_probe sg cN V W G rest t2
      HK HP HPS HT).
Qed.
Open Scope N_scope.
Open Scope bool_scope.
Opaque LROUND_FUEL LROUND_CHUNKS
       FLAT_ROUND_FUEL CFUEL TRIES.
Definition nobase (g : bg) : bool := negb (tagbase g).
Lemma phshape_of_nobase : forall g,
  nobase g = true -> phshape g = false.
Proof.
  intros [[o z] c] H. unfold nobase, tagbase in H.
  unfold phshape, tagbase.
  cbn [gO gZ gC] in *.
  destruct (o =? PHO); destruct (z =? 2);
    cbn [andb negb] in H |- *; try reflexivity; discriminate.
Qed.
Lemma flat_nobase_app : forall sg p t,
  forallb nobase p = true ->
  lin_flat sg (p ++ t) = p ++ lin_flat sg t.
Proof.
  intros sg p. induction p as [|g p IH]; intros t H; [reflexivity|].
  cbn [forallb] in H. apply andb_prop in H as [Hg Hp].
  cbn [app]. rewrite flat_cons_nonlvl.
  - f_equal. exact (IH t Hp).
  - exact (phshape_of_nobase g Hg).
Qed.
Lemma countkey_nobase : forall k p,
  forallb nobase p = true -> countkey k p = O.
Proof.
  intros k p. induction p as [|g p IH]; intros H; [reflexivity|].
  cbn [forallb] in H. apply andb_prop in H as [Hg Hp].
  cbn [countkey]. rewrite (phshape_of_nobase g Hg), (IH Hp).
  reflexivity.
Qed.
Lemma lin_ok_nobase_prefix : forall sg p q t,
  forallb nobase p = true -> forallb nobase q = true ->
  lin_ok sg (q ++ t) = lin_ok sg (p ++ t).
Proof.
  intros sg p q t HP HQ. unfold lin_ok.
  induction sg as [|s sg IH]; [reflexivity|].
  cbn [forallb]. rewrite IH, !countkey_app.
  rewrite (countkey_nobase (sKey s) p HP).
  rewrite (countkey_nobase (sKey s) q HQ). reflexivity.
Qed.
Lemma lin_ptags_nobase : forall sg p,
  forallb nobase p = true -> lin_ptags sg p = true.
Proof.
  intros sg p. induction p as [|g p IH]; intros H; [reflexivity|].
  cbn [forallb] in H. apply andb_prop in H as [Hg Hp].
  cbn [lin_ptags]. apply andb_true_intro. split.
  - rewrite (phshape_of_nobase g Hg). reflexivity.
  - exact (IH Hp).
Qed.
Lemma lin_ptags_nobase_prefix : forall sg p q t,
  forallb nobase p = true -> forallb nobase q = true ->
  lin_ptags sg (p ++ t) = true ->
  lin_ptags sg (q ++ t) = true.
Proof.
  intros sg p q t HP HQ HT.
  pose proof (lin_ptags_skipn sg (length p) (p ++ t) HT) as Ht.
  rewrite skipn_app, skipn_all, PeanoNat.Nat.sub_diag in Ht.
  cbn [app skipn] in Ht.
  apply lin_ptags_app_true.
  - exact (lin_ptags_nobase sg q HQ).
  - exact Ht.
Qed.
Lemma sound_merge : forall J A Z t f,
  (2 <= A)%N -> (1 <= Z)%N ->
  sound_impl
    ((2,2,J) :: (A,1,1) :: (1,Z,1) :: t) f
    ((2,2,J+1) :: (A,Z+1,1) :: t) f.
Proof.
  intros J A Z t f HA HZ Hh.
  exact (wstep_halts_pull _ _ (bridge_merge J A Z t f HA HZ) Hh).
Qed.
Lemma sound_tick : forall J A B Z t f,
  (2 <= A)%N -> (2 <= B)%N -> (1 <= Z)%N ->
  sound_impl
    ((2,2,J) :: (A,1,1) :: (B,Z,1) :: t) f
    ((2,2,J+1) :: (A,1,1) :: (B-1,Z,1) :: t) f.
Proof.
  intros J A B Z t f HA HB HZ Hh.
  exact (wstep_halts_pull _ _ (bridge_tick J A B Z t f HA HB HZ) Hh).
Qed.
Lemma sound_clean : forall K t f,
  (2 <= K)%N ->
  sound_impl
    ((2,2,4) :: (5,2,1) :: (3,1,K) :: t) f
    ([(2,2,3 * N.div2 K + 4); (5,2,1); (3,2,N.div2 K)]
       ++ (if N.odd K then [(3,1,1)] else []) ++ t) f.
Proof.
  intros K t f HK Hh.
  assert (Hmid : halts tmB (wconf' ([], 0%sym,
    sdecode ((2,2,(4 + 3 * (K / 2))) :: (5,2,1)
               :: (3,2,K / 2) :: (3,1,K mod 2) :: t) f))).
  { cbn [wconf'].
    rewrite N.div2_div in Hh.
    replace (4 + 3 * (K / 2)) with (3 * (K / 2) + 4) by lia.
    destruct (N.odd K) eqn:EO.
    - assert (EMOD : K mod 2 = 1).
      { rewrite <- N.bit0_odd in EO. rewrite N.bit0_eqb in EO.
        apply N.eqb_eq in EO. exact EO. }
      rewrite EMOD.
      cbn [app] in Hh. exact Hh.
    - assert (EMOD : K mod 2 = 0).
      { rewrite <- N.bit0_odd in EO. rewrite N.bit0_eqb in EO.
        apply N.eqb_neq in EO.
        pose proof (N.mod_lt K 2 ltac:(lia)). lia. }
      rewrite EMOD.
      cbn [app] in Hh |- *. exact Hh. }
  exact (wstep_halts_pull _ _ (bridge_cleanconv 4 0 K t f HK) Hmid).
Qed.
Lemma sound_four : forall n M t f,
  (2 <= M)%N ->
  sound_impl
    ((2,2,n) :: (4,2,1) :: (4,1,M) :: t) f
    (if N.odd M
     then (2,2,n+2*(M-1)) :: (4,2,N.div2 (M+1)) :: (4,1,1) :: t
     else (2,2,n+2*M) :: (4,2,N.div2 M+1) :: t) f.
Proof.
  intros n M t f HM Hh.
  assert (HB := bridge_fourconv n 1 M t f ltac:(lia) HM).
  destruct (N.odd M) eqn:EO.
  - assert (EMOD : M mod 2 = 1).
    { rewrite <- N.bit0_odd in EO. rewrite N.bit0_eqb in EO.
      apply N.eqb_eq in EO. exact EO. }
    assert (HQ : M = 2 * (M / 2) + 1).
    { pose proof (N.div_mod M 2 ltac:(lia)). lia. }
    apply (wstep_halts_pull _ _ HB).
    cbn [wconf'] in Hh |- *.
    rewrite N.div2_div in Hh.
    replace (n + 4 * (M / 2)) with (n + 2 * (M - 1)) by lia.
    replace (1 + M / 2) with ((M + 1) / 2).
    + rewrite EMOD. exact Hh.
    + replace (M + 1) with (2 * (M / 2 + 1)) by lia.
      rewrite N.mul_comm, N.div_mul by lia. lia.
  - apply (wstep_halts_pull _ _ HB).
    cbn [wconf'] in Hh |- *.
    rewrite N.div2_div in Hh.
    assert (EMOD : M mod 2 = 0).
    { rewrite <- N.bit0_odd in EO. rewrite N.bit0_eqb in EO.
      apply N.eqb_neq in EO.
      pose proof (N.mod_lt M 2 ltac:(lia)). lia. }
    rewrite EMOD.
    replace (n + 4 * (M / 2)) with (n + 2 * M) by lia.
    replace (1 + M / 2) with (M / 2 + 1) by lia.
    change (halts tmB (wconf [] 0
      (sdecode ((2,2,n+2*M)::(4,2,M/2+1)::(4,1,0)::t) f))).
    rewrite (sdecode_cons (2,2,n+2*M) _ f).
    rewrite (sdecode_cons (4,2,M/2+1) _ f).
    rewrite (sdecode_drop0 4 1 t f).
    rewrite <- !sdecode_cons.
    exact Hh.
Qed.
Lemma sound_522_1 : forall c t f,
  sound_impl
    ((2,2,c) :: (4,1,1) :: (1,1,1) :: t) f
    ((2,2,c+1) :: (4,2,1) :: t) f.
Proof. intros. apply sound_merge; lia. Qed.
Lemma sound_522_2 : forall c t f,
  sound_impl
    ((2,2,c) :: (4,1,1) :: (2,1,1) :: t) f
    ((2,2,c+2) :: (4,2,1) :: t) f.
Proof.
  intros c t f. eapply sound_trans.
  - apply sound_tick; lia.
  - replace (c + 2) with ((c + 1) + 1) by lia.
    apply sound_merge; lia.
Qed.
Lemma sound_522_3 : forall c t f,
  sound_impl
    ((2,2,c) :: (4,1,1) :: (3,1,1) :: t) f
    ((2,2,c+3) :: (4,2,1) :: t) f.
Proof.
  intros c t f. eapply sound_trans.
  - apply sound_tick; lia.
  - eapply sound_trans.
    + apply sound_tick; lia.
    + replace (c + 3) with (((c + 1) + 1) + 1) by lia.
      apply sound_merge; lia.
Qed.
Lemma sound_512_1 : forall c t f,
  sound_impl
    ((2,2,c) :: (5,1,1) :: (1,1,1) :: t) f
    ((2,2,c+1) :: (5,2,1) :: t) f.
Proof. intros. apply sound_merge; lia. Qed.
Lemma sound_512_2 : forall c t f,
  sound_impl
    ((2,2,c) :: (5,1,1) :: (2,1,1) :: t) f
    ((2,2,c+2) :: (5,2,1) :: t) f.
Proof.
  intros c t f. eapply sound_trans.
  - apply sound_tick; lia.
  - replace (c + 2) with ((c + 1) + 1) by lia.
    apply sound_merge; lia.
Qed.
Lemma sound_502 : forall j K t f,
  (2 <= K)%N ->
  sound_impl
    ((2,2,j) :: (5,1,1) :: (3,1,K) :: t) f
    ((2,2,j+1) :: (5,1,1) :: (2,1,1) :: (3,1,K-1) :: t) f.
Proof.
  intros j K t f HK Hh.
  pose proof (sound_tick j 5 3 1 ((3,1,K-1)::t) f
                ltac:(lia) ltac:(lia) ltac:(lia) Hh) as HS.
  unfold sound_impl in *.
  assert (ESPL :
    sdecode ((2,2,j)::(5,1,1)::(3,1,K)::t) f =
    sdecode ((2,2,j)::(5,1,1)::(3,1,1)::(3,1,K-1)::t) f).
  { rewrite !sdecode_cons.
    replace (3,1,K) with (3,1,1 + (K - 1)) by (f_equal; f_equal; lia).
    rewrite gdec1_merge, <- !app_assoc. reflexivity. }
  rewrite ESPL. exact HS.
Qed.
Definition front_repr (sg : list seg) (cw : word) : Prop :=
  lin_ok sg cw = true /\
  lin_ptags sg cw = true.
Definition stable_guard (sg : list seg) (cw : word) : Prop :=
  front_repr sg cw /\
  tag_edges cw /\
  sg_wf sg /\
  sg_shape sg /\
  keys_big sg /\
  SGP sg.
Lemma adjk_spc : forall p g,
  is_spc g = true -> adjk p g = g.
Proof.
  intros p [[o z] c] H. unfold is_spc in H.
  cbn [gO gZ gC] in H.
  repeat rewrite Bool.andb_true_iff in H.
  destruct H as [[Ho Hz] Hc].
  apply N.eqb_eq in Ho, Hz, Hc. subst o z c.
  unfold adjk. cbn [gO gZ]. reflexivity.
Qed.
Lemma segshape_live : forall s,
  segcache s = true -> segshape s = true ->
  existsb (fun g => negb (gC g =? 0)%N) (sFlat s) = true.
Proof.
  intros s HC HS.
  unfold segshape in HS. apply andb_prop in HS as [HL HA].
  apply PeanoNat.Nat.leb_le in HL.
  unfold segcache in HC. apply PeanoNat.Nat.eqb_eq in HC.
  assert (HLB : (2 <= length (sBody s))%nat).
  { unfold sBody. rewrite length_app, length_rev. lia. }
  destruct (sBody s) as [|l [|sp rest]] eqn:EB;
    cbn [length] in HLB; try lia.
  cbn [segalt] in HA.
  apply andb_prop in HA as [HLS _].
  apply andb_prop in HLS as [_ HSP].
  apply existsb_exists. exists (adjk (sPend s) sp).
  split.
  - unfold sFlat, matb. apply in_map.
    rewrite EB. right. left. reflexivity.
  - rewrite (adjk_spc _ _ HSP).
    destruct sp as [[o z] c]. unfold is_spc in HSP.
    cbn [gO gZ gC] in HSP |- *.
    repeat rewrite Bool.andb_true_iff in HSP.
    destruct HSP as [[Ho Hz] Hc]. apply N.eqb_eq in Hc. subst c.
    reflexivity.
Qed.
Lemma sg_shape_alt : forall sg,
  sg_shape sg ->
  forall s, In s sg -> segalt (sBody s) = true.
Proof.
  intros sg HS s Hin. unfold sg_shape in HS.
  eapply forallb_forall in HS; [|exact Hin].
  unfold segshape in HS. exact (proj2 (andb_prop _ _ HS)).
Qed.
Lemma sg_shape_live : forall sg,
  sg_wf sg -> sg_shape sg ->
  sg_live sg.
Proof.
  intros sg HW HS s Hin.
  destruct (sg_wf_seg sg s HW Hin) as [HC _].
  apply (segshape_live s HC).
  unfold sg_shape in HS.
  eapply forallb_forall in HS; [exact HS|exact Hin].
Qed.
Lemma stable_guard_live : forall sg cw,
  stable_guard sg cw -> sg_live sg.
Proof.
  intros sg cw (_ & _ & HW & HS & _ & _).
  exact (sg_shape_live sg HW HS).
Qed.
Lemma cond_wf : forall w h cw sg h0,
  lin_cond w h = Some (cw, sg, h0) -> sg_wf sg.
Proof.
  intros w h cw sg h0 H.
  unfold lin_cond in H.
  destruct (lplan (length w) w O) as [|p pl0] eqn:EP;
    [discriminate|].
  destruct (lin_condk KMAGIC w h)
    as [[[cw1 sg1] h1]|] eqn:EC; [|discriminate].
  destruct (lin_ok sg1 cw1); [|discriminate].
  destruct (lin_tags sg1 cw1); [|discriminate].
  inversion H; subst cw1 sg1 h1.
  unfold lin_condk in EC. rewrite EP in EC.
  destruct (lapply (p :: pl0) w O KMAGIC)
    as [cw' sg'] eqn:ELap.
  cbv beta iota zeta in EC.
  destruct (forallb (fun s => segcache s && segok s) sg')
    eqn:EW; [|discriminate].
  destruct (forallb segshape sg'); [|discriminate].
  destruct (forallb segpos sg'); [|discriminate].
  inversion EC; subst cw' sg'. exact EW.
Qed.
Lemma cond_pos : forall w h cw sg h0,
  lin_cond w h = Some (cw, sg, h0) -> SGP sg.
Proof.
  intros w h cw sg h0 H.
  unfold lin_cond in H.
  destruct (lplan (length w) w O) as [|p pl0] eqn:EP;
    [discriminate|].
  destruct (lin_condk KMAGIC w h)
    as [[[cw1 sg1] h1]|] eqn:EC; [|discriminate].
  destruct (lin_ok sg1 cw1); [|discriminate].
  destruct (lin_tags sg1 cw1); [|discriminate].
  inversion H; subst cw1 sg1 h1.
  unfold lin_condk in EC. rewrite EP in EC.
  destruct (lapply (p :: pl0) w O KMAGIC)
    as [cw' sg'] eqn:ELap.
  cbv beta iota zeta in EC.
  destruct (forallb (fun s => segcache s && segok s) sg');
    [|discriminate].
  destruct (forallb segshape sg'); [|discriminate].
  destruct (forallb segpos sg') eqn:HP; [|discriminate].
  inversion EC; subst cw' sg'. exact HP.
Qed.
Definition T_cond_stable : Prop :=
  forall w h cw sg h0,
    lin_cond w h = Some (cw, sg, h0) ->
    lin_flat sg cw = w /\ stable_guard sg cw.
Theorem T_cond_stable_holds : T_cond_stable.
Proof.
  intros w h cw sg h0 H.
  destruct (T_cond_holds w h cw sg h0 H)
    as (HF & HOk & HGuard & HBig & HTags).
  pose proof (lin_tags_ptags sg cw HTags) as HPTags.
  pose proof (T_cond_flanked w h cw sg h0 H) as HFlanked.
  pose proof (tag_edges_of_nbrs1z sg cw
    (nbrs_nbrs1z sg cw
      (ph_flanked_nbrs sg cw HFlanked)) HPTags) as HEdges.
  split; [exact HF|]. split.
  - split; [exact HOk|exact HPTags].
  - split; [exact HEdges|].
    split; [exact (cond_wf w h cw sg h0 H)|].
    split; [exact (T_cond_shape w h cw sg h0 H)|].
    split; [exact HBig|exact (cond_pos w h cw sg h0 H)].
Qed.
Definition T_repack_stable : Prop :=
  forall sg ps cw sg2 ps2 cw2,
    stable_guard sg cw ->
    lin_repack_when_needed sg ps cw = Some (sg2, ps2, cw2) ->
    lin_flat sg2 cw2 = lin_flat sg cw /\
    lin_guard sg2 cw2 = true /\ stable_guard sg2 cw2.
Lemma lin_repack_output_tags : forall sg cw sg2 ps2 cw2,
  lin_repack sg cw = Some (sg2, ps2, cw2) ->
  lin_tags sg2 cw2 = true.
Proof.
  intros sg cw sg2 ps2 cw2 H.
  unfold lin_repack in H.
  destruct (repack_keys (map sKey sg) sg cw)
    as [[sgA wA]|] eqn:ER; [|discriminate].
  cbv beta iota in H.
  destruct (if Nat.leb (length wA) LZONE_MAX
            then Some (sgA, wA) else lin_extend sgA wA)
    as [[sgB wB]|] eqn:EE; [|discriminate].
  cbv beta iota in H.
  destruct (locate_all sgB wB) as [psB|] eqn:EL; [|discriminate].
  destruct (lin_guard_at sgB psB wB) eqn:EG; [|discriminate].
  destruct (lin_tags sgB wB) eqn:ET; [|discriminate].
  injection H as <- <- <-. exact ET.
Qed.
Lemma lin_repack_stable_direct : forall sg cw sg2 ps2 cw2,
  stable_guard sg cw ->
  lin_repack sg cw = Some (sg2, ps2, cw2) ->
  lin_flat sg2 cw2 = lin_flat sg cw /\
  lin_guard sg2 cw2 = true /\ stable_guard sg2 cw2.
Proof.
  intros sg cw sg2 ps2 cw2
    ((HOk & HPTags) & HEdges & HW & HShape & HBig & HPos) H.
  destruct (lin_repack_ok sg cw sg2 ps2 cw2 HOk HBig H)
    as (HF & HOk2 & HGuard2 & HBig2).
  pose proof (lin_repack_output_tags sg cw sg2 ps2 cw2 H) as HTags2.
  pose proof (lin_tags_ptags sg2 cw2 HTags2) as HPTags2.
  pose proof (lin_repack_edges sg cw sg2 ps2 cw2
    HEdges H) as HEdges2.
  destruct (lin_repack_table sg cw sg2 ps2 cw2 HW HShape H)
    as (HW2 & HShape2).
  pose proof (lin_repack_pos sg cw sg2 ps2 cw2 HPos H)
    as HPos2.
  split; [exact HF|]. split; [exact HGuard2|].
  split.
  - split; assumption.
  - split; [exact HEdges2|].
    split; [exact HW2|]. split; [exact HShape2|].
    split; [exact HBig2|exact HPos2].
Qed.
Theorem T_repack_stable_holds : T_repack_stable.
Proof.
  intros sg ps cw sg2 ps2 cw2 HG H.
  unfold lin_repack_when_needed in H.
  destruct (Nat.ltb LZONE_MAX (length cw)
            || lin_repack_needed sg ps cw) eqn:EN.
  - exact (lin_repack_stable_direct sg cw sg2 ps2 cw2 HG H).
  - destruct (lin_guard_at sg ps cw) eqn:EGA.
    + injection H as <- <- <-.
      split; [reflexivity|]. split.
      * exact (lin_guard_at_sound sg ps cw
                 (proj1 (proj1 HG)) EGA).
      * exact HG.
    + exact (lin_repack_stable_direct sg cw sg2 ps2 cw2 HG H).
Qed.
Lemma fixup_stable : forall sg w st sg2 w2 st2,
  stable_guard sg w ->
  fixup sg w st = Some (sg2, w2, st2) ->
  lin_flat sg2 w2 = lin_flat sg w /\
  lin_guard sg2 w2 = true /\ stable_guard sg2 w2.
Proof.
  intros sg w st sg2 w2 st2
    ((HOk & HPTags) & HEdges & HW & HShape & HBig & HPos) H.
  unfold fixup in H. rewrite HOk in H. cbn [negb] in H.
  destruct (lin_guard sg w) eqn:HGuard.
  - injection H as <- <- <-. split; [reflexivity|].
    split; [exact HGuard|].
    split; [split; assumption|].
    split; [exact HEdges|].
    split; [exact HW|]. split; [exact HShape|]. split; assumption.
  - destruct (lin_relax sg w) as [w4 sg4] eqn:ER.
    destruct (lin_guard sg4 w4) eqn:HGuard4; [|discriminate].
    destruct (lin_ok sg4 w4) eqn:HOk4; [|discriminate].
    injection H as <- <- <-.
    pose proof (lin_relax_flat sg w w4 sg4 HW HShape HOk ER)
      as HFlat.
    pose proof (lin_relax_ptags sg w w4 sg4
                  HW HShape HOk HPTags ER) as HPTags4.
    pose proof (lin_relax_edges sg w w4 sg4
                  HW HShape HOk HPTags HEdges ER) as HEdges4.
    destruct (lin_relax_table sg w w4 sg4 HW HShape ER)
      as (HW4 & HShape4).
    pose proof (lin_relax_keys_big sg w w4 sg4 HBig ER)
      as HBig4.
    pose proof (lin_relax_pos sg w w4 sg4 HPos ER) as HPos4.
    split; [exact HFlat|]. split; [exact HGuard4|]. split.
    + split; assumption.
    + split; [exact HEdges4|].
      split; [exact HW4|]. split; [exact HShape4|]. split; assumption.
Qed.
Lemma lin_fixup_at_stable : forall sg ps w st sg2 ps2 w2 st2,
  stable_guard sg w ->
  lin_fixup_at sg ps w st = Some (sg2, ps2, w2, st2) ->
  lin_flat sg2 w2 = lin_flat sg w /\
  lin_guard sg2 w2 = true /\ stable_guard sg2 w2.
Proof.
  intros sg ps w st sg2 ps2 w2 st2 HG H.
  unfold lin_fixup_at in H.
  destruct (lin_guard_at sg ps w) eqn:EGA.
  - injection H as <- <- <- <-. split; [reflexivity|]. split.
    + exact (lin_guard_at_sound sg ps w
               (proj1 (proj1 HG)) EGA).
    + exact HG.
  - destruct (fixup sg w st) as [[[sgA wA] stA]|] eqn:EF;
      [|discriminate].
    destruct (fixup_stable sg w st sgA wA stA HG EF)
      as (HFlat & HGuard & HStable).
    destruct (locate_all sgA wA) as [psA|] eqn:EL; [|discriminate].
    destruct (lin_guard_at sgA psA wA); [|discriminate].
    injection H as <- <- <- <-.
    split; [exact HFlat|]. split; assumption.
Qed.
Lemma front_finish : forall sg P Q t f,
  front_repr sg (P ++ t) ->
  forallb nobase P = true -> forallb nobase Q = true ->
  sound_impl (P ++ lin_flat sg t) f
    (Q ++ lin_flat sg t) f ->
  sound_impl (lin_flat sg (P ++ t)) f
    (lin_flat sg (lin_normalize_full (Q ++ t))) f /\
  front_repr sg (lin_normalize_full (Q ++ t)).
Proof.
  intros sg P Q t f HG HP HQ HS.
  destruct HG as (HOk & HPTags).
  assert (HOkRaw : lin_ok sg (Q ++ t) = true).
  { rewrite (lin_ok_nobase_prefix sg P Q t HP HQ). exact HOk. }
  assert (HPTagsRaw : lin_ptags sg (Q ++ t) = true).
  { exact (lin_ptags_nobase_prefix sg P Q t HP HQ HPTags). }
  split.
  - assert (HSraw : sound_impl
      (lin_flat sg (P ++ t)) f
      (lin_flat sg (Q ++ t)) f).
    { rewrite (flat_nobase_app sg P t HP), (flat_nobase_app sg Q t HQ).
      exact HS. }
    exact (sound_trans _ _ _ _ _ _ HSraw
      (lin_normalize_full_sound sg (Q ++ t) f)).
  - split.
    + rewrite lin_ok_lin_normalize_full. exact HOkRaw.
    + exact (lin_ptags_lin_normalize_full sg (Q ++ t)
               HPTagsRaw).
Qed.
Lemma fr_clean_inv : forall (K : N) t f w2 f2,
  fr_clean ((2,2,4) :: (5,2,1) :: (3,1,K) :: t) f
    = Some (ROk w2 f2) ->
  (2 <= K)%N /\ f2 = f /\
  w2 = ([(2,2,3 * N.div2 K + 4); (5,2,1); (3,2,N.div2 K)]
        ++ (if N.odd K then [(3,1,1)] else []) ++ t).
Proof.
  intros K t f w2 f2 H. cbn [fr_clean] in H.
  destruct (2 <=? K)%N eqn:E; [|discriminate].
  apply N.leb_le in E. unfold o_ in H. injection H as HW HF.
  split; [exact E|]. split; [exact (eq_sym HF)|exact (eq_sym HW)].
Qed.
Lemma fr_four_inv : forall (n M od zd cd : N) t f w2 f2,
  fr_four ((2,2,n) :: (4,2,1) :: (4,1,M) :: (od,zd,cd) :: t) f
    = Some (ROk w2 f2) ->
  (2 <= M)%N /\ f2 = f /\
  w2 = (if N.odd M
        then (2,2,n+2*(M-1)) :: (4,2,N.div2 (M+1)) :: (4,1,1)
               :: (od,zd,cd) :: t
        else (2,2,n+2*M) :: (4,2,N.div2 M+1) :: (od,zd,cd) :: t).
Proof.
  intros n M od zd cd t f w2 f2 H. cbn [fr_four] in H.
  destruct ((2 <=? M) &&
    (((od =? 8) && (zd =? 2)) || ((od =? 5) && (zd =? 1))))%N
    eqn:E; [|discriminate].
  apply andb_prop in E as [EM ED]. apply N.leb_le in EM.
  unfold o_ in H. destruct (N.odd M).
  - injection H as HW HF. split; [exact EM|].
    split; [exact (eq_sym HF)|exact (eq_sym HW)].
  - injection H as HW HF. split; [exact EM|].
    split; [exact (eq_sym HF)|exact (eq_sym HW)].
Qed.
Lemma front_done_clean_inv : forall q K t f q2 cw2 f2,
  lin_front_done q
    (fr_clean ((2,2,4)::(5,2,1)::(3,1,K)::t) f)
    = Some (q2,cw2,f2) ->
  (2 <= K)%N /\ q2 = q /\ f2 = f /\
  cw2 = lin_normalize_full
    ([(2,2,3 * N.div2 K + 4); (5,2,1); (3,2,N.div2 K)]
     ++ (if N.odd K then [(3,1,1)] else []) ++ t).
Proof.
  intros q K t f q2 cw2 f2 H.
  unfold lin_front_done in H.
  destruct (fr_clean _) as [[w ff| |]|] eqn:E; try discriminate.
  inversion H; subst q2 cw2 f2.
  destruct (fr_clean_inv K t f w ff E) as (HK & HF & HW).
  subst ff w. repeat split; reflexivity || assumption.
Qed.
Lemma front_done_four_inv : forall q n M t f q2 cw2 f2,
  lin_front_done q
    (fr_four ((2,2,n)::(4,2,1)::(4,1,M)::t) f)
    = Some (q2,cw2,f2) ->
  (2 <= M)%N /\ q2 = q /\ f2 = f /\
  cw2 = lin_normalize_full
    (if N.odd M
     then (2,2,n+2*(M-1)) :: (4,2,N.div2 (M+1)) :: (4,1,1) :: t
     else (2,2,n+2*M) :: (4,2,N.div2 M+1) :: t).
Proof.
  intros q n M t f q2 cw2 f2 H.
  unfold lin_front_done in H.
  destruct (fr_four _) as [[w ff| |]|] eqn:E; try discriminate.
  inversion H; subst q2 cw2 f2.
  destruct t as [|[[od zd] cd] t'];
    [cbn [fr_four] in E; discriminate|].
  destruct (fr_four_inv n M od zd cd t' f w ff E) as (HM & HF & HW).
  subst ff w. repeat split; reflexivity || assumption.
Qed.
Lemma front_finish_clean : forall sg P K t f q q2 cw2 f2,
  front_repr sg (P ++ t) ->
  forallb nobase P = true ->
  sound_impl (P ++ lin_flat sg t) f
    ((2,2,4)::(5,2,1)::(3,1,K)::lin_flat sg t) f ->
  lin_front_done q
    (fr_clean ((2,2,4)::(5,2,1)::(3,1,K)::t) f)
    = Some (q2,cw2,f2) ->
  sound_impl (lin_flat sg (P ++ t)) f
    (lin_flat sg cw2) f2 /\ front_repr sg cw2.
Proof.
  intros sg P K t f q q2 cw2 f2 HG HP HS HD.
  destruct (front_done_clean_inv q K t f q2 cw2 f2 HD)
    as (HK & Hq & Hf & Hw). subst q2 f2 cw2.
  destruct (N.odd K) eqn:EO; cbn [app] in *.
  - eapply (front_finish sg P
      [(2,2,3*N.div2 K+4); (5,2,1); (3,2,N.div2 K); (3,1,1)] t f);
      [exact HG|exact HP|reflexivity|].
    eapply sound_trans; [exact HS|].
    pose proof (sound_clean K (lin_flat sg t) f HK) as HC.
    rewrite EO in HC. exact HC.
  - eapply (front_finish sg P
      [(2,2,3*N.div2 K+4); (5,2,1); (3,2,N.div2 K)] t f);
      [exact HG|exact HP|reflexivity|].
    eapply sound_trans; [exact HS|].
    pose proof (sound_clean K (lin_flat sg t) f HK) as HC.
    rewrite EO in HC. exact HC.
Qed.
Lemma front_finish_four : forall sg P n M t f q q2 cw2 f2,
  front_repr sg (P ++ t) ->
  forallb nobase P = true ->
  sound_impl (P ++ lin_flat sg t) f
    ((2,2,n)::(4,2,1)::(4,1,M)::lin_flat sg t) f ->
  lin_front_done q
    (fr_four ((2,2,n)::(4,2,1)::(4,1,M)::t) f)
    = Some (q2,cw2,f2) ->
  sound_impl (lin_flat sg (P ++ t)) f
    (lin_flat sg cw2) f2 /\ front_repr sg cw2.
Proof.
  intros sg P n M t f q q2 cw2 f2 HG HP HS HD.
  destruct (front_done_four_inv q n M t f q2 cw2 f2 HD)
    as (HM & Hq & Hf & Hw). subst q2 f2 cw2.
  destruct (N.odd M) eqn:EO; cbn [app] in *.
  - eapply (front_finish sg P
      [(2,2,n+2*(M-1)); (4,2,N.div2 (M+1)); (4,1,1)] t f);
      [exact HG|exact HP|reflexivity|].
    eapply sound_trans; [exact HS|].
    pose proof (sound_four n M (lin_flat sg t) f HM) as HC.
    rewrite EO in HC. exact HC.
  - eapply (front_finish sg P
      [(2,2,n+2*M); (4,2,N.div2 M+1)] t f);
      [exact HG|exact HP|reflexivity|].
    eapply sound_trans; [exact HS|].
    pose proof (sound_four n M (lin_flat sg t) f HM) as HC.
    rewrite EO in HC. exact HC.
Qed.
Lemma front_arm_522_1 : forall sg c M t f q cw2 f2,
  front_repr sg
    ([(2,2,c); (4,1,1); (1,1,1); (4,1,M)] ++ t) ->
  lin_front_done 2
    (fr_four ((2,2,c+1)::(4,2,1)::(4,1,M)::t) f)
    = Some (q,cw2,f2) ->
  sound_impl
    (lin_flat sg ([(2,2,c); (4,1,1); (1,1,1); (4,1,M)] ++ t)) f
    (lin_flat sg cw2) f2 /\ front_repr sg cw2.
Proof.
  intros. eapply front_finish_four; [eassumption|reflexivity| |eassumption].
  cbn [app]. apply sound_522_1.
Qed.
Lemma front_arm_522_2 : forall sg c M t f q cw2 f2,
  front_repr sg
    ([(2,2,c); (4,1,1); (2,1,1); (4,1,M)] ++ t) ->
  lin_front_done 3
    (fr_four ((2,2,c+2)::(4,2,1)::(4,1,M)::t) f)
    = Some (q,cw2,f2) ->
  sound_impl
    (lin_flat sg ([(2,2,c); (4,1,1); (2,1,1); (4,1,M)] ++ t)) f
    (lin_flat sg cw2) f2 /\ front_repr sg cw2.
Proof.
  intros. eapply front_finish_four; [eassumption|reflexivity| |eassumption].
  cbn [app]. apply sound_522_2.
Qed.
Lemma front_arm_522_3 : forall sg c M t f q cw2 f2,
  front_repr sg
    ([(2,2,c); (4,1,1); (3,1,1); (4,1,M)] ++ t) ->
  lin_front_done 4
    (fr_four ((2,2,c+3)::(4,2,1)::(4,1,M)::t) f)
    = Some (q,cw2,f2) ->
  sound_impl
    (lin_flat sg ([(2,2,c); (4,1,1); (3,1,1); (4,1,M)] ++ t)) f
    (lin_flat sg cw2) f2 /\ front_repr sg cw2.
Proof.
  intros. eapply front_finish_four; [eassumption|reflexivity| |eassumption].
  cbn [app]. apply sound_522_3.
Qed.
