Lemma front_arm_512_1 : forall sg K t f q cw2 f2,
  front_repr sg
    ([(2,2,3); (5,1,1); (1,1,1); (3,1,K)] ++ t) ->
  lin_front_done 2
    (fr_clean ((2,2,4)::(5,2,1)::(3,1,K)::t) f)
    = Some (q,cw2,f2) ->
  sound_impl
    (lin_flat sg ([(2,2,3); (5,1,1); (1,1,1); (3,1,K)] ++ t)) f
    (lin_flat sg cw2) f2 /\ front_repr sg cw2.
Proof.
  intros. eapply front_finish_clean; [eassumption|reflexivity| |eassumption].
  cbn [app]. apply sound_512_1.
Qed.
Lemma front_arm_512_2 : forall sg K t f q cw2 f2,
