Lemma front_arm_512_1_eq : forall sg c k K t f q cw2 f2,
  k = 1%N -> c + k = 4%N ->
  front_repr sg
    ([(2,2,c); (5,1,1); (k,1,1); (3,1,K)] ++ t) ->
