Lemma front_arm_502 : forall sg K t f q cw2 f2,
  (3 <= K)%N ->
  front_repr sg ([(2,2,1); (5,1,1); (3,1,K)] ++ t) ->
  lin_front_done 4
    (fr_clean ((2,2,4)::(5,2,1)::(3,1,K-1)::t) f)
    = Some (q,cw2,f2) ->
  sound_impl
    (lin_flat sg ([(2,2,1); (5,1,1); (3,1,K)] ++ t)) f
    (lin_flat sg cw2) f2 /\ front_repr sg cw2.
Proof.
  intros sg K t f q cw2 f2 HK HG HD.
  eapply front_finish_clean; [exact HG|reflexivity| |exact HD].
  cbn [app]. eapply sound_trans.
  - apply sound_502; lia.
  - apply sound_512_2.
Qed.
Lemma front_arm_502_eq : forall sg c K t f q cw2 f2,
  c = 1%N -> (3 <= K)%N ->
  front_repr sg ([(2,2,c); (5,1,1); (3,1,K)] ++ t) ->
  lin_front_done 4
    (fr_clean ((2,2,4)::(5,2,1)::(3,1,K-1)::t) f)
    = Some (q,cw2,f2) ->
  sound_impl
    (lin_flat sg ([(2,2,c); (5,1,1); (3,1,K)] ++ t)) f
    (lin_flat sg cw2) f2 /\ front_repr sg cw2.
Proof. intros; subst c. eapply front_arm_502; eassumption. Qed.
Lemma front_arm_rot : forall sg K t f q cw2 f2,
  (2 <= K)%N ->
  front_repr sg ([(5,1,1); (4,1,1); (3,1,K)] ++ t) ->
  lin_front_done 5
    (fr_clean ((2,2,4)::(5,2,1)::(3,1,K)::t) f)
    = Some (q,cw2,f2) ->
  sound_impl
    (lin_flat sg ([(5,1,1); (4,1,1); (3,1,K)] ++ t)) f
    (lin_flat sg cw2) f2 /\ front_repr sg cw2.
Proof.
  intros sg K t f q cw2 f2 HK HG HD.
  eapply front_finish_clean; [exact HG|reflexivity| |exact HD].
  cbn [app].
  pose proof (rot_sound K (lin_flat sg t) f) as S0.
  assert (S1 : sound_impl
    ((2,2,1)::(5,1,1)::(3,1,K+1)::lin_flat sg t) f
    ((2,2,2)::(5,1,1)::(2,1,1)::(3,1,K)::lin_flat sg t) f).
  { replace K with (K + 1 - 1) at 2 by lia.
    apply sound_502. lia. }
  pose proof (sound_512_2 2
    ((3,1,K)::lin_flat sg t) f) as S2.
  exact (sound_trans _ _ _ _ _ _ S0
    (sound_trans _ _ _ _ _ _ S1 S2)).
Qed.
Ltac digsH H :=
  repeat match type of H with
  | context [match ?x with N0 => _ | N.pos _ => _ end] =>
      is_var x; destruct x; try discriminate
  | context [match ?x with xI _ => _ | xO _ => _ | xH => _ end] =>
      is_var x; destruct x; try discriminate
  end.
Ltac front_prep H :=
  repeat match type of H with
  | context [if ?b then _ else _] =>
      let E := fresh "EB" in destruct b eqn:E; try discriminate
  end;
  repeat match goal with
  | E : (_ && _)%bool = true |- _ =>
      let E2 := fresh "EB" in
      apply andb_prop in E; destruct E as [E E2]
  end;
  repeat match goal with
  | E : (_ <=? _)%N = true |- _ => apply N.leb_le in E
  | E : (_ =? _)%N = true |- _ => apply N.eqb_eq in E
  end;
  try (exfalso; lia).
Ltac close_front_case HG HC :=
  lazymatch type of HG with
  | front_repr _ ((5,1,1) :: (4,1,1) :: (3,1,?K) :: ?t) =>
      eapply front_arm_rot; [lia|exact HG|exact HC]
  | front_repr _ ((2,2,?c) :: (5,1,1) :: (3,1,?K) :: ?t) =>
      eapply front_arm_502_eq; [lia|lia|exact HG|exact HC]
  | front_repr _ ((2,2,?c) :: (5,1,1) :: (?k,1,1) ::
                    (3,1,?K) :: ?t) =>
      first
        [ match goal with
          | Hk : k = 1%N |- _ =>
              eapply front_arm_512_1_eq;
                [exact Hk|lia|exact HG|exact HC]
          end
        | match goal with
          | Hk : k = 2%N |- _ =>
              eapply front_arm_512_2_eq;
                [exact Hk|lia|exact HG|exact HC]
          end ]
  | front_repr _ ((2,2,?c) :: (4,1,1) :: (?k,1,1) ::
                    (4,1,?M) :: ?t) =>
      first
        [ match goal with
          | Hk : k = 1%N |- _ =>
              eapply front_arm_522_1_eq; [exact Hk|exact HG|exact HC]
          end
        | match goal with
          | Hk : k = 2%N |- _ =>
              eapply front_arm_522_2_eq; [exact Hk|exact HG|exact HC]
          end
        | match goal with
          | Hk : k = 3%N |- _ =>
              eapply front_arm_522_3_eq; [exact Hk|exact HG|exact HC]
          end ]
  end.
Ltac close_front_case_assumption HG :=
  lazymatch type of HG with
  | front_repr _ ((5,1,1) :: (4,1,1) :: (3,1,?K) :: ?t) =>
      eapply front_arm_rot; [lia|exact HG|eassumption]
  | front_repr _ ((2,2,?c) :: (5,1,1) :: (3,1,?K) :: ?t) =>
      eapply front_arm_502_eq; [lia|lia|exact HG|eassumption]
  | front_repr _ ((2,2,?c) :: (5,1,1) :: (?k,1,1) ::
                    (3,1,?K) :: ?t) =>
      first
        [ match goal with
          | Hk : k = 1%N |- _ =>
              eapply front_arm_512_1_eq;
                [exact Hk|lia|exact HG|eassumption]
          end
        | match goal with
          | Hk : k = 2%N |- _ =>
              eapply front_arm_512_2_eq;
                [exact Hk|lia|exact HG|eassumption]
          end ]
  | front_repr _ ((2,2,?c) :: (4,1,1) :: (?k,1,1) ::
                    (4,1,?M) :: ?t) =>
      first
        [ match goal with
          | Hk : k = 1%N |- _ =>
              eapply front_arm_522_1_eq; [exact Hk|exact HG|eassumption]
          end
        | match goal with
          | Hk : k = 2%N |- _ =>
              eapply front_arm_522_2_eq; [exact Hk|exact HG|eassumption]
          end
        | match goal with
          | Hk : k = 3%N |- _ =>
              eapply front_arm_522_3_eq; [exact Hk|exact HG|eassumption]
          end ]
  end.
Lemma front_done_clean_edges : forall q pre f q2 cw2 f2,
  tag_edges pre ->
  lin_front_done q (fr_clean pre f) = Some (q2,cw2,f2) ->
  tag_edges cw2.
Proof.
  intros q pre f q2 cw2 f2 HE H.
  unfold lin_front_done in H.
  destruct (fr_clean pre f) as [[w ff| |]|] eqn:E;
    try discriminate.
  injection H as <- <- <-.
  apply tag_edges_normalize_full.
  exact (fr_clean_edges_probe pre f w ff E HE).
Qed.
Lemma front_done_four_edges : forall q pre f q2 cw2 f2,
  tag_edges pre ->
  lin_front_done q (fr_four pre f) = Some (q2,cw2,f2) ->
  tag_edges cw2.
Proof.
  intros q pre f q2 cw2 f2 HE H.
  unfold lin_front_done in H.
  destruct (fr_four pre f) as [[w ff| |]|] eqn:E;
    try discriminate.
  injection H as <- <- <-.
  apply tag_edges_normalize_full.
  exact (fr_four_edges_probe pre f w ff E HE).
Qed.
Lemma close_edges_3to3 : forall a b l p q r t,
  tag_edges (a :: b :: l :: t) ->
  ~ side8 l -> shape_free [p;q;r] ->
  tag_edges (p :: q :: r :: t).
Proof.
  intros a b l p q r t HE HN HF.
  exact (tag_edges_replace_prefix_probe
    [a;b] l [p;q;r] t HE HN HF).
Qed.
Lemma close_edges_4to3 : forall a b c l p q r t,
  tag_edges (a :: b :: c :: l :: t) ->
  ~ side8 l -> shape_free [p;q;r] ->
  tag_edges (p :: q :: r :: t).
Proof.
  intros a b c l p q r t HE HN HF.
  exact (tag_edges_replace_prefix_probe
    [a;b;c] l [p;q;r] t HE HN HF).
Qed.
Ltac close_front_pre_edges HE p0 p1 p2 t :=
  let HP := fresh "HPreEdges" in
  assert (HP : tag_edges (p0 :: p1 :: p2 :: t));
  [ first
      [ lazymatch type of HE with
        | tag_edges (?a :: ?b :: ?c :: ?l :: ?t0) =>
            unify t0 t;
            eapply close_edges_4to3
        end
      | lazymatch type of HE with
        | tag_edges (?a :: ?b :: ?l :: ?t0) =>
            unify t0 t;
            eapply close_edges_3to3
        end ];
    [ exact HE
    | intros [_ Hside]; discriminate Hside
    | unfold shape_free;
      shape_lits_probe ]
  | idtac ].
Ltac close_front_edges_case HE HC :=
  lazymatch type of HC with
  | lin_front_done _
      (fr_clean (?p0 :: ?p1 :: ?p2 :: ?t) _) = _ =>
      close_front_pre_edges HE p0 p1 p2 t;
      eapply front_done_clean_edges; [eassumption|exact HC]
  | lin_front_done _
      (fr_four (?p0 :: ?p1 :: ?p2 :: ?t) _) = _ =>
      close_front_pre_edges HE p0 p1 p2 t;
      eapply front_done_four_edges; [eassumption|exact HC]
  end.
Ltac close_front_case_auto HG :=
  match goal with
  | HD : lin_front_done ?q ?r = ?x |- _ =>
      close_front_case HG HD
  end.
Ltac close_front_edges_case_auto HE :=
  match goal with
  | HD : lin_front_done ?q ?r = ?x |- _ =>
      close_front_edges_case HE HD
  end.
Inductive front_close_case : word -> N -> nat -> word -> N -> Prop :=
  | FCC_rot (K : N) (t : word) (f : N)
      (q : nat) (cw2 : word) (f2 : N) :
      (2 <= K)%N ->
      lin_front_done 5
        (fr_clean ((2,2,4)%N :: (5,2,1)%N :: (3,1,K)%N :: t) f)
        = Some (q, cw2, f2) ->
      front_close_case ([(5,1,1); (4,1,1); (3,1,K)]%N ++ t)
        f q cw2 f2
  | FCC_502 (c K : N) (t : word) (f : N)
      (q : nat) (cw2 : word) (f2 : N) :
      c = 1%N -> (3 <= K)%N ->
      lin_front_done 4
        (fr_clean ((2,2,4)%N :: (5,2,1)%N :: (3,1,K-1)%N :: t) f)
        = Some (q, cw2, f2) ->
      front_close_case ([(2,2,c); (5,1,1); (3,1,K)]%N ++ t)
        f q cw2 f2
  | FCC_512_1 (c k K : N) (t : word) (f : N)
      (q : nat) (cw2 : word) (f2 : N) :
      k = 1%N -> (c + k = 4)%N ->
      lin_front_done 2
        (fr_clean ((2,2,4)%N :: (5,2,1)%N :: (3,1,K)%N :: t) f)
        = Some (q, cw2, f2) ->
      front_close_case
        ([(2,2,c); (5,1,1); (k,1,1); (3,1,K)]%N ++ t) f q cw2 f2
  | FCC_512_2 (c k K : N) (t : word) (f : N)
      (q : nat) (cw2 : word) (f2 : N) :
      k = 2%N -> (c + k = 4)%N ->
      lin_front_done 3
        (fr_clean ((2,2,4)%N :: (5,2,1)%N :: (3,1,K)%N :: t) f)
        = Some (q, cw2, f2) ->
      front_close_case
        ([(2,2,c); (5,1,1); (k,1,1); (3,1,K)]%N ++ t) f q cw2 f2
  | FCC_522_1 (c k M : N) (t : word) (f : N)
      (q : nat) (cw2 : word) (f2 : N) :
      k = 1%N ->
      lin_front_done 2
        (fr_four ((2,2,c+1)%N :: (4,2,1)%N :: (4,1,M)%N :: t) f)
        = Some (q, cw2, f2) ->
      front_close_case
        ([(2,2,c); (4,1,1); (k,1,1); (4,1,M)]%N ++ t) f q cw2 f2
  | FCC_522_2 (c k M : N) (t : word) (f : N)
      (q : nat) (cw2 : word) (f2 : N) :
      k = 2%N ->
      lin_front_done 3
        (fr_four ((2,2,c+2)%N :: (4,2,1)%N :: (4,1,M)%N :: t) f)
        = Some (q, cw2, f2) ->
      front_close_case
        ([(2,2,c); (4,1,1); (k,1,1); (4,1,M)]%N ++ t) f q cw2 f2
  | FCC_522_3 (c k M : N) (t : word) (f : N)
      (q : nat) (cw2 : word) (f2 : N) :
      k = 3%N ->
      lin_front_done 4
        (fr_four ((2,2,c+3)%N :: (4,2,1)%N :: (4,1,M)%N :: t) f)
        = Some (q, cw2, f2) ->
      front_close_case
        ([(2,2,c); (4,1,1); (k,1,1); (4,1,M)]%N ++ t) f q cw2 f2.
Ltac close_front_view HC :=
  first
    [ eapply FCC_rot; [lia|exact HC]
    | eapply FCC_502; [lia|lia|exact HC]
    | match goal with
      | Hk : _ = 1%N |- _ => eapply FCC_512_1; [exact Hk|lia|exact HC]
      end
    | match goal with
      | Hk : _ = 2%N |- _ => eapply FCC_512_2; [exact Hk|lia|exact HC]
      end
    | match goal with
      | Hk : _ = 1%N |- _ => eapply FCC_522_1; [exact Hk|exact HC]
      end
    | match goal with
      | Hk : _ = 2%N |- _ => eapply FCC_522_2; [exact Hk|exact HC]
      end
    | match goal with
      | Hk : _ = 3%N |- _ => eapply FCC_522_3; [exact Hk|exact HC]
      end ].
Theorem lin_front_close_case_of (cw : word) (f : N)
      (q : nat) (cw2 : word) (f2 : N) :
  lin_front_close cw f = Some (q, cw2, f2) ->
  front_close_case cw f q cw2 f2.
Proof.
  intros HC.
  unfold lin_front_close in HC.
  destruct (lin_front_shape_of cw) as [s|] eqn:ES;
    [|discriminate].
  destruct s; cbn [lin_front_shape_run] in HC;
    front_prep HC; close_front_view HC.
Qed.
Definition T_front_close_stable : Prop :=
  forall sg cw f q cw2 f2,
    front_repr sg cw ->
    lin_front_close cw f = Some (q, cw2, f2) ->
    (sound_impl (lin_flat sg cw) f
       (lin_flat sg cw2) f2 /\ front_repr sg cw2) /\
    (tag_edges cw -> tag_edges cw2).
Theorem T_front_close_stable_holds : T_front_close_stable.
Proof.
  intros sg cw f q cw2 f2 HG HC.
  pose proof (lin_front_close_case_of cw f q cw2 f2 HC) as HCase.
  clear HC. revert sg HG.
  destruct HCase; intros sg HG.
  all: cbn [app] in HG |- *.
  all: split; [close_front_case_assumption HG|].
  all: intros HE; close_front_edges_case_auto HE.
Qed.
Open Scope N_scope.
Open Scope bool_scope.
Opaque LROUND_FUEL LROUND_CHUNKS
       FLAT_ROUND_FUEL CFUEL TRIES.
Lemma firstn_nbrs_of_notlast : forall sg w i,
  ph_nbrs sg w ->
  ph_notlast sg (firstn i w) ->
  ph_nbrs sg (firstn i w).
Proof.
  intros sg w i HN HL p g Hp Hph.
  assert (HpL : (p < length (firstn i w))%nat).
  { apply nth_error_Some. rewrite Hp. discriminate. }
  assert (Hpi : (p < i)%nat).
  { rewrite length_firstn in HpL. lia. }
  assert (Hpw : nth_error w p = Some g).
  { rewrite <- (firstn_skipn i w).
    rewrite nth_error_app1; [exact Hp|].
    exact HpL. }
  destruct (HN p g Hpw Hph) as ((gr & Hgr & Hsp) & Hleft).
  split.
  - exists gr. split; [|exact Hsp].
    pose proof (HL p g Hp Hph) as Hnext.
    rewrite nth_error_firstn.
    replace (PeanoNat.Nat.ltb (p + 1) i) with true
      by (symmetry; apply PeanoNat.Nat.ltb_lt;
          rewrite length_firstn in Hnext; lia).
    exact Hgr.
  - intros gl Hp1 Hgl. apply (Hleft gl Hp1).
    rewrite <- (firstn_skipn i w).
    rewrite nth_error_app1; [exact Hgl|].
    apply (proj1 (nth_error_Some (firstn i w) (p - 1))).
    rewrite Hgl. discriminate.
Qed.
Lemma firstn_mend_of_site : forall sg w i g u,
  ph_margins sg w ->
  skipn i w = g :: u -> casc g = false ->
  mend sg (firstn i w).
Proof.
  intros sg w i g u HM ES HC p gp Hp Hph.
  assert (Hiw : (i < length w)%nat).
  { apply PeanoNat.Nat.lt_nge. intros Hle.
    rewrite skipn_all2 in ES by lia. discriminate. }
  assert (HpL : (p < i)%nat).
  { assert (Hp' : (p < length (firstn i w))%nat).
    { apply (proj1 (nth_error_Some (firstn i w) p)).
      rewrite Hp. discriminate. }
    rewrite firstn_length_le in Hp' by lia. exact Hp'. }
  assert (Hpw : nth_error w p = Some gp).
  { rewrite <- (firstn_skipn i w).
    rewrite nth_error_app1.
    - exact Hp.
    - rewrite firstn_length_le by lia. exact HpL. }
  destruct (HM p gp Hpw Hph) as (_ & _ & HW).
  destruct (PeanoNat.Nat.lt_ge_cases (p + 3) i) as [Hlt|Hge];
    [rewrite firstn_length_le by lia; exact Hlt|].
  exfalso.
  destruct (HW i ltac:(unfold GUARD; lia)
              ltac:(unfold GUARD; lia) ltac:(lia))
    as (gi & Hgi & Hci & _).
  assert (Hsite : nth_error w i = Some g).
  { replace i with (i + O)%nat by lia.
    rewrite <- (nth_skipn i O w), ES. reflexivity. }
  rewrite Hsite in Hgi. injection Hgi as <-. congruence.
Qed.
Lemma firstn_head_nonph : forall sg w i,
  ph_margins sg w ->
  forall g t, firstn i w = g :: t -> ph sg g = false.
Proof.
  intros sg w i HM g t E.
  assert (Hin : In g (firstn 1 w)).
  { destruct w as [|g0 w'].
    - destruct i; discriminate E.
    - destruct i; [discriminate E|]. cbn [firstn] in E.
    injection E as <- _. left. reflexivity. }
  exact (margins_firstn_phfree sg w 1 HM
           ltac:(unfold GUARD; lia) g Hin).
Qed.
Lemma firstn_zspack_of_site : forall sg w i g u,
  ph_margins sg w -> ph_nbrs sg w ->
  skipn i w = g :: u -> casc g = false ->
  zspack sg (firstn i w).
Proof.
  intros sg w i g u HM HN ES HC. split; [|split].
  - exact (firstn_mend_of_site sg w i g u HM ES HC).
  - apply firstn_nbrs_of_notlast; [exact HN|].
    exact (margins_ph_notlast sg w i g u HM ES HC).
  - exact (firstn_head_nonph sg w i HM).
Qed.
Lemma jump_comp_out_tag : forall sg pre B post f k body f2,
  sg_wf sg -> keys_big sg ->
  zspack sg pre ->
  ph_margins sg ((4,3,1)::(4,2,B)::post) ->
  ph_nbrs sg ((4,3,1)::(4,2,B)::post) ->
  jump_comp pre B post f = Some (k, body, f2) ->
  zpack sg body.
Proof.
  intros sg pre B post f k body f2 HW HK HP HM HN HRun.
  unfold jump_comp in HRun.
  destruct post as [|gr2 rest2t].
  { destruct (f =? 4)%N.
    - destruct (lawR_seg pre B) as [body0|] eqn:ELR;
        [|discriminate].
      injection HRun as <- <- <-.
      exact (lawR_out_tag sg pre B body0 HK HP ELR).
    - destruct (5 <=? f)%N; [|discriminate].
      destruct (jump_seg pre B) as [seg|] eqn:EJP;
        [|discriminate].
      injection HRun as <- <- <-.
      apply zpack_app.
      + exact (jump_out_tag sg pre B seg HK HP EJP).
      + apply zpack_lits. lits_nonph HK. }
  destruct (jump_seg pre B) as [seg|] eqn:EJS;
    [|discriminate].
  cbv beta iota in HRun.
  destruct (seek (gr2::rest2t)) as [cols2 s3] eqn:ESK2.
  pose proof (LineageGuard_seek_split (gr2::rest2t)) as HSPL2.
  rewrite ESK2 in HSPL2. cbn [fst snd] in HSPL2.
  assert (HNr2 : ph_nbrs sg (gr2::rest2t))
    by (exact (ph_nbrs_tail sg _ _
                (ph_nbrs_tail sg _ _ HN))).
  assert (HMEc2 : mend sg cols2).
  { pose proof (mend_seek sg
                  ((4,3,1)::(4,2,B)::[]) (gr2::rest2t) HM) as H0.
    rewrite ESK2 in H0. exact H0. }
  assert (HNc2 : ph_nbrs sg cols2).
  { pose proof (ph_nbrs_seek_fst sg (gr2::rest2t) HNr2)
      as H0. rewrite ESK2 in H0. exact H0. }
  assert (HHc2 : forall g u, cols2 = g::u -> ph sg g = false).
  { intros g u E. assert (Hg2 : gr2 = g).
    { rewrite E in HSPL2. cbn [app] in HSPL2.
      injection HSPL2 as <- _. reflexivity. }
    subst gr2. exact (nbrs_excl sg _ 1%nat _ _ HN
                       eq_refl eq_refl eq_refl). }
  assert (HPc2 : zspack sg cols2)
    by (exact (conj HMEc2 (conj HNc2 HHc2))).
  assert (HM3 : ph_margins sg s3).
  { destruct s3 as [|g7 s3t].
    { intros p g Hp Hph. destruct p; discriminate. }
    assert (Hst7 : seektest g7 = false)
      by (apply (seek_snd_head (gr2::rest2t) g7 s3t);
          rewrite ESK2; reflexivity).
    assert (Hnc7 : casc g7 = false)
      by (exact (seektest_noncasc _ Hst7)).
    assert (HEq3 : (4,3,1)::(4,2,B)::gr2::rest2t
        = ((4,3,1)::(4,2,B)::cols2) ++ g7::s3t)
      by (cbn [app]; f_equal; f_equal; exact HSPL2).
    exact (margins_cut_at sg _ _ _ _ HM HEq3 Hnc7
             (seektest_notag _ Hst7)). }
  assert (HN3 : ph_nbrs sg s3)
    by (exact (ph_nbrs_app_r sg cols2 s3
                (ph_nbrs_at_eq sg _ _ HNr2 HSPL2))).
  assert (HJ : zpack sg seg)
    by (exact (jump_out_tag sg pre B seg HK HP EJS)).
  match type of HRun with
  | context [renew_seg ?nn ?cc ?ss ?ff] =>
      destruct (renew_seg nn cc ss ff) as [[body0 f0]|] eqn:ERN2
  end.
  { cbv beta iota in HRun. injection HRun as <- <- <-.
    apply zpack_app; [exact HJ|].
    exact (proj2 (fire_renew_out_tag _ sg HW HK)
             cols2 s3 f body0 f0 HPc2 HM3 HN3 ERN2). }
  cbv beta iota in HRun.
  destruct s3 as [|[[o7 z7] c7] s3t].
  { cbn [leaf_act] in HRun. cbv beta iota in HRun.
    destruct (5 <=? f)%N.
    { injection HRun as <- <- <-.
      apply zpack_app; [exact HJ|].
      apply (zpack_zspack_app sg cols2 [(f-1,1,1)] HPc2).
      apply zpack_lits. lits_nonph HK. }
    destruct (f =? 4)%N; [|discriminate].
    match type of HRun with
    | context [dtb4_conv ?ww] =>
        destruct (dtb4_conv ww) as [cols2'|] eqn:EDC
    end.
    2:{ cbv beta iota in HRun. destruct (forallb w42 cols2);
          [|discriminate].
        destruct (lawR_seg pre B) as [seg2|] eqn:ELR2;
          [|discriminate].
        injection HRun as <- <- <-.
        apply zpack_app.
        - exact (lawR_out_tag sg pre B seg2 HK HP ELR2).
        - exact (zpack_zspack sg cols2 HPc2). }
    cbv beta iota in HRun. injection HRun as <- <- <-.
    destruct (dtb4_out_tag sg cols2 cols2' HK HNc2 EDC)
      as (HD1 & HD3).
    apply zpack_app; [exact HJ|].
    exact (zpack_of_head_origin sg cols2 cols2' HK
             HHc2 HD1 HD3). }
  destruct ((z7 =? 3) && (c7 =? 1))%N eqn:E73.
  { cbv beta iota in HRun.
    match type of HRun with
    | context [fire_comp ?nn ?ww ?ff] =>
        destruct (fire_comp nn ww ff) as [[s3' f3']|] eqn:EFC3
    end.
    { cbv beta iota in HRun. injection HRun as <- <- <-.
      apply zpack_app; [exact HJ|].
      apply (zpack_zspack_app sg cols2 s3' HPc2).
      exact (proj1 (fire_renew_out_tag _ sg HW HK)
               _ f s3' f3' HM3 HN3 EFC3). }
    cbv beta iota in HRun. discriminate. }
  cbv beta iota in HRun.
  match type of HRun with
  | context [sand_leaf ?ww] => destruct (sand_leaf ww)
  end; [cbv beta iota in HRun; discriminate|].
  cbv beta iota in HRun.
  match type of HRun with
  | context [leaf_act ?ww ?ff] =>
      destruct (leaf_act ww ff) as [[s3' f3']|] eqn:ELA3
  end.
  2:{ cbv beta iota in HRun. discriminate. }
  cbv beta iota in HRun. injection HRun as <- <- <-.
  apply zpack_app; [exact HJ|].
  apply (zpack_zspack_app sg cols2 s3' HPc2).
  exact (zpack_of_npack sg s3'
    (leaf_npack_out_tag sg _ f s3' f3'
      HW HK HM3 HN3 ELA3)).
Qed.
Lemma site_comp_out_tag : forall sg w i f k body f2,
  sg_wf sg -> keys_big sg ->
  ph_margins sg w -> ph_nbrs sg w ->
  site_comp w i f = Some (k, body, f2) ->
  zpack sg body.
Proof.
  intros sg w i f k body f2 HW HK HM HN HRun.
  destruct (site_comp_head sg w i f k body f2 HRun)
    as (g & u & ES & Hph & Hcasc & Hnotag).
  assert (HP : zspack sg (firstn i w))
    by (exact (firstn_zspack_of_site sg w i g u HM HN ES Hcasc)).
  assert (HMs : ph_margins sg (skipn i w)).
  { rewrite ES.
    exact (margins_cut_at sg w (firstn i w) g u HM
      ltac:(rewrite <- ES; symmetry; apply firstn_skipn) Hcasc Hnotag). }
  assert (HNs : ph_nbrs sg (skipn i w)).
  { pose proof (ph_nbrs_app_r sg (firstn i w) (skipn i w)
      ltac:(rewrite firstn_skipn; exact HN)) as H0.
    exact H0. }
  unfold site_comp in HRun.
  destruct (skipn i w) as [|[[o4 z4] c4] s2t] eqn:ES0;
    [discriminate|].
  destruct ((o4 =? 4) && (z4 =? 3) && (c4 =? 1)
            && Nat.leb 3 i)%N eqn:E43.
  { apply andb_prop in E43 as [E43 _].
    apply andb_prop in E43 as [E43 Ec4].
    apply andb_prop in E43 as [Eo4 Ez4].
    apply N.eqb_eq in Eo4, Ez4, Ec4. subst o4 z4 c4.
    cbv beta iota in HRun.
    destruct s2t as [|[[o5 z5] b5] rest2].
    - destruct (endR_seg (firstn i w) f) as [body0|] eqn:EER;
        [|discriminate].
      injection HRun as <- <- <-.
      exact (endR_out_tag sg (firstn i w) f body0 HK HP EER).
    - destruct ((o5 =? 4) && (z5 =? 2))%N eqn:E52.
      + cbv beta iota in HRun.
        destruct (1 <=? b5)%N eqn:EB; [|discriminate].
        apply andb_prop in E52 as [Eo5 Ez5].
        apply N.eqb_eq in Eo5, Ez5. subst o5 z5.
        exact (jump_comp_out_tag sg (firstn i w) b5 rest2
                 f k body f2 HW HK HP HMs HNs HRun).
      + cbv beta iota in HRun.
        destruct ((z5 =? 3) && (b5 =? 1)
                  && match rest2 with [] => true | _ :: _ => false end
                  && (f =? 4) && (1 <=? o5))%N eqn:EREN.
        * destruct (endY_seg (firstn i w) o5) as [body0|] eqn:EEY;
            [|discriminate].
          injection HRun as <- <- <-.
          exact (endY_out_tag sg (firstn i w) o5 body0
                   HK HP EEY).
        * match type of HRun with
          | context [fire_comp ?nn ?ss ?ff] =>
              destruct (fire_comp nn ss ff)
                as [[body0 f0]|] eqn:EFC in HRun
          end; [|discriminate].
          cbv beta iota in HRun. injection HRun as <- <- <-.
          exact (proj1 (fire_renew_out_tag _ sg HW HK)
                   _ f body0 f0 HMs HNs EFC). }
  cbv beta iota in HRun.
  destruct ((z4 =? 3) && (c4 =? 1))%N eqn:E3.
  { match type of HRun with
    | context [fire_comp ?nn ?ss ?ff] =>
        destruct (fire_comp nn ss ff) as [[body0 f0]|] eqn:EFC in HRun
    end; [|discriminate].
    cbv beta iota in HRun. injection HRun as <- <- <-.
    exact (proj1 (fire_renew_out_tag _ sg HW HK)
             _ f body0 f0 HMs HNs EFC). }
  cbv beta iota in HRun.
  destruct (z4 =? 1)%N eqn:E1.
  { match type of HRun with
    | context [leaf_act ?ss ?ff] =>
        destruct (leaf_act ss ff) as [[body0 f0]|] eqn:ELA in HRun
    end; [|discriminate].
    cbv beta iota in HRun. injection HRun as <- <- <-.
    exact (zpack_of_npack sg body0
      (leaf_npack_out_tag sg _ f body0 f0
        HW HK HMs HNs ELA)). }
  cbv beta iota in HRun.
  destruct ((z4 =? 4) && (c4 =? 1))%N eqn:E4; [|discriminate].
  apply andb_prop in E4 as [Ez4 Ec4].
  apply N.eqb_eq in Ez4, Ec4. subst z4 c4.
  destruct s2t as [|[[on zn] cn] t2].
  2:{ destruct ((o4 =? 4) && (on =? 4) && (zn =? 2)
                 && (1 <=? cn))%N eqn:EA.
      - apply andb_prop in EA as [EA _].
        apply andb_prop in EA as [EA Ezn].
        apply andb_prop in EA as [Eo4 Eon].
        apply N.eqb_eq in Eo4, Eon, Ezn. subst o4 on zn.
        assert (HT : zpack sg t2).
        { apply zpack_zspack. split; [|split].
          - apply (mend_tail_word sg [(4,4,1);(4,2,cn)]).
            exact HMs.
          - exact (ph_nbrs_tail sg _ _
                    (ph_nbrs_tail sg _ _ HNs)).
          - intros gt tt Et. subst t2.
            exact (nbrs_excl sg _ 1%nat _ _ HNs
                     eq_refl eq_refl eq_refl). }
        cbv beta iota in HRun.
        destruct (last2 (firstn i w))
          as [[[ini [[ga gaz] gac]] [[gb gbz] gbc]]|] eqn:EL;
          [|discriminate].
        lazymatch type of HRun with
        | (if ?b then _ else _) = _ => destruct b eqn:EG in HRun
        end; [|discriminate].
        apply andb_prop in EG as [EG Egbc].
        apply andb_prop in EG as [EG Egbz].
        apply andb_prop in EG as [EG Egb].
        apply andb_prop in EG as [EG Egac].
        apply andb_prop in EG as [EG Egaz].
        apply N.eqb_eq in EG, Egaz, Egac, Egb, Egbz.
        subst ga gaz gac gb gbz.
        set (seg := ini ++
          [(7,1,1);(3,2,1);(4,2,gbc);(8,2,1)] ++
          (if 1 <? cn then [(4,2,cn-1)] else [])).
        assert (EJP : jump_seg (firstn i w) cn = Some seg).
        { unfold jump_seg. rewrite EL. cbv beta iota. rewrite Egbc.
          reflexivity. }
        cbv beta iota in HRun. injection HRun as <- <- <-.
        pose proof (zpack_app sg seg t2
          (jump_out_tag sg (firstn i w) cn seg HK HP EJP) HT)
          as Hout.
        unfold seg in Hout. rewrite <- !app_assoc in Hout. exact Hout.
      - cbv beta iota in HRun.
        destruct ((4 <? o4) && (on =? 4) && (zn =? 2)
                  && (1 <=? cn))%N eqn:EB; [|discriminate].
        apply andb_prop in EB as [EB _].
        apply andb_prop in EB as [EB Ezn].
        apply andb_prop in EB as [_ Eon].
        apply N.eqb_eq in Eon, Ezn. subst on zn.
        assert (HT : zpack sg t2).
        { apply zpack_zspack. split; [|split].
          - apply (mend_tail_word sg [(o4,4,1);(4,2,cn)]).
            exact HMs.
          - exact (ph_nbrs_tail sg _ _
                    (ph_nbrs_tail sg _ _ HNs)).
          - intros gt tt Et. subst t2.
            exact (nbrs_excl sg _ 1%nat _ _ HNs
                     eq_refl eq_refl eq_refl). }
        injection HRun as <- <- <-.
        apply (zpack_lits_app sg
          ((o4-1,1,1)::(7,2,1)::
             (if 1 <? cn then [(4,2,cn-1)] else [])) t2).
        + intros gt Hin.
          destruct (1 <? cn)%N; cbn [app In] in Hin;
            repeat (destruct Hin as [<-|Hin]); try (destruct Hin);
            litnp HK.
        + exact HT. }
  destruct ((o4 =? 4) && (1 <=? f))%N eqn:EO; [|discriminate].
  apply andb_prop in EO as [Eo4 _]. apply N.eqb_eq in Eo4. subst o4.
  cbv beta iota in HRun.
  destruct (last2 (firstn i w))
    as [[[ini [[ga gaz] gac]] [[gb gbz] gbc]]|] eqn:EL;
    [|discriminate].
  pose proof (LineageGuard_last2_split (firstn i w) ini
    (ga,gaz,gac) (gb,gbz,gbc) EL) as EP.
  pose proof HP as HPi. rewrite EP in HPi.
  destruct HPi as (HMi & HNi & HHi).
  destruct (mend_last2_nonph sg ini
    (ga,gaz,gac) (gb,gbz,gbc) HMi) as [Hpa Hpb].
  lazymatch type of HRun with
  | (if ?b then _ else _) = _ => destruct b eqn:EG1 in HRun
  end.
  { cbv beta iota in HRun. injection HRun as <- <- <-.
    apply (zpack_ini_lits sg ini
      (ga,gaz,gac) (gb,gbz,gbc)
      [(7,1,1);(3,2,1);(gb,gbz,gbc)] HMi HNi HHi).
    intros gt Hin. repeat (destruct Hin as [<-|Hin]); try (destruct Hin);
      first [exact Hpb | litnp HK]. }
  lazymatch type of HRun with
  | (if ?b then _ else _) = _ => destruct b eqn:EG2 in HRun
  end; [|discriminate].
  cbv beta iota in HRun. injection HRun as <- <- <-.
  apply (zpack_ini_lits sg ini
    (ga,gaz,gac) (gb,gbz,gbc)
    [(ga,gaz,gac);(7,1,1);(3,2,1)] HMi HNi HHi).
  intros gt Hin. repeat (destruct Hin as [<-|Hin]); try (destruct Hin);
    first [exact Hpa | litnp HK].
Qed.
Open Scope N_scope.
Open Scope bool_scope.
Opaque LROUND_FUEL LROUND_CHUNKS
       FLAT_ROUND_FUEL CFUEL TRIES.
Lemma master_nonph : forall sg J,
  ph sg (2%N,2%N,J) = false.
Proof.
  intros sg J. apply notag_ph.
  unfold notag, phshape, tagbase, PHO.
  reflexivity.
Qed.
Lemma master_noncasc : forall J,
  casc (2%N,2%N,J) = false.
Proof.
  intros J. unfold casc, is_lvl, is_spc.
  cbn [gO gZ gC]. reflexivity.
Qed.
Lemma margins_master_change : forall sg A B t,
  ph_margins sg ((2,2,A) :: t) ->
  ph_margins sg ((2,2,B) :: t).
Proof.
  intros sg A B t HM [|j] g Hj Hph.
  - cbn [nth_error] in Hj. injection Hj as <-.
    rewrite master_nonph in Hph. discriminate.
  - destruct (HM (S j) g Hj Hph) as (Hlo & Hhi & HW).
    split; [exact Hlo|]. split; [exact Hhi|].
    intros [|j'] Hjlo Hjhi Hne.
    + destruct (HW O Hjlo Hjhi Hne) as (g' & Hg' & Hc & Hnp).
      cbn [nth_error] in Hg'. injection Hg' as <-.
      rewrite master_noncasc in Hc. discriminate.
    + destruct (HW (S j') Hjlo Hjhi Hne) as (g' & Hg' & Hc & Hnp).
      exists g'. repeat split; assumption.
Qed.
Lemma nbrs_master_change : forall sg A B t,
  ph_nbrs sg ((2,2,A) :: t) ->
  ph_nbrs sg ((2,2,B) :: t).
Proof.
  intros sg A B t HN [|p] g Hp Hph.
  - cbn [nth_error] in Hp. injection Hp as <-.
    rewrite master_nonph in Hph. discriminate.
  - destruct (HN (S p) g Hp Hph) as ((gr & Hgr & Hsp) & HL).
    split.
    + exists gr. split; [exact Hgr|exact Hsp].
    + intros gl Hp1 Hgl. destruct p as [|p'].
      * cbn [nth_error] in Hgl. injection Hgl as <-.
        exfalso. specialize (HL (2,2,A) ltac:(lia) eq_refl).
        unfold is_spc in HL.
        cbn [gO gZ gC] in HL. discriminate.
      * apply (HL gl); [lia|exact Hgl].
Qed.
Lemma LineageSpliceSound_forallb_is_col_phcol : forall sg w,
  forallb is_col w = true ->
  forallb (fun g => ph sg g || is_col g) w = true.
Proof.
  intros sg w H. apply forallb_forall. intros g Hin.
  eapply forallb_forall in H; [|exact Hin]. rewrite H, Bool.orb_true_r.
  reflexivity.
Qed.
Lemma direct_flat_step_of_site : forall sg J t s i f k body f2,
  sg_wf sg -> keys_big sg ->
  sg_live sg -> sg_pos sg ->
  (1 <= J)%N -> (1 <= s)%nat -> (1 <= i)%nat ->
  first_rule front_rules
    (lin_flat sg ((2,2,J) :: t)) f = None ->
  find_active ((2,2,J) :: t) s = Some i ->
  forallb is_col (firstn i ((2,2,J) :: t)) = true ->
  (match last1 (firstn i ((2,2,J) :: t)) with
   | Some g => ((3 <=? gO g) && (1 <=? gC g))%N
   | None => false
   end) = true ->
  Nat.leb 3 i = Nat.leb 3
    (length (lin_flat sg (firstn i ((2,2,J+1) :: t)))) ->
  ph_notlast sg (firstn i ((2,2,J+1) :: t)) ->
  nbrs1z sg (skipn i ((2,2,J+1) :: t)) ->
  (forall g u, skipn i ((2,2,J+1) :: t) = g :: u ->
     ph sg g = false) ->
  site_comp ((2,2,J+1) :: t) i f = Some (k,body,f2) ->
  let sF := length (lin_flat sg
    (firstn s ((2,2,J) :: t))) in
  let iF := length (lin_flat sg
    (firstn i ((2,2,J) :: t))) in
  step (lin_flat sg ((2,2,J) :: t)) f sF =
    match k with
    | JMP =>
        (ROk (normalize (lin_flat sg body)) f2, iF)
    | STD =>
        (ROk (normalize
          (firstn iF (lin_flat sg ((2,2,J+1) :: t)) ++
           lin_flat sg body)) f2, iF)
    end.
Proof.
  intros sg J t s i f k body f2 HW HK HL HP HJ HS HI HFront HFA
    HCols HLast HD HPN HNs HH HComp.
  cbv beta zeta.
  set (sF := length (lin_flat sg
    (firstn s ((2,2,J) :: t)))).
  set (iF := length (lin_flat sg
    (firstn i ((2,2,J) :: t)))).
  assert (Hilt : (i < length ((2%N,2%N,(J+1)%N) :: t))%nat)
    by (exact (site_comp_some_lt _ _ _ _ _ _ HComp)).
  assert (Hsle : (s <= i)%nat)
    by (exact (find_active_lb _ _ _ HFA)).
  assert (Hslen : length (firstn s ((2,2,J) :: t)) = s).
  { apply firstn_length_le. cbn [length] in Hilt |- *. lia. }
  assert (HsF : (1 <= sF)%nat).
  { unfold sF. pose proof (flat_len_ge sg
      (firstn s ((2,2,J) :: t)) HW) as Hge.
    assert (HS' : (1 <= length (firstn s ((2%N,2%N,J) :: t)))%nat)
      by lia.
    exact (PeanoNat.Nat.le_trans _ _ _ HS' Hge). }
  assert (HFAF : find_active
      (lin_flat sg ((2,2,J) :: t)) sF = Some iF).
  { unfold sF, iF. exact (find_active_flat
      sg ((2,2,J) :: t) s i HW HFA). }
  assert (HColsF : forallb is_col
      (firstn iF (lin_flat sg ((2,2,J) :: t))) = true).
  { replace (firstn iF (lin_flat sg ((2,2,J) :: t)))
      with (lin_flat sg (firstn i ((2,2,J) :: t))).
    apply flat_forallb_is_col; [exact HW|].
    exact (LineageSpliceSound_forallb_is_col_phcol sg _ HCols).
    unfold iF. exact (flat_firstn sg ((2,2,J) :: t) i). }
  assert (HLastF :
      (match last1
        (firstn iF (lin_flat sg ((2,2,J) :: t))) with
       | Some g => ((3 <=? gO g) && (1 <=? gC g))%N
       | None => false
       end) = true).
  { replace (firstn iF (lin_flat sg ((2,2,J) :: t)))
      with (lin_flat sg (firstn i ((2,2,J) :: t))).
    - exact (flat_last_guard sg
        (firstn i ((2,2,J) :: t)) HW HP HLast).
    - unfold iF. exact (flat_firstn sg ((2,2,J) :: t) i). }
  assert (HiEq : length (lin_flat sg
      (firstn i ((2,2,J+1) :: t))) = iF).
  { unfold iF. apply flat_firstn_master_len. exact HI. }
  assert (HiF : (1 <= iF)%nat).
  { unfold iF.
    pose proof (flat_len_ge sg
      (firstn i ((2%N,2%N,J) :: t)) HW) as Hge.
    assert (HiLen : length (firstn i ((2%N,2%N,J) :: t)) = i)
      by (apply firstn_length_le; cbn [length] in Hilt |- *; lia).
    assert (HiP : (1 <= length (firstn i ((2%N,2%N,J) :: t)))%nat)
      by (rewrite HiLen; exact HI).
    exact (PeanoNat.Nat.le_trans _ _ _ HiP Hge). }
  assert (HCompF : site_comp
      (lin_flat sg ((2,2,J+1) :: t)) iF f =
      Some (k, lin_flat sg body, f2)).
  { pose proof (site_comp_flat_dispatch
      sg ((2,2,J+1) :: t) i f HW HK HL HD HPN HNs HH) as E.
    rewrite HComp in E. rewrite <- HiEq. exact E. }
  unfold step, step_after_front, step_after_front_with,
    step_after_front_with_guard.
  rewrite HFront.
  rewrite flat_master.
  rewrite flat_master in HColsF, HLastF, HCompF.
  assert (EsF : Nat.ltb sF 1%nat = false)
    by (apply PeanoNat.Nat.ltb_ge; exact HsF).
  rewrite EsF.
  change (find_active ((2,2,J) :: lin_flat sg t) sF)
    with (find_active
      (lin_flat sg ((2,2,J) :: t)) sF).
  rewrite HFAF.
  rewrite HColsF. cbn [negb orb].
  cbn [gO gZ gC].
  assert (HJb : (1 <=? J)%N = true) by (apply N.leb_le; exact HJ).
  assert (HiF0 : Nat.eqb iF 0%nat = false)
    by (apply PeanoNat.Nat.eqb_neq; lia).
  rewrite HJb, HiF0. cbn [N.eqb andb Nat.eqb negb].
  lazymatch goal with
  | |- (if ?b then _ else _) = _ =>
      let E := fresh "Eguard" in
      assert (E : b = false) by reflexivity; rewrite E
  end.
  rewrite HLastF. cbn [negb orb].
  fold (site_comp
    ((2,2,J+1) :: lin_flat sg t) iF f).
  rewrite HCompF. destruct k; reflexivity.
Qed.
Lemma leb3_flat_prefix : forall sg w i,
  sg_wf sg -> ph_margins sg w ->
  (i < length w)%nat ->
  Nat.leb 3 i = Nat.leb 3
    (length (lin_flat sg (firstn i w))).
Proof.
  intros sg w i HW HM Hiw.
  destruct (Nat.leb 3 i) eqn:EI.
  - apply PeanoNat.Nat.leb_le in EI.
    symmetry. apply PeanoNat.Nat.leb_le.
    pose proof (flat_len_ge sg (firstn i w) HW) as Hge.
    rewrite firstn_length_le in Hge by lia. lia.
  - apply PeanoNat.Nat.leb_gt in EI.
    assert (Hfree : forall g, In g (firstn i w) -> ph sg g = false).
    { apply margins_firstn_phfree; [exact HM|].
      unfold GUARD. lia. }
    rewrite (lin_flat_nonph sg (firstn i w) Hfree).
    rewrite firstn_length_le by lia.
    symmetry. apply PeanoNat.Nat.leb_gt. exact EI.
Qed.
Lemma splice_none_direct_sound :
  forall sg J t f h s i cw2 f2 ir,
  sg_wf sg -> keys_big sg ->
  sg_live sg -> sg_pos sg ->
  ph_margins sg ((2,2,J) :: t) ->
  ph_nbrs sg ((2,2,J) :: t) ->
  front_gate ((2,2,J) :: t) f = None ->
  s = (if Nat.ltb h 1 then 1%nat else h) ->
  find_active ((2,2,J) :: t) s = Some i ->
  splice_call sg None ((2,2,J) :: t) f h
    = (ROk cw2 f2, ir) ->
  sound_impl (lin_flat sg ((2,2,J) :: t)) f
    (lin_flat sg cw2) f2.
Proof.
  intros sg J t f h s i cw2 f2 ir HW HK HL HP HM HN HFG ES HFA HRun.
  destruct (splice_none_direct_inv
    sg J t f h s i cw2 f2 ir ES HFA HRun)
    as (k & body & HJ & HS & HCols & HLast & HComp & -> & ->).
  assert (HI : (1 <= i)%nat)
    by (pose proof (find_active_lb _ _ _ HFA); lia).
  assert (HM1 : ph_margins sg ((2,2,J+1) :: t))
    by (exact (margins_master_change sg J (J+1) t HM)).
  assert (HN1 : ph_nbrs sg ((2,2,J+1) :: t))
    by (exact (nbrs_master_change sg J (J+1) t HN)).
  destruct (site_comp_head
    sg ((2,2,J+1) :: t) i f k body f2 HComp)
    as (g & u & Hsite & Hph & Hcasc & Hnotag).
  assert (Hilt : (i < length ((2%N,2%N,(J+1)%N) :: t))%nat)
    by (exact (site_comp_some_lt _ _ _ _ _ _ HComp)).
  assert (HPN : ph_notlast sg
      (firstn i ((2,2,J+1) :: t))).
  { exact (margins_ph_notlast
      sg ((2,2,J+1) :: t) i g u HM1 Hsite Hcasc). }
  assert (HNs : nbrs1z sg
      (skipn i ((2,2,J+1) :: t))).
  { apply nbrs_nbrs1z.
    apply (ph_nbrs_app_r sg
      (firstn i ((2,2,J+1) :: t))).
    rewrite firstn_skipn. exact HN1. }
  assert (HH : forall g0 u0,
      skipn i ((2,2,J+1) :: t) = g0 :: u0 ->
      ph sg g0 = false).
  { intros g0 u0 E.
    pose proof (eq_trans (eq_sym Hsite) E) as EE.
    injection EE as Eg _. subst g0. exact Hph. }
  assert (HFront : first_rule front_rules
      (lin_flat sg ((2,2,J) :: t)) f = None).
  { exact (front_gate_None_flat_tag
      sg ((2,2,J) :: t) f HW HK HL HM HN HFG). }
  assert (HD : Nat.leb 3 i = Nat.leb 3
      (length (lin_flat sg (firstn i ((2,2,J+1) :: t)))))
    by (exact (leb3_flat_prefix sg ((2,2,J+1)::t) i HW HM1 Hilt)).
  pose proof (direct_flat_step_of_site
    sg J t s i f k body f2 HW HK HL HP HJ HS HI HFront HFA
    HCols HLast HD HPN HNs HH HComp) as HStep.
  cbv beta zeta in HStep.
  set (iF := length (lin_flat sg
    (firstn i ((2,2,J) :: t)))) in HStep.
  assert (HiEq : length (lin_flat sg
      (firstn i ((2,2,J+1) :: t))) = iF).
  { unfold iF. apply flat_firstn_master_len. exact HI. }
  destruct k.
  - pose proof (step_sound_live _ _ _ _ _ _ HStep) as HSnd.
    eapply sound_impl_sdecode; [reflexivity| |exact HSnd].
    transitivity (sdecode
      (firstn iF (lin_flat sg ((2,2,J+1) :: t)) ++
       lin_flat sg body) f2).
    + apply normalize_sound.
    + assert (ERaw : lin_flat sg
          (firstn i ((2,2,J+1) :: t) ++ body) =
          firstn iF (lin_flat sg ((2,2,J+1) :: t)) ++
            lin_flat sg body).
      { rewrite lin_flat_app_c.
        f_equal.
        transitivity (firstn
          (length (lin_flat sg (firstn i ((2,2,J+1) :: t))))
          (lin_flat sg ((2,2,J+1) :: t))).
        - apply flat_firstn.
        - f_equal. exact HiEq. }
      rewrite <- ERaw. symmetry.
      apply lin_normalize_join_flat_sdecode.
  - pose proof (step_sound_live _ _ _ _ _ _ HStep) as HSnd.
    eapply sound_impl_sdecode; [reflexivity| |exact HSnd].
    transitivity (sdecode (lin_flat sg body) f2).
    + apply normalize_sound.
    + symmetry. apply lin_normalize_at_flat_sdecode.
Qed.
Lemma splice_none_fallback_inv : forall sg J t f h s cw2 f2 ir,
  s = (if Nat.ltb h 1 then 1%nat else h) ->
  find_active ((2,2,J) :: t) s = None ->
  splice_call sg None ((2,2,J) :: t) f h
    = (ROk cw2 f2, ir) ->
  exists j sfx,
    (1 <= J)%N /\
    cmf_from ((2,2,J) :: t)
      (Nat.max 1
        (match (2,2,J) :: t with
         | (2,2,_) :: (5,2,_) :: (3,2,_) :: (2,2,1) :: _ => 4%nat
         | (2,2,_) :: (5,2,_) :: (3,2,_) :: _ => 3%nat
         | _ => 1%nat
         end)) (length ((2,2,J) :: t)) = Some j /\
    forallb is_col (firstn j ((2,2,J) :: t)) = true /\
    leaf_act (skipn j ((2,2,J+1) :: t)) f = Some (sfx,f2) /\
    ir = O /\
    cw2 = lin_normalize_join sg
      (firstn j ((2,2,J+1) :: t)) sfx.
Proof.
  intros sg J t f h s cw2 f2 ir ES HFA H.
  subst s.
  unfold splice_call, step_after_front_with_guard in H.
  cbv beta zeta iota in H. rewrite HFA in H. cbv beta zeta iota in H.
  cbn [gO gZ gC] in H.
  lazymatch type of H with
  | (if ?b then _ else _) = _ => destruct b eqn:HMaster in H
  end; [discriminate|].
  apply Bool.negb_false_iff in HMaster.
  cbn [N.eqb andb] in HMaster.
  apply andb_prop in HMaster as [_ HJ]. apply N.leb_le in HJ.
  lazymatch type of H with
  | context [cmf_from ?ww ?st ?nn] =>
      destruct (cmf_from ww st nn) as [j|] eqn:EC in H
  end.
  2:{ cbv beta zeta iota in H.
      lazymatch type of H with
      | context [existsb ?p ?ww] =>
          destruct (existsb p ww) eqn:EX in H
      end.
      - lazymatch type of H with
        | context [debris_to_blank ?ww ?ff] =>
            destruct (debris_to_blank ww ff) eqn:ED in H
        end; discriminate.
      - discriminate. }
  cbv beta zeta iota in H.
  lazymatch type of H with
  | (if ?b then _ else _) = _ => destruct b eqn:HColsBad in H
  end; [discriminate|].
  apply Bool.negb_false_iff in HColsBad.
  cbn [orb] in HColsBad. rename HColsBad into HCols.
  match type of H with
  | context [leaf_act ?w ?ff] =>
      destruct (leaf_act w ff) as [[sfx f2']|] eqn:EL in H
  end.
  2:{ cbv beta zeta iota in H.
      lazymatch type of H with
      | context [match ?r with
                 | ROk _ _ => _ | RHalt => _ | RBad => _
                 end] => destruct r in H
      end; discriminate. }
  cbv beta zeta iota in H. inversion H; subst cw2 f2 ir.
  exists j, sfx. repeat split; assumption || reflexivity.
Qed.
Lemma skipn_master_change : forall (A B : N) t j,
  (1 <= j)%nat -> skipn j ((2,2,A) :: t) = skipn j ((2,2,B) :: t).
Proof. intros A B t [|j] H; [lia|reflexivity]. Qed.
Lemma firstn_master_form : forall (A : N) t j,
  (1 <= j)%nat ->
  firstn j ((2,2,A) :: t) = (2,2,A) :: firstn (j-1) t.
Proof.
  intros A t [|j] H; [lia|].
  replace (S j - 1)%nat with j by lia. reflexivity.
Qed.
Lemma splice_none_fallback_sound :
  forall sg J t f h s cw2 f2 ir,
  sg_wf sg -> keys_big sg ->
  sg_live sg ->
  ph_margins sg ((2,2,J) :: t) ->
  ph_nbrs sg ((2,2,J) :: t) ->
  front_gate ((2,2,J) :: t) f = None ->
  s = (if Nat.ltb h 1 then 1%nat else h) ->
  find_active ((2,2,J) :: t) s = None ->
  splice_call sg None ((2,2,J) :: t) f h
    = (ROk cw2 f2, ir) ->
  sound_impl (lin_flat sg ((2,2,J) :: t)) f
    (lin_flat sg cw2) f2.
Proof.
  intros sg J t f h s cw2 f2 ir HW HK HL HM HN HFG ES HFA HRun.
  destruct (splice_none_fallback_inv sg J t f h s cw2 f2 ir ES HFA HRun)
    as (j & sfx & HJ & ECMF & HCols & ELeaf & -> & ->).
  destruct (cmf_from_inv _ _ _ _ ECMF)
    as (Hstart & g & Hwat & Hcmf).
  assert (Hj : (1 <= j)%nat).
  { eapply PeanoNat.Nat.le_trans; [|exact Hstart].
    apply PeanoNat.Nat.le_max_l. }
  assert (Es : exists u, skipn j ((2,2,J) :: t) = g :: u).
  { unfold wat in Hwat.
    assert (E0 : nth_error (skipn j ((2,2,J)::t)) O = Some g).
    { rewrite nth_skipn, PeanoNat.Nat.add_0_r. exact Hwat. }
    destruct (skipn j ((2,2,J)::t)) as [|g0 u] eqn:ESk.
    - discriminate E0.
    - cbn [nth_error] in E0. injection E0 as <-.
      exists u. reflexivity. }
  destruct Es as (u & Es).
  assert (Hph : ph sg g = false).
  { destruct (ph sg g) eqn:E; [|reflexivity].
    pose proof (ph_not_cmf sg g E) as Hnc.
    rewrite Hcmf in Hnc. discriminate. }
  assert (Es1 : skipn j ((2,2,J+1) :: t) = g :: u).
  { rewrite <- (skipn_master_change J (J+1) t j Hj). exact Es. }
  assert (HM1 : ph_margins sg ((2,2,J+1) :: t))
    by (exact (margins_master_change sg J (J+1) t HM)).
  assert (HN1 : ph_nbrs sg ((2,2,J+1) :: t))
    by (exact (nbrs_master_change sg J (J+1) t HN)).
  assert (HNs : nbrs1z sg (skipn j ((2,2,J+1) :: t))).
  { apply nbrs_nbrs1z.
    apply (ph_nbrs_app_r sg
      (firstn j ((2,2,J+1) :: t))).
    rewrite firstn_skipn. exact HN1. }
  assert (HH : forall g0 u0,
      skipn j ((2,2,J+1) :: t) = g0 :: u0 ->
      ph sg g0 = false).
  { intros g0 u0 E.
    pose proof (eq_trans (eq_sym Es1) E) as EE.
    injection EE as Eg _. subst g0. exact Hph. }
  assert (ELeafF : leaf_act
      (lin_flat sg (skipn j ((2,2,J+1) :: t))) f =
      Some (lin_flat sg sfx, f2)).
  { pose proof (leaf_act_flat_z sg
      (skipn j ((2,2,J+1)::t)) f HW HK HNs HH) as E.
    rewrite ELeaf in E. exact E. }
  set (pF := lin_flat sg (firstn j ((2,2,J) :: t))).
  set (sF := lin_flat sg (skipn j ((2,2,J+1) :: t))).
  assert (HColsF : forallb is_col pF = true).
  { unfold pF. exact (flat_checked_prefix_cols
      sg (firstn j ((2,2,J)::t)) HW HCols). }
  assert (EpF : pF = (2,2,J) ::
      lin_flat sg (firstn (j-1) t)).
  { unfold pF. rewrite (firstn_master_form J t j Hj).
    apply flat_master. }
  assert (EsF : sF = g :: lin_flat sg u).
  { unfold sF. rewrite Es1.
    apply flat_cons_nonph. exact Hph. }
  assert (HPC : cmf_prefix_ok pF sF).
  { rewrite EpF, EsF. destruct g as [[go gz] gc].
    unfold cmf_prefix_ok. cbn.
    intros _ _. repeat split; try reflexivity. exact HJ. }
  assert (EInput : lin_flat sg ((2,2,J) :: t) =
      pF ++ sF).
  { unfold pF, sF.
    rewrite <- lin_flat_app_c.
    rewrite <- (skipn_master_change J (J+1) t j Hj).
    rewrite firstn_skipn. reflexivity. }
  assert (EOut : sdecode
      (lin_flat sg
        (firstn j ((2,2,J+1) :: t) ++ sfx)) f2 =
      sdecode ((2,2,1) :: pF ++ lin_flat sg sfx) f2).
  { rewrite lin_flat_app_c.
    unfold pF.
    rewrite (firstn_master_form (J+1) t j Hj),
      (firstn_master_form J t j Hj).
    rewrite !flat_master.
    change (sdec
      ((2,2,J+1) :: lin_flat sg (firstn (j-1) t) ++
        lin_flat sg sfx) f2 =
      sdec
      ((2,2,1) :: (2,2,J) ::
        lin_flat sg (firstn (j-1) t) ++
        lin_flat sg sfx) f2).
    apply sdec_incr. }
  unfold sound_impl. intros Hhalt.
  pose proof (lin_normalize_join_flat_sdecode sg
    (firstn j ((2,2,J+1)::t)) sfx f2) as ENorm.
  rewrite ENorm in Hhalt.
  assert (Hhalt2 : halts tmB (wconf [] 0
      (sdecode ((2,2,1) :: pF ++ lin_flat sg sfx) f2))).
  { exact (eq_ind _ (fun x => halts tmB (wconf [] 0 x))
      Hhalt _ EOut). }
  pose proof (leaf_act_sound pF sF f
    (lin_flat sg sfx) f2 HColsF HPC ELeafF Hhalt2) as Hin.
  rewrite EInput. exact Hin.
Qed.
Lemma splice_none_rok_master : forall sg cw f h cw2 f2 i,
  splice_call sg None cw f h = (ROk cw2 f2, i) ->
  exists J t, cw = (2,2,J) :: t /\ (1 <= J)%N.
Proof.
  intros sg cw f h cw2 f2 i H.
  unfold splice_call, step_after_front_with_guard in H.
  destruct cw as [|[[o z] J] t].
  - unfold find_active in H. rewrite skipn_nil in H.
    cbn [find_active_s] in H.
    discriminate H.
  - cbv beta zeta iota in H.
    lazymatch type of H with
    | context [match find_active ?w ?s with
               | Some _ => _
               | None => _
               end] =>
        revert H;
        destruct (find_active w s) as [j|] eqn:EF;
        intro H; cbv beta zeta iota in H
    end.
  + lazymatch type of H with
    | (if ?b then _ else _) = _ => destruct b eqn:EC in H
    end; [discriminate H|].
    lazymatch type of H with
    | (if ?b then _ else _) = _ => destruct b eqn:EM in H
    end; [discriminate H|].
    apply negb_false_iff in EM.
    cbn [orb gO gZ gC] in EM.
    repeat rewrite Bool.andb_true_iff in EM.
    destruct EM as [[[EO EZ] EJ] _].
    apply N.eqb_eq in EO, EZ. apply N.leb_le in EJ. subst o z.
    exists J, t. split; [reflexivity|exact EJ].
  + cbv beta zeta iota in H.
    cbn [gO gZ gC] in H.
    destruct (negb ((o =? 2) && (z =? 2) && (1 <=? J)))%N eqn:EM;
      [discriminate|].
    apply negb_false_iff in EM. repeat rewrite Bool.andb_true_iff in EM.
    destruct EM as [[EO EZ] EJ].
    apply N.eqb_eq in EO, EZ. apply N.leb_le in EJ. subst o z.
    exists J, t. split; [reflexivity|exact EJ].
Qed.
Lemma splice_checked_sound : forall sg cw f h cw2 f2 i,
  sg_wf sg -> keys_big sg ->
  sg_live sg -> sg_pos sg ->
  ph_margins sg cw -> ph_nbrs sg cw ->
  splice_call sg (front_gate cw f) cw f h
    = (ROk cw2 f2, i) ->
  sound_impl (lin_flat sg cw) f
    (lin_flat sg cw2) f2.
Proof.
  intros sg cw f h cw2 f2 i HW HK HL HP HM HN HRun.
  destruct (front_gate cw f) as [r|] eqn:EFG.
  - destruct r as [w2 f2'| |].
    + unfold splice_call, step_after_front_with_guard in HRun.
      cbv beta iota in HRun.
      injection HRun as <- <- <-.
      exact (splice_front_sound_tag
        sg cw f w2 f2' HW HK HL HM HN EFG).
    + unfold splice_call, step_after_front_with_guard in HRun.
      discriminate.
    + unfold splice_call, step_after_front_with_guard in HRun.
      discriminate.
  - destruct (splice_none_rok_master sg cw f h cw2 f2 i HRun)
      as (J & t & -> & HJ).
    set (s := if Nat.ltb h 1 then 1%nat else h).
    destruct (find_active ((2,2,J) :: t) s) as [j|] eqn:EFA.
    + eapply splice_none_direct_sound; try eassumption.
      exact eq_refl.
    + eapply splice_none_fallback_sound; try eassumption.
      exact eq_refl.
Qed.
Open Scope N_scope.
Open Scope bool_scope.
Opaque LROUND_FUEL LROUND_CHUNKS
       FLAT_ROUND_FUEL CFUEL TRIES.
Definition shape_lmargin (n : nat) (w : word) : Prop :=
  forall p g, nth_error w p = Some g -> phshape g = true ->
    (n <= p)%nat /\
    (forall q, (p - n <= q)%nat -> (q < p)%nat ->
       exists g', nth_error w q = Some g' /\
                  casc g' = true /\ phshape g' = false).
Definition edge_out (w : word) : Prop :=
  shape_head_free w /\ tag_edges w.
Definition shape_notlast (w : word) : Prop :=
  forall p g, nth_error w p = Some g -> phshape g = true ->
    (p + 1 < length w)%nat.
Definition edge_pack (w : word) : Prop :=
  edge_out w /\ shape_notlast w.
Lemma shape_lmargin_weaken : forall n m w,
  (m <= n)%nat -> shape_lmargin n w -> shape_lmargin m w.
Proof.
  intros n m w Hmn HM p g Hp HT. destruct (HM p g Hp HT) as (Hnp & HW).
  split; [lia|]. intros q Hq1 Hq2. apply HW; lia.
Qed.
Lemma shape_lmargin_nonph_at : forall n w q gq p g,
  shape_lmargin n w -> nth_error w q = Some gq ->
  casc gq = false -> nth_error w p = Some g ->
  (q < p)%nat -> (p - n <= q)%nat -> phshape g = false.
Proof.
  intros n w q gq p g HM Hq HC Hp Hqp Hlo.
  destruct (phshape g) eqn:HT; [|reflexivity].
  destruct (HM p g Hp HT) as (_ & HW).
  destruct (HW q Hlo Hqp) as (g' & Hg' & HC' & _).
  rewrite Hq in Hg'. injection Hg' as <-. congruence.
Qed.
Lemma shape_lmargin_tail_noncasc : forall n g t,
  shape_lmargin n (g :: t) -> casc g = false ->
  shape_lmargin n t.
Proof.
  intros n g t HM HC p gp Hp HT.
  destruct (HM (S p) gp Hp HT) as (Hn & HW).
  assert (Hnp : (n <= p)%nat).
  { destruct (PeanoNat.Nat.le_gt_cases n p) as [Hle|Hgt]; [exact Hle|].
    assert (En : n = S p) by lia. subst n.
    destruct (HW O ltac:(lia) ltac:(lia)) as (g' & Hg' & HC' & _).
    cbn [nth_error] in Hg'. injection Hg' as <-. congruence. }
  split; [exact Hnp|]. intros q Hq1 Hq2.
  destruct (HW (S q) ltac:(lia) ltac:(lia)) as (g' & Hg' & HC' & HT').
  exists g'. split; [exact Hg'|]. auto.
Qed.
Lemma shape_lmargin_tail_drop : forall n g t,
  shape_lmargin (S n) (g :: t) -> shape_lmargin n t.
Proof.
  intros n g t HM p gp Hp HS.
  destruct (HM (S p) gp Hp HS) as (Hn & HW). split; [lia|].
  intros q Hq1 Hq2.
  destruct (HW (S q) ltac:(lia) ltac:(lia))
    as (g' & Hg' & HC & HP).
  exists g'. split; [exact Hg'|]. auto.
Qed.
Lemma shape_lmargin_shape_free : forall n w,
  shape_free w -> shape_lmargin n w.
Proof.
  intros n w HF p g Hg HS.
  rewrite (HF g (nth_error_In w p Hg)) in HS. discriminate.
Qed.
Lemma shape_lmargin_app : forall n a b,
  shape_lmargin n a -> shape_lmargin n b -> shape_lmargin n (a ++ b).
Proof.
  intros n a b HA HB p g Hg HS.
  destruct (PeanoNat.Nat.lt_ge_cases p (length a)) as [Hp|Hp].
  - rewrite nth_error_app1 in Hg by exact Hp.
    destruct (HA p g Hg HS) as (Hn & HW). split; [exact Hn|].
    intros q Hq1 Hq2. destruct (HW q Hq1 Hq2)
      as (g' & Hg' & HC & HP).
    exists g'. split.
    + rewrite nth_error_app1 by lia. exact Hg'.
    + auto.
  - rewrite nth_error_app2 in Hg by exact Hp.
    set (pb := (p - length a)%nat) in *.
    assert (Ep : (p = length a + pb)%nat) by (unfold pb; lia).
    destruct (HB pb g Hg HS) as (Hn & HW). split; [lia|].
    intros q Hq1 Hq2.
    assert (Hqa : (length a <= q)%nat) by lia.
    set (qb := (q - length a)%nat).
    destruct (HW qb ltac:(unfold qb; lia) ltac:(unfold qb; lia))
      as (g' & Hg' & HC & HP).
    exists g'. split.
    + rewrite nth_error_app2 by exact Hqa.
      replace (q - length a)%nat with qb by reflexivity. exact Hg'.
    + auto.
Qed.
Lemma shape_lmargin_prefix : forall n a b,
  shape_lmargin n (a ++ b) -> shape_lmargin n a.
Proof.
  intros n a b H p g Hg HS.
  assert (Hp : (p < length a)%nat)
    by (apply nth_error_Some; rewrite Hg; discriminate).
  assert (Hg' : nth_error (a ++ b) p = Some g)
    by (rewrite nth_error_app1 by exact Hp; exact Hg).
  destruct (H p g Hg' HS) as (Hn & HW). split; [exact Hn|].
  intros q Hq1 Hq2. destruct (HW q Hq1 Hq2)
    as (g' & Hgq & HC & HP).
  exists g'. split.
  - rewrite nth_error_app1 in Hgq by lia. exact Hgq.
  - auto.
Qed.
Lemma shape_lmargin_phfree_suffix : forall n a b,
  shape_lmargin n a -> shape_free b -> shape_lmargin n (a ++ b).
Proof.
  intros n a b HA HB. apply shape_lmargin_app; [exact HA|].
  exact (shape_lmargin_shape_free n b HB).
Qed.
Lemma shape_lmargin_prefix_cons_phfree : forall n pre g tail,
  shape_lmargin n (pre ++ [g]) -> shape_free tail ->
  shape_lmargin n (pre ++ g :: tail).
Proof.
  intros n pre g tail HM HF.
  replace (pre ++ g :: tail) with ((pre ++ [g]) ++ tail)
    by (rewrite <- app_assoc; reflexivity).
  exact (shape_lmargin_phfree_suffix n (pre++[g]) tail HM HF).
Qed.
Lemma shape_lmargin_lits_app : forall n p t,
  shape_free p -> shape_lmargin n t -> shape_lmargin n (p ++ t).
Proof.
  intros n p t HP HT. apply shape_lmargin_app;
    [apply shape_lmargin_shape_free|]; assumption.
Qed.
Lemma shape_lmargin_suffix_noncasc : forall n pre g t,
  shape_lmargin n (pre ++ g :: t) ->
  casc g = false -> phshape g = false ->
  shape_lmargin n (g :: t).
Proof.
  intros n pre g t HM HC HG p gp Hp HS.
  destruct p as [|p].
  - cbn [nth_error] in Hp. injection Hp as <-.
    rewrite HG in HS. discriminate.
  - assert (HpG : nth_error (pre ++ g :: t) (length pre + S p)
                   = Some gp).
    { rewrite nth_error_app2 by lia.
      replace (length pre + S p - length pre)%nat with (S p) by lia.
      exact Hp. }
    destruct (HM _ _ HpG HS) as (HnG & HW).
    assert (Hn : (n <= S p)%nat).
    { destruct (PeanoNat.Nat.le_gt_cases n (S p)) as [Hle|Hgt];
        [exact Hle|].
      destruct (HW (length pre) ltac:(lia) ltac:(lia))
        as (g' & Hg' & HC' & _).
      rewrite nth_error_app2 in Hg' by lia.
      replace (length pre - length pre)%nat with O in Hg' by lia.
      cbn [nth_error] in Hg'. injection Hg' as <-. congruence. }
    split; [exact Hn|]. intros q Hq1 Hq2.
    destruct (HW (length pre + q)%nat ltac:(lia) ltac:(lia))
      as (g' & Hg' & HC' & HP').
    exists g'. split.
    + rewrite nth_error_app2 in Hg' by lia.
      replace (length pre + q - length pre)%nat with q in Hg' by lia.
      exact Hg'.
    + auto.
Qed.
Lemma shape_lmargin_replace_head : forall n a b t,
  phshape b = false -> casc b = casc a ->
  shape_lmargin n (a :: t) -> shape_lmargin n (b :: t).
Proof.
  intros n a b t HB HC HM p g Hp HS. destruct p as [|p].
  - cbn [nth_error] in Hp. injection Hp as <-.
    rewrite HB in HS. discriminate.
  - destruct (HM (S p) g Hp HS) as (Hn & HW). split; [exact Hn|].
    intros q Hq1 Hq2. destruct q as [|q].
    + destruct (HW O Hq1 Hq2) as (g' & Hg' & HC' & HP').
      cbn [nth_error] in Hg'. injection Hg' as <-.
      exists b. split; [reflexivity|]. split; [rewrite HC; exact HC'|exact HB].
    + destruct (HW (S q) Hq1 Hq2) as (g' & Hg' & HC' & HP').
      exists g'. split; [exact Hg'|]. auto.
Qed.
Lemma shape_notlast_app_r : forall p t,
  shape_notlast (p ++ t) -> shape_notlast t.
Proof.
  intros p t H q g Hg HP.
  assert (Hg' : nth_error (p ++ t) (length p + q) = Some g).
  { rewrite nth_error_app2 by lia.
    replace (length p + q - length p)%nat with q by lia. exact Hg. }
  specialize (H _ _ Hg' HP). rewrite length_app in H. lia.
Qed.
Lemma shape_notlast_shape_free : forall w,
  shape_free w -> shape_notlast w.
Proof.
  intros w HF p g Hg HP.
  rewrite (HF g (nth_error_In w p Hg)) in HP. discriminate.
Qed.
Lemma shape_notlast_lits_app : forall p t,
  shape_free p -> shape_notlast t -> shape_notlast (p ++ t).
Proof.
  intros p t HP HT q g Hg HS.
  destruct (PeanoNat.Nat.lt_ge_cases q (length p)) as [Hq|Hq].
  - rewrite nth_error_app1 in Hg by exact Hq.
    rewrite (HP g (nth_error_In p q Hg)) in HS. discriminate.
  - rewrite nth_error_app2 in Hg by exact Hq.
    specialize (HT (q-length p)%nat g Hg HS).
    rewrite length_app. lia.
Qed.
Lemma shape_notlast_app : forall a b,
  shape_notlast a -> shape_notlast b -> shape_notlast (a ++ b).
Proof.
  intros a b HA HB p g Hg HS.
  destruct (PeanoNat.Nat.lt_ge_cases p (length a)) as [Hp|Hp].
  - rewrite nth_error_app1 in Hg by exact Hp.
    specialize (HA p g Hg HS). rewrite length_app. lia.
  - rewrite nth_error_app2 in Hg by exact Hp.
    specialize (HB (p-length a)%nat g Hg HS).
    rewrite length_app. lia.
Qed.
Lemma tag_edges_app_pack : forall a b,
  tag_edges a -> tag_edges b ->
  shape_notlast a -> shape_head_free b ->
  tag_edges (a ++ b).
Proof.
  intros a. induction a as [|x a IH]; intros b HEa HEb HNa HHb;
    [exact HEb|].
  destruct a as [|y a].
  - destruct b as [|z b]; [exact I|].
    cbn [app tag_edges]. split; [|exact HEb]. split.
    + intros HX. specialize (HNa O x eq_refl HX). cbn [length] in HNa. lia.
    + intros HZ. rewrite (HHb z b eq_refl) in HZ. discriminate.
  - cbn [app tag_edges] in HEa |- *. split.
    + exact (proj1 HEa).
    + apply IH.
      * exact (proj2 HEa).
      * exact HEb.
      * apply (shape_notlast_app_r [x] (y::a)).
        cbn [app]. exact HNa.
      * exact HHb.
Qed.
Lemma edge_pack_app : forall a b,
  edge_pack a -> edge_pack b -> edge_pack (a ++ b).
Proof.
  intros a b [[HHa HEa] HNa] [[HHb HEb] HNb]. split.
  - split.
    + intros g t E. destruct a as [|x a].
      * cbn [app] in E. exact (HHb g t E).
      * cbn [app] in E. injection E as <- _.
        exact (HHa x a eq_refl).
    + exact (tag_edges_app_pack a b HEa HEb HNa HHb).
  - exact (shape_notlast_app a b HNa HNb).
Qed.
Lemma edge_pack_lits_app : forall a b,
  shape_free a -> edge_pack b -> edge_pack (a ++ b).
Proof.
  intros a b HF [[HH HE] HN]. split.
  - split.
    + intros g t E. destruct a as [|x a].
      * cbn [app] in E. exact (HH g t E).
      * cbn [app] in E. injection E as <- _.
        exact (HF x (or_introl eq_refl)).
    + exact (tag_edges_shape_free_app_probe a b HF HH HE).
  - exact (shape_notlast_lits_app a b HF HN).
Qed.
Lemma edge_out_lits_app : forall A t,
  shape_free A -> edge_out t -> edge_out (A ++ t).
Proof.
  intros A t HA (HH & HE). split.
  - intros g u E. destruct A as [|a A].
    + cbn [app] in E. exact (HH g u E).
    + cbn [app] in E. injection E as <- _.
      exact (HA a (or_introl eq_refl)).
  - apply tag_edges_shape_free_app_probe; assumption.
Qed.
Lemma edge_out_shape_free : forall w,
  shape_free w -> edge_out w.
Proof.
  intros w HF. split.
  - intros g t ->. exact (HF g (or_introl eq_refl)).
  - exact (tag_edges_shape_free_probe w HF).
Qed.
Lemma lin_ptags_nth_shape_probe : forall sg w p g,
  lin_ptags sg w = true -> nth_error w p = Some g ->
  phshape g = true -> ph sg g = true.
Proof.
  intros sg w. induction w as [|a w IH]; intros p g HT Hg HS;
    [destruct p; discriminate|].
  cbn [lin_ptags] in HT. apply andb_prop in HT as [Ha HT].
  destruct p as [|p].
  - cbn [nth_error] in Hg. injection Hg as <-.
    rewrite HS in Ha. cbn [negb orb] in Ha. exact Ha.
  - cbn [nth_error] in Hg. exact (IH p g HT Hg HS).
Qed.
Lemma margins_shape_lmargin3_probe : forall sg w,
  ph_margins sg w ->
  lin_ptags sg w = true -> shape_lmargin 3 w.
Proof.
  intros sg w HM HT p g Hp HS.
  assert (Hph : ph sg g = true)
    by (exact (lin_ptags_nth_shape_probe sg w p g HT Hp HS)).
  destruct (HM p g Hp Hph) as (Hlo & _ & HW).
  split; [exact Hlo|]. intros q Hq1 Hq2.
  destruct (HW q Hq1 ltac:(unfold GUARD; lia) ltac:(lia))
    as (g' & Hg' & HC' & HP').
  exists g'. split; [exact Hg'|]. split; [exact HC'|].
  destruct (phshape g') eqn:HS'; [|reflexivity].
  pose proof (lin_ptags_nth_shape_probe sg w q g' HT Hg' HS') as HP''.
  congruence.
Qed.
Lemma seek_suffix_edge_pack : forall w cols g t,
  seek w = (cols, g :: t) -> edge_pack w -> edge_pack (g :: t).
Proof.
  intros w cols g t ES [[HH HE] HN].
  pose proof (LineageGuard_seek_split w) as HSP.
  rewrite ES in HSP. cbn [fst snd] in HSP. split.
  - split.
    + intros x u E. injection E as <- _.
      pose proof (seek_snd_head w g t
                    ltac:(rewrite ES; reflexivity)) as HST.
      pose proof (seektest_notag g HST) as HNT.
      unfold notag in HNT. apply negb_true_iff in HNT.
      exact HNT.
    + apply (tag_edges_app_r_probe cols (g::t)). rewrite <- HSP. exact HE.
  - apply (shape_notlast_app_r cols (g::t)). rewrite <- HSP. exact HN.
Qed.
Lemma seek_suffix_lmargin : forall n w cols g t,
  seek w = (cols, g :: t) -> shape_lmargin n w ->
  shape_lmargin n (g :: t).
Proof.
  intros n w cols g t ES HM.
  pose proof (LineageGuard_seek_split w) as HSP.
  rewrite ES in HSP. cbn [fst snd] in HSP.
  pose proof (seek_snd_head w g t
                ltac:(rewrite ES; reflexivity)) as HST.
  apply (shape_lmargin_suffix_noncasc n cols g t).
  - rewrite <- HSP. exact HM.
  - exact (seektest_noncasc g HST).
  - pose proof (seektest_notag g HST) as HNT.
    unfold notag in HNT. apply negb_true_iff in HNT.
    exact HNT.
Qed.
Lemma edge_out_replace_prefix_nonside : forall pin l pout t,
  tag_edges (pin ++ l :: t) ->
  ~ side8 l -> shape_free pout -> edge_out (pout ++ t).
Proof.
  intros pin l pout t HE HNS HF. split.
  - intros g u E. destruct pout as [|a pout].
    + cbn [app] in E.
      exact (head_free_after_nonside_probe pin l t HE HNS g u E).
    + cbn [app] in E. injection E as <- _.
      exact (HF a (or_introl eq_refl)).
  - exact (tag_edges_replace_prefix_probe pin l pout t HE HNS HF).
Qed.
Lemma edge_out_prefix_tail : forall pout t,
  shape_free pout -> shape_head_free t -> tag_edges t ->
  edge_out (pout ++ t).
Proof.
  intros pout t HF HH HE. split.
  - intros g u E. destruct pout as [|a pout].
    + cbn [app] in E. exact (HH g u E).
    + cbn [app] in E. injection E as <- _.
      exact (HF a (or_introl eq_refl)).
  - exact (tag_edges_shape_free_app_probe pout t HF HH HE).
Qed.
Lemma not_side8_z1 : forall o c, ~ side8 (o,1%N,c).
Proof.
  intros o c [_ H]. cbn [gZ] in H. discriminate.
Qed.
Lemma not_side8_o4 : forall z c, ~ side8 (4%N,z,c).
Proof.
  intros z c [H _]. cbn [gO] in H. discriminate.
Qed.
Lemma not_side8_z_ge3 : forall o z c,
  (3 <= z)%N -> ~ side8 (o,z,c).
Proof.
  intros o z c Hz [_ H]. cbn [gZ] in H. lia.
Qed.
Lemma leaf_act_edges2_probe : forall s f s2 f2,
  shape_lmargin 2 s -> tag_edges s ->
  leaf_act s f = Some (s2, f2) -> edge_out s2.
Proof.
  induction s as [|[[o z] c] t IH]; intros f s2 f2 HM HE HRun;
    [discriminate|].
  destruct z as [|[zp|zp|]].
  { cbn [leaf_act] in HRun. discriminate. }
  { cbn [leaf_act] in HRun. discriminate. }
  2:{
      cbn [leaf_act] in HRun.
      destruct (2 <=? c)%N.
      { destruct (2 <=? o)%N; [|discriminate].
        injection HRun as <- <-.
        destruct (2 <? c)%N.
        - change (edge_out
            ([(o,1%N,1%N); ((o-1)%N,1%N,1%N);
              (o,1%N,(c-2)%N)] ++ t)).
          eapply edge_out_replace_prefix_nonside with
            (pin := []) (l := (o,1%N,c)) (t := t);
            [cbn [app]; exact HE|apply not_side8_z1|].
          unfold shape_free. shape_lits_probe.
        - change (edge_out
            ([(o,1%N,1%N); ((o-1)%N,1%N,1%N)] ++ t)).
          eapply edge_out_replace_prefix_nonside with
            (pin := []) (l := (o,1%N,c)) (t := t);
            [cbn [app]; exact HE|apply not_side8_z1|].
          unfold shape_free. shape_lits_probe. }
      destruct (negb (c =? 1) || negb (2 <=? o))%N; [discriminate|].
      destruct t as [|[[B zb] cb] t2].
      { destruct (2 <=? f)%N.
        - injection HRun as <- <-. apply edge_out_shape_free.
          unfold shape_free. shape_lits_probe.
        - destruct (f =? 1)%N; [|discriminate].
          injection HRun as <- <-. apply edge_out_shape_free.
          unfold shape_free. shape_lits_probe. }
      match type of HRun with
      | (if ?X then _ else _) = _ => destruct X eqn:EG
      end.
      { assert (HB8 : (B =? 8)%N = false).
        { apply andb_prop in EG as [EG _].
          apply andb_prop in EG as [_ EB8].
          apply negb_true_iff in EB8. exact EB8. }
        assert (HNSB : ~ side8 (B,zb,cb)).
        { intros [HB _]. cbn [gO] in HB. subst B.
          cbn in HB8. discriminate. }
        match type of HRun with
        | (if ?X then _ else _) = _ => destruct X eqn:E5
        end.
        - destruct t2 as [|[[o2 z2] c2] t3]; [discriminate|].
          injection HRun as <- <-.
          apply andb_prop in E5 as [E5a E5b].
          apply andb_prop in E5a as [EB5 Ecb1].
          apply N.eqb_eq in EB5, Ecb1. subst B cb.
          apply andb_prop in E5b as [Eo2 Ez2].
          apply N.eqb_eq in Eo2, Ez2. subst o2 z2.
          pose proof EG as EG0.
          apply andb_prop in EG0 as [EG0 _].
          apply andb_prop in EG0 as [Ezb _].
          apply N.eqb_eq in Ezb. subst zb.
          eapply edge_out_replace_prefix_nonside with
            (pin := [(o,1%N,c); (5%N,2%N,1%N)])
            (l := (4%N,2%N,c2))
            (pout := [(o,1%N,1%N); (4%N,2%N,c2+1)%N]) (t := t3).
          + cbn [app]. exact HE.
          + apply not_side8_o4.
          + unfold shape_free. shape_lits_probe.
        - destruct (B =? 1)%N eqn:EB1.
          + apply N.eqb_eq in EB1. subst B.
            destruct (cb =? 1)%N; [|discriminate].
            injection HRun as <- <-.
            eapply edge_out_replace_prefix_nonside with
              (pin := [(o,1%N,c)]) (l := (1%N,zb,cb))
              (pout := [(o,3%N,1%N)]) (t := t2).
            * cbn [app]. exact HE.
            * exact HNSB.
            * unfold shape_free. shape_lits_probe.
          + destruct ((cb =? 1) && (2 <=? B))%N; [|discriminate].
            injection HRun as <- <-.
            eapply edge_out_replace_prefix_nonside with
              (pin := [(o,1%N,c)]) (l := (B,zb,cb))
              (pout := [(o,1%N,1%N); ((B-1)%N,zb,1%N)]) (t := t2).
            * cbn [app]. exact HE.
            * exact HNSB.
            * unfold shape_free. shape_lits_probe. }
      destruct ((B =? 8) && (zb =? 2) && (cb =? 1))%N eqn:E8.
      { apply andb_prop in E8 as [E8 Ecb].
        apply andb_prop in E8 as [EB Ez].
        apply N.eqb_eq in EB, Ez, Ecb. subst B zb cb.
        injection HRun as <- <-.
        assert (HH : shape_head_free t2).
        { intros g u Et. subst t2.
          eapply shape_lmargin_nonph_at with
            (q := O) (gq := (o,1%N,c)) (p := 2%nat).
          - exact HM.
          - reflexivity.
          - apply casc_z1_false.
          - reflexivity.
          - lia.
          - lia. }
        eapply edge_out_prefix_tail with
          (pout := [(o,1%N,1%N); (7%N,2%N,1%N)]) (t := t2).
        - unfold shape_free. shape_lits_probe.
        - exact HH.
        - apply (tag_edges_app_r_probe
            [(o,1%N,c); (8%N,2%N,1%N)] t2).
          cbn [app]. exact HE. }
      destruct ((B =? 4) && (zb =? 2))%N eqn:E4.
      { apply andb_prop in E4 as [EB Ez].
        apply N.eqb_eq in EB, Ez. subst B zb.
        destruct (cb =? 1)%N.
        - injection HRun as <- <-.
          eapply edge_out_replace_prefix_nonside with
            (pin := [(o,1%N,c)]) (l := (4%N,2%N,cb))
            (pout := [(o,1%N,1%N); (3%N,2%N,1%N)]) (t := t2).
          + cbn [app]. exact HE.
          + apply not_side8_o4.
          + unfold shape_free. shape_lits_probe.
        - destruct (2 <=? cb)%N; [|discriminate].
          injection HRun as <- <-.
          eapply edge_out_replace_prefix_nonside with
            (pin := [(o,1%N,c)]) (l := (4%N,2%N,cb))
            (pout := [(o,1%N,1%N); (3%N,2%N,1%N);
                      (4%N,2%N,(cb-1)%N)]) (t := t2).
          + cbn [app]. exact HE.
          + apply not_side8_o4.
          + unfold shape_free. shape_lits_probe. }
      destruct (zb =? 1)%N eqn:Ezb.
      { apply N.eqb_eq in Ezb. subst zb.
        destruct (2 <=? cb)%N.
        - destruct (2 <=? B)%N; [|discriminate].
          injection HRun as <- <-.
          eapply edge_out_replace_prefix_nonside with
            (pin := [(o,1%N,c)]) (l := (B,1%N,cb))
            (pout := [(o,1%N,1%N); ((B-1)%N,1%N,1%N);
                      (B,1%N,(cb-1)%N)]) (t := t2).
          + cbn [app]. exact HE.
          + apply not_side8_z1.
          + unfold shape_free. shape_lits_probe.
        - destruct (B =? 1)%N.
          + destruct (cb =? 1)%N; [|discriminate].
            injection HRun as <- <-.
            eapply edge_out_replace_prefix_nonside with
              (pin := [(o,1%N,c)]) (l := (B,1%N,cb))
              (pout := [(o,2%N,1%N)]) (t := t2).
            * cbn [app]. exact HE.
            * apply not_side8_z1.
            * unfold shape_free. shape_lits_probe.
          + destruct ((cb =? 1) && (2 <=? B))%N; [|discriminate].
            injection HRun as <- <-.
            eapply edge_out_replace_prefix_nonside with
              (pin := [(o,1%N,c)]) (l := (B,1%N,cb))
              (pout := [(o,1%N,1%N); ((B-1)%N,1%N,cb)]) (t := t2).
            * cbn [app]. exact HE.
            * apply not_side8_z1.
            * unfold shape_free. shape_lits_probe. }
      destruct ((3 <=? zb) && (cb =? 1))%N eqn:E3z; [|discriminate].
      apply andb_prop in E3z as [Ezb3 Ecb].
      apply N.leb_le in Ezb3. apply N.eqb_eq in Ecb. subst cb.
      destruct (B =? 1)%N.
      { injection HRun as <- <-.
        eapply edge_out_replace_prefix_nonside with
          (pin := [(o,1%N,c)]) (l := (B,zb,1%N))
          (pout := [(o,(zb+1)%N,1%N)]) (t := t2).
        - cbn [app]. exact HE.
        - apply not_side8_z_ge3. exact Ezb3.
        - unfold shape_free. shape_lits_probe. }
      destruct (2 <=? B)%N; [|discriminate].
      injection HRun as <- <-.
      eapply edge_out_replace_prefix_nonside with
        (pin := [(o,1%N,c)]) (l := (B,zb,1%N))
        (pout := [(o,1%N,1%N); ((B-1)%N,zb,1%N)]) (t := t2).
      - cbn [app]. exact HE.
      - apply not_side8_z_ge3. exact Ezb3.
      - unfold shape_free. shape_lits_probe. }
  - destruct zp as [zp'|zp'|]; cbn [leaf_act] in HRun;
      try discriminate.
    destruct c as [|[cp|cp|]]; cbn [leaf_act] in HRun;
      try discriminate.
    destruct ((5 <=? o) && negb (o =? 8) && negb (o =? 12))%N
      eqn:EO; [|discriminate].
    assert (HC : casc (o,2%N,1%N) = false)
      by (exact (casc_cmf_false o 1%N EO)).
    assert (HMt : shape_lmargin 2 t)
      by (exact (shape_lmargin_tail_noncasc 2 (o,2%N,1%N) t HM HC)).
    assert (HEt : tag_edges t)
      by (exact (tag_edges_tail (o,2%N,1%N) t HE)).
    destruct t as [|[[on zn] cn] t2].
    + destruct (f =? 3)%N; cbv beta iota in HRun.
      * injection HRun as <- <-. apply edge_out_shape_free.
        unfold shape_free. shape_lits_probe.
      * destruct (f =? 2)%N; cbv beta iota in HRun.
        -- injection HRun as <- <-. apply edge_out_shape_free.
           unfold shape_free. shape_lits_probe.
        -- destruct (f =? 4)%N; cbv beta iota in HRun;
             [injection HRun as <- <-|discriminate].
           apply edge_out_shape_free. unfold shape_free. shape_lits_probe.
    + destruct (on =? 1)%N; [discriminate|].
      destruct ((on =? 3) && (zn =? 2) && (cn =? 1) && (f =? 4))%N
        eqn:E3.
      * apply andb_prop in E3 as [E3 _].
        apply andb_prop in E3 as [E3 Ecn].
        apply andb_prop in E3 as [Eon Ezn].
        apply N.eqb_eq in Eon, Ezn, Ecn. subst on zn cn.
        destruct t2 as [|[[o2 z2] c2] t3].
        -- injection HRun as <- <-. apply edge_out_shape_free.
           unfold shape_free. shape_lits_probe.
        -- destruct t3 as [|g3 t4]; [|discriminate].
           destruct ((o2 =? 4) && (z2 =? 2))%N; [|discriminate].
           injection HRun as <- <-. apply edge_out_shape_free.
           unfold shape_free. shape_lits_probe.
      * destruct ((on =? 4) && (zn =? 2))%N eqn:E4.
        -- apply andb_prop in E4 as [Eon Ezn].
           apply N.eqb_eq in Eon, Ezn. subst on zn.
           destruct t2 as [|[[o2 z2] c2] t3].
           ++ destruct (f =? 4)%N; [|discriminate].
              injection HRun as <- <-. apply edge_out_shape_free.
              unfold shape_free. shape_lits_probe.
           ++ destruct t3 as [|[[o3 z3] c3] t4]; [discriminate|].
              destruct t4 as [|g4 t5]; [|discriminate].
              lazymatch type of HRun with
              | (if ?b then _ else _) = _ => destruct b eqn:EOr in HRun
              end; [|discriminate].
              apply andb_prop in EOr as [EOr _].
              apply andb_prop in EOr as [EOr Ez3].
              apply andb_prop in EOr as [EOr Eo3].
              apply andb_prop in EOr as [EOr Ec2].
              apply andb_prop in EOr as [EOr Ez2].
              apply andb_prop in EOr as [_ Eo2].
              apply N.eqb_eq in Eo2, Ez2, Ec2, Eo3, Ez3.
              subst o2 z2 c2 o3 z3.
              injection HRun as <- <-. apply edge_out_shape_free.
              unfold shape_free.
              destruct (cn =? 1)%N; shape_lits_probe.
        -- lazymatch type of HRun with
           | (if ?b then _ else _) = _ => destruct b eqn:EX6 in HRun
           end.
           ++ destruct t2 as [|[[o2 z2] c2] t3]; [discriminate|].
              destruct t3 as [|g3 t4]; [|discriminate].
              apply andb_prop in EX6 as [EX6 EM].
              apply andb_prop in EX6 as [EX6 _].
              apply andb_prop in EX6 as [EX6 Ecn].
              apply andb_prop in EX6 as [EX6 Ezn].
              apply andb_prop in EX6 as [_ Eon].
              apply N.eqb_eq in Eon, Ezn, Ecn. subst on zn cn.
              apply andb_prop in EM as [Eo Ez].
              apply N.eqb_eq in Eo, Ez. subst o2 z2.
              injection HRun as <- <-. apply edge_out_shape_free.
              unfold shape_free. shape_lits_probe.
           ++ lazymatch type of HRun with
              | (if ?b then _ else _) = _ => destruct b in HRun
              end; [|discriminate].
              lazymatch type of HRun with
              | context [leaf_act ?w ?ff] =>
                  destruct (leaf_act w ff) as [[s' f']|] eqn:ERC
              end; [|discriminate].
              cbv beta iota in HRun. injection HRun as <- <-.
              change (edge_out ([(o,2%N,1%N)] ++ s')).
              apply edge_out_lits_app.
              ** unfold shape_free. shape_lits_probe.
              ** exact (IH f s' f' HMt HEt ERC).
Qed.
Lemma leaf_act_notlast_probe : forall s f s2 f2,
  shape_notlast s -> leaf_act s f = Some (s2, f2) ->
  shape_notlast s2.
Proof.
  induction s as [|[[o z] c] t IH]; intros f s2 f2 HN HRun;
    [discriminate|].
  destruct z as [|[zp|zp|]].
  { cbn [leaf_act] in HRun. discriminate. }
  { cbn [leaf_act] in HRun. discriminate. }
  2:{ cbn [leaf_act] in HRun.
      assert (HNt : shape_notlast t)
        by (exact (shape_notlast_app_r [(o,1%N,c)] t
                    ltac:(cbn [app]; exact HN))).
      destruct (2 <=? c)%N.
      { destruct (2 <=? o)%N; [|discriminate].
        injection HRun as <- <-. destruct (2 <? c)%N.
        - change (shape_notlast
            ([(o,1%N,1%N); ((o-1)%N,1%N,1%N);
              (o,1%N,(c-2)%N)] ++ t)).
          apply shape_notlast_lits_app;
            [unfold shape_free; shape_lits_probe|exact HNt].
        - change (shape_notlast
            ([(o,1%N,1%N); ((o-1)%N,1%N,1%N)] ++ t)).
          apply shape_notlast_lits_app;
            [unfold shape_free; shape_lits_probe|exact HNt]. }
      destruct (negb (c =? 1) || negb (2 <=? o))%N; [discriminate|].
      destruct t as [|[[B zb] cb] t2].
      { destruct (2 <=? f)%N.
        - injection HRun as <- <-. apply shape_notlast_shape_free.
          unfold shape_free. shape_lits_probe.
        - destruct (f =? 1)%N; [|discriminate].
          injection HRun as <- <-. apply shape_notlast_shape_free.
          unfold shape_free. shape_lits_probe. }
      assert (HNt2 : shape_notlast t2).
      { apply (shape_notlast_app_r
          [(o,1%N,c); (B,zb,cb)] t2).
        cbn [app]. exact HN. }
      match type of HRun with
      | (if ?X then _ else _) = _ => destruct X eqn:EG
      end.
      { match type of HRun with
        | (if ?X then _ else _) = _ => destruct X eqn:E5
        end.
        - destruct t2 as [|[[o2 z2] c2] t3]; [discriminate|].
          injection HRun as <- <-.
          apply andb_prop in E5 as [E5a E5b].
          apply andb_prop in E5a as [EB5 Ecb1].
          apply N.eqb_eq in EB5, Ecb1. subst B cb.
          apply andb_prop in E5b as [Eo2 Ez2].
          apply N.eqb_eq in Eo2, Ez2. subst o2 z2.
          eapply shape_notlast_lits_app with
            (p := [(o,1%N,1%N); (4%N,2%N,c2+1)%N]) (t := t3).
          + unfold shape_free. shape_lits_probe.
          + apply (shape_notlast_app_r
              [(o,1%N,c); (5%N,zb,1%N); (4%N,2%N,c2)] t3).
            cbn [app]. exact HN.
        - destruct (B =? 1)%N.
          + destruct (cb =? 1)%N; [|discriminate].
            injection HRun as <- <-.
            eapply shape_notlast_lits_app with
              (p := [(o,3%N,1%N)]) (t := t2).
            * unfold shape_free. shape_lits_probe.
            * exact HNt2.
          + destruct ((cb =? 1) && (2 <=? B))%N; [|discriminate].
            injection HRun as <- <-.
            eapply shape_notlast_lits_app with
              (p := [(o,1%N,1%N); ((B-1)%N,zb,1%N)]) (t := t2).
            * unfold shape_free. shape_lits_probe.
            * exact HNt2. }
      destruct ((B =? 8) && (zb =? 2) && (cb =? 1))%N.
      { injection HRun as <- <-.
        eapply shape_notlast_lits_app with
          (p := [(o,1%N,1%N); (7%N,2%N,1%N)]) (t := t2).
        - unfold shape_free. shape_lits_probe.
        - exact HNt2. }
      destruct ((B =? 4) && (zb =? 2))%N eqn:E4.
      { apply andb_prop in E4 as [EB Ez].
        apply N.eqb_eq in EB, Ez. subst B zb.
        destruct (cb =? 1)%N.
        - injection HRun as <- <-.
          eapply shape_notlast_lits_app with
            (p := [(o,1%N,1%N); (3%N,2%N,1%N)]) (t := t2).
          + unfold shape_free. shape_lits_probe.
          + exact HNt2.
        - destruct (2 <=? cb)%N; [|discriminate].
          injection HRun as <- <-.
          eapply shape_notlast_lits_app with
            (p := [(o,1%N,1%N); (3%N,2%N,1%N);
                    (4%N,2%N,(cb-1)%N)]) (t := t2).
          + unfold shape_free. shape_lits_probe.
          + exact HNt2. }
      destruct (zb =? 1)%N eqn:Ezb.
      { apply N.eqb_eq in Ezb. subst zb.
        destruct (2 <=? cb)%N.
        - destruct (2 <=? B)%N; [|discriminate].
          injection HRun as <- <-.
          eapply shape_notlast_lits_app with
            (p := [(o,1%N,1%N); ((B-1)%N,1%N,1%N);
                    (B,1%N,(cb-1)%N)]) (t := t2).
          + unfold shape_free. shape_lits_probe.
          + exact HNt2.
        - destruct (B =? 1)%N.
          + destruct (cb =? 1)%N; [|discriminate].
            injection HRun as <- <-.
            eapply shape_notlast_lits_app with
              (p := [(o,2%N,1%N)]) (t := t2).
            * unfold shape_free. shape_lits_probe.
            * exact HNt2.
          + destruct ((cb =? 1) && (2 <=? B))%N; [|discriminate].
            injection HRun as <- <-.
            eapply shape_notlast_lits_app with
              (p := [(o,1%N,1%N); ((B-1)%N,1%N,cb)]) (t := t2).
            * unfold shape_free. shape_lits_probe.
            * exact HNt2. }
      destruct ((3 <=? zb) && (cb =? 1))%N eqn:E3z; [|discriminate].
      apply andb_prop in E3z as [Ezb3 Ecb].
      apply N.leb_le in Ezb3. apply N.eqb_eq in Ecb. subst cb.
      destruct (B =? 1)%N.
      { injection HRun as <- <-.
        eapply shape_notlast_lits_app with
          (p := [(o,(zb+1)%N,1%N)]) (t := t2).
        - unfold shape_free. shape_lits_probe.
        - exact HNt2. }
      destruct (2 <=? B)%N; [|discriminate].
      injection HRun as <- <-.
      eapply shape_notlast_lits_app with
        (p := [(o,1%N,1%N); ((B-1)%N,zb,1%N)]) (t := t2).
      + unfold shape_free. shape_lits_probe.
      + exact HNt2. }
  - destruct zp as [zp'|zp'|]; cbn [leaf_act] in HRun;
      try discriminate.
    destruct c as [|[cp|cp|]]; cbn [leaf_act] in HRun;
      try discriminate.
    destruct ((5 <=? o) && negb (o =? 8) && negb (o =? 12))%N;
      [|discriminate].
    assert (HNt : shape_notlast t)
      by (exact (shape_notlast_app_r [(o,2%N,1%N)] t
                  ltac:(cbn [app]; exact HN))).
    destruct t as [|[[on zn] cn] t2].
    + destruct (f =? 3)%N; cbv beta iota in HRun.
      * injection HRun as <- <-. apply shape_notlast_shape_free.
        unfold shape_free. shape_lits_probe.
      * destruct (f =? 2)%N; cbv beta iota in HRun.
        -- injection HRun as <- <-. apply shape_notlast_shape_free.
           unfold shape_free. shape_lits_probe.
        -- destruct (f =? 4)%N; cbv beta iota in HRun;
             [injection HRun as <- <-|discriminate].
           apply shape_notlast_shape_free. unfold shape_free. shape_lits_probe.
    + destruct (on =? 1)%N; [discriminate|].
      destruct ((on =? 3) && (zn =? 2) && (cn =? 1) && (f =? 4))%N
        eqn:E3.
      * apply andb_prop in E3 as [E3 _].
        apply andb_prop in E3 as [E3 Ecn].
        apply andb_prop in E3 as [Eon Ezn].
        apply N.eqb_eq in Eon, Ezn, Ecn. subst on zn cn.
        destruct t2 as [|[[o2 z2] c2] t3].
        -- injection HRun as <- <-. apply shape_notlast_shape_free.
           unfold shape_free. shape_lits_probe.
        -- destruct t3 as [|g3 t4]; [|discriminate].
           destruct ((o2 =? 4) && (z2 =? 2))%N eqn:E42;
             [|discriminate].
           apply andb_prop in E42 as [Eo Ez].
           apply N.eqb_eq in Eo, Ez. subst o2 z2.
           injection HRun as <- <-. apply shape_notlast_shape_free.
           unfold shape_free. shape_lits_probe.
      * destruct ((on =? 4) && (zn =? 2))%N eqn:E4.
        -- apply andb_prop in E4 as [Eon Ezn].
           apply N.eqb_eq in Eon, Ezn. subst on zn.
           destruct t2 as [|[[o2 z2] c2] t3].
           ++ destruct (f =? 4)%N; [|discriminate].
              injection HRun as <- <-. apply shape_notlast_shape_free.
              unfold shape_free. shape_lits_probe.
           ++ destruct t3 as [|[[o3 z3] c3] t4]; [discriminate|].
              destruct t4 as [|g4 t5]; [|discriminate].
              lazymatch type of HRun with
              | (if ?b then _ else _) = _ => destruct b eqn:EOr in HRun
              end; [|discriminate].
              apply andb_prop in EOr as [EOr _].
              apply andb_prop in EOr as [EOr Ez3].
              apply andb_prop in EOr as [EOr Eo3].
              apply andb_prop in EOr as [EOr Ec2].
              apply andb_prop in EOr as [EOr Ez2].
              apply andb_prop in EOr as [_ Eo2].
              apply N.eqb_eq in Eo2, Ez2, Ec2, Eo3, Ez3.
              subst o2 z2 c2 o3 z3.
              injection HRun as <- <-. apply shape_notlast_shape_free.
              unfold shape_free. destruct (cn =? 1)%N; shape_lits_probe.
        -- lazymatch type of HRun with
           | (if ?b then _ else _) = _ => destruct b eqn:EX6 in HRun
           end.
           ++ destruct t2 as [|[[o2 z2] c2] t3]; [discriminate|].
              destruct t3 as [|g3 t4]; [|discriminate].
              apply andb_prop in EX6 as [EX6 EM].
              apply andb_prop in EX6 as [EX6 _].
              apply andb_prop in EX6 as [EX6 Ecn].
              apply andb_prop in EX6 as [EX6 Ezn].
              apply andb_prop in EX6 as [_ Eon].
              apply N.eqb_eq in Eon, Ezn, Ecn. subst on zn cn.
              apply andb_prop in EM as [Eo Ez].
              apply N.eqb_eq in Eo, Ez. subst o2 z2.
              injection HRun as <- <-. apply shape_notlast_shape_free.
              unfold shape_free. shape_lits_probe.
           ++ lazymatch type of HRun with
              | (if ?b then _ else _) = _ => destruct b in HRun
              end; [|discriminate].
              lazymatch type of HRun with
              | context [leaf_act ?w ?ff] =>
                  destruct (leaf_act w ff) as [[s' f']|] eqn:ERC
              end; [|discriminate].
              cbv beta iota in HRun. injection HRun as <- <-.
              change (shape_notlast ([(o,2%N,1%N)] ++ s')).
              eapply shape_notlast_lits_app with
                (p := [(o,2%N,1%N)]) (t := s').
              ** unfold shape_free. shape_lits_probe.
              ** exact (IH f s' f' HNt ERC).
Qed.
Lemma leaf_act_edge_pack2_probe : forall s f s2 f2,
  shape_lmargin 2 s -> edge_pack s ->
  leaf_act s f = Some (s2, f2) -> edge_pack s2.
Proof.
  intros s f s2 f2 HM [[HH HE] HN] HR. split.
  - exact (leaf_act_edges2_probe s f s2 f2 HM HE HR).
  - exact (leaf_act_notlast_probe s f s2 f2 HN HR).
Qed.
Lemma leaf_act_margin3to2_probe : forall s f s2 f2,
  shape_lmargin 3 s -> leaf_act s f = Some (s2, f2) ->
  shape_lmargin 2 s2.
Proof.
  induction s as [|[[o z] c] t IH]; intros f s2 f2 HM HRun;
    [discriminate|].
  destruct z as [|[zp|zp|]].
  { cbn [leaf_act] in HRun. discriminate. }
  { cbn [leaf_act] in HRun. discriminate. }
  2:{ cbn [leaf_act] in HRun.
      assert (HMt3 : shape_lmargin 3 t).
      { exact (shape_lmargin_tail_noncasc 3 (o,1%N,c) t HM
                 (casc_z1_false o c)). }
      assert (HMt2 : shape_lmargin 2 t)
        by (exact (shape_lmargin_weaken 3 2 t ltac:(lia) HMt3)).
      destruct (2 <=? c)%N.
      { destruct (2 <=? o)%N; [|discriminate].
        injection HRun as <- <-. destruct (2 <? c)%N.
        - change (shape_lmargin 2
            ([(o,1%N,1%N); ((o-1)%N,1%N,1%N);
              (o,1%N,(c-2)%N)] ++ t)).
          apply shape_lmargin_lits_app;
            [unfold shape_free; shape_lits_probe|exact HMt2].
        - change (shape_lmargin 2
            ([(o,1%N,1%N); ((o-1)%N,1%N,1%N)] ++ t)).
          apply shape_lmargin_lits_app;
            [unfold shape_free; shape_lits_probe|exact HMt2]. }
      destruct (negb (c =? 1) || negb (2 <=? o))%N; [discriminate|].
      destruct t as [|[[B zb] cb] t2].
      { destruct (2 <=? f)%N.
        - injection HRun as <- <-. apply shape_lmargin_shape_free.
          unfold shape_free. shape_lits_probe.
        - destruct (f =? 1)%N; [|discriminate].
          injection HRun as <- <-. apply shape_lmargin_shape_free.
          unfold shape_free. shape_lits_probe. }
      assert (HMt2' : shape_lmargin 2 t2).
      { exact (shape_lmargin_tail_drop 2 (B,zb,cb) t2 HMt3). }
      match type of HRun with
      | (if ?X then _ else _) = _ => destruct X eqn:EG
      end.
      { match type of HRun with
        | (if ?X then _ else _) = _ => destruct X eqn:E5
        end.
        - destruct t2 as [|[[o2 z2] c2] t3]; [discriminate|].
          injection HRun as <- <-.
          apply andb_prop in E5 as [E5a E5b].
          apply andb_prop in E5a as [EB5 Ecb1].
          apply N.eqb_eq in EB5, Ecb1. subst B cb.
          apply andb_prop in E5b as [Eo2 Ez2].
          apply N.eqb_eq in Eo2, Ez2. subst o2 z2.
          change (shape_lmargin 2
            ([(o,1%N,1%N)] ++ (4%N,2%N,c2+1)%N :: t3)).
          apply shape_lmargin_lits_app.
          + unfold shape_free. shape_lits_probe.
          + eapply shape_lmargin_replace_head with
              (a := (4%N,2%N,c2)).
            * apply phshape_onot9. reflexivity.
            * reflexivity.
            * exact HMt2'.
        - destruct (B =? 1)%N.
          + destruct (cb =? 1)%N; [|discriminate].
            injection HRun as <- <-.
            eapply shape_lmargin_lits_app with
              (p := [(o,3%N,1%N)]) (t := t2).
            * unfold shape_free. shape_lits_probe.
            * exact HMt2'.
          + destruct ((cb =? 1) && (2 <=? B))%N; [|discriminate].
            injection HRun as <- <-.
            eapply shape_lmargin_lits_app with
              (p := [(o,1%N,1%N); ((B-1)%N,zb,1%N)]) (t := t2).
            * unfold shape_free. shape_lits_probe.
            * exact HMt2'. }
      destruct ((B =? 8) && (zb =? 2) && (cb =? 1))%N.
      { injection HRun as <- <-.
        eapply shape_lmargin_lits_app with
          (p := [(o,1%N,1%N); (7%N,2%N,1%N)]) (t := t2).
        - unfold shape_free. shape_lits_probe.
        - exact HMt2'. }
      destruct ((B =? 4) && (zb =? 2))%N eqn:E4.
      { apply andb_prop in E4 as [EB Ez].
        apply N.eqb_eq in EB, Ez. subst B zb.
        destruct (cb =? 1)%N.
        - injection HRun as <- <-.
          eapply shape_lmargin_lits_app with
            (p := [(o,1%N,1%N); (3%N,2%N,1%N)]) (t := t2).
          + unfold shape_free. shape_lits_probe.
          + exact HMt2'.
        - destruct (2 <=? cb)%N; [|discriminate].
          injection HRun as <- <-.
          eapply shape_lmargin_lits_app with
            (p := [(o,1%N,1%N); (3%N,2%N,1%N);
                    (4%N,2%N,(cb-1)%N)]) (t := t2).
          + unfold shape_free. shape_lits_probe.
          + exact HMt2'. }
      destruct (zb =? 1)%N eqn:Ezb.
      { apply N.eqb_eq in Ezb. subst zb.
        destruct (2 <=? cb)%N.
        - destruct (2 <=? B)%N; [|discriminate].
          injection HRun as <- <-.
          eapply shape_lmargin_lits_app with
            (p := [(o,1%N,1%N); ((B-1)%N,1%N,1%N);
                    (B,1%N,(cb-1)%N)]) (t := t2).
          + unfold shape_free. shape_lits_probe.
          + exact HMt2'.
        - destruct (B =? 1)%N.
          + destruct (cb =? 1)%N; [|discriminate].
            injection HRun as <- <-.
            eapply shape_lmargin_lits_app with
              (p := [(o,2%N,1%N)]) (t := t2).
            * unfold shape_free. shape_lits_probe.
            * exact HMt2'.
          + destruct ((cb =? 1) && (2 <=? B))%N; [|discriminate].
            injection HRun as <- <-.
            eapply shape_lmargin_lits_app with
              (p := [(o,1%N,1%N); ((B-1)%N,1%N,cb)]) (t := t2).
            * unfold shape_free. shape_lits_probe.
            * exact HMt2'. }
      destruct ((3 <=? zb) && (cb =? 1))%N eqn:E3z; [|discriminate].
      apply andb_prop in E3z as [Ezb3 Ecb].
      apply N.leb_le in Ezb3. apply N.eqb_eq in Ecb. subst cb.
      destruct (B =? 1)%N.
      { injection HRun as <- <-.
        eapply shape_lmargin_lits_app with
          (p := [(o,(zb+1)%N,1%N)]) (t := t2).
        - unfold shape_free. shape_lits_probe.
        - exact HMt2'. }
      destruct (2 <=? B)%N; [|discriminate].
      injection HRun as <- <-.
      eapply shape_lmargin_lits_app with
        (p := [(o,1%N,1%N); ((B-1)%N,zb,1%N)]) (t := t2).
      - unfold shape_free. shape_lits_probe.
      - exact HMt2'. }
  - destruct zp as [zp'|zp'|]; cbn [leaf_act] in HRun;
      try discriminate.
    destruct c as [|[cp|cp|]]; cbn [leaf_act] in HRun;
      try discriminate.
    destruct ((5 <=? o) && negb (o =? 8) && negb (o =? 12))%N
      eqn:EO; [|discriminate].
    assert (HMt3 : shape_lmargin 3 t).
    { exact (shape_lmargin_tail_noncasc 3 (o,2%N,1%N) t HM
               (casc_cmf_false o 1%N EO)). }
    destruct t as [|[[on zn] cn] t2].
    + destruct (f =? 3)%N; cbv beta iota in HRun.
      * injection HRun as <- <-. apply shape_lmargin_shape_free.
        unfold shape_free. shape_lits_probe.
      * destruct (f =? 2)%N; cbv beta iota in HRun.
        -- injection HRun as <- <-. apply shape_lmargin_shape_free.
           unfold shape_free. shape_lits_probe.
        -- destruct (f =? 4)%N; cbv beta iota in HRun;
             [injection HRun as <- <-|discriminate].
           apply shape_lmargin_shape_free. unfold shape_free. shape_lits_probe.
    + destruct (on =? 1)%N; [discriminate|].
      destruct ((on =? 3) && (zn =? 2) && (cn =? 1) && (f =? 4))%N
        eqn:E3.
      * apply andb_prop in E3 as [E3 _].
        apply andb_prop in E3 as [E3 Ecn].
        apply andb_prop in E3 as [Eon Ezn].
        apply N.eqb_eq in Eon, Ezn, Ecn. subst on zn cn.
        destruct t2 as [|[[o2 z2] c2] t3].
        -- injection HRun as <- <-. apply shape_lmargin_shape_free.
           unfold shape_free. shape_lits_probe.
        -- destruct t3 as [|g3 t4]; [|discriminate].
           destruct ((o2 =? 4) && (z2 =? 2))%N eqn:E42;
             [|discriminate].
           apply andb_prop in E42 as [Eo Ez].
           apply N.eqb_eq in Eo, Ez. subst o2 z2.
           injection HRun as <- <-. apply shape_lmargin_shape_free.
           unfold shape_free. shape_lits_probe.
      * destruct ((on =? 4) && (zn =? 2))%N eqn:E4.
        -- apply andb_prop in E4 as [Eon Ezn].
           apply N.eqb_eq in Eon, Ezn. subst on zn.
           destruct t2 as [|[[o2 z2] c2] t3].
           ++ destruct (f =? 4)%N; [|discriminate].
              injection HRun as <- <-. apply shape_lmargin_shape_free.
              unfold shape_free. shape_lits_probe.
           ++ destruct t3 as [|[[o3 z3] c3] t4]; [discriminate|].
              destruct t4 as [|g4 t5]; [|discriminate].
              lazymatch type of HRun with
              | (if ?b then _ else _) = _ => destruct b eqn:EOr in HRun
              end; [|discriminate].
              apply andb_prop in EOr as [EOr _].
              apply andb_prop in EOr as [EOr Ez3].
              apply andb_prop in EOr as [EOr Eo3].
              apply andb_prop in EOr as [EOr Ec2].
              apply andb_prop in EOr as [EOr Ez2].
              apply andb_prop in EOr as [_ Eo2].
              apply N.eqb_eq in Eo2, Ez2, Ec2, Eo3, Ez3.
              subst o2 z2 c2 o3 z3.
              injection HRun as <- <-. apply shape_lmargin_shape_free.
              unfold shape_free. destruct (cn =? 1)%N; shape_lits_probe.
        -- lazymatch type of HRun with
           | (if ?b then _ else _) = _ => destruct b eqn:EX6 in HRun
           end.
           ++ destruct t2 as [|[[o2 z2] c2] t3]; [discriminate|].
              destruct t3 as [|g3 t4]; [|discriminate].
              apply andb_prop in EX6 as [EX6 EM].
              apply andb_prop in EX6 as [EX6 _].
              apply andb_prop in EX6 as [EX6 Ecn].
              apply andb_prop in EX6 as [EX6 Ezn].
              apply andb_prop in EX6 as [_ Eon].
              apply N.eqb_eq in Eon, Ezn, Ecn. subst on zn cn.
              apply andb_prop in EM as [Eo Ez].
              apply N.eqb_eq in Eo, Ez. subst o2 z2.
              injection HRun as <- <-. apply shape_lmargin_shape_free.
              unfold shape_free. shape_lits_probe.
           ++ lazymatch type of HRun with
              | (if ?b then _ else _) = _ => destruct b in HRun
              end; [|discriminate].
              lazymatch type of HRun with
              | context [leaf_act ?w ?ff] =>
                  destruct (leaf_act w ff) as [[s' f']|] eqn:ERC
              end; [|discriminate].
              cbv beta iota in HRun. injection HRun as <- <-.
              change (shape_lmargin 2 ([(o,2%N,1%N)] ++ s')).
              apply shape_lmargin_lits_app.
              ** unfold shape_free. shape_lits_probe.
              ** exact (IH f s' f' HMt3 ERC).
Qed.
Ltac split_last2_margin H cols :=
  lazymatch type of H with
  | context [last2 cols] =>
      destruct (last2 cols)
        as [[[ini [[ga gaz] gac]] [[gb gbz] gbc]]|] eqn:EL in H;
        [|discriminate];
      pose proof (LineageGuard_last2_split cols ini
        (ga,gaz,gac) (gb,gbz,gbc) EL) as EC;
      subst cols
  end.
Ltac split_bool_ands E :=
  repeat match type of E with
  | (_ && _)%bool = true =>
      apply andb_prop in E; destruct E as [E ?E]
  end.
Lemma lawR_seg_lmargin_probe : forall n cols B body,
  shape_lmargin n cols -> lawR_seg cols B = Some body ->
  shape_lmargin n body.
Proof.
  intros n cols B body HM H. unfold lawR_seg in H.
  split_last2_margin H cols.
  destruct ((ga =? 8) && (gaz =? 2) && (gac =? 1)
    && (gb =? 4) && (gbz =? 2) && (1 <=? gbc))%N eqn:E1.
  - injection H as <-. split_bool_ands E1.
    repeat match goal with
    | E : (_ =? _)%N = true |- _ => apply N.eqb_eq in E
    end. subst ga gaz gac gb gbz.
    apply shape_lmargin_phfree_suffix.
    + exact (shape_lmargin_prefix n ini
        [(8%N,2%N,1%N); (4%N,2%N,gbc)] HM).
    + unfold shape_free. destruct (1 <? B)%N; shape_lits_probe.
  - destruct ((gb =? 8) && (gbz =? 2) && (gbc =? 1))%N eqn:E2;
      [|discriminate].
    injection H as <-. split_bool_ands E2.
    repeat match goal with
    | E : (_ =? _)%N = true |- _ => apply N.eqb_eq in E
    end. subst gb gbz gbc.
    apply shape_lmargin_prefix_cons_phfree.
    + apply (shape_lmargin_prefix n (ini ++ [(ga,gaz,gac)])
        [(8%N,2%N,1%N)]).
      rewrite <- app_assoc. cbn [app]. exact HM.
    + unfold shape_free. destruct (1 <? B)%N; shape_lits_probe.
Qed.
