Lemma shape_free_w42_probe : forall w,
  forallb w42 w = true -> shape_free w.
Proof.
  intros w HW g Hg. apply forallb_forall with (x := g) in HW; [|exact Hg].
  pose proof (w42_notag g HW) as HN.
  unfold notag in HN. apply negb_true_iff in HN. exact HN.
Qed.
Lemma dtb4_conv_lmargin_ctx_probe : forall n body pre body',
  shape_lmargin n (pre ++ body) ->
  dtb4_conv body = Some body' ->
  shape_lmargin n (pre ++ body').
Proof.
  intros n body. induction body as [|[[o z] c] t IH];
    intros pre body' HM H; [discriminate|].
  cbn [dtb4_conv] in H.
  destruct (dtb4_conv t) as [t'|] eqn:ED.
  - injection H as <-.
    specialize (IH (pre ++ [(o,z,c)]) t').
    repeat rewrite <- app_assoc in IH. cbn [app] in IH.
    exact (IH HM eq_refl).
  - lazymatch type of H with
    | (if ?b then _ else _) = _ => destruct b eqn:E8 in H
    end; [|discriminate].
    cbn [gO gZ gC] in E8.
    apply andb_prop in E8 as [E8 Ec].
    apply andb_prop in E8 as [Eo Ez].
    apply N.eqb_eq in Eo, Ez, Ec. subst o z c.
    lazymatch type of H with
    | (if ?b then _ else _) = _ => destruct b eqn:EW in H
    end.
    + injection H as <-. apply shape_lmargin_phfree_suffix.
      * exact (shape_lmargin_prefix n pre ((8%N,2%N,1%N)::t) HM).
      * unfold shape_free. intros g Hg.
        destruct Hg as [<-|Hg]; [apply phshape_c1|].
        destruct Hg as [<-|Hg]; [apply phshape_c1|].
        exact (shape_free_w42_probe t EW g Hg).
    + destruct t as [|[[o1 z1] c1] [|[[o2 z2] c2] t2]];
        try discriminate.
      lazymatch type of H with
      | (if ?b then _ else _) = _ => destruct b eqn:EOr in H
      end; [|discriminate].
      apply andb_prop in EOr as [EOr Ec2].
      apply andb_prop in EOr as [EOr Ez2].
      apply andb_prop in EOr as [EOr Eo2].
      apply andb_prop in EOr as [EOr _].
      apply andb_prop in EOr as [Eo1 Ez1].
      apply N.eqb_eq in Eo1, Ez1, Eo2, Ez2, Ec2.
      rewrite Eo1, Ez1, Eo2, Ez2, Ec2 in *.
      destruct t2 as [|[[o3 z3] c3] [|g4 t4]]; try discriminate.
      * injection H as <-. apply shape_lmargin_phfree_suffix.
        -- exact (shape_lmargin_prefix n pre
             ((8%N,2%N,1%N)::(4%N,2%N,c1)::(3%N,2%N,1%N)::[]) HM).
        -- unfold shape_free. destruct (1 <? c1)%N; shape_lits_probe.
      * lazymatch type of H with
        | (if ?b then _ else _) = _ => destruct b eqn:E3 in H
        end; [|discriminate].
        apply andb_prop in E3 as [Eo3 Ez3].
        apply N.eqb_eq in Eo3, Ez3. rewrite Eo3, Ez3 in *.
        injection H as <-. apply shape_lmargin_phfree_suffix.
        -- exact (shape_lmargin_prefix n pre
             ((8%N,2%N,1%N)::(4%N,2%N,c1)::(3%N,2%N,1%N)::
              (4%N,2%N,c3)::[]) HM).
        -- unfold shape_free. destruct (1 <? c1)%N; shape_lits_probe.
Qed.
Lemma dtb3_conv_lmargin_ctx_probe : forall n body pre body',
  shape_lmargin n (pre ++ body) ->
  dtb3_conv body = Some body' ->
  shape_lmargin n (pre ++ body').
Proof.
  intros n body. induction body as [|[[o z] c] t IH];
    intros pre body' HM H; [discriminate|].
  cbn [dtb3_conv] in H.
  destruct (dtb3_conv t) as [t'|] eqn:ED.
  - injection H as <-.
    specialize (IH (pre ++ [(o,z,c)]) t').
    repeat rewrite <- app_assoc in IH. cbn [app] in IH.
    exact (IH HM eq_refl).
  - lazymatch type of H with
    | (if ?b then _ else _) = _ => destruct b eqn:E8 in H
    end; [|discriminate].
    cbn [gO gZ gC] in E8.
    apply andb_prop in E8 as [E8 Ec].
    apply andb_prop in E8 as [Eo Ez].
    apply N.eqb_eq in Eo, Ez, Ec. subst o z c.
    destruct t as [|[[o1 z1] c1] t1]; [discriminate|].
    lazymatch type of H with
    | (if ?b then _ else _) = _ => destruct b eqn:E1 in H
    end; [|discriminate].
    apply andb_prop in E1 as [E1 EW].
    apply andb_prop in E1 as [E1 _].
    apply andb_prop in E1 as [Eo1 Ez1].
    apply N.eqb_eq in Eo1, Ez1. rewrite Eo1, Ez1 in *.
    injection H as <-. apply shape_lmargin_phfree_suffix.
    + exact (shape_lmargin_prefix n pre
        ((8%N,2%N,1%N)::(4%N,2%N,c1)::t1) HM).
    + unfold shape_free. intros g Hg.
      destruct Hg as [<-|Hg]; [apply phshape_c1|].
      destruct Hg as [<-|Hg]; [apply phshape_c1|].
      destruct Hg as [<-|Hg].
      * apply phshape_onot9. reflexivity.
      * exact (shape_free_w42_probe t1 EW g Hg).
Qed.
Corollary dtb4_conv_lmargin_probe : forall n body body',
  shape_lmargin n body -> dtb4_conv body = Some body' ->
  shape_lmargin n body'.
Proof.
  intros n body body' HM H.
  exact (dtb4_conv_lmargin_ctx_probe n body [] body' HM H).
Qed.
Corollary dtb3_conv_lmargin_probe : forall n body body',
  shape_lmargin n body -> dtb3_conv body = Some body' ->
  shape_lmargin n body'.
Proof.
  intros n body body' HM H.
  exact (dtb3_conv_lmargin_ctx_probe n body [] body' HM H).
Qed.
Definition shape_rmargin1 (w : word) : Prop :=
  forall p g, nth_error w p = Some g -> phshape g = true ->
    exists gr, nth_error w (p + 1) = Some gr /\
               casc gr = true /\ phshape gr = false.
Lemma shape_rmargin1_shape_free : forall w,
  shape_free w -> shape_rmargin1 w.
Proof.
  intros w HF p g Hg HS.
  rewrite (HF g (nth_error_In w p Hg)) in HS. discriminate.
Qed.
Lemma shape_rmargin1_app : forall a b,
  shape_rmargin1 a -> shape_rmargin1 b -> shape_rmargin1 (a ++ b).
Proof.
  intros a b HA HB p g Hg HS.
  destruct (PeanoNat.Nat.lt_ge_cases p (length a)) as [Hp|Hp].
  - rewrite nth_error_app1 in Hg by exact Hp.
    destruct (HA p g Hg HS) as (gr & Hgr & HC & HPh).
    exists gr. split.
    + rewrite nth_error_app1 by
        (apply nth_error_Some; rewrite Hgr; discriminate).
      exact Hgr.
    + auto.
  - rewrite nth_error_app2 in Hg by exact Hp.
    destruct (HB (p - length a)%nat g Hg HS)
      as (gr & Hgr & HC & HPh).
    exists gr. split.
    + rewrite nth_error_app2 by lia.
      replace (p + 1 - length a)%nat with
        ((p - length a) + 1)%nat by lia.
      exact Hgr.
    + auto.
Qed.
Lemma shape_rmargin1_app_r : forall a b,
  shape_rmargin1 (a ++ b) -> shape_rmargin1 b.
Proof.
  intros a b H p g Hg HS.
  assert (Hg' : nth_error (a ++ b) (length a + p) = Some g).
  { rewrite nth_error_app2 by lia.
    replace (length a + p - length a)%nat with p by lia. exact Hg. }
  destruct (H _ _ Hg' HS) as (gr & Hgr & HC & HPh).
  exists gr. split.
  - rewrite nth_error_app2 in Hgr by lia.
    replace (length a + p + 1 - length a)%nat with (p+1)%nat in Hgr
      by lia.
    exact Hgr.
  - auto.
Qed.
Lemma shape_rmargin1_lits_app : forall a b,
  shape_free a -> shape_rmargin1 b -> shape_rmargin1 (a ++ b).
Proof.
  intros a b HA HB. apply shape_rmargin1_app;
    [apply shape_rmargin1_shape_free|]; assumption.
Qed.
Lemma shape_notlast_of_rmargin1 : forall w,
  shape_rmargin1 w -> shape_notlast w.
Proof.
  intros w H p g Hg HS.
  destruct (H p g Hg HS) as (gr & Hgr & _).
  apply nth_error_Some. rewrite Hgr. discriminate.
Qed.
Lemma leaf_act_rmargin1_probe : forall s f s2 f2,
  shape_rmargin1 s -> leaf_act s f = Some (s2, f2) ->
  shape_rmargin1 s2.
Proof.
  induction s as [|[[o z] c] t IH]; intros f s2 f2 HR HRun;
    [discriminate|].
  destruct z as [|[zp|zp|]].
  { cbn [leaf_act] in HRun. discriminate. }
  { cbn [leaf_act] in HRun. discriminate. }
  2:{ cbn [leaf_act] in HRun.
      assert (HRt : shape_rmargin1 t).
      { apply (shape_rmargin1_app_r [(o,1%N,c)] t).
        cbn [app]. exact HR. }
      destruct (2 <=? c)%N.
      { destruct (2 <=? o)%N; [|discriminate].
        injection HRun as <- <-. destruct (2 <? c)%N.
        - change (shape_rmargin1
            ([(o,1%N,1%N); ((o-1)%N,1%N,1%N);
              (o,1%N,(c-2)%N)] ++ t)).
          apply shape_rmargin1_lits_app;
            [unfold shape_free; shape_lits_probe|exact HRt].
        - change (shape_rmargin1
            ([(o,1%N,1%N); ((o-1)%N,1%N,1%N)] ++ t)).
          apply shape_rmargin1_lits_app;
            [unfold shape_free; shape_lits_probe|exact HRt]. }
      destruct (negb (c =? 1) || negb (2 <=? o))%N;
        [discriminate|].
      destruct t as [|[[B zb] cb] t2].
      { destruct (2 <=? f)%N.
        - injection HRun as <- <-. apply shape_rmargin1_shape_free.
          unfold shape_free. shape_lits_probe.
        - destruct (f =? 1)%N; [|discriminate].
          injection HRun as <- <-. apply shape_rmargin1_shape_free.
          unfold shape_free. shape_lits_probe. }
      assert (HRt2 : shape_rmargin1 t2).
      { apply (shape_rmargin1_app_r
          [(o,1%N,c); (B,zb,cb)] t2).
        cbn [app]. exact HR. }
      match type of HRun with
      | (if ?X then _ else _) = _ => destruct X eqn:EG
      end.
      { match type of HRun with
        | (if ?X then _ else _) = _ => destruct X eqn:E5
        end.
        - destruct t2 as [|[[o2 z2] c2] t3]; [discriminate|].
          injection HRun as <- <-.
          apply andb_prop in E5 as [E5a E5b].
          apply andb_prop in E5a as [EB5 Ecb1].
          apply N.eqb_eq in EB5, Ecb1. subst B cb.
          apply andb_prop in E5b as [Eo2 Ez2].
          apply N.eqb_eq in Eo2, Ez2. subst o2 z2.
          change (shape_rmargin1
            ([(o,1%N,1%N); (4%N,2%N,c2+1)%N] ++ t3)).
          apply shape_rmargin1_lits_app.
          + unfold shape_free. shape_lits_probe.
          + apply (shape_rmargin1_app_r [(4%N,2%N,c2)] t3).
            exact HRt2.
        - destruct (B =? 1)%N.
          + destruct (cb =? 1)%N; [|discriminate].
            injection HRun as <- <-.
            change (shape_rmargin1 ([(o,3%N,1%N)] ++ t2)).
            apply shape_rmargin1_lits_app;
              [unfold shape_free; shape_lits_probe|exact HRt2].
          + destruct ((cb =? 1) && (2 <=? B))%N; [|discriminate].
            injection HRun as <- <-.
            change (shape_rmargin1
              ([(o,1%N,1%N); ((B-1)%N,zb,1%N)] ++ t2)).
            apply shape_rmargin1_lits_app;
              [unfold shape_free; shape_lits_probe|exact HRt2]. }
      destruct ((B =? 8) && (zb =? 2) && (cb =? 1))%N.
      { injection HRun as <- <-.
        change (shape_rmargin1
          ([(o,1%N,1%N); (7%N,2%N,1%N)] ++ t2)).
        apply shape_rmargin1_lits_app;
          [unfold shape_free; shape_lits_probe|exact HRt2]. }
      destruct ((B =? 4) && (zb =? 2))%N eqn:E4.
      { apply andb_prop in E4 as [EB Ez].
        apply N.eqb_eq in EB, Ez. subst B zb.
        destruct (cb =? 1)%N.
        - injection HRun as <- <-.
          change (shape_rmargin1
            ([(o,1%N,1%N); (3%N,2%N,1%N)] ++ t2)).
          apply shape_rmargin1_lits_app;
            [unfold shape_free; shape_lits_probe|exact HRt2].
        - destruct (2 <=? cb)%N; [|discriminate].
          injection HRun as <- <-.
          change (shape_rmargin1
            ([(o,1%N,1%N); (3%N,2%N,1%N);
              (4%N,2%N,(cb-1)%N)] ++ t2)).
          apply shape_rmargin1_lits_app;
            [unfold shape_free; shape_lits_probe|exact HRt2]. }
      destruct (zb =? 1)%N eqn:Ezb.
      { apply N.eqb_eq in Ezb. subst zb.
        destruct (2 <=? cb)%N.
        - destruct (2 <=? B)%N; [|discriminate].
          injection HRun as <- <-.
          change (shape_rmargin1
            ([(o,1%N,1%N); ((B-1)%N,1%N,1%N);
              (B,1%N,(cb-1)%N)] ++ t2)).
          apply shape_rmargin1_lits_app;
            [unfold shape_free; shape_lits_probe|exact HRt2].
        - destruct (B =? 1)%N.
          + destruct (cb =? 1)%N; [|discriminate].
            injection HRun as <- <-.
            change (shape_rmargin1 ([(o,2%N,1%N)] ++ t2)).
            apply shape_rmargin1_lits_app;
              [unfold shape_free; shape_lits_probe|exact HRt2].
          + destruct ((cb =? 1) && (2 <=? B))%N; [|discriminate].
            injection HRun as <- <-.
            change (shape_rmargin1
              ([(o,1%N,1%N); ((B-1)%N,1%N,cb)] ++ t2)).
            apply shape_rmargin1_lits_app;
              [unfold shape_free; shape_lits_probe|exact HRt2]. }
      destruct ((3 <=? zb) && (cb =? 1))%N eqn:E3z;
        [|discriminate].
      apply andb_prop in E3z as [Ezb3 Ecb].
      apply N.eqb_eq in Ecb. subst cb.
      destruct (B =? 1)%N.
      { injection HRun as <- <-.
        change (shape_rmargin1 ([(o,(zb+1)%N,1%N)] ++ t2)).
        apply shape_rmargin1_lits_app;
          [unfold shape_free; shape_lits_probe|exact HRt2]. }
      destruct (2 <=? B)%N; [|discriminate].
      injection HRun as <- <-.
      change (shape_rmargin1
        ([(o,1%N,1%N); ((B-1)%N,zb,1%N)] ++ t2)).
      apply shape_rmargin1_lits_app;
        [unfold shape_free; shape_lits_probe|exact HRt2]. }
  - destruct zp as [zp'|zp'|]; cbn [leaf_act] in HRun;
      try discriminate.
    destruct c as [|[cp|cp|]]; cbn [leaf_act] in HRun;
      try discriminate.
    destruct ((5 <=? o) && negb (o =? 8) && negb (o =? 12))%N;
      [|discriminate].
    assert (HRt : shape_rmargin1 t).
    { apply (shape_rmargin1_app_r [(o,2%N,1%N)] t).
      cbn [app]. exact HR. }
    destruct t as [|[[on zn] cn] t2].
    + destruct (f =? 3)%N; cbv beta iota in HRun.
      * injection HRun as <- <-. apply shape_rmargin1_shape_free.
        unfold shape_free. shape_lits_probe.
      * destruct (f =? 2)%N; cbv beta iota in HRun.
        -- injection HRun as <- <-. apply shape_rmargin1_shape_free.
           unfold shape_free. shape_lits_probe.
        -- destruct (f =? 4)%N; cbv beta iota in HRun;
             [injection HRun as <- <-|discriminate].
           apply shape_rmargin1_shape_free.
           unfold shape_free. shape_lits_probe.
    + destruct (on =? 1)%N; [discriminate|].
      destruct ((on =? 3) && (zn =? 2) && (cn =? 1) && (f =? 4))%N
        eqn:E3.
      * destruct t2 as [|[[o2 z2] c2] t3].
        -- injection HRun as <- <-. apply shape_rmargin1_shape_free.
           unfold shape_free. shape_lits_probe.
        -- destruct t3 as [|g3 t4]; [|discriminate].
           destruct ((o2 =? 4) && (z2 =? 2))%N; [|discriminate].
           injection HRun as <- <-. apply shape_rmargin1_shape_free.
           unfold shape_free. shape_lits_probe.
      * destruct ((on =? 4) && (zn =? 2))%N eqn:E4.
        -- apply andb_prop in E4 as [Eon Ezn].
           apply N.eqb_eq in Eon, Ezn. subst on zn.
           destruct t2 as [|[[o2 z2] c2] t3].
           ++ destruct (f =? 4)%N; [|discriminate].
              injection HRun as <- <-. apply shape_rmargin1_shape_free.
              unfold shape_free. shape_lits_probe.
           ++ destruct t3 as [|[[o3 z3] c3] t4]; [discriminate|].
              destruct t4 as [|g4 t5]; [|discriminate].
              lazymatch type of HRun with
              | (if ?b then _ else _) = _ => destruct b eqn:EOr in HRun
              end; [|discriminate].
              apply andb_prop in EOr as [EOr _].
              apply andb_prop in EOr as [EOr Ez3].
              apply andb_prop in EOr as [EOr Eo3].
              apply andb_prop in EOr as [EOr Ec2].
              apply andb_prop in EOr as [EOr Ez2].
              apply andb_prop in EOr as [_ Eo2].
              apply N.eqb_eq in Eo2, Ez2, Ec2, Eo3, Ez3.
              subst o2 z2 c2 o3 z3.
              injection HRun as <- <-. apply shape_rmargin1_shape_free.
              unfold shape_free. destruct (cn =? 1)%N; shape_lits_probe.
        -- lazymatch type of HRun with
           | (if ?b then _ else _) = _ => destruct b eqn:EX6 in HRun
           end.
           ++ destruct t2 as [|[[o2 z2] c2] t3]; [discriminate|].
              destruct t3 as [|g3 t4]; [|discriminate].
              apply andb_prop in EX6 as [EX6 EM].
              apply andb_prop in EX6 as [EX6 _].
              apply andb_prop in EX6 as [EX6 Ecn].
              apply andb_prop in EX6 as [EX6 Ezn].
              apply andb_prop in EX6 as [_ Eon].
              apply N.eqb_eq in Eon, Ezn, Ecn. subst on zn cn.
              apply andb_prop in EM as [Eo Ez].
              apply N.eqb_eq in Eo, Ez. subst o2 z2.
              injection HRun as <- <-. apply shape_rmargin1_shape_free.
              unfold shape_free. shape_lits_probe.
           ++ lazymatch type of HRun with
              | (if ?b then _ else _) = _ => destruct b in HRun
              end; [|discriminate].
              lazymatch type of HRun with
              | context [leaf_act ?w ?ff] =>
                  destruct (leaf_act w ff) as [[s' f']|] eqn:ERC
              end; [|discriminate].
              cbv beta iota in HRun. injection HRun as <- <-.
              change (shape_rmargin1 ([(o,2%N,1%N)] ++ s')).
              apply shape_rmargin1_lits_app.
              ** unfold shape_free. shape_lits_probe.
              ** exact (IH f s' f' HRt ERC).
Qed.
Definition shape_rmargin (n : nat) (w : word) : Prop :=
  forall p g, nth_error w p = Some g -> phshape g = true ->
    (p + n < length w)%nat /\
    (forall q, (p < q)%nat -> (q <= p + n)%nat ->
       exists gr, nth_error w q = Some gr /\
                  casc gr = true /\ phshape gr = false).
Lemma shape_rmargin_weaken : forall n m w,
  (m <= n)%nat -> shape_rmargin n w -> shape_rmargin m w.
Proof.
  intros n m w Hmn H p g Hp HS.
  destruct (H p g Hp HS) as (Hend & Hwin). split; [lia|].
  intros q Hq1 Hq2. apply Hwin; lia.
Qed.
Lemma shape_rmargin_to1 : forall w,
  shape_rmargin 1 w -> shape_rmargin1 w.
Proof.
  intros w H p g Hp HS.
  destruct (H p g Hp HS) as (_ & Hwin).
  exact (Hwin (p+1)%nat ltac:(lia) ltac:(lia)).
Qed.
Lemma margins_shape_rmargin3_probe : forall sg w,
  ph_margins sg w ->
  lin_ptags sg w = true -> shape_rmargin 3 w.
Proof.
  intros sg w HM HT p g Hp HS.
  assert (Hph : ph sg g = true)
    by (exact (lin_ptags_nth_shape_probe sg w p g HT Hp HS)).
  destruct (HM p g Hp Hph) as (_ & Hend & Hwin). split.
  - exact Hend.
  - intros q Hq1 Hq2.
    destruct (Hwin q ltac:(unfold GUARD; lia)
                 ltac:(unfold GUARD; lia) ltac:(lia))
      as (gr & Hgr & HC & Hnph).
    exists gr. split; [exact Hgr|]. split; [exact HC|].
    destruct (phshape gr) eqn:HSr; [|reflexivity].
    pose proof (lin_ptags_nth_shape_probe sg w q gr HT Hgr HSr) as Hphr.
    congruence.
Qed.
Lemma shape_rmargin_app_r : forall n a b,
  shape_rmargin n (a ++ b) -> shape_rmargin n b.
Proof.
  intros n a b H p g Hp HS.
  assert (Hp' : nth_error (a ++ b) (length a + p) = Some g).
  { rewrite nth_error_app2 by lia.
    replace (length a + p - length a)%nat with p by lia. exact Hp. }
  destruct (H _ _ Hp' HS) as (Hend & Hwin). split.
  - rewrite length_app in Hend. lia.
  - intros q Hq1 Hq2.
    destruct (Hwin (length a + q)%nat ltac:(lia) ltac:(lia))
      as (gr & Hgr & HC & HPh).
    exists gr. split.
    + rewrite nth_error_app2 in Hgr by lia.
      replace (length a + q - length a)%nat with q in Hgr by lia.
      exact Hgr.
    + auto.
Qed.
Lemma shape_rmargin_prefix_noncasc : forall n a g t,
  shape_rmargin n (a ++ g :: t) -> casc g = false ->
  shape_rmargin n a.
Proof.
  intros n a g t H HC p gp Hp HS.
  assert (Hpa : (p < length a)%nat)
    by (apply nth_error_Some; rewrite Hp; discriminate).
  assert (Hp' : nth_error (a ++ g :: t) p = Some gp)
    by (rewrite nth_error_app1 by exact Hpa; exact Hp).
  destruct (H p gp Hp' HS) as (Hend & Hwin).
  assert (Henda : (p + n < length a)%nat).
  { destruct (PeanoNat.Nat.lt_ge_cases (p+n) (length a));
      [assumption|].
    assert (Hq1 : (p < length a)%nat) by exact Hpa.
    assert (Hq2 : (length a <= p+n)%nat) by lia.
    destruct (Hwin (length a) Hq1 Hq2) as (gr & Hgr & HCgr & _).
    rewrite nth_error_app2 in Hgr by lia.
    rewrite PeanoNat.Nat.sub_diag in Hgr.
    cbn [nth_error] in Hgr. injection Hgr as <-. congruence. }
  split; [exact Henda|]. intros q Hq1 Hq2.
  destruct (Hwin q Hq1 Hq2) as (gr & Hgr & HCgr & HPh).
  exists gr. split.
  - rewrite nth_error_app1 in Hgr by lia. exact Hgr.
  - auto.
Qed.
Lemma seek_fst_rmargin : forall n w cols s,
  seek w = (cols, s) -> shape_rmargin n w -> shape_rmargin n cols.
Proof.
  intros n w cols s ES HR.
  pose proof (LineageGuard_seek_split w) as HSP.
  rewrite ES in HSP. cbn [fst snd] in HSP.
  destruct s as [|g t].
  - rewrite HSP in HR. rewrite app_nil_r in HR. exact HR.
  - apply (shape_rmargin_prefix_noncasc n cols g t).
    + rewrite <- HSP. exact HR.
    + exact (seektest_noncasc g
        (seek_snd_head w g t
          ltac:(rewrite ES; reflexivity))).
Qed.
Lemma seek_snd_rmargin : forall n w cols s,
  seek w = (cols, s) -> shape_rmargin n w -> shape_rmargin n s.
Proof.
  intros n w cols s ES HR.
  pose proof (LineageGuard_seek_split w) as HSP.
  rewrite ES in HSP. cbn [fst snd] in HSP.
  apply (shape_rmargin_app_r n cols s). rewrite <- HSP. exact HR.
Qed.
Lemma shape_rmargin1_phfree_suffix : forall a b,
  shape_rmargin1 a -> shape_free b -> shape_rmargin1 (a ++ b).
Proof.
  intros a b HA HB. apply shape_rmargin1_app; [exact HA|].
  exact (shape_rmargin1_shape_free b HB).
Qed.
Lemma shape_rmargin3_last2_pack : forall ini a b,
  shape_rmargin 3 (ini ++ [a; b]) ->
  shape_rmargin1 ini /\
  phshape a = false /\ phshape b = false.
Proof.
  intros ini a b H. split.
  - intros p g Hp HS.
    assert (HpL : (p < length ini)%nat)
      by (apply nth_error_Some; rewrite Hp; discriminate).
    assert (Hp' : nth_error (ini ++ [a;b]) p = Some g)
      by (rewrite nth_error_app1 by exact HpL; exact Hp).
    destruct (H p g Hp' HS) as (Hend & Hwin).
    assert (Hnext : (p+1 < length ini)%nat).
    { rewrite length_app in Hend. cbn [length] in Hend. lia. }
    destruct (Hwin (p+1)%nat ltac:(lia) ltac:(lia))
      as (gr & Hgr & HC & HPh).
    exists gr. split.
    + rewrite nth_error_app1 in Hgr by exact Hnext. exact Hgr.
    + auto.
  - split.
    + destruct (phshape a) eqn:HS; [|reflexivity].
      assert (Ha : nth_error (ini ++ [a;b]) (length ini) = Some a).
      { rewrite nth_error_app2 by lia. rewrite PeanoNat.Nat.sub_diag.
        reflexivity. }
      destruct (H _ _ Ha HS) as (Hend & _).
      rewrite length_app in Hend. cbn [length] in Hend. lia.
    + destruct (phshape b) eqn:HS; [|reflexivity].
      assert (Hb : nth_error (ini ++ [a;b]) (length ini + 1) = Some b).
      { rewrite nth_error_app2 by lia.
        replace (length ini + 1 - length ini)%nat with 1%nat by lia.
        reflexivity. }
      destruct (H _ _ Hb HS) as (Hend & _).
      rewrite length_app in Hend. cbn [length] in Hend. lia.
Qed.
Ltac shape_lits_with_probe Hfree :=
  intros g Hin;
  repeat (destruct Hin as [<-|Hin]); try (destruct Hin);
  first
    [ exact Hfree
    | apply phshape_c1
    | apply phshape_c0
    | apply phshape_znot2; reflexivity
    | apply phshape_onot9; reflexivity
    | reflexivity ].
Lemma lawR_seg_rmargin_probe : forall cols B body,
  shape_rmargin 3 cols -> lawR_seg cols B = Some body ->
  shape_rmargin1 body.
Proof.
  intros cols B body HR H. unfold lawR_seg in H.
  split_last2_margin H cols.
  destruct (shape_rmargin3_last2_pack ini (ga,gaz,gac) (gb,gbz,gbc) HR)
    as (Hini & Hga & Hgb).
  destruct ((ga =? 8) && (gaz =? 2) && (gac =? 1)
    && (gb =? 4) && (gbz =? 2) && (1 <=? gbc))%N eqn:E1.
  - injection H as <-. apply shape_rmargin1_phfree_suffix;
      [exact Hini|].
    unfold shape_free. destruct (1 <? B)%N; shape_lits_probe.
  - destruct ((gb =? 8) && (gbz =? 2) && (gbc =? 1))%N;
      [|discriminate].
    injection H as <-. apply shape_rmargin1_phfree_suffix;
      [exact Hini|].
    unfold shape_free. destruct (1 <? B)%N; shape_lits_with_probe Hga.
Qed.
Lemma endR_seg_rmargin_probe : forall cols f body,
  shape_rmargin 3 cols -> endR_seg cols f = Some body ->
  shape_rmargin1 body.
Proof.
  intros cols f body HR H. unfold endR_seg in H.
  split_last2_margin H cols.
  destruct (shape_rmargin3_last2_pack ini (ga,gaz,gac) (gb,gbz,gbc) HR)
    as (Hini & Hga & Hgb).
  destruct ((ga =? 8) && (gaz =? 2) && (gac =? 1)
    && (gb =? 4) && (gbz =? 2) && (1 <=? gbc) && (2 <=? f))%N.
  - injection H as <-. apply shape_rmargin1_phfree_suffix;
      [exact Hini|].
    unfold shape_free. shape_lits_probe.
  - destruct ((gb =? 8) && (gbz =? 2) && (gbc =? 1)
              && (2 <=? f))%N; [|discriminate].
    injection H as <-. apply shape_rmargin1_phfree_suffix;
      [exact Hini|].
    unfold shape_free. shape_lits_with_probe Hga.
Qed.
Lemma endY_seg_rmargin_probe : forall cols y body,
  shape_rmargin 3 cols -> endY_seg cols y = Some body ->
  shape_rmargin1 body.
Proof.
  intros cols y body HR H. unfold endY_seg in H.
  split_last2_margin H cols.
  destruct (shape_rmargin3_last2_pack ini (ga,gaz,gac) (gb,gbz,gbc) HR)
    as (Hini & Hga & Hgb).
  destruct ((ga =? 8) && (gaz =? 2) && (gac =? 1)
    && (gb =? 4) && (gbz =? 2) && (1 <=? gbc))%N.
  - injection H as <-. apply shape_rmargin1_phfree_suffix;
      [exact Hini|].
    unfold shape_free. shape_lits_probe.
  - destruct ((gb =? 8) && (gbz =? 2) && (gbc =? 1))%N;
      [|discriminate].
    injection H as <-. apply shape_rmargin1_phfree_suffix;
      [exact Hini|].
    unfold shape_free. shape_lits_with_probe Hga.
Qed.
Lemma jump_seg_rmargin_probe : forall cols B body,
  shape_rmargin 3 cols -> jump_seg cols B = Some body ->
  shape_rmargin1 body.
Proof.
  intros cols B body HR H. unfold jump_seg in H.
  split_last2_margin H cols.
  destruct (shape_rmargin3_last2_pack ini (ga,gaz,gac) (gb,gbz,gbc) HR)
    as (Hini & Hga & Hgb).
  destruct ((ga =? 8) && (gaz =? 2) && (gac =? 1)
    && (gb =? 4) && (gbz =? 2) && (1 <=? gbc))%N.
  - injection H as <-. apply shape_rmargin1_phfree_suffix;
      [exact Hini|].
    unfold shape_free. destruct (1 <? B)%N; shape_lits_probe.
  - destruct ((gb =? 8) && (gbz =? 2) && (gbc =? 1))%N;
      [|discriminate].
    injection H as <-. apply shape_rmargin1_phfree_suffix;
      [exact Hini|].
    unfold shape_free. destruct (1 <? B)%N; shape_lits_with_probe Hga.
Qed.
Definition tag_z1canon (w : word) : Prop :=
  forall p g g1,
    nth_error w p = Some g -> phshape g = true ->
    nth_error w (p+1) = Some g1 -> gZ g1 = 1%N ->
    g1 = (7%N,1%N,1%N) /\
    nth_error w (p+2) = Some (3%N,2%N,1%N).
Lemma tag_z1canon_of_rmargin1 : forall w,
  shape_rmargin1 w -> tag_z1canon w.
Proof.
  intros w HR p g g1 Hp HS H1 Hz.
  destruct (HR p g Hp HS) as (gr & Hgr & HC & _).
  rewrite H1 in Hgr. injection Hgr as <-.
  destruct g1 as [[o z] c]. cbn [gZ] in Hz. subst z.
  rewrite casc_z1_false in HC. discriminate.
Qed.
Lemma tag_z1canon_app_r : forall a b,
  tag_z1canon (a ++ b) -> tag_z1canon b.
Proof.
  intros a b H p g g1 Hp HS H1 Hz.
  assert (Hp' : nth_error (a++b) (length a+p) = Some g).
  { rewrite nth_error_app2 by lia.
    replace (length a+p-length a)%nat with p by lia. exact Hp. }
  assert (H1' : nth_error (a++b) (length a+p+1) = Some g1).
  { rewrite nth_error_app2 by lia.
    replace (length a+p+1-length a)%nat with (p+1)%nat by lia. exact H1. }
  destruct (H _ _ _ Hp' HS H1' Hz) as (-> & H2).
  split; [reflexivity|].
  rewrite nth_error_app2 in H2 by lia.
  replace (length a+p+2-length a)%nat with (p+2)%nat in H2 by lia.
  exact H2.
Qed.
Lemma tag_z1canon_canonical_suffix : forall pre body tail,
  shape_rmargin 3 (pre ++ body) -> shape_free tail ->
  tag_z1canon (pre ++ (7%N,1%N,1%N) :: (3%N,2%N,1%N) :: tail).
Proof.
  intros pre body tail HR HF p g g1 Hp HS H1 Hz.
  assert (HFall : shape_free
      ((7%N,1%N,1%N) :: (3%N,2%N,1%N) :: tail)).
  { unfold shape_free. intros x Hx.
    destruct Hx as [<-|[<-|Hx]]; [apply phshape_c1|
      apply phshape_c1|exact (HF x Hx)]. }
  destruct (PeanoNat.Nat.lt_ge_cases p (length pre)) as [Hpp|Hpp].
  - rewrite nth_error_app1 in Hp by exact Hpp.
    assert (HpSrc : nth_error (pre++body) p = Some g)
      by (rewrite nth_error_app1 by exact Hpp; exact Hp).
    destruct (HR p g HpSrc HS) as (_ & Hwin).
    destruct (PeanoNat.Nat.lt_ge_cases (p+1) (length pre))
      as [Hin|Hbd].
    + rewrite nth_error_app1 in H1 by exact Hin.
      destruct (Hwin (p+1)%nat ltac:(lia) ltac:(lia))
        as (gr & Hgr & HC & _).
      rewrite nth_error_app1 in Hgr by exact Hin.
      rewrite H1 in Hgr. injection Hgr as <-.
      destruct g1 as [[o z] c]. cbn [gZ] in Hz. subst z.
      rewrite casc_z1_false in HC. discriminate.
    + assert (Ebd : (p+1 = length pre)%nat) by lia.
      rewrite nth_error_app2 in H1 by lia.
      rewrite Ebd, PeanoNat.Nat.sub_diag in H1.
      cbn [nth_error] in H1. injection H1 as <-.
      split; [reflexivity|].
      rewrite nth_error_app2 by lia.
      replace (p+2-length pre)%nat with 1%nat by lia. reflexivity.
  - rewrite nth_error_app2 in Hp by exact Hpp.
    assert (HG : phshape g = false).
    { apply HFall. apply nth_error_In with (n := (p-length pre)%nat).
      exact Hp. }
    rewrite HG in HS. discriminate.
Qed.
Lemma dtb4_conv_canon_ctx_probe : forall body pre body',
  shape_rmargin 3 (pre ++ body) ->
  dtb4_conv body = Some body' -> tag_z1canon (pre ++ body').
Proof.
  intros body. induction body as [|[[o z] c] t IH];
    intros pre body' HR H; [discriminate|].
  cbn [dtb4_conv] in H.
  destruct (dtb4_conv t) as [t'|] eqn:ED.
  - injection H as <-.
    specialize (IH (pre ++ [(o,z,c)]) t').
    repeat rewrite <- app_assoc in IH. cbn [app] in IH.
    exact (IH HR eq_refl).
  - lazymatch type of H with
    | (if ?b then _ else _) = _ => destruct b eqn:E8 in H
    end; [|discriminate].
    cbn [gO gZ gC] in E8.
    apply andb_prop in E8 as [E8 Ec].
    apply andb_prop in E8 as [Eo Ez].
    apply N.eqb_eq in Eo, Ez, Ec. subst o z c.
    lazymatch type of H with
    | (if ?b then _ else _) = _ => destruct b eqn:EW in H
    end.
    + injection H as <-.
      apply tag_z1canon_canonical_suffix with
        (body := (8%N,2%N,1%N)::t).
      * exact HR.
      * exact (shape_free_w42_probe t EW).
    + destruct t as [|[[o1 z1] c1] [|[[o2 z2] c2] t2]];
        try discriminate.
      lazymatch type of H with
      | (if ?b then _ else _) = _ => destruct b eqn:EOr in H
      end; [|discriminate].
      apply andb_prop in EOr as [EOr Ec2].
      apply andb_prop in EOr as [EOr Ez2].
      apply andb_prop in EOr as [EOr Eo2].
      apply andb_prop in EOr as [EOr _].
      apply andb_prop in EOr as [Eo1 Ez1].
      apply N.eqb_eq in Eo1, Ez1, Eo2, Ez2, Ec2.
      rewrite Eo1, Ez1, Eo2, Ez2, Ec2 in *.
      destruct t2 as [|[[o3 z3] c3] [|g4 t4]]; try discriminate.
      * injection H as <-.
        apply tag_z1canon_canonical_suffix with
          (body := [(8%N,2%N,1%N);(4%N,2%N,c1);(3%N,2%N,1%N)]).
        -- exact HR.
        -- unfold shape_free. destruct (1 <? c1)%N; shape_lits_probe.
      * lazymatch type of H with
        | (if ?b then _ else _) = _ => destruct b eqn:E3 in H
        end; [|discriminate].
        apply andb_prop in E3 as [Eo3 Ez3].
        apply N.eqb_eq in Eo3, Ez3. rewrite Eo3, Ez3 in *.
        injection H as <-.
        apply tag_z1canon_canonical_suffix with
          (body := [(8%N,2%N,1%N);(4%N,2%N,c1);
                    (3%N,2%N,1%N);(4%N,2%N,c3)]).
        -- exact HR.
        -- unfold shape_free. destruct (1 <? c1)%N; shape_lits_probe.
Qed.
Lemma dtb3_conv_canon_ctx_probe : forall body pre body',
  shape_rmargin 3 (pre ++ body) ->
  dtb3_conv body = Some body' -> tag_z1canon (pre ++ body').
Proof.
  intros body. induction body as [|[[o z] c] t IH];
    intros pre body' HR H; [discriminate|].
  cbn [dtb3_conv] in H.
  destruct (dtb3_conv t) as [t'|] eqn:ED.
  - injection H as <-.
    specialize (IH (pre ++ [(o,z,c)]) t').
    repeat rewrite <- app_assoc in IH. cbn [app] in IH.
    exact (IH HR eq_refl).
  - lazymatch type of H with
    | (if ?b then _ else _) = _ => destruct b eqn:E8 in H
    end; [|discriminate].
    cbn [gO gZ gC] in E8.
    apply andb_prop in E8 as [E8 Ec].
    apply andb_prop in E8 as [Eo Ez].
    apply N.eqb_eq in Eo, Ez, Ec. subst o z c.
    destruct t as [|[[o1 z1] c1] t1]; [discriminate|].
    lazymatch type of H with
    | (if ?b then _ else _) = _ => destruct b eqn:E1 in H
    end; [|discriminate].
    apply andb_prop in E1 as [E1 EW].
    apply andb_prop in E1 as [E1 _].
    apply andb_prop in E1 as [Eo1 Ez1].
    apply N.eqb_eq in Eo1, Ez1. rewrite Eo1, Ez1 in *.
    injection H as <-.
    apply tag_z1canon_canonical_suffix with
      (body := (8%N,2%N,1%N)::(4%N,2%N,c1)::t1).
    + exact HR.
    + unfold shape_free. intros g Hg.
      destruct Hg as [<-|Hg]; [apply phshape_onot9;
        reflexivity|].
      exact (shape_free_w42_probe t1 EW g Hg).
Qed.
Corollary dtb4_conv_canon_probe : forall body body',
  shape_rmargin 3 body -> dtb4_conv body = Some body' ->
  tag_z1canon body'.
Proof.
  intros body body' HR H.
  exact (dtb4_conv_canon_ctx_probe body [] body' HR H).
Qed.
Corollary dtb3_conv_canon_probe : forall body body',
  shape_rmargin 3 body -> dtb3_conv body = Some body' ->
  tag_z1canon body'.
Proof.
  intros body body' HR H.
  exact (dtb3_conv_canon_ctx_probe body [] body' HR H).
Qed.
Lemma tag_z1canon_shape_free : forall w,
  shape_free w -> tag_z1canon w.
Proof.
  intros w HF p g g1 Hp HS.
  rewrite (HF g (nth_error_In w p Hp)) in HS. discriminate.
Qed.
Lemma tag_z1canon_lits_app : forall a b,
  shape_free a -> tag_z1canon b -> tag_z1canon (a ++ b).
Proof.
  intros a b HA HB p g g1 Hp HS H1 Hz.
  destruct (PeanoNat.Nat.lt_ge_cases p (length a)) as [Hpa|Hpa].
  - rewrite nth_error_app1 in Hp by exact Hpa.
    rewrite (HA g (nth_error_In a p Hp)) in HS. discriminate.
  - rewrite nth_error_app2 in Hp by exact Hpa.
    assert (H1b : nth_error b ((p-length a)+1)%nat = Some g1).
    { rewrite nth_error_app2 in H1 by lia.
      replace (p+1-length a)%nat with ((p-length a)+1)%nat in H1 by lia.
      exact H1. }
    destruct (HB (p-length a)%nat g g1 Hp HS H1b Hz) as (-> & H2).
    split; [reflexivity|].
    rewrite nth_error_app2 by lia.
    replace (p+2-length a)%nat with ((p-length a)+2)%nat by lia.
    exact H2.
Qed.
Lemma tag_z1canon_app_left_rmargin1 : forall a b,
  shape_rmargin1 a -> tag_z1canon b -> tag_z1canon (a ++ b).
Proof.
  intros a b HA HB p g g1 Hp HS H1 Hz.
  destruct (PeanoNat.Nat.lt_ge_cases p (length a)) as [Hpa|Hpa].
  - rewrite nth_error_app1 in Hp by exact Hpa.
    destruct (HA p g Hp HS) as (gr & Hgr & HC & _).
    assert (Hnext : (p+1 < length a)%nat)
      by (apply nth_error_Some; rewrite Hgr; discriminate).
    rewrite nth_error_app1 in H1 by exact Hnext.
    rewrite H1 in Hgr. injection Hgr as <-.
    destruct g1 as [[o z] c]. cbn [gZ] in Hz. subst z.
    rewrite casc_z1_false in HC. discriminate.
  - rewrite nth_error_app2 in Hp by exact Hpa.
    assert (H1b : nth_error b ((p-length a)+1)%nat = Some g1).
    { rewrite nth_error_app2 in H1 by lia.
      replace (p+1-length a)%nat with ((p-length a)+1)%nat in H1 by lia.
      exact H1. }
    destruct (HB (p-length a)%nat g g1 Hp HS H1b Hz) as (-> & H2).
    split; [reflexivity|]. rewrite nth_error_app2 by lia.
    replace (p+2-length a)%nat with ((p-length a)+2)%nat by lia.
    exact H2.
Qed.
Lemma tag_z1canon_frame : forall pin pout t,
  shape_rmargin 3 (pin ++ t) -> shape_free pout ->
  tag_z1canon (pout ++ t).
Proof.
  intros pin pout t HR HF. apply tag_z1canon_lits_app; [exact HF|].
  apply tag_z1canon_of_rmargin1. apply shape_rmargin_to1.
  apply (shape_rmargin_weaken 3 1 t ltac:(lia)).
  exact (shape_rmargin_app_r 3 pin t HR).
Qed.
Definition fire_canon (n : nat) : Prop :=
  forall s f w2 f2,
    shape_rmargin 3 s ->
    fire_comp n s f = Some (w2, f2) -> tag_z1canon w2.
Definition renew_canon (n : nat) : Prop :=
  forall cols s f body f2,
    shape_rmargin 3 (cols ++ s) ->
    renew_seg n cols s f = Some (body, f2) -> tag_z1canon body.
Lemma renew_canon_step : forall n,
  fire_canon n -> renew_canon n -> renew_canon (S n).
Proof.
  intros n IHf IHr. unfold fire_canon in IHf.
  unfold renew_canon in IHr |- *.
  intros cols s f body f2 HR HRun.
  cbn [renew_seg] in HRun.
  destruct s as [|[[o0 z0] c_0] rest]; [discriminate|].
  destruct o0 as [|o1]; try discriminate.
  destruct o1 as [o1|o1|]; try discriminate.
  destruct o1 as [o1|o1|]; try discriminate.
  destruct o1 as [o1|o1|]; try discriminate.
  destruct z0 as [|z1]; try discriminate.
  destruct z1 as [z1|z1|]; try discriminate.
  destruct z1 as [z1|z1|]; try discriminate.
  destruct c_0 as [|c1]; try discriminate.
  destruct c1 as [c1|c1|]; try discriminate.
  assert (HRcols : shape_rmargin 3 cols).
  { apply (shape_rmargin_prefix_noncasc 3 cols (4%N,3%N,1%N) rest).
    - exact HR.
    - exact (z31_noncasc 4%N). }
  destruct rest as [|[[o5 z5] B] rest2].
  { destruct (endR_seg cols f) as [body0|] eqn:EER;
      [|discriminate].
    injection HRun as <- <-.
    apply tag_z1canon_of_rmargin1.
    exact (endR_seg_rmargin_probe cols f body0 HRcols EER). }
  destruct ((o5 =? 4) && (z5 =? 2) && (1 <=? B))%N eqn:E52.
  2:{ destruct ((z5 =? 3) && (B =? 1)
                && match rest2 with [] => true | _ :: _ => false end
                && (f =? 4) && (1 <=? o5))%N eqn:EREN;
        [|discriminate].
      split6 EREN.
      destruct rest2 as [|g2 r2]; try discriminate.
      cbv beta iota in HRun.
      destruct (endY_seg cols o5) as [body0|] eqn:EEY;
        [|discriminate].
      injection HRun as <- <-.
      apply tag_z1canon_of_rmargin1.
      exact (endY_seg_rmargin_probe cols o5 body0 HRcols EEY). }
  cbv beta iota in HRun.
  apply andb_prop in E52 as [E52 _].
  apply andb_prop in E52 as [Eo5 Ez5].
  apply N.eqb_eq in Eo5, Ez5. subst o5 z5.
  destruct rest2 as [|gr2 rest2t].
  { destruct (f =? 4)%N.
    - destruct (lawR_seg cols B) as [body0|] eqn:ELR;
        [|discriminate].
      injection HRun as <- <-. apply tag_z1canon_of_rmargin1.
      exact (lawR_seg_rmargin_probe cols B body0 HRcols ELR).
    - destruct (5 <=? f)%N; [|discriminate].
      destruct (jump_seg cols B) as [seg|] eqn:EJP;
        [|discriminate].
      injection HRun as <- <-. apply tag_z1canon_of_rmargin1.
      apply shape_rmargin1_phfree_suffix.
      + exact (jump_seg_rmargin_probe cols B seg HRcols EJP).
      + unfold shape_free. shape_lits_probe. }
  destruct (jump_seg cols B) as [seg|] eqn:EJS;
    [|discriminate].
  assert (HRseg : shape_rmargin1 seg)
    by (exact (jump_seg_rmargin_probe cols B seg HRcols EJS)).
  assert (HRrest : shape_rmargin 3 (gr2 :: rest2t)).
  { apply (shape_rmargin_app_r 3
      (cols ++ [(4%N,3%N,1%N); (4%N,2%N,B)]) (gr2::rest2t)).
    repeat rewrite <- app_assoc. cbn [app]. exact HR. }
  cbv beta iota in HRun.
  destruct (seek (gr2 :: rest2t)) as [cols2 s3] eqn:ESK2.
  assert (HRcols2 : shape_rmargin 3 cols2)
    by (exact (seek_fst_rmargin 3 (gr2::rest2t) cols2 s3 ESK2 HRrest)).
  assert (HRs3 : shape_rmargin 3 s3)
    by (exact (seek_snd_rmargin 3 (gr2::rest2t) cols2 s3 ESK2 HRrest)).
  match type of HRun with
  | context [renew_seg ?nn ?cc ?ss ?ff] =>
      destruct (renew_seg nn cc ss ff) as [[body0 f0]|] eqn:ERN2
  end.
  { cbv beta iota in HRun. injection HRun as <- <-.
    apply tag_z1canon_app_left_rmargin1; [exact HRseg|].
    apply (IHr cols2 s3 f body0 f0).
    - pose proof (LineageGuard_seek_split (gr2::rest2t)) as HSP.
      rewrite ESK2 in HSP. cbn [fst snd] in HSP.
      rewrite <- HSP. exact HRrest.
    - exact ERN2. }
  cbv beta iota in HRun.
  destruct s3 as [|[[o7 z7] c7] s3t].
  { cbn [leaf_act] in HRun. cbv beta iota in HRun.
    destruct (5 <=? f)%N.
    - injection HRun as <- <-.
      apply tag_z1canon_app_left_rmargin1; [exact HRseg|].
      apply tag_z1canon_of_rmargin1.
      apply shape_rmargin1_phfree_suffix.
      + apply shape_rmargin_to1.
        apply (shape_rmargin_weaken 3 1 cols2 ltac:(lia)). exact HRcols2.
      + unfold shape_free. shape_lits_probe.
    - destruct (f =? 4)%N; [|discriminate].
      match type of HRun with
      | context [dtb4_conv ?w] =>
          destruct (dtb4_conv w) as [cols2'|] eqn:EDC
      end.
      + cbv beta iota in HRun. injection HRun as <- <-.
        apply tag_z1canon_app_left_rmargin1; [exact HRseg|].
        exact (dtb4_conv_canon_probe cols2 cols2' HRcols2 EDC).
      + cbv beta iota in HRun.
        destruct (forallb w42 cols2); [|discriminate].
        destruct (lawR_seg cols B) as [seg2|] eqn:ELR2;
          [|discriminate].
        injection HRun as <- <-.
        apply tag_z1canon_app_left_rmargin1.
        * exact (lawR_seg_rmargin_probe cols B seg2 HRcols ELR2).
        * apply tag_z1canon_of_rmargin1. apply shape_rmargin_to1.
          apply (shape_rmargin_weaken 3 1 cols2 ltac:(lia)). exact HRcols2. }
  destruct ((z7 =? 3) && (c7 =? 1))%N eqn:E73.
  { cbv beta iota in HRun.
    match type of HRun with
    | context [fire_comp ?nn ?w ?ff] =>
        destruct (fire_comp nn w ff) as [[s3' f3']|] eqn:EFC3
    end; [|discriminate].
    cbv beta iota in HRun. injection HRun as <- <-.
    apply tag_z1canon_app_left_rmargin1; [exact HRseg|].
    apply tag_z1canon_app_left_rmargin1.
    - apply shape_rmargin_to1.
      apply (shape_rmargin_weaken 3 1 cols2 ltac:(lia)). exact HRcols2.
    - exact (IHf _ f s3' f3' HRs3 EFC3). }
  cbv beta iota in HRun.
  match type of HRun with
  | context [sand_leaf ?w] => destruct (sand_leaf w)
  end; [cbv beta iota in HRun; discriminate|].
  cbv beta iota in HRun.
  match type of HRun with
  | context [leaf_act ?w ?ff] =>
      destruct (leaf_act w ff) as [[s3' f3']|] eqn:ELA3
  end; [|discriminate].
  cbv beta iota in HRun. injection HRun as <- <-.
  apply tag_z1canon_app_left_rmargin1; [exact HRseg|].
  apply tag_z1canon_app_left_rmargin1.
  - apply shape_rmargin_to1.
    apply (shape_rmargin_weaken 3 1 cols2 ltac:(lia)). exact HRcols2.
  - apply tag_z1canon_of_rmargin1.
    apply (leaf_act_rmargin1_probe ((o7,z7,c7)::s3t) f s3' f3').
    + apply shape_rmargin_to1.
      apply (shape_rmargin_weaken 3 1 ((o7,z7,c7)::s3t) ltac:(lia)).
      exact HRs3.
    + exact ELA3.
Qed.
Lemma shape_rmargin_lits_app : forall n a b,
  shape_free a -> shape_rmargin n b -> shape_rmargin n (a ++ b).
Proof.
  intros n a b HA HB p g Hp HS.
  destruct (PeanoNat.Nat.lt_ge_cases p (length a)) as [Hpa|Hpa].
  - rewrite nth_error_app1 in Hp by exact Hpa.
    rewrite (HA g (nth_error_In a p Hp)) in HS. discriminate.
  - rewrite nth_error_app2 in Hp by exact Hpa.
    destruct (HB (p-length a)%nat g Hp HS) as (Hend & Hwin).
    split; [rewrite length_app; lia|].
    intros q Hq1 Hq2.
    assert (Hqa : (length a <= q)%nat) by lia.
    destruct (Hwin (q-length a)%nat ltac:(lia) ltac:(lia))
      as (gr & Hgr & HC & HPh).
    exists gr. split.
    + rewrite nth_error_app2 by exact Hqa.
      exact Hgr.
    + auto.
Qed.
Lemma deliver_tick_z1_canon_probe : forall n w f i o c w' f' via,
  shape_rmargin 3 w -> wat w i = Some (o,1%N,c) ->
  deliver_tick (S n) w f i via = ROk w' f' ->
  tag_z1canon w'.
Proof.
  intros n w f i o c w' f' via HR EW H.
  cbn [deliver_tick] in H. rewrite EW in H. cbv beta iota in H.
  destruct (2 <=? o)%N; [|discriminate].
  destruct (leaf_act (skipn i w) f) as [[s' f2]|] eqn:EL;
    [|discriminate].
  injection H as <- <-.
  pose proof (nth_skipn_cons w i (o,1%N,c) EW) as ESk.
  assert (HRs : shape_rmargin 3 (skipn i w)).
  { apply (shape_rmargin_app_r 3 (firstn i w) (skipn i w)).
    rewrite firstn_skipn. exact HR. }
  assert (HRp : shape_rmargin 3 (firstn i w)).
  { apply (shape_rmargin_prefix_noncasc 3 (firstn i w)
      (o,1%N,c) (skipn (S i) w)).
    - rewrite <- ESk. rewrite firstn_skipn. exact HR.
    - apply casc_z1_false. }
  apply tag_z1canon_app_left_rmargin1.
  - apply shape_rmargin_to1.
    apply (shape_rmargin_weaken 3 1 (firstn i w) ltac:(lia)). exact HRp.
  - apply tag_z1canon_of_rmargin1.
    apply (leaf_act_rmargin1_probe (skipn i w) f s' f2).
    + apply shape_rmargin_to1.
      apply (shape_rmargin_weaken 3 1 (skipn i w) ltac:(lia)). exact HRs.
    + exact EL.
Qed.
Lemma tag_z1canon_phfree_suffix : forall a b,
  tag_z1canon a -> shape_notlast a -> shape_free b ->
  tag_z1canon (a ++ b).
Proof.
  intros a b HA HN HB p g g1 Hp HS H1 Hz.
  destruct (PeanoNat.Nat.lt_ge_cases p (length a)) as [Hpa|Hpa].
  - rewrite nth_error_app1 in Hp by exact Hpa.
    assert (Hnext : (p+1 < length a)%nat) by (exact (HN p g Hp HS)).
    rewrite nth_error_app1 in H1 by exact Hnext.
    destruct (HA p g g1 Hp HS H1 Hz) as (-> & H2).
    split; [reflexivity|].
    rewrite nth_error_app1 by
      (apply nth_error_Some; rewrite H2; discriminate).
    exact H2.
  - rewrite nth_error_app2 in Hp by exact Hpa.
    assert (HG : phshape g = false).
    { apply HB. apply nth_error_In with (n := (p-length a)%nat). exact Hp. }
    rewrite HG in HS. discriminate.
Qed.
Lemma shape_notlast_nonempty_phfree_suffix : forall a b,
  shape_free b -> b <> [] -> shape_notlast (a ++ b).
Proof.
  intros a b HB Hne p g Hp HS.
  destruct (PeanoNat.Nat.lt_ge_cases p (length a)) as [Hpa|Hpa].
  - rewrite length_app. destruct b; [contradiction|cbn [length]; lia].
  - rewrite nth_error_app2 in Hp by exact Hpa.
    rewrite (HB g (nth_error_In b (p-length a)%nat Hp)) in HS.
    discriminate.
Qed.
Lemma dtb3_conv_notlast_ctx_probe : forall body pre body',
  dtb3_conv body = Some body' -> shape_notlast (pre ++ body').
Proof.
  intros body. induction body as [|[[o z] c] t IH];
    intros pre body' H; [discriminate|].
  cbn [dtb3_conv] in H.
  destruct (dtb3_conv t) as [t'|] eqn:ED.
  - injection H as <-. specialize (IH (pre++[(o,z,c)]) t' eq_refl).
    repeat rewrite <- app_assoc in IH. cbn [app] in IH. exact IH.
  - lazymatch type of H with
    | (if ?b then _ else _) = _ => destruct b eqn:E8 in H
    end; [|discriminate].
    cbn [gO gZ gC] in E8.
    apply andb_prop in E8 as [E8 Ec].
    apply andb_prop in E8 as [Eo Ez].
    apply N.eqb_eq in Eo, Ez, Ec. subst o z c.
    destruct t as [|[[o1 z1] c1] t1]; [discriminate|].
    lazymatch type of H with
    | (if ?b then _ else _) = _ => destruct b eqn:E1 in H
    end; [|discriminate].
    apply andb_prop in E1 as [E1 EW].
    apply andb_prop in E1 as [E1 _].
    apply andb_prop in E1 as [Eo1 Ez1].
    apply N.eqb_eq in Eo1, Ez1. rewrite Eo1, Ez1 in *.
    injection H as <-.
    apply shape_notlast_nonempty_phfree_suffix.
    + unfold shape_free. intros g Hg.
      repeat (destruct Hg as [<-|Hg]); try (destruct Hg);
        first [apply phshape_c1|
               apply phshape_onot9; reflexivity|
               exact (shape_free_w42_probe t1 EW g Hg)].
    + discriminate.
Qed.
Corollary dtb3_conv_notlast_probe : forall body body',
  dtb3_conv body = Some body' -> shape_notlast body'.
Proof.
  intros body body' H. exact (dtb3_conv_notlast_ctx_probe body [] body' H).
Qed.
Lemma stage_prefix3_canon_probe : forall X NL t,
  tag_z1canon t ->
  tag_z1canon (((X-1)%N,1%N,1%N) :: (7%N,2%N,1%N)
                 :: (4%N,2%N,(NL-1)%N) :: t).
Proof.
  intros X NL t H.
  change (tag_z1canon
    ([((X-1)%N,1%N,1%N);(7%N,2%N,1%N);
      (4%N,2%N,(NL-1)%N)] ++ t)).
  apply tag_z1canon_lits_app; [unfold shape_free; shape_lits_probe|exact H].
Qed.
Lemma fire_canon_step : forall n,
  fire_canon n -> renew_canon n -> fire_canon (S n).
Proof.
  intros n IHf IHr. unfold fire_canon in IHf |- *.
  unfold renew_canon in IHr.
  intros s f w2 f2 HR HRun.
  cbn [fire_comp] in HRun.
  destruct s as [|[[X z] c] rest0]; [discriminate|].
  destruct z as [|[zp|zp|]]; try discriminate.
  destruct zp as [zp'|zp'|]; try discriminate.
  destruct c as [|[cp|cp|]]; try discriminate.
  destruct (negb (5 <=? X))%N; [discriminate|].
  cbv beta iota in HRun.
  destruct rest0 as [|[[Y zY] cY] rest].
  { destruct (2 <=? f)%N; [|discriminate].
