Lemma tag_edges_prefix_probe : forall a b,
  tag_edges (a ++ b) -> tag_edges a.
Proof.
  intros a. induction a as [|x a IH]; intros b H; [exact I|].
  destruct a as [|y a]; [exact I|].
  cbn [app tag_edges] in H |- *.
  split; [exact (proj1 H)|].
  apply (IH b). exact (proj2 H).
Qed.
Lemma shape_head_free_prefix_probe : forall a b,
  shape_head_free (a ++ b) -> shape_head_free a.
Proof.
  intros [|x a] b H g t E; [discriminate|].
  injection E as <- <-. apply (H x (a++b)). reflexivity.
Qed.
Lemma edge_out_prefix_probe : forall a b,
  edge_out (a ++ b) -> edge_out a.
Proof.
  intros a b [HH HE]. split.
  - exact (shape_head_free_prefix_probe a b HH).
  - exact (tag_edges_prefix_probe a b HE).
Qed.
Lemma tag_edges_phfree_suffix_right_probe : forall a b,
  tag_edges a -> shape_free b ->
  (forall h t, b = h :: t -> right_edge h) ->
  tag_edges (a ++ b).
Proof.
  intros a. induction a as [|x a IH]; intros b HE HF HR.
  - apply tag_edges_shape_free_probe. exact HF.
  - destruct a as [|y a].
    + destruct b as [|h t]; [exact I|].
      change (edge_pair x h /\
              tag_edges (h :: t)).
      refine (conj _ (tag_edges_shape_free_probe (h :: t) _)).
      * split.
        -- intros _. exact (HR h t eq_refl).
        -- intros HS. rewrite (HF h (or_introl eq_refl)) in HS.
           discriminate.
      * intros g Hg. exact (HF g Hg).
    + cbn [app tag_edges] in HE |- *. split.
      * exact (proj1 HE).
      * apply IH; [exact (proj2 HE)|exact HF|exact HR].
Qed.
Lemma edge_pack_phfree_suffix_right_probe : forall a b,
  edge_out a -> shape_free b -> b <> [] ->
  (forall h t, b = h :: t -> right_edge h) ->
  edge_pack (a ++ b).
Proof.
  intros a b [HH HE] HF Hne HR. split.
  - split.
    + intros g t E. destruct a as [|x a].
      * cbn [app] in E. subst b. exact (HF g (or_introl eq_refl)).
      * cbn [app] in E. injection E as <- _.
        exact (HH x a eq_refl).
    + exact (tag_edges_phfree_suffix_right_probe a b HE HF HR).
  - exact (shape_notlast_nonempty_phfree_suffix a b HF Hne).
Qed.
Lemma right_edge_71_probe : right_edge (7%N,1%N,1%N).
Proof. right. reflexivity. Qed.
Lemma lawR_seg_edge_pack_probe : forall cols B body,
  edge_out cols -> lawR_seg cols B = Some body -> edge_pack body.
Proof.
  intros cols B body HP H. unfold lawR_seg in H.
  split_last2_margin H cols.
  destruct ((ga =? 8) && (gaz =? 2) && (gac =? 1)
    && (gb =? 4) && (gbz =? 2) && (1 <=? gbc))%N.
  - injection H as <-.
    apply edge_pack_phfree_suffix_right_probe.
    + apply (edge_out_prefix_probe ini [(ga,gaz,gac);(gb,gbz,gbc)]).
      cbn [app]. exact HP.
    + unfold shape_free. destruct (1 <? B)%N; shape_lits_probe.
    + destruct (1 <? B)%N; discriminate.
    + intros h t E. injection E as <- _. apply right_edge_71_probe.
  - destruct ((gb =? 8) && (gbz =? 2) && (gbc =? 1))%N;
      [|discriminate].
    injection H as <-.
    replace (ini ++ (ga,gaz,gac) :: (7,1,1) :: (3,2,1) ::
      (7,1,1) :: (3,2,1) ::
      (if 1 <? B then [(4,2,B-1)] else []))
      with ((ini ++ [(ga,gaz,gac)]) ++
        [(7,1,1);(3,2,1);(7,1,1);(3,2,1)] ++
        (if 1 <? B then [(4,2,B-1)] else []))
      by (repeat rewrite <- app_assoc; reflexivity).
    apply edge_pack_phfree_suffix_right_probe.
    + apply (edge_out_prefix_probe (ini++[(ga,gaz,gac)])
        [(gb,gbz,gbc)]).
      rewrite <- app_assoc. cbn [app]. exact HP.
    + unfold shape_free. destruct (1 <? B)%N; shape_lits_probe.
    + destruct (1 <? B)%N; discriminate.
    + intros h t E. injection E as <- _. apply right_edge_71_probe.
Qed.
