Lemma edge_pack_replace_phfree_suffix_right_probe : forall pre old new,
  edge_pack (pre ++ old) -> shape_free new -> new <> [] ->
  (forall h t, new = h :: t -> right_edge h) ->
  edge_pack (pre ++ new).
Proof.
  intros pre old new HP HF Hne HR.
  apply edge_pack_phfree_suffix_right_probe; [|exact HF|exact Hne|exact HR].
  exact (edge_out_prefix_probe pre old (proj1 HP)).
Qed.
Lemma dtb4_conv_edge_pack_ctx_probe : forall body pre body',
  edge_pack (pre ++ body) ->
  dtb4_conv body = Some body' -> edge_pack (pre ++ body').
Proof.
  intros body. induction body as [|[[o z] c] t IH];
    intros pre body' HP H; [discriminate|].
  cbn [dtb4_conv] in H.
  destruct (dtb4_conv t) as [t'|] eqn:ED.
  - injection H as <-.
    specialize (IH (pre ++ [(o,z,c)]) t').
    repeat rewrite <- app_assoc in IH. cbn [app] in IH.
    exact (IH HP eq_refl).
  - lazymatch type of H with
    | (if ?b then _ else _) = _ => destruct b eqn:E8 in H
    end; [|discriminate].
    cbn [gO gZ gC] in E8.
    apply andb_prop in E8 as [E8 Ec].
    apply andb_prop in E8 as [Eo Ez].
    apply N.eqb_eq in Eo, Ez, Ec. subst o z c.
    lazymatch type of H with
    | (if ?b then _ else _) = _ => destruct b eqn:EW in H
    end.
    + injection H as <-.
      eapply edge_pack_replace_phfree_suffix_right_probe; [exact HP| | |].
      * unfold shape_free. intros g Hg.
        destruct Hg as [<-|Hg]; [apply phshape_c1|].
        destruct Hg as [<-|Hg]; [apply phshape_c1|].
        exact (shape_free_w42_probe t EW g Hg).
      * discriminate.
      * intros h u E. injection E as <- _. apply right_edge_71_probe.
    + destruct t as [|[[o1 z1] c1] [|[[o2 z2] c2] t2]];
        try discriminate.
      lazymatch type of H with
      | (if ?b then _ else _) = _ => destruct b eqn:EOr in H
      end; [|discriminate].
      apply andb_prop in EOr as [EOr Ec2].
      apply andb_prop in EOr as [EOr Ez2].
      apply andb_prop in EOr as [EOr Eo2].
      apply andb_prop in EOr as [EOr _].
      apply andb_prop in EOr as [Eo1 Ez1].
      apply N.eqb_eq in Eo1, Ez1, Eo2, Ez2, Ec2.
      rewrite Eo1, Ez1, Eo2, Ez2, Ec2 in *.
      destruct t2 as [|[[o3 z3] c3] [|g4 t4]]; try discriminate.
      * injection H as <-.
        eapply edge_pack_replace_phfree_suffix_right_probe;
          [exact HP| | |].
        -- unfold shape_free. destruct (1 <? c1)%N; shape_lits_probe.
        -- destruct (1 <? c1)%N; discriminate.
        -- intros h u E. injection E as <- _. apply right_edge_71_probe.
      * lazymatch type of H with
        | (if ?b then _ else _) = _ => destruct b eqn:E3 in H
        end; [|discriminate].
        apply andb_prop in E3 as [Eo3 Ez3].
        apply N.eqb_eq in Eo3, Ez3. rewrite Eo3, Ez3 in *.
        injection H as <-.
        eapply edge_pack_replace_phfree_suffix_right_probe;
          [exact HP| | |].
        -- unfold shape_free. destruct (1 <? c1)%N; shape_lits_probe.
        -- destruct (1 <? c1)%N; discriminate.
        -- intros h u E. injection E as <- _. apply right_edge_71_probe.
Qed.
Lemma dtb3_conv_edge_pack_ctx_probe : forall body pre body',
  edge_pack (pre ++ body) ->
  dtb3_conv body = Some body' -> edge_pack (pre ++ body').
Proof.
  intros body. induction body as [|[[o z] c] t IH];
    intros pre body' HP H; [discriminate|].
  cbn [dtb3_conv] in H.
  destruct (dtb3_conv t) as [t'|] eqn:ED.
  - injection H as <-.
    specialize (IH (pre ++ [(o,z,c)]) t').
    repeat rewrite <- app_assoc in IH. cbn [app] in IH.
    exact (IH HP eq_refl).
  - lazymatch type of H with
    | (if ?b then _ else _) = _ => destruct b eqn:E8 in H
    end; [|discriminate].
    cbn [gO gZ gC] in E8.
    apply andb_prop in E8 as [E8 Ec].
    apply andb_prop in E8 as [Eo Ez].
    apply N.eqb_eq in Eo, Ez, Ec. subst o z c.
    destruct t as [|[[o1 z1] c1] t1]; [discriminate|].
    lazymatch type of H with
    | (if ?b then _ else _) = _ => destruct b eqn:E1 in H
    end; [|discriminate].
    apply andb_prop in E1 as [E1 EW].
    apply andb_prop in E1 as [E1 _].
    apply andb_prop in E1 as [Eo1 Ez1].
    apply N.eqb_eq in Eo1, Ez1. rewrite Eo1, Ez1 in *.
    injection H as <-.
    eapply edge_pack_replace_phfree_suffix_right_probe; [exact HP| | |].
    + unfold shape_free. intros g Hg.
      destruct Hg as [<-|Hg]; [apply phshape_c1|].
      destruct Hg as [<-|Hg]; [apply phshape_c1|].
      destruct Hg as [<-|Hg].
      * apply phshape_onot9. reflexivity.
      * exact (shape_free_w42_probe t1 EW g Hg).
    + discriminate.
    + intros h u E. injection E as <- _. apply right_edge_71_probe.
Qed.
