Lemma edge_pack_frame_nonside_probe : forall pin l pout t,
  edge_pack (pin ++ l :: t) -> ~ side8 l ->
  shape_free pout -> edge_pack (pout ++ t).
Proof.
  intros pin l pout t [[HH HE] HN] HNS HF. split.
  - exact (edge_out_replace_prefix_nonside pin l pout t HE HNS HF).
  - apply shape_notlast_lits_app; [exact HF|].
    apply (shape_notlast_app_r (pin ++ [l]) t).
    rewrite <- app_assoc. cbn [app]. exact HN.
Qed.
Corollary edge_pack_suffix_nonside_probe : forall pin l t,
  edge_pack (pin ++ l :: t) -> ~ side8 l -> edge_pack t.
Proof.
  intros pin l t HP HNS.
  change (edge_pack ([] ++ t)).
  eapply edge_pack_frame_nonside_probe; [exact HP|exact HNS|].
  unfold shape_free. intros g H. contradiction.
Qed.
Lemma shape_notlast_prefix_before_nonright_probe : forall a g t,
  tag_edges (a ++ g :: t) ->
  ~ right_edge g -> shape_notlast a.
Proof.
  intros a g t HE HNR p x Hp HS.
  assert (Hpa : (p < length a)%nat)
    by (apply nth_error_Some; rewrite Hp; discriminate).
  destruct (PeanoNat.Nat.lt_ge_cases (p+1) (length a)) as [Hlt|Hge];
    [exact Hlt|].
  assert (Ebd : (p+1 = length a)%nat) by lia.
  assert (Hpx : nth_error (a ++ g :: t) p = Some x).
  { rewrite nth_error_app1 by exact Hpa. exact Hp. }
  destruct (tag_edges_right (a ++ g::t) p x HE Hpx)
    as (gr & Hgr & HR).
  - rewrite length_app. cbn [length]. lia.
  - exact HS.
  - rewrite nth_error_app2 in Hgr by lia.
    rewrite Ebd, PeanoNat.Nat.sub_diag in Hgr.
    cbn [nth_error] in Hgr. injection Hgr as <-. contradiction.
Qed.
Lemma edge_pack_prefix_before_nonright_probe : forall a g t,
  edge_pack (a ++ g :: t) ->
  ~ right_edge g -> edge_pack a.
Proof.
  intros a g t [[HH HE] HN] HNR. split.
  - exact (edge_out_prefix_probe a (g::t) (conj HH HE)).
  - exact (shape_notlast_prefix_before_nonright_probe a g t HE HNR).
Qed.
Lemma edge_pack_suffix_head_free_probe : forall a g t,
  edge_pack (a ++ g :: t) -> phshape g = false -> edge_pack (g :: t).
Proof.
  intros a g t [[HH HE] HN] HG. split.
  - split.
    + intros x u E. injection E as <- _. exact HG.
    + exact (tag_edges_app_r_probe a (g::t) HE).
  - exact (shape_notlast_app_r a (g::t) HN).
Qed.
Lemma not_right_edge_z3_probe : forall o c,
  ~ right_edge (o,3%N,c).
Proof.
  intros o c [HS|HZ].
  - destruct HS as [_ HZ]. cbn [gZ] in HZ. discriminate.
  - cbn [gZ] in HZ. discriminate.
Qed.
Lemma edge_pack_split_z3_probe : forall a o c t,
  edge_pack (a ++ (o,3%N,c) :: t) ->
  edge_pack a /\ edge_pack ((o,3%N,c) :: t).
Proof.
  intros a o c t HP. split.
  - exact (edge_pack_prefix_before_nonright_probe a (o,3%N,c) t HP
      (not_right_edge_z3_probe o c)).
  - apply (edge_pack_suffix_head_free_probe a (o,3%N,c) t HP).
    apply phshape_znot2. reflexivity.
Qed.
Definition shape_nbrs1z (w : word) : Prop :=
  forall p g, nth_error w p = Some g -> phshape g = true ->
    exists gr, nth_error w (p+1) = Some gr /\
      (is_spc gr = true \/ gZ gr = 1%N).
Lemma shape_nbrs1z_of_live_probe : forall sg w,
  nbrs1z sg w -> lin_ptags sg w = true ->
  shape_nbrs1z w.
Proof.
  intros sg w HN HT p g Hp HS.
  assert (Hph : ph sg g = true)
    by (exact (lin_ptags_nth_shape_probe sg w p g HT Hp HS)).
  destruct (HN p g Hp Hph) as ((gr & Hgr & HR) & _).
  exists gr. auto.
Qed.
Lemma shape_nbrs1z_app_r_probe : forall a b,
  shape_nbrs1z (a ++ b) -> shape_nbrs1z b.
Proof.
  intros a b H p g Hp HS.
  assert (Hp' : nth_error (a++b) (length a+p) = Some g).
  { rewrite nth_error_app2 by lia.
    replace (length a+p-length a)%nat with p by lia. exact Hp. }
  destruct (H (length a+p)%nat g Hp' HS) as (gr & Hgr & HR).
  exists gr. split; [|exact HR].
  rewrite nth_error_app2 in Hgr by lia.
  replace (length a+p+1-length a)%nat with (p+1)%nat in Hgr by lia.
  exact Hgr.
Qed.
Lemma tag_edges_app_boundary_probe : forall a b,
  tag_edges a -> tag_edges b ->
  (forall ini x y t, a = ini ++ [x] -> b = y :: t ->
     edge_pair x y) ->
  tag_edges (a ++ b).
Proof.
  intros a. induction a as [|x a IH]; intros b HA HB HJ; [exact HB|].
  destruct a as [|y a].
  - destruct b as [|z b]; [exact I|].
    cbn [app tag_edges]. split; [|exact HB].
    exact (HJ [] x z b eq_refl eq_refl).
  - cbn [tag_edges app] in HA |- *. split.
    + exact (proj1 HA).
    + apply IH.
      * exact (proj2 HA).
      * exact HB.
      * intros ini q z t E1 E2.
        apply (HJ (x::ini) q z t); [cbn [app]; f_equal; exact E1|exact E2].
Qed.
Lemma shape_notlast_app_boundary_probe : forall a b,
  shape_notlast b ->
  (forall p g, nth_error a p = Some g -> phshape g = true ->
     (p+1 = length a)%nat -> b <> []) ->
  shape_notlast (a ++ b).
Proof.
  intros a b HB HJ p g Hp HS.
  destruct (PeanoNat.Nat.lt_ge_cases p (length a)) as [Hpa|Hpa].
  - rewrite nth_error_app1 in Hp by exact Hpa.
    destruct (PeanoNat.Nat.lt_ge_cases (p+1) (length a)) as [Hin|Hbd].
    + rewrite length_app. lia.
    + assert (Ebd : (p+1 = length a)%nat) by lia.
      specialize (HJ p g Hp HS Ebd).
      rewrite length_app. destruct b; [contradiction|cbn [length]; lia].
  - rewrite nth_error_app2 in Hp by exact Hpa.
    specialize (HB (p-length a)%nat g Hp HS).
    rewrite length_app. lia.
Qed.
Lemma seek_boundary_tag_exact_probe : forall w cols g t ini x,
  seek w = (cols, g :: t) -> w = cols ++ g :: t ->
  cols = ini ++ [x] -> phshape x = true ->
  shape_nbrs1z w -> tag_z1canon w ->
  g = (7%N,1%N,1%N) /\
  exists u, t = (3%N,2%N,1%N) :: u.
Proof.
  intros w cols g t ini x ESK EW EC HX HN HC. subst cols.
  set (p := length ini).
  assert (Hx : nth_error w p = Some x).
  { rewrite EW. rewrite nth_error_app1.
    - unfold p. rewrite nth_error_app2 by lia.
      rewrite PeanoNat.Nat.sub_diag. reflexivity.
    - unfold p. rewrite length_app. cbn [length]. lia. }
  destruct (HN p x Hx HX) as (gr & Hgr & [Hsp|Hz]).
  - assert (Hseek : seektest g = false).
    { apply (seek_snd_head w g t).
      rewrite ESK. reflexivity. }
    assert (Hgrg : gr = g).
    { rewrite EW in Hgr. rewrite nth_error_app2 in Hgr.
      - unfold p in Hgr. rewrite length_app in Hgr. cbn [length] in Hgr.
        replace (length ini + 1 - (length ini + 1))%nat with O in Hgr by lia.
        cbn [nth_error] in Hgr. congruence.
      - unfold p. rewrite length_app. cbn [length]. lia. }
    subst gr.
    assert (HCasc : casc g = true).
    { unfold casc. apply orb_true_iff. right. exact Hsp. }
    rewrite (casc_seekable g HCasc) in Hseek. discriminate.
  - assert (Hgrg : gr = g).
    { rewrite EW in Hgr. rewrite nth_error_app2 in Hgr.
      - unfold p in Hgr. rewrite length_app in Hgr. cbn [length] in Hgr.
        replace (length ini + 1 - (length ini + 1))%nat with O in Hgr by lia.
        cbn [nth_error] in Hgr. congruence.
      - unfold p. rewrite length_app. cbn [length]. lia. }
    subst gr.
    assert (Hg : nth_error w (p+1) = Some g) by exact Hgr.
    destruct (HC p x g Hx HX Hg Hz) as (Eg & H2). split; [exact Eg|].
    subst g. destruct t as [|h u].
    + rewrite EW in H2. rewrite nth_error_app2 in H2.
      * unfold p in H2. rewrite length_app in H2. cbn [length] in H2.
        replace (length ini + 2 - (length ini + 1))%nat with 1%nat in H2 by lia.
        cbn [nth_error] in H2. discriminate.
      * unfold p. rewrite length_app. cbn [length]. lia.
    + exists u. f_equal.
      rewrite EW in H2. rewrite nth_error_app2 in H2.
      * unfold p in H2. rewrite length_app in H2. cbn [length] in H2.
        replace (length ini + 2 - (length ini + 1))%nat with 1%nat in H2 by lia.
        cbn [nth_error] in H2. congruence.
      * unfold p. rewrite length_app. cbn [length]. lia.
Qed.
Lemma leaf_act_7132_head_probe : forall t f out f',
  leaf_act ((7%N,1%N,1%N)::(3%N,2%N,1%N)::t) f
    = Some (out,f') ->
  exists u, out = (7%N,1%N,1%N) :: u.
Proof.
  intros t f out f' H. cbn [leaf_act] in H.
  injection H as <- <-. eexists. reflexivity.
Qed.
Lemma leaf_after_seek_edge_pack_probe : forall w cols s f out f',
  seek w = (cols,s) -> shape_lmargin 2 s -> edge_pack w ->
  shape_nbrs1z w -> tag_z1canon w ->
  leaf_act s f = Some (out,f') -> edge_pack (cols ++ out).
Proof.
  intros w cols s f out f' ESK HM HP HN HC EL.
  destruct s as [|g t]; [cbn [leaf_act] in EL; discriminate|].
  assert (EW : w = cols ++ g :: t).
  { pose proof (LineageGuard_seek_split w) as H.
    rewrite ESK in H. cbn [fst snd] in H. exact H. }
  assert (HPs : edge_pack (g::t))
    by (exact (seek_suffix_edge_pack w cols g t ESK HP)).
  assert (HPout : edge_pack out)
    by (exact (leaf_act_edge_pack2_probe (g::t) f out f' HM HPs EL)).
  destruct HP as [[HH HE] Hlast]. destruct HPout as [[HHo HEo] HNo].
  split.
  - split.
    + intros h u E. destruct cols as [|q cols].
      * cbn [app] in E. exact (HHo h u E).
      * cbn [app] in E. injection E as <- _.
        exact (HH q (cols++g::t) ltac:(rewrite EW; reflexivity)).
    + apply tag_edges_app_boundary_probe.
      * exact (tag_edges_prefix_probe cols (g::t) ltac:(rewrite <- EW; exact HE)).
      * exact HEo.
      * intros ini x y u EC EO. split.
        -- intros HX.
           destruct (seek_boundary_tag_exact_probe w cols g t ini x
             ESK EW EC HX HN HC) as (-> & v & ->).
           destruct (leaf_act_7132_head_probe v f out f' EL) as (u' & Eout).
           assert (Ey : y = (7%N,1%N,1%N)) by (rewrite EO in Eout; congruence).
           subst y.
           apply right_edge_71_probe.
        -- intros HY. rewrite (HHo y u EO) in HY. discriminate.
  - apply shape_notlast_app_boundary_probe; [exact HNo|].
    intros p x Hx HX Ebd.
    destruct (nth_error_split cols p Hx)
      as (ini & tail & EC & Elen).
    assert (Etail : tail = []).
    { rewrite EC, length_app in Ebd. cbn [length] in Ebd.
      rewrite Elen in Ebd. apply length_zero_iff_nil. lia. }
    subst tail.
    destruct (seek_boundary_tag_exact_probe w cols g t ini x
      ESK EW EC HX HN HC) as (-> & v & ->).
    destruct (leaf_act_7132_head_probe v f out f' EL) as (u & ->).
    discriminate.
Qed.
Lemma seek_suffix_lmargin_ctx_probe : forall n pre w cols g t,
  seek w = (cols,g::t) -> shape_lmargin n (pre ++ w) ->
  shape_lmargin n (g::t).
Proof.
  intros n pre w cols g t ESK HM.
  pose proof (LineageGuard_seek_split w) as EW.
  rewrite ESK in EW. cbn [fst snd] in EW.
  apply (shape_lmargin_suffix_noncasc n (pre++cols) g t).
  - rewrite <- app_assoc. rewrite <- EW. exact HM.
  - apply seektest_noncasc.
    apply (seek_snd_head w g t).
    rewrite ESK. reflexivity.
  - pose proof (seektest_notag g
      (seek_snd_head w g t ltac:(rewrite ESK; reflexivity))) as H.
    unfold notag in H. apply negb_true_iff in H. exact H.
Qed.
Definition fire_edges (n : nat) : Prop :=
  forall s f out f',
    shape_lmargin 2 s -> edge_pack s ->
    shape_nbrs1z s -> tag_z1canon s ->
    fire_comp n s f = Some (out,f') -> edge_pack out.
Definition renew_edges (n : nat) : Prop :=
  forall cols s f out f',
    shape_lmargin 2 s -> edge_pack (cols ++ s) ->
    shape_nbrs1z (cols ++ s) -> tag_z1canon (cols ++ s) ->
    renew_seg n cols s f = Some (out,f') -> edge_pack out.
Lemma edge_pack_shape_free_probe : forall w,
  shape_free w -> edge_pack w.
Proof.
  intros w HF. split.
  - exact (edge_out_shape_free w HF).
  - exact (shape_notlast_shape_free w HF).
Qed.
Lemma renew_edges_step : forall n,
  fire_edges n -> renew_edges n -> renew_edges (S n).
Proof.
  intros n IHf IHr. unfold fire_edges in IHf.
  unfold renew_edges in IHr |- *.
  intros cols s f body f2 HM HP HN HC HRun.
  cbn [renew_seg] in HRun.
  destruct s as [|[[o0 z0] c_0] rest]; [discriminate|].
  destruct o0 as [|o1]; try discriminate.
  destruct o1 as [o1|o1|]; try discriminate.
  destruct o1 as [o1|o1|]; try discriminate.
  destruct o1 as [o1|o1|]; try discriminate.
  destruct z0 as [|z1]; try discriminate.
  destruct z1 as [z1|z1|]; try discriminate.
  destruct z1 as [z1|z1|]; try discriminate.
  destruct c_0 as [|c1]; try discriminate.
  destruct c1 as [c1|c1|]; try discriminate.
  assert (Hcols : edge_out cols).
  { apply (edge_out_prefix_probe cols ((4%N,3%N,1%N)::rest)).
    exact (proj1 HP). }
  destruct rest as [|[[o5 z5] B] rest2].
  { destruct (endR_seg cols f) as [body0|] eqn:EER;
      [|discriminate].
    injection HRun as <- <-.
    exact (endR_seg_edge_pack_probe cols f body0 Hcols EER). }
  destruct ((o5 =? 4) && (z5 =? 2) && (1 <=? B))%N eqn:E52.
  2:{ destruct ((z5 =? 3) && (B =? 1)
                && match rest2 with [] => true | _ :: _ => false end
                && (f =? 4) && (1 <=? o5))%N eqn:EREN;
        [|discriminate].
      split6 EREN.
      destruct rest2 as [|g2 r2]; try discriminate.
      cbv beta iota in HRun.
      destruct (endY_seg cols o5) as [body0|] eqn:EEY;
        [|discriminate].
      injection HRun as <- <-.
      exact (endY_seg_edge_pack_probe cols o5 body0 Hcols EEY). }
  cbv beta iota in HRun.
  apply andb_prop in E52 as [E52 _].
  apply andb_prop in E52 as [Eo5 Ez5].
  apply N.eqb_eq in Eo5, Ez5. subst o5 z5.
  destruct rest2 as [|gr2 rest2t].
  { destruct (f =? 4)%N.
    - destruct (lawR_seg cols B) as [body0|] eqn:ELR;
        [|discriminate].
      injection HRun as <- <-.
      exact (lawR_seg_edge_pack_probe cols B body0 Hcols ELR).
    - destruct (5 <=? f)%N; [|discriminate].
      destruct (jump_seg cols B) as [seg|] eqn:EJP;
        [|discriminate].
      injection HRun as <- <-.
      apply edge_pack_app.
      + exact (jump_seg_edge_pack_probe cols B seg Hcols EJP).
      + apply edge_pack_shape_free_probe. unfold shape_free. shape_lits_probe. }
  destruct (jump_seg cols B) as [seg|] eqn:EJS;
    [|discriminate].
  assert (Hseg : edge_pack seg)
    by (exact (jump_seg_edge_pack_probe cols B seg Hcols EJS)).
  set (rest2 := gr2 :: rest2t) in *.
  assert (HPrest : edge_pack rest2).
  { eapply edge_pack_suffix_nonside_probe with
      (pin := cols ++ [(4%N,3%N,1%N)]) (l := (4%N,2%N,B)).
    - rewrite <- app_assoc. cbn [app]. exact HP.
    - apply not_side8_o4. }
  assert (HNrest : shape_nbrs1z rest2).
  { apply (shape_nbrs1z_app_r_probe
      (cols ++ [(4%N,3%N,1%N);(4%N,2%N,B)]) rest2).
    repeat rewrite <- app_assoc. cbn [app]. exact HN. }
  assert (HCrest : tag_z1canon rest2).
  { apply (tag_z1canon_app_r
      (cols ++ [(4%N,3%N,1%N);(4%N,2%N,B)]) rest2).
    repeat rewrite <- app_assoc. cbn [app]. exact HC. }
  cbv beta iota in HRun.
  destruct (seek rest2) as [cols2 s3] eqn:ESK2.
  pose proof (LineageGuard_seek_split rest2) as HSP2.
  rewrite ESK2 in HSP2. cbn [fst snd] in HSP2.
  assert (HMs3 : shape_lmargin 2 s3).
  { destruct s3 as [|g t].
    - apply shape_lmargin_shape_free. unfold shape_free. intros x Hx.
      contradiction.
    - apply (seek_suffix_lmargin_ctx_probe 2
        [(4%N,3%N,1%N);(4%N,2%N,B)] rest2 cols2 g t ESK2).
      cbn [app]. exact HM. }
  assert (HPjoin : edge_pack (cols2 ++ s3)) by (rewrite <- HSP2; exact HPrest).
  assert (HNjoin : shape_nbrs1z (cols2 ++ s3))
    by (rewrite <- HSP2; exact HNrest).
  assert (HCjoin : tag_z1canon (cols2 ++ s3))
    by (rewrite <- HSP2; exact HCrest).
  match type of HRun with
  | context [renew_seg ?nn ?cc ?ss ?ff] =>
      destruct (renew_seg nn cc ss ff) as [[body0 f0]|] eqn:ERN2
  end.
  { cbv beta iota in HRun. injection HRun as <- <-.
    apply edge_pack_app; [exact Hseg|].
    exact (IHr cols2 s3 f body0 f0 HMs3 HPjoin HNjoin HCjoin ERN2). }
  cbv beta iota in HRun.
  destruct s3 as [|[[o7 z7] c7] s3t].
  { cbn [leaf_act] in HRun. cbv beta iota in HRun.
    assert (HPcols2 : edge_pack cols2).
    { rewrite app_nil_r in HPjoin. exact HPjoin. }
    destruct (5 <=? f)%N.
    - injection HRun as <- <-.
      apply edge_pack_app; [exact Hseg|].
      apply edge_pack_app; [exact HPcols2|].
      apply edge_pack_shape_free_probe. unfold shape_free. shape_lits_probe.
    - destruct (f =? 4)%N; [|discriminate].
      match type of HRun with
      | context [dtb4_conv ?w] =>
          destruct (dtb4_conv w) as [cols2'|] eqn:EDC
      end.
      + cbv beta iota in HRun. injection HRun as <- <-.
        apply edge_pack_app; [exact Hseg|].
        exact (dtb4_conv_edge_pack_probe cols2 cols2' HPcols2 EDC).
      + cbv beta iota in HRun.
        destruct (forallb w42 cols2); [|discriminate].
        destruct (lawR_seg cols B) as [seg2|] eqn:ELR2;
          [|discriminate].
        injection HRun as <- <-.
        apply edge_pack_app.
        * exact (lawR_seg_edge_pack_probe cols B seg2 Hcols ELR2).
        * exact HPcols2. }
  assert (HPs3 : edge_pack ((o7,z7,c7)::s3t)).
  { exact (seek_suffix_edge_pack rest2 cols2 (o7,z7,c7) s3t ESK2 HPrest). }
  assert (HNs3 : shape_nbrs1z ((o7,z7,c7)::s3t))
    by (exact (shape_nbrs1z_app_r_probe cols2 _ HNjoin)).
  assert (HCs3 : tag_z1canon ((o7,z7,c7)::s3t))
    by (exact (tag_z1canon_app_r cols2 _ HCjoin)).
  destruct ((z7 =? 3) && (c7 =? 1))%N eqn:E73.
  { cbv beta iota in HRun.
    apply andb_prop in E73 as [Ez7 Ec7].
    apply N.eqb_eq in Ez7, Ec7. subst z7 c7.
    match type of HRun with
    | context [fire_comp ?nn ?w ?ff] =>
        destruct (fire_comp nn w ff) as [[s3' f3']|] eqn:EFC3
    end; [|discriminate].
    cbv beta iota in HRun. injection HRun as <- <-.
    destruct (edge_pack_split_z3_probe cols2 o7 1%N s3t HPjoin)
      as (HPcols2 & _).
    apply edge_pack_app; [exact Hseg|].
    apply edge_pack_app; [exact HPcols2|].
    exact (IHf ((o7,3%N,1%N)::s3t) f s3' f3'
      HMs3 HPs3 HNs3 HCs3 EFC3). }
  cbv beta iota in HRun.
  match type of HRun with
  | context [sand_leaf ?w] => destruct (sand_leaf w)
  end; [cbv beta iota in HRun; discriminate|].
  cbv beta iota in HRun.
  match type of HRun with
  | context [leaf_act ?w ?ff] =>
      destruct (leaf_act w ff) as [[s3' f3']|] eqn:ELA3
  end; [|discriminate].
  cbv beta iota in HRun. injection HRun as <- <-.
  apply edge_pack_app; [exact Hseg|].
  exact (leaf_after_seek_edge_pack_probe rest2 cols2
    ((o7,z7,c7)::s3t) f s3' f3' ESK2 HMs3 HPrest HNrest HCrest ELA3).
Qed.
Lemma split_boundary_tag_z1_exact_probe : forall w pre g t ini x,
  w = pre ++ g :: t -> pre = ini ++ [x] ->
  phshape x = true -> tag_z1canon w -> gZ g = 1%N ->
  g = (7%N,1%N,1%N) /\ exists u, t = (3%N,2%N,1%N) :: u.
Proof.
  intros w pre g t ini x EW EC HX HC Hz. subst pre.
  set (p := length ini).
  assert (Hx : nth_error w p = Some x).
  { rewrite EW. rewrite nth_error_app1.
    - unfold p. rewrite nth_error_app2 by lia.
      rewrite PeanoNat.Nat.sub_diag. reflexivity.
    - unfold p. rewrite length_app. cbn [length]. lia. }
  assert (Hg : nth_error w (p+1) = Some g).
  { rewrite EW. rewrite nth_error_app2.
    - unfold p. rewrite length_app. cbn [length].
      replace (length ini+1-(length ini+1))%nat with O by lia.
      reflexivity.
    - unfold p. rewrite length_app. cbn [length]. lia. }
  destruct (HC p x g Hx HX Hg Hz) as (Eg & H2). split; [exact Eg|].
  subst g. destruct t as [|h u].
  - rewrite EW in H2. rewrite nth_error_app2 in H2.
    + unfold p in H2. rewrite length_app in H2. cbn [length] in H2.
      replace (length ini+2-(length ini+1))%nat with 1%nat in H2 by lia.
      cbn [nth_error] in H2. discriminate.
    + unfold p. rewrite length_app. cbn [length]. lia.
  - exists u. f_equal.
    rewrite EW in H2. rewrite nth_error_app2 in H2.
    + unfold p in H2. rewrite length_app in H2. cbn [length] in H2.
      replace (length ini+2-(length ini+1))%nat with 1%nat in H2 by lia.
      cbn [nth_error] in H2. congruence.
    + unfold p. rewrite length_app. cbn [length]. lia.
Qed.
Lemma leaf_after_split_z1_edge_pack_probe : forall w pre o c t f out f',
  w = pre ++ (o,1%N,c) :: t -> shape_lmargin 2 ((o,1%N,c)::t) ->
  edge_pack w -> tag_z1canon w ->
  leaf_act ((o,1%N,c)::t) f = Some (out,f') ->
  edge_pack (pre ++ out).
Proof.
  intros w pre o c t f out f' EW HM HP HC EL.
  assert (HPs : edge_pack ((o,1%N,c)::t)).
  { apply (edge_pack_suffix_head_free_probe pre (o,1%N,c) t).
    - rewrite EW in HP. exact HP.
    - apply phshape_znot2. reflexivity. }
  assert (HPout : edge_pack out)
    by (exact (leaf_act_edge_pack2_probe _ f out f' HM HPs EL)).
  destruct HP as [[HH HE] Hlast]. destruct HPout as [[HHo HEo] HNo].
  split.
  - split.
    + intros h u E. destruct pre as [|q pre].
      * cbn [app] in E. exact (HHo h u E).
      * cbn [app] in E. injection E as <- _.
        exact (HH q (pre++(o,1%N,c)::t) ltac:(rewrite EW; reflexivity)).
    + apply tag_edges_app_boundary_probe.
      * pose proof HE as HE'. rewrite EW in HE'.
        exact (tag_edges_prefix_probe pre ((o,1%N,c)::t) HE').
      * exact HEo.
      * intros ini x y u EC EO. split.
        -- intros HX.
           destruct (split_boundary_tag_z1_exact_probe w pre
             (o,1%N,c) t ini x EW EC HX HC eq_refl) as (Eg & v & Et).
           assert (Eo : o = 7%N) by congruence.
           assert (Ec : c = 1%N) by congruence. subst o c t.
           destruct (leaf_act_7132_head_probe v f out f' EL) as (u' & Eout).
           assert (Ey : y = (7%N,1%N,1%N)) by (rewrite EO in Eout; congruence).
           subst y. apply right_edge_71_probe.
        -- intros HY. rewrite (HHo y u EO) in HY. discriminate.
  - apply shape_notlast_app_boundary_probe; [exact HNo|].
    intros p x Hx HX Ebd.
    destruct (nth_error_split pre p Hx) as (ini & tail & EC & Elen).
    assert (Etail : tail = []).
    { rewrite EC, length_app in Ebd. cbn [length] in Ebd.
      rewrite Elen in Ebd. apply length_zero_iff_nil. lia. }
    subst tail.
    destruct (split_boundary_tag_z1_exact_probe w pre
      (o,1%N,c) t ini x EW EC HX HC eq_refl) as (Eg & v & Et).
    assert (Eo : o = 7%N) by congruence.
    assert (Ec : c = 1%N) by congruence. subst o c t.
    destruct (leaf_act_7132_head_probe v f out f' EL) as (u & ->).
    discriminate.
Qed.
Lemma deliver_tick_z1_edges_probe : forall n w f i o c out f' via,
  shape_lmargin 2 (skipn i w) -> edge_pack w -> tag_z1canon w ->
  wat w i = Some (o,1%N,c) ->
  deliver_tick (S n) w f i via = ROk out f' -> edge_pack out.
Proof.
  intros n w f i o c out f' via HM HP HC EW H.
  cbn [deliver_tick] in H. rewrite EW in H. cbv beta iota in H.
  destruct (2 <=? o)%N; [|discriminate].
  destruct (leaf_act (skipn i w) f) as [[s' f2]|] eqn:EL;
    [|discriminate].
  injection H as <- <-.
  pose proof (nth_skipn_cons w i (o,1%N,c) EW) as ESk.
  assert (EFull : w = firstn i w ++ (o,1%N,c) :: skipn (S i) w).
  { pose proof (firstn_skipn i w) as HFS. rewrite ESk in HFS.
    symmetry. exact HFS. }
  assert (HMs : shape_lmargin 2 ((o,1%N,c)::skipn (S i) w)).
  { rewrite ESk in HM. exact HM. }
  rewrite ESk in EL.
  exact (leaf_after_split_z1_edge_pack_probe w (firstn i w) o c
    (skipn (S i) w) f s' f2 EFull HMs HP HC EL).
Qed.
Lemma fire_comp_head_z3_probe : forall n o z c t f out f',
  fire_comp n ((o,z,c)::t) f = Some (out,f') ->
  z = 3%N /\ c = 1%N.
Proof.
  intros [|n] o z c t f out f' H; [discriminate|].
  cbn [fire_comp] in H.
  destruct z as [|[zp|zp|]]; try discriminate.
  destruct zp as [zp'|zp'|]; try discriminate.
  destruct c as [|[cp|cp|]]; try discriminate.
  auto.
Qed.
Lemma shape_head_free_tail2_probe : forall a b t,
  shape_lmargin 2 (a::b::t) -> casc a = false ->
  shape_head_free t.
Proof.
  intros a b [|g u] HM HA x v E; [discriminate|].
  injection E as <- <-. destruct (phshape g) eqn:HG;
    [|reflexivity].
  destruct (HM 2%nat g eq_refl HG) as (_ & HW).
  destruct (HW O ltac:(lia) ltac:(lia)) as (q & Hq & HC & _).
  cbn [nth_error] in Hq. injection Hq as <-. congruence.
Qed.
Lemma edge_pack_tail2_probe : forall a b t,
  shape_lmargin 2 (a::b::t) -> casc a = false ->
  edge_pack (a::b::t) -> edge_pack t.
Proof.
  intros a b t HM HA [[HH HE] HN]. split.
  - split.
    + exact (shape_head_free_tail2_probe a b t HM HA).
    + exact (tag_edges_app_r_probe [a;b] t HE).
  - exact (shape_notlast_app_r [a;b] t HN).
Qed.
Lemma fire_edges_step : forall n,
  fire_edges n -> renew_edges n -> fire_edges (S n).
Proof.
  intros n IHf IHr. unfold fire_edges in IHf |- *.
  unfold renew_edges in IHr.
  intros s f out f' HM HP HN HC HRun.
  cbn [fire_comp] in HRun.
  destruct s as [|[[X z] c] rest0]; [discriminate|].
  destruct z as [|[zp|zp|]]; try discriminate.
  destruct zp as [zp'|zp'|]; try discriminate.
  destruct c as [|[cp|cp|]]; try discriminate.
  destruct (negb (5 <=? X))%N; [discriminate|].
  cbv beta iota in HRun.
  destruct rest0 as [|[[Y zY] cY] rest].
  { destruct (2 <=? f)%N; [|discriminate].
    injection HRun as <- <-. apply edge_pack_shape_free_probe.
    unfold shape_free. shape_lits_probe. }
  destruct ((Y =? 4) && (zY =? 2))%N eqn:EY4.
  2:{ cbv beta iota in HRun.
      destruct ((Y =? 8) && (zY =? 2) && (cY =? 1))%N eqn:EY8.
      { cbv beta iota zeta in HRun.
        apply andb_prop in EY8 as [EY8 EcY].
        apply andb_prop in EY8 as [EYo EYz].
        apply N.eqb_eq in EYo, EYz, EcY. subst Y zY cY.
        unfold tick_target in HRun. cbn [skipn] in HRun.
        destruct (tick_target_s rest 2%nat) as [i|] eqn:ETT;
          [|discriminate].
        cbv beta iota in HRun.
        match type of HRun with
        | context [wat ?ww ?ii] =>
            destruct (wat ww ii) as [[[og zg] cg]|] eqn:EWC in HRun
        end; [|discriminate].
        cbv beta iota in HRun.
