    change (shape_lmargin 2
      ([((X-1)%N,1%N,1%N);(7%N,2%N,1%N);
        (4%N,2%N,cY-1)] ++ (cols ++ s2'))).
    apply shape_lmargin_lits_app; [unfold shape_free; shape_lits_probe|].
    apply shape_lmargin_app; [exact HMcols|].
    exact (IHf ((o4,z4,c4)::s2t) f s2' f2' HMs2 EFC2). }
  cbv beta iota in HRun.
  match type of HRun with
  | context [leaf_act ?ss ?ff] =>
      destruct (leaf_act ss ff) as [[s2' f2']|] eqn:ELA2
  end; [|discriminate].
  cbv beta iota in HRun. injection HRun as <- <-.
  change (shape_lmargin 2
    ([((X-1)%N,1%N,1%N);(7%N,2%N,1%N);
      (4%N,2%N,cY-1)] ++ (cols ++ s2'))).
  apply shape_lmargin_lits_app; [unfold shape_free; shape_lits_probe|].
  apply shape_lmargin_app; [exact HMcols|].
  exact (leaf_act_margin3to2_probe
    ((o4,z4,c4)::s2t) f s2' f2' HMs2 ELA2).
Qed.
Lemma fire_renew_margin32_probe : forall n,
  fire_margin32 n /\ renew_margin32 n.
Proof.
  induction n as [|n [IHf IHr]].
  - split; unfold fire_margin32, renew_margin32; intros; discriminate.
  - split.
    + exact (fire_margin32_step n IHf IHr).
    + exact (renew_margin32_step n IHf IHr).
Qed.
Corollary fire_comp_margin32_probe : forall n s f out f',
  shape_lmargin 3 s ->
  fire_comp n s f = Some (out,f') -> shape_lmargin 2 out.
Proof. intros n. exact (proj1 (fire_renew_margin32_probe n)). Qed.
Corollary renew_seg_margin32_probe : forall n cols s f out f',
  shape_lmargin 2 (cols ++ s) -> shape_lmargin 3 s ->
  renew_seg n cols s f = Some (out,f') -> shape_lmargin 2 out.
Proof. intros n. exact (proj2 (fire_renew_margin32_probe n)). Qed.
Lemma shape_head_free_of_lmargin_probe : forall n w,
  (1 <= n)%nat -> shape_lmargin n w -> shape_head_free w.
Proof.
  intros n [|g t] Hn HM x u E; [discriminate|].
  injection E as <- <-. destruct (phshape g) eqn:HP;
    [|reflexivity].
  destruct (HM O g eq_refl HP) as (Hlo & _). lia.
Qed.
Lemma round_at_after_seek_margin_ctx_probe : forall w cols s f out f',
  seek w = (cols,s) ->
  shape_lmargin 2 w -> shape_lmargin 3 s ->
  round_at cols s f = Some (out,f') -> shape_lmargin 2 out.
Proof.
  intros w cols s f out f' ESK HM2 HM3 HRun.
  pose proof (LineageGuard_seek_split w) as HSP.
  rewrite ESK in HSP. cbn [fst snd] in HSP.
  assert (HMjoin2 : shape_lmargin 2 (cols++s)).
  { exact (eq_ind w (fun x => shape_lmargin 2 x) HM2 _ HSP). }
  assert (HMcols : shape_lmargin 2 cols)
    by (exact (shape_lmargin_prefix 2 cols s HMjoin2)).
  unfold round_at in HRun.
  destruct s as [|[[og zg] cg] t].
  { cbn [leaf_act] in HRun. discriminate. }
  pose proof HM3 as HMs3.
  assert (LEAF : forall s2 g2,
    leaf_act ((og,zg,cg)::t) f = Some (s2,g2) ->
    shape_lmargin 2 (cols++s2)).
  { intros s2 g2 EL. apply shape_lmargin_app; [exact HMcols|].
    exact (leaf_act_margin3to2_probe _ f s2 g2 HMs3 EL). }
  destruct zg as [|[z1|z1|]].
  { match type of HRun with
    | context [leaf_act ?ss ?ff] =>
        destruct (leaf_act ss ff) as [[s2 g2]|] eqn:EL
    end; [|discriminate]. cbv beta iota in HRun.
    injection HRun as <- <-. exact (LEAF s2 g2 EL). }
  2:{ match type of HRun with
    | context [leaf_act ?ss ?ff] =>
        destruct (leaf_act ss ff) as [[s2 g2]|] eqn:EL
    end; [|discriminate]. cbv beta iota in HRun.
    injection HRun as <- <-. exact (LEAF s2 g2 EL). }
  2:{ match type of HRun with
    | context [leaf_act ?ss ?ff] =>
        destruct (leaf_act ss ff) as [[s2 g2]|] eqn:EL
    end; [|discriminate]. cbv beta iota in HRun.
    injection HRun as <- <-. exact (LEAF s2 g2 EL). }
  destruct z1 as [z1|z1|].
  1,2: match type of HRun with
  | context [leaf_act ?ss ?ff] =>
      destruct (leaf_act ss ff) as [[s2 g2]|] eqn:EL
  end; [cbv beta iota in HRun; injection HRun as <- <-;
        exact (LEAF s2 g2 EL)|discriminate].
  destruct cg as [|[c1|c1|]].
  1,2,3: match type of HRun with
  | context [leaf_act ?ss ?ff] =>
      destruct (leaf_act ss ff) as [[s2 g2]|] eqn:EL
  end; [cbv beta iota in HRun; injection HRun as <- <-;
        exact (LEAF s2 g2 EL)|discriminate].
  match type of HRun with
  | context [renew_seg ?nn ?cc ?ss ?ff] =>
      destruct (renew_seg nn cc ss ff) as [[body g2]|] eqn:EREN
  end.
  { cbv beta iota in HRun. injection HRun as <- <-.
    exact (renew_seg_margin32_probe (length ((og,3%N,1%N)::t))
      cols ((og,3%N,1%N)::t) f body g2 HMjoin2 HMs3 EREN). }
  cbv beta iota in HRun.
  match type of HRun with
  | context [fire_comp ?nn ?ss ?ff] =>
      destruct (fire_comp nn ss ff) as [[s2 g2]|] eqn:EFIRE
  end; [|discriminate].
  cbv beta iota in HRun. injection HRun as <- <-.
  apply shape_lmargin_app; [exact HMcols|].
  exact (fire_comp_margin32_probe (length ((og,3%N,1%N)::t))
    ((og,3%N,1%N)::t) f s2 g2 HMs3 EFIRE).
Qed.
Lemma round_at_after_seek_canon_probe : forall w cols s f out f',
  seek w = (cols,s) -> shape_rmargin 3 w ->
  round_at cols s f = Some (out,f') -> tag_z1canon out.
Proof.
  intros w cols s f out f' ESK HR HRun.
  pose proof (LineageGuard_seek_split w) as HSP.
  rewrite ESK in HSP. cbn [fst snd] in HSP.
  assert (HRcols3 : shape_rmargin 3 cols)
    by (exact (seek_fst_rmargin 3 w cols s ESK HR)).
  assert (HRs3 : shape_rmargin 3 s)
    by (exact (seek_snd_rmargin 3 w cols s ESK HR)).
  assert (HRcols1 : shape_rmargin1 cols).
  { apply shape_rmargin_to1. exact (shape_rmargin_weaken 3 1 cols
      ltac:(lia) HRcols3). }
  assert (HRs1 : shape_rmargin1 s).
  { apply shape_rmargin_to1. exact (shape_rmargin_weaken 3 1 s
      ltac:(lia) HRs3). }
  unfold round_at in HRun.
  destruct s as [|[[og zg] cg] t].
  { cbn [leaf_act] in HRun. discriminate. }
  assert (LEAF : forall s2 g2,
    leaf_act ((og,zg,cg)::t) f = Some (s2,g2) ->
    tag_z1canon (cols++s2)).
  { intros s2 g2 EL. apply tag_z1canon_app_left_rmargin1;
      [exact HRcols1|].
    apply tag_z1canon_of_rmargin1.
    exact (leaf_act_rmargin1_probe _ f s2 g2 HRs1 EL). }
  destruct zg as [|[z1|z1|]].
  { match type of HRun with
    | context [leaf_act ?ss ?ff] =>
        destruct (leaf_act ss ff) as [[s2 g2]|] eqn:EL
    end; [|discriminate]. cbv beta iota in HRun.
    injection HRun as <- <-. exact (LEAF s2 g2 EL). }
  2:{ match type of HRun with
    | context [leaf_act ?ss ?ff] =>
        destruct (leaf_act ss ff) as [[s2 g2]|] eqn:EL
    end; [|discriminate]. cbv beta iota in HRun.
    injection HRun as <- <-. exact (LEAF s2 g2 EL). }
  2:{ match type of HRun with
    | context [leaf_act ?ss ?ff] =>
        destruct (leaf_act ss ff) as [[s2 g2]|] eqn:EL
    end; [|discriminate]. cbv beta iota in HRun.
    injection HRun as <- <-. exact (LEAF s2 g2 EL). }
  destruct z1 as [z1|z1|].
  1,2: match type of HRun with
  | context [leaf_act ?ss ?ff] =>
      destruct (leaf_act ss ff) as [[s2 g2]|] eqn:EL
  end; [cbv beta iota in HRun; injection HRun as <- <-;
        exact (LEAF s2 g2 EL)|discriminate].
  destruct cg as [|[c1|c1|]].
  1,2,3: match type of HRun with
  | context [leaf_act ?ss ?ff] =>
      destruct (leaf_act ss ff) as [[s2 g2]|] eqn:EL
  end; [cbv beta iota in HRun; injection HRun as <- <-;
        exact (LEAF s2 g2 EL)|discriminate].
  match type of HRun with
  | context [renew_seg ?nn ?cc ?ss ?ff] =>
      destruct (renew_seg nn cc ss ff) as [[body g2]|] eqn:EREN
  end.
  { cbv beta iota in HRun. injection HRun as <- <-.
    apply (renew_seg_canon_probe (length ((og,3%N,1%N)::t))
      cols ((og,3%N,1%N)::t) f body g2).
    - exact (eq_ind w (fun x => shape_rmargin 3 x) HR _ HSP).
    - exact EREN. }
  cbv beta iota in HRun.
  match type of HRun with
  | context [fire_comp ?nn ?ss ?ff] =>
      destruct (fire_comp nn ss ff) as [[s2 g2]|] eqn:EFIRE
  end; [|discriminate].
  cbv beta iota in HRun. injection HRun as <- <-.
  apply tag_z1canon_app_left_rmargin1; [exact HRcols1|].
  exact (fire_comp_canon_probe (length ((og,3%N,1%N)::t))
    ((og,3%N,1%N)::t) f s2 g2 HRs3 EFIRE).
Qed.
Lemma lin_ptags_app_r_probe : forall sg a b,
  lin_ptags sg (a ++ b) = true ->
  lin_ptags sg b = true.
Proof.
  intros sg a. induction a as [|g a IH]; intros b H; [exact H|].
  cbn [app lin_ptags] in H.
  exact (IH b (proj2 (andb_prop _ _ H))).
Qed.
Lemma round1g_struct_pack_at_probe : forall sg pfx tail f t2 f2,
  sg_wf sg -> keys_big sg ->
  ph_margins sg (pfx ++ tail) ->
  ph_nbrs sg (pfx ++ tail) ->
  lin_ptags sg (pfx ++ tail) = true ->
  shape_lmargin 2 tail ->
  (forall g, nth_error tail O = Some g -> ph sg g = false) ->
  round1g tail f = Some (t2,f2) ->
  edge_pack t2 /\ shape_lmargin 2 t2 /\
  shape_nbrs1z t2 /\ tag_z1canon t2.
Proof.
  intros sg pfx tail f t2 f2 HW HK HM HN HT HMtail2 Hhead HRound.
  pose proof HRound as HRound0.
  pose proof (margins_shape_lmargin3_probe sg (pfx++tail) HM HT) as HL3.
  pose proof (margins_shape_rmargin3_probe sg (pfx++tail) HM HT) as HR3.
  assert (HTtail : lin_ptags sg tail = true)
    by (exact (lin_ptags_app_r_probe sg pfx tail HT)).
  assert (HNtail : ph_nbrs sg tail)
    by (exact (ph_nbrs_app_r sg pfx tail HN)).
  assert (HRtail3 : shape_rmargin 3 tail)
    by (exact (shape_rmargin_app_r 3 pfx tail HR3)).
  assert (HP : edge_pack tail).
  { split.
    - split.
      + exact (shape_head_free_of_lmargin_probe 2 tail ltac:(lia) HMtail2).
      + exact (tag_edges_of_nbrs1z sg tail
          (nbrs_nbrs1z sg tail HNtail) HTtail).
    - apply shape_notlast_of_rmargin1. apply shape_rmargin_to1.
      exact (shape_rmargin_weaken 3 1 tail ltac:(lia) HRtail3). }
  pose proof (shape_nbrs1z_of_live_probe sg tail
    (nbrs_nbrs1z sg tail HNtail) HTtail) as HNs.
  pose proof (tag_z1canon_of_rmargin1 tail
    (shape_rmargin_to1 tail
      (shape_rmargin_weaken 3 1 tail ltac:(lia) HRtail3))) as HC.
  unfold round1g in HRound.
  destruct (seek tail) as [cols s] eqn:ESK.
  assert (HMs3 : shape_lmargin 3 s).
  { destruct s as [|g t].
    - apply shape_lmargin_shape_free. unfold shape_free. intros x Hx.
      contradiction.
    - exact (seek_suffix_lmargin_ctx_probe 3 pfx tail cols g t ESK HL3). }
  assert (HP2 : edge_pack t2).
  { exact (round_at_after_seek_edges_probe tail cols s f t2 f2 ESK
      (shape_lmargin_weaken 3 2 s ltac:(lia) HMs3)
      HP HNs HC HRound). }
  assert (HM2 : shape_lmargin 2 t2).
  { exact (round_at_after_seek_margin_ctx_probe tail cols s f t2 f2 ESK
      HMtail2 HMs3 HRound). }
  assert (HC2 : tag_z1canon t2).
  { exact (round_at_after_seek_canon_probe tail cols s f t2 f2
      ESK HRtail3 HRound). }
  assert (HZ2 : zpack sg t2).
  { exact (round1g_zpack_at_probe sg pfx tail f t2 f2 HW HK
      HM HN Hhead HRound0). }
  assert (HPT2 : lin_ptags sg t2 = true).
  { exact (lin_ptags_of_phseq_eq sg tail t2
      (round1g_phseq_probe tail f t2 f2 HRound0) HTtail). }
  assert (HN2 : shape_nbrs1z t2).
  { exact (shape_nbrs1z_of_live_probe sg t2 (proj1 HZ2) HPT2). }
  exact (conj HP2 (conj HM2 (conj HN2 HC2))).
Qed.
Lemma round2g_edge_pack_at_probe : forall sg pfx tail f out f',
  sg_wf sg -> keys_big sg ->
  ph_margins sg (pfx ++ tail) ->
  ph_nbrs sg (pfx ++ tail) ->
  lin_ptags sg (pfx ++ tail) = true ->
  shape_lmargin 2 tail ->
  (forall g, nth_error tail O = Some g -> ph sg g = false) ->
  round2g tail f = Some (out,f') -> edge_pack out.
Proof.
  intros sg pfx tail f out f' HW HK HM HN HT HMtail Hhead HRun.
  unfold round2g in HRun.
  destruct (seek tail) as [cols s] eqn:ESK.
  destruct (round_at cols s f) as [[t2 f2]|] eqn:ER1;
    [|discriminate].
  assert (ERound1 : round1g tail f = Some (t2,f2)).
  { unfold round1g. rewrite ESK. exact ER1. }
  destruct (round1g_struct_pack_at_probe sg pfx tail f t2 f2
    HW HK HM HN HT HMtail Hhead ERound1)
    as (HP2 & HM2 & HN2 & HC2).
  destruct (seek t2) as [cols2 s2] eqn:ESK2.
  pose proof (LineageGuard_seek_split t2) as HSP2.
  rewrite ESK2 in HSP2. cbn [fst snd] in HSP2.
  destruct s2 as [|g2 s2t].
  - assert (HPcols2 : edge_pack cols2).
    { rewrite app_nil_r in HSP2.
      exact (eq_ind t2 (fun w => edge_pack w) HP2 cols2 HSP2). }
    destruct (f2 =? 4)%N.
    + destruct (dtb4_conv cols2) as [cols2'|] eqn:EDC;
        [|discriminate].
      cbv beta iota in HRun. injection HRun as <- <-.
      exact (dtb4_conv_edge_pack_probe cols2 cols2' HPcols2 EDC).
    + destruct (5 <=? f2)%N; [|discriminate].
      cbv beta iota in HRun. injection HRun as <- <-.
      apply edge_pack_app; [exact HPcols2|].
      apply edge_pack_shape_free_probe. unfold shape_free. shape_lits_probe.
  - assert (HMs2 : shape_lmargin 2 (g2::s2t)).
    { exact (seek_suffix_lmargin 2 t2 cols2 g2 s2t ESK2 HM2). }
    exact (round_at_after_seek_edges_probe t2 cols2 (g2::s2t)
      f2 out f' ESK2 HMs2 HP2 HN2 HC2 HRun).
Qed.
Lemma round2g_pre8_edge_pack_at_probe : forall sg pfx tail f cols2,
  sg_wf sg -> keys_big sg ->
  ph_margins sg (pfx ++ tail) ->
  ph_nbrs sg (pfx ++ tail) ->
  lin_ptags sg (pfx ++ tail) = true ->
  shape_lmargin 2 tail ->
  (forall g, nth_error tail O = Some g -> ph sg g = false) ->
  round2g_pre8 tail f = Some cols2 -> edge_pack cols2.
Proof.
  intros sg pfx tail f cols2 HW HK HM HN HT HMtail Hhead HRun.
  unfold round2g_pre8 in HRun.
  destruct (seek tail) as [cols s] eqn:ESK.
  destruct (round_at cols s f) as [[t2 f2]|] eqn:ER1;
    [|discriminate].
  assert (ERound1 : round1g tail f = Some (t2,f2)).
  { unfold round1g. rewrite ESK. exact ER1. }
  destruct (round1g_struct_pack_at_probe sg pfx tail f t2 f2
    HW HK HM HN HT HMtail Hhead ERound1) as (HP2 & _).
  destruct (seek t2) as [cols3 s2] eqn:ESK2.
  pose proof (LineageGuard_seek_split t2) as HSP2.
  rewrite ESK2 in HSP2. cbn [fst snd] in HSP2.
  destruct s2 as [|g2 s2t]; [|discriminate].
  cbv beta iota in HRun.
  destruct ((f2 =? 4) && forallb w42 cols3)%N; [|discriminate].
  destruct (dtb4_conv cols3); [discriminate|].
  injection HRun as <-.
  rewrite app_nil_r in HSP2.
  exact (eq_ind t2 (fun w => edge_pack w) HP2 cols3 HSP2).
Qed.
Open Scope N_scope.
Open Scope bool_scope.
Opaque LROUND_FUEL LROUND_CHUNKS
       FLAT_ROUND_FUEL CFUEL TRIES.
Lemma shape_free_of_phseq_nil_probe : forall w,
  phseq w = [] -> shape_free w.
Proof.
  induction w as [|g t IH]; intros HP x Hx; [contradiction|].
  cbn [phseq] in HP.
  destruct (phshape g) eqn:HG.
  - discriminate.
  - destruct Hx as [<-|Hx]; [exact HG|].
    exact (IH HP x Hx).
Qed.
Lemma fr_span2B_edges_probe : forall sg w f w2 f2,
  sg_wf sg -> keys_big sg ->
  ph_margins sg w -> ph_nbrs sg w ->
  lin_ptags sg w = true ->
  fr_span2B w f = Some (ROk w2 f2) ->
  tag_edges w2.
Proof.
  intros sg w f w2 f2 HW HK HM HN HT H.
  destruct (fr_span2B_view_of w f w2 f2 H)
    as [c_0 c2 c4 c6 rest ff t3 f3 ER].
  assert (HL3 : shape_lmargin 3
      ((2%N,2%N,c_0)::(5%N,2%N,1%N)::(3%N,2%N,c2)::
       (2%N,2%N,1%N)::(4%N,2%N,c4)::(4%N,3%N,1%N)::
       (4%N,2%N,c6)::rest)).
  try solve
    [exact (margins_shape_lmargin3_probe sg _ HM HT)].
  assert (HMsuf : shape_lmargin 3
      ((4%N,3%N,1%N)::(4%N,2%N,c6)::rest)).
  try solve
    [apply (shape_lmargin_suffix_noncasc 3
       [(2%N,2%N,c_0);(5%N,2%N,1%N);(3%N,2%N,c2);
        (2%N,2%N,1%N);(4%N,2%N,c4)]
       (4%N,3%N,1%N) ((4%N,2%N,c6)::rest));
     [cbn [app]; exact HL3
     |apply z31_noncasc
     |apply phshape_znot2; reflexivity]].
  assert (HMrest : shape_lmargin 2 rest).
  try solve
    [exact (shape_lmargin_after_noncasc_drop32_probe
       (4%N,3%N,1%N) (4%N,2%N,c6) rest HMsuf
       (z31_noncasc 4%N))].
  assert (Hhead : forall g, nth_error rest O = Some g ->
      ph sg g = false).
  try solve
    [intros g Hg;
     apply (margins_win_excl sg _ 7%nat 5%nat g
       (4%N,3%N,1%N) HM);
     [cbn [nth_error]; exact Hg|reflexivity|reflexivity|lia|lia]].
  pose proof (round2g_edge_pack_at_probe sg
      [(2%N,2%N,c_0);(5%N,2%N,1%N);(3%N,2%N,c2);
       (2%N,2%N,1%N);(4%N,2%N,c4);(4%N,3%N,1%N);
       (4%N,2%N,c6)] rest ff t3 f3 HW HK
      ltac:(cbn [app]; exact HM) ltac:(cbn [app]; exact HN)
      ltac:(cbn [app]; exact HT) HMrest Hhead ER) as HPout.
  change (tag_edges
      ([(2%N,2%N,c_0+1);(4%N,1%N,1%N);(3%N,1%N,1%N);
        (4%N,1%N,c2-1);(5%N,1%N,1%N);(3%N,2%N,1%N);
        (4%N,2%N,c4);(8%N,2%N,1%N);(4%N,2%N,c6-1)] ++ t3)).
  apply tag_edges_shape_free_app_probe.
  - unfold shape_free; shape_lits_probe.
  - exact (proj1 (proj1 HPout)).
  - exact (proj2 (proj1 HPout)).
Qed.
Lemma fr_span8_edges_probe : forall sg w f w2 f2,
  sg_wf sg -> keys_big sg ->
  ph_margins sg w -> ph_nbrs sg w ->
  lin_ptags sg w = true ->
  fr_span8 w f = Some (ROk w2 f2) ->
  tag_edges w2.
Proof.
  intros sg w f w2 f2 HW HK HM HN HT H.
  destruct w as [|[[o0 z0] c_0] [|[[o1 z1] c1]
    [|[[o2 z2] c2] [|[[o3 z3] c3] rest]]]]; try discriminate.
  all: cbn [fr_span8] in H; digs_probe H; try discriminate.
  all: destruct rest as [|gh rest].
  - pose proof (fr_span8_phseq_probe
      [(2,2,c_0); (4,2,c1); (4,3,1); (4,2,c3)] f w2 f2 H) as HPS.
    apply tag_edges_shape_free_probe.
    apply shape_free_of_phseq_nil_probe. rewrite HPS.
    phseq_lits_probe.
  - destruct (fr_span8_nonempty_view_of c_0 c1 c3 gh rest f w2 f2 H)
      as [t3 f3 ER|cols2 ER EP].
    all: assert (HL3 : shape_lmargin 3
        ((2%N,2%N,c_0)::(4%N,2%N,c1)::(4%N,3%N,1%N)::
         (4%N,2%N,c3)::gh::rest)).
    all: try solve [exact (margins_shape_lmargin3_probe sg _ HM HT)].
    all: assert (HMsuf : shape_lmargin 3
        ((4%N,3%N,1%N)::(4%N,2%N,c3)::gh::rest)).
    all: try solve
      [apply (shape_lmargin_suffix_noncasc 3
        [(2%N,2%N,c_0);(4%N,2%N,c1)]
        (4%N,3%N,1%N) ((4%N,2%N,c3)::gh::rest));
       [cbn [app]; exact HL3
       |apply z31_noncasc
       |apply phshape_znot2; reflexivity]].
    all: assert (HMrest : shape_lmargin 2 (gh::rest)).
    all: try solve
      [exact (shape_lmargin_after_noncasc_drop32_probe
        (4%N,3%N,1%N) (4%N,2%N,c3) (gh::rest) HMsuf
        (z31_noncasc 4%N))].
    all: assert (Hhead : forall x, nth_error (gh::rest) O = Some x ->
        ph sg x = false).
    all: try solve
      [intros x Hx;
       apply (margins_win_excl sg _ 4%nat 2%nat x
        (4%N,3%N,1%N) HM);
       [cbn [nth_error]; exact Hx|reflexivity|reflexivity|lia|lia]].
    +
      pose proof (round2g_edge_pack_at_probe sg
        [(2%N,2%N,c_0);(4%N,2%N,c1);(4%N,3%N,1%N);
         (4%N,2%N,c3)] (gh::rest) f t3 f3 HW HK
        ltac:(cbn [app]; exact HM) ltac:(cbn [app]; exact HN)
        ltac:(cbn [app]; exact HT) HMrest Hhead ER) as HPout.
      change (tag_edges
        ([(5%N,1%N,1%N);(4%N,1%N,1%N);(3%N,1%N,c_0-2);
          (2%N,2%N,1%N);(4%N,2%N,c1);(8%N,2%N,1%N);
          (4%N,2%N,c3-1)] ++ t3)).
      apply tag_edges_shape_free_app_probe.
      * unfold shape_free. shape_lits_probe.
      * exact (proj1 (proj1 HPout)).
      * exact (proj2 (proj1 HPout)).
    +
      pose proof (round2g_pre8_edge_pack_at_probe sg
        [(2%N,2%N,c_0);(4%N,2%N,c1);(4%N,3%N,1%N);
         (4%N,2%N,c3)] (gh::rest) f cols2 HW HK
        ltac:(cbn [app]; exact HM) ltac:(cbn [app]; exact HN)
        ltac:(cbn [app]; exact HT) HMrest Hhead EP) as HPout.
      change (tag_edges
        ([(5%N,1%N,1%N);(4%N,1%N,1%N);(3%N,1%N,c_0-2);
          (2%N,2%N,1%N);(4%N,2%N,c1);(7%N,1%N,1%N);
          (3%N,2%N,1%N);(4%N,2%N,c3-1)] ++ cols2)).
      apply tag_edges_shape_free_app_probe.
      * unfold shape_free. shape_lits_probe.
      * exact (proj1 (proj1 HPout)).
      * exact (proj2 (proj1 HPout)).
Qed.
Lemma first_rule_front_edges : forall sg w f w2 f2,
  sg_wf sg -> keys_big sg ->
  ph_margins sg w -> ph_nbrs sg w ->
  lin_ptags sg w = true -> tag_edges w ->
  first_rule front_rules w f = Some (ROk w2 f2) ->
  tag_edges w2.
Proof.
  intros sg w f w2 f2 HW HK HM HN HT HE H.
  cbn [front_rules first_rule] in H.
  destruct (fr_primordial w f) as [r|] eqn:E1.
  { injection H as ->. exact (fr_primordial_edges_probe _ _ _ _ E1). }
  destruct (fr_prim4 w f) as [r|] eqn:E2.
  { injection H as ->. exact (fr_prim4_edges_probe _ _ _ _ E2). }
  destruct (fr_clean w f) as [r|] eqn:E3.
  { injection H as ->. exact (fr_clean_edges_probe _ _ _ _ E3 HE). }
  destruct (fr_four w f) as [r|] eqn:E4.
  { injection H as ->. exact (fr_four_edges_probe _ _ _ _ E4 HE). }
  destruct (fr_span2A w f) as [r|] eqn:E5.
  { injection H as ->.
    exact (fr_span2A_edges_probe sg _ _ _ _ HW HK HM HN HT E5). }
  destruct (fr_span2A' w f) as [r|] eqn:E6.
  { injection H as ->. exact (fr_span2A'_edges_probe _ _ _ _ E6). }
  destruct (fr_span2C' w f) as [r|] eqn:E7.
  { injection H as ->. exact (fr_span2C'_edges_probe _ _ _ _ E7). }
  destruct (fr_span8far w f) as [r|] eqn:E8.
  { injection H as ->. exact (fr_span8far_edges_probe _ _ _ _ E8). }
  destruct (fr_span2B w f) as [r|] eqn:E9.
  { injection H as ->.
    exact (fr_span2B_edges_probe sg _ _ _ _ HW HK HM HN HT E9). }
  destruct (fr_span8orph w f) as [r|] eqn:E10.
  { injection H as ->.
    exact (fr_span8orph_edges_probe sg _ _ _ _ HW HK HM HN HT E10). }
  destruct (fr_span8 w f) as [r|] eqn:E11.
  { injection H as ->.
    exact (fr_span8_edges_probe sg _ _ _ _ HW HK HM HN HT E11). }
  destruct (fr_rot w f) as [r|] eqn:E12.
  { injection H as ->. exact (fr_rot_edges_probe _ _ _ _ E12 HE). }
  destruct (fr_502 w f) as [r|] eqn:E13.
  { injection H as ->. exact (fr_502_edges_probe _ _ _ _ E13 HE). }
  destruct (fr_512 w f) as [r|] eqn:E14.
  { injection H as ->. exact (fr_512_edges_probe _ _ _ _ E14 HE). }
  destruct (fr_522 w f) as [r|] eqn:E15.
  { injection H as ->. exact (fr_522_edges_probe _ _ _ _ E15 HE). }
  discriminate.
Qed.
Lemma front_gate_edges : forall sg w f w2 f2,
  sg_wf sg -> keys_big sg ->
  ph_margins sg w -> ph_nbrs sg w ->
  lin_ptags sg w = true -> tag_edges w ->
  front_gate w f = Some (ROk w2 f2) ->
  tag_edges w2.
Proof.
  intros sg w f w2 f2 HW HK HM HN HT HE H.
  unfold front_gate in H.
  destruct (lin_front_possible w); [|discriminate].
  exact (first_rule_front_edges sg w f w2 f2 HW HK HM HN HT HE H).
Qed.
Open Scope N_scope.
Open Scope bool_scope.
Opaque LROUND_FUEL LROUND_CHUNKS
       FLAT_ROUND_FUEL CFUEL TRIES.
Definition site_raw (k : ckind) (pre body : word) : word :=
  match k with STD => pre ++ body | JMP => body end.
Definition site_out (sg : list seg) (k : ckind)
    (pre body : word) (i : nat) : word :=
  match k with
  | STD => lin_normalize_join sg pre body
  | JMP => lin_normalize_at sg body i
  end.
Lemma site_raw_phseq_probe : forall w i f k body f2,
  site_comp w i f = Some (k, body, f2) ->
  phseq (site_raw k (firstn i w) body) =
  phseq w.
Proof.
  intros w i f k body f2 HC. destruct k.
  - unfold site_raw. rewrite phseq_app.
    rewrite (site_comp_std_phseq w i f body f2 HC).
    symmetry. apply cut_phseq.
  - unfold site_raw.
    exact (site_comp_jmp_phseq w i f body f2 HC).
Qed.
Lemma site_raw_zpack_probe : forall sg w i f k body f2,
  sg_wf sg -> keys_big sg ->
  ph_margins sg w -> ph_nbrs sg w ->
  site_comp w i f = Some (k, body, f2) ->
  zpack sg (site_raw k (firstn i w) body).
Proof.
  intros sg w i f k body f2 HW HK HM HN HC.
  pose proof (site_comp_out_tag sg w i f k body f2
    HW HK HM HN HC) as HB.
  destruct k; [|exact HB].
  destruct (site_comp_head sg w i f STD body f2 HC)
    as (g & u & ES & Hph & Hcasc & Hnotag).
  unfold site_raw.
  apply zpack_zspack_app; [|exact HB].
  exact (firstn_zspack_of_site sg w i g u HM HN ES Hcasc).
Qed.
Lemma site_out_repr_probe : forall sg w i f k body f2,
  front_repr sg w ->
  sg_wf sg -> keys_big sg ->
  ph_margins sg w -> ph_nbrs sg w ->
  site_comp w i f = Some (k, body, f2) ->
  front_repr sg (site_out sg k (firstn i w) body i) /\
  tag_edges (site_out sg k (firstn i w) body i).
Proof.
  intros sg w i f k body f2 (HOk & HPT) HW HK HM HN HC.
  pose proof (site_raw_phseq_probe w i f k body f2 HC) as ERaw.
  pose proof (site_raw_zpack_probe sg w i f k body f2 HW HK HM HN HC)
    as HZ.
  assert (HPTRaw : lin_ptags sg
      (site_raw k (firstn i w) body) = true).
  { exact (lin_ptags_of_phseq_eq sg w _ ERaw HPT). }
  assert (HERaw : tag_edges
      (site_raw k (firstn i w) body)).
  { exact (tag_edges_of_nbrs1z sg _ (proj1 HZ) HPTRaw). }
  assert (EOut : phseq
      (site_out sg k (firstn i w) body i) = phseq w).
  { destruct k.
    - unfold site_out. rewrite phseq_lin_normalize_join.
      exact ERaw.
    - unfold site_out. rewrite phseq_lin_normalize_at.
      exact ERaw. }
  split.
  - split.
    + exact (lin_ok_of_phseq_eq sg w _ EOut HOk).
    + exact (lin_ptags_of_phseq_eq sg w _ EOut HPT).
  - destruct k.
    + unfold site_out, site_raw in *.
      exact (tag_edges_normalize_join sg _ _ HERaw).
    + unfold site_out, site_raw in *.
      exact (tag_edges_normalize_at sg _ i HERaw).
Qed.
Lemma leaf_join_out_repr_probe : forall sg w i g u f sfx f2,
  front_repr sg w ->
  sg_wf sg -> keys_big sg ->
  ph_margins sg w -> ph_nbrs sg w ->
  skipn i w = g :: u -> casc g = false ->
  notag g = true ->
  leaf_act (skipn i w) f = Some (sfx, f2) ->
  front_repr sg
    (lin_normalize_join sg (firstn i w) sfx) /\
  tag_edges
    (lin_normalize_join sg (firstn i w) sfx).
Proof.
  intros sg w i g u f sfx f2 (HOk & HPT) HW HK HM HN
    ES HC HNT ELeaf.
  assert (HMs : ph_margins sg (skipn i w)).
  { rewrite ES. exact (margins_cut_at sg w (firstn i w)
      g u HM ltac:(rewrite <- ES; symmetry; apply firstn_skipn) HC HNT). }
  assert (HNs : ph_nbrs sg (skipn i w)).
  { apply (ph_nbrs_app_r sg (firstn i w)).
    rewrite firstn_skipn. exact HN. }
  pose proof (leaf_npack_out_tag sg (skipn i w) f sfx f2
    HW HK HMs HNs ELeaf) as HLeaf.
  pose proof (firstn_zspack_of_site sg w i g u HM HN ES HC)
    as HPre.
  pose proof (zpack_zspack_app sg (firstn i w) sfx HPre
    (zpack_of_npack sg sfx HLeaf)) as HRawZ.
  assert (ERaw : phseq (firstn i w ++ sfx) =
      phseq w).
  { rewrite phseq_app,
      (leaf_act_phseq (skipn i w) f sfx f2 ELeaf).
    symmetry. apply cut_phseq. }
  assert (HPTRaw : lin_ptags sg (firstn i w ++ sfx) = true).
  { exact (lin_ptags_of_phseq_eq sg w _ ERaw HPT). }
  assert (HERaw : tag_edges (firstn i w ++ sfx)).
  { exact (tag_edges_of_nbrs1z sg _ (proj1 HRawZ) HPTRaw). }
  assert (EOut : phseq
      (lin_normalize_join sg (firstn i w) sfx) =
      phseq w).
  { rewrite phseq_lin_normalize_join. exact ERaw. }
  split.
  - split.
    + exact (lin_ok_of_phseq_eq sg w _ EOut HOk).
    + exact (lin_ptags_of_phseq_eq sg w _ EOut HPT).
  - exact (tag_edges_normalize_join sg _ _ HERaw).
Qed.
Lemma master_phseq_change_probe : forall A B t,
  phseq ((2,2,A) :: t) =
  phseq ((2,2,B) :: t).
Proof.
  intros A B t. cbn [phseq].
  rewrite !phshape_onot9 by reflexivity. reflexivity.
Qed.
Lemma master_edges_change_probe : forall A B t,
  tag_edges ((2,2,A) :: t) ->
  tag_edges ((2,2,B) :: t).
Proof.
  intros A B [|x t] HE; [exact I|].
  cbn [tag_edges] in HE |- *.
  destruct HE as ([HR HL] & HE). split; [split|exact HE].
  - intros HP. rewrite phshape_onot9 in HP by reflexivity.
    discriminate.
  - intros HP. exfalso. destruct (HL HP) as [HO _].
    cbn [gO] in HO. discriminate.
Qed.
Lemma front_repr_master_change_probe : forall sg A B t,
  front_repr sg ((2,2,A) :: t) ->
  front_repr sg ((2,2,B) :: t).
Proof.
  intros sg A B t (HOk & HPT). split.
  - exact (lin_ok_of_phseq_eq sg ((2,2,A)::t)
      ((2,2,B)::t) (eq_sym (master_phseq_change_probe A B t)) HOk).
  - exact (lin_ptags_of_phseq_eq sg ((2,2,A)::t)
      ((2,2,B)::t) (eq_sym (master_phseq_change_probe A B t)) HPT).
Qed.
Lemma stable_guard_master_change_probe : forall sg A B t,
  stable_guard sg ((2,2,A) :: t) ->
  stable_guard sg ((2,2,B) :: t).
Proof.
  intros sg A B t (HR & HE & HW & HS & HK & HP).
  split.
  - exact (front_repr_master_change_probe sg A B t HR).
  - split; [exact (master_edges_change_probe A B t HE)|].
    split; [exact HW|]. split; [exact HS|]. split; assumption.
Qed.
Lemma splice_none_direct_stable_probe :
  forall sg J t f h s i cw2 f2 ir,
  stable_guard sg ((2,2,J) :: t) ->
  lin_guard sg ((2,2,J) :: t) = true ->
  front_gate ((2,2,J) :: t) f = None ->
  s = (if Nat.ltb h 1 then 1%nat else h) ->
  find_active ((2,2,J) :: t) s = Some i ->
  splice_call sg None ((2,2,J) :: t) f h
    = (ROk cw2 f2, ir) ->
  sound_impl (lin_flat sg ((2,2,J) :: t)) f
    (lin_flat sg cw2) f2 /\
  stable_guard sg cw2.
Proof.
  intros sg J t f h s i cw2 f2 ir HG HGuard HFG ES HFA HRun.
  destruct HG as ((HOk & HPT) & HE & HW & HShape & HK & HP).
  assert (HM : ph_margins sg ((2,2,J)::t))
    by (exact (lguard_margins sg _ HGuard)).
  assert (HN : ph_nbrs sg ((2,2,J)::t))
    by (exact (margins_edges_nbrs sg _ HM HE)).
  assert (HL : sg_live sg)
    by (exact (sg_shape_live sg HW HShape)).
  assert (HSound : sound_impl
      (lin_flat sg ((2,2,J)::t)) f
      (lin_flat sg cw2) f2).
  { exact (splice_none_direct_sound sg J t f h s i
      cw2 f2 ir HW HK HL HP HM HN HFG ES HFA HRun). }
  destruct (splice_none_direct_inv
    sg J t f h s i cw2 f2 ir ES HFA HRun)
    as (k & body & HJ & HS & HCols & HLast & HComp & -> & ->).
  assert (HG0 : stable_guard sg ((2,2,J)::t))
    by (repeat split; assumption).
  assert (HG1 : stable_guard sg ((2,2,J+1)::t)).
  { exact (stable_guard_master_change_probe sg J (J+1) t HG0). }
  destruct HG1 as (HR1 & HE1 & HW1 & HShape1 & HK1 & HP1).
  assert (HM1 : ph_margins sg ((2,2,J+1)::t))
    by (exact (margins_master_change sg J (J+1) t HM)).
  assert (HN1 : ph_nbrs sg ((2,2,J+1)::t))
    by (exact (margins_edges_nbrs sg _ HM1 HE1)).
  destruct (site_out_repr_probe sg ((2,2,J+1)::t) i f k body f2
    HR1 HW1 HK1 HM1 HN1 HComp) as (HROut & HEOut).
  split; [exact HSound|].
  split; [exact HROut|]. split; [exact HEOut|].
  split; [exact HW1|]. split; [exact HShape1|]. split; assumption.
Qed.
Lemma splice_none_fallback_stable_probe :
  forall sg J t f h s cw2 f2 ir,
  stable_guard sg ((2,2,J) :: t) ->
  lin_guard sg ((2,2,J) :: t) = true ->
  front_gate ((2,2,J) :: t) f = None ->
  s = (if Nat.ltb h 1 then 1%nat else h) ->
  find_active ((2,2,J) :: t) s = None ->
  splice_call sg None ((2,2,J) :: t) f h
    = (ROk cw2 f2, ir) ->
  sound_impl (lin_flat sg ((2,2,J) :: t)) f
    (lin_flat sg cw2) f2 /\
  stable_guard sg cw2.
Proof.
  intros sg J t f h s cw2 f2 ir HG HGuard HFG ES HFA HRun.
  destruct HG as ((HOk & HPT) & HE & HW & HShape & HK & HP).
  assert (HM : ph_margins sg ((2,2,J)::t))
    by (exact (lguard_margins sg _ HGuard)).
  assert (HN : ph_nbrs sg ((2,2,J)::t))
    by (exact (margins_edges_nbrs sg _ HM HE)).
  assert (HL : sg_live sg)
    by (exact (sg_shape_live sg HW HShape)).
  assert (HSound : sound_impl
      (lin_flat sg ((2,2,J)::t)) f
      (lin_flat sg cw2) f2).
  { exact (splice_none_fallback_sound sg J t f h s
      cw2 f2 ir HW HK HL HM HN HFG ES HFA HRun). }
  destruct (splice_none_fallback_inv
    sg J t f h s cw2 f2 ir ES HFA HRun)
    as (j & sfx & HJ & ECMF & HCols & ELeaf & -> & ->).
  destruct (cmf_from_inv _ _ _ _ ECMF)
    as (Hstart & g & Hwat & Hcmf).
  assert (Hj : (1 <= j)%nat).
  { eapply PeanoNat.Nat.le_trans; [|exact Hstart].
    apply PeanoNat.Nat.le_max_l. }
  assert (Es0 : exists u, skipn j ((2,2,J) :: t) = g :: u).
  { unfold wat in Hwat.
    assert (E0 : nth_error (skipn j ((2,2,J)::t)) O = Some g).
    { rewrite nth_skipn, PeanoNat.Nat.add_0_r. exact Hwat. }
    destruct (skipn j ((2,2,J)::t)) as [|g0 u] eqn:ESk.
    - discriminate E0.
    - cbn [nth_error] in E0. injection E0 as <-. exists u. reflexivity. }
  destruct Es0 as (u & Es0).
  assert (Es1 : skipn j ((2,2,J+1)::t) = g :: u).
  { rewrite <- (skipn_master_change J (J+1) t j Hj).
    exact Es0. }
  assert (HC : casc g = false).
  { destruct (casc g) eqn:EC; [|reflexivity].
    rewrite (casc_not_cmf g EC) in Hcmf. discriminate. }
  assert (HNT : notag g = true)
    by (exact (cmf_notag g Hcmf)).
  assert (HG0 : stable_guard sg ((2,2,J)::t))
    by (repeat split; assumption).
  assert (HG1 : stable_guard sg ((2,2,J+1)::t)).
  { exact (stable_guard_master_change_probe sg J (J+1) t HG0). }
  destruct HG1 as (HR1 & HE1 & HW1 & HShape1 & HK1 & HP1).
  assert (HM1 : ph_margins sg ((2,2,J+1)::t))
    by (exact (margins_master_change sg J (J+1) t HM)).
  assert (HN1 : ph_nbrs sg ((2,2,J+1)::t))
    by (exact (margins_edges_nbrs sg _ HM1 HE1)).
  destruct (leaf_join_out_repr_probe sg ((2,2,J+1)::t) j g u f sfx f2
    HR1 HW1 HK1 HM1 HN1 Es1 HC HNT ELeaf) as (HROut & HEOut).
  split; [exact HSound|].
  split; [exact HROut|]. split; [exact HEOut|].
  split; [exact HW1|]. split; [exact HShape1|]. split; assumption.
Qed.
Lemma splice_none_stable_probe : forall sg cw f h cw2 f2 i,
  stable_guard sg cw ->
  lin_guard sg cw = true ->
  front_gate cw f = None ->
  splice_call sg None cw f h = (ROk cw2 f2, i) ->
  sound_impl (lin_flat sg cw) f
    (lin_flat sg cw2) f2 /\
  stable_guard sg cw2.
Proof.
  intros sg cw f h cw2 f2 i HG HGuard HFG HRun.
  destruct (splice_none_rok_master sg cw f h cw2 f2 i
    HRun) as (J & t & -> & HJ).
  set (s := if Nat.ltb h 1 then 1%nat else h).
  destruct (find_active ((2,2,J)::t) s) as [j|] eqn:EFA.
  - exact (splice_none_direct_stable_probe sg J t f h s j cw2 f2 i HG
      HGuard HFG eq_refl EFA HRun).
  - exact (splice_none_fallback_stable_probe sg J t f h s cw2 f2 i HG
      HGuard HFG eq_refl EFA HRun).
Qed.
Lemma splice_front_stable : forall sg cw f h fw ff cw2 f2 i,
  stable_guard sg cw ->
  lin_guard sg cw = true ->
  front_gate cw f = Some (ROk fw ff) ->
  splice_call sg (front_gate cw f) cw f h
    = (ROk cw2 f2, i) ->
  sound_impl (lin_flat sg cw) f
    (lin_flat sg cw2) f2 /\
  stable_guard sg cw2.
Proof.
  intros sg cw f h fw ff cw2 f2 i HG HGuard HFG HRun.
  destruct HG as ((HOk & HPT) & HE & HW & HShape & HK & HP).
  assert (HM : ph_margins sg cw)
    by (exact (lguard_margins sg cw HGuard)).
  assert (HN : ph_nbrs sg cw)
    by (exact (margins_edges_nbrs sg cw HM HE)).
  assert (HL : sg_live sg)
    by (exact (sg_shape_live sg HW HShape)).
  assert (HSound : sound_impl (lin_flat sg cw) f
      (lin_flat sg cw2) f2).
  { exact (splice_checked_sound sg cw f h cw2 f2 i
      HW HK HL HP HM HN HRun). }
  assert (EFront : phseq fw = phseq cw).
  { exact (front_gate_phseq_probe cw f fw ff HFG). }
  assert (HEFront : tag_edges fw).
  { exact (front_gate_edges sg cw f fw ff HW HK HM HN HPT HE HFG). }
  unfold splice_call, step_after_front_with_guard in HRun.
  rewrite HFG in HRun. cbv beta iota in HRun.
  injection HRun as <- <- <-.
  assert (EOut : phseq
      (lin_normalize_at sg fw O) = phseq cw).
  { rewrite phseq_lin_normalize_at. exact EFront. }
  split; [exact HSound|].
  split.
  - split.
    + exact (lin_ok_of_phseq_eq sg cw _ EOut HOk).
    + exact (lin_ptags_of_phseq_eq sg cw _ EOut HPT).
  - split.
    + exact (tag_edges_normalize_at sg fw O HEFront).
    + split; [exact HW|]. split; [exact HShape|]. split; assumption.
Qed.
Lemma splice_stable : forall sg cw f h cw2 f2 i,
  stable_guard sg cw ->
  lin_guard sg cw = true ->
  splice_call sg (front_gate cw f) cw f h
    = (ROk cw2 f2, i) ->
  sound_impl (lin_flat sg cw) f
    (lin_flat sg cw2) f2 /\
  stable_guard sg cw2.
Proof.
  intros sg cw f h cw2 f2 i HG HGuard HRun.
  destruct (front_gate cw f) as [r|] eqn:HFG.
  - destruct r as [fw ff| |].
    + apply (splice_front_stable sg cw f h fw ff cw2 f2 i
        HG HGuard HFG).
      rewrite HFG. exact HRun.
    + unfold splice_call,
        step_after_front_with_guard in HRun.
      discriminate.
    + unfold splice_call,
        step_after_front_with_guard in HRun.
      discriminate.
  - exact (splice_none_stable_probe sg cw f h cw2 f2 i
      HG HGuard HFG HRun).
Qed.
Open Scope list.
Opaque LROUND_FUEL LROUND_CHUNKS
       FLAT_ROUND_FUEL CFUEL TRIES.
Definition rung1 (c : N) : word := [(8,2,1)%N; (4,2,c)%N].
Fixpoint runway (cs : list N) : word :=
  match cs with
  | [] => []
  | c :: cs' => rung1 c ++ runway cs'
  end.
Definition dec4 (c : N) : N := (c - 4)%N.
Definition crossed_post (cs : list N) (b : N) (post : word)
  : word := runway (List.map dec4 cs) ++ rung1 (b - 1)%N ++ post.
Lemma runway_app (a b : list N) : runway (a ++ b) = runway a ++ runway b.
Proof.
  induction a as [|c a IH]; cbn [runway app]; [reflexivity|].
  now rewrite IH, app_assoc.
Qed.
Lemma length_runway (cs : list N) : length (runway cs) = (2 * length cs)%nat.
Proof.
  induction cs as [|c cs IH]; [reflexivity|].
  cbn [runway length]. rewrite length_app, IH. cbn [rung1 length]. lia.
Qed.
Lemma map_adj4_rung1 (c : N) :
  List.map adj4 (rung1 c) = rung1 (dec4 c).
Proof. reflexivity. Qed.
Lemma map_adj4_runway (cs : list N) :
  List.map adj4 (runway cs) = runway (List.map dec4 cs).
Proof.
  induction cs as [|c cs IH]; [reflexivity|].
  cbn [runway map]. rewrite map_app, map_adj4_rung1, IH. reflexivity.
Qed.
Lemma wat_at_app (pre post : word) (g : bg) :
  wat (pre ++ g :: post) (length pre) = Some g.
Proof. unfold wat. apply nth_pre. Qed.
Lemma wat_app_shift (pre w : word) (k : nat) :
  wat (pre ++ w) (length pre + k) = wat w k.
Proof.
  unfold wat. rewrite nth_error_app2 by lia.
  now replace (length pre + k - length pre)%nat with k by lia.
Qed.
Lemma clean_above_runway : forall (cs : list N) (pre suffix : word),
  Forall (fun x => (FLOOR <= x)%N) cs ->
  clean_above (pre ++ runway cs ++ suffix)
    (length pre + 2 * length cs - 1) (length cs) = true.
Proof.
  induction cs as [|c cs IH] using rev_ind; intros pre suffix Hall;
    [reflexivity|].
  rewrite Forall_app in Hall. destruct Hall as [Hall Hc].
  inversion Hc as [|y ys Hy _]; subst y ys.
  rewrite runway_app. cbn [runway rung1 app].
  rewrite length_app. cbn [length].
  rewrite <- !app_assoc. cbn [app].
  rewrite (app_assoc pre (runway cs)).
  set (A := pre ++ runway cs).
  assert (HA : length A = (length pre + 2 * length cs)%nat)
    by (unfold A; rewrite length_app, length_runway; lia).
  replace (length pre + 2 * (length cs + 1) - 1)%nat
    with (length A + 1)%nat by lia.
  replace (length cs + 1)%nat with (S (length cs)) by lia.
  cbn [clean_above].
  replace (Nat.ltb (length A + 1) 1) with false
    by (symmetry; apply PeanoNat.Nat.ltb_ge; lia).
  rewrite (wat_app_shift A _ 1).
  replace (length A + 1 - 1)%nat with (length A + 0)%nat by lia.
  rewrite (wat_app_shift A _ 0).
  cbn [wat nth_error].
  rewrite (lvl_big_intro c) by exact Hy.
  cbn [spacer gO gZ gC andb].
  replace (length A + 1 - 2)%nat with (length pre + 2 * length cs - 1)%nat
    by lia.
  unfold A. rewrite <- app_assoc.
  now apply IH.
Qed.
Lemma firstn_runway_slice (c : N) (cs : list N) (pre suffix : word) :
  firstn (2 * length (c::cs) - 1)
    (skipn (S (length pre)) (pre ++ runway (c::cs) ++ suffix))
  = (4,2,c)%N :: runway cs.
Proof.
  replace (pre ++ runway (c::cs) ++ suffix)
    with ((pre ++ [(8,2,1)%N]) ++ ((4,2,c)%N :: runway cs) ++ suffix)
    by (cbn [runway rung1 app]; rewrite <- !app_assoc; reflexivity).
  replace (S (length pre)) with (length (pre ++ [(8,2,1)%N]))
    by (rewrite length_app; cbn [length]; lia).
  rewrite skipn_pre.
  replace (2 * length (c::cs) - 1)%nat
    with (length ((4,2,c)%N :: runway cs))
    by (cbn [length]; rewrite length_runway; lia).
  apply GenerationSound_firstn_pre.
Qed.
Lemma div_28 (q rem : N) : (rem < 28)%N -> ((28 * q + rem) / 28 = q)%N.
Proof.
  intros H. replace (28 * q + rem)%N with (q * 28 + rem)%N by lia.
  rewrite N.div_add_l by discriminate. rewrite N.div_small by lia. lia.
Qed.
Lemma mod_28 (q rem : N) : (rem < 28)%N -> ((28 * q + rem) mod 28 = rem)%N.
Proof.
  intros H. replace (28 * q + rem)%N with (rem + q * 28)%N by lia.
  rewrite N.Div0.mod_add. apply N.mod_small; lia.
Qed.
Lemma marks_split (q rem : N) : (rem < 28)%N ->
  marks (28 * q + rem) = (4 * q + marks rem)%N.
Proof.
  intros H. unfold marks.
  rewrite div_28 by lia. rewrite mod_28 by lia.
  rewrite (N.div_small rem 28) by lia. rewrite (N.mod_small rem 28) by lia.
  lia.
Qed.
Lemma marks_le3 (q : N) : (q < 28)%N -> (marks q <= 3)%N.
Proof.
  intros H. change 3%N with (marks 27).
  apply marks_mono; lia.
Qed.
Lemma site_wat (pre post : word) (p c : N) : (p < 28)%N ->
  wat (site pre p c post)
           (length pre + phase_len p)
  = Some (4,2,c)%N.
Proof.
  intros Hp. unfold site.
  rewrite <- (phase_form_len p Hp), app_assoc.
  replace (length pre + length (phase_form p))%nat
    with (length (pre ++ phase_form p))
    by (rewrite length_app; lia).
  apply wat_at_app.
Qed.
Lemma site_skipn (pre post : word) (p c : N) : (p < 28)%N ->
  skipn (S (length pre + phase_len p))
        (site pre p c post) = post.
Proof.
  intros Hp. unfold site.
  rewrite <- (phase_form_len p Hp).
  replace (phase_form p ++ (4,2,c)%N :: post)
    with ((phase_form p ++ [(4,2,c)%N]) ++ post)
    by (rewrite <- app_assoc; reflexivity).
  replace (S (length pre + length (phase_form p)))%nat
    with (length pre + length (phase_form p ++ [(4,2,c)%N]))%nat
    by (rewrite length_app; cbn [length]; lia).
  apply (skipn_pre2 pre
           (phase_form p ++ [(4,2,c)%N]) post).
Qed.
Lemma site_length (pre post : word) (p c : N) : (p < 28)%N ->
  length (site pre p c post)
  = (length pre + phase_len p + 1 + length post)%nat.
Proof.
  intros Hp. unfold site.
  rewrite len_app3.
  now rewrite (phase_form_len p Hp).
Qed.
Lemma bulk_stage_runway (c : N) (cs : list N) (pre post : word)
      (p b rem : N) :
  Forall (fun x => (FLOOR <= x)%N) (c::cs) ->
  (p < 28)%N -> (rem < 28)%N -> post <> [] -> (FLOOR <= b)%N ->
  bulk_stage
    (site (pre ++ runway (c::cs)) p
       (b + DBu p) post)
    (length (pre ++ runway (c::cs))) p
    (28 * N.of_nat (length (c::cs)) - p + rem)
  = Some (site pre rem (c - 3 + DBu rem)
            (crossed_post cs b post),
          length pre, rem,
          (marks (28 * N.of_nat (length (c::cs)) + rem)
             - marks p)%N).
Proof.
  intros Hall Hp Hrem Hpost Hb.
  inversion Hall as [|y ys Hc Hcs]; subst y ys.
  assert (Hc3 : (3 <= c)%N) by (unfold FLOOR in Hc; lia).
  assert (Hb1 : (1 <= b)%N) by (unfold FLOOR in Hb; lia).
  set (n := length (c::cs)).
  set (j := length (pre ++ runway (c::cs))).
  assert (Hn : (1 <= n)%nat) by (unfold n; cbn [length]; lia).
  assert (HNn : (1 <= N.of_nat n)%N) by lia.
  assert (Hj : j = (length pre + 2 * n)%nat)
    by (unfold j, n; rewrite length_app, length_runway; lia).
  assert (Etot : (p + (28 * N.of_nat n - p + rem) = 28 * N.of_nat n + rem)%N)
    by lia.
  assert (Hwat : wat
      (site (pre ++ runway (c::cs)) p
         (b + DBu p) post) (j + phase_len p)
    = Some (4,2,b + DBu p)%N)
    by (unfold j; apply site_wat; exact Hp).
  assert (Hbig : lvl_big (4,2,b + DBu p)%N = true)
    by (apply lvl_big_intro; lia).
  assert (Hend : Nat.eqb (S (j + phase_len p))
      (length (site (pre ++ runway (c::cs)) p
                 (b + DBu p) post)) = false).
  { apply PeanoNat.Nat.eqb_neq. rewrite site_length by exact Hp.
    destruct post; [contradiction | cbn [length]; lia]. }
  assert (Hdiv : N.to_nat ((28 * N.of_nat n + rem) / 28) = n)
    by (rewrite div_28 by lia; apply Nat2N.id).
  assert (Hmod : ((28 * N.of_nat n + rem) mod 28 = rem)%N)
    by (apply mod_28; lia).
  assert (Hfull0 : Nat.eqb n 0 = false) by (apply PeanoNat.Nat.eqb_neq; lia).
  assert (Hlt : Nat.ltb j (2 * n) = false)
    by (apply PeanoNat.Nat.ltb_ge; lia).
  assert (Hclean : clean_above
      (site (pre ++ runway (c::cs)) p
         (b + DBu p) post) (j - 1) n = true).
  { unfold site. rewrite <- app_assoc.
    unfold j, n. rewrite length_app, length_runway.
    apply clean_above_runway. exact Hall. }
  assert (Hnh : (j - 2 * n)%nat = length pre) by lia.
  assert (Hfirst : firstn (length pre)
      (site (pre ++ runway (c::cs)) p
         (b + DBu p) post) = pre).
  { unfold site. rewrite <- !app_assoc.
    apply GenerationSound_firstn_pre. }
  assert (Hslice : firstn (2 * n - 1)
      (skipn (S (length pre))
        (site (pre ++ runway (c::cs)) p
           (b + DBu p) post))
    = (4,2,c)%N :: runway cs).
  { unfold site. rewrite <- !app_assoc.
    unfold n. apply firstn_runway_slice. }
  assert (Htail : skipn (S (j + phase_len p))
      (site (pre ++ runway (c::cs)) p
         (b + DBu p) post) = post)
    by (unfold j; apply site_skipn; exact Hp).
  unfold bulk_stage. cbv beta zeta.
  rewrite Etot.
  rewrite Hwat. cbv beta iota.
  rewrite Hbig. cbn [negb]. cbv beta iota.
  rewrite Hend. cbv beta iota.
  rewrite Hdiv, Hmod, Hfull0. cbv beta iota.
  rewrite Hlt. cbv beta iota.
  rewrite Hclean. cbn [negb]. cbv beta iota.
  rewrite Hnh. rewrite Hslice. cbv beta iota.
  rewrite Hfirst, Htail.
  rewrite map_adj4_runway.
  cbn [gC].
  replace (c + DBu rem - 3)%N with (c - 3 + DBu rem)%N
    by lia.
  replace (b + DBu p - 1 - DBu p)%N with (b - 1)%N
    by lia.
  unfold site, crossed_post, rung1.
  rewrite <- !app_assoc. cbn [app]. reflexivity.
Qed.
Open Scope list.
Opaque LROUND_FUEL LROUND_CHUNKS
       FLAT_ROUND_FUEL CFUEL TRIES.
Ltac xput H :=
  match type of H with
  | ?L = ?R =>
      match goal with
      | |- context [?T] =>
          unify T L;
          let E := fresh "EX9" in
          assert (E : T = R) by exact H;
          rewrite E; clear E
      end
  end.
Fixpoint gclimb (fu : nat) (sg : list seg) (rw : word)
                (need : nat) (top : bool)
  : option (word * word * list seg) :=
  match fu with
  | O => None
  | S fu' =>
      if Nat.eqb need O then Some (rw, [], sg) else
      match rw with
      | l :: s :: rest =>
          if negb (is_spc s) then None else
          match keyi sg l with
          | Some sg1 =>
              if top then None else
              let nl := segl sg1 in
              if negb (can_cross sg1) then None else
              if Nat.ltb need nl then None else
              match gclimb fu'
                      (sgset sg (sKey sg1)
                         (bump_pend sg1)) rest (need - nl)%nat false
              with
              | Some (left, used, sg2) => Some (left, l :: s :: used, sg2)
              | None => None
              end
          | None =>
              if negb (lit_crossable l) then None else
              match gclimb fu' sg rest (need - 1)%nat false with
              | Some (left, used, sg2) => Some (left, l :: s :: used, sg2)
              | None => None
              end
          end
      | _ => None
      end
  end.
Lemma rev_firstn_S : forall (w : word) k (d : bg),
  (k < length w)%nat ->
  rev (firstn (S k) w) = nth k w d :: rev (firstn k w).
Proof.
  intros w. induction w as [|g t IH]; intros k d Hk; [cbn in Hk; lia|].
  destruct k as [|k]; [reflexivity|].
  cbn [firstn length nth] in *.
  cbn [rev]. rewrite (IH k d ltac:(lia)).
  cbn [rev app]. reflexivity.
Qed.
Lemma wat_nth : forall (w : word) k (d : bg),
  (k < length w)%nat -> wat w k = Some (nth k w d).
Proof.
  intros w k d Hk. unfold wat.
  apply nth_error_nth'. exact Hk.
Qed.
Lemma length_rev_firstn : forall (w : word) k,
  (k <= length w)%nat -> length (rev (firstn k w)) = k.
Proof.
  intros w k Hk. rewrite length_rev, length_firstn. lia.
Qed.
Lemma climb_gclimb : forall fu sg w k need top,
  (S k <= length w)%nat ->
  is_spc (nth O w d0) = false ->
  climb fu sg w k need top
  = match gclimb fu sg (rev (firstn (S k) w)) need top with
    | Some (left, used, sg') => Some (length left, sg')
    | None => None
    end.
Proof.
  intros fu. induction fu as [|fu IH]; intros sg w k need top Hk H0;
    [reflexivity|].
  cbn [climb gclimb].
  destruct (Nat.eqb need O) eqn:En.
  { rewrite length_rev_firstn by lia. reflexivity. }
  destruct (Nat.ltb k 1) eqn:Hk1.
  { apply PeanoNat.Nat.ltb_lt in Hk1.
    assert (k = O) by lia. subst k.
    cbn [firstn]. destruct w as [|g t]; [cbn in Hk; lia|].
    cbn [firstn rev app]. reflexivity. }
  apply PeanoNat.Nat.ltb_ge in Hk1.
  destruct k as [|k']; [lia|].
  replace (S k' - 1)%nat with k' by lia.
  rewrite (rev_firstn_S w (S k') d0 ltac:(lia)).
  rewrite (rev_firstn_S w k' d0 ltac:(lia)).
  rewrite (wat_nth w (S k') d0 ltac:(lia)).
  rewrite (wat_nth w k' d0 ltac:(lia)).
  cbv beta iota.
  destruct (negb (is_spc (nth k' w d0))) eqn:Hspc;
    [reflexivity|].
  assert (Hk2 : (1 <= k')%nat).
  { destruct k' as [|k'']; [|lia]. cbn in Hspc. rewrite H0 in Hspc.
    discriminate Hspc. }
  replace (S k' - 2)%nat with (k' - 1)%nat by lia.
  replace (rev (firstn k' w)) with (rev (firstn (S (k'-1)) w))
    by (f_equal; f_equal; lia).
  destruct (keyi sg (nth (S k') w d0)) as [s|] eqn:EK.
  - destruct top; [reflexivity|].
    destruct (negb (can_cross s)); [reflexivity|].
    destruct (Nat.ltb need (segl s)); [reflexivity|].
    rewrite (IH (sgset sg (sKey s) (bump_pend s))
               w (k'-1)%nat (need - segl s)%nat false
               ltac:(lia) H0).
    destruct (gclimb fu _ _ _ _) as [[[l0 u0] s0]|]; reflexivity.
  - destruct (negb (lit_crossable (nth (S k') w d0)));
      [reflexivity|].
    rewrite (IH sg w (k'-1)%nat (need - 1)%nat false ltac:(lia) H0).
    destruct (gclimb fu _ _ _ _) as [[[l0 u0] s0]|]; reflexivity.
Qed.
Lemma gclimb_split : forall fu sg rw need top left used sg',
  gclimb fu sg rw need top = Some (left, used, sg') ->
  rw = used ++ left.
Proof.
  intros fu. induction fu as [|fu IH]; intros sg rw need top left used sg' H;
    [discriminate|].
  cbn [gclimb] in H.
  destruct (Nat.eqb need O); [injection H as -> <- _; reflexivity|].
  destruct rw as [|l [|s rest]]; try discriminate.
  destruct (negb (is_spc s)); [discriminate|].
  destruct (keyi sg l) as [s0|].
  - destruct top; [discriminate|].
    destruct (negb (can_cross s0)); [discriminate|].
    destruct (Nat.ltb need (segl s0)); [discriminate|].
    destruct (gclimb fu _ rest _ false) as [[[l1 u1] g1]|] eqn:E;
      [|discriminate].
    injection H as -> <- <-. cbn [app]. do 2 f_equal.
    exact (IH _ _ _ _ _ _ _ E).
  - destruct (negb (lit_crossable l)); [discriminate|].
    destruct (gclimb fu sg rest _ false) as [[[l1 u1] g1]|] eqn:E;
      [|discriminate].
    injection H as -> <- <-. cbn [app]. do 2 f_equal.
    exact (IH _ _ _ _ _ _ _ E).
Qed.
Fixpoint bump_groups (sg : list seg) (w : word)
  : list seg :=
  match w with
  | [] => sg
  | g :: w' =>
      match keyi sg g with
      | Some s => bump_groups
          (sgset sg (sKey s) (bump_pend s)) w'
      | None => bump_groups sg w'
      end
  end.
Lemma sKey_bump (s : seg) :
  sKey (bump_pend s) = sKey s.
Proof. destruct s as [[[[[[k p] m] l] bf] bb] cs]. reflexivity. Qed.
Lemma keyi_some_in sg g s :
  keyi sg g = Some s -> In s sg.
Proof. intros H. exact (proj1 (keyi_in sg g s H)). Qed.
Lemma keyi_some_lvl sg g s :
  keyi sg g = Some s -> phshape g = true.
Proof. intros H. exact (proj1 (proj2 (keyi_in sg g s H))). Qed.
Lemma keyi_some_key sg g s :
  keyi sg g = Some s -> gC g = sKey s.
Proof. intros H. exact (proj2 (proj2 (keyi_in sg g s H))). Qed.
Lemma keyi_sgset_self sg g s :
  keyi sg g = Some s ->
  keyi (sgset sg (sKey s) (bump_pend s)) g
  = Some (bump_pend s).
Proof.
  intros Ek.
  rewrite (sgset_keyi sg (sKey s) _ g (sKey_bump s)).
  rewrite Ek. rewrite N.eqb_refl. reflexivity.
Qed.
Lemma keyi_sgset_away sg g old x sx :
  keyi sg g = Some old ->
  keyi sg x = Some sx ->
  is_key (sKey old) x = false ->
  keyi (sgset sg (sKey sx) (bump_pend sx)) g
  = Some old.
Proof.
  intros Eg Ex Hx.
  rewrite (sgset_keyi sg (sKey sx) _ g (sKey_bump sx)).
  rewrite Eg.
  replace (sKey old =? sKey sx)%N with false;
    [reflexivity|].
  symmetry. apply N.eqb_neq.
  unfold is_key in Hx.
  rewrite (keyi_some_lvl sg x sx Ex) in Hx. cbn [andb] in Hx.
  apply N.eqb_neq in Hx.
  rewrite (keyi_some_key sg x sx Ex) in Hx. congruence.
Qed.
Lemma bump_groups_keys sg xs :
  List.map sKey (bump_groups sg xs) = List.map sKey sg.
Proof.
  revert sg. induction xs as [|g xs IH]; intros sg; [reflexivity|].
  cbn [bump_groups]. destruct (keyi sg g) as [s|] eqn:Ek.
  - rewrite IH. apply sgset_keys. apply sKey_bump.
  - apply IH.
Qed.
Lemma keyi_none_same_keys sg sg' g :
  List.map sKey sg' = List.map sKey sg ->
  keyi sg g = None -> keyi sg' g = None.
Proof.
  intros Hkeys. unfold keyi.
  destruct (phshape g); [|reflexivity].
  revert sg' Hkeys. induction sg as [|s sg IH]; intros [|s' sg'] Hkeys;
    try discriminate; [reflexivity|].
  cbn [List.map] in Hkeys. inversion Hkeys as [[Hk Hks]].
  cbn. rewrite Hk.
  destruct (gC g =? sKey s)%N; [discriminate|].
  apply IH. exact Hks.
Qed.
Lemma bump_groups_keyi_none sg xs g :
  keyi sg g = None ->
  keyi (bump_groups sg xs) g = None.
Proof.
  intros H. eapply keyi_none_same_keys; [apply bump_groups_keys|exact H].
Qed.
Lemma keyi_adj4 : forall sg g,
  keyi sg (adj4 g) = keyi sg g.
Proof.
  intros sg [[o z] c]. unfold adj4, keyi,
    phshape, PHO. cbn [gO gZ gC].
  destruct ((o =? 4) && (z =? 2))%N eqn:E; [|reflexivity].
  apply andb_prop in E as [Eo _]. apply N.eqb_eq in Eo. subst o.
  reflexivity.
Qed.
Lemma countkey_cons_match k g xs :
  is_key k g = true ->
  countkey k (g :: xs) = S (countkey k xs).
Proof. unfold is_key. cbn [countkey]. now intros ->. Qed.
Lemma countkey_cons_nomatch k g xs :
  is_key k g = false ->
  countkey k (g :: xs) = countkey k xs.
Proof. unfold is_key. cbn [countkey]. now intros ->. Qed.
Lemma is_key_of_keyi sg g s :
  keyi sg g = Some s -> is_key (sKey s) g = true.
Proof.
  intros Ek. unfold is_key.
  rewrite (keyi_some_lvl sg g s Ek). cbn [andb].
  apply N.eqb_eq. exact (keyi_some_key sg g s Ek).
Qed.
Lemma keyi_same_key sg a b s :
  keyi sg a = Some s ->
  phshape b = true -> gC b = gC a ->
  keyi sg b = Some s.
Proof.
  intros Ha Hb Hc. unfold keyi in Ha |- *.
  rewrite Hb. rewrite (keyi_some_lvl sg a s Ha) in Ha.
  now rewrite Hc.
Qed.
Lemma bump_groups_keyi_count0 : forall xs sg g old,
  keyi sg g = Some old ->
  countkey (sKey old) xs = 0%nat ->
  keyi (bump_groups sg xs) g = Some old.
Proof.
  induction xs as [|x xs IH]; intros sg g old Eg Hcount; [exact Eg|].
  destruct (is_key (sKey old) x) eqn:Hx.
  - rewrite (countkey_cons_match _ _ _ Hx) in Hcount. lia.
  - rewrite (countkey_cons_nomatch _ _ _ Hx) in Hcount.
    cbn [bump_groups]. destruct (keyi sg x) as [sx|] eqn:Ex.
    + eapply IH; [exact (keyi_sgset_away sg g old x sx Eg Ex Hx)|exact Hcount].
    + exact (IH sg g old Eg Hcount).
Qed.
Lemma bump_groups_keyi_count1 : forall xs sg g old,
  keyi sg g = Some old ->
  countkey (sKey old) xs = 1%nat ->
  keyi (bump_groups sg xs) g = Some (bump_pend old).
Proof.
  induction xs as [|x xs IH]; intros sg g old Eg Hcount; [discriminate|].
  destruct (is_key (sKey old) x) eqn:Hx.
  - rewrite (countkey_cons_match _ _ _ Hx) in Hcount.
    assert (Htail : countkey (sKey old) xs = 0%nat) by lia.
    unfold is_key in Hx. apply andb_prop in Hx.
    destruct Hx as [Hshape Hkey]. apply N.eqb_eq in Hkey.
    assert (Hsame : gC x = gC g)
      by (rewrite (keyi_some_key sg g old Eg); exact Hkey).
    pose proof (keyi_same_key sg g x old Eg Hshape Hsame) as Ex.
    cbn [bump_groups]. rewrite Ex.
    eapply bump_groups_keyi_count0.
    + exact (keyi_sgset_self sg g old Eg).
    + rewrite sKey_bump. exact Htail.
  - rewrite (countkey_cons_nomatch _ _ _ Hx) in Hcount.
    cbn [bump_groups]. destruct (keyi sg x) as [sx|] eqn:Ex.
    + eapply IH; [exact (keyi_sgset_away sg g old x sx Eg Ex Hx)|exact Hcount].
    + exact (IH sg g old Eg Hcount).
Qed.
Definition LineageBulk_lin_atmost (sg : list seg) (w : word) : bool :=
  forallb (fun s => Nat.leb (countkey (sKey s) w) 1) sg.
Lemma countkey_pos_of_in k g w :
  is_key k g = true -> In g w -> (1 <= countkey k w)%nat.
Proof.
  intros Hg Hin. induction w as [|x w IH]; [contradiction|].
  cbn in Hin. destruct Hin as [<-|Hin].
  - rewrite (countkey_cons_match _ _ _ Hg). lia.
  - destruct (is_key k x) eqn:Hx.
    + rewrite (countkey_cons_match _ _ _ Hx). lia.
    + rewrite (countkey_cons_nomatch _ _ _ Hx). exact (IH Hin).
Qed.
Lemma countkey_rev k w :
  countkey k (rev w) = countkey k w.
Proof.
  induction w as [|g w IH]; [reflexivity|].
  cbn [rev]. rewrite countkey_app, IH.
  cbn [countkey]. lia.
Qed.
Lemma lin_atmost_rev sg xs : LineageBulk_lin_atmost sg (rev xs) = LineageBulk_lin_atmost sg xs.
Proof.
  unfold LineageBulk_lin_atmost. induction sg as [|s sg IH]; [reflexivity|].
  cbn [forallb]. now rewrite countkey_rev, IH.
Qed.
Lemma lin_atmost_middle sg pre xs post :
  lin_ok sg (pre ++ xs ++ post) = true -> LineageBulk_lin_atmost sg xs = true.
Proof.
  intros HO. unfold lin_ok in HO. unfold LineageBulk_lin_atmost.
  apply forallb_forall. intros s Hin.
  apply forallb_forall with (x := s) in HO; [|exact Hin].
  apply PeanoNat.Nat.eqb_eq in HO. apply PeanoNat.Nat.leb_le.
  rewrite !countkey_app in HO. lia.
Qed.
Lemma lin_atmost_keyi_count1 sg xs g s :
  LineageBulk_lin_atmost sg xs = true -> In g xs -> keyi sg g = Some s ->
  countkey (sKey s) xs = 1%nat.
Proof.
  intros HA Hin Ek. unfold LineageBulk_lin_atmost in HA.
  apply forallb_forall with (x := s) in HA; [|exact (keyi_some_in _ _ _ Ek)].
  apply PeanoNat.Nat.leb_le in HA.
  pose proof (countkey_pos_of_in (sKey s) g xs
    (is_key_of_keyi _ _ _ Ek) Hin) as Hpos. lia.
Qed.
Lemma bump_groups_keyi_some_atmost sg xs g s :
  LineageBulk_lin_atmost sg xs = true -> In g xs -> keyi sg g = Some s ->
  keyi (bump_groups sg xs) g = Some (bump_pend s).
Proof.
  intros HA Hin Ek. apply bump_groups_keyi_count1; [exact Ek|].
  exact (lin_atmost_keyi_count1 sg xs g s HA Hin Ek).
Qed.
Lemma bump_groups_affine_sublist sg xs ys :
  LineageBulk_lin_atmost sg xs = true ->
  (forall g, In g ys -> In g xs) ->
  lin_flat (bump_groups sg xs)
      (List.map (adj4p (bump_groups sg xs)) ys)
  = List.map adj4 (lin_flat sg ys).
Proof.
  intros HA Hsub. induction ys as [|g ys IH]; [reflexivity|].
  cbn [List.map]. rewrite !lin_flat_cons.
  destruct (keyi sg g) as [s|] eqn:Ek.
  - pose proof (bump_groups_keyi_some_atmost sg xs g s HA
      (Hsub g (or_introl eq_refl)) Ek) as Ef.
    assert (Hadj : adj4p (bump_groups sg xs) g = g)
      by (unfold adj4p, ph; rewrite Ef; reflexivity).
    rewrite Hadj. unfold keyb. rewrite Ef, Ek. cbv beta iota.
    rewrite List.map_app, (sFlat_bump s).
    f_equal. apply IH. intros x Hx. apply Hsub. now right.
  - pose proof (bump_groups_keyi_none sg xs g Ek) as Ef.
    assert (Hadj : adj4p (bump_groups sg xs) g = adj4 g)
      by (unfold adj4p, ph; rewrite Ef; reflexivity).
    rewrite Hadj. unfold keyb. rewrite Ek.
    rewrite (bump_groups_keyi_none sg xs (adj4 g)
      (ltac:(rewrite keyi_adj4; exact Ek))).
    cbv beta iota. cbn [List.map]. f_equal.
    apply IH. intros x Hx. apply Hsub. now right.
Qed.
Lemma bump_groups_flat_away sg xs ys :
  (forall g s, In g ys -> keyi sg g = Some s ->
     countkey (sKey s) xs = 0%nat) ->
  lin_flat (bump_groups sg xs) ys = lin_flat sg ys.
Proof.
  intros Haway. induction ys as [|g ys IH]; [reflexivity|].
  rewrite !lin_flat_cons. unfold keyb.
  destruct (keyi sg g) as [s|] eqn:Ek.
  - rewrite (bump_groups_keyi_count0 xs sg g s Ek
      (Haway g s (or_introl eq_refl) Ek)).
    f_equal. apply IH. intros x s0 Hx Ex.
    apply Haway with (g := x); [now right|exact Ex].
  - rewrite (bump_groups_keyi_none sg xs g Ek).
    f_equal. apply IH. intros x s Hx Ex.
    apply Haway with (g := x); [now right|exact Ex].
Qed.
Lemma outside_crossed_count0 sg pre crossed post g s :
  lin_ok sg (pre ++ rev crossed ++ post) = true ->
  In g (pre ++ post) -> keyi sg g = Some s ->
  countkey (sKey s) crossed = 0%nat.
Proof.
  intros HO Hin Ek.
  pose proof HO as HC. unfold lin_ok in HC.
  apply forallb_forall with (x := s) in HC;
    [|exact (keyi_some_in _ _ _ Ek)].
  apply PeanoNat.Nat.eqb_eq in HC.
  pose proof (countkey_pos_of_in (sKey s) g (pre ++ post)
    (is_key_of_keyi _ _ _ Ek) Hin) as Hpos.
  rewrite !countkey_app in HC.
  rewrite !countkey_app in Hpos.
  rewrite countkey_rev in HC. lia.
Qed.
Lemma bump_groups_flat_outside sg crossed pre post :
  lin_ok sg (pre ++ rev crossed ++ post) = true ->
  lin_flat (bump_groups sg crossed) pre = lin_flat sg pre /\
  lin_flat (bump_groups sg crossed) post = lin_flat sg post.
Proof.
  intros HO. split; apply bump_groups_flat_away; intros g s Hin Ek;
    eapply outside_crossed_count0; try exact HO; try exact Ek;
    apply in_or_app; [now left|now right].
Qed.
Lemma is_spc_keyi_none sg g :
  is_spc g = true -> keyi sg g = None.
Proof.
  intros H. unfold keyi, is_spc, is_lvl in *.
  destruct g as [[o z] c]. cbn [gO gZ gC] in *.
  repeat rewrite Bool.andb_true_iff in H.
  destruct H as [[Ho _] _]. apply N.eqb_eq in Ho. subst o.
  reflexivity.
Qed.
Lemma gclimb_bump_groups : forall fu sg rw need top left used sg',
  gclimb fu sg rw need top = Some (left, used, sg') ->
  sg' = bump_groups sg used.
Proof.
  intros fu. induction fu as [|fu IH];
    intros sg rw need top left used sg' H; [discriminate|].
  cbn [gclimb] in H.
  destruct (Nat.eqb need O); [injection H as _ <- <-; reflexivity|].
  destruct rw as [|l [|s rest]]; try discriminate.
  destruct (negb (is_spc s)) eqn:Esp; [discriminate|].
  apply negb_false_iff in Esp.
  destruct (keyi sg l) as [s0|] eqn:Ekl.
  - destruct top; [discriminate|].
    destruct (negb (can_cross s0)); [discriminate|].
    destruct (Nat.ltb need (segl s0)); [discriminate|].
    destruct (gclimb fu _ rest _ false) as [[[l1 u1] g1]|] eqn:E;
      [|discriminate].
    injection H as <- <- <-.
    cbn [bump_groups]. rewrite Ekl.
    rewrite (is_spc_keyi_none _ s Esp).
    exact (IH _ _ _ _ _ _ _ E).
  - destruct (negb (lit_crossable l)); [discriminate|].
    destruct (gclimb fu sg rest _ false) as [[[l1 u1] g1]|] eqn:E;
      [|discriminate].
    injection H as <- <- <-.
    cbn [bump_groups]. rewrite Ekl.
    rewrite (is_spc_keyi_none _ s Esp).
    exact (IH _ _ _ _ _ _ _ E).
Qed.
Lemma gclimb_used_pairshape : forall fu sg rw need top left used sg',
  gclimb fu sg rw need top = Some (left, used, sg') ->
  used = [] \/ exists l s rest, used = l :: s :: rest.
Proof.
  intros fu. destruct fu as [|fu];
    intros sg rw need top left used sg' H; [discriminate|].
  cbn [gclimb] in H.
  destruct (Nat.eqb need O); [injection H as _ <- _; now left|].
  destruct rw as [|l [|s rest]]; try discriminate.
  destruct (negb (is_spc s)); [discriminate|].
  destruct (keyi sg l) as [s0|].
  - destruct top; [discriminate|].
    destruct (negb (can_cross s0)); [discriminate|].
    destruct (Nat.ltb need (segl s0)); [discriminate|].
    destruct (gclimb fu _ rest _ false) as [[[l1 u1] g1]|];
      [|discriminate].
    injection H as _ <- _. right. now exists l, s, u1.
  - destruct (negb (lit_crossable l)); [discriminate|].
    destruct (gclimb fu sg rest _ false) as [[[l1 u1] g1]|];
      [|discriminate].
    injection H as _ <- _. right. now exists l, s, u1.
Qed.
Lemma gclimb_last_nonph_lvl : forall fu sg rw need top left used sg'
                                    sp hd rest,
  gclimb fu sg rw need top = Some (left, used, sg') ->
  rev used = sp :: hd :: rest ->
  ph sg' hd = false ->
  lvl_big hd = true.
Proof.
  intros fu. induction fu as [|fu IH];
    intros sg rw need top left used sg' sp hd out H Erev Hph;
    [discriminate|].
  cbn [gclimb] in H.
  destruct (Nat.eqb need O); [injection H as _ <- _; discriminate Erev|].
  destruct rw as [|l [|s rw']]; try discriminate.
  destruct (negb (is_spc s)) eqn:Esp; [discriminate|].
  destruct (keyi sg l) as [s0|] eqn:Ekl.
  - destruct top; [discriminate|].
    destruct (negb (can_cross s0)); [discriminate|].
    destruct (Nat.ltb need (segl s0)); [discriminate|].
    destruct (gclimb fu
      (sgset sg (sKey s0) (bump_pend s0))
      rw' (need - segl s0) false) as [[[l1 u1] g1]|] eqn:ER;
      [|discriminate].
    injection H as <- <- <-.
    cbn [rev] in Erev.
    destruct (rev u1) as [|a [|b rr]] eqn:Eu.
    + cbn [app] in Erev. injection Erev as <- <- _.
      assert (Eu0 : u1 = []).
      { rewrite <- (rev_involutive u1), Eu. reflexivity. }
      subst u1.
      pose proof (gclimb_bump_groups _ _ _ _ _ _ _ _ ER) as Eg1.
      cbn [bump_groups] in Eg1.
      unfold ph in Hph.
      rewrite Eg1 in Hph.
      rewrite (keyi_sgset_self sg l s0 Ekl) in Hph. discriminate.
    + exfalso.
      pose proof (gclimb_used_pairshape _ _ _ _ _ _ _ _ ER) as Hu.
      pose proof (f_equal (@length bg) Eu) as Elen.
      rewrite length_rev in Elen. cbn [length] in Elen.
      destruct Hu as [->|(x & y & ys & ->)]; cbn [length] in Elen; lia.
    + cbn [app] in Erev. injection Erev as <- <- Eout.
      eapply IH; [exact ER|exact Eu|exact Hph].
  - destruct (negb (lit_crossable l)) eqn:Ebig; [discriminate|].
    apply negb_false_iff in Ebig.
    unfold lit_crossable in Ebig.
    apply andb_prop in Ebig as [Ebig _].
    destruct (gclimb fu sg rw' (need - 1) false)
      as [[[l1 u1] g1]|] eqn:ER; [|discriminate].
    injection H as <- <- <-.
    cbn [rev] in Erev.
    destruct (rev u1) as [|a [|b rr]] eqn:Eu.
    + cbn [app] in Erev. injection Erev as <- <- _. exact Ebig.
    + exfalso.
      pose proof (gclimb_used_pairshape _ _ _ _ _ _ _ _ ER) as Hu.
      pose proof (f_equal (@length bg) Eu) as Elen.
      rewrite length_rev in Elen. cbn [length] in Elen.
      destruct Hu as [->|(x & y & ys & ->)]; cbn [length] in Elen; lia.
    + cbn [app] in Erev. injection Erev as <- <- Eout.
      eapply IH; [exact ER|exact Eu|exact Hph].
Qed.
Fixpoint altb (w : word) : bool :=
  match w with
  | [l] => is_lvl l
  | l :: s :: w' => is_lvl l && is_spc s && altb w'
  | _ => false
  end.
Lemma is_spc_eq g : is_spc g = true -> g = (8,2,1)%N.
Proof.
  destruct g as [[o z] c]. unfold is_spc.
  cbn [gO gZ gC]. intros H.
  repeat rewrite Bool.andb_true_iff in H.
  destruct H as [[Ho Hz] Hc].
  apply N.eqb_eq in Ho, Hz, Hc. now subst.
Qed.
Lemma is_lvl_eq g :
  is_lvl g = true -> g = (4,2,gC g)%N.
Proof.
  destruct g as [[o z] c]. unfold is_lvl.
  cbn [gO gZ gC]. intros H.
  apply andb_prop in H. destruct H as [Ho Hz].
  apply N.eqb_eq in Ho, Hz. now subst.
Qed.
Lemma altb_runway : forall b B, altb b = true ->
  (forall g, In g b -> is_lvl g = true -> (B <= gC g)%N) ->
  exists cs, ((8,2,1)%N :: b) = runway cs
          /\ length cs = S (Nat.div2 (length b))
          /\ Forall (fun x => (B <= x)%N) cs.
Proof.
  fix IHs 1. intros b B HA HB.
  destruct b as [|l [|s b']]; [discriminate| |].
  - cbn [altb] in HA.
    exists [gC l]. cbn [runway rung1 app length Nat.div2].
    rewrite <- (is_lvl_eq l HA).
    split; [reflexivity|]. split; [reflexivity|].
    constructor; [exact (HB l (or_introl eq_refl) HA)|constructor].
  - cbn [altb] in HA. repeat rewrite Bool.andb_true_iff in HA.
    destruct HA as [[Hl Hs] HA'].
    destruct (IHs b' B HA'
                (fun g Hg Hlv => HB g (or_intror (or_intror Hg)) Hlv))
      as (cs & Hcs & Hlen & Hall).
    exists (gC l :: cs).
    split; [|split].
    + destruct l as [[ol zl] cl]; destruct s as [[os zs] cs0].
      unfold is_lvl in Hl; unfold is_spc in Hs.
      cbn [gO gZ gC] in Hl, Hs |- *.
      apply andb_prop in Hl; destruct Hl as [Ho Hz].
      repeat rewrite Bool.andb_true_iff in Hs.
      destruct Hs as [[Ho2 Hz2] Hc2].
      apply N.eqb_eq in Ho, Hz, Ho2, Hz2, Hc2. subst.
      cbn [runway rung1 app]. rewrite <- Hcs. reflexivity.
    + cbn [length Nat.div2]. lia.
    + constructor; [exact (HB l (or_introl eq_refl) Hl)|exact Hall].
Qed.
Lemma adjk_is_lvl p g : is_lvl (adjk p g) = is_lvl g.
Proof.
  destruct g as [[o z] c]. unfold adjk, is_lvl.
  cbn [gO gZ]. destruct ((o =? 4) && (z =? 2))%N eqn:E;
    cbn [gO gZ]; now rewrite E.
Qed.
Lemma adjk_is_spc p g : is_spc (adjk p g) = is_spc g.
Proof.
  destruct g as [[o z] c]. unfold adjk, is_spc.
  cbn [gO gZ gC]. destruct ((o =? 4) && (z =? 2))%N eqn:E;
    cbn [gO gZ gC]; [|reflexivity].
  apply andb_prop in E. destruct E as [Ho _]. apply N.eqb_eq in Ho.
  subst o. reflexivity.
Qed.
Lemma altb_matb : forall b p, altb (matb p b) = altb b.
Proof.
  fix IHs 1. intros b p. destruct b as [|l [|s b']]; [reflexivity| |].
  - unfold matb. cbn [List.map altb]. apply adjk_is_lvl.
  - unfold matb in *. cbn [List.map altb].
    rewrite adjk_is_lvl, adjk_is_spc.
    rewrite (IHs b' p). reflexivity.
Qed.
Lemma matb_level_bound : forall b p B m g,
  (forall g0, In g0 b -> is_lvl g0 = true -> (m <= gC g0)%N) ->
  (B + 4 * p <= m)%N ->
  In g (matb p b) -> is_lvl g = true -> (B <= gC g)%N.
Proof.
  intros b p B m g Hm HB Hin Hlv.
  unfold matb in Hin. apply in_map_iff in Hin.
  destruct Hin as (g0 & <- & Hin0).
  rewrite adjk_is_lvl in Hlv.
  specialize (Hm g0 Hin0 Hlv).
  destruct g0 as [[o z] c].
  unfold is_lvl in Hlv. cbn [gO gZ] in Hlv.
  unfold adjk. cbn [gC] in Hm |- *.
  rewrite Hlv. cbn [gC]. lia.
Qed.
Lemma seg_runway : forall s B,
  segcache s = true -> segok s = true ->
  altb (sBody s) = true ->
  (B + 4 * sPend s <= sMin s)%N ->
  exists cs, ((8,2,1)%N :: sFlat s) = runway cs
          /\ length cs = segl s
          /\ Forall (fun x => (B <= x)%N) cs.
Proof.
  intros s B HC HO HA HB.
  assert (Hbound : forall g0, In g0 (sBody s) ->
            is_lvl g0 = true -> (sMin s <= gC g0)%N).
  { intros g0 Hin Hlv. unfold segok in HO. cbv zeta in HO.
    destruct (sBody s) as [|g1 b1] eqn:EB; [contradiction|].
    apply andb_prop in HO. destruct HO as [_ HO].
    rewrite <- EB in HO. rewrite <- EB in Hin.
    eapply forallb_forall in HO; [|exact Hin].
    rewrite Hlv in HO. cbn [negb orb] in HO. apply N.leb_le. exact HO. }
  destruct (altb_runway (sFlat s) B
              (eq_trans (altb_matb (sBody s) (sPend s)) HA)
              (fun g Hin Hlv =>
                 matb_level_bound (sBody s) (sPend s) B
                   (sMin s) g Hbound HB Hin Hlv))
    as (cs & Hcs & Hlen & Hall).
  exists cs. split; [exact Hcs|]. split; [|exact Hall].
  rewrite Hlen. unfold segl. do 2 f_equal.
  unfold sFlat, matb. rewrite List.map_length.
  unfold segcache in HC. apply PeanoNat.Nat.eqb_eq in HC.
  rewrite HC. unfold sBody. rewrite length_app, length_rev.
  reflexivity.
Qed.
Lemma forallb_sgset : forall (P : seg -> bool) sg k s2,
  forallb P sg = true -> P s2 = true ->
  forallb P (sgset sg k s2) = true.
Proof.
  intros P sg k s2. induction sg as [|x t IH]; intros H H2; [reflexivity|].
  cbn [sgset]. cbn [forallb] in H. apply andb_prop in H.
  destruct H as [Hx Ht].
  destruct (sKey x =? k)%N; cbn [forallb];
    [now rewrite H2, Ht | now rewrite Hx, (IH Ht H2)].
Qed.
Lemma In_sgset : forall sg k s2 x,
  In x (sgset sg k s2) -> x = s2 \/ In x sg.
Proof.
  intros sg k s2 x. induction sg as [|y t IH]; [contradiction|].
  cbn [sgset]. destruct (sKey y =? k)%N; cbn [In].
  - intros [<-|H]; [now left|right; now right].
  - intros [<-|H]; [right; now left|].
    destruct (IH H) as [->|H']; [now left|right; now right].
Qed.
Lemma segcache_bump s :
  segcache (bump_pend s) = segcache s.
Proof. destruct s as [[[[[[k p] m] l] bf] bb] cs]. reflexivity. Qed.
Lemma segok_bump s : segok (bump_pend s) = segok s.
Proof. destruct s as [[[[[[k p] m] l] bf] bb] cs]. reflexivity. Qed.
Lemma sBody_bump s : sBody (bump_pend s) = sBody s.
Proof. destruct s as [[[[[[k p] m] l] bf] bb] cs]. reflexivity. Qed.
Lemma sg_wf_sgset_bump sg s0 :
  sg_wf sg -> In s0 sg ->
  sg_wf
    (sgset sg (sKey s0) (bump_pend s0)).
Proof.
  intros HW Hin. unfold sg_wf in *.
  apply forallb_sgset; [exact HW|].
  rewrite segcache_bump, segok_bump.
  eapply forallb_forall in HW; [exact HW|exact Hin].
Qed.
Lemma lin_atmost_tl sg g xs :
  LineageBulk_lin_atmost sg (g :: xs) = true -> LineageBulk_lin_atmost sg xs = true.
Proof.
  unfold LineageBulk_lin_atmost. intros H. apply forallb_forall. intros s Hs.
  eapply forallb_forall in H; [|exact Hs].
  apply PeanoNat.Nat.leb_le in H. apply PeanoNat.Nat.leb_le.
  cbn [countkey] in H. lia.
Qed.
Lemma lin_atmost_keys sg sg' xs :
  List.map sKey sg' = List.map sKey sg ->
  LineageBulk_lin_atmost sg xs = true -> LineageBulk_lin_atmost sg' xs = true.
Proof.
  unfold LineageBulk_lin_atmost. revert sg'.
  induction sg as [|s sg IH]; intros [|s' sg'] Hk H; try discriminate;
    [reflexivity|].
  cbn [List.map] in Hk. inversion Hk as [[Hs Hss]].
  cbn [forallb] in *. apply andb_prop in H. destruct H as [H1 H2].
  rewrite Hs, H1. cbn [andb]. exact (IH sg' Hss H2).
Qed.
Lemma gclimb_runway : forall fu sg rw need top left used sg',
  gclimb fu sg rw need top = Some (left, used, sg') ->
  sg_wf sg ->
  LineageBulk_lin_atmost sg used = true ->
  (forall s, In s sg -> altb (sBody s) = true) ->
  exists cs, lin_flat sg (rev used) = runway cs
          /\ length cs = need
          /\ Forall (fun x => (FLOOR + 3 <= x)%N) cs.
Proof.
  intros fu. induction fu as [|fu IH];
    intros sg rw need top left used sg' H HW HA HAlt; [discriminate|].
  cbn [gclimb] in H.
  destruct (Nat.eqb need O) eqn:En.
  { apply PeanoNat.Nat.eqb_eq in En. injection H as _ <- _.
    exists (@nil N). split; [reflexivity|].
    split; [now rewrite En|constructor]. }
  destruct rw as [|l [|s rest]]; try discriminate.
  destruct (negb (is_spc s)) eqn:Esp; [discriminate|].
  apply negb_false_iff in Esp.
  assert (Eks : keyi sg s = None) by exact (is_spc_keyi_none sg s Esp).
  destruct (keyi sg l) as [s0|] eqn:Ekl.
  -
    destruct top; [discriminate|].
    destruct (negb (can_cross s0)) eqn:Ecross; [discriminate|].
    apply negb_false_iff in Ecross.
    destruct (Nat.ltb need (segl s0)) eqn:Elt; [discriminate|].
    apply PeanoNat.Nat.ltb_ge in Elt.
    destruct (gclimb fu _ rest _ false) as [[[l1 u1] g1]|] eqn:E;
      [|discriminate].
    injection H as <- <- <-.
    set (sg1 := sgset sg (sKey s0) (bump_pend s0))
      in *.
    assert (Hin0 : In s0 sg) by exact (keyi_some_in _ _ _ Ekl).
    assert (Hnl : is_lvl s = false)
      by (rewrite (is_spc_eq s Esp); reflexivity).
    assert (Hps : phshape s = false)
      by (rewrite (is_spc_eq s Esp); reflexivity).
    assert (Hks2 : is_key (sKey s0) s = false)
      by (unfold is_key; now rewrite Hps).
    assert (Hz : countkey (sKey s0) u1 = O).
    { unfold LineageBulk_lin_atmost in HA.
      eapply forallb_forall in HA; [|exact Hin0].
      apply PeanoNat.Nat.leb_le in HA.
      rewrite (countkey_cons_match _ _ _ (is_key_of_keyi _ _ _ Ekl)) in HA.
      rewrite (countkey_cons_nomatch _ _ _ Hks2) in HA. lia. }
    assert (HkeysE : List.map sKey sg1 = List.map sKey sg)
      by (unfold sg1; apply sgset_keys, sKey_bump).
    assert (HAlts : forall s2, In s2 sg1 -> altb (sBody s2) = true).
    { intros s2 Hs2. destruct (In_sgset _ _ _ _ Hs2) as [->|H2].
      - rewrite sBody_bump. exact (HAlt s0 Hin0).
      - exact (HAlt s2 H2). }
    destruct (IH sg1 rest (need - segl s0)%nat false l1 u1 g1 E
                (sg_wf_sgset_bump sg s0 HW Hin0)
                (lin_atmost_keys sg sg1 u1 HkeysE
                   (lin_atmost_tl _ _ _ (lin_atmost_tl _ _ _ HA)))
                HAlts)
      as (cs & Hcs & Hlen & Hall).
    assert (Hcross : (FLOOR + 3 +
                        4 * sPend s0 <= sMin s0)%N).
    { unfold can_cross in Ecross. apply N.leb_le. exact Ecross. }
    destruct (seg_runway s0 (FLOOR + 3)
                (proj1 (sg_wf_seg sg s0 HW Hin0))
                (proj2 (sg_wf_seg sg s0 HW Hin0))
                (HAlt s0 Hin0) Hcross)
      as (cs0 & Hcs0 & Hlen0 & Hall0).
    exists (cs ++ cs0). split; [|split].
    + cbn [rev]. rewrite <- app_assoc. cbn [app].
      rewrite lin_flat_app_c.
      unfold sg1 in Hcs.
      rewrite (lin_flat_sgset sg (sKey s0)
                 (bump_pend s0) (rev u1) (sKey_bump s0)
                 (eq_trans (countkey_rev _ u1) Hz)) in Hcs.
      rewrite Hcs, runway_app. f_equal.
      rewrite lin_flat_cons. unfold keyb.
      rewrite Eks.
      rewrite lin_flat_cons. unfold keyb.
      rewrite Ekl. cbn [lin_flat].
      rewrite app_nil_r, (is_spc_eq s Esp). exact Hcs0.
    + rewrite length_app, Hlen, Hlen0. lia.
    + apply Forall_app. split; [exact Hall|exact Hall0].
  -
    destruct (negb (lit_crossable l)) eqn:Ebig; [discriminate|].
    apply negb_false_iff in Ebig.
    unfold lit_crossable in Ebig.
    apply andb_prop in Ebig as [Ebig Efloor].
    destruct (gclimb fu sg rest _ false) as [[[l1 u1] g1]|] eqn:E;
      [|discriminate].
    injection H as <- <- <-.
    destruct (IH sg rest (need - 1)%nat false l1 u1 g1 E HW
                (lin_atmost_tl _ _ _ (lin_atmost_tl _ _ _ HA)) HAlt)
      as (cs & Hcs & Hlen & Hall).
    exists (cs ++ [gC l]). split; [|split].
    + cbn [rev]. rewrite <- app_assoc. cbn [app].
      rewrite lin_flat_app_c, Hcs, runway_app. f_equal.
      rewrite lin_flat_cons. unfold keyb.
      rewrite Eks.
      rewrite lin_flat_cons. unfold keyb.
      rewrite Ekl. cbn [lin_flat].
      cbn [runway rung1 app].
      rewrite (is_spc_eq s Esp).
      f_equal. f_equal.
      apply is_lvl_eq. unfold lvl_big in Ebig.
      unfold is_lvl.
      repeat rewrite Bool.andb_true_iff in Ebig.
      destruct Ebig as [[Ho Hz] _]. now rewrite Ho, Hz.
    + rewrite length_app, Hlen. cbn [length].
      apply PeanoNat.Nat.eqb_neq in En. lia.
    + apply Forall_app. split; [exact Hall|].
      apply N.leb_le in Efloor.
      constructor; [exact Efloor|constructor].
Qed.
Lemma flat_nolvl : forall sg x,
  forallb (fun g => negb (phshape g)) x = true ->
  lin_flat sg x = x.
Proof.
  intros sg x. induction x as [|g x IH]; intros H; [reflexivity|].
  cbn [forallb] in H. apply andb_prop in H. destruct H as [Hg Hx].
  apply negb_true_iff in Hg.
  rewrite lin_flat_cons. unfold keyb, keyi.
  rewrite Hg. f_equal. exact (IH Hx).
Qed.
Lemma phase_form_nolvl : forall p, (p < 28)%N ->
  forallb (fun g => negb (phshape g))
    (phase_form p) = true.
Proof.
  intros p Hp.
  pose proof (below28_In p Hp) as HIn.
  cbn [P28 List.map seq In] in HIn.
  repeat (destruct HIn as [<-|HIn]; [reflexivity|]). contradiction.
Qed.
Lemma flat_phase_form : forall sg p, (p < 28)%N ->
  lin_flat sg (phase_form p) = phase_form p.
Proof. intros sg p Hp. apply flat_nolvl, phase_form_nolvl, Hp. Qed.
Lemma gclimb_used_nonempty : forall fu sg rw need top left used sg',
  need <> O ->
  gclimb fu sg rw need top = Some (left, used, sg') -> used <> [].
Proof.
  intros fu. destruct fu as [|fu];
    intros sg rw need top left used sg' Hn H; [discriminate|].
  cbn [gclimb] in H.
  destruct (Nat.eqb need O) eqn:En;
    [apply PeanoNat.Nat.eqb_eq in En; contradiction|].
  destruct rw as [|l [|s rest]]; try discriminate.
  destruct (negb (is_spc s)); [discriminate|].
  destruct (keyi sg l) as [s0|].
  - destruct top; [discriminate|].
    destruct (negb (can_cross s0)); [discriminate|].
    destruct (Nat.ltb need (segl s0)); [discriminate|].
    destruct (gclimb fu _ rest _ false) as [[[l1 u1] g1]|]; [|discriminate].
    injection H as _ <- _. discriminate.
  - destruct (negb (lit_crossable l)); [discriminate|].
    destruct (gclimb fu sg rest _ false) as [[[l1 u1] g1]|]; [|discriminate].
    injection H as _ <- _. discriminate.
Qed.
Lemma fmapw_flat_prefix : forall sg w j,
  sg_wf sg -> (j <= length w)%nat ->
  fmapw sg w O O j
  = length (lin_flat sg (firstn j w)).
Proof.
  intros sg w j HW Hj.
  rewrite (fmapw_gen sg w O O j HW ltac:(lia) ltac:(lia)).
  rewrite PeanoNat.Nat.sub_0_r. reflexivity.
Qed.
Lemma lvl_big_shape g : lvl_big g = true ->
  exists c, g = (4,2,c)%N.
Proof.
  destruct g as [[o z] c]. unfold lvl_big.
  cbn [gO gZ gC]. intros H.
  repeat rewrite Bool.andb_true_iff in H.
  destruct H as [[Ho Hz] _]. apply N.eqb_eq in Ho, Hz. subst.
  exists c. reflexivity.
Qed.
Lemma lin_bulk_pieces : forall sg w j p t w' sg' nh rem emit gb pre post,
  w = pre ++ phase_form p ++ gb :: post ->
  length pre = j -> post <> [] ->
  keyi sg gb = None ->
  (p < 28)%N ->
  is_spc (nth O w d0) = false ->
  Nat.eqb (N.to_nat ((p+t)/28)) O = false ->
  lin_bulk sg w j p t = Some (w', sg', nh, rem, emit) ->
  exists left used sp hd rest0 cgb,
       gclimb (S (N.to_nat ((p+t)/28))) sg (rev pre)
              (N.to_nat ((p+t)/28)) true = Some (left, used, sg')
    /\ rev used = sp :: hd :: rest0
    /\ pre = rev left ++ sp :: hd :: rest0
    /\ length left = nh
    /\ gb = (4,2,cgb)%N
    /\ (FLOOR + DBu p <= cgb)%N
    /\ rem = ((p+t) mod 28)%N
    /\ emit = (marks (p+t) - marks p)%N
    /\ ph sg' hd = false
    /\ w' = rev left
              ++ (phase_form rem
                  ++ (gO hd, gZ hd,
                      (gC hd + DBu rem) - 3)%N
                     :: List.map (adj4p sg') rest0 ++ [(8,2,1)%N])
              ++ (4,2,(cgb - 1) - DBu p)%N :: post.
Proof.
  intros sg w j p t w' sg' nh rem emit gb pre post Hw Hj Hpost Hgb Hp H0 Hfull
    HB.
  assert (Hpf : length (phase_form p) = phase_len p)
    by (apply phase_form_len; exact Hp).
  assert (Hwat : wat w (j + phase_len p)%nat = Some gb).
  { subst w. rewrite <- Hpf, <- Hj, <- length_app, app_assoc.
    apply wat_at_app. }
  assert (Hlen : length w
    = (j + phase_len p + S (length post))%nat).
  { subst w. rewrite !length_app. cbn [length]. lia. }
  unfold lin_bulk in HB. cbv zeta in HB.
  rewrite Hwat in HB. cbv beta iota in HB.
  assert (Hph : ph sg gb = false)
    by (unfold ph; now rewrite Hgb).
  rewrite Hph in HB. cbv beta iota in HB.
  destruct (negb (lvl_big gb)) eqn:Ebig; [discriminate|].
  apply negb_false_iff in Ebig.
  destruct (negb (erode_safe p gb)) eqn:Eerode; [discriminate|].
  apply negb_false_iff in Eerode.
  assert (Hend : Nat.eqb (S (j + phase_len p)) (length w) = false).
  { apply PeanoNat.Nat.eqb_neq. rewrite Hlen.
    destruct post; [contradiction|cbn [length]; lia]. }
  rewrite Hend in HB. cbv beta iota in HB.
  rewrite Hfull in HB. cbv beta iota in HB.
  destruct (Nat.ltb j 1) eqn:Ej1; [discriminate|].
  apply PeanoNat.Nat.ltb_ge in Ej1.
  rewrite (climb_gclimb (S (N.to_nat ((p+t)/28))) sg w (j-1)%nat
             (N.to_nat ((p+t)/28)) true ltac:(rewrite Hlen; lia) H0) in HB.
  replace (S (j-1))%nat with j in HB by lia.
  assert (Hfw : firstn j w = pre)
    by (subst w; rewrite <- Hj; apply GenerationSound_firstn_pre).
  rewrite Hfw in HB.
  destruct (gclimb (S (N.to_nat ((p+t)/28))) sg (rev pre)
              (N.to_nat ((p+t)/28)) true) as [[[left used] sgc]|] eqn:EC;
    [|discriminate].
  cbv beta iota in HB.
  pose proof (gclimb_split _ _ _ _ _ _ _ _ EC) as Hsplit.
  assert (Hpre : pre = rev left ++ rev used).
  { rewrite <- (rev_involutive pre), Hsplit, rev_app_distr. reflexivity. }
  assert (Hne : used <> [])
    by (eapply gclimb_used_nonempty;
        [apply PeanoNat.Nat.eqb_neq; exact Hfull|exact EC]).
  assert (Hnh : (length left + length used)%nat = j).
  { rewrite <- Hj, Hpre, length_app, !length_rev. lia. }
  assert (Hrne : rev used <> []).
  { intro E. apply Hne. rewrite <- (rev_involutive used), E. reflexivity. }
  destruct (rev used) as [|sp MID] eqn:EM; [contradiction|].
  assert (Hpre2 : pre = rev left ++ sp :: MID)
    by (rewrite Hpre; try rewrite EM; reflexivity).
  assert (Hlu : length used = S (length MID)).
  { rewrite <- (length_rev used). try rewrite EM. reflexivity. }
  assert (Hw2 : w = rev left ++ [sp]
                  ++ (MID ++ phase_form p ++ gb :: post))
    by (rewrite Hw, Hpre2, <- !app_assoc; reflexivity).
  assert (Hsk : skipn (S (length left)) w
              = MID ++ phase_form p ++ gb :: post).
  { rewrite Hw2.
    replace (S (length left)) with (length (rev left) + length [sp])%nat
      by (rewrite length_rev; cbn [length]; lia).
    apply skipn_pre2. }
  rewrite Hsk in HB.
  replace (j - S (length left))%nat with (length MID) in HB by lia.
  rewrite GenerationSound_firstn_pre in HB.
  destruct MID as [|hd rest0]; [discriminate|].
  destruct hd as [[o0 z0] c_0].
  destruct (ph sgc (o0,z0,c_0)%N) eqn:Eph; [discriminate|].
  assert (Hfn : firstn (length left) w = rev left).
  { rewrite Hw2. replace (length left) with (length (rev left))
      by apply length_rev. apply GenerationSound_firstn_pre. }
  rewrite Hfn in HB.
  assert (Hsk2 : skipn (S (j + phase_len p)) w = post).
  { rewrite Hw.
    replace (pre ++ phase_form p ++ gb :: post)
      with (pre ++ (phase_form p ++ [gb]) ++ post)
      by (rewrite <- !app_assoc; reflexivity).
    replace (S (j + phase_len p))
      with (length pre + length (phase_form p ++ [gb]))%nat
      by (rewrite length_app, Hpf, Hj; cbn [length]; lia).
    apply skipn_pre2. }
  rewrite Hsk2 in HB.
  destruct (lvl_big_shape gb Ebig) as (cgb & Hcgb).
  injection HB as <- <- <- <- <-.
  exists left, used, sp, (o0,z0,c_0)%N, rest0, cgb.
  split; [first [exact EC|reflexivity]|].
  split; [first [exact EM|reflexivity]|].
  split; [first [exact Hpre2|reflexivity]|].
  split; [reflexivity|].
  split; [exact Hcgb|].
  split.
  { unfold erode_safe in Eerode. rewrite Hcgb in Eerode.
    cbn [gC] in Eerode. apply N.leb_le. exact Eerode. }
  split; [reflexivity|]. split; [reflexivity|].
  split; [exact Eph|].
  cbn [gO gZ gC]. rewrite Hcgb. cbn [gC]. reflexivity.
Qed.
Lemma sg_wf_bump_groups : forall xs sg,
  sg_wf sg -> sg_wf (bump_groups sg xs).
Proof.
  induction xs as [|g xs IH]; intros sg HW; [exact HW|].
  cbn [bump_groups]. destruct (keyi sg g) as [s|] eqn:Ek.
  - apply IH, sg_wf_sgset_bump; [exact HW|exact (keyi_some_in _ _ _ Ek)].
  - apply IH, HW.
Qed.
Lemma hd_app_spc : forall (a : word) s l,
  is_spc s = true ->
  match a with [] => True | sp :: _ => is_spc sp = true end ->
  match (a ++ [s]) ++ [l] with
  | [] => True | sp :: _ => is_spc sp = true end.
Proof. intros a s l Hs Ha. destruct a as [|x xs]; cbn [app]; assumption. Qed.
Lemma gclimb_last_spc : forall fu sg rw need top left used sg',
  gclimb fu sg rw need top = Some (left, used, sg') ->
  match rev used with [] => True | sp :: _ => is_spc sp = true end.
Proof.
  intros fu. induction fu as [|fu IH];
    intros sg rw need top left used sg' H; [discriminate|].
  cbn [gclimb] in H.
  destruct (Nat.eqb need O); [injection H as _ <- _; exact I|].
  destruct rw as [|l [|s rest]]; try discriminate.
  destruct (negb (is_spc s)) eqn:Esp; [discriminate|].
  apply negb_false_iff in Esp.
  destruct (keyi sg l) as [s0|] eqn:Ekl.
  - destruct top; [discriminate|].
    destruct (negb (can_cross s0)); [discriminate|].
    destruct (Nat.ltb need (segl s0)); [discriminate|].
    destruct (gclimb fu _ rest _ false) as [[[l1 u1] g1]|] eqn:E;
      [|discriminate].
    injection H as <- <- <-. cbn [rev].
    apply hd_app_spc; [exact Esp|exact (IH _ _ _ _ _ _ _ E)].
  - destruct (negb (lit_crossable l)); [discriminate|].
    destruct (gclimb fu sg rest _ false) as [[[l1 u1] g1]|] eqn:E;
      [|discriminate].
    injection H as <- <- <-. cbn [rev].
    apply hd_app_spc; [exact Esp|exact (IH _ _ _ _ _ _ _ E)].
Qed.
Lemma flat_single sg g :
  keyi sg g = None -> lin_flat sg [g] = [g].
Proof.
  intros H. rewrite lin_flat_cons. unfold keyb.
  rewrite H. reflexivity.
Qed.
Lemma In_rev2 {A : Type} (l : list A) (x : A) : In x l -> In x (rev l).
Proof.
  induction l as [|a l IH]; cbn [In rev]; [contradiction|].
  intros [->|H]; apply in_or_app; [right; now left|left; exact (IH H)].
Qed.
Lemma In_rev3 {A : Type} (l : list A) (x : A) : In x (rev l) -> In x l.
Proof.
  intros H. rewrite <- (rev_involutive l). exact (In_rev2 (rev l) x H).
Qed.
Lemma segok_body_ne s :
  segok s = true -> sBody s <> [].
Proof.
  unfold segok. cbv zeta. destruct (sBody s) as [|g b];
    [discriminate|intros _ E; discriminate E].
Qed.
Lemma lin_flat_nonempty : forall sg x,
  sg_wf sg -> x <> [] -> lin_flat sg x <> [].
Proof.
  intros sg x HW Hx. destruct x as [|g tl]; [contradiction|].
  rewrite lin_flat_cons. unfold keyb.
  destruct (keyi sg g) as [s|] eqn:Ek; [|discriminate].
  intros E. apply app_eq_nil in E. destruct E as [E _].
  unfold sFlat, matb in E.
  apply map_eq_nil in E.
  exact (segok_body_ne s
    (proj2 (sg_wf_seg sg s HW (keyi_some_in _ _ _ Ek))) E).
Qed.
Theorem lin_bulk_ledger : forall sg w j p t w' sg' nh rem emit gb pre post,
  sg_wf sg ->
  lin_ok sg w = true ->
  (forall s, In s sg -> altb (sBody s) = true) ->
  is_spc (nth O w d0) = false ->
  w = pre ++ phase_form p ++ gb :: post ->
  length pre = j -> post <> [] -> keyi sg gb = None ->
  (p < 28)%N ->
  Nat.eqb (N.to_nat ((p+t)/28)) O = false ->
  lin_bulk sg w j p t = Some (w', sg', nh, rem, emit) ->
  exists PRE POST c cs b,
       lin_flat sg w
         = site (PRE ++ runway (c :: cs)) p
             (b + DBu p) POST
    /\ lin_flat sg' w'
         = site PRE rem (c - 3 + DBu rem)
             (crossed_post cs b POST)
    /\ fmapw sg w O O j = length (PRE ++ runway (c :: cs))
    /\ fmapw sg' w' O O nh = length PRE
    /\ length (c :: cs) = N.to_nat ((p+t)/28)
    /\ Forall (fun x => (FLOOR + 3 <= x)%N) (c :: cs)
    /\ POST <> []
    /\ (FLOOR <= b)%N
    /\ rem = ((p+t) mod 28)%N
    /\ emit = (marks (p+t) - marks p)%N.
Proof.
  intros sg w j p t w' sg' nh rem emit gb pre post
    HW Hok Halt H0 Hw Hj Hpost Hgb Hp Hfull HB.
  destruct (lin_bulk_pieces sg w j p t w' sg' nh rem emit gb pre post
              Hw Hj Hpost Hgb Hp H0 Hfull HB)
    as (left & used & sp & hd & rest0 & cgb & EC & EM & Hpre2 & Hnh
        & Hgbs & Hcgbf & Hrem & Hemit & Heph & Hw').
  assert (Hsg' : sg' = bump_groups sg used)
    by exact (gclimb_bump_groups _ _ _ _ _ _ _ _ EC).
  assert (Hpre3 : pre = rev left ++ rev used)
    by (rewrite Hpre2, EM; reflexivity).
  assert (Hw3 : w = rev left ++ rev used
                    ++ (phase_form p ++ gb :: post))
    by (rewrite Hw, Hpre3, <- app_assoc; reflexivity).
  assert (HA : LineageBulk_lin_atmost sg used = true).
  { rewrite <- lin_atmost_rev. eapply lin_atmost_middle.
    rewrite <- Hw3. exact Hok. }
  destruct (gclimb_runway _ sg _ _ _ _ _ _ EC HW HA Halt)
    as (csall & Hcs & Hlencs & Hall).
  assert (Hspc : is_spc sp = true).
  { pose proof (gclimb_last_spc _ _ _ _ _ _ _ _ EC) as HS.
    rewrite EM in HS. exact HS. }
  assert (Hephk : keyi sg' hd = None).
  { unfold ph in Heph.
    destruct (keyi sg' hd); [discriminate|reflexivity]. }
  assert (Ehd : keyi sg hd = None).
  { apply (keyi_none_same_keys (bump_groups sg used) sg hd
             (eq_sym (bump_groups_keys sg used))).
    rewrite <- Hsg'. exact Hephk. }
  assert (Hf2 : sp :: hd :: lin_flat sg rest0 = runway csall).
  { rewrite <- Hcs, EM.
    rewrite (lin_flat_cons sg sp),
            (lin_flat_cons sg hd).
    unfold keyb.
    rewrite (is_spc_keyi_none sg sp Hspc), Ehd. reflexivity. }
  destruct csall as [|c cs]; [cbn [runway] in Hf2; discriminate|].
  cbn [runway rung1 app] in Hf2.
  injection Hf2 as Hsp Hhd Hrest.
  assert (Hc3 : (3 <= c)%N)
    by (inversion Hall as [|y ys Hy Hys]; lia).
  assert (Hrem28 : (rem < 28)%N) by (rewrite Hrem; apply N.mod_lt; lia).
  assert (Hsgwf' : sg_wf sg')
    by (rewrite Hsg'; apply sg_wf_bump_groups, HW).
  assert (Hsub : forall g, In g rest0 -> In g used).
  { intros g Hg. apply In_rev3. rewrite EM. right. right. exact Hg. }
  assert (Eleft : lin_flat sg' (rev left)
                  = lin_flat sg (rev left)).
  { rewrite Hsg'.
    exact (proj1 (bump_groups_flat_outside sg used (rev left)
             (phase_form p ++ gb :: post)
             ltac:(rewrite <- Hw3; exact Hok))). }
  assert (Epost : lin_flat sg' post = lin_flat sg post).
  { rewrite Hsg'. apply bump_groups_flat_away. intros g s Hin Ek.
    eapply outside_crossed_count0; [rewrite <- Hw3; exact Hok| |exact Ek].
    apply in_or_app. right. apply in_or_app. right. right. exact Hin. }
  assert (Emid : lin_flat sg' (List.map (adj4p sg') rest0)
                 = runway (List.map dec4 cs)).
  { rewrite Hsg'.
    rewrite (bump_groups_affine_sublist sg used rest0 HA Hsub).
    rewrite Hrest. apply map_adj4_runway. }
  assert (Hk1 : keyi sg' ((4,2,(c + DBu rem) - 3)%N) = None).
  { rewrite Hsg'. apply bump_groups_keyi_none.
    reflexivity. }
  assert (Hk2 : keyi sg'
                  ((4,2,(cgb - 1) - DBu p)%N) = None).
  { rewrite Hsg'. apply bump_groups_keyi_none. reflexivity. }
  assert (Hk3 : keyi sg' ((8,2,1)%N) = None)
    by (apply is_spc_keyi_none; reflexivity).
  assert (Hjlen : (j <= length w)%nat)
    by (rewrite Hw, !length_app, <- Hj; lia).
  assert (Hfw : firstn j w = pre)
    by (rewrite Hw, <- Hj; apply GenerationSound_firstn_pre).
  assert (Hw'2 : w' = rev left ++ (phase_form rem
                   ++ ([(4,2,(c + DBu rem) - 3)%N]
                       ++ (List.map (adj4p sg') rest0
                           ++ ([(8,2,1)%N]
                               ++ ([(4,2,(cgb - 1) - DBu p)%N]
                                   ++ post)))))).
  { rewrite Hw', Hhd. cbn [gO gZ gC].
    repeat rewrite <- app_assoc. cbn [app].
    repeat rewrite <- app_assoc. cbn [app]. reflexivity. }
  exists (lin_flat sg (rev left)), (lin_flat sg post),
         c, cs, (cgb - DBu p)%N.
  split; [|split; [|split; [|split; [|split; [|split; [|split;
    [|split; [|split]]]]]]]].
  -
    rewrite Hw3, !lin_flat_app_c, Hcs.
    rewrite (flat_phase_form sg p Hp).
    rewrite (lin_flat_cons sg gb). unfold keyb.
    rewrite Hgb, Hgbs.
    unfold site.
    replace (cgb - DBu p + DBu p)%N with cgb by lia.
    rewrite <- !app_assoc. reflexivity.
  -
    rewrite Hw'2, !lin_flat_app_c.
    pose proof (flat_single sg' _ Hk1) as R1.
    pose proof (flat_single sg' _ Hk2) as R2.
    pose proof (flat_single sg' _ Hk3) as R3.
    pose proof (flat_phase_form sg' rem Hrem28) as R4.
    xput R1. xput R2. xput R3. xput R4.
    xput Eleft. xput Emid. xput Epost.
    unfold site, crossed_post, rung1.
    replace (c + DBu rem - 3)%N
      with (c - 3 + DBu rem)%N by lia.
    replace (cgb - 1 - DBu p)%N
      with (cgb - DBu p - 1)%N by lia.
    repeat rewrite <- app_assoc. cbn [app]. reflexivity.
  -
    rewrite (fmapw_flat_prefix sg w j HW Hjlen), Hfw, Hpre3.
    rewrite lin_flat_app_c, Hcs. reflexivity.
  -
    assert (Hnhlen : (nh <= length w')%nat)
      by (rewrite <- Hnh, Hw'2, !length_app, length_rev; lia).
    rewrite (fmapw_flat_prefix sg' w' nh Hsgwf' Hnhlen).
    assert (Hfw' : firstn nh w' = rev left).
    { rewrite Hw'2, <- Hnh.
      replace (length left) with (length (rev left)) by apply length_rev.
      apply GenerationSound_firstn_pre. }
    rewrite Hfw', Eleft. reflexivity.
  - exact Hlencs.
  - exact Hall.
  - apply lin_flat_nonempty; [exact HW|exact Hpost].
  - lia.
  - exact Hrem.
  - exact Hemit.
Qed.
Lemma lin_bulk_partial_out : forall sg w j p t w' sg' nh rem emit gb,
  Nat.eqb (N.to_nat ((p+t)/28)) O = true ->
  lin_bulk sg w j p t = Some (w', sg', nh, rem, emit) ->
  wat w (j + phase_len p)%nat = Some gb ->
  sg' = sg /\ nh = j /\ rem = ((p+t) mod 28)%N
  /\ emit = (marks (p+t) - marks p)%N
  /\ w' = subst_at j (phase_len p)
            (phase_form ((p+t) mod 28))
            (subst_at (j + phase_len p)%nat 1
               [(4,2,(gC gb + DBu ((p+t) mod 28))
                     - DBu p)%N] w).
Proof.
  intros sg w j p t w' sg' nh rem emit gb Hfull HB EW.
  unfold lin_bulk in HB. cbv zeta in HB.
  xrewrite_in HB EW. cbv beta iota in HB.
  destruct (ph sg gb); [discriminate|].
  destruct (negb (lvl_big gb)); [discriminate|].
  destruct (negb (erode_safe p gb)); [discriminate|].
  destruct (Nat.eqb (S (j + phase_len p)) (length w));
    [discriminate|].
  rewrite Hfull in HB. cbv beta iota in HB.
  injection HB as E1 E2 E3 E4 E5.
  repeat split; symmetry; assumption.
Qed.
Lemma LineageBulk_skipn_wat : forall (w : word) i g,
  wat w i = Some g -> skipn i w = g :: skipn (S i) w.
Proof.
  intros w. induction w as [|x t IH]; intros i g H.
  - unfold wat in H. destruct i; discriminate.
  - destruct i as [|i]; cbn [skipn].
    + unfold wat in H. cbn [nth_error] in H.
      injection H as <-. reflexivity.
    + apply IH. unfold wat in *. cbn [nth_error] in H. exact H.
Qed.
Lemma detect_phase_form : forall w i p,
  detect_phase w i = Some p ->
  (p < 28)%N /\
  firstn (phase_len p) (skipn i w) = phase_form p.
Proof.
  intros w i p H. unfold detect_phase in H.
  destruct (wat w i) as [[[o z] c]|] eqn:E1; [|discriminate].
  rewrite (LineageBulk_skipn_wat w i _ E1).
  destruct (negb (c =? 1)%N) eqn:Ec; [discriminate|].
  apply negb_false_iff, N.eqb_eq in Ec. subst c.
  destruct (z =? 3)%N eqn:Ez3.
  - apply N.eqb_eq in Ez3. subst z.
    destruct (o =? 7)%N eqn:Q7;
      [apply N.eqb_eq in Q7; subst o; injection H as <-;
       split; [lia|reflexivity]|].
    destruct (o =? 6)%N eqn:Q6;
      [apply N.eqb_eq in Q6; subst o; injection H as <-;
       split; [lia|reflexivity]|].
    destruct (o =? 5)%N eqn:Q5;
      [apply N.eqb_eq in Q5; subst o; injection H as <-;
       split; [lia|reflexivity]|].
    destruct (o =? 4)%N eqn:Q4;
      [apply N.eqb_eq in Q4; subst o; injection H as <-;
       split; [lia|reflexivity]|discriminate].
  - destruct (negb ((z =? 1) && (4 <=? o) && (o <=? 7))%N) eqn:Eg;
      [discriminate|].
    apply negb_false_iff in Eg.
    repeat rewrite Bool.andb_true_iff in Eg.
    destruct Eg as [[Ez1 Ho4] Ho7].
    apply N.eqb_eq in Ez1. subst z.
    apply N.leb_le in Ho4. apply N.leb_le in Ho7.
    destruct (wat w (S i)) as [[[o2 z2] c2]|] eqn:E2;
      [|destruct (o =? 7)%N; discriminate].
    rewrite (LineageBulk_skipn_wat w (S i) _ E2).
    cbv beta iota in H.
    destruct (o =? 7)%N eqn:Q7.
    + apply N.eqb_eq in Q7. subst o.
      destruct ((z2 =? 2) && (c2 =? 1))%N eqn:Ef; [|discriminate].
      apply andb_prop in Ef. destruct Ef as [Ez2 Ec2].
      apply N.eqb_eq in Ez2. apply N.eqb_eq in Ec2. subst z2 c2.
      destruct (o2 =? 3)%N eqn:B3;
        [apply N.eqb_eq in B3; subst o2; injection H as <-;
         split; [lia|reflexivity]|].
      destruct (o2 =? 2)%N eqn:B2;
        [apply N.eqb_eq in B2; subst o2; injection H as <-;
         split; [lia|reflexivity]|].
      destruct (o2 =? 1)%N eqn:B1;
        [apply N.eqb_eq in B1; subst o2; injection H as <-;
         split; [lia|reflexivity]|discriminate].
    + apply N.eqb_neq in Q7.
      assert (Ho456 : o = 4 \/ o = 5 \/ o = 6) by lia.
      destruct ((z2 =? 2) && (c2 =? 1))%N eqn:Ef.
      * apply andb_prop in Ef. destruct Ef as [Ez2 Ec2].
        apply N.eqb_eq in Ez2. apply N.eqb_eq in Ec2. subst z2 c2.
        destruct ((5 <=? o2) && (o2 <=? 7))%N eqn:R1.
        -- apply andb_prop in R1. destruct R1 as [L5 L7].
           apply N.leb_le in L5. apply N.leb_le in L7.
           assert (Ho2 : o2 = 5 \/ o2 = 6 \/ o2 = 7) by lia.
           destruct Ho456 as [Ha|[Ha|Ha]]; destruct Ho2 as [Hb|[Hb|Hb]];
             subst o o2; injection H as <-; (split; [lia|reflexivity]).
        -- destruct ((1 <=? o2) && (o2 <=? 3))%N eqn:R2.
           ++ apply andb_prop in R2. destruct R2 as [L1 L3].
              apply N.leb_le in L1. apply N.leb_le in L3.
              assert (Ho2 : o2 = 1 \/ o2 = 2 \/ o2 = 3) by lia.
              destruct Ho456 as [Ha|[Ha|Ha]]; destruct Ho2 as [Hb|[Hb|Hb]];
                subst o o2; injection H as <-; (split; [lia|reflexivity]).
           ++ destruct ((o2 =? 4) && (2 =? 2))%N eqn:R3; [|discriminate].
              apply andb_prop in R3. destruct R3 as [L4 _].
              apply N.eqb_eq in L4. subst o2.
              destruct Ho456 as [Ha|[Ha|Ha]];
                subst o; injection H as <-; (split; [lia|reflexivity]).
      * destruct ((o2 =? 4) && (z2 =? 2))%N eqn:R3; [|discriminate].
        apply andb_prop in R3. destruct R3 as [L4 L2].
        apply N.eqb_eq in L4. apply N.eqb_eq in L2. subst o2 z2.
        destruct Ho456 as [Ha|[Ha|Ha]];
          subst o; injection H as <-; (split; [lia|reflexivity]).
Qed.
Lemma skipn_add : forall (w : word) a b,
  skipn b (skipn a w) = skipn (a + b) w.
Proof.
  intros w a. revert w. induction a as [|a IH]; intros w b; [reflexivity|].
  destruct w as [|x t]; cbn [skipn Nat.add].
  - destruct b; reflexivity.
  - apply IH.
Qed.
Lemma skipn_ne : forall (w : word) k,
  (k < length w)%nat -> skipn k w <> [].
Proof.
  intros w k Hk E.
  assert (length (skipn k w) = O) by (rewrite E; reflexivity).
  rewrite length_skipn in *. lia.
Qed.
Lemma site_layout : forall w i p gb,
  detect_phase w i = Some p ->
  wat w (i + phase_len p)%nat = Some gb ->
  Nat.eqb (S (i + phase_len p)) (length w) = false ->
  w = firstn i w ++ phase_form p
        ++ gb :: skipn (S (i + phase_len p)) w
  /\ length (firstn i w) = i
  /\ skipn (S (i + phase_len p)) w <> [].
Proof.
  intros w i p gb HD HW HE.
  destruct (detect_phase_form w i p HD) as (Hp & HF).
  assert (Hlt : (i + phase_len p < length w)%nat).
  { unfold wat in HW. apply nth_error_Some. rewrite HW. discriminate. }
  apply PeanoNat.Nat.eqb_neq in HE.
  split; [|split].
  - rewrite <- (firstn_skipn i w) at 1. f_equal.
    rewrite <- (firstn_skipn (phase_len p) (skipn i w)) at 1.
    rewrite HF. f_equal. rewrite skipn_add.
    apply (LineageBulk_skipn_wat w _ gb HW).
  - rewrite length_firstn. lia.
  - apply skipn_ne. lia.
Qed.
Lemma lin_bulk_checks : forall sg w j p t r,
  lin_bulk sg w j p t = Some r ->
  exists gb, wat w (j + phase_len p)%nat = Some gb
          /\ keyi sg gb = None
          /\ lvl_big gb = true
          /\ (FLOOR + DBu p <= gC gb)%N
          /\ Nat.eqb (S (j + phase_len p)) (length w) = false.
Proof.
  intros sg w j p t r H. unfold lin_bulk in H. cbv zeta in H.
  destruct (wat w (j + phase_len p)%nat) as [gb|] eqn:EW;
    [|discriminate].
  exists gb. split; [reflexivity|].
  destruct (ph sg gb) eqn:EP; [discriminate|].
  split; [unfold ph in EP;
          destruct (keyi sg gb); [discriminate|reflexivity]|].
  destruct (negb (lvl_big gb)) eqn:EB; [discriminate|].
  apply negb_false_iff in EB. split; [exact EB|].
  destruct (negb (erode_safe p gb)) eqn:ER; [discriminate|].
  apply negb_false_iff in ER. split.
  - unfold erode_safe in ER. apply N.leb_le. exact ER.
  -
  destruct (Nat.eqb (S (j + phase_len p)) (length w)) eqn:EE;
    [discriminate|reflexivity].
Qed.
Lemma bulk_full_zero_lt28 : forall p t,
  Nat.eqb (N.to_nat ((p+t)/28)) O = true -> (p+t < 28)%N.
Proof.
  intros p t H. apply PeanoNat.Nat.eqb_eq in H.
  assert (HD : ((p+t)/28 = 0)%N).
  { apply N2Nat.inj. cbn [N.to_nat]. exact H. }
  pose proof (N.div_mod' (p+t) 28) as EDM.
  pose proof (N.mod_lt (p+t) 28 ltac:(lia)) as HM.
  rewrite HD in EDM. cbn in EDM. lia.
Qed.
Fixpoint dtickN (k : nat) (w : word) (f : N) : option (word * N) :=
  match k with
  | O => Some (w, f)
  | S k' => match dtick w f with
            | Some (w2, f2) => dtickN k' w2 f2
            | None => None
            end
  end.
Lemma bump_groups_ph : forall sg xs g,
  ph (bump_groups sg xs) g = ph sg g.
Proof.
  intros sg xs g. unfold ph.
  destruct (keyi sg g) as [s|] eqn:Ek.
  - destruct (keyi (bump_groups sg xs) g) eqn:Ef; [reflexivity|].
    exfalso.
    rewrite (keyi_none_same_keys (bump_groups sg xs) sg g
               (eq_sym (bump_groups_keys sg xs)) Ef) in Ek. discriminate.
  - now rewrite (bump_groups_keyi_none sg xs g Ek).
Qed.
Lemma phshape_adj4 : forall g,
  phshape (adj4 g) = phshape g.
Proof.
  intros [[o z] c]. unfold adj4, phshape, PHO.
  cbn [gO gZ gC].
  destruct ((o =? 4) && (z =? 2))%N eqn:E; [|reflexivity].
  apply andb_prop in E as [Eo _]. apply N.eqb_eq in Eo. subst o.
  reflexivity.
Qed.
Lemma ph_adj4 : forall sg g,
  ph sg (adj4 g) = ph sg g.
Proof.
  intros sg g. destruct (phshape g) eqn:EP.
  - now rewrite (adj4_tag_id g EP).
  - unfold ph, keyi. rewrite phshape_adj4, EP. reflexivity.
Qed.
Lemma countkey_map_adj4p : forall sg sg' xs s,
  In s sg ->
  (forall g, ph sg' g = ph sg g) ->
  countkey (sKey s) (List.map (adj4p sg') xs)
  = countkey (sKey s) xs.
Proof.
  intros sg sg' xs s Hin Hph.
  induction xs as [|g xs IH]; [reflexivity|].
  cbn [List.map countkey].
  assert (IHx : countkey (sKey s)
                  (List.map (adj4p sg') xs)
                = countkey (sKey s) xs)
    by exact IH.
  destruct (ph sg g) eqn:EP.
  - assert (Hg : adj4p sg' g = g)
      by (unfold adj4p; rewrite Hph, EP; reflexivity).
    rewrite Hg, IHx. reflexivity.
  - assert (Hg : adj4p sg' g = adj4 g)
      by (unfold adj4p; rewrite Hph, EP; reflexivity).
    rewrite Hg, IHx.
    assert (Z1 : countkey (sKey s) [g] = O).
    { apply (countkey_nonph_zero sg [g] s); [|exact Hin].
      intros x Hx. destruct Hx as [<-|F]; [exact EP|contradiction]. }
    assert (Z2 : countkey (sKey s)
                   [adj4 g] = O).
    { apply (countkey_nonph_zero sg
               [adj4 g] s); [|exact Hin].
      intros x Hx. destruct Hx as [<-|F];
        [rewrite ph_adj4; exact EP|contradiction]. }
    cbn [countkey] in Z1, Z2.
    destruct (phshape (adj4 g)
              && (gC (adj4 g) =? sKey s))%N;
      destruct (phshape g && (gC g =? sKey s))%N;
      cbn in Z1, Z2 |- *; lia.
Qed.
Lemma ph_nolvl : forall sg x,
  forallb (fun g => negb (phshape g)) x = true ->
  forall g, In g x -> ph sg g = false.
Proof.
  intros sg x H g Hin. eapply forallb_forall in H; [|exact Hin].
  apply negb_true_iff in H. unfold ph, keyi. now rewrite H.
Qed.
Lemma ck1_zero : forall sg s g,
  In s sg -> ph sg g = false ->
  countkey (sKey s) [g] = O.
Proof.
  intros sg s g Hin Hp.
  apply (countkey_nonph_zero sg [g] s); [|exact Hin].
  intros x Hx. destruct Hx as [<-|F]; [exact Hp|contradiction].
Qed.
Lemma ck_nolvl_zero : forall sg s x,
  In s sg -> forallb (fun g => negb (phshape g)) x = true ->
  countkey (sKey s) x = O.
Proof.
  intros sg s x Hin H.
  apply (countkey_nonph_zero sg x s);
    [exact (ph_nolvl sg x H)|exact Hin].
Qed.
Theorem lin_ok_cross : forall sg w j p t w' sg' nh rem emit gb pre post,
  lin_ok sg w = true ->
  is_spc (nth O w d0) = false ->
  w = pre ++ phase_form p ++ gb :: post ->
  length pre = j -> post <> [] -> keyi sg gb = None ->
  (p < 28)%N ->
  Nat.eqb (N.to_nat ((p+t)/28)) O = false ->
  lin_bulk sg w j p t = Some (w', sg', nh, rem, emit) ->
  lin_ok sg' w' = true.
Proof.
  intros sg w j p t w' sg' nh rem emit gb pre post
    Hok H0 Hw Hj Hpost Hgb Hp Hfull HB.
  destruct (lin_bulk_pieces sg w j p t w' sg' nh rem emit gb pre post
              Hw Hj Hpost Hgb Hp H0 Hfull HB)
    as (left & used & sp & hd & rest0 & cgb & EC & EM & Hpre2 & Hnh
        & Hgbs & Hcgbf & Hrem & Hemit & Heph & Hw').
  assert (Hsg' : sg' = bump_groups sg used)
    by exact (gclimb_bump_groups _ _ _ _ _ _ _ _ EC).
  rewrite Hsg', (lin_ok_of_keys (bump_groups sg used) sg w'
                   (bump_groups_keys sg used)).
  assert (Hspc : is_spc sp = true).
  { pose proof (gclimb_last_spc _ _ _ _ _ _ _ _ EC) as HS.
    rewrite EM in HS. exact HS. }
  assert (Ehd : keyi sg hd = None).
  { apply (keyi_none_same_keys (bump_groups sg used) sg hd
             (eq_sym (bump_groups_keys sg used))).
    unfold ph in Heph. rewrite Hsg' in Heph.
    destruct (keyi (bump_groups sg used) hd);
      [discriminate|reflexivity]. }
  assert (HX : ph sg (gO hd, gZ hd,
                 (gC hd + DBu rem) - 3)%N = false).
  { assert (EL : lvl_big hd = true).
    { eapply gclimb_last_nonph_lvl; [exact EC|exact EM|exact Heph]. }
    destruct (lvl_big_shape hd EL) as (ch & ->). reflexivity. }
  assert (HY : ph sg (4,2,(cgb - 1) - DBu p)%N = false).
  { reflexivity. }
  assert (DW : w = rev left ++ ([sp] ++ ([hd] ++ (rest0
                 ++ (phase_form p ++ ([gb] ++ post)))))).
  { rewrite Hw, Hpre2. rewrite <- !app_assoc. cbn [app]. reflexivity. }
  assert (DW' : w' = rev left ++ (phase_form rem
                 ++ ([(gO hd, gZ hd,
                       (gC hd + DBu rem) - 3)%N]
                     ++ (List.map (adj4p sg') rest0
                         ++ ([(8,2,1)%N]
                             ++ ([(4,2,(cgb - 1) - DBu p)%N]
                                 ++ post)))))).
  { rewrite Hw'. rewrite <- !app_assoc. cbn [app].
    rewrite <- !app_assoc. cbn [app]. reflexivity. }
  unfold lin_ok in Hok |- *.
  apply forallb_forall. intros s Hs.
  eapply forallb_forall in Hok; [|exact Hs].
  apply PeanoNat.Nat.eqb_eq in Hok. apply PeanoNat.Nat.eqb_eq.
  rewrite DW in Hok. rewrite DW'.
  rewrite !countkey_app in Hok |- *.
  rewrite (ck1_zero sg s sp Hs (ltac:(unfold ph;
             now rewrite (is_spc_keyi_none sg sp Hspc)))) in Hok.
  rewrite (ck1_zero sg s hd Hs (ltac:(unfold ph;
             now rewrite Ehd))) in Hok.
  rewrite (ck1_zero sg s gb Hs (ltac:(unfold ph;
             now rewrite Hgb))) in Hok.
  rewrite (ck_nolvl_zero sg s (phase_form p) Hs
             (phase_form_nolvl p Hp)) in Hok.
  pose proof (ck1_zero sg s _ Hs HX) as ZX. xput ZX.
  pose proof (ck1_zero sg s _ Hs HY) as ZY. xput ZY.
  pose proof (ck1_zero sg s (8,2,1)%N Hs eq_refl) as Z8. xput Z8.
  pose proof (ck_nolvl_zero sg s (phase_form rem) Hs
             (phase_form_nolvl rem
                (ltac:(rewrite Hrem; apply N.mod_lt; lia)))) as ZP.
  xput ZP.
  assert (HPH : forall g, ph sg' g = ph sg g)
    by (intros g; rewrite Hsg'; apply bump_groups_ph).
  pose proof (countkey_map_adj4p sg sg' rest0 s Hs HPH) as ZM.
  xput ZM.
  lia.
Qed.
Open Scope N_scope.
Open Scope bool_scope.
Opaque LROUND_FUEL LROUND_CHUNKS
       FLAT_ROUND_FUEL CFUEL TRIES.
Lemma phseq_notag_nil : forall w,
  forallb notag w = true -> phseq w = [].
Proof.
  intros w. induction w as [|g w IH]; intros H; [reflexivity|].
  cbn [forallb] in H. apply andb_prop in H as [Hg Hw].
  cbn [phseq]. unfold notag in Hg.
  apply negb_true_iff in Hg. rewrite Hg. exact (IH Hw).
Qed.
Lemma phseq_phase_form_nil : forall p,
  (p < 28)%N -> phseq (phase_form p) = [].
Proof.
  intros p Hp. apply phseq_notag_nil.
  exact (phase_form_nolvl p Hp).
Qed.
Lemma adj4p_tag_id : forall sg g,
  phshape g = true -> adj4p sg g = g.
Proof.
  intros sg g HP. unfold adj4p.
  destruct (ph sg g); [reflexivity|].
  exact (adj4_tag_id g HP).
Qed.
Lemma phshape_adj4p : forall sg g,
  phshape (adj4p sg g) = phshape g.
Proof.
  intros sg g. unfold adj4p.
  destruct (ph sg g); [reflexivity|].
  apply phshape_adj4.
Qed.
Lemma phseq_map_adj4p : forall sg w,
  phseq (List.map (adj4p sg) w)
  = phseq w.
Proof.
  intros sg w. induction w as [|g w IH]; [reflexivity|].
  cbn [List.map phseq]. rewrite phshape_adj4p.
  destruct (phshape g) eqn:EP.
  - rewrite (adj4p_tag_id sg g EP), IH. reflexivity.
  - exact IH.
Qed.
Lemma lin_bulk_cross_phseq : forall sg w j p t w' sg' nh rem emit gb pre post,
  is_spc (nth O w d0) = false ->
  w = pre ++ phase_form p ++ gb :: post ->
  length pre = j -> post <> [] -> keyi sg gb = None ->
  (p < 28)%N ->
  Nat.eqb (N.to_nat ((p+t)/28)) O = false ->
  lin_bulk sg w j p t = Some (w', sg', nh, rem, emit) ->
  phseq w' = phseq w.
Proof.
  intros sg w j p t w' sg' nh rem emit gb pre post
    H0 Hw Hj Hpost Hgb Hp Hfull HB.
  destruct (lin_bulk_pieces sg w j p t w' sg' nh rem emit
    gb pre post Hw Hj Hpost Hgb Hp H0 Hfull HB)
    as (left & used & sp & hd & rest0 & cgb & EC & EM & Hpre2 & Hnh
        & Hgbs & Hcgbf & Hrem & Hemit & Heph & Hw').
  assert (Hspc : is_spc sp = true).
  { pose proof (gclimb_last_spc _ _ _ _ _ _ _ _ EC) as HS.
    rewrite EM in HS. exact HS. }
  assert (Hsp : phshape sp = false).
  { apply negb_true_iff. exact (spc_notag sp Hspc). }
  assert (HL : lvl_big hd = true).
  { eapply gclimb_last_nonph_lvl;
      [exact EC|exact EM|exact Heph]. }
  destruct (lvl_big_shape hd HL) as (ch & Ehd).
  assert (Hr : (rem < 28)%N).
  { rewrite Hrem. apply N.mod_lt. lia. }
  rewrite Hw, Hpre2, Hw', Ehd, Hgbs.
  repeat rewrite phseq_app.
  rewrite (phseq_phase_form_nil p Hp), (phseq_phase_form_nil rem Hr).
  cbn [phseq gO gZ gC].
  rewrite Hsp.
  repeat rewrite phshape_onot9 by reflexivity.
  repeat rewrite phseq_app.
  rewrite phseq_map_adj4p.
  cbn [phseq].
  repeat rewrite phshape_onot9 by reflexivity.
  try rewrite !app_nil_r; try rewrite !app_nil_l; try rewrite app_assoc;
    reflexivity.
Qed.
Lemma segshape_bump : forall s,
  segshape (bump_pend s) = segshape s.
Proof. intros [[[[[[k p] m] l] bf] bb] cs]. reflexivity. Qed.
Lemma segpos_bump_of_cross : forall s,
  can_cross s = true ->
  segpos (bump_pend s) = true.
Proof.
  intros [[[[[[k p] m] l] bf] bb] cs] H.
  unfold can_cross in H. apply N.leb_le in H.
  unfold segpos, bump_pend.
  cbn [sPend sMin]. apply N.leb_le.
  unfold FLOOR in H |- *.
  cbn [sPend sMin] in H.
  lia.
Qed.
Lemma SGS_sgset_bump : forall sg s,
  SGS sg -> In s sg ->
  SGS
    (sgset sg (sKey s) (bump_pend s)).
Proof.
  intros sg s HS Hin.
  destruct (SGS_in sg s HS Hin) as (HC & HO & HShape).
  apply SGS_sgset.
  - exact HS.
  - now rewrite segcache_bump.
  - now rewrite segok_bump.
  - now rewrite segshape_bump.
Qed.
Lemma SGP_sgset_bump : forall sg s,
  SGP sg -> In s sg -> can_cross s = true ->
  SGP
    (sgset sg (sKey s) (bump_pend s)).
Proof.
  intros sg s HP _ HC. apply SGP_sgset; [exact HP|].
  exact (segpos_bump_of_cross s HC).
Qed.
Lemma gclimb_tables : forall fu sg rw need top left used sg',
  gclimb fu sg rw need top = Some (left, used, sg') ->
  SGS sg -> SGP sg ->
  keys_big sg ->
  SGS sg' /\ SGP sg' /\
  keys_big sg'.
Proof.
  intros fu. induction fu as [|fu IH];
    intros sg rw need top left used sg' H HS HP HK; [discriminate|].
  cbn [gclimb] in H.
  destruct (Nat.eqb need O);
    [injection H as <- <- <-; repeat split; assumption|].
  destruct rw as [|l [|s rest]]; try discriminate.
  destruct (negb (is_spc s)); [discriminate|].
  destruct (keyi sg l) as [s0|] eqn:Ekl.
  - destruct top; [discriminate|].
    destruct (negb (can_cross s0)) eqn:EC; [discriminate|].
    apply negb_false_iff in EC.
    destruct (Nat.ltb need (segl s0)); [discriminate|].
    destruct (gclimb fu
      (sgset sg (sKey s0) (bump_pend s0))
      rest (need - segl s0) false) as [[[l1 u1] g1]|] eqn:ER;
      [|discriminate].
    injection H as <- <- <-.
    assert (Hin : In s0 sg)
      by exact (keyi_some_in sg l s0 Ekl).
    assert (HS1 : SGS
      (sgset sg (sKey s0) (bump_pend s0)))
      by exact (SGS_sgset_bump sg s0 HS Hin).
    assert (HP1 : SGP
      (sgset sg (sKey s0) (bump_pend s0)))
      by exact (SGP_sgset_bump sg s0 HP Hin EC).
    assert (HK1 : keys_big
      (sgset sg (sKey s0) (bump_pend s0))).
    { eapply keys_big_map_eq; [|exact HK].
      apply sgset_keys. apply sKey_bump. }
    exact (IH _ _ _ _ _ _ _ ER HS1 HP1 HK1).
  - destruct (negb (lit_crossable l)); [discriminate|].
    destruct (gclimb fu sg rest (need - 1) false)
      as [[[l1 u1] g1]|] eqn:ER; [|discriminate].
    injection H as <- <- <-.
    exact (IH _ _ _ _ _ _ _ ER HS HP HK).
Qed.
Lemma lin_bulk_cross_tables : forall sg w j p t w' sg' nh rem emit gb pre post,
  sg_wf sg -> sg_shape sg ->
  keys_big sg -> SGP sg ->
  is_spc (nth O w d0) = false ->
  w = pre ++ phase_form p ++ gb :: post ->
  length pre = j -> post <> [] -> keyi sg gb = None ->
  (p < 28)%N ->
  Nat.eqb (N.to_nat ((p+t)/28)) O = false ->
  lin_bulk sg w j p t = Some (w', sg', nh, rem, emit) ->
  sg_wf sg' /\ sg_shape sg' /\
  keys_big sg' /\ SGP sg'.
Proof.
  intros sg w j p t w' sg' nh rem emit gb pre post
    HW HShape HK HP H0 Hw Hj Hpost Hgb Hp Hfull HB.
  destruct (lin_bulk_pieces sg w j p t w' sg' nh rem emit
    gb pre post Hw Hj Hpost Hgb Hp H0 Hfull HB)
    as (left & used & sp & hd & rest0 & cgb & EC & EM & Hpre2 & Hnh
        & Hgbs & Hcgbf & Hrem & Hemit & Heph & Hw').
  destruct (gclimb_tables _ _ _ _ _ _ _ _ EC
              (SGS_of sg HW HShape) HP HK)
    as (HS2 & HP2 & HK2).
  split; [exact (SGS_wf sg' HS2)|].
  split; [exact (SGS_shape sg' HS2)|].
  split; assumption.
Qed.
Lemma lin_bulk_cross_front_repr : forall sg w j p t w' sg' nh rem emit
                                         gb pre post,
  front_repr sg w ->
  is_spc (nth O w d0) = false ->
  w = pre ++ phase_form p ++ gb :: post ->
  length pre = j -> post <> [] -> keyi sg gb = None ->
  (p < 28)%N ->
  Nat.eqb (N.to_nat ((p+t)/28)) O = false ->
  lin_bulk sg w j p t = Some (w', sg', nh, rem, emit) ->
  front_repr sg' w'.
Proof.
  intros sg w j p t w' sg' nh rem emit gb pre post
    [HOk HPT] H0 Hw Hj Hpost Hgb Hp Hfull HB.
  assert (ESeq : phseq w' = phseq w)
    by (eapply lin_bulk_cross_phseq; eassumption).
  split.
  - exact (lin_ok_cross sg w j p t w' sg' nh rem emit
      gb pre post HOk H0 Hw Hj Hpost Hgb Hp Hfull HB).
  - destruct (lin_bulk_pieces sg w j p t w' sg' nh rem emit
      gb pre post Hw Hj Hpost Hgb Hp H0 Hfull HB)
      as (left & used & sp & hd & rest0 & cgb & EC & EM & Hpre2 & Hnh
          & Hgbs & Hcgbf & Hrem & Hemit & Heph & Hw').
    assert (Hsg' : sg' = bump_groups sg used)
      by exact (gclimb_bump_groups _ _ _ _ _ _ _ _ EC).
    apply (lin_ptags_of_phseq_eq sg' w w' ESeq).
    eapply lin_ptags_mono; [|exact HPT].
    intros g Hg. rewrite Hsg', bump_groups_ph. exact Hg.
Qed.
Lemma lin_bulk_cross_of_detect : forall sg w j p t w' sg' nh rem emit,
  front_repr sg w ->
  is_spc (nth O w d0) = false ->
  detect_phase w j = Some p ->
  Nat.eqb (N.to_nat ((p+t)/28)) O = false ->
  lin_bulk sg w j p t = Some (w', sg', nh, rem, emit) ->
  front_repr sg' w'.
Proof.
  intros sg w j p t w' sg' nh rem emit HR H0 HD Hfull HB.
  destruct (lin_bulk_checks sg w j p t _ HB)
    as (gb & EW & EK & EL & _ & EE).
  destruct (site_layout w j p gb HD EW EE)
    as (HL & HLen & HNe).
  destruct (detect_phase_form w j p HD) as (Hp & _).
  exact (lin_bulk_cross_front_repr sg w j p t w' sg' nh rem emit gb
    (firstn j w) (skipn (S (j + phase_len p)) w)
    HR H0 HL HLen HNe EK Hp Hfull HB).
Qed.
Lemma lin_bulk_partial_phseq : forall sg w j p t w' sg' nh rem emit,
  (p + t < 28)%N ->
  detect_phase w j = Some p ->
  lin_bulk sg w j p t = Some (w', sg', nh, rem, emit) ->
  sg' = sg /\ phseq w' = phseq w.
Proof.
  intros sg w j p t w' sg' nh rem emit Hpt HD HB.
  destruct (lin_bulk_checks sg w j p t _ HB)
    as (gb & EW & EK & EL & _ & EE).
  assert (Hfull : Nat.eqb (N.to_nat ((p+t)/28)) O = true).
  { rewrite (N.div_small (p+t) 28) by lia. reflexivity. }
  destruct (lin_bulk_partial_out sg w j p t w' sg' nh rem
    emit gb Hfull HB EW) as (Esg & Enh & Erem & Eemit & Ew').
  destruct (site_layout w j p gb HD EW EE)
    as (HL & HLen & HNe).
  destruct (detect_phase_form w j p HD) as (Hp & _).
  destruct (lvl_big_shape gb EL) as (cgb & Egb).
  set (PRE := firstn j w) in *.
  set (RST := skipn (S (j + phase_len p)) w) in *.
  assert (Hr : ((p+t) mod 28 < 28)%N) by (apply N.mod_lt; lia).
  assert (Hplen : length (phase_form p) = phase_len p)
    by (apply phase_form_len; exact Hp).
  assert (EW2 : w' = PRE ++ phase_form ((p+t) mod 28)
                    ++ (4,2,(cgb + DBu ((p+t) mod 28))
                             - DBu p)%N :: RST).
  { rewrite Ew'. rewrite HL at 1. rewrite Egb.
    rewrite <- HLen, <- Hplen. apply subst_site. }
  split; [exact Esg|].
  rewrite EW2, HL, Egb.
  repeat rewrite phseq_app.
  rewrite (phseq_phase_form_nil p Hp),
          (phseq_phase_form_nil ((p+t) mod 28) Hr).
  cbn [phseq].
  repeat rewrite phshape_onot9 by reflexivity.
  try rewrite !app_nil_r; try rewrite !app_nil_l; try rewrite app_assoc;
    reflexivity.
Qed.
Lemma lin_bulk_partial_front_repr : forall sg w j p t w' sg' nh rem emit,
  front_repr sg w ->
  (p + t < 28)%N ->
  detect_phase w j = Some p ->
  lin_bulk sg w j p t = Some (w', sg', nh, rem, emit) ->
  front_repr sg' w'.
Proof.
  intros sg w j p t w' sg' nh rem emit [HOk HPT] Hpt HD HB.
  destruct (lin_bulk_partial_phseq sg w j p t w' sg' nh rem emit Hpt HD HB)
    as [Esg ESeq]. subst sg'. split.
  - exact (lin_ok_of_phseq_eq sg w w' ESeq HOk).
  - exact (lin_ptags_of_phseq_eq sg w w' ESeq HPT).
Qed.
Lemma full_zero_lt28 : forall p t,
  Nat.eqb (N.to_nat ((p+t)/28)) O = true -> (p+t < 28)%N.
Proof.
  intros p t H. apply PeanoNat.Nat.eqb_eq in H.
  assert (HD : ((p+t)/28 = 0)%N).
  { apply N2Nat.inj. cbn [N.to_nat]. exact H. }
  pose proof (N.div_mod' (p+t) 28) as EDM.
  pose proof (N.mod_lt (p+t) 28 ltac:(lia)) as HM.
  rewrite HD in EDM. cbn in EDM. lia.
Qed.
Lemma lin_bulk_front_repr : forall sg w j p t w' sg' nh rem emit,
  front_repr sg w ->
  is_spc (nth O w d0) = false ->
  detect_phase w j = Some p ->
  lin_bulk sg w j p t = Some (w', sg', nh, rem, emit) ->
  front_repr sg' w'.
Proof.
  intros sg w j p t w' sg' nh rem emit HR H0 HD HB.
  destruct (Nat.eqb (N.to_nat ((p+t)/28)) O) eqn:EF.
  - exact (lin_bulk_partial_front_repr sg w j p t w' sg' nh rem emit
      HR (full_zero_lt28 p t EF) HD HB).
  - exact (lin_bulk_cross_of_detect sg w j p t w' sg' nh rem emit
      HR H0 HD EF HB).
Qed.
Lemma lin_bulk_tables : forall sg w j p t w' sg' nh rem emit,
  sg_wf sg -> sg_shape sg ->
  keys_big sg -> SGP sg ->
  is_spc (nth O w d0) = false ->
  detect_phase w j = Some p ->
  lin_bulk sg w j p t = Some (w', sg', nh, rem, emit) ->
  sg_wf sg' /\ sg_shape sg' /\
  keys_big sg' /\ SGP sg'.
Proof.
  intros sg w j p t w' sg' nh rem emit HW HS HK HP H0 HD HB.
  destruct (Nat.eqb (N.to_nat ((p+t)/28)) O) eqn:EF.
  - destruct (lin_bulk_checks sg w j p t _ HB)
      as (gb & EW & EK & EL & _ & EE).
    destruct (lin_bulk_partial_out sg w j p t w' sg' nh rem
      emit gb EF HB EW) as (-> & _). repeat split; assumption.
  - destruct (lin_bulk_checks sg w j p t _ HB)
      as (gb & EW & EK & EL & _ & EE).
    destruct (site_layout w j p gb HD EW EE)
      as (HL & HLen & HNe).
    destruct (detect_phase_form w j p HD) as (Hp & _).
    exact (lin_bulk_cross_tables sg w j p t w' sg' nh rem emit gb
      (firstn j w) (skipn (S (j + phase_len p)) w)
      HW HS HK HP H0 HL HLen HNe EK Hp EF HB).
Qed.
Definition edge_join (a b : word) : Prop :=
  match a, b with
  | [], _ | _, [] => True
  | _, y :: _ => edge_pair (last a d0) y
  end.
Lemma tag_edges_prefix : forall a b,
  tag_edges (a ++ b) -> tag_edges a.
Proof.
  intros a. induction a as [|x [|y a] IH]; intros b H; try exact I.
  cbn [app tag_edges] in H |- *. split; [exact (proj1 H)|].
  exact (IH b (proj2 H)).
Qed.
Lemma tag_edges_app_join : forall a b,
  tag_edges a -> tag_edges b -> edge_join a b ->
  tag_edges (a ++ b).
Proof.
  intros a. induction a as [|x [|y a] IH]; intros b HA HB HJ.
  - exact HB.
  - destruct b as [|z b]; [exact I|].
    cbn [app tag_edges edge_join last] in HJ |- *.
    split; assumption.
  - cbn [app tag_edges] in HA |- *. split; [exact (proj1 HA)|].
    apply IH; [exact (proj2 HA)|exact HB|].
    unfold edge_join in *. destruct b as [|z b]; [exact I|].
    cbn [last]. exact HJ.
Qed.
Lemma adj4p_head_equiv : forall sg g,
  head_equiv (adj4p sg g) g.
Proof.
  intros sg g. unfold head_equiv. split.
  - destruct g as [[o z] c]. unfold adj4p, adj4.
    cbn [gO gZ gC]. destruct (ph sg (o,z,c));
      [reflexivity|]. destruct ((o =? 4) && (z =? 2))%N; reflexivity.
  - split.
    + destruct g as [[o z] c]. unfold adj4p, adj4.
      cbn [gO gZ gC]. destruct (ph sg (o,z,c));
        [reflexivity|]. destruct ((o =? 4) && (z =? 2))%N; reflexivity.
    + apply phshape_adj4p.
Qed.
Lemma tag_edges_map_adj4p : forall sg w,
  tag_edges w ->
  tag_edges (List.map (adj4p sg) w).
Proof.
  intros sg w. induction w as [|a [|b w] IH]; intros HE; try exact I.
  cbn [List.map tag_edges]. split.
  - assert (EA : head_equiv a (adj4p sg a)).
    { destruct (adj4p_head_equiv sg a) as (Ho & Hz & Hp).
      repeat split; symmetry; assumption. }
    assert (EB : head_equiv b (adj4p sg b)).
    { destruct (adj4p_head_equiv sg b) as (Ho & Hz & Hp).
      repeat split; symmetry; assumption. }
    pose proof (edge_pair_head_l a
      (adj4p sg a) b EA (proj1 HE)) as E1.
    exact (edge_pair_head_r (adj4p sg a) b
      (adj4p sg b) EB E1).
  - exact (IH (proj2 HE)).
Qed.
Lemma edge_pair_to_spc : forall a,
  edge_pair a (8,2,1)%N.
Proof.
  intros a. split.
  - intros _. left. split; reflexivity.
  - intros H. rewrite phshape_c1 in H. discriminate.
Qed.
Lemma shape_head_map_adj4p : forall sg w,
  shape_head_free w ->
  shape_head_free (List.map (adj4p sg) w).
Proof.
  intros sg [|g w] H x t E; [discriminate|].
  cbn [List.map] in E. injection E as <- <-.
  rewrite phshape_adj4p. exact (H g w eq_refl).
Qed.
Open Scope N_scope.
Open Scope sym.
Opaque LROUND_FUEL LROUND_CHUNKS
       FLAT_ROUND_FUEL CFUEL TRIES.
Lemma lin_sched_grant_one_eq : forall slot,
  lin_sched_grant_one slot =
  lin_sched_grants slot 1.
Proof.
  intros slot.
  unfold lin_sched_grant_one, lin_sched_grants.
  destruct (slot =? 0)%N eqn:E0.
  - apply N.eqb_eq in E0. subst slot. reflexivity.
  - apply N.eqb_neq in E0.
    rewrite N.div_small; [reflexivity|lia].
Qed.
Lemma lin_sched_slot_advance_one_eq : forall slot,
  lin_sched_slot_advance_one slot =
  lin_sched_slot_advance slot 1.
Proof.
  intros slot.
  unfold lin_sched_slot_advance_one,
    lin_sched_slot_advance.
  destruct (slot =? 0)%N eqn:E0.
  - apply N.eqb_eq in E0. subst slot. reflexivity.
  - apply N.eqb_neq in E0.
    destruct (slot =? 1)%N eqn:E1.
    + apply N.eqb_eq in E1. subst slot. reflexivity.
    + apply N.eqb_neq in E1.
      destruct (slot =? 2)%N eqn:E2.
      * apply N.eqb_eq in E2. subst slot. reflexivity.
      * apply N.eqb_neq in E2.
        replace (3 - slot)%N with 0%N by lia.
        reflexivity.
Qed.
Lemma lin_sched_advance_one_eq : forall fr,
  lin_sched_advance_one fr =
  lin_sched_advance fr 1.
Proof.
  intros fr.
  unfold lin_sched_advance_one, lin_sched_advance.
  rewrite lin_sched_grant_one_eq, lin_sched_slot_advance_one_eq.
  reflexivity.
Qed.
Definition delivery_trip (s : word) (f : N)
    (s' : word) (f' : N) : Prop :=
  exists c p q,
    FTrip c (sdec s f) p q /\
    wconf [] 0 ((1,S p)::q) = wconf [] 0 (sdec s' f').
Inductive deliveries : nat -> word -> N -> word -> N -> Prop :=
  | deliveries_O : forall s f s' f',
      sdec s f = sdec s' f' -> deliveries O s f s' f'
  | deliveries_S : forall n s f s1 f1 s2 f2,
      delivery_trip s f s1 f1 ->
      deliveries n s1 f1 s2 f2 ->
      deliveries (S n) s f s2 f2.
Lemma delivery_trip_sdec_left : forall s0 f0 s f s' f',
  sdec s0 f0 = sdec s f ->
  delivery_trip s f s' f' ->
  delivery_trip s0 f0 s' f'.
Proof.
  intros s0 f0 s f s' f' E (c & p & q & HF & EQ).
  exists c, p, q. rewrite E. auto.
Qed.
Lemma delivery_trip_sdec_right : forall s f s' f' s0 f0,
  sdec s' f' = sdec s0 f0 ->
  delivery_trip s f s' f' ->
  delivery_trip s f s0 f0.
Proof.
  intros s f s' f' s0 f0 E (c & p & q & HF & EQ).
  exists c, p, q. split; [exact HF|now rewrite <- E].
Qed.
Lemma deliveries_sdec_left : forall n s0 f0 s f s' f',
  sdec s0 f0 = sdec s f ->
  deliveries n s f s' f' ->
  deliveries n s0 f0 s' f'.
Proof.
  intros n s0 f0 s f s' f' E H.
  destruct H as [s f s' f' H0|n s f s1 f1 s2 f2 HT HR].
  - apply deliveries_O. now rewrite E.
  - econstructor.
    + exact (delivery_trip_sdec_left _ _ _ _ _ _ E HT).
    + exact HR.
Qed.
Lemma deliveries_sdec_right : forall n s f s' f' s0 f0,
  sdec s' f' = sdec s0 f0 ->
  deliveries n s f s' f' ->
  deliveries n s f s0 f0.
Proof.
  intros n. induction n as [|n IH]; intros s f s' f' s0 f0 E H.
  - inversion H; subst. apply deliveries_O. now rewrite <- E.
  - inversion H; subst.
    econstructor; [eassumption|]. eapply IH; eassumption.
Qed.
Lemma deliveries_app : forall a b s f s1 f1 s2 f2,
  deliveries a s f s1 f1 ->
  deliveries b s1 f1 s2 f2 ->
  deliveries (a + b)%nat s f s2 f2.
Proof.
  intros a b s f s1 f1 s2 f2 HA HB. induction HA.
  - eapply deliveries_sdec_left; [eassumption|exact HB].
  - cbn [Nat.add]. econstructor; eauto.
Qed.
Lemma lin_join_safe_some : forall sg pre sfx out,
  lin_join_safe sg pre sfx = Some out -> out = pre ++ sfx.
Proof.
  intros sg pre. induction pre as [|g pre IH]; intros sfx out H.
  - change ((let '(mid, _) := lin_split_at 6 sfx in
             if lin_nadj_span 6 sg mid
             then Some sfx else None) = Some out) in H.
    destruct (lin_split_at 6 sfx) as [mid post] eqn:ES.
    destruct (lin_nadj_span 6 sg mid) eqn:EN.
    + injection H as Eout. subst out. reflexivity.
    + cbn in H. congruence.
  - destruct pre as [|g1 pre].
    + change ((let '(mid, _) := lin_split_at 5 sfx in
               if lin_nadj_span 6 sg (g::mid)
               then Some (g::sfx) else None) = Some out) in H.
      destruct (lin_split_at 5 sfx) as [mid post] eqn:ES.
      destruct (lin_nadj_span 6 sg (g::mid)) eqn:EN.
      * injection H as Eout. subst out. reflexivity.
      * cbn in H. congruence.
    + destruct pre as [|g2 t].
      * change ((let '(mid, _) := lin_split_at 4 sfx in
                 if lin_nadj_span 6 sg (g::g1::mid)
                 then Some (g::g1::sfx) else None) = Some out) in H.
        destruct (lin_split_at 4 sfx) as [mid post] eqn:ES.
        destruct (lin_nadj_span 6 sg (g::g1::mid)) eqn:EN.
        -- injection H as Eout. subst out. reflexivity.
        -- cbn in H. congruence.
      * change ((match lin_join_safe sg (g1::g2::t) sfx with
                 | Some tail => Some (g::tail)
                 | None => None
                 end) = Some out) in H.
        destruct (lin_join_safe sg (g1::g2::t) sfx)
          as [tail|] eqn:E; [|discriminate].
        injection H as Eout. subst out.
        specialize (IH sfx tail E). subst tail. reflexivity.
Qed.
Lemma lin_at_safe_some : forall sg w center out,
  lin_at_safe sg w center = Some out -> out = w.
Proof.
  intros sg w center out H. unfold lin_at_safe in H.
  destruct (Nat.eqb center O); [now injection H as <-|].
  destruct (lin_nadj_span 6 sg (skipn (center-2) w));
    [now injection H as <-|discriminate].
Qed.
Definition Delivers (n k : nat) (F : word) (f : N)
                    (F' : word) (f' : N) : Prop :=
  exists post, dtickN k (skipn n F) f = Some (post, f')
            /\ F' = firstn n F ++ post.
Lemma dtickN_add : forall a b w f,
  dtickN (a + b) w f
  = match dtickN a w f with
    | Some (w2, f2) => dtickN b w2 f2
    | None => None
    end.
Proof.
  induction a as [|a IH]; intros b w f; [reflexivity|].
  cbn [Nat.add dtickN].
  destruct (dtick w f) as [[w2 f2]|];
    [apply IH|reflexivity].
Qed.
Lemma Delivers_id : forall n F f, Delivers n O F f F f.
Proof.
  intros n F f. exists (skipn n F).
  split; [reflexivity|]. symmetry. apply firstn_skipn.
Qed.
Lemma firstn_len_app : forall (A : Type) (a b : list A),
  firstn (length a) (a ++ b) = a.
Proof.
  intros A a. induction a as [|x a IH]; intros b; [reflexivity|].
  cbn [length app firstn]. now rewrite IH.
Qed.
Lemma LineageCascade_skipn_len_app : forall (A : Type) (a b : list A),
  skipn (length a) (a ++ b) = b.
Proof.
  intros A a. induction a as [|x a IH]; intros b; [reflexivity|].
  cbn [length app skipn]. now rewrite IH.
Qed.
Lemma firstn_prefix_add : forall (A : Type) (pre xs : list A) n,
  firstn (length pre + n) (pre ++ xs) = pre ++ firstn n xs.
Proof.
  intros A pre. induction pre as [|x pre IH]; intros xs n;
    [reflexivity|].
  cbn [length Nat.add app firstn]. f_equal. apply IH.
Qed.
Lemma skipn_prefix_add : forall (A : Type) (pre xs : list A) n,
  skipn (length pre + n) (pre ++ xs) = skipn n xs.
Proof.
  intros A pre. induction pre as [|x pre IH]; intros xs n;
    [reflexivity|].
  cbn [length Nat.add app skipn]. apply IH.
Qed.
Lemma firstn_add_skipn : forall (A : Type) (a d : nat) (xs : list A),
  firstn (a+d) xs = firstn a xs ++ firstn d (skipn a xs).
Proof.
  intros A a. induction a as [|a IH]; intros d xs.
  - reflexivity.
  - destruct xs as [|x xs].
    + cbn [firstn skipn Nat.add app]. now rewrite firstn_nil.
    + cbn [firstn skipn Nat.add app]. f_equal. apply IH.
Qed.
Lemma setsfx_app : forall n (w s : word),
  (n <= length w)%nat ->
  setsfx n w s = firstn n w ++ s.
Proof.
  induction n as [|n IH]; intros w s Hn; [reflexivity|].
  destruct w as [|g t]; [cbn [length] in Hn; lia|].
  cbn [length] in Hn. cbn [setsfx firstn app].
  f_equal. apply IH. lia.
Qed.
Lemma Delivers_comp : forall n a b F f F1 f1 F2 f2,
  (n <= length F)%nat ->
  Delivers n a F f F1 f1 -> Delivers n b F1 f1 F2 f2 ->
  Delivers n (a + b) F f F2 f2.
Proof.
  intros n a b F f F1 f1 F2 f2 Hn (p1 & E1 & ->) (p2 & E2 & ->).
  assert (HL : length (firstn n F) = n)
    by (rewrite length_firstn; lia).
  assert (ESkip : skipn n (firstn n F ++ p1) = p1).
  { rewrite <- HL at 1. apply LineageCascade_skipn_len_app. }
  rewrite ESkip in E2.
  exists p2. split.
  - rewrite dtickN_add, E1. exact E2.
  - assert (EFirst : firstn n (firstn n F ++ p1) = firstn n F).
    { rewrite <- HL at 1. apply firstn_len_app. }
    rewrite EFirst. reflexivity.
Qed.
Lemma flat_cursor : forall sg w cur,
  sg_wf sg -> (cur <= length w)%nat ->
  firstn (fmapw sg w O O cur) (lin_flat sg w)
    = lin_flat sg (firstn cur w)
  /\ skipn (fmapw sg w O O cur) (lin_flat sg w)
    = lin_flat sg (skipn cur w).
Proof.
  intros sg w cur HW Hc.
  rewrite (fmapw_flat_prefix sg w cur HW Hc).
  split; symmetry;
    [apply flat_firstn|apply flat_skipn].
Qed.
Lemma literal_word_flat : forall sg w,
  lin_literal_word w = true -> lin_flat sg w = w.
Proof.
  intros sg w. induction w as [|g w IH]; intros H; [reflexivity|].
  unfold lin_literal_word in H.
  cbn [forallb] in H. apply andb_prop in H as [Hg Hw].
  apply negb_true_iff in Hg.
  rewrite flat_cons_nonlvl by exact Hg.
  f_equal. apply IH. exact Hw.
Qed.
Lemma literal_word_firstn : forall n w,
  lin_literal_word w = true ->
  lin_literal_word (firstn n w) = true.
Proof.
  intros n. induction n as [|n IH]; intros [|g w] H; try reflexivity.
  unfold lin_literal_word in H |- *.
  cbn [forallb firstn] in H |- *. apply andb_prop in H as [Hg Hw].
  apply andb_true_intro. split; [exact Hg|].
  change (lin_literal_word (firstn n w) = true).
  apply IH. exact Hw.
Qed.
Lemma raw_one_delivery : forall w cur cols s f sfx f2,
  seek (skipn cur w) = (cols, s) ->
  dtick_after_seek cols s f = Some (sfx, f2) ->
  Delivers cur 1 w f (firstn cur w ++ sfx) f2.
Proof.
  intros w cur cols s f sfx f2 ESeek HRun.
  exists sfx. split; [|reflexivity].
  cbn [dtickN]. unfold dtick.
  rewrite ESeek, HRun. reflexivity.
Qed.
Lemma lin_dtick_after_seek_proj : forall cols s f renewed out f',
  lin_dtick_after_seek cols s f = Some (renewed, out, f') ->
  dtick_after_seek cols s f = Some (out, f').
Proof.
  intros cols s f renewed out f' H.
  unfold lin_dtick_after_seek in H.
  unfold dtick_after_seek.
  destruct (renew_seg (length s) cols s f)
    as [[body f2]|] eqn:ER.
  - cbn in H. inversion H; subst. reflexivity.
  - remember
      (match s with
       | (o7,z7,c7) :: _ =>
           if (z7 =? 3) && (c7 =? 1)
           then fire_comp (length s) s f
           else if sand_leaf s then None else leaf_act s f
       | [] => leaf_act s f
       end) as dispatch.
    destruct dispatch as [[tail f2]|].
    + cbn in H |- *. inversion H; subst. reflexivity.
    + cbn in H. discriminate.
Qed.
Lemma lin_bottom_sched_zrun_erases : forall q lc sg lw f gap slot lw' f',
  lin_bottom_sched_zrun q lc sg lw f gap slot = Some (lw', f') ->
  lin_bottom_zrun q lc sg lw f = Some (lw', f').
Proof.
  induction q as [|q IH];
    intros lc sg lw f gap slot lw' f' HRun.
  - cbn [lin_bottom_sched_zrun] in HRun.
    cbn [lin_bottom_zrun].
    destruct (lin_literal_word lw); [exact HRun|discriminate].
  - cbn [lin_bottom_sched_zrun] in HRun.
    destruct (lin_literal_word lw) eqn:ELit; [|discriminate].
    destruct (seek (skipn lc lw)) as [cols s] eqn:ESeek.
    destruct s as [|g t]; [discriminate|].
    destruct (lin_dtick_after_seek cols (g::t) f)
      as [[[renewed sfx] f2]|] eqn:ELin; [|discriminate].
    pose proof (lin_dtick_after_seek_proj
      cols (g::t) f renewed sfx f2 ELin) as HStep.
    destruct renewed.
    + destruct (negb (Nat.leb (gap + 2) (lin_flen sg cols)))
        eqn:EGuard; [discriminate|].
      destruct (if Nat.eqb lc O then Some sfx
                else lin_join_safe sg (firstn lc lw) sfx)
        as [lw2|] eqn:EJoin; [|discriminate].
      pose proof (IH lc sg lw2 f2
        (gap - 2 * N.to_nat (lin_sched_grant_one slot))%nat
        (lin_sched_slot_advance_one slot) lw' f' HRun) as HRest.
      cbn [lin_bottom_zrun].
      rewrite ELit, ESeek, HStep, EJoin. exact HRest.
    + destruct (if Nat.eqb lc O then Some sfx
                else lin_join_safe sg (firstn lc lw) sfx)
        as [lw2|] eqn:EJoin; [|discriminate].
      pose proof (IH lc sg lw2 f2
        (gap - 2 * N.to_nat (lin_sched_grant_one slot))%nat
        (lin_sched_slot_advance_one slot) lw' f' HRun) as HRest.
      cbn [lin_bottom_zrun].
      rewrite ELit, ESeek, HStep, EJoin. exact HRest.
Qed.
Lemma lin_bottom_zrun_raw : forall q lc sg lw f lw' f',
  lin_bottom_zrun q lc sg lw f = Some (lw',f') ->
  Delivers lc q lw f lw' f'.
Proof.
  induction q as [|q IH]; intros lc sg lw f lw' f' HRun.
  - cbn [lin_bottom_zrun] in HRun.
    destruct (lin_literal_word lw); [|discriminate].
    injection HRun as <- <-. apply Delivers_id.
  - cbn [lin_bottom_zrun] in HRun.
    destruct (lin_literal_word lw) eqn:ELit; [|discriminate].
    destruct (seek (skipn lc lw)) as [cols s] eqn:ESeek.
    destruct s as [|g t]; [discriminate|].
    destruct (dtick_after_seek cols (g::t) f)
      as [[sfx f2]|] eqn:HStep; [|discriminate].
    destruct (if Nat.eqb lc O then Some sfx
              else lin_join_safe sg (firstn lc lw) sfx)
      as [lw2|] eqn:EJoin; [|discriminate].
    assert (EOut : lw2 = firstn lc lw ++ sfx).
    { destruct (Nat.eqb lc O) eqn:E0.
      - apply PeanoNat.Nat.eqb_eq in E0. subst lc.
        cbn in EJoin. injection EJoin as <-. reflexivity.
      - exact (lin_join_safe_some sg (firstn lc lw) sfx lw2 EJoin). }
    assert (Hne : skipn lc lw <> []).
    { pose proof (LineageGuard_seek_split (skipn lc lw)) as HS.
      rewrite ESeek in HS. cbn [fst snd] in HS.
      rewrite HS. intros E. apply app_eq_nil in E as [_ E]. discriminate. }
    assert (Hcur : (lc <= length lw)%nat).
    { destruct (PeanoNat.Nat.le_gt_cases lc (length lw)); [assumption|].
      exfalso. apply Hne. apply skipn_all2. lia. }
    assert (HOne : Delivers lc 1 lw f lw2 f2).
    { rewrite EOut. exact (raw_one_delivery lw lc cols (g::t)
        f sfx f2 ESeek HStep). }
    pose proof (IH lc sg lw2 f2 lw' f' HRun) as HRest.
    change (S q) with (1 + q)%nat.
    exact (Delivers_comp lc 1 q lw f lw2 f2 lw' f' Hcur HOne HRest).
Qed.
Lemma lin_bottom_zrun_literals : forall q lc sg lw f lw' f',
  lin_bottom_zrun q lc sg lw f = Some (lw',f') ->
  lin_literal_word lw = true /\
  lin_literal_word lw' = true.
Proof.
  induction q as [|q IH]; intros lc sg lw f lw' f' HRun.
  - cbn [lin_bottom_zrun] in HRun.
    destruct (lin_literal_word lw) eqn:EL; [|discriminate].
    injection HRun as <- <-. auto.
  - cbn [lin_bottom_zrun] in HRun.
    destruct (lin_literal_word lw) eqn:EL; [|discriminate].
    destruct (seek (skipn lc lw)) as [cols s].
    destruct s as [|g t]; [discriminate|].
    destruct (dtick_after_seek cols (g::t) f)
      as [[sfx f2]|]; [|discriminate].
    destruct (if Nat.eqb lc O then Some sfx
              else lin_join_safe sg (firstn lc lw) sfx)
      as [lw2|]; [|discriminate].
    destruct (IH lc sg lw2 f2 lw' f' HRun) as [_ HOut].
    split; [reflexivity|exact HOut].
Qed.
Lemma lin_bottom_sched_zrun_raw : forall q lc sg lw f gap slot lw' f',
  lin_bottom_sched_zrun q lc sg lw f gap slot = Some (lw', f') ->
  Delivers lc q lw f lw' f'.
Proof.
  intros q lc sg lw f gap slot lw' f' HRun.
  apply lin_bottom_zrun_raw with (sg := sg).
  exact (lin_bottom_sched_zrun_erases
    q lc sg lw f gap slot lw' f' HRun).
Qed.
Lemma lin_bottom_sched_zrun_literals :
  forall q lc sg lw f gap slot lw' f',
  lin_bottom_sched_zrun q lc sg lw f gap slot = Some (lw', f') ->
  lin_literal_word lw = true /\
  lin_literal_word lw' = true.
Proof.
  intros q lc sg lw f gap slot lw' f' HRun.
  apply lin_bottom_zrun_literals with
    (q := q) (lc := lc) (sg := sg) (f := f) (f' := f').
  exact (lin_bottom_sched_zrun_erases
    q lc sg lw f gap slot lw' f' HRun).
Qed.
Lemma dtick_after_seek_trip : forall cols s f out f',
  forallb (fun g => is_col g && negb (is_cmf g)
                    && (3 <=? gO g)%N) cols = true ->
  dtick_after_seek cols s f = Some (out, f') ->
  delivery_trip (cols ++ s) f out f'.
Proof.
  intros cols s f out f' Hcols H.
  unfold dtick_after_seek in H. cbv beta zeta iota in H.
  destruct (renew_seg (length s) cols s f)
    as [[body f2]|] eqn:ER.
  - inversion H; subst body f2.
    exact (renew_ftrip _ _ _ _ _ _ Hcols ER).
  - destruct s as [|[[o z] c] rest].
    + cbn in H. discriminate.
    + cbv beta iota in H.
      destruct ((z =? 3) && (c =? 1)) eqn:Efire.
      * change
          (match fire_comp (S (length rest))
             (((o,z,c)::rest)%list) f with
           | Some (tail, f2) => Some (cols ++ tail, f2)
           | None => None
           end = Some (out, f')) in H.
        destruct (fire_comp (S (length rest))
            (((o,z,c)::rest)%list) f) as [[tail f2]|] eqn:EF.
        2: discriminate.
        inversion H; subst out f'.
        destruct (fire_comp_ftrip _ _ _ _ _ EF)
          as (ci & pi & qi & HFi & EQi).
        unfold delivery_trip.
        destruct (ren_lift cols (((o,z,c)::rest)%list) tail
          f f2 ci pi qi Hcols HFi EQi)
          as (co & po & qo & HFo & EQo).
        now exists co, po, qo.
      * remember (sand_leaf (((o,z,c)::rest)%list)) as sb eqn:ESand.
        destruct sb.
        -- symmetry in ESand. setoid_rewrite ESand in H. discriminate.
        -- symmetry in ESand. setoid_rewrite ESand in H. cbn in H.
           destruct (leaf_act (((o,z,c)::rest)%list) f)
             as [[tail f2]|] eqn:EL.
           2: { setoid_rewrite EL in H. discriminate. }
           setoid_rewrite EL in H. inversion H; subst out f'.
           destruct (leaf_ftrip _ _ _ _ EL)
             as [(ci & pi & qi & HFi & EQi)|
                 (ci & pi & qi & HSi & EQi & HS & _)].
           ++ unfold delivery_trip.
              destruct (ren_lift cols (((o,z,c)::rest)%list) tail
                f f2 ci pi qi Hcols HFi EQi)
                as (co & po & qo & HFo & EQo).
              now exists co, po, qo.
           ++ rewrite ESand in HS. discriminate.
Qed.
Lemma dtick_after_seek_flat : forall sg cols s f,
  sg_wf sg -> keys_big sg ->
  sg_live sg ->
  (forall t', s = (4%N,3%N,1%N) :: t' ->
     ph_notlast sg cols) ->
  nbrs1z sg s ->
  (forall g t, s = g :: t -> ph sg g = false) ->
  dtick_after_seek (lin_flat sg cols)
                              (lin_flat sg s) f
  = flat_res sg (dtick_after_seek cols s f).
Proof.
  intros sg cols s f HW HK HL HPnC HN Hh.
  unfold dtick_after_seek.
  assert (EREN : renew_seg (length (lin_flat sg s))
                   (lin_flat sg cols) (lin_flat sg s) f
                 = flat_res sg
                     (renew_seg (length s) cols s f)).
  { pose proof (proj2 (fire_renew_flat_z
                         (length (lin_flat sg s)) sg HW HK HL)
                  cols s f HPnC HN Hh) as E0.
    rewrite (renew_seg_sat cols s f
               (length (lin_flat sg s))) in E0.
    - exact E0.
    - exact (flat_len_ge sg s HW). }
  xrewrite EREN.
  destruct (renew_seg (length s) cols s f) as [[body f2]|] eqn:ER;
    repeat (xrewrite ER).
  { cbn [flat_res]. reflexivity. }
  cbn [flat_res]. cbv beta iota.
  destruct s as [|[[o7 z7] c7] st].
  { reflexivity. }
  assert (Hph : ph sg (o7,z7,c7) = false)
    by exact (Hh _ _ eq_refl).
  assert (EF : lin_flat sg ((o7,z7,c7) :: st)
               = (o7,z7,c7) :: lin_flat sg st)
    by (apply flat_cons_nonph; exact Hph).
  xrewrite EF. cbv beta iota.
  destruct ((z7 =? 3) && (c7 =? 1))%N eqn:EZC.
  - assert (EFIR : fire_comp
                     (length ((o7,z7,c7) :: lin_flat sg st))
                     ((o7,z7,c7) :: lin_flat sg st) f
                   = flat_res sg
                       (fire_comp (length ((o7,z7,c7) :: st))
                          ((o7,z7,c7) :: st) f)).
    { pose proof (proj1 (fire_renew_flat_z
                           (length ((o7,z7,c7) :: lin_flat sg st))
                           sg HW HK HL)
                    ((o7,z7,c7) :: st) f HN
                    ltac:(intros g t E; injection E as <- <-; exact Hph))
        as E0.
      xrewrite_in E0 EF.
      rewrite (fire_comp_sat ((o7,z7,c7)::st) f
                 (length ((o7,z7,c7)::lin_flat sg st))) in E0.
      - exact E0.
      - cbn [length]. apply le_n_S.
        exact (flat_len_ge sg st HW). }
    xrewrite EFIR.
    destruct (fire_comp (length ((o7,z7,c7) :: st))
                ((o7,z7,c7) :: st) f) as [[s2 f2]|] eqn:EFC;
      repeat (xrewrite EFC).
    + cbn [flat_res]. cbv beta iota.
      f_equal. f_equal. rewrite lin_flat_app_c. reflexivity.
    + cbn [flat_res]. reflexivity.
  - assert (ESL : sand_leaf ((o7,z7,c7) :: lin_flat sg st)
                  = sand_leaf ((o7,z7,c7) :: st)).
    { pose proof (sand_leaf_flat sg ((o7,z7,c7) :: st) HW
                    ltac:(intros g t E; injection E as <- <-; exact Hph))
        as E0.
      xrewrite_in E0 EF. exact E0. }
    xrewrite ESL.
    destruct (sand_leaf ((o7,z7,c7) :: st)) eqn:ES;
      repeat (xrewrite ES).
    + reflexivity.
    + assert (ELA : leaf_act ((o7,z7,c7) :: lin_flat sg st) f
                    = flat_res sg
                        (leaf_act ((o7,z7,c7) :: st) f)).
      { pose proof (leaf_act_flat_z sg
                      ((o7,z7,c7) :: st) f HW HK HN
                      ltac:(intros g t E; injection E as <- <-; exact Hph))
          as E0.
        xrewrite_in E0 EF. exact E0. }
      xrewrite ELA.
      destruct (leaf_act ((o7,z7,c7) :: st) f)
        as [[s2 f2]|] eqn:EL; repeat (xrewrite EL).
      * cbn [flat_res]. cbv beta iota.
        f_equal. f_equal. rewrite lin_flat_app_c. reflexivity.
      * cbn [flat_res]. reflexivity.
Qed.
Lemma lin_dtick_after_seek_flat_some :
  forall sg cols s f renewed out f',
  sg_wf sg -> keys_big sg ->
  sg_live sg ->
  (forall t', s = (4%N,3%N,1%N) :: t' ->
     ph_notlast sg cols) ->
  nbrs1z sg s ->
  (forall g t, s = g :: t -> ph sg g = false) ->
  lin_dtick_after_seek cols s f = Some (renewed, out, f') ->
  lin_dtick_after_seek (lin_flat sg cols)
    (lin_flat sg s) f
  = Some (renewed, lin_flat sg out, f').
Proof.
  intros sg cols s f renewed out f' HW HK HL HPnC HN Hh HRun.
  assert (EREN : renew_seg (length (lin_flat sg s))
                   (lin_flat sg cols) (lin_flat sg s) f
                 = flat_res sg
                     (renew_seg (length s) cols s f)).
  { pose proof (proj2 (fire_renew_flat_z
                         (length (lin_flat sg s)) sg HW HK HL)
                  cols s f HPnC HN Hh) as E0.
    rewrite (renew_seg_sat cols s f
               (length (lin_flat sg s))) in E0.
    - exact E0.
    - exact (flat_len_ge sg s HW). }
  unfold lin_dtick_after_seek in HRun |- *.
  remember (renew_seg (length s) cols s f) as rr eqn:ER.
  symmetry in ER.
  destruct rr as [[body f2]|].
  - cbn [flat_res] in EREN.
    xrewrite EREN. xrewrite_in HRun ER.
    cbn in HRun.
    inversion HRun. reflexivity.
  - cbn [flat_res] in EREN.
    xrewrite EREN. xrewrite_in HRun ER.
    cbn in HRun |- *.
    remember
      (match s with
       | (o7,z7,c7) :: _ =>
           if (z7 =? 3) && (c7 =? 1)
           then fire_comp (length s) s f
           else if sand_leaf s then None else leaf_act s f
       | [] => leaf_act s f
       end) as dispatch eqn:ED.
    symmetry in ED.
    destruct dispatch as [[tail f2]|].
    2: { xrewrite_in HRun ED. cbn in HRun.
         discriminate HRun. }
    xrewrite_in HRun ED. cbn in HRun. inversion HRun.
    assert (HFlat :
      dtick_after_seek (lin_flat sg cols)
        (lin_flat sg s) f
      = Some (lin_flat sg (cols ++ tail), f2)).
    { rewrite (dtick_after_seek_flat sg cols s f
        HW HK HL HPnC HN Hh).
      unfold dtick_after_seek.
      xrewrite ER. xrewrite ED.
      cbn [flat_res]. reflexivity. }
    unfold dtick_after_seek in HFlat.
    xrewrite_in HFlat EREN.
    cbn in HFlat.
    remember
      (match lin_flat sg s with
       | (o7,z7,c7) :: _ =>
           if (z7 =? 3) && (c7 =? 1)
           then fire_comp (length (lin_flat sg s))
                  (lin_flat sg s) f
           else if sand_leaf (lin_flat sg s)
                then None else leaf_act (lin_flat sg s) f
       | [] => leaf_act (lin_flat sg s) f
       end) as dispatchF.
    destruct dispatchF as [[tailF fF]|]; [|discriminate HFlat].
    cbn in HFlat. inversion HFlat.
    rewrite <- H2. reflexivity.
Qed.
Open Scope N_scope.
Open Scope sym.
Opaque LROUND_FUEL LROUND_CHUNKS
       FLAT_ROUND_FUEL CFUEL TRIES.
Lemma delivery_trip_cols : forall cols s f s' f',
  forallb (fun g => is_col g && negb (is_cmf g)
                    && (3 <=? gO g)%N) cols = true ->
  delivery_trip s f s' f' ->
  delivery_trip (cols ++ s) f (cols ++ s') f'.
Proof.
  intros cols s f s' f' Hcols (c & p & q & HF & EQ).
  destruct (ren_lift cols s s' f f' c p q Hcols HF EQ)
    as (c' & p' & q' & HF' & EQ').
  now exists c', p', q'.
Qed.
Lemma delivery_stage : forall X cY rest tail f f2,
  (5 <= X)%N -> (1 <= cY)%N ->
  delivery_trip rest f tail f2 ->
  delivery_trip
    ((X,3,1)%N :: (4,2,cY)%N :: rest) f
    ((X-1,1,1)%N :: (7,2,1)%N :: (4,2,cY-1)%N :: tail) f2.
Proof.
  intros X cY rest tail f f2 HX HY (ci & pi & qi & HFi & EQi).
  destruct (casc_stage X cY rest tail f f2 ci pi qi
              HX HY HFi EQi) as (c & p & q & HF & EQ).
  now exists c, p, q.
Qed.
Lemma delivery_jump : forall cols sfx tail seg B f f2,
  forallb (fun g => is_col g && negb (is_cmf g)
                    && (3 <=? gO g)%N) cols = true ->
  jump_seg cols B = Some seg -> (1 <= B)%N ->
  delivery_trip sfx f tail f2 ->
  delivery_trip
    (cols ++ (4,3,1)%N :: (4,2,B)%N :: sfx) f
    (seg ++ tail) f2.
Proof.
  intros cols sfx tail seg B f f2 Hcols Hjump HB
    (ci & pi & qi & HFi & EQi).
  destruct (casc_jump_inner cols sfx tail seg B f f2 ci pi qi
              Hcols Hjump HB HFi EQi) as (c & p & q & HF & EQ).
  now exists c, p, q.
Qed.
Lemma deliveries_zero_sdec : forall s f s' f',
  deliveries O s f s' f' ->
  sdec s f = sdec s' f'.
Proof. intros s f s' f' H. inversion H. assumption. Qed.
Lemma deliveries_one_trip : forall s f s' f',
  deliveries 1 s f s' f' ->
  delivery_trip s f s' f'.
Proof.
  intros s f s' f' H. dependent destruction H. dependent destruction H0.
  eapply delivery_trip_sdec_right; eauto.
Qed.
Lemma deliveries_split : forall a b s f s' f',
  deliveries (a+b)%nat s f s' f' ->
  exists sm fm,
    deliveries a s f sm fm /\
    deliveries b sm fm s' f'.
Proof.
  induction a as [|a IH]; intros b s f s' f' H.
  - exists s, f. split.
    + apply deliveries_O. reflexivity.
    + exact H.
  - cbn [Nat.add] in H. dependent destruction H.
    destruct (IH b _ _ _ _ H0) as (sm & fm & HA & HB).
    exists sm, fm. split.
    + eapply deliveries_S; [exact H|exact HA].
    + exact HB.
Qed.
Lemma leaf_delivery : forall p c rest f,
  (p < 28)%N -> emits p = false -> (2 <= c)%N ->
  delivery_trip
    (phase_form p ++ (4,2,c)%N :: rest) f
    (phase_form (p+1) ++
       (4,2,c + DBu (p+1) - DBu p)%N :: rest) f.
Proof.
  intros p c rest f Hp Hem Hc.
  pose proof (leaf_tick p c rest f Hp Hem Hc) as HL.
  destruct (leaf_ftrip _ _ _ _ HL)
    as [(ci & pi & qi & HF & EQ)|
        (ci & pi & qi & HS & EQ & Hsand & Hrest)].
  - now exists ci, pi, qi.
  - destruct (leaf_phase_head p Hp Hem)
      as (x & tail & Ephase).
    rewrite Ephase in Hsand. cbn [app] in Hsand.
    rewrite sand_leaf_z1 in Hsand. discriminate.
Qed.
Lemma marks_delta_zero : forall p,
  (p < 27)%N -> emits p = false ->
  N.to_nat (marks (p+1) - marks p) = O.
Proof.
  intros p Hp Hem. assert (Hp28 : (p < 28)%N) by lia.
  pose proof (emits_is_the_marks_jump p Hp28) as E.
  rewrite E in Hem. apply negb_false_iff in Hem. apply N.eqb_eq in Hem.
  rewrite Hem, N.sub_diag. reflexivity.
Qed.
Lemma phase_tick_delivery : forall p c rest tail f f',
  (p < 27)%N -> (2 <= c)%N ->
  deliveries
    (N.to_nat (marks (p+1) - marks p))
    rest f tail f' ->
  delivery_trip
    (phase_form p ++ (4,2,c)%N :: rest) f
    (phase_form (p+1) ++
       (4,2,c + DBu (p+1) - DBu p)%N :: tail) f'.
Proof.
  intros p c rest tail f f' Hp Hc HD.
  assert (Hp28 : (p < 28)%N) by lia.
  destruct (emits p) eqn:Hem.
  - destruct (emits_nonjump p Hp28 Hem ltac:(lia))
      as [E|[E|E]]; subst p;
      cbn [marks EMt] in HD |- *;
      pose proof (deliveries_one_trip _ _ _ _ HD) as HT.
    + pose proof (delivery_stage 7 c rest tail f f'
        ltac:(lia) ltac:(lia) HT) as HS.
      eapply delivery_trip_sdec_right; [|exact HS].
      normgen. cbn [app].
      replace (c + 2 - 3)%N with (c-1)%N by lia. reflexivity.
    + pose proof (delivery_stage 6 c rest tail f f'
        ltac:(lia) ltac:(lia) HT) as HS.
      eapply delivery_trip_sdec_right; [|exact HS].
      normgen. cbn [app].
      replace (c + 1 - 2)%N with (c-1)%N by lia. reflexivity.
    + pose proof (delivery_stage 5 c rest tail f f'
        ltac:(lia) ltac:(lia) HT) as HS.
      eapply delivery_trip_sdec_right; [|exact HS].
      normgen. cbn [app].
      replace (c + 0 - 1)%N with (c-1)%N by lia. reflexivity.
  - rewrite (marks_delta_zero p Hp Hem) in HD.
    pose proof (deliveries_zero_sdec _ _ _ _ HD) as HE.
    pose proof (leaf_delivery p c rest f Hp28 Hem Hc) as HL.
    eapply delivery_trip_sdec_right; [|exact HL].
    rewrite !sdec_app, !sdec_cons, HE. reflexivity.
Qed.
Lemma phase_ticks_delivery : forall n p b rest tail f f',
  (p + N.of_nat n < 28)%N -> (FLOOR <= b)%N ->
  deliveries
    (N.to_nat
      (marks (p + N.of_nat n) - marks p))
    rest f tail f' ->
  deliveries n
    (phase_form p ++
       (4,2,b + DBu p)%N :: rest) f
    (phase_form (p + N.of_nat n) ++
       (4,2,b + DBu (p + N.of_nat n))%N :: tail) f'.
Proof.
  induction n as [|n IH]; intros p b rest tail f f' Hbound Hb HD.
  - change (N.of_nat O) with 0%N in *.
    rewrite N.add_0_r in HD |- *. rewrite N.sub_diag in HD.
    cbn [N.to_nat] in HD.
    apply deliveries_O.
    rewrite !sdec_app, !sdec_cons.
    exact (f_equal
      (fun x => expand
        (map gdecode (phase_form p)) ++
        pair_runs (N.to_nat 4) (N.to_nat 2)
          (N.to_nat (b + DBu p)) ++ x)
      (deliveries_zero_sdec _ _ _ _ HD)).
  - rewrite Nat2N.inj_succ in Hbound, HD |- *.
    set (q := (p + 1)%N).
    replace (p + N.succ (N.of_nat n))%N with
      (q + N.of_nat n)%N in HD by (unfold q; lia).
    assert (Hp : (p < 27)%N) by (unfold q in *; lia).
    assert (Hq : (q + N.of_nat n < 28)%N) by (unfold q; lia).
    assert (Hm0 : (marks p <= marks q)%N).
    { apply marks_mono; unfold q; lia. }
    assert (Hm1 :
      (marks q <= marks (q + N.of_nat n))%N).
    { apply marks_mono; lia. }
    assert (Hemadd :
      N.to_nat
        (marks (q + N.of_nat n) - marks p) =
      (N.to_nat (marks q - marks p) +
       N.to_nat
         (marks (q + N.of_nat n) - marks q))%nat).
    { rewrite <- N2Nat.inj_add. f_equal. lia. }
    rewrite Hemadd in HD.
    destruct (deliveries_split _ _ _ _ _ _ HD)
      as (mid & fm & Hone & Hrest).
    assert (Hdp : (DBu p <= 3)%N)
      by (apply DBu_le3; lia).
    assert (Htick : delivery_trip
      (phase_form p ++
        (4,2,b + DBu p)%N :: rest) f
      (phase_form (p+1) ++
        (4,2,b + DBu (p+1))%N :: mid) fm).
    { pose proof (phase_tick_delivery p (b + DBu p)
        rest mid f fm Hp ltac:(unfold FLOOR in Hb; lia) Hone)
        as HT.
      replace (b + DBu p + DBu (p+1) -
        DBu p)%N with
        (b + DBu (p+1))%N in HT by lia.
      exact HT. }
    econstructor; [exact Htick|].
    change (p + 1)%N with q.
    replace (p + N.succ (N.of_nat n))%N with
      (q + N.of_nat n)%N by (unfold q; lia).
    exact (IH q b mid tail fm f' Hq Hb Hrest).
Qed.
Definition delivery_cols (w : word) : bool :=
  forallb (fun g => is_col g && negb (is_cmf g)
                    && (3 <=? gO g)%N) w.
Lemma deliveries_cols : forall n cols s f s' f',
  delivery_cols cols = true ->
  deliveries n s f s' f' ->
  deliveries n (cols ++ s) f (cols ++ s') f'.
Proof.
  intros n cols s f s' f' Hcols HD. induction HD.
  - apply deliveries_O.
    rewrite !sdec_app, H. reflexivity.
  - econstructor.
    + exact (delivery_trip_cols _ _ _ _ _ Hcols H).
    + exact IHHD.
Qed.
Lemma delivery_cols_app : forall a b,
  delivery_cols (a ++ b) = delivery_cols a && delivery_cols b.
Proof. intros a b. unfold delivery_cols. apply forallb_app. Qed.
Lemma delivery_cols_rung : forall c,
  delivery_cols (rung1 c) = true.
Proof.
  intros c. unfold delivery_cols, rung1,
    is_col, is_cmf.
  destruct c as [|p]; [reflexivity|]. destruct p; reflexivity.
Qed.
Lemma delivery_cols_runway : forall cs,
  delivery_cols (runway cs) = true.
Proof.
  induction cs as [|c cs IH]; [reflexivity|].
  cbn [runway].
  rewrite delivery_cols_app, delivery_cols_rung, IH. reflexivity.
Qed.
Lemma last2_app_rung : forall pre c,
  last2 (pre ++ rung1 c) =
  Some (pre, (8,2,1)%N, (4,2,c)%N).
Proof.
  induction pre as [|g pre IH]; intros c; [reflexivity|].
  destruct pre as [|x pre']; cbn [app last2] in *.
  - reflexivity.
  - rewrite IH. now destruct pre'.
Qed.
Lemma jump_seg_app_rung : forall pre c b,
  (1 <= c)%N -> (2 <= b)%N ->
  jump_seg (pre ++ rung1 c) b =
  Some (pre ++ phase_form 0 ++
          (4,2,c)%N :: rung1 (b-1)).
Proof.
  intros pre c b Hc Hb. unfold jump_seg.
  rewrite last2_app_rung.
  change (phase_form 0) with [(7,1,1)%N; (3,2,1)%N].
  replace (1 <=? c)%N with true by (symmetry; apply N.leb_le; exact Hc).
  replace (1 <? b)%N with true by (symmetry; apply N.ltb_lt; lia).
  cbn [N.eqb Pos.eqb andb]. repeat rewrite <- app_assoc. reflexivity.
Qed.
Lemma marks_transit_split : forall p,
  (p < 28)%N ->
  N.to_nat (marks 28 - marks p) =
  (N.to_nat (marks 27 - marks p) + 1)%nat.
Proof.
  intros p Hp.
  assert (Hm : (marks p <= marks 27)%N).
  { apply marks_mono; lia. }
  change (marks 27) with 3%N in Hm |- *.
  change (marks 28) with 4%N.
  change 1%nat with (N.to_nat 1).
  rewrite <- N2Nat.inj_add. f_equal. lia.
Qed.
Lemma ticks_to_jump : forall p b post mid f fm,
  (p < 28)%N -> (FLOOR <= b)%N ->
  deliveries
    (N.to_nat (marks 27 - marks p))
    post f mid fm ->
  deliveries (N.to_nat (27-p))
    (phase_form p ++
       (4,2,b + DBu p)%N :: post) f
    (phase_form 27 ++ (4,2,b)%N :: mid) fm.
Proof.
  intros p b post mid f fm Hp Hb HD.
  pose proof (phase_ticks_delivery (N.to_nat (27-p)) p b
    post mid f fm) as H.
  rewrite N2Nat.id in H.
  replace (p + (27-p))%N with 27%N in H by lia.
  change (DBu 27) with 0%N in H.
  replace (b+0)%N with b in H by lia.
  apply H; [lia|exact Hb|exact HD].
Qed.
Lemma transit_delivery_pos : forall cols c p b post tail f f',
  delivery_cols cols = true -> (p < 28)%N ->
  (1 <= c)%N -> (FLOOR <= b)%N ->
  deliveries
    (N.to_nat (marks 28 - marks p))
    post f tail f' ->
  deliveries (N.to_nat (28-p))
    (cols ++ rung1 c ++ phase_form p ++
       (4,2,b + DBu p)%N :: post) f
    (cols ++ phase_form 0 ++ (4,2,c)%N ::
       rung1 (b-1) ++ tail) f'.
Proof.
  intros cols c p b post tail f f' Hcols Hp Hc Hb HD.
  rewrite (marks_transit_split p Hp) in HD.
  destruct (deliveries_split _ _ _ _ _ _ HD)
    as (mid & fm & Hpre & Hlast).
  pose proof (ticks_to_jump p b post mid f fm Hp Hb Hpre) as Hticks.
  assert (Hprefix : delivery_cols
      (cols ++ rung1 c) = true).
  { rewrite delivery_cols_app, Hcols, delivery_cols_rung. reflexivity. }
  pose proof (deliveries_cols _ (cols ++ rung1 c)
    _ _ _ _ Hprefix Hticks) as Hticks'.
  pose proof (deliveries_one_trip _ _ _ _ Hlast) as Htail.
  assert (Hb1 : (1 <= b)%N) by (unfold FLOOR in Hb; lia).
  pose proof (delivery_jump
    (cols ++ rung1 c) mid tail
    ((cols ++ phase_form 0 ++ (4,2,c)%N ::
       rung1 (b-1))%list)
    b fm f' Hprefix (jump_seg_app_rung cols c b
      Hc
      ltac:(unfold FLOOR in Hb; lia)) Hb1 Htail) as Hjump.
  pose proof (deliveries_S O _ _ _ _ _ _ Hjump
    (deliveries_O _ _ _ _ eq_refl)) as Hone.
  pose proof (deliveries_app _ _ _ _ _ _ _ _
    Hticks' Hone) as Hall.
  replace (N.to_nat (28-p)) with (N.to_nat (27-p) + 1)%nat.
  2: { rewrite N2Nat.inj_sub by lia. rewrite N2Nat.inj_sub by lia.
       change (N.to_nat 28) with 28%nat.
       change (N.to_nat 27) with 27%nat. lia. }
  repeat rewrite app_assoc in Hall |- *.
  assert (Eout :
    (((cols ++ phase_form 0) ++
       (4,2,c)%N :: rung1 (b-1)) ++ tail) =
    cols ++ phase_form 0 ++ (4,2,c)%N ::
      rung1 (b-1) ++ tail).
  { rewrite <- (app_assoc (cols ++ phase_form 0)
        ((4,2,c)%N :: rung1 (b-1)) tail).
    cbn [app]. symmetry. apply app_assoc. }
  now rewrite <- Eout.
Qed.
Lemma transit_delivery : forall cols c p b post tail f f',
  delivery_cols cols = true -> (p < 28)%N ->
  (FLOOR + 3 <= c)%N -> (FLOOR <= b)%N ->
  deliveries
    (N.to_nat (marks 28 - marks p))
    post f tail f' ->
  deliveries (N.to_nat (28-p))
    (cols ++ rung1 c ++ phase_form p ++
       (4,2,b + DBu p)%N :: post) f
    (cols ++ phase_form 0 ++ (4,2,c)%N ::
       rung1 (b-1) ++ tail) f'.
Proof.
  intros cols c p b post tail f f' Hcols Hp Hc Hb HD.
  exact (transit_delivery_pos cols c p b post tail f f'
    Hcols Hp ltac:(unfold FLOOR in Hc; lia) Hb HD).
Qed.
Lemma dtick_trip : forall s f out f',
  dtick s f = Some (out, f') ->
  delivery_trip s f out f'.
Proof.
  intros s f out f'. unfold dtick.
  destruct (seek s) as [cols rest] eqn:ES. intros H.
  destruct (seek_split s cols rest ES) as [-> Hcols].
  exact (dtick_after_seek_trip cols rest f out f' Hcols H).
Qed.
Open Scope N_scope.
Open Scope sym.
Opaque LROUND_FUEL LROUND_CHUNKS
       FLAT_ROUND_FUEL CFUEL TRIES.
Lemma last2_len2 : forall (l : word) ini a b,
  last2 l = Some (ini, a, b) -> exists u v r, l = u :: v :: r.
Proof.
  intros l ini a b H.
  destruct l as [|u [|v r]]; [discriminate H|discriminate H|].
  exists u, v, r. reflexivity.
Qed.
Lemma last2_app_l : forall (mid l : word) ini a b,
  last2 l = Some (ini, a, b) ->
  last2 (mid ++ l) = Some (mid ++ ini, a, b).
Proof.
  induction mid as [|g mid IH]; intros l ini a b H; [exact H|].
  cbn [app]. rewrite last2_cons_ge2.
  - rewrite (IH l ini a b H). reflexivity.
  - destruct (last2_len2 l ini a b H) as (u & v & r & ->).
    rewrite length_app. cbn [length]. lia.
Qed.
Lemma LineageSchedule_jump_seg_app : forall (mid cols : word) (B : N) seg,
  jump_seg cols B = Some seg ->
  jump_seg (mid ++ cols) B = Some (mid ++ seg).
Proof.
  intros mid cols B seg H. unfold jump_seg in H |- *.
  destruct (last2 cols)
    as [[[ini [[gao gaz] gac]] [[gbo gbz] gbc]]|] eqn:E; [|discriminate].
  rewrite (last2_app_l mid cols ini _ _ E).
  destruct ((gao =? 8) && (gaz =? 2) && (gac =? 1)
            && (gbo =? 4) && (gbz =? 2) && (1 <=? gbc))%N.
  - injection H as <-. rewrite <- app_assoc. reflexivity.
  - destruct ((gbo =? 8) && (gbz =? 2) && (gbc =? 1))%N;
      [|discriminate].
    injection H as <-. rewrite <- app_assoc. reflexivity.
Qed.
Lemma LineageSchedule_lawR_seg_app : forall (mid cols : word) (B : N) seg,
  lawR_seg cols B = Some seg ->
  lawR_seg (mid ++ cols) B = Some (mid ++ seg).
Proof.
  intros mid cols B seg H. unfold lawR_seg in H |- *.
  destruct (last2 cols)
    as [[[ini [[gao gaz] gac]] [[gbo gbz] gbc]]|] eqn:E; [|discriminate].
  rewrite (last2_app_l mid cols ini _ _ E).
  destruct ((gao =? 8) && (gaz =? 2) && (gac =? 1)
            && (gbo =? 4) && (gbz =? 2) && (1 <=? gbc))%N.
  - injection H as <-. rewrite <- app_assoc. reflexivity.
  - destruct ((gbo =? 8) && (gbz =? 2) && (gbc =? 1))%N;
      [|discriminate].
    injection H as <-. rewrite <- app_assoc. reflexivity.
Qed.
Lemma endR_seg_app : forall (mid cols : word) (f : N) seg,
  endR_seg cols f = Some seg ->
  endR_seg (mid ++ cols) f = Some (mid ++ seg).
Proof.
  intros mid cols f seg H. unfold endR_seg in H |- *.
  destruct (last2 cols)
    as [[[ini [[gao gaz] gac]] [[gbo gbz] gbc]]|] eqn:E; [|discriminate].
  rewrite (last2_app_l mid cols ini _ _ E).
  destruct ((gao =? 8) && (gaz =? 2) && (gac =? 1)
            && (gbo =? 4) && (gbz =? 2) && (1 <=? gbc)
            && (2 <=? f))%N.
  - injection H as <-. rewrite <- app_assoc. reflexivity.
  - destruct ((gbo =? 8) && (gbz =? 2) && (gbc =? 1)
              && (2 <=? f))%N; [|discriminate].
    injection H as <-. rewrite <- app_assoc. reflexivity.
Qed.
Lemma endY_seg_app : forall (mid cols : word) (y : N) seg,
  endY_seg cols y = Some seg ->
  endY_seg (mid ++ cols) y = Some (mid ++ seg).
Proof.
  intros mid cols y seg H. unfold endY_seg in H |- *.
  destruct (last2 cols)
    as [[[ini [[gao gaz] gac]] [[gbo gbz] gbc]]|] eqn:E; [|discriminate].
  rewrite (last2_app_l mid cols ini _ _ E).
  destruct ((gao =? 8) && (gaz =? 2) && (gac =? 1)
            && (gbo =? 4) && (gbz =? 2) && (1 <=? gbc))%N.
  - injection H as <-. rewrite <- app_assoc. reflexivity.
  - destruct ((gbo =? 8) && (gbz =? 2) && (gbc =? 1))%N;
      [|discriminate].
    injection H as <-. rewrite <- app_assoc. reflexivity.
Qed.
Lemma renew_seg_nil : forall n cols f,
  renew_seg n cols [] f = None.
Proof. intros n cols f. destruct n; reflexivity. Qed.
Ltac sched_both H E :=
  try (xrewrite_in H E); try (xrewrite E);
  cbv beta iota zeta in H |- *.
Ltac sched_goal E :=
  try (xrewrite E); cbv beta iota zeta.
Lemma renew_seg_app :
  forall n (mid cols rest : word) f body f2,
  renew_seg n cols ((4,3,1)%N :: rest) f = Some (body, f2) ->
  renew_seg n (mid ++ cols) ((4,3,1)%N :: rest) f
    = Some (mid ++ body, f2).
Proof.
  intros n mid cols rest f body f2 H.
  destruct n as [|n]; [discriminate|].
  cbn [renew_seg] in H |- *.
  destruct rest as [|[[o5 z5] B] rest2].
  { destruct (endR_seg cols f) as [b0|] eqn:E; [|discriminate].
    rewrite (endR_seg_app mid cols f b0 E).
    injection H as <- <-. reflexivity. }
  destruct ((o5 =? 4) && (z5 =? 2) && (1 <=? B))%N eqn:E45.
  - destruct rest2 as [|g2 rest2t].
    + destruct (f =? 4)%N eqn:Ef4.
      * destruct (lawR_seg cols B) as [b0|] eqn:E; [|discriminate].
        rewrite (LineageSchedule_lawR_seg_app mid cols B b0 E).
        injection H as <- <-. reflexivity.
      * destruct (5 <=? f)%N eqn:Ef5; [|discriminate].
        destruct (jump_seg cols B) as [seg|] eqn:E; [|discriminate].
        rewrite (LineageSchedule_jump_seg_app mid cols B seg E).
        injection H as <- <-. rewrite app_assoc. reflexivity.
    + destruct (jump_seg cols B) as [seg|] eqn:EJ; [|discriminate].
      rewrite (LineageSchedule_jump_seg_app mid cols B seg EJ).
      destruct (seek (g2 :: rest2t)) as [cols2 s3] eqn:ESK.
      cbv beta iota zeta in H |- *.
      destruct s3 as [|[[o7 z7] c7] s3t].
      * rewrite renew_seg_nil in H |- *. cbv beta iota zeta in H |- *.
        change (leaf_act [] f) with
          (None : option (word * N)) in H |- *.
        cbv beta iota zeta in H |- *.
        destruct (5 <=? f)%N eqn:Ef5.
        { injection H as <- <-. rewrite !app_assoc. reflexivity. }
        destruct (f =? 4)%N eqn:Ef4; [|discriminate].
        destruct (dtb4_conv cols2) as [c2'|] eqn:ED4.
        { injection H as <- <-. rewrite app_assoc. reflexivity. }
        destruct (forallb w42 cols2) eqn:EW; [|discriminate].
        destruct (lawR_seg cols B) as [seg2|] eqn:EL;
          [|discriminate].
        rewrite (LineageSchedule_lawR_seg_app mid cols B seg2 EL).
        injection H as <- <-. rewrite <- app_assoc. reflexivity.
      * destruct (renew_seg n cols2 ((o7,z7,c7)%N :: s3t) f)
          as [[b0 f0]|] eqn:ER; sched_both H ER.
        { injection H as <- <-. rewrite <- app_assoc. reflexivity. }
        destruct ((z7 =? 3) && (c7 =? 1))%N eqn:EZ;
          sched_both H EZ.
        { destruct (fire_comp n ((o7,z7,c7)%N :: s3t) f)
            as [[s3' f0]|] eqn:EF; sched_both H EF; [|discriminate].
          injection H as <- <-. rewrite <- !app_assoc. reflexivity. }
        destruct (sand_leaf ((o7,z7,c7)%N :: s3t)) eqn:ESL;
          sched_both H ESL; [discriminate|].
        destruct (leaf_act ((o7,z7,c7)%N :: s3t) f)
          as [[s3' f0]|] eqn:EL; sched_both H EL; [|discriminate].
        injection H as <- <-. rewrite <- !app_assoc. reflexivity.
  - destruct ((z5 =? 3) && (B =? 1)
              && match rest2 with [] => true | _ => false end
              && (f =? 4) && (1 <=? o5))%N eqn:EY; [|discriminate].
    destruct (endY_seg cols o5) as [b0|] eqn:E; [|discriminate].
    rewrite (endY_seg_app mid cols o5 b0 E).
    injection H as <- <-. reflexivity.
Qed.
Lemma last2_ex : forall l : word, (2 <= length l)%nat ->
  exists ini a b, last2 l = Some (ini, a, b).
Proof.
  induction l as [|x l IH]; intros H; [cbn [length] in H; lia|].
  destruct l as [|y l]; [cbn [length] in H; lia|].
  destruct l as [|z l].
  - exists ([] : word), x, y. reflexivity.
  - destruct (IH ltac:(cbn [length]; lia)) as (ini & a & b & E).
    rewrite (last2_cons_ge2 x (y::z::l)
      ltac:(cbn [length]; lia)), E.
    exists (x::ini), a, b. reflexivity.
Qed.
Lemma jump_seg_app_eq : forall (mid cols : word) B,
  (2 <= length cols)%nat ->
  jump_seg (mid ++ cols) B =
  match jump_seg cols B with
  | Some s => Some (mid ++ s) | None => None
  end.
Proof.
  intros mid cols B Hlen.
  destruct (last2_ex cols Hlen)
    as (ini & [[gao gaz] gac] & [[gbo gbz] gbc] & E).
  unfold jump_seg.
  rewrite (last2_app_l mid cols ini _ _ E), E.
  destruct ((gao =? 8) && (gaz =? 2) && (gac =? 1)
            && (gbo =? 4) && (gbz =? 2) && (1 <=? gbc))%N.
  - rewrite <- app_assoc. reflexivity.
  - destruct ((gbo =? 8) && (gbz =? 2) && (gbc =? 1))%N;
      [|reflexivity].
    rewrite <- app_assoc. reflexivity.
Qed.
Lemma lawR_seg_app_eq : forall (mid cols : word) B,
  (2 <= length cols)%nat ->
  lawR_seg (mid ++ cols) B =
  match lawR_seg cols B with
  | Some s => Some (mid ++ s) | None => None
  end.
Proof.
  intros mid cols B Hlen.
  destruct (last2_ex cols Hlen)
    as (ini & [[gao gaz] gac] & [[gbo gbz] gbc] & E).
  unfold lawR_seg.
  rewrite (last2_app_l mid cols ini _ _ E), E.
  destruct ((gao =? 8) && (gaz =? 2) && (gac =? 1)
            && (gbo =? 4) && (gbz =? 2) && (1 <=? gbc))%N.
  - rewrite <- app_assoc. reflexivity.
  - destruct ((gbo =? 8) && (gbz =? 2) && (gbc =? 1))%N;
      [|reflexivity].
    rewrite <- app_assoc. reflexivity.
Qed.
Lemma endR_seg_app_eq : forall (mid cols : word) f,
  (2 <= length cols)%nat ->
  endR_seg (mid ++ cols) f =
  match endR_seg cols f with
  | Some s => Some (mid ++ s) | None => None
  end.
Proof.
  intros mid cols f Hlen.
  destruct (last2_ex cols Hlen)
    as (ini & [[gao gaz] gac] & [[gbo gbz] gbc] & E).
  unfold endR_seg.
  rewrite (last2_app_l mid cols ini _ _ E), E.
  destruct ((gao =? 8) && (gaz =? 2) && (gac =? 1)
            && (gbo =? 4) && (gbz =? 2) && (1 <=? gbc)
            && (2 <=? f))%N.
  - rewrite <- app_assoc. reflexivity.
  - destruct ((gbo =? 8) && (gbz =? 2) && (gbc =? 1)
              && (2 <=? f))%N; [|reflexivity].
    rewrite <- app_assoc. reflexivity.
Qed.
Lemma endY_seg_app_eq : forall (mid cols : word) y,
  (2 <= length cols)%nat ->
  endY_seg (mid ++ cols) y =
  match endY_seg cols y with
  | Some s => Some (mid ++ s) | None => None
  end.
Proof.
  intros mid cols y Hlen.
  destruct (last2_ex cols Hlen)
    as (ini & [[gao gaz] gac] & [[gbo gbz] gbc] & E).
  unfold endY_seg.
  rewrite (last2_app_l mid cols ini _ _ E), E.
  destruct ((gao =? 8) && (gaz =? 2) && (gac =? 1)
            && (gbo =? 4) && (gbz =? 2) && (1 <=? gbc))%N.
  - rewrite <- app_assoc. reflexivity.
  - destruct ((gbo =? 8) && (gbz =? 2) && (gbc =? 1))%N;
      [|reflexivity].
    rewrite <- app_assoc. reflexivity.
Qed.
Lemma renew_seg_app_eq : forall n (mid cols rest : word) f,
  (2 <= length cols)%nat ->
  renew_seg n (mid ++ cols) ((4,3,1)%N :: rest) f =
  match renew_seg n cols ((4,3,1)%N :: rest) f with
  | Some (b, f') => Some (mid ++ b, f') | None => None
  end.
Proof.
  intros n mid cols rest f Hlen.
  destruct n as [|n]; [reflexivity|].
  cbn [renew_seg].
  destruct rest as [|[[o5 z5] B] rest2].
  { rewrite (endR_seg_app_eq mid cols f Hlen).
    destruct (endR_seg cols f); reflexivity. }
  destruct ((o5 =? 4) && (z5 =? 2) && (1 <=? B))%N eqn:E45.
  - destruct rest2 as [|g2 rest2t].
    + destruct (f =? 4)%N eqn:Ef4.
      * rewrite (lawR_seg_app_eq mid cols B Hlen).
        destruct (lawR_seg cols B); reflexivity.
      * destruct (5 <=? f)%N eqn:Ef5; [|reflexivity].
        rewrite (jump_seg_app_eq mid cols B Hlen).
        destruct (jump_seg cols B); [|reflexivity].
        rewrite <- !app_assoc. reflexivity.
    + rewrite (jump_seg_app_eq mid cols B Hlen).
      destruct (jump_seg cols B) as [seg|]; [|reflexivity].
      cbv beta iota zeta.
      destruct (seek (g2 :: rest2t)) as [cols2 s3] eqn:ESK.
      cbv beta iota zeta.
      destruct s3 as [|[[o7 z7] c7] s3t].
      * rewrite renew_seg_nil. cbv beta iota zeta.
        change (leaf_act [] f) with
          (None : option (word * N)).
        cbv beta iota zeta.
        destruct (5 <=? f)%N eqn:Ef5.
        { rewrite <- !app_assoc. reflexivity. }
        destruct (f =? 4)%N eqn:Ef4; [|reflexivity].
        destruct (dtb4_conv cols2) as [c2'|] eqn:ED4.
        { rewrite <- !app_assoc. reflexivity. }
        destruct (forallb w42 cols2) eqn:EW; [|reflexivity].
        rewrite (lawR_seg_app_eq mid cols B Hlen).
        destruct (lawR_seg cols B) as [seg2|]; [|reflexivity].
        rewrite <- app_assoc. reflexivity.
      * destruct (renew_seg n cols2 ((o7,z7,c7)%N :: s3t) f)
          as [[b0 f0]|] eqn:ER; sched_goal ER.
        { rewrite <- app_assoc. reflexivity. }
        destruct ((z7 =? 3) && (c7 =? 1))%N eqn:EZ; sched_goal EZ.
        { destruct (fire_comp n ((o7,z7,c7)%N :: s3t) f)
            as [[s3' f0]|] eqn:EF; sched_goal EF; [|reflexivity].
          rewrite <- !app_assoc. reflexivity. }
        destruct (sand_leaf ((o7,z7,c7)%N :: s3t)) eqn:ESL;
          sched_goal ESL; [reflexivity|].
        destruct (leaf_act ((o7,z7,c7)%N :: s3t) f)
          as [[s3' f0]|] eqn:EL; sched_goal EL; [|reflexivity].
        rewrite <- !app_assoc. reflexivity.
  - destruct ((z5 =? 3) && (B =? 1)
              && match rest2 with [] => true | _ => false end
              && (f =? 4) && (1 <=? o5))%N eqn:EY; [|reflexivity].
    rewrite (endY_seg_app_eq mid cols o5 Hlen).
    destruct (endY_seg cols o5); reflexivity.
Qed.
Lemma renew_seg_head : forall n cols s f r,
  renew_seg n cols s f = Some r ->
  exists rest, s = ((4,3,1)%N :: rest).
Proof.
  intros n cols s f r H.
  destruct n as [|n]; [discriminate|].
  destruct s as [|[[o z] c] rest]; [discriminate|].
  destruct o as [|p]; [discriminate|].
  destruct p as [p|p|]; [discriminate| |discriminate].
  destruct p as [p|p|]; [discriminate| |discriminate].
  destruct p as [p|p|]; [discriminate|discriminate|].
  destruct z as [|q]; [discriminate|].
  destruct q as [q|q|]; [|discriminate|discriminate].
  destruct q as [q|q|]; [discriminate|discriminate|].
  destruct c as [|r2]; [discriminate|].
  destruct r2 as [r2|r2|]; [discriminate|discriminate|].
  exists rest. reflexivity.
Qed.
Lemma lin_dtick_after_seek_strip :
  forall (mid cols s : word) f renewed out f2,
  lin_dtick_after_seek (mid ++ cols) s f
    = Some (renewed, out, f2) ->
  (renewed = true -> (2 <= length cols)%nat) ->
  exists body,
    lin_dtick_after_seek cols s f = Some (renewed, body, f2) /\
    out = mid ++ body.
Proof.
  intros mid cols s f renewed out f2 Hrun Hstock.
  unfold lin_dtick_after_seek in Hrun |- *.
  destruct (renew_seg (length s) (mid ++ cols) s f)
    as [[bodyF fF]|] eqn:ERF.
  - inversion Hrun; subst renewed out f2.
    assert (Hlen : (2 <= length cols)%nat) by (apply Hstock; reflexivity).
    destruct (renew_seg_head (length s) (mid ++ cols) s f
      (bodyF, fF) ERF) as (rest & ->).
    change (renew_seg (length ((4,3,1)%N :: rest))
      (mid ++ cols) ((4,3,1)%N :: rest) f = Some (bodyF, fF)) in ERF.
    pose proof (renew_seg_app_eq (length ((4,3,1)%N :: rest))
      mid cols rest f Hlen) as E.
    rewrite ERF in E.
    destruct (renew_seg (length ((4,3,1)%N :: rest)) cols
      ((4,3,1)%N :: rest) f) as [[body fB]|] eqn:ERB;
      [|discriminate E].
    inversion E; subst bodyF fF.
    exists body. split.
    + xrewrite ERB. reflexivity.
    + reflexivity.
  - destruct (renew_seg (length s) cols s f)
      as [[bodyB fB]|] eqn:ERB.
    + destruct (renew_seg_head (length s) cols s f
        (bodyB, fB) ERB) as (rest & ->).
      change (renew_seg (length ((4,3,1)%N :: rest))
        (mid ++ cols) ((4,3,1)%N :: rest) f = None) in ERF.
      pose proof (renew_seg_app (length ((4,3,1)%N :: rest))
        mid cols rest f bodyB fB ERB) as E.
      rewrite ERF in E. discriminate.
    + remember
        (match s with
         | (o7,z7,c7) :: _ =>
             if (z7 =? 3) && (c7 =? 1)
             then fire_comp (length s) s f
             else if sand_leaf s then None else leaf_act s f
         | [] => leaf_act s f
         end) as dispatch.
      destruct dispatch as [[tail fT]|]; [|discriminate Hrun].
      cbn in Hrun. inversion Hrun; subst renewed out f2.
      exists (cols ++ tail). split.
      * reflexivity.
      * rewrite app_assoc. reflexivity.
Qed.
Lemma seek_app_delivery_cols : forall (mid w : word),
  delivery_cols mid = true ->
  seek (mid ++ w) =
    (mid ++ fst (seek w), snd (seek w)).
Proof.
  intros mid w Hcols. apply seek_app_col.
  intros g Hin. unfold delivery_cols in Hcols.
  pose proof (proj1 (forallb_forall _ _) Hcols g Hin) as H.
  exact H.
Qed.
Inductive schedule_run : list (option N) -> word -> N ->
                         word -> N -> Prop :=
  | schedule_run_nil : forall w f,
      schedule_run [] w f w f
  | schedule_run_none : forall rs w f w1 f1 w2 f2,
      dtick w f = Some (w1, f1) ->
      schedule_run rs w1 f1 w2 f2 ->
      schedule_run (None :: rs) w f w2 f2
  | schedule_run_some : forall c rs w f w1 f1 w2 f2,
      dtick w f = Some (w1, f1) ->
      schedule_run rs (rung1 c ++ w1) f1 w2 f2 ->
      schedule_run (Some c :: rs) w f w2 f2.
Inductive schedule_deliveries : list (option N) -> word -> N ->
                                word -> N -> Prop :=
  | schedule_deliveries_nil : forall w f,
      schedule_deliveries [] w f w f
  | schedule_deliveries_none : forall rs w f w1 f1 w2 f2,
      delivery_trip w f w1 f1 ->
      schedule_deliveries rs w1 f1 w2 f2 ->
      schedule_deliveries (None :: rs) w f w2 f2
  | schedule_deliveries_some : forall c rs w f w1 f1 w2 f2,
      delivery_trip w f w1 f1 ->
      schedule_deliveries rs (rung1 c ++ w1) f1 w2 f2 ->
      schedule_deliveries (Some c :: rs) w f w2 f2.
Inductive schedule_trips : list (option N) -> word -> N ->
                           word -> N -> Prop :=
  | schedule_trips_nil : forall w f w' f',
      sdec w f = sdec w' f' ->
      schedule_trips [] w f w' f'
  | schedule_trips_none : forall rs w f w1 f1 w2 f2,
      delivery_trip w f w1 f1 ->
      schedule_trips rs w1 f1 w2 f2 ->
      schedule_trips (None :: rs) w f w2 f2
  | schedule_trips_some : forall c rs w f w1 f1 w2 f2,
      delivery_trip w f w1 f1 ->
      schedule_trips rs (rung1 c ++ w1) f1 w2 f2 ->
      schedule_trips (Some c :: rs) w f w2 f2.
Lemma schedule_deliveries_trips : forall rs w f out f',
  schedule_deliveries rs w f out f' -> schedule_trips rs w f out f'.
Proof.
  intros rs w f out f' H. induction H.
  - constructor. reflexivity.
  - econstructor; eassumption.
  - eapply schedule_trips_some; eassumption.
Qed.
Lemma schedule_run_deliveries : forall rs w f out f',
  schedule_run rs w f out f' -> schedule_deliveries rs w f out f'.
Proof.
  intros rs w f out f' H. induction H.
  - constructor.
  - econstructor; [exact (dtick_trip _ _ _ _ H)|exact IHschedule_run].
  - eapply schedule_deliveries_some;
      [exact (dtick_trip _ _ _ _ H)|exact IHschedule_run].
Qed.
Fixpoint schedule_stock (rs : list (option N)) : word :=
  match rs with
  | [] => []
  | None :: r => schedule_stock r
  | Some c :: r => schedule_stock r ++ rung1 c
  end.
Lemma schedule_stock_repeat_none : forall n,
  schedule_stock (repeat None n) = [].
Proof.
  induction n as [|n IH]; [reflexivity|].
  cbn [repeat schedule_stock]. exact IH.
Qed.
Lemma schedule_stock_app : forall a b,
  schedule_stock (a ++ b) = schedule_stock b ++ schedule_stock a.
Proof.
  induction a as [|[c|] a IH]; intros b; cbn [schedule_stock app].
  - now rewrite app_nil_r.
  - rewrite IH, app_assoc. reflexivity.
  - apply IH.
Qed.
Lemma schedule_stock_cols : forall rs,
  delivery_cols (schedule_stock rs) = true.
Proof.
  induction rs as [|[c|] rs IH]; [reflexivity| |exact IH].
  cbn [schedule_stock]. rewrite delivery_cols_app,
    IH, delivery_cols_rung. reflexivity.
Qed.
Lemma schedule_deliveries_app_inv : forall a b w f out f',
  schedule_deliveries (a ++ b) w f out f' ->
  exists mid fm,
    schedule_deliveries a w f mid fm /\
    schedule_deliveries b mid fm out f'.
Proof.
  induction a as [|[c|] a IH]; intros b w f out f' HRun.
  - cbn [app] in HRun. exists w, f. split; [constructor|exact HRun].
  - cbn [app] in HRun.
    inversion HRun as
      [|rs w0 f0 w1 f1 w2 f2 HD HRest
       |c_0 rs w0 f0 w1 f1 w2 f2 HD HRest]; subst; try discriminate.
    destruct (IH b (rung1 c ++ w1) f1 out f' HRest)
      as (mid & fm & HA & HB).
    exists mid, fm. split; [|exact HB].
    eapply schedule_deliveries_some; eassumption.
  - cbn [app] in HRun.
    inversion HRun as
      [|rs w0 f0 w1 f1 w2 f2 HD HRest
       |c_0 rs w0 f0 w1 f1 w2 f2 HD HRest]; subst; try discriminate.
    destruct (IH b w1 f1 out f' HRest) as (mid & fm & HA & HB).
    exists mid, fm. split; [|exact HB].
    eapply schedule_deliveries_none; eassumption.
Qed.
Lemma schedule_deliveries_nones : forall n w f out f',
  schedule_deliveries (repeat None n) w f out f' ->
  deliveries n w f out f'.
Proof.
  induction n as [|n IH]; intros w f out f' HRun.
  - cbn [repeat] in HRun. inversion HRun; subst.
    apply deliveries_O. reflexivity.
  - cbn [repeat] in HRun.
    inversion HRun as
      [|rs w0 f0 w1 f1 w2 f2 HD HRest
       |c rs w0 f0 w1 f1 w2 f2 HD HRest]; subst.
    econstructor; [exact HD|exact (IH _ _ _ _ HRest)].
Qed.
Lemma schedule_deliveries_nones_some : forall n c w f out f',
  schedule_deliveries (repeat None n ++ [Some c]) w f out f' ->
  exists tail,
    deliveries (S n) w f tail f' /\
    out = rung1 c ++ tail.
Proof.
  induction n as [|n IH]; intros c w f out f' HRun.
  - cbn [repeat app] in HRun.
    inversion HRun as
      [|rs w0 f0 w1 f1 w2 f2 HD HRest
       |c_0 rs w0 f0 w1 f1 w2 f2 HD HRest]; subst.
    inversion HRest; subst. exists w1. split; [|reflexivity].
    econstructor; [exact HD|apply deliveries_O; reflexivity].
  - cbn [repeat app] in HRun.
    inversion HRun as
      [|rs w0 f0 w1 f1 w2 f2 HD HRest
       |c_0 rs w0 f0 w1 f1 w2 f2 HD HRest]; subst.
    destruct (IH c w1 f1 out f' HRest) as (tail & HDel & ->).
    exists tail. split; [|reflexivity].
    econstructor; [exact HD|exact HDel].
Qed.
Lemma schedule_trips_sdec_left : forall rs w0 f0 w f out f',
  sdec w0 f0 = sdec w f ->
  schedule_trips rs w f out f' -> schedule_trips rs w0 f0 out f'.
Proof.
  intros rs w0 f0 w f out f' E H. destruct H.
  - constructor. now rewrite E.
  - econstructor.
    + eapply delivery_trip_sdec_left; eassumption.
    + exact H0.
  - eapply schedule_trips_some.
    + eapply delivery_trip_sdec_left; eassumption.
    + exact H0.
Qed.
Lemma schedule_trips_app : forall a b w f w1 f1 w2 f2,
  schedule_trips a w f w1 f1 -> schedule_trips b w1 f1 w2 f2 ->
  schedule_trips (a ++ b) w f w2 f2.
Proof.
  intros a b w f w1 f1 w2 f2 HA HB. induction HA.
  - exact (schedule_trips_sdec_left b w f w' f' w2 f2 H HB).
  - cbn [app]. econstructor; [exact H|exact (IHHA HB)].
  - cbn [app]. eapply schedule_trips_some; [exact H|exact (IHHA HB)].
Qed.
Lemma deliveries_to_schedule_trips : forall rs n w f out f',
  length rs = n ->
  deliveries n w f out f' ->
  schedule_trips rs w f (schedule_stock rs ++ out) f'.
Proof.
  induction rs as [|[c|] rs IH]; intros n w f out f' HLen HDel.
  - cbn [length] in HLen. subst n.
    inversion HDel; subst. cbn [schedule_stock app]. constructor. exact H.
  - cbn [length] in HLen. subst n.
    inversion HDel as [|n0 w0 f0 w1 f1 w2 f2 HT HR]; subst.
    pose proof (deliveries_cols _
      (rung1 c) _ _ _ _
      (delivery_cols_rung c) HR) as HRest.
    pose proof (IH _ _ _ _ _ eq_refl HRest) as HIH.
    cbn [schedule_stock]. rewrite <- app_assoc.
    eapply schedule_trips_some; [exact HT|exact HIH].
  - cbn [length] in HLen. subst n.
    inversion HDel as [|n0 w0 f0 w1 f1 w2 f2 HT HR]; subst.
    pose proof (IH _ _ _ _ _ eq_refl HR) as HIH.
    cbn [schedule_stock].
    eapply schedule_trips_none; [exact HT|exact HIH].
Qed.
Lemma list_snoc_of_length_succ : forall (A : Type) (xs : list A) n,
  length xs = S n ->
  exists pre x, xs = pre ++ [x] /\ length pre = n.
Proof.
  intros A xs n HLen.
  destruct (rev xs) as [|x r] eqn:ER.
  - apply (f_equal (@length A)) in ER.
    rewrite length_rev in ER. cbn [length] in ER. lia.
  - exists (rev r), x. split.
    + rewrite <- (rev_involutive xs), ER. cbn [rev app]. reflexivity.
    + apply (f_equal (@length A)) in ER.
      rewrite length_rev in ER. cbn [length] in ER.
      rewrite length_rev. lia.
Qed.
Lemma app_suffix_factor : forall (A : Type) (a b c d : list A),
  a ++ b = c ++ d -> (length d <= length b)%nat ->
  exists mid, c = a ++ mid /\ b = mid ++ d.
Proof.
  intros A a. induction a as [|x a IH]; intros b c d E HLen.
  - exists c. cbn [app] in E |- *. split; [reflexivity|exact E].
  - destruct c as [|y c].
    + apply (f_equal (@length A)) in E.
      rewrite !length_app in E. cbn [length] in E. lia.
    + cbn [app] in E. injection E as Ex Erest. subst y.
      destruct (IH b c d Erest HLen) as (mid & -> & ->).
      exists mid. split; reflexivity.
Qed.
Lemma app_prefix_factor : forall (A : Type) (a b c d : list A),
  a ++ b = c ++ d -> (length a <= length c)%nat ->
  exists mid, c = a ++ mid /\ b = mid ++ d.
Proof.
  intros A a. induction a as [|x a IH]; intros b c d E HLen.
  - exists c. cbn [app] in E |- *. split; [reflexivity|exact E].
  - destruct c as [|y c].
    + cbn [length] in HLen. lia.
    + cbn [app] in E. injection E as Ex Erest. subst y.
      destruct (IH b c d Erest ltac:(cbn [length] in HLen; lia))
        as (mid & -> & ->).
      exists mid. split; reflexivity.
Qed.
Lemma schedule_stock_snoc : forall pre oc,
  schedule_stock (pre ++ [oc]) =
  match oc with
  | None => schedule_stock pre
  | Some c => rung1 c ++ schedule_stock pre
  end.
Proof.
  intros pre [c|]; rewrite schedule_stock_app;
    cbn [schedule_stock app].
  - reflexivity.
  - reflexivity.
Qed.
Lemma schedule_trips_app_inv : forall a b w f out f',
  schedule_trips (a ++ b) w f out f' ->
  exists mid fm,
    schedule_trips a w f mid fm /\
    schedule_trips b mid fm out f'.
Proof.
  induction a as [|[c|] a IH]; intros b w f out f' HRun.
  - cbn [app] in HRun. exists w, f. split; [constructor; reflexivity|].
    exact HRun.
  - cbn [app] in HRun.
    inversion HRun as
      [|rs w0 f0 w1 f1 w2 f2 HD HRest
       |c_0 rs w0 f0 w1 f1 w2 f2 HD HRest]; subst; try discriminate.
    destruct (IH b (rung1 c ++ w1) f1 out f' HRest)
      as (mid & fm & HA & HB).
    exists mid, fm. split; [|exact HB].
    eapply schedule_trips_some; eassumption.
  - cbn [app] in HRun.
    inversion HRun as
      [|rs w0 f0 w1 f1 w2 f2 HD HRest
       |c_0 rs w0 f0 w1 f1 w2 f2 HD HRest]; subst; try discriminate.
    destruct (IH b w1 f1 out f' HRest) as (mid & fm & HA & HB).
    exists mid, fm. split; [|exact HB].
    eapply schedule_trips_none; eassumption.
Qed.
Lemma schedule_trips_nones : forall n w f out f',
  schedule_trips (repeat None n) w f out f' ->
  deliveries n w f out f'.
Proof.
  induction n as [|n IH]; intros w f out f' HRun.
  - cbn [repeat] in HRun. inversion HRun; subst.
    apply deliveries_O. exact H.
  - cbn [repeat] in HRun.
    inversion HRun as
      [|rs w0 f0 w1 f1 w2 f2 HD HRest
       |c rs w0 f0 w1 f1 w2 f2 HD HRest]; subst.
    econstructor; [exact HD|exact (IH _ _ _ _ HRest)].
Qed.
Lemma schedule_trips_one_some : forall c w f out f',
  schedule_trips [Some c] w f out f' ->
  exists tail ft,
    delivery_trip w f tail ft /\
    sdec (rung1 c ++ tail) ft =
      sdec out f'.
Proof.
  intros c w f out f' HRun.
  inversion HRun as
    [|rs w0 f0 w1 f1 w2 f2 HD HRest
     |c_0 rs w0 f0 w1 f1 w2 f2 HD HRest]; subst; try discriminate.
  inversion HRest; subst.
  exists w1, f1. split; assumption.
Qed.
Lemma sdec_prefix_eq : forall pre a f b f',
  sdec a f = sdec b f' ->
  sdec (pre ++ a) f = sdec (pre ++ b) f'.
Proof.
  intros pre a f b f' E. rewrite !sdec_app, E. reflexivity.
Qed.
Fixpoint schedule_shape (slot : N) (rs : list (option N)) : Prop :=
  match rs with
  | [] => True
  | oc :: r =>
      if slot =? 0 then
        exists c, oc = Some c /\ schedule_shape 3 r
      else oc = None /\ schedule_shape (slot - 1) r
  end.
Lemma schedule_shape_cons_zero : forall oc r,
  schedule_shape 0 (oc :: r) ->
  exists c, oc = Some c /\ schedule_shape 3 r.
Proof. intros oc r H. exact H. Qed.
Lemma schedule_shape_cons_pos : forall slot oc r,
  slot <> 0%N -> schedule_shape slot (oc :: r) ->
  oc = None /\ schedule_shape (slot - 1) r.
Proof.
  intros slot oc r Hne H. cbn [schedule_shape] in H.
  assert (E : (slot =? 0)%N = false) by (apply N.eqb_neq; exact Hne).
  rewrite E in H. exact H.
Qed.
Fixpoint schedule_grants (slot : nat) (vals : list N)
  : list (option N) :=
  match vals with
  | [] => []
  | c :: cs => repeat None slot ++ Some c :: schedule_grants 3 cs
  end.
Definition schedule_plan (slot : nat) (vals : list N) (tail : nat)
  : list (option N) :=
  schedule_grants slot vals ++ repeat None tail.
Lemma schedule_grants_length : forall slot c cs,
  length (schedule_grants slot (c :: cs)) =
    (slot + 1 + 4 * length cs)%nat.
Proof.
  intros slot c cs. revert slot c.
  induction cs as [|d ds IH]; intros slot c.
  - change (length (repeat None slot ++ [Some c]) =
      (slot + 1 + 4 * length ([] : list N))%nat).
    rewrite length_app, repeat_length. cbn [length]. lia.
  - change (length
      (repeat None slot ++ Some c :: schedule_grants 3%nat (d :: ds)) =
      (slot + 1 + 4 * length (d :: ds))%nat).
    rewrite length_app, repeat_length. cbn [length].
    rewrite (IH 3%nat d). lia.
Qed.
Lemma schedule_plan_length : forall slot c cs tail,
  length (schedule_plan slot (c :: cs) tail) =
    (slot + 1 + 4 * length cs + tail)%nat.
Proof.
  intros slot c cs tail. unfold schedule_plan.
  rewrite length_app, schedule_grants_length, repeat_length. lia.
Qed.
Lemma schedule_grants_stock : forall slot vals,
  schedule_stock (schedule_grants slot vals) =
  runway (rev vals).
Proof.
  intros slot vals. revert slot.
  induction vals as [|c cs IH]; intros slot; [reflexivity|].
  cbn [schedule_grants].
  rewrite schedule_stock_app, schedule_stock_repeat_none.
  cbn [schedule_stock]. rewrite IH, app_nil_r.
  cbn [rev]. rewrite runway_app.
  cbn [runway app]. reflexivity.
Qed.
Lemma schedule_plan_stock : forall slot vals tail,
  schedule_stock (schedule_plan slot vals tail) =
  runway (rev vals).
Proof.
  intros slot vals tail. unfold schedule_plan.
  rewrite schedule_stock_app, schedule_stock_repeat_none,
    schedule_grants_stock. reflexivity.
Qed.
Lemma schedule_shape_nones_nat : forall n slot,
  (n <= slot)%nat -> (slot <= 3)%nat ->
  schedule_shape (N.of_nat slot) (repeat None n).
Proof.
  induction n as [|n IH]; intros slot Hns Hs; [exact I|].
  destruct slot as [|slot]; [lia|].
  cbn [repeat schedule_shape]. split; [reflexivity|].
  assert (E : (N.of_nat (S slot) - 1 = N.of_nat slot)%N) by lia.
  rewrite E. apply IH; lia.
Qed.
Lemma schedule_shape_block_prefix_nat : forall slot c rest,
  (slot <= 3)%nat -> schedule_shape 3 rest ->
  schedule_shape (N.of_nat slot)
    (repeat None slot ++ Some c :: rest).
Proof.
  induction slot as [|slot IH]; intros c rest Hslot HRest.
  - cbn [repeat app schedule_shape]. exists c. auto.
  - cbn [repeat app schedule_shape]. split; [reflexivity|].
    assert (E : (N.of_nat (S slot) - 1 = N.of_nat slot)%N) by lia.
    rewrite E. apply IH; [lia|exact HRest].
Qed.
Lemma schedule_grants_shape : forall slot c cs tail,
  (slot <= 3)%nat -> schedule_shape 3 tail ->
  schedule_shape (N.of_nat slot)
    (schedule_grants slot (c :: cs) ++ tail).
Proof.
  intros slot c cs. revert slot c.
  induction cs as [|d ds IH]; intros slot c tail Hslot Htail.
  - cbn [schedule_grants]. rewrite <- app_assoc. cbn [app].
    exact (schedule_shape_block_prefix_nat slot c tail Hslot Htail).
  - cbn [schedule_grants]. rewrite <- app_assoc. cbn [app].
    apply schedule_shape_block_prefix_nat; [exact Hslot|].
    exact (IH 3%nat d tail ltac:(lia) Htail).
Qed.
Lemma schedule_plan_shape : forall slot c cs tail,
  (slot <= 3)%nat -> (tail <= 3)%nat ->
  schedule_shape (N.of_nat slot)
    (schedule_plan slot (c :: cs) tail).
Proof.
  intros slot c cs tail Hslot Htail. unfold schedule_plan.
  apply schedule_grants_shape; [exact Hslot|].
  exact (schedule_shape_nones_nat tail 3 ltac:(lia) ltac:(lia)).
Qed.
Definition schedule_slot_nat (p : N) : nat :=
  (3 - N.to_nat (marks p))%nat.
Definition schedule_values (cs : list N) (b : N) : list N :=
  (b - 1)%N :: rev (map dec4 cs).
Definition bulk_schedule (p rem : N) (cs : list N) (b : N)
  : list (option N) :=
  schedule_plan (schedule_slot_nat p) (schedule_values cs b)
    (N.to_nat (marks rem)).
Lemma marks_to_nat_le3 : forall p,
  (p < 28)%N -> (N.to_nat (marks p) <= 3)%nat.
Proof.
  intros p Hp.
  pose proof (marks_le3 p Hp) as H.
  assert (E : marks p = 0%N \/
              marks p = 1%N \/
              marks p = 2%N \/
              marks p = 3%N) by lia.
  destruct E as [E|[E|[E|E]]]; rewrite E; cbn [N.to_nat]; lia.
Qed.
Lemma lin_sched_slot_nat : forall p,
  (p < 28)%N ->
  lin_sched_slot p = N.of_nat (schedule_slot_nat p).
Proof.
  intros p Hp. unfold lin_sched_slot, schedule_slot_nat.
  pose proof (marks_le3 p Hp) as H.
  assert (E : marks p = 0%N \/
              marks p = 1%N \/
              marks p = 2%N \/
              marks p = 3%N) by lia.
  destruct E as [E|[E|[E|E]]]; rewrite E; reflexivity.
Qed.
Lemma bulk_schedule_stock : forall p rem cs b,
  schedule_stock (bulk_schedule p rem cs b) =
  crossed_post cs b [].
Proof.
  intros p rem cs b. unfold bulk_schedule, schedule_values.
  rewrite schedule_plan_stock. cbn [rev].
  rewrite rev_involutive, runway_app.
  cbn [runway app crossed_post].
  rewrite app_nil_r. reflexivity.
Qed.
Lemma bulk_schedule_length : forall p rem cs b,
  (p < 28)%N -> (rem < 28)%N ->
  length (bulk_schedule p rem cs b) =
  N.to_nat
    (marks (28 * N.of_nat (S (length cs)) + rem) -
     marks p).
Proof.
  intros p rem cs b Hp Hr.
  unfold bulk_schedule, schedule_values.
  rewrite schedule_plan_length, length_rev, map_length.
  rewrite marks_split by exact Hr.
  rewrite N2Nat.inj_sub.
  rewrite N2Nat.inj_add, N2Nat.inj_mul, Nat2N.id.
  change (N.to_nat 4) with 4%nat.
  unfold schedule_slot_nat.
  pose proof (marks_to_nat_le3 p Hp) as HMp.
  pose proof (marks_to_nat_le3 rem Hr) as HMr.
  lia.
Qed.
Lemma bulk_schedule_shape : forall p rem cs b,
  (p < 28)%N -> (rem < 28)%N ->
  schedule_shape (lin_sched_slot p)
    (bulk_schedule p rem cs b).
Proof.
  intros p rem cs b Hp Hr.
  rewrite (lin_sched_slot_nat p Hp).
  unfold bulk_schedule, schedule_values.
  apply schedule_plan_shape.
  - unfold schedule_slot_nat. pose proof (marks_to_nat_le3 p Hp). lia.
  - exact (marks_to_nat_le3 rem Hr).
Qed.
Definition partial_schedule (p t : N) : list (option N) :=
  repeat None
    (N.to_nat (marks (p+t) - marks p)).
Lemma partial_schedule_shape : forall p t,
  (p + t < 28)%N ->
  schedule_shape (lin_sched_slot p) (partial_schedule p t).
Proof.
  intros p t Hpt.
  assert (Hp : (p < 28)%N) by lia.
  assert (HM : (marks p <= marks (p+t))%N)
    by (apply marks_mono; lia).
  rewrite (lin_sched_slot_nat p Hp).
  unfold partial_schedule.
  apply schedule_shape_nones_nat.
  - rewrite N2Nat.inj_sub by exact HM.
    unfold schedule_slot_nat.
    pose proof (marks_to_nat_le3 (p+t) Hpt). lia.
  - unfold schedule_slot_nat.
    pose proof (marks_to_nat_le3 p Hp). lia.
Qed.
Lemma partial_schedule_stock : forall p t,
  schedule_stock (partial_schedule p t) = [].
Proof. intros p t. apply schedule_stock_repeat_none. Qed.
Lemma partial_interleaved :
  forall p t b prs avail post child f f',
  (p + t < 28)%N -> (FLOOR <= b)%N ->
  delivery_cols avail = true ->
  length prs = N.to_nat t ->
  schedule_trips (partial_schedule p t) post f child f' ->
  schedule_trips prs
    (avail ++ phase_form p ++
       (4,2,b + DBu p)%N :: post) f
    (schedule_stock prs ++ avail ++ phase_form (p+t) ++
       (4,2,b + DBu (p+t))%N :: child) f'.
Proof.
  intros p t b prs avail post child f f'
    Hpt Hb HAvail HLen HChild.
  unfold partial_schedule in HChild.
  pose proof (schedule_trips_nones
    (N.to_nat (marks (p+t) - marks p))
    post f child f' HChild) as HDown.
  assert (HDown' : deliveries
      (N.to_nat
        (marks (p + N.of_nat (N.to_nat t)) -
         marks p)) post f child f').
  { rewrite N2Nat.id. exact HDown. }
  pose proof (phase_ticks_delivery
    (N.to_nat t) p b post child f f'
    ltac:(rewrite N2Nat.id; exact Hpt) Hb HDown') as HPhase.
  rewrite N2Nat.id in HPhase.
  pose proof (deliveries_cols _ avail _ _ _ _
    HAvail HPhase) as HPhaseCols.
  pose proof (deliveries_to_schedule_trips prs (N.to_nat t)
    (avail ++ phase_form p ++
       (4,2,b + DBu p)%N :: post) f
    (avail ++ phase_form (p+t) ++
       (4,2,b + DBu (p+t))%N :: child) f'
    HLen HPhaseCols) as HParent.
  repeat rewrite <- app_assoc in HParent |- *.
  exact HParent.
Qed.
Lemma bulk_schedule_nil : forall p rem b,
  bulk_schedule p rem [] b =
    (repeat None (schedule_slot_nat p) ++ [Some (b-1)%N]) ++
    repeat None (N.to_nat (marks rem)).
Proof.
  intros p rem b.
  unfold bulk_schedule, schedule_plan, schedule_values.
  reflexivity.
Qed.
Lemma bulk_schedule_snoc : forall p rem cs b d,
  (4 <= d)%N ->
  bulk_schedule p rem (cs ++ [d]) b =
    (repeat None (schedule_slot_nat p) ++ [Some (b-1)%N]) ++
    bulk_schedule 0 rem cs (d-3)%N.
Proof.
  intros p rem cs b d Hd.
  unfold bulk_schedule, schedule_plan, schedule_values.
  rewrite map_app, rev_app_distr.
  cbn [map rev schedule_grants schedule_slot_nat marks].
  replace (d - 3 - 1)%N with (dec4 d)
    by (unfold dec4; lia).
  change (schedule_slot_nat 0) with 3%nat.
  cbn [app schedule_grants].
  repeat rewrite <- app_assoc. reflexivity.
Qed.
Lemma schedule_slot_transit_count : forall p,
  (p < 28)%N ->
  S (schedule_slot_nat p) =
  N.to_nat (marks 28 - marks p).
Proof.
  intros p Hp. unfold schedule_slot_nat.
  pose proof (marks_le3 p Hp) as HM.
  change (marks 28) with 4%N.
  rewrite N2Nat.inj_sub by lia. cbn [N.to_nat]. lia.
Qed.
Lemma schedule_slot_prefix_count : forall p,
  (p < 28)%N ->
  schedule_slot_nat p =
    N.to_nat (marks 27 - marks p).
Proof.
  intros p Hp. unfold schedule_slot_nat.
  pose proof (marks_le3 p Hp) as HM.
  change (marks 27) with 3%N.
  rewrite N2Nat.inj_sub by lia. cbn [N.to_nat]. lia.
Qed.
Lemma one_runway_scheduled_deliveries :
  forall c cols p rem b post out f f',
  delivery_cols cols = true ->
  (FLOOR + 3 <= c)%N ->
  (p < 28)%N -> (rem < 28)%N -> (FLOOR <= b)%N ->
  schedule_deliveries (bulk_schedule p rem [] b) post f out f' ->
  deliveries
    (N.to_nat (28 + rem - p))
    (cols ++ rung1 c ++ phase_form p ++
       (4,2,b + DBu p)%N :: post) f
    (cols ++ phase_form rem ++
       (4,2,c - 3 + DBu rem)%N :: out) f'.
Proof.
  intros c cols p rem b post out f f' HCols Hc Hp Hr Hb HRun.
  rewrite bulk_schedule_nil in HRun.
  destruct (schedule_deliveries_app_inv
    (repeat None (schedule_slot_nat p) ++ [Some (b-1)%N])
    (repeat None (N.to_nat (marks rem)))
    post f out f' HRun) as (mid & fm & HBlock & HRest).
  destruct (schedule_deliveries_nones_some
    (schedule_slot_nat p) (b-1)%N post f mid fm HBlock)
    as (post1 & HDeliver & Emid).
  subst mid.
  rewrite (schedule_slot_transit_count p Hp) in HDeliver.
  pose proof (transit_delivery
    cols c p b post post1 f fm HCols Hp Hc Hb HDeliver) as HTransit.
  pose proof (schedule_deliveries_nones
    (N.to_nat (marks rem))
    (rung1 (b-1)%N ++ post1)
    fm out f' HRest) as HRem.
  assert (HRem' : deliveries
    (N.to_nat
      (marks (0 + N.of_nat (N.to_nat rem)) -
       marks 0))
    (rung1 (b-1)%N ++ post1) fm out f').
  { rewrite N2Nat.id, N.add_0_l.
    change (marks 0) with 0%N. rewrite N.sub_0_r.
    exact HRem. }
  pose proof (phase_ticks_delivery
    (N.to_nat rem) 0 (c-3)%N
    (rung1 (b-1)%N ++ post1) out fm f'
    ltac:(rewrite N2Nat.id; lia)
    ltac:(unfold FLOOR in *; lia) HRem') as HPartial.
  rewrite N2Nat.id, N.add_0_l in HPartial.
  change (DBu 0) with 3%N in HPartial.
  replace (c - 3 + 3)%N with c in HPartial by lia.
  pose proof (deliveries_cols _ cols _ _ _ _
    HCols HPartial) as HPartialCols.
  pose proof (deliveries_app _ _ _ _ _ _ _ _
    HTransit HPartialCols) as HBoth.
  replace (N.to_nat (28 + rem - p)) with
    (N.to_nat (28-p) + N.to_nat rem)%nat.
  2: { rewrite <- N2Nat.inj_add. f_equal. lia. }
  repeat rewrite app_assoc in HBoth |- *.
  exact HBoth.
Qed.
Theorem runway_scheduled_deliveries :
  forall c cs cols p rem b post out f f',
  delivery_cols cols = true ->
  Forall (fun x => (FLOOR + 3 <= x)%N) (c :: cs) ->
  (p < 28)%N -> (rem < 28)%N -> (FLOOR <= b)%N ->
  schedule_deliveries (bulk_schedule p rem cs b) post f out f' ->
  deliveries
    (N.to_nat
      (28 * N.of_nat (length (c :: cs)) + rem - p))
    (cols ++ runway (c :: cs) ++
       phase_form p ++
       (4,2,b + DBu p)%N :: post) f
    (cols ++ phase_form rem ++
       (4,2,c - 3 + DBu rem)%N :: out) f'.
Proof.
  intros c cs. revert c.
  induction cs as [|d cs IH] using rev_ind;
    intros c cols p rem b post out f f'
      HCols HLevels Hp Hr Hb HRun.
  - change (length [c]) with 1%nat.
    change (runway [c]) with
      (rung1 c).
    replace (28 * N.of_nat 1 + rem - p)%N with (28 + rem - p)%N by lia.
    exact (one_runway_scheduled_deliveries
      c cols p rem b post out f f' HCols
      ltac:(inversion HLevels; assumption) Hp Hr Hb HRun).
  - assert (ELevels : c :: cs ++ [d] = (c :: cs) ++ [d]) by reflexivity.
    rewrite ELevels in HLevels.
    apply Forall_app in HLevels. destruct HLevels as [HOuter HLast].
    inversion HLast as [|d0 nil Hd HNil]; subst d0 nil.
    assert (Hd4 : (4 <= d)%N)
      by (unfold FLOOR in Hd; lia).
    rewrite (bulk_schedule_snoc p rem cs b d Hd4) in HRun.
    destruct (schedule_deliveries_app_inv
      (repeat None (schedule_slot_nat p) ++ [Some (b-1)%N])
      (bulk_schedule 0 rem cs (d-3)%N)
      post f out f' HRun) as (mid & fm & HBlock & HRest).
    destruct (schedule_deliveries_nones_some
      (schedule_slot_nat p) (b-1)%N post f mid fm HBlock)
      as (post1 & HDeliver & Emid).
    subst mid.
    rewrite (schedule_slot_transit_count p Hp) in HDeliver.
    assert (HOuterCols : delivery_cols
      (cols ++ runway (c :: cs)) = true).
    { rewrite delivery_cols_app, HCols,
        delivery_cols_runway. reflexivity. }
    pose proof (transit_delivery
      (cols ++ runway (c :: cs))
      d p b post post1 f fm HOuterCols Hp Hd Hb HDeliver) as HFirst.
    pose proof (IH c cols 0%N rem (d-3)%N
      (rung1 (b-1)%N ++ post1) out fm f'
      HCols HOuter ltac:(lia) Hr ltac:(lia) HRest) as HDeep.
    rewrite N.sub_0_r in HDeep.
    change (DBu 0) with 3%N in HDeep.
    replace (d - 3 + 3)%N with d in HDeep by lia.
    repeat rewrite app_assoc in HFirst, HDeep.
    pose proof (deliveries_app _ _ _ _ _ _ _ _
      HFirst HDeep) as HBoth.
    replace (length (c :: cs ++ [d])) with (S (length (c :: cs)))
      by (cbn [length]; rewrite length_app; cbn [length]; lia).
    rewrite Nat2N.inj_succ.
    replace
      (N.to_nat
        (28 * N.succ (N.of_nat (length (c :: cs))) + rem - p))
      with
      (N.to_nat (28-p) +
       N.to_nat (28 * N.of_nat (length (c :: cs)) + rem))%nat.
    2: { rewrite <- N2Nat.inj_add. f_equal. lia. }
    rewrite ELevels, runway_app.
    cbn [runway app] in HBoth |- *.
    repeat rewrite app_nil_r in HBoth.
    repeat rewrite app_nil_r.
    repeat rewrite app_assoc in HBoth.
    repeat rewrite app_assoc.
    exact HBoth.
Qed.
Fixpoint schedule_count (rs : list (option N)) : nat :=
  match rs with
  | [] => O
  | None :: r => schedule_count r
  | Some _ :: r => S (schedule_count r)
  end.
Lemma schedule_count_app : forall a b,
  schedule_count (a ++ b) = (schedule_count a + schedule_count b)%nat.
Proof.
  induction a as [|[c|] a IH]; intros b;
    cbn [schedule_count app]; rewrite ?IH; lia.
Qed.
Lemma sched_grants_zero_succ : forall take,
  lin_sched_grants 0 (1 + take) =
  (1 + lin_sched_grants 3 take)%N.
Proof.
  intros take. unfold lin_sched_grants.
  replace (1 + take + (3 - 0))%N with (1 * 4 + take)%N by lia.
  rewrite N.div_add_l by discriminate.
  replace (take + (3 - 3))%N with take by lia. reflexivity.
Qed.
Lemma sched_grants_pos_succ : forall slot take,
  (slot <= 3)%N -> slot <> 0%N ->
  lin_sched_grants slot (1 + take) =
  lin_sched_grants (slot - 1) take.
Proof.
  intros slot take Hle Hne.
  assert (E : slot = 1%N \/ slot = 2%N \/ slot = 3%N) by lia.
  destruct E as [E|[E|E]]; subst slot; unfold lin_sched_grants;
    f_equal; lia.
Qed.
Lemma schedule_shape_count : forall rs slot,
  (slot <= 3)%N -> schedule_shape slot rs ->
  N.of_nat (schedule_count rs) =
    lin_sched_grants slot (N.of_nat (length rs)).
Proof.
  induction rs as [|oc rs IH]; intros slot Hslot Hshape.
  - cbn [schedule_count length N.of_nat].
    unfold lin_sched_grants.
    rewrite N.div_small; lia.
  - destruct (N.eq_dec slot 0) as [->|Hnz].
    + destruct (schedule_shape_cons_zero oc rs Hshape)
        as (c & -> & Hrest).
      cbn [schedule_count length]. rewrite !Nat2N.inj_succ.
      replace (N.succ (N.of_nat (length rs)))%N with
        (1 + N.of_nat (length rs))%N by lia.
      rewrite (IH 3 ltac:(lia) Hrest), sched_grants_zero_succ.
      lia.
    + destruct (schedule_shape_cons_pos slot oc rs Hnz Hshape)
        as (-> & Hrest).
      cbn [schedule_count length]. rewrite !Nat2N.inj_succ.
      replace (N.succ (N.of_nat (length rs)))%N with
        (1 + N.of_nat (length rs))%N by lia.
      rewrite (IH (slot-1)%N ltac:(lia) Hrest).
      symmetry. apply sched_grants_pos_succ; assumption.
Qed.
Lemma schedule_stock_length : forall rs,
  length (schedule_stock rs) = (2 * schedule_count rs)%nat.
Proof.
  induction rs as [|[c|] rs IH]; cbn [schedule_stock schedule_count length].
  - reflexivity.
  - rewrite length_app, IH.
    cbn [rung1 length]. lia.
  - exact IH.
Qed.
Lemma schedule_stock_first_skip : forall n rs,
  schedule_stock rs =
    schedule_stock (skipn n rs) ++ schedule_stock (firstn n rs).
Proof.
  intros n rs.
  rewrite <- (firstn_skipn n rs) at 1.
  apply schedule_stock_app.
Qed.
Lemma schedule_shape_firstn : forall n rs slot,
  schedule_shape slot rs -> schedule_shape slot (firstn n rs).
Proof.
  induction n as [|n IH]; intros rs slot H; [exact I|].
  destruct rs as [|oc rs]; [exact I|].
  cbn [firstn schedule_shape] in *.
  destruct (slot =? 0)%N.
  - destruct H as (c & -> & HR). exists c. split; [reflexivity|].
    exact (IH rs 3 HR).
  - destruct H as (-> & HR). split; [reflexivity|].
    exact (IH rs (slot-1)%N HR).
Qed.
Lemma schedule_count_firstn : forall n rs slot,
  (slot <= 3)%N -> schedule_shape slot rs ->
  N.of_nat (schedule_count (firstn n rs)) =
  lin_sched_grants slot (N.of_nat (length (firstn n rs))).
Proof.
  intros n rs slot HS HShape. apply schedule_shape_count; [exact HS|].
  exact (schedule_shape_firstn n rs slot HShape).
Qed.
Lemma sched_slot_advance_le3 : forall slot take,
  (slot <= 3)%N ->
  (lin_sched_slot_advance slot take <= 3)%N.
Proof.
  intros slot take HSlot. unfold lin_sched_slot_advance.
  assert (HMod : ((3 - slot + take) mod 4 < 4)%N)
    by (apply N.mod_lt; lia).
  lia.
Qed.
Lemma schedule_count_first4 : forall rs slot,
  (4 <= length rs)%nat -> (slot <= 3)%N -> schedule_shape slot rs ->
  schedule_count (firstn 4 rs) = 1%nat.
Proof.
  intros rs slot HLen HSlot HShape.
  pose proof (schedule_count_firstn 4 rs slot HSlot HShape) as HC.
  rewrite length_firstn, PeanoNat.Nat.min_l in HC by lia.
  assert (ESlot : slot = 0%N \/ slot = 1%N \/
                  slot = 2%N \/ slot = 3%N) by lia.
  destruct ESlot as [E|[E|[E|E]]]; subst slot;
    cbv [lin_sched_grants] in HC;
    apply (f_equal N.to_nat) in HC;
    rewrite Nat2N.id in HC; cbn [N.to_nat] in HC; lia.
Qed.
Lemma schedule_stock_skip_length : forall n rs slot,
  (n <= length rs)%nat -> (slot <= 3)%N -> schedule_shape slot rs ->
  length (schedule_stock (skipn n rs)) =
  (length (schedule_stock rs) -
    2 * N.to_nat (lin_sched_grants slot (N.of_nat n)))%nat.
Proof.
  intros n rs slot Hn Hslot Hshape.
  pose proof (schedule_stock_first_skip n rs) as E.
  apply (f_equal (@length bg)) in E.
  rewrite length_app in E.
  rewrite !schedule_stock_length in E.
  assert (HL : length (firstn n rs) = n)
    by (rewrite length_firstn; lia).
  pose proof (schedule_count_firstn n rs slot Hslot Hshape) as HC.
  rewrite HL in HC. apply (f_equal N.to_nat) in HC.
  rewrite Nat2N.id in HC. rewrite HC in E.
  rewrite !schedule_stock_length. lia.
Qed.
Definition schedule_slot_step (slot : N) : N :=
  if slot =? 0 then 3 else slot - 1.
Fixpoint schedule_slot_steps (slot : N) (n : nat) : N :=
  match n with
  | O => slot
  | S n' => schedule_slot_steps (schedule_slot_step slot) n'
  end.
Lemma schedule_slot_step_le3 : forall slot,
  (slot <= 3)%N -> (schedule_slot_step slot <= 3)%N.
Proof.
  intros slot H. unfold schedule_slot_step.
  destruct (slot =? 0)%N; lia.
Qed.
Lemma schedule_shape_skip_steps : forall n rs slot,
  (slot <= 3)%N -> schedule_shape slot rs ->
  schedule_shape (schedule_slot_steps slot n) (skipn n rs).
Proof.
  induction n as [|n IH]; intros rs slot Hslot Hshape;
    [exact Hshape|].
  destruct rs as [|oc rs]; [exact I|].
  cbn [skipn schedule_slot_steps].
  destruct (N.eq_dec slot 0) as [->|Hnz].
  - destruct (schedule_shape_cons_zero oc rs Hshape)
      as (c & -> & HR).
    unfold schedule_slot_step. cbn [N.eqb].
    exact (IH rs 3 ltac:(lia) HR).
  - destruct (schedule_shape_cons_pos slot oc rs Hnz Hshape)
      as (_ & HR).
    unfold schedule_slot_step.
    assert (E : (slot =? 0)%N = false) by (apply N.eqb_neq; exact Hnz).
    rewrite E.
    exact (IH rs (slot-1)%N ltac:(lia) HR).
Qed.
Lemma sched_slot_advance_succ : forall slot take,
  (slot <= 3)%N ->
  lin_sched_slot_advance slot (1 + take) =
  lin_sched_slot_advance (schedule_slot_step slot) take.
Proof.
  intros slot take Hslot.
  assert (E : slot = 0%N \/ slot = 1%N \/ slot = 2%N \/ slot = 3%N)
    by lia.
  destruct E as [E|[E|[E|E]]]; subst slot;
    unfold schedule_slot_step, lin_sched_slot_advance;
    cbn [N.eqb].
  - replace (3-0)%N with 3%N by lia.
    replace (3-3)%N with 0%N by lia.
    replace (3 + (1 + take))%N with (take + 1 * 4)%N by lia.
    rewrite N.Div0.mod_add. reflexivity.
  - first [reflexivity | solve [f_equal; f_equal; lia] | solve [f_equal; lia]].
  - first [reflexivity | solve [f_equal; f_equal; lia] | solve [f_equal; lia]].
  - first [reflexivity | solve [f_equal; f_equal; lia] | solve [f_equal; lia]].
Qed.
Lemma schedule_slot_steps_eq : forall n slot,
  (slot <= 3)%N ->
  schedule_slot_steps slot n =
  lin_sched_slot_advance slot (N.of_nat n).
Proof.
  induction n as [|n IH]; intros slot Hslot.
  - cbn [schedule_slot_steps N.of_nat].
    unfold lin_sched_slot_advance.
    rewrite N.add_0_r.
    rewrite N.mod_small; lia.
  - cbn [schedule_slot_steps]. rewrite Nat2N.inj_succ.
    replace (N.succ (N.of_nat n))%N with (1 + N.of_nat n)%N by lia.
    rewrite sched_slot_advance_succ by exact Hslot.
    apply IH. exact (schedule_slot_step_le3 slot Hslot).
Qed.
Lemma schedule_shape_skipn : forall n rs slot,
  (slot <= 3)%N -> schedule_shape slot rs ->
  schedule_shape
    (lin_sched_slot_advance slot (N.of_nat n)) (skipn n rs).
Proof.
  intros n rs slot Hslot Hshape.
  rewrite <- schedule_slot_steps_eq by exact Hslot.
  exact (schedule_shape_skip_steps n rs slot Hslot Hshape).
Qed.
Lemma schedule_count_blocks : forall k rs slot,
  (slot <= 3)%N -> schedule_shape slot rs ->
  (4*k <= length rs)%nat -> (k <= schedule_count rs)%nat.
Proof.
  induction k as [|k IH]; intros rs slot HSlot HShape HLen; [lia|].
  assert (HFour : (4 <= length rs)%nat) by lia.
  pose proof (schedule_count_first4 rs slot HFour HSlot HShape) as HFirst.
  pose proof (schedule_shape_skipn 4 rs slot HSlot HShape) as HRestShape.
  pose proof (sched_slot_advance_le3 slot 4 HSlot) as HRestSlot.
  assert (HRestLen : (4*k <= length (skipn 4 rs))%nat).
  { rewrite length_skipn. lia. }
  pose proof (IH (skipn 4 rs)
    (lin_sched_slot_advance slot (N.of_nat 4))
    HRestSlot HRestShape HRestLen) as HRest.
  rewrite <- (firstn_skipn 4 rs), schedule_count_app.
  rewrite HFirst. lia.
Qed.
Definition schedule_release (oc : option N) (w : word) : word :=
  match oc with
  | None => w
  | Some c => rung1 c ++ w
  end.
Lemma schedule_step_strip :
  forall oc rs base cols s f renewed out f2,
  lin_dtick_after_seek
      ((base ++ schedule_stock (oc :: rs)) ++ cols) s f
    = Some (renewed, out, f2) ->
  (renewed = true -> (2 <= length cols)%nat) ->
  exists body,
    lin_dtick_after_seek cols s f
      = Some (renewed, body, f2) /\
    out = (base ++ schedule_stock rs) ++ schedule_release oc body.
Proof.
  intros oc rs base cols s f renewed out f2 HRun HLen.
  destruct (lin_dtick_after_seek_strip
    (base ++ schedule_stock (oc :: rs)) cols s f
    renewed out f2 HRun HLen) as (body & HBody & ->).
  exists body. split; [exact HBody|].
  destruct oc as [c|]; cbn [schedule_stock schedule_release].
  - rewrite !app_assoc. reflexivity.
  - reflexivity.
Qed.
Lemma schedule_dtick_after_seek : forall tail cols s f renewed body f2,
  seek tail = (cols, s) ->
  lin_dtick_after_seek cols s f
    = Some (renewed, body, f2) ->
  dtick tail f = Some (body, f2).
Proof.
  intros tail cols s f renewed body f2 ESeek HRun.
  pose proof (lin_dtick_after_seek_proj
    cols s f renewed body f2 HRun) as HProj.
  unfold dtick. rewrite ESeek, HProj. reflexivity.
Qed.
Lemma schedule_run_cons : forall oc rs tail cols s f renewed body f2 out f',
  seek tail = (cols, s) ->
  lin_dtick_after_seek cols s f
    = Some (renewed, body, f2) ->
  schedule_run rs (schedule_release oc body) f2 out f' ->
  schedule_run (oc :: rs) tail f out f'.
Proof.
  intros oc rs tail cols s f renewed body f2 out f'
    ESeek HRun HRest.
  pose proof (schedule_dtick_after_seek
    tail cols s f renewed body f2 ESeek HRun) as HD.
  destruct oc as [c|].
  - eapply schedule_run_some; eassumption.
  - eapply schedule_run_none; eassumption.
Qed.
Definition schedule_frame_view (fr : lsc_frame)
    (suffix : word) (rs : list (option N))
    (base tail : word) : Prop :=
  (lsSlot fr <= 3)%N /\
  length rs = N.to_nat (lsTicks fr) /\
  schedule_shape (lsSlot fr) rs /\
  delivery_cols base = true /\
  suffix = (base ++ schedule_stock rs) ++ tail /\
  length (base ++ schedule_stock rs) = lsGap fr.
Lemma schedule_ticks_tail : forall tk (oc : option N) (rs : list (option N)),
  length (oc :: rs) = N.to_nat tk ->
  length rs = N.to_nat (tk - 1).
Proof.
  intros tk oc rs HLen. cbn [length] in HLen.
  assert (Htk : (1 <= tk)%N).
  { destruct tk; cbn [N.to_nat] in HLen; lia. }
  rewrite N2Nat.inj_sub by exact Htk. cbn [N.to_nat]. lia.
Qed.
Lemma schedule_ticks_skip : forall tk take (rs : list (option N)),
  length rs = N.to_nat tk -> (take <= tk)%N ->
  length (skipn (N.to_nat take) rs) = N.to_nat (tk - take).
Proof.
  intros tk take rs HLen HTake.
  rewrite length_skipn, HLen.
  rewrite N2Nat.inj_sub by exact HTake. lia.
Qed.
Lemma schedule_frame_view_advance_one :
  forall fr suffix oc rs base tail body,
  schedule_frame_view fr suffix (oc :: rs) base tail ->
  schedule_frame_view (lin_sched_advance fr 1)
    ((base ++ schedule_stock rs) ++ schedule_release oc body)
    rs base (schedule_release oc body).
Proof.
  intros fr suffix oc rs base tail body
    (HSlot & HLen & HShape & HCols & _ & HGap).
  unfold schedule_frame_view, lin_sched_advance.
  cbn [lsSlot lsTicks lsGap].
  repeat split.
  - unfold lin_sched_slot_advance.
    assert (H : ((3 - lsSlot fr + 1) mod 4 < 4)%N)
      by (apply N.mod_lt; lia).
    lia.
  - exact (schedule_ticks_tail (lsTicks fr) oc rs HLen).
  - change (schedule_shape
      (lin_sched_slot_advance (lsSlot fr) 1) rs).
    replace rs with (skipn 1 (oc :: rs)) by reflexivity.
    replace 1%N with (N.of_nat 1) by reflexivity.
    exact (schedule_shape_skipn 1 (oc :: rs)
      (lsSlot fr) HSlot HShape).
  - exact HCols.
  - rewrite <- HGap.
    rewrite !length_app.
    destruct (N.eq_dec (lsSlot fr) 0) as [E0|E0].
    + rewrite E0 in HShape |- *.
      destruct (schedule_shape_cons_zero oc rs HShape)
        as (c & -> & _).
      cbn [schedule_stock rung1 length
           lin_sched_grants].
      rewrite length_app.
      replace (length (rung1 c)) with 2%nat
        by reflexivity.
      replace (N.to_nat (lin_sched_grants 0 1)) with 1%nat
        by reflexivity.
      lia.
    + destruct (schedule_shape_cons_pos
        (lsSlot fr) oc rs E0 HShape) as (-> & _).
      cbn [schedule_stock].
      assert (E : lsSlot fr = 1%N \/
                  lsSlot fr = 2%N \/
                  lsSlot fr = 3%N) by lia.
      destruct E as [E|[E|E]].
      * replace (N.to_nat
          (lin_sched_grants (lsSlot fr) 1)) with 0%nat
          by (rewrite E; reflexivity).
        rewrite PeanoNat.Nat.mul_0_r, PeanoNat.Nat.sub_0_r. reflexivity.
      * replace (N.to_nat
          (lin_sched_grants (lsSlot fr) 1)) with 0%nat
          by (rewrite E; reflexivity).
        rewrite PeanoNat.Nat.mul_0_r, PeanoNat.Nat.sub_0_r. reflexivity.
      * replace (N.to_nat
          (lin_sched_grants (lsSlot fr) 1)) with 0%nat
          by (rewrite E; reflexivity).
        rewrite PeanoNat.Nat.mul_0_r, PeanoNat.Nat.sub_0_r. reflexivity.
Qed.
Lemma schedule_stock_firstn_27_ge2 : forall rs slot,
  (slot <= 3)%N -> schedule_shape slot rs ->
  (27 <= length rs)%nat ->
  (2 <= length (schedule_stock (firstn 27 rs)))%nat.
Proof.
  intros rs slot HSlot HShape HLen.
  assert (HFirst : length (firstn 27 rs) = 27%nat)
    by (rewrite length_firstn; lia).
  pose proof (schedule_count_firstn 27 rs slot HSlot HShape) as HC.
  rewrite HFirst in HC.
  apply (f_equal N.to_nat) in HC. rewrite Nat2N.id in HC.
  assert (ESlot : slot = 0%N \/ slot = 1%N \/
                  slot = 2%N \/ slot = 3%N) by lia.
  destruct ESlot as [E|[E|[E|E]]]; subst slot;
    cbv [lin_sched_grants] in HC;
    rewrite schedule_stock_length; lia.
Qed.
Lemma schedule_stock_firstn_length : forall n rs slot,
  (n <= length rs)%nat -> (slot <= 3)%N -> schedule_shape slot rs ->
  length (schedule_stock (firstn n rs)) =
    (2 * N.to_nat
      (lin_sched_grants slot (N.of_nat n)))%nat.
Proof.
  intros n rs slot Hn HSlot HShape.
  rewrite schedule_stock_length.
  pose proof (schedule_count_firstn n rs slot HSlot HShape) as HC.
  rewrite length_firstn, PeanoNat.Nat.min_l in HC by exact Hn.
  apply (f_equal N.to_nat) in HC. rewrite Nat2N.id in HC.
  rewrite HC. reflexivity.
Qed.
Lemma schedule_bulk_ready : forall fr prs pk take avail colflat,
  (lsSlot fr <= 3)%N ->
  length prs = N.to_nat (lsTicks fr) ->
  schedule_shape (lsSlot fr) prs ->
  (pk < 28)%N -> ((pk+take)/28 <> 0)%N ->
  (take <= lsTicks fr)%N ->
  colflat = (lsGap fr + length avail)%nat ->
  lin_sched_bulk_safe fr colflat pk take = true ->
  (2 <= length
    (schedule_stock
       (firstn (N.to_nat (27-pk))
         (firstn (N.to_nat take) prs)) ++ avail))%nat.
Proof.
  intros fr prs pk take avail colflat HSlot HLen HShape
    Hp HFull HTake HCol HSafe.
  assert (HFlight : (28-pk <= take)%N).
  { assert (Hge : (28 <= pk+take)%N).
    { destruct (N.lt_ge_cases (pk+take) 28) as [Hlt|Hge]; [|exact Hge].
      rewrite N.div_small in HFull by exact Hlt. contradiction. }
    lia. }
  assert (HTakeNat : (N.to_nat take <= length prs)%nat).
  { rewrite HLen. apply PeanoNat.Nat.compare_le_iff.
    rewrite <- N2Nat.inj_compare. apply N.compare_le_iff. exact HTake. }
  assert (HPreTake :
    (N.to_nat (27-pk) <= N.to_nat take)%nat).
  { apply PeanoNat.Nat.compare_le_iff.
    rewrite <- N2Nat.inj_compare. apply N.compare_le_iff. lia. }
  assert (EFirst :
    firstn (N.to_nat (27-pk)) (firstn (N.to_nat take) prs) =
    firstn (N.to_nat (27-pk)) prs).
  { rewrite firstn_firstn, PeanoNat.Nat.min_l by exact HPreTake.
    reflexivity. }
  rewrite EFirst.
  pose proof (schedule_stock_firstn_length
    (N.to_nat (27-pk)) prs (lsSlot fr)
    ltac:(lia) HSlot HShape) as HStockLen.
  unfold lin_sched_bulk_safe in HSafe.
  destruct (((pk+take)/28) =? 0)%N eqn:EFull.
  { apply N.eqb_eq in EFull. contradiction. }
  apply andb_prop in HSafe. destruct HSafe as [_ HSafe].
  apply PeanoNat.Nat.leb_le in HSafe.
  rewrite HCol in HSafe.
  rewrite length_app, HStockLen.
  rewrite N2Nat.id.
  lia.
Qed.
Lemma schedule_bulk_stock_enough : forall fr prs pk take avail colflat,
  (lsSlot fr <= 3)%N ->
  length prs = N.to_nat (lsTicks fr) ->
  schedule_shape (lsSlot fr) prs ->
  (pk < 28)%N -> ((pk+take)/28 <> 0)%N ->
  (take <= lsTicks fr)%N ->
  colflat = (lsGap fr + length avail)%nat ->
  lin_sched_bulk_safe fr colflat pk take = true ->
  (2 * N.to_nat ((pk+take)/28) <=
    length (schedule_stock (firstn (N.to_nat take) prs) ++ avail))%nat.
Proof.
  intros fr prs pk take avail colflat HSlot HLen HShape
    Hp HFull HTake HCol HSafe.
  pose proof (schedule_bulk_ready fr prs pk take avail colflat
    HSlot HLen HShape Hp HFull HTake HCol HSafe) as HReady.
  set (used := firstn (N.to_nat take) prs) in *.
  set (pre := firstn (N.to_nat (27-pk)) used) in *.
  set (after := skipn (N.to_nat (27-pk)) used) in *.
  assert (HTakeNat : (N.to_nat take <= length prs)%nat).
  { rewrite HLen. apply PeanoNat.Nat.compare_le_iff.
    rewrite <- N2Nat.inj_compare. apply N.compare_le_iff. exact HTake. }
  assert (HUsedLen : length used = N.to_nat take).
  { unfold used. rewrite length_firstn, PeanoNat.Nat.min_l by exact HTakeNat.
    reflexivity. }
  assert (HFlight : (28-pk <= take)%N).
  { assert (Hge : (28 <= pk+take)%N).
    { destruct (N.lt_ge_cases (pk+take) 28) as [Hlt|Hge]; [|exact Hge].
      rewrite N.div_small in HFull by exact Hlt. contradiction. }
    lia. }
  assert (HPreNat :
    (N.to_nat (27-pk) <= length used)%nat).
  { rewrite HUsedLen. apply PeanoNat.Nat.compare_le_iff.
    rewrite <- N2Nat.inj_compare. apply N.compare_le_iff. lia. }
  assert (HUsedShape : schedule_shape (lsSlot fr) used).
  { unfold used. exact (schedule_shape_firstn _ _ _ HShape). }
  assert (HAfterSlot :
    (lin_sched_slot_advance (lsSlot fr)
      (N.of_nat (N.to_nat (27-pk))) <= 3)%N)
    by (apply sched_slot_advance_le3; exact HSlot).
  assert (HAfterShape : schedule_shape
      (lin_sched_slot_advance (lsSlot fr)
        (N.of_nat (N.to_nat (27-pk)))) after).
  { unfold after. exact (schedule_shape_skipn _ _ _ HSlot HUsedShape). }
  set (full := ((pk+take)/28)%N).
  assert (HFullNat : (1 <= N.to_nat full)%nat).
  { destruct full eqn:EFullNat.
    - exfalso. apply HFull. exact EFullNat.
    - cbn [N.to_nat]. lia. }
  assert (HpNat : (N.to_nat pk < 28)%nat).
  { change (N.to_nat pk < N.to_nat 28)%nat.
    apply PeanoNat.Nat.compare_lt_iff.
    rewrite <- N2Nat.inj_compare. apply N.compare_lt_iff. exact Hp. }
  pose proof (N.div_mod' (pk+take) 28) as HDiv.
  apply (f_equal N.to_nat) in HDiv.
  rewrite !N2Nat.inj_add, !N2Nat.inj_mul in HDiv.
  change (N.to_nat 28) with 28%nat in HDiv.
  assert (HAfterLen :
    (4 * (N.to_nat full - 1) <= length after)%nat).
  { unfold after. rewrite length_skipn, HUsedLen.
    rewrite N2Nat.inj_sub by lia.
    change (N.to_nat 27) with 27%nat.
    unfold full in *. lia. }
  pose proof (schedule_count_blocks (N.to_nat full - 1) after
    (lin_sched_slot_advance (lsSlot fr)
      (N.of_nat (N.to_nat (27-pk))))
    HAfterSlot HAfterShape HAfterLen) as HAfterCount.
  assert (HCount : schedule_count used =
      (schedule_count pre + schedule_count after)%nat).
  { unfold pre, after. rewrite <- (firstn_skipn (N.to_nat (27-pk)) used)
      at 1. apply schedule_count_app. }
  rewrite length_app, !schedule_stock_length in HReady |- *.
  rewrite HCount. lia.
Qed.
Lemma list_split_length : forall (A : Type) (xs : list A) n,
  (n <= length xs)%nat ->
  exists a b, xs = a ++ b /\ length a = n.
Proof.
  intros A xs n Hn. exists (firstn n xs), (skipn n xs).
  split; [symmetry; apply firstn_skipn|].
  rewrite length_firstn. lia.
Qed.
Lemma split_flight_schedule : forall p (prs : list (option N)) R,
  (p < 28)%N ->
  length prs = (N.to_nat (28-p) + R)%nat ->
  exists pre oc rest,
    prs = (pre ++ [oc]) ++ rest /\
    length pre = N.to_nat (27-p) /\
    length rest = R.
Proof.
  intros p prs R Hp HLen.
  assert (EFlight : N.to_nat (28-p) = S (N.to_nat (27-p))).
  { rewrite !N2Nat.inj_sub by lia.
    change (N.to_nat 28) with 28%nat.
    change (N.to_nat 27) with 27%nat. lia. }
  destruct (list_split_length (option N) prs (N.to_nat (28-p)))
    as (flight & rest & EPrs & HFlight).
  { rewrite HLen. lia. }
  destruct (list_snoc_of_length_succ (option N) flight
    (N.to_nat (27-p))) as (pre & oc & EFlightWord & HPre).
  { rewrite <- EFlight. exact HFlight. }
  exists pre, oc, rest. subst flight. split; [exact EPrs|].
  split; [exact HPre|].
  apply (f_equal (@length (option N))) in EPrs.
  rewrite length_app, HFlight, HLen in EPrs. lia.
Qed.
Lemma one_runway_interleaved :
  forall p b c prs pre oc avail outer post child f f',
  (p < 28)%N ->
  (FLOOR <= b)%N ->
  (FLOOR + 3 <= c)%N ->
  delivery_cols avail = true ->
  prs = pre ++ [oc] ->
  length pre = N.to_nat (27-p) ->
  (2 <= length (schedule_stock pre ++ avail))%nat ->
  schedule_stock prs ++ avail =
    outer ++ rung1 c ->
  schedule_trips (bulk_schedule p 0 [] b) post f child f' ->
  schedule_trips prs
    (avail ++ phase_form p ++
       (4,2,b + DBu p)%N :: post) f
    (outer ++ phase_form 0 ++ (4,2,c)%N :: child) f'.
Proof.
  intros p b c prs pre oc avail outer post child f f'
    Hp Hb Hc HAvailCols HPrs HPreLen HReady HStock HChild.
  subst prs.
  assert (EBulk : bulk_schedule p 0 [] b =
      repeat None (schedule_slot_nat p) ++ [Some (b-1)%N]).
  { rewrite bulk_schedule_nil.
    cbn [marks N.to_nat repeat]. rewrite app_nil_r.
    reflexivity. }
  rewrite EBulk in HChild.
  destruct (schedule_trips_app_inv
    (repeat None (schedule_slot_nat p)) [Some (b-1)%N]
    post f child f' HChild)
    as (mid & fm & HChildPre & HChildLast).
  pose proof (schedule_trips_nones
    (schedule_slot_nat p) post f mid fm HChildPre) as HDownPre.
  rewrite (schedule_slot_prefix_count p Hp) in HDownPre.
  pose proof (ticks_to_jump
    p b post mid f fm Hp Hb HDownPre) as HTargetPre.
  pose proof (deliveries_cols _ avail _ _ _ _
    HAvailCols HTargetPre) as HTargetPreCols.
  pose proof (deliveries_to_schedule_trips pre
    (N.to_nat (27-p))
    (avail ++ phase_form p ++
       (4,2,b + DBu p)%N :: post) f
    (avail ++ phase_form 27 ++ (4,2,b)%N :: mid) fm
    HPreLen HTargetPreCols) as HParentPre.
  destruct (schedule_trips_one_some
    (b-1)%N mid fm child f' HChildLast)
    as (tail & ft & HDownLast & EChild).
  assert (HFactor : exists outer0,
      schedule_stock pre ++ avail =
        outer0 ++ rung1 c /\
      outer = schedule_release oc outer0).
  { destruct oc as [d|].
    - rewrite schedule_stock_snoc in HStock.
      replace
        ((rung1 d ++ schedule_stock pre) ++ avail)
        with
        (rung1 d ++ (schedule_stock pre ++ avail))
        in HStock by apply app_assoc.
      destruct (app_suffix_factor bg
        (rung1 d)
        (schedule_stock pre ++ avail) outer
        (rung1 c) HStock)
        as (outer0 & EOuter & EAvail).
      { cbn [rung1 length]. lia. }
      exists outer0. split; [exact EAvail|].
      cbn [schedule_release]. exact EOuter.
    - rewrite schedule_stock_snoc in HStock.
      exists outer. split; [exact HStock|reflexivity]. }
  destruct HFactor as (outer0 & EAvail & EOuter).
  assert (HOuterCols : delivery_cols outer0 = true).
  { assert (HAll : delivery_cols
        (schedule_stock pre ++ avail) = true).
    { rewrite delivery_cols_app,
        schedule_stock_cols, HAvailCols. reflexivity. }
    rewrite EAvail, delivery_cols_app in HAll.
    apply andb_prop in HAll as [HOut _]. exact HOut. }
  assert (HParentPre' : schedule_trips pre
      (avail ++ phase_form p ++
         (4,2,b + DBu p)%N :: post) f
      (outer0 ++ rung1 c ++
         phase_form 27 ++ (4,2,b)%N :: mid) fm).
  { replace
      (schedule_stock pre ++
        (avail ++ phase_form 27 ++ (4,2,b)%N :: mid))
      with
      (outer0 ++ rung1 c ++
        phase_form 27 ++ (4,2,b)%N :: mid)
      in HParentPre.
    - exact HParentPre.
    - rewrite (app_assoc (schedule_stock pre) avail
        (phase_form 27 ++ (4,2,b)%N :: mid)).
      rewrite EAvail.
      rewrite <- (app_assoc outer0 (rung1 c)
        (phase_form 27 ++ (4,2,b)%N :: mid)).
      reflexivity. }
  assert (HDownLast' : deliveries 1 mid fm tail ft).
  { econstructor; [exact HDownLast|].
    apply deliveries_O. reflexivity. }
  assert (HEmitLast : deliveries
      (N.to_nat (marks 28 - marks 27))
      mid fm tail ft).
  { change (N.to_nat (marks 28 - marks 27))
      with 1%nat. exact HDownLast'. }
  pose proof (transit_delivery
    outer0 c 27 b mid tail fm ft HOuterCols ltac:(lia) Hc Hb HEmitLast)
    as HTransit.
  change (DBu 27) with 0%N in HTransit.
  replace (b+0)%N with b in HTransit by lia.
  pose proof (deliveries_one_trip _ _ _ _ HTransit)
    as HTargetLast.
  destruct oc as [d|].
  - cbn [schedule_release] in EOuter.
    assert (HParentLast : schedule_trips [Some d]
      (outer0 ++ rung1 c ++
         phase_form 27 ++ (4,2,b)%N :: mid) fm
      (outer ++ phase_form 0 ++ (4,2,c)%N :: child) f').
    { eapply schedule_trips_some; [exact HTargetLast|].
      constructor.
      set (finpre := rung1 d ++ outer0 ++
        phase_form 0 ++ [(4,2,c)%N]).
      assert (EL : rung1 d ++
          (outer0 ++ phase_form 0 ++ (4,2,c)%N ::
             rung1 (b-1)%N ++ tail) =
          finpre ++ (rung1 (b-1)%N ++ tail)).
      { unfold finpre. repeat rewrite <- app_assoc. reflexivity. }
      assert (ER : outer ++ phase_form 0 ++
          (4,2,c)%N :: child = finpre ++ child).
      { rewrite EOuter. unfold finpre.
        repeat rewrite <- app_assoc. reflexivity. }
      rewrite EL, ER. exact (sdec_prefix_eq _ _ _ _ _ EChild). }
    exact (schedule_trips_app pre [Some d] _ _ _ _ _ _
      HParentPre' HParentLast).
  - cbn [schedule_release] in EOuter.
    assert (HParentLast : schedule_trips [None]
      (outer0 ++ rung1 c ++
         phase_form 27 ++ (4,2,b)%N :: mid) fm
      (outer ++ phase_form 0 ++ (4,2,c)%N :: child) f').
    { eapply schedule_trips_none; [exact HTargetLast|].
      constructor.
      set (finpre := outer0 ++ phase_form 0 ++ [(4,2,c)%N]).
      assert (EL : outer0 ++ phase_form 0 ++ (4,2,c)%N ::
          rung1 (b-1)%N ++ tail =
          finpre ++ (rung1 (b-1)%N ++ tail)).
      { unfold finpre. repeat rewrite <- app_assoc. reflexivity. }
      assert (ER : outer ++ phase_form 0 ++
          (4,2,c)%N :: child = finpre ++ child).
      { rewrite EOuter. unfold finpre.
        repeat rewrite <- app_assoc. reflexivity. }
      rewrite EL, ER. exact (sdec_prefix_eq _ _ _ _ _ EChild). }
    exact (schedule_trips_app pre [None] _ _ _ _ _ _
      HParentPre' HParentLast).
Qed.
Lemma one_runway_partial_interleaved :
  forall p rem b c prs avail outer post child f f',
  (p < 28)%N -> (rem < 28)%N ->
  (FLOOR <= b)%N ->
  (FLOOR + 3 <= c)%N ->
  delivery_cols avail = true ->
  length prs = N.to_nat (28 + rem - p) ->
  (2 <= length
    (schedule_stock (firstn (N.to_nat (27-p)) prs) ++ avail))%nat ->
  schedule_stock prs ++ avail =
    outer ++ rung1 c ->
  schedule_trips (bulk_schedule p rem [] b) post f child f' ->
  schedule_trips prs
    (avail ++ phase_form p ++
       (4,2,b + DBu p)%N :: post) f
    (outer ++ phase_form rem ++
       (4,2,c - 3 + DBu rem)%N :: child) f'.
Proof.
  intros p rem b c prs avail outer post child f f'
    Hp Hr Hb Hc HAvailCols HLen HReady HStock HChild.
  assert (HLenSplit : length prs =
      (N.to_nat (28-p) + N.to_nat rem)%nat).
  { rewrite HLen. rewrite <- N2Nat.inj_add. f_equal. lia. }
  destruct (split_flight_schedule p prs (N.to_nat rem) Hp HLenSplit)
    as (pre & oc & rest & EPrs & HPre & HRestLen).
  assert (EFirstPre : firstn (N.to_nat (27-p)) prs = pre).
  { rewrite EPrs, <- app_assoc, <- HPre.
    apply firstn_len_app. }
  rewrite EFirstPre in HReady.
  assert (HFlightReady :
      (2 <= length (schedule_stock (pre ++ [oc]) ++ avail))%nat).
  { rewrite schedule_stock_snoc. destruct oc as [d|].
    - repeat rewrite length_app. rewrite length_app in HReady.
      cbn [rung1 length]. lia.
    - exact HReady. }
  rewrite EPrs, schedule_stock_app in HStock.
  replace
    ((schedule_stock rest ++ schedule_stock (pre ++ [oc])) ++ avail)
    with
    (schedule_stock rest ++
      (schedule_stock (pre ++ [oc]) ++ avail))
    in HStock by apply app_assoc.
  destruct (app_suffix_factor bg (schedule_stock rest)
    (schedule_stock (pre ++ [oc]) ++ avail) outer
    (rung1 c) HStock)
    as (mid & EOuter & EFlightStock).
  { cbn [rung1 length]. lia. }
  assert (HMidCols : delivery_cols mid = true).
  { assert (HAll : delivery_cols
        (schedule_stock (pre ++ [oc]) ++ avail) = true).
    { rewrite delivery_cols_app,
        schedule_stock_cols, HAvailCols. reflexivity. }
    rewrite EFlightStock, delivery_cols_app in HAll.
    apply andb_prop in HAll as [HM _]. exact HM. }
  rewrite bulk_schedule_nil in HChild.
  destruct (schedule_trips_app_inv
    (repeat None (schedule_slot_nat p) ++ [Some (b-1)%N])
    (repeat None (N.to_nat (marks rem)))
    post f child f' HChild)
    as (childMid & fm & HChildFlight0 & HChildRest).
  assert (HChildFlight : schedule_trips (bulk_schedule p 0 [] b)
      post f childMid fm).
  { rewrite bulk_schedule_nil.
    cbn [marks N.to_nat repeat]. rewrite app_nil_r.
    exact HChildFlight0. }
  pose proof (one_runway_interleaved p b c (pre ++ [oc]) pre oc
    avail mid post childMid f fm Hp Hb Hc HAvailCols eq_refl HPre
    HReady EFlightStock HChildFlight) as HParentFlight.
  pose proof (schedule_trips_nones
    (N.to_nat (marks rem)) childMid fm child f' HChildRest)
    as HDownRem.
  assert (HDownRem' : deliveries
      (N.to_nat
        (marks (0 + N.of_nat (N.to_nat rem)) -
         marks 0)) childMid fm child f').
  { rewrite N2Nat.id, N.add_0_l.
    change (marks 0) with 0%N. rewrite N.sub_0_r.
    exact HDownRem. }
  pose proof (phase_ticks_delivery
    (N.to_nat rem) 0 (c-3)%N childMid child fm f'
    ltac:(rewrite N2Nat.id; lia)
    ltac:(unfold FLOOR in *; lia) HDownRem') as HPartial.
  rewrite N2Nat.id, N.add_0_l in HPartial.
  change (DBu 0) with 3%N in HPartial.
  replace (c - 3 + 3)%N with c in HPartial by lia.
  pose proof (deliveries_cols _ mid _ _ _ _
    HMidCols HPartial) as HPartialCols.
  pose proof (deliveries_to_schedule_trips rest (N.to_nat rem)
    (mid ++ phase_form 0 ++ (4,2,c)%N :: childMid) fm
    (mid ++ phase_form rem ++
       (4,2,c-3 + DBu rem)%N :: child) f'
    HRestLen HPartialCols) as HParentRest.
  assert (HParentRest' : schedule_trips rest
      (mid ++ phase_form 0 ++ (4,2,c)%N :: childMid) fm
      (outer ++ phase_form rem ++
        (4,2,c-3 + DBu rem)%N :: child) f').
  { replace
      (schedule_stock rest ++
        (mid ++ phase_form rem ++
          (4,2,c-3 + DBu rem)%N :: child))
      with
      (outer ++ phase_form rem ++
        (4,2,c-3 + DBu rem)%N :: child)
      in HParentRest.
    - exact HParentRest.
    - rewrite (app_assoc (schedule_stock rest) mid
        (phase_form rem ++
          (4,2,c-3 + DBu rem)%N :: child)).
      rewrite <- EOuter. reflexivity. }
  rewrite EPrs.
  exact (schedule_trips_app (pre ++ [oc]) rest _ _ _ _ _ _
    HParentFlight HParentRest').
Qed.
Theorem runway_interleaved :
  forall c cs p rem b slot prs avail outer post child f f',
  Forall (fun x => (FLOOR + 3 <= x)%N) (c :: cs) ->
  (p < 28)%N -> (rem < 28)%N ->
  (FLOOR <= b)%N ->
  (slot <= 3)%N ->
  delivery_cols avail = true ->
  length prs = N.to_nat
    (28 * N.of_nat (length (c :: cs)) + rem - p) ->
  schedule_shape slot prs ->
  (2 <= length
    (schedule_stock (firstn (N.to_nat (27-p)) prs) ++ avail))%nat ->
  schedule_stock prs ++ avail =
    outer ++ runway (c :: cs) ->
  schedule_trips (bulk_schedule p rem cs b) post f child f' ->
  schedule_trips prs
    (avail ++ phase_form p ++
       (4,2,b + DBu p)%N :: post) f
    (outer ++ phase_form rem ++
       (4,2,c - 3 + DBu rem)%N :: child) f'.
Proof.
  intros c cs. revert c.
  induction cs as [|d cs IH] using rev_ind;
    intros c p rem b slot prs avail outer post child f f'
      HLevels Hp Hr Hb HSlot HAvailCols HLen HShape HReady HStock HChild.
  - change (length [c]) with 1%nat in HLen.
    replace (28 * N.of_nat 1 + rem - p)%N with (28 + rem - p)%N
      in HLen by lia.
    change (runway [c]) with
      (rung1 c) in HStock.
    exact (one_runway_partial_interleaved
      p rem b c prs avail outer post child f f'
      Hp Hr Hb ltac:(inversion HLevels; assumption)
      HAvailCols HLen HReady HStock HChild).
  - assert (ELevels : c :: cs ++ [d] = (c :: cs) ++ [d])
      by reflexivity.
    rewrite ELevels in HLevels.
    apply Forall_app in HLevels. destruct HLevels as [HOuterLevels HLast].
    inversion HLast as [|d0 nil Hd HNil]; subst d0 nil.
    assert (Hd4 : (4 <= d)%N)
      by (unfold FLOOR in Hd; lia).
    assert (HLenSplit : length prs =
      (N.to_nat (28-p) +
       N.to_nat (28 * N.of_nat (length (c :: cs)) + rem))%nat).
    { rewrite HLen. rewrite <- N2Nat.inj_add. f_equal.
      rewrite ELevels, length_app. cbn [length].
      rewrite Nat2N.inj_succ. lia. }
    destruct (split_flight_schedule p prs
      (N.to_nat (28 * N.of_nat (length (c :: cs)) + rem))
      Hp HLenSplit)
      as (pre & oc & rest & EPrs & HPre & HRestLen).
    assert (EFirstPre : firstn (N.to_nat (27-p)) prs = pre).
    { rewrite EPrs, <- app_assoc, <- HPre.
      apply firstn_len_app. }
    rewrite EFirstPre in HReady.
    assert (HFlightReady :
        (2 <= length (schedule_stock (pre ++ [oc]) ++ avail))%nat).
    { rewrite schedule_stock_snoc. destruct oc as [grant|].
      - repeat rewrite length_app. rewrite length_app in HReady.
        cbn [rung1 length]. lia.
      - exact HReady. }
    assert (ERest : rest = skipn (N.to_nat (28-p)) prs).
    { rewrite EPrs.
      replace (N.to_nat (28-p)) with (length (pre ++ [oc])).
      - rewrite LineageCascade_skipn_len_app. reflexivity.
      - rewrite length_app, HPre. cbn [length].
        rewrite !N2Nat.inj_sub by lia.
        change (N.to_nat 28) with 28%nat.
        change (N.to_nat 27) with 27%nat. lia. }
    assert (HRestSlot :
      (lin_sched_slot_advance slot (N.of_nat (N.to_nat (28-p)))
       <= 3)%N).
    { unfold lin_sched_slot_advance.
      assert (HM : ((3 - slot + N.of_nat (N.to_nat (28-p))) mod 4
                    < 4)%N) by (apply N.mod_lt; lia).
      lia. }
    assert (HRestShape : schedule_shape
      (lin_sched_slot_advance slot (N.of_nat (N.to_nat (28-p))))
      rest).
    { rewrite ERest.
      exact (schedule_shape_skipn (N.to_nat (28-p)) prs slot
        HSlot HShape). }
    rewrite EPrs, schedule_stock_app in HStock.
    replace
      ((schedule_stock rest ++ schedule_stock (pre ++ [oc])) ++ avail)
      with
      (schedule_stock rest ++
        (schedule_stock (pre ++ [oc]) ++ avail))
      in HStock by apply app_assoc.
    rewrite ELevels, runway_app in HStock.
    cbn [runway app] in HStock.
    rewrite app_nil_r in HStock.
    assert (HStock' :
      schedule_stock rest ++
        (schedule_stock (pre ++ [oc]) ++ avail) =
      (outer ++ runway (c :: cs)) ++
        rung1 d).
    { rewrite HStock. apply app_assoc. }
    destruct (app_suffix_factor bg (schedule_stock rest)
      (schedule_stock (pre ++ [oc]) ++ avail)
      (outer ++ runway (c :: cs))
      (rung1 d) HStock')
      as (mid & EOuter & EFlightStock).
    { cbn [rung1 length]. lia. }
    assert (HMidCols : delivery_cols mid = true).
    { assert (HAll : delivery_cols
          (schedule_stock (pre ++ [oc]) ++ avail) = true).
      { rewrite delivery_cols_app,
          schedule_stock_cols, HAvailCols. reflexivity. }
      rewrite EFlightStock, delivery_cols_app in HAll.
      apply andb_prop in HAll as [HM _]. exact HM. }
    rewrite (bulk_schedule_snoc p rem cs b d Hd4) in HChild.
    destruct (schedule_trips_app_inv
      (repeat None (schedule_slot_nat p) ++ [Some (b-1)%N])
      (bulk_schedule 0 rem cs (d-3)%N)
      post f child f' HChild)
      as (childMid & fm & HChildFlight0 & HChildRest).
    assert (HChildFlight : schedule_trips (bulk_schedule p 0 [] b)
        post f childMid fm).
    { rewrite bulk_schedule_nil.
      cbn [marks N.to_nat repeat]. rewrite app_nil_r.
      exact HChildFlight0. }
    pose proof (one_runway_interleaved p b d (pre ++ [oc]) pre oc
      avail mid post childMid f fm Hp Hb Hd HAvailCols eq_refl HPre
      HReady EFlightStock HChildFlight) as HParentFlight.
    assert (HRest27 : (27 <= length rest)%nat).
    { rewrite HRestLen, N2Nat.inj_add, N2Nat.inj_mul, Nat2N.id.
      change (N.to_nat 28) with 28%nat. cbn [length]. lia. }
    pose proof (schedule_stock_firstn_27_ge2 rest
      (lin_sched_slot_advance slot
        (N.of_nat (N.to_nat (28-p))))
      HRestSlot HRestShape HRest27) as HNextStock.
    assert (HNextReady :
      (2 <= length
        (schedule_stock (firstn (N.to_nat (27-0)) rest) ++ mid))%nat).
    { change (N.to_nat (27-0)) with 27%nat.
      rewrite length_app. lia. }
    pose proof (IH c 0%N rem (d-3)%N
      (lin_sched_slot_advance slot
        (N.of_nat (N.to_nat (28-p))))
      rest mid outer childMid child fm f'
      HOuterLevels ltac:(lia) Hr ltac:(unfold FLOOR in *; lia)
      HRestSlot HMidCols ltac:(rewrite N.sub_0_r; exact HRestLen)
      HRestShape HNextReady
      ltac:(symmetry; exact EOuter) HChildRest) as HParentRest.
    change (DBu 0) with 3%N in HParentRest.
    replace (d - 3 + 3)%N with d in HParentRest by lia.
    rewrite EPrs.
    exact (schedule_trips_app (pre ++ [oc]) rest _ _ _ _ _ _
      HParentFlight HParentRest).
Qed.
Definition scheduled_frame (fr : lsc_frame)
    (sg : list seg) (w : word) (f : N)
    (sg' : list seg) (w' : word) (f' : N) : Prop :=
  (forall i, (i <= lsCur fr)%nat ->
    lin_flat sg (firstn i w) =
      lin_flat sg' (firstn i w')) /\
  forall rs base tail,
    schedule_frame_view fr
      (lin_flat sg (skipn (lsCur fr) w))
      rs base tail ->
    exists tail',
      schedule_trips rs tail f tail' f' /\
      lin_flat sg' (skipn (lsCur fr) w') =
        base ++ tail'.
Inductive scheduled_work : list lsc_frame ->
    list seg -> word -> N ->
    list seg -> word -> N -> Prop :=
  | scheduled_work_nil : forall sg w f,
      scheduled_work [] sg w f sg w f
  | scheduled_work_cons : forall fr rest sg w f sg1 w1 f1 sg2 w2 f2,
      scheduled_frame fr sg w f sg1 w1 f1 ->
      scheduled_work rest sg1 w1 f1 sg2 w2 f2 ->
      scheduled_work (fr :: rest) sg w f sg2 w2 f2.
Lemma scheduled_frame_zero : forall cur slot gap sg w f,
  scheduled_frame
    {| lsCur := cur; lsTicks := 0;
       lsSlot := slot; lsGap := gap |}
    sg w f sg w f.
Proof.
  intros cur slot gap sg w f. split; [intros; reflexivity|].
  intros rs base tail
    (HSlot & HLen & HShape & HCols & HLayout & HGap).
  cbn [lsTicks N.to_nat] in HLen. apply length_zero_iff_nil in HLen.
  subst rs. cbn [schedule_stock app] in HLayout.
  rewrite app_nil_r in HLayout.
  exists tail. split; [constructor; reflexivity|].
  exact HLayout.
Qed.
Lemma scheduled_work_zero : forall fr rest sg w f sg' w' f',
  lsTicks fr = 0%N ->
  scheduled_work rest sg w f sg' w' f' ->
  scheduled_work (fr :: rest) sg w f sg' w' f'.
Proof.
  intros [cur tk slot gap] rest sg w f sg' w' f' Htk HWork.
  cbn [lsTicks] in Htk. subst tk.
  econstructor; [apply scheduled_frame_zero|exact HWork].
Qed.
Lemma lin_bulk_child_layout :
  forall sg w j p t w' sg' nh rem emit gb pre post,
  sg_wf sg -> lin_ok sg w = true ->
  (forall s, In s sg -> altb (sBody s) = true) ->
  is_spc (nth O w d0) = false ->
  w = pre ++ phase_form p ++ gb :: post ->
  length pre = j -> post <> [] -> keyi sg gb = None ->
  (p < 28)%N ->
  Nat.eqb (N.to_nat ((p+t)/28)) O = false ->
  lin_bulk sg w j p t = Some (w', sg', nh, rem, emit) ->
  sg_wf sg' ->
  exists PRE POST c cs b,
    lin_flat sg w =
      site
        (PRE ++ runway (c :: cs)) p
        (b + DBu p) POST /\
    lin_flat sg' w' =
      site PRE rem (c - 3 + DBu rem)
        (crossed_post cs b POST) /\
    fmapw sg w O O j =
      length (PRE ++ runway (c :: cs)) /\
    fmapw sg' w' O O nh = length PRE /\
    length (c :: cs) = N.to_nat ((p+t)/28) /\
    Forall (fun x => (FLOOR + 3 <= x)%N) (c :: cs) /\
    POST <> [] /\
    (FLOOR <= b)%N /\
    rem = ((p+t) mod 28)%N /\
    emit = (marks (p+t) - marks p)%N /\
    (rem < 28)%N /\
    lin_flat sg'
      (skipn (nh + phase_len rem)%nat w') =
      [(4,2,c - 3 + DBu rem)%N] ++
      crossed_post cs b POST.
Proof.
  intros sg w j p t w' sg' nh rem emit gb pre post
    HW HOk HAlt H0 HLayout HJ HPost HKey Hp HFull HB HW'.
  destruct (lin_bulk_ledger
    sg w j p t w' sg' nh rem emit gb pre post
    HW HOk HAlt H0 HLayout HJ HPost HKey Hp HFull HB)
    as (PRE & POST & c & cs & b & HIn & HOut & HCoord & HCoord' &
        HLevels & HSafe & HPOST & Hb & HRem & HEmit).
  assert (HRem28 : (rem < 28)%N).
  { rewrite HRem. apply N.mod_lt. lia. }
  destruct (lin_bulk_pieces
    sg w j p t w' sg' nh rem emit gb pre post
    HLayout HJ HPost HKey Hp H0 HFull HB)
    as (left & used & sp & hd & rest0 & cgb & EC & EM & Hpre & Hnh &
        Hgb & Hcgb & Hrem0 & Hemit0 & Hph & Hw').
  assert (Hnhlen : (nh <= length w')%nat).
  { rewrite Hw', !length_app, length_rev. lia. }
  assert (Hfirstnh : firstn nh w' = rev left).
  { rewrite Hw'. rewrite <- Hnh.
    replace (length left) with (length (rev left)) by apply length_rev.
    apply GenerationSound_firstn_pre. }
  destruct (flat_cursor sg' w' nh HW' Hnhlen)
    as (HFlatFirst & _).
  assert (Eleft : lin_flat sg' (rev left) = PRE).
  { rewrite HCoord', HOut in HFlatFirst.
    unfold site in HFlatFirst.
    rewrite firstn_len_app, Hfirstnh in HFlatFirst.
    symmetry. exact HFlatFirst. }
  assert (HphaseLen :
    length (phase_form rem) = phase_len rem)
    by (apply phase_form_len; exact HRem28).
  set (child := (nh + phase_len rem)%nat).
  assert (Hchildlen : (child <= length w')%nat).
  { unfold child. rewrite Hw', !length_app, length_rev, HphaseLen. lia. }
  assert (HfirstChild : firstn child w' =
      rev left ++ phase_form rem).
  { unfold child. rewrite Hw'.
    replace (nh + phase_len rem)%nat with
      (length (rev left) + length (phase_form rem))%nat
      by (rewrite length_rev, Hnh, HphaseLen; reflexivity).
    rewrite firstn_prefix_add.
    rewrite <- app_assoc.
    rewrite firstn_len_app. reflexivity. }
  assert (HMapChild : fmapw sg' w' O O child =
      length (PRE ++ phase_form rem)).
  { rewrite (fmapw_flat_prefix sg' w' child HW' Hchildlen).
    rewrite HfirstChild, lin_flat_app_c, Eleft.
    rewrite (flat_phase_form sg' rem HRem28). reflexivity. }
  destruct (flat_cursor sg' w' child HW' Hchildlen)
    as (_ & HFlatSkip).
  assert (HSuffix : lin_flat sg' (skipn child w') =
      [(4,2,c - 3 + DBu rem)%N] ++
      crossed_post cs b POST).
  { rewrite HMapChild, HOut in HFlatSkip.
    unfold site in HFlatSkip.
    rewrite app_assoc in HFlatSkip.
    rewrite LineageCascade_skipn_len_app in HFlatSkip.
    symmetry. exact HFlatSkip. }
  exists PRE, POST, c, cs, b.
  repeat split; try assumption.
Qed.
Open Scope N_scope.
Open Scope sym.
Opaque LROUND_FUEL LROUND_CHUNKS
       FLAT_ROUND_FUEL CFUEL TRIES.
Lemma sg_wf_cached : forall sg,
  sg_wf sg -> sg_cached sg.
Proof.
  intros sg HW. unfold sg_wf in HW.
  unfold sg_cached. apply forallb_forall.
  intros s Hin. eapply forallb_forall in HW; [|exact Hin].
  exact (proj1 (andb_prop _ _ HW)).
Qed.
Lemma lin_flen_flat_wf : forall sg w,
  sg_wf sg ->
  lin_flen sg w = length (lin_flat sg w).
Proof.
  intros sg w HW. apply flen_flat, sg_wf_cached, HW.
Qed.
Lemma firstn_seek_at : forall w cur cols s,
  seek (skipn cur w) = (cols, s) ->
  firstn (cur + length cols) w = firstn cur w ++ cols.
Proof.
  intros w cur cols s HSeek.
  rewrite firstn_add_skipn.
  pose proof (LineageGuard_seek_split (skipn cur w)) as E.
  rewrite HSeek in E. cbn [fst snd] in E.
  rewrite E, firstn_len_app. reflexivity.
Qed.
Lemma skipn_seek_at : forall w cur cols s,
  seek (skipn cur w) = (cols, s) ->
  skipn (cur + length cols) w = s.
Proof.
  intros w cur cols s HSeek.
  rewrite <- skipn_add.
  pose proof (LineageGuard_seek_split (skipn cur w)) as E.
  rewrite HSeek in E. cbn [fst snd] in E.
  rewrite E, LineageCascade_skipn_len_app. reflexivity.
Qed.
Lemma firstn_app_left : forall (A : Type) (i : nat) (a b : list A),
  (i <= length a)%nat -> firstn i (a ++ b) = firstn i a.
Proof.
  intros A i a b Hi. rewrite firstn_app.
  replace (i - length a)%nat with O by lia.
  cbn [firstn]. rewrite app_nil_r. reflexivity.
Qed.
Lemma altb_delivery_cols : forall w,
  altb w = true ->
  delivery_cols w = true.
Proof.
  fix IH 1. intros w HAlt.
  destruct w as [|l [|s rest]]; [discriminate| |].
  - cbn [altb] in HAlt.
    rewrite (is_lvl_eq l HAlt).
    unfold delivery_cols, is_col, is_cmf.
    cbn [forallb gO gZ gC].
    destruct ((gC l =? 1)%N); reflexivity.
  - cbn [altb] in HAlt.
    repeat rewrite Bool.andb_true_iff in HAlt.
    destruct HAlt as [[HL HS] HR].
    rewrite (is_lvl_eq l HL), (is_spc_eq s HS).
    unfold delivery_cols, is_col, is_cmf.
    cbn [forallb gO gZ gC].
    destruct ((gC l =? 1)%N); exact (IH rest HR).
Qed.
Lemma lin_flat_delivery_cols : forall sg cols,
  delivery_cols cols = true ->
  (forall x, In x sg -> altb (sBody x) = true) ->
  delivery_cols (lin_flat sg cols) = true.
Proof.
  intros sg cols. induction cols as [|g cols IH];
    intros HCols HAlt; [reflexivity|].
  unfold delivery_cols in HCols.
  cbn [forallb] in HCols. apply andb_prop in HCols as [HG HCols].
  cbn [lin_flat]. unfold keyb.
  destruct (keyi sg g) as [se|] eqn:EKey.
  - assert (HFlatCols :
        delivery_cols (sFlat se) = true).
    { apply altb_delivery_cols. unfold sFlat.
      rewrite altb_matb. apply HAlt.
      exact (keyi_some_in _ _ _ EKey). }
    rewrite delivery_cols_app, HFlatCols.
    apply IH; [exact HCols|exact HAlt].
  - unfold delivery_cols. cbn [forallb].
    rewrite HG. exact (IH HCols HAlt).
Qed.
Lemma lin_bulk_prefix_before :
  forall sg w cur j p t w' sg' nh rem emit,
  sg_wf sg -> lin_ok sg w = true ->
  is_spc (nth O w d0) = false ->
  detect_phase w j = Some p ->
  Nat.eqb (N.to_nat ((p+t)/28)) O = false ->
  lin_bulk sg w j p t = Some (w', sg', nh, rem, emit) ->
  (cur <= nh)%nat ->
  forall i, (i <= cur)%nat ->
    lin_flat sg (firstn i w) =
    lin_flat sg' (firstn i w').
Proof.
  intros sg w cur j p t w' sg' nh rem emit
    HW HOk H0 HD HFull HB HCur i Hi.
  destruct (lin_bulk_checks sg w j p t _ HB)
    as (gb & EW & HKey & _ & _ & HEnd).
  destruct (site_layout w j p gb HD EW HEnd)
    as (HLayout & HJ & HPost).
  destruct (detect_phase_form w j p HD) as (Hp & _).
  destruct (lin_bulk_pieces
    sg w j p t w' sg' nh rem emit gb (firstn j w)
    (skipn (S (j + phase_len p)) w)
    HLayout HJ HPost HKey Hp H0 HFull HB)
    as (left & used & sp & hd & rest0 & cgb & EC & EM & Hpre & Hnh &
        Hgb & Hcgb & Hrem & Hemit & Hph & Hw').
  assert (Hsg' : sg' = bump_groups sg used)
    by exact (gclimb_bump_groups _ _ _ _ _ _ _ _ EC).
  assert (EIn : w = rev left ++ rev used ++
      (phase_form p ++ gb ::
        skipn (S (j + phase_len p)) w)).
  { rewrite HLayout at 1. rewrite Hpre, EM.
    repeat rewrite <- app_assoc. reflexivity. }
  assert (EOut : exists out,
      w' = rev left ++ out).
  { exists ((phase_form rem ++
        (gO hd, gZ hd,
          (gC hd + DBu rem) - 3)%N ::
          map (adj4p sg') rest0 ++ [(8,2,1)%N]) ++
        (4,2,(cgb - 1) - DBu p)%N ::
          skipn (S (j + phase_len p)) w).
    exact Hw'. }
  destruct EOut as (out & EOut).
  assert (HiLeft : (i <= length (rev left))%nat)
    by (rewrite length_rev, Hnh; lia).
  rewrite EIn, (firstn_app_left _ i (rev left)
    (rev used ++
      (phase_form p ++ gb ::
        skipn (S (j + phase_len p)) w)) HiLeft).
  rewrite EOut, (firstn_app_left _ i (rev left) out HiLeft).
  rewrite Hsg'. symmetry. apply bump_groups_flat_away.
  intros g s Hg EKey.
  eapply outside_crossed_count0
    with (pre := rev left)
         (post := phase_form p ++ gb ::
           skipn (S (j + phase_len p)) w).
  - rewrite <- EIn. exact HOk.
  - apply in_or_app. left. eapply In_firstn. exact Hg.
  - exact EKey.
Qed.
Lemma lin_bulk_cursor_layout :
  forall sg w cur cols s j p t w' sg' nh rem emit,
  sg_wf sg -> lin_ok sg w = true ->
  (forall x, In x sg -> altb (sBody x) = true) ->
  is_spc (nth O w d0) = false ->
  seek (skipn cur w) = (cols, s) ->
  j = (cur + length cols)%nat ->
  detect_phase w j = Some p ->
  Nat.eqb (N.to_nat ((p+t)/28)) O = false ->
  lin_bulk sg w j p t = Some (w', sg', nh, rem, emit) ->
  sg_wf sg' ->
  exists PRE POST c cs b,
    lin_flat sg (firstn cur w) ++ lin_flat sg cols =
      PRE ++ runway (c :: cs) /\
    lin_flat sg s =
      phase_form p ++
        (4,2,b + DBu p)%N :: POST /\
    lin_flat sg' w' =
      site PRE rem
        (c - 3 + DBu rem)
        (crossed_post cs b POST) /\
    fmapw sg' w' O O nh = length PRE /\
    (nh <= length w')%nat /\
    lin_flat sg'
      (firstn (nh + phase_len rem)%nat w') =
      PRE ++ phase_form rem /\
    lin_flat sg'
      (skipn (nh + phase_len rem)%nat w') =
      [(4,2,c - 3 + DBu rem)%N] ++
        crossed_post cs b POST /\
    length (c :: cs) = N.to_nat ((p+t)/28) /\
    Forall (fun x => (FLOOR + 3 <= x)%N) (c :: cs) /\
    POST <> [] /\ (FLOOR <= b)%N /\
    rem = ((p+t) mod 28)%N /\
    emit = (marks (p+t) - marks p)%N.
Proof.
  intros sg w cur cols s j p t w' sg' nh rem emit
    HW HOk HAlt H0 HSeek Hj HD HFull HB HW'.
  destruct (lin_bulk_checks sg w j p t _ HB)
    as (gb & EW & HKey & HLevel & HFloor & HEnd).
  destruct (site_layout w j p gb HD EW HEnd)
    as (HLayout & HJ & HPost).
  destruct (detect_phase_form w j p HD) as (Hp & _).
  destruct (lin_bulk_ledger
    sg w j p t w' sg' nh rem emit gb (firstn j w)
    (skipn (S (j + phase_len p)) w)
    HW HOk HAlt H0 HLayout HJ HPost HKey Hp HFull HB)
    as (PRE & POST & c & cs & b & EBefore & EAfter & EMap & EMap' &
        HLevels & HSafe & HPOST & Hb & HRem & HEmit).
  assert (HjLen : (j <= length w)%nat).
  { unfold wat in EW.
    assert (Hlt : (j + phase_len p < length w)%nat).
    { apply nth_error_Some. rewrite EW. discriminate. }
    lia. }
  assert (HcurLen : (cur <= length w)%nat) by (subst j; lia).
  destruct (flat_cursor sg w j HW HjLen)
    as (EFirstJ & ESkipJ).
  assert (EPre : lin_flat sg (firstn j w) =
      PRE ++ runway (c :: cs)).
  { rewrite <- EFirstJ, EMap, EBefore.
    unfold site.
    rewrite firstn_len_app. reflexivity. }
  assert (ESite : lin_flat sg (skipn j w) =
      phase_form p ++
        (4,2,b + DBu p)%N :: POST).
  { rewrite <- ESkipJ, EMap, EBefore.
    unfold site.
    rewrite LineageCascade_skipn_len_app. reflexivity. }
  destruct (lin_bulk_pieces
    sg w j p t w' sg' nh rem emit gb (firstn j w)
    (skipn (S (j + phase_len p)) w)
    HLayout HJ HPost HKey Hp H0 HFull HB)
    as (left & used & sp & hd & rest0 & cgb & EC & EM & Hpre & Hnh &
        Hgb & Hcgb & Hrem0 & Hemit0 & Hph & Hw').
  assert (HRem28 : (rem < 28)%N).
  { rewrite HRem. apply N.mod_lt. lia. }
  assert (Hnhlen : (nh <= length w')%nat).
  { rewrite Hw', !length_app, length_rev. lia. }
  assert (Hfirstnh : firstn nh w' = rev left).
  { rewrite Hw'. rewrite <- Hnh.
    replace (length left) with (length (rev left)) by apply length_rev.
    apply firstn_len_app. }
  destruct (flat_cursor sg' w' nh HW' Hnhlen)
    as (HFlatFirst & _).
  assert (Eleft : lin_flat sg' (rev left) = PRE).
  { rewrite EMap', EAfter in HFlatFirst.
    unfold site in HFlatFirst.
    rewrite firstn_len_app, Hfirstnh in HFlatFirst.
    symmetry. exact HFlatFirst. }
  assert (HphaseLen :
    length (phase_form rem) = phase_len rem)
    by (apply phase_form_len; exact HRem28).
  set (child := (nh + phase_len rem)%nat).
  assert (Hchildlen : (child <= length w')%nat).
  { unfold child. rewrite Hw', !length_app, length_rev, HphaseLen. lia. }
  assert (HfirstChild : firstn child w' =
      rev left ++ phase_form rem).
  { unfold child. rewrite Hw'.
    replace (nh + phase_len rem)%nat with
      (length (rev left) + length (phase_form rem))%nat
      by (rewrite length_rev, Hnh, HphaseLen; reflexivity).
    rewrite firstn_prefix_add.
    rewrite <- app_assoc.
    rewrite firstn_len_app. reflexivity. }
  assert (EChildPre : lin_flat sg' (firstn child w') =
      PRE ++ phase_form rem).
  { rewrite HfirstChild, lin_flat_app_c, Eleft.
    rewrite (flat_phase_form sg' rem HRem28). reflexivity. }
  assert (HMapChild : fmapw sg' w' O O child =
      length (PRE ++ phase_form rem)).
  { rewrite (fmapw_flat_prefix sg' w' child HW' Hchildlen).
    rewrite EChildPre. reflexivity. }
  destruct (flat_cursor sg' w' child HW' Hchildlen)
    as (_ & HFlatSkip).
  assert (EChildTail : lin_flat sg' (skipn child w') =
      [(4,2,c - 3 + DBu rem)%N] ++
        crossed_post cs b POST).
  { rewrite HMapChild, EAfter in HFlatSkip.
    unfold site in HFlatSkip.
    rewrite app_assoc in HFlatSkip.
    rewrite LineageCascade_skipn_len_app in HFlatSkip.
    symmetry. exact HFlatSkip. }
  exists PRE, POST, c, cs, b.
  repeat split; try assumption.
  - rewrite <- EPre, Hj, (firstn_seek_at w cur cols s HSeek).
    symmetry. apply lin_flat_app_c.
  - rewrite <- ESite, Hj, (skipn_seek_at w cur cols s HSeek).
    reflexivity.
Qed.
Lemma lcc_le : forall fu sg w k mmax,
  (lcc fu sg w k mmax <= mmax)%nat.
Proof.
  induction fu as [|fu IH]; intros sg w k mmax; [cbn [lcc]; lia|].
  cbn [lcc]. cbv zeta.
  destruct (Nat.eqb mmax O) eqn:EM; [lia|].
  apply PeanoNat.Nat.eqb_neq in EM.
  destruct (Nat.ltb k 1); [lia|].
  destruct (wat w k) as [l|]; [|lia].
  destruct (wat w (k - 1)%nat) as [sp|]; [|lia].
  destruct (negb (is_spc sp)); [lia|].
  destruct (keyi sg l) as [se|].
  - destruct (can_cross se && Nat.leb (segl se) mmax)
      eqn:EC; [|lia].
    apply andb_prop in EC as [_ EC]. apply PeanoNat.Nat.leb_le in EC.
    pose proof (IH sg w (k - 2)%nat (mmax - segl se)%nat). lia.
  - destruct (lit_crossable l); [|lia].
    pose proof (IH sg w (k - 2)%nat (mmax - 1)%nat). lia.
Qed.
Lemma lin_bulk_take_full_le : forall sg w cur tg pk tk,
  (THRESH <= lin_bulk_take sg w cur tg pk tk)%N ->
  (N.to_nat ((pk + lin_bulk_take sg w cur tg pk tk) / 28)
   <= Nat.div2 (fmapw sg w O O tg
                - fmapw sg w O O cur - 2))%nat.
Proof.
  intros sg w cur tg pk tk HT.
  unfold lin_bulk_take in *. cbv zeta in *.
  unfold THRESH in HT.
  set (mgeom := Nat.div2 (fmapw sg w O O tg
                          - fmapw sg w O O cur - 2)) in *.
  set (mneed := N.to_nat ((pk + tk) / 28)) in *.
  set (m := Nat.min mneed
              (lin_count_clean sg w (tg - 1) (Nat.min mgeom mneed)))
    in *.
  destruct (Nat.eqb m O) eqn:EM.
  - pose proof (N.le_min_r tk (27 - pk)) as HR.
    assert (HB : (pk + N.min tk (27 - pk) < 28)%N) by lia.
    rewrite (N.div_small _ _ HB). cbn [N.to_nat]. lia.
  - pose proof (N.le_min_r tk (28 * N.of_nat m - pk)) as HR.
    assert (HB : (pk + N.min tk (28 * N.of_nat m - pk)
                  <= 28 * N.of_nat m)%N) by lia.
    assert (HD : ((pk + N.min tk (28 * N.of_nat m - pk)) / 28
                  <= N.of_nat m)%N).
    { apply (N.Div0.div_le_upper_bound _ 28 (N.of_nat m)); lia. }
    assert (HM : (m <= mgeom)%nat).
    { unfold m, lin_count_clean.
      pose proof (lcc_le (S (tg - 1)) sg w (tg - 1)
                    (Nat.min mgeom mneed)) as HL. lia. }
    assert (HN :
      (N.to_nat ((pk + N.min tk (28 * N.of_nat m - pk)) / 28) <= m)%nat)
      by lia.
    lia.
Qed.
Lemma lin_bulk_take_lands_after_cursor :
  forall sg w cur cols s j p tk take w' sg' nh rem emit,
  sg_wf sg -> lin_ok sg w = true ->
  (forall x, In x sg -> altb (sBody x) = true) ->
  is_spc (nth O w d0) = false ->
  seek (skipn cur w) = (cols, s) ->
  j = (cur + length cols)%nat ->
  detect_phase w j = Some p ->
  take = lin_bulk_take sg w cur j p tk ->
  (THRESH <= take)%N ->
  Nat.eqb (N.to_nat ((p+take)/28)) O = false ->
  lin_bulk sg w j p take = Some (w', sg', nh, rem, emit) ->
  sg_wf sg' ->
  (cur <= nh)%nat.
Proof.
  intros sg w cur cols s j p tk take w' sg' nh rem emit
    HW HOk HAlt H0 HSeek Hj HD HTake HThresh HFull HB HW'.
  destruct (lin_bulk_checks sg w j p take _ HB)
    as (gb & EW & _ & _ & _ & _).
  assert (HjLen : (j <= length w)%nat).
  { unfold wat in EW.
    assert (Hlt : (j + phase_len p < length w)%nat).
    { apply nth_error_Some. rewrite EW. discriminate. }
    lia. }
  assert (HcurLen : (cur <= length w)%nat) by (rewrite Hj in HjLen; lia).
  destruct (lin_bulk_cursor_layout
    sg w cur cols s j p take w' sg' nh rem emit
    HW HOk HAlt H0 HSeek Hj HD HFull HB HW')
    as (PRE & POST & c & cs & b & ECursor & _ & _ & EMap & HnhLen &
        _ & _ & HLevels & _ & _ & _ & _ & _).
  assert (EJ : fmapw sg w O O j =
      (length PRE + 2 * N.to_nat ((p+take)/28))%nat).
  { rewrite (fmapw_flat_prefix sg w j HW HjLen).
    rewrite Hj, (firstn_seek_at w cur cols s HSeek).
    rewrite lin_flat_app_c, ECursor.
    rewrite length_app, length_runway, HLevels.
    reflexivity. }
  assert (ECur : fmapw sg w O O cur =
      length (lin_flat sg (firstn cur w))).
  { apply fmapw_flat_prefix; assumption. }
  pose proof (lin_bulk_take_full_le sg w cur j p tk
    ltac:(rewrite <- HTake; exact HThresh)) as HCap.
  rewrite <- HTake in HCap.
  rewrite EJ, ECur in HCap.
  set (gap := (length PRE + 2 * N.to_nat ((p+take)/28) -
               length (lin_flat sg (firstn cur w)) - 2)%nat).
  fold gap in HCap.
  pose proof (PeanoNat.Nat.div2_odd gap) as HGapParity.
  assert (HFullGap :
      (2 * N.to_nat ((p+take)/28) <= gap)%nat).
  { destruct (Nat.odd gap); cbn in HGapParity; lia. }
  assert (HFlatGap :
      (length (lin_flat sg (firstn cur w)) + 2
       <= length PRE)%nat).
  { destruct (Compare_dec.le_lt_dec
      (length (lin_flat sg (firstn cur w)) + 2)
      (length PRE)) as [Hle|Hbad]; [exact Hle|exfalso].
    assert (HFullPos : (0 < N.to_nat ((p+take)/28))%nat).
    { apply PeanoNat.Nat.eqb_neq in HFull. lia. }
    assert (HGapLt :
      (gap < 2 * N.to_nat ((p+take)/28))%nat).
    { unfold gap. lia. }
    lia. }
  pose proof (lin_bulk_prefix_before sg w nh j p take w' sg' nh rem emit
    HW HOk H0 HD HFull HB (le_n nh) nh (le_n nh)) as HPrefix.
  assert (EOutLen :
      length (lin_flat sg' (firstn nh w')) = length PRE).
  { rewrite <- EMap. symmetry.
    apply fmapw_flat_prefix; assumption. }
  assert (EInLen :
      length (lin_flat sg (firstn nh w)) = length PRE).
  { rewrite HPrefix. exact EOutLen. }
  destruct (PeanoNat.Nat.le_gt_cases cur nh) as [Hle|Hgt]; [exact Hle|].
  assert (HMono :
      (length (lin_flat sg (firstn nh w)) <=
       length (lin_flat sg (firstn cur w)))%nat).
  { set (d := (cur - nh)%nat).
    assert (Ecur : cur = (nh + d)%nat) by (unfold d; lia).
    rewrite Ecur, firstn_add_skipn,
      lin_flat_app_c, length_app. lia. }
  lia.
Qed.
Definition scheduled_transition (fr : lsc_frame) (take : N)
    (sg : list seg) (w : word) (f : N)
    (sg' : list seg) (w' : word) (f' : N) : Prop :=
  (forall i, (i <= lsCur fr)%nat ->
    lin_flat sg (firstn i w) =
      lin_flat sg' (firstn i w')) /\
  forall prs base tail,
    schedule_frame_view fr
      (lin_flat sg (skipn (lsCur fr) w))
      prs base tail ->
    exists used rest tail',
      prs = used ++ rest /\
      length used = N.to_nat take /\
      schedule_trips used tail f tail' f' /\
      schedule_frame_view
        (lin_sched_advance fr take)
        (lin_flat sg'
          (skipn (lsCur fr) w'))
        rest base tail'.
Lemma scheduled_transition_frame :
  forall fr take sg w f sg1 w1 f1 sg2 w2 f2,
  scheduled_transition fr take sg w f sg1 w1 f1 ->
  scheduled_frame (lin_sched_advance fr take)
    sg1 w1 f1 sg2 w2 f2 ->
  scheduled_frame fr sg w f sg2 w2 f2.
Proof.
  intros fr take sg w f sg1 w1 f1 sg2 w2 f2
    (HP & HStep) (HP2 & HFrame). split.
  - intros i Hi. rewrite (HP i Hi), (HP2 i Hi). reflexivity.
  - intros prs base tail HView.
    destruct (HStep prs base tail HView)
      as (used & rest & tail1 & EPrs & HUsed & HTrips & HView1).
    destruct (HFrame rest base tail1 HView1)
      as (tail2 & HTrips2 & HOut).
    exists tail2. split; [|exact HOut].
    rewrite EPrs. eapply schedule_trips_app; eassumption.
Qed.
Lemma scheduled_frame_output :
  forall fr sg w f sg' w' f' rs base tail,
  scheduled_frame fr sg w f sg' w' f' ->
  schedule_frame_view fr
    (lin_flat sg (skipn (lsCur fr) w))
    rs base tail ->
  exists tail',
    schedule_trips rs tail f tail' f' /\
    lin_flat sg' w' =
      lin_flat sg (firstn (lsCur fr) w) ++
        base ++ tail'.
Proof.
  intros fr sg w f sg' w' f' rs base tail
    (HP & HFrame) HView.
  destruct (HFrame rs base tail HView) as (tail' & HTrips & HOut).
  exists tail'. split; [exact HTrips|].
  rewrite (flat_firstn_skipn sg' w' (lsCur fr)).
  rewrite HOut, <- (HP (lsCur fr) (le_n _)).
  repeat rewrite <- app_assoc. reflexivity.
Qed.
Lemma lin_bulk_scheduled_transition :
  forall fr sg w f cols s j p take w' sg' nh rem emit sg1 w1 f1,
  sg_wf sg -> lin_ok sg w = true ->
  (forall x, In x sg -> altb (sBody x) = true) ->
  is_spc (nth O w d0) = false ->
  seek (skipn (lsCur fr) w) = (cols, s) ->
  j = (lsCur fr + length cols)%nat ->
  detect_phase w j = Some p ->
  Nat.eqb (N.to_nat ((p+take)/28)) O = false ->
  lin_bulk sg w j p take = Some (w', sg', nh, rem, emit) ->
  sg_wf sg' ->
  (take <= lsTicks fr)%N ->
  lin_sched_bulk_safe fr (lin_flen sg cols) p take = true ->
  (lsCur fr <= nh)%nat ->
  scheduled_frame
    (lin_sched_child nh rem emit p take)
    sg' w' f sg1 w1 f1 ->
  scheduled_transition fr take sg w f sg1 w1 f1.
Proof.
  intros fr sg w f cols s j p take w' sg' nh rem emit sg1 w1 f1
    HW HOk HAlt H0 HSeek Hj HD HFull HB HW' HTake HSafe HCur HChild.
  destruct (detect_phase_form w j p HD) as (Hp & _).
  assert (HFullNat : N.to_nat ((p+take)/28) <> 0%nat)
    by (apply PeanoNat.Nat.eqb_neq; exact HFull).
  assert (HFullN : ((p+take)/28 <> 0)%N).
  { intro E. apply HFullNat. rewrite E. reflexivity. }
  assert (EFullN : (((p+take)/28 =? 0)%N = false))
    by (apply N.eqb_neq; exact HFullN).
  destruct (lin_bulk_cursor_layout
    sg w (lsCur fr) cols s j p take w' sg' nh rem emit
    HW HOk HAlt H0 HSeek Hj HD HFull HB HW')
    as (PRE & POST & c & cs & b & EPre & ESite & EBulk & EMap &
        HnhLen & EChildPre & EChildTail & HLevels & HLevelsSafe & HPOST & Hb &
        HRem & HEmit).
  destruct HChild as (HChildPrefix & HChildFrame).
  assert (HPrefix : forall i, (i <= lsCur fr)%nat ->
      lin_flat sg (firstn i w) =
      lin_flat sg1 (firstn i w1)).
  { intros i Hi. transitivity (lin_flat sg' (firstn i w')).
    - exact (lin_bulk_prefix_before
        sg w (lsCur fr) j p take w' sg' nh rem emit
        HW HOk H0 HD HFull HB HCur i Hi).
    - apply HChildPrefix. cbn [lin_sched_child lsCur]. lia. }
  split; [exact HPrefix|].
  intros prs base tail HView.
  destruct HView as (HSlot & HLen & HShape & HBaseCols & HLayout & HGap).
  pose proof (seek_split (skipn (lsCur fr) w)
    cols s HSeek) as HSeekSplit.
  destruct HSeekSplit as (ESeekWord & HCols).
  assert (EFlatSuffix :
      lin_flat sg (skipn (lsCur fr) w) =
      lin_flat sg cols ++ lin_flat sg s).
  { rewrite ESeekWord. apply lin_flat_app_c. }
  assert (EFrameSite :
      (base ++ schedule_stock prs) ++ tail =
      lin_flat sg cols ++ lin_flat sg s).
  { rewrite <- HLayout. exact EFlatSuffix. }
  assert (HBoundary :
      (lsGap fr <= length (lin_flat sg cols))%nat).
  { unfold lin_sched_bulk_safe in HSafe. cbv zeta in HSafe.
    rewrite EFullN in HSafe. apply andb_prop in HSafe as [HBnd _].
    apply PeanoNat.Nat.leb_le in HBnd.
    rewrite <- (lin_flen_flat_wf sg cols HW). exact HBnd. }
  assert (HBaseLen :
      (length (base ++ schedule_stock prs) <=
       length (lin_flat sg cols))%nat)
    by (rewrite HGap; exact HBoundary).
  destruct (app_prefix_factor bg
    (base ++ schedule_stock prs) tail
    (lin_flat sg cols) (lin_flat sg s)
    EFrameSite HBaseLen) as (avail & ECols & ETail).
  assert (HFlatCols : delivery_cols
      (lin_flat sg cols) = true)
    by (apply lin_flat_delivery_cols; assumption).
  assert (HAvailCols : delivery_cols avail = true).
  { rewrite ECols, !delivery_cols_app,
      HBaseCols, schedule_stock_cols in HFlatCols.
    exact HFlatCols. }
  assert (ETailSite : tail =
      avail ++ phase_form p ++
        (4,2,b + DBu p)%N :: POST).
  { rewrite ETail, ESite. repeat rewrite <- app_assoc. reflexivity. }
  set (used := firstn (N.to_nat take) prs).
  set (rest := skipn (N.to_nat take) prs).
  assert (HTakeNat : (N.to_nat take <= length prs)%nat).
  { rewrite HLen. apply PeanoNat.Nat.compare_le_iff.
    rewrite <- N2Nat.inj_compare. apply N.compare_le_iff. exact HTake. }
  assert (EPrs : prs = used ++ rest).
  { unfold used, rest. symmetry. apply firstn_skipn. }
  assert (HUsedLen : length used = N.to_nat take).
  { unfold used. rewrite length_firstn, PeanoNat.Nat.min_l by exact HTakeNat.
    reflexivity. }
  assert (HUsedShape : schedule_shape (lsSlot fr) used).
  { unfold used. exact (schedule_shape_firstn
      _ _ _ HShape). }
  assert (HColFlat : lin_flen sg cols =
      (lsGap fr + length avail)%nat).
  { rewrite lin_flen_flat_wf by exact HW.
    rewrite ECols, length_app, HGap. reflexivity. }
  pose proof (schedule_bulk_ready
    fr prs p take avail (lin_flen sg cols)
    HSlot HLen HShape Hp HFullN HTake HColFlat HSafe) as HReady.
  fold used in HReady.
  pose proof (schedule_bulk_stock_enough
    fr prs p take avail (lin_flen sg cols)
    HSlot HLen HShape Hp HFullN HTake HColFlat HSafe) as HEnough.
  fold used in HEnough.
  assert (EResource :
      (lin_flat sg (firstn (lsCur fr) w) ++
         base ++ schedule_stock rest) ++
        (schedule_stock used ++ avail) =
      PRE ++ runway (c :: cs)).
  { rewrite ECols, EPrs, schedule_stock_app in EPre.
    rewrite <- EPre. repeat rewrite <- app_assoc. reflexivity. }
  assert (HRunwayLen :
      length (runway (c :: cs)) =
        (2 * N.to_nat ((p+take)/28))%nat).
  { rewrite length_runway, HLevels. reflexivity. }
  destruct (app_suffix_factor bg
    (lin_flat sg (firstn (lsCur fr) w) ++
       base ++ schedule_stock rest)
    (schedule_stock used ++ avail)
    PRE (runway (c :: cs))
    EResource ltac:(rewrite HRunwayLen; exact HEnough))
    as (outer & EPreOuter & EStockOuter).
  assert (HRem28 : (rem < 28)%N).
  { rewrite HRem. apply N.mod_lt. lia. }
  set (crs := bulk_schedule p rem cs b).
  set (cbase := [(4,2,c - 3 + DBu rem)%N]).
  assert (HChildView : schedule_frame_view
      (lin_sched_child nh rem emit p take)
      (lin_flat sg'
        (skipn (nh + phase_len rem)%nat w'))
      crs cbase POST).
  { unfold schedule_frame_view, lin_sched_child.
    cbv beta zeta. cbn [lsSlot lsTicks lsGap].
    repeat split.
    - unfold lin_sched_slot. lia.
    - unfold crs.
      rewrite (bulk_schedule_length p rem cs b Hp HRem28).
      assert (HQ : N.of_nat (S (length cs)) = ((p+take)/28)%N).
      { cbn [length] in HLevels. rewrite HLevels, N2Nat.id. reflexivity. }
      pose proof (N.div_mod' (p+take) 28) as HDiv.
      assert (ESpan :
        (28 * N.of_nat (S (length cs)) + rem = p+take)%N) by lia.
      rewrite ESpan, <- HEmit. reflexivity.
    - unfold crs. exact (bulk_schedule_shape
        p rem cs b Hp HRem28).
    - unfold cbase, delivery_cols.
      unfold is_col, is_cmf.
      cbn [forallb gO gZ gC].
      destruct ((c - 3 + DBu rem =? 1)%N); reflexivity.
    - unfold cbase, crs.
      rewrite bulk_schedule_stock, EChildTail.
      unfold crossed_post.
      rewrite app_nil_r. repeat rewrite <- app_assoc. reflexivity.
    - unfold cbase, crs. rewrite bulk_schedule_stock.
      unfold crossed_post.
      rewrite !length_app, length_runway, map_length.
      cbn [rung1 length].
      change (S (length cs) = N.to_nat ((p+take)/28)) in HLevels.
      lia. }
  destruct (HChildFrame crs cbase POST HChildView)
    as (child & HChildTrips & HChildOut).
  cbn [lin_sched_child lsCur] in HChildOut.
  assert (EChildFull : lin_flat sg1 w1 =
      PRE ++ phase_form rem ++
        (4,2,c - 3 + DBu rem)%N :: child).
  { rewrite (flat_firstn_skipn sg1 w1
      (nh + phase_len rem)%nat).
    rewrite <- (HChildPrefix (nh + phase_len rem)%nat (le_n _)).
    rewrite EChildPre, HChildOut. unfold cbase.
    repeat rewrite <- app_assoc. reflexivity. }
  assert (HTakeSpan : take =
      (28 * N.of_nat (length (c :: cs)) + rem - p)%N).
  { pose proof (N.div_mod' (p+take) 28) as HDiv.
    assert (HQ : N.of_nat (length (c :: cs)) = ((p+take)/28)%N)
      by (rewrite HLevels, N2Nat.id; reflexivity).
    rewrite HQ, HRem. lia. }
  assert (HUsedSpan : length used = N.to_nat
      (28 * N.of_nat (length (c :: cs)) + rem - p)).
  { rewrite HUsedLen, HTakeSpan. reflexivity. }
  unfold crs in HChildTrips.
  pose proof (runway_interleaved
    c cs p rem b (lsSlot fr) used avail outer POST child f f1
    HLevelsSafe Hp HRem28 Hb HSlot HAvailCols HUsedSpan HUsedShape
    HReady EStockOuter HChildTrips) as HParentTrips0.
  assert (HParentTrips : schedule_trips used tail f
      (outer ++ phase_form rem ++
        (4,2,c - 3 + DBu rem)%N :: child) f1).
  { rewrite ETailSite. exact HParentTrips0. }
  set (tail' := outer ++ phase_form rem ++
    (4,2,c - 3 + DBu rem)%N :: child).
  assert (EFinalFull : lin_flat sg1 w1 =
      lin_flat sg (firstn (lsCur fr) w) ++
        (base ++ schedule_stock rest) ++ tail').
  { unfold tail'. rewrite EChildFull, EPreOuter.
    repeat rewrite <- app_assoc. reflexivity. }
  assert (EFinalSuffix :
      lin_flat sg1 (skipn (lsCur fr) w1) =
        (base ++ schedule_stock rest) ++ tail').
  { pose proof (flat_firstn_skipn
      sg1 w1 (lsCur fr)) as EDec.
    rewrite <- (HPrefix (lsCur fr) (le_n _)) in EDec.
    rewrite EFinalFull in EDec. apply app_inv_head in EDec.
    symmetry. exact EDec. }
  exists used, rest, tail'.
  split; [exact EPrs|]. split; [exact HUsedLen|].
  split; [exact HParentTrips|].
  unfold schedule_frame_view, lin_sched_advance.
  cbn [lsSlot lsTicks lsGap].
  repeat split.
  - exact (sched_slot_advance_le3
      (lsSlot fr) take HSlot).
  - unfold rest. exact (schedule_ticks_skip
      (lsTicks fr) take prs HLen HTake).
  - change (schedule_shape
      (lin_sched_slot_advance (lsSlot fr) take) rest).
    unfold rest.
    pose proof (schedule_shape_skipn
      (N.to_nat take) prs (lsSlot fr) HSlot HShape) as HRestShape.
    rewrite N2Nat.id in HRestShape. exact HRestShape.
  - exact HBaseCols.
  - exact EFinalSuffix.
  - unfold rest.
    pose proof (schedule_stock_skip_length
      (N.to_nat take) prs (lsSlot fr)
      HTakeNat HSlot HShape) as HRestStock.
    rewrite N2Nat.id in HRestStock.
    pose proof (schedule_stock_first_skip
      (N.to_nat take) prs) as EStockSplit.
    apply (f_equal (@length bg)) in EStockSplit.
    rewrite length_app in EStockSplit.
    fold used rest in EStockSplit.
    pose proof (schedule_stock_firstn_length
      (N.to_nat take) prs (lsSlot fr)
      HTakeNat HSlot HShape) as HUsedStock.
    fold used in HUsedStock. rewrite N2Nat.id in HUsedStock.
    rewrite length_app, HRestStock. rewrite length_app in HGap. lia.
Qed.
Lemma lin_bulk_partial_scheduled_transition :
  forall fr sg w f cols s j p take w' sg' nh rem emit sg1 w1 f1,
  sg_wf sg ->
  seek (skipn (lsCur fr) w) = (cols, s) ->
  j = (lsCur fr + length cols)%nat ->
  detect_phase w j = Some p ->
  Nat.eqb (N.to_nat ((p+take)/28)) O = true ->
  lin_bulk sg w j p take = Some (w', sg', nh, rem, emit) ->
  (take <= lsTicks fr)%N ->
  scheduled_frame
    (lin_sched_child nh rem emit p take)
    sg' w' f sg1 w1 f1 ->
  scheduled_transition fr take sg w f sg1 w1 f1.
Proof.
  intros fr sg w f cols s j p take w' sg' nh rem emit sg1 w1 f1
    HW HSeek Hj HD HFull HB HTake HChild.
  pose proof (bulk_full_zero_lt28 p take HFull) as Hpt.
  destruct (detect_phase_form w j p HD) as (Hp & _).
  destruct (lin_bulk_checks sg w j p take _ HB)
    as (gb & EW & HKey & HLevel & HFloor & HEnd).
  destruct (site_layout w j p gb HD EW HEnd)
    as (HLayoutRaw & HJ & HPost).
  destruct (lvl_big_shape gb HLevel) as (c & Hgb).
  rewrite Hgb in HFloor. cbn [gC] in HFloor.
  destruct (lin_bulk_partial_out
    sg w j p take w' sg' nh rem emit gb HFull HB EW)
    as (Esg & Enh & Erem & Eemit & Ew').
  subst sg'. subst nh. subst rem. subst emit.
  assert (HMod : ((p+take) mod 28 = p+take)%N)
    by (apply N.mod_small; exact Hpt).
  rewrite HMod in Ew', HChild.
  set (PRE := firstn j w) in *.
  set (POST := skipn (S (j + phase_len p)) w) in *.
  assert (Hplen :
    length (phase_form p) = phase_len p)
    by (apply phase_form_len; exact Hp).
  assert (Hrlen :
    length (phase_form (p+take)) =
      phase_len (p+take))
    by (apply phase_form_len; exact Hpt).
  assert (EW2 : w' = PRE ++ phase_form (p+take) ++
      (4,2,(c + DBu (p+take)) - DBu p)%N :: POST).
  { rewrite Ew'. rewrite HLayoutRaw at 1. rewrite Hgb.
    rewrite <- HJ, <- Hplen. apply subst_site. }
  assert (ESkip : s = phase_form p ++ (4,2,c)%N :: POST).
  { rewrite <- (skipn_seek_at w (lsCur fr) cols s HSeek), <- Hj.
    rewrite HLayoutRaw, Hgb.
    rewrite <- HJ. apply LineageCascade_skipn_len_app. }
  assert (ESite : lin_flat sg s =
      phase_form p ++ (4,2,c)%N :: lin_flat sg POST).
  { rewrite ESkip, lin_flat_app_c,
      (flat_phase_form sg p Hp).
    cbn [lin_flat]. unfold keyb, keyi,
      phshape. cbn [gO gZ]. reflexivity. }
  destruct HChild as (HChildPrefix & HChildFrame).
  assert (HRawPrefix : forall i, (i <= lsCur fr)%nat ->
      firstn i w = firstn i w').
  { intros i Hi.
    assert (HiJ : (i <= length PRE)%nat)
      by (rewrite HJ; subst j; lia).
    rewrite HLayoutRaw at 1.
    rewrite (firstn_app_left _ i PRE
      (phase_form p ++ gb :: POST) HiJ).
    rewrite EW2, (firstn_app_left _ i PRE
      (phase_form (p+take) ++
        (4,2,c + DBu (p+take) - DBu p)%N :: POST)
      HiJ). reflexivity. }
  assert (HPrefix : forall i, (i <= lsCur fr)%nat ->
      lin_flat sg (firstn i w) =
      lin_flat sg1 (firstn i w1)).
  { intros i Hi. rewrite (HRawPrefix i Hi).
    apply HChildPrefix.
    cbn [lin_sched_child lsCur]. subst j. lia. }
  split; [exact HPrefix|].
  intros prs base tail HView.
  destruct HView as (HSlot & HLen & HShape & HBaseCols & HFrame & HGap).
  assert (HMidCols : delivery_cols
      (base ++ schedule_stock prs) = true).
  { rewrite delivery_cols_app, HBaseCols,
      schedule_stock_cols. reflexivity. }
  assert (EFlatSeek :
      seek ((base ++ schedule_stock prs) ++ tail) =
      (lin_flat sg cols, lin_flat sg s)).
  { rewrite <- HFrame, seek_flat by exact HW.
    rewrite HSeek. reflexivity. }
  rewrite (seek_app_delivery_cols
    (base ++ schedule_stock prs) tail HMidCols)
    in EFlatSeek.
  destruct (seek tail) as [avail tail0] eqn:ETailSeek.
  cbn [fst snd] in EFlatSeek.
  pose proof (f_equal fst EFlatSeek) as ECols0.
  pose proof (f_equal snd EFlatSeek) as ETail0.
  cbn [fst snd] in ECols0, ETail0.
  assert (ECols : lin_flat sg cols =
      (base ++ schedule_stock prs) ++ avail)
    by (symmetry; exact ECols0).
  destruct (seek_split tail avail tail0 ETailSeek)
    as (ETailSplit & HAvailCols).
  assert (ETail : tail = avail ++ lin_flat sg s).
  { rewrite ETailSplit, ETail0. reflexivity. }
  assert (ETailSite : tail = avail ++ phase_form p ++
      (4,2,c)%N :: lin_flat sg POST).
  { rewrite ETail, ESite. repeat rewrite <- app_assoc. reflexivity. }
  set (used := firstn (N.to_nat take) prs).
  set (rest := skipn (N.to_nat take) prs).
  assert (HTakeNat : (N.to_nat take <= length prs)%nat).
  { rewrite HLen. apply PeanoNat.Nat.compare_le_iff.
    rewrite <- N2Nat.inj_compare. apply N.compare_le_iff. exact HTake. }
  assert (EPrs : prs = used ++ rest).
  { unfold used, rest. symmetry. apply firstn_skipn. }
  assert (HUsedLen : length used = N.to_nat take).
  { unfold used. rewrite length_firstn, PeanoNat.Nat.min_l by exact HTakeNat.
    reflexivity. }
  set (crs := partial_schedule p take).
  set (cbase :=
    [(4,2,(c + DBu (p+take)) - DBu p)%N]).
  assert (EChildSuffix : lin_flat sg
      (skipn (j + phase_len (p+take))%nat w') =
      cbase ++ lin_flat sg POST).
  { rewrite EW2.
    replace (j + phase_len (p+take))%nat with
      (length (PRE ++ phase_form (p+take)))
      by (rewrite length_app, HJ, Hrlen; reflexivity).
    rewrite app_assoc, LineageCascade_skipn_len_app.
    unfold cbase. cbn [lin_flat].
    unfold keyb, keyi, phshape.
    cbn [gO gZ]. reflexivity. }
  assert (HChildView : schedule_frame_view
      (lin_sched_child j (p+take)
        (marks (p+take) - marks p) p take)
      (lin_flat sg
        (skipn (j + phase_len (p+take))%nat w'))
      crs cbase (lin_flat sg POST)).
  { unfold schedule_frame_view, lin_sched_child.
    cbv beta zeta. cbn [lsSlot lsTicks lsGap].
    repeat split.
    - unfold lin_sched_slot.
      pose proof (marks_le3 p Hp). lia.
    - unfold crs, partial_schedule. rewrite repeat_length.
      reflexivity.
    - unfold crs. exact (partial_schedule_shape p take Hpt).
    - unfold cbase, delivery_cols.
      unfold is_col, is_cmf.
      cbn [forallb gO gZ gC].
      destruct (((c + DBu (p+take)) -
        DBu p =? 1)%N); reflexivity.
    - rewrite EChildSuffix. unfold cbase, crs.
      rewrite partial_schedule_stock. cbn [app]. reflexivity.
    - unfold cbase, crs. rewrite partial_schedule_stock.
      apply PeanoNat.Nat.eqb_eq in HFull.
      cbn [length app]. rewrite HFull. reflexivity. }
  destruct (HChildFrame crs cbase (lin_flat sg POST) HChildView)
    as (child & HChildTrips & HChildOut).
  cbn [lin_sched_child lsCur] in HChildOut.
  assert (EChildPre : lin_flat sg
      (firstn (j + phase_len (p+take))%nat w') =
      lin_flat sg PRE ++ phase_form (p+take)).
  { rewrite EW2.
    replace (j + phase_len (p+take))%nat with
      (length PRE + length (phase_form (p+take)))%nat
      by (rewrite HJ, Hrlen; reflexivity).
    rewrite firstn_prefix_add, lin_flat_app_c.
    rewrite firstn_len_app.
    rewrite (flat_phase_form sg (p+take) Hpt). reflexivity. }
  assert (EChildFull : lin_flat sg1 w1 =
      lin_flat sg PRE ++ phase_form (p+take) ++
        (4,2,c + DBu (p+take) - DBu p)%N :: child).
  { rewrite (flat_firstn_skipn sg1 w1
      (j + phase_len (p+take))%nat).
    rewrite <- (HChildPrefix
      (j + phase_len (p+take))%nat (le_n _)).
    rewrite EChildPre, HChildOut. unfold cbase.
    repeat rewrite <- app_assoc. reflexivity. }
  unfold crs in HChildTrips.
  pose proof (partial_interleaved
    p take (c - DBu p)%N used avail
    (lin_flat sg POST) child f f1 Hpt
    ltac:(unfold FLOOR in *; lia)
    HAvailCols HUsedLen HChildTrips) as HParentTrips0.
  replace (c - DBu p + DBu p)%N with c
    in HParentTrips0 by lia.
  replace (c - DBu p + DBu (p+take))%N with
    (c + DBu (p+take) - DBu p)%N
    in HParentTrips0 by lia.
  assert (HParentTrips : schedule_trips used tail f
      (schedule_stock used ++ avail ++
        phase_form (p+take) ++
        (4,2,c + DBu (p+take) - DBu p)%N :: child) f1).
  { rewrite ETailSite. exact HParentTrips0. }
  set (tail' := schedule_stock used ++ avail ++
    phase_form (p+take) ++
    (4,2,c + DBu (p+take) - DBu p)%N :: child).
  assert (EPreFlat : lin_flat sg PRE =
      lin_flat sg (firstn (lsCur fr) w) ++
        lin_flat sg cols).
  { unfold PRE. rewrite Hj, (firstn_seek_at w
      (lsCur fr) cols s HSeek).
    apply lin_flat_app_c. }
  assert (EFinalFull : lin_flat sg1 w1 =
      lin_flat sg (firstn (lsCur fr) w) ++
        (base ++ schedule_stock rest) ++ tail').
  { unfold tail'. rewrite EChildFull, EPreFlat, ECols, EPrs,
      schedule_stock_app.
    repeat rewrite <- app_assoc. reflexivity. }
  assert (EFinalSuffix : lin_flat sg1
      (skipn (lsCur fr) w1) =
      (base ++ schedule_stock rest) ++ tail').
  { pose proof (flat_firstn_skipn
      sg1 w1 (lsCur fr)) as EDec.
    rewrite <- (HPrefix (lsCur fr) (le_n _)) in EDec.
    rewrite EFinalFull in EDec. apply app_inv_head in EDec.
    symmetry. exact EDec. }
  exists used, rest, tail'.
  split; [exact EPrs|]. split; [exact HUsedLen|].
  split; [exact HParentTrips|].
  unfold schedule_frame_view, lin_sched_advance.
  cbn [lsSlot lsTicks lsGap].
  repeat split.
  - exact (sched_slot_advance_le3
      (lsSlot fr) take HSlot).
  - unfold rest. exact (schedule_ticks_skip
      (lsTicks fr) take prs HLen HTake).
  - change (schedule_shape
      (lin_sched_slot_advance (lsSlot fr) take) rest).
    unfold rest.
    pose proof (schedule_shape_skipn
      (N.to_nat take) prs (lsSlot fr) HSlot HShape) as HRestShape.
    rewrite N2Nat.id in HRestShape. exact HRestShape.
  - exact HBaseCols.
  - exact EFinalSuffix.
  - unfold rest.
    pose proof (schedule_stock_skip_length
      (N.to_nat take) prs (lsSlot fr)
      HTakeNat HSlot HShape) as HRestStock.
    rewrite N2Nat.id in HRestStock.
    pose proof (schedule_stock_first_skip
      (N.to_nat take) prs) as EStockSplit.
    apply (f_equal (@length bg)) in EStockSplit.
    rewrite length_app in EStockSplit. fold used rest in EStockSplit.
    pose proof (schedule_stock_firstn_length
      (N.to_nat take) prs (lsSlot fr)
      HTakeNat HSlot HShape) as HUsedStock.
    fold used in HUsedStock. rewrite N2Nat.id in HUsedStock.
    rewrite length_app, HRestStock. rewrite length_app in HGap. lia.
Qed.
Lemma lin_direct_scheduled_transition :
  forall fr sg w f cols s renewed sfx f2 w2,
  sg_wf sg -> keys_big sg ->
  sg_live sg ->
  (lsCur fr <= length w)%nat ->
  lsTicks fr <> 0%N ->
  seek (skipn (lsCur fr) w) = (cols, s) ->
  s <> [] ->
  (forall t', s = (4%N,3%N,1%N) :: t' ->
     ph_notlast sg cols) ->
  nbrs1z sg s ->
  (forall g t, s = g :: t -> ph sg g = false) ->
  lin_dtick_after_seek cols s f = Some (renewed, sfx, f2) ->
  (renewed = true ->
    (lsGap fr + 2 <= lin_flen sg cols)%nat) ->
  (if Nat.eqb (lsCur fr) O then Some sfx
   else lin_join_safe sg
          (firstn (lsCur fr) w) sfx) = Some w2 ->
  scheduled_transition fr 1 sg w f sg w2 f2.
Proof.
  intros fr sg w f cols s renewed sfx f2 w2
    HW HK HL HCur HTicks HSeek Hs HP HN HHead HRun HRenew HJoin.
  assert (EW2 : w2 = firstn (lsCur fr) w ++ sfx).
  { destruct (Nat.eqb (lsCur fr) O) eqn:ECur.
    - apply PeanoNat.Nat.eqb_eq in ECur. injection HJoin as <-.
      rewrite ECur. reflexivity.
    - exact (lin_join_safe_some _ _ _ _ HJoin). }
  assert (HPrefix : forall i, (i <= lsCur fr)%nat ->
      lin_flat sg (firstn i w) =
      lin_flat sg (firstn i w2)).
  { intros i Hi. rewrite EW2.
    assert (HCurFirst : length (firstn (lsCur fr) w) =
        lsCur fr) by (rewrite length_firstn; lia).
    rewrite (firstn_app_left _ i (firstn (lsCur fr) w)
      sfx ltac:(rewrite HCurFirst; exact Hi)).
    rewrite firstn_firstn, PeanoNat.Nat.min_l by exact Hi. reflexivity. }
  split; [exact HPrefix|].
  intros prs base tail HView.
  destruct prs as [|oc rs].
  { cbn [length] in HView. destruct HView as [_ [HLen _]].
    exfalso. apply HTicks. apply (f_equal N.of_nat) in HLen.
    rewrite N2Nat.id in HLen. symmetry. exact HLen. }
  destruct HView as (HSlot & HLen & HShape & HBaseCols & HFrame & HGap).
  assert (HMidCols : delivery_cols
      (base ++ schedule_stock (oc :: rs)) = true).
  { rewrite delivery_cols_app, HBaseCols,
      schedule_stock_cols. reflexivity. }
  assert (EFlatSeek :
      seek ((base ++ schedule_stock (oc :: rs)) ++ tail)
        = (lin_flat sg cols, lin_flat sg s)).
  { rewrite <- HFrame, seek_flat by exact HW.
    rewrite HSeek. reflexivity. }
  rewrite (seek_app_delivery_cols
    (base ++ schedule_stock (oc :: rs)) tail HMidCols)
    in EFlatSeek.
  destruct (seek tail) as [avail tail0] eqn:ETailSeek.
  cbn [fst snd] in EFlatSeek.
  pose proof (f_equal fst EFlatSeek) as ECols0.
  pose proof (f_equal snd EFlatSeek) as ETail0.
  cbn [fst snd] in ECols0, ETail0.
  assert (ECols : lin_flat sg cols =
      (base ++ schedule_stock (oc :: rs)) ++ avail)
    by (symmetry; exact ECols0).
  destruct (seek_split tail avail tail0 ETailSeek)
    as (ETailSplit & HAvailCols).
  assert (ETail : tail = avail ++ lin_flat sg s).
  { rewrite ETailSplit, ETail0. reflexivity. }
  pose proof (lin_dtick_after_seek_flat_some
    sg cols s f renewed sfx f2 HW HK HL HP HN HHead HRun) as HFlatRun.
  rewrite ECols in HFlatRun.
  assert (HRenewAvail : renewed = true -> (2 <= length avail)%nat).
  { intro ER. specialize (HRenew ER).
    rewrite (lin_flen_flat_wf sg cols HW), ECols, length_app, HGap
      in HRenew. lia. }
  destruct (schedule_step_strip
    oc rs base avail (lin_flat sg s) f renewed
    (lin_flat sg sfx) f2 HFlatRun HRenewAvail)
    as (body & HBody & EBody).
  assert (ETailSeek' : seek tail = (avail, lin_flat sg s)).
  { rewrite ETailSeek, ETail0. reflexivity. }
  assert (HOneRun : schedule_run [oc] tail f
      (schedule_release oc body) f2).
  { eapply schedule_run_cons
      with (cols := avail) (s := lin_flat sg s)
           (renewed := renewed) (body := body).
    - exact ETailSeek'.
    - exact HBody.
    - constructor. }
  pose proof (schedule_deliveries_trips _ _ _ _ _
    (schedule_run_deliveries _ _ _ _ _ HOneRun))
    as HOneTrips.
  assert (EOutSuffix : lin_flat sg
      (skipn (lsCur fr) w2) =
      (base ++ schedule_stock rs) ++
        schedule_release oc body).
  { rewrite EW2.
    assert (HFirstLen : length (firstn (lsCur fr) w) =
        lsCur fr) by (rewrite length_firstn; lia).
    replace (lsCur fr) with
      (length (firstn (lsCur fr) w)) at 1
      by exact HFirstLen.
    rewrite LineageCascade_skipn_len_app, EBody. reflexivity. }
  exists [oc], rs, (schedule_release oc body).
  split; [reflexivity|]. split; [reflexivity|].
  split; [exact HOneTrips|].
  pose proof (schedule_frame_view_advance_one
    fr (lin_flat sg (skipn (lsCur fr) w))
    oc rs base tail body
    (conj HSlot (conj HLen (conj HShape
      (conj HBaseCols (conj HFrame HGap)))))) as HAdvance.
  rewrite EOutSuffix. exact HAdvance.
Qed.
Lemma literal_word_skipn : forall n w,
  lin_literal_word w = true ->
  lin_literal_word (skipn n w) = true.
Proof.
  induction n as [|n IH]; intros w H.
  - exact H.
  - destruct w as [|g w]; [reflexivity|]. cbn [skipn]. apply IH.
    unfold lin_literal_word in H.
    cbn [forallb] in H. apply andb_prop in H as [_ H]. exact H.
Qed.
Lemma literal_word_app_l : forall a b,
  lin_literal_word (a ++ b) = true ->
  lin_literal_word a = true.
Proof.
  intros a b H. unfold lin_literal_word in *.
  rewrite forallb_app in H. apply andb_prop in H as [H _]. exact H.
Qed.
Lemma lin_bottom_sched_zrun_S_inv :
  forall q lc sg lw f gap slot lw' f',
  lin_bottom_sched_zrun (S q) lc sg lw f gap slot
    = Some (lw', f') ->
  exists cols g t renewed sfx f2 lw2,
    lin_literal_word lw = true /\
    seek (skipn lc lw) = (cols, g :: t) /\
    lin_dtick_after_seek cols (g :: t) f
      = Some (renewed, sfx, f2) /\
    (renewed = true -> (gap + 2 <= lin_flen sg cols)%nat) /\
    (if Nat.eqb lc O then Some sfx
     else lin_join_safe sg (firstn lc lw) sfx) = Some lw2 /\
    lin_bottom_sched_zrun q lc sg lw2 f2
      (gap - 2 * N.to_nat (lin_sched_grant_one slot))%nat
      (lin_sched_slot_advance_one slot) = Some (lw', f').
Proof.
  intros q lc sg lw f gap slot lw' f' HRun.
  cbn [lin_bottom_sched_zrun] in HRun.
  destruct (lin_literal_word lw) eqn:ELit; [|discriminate].
  destruct (seek (skipn lc lw)) as [cols s] eqn:ESeek.
  destruct s as [|g t]; [discriminate|].
  destruct (lin_dtick_after_seek cols (g :: t) f)
    as [[[renewed sfx] f2]|] eqn:EStep; [|discriminate].
  destruct renewed.
  - destruct (negb (Nat.leb (gap + 2) (lin_flen sg cols)))
      eqn:EGuard; [discriminate|].
    destruct (if Nat.eqb lc O then Some sfx
              else lin_join_safe sg (firstn lc lw) sfx)
      as [lw2|] eqn:EJoin; [|discriminate].
    exists cols, g, t. exists true. exists sfx, f2, lw2.
    repeat split; try assumption.
    intros _. apply negb_false_iff in EGuard.
    apply PeanoNat.Nat.leb_le. exact EGuard.
  - destruct (if Nat.eqb lc O then Some sfx
              else lin_join_safe sg (firstn lc lw) sfx)
      as [lw2|] eqn:EJoin; [|discriminate].
    exists cols, g, t. exists false. exists sfx, f2, lw2.
    repeat split; try assumption. discriminate.
Qed.
Lemma lin_bottom_sched_zrun_schedule :
  forall q fr sg lw f lw' f',
  sg_wf sg ->
  (lsCur fr <= length lw)%nat ->
  (N.of_nat q <= lsTicks fr)%N ->
  lin_bottom_sched_zrun q (lsCur fr) sg lw f
    (lsGap fr) (lsSlot fr) = Some (lw', f') ->
  forall prs base tail,
  schedule_frame_view fr
    (skipn (lsCur fr) lw) prs base tail ->
  exists used rest tail',
    prs = used ++ rest /\
    length used = q /\
    schedule_trips used tail f tail' f' /\
    (forall i, (i <= lsCur fr)%nat ->
      firstn i lw = firstn i lw') /\
    skipn (lsCur fr) lw' =
      (base ++ schedule_stock rest) ++ tail'.
Proof.
  induction q as [|q IH];
    intros fr sg lw f lw' f' HW HCur HQt HRun prs base tail HView.
  - cbn [lin_bottom_sched_zrun] in HRun.
    destruct (lin_literal_word lw); [|discriminate].
    injection HRun as <- <-.
    destruct HView as (_ & _ & _ & _ & HFrame & _).
    exists (@nil (option N)), prs, tail.
    split; [reflexivity|]. split; [reflexivity|].
    split; [constructor; reflexivity|]. split.
    + intros; reflexivity.
    + exact HFrame.
  - destruct (lin_bottom_sched_zrun_S_inv q
      (lsCur fr) sg lw f (lsGap fr)
      (lsSlot fr) lw' f' HRun)
      as (cols & g & t & renewed & sfx & f2 & lw2 & HLit & ESeek &
          EStep & HRenew & EJoin & HRestRun).
    rewrite lin_sched_grant_one_eq,
      lin_sched_slot_advance_one_eq in HRestRun.
    destruct HView as
      (HSlot & HLen & HShape & HBaseCols & HFrame & HGap).
    destruct prs as [|oc rs].
    { cbn [length] in HLen. apply (f_equal N.of_nat) in HLen.
      rewrite N2Nat.id in HLen. cbn [N.of_nat] in HLen. lia. }
    assert (HMidCols : delivery_cols
        (base ++ schedule_stock (oc :: rs)) = true).
    { rewrite delivery_cols_app, HBaseCols,
        schedule_stock_cols. reflexivity. }
    assert (ESeekFrame :
        seek ((base ++ schedule_stock (oc :: rs)) ++
          tail) = (cols, g :: t)).
    { rewrite <- HFrame. exact ESeek. }
    rewrite (seek_app_delivery_cols
      (base ++ schedule_stock (oc :: rs)) tail HMidCols)
      in ESeekFrame.
    destruct (seek tail) as [avail tail0] eqn:ETailSeek.
    cbn [fst snd] in ESeekFrame.
    pose proof (f_equal fst ESeekFrame) as ECols0.
    pose proof (f_equal snd ESeekFrame) as ETail0.
    cbn [fst snd] in ECols0, ETail0.
    assert (ECols : cols =
        (base ++ schedule_stock (oc :: rs)) ++ avail)
      by (symmetry; exact ECols0).
    destruct (seek_split tail avail tail0 ETailSeek)
      as (ETailSplit & HAvailCols).
    assert (ETail : tail = avail ++ g :: t).
    { rewrite ETailSplit, ETail0. reflexivity. }
    assert (HLitCols : lin_literal_word cols = true).
    { pose proof (literal_word_skipn (lsCur fr) lw HLit) as HS.
      pose proof (seek_split (skipn (lsCur fr) lw)
        cols (g :: t) ESeek) as [ESplit _].
      rewrite ESplit in HS. exact (literal_word_app_l cols (g::t) HS). }
    rewrite ECols in EStep.
    assert (HRenewAvail : renewed = true -> (2 <= length avail)%nat).
    { intro ER. specialize (HRenew ER).
      rewrite (lin_flen_flat_wf sg cols HW) in HRenew.
      rewrite (literal_word_flat sg cols HLitCols), ECols
        in HRenew.
      rewrite length_app, HGap in HRenew. lia. }
    destruct (schedule_step_strip
      oc rs base avail (g :: t) f renewed sfx f2 EStep HRenewAvail)
      as (body & HBody & EBody).
    assert (ETailSeek' : seek tail = (avail, g :: t)).
    { rewrite ETailSeek, ETail0. reflexivity. }
    assert (HOneRun : schedule_run [oc] tail f
        (schedule_release oc body) f2).
    { eapply schedule_run_cons
        with (cols := avail) (s := g :: t)
             (renewed := renewed) (body := body).
      - exact ETailSeek'.
      - exact HBody.
      - constructor. }
    pose proof (schedule_deliveries_trips _ _ _ _ _
      (schedule_run_deliveries _ _ _ _ _ HOneRun))
      as HOneTrips.
    assert (EW2 : lw2 = firstn (lsCur fr) lw ++ sfx).
    { destruct (Nat.eqb (lsCur fr) O) eqn:ECur.
      - apply PeanoNat.Nat.eqb_eq in ECur. injection EJoin as <-.
        rewrite ECur. reflexivity.
      - exact (lin_join_safe_some _ _ _ _ EJoin). }
    assert (HStepPrefix : forall i, (i <= lsCur fr)%nat ->
        firstn i lw = firstn i lw2).
    { intros i Hi. rewrite EW2.
      assert (HFirstLen : length (firstn (lsCur fr) lw) =
          lsCur fr) by (rewrite length_firstn; lia).
      rewrite (firstn_app_left _ i (firstn (lsCur fr) lw)
        sfx ltac:(rewrite HFirstLen; exact Hi)).
      rewrite firstn_firstn, PeanoNat.Nat.min_l by exact Hi. reflexivity. }
    assert (EOutSuffix : skipn (lsCur fr) lw2 =
        (base ++ schedule_stock rs) ++
          schedule_release oc body).
    { rewrite EW2.
      assert (HFirstLen : length (firstn (lsCur fr) lw) =
          lsCur fr) by (rewrite length_firstn; lia).
      replace (lsCur fr) with
        (length (firstn (lsCur fr) lw)) at 1 by exact HFirstLen.
      rewrite LineageCascade_skipn_len_app, EBody. reflexivity. }
    pose proof (schedule_frame_view_advance_one
      fr (skipn (lsCur fr) lw) oc rs base tail body
      (conj HSlot (conj HLen (conj HShape
        (conj HBaseCols (conj HFrame HGap)))))) as HAdvance0.
    assert (HAdvance : schedule_frame_view
        (lin_sched_advance fr 1)
        (skipn (lsCur fr) lw2) rs base
        (schedule_release oc body)).
    { rewrite EOutSuffix. exact HAdvance0. }
    assert (HCur2 : (lsCur (lin_sched_advance fr 1) <=
        length lw2)%nat).
    { cbn [lin_sched_advance lsCur]. rewrite EW2.
      rewrite length_app, length_firstn. lia. }
    assert (HQt2 : (N.of_nat q <=
        lsTicks (lin_sched_advance fr 1))%N).
    { cbn [lin_sched_advance lsTicks].
      rewrite Nat2N.inj_succ in HQt. lia. }
    destruct (IH (lin_sched_advance fr 1) sg lw2 f2 lw' f'
      HW HCur2 HQt2 HRestRun rs base
      (schedule_release oc body) HAdvance)
      as (used & rest & tail' & ERs & HUsed & HTrips & HRecPrefix & HOut).
    exists (oc :: used), rest, tail'.
    split; [rewrite ERs; reflexivity|]. split; [cbn [length]; lia|].
    split.
    + change (schedule_trips ([oc] ++ used) tail f tail' f').
      eapply schedule_trips_app; eassumption.
    + split.
      * intros i Hi. rewrite (HStepPrefix i Hi).
        apply HRecPrefix. cbn [lin_sched_advance lsCur].
        exact Hi.
      * exact HOut.
Qed.
Lemma lin_bottom_local_scheduled_transition :
  forall take fr sg lw f lw' f',
  sg_wf sg ->
  (lsCur fr <= length lw)%nat ->
  (take <= lsTicks fr)%N ->
  lin_bottom_sched_zrun (N.to_nat take)
    (lsCur fr) sg lw f (lsGap fr) (lsSlot fr)
    = Some (lw', f') ->
  scheduled_transition fr take sg lw f sg lw' f'.
Proof.
  intros take fr sg lw f lw' f' HW HCur HTake HRun.
  destruct (lin_bottom_sched_zrun_literals
    (N.to_nat take) (lsCur fr) sg lw f
    (lsGap fr) (lsSlot fr) lw' f' HRun)
    as (HLit & HLit').
  destruct (lin_bottom_sched_zrun_raw
    (N.to_nat take) (lsCur fr) sg lw f
    (lsGap fr) (lsSlot fr) lw' f' HRun)
    as (post & HRawRun & EW').
  assert (HPrefix : forall i, (i <= lsCur fr)%nat ->
      lin_flat sg (firstn i lw) =
      lin_flat sg (firstn i lw')).
  { intros i Hi.
    rewrite (literal_word_flat sg (firstn i lw)
      (literal_word_firstn i lw HLit)).
    rewrite (literal_word_flat sg (firstn i lw')
      (literal_word_firstn i lw' HLit')).
    rewrite EW'.
    assert (HFirstLen : length (firstn (lsCur fr) lw) =
        lsCur fr) by (rewrite length_firstn; lia).
    rewrite (firstn_app_left _ i (firstn (lsCur fr) lw)
      post ltac:(rewrite HFirstLen; exact Hi)).
    rewrite firstn_firstn, PeanoNat.Nat.min_l by exact Hi. reflexivity. }
  split; [exact HPrefix|].
  intros prs base tail HView.
  assert (HViewRaw : schedule_frame_view fr
      (skipn (lsCur fr) lw) prs base tail).
  { rewrite <- (literal_word_flat sg
      (skipn (lsCur fr) lw)
      (literal_word_skipn (lsCur fr) lw HLit)).
    exact HView. }
  assert (HQt : (N.of_nat (N.to_nat take) <= lsTicks fr)%N)
    by (rewrite N2Nat.id; exact HTake).
  destruct (lin_bottom_sched_zrun_schedule
    (N.to_nat take) fr sg lw f lw' f' HW HCur HQt HRun
    prs base tail HViewRaw)
    as (used & rest & tail' & EPrs & HUsed & HTrips & _ & HOutRaw).
  destruct HView as
    (HSlot & HLen & HShape & HBaseCols & HFrame & HGap).
  assert (ERest : rest = skipn (N.to_nat take) prs).
  { rewrite EPrs, <- HUsed. symmetry.
    apply LineageCascade_skipn_len_app. }
  assert (HTakeNat : (N.to_nat take <= length prs)%nat).
  { rewrite EPrs, length_app, HUsed. lia. }
  assert (HOut : lin_flat sg
      (skipn (lsCur fr) lw') =
      (base ++ schedule_stock rest) ++ tail').
  { rewrite (literal_word_flat sg
      (skipn (lsCur fr) lw')
      (literal_word_skipn (lsCur fr) lw' HLit')).
    exact HOutRaw. }
  exists used, rest, tail'.
  split; [exact EPrs|]. split; [exact HUsed|]. split; [exact HTrips|].
  unfold schedule_frame_view, lin_sched_advance.
  cbn [lsSlot lsTicks lsGap].
  repeat split.
  - exact (sched_slot_advance_le3
      (lsSlot fr) take HSlot).
  - rewrite ERest. exact (schedule_ticks_skip
      (lsTicks fr) take prs HLen HTake).
  - change (schedule_shape
      (lin_sched_slot_advance (lsSlot fr) take) rest).
    rewrite ERest.
    pose proof (schedule_shape_skipn
      (N.to_nat take) prs (lsSlot fr) HSlot HShape) as HRestShape.
    rewrite N2Nat.id in HRestShape. exact HRestShape.
  - exact HBaseCols.
  - exact HOut.
  - rewrite ERest.
    pose proof (schedule_stock_skip_length
      (N.to_nat take) prs (lsSlot fr)
      HTakeNat HSlot HShape) as HRestStock.
    rewrite N2Nat.id in HRestStock.
    pose proof (schedule_stock_first_skip
      (N.to_nat take) prs) as EStockSplit.
    apply (f_equal (@length bg)) in EStockSplit.
    rewrite length_app in EStockSplit.
    pose proof (schedule_stock_firstn_length
      (N.to_nat take) prs (lsSlot fr)
      HTakeNat HSlot HShape) as HUsedStock.
    rewrite N2Nat.id in HUsedStock.
    rewrite length_app, HRestStock. rewrite length_app in HGap. lia.
Qed.
Lemma lin_bottom_global_scheduled_transition :
  forall take fr base lc sg w f lw' f' w2,
  sg_wf sg ->
  lsCur fr = (base + lc)%nat ->
  (base <= length w)%nat ->
  (lc <= length (skipn base w))%nat ->
  (take <= lsTicks fr)%N ->
  lin_bottom_sched_zrun (N.to_nat take) lc sg
    (skipn base w) f (lsGap fr) (lsSlot fr)
    = Some (lw', f') ->
  w2 = setsfx base w lw' ->
  scheduled_transition fr take sg w f sg w2 f'.
Proof.
  intros take fr base lc sg w f lw' f' w2
    HW HCur HBase HLc HTake HRun ->.
  set (lfr := {| lsCur := lc;
                 lsTicks := lsTicks fr;
                 lsSlot := lsSlot fr;
                 lsGap := lsGap fr |}).
  assert (HLocal : scheduled_transition lfr take sg (skipn base w) f
      sg lw' f').
  { apply lin_bottom_local_scheduled_transition; [exact HW|exact HLc|exact HTake|].
    unfold lfr. cbn [lsCur lsGap lsSlot]. exact HRun. }
  destruct HLocal as (HLocalPrefix & HLocalFrame).
  assert (HPreLen : length (firstn base w) = base)
    by (rewrite length_firstn; lia).
  assert (EInput : w = firstn base w ++ skipn base w)
    by (symmetry; apply firstn_skipn).
  assert (EOutput : setsfx base w lw' = firstn base w ++ lw')
    by (apply setsfx_app; exact HBase).
  assert (HPrefix : forall i, (i <= lsCur fr)%nat ->
      lin_flat sg (firstn i w) =
      lin_flat sg
        (firstn i (setsfx base w lw'))).
  { intros i Hi.
    destruct (PeanoNat.Nat.le_gt_cases i base) as [HIB|HIB].
    - rewrite EOutput. rewrite EInput at 1.
      rewrite
        (firstn_app_left _ i (firstn base w) (skipn base w)
          ltac:(rewrite HPreLen; exact HIB)).
      rewrite
        (firstn_app_left _ i (firstn base w) lw'
          ltac:(rewrite HPreLen; exact HIB)). reflexivity.
    - set (d := (i-base)%nat).
      assert (Ei : i = (base+d)%nat) by (unfold d; lia).
      assert (Hd : (d <= lc)%nat) by (unfold d; rewrite HCur in Hi; lia).
      assert (EFirstIn : firstn i w =
          firstn base w ++ firstn d (skipn base w)).
      { rewrite Ei. apply firstn_add_skipn. }
      assert (EFirstOut : firstn i (setsfx base w lw') =
          firstn base w ++ firstn d lw').
      { rewrite EOutput.
        replace i with (length (firstn base w) + d)%nat by lia.
        apply firstn_prefix_add. }
      rewrite EFirstIn, EFirstOut, !lin_flat_app_c.
      rewrite (HLocalPrefix d ltac:(unfold lfr; cbn [lsCur]; exact Hd)).
      reflexivity. }
  split; [exact HPrefix|].
  intros prs bword tail HView.
  assert (EInputSuffix : skipn lc (skipn base w) =
      skipn (lsCur fr) w).
  { rewrite skipn_add, HCur. reflexivity. }
  assert (HViewLocal : schedule_frame_view lfr
      (lin_flat sg (skipn lc (skipn base w))) prs bword tail).
  { rewrite EInputSuffix. unfold lfr, schedule_frame_view in *.
    cbn [lsSlot lsTicks lsGap] in *. exact HView. }
  destruct (HLocalFrame prs bword tail HViewLocal)
    as (used & rest & tail' & EPrs & HUsed & HTrips & HViewOut).
  assert (EOutputSuffix :
      skipn (lsCur fr) (setsfx base w lw') = skipn lc lw').
  { rewrite EOutput.
    replace (lsCur fr) with
      (length (firstn base w) + lc)%nat by lia.
    apply skipn_prefix_add. }
  exists used, rest, tail'.
  split; [exact EPrs|].
  split; [exact HUsed|].
  split; [exact HTrips|].
  rewrite EOutputSuffix.
  unfold lfr, schedule_frame_view,
    lin_sched_advance in *.
  cbn [lsSlot lsTicks lsGap] in *.
  exact HViewOut.
Qed.
Open Scope N_scope.
Open Scope sym.
Opaque LROUND_FUEL LROUND_CHUNKS
       FLAT_ROUND_FUEL CFUEL TRIES.
Lemma lin_dtick_after_seek_phseq :
  forall cols s f renewed out f',
  lin_dtick_after_seek cols s f = Some (renewed, out, f') ->
  phseq out =
    phseq cols ++ phseq s.
Proof.
  intros cols s f renewed out f' HRun.
  unfold lin_dtick_after_seek in HRun.
  destruct (renew_seg (length s) cols s f)
    as [[body f2]|] eqn:ER.
  - injection HRun as <- <- <-.
    exact (renew_seg_phseq
      (length s) cols s f body f2 ER).
  - destruct s as [|[[o z] c] t].
    + destruct (leaf_act [] f) as [[tail f2]|] eqn:EL;
        [|discriminate].
      injection HRun as <- <- <-.
      rewrite phseq_app.
      rewrite (leaf_act_phseq [] f tail f2 EL).
      reflexivity.
    + destruct ((z =? 3) && (c =? 1))%N eqn:EZ.
      * match type of HRun with
        | context [fire_comp ?nn ?ss ?ff] =>
            destruct (fire_comp nn ss ff)
              as [[tail f2]|] eqn:EF in HRun
        end.
        -- cbv beta iota in HRun. injection HRun as <- <- <-.
           rewrite phseq_app.
           rewrite (fire_comp_phseq
             (length ((o,z,c)::t)) ((o,z,c)::t) f tail f2 EF).
           reflexivity.
        -- cbv beta iota in HRun. discriminate.
      * match type of HRun with
        | context [sand_leaf ?ss] =>
            destruct (sand_leaf ss) eqn:ES in HRun
        end; [cbv beta iota in HRun; discriminate|].
        cbv beta iota in HRun.
        match type of HRun with
        | context [leaf_act ?ss ?ff] =>
            destruct (leaf_act ss ff)
              as [[tail f2]|] eqn:EL in HRun
        end.
        -- cbv beta iota in HRun. injection HRun as <- <- <-.
           rewrite phseq_app.
           rewrite (leaf_act_phseq
             ((o,z,c)::t) f tail f2 EL).
           reflexivity.
        -- cbv beta iota in HRun. discriminate.
Qed.
Lemma lin_direct_phseq :
  forall sg w cur f cols s renewed sfx f2 w2,
  seek (skipn cur w) = (cols, s) ->
  lin_dtick_after_seek cols s f = Some (renewed, sfx, f2) ->
  (if Nat.eqb cur O then Some sfx
   else lin_join_safe sg (firstn cur w) sfx) = Some w2 ->
  phseq w2 = phseq w.
Proof.
  intros sg w cur f cols s renewed sfx f2 w2 HSeek HRun HJoin.
  assert (EOut : w2 = firstn cur w ++ sfx).
  { destruct (Nat.eqb cur O) eqn:ECur.
    - apply PeanoNat.Nat.eqb_eq in ECur. injection HJoin as <-.
      rewrite ECur. reflexivity.
    - exact (lin_join_safe_some
        sg (firstn cur w) sfx w2 HJoin). }
  pose proof (seek_split (skipn cur w) cols s HSeek) as [ESplit _].
  rewrite EOut, phseq_app,
    (lin_dtick_after_seek_phseq cols s f renewed sfx f2 HRun).
  rewrite <- phseq_app, <- ESplit.
  rewrite <- phseq_app, firstn_skipn. reflexivity.
Qed.
Lemma lin_direct_zpack :
  forall sg w cur f cols g t renewed sfx f2 w2,
  sg_wf sg -> keys_big sg ->
  ph_margins sg w -> ph_nbrs sg w ->
  seek (skipn cur w) = (cols, g :: t) ->
  lin_dtick_after_seek cols (g :: t) f
    = Some (renewed, sfx, f2) ->
  (if Nat.eqb cur O then Some sfx
   else lin_join_safe sg (firstn cur w) sfx) = Some w2 ->
  zpack sg w2.
Proof.
  intros sg w cur f cols [[o z] c] t renewed sfx f2 w2
    HW HK HM HN HSeek HRun HJoin.
  set (tg := (cur + length cols)%nat).
  assert (EFirst : firstn tg w = firstn cur w ++ cols).
  { unfold tg. exact (firstn_seek_at
      w cur cols ((o,z,c)::t) HSeek). }
  assert (ESkip : skipn tg w = (o,z,c) :: t).
  { unfold tg. exact (skipn_seek_at
      w cur cols ((o,z,c)::t) HSeek). }
  assert (HSnd : snd (seek (skipn cur w)) = (o,z,c) :: t)
    by (rewrite HSeek; reflexivity).
  assert (HTest : seektest (o,z,c) = false)
    by (exact (seek_snd_head
      (skipn cur w) (o,z,c) t HSnd)).
  assert (HNoncasc : casc (o,z,c) = false)
    by (exact (seektest_noncasc _ HTest)).
  assert (HSeq : w = firstn tg w ++ (o,z,c) :: t).
  { rewrite <- ESkip. symmetry. apply firstn_skipn. }
  assert (HPrefix : zspack sg (firstn tg w)).
  { exact (firstn_zspack_of_site
      sg w tg (o,z,c) t HM HN ESkip HNoncasc). }
  assert (HMs : ph_margins sg ((o,z,c)::t)).
  { exact (margins_cut_at sg w (firstn tg w)
      (o,z,c) t HM HSeq HNoncasc
      (seektest_notag _ HTest)). }
  assert (HNs : ph_nbrs sg ((o,z,c)::t)).
  { apply (ph_nbrs_app_r sg (firstn tg w)).
    rewrite <- HSeq. exact HN. }
  assert (EOut : w2 = firstn cur w ++ sfx).
  { destruct (Nat.eqb cur O) eqn:ECur.
    - apply PeanoNat.Nat.eqb_eq in ECur. injection HJoin as <-.
      rewrite ECur. reflexivity.
    - exact (lin_join_safe_some
        sg (firstn cur w) sfx w2 HJoin). }
  unfold lin_dtick_after_seek in HRun.
  match type of HRun with
  | context [renew_seg ?nn ?cc ?ss ?ff] =>
      destruct (renew_seg nn cc ss ff)
        as [[body fR]|] eqn:ER in HRun
  end.
  - cbv beta iota in HRun. injection HRun as <- <- <-.
    destruct (renew_seg_head
      (length ((o,z,c)::t)) cols ((o,z,c)::t) f (body,fR) ER)
      as (rest & ES). injection ES as Eo Ez Ec Et.
    subst o z c t.
    pose proof (renew_seg_app
      (length ((4,3,1)%N::rest)) (firstn cur w) cols rest f body fR ER)
      as ERFull.
    rewrite EOut.
    exact (proj2 (fire_renew_out_tag
      (length ((4,3,1)%N::rest)) sg HW HK)
      (firstn tg w) ((4,3,1)%N::rest) f
      (firstn cur w ++ body) fR HPrefix HMs HNs
      ltac:(rewrite EFirst; exact ERFull)).
  - destruct ((z =? 3) && (c =? 1))%N eqn:EZ.
    + match type of HRun with
      | context [fire_comp ?nn ?ss ?ff] =>
          destruct (fire_comp nn ss ff)
            as [[tail fR]|] eqn:EF in HRun
      end.
      * cbv beta iota in HRun. injection HRun as <- <- <-.
        rewrite EOut, app_assoc, <- EFirst.
        apply (zpack_zspack_app sg (firstn tg w) tail HPrefix).
        exact (proj1 (fire_renew_out_tag
          (length ((o,z,c)::t)) sg HW HK)
          ((o,z,c)::t) f tail fR HMs HNs EF).
      * cbv beta iota in HRun. discriminate.
    + match type of HRun with
      | context [sand_leaf ?ss] =>
          destruct (sand_leaf ss) eqn:ES in HRun
      end; [cbv beta iota in HRun; discriminate|].
      cbv beta iota in HRun.
      match type of HRun with
      | context [leaf_act ?ss ?ff] =>
          destruct (leaf_act ss ff)
            as [[tail fR]|] eqn:EL in HRun
      end.
      * cbv beta iota in HRun. injection HRun as <- <- <-.
        rewrite EOut, app_assoc, <- EFirst.
        apply (zpack_zspack_app sg (firstn tg w) tail HPrefix).
        apply zpack_of_npack.
        exact (leaf_npack_out_tag sg ((o,z,c)::t) f tail fR
          HW HK HMs HNs EL).
      * cbv beta iota in HRun. discriminate.
Qed.
Lemma lin_direct_stable :
  forall sg w cur f cols g t renewed sfx f2 w2,
  stable_guard sg w -> lin_guard sg w = true ->
  seek (skipn cur w) = (cols, g :: t) ->
  lin_dtick_after_seek cols (g :: t) f
    = Some (renewed, sfx, f2) ->
  (if Nat.eqb cur O then Some sfx
   else lin_join_safe sg (firstn cur w) sfx) = Some w2 ->
  stable_guard sg w2.
Proof.
  intros sg w cur f cols g t renewed sfx f2 w2
    ((HOk & HPT) & HE & HW & HS & HK & HP) HGuard HSeek HRun HJoin.
  assert (HM : ph_margins sg w)
    by (exact (lguard_margins sg w HGuard)).
  assert (HN : ph_nbrs sg w)
    by (exact (margins_edges_nbrs sg w HM HE)).
  assert (ESeq : phseq w2 = phseq w)
    by (exact (lin_direct_phseq sg w cur f cols (g::t)
      renewed sfx f2 w2 HSeek HRun HJoin)).
  assert (HOk2 : lin_ok sg w2 = true)
    by (exact (lin_ok_of_phseq_eq sg w w2 ESeq HOk)).
  assert (HPT2 : lin_ptags sg w2 = true)
    by (exact (lin_ptags_of_phseq_eq sg w w2 ESeq HPT)).
  assert (HZ : zpack sg w2)
    by (exact (lin_direct_zpack sg w cur f cols g t renewed sfx f2 w2
      HW HK HM HN HSeek HRun HJoin)).
  assert (HE2 : tag_edges w2)
    by (exact (tag_edges_of_nbrs1z sg w2 (proj1 HZ) HPT2)).
  unfold stable_guard, front_repr.
  repeat split; assumption.
Qed.
Lemma literal_word_phseq_nil : forall w,
  lin_literal_word w = true -> phseq w = [].
Proof.
  intros w. induction w as [|g w IH]; intros H; [reflexivity|].
  unfold lin_literal_word in H.
  cbn [forallb] in H. apply andb_prop in H as [Hg Hw].
  apply negb_true_iff in Hg. cbn [phseq].
  rewrite Hg. exact (IH Hw).
Qed.
Lemma literal_word_phfreeP : forall w,
  lin_literal_word w = true -> phfreeP w.
Proof.
  intros w H g Hin. unfold lin_literal_word in H.
  apply forallb_forall with (x := g) in H; [|exact Hin].
  apply negb_true_iff in H. exact H.
Qed.
Lemma tag_edges_app_join_inv : forall a b,
  tag_edges (a ++ b) -> edge_join a b.
Proof.
  intros a. induction a as [|x [|y a] IH]; intros b HE.
  - exact I.
  - destruct b as [|z b]; [exact I|].
    cbn [app tag_edges edge_join last] in HE |- *.
    exact (proj1 HE).
  - cbn [app tag_edges] in HE.
    exact (IH b (proj2 HE)).
Qed.
Lemma literal_suffix_replace_edges :
  forall w base old new lc,
  w = firstn base w ++ old ->
  tag_edges w ->
  lin_literal_word old = true ->
  lin_literal_word new = true ->
  (base = O \/ (1 <= lc)%nat) ->
  (forall i, (i <= lc)%nat -> firstn i old = firstn i new) ->
  tag_edges (firstn base w ++ new).
Proof.
  intros w base old new lc EW HE HOld HNew Hlc HP.
  assert (HPre : tag_edges (firstn base w)).
  { apply (tag_edges_prefix (firstn base w) old).
    rewrite <- EW. exact HE. }
  assert (HNewE : tag_edges new).
  { apply tag_edges_phfreeP.
    exact (literal_word_phfreeP new HNew). }
  apply tag_edges_app_join; [exact HPre|exact HNewE|].
  destruct (firstn base w) as [|x pre] eqn:EPre; [exact I|].
  destruct new as [|y ys] eqn:ENew; [exact I|].
  destruct Hlc as [Hbase|Hlc].
  { subst base. cbn [firstn] in EPre. discriminate. }
  assert (EHead : firstn 1 old = firstn 1 (y::ys)) by (apply HP; lia).
  destruct old as [|z zs]; [discriminate EHead|].
  cbn [firstn] in EHead. injection EHead as <-.
  pose proof (tag_edges_app_join_inv (firstn base w) (z::zs)
    ltac:(rewrite EPre, <- EW; exact HE)) as HJ.
  rewrite EPre in HJ.
  unfold edge_join in HJ |- *.
  cbn in HJ |- *. exact HJ.
Qed.
Lemma literal_suffix_replace_stable :
  forall sg w base old new lc,
  stable_guard sg w ->
  w = firstn base w ++ old ->
  lin_literal_word old = true ->
  lin_literal_word new = true ->
  (base = O \/ (1 <= lc)%nat) ->
  (forall i, (i <= lc)%nat -> firstn i old = firstn i new) ->
  stable_guard sg (firstn base w ++ new).
Proof.
  intros sg w base old new lc
    ((HOk & HPT) & HE & HW & HS & HK & HP) EW HOld HNew Hlc HPrefix.
  assert (EOldSeq : phseq w =
      phseq (firstn base w)).
  { rewrite EW at 1. rewrite phseq_app,
      (literal_word_phseq_nil old HOld), app_nil_r. reflexivity. }
  assert (ESeq : phseq (firstn base w ++ new) =
      phseq w).
  { rewrite phseq_app,
      (literal_word_phseq_nil new HNew), app_nil_r.
    symmetry. exact EOldSeq. }
  assert (HOk2 : lin_ok sg (firstn base w ++ new) = true)
    by (exact (lin_ok_of_phseq_eq sg w _ ESeq HOk)).
  assert (HPT2 : lin_ptags sg (firstn base w ++ new) = true)
    by (exact (lin_ptags_of_phseq_eq sg w _ ESeq HPT)).
  assert (HE2 : tag_edges (firstn base w ++ new))
    by (exact (literal_suffix_replace_edges
      w base old new lc EW HE HOld HNew Hlc HPrefix)).
  unfold stable_guard, front_repr.
  repeat split; assumption.
Qed.
Lemma lin_bottom_global_stable :
  forall take fr base lc sg w f lw' f',
  stable_guard sg w ->
  lsCur fr = (base + lc)%nat ->
  base = (lsCur fr - 2)%nat ->
  (base <= length w)%nat ->
  (lc <= length (skipn base w))%nat ->
  lin_bottom_sched_zrun (N.to_nat take) lc sg
    (skipn base w) f (lsGap fr) (lsSlot fr)
    = Some (lw', f') ->
  stable_guard sg (setsfx base w lw').
Proof.
  intros take fr base lc sg w f lw' f' HG HCur HBase HbaseLen Hlc HRun.
  destruct (lin_bottom_sched_zrun_literals
    (N.to_nat take) lc sg (skipn base w) f
    (lsGap fr) (lsSlot fr) lw' f' HRun)
    as (HLit & HLit').
  destruct (lin_bottom_sched_zrun_raw
    (N.to_nat take) lc sg (skipn base w) f
    (lsGap fr) (lsSlot fr) lw' f' HRun)
    as (post & _ & EOut).
  assert (HPrefix : forall i, (i <= lc)%nat ->
      firstn i (skipn base w) = firstn i lw').
  { intros i Hi. rewrite EOut.
    rewrite (firstn_app_left bg i
      (firstn lc (skipn base w)) post
      ltac:(rewrite length_firstn; lia)).
    rewrite firstn_firstn, PeanoNat.Nat.min_l by exact Hi. reflexivity. }
  assert (HlcPos : base = O \/ (1 <= lc)%nat).
  { destruct (PeanoNat.Nat.eq_dec base O); [left; exact e|right].
    rewrite HBase in n. rewrite HCur in *. lia. }
  rewrite (setsfx_app base w lw' HbaseLen).
  apply (literal_suffix_replace_stable sg w base (skipn base w) lw' lc
    HG ltac:(symmetry; apply firstn_skipn) HLit HLit' HlcPos HPrefix).
Qed.
Lemma lin_ptags_nth_ph : forall sg w i g,
  lin_ptags sg w = true ->
  nth_error w i = Some g -> phshape g = true ->
  ph sg g = true.
Proof.
  intros sg w i. revert w.
  induction i as [|i IH]; intros [|a w] g HPT Hnth HP;
    try discriminate.
  - cbn [nth_error] in Hnth. injection Hnth as <-.
    exact (lin_ptags_head_ph sg a w HPT HP).
  - cbn [nth_error] in Hnth.
    cbn [lin_ptags] in HPT.
    exact (IH w g (proj2 (andb_prop _ _ HPT)) Hnth HP).
Qed.
Lemma phase_form_phfreeP : forall p,
  (p < 28)%N -> phfreeP (phase_form p).
Proof.
  intros p Hp g Hin.
  pose proof (phase_form_nolvl p Hp) as H.
  apply forallb_forall with (x := g) in H; [|exact Hin].
  apply negb_true_iff in H. exact H.
Qed.
Lemma phase_form_head_guard : forall p,
  (p < 28)%N ->
  exists g rest,
    phase_form p = g :: rest /\
    phshape g = false /\
    (right_edge g \/ casc g = false).
Proof.
  intros p Hp.
  pose proof (below28_In p Hp) as H.
  cbn [P28 List.map seq In] in H.
  repeat (destruct H as [H|H];
    [ subst p; eexists; eexists; split; [reflexivity|]; split;
      [reflexivity|first [left; right; reflexivity | right; reflexivity]]
    | ]).
  contradiction.
Qed.
Lemma phase_form_edge_join_guarded : forall sg pre p tail,
  (p < 28)%N ->
  ph_margins sg
    (pre ++ (phase_form p ++ tail)) ->
  lin_ptags sg
    (pre ++ (phase_form p ++ tail)) = true ->
  edge_join pre (phase_form p ++ tail).
Proof.
  intros sg pre p tail Hp HM HPT.
  destruct (phase_form_head_guard p Hp)
    as (g & rest & EPhase & HG & [HR|HC]).
  all: rewrite EPhase in HM, HPT |- *.
  all: destruct pre as [|a pre]; [exact I|].
  all: change (edge_pair (last (a::pre) d0) g).
  - split; [intros _; exact HR|]. intros H. rewrite HG in H. discriminate.
  - split; [|intros H; rewrite HG in H; discriminate].
    intros HLast. exfalso.
    set (pi := (length (a::pre) - 1)%nat).
    set (qi := length (a::pre)).
    assert (HLastNth :
      nth_error ((a::pre) ++ (g :: rest ++ tail)) pi =
        Some (last (a::pre) d0)).
    { unfold pi. rewrite nth_error_app1 by (cbn [length]; lia).
      rewrite <- (nth_last (a::pre) d0
        ltac:(discriminate)).
      apply nth_error_nth'. cbn [length]. lia. }
    assert (HHeadNth :
      nth_error ((a::pre) ++ ((g :: rest) ++ tail)) qi = Some g).
    { unfold qi. rewrite nth_error_app2 by lia.
      replace (length (a::pre) - length (a::pre))%nat with O by lia.
      reflexivity. }
    assert (HPh : ph sg (last (a::pre) d0) = true).
    { exact (lin_ptags_nth_ph sg
        ((a::pre) ++ (g :: rest ++ tail)) pi
        (last (a::pre) d0) HPT HLastNth HLast). }
    destruct (HM pi (last (a::pre) d0) HLastNth HPh)
      as (_ & _ & HWin).
    destruct (HWin qi ltac:(unfold pi, qi, GUARD; lia)
      ltac:(unfold pi, qi, GUARD; lia)
      ltac:(unfold pi, qi; cbn [length]; lia)) as (g' & Hg' & HC' & _).
    rewrite HHeadNth in Hg'. injection Hg' as <-. congruence.
Qed.
Lemma phase_form_replace_edges_guarded :
  forall sg pre p q oldg newg post,
  (p < 28)%N -> (q < 28)%N ->
  tag_edges
    (pre ++ (phase_form p ++ oldg :: post)) ->
  ph_margins sg
    (pre ++ (phase_form q ++ newg :: post)) ->
  lin_ptags sg
    (pre ++ (phase_form q ++ newg :: post)) = true ->
  head_equiv oldg newg ->
  phshape newg = false ->
  tag_edges
    (pre ++ (phase_form q ++ newg :: post)).
Proof.
  intros sg pre p q oldg newg post Hp Hq HE HM HPT HEquiv HNew.
  assert (HPre : tag_edges pre).
  { apply (tag_edges_prefix pre
      (phase_form p ++ oldg :: post)). exact HE. }
  assert (HOldTail : tag_edges (oldg :: post)).
  { apply (tag_edges_app_r_probe
      (pre ++ phase_form p) (oldg::post)).
    rewrite <- app_assoc. exact HE. }
  assert (HNewTail : tag_edges (newg :: post)).
  { apply (tag_edges_replace_head [] oldg newg post
      HEquiv). exact HOldTail. }
  assert (HPhaseTail : tag_edges
      (phase_form q ++ newg :: post)).
  { apply tag_edges_shape_free_app_probe.
    - exact (phase_form_phfreeP q Hq).
    - intros g t E. injection E as <- <-. exact HNew.
    - exact HNewTail. }
  apply tag_edges_app_join;
    [exact HPre|exact HPhaseTail|].
  exact (phase_form_edge_join_guarded sg pre q (newg::post)
    Hq HM HPT).
Qed.
Lemma lin_bulk_partial_edges_guarded :
  forall sg w j p t w' sg' nh rem emit,
  tag_edges w ->
  lin_guard sg' w' = true ->
  lin_ptags sg' w' = true ->
  detect_phase w j = Some p ->
  Nat.eqb (N.to_nat ((p+t)/28)) O = true ->
  lin_bulk sg w j p t = Some (w', sg', nh, rem, emit) ->
  tag_edges w'.
Proof.
  intros sg w j p t w' sg' nh rem emit HE HGuard HPT HD Hfull HB.
  destruct (lin_bulk_checks sg w j p t _ HB)
    as (gb & EW & EK & EL & _ & EE).
  destruct (site_layout w j p gb HD EW EE)
    as (HL & HLen & HPost).
  destruct (detect_phase_form w j p HD) as (Hp & _).
  destruct (lin_bulk_partial_out sg w j p t w' sg' nh rem
    emit gb Hfull HB EW) as (Esg & Enh & Erem & Eemit & Ew').
  destruct (lvl_big_shape gb EL) as (cgb & Egb).
  set (PRE := firstn j w) in *.
  set (RST := skipn (S (j + phase_len p)) w) in *.
  assert (Hpt : (p+t < 28)%N)
    by exact (full_zero_lt28 p t Hfull).
  assert (Hq : ((p+t) mod 28 < 28)%N) by (apply N.mod_lt; lia).
  assert (Hplen : length (phase_form p) = phase_len p)
    by (apply phase_form_len; exact Hp).
  assert (EW2 : w' = PRE ++ phase_form ((p+t) mod 28)
      ++ (4,2,(cgb + DBu ((p+t) mod 28))
                    - DBu p)%N :: RST).
  { rewrite Ew'. rewrite HL at 1. rewrite Egb.
    rewrite <- HLen, <- Hplen. apply subst_site. }
  assert (EW3 : w' = PRE ++ (phase_form ((p+t) mod 28)
      ++ (4,2,(cgb + DBu ((p+t) mod 28))
                    - DBu p)%N :: RST)).
  { rewrite EW2. reflexivity. }
  subst sg'. rewrite EW3 in HGuard, HPT. rewrite EW3.
  apply (phase_form_replace_edges_guarded sg PRE p ((p+t) mod 28)
    (4,2,cgb)%N
    (4,2,(cgb + DBu ((p+t) mod 28))
                  - DBu p)%N RST Hp Hq).
  - rewrite <- Egb, <- HL. exact HE.
  - exact (lguard_margins sg _ HGuard).
  - exact HPT.
  - unfold head_equiv.
    cbn [gO gZ]. repeat split; try reflexivity.
  - apply phshape_onot9. reflexivity.
Qed.
Lemma lin_bulk_cross_edges_guarded :
  forall sg w j p t w' sg' nh rem emit gb pre post,
  tag_edges w ->
  lin_guard sg' w' = true ->
  lin_ptags sg' w' = true ->
  is_spc (nth O w d0) = false ->
  w = pre ++ phase_form p ++ gb :: post ->
  length pre = j -> post <> [] -> keyi sg gb = None ->
  (p < 28)%N ->
  Nat.eqb (N.to_nat ((p+t)/28)) O = false ->
  lin_bulk sg w j p t = Some (w', sg', nh, rem, emit) ->
  tag_edges w'.
Proof.
  intros sg w j p t w' sg' nh rem emit gb pre post
    HE HGuard HPT H0 Hw Hj Hpost Hgb Hp Hfull HB.
  destruct (lin_bulk_pieces sg w j p t w' sg' nh rem emit
    gb pre post Hw Hj Hpost Hgb Hp H0 Hfull HB)
    as (left & used & sp & hd & rest0 & cgb & EC & EM & Hpre2 & Hnh
        & Hgbs & Hcgbf & Hrem & Hemit & Heph & Hw').
  assert (Hspc : is_spc sp = true).
  { pose proof (gclimb_last_spc _ _ _ _ _ _ _ _ EC) as HS.
    rewrite EM in HS. exact HS. }
  assert (HL : lvl_big hd = true).
  { eapply gclimb_last_nonph_lvl;
      [exact EC|exact EM|exact Heph]. }
  destruct (lvl_big_shape hd HL) as (ch & Ehd). subst hd.
  assert (Hr : (rem < 28)%N).
  { rewrite Hrem. apply N.mod_lt. lia. }
  assert (DWO : w = rev left ++ ([sp] ++ ([(4,2,ch)%N] ++
      (rest0 ++ (phase_form p ++ ([(4,2,cgb)%N] ++ post)))))).
  { rewrite Hw, Hpre2, Hgbs. rewrite <- !app_assoc.
    cbn [app]. reflexivity. }
  assert (HP : tag_edges (rev left)).
  { apply (tag_edges_prefix (rev left)
      ([sp] ++ ([(4,2,ch)%N] ++
       (rest0 ++ (phase_form p ++ ([(4,2,cgb)%N] ++ post)))))).
    rewrite <- DWO. exact HE. }
  assert (HTail : tag_edges
      ((4,2,ch)%N :: rest0 ++ phase_form p ++ (4,2,cgb)%N :: post)).
  { pose proof HE as H. rewrite DWO in H.
    exact (tag_edges_app_r_probe
      (rev left ++ [sp])
      ((4,2,ch)%N :: rest0 ++ phase_form p ++
        (4,2,cgb)%N :: post)
      ltac:(rewrite <- app_assoc; cbn [app]; exact H)). }
  assert (HRHead : shape_head_free rest0).
  { destruct rest0 as [|g0 r0].
    - intros g r Er. discriminate.
    - intros g r Er. injection Er as <- <-.
      pose proof (head_free_after_nonside_probe
        [] (4,2,ch)%N
        ((g0::r0) ++ phase_form p ++ (4,2,cgb)%N :: post)
        HTail ltac:(intros [H _]; discriminate)) as HH.
      exact (HH g0 (r0 ++ phase_form p ++ (4,2,cgb)%N :: post)
        eq_refl). }
  assert (HR : tag_edges rest0).
  { exact (tag_edges_app_r_probe [(4,2,ch)%N] rest0
      ltac:(apply tag_edges_prefix with
        (b := phase_form p ++ (4,2,cgb)%N :: post);
        exact HTail)). }
  assert (HGBPost : tag_edges ((4,2,cgb)%N :: post)).
  { pose proof HE as H. rewrite DWO in H.
    exact (tag_edges_app_r_probe
      (rev left ++ [sp] ++ [(4,2,ch)%N] ++ rest0 ++ phase_form p)
      ((4,2,cgb)%N :: post) ltac:(rewrite <- !app_assoc; exact H)). }
  assert (HPostHead : shape_head_free post).
  { exact (head_free_after_nonside_probe [] (4,2,cgb)%N post
      HGBPost ltac:(intros [H _]; discriminate)). }
  assert (HPost : tag_edges post)
    by exact (tag_edges_tail (4,2,cgb)%N post HGBPost).
  set (hnew := (4,2,ch + DBu rem - 3)%N).
  set (bend := (4,2,cgb - 1 - DBu p)%N).
  set (A := phase_form rem ++ [hnew]).
  set (R := List.map (adj4p sg') rest0).
  set (S := [(8,2,1)%N; bend] ++ post).
  set (Tail := [hnew] ++ (R ++ S)).
  assert (HAfree : phfreeP A).
  { unfold A, phfreeP. intros g Hin.
    apply in_app_or in Hin. destruct Hin as [Hin|Hin].
    - exact (phase_form_phfreeP rem Hr g Hin).
    - cbn [In] in Hin. destruct Hin as [<-|[]].
      unfold hnew. apply phshape_onot9. reflexivity. }
  assert (HA : tag_edges A)
    by exact (tag_edges_phfreeP A HAfree).
  assert (HRE : tag_edges R)
    by (unfold R; exact (tag_edges_map_adj4p sg' rest0 HR)).
  assert (HRH : shape_head_free R)
    by (unfold R; exact (shape_head_map_adj4p
      sg' rest0 HRHead)).
  assert (HSfree : phfreeP [(8,2,1)%N; bend]).
  { unfold phfreeP. intros g Hin.
    repeat (destruct Hin as [<-|Hin]); try destruct Hin;
      first [apply phshape_c1
            |unfold bend; apply phshape_onot9; reflexivity]. }
  assert (HSE : tag_edges S).
  { unfold S. apply tag_edges_shape_free_app_probe.
    - exact HSfree.
    - exact HPostHead.
    - exact HPost. }
  assert (HAR : tag_edges (A ++ R)).
  { apply tag_edges_shape_free_app_probe.
    - exact HAfree.
    - exact HRH.
    - exact HRE. }
  assert (HARS : tag_edges ((A ++ R) ++ S)).
  { apply tag_edges_app_join; [exact HAR|exact HSE|].
    unfold edge_join, S.
    destruct (A ++ R) as [|x xs]; [exact I|].
    apply edge_pair_to_spc. }
  assert (EPhaseTail : phase_form rem ++ Tail = (A ++ R) ++ S).
  { unfold Tail, A. repeat rewrite app_assoc. reflexivity. }
  assert (EOut :
    (phase_form rem ++ (hnew :: R ++ [(8,2,1)%N])) ++
      bend :: post = (A ++ R) ++ S).
  { rewrite <- EPhaseTail. unfold Tail, S.
    rewrite <- app_assoc. cbn [app].
    rewrite <- app_assoc. cbn [app]. reflexivity. }
  assert (HOutLayout :
    w' = rev left ++ (phase_form rem ++ Tail)).
  { rewrite Hw'. cbn [gO gZ gC]. fold hnew bend R.
    rewrite EOut, <- EPhaseTail. reflexivity. }
  assert (HMout : ph_margins sg'
      (rev left ++ (phase_form rem ++ Tail))).
  { rewrite <- HOutLayout. exact (lguard_margins sg' w' HGuard). }
  assert (HPTout : lin_ptags sg'
      (rev left ++ (phase_form rem ++ Tail)) = true).
  { rewrite <- HOutLayout. exact HPT. }
  rewrite HOutLayout.
  apply tag_edges_app_join; [exact HP| |].
  - rewrite EPhaseTail. exact HARS.
  - exact (phase_form_edge_join_guarded sg' (rev left) rem Tail
      Hr HMout HPTout).
Qed.
Lemma lin_bulk_stable_guarded :
  forall sg w j p t w' sg' nh rem emit,
  stable_guard sg w ->
  is_spc (nth O w d0) = false ->
  detect_phase w j = Some p ->
  lin_bulk sg w j p t = Some (w', sg', nh, rem, emit) ->
  lin_guard sg' w' = true ->
  stable_guard sg' w'.
Proof.
  intros sg w j p t w' sg' nh rem emit
    (HR & HE & HW & HS & HK & HP) H0 HD HB HGuard.
  assert (HR' : front_repr sg' w').
  { exact (lin_bulk_front_repr
      sg w j p t w' sg' nh rem emit HR H0 HD HB). }
  destruct (lin_bulk_tables
    sg w j p t w' sg' nh rem emit HW HS HK HP H0 HD HB)
    as (HW' & HS' & HK' & HP').
  assert (HE' : tag_edges w').
  { destruct (Nat.eqb (N.to_nat ((p+t)/28)) O) eqn:Hfull.
    - exact (lin_bulk_partial_edges_guarded
        sg w j p t w' sg' nh rem emit HE HGuard (proj2 HR')
        HD Hfull HB).
    - destruct (lin_bulk_checks sg w j p t _ HB)
        as (gb & EW & EK & EL & _ & EE).
      destruct (site_layout w j p gb HD EW EE)
        as (HL & HLen & HPost).
      destruct (detect_phase_form w j p HD) as (Hp & _).
      exact (lin_bulk_cross_edges_guarded
        sg w j p t w' sg' nh rem emit gb (firstn j w)
        (skipn (S (j + phase_len p)) w)
        HE HGuard (proj2 HR') H0 HL HLen HPost EK Hp Hfull HB). }
  unfold stable_guard.
  split; [exact HR'|]. repeat split; assumption.
Qed.
Open Scope N_scope.
Open Scope sym.
Opaque LROUND_FUEL LROUND_CHUNKS
       FLAT_ROUND_FUEL CFUEL TRIES.
Definition frame_pos (fr : lsc_frame) : Prop :=
  (3 <= lsCur fr)%nat.
Lemma stable_altb : forall sg w,
  stable_guard sg w ->
  forall s, In s sg -> altb (sBody s) = true.
Proof.
  intros sg w (_ & _ & _ & HS & _ & _) s Hin.
  change (segalt (sBody s) = true).
  exact (sg_shape_alt sg HS s Hin).
Qed.
Lemma lin_bulk_take_le : forall sg w cur tg p tk,
  (lin_bulk_take sg w cur tg p tk <= tk)%N.
Proof.
  intros sg w cur tg p tk. unfold lin_bulk_take. cbv zeta.
  destruct (Nat.eqb
    (Nat.min (N.to_nat ((p + tk) / 28))
      (lin_count_clean sg w (tg - 1)
        (Nat.min
          (Nat.div2
            (fmapw sg w 0 0 tg - fmapw sg w 0 0 cur - 2))
          (N.to_nat ((p + tk) / 28))))) 0);
    apply N.le_min_l.
Qed.
Close Scope sym.
Lemma lin_bottom_take_le : forall cols s3 f tk take,
  lin_bottom_take cols s3 f tk = Some take ->
  (take <= tk)%N.
Proof.
  intros cols s3 f tk take H.
  unfold lin_bottom_take in H.
  destruct (lin_bottom_form s3) as [[p fc]|] eqn:EForm;
    [|discriminate].
  destruct (lin_bottom_level cols) as [hi|] eqn:ELevel;
    [|discriminate].
  destruct ((f =? 4) && (1 <=? tk) &&
            (FLOOR <=? hi) && (2 <=? fc))%N;
    [|discriminate].
  injection H as <-.
  rewrite Nat2N.inj_min, N2Nat.id. apply N.le_min_l.
Qed.
Open Scope sym.
Lemma prefix_replace_head_nonspc : forall w w' n tail,
  (1 <= n)%nat ->
  (n <= length w)%nat ->
  w' = firstn n w ++ tail ->
  is_spc (nth O w d0) = false ->
  is_spc (nth O w' d0) = false.
Proof.
  intros [|g w] w' n tail Hn Hlen -> H0.
  - cbn [length] in Hlen. lia.
  - destruct n; [lia|]. cbn [firstn app nth] in H0 |- *. exact H0.
Qed.
Lemma setsfx_head_nonspc : forall base w lw,
  (1 <= base)%nat ->
  (base <= length w)%nat ->
  is_spc (nth O w d0) = false ->
  is_spc
    (nth O (setsfx base w lw) d0) = false.
Proof.
  intros base w lw Hpos Hbase H0.
  rewrite (setsfx_app base w lw Hbase).
  destruct base as [|base]; [lia|].
  destruct w as [|g w]; [cbn [length] in Hbase; lia|].
  cbn [firstn app nth] in H0 |- *. exact H0.
Qed.
Lemma lin_bulk_head_pos :
  forall sg w j p t w' sg' nh rem emit,
  (1 <= j)%nat ->
  is_spc (nth O w d0) = false ->
  detect_phase w j = Some p ->
  lin_bulk sg w j p t = Some (w', sg', nh, rem, emit) ->
  (1 <= nh)%nat /\
  is_spc (nth O w' d0) = false.
Proof.
  intros sg w j p t w' sg' nh rem emit HjPos H0 HD HB.
  destruct (Nat.eqb (N.to_nat ((p+t)/28)) O) eqn:Hfull.
  - destruct (lin_bulk_checks sg w j p t _ HB)
      as (gb & EW & EK & EL & _ & EE).
    destruct (site_layout w j p gb HD EW EE)
      as (HL & HLen & HPost).
    destruct (detect_phase_form w j p HD) as (Hp & _).
    destruct (lin_bulk_partial_out
      sg w j p t w' sg' nh rem emit gb Hfull HB EW)
      as (Esg & Enh & Erem & Eemit & Ew').
    destruct (lvl_big_shape gb EL) as (cgb & Egb).
    set (PRE := firstn j w) in *.
    set (RST := skipn (S (j + phase_len p)) w) in *.
    assert (Hplen : length (phase_form p) = phase_len p)
      by (apply phase_form_len; exact Hp).
    assert (EW2 : w' = PRE ++ phase_form ((p+t) mod 28)
        ++ (4,2,(cgb + DBu ((p+t) mod 28))
                      - DBu p)%N :: RST).
    { rewrite Ew'. rewrite HL at 1. rewrite Egb.
      rewrite <- HLen, <- Hplen. apply subst_site. }
    assert (HjLen : (j <= length w)%nat).
    { unfold PRE in HLen. rewrite length_firstn in HLen. lia. }
    split; [rewrite Enh; exact HjPos|].
    eapply prefix_replace_head_nonspc;
      [exact HjPos|exact HjLen|exact EW2|exact H0].
  - destruct (lin_bulk_checks sg w j p t _ HB)
      as (gb & EW & EK & EL & _ & EE).
    destruct (site_layout w j p gb HD EW EE)
      as (HL & HLen & HPost).
    destruct (detect_phase_form w j p HD) as (Hp & _).
    destruct (lin_bulk_pieces sg w j p t w' sg' nh rem emit
      gb (firstn j w) (skipn (S (j + phase_len p)) w)
      HL HLen HPost EK Hp H0 Hfull HB)
      as (left & used & sp & hd & rest0 & cgb & EC & EM & Hpre & Hnh
          & Hgb & Hfloor & Hrem & Hemit & Hph & Hout).
    assert (Hspc : is_spc sp = true).
    { pose proof (gclimb_last_spc _ _ _ _ _ _ _ _ EC) as H.
      rewrite EM in H. exact H. }
    assert (Hleft : rev left <> []).
    { intro E. pose proof H0 as Hbad.
      rewrite HL, Hpre, E in Hbad. cbn [app nth] in Hbad. congruence. }
    split.
    + rewrite <- Hnh. destruct left; [contradiction|].
      cbn [length]. lia.
    + destruct (rev left) as [|a ltail] eqn:Eleft; [contradiction|].
      pose proof H0 as Hhead.
      rewrite HL, Hpre in Hhead.
      rewrite Hout. cbn [app nth] in Hhead |- *. exact Hhead.
Qed.
Lemma frame_pos_advance : forall fr take,
  frame_pos fr -> frame_pos (lin_sched_advance fr take).
Proof.
  intros [cur tk slot gap] take H.
  exact H.
Qed.
Lemma scheduled_work_inv :
  forall fr rest sg w f sg' w' f',
  scheduled_work (fr :: rest) sg w f sg' w' f' ->
  exists sg1 w1 f1,
    scheduled_frame fr sg w f sg1 w1 f1 /\
    scheduled_work rest sg1 w1 f1 sg' w' f'.
Proof.
  intros fr rest sg w f sg' w' f' H.
  inversion H; subst.
  eauto.
Qed.
Definition lin_bulk_candidate
    (sg : list seg) (w : word)
    (cur : nat) (tk : N) (tg : nat) (s3 : word)
  : option (word * list seg * nat * N * N * N * N) :=
  if Nat.ltb (cur + 2) tg then
    match detect_phase s3 O with
    | Some pk =>
        let take := lin_bulk_take sg w cur tg pk tk in
        if (THRESH <=? take)%N then
          match lin_bulk sg w tg pk take with
          | Some (w2, sg2, nh, rem, emit) =>
              Some (w2, sg2, nh, rem, emit, take, pk)
          | None => None
          end
        else None
    | None => None
    end
  else None.
Lemma lin_bulk_candidate_some :
  forall sg w cur tk tg s3 w2 sg2 nh rem emit take pk,
  lin_bulk_candidate sg w cur tk tg s3 =
    Some (w2, sg2, nh, rem, emit, take, pk) ->
  Nat.ltb (cur + 2) tg = true /\
  detect_phase s3 O = Some pk /\
  take = lin_bulk_take sg w cur tg pk tk /\
  (THRESH <=? take)%N = true /\
  lin_bulk sg w tg pk take = Some (w2, sg2, nh, rem, emit).
Proof.
  intros sg w cur tk tg s3 w2 sg2 nh rem emit take pk H.
  unfold lin_bulk_candidate in H.
  destruct (Nat.ltb (cur + 2) tg) eqn:HLt; [|discriminate].
  destruct (detect_phase s3 O) as [pk0|] eqn:HPhase;
    [|discriminate].
  remember (lin_bulk_take sg w cur tg pk0 tk) as take0 eqn:HTake.
  destruct (THRESH <=? take0)%N eqn:HThresh;
    [|discriminate].
  destruct (lin_bulk sg w tg pk0 take0)
    as [[[[[w0 sg0] nh0] rem0] emit0]|] eqn:HBulk; [|discriminate].
  injection H as <- <- <- <- <- <- <-.
  repeat split; try assumption.
Qed.
Theorem lin_casc_safe_at_work :
  forall fu sg ps w f st w' sg' ps' f',
  stable_guard sg w ->
  lin_guard sg w = true ->
  is_spc (nth O w d0) = false ->
  Forall frame_pos st ->
  lin_casc_safe_at fu sg ps w f st = Some (w', sg', ps', f') ->
  scheduled_work st sg w f sg' w' f' /\
  stable_guard sg' w' /\
  lin_guard sg' w' = true /\
  is_spc (nth O w' d0) = false.
Proof.
  induction fu as [|fu IH];
    intros sg ps w f st w' sg' ps' f' HG HGuard HHead HFrames HRun.
  - cbn [lin_casc_safe_at] in HRun. discriminate.
  - destruct st as [|fr rest].
    + cbn [lin_casc_safe_at] in HRun.
      injection HRun as <- <- <- <-.
      split; [constructor|].
      split; [exact HG|]. split; assumption.
    + inversion HFrames as [|fr0 rest0 HFr HRest]; subst fr0 rest0.
      cbn [lin_casc_safe_at] in HRun.
      destruct (lsTicks fr =? 0)%N eqn:ETicks.
      * destruct (IH sg ps w f rest w' sg' ps' f'
          HG HGuard HHead HRest HRun)
          as (HWork & HG' & HGuard' & HHead').
        split.
        -- eapply scheduled_work_zero;
             [apply N.eqb_eq; exact ETicks|exact HWork].
        -- split; [exact HG'|]. split; assumption.
      * destruct (seek (skipn (lsCur fr) w))
          as [cols s] eqn:HSeek.
        destruct s as [|g t]; [discriminate|].
        cbn [fst snd] in HRun.
        pose proof (LineageGuard_seek_split
          (skipn (lsCur fr) w)) as HSplit.
        rewrite HSeek in HSplit. cbn [fst snd] in HSplit.
        assert (HCurLen : (lsCur fr <= length w)%nat).
        { pose proof (f_equal (@length bg) HSplit) as HLen.
          rewrite length_skipn, length_app in HLen.
          cbn [length] in HLen. lia. }
        unfold frame_pos in HFr.
        pose proof HG as HG0.
        destruct HG as ((HOk & HPT) & HEdges & HWf & HShape & HKeys & HPos).
        set (tg := (lsCur fr + length cols)%nat) in *.
        destruct (lin_bottom_take cols (g :: t) f
          (lsTicks fr)) as [take|] eqn:HBottom.
        -- set (base := (lsCur fr - 2)%nat) in *.
           set (lc := (lsCur fr - base)%nat) in *.
           destruct (lin_bottom_sched_zrun (N.to_nat take) lc sg
             (skipn base w) f (lsGap fr) (lsSlot fr))
             as [[lw2 f2]|] eqn:HZRun; [|discriminate].
           set (w2 := setsfx base w lw2) in *.
           destruct (relocate_all sg ps w2) as [ps2|] eqn:HRel;
             [|discriminate].
           destruct (lin_guard_at sg ps2 w2) eqn:HAt;
             [|discriminate].
           assert (HCurEq : lsCur fr = (base + lc)%nat).
           { unfold base, lc. lia. }
           assert (HBaseLen : (base <= length w)%nat).
           { unfold base. lia. }
           assert (HLcLen : (lc <= length (skipn base w))%nat).
           { rewrite length_skipn. unfold base, lc. lia. }
           assert (HTake : (take <= lsTicks fr)%N)
             by (eapply lin_bottom_take_le; exact HBottom).
           assert (HG2 : stable_guard sg w2).
           { unfold w2. eapply lin_bottom_global_stable.
             + exact HG0.
             + exact HCurEq.
             + unfold base. reflexivity.
             + exact HBaseLen.
             + exact HLcLen.
             + exact HZRun. }
           assert (HGuard2 : lin_guard sg w2 = true).
           { eapply lin_guard_at_sound;
               [exact (proj1 (proj1 HG2))|exact HAt]. }
           assert (HHead2 :
             is_spc (nth O w2 d0) = false).
           { unfold w2. eapply setsfx_head_nonspc.
             + unfold base. lia.
             + exact HBaseLen.
             + exact HHead. }
           assert (HFrames2 : Forall frame_pos
             (lin_sched_advance fr take :: rest)).
           { constructor.
             + apply frame_pos_advance. unfold frame_pos. exact HFr.
             + exact HRest. }
           destruct (IH sg ps2 w2 f2
             (lin_sched_advance fr take :: rest)
             w' sg' ps' f' HG2 HGuard2 HHead2 HFrames2 HRun)
             as (HWork & HG' & HGuard' & HHead').
           destruct (scheduled_work_inv _ _ _ _ _ _ _ _ HWork)
             as (sg1 & w1 & f1 & HAdvance & HRestWork).
           assert (HTrans : scheduled_transition
             fr take sg w f sg w2 f2).
           { eapply lin_bottom_global_scheduled_transition
               with (base := base) (lc := lc) (lw' := lw2).
             + exact HWf.
             + exact HCurEq.
             + exact HBaseLen.
             + exact HLcLen.
             + exact HTake.
             + exact HZRun.
             + unfold w2. reflexivity. }
           assert (HFrame : scheduled_frame fr
             sg w f sg1 w1 f1).
           { eapply scheduled_transition_frame;
               [exact HTrans|exact HAdvance]. }
           split.
           { econstructor; [exact HFrame|exact HRestWork]. }
           split; [exact HG'|]. split; assumption.
        -- fold (lin_bulk_candidate sg w (lsCur fr)
             (lsTicks fr) tg (g :: t)) in HRun.
           destruct (lin_bulk_candidate sg w (lsCur fr)
             (lsTicks fr) tg (g :: t)) as [bc|] eqn:HBC.
           ++ destruct bc as [[[[[[w2 sg2] nh] rem] emit] take] pk].
              destruct (lin_bulk_candidate_some
                sg w (lsCur fr) (lsTicks fr) tg (g :: t)
                w2 sg2 nh rem emit take pk HBC)
                as (HLt & HPhase & HTakeEq & HThresh & HBulk).
              destruct (negb (lin_sched_bulk_safe fr
                (lin_flen sg cols) pk take)) eqn:HSafe0;
                [discriminate|].
              apply negb_false_iff in HSafe0.
              destruct (lin_at_safe sg2 w2 nh) as [w3|]
                eqn:HAtSafe; [|discriminate].
              pose proof (lin_at_safe_some
                sg2 w2 nh w3 HAtSafe) as ->.
              destruct (locate_all sg2 w2) as [ps2|] eqn:HLocate;
                [|discriminate].
              destruct (lin_guard_at sg2 ps2 w2) eqn:HAt;
                [|discriminate].
              assert (HD : detect_phase w tg = Some pk).
              { rewrite detect_phase_skipn.
                unfold tg.
                rewrite (skipn_seek_at
                  w (lsCur fr) cols (g :: t) HSeek).
                exact HPhase. }
              assert (HTgPos : (1 <= tg)%nat).
              { apply PeanoNat.Nat.ltb_lt in HLt. lia. }
              pose proof (lin_bulk_front_repr
                sg w tg pk take w2 sg2 nh rem emit
                (conj HOk HPT) HHead HD HBulk) as HFront2.
              assert (HGuard2 : lin_guard sg2 w2 = true).
              { eapply lin_guard_at_sound;
                  [exact (proj1 HFront2)|exact HAt]. }
              assert (HG2 : stable_guard sg2 w2).
              { eapply lin_bulk_stable_guarded;
                  eauto. }
              destruct (lin_bulk_head_pos
                sg w tg pk take w2 sg2 nh rem emit
                HTgPos HHead HD HBulk) as (HNhPos & HHead2).
              assert (HTake : (take <= lsTicks fr)%N).
              { rewrite HTakeEq. apply lin_bulk_take_le. }
              assert (HThreshLe : (THRESH <= take)%N)
                by (apply N.leb_le; exact HThresh).
              assert (HPartial :
                Nat.eqb (N.to_nat ((pk + take) / 28)) O = true -> nh = tg).
              { intros HFull.
                destruct (lin_bulk_checks
                  sg w tg pk take _ HBulk)
                  as (gb & HWat & _ & _ & _ & _).
                destruct (lin_bulk_partial_out
                  sg w tg pk take w2 sg2 nh rem emit gb
                  HFull HBulk HWat) as (_ & Hnh & _ & _ & _).
                exact Hnh. }
              assert (HCross :
                Nat.eqb (N.to_nat ((pk + take) / 28)) O = false ->
                (lsCur fr <= nh)%nat).
              { intros HFull.
                eapply lin_bulk_take_lands_after_cursor.
                + exact HWf.
                + exact HOk.
                + exact (stable_altb sg w HG0).
                + exact HHead.
                + exact HSeek.
                + reflexivity.
                + exact HD.
                + exact HTakeEq.
                + exact HThreshLe.
                + exact HFull.
                + exact HBulk.
                + exact (proj1 (proj2 (proj2 HG2))). }
              assert (HChildPos : frame_pos
                (lin_sched_child nh rem emit pk take)).
              { unfold frame_pos, lin_sched_child.
                cbn [lsCur].
                destruct (Nat.eqb (N.to_nat ((pk + take) / 28)) O)
                  eqn:HFull.
                + rewrite (HPartial eq_refl). lia.
                + pose proof (HCross eq_refl). lia. }
              assert (HFrames2 : Forall frame_pos
                (lin_sched_child nh rem emit pk take ::
                 lin_sched_advance fr take :: rest)).
              { constructor; [exact HChildPos|]. constructor.
                + apply frame_pos_advance. unfold frame_pos. exact HFr.
                + exact HRest. }
              destruct (IH sg2 ps2 w2 f
                (lin_sched_child nh rem emit pk take ::
                 lin_sched_advance fr take :: rest)
                w' sg' ps' f' HG2 HGuard2 HHead2 HFrames2 HRun)
                as (HWork & HG' & HGuard' & HHead').
              destruct (scheduled_work_inv _ _ _ _ _ _ _ _ HWork)
                as (sgc & wc & fc & HChild & HAfterChild).
              destruct (scheduled_work_inv _ _ _ _ _ _ _ _ HAfterChild)
                as (sga & wa & fa & HAdvance & HRestWork).
              assert (HTrans : scheduled_transition
                fr take sg w f sgc wc fc).
              { destruct (Nat.eqb (N.to_nat ((pk + take) / 28)) O)
                  eqn:HFull.
                + eapply lin_bulk_partial_scheduled_transition.
                  * exact HWf.
                  * exact HSeek.
                  * reflexivity.
                  * exact HD.
                  * exact HFull.
                  * exact HBulk.
                  * exact HTake.
                  * exact HChild.
                + eapply lin_bulk_scheduled_transition.
                  * exact HWf.
                  * exact HOk.
                  * exact (stable_altb sg w HG0).
                  * exact HHead.
                  * exact HSeek.
                  * reflexivity.
                  * exact HD.
                  * exact HFull.
                  * exact HBulk.
                  * exact (proj1 (proj2 (proj2 HG2))).
                  * exact HTake.
                  * exact HSafe0.
                  * exact (HCross eq_refl).
                  * exact HChild. }
              assert (HFrame : scheduled_frame fr
                sg w f sga wa fa).
              { eapply scheduled_transition_frame;
                  [exact HTrans|exact HAdvance]. }
              split.
              { econstructor; [exact HFrame|exact HRestWork]. }
              split; [exact HG'|]. split; assumption.
           ++ destruct (lin_dtick_after_seek cols (g :: t) f)
                as [[[renewed sfx] f2]|] eqn:HStep; [|discriminate].
              assert (HM : ph_margins sg w)
                by (exact (lguard_margins sg w HGuard)).
              assert (HN : ph_nbrs sg w)
                by (exact (margins_edges_nbrs sg w HM HEdges)).
              assert (HN1 : nbrs1z sg w)
                by (exact (nbrs_nbrs1z sg w HN)).
              assert (HNCur : nbrs1z sg
                (skipn (lsCur fr) w)).
              { apply (nbrs1z_app_r sg
                  (firstn (lsCur fr) w)
                  (skipn (lsCur fr) w)).
                rewrite firstn_skipn. exact HN1. }
              assert (HNS : nbrs1z sg (g :: t)).
              { apply (nbrs1z_app_r sg cols (g :: t)).
                rewrite <- HSplit. exact HNCur. }
              assert (HNotLast : forall t',
                g :: t = (4%N,3%N,1%N) :: t' ->
                ph_notlast sg cols).
              { intros t' E. injection E as Eg Et. subst g t.
                pose proof (nbrs1z_seek_notlast sg
                  (skipn (lsCur fr) w) (4%N,3%N,1%N) t'
                  HNCur ltac:(rewrite HSeek; reflexivity)
                  ltac:(unfold is_spc; reflexivity)
                  ltac:(cbn [gZ]; lia)) as H.
                rewrite HSeek in H. cbn [fst] in H. exact H. }
              assert (HNonPh : forall gh u,
                g :: t = gh :: u -> ph sg gh = false).
              { intros gh u E. injection E as <- <-.
                exact (nbrs1z_seek_snd_head sg
                  (skipn (lsCur fr) w) g t HNCur
                  ltac:(rewrite HSeek; reflexivity)). }
              destruct renewed eqn:ERenew;
                [ destruct (negb (Nat.leb (lsGap fr + 2)
                    (lin_flen sg cols))) eqn:HGap;
                    try discriminate;
                  apply negb_false_iff in HGap;
                  assert (HRenew : true = true ->
                    (lsGap fr + 2 <=
                      lin_flen sg cols)%nat)
                    by (intros _; apply PeanoNat.Nat.leb_le; exact HGap)
                | assert (HRenew : false = true ->
                    (lsGap fr + 2 <=
                      lin_flen sg cols)%nat)
                    by discriminate ].
              all: destruct (if Nat.eqb (lsCur fr) O
                    then Some sfx
                    else lin_join_safe sg
                      (firstn (lsCur fr) w) sfx)
                  as [w2|] eqn:HJoin; [|discriminate].
              all: destruct (if lin_same_length w w2
                    then Some ps else relocate_all sg ps w2)
                  as [ps2|] eqn:HRel; [|discriminate].
              all: destruct (lin_guard_at sg ps2 w2) eqn:HAt;
                  [|discriminate].
              all: rewrite lin_sched_advance_one_eq in HRun.
              all: assert (HG2 : stable_guard sg w2)
                by (eapply lin_direct_stable; eauto).
              all: assert (HGuard2 : lin_guard sg w2 = true)
                by (eapply lin_guard_at_sound;
                    [exact (proj1 (proj1 HG2))|exact HAt]).
              all: assert (EW2 :
                w2 = firstn (lsCur fr) w ++ sfx)
                by (destruct (Nat.eqb (lsCur fr) O) eqn:HCur0;
                    [apply PeanoNat.Nat.eqb_eq in HCur0; lia
                    | exact (lin_join_safe_some
                        sg (firstn (lsCur fr) w) sfx w2 HJoin)]).
              all: assert (HHead2 :
                is_spc (nth O w2 d0) = false)
                by (exact (prefix_replace_head_nonspc
                    w w2 (lsCur fr) sfx
                    ltac:(lia) HCurLen EW2 HHead)).
              all: assert (HFrames2 : Forall frame_pos
                (lin_sched_advance fr 1 :: rest))
                by (constructor;
                    [apply frame_pos_advance; unfold frame_pos; exact HFr
                    |exact HRest]).
              all: destruct (IH sg ps2 w2 f2
                (lin_sched_advance fr 1 :: rest)
                w' sg' ps' f' HG2 HGuard2 HHead2 HFrames2 HRun)
                as (HWork & HG' & HGuard' & HHead').
              all: destruct (scheduled_work_inv _ _ _ _ _ _ _ _ HWork)
                as (sg1 & w1 & f1 & HAdvance & HRestWork).
              all: assert (HTrans : scheduled_transition
                fr 1 sg w f sg w2 f2)
                by (eapply lin_direct_scheduled_transition;
                    [ exact HWf
                    | exact HKeys
                    | exact (stable_guard_live sg w HG0)
                    | exact HCurLen
                    | apply N.eqb_neq; exact ETicks
                    | exact HSeek
                    | discriminate
                    | exact HNotLast
                    | exact HNS
                    | exact HNonPh
                    | exact HStep
                    | exact HRenew
                    | exact HJoin ]).
              all: assert (HFrame : scheduled_frame fr
                sg w f sg1 w1 f1)
                by (eapply scheduled_transition_frame;
                    [exact HTrans|exact HAdvance]).
              all: (split;
                [econstructor; [exact HFrame|exact HRestWork]
                |split; [exact HG'|]; split; assumption]).
Qed.
Open Scope N_scope.
Open Scope sym.
Opaque LROUND_FUEL LROUND_CHUNKS
       FLAT_ROUND_FUEL CFUEL TRIES.
Lemma delivery_master_sound : forall J pr s f s' f',
  delivery_trip s f s' f' ->
  forallb is_col pr = true -> (1 <= J)%N ->
  sound_impl
    (((2,2,J)::pr) ++ s) f
    (((2,2,J+1)::pr) ++ s') f'.
Proof.
  intros J pr s f s' f' (c & p & q & HF & EQ) Hpr HJ Hhalt.
  exact (std_transfer J pr s s' f f' c p q
    HF EQ Hpr HJ Hhalt).
Qed.
Lemma deliveries_master_sound : forall n J pr s f s' f',
  deliveries n s f s' f' ->
  forallb is_col pr = true -> (1 <= J)%N ->
  sound_impl
    (((2,2,J)::pr) ++ s) f
    (((2,2,J + N.of_nat n)::pr) ++ s') f'.
Proof.
  intros n J pr s f s' f' HD. revert J pr.
  induction HD as [s f s' f' E|n s f s1 f1 s2 f2 HT HR IH];
    intros J pr Hpr HJ.
  - change (J + 0)%N with (J + N.of_nat O)%N.
    rewrite N.add_0_r.
    unfold sound_impl.
    change
      (halts tmB (wconf [] 0
        (sdec (((2,2,J)::pr) ++ s') f')) ->
       halts tmB (wconf [] 0
        (sdec (((2,2,J)::pr) ++ s) f))).
    rewrite !sdec_app, E. exact (fun Hhalt => Hhalt).
  - replace (J + N.of_nat (S n))%N with ((J + 1) + N.of_nat n)%N
      by (rewrite Nat2N.inj_succ; lia).
    unfold sound_impl in *.
    intros Hhalt.
    eapply delivery_master_sound; [exact HT|exact Hpr|exact HJ|].
    exact (IH (J+1) pr Hpr ltac:(lia) Hhalt).
Qed.
Lemma schedule_trips_factor : forall rs w f out f',
  schedule_trips rs w f out f' ->
  exists out0 f0,
    schedule_deliveries rs w f out0 f0 /\
    sdec out0 f0 = sdec out f'.
Proof.
  intros rs w f out f' H. induction H.
  - exists w, f. split; [constructor|exact H].
  - destruct IHschedule_trips as (out0 & f0 & HRun & E).
    exists out0, f0. split; [econstructor; eassumption|exact E].
  - destruct IHschedule_trips as (out0 & f0 & HRun & E).
    exists out0, f0. split.
    + eapply schedule_deliveries_some; eassumption.
    + exact E.
Qed.
Open Scope N_scope.
Open Scope sym.
Opaque LROUND_FUEL LROUND_CHUNKS
       FLAT_ROUND_FUEL CFUEL TRIES.
Lemma phase_len_pos : forall p, (1 <= phase_len p)%nat.
Proof.
  intros p. unfold phase_len.
  destruct ((p mod 4 =? 3)%N); lia.
Qed.
Lemma firstn_length_bound : forall (A : Type) n (xs : list A),
  (length (firstn n xs) <= length xs)%nat.
Proof.
  intros A n. induction n as [|n IH]; intros [|x xs]; cbn; try lia.
  specialize (IH xs). lia.
Qed.
Lemma subst_at_twice_preserves_head : forall g tail i k rep j l rep',
  (1 <= i)%nat -> (1 <= j)%nat ->
  exists tail',
    subst_at i k rep
      (subst_at j l rep' (g :: tail)) = g :: tail'.
Proof.
  intros g tail [|i] k rep [|j] l rep' Hi Hj; try lia.
  unfold subst_at. cbn [firstn skipn app].
  eexists. reflexivity.
Qed.
Lemma lin_flat_master : forall sg J tail,
  lin_flat sg ((2,2,J) :: tail) =
    (2,2,J) :: lin_flat sg tail.
Proof. reflexivity. Qed.
Lemma flat_firstn_master_change : forall sg A B tail n rest,
  (1 <= n)%nat ->
  lin_flat sg (firstn n ((2,2,A) :: tail)) = (2,2,A) :: rest ->
  lin_flat sg (firstn n ((2,2,B) :: tail)) = (2,2,B) :: rest.
Proof.
  intros sg A B tail [|n] rest Hn H; [lia|].
  cbn [firstn] in H |- *. rewrite !lin_flat_master in H |- *.
  injection H as E. now rewrite E.
Qed.
Lemma flat_prefix_master_runway : forall sg J tail j PRE c cs,
  (1 <= j)%nat ->
  lin_flat sg (firstn j ((2,2,J) :: tail)) =
    PRE ++ runway (c :: cs) ->
  exists pr, PRE = (2,2,J) :: pr.
Proof.
  intros sg J tail [|j] [|a pr] c cs Hj E; [lia|lia| |].
  - cbn [firstn] in E. rewrite lin_flat_master in E.
    cbn [runway rung1 app] in E.
    discriminate.
  - cbn [firstn] in E. rewrite lin_flat_master in E.
    cbn [app] in E. injection E as Ea _. subst a.
    exists pr. reflexivity.
Qed.
Lemma flat_prefix_master_inv : forall sg J tail j rest,
  (1 <= j)%nat ->
  lin_flat sg (firstn j ((2,2,J) :: tail)) = (2,2,J) :: rest ->
  lin_flat sg (firstn (j-1)%nat tail) = rest.
Proof.
  intros sg J tail [|j] rest Hj E; [lia|].
  cbn [firstn Nat.sub] in E.
  injection E as E.
  replace (S j - 1)%nat with j by lia. exact E.
Qed.
Lemma lin_generation_prefix_master : forall J tail j,
  forallb is_col (firstn j ((2,2,J) :: tail)) = true ->
  forallb is_col (firstn (j-1)%nat tail) = true.
Proof.
  intros J tail [|j] H; [reflexivity|].
  cbn [firstn Nat.sub forallb is_col gO gZ] in H |- *.
  replace (j - 0)%nat with j by lia.
  exact H.
Qed.
Lemma lin_bulk_preserves_master :
  forall sg J tail j p tk w' sg' nh rem emit,
  (1 <= j)%nat ->
  detect_phase ((2,2,J) :: tail) j = Some p ->
  lin_bulk sg ((2,2,J) :: tail) j p tk =
    Some (w', sg', nh, rem, emit) ->
  exists tail', w' = (2,2,J) :: tail'.
Proof.
  intros sg J tail j p tk w' sg' nh rem emit Hj HD HB.
  assert (H0 : is_spc
      (nth O ((2,2,J)::tail) d0) = false) by reflexivity.
  destruct (Nat.eqb (N.to_nat ((p+tk)/28)) O) eqn:Hfull.
  - destruct (lin_bulk_checks
      sg ((2,2,J)::tail) j p tk _ HB)
      as (gb & EW & EK & EL & HF & EE).
    destruct (lin_bulk_partial_out
      sg ((2,2,J)::tail) j p tk w' sg' nh rem emit gb Hfull HB EW)
      as (Esg & Enh & Erem & Eemit & Ew').
    subst w'. eapply subst_at_twice_preserves_head; lia.
  - destruct (lin_bulk_checks
      sg ((2,2,J)::tail) j p tk _ HB)
      as (gb & EW & EK & EL & HF & EE).
    destruct (site_layout ((2,2,J)::tail) j p gb HD EW EE)
      as (HL & HLen & HPost).
    destruct (detect_phase_form ((2,2,J)::tail) j p HD)
      as (Hp & _).
    destruct (lin_bulk_pieces
      sg ((2,2,J)::tail) j p tk w' sg' nh rem emit gb
      (firstn j ((2,2,J)::tail))
      (skipn (S (j + phase_len p)) ((2,2,J)::tail))
      HL HLen HPost EK Hp H0 Hfull HB)
      as (left & used & sp & hd & rest0 & cgb & EC & EM & Hpre & Hnh
          & Hgb & Hfloor & Hrem & Hemit & Hph & Hout).
    assert (Hspc : is_spc sp = true).
    { pose proof (gclimb_last_spc _ _ _ _ _ _ _ _ EC) as H.
      rewrite EM in H. exact H. }
    destruct j as [|j]; [lia|]. cbn [firstn] in Hpre.
    assert (Hleft : rev left <> []).
    { intro E. rewrite E in Hpre. cbn [app] in Hpre.
      injection Hpre as Ehead _. subst sp. discriminate Hspc. }
    destruct (rev left) as [|a ltail] eqn:Eleft; [contradiction|].
    assert (Ea : a = (2,2,J)%N).
    { cbn [app] in Hpre.
      injection Hpre as Ea _. symmetry. exact Ea. }
    subst a. rewrite Hout. eexists. reflexivity.
Qed.
Lemma lin_bulk_master_stable :
  forall sg ps J tail j p tk w1 sg1 nh rem emit,
  stable_guard sg ((2,2,J) :: tail) ->
  (1 <= j)%nat ->
  detect_phase ((2,2,J) :: tail) j = Some p ->
  lin_bulk sg ((2,2,J) :: tail) j p tk =
    Some (w1, sg1, nh, rem, emit) ->
  lin_guard_at sg1 ps
    (subst_at O 1 [(2,2,J+tk)] w1) = true ->
  stable_guard sg1
      (subst_at O 1 [(2,2,J+tk)] w1) /\
  lin_guard sg1
      (subst_at O 1 [(2,2,J+tk)] w1) = true /\
  is_spc
      (nth O (subst_at O 1 [(2,2,J+tk)] w1) d0) = false /\
  (1 <= nh)%nat.
Proof.
  intros sg ps J tail j p tk w1 sg1 nh rem emit
    HG Hj HD HB HAt.
  destruct (lin_bulk_preserves_master
    sg J tail j p tk w1 sg1 nh rem emit Hj HD HB)
    as (tail1 & Ew1).
  assert (HHead : is_spc
      (nth O ((2,2,J)::tail) d0) = false) by reflexivity.
  assert (HFront1 : front_repr sg1 w1).
  { exact (lin_bulk_front_repr
      sg ((2,2,J)::tail) j p tk w1 sg1 nh rem emit
      (proj1 HG) HHead HD HB). }
  assert (EWM : subst_at O 1 [(2,2,J+tk)] w1 =
      (2,2,J+tk) :: tail1).
  { rewrite Ew1. reflexivity. }
  assert (HFrontM : front_repr sg1
      (subst_at O 1 [(2,2,J+tk)] w1)).
  { rewrite EWM.
    exact (front_repr_master_change_probe
      sg1 J (J+tk) tail1 ltac:(rewrite <- Ew1; exact HFront1)). }
  assert (HGuardM : lin_guard sg1
      (subst_at O 1 [(2,2,J+tk)] w1) = true).
  { eapply lin_guard_at_sound;
      [exact (proj1 HFrontM)|exact HAt]. }
  assert (HGuard1 : lin_guard sg1 w1 = true).
  { rewrite Ew1. apply lguard_of_margins.
    rewrite EWM in HGuardM.
    exact (margins_master_change sg1 (J+tk) J tail1
      (lguard_margins sg1 ((2,2,J+tk)::tail1) HGuardM)). }
  assert (HG1 : stable_guard sg1 w1).
  { eapply lin_bulk_stable_guarded;
      [exact HG|exact HHead|exact HD|exact HB|exact HGuard1]. }
  assert (HGM : stable_guard sg1
      (subst_at O 1 [(2,2,J+tk)] w1)).
  { rewrite EWM.
    exact (stable_guard_master_change_probe
      sg1 J (J+tk) tail1 ltac:(rewrite <- Ew1; exact HG1)). }
  destruct (lin_bulk_head_pos
    sg ((2,2,J)::tail) j p tk w1 sg1 nh rem emit
    Hj HHead HD HB) as (Hnh & _).
  split; [exact HGM|]. split; [exact HGuardM|].
  split; [rewrite EWM; reflexivity|exact Hnh].
Qed.
Lemma lin_bulk_child_frame_data :
  forall sg w j p tk w1 sg1 nh rem emit gb pre post,
  sg_wf sg -> lin_ok sg w = true ->
  (forall s, In s sg -> altb (sBody s) = true) ->
  is_spc (nth O w d0) = false ->
  w = pre ++ phase_form p ++ gb :: post ->
  length pre = j -> post <> [] -> keyi sg gb = None ->
  (p < 28)%N ->
  Nat.eqb (N.to_nat ((p+tk)/28)) O = false ->
  lin_bulk sg w j p tk = Some (w1, sg1, nh, rem, emit) ->
  sg_wf sg1 ->
  exists PRE POST c cs b,
    lin_flat sg w =
      site
        (PRE ++ runway (c :: cs)) p
        (b + DBu p) POST /\
    lin_flat sg1 w1 =
      site PRE rem (c - 3 + DBu rem)
        (crossed_post cs b POST) /\
    fmapw sg w O O j =
      length (PRE ++ runway (c :: cs)) /\
    length (c :: cs) = N.to_nat ((p+tk)/28) /\
    Forall (fun x => (FLOOR + 3 <= x)%N) (c :: cs) /\
    POST <> [] /\
    (FLOOR <= b)%N /\
    rem = ((p+tk) mod 28)%N /\
    emit = (marks (p+tk) - marks p)%N /\
    (rem < 28)%N /\
    schedule_frame_view
      (lin_sched_child nh rem emit p tk)
      (lin_flat sg1
        (skipn (nh + phase_len rem)%nat w1))
      (bulk_schedule p rem cs b)
      [(4,2,c - 3 + DBu rem)%N] POST.
Proof.
  intros sg w j p tk w1 sg1 nh rem emit gb pre post
    HW HOk HAlt HHead HLayout HJ HPost HKey Hp HFull HB HW1.
  destruct (lin_bulk_child_layout
    sg w j p tk w1 sg1 nh rem emit gb pre post
    HW HOk HAlt HHead HLayout HJ HPost HKey Hp HFull HB HW1)
    as (PRE & POST & c & cs & b & HIn & HOut & HCoord & HCoord' &
        HLevels & HSafe & HPOST & Hb & HRem & HEmit & HRem28 & HSuffix).
  exists PRE, POST, c, cs, b.
  split; [exact HIn|]. split; [exact HOut|]. split; [exact HCoord|].
  split; [exact HLevels|]. split; [exact HSafe|]. split; [exact HPOST|].
  split; [exact Hb|]. split; [exact HRem|]. split; [exact HEmit|].
  split; [exact HRem28|].
  unfold schedule_frame_view, lin_sched_child.
  cbv beta zeta. cbn [lsSlot lsTicks lsGap].
  repeat split.
  - unfold lin_sched_slot. lia.
  - rewrite (bulk_schedule_length p rem cs b Hp HRem28).
    assert (HQ : N.of_nat (S (length cs)) = ((p+tk)/28)%N).
    { cbn [length] in HLevels. rewrite HLevels, N2Nat.id. reflexivity. }
    pose proof (N.div_mod' (p+tk) 28) as HDiv.
    assert (ESpan :
      (28 * N.of_nat (S (length cs)) + rem = p+tk)%N) by lia.
    rewrite ESpan, <- HEmit. reflexivity.
  - exact (bulk_schedule_shape p rem cs b Hp HRem28).
  - unfold delivery_cols, is_col, is_cmf.
    cbn [forallb gO gZ gC].
    destruct ((c - 3 + DBu rem =? 1)%N); reflexivity.
  - rewrite bulk_schedule_stock, HSuffix.
    unfold crossed_post.
    rewrite app_nil_r. repeat rewrite <- app_assoc. reflexivity.
  - rewrite bulk_schedule_stock.
    unfold crossed_post.
    rewrite !length_app, length_runway, map_length.
    cbn [rung1 length].
    change (S (length cs) = N.to_nat ((p+tk)/28)) in HLevels.
    lia.
Qed.
Lemma lin_bulk_master_scheduled_sound_full :
  forall sg J tail f j p tk w1 sg1 nh rem emit sg2 w2 f2,
  stable_guard sg ((2,2,J) :: tail) ->
  (1 <= J)%N -> (1 <= j)%nat ->
  forallb is_col (firstn j ((2,2,J) :: tail)) = true ->
  detect_phase ((2,2,J) :: tail) j = Some p ->
  Nat.eqb (N.to_nat ((p+tk)/28)) O = false ->
  lin_bulk sg ((2,2,J) :: tail) j p tk =
    Some (w1, sg1, nh, rem, emit) ->
  scheduled_frame
    (lin_sched_child nh rem emit p tk)
    sg1 (subst_at O 1 [(2,2,J+tk)] w1) f sg2 w2 f2 ->
  sound_impl
    (lin_flat sg ((2,2,J) :: tail)) f
    (lin_flat sg2 w2) f2.
Proof.
  intros sg J tail f j p tk w1 sg1 nh rem emit sg2 w2 f2
    HG HJ Hj HCols HD HFull HB HFrame.
  pose proof HG as HG0.
  destruct HG as ((HOk & HPT) & HEdges & HW & HShape & HKeys & HPos).
  assert (HHead : is_spc
      (nth O ((2,2,J)::tail) d0) = false) by reflexivity.
  assert (HAlt : forall s, In s sg ->
      altb (sBody s) = true)
    by (exact (stable_altb sg ((2,2,J)::tail) HG0)).
  destruct (lin_bulk_checks
    sg ((2,2,J)::tail) j p tk _ HB)
    as (gb & EW & HKey & HLevel & HFloor & HEnd).
  destruct (site_layout ((2,2,J)::tail) j p gb HD EW HEnd)
    as (HLayout & HJRaw & HPost).
  destruct (detect_phase_form ((2,2,J)::tail) j p HD)
    as (Hp & HPhase).
  destruct (lin_bulk_tables
    sg ((2,2,J)::tail) j p tk w1 sg1 nh rem emit
    HW HShape HKeys HPos HHead HD HB)
    as (HW1 & HShape1 & HKeys1 & HPos1).
  destruct (lin_bulk_child_frame_data
    sg ((2,2,J)::tail) j p tk w1 sg1 nh rem emit gb
    (firstn j ((2,2,J)::tail))
    (skipn (S (j + phase_len p)) ((2,2,J)::tail))
    HW HOk HAlt HHead HLayout HJRaw HPost HKey Hp HFull HB HW1)
    as (PRE & POST & c & cs & b & HIn & HOut & HCoord & HLevels &
        HSafe & HPOST & Hb & HRem & HEmit & HRem28 & HView).
  assert (HjLen : (j <= length ((2,2,J)%N :: tail))%nat).
  { rewrite <- HJRaw. apply firstn_length_bound. }
  destruct (flat_cursor sg ((2,2,J)::tail) j HW HjLen)
    as (HFirst & HSkip).
  assert (EPrefix : lin_flat sg
      (firstn j ((2,2,J)::tail)) =
      PRE ++ runway (c :: cs)).
  { transitivity (firstn
      (fmapw sg ((2,2,J)%N::tail) O O j)
      (lin_flat sg ((2,2,J)%N::tail))).
    - symmetry. exact HFirst.
    - rewrite HCoord, HIn.
    unfold site.
    rewrite firstn_len_app. reflexivity. }
  destruct (flat_prefix_master_runway
    sg J tail j PRE c cs Hj EPrefix) as (pr & EPre).
  subst PRE.
  assert (EPrefixTail : lin_flat sg
      (firstn (j-1)%nat tail) =
      pr ++ runway (c :: cs)).
  { apply (flat_prefix_master_inv sg J tail j
      (pr ++ runway (c :: cs)) Hj).
    rewrite EPrefix. reflexivity. }
  assert (HFlatCols : forallb is_col
      (lin_flat sg (firstn (j-1)%nat tail)) = true).
  { apply flat_checked_prefix_cols.
    - exact HW.
    - exact (lin_generation_prefix_master J tail j HCols). }
  rewrite EPrefixTail in HFlatCols.
  rewrite forallb_app in HFlatCols.
  apply andb_prop in HFlatCols as [HPreCols HRunwayCols].
  assert (HprCols : forallb is_col pr = true)
    by exact HPreCols.
  destruct (lin_bulk_preserves_master
    sg J tail j p tk w1 sg1 nh rem emit Hj HD HB)
    as (tail1 & Ew1).
  assert (EWM : subst_at O 1 [(2,2,J+tk)] w1 =
      (2,2,J+tk) :: tail1) by (rewrite Ew1; reflexivity).
  destruct (lin_bulk_head_pos
    sg ((2,2,J)::tail) j p tk w1 sg1 nh rem emit
    Hj HHead HD HB) as (Hnh & HHead1).
  set (cur := (nh + phase_len rem)%nat).
  assert (Hcur : (1 <= cur)%nat).
  { unfold cur. pose proof (phase_len_pos rem). lia. }
  assert (ESkipMaster :
      skipn cur (subst_at O 1 [(2,2,J+tk)] w1) = skipn cur w1).
  { rewrite EWM, Ew1. destruct cur; [lia|reflexivity]. }
  assert (HViewM : schedule_frame_view
      (lin_sched_child nh rem emit p tk)
      (lin_flat sg1
        (skipn cur (subst_at O 1 [(2,2,J+tk)] w1)))
      (bulk_schedule p rem cs b)
      [(4,2,c - 3 + DBu rem)%N] POST).
  { rewrite ESkipMaster. exact HView. }
  destruct (scheduled_frame_output
    (lin_sched_child nh rem emit p tk)
    sg1 (subst_at O 1 [(2,2,J+tk)] w1) f sg2 w2 f2
    (bulk_schedule p rem cs b)
    [(4,2,c - 3 + DBu rem)%N] POST
    HFrame HViewM) as (child & HTrips & HFinal).
  pose proof HView as HViewParts.
  unfold schedule_frame_view in HViewParts.
  destruct HViewParts as
    (HSlot & HLen & HSchedShape & HBaseCols & HSuffix0 & HGap).
  assert (HSuffix : lin_flat sg1 (skipn cur w1) =
      [(4,2,c - 3 + DBu rem)%N] ++
        crossed_post cs b POST).
  { unfold cur. rewrite bulk_schedule_stock in HSuffix0.
    unfold crossed_post in HSuffix0 |- *.
    rewrite app_nil_r in HSuffix0.
    repeat rewrite <- app_assoc in HSuffix0.
    exact HSuffix0. }
  assert (EPrefix1 : lin_flat sg1 (firstn cur w1) =
      (2,2,J) :: pr ++ phase_form rem).
  { pose proof (flat_firstn_skipn sg1 w1 cur) as EDec.
    rewrite HOut, HSuffix in EDec.
    unfold site in EDec.
    rewrite app_assoc in EDec.
    apply app_inv_tail in EDec. symmetry. exact EDec. }
  assert (EPrefix1' : lin_flat sg1 (firstn cur w1) =
      (2,2,J) :: (pr ++ phase_form rem)).
  { rewrite EPrefix1. reflexivity. }
  rewrite Ew1 in EPrefix1'.
  assert (EPrefixM0 : lin_flat sg1
      (firstn cur ((2,2,J+tk)::tail1)) =
      (2,2,J+tk) :: (pr ++ phase_form rem)).
  { exact (flat_firstn_master_change sg1 J (J+tk) tail1 cur
      (pr ++ phase_form rem) Hcur EPrefix1'). }
  assert (EPrefixM : lin_flat sg1
      (firstn cur (subst_at O 1 [(2,2,J+tk)] w1)) =
      (2,2,J+tk) :: (pr ++ phase_form rem)).
  { rewrite EWM. exact EPrefixM0. }
  set (tail2 := ((pr ++ phase_form rem) ++
    [(4,2,c - 3 + DBu rem)%N]) ++ child).
  assert (EFinal : lin_flat sg2 w2 = (2,2,J+tk) :: tail2).
  { change (lin_flat sg2 w2 =
      lin_flat sg1
        (firstn cur (subst_at O 1 [(2,2,J+tk)] w1)) ++
      [(4,2,c - 3 + DBu rem)%N] ++ child) in HFinal.
    unfold tail2.
    rewrite HFinal, EPrefixM.
    cbn [app]. f_equal.
    exact (app_assoc (pr ++ phase_form rem)
      [(4,2,c - 3 + DBu rem)%N] child). }
  destruct (schedule_trips_factor
    (bulk_schedule p rem cs b)
    POST f child f2 HTrips)
    as (child0 & f0 & HChild & EChild).
  pose proof (runway_scheduled_deliveries
    c cs [] p rem b POST child0 f f0 eq_refl
    HSafe Hp HRem28 Hb HChild)
    as HRun.
  cbn [app] in HRun.
  replace
    (N.to_nat (28 * N.of_nat (length (c :: cs)) + rem - p))
    with (N.to_nat tk) in HRun.
  2: { f_equal. rewrite HLevels, N2Nat.id, HRem.
       pose proof (N.div_mod' (p+tk) 28). lia. }
  assert (EEnd : sdec
      (phase_form rem ++
        (4,2,c - 3 + DBu rem)%N :: child0) f0 =
      sdec
        (phase_form rem ++
          (4,2,c - 3 + DBu rem)%N :: child) f2).
  { rewrite !sdec_app, !sdec_cons, EChild. reflexivity. }
  pose proof (deliveries_sdec_right
    (N.to_nat tk)
    (runway (c :: cs) ++
      phase_form p ++
      (4,2,b + DBu p)%N :: POST) f
    (phase_form rem ++
      (4,2,c - 3 + DBu rem)%N :: child0) f0
    (phase_form rem ++
      (4,2,c - 3 + DBu rem)%N :: child) f2
    EEnd HRun) as HRun2.
  pose proof (deliveries_master_sound
    (N.to_nat tk) J pr
    (runway (c :: cs) ++
      phase_form p ++
      (4,2,b + DBu p)%N :: POST) f
    (phase_form rem ++
      (4,2,c - 3 + DBu rem)%N :: child) f2
    HRun2 HprCols HJ) as HSound.
  rewrite N2Nat.id in HSound.
  refine (sound_impl_sdecode
    _ _ _ _ _ _ _ _ _ _ HSound).
  - rewrite HIn. unfold site.
    f_equal; cbn [app]; repeat rewrite app_assoc; cbn [app]; reflexivity.
  - rewrite EFinal. unfold tail2.
    f_equal; cbn [app]; repeat rewrite <- app_assoc; cbn [app]; reflexivity.
Qed.
Lemma lin_bulk_generation_frame_pos :
  forall sg J tail j p m w1 sg1 nh rem emit,
  (3 <= j)%nat -> m <> O ->
  detect_phase ((2,2,J) :: tail) j = Some p ->
  lin_bulk sg ((2,2,J) :: tail) j p
      (28 * N.of_nat m - p) = Some (w1, sg1, nh, rem, emit) ->
  frame_pos
    (lin_sched_child nh rem emit p (28 * N.of_nat m - p)).
Proof.
  intros sg J tail j p [|m] w1 sg1 nh rem emit Hj Hm HD HB;
    [contradiction|].
  destruct (detect_phase_form ((2,2,J)::tail) j p HD)
    as (Hp & HPhase).
  assert (ESum :
      (p + (28 * N.of_nat (S m) - p) = 28 * N.of_nat (S m))%N)
    by (cbn [N.of_nat]; lia).
  destruct (Nat.eqb
    (N.to_nat ((p + (28 * N.of_nat (S m) - p))/28)) O)
    eqn:HFull.
  - destruct (lin_bulk_checks
      sg ((2,2,J)::tail) j p (28 * N.of_nat (S m) - p) _ HB)
      as (gb & EW & HKey & HLevel & HFloor & HEnd).
    destruct (lin_bulk_partial_out
      sg ((2,2,J)::tail) j p (28 * N.of_nat (S m) - p)
      w1 sg1 nh rem emit gb HFull HB EW)
      as (Esg & Enh & Erem & Eemit & Ew1).
    unfold frame_pos, lin_sched_child.
    cbn [lsCur]. rewrite Enh. lia.
  - destruct (lin_bulk_head_pos
      sg ((2,2,J)::tail) j p (28 * N.of_nat (S m) - p)
      w1 sg1 nh rem emit ltac:(lia) ltac:(reflexivity) HD HB)
      as (Hnh & HHead).
    destruct (lin_bulk_checks
      sg ((2,2,J)::tail) j p (28 * N.of_nat (S m) - p) _ HB)
      as (gb & EW & HKey & HLevel & HFloor & HEnd).
    destruct (site_layout
      ((2,2,J)::tail) j p gb HD EW HEnd)
      as (HLayout & HJRaw & HPost).
    destruct (lin_bulk_pieces
      sg ((2,2,J)::tail) j p (28 * N.of_nat (S m) - p)
      w1 sg1 nh rem emit gb (firstn j ((2,2,J)::tail))
      (skipn (S (j + phase_len p)) ((2,2,J)::tail))
      HLayout HJRaw HPost HKey Hp ltac:(reflexivity) HFull HB)
      as (left & used & sp & hd & rest0 & cgb & EC & EM & Hpre & HnhEq &
          Hgb & Hfloor & Hrem & Hemit & Hph & Hout).
    assert (Hrem0 : rem = 0%N).
    { rewrite Hrem, ESum.
      exact (mod_28 (N.of_nat (S m)) 0 ltac:(lia)). }
    unfold frame_pos, lin_sched_child.
    cbn [lsCur]. rewrite Hrem0.
    change (3 <= nh + 2)%nat. lia.
Qed.
Lemma generation_take_full : forall p m,
  (p < 28)%N -> m <> O ->
  Nat.eqb
    (N.to_nat ((p + (28 * N.of_nat m - p))/28)) O = false.
Proof.
  intros p [|m] Hp Hm; [contradiction|].
  assert (ESum :
      (p + (28 * N.of_nat (S m) - p) = 28 * N.of_nat (S m))%N)
    by (cbn [N.of_nat]; lia).
  rewrite ESum.
  assert (EDiv : ((28 * N.of_nat (S m))/28 = N.of_nat (S m))%N).
  { replace (28 * N.of_nat (S m))%N with
      (28 * N.of_nat (S m) + 0)%N by lia.
    apply div_28. lia. }
  rewrite EDiv.
  rewrite Nat2N.id. apply PeanoNat.Nat.eqb_neq. lia.
Qed.
Lemma lin_try_at_master_stable_sound :
  forall k sg ps J tail f i p m t w3 sg3 ps3 f3 fs,
  stable_guard sg ((2,2,J) :: tail) ->
  (1 <= J)%N -> (3 <= i)%nat ->
  forallb is_col (firstn i ((2,2,J) :: tail)) = true ->
  detect_phase ((2,2,J) :: tail) i = Some p ->
  lin_try_at k sg ps ((2,2,J) :: tail) f J i p m =
    Some (t, w3, sg3, ps3, f3, fs) ->
  sound_impl
    (lin_flat sg ((2,2,J) :: tail)) f
    (lin_flat sg3 w3) f3 /\
  stable_guard sg3 w3 /\
  lin_guard sg3 w3 = true /\
  is_spc (nth O w3 d0) = false.
Proof.
  induction k as [|k IH];
    intros sg ps J tail f i p m t w3 sg3 ps3 f3 fs
      HG HJ Hi HCols HD HRun.
  - cbn [lin_try_at] in HRun. discriminate.
  - cbn [lin_try_at] in HRun.
    destruct (Nat.eqb m O) eqn:Hm; [discriminate|].
    apply PeanoNat.Nat.eqb_neq in Hm.
    destruct (lin_bulk sg ((2,2,J)::tail) i p
      (28 * N.of_nat m - p))
      as [[[[[w1 sg1] nh] rem] emit]|] eqn:HB; [|discriminate].
    destruct (lin_at_safe sg1
      (subst_at O 1 [(2,2,J + (28 * N.of_nat m - p))] w1) nh)
      as [w2|] eqn:HAtSafe.
    2: { exact (IH sg ps J tail f i p (Nat.div2 m)
          t w3 sg3 ps3 f3 fs HG HJ Hi HCols HD HRun). }
    pose proof (lin_at_safe_some sg1
      (subst_at O 1 [(2,2,J + (28 * N.of_nat m - p))] w1)
      nh w2 HAtSafe) as Ew2. subst w2.
    destruct (locate_all sg1
      (subst_at O 1 [(2,2,J + (28 * N.of_nat m - p))] w1))
      as [ps1|] eqn:HLocate.
    2: { exact (IH sg ps J tail f i p (Nat.div2 m)
          t w3 sg3 ps3 f3 fs HG HJ Hi HCols HD HRun). }
    destruct (lin_keep_at sg1 ps1
      (subst_at O 1 [(2,2,J + (28 * N.of_nat m - p))] w1)
      [((nh + phase_len rem)%nat, emit)])
      as [[[[sgA psA] wA] stA]|] eqn:HKeep.
    2: { exact (IH sg ps J tail f i p (Nat.div2 m)
          t w3 sg3 ps3 f3 fs HG HJ Hi HCols HD HRun). }
    unfold lin_keep_at in HKeep.
    destruct (lin_guard_at sg1 ps1
      (subst_at O 1 [(2,2,J + (28 * N.of_nat m - p))] w1))
      eqn:HAt; [|discriminate].
    injection HKeep as <- <- <- <-.
    change
      (match lin_casc_safe_at CFUEL sg1 ps1
          (subst_at O 1
            [(2,2,J + (28 * N.of_nat m - p))] w1) f
          [lin_sched_child nh rem emit p
            (28 * N.of_nat m - p)] with
       | Some (wc, sgc, psc, fc) =>
           Some (28 * N.of_nat m - p, wc, sgc, psc, fc,
             fmapw sg1 w1 O O (nh + 2)%nat)
       | None =>
           lin_try_at k sg ps ((2,2,J)::tail) f J i p
             (Nat.div2 m)
       end = Some (t, w3, sg3, ps3, f3, fs)) in HRun.
    destruct (lin_casc_safe_at CFUEL sg1 ps1
      (subst_at O 1 [(2,2,J + (28 * N.of_nat m - p))] w1) f
      [lin_sched_child nh rem emit p
        (28 * N.of_nat m - p)])
      as [[[[wC sgC] psC] fC]|] eqn:HCasc.
    2: { cbv beta iota in HRun.
         exact (IH sg ps J tail f i p (Nat.div2 m)
          t w3 sg3 ps3 f3 fs HG HJ Hi HCols HD HRun). }
    cbv beta iota in HRun.
    injection HRun as <- <- <- <- <- <-.
    destruct (lin_bulk_master_stable
      sg ps1 J tail i p (28 * N.of_nat m - p)
      w1 sg1 nh rem emit HG ltac:(lia) HD HB HAt)
      as (HStable1 & HGuard1 & HHead1 & Hnh).
    assert (HFramePos : frame_pos
      (lin_sched_child nh rem emit p
        (28 * N.of_nat m - p))).
    { exact (lin_bulk_generation_frame_pos
        sg J tail i p m w1 sg1 nh rem emit Hi Hm HD HB). }
    destruct (lin_casc_safe_at_work
      CFUEL sg1 ps1
      (subst_at O 1 [(2,2,J + (28 * N.of_nat m - p))] w1) f
      [lin_sched_child nh rem emit p
        (28 * N.of_nat m - p)]
      wC sgC psC fC HStable1 HGuard1 HHead1
      ltac:(constructor; [exact HFramePos|constructor]) HCasc)
      as (HWork & HStableC & HGuardC & HHeadC).
    destruct (scheduled_work_inv
      (lin_sched_child nh rem emit p
        (28 * N.of_nat m - p)) []
      sg1 (subst_at O 1
        [(2,2,J + (28 * N.of_nat m - p))] w1) f
      sgC wC fC HWork)
      as (sgX & wX & fX & HFrame & HRest).
    inversion HRest; subst.
    destruct (detect_phase_form
      ((2,2,J)::tail) i p HD) as (Hp & HPhase).
    assert (HFull : Nat.eqb
      (N.to_nat ((p + (28 * N.of_nat m - p))/28)) O = false)
      by (exact (generation_take_full p m Hp Hm)).
    pose proof (lin_bulk_master_scheduled_sound_full
      sg J tail f i p (28 * N.of_nat m - p)
      w1 sg1 nh rem emit sgC wC fC
      HG HJ ltac:(lia) HCols HD HFull HB HFrame) as HSound.
    split; [exact HSound|]. split; [exact HStableC|].
    split; assumption.
Qed.
Lemma lin_gen_action_at_master_stable :
  forall front sg ps J tail f h t w2 sg2 ps2 f2 fs,
  stable_guard sg ((2,2,J) :: tail) ->
  lin_gen_action_at front sg ps ((2,2,J) :: tail) f h =
    Some (Some (t, w2, sg2, ps2, f2, fs)) ->
  sound_impl
    (lin_flat sg ((2,2,J) :: tail)) f
    (lin_flat sg2 w2) f2 /\
  stable_guard sg2 w2 /\
  lin_guard sg2 w2 = true /\
  is_spc (nth O w2 d0) = false.
Proof.
  intros front sg ps J tail f h t w2 sg2 ps2 f2 fs HG HRun.
  unfold lin_gen_action_at in HRun. cbv beta zeta in HRun.
  cbn [N.eqb Pos.eqb andb] in HRun.
  destruct (negb (front_blind ((2,2,J)::tail)))
    eqn:HBlind; [discriminate|].
  destruct front as [r|]; [discriminate|].
  destruct (negb (f =? 4)) eqn:Hf; [discriminate|].
  set (start := if Nat.ltb h 1 then 1%nat else h) in *.
  destruct (find_active ((2,2,J)::tail) start)
    as [i|] eqn:HFind; [|discriminate].
  destruct (negb (Nat.ltb (S MARGIN) i))
    eqn:HMargin; [discriminate|].
  apply negb_false_iff in HMargin.
  lazymatch type of HRun with
  | context [if negb ?colsok then _ else _] =>
      destruct colsok eqn:HCols
  end.
  2: discriminate.
  destruct (detect_phase ((2,2,J)::tail) i)
    as [p|] eqn:HPhase; [|discriminate].
  set (k0 := (i-1)%nat) in *.
  set (clean1 :=
    if Nat.ltb k0 1 then false
    else match wat ((2,2,J)::tail) k0,
               wat ((2,2,J)::tail) (k0-1) with
         | Some l, Some sp => lvl_big l && spacer sp
         | _, _ => false
         end) in *.
  destruct (negb clean1) eqn:HClean; [discriminate|].
  destruct (negb (1 <=? J)%N) eqn:HJb; [discriminate|].
  apply negb_false_iff in HJb. apply N.leb_le in HJb.
  set (mmax := Nat.div2
    (fmapw sg ((2,2,J)::tail) O O i - MARGIN)) in *.
  set (m := lin_count_clean sg ((2,2,J)::tail) k0 mmax) in *.
  injection HRun as HTry.
  exact (lin_try_at_master_stable_sound TRIES
    sg ps J tail f i p m t w2 sg2 ps2 f2 fs
    HG HJb ltac:(apply PeanoNat.Nat.ltb_lt in HMargin;
                 unfold MARGIN in HMargin; lia)
    HCols HPhase HTry).
Qed.
Lemma lin_gen_action_at_stable :
  forall front sg ps w f h t w2 sg2 ps2 f2 fs,
  stable_guard sg w ->
  lin_gen_action_at front sg ps w f h =
    Some (Some (t, w2, sg2, ps2, f2, fs)) ->
  sound_impl (lin_flat sg w) f
    (lin_flat sg2 w2) f2 /\
  stable_guard sg2 w2 /\
  lin_guard sg2 w2 = true /\
  is_spc (nth O w2 d0) = false.
Proof.
  intros front sg ps w f h t w2 sg2 ps2 f2 fs HG HRun.
  pose proof HRun as HShape.
  unfold lin_gen_action_at in HShape. cbv beta zeta in HShape.
  destruct (negb (front_blind w)); [discriminate|].
  destruct front; [discriminate|].
  destruct (negb (f =? 4)); [discriminate|].
  destruct w as [|[[o z] J] tail]; [discriminate|].
  destruct o as [|op]; cbn in HShape; try discriminate.
  destruct op as [op1|op1|]; cbn in HShape; try discriminate.
  destruct op1 as [op2|op2|]; cbn in HShape; try discriminate.
  destruct z as [|zp]; cbn in HShape; try discriminate.
  destruct zp as [zp1|zp1|]; cbn in HShape; try discriminate.
  destruct zp1 as [zp2|zp2|]; cbn in HShape; try discriminate.
  change (stable_guard sg ((2,2,J)::tail)) in HG.
  change (lin_gen_action_at None sg ps ((2,2,J)::tail) f h =
    Some (Some (t,w2,sg2,ps2,f2,fs))) in HRun.
  exact (lin_gen_action_at_master_stable
    None sg ps J tail f h t w2 sg2 ps2 f2 fs HG HRun).
Qed.
Open Scope N_scope.
Open Scope sym.
Opaque LROUND_FUEL LROUND_CHUNKS
       FLAT_ROUND_FUEL CFUEL TRIES.
Lemma tick_stage_site : forall w i q w1 j2 rem emit,
  lin_tick_front_stage w i = Some (q, w1, j2, rem, emit) ->
  i = 5%nat \/ i = 6%nat \/ i = 7%nat.
Proof.
  intros w i q w1 j2 rem emit H.
  unfold lin_tick_front_stage in H.
  destruct (Nat.eqb i 7) eqn:E7.
  - apply PeanoNat.Nat.eqb_eq in E7. auto.
  - destruct (Nat.eqb i 6) eqn:E6.
    + apply PeanoNat.Nat.eqb_eq in E6. auto.
    + destruct (Nat.eqb i 5) eqn:E5; [|discriminate].
      apply PeanoNat.Nat.eqb_eq in E5. auto.
Qed.
Inductive tick_stage_7_view (w : word) (q : N) (w1 : word)
    (j2 : nat) (rem emit : N) : Prop :=
  | TickStage7View (a0 a1 a2 a3 a4 : bg) (c cg : N)
      (rest : word) :
      w = [a0;a1;a2;a3;a4; (8,2,1)%N; (4,2,c)%N;
           (7,1,1)%N; (3,2,1)%N; (4,2,cg)%N] ++ rest ->
      w1 = [a0;a1;a2;a3;a4; (7,1,1)%N; (3,2,1)%N; (4,2,c)%N;
            (8,2,1)%N; (4,2,cg-4)%N] ++ rest ->
      rest <> [] ->
      (FLOOR <= c)%N ->
      (FLOOR + 3 <= cg)%N ->
      q = 28%N -> j2 = 5%nat -> rem = 0%N -> emit = 4%N ->
      tick_stage_7_view w q w1 j2 rem emit.
Lemma tick_stage_7 : forall w q w1 j2 rem emit,
  lin_tick_front_stage w 7 = Some (q, w1, j2, rem, emit) ->
  tick_stage_7_view w q w1 j2 rem emit.
Proof.
  intros w q w1 j2 rem emit H.
  unfold lin_tick_front_stage in H. cbn [Nat.eqb] in H.
  destruct w as [|a0 [|a1 [|a2 [|a3 [|a4 [|sp [|lv
    [|[[o7 z7] c7] [|[[o8 z8] c8] [|[[o9 z9] c9] [|r0 rest]]]]]]]]]]];
    try discriminate; try (digsH H; discriminate).
  digsH H; try discriminate.
  destruct (spacer sp) eqn:ESP;
  destruct (lvl_big lv) eqn:ELV;
  destruct (erode_safe 0 (4,2,c9)%N) eqn:ELG;
    cbn [andb] in H; try discriminate.
  injection H as <- <- <- <- <-.
  destruct sp as [[so sz] sc].
  unfold spacer in ESP.
  cbn [gO gZ gC] in ESP.
  repeat rewrite Bool.andb_true_iff in ESP.
  destruct ESP as [[Eo Ez] Ec].
  apply N.eqb_eq in Eo, Ez, Ec. subst so sz sc.
  destruct lv as [[lo lz] lc].
  unfold lvl_big in ELV.
  cbn [gO gZ gC] in ELV.
  repeat rewrite Bool.andb_true_iff in ELV.
  destruct ELV as [[Eo Ez] Elc].
  apply N.eqb_eq in Eo, Ez. apply N.leb_le in Elc. subst lo lz.
  unfold erode_safe in ELG.
  cbn [gC DBu DBu_tbl] in ELG.
  apply N.leb_le in ELG.
  eapply (@TickStage7View _ _ _ _ _ _
    a0 a1 a2 a3 a4 lc c9 (r0::rest));
    try reflexivity; try assumption. discriminate.
Qed.
Inductive tick_stage_5_view (w : word) (q : N) (w1 : word)
    (j2 : nat) (rem emit : N) : Prop :=
  | TickStage5View (a0 a1 a2 a3 a4 : bg) (cg : N)
      (rest : word) :
      w = [a0;a1;a2;a3;a4; (7,1,1)%N; (3,2,1)%N;
           (4,2,cg)%N] ++ rest ->
      w1 = [a0;a1;a2;a3;a4; (4,3,1)%N; (4,2,cg-3)%N] ++ rest ->
      rest <> [] ->
      (FLOOR + 3 <= cg)%N ->
      q = 27%N -> j2 = 5%nat -> rem = 27%N -> emit = 3%N ->
      tick_stage_5_view w q w1 j2 rem emit.
Lemma tick_stage_5 : forall w q w1 j2 rem emit,
  lin_tick_front_stage w 5 = Some (q, w1, j2, rem, emit) ->
  tick_stage_5_view w q w1 j2 rem emit.
Proof.
  intros w q w1 j2 rem emit H.
  unfold lin_tick_front_stage in H. cbn [Nat.eqb] in H.
  destruct w as [|a0 [|a1 [|a2 [|a3 [|a4 [|[[o5 z5] c5]
    [|[[o6 z6] c6] [|[[o7 z7] c7] [|r0 rest]]]]]]]]];
    try discriminate; try (digsH H; discriminate).
  digsH H; try discriminate.
  destruct (erode_safe 0 (4,2,c7)%N) eqn:ELG; [|discriminate].
  injection H as <- <- <- <- <-.
  unfold erode_safe in ELG.
  cbn [gC DBu DBu_tbl] in ELG.
  apply N.leb_le in ELG.
  eapply (@TickStage5View _ _ _ _ _ _
    a0 a1 a2 a3 a4 c7 (r0::rest));
    try reflexivity; try assumption. discriminate.
Qed.
Lemma bulk_stage_6_checks : forall w out nh rem emit,
  bulk_stage w 6 0 28 = Some (out, nh, rem, emit) ->
  exists gb,
    wat w 8 = Some gb /\
    lvl_big gb = true /\
    Nat.eqb 9 (length w) = false /\
    clean_above w 5 1 = true.
Proof.
  intros w out nh rem emit H.
  unfold bulk_stage in H. cbv beta zeta in H.
  assert (EPhase : phase_len 0 = 2%nat) by reflexivity.
  assert (EFull : N.to_nat ((0+28)/28) = 1%nat) by reflexivity.
  rewrite EPhase, EFull in H.
  replace (6 + 2)%nat with 8%nat in H by reflexivity.
  destruct (wat w 8) as [gb|] eqn:EW; [|discriminate].
  destruct (negb (lvl_big gb)) eqn:EB; [discriminate|].
  apply negb_false_iff in EB.
  destruct (Nat.eqb 9 (length w)) eqn:EE; [discriminate|].
  replace (2 * 1)%nat with 2%nat in H by reflexivity.
  replace (6 - 1)%nat with 5%nat in H by reflexivity.
  replace (6 - 2)%nat with 4%nat in H by reflexivity.
  replace (2 - 1)%nat with 1%nat in H by reflexivity.
  cbn [Nat.eqb Nat.ltb] in H.
  destruct (negb (clean_above w 5 1)) eqn:EC;
    [discriminate|].
  apply negb_false_iff in EC.
  destruct (firstn 1 (skipn 5 w)); [discriminate|].
  exists gb. repeat split; assumption.
Qed.
Lemma clean_above_6_prefix : forall w,
  clean_above w 5 1 = true ->
  exists a0 a1 a2 a3 c,
    firstn 6 w = [a0;a1;a2;a3; (8,2,1)%N; (4,2,c)%N] /\
    (FLOOR <= c)%N.
Proof.
  intros [|a0 [|a1 [|a2 [|a3 [|sp [|lv tail]]]]]] H;
    cbn [clean_above wat nth_error] in H;
    try discriminate.
  replace (5 - 1)%nat with 4%nat in H by reflexivity.
  cbn [wat nth_error] in H.
  destruct (lvl_big lv) eqn:EL.
  2: { discriminate. }
  destruct (spacer sp) eqn:ES.
  2: { discriminate. }
  destruct sp as [[so sz] sc].
  unfold spacer in ES.
  cbn [gO gZ gC] in ES.
  repeat rewrite Bool.andb_true_iff in ES.
  destruct ES as [[Eo Ez] Ec].
  apply N.eqb_eq in Eo, Ez, Ec. subst so sz sc.
  destruct lv as [[lo lz] lc].
  unfold lvl_big in EL.
  cbn [gO gZ gC] in EL.
  repeat rewrite Bool.andb_true_iff in EL.
  destruct EL as [[Eo Ez] Elc].
  apply N.eqb_eq in Eo, Ez. apply N.leb_le in Elc. subst lo lz.
  exists a0. exists a1. exists a2. exists a3. exists lc.
  split; [reflexivity|exact Elc].
Qed.
Lemma tick_stage_6 : forall w q w1 j2 rem emit,
  detect_phase w 6 = Some 0%N ->
  lin_tick_front_stage w 6 = Some (q, w1, j2, rem, emit) ->
  exists a0 a1 a2 a3 c cg rest,
    w = [a0;a1;a2;a3; (8,2,1)%N; (4,2,c)%N;
         (7,1,1)%N; (3,2,1)%N; (4,2,cg)%N] ++ rest /\
    w1 = [a0;a1;a2;a3; (7,1,1)%N; (3,2,1)%N; (4,2,c)%N;
          (8,2,1)%N; (4,2,cg-4)%N] ++ rest /\
    rest <> [] /\
    (FLOOR <= c)%N /\
    (FLOOR + 3 <= cg)%N /\
    q = 28%N /\ j2 = 4%nat /\ rem = 0%N /\ emit = 4%N.
Proof.
  intros w q w1 j2 rem emit HD H.
  unfold lin_tick_front_stage in H. cbn [Nat.eqb] in H.
  assert (EPhase : phase_len 0 = 2%nat) by reflexivity.
  rewrite EPhase in H.
  replace (6 + 2)%nat with 8%nat in H by reflexivity.
  destruct (wat w 8) as [gb|] eqn:EW; [|discriminate].
  destruct (erode_safe 0 gb) eqn:HER; [|discriminate].
  destruct (bulk_stage w 6 0 28)
    as [[[[out nh] rp] em]|] eqn:HB; [|discriminate].
  injection H as <- <- <- <- <-.
  destruct (bulk_stage_6_checks w out nh rp em HB)
    as (gb' & EW' & EBig & EEnd & HClean).
  rewrite EW in EW'. injection EW' as <-.
  destruct (lvl_big_shape gb EBig) as (cg & ->).
  destruct (site_layout w 6 0 (4,2,cg)%N HD EW EEnd)
    as (HLayout & HPreLen & HPost).
  destruct (clean_above_6_prefix w HClean)
    as (a0 & a1 & a2 & a3 & c & HPre & Hc).
  rewrite HPre in HLayout.
  change (phase_form 0) with [(7,1,1)%N;(3,2,1)%N]
    in HLayout.
  rewrite EPhase in HLayout, HPost.
  replace (S (6 + 2))%nat with 9%nat in HLayout, HPost by reflexivity.
  set (post := skipn 9 w) in *.
  assert (Hcg : (FLOOR + 3 <= cg)%N).
  { unfold erode_safe in HER.
    cbn [gC DBu DBu_tbl] in HER.
    apply N.leb_le in HER. exact HER. }
  pose proof (bulk_stage_runway
    c [] [a0;a1;a2;a3] post 0 (cg-3) 0
    ltac:(constructor; [exact Hc|constructor]) ltac:(lia) ltac:(lia)
    HPost ltac:(lia)) as HFused.
  change (DBu 0) with 3%N in HFused.
  change (N.of_nat 1) with 1%N in HFused.
  change (marks 28) with 4%N in HFused.
  change (marks 0) with 0%N in HFused.
  replace (cg - 3 + 3)%N with cg in HFused by lia.
  assert (Ec : (c - 3 + 3 = c)%N).
  { unfold FLOOR in Hc. lia. }
  rewrite Ec in HFused.
  unfold site, runway,
    rung1, crossed_post in HFused.
  cbn [app length map] in HFused.
  assert (Ecg : (cg - 3 - 1 = cg - 4)%N).
  { unfold FLOOR in Hcg. lia. }
  rewrite Ecg in HFused.
  change (phase_form 0)
    with [(7,1,1)%N;(3,2,1)%N] in HFused.
  change (N.of_nat 1) with 1%N in HFused.
  change (28 * 1 - 0 + 0)%N with 28%N in HFused.
  change (marks (28 * 1 + 0) - 0)%N with 4%N in HFused.
  cbn [runway rung1 app] in HFused.
  rewrite HLayout in HB.
  cbn [app] in HB.
  pose proof (eq_trans (eq_sym HB) HFused) as EResults.
  injection EResults as Eout Enh Erp Eem.
  subst out nh rp em.
  exists a0. exists a1. exists a2. exists a3.
  exists c. exists cg. exists post.
  repeat split; try reflexivity; try assumption.
Qed.
Lemma stable_guard_phseq_edges : forall sg src out,
  stable_guard sg src ->
  phseq out = phseq src ->
  tag_edges out ->
  stable_guard sg out.
Proof.
  intros sg src out ((HOk & HPT) & HE & HW & HS & HK & HP) ESeq HEout.
  split.
  - split.
    + exact (lin_ok_of_phseq_eq sg src out ESeq HOk).
    + exact (lin_ptags_of_phseq_eq sg src out ESeq HPT).
  - repeat split; assumption.
Qed.
Lemma front_repr_phseq : forall sg src out,
  stable_guard sg src ->
  phseq out = phseq src ->
  front_repr sg out.
Proof.
  intros sg src out ((HOk & HPT) & _) ESeq.
  split.
  - exact (lin_ok_of_phseq_eq sg src out ESeq HOk).
  - exact (lin_ptags_of_phseq_eq sg src out ESeq HPT).
Qed.
Lemma phseq_partial_tick : forall J K pre cg rest,
  phseq
    (((2,2,K)::pre) ++ phase_form 27 ++
      (4,2,cg-3)%N :: rest) =
  phseq
    (((2,2,J)::pre) ++ phase_form 0 ++
      (4,2,cg)%N :: rest).
Proof.
  intros J K pre cg rest.
  repeat rewrite phseq_app.
  cbn [phase_form phseq app].
  repeat rewrite phshape_onot9 by reflexivity.
  reflexivity.
Qed.
Lemma tick_partial_master_stable : forall sg J pre cg rest,
  stable_guard sg
    (((2,2,J)::pre) ++ phase_form 0 ++ (4,2,cg)%N :: rest) ->
  lin_guard sg
    (((2,2,J+27)::pre) ++ phase_form 27 ++
      (4,2,cg-3)%N :: rest) = true ->
  stable_guard sg
    (((2,2,J+27)::pre) ++ phase_form 27 ++
      (4,2,cg-3)%N :: rest).
Proof.
  intros sg J pre cg rest HG HGuard.
  assert (HGm : stable_guard sg
    (((2,2,J+27)::pre) ++ phase_form 0 ++
      (4,2,cg)%N :: rest)).
  { change (stable_guard sg
      ((2,2,J+27)::(pre ++ phase_form 0 ++
        (4,2,cg)%N::rest))).
    change (stable_guard sg
      ((2,2,J)::(pre ++ phase_form 0 ++
        (4,2,cg)%N::rest))) in HG.
    exact (stable_guard_master_change_probe
      sg J (J+27) _ HG). }
  set (out := (((2,2,J+27)::pre) ++ phase_form 27 ++
    (4,2,cg-3)%N::rest)).
  assert (ESeq : phseq out = phseq
      (((2,2,J+27)::pre) ++ phase_form 0 ++
        (4,2,cg)%N::rest)).
  { unfold out. exact (phseq_partial_tick (J+27) (J+27) pre cg rest). }
  assert (HFront : front_repr sg out)
    by (exact (front_repr_phseq sg _ out HGm ESeq)).
  assert (HMout : ph_margins sg out).
  { unfold out. exact (lguard_margins sg _ HGuard). }
  set (P := (2,2,J+27)%N :: pre).
  assert (HEout : tag_edges out).
  { unfold out, P in *.
    eapply phase_form_replace_edges_guarded
      with (pre := (2,2,J+27)%N::pre)
           (p := 0%N) (q := 27%N) (oldg := (4,2,cg)%N)
           (newg := (4,2,cg-3)%N) (post := rest).
    - lia.
    - lia.
    - exact (proj1 (proj2 HGm)).
    - exact HMout.
    - exact (proj2 HFront).
    - unfold head_equiv. repeat split; reflexivity.
    - reflexivity. }
  exact (stable_guard_phseq_edges sg _ out HGm ESeq HEout).
Qed.
Lemma phseq_full_cross : forall J K pre c cg rest,
  phseq
    (((2,2,K)::pre) ++ phase_form 0 ++ (4,2,c)%N ::
      rung1 (cg-4)%N ++ rest) =
  phseq
    (((2,2,J)::pre) ++ rung1 c ++
      phase_form 0 ++ (4,2,cg)%N :: rest).
Proof.
  intros J K pre c cg rest.
  repeat rewrite phseq_app.
  cbn [rung1 phase_form
       phseq app].
  repeat rewrite phshape_onot9 by reflexivity.
  reflexivity.
Qed.
Lemma tick_full_master_stable : forall sg J pre c cg rest,
  stable_guard sg
    (((2,2,J)::pre) ++ rung1 c ++
      phase_form 0 ++ (4,2,cg)%N :: rest) ->
  lin_guard sg
    (((2,2,J+28)::pre) ++ phase_form 0 ++ (4,2,c)%N ::
      rung1 (cg-4)%N ++ rest) = true ->
  stable_guard sg
    (((2,2,J+28)::pre) ++ phase_form 0 ++ (4,2,c)%N ::
      rung1 (cg-4)%N ++ rest).
Proof.
  intros sg J pre c cg rest HG HGuard.
  assert (HGm : stable_guard sg
    (((2,2,J+28)::pre) ++ rung1 c ++
      phase_form 0 ++ (4,2,cg)%N :: rest)).
  { change (stable_guard sg
      ((2,2,J+28)::(pre ++ rung1 c ++
        phase_form 0 ++ (4,2,cg)%N::rest))).
    change (stable_guard sg
      ((2,2,J)::(pre ++ rung1 c ++
        phase_form 0 ++ (4,2,cg)%N::rest))) in HG.
    exact (stable_guard_master_change_probe
      sg J (J+28) _ HG). }
  set (out := (((2,2,J+28)::pre) ++ phase_form 0 ++
    (4,2,c)%N :: rung1 (cg-4)%N ++ rest)).
  assert (ESeq : phseq out = phseq
      (((2,2,J+28)::pre) ++ rung1 c ++
        phase_form 0 ++ (4,2,cg)%N :: rest)).
  { unfold out. exact (phseq_full_cross (J+28) (J+28) pre c cg rest). }
  assert (HFront : front_repr sg out).
  { split.
    - exact (lin_ok_of_phseq_eq sg _ _ ESeq
        (proj1 (proj1 HGm))).
    - exact (lin_ptags_of_phseq_eq sg _ _ ESeq
        (proj2 (proj1 HGm))). }
  assert (HMout : ph_margins sg out).
  { unfold out. exact (lguard_margins sg _ HGuard). }
  set (P := (2,2,J+28)%N :: pre).
  set (oldg := (4,2,cg)%N).
  set (newg := (4,2,cg-4)%N).
  assert (HEin : tag_edges
      (P ++ rung1 c ++
        phase_form 0 ++ oldg :: rest)).
  { unfold P, oldg. exact (proj1 (proj2 HGm)). }
  assert (HPre : tag_edges P).
  { apply (tag_edges_prefix P
      (rung1 c ++ phase_form 0 ++
        oldg::rest)).
    exact HEin. }
  assert (HOldTail : tag_edges (oldg :: rest)).
  { assert (H1 : tag_edges
        (rung1 c ++ phase_form 0 ++
          oldg::rest)).
    { exact (tag_edges_app_r_probe P _ HEin). }
    assert (H2 : tag_edges
        (phase_form 0 ++ oldg::rest)).
    { exact (tag_edges_app_r_probe
        (rung1 c) _ H1). }
    exact (tag_edges_app_r_probe
      (phase_form 0) _ H2). }
  assert (HNewTail : tag_edges (newg :: rest)).
  { eapply tag_edges_replace_head with (pre := []).
    - unfold head_equiv, oldg, newg.
      repeat split; reflexivity.
    - exact HOldTail. }
  assert (HCore : tag_edges
      ((4,2,c)%N :: rung1 (cg-4)%N ++ rest)).
  { unfold rung1.
    change (tag_edges
      ([(4,2,c);(8,2,1)]%N ++ newg::rest)).
    apply tag_edges_shape_free_app_probe.
    - intros g Hin; repeat (destruct Hin as [<-|Hin]);
        try (destruct Hin); reflexivity.
    - intros g t E. injection E as <- <-. unfold newg. reflexivity.
    - exact HNewTail. }
  assert (HPhaseTail : tag_edges
      (phase_form 0 ++
        (4,2,c)%N :: rung1 (cg-4)%N ++ rest)).
  { apply tag_edges_shape_free_app_probe.
    - exact (phase_form_phfreeP 0 ltac:(lia)).
    - intros g t E. injection E as <- <-. reflexivity.
    - exact HCore. }
  assert (HJoin : edge_join P
      (phase_form 0 ++
        (4,2,c)%N :: rung1 (cg-4)%N ++ rest)).
  { apply (phase_form_edge_join_guarded
      sg P 0 ((4,2,c)%N :: rung1 (cg-4)%N ++ rest)
      ltac:(lia)).
    - unfold out in HMout. exact HMout.
    - unfold out in HFront. exact (proj2 HFront). }
  assert (HEout : tag_edges out).
  { unfold out, P in HPre, HJoin |- *.
    exact (tag_edges_app_join _ _ HPre HPhaseTail HJoin). }
  exact (stable_guard_phseq_edges sg _ out HGm ESeq HEout).
Qed.
Lemma one_runway_zero_scheduled_deliveries :
  forall c cols b post out f f',
  delivery_cols cols = true ->
  (1 <= c)%N -> (FLOOR <= b)%N ->
  schedule_deliveries
    (bulk_schedule 0 0 [] b) post f out f' ->
  deliveries 28
    (cols ++ rung1 c ++ phase_form 0 ++
      (4,2,b + DBu 0)%N :: post) f
    (cols ++ phase_form 0 ++ (4,2,c)%N :: out) f'.
Proof.
  intros c cols b post out f f' HCols Hc Hb HRun.
  rewrite bulk_schedule_nil in HRun.
  change (schedule_slot_nat 0) with 3%nat in HRun.
  change (marks 0) with 0%N in HRun.
  cbn [N.to_nat repeat app] in HRun.
  destruct (schedule_deliveries_nones_some
    3 (b-1)%N post f out f' HRun) as (tail & HDeliver & ->).
  pose proof (transit_delivery_pos
    cols c 0 b post tail f f' HCols ltac:(lia) Hc Hb HDeliver) as HTransit.
  change (N.to_nat (28-0)) with 28%nat in HTransit.
  repeat rewrite app_assoc in HTransit |- *.
  exact HTransit.
Qed.
Lemma tick_full_master_scheduled_sound :
  forall sg J pre c cg rest f sg2 w2 f2,
  (1 <= J)%N ->
  (FLOOR <= c)%N ->
  (FLOOR + 3 <= cg)%N ->
  delivery_cols (lin_flat sg pre) = true ->
  scheduled_frame
    (lin_sched_child (S (length pre)) 0 4 0 28)
    sg
    ((((2,2,J+28)::pre) ++ phase_form 0 ++ (4,2,c)%N ::
      rung1 (cg-4)%N) ++ rest)
    f sg2 w2 f2 ->
  sound_impl
    (lin_flat sg
      ((((2,2,J)::pre) ++ rung1 c ++
        phase_form 0 ++ [(4,2,cg)%N]) ++ rest)) f
    (lin_flat sg2 w2) f2.
Proof.
  intros sg J pre c cg rest f sg2 w2 f2 HJ Hc Hcg HCols HFrame.
  set (pr := lin_flat sg pre).
  set (post := lin_flat sg rest).
  set (b := (cg-3)%N).
  set (wout := ((((2,2,J+28)::pre) ++ phase_form 0 ++
    (4,2,c)%N :: rung1 (cg-4)%N) ++ rest)).
  set (cur := (S (length pre) + phase_len 0)%nat).
  assert (H0 : (0 < 28)%N) by lia.
  assert (Hcur : cur = (S (length pre) + 2)%nat) by reflexivity.
  assert (Hb : (FLOOR <= b)%N).
  { unfold b, FLOOR in *. lia. }
  assert (EIn : lin_flat sg
      ((((2,2,J)::pre) ++ rung1 c ++
        phase_form 0 ++ [(4,2,cg)%N]) ++ rest) =
    (2,2,J)%N :: pr ++ rung1 c ++
      phase_form 0 ++ (4,2,cg)%N :: post).
  { unfold pr, post.
    rewrite !lin_flat_app_c,
      (flat_phase_form sg 0 H0).
    rewrite lin_flat_master.
    cbn [rung1 lin_flat keyb keyi
         phshape gO gZ].
    repeat rewrite <- app_assoc. reflexivity. }
  assert (ESkip : lin_flat sg (skipn cur wout) =
      (4,2,c)%N :: rung1 (cg-4)%N ++ post).
  { unfold wout, post. rewrite Hcur.
    replace (S (length pre) + 2)%nat with
      (length (((2,2,J+28)%N::pre) ++ phase_form 0))%nat.
    2: { rewrite length_app, phase_form_len by lia.
         change (phase_len 0) with 2%nat.
         cbn [length]. reflexivity. }
    replace
      (((((2,2,J+28)%N::pre) ++ phase_form 0 ++
          (4,2,c)%N :: rung1 (cg-4)%N) ++ rest))
      with
      ((((2,2,J+28)%N::pre) ++ phase_form 0) ++
        (((4,2,c)%N :: rung1 (cg-4)%N) ++ rest))
      by (repeat rewrite app_assoc; reflexivity).
    rewrite LineageCascade_skipn_len_app.
    cbn [rung1 lin_flat keyb keyi
         phshape gO gZ]. reflexivity. }
  assert (HView : schedule_frame_view
      (lin_sched_child (S (length pre)) 0 4 0 28)
      (lin_flat sg (skipn cur wout))
      (bulk_schedule 0 0 [] b)
      [(4,2,c)%N] post).
  { unfold schedule_frame_view, lin_sched_child.
    cbv beta zeta. cbn [lsSlot lsTicks lsGap].
    split.
    - unfold lin_sched_slot. lia.
    - split.
      + rewrite (bulk_schedule_length 0 0 [] b)
          by lia.
        reflexivity.
      + split.
        * exact (bulk_schedule_shape 0 0 [] b
            ltac:(lia) ltac:(lia)).
        * split.
          -- unfold delivery_cols, is_col, is_cmf.
             cbn [forallb gO gZ gC].
             destruct ((c =? 1)%N); reflexivity.
          -- split.
             ++ rewrite ESkip, bulk_schedule_stock.
                unfold crossed_post,
                  rung1, b.
                cbn [map app].
                replace (cg - 3 - 1)%N with (cg-4)%N by lia.
                reflexivity.
             ++ rewrite bulk_schedule_stock.
                unfold crossed_post,
                  rung1.
                cbn [map app length]. reflexivity. }
  change (scheduled_frame
    (lin_sched_child (S (length pre)) 0 4 0 28)
    sg wout f sg2 w2 f2) in HFrame.
  destruct (scheduled_frame_output
    (lin_sched_child (S (length pre)) 0 4 0 28)
    sg wout f sg2 w2 f2
    (bulk_schedule 0 0 [] b)
    [(4,2,c)%N] post HFrame HView)
    as (child & HTrips & HFinal).
  assert (EPrefix : lin_flat sg (firstn cur wout) =
      (2,2,J+28)%N :: pr ++ phase_form 0).
  { unfold wout. rewrite Hcur.
    replace (S (length pre) + 2)%nat with
      (length ((2,2,J+28)%N::pre) +
        length (phase_form 0))%nat by reflexivity.
    replace
      (((((2,2,J+28)%N::pre) ++ phase_form 0 ++
          (4,2,c)%N :: rung1 (cg-4)%N) ++ rest))
      with
      (((2,2,J+28)%N::pre) ++
        (phase_form 0 ++
          (((4,2,c)%N :: rung1 (cg-4)%N) ++ rest)))
      by (repeat rewrite app_assoc; reflexivity).
    rewrite firstn_prefix_add,
      firstn_len_app, lin_flat_app_c,
      lin_flat_master,
      (flat_phase_form sg 0 H0).
    unfold pr. reflexivity. }
  change (lin_flat sg2 w2 =
    lin_flat sg (firstn cur wout) ++ [(4,2,c)%N] ++ child)
    in HFinal.
  set (tail2 := pr ++ phase_form 0 ++ (4,2,c)%N :: child).
  assert (EFinal : lin_flat sg2 w2 = (2,2,J+28)%N :: tail2).
  { unfold tail2. rewrite HFinal, EPrefix. cbn [app]. f_equal.
    exact (eq_sym (app_assoc pr (phase_form 0)
      ((4,2,c)%N::child))). }
  destruct (schedule_trips_factor
    (bulk_schedule 0 0 [] b)
    post f child f2 HTrips) as (child0 & f0 & HChild & EChild).
  pose proof (one_runway_zero_scheduled_deliveries
    c pr b post child0 f f0 HCols
    ltac:(unfold FLOOR in Hc; lia) Hb HChild) as HRun.
  change (DBu 0) with 3%N in HRun.
  replace (b+3)%N with cg in HRun by (unfold b; lia).
  assert (EEnd : sdec
      (pr ++ phase_form 0 ++ (4,2,c)%N :: child0) f0 =
      sdec tail2 f2).
  { unfold tail2.
    pose proof (sdec_prefix_eq
      [(4,2,c)%N] child0 f0 child f2 EChild) as E1.
    cbn [app] in E1.
    pose proof (sdec_prefix_eq
      (phase_form 0) ((4,2,c)%N::child0) f0
      ((4,2,c)%N::child) f2 E1) as E2.
    exact (sdec_prefix_eq pr _ f0 _ f2 E2). }
  pose proof (deliveries_sdec_right
    28
    (pr ++ rung1 c ++ phase_form 0 ++
      (4,2,cg)%N::post) f
    (pr ++ phase_form 0 ++ (4,2,c)%N::child0) f0
    tail2 f2 EEnd HRun) as HRun2.
  pose proof (deliveries_master_sound
    28 J []
    (pr ++ rung1 c ++ phase_form 0 ++
      (4,2,cg)%N::post) f
    tail2 f2 HRun2 eq_refl HJ) as HSound.
  change (N.of_nat 28) with 28%N in HSound.
  cbn [app] in HSound.
  rewrite EIn, EFinal. exact HSound.
Qed.
Lemma tick_partial_master_scheduled_sound :
  forall sg J pre cg rest f sg2 w2 f2,
  (1 <= J)%N ->
  (FLOOR + 3 <= cg)%N ->
  delivery_cols (lin_flat sg pre) = true ->
  scheduled_frame
    (lin_sched_child (S (length pre)) 27 3 0 27)
    sg
    (((2,2,J+27)::pre) ++ phase_form 27 ++
      (4,2,cg-3)%N :: rest)
    f sg2 w2 f2 ->
  sound_impl
    (lin_flat sg
      (((2,2,J)::pre) ++ phase_form 0 ++ (4,2,cg)%N::rest)) f
    (lin_flat sg2 w2) f2.
Proof.
  intros sg J pre cg rest f sg2 w2 f2 HJ Hcg HCols HFrame.
  set (pr := lin_flat sg pre).
  set (post := lin_flat sg rest).
  set (wout := (((2,2,J+27)::pre) ++ phase_form 27 ++
    (4,2,cg-3)%N::rest)).
  set (cur := (S (length pre) + phase_len 27)%nat).
  assert (H27 : (27 < 28)%N) by lia.
  assert (H0 : (0 < 28)%N) by lia.
  assert (Hcur : cur = (S (length pre) + 1)%nat).
  { unfold cur. reflexivity. }
  assert (EIn : lin_flat sg
      (((2,2,J)::pre) ++ phase_form 0 ++ (4,2,cg)%N::rest) =
    (2,2,J)%N :: pr ++ phase_form 0 ++ (4,2,cg)%N::post).
  { unfold pr, post.
    rewrite !lin_flat_app_c,
      (flat_phase_form sg 0 H0).
    rewrite lin_flat_master.
    cbn [lin_flat keyb keyi phshape
         gO gZ]. reflexivity. }
  assert (EOutFlat : lin_flat sg wout =
    (2,2,J+27)%N :: pr ++ phase_form 27 ++
      (4,2,cg-3)%N::post).
  { unfold wout, pr, post.
    rewrite !lin_flat_app_c,
      (flat_phase_form sg 27 H27).
    rewrite lin_flat_master.
    cbn [lin_flat keyb keyi phshape
         gO gZ]. reflexivity. }
  assert (ESkip : lin_flat sg (skipn cur wout) =
      (4,2,cg-3)%N :: post).
  { unfold wout, post. rewrite Hcur.
    replace (S (length pre) + 1)%nat with
      (length (((2,2,J+27)%N::pre) ++ phase_form 27))%nat.
    2: { rewrite length_app, phase_form_len by lia.
         change (phase_len 27) with 1%nat.
         cbn [length]. reflexivity. }
    rewrite app_assoc, LineageCascade_skipn_len_app.
    cbn [lin_flat keyb keyi phshape
         gO gZ]. reflexivity. }
  assert (HView : schedule_frame_view
      (lin_sched_child (S (length pre)) 27 3 0 27)
      (lin_flat sg (skipn cur wout))
      (partial_schedule 0 27)
      [(4,2,cg-3)%N] post).
  { unfold schedule_frame_view, lin_sched_child.
    cbv beta zeta. cbn [lsSlot lsTicks lsGap].
    repeat split.
    - unfold lin_sched_slot. lia.
    - unfold delivery_cols, is_col, is_cmf.
      cbn [forallb gO gZ gC].
      destruct ((cg-3 =? 1)%N); reflexivity.
    - rewrite ESkip, partial_schedule_stock.
      cbn [app]. reflexivity. }
  change (scheduled_frame
    (lin_sched_child (S (length pre)) 27 3 0 27)
    sg wout f sg2 w2 f2) in HFrame.
  destruct (scheduled_frame_output
    (lin_sched_child (S (length pre)) 27 3 0 27)
    sg wout f sg2 w2 f2
    (partial_schedule 0 27)
    [(4,2,cg-3)%N] post HFrame HView)
    as (child & HTrips & HFinal).
  assert (EPrefix : lin_flat sg (firstn cur wout) =
      (2,2,J+27)%N :: pr ++ phase_form 27).
  { unfold wout. rewrite Hcur.
    replace (S (length pre) + 1)%nat with
      (length ((2,2,J+27)%N::pre) +
        length (phase_form 27))%nat by reflexivity.
    rewrite firstn_prefix_add,
      firstn_len_app, lin_flat_app_c,
      lin_flat_master,
      (flat_phase_form sg 27 H27).
    unfold pr. reflexivity. }
  change (lin_flat sg2 w2 =
    lin_flat sg (firstn cur wout) ++ [(4,2,cg-3)%N] ++ child)
    in HFinal.
  set (tail2 := pr ++ phase_form 27 ++
    (4,2,cg-3)%N :: child).
  assert (EFinal : lin_flat sg2 w2 = (2,2,J+27)%N :: tail2).
  { unfold tail2. rewrite HFinal, EPrefix. cbn [app]. f_equal.
    exact (eq_sym (app_assoc pr (phase_form 27)
      ((4,2,cg-3)%N::child))). }
  set (b := (cg-3)%N).
  assert (Hb : (FLOOR <= b)%N).
  { unfold b, FLOOR in *. lia. }
  pose proof (partial_interleaved
    0 27 b (repeat None (N.to_nat 27)) pr post child f f2
    ltac:(lia) Hb HCols ltac:(apply repeat_length) HTrips) as HParent.
  rewrite schedule_stock_repeat_none in HParent.
  cbn [app] in HParent.
  replace (0+27)%N with 27%N in HParent by reflexivity.
  replace (b + DBu 0)%N with cg in HParent.
  2: { unfold b, DBu, DBu_tbl,
        FLOOR in *. cbn [nth N.to_nat]. lia. }
  replace (b + DBu 27)%N with (cg-3)%N in HParent.
  2: { change (DBu 27) with 0%N.
       unfold b. lia. }
  pose proof (schedule_trips_nones
    (N.to_nat 27)
    (pr ++ phase_form 0 ++ (4,2,cg)%N::post) f
    (pr ++ phase_form 27 ++ (4,2,cg-3)%N::child) f2
    HParent) as HRun.
  pose proof (deliveries_sdec_left
    (N.to_nat 27)
    (pr ++ phase_form 0 ++ (4,2,cg)%N::post) f
    (pr ++ phase_form 0 ++ (4,2,cg)%N::post) f
    (pr ++ phase_form 27 ++ (4,2,cg-3)%N::child) f2
    eq_refl HRun) as HRun0.
  assert (EEnd : sdec
      (pr ++ phase_form 27 ++ (4,2,cg-3)%N::child) f2 =
      sdec tail2 f2) by (unfold tail2; reflexivity).
  pose proof (deliveries_sdec_right
    (N.to_nat 27)
    (pr ++ phase_form 0 ++ (4,2,cg)%N::post) f
    (pr ++ phase_form 27 ++ (4,2,cg-3)%N::child) f2
    tail2 f2 EEnd HRun0) as HRun2.
  pose proof (deliveries_master_sound
    (N.to_nat 27) J []
    (pr ++ phase_form 0 ++ (4,2,cg)%N::post) f
    tail2 f2 HRun2 eq_refl HJ) as HSound.
  rewrite N2Nat.id in HSound. cbn [app] in HSound.
  rewrite EIn, EFinal. exact HSound.
Qed.
Lemma transfer_scan_delivery_cols : forall xs,
  forallb (fun g => is_col g && negb (is_cmf g) &&
    (3 <=? gO g)%N) xs = true ->
  delivery_cols xs = true.
Proof.
  intros xs H. exact H.
Qed.
Lemma transfer_prefix_delivery_cols : forall h tail i,
  lin_transfer_prefix (h::tail) i = true ->
  delivery_cols (firstn (i-1)%nat tail) = true.
Proof.
  intros h tail i H. unfold lin_transfer_prefix in H.
  exact (transfer_scan_delivery_cols _ H).
Qed.
Lemma tick_cascade_singleton :
  forall sg ps w f fr w3 sg3 ps3 f3,
  stable_guard sg w ->
  lin_guard sg w = true ->
  is_spc (nth O w d0) = false ->
  frame_pos fr ->
  lin_casc_safe_at CFUEL sg ps w f [fr] =
    Some (w3, sg3, ps3, f3) ->
  scheduled_frame fr sg w f sg3 w3 f3 /\
  stable_guard sg3 w3 /\
  lin_guard sg3 w3 = true /\
  is_spc (nth O w3 d0) = false.
Proof.
  intros sg ps w f fr w3 sg3 ps3 f3 HG HGuard HHead HPos HRun.
  destruct (lin_casc_safe_at_work
    CFUEL sg ps w f [fr] w3 sg3 ps3 f3
    HG HGuard HHead ltac:(constructor; [exact HPos|constructor]) HRun)
    as (HWork & HG3 & HGuard3 & HHead3).
  destruct (scheduled_work_inv
    fr [] sg w f sg3 w3 f3 HWork)
    as (sgX & wX & fX & HFrame & HRest).
  inversion HRest; subst.
  split; [exact HFrame|]. split; [exact HG3|]. split; assumption.
Qed.
Lemma app3_tail : forall (A : Type) (a b c d : list A),
  a ++ b ++ c ++ d = (a ++ b ++ c) ++ d.
Proof.
  intros A a b c d.
  rewrite (app_assoc b c d), (app_assoc a (b ++ c) d).
  reflexivity.
Qed.
Lemma app4_tail : forall (A : Type) (a b c d e : list A),
  a ++ b ++ c ++ d ++ e = (a ++ b ++ c ++ d) ++ e.
Proof.
  intros A a b c d e.
  rewrite (app_assoc c d e), (app_assoc b (c ++ d) e),
    (app_assoc a (b ++ c ++ d) e).
  reflexivity.
Qed.
Lemma tick_full_master_scheduled_sound_canon :
  forall sg J pre c cg rest f sg2 w2 f2,
  (1 <= J)%N ->
  (FLOOR <= c)%N ->
  (FLOOR + 3 <= cg)%N ->
  delivery_cols (lin_flat sg pre) = true ->
  scheduled_frame
    (lin_sched_child (S (length pre)) 0 4 0 28)
    sg
    (((2,2,J+28)::pre) ++ phase_form 0 ++ (4,2,c)%N ::
      rung1 (cg-4)%N ++ rest)
    f sg2 w2 f2 ->
  sound_impl
    (lin_flat sg
      (((2,2,J)::pre) ++ rung1 c ++
        phase_form 0 ++ (4,2,cg)%N :: rest)) f
    (lin_flat sg2 w2) f2.
Proof.
  intros sg J pre c cg rest f sg2 w2 f2 HJ Hc Hcg HCols HFrame.
  assert (EOut :
      (((2,2,J+28)::pre) ++ phase_form 0 ++ (4,2,c)%N ::
        rung1 (cg-4)%N ++ rest) =
      ((((2,2,J+28)::pre) ++ phase_form 0 ++ (4,2,c)%N ::
        rung1 (cg-4)%N) ++ rest)).
  { exact (app3_tail bg ((2,2,J+28)%N::pre)
      (phase_form 0)
      ((4,2,c)%N :: rung1 (cg-4)%N) rest). }
  rewrite EOut in HFrame.
  assert (EIn :
      (((2,2,J)::pre) ++ rung1 c ++
        phase_form 0 ++ (4,2,cg)%N :: rest) =
      ((((2,2,J)::pre) ++ rung1 c ++
        phase_form 0 ++ [(4,2,cg)%N]) ++ rest)).
  { exact (app4_tail bg ((2,2,J)%N::pre)
      (rung1 c) (phase_form 0)
      [(4,2,cg)%N] rest). }
  rewrite EIn.
  exact (tick_full_master_scheduled_sound
    sg J pre c cg rest f sg2 w2 f2 HJ Hc Hcg HCols HFrame).
Qed.
Lemma tick_full_master_finish :
  forall sg J pre c cg rest f ps1 w3 sg3 ps3 f3,
  stable_guard sg
    (((2,2,J)::pre) ++ rung1 c ++
      phase_form 0 ++ (4,2,cg)%N :: rest) ->
  (1 <= J)%N ->
  (FLOOR <= c)%N ->
  (FLOOR + 3 <= cg)%N ->
  delivery_cols (lin_flat sg pre) = true ->
  lin_guard_at sg ps1
    (((2,2,J+28)::pre) ++ phase_form 0 ++ (4,2,c)%N ::
      rung1 (cg-4)%N ++ rest) = true ->
  lin_casc_safe_at CFUEL sg ps1
    (((2,2,J+28)::pre) ++ phase_form 0 ++ (4,2,c)%N ::
      rung1 (cg-4)%N ++ rest) f
    [lin_sched_child (S (length pre)) 0 4 0 28] =
    Some (w3, sg3, ps3, f3) ->
  sound_impl
    (lin_flat sg
      (((2,2,J)::pre) ++ rung1 c ++
        phase_form 0 ++ (4,2,cg)%N :: rest)) f
    (lin_flat sg3 w3) f3 /\
  stable_guard sg3 w3 /\
  lin_guard sg3 w3 = true /\
  is_spc (nth O w3 d0) = false.
Proof.
  intros sg J pre c cg rest f ps1 w3 sg3 ps3 f3
    HG HJ Hc Hcg HCols HAt HCasc.
  set (wout := (((2,2,J+28)::pre) ++ phase_form 0 ++
    (4,2,c)%N :: rung1 (cg-4)%N ++ rest)).
  assert (HGm : stable_guard sg
      (((2,2,J+28)::pre) ++ rung1 c ++
        phase_form 0 ++ (4,2,cg)%N :: rest)).
  { change (stable_guard sg
      ((2,2,J+28)::(pre ++ rung1 c ++
        phase_form 0 ++ (4,2,cg)%N::rest))).
    change (stable_guard sg
      ((2,2,J)::(pre ++ rung1 c ++
        phase_form 0 ++ (4,2,cg)%N::rest))) in HG.
    exact (stable_guard_master_change_probe
      sg J (J+28) _ HG). }
  assert (HFront : front_repr sg wout).
  { apply (front_repr_phseq sg
      (((2,2,J+28)::pre) ++ rung1 c ++
        phase_form 0 ++ (4,2,cg)%N::rest) wout HGm).
    unfold wout. exact (phseq_full_cross (J+28) (J+28) pre c cg rest). }
  assert (HGuard : lin_guard sg wout = true).
  { eapply lin_guard_at_sound; [exact (proj1 HFront)|exact HAt]. }
  assert (HStable : stable_guard sg wout).
  { unfold wout. exact (tick_full_master_stable
      sg J pre c cg rest HG HGuard). }
  assert (HHead : is_spc (nth O wout d0) = false).
  { unfold wout. reflexivity. }
  assert (HPos : frame_pos
      (lin_sched_child (S (length pre)) 0 4 0 28)).
  { unfold frame_pos, lin_sched_child.
    change (3 <= S (length pre) + 2)%nat. lia. }
  change (lin_casc_safe_at CFUEL sg ps1 wout f
    [lin_sched_child (S (length pre)) 0 4 0 28] =
    Some (w3,sg3,ps3,f3)) in HCasc.
  destruct (tick_cascade_singleton
    sg ps1 wout f (lin_sched_child (S (length pre)) 0 4 0 28)
    w3 sg3 ps3 f3 HStable HGuard HHead HPos HCasc)
    as (HFrame & HG3 & HGuard3 & HHead3).
  split.
  - exact (tick_full_master_scheduled_sound_canon
      sg J pre c cg rest f sg3 w3 f3 HJ Hc Hcg HCols HFrame).
  - split; [exact HG3|]. split; assumption.
Qed.
Lemma tick_partial_master_finish :
  forall sg J pre cg rest f ps1 w3 sg3 ps3 f3,
  stable_guard sg
    (((2,2,J)::pre) ++ phase_form 0 ++ (4,2,cg)%N :: rest) ->
  (1 <= J)%N -> (1 <= length pre)%nat ->
  (FLOOR + 3 <= cg)%N ->
  delivery_cols (lin_flat sg pre) = true ->
  lin_guard_at sg ps1
    (((2,2,J+27)::pre) ++ phase_form 27 ++
      (4,2,cg-3)%N :: rest) = true ->
  lin_casc_safe_at CFUEL sg ps1
    (((2,2,J+27)::pre) ++ phase_form 27 ++
      (4,2,cg-3)%N :: rest) f
    [lin_sched_child (S (length pre)) 27 3 0 27] =
    Some (w3, sg3, ps3, f3) ->
  sound_impl
    (lin_flat sg
      (((2,2,J)::pre) ++ phase_form 0 ++ (4,2,cg)%N :: rest)) f
    (lin_flat sg3 w3) f3 /\
  stable_guard sg3 w3 /\
  lin_guard sg3 w3 = true /\
  is_spc (nth O w3 d0) = false.
Proof.
  intros sg J pre cg rest f ps1 w3 sg3 ps3 f3
    HG HJ HPre Hcg HCols HAt HCasc.
  set (wout := (((2,2,J+27)::pre) ++ phase_form 27 ++
    (4,2,cg-3)%N::rest)).
  assert (HGm : stable_guard sg
      (((2,2,J+27)::pre) ++ phase_form 0 ++
        (4,2,cg)%N::rest)).
  { change (stable_guard sg
      ((2,2,J+27)::(pre ++ phase_form 0 ++
        (4,2,cg)%N::rest))).
    change (stable_guard sg
      ((2,2,J)::(pre ++ phase_form 0 ++
        (4,2,cg)%N::rest))) in HG.
    exact (stable_guard_master_change_probe
      sg J (J+27) _ HG). }
  assert (HFront : front_repr sg wout).
  { apply (front_repr_phseq sg
      (((2,2,J+27)::pre) ++ phase_form 0 ++
        (4,2,cg)%N::rest) wout HGm).
    unfold wout. exact (phseq_partial_tick (J+27) (J+27) pre cg rest). }
  assert (HGuard : lin_guard sg wout = true).
  { eapply lin_guard_at_sound; [exact (proj1 HFront)|exact HAt]. }
  assert (HStable : stable_guard sg wout).
  { unfold wout. exact (tick_partial_master_stable
      sg J pre cg rest HG HGuard). }
  assert (HHead : is_spc (nth O wout d0) = false).
  { unfold wout. reflexivity. }
  assert (HPos : frame_pos
      (lin_sched_child (S (length pre)) 27 3 0 27)).
  { unfold frame_pos, lin_sched_child.
    change (3 <= S (length pre) + 1)%nat. lia. }
  change (lin_casc_safe_at CFUEL sg ps1 wout f
    [lin_sched_child (S (length pre)) 27 3 0 27] =
    Some (w3,sg3,ps3,f3)) in HCasc.
  destruct (tick_cascade_singleton
    sg ps1 wout f (lin_sched_child (S (length pre)) 27 3 0 27)
    w3 sg3 ps3 f3 HStable HGuard HHead HPos HCasc)
    as (HFrame & HG3 & HGuard3 & HHead3).
  split.
  - exact (tick_partial_master_scheduled_sound
      sg J pre cg rest f sg3 w3 f3 HJ Hcg HCols HFrame).
  - split; [exact HG3|]. split; assumption.
Qed.
Lemma lin_tick_front_at_master_stable :
  forall front sg ps J tail f hint q w3 sg3 ps3 f3 fs,
  stable_guard sg ((2,2,J)::tail) ->
  lin_tick_front_at front sg ps ((2,2,J)::tail) f hint =
    Some (q,w3,sg3,ps3,f3,fs) ->
  sound_impl
    (lin_flat sg ((2,2,J)::tail)) f
    (lin_flat sg3 w3) f3 /\
  stable_guard sg3 w3 /\
  lin_guard sg3 w3 = true /\
  is_spc (nth O w3 d0) = false.
Proof.
  intros front sg ps J tail f hint q w3 sg3 ps3 f3 fs HG HRun.
  unfold lin_tick_front_at in HRun. cbv beta zeta in HRun.
  destruct front as [r|]; [discriminate|].
  destruct (Nat.ltb (length sg) 2 ||
    negb (forallb (fun s => Nat.leb SEGMIN (segl s)) sg))
    eqn:EInit; [discriminate|].
  destruct (negb (f =? 4)) eqn:Ef; [discriminate|].
  cbn [N.eqb Pos.eqb andb] in HRun.
  destruct (negb (1 <=? J)%N) eqn:EJB; [discriminate|].
  apply negb_false_iff in EJB. apply N.leb_le in EJB.
  set (start := if Nat.ltb hint 1 then 1%nat else hint) in *.
  destruct (find_active ((2,2,J)::tail) start)
    as [i|] eqn:EFind; [|discriminate].
  destruct (negb (lin_transfer_prefix ((2,2,J)::tail) i))
    eqn:ECols; [discriminate|].
  apply negb_false_iff in ECols.
  destruct (detect_phase ((2,2,J)::tail) i)
    as [p|] eqn:EPhase; [|discriminate].
  set (q0 := if (Nat.eqb i 7 || Nat.eqb i 6) && (p =? 0)%N
    then 28%N else if Nat.eqb i 5 && (p =? 0)%N then 27%N else 0%N) in *.
  destruct ((q0 =? 0)%N) eqn:EQ0; [discriminate|].
  destruct (lin_tick_front_stage ((2,2,J)::tail) i)
    as [[[[[q1 w1] j2] rem] emit]|] eqn:EStage; [|discriminate].
  destruct (if Nat.eqb i 6
    then lin_at_safe sg w1 j2 else Some w1)
    as [w1'|] eqn:EAtSafe; [|discriminate].
  set (wout := subst_at O 1 [(2,2,J+q1)] w1') in *.
  destruct (relocate_all sg ps wout) as [ps1|]
    eqn:ELocate; [|discriminate].
  destruct (lin_guard_at sg ps1 wout) eqn:EAt;
    [|discriminate].
  destruct (lin_casc_safe_at CFUEL sg ps1 wout f
    [lin_sched_child j2 rem emit p q1])
    as [[[[wC sgC] psC] fC]|] eqn:ECasc; [|discriminate].
  injection HRun as <- <- <- <- <- <-.
  pose proof HG as HG0.
  assert (HAlt : forall s, In s sg ->
      altb (sBody s) = true)
    by (exact (stable_altb sg ((2,2,J)::tail) HG0)).
  destruct (tick_stage_site ((2,2,J)::tail) i q1 w1 j2 rem emit EStage)
    as [Ei|[Ei|Ei]]; subst i.
  - unfold q0 in EQ0. cbn [Nat.eqb] in EQ0.
    destruct p as [|pp]; [|discriminate].
    destruct (tick_stage_5 ((2,2,J)::tail) q1 w1 j2 rem emit EStage)
      as [a0 a1 a2 a3 a4 cg rest HIn HOut HRest Hcg Hq Hj Hr He].
    injection HIn as Ea0 Etail. subst a0 tail q1 j2 rem emit.
    cbn [Nat.eqb] in EAtSafe. injection EAtSafe as <-.
    assert (EWord : wout =
        (((2,2,J+27)::[a1;a2;a3;a4]) ++ phase_form 27 ++
          (4,2,cg-3)%N::rest)).
    { unfold wout. rewrite HOut. reflexivity. }
    rewrite EWord in EAt, ECasc.
    assert (HRaw : delivery_cols [a1;a2;a3;a4] = true).
    { pose proof (transfer_prefix_delivery_cols
        (2,2,J)%N
        (a1::a2::a3::a4::(7,1,1)%N::(3,2,1)%N::
          (4,2,cg)%N::rest) 5 ECols) as H.
      exact H. }
    assert (HFlat : delivery_cols
        (lin_flat sg [a1;a2;a3;a4]) = true).
    { exact (lin_flat_delivery_cols
        sg [a1;a2;a3;a4] HRaw HAlt). }
    change (stable_guard sg
      (((2,2,J)::[a1;a2;a3;a4]) ++ phase_form 0 ++
        (4,2,cg)%N::rest)) in HG.
    exact (tick_partial_master_finish
      sg J [a1;a2;a3;a4] cg rest f ps1 wC sgC psC fC
      HG EJB ltac:(cbn [length]; lia) Hcg HFlat EAt ECasc).
  - unfold q0 in EQ0. cbn [Nat.eqb] in EQ0.
    destruct p as [|pp]; [|discriminate].
    destruct (tick_stage_6 ((2,2,J)::tail) q1 w1 j2 rem emit
      EPhase EStage)
      as (a0 & a1 & a2 & a3 & c & cg & rest & HIn & HOut & HRest &
          Hc & Hcg & Hq & Hj & Hr & He).
    injection HIn as Ea0 Etail. subst a0 tail q1 j2 rem emit.
    pose proof (lin_at_safe_some sg w1 4 w1' EAtSafe)
      as Ew1'. subst w1'.
    assert (EWord : wout =
        (((2,2,J+28)::[a1;a2;a3]) ++ phase_form 0 ++
          (4,2,c)%N :: rung1 (cg-4)%N ++ rest)).
    { unfold wout. rewrite HOut. reflexivity. }
    rewrite EWord in EAt, ECasc.
    assert (HRawAll : delivery_cols
        ([a1;a2;a3] ++ rung1 c) = true).
    { pose proof (transfer_prefix_delivery_cols
        (2,2,J)%N
        (a1::a2::a3::(8,2,1)%N::(4,2,c)%N::
          (7,1,1)%N::(3,2,1)%N::(4,2,cg)%N::rest) 6 ECols) as H.
      exact H. }
    rewrite delivery_cols_app in HRawAll.
    apply andb_prop in HRawAll as [HRaw _].
    assert (HFlat : delivery_cols
        (lin_flat sg [a1;a2;a3]) = true).
    { exact (lin_flat_delivery_cols
        sg [a1;a2;a3] HRaw HAlt). }
    change (stable_guard sg
      (((2,2,J)::[a1;a2;a3]) ++ rung1 c ++
        phase_form 0 ++ (4,2,cg)%N::rest)) in HG.
    exact (tick_full_master_finish
      sg J [a1;a2;a3] c cg rest f ps1 wC sgC psC fC
      HG EJB Hc Hcg HFlat EAt ECasc).
  - unfold q0 in EQ0. cbn [Nat.eqb] in EQ0.
    destruct p as [|pp]; [|discriminate].
    destruct (tick_stage_7 ((2,2,J)::tail) q1 w1 j2 rem emit EStage)
      as [a0 a1 a2 a3 a4 c cg rest HIn HOut HRest Hc Hcg Hq Hj Hr He].
    injection HIn as Ea0 Etail. subst a0 tail q1 j2 rem emit.
    cbn [Nat.eqb] in EAtSafe. injection EAtSafe as <-.
    assert (EWord : wout =
        (((2,2,J+28)::[a1;a2;a3;a4]) ++ phase_form 0 ++
          (4,2,c)%N :: rung1 (cg-4)%N ++ rest)).
    { unfold wout. rewrite HOut. reflexivity. }
    rewrite EWord in EAt, ECasc.
    assert (HRawAll : delivery_cols
        ([a1;a2;a3;a4] ++ rung1 c) = true).
    { pose proof (transfer_prefix_delivery_cols
        (2,2,J)%N
        (a1::a2::a3::a4::(8,2,1)%N::(4,2,c)%N::
          (7,1,1)%N::(3,2,1)%N::(4,2,cg)%N::rest) 7 ECols) as H.
      exact H. }
    rewrite delivery_cols_app in HRawAll.
    apply andb_prop in HRawAll as [HRaw _].
    assert (HFlat : delivery_cols
        (lin_flat sg [a1;a2;a3;a4]) = true).
    { exact (lin_flat_delivery_cols
        sg [a1;a2;a3;a4] HRaw HAlt). }
    change (stable_guard sg
      (((2,2,J)::[a1;a2;a3;a4]) ++ rung1 c ++
        phase_form 0 ++ (4,2,cg)%N::rest)) in HG.
    exact (tick_full_master_finish
      sg J [a1;a2;a3;a4] c cg rest f ps1 wC sgC psC fC
      HG EJB Hc Hcg HFlat EAt ECasc).
Qed.
Lemma lin_tick_front_at_stable :
  forall front sg ps w f hint q w3 sg3 ps3 f3 fs,
  stable_guard sg w ->
  lin_tick_front_at front sg ps w f hint =
    Some (q,w3,sg3,ps3,f3,fs) ->
  sound_impl (lin_flat sg w) f
    (lin_flat sg3 w3) f3 /\
  stable_guard sg3 w3 /\
  lin_guard sg3 w3 = true /\
  is_spc (nth O w3 d0) = false.
Proof.
  intros front sg ps w f hint q w3 sg3 ps3 f3 fs HG HRun.
  pose proof HRun as HShape.
  unfold lin_tick_front_at in HShape. cbv beta zeta in HShape.
  destruct front as [r|]; [discriminate|].
  destruct (Nat.ltb (length sg) 2 ||
    negb (forallb (fun s => Nat.leb SEGMIN (segl s)) sg));
    [discriminate|].
  destruct (negb (f =? 4)); [discriminate|].
  destruct w as [|[[o z] J] tail]; [discriminate|].
  destruct o as [|op]; cbn in HShape; try discriminate.
  destruct op as [op1|op1|]; cbn in HShape; try discriminate.
  destruct op1 as [op2|op2|]; cbn in HShape; try discriminate.
  destruct z as [|zp]; cbn in HShape; try discriminate.
  destruct zp as [zp1|zp1|]; cbn in HShape; try discriminate.
  destruct zp1 as [zp2|zp2|]; cbn in HShape; try discriminate.
  change (stable_guard sg ((2,2,J)::tail)) in HG.
  change (lin_tick_front_at None sg ps ((2,2,J)::tail) f hint =
    Some (q,w3,sg3,ps3,f3,fs)) in HRun.
  exact (lin_tick_front_at_master_stable
    None sg ps J tail f hint q w3 sg3 ps3 f3 fs HG HRun).
Qed.
Open Scope N_scope.
Open Scope bool_scope.
Opaque LROUND_FUEL LROUND_CHUNKS
       FLAT_ROUND_FUEL CFUEL TRIES.
Opaque lin_normalize_full.
Definition T_front_close_stable_full : Prop :=
  forall sg cw f q cw2 f2,
    stable_guard sg cw ->
    lin_front_close cw f = Some (q, cw2, f2) ->
    sound_impl (lin_flat sg cw) f
      (lin_flat sg cw2) f2 /\
    stable_guard sg cw2.
Theorem T_front_close_stable_full_holds : T_front_close_stable_full.
Proof.
  intros sg cw f q cw2 f2
    (HR & HE & HW & HS & HK & HP) HC.
  destruct (T_front_close_stable_holds
    sg cw f q cw2 f2 HR HC) as ((HSound & HR2) & HEdges).
  split; [exact HSound|].
  split; [exact HR2|].
  split; [exact (HEdges HE)|].
  split; [exact HW|]. split; [exact HS|]. split; assumption.
Qed.
Lemma lin_step_post_settled : forall front sg ps w i sg2 ps2 w2 i2,
  stable_guard sg w ->
  lin_step_post front sg ps w i = Some (sg2, ps2, w2, i2) ->
  lin_flat sg2 w2 = lin_flat sg w /\
  lin_guard sg2 w2 = true /\
  stable_guard sg2 w2.
Proof.
  intros front sg ps w i sg2 ps2 w2 i2 HG H.
  destruct front as [r|].
  - unfold lin_step_post in H. cbv beta zeta in H.
    destruct (lin_fixup_at sg ps w [])
      as [[[[sgA psA] wA] stA]|] eqn:EF; [|discriminate].
    injection H as <- <- <- <-.
    exact (lin_fixup_at_stable
      sg ps w [] sgA psA wA stA HG EF).
  - unfold lin_step_post, lin_micro_post in H.
    destruct (lin_near_at ps i GUARD) eqn:EN;
      cbv beta zeta in H.
    + destruct (lin_fixup_at sg ps w [])
        as [[[[sgA psA] wA] stA]|] eqn:EF; [|discriminate].
      injection H as <- <- <- <-.
      exact (lin_fixup_at_stable
        sg ps w [] sgA psA wA stA HG EF).
    + destruct (lin_guard_at sg ps w) eqn:EGA;
        cbv beta zeta in H.
      * injection H as <- <- <- <-. split; [reflexivity|]. split.
        -- exact (lin_guard_at_sound
             sg ps w (proj1 (proj1 HG)) EGA).
        -- exact HG.
      * destruct (lin_fixup_at sg ps w [])
          as [[[[sgA psA] wA] stA]|] eqn:EF; [|discriminate].
        injection H as <- <- <- <-.
        exact (lin_fixup_at_stable
          sg ps w [] sgA psA wA stA HG EF).
Qed.
Open Scope list.
Opaque LROUND_FUEL LROUND_CHUNKS
       FLAT_ROUND_FUEL CFUEL TRIES.
Definition settled (sg : list seg) (cw : word) : Prop :=
  stable_guard sg cw /\
  lin_guard sg cw = true.
Definition round_out (sg : list seg) (cw : word) (f : N)
    (sg2 : list seg) (cw2 : word) (f2 : N)
    (stop : lrstop) : Prop :=
  match stop with
  | LRFuel =>
      sound_impl (lin_flat sg cw) f
        (lin_flat sg2 cw2) f2 /\ settled sg2 cw2
  | LRMore =>
      sound_impl (lin_flat sg cw) f
        (lin_flat sg2 cw2) f2
  | LRClosed =>
      sound_impl (lin_flat sg cw) f
        (lin_flat sg2 cw2) f2 /\
      stable_guard sg2 cw2
  | LRHalt =>
      halts tmB (wconf [] 0 (sdecode (lin_flat sg cw) f))
  end.
Lemma round_out_pre sg cw f sg1 cw1 f1 sg2 cw2 f2 stop :
  sound_impl (lin_flat sg cw) f
    (lin_flat sg1 cw1) f1 ->
  round_out sg1 cw1 f1 sg2 cw2 f2 stop ->
  round_out sg cw f sg2 cw2 f2 stop.
Proof.
  intros HS Hout. destruct stop; cbn in Hout |- *.
  - destruct Hout as [H1 H2].
    split; [exact (sound_trans _ _ _ _ _ _ HS H1)|exact H2].
  - exact (sound_trans _ _ _ _ _ _ HS Hout).
  - destruct Hout as [H1 H2].
    split; [exact (sound_trans _ _ _ _ _ _ HS H1)|exact H2].
  - exact (HS Hout).
Qed.
Lemma run_round_out :
  forall fu sg ps cw f h jc n m sg2 ps2 cw2 f2 h2 jc2 n2 m2 stop,
    settled sg cw ->
    lin_run_round fu sg ps cw f h jc n m =
      (sg2, ps2, cw2, f2, h2, jc2, n2, m2, stop) ->
    round_out sg cw f sg2 cw2 f2 stop.
Proof.
  induction fu as [|fu IH];
    intros sg ps cw f h jc n m sg2 ps2 cw2 f2 h2 jc2 n2 m2 stop
      HSet Hrun;
    cbn [lin_run_round] in Hrun;
    cbv beta zeta iota in Hrun.
  all: destruct HSet as [HG HGuard].
  - inversion Hrun;
      subst sg2 ps2 cw2 f2 h2 jc2 n2 m2 stop.
    cbn. split; [exact (sound_refl _ _)|].
    split; assumption.
  - set (fr := (if lin_front_possible cw
                then first_rule front_rules cw f
                else None)) in Hrun.
    destruct (lin_front_close cw f)
      as [[[qF cwF] fF]|] eqn:EFC.
    + destruct (relocate_all sg ps cwF) as [psF|] eqn:ERel.
      * lazymatch type of Hrun with
        | context [if ?late then _ else _] => destruct late eqn:ELate
        end;
          cbv beta zeta iota in Hrun;
          inversion Hrun; subst sg2 ps2 cw2 f2 h2 jc2 n2 m2 stop;
          cbn; exact (T_front_close_stable_full_holds
            sg cw f qF cwF fF HG EFC).
      * inversion Hrun; subst sg2 ps2 cw2 f2 h2 jc2 n2 m2 stop.
        cbn. exact (sound_refl _ _).
    + destruct (lin_gen_action_at fr sg ps cw f h)
        as [og|] eqn:EGen.
      * destruct og as [[[[[[tG cwG] sgG] psG] fG] fsG]|].
        -- destruct (lin_gen_action_at_stable
             fr sg ps cw f h tG cwG sgG psG fG fsG HG EGen)
             as (HSg & HGg & HGuardg & _).
           exact (round_out_pre _ _ _ _ _ _ _ _ _ _ HSg
                    (IH _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _
                       (conj HGg HGuardg) Hrun)).
        -- destruct (lin_halt_probe fr sg cw f h) eqn:EP.
           ++ destruct (fst (lin_halt_confirm sg cw f)) eqn:EC.
              ** inversion Hrun; subst sg2 ps2 cw2 f2 h2 jc2 n2 m2 stop.
                 cbn. exact (splice_halt_confirmed sg cw f EC).
              ** inversion Hrun; subst sg2 ps2 cw2 f2 h2 jc2 n2 m2 stop.
                 cbn. exact (sound_refl _ _).
           ++ inversion Hrun; subst sg2 ps2 cw2 f2 h2 jc2 n2 m2 stop.
              cbn. exact (sound_refl _ _).
      * destruct (if lin_tick_front_due cw
                    then lin_tick_front_at fr sg ps cw f h
                    else None)
          as [[[[[[qT cwT] sgT] psT] fT] fsT]|] eqn:ETF.
        -- destruct (lin_tick_front_due cw) eqn:EDue.
           ++ cbn in ETF.
              destruct (lin_tick_front_at_stable
                fr sg ps cw f h qT cwT sgT psT fT fsT HG ETF)
                as (HSt & HGt & HGuardt & _).
              exact (round_out_pre _ _ _ _ _ _ _ _ _ _ HSt
                       (IH _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _
                          (conj HGt HGuardt) Hrun)).
           ++ cbn in ETF. discriminate.
        -- destruct (lin_micro_action_guard fr cw h) eqn:EMicro.
           2:{ inversion Hrun; subst sg2 ps2 cw2 f2 h2 jc2 n2 m2 stop.
               cbn. exact (sound_refl _ _). }
           destruct (step_after_front_with_guard false
             (lin_normalize_at sg)
             (fun pre sfx _ => lin_normalize_join sg pre sfx)
             fr cw f h) as [[wS fS| |] iS] eqn:ESP.
           ++ destruct (lin_splice_arm_guard fr cw iS) eqn:EGA.
              ** destruct (relocate_all sg ps wS)
                   as [psS|] eqn:EPS.
                 --- destruct (splice_stable
                       sg cw f h wS fS iS HG HGuard ESP)
                       as (HSs & HGs).
                     destruct (lin_round_closing cw f) eqn:ECl.
                     +++ inversion Hrun;
                           subst sg2 ps2 cw2 f2 h2 jc2 n2 m2 stop.
                         cbn. split; assumption.
                     +++ destruct (lin_step_post fr sg psS wS iS)
                           as [[[[sgP psP] cwP] iP]|] eqn:EPost.
                         *** destruct (lin_step_post_settled
                               fr sg psS wS iS sgP psP cwP iP HGs EPost)
                               as (HFlat & HGuardP & HGp).
                             assert (HSPost : sound_impl
                               (lin_flat sg wS) fS
                               (lin_flat sgP cwP) fS).
                             { unfold sound_impl.
                               rewrite HFlat. exact (fun H => H). }
                             pose proof (sound_trans
                               _ _ _ _ _ _ HSs HSPost) as HSs2.
                             exact (round_out_pre _ _ _ _ _ _ _ _ _ _ HSs2
                               (IH _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _
                                  (conj HGp HGuardP) Hrun)).
                         *** inversion Hrun;
                               subst sg2 ps2 cw2 f2 h2 jc2 n2 m2 stop.
                             cbn. exact (sound_refl _ _).
                 --- inversion Hrun;
                       subst sg2 ps2 cw2 f2 h2 jc2 n2 m2 stop.
                     cbn. exact (sound_refl _ _).
              ** inversion Hrun; subst sg2 ps2 cw2 f2 h2 jc2 n2 m2 stop.
                 cbn. exact (sound_refl _ _).
           ++ destruct (fst (lin_halt_confirm sg cw f)) eqn:EC.
              ** inversion Hrun; subst sg2 ps2 cw2 f2 h2 jc2 n2 m2 stop.
                 cbn. exact (splice_halt_confirmed sg cw f EC).
              ** inversion Hrun; subst sg2 ps2 cw2 f2 h2 jc2 n2 m2 stop.
                 cbn. exact (sound_refl _ _).
           ++ inversion Hrun; subst sg2 ps2 cw2 f2 h2 jc2 n2 m2 stop.
              cbn. exact (sound_refl _ _).
Qed.
Lemma run_chunked_out :
  forall chunks sg ps cw f h jc n m sg2 ps2 cw2 f2 jc2 n2 m2 stop,
    settled sg cw ->
    lin_run_round_chunked chunks sg ps cw f h jc n m =
      (sg2, ps2, cw2, f2, jc2, n2, m2, stop) ->
    round_out sg cw f sg2 cw2 f2 stop.
Proof.
  induction chunks as [|ch IH];
    intros sg ps cw f h jc n m sg2 ps2 cw2 f2 jc2 n2 m2 stop HSet Hrun;
    cbn [lin_run_round_chunked] in Hrun.
  - inversion Hrun; subst sg2 ps2 cw2 f2 jc2 n2 m2 stop.
    cbn. exact (sound_refl _ _).
  - destruct (lin_run_round LROUND_FUEL
        sg ps cw f h jc n m)
      as [[[[[[[[sgR psR] cwR] fR] hR] jcR] nR] mR] stopR] eqn:ER.
    pose proof (run_round_out _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _
                  HSet ER) as HR.
    destruct stopR.
    + destruct HR as [HSr HSetR].
      exact (round_out_pre _ _ _ _ _ _ _ _ _ _ HSr
               (IH _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ HSetR Hrun)).
    + inversion Hrun; subst sg2 ps2 cw2 f2 jc2 n2 m2 stop. exact HR.
    + inversion Hrun; subst sg2 ps2 cw2 f2 jc2 n2 m2 stop. exact HR.
    + inversion Hrun; subst sg2 ps2 cw2 f2 jc2 n2 m2 stop. exact HR.
Qed.
Definition lp_stable (s : lpstate) : Prop :=
  match s with
  | LPFlat _ _ _ => True
  | LPCond sg _ cw _ _ _ => settled sg cw
  end.
Definition lp_halts (s : lpstate) : Prop :=
  let '(w, f, _) := lp_sem s in
  halts tmB (wconf [] 0 (sdecode w f)).
Definition lp_sound_impl (s s' : lpstate) : Prop :=
  let '(w, f, _) := lp_sem s in
  let '(w', f', _) := lp_sem s' in
  sound_impl w f w' f'.
Lemma fallback_lps_next_stable w f h k m s' :
  lps_of_lpnext (lp_fallback_round w f h) =
    LPSNext k m s' ->
  lp_stable s' /\
  (let '(w', f', _) := lp_sem s' in
   sound_impl w f w' f').
Proof.
  unfold lp_fallback_round. intros H.
  destruct (lp_fallback_round_run FLAT_ROUND_FUEL
      None w f h nc0 O) as [k1 m1 s1|k1 m1 w1 f1|k1 m1 w1 f1] eqn:EF;
    cbn [lps_of_lpnext] in H; try discriminate.
  inversion H; subst k m s1.
  destruct (fallback_run_next _ _ _ _ _ _ _ _ _ _ EF)
    as (w' & f' & h' & -> & HS).
  split; [exact I|]. cbn [lp_sem]. exact HS.
Qed.
Lemma fallback_lps_guard_stable w f h k m len fg lm :
  lps_of_lpnext (lp_fallback_round w f h) =
    LPSGuard k m len fg lm ->
  halts tmB (wconf [] 0 (sdecode w f)).
Proof.
  exact (fallback_lps_guard w f h k m len fg lm).
Qed.
Lemma lr_continue_next_stable :
  forall sg cw f jc k m k' m' s',
    lr_continue_flat sg cw f jc k m =
      Some (LPNext k' m' s') ->
    lp_stable s' /\
    exists w' f' h', lp_sem s' = (w', f', h') /\
      sound_impl (lin_flat sg cw) f w' f'.
Proof.
  intros sg cw f jc k m k' m' s' Hrun.
  unfold lr_continue_flat in Hrun. cbv beta zeta iota in Hrun.
  destruct (Nat.eqb m O); [discriminate|].
  destruct (negb (lin_post_full sg cw)); [discriminate|].
  set (res := lp_fallback_round_run FLAT_ROUND_FUEL
         None (lin_flat sg cw) f
         (hint_of (fmapw sg cw O O jc)) k m) in Hrun.
  injection Hrun. intros Hfb.
  unfold res in Hfb. clear Hrun res.
  destruct (fallback_run_next _ _ _ _ _ _ _ _ _ _ Hfb)
    as (w' & f' & h' & -> & HS).
  split; [exact I|]. do 3 eexists. split; [reflexivity|exact HS].
Qed.
Lemma lr_continue_guard_stable :
  forall sg cw f jc k m k' m' len fg,
    lr_continue_flat sg cw f jc k m =
      Some (LPGuard k' m' len fg) ->
    halts tmB (wconf [] 0 (sdecode (lin_flat sg cw) f)).
Proof.
  intros sg cw f jc k m k' m' len fg Hrun.
  unfold lr_continue_flat in Hrun. cbv beta zeta iota in Hrun.
  destruct (Nat.eqb m O); [discriminate|].
  destruct (negb (lin_post_full sg cw)); [discriminate|].
  set (res := lp_fallback_round_run FLAT_ROUND_FUEL
         None (lin_flat sg cw) f
         (hint_of (fmapw sg cw O O jc)) k m) in Hrun.
  injection Hrun. intros Hfb.
  unfold res in Hfb. clear Hrun res.
  exact (fallback_run_guard _ _ _ _ _ _ _ _ _ _ _ Hfb).
Qed.
Lemma lr_accept_next_stable :
  forall sg ps cw f jc k m r,
    stable_guard sg cw ->
    lr_accept true sg ps cw f jc k m = Some r ->
    exists k' m' s', r = LPNext k' m' s' /\
      lp_stable s' /\
      exists h', lp_sem s' = (lin_flat sg cw, f, h').
Proof.
  intros sg ps cw f jc k m r HG Hacc.
  unfold lr_accept in Hacc. cbv beta zeta iota in Hacc.
  destruct (Nat.eqb m O); [discriminate|].
  cbn [orb] in Hacc.
  destruct (lin_repack_when_needed sg ps cw)
    as [[[sg3 ps3] cw3]|] eqn:ERep; [|discriminate].
  destruct (T_repack_stable_holds
    sg ps cw sg3 ps3 cw3 HG ERep) as (HFl & HGuard3 & HG3).
  destruct (negb (lin_ok sg3 cw3)); [discriminate|].
  destruct sg3 as [|s0 sg3'] eqn:Esg3.
  - inversion Hacc; subst r. do 3 eexists.
    split; [reflexivity|]. split; [exact I|].
    eexists. cbn [lp_sem].
    rewrite <- HFl, lin_flat_nil. reflexivity.
  - inversion Hacc; subst r. do 3 eexists.
    split; [reflexivity|]. split.
    + cbn [lp_stable settled]. split; assumption.
    + eexists. cbn [lp_sem]. rewrite HFl. reflexivity.
Qed.
Lemma continue_or_fallback_next_stable
    sg2 cw2 f2 j2 k0 m0 wfb ffb hfb k m s' :
  (match lr_continue_flat sg2 cw2 f2 j2 k0 m0 with
   | Some r => lps_of_lpnext r
   | None => lps_of_lpnext (lp_fallback_round wfb ffb hfb)
   end) = LPSNext k m s' ->
  lp_stable s' /\
  (let '(w', f', _) := lp_sem s' in
   sound_impl (lin_flat sg2 cw2) f2 w' f' \/
   sound_impl wfb ffb w' f').
Proof.
  intros H.
  destruct (lr_continue_flat sg2 cw2 f2 j2 k0 m0)
    as [r|] eqn:ECo.
  - destruct r as [k1 m1 s1|k1 m1 w1 f1|k1 m1 w1 f1];
      cbn [lps_of_lpnext] in H; try discriminate.
    inversion H; subst k m s1.
    destruct (lr_continue_next_stable _ _ _ _ _ _ _ _ _ ECo)
      as [HStable (w' & f' & h' & Hsem & HS)].
    split; [exact HStable|]. rewrite Hsem. left. exact HS.
  - destruct (fallback_lps_next_stable _ _ _ _ _ _ H)
      as [HStable HS].
    split; [exact HStable|].
    destruct (lp_sem s') as [[w' f'] h'].
    right. exact HS.
Qed.
Lemma continue_or_fallback_guard_stable
    sg2 cw2 f2 j2 k0 m0 wfb ffb hfb k m len fg lm :
  (match lr_continue_flat sg2 cw2 f2 j2 k0 m0 with
   | Some r => lps_of_lpnext r
   | None => lps_of_lpnext (lp_fallback_round wfb ffb hfb)
   end) = LPSGuard k m len fg lm ->
  halts tmB (wconf [] 0 (sdecode (lin_flat sg2 cw2) f2)) \/
  halts tmB (wconf [] 0 (sdecode wfb ffb)).
Proof.
  intros H.
  destruct (lr_continue_flat sg2 cw2 f2 j2 k0 m0)
    as [r|] eqn:ECo.
  - destruct r as [k1 m1 s1|k1 m1 w1 f1|k1 m1 w1 f1];
      cbn [lps_of_lpnext] in H; try discriminate.
    left. exact (lr_continue_guard_stable _ _ _ _ _ _ _ _ _ _ ECo).
  - right. exact (fallback_lps_guard_stable _ _ _ _ _ _ _ _ H).
Qed.
Lemma accept_or_fallback_next_stable
    sg2 ps2 cw2 f2 j2 k0 m0 wfb ffb hfb k m s' :
  stable_guard sg2 cw2 ->
  (match lr_accept true sg2 ps2 cw2 f2 j2 k0 m0 with
   | Some r => lps_of_lpnext r
   | None => lps_of_lpnext (lp_fallback_round wfb ffb hfb)
   end) = LPSNext k m s' ->
  lp_stable s' /\
  (let '(w', f', _) := lp_sem s' in
   sound_impl (lin_flat sg2 cw2) f2 w' f' \/
   sound_impl wfb ffb w' f').
Proof.
  intros HG H.
  destruct (lr_accept true sg2 ps2 cw2 f2 j2 k0 m0)
    as [r|] eqn:EAcc.
  - destruct (lr_accept_next_stable _ _ _ _ _ _ _ _ HG EAcc)
      as (k1 & m1 & s1 & -> & HStable & h' & Hsem).
    cbn [lps_of_lpnext] in H.
    inversion H; subst k m s1.
    split; [exact HStable|]. rewrite Hsem.
    left. exact (sound_refl _ _).
  - destruct (fallback_lps_next_stable _ _ _ _ _ _ H)
      as [HStable HS].
    split; [exact HStable|].
    destruct (lp_sem s') as [[w' f'] h'].
    right. exact HS.
Qed.
Lemma accept_or_fallback_guard_stable
    sg2 ps2 cw2 f2 j2 k0 m0 wfb ffb hfb k m len fg lm :
  stable_guard sg2 cw2 ->
  (match lr_accept true sg2 ps2 cw2 f2 j2 k0 m0 with
   | Some r => lps_of_lpnext r
   | None => lps_of_lpnext (lp_fallback_round wfb ffb hfb)
   end) = LPSGuard k m len fg lm ->
  halts tmB (wconf [] 0 (sdecode wfb ffb)).
Proof.
  intros HG H.
  destruct (lr_accept true sg2 ps2 cw2 f2 j2 k0 m0)
    as [r|] eqn:EAcc.
  - destruct (lr_accept_next_stable _ _ _ _ _ _ _ _ HG EAcc)
      as (k1 & m1 & s1 & -> & HStable & h' & Hsem).
    cbn [lps_of_lpnext] in H. discriminate.
  - exact (fallback_lps_guard_stable _ _ _ _ _ _ _ _ H).
Qed.
Theorem linstep_next_stable :
  forall s k m s',
    lp_stable s ->
    linstep s = LPSNext k m s' ->
    lp_stable s' /\ lp_sound_impl s s'.
Proof.
  intros s k m s' HStable Hstep.
  destruct s as [w f h|sg ps cw f h j].
  - unfold linstep in Hstep.
    destruct (lin_cond w h) as [[[cw0 sg0] h0]|] eqn:EC.
    2: { destruct (fallback_lps_next_stable _ _ _ _ _ _ Hstep)
           as [HStable' HS].
         split; [exact HStable'|]. exact HS. }
    destruct (locate_all sg0 cw0) as [ps0|] eqn:EL.
    2: { destruct (fallback_lps_next_stable _ _ _ _ _ _ Hstep)
           as [HStable' HS].
         split; [exact HStable'|]. exact HS. }
    destruct (T_cond_stable_holds w h cw0 sg0 h0 EC)
      as [HFlat HG0].
    destruct (T_cond_holds w h cw0 sg0 h0 EC)
      as (_ & _ & HGuard0 & _ & _).
    destruct (lin_run_round_chunked LROUND_CHUNKS
        sg0 ps0 cw0 f h0 O nc0 O)
      as [[[[[[[sgR psR] cwR] fR] jR] nR] mR] stopR] eqn:ER.
    pose proof (run_chunked_out _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _
                  (conj HG0 HGuard0) ER) as HR.
    destruct stopR.
    + destruct HR as [HS _].
      destruct (continue_or_fallback_next_stable
          sgR cwR fR jR nR mR w f h k m s' Hstep)
        as [HStable' HD].
      split; [exact HStable'|].
      unfold lp_sound_impl. cbn [lp_sem].
      destruct (lp_sem s') as [[w' f'] h'].
      destruct HD as [HD|HD].
      * rewrite <- HFlat.
        exact (sound_trans _ _ _ _ _ _ HS HD).
      * exact HD.
    + destruct (continue_or_fallback_next_stable
          sgR cwR fR jR nR mR w f h k m s' Hstep)
        as [HStable' HD].
      split; [exact HStable'|].
      unfold lp_sound_impl. cbn [lp_sem].
      destruct (lp_sem s') as [[w' f'] h'].
      destruct HD as [HD|HD].
      * rewrite <- HFlat.
        exact (sound_trans _ _ _ _ _ _ HR HD).
      * exact HD.
    + destruct HR as [HS HG2].
      destruct (accept_or_fallback_next_stable
          sgR psR cwR fR jR nR mR w f h k m s' HG2 Hstep)
        as [HStable' HD].
      split; [exact HStable'|].
      unfold lp_sound_impl. cbn [lp_sem].
      destruct (lp_sem s') as [[w' f'] h'].
      destruct HD as [HD|HD].
      * rewrite <- HFlat.
        exact (sound_trans _ _ _ _ _ _ HS HD).
      * exact HD.
    + discriminate.
  - cbn [lp_stable] in HStable.
    pose proof HStable as HG.
    unfold linstep in Hstep.
    destruct (lin_run_round_chunked LROUND_CHUNKS
        sg ps cw f h (hmapw sg cw O O j) nc0 O)
      as [[[[[[[sgR psR] cwR] fR] jR] nR] mR] stopR] eqn:ER.
    pose proof (run_chunked_out _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _
                  HG ER) as HR.
    destruct stopR.
    + destruct HR as [HS _].
      destruct (continue_or_fallback_next_stable
          sgR cwR fR jR nR mR (lin_flat sg cw) f
          (hint_of j) k m s' Hstep) as [HStable' HD].
      split; [exact HStable'|].
      unfold lp_sound_impl. cbn [lp_sem].
      destruct (lp_sem s') as [[w' f'] h'].
      destruct HD as [HD|HD].
      * exact (sound_trans _ _ _ _ _ _ HS HD).
      * exact HD.
    + destruct (continue_or_fallback_next_stable
          sgR cwR fR jR nR mR (lin_flat sg cw) f
          (hint_of j) k m s' Hstep) as [HStable' HD].
      split; [exact HStable'|].
      unfold lp_sound_impl. cbn [lp_sem].
      destruct (lp_sem s') as [[w' f'] h'].
      destruct HD as [HD|HD].
      * exact (sound_trans _ _ _ _ _ _ HR HD).
      * exact HD.
    + destruct HR as [HS HG2].
      destruct (accept_or_fallback_next_stable
          sgR psR cwR fR jR nR mR (lin_flat sg cw) f
          (hint_of j) k m s' HG2 Hstep) as [HStable' HD].
      split; [exact HStable'|].
      unfold lp_sound_impl. cbn [lp_sem].
      destruct (lp_sem s') as [[w' f'] h'].
      destruct HD as [HD|HD].
      * exact (sound_trans _ _ _ _ _ _ HS HD).
      * exact HD.
    + discriminate.
Qed.
