Lemma front_finishc (sg : list seg) (P Q t : word)
      (f : N) (d : cost) :
  forallb nobase P = true ->
  forallb nobase Q = true ->
  sound_impl_c d (P ++ lin_flat sg t) f
                 (Q ++ lin_flat sg t) f ->
  creach d
    (wconf [] 0 (sdecode (lin_flat sg (P ++ t)) f))
    (wconf [] 0 (sdecode (lin_flat sg
                            (lin_normalize_full (Q ++ t))) f)).
Proof.
  intros HP HQ HS. unfold sound_impl_c in HS.
  rewrite (flat_nobase_app sg P t HP).
  rewrite (flat_lin_normalize_full_sd sg (Q ++ t) f).
  rewrite (flat_nobase_app sg Q t HQ).
  exact HS.
Qed.
Lemma nobase_Qclean (K : N) :
  forallb nobase (Qclean K) = true.
Proof. unfold Qclean. destruct (N.odd K); reflexivity. Qed.
Lemma nobase_Qfour (n M : N) :
  forallb nobase (Qfour n M) = true.
Proof. unfold Qfour. destruct (N.odd M); reflexivity. Qed.
Lemma fclc_clean (sg : list seg) (P : word) (K : N)
      (t : word) (f : N) (d : cost)
      (q q2 : nat) (cw2 : word) (f2 : N) :
  forallb nobase P = true ->
  ((2 <= K)%N ->
     sound_impl_c d (P ++ lin_flat sg t) f
                    (Qclean K ++ lin_flat sg t) f) ->
  lin_front_done q
    (fr_clean ((2,2,4)%N :: (5,2,1)%N :: (3,1,K)%N :: t) f)
    = Some (q2, cw2, f2) ->
  creach d
    (wconf [] 0 (sdecode (lin_flat sg (P ++ t)) f))
    (wconf [] 0 (sdecode (lin_flat sg cw2) f2)).
Proof.
  intros HP HS HD.
  destruct (front_done_clean_inv q K t f q2 cw2 f2 HD)
    as (HK & _ & Hf & Hw). subst f2 cw2.
  pose proof (front_finishc sg P (Qclean K) t f d HP
                (nobase_Qclean K) (HS HK)) as HR.
  unfold Qclean in HR.
  destruct (N.odd K); cbn [app] in HR |- *; exact HR.
Qed.
Lemma fclc_four (sg : list seg) (P : word) (n M : N)
      (t : word) (f : N) (d : cost)
      (q q2 : nat) (cw2 : word) (f2 : N) :
  forallb nobase P = true ->
  ((2 <= M)%N ->
     sound_impl_c d (P ++ lin_flat sg t) f
                    (Qfour n M ++ lin_flat sg t) f) ->
  lin_front_done q
    (fr_four ((2,2,n)%N :: (4,2,1)%N :: (4,1,M)%N :: t) f)
    = Some (q2, cw2, f2) ->
  creach d
    (wconf [] 0 (sdecode (lin_flat sg (P ++ t)) f))
    (wconf [] 0 (sdecode (lin_flat sg cw2) f2)).
Proof.
  intros HP HS HD.
  destruct (front_done_four_inv q n M t f q2 cw2 f2 HD)
    as (HM & _ & Hf & Hw). subst f2 cw2.
  pose proof (front_finishc sg P (Qfour n M) t f d HP
                (nobase_Qfour n M) (HS HM)) as HR.
  unfold Qfour in HR.
  destruct (N.odd M); cbn [app] in HR |- *; exact HR.
Qed.
Lemma fclc_522_1 (sg : list seg) (c k M : N) (t : word)
      (f : N) (q : nat) (cw2 : word) (f2 : N) :
  k = 1%N ->
  lin_front_done 2
    (fr_four ((2,2,c+1)%N :: (4,2,1)%N :: (4,1,M)%N :: t) f)
    = Some (q, cw2, f2) ->
  creach (dfc ([(2,2,c); (4,1,1); (k,1,1); (4,1,M)]%N ++ t) f)
    (wconf [] 0 (sdecode (lin_flat sg
                    ([(2,2,c); (4,1,1); (k,1,1); (4,1,M)]%N ++ t)) f))
    (wconf [] 0 (sdecode (lin_flat sg cw2) f2)).
Proof.
  intros Hk HD. subst k.
  eapply (fclc_four sg [(2,2,c); (4,1,1); (1,1,1); (4,1,M)]%N
            (c+1)%N M t f _ 2 q cw2 f2); [reflexivity| |exact HD].
  intros HM. cbn [app].
  unfold dfc, fcsplit. cbv beta iota zeta.
  rewrite (proj2 (N.leb_le 2 M) HM). cbn [N.eqb].
  exact (fcc_522_1 c M (lin_flat sg t) f HM).
Qed.
Lemma fclc_522_2 (sg : list seg) (c k M : N) (t : word)
      (f : N) (q : nat) (cw2 : word) (f2 : N) :
  k = 2%N ->
  lin_front_done 3
    (fr_four ((2,2,c+2)%N :: (4,2,1)%N :: (4,1,M)%N :: t) f)
    = Some (q, cw2, f2) ->
  creach (dfc ([(2,2,c); (4,1,1); (k,1,1); (4,1,M)]%N ++ t) f)
    (wconf [] 0 (sdecode (lin_flat sg
                    ([(2,2,c); (4,1,1); (k,1,1); (4,1,M)]%N ++ t)) f))
    (wconf [] 0 (sdecode (lin_flat sg cw2) f2)).
Proof.
  intros Hk HD. subst k.
  eapply (fclc_four sg [(2,2,c); (4,1,1); (2,1,1); (4,1,M)]%N
            (c+2)%N M t f _ 3 q cw2 f2); [reflexivity| |exact HD].
  intros HM. cbn [app].
  unfold dfc, fcsplit. cbv beta iota zeta.
  rewrite (proj2 (N.leb_le 2 M) HM). cbn [N.eqb].
  exact (fcc_522_2 c M (lin_flat sg t) f HM).
Qed.
Lemma fclc_522_3 (sg : list seg) (c k M : N) (t : word)
      (f : N) (q : nat) (cw2 : word) (f2 : N) :
  k = 3%N ->
  lin_front_done 4
    (fr_four ((2,2,c+3)%N :: (4,2,1)%N :: (4,1,M)%N :: t) f)
    = Some (q, cw2, f2) ->
  creach (dfc ([(2,2,c); (4,1,1); (k,1,1); (4,1,M)]%N ++ t) f)
