Proof.
  intros Hk HD. subst k.
  eapply (fclc_four sg [(2,2,c); (4,1,1); (3,1,1); (4,1,M)]%N
            (c+3)%N M t f _ 4 q cw2 f2); [reflexivity| |exact HD].
  intros HM. cbn [app].
  unfold dfc, fcsplit. cbv beta iota zeta.
  rewrite (proj2 (N.leb_le 2 M) HM). cbn [N.eqb].
  exact (fcc_522_3 c M (lin_flat sg t) f HM).
Qed.
Lemma fclc_512_1 (sg : list seg) (c k K : N) (t : word)
      (f : N) (q : nat) (cw2 : word) (f2 : N) :
  k = 1%N -> (c + k = 4)%N ->
  lin_front_done 2
    (fr_clean ((2,2,4)%N :: (5,2,1)%N :: (3,1,K)%N :: t) f)
    = Some (q, cw2, f2) ->
  creach (dfc ([(2,2,c); (5,1,1); (k,1,1); (3,1,K)]%N ++ t) f)
    (wconf [] 0 (sdecode (lin_flat sg
                    ([(2,2,c); (5,1,1); (k,1,1); (3,1,K)]%N ++ t)) f))
    (wconf [] 0 (sdecode (lin_flat sg cw2) f2)).
Proof.
  intros Hk Hc HD. assert (c = 3)%N by lia. subst k c.
  eapply (fclc_clean sg [(2,2,3); (5,1,1); (1,1,1); (3,1,K)]%N
            K t f _ 2 q cw2 f2); [reflexivity| |exact HD].
  intros HK. cbn [app].
  unfold dfc, fcsplit. cbv beta iota zeta.
  rewrite (proj2 (N.leb_le 2 K) HK). cbn [N.eqb andb].
  exact (fcc_512_1 K (lin_flat sg t) f HK).
Qed.
Lemma fclc_512_2 (sg : list seg) (c k K : N) (t : word)
      (f : N) (q : nat) (cw2 : word) (f2 : N) :
  k = 2%N -> (c + k = 4)%N ->
  lin_front_done 3
    (fr_clean ((2,2,4)%N :: (5,2,1)%N :: (3,1,K)%N :: t) f)
    = Some (q, cw2, f2) ->
  creach (dfc ([(2,2,c); (5,1,1); (k,1,1); (3,1,K)]%N ++ t) f)
    (wconf [] 0 (sdecode (lin_flat sg
                    ([(2,2,c); (5,1,1); (k,1,1); (3,1,K)]%N ++ t)) f))
    (wconf [] 0 (sdecode (lin_flat sg cw2) f2)).
Proof.
  intros Hk Hc HD. assert (c = 2)%N by lia. subst k c.
  eapply (fclc_clean sg [(2,2,2); (5,1,1); (2,1,1); (3,1,K)]%N
            K t f _ 3 q cw2 f2); [reflexivity| |exact HD].
  intros HK. cbn [app].
  unfold dfc, fcsplit. cbv beta iota zeta.
  rewrite (proj2 (N.leb_le 2 K) HK). cbn [N.eqb andb].
  exact (fcc_512_2 K (lin_flat sg t) f HK).
Qed.
Lemma fclc_502 (sg : list seg) (c K : N) (t : word)
      (f : N) (q : nat) (cw2 : word) (f2 : N) :
  c = 1%N -> (3 <= K)%N ->
  lin_front_done 4
    (fr_clean ((2,2,4)%N :: (5,2,1)%N :: (3,1,K-1)%N :: t) f)
    = Some (q, cw2, f2) ->
  creach (dfc ([(2,2,c); (5,1,1); (3,1,K)]%N ++ t) f)
    (wconf [] 0 (sdecode (lin_flat sg
                    ([(2,2,c); (5,1,1); (3,1,K)]%N ++ t)) f))
    (wconf [] 0 (sdecode (lin_flat sg cw2) f2)).
Proof.
  intros Hc HK HD. subst c.
  eapply (fclc_clean sg [(2,2,1); (5,1,1); (3,1,K)]%N
            (K-1)%N t f _ 4 q cw2 f2); [reflexivity| |exact HD].
  intros _. cbn [app].
  unfold dfc, fcsplit. cbv beta iota zeta.
  rewrite (proj2 (N.leb_le 3 K) HK).
  destruct K as [|p]; [exfalso; lia|].
  destruct p as [p'|p'|]; [| |exfalso; lia].
  all: cbv beta iota zeta; cbn [N.eqb Pos.eqb andb];
       exact (fcc_502 _ (lin_flat sg t) f HK).
Qed.
Lemma fclc_rot (sg : list seg) (K : N) (t : word)
      (f : N) (q : nat) (cw2 : word) (f2 : N) :
  (2 <= K)%N ->
  lin_front_done 5
    (fr_clean ((2,2,4)%N :: (5,2,1)%N :: (3,1,K)%N :: t) f)
    = Some (q, cw2, f2) ->
  creach (dfc ([(5,1,1); (4,1,1); (3,1,K)]%N ++ t) f)
    (wconf [] 0 (sdecode (lin_flat sg
                    ([(5,1,1); (4,1,1); (3,1,K)]%N ++ t)) f))
    (wconf [] 0 (sdecode (lin_flat sg cw2) f2)).
Proof.
  intros HK HD.
  eapply (fclc_clean sg [(5,1,1); (4,1,1); (3,1,K)]%N
            K t f _ 5 q cw2 f2); [reflexivity| |exact HD].
  intros _. cbn [app].
  unfold dfc, fcsplit. cbv beta iota zeta.
  rewrite (proj2 (N.leb_le 2 K) HK).
  exact (fcc_rot K (lin_flat sg t) f HK).
Qed.
Ltac digsH H ::=
  repeat match type of H with
  | context [match ?x with N0 => _ | N.pos _ => _ end] =>
      is_var x; destruct x
  | context [match ?x with xI _ => _ | xO _ => _ | xH => _ end] =>
      is_var x; destruct x
  end.
Ltac front_prep H ::=
  repeat match type of H with
  | context [if ?b then _ else _] =>
      let E := fresh "EB" in destruct b eqn:E; try discriminate
  end;
  repeat match goal with
  | E : (_ && _)%bool = true |- _ =>
      let E2 := fresh "EB" in
      apply andb_prop in E; destruct E as [E E2]
  end;
  repeat match goal with
  | E : (_ <=? _)%N = true |- _ => apply N.leb_le in E
  | E : (_ =? _)%N = true |- _ => apply N.eqb_eq in E
  end;
  try (exfalso; lia).
Ltac close_fclc HC :=
  first
    [ eapply fclc_rot; [lia|exact HC]
    | eapply fclc_502; [lia|lia|exact HC]
    | match goal with
      | Hk : _ = 1%N |- _ => eapply fclc_512_1; [exact Hk|lia|exact HC]
      end
    | match goal with
      | Hk : _ = 2%N |- _ => eapply fclc_512_2; [exact Hk|lia|exact HC]
      end
    | match goal with
      | Hk : _ = 1%N |- _ => eapply fclc_522_1; [exact Hk|exact HC]
      end
    | match goal with
      | Hk : _ = 2%N |- _ => eapply fclc_522_2; [exact Hk|exact HC]
      end
    | match goal with
      | Hk : _ = 3%N |- _ => eapply fclc_522_3; [exact Hk|exact HC]
      end ].
Lemma dfc_flat_502_tail (sg : list seg) (K : N)
      (t : word) (f : N) :
  (3 <= K)%N ->
  dfc ([(2,2,1); (5,1,1); (3,1,K)]%N ++ lin_flat sg t) f =
  dfc ([(2,2,1); (5,1,1); (3,1,K)]%N ++ t) f.
Proof.
  intros HK. cbn [app]. unfold dfc, fcsplit. cbv beta iota zeta.
  rewrite (proj2 (N.leb_le 3 K) HK).
  destruct K as [|p]; [exfalso; lia|].
  destruct p as [p'|p'|]; [| |exfalso; lia].
  all: cbv beta iota zeta; cbn [N.eqb Pos.eqb andb]; reflexivity.
Qed.
Lemma dfc_flat_rot_tail (sg : list seg) (K : N)
      (t : word) (f : N) :
  (2 <= K)%N ->
  dfc ([(5,1,1); (4,1,1); (3,1,K)]%N ++ lin_flat sg t) f =
  dfc ([(5,1,1); (4,1,1); (3,1,K)]%N ++ t) f.
Proof.
  intros HK. cbn [app]. unfold dfc, fcsplit. cbv beta iota zeta.
  rewrite (proj2 (N.leb_le 2 K) HK). reflexivity.
Qed.
Ltac close_fclc_case :=
  first
    [ eapply fclc_rot; eassumption
    | eapply fclc_502; eassumption
    | eapply fclc_512_1; eassumption
    | eapply fclc_512_2; eassumption
    | eapply fclc_522_1; eassumption
    | eapply fclc_522_2; eassumption
    | eapply fclc_522_3; eassumption ].
Lemma dfc_flat_of_case (sg : list seg) (cw : word)
      (f : N) (q : nat) (cw2 : word) (f2 : N) :
  front_close_case cw f q cw2 f2 ->
  dfc (lin_flat sg cw) f = dfc cw f.
Proof.
  assert (Hzone1 : forall o c : N,
      phshape (o, 1%N, c) = false).
  { intros o c. unfold phshape, tagbase.
    cbn [gO gZ gC].
    destruct (o =? PHO)%N; reflexivity. }
  intros HC. destruct HC; cbn [app].
  all: try subst c; try subst k.
  all: try (assert (c = 3)%N by lia; subst c).
  all: try (assert (c = 2)%N by lia; subst c).
  all: repeat rewrite flat_cons_nonlvl by
         (first [apply Hzone1 | reflexivity]);
       try reflexivity.
  all: try (apply dfc_flat_502_tail; lia).
  all: try (apply dfc_flat_rot_tail; lia).
  all: destruct t as [|[[ot zt] ct] t]; [reflexivity|].
  all: match goal with
       | HD : lin_front_done _ _ = Some _ |- _ =>
           unfold lin_front_done in HD;
           cbn [fr_clean fr_four] in HD;
           digsH HD; try discriminate; front_prep HD
       end.
  all: repeat rewrite flat_cons_nonlvl by
         (first [apply Hzone1 | reflexivity]);
       reflexivity.
Qed.
Theorem lin_front_close_facts (sg : list seg) (cw : word)
        (f : N) (q : nat) (cw2 : word) (f2 : N) :
  lin_front_close cw f = Some (q, cw2, f2) ->
  creach (dfc cw f)
    (wconf [] 0 (sdecode (lin_flat sg cw) f))
    (wconf [] 0 (sdecode (lin_flat sg cw2) f2))
  /\ dfc (lin_flat sg cw) f = dfc cw f.
Proof.
  intros HC.
  pose proof (lin_front_close_case_of cw f q cw2 f2 HC)
    as HCase.
  split.
  - destruct HCase.
    all: close_fclc_case.
  - exact (dfc_flat_of_case sg cw f q cw2 f2 HCase).
Qed.
Theorem lin_front_close_creach (sg : list seg) (cw : word)
        (f : N) (q : nat) (cw2 : word) (f2 : N) :
  lin_front_close cw f = Some (q, cw2, f2) ->
  creach (dfc cw f)
    (wconf [] 0 (sdecode (lin_flat sg cw) f))
    (wconf [] 0 (sdecode (lin_flat sg cw2) f2)).
Proof.
  intros HC. destruct (lin_front_close_facts sg cw f q cw2 f2 HC) as [H _].
  exact H.
Qed.
Lemma dfc_flat_on_fire (sg : list seg) (cw : word)
      (f : N) (q : nat) (cw2 : word) (f2 : N) :
  lin_front_close cw f = Some (q, cw2, f2) ->
  dfc (lin_flat sg cw) f = dfc cw f.
Proof.
  intros HC. destruct (lin_front_close_facts sg cw f q cw2 f2 HC) as [_ H].
  exact H.
Qed.
Corollary lin_front_close_creach_i (sg : list seg) (cw : word)
        (f : N) (q : nat) (cw2 : word) (f2 : N) :
  lin_front_close cw f = Some (q, cw2, f2) ->
  creach (dfci cw f)
    (wconf [] 0 (sdecode (lin_flat sg cw) f))
    (wconf [] 0 (sdecode (lin_flat sg cw2) f2)).
Proof.
  intros HC.
  destruct (dfc_dfci cw f) as (HL & HH).
  exact (creach_widen' _ _ _ _ HL HH
           (lin_front_close_creach sg cw f q cw2 f2 HC)).
Qed.
