Definition gmeas (w : word) (f : N) : N := ccolcost w + 2 * f.
Lemma gmeas_normalize (w : word) (f : N) :
  gmeas (normalize w) f = gmeas w f.
Proof. unfold gmeas. rewrite ccolcost_normalize. reflexivity. Qed.
Ltac harm := intros HH; injection HH; intros; subst; gfin; (lia || nia).
Lemma gif_true {A : Type} (x y : A) : (if true then x else y) = x.
Proof. reflexivity. Qed.
Lemma gif_false {A : Type} (x y : A) : (if false then x else y) = y.
Proof. reflexivity. Qed.
Lemma nmul2 (x : N) :
  match x with N0 => N0 | N.pos q => N.pos (q~0)%positive end = 2 * x.
Proof. destruct x; reflexivity. Qed.
Lemma nmul3 (x : N) :
  match x with N0 => N0 | N.pos q => N.pos (q + q~0)%positive end = 3 * x.
Proof. destruct x; reflexivity. Qed.
Ltac gif := rewrite ?gif_true, ?gif_false, ?nmul2, ?nmul3 in *.
Ltac gopt :=
  repeat match goal with
  | |- context [ if (1 <? ?V)%N then _ else _ ] =>
      let E := fresh "EV" in
      destruct (1 <? V)%N eqn:E;
      [ apply N.ltb_lt in E | apply N.ltb_ge in E ]
  | H : context [ if (1 <? ?V)%N then _ else _ ] |- _ =>
      let E := fresh "EV" in
      destruct (1 <? V)%N eqn:E;
      [ apply N.ltb_lt in E | apply N.ltb_ge in E ]
  end; gif; gcc.
Ltac gz := gif; gcc; gopt; lia.
Ltac nkm H :=
  repeat (match type of H with
          | (match ?x with _ => _ end) = _ =>
              match type of x with
              | N => destruct x
              | positive => destruct x
              end
          end; try discriminate);
  try discriminate.
Ltac kdt :=
  match goal with
  | |- context [ wat ?a ?b ] => destruct (wat a b) as [gz|]
  end;
  [ match goal with
    | |- context [ (gZ ?g =? 1)%N ] => destruct ((gZ g =? 1)%N)
    end; [discriminate|];
    match goal with
    | |- context [ e0_chain ?a ?b ] => destruct (e0_chain a b)
    end; [discriminate|];
    match goal with
    | |- context [ deliver_tick ?a ?b ?c ?d ?e ] =>
        destruct (deliver_tick a b c d e)
    end; discriminate
  | discriminate ].
Ltac kcm :=
  match goal with
  | |- context [ chain_merge_advance ?a ?b ?c ?d ] =>
      destruct (chain_merge_advance a b c d)
  end; discriminate.
Ltac bs H :=
  repeat (match type of H with
          | (_ && _)%bool = true => apply andb_prop in H; destruct H as [H ?]
          end);
  repeat (match goal with
          | HH : (_ =? _)%N = true |- _ => apply N.eqb_eq in HH; subst
          | HH : (_ <=? _)%N = true |- _ => apply N.leb_le in HH
          | HH : (_ <? _)%N = true |- _ => apply N.ltb_lt in HH
          end).
Lemma round_at_grow (cols s : word) (f : N) (t : word) (f2 : N) :
  round_at cols s f = Some (t, f2) ->
  ccolcost cols + ccolcost s + 2 * f
    <= ccolcost t + 2 * f2 + 8.
Proof.
  unfold round_at.
  destruct s as [|[[oR zR] cR] sT].
  {   cbn [leaf_act]. discriminate. }
  destruct zR as [|zp].
  {
    match goal with
    | |- context [ leaf_act ?a ?b ] =>
        destruct (leaf_act a b) as [[s2 f3]|] eqn:EL
    end; [|discriminate].
    intros HH; injection HH as HH1 HH2; subst.
    pose proof (leaf_grow _ _ _ _ EL) as HG.
    rewrite ccolcost_app. lia. }
  destruct zp as [zp'|zp'|].
  -
    destruct zp' as [q|q|].
    +
      match goal with
      | |- context [ leaf_act ?a ?b ] =>
          destruct (leaf_act a b) as [[s2 f3]|] eqn:EL
      end; [|discriminate].
      intros HH; injection HH as HH1 HH2; subst.
      pose proof (leaf_grow _ _ _ _ EL) as HG.
      rewrite ccolcost_app. lia.
    +
      match goal with
      | |- context [ leaf_act ?a ?b ] =>
          destruct (leaf_act a b) as [[s2 f3]|] eqn:EL
      end; [|discriminate].
      intros HH; injection HH as HH1 HH2; subst.
      pose proof (leaf_grow _ _ _ _ EL) as HG.
      rewrite ccolcost_app. lia.
    +
      destruct cR as [|cp].
      { match goal with
        | |- context [ leaf_act ?a ?b ] =>
            destruct (leaf_act a b) as [[s2 f3]|] eqn:EL
        end; [|discriminate].
        intros HH; injection HH as HH1 HH2; subst.
        pose proof (leaf_grow _ _ _ _ EL) as HG.
        rewrite ccolcost_app. lia. }
      destruct cp as [cp'|cp'|].
      * match goal with
        | |- context [ leaf_act ?a ?b ] =>
            destruct (leaf_act a b) as [[s2 f3]|] eqn:EL
        end; [|discriminate].
        intros HH; injection HH as HH1 HH2; subst.
        pose proof (leaf_grow _ _ _ _ EL) as HG.
        rewrite ccolcost_app. lia.
      * match goal with
        | |- context [ leaf_act ?a ?b ] =>
            destruct (leaf_act a b) as [[s2 f3]|] eqn:EL
        end; [|discriminate].
        intros HH; injection HH as HH1 HH2; subst.
        pose proof (leaf_grow _ _ _ _ EL) as HG.
        rewrite ccolcost_app. lia.
      *
        match goal with
        | |- context [ renew_seg ?n ?a ?b ?c ] =>
            pose proof (proj2 (casc_grow n) a b c) as HR;
            destruct (renew_seg n a b c) as [[body f3]|] eqn:ER
        end.
        { intros HH; injection HH as HH1 HH2; subst.
          specialize (HR _ _ eq_refl). lia. }
        match goal with
        | |- context [ fire_comp ?n ?a ?b ] =>
            pose proof (proj1 (casc_grow n) a b) as HF;
            destruct (fire_comp n a b) as [[s2 f3]|] eqn:EF
        end; [|discriminate].
        intros HH; injection HH as HH1 HH2; subst.
        specialize (HF _ _ eq_refl).
        rewrite ccolcost_app. lia.
  -
    match goal with
    | |- context [ leaf_act ?a ?b ] =>
        destruct (leaf_act a b) as [[s2 f3]|] eqn:EL
    end; [|discriminate].
    intros HH; injection HH as HH1 HH2; subst.
    pose proof (leaf_grow _ _ _ _ EL) as HG.
    rewrite ccolcost_app. lia.
  -
    match goal with
    | |- context [ leaf_act ?a ?b ] =>
        destruct (leaf_act a b) as [[s2 f3]|] eqn:EL
    end; [|discriminate].
    intros HH; injection HH as HH1 HH2; subst.
    pose proof (leaf_grow _ _ _ _ EL) as HG.
    rewrite ccolcost_app. lia.
Qed.
Lemma round1g_grow (tail : word) (f : N) (t : word) (f2 : N) :
  round1g tail f = Some (t, f2) -> gmeas tail f <= gmeas t f2 + 8.
Proof.
  unfold round1g, gmeas.
  destruct (seek tail) as [cols s] eqn:ESK.
  pose proof (ccolcost_seek_eq _ _ _ ESK) as HSK.
  intros H. pose proof (round_at_grow _ _ _ _ _ H). lia.
Qed.
Lemma dtb4_conv_grow (cols body : word) :
  dtb4_conv cols = Some body ->
  ccolcost cols <= ccolcost body.
Proof.
  intros H. destruct (dtb4d_some _ _ H) as [d Hd].
  rewrite (dtb4_conv_ccolcost _ _ _ H Hd). lia.
Qed.
Lemma round2g_grow (tail : word) (f : N) (t : word) (f2 : N) :
  round2g tail f = Some (t, f2) -> gmeas tail f <= gmeas t f2 + 16.
Proof.
  unfold round2g, gmeas.
  destruct (seek tail) as [cols s] eqn:ESK.
  pose proof (ccolcost_seek_eq _ _ _ ESK) as HSK.
  destruct (round_at cols s f) as [[t2 f3]|] eqn:ER1; [|discriminate].
  pose proof (round_at_grow _ _ _ _ _ ER1) as HG1.
  destruct (seek t2) as [cols2 s2] eqn:ESK2.
  pose proof (ccolcost_seek_eq _ _ _ ESK2) as HSK2.
  destruct s2 as [|g2 s2t].
  - cbn [ccolcost] in HSK2.
    destruct (f3 =? 4) eqn:E4.
    + destruct (dtb4_conv cols2) as [cols2'|] eqn:ED; [|discriminate].
      pose proof (dtb4_conv_grow _ _ ED) as HD.
      intros HH; injection HH as HH1 HH2; subst. lia.
    + destruct (5 <=? f3) eqn:E5; [|discriminate].
      apply N.leb_le in E5.
      intros HH; injection HH as HH1 HH2; subst.
      rewrite ccolcost_app, ccolcost_cons, ccg_unfold.
      lia.
  - intros H2. pose proof (round_at_grow _ _ _ _ _ H2) as HG2. lia.
Qed.
Lemma round2g_pre8_grow (tail : word) (f : N) (cols2 : word) :
  round2g_pre8 tail f = Some cols2 -> gmeas tail f <= gmeas cols2 4 + 8.
Proof.
  unfold round2g_pre8, gmeas.
  destruct (seek tail) as [cols s] eqn:ESK.
  pose proof (ccolcost_seek_eq _ _ _ ESK) as HSK.
  destruct (round_at cols s f) as [[t2 f3]|] eqn:ER1; [|discriminate].
  pose proof (round_at_grow _ _ _ _ _ ER1) as HG1.
  destruct (seek t2) as [cols2' s2] eqn:ESK2.
  pose proof (ccolcost_seek_eq _ _ _ ESK2) as HSK2.
  destruct s2 as [|g2 s2t]; [|discriminate].
  cbn [ccolcost] in HSK2.
  destruct ((f3 =? 4) && forallb w42 cols2')%bool eqn:EG; [|discriminate].
  apply andb_prop in EG. destruct EG as [E4 _]. apply N.eqb_eq in E4. subst f3.
  destruct (dtb4_conv cols2') as [x|] eqn:ED; [discriminate|].
  intros HH; injection HH as HH1; subst. lia.
Qed.
Local Opaque ccolcost.
Lemma span2_core_grow (a m : N) (rest : word) (f : N)
      (w2 : word) (f2 : N) :
  span2_core a m rest f = ROk w2 f2 ->
  gmeas ((2,2,a) :: (5,2,1) :: (3,2,m) :: (3,3,1) :: rest) f
    <= gmeas w2 f2.
Proof.
  unfold gmeas, span2_core.
  destruct rest as [|[[o0 z0] V] rest']; [discriminate|].
  destruct rest' as [|g1 rest1]; [discriminate|].
  destruct ((o0 =? 4) && (z0 =? 2) && (1 <=? V))%bool eqn:EG; [|discriminate].
  nlbools. subst o0 z0.
  cbv zeta.
  destruct (seek (g1 :: rest1)) as [cols s] eqn:ESK.
  pose proof (ccolcost_seek_eq _ _ _ ESK) as HSK.
  destruct s as [|[[oR zR] cR] tR]; [discriminate|].
  destruct zR as [|zp].
  { discriminate. }
  destruct zp as [zp'|zp'|].
  - destruct zp' as [q|q|]; try discriminate.
    destruct cR as [|cp]; [discriminate|].
    destruct cp as [cp'|cp'|]; try discriminate.
    match goal with
    | |- context [ renew_seg ?n ?A ?B ?C ] =>
        pose proof (proj2 (casc_grow n) A B C) as HR;
        destruct (renew_seg n A B C) as [[body f3]|] eqn:ER
    end.
    { intros HH; injection HH as HH1 HH2; subst.
      specialize (HR _ _ eq_refl). gz. }
    match goal with
    | |- context [ fire_comp ?n ?A ?B ] =>
        pose proof (proj1 (casc_grow n) A B) as HF;
        destruct (fire_comp n A B) as [[s2 f3]|] eqn:EF
    end; [|discriminate].
    intros HH; injection HH as HH1 HH2; subst.
    specialize (HF _ _ eq_refl). gz.
  - discriminate.
  -
    match goal with
    | |- context [ leaf_act ?A ?B ] =>
        destruct (leaf_act A B) as [[s2 f3]|] eqn:EL
    end; [|discriminate].
    intros HH; injection HH as HH1 HH2; subst.
    pose proof (leaf_grow _ _ _ _ EL) as HG. gz.
Qed.
Lemma fr_primordial_grow (w w2 : word) (f f2 : N) :
  fr_primordial w f = Some (ROk w2 f2) -> gmeas w f <= gmeas w2 f2.
Proof.
  unfold fr_primordial, gmeas. intros E.
  destruct w as [|[[o1 z1] c1] w1]; [discriminate E|].
  destruct w1 as [|[[o2 z2] c2] w1'].
  - nkm E.
    destruct (2 <=? f) eqn:EF; [|discriminate E].
    apply N.leb_le in EF.
    unfold o_ in E; injection E as E1 E2; subst. gz.
  - destruct w1' as [|g3 t3]; [|nkm E].
    nkm E.
    destruct (2 <=? f) eqn:EF.
    { apply N.leb_le in EF.
      unfold o_ in E; injection E as E1 E2; subst. gz. }
    destruct (f =? 1) eqn:EF1; [|discriminate E].
    apply N.eqb_eq in EF1; subst f.
    unfold o_ in E; injection E as E1 E2; subst. gz.
Qed.
Lemma fr_prim4_grow (w w2 : word) (f f2 : N) :
  fr_prim4 w f = Some (ROk w2 f2) -> gmeas w f <= gmeas w2 f2.
Proof.
  unfold fr_prim4, gmeas. intros E.
  destruct w as [|[[o1 z1] cN] w1]; [discriminate E|].
  destruct w1 as [|g2 t2]; [|nkm E].
  nkm E.
  destruct ((cN =? 4) && (f =? 4))%bool eqn:EG; [|discriminate E].
  nlbools. subst cN f.
  unfold o_ in E; injection E as E1 E2; subst. gz.
Qed.
Lemma fr_clean_grow (w w2 : word) (f f2 : N) :
  fr_clean w f = Some (ROk w2 f2) -> gmeas w f <= gmeas w2 f2.
Proof.
  unfold fr_clean, gmeas. intros E.
  destruct w as [|[[o1 z1] c1] w1]; [discriminate E|].
  destruct w1 as [|[[o2 z2] c2] w1']; [nkm E|].
  destruct w1' as [|[[o3 z3] K] rest]; [nkm E|].
  nkm E.
  destruct (2 <=? K) eqn:EK2; [|discriminate E].
  apply N.leb_le in EK2.
  pose proof (N.div2_odd K) as HD.
  cbv zeta in E.
  destruct (N.odd K) eqn:EO; cbn [N.b2n] in HD;
    unfold o_ in E; injection E as E1 E2; subst; gz.
Qed.
Lemma fr_four_grow (w w2 : word) (f f2 : N) :
  fr_four w f = Some (ROk w2 f2) -> gmeas w f <= gmeas w2 f2.
Proof.
  unfold fr_four, gmeas. intros E.
  destruct w as [|[[o1 z1] cN] w1]; [discriminate E|].
  destruct w1 as [|[[o2 z2] c2] w1']; [nkm E|].
  destruct w1' as [|[[o3 z3] M] w3]; [nkm E|].
  destruct w3 as [|[[od zd] cd] w4]; [nkm E|].
  nkm E.
  destruct ((2 <=? M) && (((od =? 8) && (zd =? 2))
                          || ((od =? 5) && (zd =? 1))))%bool eqn:EGF;
    [|discriminate E].
  apply andb_prop in EGF. destruct EGF as [EM _]. apply N.leb_le in EM.
  pose proof (N.div2_odd M) as HD.
  pose proof (N.div2_odd (M + 1)) as HD1.
  destruct (N.odd (M + 1)) eqn:EO1; cbn [N.b2n] in HD1.
  - destruct (N.odd M) eqn:EO; cbn [N.b2n] in HD;
      unfold o_ in E; injection E as E1 E2; subst; gz.
  - destruct (N.odd M) eqn:EO; cbn [N.b2n] in HD;
      unfold o_ in E; injection E as E1 E2; subst; gz.
Qed.
Lemma fr_span2A_grow (w w2 : word) (f f2 : N) :
  fr_span2A w f = Some (ROk w2 f2) -> gmeas w f <= gmeas w2 f2.
Proof.
  unfold fr_span2A. intros E.
  destruct w as [|[[o1 z1] a] w1]; [discriminate E|].
  destruct w1 as [|[[o2 z2] c2] w1']; [nkm E|].
  destruct w1' as [|[[o3 z3] m] w2']; [nkm E|].
  destruct w2' as [|[[o4 z4] c4] rest]; [nkm E|].
  destruct rest as [|[[o5 z5] c5] rest']; [nkm E|].
  nkm E.
  unfold o_ in E; injection E as E1.
  apply (span2_core_grow a m _ f). exact E1.
Qed.
Lemma fr_span2A'_grow (w w2 : word) (f f2 : N) :
  fr_span2A' w f = Some (ROk w2 f2) -> gmeas w f <= gmeas w2 f2.
Proof.
  unfold fr_span2A', gmeas. intros E.
  destruct w as [|[[o1 z1] a] w1]; [discriminate E|].
  destruct w1 as [|[[o2 z2] c2] w1']; [nkm E|].
  destruct w1' as [|[[o3 z3] m] w2']; [nkm E|].
  destruct w2' as [|[[o4 z4] V] w3']; [nkm E|].
  destruct w3' as [|g5 t5]; [|nkm E].
  nkm E.
  destruct ((1 <=? a) && (1 <=? m) && (1 <=? V) && (f =? 4))%bool eqn:EG;
    [|discriminate E].
  nlbools. subst f.
  unfold o_ in E; injection E as E1 E2; subst. gz.
Qed.
Lemma fr_span2C'_grow (w w2 : word) (f f2 : N) :
  fr_span2C' w f = Some (ROk w2 f2) -> gmeas w f <= gmeas w2 f2.
Proof.
  unfold fr_span2C', gmeas. intros E.
  destruct w as [|[[o1 z1] a] w1]; [discriminate E|].
  destruct w1 as [|[[o2 z2] c2] w1']; [nkm E|].
  destruct w1' as [|[[o3 z3] m] w2']; [nkm E|].
  destruct w2' as [|[[o4 z4] c4] w3']; [nkm E|].
  destruct w3' as [|[[o5 z5] V] w4']; [nkm E|].
  destruct w4' as [|g6 t6]; [|nkm E].
  nkm E.
  destruct ((1 <=? a) && (1 <=? m) && (1 <=? V) && (f =? 4))%bool eqn:EG;
    [|discriminate E].
  nlbools. subst f.
  unfold o_ in E; injection E as E1 E2; subst. gz.
Qed.
Lemma fr_rot_grow (w w2 : word) (f f2 : N) :
  fr_rot w f = Some (ROk w2 f2) -> gmeas w f <= gmeas w2 f2.
Proof.
  unfold fr_rot, gmeas. intros E.
  destruct w as [|[[o1 z1] c1] w1]; [discriminate E|].
  destruct w1 as [|[[o2 z2] c2] w1']; [nkm E|].
  destruct w1' as [|[[o3 z3] K] rest]; [nkm E|].
  nkm E.
  unfold o_ in E; injection E as E1 E2; subst. gz.
Qed.
Lemma fr_502_grow (w w2 : word) (f f2 : N) :
  fr_502 w f = Some (ROk w2 f2) -> gmeas w f <= gmeas w2 f2.
Proof.
  unfold fr_502, gmeas. intros E.
  destruct w as [|[[o1 z1] j] w1]; [discriminate E|].
  destruct w1 as [|[[o2 z2] c2] w1']; [nkm E|].
  destruct w1' as [|[[o3 z3] K] rest]; [nkm E|].
  nkm E.
  destruct (K =? 1) eqn:EK1.
  { apply N.eqb_eq in EK1; subst K.
    unfold o_ in E; injection E as E1 E2; subst. gz. }
  destruct (2 <=? K) eqn:EK2; [|discriminate E].
  apply N.leb_le in EK2.
  unfold o_ in E; injection E as E1 E2; subst. gz.
Qed.
Lemma fr_512_grow (w w2 : word) (f f2 : N) :
  fr_512 w f = Some (ROk w2 f2) -> gmeas w f <= gmeas w2 f2.
Proof.
  unfold fr_512, gmeas. intros E.
  destruct w as [|[[o1 z1] j] w1]; [discriminate E|].
  destruct w1 as [|[[o2 z2] c2] w1']; [nkm E|].
  destruct w1' as [|[[k z3] c3] rest]; [nkm E|].
  nkm E.
  destruct ((k <? 3) && (1 <=? k))%bool eqn:EG; [|discriminate E].
  nlbools.
  destruct (k =? 1) eqn:EK1;
    [ apply N.eqb_eq in EK1; subst k | apply N.eqb_neq in EK1 ];
    unfold o_ in E; injection E as E1 E2; subst; gz.
Qed.
Lemma fr_522_grow (w w2 : word) (f f2 : N) :
  fr_522 w f = Some (ROk w2 f2) -> gmeas w f <= gmeas w2 f2.
Proof.
  unfold fr_522, gmeas. intros E.
  destruct w as [|[[o1 z1] cN] w1]; [discriminate E|].
  destruct w1 as [|[[o2 z2] c2] w1']; [nkm E|].
  destruct w1' as [|[[k z3] c3] rest]; [nkm E|].
  nkm E.
  destruct ((k <=? 3) && (1 <=? k))%bool eqn:EG; [|discriminate E].
  nlbools.
  destruct (k =? 1) eqn:EK1;
    [ apply N.eqb_eq in EK1; subst k | apply N.eqb_neq in EK1 ];
    unfold o_ in E; injection E as E1 E2; subst; gz.
Qed.
Lemma fr_span8far_grow (w w2 : word) (f f2 : N) :
  fr_span8far w f = Some (ROk w2 f2) -> gmeas w f <= gmeas w2 f2.
Proof.
  unfold fr_span8far, span8far_out, gmeas. intros E.
  destruct w as [|[[o1 z1] cN] w1]; [discriminate E|].
  destruct w1 as [|[[o2 z2] V] w1']; [nkm E|].
  destruct w1' as [|[[o3 z3] c3] w2'].
  {
    nkm E.
    destruct ((3 <=? cN) && (1 <=? V) && (f =? 3))%bool eqn:EG;
      [|discriminate E].
    nlbools. subst f.
    unfold o_ in E; injection E as E1 E2; subst. gz. }
  destruct w2' as [|[[o4 z4] G] w3'].
  {
    nkm E.
    destruct ((3 <=? cN) && (1 <=? V) && (f =? 4))%bool eqn:EG;
      [|discriminate E].
    nlbools. subst f.
    unfold o_ in E; injection E as E1 E2; subst. gz. }
  destruct w3' as [|g5 t5]; [|nkm E].
  nkm E.
  destruct ((3 <=? cN) && (1 <=? V) && (1 <=? G) && (f =? 4))%bool eqn:EG;
    [|discriminate E].
  nlbools. subst f.
  unfold o_ in E; injection E as E1 E2; subst. gz.
Qed.
Lemma fr_span2B_grow (w w2 : word) (f f2 : N) :
  fr_span2B w f = Some (ROk w2 f2) -> gmeas w f <= gmeas w2 f2.
Proof.
  unfold fr_span2B, gmeas. intros E.
  destruct w as [|[[o1 z1] a] w1]; [discriminate E|].
  destruct w1 as [|[[o2 z2] c2] w1']; [nkm E|].
  destruct w1' as [|[[o3 z3] m] w2']; [nkm E|].
  destruct w2' as [|[[o4 z4] c4] w3']; [nkm E|].
  destruct w3' as [|[[o5 z5] V] w4']; [nkm E|].
  destruct w4' as [|[[o6 z6] c6] w5']; [nkm E|].
  destruct w5' as [|[[o7 z7] G] restB]; [nkm E|].
  nkm E.
  destruct ((1 <=? m) && (1 <=? G))%bool eqn:EG; [|discriminate E].
  nlbools.
  destruct (round2g restB f) as [[t3 f3]|] eqn:ER; [|discriminate E].
  pose proof (round2g_grow _ _ _ _ ER) as HR. unfold gmeas in HR.
  unfold o_ in E; injection E as E1 E2; subst. gz.
Qed.
Lemma fr_span8orph_grow (w w2 : word) (f f2 : N) :
  fr_span8orph w f = Some (ROk w2 f2) -> gmeas w f <= gmeas w2 f2.
Proof.
  unfold fr_span8orph, gmeas. intros E.
  destruct w as [|[[o1 z1] cN] w1]; [discriminate E|].
  destruct w1 as [|[[o2 z2] V] w1']; [nkm E|].
  destruct w1' as [|[[o3 z3] c3] w2']; [nkm E|].
  destruct w2' as [|[[o4 z4] W] w3']; [nkm E|].
  destruct w3' as [|[[o5 z5] c5] w4']; [nkm E|].
  destruct w4' as [|[[o6 z6] G] restB]; [nkm E|].
  nkm E. cbv zeta in E.
  destruct ((2 <=? cN) && (1 <=? V) && (1 <=? G))%bool eqn:EG;
    [|discriminate E].
  nlbools.
  destruct (round1g ((if 1 <? G then [(4,2,G-1)] else []) ++ restB) f)
    as [[t2 f3]|] eqn:ER; [|discriminate E].
  pose proof (round1g_grow _ _ _ _ ER) as HR. unfold gmeas in HR.
  unfold o_ in E; injection E as E1 E2; subst. gz.
Qed.
Lemma s8_tick_target (cN V G : N) :
  tick_target ([(5,1,1); (4,1,1); (3,1,cN-2); (2,2,1); (4,2,V)]
                    ++ [(7,1,1); (3,2,1)]
                    ++ (if 1 <? G then [(4,2,G-1)] else [])) 5%nat
  = Some 5%nat.
Proof. reflexivity. Qed.
Lemma s8_wat (cN V G : N) :
  wat ([(5,1,1); (4,1,1); (3,1,cN-2); (2,2,1); (4,2,V)]
            ++ [(7,1,1); (3,2,1)]
            ++ (if 1 <? G then [(4,2,G-1)] else [])) 5%nat
  = Some (7,1,1).
Proof. reflexivity. Qed.
Lemma fr_span8_grow (w w2 : word) (f f2 : N) :
  fr_span8 w f = Some (ROk w2 f2) -> gmeas w f <= gmeas w2 f2 + 2.
Proof.
  unfold fr_span8, gmeas. intros E.
  destruct w as [|[[o1 z1] cN] w1]; [discriminate E|].
  destruct w1 as [|[[o2 z2] V] w1']; [nkm E|].
  destruct w1' as [|[[o3 z3] c3] w2']; [nkm E|].
  destruct w2' as [|[[o4 z4] G] rest]; [nkm E|].
  nkm E. cbv zeta in E.
  destruct rest as [|gr restt].
  -
    cbv zeta in E.
    destruct ((2 <=? cN) && (1 <=? G) && (f =? 4))%bool eqn:EG4.
    + nlbools. subst f.
      rewrite (s8_tick_target cN V G) in E.
      destruct (deliver_tick FUEL
                  ([(5,1,1); (4,1,1); (3,1,cN-2); (2,2,1); (4,2,V)]
                   ++ [(7,1,1); (3,2,1)]
                   ++ (if 1 <? G then [(4,2,G-1)] else [])) 4 5%nat true)
        as [wd fd| |] eqn:ED; [|discriminate E|discriminate E].
      pose proof (deliver_tick_z1_grow FUEL _ 4 5%nat true 7 1 wd fd
                    (s8_wat cN V G) ED) as HD.
      unfold o_ in E; injection E as E1 E2; subst. gz.
    + destruct ((2 <=? cN) && (1 <=? G) && (5 <=? f))%bool eqn:EG5;
        [|discriminate E].
      nlbools.
      unfold o_ in E; injection E as E1 E2; subst. gz.
  -
    destruct ((2 <=? cN) && (1 <=? G))%bool eqn:EG; [|discriminate E].
    destruct (round2g (gr :: restt) f) as [[t3 f3]|] eqn:ER.
    + pose proof (round2g_grow _ _ _ _ ER) as HR. unfold gmeas in HR.
      nlbools.
      unfold o_ in E; injection E as E1 E2; subst. gz.
    + destruct (round2g_pre8 (gr :: restt) f) as [cols2|] eqn:EP;
        [|discriminate E].
      pose proof (round2g_pre8_grow _ _ _ EP) as HP. unfold gmeas in HP.
      nlbools.
      unfold o_ in E; injection E as E1 E2; subst. gz.
Qed.
Theorem front_grow (w : word) (f : N) (w2 : word) (f2 : N) :
  first_rule front_rules w f = Some (ROk w2 f2) ->
  gmeas w f <= gmeas w2 f2 + 2.
Proof.
  unfold front_rules. cbn [first_rule].
  destruct (fr_primordial w f) as [r|] eqn:E01.
  { intros HH; injection HH as HH; subst r.
    pose proof (fr_primordial_grow w w2 f f2 E01). lia. }
  destruct (fr_prim4 w f) as [r|] eqn:E02.
  { intros HH; injection HH as HH; subst r.
    pose proof (fr_prim4_grow w w2 f f2 E02). lia. }
  destruct (fr_clean w f) as [r|] eqn:E03.
  { intros HH; injection HH as HH; subst r.
    pose proof (fr_clean_grow w w2 f f2 E03). lia. }
  destruct (fr_four w f) as [r|] eqn:E04.
  { intros HH; injection HH as HH; subst r.
    pose proof (fr_four_grow w w2 f f2 E04). lia. }
  destruct (fr_span2A w f) as [r|] eqn:E05.
  { intros HH; injection HH as HH; subst r.
    pose proof (fr_span2A_grow w w2 f f2 E05). lia. }
  destruct (fr_span2A' w f) as [r|] eqn:E06.
  { intros HH; injection HH as HH; subst r.
    pose proof (fr_span2A'_grow w w2 f f2 E06). lia. }
  destruct (fr_span2C' w f) as [r|] eqn:E07.
  { intros HH; injection HH as HH; subst r.
    pose proof (fr_span2C'_grow w w2 f f2 E07). lia. }
  destruct (fr_span8far w f) as [r|] eqn:E08.
  { intros HH; injection HH as HH; subst r.
    pose proof (fr_span8far_grow w w2 f f2 E08). lia. }
  destruct (fr_span2B w f) as [r|] eqn:E09.
  { intros HH; injection HH as HH; subst r.
    pose proof (fr_span2B_grow w w2 f f2 E09). lia. }
  destruct (fr_span8orph w f) as [r|] eqn:E10.
  { intros HH; injection HH as HH; subst r.
    pose proof (fr_span8orph_grow w w2 f f2 E10). lia. }
  destruct (fr_span8 w f) as [r|] eqn:E11.
  { intros HH; injection HH as HH; subst r.
    exact (fr_span8_grow w w2 f f2 E11). }
  destruct (fr_rot w f) as [r|] eqn:E12.
  { intros HH; injection HH as HH; subst r.
    pose proof (fr_rot_grow w w2 f f2 E12). lia. }
  destruct (fr_502 w f) as [r|] eqn:E13.
  { intros HH; injection HH as HH; subst r.
    pose proof (fr_502_grow w w2 f f2 E13). lia. }
  destruct (fr_512 w f) as [r|] eqn:E14.
  { intros HH; injection HH as HH; subst r.
    pose proof (fr_512_grow w w2 f f2 E14). lia. }
  destruct (fr_522 w f) as [r|] eqn:E15.
  { intros HH; injection HH as HH; subst r.
    pose proof (fr_522_grow w w2 f f2 E15). lia. }
  discriminate.
Qed.
Lemma gstd (w : word) (i : nat) (sfx' : word) (f f2 : N) :
  chd22 w = true ->
  ccolcost (skipn i (cbump w)) + 2 * f
    <= ccolcost sfx' + 2 * f2 + 8 ->
  gmeas w f
    <= gmeas (normalize (firstn i (cbump w) ++ sfx')) f2.
Proof.
  intros HC HN. unfold gmeas.
  rewrite ccolcost_normalize, ccolcost_app.
  pose proof (ccl_split w i HC). lia.
Qed.
Lemma gjmp (w body : word) (f f2 : N) :
  ccolcost w + 2 * f <= ccolcost body + 2 * f2 ->
  gmeas w f <= gmeas (normalize body) f2.
Proof. unfold gmeas. rewrite ccolcost_normalize. lia. Qed.
Lemma chd22_guard (w : word) (j : nat) :
  chd22 w = false ->
  match w with
  | g0 :: _ => (gO g0 =? 2) && (gZ g0 =? 2)
               && (1 <=? gC g0) && negb (Nat.eqb j 0)
  | [] => false
  end = false.
Proof.
  destruct w as [|[[o z] c] t]; [reflexivity|].
  cbn [chd22 gO gZ gC]. intros H. rewrite H. reflexivity.
Qed.
Theorem comp_grow (w : word) (f : N) (h : nat)
        (w2 : word) (f2 : N) (i : nat) :
  step_after_front None w f h = (ROk w2 f2, i) ->
  gmeas w f <= gmeas w2 f2.
Proof.
  destruct (chd22 w) eqn:HC.
  2:{
      unfold step_after_front, step_after_front_with,
             step_after_front_with_guard.
      cbn [orb]. cbv zeta.
      destruct (find_active w
                  match w with
                  | (2,2,_) :: _ => if Nat.ltb h 1 then 1%nat else h
                  | _ => h
                  end) as [j|] eqn:EFA.
      - destruct (negb (forallb is_col (firstn j w))); [discriminate|].
        rewrite (chd22_guard w j HC). cbn [negb]. discriminate.
      - destruct w as [|[[o0 z0] c_0] wt]; [discriminate|].
        cbn [chd22] in HC. cbn [gO gZ gC].
        rewrite HC. cbn [andb negb]. discriminate. }
  pose proof (ccl_split w) as HSPL. specialize (fun k => HSPL k HC).
  unfold step_after_front, step_after_front_with,
         step_after_front_with_guard.
  cbn [orb]. cbv zeta.
  destruct (find_active w
              match w with
              | (2,2,_) :: _ => if Nat.ltb h 1 then 1%nat else h
              | _ => h
              end) as [j|] eqn:EFA.
  - destruct (negb (forallb is_col (firstn j w))); [discriminate|].
    match goal with
    | |- context [ if negb ?b then _ else _ ] => destruct (negb b)
    end; [discriminate|].
    match goal with
    | |- context [ if negb ?b then _ else _ ] => destruct (negb b)
    end; [discriminate|].
    change (match w with
            | g0 :: t => (2, 2, gC g0 + 1) :: t
            | [] => w
            end) with (cbump w).
    cbv zeta.
    destruct (skipn j (cbump w)) as [|[[o4 z4] c4] s2t] eqn:ESF; [kdt|].
    specialize (HSPL j). rewrite ESF in HSPL.
    destruct ((o4 =? 4) && (z4 =? 3) && (c4 =? 1) && Nat.leb 3 j) eqn:EG1.
    + destruct s2t as [|[[o5 z5] Bq] rest2].
      *
        destruct (endR_seg (firstn j (cbump w)) f) as [body|] eqn:EER;
          [|kdt].
        intros HH. injection HH as HH1 HH2. subst.
        apply gjmp.
        rewrite (endR_seg_ccolcost _ _ _ EER).
        bs EG1. gcc. lia.
      * destruct ((o5 =? 4) && (z5 =? 2)) eqn:EG2.
        {
          destruct (1 <=? Bq) eqn:EB; [|kdt].
          destruct (jump_comp (firstn j (cbump w)) Bq rest2 f)
            as [[[kk body] ff]|] eqn:EJC; [|kdt].
          rewrite (jump_comp_jmp _ _ _ _ _ _ _ EJC) in EJC |- *.
          pose proof (jump_comp_grow (firstn j (cbump w)) Bq rest2 f
                        body ff ltac:(apply N.leb_le; exact EB) EJC) as HJ.
          intros HH. injection HH as HH1 HH2. subst.
          apply gjmp. bs EG1. bs EG2. gcc. lia. }
        destruct ((z5 =? 3) && (Bq =? 1)
                  && (match rest2 with [] => true | _ => false end)
                  && (f =? 4) && (1 <=? o5)) eqn:EG3.
        {
          destruct rest2 as [|gr rt]; [|bs EG3; discriminate].
          destruct (endY_seg (firstn j (cbump w)) o5) as [body|]
            eqn:EEY; [|kdt].
          intros HH. injection HH as HH1 HH2. subst.
          apply gjmp.
          rewrite (endY_seg_ccolcost _ _ _ EEY).
          bs EG1. bs EG3. gcc. lia. }
        match goal with
        | |- context [ fire_comp ?n ?A ?B ] =>
            pose proof (proj1 (casc_grow n) A B) as HF;
            destruct (fire_comp n A B) as [[sf ff]|] eqn:EFC
        end; [|kdt].
        specialize (HF _ _ eq_refl).
        intros HH. injection HH as HH1 HH2. subst.
        apply gstd; [exact HC|]. rewrite ESF.
        eapply N.le_trans; [exact HF|lia].
    + destruct ((z4 =? 3) && (c4 =? 1)) eqn:EG4.
      {
        match goal with
        | |- context [ fire_comp ?n ?A ?B ] =>
            pose proof (proj1 (casc_grow n) A B) as HF;
            destruct (fire_comp n A B) as [[sf ff]|] eqn:EFC
        end; [|kdt].
        specialize (HF _ _ eq_refl).
        intros HH. injection HH as HH1 HH2. subst.
        apply gstd; [exact HC|]. rewrite ESF.
        eapply N.le_trans; [exact HF|lia]. }
      destruct (z4 =? 1) eqn:EG5.
      {
        match goal with
        | |- context [ leaf_act ?A ?B ] =>
            destruct (leaf_act A B) as [[sl fl]|] eqn:EL; [|kdt]
        end.
        pose proof (leaf_grow _ _ _ _ EL) as HG.
        intros HH. injection HH as HH1 HH2. subst.
        apply gstd; [exact HC|]. rewrite ESF. exact HG. }
      destruct ((z4 =? 4) && (c4 =? 1)) eqn:EG6; [|kdt].
      destruct s2t as [|[[on zn] cn] t2].
      *
        destruct ((o4 =? 4) && (1 <=? f)) eqn:EG7; [|kdt].
        destruct (last2 (firstn j (cbump w)))
          as [[[ini [[ga gaz] gac]] [[gb gbz] gbc]]|] eqn:EL2; [|kdt].
        pose proof (last2_app _ _ _ _ EL2) as HAP.
        destruct ((ga =? 8) && (gaz =? 2) && (gac =? 1)
                  && (gb =? 4) && (gbz =? 2) && (1 <=? gbc)) eqn:EGa.
        { intros HH. injection HH as HH1 HH2. subst.
          apply gjmp.
          rewrite HAP in HSPL.
          bs EG6. bs EG7. bs EGa. gcc. lia. }
        destruct ((gb =? 8) && (gbz =? 2) && (gbc =? 1)) eqn:EGb; [|kdt].
        intros HH. injection HH as HH1 HH2. subst.
        apply gjmp.
        rewrite HAP in HSPL.
        bs EG6. bs EG7. bs EGb. gcc. lia.
      * destruct ((o4 =? 4) && (on =? 4) && (zn =? 2) && (1 <=? cn)) eqn:EGc.
        {
          destruct (last2 (firstn j (cbump w)))
            as [[[ini [[ga gaz] gac]] [[gb gbz] gbc]]|] eqn:EL2; [|kdt].
          pose proof (last2_app _ _ _ _ EL2) as HAP.
          destruct ((ga =? 8) && (gaz =? 2) && (gac =? 1)
                    && (gb =? 4) && (gbz =? 2) && (1 <=? gbc)) eqn:EGa;
            [|kdt].
          intros HH. injection HH as HH1 HH2. subst.
          apply gjmp.
          rewrite HAP in HSPL.
          bs EG6. bs EGc. bs EGa. gz. }
        destruct ((4 <? o4) && (on =? 4) && (zn =? 2) && (1 <=? cn)) eqn:EGd;
          [|kdt].
        intros HH. injection HH as HH1 HH2. subst.
        apply gstd; [exact HC|]. rewrite ESF.
        bs EG6. bs EGd. gz.
  -
    destruct w as [|g0i t]; [discriminate|].
    match goal with
    | |- context [ if negb ?b then _ else _ ] => destruct (negb b)
    end; [discriminate|].
    cbv zeta.
    destruct (cmf_from (g0i :: t) _ _) as [jj|] eqn:ECM.
    + destruct (negb (forallb is_col (firstn jj (g0i :: t))));
        [discriminate|].
      change ((2, 2, gC g0i + 1) :: t) with (cbump (g0i :: t)).
      cbv zeta.
      match goal with
      | |- context [ leaf_act ?A ?B ] =>
          destruct (leaf_act A B) as [[sl fl]|] eqn:EL; [|kcm]
      end.
      pose proof (leaf_grow _ _ _ _ EL) as HG.
      intros HH. injection HH as HH1 HH2. subst.
      apply gstd; [exact HC|]. exact HG.
    + match goal with
      | |- context [ existsb ?p ?l ] => destruct (existsb p l)
      end; [|discriminate].
      cbv zeta.
      match goal with
      | |- context [ debris_to_blank ?A ?B ] =>
          destruct (debris_to_blank A B)
      end; discriminate.
Qed.
Theorem step_grow (w : word) (f : N) (h : nat)
        (w2 : word) (f2 : N) (i : nat) :
  step w f h = (ROk w2 f2, i) -> gmeas w f <= gmeas w2 f2 + 2.
Proof.
  unfold step.
  destruct (first_rule front_rules w f) as [r|] eqn:EFR.
  - unfold step_after_front, step_after_front_with,
           step_after_front_with_guard.
    destruct r as [wr fr| |]; [|discriminate|discriminate].
    intros HH.
    pose proof (front_grow w f wr fr EFR) as HG.
    inversion HH. subst.
    rewrite gmeas_normalize. exact HG.
  - intros HH.
    pose proof (comp_grow w f h w2 f2 i HH). lia.
Qed.
Definition gmeasS (s : sstate) : N :=
  let '(w, f, h) := s in gmeas w f.
Lemma step1_grow (s s' : sstate) :
  step1 s = Some s' -> gmeasS s <= gmeasS s' + 2.
Proof.
  destruct s as [[w f] h]. unfold step1.
  destruct (step w f h) as [[wr fr| |] ii] eqn:ES; try discriminate.
  intros HH. injection HH as HH. subst s'. cbn [gmeasS].
  exact (step_grow w f h wr fr ii ES).
Qed.
Lemma stepk_grow (k : nat) (s s' : sstate) :
  stepk k s = Some s' -> gmeasS s <= gmeasS s' + 2 * N.of_nat k.
Proof.
  revert s. induction k as [|k IH]; intros s.
  - cbn [stepk]. intros HH; injection HH as HH; subst s'. lia.
  - cbn [stepk].
    destruct (step1 s) as [s1|] eqn:E1; [|discriminate].
    intros HH.
    pose proof (step1_grow _ _ E1) as H1.
    pose proof (IH _ HH) as H2.
    rewrite Nat2N.inj_succ. lia.
Qed.
Lemma stepN_grow (n : N) (s s' : sstate) :
  stepN n s = Some s' -> gmeasS s <= gmeasS s' + 2 * n.
Proof.
  unfold stepN. intros H.
  pose proof (stepk_grow _ _ _ H) as HG.
  rewrite N2Nat.id in HG. exact HG.
Qed.
