Ltac ubfin ::=
  cbn [fst snd];
  try (unfold word in *);
  rewrite ?chi_cadd, ?chi_cx, ?chi_cundef, ?chi_czero;
  rewrite ?ccolcost_cons, ?ccolcost_consn,
          ?ccolcost_nil, ?ccolcost_niln,
          ?ccg_unfold in *;
  (lia || nia).
Lemma ccolcost_firstn_le (w : word) (n : nat) :
  ccolcost (firstn n w) <= ccolcost w.
Proof. rewrite (ccolcost_split w n). lia. Qed.
Lemma ccolcost_skipn_le (w : word) (n : nat) :
  ccolcost (skipn n w) <= ccolcost w.
Proof. rewrite (ccolcost_split w n). lia. Qed.
Lemma ccolcost_cbump_le (w : word) :
  ccolcost (cbump w) <= 2 * ccolcost w + 10.
Proof.
  destruct w as [|[[o z] c] t]; [cbn; apply N.le_0_l|].
  unfold cbump. cbn [gC].
  rewrite !ccolcost_cons, !ccg_unfold. nia.
Qed.
Ltac fub := cbn [chi cundef cx fst snd]; try lia.
Ltac dfront :=
  repeat (cbv iota;
          match goal with
          | |- context [ match ?x with _ => _ end ] => is_var x; destruct x
          end);
  cbv iota;
  cbn [chi cx cundef fst snd];
  rewrite ?ccolcost_cons, ?ccg_unfold;
  (lia || nia).
Lemma d_rot_ub (w : word) (f : N) :
  chi (d_rot w f) <= ccolcost w + 19.
Proof. unfold d_rot. fub. Qed.
Lemma d_502_ub (w : word) (f : N) :
  chi (d_502 w f) <= ccolcost w + 19.
Proof. unfold d_502. dfront. Qed.
Lemma d_512_ub (w : word) (f : N) :
  chi (d_512 w f) <= ccolcost w + 19.
Proof. unfold d_512. dfront. Qed.
Lemma d_522_ub (w : word) (f : N) :
  chi (d_522 w f) <= ccolcost w + 17.
Proof. unfold d_522. dfront. Qed.
Lemma d_primordial_ub (w : word) (f : N) :
  chi (d_primordial w f) <= ccolcost w + 17.
Proof. unfold d_primordial. dfront. Qed.
Lemma d_prim4_ub (w : word) (f : N) :
  chi (d_prim4 w f) <= ccolcost w + 184.
Proof. unfold d_prim4. dfront. Qed.
Lemma d_span2A'_ub (w : word) (f : N) :
  chi (d_span2A' w f) <= ccolcost w + 43.
Proof. unfold d_span2A'. dfront. Qed.
Lemma d_span2C'_ub (w : word) (f : N) :
  chi (d_span2C' w f) <= 2 * ccolcost w + 83.
Proof. unfold d_span2C'. dfront. Qed.
Lemma d_span8far_ub (w : word) (f : N) :
  chi (d_span8far w f) <= 3 * ccolcost w + 28.
Proof. unfold d_span8far. dfront. Qed.
Lemma d_jcomp_ub (pre : word) (Bq : N) (post : word) (f : N) :
  chi (d_jcomp pre Bq post f)
    <= ccolcost pre + 28 * Bq + 2 * ccolcost post + 2 * f + 92.
Proof.
  unfold d_jcomp.
  destruct (negb (forallb is_col pre)); [ubfin|].
  destruct post as [|g0 postT].
  { unfold dseg_lawR.
    destruct (f =? 4) eqn:E4.
    { apply N.eqb_eq in E4.
      eapply N.le_trans;
        [apply (dseg_ub pre (fun gbc => 14 * gbc + 14 * Bq + 65)
                  (14 * Bq + 65)); intros; lia|]. lia. }
    destruct (5 <=? f) eqn:E5.
    { eapply N.le_trans;
        [apply (dseg_ub pre (fun gbc => 14 * gbc + 14 * Bq + 2 * f + 57)
                  (14 * Bq + 2 * f + 57)); intros; lia|]. lia. }
    ubfin. }
  destruct (jump_seg pre Bq) as [sg|] eqn:EJS; [|ubfin].
  destruct (seek (g0 :: postT)) as [cols2 s3] eqn:Esk.
  pose proof (ccolcost_seek_eq _ _ _ Esk) as HSK.
  match goal with
  | |- context [ crenew_seg ?a ?b ?cc ?d ] =>
      destruct (fst (crenew_seg a b cc d)) as [[bd fd]|] eqn:ER
  end.
  { match goal with
    | ER : fst (crenew_seg ?a ?b ?cc ?d) = _ |- _ =>
        pose proof (proj2 (cascade_ub a) b cc d bd fd ER) as IHq
    end.
    unfold ubc in IHq. unfold d_jsplice. ubfin. }
  destruct s3 as [|[[o7 z7] c7] s3t].
  { destruct (5 <=? f); [ubfin|].
    destruct (f =? 4); [|ubfin].
    match goal with
    | |- context [ dtb4_convc ?a ] =>
        destruct (dtb4_convc a) as [[bd2 Kd]|] eqn:ED
    end.
    - pose proof (dtb4_convc_ub _ _ _ ED) as HD. ubfin.
    - destruct (forallb w42 cols2); [|ubfin].
      destruct (lawR_seg pre Bq); ubfin. }
  destruct ((z7 =? 3) && (c7 =? 1))%bool.
  { match goal with
    | |- context [ cfire_comp ?a ?b ?cc ] =>
        destruct (fst (cfire_comp a b cc)) as [[sd fd]|] eqn:EFq
    end; [|ubfin].
    match goal with
    | EFq : fst (cfire_comp ?a ?b ?cc) = _ |- _ =>
        pose proof (proj1 (cascade_ub a) b cc sd fd EFq) as IHq
    end.
    unfold ubc in IHq. unfold d_cols, d_jsplice. ubfin. }
  match goal with
  | |- context [ sand_leaf ?a ] => destruct (sand_leaf a)
  end; [ubfin|].
  match goal with
  | |- context [ cleaf_act ?b ?cc ] =>
      destruct (fst (cleaf_act b cc)) as [[sd fd]|] eqn:EL
  end; [|ubfin].
  match goal with
  | EL : fst (cleaf_act ?b ?cc) = _ |- _ =>
      pose proof (cleaf_act_ub b cc sd fd EL) as IHq
  end.
  unfold ubc in IHq. ubfin.
Qed.
Lemma last2_gb_ccolcost (l ini : word) (a : bg) (gb gbz gbc : N) :
  last2 l = Some (ini, a, (gb, gbz, gbc)) ->
  gbc * (2 * gb + 6) <= ccolcost l.
Proof.
  intros E. rewrite (last2_app _ _ _ _ E).
  rewrite ccolcost_app.
  rewrite !ccolcost_cons. cbn [ccolcost].
  rewrite !ccg_unfold. lia.
Qed.
Lemma chi_cdisp_ftrip (w : word) (s : nat) (d : cost) :
  chi (cdispatch Tftrip w s d)
  = ccolcost (firstn s w) + (chi d + 6).
Proof. reflexivity. Qed.
Lemma chi_cdisp_loc (w : word) (s : nat) (d : cost) :
  chi (cdispatch Tloc w s d)
  = ccolcost (firstn s w) + (chi d + 0).
Proof. reflexivity. Qed.
Lemma dseg_endR_ub (cols : word) (f : N) :
  chi (dseg_endR cols f) <= ccolcost cols + 2 * f + 57.
Proof.
  unfold dseg_endR. destruct (2 <=? f); [|ubfin].
  eapply N.le_trans;
    [apply (dseg_ub cols (fun gbc => 14 * gbc + 2 * f + 57) (2 * f + 57));
     intros; lia|]. lia.
Qed.
Lemma dseg_endY_ub (cols : word) (y : N) :
  chi (dseg_endY cols y) <=
  ccolcost cols + 2 * y + 79.
Proof.
  unfold dseg_endY.
  eapply N.le_trans;
    [apply (dseg_ub cols (fun gbc => 14 * gbc + 2 * y + 79)
              (2 * y + 79)); intros; lia|].
  lia.
Qed.
Theorem d_comp_site_ub (w : word) (f : N) (h : nat)
        (w2 : word) (f2 : N) (i : nat) :
  step_after_front None w f h = (ROk w2 f2, i) ->
  chi (d_comp w f h) <= 20 * ccolcost w + 2 * f + 300.
Proof.
  pose proof (ccolcost_cbump_le w) as HB.
  pose proof (fun n => ccolcost_firstn_le (cbump w) n) as HFB.
  pose proof (fun n => ccolcost_skipn_le (cbump w) n) as HKB.
  pose proof (fun n => ccolcost_firstn_le w n) as HFW.
  unfold step_after_front, step_after_front_with,
         step_after_front_with_guard, d_comp.
  cbn [orb]. cbv zeta.
  destruct (find_active w
              match w with
              | (2,2,_) :: _ => if Nat.ltb h 1 then 1%nat else h
              | _ => h
              end) as [j|] eqn:EFA.
  - destruct (negb (forallb is_col (firstn j w))); [discriminate|].
    match goal with
    | |- context [ if negb ?b then _ else _ ] => destruct (negb b)
    end; [discriminate|].
    match goal with
    | |- context [ if negb ?b then _ else _ ] => destruct (negb b)
    end; [discriminate|].
    change (match w with
            | g0 :: t => (2, 2, gC g0 + 1) :: t
            | [] => w
            end) with (cbump w).
    cbv zeta.
    destruct (skipn j (cbump w)) as [|[[o4 z4] c4] s2t] eqn:ESF;
      [kdt|].
    specialize (HKB j). rewrite ESF in HKB.
    rewrite ?ccolcost_cons, ?ccg_unfold in HKB.
    destruct ((o4 =? 4) && (z4 =? 3) && (c4 =? 1) && Nat.leb 3 j) eqn:EG1.
    + destruct s2t as [|[[o5 z5] Bq] rest2].
      *
        intros _. rewrite chi_cdisp_ftrip.
        pose proof (dseg_endR_ub (skipn 1 (firstn j (cbump w))) f) as HD.
        pose proof (ccolcost_skipn_le (firstn j (cbump w)) 1) as HS1.
        specialize (HFB j). specialize (HFW 1%nat). lia.
      * destruct ((o5 =? 4) && (z5 =? 2)) eqn:EG2.
        { destruct (1 <=? Bq) eqn:EB; [|intros _; ubfin].
          intros _. rewrite chi_cdisp_ftrip.
          pose proof (d_jcomp_ub (skipn 1 (firstn j (cbump w)))
                        Bq rest2 f) as HD.
          pose proof (ccolcost_skipn_le (firstn j (cbump w)) 1) as HS1.
          specialize (HFB j). specialize (HFW 1%nat).
          rewrite ?ccolcost_cons, ?ccg_unfold in HKB.
          nia. }
        destruct ((z5 =? 3) && (Bq =? 1)
                  && (match rest2 with [] => true | _ => false end)
                  && (f =? 4) && (1 <=? o5)) eqn:EG3.
        { intros _. rewrite chi_cdisp_ftrip.
          apply andb_prop in EG3; destruct EG3 as [EG3 Eo5].
          apply andb_prop in EG3; destruct EG3 as [EG3 Ef4].
          apply andb_prop in EG3; destruct EG3 as [EG3 Erest].
          apply andb_prop in EG3; destruct EG3 as [Ez5 EBq].
          apply N.eqb_eq in EBq. apply N.eqb_eq in Ef4.
          subst Bq f.
          pose proof (dseg_endY_ub
            (skipn 1 (firstn j (cbump w))) o5) as HD.
          pose proof (ccolcost_skipn_le
            (firstn j (cbump w)) 1) as HS1.
          specialize (HFB j). specialize (HFW 1%nat).
          rewrite ?ccolcost_cons, ?ccg_unfold in HKB.
          nia. }
        match goal with
        | |- context [ fire_comp ?n ?A ?B ] =>
            destruct (fire_comp n A B) as [[sf ff]|] eqn:EFC
        end; [|kdt].
        intros _.
        match goal with
        | |- context [ cfire_comp ?n ?A ?B ] =>
            assert (HQ : fst (cfire_comp n A B) = Some (sf, ff))
              by (rewrite cfire_comp_proj; exact EFC);
            pose proof (proj1 (cascade_ub n) A B sf ff HQ) as HC
        end.
        unfold ubc in HC. rewrite chi_cdisp_ftrip.
        rewrite ?ccolcost_cons, ?ccg_unfold in HC.
        rewrite ?ccolcost_cons, ?ccg_unfold in HKB.
        specialize (HFW j). lia.
    + destruct ((z4 =? 3) && (c4 =? 1)) eqn:EG4.
      { match goal with
        | |- context [ fire_comp ?n ?A ?B ] =>
            destruct (fire_comp n A B) as [[sf ff]|] eqn:EFC
        end; [|kdt].
        intros _.
        match goal with
        | |- context [ cfire_comp ?n ?A ?B ] =>
            assert (HQ : fst (cfire_comp n A B) = Some (sf, ff))
              by (rewrite cfire_comp_proj; exact EFC);
            pose proof (proj1 (cascade_ub n) A B sf ff HQ) as HC
        end.
        unfold ubc in HC. rewrite chi_cdisp_ftrip.
        rewrite ?ccolcost_cons, ?ccg_unfold in HC.
        rewrite ?ccolcost_cons, ?ccg_unfold in HKB.
        specialize (HFW j). lia. }
      destruct (z4 =? 1) eqn:EG5.
      { match goal with
        | |- context [ leaf_act ?A ?B ] =>
            destruct (leaf_act A B) as [[sl fl]|] eqn:EL
        end; [|kdt].
        intros _.
        match goal with
        | |- context [ cleaf_act ?A ?B ] =>
            assert (HQ : fst (cleaf_act A B) = Some (sl, fl))
              by (rewrite cleaf_act_proj; exact EL);
            pose proof (cleaf_act_ub A B sl fl HQ) as HC
        end.
        unfold ubc in HC. rewrite chi_cdisp_loc.
        rewrite ?ccolcost_cons, ?ccg_unfold in HC.
        rewrite ?ccolcost_cons, ?ccg_unfold in HKB.
        specialize (HFW j). lia. }
      destruct ((z4 =? 4) && (c4 =? 1)) eqn:EG6; [|intros _; ubfin].
      apply andb_prop in EG6. destruct EG6 as [EG6a EG6b].
      apply N.eqb_eq in EG6b. subst c4.
      destruct s2t as [|[[on zn] cn] t2].
      * destruct ((o4 =? 4) && (1 <=? f)) eqn:EG7; [|intros _; ubfin].
        destruct (last2 (firstn j (cbump w)))
          as [[[ini [[ga gaz] gac]] [[gb gbz] gbc]]|] eqn:EL2;
          [|intros _; ubfin].
        pose proof (last2_gb_ccolcost _ _ _ _ _ _ EL2) as HG.
        specialize (HFB j).
        destruct ((ga =? 8) && (gaz =? 2) && (gac =? 1)
                  && (gb =? 4) && (gbz =? 2) && (1 <=? gbc)) eqn:EGa.
        { intros _. rewrite chi_cdisp_ftrip. unfold d_lcol.
          rewrite chi_cx. specialize (HFW (List.length ini)). nia. }
        destruct ((gb =? 8) && (gbz =? 2) && (gbc =? 1)) eqn:EGb;
          [|intros _; ubfin].
        intros _. rewrite chi_cdisp_ftrip. unfold d_lcol.
        rewrite chi_cx. specialize (HFW (S (List.length ini))). lia.
      * destruct ((o4 =? 4) && (on =? 4) && (zn =? 2) && (1 <=? cn)) eqn:EGc.
        { destruct (last2 (firstn j (cbump w)))
            as [[[ini [[ga gaz] gac]] [[gb gbz] gbc]]|] eqn:EL2;
            [|intros _; ubfin].
          pose proof (last2_gb_ccolcost _ _ _ _ _ _ EL2) as HG.
          specialize (HFB j).
          destruct ((ga =? 8) && (gaz =? 2) && (gac =? 1)
                    && (gb =? 4) && (gbz =? 2) && (1 <=? gbc)) eqn:EGa;
            [|intros _; ubfin].
          intros _. rewrite chi_cdisp_ftrip. unfold d_lcol.
          rewrite chi_cx. specialize (HFW (List.length ini)). nia. }
        destruct ((4 <? o4) && (on =? 4) && (zn =? 2) && (1 <=? cn)) eqn:EGd;
          [|intros _; ubfin].
        intros _. rewrite chi_cdisp_ftrip. unfold d_lcstd.
        rewrite chi_cx. specialize (HFW j). nia.
  -
    destruct w as [|[[og zg] cg] t]; [discriminate|].
    lazymatch goal with
    | |- (if ?b then _ else _) = _ -> _ => destruct b
    end; [discriminate|].
    cbv zeta.
    match goal with
    | |- context [ cmf_from ?a ?b ?c ] =>
        destruct (cmf_from a b c) as [jj|] eqn:ECM
    end; [|intros _; ubfin].
    lazymatch goal with
    | |- (if ?b then _ else _) = _ -> _ => destruct b
    end; [discriminate|].
    cbv zeta.
    match goal with
    | |- context [ leaf_act ?A ?B ] =>
        destruct (leaf_act A B) as [[sl fl]|] eqn:EL
    end; [|kcm].
    intros _.
    match goal with
    | |- context [ cleaf_act ?A ?B ] =>
        assert (HQ : fst (cleaf_act A B) = Some (sl, fl))
          by (rewrite cleaf_act_proj; exact EL);
        pose proof (cleaf_act_ub A B sl fl HQ) as HC
    end.
    unfold ubc in HC. rewrite chi_cdisp_loc.
    specialize (HFW jj).
    match goal with
    | |- _ <= 20 * ccolcost ?W0 + _ + _ =>
      match goal with
      | |- context [ cleaf_act (skipn ?J ?W1) _ ] =>
          assert (HS1 : ccolcost (skipn J W1) <= ccolcost W1)
            by exact (ccolcost_skipn_le W1 J);
          assert (HB1 : ccolcost W1 <= 2 * ccolcost W0 + 10)
            by exact (ccolcost_cbump_le ((og, zg, cg) :: t))
      end
    end.
    lia.
Qed.
Local Open Scope N_scope.
Local Open Scope bool_scope.
Local Open Scope sym.
Local Open Scope N_scope.
Local Open Scope bool_scope.
Local Open Scope sym.
Local Open Scope N_scope.
Definition phi (w : word) (f : N) (k : ncost) : N :=
  gmeas w f + 2 * fst k.
Definition phi_st (s : lpstate) (k : ncost) : N :=
  let '(w, f, _) := lp_sem s in phi w f k.
Lemma lin_zsp_grow (w : word) (f : N) (h : nat)
      (t : N) (st' : sstate) (d : cost) :
  lin_zsp w f h = Some (t, st', d) -> gmeas w f <= gmeasS st' + 2 * t.
Proof.
  intros H.
  exact (stepN_grow t (w,f,h) st'
    (zjump3_sound _ _ _ _ _
      (lin_zsp_proj _ _ _ _ _ _ H))).
Qed.
Definition dom_of (w : word) (f : N) (k : ncost) (r : lpnext)
  : Prop :=
  match r with
  | LPNext k' _ s' => phi w f k <= phi_st s' k'
  | LPGuard k' _ wT fT => phi w f k <= phi wT fT k'
  | LPBad _ _ _ _ => True
  end.
Lemma dom_mono (w : word) (f : N) (k : ncost)
      (w2 : word) (f2 : N) (k2 : ncost) (r : lpnext) :
  phi w f k <= phi w2 f2 k2 -> dom_of w2 f2 k2 r -> dom_of w f k r.
Proof.
  unfold dom_of. destruct r as [k' m' s'|k' m' wT fT|k' m' wT fT];
    [intros H1 H2; lia|intros H1 H2; unfold phi in *; lia|intros; exact I].
Qed.
Theorem lp_fbrr_dom (fu : nat) (T : ctot) (w : word) (f : N)
        (h : nat) (k : ncost) (m : nat) :
  dom_of w f k (lp_fallback_round_run fu T w f h k m).
Proof.
  revert T w f h k m.
  induction fu as [|fu IH]; intros T w f h k m.
  - cbn [lp_fallback_round_run].
    cbn [dom_of phi_st lp_sem]. unfold phi. lia.
  - cbn [lp_fallback_round_run].
    destruct (lin_zsp w f h) as [[[t [[w2 f2] h2]] dz]|] eqn:EZ.
    + pose proof (lin_zsp_grow _ _ _ _ _ _ EZ) as HZ. cbn [gmeasS] in HZ.
      apply (dom_mono w f k w2 f2 (nc_rbump k t)); [|apply IH].
      unfold phi, nc_rbump; cbn [fst]. lia.
    + destruct (step w f h) as [[wr fr| |] ii] eqn:ES.
      * pose proof (step_grow _ _ _ _ _ _ ES) as HS.
        destruct (lin_round_closing w f).
        {
          cbn [dom_of phi_st lp_sem]. unfold phi, nc_bump; cbn [fst].
          lia. }
        apply (dom_mono w f k wr fr (nc_qbump k 1 czero));
          [|apply IH].
        unfold phi, nc_qbump; cbn [fst]. lia.
      * cbn [dom_of]. unfold phi, nc_bump; cbn [fst]. lia.
      * cbn [dom_of]. exact I.
Qed.
Lemma lp_fbrr_flat_step (fu : nat) (T : ctot) (w : word) (f : N)
      (h : nat) (k : ncost) (m : nat) (w2 : word) (f2 : N) (i : nat)
      :
  lin_zsp w f h = None ->
  step w f h = (ROk w2 f2, i) ->
  lin_round_closing w f = false ->
  lp_fallback_round_run (S fu) T w f h k m
  = lp_fallback_round_run fu None w2 f2
      (if Nat.ltb i 5 then O else (i - 4)%nat)
      (nc_qbump k 1 czero) (S m).
Proof.
  intros HZ HS HC. cbn [lp_fallback_round_run].
  rewrite HZ, HS, HC. reflexivity.
Qed.
Lemma lp_fbrr_span_step (fu : nat) (T : ctot) (w : word) (f : N)
      (h : nat) (k : ncost) (m : nat) (t : N) (w2 : word) (f2 : N)
      (h2 : nat) (dz : cost) :
  lin_zsp w f h = Some (t, (w2, f2, h2), dz) ->
  lp_fallback_round_run (S fu) T w f h k m
  = lp_fallback_round_run fu None w2 f2 h2 (nc_rbump k t) (S m).
Proof.
  intros HZ. cbn [lp_fallback_round_run]. rewrite HZ. reflexivity.
Qed.
Set Warnings "require-in-module".
Local Open Scope N_scope.
Opaque FLAT_ROUND_FUEL LROUND_FUEL LROUND_CHUNKS.
Opaque front_late.
Definition cmeas (sg : list seg) (cw : word) (f : N) : N :=
  gmeas (lin_flat sg cw) f.
Definition lpm (s : lpstate) : N :=
  match s with
  | LPFlat w f _ => gmeas w f
  | LPCond sg _ cw f _ _ => cmeas sg cw f
  end.
Lemma lpm_phi_st (s : lpstate) (k : ncost) :
  phi_st s k = lpm s + 2 * fst k.
Proof.
  destruct s as [w f h|sg ps cw f h j];
    cbn [phi_st lp_sem lpm]; unfold phi, cmeas; reflexivity.
Qed.
Definition FrontCloseDom : Prop :=
  forall (sg : list seg) (cw : word) (f : N)
         (q : nat) (cw2 : word) (f2 : N),
    lin_front_close cw f = Some (q, cw2, f2) ->
    cmeas sg cw f <= cmeas sg cw2 f2 + 2 * N.of_nat q.
Definition FlightDom : Prop :=
  forall (fr : option res) (sg : list seg) (ps : atab)
         (cw : word) (f : N) (h : nat)
         (t : N) (cw2 : word) (sg2 : list seg) (ps2 : atab)
         (f2 : N) (fs : nat),
    stable_guard sg cw ->
    lin_gen_action_at fr sg ps cw f h
      = Some (Some (t, cw2, sg2, ps2, f2, fs)) ->
    cmeas sg cw f <= cmeas sg2 cw2 f2 + 2 * t.
Definition TickFrontDom : Prop :=
  forall (fr : option res) (sg : list seg) (ps : atab)
         (cw : word) (f : N) (h : nat)
         (q : N) (cw2 : word) (sg2 : list seg) (ps2 : atab)
         (f2 : N) (fs : nat),
    stable_guard sg cw ->
    lin_tick_front_at fr sg ps cw f h
      = Some (q, cw2, sg2, ps2, f2, fs) ->
    cmeas sg cw f <= cmeas sg2 cw2 f2 + 2 * q.
Definition MicroDom : Prop :=
  forall (fr : option res) (sg : list seg)
         (cw : word) (f : N) (h : nat)
         (cw2 : word) (f2 : N) (i : nat),
    stable_guard sg cw ->
    lin_guard sg cw = true ->
    fr = front_gate cw f ->
    step_after_front_with_guard false
      (lin_normalize_at sg)
      (fun pre sfx _ => lin_normalize_join sg pre sfx) fr cw f h
      = (ROk cw2 f2, i) ->
    cmeas sg cw f <= cmeas sg cw2 f2 + 2.
Definition PostDom : Prop :=
  forall (fr : option res) (sg : list seg) (ps : atab)
         (cw : word) (i : nat) (f : N)
         (sg3 : list seg) (ps3 : atab) (cw3 : word) (i3 : nat),
    stable_guard sg cw ->
    lin_step_post fr sg ps cw i = Some (sg3, ps3, cw3, i3) ->
    cmeas sg cw f <= cmeas sg3 cw3 f.
Definition RepackFlat : Prop :=
  forall (sg : list seg) (ps : atab) (cw : word)
         (sg2 : list seg) (ps2 : atab) (cw2 : word),
    stable_guard sg cw ->
    lin_repack_when_needed sg ps cw = Some (sg2, ps2, cw2) ->
    lin_flat sg2 cw2 = lin_flat sg cw.
Record CondArms : Prop := MkCondArms {
  ca_flight : FlightDom;
  ca_tick   : TickFrontDom;
  ca_micro  : MicroDom }.
Theorem post_dom_stable (fr : option res) (sg : list seg)
        (ps : atab) (cw : word) (i : nat) (f : N)
        (sg3 : list seg) (ps3 : atab) (cw3 : word) (i3 : nat) :
  stable_guard sg cw ->
  lin_step_post fr sg ps cw i = Some (sg3, ps3, cw3, i3) ->
  cmeas sg cw f = cmeas sg3 cw3 f.
Proof.
  intros HS HP.
  destruct (lin_step_post_settled fr sg ps cw i sg3 ps3 cw3 i3 HS HP)
    as [HF _].
  unfold cmeas. rewrite HF. reflexivity.
Qed.
Theorem post_dom : PostDom.
Proof.
  intros fr sg ps cw i f sg3 ps3 cw3 i3 HS HP.
  rewrite (post_dom_stable fr sg ps cw i f sg3 ps3 cw3 i3 HS HP). lia.
Qed.
Theorem repack_flat_stable (sg : list seg) (ps : atab)
        (cw : word) (sg2 : list seg) (ps2 : atab)
        (cw2 : word) :
  stable_guard sg cw ->
  lin_repack_when_needed sg ps cw = Some (sg2, ps2, cw2) ->
  lin_flat sg2 cw2 = lin_flat sg cw.
Proof.
  intros HS HR.
  destruct (T_repack_stable_holds sg ps cw sg2 ps2 cw2 HS HR) as [HF _].
  exact HF.
Qed.
Theorem repack_flat : RepackFlat.
Proof. exact repack_flat_stable. Qed.
Lemma GrowD_ccolcost_nil : ccolcost [] = 0.
Proof. reflexivity. Qed.
Lemma keyb_nontag (sg : list seg) (g : bg) :
  tagbase g = false -> keyb sg g = None.
Proof.
  intros H. unfold keyb, keyi, phshape.
  rewrite H. cbn [andb]. reflexivity.
Qed.
Lemma lin_flat_cons_ccol (sg : list seg) (g : bg) (t : word) :
  ccolcost (lin_flat sg (g :: t))
  = (match keyb sg g with
     | Some b => ccolcost b
     | None => ccg g
     end) + ccolcost (lin_flat sg t).
Proof.
  cbn [lin_flat]. destruct (keyb sg g);
    [apply ccolcost_app|apply ccolcost_cons].
Qed.
Lemma GrowD_tagbase_c (o z c c' : N) : tagbase (o,z,c) = tagbase (o,z,c').
Proof. reflexivity. Qed.
Theorem lin_ccolcost_lnf (sg : list seg) (w : word) :
  ccolcost (lin_flat sg (lin_normalize_full w))
  = ccolcost (lin_flat sg w).
Proof.
  induction w as [|g t IH]; [reflexivity|].
  destruct g as [[o z] c]. cbn [lin_normalize_full].
  destruct (lin_normalize_full t) as [|g2 t2] eqn:EN.
  - rewrite !lin_flat_cons_ccol. cbn [lin_flat] in IH |- *.
    rewrite GrowD_ccolcost_nil in IH |- *. lia.
  - destruct g2 as [[o2 z2] c2].
    destruct (tagbase (o,z,c) || tagbase (o2,z2,c2))%bool eqn:ET.
    + rewrite !lin_flat_cons_ccol. rewrite <- IH.
      rewrite lin_flat_cons_ccol. reflexivity.
    + apply orb_false_iff in ET as [ET1 ET2].
      destruct ((o =? o2) && (z =? z2))%bool eqn:EQ.
      * apply andb_true_iff in EQ as [E1 E2].
        apply N.eqb_eq in E1. apply N.eqb_eq in E2. subst o2 z2.
        assert (K1 : keyb sg (o,z,c) = None)
          by (apply keyb_nontag; exact ET1).
        assert (K2 : keyb sg (o,z,c2) = None)
          by (apply keyb_nontag; exact ET2).
        assert (K3 : keyb sg (o,z,c+c2) = None)
          by (apply keyb_nontag; rewrite (GrowD_tagbase_c o z (c+c2) c); exact ET1).
        assert (HL : ccolcost (lin_flat sg ((o,z,c+c2)%N :: t2))
                     = ccg (o,z,c+c2)%N
                       + ccolcost (lin_flat sg t2))
          by (rewrite lin_flat_cons_ccol, K3; reflexivity).
        assert (HR : ccolcost (lin_flat sg ((o,z,c)%N :: t))
                     = ccg (o,z,c)%N
                       + ccolcost (lin_flat sg t))
          by (rewrite lin_flat_cons_ccol, K1; reflexivity).
        assert (HI : ccg (o,z,c2)%N + ccolcost (lin_flat sg t2)
                     = ccolcost (lin_flat sg t)).
        { rewrite <- IH, lin_flat_cons_ccol, K2. reflexivity. }
        transitivity (ccg (o,z,c+c2)%N
                      + ccolcost (lin_flat sg t2)); [exact HL|].
        symmetry.
        transitivity (ccg (o,z,c)%N
                      + ccolcost (lin_flat sg t)); [exact HR|].
        unfold ccg in HI |- *. cbn [gC gO] in HI |- *.
        rewrite N.mul_add_distr_r. lia.
      * rewrite !lin_flat_cons_ccol. rewrite <- IH.
        rewrite lin_flat_cons_ccol. reflexivity.
Qed.
Corollary gmeas_lnf (sg : list seg) (w : word) (f : N) :
  gmeas (lin_flat sg (lin_normalize_full w)) f
  = gmeas (lin_flat sg w) f.
Proof. unfold gmeas. rewrite lin_ccolcost_lnf. reflexivity. Qed.
Lemma fcd_finish (sg : list seg) (P Q t : word) (f q : N) :
  forallb nobase P = true ->
  forallb nobase Q = true ->
  ccolcost P <= ccolcost Q + 2 * q ->
  cmeas sg (P ++ t) f
    <= cmeas sg (lin_normalize_full (Q ++ t)) f + 2 * q.
Proof.
  intros HP HQ HC. unfold cmeas.
  rewrite (gmeas_lnf sg (Q ++ t) f).
  rewrite (flat_nobase_app sg P t HP), (flat_nobase_app sg Q t HQ).
  unfold gmeas. rewrite !ccolcost_app. lia.
Qed.
Lemma fcd_clean (sg : list seg) (P : word) (K : N)
      (t : word) (f : N) (qn : N) (q q2 : nat)
      (cw2 : word) (f2 : N) :
  forallb nobase P = true ->
  (2 <= K -> ccolcost P <= ccolcost (Qclean K) + 2 * qn) ->
  lin_front_done q
    (fr_clean ((2,2,4)%N :: (5,2,1)%N :: (3,1,K)%N :: t) f)
    = Some (q2, cw2, f2) ->
  cmeas sg (P ++ t) f <= cmeas sg cw2 f2 + 2 * qn.
Proof.
  intros HP HC HD.
  destruct (front_done_clean_inv q K t f q2 cw2 f2 HD)
    as (HK & _ & Hf & Hw). subst f2 cw2.
  pose proof (fcd_finish sg P (Qclean K) t f qn HP
                (nobase_Qclean K) (HC HK)) as HR.
  unfold Qclean in HR.
  destruct (N.odd K); cbn [app] in HR |- *; exact HR.
Qed.
Lemma fcd_four (sg : list seg) (P : word) (n M : N)
      (t : word) (f : N) (qn : N) (q q2 : nat)
      (cw2 : word) (f2 : N) :
  forallb nobase P = true ->
  (2 <= M -> ccolcost P <= ccolcost (Qfour n M) + 2 * qn) ->
  lin_front_done q
    (fr_four ((2,2,n)%N :: (4,2,1)%N :: (4,1,M)%N :: t) f)
    = Some (q2, cw2, f2) ->
  cmeas sg (P ++ t) f <= cmeas sg cw2 f2 + 2 * qn.
Proof.
  intros HP HC HD.
  destruct (front_done_four_inv q n M t f q2 cw2 f2 HD)
    as (HM & _ & Hf & Hw). subst f2 cw2.
  pose proof (fcd_finish sg P (Qfour n M) t f qn HP
                (nobase_Qfour n M) (HC HM)) as HR.
  unfold Qfour in HR.
  destruct (N.odd M); cbn [app] in HR |- *; exact HR.
Qed.
Lemma div2_split (x : N) : x = 2 * N.div2 x + (if N.odd x then 1 else 0).
Proof. destruct x as [|p]; [reflexivity|destruct p; reflexivity]. Qed.
Lemma odd_succ_neg (M : N) : N.odd (M + 1) = negb (N.odd M).
Proof. rewrite N.add_1_r, N.odd_succ, <- N.negb_odd. reflexivity. Qed.
Ltac fcd_arith :=
  cbn [ccolcost gO gZ gC app N.b2n];
  lia.
Ltac fcd_four_arith M :=
  let HD := fresh "HD" in let HD1 := fresh "HD1" in
  let HO := fresh "HO" in let EM := fresh "EM" in
  pose proof (div2_split M) as HD;
  pose proof (div2_split (M + 1)) as HD1;
  pose proof (odd_succ_neg M) as HO;
  unfold Qfour;
  destruct (N.odd M) eqn:EM; rewrite HO in HD1; cbn [negb] in HD1;
  fcd_arith.
Ltac fcd_clean_arith K :=
  let HD := fresh "HD" in let EK := fresh "EK" in
  pose proof (div2_split K) as HD;
  unfold Qclean;
  destruct (N.odd K) eqn:EK; fcd_arith.
Lemma qf_522_1 (c M : N) : 2 <= M ->
  ccolcost [(2,2,c); (4,1,1); (1,1,1); (4,1,M)]%N
    <= ccolcost (Qfour (c+1) M) + 2 * 2.
Proof. intros HM. fcd_four_arith M. Qed.
Lemma qf_522_2 (c M : N) : 2 <= M ->
  ccolcost [(2,2,c); (4,1,1); (2,1,1); (4,1,M)]%N
    <= ccolcost (Qfour (c+2) M) + 2 * 3.
Proof. intros HM. fcd_four_arith M. Qed.
Lemma qf_522_3 (c M : N) : 2 <= M ->
  ccolcost [(2,2,c); (4,1,1); (3,1,1); (4,1,M)]%N
    <= ccolcost (Qfour (c+3) M) + 2 * 4.
Proof. intros HM. fcd_four_arith M. Qed.
Lemma qf_512_1 (K : N) : 2 <= K ->
  ccolcost [(2,2,3); (5,1,1); (1,1,1); (3,1,K)]%N
    <= ccolcost (Qclean K) + 2 * 2.
Proof. intros HK. fcd_clean_arith K. Qed.
Lemma qf_512_2 (K : N) : 2 <= K ->
  ccolcost [(2,2,2); (5,1,1); (2,1,1); (3,1,K)]%N
    <= ccolcost (Qclean K) + 2 * 3.
Proof. intros HK. fcd_clean_arith K. Qed.
Lemma qf_502 (K : N) : 3 <= K ->
  ccolcost [(2,2,1); (5,1,1); (3,1,K)]%N
    <= ccolcost (Qclean (K-1)) + 2 * 4.
Proof.
  intros HK.
  pose proof (div2_split (K-1)) as HD. unfold Qclean.
  destruct (N.odd (K-1)) eqn:EK; fcd_arith.
Qed.
Lemma qf_rot (K : N) : 2 <= K ->
  ccolcost [(5,1,1); (4,1,1); (3,1,K)]%N
    <= ccolcost (Qclean K) + 2 * 5.
Proof. intros HK. fcd_clean_arith K. Qed.
Lemma fcd_522_1 (sg : list seg) (c k M : N) (t : word)
      (f : N) (q : nat) (cw2 : word) (f2 : N) :
  k = 1%N ->
  lin_front_done 2
    (fr_four ((2,2,c+1)%N :: (4,2,1)%N :: (4,1,M)%N :: t) f)
    = Some (q, cw2, f2) ->
  cmeas sg ([(2,2,c); (4,1,1); (k,1,1); (4,1,M)]%N ++ t) f
    <= cmeas sg cw2 f2 + 2 * N.of_nat q.
Proof.
  intros Hk HD. subst k.
  destruct (front_done_four_inv 2 (c+1)%N M t f q cw2 f2 HD)
    as (_ & Hq & _ & _). subst q. change (N.of_nat 2) with 2.
  eapply (fcd_four sg [(2,2,c); (4,1,1); (1,1,1); (4,1,M)]%N
            (c+1)%N M t f 2 2%nat 2%nat cw2 f2); [reflexivity| |exact HD].
  exact (qf_522_1 c M).
Qed.
Lemma fcd_522_2 (sg : list seg) (c k M : N) (t : word)
      (f : N) (q : nat) (cw2 : word) (f2 : N) :
  k = 2%N ->
  lin_front_done 3
    (fr_four ((2,2,c+2)%N :: (4,2,1)%N :: (4,1,M)%N :: t) f)
    = Some (q, cw2, f2) ->
  cmeas sg ([(2,2,c); (4,1,1); (k,1,1); (4,1,M)]%N ++ t) f
    <= cmeas sg cw2 f2 + 2 * N.of_nat q.
Proof.
  intros Hk HD. subst k.
  destruct (front_done_four_inv 3 (c+2)%N M t f q cw2 f2 HD)
    as (_ & Hq & _ & _). subst q. change (N.of_nat 3) with 3.
  eapply (fcd_four sg [(2,2,c); (4,1,1); (2,1,1); (4,1,M)]%N
            (c+2)%N M t f 3 3%nat 3%nat cw2 f2); [reflexivity| |exact HD].
  exact (qf_522_2 c M).
Qed.
Lemma fcd_522_3 (sg : list seg) (c k M : N) (t : word)
      (f : N) (q : nat) (cw2 : word) (f2 : N) :
  k = 3%N ->
  lin_front_done 4
    (fr_four ((2,2,c+3)%N :: (4,2,1)%N :: (4,1,M)%N :: t) f)
    = Some (q, cw2, f2) ->
  cmeas sg ([(2,2,c); (4,1,1); (k,1,1); (4,1,M)]%N ++ t) f
    <= cmeas sg cw2 f2 + 2 * N.of_nat q.
Proof.
  intros Hk HD. subst k.
  destruct (front_done_four_inv 4 (c+3)%N M t f q cw2 f2 HD)
    as (_ & Hq & _ & _). subst q. change (N.of_nat 4) with 4.
  eapply (fcd_four sg [(2,2,c); (4,1,1); (3,1,1); (4,1,M)]%N
            (c+3)%N M t f 4 4%nat 4%nat cw2 f2); [reflexivity| |exact HD].
  exact (qf_522_3 c M).
Qed.
Lemma fcd_512_1 (sg : list seg) (c k K : N) (t : word)
      (f : N) (q : nat) (cw2 : word) (f2 : N) :
  k = 1%N -> (c + k = 4)%N ->
  lin_front_done 2
    (fr_clean ((2,2,4)%N :: (5,2,1)%N :: (3,1,K)%N :: t) f)
    = Some (q, cw2, f2) ->
  cmeas sg ([(2,2,c); (5,1,1); (k,1,1); (3,1,K)]%N ++ t) f
    <= cmeas sg cw2 f2 + 2 * N.of_nat q.
Proof.
  intros Hk Hc HD. assert (c = 3)%N by lia. subst k c.
  destruct (front_done_clean_inv 2 K t f q cw2 f2 HD)
    as (_ & Hq & _ & _). subst q. change (N.of_nat 2) with 2.
  eapply (fcd_clean sg [(2,2,3); (5,1,1); (1,1,1); (3,1,K)]%N
            K t f 2 2%nat 2%nat cw2 f2); [reflexivity| |exact HD].
  exact (qf_512_1 K).
Qed.
Lemma fcd_512_2 (sg : list seg) (c k K : N) (t : word)
      (f : N) (q : nat) (cw2 : word) (f2 : N) :
  k = 2%N -> (c + k = 4)%N ->
  lin_front_done 3
    (fr_clean ((2,2,4)%N :: (5,2,1)%N :: (3,1,K)%N :: t) f)
    = Some (q, cw2, f2) ->
  cmeas sg ([(2,2,c); (5,1,1); (k,1,1); (3,1,K)]%N ++ t) f
    <= cmeas sg cw2 f2 + 2 * N.of_nat q.
Proof.
  intros Hk Hc HD. assert (c = 2)%N by lia. subst k c.
  destruct (front_done_clean_inv 3 K t f q cw2 f2 HD)
    as (_ & Hq & _ & _). subst q. change (N.of_nat 3) with 3.
  eapply (fcd_clean sg [(2,2,2); (5,1,1); (2,1,1); (3,1,K)]%N
            K t f 3 3%nat 3%nat cw2 f2); [reflexivity| |exact HD].
  exact (qf_512_2 K).
Qed.
Lemma fcd_502 (sg : list seg) (c K : N) (t : word)
      (f : N) (q : nat) (cw2 : word) (f2 : N) :
  c = 1%N -> (3 <= K)%N ->
  lin_front_done 4
    (fr_clean ((2,2,4)%N :: (5,2,1)%N :: (3,1,K-1)%N :: t) f)
    = Some (q, cw2, f2) ->
  cmeas sg ([(2,2,c); (5,1,1); (3,1,K)]%N ++ t) f
    <= cmeas sg cw2 f2 + 2 * N.of_nat q.
Proof.
  intros Hc HK HD. subst c.
  destruct (front_done_clean_inv 4 (K-1)%N t f q cw2 f2 HD)
    as (_ & Hq & _ & _). subst q. change (N.of_nat 4) with 4.
  eapply (fcd_clean sg [(2,2,1); (5,1,1); (3,1,K)]%N
            (K-1)%N t f 4 4%nat 4%nat cw2 f2); [reflexivity| |exact HD].
  intros _. exact (qf_502 K HK).
Qed.
Lemma fcd_rot (sg : list seg) (K : N) (t : word)
      (f : N) (q : nat) (cw2 : word) (f2 : N) :
  (2 <= K)%N ->
  lin_front_done 5
    (fr_clean ((2,2,4)%N :: (5,2,1)%N :: (3,1,K)%N :: t) f)
    = Some (q, cw2, f2) ->
  cmeas sg ([(5,1,1); (4,1,1); (3,1,K)]%N ++ t) f
    <= cmeas sg cw2 f2 + 2 * N.of_nat q.
Proof.
  intros HK HD.
  destruct (front_done_clean_inv 5 K t f q cw2 f2 HD)
    as (_ & Hq & _ & _). subst q. change (N.of_nat 5) with 5.
  eapply (fcd_clean sg [(5,1,1); (4,1,1); (3,1,K)]%N
            K t f 5 5%nat 5%nat cw2 f2); [reflexivity| |exact HD].
  exact (qf_rot K).
Qed.
Ltac digsH H ::=
  repeat match type of H with
  | context [match ?x with N0 => _ | N.pos _ => _ end] =>
      is_var x; destruct x
  | context [match ?x with xI _ => _ | xO _ => _ | xH => _ end] =>
      is_var x; destruct x
  end.
Ltac front_prep H ::=
  repeat match type of H with
  | context [if ?b then _ else _] =>
      let E := fresh "EB" in destruct b eqn:E; try discriminate
  end;
  repeat match goal with
  | E : (_ && _)%bool = true |- _ =>
      let E2 := fresh "EB" in
      apply andb_prop in E; destruct E as [E E2]
  end;
  repeat match goal with
  | E : (_ <=? _)%N = true |- _ => apply N.leb_le in E
  | E : (_ =? _)%N = true |- _ => apply N.eqb_eq in E
  end;
  try (exfalso; lia).
Ltac close_fcd HC :=
  first
    [ eapply fcd_rot; [lia|exact HC]
    | eapply fcd_502; [lia|lia|exact HC]
    | match goal with
      | Hk : _ = 1%N |- _ => eapply fcd_512_1; [exact Hk|lia|exact HC]
      end
    | match goal with
      | Hk : _ = 2%N |- _ => eapply fcd_512_2; [exact Hk|lia|exact HC]
      end
    | match goal with
      | Hk : _ = 1%N |- _ => eapply fcd_522_1; [exact Hk|exact HC]
      end
    | match goal with
      | Hk : _ = 2%N |- _ => eapply fcd_522_2; [exact Hk|exact HC]
      end
    | match goal with
      | Hk : _ = 3%N |- _ => eapply fcd_522_3; [exact Hk|exact HC]
      end ].
Theorem front_close_dom : FrontCloseDom.
Proof.
  intros sg cw f q cw2 f2 HC.
  destruct (lin_front_close_case_of
    cw f q cw2 f2 HC).
  all: first
    [ eapply fcd_rot; eassumption
    | eapply fcd_502; eassumption
    | eapply fcd_512_1; eassumption
    | eapply fcd_512_2; eassumption
    | eapply fcd_522_1; eassumption
    | eapply fcd_522_2; eassumption
    | eapply fcd_522_3; eassumption ].
Qed.
Definition cd (sg : list seg) (cw : word) (f : N) (n : ncost)
              (r : lround_result) : Prop :=
  match r with
  | (sg2, _, cw2, f2, _, _, n2, _, _) =>
      cmeas sg cw f + 2 * fst n <= cmeas sg2 cw2 f2 + 2 * fst n2
  end.
Lemma cd_mono (sg : list seg) (cw : word) (f : N) (n : ncost)
      (sg' : list seg) (cw' : word) (f' : N) (n' : ncost)
      (r : lround_result) :
  cmeas sg cw f + 2 * fst n <= cmeas sg' cw' f' + 2 * fst n' ->
  cd sg' cw' f' n' r -> cd sg cw f n r.
Proof.
  unfold cd.
  destruct r as [[[[[[[[a b] c] d] e] g] i] j] k]. lia.
Qed.
Lemma cd_refl (sg : list seg) (cw : word) (f : N) (n n' : ncost)
      (ps : atab) (h jc m : nat) (stop : lrstop) :
  fst n <= fst n' ->
  cd sg cw f n (sg, ps, cw, f, h, jc, n', m, stop).
Proof. unfold cd. lia. Qed.
Theorem cond_round_dom (CA : CondArms) (fu : nat) :
  forall (sg : list seg) (ps : atab) (cw : word) (f : N)
         (h jc : nat) (n : ncost) (m : nat),
    settled sg cw ->
    cd sg cw f n (lin_run_round fu sg ps cw f h jc n m).
Proof.
  destruct CA as [HFL HTF HMI].
  induction fu as [|fu IH]; intros sg ps cw f h jc n m HSet;
    destruct HSet as [HG HGuard].
  - cbn [lin_run_round]. apply cd_refl. lia.
  - cbn [lin_run_round].
    destruct (lin_front_close cw f) as [[[q cw2] f2]|] eqn:EFC.
    { destruct (relocate_all sg ps cw2) as [ps2|] eqn:ER.
      - destruct (front_late cw);
          unfold cd; cbn [fst];
          unfold nc_ebump, nc_bump; cbn [fst];
          pose proof (front_close_dom sg cw f q cw2 f2 EFC) as HD; lia.
      - apply cd_refl. lia. }
    set (front := if lin_front_possible cw
                  then first_rule front_rules cw f else None).
    assert (Hfr : front = front_gate cw f) by reflexivity.
    destruct (lin_gen_action_at front sg ps cw f h)
      as [[[[[[[t cwG] sgG] psG] fG] fsG]|]|] eqn:EG.
    { pose proof (HFL front sg ps cw f h t cwG sgG psG fG fsG HG EG) as HD.
      destruct (lin_gen_action_at_stable
                  front sg ps cw f h t cwG sgG psG fG fsG HG EG)
        as (_ & HGg & HGuardg & _).
      apply (cd_mono sg cw f n sgG cwG fG (nc_fbump n t));
        [unfold nc_fbump; cbn [fst]; lia
        |apply IH; exact (conj HGg HGuardg)]. }
    { destruct (lin_halt_probe front sg cw f h).
      - destruct (fst (lin_halt_confirm sg cw f)).
        + apply cd_refl. unfold nc_bump; cbn [fst]. lia.
        + apply cd_refl. lia.
      - apply cd_refl. lia. }
    destruct (if lin_tick_front_due cw
              then lin_tick_front_at front sg ps cw f h
              else None) as [[[[[[q cwT] sgT] psT] fT] fsT]|] eqn:ET.
    { assert (HT : lin_tick_front_at front sg ps cw f h
                   = Some (q, cwT, sgT, psT, fT, fsT)).
      { destruct (lin_tick_front_due cw); [exact ET|discriminate]. }
      pose proof (HTF front sg ps cw f h q cwT sgT psT fT fsT HG HT) as HD.
      destruct (lin_tick_front_at_stable
                  front sg ps cw f h q cwT sgT psT fT fsT HG HT)
        as (_ & HGt & HGuardt & _).
      apply (cd_mono sg cw f n sgT cwT fT (nc_fbump n q));
        [unfold nc_fbump; cbn [fst]; lia
        |apply IH; exact (conj HGt HGuardt)]. }
    destruct (lin_micro_action_guard front cw h) eqn:EMicro.
    2:{ apply cd_refl. lia. }
    destruct (step_after_front_with_guard false
                (lin_normalize_at sg)
                (fun pre sfx _ => lin_normalize_join sg pre sfx)
                front cw f h) as [[wS fS| |] iS] eqn:ES.
    + destruct (lin_splice_arm_guard front cw iS) eqn:EGD;
        [|apply cd_refl; lia].
      destruct (relocate_all sg ps wS) as [psS|] eqn:ER2;
        [|apply cd_refl; lia].
      pose proof (HMI front sg cw f h wS fS iS HG HGuard Hfr ES) as HD.
      destruct (lin_round_closing cw f) eqn:ECL.
      * unfold cd. cbn [fst]. unfold nc_bump; cbn [fst]. lia.
      * destruct (lin_step_post front sg psS wS iS)
          as [[[[sgP psP] cwP] iP]|] eqn:EP; [|apply cd_refl; lia].
        destruct (splice_stable sg cw f h wS fS iS HG HGuard ES)
          as (_ & HGs).
        pose proof (post_dom front sg psS wS iS fS sgP psP cwP iP HGs EP)
          as HD2.
        destruct (lin_step_post_settled
                    front sg psS wS iS sgP psP cwP iP HGs EP)
          as (_ & HGuardP & HGp).
        apply (cd_mono sg cw f n sgP cwP fS
                 (nc_qbump n 1 czero));
          [unfold nc_qbump; cbn [fst]; lia
          |apply IH; exact (conj HGp HGuardP)].
    + destruct (fst (lin_halt_confirm sg cw f)).
      * apply cd_refl. unfold nc_bump; cbn [fst]. lia.
      * apply cd_refl. lia.
    + apply cd_refl. lia.
Qed.
Definition cdc (sg : list seg) (cw : word) (f : N) (n : ncost)
    (r : list seg * atab * word * N * nat * ncost * nat * lrstop)
  : Prop :=
  match r with
  | (sg2, _, cw2, f2, _, n2, _, _) =>
      cmeas sg cw f + 2 * fst n <= cmeas sg2 cw2 f2 + 2 * fst n2
  end.
Theorem cond_chunked_dom (CA : CondArms) (chunks : nat) :
  forall (sg : list seg) (ps : atab) (cw : word) (f : N)
         (h jc : nat) (n : ncost) (m : nat),
    settled sg cw ->
    cdc sg cw f n (lin_run_round_chunked chunks sg ps cw f h jc n m).
Proof.
  induction chunks as [|ch IH]; intros sg ps cw f h jc n m HSet.
  - cbn [lin_run_round_chunked]. unfold cdc. lia.
  - cbn [lin_run_round_chunked].
    pose proof (cond_round_dom CA LROUND_FUEL sg ps cw f h jc n m HSet) as HR.
    pose proof (run_round_out LROUND_FUEL sg ps cw f h jc n m) as HO.
    destruct (lin_run_round LROUND_FUEL sg ps cw f h jc n m)
      as [[[[[[[[sg2 ps2] cw2] f2] h2] j2] n2] m2] stop] eqn:ERR.
    unfold cd in HR.
    specialize (HO sg2 ps2 cw2 f2 h2 j2 n2 m2 stop HSet eq_refl).
    destruct stop; try (unfold cdc; exact HR).
    cbn [round_out] in HO.
    pose proof (IH sg2 ps2 cw2 f2 h2 j2 n2 m2 (proj2 HO)) as HC.
    destruct (lin_run_round_chunked ch sg2 ps2 cw2 f2 h2 j2 n2 m2)
      as [[[[[[[sg3 ps3] cw3] f3] j3] n3] m3] stop3].
    unfold cdc in HC |- *. lia.
Qed.
Lemma lr_accept_exact (closed : bool)
      (sg : list seg) (ps : atab) (cw : word) (f : N)
      (jc : nat) (k : ncost) (m : nat) (r : lpnext) :
  stable_guard sg cw ->
  lr_accept closed sg ps cw f jc k m = Some r ->
  exists (s' : lpstate), r = LPNext k m s' /\ lpm s' = cmeas sg cw f.
Proof.
  intros HS.
  unfold lr_accept. destruct (Nat.eqb m O); [discriminate|].
  destruct (closed || Nat.eqb m LROUND_FUEL)%bool.
  - destruct (lin_repack_when_needed sg ps cw) as [[[sg2 ps2] cw2]|] eqn:ERP;
      [|discriminate].
    pose proof (repack_flat sg ps cw sg2 ps2 cw2 HS ERP) as HF.
    destruct (negb (lin_ok sg2 cw2)); [discriminate|].
    destruct sg2 as [|s0 t0] eqn:ESG.
    + intros HE. injection HE as HE. subst r.
      eexists. split; [reflexivity|].
      cbn [lpm]. unfold cmeas. rewrite <- HF.
      rewrite lin_flat_nil. reflexivity.
    + intros HE. injection HE as HE. subst r.
      eexists. split; [reflexivity|].
      cbn [lpm]. unfold cmeas. rewrite HF. reflexivity.
  - destruct (negb (lin_post_full sg cw)); [discriminate|].
    intros HE. injection HE as HE. subst r.
    eexists. split; [reflexivity|]. cbn [lpm]. reflexivity.
Qed.
Lemma lr_continue_dom (sg : list seg) (cw : word) (f : N)
      (jc : nat) (k : ncost) (m : nat) (r : lpnext) :
  lr_continue_flat sg cw f jc k m = Some r ->
  dom_of (lin_flat sg cw) f k r.
Proof.
  unfold lr_continue_flat. destruct (Nat.eqb m O); [discriminate|].
  destruct (negb (lin_post_full sg cw)); [discriminate|].
  intros HE. injection HE as HE. subst r. apply lp_fbrr_dom.
Qed.
Lemma dom_of_next (w : word) (f : N) (k k' : ncost) (m' : nat)
      (s' : lpstate) :
  dom_of w f k (LPNext k' m' s') -> gmeas w f + 2 * fst k <= lpm s' + 2 * fst k'.
Proof.
  cbn [dom_of]. rewrite lpm_phi_st. unfold phi. lia.
Qed.
Theorem linstep_dom (CA : CondArms)
        (s : lpstate) (k : ncost) (m : nat) (s' : lpstate) :
  lp_stable s ->
  linstep s = LPSNext k m s' -> lpm s <= lpm s' + 2 * fst k.
Proof.
  assert (FB : forall (w : word) (f : N) (h : nat)
                      (k0 : ncost) (m0 : nat) (s0 : lpstate),
                 lps_of_lpnext (lp_fallback_round w f h)
                   = LPSNext k0 m0 s0 ->
                 gmeas w f <= lpm s0 + 2 * fst k0).
  { intros w f h k0 m0 s0 HE.
    pose proof (lp_fbrr_dom FLAT_ROUND_FUEL None w f h nc0 O) as HD.
    unfold lp_fallback_round in HE.
    destruct (lp_fallback_round_run FLAT_ROUND_FUEL None w f h nc0 O)
      as [k1 m1 s1|k1 m1 w1 f1|k1 m1 w1 f1]; cbn [lps_of_lpnext] in HE;
      try discriminate.
    injection HE as HE1 HE2 HE3. subst k1 m1 s1.
    pose proof (dom_of_next w f nc0 k0 m0 s0 HD) as HH.
    unfold nc0 in HH; cbn [fst] in HH. lia. }
  intros HStable.
  destruct s as [w f h|sg ps cw f h j]; cbn [linstep lpm].
  - destruct (lin_cond w h) as [[[cw sg] h0]|] eqn:EC; [|exact (FB w f h k m s')].
    destruct (locate_all sg cw) as [ps|] eqn:EL; [|exact (FB w f h k m s')].
    destruct (T_cond_flat_ok w h cw sg h0 EC) as [HFL _].
    destruct (T_cond_stable_holds w h cw sg h0 EC) as [_ HG0].
    destruct (T_cond_holds w h cw sg h0 EC) as (_ & _ & HGuard0 & _ & _).
    pose proof (cond_chunked_dom CA LROUND_CHUNKS sg ps cw f h0 O nc0 O
                  (conj HG0 HGuard0)) as HR.
    pose proof (run_chunked_out LROUND_CHUNKS sg ps cw f h0 O nc0 O)
      as HO.
    destruct (lin_run_round_chunked LROUND_CHUNKS sg ps cw f h0 O nc0 O)
      as [[[[[[[sg2 ps2] cw2] f2] j2] k2] m2] stop] eqn:ERR.
    specialize (HO sg2 ps2 cw2 f2 j2 k2 m2 stop (conj HG0 HGuard0) eq_refl).
    unfold cdc in HR. unfold nc0 in HR; cbn [fst] in HR.
    assert (HE : cmeas sg cw f = gmeas w f)
      by (unfold cmeas; rewrite HFL; reflexivity).
    rewrite HE in HR.
    destruct stop.
    +
      destruct (lr_continue_flat sg2 cw2 f2 j2 k2 m2) as [r|] eqn:ECF;
        [|exact (FB w f h k m s')].
      pose proof (lr_continue_dom sg2 cw2 f2 j2 k2 m2 r ECF) as HDF.
      destruct r as [k3 m3 s3|k3 m3 w3 f3|k3 m3 w3 f3];
        cbn [lps_of_lpnext]; intros HX; try discriminate.
      injection HX as HX1 HX2 HX3. subst k3 m3 s3.
      pose proof (dom_of_next (lin_flat sg2 cw2) f2 k2 k m s' HDF) as HH.
      unfold cmeas in HR. lia.
    +
      destruct (lr_continue_flat sg2 cw2 f2 j2 k2 m2) as [r|] eqn:ECF;
        [|exact (FB w f h k m s')].
      pose proof (lr_continue_dom sg2 cw2 f2 j2 k2 m2 r ECF) as HDF.
      destruct r as [k3 m3 s3|k3 m3 w3 f3|k3 m3 w3 f3];
        cbn [lps_of_lpnext]; intros HX; try discriminate.
      injection HX as HX1 HX2 HX3. subst k3 m3 s3.
      pose proof (dom_of_next (lin_flat sg2 cw2) f2 k2 k m s' HDF) as HH.
      unfold cmeas in HR. lia.
    +
      cbn [round_out] in HO.
      destruct (lr_accept true sg2 ps2 cw2 f2 j2 k2 m2) as [r|] eqn:EA;
        [|exact (FB w f h k m s')].
      destruct (lr_accept_exact true sg2 ps2 cw2 f2 j2 k2 m2 r
                  (proj2 HO) EA)
        as [sA [HrA HmA]]. subst r.
      cbn [lps_of_lpnext]. intros HX.
      injection HX as HX1 HX2 HX3. subst k2 m2 sA. lia.
    +   intros HX; discriminate.
  - cbn [lp_stable] in HStable.
    pose proof (cond_chunked_dom CA LROUND_CHUNKS sg ps cw f h
                  (hmapw sg cw O O j) nc0 O HStable) as HR.
    pose proof (run_chunked_out LROUND_CHUNKS sg ps cw f h
                  (hmapw sg cw O O j) nc0 O) as HO.
    destruct (lin_run_round_chunked LROUND_CHUNKS sg ps cw f h
                (hmapw sg cw O O j) nc0 O)
      as [[[[[[[sg2 ps2] cw2] f2] j2] k2] m2] stop] eqn:ERR.
    specialize (HO sg2 ps2 cw2 f2 j2 k2 m2 stop HStable eq_refl).
    unfold cdc in HR. unfold nc0 in HR; cbn [fst] in HR.
    destruct stop.
    + destruct (lr_continue_flat sg2 cw2 f2 j2 k2 m2) as [r|] eqn:ECF;
        [|exact (FB (lin_flat sg cw) f (hint_of j) k m s')].
      pose proof (lr_continue_dom sg2 cw2 f2 j2 k2 m2 r ECF) as HDF.
      destruct r as [k3 m3 s3|k3 m3 w3 f3|k3 m3 w3 f3];
        cbn [lps_of_lpnext]; intros HX; try discriminate.
      injection HX as HX1 HX2 HX3. subst k3 m3 s3.
      pose proof (dom_of_next (lin_flat sg2 cw2) f2 k2 k m s' HDF) as HH.
      unfold cmeas in HR |- *. lia.
    + destruct (lr_continue_flat sg2 cw2 f2 j2 k2 m2) as [r|] eqn:ECF;
        [|exact (FB (lin_flat sg cw) f (hint_of j) k m s')].
      pose proof (lr_continue_dom sg2 cw2 f2 j2 k2 m2 r ECF) as HDF.
      destruct r as [k3 m3 s3|k3 m3 w3 f3|k3 m3 w3 f3];
        cbn [lps_of_lpnext]; intros HX; try discriminate.
      injection HX as HX1 HX2 HX3. subst k3 m3 s3.
      pose proof (dom_of_next (lin_flat sg2 cw2) f2 k2 k m s' HDF) as HH.
      unfold cmeas in HR |- *. lia.
    + cbn [round_out] in HO.
      destruct (lr_accept true sg2 ps2 cw2 f2 j2 k2 m2) as [r|] eqn:EA;
        [|exact (FB (lin_flat sg cw) f (hint_of j) k m s')].
      destruct (lr_accept_exact true sg2 ps2 cw2 f2 j2 k2 m2 r
                  (proj2 HO) EA)
        as [sA [HrA HmA]]. subst r.
      cbn [lps_of_lpnext]. intros HX.
      injection HX as HX1 HX2 HX3. subst k2 m2 sA. lia.
    + intros HX; discriminate.
Qed.
Lemma dom_of_guard (w : word) (f : N) (k k' : ncost) (m' : nat)
      (wT : word) (fT : N) :
  dom_of w f k (LPGuard k' m' wT fT) ->
  gmeas w f + 2 * fst k <= lmeas wT fT + 2 * fst k'.
Proof. cbn [dom_of]. unfold phi, gmeas, lmeas. lia. Qed.
Theorem linstep_guard_dom (CA : CondArms)
        (s : lpstate) (k : ncost) (m len : nat) (f lm : N) :
  lp_stable s ->
  linstep s = LPSGuard k m len f lm -> lpm s <= lm + 2 * fst k.
Proof.
  assert (FB : forall (w : word) (f0 : N) (h : nat)
                      (k0 : ncost) (m0 len0 : nat) (f0' lm0 : N),
                 lps_of_lpnext (lp_fallback_round w f0 h)
                   = LPSGuard k0 m0 len0 f0' lm0 ->
                 gmeas w f0 <= lm0 + 2 * fst k0).
  { intros w f0 h k0 m0 len0 f0' lm0 HE.
    pose proof (lp_fbrr_dom FLAT_ROUND_FUEL None w f0 h nc0 O) as HD.
    unfold lp_fallback_round in HE.
    destruct (lp_fallback_round_run FLAT_ROUND_FUEL None w f0 h nc0 O)
      as [k1 m1 s1|k1 m1 w1 f1|k1 m1 w1 f1]; cbn [lps_of_lpnext] in HE;
      try discriminate.
    injection HE as HE1 HE2 HE3 HE4. subst k1 m1 len0 lm0.
    pose proof (dom_of_guard w f0 nc0 k0 m0 w1 f1 HD) as HH.
    unfold nc0 in HH; cbn [fst] in HH. lia. }
  intros HStable.
  destruct s as [w f0 h|sg ps cw f0 h j]; cbn [linstep lpm].
  - destruct (lin_cond w h) as [[[cw sg] h0]|] eqn:EC;
      [|exact (FB w f0 h k m len f lm)].
    destruct (locate_all sg cw) as [ps|] eqn:EL;
      [|exact (FB w f0 h k m len f lm)].
    destruct (T_cond_flat_ok w h cw sg h0 EC) as [HFL _].
    destruct (T_cond_stable_holds w h cw sg h0 EC) as [_ HG0].
    destruct (T_cond_holds w h cw sg h0 EC) as (_ & _ & HGuard0 & _ & _).
    pose proof (cond_chunked_dom CA LROUND_CHUNKS sg ps cw f0 h0 O nc0 O
                  (conj HG0 HGuard0)) as HR.
    pose proof (run_chunked_out LROUND_CHUNKS sg ps cw f0 h0 O nc0 O)
      as HO.
    destruct (lin_run_round_chunked LROUND_CHUNKS sg ps cw f0 h0 O nc0 O)
      as [[[[[[[sg2 ps2] cw2] f2] j2] k2] m2] stop] eqn:ERR.
    specialize (HO sg2 ps2 cw2 f2 j2 k2 m2 stop (conj HG0 HGuard0) eq_refl).
    unfold cdc in HR. unfold nc0 in HR; cbn [fst] in HR.
    assert (HE : cmeas sg cw f0 = gmeas w f0)
      by (unfold cmeas; rewrite HFL; reflexivity).
    rewrite HE in HR.
    destruct stop.
    +
      destruct (lr_continue_flat sg2 cw2 f2 j2 k2 m2) as [r|] eqn:ECF;
        [|exact (FB w f0 h k m len f lm)].
      pose proof (lr_continue_dom sg2 cw2 f2 j2 k2 m2 r ECF) as HDF.
      destruct r as [k3 m3 s3|k3 m3 w3 f3|k3 m3 w3 f3];
        cbn [lps_of_lpnext]; intros HX; try discriminate.
      injection HX as HX1 HX2 HX3 HX4. subst k3 m3 len lm.
      pose proof (dom_of_guard (lin_flat sg2 cw2) f2 k2 k m w3 f3 HDF) as HH.
      unfold cmeas in HR. lia.
    +
      destruct (lr_continue_flat sg2 cw2 f2 j2 k2 m2) as [r|] eqn:ECF;
        [|exact (FB w f0 h k m len f lm)].
      pose proof (lr_continue_dom sg2 cw2 f2 j2 k2 m2 r ECF) as HDF.
      destruct r as [k3 m3 s3|k3 m3 w3 f3|k3 m3 w3 f3];
        cbn [lps_of_lpnext]; intros HX; try discriminate.
      injection HX as HX1 HX2 HX3 HX4. subst k3 m3 len lm.
      pose proof (dom_of_guard (lin_flat sg2 cw2) f2 k2 k m w3 f3 HDF) as HH.
      unfold cmeas in HR. lia.
    +
      cbn [round_out] in HO.
      destruct (lr_accept true sg2 ps2 cw2 f2 j2 k2 m2) as [r|] eqn:EA;
        [|exact (FB w f0 h k m len f lm)].
      destruct (lr_accept_exact true sg2 ps2 cw2 f2 j2 k2 m2 r
                  (proj2 HO) EA)
        as [sA [HrA HmA]]. subst r.
      cbn [lps_of_lpnext]. intros HX. discriminate.
    +
      intros HX. injection HX as HX1 HX2 HX3 HX4. subst k2 m2 len lm.
      unfold cmeas, gmeas, lmeas in HR |- *. lia.
  - cbn [lp_stable] in HStable.
    pose proof (cond_chunked_dom CA LROUND_CHUNKS sg ps cw f0 h
                  (hmapw sg cw O O j) nc0 O HStable) as HR.
    pose proof (run_chunked_out LROUND_CHUNKS sg ps cw f0 h
                  (hmapw sg cw O O j) nc0 O) as HO.
    destruct (lin_run_round_chunked LROUND_CHUNKS sg ps cw f0 h
                (hmapw sg cw O O j) nc0 O)
      as [[[[[[[sg2 ps2] cw2] f2] j2] k2] m2] stop] eqn:ERR.
    specialize (HO sg2 ps2 cw2 f2 j2 k2 m2 stop HStable eq_refl).
    unfold cdc in HR. unfold nc0 in HR; cbn [fst] in HR.
    destruct stop.
    + destruct (lr_continue_flat sg2 cw2 f2 j2 k2 m2) as [r|] eqn:ECF;
        [|exact (FB (lin_flat sg cw) f0 (hint_of j) k m len f lm)].
      pose proof (lr_continue_dom sg2 cw2 f2 j2 k2 m2 r ECF) as HDF.
      destruct r as [k3 m3 s3|k3 m3 w3 f3|k3 m3 w3 f3];
        cbn [lps_of_lpnext]; intros HX; try discriminate.
      injection HX as HX1 HX2 HX3 HX4. subst k3 m3 len lm.
      pose proof (dom_of_guard (lin_flat sg2 cw2) f2 k2 k m w3 f3 HDF) as HH.
      unfold cmeas in HR |- *. lia.
    + destruct (lr_continue_flat sg2 cw2 f2 j2 k2 m2) as [r|] eqn:ECF;
        [|exact (FB (lin_flat sg cw) f0 (hint_of j) k m len f lm)].
      pose proof (lr_continue_dom sg2 cw2 f2 j2 k2 m2 r ECF) as HDF.
      destruct r as [k3 m3 s3|k3 m3 w3 f3|k3 m3 w3 f3];
        cbn [lps_of_lpnext]; intros HX; try discriminate.
      injection HX as HX1 HX2 HX3 HX4. subst k3 m3 len lm.
      pose proof (dom_of_guard (lin_flat sg2 cw2) f2 k2 k m w3 f3 HDF) as HH.
      unfold cmeas in HR |- *. lia.
    + cbn [round_out] in HO.
      destruct (lr_accept true sg2 ps2 cw2 f2 j2 k2 m2) as [r|] eqn:EA;
        [|exact (FB (lin_flat sg cw) f0 (hint_of j) k m len f lm)].
      destruct (lr_accept_exact true sg2 ps2 cw2 f2 j2 k2 m2 r
                  (proj2 HO) EA)
        as [sA [HrA HmA]]. subst r.
      cbn [lps_of_lpnext]. intros HX. discriminate.
    + intros HX. injection HX as HX1 HX2 HX3 HX4. subst k2 m2 len lm.
      unfold cmeas, gmeas, lmeas in HR |- *. lia.
Qed.
Definition sdom (s : lpstate) (n : ncost) (r : lsummary) : Prop :=
  match r with
  | LSGuard _ _ n' lm => lpm s + 2 * fst n <= lm + 2 * fst n'
  | _ => True
  end.
Definition ordom (a b : lpsacc) : Prop :=
  (forall r, a = LPSFinished r -> b = LPSFinished r)
  /\ match a with
     | LPSFinished _ => True
     | LPSRunning s n =>
         match b with
         | LPSRunning s2 n2 => lpm s + 2 * fst n <= lpm s2 + 2 * fst n2
         | LPSFinished r => sdom s n r
         end
     end.
Definition sacc_stable (a : lpsacc) : Prop :=
  match a with
  | LPSRunning s _ => lp_stable s
  | LPSFinished _ => True
  end.
Lemma ordom_once (CA : CondArms) (a : lpsacc) :
  sacc_stable a -> ordom a (lps_once a).
Proof.
  destruct a as [s n|r]; [|intros _; split; [intros r0 H; exact H|exact I]].
  cbn [sacc_stable]. intros HS.
  cbn [lps_once]. split; [intros r0 H; discriminate|].
  destruct (linstep s) as [k m s2|k m len f lm|k m len f lm] eqn:EL.
  - pose proof (linstep_dom CA s k m s2 HS EL) as HD.
    unfold nc_add; cbn [fst]. lia.
  - cbn [sdom].
    pose proof (linstep_guard_dom CA s k m len f lm HS EL) as HD.
    unfold nc_add; cbn [fst]. lia.
  - exact I.
Qed.
Local Open Scope N_scope.
Local Open Scope N_scope.
Local Open Scope bool_scope.
