Definition ladderA (p : N) : N :=
  match phase_form p with
  | (o,_,_) :: _ => o
  | [] => 0%N
  end.
Lemma sdecode_is_sdec (w : word) (f : N) :
  sdecode w f = sdec w f.
Proof. reflexivity. Qed.
Lemma bsum_master (J : N) (pre : word) :
  bsum ((2,2,J)%N :: pre) = (10 * J + bsum pre)%N.
Proof. cbn [bsum bpc]. lia. Qed.
Definition delivery_tripc (K : N) (s : word) (f : N)
                          (s' : word) (f' : N) : Prop :=
  exists c p q,
    FTripC c K (sdec s f) p q
    /\ wconf [] 0 ((1,S p)::q) = wconf [] 0 (sdec s' f').
Inductive deliveriesc : list N -> word -> N -> word -> N -> Prop :=
  | deliveriesc_O : forall s f s' f',
      sdec s f = sdec s' f' -> deliveriesc [] s f s' f'
  | deliveriesc_S : forall K Ks s f s1 f1 s2 f2,
      delivery_tripc K s f s1 f1 -> deliveriesc Ks s1 f1 s2 f2 ->
      deliveriesc (K :: Ks) s f s2 f2.
Fixpoint nsumN (Ks : list N) : N :=
  match Ks with [] => 0%N | k :: r => (k + nsumN r)%N end.
Lemma delivery_master_creach (K c_0 : N) (p' s s' : word) (f f' : N) :
  zpre p' -> (1 <= c_0)%N ->
  delivery_tripc K s f s' f' ->
  creach (cx (bsum ((2,2,c_0)%N :: p') + (K + 6))%N)
    (wconf [] 0 (sdecode (((2,2,c_0)%N :: p') ++ s) f))
    (wconf [] 0 (sdecode (((2,2,c_0+1)%N :: p') ++ s') f')).
Proof.
  intros HP HC0 (c & pp & q & HF & EQ).
  pose proof (leaf_trip_returnc c_0 p' s s' f f' c pp K q
                HP HC0 HF EQ) as HR.
  assert (ET : sdecode (((2,2,c_0+1)%N :: p') ++ s') f'
             = sdecode ((2,2,1)%N :: ((2,2,c_0)%N :: p') ++ s') f').
  { cbn [app]. rewrite !sdecode_is_sdec. apply sdec_incr. }
  rewrite ET. exact HR.
Qed.
Lemma FlightC_sdec_prefix_eq (q s s' : word) (f f' : N) :
  sdec s f = sdec s' f' ->
  sdec (q ++ s) f = sdec (q ++ s') f'.
Proof. intros E. rewrite !sdec_app, E. reflexivity. Qed.
Lemma deliveriesc_master_creach (Ks : list N) :
  forall (c_0 : N) (p' s s' : word) (f f' : N),
  zpre p' -> (1 <= c_0)%N ->
  deliveriesc Ks s f s' f' ->
  creach (cx (N.of_nat (length Ks) * bsum ((2,2,c_0)%N :: p')
              + 10 * tri (length Ks)
              + nsumN Ks + 6 * N.of_nat (length Ks))%N)
    (wconf [] 0 (sdecode (((2,2,c_0)%N :: p') ++ s) f))
    (wconf [] 0 (sdecode
       (((2,2, c_0 + N.of_nat (length Ks))%N :: p') ++ s') f')).
Proof.
  induction Ks as [|K Ks IH];
    intros c_0 p' s s' f f' HP HC0 HD.
  - inversion HD as [s0 f0 s1 f1 E| ]; subst.
    cbn [length nsumN tri].
    change (N.of_nat 0) with 0%N. rewrite !N.add_0_r.
    replace (0 * bsum ((2,2,c_0)%N :: p') + 10 * 0 + 0 + 6 * 0)%N
      with 0%N by lia.
    change (cx 0%N) with czero.
    assert (EE : sdecode (((2,2,c_0)%N :: p') ++ s) f
               = sdecode (((2,2,c_0)%N :: p') ++ s') f').
    { rewrite !sdecode_is_sdec.
      exact (FlightC_sdec_prefix_eq ((2,2,c_0)%N :: p') s s' f f' E). }
    rewrite EE. apply creach_refl.
  - inversion HD as [|K0 Ks0 s0 f0 s1 f1 s2 f2 HT HR]; subst.
    pose proof (delivery_master_creach K c_0 p' s s1 f f1 HP HC0 HT) as H1.
    pose proof (IH (c_0+1)%N p' s1 s' f1 f' HP ltac:(lia) HR) as H2.
    pose proof (creach_cx_trans _ _ _ _ _ H1 H2) as H3.
    replace (c_0 + 1 + N.of_nat (length Ks))%N
      with (c_0 + N.of_nat (length (K :: Ks)))%N in H3
      by (cbn [length]; rewrite Nat2N.inj_succ; lia).
    assert (EB : bsum ((2,2,c_0+1)%N :: p')
               = (bsum ((2,2,c_0)%N :: p') + 10)%N)
      by (rewrite !bsum_master; lia).
    eapply creach_widen'; [| |exact H3];
      cbn [length tri nsumN cx fst snd];
      rewrite Nat2N.inj_succ, EB, N.mul_succ_l, N.mul_add_distr_l; lia.
Qed.
Lemma delivery_tripc_sdec_left (K : N) (s0 s s' : word) (f0 f f' : N) :
  sdec s0 f0 = sdec s f ->
  delivery_tripc K s f s' f' -> delivery_tripc K s0 f0 s' f'.
Proof. intros E (c & p & q & HF & EQ). exists c, p, q. rewrite E. auto. Qed.
Lemma delivery_tripc_sdec_right (K : N) (s s' s0 : word) (f f' f0 : N) :
  sdec s' f' = sdec s0 f0 ->
  delivery_tripc K s f s' f' -> delivery_tripc K s f s0 f0.
Proof.
  intros E (c & p & q & HF & EQ). exists c, p, q.
  split; [exact HF|now rewrite <- E].
Qed.
Lemma delivery_tripc_cols (ini s s' : word) (K f f' : N) :
  forallb (fun g => is_col g && negb (is_cmf g)
                    && (3 <=? gO g)%N) ini = true ->
  delivery_tripc K s f s' f' ->
  delivery_tripc (K + wcolcost ini)%N (ini ++ s) f (ini ++ s') f'.
Proof.
  intros HB (c & p & q & HF & EQ).
  destruct (DebrisLeafC_ren_liftc ini s s' f f' c p K q HB HF EQ)
    as (c2 & p2 & q2 & HF2 & EQ2).
  exists c2, p2, q2. split; assumption.
Qed.
Fixpoint shiftK (ini : word) (Ks : list N) : list N :=
  match Ks with
  | [] => []
  | k :: r => (k + wcolcost ini)%N :: shiftK ini r
  end.
Lemma shiftK_length (ini : word) (Ks : list N) :
  length (shiftK ini Ks) = length Ks.
Proof. induction Ks as [|k r IH]; cbn [shiftK length]; auto. Qed.
Lemma nsumN_shiftK (ini : word) (Ks : list N) :
  nsumN (shiftK ini Ks)
  = (nsumN Ks + N.of_nat (length Ks) * wcolcost ini)%N.
Proof.
  induction Ks as [|k r IH]; cbn [shiftK nsumN length]; [lia|].
  rewrite IH, Nat2N.inj_succ, N.mul_succ_l. lia.
Qed.
Lemma deliveriesc_cols (ini : word) (Ks : list N)
      (s s' : word) (f f' : N) :
  forallb (fun g => is_col g && negb (is_cmf g)
                    && (3 <=? gO g)%N) ini = true ->
  deliveriesc Ks s f s' f' ->
  deliveriesc (shiftK ini Ks) (ini ++ s) f (ini ++ s') f'.
Proof.
  intros HB H. induction H as [s f s' f' E|K Ks s f s1 f1 s2 f2 HT HR IH].
  - apply deliveriesc_O. rewrite !sdec_app, E. reflexivity.
  - cbn [shiftK].
    exact (deliveriesc_S _ _ _ _ _ _ _ _
             (delivery_tripc_cols ini s s1 K f f1 HB HT) IH).
Qed.
Lemma deliveriesc_app (a b : list N) (s s1 s2 : word) (f f1 f2 : N) :
  deliveriesc a s f s1 f1 -> deliveriesc b s1 f1 s2 f2 ->
  deliveriesc (a ++ b) s f s2 f2.
Proof.
  intros HA HB. induction HA as [s f s' f' E|K Ks s f sm fm s' f' HT HR IH].
  - cbn [app]. inversion HB as [s0 f0 s1' f1' E1|K1 Ks1 s0 f0 sm fm s1' f1' HT1 HR1]; subst.
    + apply deliveriesc_O. rewrite E. exact E1.
    + exact (deliveriesc_S _ _ _ _ _ _ _ _
               (delivery_tripc_sdec_left _ _ _ _ _ _ _ E HT1) HR1).
  - cbn [app]. exact (deliveriesc_S _ _ _ _ _ _ _ _ HT (IH HB)).
Qed.
Lemma delivery_stagec (X cY K : N) (rest tail : word) (f f2 : N) :
  (5 <= X)%N -> (1 <= cY)%N ->
  delivery_tripc K rest f tail f2 ->
  delivery_tripc (K + 2*X + 14*cY + 14)%N
    ((X,3,1)%N :: (4,2,cY)%N :: rest) f
    ((X-1,1,1)%N :: (7,2,1)%N :: (4,2,cY-1)%N :: tail) f2.
Proof.
  intros HX HY (c & p & q & HF & EQ).
  destruct (casc_stagec X cY rest tail f f2 c p K q HX HY HF EQ)
    as (c2 & p2 & q2 & HF2 & EQ2).
  exists c2, p2, q2. split; assumption.
Qed.
Lemma delivery_jumpc (cols sfx tail seg : word) (B K f f2 : N) :
  forallb (fun g => is_col g && negb (is_cmf g)
                    && (3 <=? gO g)%N) cols = true ->
  jump_seg cols B = Some seg -> (1 <= B)%N ->
  delivery_tripc K sfx f tail f2 ->
  delivery_tripc (K + wcolcost cols + 14*B + 22)%N
    (cols ++ (4,3,1)%N :: (4,2,B)%N :: sfx) f (seg ++ tail) f2.
Proof.
  intros HC HJ HB (c & p & q & HF & EQ).
  destruct (casc_jump_innerc cols sfx tail seg B f f2 c p K q
              HC HJ HB HF EQ) as (c2 & p2 & q2 & HF2 & EQ2).
  exists c2, p2, q2. split; assumption.
Qed.
Ltac emits_seg :=
  intros i Hi;
  repeat (destruct i as [|i]; [vm_compute; reflexivity|]); lia.
