Lemma delivery_tripc_trip (K : N) (s s' : word) (f f' : N) :
  delivery_tripc K s f s' f' -> delivery_trip s f s' f'.
Proof.
  intros (c & p & q & HF & EQ).
  exists c, p, q. split; [exact (FTripC_FTrip _ _ _ _ _ HF)|exact EQ].
Qed.
Lemma deliveriesc_deliveries (Ks : list N) (s s' : word) (f f' : N) :
  deliveriesc Ks s f s' f' ->
  deliveries (length Ks) s f s' f'.
Proof.
  intros H. induction H as [s f s' f' E|K Ks s f s1 f1 s2 f2 HT HR IH].
  - apply deliveries_O. exact E.
  - cbn [length]. exact (deliveries_S _ _ _ _ _ _ _
      (delivery_tripc_trip _ _ _ _ _ HT) IH).
Qed.
Lemma nsumN_app (a b : list N) :
  nsumN (a ++ b) = (nsumN a + nsumN b)%N.
Proof. induction a as [|x t IH]; cbn [app nsumN]; lia. Qed.
Definition deliv (n : nat) (T : N) (s : word) (f : N)
                 (s' : word) (f' : N) : Prop :=
  exists Ks : list N,
    length Ks = n /\ nsumN Ks = T /\ deliveriesc Ks s f s' f'.
Lemma deliv_O (s : word) (f : N) (s' : word) (f' : N) :
  sdec s f = sdec s' f' -> deliv O 0%N s f s' f'.
Proof.
  intros E. exists ([] : list N). cbn [length nsumN].
  split; [reflexivity|]. split; [reflexivity|].
  exact (deliveriesc_O _ _ _ _ E).
Qed.
Lemma deliv_S (K T : N) (n : nat) (s : word) (f : N)
      (s1 : word) (f1 : N) (s2 : word) (f2 : N) :
  delivery_tripc K s f s1 f1 -> deliv n T s1 f1 s2 f2 ->
  deliv (S n) (K + T)%N s f s2 f2.
Proof.
  intros HT (Ks & HL & HS & HD). exists (K :: Ks).
  cbn [length nsumN]. rewrite HL, HS.
  split; [reflexivity|]. split; [reflexivity|].
  exact (deliveriesc_S _ _ _ _ _ _ _ _ HT HD).
Qed.
Lemma deliv_one (K : N) (s : word) (f : N) (s' : word) (f' : N) :
  delivery_tripc K s f s' f' -> deliv 1 K s f s' f'.
Proof.
  intros HT. rewrite <- (N.add_0_r K).
  exact (deliv_S K 0%N O s f s' f' s' f' HT
           (deliv_O s' f' s' f' eq_refl)).
Qed.
Lemma deliv_app (a b : nat) (Ta Tb : N) (s s1 s2 : word)
      (f f1 f2 : N) :
  deliv a Ta s f s1 f1 -> deliv b Tb s1 f1 s2 f2 ->
  deliv (a + b) (Ta + Tb)%N s f s2 f2.
Proof.
  intros (A & HLA & HSA & HDA) (B & HLB & HSB & HDB).
  exists (A ++ B). rewrite length_app, nsumN_app, HLA, HSA, HLB, HSB.
  split; [reflexivity|]. split; [reflexivity|].
  exact (deliveriesc_app A B s s1 s2 f f1 f2 HDA HDB).
Qed.
Lemma deliv_zero_inv (T : N) (s : word) (f : N)
      (s' : word) (f' : N) :
  deliv O T s f s' f' -> T = 0%N /\ sdec s f = sdec s' f'.
Proof.
  intros (Ks & HL & HS & HD).
  destruct Ks as [|k r]; [|cbn [length] in HL; lia].
  cbn [nsumN] in HS. subst T.
  inversion HD as [s0 f0 s1 f1 E|]; subst.
  split; [reflexivity|exact E].
Qed.
Lemma deliv_one_inv (T : N) (s : word) (f : N)
      (s' : word) (f' : N) :
  deliv 1 T s f s' f' -> delivery_tripc T s f s' f'.
Proof.
  intros (Ks & HL & HS & HD).
  destruct Ks as [|k r]; [cbn [length] in HL; lia|].
  destruct r as [|k2 r2]; [|cbn [length] in HL; lia].
  cbn [nsumN] in HS. rewrite N.add_0_r in HS. subst k.
  inversion HD as [|K0 Ks0 s0 f0 s1 f1 s2 f2 HTrip HRest]; subst.
  inversion HRest as [sa fa sb fb E|]; subst.
  exact (delivery_tripc_sdec_right _ _ _ _ _ _ _ E HTrip).
Qed.
Lemma deliv_split (a b : nat) (T : N) (s s' : word) (f f' : N) :
  deliv (a + b) T s f s' f' ->
  exists sm fm Ta Tb,
    T = (Ta + Tb)%N /\ deliv a Ta s f sm fm /\ deliv b Tb sm fm s' f'.
Proof.
  revert T s f s' f'.
  induction a as [|a IH]; intros T s f s' f' (Ks & HL & HS & HD).
  - exists s, f, 0%N, T. cbn [Nat.add] in HL.
    split; [lia|]. split; [exact (deliv_O s f s f eq_refl)|].
    exists Ks. auto.
  - destruct Ks as [|k r]; [cbn [Nat.add length] in HL; lia|].
    cbn [Nat.add length nsumN] in HL, HS.
    inversion HD as [|K0 Ks0 s0 f0 s1 f1 s2 f2 HTrip HRest]; subst.
    assert (HLr : length r = (a + b)%nat) by lia.
    assert (HRr : deliv (a + b) (nsumN r) s1 f1 s' f')
      by (exists r; split; [exact HLr|split; [reflexivity|exact HRest]]).
    destruct (IH (nsumN r) s1 f1 s' f' HRr)
      as (sm & fm & Ta & Tb & ET & HA & HB).
    exists sm, fm, (k + Ta)%N, Tb.
    split; [lia|]. split; [|exact HB].
    exact (deliv_S k Ta a s f s1 f1 sm fm HTrip HA).
Qed.
Lemma deliv_sdec_left (n : nat) (T : N) (s0 s s' : word)
      (f0 f f' : N) :
  sdec s0 f0 = sdec s f ->
  deliv n T s f s' f' -> deliv n T s0 f0 s' f'.
Proof.
  intros E (Ks & HL & HS & HD). exists Ks.
  split; [exact HL|]. split; [exact HS|].
  destruct HD as [sa fa sb fb E1|K Ks1 sa fa s1 f1 s2 f2 HT HR].
  - apply deliveriesc_O. rewrite E. exact E1.
  - exact (deliveriesc_S _ _ _ _ _ _ _ _
             (delivery_tripc_sdec_left _ _ _ _ _ _ _ E HT) HR).
Qed.
Lemma deliveriesc_sdec_right (Ks : list N) (s s' s0 : word)
      (f f' f0 : N) :
  sdec s' f' = sdec s0 f0 ->
  deliveriesc Ks s f s' f' -> deliveriesc Ks s f s0 f0.
Proof.
  intros E HD. revert s0 f0 E.
  induction HD as [sa fa sb fb E1|K Ks1 sa fa s1 f1 s2 f2 HT HR IH];
    intros s0 f0 E.
  - apply deliveriesc_O. rewrite E1. exact E.
  - exact (deliveriesc_S _ _ _ _ _ _ _ _ HT (IH s0 f0 E)).
Qed.
Lemma deliv_sdec_right (n : nat) (T : N) (s s' s0 : word)
      (f f' f0 : N) :
  sdec s' f' = sdec s0 f0 ->
  deliv n T s f s' f' -> deliv n T s f s0 f0.
Proof.
  intros E (Ks & HL & HS & HD). exists Ks.
  split; [exact HL|]. split; [exact HS|].
  exact (deliveriesc_sdec_right Ks s s' s0 f f' f0 E HD).
Qed.
Lemma deliv_cols (n : nat) (T : N) (cols s s' : word) (f f' : N) :
  delivery_cols cols = true ->
  deliv n T s f s' f' ->
  deliv n (T + N.of_nat n * wcolcost cols)%N
       (cols ++ s) f (cols ++ s') f'.
Proof.
  intros HC (Ks & HL & HS & HD).
  exists (shiftK cols Ks).
  rewrite shiftK_length, nsumN_shiftK, HL, HS.
  split; [reflexivity|]. split; [reflexivity|].
  exact (deliveriesc_cols cols Ks s s' f f' HC HD).
Qed.
Lemma deliv_deliveries (n : nat) (T : N) (s s' : word) (f f' : N) :
  deliv n T s f s' f' -> deliveries n s f s' f'.
Proof.
  intros (Ks & HL & _ & HD). rewrite <- HL.
  exact (deliveriesc_deliveries Ks s s' f f' HD).
Qed.
Definition dphase (p c : N) : N :=
  (2 * ladderA p
   + (if emits p then 14 * c + 14 else 3))%N.
Lemma leaf_deliveryc (p c : N) (rest : word) (f : N) :
  (p < 28)%N -> emits p = false -> (2 <= c)%N ->
  delivery_tripc (dphase p c)
    (phase_form p ++ (4,2,c)%N :: rest) f
    (phase_form (p+1) ++
       (4,2, c + DBu (p+1) - DBu p)%N :: rest) f.
Proof.
  intros Hp Hem Hc.
  pose proof (leaf_tick p c rest f Hp Hem Hc) as HL.
  destruct (leaf_phase_head p Hp Hem) as (x & tl0 & EPh).
  assert (EA : ladderA p = x) by (unfold ladderA; rewrite EPh; reflexivity).
  unfold dphase. rewrite EA, Hem.
  rewrite EPh in HL |- *. cbn [app] in HL |- *.
  destruct (leaf_z1_ftripC x 1
              (tl0 ++ (4,2,c)%N :: rest) _ f f HL) as (pp & q & HF & EQ).
  exists 2%nat, pp, q. split; [|exact EQ].
  replace (2 * x + 3)%N with (2 * x + 3)%N by lia. exact HF.
Qed.
Lemma phase_tick_delivc (p c T : N) (rest tail : word) (f f' : N) :
  (p < 27)%N -> (2 <= c)%N ->
  deliv (N.to_nat (marks (p+1) - marks p)) T
        rest f tail f' ->
  delivery_tripc (dphase p c + T)%N
    (phase_form p ++ (4,2,c)%N :: rest) f
    (phase_form (p+1) ++
       (4,2, c + DBu (p+1) - DBu p)%N :: tail) f'.
Proof.
  intros Hp Hc HD.
  assert (Hp28 : (p < 28)%N) by lia.
  destruct (emits p) eqn:Hem.
  - destruct (emits_nonjump p Hp28 Hem ltac:(lia))
      as [E|[E|E]]; subst p;
      cbn [marks EMt] in HD |- *;
      pose proof (deliv_one_inv _ _ _ _ _ HD) as HT.
    + pose proof (delivery_stagec 7 c T rest tail f f'
        ltac:(lia) ltac:(lia) HT) as HS.
      assert (EC : (dphase 3 c + T)%N = (T + 2*7 + 14*c + 14)%N).
      { unfold dphase.
        replace (ladderA 3) with 7%N by reflexivity.
        replace (emits 3) with true by reflexivity.
        lia. }
      rewrite EC.
      eapply delivery_tripc_sdec_right; [|exact HS].
      normgen. cbn [app].
      replace (c + 2 - 3)%N with (c-1)%N by lia. reflexivity.
    + pose proof (delivery_stagec 6 c T rest tail f f'
        ltac:(lia) ltac:(lia) HT) as HS.
      assert (EC : (dphase 11 c + T)%N = (T + 2*6 + 14*c + 14)%N).
      { unfold dphase.
        replace (ladderA 11) with 6%N by reflexivity.
        replace (emits 11) with true by reflexivity.
        lia. }
      rewrite EC.
      eapply delivery_tripc_sdec_right; [|exact HS].
      normgen. cbn [app].
      replace (c + 1 - 2)%N with (c-1)%N by lia. reflexivity.
    + pose proof (delivery_stagec 5 c T rest tail f f'
        ltac:(lia) ltac:(lia) HT) as HS.
      assert (EC : (dphase 19 c + T)%N = (T + 2*5 + 14*c + 14)%N).
      { unfold dphase.
        replace (ladderA 19) with 5%N by reflexivity.
        replace (emits 19) with true by reflexivity.
        lia. }
      rewrite EC.
      eapply delivery_tripc_sdec_right; [|exact HS].
      normgen. cbn [app].
      replace (c + 0 - 1)%N with (c-1)%N by lia. reflexivity.
  - rewrite (marks_delta_zero p Hp Hem) in HD.
    destruct (deliv_zero_inv _ _ _ _ _ HD) as (ET & HE). subst T.
    rewrite N.add_0_r.
    pose proof (leaf_deliveryc p c rest f Hp28 Hem Hc) as HLc.
    eapply delivery_tripc_sdec_right; [|exact HLc].
    rewrite !sdec_app, !sdec_cons, HE. reflexivity.
Qed.
Fixpoint dladder (p b : N) (n : nat) : N :=
  match n with
  | O => 0%N
  | S k => (dphase p (b + DBu p) + dladder (p+1) b k)%N
  end.
Lemma phase_ticks_delivc (n : nat) :
  forall (p b T : N) (rest tail : word) (f f' : N),
  (p + N.of_nat n < 28)%N -> (FLOOR <= b)%N ->
  deliv (N.to_nat (marks (p + N.of_nat n) - marks p))
        T rest f tail f' ->
  deliv n (dladder p b n + T)%N
    (phase_form p ++ (4,2,b + DBu p)%N :: rest) f
    (phase_form (p + N.of_nat n) ++
       (4,2, b + DBu (p + N.of_nat n))%N :: tail) f'.
Proof.
  induction n as [|n IH]; intros p b T rest tail f f' Hbound Hb HD.
  - change (N.of_nat O) with 0%N in *.
    rewrite N.add_0_r in HD |- *. rewrite N.sub_diag in HD.
    cbn [N.to_nat] in HD.
    destruct (deliv_zero_inv _ _ _ _ _ HD) as (ET & HE). subst T.
    cbn [dladder]. rewrite N.add_0_r.
    apply deliv_O.
    rewrite !sdec_app, !sdec_cons.
    exact (f_equal
      (fun x => expand
        (map gdecode (phase_form p)) ++
        pair_runs (N.to_nat 4) (N.to_nat 2)
          (N.to_nat (b + DBu p)) ++ x) HE).
  - rewrite Nat2N.inj_succ in Hbound, HD |- *.
    set (q := (p + 1)%N).
    replace (p + N.succ (N.of_nat n))%N with
      (q + N.of_nat n)%N in HD by (unfold q; lia).
    assert (Hp : (p < 27)%N) by (unfold q in *; lia).
    assert (Hq : (q + N.of_nat n < 28)%N) by (unfold q; lia).
    assert (Hm0 : (marks p <= marks q)%N)
      by (apply marks_mono; unfold q; lia).
    assert (Hm1 :
      (marks q <= marks (q + N.of_nat n))%N)
      by (apply marks_mono; lia).
    assert (Hemadd :
      N.to_nat
        (marks (q + N.of_nat n) - marks p) =
      (N.to_nat (marks q - marks p) +
       N.to_nat
         (marks (q + N.of_nat n) - marks q))%nat)
      by (rewrite <- N2Nat.inj_add; f_equal; lia).
    rewrite Hemadd in HD.
    destruct (deliv_split _ _ _ _ _ _ _ HD)
      as (mid & fm & T1 & T2 & ET & Hone & Hrest).
    assert (Hdp : (DBu p <= 3)%N)
      by (apply DBu_le3; lia).
    assert (Htick : delivery_tripc
      (dphase p (b + DBu p) + T1)%N
      (phase_form p ++
        (4,2,b + DBu p)%N :: rest) f
      (phase_form (p+1) ++
        (4,2,b + DBu (p+1))%N :: mid) fm).
    { pose proof (phase_tick_delivc p (b + DBu p) T1
        rest mid f fm Hp ltac:(unfold FLOOR in Hb; lia) Hone)
        as HT.
      replace (b + DBu p + DBu (p+1) -
        DBu p)%N with
        (b + DBu (p+1))%N in HT by lia.
      exact HT. }
    replace (dladder p b (S n) + T)%N with
      ((dphase p (b + DBu p) + T1)
       + (dladder q b n + T2))%N
      by (cbn [dladder]; unfold q; lia).
    change (p + 1)%N with q.
    replace (p + N.succ (N.of_nat n))%N with
      (q + N.of_nat n)%N by (unfold q; lia).
    exact (deliv_S _ _ _ _ _ _ _ _ _ Htick
             (IH q b T2 mid tail fm f' Hq Hb Hrest)).
Qed.
Lemma ticks_to_jumpc (p b T : N) (post mid : word) (f fm : N) :
  (p < 28)%N -> (FLOOR <= b)%N ->
  deliv (N.to_nat (marks 27 - marks p)) T
        post f mid fm ->
  deliv (N.to_nat (27-p)) (dladder p b (N.to_nat (27-p)) + T)%N
    (phase_form p ++ (4,2,b + DBu p)%N :: post) f
    (phase_form 27 ++ (4,2,b)%N :: mid) fm.
Proof.
  intros Hp Hb HD.
  pose proof (phase_ticks_delivc (N.to_nat (27-p)) p b T
    post mid f fm) as H.
  rewrite N2Nat.id in H.
  replace (p + (27-p))%N with 27%N in H by lia.
  change (DBu 27) with 0%N in H.
  replace (b+0)%N with b in H by lia.
  apply H; [lia|exact Hb|exact HD].
Qed.
Lemma transit_delivery_posc (cols : word) (c p b T : N)
      (post tail : word) (f f' : N) :
  delivery_cols cols = true -> (p < 28)%N ->
  (1 <= c)%N -> (FLOOR <= b)%N ->
  deliv (N.to_nat (marks 28 - marks p)) T
        post f tail f' ->
  deliv (N.to_nat (28-p))
    (dladder p b (N.to_nat (27-p))
     + (28-p) * wcolcost (cols ++ rung1 c)
     + 14*b + 22 + T)%N
    (cols ++ rung1 c ++ phase_form p ++
       (4,2,b + DBu p)%N :: post) f
    (cols ++ phase_form 0 ++ (4,2,c)%N ::
       rung1 (b-1) ++ tail) f'.
Proof.
  intros Hcols Hp Hc Hb HD.
  rewrite (marks_transit_split p Hp) in HD.
  destruct (deliv_split _ _ _ _ _ _ _ HD)
    as (mid & fm & T1 & T2 & ET & Hpre & Hlast).
  pose proof (ticks_to_jumpc p b T1 post mid f fm Hp Hb Hpre) as Hticks.
  assert (Hprefix : delivery_cols
      (cols ++ rung1 c) = true).
  { rewrite delivery_cols_app, Hcols,
      delivery_cols_rung. reflexivity. }
  pose proof (deliv_cols _ _ (cols ++ rung1 c)
    _ _ _ _ Hprefix Hticks) as Hticks'.
  pose proof (deliv_one_inv _ _ _ _ _ Hlast) as Htail.
  assert (Hb1 : (1 <= b)%N) by (unfold FLOOR in Hb; lia).
  pose proof (delivery_jumpc
    (cols ++ rung1 c) mid tail
    ((cols ++ phase_form 0 ++ (4,2,c)%N ::
       rung1 (b-1))%list)
    b T2 fm f' Hprefix (jump_seg_app_rung cols c b
      Hc ltac:(unfold FLOOR in Hb; lia)) Hb1 Htail) as Hjump.
  pose proof (deliv_app _ _ _ _ _ _ _ _ _ _ Hticks'
    (deliv_one _ _ _ _ _ Hjump)) as Hall.
  replace (N.to_nat (28-p)) with (N.to_nat (27-p) + 1)%nat.
  2: { rewrite N2Nat.inj_sub by lia. rewrite N2Nat.inj_sub by lia.
       change (N.to_nat 28) with 28%nat.
       change (N.to_nat 27) with 27%nat. lia. }
  replace (dladder p b (N.to_nat (27-p))
     + (28-p) * wcolcost (cols ++ rung1 c)
     + 14*b + 22 + T)%N
    with ((dladder p b (N.to_nat (27-p)) + T1
           + N.of_nat (N.to_nat (27-p))
             * wcolcost (cols ++ rung1 c))
          + (T2 + wcolcost (cols ++ rung1 c)
             + 14*b + 22))%N.
  2: { rewrite N2Nat.id.
       replace (28-p)%N with ((27-p) + 1)%N by lia. lia. }
  repeat rewrite app_assoc in Hall |- *.
  assert (Eout :
    (((cols ++ phase_form 0) ++
       (4,2,c)%N :: rung1 (b-1)) ++ tail) =
    cols ++ phase_form 0 ++ (4,2,c)%N ::
      rung1 (b-1) ++ tail).
  { rewrite <- (app_assoc (cols ++ phase_form 0)
        ((4,2,c)%N :: rung1 (b-1)) tail).
    cbn [app]. symmetry. apply app_assoc. }
  rewrite <- Eout. repeat rewrite app_assoc. exact Hall.
Qed.
Lemma deliv_master_creach (n : nat) (T c_0 : N) (p' s s' : word)
      (f f' : N) :
  zpre p' -> (1 <= c_0)%N -> deliv n T s f s' f' ->
  creach (cx (N.of_nat n * bsum ((2,2,c_0)%N :: p')
              + 10 * tri n + T + 6 * N.of_nat n)%N)
    (wconf [] 0 (sdecode (((2,2,c_0)%N :: p') ++ s) f))
    (wconf [] 0 (sdecode
       (((2,2, c_0 + N.of_nat n)%N :: p') ++ s') f')).
Proof.
  intros HP HC0 (Ks & HL & HS & HD).
  pose proof (deliveriesc_master_creach Ks c_0 p' s s' f f' HP HC0 HD) as H.
  rewrite HL, HS in H. exact H.
Qed.
Lemma wcolcost_rung1 (c : N) :
  wcolcost (rung1 c) = (14 * c + 22)%N.
Proof.
  cbn [rung1 wcolcost
       gO gZ gC]. lia.
Qed.
Definition sd_next (o : option N) (w1 : word) : word :=
  match o with
  | None => w1
  | Some c => rung1 c ++ w1
  end.
Fixpoint sched_delivc (T : N) (rs : list (option N))
         (w : word) (f : N) (out : word) (f' : N) : Prop :=
  match rs with
  | [] => T = 0%N /\ w = out /\ f = f'
  | o :: r =>
      exists K T1 w1 f1,
        T = (K + T1)%N /\ delivery_tripc K w f w1 f1
        /\ sched_delivc T1 r (sd_next o w1) f1 out f'
  end.
Fixpoint sched_tripsc (T : N) (rs : list (option N))
         (w : word) (f : N) (out : word) (f' : N) : Prop :=
  match rs with
  | [] => T = 0%N /\ sdec w f = sdec out f'
  | o :: r =>
      exists K T1 w1 f1,
        T = (K + T1)%N /\ delivery_tripc K w f w1 f1
        /\ sched_tripsc T1 r (sd_next o w1) f1 out f'
  end.
Lemma sched_delivc_proj (rs : list (option N)) :
  forall (T : N) (w out : word) (f f' : N),
  sched_delivc T rs w f out f' ->
  schedule_deliveries rs w f out f'.
Proof.
  induction rs as [|o r IH]; intros T w out f f' H.
  - destruct H as (_ & <- & <-). constructor.
  - destruct H as (K & T1 & w1 & f1 & _ & HD & HR).
    destruct o as [c|]; cbn [sd_next] in HR.
    + exact (schedule_deliveries_some _ _ _ _ _ _ _ _
               (delivery_tripc_trip _ _ _ _ _ HD) (IH _ _ _ _ _ HR)).
    + exact (schedule_deliveries_none _ _ _ _ _ _ _
               (delivery_tripc_trip _ _ _ _ _ HD) (IH _ _ _ _ _ HR)).
Qed.
Lemma sched_tripsc_proj (rs : list (option N)) :
  forall (T : N) (w out : word) (f f' : N),
  sched_tripsc T rs w f out f' ->
  schedule_trips rs w f out f'.
Proof.
  induction rs as [|o r IH]; intros T w out f f' H.
  - destruct H as (_ & E). constructor. exact E.
  - destruct H as (K & T1 & w1 & f1 & _ & HD & HR).
    destruct o as [c|]; cbn [sd_next] in HR.
    + exact (schedule_trips_some _ _ _ _ _ _ _ _
               (delivery_tripc_trip _ _ _ _ _ HD) (IH _ _ _ _ _ HR)).
    + exact (schedule_trips_none _ _ _ _ _ _ _
               (delivery_tripc_trip _ _ _ _ _ HD) (IH _ _ _ _ _ HR)).
Qed.
Lemma sched_delivc_tripsc (rs : list (option N)) :
  forall (T : N) (w out : word) (f f' : N),
  sched_delivc T rs w f out f' -> sched_tripsc T rs w f out f'.
Proof.
  induction rs as [|o r IH]; intros T w out f f' H.
  - destruct H as (E & <- & <-). split; [exact E|reflexivity].
  - destruct H as (K & T1 & w1 & f1 & ET & HD & HR).
    exists K, T1, w1, f1. split; [exact ET|].
    split; [exact HD|exact (IH _ _ _ _ _ HR)].
Qed.
Lemma sched_delivc_app_inv (a : list (option N)) :
  forall (b : list (option N)) (T : N) (w out : word) (f f' : N),
  sched_delivc T (a ++ b) w f out f' ->
  exists mid fm Ta Tb,
    T = (Ta + Tb)%N /\ sched_delivc Ta a w f mid fm
    /\ sched_delivc Tb b mid fm out f'.
Proof.
  induction a as [|o a IH]; intros b T w out f f' H.
  - cbn [app] in H. exists w, f, 0%N, T.
    split; [lia|]. split; [cbn [sched_delivc]; auto|exact H].
  - cbn [app sched_delivc] in H.
    destruct H as (K & T1 & w1 & f1 & ET & HD & HR).
    destruct (IH b T1 (sd_next o w1) out f1 f' HR)
      as (mid & fm & Ta & Tb & ET1 & HA & HB).
    exists mid, fm, (K + Ta)%N, Tb.
    split; [lia|]. split; [|exact HB].
    cbn [sched_delivc]. exists K, Ta, w1, f1.
    split; [reflexivity|]. split; [exact HD|exact HA].
Qed.
Lemma sched_delivc_nones (n : nat) :
  forall (T : N) (w out : word) (f f' : N),
  sched_delivc T (repeat None n) w f out f' -> deliv n T w f out f'.
Proof.
  induction n as [|n IH]; intros T w out f f' H.
  - cbn [repeat sched_delivc] in H. destruct H as (-> & <- & <-).
    apply deliv_O. reflexivity.
  - cbn [repeat sched_delivc] in H.
    destruct H as (K & T1 & w1 & f1 & -> & HD & HR).
    cbn [sd_next] in HR.
    exact (deliv_S _ _ _ _ _ _ _ _ _ HD (IH _ _ _ _ _ HR)).
Qed.
Lemma sched_delivc_nones_some (n : nat) :
  forall (c T : N) (w out : word) (f f' : N),
  sched_delivc T (repeat None n ++ [Some c]) w f out f' ->
  exists tail,
    deliv (S n) T w f tail f'
    /\ out = rung1 c ++ tail.
Proof.
  induction n as [|n IH]; intros c T w out f f' H.
  - cbn [repeat app sched_delivc] in H.
    destruct H as (K & T1 & w1 & f1 & -> & HD & HR).
    cbn [sd_next sched_delivc] in HR.
    destruct HR as (-> & <- & <-).
    exists w1. split; [|reflexivity]. rewrite N.add_0_r.
    exact (deliv_one _ _ _ _ _ HD).
  - cbn [repeat app sched_delivc] in H.
    destruct H as (K & T1 & w1 & f1 & -> & HD & HR).
    cbn [sd_next] in HR.
    destruct (IH c T1 w1 out f1 f' HR) as (tail & HDel & ->).
    exists tail. split; [|reflexivity].
    exact (deliv_S _ _ _ _ _ _ _ _ _ HD HDel).
Qed.
Lemma CascadeC_wcolcost_app (a b : word) :
  wcolcost (a ++ b)
  = (wcolcost a + wcolcost b)%N.
Proof.
  induction a as [|g t IH]; cbn [app wcolcost]; lia.
Qed.
Fixpoint wcolsum (l : list N) : N :=
  match l with [] => 0%N | x :: r => (14 * x + 22 + wcolsum r)%N end.
Lemma wcolcost_runway (l : list N) :
  wcolcost (runway l) = wcolsum l.
Proof.
  induction l as [|x r IH]; [reflexivity|].
  cbn [runway wcolsum].
  rewrite CascadeC_wcolcost_app, wcolcost_rung1, IH. lia.
Qed.
Definition dtransit1 (p b W : N) : N :=
  (dladder p b (N.to_nat (27-p)) + (28-p) * W + 14*b + 22)%N.
Fixpoint drunway (W0 : N) (rl : list N) (p rem b : N) : N :=
  match rl with
  | [] => 0%N
  | d :: rest =>
      (dtransit1 p b (W0 + wcolsum (d :: rest))
       + match rest with
         | [] => (dladder 0 (d-3) (N.to_nat rem) + rem * W0)%N
         | _ => drunway W0 rest 0 rem (d-3)
         end)%N
  end.
Lemma one_runway_scheduled_delivc (c : N) (cols : word)
      (p rem b T : N) (post out : word) (f f' : N) :
  delivery_cols cols = true ->
  (FLOOR + 3 <= c)%N ->
  (p < 28)%N -> (rem < 28)%N -> (FLOOR <= b)%N ->
  sched_delivc T (bulk_schedule p rem [] b) post f out f' ->
  deliv (N.to_nat (28 + rem - p))
    (drunway (wcolcost cols) [c] p rem b + T)%N
    (cols ++ rung1 c ++ phase_form p ++
       (4,2,b + DBu p)%N :: post) f
    (cols ++ phase_form rem ++
       (4,2,c - 3 + DBu rem)%N :: out) f'.
Proof.
  intros HCols Hc Hp Hr Hb HRun.
  rewrite bulk_schedule_nil in HRun.
  destruct (sched_delivc_app_inv
    (repeat None (schedule_slot_nat p) ++ [Some (b-1)%N])
    (repeat None (N.to_nat (marks rem)))
    T post out f f' HRun) as (mid & fm & TB & TR & ET & HBlock & HRest).
  destruct (sched_delivc_nones_some
    (schedule_slot_nat p) (b-1)%N TB post mid f fm HBlock)
    as (post1 & HDeliver & Emid).
  subst mid.
  rewrite (schedule_slot_transit_count p Hp) in HDeliver.
  pose proof (transit_delivery_posc cols c p b TB post post1 f fm
    HCols Hp ltac:(unfold FLOOR in Hc; lia) Hb HDeliver)
    as HTransit.
  pose proof (sched_delivc_nones
    (N.to_nat (marks rem)) TR
    (rung1 (b-1)%N ++ post1) out fm f' HRest) as HRem.
  assert (HRem' : deliv
    (N.to_nat
      (marks (0 + N.of_nat (N.to_nat rem)) -
       marks 0)) TR
    (rung1 (b-1)%N ++ post1) fm out f').
  { rewrite N2Nat.id, N.add_0_l.
    change (marks 0) with 0%N. rewrite N.sub_0_r.
    exact HRem. }
  pose proof (phase_ticks_delivc
    (N.to_nat rem) 0 (c-3)%N TR
    (rung1 (b-1)%N ++ post1) out fm f'
    ltac:(rewrite N2Nat.id; lia)
    ltac:(unfold FLOOR in *; lia) HRem') as HPartial.
  rewrite N2Nat.id, N.add_0_l in HPartial.
  change (DBu 0) with 3%N in HPartial.
  replace (c - 3 + 3)%N with c in HPartial by lia.
  pose proof (deliv_cols _ _ cols _ _ _ _ HCols HPartial) as HPartialCols.
  pose proof (deliv_app _ _ _ _ _ _ _ _ _ _ HTransit HPartialCols) as HBoth.
  replace (N.to_nat (28 + rem - p)) with
    (N.to_nat (28-p) + N.to_nat rem)%nat.
  2: { rewrite <- N2Nat.inj_add. f_equal. lia. }
  replace (drunway (wcolcost cols) [c] p rem b + T)%N
    with ((dladder p b (N.to_nat (27-p))
           + (28-p) * wcolcost
                        (cols ++ rung1 c)
           + 14*b + 22 + TB)
          + (dladder 0 (c-3) (N.to_nat rem) + TR
             + N.of_nat (N.to_nat rem) * wcolcost cols))%N.
  2: { cbn [drunway wcolsum]. unfold dtransit1.
       rewrite CascadeC_wcolcost_app, wcolcost_rung1, N2Nat.id. lia. }
  repeat rewrite app_assoc in HBoth |- *.
  exact HBoth.
Qed.
Lemma wcolsum_app (a b : list N) :
  wcolsum (a ++ b) = (wcolsum a + wcolsum b)%N.
Proof. induction a as [|x t IH]; cbn [app wcolsum]; lia. Qed.
Lemma wcolsum_rev (l : list N) : wcolsum (rev l) = wcolsum l.
Proof.
  induction l as [|x t IH]; [reflexivity|].
  cbn [rev wcolsum]. rewrite wcolsum_app, IH. cbn [wcolsum]. lia.
Qed.
Lemma drunway_cons_ne (W0 d : N) (rest : list N) (p rem b : N) :
  rest <> [] ->
  drunway W0 (d :: rest) p rem b
  = (dtransit1 p b (W0 + wcolsum (d :: rest))
     + drunway W0 rest 0 rem (d-3))%N.
Proof. intros H. destruct rest as [|x r]; [contradiction|reflexivity]. Qed.
Lemma rev_cons_ne (a : N) (l : list N) : rev (a :: l) <> [].
Proof.
  cbn [rev]. destruct (rev l) as [|y ys]; cbn [app]; discriminate.
Qed.
Theorem runway_scheduled_delivc (cs : list N) :
  forall (c : N) (cols : word) (p rem b T : N)
         (post out : word) (f f' : N),
  delivery_cols cols = true ->
  Forall (fun x => (FLOOR + 3 <= x)%N) (c :: cs) ->
  (p < 28)%N -> (rem < 28)%N -> (FLOOR <= b)%N ->
  sched_delivc T (bulk_schedule p rem cs b) post f out f' ->
  deliv
    (N.to_nat (28 * N.of_nat (length (c :: cs)) + rem - p))
    (drunway (wcolcost cols) (rev (c :: cs)) p rem b + T)%N
    (cols ++ runway (c :: cs) ++
       phase_form p ++
       (4,2,b + DBu p)%N :: post) f
    (cols ++ phase_form rem ++
       (4,2,c - 3 + DBu rem)%N :: out) f'.
Proof.
  induction cs as [|d cs IH] using rev_ind;
    intros c cols p rem b T post out f f'
      HCols HLevels Hp Hr Hb HRun.
  - change (length [c]) with 1%nat.
    change (runway [c]) with
      (rung1 c).
    replace (28 * N.of_nat 1 + rem - p)%N with (28 + rem - p)%N by lia.
    change (rev [c]) with [c].
    exact (one_runway_scheduled_delivc
      c cols p rem b T post out f f' HCols
      ltac:(inversion HLevels; assumption) Hp Hr Hb HRun).
  - assert (ELevels : c :: cs ++ [d] = (c :: cs) ++ [d]) by reflexivity.
    rewrite ELevels in HLevels.
    apply Forall_app in HLevels. destruct HLevels as [HOuter HLast].
    inversion HLast as [|d0 nil0 Hd HNil]; subst d0 nil0.
    assert (Hd4 : (4 <= d)%N)
      by (unfold FLOOR in Hd; lia).
    rewrite (bulk_schedule_snoc p rem cs b d Hd4) in HRun.
    destruct (sched_delivc_app_inv
      (repeat None (schedule_slot_nat p) ++ [Some (b-1)%N])
      (bulk_schedule 0 rem cs (d-3)%N)
      T post out f f' HRun) as (mid & fm & TB & TR & ET & HBlock & HRest).
    destruct (sched_delivc_nones_some
      (schedule_slot_nat p) (b-1)%N TB post mid f fm HBlock)
      as (post1 & HDeliver & Emid).
    subst mid.
    rewrite (schedule_slot_transit_count p Hp) in HDeliver.
    assert (HOuterCols : delivery_cols
      (cols ++ runway (c :: cs)) = true).
    { rewrite delivery_cols_app, HCols,
        delivery_cols_runway. reflexivity. }
    pose proof (transit_delivery_posc
      (cols ++ runway (c :: cs))
      d p b TB post post1 f fm HOuterCols Hp
      ltac:(unfold FLOOR in Hd; lia) Hb HDeliver) as HFirst.
    pose proof (IH c cols 0%N rem (d-3)%N TR
      (rung1 (b-1)%N ++ post1) out fm f'
      HCols HOuter ltac:(lia) Hr ltac:(lia) HRest) as HDeep.
    rewrite N.sub_0_r in HDeep.
    change (DBu 0) with 3%N in HDeep.
    replace (d - 3 + 3)%N with d in HDeep by lia.
    repeat rewrite app_assoc in HFirst, HDeep.
    pose proof (deliv_app _ _ _ _ _ _ _ _ _ _ HFirst HDeep) as HBoth.
    replace (length (c :: cs ++ [d])) with (S (length (c :: cs)))
      by (cbn [length]; rewrite length_app; cbn [length]; lia).
    rewrite Nat2N.inj_succ.
    replace
      (N.to_nat
        (28 * N.succ (N.of_nat (length (c :: cs))) + rem - p))
      with
      (N.to_nat (28-p) +
       N.to_nat (28 * N.of_nat (length (c :: cs)) + rem))%nat.
    2: { rewrite <- N2Nat.inj_add. f_equal. lia. }
    assert (ERev : rev (c :: cs ++ [d]) = d :: rev (c :: cs)).
    { rewrite ELevels, rev_app_distr. reflexivity. }
    rewrite ERev, (drunway_cons_ne _ _ _ _ _ _ (rev_cons_ne c cs)).
    replace (wcolcost cols + wcolsum (d :: rev (c :: cs)))%N
      with (wcolcost
              ((cols ++ runway (c :: cs))
               ++ rung1 d)).
    2: { rewrite !CascadeC_wcolcost_app, wcolcost_rung1, wcolcost_runway.
         replace (wcolsum (d :: rev (c :: cs)))
           with (14*d + 22 + wcolsum (rev (c :: cs)))%N by reflexivity.
         rewrite wcolsum_rev. lia. }
    unfold dtransit1.
    replace
      ((dladder p b (N.to_nat (27-p))
        + (28-p) * wcolcost
                     ((cols ++ runway (c :: cs))
                      ++ rung1 d)
        + 14*b + 22)
       + drunway (wcolcost cols) (rev (c :: cs)) 0 rem (d-3)
       + T)%N
      with
      ((dladder p b (N.to_nat (27-p))
        + (28-p) * wcolcost
                     ((cols ++ runway (c :: cs))
                      ++ rung1 d)
        + 14*b + 22 + TB)
       + (drunway (wcolcost cols) (rev (c :: cs)) 0 rem (d-3)
          + TR))%N by lia.
    rewrite ELevels, runway_app.
    cbn [runway app] in HBoth |- *.
    repeat rewrite app_nil_r in HBoth.
    repeat rewrite app_nil_r.
    repeat rewrite app_assoc in HBoth.
    repeat rewrite app_assoc.
    exact HBoth.
Qed.
Lemma sched_tripsc_factor (rs : list (option N)) :
  forall (T : N) (w out : word) (f f' : N),
  sched_tripsc T rs w f out f' ->
  exists out0 f0,
    sched_delivc T rs w f out0 f0
    /\ sdec out0 f0 = sdec out f'.
Proof.
  induction rs as [|o r IH]; intros T w out f f' H.
  - destruct H as (-> & E). exists w, f.
    split; [cbn [sched_delivc]; auto|exact E].
  - destruct H as (K & T1 & w1 & f1 & -> & HD & HR).
    destruct (IH T1 (sd_next o w1) out f1 f' HR) as (out0 & f0 & HRun & E).
    exists out0, f0. split; [|exact E].
    cbn [sched_delivc]. exists K, T1, w1, f1.
    split; [reflexivity|]. split; [exact HD|exact HRun].
Qed.
Definition scheduled_framec (T : N) (fr : lsc_frame)
    (sg : list seg) (w : word) (f : N)
    (sg' : list seg) (w' : word) (f' : N) : Prop :=
  (forall i, (i <= lsCur fr)%nat ->
    lin_flat sg (firstn i w) =
      lin_flat sg' (firstn i w')) /\
  forall rs base tail,
    schedule_frame_view fr
      (lin_flat sg (skipn (lsCur fr) w))
      rs base tail ->
    exists tail',
      sched_tripsc T rs tail f tail' f' /\
      lin_flat sg' (skipn (lsCur fr) w') =
        base ++ tail'.
Lemma scheduled_framec_frame (T : N) (fr : lsc_frame)
    (sg : list seg) (w : word) (f : N)
    (sg' : list seg) (w' : word) (f' : N) :
  scheduled_framec T fr sg w f sg' w' f' ->
  scheduled_frame fr sg w f sg' w' f'.
Proof.
  intros (HP & HF). split; [exact HP|].
  intros rs base tail HView.
  destruct (HF rs base tail HView) as (tail' & HT & HO).
  exists tail'. split; [exact (sched_tripsc_proj _ _ _ _ _ _ HT)|exact HO].
Qed.
Lemma scheduled_framec_output (T : N) (fr : lsc_frame)
    (sg : list seg) (w : word) (f : N)
    (sg' : list seg) (w' : word) (f' : N)
    (rs : list (option N)) (base tail : word) :
  scheduled_framec T fr sg w f sg' w' f' ->
  schedule_frame_view fr
    (lin_flat sg (skipn (lsCur fr) w)) rs base tail ->
  exists tail',
    sched_tripsc T rs tail f tail' f' /\
    lin_flat sg' w' =
      lin_flat sg (firstn (lsCur fr) w) ++ base ++ tail'.
Proof.
  intros (HP & HFrame) HView.
  destruct (HFrame rs base tail HView) as (tail' & HTrips & HOut).
  exists tail'. split; [exact HTrips|].
  rewrite (flat_firstn_skipn sg' w' (lsCur fr)).
  rewrite HOut, <- (HP (lsCur fr) (le_n _)).
  repeat rewrite <- app_assoc. reflexivity.
Qed.
Lemma creach_sdecode (d : cost) (a b a' b' : word)
      (fa fb fa' fb' : N) :
  sdecode a fa = sdecode a' fa' ->
  sdecode b fb = sdecode b' fb' ->
  creach d (wconf [] 0 (sdecode a fa)) (wconf [] 0 (sdecode b fb)) ->
  creach d (wconf [] 0 (sdecode a' fa'))
           (wconf [] 0 (sdecode b' fb')).
Proof. intros EA EB H. rewrite <- EA, <- EB. exact H. Qed.
Definition d_flight (base tk D : N) : cost :=
  cx (tk * base + 10 * (tk * (tk - 1) / 2) + 6 * tk + D)%N.
Lemma d_flight_eq (base tk D : N) :
  d_flight base tk D
  = cx (tk * base + 10 * tri (N.to_nat tk) + D + 6 * tk)%N.
Proof.
  unfold d_flight. rewrite tri_closed, !N2Nat.id. f_equal. lia.
Qed.
Lemma lin_bulk_master_scheduled_sound_fullc :
  forall sg J tail f j p tk w1 sg1 nh rem emit sg2 w2 f2 (T : N),
  stable_guard sg ((2,2,J)%N :: tail) ->
  (1 <= J)%N -> (1 <= j)%nat ->
  forallb is_col (firstn j ((2,2,J)%N :: tail)) = true ->
  detect_phase ((2,2,J)%N :: tail) j = Some p ->
  Nat.eqb (N.to_nat ((p+tk)/28)) O = false ->
  lin_bulk sg ((2,2,J)%N :: tail) j p tk =
    Some (w1, sg1, nh, rem, emit) ->
  scheduled_framec T
    (lin_sched_child nh rem emit p tk)
    sg1 (subst_at O 1 [(2,2,J+tk)%N] w1) f sg2 w2 f2 ->
  exists (pr : word) (c b : N) (cs : list N),
    forallb is_col pr = true
    /\ lin_flat sg (firstn j ((2,2,J)%N :: tail))
       = (2,2,J)%N :: pr ++ runway (c :: cs)
    /\ creach (d_flight (bsum ((2,2,J)%N :: pr)) tk
                 (drunway 0 (rev (c :: cs)) p rem b + T)%N)
         (wconf [] 0 (sdecode
            (lin_flat sg ((2,2,J)%N :: tail)) f))
         (wconf [] 0 (sdecode (lin_flat sg2 w2) f2)).
Proof.
  intros sg J tail f j p tk w1 sg1 nh rem emit sg2 w2 f2 T
    HG HJ Hj HCols HD HFull HB HFrame.
  pose proof HG as HG0.
  destruct HG as ((HOk & HPT) & HEdges & HW & HShape & HKeys & HPos).
  assert (HHead : is_spc
      (nth O ((2,2,J)%N::tail) d0) = false) by reflexivity.
  assert (HAlt : forall s, In s sg ->
      altb (sBody s) = true)
    by (exact (stable_altb sg ((2,2,J)%N::tail) HG0)).
  destruct (lin_bulk_checks
    sg ((2,2,J)%N::tail) j p tk _ HB)
    as (gb & EW & HKey & HLevel & HFloor & HEnd).
  destruct (site_layout ((2,2,J)%N::tail) j p gb HD EW HEnd)
    as (HLayout & HJRaw & HPost).
  destruct (detect_phase_form ((2,2,J)%N::tail) j p HD)
    as (Hp & HPhase).
  destruct (lin_bulk_tables
    sg ((2,2,J)%N::tail) j p tk w1 sg1 nh rem emit
    HW HShape HKeys HPos HHead HD HB)
    as (HW1 & HShape1 & HKeys1 & HPos1).
  destruct (lin_bulk_child_frame_data
    sg ((2,2,J)%N::tail) j p tk w1 sg1 nh rem emit gb
    (firstn j ((2,2,J)%N::tail))
    (skipn (S (j + phase_len p)) ((2,2,J)%N::tail))
    HW HOk HAlt HHead HLayout HJRaw HPost HKey Hp HFull HB HW1)
    as (PRE & POST & c & cs & b & HIn & HOut & HCoord & HLevels &
        HSafe & HPOST & Hb & HRem & HEmit & HRem28 & HView).
  assert (HjLen : (j <= length ((2,2,J)%N :: tail))%nat).
  { rewrite <- HJRaw. apply firstn_length_bound. }
  destruct (flat_cursor sg ((2,2,J)%N::tail) j HW HjLen)
    as (HFirst & HSkip).
  assert (EPrefix : lin_flat sg
      (firstn j ((2,2,J)%N::tail)) =
      PRE ++ runway (c :: cs)).
  { transitivity (firstn
      (fmapw sg ((2,2,J)%N::tail) O O j)
      (lin_flat sg ((2,2,J)%N::tail))).
    - symmetry. exact HFirst.
    - rewrite HCoord, HIn.
    unfold site.
    rewrite firstn_len_app. reflexivity. }
  destruct (flat_prefix_master_runway
    sg J tail j PRE c cs Hj EPrefix) as (pr & EPre).
  subst PRE.
  assert (EPrefixTail : lin_flat sg
      (firstn (j-1)%nat tail) =
      pr ++ runway (c :: cs)).
  { apply (flat_prefix_master_inv sg J tail j
      (pr ++ runway (c :: cs)) Hj).
    rewrite EPrefix. reflexivity. }
  assert (HFlatCols : forallb is_col
      (lin_flat sg (firstn (j-1)%nat tail)) = true).
  { apply flat_checked_prefix_cols.
    - exact HW.
    - exact (lin_generation_prefix_master
               J tail j HCols). }
  rewrite EPrefixTail in HFlatCols.
  rewrite forallb_app in HFlatCols.
  apply andb_prop in HFlatCols as [HPreCols HRunwayCols].
  assert (HprCols : forallb is_col pr = true)
    by exact HPreCols.
  destruct (lin_bulk_preserves_master
    sg J tail j p tk w1 sg1 nh rem emit Hj HD HB)
    as (tail1 & Ew1).
  assert (EWM : subst_at O 1 [(2,2,J+tk)%N] w1 =
      (2,2,J+tk)%N :: tail1) by (rewrite Ew1; reflexivity).
  destruct (lin_bulk_head_pos
    sg ((2,2,J)%N::tail) j p tk w1 sg1 nh rem emit
    Hj HHead HD HB) as (Hnh & HHead1).
  set (cur := (nh + phase_len rem)%nat).
  assert (Hcur : (1 <= cur)%nat).
  { unfold cur. pose proof (phase_len_pos rem). lia. }
  assert (ESkipMaster :
      skipn cur (subst_at O 1 [(2,2,J+tk)%N] w1) = skipn cur w1).
  { rewrite EWM, Ew1. destruct cur; [lia|reflexivity]. }
  assert (HViewM : schedule_frame_view
      (lin_sched_child nh rem emit p tk)
      (lin_flat sg1
        (skipn cur (subst_at O 1 [(2,2,J+tk)%N] w1)))
      (bulk_schedule p rem cs b)
      [(4,2,c - 3 + DBu rem)%N] POST).
  { rewrite ESkipMaster. exact HView. }
  destruct (scheduled_framec_output T
    (lin_sched_child nh rem emit p tk)
    sg1 (subst_at O 1 [(2,2,J+tk)%N] w1) f sg2 w2 f2
    (bulk_schedule p rem cs b)
    [(4,2,c - 3 + DBu rem)%N] POST
    HFrame HViewM) as (child & HTrips & HFinal).
  pose proof HView as HViewParts.
  unfold schedule_frame_view in HViewParts.
  destruct HViewParts as
    (HSlot & HLen & HSchedShape & HBaseCols & HSuffix0 & HGap).
  assert (HSuffix : lin_flat sg1 (skipn cur w1) =
      [(4,2,c - 3 + DBu rem)%N] ++
        crossed_post cs b POST).
  { unfold cur. rewrite bulk_schedule_stock in HSuffix0.
    unfold crossed_post in HSuffix0 |- *.
    rewrite app_nil_r in HSuffix0.
    repeat rewrite <- app_assoc in HSuffix0.
    exact HSuffix0. }
  assert (EPrefix1 : lin_flat sg1 (firstn cur w1) =
      (2,2,J)%N :: pr ++ phase_form rem).
  { pose proof (flat_firstn_skipn sg1 w1 cur) as EDec.
    rewrite HOut, HSuffix in EDec.
    unfold site in EDec.
    rewrite app_assoc in EDec.
    apply app_inv_tail in EDec. symmetry. exact EDec. }
  assert (EPrefix1' : lin_flat sg1 (firstn cur w1) =
      (2,2,J)%N :: (pr ++ phase_form rem)).
  { rewrite EPrefix1. reflexivity. }
  rewrite Ew1 in EPrefix1'.
  assert (EPrefixM0 : lin_flat sg1
      (firstn cur ((2,2,J+tk)%N::tail1)) =
      (2,2,J+tk)%N :: (pr ++ phase_form rem)).
  { exact (flat_firstn_master_change
             sg1 J (J+tk)%N tail1 cur
             (pr ++ phase_form rem) Hcur EPrefix1'). }
  assert (EPrefixM : lin_flat sg1
      (firstn cur (subst_at O 1 [(2,2,J+tk)%N] w1)) =
      (2,2,J+tk)%N :: (pr ++ phase_form rem)).
  { rewrite EWM. exact EPrefixM0. }
  set (tail2 := ((pr ++ phase_form rem) ++
    [(4,2,c - 3 + DBu rem)%N]) ++ child).
  assert (EFinal : lin_flat sg2 w2 = (2,2,J+tk)%N :: tail2).
  { change (lin_flat sg2 w2 =
      lin_flat sg1
        (firstn cur (subst_at O 1 [(2,2,J+tk)%N] w1)) ++
      [(4,2,c - 3 + DBu rem)%N] ++ child) in HFinal.
    unfold tail2.
    rewrite HFinal, EPrefixM.
    cbn [app]. f_equal.
    exact (app_assoc (pr ++ phase_form rem)
      [(4,2,c - 3 + DBu rem)%N] child). }
  destruct (sched_tripsc_factor
    (bulk_schedule p rem cs b) T
    POST child f f2 HTrips)
    as (child0 & f0 & HChild & EChild).
  pose proof (runway_scheduled_delivc cs c [] p rem b T POST child0 f f0
    eq_refl HSafe Hp HRem28 Hb HChild) as HRun.
  cbn [app] in HRun.
  change (wcolcost []) with 0%N in HRun.
  replace
    (N.to_nat (28 * N.of_nat (length (c :: cs)) + rem - p))
    with (N.to_nat tk) in HRun.
  2: { f_equal. rewrite HLevels, N2Nat.id, HRem.
       pose proof (N.div_mod' (p+tk) 28). lia. }
  assert (EEnd : sdec
      (phase_form rem ++
        (4,2,c - 3 + DBu rem)%N :: child0) f0 =
      sdec
        (phase_form rem ++
          (4,2,c - 3 + DBu rem)%N :: child) f2).
  { rewrite !sdec_app, !sdec_cons, EChild. reflexivity. }
  pose proof (deliv_sdec_right _ _ _ _ _ _ _ _ EEnd HRun) as HRun2.
  pose proof (deliv_master_creach (N.to_nat tk) _ J pr
    (runway (c :: cs) ++
      phase_form p ++
      (4,2,b + DBu p)%N :: POST)
    (phase_form rem ++
      (4,2,c - 3 + DBu rem)%N :: child) f f2
    (zpre_of_forallb pr HprCols) HJ HRun2) as HSound.
  rewrite N2Nat.id in HSound.
  exists pr, c, b, cs.
  split; [exact HprCols|].
  split; [exact EPrefix|].
  rewrite d_flight_eq.
  eapply creach_sdecode; [| |exact HSound].
  - rewrite HIn. unfold site.
    f_equal; cbn [app]; repeat rewrite app_assoc; cbn [app]; reflexivity.
  - rewrite EFinal. unfold tail2.
    f_equal; cbn [app]; repeat rewrite <- app_assoc; cbn [app]; reflexivity.
Qed.
Lemma one_runway_zero_scheduled_delivc (c : N) (cols : word)
      (b T : N) (post out : word) (f f' : N) :
  delivery_cols cols = true ->
  (1 <= c)%N -> (FLOOR <= b)%N ->
  sched_delivc T (bulk_schedule 0 0 [] b) post f out f' ->
  deliv 28
    (dtransit1 0 b
       (wcolcost (cols ++ rung1 c)) + T)%N
    (cols ++ rung1 c ++ phase_form 0 ++
      (4,2,b + DBu 0)%N :: post) f
    (cols ++ phase_form 0 ++ (4,2,c)%N :: out) f'.
Proof.
  intros HCols Hc Hb HRun.
  rewrite bulk_schedule_nil in HRun.
  change (schedule_slot_nat 0) with 3%nat in HRun.
  change (marks 0) with 0%N in HRun.
  cbn [N.to_nat repeat app] in HRun.
  destruct (sched_delivc_app_inv
    (repeat None 3 ++ [Some (b-1)%N]) [] T post out f f' HRun)
    as (mid & fm & TB & TR & ET & HBlock & HNil).
  cbn [sched_delivc] in HNil. destruct HNil as (ET0 & Emid & Efm).
  subst TR. rewrite N.add_0_r in ET. subst T. subst mid. subst fm.
  destruct (sched_delivc_nones_some 3 (b-1)%N TB post out f f' HBlock)
    as (tail & HDeliver & ->).
  pose proof (transit_delivery_posc cols c 0 b TB post tail f f'
    HCols ltac:(lia) Hc Hb HDeliver) as HTransit.
  change (N.to_nat (28-0)) with 28%nat in HTransit.
  unfold dtransit1.
  change (N.to_nat (27-0)) with 27%nat.
  replace (28-0)%N with 28%N by lia.
  repeat rewrite app_assoc in HTransit |- *.
  exact HTransit.
Qed.
Lemma tick_full_master_scheduled_soundc :
  forall sg J pre c cg rest f sg2 w2 f2 (T : N),
  (1 <= J)%N ->
  (FLOOR <= c)%N ->
  (FLOOR + 3 <= cg)%N ->
  delivery_cols (lin_flat sg pre) = true ->
  scheduled_framec T
    (lin_sched_child (S (length pre)) 0 4 0 28)
    sg
    ((((2,2,J+28)%N::pre) ++ phase_form 0 ++ (4,2,c)%N ::
      rung1 (cg-4)%N) ++ rest)
    f sg2 w2 f2 ->
  creach (d_flight (bsum [(2,2,J)%N]) 28
            (dtransit1 0 (cg-3)
               (wcolcost
                  (lin_flat sg pre ++ rung1 c))
             + T)%N)
    (wconf [] 0 (sdecode (lin_flat sg
      ((((2,2,J)%N::pre) ++ rung1 c ++
        phase_form 0 ++ [(4,2,cg)%N]) ++ rest)) f))
    (wconf [] 0 (sdecode (lin_flat sg2 w2) f2)).
Proof.
  intros sg J pre c cg rest f sg2 w2 f2 T HJ Hc Hcg HCols HFrame.
  set (pr := lin_flat sg pre).
  set (post := lin_flat sg rest).
  set (b := (cg-3)%N).
  set (wout := ((((2,2,J+28)%N::pre) ++ phase_form 0 ++
    (4,2,c)%N :: rung1 (cg-4)%N) ++ rest)).
  set (cur := (S (length pre) + phase_len 0)%nat).
  assert (H0 : (0 < 28)%N) by lia.
  assert (Hcur : cur = (S (length pre) + 2)%nat) by reflexivity.
  assert (Hb : (FLOOR <= b)%N).
  { unfold b, FLOOR in *. lia. }
  assert (EIn : lin_flat sg
      ((((2,2,J)%N::pre) ++ rung1 c ++
        phase_form 0 ++ [(4,2,cg)%N]) ++ rest) =
    (2,2,J)%N :: pr ++ rung1 c ++
      phase_form 0 ++ (4,2,cg)%N :: post).
  { unfold pr, post.
    rewrite !lin_flat_app_c,
      (flat_phase_form sg 0 H0).
    rewrite lin_flat_master.
    cbn [rung1 lin_flat keyb keyi
         phshape gO gZ].
    repeat rewrite <- app_assoc. reflexivity. }
  assert (ESkip : lin_flat sg (skipn cur wout) =
      (4,2,c)%N :: rung1 (cg-4)%N ++ post).
  { unfold wout, post. rewrite Hcur.
    replace (S (length pre) + 2)%nat with
      (length (((2,2,J+28)%N::pre) ++ phase_form 0))%nat.
    2: { rewrite length_app, phase_form_len by lia.
         change (phase_len 0) with 2%nat.
         cbn [length]. reflexivity. }
    replace
      (((((2,2,J+28)%N::pre) ++ phase_form 0 ++
          (4,2,c)%N :: rung1 (cg-4)%N) ++ rest))
      with
      ((((2,2,J+28)%N::pre) ++ phase_form 0) ++
        (((4,2,c)%N :: rung1 (cg-4)%N) ++ rest))
      by (repeat rewrite app_assoc; reflexivity).
    rewrite LineageCascade_skipn_len_app.
    cbn [rung1 lin_flat keyb keyi
         phshape gO gZ]. reflexivity. }
  assert (HView : schedule_frame_view
      (lin_sched_child (S (length pre)) 0 4 0 28)
      (lin_flat sg (skipn cur wout))
      (bulk_schedule 0 0 [] b)
      [(4,2,c)%N] post).
  { unfold schedule_frame_view, lin_sched_child.
    cbv beta zeta. cbn [lsSlot lsTicks lsGap].
    split.
    - unfold lin_sched_slot. lia.
    - split.
      + rewrite (bulk_schedule_length 0 0 [] b)
          by lia.
        reflexivity.
      + split.
        * exact (bulk_schedule_shape 0 0 [] b
            ltac:(lia) ltac:(lia)).
        * split.
          -- unfold delivery_cols, is_col, is_cmf.
             cbn [forallb gO gZ gC].
             destruct ((c =? 1)%N); reflexivity.
          -- split.
             ++ rewrite ESkip, bulk_schedule_stock.
                unfold crossed_post,
                  rung1, b.
                cbn [map app].
                replace (cg - 3 - 1)%N with (cg-4)%N by lia.
                reflexivity.
             ++ rewrite bulk_schedule_stock.
                unfold crossed_post,
                  rung1.
                cbn [map app length]. reflexivity. }
  change (scheduled_framec T
    (lin_sched_child (S (length pre)) 0 4 0 28)
    sg wout f sg2 w2 f2) in HFrame.
  destruct (scheduled_framec_output T
    (lin_sched_child (S (length pre)) 0 4 0 28)
    sg wout f sg2 w2 f2
    (bulk_schedule 0 0 [] b)
    [(4,2,c)%N] post HFrame HView)
    as (child & HTrips & HFinal).
  assert (EPrefix : lin_flat sg (firstn cur wout) =
      (2,2,J+28)%N :: pr ++ phase_form 0).
  { unfold wout. rewrite Hcur.
    replace (S (length pre) + 2)%nat with
      (length ((2,2,J+28)%N::pre) +
        length (phase_form 0))%nat by reflexivity.
    replace
      (((((2,2,J+28)%N::pre) ++ phase_form 0 ++
          (4,2,c)%N :: rung1 (cg-4)%N) ++ rest))
      with
      (((2,2,J+28)%N::pre) ++
        (phase_form 0 ++
          (((4,2,c)%N :: rung1 (cg-4)%N) ++ rest)))
      by (repeat rewrite app_assoc; reflexivity).
    rewrite firstn_prefix_add,
      firstn_len_app, lin_flat_app_c,
      lin_flat_master,
      (flat_phase_form sg 0 H0).
    unfold pr. reflexivity. }
  change (lin_flat sg2 w2 =
    lin_flat sg (firstn cur wout) ++ [(4,2,c)%N] ++ child)
    in HFinal.
  set (tail2 := pr ++ phase_form 0 ++ (4,2,c)%N :: child).
  assert (EFinal : lin_flat sg2 w2 = (2,2,J+28)%N :: tail2).
  { unfold tail2. rewrite HFinal, EPrefix. cbn [app]. f_equal.
    exact (eq_sym (app_assoc pr (phase_form 0)
      ((4,2,c)%N::child))). }
  destruct (sched_tripsc_factor
    (bulk_schedule 0 0 [] b) T
    post child f f2 HTrips) as (child0 & f0 & HChild & EChild).
  pose proof (one_runway_zero_scheduled_delivc
    c pr b T post child0 f f0 HCols
    ltac:(unfold FLOOR in Hc; lia) Hb HChild) as HRun.
  change (DBu 0) with 3%N in HRun.
  replace (b+3)%N with cg in HRun by (unfold b; lia).
  assert (EEnd : sdec
      (pr ++ phase_form 0 ++ (4,2,c)%N :: child0) f0 =
      sdec tail2 f2).
  { unfold tail2.
    pose proof (sdec_prefix_eq
      [(4,2,c)%N] child0 f0 child f2 EChild) as E1.
    cbn [app] in E1.
    pose proof (sdec_prefix_eq
      (phase_form 0) ((4,2,c)%N::child0) f0
      ((4,2,c)%N::child) f2 E1) as E2.
    exact (sdec_prefix_eq pr _ f0 _ f2 E2). }
  pose proof (deliv_sdec_right _ _ _ _ _ _ _ _ EEnd HRun) as HRun2.
  pose proof (deliv_master_creach 28 _ J []
    (pr ++ rung1 c ++ phase_form 0 ++
      (4,2,cg)%N::post)
    tail2 f f2 (Forall_nil _) HJ HRun2) as HSound.
  change (N.of_nat 28) with 28%N in HSound.
  cbn [app] in HSound.
  rewrite EIn, EFinal, d_flight_eq.
  change (N.to_nat 28) with 28%nat.
  exact HSound.
Qed.
Lemma creach_cx_eq_c (a b : N) (u v : Q * tape) :
  a = b -> creach (cx a) u v -> creach (cx b) u v.
Proof. intros <- H. exact H. Qed.
Definition dpartial1 (b W : N) : N := (dladder 0 b 27 + 27 * W)%N.
Lemma tick_partial_master_scheduled_soundc :
  forall sg J pre cg rest f sg2 w2 f2 (T : N),
  (1 <= J)%N ->
  (FLOOR + 3 <= cg)%N ->
  delivery_cols (lin_flat sg pre) = true ->
  scheduled_framec T
    (lin_sched_child (S (length pre)) 27 3 0 27)
    sg
    (((2,2,J+27)%N::pre) ++ phase_form 27 ++
      (4,2,cg-3)%N :: rest)
    f sg2 w2 f2 ->
  creach (d_flight (bsum [(2,2,J)%N]) 27
            (dpartial1 (cg-3)
               (wcolcost (lin_flat sg pre)) + T)%N)
    (wconf [] 0 (sdecode (lin_flat sg
      (((2,2,J)%N::pre) ++ phase_form 0 ++ (4,2,cg)%N::rest)) f))
    (wconf [] 0 (sdecode (lin_flat sg2 w2) f2)).
Proof.
  intros sg J pre cg rest f sg2 w2 f2 T HJ Hcg HCols HFrame.
  set (pr := lin_flat sg pre).
  set (post := lin_flat sg rest).
  set (wout := (((2,2,J+27)%N::pre) ++ phase_form 27 ++
    (4,2,cg-3)%N::rest)).
  set (cur := (S (length pre) + phase_len 27)%nat).
  assert (H27 : (27 < 28)%N) by lia.
  assert (H0 : (0 < 28)%N) by lia.
  assert (Hcur : cur = (S (length pre) + 1)%nat) by reflexivity.
  assert (EIn : lin_flat sg
      (((2,2,J)%N::pre) ++ phase_form 0 ++ (4,2,cg)%N::rest) =
    (2,2,J)%N :: pr ++ phase_form 0 ++ (4,2,cg)%N::post).
  { unfold pr, post.
    rewrite !lin_flat_app_c,
      (flat_phase_form sg 0 H0).
    rewrite lin_flat_master.
    cbn [lin_flat keyb keyi phshape
         gO gZ]. reflexivity. }
  assert (ESkip : lin_flat sg (skipn cur wout) =
      (4,2,cg-3)%N :: post).
  { unfold wout, post. rewrite Hcur.
    replace (S (length pre) + 1)%nat with
      (length (((2,2,J+27)%N::pre) ++ phase_form 27))%nat.
    2: { rewrite length_app, phase_form_len by lia.
         change (phase_len 27) with 1%nat.
         cbn [length]. reflexivity. }
    rewrite app_assoc, LineageCascade_skipn_len_app.
    cbn [lin_flat keyb keyi phshape
         gO gZ]. reflexivity. }
  assert (HView : schedule_frame_view
      (lin_sched_child (S (length pre)) 27 3 0 27)
      (lin_flat sg (skipn cur wout))
      (partial_schedule 0 27)
      [(4,2,cg-3)%N] post).
  { unfold schedule_frame_view, lin_sched_child.
    cbv beta zeta. cbn [lsSlot lsTicks lsGap].
    repeat split.
    - unfold lin_sched_slot. lia.
    - unfold delivery_cols, is_col, is_cmf.
      cbn [forallb gO gZ gC].
      destruct ((cg-3 =? 1)%N); reflexivity.
    - rewrite ESkip, partial_schedule_stock.
      cbn [app]. reflexivity. }
  change (scheduled_framec T
    (lin_sched_child (S (length pre)) 27 3 0 27)
    sg wout f sg2 w2 f2) in HFrame.
  destruct (scheduled_framec_output T
    (lin_sched_child (S (length pre)) 27 3 0 27)
    sg wout f sg2 w2 f2
    (partial_schedule 0 27)
    [(4,2,cg-3)%N] post HFrame HView)
    as (child & HTrips & HFinal).
  assert (EPrefix : lin_flat sg (firstn cur wout) =
      (2,2,J+27)%N :: pr ++ phase_form 27).
  { unfold wout. rewrite Hcur.
    replace (S (length pre) + 1)%nat with
      (length ((2,2,J+27)%N::pre) +
        length (phase_form 27))%nat by reflexivity.
    rewrite firstn_prefix_add,
      firstn_len_app, lin_flat_app_c,
      lin_flat_master,
      (flat_phase_form sg 27 H27).
    unfold pr. reflexivity. }
  change (lin_flat sg2 w2 =
    lin_flat sg (firstn cur wout) ++ [(4,2,cg-3)%N] ++ child)
    in HFinal.
  set (tail2 := pr ++ phase_form 27 ++ (4,2,cg-3)%N :: child).
  assert (EFinal : lin_flat sg2 w2 = (2,2,J+27)%N :: tail2).
  { unfold tail2. rewrite HFinal, EPrefix. cbn [app]. f_equal.
    exact (eq_sym (app_assoc pr (phase_form 27)
      ((4,2,cg-3)%N::child))). }
  set (b := (cg-3)%N).
  assert (Hb : (FLOOR <= b)%N).
  { unfold b, FLOOR in *. lia. }
  destruct (sched_tripsc_factor
    (partial_schedule 0 27) T post child f f2 HTrips)
    as (child0 & f0 & HChild & EChild).
  unfold partial_schedule in HChild.
  pose proof (sched_delivc_nones _ T post child0 f f0 HChild) as HDown.
  assert (HDown' : deliv
      (N.to_nat (marks (0 + N.of_nat 27) - marks 0))
      T post f child0 f0).
  { change (0 + N.of_nat 27)%N with (0 + 27)%N. exact HDown. }
  pose proof (phase_ticks_delivc 27 0 b T post child0 f f0
    ltac:(change (N.of_nat 27) with 27%N; lia) Hb HDown') as HPhase.
  change (0 + N.of_nat 27)%N with 27%N in HPhase.
  change (DBu 0) with 3%N in HPhase.
  change (DBu 27) with 0%N in HPhase.
  replace (b+3)%N with cg in HPhase by (unfold b; lia).
  replace (b+0)%N with b in HPhase by lia.
  pose proof (deliv_cols 27 _ pr _ _ f f0 HCols HPhase) as HRun.
  change (N.of_nat 27) with 27%N in HRun.
  assert (EEnd : sdec
      (pr ++ phase_form 27 ++ (4,2,b)%N :: child0) f0 =
      sdec tail2 f2).
  { unfold tail2, b.
    pose proof (sdec_prefix_eq
      (phase_form 27) ((4,2,cg-3)%N::child0) f0
      ((4,2,cg-3)%N::child) f2
      (sdec_prefix_eq [(4,2,cg-3)%N] child0 f0 child f2
         EChild)) as E2.
    exact (sdec_prefix_eq pr _ f0 _ f2 E2). }
  pose proof (deliv_sdec_right _ _ _ _ _ _ _ _ EEnd HRun) as HRun2.
  pose proof (deliv_master_creach 27 _ J []
    (pr ++ phase_form 0 ++ (4,2,cg)%N::post)
    tail2 f f2 (Forall_nil _) HJ HRun2) as HSound.
  change (N.of_nat 27) with 27%N in HSound.
  cbn [app] in HSound.
  rewrite EIn, EFinal, d_flight_eq.
  change (N.to_nat 27) with 27%nat.
  unfold dpartial1.
  refine (creach_cx_eq_c _ _ _ _ _ HSound).
  change (@nil bg) with (@nil (N*N*N)%type). lia.
Qed.
Lemma scheduled_framec_zero (cur : nat) (slot : N) (gap : nat)
      (sg : list seg) (w : word) (f : N) :
  scheduled_framec 0%N
    {| lsCur := cur; lsTicks := 0;
       lsSlot := slot; lsGap := gap |}
    sg w f sg w f.
Proof.
  split; [intros; reflexivity|].
  intros rs base tail (HSlot & HLen & HShape & HCols & HLayout & HGap).
  cbn [lsTicks N.to_nat] in HLen.
  apply length_zero_iff_nil in HLen. subst rs.
  cbn [schedule_stock app] in HLayout.
  rewrite app_nil_r in HLayout.
  exists tail. split; [cbn [sched_tripsc]; auto|exact HLayout].
Qed.
Definition cdrop6 (d : cost) : cost :=
  if andb (6 <=? clo d)%N (6 <=? chi d)%N
  then ((clo d - 6)%N, (chi d - 6)%N)
  else cundef.
Lemma cdrop6_cundef : cdrop6 cundef = cundef.
Proof. reflexivity. Qed.
Lemma cin_cdrop6 (k : nat) (d : cost) :
  cin k (cdrop6 d) -> cin (k + 6) d.
Proof.
  intros H. unfold cdrop6 in H.
  destruct (andb (6 <=? clo d)%N (6 <=? chi d)%N) eqn:EG.
  - apply andb_prop in EG. destruct EG as (E1 & E2).
    apply N.leb_le in E1, E2.
    unfold cin, clo, chi in *; cbn [fst snd] in *.
    rewrite Nat2N.inj_add. change (N.of_nat 6) with 6%N. lia.
  - destruct (cin_cundef k H).
Qed.
Definition cleaf_lift (cols2 s3 : word) (f : N)
  : option (word * N) * cost :=
  match fst (cleaf_act s3 f) with
  | Some (s3', f2) =>
      (Some (cols2 ++ s3', f2),
       cadd (cx (ccolcost cols2))
                 (cdrop6 (snd (cleaf_act s3 f))))
  | None => (None, cundef)
  end.
Definition cdtick_after_seek (cols2 s3 : word) (f : N)
  : option (word * N) * cost :=
  match fst (crenew_seg (length s3) cols2 s3 f) with
  | Some (body, f2) =>
      (Some (body, f2),
       snd (crenew_seg (length s3) cols2 s3 f))
  | None =>
      match s3 with
      | (o7,z7,c7) :: _ =>
          if ((z7 =? 3) && (c7 =? 1))%N
          then match fst (cfire_comp (length s3) s3 f) with
               | Some (s3', f2) =>
                   (Some (cols2 ++ s3', f2),
                    cadd (cx (ccolcost cols2))
                              (snd (cfire_comp (length s3) s3 f)))
               | None => (None, cundef)
               end
          else if sand_leaf s3 then (None, cundef)
          else cleaf_lift cols2 s3 f
      | [] => cleaf_lift cols2 s3 f
      end
  end.
Lemma cdtick_after_seek_proj (cols2 s3 : word) (f : N) :
  fst (cdtick_after_seek cols2 s3 f)
  = dtick_after_seek cols2 s3 f.
Proof.
  unfold cdtick_after_seek, dtick_after_seek, cleaf_lift.
  rewrite <- (crenew_seg_proj (length s3) cols2 s3 f).
  destruct (fst (crenew_seg (length s3) cols2 s3 f)) as [[body f2]|];
    [reflexivity|].
  destruct s3 as [|[[o7 z7] c7] t3].
  - rewrite <- (cleaf_act_proj [] f).
    destruct (fst (cleaf_act [] f)) as [[s3' f2]|]; reflexivity.
  - destruct (((z7 =? 3) && (c7 =? 1))%N).
    + match goal with
      | |- context [ cfire_comp ?a ?b ?c ] =>
          rewrite <- (cfire_comp_proj a b c)
      end.
      match goal with
      | |- context [ fst (cfire_comp ?a ?b ?c) ] =>
          destruct (fst (cfire_comp a b c)) as [[s3' f2]|]
      end; reflexivity.
    +
      match goal with
      | |- context [ sand_leaf ?a ] => destruct (sand_leaf a)
      end; [reflexivity|].
      match goal with
      | |- context [ cleaf_act ?a ?b ] =>
          rewrite <- (cleaf_act_proj a b)
      end.
      match goal with
      | |- context [ fst (cleaf_act ?a ?b) ] =>
          destruct (fst (cleaf_act a b)) as [[s3' f2]|]
      end; reflexivity.
Qed.
Lemma cleaf_lift_tripc (cols s : word) (f : N)
      (out : word) (f' : N) (k : nat) :
  forallb (fun g => is_col g && negb (is_cmf g)
                    && (3 <=? gO g)%N) cols = true ->
  sand_leaf s = false ->
  fst (cleaf_lift cols s f) = Some (out, f') ->
  cin k (snd (cleaf_lift cols s f)) ->
  delivery_tripc (N.of_nat k) (cols ++ s) f out f'.
Proof.
  intros HC HSL HR Hk. unfold cleaf_lift in HR, Hk.
  destruct (fst (cleaf_act s f)) as [[s3' f2]|] eqn:ELA;
    cbn [fst snd] in HR, Hk; [|discriminate HR].
  injection HR as <- <-.
  destruct (cin_cadd_cx_split _ _ _ Hk) as (kd & EK & Hkd).
  pose proof (cin_cdrop6 _ _ Hkd) as Hkl.
  assert (ESP : cleaf_act s f
                = (Some (s3', f2), snd (cleaf_act s f)))
    by (rewrite <- ELA; apply surjective_pairing).
  destruct (leaf_ftripC s f s3' f2 _ _ ESP Hkl)
    as [(ci & pi & qi & K & EKK & HFi & EQi)
       |(ci & pi & qi & K & EKK & HSi & EQq & HSand & _)].
  2:{ rewrite HSand in HSL. discriminate HSL. }
  assert (EKN : K = N.of_nat kd)
    by (rewrite Nat2N.inj_add in EKK;
        change (N.of_nat 6) with 6%N in EKK; lia).
  subst K.
  destruct (ren_liftc cols s s3' f f2 ci pi (N.of_nat kd) qi
              HC HFi EQi) as (c2 & p2 & q2 & HF2 & EQ2).
  exists c2, p2, q2. split; [|exact EQ2].
  refine (FTripC_cost_eq _ _ _ _ _ _ _ HF2).
  pose proof (ccolcost_wcolcost cols) as EW. lia.
Qed.
Lemma dtick_after_seek_tripc (cols s : word) (f : N)
      (out : word) (f' : N) (k : nat) :
  forallb (fun g => is_col g && negb (is_cmf g)
                    && (3 <=? gO g)%N) cols = true ->
  fst (cdtick_after_seek cols s f) = Some (out, f') ->
  cin k (snd (cdtick_after_seek cols s f)) ->
  delivery_tripc (N.of_nat k) (cols ++ s) f out f'.
Proof.
  intros HC HR Hk. unfold cdtick_after_seek in HR, Hk.
  destruct (fst (crenew_seg (length s) cols s f))
    as [[body f2]|] eqn:ERS.
  { cbn [fst snd] in HR, Hk. injection HR as <- <-.
    assert (ESP : crenew_seg (length s) cols s f
                  = (Some (body, f2),
                     snd (crenew_seg (length s) cols s f)))
      by (rewrite <- ERS; apply surjective_pairing).
    exact (renew_ftripc leaf_ftripC (length s) cols s f
             body f2 _ k HC ESP Hk). }
  destruct s as [|[[o7 z7] c7] t3].
  { exact (cleaf_lift_tripc cols [] f out f' k HC eq_refl HR Hk). }
  destruct (((z7 =? 3) && (c7 =? 1))%N) eqn:EZ7.
  { match type of HR with
    | context [ fst (cfire_comp ?a ?b ?c) ] =>
        destruct (fst (cfire_comp a b c)) as [[s3' f2]|] eqn:EFC
    end;
      cbn [fst snd] in HR, Hk; [|discriminate HR].
    injection HR as <- <-.
    match type of EFC with
    | fst ?X = _ => pose proof (surjective_pairing X) as ESP
    end.
    rewrite EFC in ESP.
    destruct (cin_cadd_cx_split _ _ _ Hk) as (k3 & EK & Hk3).
    destruct (fire_comp_ftripc leaf_ftripC _ _ f s3' f2
                _ k3 ESP Hk3) as (ci & pi & qi & HFi & EQi).
    destruct (ren_liftc cols ((o7,z7,c7)%N :: t3) s3' f f2
                ci pi (N.of_nat k3) qi HC HFi EQi)
      as (c2 & p2 & q2 & HF2 & EQ2).
    exists c2, p2, q2. split; [|exact EQ2].
    refine (FTripC_cost_eq _ _ _ _ _ _ _ HF2).
    pose proof (ccolcost_wcolcost cols) as EW. lia. }
  match type of HR with
  | context [ sand_leaf ?a ] => destruct (sand_leaf a) eqn:ESL
  end;
    [cbn [fst snd] in HR; discriminate HR|].
  exact (cleaf_lift_tripc cols ((o7,z7,c7)%N :: t3) f out f' k
           HC ESL HR Hk).
Qed.
Set Warnings "require-in-module".
Local Open Scope nat_scope.
Local Open Scope sym.
Local Open Scope list.
Opaque LROUND_FUEL LROUND_CHUNKS
       FLAT_ROUND_FUEL CFUEL TRIES.
Opaque FUEL.
Opaque deliver_tick fire renewal chain_merge_advance.
Opaque fire_comp leaf_act debris_to_blank.
Opaque renew_seg.
Definition caddx (a b : cost) : cost :=
  if andb (clo a =? chi a)%N (clo b =? chi b)%N
  then cadd a b else cundef.
Lemma caddx_cx (a b : N) : caddx (cx a) (cx b) = cx (a + b)%N.
Proof.
  unfold caddx, cx, clo, chi, cadd; cbn [fst snd].
  rewrite !N.eqb_refl; cbn [andb]. reflexivity.
Qed.
Lemma caddx_czero_r (a : N) : caddx (cx a) czero = cx a.
Proof.
  change czero with (cx 0%N). rewrite caddx_cx.
  f_equal. lia.
Qed.
Lemma caddx_cx_inv (a b : cost) (T : N) :
  caddx a b = cx T ->
  exists Ta Tb, a = cx Ta /\ b = cx Tb /\ T = (Ta + Tb)%N.
Proof.
  unfold caddx. intros H.
  destruct (andb (clo a =? chi a)%N
                 (clo b =? chi b)%N) eqn:EG.
  - apply andb_prop in EG. destruct EG as (E1 & E2).
    apply N.eqb_eq in E1, E2.
    exists (clo a), (clo b).
    unfold clo, chi in *.
    split; [rewrite (surjective_pairing a) at 1; unfold cx;
            rewrite <- E1; reflexivity|].
    split; [rewrite (surjective_pairing b) at 1; unfold cx;
            rewrite <- E2; reflexivity|].
    unfold cadd, cx in H.
    injection H as HA HB. lia.
  - unfold cundef, cx in H. injection H as HA HB. lia.
Qed.
Fixpoint clin_bottom_sched_zrun (q lc : nat) (sg : list seg)
          (lw : word) (f : N) (gap : nat) (slot : N)
  : option (word * N) * cost :=
  if lin_literal_word lw then
  match q with
  | O => (Some (lw, f), czero)
  | S q' =>
      let sf := skipn lc lw in
      let '(cols, s3) := seek sf in
      match s3 with
      | [] => (None, cundef)
      | _ :: _ =>
          match lin_dtick_after_seek cols s3 f with
          | Some (renewed, sfx, f2) =>
              if renewed then
                if negb (Nat.leb (gap + 2) (lin_flen sg cols))
                then (None, cundef) else
                match (if Nat.eqb lc O then Some sfx
                       else lin_join_safe sg (firstn lc lw) sfx) with
                | Some lw2 =>
                    let r := clin_bottom_sched_zrun q' lc sg lw2 f2
                               (gap - 2 * N.to_nat
                                  (lin_sched_grant_one slot))%nat
                               (lin_sched_slot_advance_one slot) in
                    (fst r,
                     caddx (snd (cdtick_after_seek
                                   (skipn gap cols) s3 f)) (snd r))
                | None => (None, cundef)
                end
              else
                match (if Nat.eqb lc O then Some sfx
                       else lin_join_safe sg (firstn lc lw) sfx) with
                | Some lw2 =>
                    let r := clin_bottom_sched_zrun q' lc sg lw2 f2
                               (gap - 2 * N.to_nat
                                  (lin_sched_grant_one slot))%nat
                               (lin_sched_slot_advance_one slot) in
                    (fst r,
                     caddx (snd (cdtick_after_seek
                                   (skipn gap cols) s3 f)) (snd r))
                | None => (None, cundef)
                end
          | None => (None, cundef)
          end
      end
  end
  else (None, cundef).
Lemma clin_bottom_sched_zrun_proj (q : nat) :
  forall lc sg lw f gap slot,
  fst (clin_bottom_sched_zrun q lc sg lw f gap slot)
  = lin_bottom_sched_zrun q lc sg lw f gap slot.
Proof.
  induction q as [|q IH]; intros lc sg lw f gap slot;
    cbn [clin_bottom_sched_zrun lin_bottom_sched_zrun];
    destruct (lin_literal_word lw); try reflexivity.
  destruct (seek (skipn lc lw)) as [cols s3] eqn:ESeek.
  destruct s3 as [|g t]; [reflexivity|].
  destruct (lin_dtick_after_seek cols (g :: t) f)
    as [[[renewed sfx] f2]|]; [|reflexivity].
  destruct renewed.
  - destruct (negb (Nat.leb (gap + 2) (lin_flen sg cols)));
      [reflexivity|].
    destruct (if Nat.eqb lc O then Some sfx
              else lin_join_safe sg (firstn lc lw) sfx) as [lw2|];
      [|reflexivity].
    cbn [fst]. apply IH.
  - destruct (if Nat.eqb lc O then Some sfx
              else lin_join_safe sg (firstn lc lw) sfx) as [lw2|];
      [|reflexivity].
    cbn [fst]. apply IH.
Qed.
Lemma clin_bottom_sched_zrun_S_inv :
  forall q lc sg lw f gap slot lw' f' (d : cost),
  clin_bottom_sched_zrun (S q) lc sg lw f gap slot = (Some (lw', f'), d) ->
  exists cols g t renewed sfx f2 lw2 d2,
    lin_literal_word lw = true /\
    seek (skipn lc lw) = (cols, g :: t) /\
    lin_dtick_after_seek cols (g :: t) f
      = Some (renewed, sfx, f2) /\
    (renewed = true -> (gap + 2 <= lin_flen sg cols)%nat) /\
    (if Nat.eqb lc O then Some sfx
     else lin_join_safe sg (firstn lc lw) sfx) = Some lw2 /\
    clin_bottom_sched_zrun q lc sg lw2 f2
      (gap - 2 * N.to_nat (lin_sched_grant_one slot))%nat
      (lin_sched_slot_advance_one slot) = (Some (lw', f'), d2) /\
    d = caddx (snd (cdtick_after_seek
                      (skipn gap cols) (g :: t) f)) d2.
Proof.
  intros q lc sg lw f gap slot lw' f' d HRun.
  cbn [clin_bottom_sched_zrun] in HRun.
  destruct (lin_literal_word lw) eqn:ELit;
    [|injection HRun as HR _; discriminate HR].
  destruct (seek (skipn lc lw)) as [cols s] eqn:ESeek.
  destruct s as [|g t]; [injection HRun as HR _; discriminate HR|].
  destruct (lin_dtick_after_seek cols (g :: t) f)
    as [[[renewed sfx] f2]|] eqn:EStep;
    [|injection HRun as HR _; discriminate HR].
  destruct renewed.
  - destruct (negb (Nat.leb (gap + 2) (lin_flen sg cols)))
      eqn:EGuard; [injection HRun as HR _; discriminate HR|].
    destruct (if Nat.eqb lc O then Some sfx
              else lin_join_safe sg (firstn lc lw) sfx)
      as [lw2|] eqn:EJoin; [|injection HRun as HR _; discriminate HR].
    destruct (clin_bottom_sched_zrun q lc sg lw2 f2
               (gap - 2 * N.to_nat (lin_sched_grant_one slot))%nat
               (lin_sched_slot_advance_one slot))
      as [r1 r2] eqn:ER.
    injection HRun as HR HD. cbn [fst snd] in HR, HD.
    exists cols, g, t. exists true. exists sfx, f2, lw2. exists r2.
    repeat split; try assumption.
    + intros _. apply negb_false_iff in EGuard.
      apply PeanoNat.Nat.leb_le. exact EGuard.
    + rewrite ER, HR. reflexivity.
    + symmetry. exact HD.
  - destruct (if Nat.eqb lc O then Some sfx
              else lin_join_safe sg (firstn lc lw) sfx)
      as [lw2|] eqn:EJoin; [|injection HRun as HR _; discriminate HR].
    destruct (clin_bottom_sched_zrun q lc sg lw2 f2
               (gap - 2 * N.to_nat (lin_sched_grant_one slot))%nat
               (lin_sched_slot_advance_one slot))
      as [r1 r2] eqn:ER.
    injection HRun as HR HD. cbn [fst snd] in HR, HD.
    exists cols, g, t. exists false. exists sfx, f2, lw2. exists r2.
    repeat split; try assumption.
    + discriminate.
    + rewrite ER, HR. reflexivity.
    + symmetry. exact HD.
Qed.
Lemma sched_tripsc_sdec_left (rs : list (option N)) (T : N)
      (w0 w out : word) (f0 f f' : N) :
  sdec w f = sdec w0 f0 ->
  sched_tripsc T rs w0 f0 out f' ->
  sched_tripsc T rs w f out f'.
Proof.
  intros E H. destruct rs as [|o r].
  - destruct H as (-> & E2). split; [reflexivity|].
    rewrite E. exact E2.
  - destruct H as (K & T1 & w1 & f1 & ET & HD & HR).
    exists K, T1, w1, f1. split; [exact ET|]. split; [|exact HR].
    exact (delivery_tripc_sdec_left K w w0 w1 f f0 f1 E HD).
Qed.
Lemma sched_tripsc_app (a : list (option N)) :
  forall (b : list (option N)) (Ta Tb : N)
         (w mid out : word) (f fm f' : N),
  sched_tripsc Ta a w f mid fm ->
  sched_tripsc Tb b mid fm out f' ->
  sched_tripsc (Ta + Tb)%N (a ++ b) w f out f'.
Proof.
  induction a as [|o a IH]; intros b Ta Tb w mid out f fm f' HA HB.
  - destruct HA as (-> & E). cbn [app].
    rewrite N.add_0_l.
    exact (sched_tripsc_sdec_left b Tb mid w out fm f f' E HB).
  - destruct HA as (K & T1 & w1 & f1 & -> & HD & HR).
    cbn [app]. exists K, (T1 + Tb)%N, w1, f1.
    split; [lia|]. split; [exact HD|].
    exact (IH b T1 Tb (sd_next o w1) mid out f1 fm f' HR HB).
Qed.
Lemma sched_tripsc_one (oc : option N) (K : N)
      (tail body : word) (f f2 : N) :
  delivery_tripc K tail f body f2 ->
  sched_tripsc K [oc] tail f (schedule_release oc body) f2.
Proof.
  intros HD. exists K, 0%N, body, f2.
  split; [lia|]. split; [exact HD|].
  cbn [sched_tripsc]. split; [reflexivity|].
  destruct oc as [c|]; reflexivity.
Qed.
Lemma clin_bottom_sched_zrun_schedule (q : nat) :
  forall fr sg lw f lw' f' (T : N),
  sg_wf sg ->
  (lsCur fr <= length lw)%nat ->
  (N.of_nat q <= lsTicks fr)%N ->
  clin_bottom_sched_zrun q (lsCur fr) sg lw f
    (lsGap fr) (lsSlot fr) = (Some (lw', f'), cx T) ->
  forall prs base tail,
  schedule_frame_view fr
    (skipn (lsCur fr) lw) prs base tail ->
  exists used rest tail',
    prs = used ++ rest /\
    length used = q /\
    sched_tripsc T used tail f tail' f' /\
    (forall i, (i <= lsCur fr)%nat ->
      firstn i lw = firstn i lw') /\
    skipn (lsCur fr) lw' =
      (base ++ schedule_stock rest) ++ tail'.
Proof.
  induction q as [|q IH];
    intros fr sg lw f lw' f' T HW HCur HQt HRun prs base tail HView.
  - cbn [clin_bottom_sched_zrun] in HRun.
    destruct (lin_literal_word lw);
      [|injection HRun as HR _; discriminate HR].
    pose proof (f_equal fst HRun) as HRes.
    pose proof (f_equal snd HRun) as HCst.
    cbn [fst snd] in HRes, HCst.
    injection HRes as <- <-.
    unfold czero, cx in HCst. injection HCst as HT HT2.
    destruct HView as (_ & _ & _ & _ & HFrame & _).
    exists (@nil (option N)), prs, tail.
    split; [reflexivity|]. split; [reflexivity|].
    split.
    + cbn [sched_tripsc]. split; [symmetry; exact HT|reflexivity].
    + split; [intros; reflexivity|]. exact HFrame.
  - destruct (clin_bottom_sched_zrun_S_inv q
      (lsCur fr) sg lw f (lsGap fr)
      (lsSlot fr) lw' f' _ HRun)
      as (cols & g & t & renewed & sfx & f2 & lw2 & d2 & HLit & ESeek &
          EStep & HRenew & EJoin & HRestRun & HCost).
    destruct (caddx_cx_inv _ _ _ (eq_sym HCost)) as (K & T1 & EK & ED2 & ET).
    rewrite lin_sched_grant_one_eq,
      lin_sched_slot_advance_one_eq in HRestRun.
    destruct HView as
      (HSlot & HLen & HShape & HBaseCols & HFrame & HGap).
    destruct prs as [|oc rs].
    { cbn [length] in HLen. apply (f_equal N.of_nat) in HLen.
      rewrite N2Nat.id in HLen. cbn [N.of_nat] in HLen. lia. }
    assert (HMidCols : delivery_cols
        (base ++ schedule_stock (oc :: rs)) = true).
    { rewrite delivery_cols_app, HBaseCols,
        schedule_stock_cols. reflexivity. }
    assert (ESeekFrame :
        seek ((base ++ schedule_stock (oc :: rs)) ++
          tail) = (cols, g :: t)).
    { rewrite <- HFrame. exact ESeek. }
    rewrite (seek_app_delivery_cols
      (base ++ schedule_stock (oc :: rs)) tail HMidCols)
      in ESeekFrame.
    destruct (seek tail) as [avail tail0] eqn:ETailSeek.
    cbn [fst snd] in ESeekFrame.
    pose proof (f_equal fst ESeekFrame) as ECols0.
    pose proof (f_equal snd ESeekFrame) as ETail0.
    cbn [fst snd] in ECols0, ETail0.
    assert (ECols : cols =
        (base ++ schedule_stock (oc :: rs)) ++ avail)
      by (symmetry; exact ECols0).
    destruct (seek_split tail avail tail0 ETailSeek)
      as (ETailSplit & HAvailCols).
    assert (ETail : tail = avail ++ g :: t).
    { rewrite ETailSplit, ETail0. reflexivity. }
    assert (HLitCols : lin_literal_word cols = true).
    { pose proof (literal_word_skipn
        (lsCur fr) lw HLit) as HS.
      pose proof (seek_split (skipn (lsCur fr) lw)
        cols (g :: t) ESeek) as [ESplit _].
      rewrite ESplit in HS.
      exact (literal_word_app_l cols (g::t) HS). }
    rewrite ECols in EStep.
    assert (HRenewAvail : renewed = true -> (2 <= length avail)%nat).
    { intro ER. specialize (HRenew ER).
      rewrite (lin_flen_flat_wf sg cols HW) in HRenew.
      rewrite (literal_word_flat sg cols HLitCols), ECols
        in HRenew.
      rewrite length_app, HGap in HRenew. lia. }
    destruct (schedule_step_strip
      oc rs base avail (g :: t) f renewed sfx f2 EStep HRenewAvail)
      as (body & HBody & EBody).
    assert (EAvail : skipn (lsGap fr) cols = avail).
    { rewrite ECols, <- HGap.
      apply LineageCascade_skipn_len_app. }
    assert (HGuardAvail :
      forallb (fun gg => is_col gg && negb (is_cmf gg)
                         && (3 <=? gO gg)%N) avail = true)
      by exact HAvailCols.
    assert (HBodyC : fst (cdtick_after_seek avail (g :: t) f)
                     = Some (body, f2)).
    { rewrite cdtick_after_seek_proj.
      exact (lin_dtick_after_seek_proj
               avail (g :: t) f renewed body f2 HBody). }
    assert (HkIn : cin (N.to_nat K)
             (snd (cdtick_after_seek avail (g :: t) f))).
    { rewrite <- EAvail, EK. apply cin_cx. }
    pose proof (dtick_after_seek_tripc avail (g :: t) f body f2
      (N.to_nat K) HGuardAvail HBodyC HkIn) as HTripc0.
    rewrite N2Nat.id in HTripc0.
    assert (HTripc : delivery_tripc K tail f body f2)
      by (rewrite ETail; exact HTripc0).
    pose proof (sched_tripsc_one oc K tail body f f2 HTripc) as HOneTrips.
    assert (EW2 : lw2 = firstn (lsCur fr) lw ++ sfx).
    { destruct (Nat.eqb (lsCur fr) O) eqn:ECur.
      - apply PeanoNat.Nat.eqb_eq in ECur. injection EJoin as <-.
        rewrite ECur. reflexivity.
      - exact (lin_join_safe_some _ _ _ _ EJoin). }
    assert (HStepPrefix : forall i, (i <= lsCur fr)%nat ->
        firstn i lw = firstn i lw2).
    { intros i Hi. rewrite EW2.
      assert (HFirstLen : length (firstn (lsCur fr) lw) =
          lsCur fr) by (rewrite length_firstn; lia).
      rewrite (firstn_app_left _ i
        (firstn (lsCur fr) lw)
        sfx ltac:(rewrite HFirstLen; exact Hi)).
      rewrite firstn_firstn, PeanoNat.Nat.min_l by exact Hi. reflexivity. }
    assert (EOutSuffix : skipn (lsCur fr) lw2 =
        (base ++ schedule_stock rs) ++
          schedule_release oc body).
    { rewrite EW2.
      assert (HFirstLen : length (firstn (lsCur fr) lw) =
          lsCur fr) by (rewrite length_firstn; lia).
      replace (lsCur fr) with
        (length (firstn (lsCur fr) lw)) at 1 by exact HFirstLen.
      rewrite LineageCascade_skipn_len_app, EBody. reflexivity. }
    pose proof (schedule_frame_view_advance_one
      fr (skipn (lsCur fr) lw) oc rs base tail body
      (conj HSlot (conj HLen (conj HShape
        (conj HBaseCols (conj HFrame HGap)))))) as HAdvance0.
    assert (HAdvance : schedule_frame_view
        (lin_sched_advance fr 1)
        (skipn (lsCur fr) lw2) rs base
        (schedule_release oc body)).
    { rewrite EOutSuffix. exact HAdvance0. }
    assert (HCur2 : (lsCur (lin_sched_advance fr 1) <=
        length lw2)%nat).
    { cbn [lin_sched_advance lsCur]. rewrite EW2.
      rewrite length_app, length_firstn. lia. }
    assert (HQt2 : (N.of_nat q <=
        lsTicks (lin_sched_advance fr 1))%N).
    { cbn [lin_sched_advance lsTicks].
      rewrite Nat2N.inj_succ in HQt. lia. }
    assert (HRestRunC : clin_bottom_sched_zrun q
        (lsCur (lin_sched_advance fr 1)) sg lw2 f2
        (lsGap (lin_sched_advance fr 1))
        (lsSlot (lin_sched_advance fr 1))
        = (Some (lw', f'), cx T1)).
    { cbn [lin_sched_advance lsCur lsGap
           lsSlot].
      rewrite <- ED2. exact HRestRun. }
    destruct (IH (lin_sched_advance fr 1) sg lw2 f2 lw' f' T1
      HW HCur2 HQt2 HRestRunC rs base
      (schedule_release oc body) HAdvance)
      as (used & rest & tail' & ERs & HUsed & HTrips & HRecPrefix & HOut).
    exists (oc :: used), rest, tail'.
    split; [rewrite ERs; reflexivity|]. split; [cbn [length]; lia|].
    split.
    + change (sched_tripsc T ([oc] ++ used) tail f tail' f').
      rewrite ET.
      exact (sched_tripsc_app [oc] used K T1 tail
               (schedule_release oc body) tail'
               f f2 f' HOneTrips HTrips).
    + split.
      * intros i Hi. rewrite (HStepPrefix i Hi).
        apply HRecPrefix. cbn [lin_sched_advance lsCur].
        exact Hi.
      * exact HOut.
Qed.
Definition scheduled_transitionc (T : N) (fr : lsc_frame) (take : N)
    (sg : list seg) (w : word) (f : N)
    (sg' : list seg) (w' : word) (f' : N) : Prop :=
  (forall i, (i <= lsCur fr)%nat ->
    lin_flat sg (firstn i w) =
      lin_flat sg' (firstn i w')) /\
  forall prs base tail,
    schedule_frame_view fr
      (lin_flat sg (skipn (lsCur fr) w))
      prs base tail ->
    exists used rest tail',
      prs = used ++ rest /\
      length used = N.to_nat take /\
      sched_tripsc T used tail f tail' f' /\
      schedule_frame_view
        (lin_sched_advance fr take)
        (lin_flat sg' (skipn (lsCur fr) w'))
        rest base tail'.
Lemma scheduled_transitionc_transition (T : N) fr take sg w f sg' w' f' :
  scheduled_transitionc T fr take sg w f sg' w' f' ->
  scheduled_transition fr take sg w f sg' w' f'.
Proof.
  intros (HP & HS). split; [exact HP|].
  intros prs base tail HView.
  destruct (HS prs base tail HView)
    as (used & rest & tail' & EPrs & HUsed & HTrips & HView').
  exists used, rest, tail'.
  split; [exact EPrs|]. split; [exact HUsed|].
  split; [exact (sched_tripsc_proj _ _ _ _ _ _ HTrips)|exact HView'].
Qed.
Lemma scheduled_transition_framec :
  forall (T1 T2 : N) fr take sg w f sg1 w1 f1 sg2 w2 f2,
  scheduled_transitionc T1 fr take sg w f sg1 w1 f1 ->
  scheduled_framec T2 (lin_sched_advance fr take)
    sg1 w1 f1 sg2 w2 f2 ->
  scheduled_framec (T1 + T2)%N fr sg w f sg2 w2 f2.
Proof.
  intros T1 T2 fr take sg w f sg1 w1 f1 sg2 w2 f2
    (HP & HStep) (HP2 & HFrame). split.
  - intros i Hi. rewrite (HP i Hi).
    apply HP2. cbn [lin_sched_advance lsCur]. exact Hi.
  - intros prs base tail HView.
    destruct (HStep prs base tail HView)
      as (used & rest & tail1 & EPrs & HUsed & HTrips & HView1).
    assert (HView1' : schedule_frame_view
        (lin_sched_advance fr take)
        (lin_flat sg1
           (skipn (lsCur (lin_sched_advance fr take)) w1))
        rest base tail1)
      by (cbn [lin_sched_advance lsCur]; exact HView1).
    destruct (HFrame rest base tail1 HView1')
      as (tail2 & HTrips2 & HOut).
    exists tail2. split.
    + rewrite EPrs.
      exact (sched_tripsc_app used rest T1 T2 tail tail1 tail2
               f f1 f2 HTrips HTrips2).
    + cbn [lin_sched_advance lsCur] in HOut. exact HOut.
Qed.
Lemma scheduled_framec_zero' (fr : lsc_frame)
      (sg : list seg) (w : word) (f : N) :
  lsTicks fr = 0%N -> scheduled_framec 0%N fr sg w f sg w f.
Proof.
  destruct fr as [cur tk slot gap]. cbn [lsTicks]. intros ->.
  apply scheduled_framec_zero.
Qed.
Lemma clin_bottom_local_scheduled_transitionc :
  forall take fr sg lw f lw' f' (T : N),
  sg_wf sg ->
  (lsCur fr <= length lw)%nat ->
  (take <= lsTicks fr)%N ->
  clin_bottom_sched_zrun (N.to_nat take)
    (lsCur fr) sg lw f (lsGap fr) (lsSlot fr)
    = (Some (lw', f'), cx T) ->
  scheduled_transitionc T fr take sg lw f sg lw' f'.
Proof.
  intros take fr sg lw f lw' f' T HW HCur HTake HRunC.
  assert (HRun : lin_bottom_sched_zrun (N.to_nat take)
      (lsCur fr) sg lw f (lsGap fr) (lsSlot fr)
      = Some (lw', f')).
  { rewrite <- clin_bottom_sched_zrun_proj, HRunC. reflexivity. }
  destruct (lin_bottom_sched_zrun_literals
    (N.to_nat take) (lsCur fr) sg lw f
    (lsGap fr) (lsSlot fr) lw' f' HRun)
    as (HLit & HLit').
  destruct (lin_bottom_sched_zrun_raw
    (N.to_nat take) (lsCur fr) sg lw f
    (lsGap fr) (lsSlot fr) lw' f' HRun)
    as (post & HRawRun & EW').
  assert (HPrefix : forall i, (i <= lsCur fr)%nat ->
      lin_flat sg (firstn i lw) =
      lin_flat sg (firstn i lw')).
  { intros i Hi.
    rewrite (literal_word_flat sg (firstn i lw)
      (literal_word_firstn i lw HLit)).
    rewrite (literal_word_flat sg (firstn i lw')
      (literal_word_firstn i lw' HLit')).
    rewrite EW'.
    assert (HFirstLen : length (firstn (lsCur fr) lw) =
        lsCur fr) by (rewrite length_firstn; lia).
    rewrite (firstn_app_left _ i
      (firstn (lsCur fr) lw)
      post ltac:(rewrite HFirstLen; exact Hi)).
    rewrite firstn_firstn, PeanoNat.Nat.min_l by exact Hi. reflexivity. }
  split; [exact HPrefix|].
  intros prs base tail HView.
  assert (HViewRaw : schedule_frame_view fr
      (skipn (lsCur fr) lw) prs base tail).
  { rewrite <- (literal_word_flat sg
      (skipn (lsCur fr) lw)
      (literal_word_skipn (lsCur fr) lw HLit)).
    exact HView. }
  assert (HQt : (N.of_nat (N.to_nat take) <= lsTicks fr)%N)
    by (rewrite N2Nat.id; exact HTake).
  destruct (clin_bottom_sched_zrun_schedule
    (N.to_nat take) fr sg lw f lw' f' T HW HCur HQt HRunC
    prs base tail HViewRaw)
    as (used & rest & tail' & EPrs & HUsed & HTrips & _ & HOutRaw).
  destruct HView as
    (HSlot & HLen & HShape & HBaseCols & HFrame & HGap).
  assert (ERest : rest = skipn (N.to_nat take) prs).
  { rewrite EPrs, <- HUsed. symmetry.
    apply LineageCascade_skipn_len_app. }
  assert (HTakeNat : (N.to_nat take <= length prs)%nat).
  { rewrite EPrs, length_app, HUsed. lia. }
  assert (HOut : lin_flat sg
      (skipn (lsCur fr) lw') =
      (base ++ schedule_stock rest) ++ tail').
  { rewrite (literal_word_flat sg
      (skipn (lsCur fr) lw')
      (literal_word_skipn (lsCur fr) lw' HLit')).
    exact HOutRaw. }
  exists used, rest, tail'.
  split; [exact EPrs|]. split; [exact HUsed|]. split; [exact HTrips|].
  unfold schedule_frame_view, lin_sched_advance.
  cbn [lsSlot lsTicks lsGap].
  repeat split.
  - exact (sched_slot_advance_le3
      (lsSlot fr) take HSlot).
  - rewrite ERest. exact (schedule_ticks_skip
      (lsTicks fr) take prs HLen HTake).
  - change (schedule_shape
      (lin_sched_slot_advance (lsSlot fr) take) rest).
    rewrite ERest.
    pose proof (schedule_shape_skipn
      (N.to_nat take) prs (lsSlot fr) HSlot HShape) as HRestShape.
    rewrite N2Nat.id in HRestShape. exact HRestShape.
  - exact HBaseCols.
  - exact HOut.
  - rewrite ERest.
    pose proof (schedule_stock_skip_length
      (N.to_nat take) prs (lsSlot fr)
      HTakeNat HSlot HShape) as HRestStock.
    rewrite N2Nat.id in HRestStock.
    pose proof (schedule_stock_first_skip
      (N.to_nat take) prs) as EStockSplit.
    apply (f_equal (@length bg)) in EStockSplit.
    rewrite length_app in EStockSplit.
    pose proof (schedule_stock_firstn_length
      (N.to_nat take) prs (lsSlot fr)
      HTakeNat HSlot HShape) as HUsedStock.
    rewrite N2Nat.id in HUsedStock.
    rewrite length_app, HRestStock. rewrite length_app in HGap. lia.
Qed.
Lemma clin_bottom_global_scheduled_transitionc :
  forall take fr base lc sg w f lw' f' w2 (T : N),
  sg_wf sg ->
  lsCur fr = (base + lc)%nat ->
  (base <= length w)%nat ->
  (lc <= length (skipn base w))%nat ->
  (take <= lsTicks fr)%N ->
  clin_bottom_sched_zrun (N.to_nat take) lc sg
    (skipn base w) f (lsGap fr) (lsSlot fr)
    = (Some (lw', f'), cx T) ->
  w2 = setsfx base w lw' ->
  scheduled_transitionc T fr take sg w f sg w2 f'.
Proof.
  intros take fr base lc sg w f lw' f' w2 T
    HW HCur HBase HLc HTake HRun ->.
  set (lfr := {| lsCur := lc;
                 lsTicks := lsTicks fr;
                 lsSlot := lsSlot fr;
                 lsGap := lsGap fr |}).
  assert (HLocal : scheduled_transitionc T lfr take sg (skipn base w) f
      sg lw' f').
  { apply clin_bottom_local_scheduled_transitionc;
      [exact HW|exact HLc|exact HTake|].
    unfold lfr. cbn [lsCur lsGap lsSlot].
    exact HRun. }
  destruct HLocal as (HLocalPrefix & HLocalFrame).
  assert (HPreLen : length (firstn base w) = base)
    by (rewrite length_firstn; lia).
  assert (EInput : w = firstn base w ++ skipn base w)
    by (symmetry; apply firstn_skipn).
  assert (EOutput : setsfx base w lw' = firstn base w ++ lw')
    by (apply setsfx_app; exact HBase).
  assert (HPrefix : forall i, (i <= lsCur fr)%nat ->
      lin_flat sg (firstn i w) =
      lin_flat sg
        (firstn i (setsfx base w lw'))).
  { intros i Hi.
    destruct (PeanoNat.Nat.le_gt_cases i base) as [HIB|HIB].
    - rewrite EOutput. rewrite EInput at 1.
      rewrite
        (firstn_app_left _ i (firstn base w)
          (skipn base w) ltac:(rewrite HPreLen; exact HIB)).
      rewrite
        (firstn_app_left _ i (firstn base w) lw'
          ltac:(rewrite HPreLen; exact HIB)). reflexivity.
    - set (d := (i-base)%nat).
      assert (Ei : i = (base+d)%nat) by (unfold d; lia).
      assert (Hd : (d <= lc)%nat) by (unfold d; rewrite HCur in Hi; lia).
      assert (EFirstIn : firstn i w =
          firstn base w ++ firstn d (skipn base w)).
      { rewrite Ei. apply firstn_add_skipn. }
      assert (EFirstOut : firstn i (setsfx base w lw') =
          firstn base w ++ firstn d lw').
      { rewrite EOutput.
        replace i with (length (firstn base w) + d)%nat by lia.
        apply firstn_prefix_add. }
      rewrite EFirstIn, EFirstOut, !lin_flat_app_c.
      rewrite (HLocalPrefix d
        ltac:(unfold lfr; cbn [lsCur]; exact Hd)).
      reflexivity. }
  split; [exact HPrefix|].
  intros prs bword tail HView.
  assert (EInputSuffix : skipn lc (skipn base w) =
      skipn (lsCur fr) w).
  { rewrite skipn_add, HCur. reflexivity. }
  assert (HViewLocal : schedule_frame_view lfr
      (lin_flat sg (skipn lc (skipn base w))) prs bword tail).
  { rewrite EInputSuffix.
    unfold lfr, schedule_frame_view in *.
    cbn [lsSlot lsTicks lsGap] in *. exact HView. }
  destruct (HLocalFrame prs bword tail HViewLocal)
    as (used & rest & tail' & EPrs & HUsed & HTrips & HViewOut).
  assert (EOutputSuffix :
      skipn (lsCur fr) (setsfx base w lw') = skipn lc lw').
  { rewrite EOutput.
    replace (lsCur fr) with
      (length (firstn base w) + lc)%nat by lia.
    apply skipn_prefix_add. }
  exists used, rest, tail'.
  split; [exact EPrs|].
  split; [exact HUsed|].
  split; [exact HTrips|].
  rewrite EOutputSuffix.
  unfold lfr, schedule_frame_view,
    lin_sched_advance in *.
  cbn [lsSlot lsTicks lsGap] in *.
  exact HViewOut.
Qed.
Theorem lin_bottom_sched_zrun_framec :
  forall fr base lc sg w f lw' f' w2 (T : N),
  sg_wf sg ->
  lsCur fr = (base + lc)%nat ->
  (base <= length w)%nat ->
  (lc <= length (skipn base w))%nat ->
  clin_bottom_sched_zrun (N.to_nat (lsTicks fr)) lc sg
    (skipn base w) f (lsGap fr) (lsSlot fr)
    = (Some (lw', f'), cx T) ->
  w2 = setsfx base w lw' ->
  scheduled_framec T fr sg w f sg w2 f'.
Proof.
  intros fr base lc sg w f lw' f' w2 T HW HCur HBase HLc HRun EW2.
  replace T with (T + 0)%N by lia.
  eapply scheduled_transition_framec.
  - exact (clin_bottom_global_scheduled_transitionc
             (lsTicks fr) fr base lc sg w f lw' f' w2 T
             HW HCur HBase HLc (N.le_refl _) HRun EW2).
  - apply scheduled_framec_zero'.
    cbn [lin_sched_advance lsTicks]. lia.
Qed.
Corollary lin_bulk_zrun_flight_creach :
  forall sg J tail f j p tk w1 sg1 nh rem emit
         (basec lc : nat) lw' f2 (T : N),
  stable_guard sg ((2,2,J)%N :: tail) ->
  (1 <= J)%N -> (1 <= j)%nat ->
  forallb is_col (firstn j ((2,2,J)%N :: tail)) = true ->
  detect_phase ((2,2,J)%N :: tail) j = Some p ->
  Nat.eqb (N.to_nat ((p+tk)/28)) O = false ->
  lin_bulk sg ((2,2,J)%N :: tail) j p tk =
    Some (w1, sg1, nh, rem, emit) ->
  sg_wf sg1 ->
  lsCur (lin_sched_child nh rem emit p tk)
    = (basec + lc)%nat ->
  (basec <= length (subst_at O 1 [(2,2,J+tk)%N] w1))%nat ->
  (lc <= length (skipn basec
     (subst_at O 1 [(2,2,J+tk)%N] w1)))%nat ->
  clin_bottom_sched_zrun
    (N.to_nat (lsTicks (lin_sched_child nh rem emit p tk)))
    lc sg1 (skipn basec (subst_at O 1 [(2,2,J+tk)%N] w1)) f
    (lsGap (lin_sched_child nh rem emit p tk))
    (lsSlot (lin_sched_child nh rem emit p tk))
    = (Some (lw', f2), cx T) ->
  exists (pr : word) (c b : N) (cs : list N),
    forallb is_col pr = true
    /\ lin_flat sg (firstn j ((2,2,J)%N :: tail))
       = (2,2,J)%N :: pr ++ runway (c :: cs)
    /\ creach (d_flight (bsum ((2,2,J)%N :: pr)) tk
                 (drunway 0 (rev (c :: cs)) p rem b + T)%N)
         (wconf [] 0 (sdecode
            (lin_flat sg ((2,2,J)%N :: tail)) f))
         (wconf [] 0 (sdecode
            (lin_flat sg1
               (setsfx basec
                  (subst_at O 1 [(2,2,J+tk)%N] w1) lw')) f2)).
Proof.
  intros sg J tail f j p tk w1 sg1 nh rem emit basec lc lw' f2 T
    HG HJ Hj HCols HD HFull HB HW1 HCur HBase HLc HRun.
  eapply lin_bulk_master_scheduled_sound_fullc;
    [exact HG|exact HJ|exact Hj|exact HCols|exact HD|exact HFull|exact HB|].
  exact (lin_bottom_sched_zrun_framec
           (lin_sched_child nh rem emit p tk) basec lc sg1
           (subst_at O 1 [(2,2,J+tk)%N] w1) f lw' f2
           (setsfx basec
              (subst_at O 1 [(2,2,J+tk)%N] w1) lw') T
           HW1 HCur HBase HLc HRun eq_refl).
Qed.
