Lemma CascadeWC_keyi_in (sg : list seg) (g : bg) (s : seg) :
  keyi sg g = Some s -> In s sg.
Proof.
  unfold keyi. destruct (phshape g); [|discriminate].
  induction sg as [|x sg IH]; cbn; [discriminate|].
  destruct (gC g =? sKey x)%N.
  - intros H. injection H as <-. left. reflexivity.
  - intros H. right. exact (IH H).
Qed.
Lemma CascadeWC_segcache_len (s : seg) :
  segcache s = true ->
  length (sFlat s) = sLen s.
Proof.
  unfold segcache, sFlat, matb, sBody.
  intros H. apply PeanoNat.Nat.eqb_eq in H.
  rewrite length_map, length_app, length_rev. lia.
Qed.
Lemma sg_wf_cache (sg : list seg) (s : seg) :
  sg_wf sg -> In s sg -> segcache s = true.
Proof.
  intros HW HIn.
  destruct (sg_wf_seg sg s HW HIn) as (HC & _). exact HC.
Qed.
Lemma keyl_flat_len (sg : list seg) (g : bg) :
  sg_wf sg ->
  length (lin_flat sg [g])
  = match keyl sg g with Some l => l | None => 1%nat end.
Proof.
  intros HW. cbn [lin_flat].
  unfold keyb, keyl.
  destruct (keyi sg g) as [s|] eqn:EK.
  - rewrite app_nil_r.
    apply CascadeWC_segcache_len, (sg_wf_cache sg s HW), (CascadeWC_keyi_in sg g s EK).
  - reflexivity.
Qed.
Fixpoint wstrip (sg : list seg) (cols : word) (g : nat)
  : option word :=
  match cols with
  | [] => if Nat.eqb g O then Some [] else None
  | c :: t =>
      if Nat.eqb g O then Some (c :: t)
      else
        let l := match keyl sg c with
                 | Some l => l | None => 1%nat end in
        if Nat.leb l g then wstrip sg t (g - l)%nat else None
  end.
Lemma wstrip_flat (sg : list seg) (HW : sg_wf sg) :
  forall (cols : word) (g : nat) (av : word),
  wstrip sg cols g = Some av ->
  lin_flat sg av = skipn g (lin_flat sg cols).
Proof.
  induction cols as [|c t IH]; intros g av HS; cbn [wstrip] in HS.
  - destruct (Nat.eqb g O) eqn:EG; [|discriminate].
    apply PeanoNat.Nat.eqb_eq in EG. subst g.
    injection HS as <-. reflexivity.
  - destruct (Nat.eqb g O) eqn:EG.
    + apply PeanoNat.Nat.eqb_eq in EG. subst g.
      injection HS as <-. reflexivity.
    + set (l := match keyl sg c with Some l => l | None => 1%nat end)
        in HS.
      destruct (Nat.leb l g) eqn:EL; [|discriminate].
      apply PeanoNat.Nat.leb_le in EL.
      specialize (IH (g - l)%nat av HS).
      assert (EHead : lin_flat sg (c :: t)
                      = lin_flat sg [c] ++ lin_flat sg t).
      { change (c :: t) with ([c] ++ t). apply lin_flat_app_c. }
      assert (ELen : length (lin_flat sg [c]) = l)
        by (unfold l; apply keyl_flat_len; exact HW).
      assert (HAll : (length (lin_flat sg [c]) <= g)%nat)
        by (rewrite ELen; exact EL).
      rewrite EHead, skipn_app, ELen.
      rewrite (skipn_all2 (lin_flat sg [c]) HAll).
      cbn [app]. exact IH.
Qed.
Corollary wstrip_flen (sg : list seg) (HW : sg_wf sg)
      (cols : word) (g : nat) (av : word) :
  wstrip sg cols g = Some av ->
  lin_flen sg av = (lin_flen sg cols - g)%nat.
Proof.
  intros HS.
  rewrite (lin_flen_flat_wf sg cols HW),
          (lin_flen_flat_wf sg av HW),
          (wstrip_flat sg HW cols g av HS), length_skipn.
  reflexivity.
Qed.
Definition segcsum_ok (sg : list seg) : Prop :=
  forall s, In s sg -> sCsum s = bsum (sFlat s).
Definition segcsumb (sg : list seg) : bool :=
  forallb (fun s => (sCsum s =? bsum (sFlat s))%N) sg.
Lemma segcsumb_ok (sg : list seg) :
  segcsumb sg = true -> segcsum_ok sg.
Proof.
  unfold segcsumb, segcsum_ok. intros H s HIn.
  rewrite forallb_forall in H. specialize (H s HIn).
  apply N.eqb_eq in H. exact H.
Qed.
Lemma lin_bsum_flat (sg : list seg) (HC : segcsum_ok sg) :
  forall w : word,
  lin_bsum sg w = bsum (lin_flat sg w).
Proof.
  induction w as [|g w IH]; [reflexivity|].
  cbn [lin_bsum lin_flat].
  unfold lin_gcross, keyb.
  destruct (keyi sg g) as [s|] eqn:EK.
  - rewrite bsum_app, IH.
    rewrite (HC s (CascadeWC_keyi_in sg g s EK)). reflexivity.
  - cbn [bsum]. rewrite IH. reflexivity.
Qed.
Lemma bsum_ccolcost (w : word) :
  forallb (fun g => (gZ g =? 2)%N) w = true ->
  bsum w = ccolcost w.
Proof.
  induction w as [|g w IH]; [reflexivity|].
  cbn [forallb bsum ccolcost].
  intros H. apply andb_prop in H. destruct H as (HZ & HT).
  apply N.eqb_eq in HZ. rewrite (IH HT).
  destruct g as [[o z] c]. unfold bpc, gZ in *.
  cbn [fst snd] in *. subst z. unfold gC, gO. cbn [fst snd]. lia.
Qed.
Corollary lin_bsum_ccolcost (sg : list seg)
      (HC : segcsum_ok sg) (w : word) :
  forallb (fun g => (gZ g =? 2)%N) (lin_flat sg w) = true ->
  lin_bsum sg w = ccolcost (lin_flat sg w).
Proof.
  intros HZ. rewrite (lin_bsum_flat sg HC w). apply bsum_ccolcost, HZ.
Qed.
Inductive scheduled_workc : N -> list lsc_frame ->
    list seg -> word -> N ->
    list seg -> word -> N -> Prop :=
  | scheduled_workc_nil : forall sg w f,
      scheduled_workc 0%N [] sg w f sg w f
  | scheduled_workc_cons : forall T1 T2 fr rest sg w f sg1 w1 f1 sg2 w2 f2,
      scheduled_framec T1 fr sg w f sg1 w1 f1 ->
      scheduled_workc T2 rest sg1 w1 f1 sg2 w2 f2 ->
      scheduled_workc (T1 + T2)%N (fr :: rest) sg w f sg2 w2 f2.
Lemma scheduled_workc_work :
  forall T st sg w f sg' w' f',
  scheduled_workc T st sg w f sg' w' f' ->
  scheduled_work st sg w f sg' w' f'.
Proof.
  intros T st sg w f sg' w' f' H.
  induction H as [sg0 w0 f0
                 |T1 T2 fr rest sg0 w0 f0 sga wa fa sgb wb fb HF HR IH].
  - constructor.
  - econstructor;
      [exact (scheduled_framec_frame _ _ _ _ _ _ _ _ HF)|exact IH].
Qed.
Lemma scheduled_workc_zero :
  forall T fr rest sg w f sg' w' f',
  lsTicks fr = 0%N ->
  scheduled_workc T rest sg w f sg' w' f' ->
  scheduled_workc T (fr :: rest) sg w f sg' w' f'.
Proof.
  intros T fr rest sg w f sg' w' f' HT HW.
  replace T with (0 + T)%N by lia.
  econstructor; [apply scheduled_framec_zero'; exact HT|exact HW].
Qed.
Lemma scheduled_workc_one :
  forall T fr sg w f sg' w' f',
  scheduled_framec T fr sg w f sg' w' f' ->
  scheduled_workc T [fr] sg w f sg' w' f'.
Proof.
  intros T fr sg w f sg' w' f' H.
  replace T with (T + 0)%N by lia.
  econstructor; [exact H|constructor].
Qed.
Lemma scheduled_workc_inv :
  forall T fr rest sg w f sg' w' f',
  scheduled_workc T (fr :: rest) sg w f sg' w' f' ->
  exists T1 T2 sg1 w1 f1,
    T = (T1 + T2)%N /\
    scheduled_framec T1 fr sg w f sg1 w1 f1 /\
    scheduled_workc T2 rest sg1 w1 f1 sg' w' f'.
Proof.
  intros T fr rest sg w f sg' w' f' H. inversion H; subst.
  eexists _, _, _, _, _. split; [reflexivity|]. split; eassumption.
Qed.
Lemma lin_direct_flat_scheduled_transitionc :
  forall fr sg w f cols s renewed sfx f2 w2 (K : N),
  sg_wf sg -> keys_big sg ->
  sg_live sg ->
  (lsCur fr <= length w)%nat ->
  lsTicks fr <> 0%N ->
  seek (skipn (lsCur fr) w) = (cols, s) ->
  s <> [] ->
  (forall t', s = (4%N,3%N,1%N) :: t' -> ph_notlast sg cols) ->
  nbrs1z sg s ->
  (forall g t, s = g :: t -> ph sg g = false) ->
  lin_dtick_after_seek cols s f = Some (renewed, sfx, f2) ->
  (renewed = true ->
    (lsGap fr + 2 <= lin_flen sg cols)%nat) ->
  (if Nat.eqb (lsCur fr) O then Some sfx
   else lin_join_safe sg
          (firstn (lsCur fr) w) sfx) = Some w2 ->
  cin (N.to_nat K)
    (snd (cdtick_after_seek
            (skipn (lsGap fr) (lin_flat sg cols))
            (lin_flat sg s) f)) ->
  scheduled_transitionc K fr 1 sg w f sg w2 f2.
Proof.
  intros fr sg w f cols s renewed sfx f2 w2 K
    HW HK HL HCur HTicks HSeek Hs HP HN HHead HRun HRenew HJoin HKin.
  assert (EW2 : w2 = firstn (lsCur fr) w ++ sfx).
  { destruct (Nat.eqb (lsCur fr) O) eqn:ECur.
    - apply PeanoNat.Nat.eqb_eq in ECur. injection HJoin as <-.
      rewrite ECur. reflexivity.
    - exact (lin_join_safe_some _ _ _ _ HJoin). }
  assert (HPrefix : forall i, (i <= lsCur fr)%nat ->
      lin_flat sg (firstn i w) =
      lin_flat sg (firstn i w2)).
  { intros i Hi. rewrite EW2.
    assert (HCurFirst : length (firstn (lsCur fr) w) =
        lsCur fr) by (rewrite length_firstn; lia).
    rewrite (firstn_app_left _ i
      (firstn (lsCur fr) w) sfx
      ltac:(rewrite HCurFirst; exact Hi)).
    rewrite firstn_firstn, PeanoNat.Nat.min_l by exact Hi. reflexivity. }
  split; [exact HPrefix|].
  intros prs base tail HView.
  destruct prs as [|oc rs].
  { cbn [length] in HView. destruct HView as [_ [HLen _]].
    exfalso. apply HTicks. apply (f_equal N.of_nat) in HLen.
    rewrite N2Nat.id in HLen. symmetry. exact HLen. }
  destruct HView as (HSlot & HLen & HShape & HBaseCols & HFrame & HGap).
  assert (HMidCols : delivery_cols
      (base ++ schedule_stock (oc :: rs)) = true).
  { rewrite delivery_cols_app, HBaseCols,
      schedule_stock_cols. reflexivity. }
  assert (EFlatSeek :
      seek ((base ++ schedule_stock (oc :: rs)) ++ tail)
        = (lin_flat sg cols, lin_flat sg s)).
  { rewrite <- HFrame, seek_flat by exact HW.
    rewrite HSeek. reflexivity. }
  rewrite (seek_app_delivery_cols
    (base ++ schedule_stock (oc :: rs)) tail HMidCols)
    in EFlatSeek.
  destruct (seek tail) as [avail tail0] eqn:ETailSeek.
  cbn [fst snd] in EFlatSeek.
  pose proof (f_equal fst EFlatSeek) as ECols0.
  pose proof (f_equal snd EFlatSeek) as ETail0.
  cbn [fst snd] in ECols0, ETail0.
  assert (ECols : lin_flat sg cols =
      (base ++ schedule_stock (oc :: rs)) ++ avail)
    by (symmetry; exact ECols0).
  destruct (seek_split tail avail tail0 ETailSeek)
    as (ETailSplit & HAvailCols).
  assert (ETail : tail = avail ++ lin_flat sg s).
  { rewrite ETailSplit, ETail0. reflexivity. }
  assert (EAvail :
      skipn (lsGap fr) (lin_flat sg cols) = avail).
  { rewrite ECols, <- HGap. apply LineageCascade_skipn_len_app. }
  pose proof (lin_dtick_after_seek_flat_some
    sg cols s f renewed sfx f2 HW HK HL HP HN HHead HRun) as HFlatRun.
  rewrite ECols in HFlatRun.
  assert (HRenewAvail : renewed = true -> (2 <= length avail)%nat).
  { intro ER. specialize (HRenew ER).
    rewrite (lin_flen_flat_wf sg cols HW), ECols,
      length_app, HGap in HRenew. lia. }
  destruct (schedule_step_strip
    oc rs base avail (lin_flat sg s) f renewed
    (lin_flat sg sfx) f2 HFlatRun HRenewAvail)
    as (body & HBody & EBody).
  assert (HGuardAvail :
    forallb (fun gg => is_col gg && negb (is_cmf gg)
                       && (3 <=? gO gg)%N) avail = true)
    by exact HAvailCols.
  assert (HBodyC : fst (cdtick_after_seek avail
                          (lin_flat sg s) f) = Some (body, f2)).
  { rewrite cdtick_after_seek_proj.
    exact (lin_dtick_after_seek_proj
             avail (lin_flat sg s) f renewed body f2 HBody). }
  assert (HkIn : cin (N.to_nat K)
           (snd (cdtick_after_seek avail
                   (lin_flat sg s) f)))
    by (rewrite <- EAvail; exact HKin).
  pose proof (dtick_after_seek_tripc avail (lin_flat sg s)
    f body f2 (N.to_nat K) HGuardAvail HBodyC HkIn) as HTripc0.
  rewrite N2Nat.id in HTripc0.
  assert (HTripc : delivery_tripc K tail f body f2)
    by (rewrite ETail; exact HTripc0).
  pose proof (sched_tripsc_one oc K tail body f f2 HTripc) as HOneTrips.
  assert (EOutSuffix : lin_flat sg
      (skipn (lsCur fr) w2) =
      (base ++ schedule_stock rs) ++
        schedule_release oc body).
  { rewrite EW2.
    assert (HFirstLen : length (firstn (lsCur fr) w) =
        lsCur fr) by (rewrite length_firstn; lia).
    replace (lsCur fr) with
      (length (firstn (lsCur fr) w)) at 1 by exact HFirstLen.
    rewrite LineageCascade_skipn_len_app, EBody. reflexivity. }
  exists [oc], rs, (schedule_release oc body).
  split; [reflexivity|]. split; [reflexivity|].
  split; [exact HOneTrips|].
  pose proof (schedule_frame_view_advance_one
    fr (lin_flat sg (skipn (lsCur fr) w))
    oc rs base tail body
    (conj HSlot (conj HLen (conj HShape
      (conj HBaseCols (conj HFrame HGap)))))) as HAdvance.
  rewrite EOutSuffix. exact HAdvance.
Qed.
Definition dlocal (s : word) (f : N) : cost :=
  match s with
  | (o7,z7,c7) :: _ =>
      if ((z7 =? 3) && (c7 =? 1))%N
      then snd (cfire_comp (length s) s f)
      else cdrop6 (snd (cleaf_act s f))
  | [] => cdrop6 (snd (cleaf_act s f))
  end.
Lemma cdtick_after_seek_split (cols s : word) (f : N)
      (out : word) (f' : N) :
  fst (crenew_seg (length s) cols s f) = None ->
  fst (cdtick_after_seek cols s f) = Some (out, f') ->
  snd (cdtick_after_seek cols s f)
    = cadd (cx (ccolcost cols)) (dlocal s f).
Proof.
  intros HR HS.
  unfold cdtick_after_seek, dlocal in *.
  rewrite HR in *.
  destruct s as [|[[o7 z7] c7] t].
  - unfold cleaf_lift in *.
    destruct (fst (cleaf_act [] f)) as [[s3' f2]|] eqn:ER;
      rewrite ?ER; rewrite ?ER in HS; cbn [fst] in HS.
    + reflexivity.
    + discriminate.
  - destruct ((z7 =? 3) && (c7 =? 1))%N.
    + match goal with
      | |- context [cfire_comp ?n ?a ?b] =>
          set (X := cfire_comp n a b) in HS |- *
      end.
      clearbody X.
      destruct X as [[[s3' f2]|] d]; cbn [fst snd] in HS |- *.
      * reflexivity.
      * cbn in HS. discriminate HS.
    + match type of HS with
      | context [sand_leaf ?X] => set (Y := sand_leaf X) in HS |- *
      end.
      clearbody Y. destruct Y;
        [cbn [fst] in HS; cbn in HS; discriminate HS|].
      unfold cleaf_lift in *.
      match goal with
      | |- context [cleaf_act ?a ?b] =>
          set (X := cleaf_act a b) in HS |- *
      end.
      clearbody X.
      destruct X as [[[s3' f2]|] d]; cbn [fst snd] in HS |- *.
      * reflexivity.
      * cbn in HS. discriminate HS.
Qed.
Lemma delivery_guard_z2 (w : word) :
  forallb (fun g => is_col g && negb (is_cmf g)
                    && (3 <=? gO g)%N) w = true ->
  forallb (fun g => (gZ g =? 2)%N) w = true.
Proof.
  induction w as [|g w IH]; [reflexivity|].
  cbn [forallb]. intros H. apply andb_prop in H. destruct H as (HG & HT).
  apply andb_prop in HG. destruct HG as (HG & _).
  apply andb_prop in HG. destruct HG as (HC & _).
  unfold is_col in HC. apply andb_prop in HC. destruct HC as (HZ & _).
  rewrite HZ. cbn [andb]. exact (IH HT).
Qed.
Definition cdirect (sg : list seg) (cols s3 : word)
                   (f : N) (gap : nat) (renewed : bool) : cost :=
  if renewed then cundef
  else if lin_literal_word s3 then
    match wstrip sg cols gap with
    | Some av =>
        cadd (cx (lin_bsum sg av)) (dlocal s3 f)
    | None => cundef
    end
  else cundef.
Lemma cdirect_cin (sg : list seg) (cols s av out : word)
      (f f' : N) (gap : nat) (K : N) :
  segcsum_ok sg ->
  wstrip sg cols gap = Some av ->
  lin_literal_word s = true ->
  forallb (fun g => (gZ g =? 2)%N) (lin_flat sg av) = true ->
  fst (crenew_seg (length s) (lin_flat sg av) s f) = None ->
  fst (cdtick_after_seek (lin_flat sg av) s f)
    = Some (out, f') ->
  cdirect sg cols s f gap false = cx K ->
  cin (N.to_nat K)
    (snd (cdtick_after_seek (lin_flat sg av)
            (lin_flat sg s) f)).
Proof.
  intros HC HStrip HLit HZ2 HRN HSome HEm.
  rewrite (literal_word_flat sg s HLit).
  rewrite (cdtick_after_seek_split (lin_flat sg av) s f out f'
             HRN HSome).
  rewrite <- (lin_bsum_ccolcost sg HC av HZ2).
  unfold cdirect in HEm. rewrite HLit, HStrip in HEm.
  rewrite HEm. apply cin_cx.
Qed.
Lemma casc_ladder_step :
  forall fr take base lc rest sg w f lw' f' w2 sg' w'' f'' (T1 T2 : N),
  sg_wf sg ->
  lsCur fr = (base + lc)%nat ->
  (base <= length w)%nat ->
  (lc <= length (skipn base w))%nat ->
  (take <= lsTicks fr)%N ->
  clin_bottom_sched_zrun (N.to_nat take) lc sg
    (skipn base w) f (lsGap fr) (lsSlot fr)
    = (Some (lw', f'), cx T1) ->
  w2 = setsfx base w lw' ->
  scheduled_workc T2 (lin_sched_advance fr take :: rest)
    sg w2 f' sg' w'' f'' ->
  scheduled_workc (T1 + T2)%N (fr :: rest) sg w f sg' w'' f''.
Proof.
  intros fr take base lc rest sg w f lw' f' w2 sg' w'' f'' T1 T2
    HW HCur HBase HLc HTake HRun HW2 HWork.
  pose proof (clin_bottom_global_scheduled_transitionc
    take fr base lc sg w f lw' f' w2 T1 HW HCur HBase HLc HTake HRun HW2)
    as HTrans.
  destruct (scheduled_workc_inv _ _ _ _ _ _ _ _ _ HWork)
    as (T2a & T2b & sg1 & w1 & f1 & ET2 & HFrame & HRest).
  replace (T1 + T2)%N with ((T1 + T2a) + T2b)%N by lia.
  econstructor; [|exact HRest].
  exact (scheduled_transition_framec T1 T2a fr take
           sg w f sg w2 f' sg1 w1 f1 HTrans HFrame).
Qed.
Lemma casc_zero_step :
  forall (T : N) fr rest sg w f sg' w' f',
  lsTicks fr = 0%N ->
  scheduled_workc T rest sg w f sg' w' f' ->
  scheduled_workc T (fr :: rest) sg w f sg' w' f'.
Proof. exact scheduled_workc_zero. Qed.
Lemma casc_direct_flat_step :
  forall fr rest sg w f cols s renewed sfx f2 w2
         sg' w'' f'' (K T : N),
  sg_wf sg -> keys_big sg ->
  sg_live sg ->
  (lsCur fr <= length w)%nat ->
  lsTicks fr <> 0%N ->
  seek (skipn (lsCur fr) w) = (cols, s) ->
  s <> [] ->
  (forall t', s = (4%N,3%N,1%N) :: t' -> ph_notlast sg cols) ->
  nbrs1z sg s ->
  (forall g t, s = g :: t -> ph sg g = false) ->
  lin_dtick_after_seek cols s f = Some (renewed, sfx, f2) ->
  (renewed = true ->
    (lsGap fr + 2 <= lin_flen sg cols)%nat) ->
  (if Nat.eqb (lsCur fr) O then Some sfx
   else lin_join_safe sg
          (firstn (lsCur fr) w) sfx) = Some w2 ->
  cin (N.to_nat K)
    (snd (cdtick_after_seek
            (skipn (lsGap fr) (lin_flat sg cols))
            (lin_flat sg s) f)) ->
  scheduled_workc T (lin_sched_advance_one fr :: rest)
    sg w2 f2 sg' w'' f'' ->
  scheduled_workc (K + T)%N (fr :: rest) sg w f sg' w'' f''.
Proof.
  intros fr rest sg w f cols s renewed sfx f2 w2 sg' w'' f'' K T
    HW HK HL HCur HTicks HSeek Hs HP HN HHead HRun HRenew HJoin HKin HWork.
  pose proof (lin_direct_flat_scheduled_transitionc
    fr sg w f cols s renewed sfx f2 w2 K
    HW HK HL HCur HTicks HSeek Hs HP HN HHead HRun HRenew HJoin HKin)
    as HTrans.
  rewrite lin_sched_advance_one_eq in HWork.
  destruct (scheduled_workc_inv _ _ _ _ _ _ _ _ _ HWork)
    as (Ta & Tb & sg1 & w1 & f1 & ET & HFrame & HRest).
  replace (K + T)%N with ((K + Ta) + Tb)%N by lia.
  econstructor; [|exact HRest].
  exact (scheduled_transition_framec K Ta fr 1
           sg w f sg w2 f2 sg1 w1 f1 HTrans HFrame).
Qed.
Lemma scheduled_workc_nil_inv :
  forall T sg w f sg' w' f',
  scheduled_workc T [] sg w f sg' w' f' ->
  T = 0%N /\ sg = sg' /\ w = w' /\ f = f'.
Proof.
  intros T sg w f sg' w' f' H. inversion H; subst.
  repeat split; reflexivity.
Qed.
Lemma scheduled_workc_one_inv :
  forall T fr sg w f sg' w' f',
  scheduled_workc T [fr] sg w f sg' w' f' ->
  scheduled_framec T fr sg w f sg' w' f'.
Proof.
  intros T fr sg w f sg' w' f' H.
  destruct (scheduled_workc_inv _ _ _ _ _ _ _ _ _ H)
    as (T1 & T2 & sg1 & w1 & f1 & ET & HF & HR).
  destruct (scheduled_workc_nil_inv _ _ _ _ _ _ _ HR)
    as (ET2 & <- & <- & <-).
  subst T2. rewrite N.add_0_r in ET. subst T. exact HF.
Qed.
Definition d_flight_slot (base tk D T : N) : cost :=
  d_flight base tk (D + T)%N.
Lemma d_flight_slot_exact (base tk D T : N) :
  d_flight_slot base tk D T
  = cx (tk * base + 10 * (tk * (tk - 1) / 2) + 6 * tk + (D + T))%N.
Proof. reflexivity. Qed.
