       FLAT_ROUND_FUEL CFUEL TRIES.
Opaque FUEL.
Fixpoint ladE (q : N) (n : nat) : N :=
  match n with
  | O => 0%N
  | S k => ((if emits q then 1 else 0) + ladE (q+1) k)%N
  end.
Fixpoint ladK (q : N) (n : nat) : N :=
  match n with
  | O => 0%N
  | S k => ((2 * ladderA q
             + (if emits q
                then 14 * DBu q + 14 else 3))
            + ladK (q+1) k)%N
  end.
Fixpoint msuf (rl : list N) : N :=
  match rl with
  | [] => 0%N
  | d :: r => (msuf r + wcolsum (d :: r))%N
  end.
Definition rM2 (rl : list N) : N :=
  match rl with [] => 0%N | _ :: r => msuf r end.
Fixpoint qsum (l : list N) : N :=
  match l with [] => 0%N | x :: t => ((x - 3) + qsum t)%N end.
Definition rQ (rl : list N) : N := qsum (removelast rl).
Lemma removelast_cons2 (d e : N) (r : list N) :
  removelast (d :: e :: r) = d :: removelast (e :: r).
Proof. reflexivity. Qed.
Example drunway_pin1 :
  drunway 0%N [43;44;45]%N 5 7 40
  = (dladder 5 40 (N.to_nat (27-5))
     + (28-5) * wcolsum [43;44;45]%N + 14*40 + 22
     + 28 * rM2 [43;44;45]%N + 56 * rQ [43;44;45]%N
     + 508 * N.of_nat (pred (length [43;44;45]%N))
     + dladder 0 (45-3) (N.to_nat 7))%N.
Proof. vm_compute. reflexivity. Qed.
Lemma wcolsum_ge (l : list N) : (0 <= wcolsum l)%N.
Proof. lia. Qed.
Lemma msuf_le (l : list N) :
  (msuf l <= N.of_nat (length l) * wcolsum l)%N.
Proof.
  induction l as [|x t IH]; [cbn; lia|].
  cbn [msuf length wcolsum].
  assert (HT : (wcolsum t <= 14*x + 22 + wcolsum t)%N)
    by lia.
  assert (HM : (msuf t <= N.of_nat (length t) * wcolsum t)%N)
    by exact IH.
  rewrite Nat2N.inj_succ.
  assert (HL : (N.of_nat (length t) * wcolsum t
                <= N.of_nat (length t) * (14*x+22+wcolsum t))%N)
    by (apply N.mul_le_mono_l; lia).
  lia.
Qed.
Lemma rM2_bracket (rl : list N) :
  (rM2 rl <= N.of_nat (pred (length rl)) * wcolsum rl)%N.
Proof.
  destruct rl as [|d r]; [cbn; lia|].
  cbn [rM2 length pred].
  eapply N.le_trans; [apply msuf_le|].
  apply N.mul_le_mono_l. cbn [wcolsum]. lia.
Qed.
Lemma last_rev_cons (c : N) (cs : list N) : last (rev (c :: cs)) 0%N = c.
Proof.
  cbn [rev]. rewrite List.last_last. reflexivity.
Qed.
Lemma length_rev_cons (c : N) (cs : list N) :
  length (rev (c :: cs)) = length (c :: cs).
Proof. apply length_rev. Qed.
Lemma rev_cons_ne_nil (c : N) (cs : list N) : rev (c :: cs) <> [].
Proof.
  intro E. apply (f_equal (@length N)) in E.
  rewrite length_rev in E. cbn [length] in E. discriminate.
Qed.
Lemma qsum_app (a b : list N) : qsum (a ++ b) = (qsum a + qsum b)%N.
Proof. induction a as [|x t IH]; cbn [qsum app]; lia. Qed.
Lemma qsum_rev (l : list N) : qsum (rev l) = qsum l.
Proof.
  induction l as [|x t IH]; [reflexivity|].
  cbn [rev qsum]. rewrite qsum_app, IH. cbn [qsum]. lia.
Qed.
Lemma removelast_rev (c : N) (cs : list N) :
  removelast (rev (c :: cs)) = rev cs.
Proof.
  cbn [rev]. rewrite removelast_last. reflexivity.
Qed.
Lemma rQ_rev (c : N) (cs : list N) : rQ (rev (c :: cs)) = qsum cs.
Proof. unfold rQ. rewrite removelast_rev. apply qsum_rev. Qed.
Fixpoint wtake (sg : list seg) (cols : word) (g : nat)
  : option word :=
  match cols with
  | [] => if Nat.eqb g O then Some [] else None
  | c :: t =>
      if Nat.eqb g O then Some []
      else
        let l := match keyl sg c with
                 | Some l => l | None => 1%nat end in
        if Nat.leb l g
        then match wtake sg t (g - l)%nat with
             | Some pre => Some (c :: pre)
             | None => None
             end
        else None
  end.
Fixpoint wnth (sg : list seg) (w : word) (k : nat)
  : option bg :=
  match w with
  | [] => None
  | g :: t =>
      match keyi sg g with
      | Some s =>
          if Nat.ltb k (sLen s)
          then match nth_error (sBody s) k with
               | Some x => Some (adjk (sPend s) x)
               | None => None
               end
          else wnth sg t (k - sLen s)%nat
      | None => if Nat.eqb k O then Some g else wnth sg t (k - 1)%nat
      end
  end.
Definition dqterm (Sm Ln c : N) : N :=
  (4*Sm - (88*Ln + 56*c + 168*(Ln-1)))%N.
Definition dfl_base (base Sm c b p rem tk Ln T : N) : N :=
  (tk*base + 10*(tk*(tk-1)/2) + 6*tk
   + (ladK p (N.to_nat (27-p)) + 14 * ladE p (N.to_nat (27-p)) * b)
   + (28-p)*Sm + 14*b + 22
   + dqterm Sm Ln c
   + 508*(Ln-1)
   + (ladK 0 (N.to_nat rem) + 14 * ladE 0 (N.to_nat rem) * (c-3))
   + T)%N.
Definition dfl_num (base Sm c b p rem tk Ln M2 T : N) : N :=
  (dfl_base base Sm c b p rem tk Ln T + 28*M2)%N.
Definition dflight_num (base Sm c b p rem tk Ln T : N) : cost :=
  (dfl_base base Sm c b p rem tk Ln T,
   (dfl_base base Sm c b p rem tk Ln T + 28*((Ln-1)*Sm))%N).
Lemma lin_bulk_master_flight_at :
  forall sg J tail f j p tk w1 sg1 nh rem emit sg2 w2 f2 (T : N),
  stable_guard sg ((2,2,J)%N :: tail) ->
  (1 <= J)%N -> (1 <= j)%nat ->
  forallb is_col (firstn j ((2,2,J)%N :: tail)) = true ->
  detect_phase ((2,2,J)%N :: tail) j = Some p ->
  Nat.eqb (N.to_nat ((p+tk)/28)) O = false ->
  lin_bulk sg ((2,2,J)%N :: tail) j p tk =
    Some (w1, sg1, nh, rem, emit) ->
  scheduled_framec T
    (lin_sched_child nh rem emit p tk)
    sg1 (subst_at O 1 [(2,2,J+tk)%N] w1) f sg2 w2 f2 ->
  exists (pr : word) (c b : N) (cs : list N),
    forallb is_col pr = true
    /\ lin_flat sg (firstn j ((2,2,J)%N :: tail))
       = (2,2,J)%N :: pr ++ runway (c :: cs)
    /\ length (c :: cs) = N.to_nat ((p+tk)/28)
    /\ Forall (fun x => (FLOOR + 3 <= x)%N) (c :: cs)
    /\ wat ((2,2,J)%N :: tail) (j + phase_len p)%nat
       = Some (4,2,b + DBu p)%N
    /\ rem = ((p+tk) mod 28)%N
    /\ creach (d_flight (bsum ((2,2,J)%N :: pr)) tk
                 (drunway 0 (rev (c :: cs)) p rem b + T)%N)
         (wconf [] 0 (sdecode
            (lin_flat sg ((2,2,J)%N :: tail)) f))
         (wconf [] 0 (sdecode (lin_flat sg2 w2) f2)).
Proof.
  intros sg J tail f j p tk w1 sg1 nh rem emit sg2 w2 f2 T
    HG HJ Hj HCols HD HFull HB HFrame.
  pose proof HG as HG0.
  destruct HG as ((HOk & HPT) & HEdges & HW & HShape & HKeys & HPos).
  assert (HHead : is_spc
      (nth O ((2,2,J)%N::tail) d0) = false) by reflexivity.
  assert (HAlt : forall s, In s sg ->
      altb (sBody s) = true)
    by (exact (stable_altb sg ((2,2,J)%N::tail) HG0)).
  destruct (lin_bulk_checks
    sg ((2,2,J)%N::tail) j p tk _ HB)
    as (gb & EW & HKey & HLevel & HFloor & HEnd).
  destruct (site_layout ((2,2,J)%N::tail) j p gb HD EW HEnd)
    as (HLayout & HJRaw & HPost).
  destruct (detect_phase_form ((2,2,J)%N::tail) j p HD)
    as (Hp & HPhase).
  destruct (lin_bulk_tables
    sg ((2,2,J)%N::tail) j p tk w1 sg1 nh rem emit
    HW HShape HKeys HPos HHead HD HB)
    as (HW1 & HShape1 & HKeys1 & HPos1).
  destruct (lin_bulk_child_frame_data
    sg ((2,2,J)%N::tail) j p tk w1 sg1 nh rem emit gb
    (firstn j ((2,2,J)%N::tail))
    (skipn (S (j + phase_len p)) ((2,2,J)%N::tail))
    HW HOk HAlt HHead HLayout HJRaw HPost HKey Hp HFull HB HW1)
    as (PRE & POST & c & cs & b & HIn & HOut & HCoord & HLevels &
        HSafe & HPOST & Hb & HRem & HEmit & HRem28 & HView).
  assert (HjLen : (j <= length ((2,2,J)%N :: tail))%nat).
  { rewrite <- HJRaw. apply firstn_length_bound. }
  destruct (flat_cursor sg ((2,2,J)%N::tail) j HW HjLen)
    as (HFirst & HSkip).
  assert (EPrefix : lin_flat sg
      (firstn j ((2,2,J)%N::tail)) =
      PRE ++ runway (c :: cs)).
  { transitivity (firstn
      (fmapw sg ((2,2,J)%N::tail) O O j)
      (lin_flat sg ((2,2,J)%N::tail))).
    - symmetry. exact HFirst.
    - rewrite HCoord, HIn.
    unfold site.
    rewrite firstn_len_app. reflexivity. }
  destruct (flat_prefix_master_runway
    sg J tail j PRE c cs Hj EPrefix) as (pr & EPre).
  subst PRE.
  assert (EPrefixTail : lin_flat sg
      (firstn (j-1)%nat tail) =
      pr ++ runway (c :: cs)).
  { apply (flat_prefix_master_inv sg J tail j
      (pr ++ runway (c :: cs)) Hj).
    rewrite EPrefix. reflexivity. }
  assert (HFlatCols : forallb is_col
      (lin_flat sg (firstn (j-1)%nat tail)) = true).
  { apply flat_checked_prefix_cols.
    - exact HW.
    - exact (lin_generation_prefix_master
               J tail j HCols). }
  rewrite EPrefixTail in HFlatCols.
  rewrite forallb_app in HFlatCols.
  apply andb_prop in HFlatCols as [HPreCols HRunwayCols].
  assert (HprCols : forallb is_col pr = true)
    by exact HPreCols.
  assert (EFlatW : lin_flat sg ((2,2,J)%N::tail)
      = ((2,2,J)%N :: pr ++ runway (c :: cs))
        ++ phase_form p
        ++ gb :: lin_flat sg
                   (skipn (S (j + phase_len p))
                      ((2,2,J)%N::tail))).
  { transitivity (lin_flat sg
      (firstn j ((2,2,J)%N::tail) ++ phase_form p
       ++ gb :: skipn (S (j + phase_len p)) ((2,2,J)%N::tail))).
    { f_equal. exact HLayout. }
    rewrite lin_flat_app_c, EPrefix.
    rewrite lin_flat_app_c.
    rewrite (flat_phase_form sg p Hp).
    f_equal. f_equal.
    change (gb :: skipn (S (j + phase_len p)) ((2,2,J)%N::tail))
      with ([gb] ++ skipn (S (j + phase_len p)) ((2,2,J)%N::tail)).
    rewrite lin_flat_app_c.
    assert (EG : lin_flat sg [gb] = [gb]).
    { cbn [lin_flat]. unfold keyb. rewrite HKey. reflexivity. }
    rewrite EG. reflexivity. }
  assert (Egb : gb = (4,2,b + DBu p)%N).
  { rewrite HIn in EFlatW. unfold site in EFlatW.
    apply app_inv_head in EFlatW.
    apply app_inv_head in EFlatW.
    injection EFlatW as EGB _. symmetry. exact EGB. }
  destruct (lin_bulk_preserves_master
    sg J tail j p tk w1 sg1 nh rem emit Hj HD HB)
    as (tail1 & Ew1).
  assert (EWM : subst_at O 1 [(2,2,J+tk)%N] w1 =
      (2,2,J+tk)%N :: tail1) by (rewrite Ew1; reflexivity).
  destruct (lin_bulk_head_pos
    sg ((2,2,J)%N::tail) j p tk w1 sg1 nh rem emit
    Hj HHead HD HB) as (Hnh & HHead1).
  set (cur := (nh + phase_len rem)%nat).
  assert (Hcur : (1 <= cur)%nat).
  { unfold cur. pose proof (phase_len_pos rem). lia. }
  assert (ESkipMaster :
      skipn cur (subst_at O 1 [(2,2,J+tk)%N] w1) = skipn cur w1).
  { rewrite EWM, Ew1. destruct cur; [lia|reflexivity]. }
  assert (HViewM : schedule_frame_view
      (lin_sched_child nh rem emit p tk)
      (lin_flat sg1
        (skipn cur (subst_at O 1 [(2,2,J+tk)%N] w1)))
      (bulk_schedule p rem cs b)
      [(4,2,c - 3 + DBu rem)%N] POST).
  { rewrite ESkipMaster. exact HView. }
  destruct (scheduled_framec_output T
    (lin_sched_child nh rem emit p tk)
    sg1 (subst_at O 1 [(2,2,J+tk)%N] w1) f sg2 w2 f2
    (bulk_schedule p rem cs b)
    [(4,2,c - 3 + DBu rem)%N] POST
    HFrame HViewM) as (child & HTrips & HFinal).
  pose proof HView as HViewParts.
  unfold schedule_frame_view in HViewParts.
  destruct HViewParts as
    (HSlot & HLen & HSchedShape & HBaseCols & HSuffix0 & HGap).
  assert (HSuffix : lin_flat sg1 (skipn cur w1) =
      [(4,2,c - 3 + DBu rem)%N] ++
        crossed_post cs b POST).
  { unfold cur. rewrite bulk_schedule_stock in HSuffix0.
    unfold crossed_post in HSuffix0 |- *.
    rewrite app_nil_r in HSuffix0.
    repeat rewrite <- app_assoc in HSuffix0.
    exact HSuffix0. }
  assert (EPrefix1 : lin_flat sg1 (firstn cur w1) =
      (2,2,J)%N :: pr ++ phase_form rem).
  { pose proof (flat_firstn_skipn sg1 w1 cur) as EDec.
    rewrite HOut, HSuffix in EDec.
    unfold site in EDec.
    rewrite app_assoc in EDec.
    apply app_inv_tail in EDec. symmetry. exact EDec. }
  assert (EPrefix1' : lin_flat sg1 (firstn cur w1) =
      (2,2,J)%N :: (pr ++ phase_form rem)).
  { rewrite EPrefix1. reflexivity. }
  rewrite Ew1 in EPrefix1'.
  assert (EPrefixM0 : lin_flat sg1
      (firstn cur ((2,2,J+tk)%N::tail1)) =
      (2,2,J+tk)%N :: (pr ++ phase_form rem)).
  { exact (flat_firstn_master_change
             sg1 J (J+tk)%N tail1 cur
             (pr ++ phase_form rem) Hcur EPrefix1'). }
  assert (EPrefixM : lin_flat sg1
      (firstn cur (subst_at O 1 [(2,2,J+tk)%N] w1)) =
      (2,2,J+tk)%N :: (pr ++ phase_form rem)).
  { rewrite EWM. exact EPrefixM0. }
  set (tail2 := ((pr ++ phase_form rem) ++
    [(4,2,c - 3 + DBu rem)%N]) ++ child).
  assert (EFinal : lin_flat sg2 w2 = (2,2,J+tk)%N :: tail2).
  { change (lin_flat sg2 w2 =
      lin_flat sg1
        (firstn cur (subst_at O 1 [(2,2,J+tk)%N] w1)) ++
      [(4,2,c - 3 + DBu rem)%N] ++ child) in HFinal.
    unfold tail2.
    rewrite HFinal, EPrefixM.
    cbn [app]. f_equal.
    exact (app_assoc (pr ++ phase_form rem)
      [(4,2,c - 3 + DBu rem)%N] child). }
  destruct (sched_tripsc_factor
    (bulk_schedule p rem cs b) T
    POST child f f2 HTrips)
    as (child0 & f0 & HChild & EChild).
  pose proof (runway_scheduled_delivc cs c [] p rem b T POST child0 f f0
    eq_refl HSafe Hp HRem28 Hb HChild) as HRun.
  cbn [app] in HRun.
  change (wcolcost []) with 0%N in HRun.
  replace
    (N.to_nat (28 * N.of_nat (length (c :: cs)) + rem - p))
    with (N.to_nat tk) in HRun.
  2: { f_equal. rewrite HLevels, N2Nat.id, HRem.
       pose proof (N.div_mod' (p+tk) 28). lia. }
  assert (EEnd : sdec
      (phase_form rem ++
        (4,2,c - 3 + DBu rem)%N :: child0) f0 =
      sdec
        (phase_form rem ++
          (4,2,c - 3 + DBu rem)%N :: child) f2).
  { rewrite !sdec_app, !sdec_cons, EChild. reflexivity. }
  pose proof (deliv_sdec_right _ _ _ _ _ _ _ _ EEnd HRun) as HRun2.
  pose proof (deliv_master_creach (N.to_nat tk) _ J pr
    (runway (c :: cs) ++
      phase_form p ++
      (4,2,b + DBu p)%N :: POST)
    (phase_form rem ++
      (4,2,c - 3 + DBu rem)%N :: child) f f2
    (zpre_of_forallb pr HprCols) HJ HRun2) as HSound.
  rewrite N2Nat.id in HSound.
  exists pr, c, b, cs.
  split; [exact HprCols|].
  split; [exact EPrefix|].
  split; [exact HLevels|].
  split; [exact HSafe|].
  split; [rewrite EW, Egb; reflexivity|].
  split; [exact HRem|].
  rewrite d_flight_eq.
  eapply creach_sdecode; [| |exact HSound].
  - rewrite HIn. unfold site.
    f_equal; cbn [app]; repeat rewrite app_assoc; cbn [app]; reflexivity.
  - rewrite EFinal. unfold tail2.
    f_equal; cbn [app]; repeat rewrite <- app_assoc; cbn [app]; reflexivity.
Qed.
Lemma wcolcost_ccolcost (w : word) :
  wcolcost w = ccolcost w.
Proof. induction w as [|g t IH]; cbn [wcolcost ccolcost];
       congruence. Qed.
