Definition FlightDomC_cmeas (sg : list seg) (cw : word) (f : N) : N :=
  gmeas (lin_flat sg cw) f.
Definition phd (p : N) : N :=
  (ccolcost (phase_form p) + 14 * DBu p)%N.
Lemma ccolcost_rung1 (c : N) :
  ccolcost (rung1 c) = (14 * c + 22)%N.
Proof.
  unfold rung1. cbn [ccolcost gC gO fst snd]. lia.
Qed.
Lemma ccolcost_runway (l : list N) :
  ccolcost (runway l) = wcolsum l.
Proof.
  induction l as [|c r IH]; [reflexivity|].
  cbn [runway wcolsum].
  rewrite ccolcost_app, ccolcost_rung1, IH. lia.
Qed.
Lemma ccolcost_crossed_post (cs : list N) (b : N) (post : word) :
  ccolcost (crossed_post cs b post)
  = (wcolsum (map dec4 cs) + (14 * (b - 1) + 22)
     + ccolcost post)%N.
Proof.
  unfold crossed_post.
  rewrite !ccolcost_app, ccolcost_runway, ccolcost_rung1. lia.
Qed.
Lemma ccolcost_site (pre : word) (p c : N) (post : word) :
  ccolcost (site pre p c post)
  = (ccolcost pre + ccolcost (phase_form p)
     + 14 * c + ccolcost post)%N.
Proof.
  unfold site.
  rewrite !ccolcost_app, ccolcost_cons.
  unfold ccg. cbn [gC gO fst snd]. lia.
Qed.
Lemma wcolsum_cons (c : N) (r : list N) :
  wcolsum (c :: r) = (14 * c + 22 + wcolsum r)%N.
Proof. reflexivity. Qed.
Lemma wcolsum_dec4 (cs : list N) :
  Forall (fun x => (4 <= x)%N) cs ->
  (wcolsum (map dec4 cs) + 56 * N.of_nat (length cs)
   = wcolsum cs)%N.
Proof.
  induction cs as [|c r IH]; intros HF; [reflexivity|].
  pose proof (Forall_inv HF) as Hc. cbv beta in Hc.
  pose proof (Forall_inv_tail HF) as HR.
  specialize (IH HR).
  cbn [map length]. rewrite !wcolsum_cons. rewrite Nat2N.inj_succ.
  assert (E : (14 * dec4 c + 56 = 14 * c)%N)
    by (unfold dec4; lia).
  lia.
Qed.
Definition pgrid : list N := map N.of_nat (seq 0 28).
Lemma in_pgrid (p : N) : (p < 28)%N -> In p pgrid.
Proof.
  intros H. unfold pgrid.
  replace p with (N.of_nat (N.to_nat p)) at 1 by apply N2Nat.id.
  apply in_map. apply in_seq. lia.
Qed.
Lemma phd_hi_b : forallb (fun p => (phd p + 2 * p <=? 74)%N) pgrid = true.
Proof. vm_compute. reflexivity. Qed.
Lemma phd_hi (p : N) : (p < 28)%N -> (phd p + 2 * p <= 74)%N.
Proof.
  intros H.
  pose proof (proj1 (forallb_forall _ pgrid) phd_hi_b p (in_pgrid p H)) as HB.
  apply N.leb_le in HB. exact HB.
Qed.
Theorem lin_bulk_ccol
        (sg : list seg) (w : word) (j : nat) (p t : N)
        (w' : word) (sg' : list seg) (nh : nat) (rem emit : N)
        (gb : bg) (pre post : word) :
  sg_wf sg ->
  lin_ok sg w = true ->
  (forall s, In s sg -> altb (sBody s) = true) ->
  is_spc (nth O w d0) = false ->
  w = pre ++ phase_form p ++ gb :: post ->
  length pre = j -> post <> [] -> keyi sg gb = None ->
  (p < 28)%N ->
  Nat.eqb (N.to_nat ((p + t) / 28)) O = false ->
  lin_bulk sg w j p t = Some (w', sg', nh, rem, emit) ->
  rem = ((p + t) mod 28)%N
  /\ emit = (marks (p + t) - marks p)%N
  /\ (ccolcost (lin_flat sg' w') + phd p + 56 * ((p + t) / 28)
      = ccolcost (lin_flat sg w) + phd rem)%N.
Proof.
  intros HW HOk HAlt HHead HLay HLen HPost HKey Hp HFull HB.
  destruct (lin_bulk_ledger sg w j p t w' sg' nh rem emit gb pre post
              HW HOk HAlt HHead HLay HLen HPost HKey Hp HFull HB)
    as (PRE & POST & c & cs & b & EIn & EOut & _ & _ & HLn & HSafe
        & _ & Hb & HRem & HEmit).
  split; [exact HRem|]. split; [exact HEmit|].
  assert (HcsB : Forall (fun x => (4 <= x)%N) cs).
  { pose proof (Forall_inv_tail HSafe) as HR.
    revert HR. apply Forall_impl. unfold FLOOR. lia. }
  assert (Hc : (43 <= c)%N).
  { pose proof (Forall_inv HSafe) as Hx.
    unfold FLOOR in Hx. lia. }
  assert (HbF : (40 <= b)%N) by (unfold FLOOR in Hb; lia).
  assert (HLnN : N.of_nat (length (c :: cs)) = ((p + t) / 28)%N).
  { rewrite HLn. apply N2Nat.id. }
  rewrite EIn, EOut, !ccolcost_site.
  rewrite ccolcost_app, ccolcost_runway.
  rewrite ccolcost_crossed_post.
  pose proof (wcolsum_dec4 cs HcsB) as HD4.
  rewrite wcolsum_cons.
  cbn [length] in HLnN. rewrite Nat2N.inj_succ in HLnN.
  unfold phd. lia.
Qed.
Lemma subst_master (J t : N) (tail : word) :
  subst_at O 1 [(2,2,J + t)%N] ((2,2,J)%N :: tail)
  = ((2,2,J + t)%N :: tail).
Proof. reflexivity. Qed.
Lemma ccol_master_bump (sg : list seg) (J t : N) (tail : word) :
  ccolcost (lin_flat sg ((2,2,J + t)%N :: tail))
  = (ccolcost (lin_flat sg ((2,2,J)%N :: tail)) + 10 * t)%N.
Proof.
  rewrite !lin_flat_master, !ccolcost_cons.
  unfold ccg. cbn [gC gO fst snd]. lia.
Qed.
Lemma stable_bulk_hyps (sg : list seg) (cw : word) :
  stable_guard sg cw ->
  sg_wf sg /\ lin_ok sg cw = true
  /\ (forall s, In s sg -> altb (sBody s) = true).
Proof.
  intros HS. pose proof (stable_altb sg cw HS) as HA.
  destruct HS as ((HOk & _) & _ & HW & _ & _ & _).
  repeat split; assumption.
Qed.
Theorem bulk_master_ccol
        (sg : list seg) (J : N) (tail : word) (f : N)
        (j : nat) (p t : N) (w1 : word) (sg1 : list seg)
        (nh : nat) (rem emit : N) :
  stable_guard sg ((2,2,J)%N :: tail) ->
  (1 <= j)%nat ->
  detect_phase ((2,2,J)%N :: tail) j = Some p ->
  Nat.eqb (N.to_nat ((p + t) / 28)) O = false ->
  lin_bulk sg ((2,2,J)%N :: tail) j p t = Some (w1, sg1, nh, rem, emit) ->
  rem = ((p + t) mod 28)%N
  /\ emit = (marks (p + t) - marks p)%N
  /\ (p < 28)%N
  /\ (FlightDomC_cmeas sg1 (subst_at O 1 [(2,2,J + t)%N] w1) f
        + phd p + 56 * ((p + t) / 28)
      = FlightDomC_cmeas sg ((2,2,J)%N :: tail) f + phd rem + 10 * t)%N.
Proof.
  intros HS Hj HD HFull HB.
  destruct (stable_bulk_hyps _ _ HS) as (HW & HOk & HAlt).
  assert (HHead : is_spc (nth O ((2,2,J)%N :: tail) d0) = false)
    by reflexivity.
  destruct (lin_bulk_checks sg _ j p t _ HB)
    as (gb & EW & HKey & _ & _ & HEnd).
  destruct (site_layout _ j p gb HD EW HEnd) as (HLay & HLen & HPost).
  destruct (detect_phase_form _ j p HD) as (Hp & _).
  destruct (lin_bulk_ccol sg _ j p t w1 sg1 nh rem emit gb
              (firstn j ((2,2,J)%N :: tail))
              (skipn (S (j + phase_len p)) ((2,2,J)%N :: tail))
              HW HOk HAlt HHead HLay HLen HPost HKey Hp HFull HB)
    as (HRem & HEm & HId).
  destruct (lin_bulk_preserves_master sg J tail j p t w1 sg1 nh rem emit
              Hj HD HB) as (tail1 & E1).
  split; [exact HRem|]. split; [exact HEm|]. split; [exact Hp|].
  unfold FlightDomC_cmeas, gmeas.
  rewrite E1, subst_master, (ccol_master_bump sg1 J t tail1).
  rewrite E1 in HId. lia.
Qed.
Definition cascticks (st : list lsc_frame) : N :=
  fold_right (fun fr a => (lsTicks fr + a)%N) 0%N st.
Definition CascDom : Prop :=
  forall (fu : nat) (sg : list seg) (ps : atab) (w : word) (f : N)
         (st : list lsc_frame) (w' : word) (sg' : list seg)
         (ps' : atab) (f' : N),
    lin_casc_safe_at fu sg ps w f st = Some (w', sg', ps', f') ->
    (FlightDomC_cmeas sg w f <= FlightDomC_cmeas sg' w' f' + 8 * cascticks st)%N.
Lemma emt_le3_b : forallb (fun p => (EMt p <=? 3)%N) pgrid = true.
Proof. vm_compute. reflexivity. Qed.
Lemma emt_grid_b :
  forallb (fun p => (10 * p <=? 248 + 8 * EMt p)%N) pgrid = true.
Proof. vm_compute. reflexivity. Qed.
Lemma emt_le3 (p : N) : (p < 28)%N -> (EMt p <= 3)%N.
Proof.
  intros H.
  pose proof (proj1 (forallb_forall _ pgrid) emt_le3_b p (in_pgrid p H)) as HB.
  apply N.leb_le in HB. exact HB.
Qed.
Lemma emt_grid (p : N) :
  (p < 28)%N -> (10 * p <= 248 + 8 * EMt p)%N.
Proof.
  intros H.
  pose proof (proj1 (forallb_forall _ pgrid) emt_grid_b p (in_pgrid p H)) as HB.
  apply N.leb_le in HB. exact HB.
Qed.
Lemma marks_full (Ln : N) : marks (28 * Ln) = (4 * Ln)%N.
Proof.
  unfold marks.
  rewrite (N.mul_comm 28 Ln).
  rewrite (N.div_mul Ln 28) by discriminate.
  rewrite (N.mod_mul Ln 28) by discriminate.
  assert (E0 : EMt 0 = 0%N) by reflexivity.
  rewrite E0. lia.
Qed.
Lemma marks_small (p : N) : (p < 28)%N -> marks p = EMt p.
Proof.
  intros H. unfold marks.
  rewrite (N.div_small p 28 H), (N.mod_small p 28 H). lia.
Qed.
Lemma casc_fits (p t Ln emit : N) :
  (p < 28)%N -> (1 <= Ln)%N -> (28 * Ln = p + t)%N ->
  emit = (marks (p + t) - marks p)%N ->
  (8 * emit <= 10 * t)%N.
Proof.
  intros Hp HL HE HEm.
  rewrite <- HE in HEm. rewrite marks_full, (marks_small p Hp) in HEm.
  pose proof (emt_le3 p Hp) as H3.
  pose proof (emt_grid p Hp) as HG.
  lia.
Qed.
Lemma some_inj {A : Type} (a b : A) : Some a = Some b -> a = b.
Proof. intros H. injection H as H. exact H. Qed.
Lemma phd0 : phd 0 = 74%N.
Proof. vm_compute. reflexivity. Qed.
Lemma cascticks_one (fr : lsc_frame) : cascticks [fr] = lsTicks fr.
Proof. cbn [cascticks fold_right]. lia. Qed.
Lemma keyb_nine (sg : list seg) (g : bg) :
  (gO g =? 9)%N = false -> keyb sg g = None.
Proof.
  intros H. unfold keyb, keyi, phshape, tagbase, PHO.
  rewrite H. cbn [andb]. reflexivity.
Qed.
Lemma lin_flat_lit (sg : list seg) (l : word) :
  forallb (fun g => negb ((gO g =? 9)%N)) l = true ->
  lin_flat sg l = l.
Proof.
  induction l as [|g t IH]; [reflexivity|].
  cbn [forallb]. intros H. apply andb_prop in H as (H1 & H2).
  apply negb_true_iff in H1.
  cbn [lin_flat]. rewrite (keyb_nine sg g H1), (IH H2). reflexivity.
Qed.
Lemma FlightDomC_lin_flat_cons_ccol (sg : list seg) (g : bg) (t : word) :
  ccolcost (lin_flat sg (g :: t))
  = ((match keyb sg g with
      | Some b => ccolcost b
      | None => ccg g
      end) + ccolcost (lin_flat sg t))%N.
Proof.
  cbn [lin_flat]. destruct (keyb sg g);
    [apply ccolcost_app|apply ccolcost_cons].
Qed.
Lemma ccol_pref (sg : list seg) (a b : word) :
  ccolcost (lin_flat sg (a ++ b))
  = (ccolcost (lin_flat sg a) + ccolcost (lin_flat sg b))%N.
Proof. rewrite lin_flat_app_c, ccolcost_app. reflexivity. Qed.
Lemma tick_mid_dom (sg : list seg) (A Min Mout rest : word) :
  forallb (fun g => negb ((gO g =? 9)%N)) Min = true ->
  forallb (fun g => negb ((gO g =? 9)%N)) Mout = true ->
  (ccolcost Min <= ccolcost Mout + 60)%N ->
  (ccolcost (lin_flat sg (A ++ Min ++ rest))
   <= ccolcost (lin_flat sg (A ++ Mout ++ rest)) + 60)%N.
Proof.
  intros H1 H2 H3.
  rewrite !ccol_pref, (lin_flat_lit sg Min H1), (lin_flat_lit sg Mout H2). lia.
Qed.
Lemma tick_key (sg : list seg) (cN q f : N) (tail w1 A Min Mout R : word) :
  forallb (fun g => negb ((gO g =? 9)%N)) Min = true ->
  forallb (fun g => negb ((gO g =? 9)%N)) Mout = true ->
  (ccolcost Min <= ccolcost Mout + 60)%N ->
  tail = A ++ Min ++ R ->
  w1 = (2,2,cN)%N :: (A ++ Mout ++ R) ->
  (27 <= q)%N ->
  (FlightDomC_cmeas sg ((2,2,cN)%N :: tail) f + 210
   <= FlightDomC_cmeas sg (subst_at O 1 [(2,2,cN + q)%N] w1) f)%N.
Proof.
  intros H1 H2 H3 Et Ew Hq. subst tail w1. rewrite subst_master.
  unfold FlightDomC_cmeas, gmeas.
  rewrite !FlightDomC_lin_flat_cons_ccol.
  rewrite (keyb_nine sg (2,2,cN)%N eq_refl),
          (keyb_nine sg (2,2,cN + q)%N eq_refl).
  pose proof (tick_mid_dom sg A Min Mout R H1 H2 H3) as HB.
  unfold ccg. cbn [gC gO fst snd]. lia.
Qed.
Lemma tick_stage_dom (sg : list seg) (cN : N) (tail : word)
      (w1 : word) (i : nat) (q : N) (j2 : nat) (rem emit f : N) :
  detect_phase ((2,2,cN)%N :: tail) i = Some 0%N ->
  lin_tick_front_stage ((2,2,cN)%N :: tail) i
    = Some (q, w1, j2, rem, emit) ->
  (FlightDomC_cmeas sg ((2,2,cN)%N :: tail) f + 210
   <= FlightDomC_cmeas sg (subst_at O 1 [(2,2,cN + q)%N] w1) f)%N
  /\ (emit <= 4)%N /\ (27 <= q)%N.
Proof.
  intros HD HSt.
  destruct (tick_stage_site _ i q w1 j2 rem emit HSt) as [E|[E|E]];
    subst i.
  - destruct (tick_stage_5 _ q w1 j2 rem emit HSt)
      as [a0 a1 a2 a3 a4 cg rest Ew Ew1 _ Hcg Eq _ _ Ee].
    unfold FLOOR in Hcg.
    injection Ew as Ea0 Et. subst a0.
    split; [|split; [lia|lia]].
    refine (tick_key sg cN q f _ w1 [a1;a2;a3;a4]
              [(7,1,1)%N;(3,2,1)%N;(4,2,cg)%N]
              [(4,3,1)%N;(4,2,cg-3)%N] rest
              eq_refl eq_refl _ Et Ew1 ltac:(lia)).
    cbn [ccolcost gC gO fst snd]. lia.
  - destruct (tick_stage_6 _ q w1 j2 rem emit HD HSt)
      as (a0 & a1 & a2 & a3 & c & cg & rest & Ew & Ew1 & _ & Hc & Hcg
          & Eq & _ & _ & Ee).
    unfold FLOOR in Hcg.
    injection Ew as Ea0 Et. subst a0.
    split; [|split; [lia|lia]].
    refine (tick_key sg cN q f _ w1 [a1;a2;a3]
              [(8,2,1)%N;(4,2,c)%N;(7,1,1)%N;(3,2,1)%N;(4,2,cg)%N]
              [(7,1,1)%N;(3,2,1)%N;(4,2,c)%N;(8,2,1)%N;(4,2,cg-4)%N] rest
              eq_refl eq_refl _ Et Ew1 ltac:(lia)).
    cbn [ccolcost gC gO fst snd]. lia.
  - destruct (tick_stage_7 _ q w1 j2 rem emit HSt)
      as [a0 a1 a2 a3 a4 c cg rest Ew Ew1 _ Hc Hcg Eq _ _ Ee].
    unfold FLOOR in Hcg.
    injection Ew as Ea0 Et. subst a0.
    split; [|split; [lia|lia]].
    refine (tick_key sg cN q f _ w1 [a1;a2;a3;a4]
              [(8,2,1)%N;(4,2,c)%N;(7,1,1)%N;(3,2,1)%N;(4,2,cg)%N]
              [(7,1,1)%N;(3,2,1)%N;(4,2,c)%N;(8,2,1)%N;(4,2,cg-4)%N] rest
              eq_refl eq_refl _ Et Ew1 ltac:(lia)).
    cbn [ccolcost gC gO fst snd]. lia.
Qed.
Lemma at_safe_or_id (sg : list seg) (i j2 : nat) (w1 w1' : word) :
  (if Nat.eqb i 6 then lin_at_safe sg w1 j2 else Some w1) = Some w1' ->
  w1' = w1.
Proof.
  destruct (Nat.eqb i 6); intros H;
    [exact (lin_at_safe_some sg w1 j2 w1' H)
    |injection H as H; exact (eq_sym H)].
Qed.
Local Open Scope N_scope.
Local Open Scope bool_scope.
Local Open Scope sym.
Local Open Scope N_scope.
Local Open Scope bool_scope.
Local Open Scope sym.
Local Open Scope N_scope.
Opaque FLAT_ROUND_FUEL LROUND_FUEL LROUND_CHUNKS
       CFUEL TRIES.
Notation CascCoreW_cmeas := FlightDomC_cmeas.
Notation CascCoreW_cascticks := cascticks.
Definition LadderDom : Prop :=
  forall (sg : list seg) (w : word) (f : N)
         (basec lc gap : nat) (slot take : N)
         (lw2 : word) (f2 : N),
    lin_bottom_sched_zrun (N.to_nat take) lc sg (skipn basec w) f gap slot
      = Some (lw2, f2) ->
    (CascCoreW_cmeas sg w f
       <= CascCoreW_cmeas sg (setsfx basec w lw2) f2 + 8 * take)%N.
Definition BulkDom : Prop :=
  forall (sg : list seg) (w : word) (f : N) (tg : nat)
         (pk take : N) (w2 : word) (sg2 : list seg) (t2 : nat)
         (p2k ek : N) (w3 : word),
    lin_bulk sg w tg pk take = Some (w2, sg2, t2, p2k, ek) ->
    lin_at_safe sg2 w2 t2 = Some w3 ->
    (CascCoreW_cmeas sg w f + 8 * ek <= CascCoreW_cmeas sg2 w3 f + 8 * take)%N.
Definition DirectDom : Prop :=
  forall (sg : list seg) (w : word) (f : N) (cur : nat)
         (cols2 s3 sfx : word) (renewed : bool) (f2 : N)
         (w2 : word),
    seek (skipn cur w) = (cols2, s3) ->
    lin_dtick_after_seek cols2 s3 f = Some (renewed, sfx, f2) ->
    (if Nat.eqb cur O then Some sfx
     else lin_join_safe sg (firstn cur w) sfx) = Some w2 ->
    (CascCoreW_cmeas sg w f <= CascCoreW_cmeas sg w2 f2 + 8)%N.
Ltac wdig H :=
  repeat (match type of H with
          | (if ?b then _ else _) = _ =>
              lazymatch b with
              | context [if _ then _ else _] => fail
              | context [match _ with _ => _ end] => fail
              | _ => destruct b eqn:?
              end
          | match ?x with _ => _ end = _ =>
              lazymatch x with
              | context [if _ then _ else _] => fail
              | context [match _ with _ => _ end] => fail
              | _ => destruct x eqn:?
              end
          end; try discriminate).
Lemma nmin_le (tk : N) (k : nat) :
  (N.of_nat (Nat.min (N.to_nat tk) k) <= tk)%N.
Proof. rewrite Nat2N.inj_min, N2Nat.id. apply N.le_min_l. Qed.
Lemma bottom_take_le (cols s3 : word) (f tk take : N) :
  lin_bottom_take cols s3 f tk = Some take -> (take <= tk)%N.
Proof.
  intros H. unfold lin_bottom_take in H. cbv beta zeta in H.
  lazymatch type of H with
  | match ?x with _ => _ end = _ => destruct x as [[p F]|] eqn:EP
  end; [|discriminate].
  cbv beta iota zeta in H.
  wdig H.
  all: (try discriminate H); (try (injection H as <-)); apply nmin_le.
Qed.
Lemma bulk_take_le (sg : list seg) (w : word) (cur tg : nat)
      (pk tk : N) :
  (lin_bulk_take sg w cur tg pk tk <= tk)%N.
Proof.
  unfold lin_bulk_take. cbv beta zeta.
  destruct (Nat.eqb _ O); apply N.le_min_l.
Qed.
Lemma cascticks_cons (fr : lsc_frame) (rest : list lsc_frame) :
  CascCoreW_cascticks (fr :: rest) = (lsTicks fr + CascCoreW_cascticks rest)%N.
Proof. reflexivity. Qed.
Lemma ticks_advance (fr : lsc_frame) (take : N) :
  lsTicks (lin_sched_advance fr take) = (lsTicks fr - take)%N.
Proof. reflexivity. Qed.
Lemma ticks_advance_one (fr : lsc_frame) :
  lsTicks (lin_sched_advance_one fr) = (lsTicks fr - 1)%N.
Proof. reflexivity. Qed.
Lemma ticks_child (j : nat) (rem emit p take : N) :
  lsTicks (lin_sched_child j rem emit p take) = emit.
Proof. reflexivity. Qed.
Theorem cascdom_of (HLad : LadderDom) (HBulk : BulkDom) (HDir : DirectDom)
  : CascDom.
Proof.
  intros fu. induction fu as [|fu IH];
    intros sg ps w f st w' sg' ps' f' H; [discriminate|].
  cbn [lin_casc_safe_at] in H. cbv beta zeta in H.
  destruct st as [|fr rest].
  { injection H as <- <- _ <-. cbn [cascticks]. lia. }
  destruct (lsTicks fr =? 0)%N eqn:ETK.
  { pose proof (IH sg ps w f rest w' sg' ps' f' H) as HR.
    rewrite cascticks_cons. apply N.eqb_eq in ETK. rewrite ETK. lia. }
  apply N.eqb_neq in ETK.
  assert (HTK : (1 <= lsTicks fr)%N) by lia.
  destruct (seek (skipn (lsCur fr) w)) as [cols2 s3] eqn:ESK.
  destruct s3 as [|g3 s3t]; [discriminate|].
  destruct (lin_bottom_take cols2 (g3 :: s3t) f (lsTicks fr))
    as [take|] eqn:EBT.
  -
    pose proof (bottom_take_le _ _ _ _ _ EBT) as HLE.
    destruct (lin_bottom_sched_zrun (N.to_nat take)
                (lsCur fr - (lsCur fr - 2))%nat sg
                (skipn (lsCur fr - 2)%nat w) f (lsGap fr) (lsSlot fr))
      as [[lw2 f2]|] eqn:EZ; [|discriminate].
    destruct (relocate_all sg ps
                (setsfx (lsCur fr - 2)%nat w lw2)) as [ps2|]
      eqn:ER; [|discriminate].
    destruct (lin_guard_at sg ps2
                (setsfx (lsCur fr - 2)%nat w lw2)) eqn:EG;
      [|discriminate].
    pose proof (IH sg ps2 (setsfx (lsCur fr - 2)%nat w lw2) f2
                  (lin_sched_advance fr take :: rest)
                  w' sg' ps' f' H) as HR.
    pose proof (HLad sg w f (lsCur fr - 2)%nat
                  (lsCur fr - (lsCur fr - 2))%nat (lsGap fr)
                  (lsSlot fr) take lw2 f2 EZ) as HA.
    rewrite cascticks_cons in HR |- *.
    rewrite ticks_advance in HR. lia.
  -
    lazymatch type of H with
    | match ?x with _ => _ end = _ =>
        destruct x as [[[[[[[w2 sg2] t2] p2k] ek] take] pk]|] eqn:EBK
    end.
    +
      assert (HBK : lin_bulk sg w (lsCur fr + length cols2)%nat pk take
                    = Some (w2, sg2, t2, p2k, ek)
                    /\ (take <= lsTicks fr)%N).
      { revert EBK.
        destruct (Nat.ltb (lsCur fr + 2) (lsCur fr + length cols2));
          [|discriminate].
        destruct (detect_phase (g3 :: s3t) O) as [pk0|];
          [|discriminate].
        cbv beta zeta.
        destruct (THRESH <=?
                    lin_bulk_take sg w (lsCur fr)
                      (lsCur fr + length cols2)%nat pk0 (lsTicks fr))%N;
          [|discriminate].
        destruct (lin_bulk sg w (lsCur fr + length cols2)%nat pk0
                    (lin_bulk_take sg w (lsCur fr)
                       (lsCur fr + length cols2)%nat pk0 (lsTicks fr)))
          as [[[[[wq sgq] tq] pq] eq0]|] eqn:EBL; [|discriminate].
        intros EE. injection EE as <- <- <- <- <- <- <-.
        split; [exact EBL|apply bulk_take_le]. }
      destruct HBK as (HBK & HLE).
      destruct (negb (lin_sched_bulk_safe fr (lin_flen sg cols2) pk take))
        eqn:ESF; [discriminate|].
      destruct (lin_at_safe sg2 w2 t2) as [w3|] eqn:EAS; [|discriminate].
      destruct (locate_all sg2 w3) as [ps2|] eqn:ELO; [|discriminate].
      destruct (lin_guard_at sg2 ps2 w3) eqn:EG; [|discriminate].
      pose proof (IH sg2 ps2 w3 f
                    (lin_sched_child t2 p2k ek pk take
                     :: lin_sched_advance fr take :: rest)
                    w' sg' ps' f' H) as HR.
      pose proof (HBulk sg w f (lsCur fr + length cols2)%nat pk take
                    w2 sg2 t2 p2k ek w3 HBK EAS) as HA.
      rewrite !cascticks_cons in HR. rewrite cascticks_cons.
      rewrite ticks_advance, ticks_child in HR. lia.
    +
      lazymatch type of H with
      | match ?x with _ => _ end = _ =>
          destruct x as [[[renewed sfx] f2]|] eqn:EDT
      end; [|discriminate].
      assert (HW2 : exists w2 ps2,
        (if Nat.eqb (lsCur fr) O then Some sfx
         else lin_join_safe sg (firstn (lsCur fr) w) sfx) = Some w2
        /\ lin_casc_safe_at fu sg ps2 w2 f2
             (lin_sched_advance_one fr :: rest)
           = Some (w', sg', ps', f')).
      { revert H. destruct renewed.
        - destruct (negb (Nat.leb (lsGap fr + 2) (lin_flen sg cols2)));
            [discriminate|].
          destruct (if Nat.eqb (lsCur fr) O then Some sfx
                    else lin_join_safe sg (firstn (lsCur fr) w) sfx)
            as [wq|] eqn:EJ; [|discriminate].
          destruct (if lin_same_length w wq then Some ps
                    else relocate_all sg ps wq) as [psq|] eqn:EP2;
            [|discriminate].
          destruct (lin_guard_at sg psq wq) eqn:EG; [|discriminate].
          intros HH. exists wq, psq. split; [reflexivity|exact HH].
        - destruct (if Nat.eqb (lsCur fr) O then Some sfx
                    else lin_join_safe sg (firstn (lsCur fr) w) sfx)
            as [wq|] eqn:EJ; [|discriminate].
          destruct (if lin_same_length w wq then Some ps
                    else relocate_all sg ps wq) as [psq|] eqn:EP2;
            [|discriminate].
          destruct (lin_guard_at sg psq wq) eqn:EG; [|discriminate].
          intros HH. exists wq, psq. split; [reflexivity|exact HH]. }
      destruct HW2 as (w2 & ps2 & EJ & HH).
      pose proof (IH sg ps2 w2 f2 (lin_sched_advance_one fr :: rest)
                    w' sg' ps' f' HH) as HR.
      pose proof (HDir sg w f (lsCur fr) cols2 (g3 :: s3t) sfx renewed f2 w2
                    ESK EDT EJ) as HA.
      rewrite cascticks_cons in HR |- *.
      rewrite ticks_advance_one in HR. lia.
Qed.
