Local Open Scope N_scope.
Opaque FLAT_ROUND_FUEL LROUND_FUEL LROUND_CHUNKS
       CFUEL TRIES.
Notation CascW28_cmeas := FlightDomC_cmeas.
Theorem dtick_after_seek_grow (cols2 s3 : word) (f : N)
        (renewed : bool) (sfx : word) (f2 : N) :
  lin_dtick_after_seek cols2 s3 f = Some (renewed, sfx, f2) ->
  ccolcost cols2 + ccolcost s3 + 2 * f
    <= ccolcost sfx + 2 * f2 + 8.
Proof.
  intros HH. unfold lin_dtick_after_seek in HH.
  destruct (renew_seg (length s3) cols2 s3 f) as [[body fb]|] eqn:ER.
  { injection HH as HA HB HC. subst renewed sfx f2.
    pose proof (proj2 (casc_grow (length s3))
                  cols2 s3 f body fb ER) as HG.
    lia. }
  destruct s3 as [|g3 s3t].
  {
    change (leaf_act (@nil bg) f) with (@None (word * N)) in HH.
    discriminate. }
  destruct g3 as [[o7 z7] c7].
  destruct ((z7 =? 3) && (c7 =? 1))%N eqn:E31.
  -
    match type of HH with
    | context [fire_comp ?n ?ss ?ff] =>
        destruct (fire_comp n ss ff) as [[s3' fq]|] eqn:EF
    end; [|discriminate].
    injection HH as HA HB HC. subst renewed sfx f2.
    match type of EF with
    | fire_comp ?n ?ss ?ff = _ =>
        pose proof (proj1 (casc_grow n) ss ff s3' fq EF) as HG
    end.
    rewrite ccolcost_app. lia.
  -
    match type of HH with
    | context [sand_leaf ?ss] => destruct (sand_leaf ss) eqn:ESL
    end; [discriminate|].
    match type of HH with
    | context [leaf_act ?ss ?ff] =>
        destruct (leaf_act ss ff) as [[s3' fq]|] eqn:EL
    end; [|discriminate].
    injection HH as HA HB HC. subst renewed sfx f2.
    pose proof (leaf_grow _ _ _ _ EL) as HG.
    rewrite ccolcost_app. lia.
Qed.
Lemma CascW28_lin_flat_nil (w : word) : lin_flat [] w = w.
Proof.
  induction w as [|g t IH]; [reflexivity|].
  cbn [lin_flat]. unfold keyb, keyi.
  destruct (phshape g); cbn [sFlat]; rewrite IH; reflexivity.
Qed.
Lemma fcc_nil (sg : list seg) :
  ccolcost (lin_flat sg []) = 0.
Proof. reflexivity. Qed.
Lemma direct_out_shape (sg : list seg) (w sfx w2 : word) (cur : nat) :
  (if Nat.eqb cur O then Some sfx
   else lin_join_safe sg (firstn cur w) sfx) = Some w2 ->
  w2 = firstn cur w ++ sfx.
Proof.
  destruct (Nat.eqb cur O) eqn:EC.
  - apply PeanoNat.Nat.eqb_eq in EC. subst cur.
    intros HH. injection HH as <-. reflexivity.
  - exact (lin_join_safe_some _ _ _ _).
Qed.
Lemma direct_ccol_split (sg : list seg) (w : word) (cur : nat)
      (cols2 s3 sfx w2 : word) :
  seek (skipn cur w) = (cols2, s3) ->
  (if Nat.eqb cur O then Some sfx
   else lin_join_safe sg (firstn cur w) sfx) = Some w2 ->
  ccolcost (lin_flat sg w)
    = ccolcost (lin_flat sg (firstn cur w))
      + (ccolcost (lin_flat sg cols2)
         + ccolcost (lin_flat sg s3))
  /\ ccolcost (lin_flat sg w2)
    = ccolcost (lin_flat sg (firstn cur w))
      + ccolcost (lin_flat sg sfx).
Proof.
  intros ESK EJ.
  destruct (seek_split _ _ _ ESK) as [ESP _].
  split.
  - rewrite <- (firstn_skipn cur w) at 1.
    rewrite ccol_pref, ESP, ccol_pref. reflexivity.
  - rewrite (direct_out_shape sg w sfx w2 cur EJ).
    rewrite ccol_pref. reflexivity.
Qed.
Definition DirectDomLit : Prop :=
  forall (sg : list seg) (w : word) (f : N) (cur : nat)
         (cols2 s3 sfx : word) (renewed : bool) (f2 : N)
         (w2 : word),
    seek (skipn cur w) = (cols2, s3) ->
    lin_dtick_after_seek cols2 s3 f = Some (renewed, sfx, f2) ->
    (if Nat.eqb cur O then Some sfx
     else lin_join_safe sg (firstn cur w) sfx) = Some w2 ->
    lin_flat sg cols2 = cols2 ->
    lin_flat sg s3 = s3 ->
    lin_flat sg sfx = sfx ->
    (CascW28_cmeas sg w f <= CascW28_cmeas sg w2 f2 + 8)%N.
Theorem direct_dom_of_lit : DirectDomLit.
Proof.
  intros sg w f cur cols2 s3 sfx renewed f2 w2 ESK EDT EJ H1 H2 H3.
  destruct (direct_ccol_split sg w cur cols2 s3 sfx w2 ESK EJ) as [EA EB].
  pose proof (dtick_after_seek_grow cols2 s3 f renewed sfx f2 EDT) as HG.
  unfold CascW28_cmeas, gmeas.
  rewrite EA, EB, H1, H2, H3 in *.
  lia.
Qed.
Theorem direct_dom_nil :
  forall (w : word) (f : N) (cur : nat)
         (cols2 s3 sfx : word) (renewed : bool) (f2 : N)
         (w2 : word),
    seek (skipn cur w) = (cols2, s3) ->
    lin_dtick_after_seek cols2 s3 f = Some (renewed, sfx, f2) ->
    (if Nat.eqb cur O then Some sfx
     else lin_join_safe [] (firstn cur w) sfx) = Some w2 ->
    (CascW28_cmeas [] w f <= CascW28_cmeas [] w2 f2 + 8)%N.
Proof.
  intros w f cur cols2 s3 sfx renewed f2 w2 ESK EDT EJ.
  exact (direct_dom_of_lit [] w f cur cols2 s3 sfx renewed f2 w2
           ESK EDT EJ (CascW28_lin_flat_nil _) (CascW28_lin_flat_nil _) (CascW28_lin_flat_nil _)).
Qed.
Definition DirectLitAt : Prop :=
  forall (sg : list seg) (w : word) (cur : nat)
         (cols2 s3 sfx : word) (f f2 : N) (renewed : bool),
    seek (skipn cur w) = (cols2, s3) ->
    lin_dtick_after_seek cols2 s3 f = Some (renewed, sfx, f2) ->
    lin_flat sg cols2 = cols2
    /\ lin_flat sg s3 = s3
    /\ lin_flat sg sfx = sfx.
Theorem direct_dom_of_litat (HL : DirectLitAt) : DirectDom.
Proof.
  intros sg w f cur cols2 s3 sfx renewed f2 w2 ESK EDT EJ.
  destruct (HL sg w cur cols2 s3 sfx f f2 renewed ESK EDT) as (H1 & H2 & H3).
  exact (direct_dom_of_lit sg w f cur cols2 s3 sfx renewed f2 w2
           ESK EDT EJ H1 H2 H3).
Qed.
Lemma literal_word_app_r (a b : word) :
  lin_literal_word (a ++ b) = true -> lin_literal_word b = true.
Proof.
  unfold lin_literal_word. rewrite forallb_app.
  intros H. apply andb_prop in H as [_ H]. exact H.
Qed.
Lemma zrun_lit (q lc : nat) (sg : list seg) (lw : word) (f : N)
      (gap : nat) (slot : N) (lw' : word) (f' : N) :
  lin_bottom_sched_zrun q lc sg lw f gap slot = Some (lw', f') ->
  lin_literal_word lw = true.
Proof.
  destruct q; cbn [lin_bottom_sched_zrun];
    destruct (lin_literal_word lw) eqn:E; intros HH;
    first [reflexivity | exact E | discriminate].
Qed.
Lemma setsfx_app_all (n : nat) (w s : word) :
  setsfx n w s = firstn n w ++ s.
Proof.
  revert w. induction n as [|n IH]; intros w; [reflexivity|].
  destruct w as [|g t]; [reflexivity|].
  cbn [setsfx firstn app]. f_equal. apply IH.
Qed.
Lemma zrun_dom (q : nat) :
  forall (lc : nat) (sg : list seg) (lw : word) (f : N)
         (gap : nat) (slot : N) (lw2 : word) (f2 : N),
    lin_bottom_sched_zrun q lc sg lw f gap slot = Some (lw2, f2) ->
    (CascW28_cmeas sg lw f <= CascW28_cmeas sg lw2 f2 + 8 * N.of_nat q)%N.
Proof.
  induction q as [|q IH]; intros lc sg lw f gap slot lw2 f2 HR.
  - cbn [lin_bottom_sched_zrun] in HR.
    destruct (lin_literal_word lw); [|discriminate].
    injection HR as HA HB. subst lw2 f2.
    cbn [N.of_nat]. lia.
  - destruct (lin_bottom_sched_zrun_S_inv q lc sg lw f gap slot lw2 f2 HR)
      as (cols & g & t & renewed & sfx & fq & lwi
          & HLit & ESK & EDT & _ & EJ & HRec).
    pose proof (IH _ _ _ _ _ _ _ _ HRec) as HI.
    pose proof (literal_word_skipn lc lw HLit) as HSk.
    destruct (seek_split _ _ _ ESK) as [ESP _].
    rewrite ESP in HSk.
    pose proof (literal_word_app_l _ _ HSk) as HLc.
    pose proof (literal_word_app_r _ _ HSk) as HLs.
    pose proof (zrun_lit _ _ _ _ _ _ _ _ _ HRec) as HLi.
    rewrite (direct_out_shape sg lw sfx lwi lc EJ) in HLi.
    pose proof (literal_word_app_r _ _ HLi) as HLsfx.
    pose proof (direct_dom_of_lit sg lw f lc cols (g :: t) sfx renewed fq lwi
                  ESK EDT EJ
                  (literal_word_flat sg cols HLc)
                  (literal_word_flat sg (g :: t) HLs)
                  (literal_word_flat sg sfx HLsfx)) as HD.
    rewrite Nat2N.inj_succ. lia.
Qed.
Theorem ladder_dom_holds : LadderDom.
Proof.
  intros sg w f basec lc gap slot take lw2 f2 HR.
  pose proof (zrun_dom (N.to_nat take) lc sg (skipn basec w) f gap slot
                lw2 f2 HR) as HZ.
  rewrite N2Nat.id in HZ.
  assert (EW : ccolcost (lin_flat sg w)
             = ccolcost (lin_flat sg (firstn basec w))
               + ccolcost (lin_flat sg (skipn basec w))).
  { pose proof (ccol_pref sg (firstn basec w) (skipn basec w)) as HP.
    rewrite firstn_skipn in HP. exact HP. }
  rewrite setsfx_app_all.
  unfold CascW28_cmeas, gmeas in *.
  rewrite ccol_pref, EW.
  lia.
Qed.
Corollary cascdom_of_bulk_and_litat
    (HBulk : BulkDom) (HL : DirectLitAt) : CascDom.
Proof.
  exact (cascdom_of ladder_dom_holds HBulk (direct_dom_of_litat HL)).
Qed.
