Lemma skipn_nil_all {A : Type} (n : nat) : skipn n (@nil A) = [].
Proof. destruct n; reflexivity. Qed.
Lemma skipn_plus {A : Type} (n m : nat) (l : list A) :
  skipn (n + m) l = skipn m (skipn n l).
Proof.
  revert l. induction n as [|n IH]; intros l; [reflexivity|].
  destruct l as [|x t]; cbn [skipn Nat.add].
  - rewrite skipn_nil_all. reflexivity.
  - apply IH.
Qed.
Lemma FlightW30_skipn_len_app {A : Type} (a b : list A) :
  skipn (length a) (a ++ b) = b.
Proof.
  induction a as [|x t IH]; cbn [length skipn app]; [reflexivity|exact IH].
Qed.
Lemma FlightW30_seek_split (s cols r : word) :
  seek s = (cols, r) -> s = cols ++ r.
Proof.
  revert cols r. induction s as [|g t IH]; intros cols r Hs.
  - cbn [seek] in Hs. inversion Hs. reflexivity.
  - rewrite seek_cons in Hs.
    destruct (seekt g) eqn:Eg.
    + inversion Hs; subst cols r. cbn [app]. f_equal.
      apply IH. destruct (seek t); reflexivity.
    + inversion Hs; subst cols r. reflexivity.
Qed.
Lemma nth_error_nil_all {A : Type} (n : nat) : @nth_error A [] n = None.
Proof. destruct n; reflexivity. Qed.
Lemma nth_error_skipn_add {A : Type} (j : nat) (l : list A) (k : nat) :
  nth_error l (j + k) = nth_error (skipn j l) k.
Proof.
  revert l. induction j as [|j IH]; intros l; [reflexivity|].
  destruct l as [|x t]; cbn [skipn Nat.add nth_error].
  - rewrite !nth_error_nil_all. reflexivity.
  - apply IH.
Qed.
Lemma FlightW30_wat_skipn (j : nat) (w : word) (k : nat) :
  wat w (j + k) = wat (skipn j w) k.
Proof. unfold wat. apply nth_error_skipn_add. Qed.
Lemma FlightW30_detect_phase_skipn (w : word) (j : nat) :
  detect_phase w j = detect_phase (skipn j w) O.
Proof.
  unfold detect_phase.
  rewrite <- (FlightW30_wat_skipn j w O), <- (FlightW30_wat_skipn j w (S O)).
  replace (j + O)%nat with j by lia.
  replace (j + S O)%nat with (S j) by lia.
  reflexivity.
Qed.
Theorem detect_phase_after_seek (w : word) (cur : nat)
        (cols2 s3 : word) :
  seek (skipn cur w) = (cols2, s3) ->
  detect_phase w (cur + length cols2)%nat
  = detect_phase s3 O.
Proof.
  intros HS.
  rewrite FlightW30_detect_phase_skipn, skipn_plus.
  rewrite (FlightW30_seek_split _ _ _ HS), FlightW30_skipn_len_app. reflexivity.
Qed.
Corollary detect_phase_after_seek_some (w : word) (cur : nat)
        (cols2 s3 : word) (pk : N) :
  seek (skipn cur w) = (cols2, s3) ->
  detect_phase s3 O = Some pk ->
  detect_phase w (cur + length cols2)%nat = Some pk.
Proof.
  intros HS HP. rewrite (detect_phase_after_seek w cur cols2 s3 HS).
  exact HP.
Qed.
Set Warnings "require-in-module".
Local Open Scope N_scope.
Opaque FLAT_ROUND_FUEL LROUND_FUEL LROUND_CHUNKS
       CFUEL TRIES.
Notation CascW31_cmeas := FlightDomC_cmeas.
Definition pairs28 : list (N * N) :=
  flat_map (fun p => map (fun r => (p, r)) pgrid) pgrid.
Lemma in_pairs28 (p r : N) : (p < 28)%N -> (r < 28)%N -> In (p, r) pairs28.
Proof.
  intros Hp Hr. apply in_flat_map. exists p.
  split; [apply in_pgrid; exact Hp|].
  apply in_map. apply in_pgrid. exact Hr.
Qed.
Definition bfit0 (K p rem : N) : bool :=
  (phd p + K * (EMt rem - EMt p)
     <=? phd rem + K * (rem - p))%N.
Definition bfit1 (K p rem : N) : bool :=
  (phd p + 56 + K * (4 + EMt rem - EMt p)
     <=? phd rem + K * (28 + rem - p))%N.
Definition g0b (K : N) : bool :=
  forallb (fun pr => (negb (fst pr + 2 <=? snd pr)%N
                      || bfit0 K (fst pr) (snd pr))%bool) pairs28.
Definition g1b (K : N) : bool :=
  forallb (fun pr => bfit1 K (fst pr) (snd pr)) pairs28.
Lemma g0_8 : g0b 8 = true.
Proof. vm_compute. reflexivity. Qed.
Lemma g1_8 : g1b 8 = true.
Proof. vm_compute. reflexivity. Qed.
Lemma bfit0_at (p rem : N) :
  (p < 28)%N -> (rem < 28)%N -> (p + 2 <= rem)%N ->
  (phd p + 8 * (EMt rem - EMt p)
     <= phd rem + 8 * (rem - p))%N.
Proof.
  intros Hp Hr Hd.
  pose proof (proj1 (forallb_forall _ pairs28) g0_8 (p, rem)
                (in_pairs28 p rem Hp Hr)) as HB.
  cbn [fst snd] in HB.
  destruct (p + 2 <=? rem)%N eqn:E; cbn [negb orb] in HB.
  - apply N.leb_le in HB. exact HB.
  - apply N.leb_gt in E. lia.
Qed.
Lemma bfit1_at (p rem : N) :
  (p < 28)%N -> (rem < 28)%N ->
  (phd p + 56 + 8 * (4 + EMt rem - EMt p)
     <= phd rem + 8 * (28 + rem - p))%N.
Proof.
  intros Hp Hr.
  pose proof (proj1 (forallb_forall _ pairs28) g1_8 (p, rem)
                (in_pairs28 p rem Hp Hr)) as HB.
  cbn [fst snd] in HB. apply N.leb_le in HB. exact HB.
Qed.
Theorem bulk_arith (p take : N) :
  (p < 28)%N -> (THRESH <= take)%N ->
  (phd p + 56 * ((p + take) / 28)
     + 8 * (marks (p + take) - marks p)
   <= phd ((p + take) mod 28) + 8 * take)%N.
Proof.
  intros Hp Ht. unfold THRESH in Ht.
  rewrite (marks_small p Hp).
  unfold marks.
  set (LL := ((p + take) / 28)%N).
  set (rm := ((p + take) mod 28)%N).
  assert (HD : (28 * LL + rm = p + take)%N)
    by (unfold LL, rm; symmetry; apply N.div_mod').
  assert (HR : (rm < 28)%N)
    by (unfold rm; apply N.mod_lt; discriminate).
  pose proof (emt_le3 p Hp) as H3p.
  pose proof (emt_le3 rm HR) as H3r.
  destruct (N.eq_dec LL 0) as [HL0|HL0].
  - rewrite HL0 in *.
    assert (Hrm : (rm = p + take)%N) by lia.
    pose proof (bfit0_at p rm Hp HR ltac:(lia)) as HA. lia.
  - assert (HL1 : (1 <= LL)%N) by lia.
    pose proof (bfit1_at p rm Hp HR) as HA. lia.
Qed.
Definition CascInv (sg : list seg) (w : word) : Prop :=
  stable_guard sg w
  /\ lin_guard sg w = true
  /\ is_spc (nth O w d0) = false.
Theorem bulk_dom_full
        (sg : list seg) (w : word) (f : N) (cur : nat)
        (cols2 s3 : word) (pk take : N)
        (w2 : word) (sg2 : list seg) (t2 : nat) (p2k ek : N)
        (w3 : word) :
  CascInv sg w ->
  seek (skipn cur w) = (cols2, s3) ->
  detect_phase s3 O = Some pk ->
  (THRESH <= take)%N ->
  Nat.eqb (N.to_nat ((pk + take) / 28)) O = false ->
  lin_bulk sg w (cur + length cols2)%nat pk take
    = Some (w2, sg2, t2, p2k, ek) ->
  lin_at_safe sg2 w2 t2 = Some w3 ->
  (CascW31_cmeas sg w f + 8 * ek <= CascW31_cmeas sg2 w3 f + 8 * take)%N.
Proof.
  intros (HS & _ & HHead) HSK HPh HT HFull HB HAS.
  rewrite (lin_at_safe_some sg2 w2 t2 w3 HAS).
  destruct (stable_bulk_hyps sg w HS) as (HW & HOk & HAlt).
  pose proof (detect_phase_after_seek_some w cur cols2 s3 pk
                HSK HPh) as HDW.
  destruct (lin_bulk_checks sg w (cur + length cols2)%nat pk take
              (w2, sg2, t2, p2k, ek) HB)
    as (gb & EW & HKey & _ & _ & HEnd).
  destruct (site_layout w (cur + length cols2)%nat pk gb HDW EW HEnd)
    as (HLay & HLen & HPost).
  destruct (detect_phase_form w (cur + length cols2)%nat pk HDW)
    as (Hp & _).
  destruct (lin_bulk_ccol sg w (cur + length cols2)%nat pk take
              w2 sg2 t2 p2k ek gb
              (firstn (cur + length cols2)%nat w)
              (skipn (S ((cur + length cols2 + phase_len pk)%nat)) w)
              HW HOk HAlt HHead HLay HLen HPost HKey Hp HFull HB)
    as (HRem & HEm & HId).
  pose proof (bulk_arith pk take Hp HT) as HA.
  rewrite HRem in HId. rewrite HEm.
  unfold FlightDomC_cmeas, gmeas. lia.
Qed.
Lemma inv_nbrs1z (sg : list seg) (w : word) :
  CascInv sg w -> nbrs1z sg w.
Proof.
  intros (HS & HGuard & _).
  destruct HS as (_ & HEdges & _ & _ & _ & _).
  exact (nbrs_nbrs1z sg w
           (margins_edges_nbrs sg w
              (lguard_margins sg w HGuard) HEdges)).
Qed.
Lemma inv_nbrs1z_skipn (sg : list seg) (w : word) (cur : nat) :
  CascInv sg w -> nbrs1z sg (skipn cur w).
Proof.
  intros HI.
  apply (nbrs1z_app_r sg (firstn cur w) (skipn cur w)).
  rewrite firstn_skipn. exact (inv_nbrs1z sg w HI).
Qed.
Theorem direct_dom_S
        (sg : list seg) (w : word) (f : N) (cur : nat)
        (cols2 s3 sfx : word) (renewed : bool) (f2 : N)
        (w2 : word) :
  CascInv sg w ->
  seek (skipn cur w) = (cols2, s3) ->
  lin_dtick_after_seek cols2 s3 f = Some (renewed, sfx, f2) ->
  (if Nat.eqb cur O then Some sfx
   else lin_join_safe sg (firstn cur w) sfx) = Some w2 ->
  (CascW31_cmeas sg w f <= CascW31_cmeas sg w2 f2 + 8)%N.
Proof.
  intros HI HSK EDT EJ.
  pose proof HI as HI'.
  destruct HI' as (HS & HGuard & _).
  pose proof (stable_guard_live sg w HS) as HLive.
  destruct HS as (_ & _ & HW & _ & HK & _).
  pose proof (inv_nbrs1z_skipn sg w cur HI) as HNCur.
  assert (ESnd : snd (seek (skipn cur w)) = s3)
    by (rewrite HSK; reflexivity).
  assert (EFst : fst (seek (skipn cur w)) = cols2)
    by (rewrite HSK; reflexivity).
  assert (HNS : nbrs1z sg s3).
  { apply (nbrs1z_app_r sg cols2 s3).
    rewrite <- EFst, <- ESnd, <- (LineageGuard_seek_split (skipn cur w)).
    exact HNCur. }
  assert (HHd : forall g t, s3 = g :: t -> ph sg g = false).
  { intros g t Eg.
    apply (nbrs1z_seek_snd_head sg (skipn cur w) g t HNCur).
    rewrite ESnd. exact Eg. }
  assert (HNL : forall t', s3 = (4%N,3%N,1%N) :: t' -> ph_notlast sg cols2).
  { intros t' Et.
    rewrite <- EFst.
    apply (nbrs1z_seek_notlast sg (skipn cur w) (4%N,3%N,1%N) t' HNCur).
    - rewrite ESnd. exact Et.
    - reflexivity.
    - cbn [gZ]. discriminate. }
  pose proof (lin_dtick_after_seek_flat_some sg cols2 s3 f renewed sfx f2
                HW HK HLive HNL HNS HHd EDT) as HFlat.
  pose proof (dtick_after_seek_grow
                (lin_flat sg cols2) (lin_flat sg s3) f renewed
                (lin_flat sg sfx) f2 HFlat) as HG.
  destruct (direct_ccol_split sg w cur cols2 s3 sfx w2 HSK EJ)
    as (EA & EB).
  unfold FlightDomC_cmeas, gmeas. rewrite EA, EB. lia.
Qed.
Definition CascDomS : Prop :=
  forall (fu : nat) (sg : list seg) (ps : atab) (w : word) (f : N)
         (st : list lsc_frame) (w' : word) (sg' : list seg)
         (ps' : atab) (f' : N),
    CascInv sg w ->
    Forall frame_pos st ->
    lin_casc_safe_at fu sg ps w f st = Some (w', sg', ps', f') ->
    (CascW31_cmeas sg w f <= CascW31_cmeas sg' w' f' + 8 * cascticks st)%N.
Definition BulkPartialDom : Prop :=
  forall (sg : list seg) (w : word) (f : N) (cur : nat)
         (cols2 s3 : word) (pk take : N)
         (w2 : word) (sg2 : list seg) (t2 : nat) (p2k ek : N),
    CascInv sg w ->
    seek (skipn cur w) = (cols2, s3) ->
    detect_phase s3 O = Some pk ->
    (THRESH <= take)%N ->
    Nat.eqb (N.to_nat ((pk + take) / 28)) O = true ->
    lin_bulk sg w (cur + length cols2)%nat pk take
      = Some (w2, sg2, t2, p2k, ek) ->
    (CascW31_cmeas sg w f + 8 * ek <= CascW31_cmeas sg2 w2 f + 8 * take)%N.
Lemma flat_cons_nokey (sg : list seg) (g : bg) (t : word) :
  keyi sg g = None -> lin_flat sg (g :: t) = g :: lin_flat sg t.
Proof.
  intros H. cbn [lin_flat]. unfold keyb. rewrite H. reflexivity.
Qed.
Lemma keyi_lvl (sg : list seg) (c : N) : keyi sg (4,2,c)%N = None.
Proof.
  unfold keyi, phshape, tagbase.
  cbn [gO gZ gC fst snd]. reflexivity.
Qed.
Lemma ccol_lvl_cons (c : N) (t : word) :
  ccolcost ((4,2,c)%N :: t) = (14 * c + ccolcost t)%N.
Proof.
  rewrite ccolcost_cons. unfold ccg.
  cbn [gO gC fst snd]. lia.
Qed.
Lemma phd_split (p : N) :
  (ccolcost (phase_form p) + 14 * DBu p
   = phd p)%N.
Proof. unfold phd. lia. Qed.
Theorem bulk_dom_partial : BulkPartialDom.
Proof.
  intros sg w f cur cols2 s3 pk take w2 sg2 t2 p2k ek
         HI HSK HPh HT HFull HB.
  destruct HI as (HS & _ & _).
  destruct (stable_bulk_hyps sg w HS) as (HW & HOk & HAlt).
  pose proof (detect_phase_after_seek_some w cur cols2 s3 pk
                HSK HPh) as HDW.
  destruct (lin_bulk_checks sg w (cur + length cols2)%nat pk take
              (w2, sg2, t2, p2k, ek) HB)
    as (gb & EW & HKey & HLvl & HEro & HEnd).
  destruct (site_layout w (cur + length cols2)%nat pk gb HDW EW HEnd)
    as (HLay & HLen & HPost).
  destruct (detect_phase_form w (cur + length cols2)%nat pk HDW)
    as (Hp & _).
  destruct (lin_bulk_partial_out sg w (cur + length cols2)%nat pk take
              w2 sg2 t2 p2k ek gb HFull HB EW)
    as (ESG & _ & ERem & EEm & EW2).
  destruct (lvl_big_shape gb HLvl) as (c & Egb).
  assert (HPL : length (phase_form pk) = phase_len pk)
    by (apply phase_form_len; exact Hp).
  remember (firstn (cur + length cols2)%nat w) as pre eqn:EPre.
  remember (skipn (S ((cur + length cols2) + phase_len pk)%nat) w)
    as post eqn:EPost.
  rewrite Egb in EW2, HLay, HEro. cbn [gC] in EW2, HEro.
  rewrite HLay in EW2.
  rewrite <- HPL in EW2. rewrite <- HLen in EW2.
  rewrite subst_site in EW2.
  assert (EIn : ccolcost (lin_flat sg w)
              = (ccolcost (lin_flat sg pre)
                 + (ccolcost (phase_form pk)
                    + (14 * c + ccolcost (lin_flat sg post))))%N).
  { rewrite HLay at 1.
    rewrite ccol_pref, ccol_pref.
    rewrite (flat_phase_form sg pk Hp).
    rewrite (flat_cons_nokey sg (4,2,c)%N post (keyi_lvl sg c)).
    rewrite ccol_lvl_cons. lia. }
  assert (EOut : ccolcost (lin_flat sg w2)
              = (ccolcost (lin_flat sg pre)
                 + (ccolcost (phase_form p2k)
                    + (14 * ((c + DBu p2k) - DBu pk)
                       + ccolcost (lin_flat sg post))))%N).
  { rewrite EW2, <- ERem.
    rewrite ccol_pref, ccol_pref.
    assert (Hr : (p2k < 28)%N).
    { rewrite ERem. apply N.mod_lt. discriminate. }
    rewrite (flat_phase_form sg p2k Hr).
    rewrite (flat_cons_nokey sg (4,2,_)%N post (keyi_lvl sg _)).
    rewrite ccol_lvl_cons. lia. }
  assert (HL0 : ((pk + take) / 28 = 0)%N).
  { apply PeanoNat.Nat.eqb_eq in HFull.
    apply N2Nat.inj. cbn [N.to_nat]. exact HFull. }
  pose proof (bulk_arith pk take Hp HT) as HA.
  rewrite HL0, <- ERem in HA.
  pose proof (phd_split pk) as EPp.
  pose proof (phd_split p2k) as EPr.
  assert (HFL : (FLOOR + DBu pk <= c)%N) by exact HEro.
  unfold FLOOR in HFL.
  rewrite ESG, EEm.
  unfold FlightDomC_cmeas, gmeas.
  rewrite EIn, EOut. lia.
Qed.
Theorem bulk_dom_S_of_partial (HP : BulkPartialDom)
        (sg : list seg) (w : word) (f : N) (cur : nat)
        (cols2 s3 : word) (pk take : N)
        (w2 : word) (sg2 : list seg) (t2 : nat) (p2k ek : N)
        (w3 : word) :
  CascInv sg w ->
  seek (skipn cur w) = (cols2, s3) ->
  detect_phase s3 O = Some pk ->
  (THRESH <= take)%N ->
  lin_bulk sg w (cur + length cols2)%nat pk take
    = Some (w2, sg2, t2, p2k, ek) ->
  lin_at_safe sg2 w2 t2 = Some w3 ->
  (CascW31_cmeas sg w f + 8 * ek <= CascW31_cmeas sg2 w3 f + 8 * take)%N.
Proof.
  intros HI HSK HPh HT HB HAS.
  destruct (Nat.eqb (N.to_nat ((pk + take) / 28)) O) eqn:EF.
  - rewrite (lin_at_safe_some sg2 w2 t2 w3 HAS).
    exact (HP sg w f cur cols2 s3 pk take w2 sg2 t2 p2k ek
             HI HSK HPh HT EF HB).
  - exact (bulk_dom_full sg w f cur cols2 s3 pk take
             w2 sg2 t2 p2k ek w3 HI HSK HPh HT EF HB HAS).
Qed.
Definition bulk_dom_S := bulk_dom_S_of_partial bulk_dom_partial.
Theorem cascdom_ofS : CascDomS.
Proof.
  intros fu. induction fu as [|fu IH];
    intros sg ps w f st w' sg' ps' f' HI HFrames H; [discriminate|].
  cbn [lin_casc_safe_at] in H. cbv beta zeta in H.
  destruct st as [|fr rest].
  { injection H as <- <- _ <-. cbn [cascticks]. lia. }
  inversion HFrames as [|fr0 rest0 HFr HRest]; subst fr0 rest0.
  destruct (lsTicks fr =? 0)%N eqn:ETK.
  { pose proof (IH sg ps w f rest w' sg' ps' f' HI HRest H) as HR.
    rewrite cascticks_cons. apply N.eqb_eq in ETK. rewrite ETK. lia. }
  apply N.eqb_neq in ETK.
  assert (HTK : (1 <= lsTicks fr)%N) by lia.
  destruct (seek (skipn (lsCur fr) w)) as [cols2 s3] eqn:ESK.
  destruct s3 as [|g3 s3t]; [discriminate|].
  pose proof (LineageGuard_seek_split (skipn (lsCur fr) w)) as HSplit.
  rewrite ESK in HSplit. cbn [fst snd] in HSplit.
  assert (HCurLen : (lsCur fr <= length w)%nat).
  { pose proof (f_equal (@length bg) HSplit) as HLenW.
    rewrite length_skipn, length_app in HLenW. cbn [length] in HLenW. lia. }
  unfold frame_pos in HFr.
  pose proof HI as HI0.
  destruct HI0 as (HG0 & HGuard & HHead).
  pose proof HG0 as HG0'.
  destruct HG0' as ((HOk & HPT) & HEdges & HWf & HShape & HKeys & HPos).
  destruct (lin_bottom_take cols2 (g3 :: s3t) f (lsTicks fr))
    as [take|] eqn:EBT.
  -
    pose proof (bottom_take_le _ _ _ _ _ EBT) as HLE.
    destruct (lin_bottom_sched_zrun (N.to_nat take)
                (lsCur fr - (lsCur fr - 2))%nat sg
                (skipn (lsCur fr - 2)%nat w) f (lsGap fr) (lsSlot fr))
      as [[lw2 f2]|] eqn:EZ; [|discriminate].
    destruct (relocate_all sg ps
                (setsfx (lsCur fr - 2)%nat w lw2)) as [ps2|]
      eqn:ER; [|discriminate].
    destruct (lin_guard_at sg ps2
                (setsfx (lsCur fr - 2)%nat w lw2)) eqn:EG;
      [|discriminate].
    assert (HG2 : stable_guard sg
                    (setsfx (lsCur fr - 2)%nat w lw2)).
    { exact (lin_bottom_global_stable take fr (lsCur fr - 2)%nat
               (lsCur fr - (lsCur fr - 2))%nat sg w f lw2 f2
               HG0 ltac:(lia) eq_refl ltac:(lia)
               ltac:(rewrite length_skipn; lia) EZ). }
    assert (HGuard2 : lin_guard sg
                        (setsfx (lsCur fr - 2)%nat w lw2) = true)
      by (exact (lin_guard_at_sound sg ps2 _ (proj1 (proj1 HG2)) EG)).
    assert (HHead2 : is_spc
                       (nth O (setsfx (lsCur fr - 2)%nat w lw2)
                            d0) = false)
      by (exact (setsfx_head_nonspc (lsCur fr - 2)%nat w lw2
                   ltac:(lia) ltac:(lia) HHead)).
    assert (HFrames2 : Forall frame_pos
                         (lin_sched_advance fr take :: rest)).
    { constructor; [|exact HRest].
      apply frame_pos_advance. unfold frame_pos. lia. }
    pose proof (IH sg ps2 (setsfx (lsCur fr - 2)%nat w lw2) f2
                  (lin_sched_advance fr take :: rest)
                  w' sg' ps' f'
                  (conj HG2 (conj HGuard2 HHead2)) HFrames2 H) as HR.
    pose proof (ladder_dom_holds sg w f (lsCur fr - 2)%nat
                  (lsCur fr - (lsCur fr - 2))%nat (lsGap fr)
                  (lsSlot fr) take lw2 f2 EZ) as HA.
    rewrite cascticks_cons in HR |- *.
    rewrite ticks_advance in HR. lia.
  - lazymatch type of H with
    | match ?x with _ => _ end = _ =>
        destruct x as [[[[[[[w2 sg2] t2] p2k] ek] take] pk]|] eqn:EBK
    end.
    +
      assert (HBK : lin_bulk sg w (lsCur fr + length cols2)%nat pk take
                    = Some (w2, sg2, t2, p2k, ek)
                    /\ (take <= lsTicks fr)%N
                    /\ detect_phase (g3 :: s3t) O = Some pk
                    /\ (THRESH <= take)%N
                    /\ take = lin_bulk_take sg w (lsCur fr)
                                (lsCur fr + length cols2)%nat pk
                                (lsTicks fr)
                    /\ (lsCur fr + 2 < lsCur fr + length cols2)%nat).
      { revert EBK.
        destruct (Nat.ltb (lsCur fr + 2) (lsCur fr + length cols2))
          eqn:ELt; [|discriminate].
        destruct (detect_phase (g3 :: s3t) O) as [pk0|] eqn:EPh;
          [|discriminate].
        cbv beta zeta.
        destruct (THRESH <=?
                    lin_bulk_take sg w (lsCur fr)
                      (lsCur fr + length cols2)%nat pk0 (lsTicks fr))%N
          eqn:ETh; [|discriminate].
        destruct (lin_bulk sg w (lsCur fr + length cols2)%nat pk0
                    (lin_bulk_take sg w (lsCur fr)
                       (lsCur fr + length cols2)%nat pk0 (lsTicks fr)))
          as [[[[[wq sgq] tq] pq] eq0]|] eqn:EBL; [|discriminate].
        intros EE. injection EE as <- <- <- <- <- <- <-.
        split; [exact EBL|]. split; [apply bulk_take_le|].
        split; [first [reflexivity|exact EPh]|].
        split; [first [apply N.leb_le; exact ETh|lia]|].
        split; [reflexivity|].
        first [apply PeanoNat.Nat.ltb_lt; exact ELt|lia]. }
      destruct HBK as (HBK & HLE & HPh & HTh & HTakeEq & HLt).
      destruct (negb (lin_sched_bulk_safe fr (lin_flen sg cols2) pk take))
        eqn:ESF; [discriminate|].
      destruct (lin_at_safe sg2 w2 t2) as [w3|] eqn:EAS; [|discriminate].
      pose proof (lin_at_safe_some sg2 w2 t2 w3 EAS) as EW3. subst w3.
      destruct (locate_all sg2 w2) as [ps2|] eqn:ELO; [|discriminate].
      destruct (lin_guard_at sg2 ps2 w2) eqn:EG; [|discriminate].
      assert (HD : detect_phase w (lsCur fr + length cols2)%nat
                   = Some pk)
        by (exact (detect_phase_after_seek_some w (lsCur fr)
                     cols2 (g3 :: s3t) pk ESK HPh)).
      assert (HTgPos : (1 <= lsCur fr + length cols2)%nat) by lia.
      pose proof (lin_bulk_front_repr sg w
                    (lsCur fr + length cols2)%nat pk take
                    w2 sg2 t2 p2k ek (conj HOk HPT) HHead HD HBK) as HFront2.
      assert (HGuard2 : lin_guard sg2 w2 = true)
        by (exact (lin_guard_at_sound sg2 ps2 w2 (proj1 HFront2) EG)).
      assert (HG2 : stable_guard sg2 w2)
        by (exact (lin_bulk_stable_guarded sg w
                     (lsCur fr + length cols2)%nat pk take
                     w2 sg2 t2 p2k ek HG0 HHead HD HBK HGuard2)).
      destruct (lin_bulk_head_pos sg w (lsCur fr + length cols2)%nat
                  pk take w2 sg2 t2 p2k ek HTgPos HHead HD HBK)
        as (HNhPos & HHead2).
      assert (HChildPos : frame_pos
                            (lin_sched_child t2 p2k ek pk take)).
      { unfold frame_pos, lin_sched_child. cbn [lsCur].
        destruct (Nat.eqb (N.to_nat ((pk + take) / 28)) O) eqn:EF.
        - destruct (lin_bulk_checks sg w (lsCur fr + length cols2)%nat
                      pk take (w2, sg2, t2, p2k, ek) HBK)
            as (gb & HWat & _ & _ & _ & _).
          destruct (lin_bulk_partial_out sg w
                      (lsCur fr + length cols2)%nat pk take
                      w2 sg2 t2 p2k ek gb EF HBK HWat)
            as (_ & Hnh & _ & _ & _).
          rewrite Hnh. lia.
        - pose proof (lin_bulk_take_lands_after_cursor sg w
                        (lsCur fr) cols2 (g3 :: s3t)
                        (lsCur fr + length cols2)%nat pk (lsTicks fr)
                        take w2 sg2 t2 p2k ek
                        HWf HOk (stable_altb sg w HG0) HHead ESK eq_refl
                        HD HTakeEq HTh EF HBK
                        (proj1 (proj2 (proj2 HG2)))) as HCr. lia. }
      assert (HFrames2 : Forall frame_pos
                (lin_sched_child t2 p2k ek pk take
                 :: lin_sched_advance fr take :: rest)).
      { constructor; [exact HChildPos|]. constructor; [|exact HRest].
        apply frame_pos_advance. unfold frame_pos. lia. }
      pose proof (IH sg2 ps2 w2 f
                    (lin_sched_child t2 p2k ek pk take
                     :: lin_sched_advance fr take :: rest)
                    w' sg' ps' f'
                    (conj HG2 (conj HGuard2 HHead2)) HFrames2 H) as HR.
      pose proof (bulk_dom_S sg w f (lsCur fr) cols2 (g3 :: s3t) pk take
                    w2 sg2 t2 p2k ek w2 HI ESK HPh HTh HBK EAS) as HA.
      rewrite !cascticks_cons in HR. rewrite cascticks_cons.
      rewrite ticks_advance, ticks_child in HR. lia.
    +
      lazymatch type of H with
      | match ?x with _ => _ end = _ =>
          destruct x as [[[renewed sfx] f2]|] eqn:EDT
      end; [|discriminate].
      assert (HW2 : exists w2 ps2,
        (if Nat.eqb (lsCur fr) O then Some sfx
         else lin_join_safe sg (firstn (lsCur fr) w) sfx) = Some w2
        /\ lin_guard_at sg ps2 w2 = true
        /\ lin_casc_safe_at fu sg ps2 w2 f2
             (lin_sched_advance_one fr :: rest)
           = Some (w', sg', ps', f')).
      { revert H. destruct renewed.
        - destruct (negb (Nat.leb (lsGap fr + 2) (lin_flen sg cols2)));
            [discriminate|].
          destruct (if Nat.eqb (lsCur fr) O then Some sfx
                    else lin_join_safe sg (firstn (lsCur fr) w) sfx)
            as [wq|] eqn:EJ; [|discriminate].
          destruct (if lin_same_length w wq then Some ps
                    else relocate_all sg ps wq) as [psq|] eqn:EP2;
            [|discriminate].
          destruct (lin_guard_at sg psq wq) eqn:EG; [|discriminate].
          intros HH. exists wq, psq. split; [reflexivity|].
          split; [exact EG|exact HH].
        - destruct (if Nat.eqb (lsCur fr) O then Some sfx
                    else lin_join_safe sg (firstn (lsCur fr) w) sfx)
            as [wq|] eqn:EJ; [|discriminate].
          destruct (if lin_same_length w wq then Some ps
                    else relocate_all sg ps wq) as [psq|] eqn:EP2;
            [|discriminate].
          destruct (lin_guard_at sg psq wq) eqn:EG; [|discriminate].
          intros HH. exists wq, psq. split; [reflexivity|].
          split; [exact EG|exact HH]. }
      destruct HW2 as (w2 & ps2 & EJ & EG & HH).
      assert (HG2 : stable_guard sg w2)
        by (exact (lin_direct_stable sg w (lsCur fr) f cols2 g3 s3t
                     renewed sfx f2 w2 HG0 HGuard ESK EDT EJ)).
      assert (HGuard2 : lin_guard sg w2 = true)
        by (exact (lin_guard_at_sound sg ps2 w2 (proj1 (proj1 HG2)) EG)).
      assert (EW2 : w2 = firstn (lsCur fr) w ++ sfx).
      { destruct (Nat.eqb (lsCur fr) O) eqn:HCur0.
        - apply PeanoNat.Nat.eqb_eq in HCur0. lia.
        - exact (lin_join_safe_some sg (firstn (lsCur fr) w) sfx w2 EJ). }
      assert (HHead2 : is_spc (nth O w2 d0) = false)
        by (exact (prefix_replace_head_nonspc w w2 (lsCur fr) sfx
                     ltac:(lia) HCurLen EW2 HHead)).
      assert (HFrames2 : Forall frame_pos
                           (lin_sched_advance_one fr :: rest)).
      { constructor; [|exact HRest].
        rewrite lin_sched_advance_one_eq.
        apply frame_pos_advance. unfold frame_pos. lia. }
      pose proof (IH sg ps2 w2 f2 (lin_sched_advance_one fr :: rest)
                    w' sg' ps' f'
                    (conj HG2 (conj HGuard2 HHead2)) HFrames2 HH) as HR.
      pose proof (direct_dom_S sg w f (lsCur fr) cols2 (g3 :: s3t) sfx
                    renewed f2 w2 HI ESK EDT EJ) as HA.
      rewrite cascticks_cons in HR |- *.
      rewrite ticks_advance_one in HR. lia.
Qed.
