Theorem cround_at_ub (cols s : word) (f : N) :
  chi (snd (cround_at cols s f))
    <= 3 * (ccolcost cols + ccolcost s) + 2 * f + 70.
Proof.
  unfold cround_at. cbv zeta.
  assert (LEAF : forall s0 : word,
      ccolcost s0 = ccolcost s ->
      chi (snd (match fst (cleaf_act s0 f) with
                | Some (s2, f2) =>
                    (Some (cols ++ s2, f2),
                     cadd (cx (ccolcost cols))
                          (snd (cleaf_act s0 f)))
                | None => (None, cundef)
                end : (option (word * N) * cost)%type))
        <= 3 * (ccolcost cols + ccolcost s) + 2 * f + 70).
  { intros s0 HE.
    destruct (fst (cleaf_act s0 f)) as [[s2 f2]|] eqn:EL.
    - pose proof (cleaf_act_ub s0 f s2 f2 EL) as HU. unfold ubc in HU.
      cbn [snd]. unfold cadd, chi, cx; cbn [fst snd].
      unfold chi in HU. lia.
    - cbn [snd]. unfold cundef, chi; cbn [snd]. lia. }
  destruct s as [|[[oR zR] cR] tR]; cbv beta iota;
    [apply (LEAF []); reflexivity|].
  destruct zR as [|pz]; cbv beta iota;
    [apply LEAF; reflexivity|].
  destruct pz as [q1|q1|]; cbv beta iota;
    [|apply LEAF; reflexivity|apply LEAF; reflexivity].
  destruct q1 as [r1|r1|]; cbv beta iota;
    [apply LEAF; reflexivity|apply LEAF; reflexivity|].
  destruct cR as [|pc]; cbv beta iota; [apply LEAF; reflexivity|].
  destruct pc as [pc'|pc'|]; cbv beta iota;
    [apply LEAF; reflexivity|apply LEAF; reflexivity|].
  match goal with
  | |- context [ crenew_seg ?n ?a ?b ?c ] =>
      destruct (fst (crenew_seg n a b c)) as [[body fb]|] eqn:ER;
      [ pose proof (proj2 (cascade_ub n) a b c body fb ER) as HU |]
  end.
  - unfold ubc in HU. cbn [snd]. unfold cadd, chi, cx; cbn [fst snd].
    unfold chi in HU. lia.
  - cbn [fst].
    match goal with
    | |- context [ cfire_comp ?n ?b ?c ] =>
        destruct (fst (cfire_comp n b c)) as [[s2 f2]|] eqn:EF;
        [ pose proof (proj1 (cascade_ub n) b c s2 f2 EF) as HU |]
    end.
    + unfold ubc in HU. cbn [snd]. unfold cadd, chi, cx; cbn [fst snd].
      unfold chi in HU. lia.
    + cbn [snd]. unfold cundef, chi; cbn [snd]. lia.
Qed.
Corollary cround1g_ub (tail : word) (f : N) :
  chi (snd (cround1g tail f))
    <= 3 * ccolcost tail + 2 * f + 70.
Proof.
  unfold cround1g.
  destruct (seek tail) as [cols s] eqn:ES.
  rewrite (ccolcost_seek_eq tail cols s ES).
  apply cround_at_ub.
Qed.
Lemma chi_cadd_cx (K : N) (d : cost) : chi (cadd (cx K) d) = K + chi d.
Proof. reflexivity. Qed.
Ltac swalk :=
  repeat (cbv iota;
          match goal with
          | |- context [ match ?x with _ => _ end ] => is_var x; destruct x
          end);
  cbv iota;
  try (cbn [chi cundef cx cadd fst snd]; lia).
Theorem d_span8orph_ub (w : word) (f : N) :
  chi (d_span8orph w f) <= 3 * ccolcost w + 2 * f + 110.
Proof.
  unfold d_span8orph. swalk.
  match goal with
  | |- context [ if ?b then _ else _ ] => destruct b eqn:EG
  end; [|cbn [chi cundef snd]; lia].
  match goal with
  | |- context [ cround1g ?t ?ff ] =>
      pose proof (cround1g_ub t ff) as HU;
      destruct (fst (cround1g t ff)) as [x|] eqn:EC
  end; [|cbn [chi cundef snd]; lia].
  rewrite chi_cadd_cx.
  rewrite !ccolcost_cons, !ccg_unfold.
  cbn [gC gO].
  rewrite ?ccolcost_app, ?ccolcost_cons, ?ccg_unfold in HU.
  cbn [gC gO ccolcost] in HU.
  destruct (1 <? n2) eqn:EN2; cbn [app] in HU |- *;
    rewrite ?ccolcost_cons, ?ccg_unfold in HU;
    cbn [gC gO ccolcost] in HU;
    [apply N.ltb_lt in EN2|apply N.ltb_ge in EN2]; lia.
Qed.
Theorem d_span2A_ub (w : word) (f : N) :
  chi (d_span2A w f) <= 3 * ccolcost w + 2 * f + 110.
Proof.
  unfold d_span2A. swalk.
  match goal with
  | |- context [ if ?b then _ else _ ] => destruct b eqn:EG
  end; [|cbn [chi cundef snd]; lia].
  apply andb_prop in EG; destruct EG as [EG _EV].
  apply andb_prop in EG; destruct EG as [E2 E3].
  apply N.eqb_eq in E2. apply N.eqb_eq in E3. subst.
  destruct (seek w) as [cols s] eqn:ES.
  pose proof (ccolcost_seek_eq w cols s ES) as HSK.
  rewrite !ccolcost_cons, !ccg_unfold.
  cbn [gC gO].
  swalk.
  all: try (match goal with
            | |- context [ cleaf_act ?a ?b ] =>
                destruct (fst (cleaf_act a b)) as [[s2 f2]|] eqn:EL;
                [ pose proof (cleaf_act_ub a b s2 f2 EL) as HU;
                  unfold ubc in HU; rewrite chi_cadd_cx; lia
                | cbn [chi cundef snd]; lia ]
            end).
  all: try (match goal with
            | |- context [ crenew_seg ?nn ?a ?b ?c ] =>
                destruct (fst (crenew_seg nn a b c))
                  as [[body fb]|] eqn:ER;
                [ pose proof (proj2 (cascade_ub nn) a b c body fb ER) as HU;
                  unfold ubc in HU; rewrite chi_cadd_cx; lia
                | ]
            end).
  all: match goal with
       | |- context [ cfire_comp ?nn ?b ?c ] =>
           destruct (fst (cfire_comp nn b c)) as [[s2 f2]|] eqn:EF;
           [ pose proof (proj1 (cascade_ub nn) b c s2 f2 EF) as HU;
             unfold ubc in HU; rewrite chi_cadd_cx; lia
           | cbn [chi cundef snd]; lia ]
       end.
Qed.
