Theorem round_at_growU (cols s : word) (f : N) (t2 : word) (f2 : N) :
  round_at cols s f = Some (t2, f2) ->
  ccolcost t2 + 2 * f2
    <= 2 * (ccolcost cols + ccolcost s + 2 * f) + 64.
Proof.
  unfold round_at.
  assert (LEAF : forall s0 : word,
      ccolcost s0 = ccolcost s ->
      match leaf_act s0 f with
      | Some (s2, ff) => Some (cols ++ s2, ff)
      | None => None
      end = Some (t2, f2) ->
      ccolcost t2 + 2 * f2
        <= 2 * (ccolcost cols + ccolcost s + 2 * f) + 64).
  { intros s0 HE HH.
    destruct (leaf_act s0 f) as [[s2 ff]|] eqn:EL; [|discriminate].
    pose proof (leaf_growU s0 f s2 ff EL) as HG.
    injection HH as HH1 HH2. subst.
    rewrite ccolcost_app. lia. }
  destruct s as [|[[oR zR] cR] tR]; cbv beta iota;
    [apply (LEAF []); reflexivity|].
  destruct zR as [|pz]; cbv beta iota; [apply LEAF; reflexivity|].
  destruct pz as [q1|q1|]; cbv beta iota;
    [|apply LEAF; reflexivity|apply LEAF; reflexivity].
  destruct q1 as [r1|r1|]; cbv beta iota;
    [apply LEAF; reflexivity|apply LEAF; reflexivity|].
  destruct cR as [|pc]; cbv beta iota; [apply LEAF; reflexivity|].
  destruct pc as [pc'|pc'|]; cbv beta iota;
    [apply LEAF; reflexivity|apply LEAF; reflexivity|].
  match goal with
  | |- context [ renew_seg ?n ?a ?b ?c ] =>
      destruct (renew_seg n a b c) as [[body fb]|] eqn:ER;
      [ pose proof (proj2 (casc_growU n) a b c body fb ER) as HU |]
  end.
  - intros HH; injection HH as HH1 HH2; subst. lia.
  - match goal with
    | |- context [ fire_comp ?n ?b ?c ] =>
        destruct (fire_comp n b c) as [[s2 ff]|] eqn:EF;
        [ pose proof (proj1 (casc_growU n) b c s2 ff EF) as HU |]
    end.
    + intros HH; injection HH as HH1 HH2; subst.
      rewrite ccolcost_app. lia.
    + discriminate.
Qed.
Lemma chi_cadds_le (a b : cost) : chi (cadds a b) <= chi a + chi b.
Proof.
  unfold cadds.
  destruct (N.ltb (chi a) (clo a) || N.ltb (chi b) (clo b))%bool;
    [unfold cundef, chi; cbn [snd]; lia
    |unfold cadd, chi; cbn [snd]; lia].
Qed.
Lemma chi_cundef0 : chi cundef = 0.
Proof. reflexivity. Qed.
Theorem cround2g_ub (tail : word) (f : N) :
  chi (snd (cround2g tail f))
    <= 9 * ccolcost tail + 14 * f + 340.
Proof.
  unfold cround2g. cbv zeta.
  destruct (seek tail) as [cols s] eqn:ES.
  pose proof (ccolcost_seek_eq tail cols s ES) as HSK.
  pose proof (cround_at_ub cols s f) as H1.
  destruct (fst (cround_at cols s f)) as [[t2 f2]|] eqn:E1;
    [|cbn [snd]; rewrite chi_cundef0; lia].
  assert (HR : round_at cols s f = Some (t2, f2))
    by (rewrite <- cround_at_proj; exact E1).
  pose proof (round_at_growU cols s f t2 f2 HR) as HG.
  destruct (seek t2) as [cols2 s2] eqn:ES2.
  pose proof (ccolcost_seek_eq t2 cols2 s2 ES2) as HSK2.
  destruct s2 as [|g2 s2t].
  -
    cbn [snd].
    eapply N.le_trans; [apply chi_cadds_le|].
    assert (HT : chi (if f2 =? 4
                      then match dtb4_convc cols2 with
                           | Some (_, Kd) => cx (Kd + 6)
                           | None => cundef
                           end
                      else if 5 <=? f2
                      then cx (2 * f2 + 13 + ccolcost cols2 + 6)
                      else cundef)
                 <= ccolcost cols2 + 2 * f2 + 27).
    { destruct (f2 =? 4).
      - destruct (dtb4_convc cols2) as [[bb Kd]|] eqn:ED;
          [|rewrite chi_cundef0; lia].
        pose proof (dtb4_convc_ub cols2 bb Kd ED) as HD.
        unfold chi, cx; cbn [snd]. lia.
      - destruct (5 <=? f2); [|rewrite chi_cundef0; lia].
        unfold chi, cx; cbn [snd]. lia. }
    lia.
  -
    cbn [snd].
    eapply N.le_trans; [apply chi_cadds_le|].
    pose proof (cround_at_ub cols2 (g2 :: s2t) f2) as H2.
    lia.
Qed.
Corollary cround1g_ub' (tail : word) (f : N) :
  chi (snd (cround1g tail f))
    <= 9 * ccolcost tail + 14 * f + 340.
Proof. pose proof (cround1g_ub tail f). lia. Qed.
Theorem cround2g_pre8_ub (tail : word) (f g : N) :
  chi (snd (cround2g_pre8 tail f g))
    <= 5 * ccolcost tail + 6 * f + 14 * g + 175.
Proof.
  unfold cround2g_pre8. cbv zeta.
  destruct (seek tail) as [cols s] eqn:ES.
  pose proof (ccolcost_seek_eq tail cols s ES) as HSK.
  pose proof (cround_at_ub cols s f) as H1.
  destruct (fst (cround_at cols s f)) as [[t2 f2]|] eqn:E1;
    [|cbn [snd]; rewrite chi_cundef0; lia].
  assert (HR : round_at cols s f = Some (t2, f2))
    by (rewrite <- cround_at_proj; exact E1).
  pose proof (round_at_growU cols s f t2 f2 HR) as HG.
  destruct (seek t2) as [cols2 s2] eqn:ES2.
  pose proof (ccolcost_seek_eq t2 cols2 s2 ES2) as HSK2.
  destruct s2 as [|g2 s2t];
    [|cbn [snd]; rewrite chi_cundef0; lia].
  destruct (((f2 =? 4) && forallb w42 cols2)%N) eqn:EG;
    [|cbn [snd]; rewrite chi_cundef0; lia].
  apply andb_prop in EG as [EF4 EW42].
  apply N.eqb_eq in EF4. subst f2.
  destruct (dtb4_conv cols2) as [served|] eqn:ED;
    [cbn [snd]; rewrite chi_cundef0; lia|].
  cbn [snd]. eapply N.le_trans; [apply chi_cadds_le|].
  pose proof (w42sum_ccolcost cols2 EW42) as HW.
  unfold kdtb_plain, chi, cx; cbn [snd].
  unfold chi in H1. cbn [ccolcost] in HSK2. lia.
Qed.
Theorem d_span8_ub (w : word) (f : N) :
  chi (d_span8 w f) <= 9 * ccolcost w + 14 * f + 400.
Proof.
  unfold d_span8. swalk.
  -
    match goal with
    | |- context [if ?b then _ else _] => destruct b eqn:EG4
    end.
    + nlbools. rewrite !ccolcost_cons, !ccg_unfold.
      cbn [gC gO ccolcost].
      unfold chi, cx; cbn [snd]. lia.
    + match goal with
      | |- context [if ?b then _ else _] => destruct b eqn:EG5
      end.
      * nlbools. rewrite !ccolcost_cons, !ccg_unfold.
        cbn [gC gO ccolcost].
        unfold chi, cx; cbn [snd]. lia.
      * cbn [chi cundef snd]. lia.
  - match goal with
    | |- context [ if ?b then _ else _ ] => destruct b eqn:EG
    end; [|cbn [chi cundef snd]; lia].
    match goal with
    | |- context [ cround2g ?t ?ff ] =>
        pose proof (cround2g_ub t ff) as HU;
        destruct (fst (cround2g t ff)) as [x|] eqn:EC
    end.
    + rewrite chi_cadd_cx.
      rewrite !ccolcost_cons, !ccg_unfold.
      rewrite ?ccolcost_cons, ?ccg_unfold in HU.
      cbn [gC gO] in HU |- *. nlbools. lia.
    + match goal with
      | |- context [ cround2g_pre8 ?t ?ff ?gg ] =>
          pose proof (cround2g_pre8_ub t ff gg) as HP;
          destruct (fst (cround2g_pre8 t ff gg)) as [x|] eqn:EP
      end.
      * rewrite chi_cadd_cx.
        rewrite !ccolcost_cons, !ccg_unfold.
        rewrite ?ccolcost_cons, ?ccg_unfold in HP.
        cbn [gC gO] in HP |- *. nlbools. lia.
      * cbn [chi cundef snd]. lia.
Qed.
Theorem d_span2B_ub (w : word) (f : N) :
  chi (d_span2B w f) <= 9 * ccolcost w + 14 * f + 440.
Proof.
  unfold d_span2B. swalk.
  match goal with
  | |- context [ if ?b then _ else _ ] => destruct b eqn:EG
  end; [|cbn [chi cundef snd]; lia].
  match goal with
  | |- context [ cround2g ?t ?ff ] =>
      pose proof (cround2g_ub t ff) as HU;
      destruct (fst (cround2g t ff)) as [x|] eqn:EC
  end; [|cbn [chi cundef snd]; lia].
  rewrite chi_cadd_cx.
  rewrite !ccolcost_cons, !ccg_unfold.
  rewrite ?ccolcost_cons, ?ccg_unfold in HU.
  cbn [gC gO] in HU |- *. nlbools. lia.
Qed.
Set Warnings "require-in-module".
Local Open Scope N_scope.
Definition CoarseC_BOUND_MAX : N := TERM_UB + 7 + ALLOW.
Definition CoarseC_closeq (M : N) : N := (M + 21) * (M + 21).
Definition CoarseC_CLOSE_UB : N := CoarseC_closeq CoarseC_BOUND_MAX.
Definition CoarseC_FLIGHT_UB : N :=
  (17 * CoarseC_BOUND_MAX * RET + 5 * RET * RET
     + 880 * CoarseC_BOUND_MAX + 214 * RET + 11440)
  + 67 *
      (3 * (CoarseC_BOUND_MAX + 8 * RET) * RET
         + 6 * RET * RET
         + 547 * (CoarseC_BOUND_MAX + 8 * RET)
         + 54 * RET + 8000).
Definition CoarseC_FLIGHT_UB_WIDE : N :=
  (17 * CoarseC_BOUND_MAX * (3 * CoarseC_BOUND_MAX)
     + 5 * (3 * CoarseC_BOUND_MAX) * (3 * CoarseC_BOUND_MAX)
     + 880 * CoarseC_BOUND_MAX + 214 * (3 * CoarseC_BOUND_MAX) + 11440)
  + 67 *
      (3 * (CoarseC_BOUND_MAX + 8 * (3 * CoarseC_BOUND_MAX)) * (3 * CoarseC_BOUND_MAX)
         + 6 * (3 * CoarseC_BOUND_MAX) * (3 * CoarseC_BOUND_MAX)
         + 547 * (CoarseC_BOUND_MAX + 8 * (3 * CoarseC_BOUND_MAX))
         + 54 * (3 * CoarseC_BOUND_MAX) + 8000).
Definition CoarseC_flight_ub (q : N) : N :=
  if (q <=? RET)%N then CoarseC_FLIGHT_UB else CoarseC_FLIGHT_UB_WIDE.
Lemma half_le (a : N) : (a / 2 <= a)%N.
Proof. apply N.div_le_upper_bound; [discriminate|lia]. Qed.
Lemma clean_quad (K M : N) :
  12 * K <= M ->
  63 * ((K / 2) * (K / 2 - 1)) + 243 * (K / 2)
    <= CoarseC_closeq M.
Proof.
  intros HK. pose proof (half_le K) as HH.
  assert (K / 2 - 1 <= K / 2)%N by lia.
  unfold CoarseC_closeq. nia.
Qed.
Lemma four_quad (c K M : N) :
  10 * c + 14 * K <= M ->
  108 * ((K / 2) * (K / 2 - 1)) + (40 * c + 184) * (K / 2)
    <= CoarseC_closeq M.
Proof.
  intros HK. pose proof (half_le K) as HH.
  assert (K / 2 - 1 <= K / 2)%N by lia.
  unfold CoarseC_closeq. nia.
Qed.
Ltac close_word :=
  repeat (cbv iota;
          match goal with
          | |- context [match ?x with _ => _ end] => is_var x; destruct x
          end);
  cbv iota;
  cbn [chi cx cundef fst snd gmeas];
  rewrite ?ccolcost_cons, ?ccg_unfold.
Lemma d_clean_quad_ub (w : word) (f : N) :
  chi (d_clean w f)
    <= CoarseC_closeq (gmeas w f).
Proof.
  unfold d_clean. close_word.
  all: try lia.
  destruct (2 <=? n)%N; cbn [chi cx cundef fst snd].
  2: lia.
  apply clean_quad.
  unfold gmeas.
  rewrite !ccolcost_cons, !ccg_unfold.
  cbn [gC gO]. lia.
Qed.
Lemma d_four_quad_ub (w : word) (f : N) :
  chi (d_four w f)
    <= CoarseC_closeq (gmeas w f).
Proof.
  unfold d_four. close_word.
  all: try lia.
  destruct (2 <=? n0)%N; cbn [chi cx cundef fst snd].
  2: lia.
  apply four_quad.
  unfold gmeas.
  rewrite !ccolcost_cons, !ccg_unfold.
  cbn [gC gO]. lia.
Qed.
Lemma linear_in_quad (C f k : N) :
  k <= 440 ->
  9 * C + 14 * f + k
    <= CoarseC_closeq (C + 2 * f).
Proof. intros Hk. unfold CoarseC_closeq. nia. Qed.
Lemma comp_linear_in_quad (C f : N) :
  20 * C + 2 * f + 300
    <= CoarseC_closeq (C + 2 * f).
Proof. unfold CoarseC_closeq. nia. Qed.
Theorem front_quad_ub (w : word) (f : N)
        (r : res) (d : cost) :
  cstep_front w f = Some (r, d) ->
  chi d
    <= CoarseC_closeq (gmeas w f).
Proof.
  unfold cstep_front. rewrite cfront_rules_unfold.
  unfold cfr_primordial, cfr_prim4, cfr_clean,
         cfr_four, cfr_span2A, cfr_span2A',
         cfr_span2C', cfr_span8far, cfr_span2B,
         cfr_span8orph, cfr_span8, cfr_rot,
         cfr_502, cfr_512, cfr_522, decorate.
  cbn [cfirst_rule]. intros HS.
  pose proof (d_primordial_ub w f) as H1.
  pose proof (d_prim4_ub w f) as H2.
  pose proof (d_clean_quad_ub w f) as H3.
  pose proof (d_four_quad_ub w f) as H4.
  pose proof (d_span2A_ub w f) as H5.
  pose proof (d_span2A'_ub w f) as H6.
  pose proof (d_span2C'_ub w f) as H7.
  pose proof (d_span8far_ub w f) as H8.
  pose proof (d_span2B_ub w f) as H9.
  pose proof (d_span8orph_ub w f) as H10.
  pose proof (d_span8_ub w f) as H11.
  pose proof (d_rot_ub w f) as H12.
  pose proof (d_502_ub w f) as H13.
  pose proof (d_512_ub w f) as H14.
  pose proof (d_522_ub w f) as H15.
  unfold CoarseC_closeq.
  destruct (fr_primordial w f) as [x1|];
    [injection HS as _ <-; unfold gmeas in *; nia|].
  destruct (fr_prim4 w f) as [x2|];
    [injection HS as _ <-; unfold gmeas in *; nia|].
  destruct (fr_clean w f) as [x3|];
    [injection HS as _ <-; exact H3|].
  destruct (fr_four w f) as [x4|];
    [injection HS as _ <-; exact H4|].
  destruct (fr_span2A w f) as [x5|];
    [injection HS as _ <-; unfold gmeas in *; nia|].
  destruct (fr_span2A' w f) as [x6|];
    [injection HS as _ <-; unfold gmeas in *; nia|].
  destruct (fr_span2C' w f) as [x7|];
    [injection HS as _ <-; unfold gmeas in *; nia|].
  destruct (fr_span8far w f) as [x8|];
    [injection HS as _ <-; unfold gmeas in *; nia|].
  destruct (fr_span2B w f) as [x9|];
    [injection HS as _ <-; unfold gmeas in *; nia|].
  destruct (fr_span8orph w f) as [xa|];
    [injection HS as _ <-; unfold gmeas in *; nia|].
  destruct (fr_span8 w f) as [xb|];
    [injection HS as _ <-; unfold gmeas in *; nia|].
  destruct (fr_rot w f) as [xc|];
    [injection HS as _ <-; unfold gmeas in *; nia|].
  destruct (fr_502 w f) as [xd|];
    [injection HS as _ <-; unfold gmeas in *; nia|].
  destruct (fr_512 w f) as [xe|];
    [injection HS as _ <-; unfold gmeas in *; nia|].
  destruct (fr_522 w f) as [xf|];
    [injection HS as _ <-; unfold gmeas in *; nia|].
  discriminate HS.
Qed.
Theorem cstep_quad_ub (w : word) (f : N) (h : nat)
        (w2 : word) (f2 : N) (i : nat) :
  step w f h = (ROk w2 f2, i) ->
  chi (snd (cstep w f h))
    <= CoarseC_closeq (gmeas w f).
Proof.
  intros HS. unfold cstep.
  destruct (cstep_front w f) as [[r d]|] eqn:EF.
  - cbn [snd]. exact (front_quad_ub w f r d EF).
  - pose proof (cstep_front_proj w f) as HP.
    rewrite EF in HP. cbn [option_map] in HP.
    assert (HE : step_after_front None w f h = (ROk w2 f2, i)).
    { unfold step in HS. rewrite <- HP in HS.
      unfold step_after_front, step_after_front_with,
             step_after_front_with_guard in HS |- *.
      exact HS. }
    pose proof (d_comp_site_ub w f h w2 f2 i HE) as HU.
    rewrite HE. cbn [snd]. unfold gmeas.
    eapply N.le_trans; [exact HU|apply comp_linear_in_quad].
Qed.
Theorem flat_act_reachable_at (w : word) (f : N) (h : nat)
        (w2 : word) (f2 : N) (i : nat) (M : N) :
  step w f h = (ROk w2 f2, i) ->
  gmeas w f <= M ->
  creach (0%N, CoarseC_closeq M)
    (wconf [] 0 (sdecode w f))
    (wconf [] 0 (sdecode w2 f2)).
Proof.
  intros HS HM.
  destruct (cstep_of_step w f h (ROk w2 f2) i HS) as (d & EC).
  pose proof (cstep_quad_ub w f h w2 f2 i HS) as HU.
  rewrite EC in HU. cbn [snd] in HU.
  assert (HC : CoarseC_closeq (gmeas w f) <= CoarseC_closeq M).
  { unfold CoarseC_closeq. nia. }
  refine (creach_widen' d (0%N, CoarseC_closeq M) _ _ _ _
            (cstep_sound_live w f h w2 f2 i d EC));
    cbn [fst snd]; unfold clo, chi in *; lia.
Qed.
Lemma front_linear_ub (w : word) (f : N)
      (r : res) (d : cost) :
  cstep_front w f = Some (r, d) ->
  fr_clean w f = None -> fr_four w f = None ->
  chi d <= 9 * ccolcost w + 14 * f + 440.
Proof.
  unfold cstep_front. rewrite cfront_rules_unfold.
  unfold cfr_primordial, cfr_prim4, cfr_clean,
         cfr_four, cfr_span2A, cfr_span2A',
         cfr_span2C', cfr_span8far, cfr_span2B,
         cfr_span8orph, cfr_span8, cfr_rot,
         cfr_502, cfr_512, cfr_522, decorate.
  cbn [cfirst_rule]. intros HS HC HF.
  pose proof (d_primordial_ub w f).
  pose proof (d_prim4_ub w f).
  pose proof (d_span2A_ub w f).
  pose proof (d_span2A'_ub w f).
  pose proof (d_span2C'_ub w f).
  pose proof (d_span8far_ub w f).
  pose proof (d_span2B_ub w f).
  pose proof (d_span8orph_ub w f).
  pose proof (d_span8_ub w f).
  pose proof (d_rot_ub w f).
  pose proof (d_502_ub w f).
  pose proof (d_512_ub w f).
  pose proof (d_522_ub w f).
  destruct (fr_primordial w f) as [x1|]; [injection HS as _ <-; lia|].
  destruct (fr_prim4 w f) as [x2|]; [injection HS as _ <-; lia|].
  rewrite HC in HS. rewrite HF in HS.
  destruct (fr_span2A w f) as [x5|]; [injection HS as _ <-; lia|].
  destruct (fr_span2A' w f) as [x6|]; [injection HS as _ <-; lia|].
  destruct (fr_span2C' w f) as [x7|]; [injection HS as _ <-; lia|].
  destruct (fr_span8far w f) as [x8|]; [injection HS as _ <-; lia|].
  destruct (fr_span2B w f) as [x9|]; [injection HS as _ <-; lia|].
  destruct (fr_span8orph w f) as [xa|]; [injection HS as _ <-; lia|].
  destruct (fr_span8 w f) as [xb|]; [injection HS as _ <-; lia|].
  destruct (fr_rot w f) as [xc|]; [injection HS as _ <-; lia|].
  destruct (fr_502 w f) as [xd|]; [injection HS as _ <-; lia|].
  destruct (fr_512 w f) as [xe|]; [injection HS as _ <-; lia|].
  destruct (fr_522 w f) as [xf|]; [injection HS as _ <-; lia|].
  discriminate HS.
Qed.
Lemma cstep_linear_ub (w : word) (f : N) (h : nat)
      (w2 : word) (f2 : N) (i : nat) :
  step w f h = (ROk w2 f2, i) ->
  fr_clean w f = None -> fr_four w f = None ->
  chi (snd (cstep w f h)) <= 20 * gmeas w f + 500.
Proof.
  intros HS HC HF. unfold cstep.
  destruct (cstep_front w f) as [[r d]|] eqn:EFR.
  - cbn [snd]. pose proof (front_linear_ub w f r d EFR HC HF).
    unfold gmeas. lia.
  - pose proof (cstep_front_proj w f) as HP.
    rewrite EFR in HP. cbn [option_map] in HP.
    assert (HE : step_after_front None w f h = (ROk w2 f2, i)).
    { unfold step in HS. rewrite <- HP in HS.
      unfold step_after_front, step_after_front_with,
             step_after_front_with_guard in HS |- *. exact HS. }
    pose proof (d_comp_site_ub w f h w2 f2 i HE) as HU.
    rewrite HE. cbn [snd]. unfold gmeas in *. lia.
Qed.
Lemma act_numeric :
  20 * CoarseC_BOUND_MAX + 500 <= GrowC_ACT_UB.
Proof. vm_compute. discriminate. Qed.
Theorem flat_act_reachable_act0 (w : word) (f : N) (h : nat)
        (w2 : word) (f2 : N) (i : nat) (Lm : N) :
  step w f h = (ROk w2 f2, i) ->
  fr_clean w f = None -> fr_four w f = None ->
  gmeas w f <= Lm + ALLOW ->
  Lm <= TERM_UB + 7 ->
  creach (0%N, GrowC_ACT_UB)
    (wconf [] 0 (sdecode w f))
    (wconf [] 0 (sdecode w2 f2)).
Proof.
  intros HS HC HF HM HT.
  destruct (cstep_of_step w f h (ROk w2 f2) i HS) as (d & EC).
  pose proof (cstep_linear_ub w f h w2 f2 i HS HC HF) as HU.
  rewrite EC in HU. cbn [snd] in HU.
  pose proof act_numeric as HA. unfold CoarseC_BOUND_MAX in HA.
  refine (creach_widen' d (0%N, GrowC_ACT_UB) _ _ _ _
            (cstep_sound_live w f h w2 f2 i d EC));
    cbn [fst snd]; unfold clo, chi in *; lia.
Qed.
Lemma close_numeric :
  CoarseC_closeq (TERM_UB + 7 + ALLOW) <= CoarseC_CLOSE_UB.
Proof. unfold CoarseC_CLOSE_UB, CoarseC_BOUND_MAX. reflexivity. Qed.
Lemma close_ceiling (Lm M : N) :
  Lm <= TERM_UB + 7 -> M <= Lm + ALLOW ->
  CoarseC_closeq M <= CoarseC_CLOSE_UB.
Proof. intros HT HM. pose proof close_numeric. unfold CoarseC_closeq in *. nia. Qed.
Theorem flat_act_reachable0 (w : word) (f : N) (h : nat)
        (w2 : word) (f2 : N) (i : nat) (Lm : N) :
  step w f h = (ROk w2 f2, i) ->
  gmeas w f <= Lm + ALLOW ->
  Lm <= TERM_UB + 7 ->
  creach (0%N, CoarseC_CLOSE_UB)
    (wconf [] 0 (sdecode w f))
    (wconf [] 0 (sdecode w2 f2)).
Proof.
  intros HS HM HT.
  destruct (cstep_of_step w f h (ROk w2 f2) i HS) as (d & EC).
  pose proof (cstep_quad_ub w f h w2 f2 i HS) as HU.
  rewrite EC in HU. cbn [snd] in HU.
  pose proof (close_ceiling Lm (gmeas w f) HT HM) as HC.
  refine (creach_widen' d (0%N, CoarseC_CLOSE_UB) _ _ _ _
            (cstep_sound_live w f h w2 f2 i d EC));
    cbn [fst snd]; unfold clo, chi in *; lia.
Qed.
Definition sconf (s : sstate) : Q * tape :=
  let '(w, f, _) := s in wconf [] 0 (sdecode w f).
Lemma stepk_reachable0 (k : nat) :
  forall (s s' : sstate) (Lm : N),
  stepk k s = Some s' ->
  gmeasS s' + 2 * N.of_nat k <= Lm + ALLOW ->
  Lm <= TERM_UB + 7 ->
  creach (0%N, N.of_nat k * CoarseC_CLOSE_UB) (sconf s) (sconf s').
Proof.
  induction k as [|k IH]; intros s s' Lm HRun HB HT.
  - cbn [stepk N.of_nat] in HRun |- *.
    injection HRun as <-. unfold sconf.
    destruct s as [[w f] h]. cbn. apply creach_refl.
  - cbn [stepk] in HRun.
    destruct (step1 s) as [s1|] eqn:E1; [|discriminate HRun].
    pose proof (stepk_grow (S k) s s' ltac:(cbn [stepk];
      rewrite E1; exact HRun)) as HG.
    assert (HB0 : gmeasS s <= Lm + ALLOW).
    { eapply N.le_trans; [exact HG|]. exact HB. }
    assert (HB1 : gmeasS s' + 2 * N.of_nat k
                    <= Lm + ALLOW).
    { rewrite Nat2N.inj_succ in HB. lia. }
    destruct s as [[w f] h], s1 as [[w1 f1] h1].
    unfold step1 in E1.
    destruct (step w f h) as [[wr fr| |] i] eqn:ES;
      try discriminate E1.
    injection E1 as <- <- <-.
    cbn [sconf gmeasS] in HB0 |- *.
    replace (0%N, N.of_nat (S k) * CoarseC_CLOSE_UB)
      with (cadd (0%N, CoarseC_CLOSE_UB)
              (0%N, N.of_nat k * CoarseC_CLOSE_UB)).
    2: { unfold cadd. cbn [fst snd]. f_equal.
         rewrite Nat2N.inj_succ. nia. }
    eapply creach_trans.
    + exact (flat_act_reachable0 w f h wr fr i Lm ES HB0 HT).
    + exact (IH (wr, fr, if Nat.ltb i 5 then O else (i - 4)%nat)
                  s' Lm HRun HB1 HT).
Qed.
Theorem stepN_reachable0 (q : N) (s s' : sstate) (Lm : N) :
  stepN q s = Some s' ->
  gmeasS s' + 2 * q <= Lm + ALLOW ->
  Lm <= TERM_UB + 7 ->
  creach (0%N, q * CoarseC_CLOSE_UB) (sconf s) (sconf s').
Proof.
  unfold stepN. intros HRun HB HT.
  pose proof (stepk_reachable0 (N.to_nat q) s s' Lm HRun) as H.
  rewrite N2Nat.id in H. exact (H HB HT).
Qed.
Lemma stepk_reachable_bounded (k : nat) :
  forall (s s' : sstate) (M : N),
  stepk k s = Some s' ->
  gmeasS s' + 2 * N.of_nat k <= M ->
  creach (0%N, N.of_nat k * CoarseC_closeq M) (sconf s) (sconf s').
Proof.
  induction k as [|k IH]; intros s s' M HRun HB.
  - cbn [stepk N.of_nat] in HRun |- *.
    injection HRun as <-. unfold sconf.
    destruct s as [[w f] h]. cbn. apply creach_refl.
  - cbn [stepk] in HRun.
    destruct (step1 s) as [s1|] eqn:E1; [|discriminate HRun].
    pose proof (stepk_grow (S k) s s' ltac:(cbn [stepk];
      rewrite E1; exact HRun)) as HG.
    assert (HB0 : gmeasS s <= M).
    { eapply N.le_trans; [exact HG|exact HB]. }
    assert (HB1 : gmeasS s' + 2 * N.of_nat k <= M).
    { rewrite Nat2N.inj_succ in HB. lia. }
    destruct s as [[w f] h], s1 as [[w1 f1] h1].
    unfold step1 in E1.
    destruct (step w f h) as [[wr fr| |] i] eqn:ES;
      try discriminate E1.
    injection E1 as <- <- <-.
    cbn [sconf gmeasS] in HB0 |- *.
    replace (0%N, N.of_nat (S k) * CoarseC_closeq M)
      with (cadd (0%N, CoarseC_closeq M)
              (0%N, N.of_nat k * CoarseC_closeq M)).
    2: { unfold cadd. cbn [fst snd]. f_equal.
         rewrite Nat2N.inj_succ. nia. }
    eapply creach_trans.
    + exact (flat_act_reachable_at w f h wr fr i M ES HB0).
    + exact (IH (wr, fr, if Nat.ltb i 5 then O else (i - 4)%nat)
                  s' M HRun HB1).
Qed.
Definition CoarseC_spanq (q M : N) : N := q * CoarseC_closeq (M + 2 * q).
Theorem stepN_reachable_span (q : N) (s s' : sstate) :
  stepN q s = Some s' ->
  creach (0%N, CoarseC_spanq q (gmeasS s')) (sconf s) (sconf s').
Proof.
  unfold stepN, CoarseC_spanq. intros HRun.
  pose proof
    (stepk_reachable_bounded (N.to_nat q) s s'
       (gmeasS s' + 2 * q) HRun) as H.
  rewrite N2Nat.id in H. apply H. lia.
Qed.
Lemma closed_tickk_reachable_act (k : nat) :
  forall (s s' : sstate) (Lm : N),
  closed_tickk k s = Some s' ->
  gmeasS s' + 2 * N.of_nat k <= Lm + ALLOW ->
  Lm <= TERM_UB + 7 ->
  creach (0%N, N.of_nat k * GrowC_ACT_UB) (sconf s) (sconf s').
Proof.
  induction k as [|k IH]; intros s s' Lm HRun HB HT.
  - cbn [closed_tickk N.of_nat] in HRun |- *.
    injection HRun as <-. unfold sconf.
    destruct s as [[w f] h]. cbn. apply creach_refl.
  - cbn [closed_tickk] in HRun.
    destruct (closed_tick s) as [s1|] eqn:E1;
      [|discriminate HRun].
    pose proof (closed_tickk_sound (S k) s s'
      ltac:(cbn [closed_tickk]; rewrite E1; exact HRun))
      as HSteps.
    pose proof (stepk_grow (S k) s s' HSteps) as HG.
    assert (HB0 : gmeasS s <= Lm + ALLOW).
    { eapply N.le_trans; [exact HG|exact HB]. }
    assert (HB1 : gmeasS s' + 2 * N.of_nat k
                    <= Lm + ALLOW).
    { rewrite Nat2N.inj_succ in HB. lia. }
    destruct s as [[w f] h], s1 as [[w1 f1] h1].
    destruct (closed_tick_front_none
                w w1 f f1 h h1 E1) as (HC & HF).
    pose proof (closed_tick_sound
                  w f h w1 f1 h1 E1) as EStep.
    unfold step1 in EStep.
    destruct (step w f h) as [[wr fr| |] i] eqn:ES;
      try discriminate EStep.
    injection EStep as <- <- <-.
    cbn [sconf gmeasS] in HB0 |- *.
    replace (0%N, N.of_nat (S k) * GrowC_ACT_UB)
      with (cadd (0%N, GrowC_ACT_UB)
              (0%N, N.of_nat k * GrowC_ACT_UB)).
    2: { unfold cadd. cbn [fst snd]. f_equal.
         rewrite Nat2N.inj_succ. nia. }
    eapply creach_trans.
    + exact (flat_act_reachable_act0 w f h wr fr i Lm ES HC HF HB0 HT).
    + exact (IH (wr, fr, if Nat.ltb i 5 then O else (i - 4)%nat)
                  s' Lm HRun HB1 HT).
Qed.
Theorem zjump3_reachable_act (w : word) (f : N) (h : nat)
        (q : N) (s' : sstate) (Lm : N) :
  zjump3 w f h = Some (q, s') ->
  gmeasS s' + 2 * q <= Lm + ALLOW ->
  Lm <= TERM_UB + 7 ->
  creach (0%N, q * GrowC_ACT_UB) (sconf (w,f,h)) (sconf s').
Proof.
  intros HZ HB HT.
  pose proof (zjump3_closed _ _ _ _ _ HZ) as HC.
  pose proof (closed_tickk_reachable_act (N.to_nat q)
                (w,f,h) s' Lm HC) as HR.
  rewrite N2Nat.id in HR. exact (HR HB HT).
Qed.
Definition fcarm_size (w : word) (f : N) (a : fcarm) : Prop :=
  match a with
  | FCnone => True
  | FCclean ac K => K * 12 <= gmeas w f /\ ac <= 136
  | FCfour ac c M =>
      M * 14 + c * 2 <= gmeas w f /\
      ac <= 30 * c + 81 /\ 2 <= M
  end.
Ltac digsG :=
  repeat match goal with
  | |- context [match ?x with N0 => _ | N.pos _ => _ end] =>
      is_var x; destruct x
  | |- context [match ?x with xI _ => _ | xO _ => _ | xH => _ end] =>
      is_var x; destruct x
  end.
Lemma coarse_gmeas_eq (w : word) (f : N) :
  gmeas w f = ccolcost w + 2 * f.
Proof. reflexivity. Qed.
Opaque gmeas.
Lemma fcsplit_size (w : word) (f : N) :
  fcarm_size w f (fcsplit w).
Proof.
  destruct w as [|[[o0 z0] c_0] w];
    [cbn [fcsplit fcarm_size]; exact I|].
  destruct w as [|[[o1 z1] c1] w];
    [cbn [fcsplit fcarm_size]; digsG; exact I|].
  destruct w as [|[[o2 z2] c2] rest];
    [cbn [fcsplit fcarm_size]; digsG; exact I|].
  destruct rest as [|[[o3 z3] c3] t].
  all: cbn [fcsplit fcarm_size]; digsG.
  all: repeat match goal with
       | |- context [if ?b then _ else _] =>
           let E := fresh "EB" in destruct b eqn:E; cbn
       end.
  all: repeat match goal with
       | E : (_ && _)%bool = true |- _ =>
           let E2 := fresh "EB" in
           apply andb_prop in E; destruct E as [E E2]
       | E : (_ <=? _)%N = true |- _ => apply N.leb_le in E
       | E : (_ =? _)%N = true |- _ =>
           apply N.eqb_eq in E; inversion E; subst; clear E
       | E : Pos.eqb _ _ = true |- _ =>
           apply Pos.eqb_eq in E; subst; clear E
       end.
  all: try exact I.
  all: repeat rewrite coarse_gmeas_eq;
       repeat rewrite ccolcost_cons;
       repeat rewrite ccg_unfold;
       repeat split; try nia.
Qed.
Transparent gmeas.
Lemma fcsplit_clean_size (w : word) (f ac K : N) :
  fcsplit w = FCclean ac K ->
  K * 12 <= gmeas w f /\ ac <= 136.
Proof.
  intros E. pose proof (fcsplit_size w f) as H. rewrite E in H. exact H.
Qed.
Lemma fcsplit_four_size (w : word) (f ac c M : N) :
  fcsplit w = FCfour ac c M ->
  M * 14 + c * 2 <= gmeas w f /\
  ac <= 30 * gmeas w f + 81 /\ 2 <= M.
Proof.
  intros E. pose proof (fcsplit_size w f) as H. rewrite E in H.
  destruct H as (HM & HA & HMin). split; [exact HM|]. split; [|exact HMin].
  eapply N.le_trans; [exact HA|]. unfold gmeas in *. nia.
Qed.
Lemma dfc_quad_ub (w : word) (f : N) :
  chi (dfc w f)
    <= CoarseC_closeq (gmeas w f).
Proof.
  unfold dfc.
  destruct (fcsplit w) as [|ac K|ac c M] eqn:E;
    cbn [chi cx cundef fst snd].
  - lia.
  - destruct (fcsplit_clean_size w f ac K E) as (HK & HA).
    unfold cyc_clean.
    pose proof (half_le K) as HH.
    pose proof (N.le_sub_l (K / 2) 1) as HS. unfold CoarseC_closeq. nia.
  - destruct (fcsplit_four_size w f ac c M E) as (HM & HA & _).
    unfold cyc_four.
    pose proof (half_le M) as HH.
    pose proof (N.le_sub_l (M / 2) 1) as HS. unfold CoarseC_closeq. nia.
Qed.
Lemma below_late_pow (x : N) :
  N.size x < LATE_BITS ->
  x < 2 ^ LATE_BITS.
Proof.
  intros HS. eapply N.lt_trans; [apply N.size_gt|].
  apply N.pow_lt_mono_r; lia.
Qed.
Lemma early_ub_value :
  EARLY_UB =
    47 * (2 ^ LATE_BITS) *
         (2 ^ LATE_BITS).
Proof. vm_compute. reflexivity. Qed.
Lemma late_pow_ge_8 :
  8 <= 2 ^ LATE_BITS.
Proof.
  pose proof
    (N.pow_le_mono_r 2 3 LATE_BITS
       ltac:(discriminate)
       ltac:(unfold LATE_BITS; lia)) as H.
  change (8 <= 2 ^ LATE_BITS) in H. exact H.
Qed.
Lemma dfc_early_ub (w : word) (f : N) :
  front_late w = false ->
  chi (dfc w f) <= EARLY_UB.
Proof.
  Transparent front_late.
  unfold front_late, dfc.
  Opaque front_late.
  destruct (fcsplit w) as [|ac K|ac c M] eqn:E;
    cbn [chi cx cundef fst snd]; intros HL.
  - unfold EARLY_UB, EARLY_UNITS,
           ACT_UB. lia.
  - apply N.leb_gt in HL.
    pose proof (below_late_pow K HL) as HK.
    pose proof (fcsplit_size w f) as HSize. rewrite E in HSize.
    destruct HSize as (_ & HA).
    pose proof (N.mul_div_le K 2 ltac:(discriminate)) as HD.
    pose proof (N.le_sub_l (K / 2) 1) as HS.
    rewrite early_ub_value. unfold cyc_clean.
    pose proof late_pow_ge_8 as HP8.
    assert (HR : 2 * (K / 2) <= 2 ^ LATE_BITS) by lia.
    pose proof (N.mul_le_mono _ _ _ _ HR HR) as Hsq.
    nia.
  - apply N.leb_gt in HL.
    assert (HCs : N.size c < LATE_BITS).
    { pose proof (N.le_max_l (N.size c) (N.size M)). lia. }
    assert (HMs : N.size M < LATE_BITS).
    { pose proof (N.le_max_r (N.size c) (N.size M)). lia. }
    pose proof (below_late_pow c HCs) as HC.
    pose proof (below_late_pow M HMs) as HM.
    pose proof (fcsplit_size w f) as HSize. rewrite E in HSize.
    destruct HSize as (_ & HA & HMin).
    pose proof (N.mul_div_le M 2 ltac:(discriminate)) as HD.
    pose proof (N.le_sub_l (M / 2) 1) as HS.
    rewrite early_ub_value. unfold cyc_four.
    set (P := 2 ^ LATE_BITS) in *.
    set (r := M / 2) in *.
    pose proof late_pow_ge_8 as HP8.
    change (8 <= P) in HP8.
    assert (HR1 : 1 <= r).
    { subst r. apply N.div_le_lower_bound; [discriminate|exact HMin]. }
    assert (HR : 2 * r <= P - 1) by lia.
    assert (HC' : c <= P - 1) by lia.
    pose proof (N.mul_le_mono _ _ _ _ HR HR) as Hsq.
    pose proof (N.mul_le_mono _ _ _ _ HC' HR) as Hcross.
    clear HCs HMs HC HM HMin HD HS.
    clearbody P r. clear w f E HL M.
    nia.
Qed.
Theorem front_close_reachable_early
        (sg : list seg)
        (cw : word) (f : N) (q : nat)
        (cw2 : word) (f2 : N) :
  lin_front_close cw f = Some (q, cw2, f2) ->
  front_late cw = false ->
  creach (0%N, EARLY_UB)
    (wconf [] 0 (sdecode (lin_flat sg cw) f))
    (wconf [] 0 (sdecode (lin_flat sg cw2) f2)).
Proof.
  intros HC HL. pose proof (dfc_early_ub cw f HL) as HU.
  refine (creach_widen' (dfc cw f)
            (0%N, EARLY_UB) _ _ _ _
            (lin_front_close_creach sg cw f q cw2 f2 HC));
    cbn [fst snd]; unfold clo, chi in *; lia.
Qed.
Theorem front_close_reachable0 (sg : list seg)
        (cw : word) (f : N) (q : nat) (cw2 : word) (f2 : N)
        (Lm : N) :
  lin_front_close cw f = Some (q, cw2, f2) ->
  gmeas (lin_flat sg cw) f <= Lm + ALLOW ->
  Lm <= TERM_UB + 7 ->
  creach (0%N, CoarseC_CLOSE_UB)
    (wconf [] 0 (sdecode (lin_flat sg cw) f))
    (wconf [] 0 (sdecode (lin_flat sg cw2) f2)).
Proof.
  intros HC HM HT.
  pose proof (dfc_quad_ub (lin_flat sg cw) f) as HU.
  pose proof (close_ceiling Lm
    (gmeas (lin_flat sg cw) f) HT HM) as HB.
  rewrite (dfc_flat_on_fire sg cw f q cw2 f2 HC) in HU.
  refine (creach_widen' (dfc cw f)
            (0%N, CoarseC_CLOSE_UB) _ _ _ _
            (lin_front_close_creach sg cw f q cw2 f2 HC));
    cbn [fst snd]; unfold clo, chi in *; lia.
Qed.
