Local Open Scope N_scope.
Local Open Scope bool_scope.
Local Open Scope sym.
Local Open Scope N_scope.
Local Open Scope bool_scope.
Local Open Scope sym.
Local Open Scope N_scope.
Definition rc (c : N) : N := (14*c + 22)%N.
Lemma rc_wcolcost (c : N) :
  wcolcost (rung1 c) = rc c.
Proof. unfold rc. apply wcolcost_rung1. Qed.
Fixpoint stockmass (rs : list (option N)) : N :=
  match rs with
  | [] => 0
  | None :: r => stockmass r
  | Some c :: r => (rc c + stockmass r)
  end.
Fixpoint stockcost (rs : list (option N)) : N :=
  match rs with
  | [] => 0
  | None :: r => stockcost r
  | Some c :: r => (rc c * N.of_nat (length r) + stockcost r)
  end.
Lemma stockmass_stock (rs : list (option N)) :
  stockmass rs = wcolcost (schedule_stock rs).
Proof.
  induction rs as [|[c|] r IH]; cbn [stockmass schedule_stock].
  - reflexivity.
  - rewrite CascadeC_wcolcost_app, rc_wcolcost, IH. lia.
  - exact IH.
Qed.
Lemma stockcost_app (a b : list (option N)) :
  stockcost (a ++ b)
  = (stockcost a + N.of_nat (length b) * stockmass a + stockcost b)%N.
Proof.
  induction a as [|[c|] a IH]; cbn [app stockcost stockmass length].
  - lia.
  - rewrite IH, length_app, Nat2N.inj_add. lia.
  - rewrite IH. lia.
Qed.
Lemma stockcost_nones (n : nat) : stockcost (repeat None n) = 0%N.
Proof. induction n as [|n IH]; [reflexivity|exact IH]. Qed.
Lemma stockmass_nones (n : nat) : stockmass (repeat None n) = 0%N.
Proof. induction n as [|n IH]; [reflexivity|exact IH]. Qed.
Lemma stockcost_one (oc : option N) : stockcost [oc] = 0%N.
Proof. destruct oc as [c|]; cbn [stockcost length]; lia. Qed.
Lemma stockmass_one (oc : option N) :
  stockmass [oc] = match oc with Some c => rc c | None => 0%N end.
Proof. destruct oc as [c|]; cbn [stockmass]; lia. Qed.
Lemma deliv_to_sched_tripsc (rs : list (option N)) :
  forall (n : nat) (T : N) (w out : word) (f f' : N),
  length rs = n ->
  deliv n T w f out f' ->
  sched_tripsc (T + stockcost rs)%N rs w f
    (schedule_stock rs ++ out) f'.
Proof.
  induction rs as [|[c|] rs IH]; intros n T w out f f' HLen HD.
  - cbn [length] in HLen; subst n.
    destruct (deliv_zero_inv _ _ _ _ _ HD) as (-> & E).
    cbn [stockcost schedule_stock app sched_tripsc].
    split; [reflexivity|exact E].
  - cbn [length] in HLen; subst n.
    replace (S (length rs)) with (1 + length rs)%nat in HD by lia.
    destruct (deliv_split 1 (length rs) T w out f f' HD)
      as (sm & fm & Ta & Tb & ET & HA & HB).
    pose proof (deliv_one_inv _ _ _ _ _ HA) as HTrip.
    pose proof (deliv_cols _ _ (rung1 c)
      _ _ _ _ (delivery_cols_rung c) HB) as HB'.
    rewrite rc_wcolcost in HB'.
    pose proof (IH (length rs) _ _ _ _ _ eq_refl HB') as HIH.
    cbn [schedule_stock stockcost].
    rewrite <- app_assoc.
    exists Ta, (Tb + N.of_nat (length rs) * rc c + stockcost rs)%N, sm, fm.
    split; [lia|]. split; [exact HTrip|].
    cbn [sd_next]. exact HIH.
  - cbn [length] in HLen; subst n.
    replace (S (length rs)) with (1 + length rs)%nat in HD by lia.
    destruct (deliv_split 1 (length rs) T w out f f' HD)
      as (sm & fm & Ta & Tb & ET & HA & HB).
    pose proof (deliv_one_inv _ _ _ _ _ HA) as HTrip.
    pose proof (IH (length rs) _ _ _ _ _ eq_refl HB) as HIH.
    cbn [schedule_stock stockcost].
    exists Ta, (Tb + stockcost rs)%N, sm, fm.
    split; [lia|]. split; [exact HTrip|].
    cbn [sd_next]. exact HIH.
Qed.
Fixpoint dlocals (rl : list N) (p rem b : N) : N :=
  match rl with
  | [] => 0
  | d :: rest =>
      (dladder p b (N.to_nat (27-p)) + 14*b + 22
       + match rest with
         | [] => dladder 0 (d-3) (N.to_nat rem)
         | _ => dlocals rest 0 rem (d-3)
         end)
  end.
Fixpoint rcredit (rl : list N) (rem : N) : N :=
  match rl with
  | [] => 0
  | d :: r => (rc d * (28 * N.of_nat (length r) + rem) + rcredit r rem)
  end.
Lemma dlocals_cons_ne (d : N) (rest : list N) (p rem b : N) :
  rest <> [] ->
  dlocals (d :: rest) p rem b
  = (dladder p b (N.to_nat (27-p)) + 14*b + 22
     + dlocals rest 0 rem (d-3))%N.
Proof. intros H. destruct rest as [|x r]; [contradiction|reflexivity]. Qed.
Lemma rcredit_cons (d : N) (r : list N) (rem : N) :
  rcredit (d :: r) rem
  = (rc d * (28 * N.of_nat (length r) + rem) + rcredit r rem)%N.
Proof. reflexivity. Qed.
Lemma CascadeWI_wcolsum_cons (d : N) (r : list N) :
  wcolsum (d :: r) = (rc d + wcolsum r)%N.
Proof. unfold rc. reflexivity. Qed.
Lemma sched_tripsc_app_inv (a : list (option N)) :
  forall (b : list (option N)) (T : N) (w out : word) (f f' : N),
  sched_tripsc T (a ++ b) w f out f' ->
  exists mid fm Ta Tb,
    T = (Ta + Tb)%N /\ sched_tripsc Ta a w f mid fm
    /\ sched_tripsc Tb b mid fm out f'.
Proof.
  induction a as [|o a IH]; intros b T w out f f' H.
  - cbn [app] in H. exists w, f, 0%N, T.
    split; [lia|]. split; [cbn [sched_tripsc]; auto|exact H].
  - cbn [app sched_tripsc] in H.
    destruct H as (K & T1 & w1 & f1 & ET & HD & HR).
    destruct (IH b T1 (sd_next o w1) out f1 f' HR)
      as (mid & fm & Ta & Tb & ET1 & HA & HB).
    exists mid, fm, (K + Ta)%N, Tb.
    split; [lia|]. split; [|exact HB].
    cbn [sched_tripsc]. exists K, Ta, w1, f1.
    split; [reflexivity|]. split; [exact HD|exact HA].
Qed.
Lemma sched_tripsc_nones (n : nat) :
  forall (T : N) (w out : word) (f f' : N),
  sched_tripsc T (repeat None n) w f out f' ->
  deliv n T w f out f'.
Proof.
  induction n as [|n IH]; intros T w out f f' H.
  - cbn [repeat sched_tripsc] in H. destruct H as (-> & E).
    apply deliv_O. exact E.
  - cbn [repeat sched_tripsc] in H.
    destruct H as (K & T1 & w1 & f1 & -> & HD & HR).
    cbn [sd_next] in HR.
    exact (deliv_S _ _ _ _ _ _ _ _ _ HD (IH _ _ _ _ _ HR)).
Qed.
Lemma sched_tripsc_one_some (c : N) :
  forall (T : N) (w out : word) (f f' : N),
  sched_tripsc T [Some c] w f out f' ->
  exists tail ft,
    delivery_tripc T w f tail ft /\
    sdec (rung1 c ++ tail) ft = sdec out f'.
Proof.
  intros T w out f f' H.
  cbn [sched_tripsc] in H.
  destruct H as (K & T1 & w1 & f1 & ET & HD & HR).
  cbn [sd_next sched_tripsc] in HR.
  destruct HR as (-> & E). rewrite N.add_0_r in ET. subst T.
  exists w1, f1. split; [exact HD|exact E].
Qed.
Lemma sched_tripsc_sdec_right (rs : list (option N)) :
  forall (T : N) (w out out2 : word) (f f' f2 : N),
  sdec out f' = sdec out2 f2 ->
  sched_tripsc T rs w f out f' ->
  sched_tripsc T rs w f out2 f2.
Proof.
  induction rs as [|o r IH]; intros T w out out2 f f' f2 E H.
  - destruct H as (-> & E1). split; [reflexivity|]. rewrite E1. exact E.
  - destruct H as (K & T1 & w1 & f1 & ET & HD & HR).
    exists K, T1, w1, f1. split; [exact ET|]. split; [exact HD|].
    exact (IH T1 (sd_next o w1) out out2 f1 f' f2 E HR).
Qed.
Lemma one_runway_interleavedc :
  forall p b c prs pre oc avail outer post child f f' (T : N),
  (p < 28)%N ->
  (FLOOR <= b)%N ->
  (FLOOR + 3 <= c)%N ->
  delivery_cols avail = true ->
  prs = pre ++ [oc] ->
  length pre = N.to_nat (27-p) ->
  (2 <= length (schedule_stock pre ++ avail))%nat ->
  schedule_stock prs ++ avail =
    outer ++ rung1 c ->
  sched_tripsc T (bulk_schedule p 0 [] b)
    post f child f' ->
  sched_tripsc
    (dtransit1 p b (wcolcost avail) + stockcost prs + T)%N
    prs
    (avail ++ phase_form p ++
       (4,2,b + DBu p)%N :: post) f
    (outer ++ phase_form 0 ++ (4,2,c)%N :: child) f'.
Proof.
  intros p b c prs pre oc avail outer post child f f' T
    Hp Hb Hc HAvailCols HPrs HPreLen HReady HStock HChild.
  subst prs.
  assert (EBulk : bulk_schedule p 0 [] b =
      repeat None (schedule_slot_nat p) ++ [Some (b-1)%N]).
  { rewrite bulk_schedule_nil.
    cbn [marks N.to_nat repeat]. rewrite app_nil_r.
    reflexivity. }
  rewrite EBulk in HChild.
  destruct (sched_tripsc_app_inv
    (repeat None (schedule_slot_nat p)) [Some (b-1)%N]
    T post child f f' HChild)
    as (mid & fm & TB & TL & ET & HChildPre & HChildLast).
  pose proof (sched_tripsc_nones
    (schedule_slot_nat p) TB post mid f fm HChildPre)
    as HDownPre.
  rewrite (schedule_slot_prefix_count p Hp) in HDownPre.
  pose proof (ticks_to_jumpc p b TB post mid f fm Hp Hb HDownPre)
    as HTargetPre.
  pose proof (deliv_cols _ _ avail _ _ _ _
    HAvailCols HTargetPre) as HTargetPreCols.
  pose proof (deliv_to_sched_tripsc pre (N.to_nat (27-p))
    (dladder p b (N.to_nat (27-p)) + TB
     + N.of_nat (N.to_nat (27-p)) * wcolcost avail)%N
    (avail ++ phase_form p ++
       (4,2,b + DBu p)%N :: post)
    (avail ++ phase_form 27 ++ (4,2,b)%N :: mid) f fm
    HPreLen HTargetPreCols) as HParentPre.
  assert (HFactor : exists outer0,
      schedule_stock pre ++ avail =
        outer0 ++ rung1 c /\
      outer = schedule_release oc outer0).
  { destruct oc as [d|].
    - rewrite schedule_stock_snoc in HStock.
      replace
        ((rung1 d ++ schedule_stock pre)
           ++ avail)
        with
        (rung1 d ++
           (schedule_stock pre ++ avail))
        in HStock by apply app_assoc.
      destruct (app_suffix_factor bg
        (rung1 d)
        (schedule_stock pre ++ avail) outer
        (rung1 c) HStock)
        as (outer0 & EOuter & EAvail).
      { cbn [rung1 length]. lia. }
      exists outer0. split; [exact EAvail|].
      cbn [schedule_release]. exact EOuter.
    - rewrite schedule_stock_snoc in HStock.
      exists outer. split; [exact HStock|reflexivity]. }
  destruct HFactor as (outer0 & EAvail & EOuter).
  assert (HOuterCols : delivery_cols outer0 = true).
  { assert (HAll : delivery_cols
        (schedule_stock pre ++ avail) = true).
    { rewrite delivery_cols_app,
        schedule_stock_cols, HAvailCols. reflexivity. }
    rewrite EAvail, delivery_cols_app in HAll.
    apply andb_prop in HAll as [HOut _]. exact HOut. }
  assert (HParentPre' : sched_tripsc
      (dladder p b (N.to_nat (27-p)) + TB
       + N.of_nat (N.to_nat (27-p)) * wcolcost avail
       + stockcost pre)%N pre
      (avail ++ phase_form p ++
         (4,2,b + DBu p)%N :: post) f
      (outer0 ++ rung1 c ++
         phase_form 27 ++ (4,2,b)%N :: mid) fm).
  { replace
      (outer0 ++ rung1 c ++
        phase_form 27 ++ (4,2,b)%N :: mid)
      with
      (schedule_stock pre ++
        (avail ++ phase_form 27 ++ (4,2,b)%N :: mid)).
    - exact HParentPre.
    - rewrite (app_assoc (schedule_stock pre) avail
        (phase_form 27 ++ (4,2,b)%N :: mid)).
      rewrite EAvail.
      rewrite <- (app_assoc outer0 (rung1 c)
        (phase_form 27 ++ (4,2,b)%N :: mid)).
      reflexivity. }
  destruct (sched_tripsc_one_some (b-1)%N TL mid child fm f' HChildLast)
    as (tail & ft & HDownLast & EChild).
  assert (HEmitLast : deliv
      (N.to_nat (marks 28 - marks 27)) TL
      mid fm tail ft).
  { change (N.to_nat (marks 28 - marks 27))
      with 1%nat. exact (deliv_one _ _ _ _ _ HDownLast). }
  pose proof (transit_delivery_posc outer0 c 27 b TL mid tail fm ft
    HOuterCols ltac:(lia) ltac:(unfold FLOOR in Hc; lia) Hb
    HEmitLast) as HTransit.
  change (DBu 27) with 0%N in HTransit.
  replace (b+0)%N with b in HTransit by lia.
  change (N.to_nat (27-27)) with 0%nat in HTransit.
  cbn [dladder] in HTransit.
  change (N.to_nat (28-27)) with 1%nat in HTransit.
  pose proof (deliv_one_inv _ _ _ _ _ HTransit) as HTargetLast.
  set (K1 := (0 + (28-27) * wcolcost
                (outer0 ++ rung1 c) + 14*b + 22 + TL)%N)
    in HTargetLast.
  pose proof (sched_tripsc_one oc K1 _ _ fm ft HTargetLast)
    as HParentLast0.
  assert (HParentLast : sched_tripsc K1 [oc]
      (outer0 ++ rung1 c ++
         phase_form 27 ++ (4,2,b)%N :: mid) fm
      (outer ++ phase_form 0 ++ (4,2,c)%N :: child) f').
  { eapply sched_tripsc_sdec_right; [|exact HParentLast0].
    destruct oc as [d|]; cbn [schedule_release] in *.
    - set (finpre := rung1 d ++ outer0 ++
        phase_form 0 ++ [(4,2,c)%N]).
      assert (EL : rung1 d ++
          (outer0 ++ phase_form 0 ++ (4,2,c)%N ::
             rung1 (b-1)%N ++ tail) =
          finpre ++ (rung1 (b-1)%N ++ tail)).
      { unfold finpre. repeat rewrite <- app_assoc. reflexivity. }
      assert (ER : outer ++ phase_form 0 ++
          (4,2,c)%N :: child = finpre ++ child).
      { rewrite EOuter. unfold finpre.
        repeat rewrite <- app_assoc. reflexivity. }
      rewrite EL, ER.
      exact (sdec_prefix_eq _ _ _ _ _ EChild).
    - set (finpre := outer0 ++ phase_form 0 ++ [(4,2,c)%N]).
      assert (EL : outer0 ++ phase_form 0 ++ (4,2,c)%N ::
          rung1 (b-1)%N ++ tail =
          finpre ++ (rung1 (b-1)%N ++ tail)).
      { unfold finpre. repeat rewrite <- app_assoc. reflexivity. }
      assert (ER : outer ++ phase_form 0 ++
          (4,2,c)%N :: child = finpre ++ child).
      { rewrite EOuter. unfold finpre.
        repeat rewrite <- app_assoc. reflexivity. }
      rewrite EL, ER.
      exact (sdec_prefix_eq _ _ _ _ _ EChild). }
  pose proof (sched_tripsc_app pre [oc] _ K1 _ _ _ _ _ _
    HParentPre' HParentLast) as HAll.
  assert (EW : wcolcost (outer0 ++ rung1 c)
             = (stockmass pre + wcolcost avail)%N).
  { rewrite <- EAvail, CascadeC_wcolcost_app, stockmass_stock. lia. }
  assert (ES : stockcost (pre ++ [oc]) = (stockcost pre + stockmass pre)%N).
  { rewrite stockcost_app, stockcost_one. cbn [length]. lia. }
  unfold K1 in HAll.
  rewrite EW in HAll.
  unfold dtransit1.
  rewrite ES.
  rewrite N2Nat.id in HAll.
  replace (dladder p b (N.to_nat (27-p))
           + (28-p) * wcolcost avail + 14*b + 22
           + (stockcost pre + stockmass pre) + T)%N
    with ((dladder p b (N.to_nat (27-p)) + TB
           + (27-p) * wcolcost avail + stockcost pre)
          + (0 + (28-27) * (stockmass pre + wcolcost avail)
             + 14*b + 22 + TL))%N.
  2: { subst T. change (28-27)%N with 1%N.
       replace (28-p)%N with ((27-p)+1)%N by lia. lia. }
  exact HAll.
Qed.
Lemma partial_interleavedc :
  forall p t b prs avail post child f f' (T : N),
  (p + t < 28)%N -> (FLOOR <= b)%N ->
  delivery_cols avail = true ->
  length prs = N.to_nat t ->
  sched_tripsc T (partial_schedule p t)
    post f child f' ->
  sched_tripsc
    (dladder p b (N.to_nat t) + t * wcolcost avail
     + stockcost prs + T)%N prs
    (avail ++ phase_form p ++
       (4,2,b + DBu p)%N :: post) f
    (schedule_stock prs ++ avail ++
       phase_form (p+t) ++
       (4,2,b + DBu (p+t))%N :: child) f'.
Proof.
  intros p t b prs avail post child f f' T Hpt Hb HAvail HLen HChild.
  unfold partial_schedule in HChild.
  pose proof (sched_tripsc_nones
    (N.to_nat (marks (p+t) - marks p)) T
    post child f f' HChild) as HDown.
  assert (HDown' : deliv
      (N.to_nat
        (marks (p + N.of_nat (N.to_nat t)) -
         marks p)) T post f child f').
  { rewrite N2Nat.id. exact HDown. }
  pose proof (phase_ticks_delivc
    (N.to_nat t) p b T post child f f'
    ltac:(rewrite N2Nat.id; exact Hpt) Hb HDown') as HPhase.
  rewrite N2Nat.id in HPhase.
  pose proof (deliv_cols _ _ avail _ _ _ _ HAvail HPhase)
    as HPhaseCols.
  pose proof (deliv_to_sched_tripsc prs (N.to_nat t)
    (dladder p b (N.to_nat t) + T
     + N.of_nat (N.to_nat t) * wcolcost avail)%N
    (avail ++ phase_form p ++
       (4,2,b + DBu p)%N :: post)
    (avail ++ phase_form (p+t) ++
       (4,2,b + DBu (p+t))%N :: child) f f'
    HLen HPhaseCols) as HParent.
  rewrite N2Nat.id in HParent.
  replace (dladder p b (N.to_nat t)
           + t * wcolcost avail + stockcost prs + T)%N
    with (dladder p b (N.to_nat t) + T
          + t * wcolcost avail + stockcost prs)%N by lia.
  exact HParent.
Qed.
Lemma one_runway_partial_interleavedc :
  forall p rem b c prs avail outer post child f f' (T : N),
  (p < 28)%N -> (rem < 28)%N ->
  (FLOOR <= b)%N -> (FLOOR + 3 <= c)%N ->
  delivery_cols avail = true ->
  length prs = N.to_nat (28 + rem - p) ->
  (2 <= length
    (schedule_stock
       (firstn (N.to_nat (27-p)) prs) ++ avail))%nat ->
  schedule_stock prs ++ avail =
    outer ++ rung1 c ->
  sched_tripsc T (bulk_schedule p rem [] b)
    post f child f' ->
  exists D : N,
    (D + rcredit [c] rem
     = (28 * N.of_nat 1 + rem - p) * wcolcost avail
       + dlocals [c] p rem b + stockcost prs)%N
    /\ sched_tripsc (D + T)%N prs
         (avail ++ phase_form p ++
            (4,2,b + DBu p)%N :: post) f
         (outer ++ phase_form rem ++
            (4,2,c - 3 + DBu rem)%N :: child) f'.
Proof.
  intros p rem b c prs avail outer post child f f' T
    Hp Hr Hb Hc HAvailCols HLen HReady HStock HChild.
  assert (HLenSplit : length prs =
      (N.to_nat (28-p) + N.to_nat rem)%nat).
  { rewrite HLen. rewrite <- N2Nat.inj_add. f_equal. lia. }
  destruct (split_flight_schedule p prs (N.to_nat rem)
    Hp HLenSplit) as (pre & oc & rest & EPrs & HPre & HRestLen).
  assert (EFirstPre : firstn (N.to_nat (27-p)) prs = pre).
  { rewrite EPrs, <- app_assoc, <- HPre.
    apply firstn_len_app. }
  rewrite EFirstPre in HReady.
  assert (HFlightReady :
      (2 <= length (schedule_stock (pre ++ [oc])
                    ++ avail))%nat).
  { rewrite schedule_stock_snoc. destruct oc as [d|].
    - repeat rewrite length_app. rewrite length_app in HReady.
      cbn [rung1 length]. lia.
    - exact HReady. }
  rewrite EPrs, schedule_stock_app in HStock.
  replace
    ((schedule_stock rest ++
      schedule_stock (pre ++ [oc])) ++ avail)
    with
    (schedule_stock rest ++
      (schedule_stock (pre ++ [oc]) ++ avail))
    in HStock by apply app_assoc.
  destruct (app_suffix_factor bg
    (schedule_stock rest)
    (schedule_stock (pre ++ [oc]) ++ avail) outer
    (rung1 c) HStock)
    as (mid & EOuter & EFlightStock).
  { cbn [rung1 length]. lia. }
  assert (HMidCols : delivery_cols mid = true).
  { assert (HAll : delivery_cols
        (schedule_stock (pre ++ [oc]) ++ avail) = true).
    { rewrite delivery_cols_app,
        schedule_stock_cols, HAvailCols. reflexivity. }
    rewrite EFlightStock, delivery_cols_app in HAll.
    apply andb_prop in HAll as [HM _]. exact HM. }
  rewrite bulk_schedule_nil in HChild.
  destruct (sched_tripsc_app_inv
    (repeat None (schedule_slot_nat p) ++ [Some (b-1)%N])
    (repeat None (N.to_nat (marks rem)))
    T post child f f' HChild)
    as (childMid & fm & TF & TR & ETsplit & HChildFlight0 & HChildRest).
  assert (HChildFlight : sched_tripsc TF
      (bulk_schedule p 0 [] b) post f childMid fm).
  { rewrite bulk_schedule_nil.
    cbn [marks N.to_nat repeat]. rewrite app_nil_r.
    exact HChildFlight0. }
  pose proof (one_runway_interleavedc p b c (pre ++ [oc]) pre oc
    avail mid post childMid f fm TF Hp Hb Hc HAvailCols eq_refl HPre
    HReady EFlightStock HChildFlight) as HParentFlight.
  pose proof (sched_tripsc_nones
    (N.to_nat (marks rem)) TR childMid child fm f' HChildRest)
    as HDownRem.
  assert (HDownRem' : deliv
      (N.to_nat
        (marks (0 + N.of_nat (N.to_nat rem)) -
         marks 0)) TR childMid fm child f').
  { rewrite N2Nat.id, N.add_0_l.
    change (marks 0) with 0%N. rewrite N.sub_0_r.
    exact HDownRem. }
  pose proof (phase_ticks_delivc
    (N.to_nat rem) 0 (c-3)%N TR childMid child fm f'
    ltac:(rewrite N2Nat.id; lia)
    ltac:(unfold FLOOR in *; lia) HDownRem') as HPartial.
  rewrite N2Nat.id, N.add_0_l in HPartial.
  change (DBu 0) with 3%N in HPartial.
  replace (c - 3 + 3)%N with c in HPartial by lia.
  pose proof (deliv_cols _ _ mid _ _ _ _ HMidCols HPartial)
    as HPartialCols.
  pose proof (deliv_to_sched_tripsc rest (N.to_nat rem)
    (dladder 0 (c-3) (N.to_nat rem) + TR
     + N.of_nat (N.to_nat rem) * wcolcost mid)%N
    (mid ++ phase_form 0 ++ (4,2,c)%N :: childMid)
    (mid ++ phase_form rem ++
       (4,2,c-3 + DBu rem)%N :: child) fm f'
    HRestLen HPartialCols) as HParentRest.
  rewrite N2Nat.id in HParentRest.
  assert (HParentRest' : sched_tripsc
      (dladder 0 (c-3) (N.to_nat rem) + TR
       + rem * wcolcost mid + stockcost rest)%N rest
      (mid ++ phase_form 0 ++ (4,2,c)%N :: childMid) fm
      (outer ++ phase_form rem ++
        (4,2,c-3 + DBu rem)%N :: child) f').
  { replace
      (outer ++ phase_form rem ++
        (4,2,c-3 + DBu rem)%N :: child)
      with
      (schedule_stock rest ++
        (mid ++ phase_form rem ++
          (4,2,c-3 + DBu rem)%N :: child)).
    - exact HParentRest.
    - rewrite (app_assoc (schedule_stock rest) mid
        (phase_form rem ++
          (4,2,c-3 + DBu rem)%N :: child)).
      rewrite <- EOuter. reflexivity. }
  pose proof (sched_tripsc_app (pre ++ [oc]) rest _ _ _ _ _ _ _ _
    HParentFlight HParentRest') as HAll.
  rewrite <- EPrs in HAll.
  assert (EW : (wcolcost mid + rc c)%N
             = (stockmass (pre ++ [oc]) + wcolcost avail)%N).
  { rewrite <- rc_wcolcost, <- CascadeC_wcolcost_app, <- EFlightStock,
      CascadeC_wcolcost_app, stockmass_stock. lia. }
  assert (ES : stockcost prs
             = (stockcost (pre ++ [oc]) + rem * stockmass (pre ++ [oc])
                + stockcost rest)%N).
  { rewrite EPrs, stockcost_app, HRestLen, N2Nat.id. lia. }
  exists (dtransit1 p b (wcolcost avail)
          + stockcost (pre ++ [oc])
          + (dladder 0 (c-3) (N.to_nat rem)
             + rem * wcolcost mid + stockcost rest))%N.
  split.
  - cbn [rcredit dlocals length].
    unfold dtransit1. rewrite ES.
    assert (E0 : (rc c * (28 * N.of_nat 0 + rem) + 0)%N = (rem * rc c)%N)
      by (cbn [N.of_nat]; lia).
    rewrite E0.
    assert (E1 : (28 * N.of_nat 1 + rem - p)%N = ((28-p) + rem)%N) by lia.
    rewrite E1, N.mul_add_distr_r.
    assert (EW2 : (rem * wcolcost mid + rem * rc c)%N
                = (rem * stockmass (pre ++ [oc])
                   + rem * wcolcost avail)%N).
    { rewrite <- N.mul_add_distr_l, EW, N.mul_add_distr_l. reflexivity. }
    lia.
  - replace (dtransit1 p b (wcolcost avail)
             + stockcost (pre ++ [oc])
             + (dladder 0 (c-3) (N.to_nat rem)
                + rem * wcolcost mid + stockcost rest) + T)%N
      with ((dtransit1 p b (wcolcost avail)
             + stockcost (pre ++ [oc]) + TF)
            + (dladder 0 (c-3) (N.to_nat rem) + TR
               + rem * wcolcost mid + stockcost rest))%N
      by (subst T; lia).
    exact HAll.
Qed.
Theorem runway_interleavedc :
  forall (c : N) (cs : list N) (p rem b slot : N)
         (prs : list (option N)) (avail outer post child : word)
         (f f' T : N),
  Forall (fun x => (FLOOR + 3 <= x)%N) (c :: cs) ->
  (p < 28)%N -> (rem < 28)%N ->
  (FLOOR <= b)%N ->
  (slot <= 3)%N ->
  delivery_cols avail = true ->
  length prs = N.to_nat
    (28 * N.of_nat (length (c :: cs)) + rem - p) ->
  schedule_shape slot prs ->
  (2 <= length
    (schedule_stock
       (firstn (N.to_nat (27-p)) prs) ++ avail))%nat ->
  schedule_stock prs ++ avail =
    outer ++ runway (c :: cs) ->
  sched_tripsc T (bulk_schedule p rem cs b)
    post f child f' ->
  exists D : N,
    (D + rcredit (rev (c :: cs)) rem
     = (28 * N.of_nat (length (c :: cs)) + rem - p)
         * wcolcost avail
       + dlocals (rev (c :: cs)) p rem b + stockcost prs)%N
    /\ sched_tripsc (D + T)%N prs
         (avail ++ phase_form p ++
            (4,2,b + DBu p)%N :: post) f
         (outer ++ phase_form rem ++
            (4,2,c - 3 + DBu rem)%N :: child) f'.
Proof.
  intros c cs. revert c.
  induction cs as [|d cs IH] using rev_ind;
    intros c p rem b slot prs avail outer post child f f' T
      HLevels Hp Hr Hb HSlot HAvailCols HLen HShape HReady HStock HChild.
  - change (length [c]) with 1%nat in HLen |- *.
    change (runway [c]) with
      (rung1 c) in HStock.
    replace (28 * N.of_nat 1 + rem - p)%N with (28 + rem - p)%N
      in HLen by lia.
    change (rev [c]) with [c].
    exact (one_runway_partial_interleavedc
      p rem b c prs avail outer post child f f' T
      Hp Hr Hb ltac:(inversion HLevels; assumption)
      HAvailCols HLen HReady HStock HChild).
  - assert (ELevels : c :: cs ++ [d] = (c :: cs) ++ [d])
      by reflexivity.
    rewrite ELevels in HLevels.
    apply Forall_app in HLevels. destruct HLevels as [HOuterLevels HLast].
    inversion HLast as [|d0 nil0 Hd HNil]; subst d0 nil0.
    assert (Hd4 : (4 <= d)%N)
      by (unfold FLOOR in Hd; lia).
    assert (HLenSplit : length prs =
      (N.to_nat (28-p) +
       N.to_nat (28 * N.of_nat (length (c :: cs)) + rem))%nat).
    { rewrite HLen. rewrite <- N2Nat.inj_add. f_equal.
      rewrite ELevels, length_app. cbn [length].
      rewrite Nat2N.inj_succ. lia. }
    destruct (split_flight_schedule p prs
      (N.to_nat (28 * N.of_nat (length (c :: cs)) + rem))
      Hp HLenSplit)
      as (pre & oc & rest & EPrs & HPre & HRestLen).
    assert (EFirstPre : firstn (N.to_nat (27-p)) prs = pre).
    { rewrite EPrs, <- app_assoc, <- HPre.
      apply firstn_len_app. }
    rewrite EFirstPre in HReady.
    assert (HFlightReady :
        (2 <= length (schedule_stock (pre ++ [oc])
                      ++ avail))%nat).
    { rewrite schedule_stock_snoc. destruct oc as [grant|].
      - repeat rewrite length_app. rewrite length_app in HReady.
        cbn [rung1 length]. lia.
      - exact HReady. }
    assert (ERest : rest = skipn (N.to_nat (28-p)) prs).
    { rewrite EPrs.
      replace (N.to_nat (28-p)) with (length (pre ++ [oc])).
      - rewrite LineageCascade_skipn_len_app. reflexivity.
      - rewrite length_app, HPre. cbn [length].
        rewrite !N2Nat.inj_sub by lia.
        change (N.to_nat 28) with 28%nat.
        change (N.to_nat 27) with 27%nat. lia. }
    assert (HRestSlot :
      (lin_sched_slot_advance slot (N.of_nat (N.to_nat (28-p)))
       <= 3)%N).
    { unfold lin_sched_slot_advance.
      assert (HM : ((3 - slot + N.of_nat (N.to_nat (28-p))) mod 4
                    < 4)%N) by (apply N.mod_lt; lia).
      lia. }
    assert (HRestShape : schedule_shape
      (lin_sched_slot_advance slot (N.of_nat (N.to_nat (28-p))))
      rest).
    { rewrite ERest.
      exact (schedule_shape_skipn (N.to_nat (28-p)) prs
        slot HSlot HShape). }
    rewrite EPrs, schedule_stock_app in HStock.
    replace
      ((schedule_stock rest ++
        schedule_stock (pre ++ [oc])) ++ avail)
      with
      (schedule_stock rest ++
        (schedule_stock (pre ++ [oc]) ++ avail))
      in HStock by apply app_assoc.
    rewrite ELevels, runway_app in HStock.
    cbn [runway app] in HStock.
    rewrite app_nil_r in HStock.
    assert (HStock' :
      schedule_stock rest ++
        (schedule_stock (pre ++ [oc]) ++ avail) =
      (outer ++ runway (c :: cs)) ++
        rung1 d).
    { rewrite HStock. apply app_assoc. }
    destruct (app_suffix_factor bg
      (schedule_stock rest)
      (schedule_stock (pre ++ [oc]) ++ avail)
      (outer ++ runway (c :: cs))
      (rung1 d) HStock')
      as (mid & EOuter & EFlightStock).
    { cbn [rung1 length]. lia. }
    assert (HMidCols : delivery_cols mid = true).
    { assert (HAll : delivery_cols
          (schedule_stock (pre ++ [oc]) ++ avail) = true).
      { rewrite delivery_cols_app,
          schedule_stock_cols, HAvailCols. reflexivity. }
      rewrite EFlightStock, delivery_cols_app in HAll.
      apply andb_prop in HAll as [HM _]. exact HM. }
    rewrite (bulk_schedule_snoc p rem cs b d Hd4) in HChild.
    destruct (sched_tripsc_app_inv
      (repeat None (schedule_slot_nat p) ++ [Some (b-1)%N])
      (bulk_schedule 0 rem cs (d-3)%N)
      T post child f f' HChild)
      as (childMid & fm & TF & TR & ETsplit & HChildFlight0 & HChildRest).
    assert (HChildFlight : sched_tripsc TF
        (bulk_schedule p 0 [] b) post f childMid fm).
    { rewrite bulk_schedule_nil.
      cbn [marks N.to_nat repeat]. rewrite app_nil_r.
      exact HChildFlight0. }
    pose proof (one_runway_interleavedc p b d (pre ++ [oc]) pre oc
      avail mid post childMid f fm TF Hp Hb Hd HAvailCols eq_refl HPre
      HReady EFlightStock HChildFlight) as HParentFlight.
    assert (HRest27 : (27 <= length rest)%nat).
    { rewrite HRestLen, N2Nat.inj_add, N2Nat.inj_mul, Nat2N.id.
      change (N.to_nat 28) with 28%nat. cbn [length]. lia. }
    pose proof (schedule_stock_firstn_27_ge2 rest
      (lin_sched_slot_advance slot
        (N.of_nat (N.to_nat (28-p))))
      HRestSlot HRestShape HRest27) as HNextStock.
    assert (HNextReady :
      (2 <= length
        (schedule_stock
           (firstn (N.to_nat (27-0)) rest) ++ mid))%nat).
    { change (N.to_nat (27-0)) with 27%nat.
      rewrite length_app. lia. }
    destruct (IH c 0%N rem (d-3)%N
      (lin_sched_slot_advance slot
        (N.of_nat (N.to_nat (28-p))))
      rest mid outer childMid child fm f' TR
      HOuterLevels ltac:(lia) Hr ltac:(unfold FLOOR in *; lia)
      HRestSlot HMidCols ltac:(rewrite N.sub_0_r; exact HRestLen)
      HRestShape HNextReady
      ltac:(symmetry; exact EOuter) HChildRest) as (D2 & ED2 & HParentRest).
    change (DBu 0) with 3%N in HParentRest.
    replace (d - 3 + 3)%N with d in HParentRest by lia.
    rewrite N.sub_0_r in ED2.
    exists (dtransit1 p b (wcolcost avail)
            + stockcost (pre ++ [oc]) + D2)%N.
    assert (EW : (wcolcost mid + rc d)%N
               = (stockmass (pre ++ [oc]) + wcolcost avail)%N).
    { rewrite <- rc_wcolcost, <- CascadeC_wcolcost_app, <- EFlightStock,
        CascadeC_wcolcost_app, stockmass_stock. lia. }
    assert (ELenR : N.of_nat (length rest)
                  = (28 * N.of_nat (length (c :: cs)) + rem)%N)
      by (rewrite HRestLen, N2Nat.id; reflexivity).
    assert (ES : stockcost prs
               = (stockcost (pre ++ [oc])
                  + (28 * N.of_nat (length (c :: cs)) + rem)
                    * stockmass (pre ++ [oc])
                  + stockcost rest)%N).
    { rewrite EPrs, stockcost_app, ELenR. lia. }
    assert (ERev : rev (c :: cs ++ [d]) = d :: rev (c :: cs)).
    { rewrite ELevels, rev_app_distr. reflexivity. }
    assert (HRevNe : rev (c :: cs) <> []) by apply rev_cons_ne.
    assert (ELenRev : N.of_nat (length (rev (c :: cs)))
                    = N.of_nat (length (c :: cs)))
      by (rewrite length_rev; reflexivity).
    split.
    + rewrite ERev, rcredit_cons, ELenRev.
      rewrite (dlocals_cons_ne d (rev (c :: cs)) p rem b HRevNe).
      unfold dtransit1. rewrite ES.
      assert (ELenS : N.of_nat (length (c :: cs ++ [d]))
                    = (1 + N.of_nat (length (c :: cs)))%N).
      { rewrite ELevels, length_app. cbn [length]. lia. }
      rewrite ELenS.
      assert (E1 : (28 * (1 + N.of_nat (length (c :: cs))) + rem - p)%N
                 = ((28 - p)
                    + (28 * N.of_nat (length (c :: cs)) + rem))%N) by lia.
      rewrite E1, N.mul_add_distr_r.
      assert (EW2 :
        ((28 * N.of_nat (length (c :: cs)) + rem) * wcolcost mid
         + rc d * (28 * N.of_nat (length (c :: cs)) + rem))%N
      = ((28 * N.of_nat (length (c :: cs)) + rem) * stockmass (pre ++ [oc])
         + (28 * N.of_nat (length (c :: cs)) + rem)
           * wcolcost avail)%N).
      { replace (rc d * (28 * N.of_nat (length (c :: cs)) + rem))%N
          with ((28 * N.of_nat (length (c :: cs)) + rem) * rc d)%N by lia.
        rewrite <- N.mul_add_distr_l, EW, N.mul_add_distr_l. reflexivity. }
      lia.
    + rewrite EPrs.
      replace (dtransit1 p b (wcolcost avail)
               + stockcost (pre ++ [oc]) + D2 + T)%N
        with ((dtransit1 p b (wcolcost avail)
               + stockcost (pre ++ [oc]) + TF) + (D2 + TR))%N
        by (subst T; lia).
      exact (sched_tripsc_app (pre ++ [oc]) rest _ _ _ _ _ _ _ _
               HParentFlight HParentRest).
Qed.
Fixpoint stockvals (rs : list (option N)) : list N :=
  match rs with
  | [] => []
  | None :: r => stockvals r
  | Some c :: r => stockvals r ++ [c]
  end.
Lemma stockvals_stock (rs : list (option N)) :
  schedule_stock rs
  = runway (stockvals rs).
Proof.
  induction rs as [|[c|] r IH];
    cbn [schedule_stock stockvals].
  - reflexivity.
  - rewrite IH, runway_app.
    cbn [runway app]. rewrite app_nil_r. reflexivity.
  - exact IH.
Qed.
Lemma stockvals_count (rs : list (option N)) :
  length (stockvals rs) = schedule_count rs.
Proof.
  induction rs as [|[c|] r IH];
    cbn [stockvals schedule_count].
  - reflexivity.
  - rewrite length_app, IH. cbn [length]. lia.
  - exact IH.
Qed.
Lemma stockmass_vals (rs : list (option N)) :
  stockmass rs = wcolsum (stockvals rs).
Proof.
  rewrite stockmass_stock, stockvals_stock, wcolcost_runway.
  reflexivity.
Qed.
Fixpoint lmom (l : list N) (a : N) : N :=
  match l with
  | [] => 0
  | x :: t => (rc x * a + lmom t (a + 4))%N
  end.
Lemma lmom_snoc (l : list N) : forall (c a : N),
  lmom (l ++ [c]) a
  = (lmom l a + rc c * (a + 4 * N.of_nat (length l)))%N.
Proof.
  induction l as [|x t IH]; intros c a; cbn [app lmom length].
  - cbn [N.of_nat]. lia.
  - rewrite (IH c (a+4)%N), Nat2N.inj_succ. lia.
Qed.
Lemma lmom_head_arith (r n : N) :
  (r * n)%N = (r * (n mod 4 + 4 * (n / 4)))%N.
Proof. f_equal. pose proof (N.div_mod' n 4) as HD. lia. Qed.
Lemma stockcost_lmom (rs : list (option N)) : forall slot,
  (slot <= 3)%N -> schedule_shape slot rs ->
  stockcost rs
  = lmom (stockvals rs) ((N.of_nat (length rs) + 3 - slot) mod 4).
Proof.
  induction rs as [|oc rs IH]; intros slot Hslot Hshape.
  - cbn [stockcost stockvals lmom]. reflexivity.
  - destruct (N.eq_dec slot 0) as [->|Hnz].
    + destruct (schedule_shape_cons_zero oc rs Hshape)
        as (c & -> & Hrest).
      cbn [stockcost stockvals length].
      rewrite (IH 3%N ltac:(lia) Hrest).
      rewrite lmom_snoc, stockvals_count.
      pose proof (schedule_shape_count rs 3%N
        ltac:(lia) Hrest) as HC.
      unfold lin_sched_grants in HC.
      assert (E3 : (N.of_nat (length rs) + (3-3))%N = N.of_nat (length rs))
        by lia.
      rewrite E3 in HC.
      assert (E4 : (N.of_nat (length rs) + 3 - 3)%N = N.of_nat (length rs))
        by lia.
      rewrite E4.
      assert (EM : ((N.of_nat (S (length rs)) + 3 - 0) mod 4)%N
                 = (N.of_nat (length rs) mod 4)%N).
      { rewrite Nat2N.inj_succ.
        replace (N.succ (N.of_nat (length rs)) + 3 - 0)%N
          with (N.of_nat (length rs) + 1*4)%N by lia.
        apply N.Div0.mod_add. }
      rewrite EM, HC.
      rewrite (lmom_head_arith (rc c) (N.of_nat (length rs))).
      lia.
    + destruct (schedule_shape_cons_pos slot oc rs
        Hnz Hshape) as (-> & Hrest).
      cbn [stockcost stockvals length].
      rewrite (IH (slot-1)%N ltac:(lia) Hrest).
      f_equal. rewrite Nat2N.inj_succ. f_equal. lia.
Qed.
Fixpoint wrungs (u : word) : list N :=
  match u with
  | _ :: l :: t => gC l :: wrungs t
  | _ => []
  end.
Lemma wrungs_runway (l : list N) : wrungs (runway l) = l.
Proof.
  induction l as [|x t IH]; [reflexivity|].
  cbn [runway rung1 app wrungs gC].
  rewrite IH. reflexivity.
Qed.
Lemma runway_inj (l1 l2 : list N) :
  runway l1 = runway l2 -> l1 = l2.
Proof.
  intros E. rewrite <- (wrungs_runway l1), <- (wrungs_runway l2), E.
  reflexivity.
Qed.
Lemma stockvals_app (a b : list (option N)) :
  stockvals (a ++ b) = (stockvals b ++ stockvals a)%list.
Proof.
  induction a as [|[c|] a IH]; cbn [app stockvals].
  - rewrite app_nil_r. reflexivity.
  - rewrite IH, app_assoc. reflexivity.
  - exact IH.
Qed.
Definition bulk_stockw (sg : list seg) (cols : word)
    (gap : nat) (slot take : N) : word :=
  skipn (gap - 2 * N.to_nat (lin_sched_grants slot take))%nat
        (firstn gap (lin_flat sg cols)).
Definition bulk_surcharge (sg : list seg) (cols : word)
    (gap : nat) (slot take : N) : N :=
  lmom (wrungs (bulk_stockw sg cols gap slot take))
       ((take + 3 - slot) mod 4).
Lemma bulk_surcharge_ok
    (sg : list seg) (cols base avail : word)
    (prs used rest : list (option N)) (gap : nat) (slot take : N) :
  (slot <= 3)%N ->
  schedule_shape slot prs ->
  prs = used ++ rest ->
  length used = N.to_nat take ->
  lin_flat sg cols
    = (base ++ schedule_stock prs) ++ avail ->
  length (base ++ schedule_stock prs) = gap ->
  stockcost used = bulk_surcharge sg cols gap slot take.
Proof.
  intros Hslot HShape EPrs HUsed ECols EGap.
  assert (HUsedShape : schedule_shape slot used).
  { rewrite EPrs in HShape.
    replace used with (firstn (length used) (used ++ rest))
      by apply firstn_len_app.
    exact (schedule_shape_firstn _ _ _ HShape). }
  assert (EStockLen :
      length (schedule_stock used)
      = (2 * N.to_nat (lin_sched_grants slot take))%nat).
  { rewrite schedule_stock_length.
    pose proof (schedule_shape_count used slot
      Hslot HUsedShape) as HC.
    rewrite HUsed, N2Nat.id in HC.
    apply (f_equal N.to_nat) in HC. rewrite Nat2N.id in HC. lia. }
  assert (ESplit :
      (base ++ schedule_stock prs)
      = (base ++ schedule_stock rest)
          ++ schedule_stock used).
  { rewrite EPrs, schedule_stock_app, app_assoc.
    reflexivity. }
  assert (EFirst : firstn gap (lin_flat sg cols)
                 = base ++ schedule_stock prs).
  { rewrite ECols, <- EGap. apply firstn_len_app. }
  assert (EWin : bulk_stockw sg cols gap slot take
               = schedule_stock used).
  { unfold bulk_stockw. rewrite EFirst, ESplit.
    replace (gap - 2 * N.to_nat (lin_sched_grants slot take))%nat
      with (length (base ++ schedule_stock rest)).
    - apply LineageCascade_skipn_len_app.
    - rewrite <- EGap, ESplit, !length_app, EStockLen. lia. }
  unfold bulk_surcharge. rewrite EWin, stockvals_stock, wrungs_runway.
  rewrite (stockcost_lmom used slot Hslot HUsedShape), HUsed, N2Nat.id.
  reflexivity.
Qed.
Lemma app_len_eq (A : Type) (a b c d : list A) :
  a ++ b = c ++ d -> length a = length c -> a = c /\ b = d.
Proof.
  intros E EL.
  destruct (app_prefix_factor A a b c d E ltac:(lia))
    as (mid & -> & ->).
  rewrite length_app in EL.
  destruct mid as [|x m]; [|cbn [length] in EL; lia].
  rewrite app_nil_r. split; reflexivity.
Qed.
Lemma lin_bulk_scheduled_transitionc :
  forall fr sg w f cols s j p take w' sg' nh rem emit sg1 w1 f1
         (PRE0 POST0 : word) (c_0 b0 T D : N) (cs0 : list N),
  sg_wf sg -> lin_ok sg w = true ->
  (forall x, In x sg -> altb (sBody x) = true) ->
  is_spc (nth O w d0) = false ->
  seek (skipn (lsCur fr) w) = (cols, s) ->
  j = (lsCur fr + length cols)%nat ->
  detect_phase w j = Some p ->
  Nat.eqb (N.to_nat ((p+take)/28)) O = false ->
  lin_bulk sg w j p take = Some (w', sg', nh, rem, emit) ->
  sg_wf sg' ->
  (take <= lsTicks fr)%N ->
  lin_sched_bulk_safe fr (lin_flen sg cols) p take = true ->
  (lsCur fr <= nh)%nat ->
  lin_flat sg (firstn (lsCur fr) w)
    ++ lin_flat sg cols
    = PRE0 ++ runway (c_0 :: cs0) ->
  lin_flat sg s
    = phase_form p ++ (4,2,b0 + DBu p)%N :: POST0 ->
  length (c_0 :: cs0) = N.to_nat ((p + take)/28) ->
  (D + rcredit (rev (c_0 :: cs0)) rem
   = take * wcolcost
              (skipn (lsGap fr) (lin_flat sg cols))
     + dlocals (rev (c_0 :: cs0)) p rem b0
     + bulk_surcharge sg cols (lsGap fr) (lsSlot fr)
         take)%N ->
  scheduled_framec T
    (lin_sched_child nh rem emit p take) sg' w' f sg1 w1 f1 ->
  scheduled_transitionc (D + T)%N fr take sg w f sg1 w1 f1.
Proof.
  intros fr sg w f cols s j p take w' sg' nh rem emit sg1 w1 f1
    PRE0 POST0 c_0 b0 T D cs0
    HW HOk HAlt H0 HSeek Hj HD HFull HB HW' HTake HSafe HCur
    HLay1 HLay2 HLayL HCost HChild.
  destruct (detect_phase_form w j p HD) as (Hp & _).
  assert (HFullNat : N.to_nat ((p+take)/28) <> 0%nat)
    by (apply PeanoNat.Nat.eqb_neq; exact HFull).
  assert (HFullN : ((p+take)/28 <> 0)%N).
  { intro E. apply HFullNat. rewrite E. reflexivity. }
  assert (EFullN : (((p+take)/28 =? 0)%N = false))
    by (apply N.eqb_neq; exact HFullN).
  destruct (lin_bulk_cursor_layout
    sg w (lsCur fr) cols s j p take w' sg' nh rem emit
    HW HOk HAlt H0 HSeek Hj HD HFull HB HW')
    as (PRE & POST & c & cs & b & EPre & ESite & EBulk & EMap &
        HnhLen & EChildPre & EChildTail & HLevels & HLevelsSafe & HPOST & Hb &
        HRem & HEmit).
  assert (ERunLen : length (runway (c :: cs))
                  = length (runway (c_0 :: cs0)))
    by (rewrite !length_runway, HLevels, HLayL;
        reflexivity).
  assert (EPreLen : length PRE = length PRE0).
  { apply (f_equal (@length bg)) in EPre.
    assert (E2 := HLay1).
    apply (f_equal (@length bg)) in E2.
    rewrite !length_app in EPre, E2. lia. }
  assert (ELev : c :: cs = c_0 :: cs0).
  { assert (EE : PRE ++ runway (c :: cs)
               = PRE0 ++ runway (c_0 :: cs0))
      by (rewrite <- EPre, <- HLay1; reflexivity).
    destruct (app_len_eq bg PRE _ PRE0 _ EE EPreLen) as (_ & ER).
    exact (runway_inj _ _ ER). }
  assert (EB : b = b0).
  { assert (EE : phase_form p
                   ++ (4,2,b + DBu p)%N :: POST
               = phase_form p
                   ++ (4,2,b0 + DBu p)%N :: POST0)
      by (rewrite <- ESite, <- HLay2; reflexivity).
    apply app_inv_head in EE. injection EE as EB1 _. lia. }
  destruct HChild as (HChildPrefix & HChildFrame).
  assert (HPrefix : forall i, (i <= lsCur fr)%nat ->
      lin_flat sg (firstn i w) =
      lin_flat sg1 (firstn i w1)).
  { intros i Hi. transitivity (lin_flat sg' (firstn i w')).
    - exact (lin_bulk_prefix_before
        sg w (lsCur fr) j p take w' sg' nh rem emit
        HW HOk H0 HD HFull HB HCur i Hi).
    - apply HChildPrefix. cbn [lin_sched_child lsCur]. lia. }
  split; [exact HPrefix|].
  intros prs base tail HView.
  destruct HView as (HSlot & HLen & HShape & HBaseCols & HLayout & HGap).
  pose proof (seek_split (skipn (lsCur fr) w)
    cols s HSeek) as HSeekSplit.
  destruct HSeekSplit as (ESeekWord & HCols).
  assert (EFlatSuffix :
      lin_flat sg (skipn (lsCur fr) w) =
      lin_flat sg cols ++ lin_flat sg s).
  { rewrite ESeekWord. apply lin_flat_app_c. }
  assert (EFrameSite :
      (base ++ schedule_stock prs) ++ tail =
      lin_flat sg cols ++ lin_flat sg s).
  { rewrite <- HLayout. exact EFlatSuffix. }
  assert (HBoundary :
      (lsGap fr <= length (lin_flat sg cols))%nat).
  { unfold lin_sched_bulk_safe in HSafe. cbv zeta in HSafe.
    rewrite EFullN in HSafe. apply andb_prop in HSafe as [HBnd _].
    apply PeanoNat.Nat.leb_le in HBnd.
    rewrite <- (lin_flen_flat_wf sg cols HW). exact HBnd. }
  assert (HBaseLen :
      (length (base ++ schedule_stock prs) <=
       length (lin_flat sg cols))%nat)
    by (rewrite HGap; exact HBoundary).
  destruct (app_prefix_factor bg
    (base ++ schedule_stock prs) tail
    (lin_flat sg cols) (lin_flat sg s)
    EFrameSite HBaseLen) as (avail & ECols & ETail).
  assert (HFlatCols : delivery_cols
      (lin_flat sg cols) = true)
    by (apply lin_flat_delivery_cols; assumption).
  assert (HAvailCols : delivery_cols avail = true).
  { rewrite ECols, !delivery_cols_app,
      HBaseCols, schedule_stock_cols in HFlatCols.
    exact HFlatCols. }
  assert (ETailSite : tail =
      avail ++ phase_form p ++
        (4,2,b + DBu p)%N :: POST).
  { rewrite ETail, ESite. repeat rewrite <- app_assoc. reflexivity. }
  set (used := firstn (N.to_nat take) prs).
  set (rest := skipn (N.to_nat take) prs).
  assert (HTakeNat : (N.to_nat take <= length prs)%nat).
  { rewrite HLen. apply PeanoNat.Nat.compare_le_iff.
    rewrite <- N2Nat.inj_compare. apply N.compare_le_iff. exact HTake. }
  assert (EPrs : prs = used ++ rest).
  { unfold used, rest. symmetry. apply firstn_skipn. }
  assert (HUsedLen : length used = N.to_nat take).
  { unfold used. rewrite length_firstn, PeanoNat.Nat.min_l by exact HTakeNat.
    reflexivity. }
  assert (HUsedShape : schedule_shape (lsSlot fr) used).
  { unfold used. exact (schedule_shape_firstn
      _ _ _ HShape). }
  assert (HColFlat : lin_flen sg cols =
      (lsGap fr + length avail)%nat).
  { rewrite lin_flen_flat_wf by exact HW.
    rewrite ECols, length_app, HGap. reflexivity. }
  pose proof (schedule_bulk_ready
    fr prs p take avail (lin_flen sg cols)
    HSlot HLen HShape Hp HFullN HTake HColFlat HSafe) as HReady.
  fold used in HReady.
  pose proof (schedule_bulk_stock_enough
    fr prs p take avail (lin_flen sg cols)
    HSlot HLen HShape Hp HFullN HTake HColFlat HSafe) as HEnough.
  fold used in HEnough.
  assert (EResource :
      (lin_flat sg (firstn (lsCur fr) w) ++
         base ++ schedule_stock rest) ++
        (schedule_stock used ++ avail) =
      PRE ++ runway (c :: cs)).
  { rewrite ECols, EPrs, schedule_stock_app in EPre.
    rewrite <- EPre. repeat rewrite <- app_assoc. reflexivity. }
  assert (HRunwayLen :
      length (runway (c :: cs)) =
        (2 * N.to_nat ((p+take)/28))%nat).
  { rewrite length_runway, HLevels. reflexivity. }
  destruct (app_suffix_factor bg
    (lin_flat sg (firstn (lsCur fr) w) ++
       base ++ schedule_stock rest)
    (schedule_stock used ++ avail)
    PRE (runway (c :: cs))
    EResource ltac:(rewrite HRunwayLen; exact HEnough))
    as (outer & EPreOuter & EStockOuter).
  assert (HRem28 : (rem < 28)%N).
  { rewrite HRem. apply N.mod_lt. lia. }
  set (crs := bulk_schedule p rem cs b).
  set (cbase := [(4,2,c - 3 + DBu rem)%N]).
  assert (HChildView : schedule_frame_view
      (lin_sched_child nh rem emit p take)
      (lin_flat sg'
        (skipn (nh + phase_len rem)%nat w'))
      crs cbase POST).
  { unfold schedule_frame_view, lin_sched_child.
    cbv beta zeta. cbn [lsSlot lsTicks lsGap].
    repeat split.
    - unfold lin_sched_slot. lia.
    - unfold crs.
      rewrite (bulk_schedule_length p rem cs b Hp HRem28).
      assert (HQ : N.of_nat (S (length cs)) = ((p+take)/28)%N).
      { cbn [length] in HLevels. rewrite HLevels, N2Nat.id. reflexivity. }
      pose proof (N.div_mod' (p+take) 28) as HDiv.
      assert (ESpan :
        (28 * N.of_nat (S (length cs)) + rem = p+take)%N) by lia.
      rewrite ESpan, <- HEmit. reflexivity.
    - unfold crs. exact (bulk_schedule_shape
        p rem cs b Hp HRem28).
    - unfold cbase, delivery_cols.
      unfold is_col, is_cmf.
      cbn [forallb gO gZ gC].
      destruct ((c - 3 + DBu rem =? 1)%N); reflexivity.
    - unfold cbase, crs.
      rewrite bulk_schedule_stock, EChildTail.
      unfold crossed_post.
      rewrite app_nil_r. repeat rewrite <- app_assoc. reflexivity.
    - unfold cbase, crs. rewrite bulk_schedule_stock.
      unfold crossed_post.
      rewrite !length_app, length_runway, map_length.
      cbn [rung1 length].
      change (S (length cs) = N.to_nat ((p+take)/28)) in HLevels.
      lia. }
  destruct (HChildFrame crs cbase POST HChildView)
    as (child & HChildTrips & HChildOut).
  cbn [lin_sched_child lsCur] in HChildOut.
  assert (EChildFull : lin_flat sg1 w1 =
      PRE ++ phase_form rem ++
        (4,2,c - 3 + DBu rem)%N :: child).
  { rewrite (flat_firstn_skipn sg1 w1
      (nh + phase_len rem)%nat).
    rewrite <- (HChildPrefix (nh + phase_len rem)%nat (le_n _)).
    rewrite EChildPre, HChildOut. unfold cbase.
    repeat rewrite <- app_assoc. reflexivity. }
  assert (HTakeSpan : take =
      (28 * N.of_nat (length (c :: cs)) + rem - p)%N).
  { pose proof (N.div_mod' (p+take) 28) as HDiv.
    assert (HQ : N.of_nat (length (c :: cs)) = ((p+take)/28)%N)
      by (rewrite HLevels, N2Nat.id; reflexivity).
    rewrite HQ, HRem. lia. }
  assert (HUsedSpan : length used = N.to_nat
      (28 * N.of_nat (length (c :: cs)) + rem - p)).
  { rewrite HUsedLen, HTakeSpan. reflexivity. }
  unfold crs in HChildTrips.
  destruct (runway_interleavedc
    c cs p rem b (lsSlot fr) used avail outer POST child f f1 T
    HLevelsSafe Hp HRem28 Hb HSlot HAvailCols HUsedSpan HUsedShape
    HReady EStockOuter HChildTrips) as (Dv & EDv & HParentTrips0).
  assert (EAvail : skipn (lsGap fr) (lin_flat sg cols)
                 = avail).
  { rewrite ECols, <- HGap. apply LineageCascade_skipn_len_app. }
  assert (ESurch : stockcost used
                 = bulk_surcharge sg cols (lsGap fr)
                     (lsSlot fr) take).
  { exact (bulk_surcharge_ok sg cols base avail prs used rest
             (lsGap fr) (lsSlot fr) take
             HSlot HShape EPrs HUsedLen ECols HGap). }
  assert (EDD : Dv = D).
  { rewrite <- HTakeSpan in EDv.
    rewrite ESurch, <- EAvail in EDv.
    rewrite ELev, EB in EDv.
    lia. }
  rewrite EDD in HParentTrips0.
  assert (HParentTrips : sched_tripsc (D + T)%N used tail f
      (outer ++ phase_form rem ++
        (4,2,c - 3 + DBu rem)%N :: child) f1).
  { rewrite ETailSite. exact HParentTrips0. }
  set (tail' := outer ++ phase_form rem ++
    (4,2,c - 3 + DBu rem)%N :: child).
  assert (EFinalFull : lin_flat sg1 w1 =
      lin_flat sg (firstn (lsCur fr) w) ++
        (base ++ schedule_stock rest) ++ tail').
  { unfold tail'. rewrite EChildFull, EPreOuter.
    repeat rewrite <- app_assoc. reflexivity. }
  assert (EFinalSuffix :
      lin_flat sg1 (skipn (lsCur fr) w1) =
        (base ++ schedule_stock rest) ++ tail').
  { pose proof (flat_firstn_skipn
      sg1 w1 (lsCur fr)) as EDec.
    rewrite <- (HPrefix (lsCur fr) (le_n _)) in EDec.
    rewrite EFinalFull in EDec. apply app_inv_head in EDec.
    symmetry. exact EDec. }
  exists used, rest, tail'.
  split; [exact EPrs|]. split; [exact HUsedLen|].
  split; [exact HParentTrips|].
  unfold schedule_frame_view, lin_sched_advance.
  cbn [lsSlot lsTicks lsGap].
  repeat split.
  - exact (sched_slot_advance_le3
      (lsSlot fr) take HSlot).
  - unfold rest. exact (schedule_ticks_skip
      (lsTicks fr) take prs HLen HTake).
  - change (schedule_shape
      (lin_sched_slot_advance (lsSlot fr) take) rest).
    unfold rest.
    pose proof (schedule_shape_skipn
      (N.to_nat take) prs (lsSlot fr) HSlot HShape) as HRestShape.
    rewrite N2Nat.id in HRestShape. exact HRestShape.
  - exact HBaseCols.
  - exact EFinalSuffix.
  - unfold rest.
    pose proof (schedule_stock_skip_length
      (N.to_nat take) prs (lsSlot fr)
      HTakeNat HSlot HShape) as HRestStock.
    rewrite N2Nat.id in HRestStock.
    pose proof (schedule_stock_first_skip
      (N.to_nat take) prs) as EStockSplit.
    apply (f_equal (@length bg)) in EStockSplit.
    rewrite length_app in EStockSplit.
    fold used rest in EStockSplit.
    pose proof (schedule_stock_firstn_length
      (N.to_nat take) prs (lsSlot fr)
      HTakeNat HSlot HShape) as HUsedStock.
    fold used in HUsedStock. rewrite N2Nat.id in HUsedStock.
    rewrite length_app, HRestStock. rewrite length_app in HGap. lia.
Qed.
Lemma lin_bulk_scheduled_transition_netc :
  forall fr sg w f cols s j p take w' sg' nh rem emit sg1 w1 f1
         (PRE0 POST0 : word) (c_0 b0 T : N) (cs0 : list N),
  sg_wf sg -> lin_ok sg w = true ->
  (forall x, In x sg -> altb (sBody x) = true) ->
  is_spc (nth O w d0) = false ->
  seek (skipn (lsCur fr) w) = (cols, s) ->
  j = (lsCur fr + length cols)%nat ->
  detect_phase w j = Some p ->
  Nat.eqb (N.to_nat ((p+take)/28)) O = false ->
  lin_bulk sg w j p take = Some (w', sg', nh, rem, emit) ->
  sg_wf sg' ->
  (take <= lsTicks fr)%N ->
  lin_sched_bulk_safe fr (lin_flen sg cols) p take = true ->
  (lsCur fr <= nh)%nat ->
  lin_flat sg (firstn (lsCur fr) w)
    ++ lin_flat sg cols
    = PRE0 ++ runway (c_0 :: cs0) ->
  lin_flat sg s
    = phase_form p ++ (4,2,b0 + DBu p)%N :: POST0 ->
  length (c_0 :: cs0) = N.to_nat ((p + take)/28) ->
  scheduled_framec T
    (lin_sched_child nh rem emit p take) sg' w' f sg1 w1 f1 ->
  scheduled_transitionc
    (((take * wcolcost
          (skipn (lsGap fr) (lin_flat sg cols))
       + dlocals (rev (c_0 :: cs0)) p rem b0
       + bulk_surcharge sg cols (lsGap fr)
           (lsSlot fr) take)
      - rcredit (rev (c_0 :: cs0)) rem) + T)%N
    fr take sg w f sg1 w1 f1.
Proof.
  intros fr sg w f cols s j p take w' sg' nh rem emit sg1 w1 f1
    PRE0 POST0 c_0 b0 T cs0
    HW HOk HAlt H0 HSeek Hj HD HFull HB HW' HTake HSafe HCur
    HLay1 HLay2 HLayL HChild0.
  set (Gross :=
    (take * wcolcost
       (skipn (lsGap fr) (lin_flat sg cols))
     + dlocals (rev (c_0 :: cs0)) p rem b0
     + bulk_surcharge sg cols (lsGap fr)
         (lsSlot fr) take)%N).
  set (Credit := rcredit (rev (c_0 :: cs0)) rem).
  set (D := (Gross - Credit)%N).
  change (scheduled_transitionc (D + T)%N
            fr take sg w f sg1 w1 f1).
  destruct (detect_phase_form w j p HD) as (Hp & _).
  assert (HFullNat : N.to_nat ((p+take)/28) <> 0%nat)
    by (apply PeanoNat.Nat.eqb_neq; exact HFull).
  assert (HFullN : ((p+take)/28 <> 0)%N).
  { intro E. apply HFullNat. rewrite E. reflexivity. }
  assert (EFullN : (((p+take)/28 =? 0)%N = false))
    by (apply N.eqb_neq; exact HFullN).
  destruct (lin_bulk_cursor_layout
    sg w (lsCur fr) cols s j p take w' sg' nh rem emit
    HW HOk HAlt H0 HSeek Hj HD HFull HB HW')
    as (PRE & POST & c & cs & b & EPre & ESite & EBulk & EMap &
        HnhLen & EChildPre & EChildTail & HLevels & HLevelsSafe & HPOST & Hb &
        HRem & HEmit).
  assert (ERunLen : length (runway (c :: cs))
                  = length (runway (c_0 :: cs0)))
    by (rewrite !length_runway, HLevels, HLayL;
        reflexivity).
  assert (EPreLen : length PRE = length PRE0).
  { apply (f_equal (@length bg)) in EPre.
    assert (E2 := HLay1). apply (f_equal (@length bg)) in E2.
    rewrite !length_app in EPre, E2. lia. }
  assert (ELev : c :: cs = c_0 :: cs0).
  { assert (EE : PRE ++ runway (c :: cs)
               = PRE0 ++ runway (c_0 :: cs0))
      by (rewrite <- EPre, <- HLay1; reflexivity).
    destruct (app_len_eq bg PRE _ PRE0 _ EE EPreLen) as (_ & ER).
    exact (runway_inj _ _ ER). }
  assert (EB : b = b0).
  { assert (EE : phase_form p
                   ++ (4,2,b + DBu p)%N :: POST
               = phase_form p
                   ++ (4,2,b0 + DBu p)%N :: POST0)
      by (rewrite <- ESite, <- HLay2; reflexivity).
    apply app_inv_head in EE. injection EE as EB1 _. lia. }
  destruct HChild0 as (HChildPrefix & HChildFrame).
  assert (HPrefix : forall i, (i <= lsCur fr)%nat ->
      lin_flat sg (firstn i w) =
      lin_flat sg1 (firstn i w1)).
  { intros i Hi. transitivity (lin_flat sg' (firstn i w')).
    - exact (lin_bulk_prefix_before
        sg w (lsCur fr) j p take w' sg' nh rem emit
        HW HOk H0 HD HFull HB HCur i Hi).
    - apply HChildPrefix. cbn [lin_sched_child lsCur]. lia. }
  split; [exact HPrefix|].
  intros prs base tail HView0.
  pose proof HView0 as HView.
  destruct HView as (HSlot & HLen & HShape & HBaseCols & HLayout & HGap).
  pose proof (seek_split (skipn (lsCur fr) w)
    cols s HSeek) as HSeekSplit.
  destruct HSeekSplit as (ESeekWord & HCols).
  assert (EFlatSuffix :
      lin_flat sg (skipn (lsCur fr) w) =
      lin_flat sg cols ++ lin_flat sg s).
  { rewrite ESeekWord. apply lin_flat_app_c. }
  assert (EFrameSite :
      (base ++ schedule_stock prs) ++ tail =
      lin_flat sg cols ++ lin_flat sg s).
  { rewrite <- HLayout. exact EFlatSuffix. }
  assert (HBoundary :
      (lsGap fr <= length (lin_flat sg cols))%nat).
  { unfold lin_sched_bulk_safe in HSafe. cbv zeta in HSafe.
    rewrite EFullN in HSafe. apply andb_prop in HSafe as [HBnd _].
    apply PeanoNat.Nat.leb_le in HBnd.
    rewrite <- (lin_flen_flat_wf sg cols HW). exact HBnd. }
  assert (HBaseLen :
      (length (base ++ schedule_stock prs) <=
       length (lin_flat sg cols))%nat)
    by (rewrite HGap; exact HBoundary).
  destruct (app_prefix_factor bg
    (base ++ schedule_stock prs) tail
    (lin_flat sg cols) (lin_flat sg s)
    EFrameSite HBaseLen) as (avail & ECols & ETail).
  assert (HFlatCols : delivery_cols
      (lin_flat sg cols) = true)
    by (apply lin_flat_delivery_cols; assumption).
  assert (HAvailCols : delivery_cols avail = true).
  { rewrite ECols, !delivery_cols_app,
      HBaseCols, schedule_stock_cols in HFlatCols.
    exact HFlatCols. }
  set (used := firstn (N.to_nat take) prs).
  set (rest := skipn (N.to_nat take) prs).
  assert (HTakeNat : (N.to_nat take <= length prs)%nat).
  { rewrite HLen. apply PeanoNat.Nat.compare_le_iff.
    rewrite <- N2Nat.inj_compare. apply N.compare_le_iff. exact HTake. }
  assert (EPrs : prs = used ++ rest).
  { unfold used, rest. symmetry. apply firstn_skipn. }
  assert (HUsedLen : length used = N.to_nat take).
  { unfold used. rewrite length_firstn, PeanoNat.Nat.min_l by exact HTakeNat.
    reflexivity. }
  assert (HUsedShape : schedule_shape (lsSlot fr) used).
  { unfold used. exact (schedule_shape_firstn _ _ _ HShape). }
  assert (HColFlat : lin_flen sg cols =
      (lsGap fr + length avail)%nat).
  { rewrite lin_flen_flat_wf by exact HW.
    rewrite ECols, length_app, HGap. reflexivity. }
  pose proof (schedule_bulk_ready
    fr prs p take avail (lin_flen sg cols)
    HSlot HLen HShape Hp HFullN HTake HColFlat HSafe) as HReady.
  fold used in HReady.
  pose proof (schedule_bulk_stock_enough
    fr prs p take avail (lin_flen sg cols)
    HSlot HLen HShape Hp HFullN HTake HColFlat HSafe) as HEnough.
  fold used in HEnough.
  assert (EResource :
      (lin_flat sg (firstn (lsCur fr) w) ++
         base ++ schedule_stock rest) ++
        (schedule_stock used ++ avail) =
      PRE ++ runway (c :: cs)).
  { rewrite ECols, EPrs, schedule_stock_app in EPre.
    rewrite <- EPre. repeat rewrite <- app_assoc. reflexivity. }
  assert (HRunwayLen :
      length (runway (c :: cs)) =
        (2 * N.to_nat ((p+take)/28))%nat).
  { rewrite length_runway, HLevels. reflexivity. }
  destruct (app_suffix_factor bg
    (lin_flat sg (firstn (lsCur fr) w) ++
       base ++ schedule_stock rest)
    (schedule_stock used ++ avail)
    PRE (runway (c :: cs))
    EResource ltac:(rewrite HRunwayLen; exact HEnough))
    as (outer & EPreOuter & EStockOuter).
  assert (HRem28 : (rem < 28)%N).
  { rewrite HRem. apply N.mod_lt. lia. }
  set (crs := bulk_schedule p rem cs b).
  set (cbase := [(4,2,c - 3 + DBu rem)%N]).
  assert (HChildView : schedule_frame_view
      (lin_sched_child nh rem emit p take)
      (lin_flat sg'
        (skipn (nh + phase_len rem)%nat w'))
      crs cbase POST).
  { unfold schedule_frame_view, lin_sched_child.
    cbv beta zeta. cbn [lsSlot lsTicks lsGap].
    repeat split.
    - unfold lin_sched_slot. lia.
    - unfold crs.
      rewrite (bulk_schedule_length p rem cs b Hp HRem28).
      assert (HQ : N.of_nat (S (length cs)) = ((p+take)/28)%N).
      { cbn [length] in HLevels. rewrite HLevels, N2Nat.id. reflexivity. }
      pose proof (N.div_mod' (p+take) 28) as HDiv.
      assert (ESpan :
        (28 * N.of_nat (S (length cs)) + rem = p+take)%N) by lia.
      rewrite ESpan, <- HEmit. reflexivity.
    - unfold crs. exact (bulk_schedule_shape
        p rem cs b Hp HRem28).
    - unfold cbase, delivery_cols.
      unfold is_col, is_cmf.
      cbn [forallb gO gZ gC].
      destruct ((c - 3 + DBu rem =? 1)%N); reflexivity.
    - unfold cbase, crs.
      rewrite bulk_schedule_stock, EChildTail.
      unfold crossed_post.
      rewrite app_nil_r. repeat rewrite <- app_assoc. reflexivity.
    - unfold cbase, crs. rewrite bulk_schedule_stock.
      unfold crossed_post.
      rewrite !length_app, length_runway, map_length.
      cbn [rung1 length].
      change (S (length cs) = N.to_nat ((p+take)/28)) in HLevels.
      lia. }
  destruct (HChildFrame crs cbase POST HChildView)
    as (child & HChildTrips & HChildOut).
  assert (HTakeSpan : take =
      (28 * N.of_nat (length (c :: cs)) + rem - p)%N).
  { pose proof (N.div_mod' (p+take) 28) as HDiv.
    assert (HQ : N.of_nat (length (c :: cs)) = ((p+take)/28)%N)
      by (rewrite HLevels, N2Nat.id; reflexivity).
    rewrite HQ, HRem. lia. }
  assert (HUsedSpan : length used = N.to_nat
      (28 * N.of_nat (length (c :: cs)) + rem - p)).
  { rewrite HUsedLen, HTakeSpan. reflexivity. }
  unfold crs in HChildTrips.
  destruct (runway_interleavedc
    c cs p rem b (lsSlot fr) used avail outer POST child f f1 T
    HLevelsSafe Hp HRem28 Hb HSlot HAvailCols HUsedSpan HUsedShape
    HReady EStockOuter HChildTrips) as (Dv & EDv & HParentTrips0).
  assert (EAvail : skipn (lsGap fr) (lin_flat sg cols)
                 = avail).
  { rewrite ECols, <- HGap. apply LineageCascade_skipn_len_app. }
  assert (ESurch : stockcost used =
      bulk_surcharge sg cols (lsGap fr)
        (lsSlot fr) take).
  { exact (bulk_surcharge_ok sg cols base avail prs used rest
             (lsGap fr) (lsSlot fr) take
             HSlot HShape EPrs HUsedLen ECols HGap). }
  assert (HCost : (D + Credit = Gross)%N).
  { rewrite <- HTakeSpan in EDv.
    rewrite ESurch, <- EAvail in EDv.
    rewrite ELev, EB in EDv.
    unfold D, Gross, Credit. lia. }
  pose proof (lin_bulk_scheduled_transitionc
    fr sg w f cols s j p take w' sg' nh rem emit sg1 w1 f1
    PRE0 POST0 c_0 b0 T D cs0
    HW HOk HAlt H0 HSeek Hj HD HFull HB HW' HTake HSafe HCur
    HLay1 HLay2 HLayL HCost (conj HChildPrefix HChildFrame)) as HAll.
  exact (proj2 HAll prs base tail HView0).
Qed.
Lemma lin_bulk_partial_scheduled_transitionc :
  forall fr sg w f cols s j p take w' sg' nh rem emit sg1 w1 f1
         (POST0 : word) (c_0 T D : N),
  sg_wf sg ->
  seek (skipn (lsCur fr) w) = (cols, s) ->
  j = (lsCur fr + length cols)%nat ->
  detect_phase w j = Some p ->
  Nat.eqb (N.to_nat ((p+take)/28)) O = true ->
  lin_bulk sg w j p take = Some (w', sg', nh, rem, emit) ->
  (take <= lsTicks fr)%N ->
  lin_flat sg s
    = phase_form p ++ (4,2,c_0)%N :: POST0 ->
  (D = dladder p (c_0 - DBu p) (N.to_nat take)
       + take * wcolcost
                  (skipn (lsGap fr) (lin_flat sg cols))
       + bulk_surcharge sg cols (lsGap fr)
           (lsSlot fr) take)%N ->
  scheduled_framec T
    (lin_sched_child nh rem emit p take) sg' w' f sg1 w1 f1 ->
  scheduled_transitionc (D + T)%N fr take sg w f sg1 w1 f1.
Proof.  intros fr sg w f cols s j p take w' sg' nh rem emit sg1 w1 f1
    POST0 c_0 T D HW HSeek Hj HD HFull HB HTake HLay2 HCost HChild.
  pose proof (bulk_full_zero_lt28 p take HFull) as Hpt.
  destruct (detect_phase_form w j p HD) as (Hp & _).
  destruct (lin_bulk_checks sg w j p take _ HB)
    as (gb & EW & HKey & HLevel & HFloor & HEnd).
  destruct (site_layout w j p gb HD EW HEnd)
    as (HLayoutRaw & HJ & HPost).
  destruct (lvl_big_shape gb HLevel) as (c & Hgb).
  rewrite Hgb in HFloor. cbn [gC] in HFloor.
  destruct (lin_bulk_partial_out
    sg w j p take w' sg' nh rem emit gb HFull HB EW)
    as (Esg & Enh & Erem & Eemit & Ew').
  subst sg'. subst nh. subst rem. subst emit.
  assert (HMod : ((p+take) mod 28 = p+take)%N)
    by (apply N.mod_small; exact Hpt).
  rewrite HMod in Ew', HChild.
  set (PRE := firstn j w) in *.
  set (POST := skipn (S (j + phase_len p)) w) in *.
  assert (Hplen :
    length (phase_form p) = phase_len p)
    by (apply phase_form_len; exact Hp).
  assert (Hrlen :
    length (phase_form (p+take)) =
      phase_len (p+take))
    by (apply phase_form_len; exact Hpt).
  assert (EW2 : w' = PRE ++ phase_form (p+take) ++
      (4,2,(c + DBu (p+take)) - DBu p)%N :: POST).
  { rewrite Ew'. rewrite HLayoutRaw at 1. rewrite Hgb.
    rewrite <- HJ, <- Hplen. apply subst_site. }
  assert (ESkip : s = phase_form p ++ (4,2,c)%N :: POST).
  { rewrite <- (skipn_seek_at w (lsCur fr) cols s HSeek), <- Hj.
    rewrite HLayoutRaw, Hgb.
    rewrite <- HJ. apply LineageCascade_skipn_len_app. }
  assert (ESite : lin_flat sg s =
      phase_form p ++ (4,2,c)%N :: lin_flat sg POST).
  { rewrite ESkip, lin_flat_app_c,
      (flat_phase_form sg p Hp).
    cbn [lin_flat]. unfold keyb, keyi,
      phshape. cbn [gO gZ]. reflexivity. }
  destruct HChild as (HChildPrefix & HChildFrame).
  assert (HRawPrefix : forall i, (i <= lsCur fr)%nat ->
      firstn i w = firstn i w').
  { intros i Hi.
    assert (HiJ : (i <= length PRE)%nat)
      by (rewrite HJ; subst j; lia).
    rewrite HLayoutRaw at 1.
    rewrite (firstn_app_left _ i PRE
      (phase_form p ++ gb :: POST) HiJ).
    rewrite EW2, (firstn_app_left _ i PRE
      (phase_form (p+take) ++
        (4,2,c + DBu (p+take) - DBu p)%N :: POST)
      HiJ). reflexivity. }
  assert (HPrefix : forall i, (i <= lsCur fr)%nat ->
      lin_flat sg (firstn i w) =
      lin_flat sg1 (firstn i w1)).
  { intros i Hi. rewrite (HRawPrefix i Hi).
    apply HChildPrefix.
    cbn [lin_sched_child lsCur]. subst j. lia. }
  split; [exact HPrefix|].
  intros prs base tail HView.
  destruct HView as (HSlot & HLen & HShape & HBaseCols & HFrame & HGap).
  assert (HMidCols : delivery_cols
      (base ++ schedule_stock prs) = true).
  { rewrite delivery_cols_app, HBaseCols,
      schedule_stock_cols. reflexivity. }
  assert (EFlatSeek :
      seek ((base ++ schedule_stock prs) ++ tail) =
      (lin_flat sg cols, lin_flat sg s)).
  { rewrite <- HFrame, seek_flat by exact HW.
    rewrite HSeek. reflexivity. }
  rewrite (seek_app_delivery_cols
    (base ++ schedule_stock prs) tail HMidCols)
    in EFlatSeek.
  destruct (seek tail) as [avail tail0] eqn:ETailSeek.
  cbn [fst snd] in EFlatSeek.
  pose proof (f_equal fst EFlatSeek) as ECols0.
  pose proof (f_equal snd EFlatSeek) as ETail0.
  cbn [fst snd] in ECols0, ETail0.
  assert (ECols : lin_flat sg cols =
      (base ++ schedule_stock prs) ++ avail)
    by (symmetry; exact ECols0).
  destruct (seek_split tail avail tail0 ETailSeek)
    as (ETailSplit & HAvailCols).
  assert (ETail : tail = avail ++ lin_flat sg s).
  { rewrite ETailSplit, ETail0. reflexivity. }
  assert (ETailSite : tail = avail ++ phase_form p ++
      (4,2,c)%N :: lin_flat sg POST).
  { rewrite ETail, ESite. repeat rewrite <- app_assoc. reflexivity. }
  set (used := firstn (N.to_nat take) prs).
  set (rest := skipn (N.to_nat take) prs).
  assert (HTakeNat : (N.to_nat take <= length prs)%nat).
  { rewrite HLen. apply PeanoNat.Nat.compare_le_iff.
    rewrite <- N2Nat.inj_compare. apply N.compare_le_iff. exact HTake. }
  assert (EPrs : prs = used ++ rest).
  { unfold used, rest. symmetry. apply firstn_skipn. }
  assert (HUsedLen : length used = N.to_nat take).
  { unfold used. rewrite length_firstn, PeanoNat.Nat.min_l by exact HTakeNat.
    reflexivity. }
  set (crs := partial_schedule p take).
  set (cbase :=
    [(4,2,(c + DBu (p+take)) - DBu p)%N]).
  assert (EChildSuffix : lin_flat sg
      (skipn (j + phase_len (p+take))%nat w') =
      cbase ++ lin_flat sg POST).
  { rewrite EW2.
    replace (j + phase_len (p+take))%nat with
      (length (PRE ++ phase_form (p+take)))
      by (rewrite length_app, HJ, Hrlen; reflexivity).
    rewrite app_assoc, LineageCascade_skipn_len_app.
    unfold cbase. cbn [lin_flat].
    unfold keyb, keyi, phshape.
    cbn [gO gZ]. reflexivity. }
  assert (HChildView : schedule_frame_view
      (lin_sched_child j (p+take)
        (marks (p+take) - marks p) p take)
      (lin_flat sg
        (skipn (j + phase_len (p+take))%nat w'))
      crs cbase (lin_flat sg POST)).
  { unfold schedule_frame_view, lin_sched_child.
    cbv beta zeta. cbn [lsSlot lsTicks lsGap].
    repeat split.
    - unfold lin_sched_slot.
      pose proof (marks_le3 p Hp). lia.
    - unfold crs, partial_schedule. rewrite repeat_length.
      reflexivity.
    - unfold crs. exact (partial_schedule_shape p take Hpt).
    - unfold cbase, delivery_cols.
      unfold is_col, is_cmf.
      cbn [forallb gO gZ gC].
      destruct (((c + DBu (p+take)) -
        DBu p =? 1)%N); reflexivity.
    - rewrite EChildSuffix. unfold cbase, crs.
      rewrite partial_schedule_stock. cbn [app]. reflexivity.
    - unfold cbase, crs. rewrite partial_schedule_stock.
      apply PeanoNat.Nat.eqb_eq in HFull.
      cbn [length app]. rewrite HFull. reflexivity. }
  destruct (HChildFrame crs cbase (lin_flat sg POST) HChildView)
    as (child & HChildTrips & HChildOut).
  cbn [lin_sched_child lsCur] in HChildOut.
  assert (EChildPre : lin_flat sg
      (firstn (j + phase_len (p+take))%nat w') =
      lin_flat sg PRE ++ phase_form (p+take)).
  { rewrite EW2.
    replace (j + phase_len (p+take))%nat with
      (length PRE + length (phase_form (p+take)))%nat
      by (rewrite HJ, Hrlen; reflexivity).
    rewrite firstn_prefix_add, lin_flat_app_c.
    rewrite firstn_len_app.
    rewrite (flat_phase_form sg (p+take) Hpt). reflexivity. }
  assert (EChildFull : lin_flat sg1 w1 =
      lin_flat sg PRE ++ phase_form (p+take) ++
        (4,2,c + DBu (p+take) - DBu p)%N :: child).
  { rewrite (flat_firstn_skipn sg1 w1
      (j + phase_len (p+take))%nat).
    rewrite <- (HChildPrefix
      (j + phase_len (p+take))%nat (le_n _)).
    rewrite EChildPre, HChildOut. unfold cbase.
    repeat rewrite <- app_assoc. reflexivity. }
  unfold crs in HChildTrips.
  pose proof (partial_interleavedc
    p take (c - DBu p)%N used avail
    (lin_flat sg POST) child f f1 T Hpt
    ltac:(unfold FLOOR in *; lia)
    HAvailCols HUsedLen HChildTrips) as HParentTrips0.
  assert (EAvail : skipn (lsGap fr) (lin_flat sg cols)
                 = avail).
  { rewrite ECols, <- HGap. apply LineageCascade_skipn_len_app. }
  assert (ESurch : stockcost used
                 = bulk_surcharge sg cols (lsGap fr)
                     (lsSlot fr) take).
  { exact (bulk_surcharge_ok sg cols base avail prs used rest
             (lsGap fr) (lsSlot fr) take
             HSlot HShape EPrs HUsedLen ECols HGap). }
  assert (EC0 : c = c_0).
  { assert (EE : phase_form p ++ (4,2,c)%N
                   :: lin_flat sg POST
               = phase_form p ++ (4,2,c_0)%N :: POST0)
      by (rewrite <- ESite, <- HLay2; reflexivity).
    apply app_inv_head in EE. injection EE as EC1 _. lia. }
  assert (EDD : (dladder p (c - DBu p) (N.to_nat take)
                 + take * wcolcost avail + stockcost used)%N = D).
  { rewrite HCost, ESurch, <- EAvail, EC0. reflexivity. }
  rewrite EDD in HParentTrips0.
  replace (c - DBu p + DBu p)%N with c
    in HParentTrips0 by lia.
  replace (c - DBu p + DBu (p+take))%N with
    (c + DBu (p+take) - DBu p)%N
    in HParentTrips0 by lia.
  assert (HParentTrips : sched_tripsc (D + T)%N used tail f
      (schedule_stock used ++ avail ++
        phase_form (p+take) ++
        (4,2,c + DBu (p+take) - DBu p)%N :: child) f1).
  { rewrite ETailSite. exact HParentTrips0. }
  set (tail' := schedule_stock used ++ avail ++
    phase_form (p+take) ++
    (4,2,c + DBu (p+take) - DBu p)%N :: child).
  assert (EPreFlat : lin_flat sg PRE =
      lin_flat sg (firstn (lsCur fr) w) ++
        lin_flat sg cols).
  { unfold PRE. rewrite Hj, (firstn_seek_at w
      (lsCur fr) cols s HSeek).
    apply lin_flat_app_c. }
  assert (EFinalFull : lin_flat sg1 w1 =
      lin_flat sg (firstn (lsCur fr) w) ++
        (base ++ schedule_stock rest) ++ tail').
  { unfold tail'. rewrite EChildFull, EPreFlat, ECols, EPrs,
      schedule_stock_app.
    repeat rewrite <- app_assoc. reflexivity. }
  assert (EFinalSuffix : lin_flat sg1
      (skipn (lsCur fr) w1) =
      (base ++ schedule_stock rest) ++ tail').
  { pose proof (flat_firstn_skipn
      sg1 w1 (lsCur fr)) as EDec.
    rewrite <- (HPrefix (lsCur fr) (le_n _)) in EDec.
    rewrite EFinalFull in EDec. apply app_inv_head in EDec.
    symmetry. exact EDec. }
  exists used, rest, tail'.
  split; [exact EPrs|]. split; [exact HUsedLen|].
  split; [exact HParentTrips|].
  unfold schedule_frame_view, lin_sched_advance.
  cbn [lsSlot lsTicks lsGap].
  repeat split.
  - exact (sched_slot_advance_le3
      (lsSlot fr) take HSlot).
  - unfold rest. exact (schedule_ticks_skip
      (lsTicks fr) take prs HLen HTake).
  - change (schedule_shape
      (lin_sched_slot_advance (lsSlot fr) take) rest).
    unfold rest.
    pose proof (schedule_shape_skipn
      (N.to_nat take) prs (lsSlot fr) HSlot HShape) as HRestShape.
    rewrite N2Nat.id in HRestShape. exact HRestShape.
  - exact HBaseCols.
  - exact EFinalSuffix.
  - unfold rest.
    pose proof (schedule_stock_skip_length
      (N.to_nat take) prs (lsSlot fr)
      HTakeNat HSlot HShape) as HRestStock.
    rewrite N2Nat.id in HRestStock.
    pose proof (schedule_stock_first_skip
      (N.to_nat take) prs) as EStockSplit.
    apply (f_equal (@length bg)) in EStockSplit.
    rewrite length_app in EStockSplit. fold used rest in EStockSplit.
    pose proof (schedule_stock_firstn_length
      (N.to_nat take) prs (lsSlot fr)
      HTakeNat HSlot HShape) as HUsedStock.
    fold used in HUsedStock. rewrite N2Nat.id in HUsedStock.
    rewrite length_app, HRestStock. rewrite length_app in HGap. lia.
Qed.
Lemma casc_bulk_net_step :
  forall fr rest sg w f cols s j p take w' sg' nh rem emit
         sgZ wZ fZ (PRE0 POST0 : word) (c_0 b0 T : N)
         (cs0 : list N),
  sg_wf sg -> lin_ok sg w = true ->
  (forall x, In x sg -> altb (sBody x) = true) ->
  is_spc (nth O w d0) = false ->
  seek (skipn (lsCur fr) w) = (cols, s) ->
  j = (lsCur fr + length cols)%nat ->
  detect_phase w j = Some p ->
  Nat.eqb (N.to_nat ((p+take)/28)) O = false ->
  lin_bulk sg w j p take = Some (w', sg', nh, rem, emit) ->
  sg_wf sg' ->
  (take <= lsTicks fr)%N ->
  lin_sched_bulk_safe fr (lin_flen sg cols) p take = true ->
  (lsCur fr <= nh)%nat ->
  lin_flat sg (firstn (lsCur fr) w)
    ++ lin_flat sg cols
    = PRE0 ++ runway (c_0 :: cs0) ->
  lin_flat sg s
    = phase_form p ++ (4,2,b0 + DBu p)%N :: POST0 ->
  length (c_0 :: cs0) = N.to_nat ((p + take)/28) ->
  scheduled_workc T
    (lin_sched_child nh rem emit p take
     :: lin_sched_advance fr take :: rest) sg' w' f sgZ wZ fZ ->
  scheduled_workc
    (((take * wcolcost
          (skipn (lsGap fr) (lin_flat sg cols))
       + dlocals (rev (c_0 :: cs0)) p rem b0
       + bulk_surcharge sg cols (lsGap fr)
           (lsSlot fr) take)
      - rcredit (rev (c_0 :: cs0)) rem) + T)%N
    (fr :: rest) sg w f sgZ wZ fZ.
Proof.
  intros fr rest sg w f cols s j p take w' sg' nh rem emit
    sgZ wZ fZ PRE0 POST0 c_0 b0 T cs0
    HW HOk HAlt H0 HSeek Hj HD HFull HB HW' HTake HSafe HCur
    HLay1 HLay2 HLayL HWork.
  set (D :=
    ((take * wcolcost
        (skipn (lsGap fr) (lin_flat sg cols))
      + dlocals (rev (c_0 :: cs0)) p rem b0
      + bulk_surcharge sg cols (lsGap fr)
          (lsSlot fr) take)
     - rcredit (rev (c_0 :: cs0)) rem)%N).
  change (scheduled_workc (D + T)%N
            (fr :: rest) sg w f sgZ wZ fZ).
  destruct (scheduled_workc_inv _ _ _ _ _ _ _ _ _ HWork)
    as (T1 & T23 & sg1 & w1 & f1 & ET & HChildFrame & HWork2).
  destruct (scheduled_workc_inv _ _ _ _ _ _ _ _ _ HWork2)
    as (T2 & T3 & sg2 & w2 & f2 & ET23 & HAdvFrame & HRest).
  pose proof (lin_bulk_scheduled_transition_netc
    fr sg w f cols s j p take w' sg' nh rem emit sg1 w1 f1
    PRE0 POST0 c_0 b0 T1 cs0
    HW HOk HAlt H0 HSeek Hj HD HFull HB HW' HTake HSafe HCur
    HLay1 HLay2 HLayL HChildFrame) as HTrans.
  change (scheduled_transitionc (D + T1)%N
            fr take sg w f sg1 w1 f1) in HTrans.
  pose proof (scheduled_transition_framec (D + T1)%N T2
    fr take sg w f sg1 w1 f1 sg2 w2 f2 HTrans HAdvFrame) as HFrame.
  replace (D + T)%N with (((D + T1) + T2) + T3)%N by lia.
  exact (scheduled_workc_cons _ _ _ _ _ _ _ _ _ _ _ _ _
           HFrame HRest).
Qed.
Lemma casc_bulk_partial_step :
  forall fr rest sg w f cols s j p take w' sg' nh rem emit
         sgZ wZ fZ (POST0 : word) (c_0 D T : N),
  sg_wf sg ->
  seek (skipn (lsCur fr) w) = (cols, s) ->
  j = (lsCur fr + length cols)%nat ->
  detect_phase w j = Some p ->
  Nat.eqb (N.to_nat ((p+take)/28)) O = true ->
  lin_bulk sg w j p take = Some (w', sg', nh, rem, emit) ->
  (take <= lsTicks fr)%N ->
  lin_flat sg s
    = phase_form p ++ (4,2,c_0)%N :: POST0 ->
  (D = dladder p (c_0 - DBu p) (N.to_nat take)
       + take * wcolcost
                  (skipn (lsGap fr) (lin_flat sg cols))
       + bulk_surcharge sg cols (lsGap fr)
           (lsSlot fr) take)%N ->
  scheduled_workc T
    (lin_sched_child nh rem emit p take
     :: lin_sched_advance fr take :: rest) sg' w' f sgZ wZ fZ ->
  scheduled_workc (D + T)%N (fr :: rest) sg w f sgZ wZ fZ.
Proof.
  intros fr rest sg w f cols s j p take w' sg' nh rem emit
    sgZ wZ fZ POST0 c_0 D T
    HW HSeek Hj HD HFull HB HTake HLay2 HCost HWork.
  destruct (scheduled_workc_inv _ _ _ _ _ _ _ _ _ HWork)
    as (T1 & T23 & sg1 & w1 & f1 & ET & HChildFrame & HWork2).
  destruct (scheduled_workc_inv _ _ _ _ _ _ _ _ _ HWork2)
    as (T2 & T3 & sg2 & w2 & f2 & ET23 & HAdvFrame & HRest).
  pose proof (lin_bulk_partial_scheduled_transitionc
    fr sg w f cols s j p take w' sg' nh rem emit sg1 w1 f1
    POST0 c_0 T1 D
    HW HSeek Hj HD HFull HB HTake HLay2 HCost HChildFrame) as HTrans.
  pose proof (scheduled_transition_framec (D + T1)%N T2
    fr take sg w f sg1 w1 f1 sg2 w2 f2 HTrans HAdvFrame) as HFrame.
  replace (D + T)%N with ((D + T1 + T2) + T3)%N by lia.
  exact (scheduled_workc_cons _ _ _ _ _ _ _ _ _ _ _ _ _
           HFrame HRest).
Qed.
Lemma layout_levels (sg : list seg) (Fj PRE0 : word)
      (c_0 : N) (cs0 : list N) (L : nat) :
  Fj = PRE0 ++ runway (c_0 :: cs0) ->
  length (c_0 :: cs0) = L ->
  c_0 :: cs0 = wrungs (skipn (length Fj - 2 * L) Fj).
Proof.
  intros E EL.
  assert (ELen : length Fj = (length PRE0 + 2 * L)%nat).
  { rewrite E, length_app, length_runway, EL. reflexivity. }
  replace (length Fj - 2 * L)%nat with (length PRE0) by lia.
  rewrite E, LineageCascade_skipn_len_app, wrungs_runway. reflexivity.
Qed.
Lemma layout_base (sg : list seg) (s POST0 : word) (p b0 : N) :
  (p < 28)%N ->
  lin_flat sg s
    = phase_form p ++ (4,2,b0 + DBu p)%N :: POST0 ->
  b0 = (gC (nth (phase_len p)
                     (lin_flat sg s) d0)
        - DBu p)%N.
Proof.
  intros Hp E.
  assert (Hplen : length (phase_form p) = phase_len p)
    by (apply phase_form_len; exact Hp).
  rewrite E, <- Hplen, nth_middle. cbn [gC]. lia.
Qed.
Definition dnetc (RHS CR : N) : cost :=
  if (CR <=? RHS)%N then cx (RHS - CR)%N else cundef.
Lemma dnetc_cx (RHS CR D : N) :
  dnetc RHS CR = cx D -> (D + CR = RHS)%N.
Proof.
  unfold dnetc. destruct (CR <=? RHS)%N eqn:EB; intros HE.
  - apply N.leb_le in EB. unfold cx in HE.
    pose proof (f_equal fst HE) as E0. cbn [fst] in E0. lia.
  - unfold cx, cundef in HE.
    pose proof (f_equal fst HE) as E0.
    pose proof (f_equal snd HE) as E1.
    cbn [fst snd] in E0, E1. lia.
Qed.
Definition dbulk (sg : list seg) (w cols s : word)
    (cur gap : nat) (slot p take : N) : cost :=
  let Fj := (lin_flat sg (firstn cur w)
             ++ lin_flat sg cols)%list in
  let rem := ((p + take) mod 28)%N in
  let LL := N.to_nat ((p + take) / 28) in
  let rl := rev (wrungs (skipn (length Fj - 2 * LL) Fj)) in
  let bb := (gC (nth (phase_len p)
                          (lin_flat sg s) d0)
             - DBu p)%N in
  let W := wcolcost (skipn gap (lin_flat sg cols)) in
  dnetc (take * W + dlocals rl p rem bb
         + bulk_surcharge sg cols gap slot take)%N
        (rcredit rl rem).
Definition dbulkn (sg : list seg) (w cols s : word)
    (cur gap : nat) (slot p take : N) : cost :=
  let Fj := (lin_flat sg (firstn cur w)
             ++ lin_flat sg cols)%list in
  let rem := ((p + take) mod 28)%N in
  let LL := N.to_nat ((p + take) / 28) in
  let rl := rev (wrungs (skipn (length Fj - 2 * LL) Fj)) in
  let bb := (gC (nth (phase_len p)
                          (lin_flat sg s) d0)
             - DBu p)%N in
  let W := wcolcost (skipn gap (lin_flat sg cols)) in
  cx ((take * W + dlocals rl p rem bb
            + bulk_surcharge sg cols gap slot take)
           - rcredit rl rem)%N.
Lemma dbulk_cost (sg : list seg) (w cols s PRE0 POST0 : word)
      (cur gap : nat) (slot p take b0 c_0 D : N) (cs0 : list N) :
  (p < 28)%N ->
  lin_flat sg (firstn cur w) ++ lin_flat sg cols
    = PRE0 ++ runway (c_0 :: cs0) ->
  lin_flat sg s
    = phase_form p ++ (4,2,b0 + DBu p)%N :: POST0 ->
  length (c_0 :: cs0) = N.to_nat ((p + take)/28) ->
  dbulk sg w cols s cur gap slot p take = cx D ->
  (D + rcredit (rev (c_0 :: cs0)) ((p+take) mod 28)
   = take * wcolcost
              (skipn gap (lin_flat sg cols))
     + dlocals (rev (c_0 :: cs0)) p ((p+take) mod 28) b0
     + bulk_surcharge sg cols gap slot take)%N.
Proof.
  intros Hp HLay1 HLay2 HLayL HE.
  unfold dbulk in HE. cbv zeta in HE.
  rewrite <- (layout_levels sg _ PRE0 c_0 cs0 _ HLay1 HLayL) in HE.
  rewrite <- (layout_base sg s POST0 p b0 Hp HLay2) in HE.
  exact (dnetc_cx _ _ _ HE).
Qed.
Local Open Scope N_scope.
Local Open Scope bool_scope.
Local Open Scope sym.
Local Open Scope N_scope.
Local Open Scope bool_scope.
Local Open Scope sym.
Local Open Scope N_scope.
Opaque LROUND_FUEL LROUND_CHUNKS
       FLAT_ROUND_FUEL CFUEL TRIES.
Lemma CE_cdrop6 (d : cost) :
  (6 <= clo d)%N ->
  CE d -> CE (cdrop6 d).
Proof.
  unfold CE, cdrop6, clo, chi.
  destruct d as [lo hi]. cbn [fst snd]. intros H6 ->.
  assert (E6 : (6 <=? hi)%N = true) by (apply N.leb_le; exact H6).
  rewrite E6. reflexivity.
Qed.
Lemma FlightLiveC_CE_cadd (a b : cost) :
  CE a -> CE b -> CE (cadd a b).
Proof. intros HA HB. exact (CE_cadd a b HA HB). Qed.
Lemma CE_cx_repr (d : cost) :
  CE d -> d = cx (chi d).
Proof.
  unfold CE, clo, chi, cx.
  destruct d as [lo hi]. cbn [fst snd]. intros ->. reflexivity.
Qed.
Lemma cleaf_success_ge6 (s out : word) (f f' : N) :
  sand_leaf s = false ->
  fst (cleaf_act s f) = Some (out, f') ->
  (6 <= clo (snd (cleaf_act s f)))%N.
Proof.
  intros HSand HRun.
  pose proof (cleaf_act_live s f out f' HRun) as HLive.
  pose proof (CE_of_CL _ HLive) as HExact.
  set (d := snd (cleaf_act s f)) in *.
  assert (ED : d = cx (chi d)) by (apply CE_cx_repr; exact HExact).
  assert (HPair : cleaf_act s f = (Some (out, f'), d)).
  { unfold d. rewrite <- HRun. apply surjective_pairing. }
  assert (HIn : cin (N.to_nat (chi d)) d).
  { rewrite ED. apply cin_cx. }
  destruct (leaf_ftripC s f out f' d
              (N.to_nat (chi d)) HPair HIn)
    as [(ci & pi & qi & K & EK & HF & EQ)
       |(ci & pi & qi & K & EK & HS & EQ & HSand' & Ef)].
  - rewrite N2Nat.id in EK.
    change (6 <= clo d)%N.
    rewrite ED. cbn [clo cx fst].
    lia.
  - rewrite HSand in HSand'. discriminate HSand'.
Qed.
Theorem cdtick_after_seek_exact (cols s : word) (f : N)
    (out : word) (f' : N) :
  forallb is_col cols = true ->
  fst (cdtick_after_seek cols s f) = Some (out, f') ->
  CE (snd (cdtick_after_seek cols s f)).
Proof.
  intros HCols HRun.
  unfold cdtick_after_seek in HRun |- *.
  destruct (fst (crenew_seg (length s) cols s f))
    as [[body f2]|] eqn:ERenew.
  - exact (proj2 (cascade_live (length s))
             cols s f body f2 HCols ERenew).
  - destruct s as [|[[o z] c] rest].
    + unfold cleaf_lift in HRun |- *.
      destruct (fst (cleaf_act [] f)) as [[body f2]|] eqn:ELeaf;
        [|discriminate HRun].
      apply FlightLiveC_CE_cadd; [apply CE_cx|].
      apply CE_cdrop6.
      * eapply cleaf_success_ge6; [reflexivity|exact ELeaf].
      * apply CE_of_CL.
        exact (cleaf_act_live [] f body f2 ELeaf).
    + destruct (((z =? 3) && (c =? 1))%N) eqn:EZ.
      * match type of HRun with
        | context [fst (cfire_comp ?n ?s0 ?f0)] =>
            destruct (fst (cfire_comp n s0 f0))
              as [[body f2]|] eqn:EFire
        end;
          cbn [fst snd] in HRun |- *; [|discriminate HRun].
        apply FlightLiveC_CE_cadd; [apply CE_cx|].
        exact (proj1 (cascade_live
                       (length ((o,z,c) :: rest)))
                 ((o,z,c) :: rest) f body f2 EFire).
      * match type of HRun with
        | context [sand_leaf ?s0] =>
            destruct (sand_leaf s0) eqn:ESand
        end.
        { cbn [fst] in HRun. discriminate HRun. }
        unfold cleaf_lift in HRun |- *.
        match type of HRun with
        | context [fst (cleaf_act ?s0 ?f0)] =>
            destruct (fst (cleaf_act s0 f0))
              as [[body f2]|] eqn:ELeaf
        end;
          cbn [fst snd] in HRun |- *; [|discriminate HRun].
        apply FlightLiveC_CE_cadd; [apply CE_cx|].
        apply CE_cdrop6.
        -- eapply cleaf_success_ge6; [exact ESand|exact ELeaf].
        -- apply CE_of_CL.
           exact (cleaf_act_live
                    ((o,z,c) :: rest) f body f2 ELeaf).
Qed.
Lemma caddx_exact (a b : cost) :
  CE a -> CE b ->
  CE (caddx a b).
Proof.
  intros HA HB. unfold caddx.
  unfold CE, clo, chi in HA, HB.
  destruct a as [al ah], b as [bl bh]. cbn [fst snd] in *.
  subst ah bh. rewrite !N.eqb_refl. cbn [andb].
  unfold CE, cadd, clo, chi.
  reflexivity.
Qed.
Theorem clin_bottom_sched_zrun_exact (q : nat) :
  forall lc sg lw f gap slot out f' d,
  sg_wf sg ->
  clin_bottom_sched_zrun q lc sg lw f gap slot
    = (Some (out, f'), d) ->
  CE d.
Proof.
  induction q as [|q IH]; intros lc sg lw f gap slot out f' d HW HRun.
  - cbn [clin_bottom_sched_zrun] in HRun.
    destruct (lin_literal_word lw); [|discriminate HRun].
    injection HRun as _ HD. subst d. apply CE_czero.
  - destruct (clin_bottom_sched_zrun_S_inv q lc sg lw f gap slot
                out f' d HRun)
      as (cols & g & t & renewed & sfx & f2 & lw2 & d2
          & HLit & HSeek & HStep & HRenew & HJoin & HRec & HD).
    subst d. apply caddx_exact.
    + assert (HCols : forallb is_col (skipn gap cols) = true).
      { apply forallb_skipn.
        exact (seek_cols _ _ _ HSeek). }
      assert (HLitCols : lin_literal_word cols = true).
        { pose proof (literal_word_skipn lc lw HLit) as HS.
          pose proof (seek_split (skipn lc lw) cols (g :: t) HSeek)
            as [ESplit _].
          rewrite ESplit in HS.
          exact (literal_word_app_l cols (g :: t) HS). }
        assert (HRenewAvail : renewed = true ->
                  (2 <= length (skipn gap cols))%nat).
        { intro ER. specialize (HRenew ER).
          rewrite (lin_flen_flat_wf sg cols HW) in HRenew.
          rewrite (literal_word_flat sg cols HLitCols) in HRenew.
          rewrite length_skipn. lia. }
        destruct (lin_dtick_after_seek_strip
          (firstn gap cols) (skipn gap cols) (g :: t) f
          renewed sfx f2 ltac:(rewrite firstn_skipn; exact HStep)
          HRenewAvail) as (body & HBody & EBody).
      assert (HBodyC : fst (cdtick_after_seek
                       (skipn gap cols) (g :: t) f) = Some (body, f2)).
      { rewrite cdtick_after_seek_proj.
        exact (lin_dtick_after_seek_proj
                 (skipn gap cols) (g :: t) f renewed body f2 HBody). }
      exact (cdtick_after_seek_exact
               (skipn gap cols) (g :: t) f body f2 HCols HBodyC).
    + exact (IH lc sg lw2 f2
               (gap - 2 * N.to_nat (lin_sched_grant_one slot))%nat
               (lin_sched_slot_advance_one slot)
               out f' d2 HW HRec).
Qed.
Corollary clin_bottom_sched_zrun_cx (q lc : nat)
    (sg : list seg) (lw : word) (f : N)
    (gap : nat) (slot : N) (out : word) (f' : N) (d : cost) :
  clin_bottom_sched_zrun q lc sg lw f gap slot
    = (Some (out, f'), d) ->
  sg_wf sg ->
  exists T,
    clin_bottom_sched_zrun q lc sg lw f gap slot
      = (Some (out, f'), cx T).
Proof.
  intros HRun HW.
  exists (chi d). rewrite <- (CE_cx_repr d
    (clin_bottom_sched_zrun_exact q lc sg lw f gap slot out f' d HW HRun)).
  exact HRun.
Qed.
Set Warnings "require-in-module".
Local Open Scope N_scope.
Opaque LROUND_FUEL LROUND_CHUNKS
       FLAT_ROUND_FUEL CFUEL TRIES.
Definition ddirect (sg : list seg) (cols s : word) (f : N)
                   (gap : nat) : cost :=
  snd (cdtick_after_seek
         (skipn gap (lin_flat sg cols)) (lin_flat sg s) f).
Definition dbulkp (sg : list seg) (cols s : word)
                  (gap : nat) (slot p take : N) : cost :=
  cx (dladder p
             (gC (nth (phase_len p)
                           (lin_flat sg s) d0) - DBu p)
             (N.to_nat take)
           + take * wcolcost
                      (skipn gap (lin_flat sg cols))
           + bulk_surcharge sg cols gap slot take)%N.
Definition dbulkc (sg : list seg) (w cols s : word)
                  (cur gap : nat) (slot p take : N) : cost :=
  if Nat.eqb (N.to_nat ((p + take) / 28)) O
  then dbulkp sg cols s gap slot p take
  else dbulkn sg w cols s cur gap slot p take.
Fixpoint ccasc (fu : nat) (sg : list seg) (ps : atab)
               (w : word) (f : N) (st : list lsc_frame)
  : option (word * list seg * atab * N) * cost :=
  match fu with
  | O => (None, cundef)
  | S fu' =>
      match st with
      | [] => (Some (w, sg, ps, f), czero)
      | fr :: rest =>
          let cur := lsCur fr in
          let tk := lsTicks fr in
          if (tk =? 0)%N then ccasc fu' sg ps w f rest
          else
          let sf := skipn cur w in
          let '(cols2, s3) := seek sf in
          match s3 with
          | [] => (None, cundef)
          | _ :: _ =>
            let tg := (cur + length cols2)%nat in
            match lin_bottom_take cols2 s3 f tk with
            | Some take =>
                let basec := (cur - 2)%nat in
                let lc := (cur - basec)%nat in
                match clin_bottom_sched_zrun (N.to_nat take) lc sg
                        (skipn basec w) f (lsGap fr) (lsSlot fr) with
                | (Some (lw2, f2), dz) =>
                    let w2 := setsfx basec w lw2 in
                    match relocate_all sg ps w2 with
                    | Some ps2 =>
                        let st2 := lin_sched_advance fr take :: rest in
                        if lin_guard_at sg ps2 w2
                        then let r := ccasc fu' sg ps2 w2 f2 st2 in
                             (fst r, caddx dz (snd r))
                        else (None, cundef)
                    | None => (None, cundef)
                    end
                | (None, _) => (None, cundef)
                end
            | None =>
            match (if Nat.ltb (cur + 2) tg then
                     match detect_phase s3 O with
                     | Some pk =>
                         let take := lin_bulk_take sg w cur tg pk tk in
                         if (THRESH <=? take)%N
                         then match lin_bulk sg w tg pk take with
                              | Some (w2, sg2, t2, p2k, ek) =>
                                  Some (w2, sg2, t2, p2k, ek, take, pk)
                              | None => None
                              end
                         else None
                     | None => None
                     end
                   else None) with
            | Some (w2, sg2, t2, p2k, ek, take, pk) =>
                let colflat := lin_flen sg cols2 in
                if negb (lin_sched_bulk_safe fr colflat pk take)
                then (None, cundef) else
                match lin_at_safe sg2 w2 t2 with
                | Some w3 =>
                match locate_all sg2 w3 with
                | Some ps2 =>
                    if lin_guard_at sg2 ps2 w3
                    then let r := ccasc fu' sg2 ps2 w3 f
                                    (lin_sched_child t2 p2k ek pk take ::
                                     lin_sched_advance fr take :: rest) in
                         (fst r,
                          caddx (dbulkc sg w cols2 s3 cur
                                          (lsGap fr) (lsSlot fr) pk take)
                                       (snd r))
                    else (None, cundef)
                | None => (None, cundef)
                end
                | None => (None, cundef)
                end
            | None =>
                match lin_dtick_after_seek cols2 s3 f with
                | Some (renewed, sfx, f2) =>
                    let dd := ddirect sg cols2 s3 f (lsGap fr) in
                    if renewed then
                      if negb (Nat.leb (lsGap fr + 2) (lin_flen sg cols2))
                      then (None, cundef) else
                      match (if Nat.eqb cur O then Some sfx
                             else lin_join_safe sg (firstn cur w) sfx) with
                      | Some w2 =>
                      match (if lin_same_length w w2
                             then Some ps else relocate_all sg ps w2) with
                      | Some ps2 =>
                          if lin_guard_at sg ps2 w2
                          then let r := ccasc fu' sg ps2 w2 f2
                                          (lin_sched_advance_one fr :: rest) in
                               (fst r, caddx dd (snd r))
                          else (None, cundef)
                      | None => (None, cundef)
                      end
                      | None => (None, cundef)
                      end
                    else
                      match (if Nat.eqb cur O then Some sfx
                             else lin_join_safe sg (firstn cur w) sfx) with
                      | Some w2 =>
                      match (if lin_same_length w w2
                             then Some ps else relocate_all sg ps w2) with
                      | Some ps2 =>
                          if lin_guard_at sg ps2 w2
                          then let r := ccasc fu' sg ps2 w2 f2
                                          (lin_sched_advance_one fr :: rest) in
                               (fst r, caddx dd (snd r))
                          else (None, cundef)
                      | None => (None, cundef)
                      end
                      | None => (None, cundef)
                      end
                | None => (None, cundef)
                end
            end
            end
          end
      end
  end.
Lemma ccasc_proj (fu : nat) :
  forall sg ps w f st,
  fst (ccasc fu sg ps w f st) = lin_casc_safe_at fu sg ps w f st.
Proof.
  induction fu as [|fu IH]; intros sg ps w f st;
    cbn [ccasc lin_casc_safe_at]; [reflexivity|].
  destruct st as [|fr rest]; [reflexivity|].
  destruct (lsTicks fr =? 0)%N; [apply IH|].
  destruct (seek (skipn (lsCur fr) w)) as [cols2 s3] eqn:ESeek.
  destruct s3 as [|g t]; [reflexivity|].
  destruct (lin_bottom_take cols2 (g :: t) f (lsTicks fr))
    as [take|] eqn:ETake.
  - rewrite <- (clin_bottom_sched_zrun_proj (N.to_nat take)
      (lsCur fr - (lsCur fr - 2))%nat sg
      (skipn (lsCur fr - 2) w) f (lsGap fr) (lsSlot fr)).
    destruct (clin_bottom_sched_zrun (N.to_nat take)
      (lsCur fr - (lsCur fr - 2))%nat sg
      (skipn (lsCur fr - 2) w) f (lsGap fr) (lsSlot fr))
      as [[[lw2 f2]|] dz] eqn:EZ; cbn [fst]; [|reflexivity].
    destruct (relocate_all sg ps
      (setsfx (lsCur fr - 2) w lw2)) as [ps2|]; [|reflexivity].
    destruct (lin_guard_at sg ps2
      (setsfx (lsCur fr - 2) w lw2)); [|reflexivity].
    cbn [fst]. apply IH.
  - destruct (if Nat.ltb (lsCur fr + 2)
                (lsCur fr + length cols2)%nat then
                match detect_phase (g :: t) O with
                | Some pk =>
                    let take := lin_bulk_take sg w (lsCur fr)
                                  (lsCur fr + length cols2)%nat pk
                                  (lsTicks fr) in
                    if (THRESH <=? take)%N
                    then match lin_bulk sg w
                                 (lsCur fr + length cols2)%nat pk take with
                         | Some (w2, sg2, t2, p2k, ek) =>
                             Some (w2, sg2, t2, p2k, ek, take, pk)
                         | None => None
                         end
                    else None
                | None => None
                end
              else None)
      as [[[[[[[wB sgB] tB] pB] eB] tkB] pkB]|]; [|].
    + destruct (negb (lin_sched_bulk_safe fr (lin_flen sg cols2) pkB tkB));
        [reflexivity|].
      destruct (lin_at_safe sgB wB tB) as [wC|]; [|reflexivity].
      destruct (locate_all sgB wC) as [psB|]; [|reflexivity].
      destruct (lin_guard_at sgB psB wC); [|reflexivity].
      cbn [fst]. apply IH.
    + destruct (lin_dtick_after_seek cols2 (g :: t) f)
        as [[[renewed sfx] f2]|]; [|reflexivity].
      destruct renewed.
      * destruct (negb (Nat.leb (lsGap fr + 2) (lin_flen sg cols2)));
          [reflexivity|].
        destruct (if Nat.eqb (lsCur fr) O then Some sfx
                  else lin_join_safe sg (firstn (lsCur fr) w) sfx)
          as [w2|]; [|reflexivity].
        destruct (if lin_same_length w w2
                  then Some ps else relocate_all sg ps w2) as [ps2|];
          [|reflexivity].
        destruct (lin_guard_at sg ps2 w2); [|reflexivity].
        cbn [fst]. apply IH.
      * destruct (if Nat.eqb (lsCur fr) O then Some sfx
                  else lin_join_safe sg (firstn (lsCur fr) w) sfx)
          as [w2|]; [|reflexivity].
        destruct (if lin_same_length w w2
                  then Some ps else relocate_all sg ps w2) as [ps2|];
          [|reflexivity].
        destruct (lin_guard_at sg ps2 w2); [|reflexivity].
        cbn [fst]. apply IH.
Qed.
Lemma pair_eta {A B : Type} (p : A * B) : p = (fst p, snd p).
Proof. destruct p; reflexivity. Qed.
Lemma cx_inj (a b : N) : cx a = cx b -> a = b.
Proof. unfold cx. intros H. injection H as H1 _. exact H1. Qed.
Lemma cx_not_undef (a : N) : cx a = cundef -> False.
Proof.
  unfold cx, cundef. intros H. injection H as H1 H2. lia.
Qed.
Lemma flat_site_at (sg : list seg) (w : word) (j : nat)
      (p t : N) (r : word * list seg * nat * N * N) :
  detect_phase w j = Some p ->
  lin_bulk sg w j p t = Some r ->
  exists (c_0 : N) (POST0 : word),
    lin_flat sg (skipn j w)
      = phase_form p ++ (4,2,c_0)%N :: POST0
    /\ c_0 = gC (nth (phase_len p)
                         (lin_flat sg (skipn j w)) d0).
Proof.
  intros HD HB.
  destruct (lin_bulk_checks sg w j p t r HB)
    as (gb & EW & HKey & HLvl & _ & HEnd).
  destruct (site_layout w j p gb HD EW HEnd) as (HLayout & HJ & _).
  destruct (detect_phase_form w j p HD) as (Hp & _).
  assert (Egb : gb = (4,2,gC gb)%N).
  { unfold lvl_big in HLvl.
    apply andb_prop in HLvl as (H1 & _).
    apply andb_prop in H1 as (Ho & Hz).
    apply N.eqb_eq in Ho. apply N.eqb_eq in Hz.
    destruct gb as [[o z] c]; cbn [gO gZ gC] in *.
    subst o z. reflexivity. }
  assert (ESk : skipn j w
    = phase_form p
      ++ gb :: skipn (S (j + phase_len p)) w).
  { transitivity (skipn (length (firstn j w))
      (firstn j w ++ (phase_form p
                      ++ gb :: skipn (S (j + phase_len p)) w))).
    - rewrite HJ. f_equal. exact HLayout.
    - apply LineageCascade_skipn_len_app. }
  assert (EFlat : lin_flat sg (skipn j w)
    = phase_form p
      ++ gb :: lin_flat sg (skipn (S (j + phase_len p)) w)).
  { rewrite ESk, lin_flat_app_c, (flat_phase_form sg p Hp).
    f_equal.
    change (gb :: skipn (S (j + phase_len p)) w)
      with ([gb] ++ skipn (S (j + phase_len p)) w).
    rewrite lin_flat_app_c, (flat_single sg gb HKey). reflexivity. }
  exists (gC gb),
         (lin_flat sg (skipn (S (j + phase_len p)) w)).
  split.
  - rewrite EFlat, <- Egb. reflexivity.
  - rewrite EFlat, <- (phase_form_len p Hp), nth_middle.
    reflexivity.
Qed.
Lemma none_cx_absurd {A : Type} (x : A) (d : cost) (T : N) (P : Prop) :
  (@None A, d) = (Some x, cx T) -> P.
Proof. intros H. injection H as H1 _. discriminate H1. Qed.
Lemma delivery_cols_is_col (w : word) :
  delivery_cols w = true ->
  forallb is_col w = true.
Proof.
  induction w as [|g t IH]; [reflexivity|].
  cbn [delivery_cols forallb] in *.
  intros H. apply andb_prop in H as [Hg Ht].
  apply andb_prop in Hg as [Hg _].
  apply andb_prop in Hg as [Hg _]. rewrite Hg, (IH Ht). reflexivity.
Qed.
Lemma ddirect_exact (sg : list seg) (cols s : word) (f : N)
      (gap : nat) (renewed : bool) (sfx : word) (f2 : N) :
  sg_wf sg -> keys_big sg -> sg_live sg ->
  (forall x, In x sg -> altb (sBody x) = true) ->
  delivery_cols cols = true ->
  (forall t', s = (4%N,3%N,1%N) :: t' -> ph_notlast sg cols) ->
  nbrs1z sg s ->
  (forall g t, s = g :: t -> ph sg g = false) ->
  lin_dtick_after_seek cols s f = Some (renewed, sfx, f2) ->
  (renewed = true -> (gap + 2 <= lin_flen sg cols)%nat) ->
  CE (ddirect sg cols s f gap).
Proof.
  intros HW HK HL HAlt HCols HP HN HHead HRun HRenew.
  pose proof (lin_dtick_after_seek_flat_some
    sg cols s f renewed sfx f2 HW HK HL HP HN HHead HRun) as HFlatRun.
  assert (HRenewAvail : renewed = true ->
      (2 <= length (skipn gap (lin_flat sg cols)))%nat).
  { intro ER. specialize (HRenew ER).
    rewrite (lin_flen_flat_wf sg cols HW) in HRenew.
    rewrite length_skipn. lia. }
  destruct (lin_dtick_after_seek_strip
    (firstn gap (lin_flat sg cols))
    (skipn gap (lin_flat sg cols)) (lin_flat sg s) f
    renewed (lin_flat sg sfx) f2
    ltac:(rewrite firstn_skipn; exact HFlatRun) HRenewAvail)
    as (body & HBody & EBody).
  assert (HFlatCols : delivery_cols (lin_flat sg cols) = true)
    by (apply lin_flat_delivery_cols; assumption).
  assert (HCols' : forallb is_col
      (skipn gap (lin_flat sg cols)) = true).
  { apply forallb_skipn, delivery_cols_is_col. exact HFlatCols. }
  assert (HBodyC : fst (cdtick_after_seek
      (skipn gap (lin_flat sg cols)) (lin_flat sg s) f)
      = Some (body, f2)).
  { rewrite cdtick_after_seek_proj.
    exact (lin_dtick_after_seek_proj
      (skipn gap (lin_flat sg cols)) (lin_flat sg s) f
      renewed body f2 HBody). }
  unfold ddirect.
  exact (cdtick_after_seek_exact _ _ _ _ _ HCols' HBodyC).
Qed.
Lemma caddx_cx_of (a b : cost) :
  (exists A, a = cx A) ->
  (exists B, b = cx B) ->
  exists T, caddx a b = cx T.
Proof.
  intros (A & ->) (B & ->). exists (A+B)%N. apply caddx_cx.
Qed.
Theorem ccasc_exact :
  forall (fu : nat) (sg : list seg) (ps : atab) (w : word)
         (f : N) (st : list lsc_frame) (w' : word)
         (sg' : list seg) (ps' : atab) (f' : N) (d : cost),
  stable_guard sg w ->
  lin_guard sg w = true ->
  is_spc (nth O w d0) = false ->
  Forall frame_pos st ->
  ccasc fu sg ps w f st = (Some (w', sg', ps', f'), d) ->
  exists T, d = cx T.
Proof.
  induction fu as [|fu IH];
    intros sg ps w f st w' sg' ps' f' d HG HGuard HHead HFrames HRun.
  - cbn [ccasc] in HRun. discriminate HRun.
  - destruct st as [|fr rest].
    + cbn [ccasc] in HRun. injection HRun as <- <- <- <- <-.
      exists 0%N. reflexivity.
    + inversion HFrames as [|fr0 rest0 HFr HRest]; subst fr0 rest0.
      cbn [ccasc] in HRun. cbv beta zeta in HRun.
      destruct (lsTicks fr =? 0)%N eqn:ETicks.
      * exact (IH sg ps w f rest w' sg' ps' f' d
                 HG HGuard HHead HRest HRun).
      * destruct (seek (skipn (lsCur fr) w)) as [cols s] eqn:HSeek.
        destruct s as [|g t]; [discriminate HRun|].
        cbn [fst snd] in HRun.
        destruct (seek_split (skipn (lsCur fr) w)
                    cols (g :: t) HSeek) as (HSplit & HCols).
        assert (HCurLen : (lsCur fr <= length w)%nat).
        { pose proof (f_equal (@length bg) HSplit) as HLen.
          rewrite length_skipn, length_app in HLen.
          cbn [length] in HLen. lia. }
        unfold frame_pos in HFr.
        pose proof HG as HG0.
        destruct HG as ((HOk & HPT) & HEdges & HWf & HShape & HKeys & HPos).
        destruct (lin_bottom_take cols (g :: t) f (lsTicks fr))
          as [take|] eqn:HBottom.
        -- destruct (clin_bottom_sched_zrun (N.to_nat take)
                       (lsCur fr - (lsCur fr - 2))%nat sg
                       (skipn (lsCur fr - 2)%nat w) f
                       (lsGap fr) (lsSlot fr))
             as [[[lw2 f2]|] dz] eqn:EZ; [|discriminate HRun].
           destruct (relocate_all sg ps
                       (setsfx (lsCur fr - 2)%nat w lw2))
             as [ps2|] eqn:HRel; [|discriminate HRun].
           destruct (lin_guard_at sg ps2
                       (setsfx (lsCur fr - 2)%nat w lw2))
             eqn:HAt; [|discriminate HRun].
           destruct (ccasc fu sg ps2
                       (setsfx (lsCur fr - 2)%nat w lw2) f2
                       (lin_sched_advance fr take :: rest))
             as [o d2] eqn:ERec.
           cbn [fst snd] in HRun. injection HRun as Ho Hd.
           subst o d.
           assert (HCurEq : lsCur fr =
             ((lsCur fr - 2) + (lsCur fr - (lsCur fr - 2)))%nat)
             by lia.
           assert (HBaseLen : ((lsCur fr - 2) <= length w)%nat) by lia.
           assert (HLcLen : ((lsCur fr - (lsCur fr - 2)) <=
                  length (skipn (lsCur fr - 2)%nat w))%nat)
             by (rewrite length_skipn; lia).
           assert (HZRun : lin_bottom_sched_zrun (N.to_nat take)
                     (lsCur fr - (lsCur fr - 2))%nat sg
                     (skipn (lsCur fr - 2)%nat w) f
                     (lsGap fr) (lsSlot fr) = Some (lw2, f2)).
           { rewrite <- (clin_bottom_sched_zrun_proj (N.to_nat take)
               (lsCur fr - (lsCur fr - 2))%nat sg
               (skipn (lsCur fr - 2)%nat w) f
               (lsGap fr) (lsSlot fr)). rewrite EZ. reflexivity. }
           assert (HG2 : stable_guard sg
                     (setsfx (lsCur fr - 2)%nat w lw2)).
           { eapply lin_bottom_global_stable.
             + exact HG0.
             + exact HCurEq.
             + reflexivity.
             + exact HBaseLen.
             + exact HLcLen.
             + exact HZRun. }
           assert (HGuard2 : lin_guard sg
                     (setsfx (lsCur fr - 2)%nat w lw2) = true).
           { eapply lin_guard_at_sound;
               [exact (proj1 (proj1 HG2))|exact HAt]. }
           assert (HHead2 : is_spc
                     (nth O (setsfx (lsCur fr - 2)%nat w lw2)
                          d0) = false).
           { eapply setsfx_head_nonspc; [lia|exact HBaseLen|exact HHead]. }
           assert (HFrames2 : Forall frame_pos
             (lin_sched_advance fr take :: rest)).
           { constructor.
             + apply frame_pos_advance. unfold frame_pos. exact HFr.
             + exact HRest. }
           apply caddx_cx_of.
           ++ exists (chi dz).
              exact (CE_cx_repr dz
                (clin_bottom_sched_zrun_exact
                  (N.to_nat take)
                  (lsCur fr - (lsCur fr - 2))%nat sg
                  (skipn (lsCur fr - 2)%nat w) f
                  (lsGap fr) (lsSlot fr) lw2 f2 dz HWf EZ)).
           ++ exact (IH sg ps2
                (setsfx (lsCur fr - 2)%nat w lw2) f2
                (lin_sched_advance fr take :: rest)
                w' sg' ps' f' d2 HG2 HGuard2 HHead2 HFrames2 ERec).
        -- destruct (if Nat.ltb (lsCur fr + 2)
                          (lsCur fr + length cols)%nat
                     then match detect_phase (g :: t) O with
                          | Some pk =>
                              let take := lin_bulk_take sg w (lsCur fr)
                                 (lsCur fr + length cols)%nat pk
                                 (lsTicks fr) in
                              if (THRESH <=? take)%N
                              then match lin_bulk sg w
                                       (lsCur fr + length cols)%nat pk take with
                                   | Some (w2, sg2, t2, p2k, ek) =>
                                       Some (w2, sg2, t2, p2k, ek, take, pk)
                                   | None => None
                                   end
                              else None
                          | None => None
                          end
                     else None)
             as [[[[[[[wB sgB] tB] pB] eB] tkB] pkB]|] eqn:EBulk.
           ++ destruct (negb (lin_sched_bulk_safe fr
                                (lin_flen sg cols) pkB tkB))
                eqn:ESafe; [discriminate HRun|].
              apply negb_false_iff in ESafe.
              destruct (lin_at_safe sgB wB tB) as [wC|] eqn:EAt;
                [|discriminate HRun].
              pose proof (lin_at_safe_some sgB wB tB wC EAt) as ->.
              destruct (locate_all sgB wB) as [psB|] eqn:ELoc;
                [|discriminate HRun].
              destruct (lin_guard_at sgB psB wB) eqn:EGB;
                [|discriminate HRun].
              destruct (Nat.ltb (lsCur fr + 2)
                          (lsCur fr + length cols)%nat) eqn:ELt;
                [|discriminate EBulk].
              destruct (detect_phase (g :: t) O) as [pk|] eqn:EPh;
                [|discriminate EBulk].
              cbv beta zeta in EBulk.
              destruct ((THRESH <=?
                         lin_bulk_take sg w (lsCur fr)
                           (lsCur fr + length cols)%nat pk
                           (lsTicks fr))%N) eqn:ETh;
                [|discriminate EBulk].
              destruct (lin_bulk sg w (lsCur fr + length cols)%nat pk
                          (lin_bulk_take sg w (lsCur fr)
                             (lsCur fr + length cols)%nat pk
                             (lsTicks fr)))
                as [[[[[w2' sg2'] t2'] p2k'] ek']|] eqn:EBk;
                [|discriminate EBulk].
              inversion EBulk; subst wB sgB tB pB eB tkB pkB.
              set (take := lin_bulk_take sg w (lsCur fr)
                             (lsCur fr + length cols)%nat pk
                             (lsTicks fr)) in *.
              destruct (ccasc fu sg2' psB w2' f
                          (lin_sched_child t2' p2k' ek' pk take
                           :: lin_sched_advance fr take :: rest))
                as [o d2] eqn:ERec.
              cbn [fst snd] in HRun. injection HRun as Ho Hd.
              subst o d.
              assert (HD : detect_phase w
                             (lsCur fr + length cols)%nat = Some pk).
              { rewrite detect_phase_skipn.
                rewrite (skipn_seek_at w (lsCur fr) cols (g :: t) HSeek).
                exact EPh. }
              assert (HTgPos : (1 <= lsCur fr + length cols)%nat).
              { apply PeanoNat.Nat.ltb_lt in ELt. lia. }
              pose proof (lin_bulk_front_repr sg w
                (lsCur fr + length cols)%nat pk take
                w2' sg2' t2' p2k' ek' (conj HOk HPT) HHead HD EBk) as HFront2.
              assert (HGuard2 : lin_guard sg2' w2' = true).
              { eapply lin_guard_at_sound;
                  [exact (proj1 HFront2)|exact EGB]. }
              assert (HG2 : stable_guard sg2' w2').
              { eapply lin_bulk_stable_guarded; eauto. }
              destruct (lin_bulk_head_pos sg w
                (lsCur fr + length cols)%nat pk take
                w2' sg2' t2' p2k' ek' HTgPos HHead HD EBk)
                as (HNhPos & HHead2).
              assert (HThreshLe : (THRESH <= take)%N)
                by (apply N.leb_le; exact ETh).
              assert (HFrames2 : Forall frame_pos
                (lin_sched_child t2' p2k' ek' pk take
                 :: lin_sched_advance fr take :: rest)).
              { constructor.
                + unfold frame_pos, lin_sched_child. cbn [lsCur].
                  destruct (Nat.eqb (N.to_nat ((pk + take) / 28)) O)
                    eqn:HFull.
                  * destruct (lin_bulk_checks sg w
                      (lsCur fr + length cols)%nat pk take _ EBk)
                      as (gb & HWat & _ & _ & _ & _).
                    destruct (lin_bulk_partial_out sg w
                      (lsCur fr + length cols)%nat pk take
                      w2' sg2' t2' p2k' ek' gb HFull EBk HWat)
                      as (_ & Hnh & _ & _ & _). lia.
                  * assert (HCross : (lsCur fr <= t2')%nat).
                    { eapply lin_bulk_take_lands_after_cursor.
                      - exact HWf.
                      - exact HOk.
                      - exact (stable_altb sg w HG0).
                      - exact HHead.
                      - exact HSeek.
                      - reflexivity.
                      - exact HD.
                      - reflexivity.
                      - exact HThreshLe.
                      - exact HFull.
                      - exact EBk.
                      - exact (proj1 (proj2 (proj2 HG2))). }
                    lia.
                + constructor.
                  * apply frame_pos_advance.
                    unfold frame_pos. exact HFr.
                  * exact HRest. }
              apply caddx_cx_of.
              ** unfold dbulkc.
                 destruct (Nat.eqb (N.to_nat ((pk + take) / 28)) O).
                 --- unfold dbulkp. eexists. reflexivity.
                 --- unfold dbulkn. eexists. reflexivity.
              ** exact (IH sg2' psB w2' f
                   (lin_sched_child t2' p2k' ek' pk take
                    :: lin_sched_advance fr take :: rest)
                   w' sg' ps' f' d2 HG2 HGuard2 HHead2 HFrames2 ERec).
           ++ destruct (lin_dtick_after_seek cols (g :: t) f)
                as [[[renewed sfx] f2]|] eqn:EDt; [|discriminate HRun].
              assert (HM : ph_margins sg w)
                by (exact (lguard_margins sg w HGuard)).
              assert (HN : ph_nbrs sg w)
                by (exact (margins_edges_nbrs
                            sg w HM HEdges)).
              assert (HN1 : nbrs1z sg w)
                by (exact (nbrs_nbrs1z sg w HN)).
              assert (HNCur : nbrs1z sg (skipn (lsCur fr) w)).
              { apply (nbrs1z_app_r sg (firstn (lsCur fr) w)
                         (skipn (lsCur fr) w)).
                rewrite firstn_skipn. exact HN1. }
              assert (HNS : nbrs1z sg (g :: t)).
              { apply (nbrs1z_app_r sg cols (g :: t)).
                rewrite <- HSplit. exact HNCur. }
              assert (HNotLast : forall t',
                g :: t = (4%N,3%N,1%N) :: t' -> ph_notlast sg cols).
              { intros t' E. injection E as Eg Et. subst g t.
                pose proof (nbrs1z_seek_notlast sg
                  (skipn (lsCur fr) w) (4%N,3%N,1%N) t'
                  HNCur ltac:(rewrite HSeek; reflexivity)
                  ltac:(unfold is_spc; reflexivity)
                  ltac:(cbn [gZ]; lia)) as H.
                rewrite HSeek in H. cbn [fst] in H. exact H. }
              assert (HNonPh : forall gh u,
                g :: t = gh :: u -> ph sg gh = false).
              { intros gh u E. injection E as <- <-.
                exact (nbrs1z_seek_snd_head sg
                  (skipn (lsCur fr) w) g t HNCur
                  ltac:(rewrite HSeek; reflexivity)). }
              destruct renewed eqn:ERenew;
                [ destruct (negb (Nat.leb (lsGap fr + 2)
                      (lin_flen sg cols))) eqn:HGap;
                    [discriminate HRun|];
                  apply negb_false_iff in HGap;
                  assert (HRenew : true = true ->
                    (lsGap fr + 2 <= lin_flen sg cols)%nat)
                    by (intros _; apply PeanoNat.Nat.leb_le; exact HGap)
                | assert (HRenew : false = true ->
                    (lsGap fr + 2 <= lin_flen sg cols)%nat)
                    by discriminate ].
              all: destruct (if Nat.eqb (lsCur fr) O then Some sfx
                             else lin_join_safe sg
                                    (firstn (lsCur fr) w) sfx)
                     as [w2|] eqn:HJoin; [|discriminate HRun].
              all: destruct (if lin_same_length w w2
                             then Some ps else relocate_all sg ps w2)
                     as [ps2|] eqn:HRel; [|discriminate HRun].
              all: destruct (lin_guard_at sg ps2 w2) eqn:HAt;
                   [|discriminate HRun].
              all: destruct (ccasc fu sg ps2 w2 f2
                     (lin_sched_advance_one fr :: rest))
                     as [o d2] eqn:ERec.
              all: cbn [fst snd] in HRun.
              all: injection HRun as Ho Hd; subst o d.
              all: rewrite lin_sched_advance_one_eq in ERec.
              all: assert (HG2 : stable_guard sg w2)
                by (eapply lin_direct_stable; eauto).
              all: assert (HGuard2 : lin_guard sg w2 = true)
                by (eapply lin_guard_at_sound;
                    [exact (proj1 (proj1 HG2))|exact HAt]).
              all: assert (EW2 : w2 = firstn (lsCur fr) w ++ sfx)
                by (destruct (Nat.eqb (lsCur fr) O) eqn:HCur0;
                    [apply PeanoNat.Nat.eqb_eq in HCur0; lia
                    | exact (lin_join_safe_some
                        sg (firstn (lsCur fr) w) sfx w2 HJoin)]).
              all: assert (HHead2 : is_spc (nth O w2 d0) = false)
                by (exact (prefix_replace_head_nonspc
                    w w2 (lsCur fr) sfx ltac:(lia) HCurLen EW2 HHead)).
              all: assert (HFrames2 : Forall frame_pos
                (lin_sched_advance fr 1 :: rest))
                by (constructor;
                    [apply frame_pos_advance;
                     unfold frame_pos; exact HFr|exact HRest]).
              all: pose proof (@ddirect_exact sg cols (g :: t) f
                (lsGap fr) _ sfx f2 HWf HKeys
                (stable_guard_live sg w HG0)
                (stable_altb sg w HG0) HCols HNotLast HNS HNonPh
                EDt HRenew) as HDE.
              all: assert (HDirect : exists T,
                ddirect sg cols (g :: t) f (lsGap fr) = cx T)
                by (exists (chi
                      (ddirect sg cols (g :: t) f (lsGap fr)));
                    exact (CE_cx_repr _ HDE)).
              all: exact (caddx_cx_of _ _ HDirect
                (IH sg ps2 w2 f2 (lin_sched_advance fr 1 :: rest)
                   w' sg' ps' f' d2 HG2 HGuard2 HHead2 HFrames2 ERec)).
Qed.
Theorem ccasc_work :
  forall (fu : nat) (sg : list seg) (ps : atab) (w : word)
         (f : N) (st : list lsc_frame) (w' : word)
         (sg' : list seg) (ps' : atab) (f' T : N),
  stable_guard sg w ->
  lin_guard sg w = true ->
  is_spc (nth O w d0) = false ->
  Forall frame_pos st ->
  ccasc fu sg ps w f st = (Some (w', sg', ps', f'), cx T) ->
  scheduled_workc T st sg w f sg' w' f'
  /\ stable_guard sg' w'
  /\ lin_guard sg' w' = true
  /\ is_spc (nth O w' d0) = false.
Proof.
  induction fu as [|fu IH];
    intros sg ps w f st w' sg' ps' f' T HG HGuard HHead HFrames HRun.
  - cbn [ccasc] in HRun. exact (none_cx_absurd _ _ _ _ HRun).
  - destruct st as [|fr rest].
    + cbn [ccasc] in HRun.
      pose proof (f_equal fst HRun) as HR1; cbn [fst] in HR1.
      pose proof (f_equal snd HRun) as HR2; cbn [snd] in HR2.
      injection HR1 as <- <- <- <-.
      assert (ET : T = 0%N)
        by (unfold czero, cx in HR2; injection HR2 as E _; lia).
      subst T.
      split; [constructor|]. split; [exact HG|]. split; assumption.
    + inversion HFrames as [|fr0 rest0 HFr HRest]; subst fr0 rest0.
      cbn [ccasc] in HRun. cbv beta zeta in HRun.
      destruct (lsTicks fr =? 0)%N eqn:ETicks.
      * destruct (IH sg ps w f rest w' sg' ps' f' T
                     HG HGuard HHead HRest HRun)
          as (HWork & HG' & HGuard' & HHead').
        split.
        -- apply scheduled_workc_zero;
             [apply N.eqb_eq; exact ETicks|exact HWork].
        -- split; [exact HG'|]. split; assumption.
      * destruct (seek (skipn (lsCur fr) w)) as [cols s] eqn:HSeek.
        destruct s as [|g t]; [exact (none_cx_absurd _ _ _ _ HRun)|].
        cbn [fst snd] in HRun.
        pose proof (LineageGuard_seek_split (skipn (lsCur fr) w)) as HSplit.
        rewrite HSeek in HSplit. cbn [fst snd] in HSplit.
        assert (HCurLen : (lsCur fr <= length w)%nat).
        { pose proof (f_equal (@length bg) HSplit) as HLen.
          rewrite length_skipn, length_app in HLen.
          cbn [length] in HLen. lia. }
        unfold frame_pos in HFr.
        pose proof HG as HG0.
        destruct HG as ((HOk & HPT) & HEdges & HWf & HShape & HKeys & HPos).
        destruct (lin_bottom_take cols (g :: t) f (lsTicks fr))
          as [take|] eqn:HBottom.
        --
           destruct (clin_bottom_sched_zrun (N.to_nat take)
                       (lsCur fr - (lsCur fr - 2))%nat sg
                       (skipn (lsCur fr - 2)%nat w) f
                       (lsGap fr) (lsSlot fr))
             as [[[lw2 f2]|] dz] eqn:EZ;
             [|exact (none_cx_absurd _ _ _ _ HRun)].
           destruct (relocate_all sg ps
                       (setsfx (lsCur fr - 2)%nat w lw2))
             as [ps2|] eqn:HRel; [|exact (none_cx_absurd _ _ _ _ HRun)].
           destruct (lin_guard_at sg ps2
                       (setsfx (lsCur fr - 2)%nat w lw2))
             eqn:HAt; [|exact (none_cx_absurd _ _ _ _ HRun)].
           destruct (ccasc fu sg ps2
                       (setsfx (lsCur fr - 2)%nat w lw2) f2
                       (lin_sched_advance fr take :: rest))
             as [o d] eqn:ERec.
           cbn [fst snd] in HRun.
           injection HRun as HF HS. subst o.
           destruct (caddx_cx_inv _ _ _ HS) as (T1 & T2 & EZ1 & ED2 & ET).
           subst d.
           assert (HCurEq : lsCur fr
             = ((lsCur fr - 2) + (lsCur fr - (lsCur fr - 2)))%nat)
             by lia.
           assert (HBaseLen : ((lsCur fr - 2) <= length w)%nat) by lia.
           assert (HLcLen : ((lsCur fr - (lsCur fr - 2))
                             <= length (skipn (lsCur fr - 2)%nat w))%nat)
             by (rewrite length_skipn; lia).
           assert (HTake : (take <= lsTicks fr)%N)
             by (eapply lin_bottom_take_le; exact HBottom).
           assert (HZRun : lin_bottom_sched_zrun (N.to_nat take)
                     (lsCur fr - (lsCur fr - 2))%nat sg
                     (skipn (lsCur fr - 2)%nat w) f
                     (lsGap fr) (lsSlot fr) = Some (lw2, f2)).
           { rewrite <- (clin_bottom_sched_zrun_proj (N.to_nat take)
               (lsCur fr - (lsCur fr - 2))%nat sg
               (skipn (lsCur fr - 2)%nat w) f (lsGap fr) (lsSlot fr)).
             rewrite EZ. reflexivity. }
           assert (HG2 : stable_guard sg
                     (setsfx (lsCur fr - 2)%nat w lw2)).
           { eapply lin_bottom_global_stable.
             + exact HG0.
             + exact HCurEq.
             + reflexivity.
             + exact HBaseLen.
             + exact HLcLen.
             + exact HZRun. }
           assert (HGuard2 : lin_guard sg
                     (setsfx (lsCur fr - 2)%nat w lw2) = true).
           { eapply lin_guard_at_sound;
               [exact (proj1 (proj1 HG2))|exact HAt]. }
           assert (HHead2 : is_spc
                     (nth O (setsfx (lsCur fr - 2)%nat w lw2)
                          d0) = false).
           { eapply setsfx_head_nonspc;
               [lia|exact HBaseLen|exact HHead]. }
           assert (HFrames2 : Forall frame_pos
             (lin_sched_advance fr take :: rest)).
           { constructor.
             + apply frame_pos_advance. unfold frame_pos. exact HFr.
             + exact HRest. }
           destruct (IH sg ps2
                       (setsfx (lsCur fr - 2)%nat w lw2) f2
                       (lin_sched_advance fr take :: rest)
                       w' sg' ps' f' T2 HG2 HGuard2 HHead2 HFrames2 ERec)
             as (HWork & HG' & HGuard' & HHead').
           subst T.
           split; [|split; [exact HG'|]; split; assumption].
           refine (casc_ladder_step fr take (lsCur fr - 2)%nat
                     (lsCur fr - (lsCur fr - 2))%nat rest sg w f
                     lw2 f2 (setsfx (lsCur fr - 2)%nat w lw2)
                     sg' w' f' T1 T2 HWf HCurEq HBaseLen HLcLen HTake
                     _ eq_refl HWork).
           rewrite EZ, EZ1. reflexivity.
        -- destruct (if Nat.ltb (lsCur fr + 2)
                          (lsCur fr + length cols)%nat
                     then match detect_phase (g :: t) O with
                          | Some pk =>
                              let take := lin_bulk_take sg w (lsCur fr)
                                 (lsCur fr + length cols)%nat pk
                                 (lsTicks fr) in
                              if (THRESH <=? take)%N
                              then match lin_bulk sg w
                                       (lsCur fr + length cols)%nat pk take with
                                   | Some (w2, sg2, t2, p2k, ek) =>
                                       Some (w2, sg2, t2, p2k, ek, take, pk)
                                   | None => None
                                   end
                              else None
                          | None => None
                          end
                     else None)
             as [[[[[[[wB sgB] tB] pB] eB] tkB] pkB]|] eqn:EBulk.
           ++
              destruct (negb (lin_sched_bulk_safe fr
                                (lin_flen sg cols) pkB tkB))
                eqn:ESafe; [exact (none_cx_absurd _ _ _ _ HRun)|].
              apply negb_false_iff in ESafe.
              destruct (lin_at_safe sgB wB tB) as [wC|] eqn:EAt;
                [|exact (none_cx_absurd _ _ _ _ HRun)].
              pose proof (lin_at_safe_some sgB wB tB wC EAt) as ->.
              destruct (locate_all sgB wB) as [psB|] eqn:ELoc;
                [|exact (none_cx_absurd _ _ _ _ HRun)].
              destruct (lin_guard_at sgB psB wB) eqn:EGB;
                [|exact (none_cx_absurd _ _ _ _ HRun)].
              destruct (Nat.ltb (lsCur fr + 2)
                          (lsCur fr + length cols)%nat) eqn:ELt;
                [|discriminate].
              destruct (detect_phase (g :: t) O) as [pk|] eqn:EPh;
                [|discriminate].
              cbv beta zeta in EBulk.
              destruct ((THRESH <=?
                         lin_bulk_take sg w (lsCur fr)
                           (lsCur fr + length cols)%nat pk
                           (lsTicks fr))%N) eqn:ETh;
                [|discriminate].
              destruct (lin_bulk sg w (lsCur fr + length cols)%nat pk
                          (lin_bulk_take sg w (lsCur fr)
                             (lsCur fr + length cols)%nat pk
                             (lsTicks fr)))
                as [[[[[w2' sg2'] t2'] p2k'] ek']|] eqn:EBk;
                [|discriminate].
              inversion EBulk; subst wB sgB tB pB eB tkB pkB.
              destruct (ccasc fu sg2' psB w2' f
                          (lin_sched_child t2' p2k' ek' pk
                             (lin_bulk_take sg w (lsCur fr)
                                (lsCur fr + length cols)%nat pk
                                (lsTicks fr))
                           :: lin_sched_advance fr
                                (lin_bulk_take sg w (lsCur fr)
                                   (lsCur fr + length cols)%nat pk
                                   (lsTicks fr)) :: rest))
                as [o d] eqn:ERec.
              cbn [fst snd] in HRun.
              injection HRun as HF HS. subst o.
              destruct (caddx_cx_inv _ _ _ HS)
                as (D & T2 & EDB & ED2 & ET).
              subst d.
              set (take := lin_bulk_take sg w (lsCur fr)
                             (lsCur fr + length cols)%nat pk
                             (lsTicks fr)) in *.
              assert (HD : detect_phase w
                             (lsCur fr + length cols)%nat = Some pk).
              { rewrite detect_phase_skipn.
                rewrite (skipn_seek_at w (lsCur fr) cols (g :: t) HSeek).
                exact EPh. }
              assert (HTgPos : (1 <= lsCur fr + length cols)%nat).
              { apply PeanoNat.Nat.ltb_lt in ELt. lia. }
              pose proof (lin_bulk_front_repr sg w
                (lsCur fr + length cols)%nat pk take w2' sg2' t2' p2k' ek'
                (conj HOk HPT) HHead HD EBk) as HFront2.
              assert (HGuard2 : lin_guard sg2' w2' = true).
              { eapply lin_guard_at_sound;
                  [exact (proj1 HFront2)|exact EGB]. }
              assert (HG2 : stable_guard sg2' w2').
              { eapply lin_bulk_stable_guarded; eauto. }
              destruct (lin_bulk_head_pos sg w
                (lsCur fr + length cols)%nat pk take w2' sg2' t2' p2k' ek'
                HTgPos HHead HD EBk) as (HNhPos & HHead2).
              assert (HTake : (take <= lsTicks fr)%N)
                by (unfold take; apply lin_bulk_take_le).
              assert (HThreshLe : (THRESH <= take)%N)
                by (apply N.leb_le; exact ETh).
              assert (HFrames2 : Forall frame_pos
                (lin_sched_child t2' p2k' ek' pk take
                 :: lin_sched_advance fr take :: rest)).
              { constructor.
                + unfold frame_pos, lin_sched_child.
                  cbn [lsCur].
                  destruct (Nat.eqb (N.to_nat ((pk + take) / 28)) O)
                    eqn:HFull.
                  * destruct (lin_bulk_checks sg w
                      (lsCur fr + length cols)%nat pk take _ EBk)
                      as (gb & HWat & _ & _ & _ & _).
                    destruct (lin_bulk_partial_out sg w
                      (lsCur fr + length cols)%nat pk take
                      w2' sg2' t2' p2k' ek' gb HFull EBk HWat)
                      as (_ & Hnh & _ & _ & _).
                    lia.
                  * assert (HCross : (lsCur fr <= t2')%nat).
                    { eapply lin_bulk_take_lands_after_cursor.
                      - exact HWf.
                      - exact HOk.
                      - exact (stable_altb sg w HG0).
                      - exact HHead.
                      - exact HSeek.
                      - reflexivity.
                      - exact HD.
                      - reflexivity.
                      - exact HThreshLe.
                      - exact HFull.
                      - exact EBk.
                      - exact (proj1 (proj2 (proj2 HG2))). }
                    lia.
                + constructor.
                  * apply frame_pos_advance.
                    unfold frame_pos. exact HFr.
                  * exact HRest. }
              destruct (IH sg2' psB w2' f
                          (lin_sched_child t2' p2k' ek' pk take
                           :: lin_sched_advance fr take :: rest)
                          w' sg' ps' f' T2 HG2 HGuard2 HHead2 HFrames2 ERec)
                as (HWork & HG' & HGuard' & HHead').
              subst T.
              split; [|split; [exact HG'|]; split; assumption].
              unfold dbulkc in EDB.
              destruct (Nat.eqb (N.to_nat ((pk + take) / 28)) O) eqn:HFull.
              **
                 destruct (flat_site_at sg w (lsCur fr + length cols)%nat
                             pk take _ HD EBk) as (c_0 & POST0 & ESite & EC0).
                 rewrite (skipn_seek_at w (lsCur fr) cols (g :: t) HSeek)
                   in ESite, EC0.
                 refine (casc_bulk_partial_step fr rest sg w f
                           cols (g :: t) (lsCur fr + length cols)%nat
                           pk take w2' sg2' t2' p2k' ek' sg' w' f'
                           POST0 c_0 D T2 HWf HSeek eq_refl HD HFull EBk
                           HTake ESite _ HWork).
                 unfold dbulkp in EDB. apply cx_inj in EDB.
                 rewrite <- EDB, <- EC0. reflexivity.
              **
                 destruct (detect_phase_form w
                             (lsCur fr + length cols)%nat pk HD) as (Hp & _).
                 destruct (lin_bulk_cursor_layout sg w (lsCur fr)
                             cols (g :: t) (lsCur fr + length cols)%nat
                             pk take w2' sg2' t2' p2k' ek'
                             HWf HOk (stable_altb sg w HG0) HHead HSeek
                             eq_refl HD HFull EBk
                             (proj1 (proj2 (proj2 HG2))))
                   as (PRE0 & POST0 & c_0 & cs0 & b0 & HLay1 & HLay2 & _ & _
                       & _ & _ & _ & HLayL & _ & _ & _ & HRem & _).
                 assert (HCross : (lsCur fr <= t2')%nat).
                 { eapply lin_bulk_take_lands_after_cursor.
                   - exact HWf.
                   - exact HOk.
                   - exact (stable_altb sg w HG0).
                   - exact HHead.
                   - exact HSeek.
                   - reflexivity.
                   - exact HD.
                   - reflexivity.
                   - exact HThreshLe.
                   - exact HFull.
                   - exact EBk.
                   - exact (proj1 (proj2 (proj2 HG2))). }
                 unfold dbulkn in EDB. cbv zeta in EDB.
                 rewrite <- (layout_levels sg _ PRE0 c_0 cs0 _
                              HLay1 HLayL) in EDB.
                 rewrite <- (layout_base sg (g :: t) POST0
                              pk b0 Hp HLay2) in EDB.
                 apply cx_inj in EDB. symmetry in EDB. subst D.
                 rewrite <- HRem.
                 exact (casc_bulk_net_step fr rest sg w f
                           cols (g :: t) (lsCur fr + length cols)%nat
                           pk take w2' sg2' t2' p2k' ek' sg' w' f'
                           PRE0 POST0 c_0 b0 T2 cs0
                           HWf HOk (stable_altb sg w HG0) HHead HSeek
                           eq_refl HD HFull EBk
                           (proj1 (proj2 (proj2 HG2))) HTake ESafe HCross
                           HLay1 HLay2 HLayL HWork).
           ++
              destruct (lin_dtick_after_seek cols (g :: t) f)
                as [[[renewed sfx] f2]|] eqn:EDt;
                [|exact (none_cx_absurd _ _ _ _ HRun)].
              assert (HM : ph_margins sg w)
                by (exact (lguard_margins sg w HGuard)).
              assert (HN : ph_nbrs sg w)
                by (exact (margins_edges_nbrs sg w HM HEdges)).
              assert (HN1 : nbrs1z sg w)
                by (exact (nbrs_nbrs1z sg w HN)).
              assert (HNCur : nbrs1z sg (skipn (lsCur fr) w)).
              { apply (nbrs1z_app_r sg (firstn (lsCur fr) w)
                         (skipn (lsCur fr) w)).
                rewrite firstn_skipn. exact HN1. }
              assert (HNS : nbrs1z sg (g :: t)).
              { apply (nbrs1z_app_r sg cols (g :: t)).
                rewrite <- HSplit. exact HNCur. }
              assert (HNotLast : forall t',
                g :: t = (4%N,3%N,1%N) :: t' -> ph_notlast sg cols).
              { intros t' E. injection E as Eg Et. subst g t.
                pose proof (nbrs1z_seek_notlast sg
                  (skipn (lsCur fr) w) (4%N,3%N,1%N) t'
                  HNCur ltac:(rewrite HSeek; reflexivity)
                  ltac:(unfold is_spc; reflexivity)
                  ltac:(cbn [gZ]; lia)) as H.
                rewrite HSeek in H. cbn [fst] in H. exact H. }
              assert (HNonPh : forall gh u,
                g :: t = gh :: u -> ph sg gh = false).
              { intros gh u E. injection E as <- <-.
                exact (nbrs1z_seek_snd_head sg
                  (skipn (lsCur fr) w) g t HNCur
                  ltac:(rewrite HSeek; reflexivity)). }
              destruct renewed eqn:ERenew;
                [ destruct (negb (Nat.leb (lsGap fr + 2)
                      (lin_flen sg cols))) eqn:HGap;
                    [exact (none_cx_absurd _ _ _ _ HRun)|];
                  apply negb_false_iff in HGap;
                  assert (HRenew : true = true ->
                    (lsGap fr + 2 <= lin_flen sg cols)%nat)
                    by (intros _; apply PeanoNat.Nat.leb_le; exact HGap)
                | assert (HRenew : false = true ->
                    (lsGap fr + 2 <= lin_flen sg cols)%nat)
                    by discriminate ].
              all: destruct (if Nat.eqb (lsCur fr) O then Some sfx
                             else lin_join_safe sg
                                    (firstn (lsCur fr) w) sfx)
                     as [w2|] eqn:HJoin;
                   [|exact (none_cx_absurd _ _ _ _ HRun)].
              all: destruct (if lin_same_length w w2
                             then Some ps else relocate_all sg ps w2)
                     as [ps2|] eqn:HRel;
                   [|exact (none_cx_absurd _ _ _ _ HRun)].
              all: destruct (lin_guard_at sg ps2 w2) eqn:HAt;
                   [|exact (none_cx_absurd _ _ _ _ HRun)].
              all: destruct (ccasc fu sg ps2 w2 f2
                     (lin_sched_advance_one fr :: rest)) as [o d] eqn:ERec.
              all: cbn [fst snd] in HRun.
              all: injection HRun as HF HS; subst o.
              all: destruct (caddx_cx_inv _ _ _ HS)
                     as (K & T2 & EDD & ED2 & ET); subst d.
              all: rewrite lin_sched_advance_one_eq in ERec.
              all: assert (HG2 : stable_guard sg w2)
                by (eapply lin_direct_stable; eauto).
              all: assert (HGuard2 : lin_guard sg w2 = true)
                by (eapply lin_guard_at_sound;
                    [exact (proj1 (proj1 HG2))|exact HAt]).
              all: assert (EW2 : w2 = firstn (lsCur fr) w ++ sfx)
                by (destruct (Nat.eqb (lsCur fr) O) eqn:HCur0;
                    [apply PeanoNat.Nat.eqb_eq in HCur0; lia
                    | exact (lin_join_safe_some
                        sg (firstn (lsCur fr) w) sfx w2 HJoin)]).
              all: assert (HHead2 : is_spc (nth O w2 d0) = false)
                by (exact (prefix_replace_head_nonspc
                    w w2 (lsCur fr) sfx ltac:(lia) HCurLen EW2 HHead)).
              all: assert (HFrames2 : Forall frame_pos
                (lin_sched_advance fr 1 :: rest))
                by (constructor;
                    [apply frame_pos_advance;
                     unfold frame_pos; exact HFr
                    |exact HRest]).
              all: destruct (IH sg ps2 w2 f2
                     (lin_sched_advance fr 1 :: rest)
                     w' sg' ps' f' T2 HG2 HGuard2 HHead2 HFrames2 ERec)
                   as (HWork & HG' & HGuard' & HHead').
              all: rewrite <- lin_sched_advance_one_eq in HWork.
              all: subst T.
              all: unfold ddirect in EDD.
              all: split; [|split; [exact HG'|]; split; assumption].
              all: refine (casc_direct_flat_step fr rest sg w f
                     cols (g :: t) _ sfx f2 w2 sg' w' f' K T2
                     HWf HKeys (stable_guard_live sg w HG0)
                     HCurLen ltac:(apply N.eqb_neq; exact ETicks)
                     HSeek ltac:(discriminate) HNotLast HNS HNonPh
                     EDt HRenew HJoin _ HWork).
              all: rewrite EDD; apply cin_cx.
Qed.
Corollary lin_casc_safe_at_workc_exists :
  forall (fu : nat) (sg : list seg) (ps : atab) (w : word)
         (f : N) (st : list lsc_frame) (w' : word)
         (sg' : list seg) (ps' : atab) (f' : N),
  stable_guard sg w ->
  lin_guard sg w = true ->
  is_spc (nth O w d0) = false ->
  Forall frame_pos st ->
  lin_casc_safe_at fu sg ps w f st = Some (w', sg', ps', f') ->
  exists T,
    scheduled_workc T st sg w f sg' w' f'
    /\ stable_guard sg' w'
    /\ lin_guard sg' w' = true
    /\ is_spc (nth O w' d0) = false.
Proof.
  intros fu sg ps w f st w' sg' ps' f' HG HGuard HHead HFrames HRun.
  destruct (ccasc fu sg ps w f st) as [o d] eqn:EC.
  assert (Ho : o = Some (w', sg', ps', f')).
  { pose proof (ccasc_proj fu sg ps w f st) as HP.
    rewrite EC in HP. cbn [fst] in HP. rewrite HRun in HP. exact HP. }
  subst o.
  destruct (ccasc_exact fu sg ps w f st w' sg' ps' f' d
              HG HGuard HHead HFrames EC) as (T & Hd).
  exists T. apply (ccasc_work fu sg ps w f st w' sg' ps' f' T
                    HG HGuard HHead HFrames).
  rewrite <- Hd. exact EC.
Qed.
Corollary ccasc_frame_one :
  forall (fu : nat) (sg : list seg) (ps : atab) (w : word)
         (f : N) (fr : lsc_frame) (w' : word)
         (sg' : list seg) (ps' : atab) (f' T : N),
  stable_guard sg w ->
  lin_guard sg w = true ->
  is_spc (nth O w d0) = false ->
  frame_pos fr ->
  ccasc fu sg ps w f [fr] = (Some (w', sg', ps', f'), cx T) ->
  scheduled_framec T fr sg w f sg' w' f'.
Proof.
  intros fu sg ps w f fr w' sg' ps' f' T HG HGuard HHead HFr HR.
  destruct (ccasc_work fu sg ps w f [fr] w' sg' ps' f' T
              HG HGuard HHead (Forall_cons _ HFr (Forall_nil _)) HR)
    as (HW & _).
  exact (scheduled_workc_one_inv _ _ _ _ _ _ _ _ HW).
Qed.
Set Warnings "-require-in-module".
Local Open Scope N_scope.
Opaque FLAT_ROUND_FUEL LROUND_FUEL LROUND_CHUNKS
       CFUEL TRIES.
Definition fcc (sg : list seg) (w : word) : N :=
  ccolcost (lin_flat sg w).
Lemma cmeas_fcc (sg : list seg) (w : word) (f : N) :
  cmeas sg w f = fcc sg w + 2 * f.
Proof. reflexivity. Qed.
Lemma fcc_app (sg : list seg) (a b : word) :
  fcc sg (a ++ b) = fcc sg a + fcc sg b.
Proof. unfold fcc. rewrite lin_flat_app_c. apply ccolcost_app. Qed.
Lemma fcc_cons (sg : list seg) (g : bg) (w : word) :
  fcc sg (g :: w) = fcc sg [g] + fcc sg w.
Proof. exact (fcc_app sg [g] w). Qed.
Lemma fcc_split (sg : list seg) (w : list (N * N * N)%type) (j : nat) :
  fcc sg w = fcc sg (firstn j w) + fcc sg (skipn j w).
Proof. rewrite <- fcc_app, firstn_skipn. reflexivity. Qed.
Lemma fcc_master (sg : list seg) (X : N) (u : word) :
  fcc sg ((2,2,X)%N :: u) = 10 * X + fcc sg u.
Proof.
  unfold fcc. rewrite flat_master, ccolcost_cons.
  unfold ccg. cbn [gO gC]. lia.
Qed.
Lemma fcc_slice (sg : list seg) (w : word) :
  fcc sg (lin_normalize_slice sg w) = fcc sg w.
Proof.
  unfold fcc, lin_normalize_slice. exact (lin_ccolcost_lnf sg w).
Qed.
Theorem fcc_norm_at (sg : list seg) (w : word) (c : nat) :
  fcc sg (lin_normalize_at sg w c) = fcc sg w.
Proof.
  unfold lin_normalize_at.
  destruct (Nat.eqb c O); [reflexivity|].
  destruct (lin_nadj_span 6 sg (skipn (c - 2)%nat w)); [reflexivity|].
  rewrite (LineageSplice_lin_split_at_spec (c - 2)%nat w).
  cbv beta iota zeta.
  rewrite (LineageSplice_lin_split_at_spec 6%nat (skipn (c - 2)%nat w)).
  cbv beta iota zeta.
  rewrite !fcc_app, fcc_slice, <- fcc_app, firstn_skipn, <- fcc_app,
          firstn_skipn.
  reflexivity.
Qed.
Definition njoinb (sg : list seg) (pre sfx : word) : word :=
  lin_normalize_slice sg (pre ++ firstn (6 - length pre)%nat sfx)
    ++ skipn (6 - length pre)%nat sfx.
Lemma fcc_njoinb (sg : list seg) (pre sfx : word) :
  fcc sg (njoinb sg pre sfx) = fcc sg pre + fcc sg sfx.
Proof.
  unfold njoinb.
  rewrite fcc_app, fcc_slice, fcc_app, <- N.add_assoc, <- fcc_app,
          firstn_skipn.
  reflexivity.
Qed.
Lemma njoin_base (sg : list seg) (pre sfx : word) :
  (length pre <= 2)%nat ->
  lin_normalize_join sg pre sfx = njoinb sg pre sfx.
Proof.
  intros HL.
  destruct pre as [|g [|g1 [|g2 t]]];
    [| | |cbn [length] in HL; lia];
    unfold njoinb; cbn [lin_normalize_join];
    rewrite LineageSplice_lin_split_at_spec; reflexivity.
Qed.
Lemma njoin_cons (sg : list seg) (g g1 g2 : bg) (t sfx : word) :
  lin_normalize_join sg (g :: g1 :: g2 :: t) sfx
  = g :: lin_normalize_join sg (g1 :: g2 :: t) sfx.
Proof. reflexivity. Qed.
Theorem fcc_norm_join (sg : list seg) :
  forall (pre sfx : word),
    fcc sg (lin_normalize_join sg pre sfx) = fcc sg pre + fcc sg sfx.
Proof.
  intros pre. induction pre as [|g pre IH]; intros sfx.
  - rewrite njoin_base by (cbn [length]; lia). apply fcc_njoinb.
  - destruct pre as [|g1 [|g2 t]].
    + rewrite njoin_base by (cbn [length]; lia). apply fcc_njoinb.
    + rewrite njoin_base by (cbn [length]; lia). apply fcc_njoinb.
    + rewrite njoin_cons, fcc_cons, IH, (fcc_cons sg g (g1 :: g2 :: t)).
      lia.
Qed.
Theorem micro_front (sg : list seg) (cw : word) (f : N) (h : nat)
        (fw : word) (ff : N) (cw2 : word) (f2 : N) (i : nat) :
  stable_guard sg cw ->
  lin_guard sg cw = true ->
  front_gate cw f = Some (ROk fw ff) ->
  splice_call sg (front_gate cw f) cw f h = (ROk cw2 f2, i) ->
  cmeas sg cw f <= cmeas sg cw2 f2 + 2.
Proof.
  intros HG HGuard HFG HRun.
  destruct HG as ((HOk & HPT) & HE & HW & HShape & HK & HP).
  assert (HM : ph_margins sg cw)
    by (exact (lguard_margins sg cw HGuard)).
  assert (HN : ph_nbrs sg cw)
    by (exact (margins_edges_nbrs sg cw HM HE)).
  assert (HL : sg_live sg)
    by (exact (sg_shape_live sg HW HShape)).
  unfold splice_call, step_after_front_with_guard in HRun.
  rewrite HFG in HRun. cbv beta iota in HRun.
  injection HRun as <- <- <-.
  assert (EFR : first_rule front_rules cw f
                = Some (ROk fw ff)).
  { unfold front_gate in HFG.
    destruct (lin_front_possible cw); [exact HFG|discriminate]. }
  assert (EFF : first_rule front_rules (lin_flat sg cw) f
                = Some (ROk (lin_flat sg fw) ff)).
  { rewrite (first_rule_flat_tag sg cw f HW HK HL HM HN), EFR.
    reflexivity. }
  pose proof (front_grow (lin_flat sg cw) f (lin_flat sg fw) ff EFF)
    as HGr.
  unfold cmeas, gmeas in HGr |- *.
  change (lin_normalize_at sg fw O) with fw.
  exact HGr.
Qed.
Theorem direct_step_kernel (sg : list seg) (J : N) (t : word)
        (f : N) (h : nat) (s j : nat) (cw2 : word) (f2 : N)
        (ir : nat) :
  stable_guard sg ((2,2,J)%N :: t) ->
  lin_guard sg ((2,2,J)%N :: t) = true ->
  front_gate ((2,2,J)%N :: t) f = None ->
  s = (if Nat.ltb h 1 then 1%nat else h) ->
  find_active ((2,2,J)%N :: t) s = Some j ->
  splice_call sg None ((2,2,J)%N :: t) f h = (ROk cw2 f2, ir) ->
  exists (hf : nat) (W2 : word) (i2 : nat),
    step (lin_flat sg ((2,2,J)%N :: t)) f hf
      = (ROk W2 f2, i2)
    /\ ccolcost W2 = fcc sg cw2
    /\ sdecode W2 f2 = sdecode (lin_flat sg cw2) f2.
Proof.
  intros HG HGuard HFG ES HFA HRun.
  destruct HG as ((HOk & HPT) & HE & HW & HShape & HK & HP).
  assert (HM : ph_margins sg ((2,2,J)%N :: t))
    by (exact (lguard_margins sg _ HGuard)).
  assert (HN : ph_nbrs sg ((2,2,J)%N :: t))
    by (exact (margins_edges_nbrs sg _ HM HE)).
  assert (HL : sg_live sg)
    by (exact (sg_shape_live sg HW HShape)).
  destruct (splice_none_direct_inv sg J t f h s j cw2 f2 ir ES HFA HRun)
    as (k & body & HJ & HS & HCols & HLast & HComp & -> & ->).
  assert (HI : (1 <= j)%nat)
    by (pose proof (find_active_lb _ _ _ HFA); lia).
  assert (HM1 : ph_margins sg ((2,2,J+1)%N :: t))
    by (exact (margins_master_change sg J (J+1)%N t HM)).
  assert (HN1 : ph_nbrs sg ((2,2,J+1)%N :: t))
    by (exact (nbrs_master_change sg J (J+1)%N t HN)).
  destruct (site_comp_head sg ((2,2,J+1)%N :: t) j f k body f2 HComp)
    as (g & u & Hsite & Hph & Hcasc & Hnotag).
  assert (Hilt : (j < length ((2%N,2%N,(J+1)%N) :: t))%nat)
    by (exact (site_comp_some_lt _ _ _ _ _ _ HComp)).
  assert (HPN : ph_notlast sg (firstn j ((2,2,J+1)%N :: t))).
  { exact (margins_ph_notlast sg ((2,2,J+1)%N :: t) j g u
             HM1 Hsite Hcasc). }
  assert (HNs : nbrs1z sg (skipn j ((2,2,J+1)%N :: t))).
  { apply nbrs_nbrs1z.
    apply (ph_nbrs_app_r sg (firstn j ((2,2,J+1)%N :: t))).
    rewrite firstn_skipn. exact HN1. }
  assert (HH : forall g0 u0,
      skipn j ((2,2,J+1)%N :: t) = g0 :: u0 -> ph sg g0 = false).
  { intros g0 u0 E.
    pose proof (eq_trans (eq_sym Hsite) E) as EE.
    injection EE as Eg _. subst g0. exact Hph. }
  assert (HFront : first_rule front_rules
      (lin_flat sg ((2,2,J)%N :: t)) f = None).
  { exact (front_gate_None_flat_tag sg ((2,2,J)%N :: t) f
             HW HK HL HM HN HFG). }
  assert (HD : Nat.leb 3 j = Nat.leb 3
      (length (lin_flat sg (firstn j ((2,2,J+1)%N :: t)))))
    by (exact (leb3_flat_prefix sg ((2,2,J+1)%N :: t) j HW HM1 Hilt)).
  pose proof (direct_flat_step_of_site sg J t s j f k body f2
    HW HK HL HP HJ HS HI HFront HFA HCols HLast HD HPN HNs HH HComp) as HStep.
  cbv beta zeta in HStep.
  assert (HiEq : length (lin_flat sg (firstn j ((2,2,J+1)%N :: t)))
                 = length (lin_flat sg (firstn j ((2,2,J)%N :: t))))
    by (apply flat_firstn_master_len; exact HI).
  assert (EPre : firstn (length (lin_flat sg (firstn j ((2,2,J)%N :: t))))
                   (lin_flat sg ((2,2,J+1)%N :: t))
                 = lin_flat sg (firstn j ((2,2,J+1)%N :: t))).
  { rewrite <- HiEq. symmetry.
    exact (flat_firstn sg ((2,2,J+1)%N :: t) j). }
  destruct k; cbv beta iota; eexists; eexists; eexists;
    (split; [exact HStep|]).
  -
    split.
    + rewrite ccolcost_normalize, ccolcost_app, EPre.
      rewrite fcc_norm_join. unfold fcc. reflexivity.
    + transitivity (sdecode
        (firstn (length (lin_flat sg (firstn j ((2,2,J)%N :: t))))
           (lin_flat sg ((2,2,J+1)%N :: t)) ++ lin_flat sg body) f2).
      * apply normalize_sound.
      * rewrite EPre, <- lin_flat_app_c.
        symmetry. apply lin_normalize_join_flat_sdecode.
  -
    split.
    + rewrite ccolcost_normalize, fcc_norm_at. unfold fcc.
      reflexivity.
    + transitivity (sdecode (lin_flat sg body) f2).
      * apply normalize_sound.
      * symmetry. apply lin_normalize_at_flat_sdecode.
Qed.
Theorem micro_direct (sg : list seg) (J : N) (t : word) (f : N)
        (h : nat) (s j : nat) (cw2 : word) (f2 : N) (ir : nat) :
  stable_guard sg ((2,2,J)%N :: t) ->
  lin_guard sg ((2,2,J)%N :: t) = true ->
  front_gate ((2,2,J)%N :: t) f = None ->
  s = (if Nat.ltb h 1 then 1%nat else h) ->
  find_active ((2,2,J)%N :: t) s = Some j ->
  splice_call sg None ((2,2,J)%N :: t) f h = (ROk cw2 f2, ir) ->
  cmeas sg ((2,2,J)%N :: t) f <= cmeas sg cw2 f2 + 2.
Proof.
  intros HG HGuard HFG ES HFA HRun.
  destruct (direct_step_kernel sg J t f h s j cw2 f2 ir
              HG HGuard HFG ES HFA HRun) as (hf & W2 & i2 & HStep & HCC & _).
  pose proof (step_grow _ _ _ _ _ _ HStep) as HGr.
  unfold gmeas in HGr. rewrite HCC in HGr.
  rewrite !cmeas_fcc. unfold fcc in HGr |- *. lia.
Qed.
Theorem micro_fallback (sg : list seg) (J : N) (t : word) (f : N)
        (h : nat) (s : nat) (cw2 : word) (f2 : N) (ir : nat) :
  stable_guard sg ((2,2,J)%N :: t) ->
  lin_guard sg ((2,2,J)%N :: t) = true ->
  s = (if Nat.ltb h 1 then 1%nat else h) ->
  find_active ((2,2,J)%N :: t) s = None ->
  splice_call sg None ((2,2,J)%N :: t) f h = (ROk cw2 f2, ir) ->
  cmeas sg ((2,2,J)%N :: t) f <= cmeas sg cw2 f2.
Proof.
  intros HG HGuard ES HFA HRun.
  destruct HG as ((HOk & HPT) & HE & HW & HShape & HK & HP).
  assert (HM : ph_margins sg ((2,2,J)%N :: t))
    by (exact (lguard_margins sg _ HGuard)).
  assert (HN : ph_nbrs sg ((2,2,J)%N :: t))
    by (exact (margins_edges_nbrs sg _ HM HE)).
  destruct (splice_none_fallback_inv sg J t f h s cw2 f2 ir ES HFA HRun)
    as (j & sfx & HJ & ECMF & HCols & ELeaf & -> & ->).
  destruct (cmf_from_inv _ _ _ _ ECMF)
    as (Hstart & g & Hwat & Hcmf).
  assert (Hj : (1 <= j)%nat).
  { eapply PeanoNat.Nat.le_trans; [|exact Hstart].
    apply PeanoNat.Nat.le_max_l. }
  assert (Es : exists u, skipn j ((2,2,J)%N :: t) = g :: u).
  { unfold wat in Hwat.
    assert (E0 : nth_error (skipn j ((2,2,J)%N :: t)) O = Some g).
    { rewrite nth_skipn, PeanoNat.Nat.add_0_r. exact Hwat. }
    destruct (skipn j ((2,2,J)%N :: t)) as [|g0 u] eqn:ESk.
    - discriminate E0.
    - cbn [nth_error] in E0. injection E0 as <-. exists u. reflexivity. }
  destruct Es as (u & Es).
  assert (Hph : ph sg g = false).
  { destruct (ph sg g) eqn:E; [|reflexivity].
    pose proof (ph_not_cmf sg g E) as Hnc.
    rewrite Hcmf in Hnc. discriminate. }
  assert (Es1 : skipn j ((2,2,J+1)%N :: t) = g :: u).
  { rewrite <- (skipn_master_change J (J+1)%N t j Hj). exact Es. }
  assert (HM1 : ph_margins sg ((2,2,J+1)%N :: t))
    by (exact (margins_master_change sg J (J+1)%N t HM)).
  assert (HN1 : ph_nbrs sg ((2,2,J+1)%N :: t))
    by (exact (nbrs_master_change sg J (J+1)%N t HN)).
  assert (HNs : nbrs1z sg (skipn j ((2,2,J+1)%N :: t))).
  { apply nbrs_nbrs1z.
    apply (ph_nbrs_app_r sg (firstn j ((2,2,J+1)%N :: t))).
    rewrite firstn_skipn. exact HN1. }
  assert (HH : forall g0 u0,
      skipn j ((2,2,J+1)%N :: t) = g0 :: u0 -> ph sg g0 = false).
  { intros g0 u0 E.
    pose proof (eq_trans (eq_sym Es1) E) as EE.
    injection EE as Eg _. subst g0. exact Hph. }
  assert (ELeafF : leaf_act
      (lin_flat sg (skipn j ((2,2,J+1)%N :: t))) f
      = Some (lin_flat sg sfx, f2)).
  { pose proof (leaf_act_flat_z sg (skipn j ((2,2,J+1)%N :: t)) f
      HW HK HNs HH) as E.
    rewrite ELeaf in E. exact E. }
  pose proof (leaf_grow _ _ _ _ ELeafF) as HGr.
  pose proof (firstn_master_form J t j Hj) as EJ0.
  pose proof (firstn_master_form (J+1)%N t j Hj) as EJ1.
  pose proof (skipn_master_change J (J+1)%N t j Hj) as ESk.
  rewrite !cmeas_fcc, fcc_norm_join.
  rewrite (fcc_split sg ((2,2,J)%N :: t) j), EJ0, EJ1, ESk, !fcc_master.
  unfold fcc in HGr |- *. lia.
Qed.
Theorem micro_dom_settled (sg : list seg) (cw : word) (f : N)
        (h : nat) (cw2 : word) (f2 : N) (i : nat) :
  stable_guard sg cw ->
  lin_guard sg cw = true ->
  step_after_front_with_guard false
    (lin_normalize_at sg)
    (fun pre sfx _ => lin_normalize_join sg pre sfx)
    (front_gate cw f) cw f h = (ROk cw2 f2, i) ->
  cmeas sg cw f <= cmeas sg cw2 f2 + 2.
Proof.
  intros HG HGuard HRun.
  change (step_after_front_with_guard false (lin_normalize_at sg)
            (fun pre sfx _ => lin_normalize_join sg pre sfx)
            (front_gate cw f) cw f h)
    with (splice_call sg (front_gate cw f) cw f h) in HRun.
  destruct (front_gate cw f) as [r|] eqn:HFG.
  - destruct r as [fw ff| |].
    + apply (micro_front sg cw f h fw ff cw2 f2 i HG HGuard HFG).
      rewrite HFG. exact HRun.
    + unfold splice_call, step_after_front_with_guard in HRun.
      discriminate.
    + unfold splice_call, step_after_front_with_guard in HRun.
      discriminate.
  - destruct (splice_none_rok_master sg cw f h cw2 f2 i HRun)
      as (J & t & -> & HJ).
    set (s := if Nat.ltb h 1 then 1%nat else h).
    destruct (find_active ((2,2,J)%N :: t) s) as [j|] eqn:EFA.
    + exact (micro_direct sg J t f h s j cw2 f2 i HG HGuard HFG
               eq_refl EFA HRun).
    + assert (HD : cmeas sg ((2,2,J)%N :: t) f
                   <= cmeas sg cw2 f2)
        by (exact (micro_fallback sg J t f h s cw2 f2 i HG HGuard
                     eq_refl EFA HRun)).
      lia.
Qed.
Definition NPRE : word := [(4,2,1); (4,2,1); (5,2,1); (6,2,1)]%N.
Definition NSFX : word := [(7,1,1)]%N.
Example norm_join_keeps_pair :
  lin_normalize_join [] NPRE NSFX
  = [(4,2,1); (4,2,1); (5,2,1); (6,2,1); (7,1,1)]%N.
Proof. vm_compute. reflexivity. Qed.
Example norm_flat_merges_pair :
  normalize (NPRE ++ NSFX)
  = [(4,2,2); (5,2,1); (6,2,1); (7,1,1)]%N.
Proof. vm_compute. reflexivity. Qed.
Example norm_flat_id :
  (lin_flat [] (lin_normalize_join [] NPRE NSFX),
   lin_flat [] (NPRE ++ NSFX))
  = (lin_normalize_join [] NPRE NSFX, NPRE ++ NSFX).
Proof. vm_compute. reflexivity. Qed.
Example norm_same_ccol :
  (ccolcost (lin_normalize_join [] NPRE NSFX),
   ccolcost (normalize (NPRE ++ NSFX)))
  = (82%N, 82%N).
Proof. vm_compute. reflexivity. Qed.
Theorem front_step_kernel (sg : list seg) (cw : word) (f : N)
        (h : nat) (fw : word) (ff : N) (cw2 : word) (f2 : N)
        (i : nat) :
  stable_guard sg cw ->
  lin_guard sg cw = true ->
  front_gate cw f = Some (ROk fw ff) ->
  splice_call sg (front_gate cw f) cw f h = (ROk cw2 f2, i) ->
  forall hf : nat,
    step (lin_flat sg cw) f hf
      = (ROk (normalize (lin_flat sg fw)) f2, O)
    /\ sdecode (normalize (lin_flat sg fw)) f2
       = sdecode (lin_flat sg cw2) f2.
Proof.
  intros HG HGuard HFG HRun hf.
  destruct HG as ((HOk & HPT) & HE & HW & HShape & HK & HP).
  assert (HM : ph_margins sg cw)
    by (exact (lguard_margins sg cw HGuard)).
  assert (HN : ph_nbrs sg cw)
    by (exact (margins_edges_nbrs sg cw HM HE)).
  assert (HL : sg_live sg)
    by (exact (sg_shape_live sg HW HShape)).
  unfold splice_call, step_after_front_with_guard in HRun.
  rewrite HFG in HRun. cbv beta iota in HRun.
  injection HRun as <- <- <-.
  assert (EFR : first_rule front_rules cw f
                = Some (ROk fw ff)).
  { unfold front_gate in HFG.
    destruct (lin_front_possible cw); [exact HFG|discriminate]. }
  assert (EFF : first_rule front_rules (lin_flat sg cw) f
                = Some (ROk (lin_flat sg fw) ff)).
  { rewrite (first_rule_flat_tag sg cw f HW HK HL HM HN), EFR.
    reflexivity. }
  change (lin_normalize_at sg fw O) with fw.
  split.
  - unfold step, step_after_front, step_after_front_with,
      step_after_front_with_guard.
    rewrite EFF. reflexivity.
  - apply normalize_sound.
Qed.
Theorem micro_decode_transport (sg : list seg) (cw : word) (f : N)
        (h : nat) (cw2 : word) (f2 : N) (i : nat) :
  stable_guard sg cw ->
  lin_guard sg cw = true ->
  step_after_front_with_guard false
    (lin_normalize_at sg)
    (fun pre sfx _ => lin_normalize_join sg pre sfx)
    (front_gate cw f) cw f h = (ROk cw2 f2, i) ->
  (exists (hf : nat) (W2 : word) (i2 : nat),
      step (lin_flat sg cw) f hf = (ROk W2 f2, i2)
      /\ sdecode W2 f2 = sdecode (lin_flat sg cw2) f2)
  \/ (front_gate cw f = None
      /\ find_active cw (if Nat.ltb h 1 then 1%nat else h) = None).
Proof.
  intros HG HGuard HRun.
  change (step_after_front_with_guard false (lin_normalize_at sg)
            (fun pre sfx _ => lin_normalize_join sg pre sfx)
            (front_gate cw f) cw f h)
    with (splice_call sg (front_gate cw f) cw f h) in HRun.
  destruct (front_gate cw f) as [r|] eqn:HFG.
  - destruct r as [fw ff| |].
    + left.
      destruct (front_step_kernel sg cw f h fw ff cw2 f2 i HG HGuard HFG
                  ltac:(rewrite HFG; exact HRun) O) as (HS & HD).
      exists O, (normalize (lin_flat sg fw)), O.
      split; assumption.
    + unfold splice_call, step_after_front_with_guard in HRun.
      discriminate.
    + unfold splice_call, step_after_front_with_guard in HRun.
      discriminate.
  - destruct (splice_none_rok_master sg cw f h cw2 f2 i HRun)
      as (J & t & -> & HJ).
    destruct (find_active ((2,2,J)%N :: t)
                (if Nat.ltb h 1 then 1%nat else h)) as [j|] eqn:EFA.
    + left.
      destruct (direct_step_kernel sg J t f h
                  (if Nat.ltb h 1 then 1%nat else h) j cw2 f2 i
                  HG HGuard HFG eq_refl EFA HRun)
        as (hf & W2 & i2 & HStep & _ & HD).
      exists hf, W2, i2. split; assumption.
    + right. split; reflexivity.
Qed.
Theorem micro_act_of_flat (C : cost) (sg : list seg)
        (cw : word) (f : N) (h : nat) (cw2 : word) (f2 : N)
        (i : nat) :
  stable_guard sg cw ->
  lin_guard sg cw = true ->
  step_after_front_with_guard false
    (lin_normalize_at sg)
    (fun pre sfx _ => lin_normalize_join sg pre sfx)
    (front_gate cw f) cw f h = (ROk cw2 f2, i) ->
  (forall (hf : nat) (W2 : word) (i2 : nat),
     step (lin_flat sg cw) f hf = (ROk W2 f2, i2) ->
     creach C (wconf [] 0 (sdecode (lin_flat sg cw) f))
                   (wconf [] 0 (sdecode W2 f2))) ->
  creach C (wconf [] 0 (sdecode (lin_flat sg cw) f))
                (wconf [] 0 (sdecode (lin_flat sg cw2) f2))
  \/ (front_gate cw f = None
      /\ find_active cw (if Nat.ltb h 1 then 1%nat else h) = None).
Proof.
  intros HG HGuard HRun HFlat.
  destruct (micro_decode_transport sg cw f h cw2 f2 i HG HGuard HRun)
    as [(hf & W2 & i2 & HStep & HD)|HFall]; [|right; exact HFall].
  left. rewrite <- HD. exact (HFlat hf W2 i2 HStep).
Qed.
Theorem micro_dom : MicroDom.
Proof.
  intros fr sg cw f h cw2 f2 i HG HGuard Hfr HS. subst fr.
  exact (micro_dom_settled sg cw f h cw2 f2 i HG HGuard HS).
Qed.
Local Open Scope N_scope.
Opaque LROUND_FUEL LROUND_CHUNKS
       FLAT_ROUND_FUEL CFUEL TRIES.
Lemma chi_cdrop6_le (d : cost) :
  chi (cdrop6 d) <= chi d.
Proof.
  unfold cdrop6.
  destruct (andb (6 <=? clo d)%N (6 <=? chi d)%N);
    [unfold clo, chi; destruct d; cbn; lia
    |cbn [cundef chi snd]; lia].
Qed.
Lemma crenew_pair_ub (n : nat) (cols s : word) (f : N)
      (body : word) (f2 : N) (d : cost) :
  crenew_seg n cols s f = (Some (body, f2), d) ->
  chi d <= ubc (ccolcost cols + ccolcost s) f.
Proof.
  intros E.
  assert (EF : fst (crenew_seg n cols s f) = Some (body, f2))
    by (rewrite E; reflexivity).
  pose proof (proj2 (cascade_ub n) cols s f body f2 EF) as H.
  rewrite E in H. exact H.
Qed.
Lemma cfire_pair_ub (n : nat) (s : word) (f : N)
      (body : word) (f2 : N) (d : cost) :
  cfire_comp n s f = (Some (body, f2), d) ->
  chi d <= ubc (ccolcost s) f.
Proof.
  intros E.
  assert (EF : fst (cfire_comp n s f) = Some (body, f2))
    by (rewrite E; reflexivity).
  pose proof (proj1 (cascade_ub n) s f body f2 EF) as H.
  rewrite E in H. exact H.
Qed.
Lemma cleaf_pair_ub (s : word) (f : N)
      (body : word) (f2 : N) (d : cost) :
  cleaf_act s f = (Some (body, f2), d) ->
  chi d <= ubc (ccolcost s) f.
Proof.
  intros E.
  assert (EF : fst (cleaf_act s f) = Some (body, f2))
    by (rewrite E; reflexivity).
  pose proof (cleaf_act_ub s f body f2 EF) as H.
  rewrite E in H. exact H.
Qed.
Lemma cdtick_after_seek_ub (cols s : word) (f : N) :
  chi (snd (cdtick_after_seek cols s f))
  <= ubc (ccolcost cols + ccolcost s) f.
Proof.
  unfold cdtick_after_seek, cleaf_lift.
  match goal with
  | |- context [crenew_seg ?n ?cs ?ss ?ff] =>
      remember (crenew_seg n cs ss ff) as cr eqn:Ecr
  end.
  destruct cr as [rr dr]. destruct rr as [[body f2]|].
  - pose proof (crenew_pair_ub _ _ _ _ _ _ _ (eq_sym Ecr)) as HU.
    cbn [fst snd] in *. exact HU.
  - destruct s as [|[[o z] c] t].
    + match goal with
      | |- context [cleaf_act ?ss ?ff] =>
          remember (cleaf_act ss ff) as cl eqn:Ecl
      end.
      destruct cl as [rl dl]. destruct rl as [[body f2]|].
      * pose proof (cleaf_pair_ub _ _ _ _ _ (eq_sym Ecl)) as HU.
        cbn [fst snd cadd cx chi] in *.
        pose proof (chi_cdrop6_le dl) as HD.
        eapply N.le_trans.
        { apply N.add_le_mono_l. exact HD. }
        eapply N.le_trans.
        { apply N.add_le_mono_l. exact HU. }
        unfold ubc. cbn [ccolcost]. lia.
      * cbn [fst snd cundef chi] in *.
        unfold ubc. lia.
    + destruct (((z =? 3) && (c =? 1))%N) eqn:EZC.
      * match goal with
        | |- context [cfire_comp ?n ?ss ?ff] =>
            remember (cfire_comp n ss ff) as cf eqn:Ecf
        end.
        destruct cf as [rf df]. destruct rf as [[body f2]|].
        -- pose proof (cfire_pair_ub _ _ _ _ _ _ (eq_sym Ecf)) as HU.
           cbn [fst snd cadd cx chi] in *.
           eapply N.le_trans.
           { apply N.add_le_mono_l. exact HU. }
           unfold ubc. lia.
        -- cbn [fst snd cundef chi] in *.
           unfold ubc. lia.
      * match goal with
        | |- context [sand_leaf ?ss] =>
            remember (sand_leaf ss) as sb
        end.
        destruct sb.
        { cbn [fst snd cundef chi]. unfold ubc. lia. }
        match goal with
        | |- context [cleaf_act ?ss ?ff] =>
            remember (cleaf_act ss ff) as cl eqn:Ecl
        end.
        destruct cl as [rl dl]. destruct rl as [[body f2]|].
        -- pose proof (cleaf_pair_ub _ _ _ _ _ (eq_sym Ecl)) as HU.
           cbn [fst snd cadd cx chi] in *.
           pose proof (chi_cdrop6_le dl) as HD.
           eapply N.le_trans.
           { apply N.add_le_mono_l. exact HD. }
           eapply N.le_trans.
           { apply N.add_le_mono_l. exact HU. }
           unfold ubc. lia.
        -- cbn [fst snd cundef chi] in *.
           unfold ubc. lia.
Qed.
Definition armq (M : N) : N := 2 * (M + 32).
Lemma flat_seek_cost_le (sg : list seg) (w cols s : word)
      (cur : nat) :
  seek (skipn cur w) = (cols, s) ->
  ccolcost (lin_flat sg cols) +
  ccolcost (lin_flat sg s)
  <= ccolcost (lin_flat sg w).
Proof.
  intros HS.
  destruct (seek_split (skipn cur w) cols s HS) as (EW & _).
  pose proof (flat_firstn_skipn sg w cur) as EAll.
  rewrite EW, lin_flat_app_c in EAll.
  rewrite EAll, !ccolcost_app. lia.
Qed.
Lemma ddirect_armq (sg : list seg) (w cols s : word)
      (f : N) (cur gap : nat) :
  seek (skipn cur w) = (cols, s) ->
  chi (ddirect sg cols s f gap)
  <= armq (gmeas (lin_flat sg w) f).
Proof.
  intros HS. unfold ddirect.
  pose proof (cdtick_after_seek_ub
    (skipn gap (lin_flat sg cols)) (lin_flat sg s) f) as HU.
  pose proof (ccolcost_skipn_le (lin_flat sg cols) gap) as HK.
  pose proof (flat_seek_cost_le sg w cols s cur HS) as HW.
  unfold ubc, armq, gmeas in *. nia.
Qed.
Lemma cdtick_seek_armq (lw cols s : word) (f : N)
      (lc gap : nat) :
  seek (skipn lc lw) = (cols, s) ->
  chi (snd (cdtick_after_seek (skipn gap cols) s f))
  <= armq (gmeas lw f).
Proof.
  intros HS.
  pose proof (cdtick_after_seek_ub (skipn gap cols) s f) as HU.
  pose proof (ccolcost_skipn_le cols gap) as HK.
  destruct (seek_split (skipn lc lw) cols s HS) as (EW & _).
  pose proof (ccolcost_skipn_le lw lc) as HL.
  rewrite EW, ccolcost_app in HL.
  unfold ubc, armq, gmeas in *. nia.
Qed.
Lemma armq_mono (a b : N) : a <= b -> armq a <= armq b.
Proof. unfold armq. nia. Qed.
Lemma chi_caddx_exact (a b : cost) :
  CE a -> CE b ->
  chi (caddx a b) = chi a + chi b.
Proof.
  unfold CE, caddx, clo, chi.
  destruct a as [al ah], b as [bl bh]. cbn [fst snd].
  intros -> ->. rewrite !N.eqb_refl. reflexivity.
Qed.
Lemma zrun_chi_ub (q : nat) :
  forall lc sg lw f gap slot out f' d,
  sg_wf sg ->
  clin_bottom_sched_zrun q lc sg lw f gap slot
    = (Some (out, f'), d) ->
  chi d
  <= N.of_nat q * armq (gmeas (lin_flat sg out) f'
                         + 8 * N.of_nat q).
Proof.
  induction q as [|q IH]; intros lc sg lw f gap slot out f' d HW HR.
  - cbn [clin_bottom_sched_zrun] in HR.
    destruct (lin_literal_word lw); [|discriminate HR].
    inversion HR; subst. reflexivity.
  - destruct (clin_bottom_sched_zrun_S_inv
                q lc sg lw f gap slot out f' d HR)
      as (cols & g & t & renewed & sfx & f2 & lw2 & d2
          & HLit & HSeek & HStep & HRenew & HJoin & HRec & HD).
    subst d.
    assert (HLocalExact : CE
      (snd (cdtick_after_seek (skipn gap cols) (g :: t) f))).
    { assert (HCols : forallb is_col (skipn gap cols) = true).
      { apply forallb_skipn.
        exact (seek_cols _ _ _ HSeek). }
      assert (HLitCols : lin_literal_word cols = true).
      { pose proof (literal_word_skipn lc lw HLit) as HS.
        destruct (seek_split (skipn lc lw) cols (g :: t) HSeek)
          as (ESplit & _).
        rewrite ESplit in HS.
        exact (literal_word_app_l cols (g :: t) HS). }
      assert (HRenewAvail : renewed = true ->
                (2 <= length (skipn gap cols))%nat).
      { intro ER. specialize (HRenew ER).
        rewrite (lin_flen_flat_wf sg cols HW) in HRenew.
        rewrite (literal_word_flat sg cols HLitCols) in HRenew.
        rewrite length_skipn. lia. }
      destruct (lin_dtick_after_seek_strip
        (firstn gap cols) (skipn gap cols) (g :: t) f
        renewed sfx f2 ltac:(rewrite firstn_skipn; exact HStep)
        HRenewAvail) as (body & HBody & EBody).
      apply (cdtick_after_seek_exact
        (skipn gap cols) (g :: t) f body f2 HCols).
      rewrite cdtick_after_seek_proj.
      exact (lin_dtick_after_seek_proj
        (skipn gap cols) (g :: t) f renewed body f2 HBody). }
    assert (HRecExact : CE d2).
    { exact (clin_bottom_sched_zrun_exact
        q lc sg lw2 f2
        (gap - 2 * N.to_nat (lin_sched_grant_one slot))%nat
        (lin_sched_slot_advance_one slot) out f' d2 HW HRec). }
    rewrite (chi_caddx_exact _ _ HLocalExact HRecExact).
    pose proof (IH lc sg lw2 f2
      (gap - 2 * N.to_nat (lin_sched_grant_one slot))%nat
      (lin_sched_slot_advance_one slot) out f' d2 HW HRec) as HIR.
    pose proof (cdtick_seek_armq lw cols (g :: t) f lc gap HSeek) as HC.
    pose proof (zrun_dom (S q) lc sg lw f gap slot out f'
                  ltac:(rewrite <- clin_bottom_sched_zrun_proj;
                        rewrite HR; reflexivity)) as HM.
    unfold FlightDomC_cmeas in HM.
    rewrite (literal_word_flat sg lw HLit) in HM.
    apply N.le_trans with
      (armq (gmeas (lin_flat sg out) f'
              + 8 * N.of_nat (S q))
       + N.of_nat q * armq (gmeas (lin_flat sg out) f'
              + 8 * N.of_nat (S q)))%N.
    + apply N.add_le_mono.
      * eapply N.le_trans; [exact HC|]. apply armq_mono.
        exact HM.
      * eapply N.le_trans; [exact HIR|].
        apply N.mul_le_mono_l, armq_mono.
        rewrite !Nat2N.inj_succ. lia.
    + rewrite Nat2N.inj_succ. nia.
Qed.
Definition ladderq (M : N) : N := 20 * armq (M + 152).
Lemma bottom_min_le19 (tk : N) (p : nat) :
  N.of_nat (Nat.min (N.to_nat tk) (19 - p)%nat) <= 19.
Proof.
  rewrite Nat2N.inj_min.
  eapply N.le_trans with (m := N.of_nat (19 - p)%nat).
  - apply N.le_min_r.
  -
  rewrite Nat2N.inj_sub. apply N.le_sub_l.
Qed.
Lemma lin_bottom_take_lt20 (cols s : word) (f tk take : N) :
  lin_bottom_take cols s f tk = Some take -> take <= 19.
Proof.
  unfold lin_bottom_take.
  repeat
    match goal with
    | |- context [match ?x with _ => _ end] => destruct x eqn:?
    | |- context [if ?b then _ else _] => destruct b eqn:?
    end;
    intros H; try discriminate H; injection H as <-;
    apply bottom_min_le19.
Qed.
Lemma zrun_ladderq (q : nat) (lc : nat) (sg : list seg)
      (lw : word) (f : N) (gap : nat) (slot : N)
      (out : word) (f' : N) (d : cost) :
  sg_wf sg ->
  (N.of_nat q <= 19)%N ->
  clin_bottom_sched_zrun q lc sg lw f gap slot
    = (Some (out, f'), d) ->
  chi d <= ladderq (gmeas (lin_flat sg out) f').
Proof.
  intros HW Hq HR.
  pose proof (zrun_chi_ub q lc sg lw f gap slot out f' d HW HR) as H.
  unfold ladderq. eapply N.le_trans; [exact H|].
  apply N.mul_le_mono; [lia|].
  apply armq_mono. nia.
Qed.
Lemma ladderA_grid_b :
  forallb (fun p => (ladderA p <=? 7)%N)
          pgrid = true.
Proof. vm_compute. reflexivity. Qed.
Lemma ladderA_le7 (p : N) : p < 28 -> ladderA p <= 7.
Proof.
  intros Hp.
  pose proof (proj1 (forallb_forall _ pgrid)
    ladderA_grid_b p (in_pgrid p Hp)) as H.
  apply N.leb_le in H. exact H.
Qed.
Lemma dphase_base_ub (p b : N) :
  p < 28 ->
  dphase p (b + DBu p) <= 14 * b + 100.
Proof.
  intros Hp.
  pose proof (ladderA_le7 p Hp) as HA.
  pose proof (DBu_le3 p Hp) as HD.
  unfold dphase.
  destruct (emits p); nia.
Qed.
Lemma dladder_linear_ub (n : nat) : forall p b,
  p + N.of_nat n <= 28 ->
  dladder p b n <= N.of_nat n * (14 * b + 100).
Proof.
  induction n as [|n IH]; intros p b Hpn.
  - cbn [dladder N.of_nat]. lia.
  - cbn [dladder]. rewrite Nat2N.inj_succ in Hpn |- *.
    pose proof (dphase_base_ub p b ltac:(lia)) as HP.
    pose proof (IH (p+1)%N b ltac:(lia)) as HR.
    nia.
Qed.
Lemma dladder_block_ub (n : nat) (p b M : N) :
  p + N.of_nat n <= 28 -> b <= M ->
  dladder p b n <= 392 * M + 2800.
Proof.
  intros Hpn Hb.
  pose proof (dladder_linear_ub n p b Hpn) as H.
  assert (N.of_nat n <= 28)%N by lia.
  nia.
Qed.
Lemma mul_succ_expand (a n : N) :
  a * N.succ n = a * n + a.
Proof. replace (N.succ n) with (n+1)%N by lia. ring. Qed.
Lemma dlocals_linear_ub (rl : list N) : forall p rem b M,
  p < 28 -> rem < 28 -> b <= M ->
  Forall (fun x => x <= M) rl ->
  dlocals rl p rem b
    <= 406 * (M + 14) * (N.of_nat (length rl) + 1).
Proof.
  induction rl as [|d rest IH]; intros p rem b M Hp Hr Hb HF.
  - cbn [dlocals length N.of_nat]. lia.
  - inversion HF as [|d0 rest0 Hd HRest]; subst d0 rest0.
    destruct rest as [|e tail].
    + cbn [dlocals length].
      pose proof (dladder_block_ub (N.to_nat (27-p)) p b M
        ltac:(rewrite N2Nat.id; lia) Hb) as H1.
      pose proof (dladder_block_ub (N.to_nat rem) 0%N (d-3)%N M
        ltac:(rewrite N2Nat.id; lia) ltac:(lia)) as H2.
      cbn [N.of_nat]. nia.
    + rewrite (dlocals_cons_ne d (e :: tail) p rem b
                ltac:(discriminate)).
      pose proof (dladder_block_ub (N.to_nat (27-p)) p b M
        ltac:(rewrite N2Nat.id; lia) Hb) as H1.
      pose proof (IH 0%N rem (d-3)%N M ltac:(lia) Hr ltac:(lia) HRest) as H2.
      assert (HL :
        dladder p b (N.to_nat (27-p)) + 14*b + 22
        <= 406 * (M+14)) by nia.
      eapply N.le_trans with
        (m := 406 * (M+14) +
              406 * (M+14) *
                (N.of_nat (length (e :: tail)) + 1)).
      * apply N.add_le_mono; assumption.
      * cbn [length]. repeat rewrite Nat2N.inj_succ.
        repeat rewrite <- N.add_1_r. ring_simplify.
        apply N.le_refl.
Qed.
Lemma wcolsum_tail_le (d : N) (rest : list N) :
  wcolsum rest <= wcolsum (d :: rest).
Proof. cbn [wcolsum]. lia. Qed.
Lemma wcolsum_length_le (rl : list N) :
  N.of_nat (length rl) <= wcolsum rl.
Proof.
  induction rl as [|d rest IH]; [reflexivity|].
  cbn [wcolsum length]. rewrite Nat2N.inj_succ. lia.
Qed.
Lemma wcolsum_length22_core (rl : list N) :
  22 * N.of_nat (length rl) <= wcolsum rl.
Proof.
  induction rl as [|d rest IH]; [reflexivity|].
  cbn [length wcolsum]. rewrite Nat2N.inj_succ. lia.
Qed.
Lemma dlocals_mass_ub (rl : list N) : forall p rem b,
  p < 28 -> rem < 28 ->
  dlocals rl p rem b
    <= 406 * b + 2800 + 129 * wcolsum rl.
Proof.
  induction rl as [|d rest IH]; intros p rem b Hp Hr.
  - cbn [dlocals wcolsum]. lia.
  - destruct rest as [|e tail].
    + cbn [dlocals wcolsum].
      pose proof (dladder_block_ub (N.to_nat (27-p)) p b b
        ltac:(rewrite N2Nat.id; lia) ltac:(lia)) as H1.
      pose proof (dladder_block_ub (N.to_nat rem) 0%N (d-3)%N d
        ltac:(rewrite N2Nat.id; lia) ltac:(lia)) as H2.
      nia.
    + rewrite (dlocals_cons_ne d (e :: tail) p rem b
                ltac:(discriminate)).
      change
        (dladder p b (N.to_nat (27-p)) + 14*b + 22 +
           dlocals (e :: tail) 0 rem (d-3)
         <= 406*b + 2800 +
              129*(14*d + 22 + wcolsum (e :: tail)))%N.
      pose proof (dladder_block_ub (N.to_nat (27-p)) p b b
        ltac:(rewrite N2Nat.id; lia) ltac:(lia)) as H1.
      pose proof (IH 0%N rem (d-3)%N ltac:(lia) Hr) as H2.
      assert (Hd : 406 * (d-3) <= 406 * d)
        by (apply N.mul_le_mono_l; lia).
      eapply N.le_trans with
        (m := (406*b + 2822) +
              (406*d + 2800 + 129*wcolsum (e :: tail))).
      * apply N.add_le_mono.
        -- nia.
        -- eapply N.le_trans; [exact H2|]. nia.
      * replace
          ((406*b + 2822) +
             (406*d + 2800 + 129*wcolsum (e :: tail)))%N
          with
          ((406*b + 406*d + 5622) +
             129*wcolsum (e :: tail))%N by ring.
        replace
          (406*b + 2800 +
             129*(14*d + 22 + wcolsum (e :: tail)))%N
          with
          ((406*b + 1806*d + 5638) +
             129*wcolsum (e :: tail))%N by ring.
        apply N.add_le_mono; [lia|reflexivity].
Qed.
Lemma dtransit1_quad_ub (p b W M : N) :
  p < 28 -> b <= M -> W <= M ->
  dtransit1 p b W <= 434 * M + 2822.
Proof.
  intros Hp Hb HW.
  pose proof (dladder_block_ub (N.to_nat (27-p)) p b M
    ltac:(rewrite N2Nat.id; lia) Hb) as HL.
  unfold dtransit1. nia.
Qed.
Lemma drunway_zero_linear_ub (rl : list N) : forall p rem b M,
  p < 28 -> rem < 28 -> b <= M ->
  Forall (fun x => x <= M) rl ->
  wcolsum rl <= M ->
  drunway 0%N rl p rem b
    <= 434 * (M + 13) * (N.of_nat (length rl) + 1).
Proof.
  induction rl as [|d rest IH]; intros p rem b M Hp Hr Hb HF HM.
  - cbn [drunway length N.of_nat]. lia.
  - inversion HF as [|d0 rest0 Hd HRest]; subst d0 rest0.
    destruct rest as [|e tail].
    + cbn [drunway length].
      pose proof (dtransit1_quad_ub p b
        (wcolsum [d]) M Hp Hb HM) as H1.
      pose proof (dladder_block_ub (N.to_nat rem) 0%N (d-3)%N M
        ltac:(rewrite N2Nat.id; lia) ltac:(lia)) as H2.
      rewrite N.mul_0_r, N.add_0_r.
      eapply N.le_trans with
        (m := (434*M+2822) + (392*M+2800)).
      * apply N.add_le_mono; assumption.
      * nia.
    + rewrite (drunway_cons_ne 0%N d (e :: tail) p rem b
                ltac:(discriminate)).
      pose proof (dtransit1_quad_ub p b
        (wcolsum (d :: e :: tail)) M Hp Hb HM) as H1.
      assert (HMT : wcolsum (e :: tail) <= M).
      { eapply N.le_trans; [apply wcolsum_tail_le|exact HM]. }
      pose proof (IH 0%N rem (d-3)%N M ltac:(lia) Hr ltac:(lia)
                    HRest HMT) as H2.
      rewrite N.add_0_l.
      assert (HL : dtransit1 p b
        (wcolsum (d :: e :: tail)) <= 434 * (M+13)) by nia.
      eapply N.le_trans with
        (m := 434 * (M+13) +
              434 * (M+13) *
                (N.of_nat (length (e :: tail)) + 1)).
      * apply N.add_le_mono; assumption.
      * cbn [length]. repeat rewrite Nat2N.inj_succ.
        repeat rewrite <- N.add_1_r. ring_simplify.
        apply N.le_refl.
Qed.
Lemma drunway_zero_quad_ub (rl : list N) (p rem b M : N) :
  p < 28 -> rem < 28 -> b <= M ->
  Forall (fun x => x <= M) rl ->
  wcolsum rl <= M ->
  drunway 0%N rl p rem b
    <= 20 * (M + 13) * (M + 22).
Proof.
  intros Hp Hr Hb HF HM.
  pose proof (drunway_zero_linear_ub rl p rem b M Hp Hr Hb HF HM) as H.
  pose proof (wcolsum_length22_core rl) as HL.
  eapply N.le_trans; [exact H|].
  replace (434 * (M+13) * (N.of_nat (length rl)+1))%N
    with ((M+13) * (434 * (N.of_nat (length rl)+1)))%N by ring.
  replace (20 * (M+13) * (M+22))%N
    with ((M+13) * (20 * (M+22)))%N by ring.
  apply N.mul_le_mono_l. nia.
Qed.
Lemma drunway_zero_ticks_ub (rl : list N) (p rem b M tk : N) :
  p < 28 -> rem < 28 -> b <= M ->
  Forall (fun x => x <= M) rl ->
  wcolsum rl <= M ->
  length rl = N.to_nat ((p + tk) / 28) ->
  drunway 0%N rl p rem b
    <= 16 * (M + 13) * (tk + 55).
Proof.
  intros Hp Hr Hb HF HM HLen.
  pose proof (drunway_zero_linear_ub rl p rem b M Hp Hr Hb HF HM) as H.
  assert (EL : N.of_nat (length rl) = (p+tk)/28).
  { rewrite HLen, N2Nat.id. reflexivity. }
  pose proof (N.mul_div_le (p+tk) 28 ltac:(lia)) as HDiv.
  assert (HC :
    434 * (N.of_nat (length rl) + 1) <= 16 * (tk + 55)).
  { rewrite EL. nia. }
  eapply N.le_trans; [exact H|].
  replace (434 * (M+13) * (N.of_nat (length rl)+1))%N
    with ((M+13) * (434 * (N.of_nat (length rl)+1)))%N by ring.
  replace (16 * (M+13) * (tk+55))%N
    with ((M+13) * (16 * (tk+55)))%N by ring.
  apply N.mul_le_mono_l. exact HC.
Qed.
Definition slotq (M tk : N) : N :=
  17 * M * tk + 5 * tk * tk + 880 * M + 214 * tk + 11440.
Lemma slotq_mono (aM aq bM bq : N) :
  aM <= bM -> aq <= bq -> slotq aM aq <= slotq bM bq.
Proof.
  intros HM Hq.
  pose proof (N.mul_le_mono aM bM aq bq HM Hq) as Hprod.
  pose proof (N.mul_le_mono aq bq aq bq Hq Hq) as Hsq.
  unfold slotq. nia.
Qed.
Lemma flight_slot_ticks_ub (base tk : N) (rl : list N)
      (p rem b T M : N) :
  p < 28 -> rem < 28 -> base <= M -> b <= M ->
  Forall (fun x => x <= M) rl ->
  wcolsum rl <= M ->
  length rl = N.to_nat ((p + tk) / 28) ->
  chi (d_flight_slot base tk
    (drunway 0%N rl p rem b) T)
    <= slotq M tk + T.
Proof.
  intros Hp Hr Hbase Hb HF HM HLen.
  pose proof (drunway_zero_ticks_ub rl p rem b M tk
    Hp Hr Hb HF HM HLen) as HD.
  pose proof (N.mul_div_le (tk * (tk-1)) 2 ltac:(lia)) as HH.
  unfold d_flight_slot, d_flight,
         cx, chi, slotq. cbn [snd]. nia.
Qed.
Lemma flight_slot_quad_ub (base tk : N) (rl : list N)
      (p rem b T M : N) :
  p < 28 -> rem < 28 -> base <= M -> tk <= 3 * M -> b <= M ->
  Forall (fun x => x <= M) rl ->
  wcolsum rl <= M ->
  chi (d_flight_slot base tk
    (drunway 0%N rl p rem b) T)
    <= 68 * (M + 32) * (M + 32) + T.
Proof.
  intros Hp Hr Hbase Htk Hb HF HM.
  pose proof (drunway_zero_quad_ub rl p rem b M Hp Hr Hb HF HM) as HD.
  pose proof (N.mul_div_le (tk * (tk-1)) 2 ltac:(lia)) as HH.
  unfold d_flight_slot, d_flight,
         cx, chi. cbn [snd]. nia.
Qed.
Lemma of_nat_le_compat (a b : nat) :
  (a <= b)%nat -> N.of_nat a <= N.of_nat b.
Proof.
  intros H. apply (proj1 (N.compare_le_iff _ _)).
  rewrite N2Nat.inj_compare, !Nat2N.id.
  apply (proj2 (PeanoNat.Nat.compare_le_iff _ _)). exact H.
Qed.
Lemma wrungs_length (w : word) :
  (length (wrungs w) <= length w)%nat.
Proof.
  revert w. fix IH 1. intros w. destruct w as [|a [|b t]];
    cbn [wrungs length]; [lia|lia|].
  pose proof (IH t). lia.
Qed.
Lemma wrungs_length2 (w : word) :
  (2 * length (wrungs w) <= length w)%nat.
Proof.
  revert w. fix IH 1. intros w. destruct w as [|a [|b t]];
    cbn [wrungs length]; [lia|lia|].
  pose proof (IH t). lia.
Qed.
Lemma rc_group_ub (g : bg) :
  is_col g = true ->
  rc (gC g) <= 2 * ccg g + 22.
Proof.
  destruct g as [[o z] c]. cbn [is_col gO gZ gC].
  intros H. apply andb_prop in H as [_ Ho]. apply N.leb_le in Ho.
  cbn [gO] in Ho.
  unfold rc, ccg. cbn [gO gC].
  replace (14*c)%N with (c*14)%N by ring.
  replace (2 * (c * (2*o+6)) + 22)%N
    with (c * (2 * (2*o+6)) + 22)%N by ring.
  apply (proj1 (N.add_le_mono_r _ _ 22)).
  apply N.mul_le_mono_l. lia.
Qed.
Lemma wrungs_mass_ub (w : word) :
  forallb is_col w = true ->
  wcolsum (wrungs w)
  <= 2 * ccolcost w
     + 22 * N.of_nat (length (wrungs w)).
Proof.
  revert w. fix IH 1. intros w HC. destruct w as [|a [|b t]].
  - reflexivity.
  - cbn [wrungs wcolsum ccolcost length]. lia.
  - cbn [forallb] in HC. apply andb_prop in HC as (Ha & HC).
    apply andb_prop in HC as (Hb & Ht).
    cbn [wrungs wcolsum ccolcost length].
    rewrite Nat2N.inj_succ.
    replace (N.succ (N.of_nat (length (wrungs t))))
      with (N.of_nat (length (wrungs t)) + 1)%N by lia.
    pose proof (rc_group_ub b Hb) as HB.
    unfold ccg in HB.
    pose proof (IH t Ht) as HT.
    pose proof (N.add_le_mono _ _ _ _ HB HT) as HS.
    eapply N.le_trans; [exact HS|].
    replace
      (2 *
         (gC a * (2 * gO a + 6) +
          (gC b * (2 * gO b + 6) + ccolcost t)) +
       22 * (N.of_nat (length (wrungs t)) + 1))%N
      with
      (((2 * (gC b * (2 * gO b + 6)) + 22) +
        (2 * ccolcost t +
         22 * N.of_nat (length (wrungs t)))) +
       2 * (gC a * (2 * gO a + 6)))%N by ring.
    apply N.le_add_r.
Qed.
Lemma lmom_ub (l : list N) : forall a,
  lmom l a
  <= (a + 4 * N.of_nat (length l)) * wcolsum l.
Proof.
  induction l as [|x t IH]; intros a.
  - cbn [lmom wcolsum length]. lia.
  - cbn [lmom wcolsum length].
    rewrite Nat2N.inj_succ.
    pose proof (IH (a+4)%N) as H.
    unfold rc. nia.
Qed.
Lemma sched_grants_le (slot take : N) :
  lin_sched_grants slot take <= take + 3.
Proof.
  unfold lin_sched_grants.
  apply N.div_le_upper_bound; [discriminate|].
  assert (3-slot <= 3)%N by lia. nia.
Qed.
Lemma sched_grants_quarter (slot take : N) :
  4 * lin_sched_grants slot take <= take + 3.
Proof.
  unfold lin_sched_grants.
  pose proof (N.mul_div_le (take + (3-slot)) 4 ltac:(lia)) as H.
  assert (3-slot <= 3)%N by lia. lia.
Qed.
Lemma bulk_stockw_length (sg : list seg) (cols : word)
      (gap : nat) (slot take : N) :
  2 * N.of_nat (length (bulk_stockw sg cols gap slot take))
  <= take + 3.
Proof.
  unfold bulk_stockw.
  pose proof (length_skipn
    (gap - 2 * N.to_nat (lin_sched_grants slot take))%nat
    (firstn gap (lin_flat sg cols))) as E.
  pose proof (length_firstn gap (lin_flat sg cols)) as EF.
  assert (HL :
    (length (skipn
       (gap - 2 * N.to_nat (lin_sched_grants slot take))%nat
       (firstn gap (lin_flat sg cols)))
     <= 2 * N.to_nat (lin_sched_grants slot take))%nat) by lia.
  pose proof (of_nat_le_compat _ _ HL) as HN.
  rewrite Nat2N.inj_mul, N2Nat.id in HN.
  pose proof (sched_grants_quarter slot take) as HG. nia.
Qed.
Definition carm (M q : N) : N :=
  3 * M * q + 6 * q * q + 547 * M + 54 * q + 8000.
Lemma carm_mono (aM aq bM bq : N) :
  aM <= bM -> aq <= bq -> carm aM aq <= carm bM bq.
Proof.
  intros HM Hq.
  pose proof (N.mul_le_mono aM bM aq bq HM Hq) as Hprod.
  pose proof (N.mul_le_mono aq bq aq bq Hq Hq) as Hsq.
  unfold carm. nia.
Qed.
Definition BMAX : N := TERM_UB + 7 + ALLOW.
Definition flightq (M0 M1 q : N) : N :=
  slotq M0 q
  + N.of_nat CFUEL * carm (M1 + 8*q) q.
Transparent CFUEL.
Lemma cfuel_num : N.of_nat CFUEL = 67%N.
Proof. unfold CFUEL. reflexivity. Qed.
Opaque CFUEL.
Lemma flightq_from (M0 M1 q T : N) :
  T <= N.of_nat CFUEL * carm (M1 + 8*q) q ->
  slotq M0 q + T
    <= flightq M0 M1 q.
Proof.
  intros HT. unfold flightq. lia.
Qed.
Lemma flightq_mono (a0 a1 aq b0 b1 bq : N) :
  a0 <= b0 -> a1 <= b1 -> aq <= bq ->
  flightq a0 a1 aq <= flightq b0 b1 bq.
Proof.
  intros H0 H1 Hq. unfold flightq. apply N.add_le_mono.
  - apply slotq_mono; assumption.
  - apply N.mul_le_mono_l, carm_mono; nia.
Qed.
Lemma flightq_numeric :
  flightq BMAX BMAX RET <= CoarseC_FLIGHT_UB.
Proof.
  unfold flightq, slotq, carm, BMAX,
         CoarseC_FLIGHT_UB, CoarseC_BOUND_MAX.
  rewrite cfuel_num. reflexivity.
Qed.
Lemma flightq_numeric_wide :
  flightq BMAX BMAX (3 * BMAX) <= CoarseC_FLIGHT_UB_WIDE.
Proof.
  unfold flightq, slotq, carm, BMAX, CoarseC_FLIGHT_UB_WIDE,
         CoarseC_BOUND_MAX.
  rewrite cfuel_num. reflexivity.
Qed.
Lemma flightq_close (M0 M1 q : N) :
  M0 <= BMAX -> M1 <= BMAX -> q <= 3 * BMAX ->
  flightq M0 M1 q <= CoarseC_flight_ub q.
Proof.
  intros H0 H1 Hq. unfold CoarseC_flight_ub.
  destruct (q <=? RET)%N eqn:EQ.
  - apply N.leb_le in EQ.
    eapply N.le_trans; [apply flightq_mono|exact flightq_numeric]; assumption.
  - eapply N.le_trans; [apply flightq_mono|exact flightq_numeric_wide];
      assumption.
Qed.
Lemma flat_firstn_cost_le (sg : list seg) (w : word) (j : nat) :
  ccolcost (lin_flat sg (firstn j w))
    <= ccolcost (lin_flat sg w).
Proof.
  pose proof (flat_firstn_skipn sg w j) as E.
  rewrite E, ccolcost_app. lia.
Qed.
Lemma literal_site_base_le (sg : list seg) (w : word)
      (f p b : N) (j : nat) :
  wat w j = Some (4,2,b + DBu p)%N ->
  b <= gmeas (lin_flat sg w) f.
Proof.
  unfold wat. intros HW.
  destruct (nth_error_split w j HW) as (pre & post & EW & _).
  assert (HK : keyb sg (4,2,b + DBu p)%N = None)
    by (cbn [keyb keyi phshape tagbase PHO]; reflexivity).
  unfold gmeas.
  rewrite EW, lin_flat_app_c.
  cbn [lin_flat]. rewrite HK.
  rewrite ccolcost_app, ccolcost_cons.
  assert (HG : b <= ccg (4,2,b + DBu p)%N).
  { unfold ccg. cbn [gC gO]. nia. }
  lia.
Qed.
Lemma wcolsum_length22 (rl : list N) :
  22 * N.of_nat (length rl) <= wcolsum rl.
Proof.
  induction rl as [|d rest IH]; [reflexivity|].
  cbn [length wcolsum]. rewrite Nat2N.inj_succ. lia.
Qed.
Lemma flight_ticks_le (p tk rem c : N) (cs : list N) (M : N) :
  p < 28 ->
  rem = ((p + tk) mod 28)%N ->
  length (c :: cs) = N.to_nat ((p + tk) / 28) ->
  Forall (fun x => (FLOOR + 3 <= x)%N) (c :: cs) ->
  wcolsum (c :: cs) <= M ->
  tk <= 3 * M.
Proof.
  intros Hp Hrem Hlen Hsafe HM.
  assert (HL : N.of_nat (length (c :: cs)) = (p+tk)/28).
  { rewrite Hlen, N2Nat.id. reflexivity. }
  assert (Hr : rem < 28).
  { rewrite Hrem. apply N.mod_lt. discriminate. }
  pose proof (N.div_mod' (p+tk) 28) as HDiv.
  pose proof (wcolsum_length22 (c :: cs)) as H22.
  inversion Hsafe as [|c_0 cs0 Hc _]; subst c_0 cs0.
  cbn [wcolsum] in HM, H22.
  unfold FLOOR in Hc.
  lia.
Qed.
Lemma flat_prefix_cols_cost_le (sg : list seg) (w cols s : word)
      (cur : nat) :
  seek (skipn cur w) = (cols, s) ->
  ccolcost (lin_flat sg (firstn cur w)) +
  ccolcost (lin_flat sg cols)
  <= ccolcost (lin_flat sg w).
Proof.
  intros HS.
  destruct (seek_split (skipn cur w) cols s HS) as (EW & _).
  pose proof (flat_firstn_skipn sg w cur) as EAll.
  rewrite EW, lin_flat_app_c in EAll.
  rewrite EAll, !ccolcost_app. lia.
Qed.
Lemma site_base_le (sg : list seg) (s POST : word)
      (p b M : N) :
  lin_flat sg s =
    phase_form p ++ (4,2,b + DBu p)%N :: POST ->
  ccolcost (lin_flat sg s) <= M -> b <= M.
Proof.
  intros ES HM. rewrite ES in HM.
  rewrite ccolcost_app, ccolcost_cons,
          ccg_unfold in HM.
  cbn [gC gO] in HM. lia.
Qed.
Lemma wcolsum_levels_le (l : list N) (M : N) :
  wcolsum l <= M -> Forall (fun x => x <= M) l.
Proof.
  induction l as [|x t IH]; intros H; [constructor|].
  cbn [wcolsum] in H. constructor; [lia|].
  apply IH. lia.
Qed.
Lemma bulk_stock_cost_le (sg : list seg) (cols : word)
      (gap : nat) (slot take : N) :
  ccolcost (bulk_stockw sg cols gap slot take)
  <= ccolcost (lin_flat sg cols).
Proof.
  unfold bulk_stockw.
  eapply N.le_trans.
  - apply ccolcost_skipn_le.
  - apply ccolcost_firstn_le.
Qed.
Lemma bulk_stock_cols (sg : list seg) (cols : word)
      (gap : nat) (slot take : N) :
  delivery_cols (lin_flat sg cols) = true ->
  forallb is_col (bulk_stockw sg cols gap slot take) = true.
Proof.
  intros HC. unfold bulk_stockw.
  apply forallb_skipn,
        forallb_firstn,
        delivery_cols_is_col. exact HC.
Qed.
Lemma surcharge_arith (take a ell M : N) :
  a <= 3 -> 4 * ell <= take + 3 ->
  (a + 4 * ell) * (2 * M + 22 * ell)
  <= (take + 6) * (2 * M + 6 * take + 18).
Proof.
  intros Ha Hl.
  apply N.mul_le_mono; nia.
Qed.
Lemma bulk_surcharge_ub (sg : list seg) (cols : word)
      (gap : nat) (slot take M : N) :
  delivery_cols (lin_flat sg cols) = true ->
  ccolcost (lin_flat sg cols) <= M ->
  bulk_surcharge sg cols gap slot take
  <= (take + 6) * (2 * M + 6 * take + 18).
Proof.
  intros HCols HCM.
  unfold bulk_surcharge.
  set (stock := bulk_stockw sg cols gap slot take).
  set (rl := wrungs stock).
  set (a := ((take + 3 - slot) mod 4)%N).
  pose proof (lmom_ub rl a) as HMom.
  pose proof (wrungs_mass_ub stock
    ltac:(subst stock; apply bulk_stock_cols; exact HCols)) as HMass.
  pose proof (bulk_stock_cost_le sg cols gap slot take) as HStock.
  pose proof (bulk_stockw_length sg cols gap slot take) as HLen.
  assert (Ha : (a <= 3)%N).
  { assert (a < 4)%N by (unfold a; apply N.mod_lt; lia). lia. }
  assert (HR : (4 * N.of_nat (length rl) <= take + 3)%N).
  { pose proof (of_nat_le_compat _ _ (wrungs_length2 stock)) as HWr.
    rewrite Nat2N.inj_mul in HWr. cbn [N.of_nat] in HWr.
    unfold rl in HWr |- *.
    change (2 * N.of_nat (length (wrungs stock)) <=
            N.of_nat (length stock))%N in HWr.
    change (2 * N.of_nat (length stock) <= take + 3)%N in HLen.
    nia. }
  assert (HMassM :
    wcolsum rl <=
      2 * M + 22 * N.of_nat (length rl)).
  { unfold rl in HMass |- *.
    eapply N.le_trans; [exact HMass|].
    apply N.add_le_mono_r, N.mul_le_mono_l.
    subst stock. eapply N.le_trans; [exact HStock|exact HCM]. }
  pose proof (surcharge_arith take a (N.of_nat (length rl)) M
                Ha HR) as HAri.
  eapply N.le_trans; [exact HMom|].
  eapply N.le_trans; [apply N.mul_le_mono_l; exact HMassM|exact HAri].
Qed.
Lemma dbulkp_carm (sg : list seg) (w cols s POST : word)
      (f : N) (cur gap : nat) (slot p take b : N) :
  seek (skipn cur w) = (cols, s) ->
  p < 28 -> p + take < 28 ->
  lin_flat sg s =
    phase_form p ++ (4,2,b + DBu p)%N :: POST ->
  delivery_cols (lin_flat sg cols) = true ->
  chi (dbulkp sg cols s gap slot p take)
  <= carm (gmeas (lin_flat sg w) f) take.
Proof.
  intros HSeek Hp Hpt ESite HCols.
  set (M := gmeas (lin_flat sg w) f).
  pose proof (flat_seek_cost_le sg w cols s cur HSeek) as HParts.
  assert (HColsM : ccolcost (lin_flat sg cols) <= M).
  { unfold M, gmeas. lia. }
  assert (HSiteM : ccolcost (lin_flat sg s) <= M).
  { unfold M, gmeas. lia. }
  assert (Hb : b <= M) by (eapply site_base_le; eassumption).
  pose proof (dladder_block_ub (N.to_nat take) p b M
    ltac:(rewrite N2Nat.id; lia) Hb) as HLad.
  pose proof (bulk_surcharge_ub sg cols gap slot take M
    HCols HColsM) as HSurch.
  unfold dbulkp.
  rewrite <- (layout_base sg s POST p b Hp ESite).
  rewrite wcolcost_ccolcost.
  cbn [chi cx snd].
  change
    (dladder p b (N.to_nat take) +
       take * ccolcost (skipn gap (lin_flat sg cols)) +
       bulk_surcharge sg cols gap slot take <= carm M take)%N.
  pose proof (ccolcost_skipn_le (lin_flat sg cols) gap) as HSkip.
  assert (HW : ccolcost (skipn gap (lin_flat sg cols)) <= M)
    by lia.
  assert (HTW :
    take * ccolcost (skipn gap (lin_flat sg cols)) <= take * M)
    by (apply N.mul_le_mono_l; exact HW).
  eapply N.le_trans with
    (m := ((392*M+2800) + take*M +
           (take+6)*(2*M+6*take+18))%N).
  - lia.
  - unfold carm. nia.
Qed.
Lemma dbulkn_carm (sg : list seg)
      (w cols s PRE POST : word) (c : N) (cs : list N)
      (f : N) (cur gap : nat) (slot p take b : N) :
  seek (skipn cur w) = (cols, s) ->
  p < 28 ->
  lin_flat sg (firstn cur w) ++ lin_flat sg cols =
    PRE ++ runway (c :: cs) ->
  lin_flat sg s =
    phase_form p ++ (4,2,b + DBu p)%N :: POST ->
  length (c :: cs) = N.to_nat ((p + take) / 28) ->
  delivery_cols (lin_flat sg cols) = true ->
  chi (dbulkn sg w cols s cur gap slot p take)
  <= carm (gmeas (lin_flat sg w) f) take.
Proof.
  intros HSeek Hp EPre ESite HLen HCols.
  set (M := gmeas (lin_flat sg w) f).
  pose proof (flat_prefix_cols_cost_le sg w cols s cur HSeek) as HPrefix.
  assert (HRun :
    ccolcost (runway (c :: cs)) <= M).
  { rewrite <- ccolcost_app in HPrefix.
    rewrite EPre, ccolcost_app in HPrefix.
    unfold M, gmeas. lia. }
  assert (HLevM : Forall (fun x => x <= M) (c :: cs)).
  { apply wcolsum_levels_le.
    rewrite <- ccolcost_runway. exact HRun. }
  assert (HLevR : Forall (fun x => x <= M) (rev (c :: cs)))
    by (apply Forall_rev; exact HLevM).
  pose proof (flat_seek_cost_le sg w cols s cur HSeek) as HParts.
  assert (HColsM : ccolcost (lin_flat sg cols) <= M).
  { unfold M, gmeas. lia. }
  assert (HSiteM : ccolcost (lin_flat sg s) <= M).
  { unfold M, gmeas. lia. }
  assert (Hb : b <= M) by (eapply site_base_le; eassumption).
  assert (Hrem : ((p + take) mod 28 < 28)%N)
    by (apply N.mod_lt; discriminate).
  assert (HMassR : wcolsum (rev (c :: cs)) <= M).
  { rewrite wcolsum_rev.
    rewrite <- ccolcost_runway. exact HRun. }
  pose proof (dlocals_mass_ub (rev (c :: cs))
    p ((p+take) mod 28) b Hp Hrem) as HLoc.
  pose proof (bulk_surcharge_ub sg cols gap slot take M
    HCols HColsM) as HSurch.
  unfold dbulkn. cbv zeta.
  rewrite <- (layout_levels sg _ PRE c cs _ EPre HLen).
  rewrite <- (layout_base sg s POST p b Hp ESite).
  rewrite wcolcost_ccolcost.
  cbn [chi cx snd].
  apply N.le_trans with
    (m := (take * ccolcost (skipn gap (lin_flat sg cols)) +
           dlocals (rev (c :: cs)) p ((p+take) mod 28) b +
           bulk_surcharge sg cols gap slot take)%N).
  - apply N.le_sub_l.
  - assert (HW : ccolcost (skipn gap (lin_flat sg cols)) <= M).
    { pose proof (ccolcost_skipn_le (lin_flat sg cols) gap).
      lia. }
    assert (HTW :
      take * ccolcost (skipn gap (lin_flat sg cols)) <= take * M)
      by (apply N.mul_le_mono_l; exact HW).
    assert (HMass129 :
      129 * wcolsum (rev (c :: cs)) <= 129 * M)
      by (apply N.mul_le_mono_l; exact HMassR).
    assert (HLoc2 :
      dlocals (rev (c :: cs)) p ((p+take) mod 28) b
      <= 535*M + 2800) by nia.
    eapply N.le_trans with
      (m := (take*M + (535*M+2800)
             + (take+6)*(2*M+6*take+18))%N).
    + apply N.add_le_mono; [apply N.add_le_mono; [exact HTW|exact HLoc2]
                            |exact HSurch].
    + unfold carm. nia.
Qed.
Lemma armq_carm (a M q : N) : a <= M -> armq a <= carm M q.
Proof. unfold armq, carm. intros H. nia. Qed.
Lemma ladderq_carm (a M q : N) : a <= M -> ladderq a <= carm M q.
Proof. unfold ladderq, armq, carm. intros H. nia. Qed.
Lemma flat_setsfx_suffix_le (sg : list seg) (w lw : word)
      (f : N) (base : nat) :
  (base <= length w)%nat ->
  gmeas (lin_flat sg lw) f
  <= gmeas (lin_flat sg (setsfx base w lw)) f.
Proof.
  intros HB. rewrite (setsfx_app base w lw HB), lin_flat_app_c.
  unfold gmeas. rewrite ccolcost_app. lia.
Qed.
Lemma emt_succ_grid_b :
  forallb (fun p => (EMt (p+1) <=? EMt p + 1)%N)
          pgrid = true.
Proof. vm_compute. reflexivity. Qed.
Lemma emt_succ_le (p : N) : p < 28 ->
  EMt (p+1) <= EMt p + 1.
Proof.
  intros Hp.
  pose proof (proj1 (forallb_forall _ pgrid)
    emt_succ_grid_b p (in_pgrid p Hp)) as H.
  apply N.leb_le in H. exact H.
Qed.
Lemma marks_succ_le (a : N) :
  marks (a+1) <= marks a + 1.
Proof.
  set (q := a / 28). set (r := a mod 28).
  assert (Hr : r < 28) by (unfold r; apply N.mod_lt; discriminate).
  assert (Ea : 28*q + r = a).
  { unfold q, r. symmetry. apply N.div_mod'. }
  rewrite <- Ea.
  rewrite (marks_split q r Hr).
  destruct (r =? 27)%N eqn:Er.
  - apply N.eqb_eq in Er. subst r.
    rewrite Er.
    replace (28*q + 27 + 1)%N with ((q+1)*28)%N by ring.
    assert (Enew : marks ((q+1)*28) = 4*(q+1)).
    { rewrite N.mul_comm. apply marks_full. }
    rewrite Enew.
    rewrite marks_is_EMt by lia.
    vm_compute EMt. lia.
  - apply N.eqb_neq in Er.
    assert (Hr1 : r+1 < 28) by lia.
    replace (28*q + r + 1)%N with (28*q+(r+1))%N by ring.
    rewrite (marks_split q (r+1) Hr1).
    rewrite !marks_is_EMt by lia.
    pose proof (emt_succ_le r Hr). lia.
Qed.
Lemma marks_span_le (a t : N) :
  marks (a+t) - marks a <= t.
Proof.
  remember (N.to_nat t) as n eqn:En.
  assert (Et : t = N.of_nat n).
  { subst n. symmetry. apply N2Nat.id. }
  subst t. clear En.
  assert (H : forall n,
    marks (a + N.of_nat n)
    <= marks a + N.of_nat n).
  { intros k. induction k as [|k IH].
    - cbn [N.of_nat]. rewrite !N.add_0_r. apply N.le_refl.
    - rewrite Nat2N.inj_succ.
      replace (a + N.succ (N.of_nat k))%N
        with (a + N.of_nat k + 1)%N by lia.
      replace (marks a + N.succ (N.of_nat k))%N
        with (marks a + N.of_nat k + 1)%N by lia.
      pose proof (marks_succ_le (a + N.of_nat k)) as HS. lia. }
  pose proof (H n). lia.
Qed.
Lemma bulk_emit_le (p take emit : N) :
  emit = (marks (p+take) - marks p)%N ->
  emit <= take.
Proof. intros ->. apply marks_span_le. Qed.
Lemma cascticks_bulk_le (fr : lsc_frame) (rest : list lsc_frame)
      (nh : nat) (rem emit p take : N) :
  take <= lsTicks fr -> emit <= take ->
  cascticks
    (lin_sched_child nh rem emit p take ::
     lin_sched_advance fr take :: rest)
  <= cascticks (fr :: rest).
Proof.
  intros HT HE. rewrite !cascticks_cons.
  rewrite ticks_child, ticks_advance. lia.
Qed.
Lemma ccasc_success_CE (fu : nat) (sg : list seg) (ps : atab)
      (w : word) (f : N) (st : list lsc_frame)
      (w' : word) (sg' : list seg) (ps' : atab) (f' : N)
      (d : cost) :
  stable_guard sg w ->
  lin_guard sg w = true ->
  is_spc (nth O w d0) = false ->
  Forall frame_pos st ->
  ccasc fu sg ps w f st = (Some (w',sg',ps',f'),d) ->
  CE d.
Proof.
  intros HG HGuard HHead HFrames HR.
  destruct (ccasc_exact fu sg ps w f st w' sg' ps' f' d
              HG HGuard HHead HFrames HR) as (T & ->).
  unfold CE, cx, clo, chi. reflexivity.
Qed.
Lemma ccasc_dom (fu : nat) (sg : list seg) (ps : atab)
      (w : word) (f : N) (st : list lsc_frame)
      (w' : word) (sg' : list seg) (ps' : atab) (f' : N)
      (d : cost) :
  stable_guard sg w ->
  lin_guard sg w = true ->
  is_spc (nth O w d0) = false ->
  Forall frame_pos st ->
  ccasc fu sg ps w f st = (Some (w',sg',ps',f'),d) ->
  FlightDomC_cmeas sg w f
  <= FlightDomC_cmeas sg' w' f' + 8 * cascticks st.
Proof.
  intros HG HGuard HHead HFrames HR.
  assert (HS : lin_casc_safe_at fu sg ps w f st
               = Some (w',sg',ps',f')).
  { pose proof (f_equal fst HR) as H.
    rewrite ccasc_proj in H. exact H. }
  exact (cascdom_ofS fu sg ps w f st w' sg' ps' f'
           (conj HG (conj HGuard HHead)) HFrames HS).
Qed.
Lemma fuel_step_arith (fu : nat) (A B C : N) :
  A <= C -> B <= N.of_nat fu * C ->
  A + B <= N.of_nat (S fu) * C.
Proof. rewrite Nat2N.inj_succ, N.mul_succ_l. lia. Qed.
Lemma fuel_carm_mono (fu : nat) (a b : N) :
  forall aq bq,
  a <= b -> aq <= bq ->
  N.of_nat fu * carm a aq <= N.of_nat fu * carm b bq.
Proof.
  intros aq bq HM Hq. apply N.mul_le_mono_l, carm_mono; assumption.
Qed.
Lemma flat_site_base_at (sg : list seg) (w : word) (j : nat)
      (p take : N) (r : word * list seg * nat * N * N) :
  detect_phase w j = Some p ->
  lin_bulk sg w j p take = Some r ->
  exists (b : N) (POST : word),
    lin_flat sg (skipn j w) =
      phase_form p ++
        (4,2,b + DBu p)%N :: POST.
Proof.
  intros HD HB.
  destruct (lin_bulk_checks sg w j p take r HB)
    as (gb & HWat & HKey & HLvl & HFloor & HEnd).
  destruct (site_layout w j p gb HD HWat HEnd)
    as (HLayout & HJ & _).
  destruct (detect_phase_form w j p HD) as (Hp & _).
  destruct (lvl_big_shape gb HLvl) as (c & ->).
  assert (ESk : skipn j w =
    phase_form p ++ (4,2,c)%N ::
      skipn (S (j + phase_len p)) w).
  { transitivity (skipn (length (firstn j w))
      (firstn j w ++ (phase_form p ++ (4,2,c)%N ::
       skipn (S (j + phase_len p)) w))).
    - rewrite HJ. f_equal. exact HLayout.
    - apply LineageCascade_skipn_len_app. }
  assert (EFlat : lin_flat sg (skipn j w) =
    phase_form p ++ (4,2,c)%N ::
      lin_flat sg (skipn (S (j + phase_len p)) w)).
  { rewrite ESk, lin_flat_app_c, (flat_phase_form sg p Hp).
    f_equal. }
  exists (c - DBu p)%N,
         (lin_flat sg (skipn (S (j + phase_len p)) w)).
  rewrite EFlat.
  replace (c - DBu p + DBu p)%N with c.
  - reflexivity.
  - cbn [gC] in HFloor. lia.
Qed.
Lemma lin_bulk_emit_eq (sg : list seg) (w w' : word)
      (j nh : nat) (p take rem emit : N) (sg' : list seg) :
  lin_bulk sg w j p take = Some (w',sg',nh,rem,emit) ->
  emit = (marks (p+take) - marks p)%N.
Proof.
  unfold lin_bulk. cbv zeta.
  repeat
    match goal with
    | |- context [match ?x with _ => _ end] => destruct x eqn:?
    | |- context [if ?b then _ else _] => destruct b eqn:?
    end;
    intros H; try discriminate H; injection H as <- <- <- <- <-;
    reflexivity.
Qed.
Lemma dbulkc_carm (sg : list seg) (w cols s : word)
      (f : N) (cur gap : nat) (slot p take : N)
      (w2 : word) (sg2 : list seg) (nh : nat) (rem emit : N) :
  stable_guard sg w ->
  is_spc (nth O w d0) = false ->
  seek (skipn cur w) = (cols,s) ->
  detect_phase w (cur + length cols)%nat = Some p ->
  lin_bulk sg w (cur + length cols)%nat p take
    = Some (w2,sg2,nh,rem,emit) ->
  sg_wf sg2 ->
  delivery_cols (lin_flat sg cols) = true ->
  chi (dbulkc sg w cols s cur gap slot p take)
  <= carm (FlightDomC_cmeas sg w f) take.
Proof.
  intros HG HHead HSeek HD HB HW2 HFlatCols.
  pose proof HG as HG0.
  destruct HG as ((HOk & _) & _ & HW & _ & _ & _).
  destruct (detect_phase_form w (cur + length cols)%nat p HD)
    as (Hp & _).
  unfold dbulkc.
  destruct (Nat.eqb (N.to_nat ((p+take)/28)) O) eqn:HFull.
  - destruct (flat_site_base_at sg w (cur + length cols)%nat p take
                (w2,sg2,nh,rem,emit) HD HB) as (b & POST & ESite).
    rewrite (skipn_seek_at w cur cols s HSeek) in ESite.
    exact (dbulkp_carm sg w cols s POST f cur gap slot p take b HSeek Hp
             (bulk_full_zero_lt28 p take HFull) ESite HFlatCols).
  - destruct (lin_bulk_cursor_layout sg w cur cols s
                (cur + length cols)%nat p take w2 sg2 nh rem emit
                HW HOk (stable_altb sg w HG0) HHead HSeek eq_refl
                HD HFull HB HW2)
      as (PRE & POST & c & cs & b & EPre & ESite & _ & _ & _ & _ & _
          & HLen & _ & _ & _ & _ & _).
    exact (dbulkn_carm sg w cols s PRE POST c cs f cur gap slot p take b
             HSeek Hp EPre ESite HLen HFlatCols).
Qed.
Theorem ccasc_fuel_bound :
  forall (fu : nat) (sg : list seg) (ps : atab) (w : word)
         (f : N) (st : list lsc_frame) (w' : word)
         (sg' : list seg) (ps' : atab) (f' : N) (d : cost),
  stable_guard sg w ->
  lin_guard sg w = true ->
  is_spc (nth O w d0) = false ->
  Forall frame_pos st ->
  ccasc fu sg ps w f st = (Some (w',sg',ps',f'),d) ->
  chi d <=
    N.of_nat fu * carm
      (FlightDomC_cmeas sg' w' f' + 8 * cascticks st)
      (cascticks st).
Proof.
  induction fu as [|fu IH];
    intros sg ps w f st w' sg' ps' f' d HG HGuard HHead HFrames HRun.
  - cbn [ccasc] in HRun. discriminate HRun.
  - pose proof (ccasc_dom (S fu) sg ps w f st w' sg' ps' f' d
                  HG HGuard HHead HFrames HRun) as HWholeDom.
    destruct st as [|fr rest].
    + cbn [ccasc] in HRun.
      injection HRun as <- <- <- <- <-.
      cbn [chi czero snd cascticks]. lia.
    + inversion HFrames as [|fr0 rest0 HFr HRest]; subst fr0 rest0.
      cbn [ccasc] in HRun. cbv beta zeta in HRun.
      destruct (lsTicks fr =? 0)%N eqn:ETicks.
      * pose proof (IH sg ps w f rest w' sg' ps' f' d
                      HG HGuard HHead HRest HRun) as HR.
        assert (HQ : cascticks rest <=
                     cascticks (fr :: rest)).
        { rewrite cascticks_cons. apply N.eqb_eq in ETicks.
          rewrite ETicks. lia. }
        eapply N.le_trans; [exact HR|].
        eapply N.le_trans with
          (m := N.of_nat fu * carm
            (FlightDomC_cmeas sg' w' f' +
             8 * cascticks (fr :: rest))
            (cascticks (fr :: rest))).
        { apply fuel_carm_mono.
          - apply N.add_le_mono_l, N.mul_le_mono_l. exact HQ.
          - exact HQ. }
        rewrite Nat2N.inj_succ, N.mul_succ_l. lia.
      * destruct (seek (skipn (lsCur fr) w))
          as [cols s] eqn:HSeek.
        destruct s as [|g t]; [discriminate HRun|].
        cbn [fst snd] in HRun.
        destruct (seek_split (skipn (lsCur fr) w)
                    cols (g :: t) HSeek) as (HSplit & HCols).
        assert (HCurLen : (lsCur fr <= length w)%nat).
        { pose proof (f_equal (@length bg) HSplit) as HLen.
          rewrite length_skipn, length_app in HLen.
          cbn [length] in HLen. lia. }
        unfold frame_pos in HFr.
        pose proof HG as HG0.
        destruct HG as ((HOk & HPT) & HEdges & HWf & HShape & HKeys & HPos).
        destruct (lin_bottom_take cols (g :: t) f (lsTicks fr))
          as [take|] eqn:HBottom.
        -- destruct (clin_bottom_sched_zrun (N.to_nat take)
                       (lsCur fr - (lsCur fr - 2))%nat sg
                       (skipn (lsCur fr - 2)%nat w) f
                       (lsGap fr) (lsSlot fr))
             as [[[lw2 f2]|] dz] eqn:EZ; [|discriminate HRun].
           destruct (relocate_all sg ps
                       (setsfx (lsCur fr - 2)%nat w lw2))
             as [ps2|] eqn:HRel; [|discriminate HRun].
           destruct (lin_guard_at sg ps2
                       (setsfx (lsCur fr - 2)%nat w lw2))
             eqn:HAt; [|discriminate HRun].
           destruct (ccasc fu sg ps2
                       (setsfx (lsCur fr - 2)%nat w lw2) f2
                       (lin_sched_advance fr take :: rest))
             as [o d2] eqn:ERec.
           cbn [fst snd] in HRun. injection HRun as Ho Hd. subst o d.
           assert (HCurEq : lsCur fr =
             ((lsCur fr - 2) + (lsCur fr - (lsCur fr - 2)))%nat)
             by lia.
           assert (HBaseLen : ((lsCur fr - 2) <= length w)%nat) by lia.
           assert (HLcLen : ((lsCur fr - (lsCur fr - 2)) <=
                  length (skipn (lsCur fr - 2)%nat w))%nat)
             by (rewrite length_skipn; lia).
           assert (HZRun : lin_bottom_sched_zrun (N.to_nat take)
                     (lsCur fr - (lsCur fr - 2))%nat sg
                     (skipn (lsCur fr - 2)%nat w) f
                     (lsGap fr) (lsSlot fr) = Some (lw2, f2)).
           { rewrite <- (clin_bottom_sched_zrun_proj (N.to_nat take)
               (lsCur fr - (lsCur fr - 2))%nat sg
               (skipn (lsCur fr - 2)%nat w) f
               (lsGap fr) (lsSlot fr)). rewrite EZ. reflexivity. }
           assert (HG2 : stable_guard sg
                     (setsfx (lsCur fr - 2)%nat w lw2)).
           { eapply lin_bottom_global_stable.
             + exact HG0.
             + exact HCurEq.
             + reflexivity.
             + exact HBaseLen.
             + exact HLcLen.
             + exact HZRun. }
           assert (HGuard2 : lin_guard sg
                     (setsfx (lsCur fr - 2)%nat w lw2) = true).
           { eapply lin_guard_at_sound;
               [exact (proj1 (proj1 HG2))|exact HAt]. }
           assert (HHead2 : is_spc
                     (nth O (setsfx (lsCur fr - 2)%nat w lw2)
                          d0) = false).
           { eapply setsfx_head_nonspc; [lia|exact HBaseLen|exact HHead]. }
           assert (HFrames2 : Forall frame_pos
             (lin_sched_advance fr take :: rest)).
           { constructor.
             + apply frame_pos_advance. unfold frame_pos. exact HFr.
             + exact HRest. }
           pose proof (IH sg ps2
             (setsfx (lsCur fr - 2)%nat w lw2) f2
             (lin_sched_advance fr take :: rest)
             w' sg' ps' f' d2 HG2 HGuard2 HHead2 HFrames2 ERec) as HRec.
           assert (HRecCE : CE d2)
             by (eapply ccasc_success_CE; eassumption).
           assert (HLocalCE : CE dz).
           { exact (clin_bottom_sched_zrun_exact
               (N.to_nat take)
               (lsCur fr - (lsCur fr - 2))%nat sg
               (skipn (lsCur fr - 2)%nat w) f
               (lsGap fr) (lsSlot fr) lw2 f2 dz HWf EZ). }
           assert (HTake : take <= lsTicks fr)
             by (eapply lin_bottom_take_le; exact HBottom).
           assert (HQ : cascticks
                         (lin_sched_advance fr take :: rest)
                       <= cascticks (fr :: rest)).
           { rewrite !cascticks_cons, ticks_advance. lia. }
           pose proof (ccasc_dom fu sg ps2
             (setsfx (lsCur fr - 2)%nat w lw2) f2
             (lin_sched_advance fr take :: rest)
             w' sg' ps' f' d2 HG2 HGuard2 HHead2 HFrames2 ERec) as HRecDom.
           pose proof (flat_setsfx_suffix_le sg w lw2 f2
                         (lsCur fr - 2)%nat HBaseLen) as HSuffix.
           pose proof (zrun_ladderq (N.to_nat take)
             (lsCur fr - (lsCur fr - 2))%nat sg
             (skipn (lsCur fr - 2)%nat w) f
             (lsGap fr) (lsSlot fr) lw2 f2 dz HWf
             ltac:(rewrite N2Nat.id;
                   eapply lin_bottom_take_lt20; exact HBottom) EZ) as HLocal0.
           assert (HLocal : chi dz <= carm
             (FlightDomC_cmeas sg' w' f' +
                8 * cascticks (fr :: rest))
             (cascticks (fr :: rest))).
           { eapply N.le_trans; [exact HLocal0|]. apply ladderq_carm.
             change (gmeas (lin_flat sg
                       (setsfx (lsCur fr - 2)%nat w lw2)) f2
                       <= gmeas (lin_flat sg' w') f' +
                          8 * cascticks
                            (lin_sched_advance fr take :: rest))
               in HRecDom.
             unfold FlightDomC_cmeas. lia. }
           assert (HRec' : chi d2 <= N.of_nat fu * carm
             (FlightDomC_cmeas sg' w' f' +
                8 * cascticks (fr :: rest))
             (cascticks (fr :: rest))).
           { eapply N.le_trans; [exact HRec|]. apply fuel_carm_mono; lia. }
           rewrite (chi_caddx_exact dz d2 HLocalCE HRecCE).
           exact (fuel_step_arith fu _ _ _ HLocal HRec').
        -- destruct (if Nat.ltb (lsCur fr + 2)
                          (lsCur fr + length cols)%nat
                     then match detect_phase (g :: t) O with
                          | Some pk =>
                              let take := lin_bulk_take sg w (lsCur fr)
                                 (lsCur fr + length cols)%nat pk
                                 (lsTicks fr) in
                              if (THRESH <=? take)%N
                              then match lin_bulk sg w
                                       (lsCur fr + length cols)%nat pk take with
                                   | Some (w2, sg2, t2, p2k, ek) =>
                                       Some (w2, sg2, t2, p2k, ek, take, pk)
                                   | None => None
                                   end
                              else None
                          | None => None
                          end
                     else None)
             as [[[[[[[wB sgB] tB] pB] eB] tkB] pkB]|] eqn:EBulk.
           ++ destruct (negb (lin_sched_bulk_safe fr
                                (lin_flen sg cols) pkB tkB))
                eqn:ESafe; [discriminate HRun|].
              apply negb_false_iff in ESafe.
              destruct (lin_at_safe sgB wB tB) as [wC|] eqn:EAt;
                [|discriminate HRun].
              pose proof (lin_at_safe_some sgB wB tB wC EAt) as ->.
              destruct (locate_all sgB wB) as [psB|] eqn:ELoc;
                [|discriminate HRun].
              destruct (lin_guard_at sgB psB wB) eqn:EGB;
                [|discriminate HRun].
              destruct (Nat.ltb (lsCur fr + 2)
                          (lsCur fr + length cols)%nat) eqn:ELt;
                [|discriminate EBulk].
              destruct (detect_phase (g :: t) O)
                as [pk|] eqn:EPh; [|discriminate EBulk].
              cbv beta zeta in EBulk.
              destruct ((THRESH <=?
                         lin_bulk_take sg w (lsCur fr)
                           (lsCur fr + length cols)%nat pk
                           (lsTicks fr))%N) eqn:ETh;
                [|discriminate EBulk].
              destruct (lin_bulk sg w (lsCur fr + length cols)%nat pk
                          (lin_bulk_take sg w (lsCur fr)
                             (lsCur fr + length cols)%nat pk
                             (lsTicks fr)))
                as [[[[[w2' sg2'] t2'] p2k'] ek']|] eqn:EBk;
                [|discriminate EBulk].
              inversion EBulk; subst wB sgB tB pB eB tkB pkB.
              set (take := lin_bulk_take sg w (lsCur fr)
                             (lsCur fr + length cols)%nat pk
                             (lsTicks fr)) in *.
              destruct (ccasc fu sg2' psB w2' f
                          (lin_sched_child t2' p2k' ek' pk take
                           :: lin_sched_advance fr take :: rest))
                as [o d2] eqn:ERec.
              cbn [fst snd] in HRun. injection HRun as Ho Hd. subst o d.
              assert (HD : detect_phase w
                             (lsCur fr + length cols)%nat = Some pk).
              { rewrite detect_phase_skipn.
                rewrite (skipn_seek_at w (lsCur fr)
                           cols (g :: t) HSeek). exact EPh. }
              assert (HTgPos : (1 <= lsCur fr + length cols)%nat).
              { apply PeanoNat.Nat.ltb_lt in ELt. lia. }
              pose proof (lin_bulk_front_repr sg w
                (lsCur fr + length cols)%nat pk take
                w2' sg2' t2' p2k' ek' (conj HOk HPT) HHead HD EBk) as HFront2.
              assert (HGuard2 : lin_guard sg2' w2' = true).
              { eapply lin_guard_at_sound;
                  [exact (proj1 HFront2)|exact EGB]. }
              assert (HG2 : stable_guard sg2' w2').
              { eapply lin_bulk_stable_guarded; eauto. }
              destruct (lin_bulk_head_pos sg w
                (lsCur fr + length cols)%nat pk take
                w2' sg2' t2' p2k' ek' HTgPos HHead HD EBk)
                as (HNhPos & HHead2).
              assert (HTake : take <= lsTicks fr)
                by (unfold take; apply lin_bulk_take_le).
              assert (HThreshLe : THRESH <= take)
                by (apply N.leb_le; exact ETh).
              assert (HFrames2 : Forall frame_pos
                (lin_sched_child t2' p2k' ek' pk take
                 :: lin_sched_advance fr take :: rest)).
              { constructor.
                + unfold frame_pos, lin_sched_child. cbn [lsCur].
                  destruct (Nat.eqb (N.to_nat ((pk + take) / 28)) O)
                    eqn:HFull.
                  * destruct (lin_bulk_checks sg w
                      (lsCur fr + length cols)%nat pk take _ EBk)
                      as (gb & HWat & _ & _ & _ & _).
                    destruct (lin_bulk_partial_out sg w
                      (lsCur fr + length cols)%nat pk take
                      w2' sg2' t2' p2k' ek' gb HFull EBk HWat)
                      as (_ & Hnh & _ & _ & _). lia.
                  * assert (HCross : (lsCur fr <= t2')%nat).
                    { eapply lin_bulk_take_lands_after_cursor.
                      - exact HWf.
                      - exact HOk.
                      - exact (stable_altb sg w HG0).
                      - exact HHead.
                      - exact HSeek.
                      - reflexivity.
                      - exact HD.
                      - reflexivity.
                      - exact HThreshLe.
                      - exact HFull.
                      - exact EBk.
                      - exact (proj1 (proj2 (proj2 HG2))). }
                    lia.
                + constructor.
                  * apply frame_pos_advance.
                    unfold frame_pos. exact HFr.
                  * exact HRest. }
              pose proof (IH sg2' psB w2' f
                (lin_sched_child t2' p2k' ek' pk take
                 :: lin_sched_advance fr take :: rest)
                w' sg' ps' f' d2 HG2 HGuard2 HHead2 HFrames2 ERec) as HRec.
              assert (HRecCE : CE d2)
                by (eapply ccasc_success_CE; eassumption).
              assert (HFlatCols :
                delivery_cols
                  (lin_flat sg cols) = true).
              { apply lin_flat_delivery_cols.
                - exact HCols.
                - exact (stable_altb sg w HG0). }
              pose proof (dbulkc_carm sg w cols (g :: t) f
                (lsCur fr) (lsGap fr) (lsSlot fr) pk take
                w2' sg2' t2' p2k' ek' HG0 HHead HSeek HD EBk
                (proj1 (proj2 (proj2 HG2))) HFlatCols) as HLocal0.
              assert (HEmit : ek' <= take).
              { apply (bulk_emit_le pk take ek').
                exact (lin_bulk_emit_eq sg w w2'
                  (lsCur fr + length cols)%nat t2' pk take p2k' ek' sg2'
                  EBk). }
              assert (HQ : cascticks
                (lin_sched_child t2' p2k' ek' pk take
                 :: lin_sched_advance fr take :: rest)
                <= cascticks (fr :: rest)).
              { apply cascticks_bulk_le; assumption. }
              assert (HLocal : chi
                (dbulkc sg w cols (g :: t) (lsCur fr)
                  (lsGap fr) (lsSlot fr) pk take)
                <= carm (FlightDomC_cmeas sg' w' f' +
                           8 * cascticks (fr :: rest))
                         (cascticks (fr :: rest))).
              { eapply N.le_trans; [exact HLocal0|]. apply carm_mono.
                - exact HWholeDom.
                -
                assert (HTakeQ : take <=
                  cascticks (fr :: rest)).
                { rewrite cascticks_cons. lia. }
                exact HTakeQ. }
              assert (HRec' : chi d2 <= N.of_nat fu * carm
                (FlightDomC_cmeas sg' w' f' +
                   8 * cascticks (fr :: rest))
                (cascticks (fr :: rest))).
              { eapply N.le_trans; [exact HRec|].
                apply fuel_carm_mono; lia. }
              assert (HLocalCE : CE
                (dbulkc sg w cols (g :: t) (lsCur fr)
                   (lsGap fr) (lsSlot fr) pk take)).
              { unfold dbulkc.
                destruct (Nat.eqb (N.to_nat ((pk+take)/28)) O);
                  [unfold dbulkp|unfold dbulkn];
                  unfold CE, cx, clo, chi;
                  reflexivity. }
              rewrite (chi_caddx_exact _ _ HLocalCE HRecCE).
              exact (fuel_step_arith fu _ _ _ HLocal HRec').
           ++ destruct (lin_dtick_after_seek cols (g :: t) f)
                as [[[renewed sfx] f2]|] eqn:EDt; [|discriminate HRun].
              assert (HM : ph_margins sg w)
                by (exact (lguard_margins sg w HGuard)).
              assert (HN : ph_nbrs sg w)
                by (exact (margins_edges_nbrs
                            sg w HM HEdges)).
              assert (HN1 : nbrs1z sg w)
                by (exact (nbrs_nbrs1z sg w HN)).
              assert (HNCur : nbrs1z sg (skipn (lsCur fr) w)).
              { apply (nbrs1z_app_r sg (firstn (lsCur fr) w)
                         (skipn (lsCur fr) w)).
                rewrite firstn_skipn. exact HN1. }
              assert (HNS : nbrs1z sg (g :: t)).
              { apply (nbrs1z_app_r sg cols (g :: t)).
                rewrite <- HSplit. exact HNCur. }
              assert (HNotLast : forall t',
                g :: t = (4%N,3%N,1%N) :: t' -> ph_notlast sg cols).
              { intros t' E. injection E as Eg Et. subst g t.
                pose proof (nbrs1z_seek_notlast sg
                  (skipn (lsCur fr) w) (4%N,3%N,1%N) t'
                  HNCur ltac:(rewrite HSeek; reflexivity)
                  ltac:(unfold is_spc; reflexivity)
                  ltac:(cbn [gZ]; lia)) as H.
                rewrite HSeek in H. cbn [fst] in H. exact H. }
              assert (HNonPh : forall gh u,
                g :: t = gh :: u -> ph sg gh = false).
              { intros gh u E. injection E as <- <-.
                exact (nbrs1z_seek_snd_head sg
                  (skipn (lsCur fr) w) g t HNCur
                  ltac:(rewrite HSeek; reflexivity)). }
              destruct renewed eqn:ERenew;
                [ destruct (negb (Nat.leb (lsGap fr + 2)
                      (lin_flen sg cols))) eqn:HGap;
                    [discriminate HRun|];
                  apply negb_false_iff in HGap;
                  assert (HRenew : true = true ->
                    (lsGap fr + 2 <= lin_flen sg cols)%nat)
                    by (intros _; apply PeanoNat.Nat.leb_le; exact HGap)
                | assert (HRenew : false = true ->
                    (lsGap fr + 2 <= lin_flen sg cols)%nat)
                    by discriminate ].
              all: destruct (if Nat.eqb (lsCur fr) O then Some sfx
                             else lin_join_safe sg
                                    (firstn (lsCur fr) w) sfx)
                     as [w2|] eqn:HJoin; [|discriminate HRun].
              all: destruct (if lin_same_length w w2
                             then Some ps else relocate_all sg ps w2)
                     as [ps2|] eqn:HRel; [|discriminate HRun].
              all: destruct (lin_guard_at sg ps2 w2) eqn:HAt;
                   [|discriminate HRun].
              all: destruct (ccasc fu sg ps2 w2 f2
                     (lin_sched_advance_one fr :: rest))
                     as [o d2] eqn:ERec.
              all: cbn [fst snd] in HRun.
              all: injection HRun as Ho Hd; subst o d.
              all: rewrite lin_sched_advance_one_eq in ERec.
              all: assert (HG2 : stable_guard sg w2)
                by (eapply lin_direct_stable; eauto).
              all: assert (HGuard2 : lin_guard sg w2 = true)
                by (eapply lin_guard_at_sound;
                    [exact (proj1 (proj1 HG2))|exact HAt]).
              all: assert (EW2 : w2 = firstn (lsCur fr) w ++ sfx)
                by (destruct (Nat.eqb (lsCur fr) O) eqn:HCur0;
                    [apply PeanoNat.Nat.eqb_eq in HCur0; lia
                    | exact (lin_join_safe_some
                        sg (firstn (lsCur fr) w) sfx w2 HJoin)]).
              all: assert (HHead2 : is_spc (nth O w2 d0) = false)
                by (exact (prefix_replace_head_nonspc
                    w w2 (lsCur fr) sfx ltac:(lia) HCurLen EW2 HHead)).
              all: assert (HFrames2 : Forall frame_pos
                (lin_sched_advance fr 1 :: rest))
                by (constructor;
                    [apply frame_pos_advance;
                     unfold frame_pos; exact HFr|exact HRest]).
              all: pose proof (IH sg ps2 w2 f2
                (lin_sched_advance fr 1 :: rest)
                w' sg' ps' f' d2 HG2 HGuard2 HHead2 HFrames2 ERec) as HRec.
              all: assert (HRecCE : CE d2)
                by (eapply ccasc_success_CE; eassumption).
              all: pose proof (@ddirect_exact sg cols (g :: t) f
                (lsGap fr) _ sfx f2 HWf HKeys
                (stable_guard_live sg w HG0)
                (stable_altb sg w HG0) HCols HNotLast HNS HNonPh
                EDt HRenew) as HLocalCE.
              all: assert (HQ : cascticks
                (lin_sched_advance fr 1 :: rest)
                <= cascticks (fr :: rest)) by
                (rewrite !cascticks_cons, ticks_advance;
                 apply N.eqb_neq in ETicks; lia).
              all: pose proof (ddirect_armq sg w cols (g :: t) f
                (lsCur fr) (lsGap fr) HSeek) as HLocal0.
              all: assert (HLocal : chi
                (ddirect sg cols (g :: t) f (lsGap fr))
                <= carm (FlightDomC_cmeas sg' w' f' +
                           8 * cascticks (fr :: rest))
                         (cascticks (fr :: rest))) by
                (eapply N.le_trans; [exact HLocal0|]; apply armq_carm;
                 change (FlightDomC_cmeas sg w f <=
                   FlightDomC_cmeas sg' w' f' +
                     8 * cascticks (fr :: rest)); lia).
              all: assert (HRec' : chi d2 <= N.of_nat fu * carm
                (FlightDomC_cmeas sg' w' f' +
                   8 * cascticks (fr :: rest))
                (cascticks (fr :: rest))) by
                (eapply N.le_trans; [exact HRec|];
                 apply fuel_carm_mono; lia).
              all: rewrite (chi_caddx_exact _ _ HLocalCE HRecCE).
              all: exact (fuel_step_arith fu _ _ _ HLocal HRec').
Qed.
Corollary lin_casc_safe_at_workc_bound_exists :
  forall (fu : nat) (sg : list seg) (ps : atab) (w : word)
         (f : N) (st : list lsc_frame) (w' : word)
         (sg' : list seg) (ps' : atab) (f' : N),
  stable_guard sg w ->
  lin_guard sg w = true ->
  is_spc (nth O w d0) = false ->
  Forall frame_pos st ->
  lin_casc_safe_at fu sg ps w f st = Some (w', sg', ps', f') ->
  exists T,
    scheduled_workc T st sg w f sg' w' f'
    /\ stable_guard sg' w'
    /\ lin_guard sg' w' = true
    /\ is_spc (nth O w' d0) = false
    /\ T <= N.of_nat fu * carm
              (FlightDomC_cmeas sg' w' f' +
                 8 * cascticks st)
              (cascticks st).
Proof.
  intros fu sg ps w f st w' sg' ps' f' HG HGuard HHead HFrames HRun.
  destruct (ccasc fu sg ps w f st) as [o d] eqn:EC.
  assert (Ho : o = Some (w', sg', ps', f')).
  { pose proof (ccasc_proj fu sg ps w f st) as HP.
    rewrite EC in HP. cbn [fst] in HP. rewrite HRun in HP. exact HP. }
  subst o.
  destruct (ccasc_exact fu sg ps w f st w' sg' ps' f' d
              HG HGuard HHead HFrames EC) as (T & Hd).
  subst d.
  destruct (ccasc_work fu sg ps w f st w' sg' ps' f' T
              HG HGuard HHead HFrames EC)
    as (HWork & HG' & HGuard' & HHead').
  pose proof (ccasc_fuel_bound fu sg ps w f st w' sg' ps' f'
                (cx T) HG HGuard HHead HFrames EC) as HB.
  exists T. split; [exact HWork|].
  split; [exact HG'|]. split; [exact HGuard'|].
  split; [exact HHead'|].
  cbn [cx chi snd] in HB. exact HB.
Qed.
Theorem flight_core_reachable0
    (sg : list seg) (J : N) (tail : word) (f : N) (j : nat)
    (p tk : N) (w1 : word) (sg1 : list seg) (nh : nat)
    (rem emit : N) (ps1 : atab) (sg2 : list seg) (w2 : word)
    (ps2 : atab) (f2 : N) :
  stable_guard sg ((2,2,J)%N :: tail) ->
  (1 <= J)%N -> (1 <= j)%nat ->
  forallb is_col (firstn j ((2,2,J)%N :: tail)) = true ->
  detect_phase ((2,2,J)%N :: tail) j = Some p ->
  Nat.eqb (N.to_nat ((p+tk)/28)) O = false ->
  lin_bulk sg ((2,2,J)%N :: tail) j p tk
    = Some (w1,sg1,nh,rem,emit) ->
  stable_guard sg1 (subst_at O 1 [(2,2,J+tk)%N] w1) ->
  lin_guard sg1 (subst_at O 1 [(2,2,J+tk)%N] w1) = true ->
  is_spc (nth O (subst_at O 1 [(2,2,J+tk)%N] w1) d0) = false ->
  frame_pos (lin_sched_child nh rem emit p tk) ->
  lin_casc_safe_at CFUEL sg1 ps1
      (subst_at O 1 [(2,2,J+tk)%N] w1) f
      [lin_sched_child nh rem emit p tk]
    = Some (w2,sg2,ps2,f2) ->
  gmeas (lin_flat sg ((2,2,J)%N :: tail)) f <= BMAX ->
  gmeas (lin_flat sg2 w2) f2 <= BMAX ->
  creach (0%N, CoarseC_flight_ub tk)
    (wconf [] 0 (sdecode
      (lin_flat sg ((2,2,J)%N :: tail)) f))
    (wconf [] 0 (sdecode (lin_flat sg2 w2) f2)).
Proof.
  intros HG HJ Hj HCols HD HFull HB HG1 HGuard1 HHead1 HFrame HCasc
         HM0B HM1B.
  destruct (lin_casc_safe_at_workc_bound_exists CFUEL sg1 ps1
    (subst_at O 1 [(2,2,J+tk)%N] w1) f
    [lin_sched_child nh rem emit p tk] w2 sg2 ps2 f2
    HG1 HGuard1 HHead1 (Forall_cons _ HFrame (Forall_nil _)) HCasc)
    as (T & HWork & _ & _ & _ & HT).
  rewrite cascticks_one in HT.
  cbn [lin_sched_child lsTicks] in HT.
  destruct (lin_bulk_master_flight_at sg J tail f j p tk
    w1 sg1 nh rem emit sg2 w2 f2 T HG HJ Hj HCols HD HFull HB
    (scheduled_workc_one_inv _ _ _ _ _ _ _ _ HWork))
    as (pr & c & b & cs & Hpr & EPrefix & HLen & HSafe & EWat & ERem
        & HReach).
  set (M0 := gmeas (lin_flat sg ((2,2,J)%N :: tail)) f).
  set (M1 := gmeas (lin_flat sg2 w2) f2).
  pose proof (flat_firstn_cost_le sg ((2,2,J)%N :: tail) j) as HPref.
  change (ccolcost
            (lin_flat sg (firstn j ((2,2,J)%N :: tail)))
          <= ccolcost (lin_flat sg ((2,2,J)%N :: tail))) in HPref.
  assert (HParts :
    ccolcost ((2,2,J)%N :: pr) + wcolsum (c :: cs)
      <= M0).
  { unfold M0, gmeas.
    rewrite EPrefix in HPref.
    change (ccolcost
              (((2,2,J)%N :: pr) ++ runway (c :: cs))
            <= ccolcost (lin_flat sg ((2,2,J)%N :: tail)))
      in HPref.
    rewrite ccolcost_app, ccolcost_runway in HPref.
    lia. }
  assert (HprAll : forallb is_col ((2,2,J)%N :: pr) = true).
  { cbn [forallb is_col gO gZ]. exact Hpr. }
  pose proof (ccolcost_col_bsum _ HprAll) as EBase.
  assert (HBase : bsum ((2,2,J)%N :: pr) <= M0)
    by (rewrite <- EBase; lia).
  assert (HMass : wcolsum (c :: cs) <= M0) by lia.
  assert (HLevels : Forall (fun x => x <= M0) (rev (c :: cs))).
  { apply Forall_rev, wcolsum_levels_le. exact HMass. }
  assert (Hb : b <= M0).
  { eapply literal_site_base_le; exact EWat. }
  destruct (detect_phase_form ((2,2,J)%N :: tail) j p HD)
    as (Hp & _).
  assert (Hr : rem < 28).
  { rewrite ERem. apply N.mod_lt. discriminate. }
  assert (Hemit : emit <= tk).
  { apply (bulk_emit_le p tk emit).
    exact (lin_bulk_emit_eq sg ((2,2,J)%N :: tail) w1 j nh p tk
             rem emit sg1 HB). }
  assert (Htk : tk <= 3*M0).
  { exact (flight_ticks_le p tk rem c cs M0 Hp ERem HLen HSafe HMass). }
  pose proof (flight_slot_ticks_ub (bsum ((2,2,J)%N :: pr)) tk
    (rev (c :: cs)) p rem b T M0 Hp Hr HBase Hb HLevels
    ltac:(rewrite wcolsum_rev; exact HMass)
    ltac:(rewrite length_rev; exact HLen)) as HSlot.
  assert (HFlightQ : chi
      (d_flight_slot (bsum ((2,2,J)%N :: pr)) tk
        (drunway 0%N (rev (c :: cs)) p rem b) T)
      <= flightq M0 M1 tk).
  { eapply N.le_trans; [exact HSlot|]. apply flightq_from.
    eapply N.le_trans; [exact HT|]. apply N.mul_le_mono_l, carm_mono.
    - unfold M1, FlightDomC_cmeas. apply N.add_le_mono_l.
      apply N.mul_le_mono_l. exact Hemit.
    - exact Hemit. }
  assert (HClose : flightq M0 M1 tk <= CoarseC_flight_ub tk).
  { apply flightq_close; [exact HM0B|exact HM1B|].
    unfold M0 in Htk. eapply N.le_trans; [exact Htk|]. nia. }
  change (creach
    (d_flight_slot (bsum ((2,2,J)%N :: pr)) tk
      (drunway 0%N (rev (c :: cs)) p rem b) T)
    (wconf [] 0 (sdecode
      (lin_flat sg ((2,2,J)%N :: tail)) f))
    (wconf [] 0 (sdecode (lin_flat sg2 w2) f2))) in HReach.
  refine (creach_widen' _ (0%N, CoarseC_flight_ub tk) _ _ _ _ HReach).
  - cbn [clo fst]. lia.
  - cbn [chi snd]. eapply N.le_trans; eassumption.
Qed.
Lemma tick_full_slot_quad_ub (base b W T M : N) :
  base <= M -> b <= M -> W <= M ->
  chi (d_flight base 28
    (dtransit1 0 b W + T))
  <= slotq M 28 + T.
Proof.
  intros Hbase Hb HW.
  pose proof (dtransit1_quad_ub 0 b W M ltac:(lia) Hb HW) as HD.
  pose proof (N.mul_div_le (28 * (28-1)) 2 ltac:(lia)) as HH.
  unfold d_flight, cx, chi, slotq. cbn [snd]. nia.
Qed.
Lemma tick_partial_slot_quad_ub (base b W T M : N) :
  base <= M -> b <= M -> W <= M ->
  chi (d_flight base 27
    (dpartial1 b W + T))
  <= slotq M 27 + T.
Proof.
  intros Hbase Hb HW.
  pose proof (dladder_block_ub 27 0 b M ltac:(lia) Hb) as HD.
  pose proof (N.mul_div_le (27 * (27-1)) 2 ltac:(lia)) as HH.
  unfold dpartial1, d_flight, cx, chi, slotq.
  cbn [snd]. nia.
Qed.
Lemma literal_group_cost_le (sg : list seg) (w : word) (f : N)
      (g : bg) :
  In g w -> keyb sg g = None ->
  ccg g <= gmeas (lin_flat sg w) f.
Proof.
  intros Hin HK. destruct (in_split g w Hin) as (pre & post & ->).
  unfold gmeas. rewrite !lin_flat_app_c.
  cbn [lin_flat]. rewrite HK.
  rewrite !ccolcost_app, ccolcost_cons. lia.
Qed.
Lemma literal_count_le (sg : list seg) (w : word) (f : N)
      (o z c : N) :
  In (o,z,c)%N w -> (o =? 9)%N = false ->
  c <= gmeas (lin_flat sg w) f.
Proof.
  intros Hin Ho.
  pose proof (literal_group_cost_le sg w f (o,z,c)%N Hin
    (keyb_nine sg (o,z,c)%N Ho)) as H.
  unfold ccg in H. cbn [gC gO] in H. nia.
Qed.
Lemma flat_middle_cost_le (sg : list seg) (a b c : word) (f : N) :
  ccolcost (lin_flat sg b)
  <= gmeas (lin_flat sg (a ++ b ++ c)) f.
Proof.
  unfold gmeas. rewrite !lin_flat_app_c, !ccolcost_app.
  lia.
Qed.
Lemma lin_flat_rung1 (sg : list seg) (c : N) :
  lin_flat sg (rung1 c) = rung1 c.
Proof.
  apply lin_flat_lit. cbn [rung1 forallb gO].
  reflexivity.
Qed.
Theorem tick_full_core_reachable0
    (sg : list seg) (J : N) (pre : word) (c cg : N)
    (rest : word) (f : N) (ps1 : atab)
    (w2 : word) (sg2 : list seg) (ps2 : atab) (f2 : N) :
  stable_guard sg
    (((2,2,J)%N::pre) ++ rung1 c ++ phase_form 0 ++
      (4,2,cg)%N::rest) ->
  (1 <= J)%N -> (FLOOR <= c)%N ->
  (FLOOR + 3 <= cg)%N ->
  delivery_cols (lin_flat sg pre) = true ->
  lin_guard_at sg ps1
    (((2,2,J+28)%N::pre) ++ phase_form 0 ++ (4,2,c)%N::
      rung1 (cg-4)%N ++ rest) = true ->
  lin_casc_safe_at CFUEL sg ps1
    (((2,2,J+28)%N::pre) ++ phase_form 0 ++ (4,2,c)%N::
      rung1 (cg-4)%N ++ rest) f
    [lin_sched_child (S (length pre)) 0 4 0 28] =
      Some (w2,sg2,ps2,f2) ->
  gmeas (lin_flat sg
    (((2,2,J)%N::pre) ++ rung1 c ++ phase_form 0 ++
      (4,2,cg)%N::rest)) f <= BMAX ->
  gmeas (lin_flat sg2 w2) f2 <= BMAX ->
  creach (0%N, CoarseC_flight_ub 28)
    (wconf [] 0 (sdecode (lin_flat sg
      (((2,2,J)%N::pre) ++ rung1 c ++ phase_form 0 ++
        (4,2,cg)%N::rest)) f))
    (wconf [] 0 (sdecode (lin_flat sg2 w2) f2)).
Proof.
  intros HG HJ Hc Hcg HCols HAt HCasc HM0B HM1B.
  set (win := (((2,2,J)%N::pre) ++ rung1 c ++
    phase_form 0 ++ (4,2,cg)%N::rest)).
  set (wout := (((2,2,J+28)%N::pre) ++ phase_form 0 ++
    (4,2,c)%N :: rung1 (cg-4)%N ++ rest)).
  assert (HGm : stable_guard sg
      (((2,2,J+28)%N::pre) ++ rung1 c ++
        phase_form 0 ++ (4,2,cg)%N::rest)).
  { change (stable_guard sg
      ((2,2,J+28)%N::(pre ++ rung1 c ++
        phase_form 0 ++ (4,2,cg)%N::rest))).
    change (stable_guard sg
      ((2,2,J)%N::(pre ++ rung1 c ++
        phase_form 0 ++ (4,2,cg)%N::rest))) in HG.
    exact (stable_guard_master_change_probe
      sg J (J+28) _ HG). }
  assert (HFront : front_repr sg wout).
  { apply (front_repr_phseq sg
      (((2,2,J+28)%N::pre) ++ rung1 c ++
        phase_form 0 ++ (4,2,cg)%N::rest) wout HGm).
    unfold wout. exact (phseq_full_cross
      (J+28) (J+28) pre c cg rest). }
  assert (HGuard : lin_guard sg wout = true).
  { eapply lin_guard_at_sound; [exact (proj1 HFront)|exact HAt]. }
  assert (HStable : stable_guard sg wout).
  { unfold wout. exact (tick_full_master_stable
      sg J pre c cg rest HG HGuard). }
  assert (HHead : is_spc (nth O wout d0) = false).
  { unfold wout. reflexivity. }
  assert (HPos : frame_pos
      (lin_sched_child (S (length pre)) 0 4 0 28)).
  { unfold frame_pos, lin_sched_child.
    change (3 <= S (length pre) + 2)%nat. lia. }
  change (lin_casc_safe_at CFUEL sg ps1 wout f
    [lin_sched_child (S (length pre)) 0 4 0 28] =
      Some (w2,sg2,ps2,f2)) in HCasc.
  destruct (lin_casc_safe_at_workc_bound_exists CFUEL sg ps1
    wout f [lin_sched_child (S (length pre)) 0 4 0 28]
    w2 sg2 ps2 f2 HStable HGuard HHead
    (Forall_cons _ HPos (Forall_nil _)) HCasc)
    as (T & HWork & _ & _ & _ & HT).
  rewrite cascticks_one in HT.
  cbn [lin_sched_child lsTicks] in HT.
  pose proof (scheduled_workc_one_inv
    _ _ _ _ _ _ _ _ HWork) as HFrame.
  assert (EOut : wout =
      ((((2,2,J+28)%N::pre) ++ phase_form 0 ++
        (4,2,c)%N::rung1 (cg-4)%N) ++ rest)).
  { unfold wout. exact (app3_tail _
      ((2,2,J+28)%N::pre) (phase_form 0)
      ((4,2,c)%N::rung1 (cg-4)%N) rest). }
  rewrite EOut in HFrame.
  pose proof (tick_full_master_scheduled_soundc
    sg J pre c cg rest f sg2 w2 f2 T HJ Hc Hcg HCols HFrame) as HR.
  set (M0 := gmeas (lin_flat sg win) f).
  set (M1 := gmeas (lin_flat sg2 w2) f2).
  assert (HBase : bsum [(2,2,J)%N] <= M0).
  { rewrite <- (ccolcost_col_bsum [(2,2,J)%N]
      ltac:(reflexivity)).
    pose proof (literal_group_cost_le sg win f (2,2,J)%N
      ltac:(unfold win; repeat rewrite in_app_iff; cbn; tauto)
      ltac:(apply keyb_nine; reflexivity)) as H.
    unfold ccg in H. cbn [gC gO] in H.
    cbn [ccolcost gC gO]. unfold M0. lia. }
  assert (Hb : cg-3 <= M0).
  { assert (HcgM : cg <= M0).
    { eapply literal_count_le with (o:=4) (z:=2).
      - unfold win. repeat rewrite in_app_iff. cbn. tauto.
      - reflexivity. }
    lia. }
  assert (HW : wcolcost
      (lin_flat sg pre ++ rung1 c) <= M0).
  { rewrite wcolcost_ccolcost.
    rewrite <- (lin_flat_rung1 sg c),
      <- (lin_flat_app_c sg pre (rung1 c)).
    unfold M0, win.
    replace
      (((2,2,J)%N::pre) ++ rung1 c ++ phase_form 0 ++
        (4,2,cg)%N::rest)
      with ([(2,2,J)%N] ++ (pre ++ rung1 c) ++
        (phase_form 0 ++ (4,2,cg)%N::rest)).
    2: { cbn [app]. rewrite !app_assoc. reflexivity. }
    apply flat_middle_cost_le. }
  pose proof (tick_full_slot_quad_ub
    (bsum [(2,2,J)%N]) (cg-3)
    (wcolcost (lin_flat sg pre ++ rung1 c)) T M0
    HBase Hb HW) as HSlot.
  assert (HT28 :
    T <= N.of_nat CFUEL * carm (M1 + 8*28) 28).
  { eapply N.le_trans; [exact HT|]. apply N.mul_le_mono_l, carm_mono;
      unfold M1, FlightDomC_cmeas; nia. }
  assert (HQ : chi (d_flight
      (bsum [(2,2,J)%N]) 28
      (dtransit1 0 (cg-3)
        (wcolcost (lin_flat sg pre ++ rung1 c)) + T))
      <= flightq M0 M1 28).
  { eapply N.le_trans; [exact HSlot|]. exact (flightq_from _ _ _ _ HT28). }
  assert (HClose : flightq M0 M1 28 <= CoarseC_flight_ub 28).
  { apply flightq_close; [unfold M0, win; exact HM0B|exact HM1B|].
    vm_compute. discriminate. }
  assert (EIn : win =
      ((((2,2,J)%N::pre) ++ rung1 c ++ phase_form 0 ++
        [(4,2,cg)%N]) ++ rest)).
  { unfold win. exact (app4_tail _
      ((2,2,J)%N::pre) (rung1 c) (phase_form 0)
      [(4,2,cg)%N] rest). }
  rewrite EIn.
  refine (creach_widen' _ (0%N,CoarseC_flight_ub 28) _ _ _ _ HR).
  - cbn [clo fst]. lia.
  - cbn [chi snd]. eapply N.le_trans; eassumption.
Qed.
Theorem tick_partial_core_reachable0
    (sg : list seg) (J : N) (pre : word) (cg : N)
    (rest : word) (f : N) (ps1 : atab)
    (w2 : word) (sg2 : list seg) (ps2 : atab) (f2 : N) :
  stable_guard sg
    (((2,2,J)%N::pre) ++ phase_form 0 ++ (4,2,cg)%N::rest) ->
  (1 <= J)%N -> (1 <= length pre)%nat ->
  (FLOOR + 3 <= cg)%N ->
  delivery_cols (lin_flat sg pre) = true ->
  lin_guard_at sg ps1
    (((2,2,J+27)%N::pre) ++ phase_form 27 ++
      (4,2,cg-3)%N::rest) = true ->
  lin_casc_safe_at CFUEL sg ps1
    (((2,2,J+27)%N::pre) ++ phase_form 27 ++
      (4,2,cg-3)%N::rest) f
    [lin_sched_child (S (length pre)) 27 3 0 27] =
      Some (w2,sg2,ps2,f2) ->
  gmeas (lin_flat sg
    (((2,2,J)%N::pre) ++ phase_form 0 ++
      (4,2,cg)%N::rest)) f <= BMAX ->
  gmeas (lin_flat sg2 w2) f2 <= BMAX ->
  creach (0%N, CoarseC_flight_ub 27)
    (wconf [] 0 (sdecode (lin_flat sg
      (((2,2,J)%N::pre) ++ phase_form 0 ++
        (4,2,cg)%N::rest)) f))
    (wconf [] 0 (sdecode (lin_flat sg2 w2) f2)).
Proof.
  intros HG HJ HPre Hcg HCols HAt HCasc HM0B HM1B.
  set (win := (((2,2,J)%N::pre) ++ phase_form 0 ++
    (4,2,cg)%N::rest)).
  set (wout := (((2,2,J+27)%N::pre) ++ phase_form 27 ++
    (4,2,cg-3)%N::rest)).
  assert (HGm : stable_guard sg
      (((2,2,J+27)%N::pre) ++ phase_form 0 ++
        (4,2,cg)%N::rest)).
  { change (stable_guard sg
      ((2,2,J+27)%N::(pre ++ phase_form 0 ++
        (4,2,cg)%N::rest))).
    change (stable_guard sg
      ((2,2,J)%N::(pre ++ phase_form 0 ++
        (4,2,cg)%N::rest))) in HG.
    exact (stable_guard_master_change_probe
      sg J (J+27) _ HG). }
  assert (HFront : front_repr sg wout).
  { apply (front_repr_phseq sg
      (((2,2,J+27)%N::pre) ++ phase_form 0 ++
        (4,2,cg)%N::rest) wout HGm).
    unfold wout. exact (phseq_partial_tick
      (J+27) (J+27) pre cg rest). }
  assert (HGuard : lin_guard sg wout = true).
  { eapply lin_guard_at_sound; [exact (proj1 HFront)|exact HAt]. }
  assert (HStable : stable_guard sg wout).
  { unfold wout. exact (tick_partial_master_stable
      sg J pre cg rest HG HGuard). }
  assert (HHead : is_spc (nth O wout d0) = false).
  { unfold wout. reflexivity. }
  assert (HPos : frame_pos
      (lin_sched_child (S (length pre)) 27 3 0 27)).
  { unfold frame_pos, lin_sched_child.
    change (3 <= S (length pre) + 1)%nat. lia. }
  change (lin_casc_safe_at CFUEL sg ps1 wout f
    [lin_sched_child (S (length pre)) 27 3 0 27] =
      Some (w2,sg2,ps2,f2)) in HCasc.
  destruct (lin_casc_safe_at_workc_bound_exists CFUEL sg ps1
    wout f [lin_sched_child (S (length pre)) 27 3 0 27]
    w2 sg2 ps2 f2 HStable HGuard HHead
    (Forall_cons _ HPos (Forall_nil _)) HCasc)
    as (T & HWork & _ & _ & _ & HT).
  rewrite cascticks_one in HT.
  cbn [lin_sched_child lsTicks] in HT.
  pose proof (tick_partial_master_scheduled_soundc
    sg J pre cg rest f sg2 w2 f2 T HJ Hcg HCols
    (scheduled_workc_one_inv _ _ _ _ _ _ _ _ HWork)) as HR.
  set (M0 := gmeas (lin_flat sg win) f).
  set (M1 := gmeas (lin_flat sg2 w2) f2).
  assert (HBase : bsum [(2,2,J)%N] <= M0).
  { rewrite <- (ccolcost_col_bsum [(2,2,J)%N]
      ltac:(reflexivity)).
    pose proof (literal_group_cost_le sg win f (2,2,J)%N
      ltac:(unfold win; repeat rewrite in_app_iff; cbn; tauto)
      ltac:(apply keyb_nine; reflexivity)) as H.
    unfold ccg in H. cbn [gC gO] in H.
    cbn [ccolcost gC gO]. unfold M0. lia. }
  assert (Hb : cg-3 <= M0).
  { assert (HcgM : cg <= M0).
    { eapply literal_count_le with (o:=4) (z:=2).
      - unfold win. repeat rewrite in_app_iff. cbn. tauto.
      - reflexivity. }
    lia. }
  assert (HW : wcolcost (lin_flat sg pre) <= M0).
  { rewrite wcolcost_ccolcost.
    unfold M0, win.
    apply flat_middle_cost_le with (a:=[(2,2,J)%N])
      (c:=phase_form 0 ++ (4,2,cg)%N::rest) (f:=f). }
  pose proof (tick_partial_slot_quad_ub
    (bsum [(2,2,J)%N]) (cg-3)
    (wcolcost (lin_flat sg pre)) T M0 HBase Hb HW) as HSlot.
  assert (HT27 :
    T <= N.of_nat CFUEL * carm (M1 + 8*27) 27).
  { eapply N.le_trans; [exact HT|]. apply N.mul_le_mono_l, carm_mono;
      unfold M1, FlightDomC_cmeas; nia. }
  assert (HQ : chi (d_flight
      (bsum [(2,2,J)%N]) 27
      (dpartial1 (cg-3)
        (wcolcost (lin_flat sg pre)) + T))
      <= flightq M0 M1 27).
  { eapply N.le_trans; [exact HSlot|]. exact (flightq_from _ _ _ _ HT27). }
  assert (HClose : flightq M0 M1 27 <= CoarseC_flight_ub 27).
  { apply flightq_close; [unfold M0, win; exact HM0B|exact HM1B|].
    vm_compute. discriminate. }
  refine (creach_widen' _ (0%N,CoarseC_flight_ub 27) _ _ _ _ HR).
  - cbn [clo fst]. lia.
  - cbn [chi snd]. eapply N.le_trans; eassumption.
Qed.
Theorem tick_front_action_reachable0 :
  forall front sg ps J tail f hint q w3 sg3 ps3 f3 fs,
  stable_guard sg ((2,2,J)%N::tail) ->
  lin_tick_front_at front sg ps ((2,2,J)%N::tail) f hint =
    Some (q,w3,sg3,ps3,f3,fs) ->
  gmeas (lin_flat sg ((2,2,J)%N::tail)) f <= BMAX ->
  gmeas (lin_flat sg3 w3) f3 <= BMAX ->
  creach (0%N, CoarseC_flight_ub q)
    (wconf [] 0 (sdecode
      (lin_flat sg ((2,2,J)%N::tail)) f))
    (wconf [] 0 (sdecode (lin_flat sg3 w3) f3)).
Proof.
  intros front sg ps J tail f hint q w3 sg3 ps3 f3 fs
         HG HRun HM0B HM1B.
  unfold lin_tick_front_at in HRun. cbv beta zeta in HRun.
  destruct front as [r|]; [discriminate|].
  destruct (Nat.ltb (length sg) 2 ||
    negb (forallb (fun s => Nat.leb SEGMIN (segl s)) sg))
    eqn:EInit; [discriminate|].
  destruct (negb (f =? 4)) eqn:Ef; [discriminate|].
  cbn [N.eqb Pos.eqb andb] in HRun.
  destruct (negb (1 <=? J)%N) eqn:EJB; [discriminate|].
  apply negb_false_iff in EJB. apply N.leb_le in EJB.
  set (start := if Nat.ltb hint 1 then 1%nat else hint) in *.
  destruct (find_active ((2,2,J)%N::tail) start)
    as [i|] eqn:EFind; [|discriminate].
  destruct (negb (lin_transfer_prefix ((2,2,J)%N::tail) i))
    eqn:ECols; [discriminate|].
  apply negb_false_iff in ECols.
  destruct (detect_phase ((2,2,J)%N::tail) i)
    as [p|] eqn:EPhase; [|discriminate].
  set (q0 := if (Nat.eqb i 7 || Nat.eqb i 6) && (p =? 0)%N
    then 28%N else if Nat.eqb i 5 && (p =? 0)%N then 27%N else 0%N) in *.
  destruct ((q0 =? 0)%N) eqn:EQ0; [discriminate|].
  destruct (lin_tick_front_stage ((2,2,J)%N::tail) i)
    as [[[[[q1 w1] j2] rem] emit]|] eqn:EStage; [|discriminate].
  destruct (if Nat.eqb i 6 then lin_at_safe sg w1 j2 else Some w1)
    as [w1'|] eqn:EAtSafe; [|discriminate].
  set (wout := subst_at O 1 [(2,2,J+q1)%N] w1') in *.
  destruct (relocate_all sg ps wout) as [ps1|]
    eqn:ELocate; [|discriminate].
  destruct (lin_guard_at sg ps1 wout) eqn:EAt; [|discriminate].
  destruct (lin_casc_safe_at CFUEL sg ps1 wout f
    [lin_sched_child j2 rem emit p q1])
    as [[[[wC sgC] psC] fC]|] eqn:ECasc; [|discriminate].
  injection HRun as <- <- <- <- <- <-.
  pose proof HG as HG0.
  assert (HAlt : forall s, In s sg -> altb (sBody s) = true)
    by (exact (stable_altb sg ((2,2,J)%N::tail) HG0)).
  destruct (tick_stage_site
    ((2,2,J)%N::tail) i q1 w1 j2 rem emit EStage)
    as [Ei|[Ei|Ei]]; subst i.
  - unfold q0 in EQ0. cbn [Nat.eqb] in EQ0.
    destruct p as [|pp]; [|discriminate].
    destruct (tick_stage_5
      ((2,2,J)%N::tail) q1 w1 j2 rem emit EStage)
      as [a0 a1 a2 a3 a4 cg rest HIn HOut HRest Hcg Hq Hj Hr He].
    injection HIn as Ea0 Etail. subst a0 tail q1 j2 rem emit.
    cbn [Nat.eqb] in EAtSafe. injection EAtSafe as <-.
    assert (EWord : wout =
        (((2,2,J+27)%N::[a1;a2;a3;a4]) ++ phase_form 27 ++
          (4,2,cg-3)%N::rest)).
    { unfold wout. rewrite HOut. reflexivity. }
    rewrite EWord in EAt, ECasc.
    assert (HRaw : delivery_cols
        [a1;a2;a3;a4] = true).
    { pose proof (transfer_prefix_delivery_cols
        (2,2,J)%N
        (a1::a2::a3::a4::(7,1,1)%N::(3,2,1)%N::
          (4,2,cg)%N::rest) 5 ECols) as H.
      exact H. }
    assert (HFlat : delivery_cols
        (lin_flat sg [a1;a2;a3;a4]) = true).
    { exact (lin_flat_delivery_cols sg [a1;a2;a3;a4] HRaw HAlt). }
    change (stable_guard sg
      (((2,2,J)%N::[a1;a2;a3;a4]) ++ phase_form 0 ++
        (4,2,cg)%N::rest)) in HG.
    change (gmeas (lin_flat sg
      (((2,2,J)%N::[a1;a2;a3;a4]) ++ phase_form 0 ++
        (4,2,cg)%N::rest)) f <= BMAX) in HM0B.
    change (creach (0%N, CoarseC_flight_ub 27)
      (wconf [] 0 (sdecode (lin_flat sg
        (((2,2,J)%N::[a1;a2;a3;a4]) ++ phase_form 0 ++
          (4,2,cg)%N::rest)) f))
      (wconf [] 0 (sdecode (lin_flat sgC wC) fC))).
    exact (tick_partial_core_reachable0 sg J [a1;a2;a3;a4] cg rest
      f ps1 wC sgC psC fC HG EJB ltac:(cbn [length]; lia) Hcg HFlat
      EAt ECasc HM0B HM1B).
  - unfold q0 in EQ0. cbn [Nat.eqb] in EQ0.
    destruct p as [|pp]; [|discriminate].
    destruct (tick_stage_6
      ((2,2,J)%N::tail) q1 w1 j2 rem emit EPhase EStage)
      as (a0 & a1 & a2 & a3 & c & cg & rest & HIn & HOut & HRest &
          Hc & Hcg & Hq & Hj & Hr & He).
    injection HIn as Ea0 Etail. subst a0 tail q1 j2 rem emit.
    pose proof (lin_at_safe_some sg w1 4 w1' EAtSafe) as Ew1'.
    subst w1'.
    assert (EWord : wout =
        (((2,2,J+28)%N::[a1;a2;a3]) ++ phase_form 0 ++
          (4,2,c)%N::rung1 (cg-4)%N ++ rest)).
    { unfold wout. rewrite HOut. reflexivity. }
    rewrite EWord in EAt, ECasc.
    assert (HRawAll : delivery_cols
        ([a1;a2;a3] ++ rung1 c) = true).
    { pose proof (transfer_prefix_delivery_cols
        (2,2,J)%N
        (a1::a2::a3::(8,2,1)%N::(4,2,c)%N::
          (7,1,1)%N::(3,2,1)%N::(4,2,cg)%N::rest) 6 ECols) as H.
      exact H. }
    rewrite delivery_cols_app in HRawAll.
    apply andb_prop in HRawAll as [HRaw _].
    assert (HFlat : delivery_cols
        (lin_flat sg [a1;a2;a3]) = true).
    { exact (lin_flat_delivery_cols sg [a1;a2;a3] HRaw HAlt). }
    change (stable_guard sg
      (((2,2,J)%N::[a1;a2;a3]) ++ rung1 c ++
        phase_form 0 ++ (4,2,cg)%N::rest)) in HG.
    change (gmeas (lin_flat sg
      (((2,2,J)%N::[a1;a2;a3]) ++ rung1 c ++
        phase_form 0 ++ (4,2,cg)%N::rest)) f <= BMAX) in HM0B.
    change (creach (0%N, CoarseC_flight_ub 28)
      (wconf [] 0 (sdecode (lin_flat sg
        (((2,2,J)%N::[a1;a2;a3]) ++ rung1 c ++
          phase_form 0 ++ (4,2,cg)%N::rest)) f))
      (wconf [] 0 (sdecode (lin_flat sgC wC) fC))).
    exact (tick_full_core_reachable0 sg J [a1;a2;a3] c cg rest
      f ps1 wC sgC psC fC HG EJB Hc Hcg HFlat EAt ECasc HM0B HM1B).
  - unfold q0 in EQ0. cbn [Nat.eqb] in EQ0.
    destruct p as [|pp]; [|discriminate].
    destruct (tick_stage_7
      ((2,2,J)%N::tail) q1 w1 j2 rem emit EStage)
      as [a0 a1 a2 a3 a4 c cg rest HIn HOut HRest Hc Hcg Hq Hj Hr He].
    injection HIn as Ea0 Etail. subst a0 tail q1 j2 rem emit.
    cbn [Nat.eqb] in EAtSafe. injection EAtSafe as <-.
    assert (EWord : wout =
        (((2,2,J+28)%N::[a1;a2;a3;a4]) ++ phase_form 0 ++
          (4,2,c)%N::rung1 (cg-4)%N ++ rest)).
    { unfold wout. rewrite HOut. reflexivity. }
    rewrite EWord in EAt, ECasc.
    assert (HRawAll : delivery_cols
        ([a1;a2;a3;a4] ++ rung1 c) = true).
    { pose proof (transfer_prefix_delivery_cols
        (2,2,J)%N
        (a1::a2::a3::a4::(8,2,1)%N::(4,2,c)%N::
          (7,1,1)%N::(3,2,1)%N::(4,2,cg)%N::rest) 7 ECols) as H.
      exact H. }
    rewrite delivery_cols_app in HRawAll.
    apply andb_prop in HRawAll as [HRaw _].
    assert (HFlat : delivery_cols
        (lin_flat sg [a1;a2;a3;a4]) = true).
    { exact (lin_flat_delivery_cols sg [a1;a2;a3;a4] HRaw HAlt). }
    change (stable_guard sg
      (((2,2,J)%N::[a1;a2;a3;a4]) ++ rung1 c ++
        phase_form 0 ++ (4,2,cg)%N::rest)) in HG.
    change (gmeas (lin_flat sg
      (((2,2,J)%N::[a1;a2;a3;a4]) ++ rung1 c ++
        phase_form 0 ++ (4,2,cg)%N::rest)) f <= BMAX) in HM0B.
    change (creach (0%N, CoarseC_flight_ub 28)
      (wconf [] 0 (sdecode (lin_flat sg
        (((2,2,J)%N::[a1;a2;a3;a4]) ++ rung1 c ++
          phase_form 0 ++ (4,2,cg)%N::rest)) f))
      (wconf [] 0 (sdecode (lin_flat sgC wC) fC))).
    exact (tick_full_core_reachable0 sg J [a1;a2;a3;a4] c cg rest
      f ps1 wC sgC psC fC HG EJB Hc Hcg HFlat EAt ECasc HM0B HM1B).
Qed.
Lemma lin_try_at_reachable0 (k : nat) :
  forall sg ps J tail f i p m t w3 sg3 ps3 f3 fs,
  stable_guard sg ((2,2,J)%N::tail) ->
  (1 <= J)%N -> (3 <= i)%nat ->
  forallb is_col (firstn i ((2,2,J)%N::tail)) = true ->
  detect_phase ((2,2,J)%N::tail) i = Some p ->
  lin_try_at k sg ps ((2,2,J)%N::tail) f J i p m =
    Some (t,w3,sg3,ps3,f3,fs) ->
  gmeas (lin_flat sg ((2,2,J)%N::tail)) f <= BMAX ->
  gmeas (lin_flat sg3 w3) f3 <= BMAX ->
  creach (0%N, CoarseC_flight_ub t)
    (wconf [] 0 (sdecode
      (lin_flat sg ((2,2,J)%N::tail)) f))
    (wconf [] 0 (sdecode (lin_flat sg3 w3) f3)).
Proof.
  induction k as [|k IH];
    intros sg ps J tail f i p m t w3 sg3 ps3 f3 fs
      HG HJ Hi HCols HD HRun HM0B HM1B.
  - cbn [lin_try_at] in HRun. discriminate.
  - cbn [lin_try_at] in HRun.
    destruct (Nat.eqb m O) eqn:Hm; [discriminate|].
    apply PeanoNat.Nat.eqb_neq in Hm.
    set (tk := (28 * N.of_nat m - p)%N) in *.
    destruct (lin_bulk sg ((2,2,J)%N::tail) i p tk)
      as [[[[[w1 sg1] nh] rem] emit]|] eqn:HB; [|discriminate].
    destruct (lin_at_safe sg1
      (subst_at O 1 [(2,2,J+tk)%N] w1) nh)
      as [w2|] eqn:HAtSafe.
    2: { exact (IH sg ps J tail f i p (Nat.div2 m)
          t w3 sg3 ps3 f3 fs HG HJ Hi HCols HD HRun HM0B HM1B). }
    pose proof (lin_at_safe_some sg1
      (subst_at O 1 [(2,2,J+tk)%N] w1) nh w2 HAtSafe) as Ew2.
    subst w2.
    destruct (locate_all sg1
      (subst_at O 1 [(2,2,J+tk)%N] w1))
      as [ps1|] eqn:HLocate.
    2: { exact (IH sg ps J tail f i p (Nat.div2 m)
          t w3 sg3 ps3 f3 fs HG HJ Hi HCols HD HRun HM0B HM1B). }
    destruct (lin_keep_at sg1 ps1
      (subst_at O 1 [(2,2,J+tk)%N] w1)
      [((nh + phase_len rem)%nat,emit)])
      as [[[[sgA psA] wA] stA]|] eqn:HKeep.
    2: { exact (IH sg ps J tail f i p (Nat.div2 m)
          t w3 sg3 ps3 f3 fs HG HJ Hi HCols HD HRun HM0B HM1B). }
    unfold lin_keep_at in HKeep.
    destruct (lin_guard_at sg1 ps1
      (subst_at O 1 [(2,2,J+tk)%N] w1))
      eqn:HAt; [|discriminate].
    injection HKeep as <- <- <- <-.
    change
      (match lin_casc_safe_at CFUEL sg1 ps1
          (subst_at O 1 [(2,2,J+tk)%N] w1) f
          [lin_sched_child nh rem emit p tk] with
       | Some (wc,sgc,psc,fc) =>
           Some (tk,wc,sgc,psc,fc,fmapw sg1 w1 O O (nh+2)%nat)
       | None =>
           lin_try_at k sg ps ((2,2,J)%N::tail) f J i p (Nat.div2 m)
       end = Some (t,w3,sg3,ps3,f3,fs)) in HRun.
    destruct (lin_casc_safe_at CFUEL sg1 ps1
      (subst_at O 1 [(2,2,J+tk)%N] w1) f
      [lin_sched_child nh rem emit p tk])
      as [[[[wC sgC] psC] fC]|] eqn:HCasc.
    2: { cbv beta iota in HRun.
         exact (IH sg ps J tail f i p (Nat.div2 m)
           t w3 sg3 ps3 f3 fs HG HJ Hi HCols HD HRun HM0B HM1B). }
    cbv beta iota in HRun. injection HRun as <- <- <- <- <- <-.
    destruct (lin_bulk_master_stable
      sg ps1 J tail i p tk w1 sg1 nh rem emit HG ltac:(lia) HD HB HAt)
      as (HStable1 & HGuard1 & HHead1 & Hnh).
    assert (HFramePos : frame_pos
      (lin_sched_child nh rem emit p tk)).
    { unfold tk. exact
        (lin_bulk_generation_frame_pos
          sg J tail i p m w1 sg1 nh rem emit Hi Hm HD HB). }
    destruct (detect_phase_form ((2,2,J)%N::tail) i p HD)
      as (Hp & HPhase).
    assert (HFull : Nat.eqb (N.to_nat ((p+tk)/28)) O = false).
    { unfold tk. exact
        (generation_take_full p m Hp Hm). }
    exact (flight_core_reachable0 sg J tail f i p tk w1 sg1 nh rem emit
      ps1 sgC wC psC fC HG HJ ltac:(lia) HCols HD HFull HB
      HStable1 HGuard1 HHead1 HFramePos HCasc HM0B HM1B).
Qed.
Theorem gen_action_reachable0 :
  forall front sg ps J tail f h t w2 sg2 ps2 f2 fs,
  stable_guard sg ((2,2,J)%N::tail) ->
  lin_gen_action_at front sg ps ((2,2,J)%N::tail) f h =
    Some (Some (t,w2,sg2,ps2,f2,fs)) ->
  gmeas (lin_flat sg ((2,2,J)%N::tail)) f <= BMAX ->
  gmeas (lin_flat sg2 w2) f2 <= BMAX ->
  creach (0%N, CoarseC_flight_ub t)
    (wconf [] 0 (sdecode
      (lin_flat sg ((2,2,J)%N::tail)) f))
    (wconf [] 0 (sdecode (lin_flat sg2 w2) f2)).
Proof.
  intros front sg ps J tail f h t w2 sg2 ps2 f2 fs HG HRun HM0B HM1B.
  unfold lin_gen_action_at in HRun. cbv beta zeta in HRun.
  cbn [N.eqb Pos.eqb andb] in HRun.
  destruct (negb (front_blind ((2,2,J)%N::tail)))
    eqn:HBlind; [discriminate|].
  destruct front as [r|]; [discriminate|].
  destruct (negb (f =? 4)) eqn:Hf; [discriminate|].
  set (start := if Nat.ltb h 1 then 1%nat else h) in *.
  destruct (find_active ((2,2,J)%N::tail) start)
    as [i|] eqn:HFind; [|discriminate].
  destruct (negb (Nat.ltb (S MARGIN) i))
    eqn:HMargin; [discriminate|].
  apply negb_false_iff in HMargin.
  lazymatch type of HRun with
  | context [if negb ?colsok then _ else _] => destruct colsok eqn:HCols
  end; [|discriminate].
  destruct (detect_phase ((2,2,J)%N::tail) i)
    as [p|] eqn:HPhase; [|discriminate].
  set (k0 := (i-1)%nat) in *.
  set (clean1 :=
    if Nat.ltb k0 1 then false
    else match wat ((2,2,J)%N::tail) k0,
               wat ((2,2,J)%N::tail) (k0-1) with
         | Some l, Some sp => lvl_big l && spacer sp
         | _, _ => false
         end) in *.
  destruct (negb clean1) eqn:HClean; [discriminate|].
  destruct (negb (1 <=? J)%N) eqn:HJb; [discriminate|].
  apply negb_false_iff in HJb. apply N.leb_le in HJb.
  set (mmax := Nat.div2
    (fmapw sg ((2,2,J)%N::tail) O O i - MARGIN)) in *.
  set (m := lin_count_clean sg ((2,2,J)%N::tail) k0 mmax) in *.
  injection HRun as HTry.
  exact (lin_try_at_reachable0 TRIES sg ps J tail f i p m
    t w2 sg2 ps2 f2 fs HG HJb
    ltac:(apply PeanoNat.Nat.ltb_lt in HMargin;
          unfold MARGIN in HMargin; lia)
    HCols HPhase HTry HM0B HM1B).
Qed.
Theorem gen_action_reachable0_general :
  forall front sg ps w f h t w2 sg2 ps2 f2 fs,
  stable_guard sg w ->
  lin_gen_action_at front sg ps w f h =
    Some (Some (t,w2,sg2,ps2,f2,fs)) ->
  gmeas (lin_flat sg w) f <= BMAX ->
  gmeas (lin_flat sg2 w2) f2 <= BMAX ->
  creach (0%N, CoarseC_flight_ub t)
    (wconf [] 0 (sdecode (lin_flat sg w) f))
    (wconf [] 0 (sdecode (lin_flat sg2 w2) f2)).
Proof.
  intros front sg ps w f h t w2 sg2 ps2 f2 fs HG HRun HM0 HM1.
  pose proof HRun as HShape.
  unfold lin_gen_action_at in HShape. cbv beta zeta in HShape.
  destruct (negb (front_blind w)); [discriminate|].
  destruct front; [discriminate|].
  destruct (negb (f =? 4)); [discriminate|].
  destruct w as [|[[o z] J] tail]; [discriminate|].
  destruct o as [|op]; cbn in HShape; try discriminate.
  destruct op as [op1|op1|]; cbn in HShape; try discriminate.
  destruct op1 as [op2|op2|]; cbn in HShape; try discriminate.
  destruct z as [|zp]; cbn in HShape; try discriminate.
  destruct zp as [zp1|zp1|]; cbn in HShape; try discriminate.
  destruct zp1 as [zp2|zp2|]; cbn in HShape; try discriminate.
  change (stable_guard sg ((2,2,J)%N::tail)) in HG.
  change (lin_gen_action_at None sg ps ((2,2,J)%N::tail) f h =
    Some (Some (t,w2,sg2,ps2,f2,fs))) in HRun.
  exact (gen_action_reachable0 None sg ps J tail f h t w2 sg2 ps2 f2 fs
    HG HRun HM0 HM1).
Qed.
Theorem tick_front_action_reachable0_general :
  forall front sg ps w f hint q w3 sg3 ps3 f3 fs,
  stable_guard sg w ->
  lin_tick_front_at front sg ps w f hint =
    Some (q,w3,sg3,ps3,f3,fs) ->
  gmeas (lin_flat sg w) f <= BMAX ->
  gmeas (lin_flat sg3 w3) f3 <= BMAX ->
  creach (0%N, CoarseC_flight_ub q)
    (wconf [] 0 (sdecode (lin_flat sg w) f))
    (wconf [] 0 (sdecode (lin_flat sg3 w3) f3)).
Proof.
  intros front sg ps w f hint q w3 sg3 ps3 f3 fs HG HRun HM0 HM1.
  pose proof HRun as HShape.
  unfold lin_tick_front_at in HShape. cbv beta zeta in HShape.
  destruct front as [r|]; [discriminate|].
  destruct (Nat.ltb (length sg) 2 ||
    negb (forallb (fun s => Nat.leb SEGMIN (segl s)) sg));
    [discriminate|].
  destruct (negb (f =? 4)); [discriminate|].
  destruct w as [|[[o z] J] tail]; [discriminate|].
  destruct o as [|op]; cbn in HShape; try discriminate.
  destruct op as [op1|op1|]; cbn in HShape; try discriminate.
  destruct op1 as [op2|op2|]; cbn in HShape; try discriminate.
  destruct z as [|zp]; cbn in HShape; try discriminate.
  destruct zp as [zp1|zp1|]; cbn in HShape; try discriminate.
  destruct zp1 as [zp2|zp2|]; cbn in HShape; try discriminate.
  change (stable_guard sg ((2,2,J)%N::tail)) in HG.
  change (lin_tick_front_at None sg ps ((2,2,J)%N::tail) f hint =
    Some (q,w3,sg3,ps3,f3,fs)) in HRun.
  exact (tick_front_action_reachable0 None sg ps J tail f hint q
    w3 sg3 ps3 f3 fs HG HRun HM0 HM1).
Qed.
Local Open Scope N_scope.
Opaque FLAT_ROUND_FUEL LROUND_FUEL LROUND_CHUNKS
       CFUEL TRIES.
Notation CondW32_cmeas := FlightDomC_cmeas.
Notation CondW32_CascInv := CascInv.
Definition Bounded (w : word) (f : N) (Lm : N) : Prop :=
  (gmeas w f <= Lm + ALLOW)%N /\
  (Lm <= TERM_UB + 7)%N.
Lemma try_at_domS (k : nat) :
  forall (sg : list seg) (ps : atab) (J : N) (tail : word)
         (f : N) (i : nat) (p : N) (m : nat)
         (t : N) (w3 : word) (sg3 : list seg) (ps3 : atab)
         (f3 : N) (fs : nat),
    stable_guard sg ((2,2,J)%N :: tail) ->
    (3 <= i)%nat ->
    detect_phase ((2,2,J)%N :: tail) i = Some p ->
    lin_try_at k sg ps ((2,2,J)%N :: tail) f J i p m
      = Some (t, w3, sg3, ps3, f3, fs) ->
    (CondW32_cmeas sg ((2,2,J)%N :: tail) f <= CondW32_cmeas sg3 w3 f3 + 2 * t)%N.
Proof.
  induction k as [|k IH];
    intros sg ps J tail f i p m t w3 sg3 ps3 f3 fs HS Hi HD HT;
    [discriminate HT|].
  cbn [lin_try_at] in HT.
  destruct (Nat.eqb m O) eqn:EM; [discriminate HT|].
  apply PeanoNat.Nat.eqb_neq in EM.
  destruct (detect_phase_form _ i p HD) as (Hp & _).
  set (t0 := (28 * N.of_nat m - p)%N) in HT.
  assert (Hpt : (p + t0 = 28 * N.of_nat m)%N).
  { unfold t0. assert (H1 : (1 <= N.of_nat m)%N) by lia. lia. }
  assert (HLn : ((p + t0) / 28 = N.of_nat m)%N).
  { rewrite Hpt, (N.mul_comm 28 (N.of_nat m)).
    apply N.div_mul. discriminate. }
  assert (HFull : Nat.eqb (N.to_nat ((p + t0) / 28)) O = false).
  { rewrite HLn, Nat2N.id. apply PeanoNat.Nat.eqb_neq. exact EM. }
  destruct (lin_bulk sg ((2,2,J)%N :: tail) i p t0)
    as [[[[[w1 sg1] j2] rem] emit]|] eqn:EB; [|discriminate HT].
  destruct (bulk_master_ccol sg J tail f i p t0 w1 sg1 j2 rem emit
              HS ltac:(lia) HD HFull EB) as (HRem & HEm & _ & HId).
  assert (HRem0 : rem = 0%N).
  { rewrite HRem, Hpt, (N.mul_comm 28 (N.of_nat m)).
    apply N.mod_mul. discriminate. }
  destruct (lin_at_safe sg1
              (subst_at O 1 [(2,2,J + t0)%N] w1) j2) as [w2|] eqn:EA;
    [|exact (IH sg ps J tail f i p (Nat.div2 m) t w3 sg3 ps3 f3 fs
               HS Hi HD HT)].
  pose proof (lin_at_safe_some sg1 _ j2 w2 EA) as EW2.
  destruct (locate_all sg1 w2) as [ps1|] eqn:EL;
    [|exact (IH sg ps J tail f i p (Nat.div2 m) t w3 sg3 ps3 f3 fs
               HS Hi HD HT)].
  unfold lin_keep_at in HT.
  destruct (lin_guard_at sg1 ps1 w2) eqn:EG;
    [|exact (IH sg ps J tail f i p (Nat.div2 m) t w3 sg3 ps3 f3 fs
               HS Hi HD HT)].
  destruct (lin_casc_safe_at CFUEL sg1 ps1 w2 f
              [lin_sched_child j2 rem emit p t0])
    as [[[[wF sgF] psF] fF]|] eqn:EC;
    [|exact (IH sg ps J tail f i p (Nat.div2 m) t w3 sg3 ps3 f3 fs
               HS Hi HD HT)].
  apply some_inj in HT.
  injection HT as Et Ew Esg Eps Ef _.
  subst t w3 sg3 ps3 f3.
  assert (HGA : lin_guard_at sg1 ps1
                  (subst_at O 1 [(2,2,J + t0)%N] w1) = true)
    by (rewrite <- EW2; exact EG).
  assert (HINV : CondW32_CascInv sg1 w2).
  { rewrite EW2.
    destruct (lin_bulk_master_stable sg ps1 J tail i p t0
                w1 sg1 j2 rem emit HS ltac:(lia) HD EB HGA)
      as (A1 & A2 & A3 & _).
    exact (conj A1 (conj A2 A3)). }
  assert (HFOR : Forall frame_pos [lin_sched_child j2 rem emit p t0]).
  { constructor; [|constructor].
    unfold t0.
    exact (lin_bulk_generation_frame_pos sg J tail i p m
             w1 sg1 j2 rem emit Hi EM HD EB). }
  pose proof (cascdom_ofS CFUEL sg1 ps1 w2 f
                [lin_sched_child j2 rem emit p t0] wF sgF psF fF
                HINV HFOR EC) as HC.
  rewrite cascticks_one in HC.
  cbn [lin_sched_child lsTicks] in HC.
  rewrite EW2 in HC.
  assert (HFit : (8 * emit <= 10 * t0)%N).
  { exact (casc_fits p t0 (N.of_nat m) emit Hp ltac:(lia)
             ltac:(rewrite Hpt; reflexivity) HEm). }
  pose proof (phd_hi p Hp) as HPH.
  rewrite HRem0, phd0 in HId. rewrite HLn in HId.
  lia.
Qed.
Theorem flight_domS : FlightDom.
Proof.
  unfold FlightDom.
  intros fr sg ps cw f h t cw2 sg2 ps2 f2 fs HS HG.
  unfold lin_gen_action_at in HG.
  destruct (negb (front_blind cw)); [discriminate HG|].
  destruct fr; [discriminate HG|].
  destruct (negb (f =? 4)%N); [discriminate HG|].
  destruct cw as [|[[o z] cN] tail]; [discriminate HG|].
  destruct o as [|op]; [discriminate HG|].
  destruct op as [op1|op1|]; try discriminate HG.
  destruct op1; try discriminate HG.
  destruct z as [|zp]; [discriminate HG|].
  destruct zp as [zp1|zp1|]; try discriminate HG.
  destruct zp1; try discriminate HG.
  cbv beta iota zeta in HG.
  match type of HG with
  | context [find_active ?a ?b] =>
      destruct (find_active a b) as [i|] eqn:EF
  end; [|discriminate HG].
  match type of HG with
  | context [Nat.ltb (S MARGIN) ?x] =>
      destruct (Nat.ltb (S MARGIN) x) eqn:EI
  end; cbn [negb] in HG; [|discriminate HG].
  apply PeanoNat.Nat.ltb_lt in EI.
  match type of HG with
  | context [forallb is_col ?x] =>
      destruct (forallb is_col x) eqn:EJ
  end; cbn [negb] in HG; [|discriminate HG].
  match type of HG with
  | context [detect_phase ?a ?b] =>
      destruct (detect_phase a b) as [p|] eqn:ED
  end; [|discriminate HG].
  match type of HG with
  | context [negb ?b] => destruct b eqn:EK
  end; cbn [negb] in HG; [|discriminate HG].
  match type of HG with
  | context [negb ?b] => destruct b eqn:EL
  end; cbn [negb] in HG; [|discriminate HG].
  apply some_inj in HG.
  exact (try_at_domS TRIES sg ps cN tail f i p
           (lin_count_clean sg ((2,2,cN)%N :: tail) (i - 1)
              (Nat.div2 (fmapw sg ((2,2,cN)%N :: tail) O O i
                         - MARGIN)))
           t cw2 sg2 ps2 f2 fs HS
           ltac:(unfold MARGIN in EI; lia) ED HG).
Qed.
Lemma cascinv_full (sg : list seg) (ps1 : atab) (J c cg : N)
      (pre rest : word) :
  stable_guard sg
    (((2,2,J)%N :: pre) ++ rung1 c ++
      phase_form 0 ++ (4,2,cg)%N :: rest) ->
  lin_guard_at sg ps1
    (((2,2,J+28)%N :: pre) ++ phase_form 0 ++ (4,2,c)%N ::
      rung1 (cg-4)%N ++ rest) = true ->
  CondW32_CascInv sg
    (((2,2,J+28)%N :: pre) ++ phase_form 0 ++ (4,2,c)%N ::
      rung1 (cg-4)%N ++ rest).
Proof.
  intros HG HAt.
  assert (HGm : stable_guard sg
    (((2,2,J+28)%N :: pre) ++ rung1 c ++
      phase_form 0 ++ (4,2,cg)%N :: rest)).
  { change (stable_guard sg
      ((2,2,J+28)%N :: (pre ++ rung1 c ++
        phase_form 0 ++ (4,2,cg)%N :: rest))).
    change (stable_guard sg
      ((2,2,J)%N :: (pre ++ rung1 c ++
        phase_form 0 ++ (4,2,cg)%N :: rest))) in HG.
    exact (stable_guard_master_change_probe sg J (J+28) _ HG). }
  assert (ESeq : phseq
      (((2,2,J+28)%N :: pre) ++ phase_form 0 ++ (4,2,c)%N ::
        rung1 (cg-4)%N ++ rest)
    = phseq
      (((2,2,J+28)%N :: pre) ++ rung1 c ++
        phase_form 0 ++ (4,2,cg)%N :: rest))
    by exact (phseq_full_cross (J+28) (J+28) pre c cg rest).
  assert (HFront : front_repr sg
      (((2,2,J+28)%N :: pre) ++ phase_form 0 ++ (4,2,c)%N ::
        rung1 (cg-4)%N ++ rest))
    by exact (front_repr_phseq sg _ _ HGm ESeq).
  assert (HGuard : lin_guard sg
      (((2,2,J+28)%N :: pre) ++ phase_form 0 ++ (4,2,c)%N ::
        rung1 (cg-4)%N ++ rest) = true).
  { exact (lin_guard_at_sound sg ps1 _ (proj1 HFront) HAt). }
  split; [|split].
  - exact (tick_full_master_stable sg J pre c cg rest HG HGuard).
  - exact HGuard.
  - reflexivity.
Qed.
Lemma cascinv_partial (sg : list seg) (ps1 : atab) (J cg : N)
      (pre rest : word) :
  stable_guard sg
    (((2,2,J)%N :: pre) ++ phase_form 0 ++ (4,2,cg)%N :: rest) ->
  lin_guard_at sg ps1
    (((2,2,J+27)%N :: pre) ++ phase_form 27 ++
      (4,2,cg-3)%N :: rest) = true ->
  CondW32_CascInv sg
    (((2,2,J+27)%N :: pre) ++ phase_form 27 ++
      (4,2,cg-3)%N :: rest).
Proof.
  intros HG HAt.
  assert (HGm : stable_guard sg
    (((2,2,J+27)%N :: pre) ++ phase_form 0 ++
      (4,2,cg)%N :: rest)).
  { change (stable_guard sg
      ((2,2,J+27)%N :: (pre ++ phase_form 0 ++
        (4,2,cg)%N :: rest))).
    change (stable_guard sg
      ((2,2,J)%N :: (pre ++ phase_form 0 ++
        (4,2,cg)%N :: rest))) in HG.
    exact (stable_guard_master_change_probe sg J (J+27) _ HG). }
  assert (ESeq : phseq
      (((2,2,J+27)%N :: pre) ++ phase_form 27 ++
        (4,2,cg-3)%N :: rest)
    = phseq
      (((2,2,J+27)%N :: pre) ++ phase_form 0 ++
        (4,2,cg)%N :: rest))
    by exact (phseq_partial_tick (J+27) (J+27) pre cg rest).
  assert (HFront : front_repr sg
      (((2,2,J+27)%N :: pre) ++ phase_form 27 ++
        (4,2,cg-3)%N :: rest))
    by exact (front_repr_phseq sg _ _ HGm ESeq).
  assert (HGuard : lin_guard sg
      (((2,2,J+27)%N :: pre) ++ phase_form 27 ++
        (4,2,cg-3)%N :: rest) = true).
  { exact (lin_guard_at_sound sg ps1 _ (proj1 HFront) HAt). }
  split; [|split].
  - exact (tick_partial_master_stable sg J pre cg rest HG HGuard).
  - exact HGuard.
  - reflexivity.
Qed.
Lemma tick_cascinv (sg : list seg) (ps1 : atab) (cN qs : N)
      (tail w1 : word) (i j2 : nat) (rem emit : N) :
  stable_guard sg ((2,2,cN)%N :: tail) ->
  detect_phase ((2,2,cN)%N :: tail) i = Some 0%N ->
  lin_tick_front_stage ((2,2,cN)%N :: tail) i
    = Some (qs, w1, j2, rem, emit) ->
  lin_guard_at sg ps1 (subst_at O 1 [(2,2,cN + qs)%N] w1) = true ->
  CondW32_CascInv sg (subst_at O 1 [(2,2,cN + qs)%N] w1)
  /\ frame_pos (lin_sched_child j2 rem emit 0%N qs).
Proof.
  intros HG HD HSt HAt.
  destruct (tick_stage_site _ i qs w1 j2 rem emit HSt) as [E|[E|E]];
    subst i.
  -
    destruct (tick_stage_5 _ qs w1 j2 rem emit HSt)
      as [a0 a1 a2 a3 a4 cg rest Ew Ew1 _ Hcg Eq Ej Er Ee].
    injection Ew as Ea0 Et. subst a0 tail qs j2 rem emit.
    assert (EWord : subst_at O 1 [(2,2,cN + 27)%N] w1
                  = ((2,2,cN + 27)%N :: [a1;a2;a3;a4])
                      ++ phase_form 27 ++ (4,2,cg-3)%N :: rest)
      by (rewrite Ew1; reflexivity).
    rewrite EWord in HAt |- *.
    change (stable_guard sg
      (((2,2,cN)%N :: [a1;a2;a3;a4]) ++ phase_form 0 ++
        (4,2,cg)%N :: rest)) in HG.
    split.
    + exact (cascinv_partial sg ps1 cN cg [a1;a2;a3;a4] rest HG HAt).
    + unfold frame_pos, lin_sched_child. cbn [lsCur]. lia.
  -
    destruct (tick_stage_6 _ qs w1 j2 rem emit HD HSt)
      as (a0 & a1 & a2 & a3 & c & cg & rest & Ew & Ew1 & _ & Hc & Hcg
          & Eq & Ej & Er & Ee).
    injection Ew as Ea0 Et. subst a0 tail qs j2 rem emit.
    assert (EWord : subst_at O 1 [(2,2,cN + 28)%N] w1
                  = ((2,2,cN + 28)%N :: [a1;a2;a3])
                      ++ phase_form 0 ++ (4,2,c)%N ::
                      rung1 (cg-4)%N ++ rest)
      by (rewrite Ew1; reflexivity).
    rewrite EWord in HAt |- *.
    change (stable_guard sg
      (((2,2,cN)%N :: [a1;a2;a3]) ++ rung1 c ++
        phase_form 0 ++ (4,2,cg)%N :: rest)) in HG.
    split.
    + exact (cascinv_full sg ps1 cN c cg [a1;a2;a3] rest HG HAt).
    + unfold frame_pos, lin_sched_child. cbn [lsCur]. lia.
  -
    destruct (tick_stage_7 _ qs w1 j2 rem emit HSt)
      as [a0 a1 a2 a3 a4 c cg rest Ew Ew1 _ Hc Hcg Eq Ej Er Ee].
    injection Ew as Ea0 Et. subst a0 tail qs j2 rem emit.
    assert (EWord : subst_at O 1 [(2,2,cN + 28)%N] w1
                  = ((2,2,cN + 28)%N :: [a1;a2;a3;a4])
                      ++ phase_form 0 ++ (4,2,c)%N ::
                      rung1 (cg-4)%N ++ rest)
      by (rewrite Ew1; reflexivity).
    rewrite EWord in HAt |- *.
    change (stable_guard sg
      (((2,2,cN)%N :: [a1;a2;a3;a4]) ++ rung1 c ++
        phase_form 0 ++ (4,2,cg)%N :: rest)) in HG.
    split.
    + exact (cascinv_full sg ps1 cN c cg [a1;a2;a3;a4] rest HG HAt).
    + unfold frame_pos, lin_sched_child. cbn [lsCur]. lia.
Qed.
Lemma tick_tail_domS (sg : list seg) (ps1 : atab)
      (cN q f p : N) (tail w1 : word) (j2 : nat) (rem emit : N)
      (w3 : word) (sg3 : list seg) (ps3 : atab) (f3 : N) :
  CondW32_CascInv sg (subst_at O 1 [(2,2,cN + q)%N] w1) ->
  frame_pos (lin_sched_child j2 rem emit p q) ->
  lin_casc_safe_at CFUEL sg ps1
     (subst_at O 1 [(2,2,cN + q)%N] w1) f
     [lin_sched_child j2 rem emit p q] = Some (w3, sg3, ps3, f3) ->
  (CondW32_cmeas sg ((2,2,cN)%N :: tail) f + 210
   <= CondW32_cmeas sg (subst_at O 1 [(2,2,cN + q)%N] w1) f)%N ->
  (emit <= 4)%N ->
  (CondW32_cmeas sg ((2,2,cN)%N :: tail) f <= CondW32_cmeas sg3 w3 f3 + 2*q)%N.
Proof.
  intros HINV HPos EC HS He.
  pose proof (cascdom_ofS CFUEL sg ps1
                (subst_at O 1 [(2,2,cN + q)%N] w1) f
                [lin_sched_child j2 rem emit p q] w3 sg3 ps3 f3
                HINV (Forall_cons _ HPos (Forall_nil _)) EC) as HC.
  rewrite cascticks_one in HC.
  cbn [lin_sched_child lsTicks] in HC. lia.
Qed.
Definition TickFrontDomS : Prop :=
  forall (fr : option res) (sg : list seg) (ps : atab)
         (cw : word) (f : N) (h : nat)
         (q : N) (cw2 : word) (sg2 : list seg) (ps2 : atab)
         (f2 : N) (fs : nat),
    stable_guard sg cw ->
    lin_tick_front_at fr sg ps cw f h = Some (q, cw2, sg2, ps2, f2, fs) ->
    (CondW32_cmeas sg cw f <= CondW32_cmeas sg2 cw2 f2 + 2 * q)%N.
Theorem tick_front_domS : TickFrontDomS.
Proof.
  unfold TickFrontDomS.
  intros fr sg ps cw f h q cw2 sg2 ps2 f2 fs HSt HG.
  pose proof HG as HG0.
  unfold lin_tick_front_at in HG.
  destruct fr; [discriminate HG|].
  destruct (Nat.ltb (length sg) 2
            || negb (forallb (fun s => Nat.leb SEGMIN (segl s)) sg))%bool;
    [discriminate HG|].
  destruct (negb (f =? 4)%N); [discriminate HG|].
  destruct cw as [|[[o z] cN] tail]; [discriminate HG|].
  destruct o as [|op]; [discriminate HG|].
  destruct op as [op1|op1|]; try discriminate HG.
  destruct op1; try discriminate HG.
  destruct z as [|zp]; [discriminate HG|].
  destruct zp as [zp1|zp1|]; try discriminate HG.
  destruct zp1; try discriminate HG.
  change (stable_guard sg ((2,2,cN)%N :: tail)) in HSt.
  cbv beta iota zeta in HG.
  match type of HG with context [negb ?b] => destruct b eqn:ECN end;
    cbn [negb] in HG; [|discriminate HG].
  match type of HG with
  | context [find_active ?a ?b] =>
      destruct (find_active a b) as [i|] eqn:EF
  end; [|discriminate HG].
  match type of HG with context [negb ?b] => destruct b eqn:ETP end;
    cbn [negb] in HG; [|discriminate HG].
  match type of HG with
  | context [detect_phase ?a ?b] =>
      destruct (detect_phase a b) as [p|] eqn:ED
  end; [|discriminate HG].
  match type of HG with
  | context [(?x =? 0)%N] => destruct (x =? 0)%N eqn:EQ0
  end; [discriminate HG|].
  assert (Hp0 : p = 0%N).
  { destruct (p =? 0)%N eqn:Ep; [apply N.eqb_eq in Ep; exact Ep|].
    exfalso. rewrite !Bool.andb_false_r in EQ0. cbn in EQ0. discriminate. }
  subst p.
  match type of HG with
  | context [lin_tick_front_stage ?a ?b] =>
      destruct (lin_tick_front_stage a b)
        as [[[[[qs w1] j2] rem] emit]|] eqn:EST
  end; [|discriminate HG].
  destruct (tick_stage_dom sg cN tail w1 i qs j2 rem emit f ED EST)
    as (HStt & He & Hq).
  match type of HG with
  | context [if Nat.eqb ?x 6 then ?u else ?v] =>
      remember (if Nat.eqb x 6 then u else v) as OA eqn:EOA
  end.
  destruct OA as [w1'|]; [|discriminate HG].
  pose proof (at_safe_or_id sg i j2 w1 w1' (eq_sym EOA)) as EW1.
  subst w1'.
  match type of HG with
  | context [relocate_all ?a ?b ?c] =>
      destruct (relocate_all a b c) as [ps1|] eqn:ERL
  end; [|discriminate HG].
  match type of HG with
  | context [lin_guard_at ?a ?b ?c] =>
      destruct (lin_guard_at a b c) eqn:EGA
  end; [|discriminate HG].
  match type of HG with
  | context [lin_casc_safe_at ?fu ?a ?b ?c ?d ?e] =>
      destruct (lin_casc_safe_at fu a b c d e)
        as [[[[wF sgF] psF] fF]|] eqn:ECS
  end; [|discriminate HG].
  injection HG as Eq Ew Esg Eps Ef _. subst q cw2 sg2 ps2 f2.
  destruct (tick_cascinv sg ps1 cN qs tail w1 i j2 rem emit
              HSt ED EST EGA) as (HINV & HPos).
  exact (tick_tail_domS sg ps1 cN qs f 0%N tail w1 j2 rem emit
           wF sgF psF fF HINV HPos ECS HStt He).
Qed.
Theorem condarms : CondArms.
Proof.
  refine (MkCondArms _ _ _).
  - exact flight_domS.
  - exact tick_front_domS.
  - exact micro_dom.
Qed.
Definition CondW32_cond_round_dom := cond_round_dom condarms.
Definition CondW32_cond_chunked_dom := cond_chunked_dom condarms.
Definition CondW32_ordom_once         := ordom_once condarms.
Theorem round_bounded_aff (fu : nat)
        (sg : list seg) (ps : atab) (cw : word) (f : N)
        (h jc : nat) (n : ncost) (m : nat)
        (sg2 : list seg) (ps2 : atab) (cw2 : word) (f2 : N)
        (h2 jc2 : nat) (n2 : ncost) (m2 : nat) (stop : lrstop) (Lm : N) :
  settled sg cw ->
  lin_run_round fu sg ps cw f h jc n m
    = (sg2, ps2, cw2, f2, h2, jc2, n2, m2, stop) ->
  (cmeas sg2 cw2 f2 + 2 * fst n2 <= Lm + ALLOW)%N ->
  (Lm <= TERM_UB + 7)%N ->
  Bounded (lin_flat sg cw) f Lm.
Proof.
  intros HSet HR HL HT.
  pose proof (CondW32_cond_round_dom fu sg ps cw f h jc n m HSet) as HD.
  rewrite HR in HD. unfold cd in HD.
  unfold Bounded.
  split; [|exact HT].
  change (gmeas (lin_flat sg cw) f) with (cmeas sg cw f).
  lia.
Qed.
Theorem chunk_budget_head (chunks : nat)
        (sgR : list seg) (psR : atab) (cwR : word) (fR : N)
        (hR jcR : nat) (nR : ncost) (mR : nat)
        (sg2 : list seg) (ps2 : atab) (cw2 : word) (f2 : N)
        (jc2 : nat) (n2 : ncost) (m2 : nat) (stop2 : lrstop) (Lm : N) :
  settled sgR cwR ->
  lin_run_round_chunked chunks sgR psR cwR fR hR jcR nR mR
    = (sg2, ps2, cw2, f2, jc2, n2, m2, stop2) ->
  (cmeas sg2 cw2 f2 + 2 * fst n2 <= Lm + ALLOW)%N ->
  (cmeas sgR cwR fR + 2 * fst nR <= Lm + ALLOW)%N.
Proof.
  intros HSet HR HL.
  pose proof (CondW32_cond_chunked_dom chunks sgR psR cwR fR hR jcR nR mR HSet) as HD.
  rewrite HR in HD. unfold cdc in HD. lia.
Qed.
Set Warnings "require-in-module".
Open Scope nat_scope.
Open Scope sym.
Open Scope list.
Opaque LROUND_FUEL LROUND_CHUNKS
       FLAT_ROUND_FUEL CFUEL TRIES.
Opaque front_late.
Definition cne (d : cost) : Prop := (fst d <= snd d)%N.
Lemma cne_czero : cne czero.
Proof. unfold cne, czero; cbn [fst snd]; lia. Qed.
Lemma cne_cx (K : N) : cne (cx K).
Proof. unfold cne, cx; cbn [fst snd]; lia. Qed.
Lemma closing_false_flat_none (sg : list seg)
      (cw : word) (f : N) :
  stable_guard sg cw ->
  lin_guard sg cw = true ->
  lin_round_closing cw f = false ->
  fr_clean (lin_flat sg cw) f = None /\
  fr_four (lin_flat sg cw) f = None.
Proof.
  intros HG HGuard HC.
  destruct HG as ((HOk & HPT) & HEdges & HW & HShape & HK & HP).
  assert (HM : ph_margins sg cw)
    by exact (lguard_margins sg cw HGuard).
  unfold lin_round_closing in HC.
  destruct (fr_clean cw f) as [r1|] eqn:E1; [discriminate HC|].
  destruct (fr_four cw f) as [r2|] eqn:E2; [discriminate HC|].
  split.
  - rewrite (fr_clean_flat_tag sg cw f HW HM), E1.
    reflexivity.
  - rewrite (fr_four_flat_tag sg cw f HW HM), E2.
    reflexivity.
Qed.
Theorem micro_act_reachable_act0
    (fr : option res) (sg : list seg) (cw : word)
    (f : N) (h : nat) (cw2 : word) (f2 : N) (i : nat) (Lm : N) :
  stable_guard sg cw ->
  lin_guard sg cw = true ->
  fr = front_gate cw f ->
  lin_round_closing cw f = false ->
  step_after_front_with_guard false (lin_normalize_at sg)
    (fun pre sfx _ => lin_normalize_join sg pre sfx) fr cw f h
    = (ROk cw2 f2, i) ->
  ~ (fr = None /\
     find_active cw (if Nat.ltb h 1 then 1%nat else h) = None) ->
  (gmeas (lin_flat sg cw) f <= Lm + ALLOW)%N /\
  (Lm <= TERM_UB + 7)%N ->
  creach (0%N, ACT_UB)
    (wconf [] 0 (sdecode (lin_flat sg cw) f))
    (wconf [] 0 (sdecode (lin_flat sg cw2) f2)).
Proof.
  intros HG HGuard Efr HClose HRun HNoFall [HM HT]. subst fr.
  destruct (closing_false_flat_none sg cw f HG HGuard HClose) as (HC & HF).
  destruct (micro_act_of_flat (0%N, ACT_UB)
              sg cw f h cw2 f2 i HG HGuard HRun
              (fun hf W2 i2 HStep =>
                 flat_act_reachable_act0
                   (lin_flat sg cw) f hf W2 f2 i2 Lm
                   HStep HC HF HM HT))
    as [HR|HFall].
  - exact HR.
  - exfalso. apply HNoFall. exact HFall.
Qed.
Theorem micro_act_reachable_close0
    (fr : option res) (sg : list seg) (cw : word)
    (f : N) (h : nat) (cw2 : word) (f2 : N) (i : nat) (Lm : N) :
  stable_guard sg cw ->
  lin_guard sg cw = true ->
  fr = front_gate cw f ->
  step_after_front_with_guard false (lin_normalize_at sg)
    (fun pre sfx _ => lin_normalize_join sg pre sfx) fr cw f h
    = (ROk cw2 f2, i) ->
  ~ (fr = None /\
     find_active cw (if Nat.ltb h 1 then 1%nat else h) = None) ->
  (gmeas (lin_flat sg cw) f <= Lm + ALLOW)%N /\
  (Lm <= TERM_UB + 7)%N ->
  creach (0%N, CoarseC_CLOSE_UB)
    (wconf [] 0 (sdecode (lin_flat sg cw) f))
    (wconf [] 0 (sdecode (lin_flat sg cw2) f2)).
Proof.
  intros HG HGuard Efr HRun HNoFall [HM HT]. subst fr.
  destruct (micro_act_of_flat (0%N, CoarseC_CLOSE_UB)
              sg cw f h cw2 f2 i HG HGuard HRun
              (fun hf W2 i2 HStep =>
                 flat_act_reachable0
                   (lin_flat sg cw) f hf W2 f2 i2 Lm
                   HStep HM HT))
    as [HR|HFall].
  - exact HR.
  - exfalso. apply HNoFall. exact HFall.
Qed.
Lemma cundef_not_cne : ~ cne cundef.
Proof. unfold cne, cundef; cbn [fst snd]; lia. Qed.
Lemma cadd_czero_r (a : cost) : cadd a czero = a.
Proof.
  destruct a as [x y]; unfold cadd, czero; cbn [fst snd].
  f_equal; lia.
Qed.
Lemma LineageCount_cadd_czero_l (a : cost) : cadd czero a = a.
Proof.
  destruct a as [x y]; unfold cadd, czero; cbn [fst snd].
  f_equal; lia.
Qed.
Lemma LineageCount_cadd_assoc (a b c : cost) :
  cadd (cadd a b) c = cadd a (cadd b c).
Proof. destruct a, b, c; unfold cadd; cbn [fst snd]; f_equal; lia. Qed.
Lemma cne_cadd (a b : cost) : cne a -> cne b -> cne (cadd a b).
Proof. destruct a, b; unfold cne, cadd; cbn [fst snd]; lia. Qed.
Lemma cadds_cundef_l (b : cost) :
  cadds cundef b = cundef.
Proof. reflexivity. Qed.
Lemma cadds_cundef_r (a : cost) :
  cadds a cundef = cundef.
Proof.
  unfold cadds.
  destruct (N.ltb (chi a) (clo a)); reflexivity.
Qed.
Lemma cadds_ne (a b : cost) :
  cne (cadds a b) ->
  cne a /\ cne b /\ cadds a b = cadd a b.
Proof.
  intros H. unfold cadds in *.
  destruct (orb (N.ltb (chi a) (clo a))
                (N.ltb (chi b) (clo b))) eqn:E.
  - exfalso. exact (cundef_not_cne H).
  - apply Bool.orb_false_iff in E. destruct E as [E1 E2].
    apply N.ltb_ge in E1. apply N.ltb_ge in E2.
    unfold clo, chi, cne in *.
    repeat split; assumption.
Qed.
Definition dstep (n n2 : ncost) (d : cost) : Prop :=
  cne (ncl n2) ->
    cne (ncl n) /\ cne d /\
    ncl n2 = cadd (ncl n) d.
Lemma cne_widen (a : cost) (x : N) :
  cne a -> cne (cadds a (0%N, x)).
Proof.
  intros Ha. rewrite (cadds_exact a (0%N, x) Ha).
  - unfold cne, cadd, clo, chi in *; cbn [fst snd]; lia.
  - unfold clo, chi; cbn [fst snd]; lia.
Qed.
Lemma dstep_refl (n : ncost) : dstep n n czero.
Proof.
  unfold dstep. intros H. split; [exact H|]. split; [exact cne_czero|].
  rewrite cadd_czero_r. reflexivity.
Qed.
Lemma dstep_bump (n : ncost) (q : N) (dc de : cost) :
  dstep n (nc_bump n q dc de) dc.
Proof.
  unfold dstep, nc_bump, ncl, ncs, ncq,
    ncf, ncfw, nce;
    cbn [fst snd].
  intros H.
  destruct (cadds_ne _ _ H) as (H1 & H2 & H3).
  destruct (cadds_ne _ _ H1) as (HS & Hdc & HE).
  split; [exact (cne_widen _ _ HS)|]. split; [exact Hdc|].
  rewrite H3, HE.
  rewrite (cadds_exact (fst (fst (snd n))) (0%N, _) HS)
    by (unfold clo, chi; cbn [fst snd]; lia).
  unfold cadd, clo, chi in *; cbn [fst snd] in *.
  f_equal; ring.
Qed.
Lemma dstep_rbump (n : ncost) (q : N) :
  dstep n (nc_rbump n q) (0%N, (q * ACT_UB)%N).
Proof.
  unfold dstep, nc_rbump, ncl, ncs, ncq,
    ncf, ncfw, nce;
    cbn [fst snd].
  intros H.
  destruct (cadds_ne _ _ H) as (HS & H2 & H3).
  split; [exact (cne_widen _ _ HS)|].
  split; [unfold cne, clo, chi; cbn [fst snd]; lia|].
  rewrite H3.
  rewrite (cadds_exact (fst (fst (snd n))) (0%N, _) HS)
    by (unfold clo, chi; cbn [fst snd]; lia).
  unfold cadd, clo, chi in *; cbn [fst snd] in *.
  f_equal; ring.
Qed.
Lemma dstep_qbump (n : ncost) (q : N) (de : cost) :
  dstep n (nc_qbump n q de) (0%N, ACT_UB).
Proof.
  unfold dstep, nc_qbump, ncl, ncs, ncq,
    ncf, ncfw, nce;
    cbn [fst snd].
  intros H.
  destruct (cadds_ne _ _ H) as (HS & H2 & H3).
  split; [exact (cne_widen _ _ HS)|].
  split; [unfold cne, clo, chi; cbn [fst snd]; lia|].
  rewrite H3.
  rewrite (cadds_exact (fst (fst (snd n))) (0%N, _) HS)
    by (unfold clo, chi; cbn [fst snd]; lia).
  unfold cadd, clo, chi in *; cbn [fst snd] in *.
  f_equal; ring.
Qed.
Lemma dstep_ebump (n : ncost) (q : N) :
  dstep n (nc_ebump n q) (0%N, EARLY_UB).
Proof.
  unfold dstep, nc_ebump, ncl, ncs,
    ncq, ncf, ncfw, nce,
    EARLY_UB;
    cbn [fst snd].
  intros H.
  destruct (cadds_ne _ _ H) as (HS & H2 & H3).
  split; [exact (cne_widen _ _ HS)|].
  split; [unfold cne, clo, chi; cbn [fst snd]; lia|].
  rewrite H3.
  rewrite (cadds_exact (fst (fst (snd n))) (0%N, _) HS)
    by (unfold clo, chi; cbn [fst snd]; lia).
  unfold cadd, clo, chi in *; cbn [fst snd] in *.
  f_equal; ring.
Qed.
Lemma dstep_sbump (n : ncost) (q M : N) :
  dstep n (nc_sbump n q M) (0%N, spanq q M).
Proof.
  unfold nc_sbump. exact (dstep_bump n q _ _).
Qed.
Lemma dstep_fbump (n : ncost) (q : N) :
  dstep n (nc_fbump n q) (0%N, flight_ub q).
Proof.
  unfold dstep, nc_fbump, ncl, ncs, ncq,
    ncf, ncfw, nce, flight_ub;
    destruct (q <=? FLIGHT_QMAX)%N eqn:Eq;
    cbn [fst snd].
  all: intros H;
    destruct (cadds_ne _ _ H) as (HS & H2 & H3);
    split; [exact (cne_widen _ _ HS)|];
    split; [unfold cne, clo, chi; cbn [fst snd]; lia|];
    rewrite H3;
    rewrite (cadds_exact (fst (fst (snd n))) (0%N, _) HS)
      by (unfold clo, chi; cbn [fst snd]; lia);
    unfold cadd, clo, chi in *; cbn [fst snd] in *;
    f_equal; ring.
Qed.
Lemma dstep_add (n k : ncost) :
  dstep n (nc_add n k) (ncl k).
Proof.
  unfold dstep, nc_add, ncl, ncs, ncq,
    ncf, ncfw, nce;
    cbn [fst snd].
  intros H.
  destruct (cadds_ne _ _ H) as (H1 & H2 & H3).
  destruct (cadds_ne _ _ H1) as (HN & HK & HE).
  split; [exact (cne_widen _ _ HN)|]. split; [exact (cne_widen _ _ HK)|].
  rewrite H3, HE.
  rewrite (cadds_exact (fst (fst (snd n))) (0%N, _) HN)
    by (unfold clo, chi; cbn [fst snd]; lia).
  rewrite (cadds_exact (fst (fst (snd k))) (0%N, _) HK)
    by (unfold clo, chi; cbn [fst snd]; lia).
  unfold cadd, clo, chi in *; cbn [fst snd] in *.
  f_equal; ring.
Qed.
Lemma dstep_comp (n n1 n2 : ncost) (d1 d2 : cost) :
  dstep n n1 d1 -> dstep n1 n2 d2 -> dstep n n2 (cadds d1 d2).
Proof.
  unfold dstep. intros H1 H2 H.
  destruct (H2 H) as (Hn1 & Hd2 & He2).
  destruct (H1 Hn1) as (Hn & Hd1 & He1).
  assert (Ed : cadds d1 d2 = cadd d1 d2).
  { apply cadds_exact; unfold cne, clo, chi in *; lia. }
  rewrite Ed. split; [exact Hn|]. split; [exact (cne_cadd _ _ Hd1 Hd2)|].
  rewrite He2, He1, LineageCount_cadd_assoc. reflexivity.
Qed.
Lemma dstep_nc0 (k : ncost) (d : cost) :
  dstep nc0 k d -> cne (ncl k) -> ncl k = d.
Proof.
  intros H Hne. destruct (H Hne) as (_ & _ & He).
  rewrite He. change (ncl nc0) with czero.
  apply LineageCount_cadd_czero_l.
Qed.
Definition conf (w : word) (f : N) : Q * tape :=
  wconf [] 0 (sdecode w f).
Definition lp_conf (s : lpstate) : Q * tape :=
  let '(w, f, _) := lp_sem s in conf w f.
Lemma sound_of_span (w : word) (f : N) (h : nat) (t : N)
      (w2 : word) (f2 : N) (h2 : nat) (d : cost) (Lm : N) :
  lin_zsp w f h = Some (t, (w2, f2, h2), d) ->
  (gmeas w2 f2 + 2 * t <= Lm + ALLOW)%N ->
  (Lm <= TERM_UB + 7)%N ->
  creach (0%N, (t * ACT_UB)%N) (conf w f) (conf w2 f2).
Proof.
  intros HZ HB HT.
  pose proof (lin_zsp_proj _ _ _ _ _ _ HZ) as HS.
  unfold conf, sconf.
  replace ACT_UB with GrowC_ACT_UB by reflexivity.
  exact (zjump3_reachable_act
           w f h t (w2,f2,h2) Lm HS HB HT).
Qed.
Lemma closing_act_exact (w : word) (f : N) (h : nat)
      (w2 : word) (f2 : N) (i : nat) :
  step w f h = (ROk w2 f2, i) ->
  cne (snd (cstep w f h)) ->
  creach (snd (cstep w f h)) (conf w f) (conf w2 f2).
Proof.
  intros HS Hne.
  destruct (cstep w f h) as [[r i0] d] eqn:EC.
  pose proof (cstep_res _ _ _ _ _ _ EC) as HR.
  rewrite HS in HR. injection HR as HR1 HR2. subst r.
  cbn [snd] in Hne |- *.
  destruct (StepSoundC_holds w f h w2 f2 i0 d EC)
    as [Hemp|Hok].
  - exfalso. unfold cempty, cne, clo, chi in *. lia.
  - unfold conf. exact Hok.
Qed.
Lemma flat_nonclosing_none (w : word) (f : N) :
  lin_round_closing w f = false ->
  fr_clean w f = None /\ fr_four w f = None.
Proof.
  unfold lin_round_closing.
  destruct (fr_clean w f); [discriminate|].
  destruct (fr_four w f); [discriminate|].
  intros _. split; reflexivity.
Qed.
Lemma flight_slot_creach (fr : option res) (sg : list seg)
      (ps : atab) (cw : word) (f : N) (h : nat) (t : N)
      (cw2 : word) (sg2 : list seg) (ps2 : atab)
      (f2 : N) (fs : nat) (Lm : N) :
  stable_guard sg cw ->
  lin_gen_action_at fr sg ps cw f h
    = Some (Some (t, cw2, sg2, ps2, f2, fs)) ->
  Bounded (lin_flat sg cw) f Lm ->
  Bounded (lin_flat sg2 cw2) f2 Lm ->
  creach (0%N, flight_ub t)
    (conf (lin_flat sg cw) f) (conf (lin_flat sg2 cw2) f2).
Proof.
  intros HG HRun [HM0 HT] [HM1 _]. unfold conf.
  replace (flight_ub t) with (CoarseC_flight_ub t)
    by (unfold flight_ub, FLIGHT_QMAX,
               CoarseC_flight_ub, RET; reflexivity).
  apply (gen_action_reachable0_general
           fr sg ps cw f h t cw2 sg2 ps2 f2 fs HG HRun);
    unfold BMAX; lia.
Qed.
Lemma tick_front_slot_creach (fr : option res) (sg : list seg)
      (ps : atab) (cw : word) (f : N) (h : nat) (q : N)
      (cw2 : word) (sg2 : list seg) (ps2 : atab)
      (f2 : N) (fs : nat) (Lm : N) :
  stable_guard sg cw ->
  lin_tick_front_at fr sg ps cw f h
    = Some (q, cw2, sg2, ps2, f2, fs) ->
  Bounded (lin_flat sg cw) f Lm ->
  Bounded (lin_flat sg2 cw2) f2 Lm ->
  creach (0%N, flight_ub q)
    (conf (lin_flat sg cw) f) (conf (lin_flat sg2 cw2) f2).
Proof.
  intros HG HRun [HM0 HT] [HM1 _]. unfold conf.
  replace (flight_ub q) with (CoarseC_flight_ub q)
    by (unfold flight_ub, FLIGHT_QMAX,
               CoarseC_flight_ub, RET; reflexivity).
  apply (tick_front_action_reachable0_general
           fr sg ps cw f h q cw2 sg2 ps2 f2 fs HG HRun);
    unfold BMAX; lia.
Qed.
Definition rbud (sg2 : list seg) (cw2 : word) (f2 : N)
                (n2 : ncost) (Lm : N) : Prop :=
  (cmeas sg2 cw2 f2 + 2 * fst n2 <= Lm + ALLOW)%N
  /\ (Lm <= TERM_UB + 7)%N.
Definition round_outc (sg : list seg) (cw : word) (f : N)
    (sg2 : list seg) (cw2 : word) (f2 : N)
    (stop : lrstop) (d : cost) : Prop :=
  match stop with
  | LRHalt =>
      cne d -> exists k, cin k d /\
        halts_in tmB (conf (lin_flat sg cw) f) k
  | _ =>
      cne d -> creach d (conf (lin_flat sg cw) f)
                             (conf (lin_flat sg2 cw2) f2)
  end.
Lemma round_outc_undef sg cw f sg2 cw2 f2 stop :
  round_outc sg cw f sg2 cw2 f2 stop cundef.
Proof.
  unfold round_outc. destruct stop; intros H; exfalso;
    exact (cundef_not_cne H).
Qed.
Lemma round_outc_pre sg cw f sg1 cw1 f1 sg2 cw2 f2 stop d1 d2 :
  (cne d1 -> creach d1 (conf (lin_flat sg cw) f)
                            (conf (lin_flat sg1 cw1) f1)) ->
  round_outc sg1 cw1 f1 sg2 cw2 f2 stop d2 ->
  round_outc sg cw f sg2 cw2 f2 stop (cadds d1 d2).
Proof.
  intros H1 H2. unfold round_outc in *. destruct stop.
  - intros H. destruct (cadds_ne _ _ H) as (Hd1 & Hd2 & Hed).
    rewrite Hed. exact (creach_trans _ _ _ _ _ (H1 Hd1) (H2 Hd2)).
  - intros H. destruct (cadds_ne _ _ H) as (Hd1 & Hd2 & Hed).
    rewrite Hed. exact (creach_trans _ _ _ _ _ (H1 Hd1) (H2 Hd2)).
  - intros H. destruct (cadds_ne _ _ H) as (Hd1 & Hd2 & Hed).
    rewrite Hed. exact (creach_trans _ _ _ _ _ (H1 Hd1) (H2 Hd2)).
  - intros H. destruct (cadds_ne _ _ H) as (Hd1 & Hd2 & Hed).
    rewrite Hed.
    destruct (H2 Hd2) as (k2 & Hk2 & Hh2).
    destruct (creach_halts_in _ _ _ _ (H1 Hd1) Hh2)
      as (k1 & Hk1 & Hh1).
    exists (k1 + k2)%nat.
    split; [exact (cin_add _ _ _ _ Hk1 Hk2)|exact Hh1].
Qed.
Lemma halt_confirm_in (sg : list seg) (cw : word) (f : N) :
  fst (lin_halt_confirm sg cw f) = true ->
  exists k, cin k (snd (lin_halt_confirm sg cw f))
            /\ halts_in tmB (conf (lin_flat sg cw) f) k.
Proof.
  unfold lin_halt_confirm, conf.
  destruct (cstep (lin_flat sg cw) f O)
    as [[r i] d] eqn:ES.
  destruct r as [w2 f2| |]; cbn [fst snd]; intros HT; try discriminate.
  exact (StepGuardC_holds _ _ _ _ _ ES).
Qed.
Lemma run_round_outc :
  forall fu sg ps cw f h jc n m sg2 ps2 cw2 f2 h2 jc2 n2 m2 stop,
    settled sg cw ->
    lin_run_round fu sg ps cw f h jc n m =
      (sg2, ps2, cw2, f2, h2, jc2, n2, m2, stop) ->
    exists d, dstep n n2 d /\
      (forall Lm, rbud sg2 cw2 f2 n2 Lm ->
                  round_outc sg cw f sg2 cw2 f2 stop d).
Proof.
  induction fu as [|fu IH];
    intros sg ps cw f h jc n m sg2 ps2 cw2 f2 h2 jc2 n2 m2 stop
      HSet Hrun;
    assert (HBD : forall Lm, rbud sg2 cw2 f2 n2 Lm ->
                    Bounded (lin_flat sg cw) f Lm)
      by (intros Lm0 HB0; destruct HB0 as [HB1 HB2];
          exact (round_bounded_aff _ sg ps cw f h jc n m
                   sg2 ps2 cw2 f2 h2 jc2 n2 m2 stop Lm0 HSet Hrun HB1 HB2));
    destruct HSet as [HG HGuard];
    cbn [lin_run_round] in Hrun;
    cbv beta zeta iota in Hrun.
  - inversion Hrun; subst sg2 ps2 cw2 f2 h2 jc2 n2 m2 stop.
    exists czero. split; [exact (dstep_refl n)|].
    intros Lm HB. unfold round_outc. intros _. exact (creach_refl _).
  - lazymatch type of Hrun with
    | context [lin_gen_action_at ?F] => set (fr := F) in Hrun
    end.
    destruct (lin_front_close cw f) as [[[qF cwF] fF]|] eqn:EFC.
    + destruct (relocate_all sg ps cwF) as [psF|] eqn:ERel.
      *
        lazymatch type of Hrun with
        | context [if ?late then _ else _] => destruct late eqn:ELate
        end;
          cbv beta zeta iota in Hrun.
        -- inversion Hrun; subst sg2 ps2 cw2 f2 h2 jc2 n2 m2 stop.
           exists (dfci cw f). split.
           ++ exact (dstep_bump n (N.of_nat qF) _ _).
           ++ intros Lm HB. unfold round_outc. intros _.
              exact (lin_front_close_creach_i
                       sg cw f qF cwF fF EFC).
        -- inversion Hrun; subst sg2 ps2 cw2 f2 h2 jc2 n2 m2 stop.
           exists (0%N, EARLY_UB). split.
           ++ exact (dstep_ebump n (N.of_nat qF)).
           ++ intros Lm HB. unfold round_outc. intros _.
              exact (front_close_reachable_early
                       sg cw f qF cwF fF EFC ELate).
      * inversion Hrun; subst sg2 ps2 cw2 f2 h2 jc2 n2 m2 stop.
        exists czero. split; [exact (dstep_refl n)|].
        intros Lm HB. unfold round_outc. intros _. exact (creach_refl _).
    + destruct (lin_gen_action_at fr sg ps cw f h) as [og|] eqn:EGen.
      * destruct og as [[[[[[tG cwG] sgG] psG] fG] fsG]|].
        --
           destruct (lin_gen_action_at_stable
                       fr sg ps cw f h tG cwG sgG psG fG fsG HG EGen)
             as (_ & HGg & HGuardg & _).
           destruct (IH _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _
                       (conj HGg HGuardg) Hrun)
             as (d & Hd & Hr).
           assert (HBDG : forall Lm,
                     rbud sg2 cw2 f2 n2 Lm ->
                     Bounded (lin_flat sgG cwG) fG Lm).
           { intros Lm0 HB0. destruct HB0 as [HB1 HB2].
             eapply round_bounded_aff;
               [exact (conj HGg HGuardg)|exact Hrun|exact HB1|exact HB2]. }
           exists (cadds (0%N, flight_ub tG) d). split.
           ++ exact (dstep_comp _ _ _ _ _
                       (dstep_fbump n tG) Hd).
           ++ intros Lm HB.
              exact (round_outc_pre _ _ _ _ _ _ _ _ _ _ _ _
                       (fun _ => flight_slot_creach
                                   fr sg ps cw f h tG cwG sgG psG fG fsG
                                   Lm HG EGen (HBD Lm HB) (HBDG Lm HB))
                       (Hr Lm HB)).
        -- destruct (lin_halt_probe fr sg cw f h) eqn:EP.
           ++ destruct (fst (lin_halt_confirm sg cw f)) eqn:ECf.
              ** inversion Hrun; subst sg2 ps2 cw2 f2 h2 jc2 n2 m2 stop.
                 exists (snd (lin_halt_confirm sg cw f)). split.
                 --- exact (dstep_bump n 0%N _ _).
                 --- intros Lm HB. unfold round_outc. intros _.
                     exact (halt_confirm_in sg cw f ECf).
              ** inversion Hrun; subst sg2 ps2 cw2 f2 h2 jc2 n2 m2 stop.
                 exists czero. split; [exact (dstep_refl n)|].
                 intros Lm HB. unfold round_outc. intros _. exact (creach_refl _).
           ++ inversion Hrun; subst sg2 ps2 cw2 f2 h2 jc2 n2 m2 stop.
              exists czero. split; [exact (dstep_refl n)|].
              intros Lm HB. unfold round_outc. intros _. exact (creach_refl _).
      * destruct (if lin_tick_front_due cw
                  then lin_tick_front_at fr sg ps cw f h
                  else None)
          as [[[[[[qT cwT] sgT] psT] fT] fsT]|] eqn:ETF.
        --
           assert (ETF' : lin_tick_front_at fr sg ps cw f h
                          = Some (qT, cwT, sgT, psT, fT, fsT)).
           { destruct (lin_tick_front_due cw);
               [exact ETF|discriminate ETF]. }
           destruct (lin_tick_front_at_stable
                       fr sg ps cw f h qT cwT sgT psT fT fsT HG ETF')
             as (_ & HGt & HGuardt & _).
           destruct (IH _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _
                       (conj HGt HGuardt) Hrun)
             as (d & Hd & Hr).
           assert (HBDT : forall Lm,
                     rbud sg2 cw2 f2 n2 Lm ->
                     Bounded (lin_flat sgT cwT) fT Lm).
           { intros Lm0 HB0. destruct HB0 as [HB1 HB2].
             eapply round_bounded_aff;
               [exact (conj HGt HGuardt)|exact Hrun|exact HB1|exact HB2]. }
           exists (cadds (0%N, flight_ub qT) d). split.
           ++ exact (dstep_comp _ _ _ _ _
                       (dstep_fbump n qT) Hd).
           ++ intros Lm HB.
              exact (round_outc_pre _ _ _ _ _ _ _ _ _ _ _ _
                       (fun _ => tick_front_slot_creach
                                   fr sg ps cw f h qT cwT sgT psT fT fsT
                                   Lm HG ETF' (HBD Lm HB) (HBDT Lm HB))
                       (Hr Lm HB)).
        -- destruct (lin_micro_action_guard fr cw h) eqn:EMicro.
           2:{ inversion Hrun; subst sg2 ps2 cw2 f2 h2 jc2 n2 m2 stop.
               exists czero. split; [exact (dstep_refl n)|].
               intros Lm HB. unfold round_outc. intros _.
               exact (creach_refl _). }
           assert (HNoFall :
             ~ (fr = None /\
                find_active cw
                  (if Nat.ltb h 1 then 1%nat else h) = None))
             by exact (lin_micro_action_guard_sound fr cw h EMicro).
           destruct (step_after_front_with_guard false
              (lin_normalize_at sg)
              (fun pre sfx _ => lin_normalize_join sg pre sfx)
              fr cw f h) as [[wS fS| |] iS] eqn:ESP.
           ++ destruct (lin_splice_arm_guard fr cw iS) eqn:EGA.
              ** destruct (relocate_all sg ps wS)
                   as [psS|] eqn:EPS.
                 --- destruct (lin_round_closing cw f) eqn:ECl.
                     +++
                         pose proof (HBD) as HBD0.
                         inversion Hrun;
                           subst sg2 ps2 cw2 f2 h2 jc2 n2 m2 stop.
                         exists (0%N, CLOSE_UB). split.
                         ---- exact (dstep_bump n 1%N _ _).
                         ---- intros Lm HB. unfold round_outc. intros _.
                              exact (micro_act_reachable_close0
                                fr sg cw f h wS fS iS Lm HG HGuard
                                eq_refl ESP HNoFall (HBD0 Lm HB)).
                     +++ destruct (lin_step_post fr sg psS wS iS)
                           as [[[[sgP psP] cwP] iP]|] eqn:EPost.
                         ***
                             destruct (splice_stable
                                         sg cw f h wS fS iS HG HGuard ESP)
                               as (_ & HGs).
                             destruct (lin_step_post_settled
                                         fr sg psS wS iS sgP psP cwP iP
                                         HGs EPost)
                               as (HFlatP & HGuardP & HGp).
                             destruct (IH _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _
                                        (conj HGp HGuardP) Hrun)
                               as (d & Hd & Hr).
                             exists (cadds (0%N, ACT_UB) d).
                             split.
                             ---- exact (dstep_comp _ _ _ _ _
                                    (dstep_qbump n 1%N czero) Hd).
                             ---- intros Lm HB.
                                  refine (round_outc_pre _ _ _ _ _ _ _ _ _ _ _ _
                                    (fun _ => _)
                                    (Hr Lm HB));
                                  rewrite HFlatP;
                                  exact (micro_act_reachable_act0
                                    fr sg cw f h wS fS iS Lm HG HGuard
                                    eq_refl ECl ESP HNoFall (HBD Lm HB)).
                         *** inversion Hrun;
                               subst sg2 ps2 cw2 f2 h2 jc2 n2 m2 stop.
                             exists czero.
                             split; [exact (dstep_refl n)|].
                             intros Lm HB. unfold round_outc. intros _.
                             exact (creach_refl _).
                 --- inversion Hrun;
                       subst sg2 ps2 cw2 f2 h2 jc2 n2 m2 stop.
                     exists czero. split; [exact (dstep_refl n)|].
                     intros Lm HB. unfold round_outc. intros _. exact (creach_refl _).
              ** inversion Hrun; subst sg2 ps2 cw2 f2 h2 jc2 n2 m2 stop.
                 exists czero. split; [exact (dstep_refl n)|].
                 intros Lm HB. unfold round_outc. intros _. exact (creach_refl _).
           ++ destruct (fst (lin_halt_confirm sg cw f)) eqn:ECf.
              ** inversion Hrun; subst sg2 ps2 cw2 f2 h2 jc2 n2 m2 stop.
                 exists (snd (lin_halt_confirm sg cw f)). split.
                 --- exact (dstep_bump n 0%N _ _).
                 --- intros Lm HB. unfold round_outc. intros _.
                     exact (halt_confirm_in sg cw f ECf).
              ** inversion Hrun; subst sg2 ps2 cw2 f2 h2 jc2 n2 m2 stop.
                 exists czero. split; [exact (dstep_refl n)|].
                 intros Lm HB. unfold round_outc. intros _. exact (creach_refl _).
           ++ inversion Hrun; subst sg2 ps2 cw2 f2 h2 jc2 n2 m2 stop.
              exists czero. split; [exact (dstep_refl n)|].
              intros Lm HB. unfold round_outc. intros _. exact (creach_refl _).
Qed.
Lemma run_chunked_outc :
  forall chunks sg ps cw f h jc n m sg2 ps2 cw2 f2 jc2 n2 m2 stop,
    settled sg cw ->
    lin_run_round_chunked chunks sg ps cw f h jc n m =
      (sg2, ps2, cw2, f2, jc2, n2, m2, stop) ->
    exists d, dstep n n2 d /\
      (forall Lm, rbud sg2 cw2 f2 n2 Lm ->
                  round_outc sg cw f sg2 cw2 f2 stop d).
Proof.
  induction chunks as [|ch IH];
    intros sg ps cw f h jc n m sg2 ps2 cw2 f2 jc2 n2 m2 stop HSet Hrun;
    cbn [lin_run_round_chunked] in Hrun.
  - inversion Hrun; subst sg2 ps2 cw2 f2 jc2 n2 m2 stop.
    exists czero. split; [exact (dstep_refl n)|].
    intros Lm HB. unfold round_outc. intros _. exact (creach_refl _).
  - destruct (lin_run_round LROUND_FUEL sg ps cw f h jc n m)
      as [[[[[[[[sgR psR] cwR] fR] hR] jcR] nR] mR] stopR] eqn:ER.
    destruct (run_round_outc _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _
                HSet ER)
      as (d1 & Hd1 & Hr1).
    pose proof (run_round_out
                  _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ HSet ER) as HRO.
    destruct stopR.
    + cbn [round_out] in HRO.
      destruct HRO as [_ HSetR].
      destruct (IH _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ HSetR Hrun)
        as (d2 & Hd2 & Hr2).
      exists (cadds d1 d2). split.
      * exact (dstep_comp _ _ _ _ _ Hd1 Hd2).
      * intros Lm HB.
        assert (HB1 : rbud sgR cwR fR nR Lm).
        { destruct HB as [HB1 HB2]. split; [|exact HB2].
          exact (chunk_budget_head ch sgR psR cwR fR hR jcR nR mR
                   sg2 ps2 cw2 f2 jc2 n2 m2 stop Lm HSetR Hrun HB1). }
        exact (round_outc_pre _ _ _ _ _ _ _ _ _ _ _ _
                 (Hr1 Lm HB1) (Hr2 Lm HB)).
    + inversion Hrun; subst sg2 ps2 cw2 f2 jc2 n2 m2 stop.
      exists d1. split; assumption.
    + inversion Hrun; subst sg2 ps2 cw2 f2 jc2 n2 m2 stop.
      exists d1. split; assumption.
    + inversion Hrun; subst sg2 ps2 cw2 f2 jc2 n2 m2 stop.
      exists d1. split; assumption.
Qed.
Lemma fallback_run_next_c :
  forall fu T w f h k m k' m' s',
    lp_fallback_round_run fu T w f h k m = LPNext k' m' s' ->
    ctot_ok T w ->
    exists w' f' h' d,
      s' = LPFlat w' f' h' /\ dstep k k' d /\
      (forall Lm,
       (gmeas w' f' + 2 * fst k' <= Lm + ALLOW)%N ->
       (Lm <= TERM_UB + 7)%N ->
       cne d -> creach d (conf w f) (conf w' f')).
Proof.
  induction fu as [|fu IH];
    intros T w f h k m k' m' s' Hrun HT;
    cbn [lp_fallback_round_run] in Hrun; cbv beta zeta iota in Hrun.
  - inversion Hrun; subst k' m' s'.
    exists w, f, h, czero.
    split; [reflexivity|]. split; [exact (dstep_refl k)|].
    intros Lm HB HL _. exact (creach_refl _).
  - destruct (lin_zsp w f h) as [[[k2 [[w2 f2] h2]] dz]|] eqn:EZ.
    + destruct (IH _ _ _ _ _ _ _ _ _ Hrun I)
        as (w' & f' & h' & d & -> & Hd & Hr).
      exists w', f', h',
        (cadds (0%N, (k2 * ACT_UB)%N) d).
      split; [reflexivity|]. split.
      * exact (dstep_comp _ _ _ _ _ (dstep_rbump k k2) Hd).
      * intros Lm HB HL H.
        destruct (cadds_ne _ _ H) as (H1 & H2 & He).
        assert (HB2 : (gmeas w2 f2 + 2 * k2
                         <= Lm + ALLOW)%N).
        { pose proof (lp_fbrr_dom fu None w2 f2 h2
                        (nc_rbump k k2) (S m)) as HDom.
          rewrite Hrun in HDom.
          cbn [dom_of phi_st lp_sem] in HDom.
          unfold phi, nc_rbump in HDom. cbn [fst] in HDom.
          lia. }
        rewrite He. exact (creach_trans _ _ _ _ _
          (sound_of_span w f h k2 w2 f2 h2 dz Lm EZ HB2 HL)
          (Hr Lm HB HL H2)).
    + destruct (step w f h) as [[wS fS| |] iS] eqn:ES.
      * destruct (lin_round_closing w f) eqn:ECl.
        --
           inversion Hrun; subst k' m' s'.
           exists wS, fS, (if Nat.ltb iS 5 then O else (iS - 4)%nat),
             (snd (cstep w f h)).
           split; [reflexivity|]. split;
             [exact (dstep_bump k 1%N _ _)|].
           intros Lm HB HL Hne. exact (closing_act_exact _ _ _ _ _ _ ES Hne).
        -- destruct (IH _ _ _ _ _ _ _ _ _ Hrun I)
             as (w' & f' & h' & d & -> & Hd & Hr).
           exists w', f', h',
             (cadds (0%N, ACT_UB) d).
           split; [reflexivity|]. split.
           ++ exact (dstep_comp _ _ _ _ _
                       (dstep_qbump k 1%N czero) Hd).
           ++ intros Lm HB HL H. destruct (cadds_ne _ _ H) as (H1 & H2 & He).
              assert (HBw : (gmeas w f <= Lm + ALLOW)%N).
              { pose proof (lp_fbrr_dom (S fu) T w f h k m) as HDom.
                rewrite (lp_fbrr_flat_step
                  fu T w f h k m wS fS iS EZ ES ECl) in HDom.
                rewrite Hrun in HDom.
                cbn [dom_of phi_st lp_sem] in HDom.
                unfold phi in HDom. lia. }
              destruct (flat_nonclosing_none w f ECl) as (HC & HF).
              rewrite He.
              exact (creach_trans _ _ _ _ _
                (flat_act_reachable_act0
                   w f h wS fS iS Lm ES HC HF HBw HL)
                (Hr Lm HB HL H2)).
      * discriminate.
      * discriminate.
Qed.
Lemma fallback_run_guard_c :
  forall fu T w f h k m k' m' w2 f2,
    lp_fallback_round_run fu T w f h k m
      = LPGuard k' m' w2 f2 ->
    ctot_ok T w ->
    exists d, dstep k k' d /\
      (forall Lm,
       (gmeas w2 f2 + 2 * fst k' <= Lm + ALLOW)%N ->
       (Lm <= TERM_UB + 7)%N ->
       cne d -> exists j, cin j d /\ halts_in tmB (conf w f) j).
Proof.
  induction fu as [|fu IH];
    intros T w f h k m k' m' w2 f2 Hrun HT;
    cbn [lp_fallback_round_run] in Hrun; cbv beta zeta iota in Hrun.
  - discriminate.
  - destruct (lin_zsp w f h) as [[[kz [[wz fz] hz]] dz]|] eqn:EZ.
    + destruct (IH _ _ _ _ _ _ _ _ _ _ Hrun I) as (d & Hd & Hr).
      exists (cadds (0%N, (kz * ACT_UB)%N) d). split.
      * exact (dstep_comp _ _ _ _ _ (dstep_rbump k kz) Hd).
      * intros Lm HB HL H. destruct (cadds_ne _ _ H) as (H1 & H2 & He).
        assert (HBz : (gmeas wz fz + 2 * kz
                        <= Lm + ALLOW)%N).
        { pose proof (lp_fbrr_dom fu None wz fz hz
                        (nc_rbump k kz) (S m)) as HDom.
          rewrite Hrun in HDom. cbn [dom_of] in HDom.
          unfold phi, nc_rbump in HDom. cbn [fst] in HDom.
          lia. }
        rewrite He. destruct (Hr Lm HB HL H2) as (j2 & Hj2 & Hh2).
        destruct (creach_halts_in _ _ _ _
                    (sound_of_span w f h kz wz fz hz dz Lm EZ HBz HL) Hh2)
          as (j1 & Hj1 & Hh1).
        exists (j1 + j2)%nat.
        split; [exact (cin_add _ _ _ _ Hj1 Hj2)|exact Hh1].
    + destruct (step w f h) as [[wS fS| |] iS] eqn:ES.
      *
        destruct (lin_round_closing w f) eqn:ECl.
        -- discriminate.
        -- destruct (IH _ _ _ _ _ _ _ _ _ _ Hrun I)
             as (d & Hd & Hr).
           exists (cadds (0%N, ACT_UB) d). split.
           ++ exact (dstep_comp _ _ _ _ _
                       (dstep_qbump k 1%N czero) Hd).
           ++ intros Lm HB HL H. destruct (cadds_ne _ _ H) as (H1 & H2 & He).
              assert (HBw : (gmeas w f <= Lm + ALLOW)%N).
              { pose proof (lp_fbrr_dom (S fu) T w f h k m) as HDom.
                rewrite (lp_fbrr_flat_step
                  fu T w f h k m wS fS iS EZ ES ECl) in HDom.
                rewrite Hrun in HDom. cbn [dom_of] in HDom.
                unfold phi in HDom. lia. }
              destruct (flat_nonclosing_none w f ECl) as (HC & HF).
              rewrite He. destruct (Hr Lm HB HL H2) as (j2 & Hj2 & Hh2).
              destruct (creach_halts_in _ _ _ _
                          (flat_act_reachable_act0
                             w f h wS fS iS Lm ES HC HF HBw HL) Hh2)
                as (j1 & Hj1 & Hh1).
              exists (j1 + j2)%nat.
              split; [exact (cin_add _ _ _ _ Hj1 Hj2)|exact Hh1].
      * destruct (cstep w f h) as [[rC iC] d0] eqn:EC.
        pose proof (cstep_res _ _ _ _ _ _ EC) as HR.
        rewrite ES in HR. injection HR as <- <-.
        inversion Hrun; subst k' m' w2 f2.
        exists d0. split; [exact (dstep_bump k 0%N d0 d0)|].
        intros Lm HB HL _. unfold conf.
        exact (StepGuardC_holds _ _ _ _ _ EC).
      * discriminate.
Qed.
Lemma lr_accept_k (closed : bool) sg ps cw f jc k m k' m' s' :
  lr_accept closed sg ps cw f jc k m = Some (LPNext k' m' s') ->
  k' = k.
Proof.
  unfold lr_accept. cbv beta zeta iota. intros H.
  destruct (Nat.eqb m O); [discriminate|].
  destruct (closed || Nat.eqb m LROUND_FUEL)%bool.
  - destruct (lin_repack_when_needed sg ps cw)
      as [[[sg3 ps3] cw3]|]; [|discriminate].
    destruct (negb (lin_ok sg3 cw3)); [discriminate|].
    destruct sg3; inversion H; reflexivity.
  - destruct (negb (lin_post_full sg cw)); [discriminate|].
    inversion H; reflexivity.
Qed.
Lemma lr_continue_c sg cw f jc k m r :
  lr_continue_flat sg cw f jc k m = Some r ->
  r = lp_fallback_round_run FLAT_ROUND_FUEL
        None (lin_flat sg cw) f
        (hint_of (fmapw sg cw O O jc)) k m.
Proof.
  unfold lr_continue_flat. cbv beta zeta iota. intros H.
  destruct (Nat.eqb m O); [discriminate|].
  destruct (negb (lin_post_full sg cw)); [discriminate|].
  injection H as H1. exact (eq_sym H1).
Qed.
Lemma continue_or_fallback_next_c
    sg2 cw2 f2 j2 k0 m0 wfb ffb hfb k m s' :
  (match lr_continue_flat sg2 cw2 f2 j2 k0 m0 with
   | Some r => lps_of_lpnext r
   | None => lps_of_lpnext (lp_fallback_round wfb ffb hfb)
   end) = LPSNext k m s' ->
  ((cmeas sg2 cw2 f2 + 2 * fst k0 <= lpm s' + 2 * fst k)%N /\
   exists d, dstep k0 k d /\
     (forall Lm,
      (lpm s' + 2 * fst k <= Lm + ALLOW)%N ->
      (Lm <= TERM_UB + 7)%N ->
      cne d -> creach d (conf (lin_flat sg2 cw2) f2)
                              (lp_conf s')))
  \/ (exists d, dstep nc0 k d /\
     (forall Lm,
      (lpm s' + 2 * fst k <= Lm + ALLOW)%N ->
      (Lm <= TERM_UB + 7)%N ->
      cne d -> creach d (conf wfb ffb) (lp_conf s'))).
Proof.
  intros H.
  destruct (lr_continue_flat sg2 cw2 f2 j2 k0 m0) as [r|] eqn:ECo.
  - pose proof (lr_continue_c _ _ _ _ _ _ _ ECo) as Er.
    destruct r as [k1 m1 s1|k1 m1 w1 f1|k1 m1 w1 f1];
      cbn [lps_of_lpnext] in H; try discriminate.
    inversion H; subst k1 m1 s1. clear H.
    pose proof (dom_of_next (lin_flat sg2 cw2) f2 k0 k m s'
                  (lr_continue_dom sg2 cw2 f2 j2 k0 m0 _ ECo)) as HDN.
    destruct (fallback_run_next_c _ _ _ _ _ _ _ _ _ _ (eq_sym Er) I)
      as (w' & f' & h' & d & -> & Hd & Hr).
    left. split; [exact HDN|]. exists d. split; [exact Hd|].
    cbn [lp_conf lp_sem lpm]. exact Hr.
  - unfold lp_fallback_round in H.
    destruct (lp_fallback_round_run FLAT_ROUND_FUEL
                None wfb ffb hfb nc0 O)
      as [k1 m1 s1|k1 m1 w1 f1|k1 m1 w1 f1] eqn:EF;
      cbn [lps_of_lpnext] in H; try discriminate.
    inversion H; subst k1 m1 s1. clear H.
    destruct (fallback_run_next_c _ _ _ _ _ _ _ _ _ _ EF I)
      as (w' & f' & h' & d & -> & Hd & Hr).
    right. exists d. split; [exact Hd|].
    cbn [lp_conf lp_sem lpm]. exact Hr.
Qed.
Lemma continue_or_fallback_guard_c
    sg2 cw2 f2 j2 k0 m0 wfb ffb hfb k m len fg lm :
  (match lr_continue_flat sg2 cw2 f2 j2 k0 m0 with
   | Some r => lps_of_lpnext r
   | None => lps_of_lpnext (lp_fallback_round wfb ffb hfb)
   end) = LPSGuard k m len fg lm ->
  ((cmeas sg2 cw2 f2 + 2 * fst k0 <= lm + 2 * fst k)%N /\
   exists d, dstep k0 k d /\
     (forall Lm,
      (lm + 2 * fst k <= Lm + ALLOW)%N ->
      (Lm <= TERM_UB + 7)%N ->
      cne d -> exists j, cin j d /\
        halts_in tmB (conf (lin_flat sg2 cw2) f2) j))
  \/ (exists d, dstep nc0 k d /\
     (forall Lm,
      (lm + 2 * fst k <= Lm + ALLOW)%N ->
      (Lm <= TERM_UB + 7)%N ->
      cne d -> exists j, cin j d /\ halts_in tmB (conf wfb ffb) j)).
Proof.
  intros H.
  destruct (lr_continue_flat sg2 cw2 f2 j2 k0 m0) as [r|] eqn:ECo.
  - pose proof (lr_continue_c _ _ _ _ _ _ _ ECo) as Er.
    pose proof (lr_continue_dom sg2 cw2 f2 j2 k0 m0 _ ECo) as HDG.
    destruct r as [k1 m1 s1|k1 m1 w1 f1|k1 m1 w1 f1];
      cbn [lps_of_lpnext] in H; try discriminate.
    inversion H; subst; clear H.
    left. split.
    + exact (dom_of_guard _ _ _ _ _ _ _ HDG).
    + exact (fallback_run_guard_c _ _ _ _ _ _ _ _ _ _ _ (eq_sym Er) I).
  - unfold lp_fallback_round in H.
    destruct (lp_fallback_round_run FLAT_ROUND_FUEL
                None wfb ffb hfb nc0 O)
      as [k1 m1 s1|k1 m1 w1 f1|k1 m1 w1 f1] eqn:EF;
      cbn [lps_of_lpnext] in H; try discriminate.
    inversion H; subst k1 m1 fg lm. clear H.
    change (gmeas w1 f1) with (lmeas w1 f1).
    right. exact (fallback_run_guard_c _ _ _ _ _ _ _ _ _ _ _ EF I).
Qed.
Lemma accept_or_fallback_next_c
    sg2 ps2 cw2 f2 j2 k0 m0 wfb ffb hfb k m s' :
  stable_guard sg2 cw2 ->
  (match lr_accept true sg2 ps2 cw2 f2 j2 k0 m0 with
   | Some r => lps_of_lpnext r
   | None => lps_of_lpnext (lp_fallback_round wfb ffb hfb)
   end) = LPSNext k m s' ->
  (k = k0 /\ lp_conf s' = conf (lin_flat sg2 cw2) f2
     /\ lpm s' = cmeas sg2 cw2 f2)
  \/ (exists d, dstep nc0 k d /\
     (forall Lm,
      (lpm s' + 2 * fst k <= Lm + ALLOW)%N ->
      (Lm <= TERM_UB + 7)%N ->
      cne d -> creach d (conf wfb ffb) (lp_conf s'))).
Proof.
  intros HG H.
  destruct (lr_accept true sg2 ps2 cw2 f2 j2 k0 m0) as [r|] eqn:EAcc.
  - pose proof (lr_accept_exact true sg2 ps2 cw2 f2 j2 k0 m0 _
                  HG EAcc) as HEX.
    destruct (lr_accept_next_stable
                _ _ _ _ _ _ _ _ HG EAcc)
      as (k1 & m1 & s1 & Er & HStable & h' & Hsem).
    subst r. cbn [lps_of_lpnext] in H.
    destruct HEX as [sA [HrA HmA]].
    injection HrA as HrA1 HrA2 HrA3. subst sA.
    inversion H; subst k1 m1 s1. clear H.
    left. split; [|split].
    + congruence.
    + unfold lp_conf. rewrite Hsem. reflexivity.
    + exact HmA.
  - unfold lp_fallback_round in H.
    destruct (lp_fallback_round_run FLAT_ROUND_FUEL
                None wfb ffb hfb nc0 O)
      as [k1 m1 s1|k1 m1 w1 f1|k1 m1 w1 f1] eqn:EF;
      cbn [lps_of_lpnext] in H; try discriminate.
    inversion H; subst k1 m1 s1. clear H.
    destruct (fallback_run_next_c _ _ _ _ _ _ _ _ _ _ EF I)
      as (w' & f' & h' & d & -> & Hd & Hr).
    right. exists d. split; [exact Hd|].
    cbn [lp_conf lp_sem lpm]. exact Hr.
Qed.
Lemma accept_or_fallback_guard_c
    sg2 ps2 cw2 f2 j2 k0 m0 wfb ffb hfb k m len fg lm :
  stable_guard sg2 cw2 ->
  (match lr_accept true sg2 ps2 cw2 f2 j2 k0 m0 with
   | Some r => lps_of_lpnext r
   | None => lps_of_lpnext (lp_fallback_round wfb ffb hfb)
   end) = LPSGuard k m len fg lm ->
  exists d, dstep nc0 k d /\
    (forall Lm,
     (lm + 2 * fst k <= Lm + ALLOW)%N ->
     (Lm <= TERM_UB + 7)%N ->
     cne d -> exists j, cin j d /\ halts_in tmB (conf wfb ffb) j).
Proof.
  intros HG H.
  destruct (lr_accept true sg2 ps2 cw2 f2 j2 k0 m0) as [r|] eqn:EAcc.
  - destruct (lr_accept_next_stable
                _ _ _ _ _ _ _ _ HG EAcc)
      as (k1 & m1 & s1 & Er & HStable & h' & Hsem).
    subst r. cbn [lps_of_lpnext] in H. discriminate.
  - unfold lp_fallback_round in H.
    destruct (lp_fallback_round_run FLAT_ROUND_FUEL
                None wfb ffb hfb nc0 O)
      as [k1 m1 s1|k1 m1 w1 f1|k1 m1 w1 f1] eqn:EF;
      cbn [lps_of_lpnext] in H; try discriminate.
    inversion H; subst k1 m1 fg lm. clear H.
    change (gmeas w1 f1) with (lmeas w1 f1).
    exact (fallback_run_guard_c _ _ _ _ _ _ _ _ _ _ _ EF I).
Qed.
Lemma rbud_of_next (sgR : list seg) (cwR : word) (fR : N)
      (nR k : ncost) (s' : lpstate) (Lm : N) :
  (cmeas sgR cwR fR + 2 * fst nR <= lpm s' + 2 * fst k)%N ->
  (lpm s' + 2 * fst k <= Lm + ALLOW)%N ->
  (Lm <= TERM_UB + 7)%N ->
  rbud sgR cwR fR nR Lm.
Proof. intros H1 H2 H3. unfold rbud. split; [lia|exact H3]. Qed.
Lemma rbud_of_guard (sgR : list seg) (cwR : word) (fR : N)
      (nR k : ncost) (lm : N) :
  (cmeas sgR cwR fR + 2 * fst nR <= lm + 2 * fst k)%N ->
  (2 * fst k <= ALLOW)%N ->
  (lm <= TERM_UB + 7)%N ->
  rbud sgR cwR fR nR lm.
Proof. intros H1 H2 H3. unfold rbud. split; [lia|exact H3]. Qed.
Theorem linstep_next_c :
  forall s k m s' Lm,
    lp_stable s ->
    linstep s = LPSNext k m s' ->
    (lpm s' + 2 * fst k <= Lm + ALLOW)%N ->
    (Lm <= TERM_UB + 7)%N ->
    cne (ncl k) ->
    creach (ncl k) (lp_conf s) (lp_conf s').
Proof.
  intros s k m s' Lm HStable Hstep HBu HT Hne.
  destruct s as [w f h|sg ps cw f h j].
  - cbn [lp_conf lp_sem].
    unfold linstep in Hstep.
    destruct (lin_cond w h) as [[[cw0 sg0] h0]|] eqn:ECo.
    2:{ unfold lp_fallback_round in Hstep.
        destruct (lp_fallback_round_run FLAT_ROUND_FUEL
                    None w f h nc0 O)
          as [k1 m1 s1|k1 m1 w1 f1|k1 m1 w1 f1] eqn:EF;
          cbn [lps_of_lpnext] in Hstep; try discriminate.
        inversion Hstep; subst k1 m1 s1. clear Hstep.
        destruct (fallback_run_next_c _ _ _ _ _ _ _ _ _ _ EF I)
          as (w' & f' & h' & d & -> & Hd & Hr).
        rewrite (dstep_nc0 _ _ Hd Hne).
        cbn [lp_conf lp_sem].
        apply (Hr Lm HBu HT).
        rewrite <- (dstep_nc0 _ _ Hd Hne). exact Hne. }
    destruct (locate_all sg0 cw0) as [ps0|] eqn:EL.
    2:{ unfold lp_fallback_round in Hstep.
        destruct (lp_fallback_round_run FLAT_ROUND_FUEL
                    None w f h nc0 O)
          as [k1 m1 s1|k1 m1 w1 f1|k1 m1 w1 f1] eqn:EF;
          cbn [lps_of_lpnext] in Hstep; try discriminate.
        inversion Hstep; subst k1 m1 s1. clear Hstep.
        destruct (fallback_run_next_c _ _ _ _ _ _ _ _ _ _ EF I)
          as (w' & f' & h' & d & -> & Hd & Hr).
        rewrite (dstep_nc0 _ _ Hd Hne).
        cbn [lp_conf lp_sem].
        apply (Hr Lm HBu HT).
        rewrite <- (dstep_nc0 _ _ Hd Hne). exact Hne. }
    destruct (T_cond_stable_holds w h cw0 sg0 h0 ECo)
      as [HFlat HG0].
    destruct (T_cond_holds w h cw0 sg0 h0 ECo)
      as (_ & _ & HGuard0 & _ & _).
    destruct (lin_run_round_chunked LROUND_CHUNKS
        sg0 ps0 cw0 f h0 O nc0 O)
      as [[[[[[[sgR psR] cwR] fR] jR] nR] mR] stopR] eqn:ER.
    destruct (run_chunked_outc _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _
                (conj HG0 HGuard0) ER)
      as (d1 & Hd1 & Hr1).
    destruct stopR.
    + destruct (continue_or_fallback_next_c
          sgR cwR fR jR nR mR w f h k m s' Hstep) as [HD|HD].
      * destruct HD as (HDN & d2 & Hd2 & Hr2).
        pose proof (dstep_comp _ _ _ _ _ Hd1 Hd2) as Hdc.
        rewrite (dstep_nc0 _ _ Hdc Hne).
        assert (Hnec : cne (cadds d1 d2))
          by (rewrite <- (dstep_nc0 _ _ Hdc Hne); exact Hne).
        destruct (cadds_ne _ _ Hnec) as (He1 & He2 & Hed).
        rewrite Hed, <- HFlat.
        exact (creach_trans _ _ _ _ _
                 (Hr1 Lm (rbud_of_next _ _ _ _ _ _ _ HDN HBu HT) He1)
                 (Hr2 Lm HBu HT He2)).
      * destruct HD as (d2 & Hd2 & Hr2).
        rewrite (dstep_nc0 _ _ Hd2 Hne).
        apply (Hr2 Lm HBu HT).
        rewrite <- (dstep_nc0 _ _ Hd2 Hne). exact Hne.
    + destruct (continue_or_fallback_next_c
          sgR cwR fR jR nR mR w f h k m s' Hstep) as [HD|HD].
      * destruct HD as (HDN & d2 & Hd2 & Hr2).
        pose proof (dstep_comp _ _ _ _ _ Hd1 Hd2) as Hdc.
        rewrite (dstep_nc0 _ _ Hdc Hne).
        assert (Hnec : cne (cadds d1 d2))
          by (rewrite <- (dstep_nc0 _ _ Hdc Hne); exact Hne).
        destruct (cadds_ne _ _ Hnec) as (He1 & He2 & Hed).
        rewrite Hed, <- HFlat.
        exact (creach_trans _ _ _ _ _
                 (Hr1 Lm (rbud_of_next _ _ _ _ _ _ _ HDN HBu HT) He1)
                 (Hr2 Lm HBu HT He2)).
      * destruct HD as (d2 & Hd2 & Hr2).
        rewrite (dstep_nc0 _ _ Hd2 Hne).
        apply (Hr2 Lm HBu HT).
        rewrite <- (dstep_nc0 _ _ Hd2 Hne). exact Hne.
    + destruct (run_chunked_out
                  _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _
                  (conj HG0 HGuard0) ER) as [_ HG2].
      destruct (accept_or_fallback_next_c
          sgR psR cwR fR jR nR mR w f h k m s' HG2 Hstep) as [HD|HD].
      * destruct HD as (-> & Hsem & Hlpm).
        assert (HBUD : rbud sgR cwR fR nR Lm)
          by (unfold rbud; split; [rewrite Hlpm in HBu; lia|exact HT]).
        rewrite (dstep_nc0 _ _ Hd1 Hne), Hsem, <- HFlat.
        apply (Hr1 Lm HBUD).
        rewrite <- (dstep_nc0 _ _ Hd1 Hne). exact Hne.
      * destruct HD as (d2 & Hd2 & Hr2).
        rewrite (dstep_nc0 _ _ Hd2 Hne).
        apply (Hr2 Lm HBu HT).
        rewrite <- (dstep_nc0 _ _ Hd2 Hne). exact Hne.
    + discriminate.
  - cbn [lp_stable] in HStable.
    cbn [lp_conf lp_sem].
    unfold linstep in Hstep.
    destruct (lin_run_round_chunked LROUND_CHUNKS
        sg ps cw f h (hmapw sg cw O O j) nc0 O)
      as [[[[[[[sgR psR] cwR] fR] jR] nR] mR] stopR] eqn:ER.
    destruct (run_chunked_outc _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _
                HStable ER)
      as (d1 & Hd1 & Hr1).
    destruct stopR.
    + destruct (continue_or_fallback_next_c
          sgR cwR fR jR nR mR (lin_flat sg cw) f
          (hint_of j) k m s' Hstep) as [HD|HD].
      * destruct HD as (HDN & d2 & Hd2 & Hr2).
        pose proof (dstep_comp _ _ _ _ _ Hd1 Hd2) as Hdc.
        rewrite (dstep_nc0 _ _ Hdc Hne).
        assert (Hnec : cne (cadds d1 d2))
          by (rewrite <- (dstep_nc0 _ _ Hdc Hne); exact Hne).
        destruct (cadds_ne _ _ Hnec) as (He1 & He2 & Hed).
        rewrite Hed.
        exact (creach_trans _ _ _ _ _
                 (Hr1 Lm (rbud_of_next _ _ _ _ _ _ _ HDN HBu HT) He1)
                 (Hr2 Lm HBu HT He2)).
      * destruct HD as (d2 & Hd2 & Hr2).
        rewrite (dstep_nc0 _ _ Hd2 Hne).
        apply (Hr2 Lm HBu HT).
        rewrite <- (dstep_nc0 _ _ Hd2 Hne). exact Hne.
    + destruct (continue_or_fallback_next_c
          sgR cwR fR jR nR mR (lin_flat sg cw) f
          (hint_of j) k m s' Hstep) as [HD|HD].
      * destruct HD as (HDN & d2 & Hd2 & Hr2).
        pose proof (dstep_comp _ _ _ _ _ Hd1 Hd2) as Hdc.
        rewrite (dstep_nc0 _ _ Hdc Hne).
        assert (Hnec : cne (cadds d1 d2))
          by (rewrite <- (dstep_nc0 _ _ Hdc Hne); exact Hne).
        destruct (cadds_ne _ _ Hnec) as (He1 & He2 & Hed).
        rewrite Hed.
        exact (creach_trans _ _ _ _ _
                 (Hr1 Lm (rbud_of_next _ _ _ _ _ _ _ HDN HBu HT) He1)
                 (Hr2 Lm HBu HT He2)).
      * destruct HD as (d2 & Hd2 & Hr2).
        rewrite (dstep_nc0 _ _ Hd2 Hne).
        apply (Hr2 Lm HBu HT).
        rewrite <- (dstep_nc0 _ _ Hd2 Hne). exact Hne.
    + destruct (run_chunked_out
                  _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ HStable ER) as [_ HG2].
      destruct (accept_or_fallback_next_c
          sgR psR cwR fR jR nR mR (lin_flat sg cw) f
          (hint_of j) k m s' HG2 Hstep) as [HD|HD].
      * destruct HD as (-> & Hsem & Hlpm).
        assert (HBUD : rbud sgR cwR fR nR Lm)
          by (unfold rbud; split; [rewrite Hlpm in HBu; lia|exact HT]).
        rewrite (dstep_nc0 _ _ Hd1 Hne), Hsem.
        apply (Hr1 Lm HBUD).
        rewrite <- (dstep_nc0 _ _ Hd1 Hne). exact Hne.
      * destruct HD as (d2 & Hd2 & Hr2).
        rewrite (dstep_nc0 _ _ Hd2 Hne).
        apply (Hr2 Lm HBu HT).
        rewrite <- (dstep_nc0 _ _ Hd2 Hne). exact Hne.
    + discriminate.
Qed.
Theorem linstep_guard_c :
  forall s k m len fg lm,
    lp_stable s ->
    linstep s = LPSGuard k m len fg lm ->
    (2 * fst k <= ALLOW)%N ->
    (lm <= TERM_UB + 7)%N ->
    cne (ncl k) ->
    exists j, cin j (ncl k) /\ halts_in tmB (lp_conf s) j.
Proof.
  intros s k m len fg lm HStable Hstep HK HT Hne.
  destruct s as [w f h|sg ps cw f h j].
  - cbn [lp_conf lp_sem].
    unfold linstep in Hstep.
    destruct (lin_cond w h) as [[[cw0 sg0] h0]|] eqn:ECo.
    2:{ unfold lp_fallback_round in Hstep.
        destruct (lp_fallback_round_run FLAT_ROUND_FUEL
                    None w f h nc0 O)
          as [k1 m1 s1|k1 m1 w1 f1|k1 m1 w1 f1] eqn:EF;
          cbn [lps_of_lpnext] in Hstep; try discriminate.
        inversion Hstep; subst k1 m1. clear Hstep.
        destruct (fallback_run_guard_c _ _ _ _ _ _ _ _ _ _ _ EF I)
          as (d & Hd & Hr).
        rewrite (dstep_nc0 _ _ Hd Hne).
        apply (Hr lm ltac:(unfold gmeas, lmeas in *; lia) HT).
        rewrite <- (dstep_nc0 _ _ Hd Hne). exact Hne. }
    destruct (locate_all sg0 cw0) as [ps0|] eqn:EL.
    2:{ unfold lp_fallback_round in Hstep.
        destruct (lp_fallback_round_run FLAT_ROUND_FUEL
                    None w f h nc0 O)
          as [k1 m1 s1|k1 m1 w1 f1|k1 m1 w1 f1] eqn:EF;
          cbn [lps_of_lpnext] in Hstep; try discriminate.
        inversion Hstep; subst k1 m1. clear Hstep.
        destruct (fallback_run_guard_c _ _ _ _ _ _ _ _ _ _ _ EF I)
          as (d & Hd & Hr).
        rewrite (dstep_nc0 _ _ Hd Hne).
        apply (Hr lm ltac:(unfold gmeas, lmeas in *; lia) HT).
        rewrite <- (dstep_nc0 _ _ Hd Hne). exact Hne. }
    destruct (T_cond_stable_holds w h cw0 sg0 h0 ECo)
      as [HFlat HG0].
    destruct (T_cond_holds w h cw0 sg0 h0 ECo)
      as (_ & _ & HGuard0 & _ & _).
    destruct (lin_run_round_chunked LROUND_CHUNKS
        sg0 ps0 cw0 f h0 O nc0 O)
      as [[[[[[[sgR psR] cwR] fR] jR] nR] mR] stopR] eqn:ER.
    destruct (run_chunked_outc _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _
                (conj HG0 HGuard0) ER)
      as (d1 & Hd1 & Hr1).
    destruct stopR.
    + destruct (continue_or_fallback_guard_c
          sgR cwR fR jR nR mR w f h k m len fg lm Hstep) as [HD|HD].
      * destruct HD as (HDG & d2 & Hd2 & Hr2).
        pose proof (dstep_comp _ _ _ _ _ Hd1 Hd2) as Hdc.
        rewrite (dstep_nc0 _ _ Hdc Hne).
        assert (Hnec : cne (cadds d1 d2))
          by (rewrite <- (dstep_nc0 _ _ Hdc Hne); exact Hne).
        destruct (cadds_ne _ _ Hnec) as (He1 & He2 & Hed).
        rewrite Hed, <- HFlat.
        destruct (Hr2 lm ltac:(lia) HT He2) as (k2 & Hk2 & Hh2).
        destruct (creach_halts_in _ _ _ _
                    (Hr1 lm (rbud_of_guard _ _ _ _ _ _ HDG HK HT) He1) Hh2)
          as (k1' & Hk1 & Hh1).
        exists (k1' + k2)%nat.
        split; [exact (cin_add _ _ _ _ Hk1 Hk2)|exact Hh1].
      * destruct HD as (d2 & Hd2 & Hr2).
        rewrite (dstep_nc0 _ _ Hd2 Hne).
        apply (Hr2 lm ltac:(lia) HT).
        rewrite <- (dstep_nc0 _ _ Hd2 Hne). exact Hne.
    + destruct (continue_or_fallback_guard_c
          sgR cwR fR jR nR mR w f h k m len fg lm Hstep) as [HD|HD].
      * destruct HD as (HDG & d2 & Hd2 & Hr2).
        pose proof (dstep_comp _ _ _ _ _ Hd1 Hd2) as Hdc.
        rewrite (dstep_nc0 _ _ Hdc Hne).
        assert (Hnec : cne (cadds d1 d2))
          by (rewrite <- (dstep_nc0 _ _ Hdc Hne); exact Hne).
        destruct (cadds_ne _ _ Hnec) as (He1 & He2 & Hed).
        rewrite Hed, <- HFlat.
        destruct (Hr2 lm ltac:(lia) HT He2) as (k2 & Hk2 & Hh2).
        destruct (creach_halts_in _ _ _ _
                    (Hr1 lm (rbud_of_guard _ _ _ _ _ _ HDG HK HT) He1) Hh2)
          as (k1' & Hk1 & Hh1).
        exists (k1' + k2)%nat.
        split; [exact (cin_add _ _ _ _ Hk1 Hk2)|exact Hh1].
      * destruct HD as (d2 & Hd2 & Hr2).
        rewrite (dstep_nc0 _ _ Hd2 Hne).
        apply (Hr2 lm ltac:(lia) HT).
        rewrite <- (dstep_nc0 _ _ Hd2 Hne). exact Hne.
    + destruct (run_chunked_out
                  _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _
                  (conj HG0 HGuard0) ER) as [_ HG2].
      destruct (accept_or_fallback_guard_c
          sgR psR cwR fR jR nR mR w f h k m len fg lm HG2 Hstep)
        as (d2 & Hd2 & Hr2).
      rewrite (dstep_nc0 _ _ Hd2 Hne).
      apply (Hr2 lm ltac:(lia) HT).
      rewrite <- (dstep_nc0 _ _ Hd2 Hne). exact Hne.
    +
      inversion Hstep; subst k m len fg lm.
      assert (HBUD : rbud sgR cwR fR nR
                       (lmeas (lin_flat sgR cwR) fR)).
      { unfold rbud. split; [|exact HT].
        unfold cmeas, gmeas, lmeas. lia. }
      rewrite (dstep_nc0 _ _ Hd1 Hne), <- HFlat.
      apply (Hr1 _ HBUD).
      rewrite <- (dstep_nc0 _ _ Hd1 Hne). exact Hne.
  - cbn [lp_stable] in HStable.
    cbn [lp_conf lp_sem].
    unfold linstep in Hstep.
    destruct (lin_run_round_chunked LROUND_CHUNKS
        sg ps cw f h (hmapw sg cw O O j) nc0 O)
      as [[[[[[[sgR psR] cwR] fR] jR] nR] mR] stopR] eqn:ER.
    destruct (run_chunked_outc _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _
                HStable ER)
      as (d1 & Hd1 & Hr1).
    destruct stopR.
    + destruct (continue_or_fallback_guard_c
          sgR cwR fR jR nR mR (lin_flat sg cw) f
          (hint_of j) k m len fg lm Hstep) as [HD|HD].
      * destruct HD as (HDG & d2 & Hd2 & Hr2).
        pose proof (dstep_comp _ _ _ _ _ Hd1 Hd2) as Hdc.
        rewrite (dstep_nc0 _ _ Hdc Hne).
        assert (Hnec : cne (cadds d1 d2))
          by (rewrite <- (dstep_nc0 _ _ Hdc Hne); exact Hne).
        destruct (cadds_ne _ _ Hnec) as (He1 & He2 & Hed).
        rewrite Hed.
        destruct (Hr2 lm ltac:(lia) HT He2) as (k2 & Hk2 & Hh2).
        destruct (creach_halts_in _ _ _ _
                    (Hr1 lm (rbud_of_guard _ _ _ _ _ _ HDG HK HT) He1) Hh2)
          as (k1' & Hk1 & Hh1).
        exists (k1' + k2)%nat.
        split; [exact (cin_add _ _ _ _ Hk1 Hk2)|exact Hh1].
      * destruct HD as (d2 & Hd2 & Hr2).
        rewrite (dstep_nc0 _ _ Hd2 Hne).
        apply (Hr2 lm ltac:(lia) HT).
        rewrite <- (dstep_nc0 _ _ Hd2 Hne). exact Hne.
    + destruct (continue_or_fallback_guard_c
          sgR cwR fR jR nR mR (lin_flat sg cw) f
          (hint_of j) k m len fg lm Hstep) as [HD|HD].
      * destruct HD as (HDG & d2 & Hd2 & Hr2).
        pose proof (dstep_comp _ _ _ _ _ Hd1 Hd2) as Hdc.
        rewrite (dstep_nc0 _ _ Hdc Hne).
        assert (Hnec : cne (cadds d1 d2))
          by (rewrite <- (dstep_nc0 _ _ Hdc Hne); exact Hne).
        destruct (cadds_ne _ _ Hnec) as (He1 & He2 & Hed).
        rewrite Hed.
        destruct (Hr2 lm ltac:(lia) HT He2) as (k2 & Hk2 & Hh2).
        destruct (creach_halts_in _ _ _ _
                    (Hr1 lm (rbud_of_guard _ _ _ _ _ _ HDG HK HT) He1) Hh2)
          as (k1' & Hk1 & Hh1).
        exists (k1' + k2)%nat.
        split; [exact (cin_add _ _ _ _ Hk1 Hk2)|exact Hh1].
      * destruct HD as (d2 & Hd2 & Hr2).
        rewrite (dstep_nc0 _ _ Hd2 Hne).
        apply (Hr2 lm ltac:(lia) HT).
        rewrite <- (dstep_nc0 _ _ Hd2 Hne). exact Hne.
    + destruct (run_chunked_out
                  _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ HStable ER) as [_ HG2].
      destruct (accept_or_fallback_guard_c
          sgR psR cwR fR jR nR mR (lin_flat sg cw) f
          (hint_of j) k m len fg lm HG2 Hstep)
        as (d2 & Hd2 & Hr2).
      rewrite (dstep_nc0 _ _ Hd2 Hne).
      apply (Hr2 lm ltac:(lia) HT).
      rewrite <- (dstep_nc0 _ _ Hd2 Hne). exact Hne.
    +
      inversion Hstep; subst k m len fg lm.
      assert (HBUD : rbud sgR cwR fR nR
                       (lmeas (lin_flat sgR cwR) fR)).
      { unfold rbud. split; [|exact HT].
        unfold cmeas, gmeas, lmeas. lia. }
      rewrite (dstep_nc0 _ _ Hd1 Hne).
      apply (Hr1 _ HBUD).
      rewrite <- (dstep_nc0 _ _ Hd1 Hne). exact Hne.
Qed.
Record LineageSoundC : Prop := {
  linstep_next_okc :
    forall s k m s' Lm,
      lp_stable s ->
      linstep s = LPSNext k m s' ->
      (lpm s' + 2 * fst k <= Lm + ALLOW)%N ->
      (Lm <= TERM_UB + 7)%N ->
      cne (ncl k) ->
      creach (ncl k) (lp_conf s) (lp_conf s');
  linstep_guard_okc :
    forall s k m len f lm,
      lp_stable s ->
      linstep s = LPSGuard k m len f lm ->
      (2 * fst k <= ALLOW)%N ->
      (lm <= TERM_UB + 7)%N ->
      cne (ncl k) ->
      exists j, cin j (ncl k) /\ halts_in tmB (lp_conf s) j
}.
Theorem LineageSoundC_holds : LineageSoundC.
Proof.
  constructor.
  - exact linstep_next_c.
  - exact linstep_guard_c.
Qed.
Definition acc_ok (Lm : N) (u : Q * tape) (n : ncost)
                  (a : lpsacc) : Prop :=
  match a with
  | LPSRunning s' n' =>
      lp_stable s' /\
      ((lpm s' + 2 * fst n' <= Lm + ALLOW)%N ->
       cne (ncl n') ->
         cne (ncl n) /\
         exists d, cne d /\ ncl n' = cadd (ncl n) d
                   /\ creach d u (lp_conf s'))
  | LPSFinished (LSGuard _ _ n' lm) =>
      lm = Lm ->
      (2 * fst n' <= ALLOW)%N ->
      cne (ncl n') ->
        cne (ncl n) /\
        exists d, cne d /\ ncl n' = cadd (ncl n) d
                  /\ exists j, cin j d /\ halts_in tmB u j
  | _ => True
  end.
Lemma acc_ok_start (Lm : N) (s : lpstate) (n : ncost) :
  lp_stable s ->
  acc_ok Lm (lp_conf s) n (LPSRunning s n).
Proof.
  intros HS. cbn [acc_ok]. split; [exact HS|].
  intros _ H. split; [exact H|].
  exists czero. split; [exact cne_czero|].
  split; [rewrite cadd_czero_r; reflexivity|].
  exact (creach_refl _).
Qed.
Lemma acc_ok_comp (Lm : N) (u : Q * tape) (n : ncost)
      (s1 : lpstate) (n1 : ncost) (a : lpsacc) :
  ordom (LPSRunning s1 n1) a ->
  acc_ok Lm u n (LPSRunning s1 n1) ->
  acc_ok Lm (lp_conf s1) n1 a ->
  acc_ok Lm u n a.
Proof.
  intros HO H1 H2. cbn [acc_ok] in H1. destruct H1 as [HS1 H1].
  destruct HO as [_ HOd].
  destruct a as [s2 n2|r];
    [|destruct r as [len f n2 lm|len f n2 lm|len f n2 lm]].
  - cbn [acc_ok] in *. destruct H2 as [HS2 H2].
    split; [exact HS2|]. intros HB H.
    assert (HB1 : (lpm s1 + 2 * fst n1 <= Lm + ALLOW)%N)
      by (cbn beta iota in HOd; lia).
    destruct (H2 HB H) as (Hn1 & d2 & Hd2 & He2 & Hr2).
    destruct (H1 HB1 Hn1) as (Hn & d1 & Hd1 & He1 & Hr1).
    split; [exact Hn|].
    exists (cadd d1 d2). split; [exact (cne_cadd _ _ Hd1 Hd2)|].
    split; [rewrite He2, He1, LineageCount_cadd_assoc; reflexivity|].
    exact (creach_trans _ _ _ _ _ Hr1 Hr2).
  - cbn [acc_ok] in *. intros HL HN H.
    cbn beta iota delta [sdom] in HOd.
    assert (HB1 : (lpm s1 + 2 * fst n1 <= Lm + ALLOW)%N)
      by (subst lm; lia).
    destruct (H2 HL HN H) as (Hn1 & d2 & Hd2 & He2 & j & Hj & Hh).
    destruct (H1 HB1 Hn1) as (Hn & d1 & Hd1 & He1 & Hr1).
    split; [exact Hn|].
    exists (cadd d1 d2). split; [exact (cne_cadd _ _ Hd1 Hd2)|].
    split; [rewrite He2, He1, LineageCount_cadd_assoc; reflexivity|].
    destruct (creach_halts_in _ _ _ _ Hr1 Hh) as (k1 & Hk1 & Hh1).
    exists (k1 + j)%nat.
    split; [exact (cin_add _ _ _ _ Hk1 Hj)|exact Hh1].
  - exact I.
  - exact I.
Qed.
Lemma lps_once_ok (Lm : N) (s : lpstate) (n : ncost) :
  lp_stable s ->
  (Lm <= TERM_UB + 7)%N ->
  acc_ok Lm (lp_conf s) n (lps_once (LPSRunning s n)).
Proof.
  intros HS HT. cbn [lps_once].
  destruct (linstep s) as [k m s2|k m len f lm|k m len f lm] eqn:EL.
  - cbn [acc_ok]. split.
    + exact (proj1 (linstep_next_stable
                      s k m s2 HS EL)).
    + intros HB H.
      pose proof (dstep_add n k) as Hd.
      destruct (Hd H) as (Hn & Hk & He).
      split; [exact Hn|].
      exists (ncl k). split; [exact Hk|]. split; [exact He|].
      apply (linstep_next_c s k m s2 Lm HS EL); [|exact HT|exact Hk].
      unfold nc_add in HB; cbn [fst] in HB. lia.
  - cbn [acc_ok]. intros HE HN H.
    pose proof (dstep_add n k) as Hd.
    destruct (Hd H) as (Hn & Hk & He).
    split; [exact Hn|].
    exists (ncl k). split; [exact Hk|]. split; [exact He|].
    apply (linstep_guard_c s k m len f lm HS EL);
      [unfold nc_add in HN; cbn [fst] in HN; lia
      |subst lm; exact HT|exact Hk].
  - exact I.
Qed.
Lemma lps_step_ok (Lm : N) (u : Q * tape) (n : ncost)
      (a : lpsacc) :
  (Lm <= TERM_UB + 7)%N ->
  acc_ok Lm u n a -> acc_ok Lm u n (lps_once a).
Proof.
  destruct a as [s1 n1|r]; intros HT H.
  - cbn [acc_ok] in H. destruct H as [HS1 H1].
    exact (acc_ok_comp Lm u n s1 n1 _
             (CondW32_ordom_once (LPSRunning s1 n1) HS1)
             (conj HS1 H1)
             (lps_once_ok Lm s1 n1 HS1 HT)).
  - destruct r; exact H.
Qed.
Lemma lps_run_pos_ok (p : positive) :
  forall a u n Lm, (Lm <= TERM_UB + 7)%N ->
    acc_ok Lm u n a -> acc_ok Lm u n (lps_run_pos p a).
Proof.
  induction p as [p IH|p IH|]; intros a u n Lm HT H;
    cbn [lps_run_pos].
  - apply lps_step_ok; [exact HT|]. apply IH; [exact HT|].
    apply IH; [exact HT|exact H].
  - apply IH; [exact HT|]. apply IH; [exact HT|exact H].
  - apply lps_step_ok; [exact HT|exact H].
Qed.
Lemma lps_finish_guard_inv (a : lpsacc) len f n lm :
  lps_finish a = LSGuard len f n lm ->
  a = LPSFinished (LSGuard len f n lm).
Proof.
  destruct a as [s n0|r].
  - destruct s; discriminate.
  - cbn [lps_finish]. intros ->. reflexivity.
Qed.
Theorem lin_brun_halts_in :
  forall fuel w f h len f' n' lm,
    lin_brun fuel w f h nc0
      = LSGuard len f' n' lm ->
    (lm <= TERM_UB + 7)%N ->
    (2 * fst n' <= ALLOW)%N ->
    cne (ncl n') ->
    exists k, cin k (ncl n')
              /\ halts_in tmB (wconf [] 0 (sdecode w f)) k.
Proof.
  intros fuel w f h len f' n' lm Hrun HT HN Hne.
  unfold lin_brun, lin_brunN in Hrun.
  destruct (N.of_nat fuel) as [|p] eqn:Ef; [discriminate|].
  pose proof (lps_finish_guard_inv _ _ _ _ _ Hrun) as Ea.
  pose proof (lps_run_pos_ok p
                (LPSRunning (LPFlat w f h) nc0)
                (lp_conf (LPFlat w f h)) nc0 lm HT
                (acc_ok_start lm (LPFlat w f h) nc0 I))
    as HA.
  rewrite Ea in HA. cbn [acc_ok] in HA.
  destruct (HA eq_refl HN Hne) as (_ & d & Hd & He & j & Hj & Hh).
  change (ncl nc0) with czero in He.
  rewrite LineageCount_cadd_czero_l in He.
  exists j. split; [rewrite He; exact Hj|exact Hh].
Qed.
