Lemma B_bridge_creach :
  creach (cx 2%N) cB0 (wconf [] 0 [(1, 2%nat)]).
Proof.
  apply creach_cx. cbn [N.to_nat Pos.to_nat Pos.iter_op].
  change (wconf [] 0 [(1, 2%nat)])
    with (const 0 <{{D}} [1;1] *> const 0).
  exact cB_bridge.
Qed.
Lemma B_prologue_creach :
  creach (cx 29459944%N) cB0
    (wconf [] 0 (sdecode WB8 FB8)).
Proof.
  assert (E : cadd (cx 2%N) (cx B_anchor_cost)
              = cx 29459944%N) by reflexivity.
  rewrite <- E.
  exact (creach_trans _ _ _ _ _
           B_bridge_creach B_anchor_creach).
Qed.
Theorem B_halts_in_range_of :
  forall (NPIN : ncost) (LMPIN : N) (F : nat),
    lin_brun F WB8 FB8 O nc0
      = LSGuard 16124 4%N NPIN LMPIN ->
    (LMPIN <= TERM_UB + 7)%N ->
    (2 * fst NPIN <= ALLOW)%N ->
    cne (ncl NPIN) ->
    exists k,
      cin k (cadd (cx 29459944%N) (ncl NPIN))
      /\ halts_in tmB cB0 k.
Proof.
  intros NPIN LMPIN F Hpin HT HN Hne.
  destruct (lin_brun_halts_in F WB8 FB8 O
              16124 4%N NPIN LMPIN Hpin HT HN Hne) as (k & Hk & Hh).
  destruct (creach_halts_in _ _ _ _ B_prologue_creach Hh)
    as (j & Hj & Hh2).
  exists (j + k)%nat.
  split; [exact (cin_add _ _ _ _ Hj Hk)|exact Hh2].
Qed.
Theorem B_halts_in_range_num :
  forall (NPIN : ncost) (LMPIN : N) (F : nat),
    lin_brun F WB8 FB8 O nc0
      = LSGuard 16124 4%N NPIN LMPIN ->
    (LMPIN <= TERM_UB + 7)%N ->
    (2 * fst NPIN <= ALLOW)%N ->
    cne (ncl NPIN) ->
    exists k,
      (29459944 + clo (ncl NPIN) <= N.of_nat k
       <= 29459944 + chi (ncl NPIN))%N
      /\ halts_in tmB cB0 k.
Proof.
  intros NPIN LMPIN F Hpin HT HN Hne.
  destruct (B_halts_in_range_of NPIN LMPIN F Hpin HT HN Hne)
    as (k & Hk & Hh).
  exists k. split; [|exact Hh].
  unfold cin, cadd, cx, clo, chi in *.
  cbn [fst snd] in Hk. lia.
Qed.
Lemma B_range_at (LO HI : N) (NPIN : ncost) (LMPIN : N) (F : nat) :
  lin_brun F WB8 FB8 O nc0
    = LSGuard 16124 4%N NPIN LMPIN ->
  (LMPIN <= TERM_UB + 7)%N ->
  (2 * fst NPIN <= ALLOW)%N ->
  cne (ncl NPIN) ->
  (29459944 + clo (ncl NPIN))%N = LO ->
  (29459944 + chi (ncl NPIN))%N = HI ->
  exists k, (LO <= N.of_nat k <= HI)%N /\ halts_in tmB cB0 k.
Proof.
  intros Hpin HT HN Hne EL EH.
  destruct (B_halts_in_range_num NPIN LMPIN F Hpin HT HN Hne)
    as (k & Hk & Hh).
  exists k. rewrite <- EL, <- EH. split; [exact Hk|exact Hh].
Qed.
Definition B_LO : N :=
  29459944 + clo (ncl B_ncost).
Definition B_HI : N :=
  29459944 + chi (ncl B_ncost).
Definition LMPIN : N := B_terminal_measure.
Lemma B_terminal_value :
  lsm (lin_brun 16138 WB8 FB8 O
                 nc0)
  = LMPIN.
Proof. rewrite lin_orbit_pin. reflexivity. Qed.
Theorem B_terminal_pinned : TerminalUnder LMPIN.
Proof. vm_compute. reflexivity. Qed.
Theorem B_reported_terminal_under_TERM_UB :
  TerminalUnder
    (lsm (lin_brun 16138 WB8 FB8 O
                    nc0)).
Proof. rewrite B_terminal_value. exact B_terminal_pinned. Qed.
Example B_terminal_shape :
  (N.size LMPIN, (LMPIN mod 1000000000)%N, ((LMPIN - 8) mod 1000000000)%N)
  = (10676%N, 894835586%N, 894835578%N).
Proof. vm_compute. reflexivity. Qed.
Theorem B_halts_in_range :
  exists k, (B_LO <= N.of_nat k <= B_HI)%N /\ halts_in tmB cB0 k.
Proof.
  eapply B_halts_in_range_num.
  - exact lin_orbit_pin.
  - vm_compute. discriminate.
  - vm_compute. discriminate.
  - apply cne_widen.
    change (B_orbit_lo <= B_orbit_hi)%N.
    exact B_orbit_bounds_ordered.
Qed.
Corollary B_halt_steps_bounded (n : nat) :
  halts_in tmB cB0 n -> (B_LO <= N.of_nat n <= B_HI)%N.
Proof.
  intros H. destruct B_halts_in_range as (k & Hk & Hh).
  rewrite (halts_in_unique _ _ _ H Hh). exact Hk.
Qed.
Corollary B_halts : halts tmB cB0.
Proof. destruct B_halts_in_range as (k & _ & Hh). exists k. exact Hh. Qed.
