Open Scope string_scope.
Lemma perm_ok : Perm tmB (flip tm) smap.
Proof.
  split.
  - intros q s H; destruct q, s; cbn in *; try discriminate; reflexivity.
  - intros q s s' d q' H; destruct q, s; cbn in *;
      inversion H; subst; reflexivity.
Qed.
Lemma unflip_ok : Perm (flip (flip tm)) tm (fun q => q).
Proof.
  split.
  - intros q s H; destruct q, s; cbn in *; try discriminate; reflexivity.
  - intros q s s' d q' H; destruct q, s; cbn in *;
      inversion H; subst; reflexivity.
Qed.
Lemma tm_halts_in_iff n :
  halts_in tm c0 n <-> halts_in tmB cB0 n.
Proof.
  split; intros H.
  - pose proof (flip_halts_in tm c0 n H) as Hf.
    apply (perm_halts_in' _ _ _ B tape0 n perm_ok).
    exact Hf.
  - pose proof (perm_halts_in _ _ _ B tape0 n perm_ok H) as Hp.
    pose proof (flip_halts_in (flip tm) (A;; tape0) n Hp) as Hf.
    exact (perm_halts_in _ _ _ A tape0 n unflip_ok Hf).
Qed.

(* Main results *)

Definition halt_steps_lo : N := B_LO.
Definition halt_steps_hi : N := B_HI.
Theorem tm_halts_in_range :
  exists n, (halt_steps_lo <= N.of_nat n <= halt_steps_hi)%N /\
    halts_in tm c0 n.
Proof.
  destruct B_halts_in_range as (n & Hn & Hh).
  exists n. split; [exact Hn|].
  apply (proj2 (tm_halts_in_iff n)). exact Hh.
Qed.
Theorem tm_halt_steps_bounded n :
  halts_in tm c0 n ->
  (halt_steps_lo <= N.of_nat n <= halt_steps_hi)%N.
Proof.
  intros H. apply B_halt_steps_bounded.
  apply (proj1 (tm_halts_in_iff n)). exact H.
Qed.
Theorem tm_halts : halts tm c0.
Proof.
  destruct tm_halts_in_range as (n & _ & H).
  exists n. exact H.
Qed.
Theorem tm_halt_step_digits n :
  halts_in tm c0 n ->
  (10 ^ 6426 <= N.of_nat n < 10 ^ 6427)%N.
Proof.
  intros H. destruct (tm_halt_steps_bounded n H) as (Hl & Hh).
  split.
  - eapply N.le_trans; [|exact Hl].
    apply N.leb_le. vm_cast_no_check (@eq_refl bool true).
  - eapply N.le_lt_trans; [exact Hh|].
    apply N.ltb_lt. vm_cast_no_check (@eq_refl bool true).
Qed.

Print Assumptions tm_halts.
Print Assumptions tm_halt_step_digits.